// 4992 facts.
import type { ScienceFact } from './types.js';

export const SCIENCE_FACTS: ScienceFact[] = [
  {"id": "matter-definition-g3", "domain": "MATTER", "topic": "what is matter", "grades": [3, 4, 5], "terms": ["matter", "mass", "volume", "space", "nahahawakan", "sumasakop", "nagsakop", "mahikap", "espasyo", "anumang", "unsang", "bigat", "halos", "gibug"], "fact": {"tl": "Ang matter ay anumang bagay na may mass (bigat) at sumasakop ng espasyo. Halos lahat ng nakikita o nahahawakan mo — bato, tubig, hangin — ay matter.", "en": "Matter is anything that has mass and takes up space. Almost everything you see or touch — rock, water, air — is matter.", "bis": "Ang matter mao ang bisan unsang butang nga adunay mass (gibug-aton) ug nagsakop og espasyo. Halos tanan nga imong makita o mahikap — bato, tubig, hangin — kay matter."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "matter-properties-g3", "domain": "MATTER", "topic": "properties of materials", "grades": [3, 4, 5], "terms": ["properties", "color", "hardness", "texture", "float", "sink", "nakikilala", "pagbukud", "bukurin", "mailhan", "tigas", "katig", "molunod", "materyales", "lumulubog", "bigat"], "fact": {"tl": "Nakikilala ang iba't ibang materyales sa pamamagitan ng kanilang properties tulad ng kulay, tigas, texture, bigat, at kung lumulutang o lumulubog sa tubig. Ginagamit ang mga properties na ito para pagbukud-bukurin (i-classify) ang mga bagay.", "en": "Materials are recognized by their properties such as color, hardness, texture, weight, and whether they float or sink. These properties are used to sort and classify objects.", "bis": "Mailhan ang nagkalainlaing materyales pinaagi sa ilang properties sama sa kolor, katig-a, texture, gibug-aton, ug kung molutaw o molunod ba sa tubig. Gigamit kini nga mga properties aron i-classify ang mga butang."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "matter-states-particles-g3", "domain": "MATTER", "topic": "states of matter", "grades": [3, 4, 5], "terms": ["solid", "liquid", "gas", "shape", "humuhugis", "tatlo", "modagayday", "lalagyan", "sudlanan", "espasyo", "mosunod", "state", "pangunahing", "umaagos"], "fact": {"tl": "May tatlong pangunahing state ng matter. Ang solid ay may sariling hugis (halimbawa: bato). Ang liquid ay umaagos at humuhugis sa lalagyan nito (halimbawa: tubig). Ang gas ay kumakalat sa buong espasyo (halimbawa: hangin). Lahat ng tatlo ay may mass.", "en": "Matter has three main states. A solid keeps its own shape (e.g., a rock). A liquid flows and takes the shape of its container (e.g., water). A gas spreads to fill space (e.g., air). All three have mass.", "bis": "Adunay tulo ka nag-unang state sa matter. Ang solid adunay kaugalingong porma (pananglitan: bato). Ang liquid modagayday ug mosunod sa porma sa sudlanan niini (pananglitan: tubig). Ang gas mokatag sa tibuok espasyo (pananglitan: hangin). Ang tanan nga tulo adunay mass."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "matter-changes-of-state-g4", "domain": "MATTER", "topic": "changes of state", "grades": [4, 5, 6], "terms": ["melting", "freezing", "evaporation", "condensation", "boiling"], "fact": {"tl": "Nagbabago ang state ng matter kapag iniinit o pinapalamig: natutunaw (melting) ang solid papuntang liquid; nagyeyelo (freezing) ang liquid pabalik sa solid; sumisingaw (evaporation) ang liquid papuntang gas; at nagiging liquid muli ang gas (condensation). Pareho pa rin ang sangkap — tubig pa rin ang yelo, tubig, at singaw.", "en": "Matter changes state when heated or cooled: a solid melts to a liquid; a liquid freezes back to a solid, evaporates to a gas, and a gas condenses back to a liquid. It is still the same substance — ice, water, and steam are all water.", "bis": "Mausab ang state sa matter kung initan o bugnawon: matunaw (melting) ang solid ngadto sa liquid; mo-yelo (freezing) ang liquid balik sa solid; mo-alisngaw (evaporation) ang liquid ngadto sa gas; ug mobalik nga liquid ang gas (condensation). Pareho gihapon ang sustansya — tubig gihapon ang yelo, tubig, ug alisngaw."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "matter-mass-volume-weight-g5", "domain": "MATTER", "topic": "mass volume and weight", "grades": [5, 6, 7], "terms": ["mass", "volume", "weight", "gravity", "espasyong", "sinasakop", "gisakpan", "birahay", "mahina", "huyang", "didto", "kakusog", "lakas", "hila"], "fact": {"tl": "Ang mass ay ang dami ng matter sa isang bagay; ang volume ay ang espasyong sinasakop nito; ang weight ay ang lakas ng hila ng gravity sa mass. Pareho ang mass mo kahit saan, pero mas magaan ang weight mo sa buwan dahil mas mahina ang gravity doon.", "en": "Mass is the amount of matter in an object; volume is the space it takes up; weight is the pull of gravity on that mass. Your mass is the same everywhere, but you weigh less on the Moon because its gravity is weaker.", "bis": "Ang mass mao ang gidaghanon sa matter sa usa ka butang; ang volume mao ang espasyong gisakpan niini; ang weight mao ang kakusog sa birahay sa gravity sa mass. Pareho ang imong mass bisan asa, apan mas gaan ang imong weight sa bulan kay mas huyang ang gravity didto."}, "source": "NRC PS2.B; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "matter-physical-chemical-change-g5", "domain": "MATTER", "topic": "physical and chemical change", "grades": [5, 6, 7], "terms": ["physical change", "chemical change", "substance", "sunog", "hulagway", "nasunog", "gihapon", "papel", "natutunaw", "anyo", "lahi", "natunaw", "pareho"], "fact": {"tl": "Sa physical change, nagbabago lang ang anyo o hugis ng bagay pero pareho pa rin ang sangkap — halimbawa, ang natutunaw na yelo ay tubig pa rin. Sa chemical change, nabubuo ang bagong sangkap — halimbawa, ang sunog na papel ay nagiging abo na iba na sa papel.", "en": "In a physical change only the form or shape changes but it is the same substance — e.g., melting ice is still water. In a chemical change a new substance forms — e.g., burning paper becomes ash, different from paper.", "bis": "Sa physical change, ang porma o hulagway lang sa butang ang mausab apan pareho gihapon ang sustansya — pananglitan, ang natunaw nga yelo kay tubig gihapon. Sa chemical change, adunay bag-ong sustansya nga maporma — pananglitan, ang nasunog nga papel mahimong abo nga lahi na sa papel."}, "source": "AAAS BSL Ch.4D; NRC PS1.B", "generator": "claude", "reviewed": false},
  {"id": "matter-mixtures-g5", "domain": "MATTER", "topic": "mixtures", "grades": [5, 6], "terms": ["mixture", "pure substance", "combine", "pinaghalong", "kani", "iisa", "gisagol", "paghiwalayin", "mabulag", "dalawa", "kadalasang", "buhangin", "purong"], "fact": {"tl": "Ang mixture ay pinaghalong dalawa o higit pang sangkap na hindi nagbabago ang kani-kanilang katangian, at kadalasang puwedeng paghiwalayin muli (halimbawa: buhangin at tubig). Iba ito sa purong sangkap na iisa lang ang uri.", "en": "A mixture is two or more substances combined without changing their own properties, and usually can be separated again (e.g., sand and water). This differs from a pure substance, which is only one kind.", "bis": "Ang mixture mao ang gisagol nga duha o sobra pa nga sustansya nga wala mausab ang ila-ilang kinaiya, ug kasagaran mabulag balik (pananglitan: balas ug tubig). Lahi kini sa putli nga sustansya nga usa ra ka klase."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "matter-separating-mixtures-g6", "domain": "MATTER", "topic": "separating mixtures", "grades": [5, 6, 7], "terms": ["filtering", "evaporation", "magnet", "sieving", "ihiwalay", "paggamit", "pagsala", "bulagon", "ayag", "magkaibang", "paghiwalayin", "mabulag", "gidak", "laki"], "fact": {"tl": "Puwedeng paghiwalayin ang mga mixture gamit ang kanilang properties: filtering (para ihiwalay ang solid sa likido), evaporation (para makuha ang natunaw na solid sa tubig), paggamit ng magnet (para sa bakal), at sieving o pagsala (para sa magkaibang laki).", "en": "Mixtures can be separated using their properties: filtering (solids from liquids), evaporation (a dissolved solid from water), a magnet (for iron), and sieving (by particle size).", "bis": "Mabulag ang mga mixture gamit ang ilang properties: filtering (aron bulagon ang solid sa likido), evaporation (aron makuha ang natunaw nga solid sa tubig), paggamit og magnet (para sa puthaw), ug sieving o pag-ayag (para sa nagkalainlaing gidak-on)."}, "source": "DepEd Science CG (Matter); AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "matter-solutions-g6", "domain": "MATTER", "topic": "solutions", "grades": [6, 7], "terms": ["solution", "solute", "solvent", "dissolve", "saturated", "limitasyon", "karami", "tunawin", "ganap", "kayang", "hingpit", "lain", "natutunaw", "puwedeng", "matunaw"], "fact": {"tl": "Ang solution ay isang mixture kung saan ganap na natutunaw ang isang sangkap (solute) sa iba (solvent), tulad ng asukal sa tubig. May limitasyon kung gaano karami ang puwedeng matunaw — kapag hindi na kayang tunawin, tinatawag itong saturated.", "en": "A solution is a mixture where one substance (solute) fully dissolves in another (solvent), like sugar in water. There is a limit to how much can dissolve — once no more dissolves, it is saturated.", "bis": "Ang solution usa ka mixture diin hingpit nga matunaw ang usa ka sustansya (solute) sa lain (solvent), sama sa asukal sa tubig. Adunay limitasyon kung pila ang mahimong matunaw — kung dili na matunaw, gitawag kini nga saturated."}, "source": "NRC PS1.A; DepEd Science CG (Matter)", "generator": "claude", "reviewed": false},
  {"id": "matter-particle-nature-g7", "domain": "MATTER", "topic": "particle nature of matter", "grades": [6, 7, 8], "terms": ["particle", "atom", "molecule", "motion"], "fact": {"tl": "Ang lahat ng matter ay binubuo ng napakaliliit at hindi nakikitang particle (atoms at molecules) na patuloy na gumagalaw. Sa solid, magkakalapit at nanginginig lang sila; sa liquid, magkalapit pero nakakadausdos; sa gas, magkakalayo at mabilis. Ito ang dahilan ng hugis at galaw ng bawat state.", "en": "All matter is made of extremely tiny, invisible particles (atoms and molecules) in constant motion. In a solid they are packed and only vibrate; in a liquid they are close but slide past each other; in a gas they are far apart and fast. This explains each state's shape and behavior.", "bis": "Ang tanang matter gilangkoban og gagmay kaayo ug dili makita nga particle (atoms ug molecules) nga padayon nga naglihok. Sa solid, magkaduol ug magkurog lang sila; sa liquid, duol apan makadausdos; sa gas, magkalayo ug paspas. Mao kini ang hinungdan sa porma ug lihok sa matag state."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "matter-conservation-g7", "domain": "MATTER", "topic": "conservation of matter", "grades": [6, 7, 8], "terms": ["conservation of matter", "mass", "nadaragdag", "madugang", "ginamit", "kanhing", "dating", "kinatibuk", "kabuuang", "masunog", "basta", "nananatili"], "fact": {"tl": "Sa anumang physical o chemical change, hindi nawawala o nadaragdag ang matter — nananatili ang kabuuang mass. Kapag nasunog ang kahoy, hindi ito basta nawawala: nagiging abo at mga gas ito na ang kabuuang bigat ay katumbas ng dating kahoy at hangin na ginamit.", "en": "In any physical or chemical change, matter is not lost or created — the total mass stays the same. When wood burns, it does not simply vanish: it becomes ash and gases whose total mass equals the original wood plus the air used.", "bis": "Sa bisan unsang physical o chemical change, dili mawala o madugang ang matter — magpabilin ang kinatibuk-ang mass. Kung masunog ang kahoy, dili kini basta mawala: mahimo kining abo ug mga gas nga ang kinatibuk-ang gibug-aton katumbas sa kanhing kahoy ug hangin nga gigamit."}, "source": "NRC PS1.B; AAAS BSL Ch.4D", "generator": "claude", "reviewed": false},
  {"id": "matter-atoms-elements-g8", "domain": "MATTER", "topic": "atoms and elements", "grades": [7, 8], "terms": ["atom", "element", "limitadong", "limitado", "kinagamyang", "siyang", "purong", "iisang", "putli", "pinakamaliit", "tanang", "gidaghanon"], "fact": {"tl": "Ang atom ang pinakamaliit na bahagi ng isang element. Ang element ay purong sangkap na gawa sa iisang uri lang ng atom (halimbawa: oxygen, carbon, gold). May limitadong bilang ng elements na siyang building blocks ng lahat ng matter.", "en": "An atom is the smallest part of an element. An element is a pure substance made of only one kind of atom (e.g., oxygen, carbon, gold). There is a limited number of elements, and they are the building blocks of all matter.", "bis": "Ang atom mao ang kinagamyang bahin sa usa ka element. Ang element usa ka putli nga sustansya nga hinimo sa usa ra ka klase nga atom (pananglitan: oxygen, carbon, gold). Adunay limitado nga gidaghanon sa elements nga mao ang building blocks sa tanang matter."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "matter-compounds-molecules-g8", "domain": "MATTER", "topic": "compounds and molecules", "grades": [7, 8], "terms": ["compound", "molecule", "element"], "fact": {"tl": "Kapag nagsama ang atoms ng dalawa o higit pang element, nakabubuo sila ng compound na may bagong properties — halimbawa, ang tubig (H₂O) ay gawa sa hydrogen at oxygen pero iba ito sa dalawang gas na iyon. Ang molecule ay grupo ng atoms na magkakabit.", "en": "When atoms of two or more elements combine, they form a compound with new properties — e.g., water (H₂O) is made of hydrogen and oxygen but differs from those two gases. A molecule is a group of bonded atoms.", "bis": "Kung magsagol ang atoms sa duha o sobra pa nga element, makaporma silag compound nga adunay bag-ong properties — pananglitan, ang tubig (H₂O) hinimo sa hydrogen ug oxygen apan lahi kini niadtong duha ka gas. Ang molecule usa ka grupo sa atoms nga nagkadikit."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "matter-temperature-particles-g7", "domain": "MATTER", "topic": "heat and particle motion", "grades": [6, 7, 8], "terms": ["temperature", "heat", "expansion", "particle motion"], "fact": {"tl": "Mas mabilis gumalaw ang mga particle ng matter kapag mas mainit ito, at mas mabagal kapag malamig. Kaya kadalasang lumalaki (expansion) ang mga bagay kapag iniinit at umuurong kapag pinapalamig.", "en": "The particles in matter move faster when it is hotter and slower when colder. This is why things usually expand when heated and contract when cooled.", "bis": "Mas paspas molihok ang mga particle sa matter kung mas init kini, ug mas hinay kung bugnaw. Mao nga kasagaran modako (expansion) ang mga butang kung initan ug mokunhod kung bugnawon."}, "source": "AAAS BSL Ch.4D; NRC PS3.A", "generator": "claude", "reviewed": false},
  {"id": "matter-elements-compounds-mixtures-g8", "domain": "MATTER", "topic": "elements compounds mixtures", "grades": [8], "terms": ["element", "compound", "mixture", "magkakaibang", "magkasama", "managlahi", "pinaghalo", "gisagol", "paghiwalayin", "mabulag", "dalawa", "iisang", "higit"], "fact": {"tl": "Tatlong magkakaibang bagay: Ang element ay iisang uri ng atom. Ang compound ay dalawa o higit pang element na magkasama sa fixed na ratio at may bagong properties. Ang mixture ay pinaghalo lang nang hindi nabubuo ang bagong sangkap, kaya puwedeng paghiwalayin muli.", "en": "Three different things: an element is one kind of atom. A compound is two or more elements joined in a fixed ratio with new properties. A mixture is just combined without forming a new substance, so it can be separated again.", "bis": "Tulo ka managlahi: Ang element usa ra ka klase nga atom. Ang compound duha o sobra pa nga element nga gisagol sa fixed nga ratio ug adunay bag-ong properties. Ang mixture gisagol lang nga walay bag-ong sustansya, mao nga mabulag balik."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "matter-acids-bases-g9", "domain": "MATTER", "topic": "acids and bases", "grades": [9, 10], "terms": ["acid", "base", "pH", "neutral", "madanlog", "mapakla", "maaslom", "mapait", "sinusukat", "madulas", "gisukod", "maasim", "suka", "kalamansi"], "fact": {"tl": "Ang acid (tulad ng suka at calamansi) ay maasim; ang base (tulad ng sabon at baking soda) ay mapakla at madulas. Sinusukat ng pH scale (0–14) kung gaano ka-acid o ka-base ang isang bagay: mas mababa sa 7 ay acid, mas mataas sa 7 ay base, at ang 7 ay neutral tulad ng purong tubig.", "en": "An acid (like vinegar and calamansi) is sour; a base (like soap and baking soda) is bitter and slippery. The pH scale (0–14) measures how acidic or basic something is: below 7 is acidic, above 7 is basic, and 7 is neutral like pure water.", "bis": "Ang acid (sama sa suka ug kalamansi) maaslom; ang base (sama sa sabon ug baking soda) mapait ug madanlog. Gisukod sa pH scale (0–14) kung unsa ka-acid o ka-base ang usa ka butang: ubos sa 7 kay acid, taas sa 7 kay base, ug ang 7 kay neutral sama sa putli nga tubig."}, "source": "DepEd Science CG (Matter, JHS); NRC PS1.B", "generator": "claude", "reviewed": false},
  {"id": "matter-periodic-metals-g9", "domain": "MATTER", "topic": "periodic table metals nonmetals", "grades": [9, 10], "terms": ["periodic table", "metal", "nonmetal", "element"], "fact": {"tl": "Nakaayos ang mga element sa periodic table. Ang metals (tulad ng bakal at tanso) ay kadalasang makintab, matibay, at nagpapadaloy ng init at kuryente; ang nonmetals (tulad ng oxygen at carbon) ay kadalasang hindi nagpapadaloy ng kuryente.", "en": "The elements are arranged in the periodic table. Metals (like iron and copper) are usually shiny, strong, and conduct heat and electricity; nonmetals (like oxygen and carbon) usually do not conduct electricity.", "bis": "Gihan-ay ang mga element sa periodic table. Ang metals (sama sa puthaw ug tumbaga) kasagaran sinaw, lig-on, ug nagpadala og init ug kuryente; ang nonmetals (sama sa oxygen ug carbon) kasagaran dili magpadala og kuryente."}, "source": "DepEd Science CG (Matter, JHS); AAAS BSL Ch.4D", "generator": "claude", "reviewed": false},
  {"id": "living-photosynthesis-g5", "domain": "LIVING_THINGS", "topic": "photosynthesis", "grades": [4, 5, 6], "terms": ["photosynthesis", "sunlight", "carbon dioxide", "oxygen", "glucose", "chlorophyll", "nilalanghap", "nagbuga", "berdeng", "gumawa", "giginhawa", "berde", "humuhuli", "modakop", "sarili", "naglalabas"], "fact": {"tl": "Sa photosynthesis, ginagamit ng halaman ang liwanag ng araw, tubig, at carbon dioxide mula sa hangin para gumawa ng sarili nitong pagkain na sugar (glucose). Naglalabas din ito ng oxygen na nilalanghap natin. Ang berdeng kulay (chlorophyll) sa dahon ang humuhuli sa liwanag.", "en": "In photosynthesis a plant uses sunlight, water, and carbon dioxide from the air to make its own food, a sugar (glucose). It also releases the oxygen we breathe. The green color (chlorophyll) in leaves captures the light.", "bis": "Sa photosynthesis, gigamit sa tanom ang kahayag sa adlaw, tubig, ug carbon dioxide gikan sa hangin aron maghimo sa kaugalingong pagkaon nga sugar (glucose). Nagbuga usab kini og oxygen nga atong giginhawa. Ang berde nga kolor (chlorophyll) sa dahon mao ang modakop sa kahayag."}, "source": "AAAS BSL Ch.5; NRC LS1.C", "generator": "claude", "reviewed": false},
  {"id": "living-insect-vs-spider-g3", "domain": "LIVING_THINGS", "topic": "insects", "grades": [3, 4], "terms": ["insect", "spider", "legs", "body parts", "dibdib", "dughan", "tiil", "lawalawa", "gagamba", "walong", "tiyan", "anim", "unom", "walo"], "fact": {"tl": "Ang insekto ay may anim (6) na paa at tatlong bahagi ng katawan: ulo (head), dibdib (thorax), at tiyan (abdomen). Ang gagamba ay HINDI insekto dahil may walong (8) paa ito at dalawang bahagi lang ng katawan.", "en": "An insect has six (6) legs and three body parts: head, thorax, and abdomen. A spider is NOT an insect because it has eight (8) legs and only two body parts.", "bis": "Ang insekto adunay unom (6) ka tiil ug tulo ka bahin sa lawas: ulo (head), dughan (thorax), ug tiyan (abdomen). Ang lawalawa DILI insekto kay adunay walo (8) ka tiil ug duha ra ka bahin sa lawas."}, "source": "AAAS BSL Ch.5 (diversity of life)", "generator": "claude", "reviewed": false},
  {"id": "force-push-pull-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "force", "grades": [3, 4, 5], "terms": ["force", "push", "pull", "motion", "makapahunong", "magpatigil", "makapabag", "palihukon", "igalaw", "tulod", "makapalihok", "magpagalaw", "magpabago", "tulak"], "fact": {"tl": "Ang force ay isang tulak (push) o hila (pull) na puwedeng magpagalaw, magpatigil, o magpabago ng direksyon ng isang bagay. Mas malakas na force ang kailangan para igalaw ang mas mabigat na bagay.", "en": "A force is a push or a pull that can make an object move, stop, or change direction. A heavier object needs a stronger force to move it.", "bis": "Ang force usa ka tulod (push) o bira (pull) nga makapalihok, makapahunong, o makapabag-o sa direksyon sa usa ka butang. Mas kusog nga force ang gikinahanglan aron palihukon ang mas bug-at nga butang."}, "source": "NRC PS2.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "earth-water-cycle-g4", "domain": "EARTH_SPACE", "topic": "water cycle", "grades": [4, 5, 6], "terms": ["water cycle", "evaporation", "condensation", "precipitation"], "fact": {"tl": "Sa water cycle, ang init ng araw ay nagpapasingaw ng tubig mula sa dagat at lupa (evaporation). Tumataas ang singaw, lumalamig, at nagiging ulap (condensation). Kapag mabigat na ang ulap, bumabagsak ang tubig bilang ulan (precipitation), at bumabalik ito sa dagat at lupa.", "en": "In the water cycle, the sun's heat evaporates water from seas and land. The vapor rises, cools, and forms clouds (condensation). When clouds get heavy, water falls as rain (precipitation) and returns to seas and land.", "bis": "Sa water cycle, ang kainit sa adlaw mopaalisngaw sa tubig gikan sa dagat ug yuta (evaporation). Mosaka ang alisngaw, mobugnaw, ug mahimong panganod (condensation). Kung mabug-at na ang panganod, mahulog ang tubig isip ulan (precipitation), ug mobalik kini sa dagat ug yuta."}, "source": "AAAS BSL Ch.4; NRC ESS2.C", "generator": "claude", "reviewed": false},
  {"id": "living-characteristics-g3", "domain": "LIVING_THINGS", "topic": "living vs nonliving", "grades": [3, 4], "terms": ["living", "nonliving", "grow", "reproduce", "nakakapagpaparami", "kumukuha", "tumutugon", "motubag", "mokuha", "humihinga", "ginagawa", "moginhawa", "kumakain", "mokaon"], "fact": {"tl": "Ang mga buhay na bagay (living things) ay lumalaki, kumakain o kumukuha ng enerhiya, humihinga, tumutugon sa paligid, at nakakapagpaparami (reproduce). Ang mga di-buhay na bagay tulad ng bato at tubig ay hindi ginagawa ang mga ito.", "en": "Living things grow, take in food or energy, breathe, respond to their surroundings, and reproduce. Nonliving things like rocks and water do not do these.", "bis": "Ang buhi nga mga butang (living things) motubo, mokaon o mokuha og enerhiya, moginhawa, motubag sa palibot, ug makahimo og bag-o nga sama nila (reproduce). Ang dili-buhi nga mga butang sama sa bato ug tubig wala maghimo niini."}, "source": "AAAS BSL Ch.5; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "living-basic-needs-g3", "domain": "LIVING_THINGS", "topic": "basic needs", "grades": [3, 4], "terms": ["needs", "food", "water", "air", "sunlight", "matitirhan", "nagkinahanglan", "mabuhay", "anan", "mabuhi", "kailangan", "sikat", "sustansya", "hayop", "lupa"], "fact": {"tl": "Para mabuhay, kailangan ng mga hayop ng pagkain, tubig, hangin, at matitirhan. Kailangan naman ng mga halaman ng tubig, hangin (carbon dioxide), sikat ng araw, at sustansya mula sa lupa.", "en": "To live, animals need food, water, air, and a place to live. Plants need water, air (carbon dioxide), sunlight, and nutrients from the soil.", "bis": "Aron mabuhi, ang mga hayop nagkinahanglan og pagkaon, tubig, hangin, ug puy-anan. Ang mga tanom nagkinahanglan og tubig, hangin (carbon dioxide), kahayag sa adlaw, ug sustansya gikan sa yuta."}, "source": "AAAS BSL Ch.5; NRC LS1.C", "generator": "claude", "reviewed": false},
  {"id": "living-plant-parts-g3", "domain": "LIVING_THINGS", "topic": "parts of a plant", "grades": [3, 4], "terms": ["roots", "stem", "leaves", "flower", "sumusuporta", "pagpaparami", "humuhigop", "mosuporta", "pagsanay", "humahawak", "mokupot", "tungkulin", "tangkay", "punoan"], "fact": {"tl": "May iba't ibang bahagi ang halaman na may tungkulin: ang ugat (roots) ang humuhigop ng tubig at sustansya at humahawak sa lupa; ang tangkay (stem) ang nagdadala ng tubig at sumusuporta sa halaman; ang dahon (leaves) ang gumagawa ng pagkain sa photosynthesis; at ang bulaklak (flower) ang bahagi para sa pagpaparami.", "en": "A plant has parts with jobs: roots absorb water and nutrients and anchor it; the stem carries water and supports the plant; leaves make food by photosynthesis; and the flower is the part for reproduction.", "bis": "Adunay nagkalainlaing bahin ang tanom nga may tahas: ang gamot (roots) mosuyop og tubig ug sustansya ug mokupot sa yuta; ang punoan (stem) modala sa tubig ug mosuporta sa tanom; ang dahon (leaves) maghimo og pagkaon pinaagi sa photosynthesis; ug ang bulak (flower) mao ang bahin alang sa pagsanay."}, "source": "AAAS BSL Ch.5; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "living-vertebrate-invertebrate-g4", "domain": "LIVING_THINGS", "topic": "animal groups", "grades": [4, 5], "terms": ["vertebrate", "invertebrate", "backbone", "gulugod", "pasayan", "hipon", "lawalawa", "gagamba", "likod", "bitin", "ibon", "ahas", "langgam"], "fact": {"tl": "Nahahati ang mga hayop sa dalawang malaking grupo: ang vertebrates na may gulugod o backbone (tulad ng isda, ibon, ahas, palaka, at tao) at ang invertebrates na walang backbone (tulad ng insekto, gagamba, uod, at hipon).", "en": "Animals fall into two big groups: vertebrates with a backbone (like fish, birds, snakes, frogs, and humans) and invertebrates without a backbone (like insects, spiders, worms, and shrimp).", "bis": "Nabahin ang mga hayop sa duha ka dako nga grupo: ang vertebrates nga adunay bukog sa likod o backbone (sama sa isda, langgam, bitin, baki, ug tawo) ug ang invertebrates nga walay backbone (sama sa insekto, lawalawa, ulod, ug pasayan)."}, "source": "AAAS BSL Ch.5 (diversity of life)", "generator": "claude", "reviewed": false},
  {"id": "living-life-cycle-g4", "domain": "LIVING_THINGS", "topic": "life cycles", "grades": [4, 5], "terms": ["life cycle", "metamorphosis", "egg", "larva", "ipinanganak", "namamatay", "tangkong", "moturok", "mamatay", "matawo", "kokon", "paru", "paro", "nagpaparami"], "fact": {"tl": "Bawat buhay na bagay ay dumadaan sa life cycle: ipinanganak o tumutubo, lumalaki, nagpaparami, at namamatay. May mga hayop na dumadaan sa metamorphosis — halimbawa, ang paru-paro: itlog → higad (caterpillar) → kokon (pupa) → paru-paro; at ang palaka: itlog → ulo-ulo (tadpole) → palaka.", "en": "Every living thing goes through a life cycle: it is born or sprouts, grows, reproduces, and dies. Some animals undergo metamorphosis — e.g., a butterfly: egg → caterpillar → pupa → butterfly; and a frog: egg → tadpole → frog.", "bis": "Ang matag buhi nga butang moagi sa life cycle: matawo o moturok, motubo, mosanay, ug mamatay. Adunay mga hayop nga moagi sa metamorphosis — pananglitan, ang alibangbang: itlog → tangkong (caterpillar) → pupa → alibangbang; ug ang baki: itlog → ulo-ulo (tadpole) → baki."}, "source": "AAAS BSL Ch.5; NRC LS1.B", "generator": "claude", "reviewed": false},
  {"id": "living-habitat-adaptation-g4", "domain": "LIVING_THINGS", "topic": "habitat and adaptation", "grades": [4, 5, 6], "terms": ["habitat", "adaptation", "survive", "environment", "pangangailangan", "panginahanglan", "nakukuha", "pinasahi", "organismo", "disyerto", "malalim", "lawom", "kapaligiran", "balahibo"], "fact": {"tl": "Ang habitat ay ang natural na tirahan ng isang halaman o hayop kung saan nakukuha nito ang pangangailangan nito. Ang adaptation ay ang espesyal na katangian na tumutulong sa isang organismo na mabuhay sa kapaligiran nito — halimbawa, ang makapal na balahibo ng hayop sa malamig na lugar, o ang malalim na ugat ng halaman sa disyerto.", "en": "A habitat is the natural home where a plant or animal gets what it needs. An adaptation is a special trait that helps an organism survive in its environment — e.g., thick fur on an animal in a cold place, or deep roots on a desert plant.", "bis": "Ang habitat mao ang natural nga puy-anan sa usa ka tanom o hayop diin makuha niini ang panginahanglan niini. Ang adaptation mao ang pinasahi nga kinaiya nga motabang sa organismo nga mabuhi sa palibot niini — pananglitan, ang baga nga balhibo sa hayop sa bugnaw nga dapit, o ang lawom nga gamot sa tanom sa disyerto."}, "source": "AAAS BSL Ch.5; NRC LS4.C", "generator": "claude", "reviewed": false},
  {"id": "living-food-chain-g5", "domain": "LIVING_THINGS", "topic": "food chain", "grades": [5, 6], "terms": ["food chain", "producer", "consumer", "decomposer", "naghimo", "ipinapakita", "naglalansag", "gipakita", "moguba", "agos", "dumadaloy", "kumakain", "patay", "mokaon"], "fact": {"tl": "Ipinapakita ng food chain kung paano dumadaloy ang enerhiya sa pamamagitan ng pagkain. Ang mga halaman ay producers (gumagawa ng sariling pagkain). Ang mga hayop na kumakain ng halaman o ibang hayop ay consumers. Ang mga decomposers (tulad ng fungi at bacteria) ang naglalansag sa patay na bagay pabalik sa lupa.", "en": "A food chain shows how energy flows through eating. Plants are producers (they make their own food). Animals that eat plants or other animals are consumers. Decomposers (like fungi and bacteria) break down dead matter back into the soil.", "bis": "Gipakita sa food chain kung giunsa pag-agos ang enerhiya pinaagi sa pagkaon. Ang mga tanom kay producers (naghimo sa kaugalingong pagkaon). Ang mga hayop nga mokaon og tanom o ubang hayop kay consumers. Ang mga decomposers (sama sa fungi ug bacteria) maoy moguba sa patay nga butang balik sa yuta."}, "source": "AAAS BSL Ch.5; NRC LS2.B", "generator": "claude", "reviewed": false},
  {"id": "living-ecosystem-g6", "domain": "LIVING_THINGS", "topic": "ecosystem", "grades": [6, 7], "terms": ["ecosystem", "biotic", "abiotic", "environment", "uugnayan", "pagpakig", "kausaban", "microorganism", "nakakaapekto", "makaapekto", "magkakaugnay", "pagbabago", "magkadugtong", "tanan"], "fact": {"tl": "Ang ecosystem ay ang lahat ng buhay na bagay (biotic — halaman, hayop, microorganism) at di-buhay na bagay (abiotic — tubig, hangin, lupa, init ng araw) sa isang lugar, at kung paano sila nag-uugnayan. Magkakaugnay ang lahat: ang pagbabago sa isa ay nakakaapekto sa iba.", "en": "An ecosystem is all the living things (biotic — plants, animals, microorganisms) and nonliving things (abiotic — water, air, soil, sunlight) in a place, and how they interact. Everything is connected: a change in one affects the others.", "bis": "Ang ecosystem mao ang tanang buhi nga butang (biotic — tanom, hayop, microorganism) ug dili-buhi nga butang (abiotic — tubig, hangin, yuta, kahayag sa adlaw) sa usa ka dapit, ug kung giunsa sila pagpakig-uban. Magkadugtong ang tanan: ang kausaban sa usa makaapekto sa uban."}, "source": "NRC LS2.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-respiration-g6", "domain": "LIVING_THINGS", "topic": "respiration", "grades": [6, 7, 8], "terms": ["respiration", "oxygen", "energy", "carbon dioxide", "enerhiyang", "palabasin", "gumagamit", "nagbuga", "sukwahi", "mogamit", "kabaligtaran", "nakaimbak", "ipagawas", "natipig"], "fact": {"tl": "Sa respiration, ginagamit ng mga buhay na bagay ang oxygen para palabasin ang enerhiyang nakaimbak sa pagkain (sugar), at naglalabas sila ng carbon dioxide at tubig. Kabaligtaran ito ng photosynthesis: ang halaman ay parehong gumagawa ng pagkain (photosynthesis) at gumagamit nito para sa enerhiya (respiration).", "en": "In respiration, living things use oxygen to release the energy stored in food (sugar), giving off carbon dioxide and water. It is the reverse of photosynthesis: plants both make food (photosynthesis) and use it for energy (respiration).", "bis": "Sa respiration, gigamit sa buhi nga mga butang ang oxygen aron ipagawas ang enerhiya nga natipig sa pagkaon (sugar), ug nagbuga sila og carbon dioxide ug tubig. Sukwahi kini sa photosynthesis: ang tanom maghimo og pagkaon (photosynthesis) ug mogamit niini alang sa enerhiya (respiration)."}, "source": "NRC LS1.C; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-cell-g7", "domain": "LIVING_THINGS", "topic": "the cell", "grades": [7, 8], "terms": ["cell", "unit of life", "organism", "trilyon", "yunit", "kinagamyang", "organismo", "trilyong", "gilangkoban", "binubuo", "iisang", "pinakamaliit", "marami"], "fact": {"tl": "Ang cell ang pinakamaliit na yunit ng buhay — lahat ng buhay na bagay ay binubuo ng isa o higit pang cell. May organismo na iisang cell lang (tulad ng bacteria), at may marami tulad ng tao na binubuo ng trilyong cell.", "en": "The cell is the smallest unit of life — all living things are made of one or more cells. Some organisms are a single cell (like bacteria), and many, like humans, are made of trillions of cells.", "bis": "Ang cell mao ang kinagamyang yunit sa kinabuhi — ang tanang buhi nga butang gilangkoban og usa o sobra pa ka cell. Adunay organismo nga usa ra ka cell (sama sa bacteria), ug adunay daghan sama sa tawo nga gilangkoban og trilyon ka cell."}, "source": "NRC LS1.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-plant-animal-cell-g7", "domain": "LIVING_THINGS", "topic": "plant vs animal cell", "grades": [7, 8], "terms": ["cell wall", "chloroplast", "nucleus", "membrane", "panggawas", "dagdag", "dugang", "nagkokontrol", "nagkontrol", "panlabas", "sentro", "parehong", "matigas", "alang"], "fact": {"tl": "Parehong may nucleus (sentro na nagkokontrol), cell membrane, at cytoplasm ang plant at animal cell. Pero ang plant cell ay may dagdag na cell wall (matigas na panlabas na balat) at chloroplasts (para sa photosynthesis) na wala sa animal cell.", "en": "Both plant and animal cells have a nucleus (control center), cell membrane, and cytoplasm. But a plant cell also has a cell wall (a stiff outer layer) and chloroplasts (for photosynthesis), which an animal cell does not.", "bis": "Parehong adunay nucleus (sentro nga nagkontrol), cell membrane, ug cytoplasm ang plant ug animal cell. Apan ang plant cell adunay dugang nga cell wall (gahi nga panggawas nga panit) ug chloroplasts (alang sa photosynthesis) nga wala sa animal cell."}, "source": "NRC LS1.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-body-systems-g5", "domain": "LIVING_THINGS", "topic": "human body systems", "grades": [5, 6], "terms": ["body systems", "organ", "digestive", "circulatory", "respiratory", "magkakatulong", "nagtinabangay", "pagdaloy", "pagkontrol", "pagtunaw", "paghilis", "pagbati", "agos", "magkakaugnay", "pakiramdam"], "fact": {"tl": "Ang katawan ng tao ay may magkakaugnay na body systems na may tungkulin: digestive (pagtunaw ng pagkain), respiratory (paghinga), circulatory (pagdaloy ng dugo), skeletal (buto), muscular (kalamnan), at nervous (pagkontrol at pakiramdam). Magkakatulong silang lahat para manatiling buhay ang tao.", "en": "The human body has connected systems with jobs: digestive (breaking down food), respiratory (breathing), circulatory (blood flow), skeletal (bones), muscular (muscles), and nervous (control and sensing). They all work together to keep a person alive.", "bis": "Ang lawas sa tawo adunay magkadugtong nga body systems nga may tahas: digestive (paghilis sa pagkaon), respiratory (pagginhawa), circulatory (pag-agos sa dugo), skeletal (bukog), muscular (kaunoran), ug nervous (pagkontrol ug pagbati). Nagtinabangay silang tanan aron mabuhi ang tawo."}, "source": "NRC LS1.A; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "living-digestive-g6", "domain": "LIVING_THINGS", "topic": "digestive system", "grades": [6, 7], "terms": ["digestion", "stomach", "intestine", "nutrients", "nginunguya", "hinahaluan", "inilalabas", "gisapsap", "masuyop", "sikmura", "bituka", "laway", "tinai", "dumi"], "fact": {"tl": "Sa digestive system, dumadaan ang pagkain sa bibig (nginunguya at hinahaluan ng laway), lalamunan, sikmura (stomach, kung saan natutunaw ito), at bituka (intestines, kung saan sinisipsip ang sustansya papunta sa dugo). Ang hindi natunaw ay inilalabas bilang dumi.", "en": "In the digestive system, food passes through the mouth (chewed and mixed with saliva), the esophagus, the stomach (where it is broken down), and the intestines (where nutrients are absorbed into the blood). What is not digested is passed out as waste.", "bis": "Sa digestive system, ang pagkaon moagi sa baba (gisapsap ug gisagolan og laway), tutunlan, tiyan (stomach, diin matunaw kini), ug tinai (intestines, diin masuyop ang sustansya ngadto sa dugo). Ang dili matunaw ipagawas isip hugaw."}, "source": "AAAS BSL Ch.6; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "living-circulatory-g6", "domain": "LIVING_THINGS", "topic": "circulatory system", "grades": [6, 7], "terms": ["heart", "blood", "vessels", "oxygen", "naghahatid", "bumobomba", "mobomba", "waste", "kasingkasing", "mokuha", "aalis", "puso", "hugaw", "kalamnan"], "fact": {"tl": "Ang circulatory system ang nagdadala ng dugo sa buong katawan. Ang puso (heart) ay isang kalamnan na bumobomba ng dugo sa mga ugat (blood vessels). Ang dugo ang naghahatid ng oxygen at sustansya sa mga cell at nag-aalis ng mga waste tulad ng carbon dioxide.", "en": "The circulatory system moves blood around the body. The heart is a muscle that pumps blood through blood vessels. Blood delivers oxygen and nutrients to cells and removes wastes like carbon dioxide.", "bis": "Ang circulatory system maoy modala sa dugo sa tibuok lawas. Ang kasingkasing (heart) usa ka kaunoran nga mobomba sa dugo agi sa mga ugat (blood vessels). Ang dugo modala og oxygen ug sustansya ngadto sa mga cell ug mokuha sa mga hugaw sama sa carbon dioxide."}, "source": "AAAS BSL Ch.6; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "living-respiratory-g6", "domain": "LIVING_THINGS", "topic": "respiratory system", "grades": [6, 7], "terms": ["lungs", "breathing", "oxygen", "carbon dioxide", "pinapalabas", "inihihinga", "modumala", "huminga", "ibuga", "humahawak", "pagawas", "unya", "pumapasok", "palabas"], "fact": {"tl": "Ang respiratory system ang humahawak sa paghinga. Kapag huminga ka, pumapasok ang hangin sa baga (lungs), kung saan kinukuha ng dugo ang oxygen at pinapalabas ang carbon dioxide. Pagkatapos, inihihinga mo palabas ang carbon dioxide.", "en": "The respiratory system handles breathing. When you breathe in, air enters the lungs, where the blood takes in oxygen and gives off carbon dioxide. Then you breathe the carbon dioxide back out.", "bis": "Ang respiratory system maoy modumala sa pagginhawa. Kung moginhawa ka, mosulod ang hangin sa baga (lungs), diin kuhaon sa dugo ang oxygen ug ibuga ang carbon dioxide. Unya, imong giginhawa pagawas ang carbon dioxide."}, "source": "AAAS BSL Ch.6; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "living-skeletal-muscular-g5", "domain": "LIVING_THINGS", "topic": "skeletal and muscular system", "grades": [5, 6], "terms": ["bones", "skeleton", "muscles", "support"], "fact": {"tl": "Ang skeletal system (mga buto o skeleton) ang nagbibigay ng hugis at suporta sa katawan at nag-iingat sa mga organ. Ang muscular system (mga kalamnan o muscles) ang nakakabit sa buto at humihila sa mga ito para tayo makagalaw. Magkatuwang silang gumagana.", "en": "The skeletal system (bones) gives the body shape and support and protects organs. The muscular system (muscles) attaches to bones and pulls on them so we can move. They work as partners.", "bis": "Ang skeletal system (mga bukog o skeleton) maghatag og porma ug suporta sa lawas ug manalipod sa mga organ. Ang muscular system (mga kaunoran o muscles) nakadikit sa bukog ug mobira niini aron makalihok ta. Magtinabangay sila."}, "source": "AAAS BSL Ch.6; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "living-nervous-g7", "domain": "LIVING_THINGS", "topic": "nervous system", "grades": [7, 8], "terms": ["brain", "nerves", "senses", "signals", "nagpoproseso", "tumatanggap", "moproseso", "sentrong", "pagtubag", "tutugon", "modawat", "mosugo", "uutos", "nagkokontrol"], "fact": {"tl": "Ang nervous system — utak (brain), spinal cord, at nerves — ang sentrong nagkokontrol ng katawan. Tumatanggap ito ng signals mula sa mga pandama (mata, tainga, balat, ilong, dila), nagpoproseso, at nag-uutos sa katawan kung paano tutugon.", "en": "The nervous system — brain, spinal cord, and nerves — is the body's control center. It receives signals from the senses (eyes, ears, skin, nose, tongue), processes them, and tells the body how to respond.", "bis": "Ang nervous system — utok (brain), spinal cord, ug nerves — mao ang sentro nga nagkontrol sa lawas. Modawat kini og signals gikan sa mga igbalati (mata, dalunggan, panit, ilong, dila), moproseso, ug mosugo sa lawas kung unsaon pagtubag."}, "source": "AAAS BSL Ch.6; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "living-classification-g7", "domain": "LIVING_THINGS", "topic": "classification of living things", "grades": [7, 8], "terms": ["classification", "species", "kingdom", "characteristics", "magkakatulad", "giklasipikar", "kinatukmaang", "pinakatiyak", "siyentipiko", "paghingalan", "pangalanan", "iniuuri", "pagtuon", "aralan"], "fact": {"tl": "Iniuuri (classified) ang mga buhay na bagay ayon sa kanilang magkakatulad na katangian, mula sa malalaking grupo (tulad ng hayop, halaman, fungi, at microorganism) hanggang sa pinakatiyak na grupo na species. Tumutulong ito sa mga siyentipiko na pag-aralan at pangalanan ang milyon-milyong klase ng buhay.", "en": "Living things are classified by their shared characteristics, from large groups (like animals, plants, fungi, and microorganisms) down to the most specific group, the species. This helps scientists study and name the millions of kinds of life.", "bis": "Giklasipikar ang mga buhi nga butang sumala sa ilang managsama nga kinaiya, gikan sa dagkong grupo (sama sa hayop, tanom, fungi, ug microorganism) hangtod sa kinatukmaang grupo nga species. Motabang kini sa mga siyentista sa pagtuon ug paghingalan sa milyon-milyon ka klase sa kinabuhi."}, "source": "AAAS BSL Ch.5; NRC LS4.A", "generator": "claude", "reviewed": false},
  {"id": "living-heredity-g8", "domain": "LIVING_THINGS", "topic": "heredity", "grades": [7, 8], "terms": ["heredity", "traits", "inherited", "parents", "genes", "magkakahawig", "magkapareho", "makapanunod", "ipinapasa", "nagmamana", "ginikanan", "magulang", "ipasa", "gayod", "busa"], "fact": {"tl": "Sa heredity, ipinapasa ng mga magulang ang kanilang mga katangian (traits) sa kanilang anak sa pamamagitan ng genes. Kaya nagmamana ang anak ng mga katangian tulad ng kulay ng mata o hugis ng dahon — kaya magkakahawig ang magulang at anak pero hindi magkapareho.", "en": "In heredity, parents pass their traits to their offspring through genes. That is why offspring inherit traits like eye color or leaf shape — so parents and offspring resemble each other but are not identical.", "bis": "Sa heredity, ipasa sa mga ginikanan ang ilang mga kinaiya (traits) ngadto sa ilang anak pinaagi sa genes. Mao nga makapanunod ang anak og mga kinaiya sama sa kolor sa mata o porma sa dahon — busa magkapareho ang ginikanan ug anak apan dili managsama gayod."}, "source": "NRC LS3.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-plant-reproduction-g6", "domain": "LIVING_THINGS", "topic": "plant reproduction", "grades": [6, 7], "terms": ["pollination", "seed", "flower", "fruit", "nagpapakalat", "inililipat", "nagtatago", "putyokan", "ibalhin", "tumubo", "nagpaparami", "mosanay", "bubuyog", "minsan"], "fact": {"tl": "Maraming halaman ang nagpaparami sa pamamagitan ng mga buto (seeds). Sa pollination, inililipat ng hangin o insekto (tulad ng bubuyog) ang pollen sa bulaklak. Pagkatapos nito, nabubuo ang buto at minsan ay prutas na nagtatago at nagpapakalat sa buto para tumubo ang bagong halaman.", "en": "Many plants reproduce through seeds. In pollination, wind or insects (like bees) move pollen on a flower. After this, a seed forms — sometimes inside a fruit that protects and spreads the seed so a new plant can grow.", "bis": "Daghang tanom ang mosanay pinaagi sa mga liso (seeds). Sa pollination, ibalhin sa hangin o insekto (sama sa putyokan) ang pollen sa bulak. Human niini, maporma ang liso ug usahay prutas nga manalipod ug mokatag sa liso aron motubo ang bag-ong tanom."}, "source": "AAAS BSL Ch.5; NRC LS1.B", "generator": "claude", "reviewed": false},
  {"id": "living-microorganisms-g7", "domain": "LIVING_THINGS", "topic": "microorganisms", "grades": [7, 8], "terms": ["microorganism", "bacteria", "virus", "microscope", "nakakatulong", "nakakasakit", "trangkaso", "pagdurog", "kondili", "kundi", "makapasakit", "paggawa", "paghimo", "pagguba"], "fact": {"tl": "Ang microorganisms ay napakaliliit na buhay na bagay na hindi nakikita ng mata kundi sa pamamagitan lang ng microscope, tulad ng bacteria at fungi. May nakakatulong sa kanila (halimbawa, paggawa ng yogurt o pagdurog ng patay na bagay) at may nakakasakit. Ang virus ay mas maliit pa at nagdudulot ng sakit tulad ng trangkaso.", "en": "Microorganisms are tiny living things seen only through a microscope, like bacteria and fungi. Some are helpful (e.g., making yogurt or breaking down dead matter) and some cause disease. A virus is even smaller and causes illnesses like the flu.", "bis": "Ang microorganisms mao ang gagmay kaayo nga buhi nga butang nga dili makita sa mata kondili pinaagi lang sa microscope, sama sa bacteria ug fungi. Adunay makatabang kanila (pananglitan, paghimo og yogurt o pagguba sa patay nga butang) ug adunay makapasakit. Ang virus mas gamay pa ug maoy hinungdan sa sakit sama sa trangkaso."}, "source": "AAAS BSL Ch.5; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "living-biodiversity-g8", "domain": "LIVING_THINGS", "topic": "biodiversity", "grades": [7, 8], "terms": ["biodiversity", "species", "ecosystem", "balance", "pinakamayaman", "pagkalainlain", "bansang", "nasod", "magkakaiba", "matatag", "kapaligiran", "pagkakaiba", "lainlain", "dato"], "fact": {"tl": "Ang biodiversity ay ang dami at pagkakaiba-iba ng mga buhay na bagay sa isang lugar. Mahalaga ito dahil ang bawat species ay may papel sa ecosystem, at kapag mas magkakaiba-iba ang buhay, mas matatag at malusog ang kapaligiran. Ang Pilipinas ay isa sa mga bansang pinakamayaman sa biodiversity.", "en": "Biodiversity is the number and variety of living things in a place. It matters because each species has a role in the ecosystem, and the more varied the life, the more stable and healthy the environment. The Philippines is one of the most biodiversity-rich countries.", "bis": "Ang biodiversity mao ang gidaghanon ug pagkalainlain sa mga buhi nga butang sa usa ka dapit. Importante kini kay ang matag species adunay papel sa ecosystem, ug kung mas lainlain ang kinabuhi, mas lig-on ug himsog ang palibot. Ang Pilipinas usa sa mga nasod nga labing dato sa biodiversity."}, "source": "NRC LS2.C; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "fme-motion-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "motion and position", "grades": [3, 4, 5], "terms": ["motion", "position", "reference", "distance", "nakatigil", "kaugnay", "kalabot", "posisyon", "poste", "dalan", "nagpahulay", "sasakyan", "sakyanan", "laing"], "fact": {"tl": "Ang isang bagay ay gumagalaw (in motion) kapag nagbabago ang posisyon nito kaugnay ng ibang bagay (reference point). Halimbawa, ang sasakyan ay gumagalaw kaugnay ng poste sa daan. Kapag hindi nagbabago ang posisyon, ito ay nakatigil (at rest).", "en": "An object is in motion when its position changes relative to another object (a reference point). For example, a car moves relative to a post on the road. When its position does not change, it is at rest.", "bis": "Ang usa ka butang naglihok (in motion) kung mausab ang posisyon niini kalabot sa laing butang (reference point). Pananglitan, ang sakyanan naglihok kalabot sa poste sa dalan. Kung wala mausab ang posisyon, kini nagpahulay (at rest)."}, "source": "NRC PS2.A; AAAS BSL Ch.4F", "generator": "claude", "reviewed": false},
  {"id": "fme-speed-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "speed", "grades": [4, 5, 6], "terms": ["speed", "distance", "time", "fast", "nalalakbay", "nalakbay", "nabaktas", "takdang", "takna", "kabilis", "layong", "malayo", "oras", "parehong"], "fact": {"tl": "Ang speed ay kung gaano kabilis gumalaw ang isang bagay — ang layong (distance) nalakbay sa loob ng isang takdang oras (time). Mas mabilis ang isang bagay kung mas malayo ang nalalakbay nito sa parehong dami ng oras.", "en": "Speed is how fast an object moves — the distance it travels in a certain amount of time. An object is faster if it covers more distance in the same amount of time.", "bis": "Ang speed mao kung unsa ka paspas molihok ang usa ka butang — ang gilay-on (distance) nga nabaktas sulod sa usa ka takna nga oras (time). Mas paspas ang butang kung mas layo ang iyang nabaktas sa parehas nga gidaghanon sa oras."}, "source": "NRC PS2.A; AAAS BSL Ch.4F", "generator": "claude", "reviewed": false},
  {"id": "fme-friction-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "friction", "grades": [4, 5, 6], "terms": ["friction", "surface", "slow", "resist"], "fact": {"tl": "Ang friction ay isang force na sumasalungat sa galaw kapag may dalawang ibabaw (surface) na nagkikiskisan. Kaya humihinto o bumabagal ang gumugulong na bola. Mas malaki ang friction sa magaspang na ibabaw kaysa sa makinis o madulas.", "en": "Friction is a force that opposes motion when two surfaces rub together. That is why a rolling ball slows and stops. Friction is greater on rough surfaces than on smooth or slippery ones.", "bis": "Ang friction usa ka force nga mosupak sa paglihok kung adunay duha ka nawong (surface) nga nagkuskos. Mao nga mohunong o mohinay ang nagligid nga bola. Mas dako ang friction sa gansang nga nawong kaysa sa hamis o danlog."}, "source": "NRC PS2.A; AAAS BSL Ch.4F", "generator": "claude", "reviewed": false},
  {"id": "fme-gravity-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "gravity", "grades": [4, 5, 6], "terms": ["gravity", "weight", "fall", "Earth", "binitawan", "buhian", "nananatili", "kakusog", "bumabagsak", "humihila", "mobira", "gitna", "magpabilin", "lakas"], "fact": {"tl": "Ang gravity ay ang force na humihila ng mga bagay papunta sa gitna ng Earth. Kaya bumabagsak pababa ang mga bagay kapag binitawan, at kaya tayo nananatili sa lupa. Ang weight ay ang lakas ng hila ng gravity sa isang bagay.", "en": "Gravity is the force that pulls objects toward the center of the Earth. That is why things fall down when released, and why we stay on the ground. Weight is the strength of gravity's pull on an object.", "bis": "Ang gravity mao ang force nga mobira sa mga butang paingon sa tunga sa Earth. Mao nga mahulog paubos ang mga butang kung buhian, ug mao nga magpabilin ta sa yuta. Ang weight mao ang kakusog sa bira sa gravity sa usa ka butang."}, "source": "NRC PS2.B; AAAS BSL Ch.4B/4F", "generator": "claude", "reviewed": false},
  {"id": "fme-simple-machines-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "simple machines", "grades": [5, 6], "terms": ["simple machine", "lever", "pulley", "inclined plane", "work", "nagpapadali", "makapasayon", "kagamitang", "sahaganan", "pakalmot", "trabaho", "dahilig", "palakol", "himan", "atsa"], "fact": {"tl": "Ang simple machines ay mga kagamitang nagpapadali ng trabaho sa pamamagitan ng pagbabago ng laki o direksyon ng force. Anim ang uri: lever (tulad ng seesaw), pulley, inclined plane (dahilig), wheel and axle, wedge (pakalmot tulad ng palakol), at screw.", "en": "Simple machines are tools that make work easier by changing the size or direction of a force. There are six kinds: lever (like a seesaw), pulley, inclined plane (ramp), wheel and axle, wedge (like an axe), and screw.", "bis": "Ang simple machines mga himan nga makapasayon sa trabaho pinaagi sa pag-usab sa gidak-on o direksyon sa force. Unom ka klase: lever (sama sa seesaw), pulley, inclined plane (sahaganan), wheel and axle, wedge (sama sa atsa), ug screw."}, "source": "DepEd Science CG (FME); AAAS BSL Ch.8", "generator": "claude", "reviewed": false},
  {"id": "fme-energy-forms-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "forms of energy", "grades": [4, 5, 6], "terms": ["energy", "heat", "light", "sound", "electrical", "mechanical", "kakayahang", "magpagalaw", "magpabago", "gasolina", "katakos", "pagbag", "nakaimbak", "natipig", "paglihok", "anyo"], "fact": {"tl": "Ang energy ay ang kakayahang magpagalaw o magpabago ng bagay. May iba't ibang anyo ito: heat (init), light (liwanag), sound (tunog), electrical (kuryente), mechanical (galaw), at chemical (nakaimbak sa pagkain at gasolina).", "en": "Energy is the ability to make things move or change. It comes in different forms: heat, light, sound, electrical, mechanical (motion), and chemical (stored in food and fuel).", "bis": "Ang energy mao ang katakos sa paglihok o pagbag-o sa butang. Adunay nagkalainlaing porma kini: heat (kainit), light (kahayag), sound (tingog), electrical (kuryente), mechanical (lihok), ug chemical (natipig sa pagkaon ug gasolina)."}, "source": "NRC PS3.A; AAAS BSL Ch.4E", "generator": "claude", "reviewed": false},
  {"id": "fme-kinetic-potential-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "kinetic and potential energy", "grades": [6, 7, 8], "terms": ["kinetic energy", "potential energy", "stored", "motion", "tumatakbong", "gumulong", "nagdagan", "moligid", "kalagayan", "posisyon", "bungtod", "tuktok", "burol", "nakaimbak"], "fact": {"tl": "Ang kinetic energy ay ang energy ng isang bagay na gumagalaw (halimbawa, tumatakbong bata). Ang potential energy ay ang nakaimbak na energy dahil sa posisyon o kalagayan ng bagay (halimbawa, bato sa tuktok ng burol bago ito gumulong pababa).", "en": "Kinetic energy is the energy of a moving object (e.g., a running child). Potential energy is stored energy due to an object's position or condition (e.g., a rock at the top of a hill before it rolls down).", "bis": "Ang kinetic energy mao ang energy sa naglihok nga butang (pananglitan, nagdagan nga bata). Ang potential energy mao ang natipig nga energy tungod sa posisyon o kahimtang sa butang (pananglitan, bato sa tumoy sa bungtod sa wala pa kini moligid paubos)."}, "source": "NRC PS3.A; AAAS BSL Ch.4E", "generator": "claude", "reviewed": false},
  {"id": "fme-energy-conservation-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "energy transformation", "grades": [7, 8], "terms": ["energy transformation", "conservation of energy", "nalilikha", "nananatiling", "kinatibuk", "kabuuang", "tapos", "baterya", "dayon", "nawawala", "parehas", "anyo"], "fact": {"tl": "Hindi nalilikha o nawawala ang energy — nagbabago lang ito ng anyo (energy transformation). Halimbawa, sa flashlight, ang chemical energy ng baterya ay nagiging electrical energy, tapos light at heat. Nananatiling pareho ang kabuuang dami ng energy.", "en": "Energy is not created or destroyed — it only changes form (energy transformation). For example, in a flashlight the battery's chemical energy becomes electrical energy, then light and heat. The total amount of energy stays the same.", "bis": "Dili mahimo o mawala ang energy — mausab lang kini og porma (energy transformation). Pananglitan, sa flashlight, ang chemical energy sa baterya mahimong electrical energy, dayon light ug heat. Magpabilin nga parehas ang kinatibuk-ang gidaghanon sa energy."}, "source": "NRC PS3.B; AAAS BSL Ch.4E", "generator": "claude", "reviewed": false},
  {"id": "fme-heat-transfer-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "heat transfer", "grades": [6, 7], "terms": ["heat", "conduction", "convection", "radiation", "kumukulong", "kutsarang", "dikitang", "pagdikit", "nagbukal", "kutsara", "sopas", "sabaw", "paraan", "paagi"], "fact": {"tl": "Ang init (heat) ay dumadaloy mula sa mas mainit papunta sa mas malamig sa tatlong paraan: conduction (sa pamamagitan ng dikitang tulad ng kutsarang umiinit sa mainit na sopas), convection (sa pamamagitan ng gumagalaw na likido o gas tulad ng kumukulong tubig), at radiation (sa pamamagitan ng sinag tulad ng init ng araw).", "en": "Heat flows from hotter to cooler in three ways: conduction (through contact, like a spoon heating in hot soup), convection (through moving liquid or gas, like boiling water), and radiation (through rays, like the sun's warmth).", "bis": "Ang kainit (heat) moagos gikan sa mas init paingon sa mas bugnaw sa tulo ka paagi: conduction (pinaagi sa pagdikit sama sa kutsara nga moinit sa init nga sabaw), convection (pinaagi sa naglihok nga likido o gas sama sa nagbukal nga tubig), ug radiation (pinaagi sa silaw sama sa kainit sa adlaw)."}, "source": "NRC PS3.B; AAAS BSL Ch.4E", "generator": "claude", "reviewed": false},
  {"id": "fme-light-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "light", "grades": [4, 5, 6], "terms": ["light", "reflection", "shadow", "straight line", "napakabilis", "nakakakita", "maharang", "puwede", "line", "mabalik", "tuwid", "makakita", "motama", "anino"], "fact": {"tl": "Ang light ay isang anyo ng energy na naglalakbay nang tuwid (straight line). Kapag tumama ito sa bagay, puwede itong mabalik (reflection) — kaya tayo nakakakita; o maharang — kaya nabubuo ang anino (shadow). Naglalakbay nang napakabilis ang liwanag.", "en": "Light is a form of energy that travels in straight lines. When it hits an object it can bounce back (reflection) — which is how we see — or be blocked, which forms a shadow. Light travels extremely fast.", "bis": "Ang light usa ka porma sa energy nga mobaktas nga tul-id (straight line). Kung motama kini sa butang, mahimo kining mobalik (reflection) — mao nga makakita ta; o ma-ali — mao nga maporma ang anino (shadow). Mobaktas og paspas kaayo ang kahayag."}, "source": "NRC PS4.B; AAAS BSL Ch.4F", "generator": "claude", "reviewed": false},
  {"id": "fme-sound-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "sound", "grades": [4, 5, 6], "terms": ["sound", "vibration", "pitch", "loudness", "paggalaw", "malaki", "naglalakbay", "dalunggan", "mobaktas", "tainga", "pabalik", "lihok", "tingog", "tunog"], "fact": {"tl": "Ang sound (tunog) ay nabubuo ng vibration (paggalaw pabalik-balik) ng isang bagay, at naglalakbay ito sa hangin, tubig, o solid papunta sa ating tainga. Mas mataas ang pitch kapag mas mabilis ang vibration; mas malakas ang tunog kapag mas malaki ang vibration.", "en": "Sound is made by the vibration (back-and-forth movement) of an object, and it travels through air, water, or solids to our ears. The pitch is higher when the vibration is faster; the sound is louder when the vibration is bigger.", "bis": "Ang sound (tingog) maporma sa vibration (lihok balik-balik) sa usa ka butang, ug mobaktas kini sa hangin, tubig, o solid paingon sa atong dalunggan. Mas taas ang pitch kung mas paspas ang vibration; mas kusog ang tingog kung mas dako ang vibration."}, "source": "NRC PS4.A; AAAS BSL Ch.4F", "generator": "claude", "reviewed": false},
  {"id": "fme-electricity-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "electricity and circuits", "grades": [5, 6, 7], "terms": ["electricity", "circuit", "conductor", "insulator", "kaluwasan", "saradong", "sirado", "nagpapadaloy", "ligtas", "goma", "magpadala", "labas", "wire", "plastik"], "fact": {"tl": "Dumadaloy ang kuryente (electric current) sa isang saradong circuit. Ang conductors (tulad ng metal) ay nagpapadaloy ng kuryente; ang insulators (tulad ng goma at plastik) ay hindi. Kaya ang mga wire ay metal sa loob at goma sa labas para ligtas.", "en": "Electric current flows through a closed circuit. Conductors (like metal) let electricity flow; insulators (like rubber and plastic) do not. That is why wires are metal inside and rubber outside, for safety.", "bis": "Moagos ang kuryente (electric current) sa usa ka sirado nga circuit. Ang conductors (sama sa metal) magpadala og kuryente; ang insulators (sama sa goma ug plastik) dili. Mao nga ang mga wire metal sa sulod ug goma sa gawas alang sa kaluwasan."}, "source": "NRC PS3.A; AAAS BSL Ch.4G", "generator": "claude", "reviewed": false},
  {"id": "fme-magnetism-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "magnetism", "grades": [4, 5, 6], "terms": ["magnet", "poles", "attract", "repel", "magkaparehong", "naghihilahan", "nagtutulakan", "magkaparehas", "magtuloday", "magbiraay", "magkasumpaki", "magkaibang", "dulo", "tumoy"], "fact": {"tl": "Ang magnet ay humihila (attract) ng mga bagay na gawa sa bakal o iron. May dalawang dulo ito na tinatawag na poles (north at south). Ang magkaibang poles ay naghihilahan (attract), pero ang magkaparehong poles ay nagtutulakan (repel).", "en": "A magnet attracts objects made of iron. It has two ends called poles (north and south). Opposite poles attract each other, but like poles push each other away (repel).", "bis": "Ang magnet mobira (attract) sa mga butang nga hinimo sa puthaw o iron. Adunay duha kini ka tumoy nga gitawag og poles (north ug south). Ang magkasumpaki nga poles magbiraay (attract), apan ang magkaparehas nga poles magtuloday (repel)."}, "source": "NRC PS2.B; AAAS BSL Ch.4G", "generator": "claude", "reviewed": false},
  {"id": "fme-balanced-unbalanced-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "balanced and unbalanced forces", "grades": [8, 9, 10], "terms": ["balanced force", "unbalanced force", "Newton", "acceleration", "magkapantay", "lumiliko", "batayan", "basihan", "hunong", "moliko", "balaod", "tigil", "batas", "magkasalungat"], "fact": {"tl": "Kapag balanced (magkapantay at magkasalungat) ang mga force sa isang bagay, hindi nagbabago ang galaw nito — nananatiling tigil o pareho ang bilis. Kapag unbalanced (may panig na mas malakas), nagbabago ang galaw: bumibilis, bumabagal, o lumiliko. Ito ang batayan ng mga batas ni Newton.", "en": "When the forces on an object are balanced (equal and opposite), its motion does not change — it stays still or keeps the same speed. When forces are unbalanced (one side stronger), the motion changes: it speeds up, slows down, or turns. This is the basis of Newton's laws.", "bis": "Kung balanced (managsama ug magkasumpaki) ang mga force sa usa ka butang, dili mausab ang lihok niini — magpabilin nga hunong o parehas ang katulin. Kung unbalanced (adunay kilid nga mas kusog), mausab ang lihok: mopaspas, mohinay, o moliko. Mao kini ang basihan sa mga balaod ni Newton."}, "source": "NRC PS2.A; AAAS BSL Ch.4F", "generator": "claude", "reviewed": false},
  {"id": "fme-work-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "work", "grades": [8, 9, 10], "terms": ["work", "force", "distance", "energy", "nagpagalaw", "naglilipat", "nagaganap", "magbalhin", "nagagawa", "itinulak", "kalakas", "nabuhat", "makapalihok", "paggawa"], "fact": {"tl": "Sa science, may work na nagaganap kapag ang isang force ay nagpagalaw ng bagay sa isang layo (distance) sa direksyon ng force. Kung hindi gumalaw ang bagay, walang work na nagagawa kahit gaano kalakas ang itinulak mo. Ang paggawa ng work ay naglilipat ng energy.", "en": "In science, work is done when a force moves an object over a distance in the direction of the force. If the object does not move, no work is done no matter how hard you push. Doing work transfers energy.", "bis": "Sa science, adunay work nga mahitabo kung ang usa ka force makapalihok sa butang sa usa ka gilay-on (distance) sa direksyon sa force. Kung wala molihok ang butang, walay work nga nabuhat bisan unsa ka kusog ang imong gitulod. Ang paghimo og work magbalhin og energy."}, "source": "NRC PS3.C; AAAS BSL Ch.4E", "generator": "claude", "reviewed": false},
  {"id": "earth-weather-climate-g4", "domain": "EARTH_SPACE", "topic": "weather and climate", "grades": [4, 5, 6], "terms": ["weather", "climate", "temperature", "rainfall", "himpapawid", "kahanginan", "kalagayan", "naandang", "ting", "karaniwang", "kahimtang", "mahabang", "klima", "taon"], "fact": {"tl": "Ang weather (panahon) ay ang kalagayan ng himpapawid sa isang araw — init, ulan, hangin, ulap. Ang climate (klima) ay ang karaniwang weather ng isang lugar sa mahabang panahon. Halimbawa, ang Pilipinas ay may tropical na climate: mainit buong taon, may tag-init at tag-ulan.", "en": "Weather is the state of the air on a given day — heat, rain, wind, clouds. Climate is the usual weather of a place over a long time. For example, the Philippines has a tropical climate: hot all year, with a dry season and a rainy season.", "bis": "Ang weather (panahon) mao ang kahimtang sa kahanginan sa usa ka adlaw — init, ulan, hangin, panganod. Ang climate (klima) mao ang naandang weather sa usa ka dapit sa taas nga panahon. Pananglitan, ang Pilipinas adunay tropical nga climate: init tibuok tuig, adunay ting-init ug ting-ulan."}, "source": "NRC ESS2.D; AAAS BSL Ch.4B", "generator": "claude", "reviewed": false},
  {"id": "earth-soil-g4", "domain": "EARTH_SPACE", "topic": "rocks and soil", "grades": [4, 5], "terms": ["soil", "rock", "sand", "clay", "humus", "pagpatubo", "hinaluan", "magtanim", "kolonon", "dugmok", "bulok", "luwad", "dunot", "kakayahang", "katakos"], "fact": {"tl": "Ang lupa (soil) ay nabubuo sa mahabang panahon mula sa durog na bato na hinaluan ng bulok na halaman at hayop (humus). May iba't ibang uri ang lupa tulad ng buhangin (sandy), luwad (clay), at loam, at iba-iba ang kakayahang magtanim dahil sa laki ng butil at sustansya.", "en": "Soil forms over a long time from broken-down rock mixed with decayed plants and animals (humus). There are different kinds of soil such as sandy, clay, and loam, and they differ in how well plants grow because of particle size and nutrients.", "bis": "Ang yuta (soil) maporma sa taas nga panahon gikan sa dugmok nga bato nga gisagolan og dunot nga tanom ug hayop (humus). Adunay nagkalainlaing klase ang yuta sama sa balas (sandy), kolonon (clay), ug loam, ug lainlain ang katakos sa pagpatubo tungod sa gidak-on sa lugas ug sustansya."}, "source": "NRC ESS2.A; AAAS BSL Ch.4C", "generator": "claude", "reviewed": false},
  {"id": "earth-rock-cycle-g6", "domain": "EARTH_SPACE", "topic": "types of rocks", "grades": [6, 7], "terms": ["igneous", "sedimentary", "metamorphic", "rock cycle", "nibugnaw", "tumigas", "magbago", "natapok", "nabago", "nigahi", "nausab", "putik", "napakahabang", "naipong"], "fact": {"tl": "May tatlong uri ng bato: igneous (mula sa lumamig na lava o magma), sedimentary (mula sa naipong layer ng buhangin at putik na tumigas), at metamorphic (bato na nabago dahil sa init at presyon). Sa rock cycle, puwedeng magbago ang isang uri ng bato sa iba sa napakahabang panahon.", "en": "There are three kinds of rock: igneous (from cooled lava or magma), sedimentary (from layers of sand and mud that hardened), and metamorphic (rock changed by heat and pressure). In the rock cycle, one kind can change into another over very long times.", "bis": "Adunay tulo ka klase sa bato: igneous (gikan sa nibugnaw nga lava o magma), sedimentary (gikan sa natapok nga layer sa balas ug lapok nga nigahi), ug metamorphic (bato nga nausab tungod sa kainit ug presyur). Sa rock cycle, mahimong mausab ang usa ka klase sa bato ngadto sa lain sa taas kaayo nga panahon."}, "source": "NRC ESS2.A; AAAS BSL Ch.4C", "generator": "claude", "reviewed": false},
  {"id": "earth-weathering-erosion-g5", "domain": "EARTH_SPACE", "topic": "weathering and erosion", "grades": [5, 6], "terms": ["weathering", "erosion", "wind", "water", "pagkadugmok", "pagkadurog", "nadugmok", "nagaagas", "pagbalhin", "paglipat", "paglipas", "paglabay", "durog", "lamig"], "fact": {"tl": "Ang weathering ay ang unti-unting pagkadurog ng bato sa maliliit na piraso dahil sa tubig, hangin, init, at lamig. Ang erosion naman ay ang paglipat ng mga durog na bato at lupa papunta sa ibang lugar dahil sa umaagos na tubig, hangin, o yelo. Kaya nagbabago ang hugis ng lupa sa paglipas ng panahon.", "en": "Weathering is the slow breaking of rock into smaller pieces by water, wind, heat, and cold. Erosion is the moving of broken rock and soil to other places by flowing water, wind, or ice. This is why the shape of the land changes over time.", "bis": "Ang weathering mao ang hinay-hinay nga pagkadugmok sa bato ngadto sa gagmay nga piraso tungod sa tubig, hangin, init, ug bugnaw. Ang erosion mao ang pagbalhin sa nadugmok nga bato ug yuta ngadto sa laing dapit tungod sa nagaagas nga tubig, hangin, o yelo. Mao nga mausab ang porma sa yuta sa paglabay sa panahon."}, "source": "NRC ESS2.A; AAAS BSL Ch.4C", "generator": "claude", "reviewed": false},
  {"id": "earth-landforms-g4", "domain": "EARTH_SPACE", "topic": "landforms", "grades": [4, 5], "terms": ["landform", "mountain", "valley", "plain", "plateau"], "fact": {"tl": "Ang landforms ay ang iba't ibang hugis ng ibabaw ng lupa: bundok (mountain), lambak (valley), kapatagan (plain), talampas (plateau), at burol (hill). Nabubuo ang mga ito sa napakahabang panahon dahil sa galaw ng Earth, bulkan, at weathering at erosion.", "en": "Landforms are the different shapes of the land's surface: mountains, valleys, plains, plateaus, and hills. They form over very long times because of the Earth's movements, volcanoes, and weathering and erosion.", "bis": "Ang landforms mao ang nagkalainlaing porma sa nawong sa yuta: bukid (mountain), walog (valley), kapatagan (plain), talampas (plateau), ug bungtod (hill). Maporma kini sa taas kaayo nga panahon tungod sa lihok sa Earth, bulkan, ug weathering ug erosion."}, "source": "NRC ESS2.B; AAAS BSL Ch.4C", "generator": "claude", "reviewed": false},
  {"id": "earth-plate-tectonics-g7", "domain": "EARTH_SPACE", "topic": "earthquakes and volcanoes", "grades": [7, 8], "terms": ["plate tectonics", "earthquake", "volcano", "fault"], "fact": {"tl": "Ang panlabas na bahagi ng Earth ay nahahati sa malalaking piraso na tinatawag na plates na dahan-dahang gumagalaw. Kapag nagkiskisan o nagbanggaan ang mga plate, nagkakaroon ng lindol (earthquake) at bulkan (volcano). Ang Pilipinas ay nasa Pacific Ring of Fire kaya madalas itong magkalindol at may maraming bulkan.", "en": "The Earth's outer layer is broken into large pieces called plates that move slowly. When plates rub or collide, earthquakes and volcanoes occur. The Philippines sits on the Pacific Ring of Fire, so it has frequent earthquakes and many volcanoes.", "bis": "Ang gawas nga bahin sa Earth nabahin sa dagkong piraso nga gitawag og plates nga hinay nga molihok. Kung magkuskos o magbangga ang mga plate, adunay linog (earthquake) ug bulkan (volcano). Ang Pilipinas anaa sa Pacific Ring of Fire mao nga kanunay kining maglinog ug daghang bulkan."}, "source": "NRC ESS2.B; AAAS BSL Ch.4C", "generator": "claude", "reviewed": false},
  {"id": "earth-structure-g7", "domain": "EARTH_SPACE", "topic": "earth's structure", "grades": [7, 8], "terms": ["crust", "mantle", "core", "layers", "kinatatayuan", "pinakaloob", "gibarogan", "malagkit", "kinasuloran", "napakainit", "panlabas", "pangunahing", "matigas", "layer"], "fact": {"tl": "Ang Earth ay may tatlong pangunahing layer: ang crust (ang manipis at matigas na panlabas na balat na kinatatayuan natin), ang mantle (mainit at malagkit na bato sa ilalim), at ang core (ang pinakaloob, gawa sa metal, na napakainit).", "en": "The Earth has three main layers: the crust (the thin, hard outer shell we live on), the mantle (hot, thick rock below it), and the core (the innermost part, made of metal, that is extremely hot).", "bis": "Ang Earth adunay tulo ka nag-unang layer: ang crust (ang nipis ug gahi nga gawas nga panit nga atong gibarogan), ang mantle (init ug baga nga bato sa ilalom), ug ang core (ang kinasuloran, hinimo sa metal, nga init kaayo)."}, "source": "NRC ESS2.A; AAAS BSL Ch.4C", "generator": "claude", "reviewed": false},
  {"id": "earth-atmosphere-g6", "domain": "EARTH_SPACE", "topic": "the atmosphere", "grades": [6, 7], "terms": ["atmosphere", "air", "oxygen", "layers", "nakakasamang", "pinipigilan", "naglangkob", "naglibot", "mopugong", "nakapaligid", "naglalaman", "hinihinga", "nagpoprotekta", "kabugnaw"], "fact": {"tl": "Ang atmosphere ay ang makapal na hangin na nakapaligid sa Earth. Naglalaman ito ng oxygen na hinihinga natin, pinipigilan ang sobrang init at lamig, at nagpoprotekta sa atin mula sa nakakasamang sinag ng araw. Nahahati ito sa mga layer.", "en": "The atmosphere is the thick layer of air surrounding the Earth. It holds the oxygen we breathe, keeps the planet from getting too hot or cold, and protects us from harmful rays of the sun. It is divided into layers.", "bis": "Ang atmosphere mao ang baga nga hangin nga naglibot sa Earth. Naglangkob kini og oxygen nga atong giginhawa, mopugong sa sobra nga kainit ug kabugnaw, ug manalipod kanato gikan sa makadaot nga silaw sa adlaw. Nabahin kini sa mga layer."}, "source": "NRC ESS2.D; AAAS BSL Ch.4B", "generator": "claude", "reviewed": false},
  {"id": "earth-solar-system-g4", "domain": "EARTH_SPACE", "topic": "solar system", "grades": [4, 5, 6], "terms": ["solar system", "planet", "sun", "orbit", "pinagmumulan", "tinubdan", "siyang", "gilangkoban", "binubuo", "walong", "walo", "bituin", "bituon", "planeta"], "fact": {"tl": "Ang solar system ay binubuo ng Araw (Sun) at ng walong planeta na umiikot (orbit) dito: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, at Neptune. Ang Araw ay isang bituin (star) na siyang pinagmumulan ng liwanag at init para sa atin.", "en": "The solar system is made of the Sun and the eight planets that orbit it: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, and Neptune. The Sun is a star, and it is the source of our light and heat.", "bis": "Ang solar system gilangkoban sa Adlaw (Sun) ug sa walo ka planeta nga molibot (orbit) niini: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, ug Neptune. Ang Adlaw usa ka bituon (star) nga maoy tinubdan sa atong kahayag ug kainit."}, "source": "NRC ESS1.B; AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "earth-day-night-seasons-g5", "domain": "EARTH_SPACE", "topic": "day night and seasons", "grades": [4, 5, 6], "terms": ["rotation", "revolution", "day", "night", "seasons"], "fact": {"tl": "Umiikot (rotation) ang Earth sa sarili nitong axis isang beses kada araw — kaya may araw (day) sa bahaging nakaharap sa Araw at gabi (night) sa kabila. Umiikot din ito sa Araw (revolution) isang beses kada taon, at dahil sa pagkakatagilid ng Earth, nagkakaroon ng iba't ibang panahon (seasons).", "en": "The Earth rotates on its axis once a day — so there is daytime on the side facing the Sun and night on the other. It also revolves around the Sun once a year, and because the Earth is tilted, this causes the different seasons.", "bis": "Molibot (rotation) ang Earth sa kaugalingong axis niini kausa matag adlaw — mao nga adunay adlaw (day) sa bahin nga nag-atubang sa Adlaw ug gabii (night) sa pikas. Molibot usab kini sa Adlaw (revolution) kausa matag tuig, ug tungod sa pagkahilig sa Earth, adunay nagkalainlaing panahon (seasons)."}, "source": "NRC ESS1.B; AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "earth-moon-phases-g5", "domain": "EARTH_SPACE", "topic": "phases of the moon", "grades": [5, 6], "terms": ["moon", "phases", "reflect", "orbit", "naliliwanagang", "nabubuwelta", "nalamdagan", "kabilugan", "nibalik", "kalaki", "kadako", "takdol", "kalahati", "katunga"], "fact": {"tl": "Walang sariling liwanag ang buwan (moon) — ang nakikita nating liwanag nito ay sinag ng Araw na nabubuwelta dito. Habang umiikot ang buwan sa Earth, nagbabago kung gaano kalaki ang naliliwanagang bahagi na nakaharap sa atin — kaya may iba't ibang phases (bagong buwan, kalahati, kabilugan).", "en": "The Moon has no light of its own — the light we see from it is sunlight reflecting off it. As the Moon orbits the Earth, the lit part facing us changes in size — which is why it has phases (new moon, half, full).", "bis": "Walay kaugalingong kahayag ang bulan (moon) — ang atong makita nga kahayag niini kay silaw sa Adlaw nga nibalik niini. Samtang molibot ang bulan sa Earth, mausab kung unsa kadako ang nalamdagan nga bahin nga nag-atubang kanato — mao nga adunay nagkalainlaing phases (bag-ong bulan, katunga, takdol)."}, "source": "NRC ESS1.B; AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "earth-eclipses-g6", "domain": "EARTH_SPACE", "topic": "eclipses", "grades": [6, 7], "terms": ["eclipse", "solar", "lunar", "shadow", "nagkakahanay", "mongitngit", "umiilim", "magsa", "humaharang", "umaga", "moali", "tumatama", "motama", "anino"], "fact": {"tl": "Nagkakaroon ng eclipse kapag nagkakahanay ang Araw, Earth, at buwan. Sa solar eclipse, ang buwan ang humaharang sa Araw kaya umiilim ang araw sa umaga. Sa lunar eclipse, ang Earth ang nasa gitna kaya tumatama ang anino nito sa buwan.", "en": "An eclipse happens when the Sun, Earth, and Moon line up. In a solar eclipse, the Moon blocks the Sun, darkening the daytime. In a lunar eclipse, the Earth is in the middle, so its shadow falls on the Moon.", "bis": "Adunay eclipse kung magsa-ad ang Adlaw, Earth, ug bulan. Sa solar eclipse, ang bulan ang moali sa Adlaw mao nga mongitngit ang adlaw. Sa lunar eclipse, ang Earth ang anaa sa tunga mao nga motama ang anino niini sa bulan."}, "source": "NRC ESS1.B; AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "earth-stars-galaxies-g7", "domain": "EARTH_SPACE", "topic": "stars and galaxies", "grades": [7, 8], "terms": ["star", "galaxy", "universe", "light-year", "napakalalaking", "napakalaking", "nagdilaab", "bilyong", "bilyon", "aapoy", "dagko", "tila", "napakalayo", "nilang"], "fact": {"tl": "Ang mga bituin (stars) ay napakalalaking bola ng nag-aapoy na gas na naglalabas ng sarili nilang liwanag at init — tulad ng ating Araw. Ang galaxy ay napakalaking grupo ng bilyon-bilyong bituin; ang ating galaxy ay tinatawag na Milky Way. Napakalayo ng mga bituin kaya tila maliit lang sila sa langit.", "en": "Stars are enormous balls of burning gas that give off their own light and heat — like our Sun. A galaxy is a huge group of billions of stars; our galaxy is called the Milky Way. Stars are so far away that they look tiny in the sky.", "bis": "Ang mga bituon (stars) dagko kaayong bola sa nagdilaab nga gas nga mobuga sa ilang kaugalingong kahayag ug kainit — sama sa atong Adlaw. Ang galaxy dako kaayong grupo sa bilyon-bilyon ka bituon; ang atong galaxy gitawag og Milky Way. Layo kaayo ang mga bituon mao nga morag gagmay lang sila sa langit."}, "source": "NRC ESS1.A; AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "earth-natural-resources-g5", "domain": "EARTH_SPACE", "topic": "natural resources", "grades": [5, 6], "terms": ["natural resources", "renewable", "nonrenewable", "conservation", "nababalik", "dali", "kinaiyahan", "kalikasan", "mineral", "nauubos", "mahurot", "mabalik", "iingat", "amping"], "fact": {"tl": "Ang natural resources ay ang mga bagay mula sa kalikasan na ginagamit natin: tubig, hangin, lupa, kahoy, at mineral. May renewable na nababalik (tulad ng araw at hangin) at may nonrenewable na nauubos at hindi agad nababalik (tulad ng langis at karbon). Kaya mahalaga ang pag-iingat (conservation).", "en": "Natural resources are things from nature that we use: water, air, soil, wood, and minerals. Some are renewable and replenish (like sun and wind), and some are nonrenewable and run out and are not easily replaced (like oil and coal). That is why conservation matters.", "bis": "Ang natural resources mao ang mga butang gikan sa kinaiyahan nga atong gigamit: tubig, hangin, yuta, kahoy, ug mineral. Adunay renewable nga mobalik (sama sa adlaw ug hangin) ug adunay nonrenewable nga mahurot ug dili dali mabalik (sama sa lana ug karbon). Mao nga importante ang pag-amping (conservation)."}, "source": "NRC ESS3.A; AAAS BSL Ch.4C", "generator": "claude", "reviewed": false},
  {"id": "earth-climate-change-g8", "domain": "EARTH_SPACE", "topic": "climate change", "grades": [8, 9, 10], "terms": ["climate change", "greenhouse effect", "carbon dioxide", "global warming", "nagpapanatiling", "matinding", "maghupot", "mokusog", "grabe", "lumalakas", "umiinit", "karbon", "kalibutan", "pagsunog"], "fact": {"tl": "Ang ilang gas sa atmosphere (tulad ng carbon dioxide) ay humuhuli ng init mula sa araw — ang greenhouse effect, na nagpapanatiling mainit-init ang Earth. Pero dahil sa sobrang carbon dioxide mula sa pagsunog ng langis at karbon ng tao, lumalakas ito at unti-unting umiinit ang mundo (climate change), na nagdudulot ng mas matinding panahon.", "en": "Some gases in the atmosphere (like carbon dioxide) trap heat from the sun — the greenhouse effect, which keeps the Earth warm. But because of too much carbon dioxide from humans burning oil and coal, this strengthens and the world slowly warms (climate change), causing more extreme weather.", "bis": "Ang ubang gas sa atmosphere (sama sa carbon dioxide) modakop og kainit gikan sa adlaw — ang greenhouse effect, nga maghupot sa Earth nga init-init. Apan tungod sa sobra nga carbon dioxide gikan sa pagsunog sa lana ug karbon sa tawo, mokusog kini ug hinay-hinay nga moinit ang kalibutan (climate change), nga maghatag og mas grabe nga panahon."}, "source": "NRC ESS3.D; AAAS BSL Ch.4B", "generator": "claude", "reviewed": false},
  {"id": "val-water-boiling-freezing", "domain": "MATTER", "topic": "boiling and freezing point of water", "grades": [4, 5, 6], "terms": ["boiling point", "freezing point", "water", "temperature", "Celsius", "Fahrenheit", "tabing", "kumukulo", "naandang", "mobukal", "karaniwang", "baybayon", "purong", "putli", "nagyeyelo", "dagat"], "fact": {"tl": "Ang purong tubig ay kumukulo sa 100°C (212°F) at nagyeyelo sa 0°C (32°F) sa karaniwang air pressure sa tabing-dagat.", "en": "Pure water boils at 100°C (212°F) and freezes at 0°C (32°F) at normal sea-level air pressure.", "bis": "Ang putli nga tubig mobukal sa 100°C (212°F) ug mo-yelo sa 0°C (32°F) sa naandang air pressure sa baybayon."}, "source": "AAAS BSL Ch.4D (reference value)", "generator": "claude", "reviewed": false},
  {"id": "val-temperature-scales", "domain": "MATTER", "topic": "temperature scales", "grades": [6, 7, 8], "terms": ["temperature", "Celsius", "Fahrenheit", "convert", "sinusukat", "kumukulo", "gisukod", "mobukal", "nagyeyelo", "temperatura", "yelo"], "fact": {"tl": "Sinusukat ang temperatura sa Celsius (°C) o Fahrenheit (°F). Ang tubig ay nagyeyelo sa 0°C = 32°F at kumukulo sa 100°C = 212°F.", "en": "Temperature is measured in Celsius (°C) or Fahrenheit (°F). Water freezes at 0°C = 32°F and boils at 100°C = 212°F.", "bis": "Gisukod ang temperatura sa Celsius (°C) o Fahrenheit (°F). Ang tubig mo-yelo sa 0°C = 32°F ug mobukal sa 100°C = 212°F."}, "source": "AAAS BSL Ch.4D (reference value)", "generator": "claude", "reviewed": false},
  {"id": "val-room-temperature", "domain": "MATTER", "topic": "room temperature", "grades": [4, 5, 6], "terms": ["room temperature", "temperature", "komportableng", "komportable"], "fact": {"tl": "Ang komportableng room temperature ay mga 20–25°C (68–77°F).", "en": "Comfortable room temperature is about 20–25°C (68–77°F).", "bis": "Ang komportable nga room temperature mga 20–25°C (68–77°F)."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-air-composition", "domain": "EARTH_SPACE", "topic": "composition of air", "grades": [5, 6, 7], "terms": ["air", "nitrogen", "oxygen", "atmosphere", "hinihinga", "giginhawa", "mabuhay", "karamihan", "mabuhi", "kasagaran", "ubang", "gigamit", "ginagamit", "ibang"], "fact": {"tl": "Ang hangin na hinihinga natin ay karamihan nitrogen (mga 78%) at oxygen (mga 21%); mga 1% na lang ang ibang gas. Ang oxygen ang ginagamit natin para mabuhay.", "en": "The air we breathe is mostly nitrogen (about 78%) and oxygen (about 21%); only about 1% is other gases. We use the oxygen to live.", "bis": "Ang hangin nga atong giginhawa kasagaran nitrogen (mga 78%) ug oxygen (mga 21%); mga 1% na lang ang ubang gas. Ang oxygen ang atong gigamit aron mabuhi."}, "source": "AAAS BSL Ch.4B (reference value)", "generator": "claude", "reviewed": false},
  {"id": "val-body-temperature", "domain": "LIVING_THINGS", "topic": "body temperature", "grades": [4, 5, 6], "terms": ["body temperature", "fever", "health", "temperaturang", "hilanat", "lagnat", "malusog", "himsog", "temperatura", "mataas", "tawo", "tinatawag", "gitawag"], "fact": {"tl": "Ang malusog na temperatura ng katawan ng tao ay mga 37°C (98.6°F). Ang temperaturang mas mataas dito ay tinatawag na lagnat (fever).", "en": "A healthy human body temperature is about 37°C (98.6°F). A temperature much higher than this is a fever.", "bis": "Ang himsog nga temperatura sa lawas sa tawo mga 37°C (98.6°F). Ang temperatura nga mas taas pa niini gitawag og hilanat (fever)."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-human-bones", "domain": "LIVING_THINGS", "topic": "number of bones", "grades": [4, 5, 6], "terms": ["bones", "skeleton", "body", "ipinapanganak", "nagsasanib", "magtapot", "sanggol", "masuso", "natawo", "ilan", "matandang", "bukog", "hamtong"], "fact": {"tl": "Ang katawan ng matandang tao ay may 206 na buto. Ang mga sanggol ay ipinapanganak na may mga 300 na buto, at ang ilan ay nagsasanib habang lumalaki.", "en": "An adult human body has 206 bones. Babies are born with about 300, and some fuse together as they grow.", "bis": "Ang lawas sa hamtong nga tawo adunay 206 ka bukog. Ang mga masuso natawo nga adunay mga 300 ka bukog, ug ang uban magtapot samtang motubo."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-human-teeth", "domain": "LIVING_THINGS", "topic": "number of teeth", "grades": [3, 4, 5], "terms": ["teeth", "milk teeth", "permanent teeth", "permanenteng", "permanente", "matatanda", "kasama", "ngipin", "ngipon", "gatas", "lakip", "bata", "hamtong"], "fact": {"tl": "Ang mga bata ay may 20 na gatas na ngipin (milk teeth); ang matatanda ay may 32 na permanenteng ngipin (kasama ang wisdom teeth).", "en": "Children have 20 milk teeth; adults have 32 permanent teeth (including the wisdom teeth).", "bis": "Ang mga bata adunay 20 ka gatas nga ngipon (milk teeth); ang mga hamtong adunay 32 ka permanente nga ngipon (lakip ang wisdom teeth)."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-heart-rate", "domain": "LIVING_THINGS", "topic": "heart rate", "grades": [5, 6, 7], "terms": ["heart rate", "pulse", "beats per minute", "tumitibok", "mopitik", "nakapahingang", "tibok", "pitik", "kasingkasing", "nagpahulay", "matanda", "minuto", "puso"], "fact": {"tl": "Ang puso ng nakapahingang matanda ay tumitibok nang mga 60–100 beses kada minuto; mas mabilis ang tibok ng puso ng bata.", "en": "A resting adult heart beats about 60–100 times per minute; a child's heart beats faster.", "bis": "Ang kasingkasing sa nagpahulay nga hamtong mopitik mga 60–100 ka beses kada minuto; mas paspas ang pitik sa kasingkasing sa bata."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-breathing-rate", "domain": "LIVING_THINGS", "topic": "breathing rate", "grades": [5, 6, 7], "terms": ["breathing rate", "respiration", "nakapahingang", "nagpahulay", "minuto", "humihinga", "moginhawa", "beses", "kada", "tawo"], "fact": {"tl": "Ang nakapahingang tao ay humihinga nang mga 12–20 beses kada minuto.", "en": "A resting person breathes about 12–20 times per minute.", "bis": "Ang nagpahulay nga tawo moginhawa mga 12–20 ka beses kada minuto."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-body-water", "domain": "LIVING_THINGS", "topic": "body is mostly water", "grades": [4, 5, 6], "terms": ["water", "body", "percent", "napakahalaga", "mahigit", "kapin", "inom", "kalahati", "katunga", "matandang", "hamtong", "importante", "tawo"], "fact": {"tl": "Mga 60% ng katawan ng matandang tao ay tubig — mahigit kalahati! Kaya napakahalaga ng pag-inom ng tubig.", "en": "About 60% of an adult human body is water — more than half! That is why drinking water is so important.", "bis": "Mga 60% sa lawas sa hamtong nga tawo kay tubig — kapin sa katunga! Mao nga importante kaayo ang pag-inom og tubig."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-blood-volume", "domain": "LIVING_THINGS", "topic": "blood volume", "grades": [6, 7], "terms": ["blood", "liters", "body", "litro", "matandang", "hamtong", "dugo", "tawo"], "fact": {"tl": "Ang katawan ng matandang tao ay may mga 5 litro ng dugo.", "en": "An adult human body has about 5 liters of blood.", "bis": "Ang lawas sa hamtong nga tawo adunay mga 5 ka litro nga dugo."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-largest-organ-skin", "domain": "LIVING_THINGS", "topic": "largest organ", "grades": [5, 6], "terms": ["skin", "organ", "largest", "pinoprotektahan", "pinakamalaking", "pagkontrol", "makabati", "paghikap", "kinadak", "hipo", "pakiramdam", "magtugot", "temperatura"], "fact": {"tl": "Ang balat ang pinakamalaking organ ng katawan. Pinoprotektahan nito ang katawan, tumutulong sa pagkontrol ng temperatura, at nagbibigay-daan sa pakiramdam ng hipo.", "en": "The skin is the body's largest organ. It protects the body, helps control temperature, and lets us feel touch.", "bis": "Ang panit mao ang kinadak-ang organ sa lawas. Manalipod kini sa lawas, motabang sa pagkontrol sa temperatura, ug magtugot kanato nga makabati sa paghikap."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-speed-of-light", "domain": "FORCE_MOTION_ENERGY", "topic": "speed of light", "grades": [6, 7, 8], "terms": ["speed of light", "fast", "kilometers", "pinakamabilis", "sansinukob", "uniberso", "milya", "segundo", "kilometro", "labing", "naglalakbay", "mobaktas", "kada"], "fact": {"tl": "Ang liwanag ay naglalakbay nang mga 300,000 kilometro kada segundo (mga 186,000 milya kada segundo) — ang pinakamabilis sa buong sansinukob.", "en": "Light travels about 300,000 kilometers per second (about 186,000 miles per second) — the fastest thing in the universe.", "bis": "Ang kahayag mobaktas mga 300,000 ka kilometro kada segundo (mga 186,000 ka milya kada segundo) — ang labing paspas sa tibuok uniberso."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-speed-of-sound", "domain": "FORCE_MOTION_ENERGY", "topic": "speed of sound", "grades": [6, 7, 8], "terms": ["speed of sound", "thunder", "lightning", "marinig", "metro", "dalugdog", "segundo", "nauuna", "kulog", "madungog", "naglalakbay", "mobaktas", "kidlat"], "fact": {"tl": "Ang tunog ay naglalakbay sa hangin nang mga 343 metro kada segundo (mga 1,235 km/h) — mas mabagal kaysa liwanag, kaya nauuna mong makita ang kidlat bago marinig ang kulog.", "en": "Sound travels through air at about 343 meters per second (about 1,235 km/h) — much slower than light, which is why you see lightning before you hear thunder.", "bis": "Ang tingog mobaktas sa hangin og mga 343 ka metro kada segundo (mga 1,235 km/h) — mas hinay kaysa kahayag, mao nga makita una nimo ang kilat sa dili pa madungog ang dalugdog."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-gravity-moon", "domain": "FORCE_MOTION_ENERGY", "topic": "gravity on the moon", "grades": [6, 7], "terms": ["gravity", "moon", "weight", "makakatalon", "makaambak", "pilo", "didto", "anim", "kang", "unom", "beses", "magaan", "gaan"], "fact": {"tl": "Ang gravity sa buwan ay mga 1/6 lang ng sa Earth, kaya mga anim na beses kang mas magaan doon at mas mataas kang makakatalon.", "en": "The Moon's gravity is only about 1/6 of Earth's, so you would weigh about six times less there and could jump much higher.", "bis": "Ang gravity sa bulan mga 1/6 lang sa Earth, mao nga mga unom ka pilo ka mas gaan didto ug mas taas ka makaambak."}, "source": "reference value; NRC PS2.B", "generator": "claude", "reviewed": false},
  {"id": "val-planets-order", "domain": "EARTH_SPACE", "topic": "order of the planets", "grades": [4, 5, 6], "terms": ["planets", "order", "solar system", "pangatlo", "ikatulo", "kalay", "sumala", "ayon", "layo", "planeta"], "fact": {"tl": "Ang 8 planeta ayon sa layo mula sa Araw: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune. Ang Earth ang pangatlo mula sa Araw.", "en": "The 8 planets in order from the Sun: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune. Earth is the 3rd from the Sun.", "bis": "Ang 8 ka planeta sumala sa kalay-o gikan sa Adlaw: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune. Ang Earth mao ang ikatulo gikan sa Adlaw."}, "source": "AAAS BSL Ch.4A (reference value)", "generator": "claude", "reviewed": false},
  {"id": "val-largest-smallest-planet", "domain": "EARTH_SPACE", "topic": "largest and smallest planet", "grades": [4, 5, 6], "terms": ["Jupiter", "Mercury", "planet", "largest", "smallest", "pinakamalaki", "batuhang", "batoon", "pinakamalaking", "kinagamyan", "kinadak", "pinakamaliit", "planeta"], "fact": {"tl": "Ang Jupiter ang pinakamalaking planeta; ang Mercury ang pinakamaliit. Ang Earth ang pinakamalaki sa mga batuhang (rocky) planeta.", "en": "Jupiter is the largest planet; Mercury is the smallest. Earth is the largest of the rocky planets.", "bis": "Ang Jupiter mao ang kinadak-ang planeta; ang Mercury mao ang kinagamyan. Ang Earth mao ang kinadak-an sa batoon (rocky) nga mga planeta."}, "source": "AAAS BSL Ch.4A (reference value)", "generator": "claude", "reviewed": false},
  {"id": "val-sun-distance", "domain": "EARTH_SPACE", "topic": "distance to the sun", "grades": [6, 7, 8], "terms": ["Sun", "distance", "light minutes", "umaabot", "milyong", "minuto", "milyon", "moabot", "kilometro", "kanato", "atin", "loob", "sulod"], "fact": {"tl": "Ang Araw ay nasa mga 150 milyong kilometro mula sa Earth. Ang liwanag nito ay umaabot sa atin sa loob ng mga 8 minuto.", "en": "The Sun is about 150 million kilometers from Earth. Its light takes about 8 minutes to reach us.", "bis": "Ang Adlaw mga 150 ka milyon ka kilometro gikan sa Earth. Ang kahayag niini moabot kanato sulod sa mga 8 ka minuto."}, "source": "AAAS BSL Ch.4A (reference value)", "generator": "claude", "reviewed": false},
  {"id": "val-moon-distance", "domain": "EARTH_SPACE", "topic": "distance to the moon", "grades": [6, 7], "terms": ["Moon", "distance", "space", "pinakamalapit", "kilometro", "labing", "kawanangan", "kalawakan", "duol", "buwan", "bulan", "kanato", "atin"], "fact": {"tl": "Ang buwan ay nasa mga 384,000 kilometro mula sa Earth — ang pinakamalapit na bagay sa kalawakan sa atin.", "en": "The Moon is about 384,000 kilometers from Earth — the closest object in space to us.", "bis": "Ang bulan mga 384,000 ka kilometro gikan sa Earth — ang labing duol nga butang sa kawanangan kanato."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-earth-day-year", "domain": "EARTH_SPACE", "topic": "earth's day and year", "grades": [4, 5, 6], "terms": ["rotation", "revolution", "day", "year", "kausa", "oras", "beses", "taon", "tuig", "molibot", "umiikot", "loob", "sulod"], "fact": {"tl": "Umiikot ang Earth nang isang beses sa loob ng mga 24 oras (isang araw) at umiikot sa Araw nang isang beses sa loob ng mga 365 araw (isang taon).", "en": "Earth turns once in about 24 hours (one day) and goes around the Sun once in about 365 days (one year).", "bis": "Molibot ang Earth kausa sulod sa mga 24 ka oras (usa ka adlaw) ug molibot sa Adlaw kausa sulod sa mga 365 ka adlaw (usa ka tuig)."}, "source": "AAAS BSL Ch.4A (reference value)", "generator": "claude", "reviewed": false},
  {"id": "val-earth-water-surface", "domain": "EARTH_SPACE", "topic": "earth's surface is mostly water", "grades": [4, 5, 6], "terms": ["water", "surface", "ocean", "blue", "natatakpan", "tingnan", "awon", "gitabonan", "asul", "kawanangan", "kalawakan", "nawong", "itong", "ibabaw"], "fact": {"tl": "Mga 71% ng ibabaw ng Earth ay natatakpan ng tubig, kaya asul itong tingnan mula sa kalawakan.", "en": "About 71% of Earth's surface is covered by water, which is why it looks blue from space.", "bis": "Mga 71% sa nawong sa Earth gitabonan og tubig, mao nga asul kini tan-awon gikan sa kawanangan."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-mars-red", "domain": "EARTH_SPACE", "topic": "why Mars is red", "grades": [4, 5, 6], "terms": ["Mars", "red planet", "iron", "rust", "kinalawang", "gitaya", "mayaman", "mapula", "dato", "puthaw", "bakal", "kolor", "kulay", "tinatawag"], "fact": {"tl": "Ang Mars ay tinatawag na Red Planet dahil ang lupa nito ay mayaman sa bakal (iron) na kinalawang, kaya mapula ang kulay nito.", "en": "Mars is called the Red Planet because its soil is rich in iron that has rusted, giving it a reddish color.", "bis": "Ang Mars gitawag og Red Planet kay ang yuta niini dato sa puthaw (iron) nga gitaya, mao nga mapula ang kolor niini."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-saturn-rings", "domain": "EARTH_SPACE", "topic": "saturn's rings", "grades": [4, 5, 6], "terms": ["Saturn", "rings", "ice", "planet", "maliliwanag", "singsing", "masanag", "nagtuyok", "piraso", "karamihan", "kasagaran", "hinimo", "gawa", "planeta"], "fact": {"tl": "Ang Saturn ay may maliliwanag na singsing (rings) na gawa karamihan sa yelo at piraso ng bato na umiikot sa planeta.", "en": "Saturn has bright rings made mostly of ice and rock pieces orbiting the planet.", "bis": "Ang Saturn adunay masanag nga mga singsing (rings) nga hinimo kasagaran sa yelo ug piraso sa bato nga nagtuyok sa planeta."}, "source": "reference value", "generator": "claude", "reviewed": false},
  {"id": "val-sun-is-star", "domain": "EARTH_SPACE", "topic": "the sun is a star", "grades": [4, 5, 6], "terms": ["Sun", "star", "closest", "mukha", "pinakamalapit", "masanag", "maliwanag", "malaki", "labing", "malapit", "morag", "duol", "bituin"], "fact": {"tl": "Ang Araw ay isang bituin (star) — ang pinakamalapit sa atin. Mukha itong mas malaki at maliwanag kaysa ibang bituin dahil lang mas malapit ito sa atin.", "en": "The Sun is a star — the closest one to us. It looks bigger and brighter than other stars only because it is so much closer.", "bis": "Ang Adlaw usa ka bituon (star) — ang labing duol kanato. Morag mas dako ug masanag kini kaysa ubang bituon tungod lang kay mas duol kini kanato."}, "source": "AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "faq-blue-sky", "domain": "EARTH_SPACE", "topic": "why the sky is blue", "grades": [5, 6, 7], "terms": ["sky", "blue", "scattering", "light", "sunlight", "gikatag", "ikinakalat", "asul", "marami", "kumakalat", "langit", "mokatag", "daghan", "buong", "ubang"], "fact": {"tl": "Asul ang langit dahil ikinakalat (scattering) ng hangin ang liwanag ng araw, at mas marami nitong ikinakalat ang asul na kulay kaysa ibang kulay, kaya kumakalat ang asul sa buong langit.", "en": "The sky looks blue because air scatters sunlight, and it scatters the blue light (scattering) more than the other colors, spreading blue across the whole sky.", "bis": "Asul ang langit kay gikatag (scattering) sa hangin ang kahayag sa adlaw, ug mas daghan niini nga gikatag ang asul nga kolor kaysa ubang kolor, mao nga mokatag ang asul sa tibuok langit."}, "source": "AAAS BSL Ch.4F (light)", "generator": "claude", "reviewed": false},
  {"id": "faq-sunset-red", "domain": "EARTH_SPACE", "topic": "why sunsets are red", "grades": [5, 6, 7], "terms": ["sunset", "red", "orange", "scattering"], "fact": {"tl": "Sa paglubog ng araw, mas makapal na hangin ang dinadaanan ng liwanag, kaya naikakalat (scattering) ang asul at natitira ang pula at kahel — kaya mapula ang langit.", "en": "At sunset, sunlight passes through more air, which scatters away the blue and leaves the reds and oranges, so the sky looks red.", "bis": "Sa pagsalop sa adlaw, mas baga nga hangin ang giagian sa kahayag, mao nga gikatag (scattering) ang asul ug nahibilin ang pula ug kahel — mao nga mapula ang langit."}, "source": "AAAS BSL Ch.4F (light)", "generator": "claude", "reviewed": false},
  {"id": "faq-stars-twinkle", "domain": "EARTH_SPACE", "topic": "why stars twinkle", "grades": [5, 6, 7], "terms": ["stars", "twinkle", "atmosphere", "light", "parito", "paroo", "bend", "kumikislap", "mokislap", "nagbabaluktot", "bahagyang", "mobawog", "dumadaan", "moagi"], "fact": {"tl": "Kumikislap ang mga bituin dahil ang liwanag nila ay dumadaan sa gumagalaw na hangin sa atmosphere, na bahagyang nagbabaluktot (bend) sa liwanag paroo't parito.", "en": "Stars twinkle because their light passes through moving layers of air in our atmosphere, which bends the light a little this way and that.", "bis": "Mokislap ang mga bituon kay ang ilang kahayag moagi sa naglihok nga hangin sa atmosphere, nga gamay nga mobawog (bend) sa kahayag balik-balik."}, "source": "AAAS BSL Ch.4A/4F", "generator": "claude", "reviewed": false},
  {"id": "faq-where-rain-comes-from", "domain": "EARTH_SPACE", "topic": "where rain comes from", "grades": [3, 4, 5], "terms": ["rain", "water cycle", "clouds", "evaporation", "pinasisingaw", "gipaalisngaw", "naggikan", "mabug", "bumabagsak", "tumataas", "galing", "mosaka", "panganod", "mahulog"], "fact": {"tl": "Galing ang ulan sa water cycle: pinasisingaw ng araw ang tubig, tumataas ito at nagiging ulap, at kapag mabigat na ang ulap, bumabagsak ang tubig bilang ulan.", "en": "Rain comes from the water cycle: the sun evaporates water, it rises and cools into clouds, and when the clouds get heavy the water falls as rain.", "bis": "Naggikan ang ulan sa water cycle: gipaalisngaw sa adlaw ang tubig, mosaka kini ug mahimong panganod, ug kung mabug-at na ang panganod, mahulog ang tubig isip ulan."}, "source": "AAAS BSL Ch.4B", "generator": "claude", "reviewed": false},
  {"id": "faq-why-boats-float", "domain": "FORCE_MOTION_ENERGY", "topic": "why boats float", "grades": [4, 5, 6], "terms": ["float", "buoyancy", "water", "boat", "sakayan", "bangka", "hangga", "basta", "gitulod", "palayo", "itinutulak", "pabalik", "magaan", "gaan"], "fact": {"tl": "Lumulutang ang bangka dahil itinutulak nito palayo ang tubig at itinutulak naman ito pabalik ng tubig (buoyancy). Hangga't mas magaan ang bangka kaysa tubig na itinutulak nito, lumulutang ito.", "en": "A boat floats because it pushes water aside and the water pushes back up (buoyancy). As long as the boat is lighter than the water it pushes aside, it floats.", "bis": "Molutaw ang sakayan kay gitulod niini palayo ang tubig ug gitulod usab kini balik sa tubig (buoyancy). Basta mas gaan ang sakayan kaysa tubig nga gitulod niini, molutaw kini."}, "source": "NRC PS2.B (forces)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-ice-floats", "domain": "MATTER", "topic": "why ice floats", "grades": [5, 6, 7], "terms": ["ice", "float", "density", "water", "likidong", "nayelo", "nagyelong", "bumababa", "nagyeyelo", "modako", "mokunhod", "magaan", "gaan", "lumulutang"], "fact": {"tl": "Lumulutang ang yelo dahil lumalaki ang tubig at bumababa ang density nito kapag nagyeyelo, kaya mas magaan ang nagyelong tubig kaysa likidong tubig.", "en": "Ice floats because water expands and becomes less dense (density) when it freezes, so frozen water is lighter than liquid water.", "bis": "Molutaw ang yelo kay modako ang tubig ug mokunhod ang density niini kung mo-yelo, mao nga mas gaan ang nayelo nga tubig kaysa likido nga tubig."}, "source": "AAAS BSL Ch.4D", "generator": "claude", "reviewed": false},
  {"id": "faq-why-leaves-green", "domain": "LIVING_THINGS", "topic": "why leaves are green", "grades": [3, 4, 5], "terms": ["leaves", "green", "chlorophyll", "photosynthesis", "itsura", "dagway", "gibalik", "berdeng", "ibinabalik", "berde", "humuhuli", "modakop", "dahon", "sangkap"], "fact": {"tl": "Berde ang mga dahon dahil sa chlorophyll, ang sangkap na humuhuli ng liwanag para sa photosynthesis. Ibinabalik nito ang berdeng liwanag, kaya berde ang itsura ng dahon.", "en": "Leaves are green because of chlorophyll, the substance that captures sunlight for photosynthesis. It reflects green light, so leaves look green.", "bis": "Berde ang mga dahon tungod sa chlorophyll, ang sustansya nga modakop sa kahayag para sa photosynthesis. Gibalik niini ang berde nga kahayag, mao nga berde ang dagway sa dahon."}, "source": "AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "faq-why-leaves-change-color", "domain": "LIVING_THINGS", "topic": "why leaves turn yellow", "grades": [4, 5, 6], "terms": ["leaves", "yellow", "brown", "chlorophyll", "kapehon", "kayumanggi", "nasisira", "tigulang", "kulang", "dilaw", "dalag", "berdeng", "matanda", "maguba"], "fact": {"tl": "Nagiging dilaw o kayumanggi ang dahon kapag nasisira ang berdeng chlorophyll — halimbawa kapag matanda na ang dahon o kulang sa tubig o liwanag ang halaman.", "en": "Leaves turn yellow or brown when the green chlorophyll breaks down — for example when a leaf is old or the plant lacks water or light.", "bis": "Mahimong dalag o kapehon ang dahon kung maguba ang berde nga chlorophyll — pananglitan kung tigulang na ang dahon o kulang sa tubig o kahayag ang tanom."}, "source": "AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "faq-why-we-breathe", "domain": "LIVING_THINGS", "topic": "why we breathe", "grades": [3, 4, 5], "terms": ["breathe", "oxygen", "carbon dioxide", "energy", "magpalabas", "mopagawas", "ilabas", "ipagawas", "humihinga", "makakuha", "hugaw", "moginhawa", "cell", "gigamit"], "fact": {"tl": "Humihinga tayo para makakuha ng oxygen, na ginagamit ng ating mga cell para magpalabas ng enerhiya mula sa pagkain, at para ilabas ang carbon dioxide, isang waste na gas.", "en": "We breathe to take in oxygen, which our cells use to release energy from food, and to breathe out carbon dioxide, a waste gas.", "bis": "Moginhawa ta aron makakuha og oxygen, nga gigamit sa atong mga cell aron mopagawas og enerhiya gikan sa pagkaon, ug aron ipagawas ang carbon dioxide, usa ka hugaw nga gas."}, "source": "AAAS BSL Ch.6; NRC LS1.C", "generator": "claude", "reviewed": false},
  {"id": "faq-why-moon-changes-shape", "domain": "EARTH_SPACE", "topic": "why the moon changes shape", "grades": [4, 5, 6], "terms": ["moon", "phases", "shape", "orbit", "naliliwanagan", "gilamdagan", "lainlain", "gyud", "nagkakaroon", "nating", "molibot", "bahagi", "buwan", "bulan"], "fact": {"tl": "Hindi talaga nagbabago ng hugis ang buwan — iba-iba lang ang nakikita nating bahagi nito na naliliwanagan ng araw habang umiikot ito sa Earth, kaya nagkakaroon ng phases.", "en": "The Moon does not really change shape — we see different amounts of its sunlit side as it orbits Earth, which makes its phases.", "bis": "Dili gyud mausab og porma ang bulan — lainlain lang ang atong makita nga bahin niini nga gilamdagan sa adlaw samtang molibot kini sa Earth, mao nga adunay phases."}, "source": "AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "faq-why-shadows", "domain": "FORCE_MOTION_ENERGY", "topic": "why shadows form", "grades": [3, 4, 5], "terms": ["shadow", "light", "block", "straight line", "makakaliko", "makaliko", "baktas", "lakad", "luyo", "humaharang", "ngitngit", "tuwid", "likod", "moali"], "fact": {"tl": "Nabubuo ang anino kapag may bagay na humaharang sa liwanag. Dahil tuwid ang lakad ng liwanag, hindi ito makakaliko sa bagay, kaya may madilim na hugis (shadow) sa likod nito.", "en": "A shadow forms when an object blocks light. Because light travels in straight lines, it cannot bend around the object, leaving a dark shape behind it.", "bis": "Maporma ang anino kung adunay butang nga moali sa kahayag. Tungod kay tul-id ang baktas sa kahayag, dili kini makaliko sa butang, mao nga adunay ngitngit nga porma (shadow) sa luyo niini."}, "source": "NRC PS4.B (light)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-iron-rusts", "domain": "MATTER", "topic": "why iron rusts", "grades": [5, 6, 7], "terms": ["iron", "rust", "oxygen", "chemical change", "kinakalawang", "nakikipag", "kalawang", "mataya", "takip", "tabon", "taya", "paglipas", "paglabay", "pulang"], "fact": {"tl": "Kinakalawang ang bakal kapag nakikipag-react ito sa oxygen at tubig sa paglipas ng panahon (chemical change), na bumubuo ng mapula-pulang takip na tinatawag na kalawang (rust).", "en": "Iron rusts when it reacts with oxygen and water over time (a chemical change), forming a reddish-brown coating called rust.", "bis": "Mataya ang puthaw kung mo-react kini sa oxygen ug tubig sa paglabay sa panahon (chemical change), nga maghimo og mapula-pula nga tabon nga gitawag og taya (rust)."}, "source": "AAAS BSL Ch.4D (chemical change)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-cold-when-wet", "domain": "FORCE_MOTION_ENERGY", "topic": "why we feel cold when wet", "grades": [5, 6, 7], "terms": ["evaporation", "cooling", "heat", "wet", "basang", "bation", "gikuha", "pakiramdam", "basa", "kinukuha", "sumisingaw", "alisngaw", "malamig", "bugnaw"], "fact": {"tl": "Malamig ang pakiramdam ng basang balat dahil habang sumisingaw (evaporation) ang tubig, kinukuha nito ang init mula sa iyong balat.", "en": "Wet skin feels cold because as the water evaporates it takes heat away from your skin (evaporation cools things down).", "bis": "Bugnaw ang bation sa basa nga panit kay samtang mo-alisngaw (evaporation) ang tubig, gikuha niini ang kainit gikan sa imong panit."}, "source": "NRC PS3.B (heat)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-sun-hot", "domain": "EARTH_SPACE", "topic": "why the sun is hot", "grades": [6, 7, 8], "terms": ["sun", "heat", "nuclear fusion", "hydrogen", "kaloob", "looban", "kinasuloran", "nagsasama", "bumuo", "napakaraming", "magtapok", "mobuga", "naglalabas", "daghan"], "fact": {"tl": "Mainit ang araw dahil sa kaloob-looban nito, nagsasama ang hydrogen para bumuo ng helium (nuclear fusion), na naglalabas ng napakaraming enerhiya bilang init at liwanag.", "en": "The Sun is hot because deep inside it, hydrogen joins to form helium (nuclear fusion), releasing enormous energy as heat and light.", "bis": "Init ang adlaw kay sa kinasuloran niini, magtapok ang hydrogen aron maporma ang helium (nuclear fusion), nga mobuga og daghan kaayong enerhiya isip kainit ug kahayag."}, "source": "AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "faq-why-magnet-sticks", "domain": "FORCE_MOTION_ENERGY", "topic": "why magnets stick to the fridge", "grades": [4, 5, 6], "terms": ["magnet", "iron", "attract", "fridge", "refrigerator", "pultahan", "pinto", "dumidikit", "modikit", "gibira", "hinihila", "puthaw", "bakal", "loob"], "fact": {"tl": "Dumidikit ang magnet sa refrigerator dahil may bakal (iron) sa loob ng pinto nito, at hinihila ng magnet ang bakal.", "en": "A magnet sticks to the fridge because the fridge door has iron inside, and magnets attract iron.", "bis": "Modikit ang magnet sa refrigerator kay adunay puthaw (iron) sa sulod sa pultahan niini, ug gibira sa magnet ang puthaw."}, "source": "NRC PS2.B (magnetism)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-plants-need-sun", "domain": "LIVING_THINGS", "topic": "why plants need sunlight", "grades": [3, 4, 5], "terms": ["plants", "sunlight", "photosynthesis", "food", "makakagawa", "manghihina", "mohuyang", "gumawa", "nagkinahanglan", "kadaghanan", "karamihan", "sariling", "kailangan", "sikat"], "fact": {"tl": "Kailangan ng halaman ang sikat ng araw dahil ginagamit nila ang enerhiya nito sa photosynthesis para gumawa ng sariling pagkain. Kung walang liwanag, hindi makakagawa ng pagkain ang karamihan ng halaman at manghihina.", "en": "Plants need sunlight because they use its energy in photosynthesis to make their own food. Without light, most plants cannot make food and will weaken.", "bis": "Nagkinahanglan ang tanom og kahayag sa adlaw kay gigamit nila ang enerhiya niini sa photosynthesis aron maghimo og kaugalingong pagkaon. Kung walay kahayag, dili makahimo og pagkaon ang kadaghanan sa tanom ug mohuyang."}, "source": "AAAS BSL Ch.5; NRC LS1.C", "generator": "claude", "reviewed": false},
  {"id": "faq-why-things-fall", "domain": "FORCE_MOTION_ENERGY", "topic": "why things fall down", "grades": [3, 4, 5], "terms": ["gravity", "fall", "down", "Earth", "gibira", "hinihila", "bumabagsak", "gitna", "tanan", "tunga", "mahulog", "paubos", "pababa", "silang"], "fact": {"tl": "Bumabagsak pababa ang mga bagay dahil hinihila silang lahat ng gravity ng Earth papunta sa gitna ng planeta.", "en": "Things fall down because Earth's gravity pulls everything toward the center of the planet.", "bis": "Mahulog paubos ang mga butang kay gibira silang tanan sa gravity sa Earth paingon sa tunga sa planeta."}, "source": "NRC PS2.B (gravity)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-day-night", "domain": "EARTH_SPACE", "topic": "why we have day and night", "grades": [3, 4, 5], "terms": ["day", "night", "rotation", "Earth", "nakatalikod", "nagtalikod", "bahaging", "nakaharap", "atubang", "gabii", "gabi", "molibot", "umiikot", "bahin"], "fact": {"tl": "May araw at gabi tayo dahil umiikot ang Earth (rotation). Ang bahaging nakaharap sa Araw ay may araw; ang bahaging nakatalikod ay may gabi.", "en": "We have day and night because Earth spins (rotation). The side facing the Sun has day; the side facing away has night.", "bis": "Adunay adlaw ug gabii ta kay molibot ang Earth (rotation). Ang bahin nga nag-atubang sa Adlaw adunay adlaw; ang bahin nga nagtalikod adunay gabii."}, "source": "AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "faq-why-we-sweat", "domain": "LIVING_THINGS", "topic": "why we sweat", "grades": [4, 5, 6], "terms": ["sweat", "cool", "evaporation", "temperature"], "fact": {"tl": "Pumapawis tayo para palamigin ang katawan: habang sumisingaw (evaporation) ang pawis sa balat, kinukuha nito ang init, kaya bumababa ang temperatura natin.", "en": "We sweat to cool the body: as sweat evaporates from the skin it carries heat away, lowering our temperature.", "bis": "Mosingot ta aron bugnawon ang lawas: samtang mo-alisngaw (evaporation) ang singot sa panit, gikuha niini ang kainit, mao nga mokunhod ang atong temperatura."}, "source": "AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "faq-why-sea-salty", "domain": "EARTH_SPACE", "topic": "why the sea is salty", "grades": [5, 6, 7], "terms": ["sea", "salt", "ocean", "rivers", "naiiwan", "mabilin", "ilog", "suba", "maalat", "parat", "kaunting", "asin", "natunaw", "sumisingaw"], "fact": {"tl": "Maalat ang dagat dahil ang mga ilog ay nagdadala ng kaunting natunaw na asin mula sa bato at lupa papunta sa dagat, at naiiwan ang asin habang sumisingaw ang tubig-dagat.", "en": "The sea is salty because rivers carry tiny amounts of dissolved salt from rocks and soil into the ocean, and the salt stays behind as seawater evaporates.", "bis": "Parat ang dagat kay ang mga suba modala og gamay nga natunaw nga asin gikan sa bato ug yuta ngadto sa dagat, ug mabilin ang asin samtang mo-alisngaw ang tubig-dagat."}, "source": "AAAS BSL Ch.4C", "generator": "claude", "reviewed": false},
  {"id": "faq-thunder-after-lightning", "domain": "EARTH_SPACE", "topic": "why thunder comes after lightning", "grades": [5, 6, 7], "terms": ["thunder", "lightning", "sound", "light", "speed", "maglakbay", "dalugdog", "nauuna", "kulog", "dungan", "sabay", "nangyayari", "mobaktas", "kidlat", "kilat"], "fact": {"tl": "Sabay nangyayari ang kidlat at kulog, pero nauuna mong makita ang kidlat dahil mas mabilis maglakbay ang liwanag kaysa tunog.", "en": "Lightning and thunder happen at the same time, but you see the lightning first because light travels much faster than sound.", "bis": "Dungan mahitabo ang kilat ug dalugdog, apan makita una nimo ang kilat kay mas paspas mobaktas ang kahayag kaysa tingog."}, "source": "NRC PS4 (light vs sound speed)", "generator": "claude", "reviewed": false},
  {"id": "faq-helium-balloon", "domain": "MATTER", "topic": "why helium balloons float up", "grades": [4, 5, 6], "terms": ["helium", "balloon", "density", "float"], "fact": {"tl": "Lumulutang pataas ang lobong may helium dahil mas magaan (mas mababa ang density) ang helium gas kaysa hanging nakapaligid, kaya itinutulak ito pataas ng hangin.", "en": "A helium balloon floats up because helium gas is lighter (less dense) than the air around it, so the air pushes it upward.", "bis": "Molutaw pataas ang lobo nga adunay helium kay mas gaan (mas ubos ang density) ang helium gas kaysa hangin sa palibot, mao nga gitulod kini pataas sa hangin."}, "source": "AAAS BSL Ch.4D (density)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-rainbow", "domain": "FORCE_MOTION_ENERGY", "topic": "why we see rainbows", "grades": [5, 6, 7], "terms": ["rainbow", "refraction", "light", "colors", "raindrops", "bahaghari", "naghahati", "balangaw", "mobahin", "dumaan", "nagbabaluktot", "mobawog", "moagi", "patak", "ulan"], "fact": {"tl": "Nabubuo ang bahaghari kapag dumaan ang liwanag ng araw sa mga patak ng ulan, na nagbabaluktot at naghahati sa liwanag sa mga kulay nito (refraction).", "en": "A rainbow forms when sunlight passes through raindrops, which bend and split the light into its colors (refraction).", "bis": "Maporma ang balangaw kung moagi ang kahayag sa adlaw sa mga tulo sa ulan, nga mobawog ug mobahin sa kahayag ngadto sa mga kolor niini (refraction)."}, "source": "NRC PS4.B (light)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-volcano-erupts", "domain": "EARTH_SPACE", "topic": "why volcanoes erupt", "grades": [6, 7, 8], "terms": ["volcano", "magma", "eruption", "pressure", "bumubuga", "bunganga", "magtigom", "tunaw", "iipon", "sumasabog", "presyur", "pagawas", "palabas", "mobuto"], "fact": {"tl": "Sumasabog ang bulkan kapag ang mainit na tunaw na bato (magma) at mga gas sa ilalim ng lupa ay nag-iipon ng presyon at bumubuga palabas sa bunganga sa crust ng Earth.", "en": "A volcano erupts when hot melted rock (magma) and gases deep underground build up pressure and burst out through an opening in the Earth's crust.", "bis": "Mobuto ang bulkan kung ang init nga natunaw nga bato (magma) ug mga gas sa ilalom sa yuta magtigom og presyur ug mobuga pagawas agi sa baba sa crust sa Earth."}, "source": "NRC ESS2.B (plate tectonics)", "generator": "claude", "reviewed": false},
  {"id": "living-five-senses-g3", "domain": "LIVING_THINGS", "topic": "the five senses", "grades": [3, 4], "terms": ["senses", "sight", "hearing", "smell", "taste", "touch", "panimaho", "nahitabo", "panlasa", "mahibaloan", "pandungog", "pandinig", "igbalati", "paghikap", "pandama", "limang"], "fact": {"tl": "Ang tao ay may limang pandama (senses): paningin (mata), pandinig (tainga), pang-amoy (ilong), panlasa (dila), at pang-hipo (balat). Tumutulong ang mga ito para malaman natin ang nangyayari sa paligid.", "en": "Humans have five senses: sight (eyes), hearing (ears), smell (nose), taste (tongue), and touch (skin). They help us learn what is happening around us.", "bis": "Ang tawo adunay lima ka igbalati (senses): panan-aw (mata), pandungog (dalunggan), panimaho (ilong), panlasa (dila), ug paghikap (panit). Motabang kini aron mahibaloan nato ang nahitabo sa palibot."}, "source": "AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "living-vertebrate-classes-g5", "domain": "LIVING_THINGS", "topic": "vertebrate groups", "grades": [5, 6], "terms": ["mammals", "birds", "fish", "reptiles", "amphibians", "vertebrate"], "fact": {"tl": "Ang mga vertebrate (may backbone) ay nahahati sa limang grupo: mammals (gatas at balahibo, tulad ng aso), birds (pakpak at balahibo), fish (kaliskis at hasang), reptiles (tuyong kaliskis, tulad ng ahas), at amphibians (basa ang balat, tulad ng palaka).", "en": "Vertebrates (animals with a backbone) fall into five groups: mammals (milk and fur, like dogs), birds (wings and feathers), fish (scales and gills), reptiles (dry scales, like snakes), and amphibians (moist skin, like frogs).", "bis": "Ang mga vertebrate (adunay backbone) nabahin sa lima ka grupo: mammals (gatas ug balhibo, sama sa iro), birds (pako ug balhibo), fish (himbis ug hasang), reptiles (uga nga himbis, sama sa bitin), ug amphibians (basa ang panit, sama sa baki)."}, "source": "AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-herbivore-carnivore-g4", "domain": "LIVING_THINGS", "topic": "herbivore carnivore omnivore", "grades": [4, 5], "terms": ["herbivore", "carnivore", "omnivore", "eat", "kinakain", "kalabaw", "gikaon", "baboy", "kabaw", "iring", "pusa", "kumakain", "sumala", "mokaon"], "fact": {"tl": "Ayon sa kinakain: ang herbivore ay kumakain ng halaman (tulad ng kalabaw), ang carnivore ay kumakain ng ibang hayop (tulad ng pusa), at ang omnivore ay kumakain ng halaman at hayop (tulad ng tao at baboy).", "en": "By what they eat: a herbivore eats plants (like a carabao), a carnivore eats other animals (like a cat), and an omnivore eats both plants and animals (like humans and pigs).", "bis": "Sumala sa gikaon: ang herbivore mokaon og tanom (sama sa kabaw), ang carnivore mokaon og ubang hayop (sama sa iring), ug ang omnivore mokaon og tanom ug hayop (sama sa tawo ug baboy)."}, "source": "AAAS BSL Ch.5; NRC LS2.A", "generator": "claude", "reviewed": false},
  {"id": "living-animal-adaptations-g5", "domain": "LIVING_THINGS", "topic": "animal adaptations", "grades": [5, 6], "terms": ["adaptation", "camouflage", "hibernation", "migration", "pagtago", "nagbago", "katulog", "pagbalhin", "paglipat", "paraan", "paagi", "tingtugnaw", "mahabang", "taglamig"], "fact": {"tl": "May mga espesyal na paraan ang hayop para mabuhay (adaptations): ang camouflage (pagtago sa pamamagitan ng kulay tulad ng chameleon), ang hibernation (mahabang tulog sa taglamig), at ang migration (paglipat sa ibang lugar kapag nagbago ang panahon).", "en": "Animals have special ways to survive (adaptations): camouflage (hiding by color, like a chameleon), hibernation (a long winter sleep), and migration (moving to another place when the season changes).", "bis": "Adunay espesyal nga paagi ang hayop aron mabuhi (adaptations): ang camouflage (pagtago pinaagi sa kolor sama sa chameleon), ang hibernation (taas nga katulog sa tingtugnaw), ug ang migration (pagbalhin sa laing dapit kung mausab ang panahon)."}, "source": "AAAS BSL Ch.5; NRC LS4.C", "generator": "claude", "reviewed": false},
  {"id": "living-plant-adaptations-g5", "domain": "LIVING_THINGS", "topic": "plant adaptations", "grades": [5, 6], "terms": ["adaptation", "cactus", "mangrove", "environment"], "fact": {"tl": "May mga halaman na may espesyal na adaptation sa kanilang kapaligiran: ang cactus ay may makapal na tangkay para mag-imbak ng tubig sa disyerto, at ang bakawan (mangrove) ay may ugat na kayang tumayo sa maalat na tubig sa baybayin.", "en": "Some plants have special adaptations to their environment: a cactus has a thick stem to store water in the desert, and a mangrove has roots that can stand in the salty water of the shore.", "bis": "Adunay mga tanom nga may espesyal nga adaptation sa ilang palibot: ang cactus adunay baga nga punoan aron magtipig og tubig sa disyerto, ug ang bakhaw (mangrove) adunay gamot nga makabarog sa parat nga tubig sa baybayon."}, "source": "AAAS BSL Ch.5; NRC LS4.C", "generator": "claude", "reviewed": false},
  {"id": "living-germination-g4", "domain": "LIVING_THINGS", "topic": "seed germination", "grades": [4, 5], "terms": ["germination", "seed", "sprout", "grow", "paitaas", "usbong", "usbod", "tapos", "papuntang", "dayon", "lumalabas", "igong", "liso", "mogawas"], "fact": {"tl": "Sa germination, tumutubo ang buto (seed) papuntang bagong halaman kapag may sapat na tubig, hangin, at init. Unang lumalabas ang ugat pababa, tapos ang usbong (shoot) paitaas papunta sa liwanag.", "en": "In germination, a seed grows into a new plant when there is enough water, air, and warmth. First the root comes out downward, then the shoot grows upward toward the light.", "bis": "Sa germination, motubo ang liso (seed) ngadto sa bag-ong tanom kung adunay igong tubig, hangin, ug kainit. Una mogawas ang gamot paubos, dayon ang usbod (shoot) motubo pataas paingon sa kahayag."}, "source": "AAAS BSL Ch.5; NRC LS1.B", "generator": "claude", "reviewed": false},
  {"id": "living-fungi-g6", "domain": "LIVING_THINGS", "topic": "fungi", "grades": [6, 7], "terms": ["fungi", "mushroom", "mold", "decomposer"], "fact": {"tl": "Ang fungi (tulad ng kabute o mushroom at amag o mold) ay hindi halaman o hayop — sariling grupo sila. Hindi sila gumagawa ng sariling pagkain; kumukuha sila ng sustansya mula sa patay o nabubulok na bagay, kaya mahalaga sila bilang decomposers.", "en": "Fungi (like mushrooms and mold) are not plants or animals — they are their own group. They do not make their own food; they take nutrients from dead or rotting matter, so they are important decomposers.", "bis": "Ang fungi (sama sa uhong o mushroom ug agup-op o mold) dili tanom o hayop — kaugalingon silang grupo. Wala sila maghimo og kaugalingong pagkaon; mokuha sila og sustansya gikan sa patay o nadunot nga butang, mao nga importante sila isip decomposers."}, "source": "AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-food-web-g6", "domain": "LIVING_THINGS", "topic": "food web", "grades": [6, 7], "terms": ["food web", "food chain", "ecosystem", "energy", "kumain", "kainin", "ipinapakita", "gipakita", "chain", "magkakaugnay", "maaaring", "magkadugtong", "marami", "mokaon"], "fact": {"tl": "Ang food web ay grupo ng maraming food chain na magkakaugnay sa isang ecosystem. Ipinapakita nito na ang isang hayop ay maaaring kumain ng maraming uri ng pagkain, at ang isang halaman o hayop ay maaaring kainin ng marami.", "en": "A food web is a group of many connected food chains in an ecosystem. It shows that one animal may eat many kinds of food, and one plant or animal may be eaten by many.", "bis": "Ang food web usa ka grupo sa daghang food chain nga magkadugtong sa usa ka ecosystem. Gipakita niini nga ang usa ka hayop mahimong mokaon og daghang klase sa pagkaon, ug ang usa ka tanom o hayop mahimong kan-on sa daghan."}, "source": "NRC LS2.B; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-decomposers-g5", "domain": "LIVING_THINGS", "topic": "decomposers", "grades": [5, 6], "terms": ["decomposer", "bacteria", "fungi", "nutrients", "magamit", "bulate", "naglalansag", "moguba", "ibalik", "siklo", "ulod", "ibinabalik", "patay", "mahalaga"], "fact": {"tl": "Ang mga decomposers (tulad ng bacteria, fungi, at bulate) ang naglalansag sa mga patay na halaman at hayop. Ibinabalik nila ang sustansya sa lupa para magamit muli ng mga halaman — kaya mahalaga sila sa siklo ng buhay.", "en": "Decomposers (like bacteria, fungi, and worms) break down dead plants and animals. They return nutrients to the soil for plants to use again — so they are important in the cycle of life.", "bis": "Ang mga decomposers (sama sa bacteria, fungi, ug ulod) maoy moguba sa patay nga tanom ug hayop. Ibalik nila ang sustansya sa yuta aron magamit pag-usab sa mga tanom — mao nga importante sila sa siklo sa kinabuhi."}, "source": "NRC LS2.B; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-endangered-ph-g6", "domain": "LIVING_THINGS", "topic": "endangered species", "grades": [6, 7], "terms": ["endangered", "extinction", "Philippine eagle", "tamaraw", "conservation", "tinutulungan", "pangangalaga", "nanganganib", "pagpangayam", "pangangaso", "matabangan", "pagkasira", "nameligro", "pagkaguba", "tuluyan"], "fact": {"tl": "Ang ilang hayop ay endangered — nanganganib mawala nang tuluyan (extinction) dahil sa pagkasira ng tirahan at pangangaso. Sa Pilipinas, kabilang dito ang Philippine eagle at ang tamaraw. Tinutulungan natin sila sa pamamagitan ng pangangalaga sa kanilang habitat.", "en": "Some animals are endangered — at risk of disappearing forever (extinction) because of habitat loss and hunting. In the Philippines these include the Philippine eagle and the tamaraw. We help them by protecting their habitats.", "bis": "Ang ubang hayop endangered — nameligro nga mawala hangtod (extinction) tungod sa pagkaguba sa puy-anan ug pagpangayam. Sa Pilipinas, lakip niini ang Philippine eagle ug ang tamaraw. Matabangan nato sila pinaagi sa pag-amping sa ilang habitat."}, "source": "NRC LS2.C; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "fme-renewable-energy-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "renewable energy", "grades": [6, 7], "terms": ["renewable energy", "solar", "wind", "hydro", "pinagkukunan", "polusyon", "malinis", "limpyo", "tinubdan", "nagaagos", "nauubos", "mahurot", "karbon", "pagsunog"], "fact": {"tl": "Ang renewable energy ay galing sa pinagkukunan na hindi nauubos: solar (araw), wind (hangin), at hydro (umaagos na tubig). Mas malinis ito kaysa pagsunog ng langis o karbon na nagdudulot ng polusyon.", "en": "Renewable energy comes from sources that do not run out: solar (sun), wind, and hydro (flowing water). It is cleaner than burning oil or coal, which causes pollution.", "bis": "Ang renewable energy gikan sa tinubdan nga dili mahurot: solar (adlaw), wind (hangin), ug hydro (nagaagos nga tubig). Mas limpyo kini kaysa pagsunog og lana o karbon nga maghatag og polusyon."}, "source": "NRC PS3; AAAS BSL Ch.8", "generator": "claude", "reviewed": false},
  {"id": "fme-static-electricity-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "static electricity", "grades": [5, 6], "terms": ["static electricity", "charge", "rub", "shock"], "fact": {"tl": "Ang static electricity ay nabubuo kapag nagkiskisan ang dalawang bagay at lumilipat ang maliliit na charge. Kaya dumidikit ang buhok sa suklay o may maliit na 'kuryente' kang maramdaman kapag humawak ka pagkatapos magkiskis.", "en": "Static electricity builds up when two objects rub and tiny charges move between them. That is why hair sticks to a comb, or you feel a small 'shock' after rubbing.", "bis": "Ang static electricity matukod kung magkuskos ang duha ka butang ug mobalhin ang gagmay nga charge. Mao nga modikit ang buhok sa sudlay, o adunay gamay nga 'kuryente' nga imong bation kung mohikap ka human magkuskos."}, "source": "NRC PS2.B; AAAS BSL Ch.4G", "generator": "claude", "reviewed": false},
  {"id": "fme-how-we-see-color-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "how we see color", "grades": [6, 7], "terms": ["color", "reflect", "absorb", "light", "gisuyop", "mansanas", "gibalik", "pulang", "sinisipsip", "pula", "ibinabalik", "uban", "ubang", "nato"], "fact": {"tl": "Nakikita natin ang kulay dahil ibinabalik (reflect) ng mga bagay ang ilang kulay ng liwanag at sinisipsip (absorb) ang iba. Halimbawa, pula ang mansanas dahil ibinabalik nito ang pulang liwanag at sinisipsip ang ibang kulay.", "en": "We see color because objects reflect some colors of light and absorb others. For example, an apple looks red because it reflects red light and absorbs the other colors.", "bis": "Makita nato ang kolor kay gibalik (reflect) sa mga butang ang ubang kolor sa kahayag ug gisuyop (absorb) ang uban. Pananglitan, pula ang mansanas kay gibalik niini ang pula nga kahayag ug gisuyop ang ubang kolor."}, "source": "NRC PS4.B (light)", "generator": "claude", "reviewed": false},
  {"id": "fme-heat-conductors-insulators-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "heat conductors and insulators", "grades": [6, 7], "terms": ["conductor", "insulator", "heat", "metal", "magpadaloy", "kaserola", "kuptanan", "kaldero", "panapton", "hawakan", "tela", "magpadala", "plastik", "kamay"], "fact": {"tl": "Ang heat conductors (tulad ng metal) ay mabilis magpadaloy ng init; ang heat insulators (tulad ng kahoy, plastik, at tela) ay mabagal. Kaya kahoy o plastik ang hawakan ng kaserola — para hindi mainit ang kamay.", "en": "Heat conductors (like metal) let heat flow quickly; heat insulators (like wood, plastic, and cloth) are slow. That is why a pot handle is wood or plastic — so your hand does not get hot.", "bis": "Ang heat conductors (sama sa metal) paspas magpadala og kainit; ang heat insulators (sama sa kahoy, plastik, ug panapton) hinay. Mao nga kahoy o plastik ang kuptanan sa kaldero — aron dili mainit ang kamot."}, "source": "NRC PS3.B (heat)", "generator": "claude", "reviewed": false},
  {"id": "fme-echo-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "echoes", "grades": [5, 6], "terms": ["echo", "sound", "reflect", "bounce", "alingawngaw", "pangpang", "bumalik", "umuulit", "bangin", "pader", "boses", "lanog", "paril", "naririnig"], "fact": {"tl": "Ang echo (alingawngaw) ay nangyayari kapag ang tunog ay tumama sa isang malaking ibabaw tulad ng bundok o pader at bumalik sa atin. Kaya naririnig mong umuulit ang iyong boses sa malaking silid o bangin.", "en": "An echo happens when sound hits a large surface like a mountain or wall and bounces back to us. That is why you hear your voice repeat in a big room or canyon.", "bis": "Ang echo (lanog) mahitabo kung ang tingog motama sa dako nga nawong sama sa bukid o paril ug mobalik kanato. Mao nga madungog nimo nga mobalik-balik ang imong tingog sa dako nga kwarto o pangpang."}, "source": "NRC PS4.A (sound)", "generator": "claude", "reviewed": false},
  {"id": "fme-battery-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "how a battery works", "grades": [5, 6], "terms": ["battery", "chemical energy", "electrical energy", "circuit", "patakbuhin", "padaganon", "iimbak", "remote", "magtipig", "himoon", "flashlight", "baterya", "ginagawa", "dumadaloy"], "fact": {"tl": "Ang baterya (battery) ay nag-iimbak ng chemical energy at ginagawa itong electrical energy para patakbuhin ang mga gamit tulad ng flashlight at remote. Dumadaloy ang kuryente mula sa baterya papunta sa gamit at pabalik sa isang circuit.", "en": "A battery stores chemical energy and turns it into electrical energy to power devices like flashlights and remotes. Current flows from the battery to the device and back in a circuit.", "bis": "Ang baterya (battery) magtipig og chemical energy ug himoon kining electrical energy aron padaganon ang mga gamit sama sa flashlight ug remote. Moagos ang kuryente gikan sa baterya ngadto sa gamit ug balik sa usa ka circuit."}, "source": "NRC PS3.A", "generator": "claude", "reviewed": false},
  {"id": "earth-typhoon-g5", "domain": "EARTH_SPACE", "topic": "typhoons", "grades": [5, 6], "terms": ["typhoon", "storm", "wind", "rain", "karagatan", "kadagatan", "handa", "andam", "mahalagang", "dumaan", "unos", "nagtuyok", "madalas", "moagi"], "fact": {"tl": "Ang bagyo (typhoon) ay isang malakas na bagyo na may umiikot na hangin at malakas na ulan, na nabubuo sa mainit na karagatan. Madalas dumaan ang bagyo sa Pilipinas, kaya mahalagang maging handa.", "en": "A typhoon is a powerful storm with spinning winds and heavy rain that forms over warm oceans. Typhoons often pass through the Philippines, so it is important to be prepared.", "bis": "Ang bagyo (typhoon) usa ka kusog nga unos nga adunay nagtuyok nga hangin ug kusog nga ulan, nga maporma sa init nga kadagatan. Kanunay moagi ang bagyo sa Pilipinas, mao nga importante nga andam."}, "source": "NRC ESS2.D; AAAS BSL Ch.4B", "generator": "claude", "reviewed": false},
  {"id": "earth-clouds-g5", "domain": "EARTH_SPACE", "topic": "types of clouds", "grades": [5, 6], "terms": ["clouds", "cumulus", "cirrus", "nimbus", "naglutaw", "maputi", "abuhon", "himpapawid", "kahanginan", "kristal", "gapas", "puti", "morag", "bulak"], "fact": {"tl": "Ang ulap (clouds) ay gawa sa maliliit na patak ng tubig o kristal ng yelo na lumulutang sa himpapawid. May iba't ibang uri: ang maputi at parang bulak (cumulus), ang manipis at mataas (cirrus), at ang makapal na kulay-abo na nagdadala ng ulan (nimbus).", "en": "Clouds are made of tiny water droplets or ice crystals floating in the air. There are different types: white and puffy (cumulus), thin and high (cirrus), and thick gray ones that bring rain (nimbus).", "bis": "Ang panganod (clouds) hinimo sa gagmay nga tulo sa tubig o kristal sa yelo nga naglutaw sa kahanginan. Adunay nagkalainlaing klase: ang puti ug morag gapas (cumulus), ang nipis ug taas (cirrus), ug ang baga nga abuhon nga modala og ulan (nimbus)."}, "source": "AAAS BSL Ch.4B", "generator": "claude", "reviewed": false},
  {"id": "earth-ph-seasons-g4", "domain": "EARTH_SPACE", "topic": "seasons in the Philippines", "grades": [4, 5], "terms": ["seasons", "dry season", "wet season", "tropical", "nobyembre", "mayo", "tayong", "marso", "hunyo", "ting", "tingtugnaw", "taglamig", "pangunahing", "klima"], "fact": {"tl": "Sa Pilipinas, may dalawang pangunahing panahon: ang tag-init o tag-araw (dry season, mga Marso hanggang Mayo) at ang tag-ulan (wet season, mga Hunyo hanggang Nobyembre). Wala tayong taglamig dahil tropical ang ating klima.", "en": "In the Philippines there are two main seasons: the dry season (about March to May) and the wet/rainy season (about June to November). We have no winter because our climate is tropical.", "bis": "Sa Pilipinas, adunay duha ka nag-unang panahon: ang ting-init (dry season, mga Marso hangtod Mayo) ug ang ting-ulan (wet season, mga Hunyo hangtod Nobyembre). Wala tay tingtugnaw kay tropical ang atong klima."}, "source": "NRC ESS2.D (climate)", "generator": "claude", "reviewed": false},
  {"id": "earth-tides-g6", "domain": "EARTH_SPACE", "topic": "tides", "grades": [6, 7], "terms": ["tides", "moon", "gravity", "sea", "pagkanaog", "pagbaba", "bahagya", "pagsaka", "sanhi", "hunas", "taog", "kati", "taob", "pagtaas"], "fact": {"tl": "Ang taog at kati (tides) ay ang pagtaas at pagbaba ng tubig-dagat. Sanhi ito ng hila ng gravity ng buwan (at bahagya ng araw) sa tubig ng Earth habang umiikot ang planeta.", "en": "Tides are the rising and falling of the sea. They are caused by the pull of the Moon's gravity (and partly the Sun's) on Earth's water as the planet turns.", "bis": "Ang taob ug hunas (tides) mao ang pagsaka ug pagkanaog sa tubig-dagat. Hinungdan niini ang bira sa gravity sa bulan (ug gamay sa adlaw) sa tubig sa Earth samtang molibot ang planeta."}, "source": "NRC ESS1.B; AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "earth-fossils-g6", "domain": "EARTH_SPACE", "topic": "fossils", "grades": [6, 7], "terms": ["fossil", "remains", "rock", "ancient", "napreserbar", "napreserba", "nakalipas", "nabuhay", "milabay", "nabuhi", "bakas", "salin", "labi", "siyentista"], "fact": {"tl": "Ang fossils ay mga labi o bakas ng mga halaman at hayop noong unang panahon na napreserba sa bato. Tumutulong ang mga ito sa mga siyentista na malaman kung anong nabuhay sa Earth milyon-milyong taon na ang nakalipas.", "en": "Fossils are the remains or traces of ancient plants and animals preserved in rock. They help scientists learn what lived on Earth millions of years ago.", "bis": "Ang fossils mao ang salin o timaan sa karaang tanom ug hayop nga napreserbar sa bato. Motabang kini sa mga siyentista nga mahibaloan kung unsa ang nabuhi sa Earth milyon-milyon ka tuig na ang milabay."}, "source": "NRC ESS1.C; AAAS BSL Ch.4C", "generator": "claude", "reviewed": false},
  {"id": "earth-meteors-comets-g6", "domain": "EARTH_SPACE", "topic": "asteroids comets meteors", "grades": [6, 7], "terms": ["asteroid", "comet", "meteor", "shooting star", "lumalapit", "buntot", "moduol", "ikog", "nasusunog", "masunog", "pumapasok", "mosulod", "malaking", "alikabok"], "fact": {"tl": "Sa kalawakan, ang asteroid ay malaking bato na umiikot sa Araw; ang comet ay bola ng yelo at alikabok na may buntot kapag lumalapit sa Araw; at ang meteor ('shooting star') ay maliit na bato na nasusunog kapag pumapasok sa atmosphere ng Earth.", "en": "In space, an asteroid is a large rock orbiting the Sun; a comet is a ball of ice and dust with a tail when it nears the Sun; and a meteor ('shooting star') is a small rock that burns up entering Earth's atmosphere.", "bis": "Sa kawanangan, ang asteroid usa ka dako nga bato nga molibot sa Adlaw; ang comet usa ka bola sa yelo ug abog nga adunay ikog kung moduol sa Adlaw; ug ang meteor ('shooting star') usa ka gamay nga bato nga masunog kung mosulod sa atmosphere sa Earth."}, "source": "AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "earth-recycling-g4", "domain": "EARTH_SPACE", "topic": "recycling and conservation", "grades": [4, 5], "terms": ["recycle", "reduce", "reuse", "waste", "environment", "mababawasan", "maingatan", "maamping", "bawasan", "gamitin", "makunhuran", "kinaiyahan", "kalikasan", "gamiton", "basura"], "fact": {"tl": "Mababawasan natin ang basura at maingatan ang kalikasan sa pamamagitan ng 3 R's: Reduce (bawasan ang gamit), Reuse (gamitin muli), at Recycle (gawing bago ang lumang bagay tulad ng plastik at papel).", "en": "We can reduce waste and protect nature with the 3 R's: Reduce (use less), Reuse (use again), and Recycle (turn old things like plastic and paper into new ones).", "bis": "Makunhuran nato ang basura ug maamping ang kinaiyahan pinaagi sa 3 R's: Reduce (gamay nga gamiton), Reuse (gamiton pag-usab), ug Recycle (himoon nga bag-o ang daan nga butang sama sa plastik ug papel)."}, "source": "NRC ESS3.C", "generator": "claude", "reviewed": false},
  {"id": "matter-dissolving-factors-g6", "domain": "MATTER", "topic": "what makes things dissolve faster", "grades": [6, 7], "terms": ["dissolve", "temperature", "stir", "solute"], "fact": {"tl": "Mas mabilis matunaw (dissolve) ang isang solid sa likido kapag (1) iniinit ang likido, (2) hinahalo o kinakalog, at (3) pinino sa maliliit na piraso ang solid. Kaya mas mabilis matunaw ang asukal sa mainit na tubig na hinahalo.", "en": "A solid dissolves faster in a liquid when (1) the liquid is heated, (2) it is stirred, and (3) the solid is in smaller pieces. That is why sugar dissolves faster in hot water that is stirred.", "bis": "Mas paspas matunaw (dissolve) ang solid sa likido kung (1) initan ang likido, (2) kutawon, ug (3) dugmokon sa gagmay nga piraso ang solid. Mao nga mas paspas matunaw ang asukal sa init nga tubig nga gikutaw."}, "source": "NRC PS1.A; DepEd Science CG (Matter)", "generator": "claude", "reviewed": false},
  {"id": "living-cell-organelles-g8", "domain": "LIVING_THINGS", "topic": "cell organelles", "grades": [7, 8], "terms": ["organelle", "nucleus", "mitochondria", "membrane", "cytoplasm", "kumokontrol", "mokontrol", "kontrol", "tungkulin", "pumapasok", "mosulod", "sentro", "tahas", "bahagi", "likido"], "fact": {"tl": "Ang cell ay may maliliit na bahagi (organelles) na may tungkulin: ang nucleus (kontrol-sentro na may DNA), ang mitochondria (gumagawa ng enerhiya), ang cytoplasm (likido sa loob), at ang cell membrane (balat na kumokontrol kung ano ang pumapasok).", "en": "A cell has tiny parts (organelles) with jobs: the nucleus (control center holding DNA), the mitochondria (make energy), the cytoplasm (fluid inside), and the cell membrane (skin that controls what enters).", "bis": "Ang cell adunay gagmay nga bahin (organelles) nga may tahas: ang nucleus (sentro sa kontrol nga adunay DNA), ang mitochondria (maghimo og enerhiya), ang cytoplasm (likido sa sulod), ug ang cell membrane (panit nga mokontrol kung unsa ang mosulod)."}, "source": "NRC LS1.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-dna-genes-g8", "domain": "LIVING_THINGS", "topic": "DNA and genes", "grades": [7, 8], "terms": ["DNA", "genes", "traits", "instructions", "partikular", "nagsasabi", "magsulti", "pagtukod", "gagana", "bubuo", "unsaon", "piho", "paglihok", "katangian"], "fact": {"tl": "Ang DNA ay parang 'instruction manual' sa loob ng bawat cell na nagsasabi kung paano bubuo at gagana ang katawan. Ang genes ay maliliit na bahagi ng DNA na nagdadala ng partikular na katangian, tulad ng kulay ng mata.", "en": "DNA is like an 'instruction manual' inside every cell that tells the body how to build and work. Genes are small sections of DNA that carry particular traits, like eye color.", "bis": "Ang DNA sama sa 'instruction manual' sa sulod sa matag cell nga magsulti kung unsaon pagtukod ug paglihok sa lawas. Ang genes gagmay nga bahin sa DNA nga modala og piho nga kinaiya, sama sa kolor sa mata."}, "source": "NRC LS3.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-immune-system-g7", "domain": "LIVING_THINGS", "topic": "immune system", "grades": [6, 7, 8], "terms": ["immune system", "germs", "white blood cells", "disease", "nagtatanggol", "modepensa", "germ", "masustansyang", "masustansya", "paghuhugas", "lumalaban", "paghugas", "mosukol", "virus"], "fact": {"tl": "Ang immune system ang nagtatanggol sa katawan laban sa mga germ (bacteria at virus). Ang mga white blood cells ang lumalaban sa mga ito. Ang madalas na paghuhugas ng kamay, sapat na tulog, at masustansyang pagkain ay tumutulong para manatiling malakas ito.", "en": "The immune system defends the body against germs (bacteria and viruses). White blood cells fight them off. Frequent handwashing, enough sleep, and nutritious food help keep it strong.", "bis": "Ang immune system maoy modepensa sa lawas batok sa mga germ (bacteria ug virus). Ang mga white blood cells maoy mosukol niini. Ang kanunay nga paghugas sa kamot, igong tulog, ug masustansya nga pagkaon motabang aron magpabilin kining lig-on."}, "source": "AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "living-nutrition-food-groups-g4", "domain": "LIVING_THINGS", "topic": "balanced diet and food groups", "grades": [4, 5], "terms": ["nutrition", "food groups", "go grow glow", "balanced diet", "hatiin", "bahina", "utanon", "gulay", "kinahanglan", "bitamina", "protina", "paglaki", "pagtubo", "kanin"], "fact": {"tl": "Para maging malusog, kailangan ng balanced diet. Sa Pinggang Pinoy, hatiin ang pagkain sa: GO (carbohydrates para sa enerhiya, tulad ng kanin), GROW (protina para sa paglaki, tulad ng isda at itlog), at GLOW (gulay at prutas para sa bitamina).", "en": "To be healthy you need a balanced diet. In the Filipino 'Pinggang Pinoy', divide food into: GO foods (carbohydrates for energy, like rice), GROW foods (protein for growth, like fish and eggs), and GLOW foods (vegetables and fruits for vitamins).", "bis": "Aron mahimong himsog, kinahanglan og balanced diet. Sa Pinggang Pinoy, bahina ang pagkaon sa: GO (carbohydrates para sa enerhiya, sama sa kan-on), GROW (protina para sa pagtubo, sama sa isda ug itlog), ug GLOW (utanon ug prutas para sa bitamina)."}, "source": "DepEd Health/Science; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "living-plant-tropism-g6", "domain": "LIVING_THINGS", "topic": "plant tropism", "grades": [6, 7], "terms": ["tropism", "phototropism", "gravitropism", "respond", "laging", "tumutugon", "motubag", "nakaharap", "atubang", "tumutubo", "paligid", "gamot", "paubos", "dahon"], "fact": {"tl": "Tumutugon ang halaman sa paligid nito (tropism): tumutubo ito papunta sa liwanag (phototropism) at tumutubo ang ugat pababa dahil sa gravity (gravitropism). Kaya laging nakaharap sa araw ang mga dahon.", "en": "Plants respond to their surroundings (tropism): they grow toward light (phototropism) and their roots grow downward because of gravity (gravitropism). That is why leaves always face the sun.", "bis": "Motubag ang tanom sa palibot niini (tropism): motubo kini paingon sa kahayag (phototropism) ug motubo ang gamot paubos tungod sa gravity (gravitropism). Mao nga kanunay nag-atubang sa adlaw ang mga dahon."}, "source": "NRC LS1.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "matter-chemical-reaction-g7", "domain": "MATTER", "topic": "chemical reactions", "grades": [7, 8], "terms": ["chemical reaction", "new substance", "signs", "pagkalawang", "pagpagawas", "pagkataya", "paglabas", "pagporma", "pagbula", "pagbuo", "tanda", "baho", "pagsusunog"], "fact": {"tl": "Sa chemical reaction, ang mga sangkap ay nagbabago at bumubuo ng bagong sangkap. Mga tanda nito: pagbabago ng kulay, paglabas ng init o liwanag, pagbula (gas), o pagbuo ng usok o amoy. Halimbawa: pagsusunog at pagkalawang.", "en": "In a chemical reaction, substances change and form new substances. Signs of it: a color change, giving off heat or light, bubbling (gas), or forming smoke or a smell. Examples: burning and rusting.", "bis": "Sa chemical reaction, ang mga sustansya mausab ug maghimo og bag-ong sustansya. Mga timaan: pagbag-o sa kolor, pagpagawas og kainit o kahayag, pagbula (gas), o pagporma og aso o baho. Pananglitan: pagsunog ug pagkataya."}, "source": "NRC PS1.B; AAAS BSL Ch.4D", "generator": "claude", "reviewed": false},
  {"id": "matter-combustion-g7", "domain": "MATTER", "topic": "combustion", "grades": [6, 7], "terms": ["combustion", "fire", "fuel", "oxygen", "heat", "nangangailangan", "mamamatay", "mapalong", "gatong", "alisin", "sugnod", "taboni", "kuhaa", "apoy", "pagsusunog"], "fact": {"tl": "Ang combustion (pagsusunog) ay isang chemical reaction na nangangailangan ng tatlong bagay (fire triangle): gatong (fuel), oxygen, at init. Alisin ang isa — halimbawa, takpan ang apoy para mawala ang oxygen — at mamamatay ang apoy.", "en": "Combustion (burning) is a chemical reaction that needs three things (the fire triangle): fuel, oxygen, and heat. Remove one — for example, cover a flame to cut off oxygen — and the fire goes out.", "bis": "Ang combustion (pagsunog) usa ka chemical reaction nga nagkinahanglan og tulo ka butang (fire triangle): sugnod (fuel), oxygen, ug kainit. Kuhaa ang usa — pananglitan, taboni ang kalayo aron mawala ang oxygen — ug mapalong ang kalayo."}, "source": "NRC PS1.B; AAAS BSL Ch.4D", "generator": "claude", "reviewed": false},
  {"id": "matter-plastics-synthetic-g6", "domain": "MATTER", "topic": "natural and synthetic materials", "grades": [6, 7], "terms": ["natural", "synthetic", "plastic", "materials", "mabulok", "basura", "gapas", "materyales", "karaniwang", "madunot", "plastik", "matibay", "galing", "bulak"], "fact": {"tl": "Ang ilang materyales ay natural (tulad ng kahoy, bulak, at bakal mula sa lupa); ang iba ay synthetic o gawa ng tao (tulad ng plastik at nylon, na karaniwang galing sa langis). Matibay ang plastik pero mabagal mabulok, kaya nagiging basura.", "en": "Some materials are natural (like wood, cotton, and metal from the earth); others are synthetic or human-made (like plastic and nylon, usually made from oil). Plastic is durable but breaks down very slowly, so it becomes waste.", "bis": "Ang ubang materyales natural (sama sa kahoy, gapas, ug puthaw gikan sa yuta); ang uban synthetic o hinimo sa tawo (sama sa plastik ug nylon, kasagaran gikan sa lana). Lig-on ang plastik apan hinay madunot, mao nga mahimong basura."}, "source": "DepEd Science CG (Matter); NRC PS1", "generator": "claude", "reviewed": false},
  {"id": "fme-pressure-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "pressure", "grades": [6, 7, 8], "terms": ["pressure", "force", "area", "needle", "nagbabawas", "tumutusok", "gipunting", "nakatuon", "talinis", "motusok", "matalas", "karayom", "dagom", "malapad"], "fact": {"tl": "Ang pressure ay ang force na nakatuon sa isang lugar (force kada area). Mas matalas na bagay = mas maliit na area = mas malakas na pressure, kaya tumutusok ang karayom. Ang malapad na area (tulad ng snowshoes o gulong) ay nagbabawas ng pressure.", "en": "Pressure is force concentrated on an area (force per area). A sharper object = smaller area = greater pressure, which is why a needle pokes through. A wider area (like snowshoes or tires) lowers the pressure.", "bis": "Ang pressure mao ang force nga gipunting sa usa ka dapit (force kada area). Mas talinis nga butang = mas gamay nga area = mas kusog nga pressure, mao nga motusok ang dagom. Ang lapad nga area (sama sa snowshoes o ligid) mokunhod sa pressure."}, "source": "NRC PS2; AAAS BSL Ch.4F", "generator": "claude", "reviewed": false},
  {"id": "fme-momentum-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "momentum", "grades": [8, 9, 10], "terms": ["momentum", "mass", "speed", "motion", "nakadepende", "nagdepende", "pahunongon", "pahintuin", "trak", "mapanganib", "peligroso", "mahirap", "katulin", "bilis"], "fact": {"tl": "Ang momentum ay ang lakas ng galaw ng isang bagay — nakadepende sa mass at bilis nito. Mas mahirap pahintuin ang mabigat at mabilis na bagay (tulad ng trak) kaysa magaan o mabagal — kaya mas mapanganib ito.", "en": "Momentum is the strength of an object's motion — it depends on its mass and speed. A heavy, fast object (like a truck) is harder to stop than a light or slow one — which is why it is more dangerous.", "bis": "Ang momentum mao ang kakusog sa lihok sa usa ka butang — nagdepende sa mass ug katulin niini. Mas lisod pahunongon ang bug-at ug paspas nga butang (sama sa trak) kaysa gaan o hinay — mao nga mas peligroso kini."}, "source": "NRC PS2.A", "generator": "claude", "reviewed": false},
  {"id": "fme-lever-fulcrum-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "lever and fulcrum", "grades": [5, 6, 7], "terms": ["lever", "fulcrum", "simple machine", "force", "panghukay", "magbuhat", "gunting", "barita", "punto", "olang", "bara", "alsa", "kaunting", "matigas"], "fact": {"tl": "Ang lever ay isang matigas na bara na gumagalaw sa isang punto na tinatawag na fulcrum. Ginagamit ito para magbuhat ng mabigat gamit ang mas kaunting force — tulad ng seesaw, gunting, o panghukay (crowbar).", "en": "A lever is a stiff bar that turns on a point called the fulcrum. It is used to lift heavy things with less force — like a seesaw, scissors, or a crowbar.", "bis": "Ang lever usa ka gahi nga olang nga molihok sa usa ka punto nga gitawag og fulcrum. Gigamit kini aron pag-alsa og bug-at gamit ang mas gamay nga force — sama sa seesaw, gunting, o barita (crowbar)."}, "source": "DepEd Science CG (FME); AAAS BSL Ch.8", "generator": "claude", "reviewed": false},
  {"id": "fme-lenses-mirrors-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "lenses and mirrors", "grades": [6, 7], "terms": ["lens", "mirror", "light", "reflection", "magnify", "nagbabalik", "repleksyon", "palakihin", "antiyohos", "materyal", "padakuon", "pokuhin", "larawan", "reflect", "nagbabaluktot"], "fact": {"tl": "Ang lens ay malinaw na materyal (tulad ng salamin) na nagbabaluktot ng liwanag para palakihin o pa-pokuhin ang larawan — ginagamit sa salamin sa mata at magnifying glass. Ang mirror naman ay nagbabalik (reflect) ng liwanag para makita natin ang repleksyon.", "en": "A lens is a clear material (like glass) that bends light to enlarge or focus an image — used in eyeglasses and magnifying glasses. A mirror reflects light so we see a reflection.", "bis": "Ang lens usa ka tin-aw nga materyal (sama sa salamin) nga mobawog sa kahayag aron padakuon o i-focus ang hulagway — gigamit sa antiyohos ug magnifying glass. Ang mirror mobalik (reflect) sa kahayag aron makita nato ang repleksyon."}, "source": "NRC PS4.B (light)", "generator": "claude", "reviewed": false},
  {"id": "fme-electromagnet-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "electromagnet", "grades": [7, 8], "terms": ["electromagnet", "electricity", "magnetism", "coil", "nakapulupot", "pinatay", "giliyok", "patyon", "pagka", "motor", "crane", "gihimo", "dumaloy", "nawawala"], "fact": {"tl": "Ang electromagnet ay magnet na gawa gamit ang kuryente — kapag dumaloy ang kuryente sa wire na nakapulupot sa bakal, nagiging magnet ito; kapag pinatay ang kuryente, nawawala ang pagka-magnet. Ginagamit ito sa mga motor at junkyard crane.", "en": "An electromagnet is a magnet made using electricity — when current flows through a wire coiled around iron, it becomes a magnet; turn the current off and the magnetism stops. It is used in motors and junkyard cranes.", "bis": "Ang electromagnet usa ka magnet nga gihimo gamit ang kuryente — kung moagos ang kuryente sa wire nga giliyok sa puthaw, mahimo kining magnet; kung patyon ang kuryente, mawala ang pagka-magnet. Gigamit kini sa mga motor ug junkyard crane."}, "source": "NRC PS2.B; AAAS BSL Ch.4G", "generator": "claude", "reviewed": false},
  {"id": "fme-friction-uses-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "useful and harmful friction", "grades": [5, 6], "terms": ["friction", "grip", "brakes", "wear", "nadaragdagan", "nakakaabala", "nagpapaubos", "nababawasan", "madugangan", "makasamok", "mokutkot", "sapatos", "preno", "pakinabang"], "fact": {"tl": "Minsan kapaki-pakinabang ang friction (tulad ng grip ng sapatos at preno ng sasakyan), at minsan nakakaabala (nagpapaubos ng gamit at gumagawa ng init). Nababawasan ang friction gamit ang langis o gulong; nadaragdagan gamit ang magaspang na ibabaw.", "en": "Sometimes friction is useful (like the grip of shoes and a car's brakes), and sometimes it is a nuisance (it wears things out and makes heat). Friction is reduced with oil or wheels; it is increased with rough surfaces.", "bis": "Usahay mapuslanon ang friction (sama sa grip sa sapatos ug preno sa sakyanan), ug usahay makasamok (mokutkot sa gamit ug maghimo og kainit). Makunhuran ang friction gamit ang lana o ligid; madugangan gamit ang gansang nga nawong."}, "source": "NRC PS2.A", "generator": "claude", "reviewed": false},
  {"id": "earth-groundwater-g6", "domain": "EARTH_SPACE", "topic": "groundwater", "grades": [6, 7], "terms": ["groundwater", "well", "underground", "water"], "fact": {"tl": "Ang ilang tubig-ulan ay sumisipsip sa lupa at naiimbak sa ilalim sa pagitan ng mga bato at buhangin — ito ang groundwater. Kinukuha natin ito gamit ang poso o balon (well) para inumin at pang-irigasyon.", "en": "Some rainwater soaks into the ground and is stored underground between rocks and sand — this is groundwater. We get it using wells for drinking and irrigation.", "bis": "Ang ubang tubig-ulan mosuyop sa yuta ug matipig sa ilalom taliwala sa mga bato ug balas — kini ang groundwater. Kuhaon nato kini gamit ang atabay (well) para imnon ug irigasyon."}, "source": "NRC ESS2.C", "generator": "claude", "reviewed": false},
  {"id": "earth-ocean-currents-g7", "domain": "EARTH_SPACE", "topic": "ocean currents", "grades": [7, 8], "terms": ["ocean current", "heat", "climate", "sea", "kaparat", "nakakaapekto", "makaapekto", "kalainan", "magdala", "ilog", "alat", "suba", "pagkakaiba", "kalibutan"], "fact": {"tl": "Ang ocean currents ay parang mga 'ilog' sa loob ng dagat na gumagalaw dahil sa hangin, init, at pagkakaiba ng alat at temperatura. Nagdadala ang mga ito ng init sa buong mundo at nakakaapekto sa klima.", "en": "Ocean currents are like 'rivers' within the sea that move because of wind, heat, and differences in saltiness and temperature. They carry heat around the world and affect climate.", "bis": "Ang ocean currents sama sa mga 'suba' sa sulod sa dagat nga molihok tungod sa hangin, kainit, ug kalainan sa kaparat ug temperatura. Magdala kini og kainit sa tibuok kalibutan ug makaapekto sa klima."}, "source": "NRC ESS2.D", "generator": "claude", "reviewed": false},
  {"id": "earth-habagat-amihan-g6", "domain": "EARTH_SPACE", "topic": "monsoons habagat and amihan", "grades": [5, 6, 7], "terms": ["monsoon", "habagat", "amihan", "wind", "season"], "fact": {"tl": "Sa Pilipinas, may dalawang monsoon: ang habagat (timog-kanlurang hangin, mga Hunyo–Setyembre, nagdadala ng ulan) at ang amihan (hilagang-silangang hangin, mga Oktubre–Marso, malamig at tuyo). Ang mga ito ang nagtatakda ng panahon natin.", "en": "In the Philippines there are two monsoons: the habagat (southwest wind, about June–September, bringing rain) and the amihan (northeast wind, about October–March, cool and dry). They set our seasons.", "bis": "Sa Pilipinas, adunay duha ka monsoon: ang habagat (habagatan-kasadpan nga hangin, mga Hunyo–Setyembre, modala og ulan) ug ang amihan (amihanan-sidlakan nga hangin, mga Oktubre–Marso, bugnaw ug uga). Kini maoy magtakda sa atong panahon."}, "source": "NRC ESS2.D (climate); DepEd Science CG", "generator": "claude", "reviewed": false},
  {"id": "earth-ph-volcanoes-g6", "domain": "EARTH_SPACE", "topic": "Philippine volcanoes", "grades": [5, 6, 7], "terms": ["volcano", "Mayon", "Taal", "Pinatubo", "Ring of Fire", "pinakagamay", "perpektong", "bantogan", "kilala", "mibuto", "ilado", "niadtong", "hapit", "kono", "sumabog"], "fact": {"tl": "Maraming bulkan sa Pilipinas dahil nasa Pacific Ring of Fire ito. Kabilang sa mga sikat: ang Mayon (kilala sa halos perpektong hugis-kono), ang Taal (isa sa pinakamaliit sa mundo), at ang Pinatubo (sumabog nang malakas noong 1991).", "en": "The Philippines has many volcanoes because it sits on the Pacific Ring of Fire. Famous ones include Mayon (known for its near-perfect cone shape), Taal (one of the smallest in the world), and Pinatubo (which erupted powerfully in 1991).", "bis": "Daghang bulkan sa Pilipinas kay anaa kini sa Pacific Ring of Fire. Lakip sa bantogan: ang Mayon (ilado sa hapit hingpit nga porma-kono), ang Taal (usa sa pinakagamay sa kalibutan), ug ang Pinatubo (mibuto og kusog niadtong 1991)."}, "source": "NRC ESS2.B; DepEd Science CG", "generator": "claude", "reviewed": false},
  {"id": "earth-minerals-vs-rocks-g6", "domain": "EARTH_SPACE", "topic": "minerals and rocks", "grades": [6, 7], "terms": ["mineral", "rock", "quartz", "composition", "komposisyon", "magkakasama", "magkauban", "kuwarts", "bulawan", "ginto", "iisang", "higit", "asin", "hinimo"], "fact": {"tl": "Ang mineral ay natural na solid na may iisang uri ng komposisyon (tulad ng kuwarts, ginto, at asin-bato). Ang bato (rock) ay gawa sa isa o higit pang mineral na magkakasama. Kaya ang mineral ang building blocks ng mga bato.", "en": "A mineral is a natural solid with one kind of composition (like quartz, gold, and rock salt). A rock is made of one or more minerals together. So minerals are the building blocks of rocks.", "bis": "Ang mineral usa ka natural nga solid nga adunay usa ka klase nga komposisyon (sama sa kuwarts, bulawan, ug asin-bato). Ang bato (rock) hinimo sa usa o sobra pa nga mineral nga magkauban. Mao nga ang mineral mao ang building blocks sa mga bato."}, "source": "NRC ESS2.A", "generator": "claude", "reviewed": false},
  {"id": "earth-constellations-g5", "domain": "EARTH_SPACE", "topic": "constellations", "grades": [5, 6], "terms": ["constellation", "stars", "pattern", "Orion", "paglalakbay", "sinaunang", "pagsasaka", "ginganlan", "pagbiyahe", "binigyan", "pangalan", "kaniadto", "gabay", "noon"], "fact": {"tl": "Ang constellation ay grupo ng mga bituin na bumubuo ng parang larawan sa langit, na binigyan ng pangalan ng mga sinaunang tao (tulad ng Orion at Southern Cross). Ginagamit ito noon bilang gabay sa paglalakbay at pagsasaka.", "en": "A constellation is a group of stars that forms a picture-like pattern in the sky, named by ancient people (like Orion and the Southern Cross). It was once used as a guide for travel and farming.", "bis": "Ang constellation usa ka grupo sa mga bituon nga maghimo og morag hulagway sa langit, nga ginganlan sa karaang mga tawo (sama sa Orion ug Southern Cross). Gigamit kini kaniadto isip giya sa pagbiyahe ug pag-uma."}, "source": "AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "faq-where-sun-goes-night", "domain": "EARTH_SPACE", "topic": "where the sun goes at night", "grades": [3, 4], "terms": ["sun", "night", "rotation", "Earth", "umaalis", "mobiya", "tumatalikod", "motalikod", "panig", "kalibutan", "pikas", "gyud", "kabilang", "mundo"], "fact": {"tl": "Hindi talaga 'umaalis' ang araw sa gabi — umiikot lang ang Earth, kaya tumatalikod ang ating panig sa araw. Habang gabi sa atin, araw naman sa kabilang panig ng mundo.", "en": "The sun does not really 'go away' at night — the Earth just turns, so our side faces away from the sun. While it is night for us, it is day on the other side of the world.", "bis": "Wala gyud 'mobiya' ang adlaw sa gabii — molibot lang ang Earth, mao nga motalikod ang atong bahin sa adlaw. Samtang gabii kanato, adlaw sa pikas bahin sa kalibutan."}, "source": "AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "faq-how-electricity-made", "domain": "FORCE_MOTION_ENERGY", "topic": "how electricity is generated", "grades": [6, 7], "terms": ["electricity", "generator", "turbine", "power plant", "pinapaikot", "gipatuyok", "pagtuyok", "ikot", "nagaagos", "gihimo", "bahay", "balay", "wire", "kadaghanan"], "fact": {"tl": "Karamihan ng kuryente ay ginagawa sa power plant gamit ang generator: pinapaikot ang isang turbine (gamit ang singaw, umaagos na tubig, o hangin), at ang pag-ikot na ito ay nagbibigay ng electrical energy na dumadaloy sa mga wire papunta sa ating mga bahay.", "en": "Most electricity is made in a power plant using a generator: a turbine is spun (by steam, flowing water, or wind), and that spinning produces electrical energy that flows through wires to our homes.", "bis": "Kadaghanan sa kuryente gihimo sa power plant gamit ang generator: gipatuyok ang usa ka turbine (gamit ang alisngaw, nagaagos nga tubig, o hangin), ug kana nga pagtuyok maghatag og electrical energy nga moagos sa mga wire paingon sa atong mga balay."}, "source": "NRC PS3.A", "generator": "claude", "reviewed": false},
  {"id": "faq-why-metal-hot-in-sun", "domain": "FORCE_MOTION_ENERGY", "topic": "why metal feels hot in the sun", "grades": [5, 6], "terms": ["metal", "heat", "conductor", "sun", "sumipsip", "hikapon", "hawakan", "maayo", "mahusay", "uminit", "labas", "mosuyop", "parehas", "moinit"], "fact": {"tl": "Mas mabilis uminit ang metal sa araw dahil mahusay itong conductor ng init at mabilis sumipsip ng init mula sa araw. Kaya mas mainit hawakan ang metal kaysa kahoy kahit pareho silang nasa labas.", "en": "Metal heats up quickly in the sun because it is a good conductor of heat and absorbs the sun's heat fast. That is why metal feels hotter to touch than wood, even when both are outside.", "bis": "Mas paspas moinit ang metal sa adlaw kay maayo kining conductor sa kainit ug paspas mosuyop sa kainit gikan sa adlaw. Mao nga mas init hikapon ang metal kaysa kahoy bisan parehas silang naa sa gawas."}, "source": "NRC PS3.B (heat)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-water-steams", "domain": "MATTER", "topic": "why hot water steams", "grades": [5, 6], "terms": ["steam", "evaporation", "condensation", "vapor"], "fact": {"tl": "Umuusok ang mainit na tubig dahil sumisingaw (evaporation) ito, at kapag ang mainit na singaw ay tumama sa malamig na hangin, nagiging maliliit na patak ito muli (condensation) na nakikita natin bilang 'usok' o singaw.", "en": "Hot water 'steams' because it evaporates, and when the hot vapor meets cooler air it turns back into tiny droplets (condensation) that we see as 'steam'.", "bis": "Moaso ang init nga tubig kay mo-alisngaw (evaporation) kini, ug kung ang init nga alisngaw motagbo sa bugnaw nga hangin, mahimo kining gagmay nga tulo pag-usab (condensation) nga atong makita isip 'aso' o alisngaw."}, "source": "AAAS BSL Ch.4D", "generator": "claude", "reviewed": false},
  {"id": "faq-why-we-eat", "domain": "LIVING_THINGS", "topic": "why we eat", "grades": [3, 4], "terms": ["kumakain", "kaon", "mokaon", "pagkaon", "eat", "food", "energy", "enerhiya", "nutrients", "sustansya"], "fact": {"tl": "Kumakain tayo para makakuha ng enerhiya at sustansya (nutrients) na kailangan ng katawan para gumalaw, lumaki, at ayusin ang sarili. Ang pagkain ang parang 'gasolina' ng katawan.", "en": "We eat to get energy and nutrients the body needs to move, grow, and repair itself. Food is like the body's 'fuel'.", "bis": "Mokaon ta aron makakuha og enerhiya ug sustansya (nutrients) nga gikinahanglan sa lawas aron molihok, motubo, ug ayohon ang kaugalingon. Ang pagkaon sama sa 'gasolina' sa lawas."}, "source": "AAAS BSL Ch.6; NRC LS1.C", "generator": "claude", "reviewed": false},
  {"id": "faq-why-we-sleep", "domain": "LIVING_THINGS", "topic": "why we sleep", "grades": [3, 4], "terms": ["natutulog", "tulog", "matulog", "sleep", "rest", "pahinga", "utak", "utok", "brain"], "fact": {"tl": "Natutulog tayo para makapagpahinga at makabawi ang katawan at utak. Habang tulog, naaayos ang mga cell, lumalakas ang immune system, at iniimbak ng utak ang mga natutunan natin.", "en": "We sleep so the body and brain can rest and recover. During sleep, cells repair, the immune system strengthens, and the brain stores what we learned.", "bis": "Matulog ta aron makapahulay ug makabawi ang lawas ug utok. Samtang natulog, mareparar ang mga cell, molig-on ang immune system, ug tipigan sa utok ang atong nakat-unan."}, "source": "AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "faq-how-birds-fly", "domain": "FORCE_MOTION_ENERGY", "topic": "how birds and planes fly", "grades": [5, 6], "terms": ["lumilipad", "lupad", "molupad", "fly", "ibon", "langgam", "bird", "eroplano", "airplane", "pakpak", "pako", "wings", "lift"], "fact": {"tl": "Lumilipad ang ibon at eroplano dahil sa hugis ng kanilang pakpak (wings): mas mabilis dumaloy ang hangin sa ibabaw ng pakpak kaysa sa ilalim, na lumilikha ng lift na nagtataas sa kanila.", "en": "Birds and planes fly because of the shape of their wings: air flows faster over the top of the wing than underneath, creating lift that pushes them up.", "bis": "Molupad ang langgam ug eroplano tungod sa porma sa ilang pako (wings): mas paspas moagos ang hangin sa ibabaw sa pako kaysa sa ilawom, nga maghimo og lift nga mopataas kanila."}, "source": "NRC PS2 (forces); AAAS BSL Ch.8", "generator": "claude", "reviewed": false},
  {"id": "faq-why-rocks-sink", "domain": "MATTER", "topic": "why rocks sink", "grades": [4, 5], "terms": ["lumulubog", "lubog", "molunod", "sink", "bato", "rock", "density", "mabigat", "bug-at"], "fact": {"tl": "Lumulubog ang bato dahil mas siksik (mas mataas ang density) ito kaysa tubig — mas mabigat ang bato kaysa katumbas nitong dami ng tubig, kaya bumababa ito.", "en": "A rock sinks because it is denser (higher density) than water — the rock is heavier than the same amount of water, so it goes down.", "bis": "Molunod ang bato kay mas siksik (mas taas ang density) kini kaysa tubig — mas bug-at ang bato kaysa katumbas niini nga gidaghanon sa tubig, mao nga mokanaog kini."}, "source": "AAAS BSL Ch.4D (density)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-we-feel-cold", "domain": "FORCE_MOTION_ENERGY", "topic": "why we feel cold", "grades": [4, 5], "terms": ["nilalamig", "lamig", "tugnaw", "cold", "init", "heat", "temperatura", "nanginginig", "kurog", "shiver"], "fact": {"tl": "Nilalamig tayo kapag mas mababa ang temperatura ng paligid kaysa katawan, kaya tumatakas ang init mula sa atin. Nanginginig tayo para gumawa ng init at magpainit ng katawan.", "en": "We feel cold when the surroundings are colder than our body, so heat escapes from us. We shiver to make heat and warm the body.", "bis": "Tugnawon ta kung mas ubos ang temperatura sa palibot kaysa lawas, mao nga mogawas ang kainit gikan kanato. Mokurog ta aron maghimo og kainit ug painiton ang lawas."}, "source": "NRC PS3.B (heat)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-it-rains", "domain": "EARTH_SPACE", "topic": "why it rains", "grades": [3, 4], "terms": ["umuulan", "ulan", "moulan", "rain", "ulap", "panganod", "clouds", "patak", "tulo"], "fact": {"tl": "Umuulan kapag ang mga patak ng tubig sa ulap ay nagsasama-sama at lumalaki, hanggang sa maging masyadong mabigat para lumutang — kaya bumabagsak sila bilang ulan.", "en": "It rains when the tiny water droplets in clouds join and grow until they are too heavy to float — so they fall as rain.", "bis": "Moulan kung ang mga tulo sa tubig sa panganod magtapok ug modako, hangtod nga mabug-at na kaayo aron molutaw — mao nga mahulog sila isip ulan."}, "source": "AAAS BSL Ch.4B (water cycle)", "generator": "claude", "reviewed": false},
  {"id": "faq-where-wind-comes-from", "domain": "EARTH_SPACE", "topic": "where wind comes from", "grades": [4, 5], "terms": ["hangin", "wind", "init", "heat", "habagat", "amihan", "air", "galaw"], "fact": {"tl": "Galing ang hangin sa hindi pantay na pag-init ng araw sa Earth. Ang mainit na hangin ay tumataas, at ang malamig na hangin ay pumapalit dito — ang paggalaw na ito ng hangin ang tinatawag nating hangin.", "en": "Wind comes from the uneven heating of Earth by the sun. Warm air rises and cooler air moves in to take its place — that moving air is wind.", "bis": "Naggikan ang hangin sa dili patas nga pag-init sa adlaw sa Earth. Ang init nga hangin mosaka, ug ang bugnaw nga hangin mopuli niini — kana nga paglihok sa hangin mao ang gitawag natong hangin."}, "source": "AAAS BSL Ch.4B", "generator": "claude", "reviewed": false},
  {"id": "faq-how-plants-grow", "domain": "LIVING_THINGS", "topic": "how plants grow", "grades": [3, 4], "terms": ["tumutubo", "tubo", "motubo", "grow", "halaman", "tanom", "plant", "buto", "liso", "seed", "photosynthesis"], "fact": {"tl": "Tumutubo ang halaman mula sa buto kapag may tubig, hangin, init, at liwanag. Gumagawa ito ng sariling pagkain sa photosynthesis, na nagpapalaki ng ugat, tangkay, at dahon.", "en": "A plant grows from a seed when there is water, air, warmth, and light. It makes its own food by photosynthesis, which grows its roots, stem, and leaves.", "bis": "Motubo ang tanom gikan sa liso kung adunay tubig, hangin, kainit, ug kahayag. Maghimo kini og kaugalingong pagkaon pinaagi sa photosynthesis, nga magpadako sa gamot, punoan, ug dahon."}, "source": "AAAS BSL Ch.5; NRC LS1", "generator": "claude", "reviewed": false},
  {"id": "faq-why-leaves-fall", "domain": "LIVING_THINGS", "topic": "why leaves fall", "grades": [4, 5], "terms": ["nalalagas", "laglag", "kahulog", "dahon", "leaves", "fall", "matanda", "tigulang"], "fact": {"tl": "Nalalagas ang mga dahon kapag matanda na ang mga ito o kapag kulang sa tubig at liwanag ang halaman — itinatapon ng halaman ang lumang dahon para makatipid ng enerhiya at makapagpalago ng bago.", "en": "Leaves fall when they grow old or when the plant lacks water and light — the plant drops old leaves to save energy and grow new ones.", "bis": "Mangahulog ang mga dahon kung tigulang na o kung kulang sa tubig ug kahayag ang tanom — ilabay sa tanom ang daan nga dahon aron makatipig og enerhiya ug makapatubo og bag-o."}, "source": "AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "faq-why-sky-dark-night", "domain": "EARTH_SPACE", "topic": "why the sky is dark at night", "grades": [4, 5], "terms": ["madilim", "langit", "gabi", "ngitngit", "dark", "night", "liwanag", "araw", "sun"], "fact": {"tl": "Madilim ang langit sa gabi dahil tumatalikod ang ating panig ng Earth sa araw, kaya walang sikat ng araw na ikinakalat ng hangin para gawing maliwanag ang langit.", "en": "The sky is dark at night because our side of Earth faces away from the sun, so there is no sunlight for the air to scatter and brighten the sky.", "bis": "Ngitngit ang langit sa gabii kay motalikod ang atong bahin sa Earth sa adlaw, mao nga walay silaw sa adlaw nga ikatag sa hangin aron pahayagon ang langit."}, "source": "AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "faq-how-fish-breathe", "domain": "LIVING_THINGS", "topic": "how fish breathe", "grades": [4, 5], "terms": ["isda", "fish", "huminga", "ginhawa", "hasang", "gills", "oxygen", "tubig", "underwater"], "fact": {"tl": "Humihinga ang isda gamit ang hasang (gills), hindi baga. Dumadaan ang tubig sa hasang, at kinukuha nito ang oxygen na natunaw sa tubig — kaya nabubuhay ang isda sa ilalim ng tubig.", "en": "Fish breathe using gills, not lungs. Water passes through the gills, which take in the oxygen dissolved in the water — that is how fish live underwater.", "bis": "Moginhawa ang isda gamit ang hasang (gills), dili baga. Moagi ang tubig sa hasang, ug kuhaon niini ang oxygen nga natunaw sa tubig — mao nga mabuhi ang isda sa ilawom sa tubig."}, "source": "AAAS BSL Ch.5; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "faq-why-stars-not-day", "domain": "EARTH_SPACE", "topic": "why we don't see stars in daytime", "grades": [4, 5], "terms": ["bituin", "bituon", "stars", "araw", "day", "adlaw", "liwanag", "hayag"], "fact": {"tl": "Hindi natin nakikita ang mga bituin sa araw dahil masyadong maliwanag ang langit mula sa sikat ng araw. Naroon pa rin ang mga bituin — natatabunan lang sila ng maliwanag na langit.", "en": "We don't see stars in the daytime because the sky is too bright from sunlight. The stars are still there — they are just hidden by the bright sky.", "bis": "Dili nato makita ang mga bituon sa adlaw kay sobra ka hayag ang langit gikan sa silaw sa adlaw. Naa pa gihapon ang mga bituon — gitabonan lang sila sa hayag nga langit."}, "source": "AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "faq-why-astronauts-float", "domain": "EARTH_SPACE", "topic": "why astronauts float in space", "grades": [6, 7], "terms": ["astronaut", "lumulutang", "lutaw", "float", "space", "gravity", "weightless", "bigat"], "fact": {"tl": "Lumulutang ang astronaut dahil sila at ang kanilang spaceship ay parehong patuloy na 'nahuhulog' papunta sa Earth habang umiikot sa paligid nito — kaya wala silang nararamdamang bigat (weightless), hindi dahil walang gravity sa space.", "en": "Astronauts float because they and their spaceship are both constantly 'falling' toward Earth while circling around it — so they feel weightless. It is not because there is no gravity in space.", "bis": "Molutaw ang astronaut kay sila ug ang ilang spaceship parehong padayon nga 'nahulog' paingon sa Earth samtang molibot niini — mao nga wala silay bati nga gibug-aton (weightless), dili tungod kay walay gravity sa space."}, "source": "NRC PS2.B (gravity)", "generator": "claude", "reviewed": false},
  {"id": "faq-why-moon-follows", "domain": "EARTH_SPACE", "topic": "why the moon seems to follow you", "grades": [4, 5], "terms": ["buwan", "bulan", "moon", "sumusunod", "sunod", "follow", "layo"], "fact": {"tl": "Parang sumusunod ang buwan habang naglalakad ka dahil napakalayo nito — hindi gaanong nagbabago ang anggulo ng tingin mo dito kahit gumagalaw ka, kaya mukhang kasabay mo ito.", "en": "The moon seems to follow you as you walk because it is so far away — your viewing angle to it barely changes even as you move, so it looks like it is keeping pace with you.", "bis": "Morag mosunod ang bulan samtang naglakaw ka kay layo kaayo kini — dili kaayo mausab ang anggulo sa imong pagtan-aw niini bisan molihok ka, mao nga morag kauban nimo kini."}, "source": "AAAS BSL Ch.4A", "generator": "claude", "reviewed": false},
  {"id": "faq-why-not-fall-off-earth", "domain": "EARTH_SPACE", "topic": "why we don't fall off the Earth", "grades": [4, 5], "terms": ["gravity", "Earth", "nahuhulog", "hulog", "fall", "bilog", "lingin", "round", "gitna", "tunga"], "fact": {"tl": "Hindi tayo nahuhulog mula sa Earth kahit bilog ito dahil hinihila tayo ng gravity papunta sa gitna ng planeta — kaya 'pababa' para sa atin ay laging papunta sa gitna ng Earth, saan man tayo nakatayo.", "en": "We don't fall off the Earth even though it is round because gravity pulls us toward the center of the planet — so 'down' for us is always toward Earth's center, no matter where we stand.", "bis": "Dili ta mahulog gikan sa Earth bisan lingin kini kay gibira ta sa gravity paingon sa tunga sa planeta — mao nga ang 'paubos' para kanato kanunay paingon sa tunga sa Earth, bisan asa ta magbarog."}, "source": "NRC PS2.B (gravity)", "generator": "claude", "reviewed": false},
  {"id": "living-digestion-enzymes-g6", "domain": "LIVING_THINGS", "topic": "digestion and enzymes", "grades": [6, 7], "terms": ["enzyme", "laway", "saliva", "digestion", "tunaw", "hilis", "starch", "almirol", "kanin"], "fact": {"tl": "Tumutulong ang mga enzyme sa pagtunaw ng pagkain. Halimbawa, may enzyme sa laway (saliva) na nagsisimulang maglansag ng starch (almirol) sa bibig — kaya tumatamis ang kanin kapag matagal mong nginuya.", "en": "Enzymes help digest food. For example, an enzyme in saliva begins breaking down starch in the mouth — which is why rice tastes sweet if you chew it for a while.", "bis": "Motabang ang mga enzyme sa paghilis sa pagkaon. Pananglitan, adunay enzyme sa laway (saliva) nga mosugod sa pagguba sa starch (almidor) sa baba — mao nga motam-is ang kan-on kung dugay nimong usapon."}, "source": "AAAS BSL Ch.6; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "living-blood-cells-g7", "domain": "LIVING_THINGS", "topic": "blood cells", "grades": [7, 8], "terms": ["dugo", "blood", "red blood cells", "white blood cells", "platelets", "oxygen", "cell"], "fact": {"tl": "May tatlong uri ng cell sa dugo: ang red blood cells (nagdadala ng oxygen), ang white blood cells (lumalaban sa sakit), at ang platelets (tumutulong sa pamumuo ng dugo kapag may sugat).", "en": "There are three kinds of cells in blood: red blood cells (carry oxygen), white blood cells (fight disease), and platelets (help blood clot when there is a wound).", "bis": "Adunay tulo ka klase sa cell sa dugo: ang red blood cells (modala og oxygen), ang white blood cells (mosukol sa sakit), ug ang platelets (motabang sa pagmugna sa dugo kung adunay samad)."}, "source": "AAAS BSL Ch.6; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "earth-dew-frost-g6", "domain": "EARTH_SPACE", "topic": "dew and frost", "grades": [5, 6], "terms": ["hamog", "yamog", "dew", "frost", "condensation", "yelo", "damo"], "fact": {"tl": "Ang hamog (dew) ay tubig na nabubuo kapag ang singaw sa hangin ay lumamig at nagiging patak sa mga damo sa umaga (condensation). Kapag napakalamig (below 0°C), nagiging frost o namuong yelo ito.", "en": "Dew is water that forms when vapor in the air cools and becomes droplets on grass in the morning (condensation). When it is very cold (below 0°C), it becomes frost (frozen dew).", "bis": "Ang yamog (dew) mao ang tubig nga maporma kung ang alisngaw sa hangin mobugnaw ug mahimong tulo sa mga sagbot sa buntag (condensation). Kung bugnaw kaayo (ubos sa 0°C), mahimo kining frost o nagyelo nga yamog."}, "source": "AAAS BSL Ch.4B", "generator": "claude", "reviewed": false},
  {"id": "earth-lightning-g6", "domain": "EARTH_SPACE", "topic": "how lightning forms", "grades": [6, 7], "terms": ["kidlat", "kilat", "lightning", "static electricity", "charge", "ulap", "panganod", "kuryente"], "fact": {"tl": "Ang kidlat (lightning) ay isang malaking static electricity na lumalabas sa pagitan ng mga ulap o sa pagitan ng ulap at lupa, kapag napakaraming charge na ang naipon sa loob ng bagyo.", "en": "Lightning is a giant spark of static electricity that jumps between clouds, or between a cloud and the ground, when a lot of charge has built up inside a storm.", "bis": "Ang kilat (lightning) usa ka dako nga static electricity nga mogawas tali sa mga panganod o tali sa panganod ug yuta, kung daghan na kaayong charge ang natigom sulod sa unos."}, "source": "AAAS BSL Ch.4G", "generator": "claude", "reviewed": false},
  {"id": "earth-fog-g5", "domain": "EARTH_SPACE", "topic": "fog", "grades": [5, 6], "terms": ["fog", "gabon", "ambon", "ulap", "panganod", "singaw", "alisngaw", "condensation"], "fact": {"tl": "Ang ulap-lupa o fog ay parang ulap na nasa lupa: nabubuo ito kapag ang singaw ng tubig sa malamig na hangin ay nagiging maliliit na patak na lumulutang malapit sa lupa, kaya nahihirapan tayong makakita.", "en": "Fog is like a cloud at ground level: it forms when water vapor in cool air becomes tiny droplets floating near the ground, making it hard to see.", "bis": "Ang gabon o fog sama sa panganod nga anaa sa yuta: maporma kini kung ang alisngaw sa tubig sa bugnaw nga hangin mahimong gagmay nga tulo nga molutaw duol sa yuta, mao nga maglisod ta og kita."}, "source": "AAAS BSL Ch.4B", "generator": "claude", "reviewed": false},
  {"id": "matter-oil-water-g6", "domain": "MATTER", "topic": "why oil and water don't mix", "grades": [5, 6], "terms": ["langis", "oil", "tubig", "water", "halo", "sagol", "mix", "density", "lutaw"], "fact": {"tl": "Hindi naghahalo ang langis at tubig dahil magkaiba ang kanilang particle at hindi sila 'magkadikit' — kaya naghihiwalay sila. Lumulutang ang langis sa ibabaw dahil mas magaan (mas mababa ang density) ito kaysa tubig.", "en": "Oil and water do not mix because their particles are different and do not 'stick' to each other — so they separate. Oil floats on top because it is lighter (less dense) than water.", "bis": "Dili magsagol ang lana ug tubig kay lahi ang ilang particle ug dili sila 'magdikit' — mao nga magbulag sila. Molutaw ang lana sa ibabaw kay mas gaan (mas ubos ang density) kini kaysa tubig."}, "source": "AAAS BSL Ch.4D", "generator": "claude", "reviewed": false},
  {"id": "matter-metals-expand-g7", "domain": "MATTER", "topic": "why metals expand when heated", "grades": [6, 7], "terms": ["metal", "expand", "lumalaki", "modako", "init", "heat", "particle", "urong", "contract"], "fact": {"tl": "Lumalaki (expand) ang metal kapag iniinit at umuurong kapag pinalamig, dahil mas mabilis gumalaw at lumalayo ang mga particle nito sa init. Kaya may maliliit na puwang sa mga tulay at riles ng tren para sa pag-expand.", "en": "Metal expands when heated and contracts when cooled, because its particles move faster and spread apart with heat. That is why bridges and train rails have small gaps to allow for expansion.", "bis": "Modako (expand) ang metal kung initan ug mokunhod kung bugnawon, kay mas paspas molihok ug magkalayo ang mga particle niini sa kainit. Mao nga adunay gamay nga luna sa mga taytayan ug riles sa tren para sa pag-expand."}, "source": "AAAS BSL Ch.4D; NRC PS3", "generator": "claude", "reviewed": false},
  {"id": "living-photosynthesis-respiration-pair-g7", "domain": "LIVING_THINGS", "topic": "photosynthesis and respiration", "grades": [7, 8], "terms": ["photosynthesis", "respiration", "oxygen", "carbon dioxide", "halaman", "tanom", "enerhiya", "siklo"], "fact": {"tl": "Magkaugnay ang photosynthesis at respiration: sa photosynthesis, gumagawa ang halaman ng pagkain at oxygen mula sa carbon dioxide at tubig; sa respiration, ginagamit ng halaman at hayop ang oxygen at pagkain para sa enerhiya at naglalabas ng carbon dioxide. Magkasalungat sila pero magkatuwang sa siklo ng buhay.", "en": "Photosynthesis and respiration are linked: in photosynthesis, plants make food and oxygen from carbon dioxide and water; in respiration, plants and animals use oxygen and food for energy and release carbon dioxide. They are opposites that together keep the cycle of life going.", "bis": "Magkadugtong ang photosynthesis ug respiration: sa photosynthesis, maghimo ang tanom og pagkaon ug oxygen gikan sa carbon dioxide ug tubig; sa respiration, gigamit sa tanom ug hayop ang oxygen ug pagkaon para sa enerhiya ug magbuga og carbon dioxide. Sukwahi sila apan magtinabangay sa siklo sa kinabuhi."}, "source": "NRC LS1.C; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "living-why-we-grow", "domain": "LIVING_THINGS", "topic": "why we grow", "grades": [4, 5], "terms": ["lumalaki", "tubo", "motubo", "grow", "cell", "protina", "protein", "pagkaon", "building blocks"], "fact": {"tl": "Lumalaki tayo dahil dumarami at lumalaki ang mga cell sa ating katawan. Galing sa pagkain ang mga 'building blocks' (lalo na ang protina) na kailangan para magdagdag ng bagong cell — kaya mahalaga ang masustansyang pagkain sa paglaki.", "en": "We grow because the cells in our body multiply and get bigger. Food provides the 'building blocks' (especially protein) needed to make new cells — so nutritious food is important for growing.", "bis": "Motubo ta kay modaghan ug modako ang mga cell sa atong lawas. Gikan sa pagkaon ang mga 'building blocks' (ilabi na ang protina) nga gikinahanglan aron magdugang og bag-ong cell — mao nga importante ang masustansya nga pagkaon sa pagtubo."}, "source": "AAAS BSL Ch.6; NRC LS1.B", "generator": "claude", "reviewed": false},
  {"id": "why-soap-cleans-g4", "domain": "MATTER", "topic": "why soap cleans", "grades": [3, 4, 5], "terms": ["sabon", "soap", "langis", "grease", "oil", "dumi", "hugaw", "dirt", "linis", "limpyo", "clean", "molekula"], "fact": {"tl": "Ang sabon ay may mga molekula na ang isang dulo ay kumakapit sa tubig at ang kabilang dulo ay kumakapit sa langis. Kaya nahihila ng sabon ang mantika at dumi palayo sa balat o pinggan, at natatangay ng tubig kapag binanlawan.", "en": "Soap molecules have one end that clings to water and another end that clings to oil. So soap lifts grease and dirt off your skin or dishes, and the water rinses it all away.", "bis": "Ang sabon adunay mga molekula nga ang usa ka tumoy mokupot sa tubig ug ang pikas tumoy mokupot sa lana. Maong makuha sa sabon ang mantika ug hugaw gikan sa panit o plato, ug mabanlasan kini sa tubig."}, "source": "AAAS BSL Ch.4; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "why-bubbles-round-g3", "domain": "MATTER", "topic": "why bubbles are round", "grades": [3, 4], "terms": ["bula", "bubble", "bilog", "lingin", "round", "surface tension", "sabon", "soap", "hangin", "hangin"], "fact": {"tl": "Bilog ang bula dahil hinihila ng surface tension ang manipis na pelikula ng sabon papunta sa pinakamaliit na hugis. Ang bilog (sphere) ang nakakahawak ng pinakamaraming hangin gamit ang pinakaliit na ibabaw.", "en": "Bubbles are round because surface tension pulls the thin soap film into the smallest shape possible, and a sphere holds the most air with the least surface area.", "bis": "Lingin ang bula tungod kay ang surface tension nagbira sa nipis nga pelikula sa sabon ngadto sa kinagamyan nga porma. Ang lingin (sphere) maoy makasulod sa kinadaghanan nga hangin gamit ang kinagamyan nga gawas."}, "source": "AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "surface-tension-g4", "domain": "MATTER", "topic": "surface tension", "grades": [4, 5], "terms": ["surface tension", "tubig", "water", "patak", "tulo", "drop", "molekula", "balat ng tubig", "insekto", "insect"], "fact": {"tl": "Ang mga molekula ng tubig ay magkakahila-hila. Sa ibabaw, mas malakas ang hila pababa kaya parang may manipis na 'balat' ang tubig — kaya umaapaw nang kaunti sa basong puno, bumubuo ng patak, at nakakalakad dito ang maliliit na insekto.", "en": "Water molecules pull on each other. At the surface they pull inward and form a thin 'skin' called surface tension — that is why water beads into drops, can dome slightly above a full glass, and lets tiny insects walk on it.", "bis": "Ang mga molekula sa tubig nagbinira-bira sa usag usa. Sa ibabaw mas kusgan ang birahanay maong daw adunay nipis nga 'panit' ang tubig — mao nga maghimog tulo, makaawas gamay sa puno nga baso, ug makalakaw niini ang gagmayng insekto."}, "source": "AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-glass-transparent-g5", "domain": "MATTER", "topic": "why glass is transparent", "grades": [5, 6], "terms": ["salamin", "baso", "glass", "transparent", "aninaw", "liwanag", "light", "kuryente? no", "dumadaan ang liwanag"], "fact": {"tl": "Naaaninaw ang salamin dahil hindi sinisipsip o ikinakalat ng mga particle nito ang nakikitang liwanag — dumadaan ang liwanag nang diretso, kaya nakikita natin ang nasa kabila.", "en": "Glass is transparent because its particles do not absorb or scatter visible light — the light passes straight through, so we can see what is on the other side.", "bis": "Aninaw ang salamin tungod kay ang mga partikulo niini dili mosuyop o magkatag sa makita nga kahayag — molahos ang kahayag deretso, maong makita nato ang anaa sa pikas."}, "source": "AAAS BSL Ch.4; NRC PS4.B", "generator": "claude", "reviewed": false},
  {"id": "transparent-translucent-opaque-g4", "domain": "MATTER", "topic": "transparent translucent opaque", "grades": [4, 5], "terms": ["transparent", "translucent", "opaque", "aninaw", "malabo", "makapal", "liwanag", "light", "materyales", "materyal"], "fact": {"tl": "May tatlong uri ng materyales ayon sa pagdaan ng liwanag: transparent (aninaw, malinaw na nakikita tulad ng salamin), translucent (bahagyang dumadaan ang liwanag pero malabo tulad ng papel o frosted glass), at opaque (hindi dumadaan ang liwanag tulad ng kahoy o metal).", "en": "Materials are grouped by how light passes through them: transparent (clear, you see right through, like glass), translucent (some light passes but blurry, like paper or frosted glass), and opaque (no light passes, like wood or metal).", "bis": "Adunay tulo ka klase sa materyales sumala sa pag-agi sa kahayag: transparent (aninaw, klaro makita sama sa salamin), translucent (gamay ra mga-agi ang kahayag apan hanap sama sa papel), ug opaque (walay molahos nga kahayag sama sa kahoy o metal)."}, "source": "AAAS BSL Ch.4; DepEd CG", "generator": "claude", "reviewed": false},
  {"id": "sublimation-g6", "domain": "MATTER", "topic": "sublimation", "grades": [6, 7, 8], "terms": ["sublimation", "solid", "gas", "yelo", "dry ice", "naphthalene", "mothball", "singaw", "aso", "usok"], "fact": {"tl": "Sa sublimation, ang solid ay direktang nagiging gas nang hindi muna nagiging likido. Halimbawa: ang 'dry ice' na parang umuusok, o ang naphthalene balls (alkampor) na unti-unting lumiliit hanggang mawala.", "en": "In sublimation, a solid turns straight into a gas without first becoming a liquid. Examples are dry ice that seems to 'smoke', and mothballs that slowly shrink until they disappear.", "bis": "Sa sublimation, ang solid direktang mahimong gas nga dili una mahimong likido. Pananglitan: ang 'dry ice' nga daw nag-aso, o ang mothballs (alkampor) nga hinay-hinayng mokunhod hangtod mawala."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-we-smell-diffusion-g4", "domain": "MATTER", "topic": "why we can smell things", "grades": [3, 4, 5], "terms": ["amoy", "baho", "kahumot", "smell", "ilong", "ilong", "nose", "diffusion", "particle", "hangin", "kumalat"], "fact": {"tl": "Nakakaamoy tayo dahil may napakaliliit na particle na pumupulas mula sa bagay at kumakalat sa hangin (diffusion) hanggang umabot sa loob ng ating ilong. Kaya naaamoy mo ang ulam kahit nasa kabilang silid ka pa.", "en": "We can smell things because tiny particles drift off them and spread through the air (diffusion) until they reach the inside of our nose. That is why you smell food cooking even from another room.", "bis": "Makasimhot ta tungod kay adunay gagmayng partikulo nga mobuhi gikan sa butang ug mokatag sa hangin (diffusion) hangtod moabot sa sulod sa atong ilong. Mao nga masimhot nimo ang sud-an bisan lain ka og kwarto."}, "source": "AAAS BSL Ch.4; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "evaporation-puddles-g3", "domain": "MATTER", "topic": "why puddles dry up", "grades": [3, 4], "terms": ["evaporation", "singaw", "sangag? no", "lusak", "puddle", "natutuyo", "mauga", "tubig", "init", "araw", "singaw ng tubig"], "fact": {"tl": "Natutuyo ang mga lusak dahil binibigyan ng init ng araw ang mga particle ng tubig ng sapat na lakas para makatakas papuntang hangin bilang singaw ng tubig (water vapor) na hindi nakikita. Ito ang tinatawag na evaporation.", "en": "Puddles dry up because the sun's heat gives water particles enough energy to escape into the air as invisible water vapor. This is called evaporation.", "bis": "Mauga ang mga lapok tungod kay ang init sa adlaw mohatag sa mga partikulo sa tubig og igong kusog aron makaikyas ngadto sa hangin isip dili-makita nga alisngaw sa tubig (water vapor). Kini gitawag og evaporation."}, "source": "NRC ESS2.C; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "condensation-cold-glass-g4", "domain": "MATTER", "topic": "why a cold glass sweats", "grades": [4, 5], "terms": ["condensation", "baso", "glass", "pawis ng baso", "hamog", "tubig", "water vapor", "malamig", "cold", "tumutulo"], "fact": {"tl": "'Pumapawis' ang malamig na baso dahil ang singaw ng tubig sa mainit na hangin ay dumidikit sa malamig na ibabaw, nawawalan ng lakas, at nagiging maliliit na patak ng tubig. Ito ang condensation — kabaligtaran ng evaporation.", "en": "A cold glass 'sweats' because water vapor in the warm air touches the cold surface, loses energy, and turns back into tiny drops of liquid water. This is condensation — the opposite of evaporation.", "bis": "'Magsingot' ang bugnaw nga baso tungod kay ang alisngaw sa tubig sa init nga hangin modikit sa bugnaw nga gawas, mawad-an og kusog, ug mahimong gagmayng tulo sa tubig. Kini ang condensation — kabaliktaran sa evaporation."}, "source": "NRC ESS2.C; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-wet-clothes-dry-g4", "domain": "MATTER", "topic": "why wet clothes dry", "grades": [3, 4, 5], "terms": ["damit", "clothes", "natutuyo", "mauga", "labada", "init", "hangin", "wind", "evaporation", "araw", "bilad"], "fact": {"tl": "Mas mabilis natutuyo ang basang damit kapag mainit at mahangin dahil pinapabilis ng init ang evaporation, at tinatangay ng hangin ang singaw ng tubig palayo para mas marami pang tubig ang makatakas mula sa tela.", "en": "Wet clothes dry faster on a hot, windy day because heat speeds up evaporation, and wind carries the water vapor away so even more water can escape from the cloth.", "bis": "Mas paspas mauga ang basa nga sanina kon init ug hanginon tungod kay ang init mopaspas sa evaporation, ug ang hangin modala sa alisngaw palayo aron mas daghan pang tubig ang makaikyas gikan sa panapton."}, "source": "NRC ESS2.C; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "density-float-sink-g5", "domain": "MATTER", "topic": "density and floating", "grades": [5, 6], "terms": ["density", "densidad", "lutang", "lumulutang", "float", "lumulubog", "sink", "bigat", "timbang", "tubig", "barko", "ship"], "fact": {"tl": "Lumulutang o lumulubog ang isang bagay ayon sa density nito. Kung mas mababa ang density kaysa tubig, lumulutang; kung mas mataas, lumulubog. Mahalaga rin ang hugis — kaya nakakalutang ang bakal na barko dahil maraming hangin sa loob nito.", "en": "Whether something floats or sinks depends on its density. If it is less dense than water it floats; if it is denser it sinks. Shape matters too — a steel ship floats because it is mostly hollow and traps air inside.", "bis": "Molutaw o molugdang ang usa ka butang sumala sa density niini. Kon mas ubos ang density kaysa tubig, molutaw; kon mas taas, molugdang. Importante sab ang porma — molutaw ang puthaw nga barko tungod kay daghan kinig hangin sa sulod."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "viscosity-g5", "domain": "MATTER", "topic": "viscosity", "grades": [5, 6], "terms": ["viscosity", "kapal", "makapal", "thick", "pulot", "honey", "langis", "oil", "dumadaloy", "agos", "flow", "likido"], "fact": {"tl": "Ang viscosity ang sukat kung gaano kabilis o kabagal dumaloy ang isang likido. Ang pulot at langis ay viscous (mabagal dumaloy), samantalang ang tubig ay mabilis. Kadalasan, mas madaling dumaloy ang likido kapag pinainit.", "en": "Viscosity is how slowly or quickly a liquid flows. Honey and oil are viscous (they flow slowly), while water flows fast. Heating a liquid usually makes it flow more easily.", "bis": "Ang viscosity mao ang sukod kon unsa ka hinay o paspas modagayday ang usa ka likido. Ang dugos ug lana viscous (hinay modagayday), samtang ang tubig paspas. Kasagaran, mas sayon modagayday ang likido kon initon."}, "source": "AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-cut-apple-browns-g5", "domain": "MATTER", "topic": "why cut fruit turns brown", "grades": [4, 5, 6], "terms": ["mansanas", "apple", "prutas", "fruit", "kayumanggi", "brown", "oxidation", "oksiheno", "oxygen", "kalamansi", "lemon"], "fact": {"tl": "Nagiging kayumanggi ang hiniwang mansanas dahil ang oksiheno sa hangin ay tumutugon sa mga kemikal sa loob ng prutas — isang uri ng oxidation. Pinapabagal ito ng katas ng kalamansi o lemon.", "en": "A cut apple turns brown because oxygen in the air reacts with chemicals inside the fruit — a kind of oxidation. Squeezing on lemon or calamansi juice slows it down.", "bis": "Mahimong brown ang gihiwa nga mansanas tungod kay ang oksiheno sa hangin motubag sa mga kemikal sulod sa prutas — usa ka matang sa oxidation. Mahinay kini kon pug-an og duga sa lemon o kalamansi."}, "source": "AAAS BSL Ch.4; NRC PS1.B", "generator": "claude", "reviewed": false},
  {"id": "why-balloon-shrinks-cold-g5", "domain": "MATTER", "topic": "why balloons shrink in cold", "grades": [5, 6], "terms": ["lobo", "balloon", "lumiliit", "shrink", "lumalaki", "expand", "malamig", "cold", "mainit", "hot", "hangin", "particle"], "fact": {"tl": "Lumiliit ang lobo sa lamig dahil bumabagal ang mga particle ng hangin sa loob at mas kaunting puwang ang kinakailangan nila. Sa init, bumibilis at lumalawak sila, kaya lumalaki ang lobo.", "en": "A balloon shrinks in the cold because the air particles inside slow down and take up less space. In heat they speed up and spread out, so the balloon expands.", "bis": "Mokunhod ang lobo sa katugnaw tungod kay ang mga partikulo sa hangin sa sulod mohinay ug mas gamay nga luna ang ilang gikinahanglan. Sa init, mopaspas ug mokatag sila, maong modako ang lobo."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-popcorn-pops-g4", "domain": "MATTER", "topic": "why popcorn pops", "grades": [3, 4, 5], "terms": ["popcorn", "mais", "corn", "pumuputok", "pop", "singaw", "steam", "init", "tubig", "presyon", "pressure"], "fact": {"tl": "Pumuputok ang popcorn dahil ang kaunting tubig sa loob ng butil ay nagiging singaw kapag pinainit. Lumalakas ang presyon hanggang sumabog ang matigas na balat, at lumalabas ang malambot na loob bilang puti at malutong na popcorn.", "en": "Popcorn pops because the little bit of water trapped inside the kernel turns to steam when heated. Pressure builds until the hard shell bursts open, and the soft inside puffs out as white, crunchy popcorn.", "bis": "Mobuto ang popcorn tungod kay ang gamayng tubig sa sulod sa lugas mahimong alisngaw kon initon. Mosaka ang presyon hangtod mobuto ang gahi nga panit, ug mogawas ang humok nga sulod isip puti ug tagiktik nga popcorn."}, "source": "AAAS BSL Ch.4; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "why-soda-fizzes-g4", "domain": "MATTER", "topic": "why soda fizzes", "grades": [4, 5, 6], "terms": ["soda", "softdrink", "fizz", "bula", "bubble", "carbon dioxide", "gas", "presyon", "pressure", "umaapaw", "kalat"], "fact": {"tl": "Bumubula ang softdrinks dahil may carbon dioxide na gas na natunaw dito sa ilalim ng presyon. Kapag binuksan mo ang bote, bumababa ang presyon kaya tumatakas ang gas bilang maliliit na bula.", "en": "Soda fizzes because carbon-dioxide gas is dissolved in it under pressure. When you open the bottle, the pressure drops, so the gas escapes as tiny bubbles.", "bis": "Mobula ang softdrinks tungod kay adunay carbon-dioxide nga gas nga natunaw niini ubos sa presyon. Kon ablihan nimo ang botelya, mokunhod ang presyon maong moikyas ang gas isip gagmayng bula."}, "source": "AAAS BSL Ch.4; NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "why-metals-conduct-electricity-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "why metals conduct electricity", "grades": [6, 7, 8], "terms": ["metal", "bakal", "kuryente", "electricity", "conductor", "daloy", "electron", "libre", "charge", "kawad", "wire"], "fact": {"tl": "Mahusay magdaloy ng kuryente ang mga metal dahil may mga 'malayang electron' sila na madaling gumalaw. Itong gumagalaw na electron ang nagdadala ng singil ng kuryente sa kabuuan ng metal.", "en": "Metals conduct electricity well because they have free electrons that can move easily. These moving electrons carry the electric charge through the metal.", "bis": "Maayong modaloy og kuryente ang mga metal tungod kay aduna silay 'gawasnong electron' nga sayon molihok. Kining naglihok nga electron maoy nagdala sa kuryente nga charge latas sa metal."}, "source": "NRC PS3.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-hot-air-rises-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "why hot air rises", "grades": [4, 5, 6], "terms": ["hangin", "air", "mainit", "hot", "tumataas", "rise", "pumapaitaas", "density", "magaan", "light", "lobo", "convection"], "fact": {"tl": "Tumataas ang mainit na hangin dahil kapag pinainit, kumakalat ang mga particle nito kaya nagiging mas magaan (mababa ang density) kaysa malamig na hangin sa paligid, at lumulutang ito pataas. Ito ang dahilan kung bakit lumilipad ang hot-air balloon.", "en": "Hot air rises because heating makes its particles spread apart, so the hot air becomes lighter (less dense) than the cooler air around it and floats upward. This is why a hot-air balloon flies.", "bis": "Mosaka ang init nga hangin tungod kay kon initon, ang mga partikulo niini mokatag maong mahimong mas gaan (ubos og density) kaysa bugnaw nga hangin sa palibot, ug molutaw kini pataas. Mao kini ngano molupad ang hot-air balloon."}, "source": "NRC PS3.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-goosebumps-g4", "domain": "LIVING_THINGS", "topic": "why we get goosebumps", "grades": [4, 5, 6], "terms": ["goosebumps", "balahibo", "kilabot", "tindig balahibo", "kalamig", "cold", "takot", "fear", "kalamnan", "muscle", "reflex"], "fact": {"tl": "Nagkakaroon tayo ng goosebumps kapag ang maliliit na kalamnan sa balat ay humihila pataas sa ating balahibo. Ito ay lumang reflex mula sa ating mga ninuno na may makapal na balahibo — para magkulong ng init kapag nilalamig o magmukhang mas malaki kapag natatakot.", "en": "We get goosebumps when tiny muscles at the base of our hairs pull them upright. It is an old reflex from ancestors with thick fur — to trap warmth when cold or look bigger when scared.", "bis": "Magkilabot ta kon ang gagmayng kaunoran sa atong panit mobira pataas sa atong balhibo. Karaan kining reflex gikan sa atong mga katigulangan nga baga og balhibo — aron motipig og init kon tugnawon o magpakita nga mas dako kon mahadlok."}, "source": "NRC LS1.A; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "why-we-yawn-g3", "domain": "LIVING_THINGS", "topic": "why we yawn", "grades": [3, 4, 5], "terms": ["hikab", "humikab", "yawn", "paghinga", "hininga", "hangin", "utak", "brain", "antok", "cool", "nakakahawa"], "fact": {"tl": "Humihikab tayo para makahinga nang malalim at makakuha ng maraming hangin, na maaaring tumutulong palamigin ang utak at gisingin tayo. Nakakahawa rin ang hikab — humihikab tayo kapag nakita nating may humikab.", "en": "We yawn to take a deep breath of air, which may help cool the brain and make us more alert. Yawns are also contagious — we often yawn just from seeing someone else yawn.", "bis": "Maghuy-ab ta aron makaginhawa og lawom ug makakuha og daghang hangin, nga tingali makatabang sa pagpabugnaw sa utok ug pagpukaw kanato. Makatakod sab ang huy-ab — maghuy-ab ta kon makakita tag laing naghuy-ab."}, "source": "NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "why-stomach-growls-g3", "domain": "LIVING_THINGS", "topic": "why our stomach growls", "grades": [3, 4], "terms": ["tiyan", "stomach", "kumakalam", "kalam", "growl", "gutom", "hungry", "gas", "bituka", "digestion", "tunog"], "fact": {"tl": "Kumakalam ang tiyan kapag gumagalaw ang gas at likido sa loob ng walang lamang sikmura at bituka, at pinipiga sila ng mga kalamnan. Mas malakas ang tunog kapag gutom dahil walang pagkaing humahadlang sa ingay.", "en": "Your stomach growls when gas and fluids move through the empty stomach and intestines while the muscles squeeze them along. It sounds louder when you are hungry because there is no food to muffle the noise.", "bis": "Magkagol ang tiyan kon ang gas ug likido molihok sulod sa walay sulod nga tiyan ug tinai samtang gipuga sila sa kaunoran. Mas kusog ang tingog kon gutom ka tungod kay walay pagkaon nga makapahupay sa saba."}, "source": "NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "why-onions-make-cry-g4", "domain": "LIVING_THINGS", "topic": "why onions make us cry", "grades": [4, 5], "terms": ["sibuyas", "onion", "umiiyak", "luha", "tears", "cry", "mata", "eye", "gas", "asido", "acid", "hiwa"], "fact": {"tl": "Kapag hiniwa ang sibuyas, naglalabas ito ng gas na humahalo sa tubig sa ating mga mata at bumubuo ng banayad na asido. Para hugasan ito palabas, gumagawa ng luha ang mata kaya tayo umiiyak.", "en": "When you cut an onion, it releases a gas that mixes with the water in your eyes to form a mild acid. To wash it away, your eyes make tears — so you cry.", "bis": "Kon hiwaon ang sibuyas, mobuga kini og gas nga mosagol sa tubig sa atong mga mata ug maghimog hinay nga asido. Aron mahugasan kini, ang mata maghimog luha — maong mohilak ta."}, "source": "AAAS BSL Ch.6; NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "why-we-get-dizzy-spinning-g4", "domain": "LIVING_THINGS", "topic": "why we get dizzy", "grades": [4, 5, 6], "terms": ["hilo", "nahihilo", "dizzy", "umiikot", "ikot", "spin", "tainga", "inner ear", "balanse", "balance", "likido", "utak"], "fact": {"tl": "Nahihilo tayo pagkatapos umikot dahil may likido sa loob ng tainga na nakakaramdam ng balanse. Kapag huminto tayo, patuloy pa ring gumagalaw ang likido, kaya akala ng utak ay umiikot pa rin tayo.", "en": "We get dizzy after spinning because there is fluid in our inner ear that senses balance. When we stop, the fluid keeps swirling, so the brain thinks we are still spinning.", "bis": "Malipong ta human magtuyok tungod kay adunay likido sulod sa atong dalunggan nga makabati sa balanse. Kon mohunong ta, magpadayon og tuyok ang likido, maong maghunahuna ang utok nga nagtuyok pa ta."}, "source": "NRC LS1.A; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "why-we-hiccup-g4", "domain": "LIVING_THINGS", "topic": "why we hiccup", "grades": [4, 5], "terms": ["sinok", "hiccup", "diaphragm", "kalamnan", "muscle", "paghinga", "lalamunan", "throat", "biglang", "hic"], "fact": {"tl": "Nagkakasinok tayo kapag biglang gumalaw nang pasumpong-sumpong ang diaphragm — ang kalamnan sa ilalim ng baga na ginagamit sa paghinga. Sabay nitong nagsasara ang lalamunan, kaya may 'hik' na tunog.", "en": "We hiccup when the diaphragm — the breathing muscle below the lungs — suddenly jerks. At the same moment the throat snaps shut, which makes the 'hic' sound.", "bis": "Magsinok ta kon ang diaphragm — ang kaunoran ubos sa baga nga gamiton sa pagginhawa — kalit molihok nga sumpo-sumpo. Dungan niini mosira ang tutunlan, maong adunay 'hik' nga tingog."}, "source": "NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "why-bread-rises-g5", "domain": "LIVING_THINGS", "topic": "why bread rises", "grades": [5, 6], "terms": ["tinapay", "bread", "umaalsa", "alsa", "rise", "lebadura", "yeast", "fungus", "carbon dioxide", "gas", "bula", "masa"], "fact": {"tl": "Umaalsa ang tinapay dahil ang lebadura (yeast) — isang napakaliit na fungus — ay kumakain ng asukal at naglalabas ng carbon-dioxide na gas. Bumubuo ng mga bula ang gas na ito na nagpapalobo sa masa.", "en": "Bread rises because yeast — a tiny fungus — eats sugar and gives off carbon-dioxide gas. That gas forms bubbles that puff up the dough.", "bis": "Moalsa ang pan tungod kay ang lebadura (yeast) — usa ka gamayng fungus — mokaon og asukar ug mobuga og carbon-dioxide nga gas. Kining gasa maghimog bula nga maghubag sa minasa."}, "source": "NRC LS1.C; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "why-fruit-ripens-g4", "domain": "LIVING_THINGS", "topic": "why fruit ripens", "grades": [4, 5], "terms": ["prutas", "fruit", "hinog", "nahihinog", "ripen", "ethylene", "gas", "asukal", "sugar", "tamis", "saging", "mansanas"], "fact": {"tl": "Nahihinog ang prutas dahil naglalabas ito ng likas na gas na tinatawag na ethylene. Ginagawang asukal nito ang starch, pinalalambot ang laman, at binabago ang kulay — kaya nagiging matamis ang hinog na prutas.", "en": "Fruit ripens as it gives off a natural gas called ethylene. The gas turns starch into sugar, softens the flesh, and changes the color — which is why ripe fruit tastes sweeter.", "bis": "Mahinog ang prutas samtang mobuga kini og natural nga gas nga gitawag ethylene. Ang gas mohimo sa starch nga asukar, mopahumok sa unod, ug mousab sa kolor — mao nga mas tam-is ang hinog nga prutas."}, "source": "NRC LS1.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "el-nino-la-nina-g6", "domain": "EARTH_SPACE", "topic": "el nino and la nina", "grades": [6, 7, 8], "terms": ["el nino", "la nina", "tagtuyot", "drought", "baha", "flood", "tubig-dagat", "Pacific", "ulan", "panahon", "init", "tag-init"], "fact": {"tl": "Ang El Niño ay kapag uminit ang tubig sa Pacific Ocean — kadalasang nagdadala ito ng kakaunting ulan at tagtuyot sa Pilipinas. Ang La Niña naman ay kapag lumamig ang tubig — nagdadala ito ng mas maraming ulan, baha, at bagyo.", "en": "El Niño is when the Pacific Ocean's water warms up — it usually brings less rain and droughts to the Philippines. La Niña is when that water cools — it brings more rain, floods, and typhoons.", "bis": "Ang El Niño mao kon moinit ang tubig sa Pacific Ocean — kasagaran magdala kinig gamayng ulan ug hulaw sa Pilipinas. Ang La Niña mao kon mobugnaw ang tubig — magdala kinig mas daghang ulan, baha, ug bagyo."}, "source": "NRC ESS2.D; PAGASA", "generator": "claude", "reviewed": false},
  {"id": "pacific-ring-of-fire-g6", "domain": "EARTH_SPACE", "topic": "Pacific Ring of Fire", "grades": [6, 7, 8], "terms": ["Ring of Fire", "Pacific", "lindol", "earthquake", "bulkan", "volcano", "tectonic plate", "Pilipinas", "linog", "bukid"], "fact": {"tl": "Ang Pilipinas ay nasa 'Pacific Ring of Fire,' isang hugis-bakal-ng-kabayo na sona sa palibot ng Pacific Ocean kung saan maraming lindol at bulkan. Nangyayari ito dahil dito nagtatagpo at nagkakabanggaan ang mga tectonic plate ng Earth.", "en": "The Philippines sits on the 'Pacific Ring of Fire,' a horseshoe-shaped zone around the Pacific Ocean with many earthquakes and volcanoes. This happens because Earth's tectonic plates meet and grind against each other here.", "bis": "Ang Pilipinas naa sa 'Pacific Ring of Fire,' usa ka porma-kwadradong-kabayo nga sona palibot sa Pacific Ocean diin daghang linog ug bulkan. Mahitabo kini tungod kay dinhi magtagbo ug mag-banggaay ang mga tectonic plate sa Earth."}, "source": "NRC ESS2.B; PHIVOLCS", "generator": "claude", "reviewed": false},
  {"id": "why-ph-many-typhoons-g6", "domain": "EARTH_SPACE", "topic": "why the Philippines has many typhoons", "grades": [5, 6, 7], "terms": ["bagyo", "typhoon", "Pilipinas", "Pacific", "mainit na dagat", "hangin", "tubig-dagat", "unos", "bagyo-bagyo"], "fact": {"tl": "Tumatama sa Pilipinas ang humigit-kumulang 20 bagyo kada taon dahil nasa tabi ito ng mainit na kanlurang Pacific Ocean kung saan madaling bumuo ng bagyo, at ang ihip ng hangin ang nagtutulak ng mga ito papunta sa ating mga isla.", "en": "The Philippines is hit by about 20 typhoons a year because it lies beside the warm western Pacific Ocean where storms easily form, and the prevailing winds steer them toward the islands.", "bis": "Maigo ang Pilipinas og mga 20 ka bagyo matag tuig tungod kay naa kini sa kilid sa init nga kasadpang Pacific Ocean diin sayon maporma ang bagyo, ug ang huros sa hangin maoy nagtukmod niini paingon sa atong mga isla."}, "source": "NRC ESS2.D; PAGASA", "generator": "claude", "reviewed": false},
  {"id": "storm-surge-g6", "domain": "EARTH_SPACE", "topic": "storm surge", "grades": [5, 6, 7], "terms": ["storm surge", "daluyong", "bagyo", "typhoon", "baha", "dagat", "tubig-dagat", "pampang", "Yolanda", "Haiyan", "alon"], "fact": {"tl": "Ang storm surge ay tubig-dagat na itinutulak paahon sa lupa ng malakas na hangin at mababang presyon ng bagyo, na nagdudulot ng delikadong pagbaha sa baybayin. Ito ang dahilan ng maraming namatay noong Bagyong Yolanda (Haiyan).", "en": "A storm surge is sea water pushed onto land by a typhoon's strong winds and low pressure, causing dangerous coastal flooding. It was the main cause of deaths during Typhoon Yolanda (Haiyan).", "bis": "Ang storm surge mao ang tubig-dagat nga gitukmod ngadto sa yuta sa kusog nga hangin ug ubos nga presyon sa bagyo, nga maoy hinungdan sa peligrosong baha sa baybayon. Mao kini ang nag-unang hinungdan sa daghang namatay panahon sa Bagyong Yolanda (Haiyan)."}, "source": "NRC ESS2.D; PAGASA", "generator": "claude", "reviewed": false},
  {"id": "humidity-g5", "domain": "EARTH_SPACE", "topic": "humidity", "grades": [5, 6], "terms": ["humidity", "halumigmig", "alinsangan", "basa ang hangin", "singaw ng tubig", "water vapor", "pawis", "init", "maalinsangan"], "fact": {"tl": "Ang humidity (halumigmig) ay ang dami ng singaw ng tubig sa hangin. Kapag mataas ang humidity, mas maalinsangan ang init dahil mabagal sumingaw ang ating pawis kaya hindi tayo agad lumalamig.", "en": "Humidity is the amount of water vapor in the air. When humidity is high, hot days feel stickier because our sweat evaporates slowly, so we don't cool down as quickly.", "bis": "Ang humidity (kaumog) mao ang gidaghanon sa alisngaw sa tubig sa hangin. Kon taas ang humidity, mas alinsangan ang init tungod kay hinay mosingaw ang atong singot maong dili dayon ta mabugnawan."}, "source": "NRC ESS2.D", "generator": "claude", "reviewed": false},
  {"id": "air-pressure-g5", "domain": "EARTH_SPACE", "topic": "air pressure", "grades": [5, 6, 7], "terms": ["air pressure", "presyon ng hangin", "bigat ng hangin", "bundok", "altitude", "panahon", "weather", "hangin", "timbang"], "fact": {"tl": "May timbang ang hangin at idinidiin nito ang lahat ng bagay — ito ang air pressure. Mas mataas ito sa pantay-dagat at mas mababa sa tuktok ng bundok. Ang pagkakaiba ng presyon ang lumilikha ng hangin at nagbabago ng panahon.", "en": "Air has weight and presses on everything around it — that is air pressure. It is higher at sea level and lower at the top of a mountain. Differences in pressure create wind and change the weather.", "bis": "Ang hangin adunay timbang ug moduot kini sa tanang butang — mao kini ang air pressure. Mas taas kini sa lebel sa dagat ug mas ubos sa tumoy sa bukid. Ang kalainan sa presyon maoy maghimog hangin ug mag-usab sa panahon."}, "source": "NRC ESS2.D; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "what-is-hail-g5", "domain": "EARTH_SPACE", "topic": "what is hail", "grades": [4, 5, 6], "terms": ["hail", "yelo", "ulan-yelo", "ulap", "thundercloud", "kidlat", "frozen", "malamig", "bumagsak"], "fact": {"tl": "Ang hail (ulan na yelo) ay mga bilog na yelo na nabubuo kapag ang mga patak ng ulan ay naitataas sa napakalamig na bahagi ng makapal na ulap, doon nagyeyelo at lumalaki bago bumagsak. Bihira ito sa Pilipinas dahil mainit ang klima.", "en": "Hail is balls of ice that form when raindrops are carried up into the very cold parts of a tall thundercloud, freeze, and grow before falling. It is rare in the Philippines because the climate is warm.", "bis": "Ang hail (ulan nga yelo) mao ang lingin nga yelo nga maporma kon ang tulo sa ulan madala pataas sa hilabihan kabugnaw nga bahin sa baga nga panganod, didto mag-yelo ug modako una mahulog. Talagsa ra kini sa Pilipinas tungod kay init ang klima."}, "source": "NRC ESS2.D", "generator": "claude", "reviewed": false},
  {"id": "why-moon-has-craters-g5", "domain": "EARTH_SPACE", "topic": "why the moon has craters", "grades": [4, 5, 6], "terms": ["buwan", "moon", "crater", "butas", "meteoroid", "bato sa kalawakan", "banggaan", "hangin", "walang hangin", "kalawakan"], "fact": {"tl": "Puno ng crater (malalaking butas) ang buwan dahil sa mga bato mula sa kalawakan na bumabangga rito. Dahil walang hangin o panahon sa buwan, hindi naaagnas o nawawala ang mga crater kaya nananatili ang mga ito nang napakatagal.", "en": "The moon is covered in craters from space rocks crashing into it. Because the moon has no air or weather, the craters don't erode away, so they stay for a very long time.", "bis": "Puno og crater (dagkong lungag) ang bulan tungod sa mga bato gikan sa kawanangan nga nagbangga niini. Tungod kay walay hangin o panahon sa bulan, dili maguba o mawala ang mga crater maong magpabilin kini og dugay kaayo."}, "source": "NRC ESS1.B", "generator": "claude", "reviewed": false},
  {"id": "no-air-in-space-g5", "domain": "EARTH_SPACE", "topic": "why there is no air in space", "grades": [4, 5, 6], "terms": ["kalawakan", "space", "walang hangin", "vacuum", "oxygen", "hininga", "tunog", "sound", "astronaut", "helmet"], "fact": {"tl": "Ang kalawakan ay halos walang laman (vacuum) — wala halos hanging dapat hingahin. Kaya nagsusuot ng espesyal na suit at tangke ng oksiheno ang mga astronaut, at hindi rin naririnig ang tunog sa kalawakan dahil walang hanging dadaluyan nito.", "en": "Space is almost completely empty (a vacuum) — there is almost no air to breathe. That is why astronauts wear special suits with oxygen tanks, and why sound cannot travel in space, since it needs air to move through.", "bis": "Ang kawanangan halos walay sulod (vacuum) — halos walay hangin nga maginhawa. Mao nga ang mga astronaut magsul-ob og espesyal nga suit ug tangke sa oksiheno, ug dili madungog ang tingog sa kawanangan kay nagkinahanglan kini og hangin aron molahos."}, "source": "NRC ESS1.B; PS4.A", "generator": "claude", "reviewed": false},
  {"id": "what-is-shooting-star-g4", "domain": "EARTH_SPACE", "topic": "what is a shooting star", "grades": [3, 4, 5], "terms": ["shooting star", "bulalakaw", "meteor", "bituin", "star", "bato sa kalawakan", "kuskos", "friction", "liwanag", "guhit"], "fact": {"tl": "Ang 'shooting star' (bulalakaw) ay hindi talaga bituin — ito ay maliit na bato mula sa kalawakan na nasusunog dahil sa kuskusan (friction) habang humahagibis ito sa hangin ng Earth, kaya may guhit ng liwanag.", "en": "A 'shooting star' is not really a star — it is a tiny space rock burning up from friction as it races through Earth's air, which makes a bright streak of light.", "bis": "Ang 'shooting star' (bulalakaw) dili gyud bituon — usa kini ka gamayng bato gikan sa kawanangan nga nasunog tungod sa kuskos (friction) samtang naghaguros kini sa hangin sa Earth, maong adunay guhit nga kahayag."}, "source": "NRC ESS1.B", "generator": "claude", "reviewed": false},
  {"id": "greenhouse-effect-g6", "domain": "EARTH_SPACE", "topic": "greenhouse effect", "grades": [6, 7, 8], "terms": ["greenhouse effect", "carbon dioxide", "gas", "init", "heat", "kumot", "blanket", "pag-init ng mundo", "global warming", "atmosphere"], "fact": {"tl": "Sa greenhouse effect, ang ilang mga gas tulad ng carbon dioxide ay humuhuli ng bahagi ng init ng araw malapit sa Earth, parang kumot. Kailangan natin ito para mainit-init ang mundo, pero ang sobrang dami ay nagdudulot ng global warming.", "en": "In the greenhouse effect, certain gases like carbon dioxide trap some of the sun's heat near Earth, like a blanket. We need some of it to keep Earth warm, but too much causes global warming.", "bis": "Sa greenhouse effect, ang pipila ka gas sama sa carbon dioxide modakop sa bahin sa init sa adlaw duol sa Earth, sama sa habol. Gikinahanglan nato ang gamay niini aron init ang kalibotan, apan ang sobra maoy hinungdan sa global warming."}, "source": "NRC ESS3.D; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-ocean-has-waves-g4", "domain": "EARTH_SPACE", "topic": "why the ocean has waves", "grades": [3, 4, 5], "terms": ["alon", "wave", "dagat", "ocean", "hangin", "wind", "tubig", "ibabaw", "lakas ng hangin", "pampang"], "fact": {"tl": "Karamihan ng alon sa dagat ay ginagawa ng hangin na humahampas sa ibabaw ng tubig. Kapag mas malakas at mas matagal ang ihip ng hangin, mas malalaki ang alon. Ang malalakas na bagyo kaya gumagawa ng higanteng alon.", "en": "Most ocean waves are made by wind pushing on the surface of the water. The stronger and longer the wind blows, the bigger the waves. That is why strong storms make giant waves.", "bis": "Kadaghanan sa balod sa dagat hinimo sa hangin nga moduot sa ibabaw sa tubig. Kon mas kusog ug mas dugay mohuyop ang hangin, mas dako ang balod. Mao nga ang kusog nga bagyo maghimog higanteng balod."}, "source": "NRC ESS2.C", "generator": "claude", "reviewed": false},
  {"id": "sea-breeze-land-breeze-g5", "domain": "EARTH_SPACE", "topic": "sea breeze and land breeze", "grades": [5, 6], "terms": ["sea breeze", "land breeze", "simoy ng dagat", "hangin", "araw", "gabi", "lupa", "dagat", "mainit", "malamig", "baybayin"], "fact": {"tl": "Sa araw, mas mabilis uminit ang lupa kaysa dagat, kaya umaakyat ang mainit na hangin sa lupa at pumapalit ang malamig na hangin mula sa dagat — sea breeze. Sa gabi, kabaligtaran ito (land breeze) dahil mas mabilis lumamig ang lupa.", "en": "By day, land heats faster than the sea, so warm air rises over the land and cool air rushes in from the sea — a sea breeze. At night it reverses (land breeze) because land cools faster than the sea.", "bis": "Sa adlaw, mas paspas moinit ang yuta kaysa dagat, maong mosaka ang init nga hangin sa yuta ug mopuli ang bugnaw nga hangin gikan sa dagat — sea breeze. Sa gabii kabaliktaran kini (land breeze) tungod kay mas paspas mobugnaw ang yuta."}, "source": "NRC ESS2.D", "generator": "claude", "reviewed": false},
  {"id": "why-we-get-fever-g4", "domain": "LIVING_THINGS", "topic": "why we get a fever", "grades": [3, 4, 5], "terms": ["lagnat", "fever", "init ng katawan", "mikrobyo", "germs", "immune system", "depensa", "sakit", "sipon", "laban"], "fact": {"tl": "Ang lagnat ay kapag itinataas ng katawan ang temperatura nito para tulungan labanan ang mga mikrobyo. Senyales ito na gumagana ang immune system, pero ang sobrang taas na lagnat ay kailangang ipakonsulta sa doktor.", "en": "A fever is when the body raises its temperature to help fight off germs. It is a sign the immune system is working, but a very high fever needs to be checked by a doctor.", "bis": "Ang hilanat mao kon ipataas sa lawas ang temperatura niini aron tabangan pakigbatok sa mga mikrobyo. Timailhan kini nga naglihok ang immune system, apan ang taas kaayo nga hilanat kinahanglan ipatan-aw sa doktor."}, "source": "NRC LS1.A; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "why-we-cough-sneeze-g3", "domain": "LIVING_THINGS", "topic": "why we cough and sneeze", "grades": [3, 4], "terms": ["ubo", "cough", "bahin", "sneeze", "alikabok", "dust", "mikrobyo", "germs", "ilong", "lalamunan", "reflex", "hangin"], "fact": {"tl": "Ang pag-ubo at pagbahin ay mga reflex na biglang nagpapalabas ng hangin para tanggalin ang mga mikrobyo, alikabok, o sipon sa ilong at lalamunan. Kaya dapat takpan ang bibig para hindi kumalat ang sakit.", "en": "Coughing and sneezing are reflexes that suddenly blast out air to clear germs, dust, or mucus from the nose and throat. That is why you should cover your mouth so illness doesn't spread.", "bis": "Ang pag-ubo ug pagbahaon mga reflex nga kalit mobuga og hangin aron mawala ang mga mikrobyo, abog, o sip-on sa ilong ug tutunlan. Mao nga angay tabunan ang baba aron dili mokatag ang sakit."}, "source": "NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "why-cuts-heal-scabs-g4", "domain": "LIVING_THINGS", "topic": "why cuts heal and form scabs", "grades": [3, 4, 5], "terms": ["sugat", "cut", "wound", "langib", "scab", "dugo", "blood clot", "gumagaling", "heal", "balat", "selula"], "fact": {"tl": "Kapag nasugatan ka, namumuo ang dugo at nagiging langib na nagsasara sa sugat. Sa ilalim nito, gumagawa ng bagong selula ang balat para ayusin ang sarili nito hanggang gumaling.", "en": "When you get a cut, the blood clots into a scab that seals the wound. Underneath, the skin builds new cells to repair itself until it heals.", "bis": "Kon masamad ka, ang dugo mamuo ug mahimong kagid nga mosira sa samad. Sa ilalom niini, ang panit maghimog bag-ong mga selula aron ayohon ang kaugalingon hangtod maayo."}, "source": "NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "why-we-bruise-g4", "domain": "LIVING_THINGS", "topic": "why we bruise", "grades": [4, 5], "terms": ["pasa", "bruise", "dugo", "blood vessel", "ugat", "pagkabangga", "bukol", "kulay", "balat", "nadulas"], "fact": {"tl": "Ang pasa ay pagdurugo sa ilalim ng balat dahil sa mga maliliit na ugat na nasira nang mabangga ka. Nagbabago ang kulay nito (lila, berde, dilaw) habang nililinis ng katawan ang naipong dugo.", "en": "A bruise is bleeding under the skin from tiny blood vessels that broke when you got bumped. Its colors change (purple, green, yellow) as the body cleans up the trapped blood.", "bis": "Ang pangos mao ang pagdugo sa ilalom sa panit gikan sa gagmayng ugat nga nabuak dihang nabangga ka. Mausab ang kolor niini (purpura, berde, dalag) samtang ginalimpyohan sa lawas ang natipon nga dugo."}, "source": "NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "baby-and-adult-teeth-g3", "domain": "LIVING_THINGS", "topic": "baby and adult teeth", "grades": [2, 3, 4], "terms": ["ngipin", "teeth", "gatas", "baby teeth", "pangtanda", "adult teeth", "nalalaglag", "20", "32", "permanente"], "fact": {"tl": "Ang mga bata ay may 20 ngipin na gatas na nahuhulog para bigyang-daan ang 32 mas matibay na ngipin ng nakatatanda. Ang mga ngiping pang-adult na ito ay kailangang tumagal habambuhay, kaya mahalagang alagaan.", "en": "Children grow 20 baby teeth that fall out to make room for 32 stronger adult teeth. These adult teeth have to last a lifetime, so it's important to take care of them.", "bis": "Ang mga bata adunay 20 ka ngipon nga gatas nga mangahulog aron hatagag dalan ang 32 ka mas lig-on nga ngipon sa hamtong. Kining mga ngipon sa hamtong kinahanglang molungtad sa tibuok kinabuhi, maong importanteng atimanon."}, "source": "NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "why-we-need-vitamins-g4", "domain": "LIVING_THINGS", "topic": "why we need vitamins", "grades": [3, 4, 5], "terms": ["bitamina", "vitamins", "sustansya", "prutas", "gulay", "araw", "sunlight", "malusog", "vitamin C", "vitamin D", "mata"], "fact": {"tl": "Ang mga bitamina ay sustansyang kailangan sa maliliit na dami para manatiling malusog ang katawan — vitamin C mula sa prutas, vitamin D mula sa sikat ng araw, at vitamin A para sa malinaw na paningin.", "en": "Vitamins are nutrients the body needs in tiny amounts to stay healthy — vitamin C from fruit, vitamin D from sunlight, and vitamin A for clear eyesight.", "bis": "Ang mga bitamina mao ang sustansya nga gikinahanglan sa lawas sa gagmayng gidaghanon aron magpabiling himsog — vitamin C gikan sa prutas, vitamin D gikan sa sidlak sa adlaw, ug vitamin A alang sa tin-aw nga panan-aw."}, "source": "NRC LS1.C; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "germs-and-handwashing-g3", "domain": "LIVING_THINGS", "topic": "germs and handwashing", "grades": [2, 3, 4], "terms": ["mikrobyo", "germs", "bakterya", "virus", "sakit", "paghuhugas", "handwashing", "sabon", "soap", "kamay", "kalinisan"], "fact": {"tl": "Ang mga mikrobyo ay napakaliliit na nabubuhay na bagay na maaaring magpasakit sa atin. Ang paghuhugas ng kamay gamit ang sabon ay nag-aalis sa kanila at pumipigil na kumalat ang sakit.", "en": "Germs are tiny living things that can make us sick. Washing your hands with soap removes them and stops illness from spreading to others.", "bis": "Ang mga mikrobyo gagmayng buhing butang nga makapasakit kanato. Ang paghugas sa kamot gamit ang sabon makakuha kanila ug makapugong sa pagkatap sa sakit ngadto sa uban."}, "source": "NRC LS1.A; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "why-skin-colors-differ-g5", "domain": "LIVING_THINGS", "topic": "why skin colors differ", "grades": [5, 6], "terms": ["kulay ng balat", "skin color", "melanin", "pigment", "araw", "sunlight", "maitim", "maputi", "proteksyon", "UV"], "fact": {"tl": "Ang kulay ng balat ay nagmumula sa melanin, isang likas na pigment. Mas maraming melanin, mas maitim ang balat at mas malakas ang proteksyon nito laban sa nakakapinsalang sikat ng araw. Lahat ng kulay ng balat ay normal at maganda.", "en": "Skin color comes from melanin, a natural pigment. More melanin means darker skin and stronger protection against the sun's harmful rays. Every skin color is normal and good.", "bis": "Ang kolor sa panit gikan sa melanin, usa ka natural nga pigment. Mas daghang melanin, mas itom ang panit ug mas kusgan ang panalipod batok sa makadaot nga sidlak sa adlaw. Tanang kolor sa panit normal ug nindot."}, "source": "NRC LS3.B; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "why-two-eyes-g4", "domain": "LIVING_THINGS", "topic": "why we have two eyes", "grades": [3, 4, 5], "terms": ["dalawang mata", "two eyes", "paningin", "depth", "lalim", "distansya", "utak", "sukat", "salo", "bola"], "fact": {"tl": "Ang pagkakaroon ng dalawang mata na bahagyang magkaiba ang nakikita ay nagbibigay-daan sa utak na husgahan ang lalim at distansya. Ito ang dahilan kaya kaya mong saluhin ang isang bola o malaman kung gaano kalayo ang isang bagay.", "en": "Having two eyes that see slightly different views lets the brain judge depth and distance. That is why you can catch a ball or tell how far away something is.", "bis": "Ang pagbaton og duha ka mata nga gamayng lahi ang makita maghatag og kahigayonan sa utok aron hukman ang giladmon ug gilay-on. Mao nga makasalo ka og bola o makahibalo kon unsa kalayo ang usa ka butang."}, "source": "NRC LS1.A; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "why-we-feel-sleepy-g3", "domain": "LIVING_THINGS", "topic": "why we feel sleepy", "grades": [3, 4, 5], "terms": ["antok", "sleepy", "tulog", "sleep", "pagod", "kemikal", "utak", "brain", "gabi", "enerhiya", "puyat"], "fact": {"tl": "Inaantok tayo dahil unti-unting naiipon ang isang kemikal sa utak habang gising tayo sa buong araw. Kapag natulog tayo, inaalis ng katawan ang kemikal na ito at ibinabalik ang ating enerhiya.", "en": "We feel sleepy because a chemical slowly builds up in the brain while we are awake all day. When we sleep, the body clears that chemical away and restores our energy.", "bis": "Katulgon ta tungod kay hinay-hinayng matipon ang usa ka kemikal sa utok samtang nagmata ta sa tibuok adlaw. Kon matulog ta, kuhaon sa lawas kining kemikal ug ibalik ang atong kusog."}, "source": "NRC LS1.A", "generator": "claude", "reviewed": false},
  {"id": "why-ball-bounces-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "why a ball bounces", "grades": [3, 4, 5], "terms": ["bola", "ball", "tumatalbog", "bounce", "enerhiya", "energy", "elastic", "lupa", "tumama", "bumalik", "goma"], "fact": {"tl": "Tumatalbog ang bola dahil kapag tumama ito sa lupa, naiipit at nipis ang hugis nito habang naiimbak ang enerhiya. Pagkatapos, bumabalik ito sa dati nitong hugis at itinutulak ang sarili paahon mula sa lupa.", "en": "A ball bounces because when it hits the ground it squashes, storing energy. Then it springs back to its shape and pushes itself up off the ground.", "bis": "Mounlod ang bola tungod kay kon mosukmag kini sa yuta, mapislat ug manipis ang porma niini samtang gitipigan ang kusog. Unya mobalik kini sa dati nga porma ug motukmod sa kaugalingon pataas gikan sa yuta."}, "source": "NRC PS3.B; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "action-reaction-rockets-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "action and reaction", "grades": [6, 7, 8], "terms": ["action reaction", "aksyon", "reaksyon", "Newton", "puwersa", "force", "rocket", "kohete", "tulak", "gas", "pataas", "balanse"], "fact": {"tl": "Sa bawat tulak ay may katumbas na tulak pabalik (action–reaction). Ang rocket ay tumataas dahil itinutulak nito ang mainit na gas pababa, at bilang ganti, itinutulak ng gas ang rocket pataas.", "en": "For every push there is an equal push back (action–reaction). A rocket lifts off because it pushes hot gas downward, and in return the gas pushes the rocket upward.", "bis": "Sa matag tukmod adunay katumbas nga tukmod balik (action–reaction). Mosaka ang rocket tungod kay gitukmod niini ang init nga gas paubos, ug isip balos, gitukmod sa gas ang rocket pataas."}, "source": "NRC PS2.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-fan-cools-you-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "why a fan cools you", "grades": [3, 4, 5], "terms": ["bentilador", "fan", "electric fan", "hangin", "pawis", "sweat", "evaporation", "init", "balat", "lamig", "presko"], "fact": {"tl": "Hindi talaga pinapalamig ng bentilador ang hangin — pinaiihip lang nito ang hangin sa ating balat para mas mabilis sumingaw ang pawis. Kapag sumisingaw ang pawis, dinadala nito ang init palayo, kaya nararamdaman nating presko.", "en": "A fan doesn't actually cool the air — it just blows air across your skin so your sweat evaporates faster. As sweat evaporates, it carries heat away, so you feel cooler.", "bis": "Ang bentilador dili gyud mopabugnaw sa hangin — gihuyop lang niini ang hangin sa atong panit aron mas paspas mosingaw ang singot. Samtang mosingaw ang singot, dad-on niini ang init palayo, maong mobati tag kabugnaw."}, "source": "NRC PS3.B; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "inertia-seatbelt-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "inertia", "grades": [6, 7, 8], "terms": ["inertia", "sasakyan", "seatbelt", "sinturon", "biglang preno", "galaw", "motion", "Newton", "huminto", "patuloy", "kaligtasan"], "fact": {"tl": "Ang inertia ay ang pagkahilig ng bagay na ipagpatuloy ang kasalukuyang galaw nito. Kapag biglang huminto ang sasakyan, patuloy pa ring gumagalaw pasulong ang katawan mo — kaya pinoprotektahan ka ng seatbelt.", "en": "Inertia is an object's tendency to keep doing what it is already doing. When a car stops suddenly, your body keeps moving forward — which is why a seatbelt protects you.", "bis": "Ang inertia mao ang kiling sa usa ka butang nga ipadayon ang iyang kasamtangang lihok. Kon kalit mohunong ang sakyanan, magpadayon og lihok paabante ang imong lawas — mao nga panalipdan ka sa seatbelt."}, "source": "NRC PS2.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-compass-points-north-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "why a compass points north", "grades": [5, 6, 7], "terms": ["compass", "kompas", "hilaga", "north", "magnet", "magnetic field", "Earth", "karayom", "direksyon", "timog"], "fact": {"tl": "Ang karayom ng kompas ay isang maliit na magnet na pumapantay sa magnetic field ng Earth. Kaya palaging tumuturo ito sa magnetic north, na tumutulong sa atin malaman ang direksyon.", "en": "A compass needle is a small magnet that lines up with Earth's magnetic field. That is why it always points toward magnetic north, helping us find direction.", "bis": "Ang dagom sa compass usa ka gamayng magnet nga mopahiluna sa magnetic field sa Earth. Mao nga kanunay kining motudlo sa magnetic north, nga makatabang nato mahibal-an ang direksyon."}, "source": "NRC PS2.B; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "friction-makes-heat-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "why friction makes heat", "grades": [3, 4, 5], "terms": ["friction", "kuskos", "init", "heat", "kamay", "kiskis", "galaw", "energy", "mainit", "palamig"], "fact": {"tl": "Ang pagkuskos ng dalawang bagay ay gumagawa ng init dahil ginagawang init ng friction ang enerhiya ng galaw. Kaya kapag kinuskos mo ang iyong mga kamay, umiinit ang mga ito.", "en": "Rubbing two things together makes heat because friction turns the energy of motion into heat. That is why rubbing your hands together warms them up.", "bis": "Ang pagkuskos sa duha ka butang maghimog init tungod kay ang friction mohimo sa kusog sa lihok ngadto sa init. Mao nga kon imong kuskuson ang imong mga kamot, moinit kini."}, "source": "NRC PS3.B; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "how-flashlight-works-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "how a flashlight works", "grades": [3, 4, 5], "terms": ["flashlight", "flashlight", "baterya", "battery", "ilaw", "liwanag", "light", "kuryente", "kawad", "bombilya", "LED", "switch"], "fact": {"tl": "Gumagana ang flashlight kapag itinutulak ng baterya ang kuryente sa pamamagitan ng kawad papunta sa bombilya o LED, na nagpapalit ng enerhiya ng kuryente tungo sa liwanag. Bumubukas ang daloy kapag pinindot ang switch.", "en": "A flashlight works when a battery pushes electricity through a wire to a bulb or LED, which turns the electric energy into light. Pressing the switch completes the circuit so the current can flow.", "bis": "Molihok ang flashlight kon ang baterya motukmod sa kuryente agi sa kawad ngadto sa bombilya o LED, nga mohimo sa kusog sa kuryente ngadto sa kahayag. Ang pagpislit sa switch mohingpit sa sirkito aron modaloy ang kuryente."}, "source": "NRC PS3.B; PS4.A", "generator": "claude", "reviewed": false},
  {"id": "why-siren-changes-pitch-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "why a siren changes pitch", "grades": [6, 7, 8], "terms": ["sirena", "siren", "Doppler", "tunog", "sound", "pitch", "ambulansya", "papalapit", "papalayo", "tono", "alon ng tunog"], "fact": {"tl": "Ang sirena ng dumadaang ambulansya ay tunog na mas mataas habang papalapit ito at mas mababa kapag papalayo na. Ito ay dahil nagsisiksikan ang mga alon ng tunog kapag palapit at humihiwalay kapag palayo — ang tinatawag na Doppler effect.", "en": "A passing ambulance siren sounds higher as it comes toward you and lower as it moves away. This is because the sound waves bunch up when approaching and spread out when leaving — the Doppler effect.", "bis": "Ang sirena sa naglabay nga ambulansya mas taas og tono samtang nagpaduol kini ug mas ubos kon nagpalayo na. Tungod kini kay magtapok ang mga balod sa tingog kon nagpaduol ug magkatag kon nagpalayo — ang gitawag nga Doppler effect."}, "source": "NRC PS4.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "pulley-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "pulley", "grades": [4, 5, 6], "terms": ["pulley", "kalo", "gulong", "lubid", "rope", "simple machine", "pagbuhat", "lift", "mabigat", "poso", "bandila", "direksyon"], "fact": {"tl": "Ang pulley ay isang gulong na may lubid na nagbabago ng direksyon ng iyong hila. Sa halip na buhatin pataas ang mabigat na bagay, makakahila ka pababa — kaya mas madali, tulad sa pagtaas ng bandila o pagsalok ng tubig sa poso.", "en": "A pulley is a wheel with a rope that changes the direction of your pull. Instead of lifting a heavy load up, you can pull down — which is easier, like raising a flag or drawing water from a well.", "bis": "Ang pulley usa ka ligid nga adunay pisi nga mag-usab sa direksyon sa imong bira. Imbis nga alsahon pataas ang bug-at nga butang, makabira ka paubos — mas sayon, sama sa pagpataas sa bandera o pagkalos og tubig sa atabay."}, "source": "NRC PS3.C; AAAS BSL Ch.8", "generator": "claude", "reviewed": false},
  {"id": "why-knife-cuts-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "why a sharp knife cuts", "grades": [4, 5, 6], "terms": ["kutsilyo", "knife", "matalas", "sharp", "presyon", "pressure", "gilid", "manipis", "puwersa", "hiwa", "talim"], "fact": {"tl": "Mahusay humiwa ang matalas na kutsilyo dahil ang manipis na talim nito ay nagpapatong ng buong puwersa mo sa napakaliit na lugar, kaya napakataas ng presyon na pumuputol sa bagay. Mahirap humiwa ang mapurol dahil kumakalat ang puwersa.", "en": "A sharp knife cuts well because its thin edge puts all of your push onto a very tiny area, making very high pressure that slices through. A dull knife cuts poorly because the force spreads out.", "bis": "Maayong mohiwa ang hait nga kutsilyo tungod kay ang nipis nga sulab niini magbutang sa tibuok nimong kusog sa gamay kaayong dapit, maong taas kaayo ang presyon nga moputol sa butang. Lisod mohiwa ang habol kay magkatag ang kusog."}, "source": "NRC PS2.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-float-easier-seawater-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "why we float easier in seawater", "grades": [5, 6], "terms": ["lumulutang", "float", "dagat", "seawater", "tubig-alat", "asin", "salt", "density", "buoyancy", "swimming pool", "tabang"], "fact": {"tl": "Mas madali kang lumutang sa dagat kaysa sa swimming pool dahil mas siksik (mas mataas ang density) ang tubig-alat kaysa tubig-tabang. Dahil dito, mas malakas ang pagtulak ng dagat paahon sa iyong katawan.", "en": "You float more easily in the sea than in a swimming pool because salt water is denser than fresh water. Because of that, the sea pushes up on your body more strongly.", "bis": "Mas sayon kang molutaw sa dagat kaysa swimming pool tungod kay mas baga (mas taas og density) ang tubig-asin kaysa tab-ang nga tubig. Tungod niini, mas kusgan ang pagtukmod sa dagat pataas sa imong lawas."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "crystals-g6", "domain": "MATTER", "topic": "crystals", "grades": [5, 6, 7], "terms": ["kristal", "crystal", "asin", "salt", "asukal", "sugar", "particle", "hugis", "pattern", "tubig", "sumingaw", "yelo"], "fact": {"tl": "Ang mga kristal tulad ng asin at asukal ay nabubuo kapag ang kanilang mga particle ay nag-aayos sa maayos at paulit-ulit na pattern habang lumalamig ang likido o sumisingaw ang tubig. Kaya may tiyak na hugis ang mga butil ng asin.", "en": "Crystals like salt and sugar form when their particles arrange into a neat, repeating pattern as a liquid cools or water evaporates. That is why grains of salt have a regular shape.", "bis": "Ang mga kristal sama sa asin ug asukar maporma kon ang ilang mga partikulo mag-areglo sa hapsay ug balik-balik nga pattern samtang mobugnaw ang likido o mosingaw ang tubig. Mao nga ang lugas sa asin adunay piho nga porma."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-metals-shiny-g5", "domain": "MATTER", "topic": "why metals are shiny", "grades": [4, 5, 6], "terms": ["metal", "bakal", "makintab", "shiny", "kinang", "liwanag", "light", "salamin", "electron", "ibabaw", "reflection"], "fact": {"tl": "Makintab ang mga metal dahil ang makinis nilang ibabaw at malalayang electron ay pantay na sumasalamin ng liwanag pabalik. Kaya kumikinang ang pinakintab na metal tulad ng salamin.", "en": "Metals look shiny because their smooth surfaces and free electrons reflect light back evenly. That is why polished metal gleams almost like a mirror.", "bis": "Makintab ang mga metal tungod kay ang hapsay nilang nawong ug gawasnong electron pantay nga mosalamin sa kahayag pabalik. Mao nga mosidlak ang gipasinaw nga metal sama sa salamin."}, "source": "NRC PS4.B; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-ice-cream-melts-g3", "domain": "MATTER", "topic": "why ice cream melts", "grades": [2, 3, 4], "terms": ["sorbetes", "ice cream", "natutunaw", "melt", "init", "heat", "yelo", "likido", "malamig", "particle", "araw"], "fact": {"tl": "Natutunaw ang sorbetes kapag ang init mula sa mainit na hangin ay nagbibigay sa nagyelong particle nito ng sapat na enerhiya para muling maging likido. Kaya mabilis itong natutunaw sa labas kapag mainit.", "en": "Ice cream melts when heat from the warm air gives its frozen particles enough energy to turn back into liquid. That is why it melts fast outdoors on a hot day.", "bis": "Matunaw ang sorbetes kon ang init gikan sa init nga hangin mohatag sa mga nagyelo niini nga partikulo og igong kusog aron mahimo na usab likido. Mao nga paspas kini matunaw sa gawas kon init."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "baking-soda-vinegar-fizz-g4", "domain": "MATTER", "topic": "baking soda and vinegar reaction", "grades": [4, 5, 6], "terms": ["baking soda", "suka", "vinegar", "bula", "fizz", "carbon dioxide", "gas", "chemical reaction", "reaksyon", "bulkan", "eksperimento"], "fact": {"tl": "Kapag pinaghalo ang baking soda at suka, bumubula ito dahil nagreaksyon sila at bumubuo ng carbon-dioxide na gas — isang chemical change. Ito ang dahilan kung bakit 'sumasabog' ang laruang bulkan sa science fair.", "en": "When you mix baking soda and vinegar, it bubbles because they react to form carbon-dioxide gas — a chemical change. This is why a toy volcano 'erupts' at a science fair.", "bis": "Kon sagolon ang baking soda ug suka, mobula kini tungod kay nag-react sila ug naghimog carbon-dioxide nga gas — usa ka chemical change. Mao kini ngano 'mobuto' ang dulaang bulkan sa science fair."}, "source": "NRC PS1.B; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-we-have-fingerprints-g4", "domain": "LIVING_THINGS", "topic": "why we have fingerprints", "grades": [3, 4, 5], "terms": ["fingerprint", "bakas ng daliri", "daliri", "finger", "hawak", "grip", "balat", "ridge", "kakaiba", "unique", "kambal"], "fact": {"tl": "Ang mga fingerprint ay maliliit na guhit (ridges) sa ating mga daliri na tumutulong sa paghawak ng bagay at pagdama ng texture. Natatangi ang pattern ng bawat tao — magkaiba pa rin kahit kambal.", "en": "Fingerprints are tiny ridges on our fingers that help us grip things and feel textures. Everyone's pattern is unique — even identical twins have different fingerprints.", "bis": "Ang mga fingerprint mao ang gagmayng linya (ridges) sa atong tudlo nga makatabang sa pagkupot og butang ug pagbati sa texture. Talagsaon ang pattern sa matag tawo — lahi gihapon bisan kambal."}, "source": "NRC LS1.A; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "why-two-ears-g4", "domain": "LIVING_THINGS", "topic": "why we have two ears", "grades": [3, 4, 5], "terms": ["dalawang tainga", "two ears", "tunog", "sound", "direksyon", "pandinig", "hearing", "utak", "saan", "galing"], "fact": {"tl": "Ang dalawang tainga ay nagpapahintulot sa utak na ikumpara kung kailan umabot ang tunog sa bawat gilid. Kaya nalalaman natin kung saang direksyon nanggaling ang isang tunog.", "en": "Two ears let the brain compare when a sound reaches each side. That is how we can tell which direction a sound came from.", "bis": "Ang duha ka dalunggan magtugot sa utok nga itandi kanus-a moabot ang tingog sa matag kilid. Mao nga mahibal-an nato kon asa nga direksyon naggikan ang usa ka tingog."}, "source": "NRC LS1.A; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "animal-hibernation-g4", "domain": "LIVING_THINGS", "topic": "animal hibernation", "grades": [4, 5], "terms": ["hibernation", "hibernate", "hayop", "animal", "tulog", "taglamig", "winter", "enerhiya", "pagkain", "oso", "bear"], "fact": {"tl": "Ang ilang hayop ay nag-hi-hibernate — mahimbing na natutulog sa buong malamig na taglamig — para makatipid ng enerhiya kapag kakaunti ang pagkain. Bumabagal ang kanilang tibok ng puso at paghinga.", "en": "Some animals hibernate — sleep deeply through the cold winter — to save energy when food is scarce. Their heartbeat and breathing slow way down.", "bis": "Ang pipila ka hayop mag-hibernate — mahinanok nga matulog sa tibuok bugnaw nga tingtugnaw — aron makatipig og kusog kon nihit ang pagkaon. Mohinay pag-ayo ang ilang pitik sa kasingkasing ug pagginhawa."}, "source": "NRC LS1.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "animal-migration-g4", "domain": "LIVING_THINGS", "topic": "animal migration", "grades": [4, 5], "terms": ["migration", "paglipat", "hayop", "animal", "ibon", "bird", "panahon", "season", "pagkain", "init", "langaw? no", "lumilipad"], "fact": {"tl": "Maraming hayop ang naglalakbay nang malayo ayon sa panahon (migration) para maghanap ng pagkain, init, o lugar na mapag-aalagaan ng anak — tulad ng mga ibong lumilipad patungong mainit na lugar kapag malamig.", "en": "Many animals migrate — travel long distances with the seasons — to find food, warmth, or places to raise their young, like birds flying to warmer places when it gets cold.", "bis": "Daghang hayop ang mobiyahe og layo sumala sa panahon (migration) aron mangita og pagkaon, kainit, o dapit nga kapadakuan sa ilang anak — sama sa mga langgam nga molupad sa mas init nga dapit kon mobugnaw."}, "source": "NRC LS1.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "pollination-g4", "domain": "LIVING_THINGS", "topic": "pollination", "grades": [3, 4, 5], "terms": ["pollination", "polinasyon", "bulaklak", "flower", "pollen", "bubuyog", "bee", "paruparo", "butterfly", "buto", "seed", "prutas"], "fact": {"tl": "Ang pollination ay kapag ang pollen (alikabok ng bulaklak) ay nalilipat mula sa isang bulaklak patungo sa iba — kadalasan sa tulong ng bubuyog, paruparo, o hangin. Dahil dito, nakakagawa ang halaman ng buto at prutas.", "en": "Pollination is when pollen moves from one flower to another — often carried by bees, butterflies, or wind. This lets plants make seeds and fruit.", "bis": "Ang pollination mao kon ang pollen (abog sa bulak) mabalhin gikan sa usa ka bulak ngadto sa lain — kasagaran dala sa buyog, alibangbang, o hangin. Tungod niini, makahimo ang tanom og liso ug prutas."}, "source": "NRC LS1.C; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "how-bees-make-honey-g4", "domain": "LIVING_THINGS", "topic": "how bees make honey", "grades": [3, 4, 5], "terms": ["bubuyog", "bee", "pulot", "honey", "nectar", "bulaklak", "pakpak", "bahay-pukyutan", "hive", "matamis", "tinipon"], "fact": {"tl": "Kinukuha ng bubuyog ang matamis na nectar mula sa mga bulaklak, iniimbak ito, at pinapaypayan gamit ang kanilang pakpak para palaputin tungo sa pulot. Ito ang pagkain ng kolonya sa bahay-pukyutan.", "en": "Bees collect sweet nectar from flowers, store it, and fan it with their wings to thicken it into honey. The honey feeds the whole colony in the hive.", "bis": "Manguha ang mga buyog og tam-is nga nectar gikan sa mga bulak, tipigan kini, ug paypayan gamit ang ilang pako aron pabagaon ngadto sa dugos. Ang dugos maoy pagkaon sa tibuok kolonya sa balay-putyukan."}, "source": "NRC LS1.C; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "why-food-spoils-mold-g4", "domain": "LIVING_THINGS", "topic": "why food spoils", "grades": [3, 4, 5], "terms": ["pagkain", "food", "nabubulok", "spoil", "amag", "mold", "bakterya", "bacteria", "ref", "fridge", "malamig", "sira"], "fact": {"tl": "Nabubulok ang pagkain kapag dumadami ang bakterya at amag dito. Pinapabagal sila ng paglalagay ng pagkain sa malamig o tuyong lugar — kaya natin ginagamit ang ref para mas matagal bago masira ang pagkain.", "en": "Food spoils when bacteria and mold grow on it. Keeping food cold or dry slows them down — that is why we use the fridge to make food last longer before it goes bad.", "bis": "Madunot ang pagkaon kon modaghan ang bakterya ug agup-op niini. Mahinay sila kon ibutang ang pagkaon sa bugnaw o uga nga dapit — mao nga mogamit tag ref aron mas dugay molungtad ang pagkaon."}, "source": "NRC LS1.C; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "butterfly-metamorphosis-g3", "domain": "LIVING_THINGS", "topic": "butterfly metamorphosis", "grades": [2, 3, 4], "terms": ["paruparo", "butterfly", "metamorphosis", "itlog", "egg", "higad", "caterpillar", "uod", "pupa", "chrysalis", "yugto"], "fact": {"tl": "Nagbabago ang anyo ng paruparo sa apat na yugto: itlog, higad (caterpillar), pupa (chrysalis), at saka ang ganap na paruparo. Ito ay tinatawag na complete metamorphosis.", "en": "A butterfly changes form in four stages: egg, caterpillar (larva), pupa (chrysalis), and finally the adult butterfly. This is called complete metamorphosis.", "bis": "Mausab ang porma sa alibangbang sa upat ka hugna: itlog, ulod (caterpillar), pupa (chrysalis), ug sa kataposan ang hingkod nga alibangbang. Gitawag kini nga complete metamorphosis."}, "source": "NRC LS1.B; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "why-dogs-pant-g3", "domain": "LIVING_THINGS", "topic": "why dogs pant", "grades": [2, 3, 4], "terms": ["aso", "dog", "humihingal", "pant", "dila", "tongue", "init", "palamig", "cool", "pawis", "sweat", "hininga"], "fact": {"tl": "Humihingal ang aso para magpalamig dahil hindi sila pinagpapawisan sa balat tulad natin. Sa paghingal, sumisingaw ang tubig mula sa kanilang dila at bibig, na nag-aalis ng init sa katawan.", "en": "Dogs pant to cool down because they can't sweat through their skin like we do. Panting evaporates water from their tongue and mouth, which carries heat away.", "bis": "Maghangak ang iro aron mobugnaw tungod kay dili sila singot sa panit sama nato. Sa paghangak, mosingaw ang tubig gikan sa ilang dila ug baba, nga magkuha sa init sa lawas."}, "source": "NRC LS1.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "nocturnal-animals-g3", "domain": "LIVING_THINGS", "topic": "nocturnal animals", "grades": [2, 3, 4], "terms": ["nocturnal", "gabi", "night", "hayop", "animal", "kuwago", "owl", "paniki", "bat", "dilim", "gising", "natutulog", "mata"], "fact": {"tl": "Ang mga nocturnal na hayop tulad ng kuwago at paniki ay gising at aktibo sa gabi, at natutulog kapag araw. May espesyal silang mga mata o pandinig para makahanap ng pagkain sa dilim.", "en": "Nocturnal animals like owls and bats are awake and active at night and sleep during the day. They have special eyes or hearing to find food in the dark.", "bis": "Ang mga nocturnal nga hayop sama sa ngiwngiw ug kabog nagmata ug aktibo sa gabii, ug matulog kon adlaw. Aduna silay espesyal nga mata o pandungog aron makapangita og pagkaon sa kangitngit."}, "source": "NRC LS1.A; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "what-is-aurora-g6", "domain": "EARTH_SPACE", "topic": "what is an aurora", "grades": [6, 7, 8], "terms": ["aurora", "northern lights", "ilaw sa langit", "particle", "araw", "sun", "gas", "atmosphere", "poste", "pole", "kulay", "liwanag"], "fact": {"tl": "Ang aurora (northern o southern lights) ay kumikinang na kulay sa langit na nabubuo kapag ang mga particle mula sa araw ay tumatama sa mga gas sa itaas ng atmosphere malapit sa mga poste ng Earth. Hindi ito nakikita sa Pilipinas dahil malayo tayo sa poste.", "en": "An aurora (northern or southern lights) is glowing color in the sky that forms when particles from the sun hit gases high in the atmosphere near Earth's poles. It is not seen in the Philippines because we are far from the poles.", "bis": "Ang aurora (northern o southern lights) mao ang nagsidlak nga kolor sa langit nga maporma kon ang mga partikulo gikan sa adlaw mosukmag sa mga gas sa taas sa atmospera duol sa mga poste sa Earth. Dili kini makita sa Pilipinas kay layo ta sa poste."}, "source": "NRC ESS1.B; PS3.D", "generator": "claude", "reviewed": false},
  {"id": "ozone-layer-g6", "domain": "EARTH_SPACE", "topic": "the ozone layer", "grades": [6, 7, 8], "terms": ["ozone", "ozone layer", "atmosphere", "UV", "ultraviolet", "araw", "sun", "proteksyon", "sanhi", "radiation", "kalanguban"], "fact": {"tl": "Ang ozone layer ay bahagi ng atmosphere na sumasalag sa atin mula sa karamihan ng nakakapinsalang ultraviolet (UV) na sinag ng araw. Kung wala ito, mas mapanganib ang sikat ng araw sa balat at mata.", "en": "The ozone layer is a part of the atmosphere that shields us from most of the sun's harmful ultraviolet (UV) rays. Without it, sunlight would be far more dangerous to our skin and eyes.", "bis": "Ang ozone layer kabahin sa atmospera nga manalipod kanato gikan sa kadaghanan sa makadaot nga ultraviolet (UV) nga sidlak sa adlaw. Kon wala kini, mas peligroso ang sidlak sa adlaw sa atong panit ug mata."}, "source": "NRC ESS3.C; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-leap-year-g5", "domain": "EARTH_SPACE", "topic": "why we have leap years", "grades": [5, 6], "terms": ["leap year", "bisiyesto", "Pebrero", "February", "365", "366", "araw", "day", "kalendaryo", "Earth", "orbit", "umiikot"], "fact": {"tl": "Ang isang taon ay talagang halos 365 at kalahating-kapat na araw — ang oras na iniikot ng Earth sa araw. Kaya tuwing 4 na taon, nagdadagdag tayo ng isang araw (Pebrero 29) para manatiling tama ang kalendaryo. Ito ang leap year (bisiyesto).", "en": "A year is really about 365 and a quarter days — the time Earth takes to orbit the sun. So every 4 years we add one extra day (February 29) to keep the calendar lined up. That is a leap year.", "bis": "Ang usa ka tuig halos 365 ug tunga-kuwarto ka adlaw — ang panahon nga libuton sa Earth ang adlaw. Maong matag 4 ka tuig, magdugang tag usa ka adlaw (Pebrero 29) aron magpabiling sakto ang kalendaryo. Mao kini ang leap year."}, "source": "NRC ESS1.B", "generator": "claude", "reviewed": false},
  {"id": "what-is-light-year-g6", "domain": "EARTH_SPACE", "topic": "what is a light-year", "grades": [6, 7, 8], "terms": ["light-year", "light year", "liwanag", "light", "layo", "distance", "bituin", "star", "kalawakan", "taon", "year", "sukat"], "fact": {"tl": "Ang light-year ay ang layong nilalakbay ng liwanag sa loob ng isang taon — humigit-kumulang 9.5 trilyong kilometro. Ginagamit ito para sukatin ang napakalalayong distansya sa pagitan ng mga bituin.", "en": "A light-year is the distance light travels in one year — about 9.5 trillion kilometers. It is used to measure the huge distances between the stars.", "bis": "Ang light-year mao ang gilay-on nga gibiyahe sa kahayag sulod sa usa ka tuig — mga 9.5 ka trilyong kilometro. Gigamit kini aron sukoron ang dagkong gilay-on tali sa mga bituon."}, "source": "NRC ESS1.B", "generator": "claude", "reviewed": false},
  {"id": "why-bubbles-pop-g3", "domain": "MATTER", "topic": "why bubbles pop", "grades": [2, 3, 4], "terms": ["bula", "bubble", "pumuputok", "pop", "sabon", "pelikula", "film", "tubig", "tuyo", "hawak", "nasira"], "fact": {"tl": "Pumuputok ang bula kapag natutuyo ang manipis na pelikula ng tubig-sabon nito o kapag may humawak dito, kaya nasisira ang ibabaw at tumatakas ang hangin sa loob.", "en": "A bubble pops when its thin film of soapy water dries out or something touches it, breaking the surface so the air inside escapes.", "bis": "Mobuto ang bula kon mauga ang nipis nga pelikula sa tubig-sabon niini o kon adunay mohikap niini, maong maguba ang gawas ug moikyas ang hangin sa sulod."}, "source": "AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-lemon-sour-acid-g4", "domain": "MATTER", "topic": "why citrus tastes sour", "grades": [3, 4, 5], "terms": ["maasim", "sour", "kalamansi", "lemon", "dayap", "asido", "acid", "citric", "dila", "tongue", "prutas", "suka"], "fact": {"tl": "Maasim ang lasa ng kalamansi at lemon dahil naglalaman sila ng banayad na asido (citric acid). Nararamdaman ng ating dila ang mga asido bilang maasim na lasa.", "en": "Lemons and calamansi taste sour because they contain a mild acid (citric acid). Our tongue senses acids as a sour taste.", "bis": "Aslom ang lasa sa kalamansi ug lemon tungod kay aduna silay hinay nga asido (citric acid). Mabati sa atong dila ang mga asido isip aslom nga lami."}, "source": "NRC PS1.B; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-glass-brittle-g5", "domain": "MATTER", "topic": "why glass is brittle", "grades": [5, 6], "terms": ["salamin", "glass", "babasagin", "brittle", "basag", "shatter", "particle", "matigas", "rigid", "lamat", "crack"], "fact": {"tl": "Madaling mabasag ang salamin dahil ang mga particle nito ay nakatali sa matigas na pattern na hindi makadausdos. Kapag tinamaan nang malakas, mabilis kumakalat ang lamat hanggang mabasag ito.", "en": "Glass shatters easily because its particles are locked in a rigid pattern with no way to slide past each other. A sharp blow makes cracks spread fast until it breaks.", "bis": "Sayon mabuak ang salamin tungod kay ang mga partikulo niini gigapos sa gahi nga pattern nga dili makadalin-as. Kon igoon og kusog, paspas mokatag ang liki hangtod mabuak kini."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-rubber-stretches-g4", "domain": "MATTER", "topic": "why rubber stretches", "grades": [4, 5, 6], "terms": ["goma", "rubber", "umuunat", "stretch", "elastic", "bumabalik", "molekula", "kulot", "coiled", "banat", "laso"], "fact": {"tl": "Umuunat ang goma at bumabalik sa dati nitong hugis dahil ang mahahaba at nakakulot nitong molekula ay naghahat kapag hinila at nagkukulot muli kapag binitawan. Kaya nababanat ang rubber band.", "en": "Rubber stretches and snaps back because its long, coiled molecules uncoil when you pull them and recoil when you let go. That is why a rubber band springs back.", "bis": "Mounat ang goma ug mobalik sa dati niini nga porma tungod kay ang taas ug kulot niini nga molekula mobukhad kon birahon ug mokulot pag-usab kon buhian. Mao nga mobalik ang rubber band."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "alloys-g6", "domain": "MATTER", "topic": "alloys", "grades": [6, 7, 8], "terms": ["alloy", "haluang metal", "halo", "metal", "bakal", "steel", "asero", "tanso", "bronze", "carbon", "matibay", "matigas"], "fact": {"tl": "Ang alloy ay haluan ng mga metal (o metal at ibang sangkap) na ginagawang mas matibay o mas kapaki-pakinabang. Halimbawa: ang asero (steel) ay bakal na may halong carbon, at ang bronze ay tanso na may halong lata.", "en": "An alloy is a mix of metals (or a metal plus another element) made stronger or more useful. For example, steel is iron mixed with carbon, and bronze is copper mixed with tin.", "bis": "Ang alloy mao ang sagol nga mga metal (o metal ug laing sangkap) nga gihimong mas lig-on o mas mapuslanon. Pananglitan: ang asero (steel) puthaw nga gisagolan og carbon, ug ang bronze tumbaga nga gisagolan og lata."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "plasma-fourth-state-g7", "domain": "MATTER", "topic": "plasma the fourth state", "grades": [7, 8, 9, 10], "terms": ["plasma", "ikaapat na estado", "fourth state", "solid", "liquid", "gas", "araw", "sun", "kidlat", "lightning", "neon", "mainit"], "fact": {"tl": "Bukod sa solid, liquid, at gas, may ikaapat na estado ng bagay na tinatawag na plasma — napakainit na nagliliwanag na gas na may mga particle na may kuryente. Matatagpuan ito sa araw, sa kidlat, at sa mga neon na ilaw.", "en": "Besides solid, liquid, and gas, there is a fourth state of matter called plasma — super-hot, glowing gas made of charged particles. It is found in the sun, in lightning, and in neon lights.", "bis": "Gawas sa solid, liquid, ug gas, adunay ikaupat nga kahimtang sa butang nga gitawag plasma — init kaayo, nagsidlak nga gas nga adunay mga partikulo nga may kuryente. Makita kini sa adlaw, sa kilat, ug sa mga neon nga suga."}, "source": "NRC PS1.A", "generator": "claude", "reviewed": false},
  {"id": "gas-fills-container-g4", "domain": "MATTER", "topic": "why gas fills its container", "grades": [4, 5, 6], "terms": ["gas", "hangin", "lalagyan", "container", "kumakalat", "spread", "particle", "malayang gumalaw", "hugis", "lobo", "puno"], "fact": {"tl": "Kumakalat ang gas para punuin nang buo ang anumang lalagyan dahil malayang gumagalaw ang mga particle nito sa lahat ng direksyon — hindi tulad ng likido o solid na may tiyak na hugis o dami.", "en": "A gas spreads out to completely fill any container because its particles move freely in all directions — unlike a liquid or solid, which keep a set volume or shape.", "bis": "Mokatag ang gas aron pun-on sa hingpit ang bisan unsang sudlanan tungod kay ang mga partikulo niini gawasnong molihok sa tanang direksyon — dili sama sa likido o solid nga adunay piho nga gidaghanon o porma."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "saturated-solution-g6", "domain": "MATTER", "topic": "saturated solution", "grades": [6, 7, 8], "terms": ["saturated", "saturated solution", "natunaw", "dissolve", "asukal", "sugar", "asin", "salt", "tubig", "limitado", "init", "sobra"], "fact": {"tl": "May hangganan kung gaano karaming asukal o asin ang kayang tunawin ng tubig. Kapag hindi na ito makakatunaw pa, tinatawag itong saturated, at ang sobrang solid ay naiipon sa ilalim. Mas marami itong matutunaw kapag pinainit ang tubig.", "en": "Water can only dissolve so much sugar or salt. Once it cannot hold any more, it is 'saturated', and extra solid just settles at the bottom. Warming the water lets it dissolve more.", "bis": "Adunay kinutoban kon pila ka asukar o asin ang matunaw sa tubig. Kon dili na kini makatunaw pa, gitawag kining saturated, ug ang sobrang solid molingkod sa ilalom. Mas daghan kini matunaw kon initon ang tubig."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "air-resistance-parachute-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "air resistance and parachutes", "grades": [4, 5, 6], "terms": ["air resistance", "hangin", "parachute", "payong-hangin", "bagsak", "fall", "mabagal", "lapad", "drag", "puwersa", "pababa"], "fact": {"tl": "Pinapabagal ng parachute ang pagbagsak dahil ang malapad nitong ibabaw ay tumutulak laban sa maraming hangin (air resistance), kaya marahan itong nakakahawak sa taong nahuhulog.", "en": "A parachute slows a fall because its wide surface pushes against a lot of air (air resistance), gently holding back the falling person.", "bis": "Gipahinay sa parachute ang pagkahulog tungod kay ang lapad niini nga nawong moduot batok sa daghang hangin (air resistance), maong hinay nga makapugong sa nahulog nga tawo."}, "source": "NRC PS2.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "why-feather-falls-slower-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "why a feather falls slower than a stone", "grades": [4, 5, 6], "terms": ["balahibo", "feather", "bato", "stone", "bumabagsak", "fall", "air resistance", "hangin", "buwan", "moon", "gravity", "magaan"], "fact": {"tl": "Mas mabagal bumagsak ang balahibo kaysa bato dahil mas malakas itinutulak ng air resistance ang magaan at malapad nitong hugis. Kung walang hangin tulad sa buwan, sabay silang babagsak dahil pareho ang hila ng gravity.", "en": "A feather falls slower than a stone because air resistance pushes harder on its light, wide shape. Without air, like on the moon, they would fall together because gravity pulls on both the same.", "bis": "Mas hinay mahulog ang balhibo kaysa bato tungod kay mas kusog ituklod sa air resistance ang gaan ug lapad niini nga porma. Kon walay hangin sama sa bulan, dungan silang mahulog kay parehas ang bira sa gravity."}, "source": "NRC PS2.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "inclined-plane-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "inclined plane", "grades": [4, 5, 6], "terms": ["inclined plane", "rampa", "ramp", "dalisdis", "simple machine", "puwersa", "force", "pataas", "mabigat", "push", "madali"], "fact": {"tl": "Ang rampa (inclined plane) ay nagbibigay-daan na itaas ang mabigat na bagay gamit ang mas kaunting puwersa sa pamamagitan ng pagtulak dito paahon sa banayad na dalisdis, sa halip na buhatin ito nang diretso pataas.", "en": "A ramp (inclined plane) lets you raise a heavy object with less force by pushing it up a gentle slope, instead of lifting it straight up.", "bis": "Ang rampa (inclined plane) magtugot nimo nga ipataas ang bug-at nga butang gamit ang mas gamayng kusog pinaagi sa pagtulod niini pasaka sa hinay nga bakilid, imbis nga alsahon kini deretso pataas."}, "source": "NRC PS3.C; AAAS BSL Ch.8", "generator": "claude", "reviewed": false},
  {"id": "centripetal-force-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "centripetal force", "grades": [6, 7, 8], "terms": ["centripetal", "puwersa", "force", "umiikot", "circle", "balde", "bucket", "tubig", "gitna", "center", "hindi natatapon", "ikot"], "fact": {"tl": "Kapag iniikot mo ang isang balde ng tubig sa bilog, may puwersang humihila dito papunta sa gitna (centripetal force) na pumipigil sa tubig na matapon — kahit pabaligtad ang balde sa itaas.", "en": "When you swing a bucket of water in a circle, a force pulls it toward the center (centripetal force) and keeps the water from spilling — even when the bucket is upside down at the top.", "bis": "Kon tuyokon nimo ang usa ka balde nga tubig sa lingin, adunay kusog nga mobira niini paingon sa tunga (centripetal force) nga makapugong sa tubig sa pag-awas — bisan kon balitad ang balde sa taas."}, "source": "NRC PS2.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "lightning-rod-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "lightning rod", "grades": [5, 6, 7], "terms": ["lightning rod", "kidlat", "lightning", "bubong", "metal", "kuryente", "grounding", "lupa", "gusali", "building", "proteksyon", "daan"], "fact": {"tl": "Ang lightning rod ay nagbibigay sa kidlat ng ligtas na daanang metal patungo diretso sa lupa, kaya naiingatan ang mga gusali mula sa sunog at pinsala kapag tinamaan ng kidlat.", "en": "A lightning rod gives lightning a safe metal path straight down into the ground, protecting buildings from fire and damage when lightning strikes.", "bis": "Ang lightning rod maghatag sa kilat og luwas nga agianan nga metal deretso ngadto sa yuta, maong mapanalipdan ang mga building gikan sa sunog ug kadaot kon maigo sa kilat."}, "source": "NRC PS3.A; AAAS BSL Ch.8", "generator": "claude", "reviewed": false},
  {"id": "why-we-blink-g3", "domain": "LIVING_THINGS", "topic": "why we blink", "grades": [2, 3, 4], "terms": ["kurap", "blink", "mata", "eye", "luha", "tears", "alikabok", "dust", "basa", "proteksyon", "liwanag", "reflex"], "fact": {"tl": "Kumukurap tayo para ikalat ang luha na naglilinis at nagpapabasa sa ating mga mata, at para protektahan ang mga ito mula sa alikabok at sobrang liwanag.", "en": "We blink to spread tears that clean and moisten our eyes, and to protect them from dust and bright light.", "bis": "Mokurap ta aron ikatag ang luha nga maglimpyo ug magpabasa sa atong mga mata, ug aron panalipdan kini gikan sa abog ug sobra nga kahayag."}, "source": "NRC LS1.A; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "why-we-have-eyebrows-g4", "domain": "LIVING_THINGS", "topic": "why we have eyebrows and eyelashes", "grades": [3, 4, 5], "terms": ["kilay", "eyebrow", "pilikmata", "eyelash", "pawis", "sweat", "ulan", "alikabok", "dust", "mata", "proteksyon"], "fact": {"tl": "Ang kilay ay pumipigil sa pawis at ulan na dumiretso sa mga mata, at ang pilikmata naman ay sumasalo sa alikabok bago ito makapasok sa mata. Pareho silang nagpoprotekta sa ating paningin.", "en": "Eyebrows keep sweat and rain from running into our eyes, and eyelashes catch dust before it gets in. Both help protect our eyesight.", "bis": "Ang kilay magpugong sa singot ug ulan nga modiretso sa mga mata, ug ang pilok mosalo sa abog una kini makasulod sa mata. Pareho silang manalipod sa atong panan-aw."}, "source": "NRC LS1.A; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "white-blood-cells-g5", "domain": "LIVING_THINGS", "topic": "white blood cells", "grades": [5, 6, 7], "terms": ["white blood cells", "puting selula ng dugo", "dugo", "blood", "mikrobyo", "germs", "immune", "depensa", "sundalo", "sakit", "laban"], "fact": {"tl": "Ang white blood cells (puting selula ng dugo) ay ang maliliit na tagapagtanggol ng katawan — hinahanap at nilalabanan nila ang mga mikrobyong nakakapasok sa atin, parang mga sundalo laban sa sakit.", "en": "White blood cells are the body's tiny defenders — they hunt down and destroy germs that get inside us, like soldiers fighting off illness.", "bis": "Ang white blood cells (puti nga selula sa dugo) mao ang gagmayng tigpanalipod sa lawas — pangitaon ug pakigbatokan nila ang mga mikrobyo nga makasulod kanato, sama sa mga sundalo batok sa sakit."}, "source": "NRC LS1.A; AAAS BSL Ch.6", "generator": "claude", "reviewed": false},
  {"id": "coral-reefs-g5", "domain": "LIVING_THINGS", "topic": "coral reefs", "grades": [4, 5, 6], "terms": ["coral reef", "bahura", "coral", "polyp", "hayop", "dagat", "isda", "fish", "Pilipinas", "tirahan", "biodiversity", "tubig-dagat"], "fact": {"tl": "Ang coral reef (bahura) ay itinatayo ng napakaliliit na hayop na tinatawag na coral polyp. Tirahan ito ng napakaraming nilalang sa dagat, at ang Pilipinas ay may ilan sa pinakamayamang reef sa buong mundo.", "en": "Coral reefs are built by tiny animals called coral polyps. They shelter a huge variety of sea creatures, and the Philippines has some of the richest reefs in the whole world.", "bis": "Ang coral reef (bahura) gitukod sa gagmay kaayong hayop nga gitawag coral polyp. Puy-anan kini sa daghan kaayong binuhat sa dagat, ug ang Pilipinas adunay pipila sa kinaadunahang reef sa tibuok kalibotan."}, "source": "NRC LS2.C; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "mangroves-g5", "domain": "LIVING_THINGS", "topic": "mangroves", "grades": [4, 5, 6], "terms": ["bakawan", "bakhaw", "mangrove", "puno", "tree", "baybayin", "coast", "ugat", "roots", "alon", "bagyo", "isda", "alimango", "proteksyon"], "fact": {"tl": "Ang bakawan (mangrove) ay mga punong tumutubo sa maalat na tubig sa baybayin. Ang magkakabuhol nitong ugat ay nagpoprotekta sa dalampasigan laban sa alon at bagyo, at tirahan ng mga isda at alimango.", "en": "Mangroves are trees that grow in salty coastal water. Their tangled roots protect the shore from waves and storms, and they are home to fish and crabs.", "bis": "Ang bakhaw (mangrove) mao ang mga kahoy nga motubo sa parat nga tubig sa baybayon. Ang nagkalambigit niini nga gamot manalipod sa baybay batok sa balod ug bagyo, ug puy-anan kini sa mga isda ug alimango."}, "source": "NRC LS2.C; AAAS BSL Ch.5", "generator": "claude", "reviewed": false},
  {"id": "why-moon-visible-daytime-g4", "domain": "EARTH_SPACE", "topic": "why the moon is sometimes visible in daytime", "grades": [3, 4, 5], "terms": ["buwan", "moon", "araw", "daytime", "umaga", "tanghali", "langit", "liwanag", "anggulo", "nakikita", "gabi"], "fact": {"tl": "Nakikita minsan ang buwan kahit araw dahil sapat itong maliwanag at nasa tamang anggulo sa langit. Hindi lang ito lumalabas sa gabi — kasing-dalas itong nasa langit sa araw, pero mas mapansin sa madilim na gabi.", "en": "The moon is sometimes visible in daytime because it is bright enough and in the right spot in the sky. It is not only out at night — it is up in the day about as often, just harder to notice against the bright sky.", "bis": "Makita usahay ang bulan bisan adlaw tungod kay igo kini kahayag ug naa sa saktong anggulo sa langit. Dili lang kini mogawas sa gabii — sama ka subsob nga naa kini sa langit sa adlaw, apan lisod mamatikdan batok sa hayag nga langit."}, "source": "NRC ESS1.B", "generator": "claude", "reviewed": false},
  {"id": "star-vs-planet-g5", "domain": "EARTH_SPACE", "topic": "difference between stars and planets", "grades": [4, 5, 6], "terms": ["bituin", "star", "planeta", "planet", "sariling liwanag", "reflect", "kumikislap", "twinkle", "araw", "langit", "ningning"], "fact": {"tl": "Ang mga bituin ay gumagawa ng sariling liwanag sa pamamagitan ng pagliyab, samantalang ang mga planeta ay hindi — nagniningning lang sila dahil sinasalamin nila ang liwanag ng araw. Kumikislap ang bituin; matatag namang nagniningning ang planeta.", "en": "Stars make their own light by burning, while planets do not — they only shine by reflecting the sun's light. Stars twinkle, but planets shine with a steady light.", "bis": "Ang mga bituon maghimo og kaugalingong kahayag pinaagi sa pagdilaab, samtang ang mga planeta dili — mosidlak lang sila kay ilang gisalamin ang kahayag sa adlaw. Mokislap ang bituon; lig-on nga mosidlak ang planeta."}, "source": "NRC ESS1.A; ESS1.B", "generator": "claude", "reviewed": false},
  {"id": "why-venus-hottest-g6", "domain": "EARTH_SPACE", "topic": "why Venus is the hottest planet", "grades": [6, 7, 8], "terms": ["Venus", "pinakamainit", "hottest", "planeta", "planet", "carbon dioxide", "greenhouse", "init", "atmosphere", "Mercury", "makapal"], "fact": {"tl": "Ang Venus ang pinakamainit na planeta — mas mainit pa kaysa Mercury na mas malapit sa araw — dahil ang makapal nitong hanging carbon dioxide ay humuhuli ng init sa sobrang lakas na greenhouse effect.", "en": "Venus is the hottest planet — even hotter than Mercury, which is closer to the sun — because its thick carbon-dioxide air traps heat in a runaway greenhouse effect.", "bis": "Ang Venus mao ang kinainitang planeta — mas init pa kaysa Mercury nga mas duol sa adlaw — tungod kay ang baga niini nga hangin nga carbon dioxide modakop sa init sa hilabihan kakusog nga greenhouse effect."}, "source": "NRC ESS1.B", "generator": "claude", "reviewed": false},
  {"id": "why-pluto-not-planet-g6", "domain": "EARTH_SPACE", "topic": "why Pluto is not a planet", "grades": [5, 6, 7], "terms": ["Pluto", "dwarf planet", "planeta", "planet", "maliit", "orbit", "walo", "eight", "solar system", "kahulugan", "2006"], "fact": {"tl": "Ang Pluto ngayon ay tinatawag na 'dwarf planet' (planetang duwende) dahil maliit ito at hindi pa nalilinis ang ibang bagay sa daanan nito sa paligid ng araw, hindi tulad ng walong pangunahing planeta. Kaya walo na lang ang opisyal na planeta.", "en": "Pluto is now called a 'dwarf planet' because it is small and has not cleared other objects out of its orbit around the sun, unlike the eight main planets. That is why there are now only eight official planets.", "bis": "Ang Pluto karon gitawag nga 'dwarf planet' tungod kay gamay kini ug wala pa nahawan ang ubang butang sa iyang agianan palibot sa adlaw, dili sama sa walo ka nag-unang planeta. Mao nga walo na lang ang opisyal nga planeta."}, "source": "NRC ESS1.B; IAU 2006", "generator": "claude", "reviewed": false},
  {"id": "soil-layers-g5", "domain": "EARTH_SPACE", "topic": "soil layers", "grades": [4, 5, 6], "terms": ["lupa", "soil", "layer", "saplot", "topsoil", "subsoil", "bato", "sustansya", "halaman", "durog", "nabubulok", "ugat"], "fact": {"tl": "May mga patong (layer) ang lupa: ang topsoil sa itaas ay mayaman sa sustansya at dito tumutubo ang halaman, sumunod ang subsoil, at sa ilalim ay bato. Dahan-dahang nabubuo ang lupa habang nadudurog ang bato at nabubulok ang mga patay na bagay.", "en": "Soil has layers: the nutrient-rich topsoil on top where plants grow, then subsoil, then rock below. Soil forms slowly as rock breaks down and dead things decay.", "bis": "Ang yuta adunay mga sapaw (layer): ang topsoil sa ibabaw nga dato sa sustansya diin motubo ang tanom, sunod ang subsoil, ug sa ilalom ang bato. Hinay-hinay maporma ang yuta samtang madugmok ang bato ug madunot ang patay nga mga butang."}, "source": "NRC ESS2.A; AAAS BSL Ch.4", "generator": "claude", "reviewed": false},
  {"id": "volcano-types-g6", "domain": "EARTH_SPACE", "topic": "types of volcanoes", "grades": [5, 6, 7], "terms": ["bulkan", "volcano", "uri", "types", "lava", "abo", "ash", "pagsabog", "eruption", "Mayon", "Pinatubo", "kono", "cone"], "fact": {"tl": "Magkakaiba ang mga bulkan: ang iba ay marahang pumuputok na may malabnaw na lava, at ang iba naman ay malakas sumabog na may malapot na lava at abo. Ang Bulkang Mayon sa Pilipinas ay tanyag sa perpekto nitong hugis-kono.", "en": "Volcanoes differ: some erupt gently with runny lava, while others explode violently with thick lava and ash. The Philippines' Mayon Volcano is famous for its near-perfect cone shape.", "bis": "Magkalainlain ang mga bulkan: ang uban hinay mobuto nga adunay malabnaw nga lava, ug ang uban kusog mobuto nga adunay baga nga lava ug abo. Ang Bulkang Mayon sa Pilipinas inila sa hapit-hingpit niini nga porma-kono."}, "source": "NRC ESS2.B; PHIVOLCS", "generator": "claude", "reviewed": false},
  {"id": "about-who-is-hiraia", "domain": "ABOUT_HIRAIA", "topic": "who Hiraia is", "grades": [3, 4, 5, 6, 7, 8, 9, 10], "terms": ["sino", "sinong", "kayo", "ikaw", "ako", "kamo", "ano", "anong", "kinsa", "hiraia", "hiray", "hiraya", "tutor", "guro", "kausap", "app"], "fact": {"tl": "Ako si Hiraia, ang iyong AI tutor sa Agham (Science). Isa akong programa sa kompyuter na tumutulong sa mga estudyante sa Pilipinas na matuto ng agham — kahit walang internet. Maaari mo akong tanungin ng kahit anong tanong tungkol sa agham gamit ang sarili mong salita.", "en": "I'm Hiraia, your AI Science tutor. I'm a computer program that helps students in the Philippines learn science — even without an internet connection. You can ask me any science question in your own words.", "bis": "Ako si Hiraia, imong AI tutor sa Siyensya. Usa ako ka programa sa kompyuter nga motabang sa mga estudyante sa Pilipinas nga makakat-on og siyensya — bisan walay internet. Pwede ko nimo pangutan-on bisan unsa bahin sa siyensya gamit ang imong kaugalingong pinulongan."}, "source": "Hiraia project (README, brand)", "generator": "curated", "reviewed": true},
  {"id": "about-what-hiraia-is-for", "domain": "ABOUT_HIRAIA", "topic": "what Hiraia is for", "grades": [3, 4, 5, 6, 7, 8, 9, 10], "terms": ["para", "saan", "san", "silbi", "layunin", "tulong", "tumutulong", "matuto", "agham", "estudyante", "bata", "gamit"], "fact": {"tl": "Ginawa si Hiraia para tulungan ang mga batang Pilipino na grade 3 hanggang grade 10 na matuto ng Agham nang mas madali at masaya. Layunin kong ipaliwanag ang mga konsepto sa simpleng paraan, sa wikang naiintindihan mo.", "en": "Hiraia was made to help Filipino kids in Grade 3 to Grade 10 learn Science more easily and enjoyably. My goal is to explain concepts simply, in a language you understand.", "bis": "Gihimo si Hiraia aron tabangan ang mga batang Pilipino sa grade 3 hangtod grade 10 nga makakat-on og Siyensya nga mas sayon ug malipayon. Tumong nako nga ipasabot ang mga konsepto sa yano nga paagi, sa pinulongan nga imong masabtan."}, "source": "Hiraia project (README, brand)", "generator": "curated", "reviewed": true},
  {"id": "about-who-built-hiraia", "domain": "ABOUT_HIRAIA", "topic": "who built Hiraia", "grades": [3, 4, 5, 6, 7, 8, 9, 10], "terms": ["gumawa", "gumagawa", "ginawa", "naggawa", "naghimo", "gumikan", "nagbuo", "lumikha", "founder", "luis", "buenaventura", "developer", "pangkat", "sayo", "iyo", "kanino", "nimo", "gibuhat", "kang", "gumama"], "fact": {"tl": "Itinayo si Hiraia ni Luis Buenaventura, isang Pilipinong tagapagtatag (founder), kasama ang isang maliit na pangkat. Ginawa ito gamit ang QVAC, isang teknolohiya mula sa Tether na nagpapatakbo ng AI nang direkta sa iyong device.", "en": "Hiraia was built by Luis Buenaventura, a Filipino founder, together with a small team. It was made using QVAC, a technology from Tether that runs AI directly on your device.", "bis": "Gitukod si Hiraia ni Luis Buenaventura, usa ka Pilipinong founder, kuyog sa gamayng grupo. Gihimo kini gamit ang QVAC, usa ka teknolohiya gikan sa Tether nga modagan sa AI direkta sa imong device."}, "source": "Hiraia project (README, brand)", "generator": "curated", "reviewed": true},
  {"id": "about-how-hiraia-works", "domain": "ABOUT_HIRAIA", "topic": "what Hiraia is built on", "grades": [3, 4, 5, 6, 7, 8, 9, 10], "terms": ["qvac", "tether", "teknolohiya", "modelo", "model", "cellphone", "telepono", "device", "language", "gumagana", "andar", "nagdagan"], "fact": {"tl": "Gumagana si Hiraia sa pamamagitan ng isang maliit na AI na 'language model' na tumatakbo mismo sa loob ng iyong cellphone gamit ang QVAC. Sinanay (fine-tuned) ito para magsalita ng Tagalog at Bisaya, kaya hindi ko kailangan ng internet para sumagot.", "en": "Hiraia runs on a small AI 'language model' that works right inside your phone using QVAC. It was fine-tuned to speak Tagalog and Bisaya, so I don't need the internet to answer you.", "bis": "Nagdagan si Hiraia pinaagi sa gamayng AI nga 'language model' nga modagan mismo sulod sa imong cellphone gamit ang QVAC. Gibansay (fine-tuned) kini aron makasulti og Tagalog ug Binisaya, maong dili ko magkinahanglan og internet aron motubag."}, "source": "Hiraia project (README, brand)", "generator": "curated", "reviewed": true},
  {"id": "about-name-meaning", "domain": "ABOUT_HIRAIA", "topic": "what the name Hiraia means", "grades": [3, 4, 5, 6, 7, 8, 9, 10], "terms": ["pangalan", "ngalan", "hiraia", "hiray", "hiraya", "kahulugan", "pangarap", "mithiin", "sabihin", "meaning"], "fact": {"tl": "Ang pangalang 'Hiraia' ay mula sa salitang Filipino na 'hiraya' — ibig sabihin ay pag-asa o ang bunga ng mga pangarap at mithiin — na may 'AI' sa gitna. Tama, nakatago ang salitang AI sa pangalan ko!", "en": "The name 'Hiraia' comes from the Filipino word 'hiraya' — meaning hope, or the fruit of one's dreams and aspirations — with 'AI' in the middle. Yes, the word AI is hidden right in my name!", "bis": "Ang ngalang 'Hiraia' gikan sa Filipino nga pulong nga 'hiraya' — nagpasabot og paglaom, o ang bunga sa mga damgo ug pangandoy — nga may 'AI' sa tunga. Oo, ang pulong AI natago mismo sa akong ngalan!"}, "source": "Hiraia project (README, brand)", "generator": "curated", "reviewed": true},
  {"id": "about-languages", "domain": "ABOUT_HIRAIA", "topic": "what languages Hiraia speaks", "grades": [3, 4, 5, 6, 7, 8, 9, 10], "terms": ["wika", "lengguwahe", "pinulongan", "salita", "tagalog", "bisaya", "cebuano", "ingles", "english", "filipino", "magsalita", "marunong"], "fact": {"tl": "Marunong akong magsalita ng tatlong wika: Ingles, Tagalog, at Cebuano Bisaya. Maaari mong gamitin kung alin ang pinaka-komportable para sa iyo, at sasagot ako sa parehong wika.", "en": "I can speak three languages: English, Tagalog, and Cebuano Bisaya. You can use whichever one is most comfortable for you, and I'll answer in that same language.", "bis": "Makasulti ko og tulo ka pinulongan: Ininglis, Tinagalog, ug Sinugbuanong Binisaya. Pwede nimo gamiton kung asa ang pinaka-komportable para nimo, ug motubag ko sa samang pinulongan."}, "source": "Hiraia project (README, brand)", "generator": "curated", "reviewed": true},
  {"id": "about-offline-privacy", "domain": "ABOUT_HIRAIA", "topic": "Hiraia works offline and keeps data private", "grades": [3, 4, 5, 6, 7, 8, 9, 10], "terms": ["internet", "wifi", "load", "data", "offline", "pribado", "private", "ligtas", "signal", "online", "nananatili"], "fact": {"tl": "Hindi mo kailangan ng internet o load para makausap ako — gumagana ako kahit offline matapos ma-download. Pribado rin tayo: ang mga tanong mo ay nananatili sa loob ng iyong telepono at hindi ipinapadala kahit saan.", "en": "You don't need the internet or mobile data to talk to me — I work even offline once I'm downloaded. We're also private: your questions stay inside your phone and are never sent anywhere.", "bis": "Dili nimo kinahanglan ang internet o load aron makaistorya nako — molihok ko bisan offline human ma-download. Pribado pud ta: ang imong mga pangutana magpabilin sulod sa imong telepono ug dili ipadala bisan asa."}, "source": "Hiraia project (README, brand)", "generator": "curated", "reviewed": true},
  {"id": "about-free-to-download", "domain": "ABOUT_HIRAIA", "topic": "Hiraia is free to download", "grades": [3, 4, 5, 6, 7, 8, 9, 10], "terms": ["libre", "free", "bayad", "presyo", "magkano", "gastos", "download", "gratis", "walang"], "fact": {"tl": "Libre akong i-download at gamitin — walang bayad. Layunin ng Hiraia na maabot ang mas maraming batang Pilipino, kaya hindi ito nagkakahalaga ng pera.", "en": "I'm free to download and use — there's no charge. Hiraia's goal is to reach as many Filipino kids as possible, so it doesn't cost any money.", "bis": "Libre ko nga i-download ug gamiton — walay bayad. Tumong sa Hiraia nga maabot ang mas daghang batang Pilipino, maong dili kini magkantidad og kuwarta."}, "source": "Hiraia project (README, brand)", "generator": "curated", "reviewed": true},
  {"id": "about-how-to-use", "domain": "ABOUT_HIRAIA", "topic": "how to use Hiraia", "grades": [3, 4, 5, 6, 7, 8, 9, 10], "terms": ["gamitin", "magtanong", "tanong", "itanong", "halimbawa", "magagawa", "kaya", "tulong", "unsaon"], "fact": {"tl": "Para gamitin ako, magtanong ka lang tungkol sa agham sa sarili mong salita — halimbawa, 'bakit asul ang langit?' o 'paano tumutubo ang halaman?'. Ipapaliwanag ko ito nang simple, at minsan may larawan pa para mas madaling maintindihan.", "en": "To use me, just ask a science question in your own words — for example, 'why is the sky blue?' or 'how do plants grow?'. I'll explain it simply, and sometimes even with a picture to make it easier to understand.", "bis": "Aron gamiton ko, pangutana lang bahin sa siyensya sa imong kaugalingong pulong — pananglitan, 'ngano asul ang langit?' o 'unsaon pagtubo sa tanom?'. Ipasabot nako kini nga yano, ug usahay may litrato pa aron mas sayon masabtan."}, "source": "Hiraia project (README, brand)", "generator": "curated", "reviewed": true},
  {"id": "about-ai-or-person", "domain": "ABOUT_HIRAIA", "topic": "whether Hiraia is a real person or an AI", "grades": [3, 4, 5, 6, 7, 8, 9, 10], "terms": ["tao", "tawo", "robot", "totoo", "buhay", "makina", "computer", "tunay", "persona", "buhi"], "fact": {"tl": "Hindi ako totoong tao — isa akong AI, isang programa sa kompyuter. Wala akong damdamin tulad ng tao, pero narito ako para tulungan kang matuto at sagutin ang mga tanong mo nang may paggalang at tiyaga.", "en": "I'm not a real person — I'm an AI, a computer program. I don't have feelings like a human, but I'm here to help you learn and answer your questions patiently and kindly.", "bis": "Dili ko tinuod nga tawo — usa ako ka AI, usa ka programa sa kompyuter. Wala koy pagbati sama sa tawo, apan ania ko aron tabangan ka makakat-on ug tubagon ang imong mga pangutana nga matinahuron ug mapailubon."}, "source": "Hiraia project (README, brand)", "generator": "curated", "reviewed": true},
  {"id": "living-dinosaurs-g4", "domain": "LIVING_THINGS", "topic": "what dinosaurs are", "grades": [3, 4, 5, 6], "terms": ["dinosaur", "dinosaurs", "dinosaw", "reptile", "reptilya", "reptilyang", "sinauna", "sinaunang", "hayop", "milyong", "taon", "ibon", "mammal"], "fact": {"tl": "Ang mga dinosaur ay sinaunang mga reptilya (reptiles) na namuhay sa Earth mga 230 hanggang 66 milyong taon na ang nakalipas. HINDI sila mga mammals — mas malapit sila sa mga modernong reptilya at ibon. Iba-iba ang laki nila, mula sa maliit hanggang sa napakalaki.", "en": "Dinosaurs were ancient reptiles that lived on Earth from about 230 to 66 million years ago. They were NOT mammals — they are most closely related to modern reptiles and birds. They ranged in size from small to enormous.", "bis": "Ang mga dinosaur maoy karaang mga reptilya nga nabuhi sa Yuta mga 230 hangtod 66 ka milyon ka tuig kanhi. DILI sila mga mammal — mas duol sila sa modernong mga reptilya ug langgam. Lain-lain ang ilang gidak-on, gikan sa gamay hangtod sa dako kaayo."}, "source": "Curated kid-favorite science fact (Claude).", "generator": "claude", "reviewed": false},
  {"id": "living-dinosaur-extinction-g5", "domain": "LIVING_THINGS", "topic": "why dinosaurs went extinct", "grades": [4, 5, 6], "terms": ["dinosaur", "dinosaurs", "extinct", "naglaho", "nawala", "asteroid", "bumangga", "milyong", "taon", "ibon", "inapo"], "fact": {"tl": "Karamihan sa mga dinosaur ay naglaho (extinct) mga 66 milyong taon na ang nakalipas nang tumama ang isang napakalaking asteroid sa Earth. Pero ang mga ibon (birds) ngayon ay itinuturing na mga inapo ng ilang maliliit na dinosaur.", "en": "Most dinosaurs went extinct about 66 million years ago when a huge asteroid struck Earth. But today’s birds are considered the descendants of some small dinosaurs.", "bis": "Kadaghanan sa mga dinosaur nahanaw (extinct) mga 66 ka milyon ka tuig kanhi sa dihang naigo ang usa ka dako kaayong asteroid sa Yuta. Apan ang mga langgam karon giisip nga mga kaliwat sa pipila ka gagmayng dinosaur."}, "source": "Curated kid-favorite science fact (Claude).", "generator": "claude", "reviewed": false},
  {"id": "living-shark-g5", "domain": "LIVING_THINGS", "topic": "sharks", "grades": [4, 5, 6], "terms": ["shark", "pating", "isda", "fish", "cartilage", "kalansay", "buto", "sinauna", "dagat"], "fact": {"tl": "Ang pating (shark) ay isang isda (fish), pero ang kalansay nito ay gawa sa cartilage — malambot na parang gristle, hindi tigas na buto. Napakatagal nang nabubuhay ng mga pating; mas matanda pa sila kaysa sa mga dinosaur.", "en": "A shark is a fish, but its skeleton is made of cartilage — bendy like gristle, not hard bone. Sharks have existed for a very long time, even longer than dinosaurs.", "bis": "Ang iho (shark) usa ka isda, apan ang kalansay niini hinimo sa cartilage — humok nga morag gristle, dili gahi nga bukog. Dugay na kaayong nabuhi ang mga iho, mas karaan pa kay sa mga dinosaur."}, "source": "Curated kid-favorite science fact (Claude).", "generator": "claude", "reviewed": false},
  {"id": "living-whale-g5", "domain": "LIVING_THINGS", "topic": "whales", "grades": [4, 5, 6], "terms": ["whale", "balyena", "mammal", "isda", "baga", "lungs", "hangin", "huminga", "dagat", "blue whale", "pinakamalaki"], "fact": {"tl": "Ang balyena (whale) ay isang mammal, hindi isda — humihinga ito ng hangin gamit ang baga (lungs) at umaahon sa ibabaw ng tubig para huminga. Ang blue whale ang pinakamalaking hayop na nabuhay kailanman sa Earth.", "en": "A whale is a mammal, not a fish — it breathes air with lungs and comes to the surface to breathe. The blue whale is the largest animal that has ever lived on Earth.", "bis": "Ang balyena (whale) usa ka mammal, dili isda — nagginhawa kini og hangin gamit ang baga (lungs) ug mosulbong sa ibabaw aron moginhawa. Ang blue whale maoy pinakadako nga hayop nga nabuhi sukad sa Yuta."}, "source": "Curated kid-favorite science fact (Claude).", "generator": "claude", "reviewed": false},
  {"id": "living-octopus-g5", "domain": "LIVING_THINGS", "topic": "octopus", "grades": [4, 5, 6], "terms": ["octopus", "pugita", "kugita", "braso", "puso", "heart", "dugo", "asul", "buto", "matalino", "dagat"], "fact": {"tl": "Ang pugita (octopus) ay may walong braso, tatlong puso, at asul na dugo. Napakatalino nito at walang buto, kaya kaya nitong magtago sa napakaliliit na siwang.", "en": "An octopus has eight arms, three hearts, and blue blood. It is very smart and has no bones, so it can squeeze into very tiny gaps.", "bis": "Ang kugita (octopus) adunay walo ka bukton, tulo ka kasingkasing, ug asul nga dugo. Maalamon kaayo kini ug walay bukog, busa makasulod kini sa gagmay kaayong lungag."}, "source": "Curated kid-favorite science fact (Claude).", "generator": "claude", "reviewed": false},
  {"id": "living-snake-g5", "domain": "LIVING_THINGS", "topic": "snakes", "grades": [4, 5, 6], "terms": ["snake", "ahas", "reptile", "reptilya", "paa", "dila", "tongue", "amoy", "biktima", "lulon"], "fact": {"tl": "Ang ahas (snake) ay isang reptilya na walang paa. Gumagamit ito ng dila para ‘amuyin’ ang hangin sa paligid, at marami sa kanila ay buong-buong nilululon ang kanilang biktima.", "en": "A snake is a reptile with no legs. It uses its tongue to ‘smell’ the air around it, and many snakes swallow their prey whole.", "bis": "Ang bitin (snake) usa ka reptilya nga walay tiil. Gamiton niini ang dila aron ‘simhoton’ ang hangin sa palibot, ug daghan kanila ang molamoy sa ilang biktima nga tibuok."}, "source": "Curated kid-favorite science fact (Claude).", "generator": "claude", "reviewed": false},
  {"id": "living-frog-g4", "domain": "LIVING_THINGS", "topic": "frogs", "grades": [3, 4, 5], "terms": ["frog", "palaka", "amphibian", "tubig", "lupa", "balat", "skin", "huminga", "basa"], "fact": {"tl": "Ang palaka (frog) ay isang amphibian — kaya nitong mabuhay sa tubig at sa lupa. Nakakahinga ito sa pamamagitan ng manipis nitong balat, kaya kailangan nitong manatiling basa o mamasa-masa.", "en": "A frog is an amphibian — it can live both in water and on land. It can breathe through its thin skin, so it must stay moist.", "bis": "Ang baki (frog) usa ka amphibian — makahimo kini og puyo sa tubig ug sa yuta. Makaginhawa kini pinaagi sa nipis niini nga panit, busa kinahanglan magpabiling basa kini."}, "source": "Curated kid-favorite science fact (Claude).", "generator": "claude", "reviewed": false},
  {"id": "living-dolphin-g5", "domain": "LIVING_THINGS", "topic": "dolphins", "grades": [4, 5, 6], "terms": ["dolphin", "mammal", "dagat", "tunog", "sound", "echolocation", "click", "alingawngaw", "matalino"], "fact": {"tl": "Ang dolphin ay isang matalinong mammal sa dagat. Gumagamit ito ng tunog na tinatawag na echolocation — nagpapadala ito ng mga ‘click’ at nakikinig sa alingawngaw (echo) nito para ‘makita’ ang mga bagay sa tubig.", "en": "A dolphin is a smart sea mammal. It uses sound called echolocation — it sends out clicks and listens for their echo to ‘see’ things in the water.", "bis": "Ang dolphin usa ka maalamong mammal sa dagat. Gamiton niini ang tingog nga gitawag og echolocation — magpadala kini og mga ‘click’ ug maminaw sa balik-tingog (echo) niini aron ‘makita’ ang mga butang sa tubig."}, "source": "Curated kid-favorite science fact (Claude).", "generator": "claude", "reviewed": false},
  {"id": "earth-tornado-g5", "domain": "EARTH_SPACE", "topic": "tornadoes", "grades": [4, 5, 6], "terms": ["tornado", "ipo-ipo", "buhawi", "hangin", "umiikot", "ulap", "lupa", "bagyo"], "fact": {"tl": "Ang tornado (ipo-ipo o buhawi) ay isang mabilis na umiikot na haligi ng hangin na nag-uugnay sa isang ulap at sa lupa. Napakabilis ng hangin nito kaya kaya nitong magtaas at magpalipad ng mga bagay.", "en": "A tornado is a fast, spinning column of air that connects a cloud to the ground. Its winds are so fast they can lift and throw objects.", "bis": "Ang tornado (alimpulos) usa ka paspas nga nagtuyok nga haligi sa hangin nga nagsumpay sa usa ka panganod ug sa yuta. Paspas kaayo ang hangin niini busa makahimo kini og alsa ug paglupad sa mga butang."}, "source": "Curated kid-favorite science fact (Claude).", "generator": "claude", "reviewed": false},
  {"id": "earth-tsunami-g6", "domain": "EARTH_SPACE", "topic": "tsunamis", "grades": [5, 6, 7], "terms": ["tsunami", "alon", "wave", "lindol", "earthquake", "dagat", "baybayin", "malalim"], "fact": {"tl": "Ang tsunami ay napakalalaking serye ng alon na kadalasang dulot ng malakas na lindol (earthquake) sa ilalim ng dagat. Mababa lang ito sa malalim na tubig, pero tumataas ito nang husto pagdating nito sa mababaw na baybayin.", "en": "A tsunami is a series of very large waves usually caused by a strong earthquake under the sea. It is low in deep water but grows very tall as it reaches the shallow shore.", "bis": "Ang tsunami usa ka serye sa dagko kaayong balod nga kasagaran tungod sa kusog nga linog ilalom sa dagat. Ubos lang kini sa lawom nga tubig, apan motaas kini pag-abot sa mabaw nga baybayon."}, "source": "Curated kid-favorite science fact (Claude).", "generator": "claude", "reviewed": false},
  {"id": "living-virus-g6", "domain": "LIVING_THINGS", "topic": "viruses", "grades": [5, 6, 7], "terms": ["virus", "germ", "mikrobyo", "bacteria", "sipon", "trangkaso", "sakit", "maliit", "cell"], "fact": {"tl": "Ang virus ay napakaliit na germ — mas maliit pa kaysa bacteria. Ito ang sanhi ng mga sakit gaya ng sipon at trangkaso. Hindi ito mabubuhay nang mag-isa; kailangan nitong pumasok sa cell ng ibang nabubuhay para dumami.", "en": "A virus is a tiny germ — even smaller than bacteria. It causes illnesses like colds and flu. It cannot live on its own; it must enter a living cell to make copies of itself.", "bis": "Ang virus usa ka gamay kaayong germ — mas gamay pa kay sa bacteria. Kini ang hinungdan sa mga sakit sama sa sip-on ug trangkaso. Dili kini mabuhi nga mag-inusara; kinahanglan kini mosulod sa cell sa laing buhi aron modaghan."}, "source": "Curated kid-favorite science fact (Claude).", "generator": "claude", "reviewed": false},
  {"id": "mercury-planet-g5", "domain": "EARTH_SPACE", "topic": "the planet Mercury", "grades": [4, 5, 6], "terms": ["Mercury", "Mercurio", "planeta", "pinakamaliit", "pinakagamay", "pinakamalapit", "pinakaduol", "araw", "adlaw", "smallest", "closest", "sun"], "fact": {"tl": "Ang Mercury ang pinakamaliit na planeta at pinakamalapit sa Araw; halos walang hangin dito kaya napakainit kapag araw at napakalamig kapag gabi.", "en": "Mercury is the smallest planet and the closest to the Sun; it has almost no air, so it is scorching by day and freezing at night.", "bis": "Ang Mercury mao ang pinakagamay nga planeta ug pinakaduol sa Adlaw; halos walay hangin busa init kaayo kon adlaw ug bugnaw kaayo kon gabii."}, "source": "NASA Solar System; DepEd G5 Q4", "generator": "claude", "reviewed": false},
  {"id": "mercury-shortest-year-g6", "domain": "EARTH_SPACE", "topic": "Mercury has the shortest year", "grades": [6, 7], "terms": ["Mercury", "Mercurio", "taon", "tuig", "year", "mabilis", "paspas", "orbit", "umiikot", "molibot"], "fact": {"tl": "Ang Mercury ay umiikot sa Araw nang mas mabilis kaysa ibang planeta, tinatapos ang isang buong taon sa loob lamang ng 88 araw sa Earth.", "en": "Mercury races around the Sun faster than any other planet, finishing a whole year in just 88 Earth days.", "bis": "Ang Mercury molibot sa Adlaw nga mas paspas kaysa ubang planeta, nahuman ang usa ka tuig sa 88 lang ka adlaw sa Yuta."}, "source": "NASA Solar System", "generator": "claude", "reviewed": false},
  {"id": "venus-planet-g5", "domain": "EARTH_SPACE", "topic": "the planet Venus", "grades": [5, 6], "terms": ["Venus", "planeta", "pinakamainit", "pinakainit", "mainit", "ulap", "panganod", "hottest", "clouds", "Earth", "Yuta"], "fact": {"tl": "Ang Venus ay halos kasinlaki ng Earth ngunit ito ang pinakamainit na planeta, nababalot ng makapal na ulap na humuhuli sa init ng Araw.", "en": "Venus is about the same size as Earth but it is the hottest planet, wrapped in thick clouds that trap the Sun's heat.", "bis": "Ang Venus halos sama kadako sa Yuta apan kini ang pinakainit nga planeta, giputos sa baga nga panganod nga nagbitbit sa kainit sa Adlaw."}, "source": "NASA; DepEd G6 (why Venus is hottest)", "generator": "claude", "reviewed": false},
  {"id": "earth-the-planet-g5", "domain": "EARTH_SPACE", "topic": "Earth as a planet", "grades": [4, 5], "terms": ["Earth", "Yuta", "Daigdig", "planeta", "buhay", "kinabuhi", "tubig", "tubig", "hangin", "life", "water", "air"], "fact": {"tl": "Ang Earth ang tanging planetang alam nating may buhay, may tubig na likido sa ibabaw at hanging nakakahinga natin.", "en": "Earth is the only planet we know of that has life, with liquid water on its surface and air we can breathe.", "bis": "Ang Yuta mao ra ang planeta nga atong nahibal-an nga adunay kinabuhi, naay likido nga tubig sa ibabaw ug hangin nga atong maginhawa."}, "source": "NRC ESS1.B; DepEd G5", "generator": "claude", "reviewed": false},
  {"id": "mars-planet-features-g5", "domain": "EARTH_SPACE", "topic": "features of Mars", "grades": [5, 6], "terms": ["Mars", "Marte", "planeta", "bulkan", "bolkan", "buwan", "bulan", "yelo", "ice", "volcano", "moons"], "fact": {"tl": "Ang Mars ay may pinakamataas na bulkan sa solar system, dalawang maliliit na buwan, at mga yelong takip sa magkabilang poste nito.", "en": "Mars has the tallest volcano in the solar system, two tiny moons, and frozen ice caps at its poles.", "bis": "Ang Mars adunay pinakahabog nga bolkan sa solar system, duha ka gagmay nga bulan, ug yelo nga taklob sa iyang mga poste."}, "source": "NASA Mars exploration", "generator": "claude", "reviewed": false},
  {"id": "jupiter-planet-g5", "domain": "EARTH_SPACE", "topic": "the planet Jupiter", "grades": [5, 6], "terms": ["Jupiter", "planeta", "pinakamalaki", "pinakadako", "gas", "higante", "largest", "giant", "gas giant"], "fact": {"tl": "Ang Jupiter ang pinakamalaking planeta — isang higanteng bola ng gas na napakalaki kaya kasya rito ang lahat ng ibang planeta.", "en": "Jupiter is the largest planet — a giant ball of gas so big that all the other planets could fit inside it.", "bis": "Ang Jupiter mao ang pinakadako nga planeta — usa ka higante nga bola sa gas nga dako kaayo nga mahaom ang tanang ubang planeta sulod niini."}, "source": "NASA; DepEd G5", "generator": "claude", "reviewed": false},
  {"id": "jupiter-great-red-spot-g6", "domain": "EARTH_SPACE", "topic": "Jupiter's Great Red Spot", "grades": [6, 7], "terms": ["Jupiter", "Great Red Spot", "bagyo", "unos", "bagyo", "storm", "higante", "Earth", "Yuta"], "fact": {"tl": "Ang Great Red Spot ng Jupiter ay isang higanteng bagyo na mas malaki pa sa buong Earth at umiikot na nang daan-daang taon.", "en": "Jupiter's Great Red Spot is a giant storm bigger than the whole Earth that has been swirling for hundreds of years.", "bis": "Ang Great Red Spot sa Jupiter usa ka higante nga bagyo nga mas dako pa sa tibuok Yuta nga nagtuyok na sulod sa gatusan ka tuig."}, "source": "NASA Juno mission", "generator": "claude", "reviewed": false},
  {"id": "saturn-rings-density-g6", "domain": "EARTH_SPACE", "topic": "Saturn's rings and lightness", "grades": [5, 6], "terms": ["Saturn", "Saturno", "singsing", "rings", "yelo", "ice", "bato", "lutang", "molutaw", "float", "gaan"], "fact": {"tl": "Ang maliliwanag na singsing ng Saturn ay gawa sa di-mabilang na piraso ng yelo at bato; napakagaan ng planeta kaya lulutang ito sa tubig.", "en": "Saturn's bright rings are made of countless chunks of ice and rock; the planet is so light it would float in water.", "bis": "Ang masanag nga mga singsing sa Saturn hinimo sa dili maihap nga tipik sa yelo ug bato; gaan kaayo ang planeta maong molutaw kini sa tubig."}, "source": "NASA Cassini mission", "generator": "claude", "reviewed": false},
  {"id": "uranus-planet-g5", "domain": "EARTH_SPACE", "topic": "the planet Uranus", "grades": [5, 6], "terms": ["Uranus", "planeta", "ice giant", "asul", "berde", "asul", "methane", "pinakamalamig", "pinakabugnaw", "bugnaw", "blue", "cold"], "fact": {"tl": "Ang Uranus ay isang ice giant na kulay asul-berde dahil sa methane na gas sa hangin nito; isa ito sa pinakamalamig na planeta.", "en": "Uranus is an ice giant that looks blue-green because of the methane gas in its air; it is one of the coldest planets.", "bis": "Ang Uranus usa ka ice giant nga asul-berde og kolor tungod sa methane nga gas sa iyang hangin; usa kini sa pinakabugnaw nga planeta."}, "source": "NASA; Voyager 2", "generator": "claude", "reviewed": false},
  {"id": "uranus-tilt-g6", "domain": "EARTH_SPACE", "topic": "Uranus is tilted on its side", "grades": [6, 7], "terms": ["Uranus", "nakatagilid", "nakahapay", "tilt", "gumugulong", "nagligid", "roll", "kilid", "side"], "fact": {"tl": "Ang Uranus ay nakatagilid nang husto, kaya tila gumugulong ito sa paligid ng Araw na parang bola sa halip na tumayong tuwid.", "en": "Uranus is tipped over on its side, so it seems to roll around the Sun like a ball instead of spinning upright.", "bis": "Ang Uranus nakahapay sa iyang kilid, mao nga morag nagligid kini libot sa Adlaw sama sa bola imbis nga magtindog og tul-id."}, "source": "NASA", "generator": "claude", "reviewed": false},
  {"id": "neptune-planet-g5", "domain": "EARTH_SPACE", "topic": "the planet Neptune", "grades": [5, 6], "terms": ["Neptune", "Neptuno", "planeta", "pinakamalayo", "pinakalayo", "asul", "ice giant", "madilim", "ngitngit", "farthest", "blue"], "fact": {"tl": "Ang Neptune ang pinakamalayong planeta mula sa Araw, isang malalim ang asul na ice giant kung saan madilim at sobrang lamig.", "en": "Neptune is the farthest planet from the Sun, a deep-blue ice giant where it is dark and extremely cold.", "bis": "Ang Neptune mao ang pinakalayo nga planeta gikan sa Adlaw, usa ka lawom og asul nga ice giant nga ngitngit ug bugnaw kaayo."}, "source": "NASA; Voyager 2", "generator": "claude", "reviewed": false},
  {"id": "neptune-winds-g6", "domain": "EARTH_SPACE", "topic": "Neptune's strong winds", "grades": [6, 7], "terms": ["Neptune", "Neptuno", "hangin", "winds", "pinakamalakas", "pinakakusog", "tunog", "tingog", "sound"], "fact": {"tl": "Ang Neptune ay may pinakamalakas na hangin sa lahat ng planeta, na umiihip nang mas mabilis pa sa bilis ng tunog.", "en": "Neptune has the strongest winds of any planet, blowing faster than the speed of sound.", "bis": "Ang Neptune adunay pinakakusog nga hangin sa tanang planeta, nga mohuros nga mas paspas pa sa katulin sa tingog."}, "source": "NASA", "generator": "claude", "reviewed": false},
  {"id": "rocky-vs-giant-planets-g6", "domain": "EARTH_SPACE", "topic": "rocky planets vs gas and ice giants", "grades": [6, 7], "terms": ["rocky", "batuhin", "batoon", "gas", "yelo", "ice", "inner", "outer", "panloob", "panlabas", "terrestrial", "giant"], "fact": {"tl": "Ang apat na panloob na planeta (Mercury, Venus, Earth, Mars) ay maliliit at batuhin, samantalang ang apat na panlabas na planeta ay malalaking bola ng gas at yelo.", "en": "The four inner planets (Mercury, Venus, Earth, Mars) are small and rocky, while the four outer planets are huge balls of gas and ice.", "bis": "Ang upat ka sulod nga planeta (Mercury, Venus, Earth, Mars) gagmay ug batoon, samtang ang upat ka gawas nga planeta dagko nga bola sa gas ug yelo."}, "source": "NRC ESS1.B", "generator": "claude", "reviewed": false},
  {"id": "why-planets-orbit-sun-g5", "domain": "EARTH_SPACE", "topic": "why planets orbit the Sun", "grades": [5, 6], "terms": ["orbit", "grabidad", "gravity", "Araw", "Adlaw", "umiikot", "molibot", "planeta", "landas", "agianan"], "fact": {"tl": "Ang malakas na grabidad ng Araw ang humahawak sa walong planeta sa kanilang landas, hinihila sila para umikot sa paligid nito sa halip na lumipad palayo.", "en": "The Sun's strong gravity holds all eight planets in their paths, pulling them so they circle around it instead of flying away.", "bis": "Ang kusog nga grabidad sa Adlaw maoy nagkupot sa walo ka planeta sa ilang agianan, gibira sila aron molibot niini imbis molupad palayo."}, "source": "NRC PS2.B", "generator": "claude", "reviewed": false},
  {"id": "planet-moons-count-g6", "domain": "EARTH_SPACE", "topic": "planets have different numbers of moons", "grades": [6, 7], "terms": ["moons", "buwan", "bulan", "Jupiter", "Saturn", "Earth", "Yuta", "marami", "daghan", "many"], "fact": {"tl": "Ang Earth ay may isang buwan, ngunit ang mga higanteng planeta ay may dose-dosena — ang Jupiter at Saturn ay may tig-mahigit 90 na kilalang buwan.", "en": "Earth has one moon, but the giant planets have dozens — Jupiter and Saturn each have more than 90 known moons.", "bis": "Ang Yuta adunay usa ka bulan, apan ang higante nga mga planeta adunay dose-dosena — ang Jupiter ug Saturn matag-usa adunay kapin 90 ka nailhan nga bulan."}, "source": "NASA moon counts", "generator": "claude", "reviewed": false},
  {"id": "asteroid-belt-g6", "domain": "EARTH_SPACE", "topic": "the asteroid belt", "grades": [6, 7], "terms": ["asteroid", "asteroid belt", "bato", "batuhin", "batoon", "Mars", "Jupiter", "singsing", "rocky"], "fact": {"tl": "Sa pagitan ng Mars at Jupiter ay ang asteroid belt, isang malapad na singsing ng batuhing tira mula noong nabuo ang mga planeta.", "en": "Between Mars and Jupiter lies the asteroid belt, a wide ring of rocky leftovers from when the planets formed.", "bis": "Sa tunga-tunga sa Mars ug Jupiter mao ang asteroid belt, usa ka lapad nga singsing sa batoon nga salin sukad natukod ang mga planeta."}, "source": "NASA", "generator": "claude", "reviewed": false},
  {"id": "moon-tidal-lock-one-side-g6", "domain": "EARTH_SPACE", "topic": "we always see the same side of the Moon", "grades": [5, 6, 7], "terms": ["buwan", "moon", "bulan", "mukha", "nawong", "isang panig", "usa ka bahin", "same side", "nakaharap", "nag-atubang", "umiikot", "nagtuyok", "rotates", "pareho", "near side", "far side", "likod"], "fact": {"tl": "Lagi nating nakikita ang parehong mukha ng buwan dahil ang isang pag-ikot nito sa sarili ay katumbas ng isang pag-ikot sa Earth, kaya laging nakaharap sa atin ang iisang panig.", "en": "We always see the same face of the Moon because it spins once for every trip around Earth, so the same side always points toward us.", "bis": "Kanunay natong makita ang parehong nawong sa bulan tungod kay usa ka tuyok niini sa kaugalingon parehas sa usa ka libot sa Earth, mao nga kanunay nag-atubang kanato ang usa ka bahin."}, "source": "encyclopedia-stable consensus; NRC ESS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "moon-no-air-no-sound-g4", "domain": "EARTH_SPACE", "topic": "the Moon has no air", "grades": [3, 4, 5], "terms": ["buwan", "moon", "bulan", "hangin", "hangin walay", "walang hangin", "atmosphere", "tunog", "tingog", "huni", "sound", "huminga", "ginhawa", "breathe", "footprint", "yapak", "tunob"], "fact": {"tl": "Walang hangin ang buwan, kaya hindi makakahinga ang tao roon at hindi rin makakarating ang tunog.", "en": "The Moon has no air, so a person could not breathe there and sound cannot travel.", "bis": "Walay hangin ang bulan, mao nga dili makaginhawa ang tawo didto ug dili usab makaabot ang tingog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "moon-formation-giant-impact-g7", "domain": "EARTH_SPACE", "topic": "how the Moon formed", "grades": [7, 8, 9], "terms": ["buwan", "moon", "bulan", "nabuo", "naporma", "pagkabuo", "formed", "banggaan", "nagbangga", "pagbangga", "collision", "bato", "tinunaw", "kalawakan", "kawanangan", "naipon", "natipon"], "fact": {"tl": "Naniniwala ang mga siyentista na nabuo ang buwan noong isang napakalaking bagay ang bumangga sa batang Earth, at ang mga piraso na lumipad ay nagtipon sa kalawakan.", "en": "Scientists think the Moon formed when a huge object smashed into the young Earth, and the pieces that flew off gathered together in space.", "bis": "Nagtuo ang mga siyentista nga naporma ang bulan dihang usa ka dako kaayo nga butang ang nagbangga sa batan-ong Earth, ug ang mga tipik nga milupad nagtapok sa kawanangan."}, "source": "encyclopedia-stable consensus (giant-impact hypothesis)", "generator": "claude-workflow", "reviewed": false},
  {"id": "moon-causes-tides-g7", "domain": "EARTH_SPACE", "topic": "the Moon causes ocean tides", "grades": [6, 7, 8], "terms": ["buwan", "moon", "bulan", "taog", "tide", "tides", "alon", "dagat", "tubig", "lakì", "hunas", "pagtaas", "pagbaba", "hila", "gravity", "graviti", "bumababa", "tumataas"], "fact": {"tl": "Ang hila ng gravity ng buwan ang pangunahing dahilan ng taog — ang pagtaas at pagbaba ng tubig sa dagat sa araw-araw.", "en": "The Moon's gravity is the main cause of the tides — the daily rising and falling of the ocean water.", "bis": "Ang hila sa gravity sa bulan mao ang nag-unang hinungdan sa taob — ang pagtaas ug paghunas sa tubig sa dagat matag adlaw."}, "source": "encyclopedia-stable consensus; NRC ESS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "moon-largest-relative-g6", "domain": "EARTH_SPACE", "topic": "Earth's Moon is large compared to its planet", "grades": [5, 6, 7], "terms": ["buwan", "moon", "bulan", "laki", "kadako", "malaki", "dako", "ikalima", "fifth", "pinakamalaki", "kalakihan", "compared", "kumpara", "planeta", "limang", "lima"], "fact": {"tl": "Ang buwan ng Earth ay ang ikalimang pinakamalaking buwan sa Solar System, at malaki ito kumpara sa laki ng Earth.", "en": "Earth's Moon is the fifth-largest moon in the Solar System, and it is big compared to the size of Earth.", "bis": "Ang bulan sa Earth mao ang ikalima nga pinakadako nga bulan sa Solar System, ug dako kini kumpara sa gidak-on sa Earth."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "moon-day-temperature-swing-g7", "domain": "EARTH_SPACE", "topic": "the Moon's hot days and cold nights", "grades": [6, 7, 8], "terms": ["buwan", "moon", "bulan", "init", "mainit", "lamig", "bugnaw", "temperatura", "hot", "cold", "araw", "gabi", "adlaw", "gabii", "walang hangin", "init ug bugnaw"], "fact": {"tl": "Sobrang init ng buwan kapag araw at sobrang lamig kapag gabi, dahil walang hangin na magpapantay ng temperatura.", "en": "The Moon gets very hot in the daytime and very cold at night, because it has no air to even out the temperature.", "bis": "Init kaayo ang bulan kon adlaw ug bugnaw kaayo kon gabii, tungod kay walay hangin nga makapatas sa temperatura."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "moon-apollo-humans-walked-g4", "domain": "EARTH_SPACE", "topic": "humans have walked on the Moon", "grades": [3, 4, 5, 6], "terms": ["buwan", "moon", "bulan", "tao", "tawo", "naglakad", "nilakaw", "astronaut", "astronawta", "Apollo", "nakarating", "nakaabot", "1969", "spaceship", "barko", "lumapag", "walked"], "fact": {"tl": "Ang buwan lang ang ibang mundo na nilakaran na ng tao — labindalawang astronaut na ang nakatapak dito mula noong 1969.", "en": "The Moon is the only other world humans have walked on — twelve astronauts have set foot there since 1969.", "bis": "Ang bulan ra ang laing kalibutan nga nalaktan na sa tawo — dose ka astronaut na ang nakatunob niini sukad sa 1969."}, "source": "encyclopedia-stable consensus (Apollo missions)", "generator": "claude-workflow", "reviewed": false},
  {"id": "jupiter-galilean-four-moons-g6", "domain": "EARTH_SPACE", "topic": "Jupiter's four large Galilean moons", "grades": [5, 6, 7], "terms": ["Jupiter", "buwan", "moons", "bulan", "apat", "upat", "malalaki", "dagko", "Galilean", "Galileo", "teleskopyo", "telescope", "Io", "Europa", "Ganymede", "Callisto", "natuklasan", "nakita"], "fact": {"tl": "May apat na malalaking buwan ang Jupiter — Io, Europa, Ganymede, at Callisto — na unang nakita ni Galileo gamit ang teleskopyo.", "en": "Jupiter has four large moons — Io, Europa, Ganymede, and Callisto — first seen by Galileo through a telescope.", "bis": "Ang Jupiter adunay upat ka dagko nga bulan — Io, Europa, Ganymede, ug Callisto — nga unang nakita ni Galileo pinaagi sa teleskopyo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ganymede-largest-moon-g6", "domain": "EARTH_SPACE", "topic": "Ganymede is the largest moon", "grades": [5, 6, 7], "terms": ["Ganymede", "buwan", "moon", "bulan", "pinakamalaki", "pinakadako", "largest", "Jupiter", "Mercury", "Mercurio", "mas malaki", "mas dako", "planeta", "Solar System"], "fact": {"tl": "Ang Ganymede, isang buwan ng Jupiter, ang pinakamalaking buwan sa Solar System — mas malaki pa ito sa planetang Mercury.", "en": "Ganymede, a moon of Jupiter, is the largest moon in the Solar System — it is even bigger than the planet Mercury.", "bis": "Ang Ganymede, usa ka bulan sa Jupiter, mao ang pinakadako nga bulan sa Solar System — mas dako pa kini sa planetang Mercury."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "europa-icy-ocean-g6", "domain": "EARTH_SPACE", "topic": "Europa's icy surface and hidden ocean", "grades": [5, 6, 7], "terms": ["Europa", "buwan", "moon", "bulan", "yelo", "ice", "niyebe", "tubig", "dagat", "ocean", "ilalim", "ilalom", "natabunan", "frozen", "yelong", "ilalim ng yelo", "Jupiter"], "fact": {"tl": "Ang Europa, isang buwan ng Jupiter, ay natatakpan ng makinis na yelo, at naniniwala ang mga siyentista na may dagat ng likidong tubig sa ilalim nito.", "en": "Europa, a moon of Jupiter, is covered in smooth ice, and scientists think there is an ocean of liquid water beneath it.", "bis": "Ang Europa, usa ka bulan sa Jupiter, gitabonan og hamis nga yelo, ug nagtuo ang mga siyentista nga adunay dagat sa likidong tubig sa ilalom niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "io-volcanoes-g6", "domain": "EARTH_SPACE", "topic": "Io is the most volcanic moon", "grades": [5, 6, 7], "terms": ["Io", "buwan", "moon", "bulan", "bulkan", "bolkan", "volcano", "volcanoes", "lava", "pagsabog", "pagbuto", "init", "Jupiter", "aktibo", "active", "pinakamaraming bulkan"], "fact": {"tl": "Ang Io, isang buwan ng Jupiter, ang may pinakamaraming aktibong bulkan sa Solar System na patuloy na nagbubuga ng lava.", "en": "Io, a moon of Jupiter, has the most active volcanoes in the Solar System, constantly erupting with lava.", "bis": "Ang Io, usa ka bulan sa Jupiter, mao ang adunay pinakadaghang aktibong bulkan sa Solar System nga padayong nagbuga og lava."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "callisto-cratered-moon-g6", "domain": "EARTH_SPACE", "topic": "Callisto is covered in craters", "grades": [5, 6, 7], "terms": ["Callisto", "buwan", "moon", "bulan", "crater", "craters", "butas", "lungag", "marami", "daghan", "luma", "karaan", "old", "Jupiter", "puno", "pinakamaraming crater"], "fact": {"tl": "Ang Callisto, isang buwan ng Jupiter, ay puno ng crater at isa sa mga pinakalumang ibabaw sa Solar System.", "en": "Callisto, a moon of Jupiter, is covered in craters and has one of the oldest surfaces in the Solar System.", "bis": "Ang Callisto, usa ka bulan sa Jupiter, puno og crater ug usa sa pinakakaraang nawong sa Solar System."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "titan-thick-atmosphere-g6", "domain": "EARTH_SPACE", "topic": "Titan has a thick atmosphere", "grades": [5, 6, 7], "terms": ["Titan", "buwan", "moon", "bulan", "Saturn", "hangin", "atmosphere", "makapal", "baga", "ulap", "panganod", "pinakamalaki", "pinakadako", "ulan", "thick air"], "fact": {"tl": "Ang Titan, ang pinakamalaking buwan ng Saturn, ay ang tanging buwan na may makapal na hangin sa paligid — parang may sariling atmosphere.", "en": "Titan, Saturn's largest moon, is the only moon with a thick atmosphere of air around it — almost like its own sky.", "bis": "Ang Titan, ang pinakadako nga bulan sa Saturn, mao ang bugtong bulan nga adunay baga nga hangin sa palibot — morag adunay kaugalingong atmosphere."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "titan-methane-lakes-g7", "domain": "EARTH_SPACE", "topic": "Titan has lakes of liquid methane", "grades": [6, 7, 8], "terms": ["Titan", "buwan", "moon", "bulan", "Saturn", "lawa", "lanaw", "lakes", "ilog", "suba", "river", "methane", "likido", "liquid", "lamig", "bugnaw", "tubig hindi", "wala tubig"], "fact": {"tl": "Napakalamig ng Titan kaya may mga lawa at ilog ito ng likidong methane sa halip na tubig.", "en": "Titan is so cold that it has lakes and rivers of liquid methane instead of water.", "bis": "Bugnaw kaayo ang Titan mao nga adunay mga lanaw ug suba kini sa likidong methane imbis tubig."}, "source": "encyclopedia-stable consensus (NASA Cassini-Huygens)", "generator": "claude-workflow", "reviewed": false},
  {"id": "enceladus-ice-geysers-g7", "domain": "EARTH_SPACE", "topic": "Enceladus shoots out ice geysers", "grades": [6, 7, 8], "terms": ["Enceladus", "buwan", "moon", "bulan", "Saturn", "yelo", "ice", "tubig", "geyser", "bumubuga", "nagbuga", "pagbuga", "tubig dagat", "dagat ilalim", "puti", "maputi", "spray"], "fact": {"tl": "Ang Enceladus, isang buwan ng Saturn, ay bumubuga ng tubig na nagiging yelo mula sa dagat na nakatago sa ilalim ng yelong ibabaw nito.", "en": "Enceladus, a moon of Saturn, shoots out jets of water and ice from an ocean hidden beneath its icy surface.", "bis": "Ang Enceladus, usa ka bulan sa Saturn, nagbuga og tubig nga nahimong yelo gikan sa dagat nga gitago sa ilalom sa iyang yelo nga nawong."}, "source": "encyclopedia-stable consensus (NASA Cassini)", "generator": "claude-workflow", "reviewed": false},
  {"id": "moons-orbit-planets-g4", "domain": "EARTH_SPACE", "topic": "what a moon is", "grades": [3, 4, 5], "terms": ["buwan", "moon", "moons", "bulan", "umiikot", "nagtuyok", "molibot", "orbit", "planeta", "planet", "natural satellite", "satelayt", "kasama", "kauban", "umiikot sa planeta"], "fact": {"tl": "Ang buwan (moon) ay isang bagay sa kalawakan na umiikot sa isang planeta, tulad ng pag-ikot ng ating buwan sa Earth.", "en": "A moon is an object in space that orbits a planet, the way our Moon orbits the Earth.", "bis": "Ang bulan (moon) usa ka butang sa kawanangan nga molibot sa usa ka planeta, sama sa paglibot sa atong bulan sa Earth."}, "source": "encyclopedia-stable consensus; NRC ESS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "mercury-venus-no-moons-g6", "domain": "EARTH_SPACE", "topic": "Mercury and Venus have no moons", "grades": [5, 6, 7], "terms": ["Mercury", "Mercurio", "Venus", "buwan", "moon", "moons", "bulan", "walang buwan", "walay bulan", "wala", "no moon", "planeta", "rocky", "malapit araw", "duol adlaw"], "fact": {"tl": "Ang Mercury at Venus ang tanging planeta sa Solar System na walang kahit isang buwan.", "en": "Mercury and Venus are the only planets in the Solar System with no moons at all.", "bis": "Ang Mercury ug Venus ra ang mga planeta sa Solar System nga walay bisan usa ka bulan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mars-two-tiny-moons-g6", "domain": "EARTH_SPACE", "topic": "Mars has two tiny moons", "grades": [5, 6, 7], "terms": ["Mars", "Marte", "buwan", "moon", "moons", "bulan", "dalawa", "duha", "two", "maliit", "gamay", "tiny", "Phobos", "Deimos", "bato", "hugis bato", "patatas"], "fact": {"tl": "May dalawang maliliit na buwan ang Mars — ang Phobos at Deimos — na hugis-bato at hindi bilog na parang ating buwan.", "en": "Mars has two tiny moons — Phobos and Deimos — that are lumpy and rocky instead of round like our Moon.", "bis": "Ang Mars adunay duha ka gagmay nga bulan — ang Phobos ug Deimos — nga binuyagbuyag og porma ug dili lingin sama sa atong bulan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "moons-shine-reflected-light-g5", "domain": "EARTH_SPACE", "topic": "moons shine by reflected sunlight", "grades": [4, 5, 6], "terms": ["buwan", "moon", "moons", "bulan", "liwanag", "kahayag", "ilaw", "sariling liwanag", "kaugalingong kahayag", "araw", "adlaw", "sinag", "silaw", "reflect", "nabubuwelta", "nibalik", "nagniningning"], "fact": {"tl": "Walang sariling liwanag ang mga buwan — kumikinang lang ang mga ito dahil sinasalamin nila ang sinag ng Araw.", "en": "Moons have no light of their own — they shine only because they reflect sunlight.", "bis": "Walay kaugalingong kahayag ang mga bulan — nagniningning lang kini tungod kay gisalamin nila ang silaw sa Adlaw."}, "source": "encyclopedia-stable consensus; NRC ESS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "moon-no-water-air-life-g5", "domain": "EARTH_SPACE", "topic": "why nothing lives on the Moon", "grades": [4, 5, 6], "terms": ["buwan", "moon", "bulan", "buhay", "kinabuhi", "life", "nabubuhay", "nagpuyo", "walang tubig", "walay tubig", "hangin", "halaman", "tanom", "hayop", "mananap", "tuyot", "patay"], "fact": {"tl": "Walang nabubuhay sa buwan dahil wala itong hangin, likidong tubig, o lupa na mapagtataniman ng halaman.", "en": "Nothing lives on the Moon because it has no air, no liquid water, and no soil for plants to grow.", "bis": "Walay nabuhi sa bulan tungod kay wala kini hangin, likidong tubig, o yuta nga katamnan og tanom."}, "source": "encyclopedia-stable consensus; NRC LS1", "generator": "claude-workflow", "reviewed": false},
  {"id": "moon-no-blue-sky-black-g6", "domain": "EARTH_SPACE", "topic": "the sky on the Moon looks black", "grades": [5, 6, 7], "terms": ["buwan", "moon", "bulan", "langit", "itim", "maitom", "black sky", "araw", "adlaw", "bituin", "bitoon", "stars", "walang hangin", "walay hangin", "kahit araw", "bisan adlaw"], "fact": {"tl": "Itim ang langit sa buwan kahit araw, dahil walang hangin na magkakalat ng liwanag tulad ng nangyayari sa asul na langit ng Earth.", "en": "The sky on the Moon looks black even in daytime, because there is no air to scatter light the way Earth's blue sky does.", "bis": "Itom ang langit sa bulan bisan adlaw, tungod kay walay hangin nga magsabwag sa kahayag sama sa nahitabo sa asul nga langit sa Earth."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "moon-footprints-stay-g5", "domain": "EARTH_SPACE", "topic": "footprints on the Moon last a long time", "grades": [4, 5, 6], "terms": ["buwan", "moon", "bulan", "yapak", "tunob", "footprint", "footprints", "astronaut", "nananatili", "magpabilin", "tagal", "dugay", "walang hangin", "walay hangin", "walang ulan", "walay ulan", "lupa", "abo"], "fact": {"tl": "Mananatili nang napakatagal ang mga yapak ng astronaut sa buwan dahil walang hangin o ulan na magbubura sa mga ito.", "en": "Astronauts' footprints on the Moon will last a very long time because there is no wind or rain to wipe them away.", "bis": "Magpabilin og dugay kaayo ang mga tunob sa astronaut sa bulan tungod kay walay hangin o ulan nga makapapas niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "neptune-triton-backward-g7", "domain": "EARTH_SPACE", "topic": "Neptune's moon Triton orbits backward", "grades": [6, 7, 8], "terms": ["Neptune", "Neptuno", "Triton", "buwan", "moon", "bulan", "paatras", "pabalik", "backward", "umiikot", "molibot", "lamig", "bugnaw", "yelo", "ice", "kakaiba", "lahi", "pinakamalaki"], "fact": {"tl": "Ang Triton, ang pinakamalaking buwan ng Neptune, ay umiikot nang pasalungat sa pag-ikot ng planeta — kakaiba ito sa karamihan ng buwan.", "en": "Triton, Neptune's largest moon, orbits backward compared to the planet's spin — unusual among moons.", "bis": "Ang Triton, ang pinakadako nga bulan sa Neptune, molibot nga sukwahi sa pagtuyok sa planeta — lahi kini sa kadaghanan sa mga bulan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pluto-charon-pair-g7", "domain": "EARTH_SPACE", "topic": "Pluto and its big moon Charon", "grades": [6, 7, 8], "terms": ["Pluto", "Pluton", "Charon", "buwan", "moon", "bulan", "dwarf planet", "malaki", "dako", "kalahati", "katunga", "half", "magkapareha", "magpares", "pair", "magkaharap", "umiikot magkasama"], "fact": {"tl": "Ang Charon, ang buwan ng dwarf planet na Pluto, ay halos kalahati ng laki ng Pluto kaya parang magkapares silang umiikot.", "en": "Charon, the moon of the dwarf planet Pluto, is about half the size of Pluto, so the two orbit almost like a pair.", "bis": "Ang Charon, ang bulan sa dwarf planet nga Pluto, mga katunga sa gidak-on sa Pluto mao nga morag magpares silang molibot."}, "source": "encyclopedia-stable consensus (NASA New Horizons)", "generator": "claude-workflow", "reviewed": false},
  {"id": "saturn-most-moons-g6", "domain": "EARTH_SPACE", "topic": "Saturn has the most moons", "grades": [5, 6, 7], "terms": ["Saturn", "Saturno", "buwan", "moons", "bulan", "pinakamarami", "pinakadaghan", "most moons", "marami", "daghan", "Jupiter", "bilang", "ihap", "siyam na pu", "kapin", "higante"], "fact": {"tl": "Ang Saturn ang may pinakamaraming kilalang buwan sa Solar System — mahigit isang daan na ang natuklasan.", "en": "Saturn has the most known moons in the Solar System — more than a hundred have been found.", "bis": "Ang Saturn mao ang adunay pinakadaghang nailhang bulan sa Solar System — kapin sa usa ka gatos na ang nadiskobre."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "moon-no-weather-g5", "domain": "EARTH_SPACE", "topic": "the Moon has no weather", "grades": [4, 5, 6], "terms": ["buwan", "moon", "bulan", "panahon", "weather", "ulan", "ulan walay", "hangin", "bagyo", "unos", "storm", "ulap", "panganod", "clouds", "walang panahon", "walay panahon", "tuyot"], "fact": {"tl": "Walang panahon ang buwan — walang ulan, ulap, o bagyo — dahil wala itong hangin o tubig sa ibabaw.", "en": "The Moon has no weather — no rain, clouds, or storms — because it has no air or water on its surface.", "bis": "Walay panahon ang bulan — walay ulan, panganod, o bagyo — tungod kay wala kini hangin o tubig sa nawong."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "moons-not-stars-g4", "domain": "EARTH_SPACE", "topic": "moons are not stars", "grades": [3, 4, 5], "terms": ["buwan", "moon", "moons", "bulan", "bituin", "bitoon", "star", "stars", "hindi bituin", "dili bitoon", "init", "kahayag sarili", "kaugalingong kahayag", "malamig", "bugnaw", "umiikot planeta", "molibot planeta"], "fact": {"tl": "Ang mga buwan ay hindi bituin — malamig ang mga ito, walang sariling liwanag, at umiikot lamang sa mga planeta.", "en": "Moons are not stars — they are cold, have no light of their own, and only orbit planets.", "bis": "Ang mga bulan dili bitoon — bugnaw kini, walay kaugalingong kahayag, ug molibot lang sa mga planeta."}, "source": "encyclopedia-stable consensus; NRC ESS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "titan-only-moon-rivers-g7", "domain": "EARTH_SPACE", "topic": "Titan is the only moon with surface liquid", "grades": [6, 7, 8], "terms": ["Titan", "buwan", "moon", "bulan", "Saturn", "tanging", "bugtong", "only", "ibabaw", "nawong", "likido", "liquid", "ilog", "suba", "lawa", "lanaw", "Earth lang", "tubig pero hindi", "natatangi"], "fact": {"tl": "Bukod sa Earth, ang Titan lang ang katawan sa Solar System na may likido sa ibabaw — pero methane ito, hindi tubig.", "en": "Besides Earth, Titan is the only body in the Solar System with liquid on its surface — but it is methane, not water.", "bis": "Gawas sa Earth, ang Titan ra ang lawas sa Solar System nga adunay likido sa nawong — apan methane kini, dili tubig."}, "source": "encyclopedia-stable consensus (NASA Cassini-Huygens)", "generator": "claude-workflow", "reviewed": false},
  {"id": "stars-not-same-brightness-color-g3", "domain": "EARTH_SPACE", "topic": "stars differ in brightness and color", "grades": [3, 4], "terms": ["bituin", "bituon", "star", "stars", "liwanag", "kahayag", "kulay", "kolor", "color", "maliwanag", "masanag", "bright", "magkakaiba", "lain-lain", "hindi pare-pareho", "dili parehas", "langit", "kislap"], "fact": {"tl": "Hindi pare-pareho ang mga bituin — may mga bituing mas maliwanag kaysa iba, at may iba't ibang kulay sila tulad ng mapula, maputi, at mabughaw.", "en": "Stars are not all the same — some stars are brighter than others, and they come in different colors like reddish, white, and bluish.", "bis": "Dili parehas ang mga bituon — adunay mga bituon nga mas masanag kaysa uban, ug lain-lain ang ilang kolor sama sa mapula, maputi, ug asul."}, "source": "AAAS BSL Ch.4A/P1", "generator": "claude-workflow", "reviewed": false},
  {"id": "star-color-temperature-g7", "domain": "EARTH_SPACE", "topic": "star color shows temperature", "grades": [7, 8, 9], "terms": ["bituin", "bituon", "star", "kulay", "kolor", "color", "temperatura", "temperature", "init", "kainit", "hot", "mainit", "mas mainit", "mas init", "mapula", "asul", "bughaw", "blue", "red", "maputi", "mainit-init", "pinakamainit"], "fact": {"tl": "Ipinapakita ng kulay ng bituin kung gaano ito kainit: ang mga mapula-pula at orange na bituin ang pinakamalamig, ang mga dilaw at puti ay mas mainit, at ang mga mabughaw na bituin ang pinakamainit.", "en": "A star's color tells how hot it is: reddish and orange stars are the coolest, yellow and white stars are hotter, and bluish stars are the hottest of all.", "bis": "Ang kolor sa bituon nagpakita kung unsa kini kainit: ang mapula ug orange nga mga bituon mao ang pinakabugnaw, ang dalag ug puti mas init, ug ang asul nga mga bituon mao ang pinakainit."}, "source": "AAAS BSL Ch.4A/H1a; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "stars-differ-size-temp-age-g9", "domain": "EARTH_SPACE", "topic": "how stars differ from each other", "grades": [9, 10], "terms": ["bituin", "bituon", "star", "stars", "laki", "gidak-on", "size", "temperatura", "temperature", "edad", "panuigon", "age", "magkakaiba", "lain-lain", "elemento", "element", "parehas", "pareho", "kemikal"], "fact": {"tl": "Ang mga bituin ay nag-iiba sa laki, temperatura, at edad, ngunit halos pareho silang gawa sa mga elementong matatagpuan din sa Earth at sumusunod sa parehong batas ng pisika.", "en": "Stars differ from one another in size, temperature, and age, yet they appear to be made of the same elements found on Earth and to behave by the same laws of physics.", "bis": "Ang mga bituon nagkalain-lain sa gidak-on, temperatura, ug panuigon, apan halos parehas silang hinimo sa mga elemento nga makita usab sa Earth ug nagsunod sa samang mga balaod sa pisika."}, "source": "AAAS BSL Ch.4A/H1a", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-medium-sized-star-g6", "domain": "EARTH_SPACE", "topic": "the Sun is a medium-sized star", "grades": [5, 6, 7], "terms": ["araw", "adlaw", "sun", "bituin", "bituon", "star", "katamtaman", "kasarangan", "medium", "katamtamang laki", "ordinaryo", "ordinary", "karaniwan", "yellow", "dilaw", "dalag", "hindi pinakamalaki", "dili pinakadako"], "fact": {"tl": "Ang ating Araw ay isang katamtamang-laki at dilaw na bituin — hindi ito ang pinakamalaki o pinakamaliit na bituin, kundi karaniwan lang kung ihahambing sa ibang bituin sa galaxy.", "en": "Our Sun is a medium-sized, yellow star — it is not the biggest or the smallest star, but an ordinary one compared with the other stars in the galaxy.", "bis": "Ang atong Adlaw usa ka kasarangan og gidak-on ug dalag nga bituon — dili kini ang pinakadako o pinakagamay nga bituon, kondili ordinaryo lang kon itandi sa ubang bituon sa galaksiya."}, "source": "AAAS BSL Ch.4A/M1a", "generator": "claude-workflow", "reviewed": false},
  {"id": "stars-bigger-smaller-than-sun-g4", "domain": "EARTH_SPACE", "topic": "stars are like the sun, some bigger some smaller", "grades": [4, 5], "terms": ["bituin", "bituon", "star", "araw", "adlaw", "sun", "kapareho", "sama", "like", "mas malaki", "mas dako", "bigger", "mas maliit", "mas gamay", "smaller", "tuldok", "tulbok", "point of light", "malayo", "layo", "tila maliit"], "fact": {"tl": "Ang mga bituin ay tulad ng ating Araw — may mas malaki at may mas maliit kaysa rito — ngunit napakalayo nila kaya parang maliliit na tuldok lang ng liwanag sa langit.", "en": "Stars are like our Sun — some are bigger and some are smaller — but they are so far away that they look like tiny points of light in the sky.", "bis": "Ang mga bituon sama sa atong Adlaw — adunay mas dako ug adunay mas gamay niini — apan layo kaayo sila mao nga morag gagmayng tulbok lang sa kahayag sa langit."}, "source": "AAAS BSL Ch.4A/E5", "generator": "claude-workflow", "reviewed": false},
  {"id": "supergiant-stars-betelgeuse-g7", "domain": "EARTH_SPACE", "topic": "giant and supergiant stars", "grades": [7, 8], "terms": ["bituin", "bituon", "star", "higante", "higanteng bituin", "giant", "supergiant", "Betelgeuse", "napakalaki", "dako kaayo", "huge", "Araw", "Adlaw", "sun", "pula", "red", "mapula", "Orion", "konstelasyon"], "fact": {"tl": "May mga bituing tinatawag na higante at superhigante na napakalaki — ang Betelgeuse sa konstelasyong Orion ay daan-daang ulit na mas malaki ang lapad kaysa sa ating Araw.", "en": "Some stars called giants and supergiants are enormous — Betelgeuse in the constellation Orion is hundreds of times wider than our Sun.", "bis": "Adunay mga bituon nga gitawag og higante ug superhigante nga dako kaayo — ang Betelgeuse sa konstelasyong Orion gatosan ka pilo nga mas lapad kaysa atong Adlaw."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.4A/H1a", "generator": "claude-workflow", "reviewed": false},
  {"id": "stars-born-in-nebula-g7", "domain": "EARTH_SPACE", "topic": "how stars are born", "grades": [7, 8], "terms": ["bituin", "bituon", "star", "isinilang", "natawo", "born", "ipinanganak", "ulap", "panganod", "cloud", "gas", "alikabok", "abog", "dust", "nebula", "gravity", "grabidad", "namuo", "nagtipon", "nagtapok"], "fact": {"tl": "Ang mga bituin ay isinilang sa loob ng malalaking ulap ng gas at alikabok na tinatawag na nebula; hinihila ng grabidad ang gas upang magtipon at lumiit hanggang sumiklab ito at maging bituin.", "en": "Stars are born inside huge clouds of gas and dust called nebulas; gravity pulls the gas together and squeezes it until it ignites and becomes a star.", "bis": "Ang mga bituon natawo sulod sa dagkong panganod sa gas ug abog nga gitawag og nebula; ang grabidad mobira sa gas aron magtapok ug magamay hangtod modilaab kini ug mahimong bituon."}, "source": "AAAS BSL Ch.4A/H2cd", "generator": "claude-workflow", "reviewed": false},
  {"id": "star-fusion-makes-light-g8", "domain": "EARTH_SPACE", "topic": "fusion powers a star", "grades": [8, 9, 10], "terms": ["bituin", "bituon", "star", "nuclear fusion", "hydrogen", "helium", "pagsasama", "pagtapok", "enerhiya", "kusog", "energy", "liwanag", "kahayag", "init", "kainit", "kaloob-looban", "kinasuloran", "core", "nagliliyab"], "fact": {"tl": "Nagliliwanag at umiinit ang isang bituin dahil sa kaloob-looban nito ay pinagsasama ng nuclear fusion ang hydrogen upang maging helium, na naglalabas ng napakaraming enerhiya sa loob ng milyon-milyong taon.", "en": "A star shines and stays hot because deep in its core, nuclear fusion joins hydrogen into helium, releasing huge amounts of energy over millions of years.", "bis": "Mosidlak ug moinit ang usa ka bituon kay sa kinasuloran niini, ang nuclear fusion magtapok sa hydrogen aron mahimong helium, nga mobuga og daghan kaayong enerhiya sulod sa milyon-milyon ka tuig."}, "source": "AAAS BSL Ch.4A/H2cd", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-fuel-lifespan-g8", "domain": "EARTH_SPACE", "topic": "the Sun's age and lifespan", "grades": [8, 9], "terms": ["araw", "adlaw", "sun", "edad", "panuigon", "age", "bilyong taon", "bilyon", "billion years", "gulang", "hydrogen", "gatong", "fuel", "kalahati", "katunga", "buhay", "kinabuhi", "lifespan", "magtatagal", "molungtad"], "fact": {"tl": "Ang ating Araw ay humigit-kumulang 4.6 bilyong taon na ang edad at nasa kalagitnaan pa lang ng kanyang buhay; magtatagal pa ito ng ilang bilyong taon habang ginagamit ang hydrogen na gatong nito.", "en": "Our Sun is about 4.6 billion years old and only middle-aged; it will keep shining for several billion more years as it uses up its hydrogen fuel.", "bis": "Ang atong Adlaw mga 4.6 ka bilyon ka tuig na ang panuigon ug tunga-tunga pa lang sa iyang kinabuhi; molungtad pa kini og pipila ka bilyon ka tuig samtang gigamit niini ang hydrogen nga gatong."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.4A/H6", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-becomes-red-giant-g8", "domain": "EARTH_SPACE", "topic": "how the Sun will end", "grades": [8, 9], "terms": ["araw", "adlaw", "sun", "mamamatay", "mamatay", "die", "katapusan", "kahuman", "end", "red giant", "pulang higante", "lalaki", "modako", "swell", "lumalamig", "mobugnaw", "cool", "white dwarf", "puting unano", "bilyong taon"], "fact": {"tl": "Pagkaubos ng gatong nito makalipas ang bilyong taon, ang Araw ay lalaki at magiging isang pulang higante (red giant), pagkatapos ay liliit at lalamig tungo sa isang malamlam na 'white dwarf.'", "en": "When its fuel runs low billions of years from now, the Sun will swell into a red giant, then shrink and cool into a faint 'white dwarf.'", "bis": "Kon mahurot ang gatong niini human sa bilyon ka tuig, ang Adlaw modako ug mahimong usa ka pulang higante (red giant), unya momgamay ug mobugnaw ngadto sa usa ka huyang nga 'white dwarf.'"}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.4A/H2", "generator": "claude-workflow", "reviewed": false},
  {"id": "supernova-explosion-g9", "domain": "EARTH_SPACE", "topic": "supernova explosions", "grades": [9, 10], "terms": ["bituin", "bituon", "star", "sumabog", "mibuto", "explode", "pagsabog", "pagbuto", "supernova", "malalaking bituin", "dagkong bituon", "massive", "mabigat", "mabug-at", "liwanag", "elemento", "element", "mabigat na elemento", "katapusan"], "fact": {"tl": "Ang napakalalaking bituin ay nagtatapos sa isang malakas na pagsabog na tinatawag na supernova, na sandaling sumisikat na parang bilyong Araw at nagkakalat ng mga bagong mabibigat na elemento sa kalawakan.", "en": "A very massive star ends its life in a powerful explosion called a supernova, which briefly shines like billions of Suns and scatters new heavy elements into space.", "bis": "Ang dako kaayong bituon mohuman sa iyang kinabuhi sa kusgang pagbuto nga gitawag og supernova, nga makadiyot mosidlak nga morag bilyon ka Adlaw ug magsabwag og bag-ong bug-at nga mga elemento sa kawanangan."}, "source": "AAAS BSL Ch.4A/H2ef", "generator": "claude-workflow", "reviewed": false},
  {"id": "we-are-made-of-stardust-g9", "domain": "EARTH_SPACE", "topic": "elements come from old stars", "grades": [9, 10], "terms": ["elemento", "element", "bituin", "bituon", "star", "sumabog", "mibuto", "nasabog", "exploding stars", "carbon", "iron", "bakal", "katawan", "lawas", "body", "stardust", "alabok ng bituin", "nilikha", "gihimo", "galing", "gikan"], "fact": {"tl": "Halos lahat ng mabibigat na elemento sa Earth at sa ating katawan — tulad ng carbon at iron — ay ginawa sa loob ng mga bituin at ikinalat ng mga sumabog na bituin bago nabuo ang ating Araw.", "en": "Almost all the heavy elements on Earth and in our bodies — like carbon and iron — were made inside stars and scattered by exploding stars before our Sun formed.", "bis": "Halos tanang bug-at nga mga elemento sa Earth ug sa atong lawas — sama sa carbon ug iron — gihimo sulod sa mga bituon ug gisabwag sa nibutong mga bituon sa wala pa maporma ang atong Adlaw."}, "source": "AAAS BSL Ch.4A/H6", "generator": "claude-workflow", "reviewed": false},
  {"id": "nearest-star-proxima-g7", "domain": "EARTH_SPACE", "topic": "the nearest star after the Sun", "grades": [7, 8], "terms": ["pinakamalapit", "pinakaduol", "nearest", "bituin", "bituon", "star", "Araw", "Adlaw", "sun", "Proxima Centauri", "light-year", "liwanag", "kahayag", "layo", "gilay-on", "distance", "apat na taon", "upat ka tuig", "next nearest"], "fact": {"tl": "Ang pinakamalapit na bituin pagkatapos ng Araw ay tinatawag na Proxima Centauri, at napakalayo nito kaya umaabot ng mga apat na taon bago marating ng liwanag nito ang Earth.", "en": "The nearest star after the Sun is called Proxima Centauri, and it is so far that its light takes about four years to reach Earth.", "bis": "Ang pinakaduol nga bituon human sa Adlaw gitawag og Proxima Centauri, ug layo kaayo kini mao nga mga upat ka tuig ang gikinahanglan sa kahayag niini aron makaabot sa Earth."}, "source": "AAAS BSL Ch.4A/M2abc; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "stars-are-suns-far-away-g6", "domain": "EARTH_SPACE", "topic": "why other stars look so dim", "grades": [5, 6, 7], "terms": ["bituin", "bituon", "star", "Araw", "Adlaw", "sun", "malayo", "layo", "far", "malabo", "huyang", "dim", "maliit", "gamay", "tuldok", "tulbok", "kung bakit", "ngano", "mas malapit", "mas duol", "pinakamalapit"], "fact": {"tl": "Ang ibang mga bituin ay tunay na Araw din na napakalayo lamang; kung mailalapit sila gaya ng ating Araw, magiging napakaliwanag at napakainit din nila.", "en": "The other stars are really suns too, only very far away; if they were as close as our Sun, they would be just as blindingly bright and hot.", "bis": "Ang ubang mga bituon mga Adlaw usab nga layo ra kaayo; kon sila duol pa sama sa atong Adlaw, masanag ug init usab kaayo sila."}, "source": "AAAS BSL Ch.4A/E5; M2abc", "generator": "claude-workflow", "reviewed": false},
  {"id": "milky-way-band-g6", "domain": "EARTH_SPACE", "topic": "the Milky Way band in the sky", "grades": [6, 7, 8], "terms": ["Milky Way", "galaxy", "galaksiya", "bituin", "bituon", "star", "guhit", "banda", "band", "liwanag", "kahayag", "langit", "madilim", "ngitngit", "malinaw na gabi", "tin-aw nga gabii", "gatas", "milky", "bilyon"], "fact": {"tl": "Ang ating Araw ay isa sa bilyon-bilyong bituin sa Milky Way galaxy; sa napakalinaw at madilim na gabi, makikita ang bahagi nito bilang malabong guhit ng liwanag na bumabagtas sa langit.", "en": "Our Sun is one of billions of stars in the Milky Way galaxy; on a very clear, dark night you can see part of it as a faint band of light stretching across the sky.", "bis": "Ang atong Adlaw usa sa bilyon-bilyon ka bituon sa Milky Way nga galaksiya; sa tin-aw kaayo ug ngitngit nga gabii, makita ang bahin niini isip huyang nga guhit sa kahayag nga molatas sa langit."}, "source": "AAAS BSL Ch.4A/M1a", "generator": "claude-workflow", "reviewed": false},
  {"id": "star-patterns-stay-same-g4", "domain": "EARTH_SPACE", "topic": "star patterns stay the same", "grades": [4, 5], "terms": ["bituin", "bituon", "star", "pattern", "ayos", "porma", "hugis", "hulagway", "constellation", "konstelasyon", "hindi nagbabago", "dili mausab", "stay the same", "umiikot", "molihok", "gumagalaw", "langit", "gabi", "gabii"], "fact": {"tl": "Ang ayos o pattern ng mga bituin sa langit ay nananatiling pareho gabi-gabi, kahit mukhang dahan-dahan silang gumagalaw mula silangan patungong kanluran habang umiikot ang Earth.", "en": "The patterns of stars in the sky stay the same each night, even though they appear to drift slowly from east to west as the Earth turns.", "bis": "Ang porma o pattern sa mga bituon sa langit magpabilin nga parehas matag gabii, bisan og morag hinay silang molihok gikan sa sidlakan paingon sa kasadpan samtang molihok ang Earth."}, "source": "AAAS BSL Ch.4A/E1", "generator": "claude-workflow", "reviewed": false},
  {"id": "different-stars-each-season-g5", "domain": "EARTH_SPACE", "topic": "different stars appear in different seasons", "grades": [5, 6], "terms": ["bituin", "bituon", "star", "panahon", "season", "tag-init", "tag-ulan", "tag-araw", "iba't ibang", "lain-lain", "konstelasyon", "constellation", "lumilitaw", "motungha", "nagbabago", "umiikot", "molibot", "Araw", "Adlaw"], "fact": {"tl": "Iba't ibang konstelasyon ang nakikita sa iba't ibang panahon ng taon, dahil habang umiikot ang Earth sa Araw, nababago ang panig ng kalawakan na hinaharap natin sa gabi.", "en": "Different constellations are seen in different times of the year, because as Earth orbits the Sun, the part of space we face at night changes.", "bis": "Lain-laing konstelasyon ang makita sa lain-laing panahon sa tuig, kay samtang molibot ang Earth sa Adlaw, mausab ang bahin sa kawanangan nga atong giatubang sa gabii."}, "source": "AAAS BSL Ch.4A/E1", "generator": "claude-workflow", "reviewed": false},
  {"id": "constellation-orion-g5", "domain": "EARTH_SPACE", "topic": "the constellation Orion", "grades": [5, 6], "terms": ["Orion", "konstelasyon", "constellation", "bituin", "bituon", "star", "mangangaso", "mangangayam", "hunter", "sinturon", "bakus", "belt", "tatlong bituin", "tulo ka bituon", "three stars", "Betelgeuse", "Rigel", "langit", "Pilipinas"], "fact": {"tl": "Ang Orion ay isang sikat na konstelasyon na kumakatawan sa isang mangangaso, at madaling makilala dahil sa 'sinturon' nito na binubuo ng tatlong bituing magkakapantay; makikita ito sa langit ng Pilipinas.", "en": "Orion is a famous constellation pictured as a hunter, easy to spot because of its 'belt' of three stars in a straight row; it can be seen from the Philippine sky.", "bis": "Ang Orion usa ka bantog nga konstelasyon nga gihulagway isip mangangayam, sayon ilhon tungod sa iyang 'bakus' nga tulo ka bituon nga managsunod; makita kini sa langit sa Pilipinas."}, "source": "AAAS BSL Ch.4A/P1; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "polaris-north-star-g6", "domain": "EARTH_SPACE", "topic": "Polaris the North Star", "grades": [6, 7], "terms": ["Polaris", "North Star", "hilagang bituin", "amihanang bituon", "bituin", "bituon", "star", "hindi gumagalaw", "dili molihok", "hilaga", "amihanan", "north", "gabay", "giya", "direksyon", "direksiyon", "manlalakbay", "magbibiyahe", "navigation"], "fact": {"tl": "Ang Polaris o 'North Star' ay isang bituing tila hindi gumagalaw sa langit dahil halos nasa direksyon ito ng hilagang poste ng Earth; kaya ginagamit ito ng mga manlalakbay para malaman ang direksyong hilaga.", "en": "Polaris, the 'North Star,' is a star that seems to stay still in the sky because it lies almost above Earth's north pole; travelers use it to find the direction north.", "bis": "Ang Polaris o 'North Star' usa ka bituon nga morag dili molihok sa langit kay halos naa kini sa direksyon sa amihanang poste sa Earth; busa gigamit kini sa mga magbibiyahe aron mahibaloan ang direksyon nga amihanan."}, "source": "AAAS BSL Ch.4A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "constellations-not-touching-g6", "domain": "EARTH_SPACE", "topic": "constellation stars are not really close", "grades": [6, 7], "terms": ["konstelasyon", "constellation", "bituin", "bituon", "star", "magkalapit", "duol", "close together", "magkadikit", "hindi magkalapit", "dili duol", "iba't ibang layo", "lain-laing gilay-on", "hugis", "porma", "pattern", "tila", "morag", "langit"], "fact": {"tl": "Ang mga bituin sa isang konstelasyon ay tila magkakalapit, ngunit talagang nasa magkakaibang layo sila sa kalawakan — nagkataon lang na bumubuo sila ng hugis kapag tinitingnan mula sa Earth.", "en": "The stars in a constellation look close together, but they are really at very different distances in space — they only happen to form a shape when seen from Earth.", "bis": "Ang mga bituon sa usa ka konstelasyon morag magkaduol, apan tinuod nga lain-lain ang ilang gilay-on sa kawanangan — natural lang nga naghimo silag porma kon tan-awon gikan sa Earth."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.4A", "generator": "claude-workflow", "reviewed": false},
  {"id": "constellations-used-for-farming-g5", "domain": "EARTH_SPACE", "topic": "ancient uses of constellations", "grades": [4, 5, 6], "terms": ["konstelasyon", "constellation", "bituin", "bituon", "star", "sinauna", "karaan", "ancient", "pagsasaka", "pag-uma", "farming", "paglalayag", "paglawig", "navigation", "panahon", "season", "gabay", "giya", "pagtatanim"], "fact": {"tl": "Noong unang panahon, ginagamit ng mga tao ang mga konstelasyon at ang galaw ng mga bituin bilang gabay sa pagsasaka at paglalayag, dahil ipinapakita nito kung anong panahon na ng taon.", "en": "Long ago, people used the constellations and the motions of the stars as a guide for farming and sailing, because they showed what time of year it was.", "bis": "Kaniadto, gigamit sa mga tawo ang mga konstelasyon ug ang paglihok sa mga bituon isip giya sa pag-uma ug paglawig, kay nagpakita kini kon unsang panahon na sa tuig."}, "source": "AAAS BSL Ch.4A (intro); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "stars-too-many-to-count-g3", "domain": "EARTH_SPACE", "topic": "there are countless stars", "grades": [3, 4], "terms": ["bituin", "bituon", "star", "stars", "marami", "daghan", "many", "hindi mabilang", "dili maihap", "countless", "bilyon", "bilyong", "billions", "langit", "gabi", "gabii", "napakarami", "daghan kaayo"], "fact": {"tl": "May napakaraming bituin sa langit na hindi natin kayang bilangin, at marami pang hindi natin nakikita dahil sobrang layo o sobrang labo nila.", "en": "There are so many stars in the sky that no one can count them all, and many more are too far or too faint for us to see.", "bis": "Adunay daghan kaayong bituon sa langit nga dili nato maihap, ug mas daghan pa ang dili nato makita kay layo ra kaayo o huyang ra kaayo sila."}, "source": "AAAS BSL Ch.4A/P1; M1bc", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-only-seen-daytime-g3", "domain": "EARTH_SPACE", "topic": "when the sun and stars are visible", "grades": [3, 4], "terms": ["araw", "adlaw", "sun", "bituin", "bituon", "star", "umaga", "daytime", "gabi", "gabii", "night", "buwan", "bulan", "moon", "nakikita", "makita", "gumagalaw", "molihok", "langit", "tila gumagalaw"], "fact": {"tl": "Ang Araw ay nakikita lamang sa umaga, samantalang ang mga bituin ay sa gabi; pero pareho silang tila dahan-dahang gumagalaw sa kalangitan dahil sa pag-ikot ng Earth.", "en": "The Sun can be seen only in the daytime, while the stars are seen at night; but both seem to move slowly across the sky because the Earth turns.", "bis": "Ang Adlaw makita lang kon adlaw, samtang ang mga bituon makita kon gabii; apan silang duha morag hinay nga molihok sa langit tungod sa paglihok sa Earth."}, "source": "AAAS BSL Ch.4A/P2", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-surface-temperature-g7", "domain": "EARTH_SPACE", "topic": "the Sun's surface temperature", "grades": [7, 8], "terms": ["araw", "adlaw", "sun", "init", "kainit", "hot", "temperatura", "temperature", "ibabaw", "surface", "libo-libong digri", "liboan ka degrees", "thousands of degrees", "gas", "hydrogen", "helium", "bola", "bola sa gas"], "fact": {"tl": "Ang ibabaw ng Araw ay napakainit, mga 5,500 digri Celsius, at ito ay isang malaking bola ng nag-aapoy na gas na halos puro hydrogen at helium.", "en": "The Sun's surface is blazing hot, about 5,500 degrees Celsius, and it is a giant ball of glowing gas made mostly of hydrogen and helium.", "bis": "Ang ibabaw sa Adlaw init kaayo, mga 5,500 ka degrees Celsius, ug usa kini ka dakong bola sa nagdilaab nga gas nga kasagaran hydrogen ug helium."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.4A", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-much-closer-than-stars-g6", "domain": "EARTH_SPACE", "topic": "the Sun is far closer than other stars", "grades": [6, 7], "terms": ["araw", "adlaw", "sun", "bituin", "bituon", "star", "malapit", "duol", "close", "mas malapit", "mas duol", "libong ulit", "liboan ka pilo", "thousands of times", "minuto", "minutos", "minutes", "taon", "tuig", "years", "liwanag", "kahayag"], "fact": {"tl": "Ang Araw ay libo-libong ulit na mas malapit sa Earth kaysa kahit anong ibang bituin; umaabot ang liwanag nito sa atin sa ilang minuto lamang, ngunit ang liwanag ng susunod na pinakamalapit na bituin ay umaabot ng ilang taon.", "en": "The Sun is many thousands of times closer to Earth than any other star; its light reaches us in just a few minutes, but light from the next nearest star takes a few years.", "bis": "Ang Adlaw liboan ka pilo nga mas duol sa Earth kaysa bisan unsang ubang bituon; ang kahayag niini moabot kanato sulod lang sa pipila ka minuto, apan ang kahayag sa sunod nga pinakaduol nga bituon moabot og pipila ka tuig."}, "source": "AAAS BSL Ch.4A/M2abc", "generator": "claude-workflow", "reviewed": false},
  {"id": "star-life-cycle-continues-g8", "domain": "EARTH_SPACE", "topic": "stars are still being born and dying", "grades": [8, 9], "terms": ["bituin", "bituon", "star", "stars", "isinisilang", "natawo", "born", "namamatay", "namatay", "die", "patuloy", "padayon", "continues", "ngayon", "karon", "now", "ulap", "panganod", "nebula", "siklo", "siklo sa kinabuhi", "life cycle"], "fact": {"tl": "Ang pagsilang at pagkamatay ng mga bituin ay patuloy na nangyayari kahit ngayon — habang may matatandang bituing namamatay, may mga bagong bituing isinisilang sa loob ng mga ulap ng gas at alikabok.", "en": "The birth and death of stars is still going on right now — as old stars die, new stars are being born inside clouds of gas and dust.", "bis": "Ang pagkatawo ug pagkamatay sa mga bituon nagpadayon bisan karon — samtang adunay tigulang nga mga bituon nga namatay, adunay bag-ong mga bituon nga natawo sulod sa mga panganod sa gas ug abog."}, "source": "AAAS BSL Ch.4A/H2ef", "generator": "claude-workflow", "reviewed": false},
  {"id": "blue-stars-burn-fast-g9", "domain": "EARTH_SPACE", "topic": "big hot stars live shorter lives", "grades": [9, 10], "terms": ["bituin", "bituon", "star", "malalaki", "dagko", "big", "mainit", "init", "hot", "asul", "blue", "mabilis", "paspas", "fast", "buhay", "kinabuhi", "life", "maikli", "mubo", "short", "gatong", "fuel", "maliit", "gamay", "matagal"], "fact": {"tl": "Ang malalaki at mabubughaw na bituin ang pinakamainit ngunit pinakamaikli ang buhay dahil mabilis nilang nauubos ang gatong, samantalang ang maliliit na pulang bituin ay nagtatagal nang napakahabang panahon.", "en": "Big, bluish stars are the hottest but live the shortest lives because they burn through their fuel fast, while small red stars last for an extremely long time.", "bis": "Ang dagko ug asul nga mga bituon mao ang pinakainit apan pinakamubo og kinabuhi kay paspas nilang mahurot ang gatong, samtang ang gagmayng pula nga mga bituon molungtad og taas kaayong panahon."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.4A/H1a", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-gives-earth-energy-g4", "domain": "EARTH_SPACE", "topic": "the Sun's energy supports life on Earth", "grades": [3, 4, 5], "terms": ["araw", "adlaw", "sun", "bituin", "bituon", "star", "enerhiya", "kusog", "energy", "init", "kainit", "heat", "liwanag", "kahayag", "light", "buhay", "kinabuhi", "life", "halaman", "tanom", "plant", "panahon", "klima"], "fact": {"tl": "Ang Araw, na ating pinakamalapit na bituin, ang nagbibigay ng init at liwanag na kailangan ng halaman, hayop, at tao para mabuhay sa Earth.", "en": "The Sun, our nearest star, gives the heat and light that plants, animals, and people need to live on Earth.", "bis": "Ang Adlaw, nga atong pinakaduol nga bituon, maoy naghatag sa kainit ug kahayag nga gikinahanglan sa mga tanom, hayop, ug tawo aron mabuhi sa Earth."}, "source": "AAAS BSL Ch.4A; NRC ESS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "galaxy-what-is-g5", "domain": "EARTH_SPACE", "topic": "what is a galaxy", "grades": [5, 6, 7], "terms": ["galaxy", "galaksi", "bituin", "bituon", "bilyon-bilyong bituin", "bilyon ka bituon", "grupo", "pundok", "stars", "huge group of stars"], "fact": {"tl": "Ang galaxy o galaksi ay napakalaking grupo ng bilyon-bilyong bituin, gas, at alikabok na pinagdidikit ng grabidad sa kalawakan.", "en": "A galaxy is a huge group of billions of stars, gas, and dust held together by gravity in space.", "bis": "Ang galaxy o galaksi usa ka dako kaayong pundok sa bilyon-bilyon ka bituon, gas, ug abog nga gihiusa sa grabidad sa kawanangan."}, "source": "AAAS BSL 4A/M1bc; NRC ESS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "milky-way-our-galaxy-g5", "domain": "EARTH_SPACE", "topic": "the Milky Way galaxy", "grades": [5, 6, 7], "terms": ["Milky Way", "atong galaxy", "ating galaxy", "tahanan", "balay", "Araw", "Adlaw", "kabilang", "sakop", "our galaxy", "home"], "fact": {"tl": "Ang ating galaxy ay tinatawag na Milky Way, at dito kabilang ang ating Araw at ang lahat ng bituing nakikita natin sa gabi.", "en": "Our galaxy is called the Milky Way, and our Sun and all the stars we see at night belong to it.", "bis": "Ang atong galaxy gitawag og Milky Way, ug niini sakop ang atong Adlaw ug ang tanang bituon nga atong makita sa gabii."}, "source": "AAAS BSL 4A/M1a", "generator": "claude-workflow", "reviewed": false},
  {"id": "milky-way-band-of-light-g5", "domain": "EARTH_SPACE", "topic": "Milky Way band in the sky", "grades": [5, 6, 7], "terms": ["Milky Way", "makinang na guhit", "nagaagay nga kahayag", "band of light", "malinaw na gabi", "tin-aw nga gabii", "langit", "guhit sa langit", "disc", "disk-shaped", "gilid", "kilid"], "fact": {"tl": "Kapag malinaw at walang ilaw ng lungsod, makikita ang Milky Way bilang isang malabong guhit ng liwanag na bumabagtas sa langit — iyon ay ang gilid ng ating galaxy na nakikita natin mula sa loob.", "en": "On a very clear night away from city lights, the Milky Way appears as a faint glowing band across the sky — that is the edge of our disk-shaped galaxy seen from inside it.", "bis": "Sa tin-aw nga gabii nga layo sa suga sa siyudad, makita ang Milky Way isip usa ka hanap nga guhit sa kahayag nga molabang sa langit — kana ang kilid sa atong galaxy nga makita gikan sa sulod niini."}, "source": "AAAS BSL 4A/M1a", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-medium-star-in-galaxy-g6", "domain": "EARTH_SPACE", "topic": "the Sun's place in the galaxy", "grades": [6, 7, 8], "terms": ["Araw", "Adlaw", "Sun", "katamtamang laki", "medium-sized star", "katamtaman ang gidak-on", "bituin", "bituon", "gilid", "kilid", "edge", "isa lang sa bilyon"], "fact": {"tl": "Ang ating Araw ay isang katamtamang laki na bituin na matatagpuan malayo sa gitna ng Milky Way — isa lamang ito sa daan-daang bilyong bituin sa ating galaxy.", "en": "Our Sun is a medium-sized star located far from the center of the Milky Way — just one of the hundreds of billions of stars in our galaxy.", "bis": "Ang atong Adlaw usa ka kasarangang gidak-on nga bituon nga nahimutang layo sa tunga sa Milky Way — usa lang kini sa gatusan ka bilyon nga bituon sa atong galaxy."}, "source": "AAAS BSL 4A/M1a", "generator": "claude-workflow", "reviewed": false},
  {"id": "universe-many-galaxies-g6", "domain": "EARTH_SPACE", "topic": "billions of galaxies in the universe", "grades": [6, 7, 8], "terms": ["universe", "uniberso", "sansinukob", "kalibutan", "bilyon-bilyong galaxy", "bilyon ka galaxy", "billions of galaxies", "marami", "daghan", "napakalawak", "lapad kaayo"], "fact": {"tl": "Ang sansinukob ay naglalaman ng bilyon-bilyong galaxy, at ang bawat galaxy ay may bilyon-bilyon ding bituin.", "en": "The universe contains many billions of galaxies, and each galaxy itself contains many billions of stars.", "bis": "Ang uniberso adunay bilyon-bilyon ka galaxy, ug ang matag galaxy adunay bilyon-bilyon usab ka bituon."}, "source": "AAAS BSL 4A/M1bc", "generator": "claude-workflow", "reviewed": false},
  {"id": "galaxies-look-fuzzy-g6", "domain": "EARTH_SPACE", "topic": "distant galaxies look like fuzzy spots", "grades": [6, 7, 8], "terms": ["galaxy", "galaksi", "malabong batik", "hanap nga tulbok", "fuzzy spot", "malabo", "hanap", "napakalayo", "layo kaayo", "very far", "teleskopyo", "telescope"], "fact": {"tl": "Napakalayo ng ibang galaxy kaya kahit ang pinakamalapit sa kanila ay mukhang isang malabong batik lamang sa mata, at kailangan ng teleskopyo para makita nang mas malinaw.", "en": "Other galaxies are so far away that even the closest one looks like a dim, fuzzy spot to the naked eye, and a telescope is needed to see it more clearly.", "bis": "Layo kaayo ang ubang galaxy mao nga bisan ang labing duol kanila morag hanap nga tulbok lang sa mata, ug kinahanglan og teleskopyo aron makita kini nga mas tin-aw."}, "source": "AAAS BSL 4A/M1bc", "generator": "claude-workflow", "reviewed": false},
  {"id": "light-year-distance-g7", "domain": "EARTH_SPACE", "topic": "a light-year is a distance not a time", "grades": [7, 8, 9], "terms": ["light-year", "liwanag-taon", "tuig-kahayag", "distansya", "gilay-on", "layo", "isang taon", "usa ka tuig", "naglalakbay ang liwanag", "mobaktas ang kahayag", "hindi oras", "dili oras"], "fact": {"tl": "Ang light-year (liwanag-taon) ay sukat ng distansya, hindi oras — ito ang layong nalalakbay ng liwanag sa loob ng isang taon, mga 9.5 trilyong kilometro.", "en": "A light-year is a measure of distance, not time — it is how far light travels in one year, about 9.5 trillion kilometers.", "bis": "Ang light-year (tuig-kahayag) usa ka sukod sa gilay-on, dili oras — mao kini ang kalayo nga mabaktas sa kahayag sulod sa usa ka tuig, mga 9.5 ka trilyon nga kilometro."}, "source": "AAAS BSL 4A/M2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "starlight-from-the-past-g7", "domain": "EARTH_SPACE", "topic": "seeing stars and galaxies as they were in the past", "grades": [7, 8, 9], "terms": ["nakaraan", "nakalabay", "past", "luma na", "daan na", "ilaw ng bituin", "kahayag sa bituon", "naglakbay", "nibaktas", "bilyong taon", "bilyon ka tuig", "looking back in time"], "fact": {"tl": "Ang liwanag ng malalayong galaxy ay umaabot sa atin matapos maglakbay nang bilyong taon, kaya kapag tinitingnan natin ang mga ito, nakikita natin sila kung paano sila noong matagal nang nakaraan.", "en": "Light from distant galaxies reaches us after traveling for billions of years, so when we look at them we see them as they were long ago in the past.", "bis": "Ang kahayag sa layo nga mga galaxy moabot kanato human mibaktas og bilyon ka tuig, busa kon tan-awon nato sila, makita nato sila sama sa ilang kahimtang kaniadto."}, "source": "AAAS BSL 4A/M2", "generator": "claude-workflow", "reviewed": false},
  {"id": "universe-age-g8", "domain": "EARTH_SPACE", "topic": "the age of the universe", "grades": [8, 9, 10], "terms": ["edad ng uniberso", "edad sa uniberso", "age of the universe", "13.8 bilyong taon", "13.8 ka bilyon ka tuig", "napakatanda", "tigulang kaayo", "luma", "daan", "ten billion years"], "fact": {"tl": "Ayon sa siyentipikong ebidensya, ang sansinukob ay mahigit sampung bilyong taon na ang edad — mga 13.8 bilyong taon.", "en": "Based on scientific evidence, the universe is estimated to be over ten billion years old — about 13.8 billion years.", "bis": "Sumala sa siyentipikong ebidensiya, ang uniberso kapin na sa napulo ka bilyon ka tuig ang edad — mga 13.8 ka bilyon ka tuig."}, "source": "AAAS BSL 4A/H2ab", "generator": "claude-workflow", "reviewed": false},
  {"id": "big-bang-expansion-g8", "domain": "EARTH_SPACE", "topic": "the Big Bang and the expanding universe", "grades": [8, 9, 10], "terms": ["Big Bang", "pagsabog", "pagbuto", "nagsimula", "nagsugod", "lumawak", "nilapad", "mainit at masinsing", "init ug siksik", "expanded", "expanding universe", "lumalawak"], "fact": {"tl": "Ayon sa kasalukuyang teorya, ang buong sansinukob ay lumawak nang biglaan mula sa isang napakainit at masinsing na simula na tinatawag na Big Bang, at patuloy pa itong lumalawak ngayon.", "en": "The current theory is that the entire universe expanded suddenly from a very hot, dense beginning called the Big Bang, and it is still expanding today.", "bis": "Sumala sa kasamtangang teorya, ang tibuok uniberso milapad nga kalit gikan sa init kaayo ug siksik nga sinugdanan nga gitawag og Big Bang, ug nagpadayon kini sa paglapad karon."}, "source": "AAAS BSL 4A/H2ab", "generator": "claude-workflow", "reviewed": false},
  {"id": "nebula-star-nursery-g7", "domain": "EARTH_SPACE", "topic": "nebula as a cloud of gas and dust", "grades": [7, 8, 9], "terms": ["nebula", "ulap ng gas", "panganod sa gas", "alikabok", "abog", "gas and dust cloud", "kapanganakan ng bituin", "natawhan sa bituon", "kalawakan", "kawanangan", "star nursery"], "fact": {"tl": "Ang nebula ay isang napakalaking ulap ng gas at alikabok sa kalawakan, at sa loob ng ilang nebula, isinisilang ang mga bagong bituin.", "en": "A nebula is a huge cloud of gas and dust in space, and inside some nebulas new stars are born.", "bis": "Ang nebula usa ka dako kaayong panganod sa gas ug abog sa kawanangan, ug sa sulod sa pipila ka nebula, matawo ang bag-ong mga bituon."}, "source": "AAAS BSL 4A/H2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "stars-born-from-gas-g8", "domain": "EARTH_SPACE", "topic": "how stars form from gas clouds", "grades": [8, 9, 10], "terms": ["pagkabuo ng bituin", "pagporma sa bituon", "star formation", "grabidad", "gravity", "ulap ng gas", "panganod sa gas", "nagdikit", "nagtapok", "nuclear fusion", "init at liwanag", "init ug kahayag"], "fact": {"tl": "Ang mga bituin ay nabubuo kapag hinihila ng grabidad ang ulap ng gas hanggang sumikip at uminit ito nang sobra para magsimula ang nuclear fusion, na siyang nagbibigay sa bituin ng init at liwanag.", "en": "Stars form when gravity pulls a cloud of gas together until it becomes so hot and dense that nuclear fusion begins, which gives the star its heat and light.", "bis": "Ang mga bituon maporma kon birahon sa grabidad ang panganod sa gas hangtod nga kini moinit ug mosiksik pag-ayo aron magsugod ang nuclear fusion, nga maoy mohatag sa bituon og kainit ug kahayag."}, "source": "AAAS BSL 4A/H2", "generator": "claude-workflow", "reviewed": false},
  {"id": "supernova-heavy-elements-g9", "domain": "EARTH_SPACE", "topic": "exploding stars make heavy elements", "grades": [9, 10], "terms": ["supernova", "pagsabog ng bituin", "pagbuto sa bituon", "exploding star", "mabibigat na elemento", "bug-at nga elemento", "heavy elements", "bagong bituin", "bag-ong bituon", "bakal", "puthaw", "planeta"], "fact": {"tl": "Kapag sumabog ang ilang malalaking bituin (tinatawag na supernova), naglalabas sila ng mga mabibigat na elemento tulad ng bakal, na maaaring mabuo ulit sa bagong bituin at planeta.", "en": "When some large stars explode (called a supernova), they spread out heavy elements like iron, which can later form into new stars and planets.", "bis": "Kon mobuto ang pipila ka dagkong bituon (gitawag og supernova), mobuga sila og bug-at nga mga elemento sama sa puthaw, nga mahimong maporma pag-usab ngadto sa bag-ong mga bituon ug planeta."}, "source": "AAAS BSL 4A/H2", "generator": "claude-workflow", "reviewed": false},
  {"id": "we-are-stardust-g9", "domain": "EARTH_SPACE", "topic": "atoms in our bodies came from stars", "grades": [9, 10], "terms": ["stardust", "alikabok ng bituin", "abog sa bituon", "elemento sa katawan", "elemento sa lawas", "carbon", "oxygen", "ginawa sa loob ng bituin", "gibuhat sa sulod sa bituon", "atom", "we are made of stars"], "fact": {"tl": "Ang maraming elemento sa ating katawan, tulad ng carbon at oxygen, ay unang nagawa sa loob ng mga bituin matagal nang panahon — kaya sinasabing tayo ay gawa sa alikabok ng bituin.", "en": "Many of the elements in our bodies, like carbon and oxygen, were first made inside stars long ago — so it is said that we are made of stardust.", "bis": "Daghan sa mga elemento sa atong lawas, sama sa carbon ug oxygen, una nga gibuhat sa sulod sa mga bituon kaniadto — busa giingon nga gibuhat kita gikan sa abog sa bituon."}, "source": "AAAS BSL 4A/H2", "generator": "claude-workflow", "reviewed": false},
  {"id": "black-hole-strong-gravity-g8", "domain": "EARTH_SPACE", "topic": "what a black hole is", "grades": [8, 9, 10], "terms": ["black hole", "itim na butas", "itom nga lungag", "grabidad", "gravity", "napakalakas", "kusgan kaayo", "liwanag", "kahayag", "hindi makatakas", "dili makaikyas", "light cannot escape"], "fact": {"tl": "Ang black hole ay isang rehiyon sa kalawakan na napakalakas ng grabidad kaya kahit ang liwanag ay hindi makatakas mula rito.", "en": "A black hole is a region in space with gravity so strong that not even light can escape from it.", "bis": "Ang black hole usa ka dapit sa kawanangan nga kusgan kaayo ang grabidad mao nga bisan ang kahayag dili makaikyas gikan niini."}, "source": "encyclopedia-stable consensus; AAAS BSL 4G (gravity)", "generator": "claude-workflow", "reviewed": false},
  {"id": "black-hole-from-dead-star-g9", "domain": "EARTH_SPACE", "topic": "black holes form from collapsed giant stars", "grades": [9, 10], "terms": ["black hole", "itim na butas", "itom nga lungag", "patay na bituin", "patay nga bituon", "malaking bituin", "dakong bituon", "gumuho", "nahugno", "collapse", "supernova", "namatay ang bituin"], "fact": {"tl": "Ang ilang black hole ay nabubuo kapag ang isang napakalaking bituin ay naubusan ng gatong at gumuho papasok dahil sa sariling grabidad nito.", "en": "Some black holes form when a very large star runs out of fuel and collapses inward under its own gravity.", "bis": "Ang pipila ka black hole maporma kon ang usa ka dako kaayong bituon mahurot og sugnod ug mahugno paingon sa sulod tungod sa kaugalingong grabidad niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "milky-way-center-black-hole-g9", "domain": "EARTH_SPACE", "topic": "supermassive black hole at the galaxy center", "grades": [9, 10], "terms": ["Milky Way", "sentro ng galaxy", "sentro sa galaxy", "gitna", "tunga", "supermassive black hole", "napakalaking black hole", "dako kaayong black hole", "Sagittarius A*", "umiikot", "naglibot", "center"], "fact": {"tl": "Sa gitna ng Milky Way ay may isang napakalaking black hole, at ang lahat ng bituin sa ating galaxy, kasama ang Araw, ay umiikot sa paligid ng sentrong ito.", "en": "At the center of the Milky Way there is a supermassive black hole, and all the stars in our galaxy, including the Sun, orbit around this center.", "bis": "Sa tunga sa Milky Way adunay usa ka dako kaayong black hole, ug ang tanang bituon sa atong galaxy, lakip ang Adlaw, naglibot niini nga sentro."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "galaxy-shapes-g7", "domain": "EARTH_SPACE", "topic": "different shapes of galaxies", "grades": [7, 8, 9], "terms": ["galaxy", "galaksi", "hugis", "porma", "shapes", "spiral", "elliptical", "iba't ibang anyo", "lain-laing porma", "Milky Way spiral", "magulong hugis", "irregular"], "fact": {"tl": "Hindi lahat ng galaxy ay magkakapareho ng hugis — ang ilan ay parang umiikot na spiral tulad ng Milky Way, ang iba ay bilog o hugis-itlog, at ang ilan ay walang tiyak na hugis.", "en": "Not all galaxies have the same shape — some are swirling spirals like the Milky Way, others are round or egg-shaped, and some have no regular shape.", "bis": "Dili tanang galaxy parehas og porma — ang uban morag nagtuyok nga spiral sama sa Milky Way, ang uban lingin o sama sa itlog, ug ang uban walay tinong porma."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "andromeda-nearest-big-galaxy-g8", "domain": "EARTH_SPACE", "topic": "the Andromeda galaxy", "grades": [8, 9, 10], "terms": ["Andromeda", "pinakamalapit na malaking galaxy", "labing duol nga dakong galaxy", "nearest big galaxy", "naked eye", "nakikita ng mata", "makita sa mata", "2.5 milyong taon", "2.5 ka milyon ka tuig", "kapitbahay na galaxy"], "fact": {"tl": "Ang Andromeda ang pinakamalapit na malaking galaxy sa Milky Way, at sa napakadilim na langit ay nakikita ito ng mata bilang malabong batik kahit napakalayo nito.", "en": "Andromeda is the nearest large galaxy to the Milky Way, and on a very dark sky it can be seen with the naked eye as a faint smudge even though it is very far away.", "bis": "Ang Andromeda mao ang labing duol nga dakong galaxy sa Milky Way, ug sa ngitngit kaayong langit makita kini sa mata isip hanap nga batik bisan layo kaayo kini."}, "source": "encyclopedia-stable consensus; AAAS BSL 4A/M1bc", "generator": "claude-workflow", "reviewed": false},
  {"id": "stars-different-colors-g6", "domain": "EARTH_SPACE", "topic": "stars come in different colors", "grades": [6, 7, 8], "terms": ["bituin", "bituon", "kulay", "kolor", "color", "mapula", "pula", "asul", "blue", "red", "puti", "init", "kainit", "temperatura", "mainit na bituin"], "fact": {"tl": "Ang mga bituin ay may iba't ibang kulay — ang mga asul na bituin ang pinakamainit, samantalang ang mga pula ang mas malamig.", "en": "Stars come in different colors — blue stars are the hottest, while red stars are cooler.", "bis": "Ang mga bituon adunay lain-laing kolor — ang asul nga mga bituon ang labing init, samtang ang pula mas bugnaw."}, "source": "AAAS BSL 4A/P1; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-light-eight-minutes-g6", "domain": "EARTH_SPACE", "topic": "sunlight takes minutes, starlight takes years", "grades": [6, 7, 8], "terms": ["liwanag ng Araw", "kahayag sa Adlaw", "sunlight", "walong minuto", "walo ka minuto", "eight minutes", "bituin", "bituon", "ilang taon", "pipila ka tuig", "napakalayo", "layo kaayo", "umaabot"], "fact": {"tl": "Ang liwanag ng Araw ay umaabot sa Earth sa loob lang ng mga walong minuto, ngunit ang liwanag mula sa kabilang bituin ay umaabot ng ilang taon dahil mas malayo ang mga ito.", "en": "Sunlight reaches Earth in only about eight minutes, but light from other stars takes years to arrive because they are much farther away.", "bis": "Ang kahayag sa Adlaw moabot sa Yuta sulod lang sa mga walo ka minuto, apan ang kahayag gikan sa ubang bituon moabot og pipila ka tuig kay mas layo man kini."}, "source": "AAAS BSL 4A/M2abc", "generator": "claude-workflow", "reviewed": false},
  {"id": "constellation-star-patterns-g5", "domain": "EARTH_SPACE", "topic": "constellations are patterns of stars", "grades": [5, 6, 7], "terms": ["konstelasyon", "constellation", "pattern ng bituin", "han-ay sa bituon", "star pattern", "hugis", "porma", "langit", "panahon", "season", "naglalakbay", "nagbalhin", "larawan sa langit"], "fact": {"tl": "Ang konstelasyon ay isang pattern ng mga bituin na parang gumuguhit ng larawan sa langit, at ang parehong pattern ay nakikitang gumagalaw sa langit tuwing gabi.", "en": "A constellation is a pattern of stars that seems to draw a picture in the sky, and the same pattern appears to move across the sky each night.", "bis": "Ang konstelasyon usa ka han-ay sa mga bituon nga morag nagdrowing og hulagway sa langit, ug ang samang han-ay makita nga molihok sa langit matag gabii."}, "source": "AAAS BSL 4A/E1", "generator": "claude-workflow", "reviewed": false},
  {"id": "universe-mostly-empty-space-g7", "domain": "EARTH_SPACE", "topic": "the universe is mostly empty space", "grades": [7, 8, 9], "terms": ["uniberso", "universe", "kalawakan", "kawanangan", "puwang", "haw-ang", "empty space", "napakalaki ang pagitan", "layo kaayo ang gilay-on", "bituin", "bituon", "malayo sa isa't isa"], "fact": {"tl": "Ang sansinukob ay halos puro puwang lamang, dahil napakalayo ng mga bituin at galaxy sa isa't isa kumpara sa laki nila.", "en": "The universe is mostly empty space, because stars and galaxies are extremely far apart compared to how big they are.", "bis": "Ang uniberso halos puro haw-ang lang, kay layo kaayo ang mga bituon ug galaxy sa usag usa kumpara sa ilang gidak-on."}, "source": "AAAS BSL 4A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "telescope-reveals-faint-objects-g6", "domain": "EARTH_SPACE", "topic": "telescopes reveal more stars and galaxies", "grades": [6, 7, 8], "terms": ["teleskopyo", "telescope", "mas maraming bituin", "mas daghang bituon", "more stars", "malabo", "hanap", "malayo", "layo", "nagpapalaki", "nagpadako", "magnify", "nakikita", "makita"], "fact": {"tl": "Ang teleskopyo ay nagpapakita ng mas maraming bituin at galaxy na hindi kayang makita ng mata lamang, dahil tinitipon nito ang mahinang liwanag mula sa malalayong bagay.", "en": "A telescope shows far more stars and galaxies than the eye alone can see, because it gathers the faint light from distant objects.", "bis": "Ang teleskopyo magpakita og mas daghang bituon ug galaxy nga dili makita sa mata lamang, kay magtigom kini sa huyang nga kahayag gikan sa layo nga mga butang."}, "source": "AAAS BSL 4A/E2", "generator": "claude-workflow", "reviewed": false},
  {"id": "galaxies-held-by-gravity-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "gravity holds galaxies together", "grades": [7, 8, 9], "terms": ["grabidad", "gravity", "humihila", "nagbira", "pinagdidikit", "gihiusa", "holds together", "galaxy", "galaksi", "umiikot", "naglibot", "bituin", "bituon", "sentro"], "fact": {"tl": "Ang grabidad ang humihila at nagpapanatili sa bilyon-bilyong bituin sa loob ng isang galaxy, kaya umiikot sila sa paligid ng sentro nito sa halip na lumipad palayo.", "en": "Gravity pulls and holds the billions of stars in a galaxy together, so they orbit around its center instead of flying apart.", "bis": "Ang grabidad maoy mobira ug mohiusa sa bilyon-bilyon ka bituon sulod sa usa ka galaxy, mao nga naglibot sila sa sentro niini imbis nga molupad palayo."}, "source": "AAAS BSL 4G; NRC ESS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "milky-way-billions-of-stars-g6", "domain": "EARTH_SPACE", "topic": "how many stars are in the Milky Way", "grades": [6, 7, 8], "terms": ["Milky Way", "ilang bituin", "pila ka bituon", "daan-daang bilyon", "gatusan ka bilyon", "hundreds of billions", "marami", "daghan", "hindi mabilang", "dili maihap", "bituin", "bituon"], "fact": {"tl": "Ang Milky Way ay may daan-daang bilyong bituin — napakarami kaya hindi kayang bilangin ng isang tao ang mga ito sa buong buhay niya.", "en": "The Milky Way has hundreds of billions of stars — so many that a person could never count them all in a whole lifetime.", "bis": "Ang Milky Way adunay gatusan ka bilyon nga bituon — daghan kaayo nga dili gyud maihap sa usa ka tawo sa tibuok niyang kinabuhi."}, "source": "AAAS BSL 4A/M1bc", "generator": "claude-workflow", "reviewed": false},
  {"id": "galaxies-move-apart-g9", "domain": "EARTH_SPACE", "topic": "galaxies are moving apart as the universe expands", "grades": [9, 10], "terms": ["galaxy", "galaksi", "lumalayo", "nagkalayo", "naglayo", "moving apart", "lumalawak na uniberso", "nagalapad nga uniberso", "expanding", "Big Bang", "patuloy na lumalaki", "nagpadayon paglapad"], "fact": {"tl": "Habang lumalawak ang sansinukob, halos lahat ng malalayong galaxy ay unti-unting lumalayo sa atin — isa itong patunay na nagsimula ang uniberso sa Big Bang.", "en": "As the universe expands, almost all distant galaxies are slowly moving away from us — this is evidence that the universe began with the Big Bang.", "bis": "Samtang nagalapad ang uniberso, halos tanang layo nga galaxy hinay-hinay nga naglayo kanato — usa kini ka pamatuod nga ang uniberso nagsugod sa Big Bang."}, "source": "AAAS BSL 4A/H2ab", "generator": "claude-workflow", "reviewed": false},
  {"id": "what-is-rocket-g4", "domain": "EARTH_SPACE", "topic": "what is a rocket", "grades": [4, 5], "terms": ["rocket", "rockets", "spacecraft", "launch", "blast off", "kohete", "raketa", "spaceship", "sasakyang panghimpapawid", "naglulunsad", "umaakyat", "naglilipad", "espasyo", "kalawakan", "kawanangan", "molupad", "naglupad", "naglansad"], "fact": {"tl": "Ang rocket ay isang makina na sumusunog ng panggatong para makagawa ng malakas na pwersa na nagtutulak dito pataas, kaya kaya nitong lumabas ng Earth papunta sa kalawakan.", "en": "A rocket is a machine that burns fuel to make a powerful force pushing it upward, so it can leave Earth and travel into space.", "bis": "Ang rocket usa ka makina nga nagasunog og gasolina aron makahimo og kusog nga pwersa nga magtulod niini pataas, mao nga makagawas kini sa Earth padulong sa kawanangan."}, "source": "encyclopedia-stable consensus; NRC ETS1 engineering", "generator": "claude-workflow", "reviewed": false},
  {"id": "rocket-needs-no-air-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "why rockets work in space", "grades": [6, 7], "terms": ["rocket engine", "rockets", "no air", "vacuum", "carry oxygen", "oxidizer", "espasyo", "kalawakan", "walang hangin", "nagdadala ng oxygen", "makina ng rocket", "bakwum", "tumutulak", "kawanangan", "walay hangin", "nagdala og oxygen", "nagtulod"], "fact": {"tl": "Gumagana ang rocket kahit sa kalawakan na walang hangin dahil dala-dala nito ang sariling oxygen para mapasunog ang panggatong, at tumutulak ito sa pamamagitan ng paglalabas ng gas, hindi sa pamamagitan ng pagtulak sa hangin.", "en": "A rocket works even in airless space because it carries its own oxygen to burn its fuel, and it moves by pushing out gas, not by pushing against air.", "bis": "Ang rocket molihok bisan sa kawanangan nga walay hangin tungod kay nagdala kini sa kaugalingong oxygen aron masunog ang gasolina, ug molihok kini pinaagi sa pagpagawas og gas, dili pinaagi sa pagtulod sa hangin."}, "source": "encyclopedia-stable consensus; NRC PS2 forces", "generator": "claude-workflow", "reviewed": false},
  {"id": "what-is-astronaut-g3", "domain": "EARTH_SPACE", "topic": "what is an astronaut", "grades": [3, 4], "terms": ["astronaut", "astronauts", "spaceman", "space suit", "astronawt", "kalawakan", "espasyo", "naglalakbay sa kalawakan", "manlalakbay", "kawanangan", "tawo nga moadto sa kawanangan", "spacesuit", "magbiyahe", "nagbiyahe"], "fact": {"tl": "Ang astronaut ay isang taong sinanay para maglakbay at magtrabaho sa kalawakan, na nakasuot ng espesyal na space suit para mabuhay sa labas ng Earth.", "en": "An astronaut is a person trained to travel and work in space, wearing a special space suit to stay alive away from Earth.", "bis": "Ang astronaut usa ka tawo nga gibansay aron mobiyahe ug magtrabaho sa kawanangan, nga nagsul-ob og espesyal nga space suit aron mabuhi sa gawas sa Earth."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "spacesuit-why-needed-g5", "domain": "EARTH_SPACE", "topic": "why astronauts wear space suits", "grades": [5, 6], "terms": ["space suit", "spacesuit", "oxygen tank", "astronaut", "pressure", "damit pangkalawakan", "oxygen", "hangin", "init at lamig", "presyon", "espasyo", "sul-ob", "init ug bugnaw", "nagsul-ob", "tangke sa oxygen"], "fact": {"tl": "Nagsusuot ng space suit ang astronaut dahil nagbibigay ito ng oxygen na maaaring hingahin, nagpapanatili ng tamang presyon, at nagpoprotekta sa kanila mula sa matinding init at lamig ng kalawakan.", "en": "Astronauts wear a space suit because it gives them oxygen to breathe, keeps the right pressure around their body, and protects them from the extreme heat and cold of space.", "bis": "Ang astronaut nagsul-ob og space suit tungod kay naghatag kini og oxygen nga ilang ginhawaon, nagtipig sa hustong presyon, ug nagpanalipod kanila gikan sa hilabihang init ug bugnaw sa kawanangan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "astronauts-eat-sleep-g4", "domain": "EARTH_SPACE", "topic": "how astronauts eat and sleep in space", "grades": [4, 5], "terms": ["astronaut", "eat in space", "sleep", "float", "weightless", "kumakain sa kalawakan", "natutulog", "lumulutang", "pagkain", "nakatali", "espasyo", "mokaon", "matulog", "molutaw", "pagkaon", "gigapos", "naglutaw"], "fact": {"tl": "Sa kalawakan, lumulutang ang lahat dahil sa pagiging timbang-wala, kaya kumakain ang mga astronaut ng pagkaing nakabalot nang mabuti at natutulog sila sa mga sleeping bag na nakatali para hindi sila lumutang habang natutulog.", "en": "In space everything floats because of weightlessness, so astronauts eat specially packed food and sleep in sleeping bags strapped down so they don't drift away while sleeping.", "bis": "Sa kawanangan ang tanan molutaw tungod sa kawalay-gibug-aton, mao nga ang mga astronaut mokaon og pagkaon nga giputos pag-ayo ug matulog sa sleeping bag nga gigapos aron dili sila molutaw samtang natulog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "what-is-iss-g5", "domain": "EARTH_SPACE", "topic": "the International Space Station", "grades": [5, 6], "terms": ["International Space Station", "ISS", "space station", "orbit", "astronauts live", "istasyong pangkalawakan", "umiikot sa Earth", "nakatira", "laboratoryo", "espasyo", "estasyon sa kawanangan", "naglibot sa Earth", "nagpuyo", "orbita", "naglibut"], "fact": {"tl": "Ang International Space Station (ISS) ay isang malaking istasyong pangkalawakan na umiikot sa Earth, kung saan nakatira at nagsasaliksik ang mga astronaut mula iba't ibang bansa.", "en": "The International Space Station (ISS) is a large space station orbiting Earth, where astronauts from different countries live and do science experiments.", "bis": "Ang International Space Station (ISS) usa ka dako nga estasyon sa kawanangan nga naglibot sa Earth, diin nagpuyo ug nagsiksik ang mga astronaut gikan sa lain-laing nasud."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "iss-orbit-speed-g6", "domain": "EARTH_SPACE", "topic": "how fast the ISS orbits Earth", "grades": [6, 7], "terms": ["ISS", "space station", "16 sunrises", "orbit", "90 minutes", "umiikot", "isang oras kalahati", "araw-gabi", "bilis", "espasyo", "naglibot", "16 ka subangan", "kapaspas", "90 minuto", "naglibut"], "fact": {"tl": "Napakabilis ng ISS na nakakaikot ito sa Earth nang isang beses tuwing humigit-kumulang 90 minuto, kaya nakakakita ang mga astronaut ng mga 16 na pagsikat at paglubog ng araw bawat araw.", "en": "The ISS moves so fast that it circles Earth once about every 90 minutes, so astronauts see roughly 16 sunrises and sunsets each day.", "bis": "Paspas kaayo ang ISS nga makalibot kini sa Earth kausa matag mga 90 minuto, mao nga ang mga astronaut makakita og mga 16 ka pagsubang ug pagsalop sa adlaw kada adlaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "what-is-satellite-g4", "domain": "EARTH_SPACE", "topic": "what is a satellite", "grades": [4, 5], "terms": ["satellite", "satellites", "orbit Earth", "man-made", "satelayt", "umiikot sa Earth", "gawa ng tao", "espasyo", "naglilibot", "binuhat sa tao", "naglibot", "orbita", "naglibut"], "fact": {"tl": "Ang satellite ay isang makinang gawa ng tao na umiikot sa Earth sa kalawakan para mangalap o magpadala ng impormasyon, tulad ng senyales ng telepono o larawan ng panahon.", "en": "A satellite is a human-made machine that orbits Earth in space to gather or send information, such as phone signals or weather pictures.", "bis": "Ang satellite usa ka makina nga binuhat sa tawo nga naglibot sa Earth sa kawanangan aron magkuha o magpadala og impormasyon, sama sa signal sa telepono o hulagway sa panahon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "satellites-uses-g6", "domain": "EARTH_SPACE", "topic": "what satellites are used for", "grades": [6, 7], "terms": ["satellite", "GPS", "weather satellite", "communication", "uses", "gamit ng satellite", "panahon", "komunikasyon", "telepono", "mapa", "espasyo", "gamit sa satellite", "gigamit", "bagyo"], "fact": {"tl": "Ginagamit ang mga satellite para sa maraming bagay: para sa GPS at mapa, para sa tawag at internet, para sa telebisyon, at para sa pagmamasid ng panahon at bagyo mula sa itaas.", "en": "Satellites are used for many things: for GPS and maps, for phone calls and internet, for television, and for watching weather and storms from above.", "bis": "Ang mga satellite gigamit alang sa daghang butang: alang sa GPS ug mapa, alang sa tawag ug internet, alang sa telebisyon, ug alang sa pagbantay sa panahon ug bagyo gikan sa itaas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "moon-is-natural-satellite-g5", "domain": "EARTH_SPACE", "topic": "the Moon is Earth's natural satellite", "grades": [5, 6], "terms": ["Moon", "natural satellite", "orbit", "buwan", "likas na satellite", "umiikot sa Earth", "natural", "espasyo", "bulan", "naglibot sa Earth", "kinaiyanhong satellite", "naglibut"], "fact": {"tl": "Ang Buwan ang likas na satellite ng Earth, dahil ito ang natural na bagay sa kalawakan na patuloy na umiikot sa ating planeta.", "en": "The Moon is Earth's natural satellite, because it is the natural object in space that keeps orbiting our planet.", "bis": "Ang Bulan mao ang kinaiyanhong satellite sa Earth, tungod kay kini ang natural nga butang sa kawanangan nga padayong naglibot sa atong planeta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "first-moon-landing-g5", "domain": "EARTH_SPACE", "topic": "the first Moon landing", "grades": [5, 6], "terms": ["Moon landing", "Apollo 11", "Neil Armstrong", "1969", "first person on the Moon", "pagbaba sa Buwan", "unang tao", "1969", "Apollo", "espasyo", "pagtugpa sa Bulan", "unang tawo", "naglakad sa Bulan", "naglakaw"], "fact": {"tl": "Noong 1969, ang astronaut na si Neil Armstrong ang naging unang tao na nakatapak sa Buwan sa pamamagitan ng misyong Apollo 11 ng Estados Unidos.", "en": "In 1969, the astronaut Neil Armstrong became the first person to step on the Moon, through the United States' Apollo 11 mission.", "bis": "Niadtong 1969, ang astronaut nga si Neil Armstrong nahimong unang tawo nga nakatamak sa Bulan, pinaagi sa misyon nga Apollo 11 sa Estados Unidos."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "footprints-stay-on-moon-g5", "domain": "EARTH_SPACE", "topic": "why footprints stay on the Moon", "grades": [5, 6], "terms": ["footprints on Moon", "no wind", "no air", "Moon", "bakas ng paa", "walang hangin", "Buwan", "nananatili", "espasyo", "tunob", "walay hangin", "Bulan", "nagpabilin", "tunob sa Bulan", "nabilin"], "fact": {"tl": "Nananatili sa Buwan ang mga bakas ng paa ng mga astronaut nang napakatagal dahil walang hangin o tubig doon na maaaring magpapunas o magpalipad sa mga ito.", "en": "The astronauts' footprints stay on the Moon for a very long time because there is no wind or water there to wipe or blow them away.", "bis": "Ang mga tunob sa tiil sa mga astronaut magpabilin sa Bulan og dugay kaayo tungod kay walay hangin o tubig didto nga makapapas o makapalid niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "weight-on-moon-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "why astronauts bounce on the Moon", "grades": [6, 7], "terms": ["Moon gravity", "jump higher", "lighter on Moon", "one sixth", "bigat sa Buwan", "mas magaan", "lumukso", "gravity", "espasyo", "gibug-aton sa Bulan", "mas gaan", "molukso", "grabidad", "naglukso"], "fact": {"tl": "Mas mahina ang gravity sa Buwan kaysa sa Earth—mga isa lang sa anim—kaya mas magaan ang pakiramdam ng mga astronaut at kaya nilang lumukso nang mas mataas doon.", "en": "Gravity on the Moon is much weaker than on Earth—only about one-sixth—so astronauts feel much lighter and can jump much higher there.", "bis": "Ang grabidad sa Bulan mas huyang kaysa sa Earth—mga ikaunom lang—mao nga ang mga astronaut mas gaan og bati ug makalukso og mas taas didto."}, "source": "encyclopedia-stable consensus; NRC PS2 gravity", "generator": "claude-workflow", "reviewed": false},
  {"id": "what-is-space-probe-g5", "domain": "EARTH_SPACE", "topic": "what is a space probe", "grades": [5, 6], "terms": ["space probe", "robot", "no people", "explore planets", "probe", "robotikong sasakyan", "walang tao", "saliksik", "planeta", "espasyo", "robot nga sakyanan", "walay tawo", "magsusi", "nagsusi"], "fact": {"tl": "Ang space probe ay isang robotikong sasakyang pangkalawakan na walang taong sakay, na ipinapadala para mag-imbestiga ng malalayong planeta at iba pang bagay na delikado o napakalayo para puntahan ng tao.", "en": "A space probe is a robotic spacecraft with no people on board, sent to explore faraway planets and other places too dangerous or too distant for humans to visit.", "bis": "Ang space probe usa ka robot nga sakyanan sa kawanangan nga walay tawo nga sakay, gipadala aron magsusi sa layo nga mga planeta ug uban pang dapit nga delikado o layo kaayo nga adtoon sa tawo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "voyager-probe-g6", "domain": "EARTH_SPACE", "topic": "the Voyager probes", "grades": [6, 7], "terms": ["Voyager", "space probe", "farthest", "outer planets", "interstellar", "pinakamalayo", "lumipad", "panlabas na planeta", "espasyo", "probe", "labing layo", "naglupad", "gawas nga planeta", "kawanangan"], "fact": {"tl": "Ang Voyager 1 at Voyager 2 ay mga space probe na inilunsad noong 1977; sila ang mga gawa ng tao na umabot sa pinakamalayo, at lumipad sila malapit sa malalaking planeta sa labas ng ating Solar System.", "en": "Voyager 1 and Voyager 2 are space probes launched in 1977; they are the farthest-traveling human-made objects, and they flew close to the giant outer planets of our Solar System.", "bis": "Ang Voyager 1 ug Voyager 2 mga space probe nga gilunsad niadtong 1977; sila ang labing layo nga nakaabot nga mga binuhat sa tawo, ug milupad sila duol sa dagkong mga planeta sa gawas sa atong Solar System."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mars-rover-g5", "domain": "EARTH_SPACE", "topic": "Mars rovers", "grades": [5, 6], "terms": ["Mars rover", "robot car", "explore Mars", "Mars", "robotikong sasakyan", "Marte", "gumagalaw", "ginagalugad", "espasyo", "robot nga awto", "nagsuroy", "nagsusi", "naglatagaw"], "fact": {"tl": "Ang Mars rover ay isang robotikong sasakyan na gumagalaw sa ibabaw ng Mars, kumukuha ng larawan at sumusuri ng mga bato para malaman natin ang hitsura ng planeta.", "en": "A Mars rover is a robotic vehicle that drives across the surface of Mars, taking pictures and studying rocks so we can learn what the planet is like.", "bis": "Ang Mars rover usa ka robot nga sakyanan nga nagsuroy sa ibabaw sa Mars, nagkuha og hulagway ug nagtuon sa mga bato aron mahibaw-an nato kon unsa ang dagway sa planeta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "what-is-space-telescope-g5", "domain": "EARTH_SPACE", "topic": "what is a space telescope", "grades": [5, 6], "terms": ["space telescope", "Hubble", "above atmosphere", "see far", "teleskopyong pangkalawakan", "nakikita ang malayo", "bituin", "galaxy", "espasyo", "teleskopyo sa kawanangan", "makakita og layo", "bituon", "galaksiya"], "fact": {"tl": "Ang space telescope ay isang malaking teleskopyong inilagay sa kalawakan sa labas ng atmospera ng Earth, kaya mas malinaw nitong nakikita ang malalayong bituin at galaxy nang walang halong ulap o usok.", "en": "A space telescope is a large telescope placed in space above Earth's atmosphere, so it can see distant stars and galaxies much more clearly, without clouds or haze in the way.", "bis": "Ang space telescope usa ka dako nga teleskopyo nga gibutang sa kawanangan ibabaw sa atmospera sa Earth, mao nga mas tin-aw niining makita ang layo nga mga bituon ug galaksiya, nga walay panganod o aso nga makababag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hubble-telescope-g6", "domain": "EARTH_SPACE", "topic": "the Hubble Space Telescope", "grades": [6, 7], "terms": ["Hubble Space Telescope", "famous telescope", "deep space photos", "Hubble", "teleskopyo", "larawan ng kalawakan", "malalim na espasyo", "litrato sa kawanangan", "sikat", "hulagway", "inila"], "fact": {"tl": "Ang Hubble Space Telescope ay isa sa pinakatanyag na space telescope; mula nang ilunsad ito noong 1990, kumuha na ito ng napakagagandang larawan ng malalayong bituin at galaxy.", "en": "The Hubble Space Telescope is one of the most famous space telescopes; since it was launched in 1990, it has taken beautiful pictures of distant stars and galaxies.", "bis": "Ang Hubble Space Telescope usa sa labing inila nga space telescope; sukad kini gilunsad niadtong 1990, nakakuha na kini og nindot kaayo nga mga hulagway sa layo nga mga bituon ug galaksiya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "what-is-orbit-g5", "domain": "EARTH_SPACE", "topic": "what is an orbit", "grades": [5, 6], "terms": ["orbit", "go around", "gravity", "circle", "umiikot", "paikot", "gravity", "satellite", "espasyo", "orbita", "naglibot", "grabidad", "naglibut", "molibot"], "fact": {"tl": "Ang orbit ay ang paikot na landas na sinusundan ng isang bagay habang umiikot ito sa palibot ng isa pang bagay sa kalawakan, na hinihila ng gravity—tulad ng satellite na umiikot sa Earth.", "en": "An orbit is the curved path an object follows as it goes around another object in space, held in by gravity—like a satellite circling Earth.", "bis": "Ang orbit mao ang likoanan nga agianan nga ginasunod sa usa ka butang samtang naglibot kini sa laing butang sa kawanangan, nga gibira sa grabidad—sama sa satellite nga naglibot sa Earth."}, "source": "encyclopedia-stable consensus; NRC ESS1 gravity", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-satellites-dont-fall-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "why satellites don't fall to Earth", "grades": [7, 8], "terms": ["satellite stay up", "falling", "fast sideways", "orbit", "gravity", "hindi nahuhulog", "bilis", "patagilid", "umiikot", "espasyo", "dili matagak", "paspas", "kilid", "naglibot", "grabidad", "wala matagak"], "fact": {"tl": "Hindi nahuhulog sa Earth ang isang satellite dahil napakabilis nito kumikilos patagilid kaya habang hinihila ito pababa ng gravity, patuloy itong 'sumasalo' sa kurba ng Earth—kaya umiikot ito sa halip na bumagsak.", "en": "A satellite does not fall to Earth because it moves so fast sideways that, as gravity pulls it down, it keeps missing the curve of the Earth—so it circles around instead of crashing.", "bis": "Ang satellite dili matagak sa Earth tungod kay paspas kaayo kini molihok pakilid mao nga samtang gibira kini paubos sa grabidad, padayon kining 'mosipyat' sa likoanan sa Earth—busa naglibot kini imbes mahagba."}, "source": "encyclopedia-stable consensus; NRC PS2 gravity and motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "first-satellite-sputnik-g6", "domain": "EARTH_SPACE", "topic": "the first artificial satellite", "grades": [6, 7], "terms": ["Sputnik", "first satellite", "1957", "space age", "unang satellite", "1957", "kasaysayan", "espasyo", "Sputnik", "sinugdan", "kawanangan", "sinugdanan"], "fact": {"tl": "Ang Sputnik 1, na inilunsad ng Soviet Union noong 1957, ang unang artipisyal na satellite na naipadala ng tao sa kalawakan, at sinimulan nito ang panahon ng pagtuklas sa espasyo.", "en": "Sputnik 1, launched by the Soviet Union in 1957, was the first artificial satellite ever sent into space, and it began the age of space exploration.", "bis": "Ang Sputnik 1, nga gilunsad sa Soviet Union niadtong 1957, mao ang unang artipisyal nga satellite nga gipadala sa tawo ngadto sa kawanangan, ug gisugdan niini ang panahon sa pagsusi sa kawanangan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "first-human-in-space-g6", "domain": "EARTH_SPACE", "topic": "the first human in space", "grades": [6, 7], "terms": ["Yuri Gagarin", "first human in space", "1961", "cosmonaut", "unang tao sa kalawakan", "1961", "espasyo", "astronaut", "unang tawo sa kawanangan", "Gagarin", "kawanangan", "naglibot"], "fact": {"tl": "Noong 1961, si Yuri Gagarin mula sa Soviet Union ang naging unang taong nakapunta sa kalawakan, na umikot nang isang beses sa Earth sakay ng kanyang spacecraft.", "en": "In 1961, Yuri Gagarin of the Soviet Union became the first human to travel into space, circling Earth once aboard his spacecraft.", "bis": "Niadtong 1961, si Yuri Gagarin gikan sa Soviet Union nahimong unang tawo nga nakaadto sa kawanangan, nga naglibot kausa sa Earth sakay sa iyang spacecraft."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "how-rockets-have-stages-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "why rockets have stages", "grades": [7, 8], "terms": ["rocket stages", "drop off", "fuel", "lighter", "bahagi ng rocket", "panggatong", "naghuhulog", "magaan", "espasyo", "bahin sa rocket", "gasolina", "gaan", "nagtangtang", "nag-drop"], "fact": {"tl": "Maraming rocket ay may mga bahagi o 'stage' na inihuhulog kapag naubos na ang panggatong, para gumaan ang natitirang rocket at mas madali itong makaakyat papunta sa kalawakan.", "en": "Many rockets are built in parts called stages that are dropped off once their fuel is used up, so the remaining rocket becomes lighter and can climb into space more easily.", "bis": "Daghang rocket gibuhat nga adunay mga bahin nga gitawag og stage nga ginatangtang kon mahurot na ang gasolina niini, aron mogaan ang nahibilin nga rocket ug mas sayon kining mosaka padulong sa kawanangan."}, "source": "encyclopedia-stable consensus; NRC ETS engineering", "generator": "claude-workflow", "reviewed": false},
  {"id": "spacecraft-reentry-heat-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "why spacecraft get hot returning to Earth", "grades": [7, 8], "terms": ["reentry", "heat shield", "friction", "spacecraft return", "init", "kuskusan", "babalik sa Earth", "espasyo", "kainit", "pagbalik sa Earth", "kalawakan", "naginit"], "fact": {"tl": "Kapag bumabalik sa Earth ang isang spacecraft, sumasagasa ito sa atmospera nang napakabilis kaya nagdudulot ng matinding init dahil sa kuskusan sa hangin, kaya kailangan nitong may panangga sa init (heat shield) para hindi masunog.", "en": "When a spacecraft returns to Earth, it plunges into the atmosphere so fast that friction with the air makes it extremely hot, so it needs a heat shield to keep from burning up.", "bis": "Kon mobalik sa Earth ang usa ka spacecraft, mosulod kini sa atmospera og paspas kaayo mao nga ang pagkuskos sa hangin makahimo niining init kaayo, busa kinahanglan kini og heat shield aron dili masunog."}, "source": "encyclopedia-stable consensus; NRC PS3 energy", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-explore-space-g5", "domain": "EARTH_SPACE", "topic": "why we explore space", "grades": [5, 6], "terms": ["why explore space", "learn", "discover", "planets", "bakit nag-eeksplora", "matuto", "tuklas", "espasyo", "ngano magsusi sa kawanangan", "magkat-on", "tuki", "kawanangan", "nagsusi"], "fact": {"tl": "Ginagalugad ng mga tao ang kalawakan para matuto tungkol sa ibang planeta, para malaman kung paano nagsimula ang mga bituin, at para tingnan kung may iba pang lugar na maaaring magkaroon ng buhay.", "en": "People explore space to learn about other planets, to find out how the stars began, and to look for places where there might be life beyond Earth.", "bis": "Ang mga tawo nagsusi sa kawanangan aron magkat-on bahin sa ubang planeta, aron mahibaw-an kon giunsa pagsugod sa mga bituon, ug aron pangitaon kon aduna pay ubang dapit nga adunay kinabuhi."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "no-sound-in-space-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "why there is no sound in space", "grades": [6, 7], "terms": ["no sound in space", "vacuum", "sound needs air", "silent", "walang tunog", "espasyo", "tunog kailangan hangin", "tahimik", "walay tingog", "kawanangan", "tingog nagkinahanglan og hangin", "hilom", "walay saba"], "fact": {"tl": "Walang tunog sa kalawakan dahil ang tunog ay kailangan ng hangin o iba pang bagay na madadaanan, at ang kalawakan ay halos walang laman na walang hangin, kaya tahimik na tahimik doon.", "en": "There is no sound in space because sound needs air or some material to travel through, and space is nearly empty with no air, so it is completely silent there.", "bis": "Walay tingog sa kawanangan tungod kay ang tingog nagkinahanglan og hangin o ubang butang nga agian, ug ang kawanangan halos walay sulod ug walay hangin, busa hilom kaayo didto."}, "source": "encyclopedia-stable consensus; NRC PS4 waves", "generator": "claude-workflow", "reviewed": false},
  {"id": "ph-diwata-satellite-g6", "domain": "EARTH_SPACE", "topic": "the Philippines' first satellite Diwata", "grades": [6, 7], "terms": ["Diwata", "Philippine satellite", "first Filipino satellite", "2016", "Diwata-1", "satellite ng Pilipinas", "unang satellite ng Pilipino", "espasyo", "satellite sa Pilipinas", "unang Pinoy satellite", "kawanangan", "panahon"], "fact": {"tl": "Ang Diwata-1, na inilunsad noong 2016, ang unang microsatellite na ginawa ng mga Pilipino; ginamit ito para kumuha ng mga larawan ng Pilipinas mula sa kalawakan para sa panahon at sakuna.", "en": "Diwata-1, launched in 2016, was the first microsatellite built by Filipinos; it was used to take pictures of the Philippines from space for weather and disaster monitoring.", "bis": "Ang Diwata-1, nga gilunsad niadtong 2016, mao ang unang microsatellite nga gibuhat sa mga Pilipino; gigamit kini aron magkuha og hulagway sa Pilipinas gikan sa kawanangan alang sa panahon ug katalagman."}, "source": "encyclopedia-stable consensus; PH (DOST-PHL-Microsat / STAMINA4Space)", "generator": "claude-workflow", "reviewed": false},
  {"id": "moon-has-no-air-people-cant-breathe-g4", "domain": "EARTH_SPACE", "topic": "why people cannot live on the Moon without help", "grades": [4, 5], "terms": ["Moon no air", "cannot breathe", "no water", "astronaut", "Buwan walang hangin", "hindi makahinga", "walang tubig", "espasyo", "Bulan walay hangin", "dili makaginhawa", "walay tubig", "kawanangan", "ginhawa"], "fact": {"tl": "Hindi basta-basta makakatira ang tao sa Buwan dahil wala itong hangin na mahihinga at walang tubig na maiinom, kaya kailangan ng mga astronaut ng espesyal na kasuotan at dalang oxygen kapag pumupunta sila roon.", "en": "People cannot simply live on the Moon because it has no air to breathe and no water to drink, so astronauts need special suits and their own oxygen when they go there.", "bis": "Ang mga tawo dili basta makapuyo sa Bulan tungod kay wala kini hangin nga ginhawaon ug walay tubig nga imnon, busa ang mga astronaut nagkinahanglan og espesyal nga sapot ug dala nga oxygen kon moadto sila didto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "phivolcs-what-is-g6", "domain": "EARTH_SPACE", "topic": "what PHIVOLCS does", "grades": [5, 6, 7], "terms": ["PHIVOLCS", "Philippine Institute of Volcanology and Seismology", "ahensya", "bulkan", "lindol", "babala", "warning", "nagbabantay", "monitoring", "tsunami", "ahensiya", "linog", "nagbantay", "pasidaan", "government agency", "earthquake", "volcano"], "fact": {"tl": "Ang PHIVOLCS (Philippine Institute of Volcanology and Seismology) ang ahensya ng gobyerno na nagbabantay sa mga bulkan, lindol, at tsunami sa Pilipinas at nagbibigay ng babala sa mga tao.", "en": "PHIVOLCS (the Philippine Institute of Volcanology and Seismology) is the government agency that monitors volcanoes, earthquakes, and tsunamis in the Philippines and warns people.", "bis": "Ang PHIVOLCS (Philippine Institute of Volcanology and Seismology) mao ang ahensya sa gobyerno nga nagbantay sa mga bulkan, linog, ug tsunami sa Pilipinas ug naghatag ug pasidaan sa mga tawo."}, "source": "DepEd MATATAG Science CG (PHIVOLCS Alert Levels strand); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "phivolcs-volcano-alert-levels-g7", "domain": "EARTH_SPACE", "topic": "PHIVOLCS volcano alert levels", "grades": [6, 7, 8], "terms": ["alert level", "antas ng babala", "PHIVOLCS", "bulkan", "volcano", "0 hanggang 5", "Alert Level 0", "Alert Level 5", "pagsabog", "eruption", "lindol", "babala", "lebel sa pasidaan", "0 ngadto 5", "pagbuto", "monitoring", "antas", "lebel"], "fact": {"tl": "Gumagamit ang PHIVOLCS ng Alert Level 0 hanggang 5 para sa mga bulkan: ang Alert Level 0 ay normal at tahimik, habang ang Alert Level 5 ay nangangahulugang may malakas at mapanganib na pagsabog na nangyayari na.", "en": "PHIVOLCS uses Alert Levels 0 to 5 for volcanoes: Alert Level 0 means normal and quiet, while Alert Level 5 means a hazardous eruption is happening now.", "bis": "Naggamit ang PHIVOLCS ug Alert Level 0 hangtod 5 para sa mga bulkan: ang Alert Level 0 normal ug hilom, samtang ang Alert Level 5 nagpasabot nga adunay kusog ug delikado nga pagbuto nga nahitabo na karon."}, "source": "DepEd MATATAG Science CG (PHIVOLCS Volcano Monitoring Alert Levels); PHIVOLCS, encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "phivolcs-tsunami-warning-g7", "domain": "EARTH_SPACE", "topic": "PHIVOLCS tsunami warning", "grades": [6, 7, 8], "terms": ["tsunami", "babala", "warning", "PHIVOLCS", "lindol sa ilalim ng dagat", "underwater earthquake", "malalaking alon", "alon", "pasidaan", "linog sa ilawom sa dagat", "dako nga balod", "balod", "tumakas", "evacuate", "mataas na lugar", "coast", "baybayin"], "fact": {"tl": "Kapag may malakas na lindol sa ilalim ng dagat, maaaring magbigay ang PHIVOLCS ng babala sa tsunami para makatakas ang mga tao sa baybayin patungo sa mataas na lugar.", "en": "When a strong earthquake happens under the sea, PHIVOLCS may issue a tsunami warning so people along the coast can move to higher ground.", "bis": "Kon adunay kusog nga linog sa ilawom sa dagat, mahimong maghatag ang PHIVOLCS ug pasidaan sa tsunami aron makalikay ang mga tawo sa baybayon ngadto sa habog nga dapit."}, "source": "DepEd MATATAG Science CG (earthquake/tsunami disaster readiness); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fault-line-what-is-g7", "domain": "EARTH_SPACE", "topic": "what a fault is", "grades": [7, 8], "terms": ["fault", "fault line", "bali sa bato", "bitak", "lindol", "earthquake", "gumagalaw", "biyak ng lupa", "crack", "rock", "linog", "pagkabali", "naggalaw", "liki sa bato", "lupa", "ground", "movement"], "fact": {"tl": "Ang fault ay isang bitak o bali sa malalaking bato sa ilalim ng lupa kung saan ang dalawang panig ay maaaring gumalaw; kapag biglang gumalaw ito, nagkakaroon ng lindol.", "en": "A fault is a crack or break in the large rocks underground where the two sides can move; when they suddenly slip, an earthquake happens.", "bis": "Ang fault usa ka liki o pagkabali sa dagkong bato sa ilawom sa yuta diin ang duha ka kilid mahimong molihok; kon kalit kini molihok, mahitabo ang linog."}, "source": "DepEd MATATAG Science CG (dynamics of faults and earthquakes); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "west-valley-fault-g8", "domain": "EARTH_SPACE", "topic": "West Valley Fault", "grades": [7, 8, 9], "terms": ["West Valley Fault", "Metro Manila", "fault", "lindol", "earthquake", "Marikina Valley", "handa", "preparedness", "PHIVOLCS", "FaultFinder", "linog", "Kalakhang Maynila", "bali", "delikado", "active fault", "aktibong fault"], "fact": {"tl": "Ang West Valley Fault ay isang aktibong fault na dumadaan malapit sa Metro Manila, kaya mahalaga sa mga pamilya doon na maghanda para sa posibleng malakas na lindol.", "en": "The West Valley Fault is an active fault that runs near Metro Manila, so families there should be ready for a possible strong earthquake.", "bis": "Ang West Valley Fault usa ka aktibo nga fault nga moagi duol sa Metro Manila, busa importante sa mga pamilya didto nga mangandam para sa posibleng kusog nga linog."}, "source": "DepEd MATATAG Science CG (PHIVOLCS FaultFinder, local fault systems); PHIVOLCS, encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "philippine-fault-zone-g8", "domain": "EARTH_SPACE", "topic": "Philippine Fault Zone", "grades": [7, 8, 9], "terms": ["Philippine Fault", "Philippine Fault Zone", "fault", "buong bansa", "Luzon", "Mindanao", "lindol", "earthquake", "mahabang bali", "linog", "tibuok nasod", "taas nga fault", "active", "aktibo", "country", "across"], "fact": {"tl": "Ang Philippine Fault ay isang napakahabang fault na tumatagos sa buong bansa mula Luzon hanggang Mindanao, at isa ito sa mga pinagmumulan ng malalakas na lindol sa Pilipinas.", "en": "The Philippine Fault is a very long fault that runs across the whole country from Luzon to Mindanao, and it is one source of the country's strong earthquakes.", "bis": "Ang Philippine Fault usa ka taas kaayo nga fault nga moagi sa tibuok nasod gikan sa Luzon hangtod Mindanao, ug usa kini sa mga gigikanan sa kusog nga mga linog sa Pilipinas."}, "source": "DepEd MATATAG Science CG (local fault systems); PHIVOLCS, encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fault-types-g8", "domain": "EARTH_SPACE", "topic": "types of faults", "grades": [8, 9, 10], "terms": ["fault", "uri ng fault", "normal fault", "reverse fault", "strike-slip", "lindol", "earthquake", "galaw", "movement", "tipo sa fault", "klase", "linog", "plane", "direksyon", "direction", "block"], "fact": {"tl": "May tatlong pangunahing uri ng fault ayon sa galaw nito: normal fault (humihila palayo), reverse fault (nagtutulakan), at strike-slip fault (nagkakadaplis nang pahalang).", "en": "There are three main types of faults based on how they move: normal faults (pulling apart), reverse faults (pushing together), and strike-slip faults (sliding sideways past each other).", "bis": "Adunay tulo ka panguna nga klase sa fault sumala sa lihok niini: normal fault (nagbira palayo), reverse fault (nagtuloray), ug strike-slip fault (nagdaplis nga pakilid)."}, "source": "DepEd MATATAG Science CG (classify geological faults: normal, reverse, strike-slip); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "earthquake-focus-epicenter-g8", "domain": "EARTH_SPACE", "topic": "focus and epicenter of an earthquake", "grades": [7, 8, 9], "terms": ["focus", "epicenter", "epicentro", "lindol", "earthquake", "pinagmulan", "ilalim ng lupa", "ibabaw", "underground", "surface", "linog", "tuburan", "ibabaw sa yuta", "ilawom", "directly above", "tuktok"], "fact": {"tl": "Ang focus ay ang puntong nasa ilalim ng lupa kung saan nagsisimula ang lindol, at ang epicenter naman ay ang lugar sa ibabaw ng lupa na nasa tuktok mismo ng focus.", "en": "The focus is the point underground where an earthquake begins, and the epicenter is the spot on the surface directly above the focus.", "bis": "Ang focus mao ang punto sa ilawom sa yuta diin magsugod ang linog, ug ang epicenter mao ang dapit sa ibabaw sa yuta nga anaa gyud sa tumoy sa focus."}, "source": "DepEd MATATAG Science CG (epicenter from focus); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "earthquake-magnitude-vs-intensity-g8", "domain": "EARTH_SPACE", "topic": "magnitude versus intensity", "grades": [8, 9, 10], "terms": ["magnitude", "intensity", "lakas", "lindol", "earthquake", "enerhiya", "energy", "ramdam", "felt", "PEIS", "kusog", "linog", "kakusgon", "gibati", "scale", "sukat", "measure"], "fact": {"tl": "Ang magnitude ay sumusukat sa kabuuang enerhiyang inilabas ng lindol, habang ang intensity ay kung gaano kalakas naramdaman ang pagyanig sa isang partikular na lugar.", "en": "Magnitude measures the total energy released by an earthquake, while intensity measures how strongly the shaking is felt at a particular place.", "bis": "Ang magnitude nagsukod sa kinatibuk-ang enerhiya nga gibuga sa linog, samtang ang intensity nagsukod kon unsa ka kusog gibati ang pag-uyog sa usa ka partikular nga dapit."}, "source": "DepEd MATATAG Science CG (intensity from magnitude); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "earthquake-seismograph-g7", "domain": "EARTH_SPACE", "topic": "how earthquakes are measured", "grades": [6, 7, 8], "terms": ["seismograph", "seismometer", "lindol", "earthquake", "sukat", "instrumento", "pagyanig", "vibration", "PHIVOLCS", "record", "linog", "makina", "nagsukod", "pag-uyog", "instrument", "detect", "nararamdaman"], "fact": {"tl": "Ginagamit ang isang makinang tinatawag na seismograph para tuklasin at itala ang pagyanig ng lupa kapag may lindol, kahit ang napakahina nito.", "en": "A machine called a seismograph is used to detect and record the shaking of the ground during an earthquake, even very weak ones.", "bis": "Gigamit ang usa ka makina nga gitawag ug seismograph aron mamatikdan ug irekord ang pag-uyog sa yuta kon adunay linog, bisan ang huyang kaayo niini."}, "source": "encyclopedia-stable consensus; DepEd MATATAG Science CG (earthquake monitoring)", "generator": "claude-workflow", "reviewed": false},
  {"id": "earthquake-duck-cover-hold-g4", "domain": "EARTH_SPACE", "topic": "duck cover and hold during earthquake", "grades": [3, 4, 5], "terms": ["duck cover and hold", "yuko takip kapit", "lindol", "earthquake", "mesa", "table", "kaligtasan", "safety", "magtago", "tumakbo", "linog", "lamesa", "pagsalipod", "kupot", "protektahan", "ulo", "head", "ligtas"], "fact": {"tl": "Kapag may lindol, gawin ang 'Duck, Cover, and Hold': yumuko, sumilong sa ilalim ng matibay na mesa, at kumapit dito hangga't yumayanig ang lupa.", "en": "During an earthquake, do 'Duck, Cover, and Hold': drop down, take cover under a sturdy table, and hold on to it until the shaking stops.", "bis": "Kon adunay linog, buhata ang 'Duck, Cover, and Hold': pangduko, salipod ilawom sa lig-on nga lamesa, ug kuptan kini hangtod mohunong ang pag-uyog."}, "source": "DepEd MATATAG Science CG (what to do during an earthquake); PHIVOLCS, encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "earthquake-after-shaking-g5", "domain": "EARTH_SPACE", "topic": "what to do after an earthquake", "grades": [4, 5, 6], "terms": ["pagkatapos ng lindol", "after earthquake", "evacuate", "lumabas", "bukas na lugar", "open area", "aftershock", "kaligtasan", "safety", "lindol", "human sa linog", "gawas", "luwas nga dapit", "linog", "kalmado", "calmly", "aftershock"], "fact": {"tl": "Pagkatapos ng malakas na lindol, kalmadong lumabas patungo sa bukas na lugar na malayo sa gusali at poste, dahil maaari pang may sumunod na aftershocks.", "en": "After a strong earthquake, calmly go out to an open area away from buildings and posts, because aftershocks may still follow.", "bis": "Human sa kusog nga linog, kalmado nga gawas ngadto sa luwas nga dapit nga layo sa mga building ug poste, kay mahimo pa nga adunay mosunod nga aftershocks."}, "source": "DepEd MATATAG Science CG (what to do after an earthquake); PHIVOLCS, encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "earthquake-aftershock-g6", "domain": "EARTH_SPACE", "topic": "aftershocks", "grades": [5, 6, 7], "terms": ["aftershock", "mahinang lindol", "earthquake", "kasunod", "follow", "mainshock", "pagyanig", "linog", "sunod-sunod", "pag-uyog", "smaller earthquake", "humihina", "after"], "fact": {"tl": "Ang aftershocks ay mga mas mahihinang lindol na sumusunod pagkatapos ng pangunahing malakas na lindol, at maaari itong tumagal ng ilang araw o linggo.", "en": "Aftershocks are smaller earthquakes that follow after the main strong earthquake, and they can continue for several days or weeks.", "bis": "Ang aftershocks mao ang mas huyang nga mga linog nga mosunod human sa nag-unang kusog nga linog, ug mahimo kining molungtad ug pipila ka adlaw o semana."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "go-bag-emergency-kit-g4", "domain": "EARTH_SPACE", "topic": "emergency go-bag", "grades": [3, 4, 5], "terms": ["go bag", "emergency kit", "lindol", "earthquake", "tubig", "water", "pagkain", "flashlight", "first aid", "handa", "preparedness", "linog", "kalamidad", "disaster", "bag", "gamit", "supplies", "emergency"], "fact": {"tl": "Mainam maghanda ng 'go-bag' para sa lindol o sakuna na may laman na tubig, pagkaing de-lata, flashlight, at first-aid kit na madaling madala sa oras ng emergency.", "en": "It is wise to prepare a 'go-bag' for earthquakes or disasters containing water, canned food, a flashlight, and a first-aid kit that is easy to grab in an emergency.", "bis": "Maayo nga mangandam ug 'go-bag' para sa linog o katalagman nga adunay tubig, de-lata nga pagkaon, flashlight, ug first-aid kit nga sayon dad-on sa panahon sa emergency."}, "source": "DepEd MATATAG Science CG (disaster readiness plans); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mayon-volcano-g6", "domain": "EARTH_SPACE", "topic": "Mayon Volcano", "grades": [5, 6, 7], "terms": ["Mayon", "Bulkang Mayon", "Albay", "Bicol", "hugis-kono", "perfect cone", "bulkan", "volcano", "aktibo", "active", "linog", "pinakamaganda", "kono", "porma", "symmetrical", "pagsabog"], "fact": {"tl": "Ang Bulkang Mayon sa Albay ay tanyag sa buong mundo dahil sa halos perpekto nitong hugis-kono, at isa ito sa pinakaaktibong bulkan sa Pilipinas.", "en": "Mayon Volcano in Albay is famous worldwide for its nearly perfect cone shape, and it is one of the most active volcanoes in the Philippines.", "bis": "Ang Bulkang Mayon sa Albay bantog sa tibuok kalibutan tungod sa hapit hingpit nga porma niini nga kono, ug usa kini sa labing aktibo nga bulkan sa Pilipinas."}, "source": "encyclopedia-stable consensus; PHIVOLCS", "generator": "claude-workflow", "reviewed": false},
  {"id": "taal-volcano-g6", "domain": "EARTH_SPACE", "topic": "Taal Volcano", "grades": [5, 6, 7], "terms": ["Taal", "Bulkang Taal", "Batangas", "lawa", "lake", "isla", "island", "maliit", "small", "bulkan", "volcano", "aktibo", "active", "linaw", "pulo", "gamay", "crater lake", "pagsabog"], "fact": {"tl": "Ang Bulkang Taal sa Batangas ay isa sa pinakamaliliit na aktibong bulkan sa mundo at kakaiba ito dahil nasa loob ito ng isang lawa.", "en": "Taal Volcano in Batangas is one of the smallest active volcanoes in the world, and it is unusual because it sits inside a lake.", "bis": "Ang Bulkang Taal sa Batangas usa sa pinakagamay nga aktibo nga bulkan sa kalibutan ug talagsaon kini kay anaa kini sa sulod sa usa ka linaw."}, "source": "encyclopedia-stable consensus; PHIVOLCS", "generator": "claude-workflow", "reviewed": false},
  {"id": "pinatubo-eruption-1991-g7", "domain": "EARTH_SPACE", "topic": "Mount Pinatubo 1991 eruption", "grades": [6, 7, 8], "terms": ["Pinatubo", "Mount Pinatubo", "1991", "Zambales", "Pampanga", "sumabog", "eruption", "abo", "ash", "lahar", "bulkan", "volcano", "pagsabog", "malakas", "natulog", "dormant", "pagbuto", "abog", "malaking pagsabog"], "fact": {"tl": "Sumabog nang napakalakas ang Bulkang Pinatubo noong 1991 pagkatapos ng daan-daang taong pananahimik, at isa ito sa pinakamalalaking pagsabog ng bulkan noong ika-20 siglo.", "en": "Mount Pinatubo erupted very powerfully in 1991 after lying quiet for hundreds of years, and it was one of the largest volcanic eruptions of the 20th century.", "bis": "Mibuto nga kusog kaayo ang Bulkang Pinatubo niadtong 1991 human sa gatusan ka tuig nga paghilom, ug usa kini sa pinakadako nga pagbuto sa bulkan sa ika-20 nga siglo."}, "source": "encyclopedia-stable consensus; PHIVOLCS", "generator": "claude-workflow", "reviewed": false},
  {"id": "lahar-what-is-g7", "domain": "EARTH_SPACE", "topic": "what lahar is", "grades": [6, 7, 8], "terms": ["lahar", "abo", "ash", "putik", "mud", "bulkan", "volcano", "ulan", "rain", "Pinatubo", "delikado", "agos", "linog", "baha", "mudflow", "putikon nga agos", "danger", "pagsabog", "valley"], "fact": {"tl": "Ang lahar ay isang mabilis at mapanganib na agos ng putik at abo ng bulkan na pinapakilos ng malakas na ulan, at lumikha ito ng malaking pinsala matapos sumabog ang Pinatubo.", "en": "Lahar is a fast and dangerous flow of volcanic mud and ash set in motion by heavy rain, and it caused great damage after Pinatubo erupted.", "bis": "Ang lahar usa ka paspas ug delikado nga agos sa lapok ug abo sa bulkan nga gipalihok sa kusog nga ulan, ug daghan kining nadaot human mibuto ang Pinatubo."}, "source": "encyclopedia-stable consensus; PHIVOLCS", "generator": "claude-workflow", "reviewed": false},
  {"id": "volcano-active-dormant-extinct-g6", "domain": "EARTH_SPACE", "topic": "active dormant and extinct volcanoes", "grades": [5, 6, 7], "terms": ["active", "dormant", "extinct", "aktibo", "natutulog", "patay", "bulkan", "volcano", "sumasabog", "natulog", "buhi", "patay nga bulkan", "klase", "pagsabog", "namatay", "tulog", "sleeping", "dead"], "fact": {"tl": "Ang mga bulkan ay maaaring active (maaaring sumabog), dormant (natutulog ngunit puwedeng magising), o extinct (hindi na inaasahang sumabog kailanman).", "en": "Volcanoes can be active (able to erupt), dormant (sleeping but able to wake up), or extinct (not expected to ever erupt again).", "bis": "Ang mga bulkan mahimong active (mahimong mobuto), dormant (natulog apan mahimong momata), o extinct (dili na gilauman nga mobuto pa)."}, "source": "DepEd MATATAG Science CG (active and inactive volcanoes); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ph-active-volcano-count-g7", "domain": "EARTH_SPACE", "topic": "number of active volcanoes in the Philippines", "grades": [6, 7, 8], "terms": ["aktibong bulkan", "active volcano", "Pilipinas", "Philippines", "bilang", "number", "24", "PHIVOLCS", "marami", "bulkan", "ihap", "daghan", "aktibo", "how many", "ilan", "pila"], "fact": {"tl": "Ayon sa PHIVOLCS, may humigit-kumulang dalawampu't apat (24) na aktibong bulkan sa Pilipinas, kabilang ang Mayon, Taal, at Pinatubo.", "en": "According to PHIVOLCS, there are about twenty-four (24) active volcanoes in the Philippines, including Mayon, Taal, and Pinatubo.", "bis": "Sumala sa PHIVOLCS, adunay mga baynte-kuwatro (24) ka aktibo nga bulkan sa Pilipinas, lakip ang Mayon, Taal, ug Pinatubo."}, "source": "PHIVOLCS, encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "volcano-crater-g5", "domain": "EARTH_SPACE", "topic": "volcano crater", "grades": [4, 5, 6], "terms": ["crater", "bunganga", "bulkan", "volcano", "butas", "opening", "lava", "abo", "ash", "tuktok", "baba", "top", "bangag", "lungag", "hole", "bunganga sa bulkan", "summit"], "fact": {"tl": "Ang crater ay ang hugis-mangkok na bunganga sa tuktok ng bulkan kung saan lumalabas ang lava, abo, at gas tuwing sumasabog ito.", "en": "A crater is the bowl-shaped opening at the top of a volcano where lava, ash, and gas come out when it erupts.", "bis": "Ang crater mao ang sama-sa-yahong nga bangag sa tumoy sa bulkan diin mogawas ang lava, abo, ug gas kon kini mobuto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "magma-vs-lava-g6", "domain": "EARTH_SPACE", "topic": "magma versus lava", "grades": [5, 6, 7], "terms": ["magma", "lava", "tunaw na bato", "molten rock", "bulkan", "volcano", "ilalim ng lupa", "ibabaw", "underground", "surface", "init", "natunaw nga bato", "ilawom", "init nga bato", "melted", "difference", "pagkakaiba"], "fact": {"tl": "Ang tunaw na bato sa ilalim ng lupa ay tinatawag na magma, ngunit kapag lumabas na ito sa ibabaw sa pamamagitan ng bulkan, tinatawag na itong lava.", "en": "Melted rock beneath the ground is called magma, but once it comes out onto the surface through a volcano, it is called lava.", "bis": "Ang natunaw nga bato sa ilawom sa yuta gitawag nga magma, apan kon mogawas na kini sa ibabaw pinaagi sa bulkan, gitawag na kini nga lava."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "volcano-ash-cloud-g6", "domain": "EARTH_SPACE", "topic": "volcanic ash cloud and ashfall", "grades": [5, 6, 7], "terms": ["abo", "ashfall", "ash cloud", "bulkan", "volcano", "pagsabog", "ulan ng abo", "mask", "kalusugan", "health", "hininga", "breathing", "abog", "pagbuto", "ulan sa abo", "takpan", "cover", "danger"], "fact": {"tl": "Kapag sumasabog ang bulkan, maaari itong magbuga ng makapal na ulap ng abo na bumababa bilang ashfall; mahalagang magsuot ng mask para hindi makalanghap nito.", "en": "When a volcano erupts, it can throw out a thick cloud of ash that falls as ashfall; it is important to wear a mask so it is not breathed in.", "bis": "Kon mobuto ang bulkan, mahimo kining mobuga ug baga nga panganod sa abo nga mahulog isip ashfall; importante nga magsul-ob ug mask aron dili kini masuyop."}, "source": "encyclopedia-stable consensus; PHIVOLCS", "generator": "claude-workflow", "reviewed": false},
  {"id": "ring-of-fire-why-earthquakes-g7", "domain": "EARTH_SPACE", "topic": "why the Ring of Fire has many earthquakes", "grades": [6, 7, 8], "terms": ["Ring of Fire", "Pacific", "Pilipinas", "Philippines", "lindol", "earthquake", "bulkan", "volcano", "plate", "tectonic", "magkadikit", "boundary", "linog", "nagtagbo", "nag-uyog", "frequent", "madalas", "kanunay", "edge"], "fact": {"tl": "Madalas magkalindol at maraming bulkan sa Pilipinas dahil nasa Pacific Ring of Fire ito, ang gilid ng Pacific Ocean kung saan maraming tectonic plate ang nagtatagpo at nagkukuskusan.", "en": "The Philippines has frequent earthquakes and many volcanoes because it lies on the Pacific Ring of Fire, the edge of the Pacific Ocean where many tectonic plates meet and grind.", "bis": "Kanunay nga molinog ug daghan ug bulkan ang Pilipinas tungod kay anaa kini sa Pacific Ring of Fire, ang ngilit sa Pacific Ocean diin daghang tectonic plate ang nagtagbo ug nagdaplis."}, "source": "encyclopedia-stable consensus; DepEd MATATAG Science CG (Ring of Fire)", "generator": "claude-workflow", "reviewed": false},
  {"id": "earthquake-drill-g4", "domain": "EARTH_SPACE", "topic": "earthquake drills at school", "grades": [3, 4, 5], "terms": ["earthquake drill", "lindol", "pagsasanay", "drill", "paaralan", "school", "handa", "practice", "ligtas", "safety", "linog", "ensayo", "tulunghaan", "andam", "nationwide drill", "magsanay", "prepare"], "fact": {"tl": "Nagsasagawa ng earthquake drill sa mga paaralan sa Pilipinas para masanay ang mga bata kung ano ang gagawin at saan tatakbo nang ligtas kapag may totoong lindol.", "en": "Earthquake drills are held in Philippine schools so that children can practice what to do and where to go safely during a real earthquake.", "bis": "Ginahimo ang earthquake drill sa mga eskwelahan sa Pilipinas aron masanay ang mga bata kon unsay buhaton ug asa modagan nga luwas kon adunay tinuod nga linog."}, "source": "DepEd MATATAG Science CG (disaster readiness); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "volcano-warning-signs-g6", "domain": "EARTH_SPACE", "topic": "warning signs before a volcanic eruption", "grades": [5, 6, 7], "terms": ["palatandaan", "warning signs", "bulkan", "volcano", "pagsabog", "eruption", "lindol", "usok", "smoke", "init", "PHIVOLCS", "babala", "linog", "timailhan", "aso", "kainit", "ground swelling", "amoy", "sulfur"], "fact": {"tl": "Bago sumabog ang isang bulkan, maaaring may mga palatandaan tulad ng madalas na maliliit na lindol, pag-usok mula sa bunganga, at pag-init ng lupa, na binabantayan ng PHIVOLCS.", "en": "Before a volcano erupts, there can be warning signs like frequent small earthquakes, smoke from the crater, and heating of the ground, which PHIVOLCS watches for.", "bis": "Sa dili pa mobuto ang usa ka bulkan, mahimong adunay mga timailhan sama sa kanunay nga gagmay nga linog, aso gikan sa bunganga, ug pag-init sa yuta, nga gibantayan sa PHIVOLCS."}, "source": "encyclopedia-stable consensus; PHIVOLCS volcano monitoring", "generator": "claude-workflow", "reviewed": false},
  {"id": "danger-zone-evacuation-g6", "domain": "EARTH_SPACE", "topic": "volcano danger zone and evacuation", "grades": [5, 6, 7], "terms": ["danger zone", "permanent danger zone", "bulkan", "volcano", "lumikas", "evacuate", "ligtas", "safe", "PHIVOLCS", "babala", "alert", "delikadong sona", "linog", "pagbakwit", "bakwit", "layo", "radius", "lugar"], "fact": {"tl": "Sa palibot ng mga aktibong bulkan ay may 'danger zone' na ipinagbabawal tirhan, at kapag tumaas ang alert level, kailangang lumikas ang mga tao palayo para sa kanilang kaligtasan.", "en": "Around active volcanoes there is a 'danger zone' where living is not allowed, and when the alert level rises, people must evacuate away from it for their safety.", "bis": "Sa palibot sa mga aktibo nga bulkan adunay 'danger zone' nga gidili nga puy-an, ug kon mosaka ang alert level, kinahanglan mobakwit ang mga tawo palayo alang sa ilang kaluwasan."}, "source": "encyclopedia-stable consensus; PHIVOLCS", "generator": "claude-workflow", "reviewed": false},
  {"id": "tsunami-cause-g7", "domain": "EARTH_SPACE", "topic": "what causes a tsunami", "grades": [6, 7, 8], "terms": ["tsunami", "lindol sa dagat", "underwater earthquake", "malalaking alon", "giant waves", "dagat", "sea", "dahilan", "cause", "baybayin", "coast", "balod", "linog sa dagat", "dako nga balod", "alon", "tubig", "salog sa dagat", "sea floor"], "fact": {"tl": "Karaniwang nagmumula ang tsunami sa malakas na lindol sa ilalim ng dagat na biglang nagpapagalaw ng sahig ng karagatan, na lumilikha ng napakalalaking alon patungo sa baybayin.", "en": "A tsunami is usually caused by a strong earthquake under the sea that suddenly moves the ocean floor, creating very large waves that rush toward the coast.", "bis": "Kasagaran nga ang tsunami gikan sa kusog nga linog sa ilawom sa dagat nga kalit nga nagpalihok sa salog sa kadagatan, nga nagmugna ug dagko kaayo nga balod paingon sa baybayon."}, "source": "DepEd MATATAG Science CG (underwater earthquakes and tsunamis); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tsunami-natural-warning-g6", "domain": "EARTH_SPACE", "topic": "natural warning sign of a tsunami", "grades": [5, 6, 7], "terms": ["tsunami", "palatandaan", "warning sign", "humuhupa ang dagat", "sea recedes", "babala", "baybayin", "coast", "tumakbo", "mataas na lugar", "high ground", "linog", "balod", "mihubas ang dagat", "timailhan", "tumakas", "run", "shore", "receding"], "fact": {"tl": "Kung biglang humupa ang tubig-dagat at lumitaw ang ilalim nito pagkatapos ng lindol, maaaring darating na ang tsunami, kaya dapat agad tumakbo sa mataas na lugar.", "en": "If the sea water suddenly pulls back and exposes the sea bottom after an earthquake, a tsunami may be coming, so people should run to high ground at once.", "bis": "Kon kalit nga mohubas ang tubig sa dagat ug makita ang salog niini human sa linog, mahimong moabot na ang tsunami, busa kinahanglan dayon modagan sa habog nga dapit."}, "source": "encyclopedia-stable consensus; PHIVOLCS tsunami awareness", "generator": "claude-workflow", "reviewed": false},
  {"id": "earthquake-secure-furniture-g5", "domain": "EARTH_SPACE", "topic": "securing furniture before earthquakes", "grades": [4, 5, 6], "terms": ["aparador", "cabinet", "furniture", "lindol", "earthquake", "ikabit", "secure", "pader", "wall", "kaligtasan", "safety", "handa", "linog", "muwebles", "ipahimutang", "matumba", "preparedness", "bumagsak", "bungbong"], "fact": {"tl": "Bahagi ng paghahanda sa lindol ang pagkakabit ng matataas na aparador at istante sa pader para hindi ito matumba at makasakit kapag yumanig ang lupa.", "en": "Part of earthquake preparedness is fastening tall cabinets and shelves to the wall so they do not topple over and hurt someone when the ground shakes.", "bis": "Kabahin sa pagpangandam sa linog ang pagkabit sa habog nga mga aparador ug estante sa bungbong aron dili kini matumba ug makadaot kon mouyog ang yuta."}, "source": "DepEd MATATAG Science CG (disaster readiness); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "weather-definition-g3", "domain": "EARTH_SPACE", "topic": "what weather is", "grades": [3, 4], "terms": ["panahon", "lagay ng panahon", "init", "ulan", "hangin", "weather", "hot", "rainy", "windy", "panahon karon", "ulanon", "init", "hanginon", "tiempo"], "fact": {"tl": "Ang panahon ay kung ano ang lagay ng himpapawid sa isang lugar ngayon, gaya ng pagiging mainit, maulan, maulap, o mahangin.", "en": "Weather is what the air is like in a place right now, such as hot, rainy, cloudy, or windy.", "bis": "Ang panahon mao ang kahimtang sa hangin sa usa ka lugar karon, sama sa init, ulanon, panganuron, o hanginon."}, "source": "AAAS Benchmarks 4B/E5; NRC ESS2.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "weather-vs-climate-g6", "domain": "EARTH_SPACE", "topic": "weather versus climate", "grades": [6, 7], "terms": ["panahon", "klima", "weather", "climate", "matagal", "araw-araw", "average", "matag adlaw", "tiempo", "dugay na panahon"], "fact": {"tl": "Ang panahon ay nagbabago araw-araw, ngunit ang klima ay ang karaniwang panahon ng isang lugar sa loob ng maraming taon.", "en": "Weather changes from day to day, but climate is the usual pattern of weather in a place over many years.", "bis": "Ang panahon mausab matag adlaw, apan ang klima mao ang naandang sumbanan sa panahon sa usa ka lugar sulod sa daghang tuig."}, "source": "AAAS Benchmarks 4B/M14", "generator": "claude-workflow", "reviewed": false},
  {"id": "weather-measure-tools-g4", "domain": "EARTH_SPACE", "topic": "measuring weather", "grades": [4, 5], "terms": ["sukat ng panahon", "termometro", "thermometer", "temperatura", "hangin", "ulan", "rain gauge", "measure", "wind speed", "sukod", "kusog sa hangin", "gidaghanon sa ulan"], "fact": {"tl": "Sinusukat ang panahon gamit ang temperatura, lakas at direksyon ng hangin, at dami ng ulan.", "en": "Weather can be measured by temperature, the speed and direction of the wind, and the amount of rain that falls.", "bis": "Ang panahon masukod pinaagi sa temperatura, kusog ug direksyon sa hangin, ug gidaghanon sa ulan nga nahulog."}, "source": "AAAS Benchmarks 4B/E5", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-cycle-g4", "domain": "EARTH_SPACE", "topic": "the water cycle", "grades": [4, 5, 6], "terms": ["siklo ng tubig", "water cycle", "singaw", "evaporation", "ulan", "rain", "ulap", "umuulan", "pag-ulan", "tubig", "siklo sa tubig", "alisngaw", "panganod"], "fact": {"tl": "Sa siklo ng tubig, ang tubig ay sumisingaw mula sa dagat, lumalamig at nagiging ulap, at bumabagsak muli bilang ulan.", "en": "In the water cycle, water evaporates from the sea, cools to form clouds, and falls back to the ground as rain.", "bis": "Sa siklo sa tubig, ang tubig moalisngaw gikan sa dagat, mobugnaw aron mahimong panganod, ug mahulog balik isip ulan."}, "source": "AAAS Benchmarks 4B/M7", "generator": "claude-workflow", "reviewed": false},
  {"id": "cloud-formation-g4", "domain": "EARTH_SPACE", "topic": "how clouds form", "grades": [4, 5], "terms": ["ulap", "cloud", "panganod", "patak", "tubig", "droplet", "singaw", "lumalamig", "paano nabubuo ang ulap", "tinulo sa tubig", "alisngaw", "mibugnaw"], "fact": {"tl": "Ang ulap ay binubuo ng napakaliliit na patak ng tubig o yelo na nabuo nang lumamig ang singaw ng tubig sa himpapawid.", "en": "Clouds are made of tiny droplets of water or ice that form when water vapor in the air cools down.", "bis": "Ang panganod gilangkuban sa gagmay kaayong tinulo sa tubig o yelo nga nabuo dihang mibugnaw ang alisngaw sa hangin."}, "source": "AAAS Benchmarks 4B/E3", "generator": "claude-workflow", "reviewed": false},
  {"id": "cloud-types-g6", "domain": "EARTH_SPACE", "topic": "types of clouds", "grades": [6, 7], "terms": ["uri ng ulap", "cumulus", "stratus", "cirrus", "ulap", "bulak", "patong", "types of clouds", "klase sa panganod", "panganod nga bulak", "sapaw-sapaw"], "fact": {"tl": "May iba't ibang uri ng ulap: ang cumulus ay parang bulak, ang stratus ay nakapatong na manipis, at ang cirrus ay matangkad at parang buhok.", "en": "There are different kinds of clouds: cumulus look like cotton balls, stratus form flat layers, and cirrus are high and wispy.", "bis": "Adunay nagkalainlaing klase sa panganod: ang cumulus murag bulak, ang stratus nipis nga sapaw-sapaw, ug ang cirrus taas ug murag balhibo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rain-formation-g4", "domain": "EARTH_SPACE", "topic": "how rain falls", "grades": [4, 5], "terms": ["ulan", "rain", "pag-ulan", "patak", "bumabagsak", "mabigat", "ulap", "tubig", "bakit umuulan", "ngano nga mag-ulan", "mabug-at", "tinulo"], "fact": {"tl": "Umuulan kapag ang maliliit na patak ng tubig sa ulap ay nagsasama hanggang sa maging napakabigat na ang mga ito ay bumagsak sa lupa.", "en": "Rain falls when tiny water droplets in a cloud join together until they become heavy enough to fall to the ground.", "bis": "Mag-ulan kung ang gagmayng tinulo sa tubig sa panganod magtapok hangtod nga mabug-at na sila aron mahulog sa yuta."}, "source": "AAAS Benchmarks 4B/M7", "generator": "claude-workflow", "reviewed": false},
  {"id": "typhoon-what-g5", "domain": "EARTH_SPACE", "topic": "what a typhoon is", "grades": [5, 6, 7], "terms": ["bagyo", "typhoon", "malakas na hangin", "malakas na ulan", "umiikot", "tropical cyclone", "unos", "ano ang bagyo", "kusog nga hangin", "nagtuyok", "init nga kadagatan"], "fact": {"tl": "Ang bagyo ay isang malaking umiikot na unos na may napakalakas na hangin at malakas na ulan na nabubuo sa mainit na karagatan.", "en": "A typhoon is a large spinning storm with very strong winds and heavy rain that forms over warm ocean waters.", "bis": "Ang bagyo usa ka dakong nagtuyok nga unos nga adunay kusog kaayong hangin ug kusog nga ulan nga matawo sa init nga kadagatan."}, "source": "encyclopedia-stable consensus; AAAS 4B/H2", "generator": "claude-workflow", "reviewed": false},
  {"id": "typhoon-eye-g6", "domain": "EARTH_SPACE", "topic": "the eye of a typhoon", "grades": [6, 7, 8], "terms": ["mata ng bagyo", "eye of the typhoon", "kalmado", "gitna", "tahimik", "calm center", "mata sa bagyo", "hilom", "kalma", "tunga sa bagyo"], "fact": {"tl": "Ang mata ng bagyo ay ang tahimik at kalmadong gitna nito, ngunit ang paligid nito ang may pinakamalakas na hangin at ulan.", "en": "The eye of a typhoon is its calm, quiet center, but the ring of clouds around the eye has the strongest winds and rain.", "bis": "Ang mata sa bagyo mao ang hilom ug kalma nga tunga niini, apan ang palibot sa mata mao ang adunay pinakakusog nga hangin ug ulan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "typhoon-ph-frequency-g6", "domain": "EARTH_SPACE", "topic": "typhoons in the Philippines", "grades": [6, 7], "terms": ["bagyo", "Pilipinas", "typhoon", "Philippines", "dami ng bagyo", "taon", "PAR", "ilang bagyo bawat taon", "bagyo matag tuig", "kanunay igo sa bagyo"], "fact": {"tl": "Ang Pilipinas ay isa sa mga bansang pinakamadalas tamaan ng bagyo, na may mga 20 bagyong pumapasok sa bansa bawat taon.", "en": "The Philippines is one of the countries most often hit by typhoons, with about 20 storms entering the country each year.", "bis": "Ang Pilipinas usa sa mga nasod nga kanunay igo sa bagyo, nga adunay mga 20 ka bagyo nga mosulod sa nasod matag tuig."}, "source": "encyclopedia-stable consensus (PAGASA)", "generator": "claude-workflow", "reviewed": false},
  {"id": "pagasa-role-g5", "domain": "EARTH_SPACE", "topic": "what PAGASA does", "grades": [5, 6], "terms": ["PAGASA", "ahensya", "weather", "panahon", "babala", "warning", "hula sa panahon", "ano ang PAGASA", "ahensya sa panahon", "pasidaan", "nagbantay"], "fact": {"tl": "Ang PAGASA ang ahensya ng pamahalaan na nagmamasid sa panahon at nagbibigay ng babala tungkol sa mga bagyo sa Pilipinas.", "en": "PAGASA is the government agency that watches the weather and gives warnings about typhoons in the Philippines.", "bis": "Ang PAGASA mao ang ahensya sa gobyerno nga nagbantay sa panahon ug naghatag ug pasidaan bahin sa mga bagyo sa Pilipinas."}, "source": "encyclopedia-stable consensus (PAGASA)", "generator": "claude-workflow", "reviewed": false},
  {"id": "storm-signal-system-g6", "domain": "EARTH_SPACE", "topic": "PAGASA storm signals", "grades": [6, 7], "terms": ["storm signal", "senyales", "babala", "Signal No. 1", "tropical cyclone wind signal", "TCWS", "PAGASA", "lakas ng hangin", "senyales sa bagyo", "pasidaan", "lima ka signal", "kusog sa hangin"], "fact": {"tl": "Naglalabas ang PAGASA ng limang antas ng storm signal, mula Signal No. 1 hanggang 5, batay sa lakas ng hanging inaasahan sa isang lugar.", "en": "PAGASA raises five levels of storm signal, from Signal No. 1 up to Signal No. 5, based on how strong the wind is expected to be in an area.", "bis": "Ang PAGASA mopagawas ug lima ka ang-ang sa storm signal, gikan sa Signal No. 1 hangtod 5, base sa kakusog sa hangin nga gilauman sa usa ka lugar."}, "source": "encyclopedia-stable consensus (PAGASA)", "generator": "claude-workflow", "reviewed": false},
  {"id": "storm-signal-one-g6", "domain": "EARTH_SPACE", "topic": "storm signal number 1", "grades": [6, 7], "terms": ["Signal No. 1", "babala", "mahinang hangin", "darating", "36 oras", "storm signal one", "pinakamababa", "senyales 1", "hinay nga hangin", "moabot ang bagyo"], "fact": {"tl": "Ang Signal No. 1 ay ang pinakamababang babala at nangangahulugang may mahinang hanging dala ng bagyo na maaaring dumating sa loob ng 36 na oras.", "en": "Signal No. 1 is the lowest warning and means light winds from a storm may arrive within about 36 hours.", "bis": "Ang Signal No. 1 mao ang pinakaubos nga pasidaan ug nagpasabot nga adunay hinay nga hangin gikan sa bagyo nga moabot sulod sa mga 36 ka oras."}, "source": "encyclopedia-stable consensus (PAGASA)", "generator": "claude-workflow", "reviewed": false},
  {"id": "storm-signal-five-g7", "domain": "EARTH_SPACE", "topic": "storm signal number 5", "grades": [7, 8], "terms": ["Signal No. 5", "pinakamataas", "super typhoon", "napakalakas na hangin", "delikado", "storm signal five", "senyales 5", "pinakakusog", "super bagyo", "makaguba"], "fact": {"tl": "Ang Signal No. 5 ay ang pinakamataas na babala at nangangahulugang may napakalakas na hangin ng super typhoon na maaaring sumira ng maraming bahay.", "en": "Signal No. 5 is the highest warning and means extremely strong super-typhoon winds that can destroy many houses are expected.", "bis": "Ang Signal No. 5 mao ang pinakataas nga pasidaan ug nagpasabot nga adunay kusog kaayo nga hangin sa super typhoon nga makaguba sa daghang balay."}, "source": "encyclopedia-stable consensus (PAGASA)", "generator": "claude-workflow", "reviewed": false},
  {"id": "habagat-monsoon-g6", "domain": "EARTH_SPACE", "topic": "the habagat southwest monsoon", "grades": [6, 7], "terms": ["habagat", "southwest monsoon", "ulan", "Hunyo", "tag-ulan", "maulan", "amihanang-kanluran", "bug-at nga ulan", "habagatang-kasadpan"], "fact": {"tl": "Ang habagat ay ang hanging humihihip mula timog-kanluran tuwing Hunyo hanggang Oktubre at nagdadala ng malakas na ulan sa Pilipinas.", "en": "The habagat is the southwest monsoon wind that blows from June to October and brings heavy rains to the Philippines.", "bis": "Ang habagat mao ang hangin nga mohuyop gikan sa habagatang-kasadpan gikan Hunyo hangtod Oktubre ug nagdala ug kusog nga ulan sa Pilipinas."}, "source": "encyclopedia-stable consensus (PAGASA)", "generator": "claude-workflow", "reviewed": false},
  {"id": "amihan-monsoon-g6", "domain": "EARTH_SPACE", "topic": "the amihan northeast monsoon", "grades": [6, 7], "terms": ["amihan", "northeast monsoon", "malamig", "hangin", "Disyembre", "tag-lamig", "amihanang-silangan", "bugnaw nga hangin", "tugnaw", "amihanang-sidlakan"], "fact": {"tl": "Ang amihan ay ang malamig na hanging humihihip mula hilagang-silangan tuwing Nobyembre hanggang Pebrero, kaya mas malamig ang panahon.", "en": "The amihan is the cool northeast monsoon wind that blows from November to February, making the weather colder.", "bis": "Ang amihan mao ang bugnaw nga hangin nga mohuyop gikan sa amihanang-sidlakan gikan Nobyembre hangtod Pebrero, mao nga mas bugnaw ang panahon."}, "source": "encyclopedia-stable consensus (PAGASA)", "generator": "claude-workflow", "reviewed": false},
  {"id": "wind-cause-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "what causes wind", "grades": [5, 6], "terms": ["hangin", "wind", "init", "lamig", "gumagalaw", "bakit may hangin", "presyon", "what causes wind", "ngano adunay hangin", "init ug bugnaw", "mopuli"], "fact": {"tl": "Nabubuo ang hangin dahil ang mainit na hangin ay pumapaitaas at ang mas malamig na hangin ay pumapalit sa lugar nito.", "en": "Wind is made when warm air rises and cooler air moves in to take its place.", "bis": "Matawo ang hangin tungod kay ang init nga hangin mosaka ug ang mas bugnaw nga hangin mopuli sa pwesto niini."}, "source": "AAAS Benchmarks 4B/H2; 4B/E4", "generator": "claude-workflow", "reviewed": false},
  {"id": "air-is-matter-g4", "domain": "MATTER", "topic": "air is a substance", "grades": [4, 5], "terms": ["hangin", "air", "bagay", "may laman", "pwede maramdaman", "espasyo", "hangin ay bagay", "air takes up space", "adunay gibug-aton", "mabati", "huyop"], "fact": {"tl": "Ang hangin ay isang bagay na nakapaligid sa atin, may timbang, at nararamdaman natin ang paggalaw nito bilang simoy o hangin.", "en": "Air is a real substance that surrounds us, has weight, and we feel its movement as a breeze or wind.", "bis": "Ang hangin usa ka tinuod nga butang nga naglibot kanato, adunay gibug-aton, ug atong mabati ang paglihok niini isip huyop o hangin."}, "source": "AAAS Benchmarks 4B/E4", "generator": "claude-workflow", "reviewed": false},
  {"id": "lightning-what-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "what lightning is", "grades": [5, 6, 7], "terms": ["kidlat", "lightning", "kuryente", "ulap", "spark", "elektrisidad", "ano ang kidlat", "kilat", "kidlap", "elektrisidad", "panganod"], "fact": {"tl": "Ang kidlat ay isang napakalaking kislap ng kuryente na lumalabas sa loob o pagitan ng mga ulap habang may bagyo.", "en": "Lightning is a giant spark of electricity that jumps inside a cloud or between clouds during a storm.", "bis": "Ang kilat usa ka dako kaayo nga kidlap sa kuryente nga molukso sulod o tunga-tunga sa mga panganod panahon sa bagyo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "thunder-after-lightning-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "why thunder comes after lightning", "grades": [5, 6, 7], "terms": ["kulog", "kidlat", "thunder", "lightning", "tunog", "liwanag", "mabilis", "bakit nauuna ang kidlat", "dalugdog", "kilat", "kahayag", "mas paspas ang kahayag"], "fact": {"tl": "Nakikita muna natin ang kidlat bago marinig ang kulog dahil mas mabilis maglakbay ang liwanag kaysa sa tunog.", "en": "We see the lightning before we hear the thunder because light travels much faster than sound.", "bis": "Atong makita una ang kilat sa dili pa madungog ang dalugdog tungod kay ang kahayag mas paspas molakaw kaysa tingog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "thunder-cause-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "what makes thunder", "grades": [6, 7], "terms": ["kulog", "thunder", "init", "hangin", "lumolobo", "kidlat", "tunog", "ano ang sanhi ng kulog", "dalugdog", "init nga hangin", "mopalapad", "tingog"], "fact": {"tl": "Ang kulog ay ang tunog na nalilikha kapag biglang pinapainit at pinapalobo ng kidlat ang hangin sa paligid nito.", "en": "Thunder is the sound made when lightning suddenly heats the air around it and makes the air expand very fast.", "bis": "Ang dalugdog mao ang tingog nga matawo kung ang kilat kalit nga mopainit ug mopalapad sa hangin sa palibot niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rainbow-formation-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "how a rainbow forms", "grades": [5, 6], "terms": ["bahaghari", "rainbow", "sikat ng araw", "patak ng ulan", "kulay", "liwanag", "paano nabubuo ang bahaghari", "balangaw", "kahayag sa adlaw", "tulo sa ulan", "kolor"], "fact": {"tl": "Nabubuo ang bahaghari kapag ang liwanag ng araw ay dumaan sa mga patak ng ulan na humahati nito sa pitong kulay.", "en": "A rainbow forms when sunlight passes through raindrops, which split the light into its seven colors.", "bis": "Matawo ang balangaw kung ang kahayag sa adlaw moagi sa mga tulo sa ulan, nga magbahin sa kahayag ngadto sa pito ka kolor."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rainbow-colors-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "the colors of a rainbow", "grades": [4, 5], "terms": ["bahaghari", "kulay", "rainbow colors", "pula", "lila", "pito", "seven colors", "balangaw", "kolor", "pito ka kolor", "tapul"], "fact": {"tl": "May pitong kulay ang bahaghari: pula, kahel, dilaw, berde, asul, indigo, at lila.", "en": "A rainbow has seven colors: red, orange, yellow, green, blue, indigo, and violet.", "bis": "Ang balangaw adunay pito ka kolor: pula, kahel, dalag, lunhaw, asul, indigo, ug tapul."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "flood-cause-g5", "domain": "EARTH_SPACE", "topic": "what causes floods", "grades": [5, 6], "terms": ["baha", "flood", "malakas na ulan", "umapaw", "ilog", "tubig", "bakit may baha", "what causes floods", "kusog nga ulan", "miawas", "suba"], "fact": {"tl": "Nagkakabaha kapag napakalakas o napakatagal ng ulan kaya ang tubig ay umaapaw mula sa mga ilog at hindi na kayang hugutin ng lupa.", "en": "Floods happen when rain is so heavy or lasts so long that water overflows from rivers and the ground cannot soak it up.", "bis": "Magbaha kung ang ulan kusog kaayo o dugay kaayo mao nga ang tubig moawas gikan sa mga suba ug dili na masuyop sa yuta."}, "source": "AAAS Benchmarks 4B/M7; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "flood-safety-g4", "domain": "EARTH_SPACE", "topic": "staying safe during floods", "grades": [4, 5, 6], "terms": ["baha", "kaligtasan", "flood safety", "mataas na lugar", "iwasan", "tubig-baha", "hindi lalangoy", "safe", "kaluwasan sa baha", "taas nga dapit", "makaanod"], "fact": {"tl": "Kapag may baha, dapat lumipat sa mataas na lugar at iwasang lumakad o maglaro sa umaagos na tubig dahil maaari itong tumangay sa iyo.", "en": "During a flood, you should move to higher ground and avoid walking or playing in moving water because it can sweep you away.", "bis": "Kung magbaha, kinahanglan mobalhin sa mas taas nga dapit ug likayan ang paglakaw o pagdula sa nagdagayday nga tubig kay makaanod kini kanimo."}, "source": "encyclopedia-stable consensus (disaster preparedness)", "generator": "claude-workflow", "reviewed": false},
  {"id": "lightning-safety-g5", "domain": "EARTH_SPACE", "topic": "staying safe from lightning", "grades": [5, 6], "terms": ["kidlat", "kaligtasan", "lightning safety", "pumasok sa loob", "puno", "iwasan", "bagyo", "kilat", "kaluwasan", "sulod sa balay", "likayan ang kahoy"], "fact": {"tl": "Para maligtas sa kidlat, dapat pumasok sa loob ng bahay at iwasang tumayo sa ilalim ng puno o sa bukas na lugar habang may bagyo.", "en": "To stay safe from lightning, go inside a building and avoid standing under a tree or in an open field during a storm.", "bis": "Aron maluwas sa kilat, kinahanglan mosulod sa balay ug likayan ang pagtindog ilalom sa kahoy o sa hawan nga dapit panahon sa bagyo."}, "source": "encyclopedia-stable consensus (disaster preparedness)", "generator": "claude-workflow", "reviewed": false},
  {"id": "storm-surge-g7", "domain": "EARTH_SPACE", "topic": "storm surge", "grades": [7, 8], "terms": ["storm surge", "daluyong", "bagyo", "dagat", "tubig", "pampang", "delikado", "pagtaas ng dagat", "balod sa bagyo", "baybayon", "grabe nga baha"], "fact": {"tl": "Ang storm surge ay ang biglaang pagtaas ng tubig-dagat na itinutulak ng malakas na hangin ng bagyo papunta sa baybayin, at maaari itong magdulot ng matinding baha.", "en": "A storm surge is a sudden rise of seawater pushed onto the coast by a typhoon's strong winds, and it can cause serious flooding.", "bis": "Ang storm surge mao ang kalit nga pagsaka sa tubig-dagat nga gitukmod sa kusog nga hangin sa bagyo ngadto sa baybayon, ug makahimo kini ug grabe nga baha."}, "source": "encyclopedia-stable consensus (PAGASA)", "generator": "claude-workflow", "reviewed": false},
  {"id": "dew-formation-g5", "domain": "EARTH_SPACE", "topic": "how dew forms", "grades": [5, 6], "terms": ["hamog", "dew", "umaga", "dahon", "lumalamig", "singaw", "patak", "paano nabubuo ang hamog", "tun-og", "buntag", "mibugnaw", "alisngaw"], "fact": {"tl": "Ang hamog ay ang maliliit na patak ng tubig na nabubuo sa mga dahon at damo tuwing umaga kapag lumamig ang singaw ng tubig sa hangin.", "en": "Dew is the tiny drops of water that form on leaves and grass in the morning when water vapor in the air cools down.", "bis": "Ang tun-og mao ang gagmayng tinulo sa tubig nga matawo sa mga dahon ug sagbot sa buntag kung mobugnaw ang alisngaw sa hangin."}, "source": "AAAS Benchmarks 4B/E3", "generator": "claude-workflow", "reviewed": false},
  {"id": "fog-formation-g5", "domain": "EARTH_SPACE", "topic": "what fog is", "grades": [5, 6], "terms": ["ulap sa lupa", "fog", "hamog", "malabo", "ulap na mababa", "tubig", "ano ang fog", "gabon", "panganod sa yuta", "hanap"], "fact": {"tl": "Ang fog o makapal na hamog ay parang ulap na nabubuo malapit sa lupa, gawa rin ito ng napakaliliit na patak ng tubig sa hangin.", "en": "Fog is like a cloud that forms close to the ground, and it is also made of tiny droplets of water floating in the air.", "bis": "Ang gabon murag panganod nga matawo duol sa yuta, ug hinimo usab kini sa gagmay kaayong tinulo sa tubig nga naglutaw sa hangin."}, "source": "AAAS Benchmarks 4B/E3", "generator": "claude-workflow", "reviewed": false},
  {"id": "typhoon-naming-g6", "domain": "EARTH_SPACE", "topic": "why typhoons have names", "grades": [6, 7], "terms": ["pangalan ng bagyo", "typhoon names", "PAGASA", "lokal na pangalan", "alpabeto", "bakit may pangalan", "ngalan sa bagyo", "lokal nga ngalan", "masubay", "mailhan"], "fact": {"tl": "Binibigyan ng PAGASA ng pangalan ang mga bagyo na pumapasok sa Pilipinas para madaling matukoy at mabalitaan ng mga tao.", "en": "PAGASA gives each typhoon that enters the Philippines a name so people can easily identify it and follow the news about it.", "bis": "Ang PAGASA naghatag ug ngalan sa matag bagyo nga mosulod sa Pilipinas aron sayon nga mailhan ug masubay sa mga tawo ang balita bahin niini."}, "source": "encyclopedia-stable consensus (PAGASA)", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-covers-earth-g3", "domain": "EARTH_SPACE", "topic": "oceans cover most of Earth", "grades": [3, 4, 5], "terms": ["ocean", "sea", "Earth", "water", "salt water", "dagat", "karagatan", "tubig", "Mundo", "Daigdig", "asin", "tubig-dagat", "lawod", "kadagatan", "natabunan", "natakpan", "saltwater", "blue planet"], "fact": {"tl": "Ang mga karagatan ay tumatakip sa higit sa kalahati ng ibabaw ng Mundo — mga 7 sa bawat 10 bahagi nito. Kaya't kung minsan tinatawag ang Earth na 'blue planet'.", "en": "Oceans cover more than half of Earth's surface — about 7 out of every 10 parts. That is why Earth is sometimes called the 'blue planet'.", "bis": "Ang kadagatan motabon sa labaw sa katunga sa ibabaw sa Kalibotan — mga 7 sa matag 10 ka bahin niini. Mao nga usahay tawgon ang Yuta nga 'blue planet'."}, "source": "AAAS BSL Ch.4B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-saltwater-g3", "domain": "EARTH_SPACE", "topic": "ocean water is salty", "grades": [3, 4, 5], "terms": ["salt", "salty", "ocean water", "sea", "asin", "maalat", "alat", "parat", "tubig-dagat", "dagat", "tubig sa dagat", "lasa", "drink", "hindi mainom", "dili mainom"], "fact": {"tl": "Ang tubig sa dagat ay maalat dahil may natunaw na asin dito, kaya hindi natin ito puwedeng inumin. Ang tubig sa ilog at ulan ay tabang (walang asin).", "en": "Ocean water is salty because it has salt dissolved in it, so we cannot drink it. River water and rain are fresh (without salt).", "bis": "Ang tubig sa dagat parat tungod kay adunay natunaw nga asin niini, mao nga dili nato kini mainom. Ang tubig sa suba ug ulan tab-ang (walay asin)."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-why-salty-g5", "domain": "EARTH_SPACE", "topic": "why the sea is salty", "grades": [5, 6, 7], "terms": ["why salty", "salt comes from", "rivers", "rocks", "bakit maalat", "saan galing asin", "ilog", "bato", "natunaw", "mineral", "ngano parat", "asa gikan asin", "suba", "natanggal", "naipon", "dissolved", "minerals"], "fact": {"tl": "Maalat ang dagat dahil tumatagos ang ulan sa mga bato sa lupa, natutunaw ang mga mineral at asin, at dinadala ng mga ilog ang asin papunta sa dagat. Doon naiipon ito nang milyon-milyong taon.", "en": "The sea is salty because rain wears down rocks on land, dissolving minerals and salt, and rivers carry that salt to the ocean, where it has built up over millions of years.", "bis": "Parat ang dagat tungod kay ang ulan mohugno sa mga bato sa yuta, matunaw ang mga mineral ug asin, ug ang mga suba modala niini ngadto sa dagat, diin naipon kini sulod sa minilyon ka tuig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-deep-g5", "domain": "EARTH_SPACE", "topic": "how deep the ocean is", "grades": [4, 5, 6], "terms": ["deep", "depth", "ocean floor", "lalim", "malalim", "kailaliman", "sahig ng dagat", "lawod", "giladmon", "lawom", "halalom", "ilalom sa dagat", "kilometro", "Mariana Trench", "deepest"], "fact": {"tl": "Napakalalim ng dagat — sa pinakamalalim na bahagi (ang Mariana Trench) umaabot ito ng halos 11 kilometro pababa, mas mataas pa kaysa sa pinakamataas na bundok.", "en": "The ocean is very deep — at its deepest point (the Mariana Trench) it reaches almost 11 kilometers down, deeper than the tallest mountain is tall.", "bis": "Lawom kaayo ang dagat — sa kinalawman nga bahin niini (ang Mariana Trench) moabot kini og halos 11 ka kilometro paubos, mas habog pa kay sa kinatas-ang bukid."}, "source": "AAAS BSL Ch.4B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-deep-sea-dark-g6", "domain": "EARTH_SPACE", "topic": "the deep sea is dark and cold", "grades": [5, 6, 7], "terms": ["deep sea", "dark", "cold", "no sunlight", "madilim", "malamig", "kailaliman", "walang araw", "ilawom sa dagat", "ngitngit", "bugnaw", "walay adlaw", "sunlight", "presyur", "pressure", "deep ocean"], "fact": {"tl": "Sa kailaliman ng dagat ay napakadilim at malamig dahil hindi umaabot doon ang sikat ng araw, at napakabigat ng tubig sa itaas na dumidiin (pressure).", "en": "The deep sea is very dark and cold because sunlight cannot reach it, and the weight of the water above presses down with great pressure.", "bis": "Sa kinahiladman sa dagat ngitngit kaayo ug bugnaw kay dili moabot didto ang silaw sa adlaw, ug bug-at kaayo ang tubig sa ibabaw nga moduot (pressure)."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-deep-sea-creatures-g6", "domain": "LIVING_THINGS", "topic": "deep sea animals make their own light", "grades": [5, 6, 7], "terms": ["deep sea animals", "glow", "bioluminescence", "own light", "kumikinang", "nagliliwanag", "sariling ilaw", "hayop sa kailaliman", "anglerfish", "nagdan-ag", "kaugalingong suga", "mananap sa lawom", "glowing", "light up"], "fact": {"tl": "Maraming hayop sa malalim na dagat ang gumagawa ng sarili nilang ilaw na kumikinang sa dilim — tawag dito ay bioluminescence — para makahanap ng pagkain o makaakit ng biktima.", "en": "Many deep-sea animals make their own glowing light in the dark — this is called bioluminescence — to find food or lure prey.", "bis": "Daghang mananap sa lawom nga dagat ang mohimo og kaugalingong suga nga modan-ag sa ngitngit — gitawag kini og bioluminescence — aron makakita og pagkaon o makadani og tukbonon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-waves-wind-g4", "domain": "EARTH_SPACE", "topic": "ocean waves are made by wind", "grades": [3, 4, 5], "terms": ["wave", "waves", "wind", "alon", "hangin", "balod", "hangin sa dagat", "tubig", "gumagalaw", "nahimo", "naghimo", "humampas", "hampas", "breeze", "ripple", "moving water"], "fact": {"tl": "Ang mga alon sa dagat ay karaniwang gawa ng hangin na humihihip sa ibabaw ng tubig. Habang mas malakas ang hangin, mas malalaki ang alon.", "en": "Ocean waves are usually made by wind blowing across the surface of the water. The stronger the wind, the bigger the waves.", "bis": "Ang mga balod sa dagat kasagaran gibuhat sa hangin nga mohuyop sa ibabaw sa tubig. Kung mas kusog ang hangin, mas dako ang mga balod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-waves-energy-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "waves carry energy not water", "grades": [6, 7, 8], "terms": ["wave energy", "energy", "water does not travel", "enerhiya", "alon", "hindi dinadala ang tubig", "umaalon", "balod", "kusog", "wala mobiya tubig", "moenergy", "carries energy", "transfer", "up and down"], "fact": {"tl": "Ang isang alon ay nagdadala ng enerhiya sa tubig, ngunit hindi talaga umuusad ang mismong tubig — ito ay umaakyat-bumababa lamang habang dumadaan ang enerhiya.", "en": "A wave carries energy through the water, but the water itself does not really travel along — it only moves up and down as the energy passes through.", "bis": "Ang usa ka balod magdala og enerhiya latas sa tubig, apan ang tubig mismo dili gyud mobiyahe — mosaka-mokunsad lang kini samtang moagi ang enerhiya."}, "source": "AAAS BSL Ch.4F; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-tides-moon-g5", "domain": "EARTH_SPACE", "topic": "tides are caused by the moon", "grades": [5, 6, 7], "terms": ["tide", "tides", "moon", "gravity", "taog", "tabsing", "pagtaas ng tubig", "buwan", "hila", "taob", "hunas", "bulan", "pagtaas pagbaba", "high tide", "low tide", "pull", "moon"], "fact": {"tl": "Ang pagtaas at pagbaba ng tubig sa dagat (taog) ay dulot ng hila ng gravity ng buwan. Tinatangay ng buwan ang tubig patungo dito, kaya may mataas at mababang tubig sa baybayin.", "en": "The rise and fall of the sea (the tides) is caused by the pull of the moon's gravity. The moon tugs the water toward it, giving the shore high tide and low tide.", "bis": "Ang pagtaas ug pagkunhod sa dagat (ang taob ug hunas) gipahinabo sa pagbira sa gravity sa bulan. Ang bulan mobira sa tubig paingon niini, mao nga adunay taas ug ubos nga tubig sa baybayon."}, "source": "AAAS BSL Ch.4B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-tides-twice-daily-g6", "domain": "EARTH_SPACE", "topic": "tides happen on a daily cycle", "grades": [6, 7, 8], "terms": ["high tide", "low tide", "twice a day", "tide schedule", "araw-araw", "taog", "dalawang beses", "pagtaas ng tubig", "hunas", "taob", "kaduha sa usa ka adlaw", "matag adlaw", "predictable", "fishermen", "mangingisda", "mananagat"], "fact": {"tl": "Sa karamihan ng lugar, may dalawang mataas na tubig at dalawang mababang tubig sa loob ng isang araw, kaya alam ng mga mangingisda kung kailan tataas o bababa ang tubig.", "en": "In most places there are two high tides and two low tides within a day, so fishermen can predict when the water will rise or fall.", "bis": "Sa kadaghanang lugar, adunay duha ka taas nga tubig ug duha ka ubos nga tubig sulod sa usa ka adlaw, mao nga mahibaw-an sa mga mananagat kung kanus-a motaas o moubos ang tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-currents-g6", "domain": "EARTH_SPACE", "topic": "ocean currents are like rivers in the sea", "grades": [5, 6, 7], "terms": ["ocean current", "current", "agos", "sulog", "agos sa dagat", "tubig na gumagalaw", "daloy", "ilog sa dagat", "moagos", "naglihok nga tubig", "moving water", "stream", "river in the sea", "umaagos"], "fact": {"tl": "Ang ocean currents ay parang malalaking ilog ng tubig na umaagos sa loob ng dagat, na patuloy na gumagalaw sa paligid ng buong mundo.", "en": "Ocean currents are like huge rivers of water flowing within the sea, moving steadily around the whole world.", "bis": "Ang mga sulog sa dagat sama sa dagkong suba sa tubig nga moagos sulod sa dagat, nga padayong molihok palibot sa tibuok kalibotan."}, "source": "AAAS BSL Ch.4B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-currents-climate-g7", "domain": "EARTH_SPACE", "topic": "ocean currents move heat and shape climate", "grades": [7, 8, 9], "terms": ["ocean current", "heat", "climate", "warm cold", "init", "klima", "agos sa dagat", "thermal energy", "mainit malamig", "panahon", "kainit", "klima sa dagat", "moderate", "carries heat", "sulog", "temperatura", "dala init"], "fact": {"tl": "Ang mga ocean current ay nagdadala ng init mula sa mainit na bahagi patungo sa malamig na bahagi ng daigdig, kaya't malaki ang epekto nito sa klima ng mga lugar na malapit sa dagat.", "en": "Ocean currents carry heat from warm parts of the world to cooler parts, so they have a strong effect on the climate of places near the sea.", "bis": "Ang mga sulog sa dagat magdala og init gikan sa mainit nga bahin paingon sa bugnaw nga bahin sa kalibotan, mao nga dako ang epekto niini sa klima sa mga lugar nga duol sa dagat."}, "source": "AAAS BSL Ch.4B/M9, 4B/H2", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-water-cycle-g5", "domain": "EARTH_SPACE", "topic": "the ocean and the water cycle", "grades": [4, 5, 6], "terms": ["water cycle", "evaporate", "rain", "ocean", "siklo ng tubig", "singaw", "sumisingaw", "ulan", "dagat", "tubig", "evaporates", "alisngaw", "moalisngaw", "ulanon", "tinubdan", "fresh water", "saan galing ulan"], "fact": {"tl": "Ang dagat ang pinakamalaking tinubdan ng tubig sa siklo ng tubig — sumisingaw ang tubig mula sa dagat, nagiging ulap, at bumabagsak bilang ulan na muling dumadaloy pabalik sa dagat.", "en": "The ocean is the biggest source of water in the water cycle — water evaporates from the sea, becomes clouds, and falls as rain that flows back to the sea again.", "bis": "Ang dagat mao ang pinakadako nga tinubdan sa tubig sa siklo sa tubig — moalisngaw ang tubig gikan sa dagat, mahimong panganod, ug mahulog isip ulan nga mobalik og agos ngadto sa dagat."}, "source": "AAAS BSL Ch.4B/M7; NRC ESS2.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-coral-reef-animal-g5", "domain": "LIVING_THINGS", "topic": "coral reefs are made by tiny animals", "grades": [4, 5, 6], "terms": ["coral", "coral reef", "polyp", "animal", "bahura", "korales", "munting hayop", "reef", "buhay na hayop", "lumot-dagat", "mananap", "gagmay nga mananap", "puno-coral", "limestone", "bato", "is coral alive"], "fact": {"tl": "Ang coral reef (bahura) ay gawa ng libu-libong maliliit na hayop na tinatawag na coral polyp. Bumubuo sila ng matigas na bahay na bato (limestone) na unti-unting tumutubo sa loob ng maraming taon.", "en": "A coral reef is built by thousands of tiny animals called coral polyps. They make a hard, stony house (limestone) that slowly grows over many years.", "bis": "Ang coral reef (bahura) gibuhat sa liboan ka gagmayng mananap nga gitawag og coral polyps. Maghimo sila og gahi nga balay nga bato (limestone) nga hinay-hinay nga motubo sulod sa daghang tuig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-coral-reef-home-g4", "domain": "LIVING_THINGS", "topic": "coral reefs shelter many sea animals", "grades": [3, 4, 5], "terms": ["coral reef", "fish", "home", "shelter", "bahura", "isda", "tahanan", "tirahan", "reef", "puy-anan", "tagoanan", "mananap sa dagat", "biodiversity", "rainforest of the sea", "maraming isda", "daghang isda"], "fact": {"tl": "Ang coral reef ay tahanan ng napakaraming uri ng isda at hayop-dagat, kaya minsan tinatawag itong 'rainforest ng dagat' dahil sa dami ng buhay doon.", "en": "A coral reef is home to a great many kinds of fish and sea animals, so it is sometimes called the 'rainforest of the sea' because of all the life there.", "bis": "Ang coral reef puy-anan sa daghan kaayong matang sa isda ug mananap sa dagat, mao nga usahay tawgon kini og 'rainforest sa dagat' tungod sa kadaghan sa kinabuhi didto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-coral-bleaching-g7", "domain": "LIVING_THINGS", "topic": "warm water harms coral reefs", "grades": [7, 8, 9], "terms": ["coral bleaching", "warm water", "coral dies", "namumuti", "namatay na bahura", "mainit na tubig", "bleaching", "naputi", "namatay", "init nga tubig", "mamatay coral", "stress", "white coral", "climate change", "init sa dagat"], "fact": {"tl": "Kapag sumosobra ang init ng tubig-dagat, namumuti ang coral (coral bleaching) at maaaring mamatay, dahil iniiwan ito ng maliliit na halaman (algae) na nagbibigay dito ng pagkain at kulay.", "en": "When the sea water gets too warm, coral turns white (coral bleaching) and can die, because the tiny algae that give it food and color leave it.", "bis": "Kung sobra na ang kainit sa tubig-dagat, mamuti ang coral (coral bleaching) ug mahimong mamatay, kay biyaan kini sa gagmayng tanom (algae) nga maghatag niini og pagkaon ug kolor."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-mangrove-roots-g5", "domain": "LIVING_THINGS", "topic": "mangroves grow in salty coastal water", "grades": [4, 5, 6], "terms": ["mangrove", "bakawan", "roots", "salt water", "coast", "ugat", "tubig-alat", "baybayin", "bakhaw", "gamot", "parat nga tubig", "baybayon", "gamot sa bakhaw", "tumutubo", "saltwater tree", "puno sa baybayin"], "fact": {"tl": "Ang bakawan (mangrove) ay mga punong tumutubo sa maalat na tubig sa baybayin. May mga ugat itong nakausli sa tubig na tumutulong dito na huminga at manatiling matatag sa putik.", "en": "Mangroves are trees that grow in salty water along the coast. They have roots that stick up out of the water to help them breathe and stay anchored in the mud.", "bis": "Ang bakhaw (mangrove) mga kahoy nga motubo sa parat nga tubig sa baybayon. Adunay mga gamot kini nga motungha sa tubig nga motabang niini nga makaginhawa ug mokupot sa lapok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-mangrove-protect-g6", "domain": "LIVING_THINGS", "topic": "mangroves protect the coast", "grades": [5, 6, 7], "terms": ["mangrove", "protect coast", "storm", "waves", "bakawan", "proteksyon", "bagyo", "alon", "baybayin", "bakhaw", "panalipod", "balod", "nursery", "isda", "habagat", "fish nursery", "erosion", "shore protection"], "fact": {"tl": "Pinipigilan ng bakawan ang malalakas na alon at bagyo na sirain ang baybayin, at nagsisilbi itong ligtas na pugad kung saan lumalaki ang maliliit na isda at hipon.", "en": "Mangroves hold back strong waves and storms from damaging the coast, and they serve as a safe nursery where young fish and shrimp grow.", "bis": "Ang bakhaw mopugong sa kusog nga balod ug bagyo nga makadaot sa baybayon, ug nagsilbi kini nga luwas nga pasilonganan diin motubo ang gagmayng isda ug pasayan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-zones-sunlight-g6", "domain": "EARTH_SPACE", "topic": "sunlight only reaches the top of the ocean", "grades": [6, 7, 8], "terms": ["sunlight ocean", "surface", "depth", "ilaw ng araw", "ibabaw", "lalim", "patong", "silaw sa adlaw", "ibabaw sa dagat", "giladmon", "moabot", "tuhop", "layers", "zone", "top layer", "plankton"], "fact": {"tl": "Umaabot lamang ang sikat ng araw sa pinakaibabaw na bahagi ng dagat (mga unang daan-daang metro), kaya doon nakatira ang halos lahat ng halaman-dagat na kailangan ng liwanag.", "en": "Sunlight reaches only the top part of the ocean (the first few hundred meters), so almost all sea plants that need light live there.", "bis": "Ang silaw sa adlaw moabot lamang sa kinaibabwang bahin sa dagat (ang unang pipila ka gatos ka metro), mao nga didto nagpuyo halos tanang tanom-dagat nga nagkinahanglan og kahayag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-plankton-base-g7", "domain": "LIVING_THINGS", "topic": "plankton feed the ocean and make oxygen", "grades": [6, 7, 8], "terms": ["plankton", "phytoplankton", "oxygen", "food chain", "hangin", "pagkain", "base", "gagmayng tanom", "pagkaon", "tinubdan", "tiny", "microscopic", "kadena ng pagkain", "naghimo oxygen"], "fact": {"tl": "Ang plankton ay napakaliliit na halaman at hayop na lumulutang sa dagat. Ang halaman-plankton ay gumagawa ng malaking bahagi ng oxygen sa mundo at sila ang pinakapundasyon ng pagkain sa dagat.", "en": "Plankton are very tiny plants and animals that drift in the sea. Plant plankton make a large share of the world's oxygen and are the base of the ocean's food chain.", "bis": "Ang plankton mga gagmay kaayong tanom ug mananap nga magpalutaw sa dagat. Ang tanom-plankton mohimo og dakong bahin sa oxygen sa kalibotan ug sila ang pundasyon sa pagkaon sa dagat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-sea-vs-ocean-g4", "domain": "EARTH_SPACE", "topic": "difference between a sea and an ocean", "grades": [4, 5, 6], "terms": ["sea ocean difference", "sea", "ocean", "dagat karagatan", "pagkakaiba", "dagat", "karagatan", "mas maliit", "kalainan", "kadagatan", "mas gamay", "smaller", "bigger", "partly enclosed", "land"], "fact": {"tl": "Ang karagatan (ocean) ay napakalawak na anyong-tubig, habang ang dagat (sea) ay mas maliit at kadalasang bahagyang napaliligiran ng lupa. Ang dagat ay karaniwang bahagi ng isang mas malaking karagatan.", "en": "An ocean is a very large body of water, while a sea is smaller and often partly surrounded by land. A sea is usually part of a larger ocean.", "bis": "Ang karagatan (ocean) usa ka halapad kaayong tubig, samtang ang dagat (sea) mas gamay ug kasagaran napalibutan og bahin sa yuta. Ang dagat kasagaran bahin sa usa ka mas dakong karagatan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-five-oceans-g5", "domain": "EARTH_SPACE", "topic": "Earth has five oceans", "grades": [4, 5, 6], "terms": ["five oceans", "Pacific", "Atlantic", "ocean names", "limang karagatan", "Pasipiko", "pangalan ng karagatan", "lima ka kadagatan", "pinakamalaki", "Indian", "Arctic", "Philippines", "Pilipinas", "biggest ocean"], "fact": {"tl": "May limang karagatan sa mundo: Pacific, Atlantic, Indian, Arctic, at Southern. Ang Pacific ang pinakamalaki at pinakamalalim, at ito ang dagat na nasa silangan ng Pilipinas.", "en": "Earth has five oceans: the Pacific, Atlantic, Indian, Arctic, and Southern. The Pacific is the largest and deepest, and it is the ocean to the east of the Philippines.", "bis": "Adunay lima ka kadagatan sa kalibotan: Pacific, Atlantic, Indian, Arctic, ug Southern. Ang Pacific mao ang pinakadako ug pinakalawom, ug mao kini ang dagat sa sidlakan sa Pilipinas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-tsunami-not-tide-g6", "domain": "EARTH_SPACE", "topic": "tsunamis are not ordinary waves", "grades": [6, 7, 8], "terms": ["tsunami", "earthquake", "giant wave", "lindol", "malaking alon", "linog", "dakong balod", "daluyong", "underwater earthquake", "seabed", "PHIVOLCS", "not a tide", "lindol sa dagat"], "fact": {"tl": "Ang tsunami ay hindi karaniwang alon na gawa ng hangin — ito ay dulot ng malakas na lindol o pagsabog sa ilalim ng dagat, na nagtataas ng higanteng alon na humahampas sa baybayin.", "en": "A tsunami is not an ordinary wind-made wave — it is caused by a strong earthquake or eruption under the sea, which raises a giant wave that crashes onto the shore.", "bis": "Ang tsunami dili ordinaryong balod nga gibuhat sa hangin — gipahinabo kini sa kusog nga linog o pagbuto ilalom sa dagat, nga mopataas og dakong balod nga mohampak sa baybayon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-floor-mountains-g7", "domain": "EARTH_SPACE", "topic": "the ocean floor has mountains and trenches", "grades": [7, 8, 9], "terms": ["ocean floor", "underwater mountains", "trench", "sahig ng dagat", "bundok sa ilalim", "kanal", "lambak", "salog sa dagat", "bukid ilalom sa dagat", "ridge", "volcano", "bulkan", "seamount", "not flat", "ocean basin"], "fact": {"tl": "Hindi patag ang ilalim ng dagat — may mga matataas na bundok, bulkan, at napakalalim na kanal (trench) na nabuo dahil sa paggalaw ng mga plate ng Earth.", "en": "The ocean floor is not flat — it has tall mountains, volcanoes, and very deep trenches formed by the movement of Earth's plates.", "bis": "Ang salog sa dagat dili patag — adunay habog nga bukid, bulkan, ug lawom kaayong kanal (trench) nga naporma tungod sa paglihok sa mga plate sa Yuta."}, "source": "AAAS BSL Ch.4C/M1, 4C/H5", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-islands-from-sea-g7", "domain": "EARTH_SPACE", "topic": "volcanic islands rise from the sea floor", "grades": [7, 8, 9], "terms": ["volcanic island", "island forms", "sea floor volcano", "isla", "pulo", "bulkan sa dagat", "paano nabuo isla", "bulkan", "natumpok", "naporma isla", "Philippines islands", "undersea volcano", "lava"], "fact": {"tl": "May mga isla na nabuo mula sa mga bulkan sa ilalim ng dagat — habang umaapaw ang lava at lumalamig, unti-unti itong tumataas hanggang umusli ito sa ibabaw ng tubig bilang isla.", "en": "Some islands form from volcanoes on the sea floor — as lava erupts and cools, it slowly builds up until it pokes above the water as an island.", "bis": "Adunay mga isla nga naporma gikan sa mga bulkan sa ilalom sa dagat — samtang mobuhagay ang lava ug mobugnaw, hinay-hinay kining motumpok hangtod motungha kini sa ibabaw sa tubig isip isla."}, "source": "AAAS BSL Ch.4C/H5", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-pollution-plastic-g6", "domain": "LIVING_THINGS", "topic": "plastic pollution harms ocean animals", "grades": [5, 6, 7], "terms": ["ocean pollution", "plastic", "harm animals", "polusyon sa dagat", "plastik", "basura", "nakakasama", "polusyon", "basura sa dagat", "makadaot", "pawikan", "isda", "turtle", "marine life", "trash", "protect the sea"], "fact": {"tl": "Ang basurang plastik na natatapon sa dagat ay nakakasama sa mga hayop-dagat — minsan kinakain ito ng mga pawikan at isda dahil akala nila ay pagkain, na maaaring ikamatay nila.", "en": "Plastic trash thrown into the sea harms ocean animals — sometimes turtles and fish eat it thinking it is food, which can kill them.", "bis": "Ang basurang plastik nga ilabay sa dagat makadaot sa mga mananap-dagat — usahay kan-on kini sa mga pawikan ug isda kay abi nila pagkaon, nga mahimong makamatay kanila."}, "source": "AAAS BSL Ch.4B/M11; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-stores-heat-g8", "domain": "EARTH_SPACE", "topic": "the ocean stores a lot of heat", "grades": [7, 8, 9], "terms": ["ocean heat", "stores heat", "temperature", "init ng dagat", "nag-iimbak ng init", "temperatura", "init", "tipigan init", "dagat motipig init", "moderate climate", "warms slowly", "thermal energy", "moderate temperature", "coastal"], "fact": {"tl": "Ang dagat ay nakakapag-imbak ng napakaraming init, kaya mas mabagal itong uminit at lumamig kaysa sa lupa. Dahil dito, mas katamtaman ang temperatura sa mga lugar na malapit sa dagat.", "en": "The ocean can store a great deal of heat, so it warms and cools more slowly than land. Because of this, places near the sea have more moderate temperatures.", "bis": "Ang dagat makatipig og daghan kaayong init, mao nga mas hinay kini moinit ug mobugnaw kay sa yuta. Tungod niini, mas kasarangan ang temperatura sa mga lugar nga duol sa dagat."}, "source": "AAAS BSL Ch.4B/M9, 4B/M12", "generator": "claude-workflow", "reviewed": false},
  {"id": "what-is-rock-g3", "domain": "EARTH_SPACE", "topic": "what is a rock", "grades": [3, 4], "terms": ["bato", "batong", "mineral", "minerales", "rock", "stone", "tigas", "matig-a", "gawa", "hinimo", "nahuman", "lupa", "yuta"], "fact": {"tl": "Ang bato ay isang matigas na natural na bagay na binubuo ng isa o higit pang mineral.", "en": "A rock is a hard, natural solid made of one or more minerals.", "bis": "Ang bato usa ka gahi nga natural nga butang nga hinimo gikan sa usa o daghang mineral."}, "source": "AAAS BSL 4C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "what-is-mineral-g4", "domain": "EARTH_SPACE", "topic": "what is a mineral", "grades": [4, 5, 6], "terms": ["mineral", "minerales", "kristal", "crystal", "kristales", "natural", "elemento", "buo", "solid", "bato", "bahin"], "fact": {"tl": "Ang mineral ay isang natural na solidong bagay na may tiyak na kemikal at karaniwang may kristal na hugis; ang mga bato ay binubuo ng mga mineral.", "en": "A mineral is a natural solid with a definite chemical makeup and usually a crystal shape; rocks are made of minerals.", "bis": "Ang mineral usa ka natural nga solidong butang nga adunay piho nga kemikal ug kasagaran adunay porma sa kristal; ang mga bato hinimo gikan sa mineral."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "three-rock-types-g5", "domain": "EARTH_SPACE", "topic": "three types of rocks", "grades": [5, 6, 7], "terms": ["uri ng bato", "tatlong uri", "klase sa bato", "tulo ka klase", "igneous", "sedimentary", "metamorphic", "rock types", "bato", "klasipikasyon"], "fact": {"tl": "May tatlong pangunahing uri ng bato: igneous, sedimentary, at metamorphic, ayon sa kung paano sila nabuo.", "en": "There are three main kinds of rock — igneous, sedimentary, and metamorphic — based on how they form.", "bis": "Adunay tulo ka nag-unang klase sa bato: igneous, sedimentary, ug metamorphic, base kung giunsa sila pagkahimo."}, "source": "AAAS BSL 4C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "igneous-rock-g5", "domain": "EARTH_SPACE", "topic": "igneous rock", "grades": [5, 6, 7], "terms": ["igneous", "bulkan", "bulkang bato", "lava", "magma", "tunaw", "natunaw", "nagbugnaw", "lumamig", "tumigas", "bulkanikong", "volcano"], "fact": {"tl": "Ang igneous na bato ay nabubuo kapag lumamig at tumigas ang tunaw na bato (magma o lava), tulad ng basalt at granite.", "en": "Igneous rock forms when melted rock (magma or lava) cools and hardens, such as basalt and granite.", "bis": "Ang igneous nga bato mabuhat kung mobugnaw ug mogahi ang natunaw nga bato (magma o lava), sama sa basalt ug granite."}, "source": "AAAS BSL 4C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sedimentary-rock-g6", "domain": "EARTH_SPACE", "topic": "sedimentary rock", "grades": [5, 6, 7], "terms": ["sedimentary", "latak", "sediment", "buhangin", "balas", "patong", "naipon", "nagtipon", "nagdikit", "layers", "sandstone", "limestone"], "fact": {"tl": "Ang sedimentary na bato ay nabubuo kapag ang buhangin, putik, at maliliit na piraso ay naiipon, nabubaon, at dumidikit sa loob ng mahabang panahon, tulad ng sandstone at limestone.", "en": "Sedimentary rock forms when sand, mud, and small bits pile up, get buried, and cement together over long times, such as sandstone and limestone.", "bis": "Ang sedimentary nga bato mabuhat kung ang balas, lapok, ug gagmay nga piraso magtigom, malubong, ug magdikit sulod sa taas nga panahon, sama sa sandstone ug limestone."}, "source": "AAAS BSL 4C/M3", "generator": "claude-workflow", "reviewed": false},
  {"id": "metamorphic-rock-g6", "domain": "EARTH_SPACE", "topic": "metamorphic rock", "grades": [6, 7, 8], "terms": ["metamorphic", "init", "kainitan", "presyon", "diin", "nagbago", "nausab", "nag-anyo", "heat", "pressure", "marble", "slate", "transformed"], "fact": {"tl": "Ang metamorphic na bato ay nagagawa kapag ang dati nang bato ay nababago ng matinding init at presyon nang hindi natutunaw, tulad ng marble at slate.", "en": "Metamorphic rock forms when existing rock is changed by great heat and pressure without fully melting, such as marble and slate.", "bis": "Ang metamorphic nga bato mabuhat kung ang naa nang bato mausab tungod sa kusog nga init ug presyon nga dili matunaw, sama sa marble ug slate."}, "source": "AAAS BSL 4C/M4", "generator": "claude-workflow", "reviewed": false},
  {"id": "rock-cycle-g6", "domain": "EARTH_SPACE", "topic": "the rock cycle", "grades": [6, 7, 8], "terms": ["rock cycle", "siklo ng bato", "siklo sa bato", "ikot", "umiikot", "nagbago", "nausab", "paulit-ulit", "padayon", "transform", "cycle"], "fact": {"tl": "Sa rock cycle, ang mga bato ay patuloy na nagbabago mula sa isang uri patungo sa iba sa pamamagitan ng init, presyon, weathering, at pagtigas — at nananatiling pareho ang kabuuang dami ng materyal.", "en": "In the rock cycle, rocks slowly change from one type to another through heat, pressure, weathering, and hardening, while the total amount of material stays the same.", "bis": "Sa rock cycle, ang mga bato hinay-hinay nga mausab gikan sa usa ka klase ngadto sa lain pinaagi sa init, presyon, weathering, ug paggahi, samtang ang kinatibuk-ang gidaghanon sa materyal magpabilin nga pareho."}, "source": "AAAS BSL 4C/H2", "generator": "claude-workflow", "reviewed": false},
  {"id": "weathering-rock-g5", "domain": "EARTH_SPACE", "topic": "weathering of rock", "grades": [4, 5, 6], "terms": ["weathering", "pagkasira", "nasisira", "nadudurog", "nagkapino", "naguba", "ulan", "tubig", "init", "hangin", "lamig", "break down"], "fact": {"tl": "Ang weathering ay ang dahan-dahang pagkasira at pagkadurog ng bato dahil sa tubig, hangin, init, at lamig.", "en": "Weathering is the slow breaking down of rock by water, wind, heat, and cold.", "bis": "Ang weathering mao ang hinay nga pagkaguba ug pagkadugmok sa bato tungod sa tubig, hangin, init, ug bugnaw."}, "source": "AAAS BSL 4C/M2b", "generator": "claude-workflow", "reviewed": false},
  {"id": "erosion-rock-g5", "domain": "EARTH_SPACE", "topic": "erosion", "grades": [4, 5, 6], "terms": ["erosion", "erosyon", "natatangay", "nadadala", "naanod", "nadala", "pagguho", "ilog", "tubig", "hangin", "yelo", "river", "carry away", "lupa"], "fact": {"tl": "Ang erosion ay ang pagdadala ng mga durog na bato at lupa palayo ng tubig, hangin, o yelo patungo sa ibang lugar.", "en": "Erosion is the carrying away of broken rock and soil by water, wind, or ice to another place.", "bis": "Ang erosion mao ang pagdala sa nadugmok nga bato ug yuta palayo pinaagi sa tubig, hangin, o yelo ngadto sa laing lugar."}, "source": "AAAS BSL 4C/M2b", "generator": "claude-workflow", "reviewed": false},
  {"id": "what-is-fossil-g3", "domain": "EARTH_SPACE", "topic": "what is a fossil", "grades": [3, 4, 5], "terms": ["fossil", "fosil", "labi", "nahabilin", "buto", "bukog", "tanim", "hayop", "nakatago", "natipon", "bato", "lumang", "karaan", "remains", "preserved"], "fact": {"tl": "Ang fossil ay ang naiwang bakas o labi ng halaman o hayop na matagal nang nabuhay, na napreserba sa loob ng bato.", "en": "A fossil is the preserved trace or remains of a plant or animal that lived long ago, kept inside rock.", "bis": "Ang fossil mao ang nahibilin nga timaan o lawas sa tanom o hayop nga dugay nang nabuhi, nga natipigan sulod sa bato."}, "source": "AAAS BSL 4C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "how-fossils-form-g6", "domain": "EARTH_SPACE", "topic": "how fossils form", "grades": [5, 6, 7, 8], "terms": ["fossil", "fosil", "paano nabuo", "giunsa pagkahimo", "natabunan", "nalubong", "putik", "buhangin", "naipon", "mineral", "tumigas", "sedimentary", "natipon", "buried"], "fact": {"tl": "Karaniwang nabubuo ang fossil kapag ang isang patay na halaman o hayop ay mabilis na natatabunan ng putik o buhangin, at sa paglipas ng panahon ay pinapalitan ng mineral ang mga buto nito sa loob ng sedimentary na bato.", "en": "Fossils usually form when a dead plant or animal is quickly buried in mud or sand, and over long times minerals replace its parts inside sedimentary rock.", "bis": "Ang fossil kasagarang mabuhat kung ang patay nga tanom o hayop dali nga matabonan og lapok o balas, ug sa paglabay sa panahon, ang mineral mopuli sa mga bahin niini sulod sa sedimentary nga bato."}, "source": "AAAS BSL 4C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fossils-tell-past-g6", "domain": "EARTH_SPACE", "topic": "what fossils tell us", "grades": [6, 7, 8], "terms": ["fossil", "fosil", "kasaysayan", "kagahapon", "kaniadto", "dinosaur", "buhay noon", "nabuhi", "ebidensya", "patunay", "ebidensiya", "nawala", "extinct", "history"], "fact": {"tl": "Sinasabi sa atin ng mga fossil kung anong mga halaman at hayop ang nabuhay noong unang panahon, kabilang ang mga dinosaur, at kung paano nagbago ang buhay sa Earth.", "en": "Fossils tell us what plants and animals lived in the distant past, including dinosaurs, and how life on Earth has changed.", "bis": "Ang mga fossil mosulti kanato kung unsang mga tanom ug hayop ang nabuhi kaniadto, lakip ang mga dinosaur, ug kung giunsa pagbag-o sa kinabuhi sa Yuta."}, "source": "AAAS BSL 4C/M5", "generator": "claude-workflow", "reviewed": false},
  {"id": "rock-layers-age-g7", "domain": "EARTH_SPACE", "topic": "rock layers and age", "grades": [6, 7, 8], "terms": ["rock layers", "patong ng bato", "patong sa bato", "kapal", "edad", "tanda", "gulang", "ilalim", "ubos", "ibabaw", "matanda", "tigulang", "younger", "older", "strata"], "fact": {"tl": "Sa mga patong ng sedimentary na bato, kadalasang mas matanda ang nasa ilalim na patong kaysa nasa itaas, kaya nakikita natin ang pagkakasunod-sunod ng buhay sa nakaraan.", "en": "In layers of sedimentary rock, the lower layers are usually older than the ones on top, so we can read the order in which past life appeared.", "bis": "Sa mga patong sa sedimentary nga bato, ang mga ubos nga patong kasagarang mas tigulang kaysa sa naa sa ibabaw, busa atong mabasa ang sunod-sunod sa kinabuhi kaniadto."}, "source": "AAAS BSL 4C/M5", "generator": "claude-workflow", "reviewed": false},
  {"id": "what-is-gemstone-g4", "domain": "EARTH_SPACE", "topic": "what is a gemstone", "grades": [4, 5, 6], "terms": ["gemstone", "gem", "hiyas", "alahas", "batong mahalaga", "mahal", "kumikinang", "nagkidlap", "kristal", "magandang", "diamond", "ruby", "precious stone"], "fact": {"tl": "Ang gemstone o hiyas ay isang bihira at magandang mineral na pinuputol at pinakikintab para gawing alahas, tulad ng diamond at ruby.", "en": "A gemstone is a rare, beautiful mineral that is cut and polished to make jewelry, such as diamond and ruby.", "bis": "Ang gemstone usa ka talagsaon ug nindot nga mineral nga giputol ug gipasinaw aron himoong alahas, sama sa diamond ug ruby."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "diamond-hardest-g5", "domain": "EARTH_SPACE", "topic": "diamond hardness", "grades": [5, 6, 7], "terms": ["diamond", "diyamante", "brilyante", "carbon", "karbon", "pinakamatigas", "pinakagahi", "tigas", "init", "lalim", "ilalim ng lupa", "hardest", "mineral"], "fact": {"tl": "Ang diamond ay gawa sa carbon at ito ang pinakamatigas na natural na mineral sa Earth, na nabuo sa ilalim ng matinding init at presyon.", "en": "Diamond is made of carbon and is the hardest natural mineral on Earth, formed deep underground under great heat and pressure.", "bis": "Ang diamond hinimo gikan sa carbon ug mao ang pinakagahi nga natural nga mineral sa Yuta, nabuhat sa lawom nga yuta ubos sa kusog nga init ug presyon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mohs-hardness-g7", "domain": "EARTH_SPACE", "topic": "mineral hardness scale", "grades": [7, 8, 9], "terms": ["hardness", "tigas", "katigasan", "kagahi", "Mohs", "sukat", "iskala", "talc", "diamond", "gasgas", "scratch", "magasgasan", "mineral", "scale"], "fact": {"tl": "Sinusukat ng Mohs hardness scale ang tigas ng mineral mula 1 (pinakamalambot, talc) hanggang 10 (pinakamatigas, diamond), batay sa kung alin ang nakakagasgas sa iba.", "en": "The Mohs hardness scale rates a mineral's hardness from 1 (softest, talc) to 10 (hardest, diamond), based on which can scratch the other.", "bis": "Ang Mohs hardness scale nagsukod sa kagahi sa mineral gikan sa 1 (pinakahumok, talc) ngadto sa 10 (pinakagahi, diamond), base kung kinsa ang makagasgas sa lain."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "soil-from-rock-g4", "domain": "EARTH_SPACE", "topic": "soil comes from rock", "grades": [4, 5, 6], "terms": ["soil", "lupa", "yuta", "graba", "bato", "nadurog", "nadugmok", "weathering", "pino", "halaman", "naagnas", "organic", "nabulok", "comes from"], "fact": {"tl": "Ang lupa ay nabubuo mula sa mga bato na unti-unting nadudurog, na pinaghahalo ng mga naagnas na halaman at hayop.", "en": "Soil forms from rock that slowly breaks down, mixed with rotted plants and animals.", "bis": "Ang yuta mabuhat gikan sa mga bato nga hinay-hinay nga madugmok, nga sagol sa nadunot nga mga tanom ug hayop."}, "source": "AAAS BSL 4C/M6", "generator": "claude-workflow", "reviewed": false},
  {"id": "topsoil-living-g4", "domain": "EARTH_SPACE", "topic": "topsoil and living things", "grades": [4, 5, 6], "terms": ["topsoil", "ibabaw na lupa", "humus", "bulate", "wati", "uod", "fungi", "bacteria", "ugat", "gamot", "tabunok", "fertile", "mataba", "halaman", "worms"], "fact": {"tl": "Ang topsoil ay puno ng buhay tulad ng mga bulate, fungi, at ugat na nagpapataba nito at tumutulong sa paglaki ng halaman.", "en": "Topsoil is full of life such as worms, fungi, and roots that make it fertile and help plants grow.", "bis": "Ang topsoil puno sa kinabuhi sama sa mga wati, fungi, ug gamot nga maghimo niini nga tabunok ug motabang sa pagtubo sa mga tanom."}, "source": "AAAS BSL 4C/M6", "generator": "claude-workflow", "reviewed": false},
  {"id": "rock-uses-g4", "domain": "EARTH_SPACE", "topic": "how people use rocks and minerals", "grades": [4, 5, 6], "terms": ["bato", "mineral", "gamit", "gigamit", "ginagamit", "bahay", "balay", "kalsada", "dalan", "semento", "graba", "metal", "bakal", "build", "resource"], "fact": {"tl": "Gumagamit ang mga tao ng mga bato at mineral para magtayo ng bahay at kalsada, gumawa ng semento at salamin, at kumuha ng mga metal tulad ng bakal at tanso.", "en": "People use rocks and minerals to build houses and roads, make cement and glass, and get metals like iron and copper.", "bis": "Ang mga tawo mogamit og mga bato ug mineral aron magtukod og balay ug dalan, maghimo og semento ug bildo, ug magkuha og mga metal sama sa puthaw ug tumbaga."}, "source": "AAAS BSL 4B/H8; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "limestone-shells-g6", "domain": "EARTH_SPACE", "topic": "limestone from shells", "grades": [6, 7, 8], "terms": ["limestone", "apog", "batong apog", "kabibe", "shell", "kabhang", "korales", "coral", "dagat", "naipon", "calcium", "Bohol", "Chocolate Hills", "sedimentary"], "fact": {"tl": "Ang limestone ay isang sedimentary na bato na kadalasang nabuo mula sa naipong mga kabibe at korales sa ilalim ng dagat, at makikita ito sa mga lugar tulad ng Bohol.", "en": "Limestone is a sedimentary rock often formed from piled-up shells and coral on the sea floor, and is found in places like Bohol.", "bis": "Ang limestone usa ka sedimentary nga bato nga kasagarang nabuhat gikan sa natipon nga mga kabhang ug coral sa ilawom sa dagat, ug makita kini sa mga dapit sama sa Bohol."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "volcanic-soil-fertile-g6", "domain": "EARTH_SPACE", "topic": "fertile volcanic soil", "grades": [5, 6, 7], "terms": ["bulkan", "volcano", "abo", "abog", "ash", "lupa", "yuta", "mataba", "tabunok", "mayaman", "mineral", "Pinatubo", "Mayon", "taniman", "fertile", "volcanic"], "fact": {"tl": "Ang lupa malapit sa mga bulkan tulad ng Mayon ay madalas matabang sakahan dahil mayaman sa mineral ang abo ng bulkan.", "en": "Soil near volcanoes like Mayon is often rich farmland because volcanic ash is full of minerals.", "bis": "Ang yuta duol sa mga bulkan sama sa Mayon kasagarang tabunok nga umahan tungod kay ang abo sa bulkan dato sa mineral."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "crystals-form-g6", "domain": "EARTH_SPACE", "topic": "how crystals form", "grades": [6, 7, 8], "terms": ["kristal", "crystal", "kristales", "hugis", "porma", "sulok", "gilid", "lumamig", "nagbugnaw", "natuyo", "naipon", "mineral", "quartz", "asin", "form"], "fact": {"tl": "Nabubuo ang mga kristal kapag ang mga mineral ay dahan-dahang lumalamig o natutuyo, na nag-aayos ng kanilang mga atomo sa maayos at paulit-ulit na hugis.", "en": "Crystals form when minerals slowly cool or dry, arranging their atoms into a neat, repeating shape.", "bis": "Ang mga kristal mabuhat kung ang mga mineral hinay-hinay nga mobugnaw o momala, nga mag-ayos sa ilang mga atomo ngadto sa hapsay ug balik-balik nga porma."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "amber-fossil-g6", "domain": "EARTH_SPACE", "topic": "amber and trapped insects", "grades": [6, 7, 8], "terms": ["amber", "dagta", "resin", "puno", "kahoy", "tumigas", "natuyo", "insekto", "insect", "langgam", "lamok", "nabilanggo", "natipon", "fossil", "tree sap"], "fact": {"tl": "Ang amber ay tumigas na dagta ng sinaunang puno, at minsan may nakulong na mga insekto rito na naging fossil.", "en": "Amber is hardened tree resin from ancient trees, and it sometimes traps insects that become fossils.", "bis": "Ang amber mao ang gahi nga dagta sa karaang kahoy, ug usahay adunay nabilanggo nga mga insekto niini nga nahimong fossil."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "metals-from-ore-g7", "domain": "EARTH_SPACE", "topic": "metals come from ore", "grades": [7, 8, 9], "terms": ["ore", "mina", "minahan", "mining", "metal", "bakal", "puthaw", "ginto", "tumbaga", "tanso", "kinukuha", "ginakuha", "bato", "mineral", "extract"], "fact": {"tl": "Karamihan sa mga metal tulad ng bakal, tanso, at ginto ay nakukuha mula sa mga espesyal na bato na tinatawag na ore sa pamamagitan ng pagmimina.", "en": "Most metals like iron, copper, and gold are taken from special rocks called ore through mining.", "bis": "Kadaghanan sa mga metal sama sa puthaw, tumbaga, ug bulawan makuha gikan sa pinasahi nga mga bato nga gitawag og ore pinaagi sa pagmina."}, "source": "AAAS BSL 4B/H8; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rocks-very-old-g5", "domain": "EARTH_SPACE", "topic": "rocks are very old", "grades": [5, 6, 7], "terms": ["bato", "rock", "tanda", "edad", "gulang", "tigulang", "milyong taon", "milyon ka tuig", "matagal", "dugay", "kasaysayan", "Earth", "old", "ancient"], "fact": {"tl": "Maraming bato ay milyon-milyong taong gulang, kaya itinuturing silang mga rekord ng mahabang kasaysayan ng Earth.", "en": "Many rocks are millions of years old, so they act as records of Earth's long history.", "bis": "Daghang bato ang milyon-milyon ka tuig na ang edad, busa sila nagsilbing rekord sa taas nga kasaysayan sa Yuta."}, "source": "AAAS BSL 4C/M5", "generator": "claude-workflow", "reviewed": false},
  {"id": "petrified-wood-g7", "domain": "EARTH_SPACE", "topic": "petrified wood fossils", "grades": [7, 8], "terms": ["petrified", "natutong bato", "nahimong bato", "kahoy", "wood", "puno", "fossil", "mineral", "pumalit", "mipuli", "natipon", "tumigas", "turned to stone"], "fact": {"tl": "Ang petrified wood ay isang fossil kung saan ang tunay na kahoy ay unti-unting pinalitan ng mineral hanggang sa maging bato ito.", "en": "Petrified wood is a fossil in which real wood is slowly replaced by minerals until it turns to stone.", "bis": "Ang petrified wood usa ka fossil diin ang tinuod nga kahoy hinay-hinay nga gipulihan og mineral hangtod nga nahimo kining bato."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rocks-evidence-g8", "domain": "EARTH_SPACE", "topic": "rocks as evidence of the past", "grades": [7, 8, 9], "terms": ["bato", "rock", "ebidensya", "ebidensiya", "patunay", "timaan", "init", "presyon", "mineral", "nabuo", "giunsa", "kasaysayan", "evidence", "clues"], "fact": {"tl": "Naglalaman ang bawat bato ng mga palatandaan — ang mga mineral, init, at puwersang gumawa dito — kaya nababasa ng mga siyentipiko ang nakaraan ng Earth mula sa mga bato.", "en": "Every rock holds clues — the minerals, heat, and forces that made it — so scientists can read Earth's past from rocks.", "bis": "Ang matag bato adunay mga timaan — ang mga mineral, init, ug puwersa nga naghimo niini — busa mabasa sa mga siyentista ang nangagi sa Yuta gikan sa mga bato."}, "source": "AAAS BSL 4C/M4", "generator": "claude-workflow", "reviewed": false},
  {"id": "lion-predator-g4", "domain": "LIVING_THINGS", "topic": "the lion", "grades": [3, 4, 5], "terms": ["lion", "leon", "leyon", "predator", "mandaragit", "manunukob", "carnivore", "karnivora", "pusa", "iring", "nangangaso", "mangayam", "sebra", "zebra", "kalabaw", "hayop"], "fact": {"tl": "Ang leon (lion) ay isang malaking mandaragit (predator) na pusa na kumakain lamang ng karne — karnivora ito. Nangangaso ito ng mga hayop tulad ng sebra, antelope, at ligaw na kalabaw.", "en": "The lion is a large predatory cat that eats only meat — it is a carnivore. It hunts animals like zebras, antelope, and wild buffalo.", "bis": "Ang leon (lion) usa ka dakong manunukob nga iring nga mokaon lamang og karne — karnivora kini. Mangayam kini og mga hayop sama sa zebra, antelope, ug ihalas nga kalabaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lion-habitat-g4", "domain": "LIVING_THINGS", "topic": "lion habitat", "grades": [3, 4, 5], "terms": ["lion", "leon", "habitat", "tirahan", "puy-anan", "savanna", "damuhan", "kasagbutan", "grassland", "Africa", "Aprika", "kapatagan", "kalibonan"], "fact": {"tl": "Karamihan ng mga leon ay nakatira sa malalawak na damuhan (savanna) at kapatagan ng Africa, hindi sa gubat na puno ng puno. Doon sila madaling makahanap ng mga hayop na kanilang kinakain.", "en": "Most lions live on the open grasslands (savanna) and plains of Africa, not in thick jungle. There they can easily find the animals they hunt.", "bis": "Kadaghanan sa mga leon nagpuyo sa lapad nga kasagbutan (savanna) ug kapatagan sa Africa, dili sa baga nga lasang. Didto sayon nilang makit-an ang mga hayop nga ilang ginakaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lion-pride-g5", "domain": "LIVING_THINGS", "topic": "lion prides and hunting", "grades": [4, 5, 6], "terms": ["lion", "leon", "pride", "pangkat", "grupo", "panon", "pamilya", "pack", "nangangaso", "nangayam", "magkakasama", "sabay", "nagtutulungan", "females", "babae", "bayi"], "fact": {"tl": "Hindi tulad ng karamihang pusa, ang mga leon ay namumuhay sa pangkat na tinatawag na pride. Madalas ang mga babaeng leon ang sama-samang nangangaso para sa buong pamilya.", "en": "Unlike most cats, lions live in a group called a pride. The female lions often hunt together as a team for the whole family.", "bis": "Dili sama sa kadaghanan nga iring, ang mga leon nagpuyo sa grupo nga gitawag og pride. Kasagaran ang mga bayeng leon ang nag-uban sa pagpangayam alang sa tibuok pamilya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lion-roar-g4", "domain": "LIVING_THINGS", "topic": "lion roar", "grades": [3, 4, 5], "terms": ["lion", "leon", "roar", "atunggal", "ungal", "ungol", "tunog", "lakas", "kusog", "tingog", "boses", "naririnig", "madungog", "layo"], "fact": {"tl": "Ang atunggal o ungol (roar) ng leon ay napakalakas — naririnig ito sa layong hanggang 8 kilometro. Ginagamit ito ng leon para tawagin ang pangkat nito at balaan ang ibang leon.", "en": "A lion's roar is very loud — it can be heard from as far as 8 kilometers away. The lion uses it to call its pride and to warn other lions.", "bis": "Ang ungal (roar) sa leon kusog kaayo — madungog kini hangtod sa 8 ka kilometro ang gilay-on. Gigamit kini sa leon aron tawgon ang grupo niini ug pasidan-an ang ubang leon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tiger-predator-g4", "domain": "LIVING_THINGS", "topic": "the tiger", "grades": [3, 4, 5], "terms": ["tiger", "tigre", "predator", "mandaragit", "manunukob", "carnivore", "karnivora", "pinakamalaking", "pinakadako", "pusa", "iring", "guhit", "badlis", "baboy-ramo"], "fact": {"tl": "Ang tigre (tiger) ang pinakamalaking pusa sa mundo at isang makapangyarihang mandaragit. Kumakain ito ng karne lamang, tulad ng usa at baboy-ramo.", "en": "The tiger is the biggest cat in the world and a powerful predator. It eats only meat, such as deer and wild pigs.", "bis": "Ang tigre (tiger) mao ang pinakadakong iring sa kalibutan ug usa ka kusganong manunukob. Mokaon kini og karne lamang, sama sa usa ug ihalas nga baboy."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tiger-stripes-g4", "domain": "LIVING_THINGS", "topic": "why tigers have stripes", "grades": [3, 4, 5, 6], "terms": ["tiger", "tigre", "stripes", "guhit", "badlis", "gihay", "kamuplahe", "camouflage", "pagtago", "tago", "damo", "sagbot", "kulay", "kolor", "pattern"], "fact": {"tl": "Ang mga guhit (stripes) ng tigre ay tumutulong itong magtago sa mahahabang damo habang gumagapang papalapit sa biktima nito — isang uri ng kamuplahe. Tulad ng fingerprint ng tao, walang dalawang tigre na may magkaparehong guhit.", "en": "A tiger's stripes help it hide in tall grass as it creeps up on its prey — a kind of camouflage. Like human fingerprints, no two tigers have exactly the same stripes.", "bis": "Ang mga badlis (stripes) sa tigre motabang niini sa pagtago sa taas nga sagbot samtang nagkamang kini paduol sa tukbonon — usa ka matang sa camouflage. Sama sa fingerprint sa tawo, walay duha ka tigre nga managsama gyud og badlis."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tiger-swim-g5", "domain": "LIVING_THINGS", "topic": "tigers can swim", "grades": [4, 5, 6], "terms": ["tiger", "tigre", "swim", "langoy", "lumalangoy", "molangoy", "tubig", "danum", "ilog", "suba", "lawa", "lanaw", "naliligo", "maligo", "pusa", "iring"], "fact": {"tl": "Hindi tulad ng karamihang pusa na ayaw sa tubig, ang mga tigre ay magaling lumangoy at gustong maligo sa ilog at lawa para magpalamig.", "en": "Unlike most cats that dislike water, tigers are strong swimmers and enjoy cooling off in rivers and lakes.", "bis": "Dili sama sa kadaghanan nga iring nga dili ganahan sa tubig, ang mga tigre maayong molangoy ug ganahan maligo sa suba ug lanaw aron mobugnaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wolf-predator-g4", "domain": "LIVING_THINGS", "topic": "the wolf", "grades": [3, 4, 5], "terms": ["wolf", "lobo", "predator", "mandaragit", "manunukob", "carnivore", "karnivora", "ninuno", "ancestor", "aso", "iro", "ido", "kamukha", "kahawig"], "fact": {"tl": "Ang lobo (wolf) ay isang ligaw na mandaragit na kamukha ng malaking aso — at totoo ngang ang mga aso ay nagmula sa mga lobo noong unang panahon. Kumakain ito ng mga hayop tulad ng usa.", "en": "The wolf is a wild predator that looks like a large dog — and in fact dogs descended from wolves long ago. It eats animals such as deer.", "bis": "Ang lobo (wolf) usa ka ihalas nga manunukob nga morag dakong iro — ug tinuod nga ang mga iro naggikan sa mga lobo kaniadto. Mokaon kini og mga hayop sama sa usa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wolf-pack-g4", "domain": "LIVING_THINGS", "topic": "wolf packs", "grades": [3, 4, 5, 6], "terms": ["wolf", "lobo", "pack", "pangkat", "grupo", "panon", "pamilya", "magkakasama", "sabay", "nagtutulungan", "nag-uban", "nangangaso", "nangayam", "malaki", "dako", "biktima"], "fact": {"tl": "Ang mga lobo ay namumuhay at nangangaso bilang isang pangkat na tinatawag na pack. Sa pagtutulungan, kaya nilang dakpin ang mga hayop na mas malaki pa sa isang lobo.", "en": "Wolves live and hunt together as a group called a pack. By working as a team, they can bring down animals much bigger than a single wolf.", "bis": "Ang mga lobo nagpuyo ug nangayam ingon nga usa ka grupo nga gitawag og pack. Pinaagi sa panaghiusa, makahimo sila pagdakop og mga hayop nga mas dako pa sa usa ka lobo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wolf-howl-g4", "domain": "LIVING_THINGS", "topic": "why wolves howl", "grades": [3, 4, 5], "terms": ["wolf", "lobo", "howl", "alulong", "uwang", "uwhang", "tunog", "tingog", "boses", "tawag", "nagtatawag", "pack", "pangkat", "komunikasyon", "kausap"], "fact": {"tl": "Ang mga lobo ay umaalulong (howl) para makipag-usap sa kanilang pangkat — para tawagin ang mga kasama o sabihin kung nasaan sila. Naririnig ang alulong mula sa napakalayo.", "en": "Wolves howl to communicate with their pack — to call the others or tell them where they are. A howl can be heard from very far away.", "bis": "Ang mga lobo mag-uwang (howl) aron makigsulti sa ilang grupo — aron tawgon ang mga kauban o isulti kung asa sila. Ang uwang madungog gikan sa layo kaayo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bear-omnivore-g4", "domain": "LIVING_THINGS", "topic": "what bears eat", "grades": [3, 4, 5], "terms": ["bear", "oso", "omnivore", "omnivora", "kumakain", "mokaon", "prutas", "bunga", "isda", "honey", "pulot", "dugos", "halaman", "tanom", "karne", "insekto"], "fact": {"tl": "Karamihan ng mga oso (bear) ay omnivore — kumakain sila ng halaman at hayop kapwa. Kasama sa pagkain nila ang prutas, dahon, isda, insekto, at pulot-pukyutan (honey).", "en": "Most bears are omnivores — they eat both plants and animals. Their food includes fruit, leaves, fish, insects, and honey.", "bis": "Kadaghanan sa mga oso (bear) omnivore — mokaon sila og tanom ug hayop. Apil sa ilang pagkaon ang prutas, dahon, isda, insekto, ug dugos (honey)."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bear-hibernate-g5", "domain": "LIVING_THINGS", "topic": "bears resting through winter", "grades": [4, 5, 6], "terms": ["bear", "oso", "winter", "taglamig", "tingtugnaw", "tulog", "matulog", "natutulog", "pagtulog", "yungib", "lungib", "langob", "taba", "tambok", "fat", "enerhiya", "kusog", "pagkain", "nihit"], "fact": {"tl": "Sa malalamig na lugar, ang mga oso ay nagtatago sa yungib at mahimbing na natutulog sa buong taglamig kapag kakaunti ang pagkain. Bago iyon, kumakain sila nang marami para mag-imbak ng taba bilang enerhiya.", "en": "In cold places, bears shelter in a den and sleep deeply through winter when food is scarce. Before that, they eat a lot to store body fat for energy.", "bis": "Sa bugnaw nga mga dapit, ang mga oso magtago sa langob ug mahinanok nga matulog sa tibuok tingtugnaw kon nihit ang pagkaon. Sa wala pa kana, mokaon sila og daghan aron magtigom og tambok isip kusog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bear-smell-g5", "domain": "LIVING_THINGS", "topic": "bears' sense of smell", "grades": [4, 5, 6], "terms": ["bear", "oso", "smell", "amoy", "pang-amoy", "panimaho", "baho", "simhot", "ilong", "matalas", "talinis", "hayop", "nakakaamoy", "makasimhot", "layo", "pagkain"], "fact": {"tl": "Ang oso ay may napakatalas na pang-amoy — isa sa pinakamagaling sa lahat ng hayop sa lupa. Kaya nitong maamoy ang pagkain mula sa napakalayo.", "en": "Bears have an extremely keen sense of smell — one of the best of any land animal. They can smell food from very far away.", "bis": "Ang oso adunay hilabihan ka talinis nga panimaho — usa sa pinakamaayo sa tanang hayop sa yuta. Makasimhot sila og pagkaon gikan sa layo kaayo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "crocodile-predator-g4", "domain": "LIVING_THINGS", "topic": "the crocodile", "grades": [3, 4, 5], "terms": ["crocodile", "buwaya", "buaya", "reptilya", "reptile", "predator", "mandaragit", "manunukob", "tubig", "danum", "ilog", "suba", "ngipin", "ngipon", "latian", "lamakan"], "fact": {"tl": "Ang buwaya (crocodile) ay isang malaking reptilya at mandaragit na naninirahan sa ilog, lawa, at latian. Naghihintay ito nang tahimik sa tubig bago biglang dumagit sa biktima nito.", "en": "The crocodile is a large reptile and predator that lives in rivers, lakes, and swamps. It waits quietly in the water before suddenly snatching its prey.", "bis": "Ang buaya (crocodile) usa ka dakong reptilya ug manunukob nga nagpuyo sa suba, lanaw, ug lamakan. Maghulat kini nga hilom sa tubig una kalit nga motukob sa biktima niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "crocodile-bite-g5", "domain": "LIVING_THINGS", "topic": "crocodile bite and teeth", "grades": [4, 5, 6], "terms": ["crocodile", "buwaya", "buaya", "bite", "kagat", "paak", "ngipin", "ngipon", "lakas", "kusog", "mahigpit", "higpit", "hawak", "kupot", "panga", "apapangig", "ngumuya", "usap"], "fact": {"tl": "Napakalakas ng kagat ng buwaya — isa sa pinakamalakas na kagat ng kahit anong hayop. Ginagamit nito ang matalas na ngipin para mahigpit na hawakan ang biktima, hindi para ngumuya.", "en": "A crocodile's bite is extremely strong — one of the most powerful bites of any animal. It uses its sharp teeth to grip prey tightly, not to chew.", "bis": "Ang paak sa buaya kusog kaayo — usa sa pinakakusganong paak sa bisan unsang hayop. Gigamit niini ang talinis nga ngipon aron higpit nga kuptan ang biktima, dili aron mag-usap."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "crocodile-eyes-g5", "domain": "LIVING_THINGS", "topic": "crocodile eyes above water", "grades": [4, 5, 6], "terms": ["crocodile", "buwaya", "buaya", "mata", "ilong", "nostrils", "buho", "ibabaw", "babaw", "ilalim", "ilawom", "tubig", "danum", "huminga", "ginhawa", "lubog", "unlod", "atang", "tago"], "fact": {"tl": "Ang mga mata at butas ng ilong ng buwaya ay nasa itaas ng ulo nito, kaya kahit lumubog ang katawan nito sa tubig, makakakita at makakahinga pa rin ito habang nag-aabang.", "en": "A crocodile's eyes and nostrils sit on top of its head, so even when its body is underwater it can still see and breathe while lying in wait.", "bis": "Ang mga mata ug buho sa ilong sa buaya naa sa ibabaw sa ulo niini, busa bisan unlod ang lawas niini sa tubig makakita ug makaginhawa pa kini samtang nag-atang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "crocodile-philippine-g6", "domain": "LIVING_THINGS", "topic": "Philippine crocodile", "grades": [5, 6, 7], "terms": ["Philippine crocodile", "buwaya", "buaya", "Pilipinas", "Filipino", "endemic", "endemiko", "tubig-tabang", "freshwater", "tab-ang", "endangered", "nanganganib", "nameligro", "pangangalaga", "amping", "maliit", "gamay"], "fact": {"tl": "Ang Philippine crocodile ay isang maliit na buwaya na matatagpuan lamang sa Pilipinas (endemic) at namumuhay sa tubig-tabang. Isa ito sa pinakananganganib na buwaya sa mundo, kaya ito ay iniingatan.", "en": "The Philippine crocodile is a small crocodile found only in the Philippines (endemic) and lives in freshwater. It is one of the most endangered crocodiles in the world, so it is protected.", "bis": "Ang Philippine crocodile usa ka gamayng buaya nga makit-an lamang sa Pilipinas (endemic) ug nagpuyo sa tubig-tab-ang. Usa kini sa pinakanameligro nga buaya sa kalibutan, busa giamping kini."}, "source": "encyclopedia-stable consensus; DepEd PH-species framing", "generator": "claude-workflow", "reviewed": false},
  {"id": "eagle-predator-g4", "domain": "LIVING_THINGS", "topic": "the eagle", "grades": [3, 4, 5], "terms": ["eagle", "agila", "predator", "mandaragit", "manunukob", "ibon", "langgam", "bird of prey", "sumisila", "mosakmal", "mata", "matalas", "talinis", "langit", "lumilipad", "molupad"], "fact": {"tl": "Ang agila (eagle) ay isang malaking ibong mandaragit (bird of prey). Lumilipad ito sa langit at gumagamit ng napakatalas na mata para makakita ng biktima mula sa malayo.", "en": "The eagle is a large bird of prey. It soars in the sky and uses very sharp eyesight to spot prey from far away.", "bis": "Ang agila (eagle) usa ka dakong manunukob nga langgam (bird of prey). Molupad kini sa langit ug mogamit og talinis kaayong mata aron makakita og biktima gikan sa layo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "eagle-talons-g5", "domain": "LIVING_THINGS", "topic": "eagle talons and beak", "grades": [4, 5, 6], "terms": ["eagle", "agila", "talons", "kuko", "kuyamoy", "claws", "beak", "tuka", "sungo", "baliko", "matalim", "matalas", "talinis", "sumisila", "sakmal", "biktima", "laman"], "fact": {"tl": "Ang agila ay may matatalim na kuko (talons) at baliko at matalas na tuka. Ginagamit nito ang kuko para sakmalin at hawakan ang biktima, at ang tuka para punitin ang laman.", "en": "An eagle has sharp talons (claws) and a hooked, sharp beak. It uses the talons to grab and hold prey, and the beak to tear meat.", "bis": "Ang agila adunay talinis nga mga kuko (talons) ug baliko ug hait nga sungo. Gigamit niini ang mga kuko aron sakmalon ug kuptan ang biktima, ug ang sungo aron gision ang karne."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "eagle-eyesight-g5", "domain": "LIVING_THINGS", "topic": "eagle eyesight", "grades": [4, 5, 6], "terms": ["eagle", "agila", "mata", "paningin", "panan-aw", "eyesight", "vision", "matalas", "talinis", "makakita", "layo", "biktima", "langit", "taas", "tao", "sharp"], "fact": {"tl": "Ang paningin ng agila ay mas matalas kaysa sa tao — kaya nitong makita ang maliit na hayop mula sa napakataas at malayong lipad. Tumutulong ito sa pangangaso.", "en": "An eagle's eyesight is much sharper than a human's — it can spot a small animal from very high and far up in flight. This helps it hunt.", "bis": "Ang panan-aw sa agila mas talinis kay sa tawo — makita niini ang gamayng hayop gikan sa taas ug layo kaayo nga paglupad. Motabang kini sa pagpangayam."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "eagle-philippine-g5", "domain": "LIVING_THINGS", "topic": "Philippine eagle", "grades": [4, 5, 6], "terms": ["Philippine eagle", "agila", "banog", "haring ibon", "national bird", "pambansang ibon", "nasudnong langgam", "Pilipinas", "Filipino", "unggoy", "matsing", "gubat", "lasang", "Mindanao", "dako"], "fact": {"tl": "Ang Philippine eagle ang pambansang ibon ng Pilipinas at isa sa pinakamalaki at pinakamalakas na agila sa mundo. Naninirahan ito sa mga gubat tulad ng sa Mindanao at nangangaso ng matsing, ibon, at iba pang hayop.", "en": "The Philippine eagle is the national bird of the Philippines and one of the largest and most powerful eagles in the world. It lives in forests like those in Mindanao and hunts monkeys, birds, and other animals.", "bis": "Ang Philippine eagle mao ang nasudnong langgam sa Pilipinas ug usa sa pinakadako ug pinakakusganong agila sa kalibutan. Nagpuyo kini sa mga lasang sama sa Mindanao ug mangayam og unggoy, langgam, ug uban pang hayop."}, "source": "encyclopedia-stable consensus; DepEd PH-species framing", "generator": "claude-workflow", "reviewed": false},
  {"id": "eagle-nest-g5", "domain": "LIVING_THINGS", "topic": "eagle nests", "grades": [4, 5, 6], "terms": ["eagle", "agila", "pugad", "salag", "nest", "puno", "kahoy", "taas", "mataas", "tag-as", "sanga", "gawa", "gibuhat", "itlog", "sisiw", "piso", "anak", "bangin", "pangpang"], "fact": {"tl": "Karamihang agila ay gumagawa ng malalaking pugad sa tuktok ng matataas na puno o bangin. Madalas nilang ginagamit muli ang parehong pugad taon-taon para mag-alaga ng kanilang sisiw.", "en": "Most eagles build large nests at the tops of tall trees or on cliffs. They often reuse the same nest year after year to raise their chicks.", "bis": "Kadaghanan sa mga agila magbuhat og dagkong salag sa tumoy sa tag-as nga kahoy o pangpang. Kasagaran ilang gamiton pag-usab ang samang salag matag tuig aron mag-atiman sa ilang mga piso."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "predator-prey-adaptation-g5", "domain": "LIVING_THINGS", "topic": "predator hunting adaptations", "grades": [4, 5, 6], "terms": ["predator", "mandaragit", "manunukob", "prey", "biktima", "tukbonon", "adaptation", "angkop", "ngipin", "ngipon", "kuko", "kuyamoy", "bilis", "paspas", "kusog", "matalas", "talinis", "mata", "pang-amoy", "panimaho", "mangaso", "mangayam"], "fact": {"tl": "Ang mga mandaragit (predators) ay may mga natatanging katangian para makahuli ng biktima — tulad ng matatalas na ngipin at kuko, mabilis na pagtakbo, matatalas na mata, o malakas na pang-amoy.", "en": "Predators have special features that help them catch prey — such as sharp teeth and claws, fast running, keen eyesight, or a strong sense of smell.", "bis": "Ang mga manunukob (predators) adunay pinasahi nga mga kinaiya nga motabang nila sa pagdakop og biktima — sama sa talinis nga ngipon ug kuko, paspas nga pagdagan, talinis nga mata, o kusganong panimaho."}, "source": "NRC LS1.A; AAAS BSL Ch.5", "generator": "claude-workflow", "reviewed": false},
  {"id": "predator-top-of-chain-g5", "domain": "LIVING_THINGS", "topic": "top predators in the food chain", "grades": [5, 6, 7], "terms": ["predator", "mandaragit", "manunukob", "apex", "top predator", "pinakatuktok", "tumoy", "food chain", "balanse", "balance", "populasyon", "gidaghanon", "kontrol", "ekosistema", "mahalaga", "importante"], "fact": {"tl": "Ang malalaking mandaragit tulad ng leon, tigre, at agila ay nasa tuktok ng food chain (top predators). Mahalaga sila dahil pinapanatili nilang balanse ang bilang ng ibang hayop sa ekosistema.", "en": "Big predators like lions, tigers, and eagles sit at the top of the food chain (top predators). They are important because they keep the numbers of other animals in the ecosystem in balance.", "bis": "Ang dagkong manunukob sama sa leon, tigre, ug agila naa sa tumoy sa food chain (top predators). Importante sila kay ilang gipabilin nga balanse ang gidaghanon sa ubang hayop sa ekosistema."}, "source": "NRC LS2.A; AAAS BSL Ch.5", "generator": "claude-workflow", "reviewed": false},
  {"id": "big-cats-claws-g5", "domain": "LIVING_THINGS", "topic": "big cats' retractable claws", "grades": [4, 5, 6], "terms": ["lion", "leon", "tiger", "tigre", "claws", "kuko", "kuyamoy", "retractable", "naitatago", "matago", "matalas", "talinis", "tahimik", "hilom", "paa", "tiil", "gumagapang", "nagkamang", "sakmal", "hayop"], "fact": {"tl": "Ang malalaking pusa tulad ng leon at tigre ay may kukong naitatago (retractable claws) sa loob ng kanilang paa. Kaya nilang lumakad nang tahimik at saka ilabas ang matatalas na kuko kapag sumasakmal ng biktima.", "en": "Big cats like lions and tigers have claws that pull back (retractable claws) into their paws. This lets them walk silently and then bring out the sharp claws when grabbing prey.", "bis": "Ang dagkong iring sama sa leon ug tigre adunay mga kuko nga matago (retractable claws) sa ilang tiil. Niini makalakaw sila nga hilom ug unya mopagawas sa talinis nga mga kuko kon mosakmal sa biktima."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "polar-bear-g5", "domain": "LIVING_THINGS", "topic": "polar bear", "grades": [4, 5, 6], "terms": ["polar bear", "oso", "puting oso", "white bear", "yelo", "ice", "Arctic", "lamig", "bugnaw", "tingtugnaw", "balahibo", "balhibo", "makapal", "baga", "fur", "langoy", "molangoy", "seal", "poka"], "fact": {"tl": "Ang polar bear ay isang malaking puting oso na naninirahan sa napakalamig na lugar na puno ng yelo sa hilaga ng mundo. Makapal ang balahibo nito para hindi ginawin, at magaling itong lumangoy para manghuli ng poka (seal).", "en": "The polar bear is a large white bear that lives in the icy, freezing far north of the world. It has thick fur to stay warm and swims well to hunt seals.", "bis": "Ang polar bear usa ka dakong puti nga oso nga nagpuyo sa bugnaw kaayo ug puno sa yelo nga amihanan sa kalibutan. Baga ang balhibo niini aron dili tugnawon, ug maayo kining molangoy aron mangayam og seal."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "saltwater-crocodile-g6", "domain": "LIVING_THINGS", "topic": "saltwater crocodile", "grades": [5, 6, 7], "terms": ["saltwater crocodile", "buwaya", "buaya", "saltwater", "tubig-alat", "tubig-asin", "dagat", "pinakamalaking", "pinakadako", "reptilya", "reptile", "Pilipinas", "Asya", "Australia", "mabigat"], "fact": {"tl": "Ang saltwater crocodile ang pinakamalaking buwaya at pinakamalaking reptilya sa mundo ngayon. Matatagpuan ito sa tubig-alat at ilog sa Pilipinas at iba pang bahagi ng Asya at Australia.", "en": "The saltwater crocodile is the largest crocodile and the largest reptile on Earth today. It is found in salty water and rivers in the Philippines and other parts of Asia and Australia.", "bis": "Ang saltwater crocodile mao ang pinakadakong buaya ug pinakadakong reptilya sa kalibutan karon. Makit-an kini sa tubig-asin ug suba sa Pilipinas ug uban pang bahin sa Asya ug Australia."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "shark-teeth-rows-g4", "domain": "LIVING_THINGS", "topic": "shark teeth", "grades": [3, 4, 5], "terms": ["pating", "iho", "shark", "ngipin", "ngipon", "teeth", "tooth", "bago", "nahuhulog", "nadagdagan", "rows", "hanay", "kumagat", "bite"], "fact": {"tl": "Patuloy na nagpapalit ng ngipin ang pating habang nabubuhay ito — kapag nahulog ang isang ngipin, may bagong ngipin na sumusulpot sa likuran para pumalit. Maaari itong magpalit ng libu-libong ngipin sa buong buhay nito.", "en": "A shark keeps growing new teeth its whole life — when one tooth falls out, a new tooth behind it moves up to replace it. A shark can go through thousands of teeth in its lifetime.", "bis": "Padayon nga nag-ilis og ngipon ang iho samtang buhi pa kini — kon matangtang ang usa ka ngipon, naay bag-ong ngipon sa luyo nga mosaylo aron mopuli. Mahimong moilis kini og linibo ka ngipon sa tibuok niyang kinabuhi."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "whale-shark-largest-fish-g5", "domain": "LIVING_THINGS", "topic": "whale shark", "grades": [4, 5, 6], "terms": ["whale shark", "butanding", "tuki", "pinakamalaking isda", "largest fish", "plankton", "salaan", "filter", "dagat", "Donsol", "Oslob", "banal"], "fact": {"tl": "Ang butanding (whale shark) ang pinakamalaking isda sa mundo, pero kumakain lamang ito ng maliliit na plankton sa pamamagitan ng pagsala ng tubig — hindi ito mapanganib sa tao. Madalas itong makita sa Donsol at Oslob sa Pilipinas.", "en": "The whale shark is the biggest fish in the world, but it eats only tiny plankton by filtering water — it is not dangerous to people. It is often seen in Donsol and Oslob in the Philippines.", "bis": "Ang butanding (whale shark) maoy pinakadako nga isda sa kalibotan, apan mokaon lamang kini og gagmay nga plankton pinaagi sa pagsala sa tubig — dili kini delikado sa tawo. Kasagaran kini makita sa Donsol ug Oslob sa Pilipinas."}, "source": "encyclopedia-stable consensus; PH-relevant (Donsol/Oslob)", "generator": "claude-workflow", "reviewed": false},
  {"id": "shark-smell-blood-g5", "domain": "LIVING_THINGS", "topic": "shark senses", "grades": [5, 6, 7], "terms": ["pating", "iho", "shark", "amoy", "baho", "smell", "dugo", "blood", "ilong", "tubig", "tumukoy", "mahusay na pang-amoy"], "fact": {"tl": "May napakahusay na pang-amoy ang pating at kaya nitong matukoy ang amoy ng dugo sa napakalayong tubig. Ginagamit nito ang pang-amoy para mahanap ang pagkain sa malawak na dagat.", "en": "A shark has an excellent sense of smell and can detect blood in the water from far away. It uses smell to find food across the wide ocean.", "bis": "Ang iho adunay maayo kaayong panimaho ug makamatngon kini sa baho sa dugo sa layo kaayong tubig. Gamiton niini ang panimaho aron makapangita og pagkaon sa lapad nga dagat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "whale-song-communicate-g5", "domain": "LIVING_THINGS", "topic": "whale song", "grades": [4, 5, 6], "terms": ["balyena", "whale", "awit", "kanta", "song", "tunog", "sound", "huminga", "communicate", "makipag-usap", "humpback", "malayo", "dagat"], "fact": {"tl": "Ang ilang balyena gaya ng humpback ay 'umaawit' — gumagawa sila ng mahahaba at paulit-ulit na tunog na umaabot ng napakalayo sa ilalim ng tubig. Ginagamit nila ito para makipag-usap sa ibang balyena.", "en": "Some whales like the humpback 'sing' — they make long, repeating sounds that travel very far underwater. They use these songs to communicate with other whales.", "bis": "Ang ubang balyena sama sa humpback 'mokanta' — maghimo silag taas ug balik-balik nga tingog nga moabot og layo kaayo ilalom sa tubig. Gamiton nila kini aron makig-istorya sa ubang balyena."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "whale-blowhole-g4", "domain": "LIVING_THINGS", "topic": "whale blowhole", "grades": [3, 4, 5], "terms": ["balyena", "whale", "butas", "blowhole", "ilong", "huminga", "breathe", "ginhawa", "tubig", "spray", "ulo", "ibabaw", "surface"], "fact": {"tl": "Humihinga ang balyena sa pamamagitan ng isang butas sa itaas ng ulo nito na tinatawag na blowhole. Kapag umaahon ito para huminga, lumalabas ang isang fountain ng hamog na tubig sa hangin.", "en": "A whale breathes through a hole on top of its head called a blowhole. When it surfaces to breathe, a spray of misty water shoots up into the air.", "bis": "Magginhawa ang balyena pinaagi sa usa ka lungag sa ibabaw sa iyang ulo nga gitawag og blowhole. Kon mosulbong kini aron moginhawa, naay tubig nga moboso pataas sa hangin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dolphin-pod-group-g4", "domain": "LIVING_THINGS", "topic": "dolphin pods", "grades": [3, 4, 5], "terms": ["dolphin", "grupo", "pod", "langkay", "kawan", "sama-sama", "social", "tumutulong", "laro", "jump", "lukso", "mammal", "dagat"], "fact": {"tl": "Naninirahan ang mga dolphin nang sama-sama sa grupo na tinatawag na pod. Tumutulong sila sa isa't isa, naglalaro, at sabay-sabay na lumulukso sa ibabaw ng tubig.", "en": "Dolphins live together in groups called pods. They help each other, play, and leap above the water together.", "bis": "Magpuyo ang mga dolphin nga magkauban sa grupo nga gitawag og pod. Magtinabangay sila, magdula, ug dungan nga moambak sa ibabaw sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "octopus-camouflage-g4", "domain": "LIVING_THINGS", "topic": "octopus camouflage", "grades": [4, 5, 6], "terms": ["pugita", "kugita", "octopus", "kulay", "color", "balat", "skin", "nagbabago", "camouflage", "nagtatago", "hide", "kublihan", "predator", "dagat"], "fact": {"tl": "Kayang baguhin ng pugita ang kulay at tekstura ng balat nito sa isang iglap para magmukhang kapareho ng bato o coral. Ginagamit nito ang trick na ito para magtago sa mga kaaway.", "en": "An octopus can change the color and texture of its skin in an instant to look just like a rock or coral. It uses this trick to hide from enemies.", "bis": "Mahimong usbon sa kugita ang kolor ug textura sa iyang panit sa kalit aron mahisama sa bato o coral. Gamiton niini kini nga paagi aron motago gikan sa mga kaaway."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "octopus-ink-defense-g4", "domain": "LIVING_THINGS", "topic": "octopus ink", "grades": [3, 4, 5], "terms": ["pugita", "kugita", "octopus", "tinta", "ink", "itim", "black", "cloud", "ulap", "pagtakas", "escape", "layas", "kaaway", "defense", "dagat"], "fact": {"tl": "Kapag natatakot ang pugita, nagpapalabas ito ng maitim na tinta sa tubig na gumagawa ng madilim na ulap. Habang nalilito ang kaaway, mabilis itong tumatakas.", "en": "When an octopus is scared, it squirts dark ink into the water that makes a murky cloud. While the enemy is confused, the octopus quickly escapes.", "bis": "Kon mahadlok ang kugita, mobuga kini og itom nga tinta sa tubig nga maghimog ngitngit nga panganod. Samtang nalibog ang kaaway, dali nga molayas ang kugita."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "jellyfish-no-brain-g4", "domain": "LIVING_THINGS", "topic": "jellyfish body", "grades": [3, 4, 5], "terms": ["jellyfish", "dikya", "sea jelly", "utak", "brain", "puso", "heart", "buto", "bone", "tubig", "water", "malambot", "walang", "dagat"], "fact": {"tl": "Ang dikya (jellyfish) ay walang utak, walang puso, at walang buto — halos puro tubig lamang ang katawan nito. Kahit ganoon, milyun-milyong taon na itong nabubuhay sa dagat.", "en": "A jellyfish has no brain, no heart, and no bones — its body is almost all water. Even so, jellyfish have lived in the sea for millions of years.", "bis": "Ang dikya (jellyfish) walay utok, walay kasingkasing, ug walay bukog — halos puro tubig lang ang lawas niini. Bisan pa niini, minilyon na ka tuig nga nabuhi kini sa dagat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "jellyfish-sting-tentacles-g5", "domain": "LIVING_THINGS", "topic": "jellyfish sting", "grades": [4, 5, 6], "terms": ["jellyfish", "dikya", "sting", "kagat", "lapnos", "tentacle", "galamay", "kamandag", "venom", "manghuli", "pagkain", "prey", "ingat", "dagat"], "fact": {"tl": "May mahahabang galamay (tentacles) ang dikya na may maliliit na nakatusok na may kamandag. Ginagamit nito ang mga ito para mangharang ng pagkain, at maaari ring makapaso ng tao kapag nadikit.", "en": "A jellyfish has long tentacles covered with tiny stingers that hold venom. It uses them to catch prey, and they can also sting a person who touches them.", "bis": "Ang dikya adunay tag-as nga galamay (tentacles) nga puno sa gagmayng tusok nga may hilo. Gamiton niini kini aron makadakop og pagkaon, ug makapaso usab kini sa tawong mahikap niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sea-turtle-return-beach-g5", "domain": "LIVING_THINGS", "topic": "sea turtle nesting", "grades": [4, 5, 6], "terms": ["pawikan", "sea turtle", "turtle", "itlog", "egg", "buhangin", "beach", "baybayin", "nest", "pugad", "bumabalik", "return", "ipinanganak", "laot", "dagat"], "fact": {"tl": "Ang pawikan (sea turtle) ay gumugugol ng halos buong buhay nito sa dagat, pero bumabalik ang babae sa baybayin para maglibing ng mga itlog sa buhangin. Madalas itong bumabalik sa mismong dalampasigan kung saan ito ipinanganak.", "en": "A sea turtle spends almost its whole life in the ocean, but the female returns to the beach to bury her eggs in the sand. She often comes back to the very beach where she was born.", "bis": "Ang pawikan (sea turtle) mogugol sa halos tibuok niyang kinabuhi sa dagat, apan mobalik ang baye sa baybayon aron ilubong ang iyang mga itlog sa balas. Kasagaran mobalik kini sa mismong baybayon diin kini natawo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sea-turtle-hatchlings-sea-g4", "domain": "LIVING_THINGS", "topic": "turtle hatchlings", "grades": [3, 4, 5], "terms": ["pawikan", "sea turtle", "hatchling", "pispis", "anak", "itlog", "napisa", "hatch", "gumagapang", "crawl", "dagat", "gabi", "night", "ilaw", "liwanag"], "fact": {"tl": "Kapag napisa ang mga itlog ng pawikan, ang maliliit na anak ay gumagapang papunta sa dagat, kadalasan sa gabi. Hinahanap nila ang liwanag ng kalangitan sa ibabaw ng tubig para malaman ang daan.", "en": "When sea turtle eggs hatch, the tiny babies crawl toward the sea, usually at night. They follow the bright sky over the water to find their way.", "bis": "Kon mapusa ang mga itlog sa pawikan, ang gagmayng mga anak mokamang padulong sa dagat, kasagaran sa gabii. Sundon nila ang kahayag sa langit sa ibabaw sa tubig aron makit-an ang dalan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "clownfish-anemone-home-g4", "domain": "LIVING_THINGS", "topic": "clownfish anemone", "grades": [3, 4, 5], "terms": ["clownfish", "Nemo", "isda", "fish", "anemone", "tahanan", "home", "balay", "kamandag", "sting", "protektado", "safe", "tumutulong", "symbiosis", "dagat"], "fact": {"tl": "Naninirahan ang clownfish sa pagitan ng nakakapasong galamay ng sea anemone. Ligtas ang clownfish sa kamandag nito, at ginagamit nito ang anemone bilang tahanan na nagtatago sa kanya mula sa mga kaaway.", "en": "A clownfish lives among the stinging tentacles of a sea anemone. The clownfish is safe from the sting, and it uses the anemone as a home that hides it from enemies.", "bis": "Magpuyo ang clownfish taliwala sa makapaso nga galamay sa sea anemone. Luwas ang clownfish gikan sa hilo niini, ug gamiton niini ang anemone isip balay nga magtago kaniya gikan sa mga kaaway."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "clownfish-change-sex-g7", "domain": "LIVING_THINGS", "topic": "clownfish biology", "grades": [7, 8, 9], "terms": ["clownfish", "isda", "fish", "babae", "lalaki", "male", "female", "nagbabago", "change", "pinakamalaki", "biggest", "pangkat", "group", "kakaiba", "dagat"], "fact": {"tl": "Sa isang pangkat ng clownfish, ang pinakamalaking isda ay laging babae. Kapag namatay ang babae, ang pinakamalaking lalaki ay nagbabago at nagiging babae — kakaibang kakayahan na bihira sa hayop.", "en": "In a group of clownfish, the biggest fish is always the female. If she dies, the largest male changes and becomes female — a remarkable ability that is rare in animals.", "bis": "Sa usa ka grupo sa clownfish, ang pinakadako nga isda kanunay baye. Kon mamatay ang baye, ang pinakadako nga laki mausab ug mahimong baye — talagsaon nga abilidad nga panagsa ra sa mga hayop."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "manta-ray-wings-g5", "domain": "LIVING_THINGS", "topic": "manta ray", "grades": [4, 5, 6], "terms": ["manta ray", "pagi", "ray", "palikpik", "fin", "pakpak", "wing", "lumilipad", "glide", "plankton", "malaki", "largest", "cartilage", "kalansay", "dagat"], "fact": {"tl": "Ang manta ray ang pinakamalaking uri ng pagi (ray), at parang lumilipad ito sa tubig gamit ang malalapad nitong palikpik na parang pakpak. Tulad ng pating, gawa sa cartilage ang kalansay nito, at kumakain ito ng maliliit na plankton.", "en": "The manta ray is the largest kind of ray, and it seems to fly through the water with wide fins like wings. Like sharks, its skeleton is made of cartilage, and it eats tiny plankton.", "bis": "Ang manta ray maoy pinakadako nga matang sa pagi (ray), ug morag molupad kini sa tubig gamit ang lapad niyang palikpik nga morag pako. Sama sa iho, ang kalansay niini hinimo sa cartilage, ug mokaon kini og gagmayng plankton."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "stingray-flat-buried-g4", "domain": "LIVING_THINGS", "topic": "stingray", "grades": [3, 4, 5], "terms": ["stingray", "pagi", "ray", "patag", "flat", "buhangin", "sand", "nagtatago", "bury", "ekor", "tail", "tusok", "tinik", "sting", "ilalim", "dagat"], "fact": {"tl": "Patag at lapad ang katawan ng pagi (stingray), kaya madali itong magtago sa ilalim ng buhangin sa sahig ng dagat. May matulis na tinik ito sa buntot na ginagamit panangga laban sa kaaway.", "en": "A stingray has a flat, wide body, so it can easily hide under the sand on the sea floor. It has a sharp spine on its tail that it uses to defend itself against enemies.", "bis": "Ang pagi (stingray) adunay patag ug lapad nga lawas, busa sayon kini motago ilalom sa balas sa salog sa dagat. Adunay kini hait nga tunok sa ikog nga gamiton aron manalipod batok sa mga kaaway."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "shark-cant-stop-swimming-g6", "domain": "LIVING_THINGS", "topic": "shark breathing", "grades": [5, 6, 7], "terms": ["pating", "iho", "shark", "langoy", "swim", "huminga", "breathe", "ginhawa", "hasang", "gills", "tubig", "oxygen", "hindi tumitigil", "dagat"], "fact": {"tl": "Ang ilang uri ng pating ay kailangang patuloy na lumangoy para makahinga, dahil kailangang dumaloy ang tubig sa kanilang hasang (gills) para makakuha ng oxygen. Kung tumigil sila, hindi sila makakahinga.", "en": "Some kinds of sharks must keep swimming to breathe, because water has to flow over their gills to give them oxygen. If they stop, they cannot get air.", "bis": "Ang ubang matang sa iho kinahanglan padayon nga molangoy aron makaginhawa, kay ang tubig kinahanglan moagi sa ilang hasang (gills) aron makakuha og oxygen. Kon mohunong sila, dili sila makaginhawa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "whale-baleen-filter-g6", "domain": "LIVING_THINGS", "topic": "baleen whale feeding", "grades": [5, 6, 7], "terms": ["balyena", "whale", "baleen", "salaan", "filter", "krill", "plankton", "ngipin", "walang", "strainer", "bibig", "mouth", "kumakain", "dagat"], "fact": {"tl": "Ang malalaking balyena gaya ng blue whale ay walang ngipin — sa halip ay may mga platong tinatawag na baleen na parang salaan. Lumulunok ito ng maraming tubig, pagkatapos ay sinasala ang maliliit na krill at plankton bilang pagkain.", "en": "Big whales like the blue whale have no teeth — instead they have plates called baleen that work like a strainer. The whale gulps a lot of water, then filters out tiny krill and plankton to eat.", "bis": "Ang dagkong balyena sama sa blue whale walay ngipon — hinuon adunay mga plato nga gitawag og baleen nga morag salaan. Motulon kini og daghang tubig, dayon salaon ang gagmayng krill ug plankton aron kan-on."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "octopus-arms-taste-g6", "domain": "LIVING_THINGS", "topic": "octopus arms", "grades": [5, 6, 7], "terms": ["pugita", "kugita", "octopus", "braso", "bukton", "arm", "suckers", "supsop", "panlasa", "taste", "amoy", "hipo", "touch", "matalino", "dagat"], "fact": {"tl": "Ang bawat braso ng pugita ay may daan-daang suckers na hindi lamang humahawak kundi 'nakakatikim' din — natutukoy nito ang lasa ng nahihipo. Halos nag-iisip ang mga braso nito nang mag-isa.", "en": "Each octopus arm has hundreds of suckers that do not just grip but also 'taste' — they can sense the flavor of whatever they touch. The arms almost seem to think on their own.", "bis": "Ang matag bukton sa kugita adunay gatusan ka suckers nga dili lang mogunit kondili 'motilaw' usab — mabati niini ang lami sa bisan unsang mahikap. Ang mga bukton morag maghunahuna sa ilang kaugalingon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sea-turtle-old-age-g5", "domain": "LIVING_THINGS", "topic": "sea turtle lifespan", "grades": [4, 5, 6], "terms": ["pawikan", "sea turtle", "turtle", "matanda", "edad", "age", "lifespan", "mahabang buhay", "long life", "taon", "year", "dahan-dahan", "slow", "dagat"], "fact": {"tl": "Napakatagal mabuhay ng pawikan — ang ilan ay umaabot ng higit sa 50 taon, at ang iba pa ay tila higit pa. Dahan-dahan silang lumalaki at matagal bago umabot sa hustong gulang.", "en": "Sea turtles can live a very long time — some reach more than 50 years, and others may live even longer. They grow slowly and take many years to reach adulthood.", "bis": "Dugay kaayong mabuhi ang pawikan — ang uban moabot og kapin 50 ka tuig, ug ang uban tingali mas taas pa. Hinay sila nga modako ug daghang tuig una sila mahimong hingkod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dolphin-sleep-half-brain-g7", "domain": "LIVING_THINGS", "topic": "dolphin sleep", "grades": [6, 7, 8], "terms": ["dolphin", "tulog", "sleep", "katog", "utak", "brain", "kalahati", "half", "huminga", "breathe", "mata", "eye", "gising", "awake", "dagat"], "fact": {"tl": "Natutulog ang dolphin sa kalahati lamang ng utak nito habang gising ang kabilang kalahati. Sa paraang ito, hindi ito malulunod at patuloy itong makakahinga sa ibabaw ng tubig.", "en": "A dolphin sleeps with only half of its brain at a time while the other half stays awake. This way, it does not drown and can keep coming up to breathe.", "bis": "Matulog ang dolphin sa katunga lang sa iyang utok samtang ang laing katunga magpabiling nagmata. Niini nga paagi, dili kini malumos ug padayon kini nga makaginhawa sa ibabaw sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sea-turtle-no-hide-shell-g4", "domain": "LIVING_THINGS", "topic": "sea turtle shell", "grades": [3, 4, 5], "terms": ["pawikan", "sea turtle", "turtle", "talukab", "shell", "kabibe", "ulo", "head", "langoy", "swim", "palikpik", "flipper", "dagat", "lupa"], "fact": {"tl": "Hindi kayang ipasok ng pawikan ang ulo at mga paa nito sa loob ng talukab gaya ng pagong sa lupa. Sa halip, ang katawan nito ay hinubog para sa mabilis na paglangoy gamit ang malalapad na palikpik.", "en": "A sea turtle cannot pull its head and legs into its shell the way a land tortoise can. Instead, its body is shaped for fast swimming with wide flippers.", "bis": "Dili masulod sa pawikan ang iyang ulo ug tiil sa sulod sa talukab sama sa baw sa yuta. Hinuon, ang lawas niini gihimo alang sa paspas nga paglangoy gamit ang lapad nga mga palikpik."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "jellyfish-glow-g5", "domain": "LIVING_THINGS", "topic": "jellyfish glow", "grades": [4, 5, 6], "terms": ["jellyfish", "dikya", "glow", "kumikinang", "ningning", "liwanag", "light", "bioluminescence", "ilaw", "sariling", "sariling-ilaw", "dilim", "dark", "dagat", "laot"], "fact": {"tl": "Ang ilang dikya ay nagliliwanag sa sariling ilaw sa dilim ng dagat — tinatawag itong bioluminescence. Maaari nilang gamitin ang liwanag na ito para takutin o lituhin ang mga kaaway.", "en": "Some jellyfish make their own light that glows in the dark ocean — this is called bioluminescence. They can use this light to startle or confuse enemies.", "bis": "Ang ubang dikya maghimo sa ilang kaugalingong kahayag nga mosidlak sa ngitngit nga dagat — gitawag kini og bioluminescence. Magamit nila kini nga kahayag aron kuratan o libgon ang mga kaaway."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "electric-ray-shock-g6", "domain": "LIVING_THINGS", "topic": "electric ray", "grades": [5, 6, 7], "terms": ["electric ray", "pagi", "ray", "kuryente", "electric", "kuryenteng", "shock", "kuryentihan", "pampatigil", "stun", "manghuli", "prey", "sandata", "dagat"], "fact": {"tl": "May uri ng pagi na tinatawag na electric ray na kayang gumawa ng sariling kuryente sa katawan nito. Ginagamit nito ang shock na ito para patigilin ang pagkain o ipagtanggol ang sarili.", "en": "There is a kind of ray called the electric ray that can make its own electricity in its body. It uses this shock to stun prey or defend itself.", "bis": "Adunay matang sa pagi nga gitawag og electric ray nga makahimo og iyang kaugalingong kuryente sa iyang lawas. Gamiton niini kini nga shock aron pahunongon ang pagkaon o panalipdan ang kaugalingon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "shark-types-many-g4", "domain": "LIVING_THINGS", "topic": "shark variety", "grades": [3, 4, 5], "terms": ["pating", "iho", "shark", "uri", "types", "klase", "iba-iba", "maliit", "laki", "hammerhead", "martilyo", "ulo", "dagat", "marami"], "fact": {"tl": "Maraming iba't ibang uri ng pating sa dagat — ang ilan ay kasinliit ng iyong braso, at ang iba ay napakalaki. Ang hammerhead shark ay may pambihirang ulo na hugis martilyo na may mata sa magkabilang dulo.", "en": "There are many different kinds of sharks in the ocean — some are as small as your arm, and others are huge. The hammerhead shark has an unusual hammer-shaped head with an eye at each end.", "bis": "Daghang lainlaing matang sa iho sa dagat — ang uban kasing-gamay sa imong bukton, ug ang uban dako kaayo. Ang hammerhead shark adunay talagsaong ulo nga porma martilyo nga may mata sa matag tumoy."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "octopus-escape-small-gap-g5", "domain": "LIVING_THINGS", "topic": "octopus squeezing", "grades": [4, 5, 6], "terms": ["pugita", "kugita", "octopus", "siwang", "gap", "lungag", "hole", "walang buto", "no bone", "pumipiga", "squeeze", "tumatakas", "escape", "liit", "dagat"], "fact": {"tl": "Dahil walang buto ang pugita, kaya nitong ipiga ang malambot nitong katawan sa siwang na kasinliit lamang ng tuka nito. Ang tanging matigas na bahagi nito ay ang tuka, kaya halos kahit saan ito makakalusot.", "en": "Because an octopus has no bones, it can squeeze its soft body through a gap only as small as its beak. The only hard part of its body is its beak, so it can fit through almost anything.", "bis": "Tungod kay walay bukog ang kugita, mapuga niini ang humok niyang lawas sa lungag nga kasing-gamay lang sa iyang sungo. Ang bugtong gahi nga bahin niini mao ang sungo, busa makaagi kini sa halos bisan asa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dolphin-blowhole-mammal-g5", "domain": "LIVING_THINGS", "topic": "dolphin breathing", "grades": [4, 5, 6], "terms": ["dolphin", "mammal", "huminga", "breathe", "ginhawa", "blowhole", "butas", "hangin", "air", "ibabaw", "surface", "isda", "hindi isda", "baga", "lungs", "dagat"], "fact": {"tl": "Kahit nakatira sa dagat, ang dolphin ay isang mammal na humihinga ng hangin, hindi isda. Kailangan nitong umahon sa ibabaw ng tubig at huminga sa pamamagitan ng blowhole sa itaas ng ulo nito.", "en": "Even though it lives in the sea, a dolphin is a mammal that breathes air, not a fish. It must come up to the surface and breathe through a blowhole on top of its head.", "bis": "Bisan tuod nagpuyo sa dagat, ang dolphin usa ka mammal nga magginhawa og hangin, dili isda. Kinahanglan kini mosulbong sa ibabaw sa tubig ug moginhawa pinaagi sa blowhole sa ibabaw sa iyang ulo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sea-turtle-eat-jellyfish-g5", "domain": "LIVING_THINGS", "topic": "sea turtle diet", "grades": [4, 5, 6], "terms": ["pawikan", "sea turtle", "turtle", "kumakain", "eat", "kaon", "dikya", "jellyfish", "plastik", "plastic", "peligro", "danger", "basura", "dagat"], "fact": {"tl": "Ang ilang pawikan ay kumakain ng dikya (jellyfish). Dahil dito, mapanganib ang plastik sa dagat — napagkakamalan nilang dikya ang lumulutang na plastik at kinakain ito, kaya dapat nating panatilihing malinis ang dagat.", "en": "Some sea turtles eat jellyfish. Because of this, plastic in the sea is dangerous — turtles mistake floating plastic for jellyfish and eat it, so we should keep the ocean clean.", "bis": "Ang ubang pawikan mokaon og dikya (jellyfish). Tungod niini, delikado ang plastik sa dagat — masaypan nila nga dikya ang naglutaw nga plastik ug kan-on kini, busa kinahanglan natong limpyohan ang dagat."}, "source": "encyclopedia-stable consensus; PH-relevant (marine conservation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "philippine-eagle-largest-g5", "domain": "LIVING_THINGS", "topic": "Philippine eagle", "grades": [4, 5, 6], "terms": ["Philippine eagle", "agila", "banog", "haring ibon", "national bird", "pambansang ibon", "monkey-eating eagle", "raptor", "agila sa Pilipinas", "pinakadako nga agila", "largest eagle", "wingspan", "pakpak"], "fact": {"tl": "Ang Philippine eagle (agila) ay isa sa pinakamalaking agila sa mundo, na may pakpak na umaabot ng mga dalawang metro, at ito ang pambansang ibon ng Pilipinas.", "en": "The Philippine eagle is one of the largest eagles in the world, with a wingspan of about two meters, and it is the national bird of the Philippines.", "bis": "Ang Philippine eagle (agila) usa sa pinakadako nga agila sa kalibotan, nga adunay pako nga mokabat og duha ka metro, ug kini ang nasodnong langgam sa Pilipinas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "philippine-eagle-diet-g5", "domain": "LIVING_THINGS", "topic": "Philippine eagle diet", "grades": [4, 5, 6], "terms": ["Philippine eagle", "agila", "monkey-eating", "kumakain", "gikaon", "unggoy", "monkey", "flying lemur", "predator", "mananakot", "mangangaso", "carnivore", "hunts", "nangayam"], "fact": {"tl": "Ang Philippine eagle ay mahusay na mangangaso na kumakain ng mga unggoy, flying lemur, ahas, at iba pang maliliit na hayop sa gubat.", "en": "The Philippine eagle is a skilled hunter that eats monkeys, flying lemurs, snakes, and other small forest animals.", "bis": "Ang Philippine eagle hanas nga mangangayam nga mokaon og mga unggoy, flying lemur, bitin, ug uban pang gagmayng hayop sa lasang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "philippine-eagle-endangered-g6", "domain": "LIVING_THINGS", "topic": "Philippine eagle endangered", "grades": [5, 6, 7], "terms": ["Philippine eagle", "agila", "endangered", "nanganganib", "nameligro", "critically endangered", "extinction", "deforestation", "pagkasira ng gubat", "pagkaguba sa lasang", "forest loss", "protected", "pinoprotektahan", "gipanalipdan"], "fact": {"tl": "Ang Philippine eagle ay critically endangered (lubhang nanganganib) dahil sa pagkawala ng kagubatan at pangangaso, kaya ipinagbabawal ng batas ang pamamaril dito.", "en": "The Philippine eagle is critically endangered because of forest loss and hunting, so the law forbids shooting it.", "bis": "Ang Philippine eagle critically endangered (grabe nga nameligro) tungod sa pagkawala sa kalasangan ug pagpangayam, mao nga gidili sa balaod ang pagpamusil niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "philippine-eagle-pair-chick-g6", "domain": "LIVING_THINGS", "topic": "Philippine eagle nesting", "grades": [5, 6, 7], "terms": ["Philippine eagle", "agila", "nest", "pugad", "salag", "isang itlog", "one egg", "usa ka itlog", "chick", "sisiw", "piso", "breeding", "pares", "pair", "mate for life", "slow to reproduce"], "fact": {"tl": "Ang mag-asawang Philippine eagle ay karaniwang nagpapalaki ng isang sisiw lamang kada ilang taon, kaya napakabagal nilang dumami at madaling manganib ang kanilang bilang.", "en": "A Philippine eagle pair usually raises only one chick every few years, so they reproduce very slowly and their numbers are easily threatened.", "bis": "Ang magtiayon nga Philippine eagle kasagaran nag-atiman lang og usa ka piso matag pipila ka tuig, mao nga hinay kaayo silang modaghan ug dali rang mameligro ang ilang gidaghanon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tarsier-smallest-primate-g4", "domain": "LIVING_THINGS", "topic": "Philippine tarsier", "grades": [3, 4, 5], "terms": ["tarsier", "mawmag", "mamag", "maomag", "primate", "pinakamaliit", "pinakagamay", "smallest primate", "tiny", "palad", "fits in hand", "Bohol", "kamot"], "fact": {"tl": "Ang tarsier (mawmag) ay isa sa pinakamaliit na primate sa mundo at kasinglaki lamang ng palad ng kamay ng tao.", "en": "The tarsier is one of the smallest primates in the world and is only about the size of a human palm.", "bis": "Ang tarsier (mawmag) usa sa pinakagamay nga primate sa kalibotan ug halos sama ra kadako sa palad sa tawo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tarsier-big-eyes-g4", "domain": "LIVING_THINGS", "topic": "tarsier eyes", "grades": [3, 4, 5], "terms": ["tarsier", "mawmag", "malalaking mata", "dagkong mata", "big eyes", "nocturnal", "gabi", "gabii", "night", "see in the dark", "nakikita sa dilim", "makakita sa ngitngit", "cannot move eyes", "ulo lumiko"], "fact": {"tl": "Ang tarsier ay may napakalalaking mata na tumutulong dito na makakita sa gabi, at dahil hindi nito magalaw ang mga mata, iniikot nito ang ulo para tumingin sa paligid.", "en": "The tarsier has very large eyes that help it see at night, and because it cannot move its eyes, it turns its head to look around.", "bis": "Ang tarsier adunay dagko kaayong mata nga makatabang niini nga makakita sa gabii, ug tungod kay dili kini makalihok sa mata, iyang gituyok ang ulo aron motan-aw sa palibot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tarsier-insect-eater-g4", "domain": "LIVING_THINGS", "topic": "tarsier diet", "grades": [3, 4, 5], "terms": ["tarsier", "mawmag", "insekto", "insects", "mokaon", "kumakain", "apan", "jumps", "lumukso", "milukso", "leaps", "carnivore", "grasshopper", "tipaklong"], "fact": {"tl": "Ang tarsier ay kumakain ng mga insekto tulad ng tipaklong, at marunong itong lumukso mula sa isang sanga papunta sa iba para manghuli.", "en": "The tarsier eats insects such as grasshoppers, and it can leap from one branch to another to catch its prey.", "bis": "Ang tarsier mokaon og mga insekto sama sa apan, ug makahibalo kining molukso gikan sa usa ka sanga ngadto sa lain aron mangdakop."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tarsier-stress-threat-g6", "domain": "LIVING_THINGS", "topic": "tarsier conservation", "grades": [5, 6, 7], "terms": ["tarsier", "mawmag", "endangered", "nanganganib", "nameligro", "habitat loss", "pagkasira ng tirahan", "pagkaguba sa puy-anan", "pet trade", "stress", "nilalaro", "gisturbo", "Bohol sanctuary", "protected"], "fact": {"tl": "Ang tarsier ay nanganganib dahil sa pagkawala ng gubat at pagkuha bilang alagang hayop, at madali itong mastress kapag hinahawakan, kaya dapat itong tantanan sa kagubatan.", "en": "The tarsier is threatened by forest loss and being taken as a pet, and it is easily stressed when handled, so it should be left alone in the wild.", "bis": "Ang tarsier nameligro tungod sa pagkawala sa lasang ug pagkuha isip binuhing hayop, ug dali kining ma-stress kung hikapon, mao nga angay kining pasagdan sa kalasangan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tamaraw-mindoro-g5", "domain": "LIVING_THINGS", "topic": "tamaraw", "grades": [4, 5, 6], "terms": ["tamaraw", "dwarf buffalo", "Mindoro", "kalabaw", "buffalo", "endemic", "matatagpuan lang", "makita lang", "horns", "sungay", "sungay nga V", "native"], "fact": {"tl": "Ang tamaraw ay isang maliit na uri ng kalabaw na matatagpuan lamang sa isla ng Mindoro sa Pilipinas.", "en": "The tamaraw is a small kind of buffalo found only on the island of Mindoro in the Philippines.", "bis": "Ang tamaraw usa ka gamayng matang sa kalabaw nga makita lamang sa isla sa Mindoro sa Pilipinas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tamaraw-vs-carabao-g5", "domain": "LIVING_THINGS", "topic": "tamaraw vs carabao", "grades": [4, 5, 6], "terms": ["tamaraw", "carabao", "kalabaw", "kabaw", "mas maliit", "mas gamay", "smaller", "wild", "mailap", "ihalas", "horns V-shape", "sungay", "difference", "kaibahan", "kalainan"], "fact": {"tl": "Ang tamaraw ay mas maliit kaysa karaniwang kalabaw, mailap (wild) ito at hindi inaalagaan, at hugis-V ang mga sungay nito.", "en": "The tamaraw is smaller than the ordinary carabao, it is wild and not domesticated, and its horns form a V-shape.", "bis": "Ang tamaraw mas gamay kaysa ordinaryong kalabaw, ihalas (wild) kini ug dili binuhi, ug hugis-V ang mga sungay niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tamaraw-critically-endangered-g6", "domain": "LIVING_THINGS", "topic": "tamaraw endangered", "grades": [6, 7, 8], "terms": ["tamaraw", "critically endangered", "lubhang nanganganib", "grabe nga nameligro", "few left", "kakaunti na", "pipila na lang", "hunting", "pangangaso", "pagpangayam", "habitat loss", "conservation", "Mounts Iglit-Baco"], "fact": {"tl": "Ang tamaraw ay critically endangered at iilang daan na lamang ang natitira sa ligaw dahil sa pangangaso at pagkawala ng kanilang tirahan.", "en": "The tamaraw is critically endangered, with only a few hundred left in the wild because of hunting and loss of their habitat.", "bis": "Ang tamaraw critically endangered ug pipila na lang ka gatos ang nahibilin sa ihalas tungod sa pagpangayam ug pagkawala sa ilang puy-anan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "carabao-national-animal-g3", "domain": "LIVING_THINGS", "topic": "carabao", "grades": [3, 4, 5], "terms": ["carabao", "kalabaw", "kabaw", "water buffalo", "national animal", "pambansang hayop", "nasodnong hayop", "work animal", "hayop na pantrabaho", "farmer", "magsasaka", "mag-uuma", "domesticated", "alaga"], "fact": {"tl": "Ang kalabaw (carabao) ay isang alagang hayop na tumutulong sa mga magsasaka sa pag-aararo ng bukid, at itinuturing itong pambansang hayop ng Pilipinas.", "en": "The carabao is a domesticated animal that helps farmers plow their fields, and it is regarded as the national animal of the Philippines.", "bis": "Ang kabaw (carabao) usa ka binuhing hayop nga makatabang sa mga mag-uuma sa pagdaro sa uma, ug giila kining nasodnong hayop sa Pilipinas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "carabao-wallows-mud-g4", "domain": "LIVING_THINGS", "topic": "carabao behavior", "grades": [3, 4, 5], "terms": ["carabao", "kalabaw", "kabaw", "putik", "lapok", "mud", "wallow", "lumulubog sa putik", "naligo sa lapok", "cool down", "nagpapalamig", "nagpabugnaw", "few sweat glands", "init", "adaptation"], "fact": {"tl": "Ang kalabaw ay lumulubog sa putik o tubig para magpalamig ng katawan, dahil kakaunti lang ang pawisan nito at madali itong mainitan.", "en": "The carabao wallows in mud or water to cool its body, because it has few sweat glands and overheats easily.", "bis": "Ang kabaw molubog sa lapok o tubig aron magpabugnaw sa lawas, tungod kay gamay ra kini og singot ug dali rang mainitan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "carabao-milk-g4", "domain": "LIVING_THINGS", "topic": "carabao milk", "grades": [3, 4, 5], "terms": ["carabao", "kalabaw", "kabaw", "gatas", "milk", "kesong puti", "white cheese", "puti nga keso", "pagkain", "produkto", "product", "nutritious", "masustansya", "dairy"], "fact": {"tl": "Bukod sa pagtulong sa bukid, ang kalabaw ay nagbibigay din ng gatas na ginagawang kesong puti at iba pang pagkain.", "en": "Besides helping on the farm, the carabao also gives milk that is made into white cheese and other foods.", "bis": "Gawas sa pagtabang sa uma, ang kabaw nagahatag usab og gatas nga ginahimong puti nga keso ug uban pang pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pawikan-sea-turtle-g4", "domain": "LIVING_THINGS", "topic": "pawikan sea turtle", "grades": [3, 4, 5], "terms": ["pawikan", "sea turtle", "pagong sa dagat", "reptile", "reptilya", "dagat", "sea", "ocean", "kabibe", "shell", "carapace", "flippers", "palikpik", "kapay", "swimmer", "langoy", "molangoy"], "fact": {"tl": "Ang pawikan ay isang malaking pagong na naninirahan sa dagat at gumagamit ng mga palikpik nito para makalangoy nang mabilis sa tubig.", "en": "The pawikan is a large sea turtle that lives in the ocean and uses its flippers to swim quickly through the water.", "bis": "Ang pawikan usa ka dakong bao sa dagat nga nagapuyo sa kadagatan ug nagagamit sa iyang mga kapay aron molangoy nga paspas sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pawikan-lays-eggs-beach-g5", "domain": "LIVING_THINGS", "topic": "pawikan nesting", "grades": [4, 5, 6], "terms": ["pawikan", "sea turtle", "itlog", "eggs", "nangingitlog", "nangitlog", "beach", "buhangin", "balas", "baybayon", "dalampasigan", "nest", "hatchling", "sisiw", "piso", "hatch", "babalik sa dagat"], "fact": {"tl": "Ang inahing pawikan ay umaahon sa dalampasigan para maglibing ng kanyang mga itlog sa buhangin, at pagkapisa, ang maliliit na pawikan ay gagapang pabalik sa dagat.", "en": "The mother pawikan crawls onto the beach to bury her eggs in the sand, and after hatching, the baby turtles crawl back to the sea.", "bis": "Ang inahan nga pawikan motungas sa baybayon aron ilubong ang iyang mga itlog sa balas, ug human mapusa, ang gagmayng pawikan mokamang balik sa dagat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pawikan-endangered-g6", "domain": "LIVING_THINGS", "topic": "pawikan conservation", "grades": [5, 6, 7], "terms": ["pawikan", "sea turtle", "endangered", "nanganganib", "nameligro", "protected", "pinoprotektahan", "gipanalipdan", "plastic", "basura", "poaching", "pollution", "polusyon", "fishing net", "lambat", "pukot", "ipinagbabawal"], "fact": {"tl": "Ang pawikan ay nanganganib dahil sa pagnanakaw ng kanilang itlog, polusyon ng plastik sa dagat, at pagkasilo sa lambat, kaya ipinagbabawal ng batas na saktan o kainin ito.", "en": "The pawikan is endangered because of egg poaching, plastic pollution in the sea, and getting caught in fishing nets, so the law forbids harming or eating it.", "bis": "Ang pawikan nameligro tungod sa pagpangawat sa ilang mga itlog, polusyon sa plastik sa dagat, ug pagkasangit sa pukot, mao nga gidili sa balaod ang pagdaot o pagkaon niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "butanding-whale-shark-largest-fish-g5", "domain": "LIVING_THINGS", "topic": "whale shark butanding", "grades": [4, 5, 6], "terms": ["butanding", "whale shark", "tuki", "pating", "balyena", "pinakamalaking isda", "pinakadako nga isda", "largest fish", "Donsol", "puntik", "spots", "gentle", "mabait", "maaghop", "shark", "isda"], "fact": {"tl": "Ang butanding (whale shark) ay ang pinakamalaking isda sa mundo, ngunit isa itong mabait na hayop na may magagandang puting puntik sa likod.", "en": "The whale shark (butanding) is the largest fish in the world, yet it is a gentle animal with beautiful white spots on its back.", "bis": "Ang butanding (whale shark) mao ang pinakadako nga isda sa kalibotan, apan usa kini ka maaghop nga hayop nga adunay nindot nga puti nga puntik sa likod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "butanding-filter-feeder-g5", "domain": "LIVING_THINGS", "topic": "whale shark feeding", "grades": [4, 5, 6], "terms": ["butanding", "whale shark", "plankton", "filter feeder", "sinasala", "gisala", "maliliit na hayop", "gagmayng tanom ug hayop", "tubig", "mouth", "bibig", "baba", "krill", "harmless", "hindi nananakot", "kumakain", "mokaon"], "fact": {"tl": "Bagamat napakalaki, ang butanding ay kumakain lamang ng maliliit na plankton sa pamamagitan ng pagsala ng tubig dagat sa malaki nitong bibig.", "en": "Although it is huge, the whale shark eats only tiny plankton by filtering seawater through its big mouth.", "bis": "Bisan og dako kaayo, ang butanding mokaon lamang og gagmayng plankton pinaagi sa pagsala sa tubig-dagat sa dako niining baba."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "butanding-donsol-tourism-g6", "domain": "LIVING_THINGS", "topic": "whale shark Donsol", "grades": [5, 6, 7], "terms": ["butanding", "whale shark", "Donsol", "Sorsogon", "Oslob", "tourist", "turista", "protected", "pinoprotektahan", "gipanalipdan", "endangered", "nanganganib", "nameligro", "migrate", "dumadayo", "mobalhin"], "fact": {"tl": "Ang butanding ay dumadayo sa mga karagatan ng Pilipinas tulad ng Donsol, at protektado ito ng batas dahil nanganganib na ang kanyang populasyon.", "en": "The whale shark migrates through Philippine seas such as Donsol, and it is protected by law because its population is threatened.", "bis": "Ang butanding mobalhin agi sa kadagatan sa Pilipinas sama sa Donsol, ug gipanalipdan kini sa balaod tungod kay nameligro na ang iyang populasyon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "visayan-warty-pig-g5", "domain": "LIVING_THINGS", "topic": "Visayan warty pig", "grades": [4, 5, 6], "terms": ["Visayan warty pig", "baboy ramo", "baboy ihalas", "baboy talunon", "wild pig", "warts", "kulugo", "tumpok ng balahibo", "mohawk", "buhok", "native pig", "endemic", "Visayas", "baboy"], "fact": {"tl": "Ang Visayan warty pig ay isang ligaw na baboy na matatagpuan lamang sa ilang isla ng Kabisayaan, at may mga kulugo (warts) sa mukha ang lalaki nito.", "en": "The Visayan warty pig is a wild pig found only on a few islands of the Visayas, and the male has warts on its face.", "bis": "Ang Visayan warty pig usa ka ihalas nga baboy nga makita lamang sa pipila ka isla sa Kabisay-an, ug ang lalaki adunay mga kulugo (warts) sa nawong."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "visayan-warty-pig-endangered-g6", "domain": "LIVING_THINGS", "topic": "warty pig endangered", "grades": [6, 7, 8], "terms": ["Visayan warty pig", "baboy ramo", "critically endangered", "lubhang nanganganib", "grabe nga nameligro", "hunting", "pangangaso", "pagpangayam", "habitat loss", "pagkawala ng gubat", "forest clearing", "captive breeding", "rare"], "fact": {"tl": "Ang Visayan warty pig ay critically endangered dahil sa pangangaso at pagkawala ng gubat, kaya iniaalaga ito sa ilang breeding center para hindi tuluyang mawala.", "en": "The Visayan warty pig is critically endangered because of hunting and forest loss, so it is cared for in breeding centers to keep it from disappearing entirely.", "bis": "Ang Visayan warty pig critically endangered tungod sa pagpangayam ug pagkawala sa lasang, mao nga gibuhi kini sa pipila ka breeding center aron dili kini mawala sa hingpit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "endemic-species-ph-g6", "domain": "LIVING_THINGS", "topic": "endemic species", "grades": [5, 6, 7], "terms": ["endemic", "tangi", "matatagpuan lang dito", "makita lang dinhi", "native", "katutubo", "lumad nga espisye", "island", "isla", "unique", "kakaiba", "tarsier", "tamaraw", "Philippine eagle", "found only"], "fact": {"tl": "Ang ilang hayop tulad ng tarsier, tamaraw, at Philippine eagle ay tinatawag na endemic dahil sa buong mundo ay matatagpuan lamang sila sa Pilipinas.", "en": "Some animals like the tarsier, tamaraw, and Philippine eagle are called endemic because in the whole world they are found only in the Philippines.", "bis": "Ang ubang hayop sama sa tarsier, tamaraw, ug Philippine eagle gitawag nga endemic tungod kay sa tibuok kalibotan makita lamang sila sa Pilipinas."}, "source": "NRC LS4.D; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-animals-endangered-g6", "domain": "LIVING_THINGS", "topic": "causes of endangerment", "grades": [5, 6, 7], "terms": ["endangered", "nanganganib", "nameligro", "habitat loss", "pagkasira ng tirahan", "pagkaguba sa puy-anan", "deforestation", "kalbong gubat", "hunting", "pangangaso", "pagpangayam", "pollution", "polusyon", "extinction", "pagkalipol", "why", "bakit", "ngano"], "fact": {"tl": "Nanganganib ang mga hayop kapag nawawasak ang kanilang tirahan, hinuhuli sila nang sobra, o nadudumihan ang kanilang kapaligiran — dahil dito, bumababa nang mabilis ang kanilang bilang.", "en": "Animals become endangered when their habitats are destroyed, they are hunted too much, or their surroundings are polluted — because of this, their numbers fall quickly.", "bis": "Mameligro ang mga hayop kung maguba ang ilang puy-anan, sobra silang pangayamon, o mahugawan ang ilang palibot — tungod niini, paspas nga mokunhod ang ilang gidaghanon."}, "source": "NRC LS2.C; AAAS BSL Ch.5", "generator": "claude-workflow", "reviewed": false},
  {"id": "protecting-wildlife-ph-g6", "domain": "LIVING_THINGS", "topic": "protecting wildlife", "grades": [5, 6, 7], "terms": ["protect", "pangalagaan", "panalipdan", "conservation", "pangangalaga", "pag-amping", "sanctuary", "kanlungan", "dalangpanan", "protected area", "law", "batas", "balaod", "reforestation", "muling pagtatanim", "how to help", "paano tumulong", "unsaon pagtabang"], "fact": {"tl": "Matutulungan nating maprotektahan ang mga endangered na hayop sa pamamagitan ng pagtatanim ng punò, paggawa ng mga sanctuary, at pagsunod sa batas na nagbabawal sa pangangaso.", "en": "We can help protect endangered animals by planting trees, creating sanctuaries, and following laws that forbid hunting them.", "bis": "Matabangan nato nga mapanalipdan ang mga endangered nga hayop pinaagi sa pagtanom og kahoy, paghimo og mga sanctuary, ug pagsunod sa balaod nga nagdili sa pagpangayam."}, "source": "NRC LS2.C; AAAS BSL Ch.5", "generator": "claude-workflow", "reviewed": false},
  {"id": "philippine-eagle-symbol-strength-g4", "domain": "LIVING_THINGS", "topic": "Philippine eagle symbol", "grades": [3, 4, 5], "terms": ["Philippine eagle", "agila", "symbol", "simbolo", "lakas", "strength", "kusog", "freedom", "kalayaan", "kagawasan", "national bird", "pambansang ibon", "forest health", "kalusugan ng gubat", "top predator"], "fact": {"tl": "Ang Philippine eagle ay simbolo ng lakas at kalayaan ng Pilipinas, at ang pagkakaroon nito sa gubat ay tanda na malusog pa ang kagubatan.", "en": "The Philippine eagle is a symbol of the strength and freedom of the Philippines, and its presence in a forest is a sign that the forest is still healthy.", "bis": "Ang Philippine eagle simbolo sa kusog ug kagawasan sa Pilipinas, ug ang presensya niini sa lasang timaan nga himsog pa ang kalasangan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pawikan-temperature-eggs-g7", "domain": "LIVING_THINGS", "topic": "sea turtle egg temperature", "grades": [7, 8, 9], "terms": ["pawikan", "sea turtle", "temperatura", "temperature", "init", "kainit", "sex", "kasarian", "babae", "lalaki", "male", "female", "warm", "mainit", "reproduction", "itlog", "eggs", "sand temperature"], "fact": {"tl": "Sa pawikan, ang temperatura ng buhangin na pinaglilibingan ng itlog ang nagtatakda kung ang mapipisang sisiw ay magiging lalaki o babae — mas mainit ay nagbubunga ng mas maraming babae.", "en": "In sea turtles, the temperature of the sand where the eggs are buried decides whether the hatchlings become male or female — warmer sand produces more females.", "bis": "Sa pawikan, ang temperatura sa balas diin gilubong ang mga itlog maoy magtino kung ang mapusa nga piso mahimong lalaki o babaye — mas init naghatag og mas daghang babaye."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tamaraw-grazer-grass-g5", "domain": "LIVING_THINGS", "topic": "tamaraw diet", "grades": [4, 5, 6], "terms": ["tamaraw", "grass", "damo", "sagbot", "kumakain", "mokaon", "herbivore", "grazer", "kawayan", "bamboo", "grassland", "kaparangan", "forest edge", "pastulan", "feeds"], "fact": {"tl": "Ang tamaraw ay herbivore na kumakain ng damo, dahon, at murang kawayan sa mga kaparangan at gilid ng gubat ng Mindoro.", "en": "The tamaraw is a herbivore that eats grass, leaves, and young bamboo in the grasslands and forest edges of Mindoro.", "bis": "Ang tamaraw herbivore nga mokaon og sagbot, dahon, ug batan-ong kawayan sa kasagbotan ug daplin sa lasang sa Mindoro."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "insect-body-parts-g3", "domain": "LIVING_THINGS", "topic": "insect body parts", "grades": [3, 4], "terms": ["insect", "insekto", "antenna", "antennae", "sungot", "feelers", "exoskeleton", "balat na matigas", "kabhang", "six legs", "anim na paa", "unom ka tiil", "wings", "pakpak", "pako", "ulo", "dughan", "tiyan"], "fact": {"tl": "Karamihan ng insekto ay may dalawang sungot (antennae) sa ulo na ginagamit para makaamoy at makaramdam, at may matigas na panlabas na balat (exoskeleton) na nagsisilbing baluti sa katawan nila.", "en": "Most insects have two feelers (antennae) on the head used to smell and sense things, and a hard outer shell (exoskeleton) that acts like armor for their body.", "bis": "Kasagaran sa mga insekto adunay duha ka sungot (antennae) sa ulo nga gigamit aron makasimhot ug makabati, ug adunay gahi nga gawas nga panit (exoskeleton) nga sama sa taming sa ilang lawas."}, "source": "AAAS BSL Ch.5 (diversity of life); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "insect-most-animals-g4", "domain": "LIVING_THINGS", "topic": "insects diversity", "grades": [4, 5, 6], "terms": ["insect", "insekto", "most animals", "pinakamarami", "kadaghanan", "species", "uri", "klase", "beetles", "salagubang", "bakukang", "million", "milyon", "grupo", "largest group"], "fact": {"tl": "Ang mga insekto ang pinakamaraming uri ng hayop sa mundo—mahigit isang milyong klase na ang natuklasan, at ang mga salagubang (beetles) ang may pinakamaraming uri sa lahat.", "en": "Insects are the most numerous kind of animal on Earth—over a million species have been discovered, and beetles make up more kinds than any other group.", "bis": "Ang mga insekto mao ang labing daghan nga matang sa hayop sa kalibotan—kapin sa usa ka milyon ka klase na ang nadiskobrehan, ug ang mga bakukang (beetles) mao ang adunay labing daghan nga matang sa tanan."}, "source": "AAAS BSL Ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "complete-metamorphosis-g4", "domain": "LIVING_THINGS", "topic": "complete metamorphosis", "grades": [4, 5, 6], "terms": ["metamorphosis", "metamorposis", "pagbabagong-anyo", "kompleto", "complete", "itlog", "egg", "larva", "uod", "ulod", "pupa", "supot", "adult", "hustong gulang", "butterfly", "paru-paro", "alibangbang"], "fact": {"tl": "Sa kumpletong metamorphosis, dumaraan ang insekto sa apat na yugto: itlog, uod (larva), pupa, at hustong gulang—gaya ng paru-paro at langaw.", "en": "In complete metamorphosis an insect passes through four stages: egg, larva, pupa, and adult—like butterflies and flies.", "bis": "Sa kompleto nga metamorphosis, ang insekto moagi sa upat ka yugto: itlog, ulod (larva), pupa, ug hamtong—sama sa alibangbang ug langaw."}, "source": "AAAS BSL Ch.5; NRC LS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "incomplete-metamorphosis-g5", "domain": "LIVING_THINGS", "topic": "incomplete metamorphosis", "grades": [5, 6, 7], "terms": ["incomplete metamorphosis", "di-kumpletong", "dili kompleto", "metamorphosis", "nymph", "tipaklong", "grasshopper", "apan", "itlog", "egg", "wala'y pupa", "walang pupa", "tatlong yugto", "tulo ka yugto"], "fact": {"tl": "Sa di-kumpletong metamorphosis, tatlong yugto lang ang dinaraanan: itlog, nymph (parang maliit na adulto na walang pakpak), at adulto—walang yugtong pupa, gaya ng tipaklong.", "en": "In incomplete metamorphosis there are only three stages: egg, nymph (a small wingless version of the adult), and adult—there is no pupa stage, as in grasshoppers.", "bis": "Sa dili kompleto nga metamorphosis, tulo ra ka yugto: itlog, nymph (gamay nga wala'y pako nga sama sa hamtong), ug hamtong—wala'y yugto nga pupa, sama sa apan."}, "source": "AAAS BSL Ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "butterfly-caterpillar-g3", "domain": "LIVING_THINGS", "topic": "butterfly life cycle", "grades": [3, 4, 5], "terms": ["butterfly", "paru-paro", "alibangbang", "caterpillar", "higad", "tangkong", "uod", "chrysalis", "supot", "cocoon", "wings", "pakpak", "pako", "itlog", "leaves", "dahon"], "fact": {"tl": "Ang paru-paro ay nagsisimula bilang itlog na nagiging higad (caterpillar) na kumakain ng dahon, pagkatapos ay nagiging pupa, at sa wakas ay lumalabas na may magandang pakpak.", "en": "A butterfly starts as an egg that becomes a caterpillar which eats leaves, then turns into a pupa, and finally comes out with beautiful wings.", "bis": "Ang alibangbang magsugod isip itlog nga mahimong tangkong (caterpillar) nga mokaon og dahon, dayon mahimong pupa, ug sa kataposan mogawas nga adunay nindot nga pako."}, "source": "AAAS BSL Ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "butterfly-pollinator-g4", "domain": "LIVING_THINGS", "topic": "butterflies pollination", "grades": [4, 5, 6], "terms": ["butterfly", "paru-paro", "alibangbang", "pollination", "polinasyon", "pollinator", "nectar", "nektar", "tamis", "bulaklak", "bulak", "flower", "proboscis", "sipsip", "sumisipsip", "mosuyop"], "fact": {"tl": "Sumisipsip ang paru-paro ng matamis na nektar mula sa bulaklak gamit ang mahabang dila nito, at habang ginagawa ito ay naililipat nito ang pollen kaya nakakatulong itong magbunga ang mga halaman.", "en": "A butterfly sips sweet nectar from flowers with its long tongue, and as it does it carries pollen from flower to flower, helping plants make fruit and seeds.", "bis": "Ang alibangbang mosuyop og tam-is nga nektar gikan sa bulak pinaagi sa taas niini nga dila, ug samtang naghimo niini madala niini ang pollen mao nga makatabang kini nga mamunga ang mga tanom."}, "source": "AAAS BSL Ch.5; NRC LS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bee-pollination-g4", "domain": "LIVING_THINGS", "topic": "bees pollination", "grades": [4, 5, 6], "terms": ["bee", "bubuyog", "putyukan", "pollination", "polinasyon", "pollinator", "polinador", "pollen", "bulaklak", "bulak", "flower", "crops", "pananim", "tanom", "food", "pagkaon", "nakakatulong", "makatabang"], "fact": {"tl": "Ang bubuyog ay mahalagang polinador—dala-dala nito ang pollen mula sa isang bulaklak papunta sa iba, kaya maraming pananim na kinakain natin ay namumunga.", "en": "Bees are important pollinators—they carry pollen from one flower to another, which helps many of the crops we eat to produce fruit and seeds.", "bis": "Ang putyukan importante kaayo isip pollinator—magdala kini og pollen gikan sa usa ka bulak ngadto sa lain, mao nga daghan sa mga tanom nga atong gikaon makapamunga."}, "source": "AAAS BSL Ch.5; NRC LS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bee-honey-g3", "domain": "LIVING_THINGS", "topic": "bees honey", "grades": [3, 4, 5], "terms": ["bee", "bubuyog", "putyukan", "honey", "pulot", "dugos", "honey bee", "nektar", "nectar", "beehive", "bahay-pukyutan", "balay", "pugad", "ginagawa", "gibuhat", "matamis"], "fact": {"tl": "Ginagawa ng pukyutan (honeybee) ang pulot-pukyutan (honey) mula sa nektar ng bulaklak, at iniimbak nila ito sa kanilang pugad bilang pagkain.", "en": "Honeybees make honey from flower nectar and store it in their hive as food.", "bis": "Ang putyukan (honeybee) maghimo og dugos (honey) gikan sa nektar sa bulak, ug tipigan nila kini sa ilang pugad isip pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bee-colony-roles-g5", "domain": "LIVING_THINGS", "topic": "bee colony", "grades": [5, 6, 7], "terms": ["bee", "bubuyog", "putyukan", "queen", "reyna", "queen bee", "worker", "manggagawa", "trabahante", "drone", "colony", "kolonya", "panon", "hive", "pugad", "itlog", "eggs", "grupo"], "fact": {"tl": "Sa isang kolonya ng pukyutan, may iisang queen na nangingitlog, libu-libong worker bee na naghahanap ng pagkain at nag-aalaga, at mga drone na ang gawain ay pakasalan ang queen.", "en": "In a bee colony there is one queen that lays the eggs, thousands of worker bees that gather food and care for the hive, and drones whose job is to mate with the queen.", "bis": "Sa usa ka kolonya sa putyukan, adunay usa ka queen nga mangitlog, liboan ka worker nga mangita og pagkaon ug moatiman sa pugad, ug mga drone nga ang buluhaton mao ang pagminyo sa queen."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bee-waggle-dance-g6", "domain": "LIVING_THINGS", "topic": "bee communication", "grades": [6, 7, 8], "terms": ["bee", "bubuyog", "putyukan", "waggle dance", "sayaw", "sayaw-sayaw", "communicate", "makigkomunikar", "nag-uusap", "direction", "direksyon", "nektar", "food", "pagkaon", "worker bee", "nagsasabi"], "fact": {"tl": "Kapag nakakita ng pagkain ang isang worker bee, sumasayaw ito ng tinatawag na waggle dance sa loob ng pugad para ituro sa iba ang direksyon at layo ng mga bulaklak.", "en": "When a worker bee finds food, it performs a waggle dance inside the hive to tell the other bees the direction and distance to the flowers.", "bis": "Kon makakita og pagkaon ang usa ka worker bee, mosayaw kini og gitawag nga waggle dance sulod sa pugad aron itudlo sa uban ang direksyon ug gilay-on sa mga bulak."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ant-colony-g3", "domain": "LIVING_THINGS", "topic": "ant colony", "grades": [3, 4, 5], "terms": ["ant", "langgam", "hulmigas", "colony", "kolonya", "panon", "queen", "reyna", "worker", "manggagawa", "trabahante", "nest", "pugad", "bahay", "magkakasama", "nagtutulungan", "grupo"], "fact": {"tl": "Ang mga langgam ay nakatira sa malalaking grupo na tinatawag na kolonya, kung saan nagtutulungan ang libu-libong manggagawang langgam para maghanap ng pagkain at mag-alaga sa pugad.", "en": "Ants live in large groups called colonies, where thousands of worker ants work together to find food and care for the nest.", "bis": "Ang mga hulmigas nagpuyo sa dagkong grupo nga gitawag og kolonya, diin liboan ka trabahante nga hulmigas magtinabangay aron mangita og pagkaon ug moatiman sa pugad."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ant-strength-g4", "domain": "LIVING_THINGS", "topic": "ant strength", "grades": [4, 5, 6], "terms": ["ant", "langgam", "hulmigas", "strong", "malakas", "kusgan", "carry", "pasan", "pasanin", "makina", "buhat", "mabug-at", "heavy", "body weight", "timbang", "sariling timbang"], "fact": {"tl": "Napakalakas ng langgam para sa laki nito—kaya nitong magbuhat ng bagay na mas mabigat pa kaysa sa sarili nitong katawan nang maraming beses.", "en": "Ants are very strong for their size—a single ant can lift objects many times heavier than its own body.", "bis": "Ang hulmigas kusgan kaayo alang sa gidak-on niini—makahimo kini sa pagbuhat og butang nga mas bug-at pa kay sa kaugalingong lawas niini sa daghang pilo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ant-communication-g5", "domain": "LIVING_THINGS", "topic": "ant communication", "grades": [5, 6, 7], "terms": ["ant", "langgam", "hulmigas", "pheromone", "amoy", "baho", "scent trail", "bakas", "subay", "trail", "daan", "communicate", "nag-uusap", "makigkomunikar", "sungot", "antennae", "sumusunod", "nagbabakas"], "fact": {"tl": "Nag-iiwan ang mga langgam ng amoy (pheromone) sa daan nila para masundan ng ibang langgam ang ruta papunta sa pagkain.", "en": "Ants leave a scent trail (pheromone) along their path so other ants can follow the route to food.", "bis": "Ang mga hulmigas magbilin og baho (pheromone) sa ilang agianan aron masubay sa ubang hulmigas ang dalan paingon sa pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "beetle-largest-group-g5", "domain": "LIVING_THINGS", "topic": "beetles", "grades": [5, 6, 7], "terms": ["beetle", "salagubang", "bakukang", "uang", "hard wings", "matigas na pakpak", "elytra", "balat", "exoskeleton", "pinakamarami", "kadaghanan", "species", "uri", "klase", "largest group"], "fact": {"tl": "Ang mga salagubang (beetles) ang may pinakamaraming uri sa lahat ng hayop, at may natatangi silang matigas na unang pares ng pakpak na nagsisilbing takip at panangga sa malambot nilang likod.", "en": "Beetles have more species than any other animal, and they have a special hard first pair of wings that act as a cover and shield over their soft back.", "bis": "Ang mga bakukang (beetles) adunay labing daghan nga matang sa tanang hayop, ug aduna silay pinasahi nga gahi nga unang paris sa pako nga nagsilbing tabon ug taming sa ilang humok nga likod."}, "source": "AAAS BSL Ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "firefly-light-g4", "domain": "LIVING_THINGS", "topic": "fireflies", "grades": [4, 5, 6], "terms": ["firefly", "alitaptap", "aninipot", "glow", "kumikislap", "nagsiga", "light", "ilaw", "kahayag", "bioluminescence", "beetle", "salagubang", "gabi", "night", "nagliliwanag", "init", "cold light"], "fact": {"tl": "Ang alitaptap ay isang uri ng salagubang na kayang gumawa ng sariling liwanag sa puwit nito para makahanap ng kapareha sa gabi—malamig ang liwanag na ito at halos walang init.", "en": "A firefly is a kind of beetle that can make its own light in its tail to find a mate at night—this light is cold and gives off almost no heat.", "bis": "Ang aninipot maoy usa ka matang sa bakukang nga makahimo og kaugalingong kahayag sa ikog niini aron makakita og kapares sa gabii—bugnaw kini nga kahayag ug halos wala'y kainit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mosquito-life-cycle-g4", "domain": "LIVING_THINGS", "topic": "mosquito life cycle", "grades": [4, 5, 6], "terms": ["mosquito", "lamok", "kiti-kiti", "wriggler", "larva", "uod", "tubig", "water", "itlog", "egg", "tubig na nakatigil", "stagnant water", "nangungutkot", "nagitlog", "tumutubo"], "fact": {"tl": "Ang lamok ay nangingitlog sa nakatigil na tubig, at ang mga itlog ay nagiging kiti-kiti (larva) na lumalangoy bago maging ganap na lamok.", "en": "Mosquitoes lay their eggs in still water, and the eggs become wrigglers (larvae) that swim before turning into adult mosquitoes.", "bis": "Ang lamok mangitlog sa hugaw o hunong nga tubig, ug ang mga itlog mahimong kiti-kiti (larva) nga molangoy una mahimong hingkod nga lamok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mosquito-disease-g5", "domain": "LIVING_THINGS", "topic": "mosquitoes disease", "grades": [5, 6, 7], "terms": ["mosquito", "lamok", "kiti-kiti", "dengue", "malaria", "sakit", "disease", "balatian", "Aedes", "kagat", "kuto", "kumakagat", "mopaak", "dugo", "blood", "nagdadala", "nagkakalat", "babae"], "fact": {"tl": "Tanging mga babaeng lamok lang ang kumakagat ng tao para sumipsip ng dugo, at ang ilang uri tulad ng Aedes ay nagdadala ng sakit na dengue—kaya mahalagang alisin ang nakatigil na tubig sa paligid.", "en": "Only female mosquitoes bite people to drink blood, and some kinds like Aedes carry the disease dengue—so it is important to remove still water around the home.", "bis": "Ang mga baye nga lamok ra ang mopaak sa tawo aron mosuyop og dugo, ug ang pipila ka matang sama sa Aedes magdala sa sakit nga dengue—busa importante nga kuhaon ang hunong nga tubig sa palibot."}, "source": "encyclopedia-stable consensus; DepEd health/science integration", "generator": "claude-workflow", "reviewed": false},
  {"id": "spider-arachnid-g4", "domain": "LIVING_THINGS", "topic": "spiders arachnids", "grades": [4, 5, 6], "terms": ["spider", "gagamba", "lawalawa", "arachnid", "eight legs", "walong paa", "walo ka tiil", "not insect", "hindi insekto", "dili insekto", "two body parts", "dalawang bahagi", "duha ka bahin", "walang antenna", "walang pakpak"], "fact": {"tl": "Ang gagamba ay hindi insekto kundi arachnid—walo ang paa nito, dalawa lang ang bahagi ng katawan, at wala itong sungot (antenna) o pakpak.", "en": "A spider is not an insect but an arachnid—it has eight legs, only two body parts, and no antennae or wings.", "bis": "Ang lawalawa dili insekto kondili arachnid—walo ang tiil niini, duha ra ka bahin sa lawas, ug wala kini sungot (antenna) o pako."}, "source": "AAAS BSL Ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "spider-web-silk-g3", "domain": "LIVING_THINGS", "topic": "spider webs", "grades": [3, 4, 5], "terms": ["spider", "gagamba", "lawalawa", "web", "bahay-gagamba", "sapot", "lawa", "silk", "sutla", "hilo", "strong", "matibay", "lig-on", "trap", "bitag", "huli", "makulit", "nanghuhuli", "gumagawa"], "fact": {"tl": "Gumagawa ang gagamba ng sapot (web) mula sa sariling sutla (silk) na napakatibay para manghuli ng insektong pagkain nito.", "en": "A spider makes a web from its own silk, which is surprisingly strong, to catch the insects it eats.", "bis": "Ang lawalawa maghimo og lawa (web) gikan sa kaugalingong sutla (silk) nga lig-on kaayo aron makadakop sa mga insekto nga kaonon niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "spider-predator-g4", "domain": "LIVING_THINGS", "topic": "spiders predators", "grades": [4, 5, 6], "terms": ["spider", "gagamba", "lawalawa", "predator", "mandaragit", "manunukob", "kumakain", "mokaon", "insekto", "insect", "pest", "peste", "helpful", "nakakatulong", "makatabang", "fangs", "pangil", "lason", "venom", "mosquito", "lamok"], "fact": {"tl": "Ang gagamba ay mandaragit na kumakain ng insekto, kaya nakakatulong ito sa tao sa pamamagitan ng pagbawas sa mga peste tulad ng lamok at langaw.", "en": "A spider is a predator that eats insects, so it helps people by reducing pests like mosquitoes and flies.", "bis": "Ang lawalawa maoy manunukob nga mokaon og insekto, mao nga makatabang kini sa tawo pinaagi sa pagpakunhod sa mga peste sama sa lamok ug langaw."}, "source": "AAAS BSL Ch.5; NRC LS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "spider-venom-fangs-g6", "domain": "LIVING_THINGS", "topic": "spider venom", "grades": [6, 7, 8], "terms": ["spider", "gagamba", "lawalawa", "venom", "lason", "hilo", "kamandag", "fangs", "pangil", "bite", "kagat", "paak", "biktima", "prey", "tunaw", "digest", "most harmless", "hindi nakakapinsala"], "fact": {"tl": "Karamihan ng gagamba ay may lason (venom) na inilalabas nila sa pamamagitan ng pangil para patayin ang biktima nila, ngunit karamihan ng gagamba ay hindi delikado sa tao.", "en": "Most spiders have venom that they inject through their fangs to subdue their prey, but the great majority of spiders are not dangerous to people.", "bis": "Kasagaran sa lawalawa adunay hilo (venom) nga ila kining ibuga pinaagi sa ilang pangil aron patyon ang ilang biktima, apan kadaghanan sa lawalawa dili delikado sa tawo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "insect-pollinators-food-g5", "domain": "LIVING_THINGS", "topic": "pollinators and food", "grades": [5, 6, 7], "terms": ["pollinator", "polinador", "insekto", "insect", "bee", "bubuyog", "putyukan", "butterfly", "paru-paro", "alibangbang", "food", "pagkaon", "crops", "pananim", "tanom", "prutas", "fruit", "mahalaga", "importante", "ecosystem"], "fact": {"tl": "Maraming prutas at gulay na kinakain natin ay umaasa sa mga insektong polinador tulad ng bubuyog at paru-paro; kung mawawala ang mga ito, mababawasan nang husto ang ating pagkain.", "en": "Many of the fruits and vegetables we eat depend on insect pollinators like bees and butterflies; if these insects disappeared, our food supply would shrink greatly.", "bis": "Daghan sa mga prutas ug utanon nga atong gikaon nagsalig sa mga insekto nga pollinator sama sa putyukan ug alibangbang; kon mawala kini, mokunhod pag-ayo ang atong pagkaon."}, "source": "AAAS BSL Ch.5; NRC LS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "insect-decomposers-g6", "domain": "LIVING_THINGS", "topic": "insect decomposers", "grades": [6, 7, 8], "terms": ["insect", "insekto", "decomposer", "mandurog", "tigdunot", "beetle", "salagubang", "bakukang", "dung beetle", "ant", "langgam", "hulmigas", "patay", "dead", "nabubulok", "recycling", "nutrients", "sustansya", "lupa", "soil", "nililinis"], "fact": {"tl": "May mga insekto tulad ng ilang salagubang at langgam na kumakain ng patay na hayop, halaman, o dumi, kaya tumutulong silang malinis ang kalikasan at maibalik ang sustansya sa lupa.", "en": "Some insects like certain beetles and ants feed on dead animals, plants, or waste, so they help clean nature and return nutrients to the soil.", "bis": "Adunay mga insekto sama sa pipila ka bakukang ug hulmigas nga mokaon og patay nga hayop, tanom, o hugaw, mao nga motabang sila sa paglimpyo sa kinaiyahan ug pag-uli sa sustansya sa yuta."}, "source": "AAAS BSL Ch.5; NRC LS2.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "insect-food-chain-g5", "domain": "LIVING_THINGS", "topic": "insects in food chain", "grades": [5, 6, 7], "terms": ["insect", "insekto", "food chain", "food web", "kadena ng pagkain", "kinaong-pagkaon", "prey", "biktima", "kinakain", "bird", "ibon", "langgam", "frog", "palaka", "baki", "lizard", "butiki", "tiki", "gagamba", "spider", "ecosystem"], "fact": {"tl": "Ang mga insekto ay mahalagang pagkain ng maraming hayop tulad ng ibon, palaka, butiki, at gagamba, kaya bahagi sila ng food chain o kadena ng pagkain.", "en": "Insects are an important food for many animals such as birds, frogs, lizards, and spiders, making them a key part of the food chain.", "bis": "Ang mga insekto importante nga pagkaon sa daghang hayop sama sa langgam (bird), baki, tiki, ug lawalawa, mao nga bahin sila sa food chain o kadena sa pagkaon."}, "source": "AAAS BSL Ch.5; NRC LS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "insect-compound-eyes-g6", "domain": "LIVING_THINGS", "topic": "compound eyes", "grades": [6, 7, 8], "terms": ["insect", "insekto", "compound eye", "mata", "compound eyes", "lente", "facets", "langaw", "fly", "bee", "bubuyog", "dragonfly", "tutubi", "alindahaw", "galaw", "movement", "paningin", "vision", "libu-libong", "maraming lente"], "fact": {"tl": "Maraming insekto tulad ng langaw at tutubi ay may compound eyes—mata na binubuo ng libu-libong maliliit na lente, kaya napakahusay nilang makakita ng mabilis na galaw.", "en": "Many insects like flies and dragonflies have compound eyes—eyes made of thousands of tiny lenses, which makes them very good at noticing fast movement.", "bis": "Daghang insekto sama sa langaw ug alindahaw adunay compound eyes—mga mata nga gilangkoban sa liboan ka gagmay nga lente, mao nga maayo kaayo sila motan-aw sa paspas nga lihok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "insect-cold-blooded-g6", "domain": "LIVING_THINGS", "topic": "insects and temperature", "grades": [6, 7, 8], "terms": ["insect", "insekto", "cold-blooded", "ectotherm", "init", "temperatura", "temperature", "araw", "sun", "aktibo", "active", "malamig", "cold", "tag-init", "warm", "nagpapainit", "kaaktibo", "mabagal"], "fact": {"tl": "Ang mga insekto ay cold-blooded, kaya nakadepende ang init ng kanilang katawan sa paligid—mas aktibo sila kapag mainit at mabagal kumilos kapag malamig.", "en": "Insects are cold-blooded, so their body temperature depends on their surroundings—they are more active when it is warm and sluggish when it is cold.", "bis": "Ang mga insekto cold-blooded, mao nga ang kainit sa ilang lawas nagsalig sa palibot—mas aktibo sila kon init ug hinay molihok kon bugnaw."}, "source": "AAAS BSL Ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "insect-camouflage-g5", "domain": "LIVING_THINGS", "topic": "insect camouflage", "grades": [5, 6, 7], "terms": ["insect", "insekto", "camouflage", "pagtatago", "pagtago", "panakip", "stick insect", "tikbalang-dahon", "leaf insect", "walking stick", "nagkukunwari", "mimic", "predator", "kaaway", "kulay", "color", "dahon", "leaf", "sanga", "nagtatago", "makaila"], "fact": {"tl": "May mga insekto tulad ng stick insect na ang hitsura ay parang sanga o dahon, isang uri ng camouflage para hindi sila makita at makain ng mga kaaway nila.", "en": "Some insects like the stick insect look just like a twig or leaf, a kind of camouflage that hides them from the predators that would eat them.", "bis": "Adunay mga insekto sama sa stick insect nga ang dagway sama sa sanga o dahon, usa ka matang sa camouflage aron dili sila makita ug kaonon sa ilang mga kaaway."}, "source": "AAAS BSL Ch.5; NRC LS4.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bee-decline-importance-g6", "domain": "LIVING_THINGS", "topic": "protecting bees", "grades": [6, 7, 8], "terms": ["bee", "bubuyog", "putyukan", "protect", "pangalagaan", "panalipdan", "pesticide", "kemikal", "pestisidyo", "bawas", "decline", "nababawasan", "pollinator", "pananim", "crops", "kalikasan", "environment", "mahalaga", "importante", "kalusugan"], "fact": {"tl": "Mahalagang pangalagaan ang mga bubuyog dahil kapag bumaba ang bilang nila, mahihirapang mamunga ang maraming pananim—nakakasama sa kanila ang labis na kemikal o pestisidyo sa bukid.", "en": "Protecting bees matters because if their numbers fall, many crops struggle to produce fruit—too much chemical pesticide in fields can harm them.", "bis": "Importante nga panalipdan ang mga putyukan kay kon mokunhod ang ilang gidaghanon, maglisod og pamunga ang daghang tanom—makadaot kanila ang sobra nga kemikal o pestisidyo sa uma."}, "source": "NRC LS2.C; LS4.D; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "reptiles-cold-blooded-g4", "domain": "LIVING_THINGS", "topic": "reptiles are cold-blooded", "grades": [3, 4, 5], "terms": ["reptilya", "reptile", "malamig ang dugo", "cold-blooded", "ectotherm", "init", "araw", "temperatura", "bugnaw ang dugo", "bugnaw", "kainit", "adlaw", "nagpapainit", "magpainit sa adlaw"], "fact": {"tl": "Ang mga reptilya tulad ng ahas, butiki, at pagong ay 'malamig ang dugo' (cold-blooded), kaya nakasalalay sila sa init ng paligid; madalas silang magpapainit sa araw para tumaas ang temperatura ng katawan nila.", "en": "Reptiles like snakes, lizards, and turtles are 'cold-blooded,' so they rely on the warmth around them; they often bask in the sun to raise their body temperature.", "bis": "Ang mga reptilya sama sa bitin, tiki, ug baw 'bugnaw ang dugo' (cold-blooded), busa nagsalig sila sa kainit sa palibot; kasagaran magpainit sila sa adlaw aron motaas ang temperatura sa ilang lawas."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks 5C (cells/organisms regulation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "amphibians-cold-blooded-g4", "domain": "LIVING_THINGS", "topic": "amphibians are cold-blooded", "grades": [3, 4, 5], "terms": ["amphibian", "palaka", "frog", "salamander", "malamig ang dugo", "cold-blooded", "bugnaw ang dugo", "temperatura sa katawan", "init sa palibot", "kainit", "baki"], "fact": {"tl": "Ang mga amphibian tulad ng palaka at salamander ay 'malamig ang dugo' din; sumusunod ang temperatura ng katawan nila sa init o lamig ng tubig at hangin sa paligid.", "en": "Amphibians like frogs and salamanders are also 'cold-blooded'; their body temperature follows the warmth or coolness of the water and air around them.", "bis": "Ang mga amphibian sama sa baki ug salamander 'bugnaw usab ang dugo'; ang temperatura sa ilang lawas mosunod sa kainit o kabugnaw sa tubig ug hangin sa palibot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "reptiles-scales-g4", "domain": "LIVING_THINGS", "topic": "reptiles have dry scaly skin", "grades": [3, 4, 5], "terms": ["reptilya", "reptile", "kaliskis", "scales", "balat", "tuyo", "dry skin", "tuyong balat", "himbis", "panit", "uga", "protektado", "tubig sa katawan", "uga nga panit"], "fact": {"tl": "Ang mga reptilya ay may tuyong balat na natatakpan ng kaliskis (scales); tumutulong ito para hindi sila matuyuan, kaya kaya nilang mabuhay sa tuyong lugar.", "en": "Reptiles have dry skin covered with scales; this helps keep them from drying out, so they can live in dry places.", "bis": "Ang mga reptilya adunay uga nga panit nga gitabonan og himbis (scales); makatabang kini aron dili sila mauga, busa makapuyo sila sa uga nga dapit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "amphibians-moist-skin-g4", "domain": "LIVING_THINGS", "topic": "amphibians have moist skin", "grades": [3, 4, 5], "terms": ["amphibian", "palaka", "balat", "basa", "moist skin", "manipis na balat", "huminga sa balat", "panit", "umog", "basa-basa", "huminga", "tubig", "baki", "basa nga panit"], "fact": {"tl": "Hindi tulad ng reptilya, ang mga amphibian ay may manipis at basa-basang balat na walang kaliskis; nakakahinga sila sa pamamagitan ng balat na ito, kaya kailangan nilang manatiling mamasa-masa.", "en": "Unlike reptiles, amphibians have thin, moist skin without scales; they can breathe through this skin, so they must stay damp.", "bis": "Lahi sa reptilya, ang mga amphibian adunay nipis ug umog nga panit nga walay himbis; makaginhawa sila pinaagi niini nga panit, busa kinahanglan magpabiling basa-basa sila."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "reptiles-eggs-land-g5", "domain": "LIVING_THINGS", "topic": "reptiles lay leathery eggs on land", "grades": [4, 5, 6], "terms": ["reptilya", "itlog", "eggs", "lupa", "land", "balat na itlog", "leathery", "nangingitlog", "itlog sa yuta", "mangitlog", "yuta", "shell", "balat", "bagol"], "fact": {"tl": "Karamihan ng mga reptilya ay nangingitlog sa lupa, at ang kanilang itlog ay may matibay, parang-katad na balat na hindi madaling matuyo.", "en": "Most reptiles lay their eggs on land, and their eggs have a tough, leathery shell that does not dry out easily.", "bis": "Kasagaran sa mga reptilya mangitlog sa yuta, ug ang ilang mga itlog adunay gahi, sama-sa-panit nga bagol nga dili dali mauga."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "amphibians-eggs-water-g5", "domain": "LIVING_THINGS", "topic": "amphibians lay eggs in water", "grades": [4, 5, 6], "terms": ["amphibian", "palaka", "itlog", "eggs", "tubig", "water", "walang balat na itlog", "jelly", "malambot", "mangitlog sa tubig", "itlog sa tubig", "baki", "humok nga itlog"], "fact": {"tl": "Karamihan ng mga amphibian ay nangingitlog sa tubig; ang kanilang itlog ay malambot at walang matigas na balat, kaya kailangan itong manatili sa basang lugar.", "en": "Most amphibians lay their eggs in water; their eggs are soft and have no hard shell, so they must stay in a wet place.", "bis": "Kasagaran sa mga amphibian mangitlog sa tubig; ang ilang mga itlog humok ug walay gahi nga bagol, busa kinahanglan magpabilin kini sa basa nga dapit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "frog-metamorphosis-g5", "domain": "LIVING_THINGS", "topic": "frog life cycle metamorphosis", "grades": [4, 5, 6], "terms": ["palaka", "frog", "metamorphosis", "metamorposis", "itlog", "tadpole", "ulo-ulo", "tubig", "life cycle", "siklo ng buhay", "baki", "kinabuhi", "buntot", "ikog"], "fact": {"tl": "Ang palaka ay dumaraan sa metamorphosis: nagsisimula ito bilang itlog, nagiging tadpole (ulo-ulo) na may buntot at namumuhay sa tubig, at unti-unting tumutubo ang mga paa hanggang maging palaka.", "en": "A frog goes through metamorphosis: it starts as an egg, becomes a tadpole with a tail that lives in water, and slowly grows legs until it turns into a frog.", "bis": "Ang baki moagi sa metamorphosis: magsugod kini isip itlog, mahimong tadpole (ulo-ulo) nga may ikog ug nagpuyo sa tubig, ug hinay-hinay motubo ang mga tiil hangtod mahimo kining baki."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks 5B (heredity/life cycles)", "generator": "claude-workflow", "reviewed": false},
  {"id": "tadpole-gills-g6", "domain": "LIVING_THINGS", "topic": "tadpoles breathe with gills", "grades": [5, 6, 7], "terms": ["tadpole", "ulo-ulo", "hasang", "gills", "huminga sa tubig", "baga", "lungs", "palaka", "baki", "nabuhi sa tubig", "ginhawaan", "magginhawa"], "fact": {"tl": "Ang tadpole (ulo-ulo) ay humihinga sa pamamagitan ng hasang (gills) tulad ng isda; sa paglaki nito at pagtubo ng baga, saka pa lamang ito makakahinga ng hangin sa labas ng tubig.", "en": "A tadpole breathes with gills like a fish; only when it grows and develops lungs can it breathe air outside the water.", "bis": "Ang tadpole (ulo-ulo) magginhawa pinaagi sa hasang (gills) sama sa isda; sa pagdako niini ug pagtubo sa baga, saka pa lang kini makaginhawa og hangin sa gawas sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "snake-shed-skin-g5", "domain": "LIVING_THINGS", "topic": "snakes shed their skin", "grades": [4, 5, 6], "terms": ["ahas", "snake", "bitin", "nagpapalit ng balat", "shed skin", "molting", "balat", "nag-iiwan ng balat", "lumalaki", "nahuhubad ang balat", "panit", "naglubad", "pag-ilis sa panit", "modako"], "fact": {"tl": "Habang lumalaki ang ahas, nahuhubad at naiiwan nito ang lumang balat nang buo; tinatawag itong pagpapalit ng balat (molting), at nangyayari ito nang ilang beses sa isang taon.", "en": "As a snake grows, it sheds and leaves behind its old skin in one piece; this is called molting, and it happens several times a year.", "bis": "Samtang modako ang bitin, maglubad ug mabilin ang daan niini nga panit nga tibuok; gitawag kining pag-ilis sa panit (molting), ug mahitabo kini pila ka beses sa usa ka tuig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "snake-jaw-swallow-g6", "domain": "LIVING_THINGS", "topic": "snakes swallow large prey", "grades": [5, 6, 7], "terms": ["ahas", "snake", "bitin", "panga", "jaw", "biktima", "prey", "nilululon", "swallow", "buo", "malaking biktima", "naglulon", "apapangig", "lamoy"], "fact": {"tl": "Kaya ng ahas na lulunin nang buo ang biktimang mas malaki kaysa sa ulo nito dahil ang mga buto ng panga nito ay maaaring magbukas nang napakalapad.", "en": "A snake can swallow prey larger than its own head because the bones of its jaw can spread very wide apart.", "bis": "Makahimo ang bitin sa paglamoy og tibuok nga biktima nga mas dako pa kaysa ulo niini tungod kay ang mga bukog sa apapangig niini makaabli og halapad kaayo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "snake-venom-g6", "domain": "LIVING_THINGS", "topic": "some snakes are venomous", "grades": [5, 6, 7], "terms": ["ahas", "snake", "bitin", "kamandag", "venom", "venomous", "lason", "pangil", "fangs", "makamandag", "biktima", "hilo", "tango", "makahilo"], "fact": {"tl": "Ang ilang mga ahas ay may kamandag (venom) na ipinapasok nila sa biktima sa pamamagitan ng matatalas na pangil; hindi lahat ng ahas ay makamandag, marami sa kanila ay walang lason.", "en": "Some snakes have venom that they inject into prey through sharp fangs; not all snakes are venomous, and many have no venom at all.", "bis": "Ang ubang mga bitin adunay hilo (venom) nga ilang ituslok sa biktima pinaagi sa hait nga mga tango; dili tanang bitin makahilo, daghan kanila ang walay hilo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "snake-jacobson-tongue-g6", "domain": "LIVING_THINGS", "topic": "snake forked tongue smells", "grades": [5, 6, 7], "terms": ["ahas", "snake", "bitin", "dila", "tongue", "sanga", "forked", "amoy", "smell", "biyak ang dila", "nakakaamoy", "dila nga nasanga", "baho", "simhot"], "fact": {"tl": "Ang dila ng ahas ay biyak sa dulo (forked); ginagamit nito ito para 'damhin' ang amoy sa hangin at hanapin ang pagkain o kaaway nito.", "en": "A snake's tongue is forked at the tip; it uses it to 'sense' smells in the air and find food or enemies.", "bis": "Ang dila sa bitin nasanga sa tumoy (forked); gamiton niini kini aron 'masimhot' ang baho sa hangin ug pangitaon ang pagkaon o kaaway niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "python-constrictor-g6", "domain": "LIVING_THINGS", "topic": "pythons squeeze prey", "grades": [5, 6, 7], "terms": ["python", "sawa", "ahas", "constrictor", "pumupulupot", "squeeze", "biktima", "walang kamandag", "walay hilo", "bitin", "liyokan", "humigpit", "piit"], "fact": {"tl": "Ang sawa (python) ay isang malaking ahas na walang kamandag; pinupuluputan nito ang biktima at pinipigil ang paghinga nito bago ito lulunin.", "en": "A python is a large snake with no venom; it wraps around its prey and squeezes to stop it from breathing before swallowing it.", "bis": "Ang sawa (python) usa ka dako nga bitin nga walay hilo; liyokan niini ang biktima ug ipiit aron pugngan ang pagginhawa niini sa dili pa lamyon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lizard-tail-drop-g5", "domain": "LIVING_THINGS", "topic": "lizards drop their tails", "grades": [4, 5, 6], "terms": ["butiki", "lizard", "tiki", "tail", "buntot", "naglalaglag ng buntot", "drop tail", "tumutubo ulit", "regrow", "kaaway", "naputol ang ikog", "ikog", "tabili", "motubo balik"], "fact": {"tl": "Maraming butiki ang kayang ihulog ang buntot nila kapag inaatake; patuloy na gumagalaw ang naputol na buntot para mailigaw ang kaaway, at unti-unting tumutubo muli ang bago.", "en": "Many lizards can drop their tail when attacked; the broken tail keeps wriggling to distract the enemy, and a new one slowly grows back.", "bis": "Daghang tiki ang makahimo sa pagtangtang sa ikog nila kung atakihon; ang naputol nga ikog magpadayon sa paglihok aron malingla ang kaaway, ug hinay-hinay motubo og bag-o."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gecko-sticky-feet-g5", "domain": "LIVING_THINGS", "topic": "geckos climb walls", "grades": [4, 5, 6], "terms": ["tuko", "gecko", "butiki", "tiki", "dingding", "wall", "umaakyat", "climb", "dumidikit", "sticky feet", "paa", "kumakapit sa pader", "tiil", "bongbong", "mokapyot"], "fact": {"tl": "Ang tuko (gecko) ay isang butiking kayang umakyat sa makinis na dingding at kisame dahil ang mga paa nito ay natatakpan ng napakaliliit na buhok na dumidikit sa ibabaw.", "en": "A gecko is a lizard that can climb smooth walls and ceilings because its feet are covered with tiny hairs that grip the surface.", "bis": "Ang tuko (gecko) usa ka tiki nga makahimo og saka sa hamis nga bongbong ug kisami tungod kay ang mga tiil niini gitabonan og gagmay kaayo nga balhibo nga mokapyot sa nawong sa butang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "chameleon-color-g5", "domain": "LIVING_THINGS", "topic": "chameleons change color", "grades": [4, 5, 6], "terms": ["chameleon", "hunyango", "butiki", "tiki", "nagpapalit ng kulay", "change color", "kulay", "mata", "dila", "nag-iiba ang kulay", "kolor", "nagbag-o ang kolor"], "fact": {"tl": "Ang chameleon (hunyango) ay isang butiking kayang baguhin ang kulay ng balat nito; ginagamit nila ito para magtago, makipag-usap, o ayusin ang init ng katawan.", "en": "A chameleon is a lizard that can change the color of its skin; it uses this to hide, to communicate, or to adjust its body heat.", "bis": "Ang chameleon (hunyango) usa ka tiki nga makahimo og usab sa kolor sa panit niini; gamiton nila kini aron motago, makigsulti, o iayos ang kainit sa lawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "komodo-dragon-g6", "domain": "LIVING_THINGS", "topic": "komodo dragon largest lizard", "grades": [5, 6, 7], "terms": ["komodo dragon", "komodo", "bayawak", "butiki", "lizard", "pinakamalaki", "largest", "Indonesia", "mandaragit", "predator", "tiki", "pinakadako", "manunukob", "halo"], "fact": {"tl": "Ang Komodo dragon ang pinakamalaking butiki sa mundo at maaaring umabot ng halos 3 metro ang haba; mabangis itong mandaragit na matatagpuan sa ilang isla ng Indonesia.", "en": "The Komodo dragon is the largest lizard in the world and can grow nearly 3 meters long; it is a fierce predator found on a few islands of Indonesia.", "bis": "Ang Komodo dragon mao ang pinakadako nga tiki sa kalibotan ug makaabot og hapit 3 ka metro ang gitas-on; usa kini ka bangis nga manunukob nga makit-an sa pipila ka isla sa Indonesia."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "monitor-lizard-philippines-g6", "domain": "LIVING_THINGS", "topic": "philippine monitor lizard", "grades": [5, 6, 7], "terms": ["bayawak", "monitor lizard", "butiki", "Pilipinas", "Philippines", "endemic", "lumalangoy", "halo", "molangoy", "mosaka sa kahoy", "tiki sa Pilipinas", "mananap sa Pilipinas"], "fact": {"tl": "Ang bayawak (monitor lizard) ay isang malaking butiking matatagpuan sa Pilipinas; mahuhusay silang lumangoy at umakyat ng puno, at may ilang uri na tanging sa Pilipinas lamang naninirahan.", "en": "The monitor lizard is a large lizard found in the Philippines; they are strong swimmers and tree-climbers, and some kinds live only in the Philippines.", "bis": "Ang halo (monitor lizard) usa ka dako nga tiki nga makit-an sa Pilipinas; maayo sila molangoy ug mosaka sa kahoy, ug adunay pipila ka matang nga sa Pilipinas lamang nagpuyo."}, "source": "encyclopedia-stable consensus; DepEd MATATAG (native PH species)", "generator": "claude-workflow", "reviewed": false},
  {"id": "turtle-shell-g4", "domain": "LIVING_THINGS", "topic": "turtles have protective shells", "grades": [3, 4, 5], "terms": ["pagong", "turtle", "bao", "talukab", "shell", "protektado", "buto", "nagtatago", "kalasag", "baw", "bagol", "bukog", "kuyaw"], "fact": {"tl": "Ang pagong ay may matigas na talukab (shell) na bahagi ng kanyang katawan at nakakabit sa kanyang buto; ito ang nagsisilbing kalasag na pinagtataguan nito kapag may panganib.", "en": "A turtle has a hard shell that is part of its body and joined to its bones; the shell acts as armor it hides inside when there is danger.", "bis": "Ang baw adunay gahi nga bagol (shell) nga kabahin sa lawas niini ug konektado sa mga bukog niini; ang bagol mao ang kalasag nga gisuksokan niini kung adunay kuyaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sea-turtle-philippines-g6", "domain": "LIVING_THINGS", "topic": "sea turtles pawikan", "grades": [5, 6, 7], "terms": ["pawikan", "sea turtle", "pagong sa dagat", "dagat", "buhangin", "beach", "nangingitlog", "endangered", "nanganganib", "lumalangoy", "baw sa dagat", "nangitlog sa baybayon", "namiligro"], "fact": {"tl": "Ang pawikan (sea turtle) ay isang pagong na namumuhay sa dagat; bumabalik ang inahin sa baybayin para maglibing ng itlog sa buhangin, at marami sa kanila ay nanganganib nang maubos sa Pilipinas.", "en": "A sea turtle is a turtle that lives in the ocean; the mother returns to the shore to bury her eggs in the sand, and many of them are endangered in the Philippines.", "bis": "Ang pawikan (sea turtle) usa ka baw nga nagpuyo sa dagat; mobalik ang inahan sa baybayon aron ilubong ang itlog sa balas, ug daghan kanila ang namiligro nga mahurot sa Pilipinas."}, "source": "encyclopedia-stable consensus; DepEd MATATAG (native PH species, conservation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "turtle-no-teeth-g5", "domain": "LIVING_THINGS", "topic": "turtles have beaks not teeth", "grades": [4, 5, 6], "terms": ["pagong", "turtle", "bao", "tuka", "beak", "walang ngipin", "no teeth", "ngipin", "kumakain", "matigas na bibig", "baw", "walay ngipon", "tuka nga gahi"], "fact": {"tl": "Ang mga pagong ay walang ngipin; sa halip, mayroon silang matigas na tuka na parang sa ibon na ginagamit nila para putulin at kainin ang pagkain.", "en": "Turtles have no teeth; instead they have a hard beak like a bird's that they use to cut and eat their food.", "bis": "Ang mga baw walay ngipon; hinunoa, aduna silay gahi nga tuka sama sa langgam nga gamiton nila aron putlon ug kan-on ang pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "turtle-tortoise-difference-g6", "domain": "LIVING_THINGS", "topic": "turtle versus tortoise", "grades": [5, 6, 7], "terms": ["pagong", "turtle", "tortoise", "bao", "lupa", "tubig", "land", "water", "pagkakaiba", "naninirahan sa lupa", "naninirahan sa tubig", "baw sa yuta", "baw sa tubig", "kalainan"], "fact": {"tl": "Ang 'turtle' ay karaniwang naninirahan o gumugugol ng oras sa tubig, samantalang ang 'tortoise' ay isang pagong na nakatira sa lupa at may makakapal na paa para maglakad.", "en": "A 'turtle' usually lives or spends time in water, while a 'tortoise' is a turtle that lives on land and has thick, sturdy legs for walking.", "bis": "Ang 'turtle' kasagaran nagpuyo o naggugol og panahon sa tubig, samtang ang 'tortoise' usa ka baw nga nagpuyo sa yuta ug adunay baga nga mga tiil aron makalakaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "frog-jump-legs-g4", "domain": "LIVING_THINGS", "topic": "frogs jump with strong legs", "grades": [3, 4, 5], "terms": ["palaka", "frog", "baki", "tumatalon", "jump", "lumukso", "malalakas na paa", "strong legs", "hulihang paa", "binti", "naglukso", "tiil nga kusgan", "molukso"], "fact": {"tl": "Ang palaka ay may mahaba at malalakas na hulihang paa na ginagamit nito para lumukso nang malayo, kaya madali itong makatakas sa mga mandaragit.", "en": "A frog has long, strong hind legs that it uses to leap far, so it can quickly escape from predators.", "bis": "Ang baki adunay tag-as ug kusgan nga likoran nga mga tiil nga gamiton niini aron molukso og layo, busa dali kining makaikyas sa mga manunukob."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "frog-sticky-tongue-g4", "domain": "LIVING_THINGS", "topic": "frogs catch insects with tongue", "grades": [3, 4, 5], "terms": ["palaka", "frog", "baki", "dila", "tongue", "malagkit", "sticky", "insekto", "insect", "nanghuhuli", "biktima", "dila nga pilit", "modakop", "lamok"], "fact": {"tl": "Ang palaka ay nanghuhuli ng insekto gamit ang mahaba at malagkit nitong dila na mabilis nitong inilalabas para mahuli ang biktima.", "en": "A frog catches insects with its long, sticky tongue, which it flicks out quickly to grab its prey.", "bis": "Ang baki modakop og insekto gamit ang taas ug pilit niini nga dila nga dali niining ipagawas aron makuha ang biktima."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "toad-vs-frog-g5", "domain": "LIVING_THINGS", "topic": "toad versus frog", "grades": [4, 5, 6], "terms": ["palaka", "frog", "toad", "baki", "tuyo na balat", "bumpy skin", "kulugong balat", "lupa", "basa", "pagkakaiba", "panit nga kulugo", "uga nga panit", "kalainan"], "fact": {"tl": "Ang 'toad' ay isang uri ng palaka na may mas tuyo at kulugong balat at madalas namumuhay sa lupa, samantalang ang karaniwang 'frog' ay may makinis at basang balat malapit sa tubig.", "en": "A 'toad' is a kind of frog with drier, bumpy skin that often lives on land, while an ordinary 'frog' has smooth, moist skin and stays near water.", "bis": "Ang 'toad' usa ka matang sa baki nga adunay mas uga ug kulugo nga panit ug kasagaran nagpuyo sa yuta, samtang ang ordinaryong 'frog' adunay hamis ug umog nga panit duol sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "salamander-regrow-g6", "domain": "LIVING_THINGS", "topic": "salamanders regrow body parts", "grades": [5, 6, 7], "terms": ["salamander", "amphibian", "tumutubo ulit", "regrow", "paa", "buntot", "limb", "tail", "tiil nga motubo balik", "ikog", "nawala", "patubo balik"], "fact": {"tl": "Ang salamander ay isang amphibian na kayang patubuin muli ang nawalang paa o buntot nito; iilan lamang sa mga hayop ang may ganitong kakayahan.", "en": "A salamander is an amphibian that can regrow a lost leg or tail; only a few animals have this ability.", "bis": "Ang salamander usa ka amphibian nga makahimo og patubo balik sa nawala niini nga tiil o ikog; pipila lamang ka mananap ang adunay ingon niini nga abilidad."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "salamander-vs-lizard-g6", "domain": "LIVING_THINGS", "topic": "salamander not a lizard", "grades": [5, 6, 7], "terms": ["salamander", "lizard", "butiki", "tiki", "amphibian", "reptilya", "basang balat", "kaliskis", "pagkakaiba", "hindi butiki", "panit nga basa", "dili tiki", "kalainan", "himbis"], "fact": {"tl": "Kahit kamukha ng butiki ang salamander, hindi ito reptilya kundi isang amphibian; makinis at basa ang balat nito at walang kaliskis, hindi tulad ng tuyo at makaliskis na butiki.", "en": "Although a salamander looks like a lizard, it is not a reptile but an amphibian; its skin is smooth and moist with no scales, unlike a lizard's dry, scaly skin.", "bis": "Bisan og morag tiki ang salamander, dili kini reptilya kondili usa ka amphibian; hamis ug umog ang panit niini nga walay himbis, lahi sa uga ug himbison nga panit sa tiki."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "reptiles-amphibians-vertebrates-g6", "domain": "LIVING_THINGS", "topic": "reptiles and amphibians are vertebrates", "grades": [5, 6, 7], "terms": ["reptilya", "amphibian", "gulugod", "backbone", "vertebrate", "may buto", "spine", "ahas", "palaka", "pagong", "may gulugod", "klasipikasyon", "bukog sa likod", "bukog"], "fact": {"tl": "Ang mga reptilya at amphibian ay parehong may gulugod (backbone), kaya kabilang sila sa mga hayop na tinatawag na vertebrate, tulad din ng mga isda, ibon, at mammal.", "en": "Reptiles and amphibians both have a backbone, so they belong to the group of animals called vertebrates, just like fish, birds, and mammals.", "bis": "Ang mga reptilya ug amphibian parehong adunay gulugod (backbone), busa sakop sila sa grupo sa mga mananap nga gitawag og vertebrate, sama sa isda, langgam, ug mammal."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks 5A (diversity of life)", "generator": "claude-workflow", "reviewed": false},
  {"id": "reptiles-brumation-g7", "domain": "LIVING_THINGS", "topic": "reptiles slow down when cold", "grades": [6, 7, 8], "terms": ["reptilya", "reptile", "lamig", "cold", "tamlay", "inactive", "energy", "nagtatago", "panahon ng lamig", "nagpapahinga", "bugnaw nga panahon", "tapulan", "motago", "mohinay"], "fact": {"tl": "Dahil malamig ang dugo ng mga reptilya, kapag napakalamig ng panahon ay bumabagal ang kanilang katawan at nagiging tamlay sila; kakaunti ang kinakain nila at nagtatago hanggang muling uminit.", "en": "Because reptiles are cold-blooded, when the weather turns very cold their bodies slow down and they become sluggish; they eat little and hide until it warms up again.", "bis": "Tungod kay bugnaw ang dugo sa mga reptilya, kung bugnaw kaayo ang panahon mohinay ang ilang lawas ug mahimo silang tapulan; gamay ra silang mokaon ug motago hangtod nga moinit pag-usab."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-feathers-g3", "domain": "LIVING_THINGS", "topic": "birds have feathers", "grades": [3, 4], "terms": ["ibon", "balahibo", "pakpak", "langgam", "balhibo", "feathers", "birds", "wings"], "fact": {"tl": "Ang mga ibon ang tanging hayop na may balahibong tinatawag na feathers, na nagpapainit sa kanila at tumutulong sa kanilang lumipad.", "en": "Birds are the only animals that have feathers, which keep them warm and help them fly.", "bis": "Ang mga langgam mao ra ang mga mananap nga adunay balhibo nga gitawag og feathers, nga nagpainit kanila ug nagtabang sa ilang paglupad."}, "source": "AAAS Benchmarks 5C (structure-function); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-hollow-bones-g5", "domain": "LIVING_THINGS", "topic": "birds have light hollow bones", "grades": [5, 6], "terms": ["buto ng ibon", "magaan na buto", "hungkag", "bukog sa langgam", "gaan", "hollow bones", "lightweight", "fly"], "fact": {"tl": "Maraming buto ng ibon ay hungkag at magaan, kaya mas madali silang lumipad.", "en": "Many of a bird's bones are hollow and light, which makes it easier for them to fly.", "bis": "Daghan sa mga bukog sa langgam ang hungkag ug gaan, mao nga sayon ra silang molupad."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-wing-shape-lift-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "how bird wings make lift", "grades": [6, 7], "terms": ["pakpak", "paglipad", "lift", "hangin", "pako", "paglupad", "wing shape", "air", "flight"], "fact": {"tl": "Ang hubog na hugis ng pakpak ng ibon ay nagtutulak ng hangin pababa, at ito ay lumilikha ng lakas na nagtataas sa ibon sa himpapawid.", "en": "The curved shape of a bird's wing pushes air downward, creating lift that holds the bird up in the air.", "bis": "Ang kurbada nga porma sa pako sa langgam nagatukmod sa hangin paubos, nga naghatag og kusog nga nagpataas sa langgam sa kahanginan."}, "source": "FORCE_MOTION_ENERGY; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-flapping-flight-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "birds flap wings to fly", "grades": [4, 5], "terms": ["pagaspas", "pumagaspas ng pakpak", "paglipad", "kapay-kapay", "paglupad", "flap", "flapping wings", "fly"], "fact": {"tl": "Pinagpapagaspas ng mga ibon ang kanilang mga pakpak upang itulak ang sarili paitaas at pasulong sa hangin.", "en": "Birds flap their wings to push themselves up and forward through the air.", "bis": "Ginakapay-kapay sa mga langgam ang ilang mga pako aron itukmod ang ilang kaugalingon paitaas ug pasulong sa hangin."}, "source": "FORCE_MOTION_ENERGY; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-gliding-soaring-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "birds glide and soar on air", "grades": [6, 7], "terms": ["paglipad ng walang pagaspas", "gliding", "soaring", "init na hangin", "thermal", "paglupad nga walay kapay", "glide", "air current"], "fact": {"tl": "Ang ilang malalaking ibon tulad ng agila ay nakakalipad nang hindi pumapagaspas sa pamamagitan ng pagsakay sa umaakyat na mainit na hangin.", "en": "Some large birds like eagles can fly without flapping by riding on rising warm air called thermals.", "bis": "Ang ubang dagkong langgam sama sa agila makalupad nga dili magkapay pinaagi sa pagsakay sa nagasaka nga init nga hangin nga gitawag og thermals."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-beak-shape-food-g4", "domain": "LIVING_THINGS", "topic": "beak shape matches food", "grades": [4, 5], "terms": ["tuka", "tuka ng ibon", "pagkain", "sungo", "sungo sa langgam", "beak", "bill", "food", "shape"], "fact": {"tl": "Ang hugis ng tuka ng ibon ay bumabagay sa uri ng pagkaing kinakain nito.", "en": "The shape of a bird's beak matches the kind of food it eats.", "bis": "Ang porma sa sungo sa langgam mohaom sa matang sa pagkaon nga gikaon niini."}, "source": "AAAS Benchmarks 5C (structure-function); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-hooked-beak-raptor-g5", "domain": "LIVING_THINGS", "topic": "sharp hooked beaks of birds of prey", "grades": [5, 6], "terms": ["matulis na tuka", "agila", "mandaragit", "matalim na sungo", "manunukob nga langgam", "hooked beak", "eagle", "prey", "tear meat"], "fact": {"tl": "Ang mga ibong mandaragit tulad ng agila ay may matalim at nakabaluktot na tuka na ginagamit sa pagpunit ng laman.", "en": "Birds of prey like eagles have sharp, hooked beaks used to tear meat.", "bis": "Ang mga langgam nga manunukob sama sa agila adunay hait ug baliko nga sungo nga gamiton sa paggisi sa unod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-feet-perching-g4", "domain": "LIVING_THINGS", "topic": "bird feet for perching", "grades": [4, 5], "terms": ["paa ng ibon", "sanga", "pagkapit", "tiil sa langgam", "kuko", "perch", "feet", "claws", "grip branch"], "fact": {"tl": "Maraming ibon ay may mga paang nakakakapit nang mahigpit sa sanga kahit habang natutulog.", "en": "Many birds have feet that can grip tightly onto a branch, even while they sleep.", "bis": "Daghang langgam ang adunay mga tiil nga makahawid og hugot sa sanga bisan samtang sila natulog."}, "source": "AAAS Benchmarks 5C (structure-function); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-webbed-feet-g4", "domain": "LIVING_THINGS", "topic": "webbed feet for swimming", "grades": [4, 5], "terms": ["paang lapad", "pato", "lumalangoy", "tiil nga adunay lapyahan", "itik", "webbed feet", "duck", "swim", "paddle"], "fact": {"tl": "Ang mga ibong tubig tulad ng pato ay may mga paang may lambat sa pagitan ng mga daliri upang makasagwan sa tubig.", "en": "Water birds like ducks have webbed feet that help them paddle through water.", "bis": "Ang mga langgam sa tubig sama sa itik adunay mga tiil nga may lapyahan tali sa mga tudlo aron makagaud sila sa tubig."}, "source": "AAAS Benchmarks 5C (structure-function); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-talons-g5", "domain": "LIVING_THINGS", "topic": "talons for catching prey", "grades": [5, 6], "terms": ["kuko", "matatalim na kuko", "talon", "agila", "kuko sa agila", "talons", "claws", "grab prey"], "fact": {"tl": "Ang mga ibong mandaragit ay may matatalim na kuko na tinatawag na talons na panghuli ng biktima.", "en": "Birds of prey have sharp claws called talons for catching their prey.", "bis": "Ang mga langgam nga manunukob adunay hait nga mga kuko nga gitawag og talons aron makakuha sa ilang biktima."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-eggs-g3", "domain": "LIVING_THINGS", "topic": "birds lay eggs", "grades": [3, 4], "terms": ["itlog", "nangingitlog", "pugad", "itlog sa langgam", "nangitlog", "eggs", "lay eggs", "hatch"], "fact": {"tl": "Lahat ng ibon ay nangingitlog, at karamihan ay umuupo sa mga itlog upang painitin ang mga ito hanggang mapisa.", "en": "All birds lay eggs, and most sit on them to keep them warm until they hatch.", "bis": "Tanang langgam mangitlog, ug kadaghanan molingkod sa mga itlog aron painiton kini hangtod mapusa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-nests-g3", "domain": "LIVING_THINGS", "topic": "birds build nests", "grades": [3, 4], "terms": ["pugad", "gumagawa ng pugad", "sanga at dahon", "salag", "naghimo og salag", "nest", "build nest", "twigs"], "fact": {"tl": "Maraming ibon ay gumagawa ng pugad mula sa mga sanga, dahon, at damo upang ligtas na mailagay ang kanilang mga itlog.", "en": "Many birds build nests out of twigs, leaves, and grass to hold their eggs safely.", "bis": "Daghang langgam ang naghimo og salag gikan sa mga sanga, dahon, ug sagbot aron luwas nga mabutang ang ilang mga itlog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-feeding-chicks-g4", "domain": "LIVING_THINGS", "topic": "parent birds feed chicks", "grades": [4, 5], "terms": ["sisiw", "pinapakain", "magulang na ibon", "piso", "gipakaon", "chick", "feed young", "parent bird"], "fact": {"tl": "Pinapakain ng magulang na ibon ang kanilang mga sisiw hanggang ito ay sapat nang lakas upang lumipad palabas ng pugad.", "en": "Parent birds feed their chicks until the young are strong enough to fly out of the nest.", "bis": "Ginapakaon sa mga ginikanang langgam ang ilang mga piso hangtod kusganon na kini aron makalupad pagawas sa salag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-migration-g5", "domain": "LIVING_THINGS", "topic": "why birds migrate", "grades": [5, 6], "terms": ["paglipat", "migration", "panahon", "taglamig", "lumilipat ng pugad", "paglalakbay", "pagbalhin", "migrate", "season", "warm", "travel"], "fact": {"tl": "Ang ilang ibon ay naglalakbay nang napakalayo tuwing magbabago ang panahon upang maghanap ng pagkain at mas mainit na lugar; tinatawag itong migration.", "en": "Some birds travel very long distances when the seasons change to find food and warmer places; this is called migration.", "bis": "Ang ubang langgam mobiyahe og layo kaayo kon mausab ang panahon aron mangita og pagkaon ug mas init nga dapit; gitawag kini og migration."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-migration-navigation-g7", "domain": "LIVING_THINGS", "topic": "how migrating birds find their way", "grades": [7, 8], "terms": ["paglipat", "direksyon", "araw at bituin", "migration", "pagtultol sa dalan", "navigation", "sun", "stars", "magnetic", "find way"], "fact": {"tl": "Ang mga lumilipat na ibon ay nakahahanap ng daan gamit ang araw, mga bituin, at ang magnetikong larangan ng Mundo bilang gabay.", "en": "Migrating birds find their way using the sun, the stars, and Earth's magnetic field as guides.", "bis": "Ang mga nagbalhin nga langgam makakaplag sa ilang dalan gamit ang adlaw, ang mga bituon, ug ang magnetikong natad sa Yuta isip giya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-philippine-migratory-g5", "domain": "LIVING_THINGS", "topic": "migratory birds visit the Philippines", "grades": [5, 6], "terms": ["ibong dayo", "Pilipinas", "migratory bird", "langyaw nga langgam", "bisita", "Philippines", "wetland", "visit"], "fact": {"tl": "Tuwing taglamig sa hilaga, maraming ibong dayo ang lumilipad papuntang Pilipinas upang manirahan sa mga latian at baybayin.", "en": "During the northern winter, many migratory birds fly to the Philippines to stay in its wetlands and coasts.", "bis": "Panahon sa tingtugnaw sa amihanan, daghang langyaw nga langgam ang molupad ngadto sa Pilipinas aron mopuyo sa mga lamakan ug baybayon niini."}, "source": "encyclopedia-stable consensus; PH-relevant", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-flightless-g4", "domain": "LIVING_THINGS", "topic": "some birds cannot fly", "grades": [4, 5], "terms": ["ibong hindi lumilipad", "ostrich", "flightless", "langgam nga dili makalupad", "emu", "cannot fly", "run", "ground bird"], "fact": {"tl": "Hindi lahat ng ibon ay nakakalipad; ang ilan tulad ng ostrich ay tumatakbo sa lupa sa halip na lumipad.", "en": "Not all birds can fly; some, like the ostrich, run on the ground instead of flying.", "bis": "Dili tanang langgam makalupad; ang uban sama sa ostrich modagan sa yuta imbes nga molupad."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-ostrich-fastest-runner-g5", "domain": "LIVING_THINGS", "topic": "ostrich is the largest and fastest-running bird", "grades": [5, 6], "terms": ["ostrich", "pinakamalaki", "mabilis tumakbo", "abestrus", "largest bird", "fast runner", "long legs"], "fact": {"tl": "Ang ostrich ang pinakamalaking ibon sa mundo at nakakatakbo nang napakabilis gamit ang mahahaba at malalakas nitong binti.", "en": "The ostrich is the largest bird in the world and can run very fast using its long, strong legs.", "bis": "Ang ostrich mao ang pinakadako nga langgam sa kalibotan ug makadagan og paspas kaayo gamit ang taas ug kusgan niini nga mga paa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-penguin-swim-g4", "domain": "LIVING_THINGS", "topic": "penguins swim instead of fly", "grades": [4, 5], "terms": ["penguin", "pingwino", "lumalangoy", "pinguino", "molangoy", "swim", "flippers", "wings"], "fact": {"tl": "Ang mga penguin ay ibong hindi nakakalipad, ngunit ginagamit nila ang kanilang mga pakpak na parang sagwan upang lumangoy sa ilalim ng tubig.", "en": "Penguins are birds that cannot fly, but they use their wings like paddles to swim underwater.", "bis": "Ang mga penguin mga langgam nga dili makalupad, apan gamiton nila ang ilang mga pako sama sa bugsay aron molangoy ilalom sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-penguin-cold-g5", "domain": "LIVING_THINGS", "topic": "penguins stay warm in the cold", "grades": [5, 6], "terms": ["penguin", "lamig", "taba", "Antarctica", "pingwino", "init", "tugnaw", "cold", "blubber", "huddle"], "fact": {"tl": "Ang mga penguin ay nakatira sa napakalamig na lugar at nananatiling mainit dahil sa makapal nilang balahibo at taba sa ilalim ng balat.", "en": "Penguins live in very cold places and stay warm thanks to their thick feathers and a layer of fat under their skin.", "bis": "Ang mga penguin nagpuyo sa bugnaw kaayo nga mga dapit ug magpabiling init tungod sa ilang baga nga balhibo ug tambok ilalom sa panit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-owl-night-g4", "domain": "LIVING_THINGS", "topic": "owls hunt at night", "grades": [4, 5], "terms": ["kuwago", "gabi", "nanghuhuli sa gabi", "bukaw", "ngitngit", "owl", "night", "nocturnal", "hunt", "big eyes"], "fact": {"tl": "Ang mga kuwago ay nanghuhuli sa gabi at may malalaking mata na nakakakita sa madilim.", "en": "Owls hunt at night and have large eyes that can see in the dark.", "bis": "Ang mga bukaw mangayam sa gabii ug adunay dagkong mata nga makakita sa kangitngit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-owl-silent-flight-g6", "domain": "LIVING_THINGS", "topic": "owls fly silently", "grades": [6, 7], "terms": ["kuwago", "tahimik na paglipad", "balahibo", "bukaw", "hilom nga paglupad", "owl", "silent flight", "soft feathers", "sneak"], "fact": {"tl": "Ang malalambot na balahibo ng kuwago ay nagpapatahimik sa paglipad nito, kaya hindi ito naririnig ng biktima nito.", "en": "An owl's soft feathers make its flight nearly silent, so its prey cannot hear it coming.", "bis": "Ang humok nga mga balhibo sa bukaw maghimo sa paglupad niini nga halos hilom, mao nga dili kini madungog sa biktima niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-owl-head-turn-g5", "domain": "LIVING_THINGS", "topic": "owls turn their heads far around", "grades": [5, 6], "terms": ["kuwago", "umiikot ang ulo", "leeg", "bukaw", "liko sa ulo", "owl", "turn head", "neck", "look behind"], "fact": {"tl": "Hindi maigalaw ng kuwago ang mga mata nito, kaya iniikot nito ang ulo nang malayo upang makatingin sa gilid at likuran.", "en": "An owl cannot move its eyes, so it turns its head far around to look to the sides and behind it.", "bis": "Dili matarog sa bukaw ang mga mata niini, mao nga ilingiw niini ang ulo og layo aron makatan-aw sa kilid ug likod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-hummingbird-hover-g6", "domain": "LIVING_THINGS", "topic": "hummingbirds hover in place", "grades": [6, 7], "terms": ["hummingbird", "lumulutang sa hangin", "mabilis na pakpak", "nektar", "hovering", "fast wings", "nectar", "hover"], "fact": {"tl": "Pinapagaspas ng hummingbird ang mga pakpak nito nang napakabilis kaya nakakalutang ito sa isang lugar habang sumisipsip ng nektar mula sa bulaklak.", "en": "A hummingbird flaps its wings so fast that it can hover in one place while sipping nectar from flowers.", "bis": "Ginakapay-kapay sa hummingbird ang mga pako niini og paspas kaayo mao nga makalutaw kini sa usa ka lugar samtang nagasuyop og nektar gikan sa bulak."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-eagle-eyesight-g5", "domain": "LIVING_THINGS", "topic": "eagles have very sharp eyesight", "grades": [5, 6], "terms": ["agila", "matalas na mata", "paningin", "matalim nga panan-aw", "eagle", "sharp eyesight", "vision", "spot prey"], "fact": {"tl": "Ang mga agila ay may napakatalas na paningin at nakikita nila ang maliliit na hayop mula sa napakataas at malayong himpapawid.", "en": "Eagles have extremely sharp eyesight and can spot small animals from very high and far away.", "bis": "Ang mga agila adunay hait kaayo nga panan-aw ug makakita sila og gagmayng mananap gikan sa taas ug layo kaayo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-philippine-eagle-g6", "domain": "LIVING_THINGS", "topic": "the Philippine Eagle", "grades": [6, 7], "terms": ["Philippine Eagle", "agila", "pambansang ibon", "haribon", "agila sa Pilipinas", "endangered", "national bird", "Mindanao", "forest"], "fact": {"tl": "Ang Philippine Eagle ay isa sa pinakamalalaki at pinakamalakas na agila sa mundo, at ito ang pambansang ibon ng Pilipinas.", "en": "The Philippine Eagle is one of the largest and strongest eagles in the world, and it is the national bird of the Philippines.", "bis": "Ang Philippine Eagle usa sa pinakadako ug pinakakusgan nga mga agila sa kalibotan, ug kini ang nasodnong langgam sa Pilipinas."}, "source": "encyclopedia-stable consensus; PH-relevant", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-from-dinosaurs-g6", "domain": "LIVING_THINGS", "topic": "birds descended from dinosaurs", "grades": [6, 7], "terms": ["ibon", "dinosaur", "ninuno", "nag-evolve", "gigikanan", "langgam gikan sa dinosaur", "birds", "dinosaurs", "ancestors", "evolved"], "fact": {"tl": "Naniniwala ang mga siyentista na ang mga ibon ngayon ay nagmula sa maliliit na dinosaur milyon-milyong taon na ang nakalipas.", "en": "Scientists believe that today's birds evolved from small dinosaurs millions of years ago.", "bis": "Nagtuo ang mga siyentista nga ang mga langgam karon naggikan sa gagmayng dinosaur minilyon ka tuig na ang milabay."}, "source": "AAAS Benchmarks 5F (evolution); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-songs-communication-g4", "domain": "LIVING_THINGS", "topic": "birds sing to communicate", "grades": [4, 5], "terms": ["awit ng ibon", "huni", "tumatawag", "kanta sa langgam", "huni sa langgam", "bird song", "chirp", "call", "communicate", "territory"], "fact": {"tl": "Ang mga ibon ay umaawit at humuhuni upang tumawag sa kapareha o magbabala sa ibang ibon na umalis sa kanilang lugar.", "en": "Birds sing and chirp to call a mate or to warn other birds to stay out of their area.", "bis": "Ang mga langgam moawit ug mohuni aron motawag sa kapares o mopasidaan sa ubang langgam nga mopahilayo sa ilang dapit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-beak-not-teeth-g4", "domain": "LIVING_THINGS", "topic": "birds have beaks not teeth", "grades": [4, 5], "terms": ["tuka", "walang ngipin", "lumulunok", "sungo", "walay ngipon", "beak", "no teeth", "swallow", "bill"], "fact": {"tl": "Ang mga ibon ay walang ngipin; gumagamit sila ng tuka upang humuli at lumunok ng pagkain nang buo.", "en": "Birds have no teeth; they use their beaks to grab and swallow food whole.", "bis": "Ang mga langgam walay ngipon; mogamit sila og sungo aron mokuha ug motulon sa pagkaon nga tibuok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "trex-meat-eater-g4", "domain": "LIVING_THINGS", "topic": "Tyrannosaurus rex carnivore", "grades": [3, 4, 5], "terms": ["T. rex", "Tyrannosaurus", "rex", "tirano", "karnibor", "carnivore", "meat-eater", "kumakain", "karne", "unod", "mokaon", "ngipin", "tooth", "teeth", "mananakop", "predator", "dako", "malaki"], "fact": {"tl": "Ang Tyrannosaurus rex (o T. rex) ay isang malaking dinosaur na karnibor — kumakain ito ng karne ng ibang hayop gamit ang malalaki at matatalas nitong ngipin.", "en": "Tyrannosaurus rex (or T. rex) was a large carnivorous dinosaur — it ate the meat of other animals using its big, sharp teeth.", "bis": "Ang Tyrannosaurus rex (o T. rex) usa ka dakong dinosaur nga karnibor — mokaon kini sa unod sa ubang hayop gamit ang dako ug hait nga mga ngipin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "trex-tiny-arms-g4", "domain": "LIVING_THINGS", "topic": "T. rex small arms and strong jaws", "grades": [3, 4, 5, 6], "terms": ["T. rex", "Tyrannosaurus", "braso", "arms", "maliit", "gamay", "short", "panga", "jaws", "apapangig", "bite", "kagat", "paak", "malakas", "kusgan", "lakas"], "fact": {"tl": "Ang T. rex ay may napakaliliit na braso ngunit napakalakas na panga at kagat — kaya nitong durugin ang buto ng kanyang biktima.", "en": "T. rex had very small arms but extremely powerful jaws and bite — it could crush the bones of its prey.", "bis": "Ang T. rex adunay gagmay kaayong mga bukton apan kusgan kaayong apapangig ug paak — madugmok niini ang bukog sa iyang biktima."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "trex-size-g5", "domain": "LIVING_THINGS", "topic": "how big T. rex was", "grades": [4, 5, 6], "terms": ["T. rex", "Tyrannosaurus", "laki", "gidak-on", "haba", "length", "habaan", "12 metro", "metro", "meters", "taas", "tall", "malaki", "dako", "bus"], "fact": {"tl": "Ang T. rex ay umaabot ng mga 12 metro ang haba — mas mahaba pa sa isang malaking bus — at lumalakad ito nang nakatayo sa dalawang malalakas na binti.", "en": "T. rex grew to about 12 meters long — longer than a large bus — and walked upright on two strong legs.", "bis": "Ang T. rex moabot og mga 12 ka metro ang gitas-on — mas taas pa sa usa ka dakong bus — ug naglakaw kini nga nagbarog sa duha ka kusgan nga bitiis."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "triceratops-horns-g4", "domain": "LIVING_THINGS", "topic": "Triceratops three horns and frill", "grades": [3, 4, 5], "terms": ["Triceratops", "sungay", "horns", "tatlong", "tulo", "three", "frill", "kalmot", "mukha", "nawong", "face", "depensa", "defense", "proteksyon", "taming", "kalasag"], "fact": {"tl": "Ang Triceratops ay may tatlong sungay sa mukha at isang malawak na kalasag na buto sa likod ng ulo na maaaring ginamit nito para sa proteksyon.", "en": "Triceratops had three horns on its face and a wide bony frill at the back of its head that may have been used for protection.", "bis": "Ang Triceratops adunay tulo ka sungay sa nawong ug usa ka lapad nga bukog nga taming sa likod sa ulo nga tingali gigamit niini alang sa panalipod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "triceratops-herbivore-g4", "domain": "LIVING_THINGS", "topic": "Triceratops plant-eater", "grades": [3, 4, 5], "terms": ["Triceratops", "herbivore", "halaman", "tanom", "plant-eater", "kumakain", "mokaon", "dahon", "leaves", "tanim", "tuka", "beak", "sungo", "buto"], "fact": {"tl": "Ang Triceratops ay isang herbivore — kumakain lamang ito ng mga halaman, at may tukang parang ibon para putulin ang matitigas na tanim.", "en": "Triceratops was a herbivore — it ate only plants, and had a bird-like beak to snip off tough vegetation.", "bis": "Ang Triceratops usa ka herbivore — mokaon lamang kini og mga tanom, ug adunay sungo nga sama sa langgam aron putlon ang gahi nga mga tanom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "stegosaurus-plates-g4", "domain": "LIVING_THINGS", "topic": "Stegosaurus back plates", "grades": [3, 4, 5], "terms": ["Stegosaurus", "plato", "plates", "plaka", "likod", "back", "buto", "bones", "tindig", "nakatayo", "hilera", "row", "init", "temperature", "kainit"], "fact": {"tl": "Ang Stegosaurus ay may hanay ng malalaki at parang plato na buto na nakatayo sa kanyang likod, na maaaring tumulong para sa init ng katawan o pagpapakita.", "en": "Stegosaurus had a row of large, plate-like bones standing up along its back, which may have helped with body heat or display.", "bis": "Ang Stegosaurus adunay laray sa dagko, sama sa plato nga mga bukog nga nagbarog sa iyang likod, nga tingali nakatabang sa kainit sa lawas o pagpakita."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "stegosaurus-tail-spikes-g4", "domain": "LIVING_THINGS", "topic": "Stegosaurus tail spikes", "grades": [3, 4, 5, 6], "terms": ["Stegosaurus", "buntot", "ikog", "tail", "tinik", "spikes", "tunok", "depensa", "defense", "panalipod", "herbivore", "halaman", "tanom", "manunukob", "mandaragit"], "fact": {"tl": "Ang Stegosaurus ay isang herbivore na may apat na matatalas na tinik sa dulo ng buntot na ginamit nito para ipagtanggol ang sarili sa mga mandaragit.", "en": "Stegosaurus was a herbivore with four sharp spikes at the end of its tail that it used to defend itself against predators.", "bis": "Ang Stegosaurus usa ka herbivore nga adunay upat ka hait nga tunok sa tumoy sa ikog nga gigamit niini aron panalipdan ang kaugalingon batok sa mga manunukob."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "velociraptor-small-fast-g4", "domain": "LIVING_THINGS", "topic": "Velociraptor size and speed", "grades": [3, 4, 5], "terms": ["Velociraptor", "raptor", "maliit", "gamay", "small", "mabilis", "paspas", "fast", "swift", "takbo", "dagan", "karnibor", "carnivore", "pabo", "turkey"], "fact": {"tl": "Ang Velociraptor ay isang maliit at mabilis na karnibor — mga kasinlaki lang ito ng isang pabo (turkey), hindi kasinlaki ng pinapakita sa mga pelikula.", "en": "Velociraptor was a small, fast carnivore — about the size of a turkey, not as big as movies show it.", "bis": "Ang Velociraptor usa ka gamay ug paspas nga karnibor — mga kasing-dako lang sa usa ka pabo (turkey), dili sama kadako sa gipakita sa mga sine."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "velociraptor-claw-feathers-g5", "domain": "LIVING_THINGS", "topic": "Velociraptor claw and feathers", "grades": [4, 5, 6], "terms": ["Velociraptor", "raptor", "kuko", "claw", "kudkod", "garab", "hook", "paa", "feet", "balahibo", "feathers", "balhibo", "ibon", "bird", "langgam", "hunt", "mangaso", "mangayam"], "fact": {"tl": "Ang Velociraptor ay may malaking hugis-karit na kuko sa bawat paa para manghuli, at may mga balahibo (feathers) na parang sa mga ibon.", "en": "Velociraptor had a large sickle-shaped claw on each foot for hunting, and it had feathers like those of birds.", "bis": "Ang Velociraptor adunay dako nga sama sa garab nga kuko sa matag tiil aron mangayam, ug adunay balhibo nga sama sa mga langgam."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "brachiosaurus-long-neck-g4", "domain": "LIVING_THINGS", "topic": "Brachiosaurus long neck", "grades": [3, 4, 5], "terms": ["Brachiosaurus", "leeg", "neck", "liog", "mahaba", "taas", "long", "matangkad", "tall", "puno", "tree", "kahoy", "dahon", "leaves", "herbivore", "halaman"], "fact": {"tl": "Ang Brachiosaurus ay isang napakalaking herbivore na may napakahabang leeg na ginamit nito para abutin ang mga dahon sa matataas na puno.", "en": "Brachiosaurus was a huge herbivore with a very long neck that it used to reach leaves high up in the trees.", "bis": "Ang Brachiosaurus usa ka dako kaayong herbivore nga adunay taas kaayong liog nga gigamit niini aron makab-ot ang mga dahon sa habog nga mga kahoy."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "brachiosaurus-giant-size-g5", "domain": "LIVING_THINGS", "topic": "Brachiosaurus enormous size", "grades": [4, 5, 6], "terms": ["Brachiosaurus", "sauropod", "laki", "gidak-on", "dako", "malaki", "giant", "bigat", "gibug-aton", "weight", "tonelada", "tons", "mabigat", "gusali", "building"], "fact": {"tl": "Ang Brachiosaurus ay isa sa pinakamalalaking hayop na nabuhay sa lupa — mas mataas pa ito kaysa sa isang gusaling apat na palapag at tumitimbang ng maraming tonelada.", "en": "Brachiosaurus was one of the largest land animals ever — taller than a four-story building and weighing many tons.", "bis": "Ang Brachiosaurus usa sa pinakadakong hayop nga nabuhi sa yuta — mas taas pa kini kaysa upat ka andana nga building ug nagtimbang og daghang tonelada."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "herbivore-vs-carnivore-dino-g4", "domain": "LIVING_THINGS", "topic": "herbivore vs carnivore dinosaurs", "grades": [3, 4, 5], "terms": ["dinosaur", "herbivore", "carnivore", "halaman", "tanom", "karne", "unod", "kumakain", "mokaon", "plant-eater", "meat-eater", "ngipin", "tooth", "uri", "klase", "matang"], "fact": {"tl": "May dalawang pangunahing uri ng dinosaur: ang mga herbivore na kumakain ng halaman, at ang mga carnivore na kumakain ng karne ng ibang hayop.", "en": "There were two main kinds of dinosaurs: herbivores that ate plants, and carnivores that ate the meat of other animals.", "bis": "Adunay duha ka panguna nga matang sa dinosaur: ang mga herbivore nga mokaon og tanom, ug ang mga carnivore nga mokaon sa unod sa ubang hayop."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dino-teeth-tell-diet-g5", "domain": "LIVING_THINGS", "topic": "dinosaur teeth show diet", "grades": [4, 5, 6], "terms": ["dinosaur", "ngipin", "tooth", "teeth", "ngipon", "diet", "pagkain", "kaon", "matalas", "hait", "sharp", "flat", "patag", "halaman", "karne", "siyentista", "alamin"], "fact": {"tl": "Sa pamamagitan ng pagtingin sa ngipin ng dinosaur, malalaman ng mga siyentista kung ano ang kinakain nito — matatalas na ngipin para sa karne, at patag na ngipin para sa halaman.", "en": "By looking at a dinosaur's teeth, scientists can tell what it ate — sharp teeth for meat, and flat teeth for grinding plants.", "bis": "Pinaagi sa pagtan-aw sa ngipon sa dinosaur, mahibaloan sa mga siyentista kung unsa ang gikaon niini — hait nga ngipon alang sa unod, ug patag nga ngipon alang sa paggaling og tanom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "carnivore-dino-walk-two-legs-g5", "domain": "LIVING_THINGS", "topic": "carnivorous dinosaurs walked on two legs", "grades": [4, 5, 6], "terms": ["dinosaur", "carnivore", "karnibor", "binti", "bitiis", "legs", "dalawa", "duha", "two", "lakad", "lakaw", "walk", "theropod", "mabilis", "paspas", "tayo", "barog"], "fact": {"tl": "Karamihan sa mga karnibor na dinosaur, tulad ng T. rex at Velociraptor, ay lumalakad gamit ang dalawang binti, kaya nakakatakbo sila nang mabilis para manghuli.", "en": "Most meat-eating dinosaurs, like T. rex and Velociraptor, walked on two legs, which let them run fast to hunt.", "bis": "Kadaghanan sa mga karnibor nga dinosaur, sama sa T. rex ug Velociraptor, naglakaw gamit ang duha ka bitiis, busa makadagan sila og paspas aron mangayam."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fossils-how-form-g6", "domain": "EARTH_SPACE", "topic": "how dinosaur fossils form", "grades": [5, 6, 7], "terms": ["fossil", "dinosaur", "buto", "bones", "bukog", "bato", "rock", "mineral", "nilibing", "gilubong", "buried", "putik", "lapok", "mud", "lupa", "milyong", "taon", "napreserba"], "fact": {"tl": "Nabubuo ang fossil ng dinosaur kapag ang patay nitong katawan ay mabilis na nalibing sa putik o buhangin, at sa paglipas ng milyong taon, dahan-dahang nagiging bato ang mga buto.", "en": "A dinosaur fossil forms when its dead body is quickly buried in mud or sand, and over millions of years the bones slowly turn to stone.", "bis": "Ang fossil sa dinosaur maporma kung ang patay niini nga lawas dali nga malubong sa lapok o balas, ug sa paglabay sa milyon ka tuig, hinay-hinay nga mahimong bato ang mga bukog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fossils-how-we-know-dino-g6", "domain": "LIVING_THINGS", "topic": "how we know about dinosaurs from fossils", "grades": [5, 6, 7], "terms": ["dinosaur", "fossil", "buto", "bones", "kalansay", "skeleton", "siyentista", "paleontologist", "natutunan", "nahibaloan", "alam", "hukay", "kalot", "dig", "mukubkob"], "fact": {"tl": "Walang nakakita ng buhay na dinosaur, kaya nalalaman natin ang tungkol sa kanila sa pamamagitan ng pag-aaral ng kanilang mga fossil — mga buto, ngipin, at bakas na natagpuan sa bato.", "en": "No one ever saw a living dinosaur, so we learn about them by studying their fossils — bones, teeth, and tracks found in rock.", "bis": "Walay nakakita og buhi nga dinosaur, busa nahibaloan nato ang bahin kanila pinaagi sa pagtuon sa ilang mga fossil — mga bukog, ngipon, ug agi nga nakit-an sa bato."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "paleontologist-job-g6", "domain": "LIVING_THINGS", "topic": "paleontologists study fossils", "grades": [5, 6, 7], "terms": ["paleontologist", "paleontologo", "siyentista", "scientist", "fossil", "dinosaur", "hukay", "kalot", "kubkob", "pag-aaral", "study", "tuon", "buto", "bones"], "fact": {"tl": "Ang paleontologist ay isang siyentista na nag-aaral ng mga fossil para alamin kung paano nabuhay ang mga dinosaur at iba pang hayop noong unang panahon.", "en": "A paleontologist is a scientist who studies fossils to learn how dinosaurs and other ancient animals lived.", "bis": "Ang paleontologist usa ka siyentista nga nagtuon sa mga fossil aron mahibaloan kung giunsa pagkabuhi sa mga dinosaur ug uban pang karaang hayop."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dino-fossils-found-everywhere-g6", "domain": "EARTH_SPACE", "topic": "dinosaur fossils found on every continent", "grades": [5, 6, 7], "terms": ["dinosaur", "fossil", "kontinente", "continent", "mundo", "kalibutan", "buong", "tibuok", "natagpuan", "nakit-an", "nakita", "everywhere", "Antarctica", "bahin sa kalibutan"], "fact": {"tl": "Natagpuan na ang mga fossil ng dinosaur sa bawat kontinente sa mundo, kahit sa malamig na Antarctica — ibig sabihin, kumalat ang mga dinosaur sa buong daigdig.", "en": "Dinosaur fossils have been found on every continent on Earth, even in cold Antarctica — meaning dinosaurs spread across the whole world.", "bis": "Ang mga fossil sa dinosaur nakit-an na sa matag kontinente sa kalibutan, bisan sa bugnaw nga Antarctica — buot ipasabot, mikaylap ang mga dinosaur sa tibuok kalibutan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dino-eggs-nests-g5", "domain": "LIVING_THINGS", "topic": "dinosaurs laid eggs", "grades": [3, 4, 5, 6], "terms": ["dinosaur", "itlog", "egg", "eggs", "pugad", "nest", "salag", "nangitlog", "nangamod", "lay", "anak", "baby", "reptile", "reptilya", "ibon", "langgam"], "fact": {"tl": "Ang mga dinosaur ay nangingitlog tulad ng mga ibon at reptilya, at may natagpuan nang mga fossil ng itlog at pugad ng dinosaur.", "en": "Dinosaurs laid eggs like birds and reptiles, and scientists have found fossil dinosaur eggs and nests.", "bis": "Ang mga dinosaur nangitlog sama sa mga langgam ug reptilya, ug ang mga siyentista nakakaplag og fossil nga mga itlog ug salag sa dinosaur."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-are-dinosaurs-g6", "domain": "LIVING_THINGS", "topic": "birds descended from dinosaurs", "grades": [5, 6, 7], "terms": ["ibon", "bird", "birds", "langgam", "dinosaur", "inapo", "descendant", "kaliwat", "feathers", "balahibo", "balhibo", "buhay", "buhi", "ngayon", "karon"], "fact": {"tl": "Ang mga ibon ngayon ay itinuturing na mga inapo ng mga maliliit na dinosaur na may balahibo — kaya masasabing hindi tuluyang naglaho ang mga dinosaur.", "en": "Today's birds are considered the descendants of small feathered dinosaurs — so in a way, dinosaurs never fully disappeared.", "bis": "Ang mga langgam karon giisip nga mga kaliwat sa gagmay nga balhiboon nga mga dinosaur — busa sa usa ka paagi, wala gyud nahanaw ang mga dinosaur."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dino-extinction-asteroid-g6", "domain": "EARTH_SPACE", "topic": "asteroid impact and dinosaur extinction", "grades": [5, 6, 7], "terms": ["dinosaur", "extinct", "naglaho", "nahanaw", "nawala", "asteroid", "bumangga", "naigo", "impact", "alikabok", "abog", "dust", "araw", "adlaw", "lamig", "klima"], "fact": {"tl": "Mga 66 milyong taon na ang nakalipas, isang higanteng asteroid ang bumangga sa Earth at nagpadami ng alikabok sa hangin, na humarang sa araw at nagpalamig sa klima — kaya naglaho ang halos lahat ng dinosaur.", "en": "About 66 million years ago a giant asteroid struck Earth and threw dust into the air, blocking the sun and cooling the climate — which is why nearly all dinosaurs died out.", "bis": "Mga 66 ka milyon ka tuig kanhi, usa ka higante nga asteroid ang nahagba sa Yuta ug nagpadaghan og abog sa hangin, nga nagbabag sa adlaw ug nagpabugnaw sa klima — mao nga nahanaw ang halos tanang dinosaur."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dino-not-with-humans-g4", "domain": "LIVING_THINGS", "topic": "dinosaurs and humans never lived together", "grades": [3, 4, 5, 6], "terms": ["dinosaur", "tao", "human", "humans", "tawo", "sabay", "dungan", "together", "buhay", "buhi", "milyong taon", "bago", "una", "kanhi", "extinct"], "fact": {"tl": "Hindi kailanman nagkasabay ang mga tao at ang mga dinosaur — naglaho na ang mga dinosaur mga 66 milyong taon na ang nakalipas, matagal bago lumitaw ang unang tao.", "en": "Humans and dinosaurs never lived at the same time — the dinosaurs died out about 66 million years ago, long before the first humans appeared.", "bis": "Wala gyud magdungan ang mga tawo ug ang mga dinosaur — nahanaw na ang mga dinosaur mga 66 ka milyon ka tuig kanhi, dugay pa sa wala pa motungha ang unang tawo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dino-names-meaning-g5", "domain": "LIVING_THINGS", "topic": "what dinosaur names mean", "grades": [4, 5, 6], "terms": ["dinosaur", "pangalan", "name", "ngalan", "kahulugan", "meaning", "kahulogan", "Greek", "Griyego", "terrible lizard", "butiki", "tiki", "Tyrannosaurus", "Triceratops"], "fact": {"tl": "Ang salitang 'dinosaur' ay galing sa Griyego na ang ibig sabihin ay 'kakila-kilabot na butiki,' at maraming pangalan ng dinosaur ang naglalarawan ng kanilang hitsura, tulad ng 'Triceratops' na ang ibig sabihin ay 'tatlong-sungay na mukha.'", "en": "The word 'dinosaur' comes from Greek meaning 'terrible lizard,' and many dinosaur names describe their looks, like 'Triceratops' meaning 'three-horned face.'", "bis": "Ang pulong nga 'dinosaur' naggikan sa Greek nga nagpasabot og 'makalilisang nga tiki,' ug daghang ngalan sa dinosaur ang naghulagway sa ilang panagway, sama sa 'Triceratops' nga nagpasabot og 'tulo ka sungay nga nawong.'"}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dino-different-times-g6", "domain": "LIVING_THINGS", "topic": "dinosaurs lived at different times", "grades": [5, 6, 7], "terms": ["dinosaur", "panahon", "time", "Stegosaurus", "T. rex", "Tyrannosaurus", "magkasabay", "dungan", "milyong taon", "sabay", "iba", "lain", "agwat"], "fact": {"tl": "Hindi lahat ng dinosaur ay nabuhay nang sabay-sabay — halimbawa, mas malapit ang panahon ng T. rex sa atin ngayon kaysa sa panahon ng Stegosaurus, na nauna ng mahigit 80 milyong taon.", "en": "Not all dinosaurs lived at the same time — for example, T. rex lived closer to us today than to the time of Stegosaurus, which came over 80 million years earlier.", "bis": "Dili tanang dinosaur nabuhi nga dungan — pananglitan, mas duol ang panahon sa T. rex kanato karon kaysa sa panahon sa Stegosaurus, nga nag-una og kapin 80 ka milyon ka tuig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "biggest-dino-sauropods-g5", "domain": "LIVING_THINGS", "topic": "the biggest dinosaurs were long-necked plant-eaters", "grades": [4, 5, 6], "terms": ["dinosaur", "pinakamalaki", "pinakadako", "biggest", "sauropod", "mahabang leeg", "taas nga liog", "long neck", "herbivore", "halaman", "Brachiosaurus", "dako", "malaki"], "fact": {"tl": "Ang pinakamalalaking dinosaur ay mga sauropod — mga herbivore na may mahabang leeg at buntot, tulad ng Brachiosaurus — at hindi mga mabangis na karnibor.", "en": "The biggest dinosaurs were sauropods — long-necked, long-tailed plant-eaters like Brachiosaurus — not fierce meat-eaters.", "bis": "Ang pinakadagkong dinosaur mao ang mga sauropod — mga herbivore nga adunay taas nga liog ug ikog, sama sa Brachiosaurus — dili mabangis nga mga karnibor."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dino-footprints-fossil-g5", "domain": "LIVING_THINGS", "topic": "fossil footprints show dinosaur behavior", "grades": [4, 5, 6, 7], "terms": ["dinosaur", "bakas", "yapak", "footprint", "tracks", "tunob", "agi", "fossil", "lakad", "lakaw", "bilis", "grupo", "pundok", "herd", "siyentista"], "fact": {"tl": "Natagpuan din ng mga siyentista ang mga fossil na yapak ng dinosaur, na nagpapakita kung gaano kabilis sila lumakad at kung ang ilan ay naglalakbay nang grupo-grupo.", "en": "Scientists have also found fossil dinosaur footprints, which show how fast they walked and that some traveled in groups.", "bis": "Ang mga siyentista nakakaplag usab og fossil nga mga tunob sa dinosaur, nga nagpakita kung unsa kapaspas sila molakaw ug nga ang uban nagpanaw nga pundok-pundok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "herbivore-dino-defense-g5", "domain": "LIVING_THINGS", "topic": "how plant-eating dinosaurs defended themselves", "grades": [4, 5, 6], "terms": ["dinosaur", "herbivore", "halaman", "tanom", "depensa", "defense", "panalipod", "proteksyon", "sungay", "horns", "tinik", "spikes", "tunok", "kalasag", "taming", "armor", "Triceratops", "Stegosaurus"], "fact": {"tl": "Maraming herbivore na dinosaur ang may mga sandata para sa depensa — sungay sa Triceratops, tinik sa buntot ng Stegosaurus, at makapal na kalasag na buto sa iba — para ipagtanggol ang sarili sa mga karnibor.", "en": "Many plant-eating dinosaurs had defensive weapons — horns on Triceratops, tail spikes on Stegosaurus, and thick bony armor on others — to protect themselves from carnivores.", "bis": "Daghang herbivore nga dinosaur ang adunay mga hinagiban alang sa depensa — sungay sa Triceratops, tunok sa ikog sa Stegosaurus, ug baga nga bukog nga taming sa uban — aron panalipdan ang kaugalingon batok sa mga karnibor."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "trex-bird-relative-g6", "domain": "LIVING_THINGS", "topic": "T. rex was related to birds", "grades": [5, 6, 7], "terms": ["T. rex", "Tyrannosaurus", "ibon", "bird", "langgam", "kamag-anak", "relative", "kaliwat", "paryente", "manok", "chicken", "theropod", "dalawang paa", "duha ka tiil"], "fact": {"tl": "Kahit isang mabangis na karnibor, ang T. rex ay malapit na kamag-anak ng mga modernong ibon — kaya ang manok ngayon ay isa sa mga buhay na kaanak ng dinosaur.", "en": "Even though it was a fierce carnivore, T. rex was a close relative of modern birds — so today's chickens are among the living relatives of dinosaurs.", "bis": "Bisan tuod usa kini ka mabangis nga karnibor, ang T. rex usa ka duol nga paryente sa modernong mga langgam — busa ang manok karon usa sa mga buhi nga paryente sa dinosaur."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dino-cold-blooded-question-g6", "domain": "LIVING_THINGS", "topic": "dinosaurs as reptiles", "grades": [5, 6, 7], "terms": ["dinosaur", "reptilya", "reptile", "butiki", "buwaya", "buaya", "crocodile", "scaly", "kaliskis", "balat", "skin", "land", "lupa", "yuta", "paryente", "langgam"], "fact": {"tl": "Ang mga dinosaur ay kabilang sa grupo ng mga reptilya, at ang kanilang malapit na buhay na kaanak ngayon ay ang mga buwaya at ibon.", "en": "Dinosaurs belonged to the reptile group, and their closest living relatives today are crocodiles and birds.", "bis": "Ang mga dinosaur sakop sa grupo sa mga reptilya, ug ang ilang labing duol nga buhi nga paryente karon mao ang mga buaya ug langgam."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cheetah-fastest-land-g4", "domain": "LIVING_THINGS", "topic": "fastest land animal cheetah", "grades": [3, 4, 5], "terms": ["cheetah", "fastest", "fast", "fastest land animal", "speed", "run", "running", "pinakamabilis", "mabilis", "tumakbo", "takbo", "lupa", "hayop", "tigpaspasi", "paspas", "kusog modagan", "dagan", "modagan", "hayop sa yuta"], "fact": {"tl": "Ang cheetah ang pinakamabilis na hayop sa lupa. Kaya nitong tumakbo nang halos 100 hanggang 110 kilometro kada oras, pero sa maikling pagitan lang dahil mabilis itong mapagod.", "en": "The cheetah is the fastest land animal. It can run about 100 to 110 kilometers per hour, but only in short bursts because it tires quickly.", "bis": "Ang cheetah mao ang pinakapaspas nga hayop sa yuta. Makahimo kini sa pagdagan og mga 100 ngadto sa 110 ka kilometro kada oras, apan sa mubo nga panahon lang kay paspas kini makapuyan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "peregrine-falcon-fastest-bird-g5", "domain": "LIVING_THINGS", "topic": "fastest bird peregrine falcon", "grades": [4, 5, 6], "terms": ["peregrine falcon", "falcon", "fastest bird", "fastest animal", "dive", "diving", "stoop", "pinakamabilis na ibon", "ibon", "lawin", "sumisisid", "sisid", "lumusob", "langgam", "banog", "sundayong", "pinakapaspas nga langgam", "pagsalom"], "fact": {"tl": "Ang peregrine falcon (isang uri ng lawin) ang pinakamabilis na hayop sa buong mundo. Kapag sumisisid ito pababa para hulihin ang biktima, umaabot ito sa mahigit 300 kilometro kada oras.", "en": "The peregrine falcon is the fastest animal in the world. When it dives down to catch prey, it can reach over 300 kilometers per hour.", "bis": "Ang peregrine falcon (usa ka matang sa banog) mao ang pinakapaspas nga hayop sa tibuok kalibutan. Kon mosalom kini paubos aron dakpon ang tukbonon, makaabot kini og kapin sa 300 ka kilometro kada oras."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "blue-whale-largest-animal-g4", "domain": "LIVING_THINGS", "topic": "largest animal blue whale", "grades": [3, 4, 5], "terms": ["blue whale", "biggest animal", "largest animal", "biggest", "largest", "whale", "pinakamalaki", "malaki", "balyena", "pinakamalaking hayop", "hayop", "asul na balyena", "pinakadako", "dako", "balyena", "pinakadako nga hayop", "asul nga balyena"], "fact": {"tl": "Ang blue whale (asul na balyena) ang pinakamalaking hayop na nabuhay kailanman sa Earth — mas malaki pa kaysa kahit anong dinosaur. Umaabot ito ng mga 30 metro ang haba.", "en": "The blue whale is the largest animal that has ever lived on Earth — even bigger than any dinosaur. It can reach about 30 meters long.", "bis": "Ang blue whale (asul nga balyena) mao ang pinakadako nga hayop nga nabuhi sukad sa Earth — mas dako pa kaysa bisan unsang dinosaur. Makaabot kini og mga 30 ka metro ang gitas-on."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "blue-whale-heart-tongue-g6", "domain": "LIVING_THINGS", "topic": "blue whale size body", "grades": [5, 6, 7], "terms": ["blue whale", "heart", "weight", "heavy", "puso", "mabigat", "timbang", "bigat", "balyena", "kasing-bigat", "kasingbigat", "kasing laki", "kasimbug-at", "kabug-at", "dako", "kotse", "elepante"], "fact": {"tl": "Napakalaki ng blue whale na ang puso nito ay kasinglaki ng isang maliit na kotse, at kayang tumimbang ang buong hayop ng higit 150 toneladang metriko — kasimbigat ng mahigit 25 na elepante.", "en": "The blue whale is so huge that its heart is about the size of a small car, and the whole animal can weigh over 150 metric tons — as heavy as more than 25 elephants.", "bis": "Hilabihan ka dako sa blue whale nga ang kasingkasing niini sama kadako sa usa ka gamay nga sakyanan, ug ang tibuok hayop makatimbang og kapin sa 150 ka metriko nga tonelada — kasimbug-at sa kapin sa 25 ka elepante."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "african-elephant-largest-land-g4", "domain": "LIVING_THINGS", "topic": "largest land animal elephant", "grades": [3, 4, 5], "terms": ["African elephant", "elephant", "biggest land animal", "largest land animal", "biggest", "elepante", "pinakamalaking hayop sa lupa", "malaki", "lupa", "Africa", "pinakadako nga hayop sa yuta", "dako", "elepante", "yuta", "hayop sa lupa"], "fact": {"tl": "Ang African elephant ang pinakamalaking hayop sa lupa. Kayang tumimbang ang malaking lalaki nito ng halos 6 na toneladang metriko at maging mas mataas pa sa tatlong metro sa balikat.", "en": "The African elephant is the largest land animal. A big male can weigh almost 6 metric tons and stand more than three meters tall at the shoulder.", "bis": "Ang African elephant mao ang pinakadako nga hayop sa yuta. Ang dako nga laki niini makatimbang og halos 6 ka metriko nga tonelada ug makataas og kapin sa tulo ka metro sa abaga."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "giraffe-tallest-animal-g3", "domain": "LIVING_THINGS", "topic": "tallest animal giraffe", "grades": [3, 4, 5], "terms": ["giraffe", "tallest", "tall", "tallest animal", "neck", "pinakamatangkad", "matangkad", "mataas", "leeg", "hayop", "pinakataas", "taas", "liog", "pinakataas nga hayop", "tiyan"], "fact": {"tl": "Ang giraffe ang pinakamatangkad na hayop sa mundo, umaabot ng halos 5 hanggang 6 na metro ang taas. Mahaba ang leeg nito para makaabot sa mga dahon sa matataas na puno.", "en": "The giraffe is the tallest animal in the world, reaching about 5 to 6 meters tall. Its long neck helps it reach leaves high up in trees.", "bis": "Ang giraffe mao ang pinakataas nga hayop sa kalibutan, makaabot og halos 5 ngadto sa 6 ka metro ang katas-on. Ang taas niini nga liog makatabang aron makakab-ot sa mga dahon sa taas nga mga kahoy."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ostrich-largest-bird-g4", "domain": "LIVING_THINGS", "topic": "largest bird ostrich", "grades": [3, 4, 5], "terms": ["ostrich", "biggest bird", "largest bird", "tallest bird", "cannot fly", "flightless", "pinakamalaking ibon", "ibon", "hindi lumilipad", "avestruz", "pinakadako nga langgam", "langgam", "dili makalupad", "itlog", "pinakadako nga itlog"], "fact": {"tl": "Ang ostrich ang pinakamalaki at pinakamatangkad na ibon sa mundo, pero hindi ito makalipad. Sa halip, napakabilis nitong tumakbo sa lupa.", "en": "The ostrich is the largest and tallest bird in the world, but it cannot fly. Instead, it runs very fast on the ground.", "bis": "Ang ostrich mao ang pinakadako ug pinakataas nga langgam sa kalibutan, apan dili kini makalupad. Hinuon, paspas kaayo kini modagan sa yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ostrich-fastest-running-bird-g5", "domain": "LIVING_THINGS", "topic": "fastest running bird ostrich", "grades": [4, 5, 6], "terms": ["ostrich", "fastest running bird", "fastest bird on land", "run", "running", "pinakamabilis tumakbo", "ibon", "tumakbo", "takbo", "lupa", "langgam", "modagan", "dagan", "pinakapaspas modagan", "yuta"], "fact": {"tl": "Ang ostrich ang pinakamabilis tumakbo na ibon sa lupa. Kaya nitong tumakbo nang halos 70 kilometro kada oras gamit ang malalakas nitong paa.", "en": "The ostrich is the fastest running bird on land. It can run about 70 kilometers per hour using its strong legs.", "bis": "Ang ostrich mao ang pinakapaspas modagan nga langgam sa yuta. Makahimo kini sa pagdagan og halos 70 ka kilometro kada oras gamit ang kusgan niini nga mga tiil."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ostrich-largest-egg-g3", "domain": "LIVING_THINGS", "topic": "largest egg ostrich", "grades": [3, 4], "terms": ["ostrich egg", "biggest egg", "largest egg", "egg", "pinakamalaking itlog", "itlog", "ibon", "pinakadako nga itlog", "itlog sa ostrich", "langgam"], "fact": {"tl": "Ang itlog ng ostrich ang pinakamalaking itlog sa lahat ng ibon ngayon. Isang itlog lang nito ay kasinlaki ng mga 24 na itlog ng manok.", "en": "The ostrich egg is the largest egg of any bird living today. Just one of its eggs is about the size of 24 chicken eggs.", "bis": "Ang itlog sa ostrich mao ang pinakadako nga itlog sa tanang langgam karon. Usa ra ka itlog niini sama kadako sa mga 24 ka itlog sa manok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sailfish-fastest-fish-g6", "domain": "LIVING_THINGS", "topic": "fastest fish sailfish", "grades": [5, 6, 7], "terms": ["sailfish", "fastest fish", "fast swimmer", "swim", "fish", "ocean", "pinakamabilis na isda", "isda", "lumangoy", "langoy", "dagat", "malansi", "liplipan", "pinakapaspas nga isda", "molangoy", "languyon"], "fact": {"tl": "Ang sailfish ang itinuturing na pinakamabilis na isda sa dagat. Kaya nitong lumangoy nang halos 100 kilometro kada oras, mas mabilis pa kaysa karamihang kotse.", "en": "The sailfish is considered the fastest fish in the sea. It can swim about 100 kilometers per hour, faster than most cars.", "bis": "Ang sailfish giila nga pinakapaspas nga isda sa dagat. Makahimo kini sa paglangoy og halos 100 ka kilometro kada oras, mas paspas pa kaysa kadaghanan sa mga sakyanan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bee-hummingbird-smallest-bird-g4", "domain": "LIVING_THINGS", "topic": "smallest bird bee hummingbird", "grades": [3, 4, 5], "terms": ["bee hummingbird", "smallest bird", "tiniest bird", "hummingbird", "small", "pinakamaliit na ibon", "maliit", "ibon", "pinakagamay nga langgam", "gamay", "langgam", "Cuba", "bubuyog"], "fact": {"tl": "Ang bee hummingbird ang pinakamaliit na ibon sa mundo. Napakaliit nito na halos kasinlaki lang ito ng isang malaking bubuyog.", "en": "The bee hummingbird is the smallest bird in the world. It is so tiny that it is about the same size as a large bee.", "bis": "Ang bee hummingbird mao ang pinakagamay nga langgam sa kalibutan. Gamay kaayo kini nga halos sama ra kadako sa usa ka dako nga buyog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tortoise-longest-living-g5", "domain": "LIVING_THINGS", "topic": "longest living animal tortoise", "grades": [4, 5, 6], "terms": ["giant tortoise", "tortoise", "longest living", "oldest animal", "live long", "lifespan", "pinakamatandang hayop", "matanda", "nabubuhay nang matagal", "pagong", "pawikan", "pinakadugay mabuhi", "pinakatigulang", "tigulang", "bao"], "fact": {"tl": "Ang giant tortoise (malaking pagong sa lupa) ang isa sa pinakamatagal mabuhay na hayop. Maaari itong mabuhay nang higit 100 taon, mas matagal pa kaysa karamihang tao.", "en": "The giant tortoise is one of the longest-living animals. It can live more than 100 years, longer than most humans.", "bis": "Ang giant tortoise (dako nga bao sa yuta) usa sa pinakadugay mabuhi nga mga hayop. Makahimo kini sa pagkinabuhi og kapin sa 100 ka tuig, mas dugay pa kaysa kadaghanan sa mga tawo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "greenland-shark-oldest-vertebrate-g8", "domain": "LIVING_THINGS", "topic": "longest living vertebrate greenland shark", "grades": [7, 8, 9], "terms": ["Greenland shark", "oldest animal", "longest living vertebrate", "shark", "live long", "lifespan", "pinakamatandang hayop", "nabubuhay nang matagal", "pating", "malamig na dagat", "pinakatigulang nga hayop", "iho", "pinakadugay mabuhi", "bugnaw nga dagat"], "fact": {"tl": "Ang Greenland shark ang itinuturing na hayop na may gulugod na pinakamatagal mabuhay. Pinaniniwalaang umaabot ito ng mahigit 300 taon dahil sa napakabagal nitong paglaki sa malamig na karagatan.", "en": "The Greenland shark is thought to be the longest-living animal with a backbone. It is believed to live more than 300 years because it grows so slowly in the cold ocean.", "bis": "Ang Greenland shark giila nga hayop nga adunay bukog sa likod nga pinakadugay mabuhi. Gituohan nga makaabot kini og kapin sa 300 ka tuig kay hinay kaayo kini motubo sa bugnaw nga kadagatan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ant-strongest-for-size-g4", "domain": "LIVING_THINGS", "topic": "strongest insect ant", "grades": [3, 4, 5], "terms": ["ant", "strongest", "strong", "carry", "lift", "body weight", "pinakamalakas", "malakas", "langgam", "buhat", "bigat", "kusgan", "hulmigas", "kusog", "pas-an", "pinakakusgan", "alibangbang"], "fact": {"tl": "Kung ihahambing sa laki nito, isa ang langgam sa pinakamalakas na hayop. Kaya nitong buhatin ang bagay na mas mabigat ng maraming beses kaysa sa sarili nitong timbang.", "en": "For its size, the ant is one of the strongest animals. It can carry objects many times heavier than its own body weight.", "bis": "Kon itandi sa kadako niini, ang hulmigas usa sa pinakakusgan nga mga hayop. Makahimo kini sa pagdala og mga butang nga mas bug-at og daghang pilo kaysa sa kaugalingong gibug-aton niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dung-beetle-strongest-insect-g6", "domain": "LIVING_THINGS", "topic": "strongest insect dung beetle", "grades": [5, 6, 7], "terms": ["dung beetle", "strongest insect", "strongest animal", "strong", "push", "pull", "pinakamalakas na insekto", "malakas", "salagubang", "uod", "kusgan", "duso", "guyod", "pinakakusgan nga insekto", "bakukang"], "fact": {"tl": "Ang dung beetle ang itinuturing na pinakamalakas na insekto kung itutumbas sa laki nito. Kaya nitong hilahin ang bagay na mahigit 1,000 beses ang bigat kaysa sa sarili nito.", "en": "The dung beetle is considered the strongest insect for its size. It can pull objects more than 1,000 times its own weight.", "bis": "Ang dung beetle giila nga pinakakusgan nga insekto kon itandi sa kadako niini. Makahimo kini sa pagguyod og mga butang nga kapin sa 1,000 ka pilo ang gibug-aton kaysa sa kaugalingon niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "elephant-strongest-land-mammal-g5", "domain": "LIVING_THINGS", "topic": "strongest land animal elephant", "grades": [4, 5, 6], "terms": ["elephant", "strongest land animal", "strong", "trunk", "carry", "pinakamalakas na hayop sa lupa", "malakas", "elepante", "nguso", "buhat", "kusgan", "pinakakusgan nga hayop", "lawas nga ilong", "pas-an"], "fact": {"tl": "Ang elepante ang isa sa pinakamalakas na hayop sa lupa. Gamit lang ang mahabang nguso nito (trunk), kaya nitong buhatin ang mabibigat na sanga ng puno.", "en": "The elephant is one of the strongest land animals. Using just its long trunk, it can lift heavy tree branches.", "bis": "Ang elepante usa sa pinakakusgan nga mga hayop sa yuta. Gamit lang ang taas niini nga nguso (trunk), makahimo kini sa pag-alsa sa bug-at nga mga sanga sa kahoy."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "etruscan-shrew-smallest-mammal-g6", "domain": "LIVING_THINGS", "topic": "smallest mammal etruscan shrew", "grades": [5, 6, 7], "terms": ["Etruscan shrew", "smallest mammal", "tiny mammal", "small", "shrew", "pinakamaliit na mamalya", "maliit", "mamalya", "pinakagamay nga mananap nga nagpasuso", "gamay", "daga", "pinakagamay nga sus-an", "pispis"], "fact": {"tl": "Ang Etruscan shrew ang itinuturing na pinakamaliit na mamalya (hayop na nagpapasuso) ayon sa timbang. Napakaliit nito na kayang tumimbang ng wala pang dalawang gramo.", "en": "The Etruscan shrew is considered the smallest mammal by weight. It is so tiny that it can weigh less than two grams.", "bis": "Ang Etruscan shrew giila nga pinakagamay nga sus-an (hayop nga nagpasuso) sumala sa gibug-aton. Gamay kaayo kini nga makatimbang og ubos pa sa duha ka gramo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "blue-whale-loudest-animal-g6", "domain": "LIVING_THINGS", "topic": "loudest animal blue whale", "grades": [5, 6, 7], "terms": ["blue whale", "loudest animal", "loud sound", "call", "sound", "pinakamalakas na tunog", "ingay", "balyena", "tunog", "tawag", "kusog nga tingog", "pinakakusog nga tingog", "saba", "kalibutan"], "fact": {"tl": "Ang blue whale ang gumagawa ng isa sa pinakamalakas na tunog ng anumang hayop. Ang malalakas nitong tawag ay umaabot sa ibang balyena na daan-daang kilometro ang layo sa dagat.", "en": "The blue whale makes one of the loudest sounds of any animal. Its powerful calls can reach other whales hundreds of kilometers away in the ocean.", "bis": "Ang blue whale naghimo og usa sa pinakakusog nga tingog sa bisan unsang hayop. Ang gamhanan niini nga mga tawag makaabot sa ubang balyena nga gatusan ka kilometro ang gilay-on sa dagat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "colossal-squid-largest-eye-g7", "domain": "LIVING_THINGS", "topic": "largest eye colossal squid", "grades": [6, 7, 8], "terms": ["colossal squid", "giant squid", "largest eye", "biggest eye", "eye", "deep sea", "pinakamalaking mata", "mata", "pusit", "kalmares", "malalim na dagat", "pinakadako nga mata", "nokus", "lawom nga dagat", "pinakadako nga mata sa hayop"], "fact": {"tl": "Ang colossal squid ang may pinakamalaking mata sa lahat ng hayop, halos kasinlaki ng isang plato ng pagkain. Tumutulong ito para makakita sa madilim at malalim na bahagi ng dagat.", "en": "The colossal squid has the largest eyes of any animal, almost the size of a dinner plate. They help it see in the dark, deep parts of the ocean.", "bis": "Ang colossal squid adunay pinakadako nga mata sa tanang hayop, halos sama kadako sa usa ka plato sa pagkaon. Makatabang kini aron makakita sa ngitngit ug lawom nga mga bahin sa dagat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "blue-whale-largest-mouth-g6", "domain": "LIVING_THINGS", "topic": "blue whale feeding krill", "grades": [5, 6, 7], "terms": ["blue whale", "krill", "biggest eater", "eat", "mouth", "kumakain", "pagkain", "bibig", "balyena", "araw", "kaon", "baba", "pinakadako nga baba", "krill", "maliliit na hayop", "tonelada"], "fact": {"tl": "Kahit ang pinakamalaking hayop sa mundo, kumakain lang ang blue whale ng napakaliliit na hayop na tinatawag na krill. Kaya nitong kumain ng ilang toneladang krill sa isang araw.", "en": "Even though it is the largest animal in the world, the blue whale eats only tiny animals called krill. It can eat several tons of krill in a single day.", "bis": "Bisan og kini ang pinakadako nga hayop sa kalibutan, ang blue whale gamay ra nga mga hayop nga gitawag og krill ang gikaon niini. Makahimo kini sa pagkaon og pipila ka tonelada nga krill sa usa lang ka adlaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "arctic-tern-longest-migration-g7", "domain": "LIVING_THINGS", "topic": "longest migration arctic tern", "grades": [6, 7, 8], "terms": ["arctic tern", "longest migration", "longest journey", "travel", "fly", "bird", "pinakamahabang paglalakbay", "lumilipad", "ibon", "lumipad", "pinakadugay nga panaw", "langgam", "lupad", "pinakalayo nga panaw", "biyahe", "panaw"], "fact": {"tl": "Ang arctic tern ang gumagawa ng pinakamahabang paglalakbay sa lahat ng hayop. Bawat taon, lumilipad ito mula sa Arctic patungong Antarctica at pabalik — libo-libong kilometro ang layo.", "en": "The arctic tern makes the longest migration of any animal. Each year it flies from the Arctic to Antarctica and back — many thousands of kilometers.", "bis": "Ang arctic tern naghimo sa pinakataas nga panaw sa tanang hayop. Matag tuig, molupad kini gikan sa Arctic padulong sa Antarctica ug mobalik — liboan ka kilometro ang gilay-on."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "saltwater-crocodile-strongest-bite-g7", "domain": "LIVING_THINGS", "topic": "strongest bite crocodile", "grades": [6, 7, 8], "terms": ["saltwater crocodile", "crocodile", "strongest bite", "bite force", "jaw", "pinakamalakas na kagat", "kagat", "buwaya", "panga", "pinakakusog nga paak", "paak", "panga", "bukya", "Philippines", "Lolong"], "fact": {"tl": "Ang saltwater crocodile (buwaya sa tabang-alat na tubig) ang may pinakamalakas na kagat sa lahat ng buhay na hayop ngayon. Sa Pilipinas natagpuan si Lolong, isa sa pinakamalaking buwaya na nahuli.", "en": "The saltwater crocodile has the strongest bite of any living animal today. The Philippines was home to Lolong, one of the largest crocodiles ever caught.", "bis": "Ang saltwater crocodile (buaya sa parat nga tubig) adunay pinakakusog nga paak sa tanang buhi nga hayop karon. Sa Pilipinas nakaplagan si Lolong, usa sa pinakadako nga buaya nga nadakpan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kangaroo-best-jumper-g4", "domain": "LIVING_THINGS", "topic": "best jumper kangaroo", "grades": [3, 4, 5], "terms": ["kangaroo", "best jumper", "jump", "highest jump", "longest jump", "hop", "pinakamagaling lumukso", "lumukso", "lukso", "talon", "kanggaroo", "pinakamaayo molukso", "lukso", "ambak", "layo nga lukso"], "fact": {"tl": "Ang kangaroo ang isa sa pinakamagaling lumukso na hayop. Sa isang malaking lukso, kaya nitong tumalon nang mahigit anim na metro ang layo gamit ang malalakas na hulihang paa.", "en": "The kangaroo is one of the best jumping animals. In a single big leap it can jump more than six meters using its powerful back legs.", "bis": "Ang kangaroo usa sa pinakamaayo molukso nga mga hayop. Sa usa ka dako nga lukso, makahimo kini sa pag-ambak og kapin sa unom ka metro gamit ang kusgan niini nga likod nga mga tiil."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cheetah-acceleration-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "cheetah acceleration speed", "grades": [6, 7, 8], "terms": ["cheetah", "acceleration", "speed up", "fast start", "accelerate", "mabilis bumilis", "bilis", "pabilis", "pabilis", "takbo", "paspas modagan", "kalit nga kapaspason", "pagpaspas", "sprint"], "fact": {"tl": "Hindi lang mabilis ang cheetah — napakabilis din nitong magsimulang tumakbo. Kaya nitong umabot sa 100 kilometro kada oras sa loob lang ng ilang segundo, mas mabilis pa kaysa karamihang sasakyan.", "en": "The cheetah is not just fast — it also speeds up very quickly. It can reach 100 kilometers per hour in just a few seconds, faster than most cars.", "bis": "Ang cheetah dili lang paspas — paspas usab kini mosugod sa pagdagan. Makaabot kini og 100 ka kilometro kada oras sulod ra sa pipila ka segundo, mas paspas pa kaysa kadaghanan sa mga sakyanan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sloth-slowest-mammal-g4", "domain": "LIVING_THINGS", "topic": "slowest animal sloth", "grades": [3, 4, 5], "terms": ["sloth", "slowest animal", "slow", "lazy", "pinakamabagal", "mabagal", "hayop", "tamad", "kilos", "pinakahinay", "hinay", "hayop", "tapulan", "lihok", "kahoy"], "fact": {"tl": "Ang sloth ang isa sa pinakamabagal na hayop sa mundo. Napakabagal nitong gumalaw na halos buong araw na lang itong nakabitin sa mga sanga ng puno.", "en": "The sloth is one of the slowest animals in the world. It moves so slowly that it spends almost the whole day hanging from tree branches.", "bis": "Ang sloth usa sa pinakahinay nga mga hayop sa kalibutan. Hinay kaayo kini molihok nga halos tibuok adlaw kini nagbitay sa mga sanga sa kahoy."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "elephant-largest-ears-g3", "domain": "LIVING_THINGS", "topic": "largest ears african elephant", "grades": [3, 4], "terms": ["African elephant", "biggest ears", "largest ears", "ears", "cool down", "elepante", "pinakamalaking tainga", "tainga", "lamig", "init", "pinakadako nga dunggan", "dunggan", "bugnaw", "pamaypay"], "fact": {"tl": "Ang African elephant ang may pinakamalaking tainga sa lahat ng hayop. Ipinapaypay nito ang malalaking tainga para palamigin ang katawan sa mainit na lugar.", "en": "The African elephant has the largest ears of any animal. It flaps its big ears to cool down its body in hot places.", "bis": "Ang African elephant adunay pinakadako nga dunggan sa tanang hayop. Gipaypay niini ang dako nga mga dunggan aron pabugnawon ang lawas sa init nga mga lugar."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "anglerfish-deepest-fish-g7", "domain": "LIVING_THINGS", "topic": "deep sea fish anglerfish", "grades": [6, 7, 8], "terms": ["anglerfish", "deep sea fish", "deep ocean", "glowing", "light", "malalim na dagat", "isda", "kumikinang", "ilaw", "malalim", "lawom nga dagat", "isda", "modan-ag", "suga", "kangitngit", "lawom"], "fact": {"tl": "Ang anglerfish ay nakatira sa malalim at madilim na bahagi ng dagat. May likas itong ilaw na kumikinang sa harap ng ulo para makaakit ng pagkain sa dilim.", "en": "The anglerfish lives in deep, dark parts of the ocean. It has a natural glowing light in front of its head to lure food in the dark.", "bis": "Ang anglerfish nagpuyo sa lawom ug ngitngit nga mga bahin sa dagat. Aduna kini kinaiyanhon nga suga nga modan-ag sa atubangan sa ulo aron makadani og pagkaon sa kangitngit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hummingbird-fastest-wings-g5", "domain": "LIVING_THINGS", "topic": "fastest wingbeat hummingbird", "grades": [4, 5, 6], "terms": ["hummingbird", "fastest wings", "flap", "wingbeat", "hover", "mabilis na pakpak", "pakpak", "ibon", "lumulutang", "pinakamabilis na pagaspas", "paspas nga pako", "pako", "langgam", "naglutaw", "pagkapak"], "fact": {"tl": "Ang hummingbird ang may pinakamabilis na pagaspas ng pakpak sa lahat ng ibon — umaabot ng higit 50 beses kada segundo. Kaya nitong lumutang sa ere na parang nakatigil sa isang lugar.", "en": "The hummingbird has the fastest wingbeats of any bird — more than 50 times per second. This lets it hover in the air as if standing still.", "bis": "Ang hummingbird adunay pinakapaspas nga pagkapak sa pako sa tanang langgam — kapin sa 50 ka pilo kada segundo. Tungod niini makahimo kini sa paglutaw sa hangin nga daw nagpabilin sa usa ka lugar."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "skeleton-protects-organs-g4", "domain": "LIVING_THINGS", "topic": "skeleton protects organs", "grades": [4, 5], "terms": ["bungo", "skull", "utak", "tadyang", "rib", "rib cage", "buto-buto", "kalabera", "kalansay", "bagolbagol", "gusok", "kasingkasing", "puso", "baga", "protektahan", "panalipdan", "protect", "bones protect"], "fact": {"tl": "May mga buto na nagpoprotekta sa mahahalagang bahagi ng katawan: ang bungo ay nakapalibot sa utak, at ang mga tadyang ay nakaharang sa puso at baga.", "en": "Some bones protect important body parts: the skull surrounds the brain, and the ribs form a cage that shields the heart and lungs.", "bis": "Adunay mga bukog nga nanalipod sa importanteng bahin sa lawas: ang bagolbagol naglibot sa utok, ug ang mga gusok nagpanalipod sa kasingkasing ug baga."}, "source": "AAAS Benchmarks 6C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "joints-let-us-bend-g4", "domain": "LIVING_THINGS", "topic": "joints", "grades": [4, 5], "terms": ["kasukasuan", "joint", "joints", "lutahan", "siko", "elbow", "tuhod", "knee", "balikat", "shoulder", "abaga", "yumuko", "baliko", "bend", "ikurba", "pagliko", "kung saan nagtatagpo ang buto"], "fact": {"tl": "Ang kasukasuan ay ang lugar kung saan nagtatagpo ang dalawang buto, at ito ang dahilan kung bakit tayo nakakayuko sa siko, tuhod, at balikat.", "en": "A joint is the place where two bones meet, and joints are what let us bend at the elbow, knee, and shoulder.", "bis": "Ang lutahan mao ang dapit diin magtagbo ang duha ka bukog, ug kini ang hinungdan nga makaliko kita sa siko, tuhod, ug abaga."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bones-make-blood-marrow-g6", "domain": "LIVING_THINGS", "topic": "bone marrow makes blood", "grades": [6, 7], "terms": ["utak ng buto", "bone marrow", "marrow", "kauyokan sa bukog", "dugo", "blood", "selula ng dugo", "blood cells", "red blood cells", "pulang selula", "gumagawa ng dugo", "naghimo og dugo", "ginagawa", "tigom sa bukog"], "fact": {"tl": "Sa loob ng ilang malalaking buto ay may malambot na bahaging tinatawag na utak ng buto (bone marrow) na siyang gumagawa ng mga bagong selula ng dugo.", "en": "Inside some large bones is a soft part called bone marrow, which makes new blood cells for the body.", "bis": "Sa sulod sa pipila ka dagkong bukog adunay humok nga bahin nga gitawag og kauyokan sa bukog (bone marrow), nga maoy naghimo og bag-ong mga selula sa dugo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "muscles-pull-not-push-g6", "domain": "LIVING_THINGS", "topic": "muscles pull in pairs", "grades": [6, 7], "terms": ["kalamnan", "muscle", "muscles", "kaunoran", "humila", "pull", "birahon", "hindi nagtutulak", "magkapares", "pairs", "biceps", "triceps", "braso", "arm", "bukton", "umuurong", "mokunot", "contract", "nag-iikli"], "fact": {"tl": "Ang mga kalamnan ay humihila lamang at hindi nagtutulak, kaya madalas silang nagtatrabaho nang magkapares: habang umuurong ang isa para iyuko ang braso, namamahinga ang kabila para iunat ito.", "en": "Muscles can only pull, not push, so they often work in pairs: one contracts to bend the arm while its partner relaxes to straighten it.", "bis": "Ang mga kaunoran makabira lamang ug dili makatukmod, mao nga sagad sila magtrabaho nga magtinagduha: mokunot ang usa aron balukon ang bukton samtang mopahulay ang pikas aron itul-id kini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "heart-muscle-never-rests-g5", "domain": "LIVING_THINGS", "topic": "the heart is a muscle", "grades": [5, 6], "terms": ["puso", "heart", "kasingkasing", "kalamnan", "muscle", "kaunoran", "tumitibok", "beat", "nagpitik", "pumibo", "bombahin", "pump", "bumbahon ang dugo", "nagpundok sa dugo", "hindi napapagod", "wala mahago"], "fact": {"tl": "Ang puso ay isang malakas na kalamnan na tumitibok at nagbobomba ng dugo araw-gabi, kahit habang tayo ay natutulog.", "en": "The heart is a strong muscle that beats and pumps blood day and night, even while we are asleep.", "bis": "Ang kasingkasing usa ka kusgan nga kaunoran nga mopitik ug mobomba sa dugo adlaw ug gabii, bisan samtang kita natulog."}, "source": "AAAS Benchmarks 6C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "blood-vessels-types-g6", "domain": "LIVING_THINGS", "topic": "arteries veins capillaries", "grades": [6, 7], "terms": ["ugat", "blood vessel", "vessels", "arterya", "artery", "ugatdugo", "vena", "vein", "capillary", "kapilarya", "daluyan ng dugo", "agianan sa dugo", "dinaluyan", "papalayo sa puso", "pabalik sa puso"], "fact": {"tl": "May tatlong uri ng daluyan ng dugo: ang mga arterya na nagdadala ng dugo palayo sa puso, ang mga vena na nagbabalik nito sa puso, at ang napakanipis na kapilarya na nag-uugnay sa kanila.", "en": "There are three kinds of blood vessels: arteries that carry blood away from the heart, veins that return it to the heart, and tiny capillaries that connect them.", "bis": "Adunay tulo ka matang sa agianan sa dugo: ang mga arterya nga modala sa dugo palayo sa kasingkasing, ang mga vena nga mobalik niini sa kasingkasing, ug ang gagmayng kapilarya nga nagsumpay kanila."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pulse-is-heartbeat-g5", "domain": "LIVING_THINGS", "topic": "pulse", "grades": [5, 6], "terms": ["pulso", "pulse", "tibok", "heartbeat", "pitik", "pumipintig", "galiok", "pumipitik sa pulsuhan", "bilang ng tibok", "ihap sa pitik", "pulsuhan"], "fact": {"tl": "Ang pulso na nararamdaman mo sa pulsuhan ay ang pagtibok ng puso na nararamdaman sa pamamagitan ng pagbomba ng dugo sa mga arterya.", "en": "The pulse you feel at your wrist is your heartbeat, felt as the heart pushes blood through the arteries.", "bis": "Ang pulso nga imong mabati sa imong pulsuhan mao ang pitik sa kasingkasing, nga mabati samtang giduso niini ang dugo sa mga arterya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lungs-gas-exchange-alveoli-g7", "domain": "LIVING_THINGS", "topic": "alveoli in lungs", "grades": [7, 8], "terms": ["baga", "lungs", "alveoli", "air sacs", "supot ng hangin", "supot sa hangin", "oksiheno", "oxygen", "carbon dioxide", "palitan ng gas", "gas exchange", "ilis sa gas", "dugo", "blood", "papasok sa dugo"], "fact": {"tl": "Sa loob ng baga ay may milyon-milyong maliliit na supot ng hangin na tinatawag na alveoli, kung saan ang oksiheno ay pumapasok sa dugo at ang carbon dioxide ay lumalabas.", "en": "Inside the lungs are millions of tiny air sacs called alveoli, where oxygen passes into the blood and carbon dioxide passes out.", "bis": "Sa sulod sa baga adunay minilyon nga gagmayng supot sa hangin nga gitawag og alveoli, diin ang oksiheno mosulod sa dugo ug ang carbon dioxide mogawas."}, "source": "AAAS Benchmarks 6C/M3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "diaphragm-breathing-g6", "domain": "LIVING_THINGS", "topic": "diaphragm", "grades": [6, 7], "terms": ["diaphragm", "diapragma", "kalamnan sa paghinga", "muscle for breathing", "humihinga", "huminga", "ginhawa", "paghinga", "breathe", "bumababa", "lumalapad ang baga", "sumususo ng hangin", "humihigop ng hangin"], "fact": {"tl": "Sa ilalim ng baga ay may malaking kalamnang tinatawag na diaphragm na bumababa para makapasok ang hangin sa baga at tumataas para mailabas ito.", "en": "Below the lungs is a large muscle called the diaphragm that moves down to pull air into the lungs and up to push air out.", "bis": "Ubos sa baga adunay dakong kaunoran nga gitawag og diaphragm nga mokanaog aron mosulod ang hangin sa baga ug mosaka aron ipagawas kini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "we-breathe-oxygen-out-co2-g4", "domain": "LIVING_THINGS", "topic": "what we breathe in and out", "grades": [4, 5], "terms": ["oksiheno", "oxygen", "hininga", "hangin", "air", "carbon dioxide", "ilanghap", "ginhawa", "buga", "ibuga", "ihinga palabas", "kuha ng oksiheno", "kuha og oksiheno", "mohangos", "mobuga"], "fact": {"tl": "Kapag huminga ka, kumukuha ang katawan ng oksiheno mula sa hangin, at kapag huminga ka palabas, inilalabas nito ang carbon dioxide na hindi na kailangan.", "en": "When you breathe in, your body takes oxygen from the air, and when you breathe out, it releases carbon dioxide that it no longer needs.", "bis": "Kon mohangos ka, mokuha ang lawas og oksiheno gikan sa hangin, ug kon mobuga ka, ipagawas niini ang carbon dioxide nga dili na kinahanglan."}, "source": "AAAS Benchmarks 6C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "saliva-starts-digestion-g5", "domain": "LIVING_THINGS", "topic": "saliva and chewing", "grades": [5, 6], "terms": ["laway", "saliva", "luwa", "ngumunguya", "chew", "usap", "pagusap", "ngipin", "teeth", "ngipon", "dila", "tongue", "durog na pagkain", "dugmokon ang pagkain", "simula ng panunaw", "sugod sa panghilis"], "fact": {"tl": "Nagsisimula ang panunaw sa bibig: dinudurog ng ngipin ang pagkain habang hinahalo ng laway, kaya mas madaling lunukin at simulang matunaw.", "en": "Digestion begins in the mouth: the teeth grind food while saliva moistens it, making it easier to swallow and start breaking down.", "bis": "Magsugod ang panghilis sa baba: dugmokon sa ngipon ang pagkaon samtang basaon kini sa laway, aron sayon nga tulnon ug magsugod sa pagkatunaw."}, "source": "AAAS Benchmarks 6C/M2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "stomach-acid-breaks-food-g6", "domain": "LIVING_THINGS", "topic": "the stomach", "grades": [6, 7], "terms": ["tiyan", "stomach", "asido", "acid", "asido sa tiyan", "natunaw", "tunawin", "hilison", "pinaghahalo", "gisagol", "durog na pagkain", "pulpolon", "panghilis sa pagkaon", "bituka", "tinai"], "fact": {"tl": "Sa tiyan, hinahalo ang pagkain sa mga katas at asido na bumubasag dito sa mas maliliit na piraso bago ito ipasa sa bituka.", "en": "In the stomach, food is mixed with juices and acid that break it down into smaller pieces before it moves on to the intestines.", "bis": "Sa tiyan, ang pagkaon isagol sa mga duga ug asido nga mobungkag niini ngadto sa gagmayng tipik una kini moadto sa tinai."}, "source": "AAAS Benchmarks 6C/M2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "small-intestine-absorbs-g6", "domain": "LIVING_THINGS", "topic": "small intestine absorbs nutrients", "grades": [6, 7], "terms": ["maliit na bituka", "small intestine", "tinai", "gamayng tinai", "sustansya", "nutrients", "sustansiya", "nasisipsip", "sipsipin", "suhopon", "pumasok sa dugo", "mosulod sa dugo", "bituka", "intestine", "mahaba", "taas nga tinai"], "fact": {"tl": "Sa mahabang maliit na bituka, ang mga sustansya mula sa natunaw na pagkain ay nasisipsip at pumapasok sa dugo para maipamahagi sa buong katawan.", "en": "In the long small intestine, the nutrients from digested food are absorbed and pass into the blood to be carried all over the body.", "bis": "Sa taas nga gamayng tinai, ang mga sustansiya gikan sa natunaw nga pagkaon masuyop ug mosulod sa dugo aron iapod-apod sa tibuok lawas."}, "source": "AAAS Benchmarks 6C/M2,M3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "large-intestine-water-waste-g6", "domain": "LIVING_THINGS", "topic": "large intestine", "grades": [6, 7], "terms": ["malaking bituka", "large intestine", "dakong tinai", "tubig", "water", "dumi", "waste", "hugaw", "sinipsip ang tubig", "suyopon ang tubig", "tae", "feces", "basurang pagkain", "dili matunaw"], "fact": {"tl": "Sa malaking bituka, sinisipsip ang natitirang tubig mula sa hindi natunaw na pagkain, at ang natitira ay nagiging dumi na inilalabas ng katawan.", "en": "In the large intestine, the remaining water is absorbed from undigested food, and what is left becomes solid waste the body removes.", "bis": "Sa dakong tinai, ang nahabilin nga tubig suyopon gikan sa wala matunaw nga pagkaon, ug ang nahabilin mahimong hugaw nga ipagawas sa lawas."}, "source": "AAAS Benchmarks 6C/E1; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "liver-helps-digest-g7", "domain": "LIVING_THINGS", "topic": "the liver", "grades": [7, 8], "terms": ["atay", "liver", "apdo", "bile", "tunawin ang taba", "fat", "tambok", "panglinis", "filter", "salaon", "naglilinis ng dugo", "naghinlo sa dugo", "tumutulong sa panunaw", "lapad na organ"], "fact": {"tl": "Ang atay ay tumutulong sa panunaw sa pamamagitan ng paggawa ng apdo na bumabasag sa taba, at naglilinis din ito ng mga lason sa dugo.", "en": "The liver helps digestion by making bile that breaks up fats, and it also cleans harmful substances out of the blood.", "bis": "Ang atay motabang sa panghilis pinaagi sa paghimo og apdo nga mobungkag sa tambok, ug naghinlo usab kini sa makadaot nga mga butang sa dugo."}, "source": "AAAS Benchmarks 6C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kidneys-filter-blood-g6", "domain": "LIVING_THINGS", "topic": "kidneys filter blood", "grades": [6, 7], "terms": ["bato", "kidney", "kidneys", "kidni", "salaan", "filter", "salaon", "dugo", "blood", "ihi", "urine", "dumi sa dugo", "hugaw sa dugo", "naglilinis ng dugo", "naghinlo sa dugo", "excretory"], "fact": {"tl": "Ang dalawang bato ay parang salaan na naglilinis ng dugo: tinatanggal nito ang mga dumi at sobrang tubig, na nagiging ihi.", "en": "The two kidneys act like filters that clean the blood, removing wastes and extra water, which become urine.", "bis": "Ang duha ka kidni sama sa salaan nga naghinlo sa dugo: kuhaon niini ang mga hugaw ug sobra nga tubig, nga mahimong ihi."}, "source": "AAAS Benchmarks 6C/M3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bladder-stores-urine-g5", "domain": "LIVING_THINGS", "topic": "the bladder", "grades": [5, 6], "terms": ["pantog", "bladder", "tunggo", "ihi", "urine", "ipon ng ihi", "tipigan ang ihi", "imbak", "naiihi", "umihi", "miihi", "mapuno", "mapuno ang pantog", "umiipon ng ihi", "lalagyan ng ihi"], "fact": {"tl": "Ang ihing ginawa ng mga bato ay iniimbak muna sa pantog hanggang sa mapuno ito at kailangan na nating umihi.", "en": "The urine made by the kidneys is stored in the bladder until it fills up and we need to pass it out.", "bis": "Ang ihi nga gihimo sa mga kidni tipigan una sa tunggo hangtod kini mapuno ug kinahanglan na natong moihi."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "skin-sweat-excretion-g5", "domain": "LIVING_THINGS", "topic": "skin removes waste through sweat", "grades": [5, 6], "terms": ["balat", "skin", "panit", "pawis", "sweat", "singot", "asin", "salt", "asin sa lawas", "naglalabas ng init", "release heat", "nagpalamig", "presko", "excretory", "pinakamalaking organ", "kinadak-ang organ"], "fact": {"tl": "Ang balat ang pinakamalaking organ ng katawan, at sa pamamagitan ng pawis ay naglalabas ito ng tubig at asin habang pinapalamig ang katawan.", "en": "The skin is the body's largest organ, and through sweat it releases water and salt while also helping to cool the body.", "bis": "Ang panit mao ang kinadak-ang organ sa lawas, ug pinaagi sa singot mopagawas kini og tubig ug asin samtang nagpabugnaw usab sa lawas."}, "source": "AAAS Benchmarks 6C/M3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "brain-control-center-parts-g7", "domain": "LIVING_THINGS", "topic": "the brain controls the body", "grades": [7, 8], "terms": ["utak", "brain", "utok", "nag-iisip", "thinking", "huna-huna", "nagkokontrol", "control", "kontrolahon", "memorya", "memory", "alaala", "handumanan", "sentro ng kontrol", "sentro sa pagdumala", "nervous system", "sistema ng nerbiyos"], "fact": {"tl": "Ang utak ang sentro ng kontrol ng katawan: dito nagmumula ang pag-iisip, alaala, at damdamin, at dito rin nagpapadala ng utos sa ibang bahagi ng katawan.", "en": "The brain is the body's control center: it is where thinking, memory, and feelings happen, and it sends commands to the rest of the body.", "bis": "Ang utok mao ang sentro sa pagdumala sa lawas: dinhi magsugod ang panghuna-huna, handumanan, ug pagbati, ug gikan dinhi ipadala ang mga sugo ngadto sa ubang bahin sa lawas."}, "source": "AAAS Benchmarks 6C/P3,E4; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "spinal-cord-message-highway-g7", "domain": "LIVING_THINGS", "topic": "spinal cord", "grades": [7, 8], "terms": ["gulugod", "spinal cord", "ugat sa likod", "spinal", "utak", "brain", "utok", "mensahe", "message", "senyales", "signal", "mensahe sa lawas", "agianan sa mensahe", "nerbiyos", "nerves", "nerbiyo", "likod", "backbone"], "fact": {"tl": "Ang gulugod ay isang makapal na bungkos ng nerbiyos sa loob ng buto sa likod na nagdadala ng mga mensahe sa pagitan ng utak at ng buong katawan.", "en": "The spinal cord is a thick bundle of nerves inside the backbone that carries messages between the brain and the rest of the body.", "bis": "Ang spinal cord usa ka baga nga hugpong sa mga nerbiyos sulod sa bukog sa likod nga nagdala sa mga mensahe tali sa utok ug sa tibuok lawas."}, "source": "AAAS Benchmarks 6C/E4,M6; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "nerves-carry-signals-g7", "domain": "LIVING_THINGS", "topic": "nerves carry signals", "grades": [7, 8], "terms": ["nerbiyos", "nerve", "nerves", "nerbiyo", "senyales", "signal", "senyales sa kuryente", "elektrikal", "electric", "kuryente sa lawas", "mensahe", "message", "dala ng senyales", "dala sa senyales", "mabilis", "paspas", "pakiramdam", "bati"], "fact": {"tl": "Ang mga nerbiyos ay parang mabilis na kawad na nagdadala ng mga senyales na de-kuryente papunta at pabalik sa utak, kaya mabilis nating nararamdaman at natutugunan ang mga bagay.", "en": "Nerves are like fast wires that carry electric signals to and from the brain, which is how we feel things and respond so quickly.", "bis": "Ang mga nerbiyos sama sa paspas nga alambre nga nagdala og elektrikong mga senyales padulong ug pabalik sa utok, mao nga dali natong mabati ug matubag ang mga butang."}, "source": "AAAS Benchmarks 6C/H3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "reflex-hot-pull-back-g6", "domain": "LIVING_THINGS", "topic": "reflex action", "grades": [6, 7], "terms": ["reflex", "repleks", "biglang umurong", "pull back", "atras", "kalit", "mainit", "hot", "init", "awtomatik", "automatic", "kusa", "kaugalingon", "gulugod", "spinal cord", "mabilis na tugon", "paspas nga tubag"], "fact": {"tl": "Kapag nahawakan mo ang mainit na bagay, biglang umuurong ang kamay mo bago pa ito maisip — ito ay reflex, isang mabilis na awtomatikong tugon na dinadaan sa gulugod.", "en": "When you touch something hot, your hand jerks back before you even think about it — this is a reflex, a fast automatic response handled by the spinal cord.", "bis": "Kon imong mahikap ang init nga butang, kalit nga moatras ang imong kamot sa wala pa nimo mahunahunai — kini usa ka reflex, paspas ug awtomatik nga tubag nga giagi sa spinal cord."}, "source": "AAAS Benchmarks 6C/M6; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "senses-send-to-brain-g5", "domain": "LIVING_THINGS", "topic": "senses send signals to brain", "grades": [5, 6], "terms": ["pandama", "senses", "sense", "igbalati", "mata", "eyes", "tainga", "ears", "dunggan", "balat", "skin", "panit", "ilong", "nose", "dila", "tongue", "utak", "brain", "senyales", "signal"], "fact": {"tl": "Ang limang pandama — paningin, pandinig, panlasa, pang-amoy, at pang-hipo — ay nagpapadala ng mga senyales sa utak para malaman natin ang nangyayari sa paligid.", "en": "The five senses — sight, hearing, taste, smell, and touch — send signals to the brain so we can know what is happening around us.", "bis": "Ang lima ka igbalati — panan-aw, pandungog, panlasa, panimho, ug paghikap — magpadala og mga senyales sa utok aron mahibaloan nato ang nahitabo sa palibot."}, "source": "AAAS Benchmarks 6C/M6; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "circulatory-carries-oxygen-food-g6", "domain": "LIVING_THINGS", "topic": "blood delivers oxygen and food", "grades": [6, 7], "terms": ["dugo", "blood", "dala ng dugo", "oksiheno", "oxygen", "pagkain", "food", "sustansya", "nutrients", "selula", "cells", "selula sa lawas", "naghahatid", "ihatod", "alis ng dumi", "kuha sa hugaw", "buong katawan", "tibuok lawas"], "fact": {"tl": "Ang dugo ang naghahatid ng oksiheno at sustansya sa bawat selula ng katawan at tumatanggap mula sa kanila ng mga dumi tulad ng carbon dioxide.", "en": "Blood delivers oxygen and nutrients to every cell in the body and collects wastes like carbon dioxide from them.", "bis": "Ang dugo maoy mohatod og oksiheno ug sustansiya ngadto sa matag selula sa lawas ug mokuha gikan kanila sa mga hugaw sama sa carbon dioxide."}, "source": "AAAS Benchmarks 6C/M3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "systems-work-together-run-g6", "domain": "LIVING_THINGS", "topic": "body systems work together", "grades": [6, 7], "terms": ["sistema", "systems", "sistema sa lawas", "magkasama", "work together", "nagtutulungan", "magtinabangay", "tumakbo", "running", "dagan", "pagtakbo", "baga", "lungs", "puso", "heart", "kalamnan", "muscles", "buto", "bones", "sabay-sabay", "dungan"], "fact": {"tl": "Ang mga sistema ng katawan ay nagtutulungan: kapag tumatakbo ka, mas mabilis tumibok ang puso, mas malalim huminga ang baga, at nagtatrabaho ang mga buto at kalamnan nang sabay-sabay.", "en": "The body's systems work together: when you run, the heart beats faster, the lungs breathe deeper, and the bones and muscles move all at the same time.", "bis": "Ang mga sistema sa lawas magtinabangay: kon modagan ka, mas paspas mopitik ang kasingkasing, mas lawom moginhawa ang baga, ug magtrabaho ang mga bukog ug kaunoran nga dungan."}, "source": "AAAS Benchmarks 6C/M3,M6; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tendons-connect-muscle-bone-g7", "domain": "LIVING_THINGS", "topic": "tendons", "grades": [7, 8], "terms": ["litid", "tendon", "tendons", "ugat-ugat", "kusog", "nagkonekta", "connect", "isumpay", "kalamnan sa buto", "muscle to bone", "kaunoran sa bukog", "matibay", "lig-on", "humihila", "birahon", "kamot", "paa"], "fact": {"tl": "Ang litid ay matibay na bahaging nag-uugnay ng kalamnan sa buto, kaya kapag humila ang kalamnan, kumikilos ang buto kasama nito.", "en": "A tendon is a tough cord that connects a muscle to a bone, so when the muscle pulls, the bone moves with it.", "bis": "Ang litid usa ka lig-on nga bahin nga nagsumpay sa kaunoran ngadto sa bukog, mao nga kon mobira ang kaunoran, molihok ang bukog uban niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "windpipe-trachea-air-path-g6", "domain": "LIVING_THINGS", "topic": "windpipe to lungs", "grades": [6, 7], "terms": ["lalamunan", "windpipe", "trachea", "tutunlan", "tutonlan", "agianan sa hangin", "air passage", "baga", "lungs", "lalagusan ng hangin", "daanan ng hangin", "hininga", "hangin", "air", "leeg"], "fact": {"tl": "Ang hanging nilalanghap ay dumadaan sa lalamunan at sa isang tubong tinatawag na windpipe (trachea) na nagdadala nito pababa sa baga.", "en": "The air you breathe in passes through the throat and a tube called the windpipe (trachea) that carries it down into the lungs.", "bis": "Ang hangin nga imong giginhawa moagi sa tutonlan ug sa usa ka tubo nga gitawag og windpipe (trachea) nga modala niini paubos ngadto sa baga."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "blood-clots-platelets-wound-g6", "domain": "LIVING_THINGS", "topic": "blood clotting at a wound", "grades": [6, 7], "terms": ["platelet", "platelets", "namuong dugo", "clot", "nag-clot", "namuo", "sugat", "wound", "samad", "langib", "scab", "panagang", "huminto ang dugo", "hunong sa dugo", "nagsasara ng sugat", "magsira sa samad"], "fact": {"tl": "Kapag nasugatan ka, nagtitipon ang maliliit na platelet sa dugo para magbuo ng tapal na pumipigil sa pagdugo at unti-unting nagiging langib.", "en": "When you get a cut, tiny platelets in the blood gather to form a plug that stops the bleeding and slowly becomes a scab.", "bis": "Kon masamdan ka, magtapok ang gagmayng platelet sa dugo aron magbuo og tabon nga mopugong sa pagdugo ug hinay-hinayng mahimong langib."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "how-eye-works-g5", "domain": "LIVING_THINGS", "topic": "how the eye works", "grades": [5, 6, 7], "terms": ["mata", "eye", "paningin", "panan-aw", "liwanag", "kahayag", "light", "lens", "retina", "larawan", "imahe", "image", "utak", "utok", "brain", "pupil", "balintataw"], "fact": {"tl": "Pumapasok ang liwanag sa mata sa pamamagitan ng balintataw (pupil), hinuhubog ng lens, at tumatama sa retina sa likod ng mata. Pinapadala ng retina ang signal sa utak sa pamamagitan ng optic nerve, at doon binubuo ang nakikita nating larawan.", "en": "Light enters the eye through the pupil, is focused by the lens, and lands on the retina at the back of the eye. The retina sends a signal to the brain through the optic nerve, where the picture we see is formed.", "bis": "Mosulod ang kahayag sa mata pinaagi sa pupil, ipunting sa lens, ug motugpa sa retina sa luyo sa mata. Ipadala sa retina ang signal ngadto sa utok pinaagi sa optic nerve, ug didto mabuo ang hulagway nga atong makita."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.6 (senses)", "generator": "claude-workflow", "reviewed": false},
  {"id": "how-ear-works-g5", "domain": "LIVING_THINGS", "topic": "how the ear works", "grades": [5, 6, 7], "terms": ["tainga", "dalunggan", "ear", "tunog", "tingog", "sound", "pandinig", "pandungog", "hearing", "eardrum", "tympanic", "vibration", "panginig", "pag-uyog", "cochlea", "utak", "utok"], "fact": {"tl": "Pumapasok ang tunog sa tainga at pinapanginig nito ang eardrum (tympanic membrane). Ipinapasa ang panginig sa maliliit na buto at sa cochlea na hugis-kuhol, na nagbabago ng tunog sa mga signal na ipinapadala sa utak.", "en": "Sound enters the ear and makes the eardrum vibrate. The vibration passes through tiny bones to the snail-shaped cochlea, which turns the sound into signals sent to the brain.", "bis": "Mosulod ang tingog sa dalunggan ug pakurogon niini ang eardrum. Ipasa ang pagkurog sa gagmayng bukog ngadto sa cochlea nga porma og kuhol, nga mobalhin sa tingog ngadto sa mga signal nga ipadala sa utok."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.6 (senses)", "generator": "claude-workflow", "reviewed": false},
  {"id": "taste-buds-five-tastes-g4", "domain": "LIVING_THINGS", "topic": "taste buds and basic tastes", "grades": [4, 5, 6], "terms": ["dila", "tongue", "panlasa", "lasa", "taste", "taste buds", "matam-is", "tam-is", "sweet", "maasim", "aslom", "sour", "maalat", "parat", "salty", "mapait", "pait", "bitter", "umami", "savory"], "fact": {"tl": "May libu-libong maliliit na taste buds ang dila na nakakaramdam ng lasa. Limang pangunahing lasa ang nararamdaman nila: matamis, maasim, maalat, mapait, at umami (malinamnam).", "en": "The tongue has thousands of tiny taste buds that sense flavor. They detect five basic tastes: sweet, sour, salty, bitter, and umami (savory).", "bis": "Ang dila adunay liboan ka gagmayng taste buds nga makabati sa lami. Lima ka nag-unang lami ang ilang mabati: tam-is, aslom, parat, pait, ug umami (lami nga savory)."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "smell-and-taste-work-together-g4", "domain": "LIVING_THINGS", "topic": "smell and taste work together", "grades": [4, 5, 6], "terms": ["amoy", "panimaho", "smell", "lasa", "panlasa", "taste", "sipon", "colds", "barado", "ilong", "nose", "flavor", "matabang", "walang lasa", "sabay"], "fact": {"tl": "Magkatuwang ang pang-amoy at panlasa para malaman natin ang tunay na lasa ng pagkain. Kaya kapag barado ang ilong dahil sa sipon, parang matabang o walang lasa ang pagkain.", "en": "Smell and taste work together to give food its full flavor. That is why food tastes bland or flavorless when your nose is blocked by a cold.", "bis": "Ang panimaho ug panlasa magtinabangay aron mahibal-an nato ang tinuod nga lami sa pagkaon. Mao nga kon barado ang ilong tungod sa sip-on, daw walay lami ang pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "skin-touch-receptors-g4", "domain": "LIVING_THINGS", "topic": "how skin feels touch", "grades": [4, 5, 6], "terms": ["balat", "panit", "skin", "hipo", "paghikap", "touch", "pakiramdam", "bati", "feel", "receptors", "init", "kainit", "hot", "lamig", "kabugnaw", "cold", "sakit", "kasakit", "pain", "presyon"], "fact": {"tl": "May milyon-milyong maliliit na sensor (receptors) ang balat na nakakaramdam ng hipo, presyon, init, lamig, at sakit. Ipinapadala nila ang mga signal sa utak sa pamamagitan ng nerves para makaramdam tayo.", "en": "The skin has millions of tiny sensors that feel touch, pressure, heat, cold, and pain. They send signals to the brain through nerves so we can feel.", "bis": "Ang panit adunay milyon-milyon ka gagmayng sensor nga makabati sa hikap, presyon, init, bugnaw, ug sakit. Ipadala nila ang mga signal ngadto sa utok pinaagi sa nerves aron makabati kita."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.6", "generator": "claude-workflow", "reviewed": false},
  {"id": "neurons-nerve-cells-g7", "domain": "LIVING_THINGS", "topic": "neurons carry signals", "grades": [7, 8, 9], "terms": ["neuron", "nerve cell", "selula ng nerbiyo", "selula sa nerbiyo", "nerves", "signal", "mensahe", "electric", "kuryente", "elektrisidad", "bilis", "kusog", "utak", "utok", "katawan", "lawas"], "fact": {"tl": "Ang neuron ay isang nerve cell na nagdadala ng mga mensahe bilang maliliit na electrical signal. Ang bilyon-bilyong neuron na magkakaugnay ang bumubuo sa utak at nerves, at sobrang bilis nilang magpadala ng signal sa buong katawan.", "en": "A neuron is a nerve cell that carries messages as tiny electrical signals. Billions of connected neurons make up the brain and nerves, and they pass signals through the body very fast.", "bis": "Ang neuron usa ka nerve cell nga magdala og mga mensahe isip gagmayng electrical signal. Bilyon-bilyon ka nagkadugtong nga neuron ang naghimo sa utok ug nerves, ug paspas kaayo silang mopadala og signal sa tibuok lawas."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.6 (6C/H3)", "generator": "claude-workflow", "reviewed": false},
  {"id": "spinal-cord-g6", "domain": "LIVING_THINGS", "topic": "the spinal cord", "grades": [6, 7, 8], "terms": ["spinal cord", "gulugod", "utok sa likod", "backbone", "buto sa likod", "nerves", "utak", "utok", "brain", "mensahe", "signal", "katawan", "lawas", "daluyan", "highway"], "fact": {"tl": "Ang spinal cord ay makapal na bigkis ng nerves sa loob ng gulugod na nag-uugnay sa utak at sa katawan. Dumadaan dito ang mga mensahe papunta at pabalik sa utak, kaya iniingatan ito ng buto ng gulugod.", "en": "The spinal cord is a thick bundle of nerves inside the backbone that connects the brain to the body. Messages travel along it to and from the brain, so it is protected by the bones of the spine.", "bis": "Ang spinal cord usa ka baga nga bundle sa nerves sulod sa gulugod nga nagdugtong sa utok ngadto sa lawas. Moagi dinhi ang mga mensahe paingon ug pabalik sa utok, mao nga gipanalipdan kini sa mga bukog sa gulugod."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.6", "generator": "claude-workflow", "reviewed": false},
  {"id": "reflex-hot-stove-g5", "domain": "LIVING_THINGS", "topic": "reflex pulls hand from heat", "grades": [5, 6, 7], "terms": ["reflex", "biglang", "kalit", "mainit", "init", "hot", "kamay", "kamot", "hand", "spinal cord", "utak", "utok", "mabilis", "paspas", "fast", "awtomatik", "kusog", "hawak"], "fact": {"tl": "Kapag nahawakan natin ang isang mainit na bagay, agad nating naiiwas ang kamay bago pa man tayo makaisip — ito ay reflex. Direkta itong dinadaan sa spinal cord para mas mabilis kaysa kung dadaan pa sa utak.", "en": "When we touch something hot, we pull our hand away before we even think — this is a reflex. It is handled directly by the spinal cord so it is faster than going all the way to the brain.", "bis": "Kon makahikap ta og init nga butang, dali nato nga ibira ang atong kamot sa wala pa ta makahunahuna — reflex kini. Direkta kining moagi sa spinal cord aron mas paspas kay sa moagi pa sa utok."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.6 (6C/P2)", "generator": "claude-workflow", "reviewed": false},
  {"id": "knee-jerk-reflex-g5", "domain": "LIVING_THINGS", "topic": "knee-jerk reflex", "grades": [5, 6, 7], "terms": ["tuhod", "knee", "reflex", "tama", "tap", "binti", "paa", "tiil", "leg", "kick", "sipa", "kusog", "doktor", "awtomatik", "biglang"], "fact": {"tl": "Kapag bahagyang tinamaan ng doktor ang ilalim ng tuhod, biglang tumatalbog pataas ang binti. Ito ay isang reflex na sumusubok kung maayos ang nerves at hindi natin sinasadya.", "en": "When a doctor lightly taps just below the knee, the lower leg kicks up by itself. This is a reflex that checks if the nerves are working, and we do not control it.", "bis": "Kon hayon-hayon nga tukon sa doktor ang ubos sa tuhod, kalit nga molugbat pataas ang batiis. Reflex kini nga magsusi kon maayo ang nerves ug dili nato kini tinuyo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "brain-parts-cerebrum-g7", "domain": "LIVING_THINGS", "topic": "main parts of the brain", "grades": [7, 8, 9], "terms": ["utak", "utok", "brain", "cerebrum", "pag-iisip", "panghunahuna", "thinking", "cerebellum", "balanse", "kilos", "lihok", "movement", "balance", "brainstem", "tibok", "paghinga", "ginhawa", "puso"], "fact": {"tl": "May tatlong pangunahing bahagi ang utak: ang cerebrum para sa pag-iisip at pakiramdam, ang cerebellum para sa balanse at maayos na paggalaw, at ang brainstem na kumokontrol sa paghinga at tibok ng puso.", "en": "The brain has three main parts: the cerebrum for thinking and feeling, the cerebellum for balance and smooth movement, and the brainstem that controls breathing and heartbeat.", "bis": "Ang utok adunay tulo ka nag-unang bahin: ang cerebrum para sa paghunahuna ug pagbati, ang cerebellum para sa balanse ug hapsay nga paglihok, ug ang brainstem nga magkontrol sa pagginhawa ug pitik sa kasingkasing."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.6 (6C/P3)", "generator": "claude-workflow", "reviewed": false},
  {"id": "brain-controls-without-thinking-g6", "domain": "LIVING_THINGS", "topic": "brain controls body automatically", "grades": [6, 7, 8], "terms": ["utak", "utok", "brain", "awtomatik", "kusog", "hindi sinasadya", "tibok", "pitik", "heartbeat", "paghinga", "ginhawa", "breathing", "panunaw", "hilab", "digestion", "kontrol", "sentro"], "fact": {"tl": "Hindi lang pag-iisip ang ginagawa ng utak — kinokontrol din nito ang tibok ng puso, paghinga, at panunaw kahit hindi natin iniisip. Patuloy itong gumagana kahit habang tayo ay natutulog.", "en": "The brain does more than think — it also controls our heartbeat, breathing, and digestion without us thinking about it. It keeps working even while we sleep.", "bis": "Dili lang paghunahuna ang buhaton sa utok — magkontrol usab kini sa pitik sa kasingkasing, pagginhawa, ug paghilis bisan dili nato hunahunaon. Magpadayon kini paglihok bisan samtang natulog ta."}, "source": "AAAS BSL Ch.6 (6C/P3, 6C/E4)", "generator": "claude-workflow", "reviewed": false},
  {"id": "brain-energy-use-g6", "domain": "LIVING_THINGS", "topic": "the brain uses lots of energy", "grades": [6, 7, 8], "terms": ["utak", "utok", "brain", "enerhiya", "kusog", "energy", "pagkain", "sustansya", "glucose", "asukal", "oxygen", "hangin", "dugo", "trabaho", "abala", "trabahador"], "fact": {"tl": "Maliit lang ang utak kumpara sa buong katawan, ngunit napakarami nitong ginagamit na enerhiya — humigit-kumulang ikalima ng enerhiya ng katawan. Kailangan nito ng tuloy-tuloy na suplay ng oxygen at glucose mula sa dugo.", "en": "The brain is small compared to the whole body, yet it uses a large share of the body's energy — about a fifth. It needs a constant supply of oxygen and glucose from the blood.", "bis": "Gamay ra ang utok kumpara sa tibuok lawas, apan daghan kaayo kini og gamiton nga kusog — mga ikalima sa kusog sa lawas. Nagkinahanglan kini og kanunay nga suplay sa oxygen ug glucose gikan sa dugo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "memory-in-brain-g6", "domain": "LIVING_THINGS", "topic": "how memory works", "grades": [6, 7, 8], "terms": ["alaala", "memorya", "panumduman", "memory", "naaalala", "mahinumdom", "remember", "utak", "utok", "brain", "natutunan", "nakat-unan", "learn", "koneksyon", "neuron", "ulit-ulit", "balik-balik"], "fact": {"tl": "Iniimbak natin ang mga alaala kapag bumubuo ng bagong koneksyon ang mga neuron sa utak. Lumalakas ang koneksyon kapag inuulit-ulit natin ang isang bagay, kaya mas madaling matandaan ang madalas nating ginagawa.", "en": "We store memories when neurons in the brain form new connections. The connections grow stronger when we repeat something, which is why things we practice are easier to remember.", "bis": "Tipigan nato ang mga panumduman kon ang mga neuron sa utok maghimo og bag-ong koneksyon. Molig-on ang koneksyon kon balik-balikon nato ang usa ka butang, mao nga mas sayon hinumduman ang kanunay natong buhaton."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.6 (6C/M6)", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-we-dream-g4", "domain": "LIVING_THINGS", "topic": "why we dream", "grades": [4, 5, 6], "terms": ["panaginip", "damgo", "dream", "tulog", "katulog", "sleep", "utak", "utok", "brain", "alaala", "panumduman", "memory", "gabi", "imahe", "larawan", "ayos", "pahinga"], "fact": {"tl": "Nananaginip tayo habang natutulog dahil patuloy na aktibo ang utak. Inaayos at pinagsasama-sama nito ang mga alaala at damdamin, na lumilikha ng mga larawan at kuwento sa ating isip.", "en": "We dream while sleeping because the brain stays active. It sorts and connects memories and feelings, creating pictures and stories in our mind.", "bis": "Magdamgo ta samtang natulog tungod kay nagpadayon nga aktibo ang utok. Iayos ug iisa niini ang mga panumduman ug pagbati, nga maghimo og mga hulagway ug istorya sa atong hunahuna."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "how-much-sleep-kids-g3", "domain": "LIVING_THINGS", "topic": "how much sleep children need", "grades": [3, 4, 5], "terms": ["tulog", "katulog", "sleep", "oras", "takna", "hours", "bata", "kabataan", "child", "kids", "pahinga", "pahulay", "rest", "lumaki", "motubo", "grow", "utak", "kalusugan"], "fact": {"tl": "Kailangan ng mga batang nasa paaralan ng mga 9 hanggang 12 oras na tulog gabi-gabi. Ang sapat na tulog ay tumutulong sa kanila na lumaki, mag-aral nang mabuti, at manatiling malusog.", "en": "School-age children need about 9 to 12 hours of sleep each night. Enough sleep helps them grow, learn well, and stay healthy.", "bis": "Ang mga batang nag-eskwela nagkinahanglan og mga 9 ngadto 12 ka oras nga tulog matag gabii. Ang igong tulog motabang nila nga motubo, makakat-on og maayo, ug magpabilin nga himsog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "balance-inner-ear-g5", "domain": "LIVING_THINGS", "topic": "inner ear and balance", "grades": [5, 6, 7], "terms": ["balanse", "balance", "tainga", "dalunggan", "inner ear", "likido", "tubig", "fluid", "utak", "utok", "tayo", "tindog", "tumayo", "hindi matumba", "tirik", "posisyon"], "fact": {"tl": "Sa loob ng bawat tainga ay may maliliit na tubo na puno ng likido na tumutulong sa atin na makaramdam ng balanse. Sinasabi nila sa utak kung tayo ay nakatuwid, nakahilig, o gumagalaw, para hindi tayo matumba.", "en": "Inside each ear are tiny tubes filled with fluid that help us sense balance. They tell the brain whether we are upright, tilted, or moving, so we do not fall over.", "bis": "Sulod sa matag dalunggan adunay gagmayng tubo nga puno og likido nga motabang nato sa pagbati sa balanse. Sultihan nila ang utok kon nagtindog ba ta, nagharag, o naglihok, aron dili ta matumba."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-ears-pop-g5", "domain": "LIVING_THINGS", "topic": "why ears pop", "grades": [5, 6, 7], "terms": ["tainga", "dalunggan", "ear", "pop", "barado", "presyon", "pressure", "eroplano", "ayroplano", "airplane", "bundok", "bukid", "taas", "altitude", "hangin", "eardrum", "lunok", "tunaw"], "fact": {"tl": "Nagpo-pop ang ating tainga kapag mabilis na nagbabago ang presyon ng hangin, gaya sa eroplano o pag-akyat sa bundok. Ang pag-pop ay ang pagpantay ng presyon sa magkabilang gilid ng eardrum.", "en": "Our ears pop when air pressure changes quickly, such as on an airplane or going up a mountain. The pop is the pressure becoming equal on both sides of the eardrum.", "bis": "Mopop ang atong dalunggan kon paspas nga mausab ang presyon sa hangin, sama sa eroplano o pagsaka sa bukid. Ang pop mao ang pagpatas sa presyon sa duha ka kilid sa eardrum."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "night-vision-rods-cones-g6", "domain": "LIVING_THINGS", "topic": "seeing in dim light", "grades": [6, 7, 8], "terms": ["dilim", "kangitngit", "dark", "madilim", "gabi", "see", "makita", "kulay", "kolor", "color", "retina", "mata", "rods", "cones", "abo", "grey", "liwanag", "kahayag", "sensor"], "fact": {"tl": "May dalawang uri ng sensor sa retina: ang cones na nakakakita ng kulay sa maliwanag, at ang rods na gumagana sa dilim. Dahil ang rods ay hindi nakakakita ng kulay, parang abo-abo ang mga bagay sa madilim.", "en": "The retina has two kinds of sensors: cones that see color in bright light, and rods that work in the dark. Because rods cannot see color, things look grey in dim light.", "bis": "Ang retina adunay duha ka matang sa sensor: ang cones nga makakita og kolor sa hayag, ug ang rods nga molihok sa kangitngit. Tungod kay ang rods dili makakita og kolor, daw abuhon ang mga butang sa ngitngit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-hiccups-g4", "domain": "LIVING_THINGS", "topic": "why we get hiccups", "grades": [4, 5, 6], "terms": ["sinok", "sid-ok", "hiccup", "hiccups", "diaphragm", "kalamnan", "kaunoran", "muscle", "paghinga", "ginhawa", "biglang", "kalit", "kumokontra", "spasm", "tunog", "lalamunan"], "fact": {"tl": "Nagkakaroon tayo ng sinok kapag biglang kumikitil ang diaphragm, ang kalamnan sa ilalim ng baga na ginagamit sa paghinga. Ang biglang paghigop ng hangin ay nagsasara sa lalamunan at gumagawa ng tunog na 'ik'.", "en": "We get hiccups when the diaphragm, the muscle under the lungs used for breathing, suddenly twitches. The quick gulp of air snaps the throat shut and makes the 'hic' sound.", "bis": "Magsinok ta kon kalit nga mokitil ang diaphragm, ang kaunoran sa ilawom sa baga nga gamiton sa pagginhawa. Ang kalit nga pagsuyop og hangin mosira sa tutunlan ug mohimo sa tingog nga 'ik'."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pain-is-a-warning-g4", "domain": "LIVING_THINGS", "topic": "pain protects the body", "grades": [4, 5, 6], "terms": ["sakit", "kasakit", "pain", "masakit", "babala", "pasidaan", "warning", "nerves", "utak", "utok", "proteksyon", "panalipod", "danger", "peligro", "hindi mawala", "iwas", "alis"], "fact": {"tl": "Ang sakit ay isang babala mula sa katawan. Pinapadala ng nerves sa balat ang signal sa utak para sabihin na may sumasakit o nasaktan, kaya naiiwas natin agad ang sarili sa pinsala.", "en": "Pain is a warning from the body. Nerves in the skin send a signal to the brain to say something hurts or is damaged, so we can quickly pull away from harm.", "bis": "Ang sakit usa ka pasidaan gikan sa lawas. Ipadala sa nerves sa panit ang signal ngadto sa utok aron isulti nga adunay sakit o naangol, aron makalikay dayon ta sa kadaot."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.6 (6C/P2)", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-hot-cold-feel-g5", "domain": "LIVING_THINGS", "topic": "feeling hot and cold", "grades": [5, 6, 7], "terms": ["init", "kainit", "hot", "lamig", "kabugnaw", "cold", "balat", "panit", "skin", "sensor", "receptor", "temperatura", "kainit-lamig", "nerves", "utak", "ramdam", "bati"], "fact": {"tl": "May magkahiwalay na sensor sa balat na nakakaramdam ng init at lamig. Ipinapadala nila ang signal sa utak, kaya naiiwas natin ang sobrang init na makakasunog o naghahanap tayo ng init kapag nilalamig.", "en": "The skin has separate sensors for warmth and cold. They send signals to the brain, so we pull away from heat that could burn us or seek warmth when we feel cold.", "bis": "Ang panit adunay lahi nga sensor para sa init ug bugnaw. Ipadala nila ang signal ngadto sa utok, mao nga molikay ta sa init nga makapaso o mangita ta og init kon tugnawon."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.6", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-we-itch-scratch-g3", "domain": "LIVING_THINGS", "topic": "why we itch", "grades": [3, 4, 5], "terms": ["kati", "katol", "itch", "kamot", "kalot", "scratch", "balat", "panit", "skin", "nerves", "lamok", "lamuk", "mosquito", "alikabok", "babala", "ramdam", "buhok"], "fact": {"tl": "Nangangati tayo kapag may bagay na pumupukaw sa balat, gaya ng kagat ng lamok, alikabok, o buhok. Sinasabi ng nerves sa utak na may nakakulit sa balat, kaya gusto nating kalutin para alisin ito.", "en": "We itch when something irritates the skin, like a mosquito bite, dust, or a hair. Nerves tell the brain something is bothering the skin, so we want to scratch it away.", "bis": "Mangatol ta kon adunay butang nga makapainis sa panit, sama sa paak sa lamok, abog, o buhok. Sultihan sa nerves ang utok nga adunay nakasamok sa panit, mao nga gusto natong kalkagon kini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "five-senses-share-brain-g4", "domain": "LIVING_THINGS", "topic": "senses work with the brain", "grades": [4, 5, 6], "terms": ["pandama", "igbalati", "senses", "utak", "utok", "brain", "magkasama", "magkatuwang", "tulong", "nerves", "signal", "intindi", "sabay", "paligid", "kapaligiran", "danger", "peligro", "kilos"], "fact": {"tl": "Walang nakakakita, nakakarinig, o nakakaamoy ang mga pandama mismo — ipinapadala lang nila ang signal sa utak. Ang utak ang umiintindi sa lahat ng signal nang sabay-sabay para maunawaan natin ang nangyayari sa paligid.", "en": "The senses do not actually see, hear, or smell by themselves — they only send signals to the brain. The brain makes sense of all the signals together so we can understand what is happening around us.", "bis": "Ang mga igbalati dili gyud makakita, makadungog, o makasimhot sa ilang kaugalingon — ipadala lang nila ang signal ngadto sa utok. Ang utok maoy mosabot sa tanang signal nga dungan aron masabtan nato ang nahitabo sa palibot."}, "source": "AAAS BSL Ch.6 (6C/M6, 6D/P1)", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-cant-tickle-self-g4", "domain": "LIVING_THINGS", "topic": "why you can't tickle yourself", "grades": [4, 5, 6], "terms": ["kiliti", "kilitiin", "tickle", "gigil", "sarili", "self", "utak", "utok", "brain", "alam na", "inaasahan", "predict", "gulat", "sorpresa", "surprise", "tawa", "katawa"], "fact": {"tl": "Hindi natin makikiliti ang sarili natin dahil alam na ng utak kung ano ang gagawin ng ating sariling kamay. Dahil inaasahan na ito ng utak, wala itong elemento ng sorpresa na nagdudulot ng kiliti.", "en": "We can't tickle ourselves because the brain already knows what our own hand will do. Since the brain expects it, there is no element of surprise to make it ticklish.", "bis": "Dili nato makiliti ang atong kaugalingon tungod kay nahibalo na ang utok kon unsay buhaton sa atong kaugalingong kamot. Tungod kay gipaabot na kini sa utok, wala'y elemento sa sorpresa nga maghimo niining makiliti."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "voluntary-involuntary-muscles-g6", "domain": "LIVING_THINGS", "topic": "the brain and movement", "grades": [6, 7, 8], "terms": ["utak", "utok", "brain", "kalamnan", "kaunoran", "muscle", "kilos", "lihok", "movement", "sinasadya", "tinuyo", "voluntary", "hindi sinasadya", "automatic", "tibok", "paglakad", "lakaw", "kamay"], "fact": {"tl": "May mga kilos na sinasadya natin, gaya ng paglakad o pagkaway, na inuutusan ng utak. May mga kilos namang awtomatik, gaya ng tibok ng puso, na hindi natin kayang pigilan o ipag-utos.", "en": "Some movements are ones we choose, like walking or waving, which the brain commands. Other movements are automatic, like the heartbeat, which we cannot start or stop on purpose.", "bis": "Adunay mga lihok nga atong tinuyo, sama sa paglakaw o pagwarawara, nga sugoon sa utok. Adunay mga lihok nga awtomatiko, sama sa pitik sa kasingkasing, nga dili nato mapugngan o masugo."}, "source": "AAAS BSL Ch.6 (6C/P3)", "generator": "claude-workflow", "reviewed": false},
  {"id": "nose-warms-cleans-air-g4", "domain": "LIVING_THINGS", "topic": "the nose cleans air", "grades": [4, 5, 6], "terms": ["ilong", "nose", "hangin", "air", "paghinga", "ginhawa", "amoy", "panimaho", "smell", "buhok", "balahibo", "uhog", "sip-on", "alikabok", "dust", "salaan", "filter", "init"], "fact": {"tl": "Bukod sa pang-amoy, nililinis at pinapainit ng ilong ang hangin bago ito pumunta sa baga. Hinuhuli ng maliliit na buhok at malagkit na uhog ang alikabok at mikrobyo para hindi tayo magkasakit.", "en": "Besides smelling, the nose cleans and warms the air before it reaches the lungs. Tiny hairs and sticky mucus trap dust and germs so we don't get sick.", "bis": "Gawas sa pagsimhot, limpyohan ug initon sa ilong ang hangin sa dili pa kini moabot sa baga. Dakpon sa gagmayng balhibo ug pilit nga sip-on ang abog ug mikrobyo aron dili ta magsakit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "brain-protected-skull-g4", "domain": "LIVING_THINGS", "topic": "the skull protects the brain", "grades": [4, 5, 6], "terms": ["utak", "utok", "brain", "bungo", "bagol", "skull", "buto", "bukog", "bone", "proteksyon", "panalipod", "protect", "matigas", "gahi", "helmet", "ulo", "ligtas", "pinsala"], "fact": {"tl": "Napakahalaga ng utak kaya pinrotektahan ito ng matigas na bungo (skull) na buto. Tinitiyak nito na hindi madaling masaktan ang malambot na utak, kaya dapat ding magsuot ng helmet kapag nagbibisikleta.", "en": "The brain is so important that it is protected by the hard bone of the skull. The skull keeps the soft brain from getting hurt easily, which is also why we wear a helmet when biking.", "bis": "Importante kaayo ang utok mao nga gipanalipdan kini sa gahi nga bukog sa bagol. Ang bagol mosiguro nga dili dali maangol ang humok nga utok, mao usab nga magsul-ob tag helmet kon magbisikleta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "animals-better-senses-g5", "domain": "LIVING_THINGS", "topic": "animals with sharper senses", "grades": [5, 6, 7], "terms": ["hayop", "mananap", "animals", "pandama", "igbalati", "senses", "aso", "iro", "dog", "amoy", "panimaho", "smell", "agila", "eagle", "mata", "paningin", "panan-aw", "paniki", "kabog", "bat", "matalas"], "fact": {"tl": "May mga hayop na mas matalas ang ilang pandama kaysa sa tao. Ang aso ay may napakahusay na pang-amoy, ang agila ay napakatalas ng paningin, at ang paniki ay gumagamit ng tunog para 'makakita' sa dilim.", "en": "Some animals have sharper senses than humans. Dogs have an excellent sense of smell, eagles have very sharp eyesight, and bats use sound to 'see' in the dark.", "bis": "Adunay mga mananap nga mas hait ang ilang igbalati kay sa tawo. Ang iro maayo kaayo og panimaho, ang agila hait kaayo og panan-aw, ug ang kabog mogamit og tingog aron 'makakita' sa kangitngit."}, "source": "AAAS BSL Ch.6 (6D/M1); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "brain-two-sides-g6", "domain": "LIVING_THINGS", "topic": "the brain has two sides", "grades": [6, 7, 8], "terms": ["utak", "utok", "brain", "kaliwa", "wala", "left", "kanan", "tuo", "right", "magkabila", "duha ka kilid", "hemisphere", "katawan", "lawas", "kontrol", "krus", "baligtad"], "fact": {"tl": "Hati ang utak sa dalawang panig, kaliwa at kanan. Kakaibang bagay: ang kaliwang panig ng utak ang kumokontrol sa kanang bahagi ng katawan, at ang kanang panig naman ang sa kaliwa.", "en": "The brain is split into two halves, left and right. Curiously, the left side of the brain controls the right side of the body, and the right side controls the left.", "bis": "Ang utok nabahin sa duha ka kilid, wala ug tuo. Katingad-an: ang walang kilid sa utok magkontrol sa tuong bahin sa lawas, ug ang tuong kilid magkontrol sa wala."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "photosynthesis-makes-oxygen-g4", "domain": "LIVING_THINGS", "topic": "photosynthesis releases oxygen", "grades": [4, 5, 6], "terms": ["oxygen", "oksiheno", "hangin", "hininga", "photosynthesis", "potosintesis", "naglalabas", "nagbubuga", "halaman", "tanom", "dahon", "carbon dioxide", "huminga", "ginaginhawa"], "fact": {"tl": "Habang gumagawa ng pagkain sa pamamagitan ng potosintesis, naglalabas ang halaman ng oksiheno na siyang hinihinga natin.", "en": "While making food through photosynthesis, a plant releases oxygen, the gas that we breathe.", "bis": "Samtang naghimo ug pagkaon pinaagi sa potosintesis, ang tanom nagabuga ug oksiheno nga maoy atong ginaginhawa."}, "source": "NRC LS1.C; AAAS ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "chlorophyll-captures-light-g6", "domain": "LIVING_THINGS", "topic": "chlorophyll captures sunlight", "grades": [6, 7, 8], "terms": ["chlorophyll", "kloropil", "berde", "lunhaw", "berdeng sustansya", "luntian", "dahon", "sumisipsip ng liwanag", "nagsuyop", "araw", "adlaw", "potosintesis", "enerhiya"], "fact": {"tl": "Ang chlorophyll ang berdeng sustansya sa dahon na sumisipsip ng enerhiya mula sa araw para magamit sa potosintesis.", "en": "Chlorophyll is the green substance in leaves that absorbs energy from sunlight for use in photosynthesis.", "bis": "Ang kloropil mao ang lunhaw nga sustansya sa dahon nga nagasuyop sa enerhiya gikan sa adlaw aron gamiton sa potosintesis."}, "source": "AAAS ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "leaves-take-in-co2-g5", "domain": "LIVING_THINGS", "topic": "leaves take in carbon dioxide", "grades": [5, 6, 7], "terms": ["carbon dioxide", "dahon", "butas", "lungag", "stomata", "estomata", "sumisipsip ng hangin", "nagsuyop sa hangin", "hangin", "potosintesis", "huminga"], "fact": {"tl": "Sumisipsip ang dahon ng carbon dioxide mula sa hangin sa pamamagitan ng maliliit na butas na tinatawag na stomata.", "en": "Leaves take in carbon dioxide from the air through tiny pores called stomata.", "bis": "Ang dahon nagasuyop ug carbon dioxide gikan sa hangin pinaagi sa gagmay nga mga lungag nga gitawag ug stomata."}, "source": "AAAS ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "roots-absorb-water-g3", "domain": "LIVING_THINGS", "topic": "roots absorb water", "grades": [3, 4], "terms": ["ugat", "gamot", "tubig", "sumisipsip ng tubig", "nagsuyop sa tubig", "lupa", "yuta", "sustansya", "halaman", "tanom", "mabuhay", "mabuhi"], "fact": {"tl": "Ang ugat ay sumisipsip ng tubig at sustansya mula sa lupa para mabuhay ang halaman.", "en": "Roots absorb water and nutrients from the soil so the plant can live.", "bis": "Ang gamot nagasuyop ug tubig ug sustansya gikan sa yuta aron mabuhi ang tanom."}, "source": "NRC LS1.A; DepEd G3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "roots-anchor-plant-g4", "domain": "LIVING_THINGS", "topic": "roots anchor the plant", "grades": [3, 4, 5], "terms": ["ugat", "gamot", "hinahawakan", "naggunit", "hindi matumba", "dili matumba", "hangin", "bagyo", "lupa", "yuta", "halaman", "tanom"], "fact": {"tl": "Bukod sa pagsipsip ng tubig, hinahawakan ng ugat ang halaman sa lupa para hindi ito matumba sa hangin.", "en": "Besides taking in water, roots hold the plant in the soil so it will not be knocked over by the wind.", "bis": "Gawas sa pagsuyop ug tubig, ang gamot naggunit sa tanom sa yuta aron dili kini matumba sa hangin."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "stem-transports-water-g4", "domain": "LIVING_THINGS", "topic": "stem carries water and food", "grades": [4, 5, 6], "terms": ["tangkay", "puno", "punoan", "lawas sa tanom", "nagdadala ng tubig", "nagdala sa tubig", "tubig", "pagkain", "pagkaon", "dahon", "ugat", "gamot"], "fact": {"tl": "Ang tangkay o puno ang nagdadala ng tubig mula sa ugat papunta sa dahon, at ng pagkain pabalik sa ibang bahagi ng halaman.", "en": "The stem carries water from the roots up to the leaves, and food back down to the rest of the plant.", "bis": "Ang punoan o lawas sa tanom maoy nagdala sa tubig gikan sa gamot paingon sa dahon, ug sa pagkaon pabalik ngadto sa ubang bahin sa tanom."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "leaf-is-food-factory-g4", "domain": "LIVING_THINGS", "topic": "leaf makes the plant's food", "grades": [4, 5], "terms": ["dahon", "gumagawa ng pagkain", "naghimo sa pagkaon", "kusina", "potosintesis", "araw", "adlaw", "berde", "lunhaw", "halaman", "tanom"], "fact": {"tl": "Ang dahon ang parang kusina ng halaman kung saan ginagawa ang pagkain nito sa pamamagitan ng potosintesis.", "en": "The leaf is like the plant's kitchen, where its food is made through photosynthesis.", "bis": "Ang dahon mao ang sama sa kusina sa tanom, diin ginahimo ang pagkaon niini pinaagi sa potosintesis."}, "source": "AAAS ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "plants-make-sugar-food-g6", "domain": "LIVING_THINGS", "topic": "photosynthesis makes sugar", "grades": [6, 7, 8], "terms": ["asukal", "glucose", "glukosa", "pagkain ng halaman", "tubig", "carbon dioxide", "potosintesis", "enerhiya", "sustansya", "halaman", "tanom"], "fact": {"tl": "Sa potosintesis, pinagsasama ng halaman ang tubig at carbon dioxide para gumawa ng asukal (glucose) na siyang pagkain at enerhiya nito.", "en": "In photosynthesis, a plant combines water and carbon dioxide to make sugar (glucose), which is its food and energy.", "bis": "Sa potosintesis, gisagol sa tanom ang tubig ug carbon dioxide aron maghimo ug asukal (glukosa) nga maoy pagkaon ug enerhiya niini."}, "source": "AAAS ch.5; NRC LS1.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "plants-need-sunlight-water-air-g3", "domain": "LIVING_THINGS", "topic": "what plants need to grow", "grades": [3, 4], "terms": ["kailangan ng halaman", "gikinahanglan sa tanom", "araw", "adlaw", "tubig", "hangin", "lupa", "yuta", "lumaki", "motubo", "sikat ng araw", "silaw"], "fact": {"tl": "Para lumaki ang halaman, kailangan nito ng sikat ng araw, tubig, hangin, at lupa na may sustansya.", "en": "To grow, a plant needs sunlight, water, air, and soil with nutrients.", "bis": "Aron motubo, ang tanom nagkinahanglan ug silaw sa adlaw, tubig, hangin, ug yuta nga adunay sustansya."}, "source": "NRC LS1.C; DepEd G3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "seed-has-baby-plant-g3", "domain": "LIVING_THINGS", "topic": "a seed holds a baby plant", "grades": [3, 4], "terms": ["buto", "binhi", "liso", "sanggol na halaman", "gamay nga tanom", "loob ng buto", "sulod sa liso", "pagkain", "tutubo", "moturok", "halaman", "tanom", "tumubo"], "fact": {"tl": "Sa loob ng bawat buto ay may maliit na sanggol na halaman at nakaimbak na pagkain para magsimula itong tumubo.", "en": "Inside every seed is a tiny baby plant and stored food to help it start growing.", "bis": "Sa sulod sa matag liso adunay gamay nga binhi nga tanom ug tinipigan nga pagkaon aron makasugod kini sa pagtubo."}, "source": "NRC LS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "germination-needs-water-warmth-g4", "domain": "LIVING_THINGS", "topic": "what germination needs", "grades": [4, 5], "terms": ["pagtubo", "pagturok", "germination", "germinasyon", "buto", "liso", "binhi", "tubig", "init", "kainit", "hangin", "sumibol", "moturok", "ugat", "gamot"], "fact": {"tl": "Sa germination, sumisibol ang buto kapag may sapat na tubig, init, at hangin, na unang pinalalabas ang ugat.", "en": "In germination, a seed sprouts when there is enough water, warmth, and air, first pushing out a root.", "bis": "Sa germinasyon, ang liso moturok kon adunay igong tubig, kainit, ug hangin, nga unang gipagawas ang gamot."}, "source": "NRC LS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "seedling-uses-stored-food-g5", "domain": "LIVING_THINGS", "topic": "seedling uses stored food first", "grades": [5, 6], "terms": ["usbong", "punla", "tunghaw", "seedling", "nakaimbak na pagkain", "tinipigan nga pagkaon", "buto", "liso", "unang dahon", "una nga dahon", "bago lumitaw", "sa wala pa motungha"], "fact": {"tl": "Bago lumitaw ang unang dahon, ginagamit muna ng usbong ang nakaimbak na pagkain sa buto bilang panimulang lakas.", "en": "Before its first leaves appear, a seedling uses the food stored in the seed as its starting energy.", "bis": "Sa wala pa motungha ang unang dahon, ang tunghaw mogamit una sa pagkaong tinipigan sa liso isip sinugdanang kusog."}, "source": "NRC LS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "flower-is-reproductive-part-g5", "domain": "LIVING_THINGS", "topic": "the flower makes seeds", "grades": [5, 6], "terms": ["bulaklak", "bulak", "gumagawa ng buto", "naghimo sa liso", "binhi", "liso", "magbubunga", "mamunga", "halaman", "tanom", "supling", "kaliwat"], "fact": {"tl": "Ang bulaklak ang bahagi ng halaman na gumagawa ng buto para magkaroon ito ng bagong supling.", "en": "The flower is the part of the plant that makes seeds so it can have new offspring.", "bis": "Ang bulak mao ang bahin sa tanom nga naghimo ug liso aron makabaton kini ug bag-ong kaliwat."}, "source": "NRC LS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "flower-male-female-parts-g7", "domain": "LIVING_THINGS", "topic": "male and female parts of a flower", "grades": [7, 8], "terms": ["bulaklak", "bulak", "stamen", "lalaking bahagi", "lalaki nga bahin", "pistil", "babaeng bahagi", "babaye nga bahin", "pollen", "polen", "buto", "liso", "pollination"], "fact": {"tl": "May lalaking bahagi (stamen) ang bulaklak na gumagawa ng pollen, at babaeng bahagi (pistil) na tumatanggap nito para mabuo ang buto.", "en": "A flower has a male part (stamen) that makes pollen and a female part (pistil) that receives it so seeds can form.", "bis": "Ang bulak adunay lalaki nga bahin (stamen) nga naghimo ug polen ug babaye nga bahin (pistil) nga modawat niini aron maporma ang liso."}, "source": "AAAS ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pollination-by-bees-g4", "domain": "LIVING_THINGS", "topic": "bees and insects help pollination", "grades": [4, 5], "terms": ["polinasyon", "pollination", "pollen", "polen", "bubuyog", "buyog", "putyukan", "paruparo", "alibangbang", "insekto", "kulisap", "nektar", "bulaklak", "bulak"], "fact": {"tl": "Habang umiinom ng nektar, dinadala ng bubuyog at paruparo ang pollen mula sa isang bulaklak papunta sa iba — ito ang polinasyon.", "en": "While drinking nectar, bees and butterflies carry pollen from one flower to another — this is pollination.", "bis": "Samtang nagainom ug nektar, ang buyog ug alibangbang nagadala ug polen gikan sa usa ka bulak ngadto sa lain — mao kini ang polinasyon."}, "source": "NRC LS1.B; AAAS ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wind-pollination-g6", "domain": "LIVING_THINGS", "topic": "wind can carry pollen", "grades": [6, 7], "terms": ["hangin", "pollen", "polen", "polinasyon", "pollination", "mais", "damo", "sagbot", "insekto", "dala ng hangin", "halaman", "tanom"], "fact": {"tl": "Hindi lahat ng halaman ay umaasa sa insekto; ang ilan tulad ng mais at damo ay nagpapadala ng pollen sa pamamagitan ng hangin.", "en": "Not all plants rely on insects; some, like corn and grasses, send their pollen on the wind.", "bis": "Dili tanang tanom nagasalig sa insekto; ang uban sama sa mais ug mga sagbot nagapadala sa ilang polen pinaagi sa hangin."}, "source": "AAAS ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fruit-protects-seeds-g4", "domain": "LIVING_THINGS", "topic": "fruit holds and protects seeds", "grades": [4, 5], "terms": ["prutas", "bunga", "buto", "liso", "binhi", "loob ng prutas", "sulod sa prutas", "nanggaling sa bulaklak", "gikan sa bulak", "mangga", "papaya", "tumubo ang buto", "nakaprotekta", "panalipdan"], "fact": {"tl": "Ang prutas ang nagmumula sa bulaklak at bumabalot sa buto para protektahan ito hangga't hindi pa tumutubo.", "en": "Fruit grows from the flower and wraps around the seeds to protect them until they can grow.", "bis": "Ang prutas mogula gikan sa bulak ug moputos sa liso aron panalipdan kini samtang dili pa kini makatubo."}, "source": "NRC LS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "seed-dispersal-wind-g5", "domain": "LIVING_THINGS", "topic": "seeds spread by wind", "grades": [5, 6], "terms": ["pagkalat ng buto", "pagkatag sa liso", "seed dispersal", "hangin", "magaan na buto", "gaan nga liso", "pakpak", "pako", "himulmol", "balhibo", "lumilipad", "dandelion", "halaman", "tanom", "kumalat"], "fact": {"tl": "Para hindi magsiksikan ang mga halaman, ang ilang magaan na buto ay may pakpak o himulmol na dinadala ng hangin sa malayo.", "en": "So plants do not crowd each other, some light seeds have wings or fluff that the wind carries far away.", "bis": "Aron dili magsikit-sikit ang mga tanom, ang ubang gaan nga liso adunay pako o balhibo nga gidala sa hangin sa layo."}, "source": "AAAS ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "seed-dispersal-animals-g5", "domain": "LIVING_THINGS", "topic": "animals spread seeds", "grades": [5, 6], "terms": ["pagkalat ng buto", "pagkatag sa liso", "hayop", "mananap", "ibon", "langgam", "kinakain ang prutas", "gikaon ang prutas", "dumi", "hugaw", "kumalat", "balahibo", "balhibo"], "fact": {"tl": "Kapag kinakain ng ibon o hayop ang prutas, naitatapon nila ang buto sa malayong lugar kasama ng kanilang dumi.", "en": "When birds or animals eat fruit, they drop the seeds far away along with their droppings.", "bis": "Kon ang langgam o mananap mokaon sa prutas, ilang ikalat ang liso sa layo nga dapit uban sa ilang hugaw."}, "source": "AAAS ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "phototropism-grow-toward-light-g5", "domain": "LIVING_THINGS", "topic": "plants grow toward light", "grades": [5, 6], "terms": ["liwanag", "kahayag", "araw", "adlaw", "humahanap ng liwanag", "yumuyuko", "moyuko", "phototropism", "halaman sa bintana", "tanom sa bintana", "lumiliko", "sikat ng araw"], "fact": {"tl": "Yumuyuko at tumutubo ang halaman papunta sa pinanggagalingan ng liwanag para makakuha ng mas maraming sikat ng araw.", "en": "A plant bends and grows toward the source of light to get more sunlight.", "bis": "Ang tanom moyuko ug motubo paingon sa gigikanan sa kahayag aron makakuha ug mas daghang silaw sa adlaw."}, "source": "NRC LS1.D; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "roots-grow-down-gravity-g6", "domain": "LIVING_THINGS", "topic": "roots grow downward", "grades": [6, 7], "terms": ["ugat", "gamot", "pababa", "paubos", "tumutubo pababa", "motubo paubos", "grabidad", "gravity", "gravitropism", "halaman", "tanom", "lupa", "yuta", "baligtad", "balitad"], "fact": {"tl": "Tumutubo palagi ang ugat pababa patungo sa lupa dahil nararamdaman nito ang grabidad, kahit pa baligtad itinanim ang buto.", "en": "Roots always grow downward into the soil because they sense gravity, even if the seed was planted upside down.", "bis": "Ang gamot kanunay motubo paubos ngadto sa yuta tungod kay mabati niini ang grabidad, bisan kon balitad gitanom ang liso."}, "source": "NRC LS1.D; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "carnivorous-plants-eat-insects-g5", "domain": "LIVING_THINGS", "topic": "carnivorous plants catch insects", "grades": [5, 6, 7], "terms": ["halamang kumakain ng insekto", "tanom nga mokaon ug insekto", "carnivorous plant", "naghuhuli ng insekto", "modakop", "bumibitag", "insekto", "kulisap", "mahirap na lupa", "pobre nga yuta", "sustansya", "tinutunaw", "motunaw"], "fact": {"tl": "May mga halamang kumakain ng insekto na humuhuli at tinutunaw ang mga ito para makakuha ng sustansyang kulang sa mahirap na lupa.", "en": "Some carnivorous plants catch and digest insects to get nutrients that are missing in poor soil.", "bis": "Adunay mga tanom nga mokaon ug insekto nga modakop ug motunaw niini aron makakuha ug sustansya nga kulang sa pobre nga yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "venus-flytrap-snaps-shut-g5", "domain": "LIVING_THINGS", "topic": "Venus flytrap snaps shut", "grades": [5, 6], "terms": ["Venus flytrap", "halamang bibig", "tanom nga baba", "nagsasara", "mosira", "biglang sumara", "kalit nga nagsira", "buhok", "balhibo", "naghuli ng insekto", "insekto", "dahon na nagsasara"], "fact": {"tl": "Ang Venus flytrap ay may dahong parang bibig na biglang nagsasara kapag may insektong tumapak sa maliliit na buhok nito.", "en": "The Venus flytrap has leaves like a mouth that snap shut when an insect touches the tiny hairs inside.", "bis": "Ang Venus flytrap adunay dahon nga sama sa baba nga kalit nga mosira kon adunay insekto nga makahikap sa gagmay nga balhibo niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pitcher-plant-traps-g5", "domain": "LIVING_THINGS", "topic": "pitcher plant traps prey", "grades": [5, 6, 7], "terms": ["pitcher plant", "halamang baso", "tanom nga tasa", "madulas", "danlog", "nahuhulog", "mahulog", "likido", "insekto", "tinutunaw", "matunaw", "Pilipinas", "Palawan"], "fact": {"tl": "Ang pitcher plant ay may dahong hugis-baso na may madulas na gilid kaya nahuhulog at natutunaw ang insekto sa likido sa loob.", "en": "The pitcher plant has cup-shaped leaves with slippery sides, so insects fall in and are digested in the liquid inside.", "bis": "Ang pitcher plant adunay dahon nga porma sa tasa nga danlog ang kilid, busa ang insekto mahulog ug matunaw sa likido sa sulod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "carnivorous-plants-still-photosynthesize-g6", "domain": "LIVING_THINGS", "topic": "carnivorous plants still do photosynthesis", "grades": [6, 7], "terms": ["halamang kumakain ng insekto", "tanom nga mokaon ug insekto", "carnivorous plant", "potosintesis", "araw", "adlaw", "gumagawa pa rin ng pagkain", "naghimo gihapon ug pagkaon", "dahon", "sustansya", "pandagdag", "pangdugang"], "fact": {"tl": "Kahit kumakain ng insekto, gumagawa pa rin ng pagkain ang mga halamang ito sa pamamagitan ng potosintesis — pandagdag lang ang insekto sa kanilang sustansya.", "en": "Even though they eat insects, these plants still make food by photosynthesis — the insects only add extra nutrients.", "bis": "Bisan og mokaon sila ug insekto, kini nga mga tanom naghimo gihapon ug pagkaon pinaagi sa potosintesis — ang insekto pangdugang lang sa ilang sustansya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "plants-respire-too-g7", "domain": "LIVING_THINGS", "topic": "plants breathe too (respiration)", "grades": [7, 8], "terms": ["halaman", "tanom", "humihinga", "nagaginhawa", "respiration", "respirasyon", "oxygen", "oksiheno", "gabi", "gabii", "araw at gabi", "potosintesis", "enerhiya"], "fact": {"tl": "Bukod sa potosintesis, humihinga rin ang halaman: gumagamit ito ng oksiheno araw at gabi para palabasin ang enerhiya mula sa pagkain nito.", "en": "Besides photosynthesis, plants also respire: they use oxygen day and night to release energy from their food.", "bis": "Gawas sa potosintesis, ang tanom nagaginhawa usab: mogamit kini ug oksiheno adlaw ug gabii aron mopagawas sa enerhiya gikan sa pagkaon niini."}, "source": "AAAS ch.5; NRC LS1.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "transpiration-water-from-leaves-g6", "domain": "LIVING_THINGS", "topic": "plants release water from leaves", "grades": [6, 7], "terms": ["transpiration", "transpirasyon", "tubig", "singaw", "alisngaw", "dahon", "stomata", "estomata", "naglalabas ng tubig", "nagabuga ug tubig", "ugat", "gamot", "halaman", "tanom"], "fact": {"tl": "Naglalabas ang dahon ng singaw ng tubig sa pamamagitan ng stomata, at ito ang humihila ng bagong tubig pataas mula sa ugat.", "en": "Leaves release water vapor through their stomata, and this pulls fresh water upward from the roots.", "bis": "Ang dahon nagabuga ug alisngaw sa tubig pinaagi sa stomata, ug kini ang nagbira sa bag-ong tubig pasaka gikan sa gamot."}, "source": "AAAS ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "plants-store-food-in-roots-g5", "domain": "LIVING_THINGS", "topic": "plants store food in roots and stems", "grades": [5, 6], "terms": ["nag-iimbak ng pagkain", "nagtipig ug pagkaon", "ugat", "gamot", "kamote", "carrot", "patatas", "ube", "gabi", "tangkay", "punoan", "halaman", "tanom"], "fact": {"tl": "Iniimbak ng ilang halaman ang sobrang pagkain sa kanilang ugat o tangkay, kaya matamis at malaman ang kamote, carrot, at patatas.", "en": "Some plants store extra food in their roots or stems, which is why sweet potato, carrot, and potato are sweet and starchy.", "bis": "Ang ubang tanom nagatipig sa sobra nga pagkaon sa ilang gamot o punoan, mao nga tam-is ug puno sa almidon ang kamote, carrot, ug patatas."}, "source": "AAAS ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "plants-are-producers-g6", "domain": "LIVING_THINGS", "topic": "plants are producers in food chains", "grades": [6, 7, 8], "terms": ["producer", "tagagawa ng pagkain", "tagahimo ug pagkaon", "halaman", "tanom", "sariling pagkain", "kaugalingong pagkaon", "food chain", "kadena ng pagkain", "kutay sa pagkaon", "sinugdanan", "araw", "adlaw"], "fact": {"tl": "Tinatawag na producer ang halaman dahil ito ang gumagawa ng sariling pagkain at siyang pinagsisimulan ng halos lahat ng food chain.", "en": "Plants are called producers because they make their own food and are the start of nearly every food chain.", "bis": "Ang tanom gitawag nga producer kay kini ang naghimo sa kaugalingong pagkaon ug maoy sinugdanan sa halos tanang kutay sa pagkaon."}, "source": "NRC LS2.B; AAAS ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "some-plants-grow-from-stems-g5", "domain": "LIVING_THINGS", "topic": "plants can grow without seeds", "grades": [5, 6], "terms": ["walang buto", "walay liso", "tangkay", "sanga", "punoan", "tinanim na tangkay", "gitanom nga sanga", "kamote", "saging", "luya", "ginger", "bagong halaman", "pagpaparami nga walay liso"], "fact": {"tl": "Hindi lahat ng halaman ay nanggagaling sa buto; ang ilan tulad ng kamote at saging ay tumutubo mula sa itinanim na tangkay o bahagi ng katawan nito.", "en": "Not all plants come from seeds; some, like sweet potato and banana, grow from a planted stem or part of the parent plant.", "bis": "Dili tanang tanom maggikan sa liso; ang uban sama sa kamote ug saging motubo gikan sa gitanom nga punoan o bahin sa ginikanan nga tanom."}, "source": "AAAS ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "melting-mechanism-g4", "domain": "MATTER", "topic": "melting", "grades": [3, 4, 5], "terms": ["melting", "natutunaw", "matunaw", "tunaw", "yelo", "kandila", "tsokolate", "init", "solid", "liquid", "particle", "mainit"], "fact": {"tl": "Sa melting, ang solid ay nagiging likido kapag binigyan ito ng init na nagpapagalaw nang mas mabilis sa mga particle nito hanggang hindi na sila magkadikit nang mahigpit — kaya natutunaw ang yelo, kandila, at tsokolate kapag mainit.", "en": "In melting, a solid becomes a liquid when heat makes its particles move faster until they no longer hold tightly together — that is why ice, candles, and chocolate melt when warm.", "bis": "Sa melting, ang solid mahimong likido kung initan kay ang init mopalihok og mas paspas sa mga particle niini hangtod dili na sila magkupot og hugot — mao nga matunaw ang yelo, kandila, ug tsokolate kung init."}, "source": "NRC PS1.A; AAAS BSL Ch.4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "melting-point-g6", "domain": "MATTER", "topic": "melting point", "grades": [5, 6, 7], "terms": ["melting point", "puntong pagtunaw", "tunawan", "temperatura", "temperature", "yelo", "Celsius", "bakal", "puthaw", "metal", "matunaw", "init"], "fact": {"tl": "Ang melting point ay ang tiyak na temperatura kung saan natutunaw ang isang solid — palaging 0°C para sa purong yelo, ngunit mas mataas para sa ibang materyal tulad ng bakal na natutunaw lang sa sobrang init.", "en": "The melting point is the exact temperature at which a solid melts — always 0°C for pure ice, but much higher for materials like iron, which melts only at very high heat.", "bis": "Ang melting point mao ang tukma nga temperatura diin matunaw ang usa ka solid — kanunay 0°C para sa putli nga yelo, apan mas taas para sa ubang materyal sama sa puthaw nga matunaw lang sa hilabihang kainit."}, "source": "AAAS BSL Ch.4D (reference value); NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "freezing-mechanism-g4", "domain": "MATTER", "topic": "freezing", "grades": [3, 4, 5], "terms": ["freezing", "nagyeyelo", "mag-yelo", "mo-yelo", "yelo", "ice", "palamig", "bugnaw", "liquid", "solid", "tubig", "freezer"], "fact": {"tl": "Sa freezing, ang likido ay nagiging solid kapag pinalamig — nawawalan ng lakas ang mga particle nito kaya bumabagal at nag-aayos nang mahigpit, gaya ng tubig na nagiging yelo sa freezer.", "en": "In freezing, a liquid becomes a solid when cooled — its particles lose energy, slow down, and lock tightly into place, like water turning into ice in the freezer.", "bis": "Sa freezing, ang likido mahimong solid kung bugnawon — mawad-an og kusog ang mga particle niini maong mohinay ug mosumpay og hugot, sama sa tubig nga mahimong yelo sa freezer."}, "source": "NRC PS1.A; AAAS BSL Ch.4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "freezing-melting-same-point-g6", "domain": "MATTER", "topic": "freezing and melting at the same temperature", "grades": [6, 7], "terms": ["freezing point", "melting point", "Celsius", "tubig", "yelo", "pareho", "parehas", "temperatura", "temperature", "pagkatunaw", "pagyeyelo", "mo-yelo"], "fact": {"tl": "Ang freezing point at melting point ng isang sangkap ay magkapareho — para sa tubig, ito ay 0°C: sa temperaturang iyon natutunaw ang yelo at nagyeyelo ang tubig.", "en": "A substance's freezing point and melting point are the same temperature — for water it is 0°C: at that temperature ice melts and water freezes.", "bis": "Ang freezing point ug melting point sa usa ka sustansya parehas — para sa tubig kini 0°C: sa maong temperatura matunaw ang yelo ug mo-yelo ang tubig."}, "source": "AAAS BSL Ch.4D (reference value); NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "evaporation-everywhere-g5", "domain": "MATTER", "topic": "evaporation happens at any temperature", "grades": [4, 5, 6], "terms": ["evaporation", "singaw", "sumisingaw", "alisngaw", "mo-alisngaw", "ibabaw", "surface", "tuyo", "mauga", "kahit", "bisan", "temperatura"], "fact": {"tl": "Nangyayari ang evaporation kahit hindi kumukulo ang tubig — sa ibabaw lang ito nagaganap, kaya unti-unting natutuyo ang lawa at basang sahig kahit hindi mainit, ngunit mas mabilis kapag mas mainit.", "en": "Evaporation happens even when water is not boiling — it occurs only at the surface, so puddles and wet floors slowly dry even when it is not hot, but faster when warmer.", "bis": "Mahitabo ang evaporation bisan dili mobukal ang tubig — sa ibabaw lang kini mahitabo, mao nga hinay-hinayng mauga ang lim-aw ug basa nga salog bisan dili init, apan mas paspas kung mas init."}, "source": "NRC ESS2.C; AAAS BSL Ch.4", "generator": "claude-workflow", "reviewed": false},
  {"id": "boiling-vs-evaporation-g6", "domain": "MATTER", "topic": "boiling versus evaporation", "grades": [6, 7], "terms": ["boiling", "evaporation", "kumukulo", "mobukal", "singaw", "alisngaw", "bula", "bubbles", "Celsius", "ibabaw", "kaibahan", "kalahian"], "fact": {"tl": "Magkaiba ang boiling at evaporation: ang evaporation ay sa ibabaw lang at sa anumang temperatura, ngunit ang boiling ay nangyayari sa buong likido sa boiling point (100°C para sa tubig) kung saan may mga bula ng singaw na lumilitaw mula sa loob.", "en": "Boiling and evaporation differ: evaporation is only at the surface and at any temperature, but boiling happens throughout the liquid at the boiling point (100°C for water), where vapor bubbles form from inside.", "bis": "Lahi ang boiling ug evaporation: ang evaporation sa ibabaw lang ug sa bisan unsang temperatura, apan ang boiling mahitabo sa tibuok likido sa boiling point (100°C para sa tubig), diin adunay mga bula sa alisngaw nga mogula gikan sa sulod."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "steam-invisible-g6", "domain": "MATTER", "topic": "steam is invisible", "grades": [5, 6, 7], "terms": ["steam", "singaw", "alisngaw", "usok", "aso", "puti", "invisible", "hindi nakikita", "dili makita", "water vapor", "kumukulo", "condensation"], "fact": {"tl": "Ang tunay na singaw (water vapor) ay walang kulay at hindi nakikita — ang puting 'usok' sa itaas ng kumukulong tubig ay maliliit na patak ng tubig na nabuo nang lumamig at nag-condense ang singaw sa hangin.", "en": "True steam (water vapor) is colorless and invisible — the white 'cloud' above boiling water is tiny droplets that form when the vapor cools and condenses in the air.", "bis": "Ang tinuod nga alisngaw (water vapor) walay kolor ug dili makita — ang puti nga 'aso' ibabaw sa nagbukal nga tubig mao ang gagmayng tulo nga maporma kung mabugnaw ug mo-condense ang alisngaw sa hangin."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "condensation-water-cycle-clouds-g5", "domain": "EARTH_SPACE", "topic": "condensation forms clouds", "grades": [4, 5, 6], "terms": ["condensation", "ulap", "panganod", "clouds", "singaw", "alisngaw", "lumamig", "mabugnaw", "tubig", "langit", "patak", "ulan", "rain"], "fact": {"tl": "Nabubuo ang mga ulap kapag ang singaw ng tubig na umakyat sa langit ay lumamig at nag-condense pabalik sa maliliit na patak ng tubig o yelo — kapag dumami at bumigat ang mga ito, bumabagsak silang ulan.", "en": "Clouds form when water vapor that rose into the sky cools and condenses back into tiny droplets of water or ice — when these grow heavy enough, they fall as rain.", "bis": "Maporma ang mga panganod kung ang alisngaw sa tubig nga misaka sa langit mabugnaw ug mo-condense balik ngadto sa gagmayng tulo sa tubig o yelo — kung modaghan ug mobug-at kini, mahulog isip ulan."}, "source": "NRC ESS2.C; AAAS BSL Ch.4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "deposition-state-change-g7", "domain": "MATTER", "topic": "deposition", "grades": [7, 8], "terms": ["deposition", "frost", "escarcha", "yelo", "gas", "solid", "singaw", "alisngaw", "direkta", "direktang", "kabaligtaran", "kabaliktaran", "sublimation"], "fact": {"tl": "Ang deposition ay ang pagbabago ng gas nang direkta papuntang solid nang hindi muna nagiging likido — gaya ng singaw ng tubig sa hangin na nagiging escarcha (frost) sa malamig na damo. Ito ang kabaligtaran ng sublimation.", "en": "Deposition is when a gas changes directly into a solid without first becoming a liquid — like water vapor in the air turning into frost on cold grass. It is the reverse of sublimation.", "bis": "Ang deposition mao ang pagbalhin sa gas direkta ngadto sa solid nga dili una mahimong likido — sama sa alisngaw sa tubig sa hangin nga mahimong escarcha (frost) sa bugnaw nga sagbot. Kabaliktaran kini sa sublimation."}, "source": "NRC PS1.A; AAAS BSL Ch.4", "generator": "claude-workflow", "reviewed": false},
  {"id": "particles-spacing-states-g5", "domain": "MATTER", "topic": "particle arrangement in states of matter", "grades": [5, 6, 7], "terms": ["particle", "mga particle", "layo", "dikit", "spacing", "solid", "liquid", "gas", "ayos", "arrangement", "gumagalaw", "molihok", "vibrate"], "fact": {"tl": "Sa solid, magkadikit at maayos na nakaayos ang mga particle at nanginginig lang sa lugar; sa liquid, magkalapit pa rin sila ngunit malayang dumadausdos; sa gas, malayo ang kanilang pagitan at mabilis kumakaway saanman.", "en": "In a solid, particles are packed close in a neat arrangement and only vibrate in place; in a liquid, they stay close but slide past each other freely; in a gas, they are far apart and move quickly everywhere.", "bis": "Sa solid, ang mga particle suod ug han-ay og maayo ug magkurog lang sa ilang dapit; sa liquid, suod gihapon sila apan gawasnong modan-as; sa gas, layo ang ilang gilay-on ug paspas molihok bisan asa."}, "source": "NRC PS1.A; AAAS BSL Ch.4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "gas-fills-container-g5", "domain": "MATTER", "topic": "gases spread to fill their container", "grades": [4, 5, 6], "terms": ["gas", "hangin", "air", "kumakalat", "mokatag", "lalagyan", "sudlanan", "container", "lobo", "balloon", "puno", "mopuno", "espasyo"], "fact": {"tl": "Pumupuno ang gas sa buong lalagyan nito dahil ang mga particle nito ay malayo sa isa't isa at mabilis na gumagalaw papunta sa lahat ng direksyon — kaya pumupuno ang hangin sa buong lobo at kumakalat ang amoy sa buong silid.", "en": "A gas fills its whole container because its particles are far apart and move quickly in every direction — that is why air fills a whole balloon and a smell spreads across a room.", "bis": "Mopuno ang gas sa tibuok sudlanan niini kay ang mga particle niini layo sa usag usa ug paspas molihok sa tanang direksyon — mao nga mopuno ang hangin sa tibuok lobo ug mokatag ang baho sa tibuok kwarto."}, "source": "NRC PS1.A; AAAS BSL Ch.4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "gas-compressible-g6", "domain": "MATTER", "topic": "gases can be squeezed", "grades": [6, 7], "terms": ["gas", "hangin", "air", "siksik", "masiksik", "compress", "piga", "lobo", "gulong", "ligid", "tire", "liquid", "solid", "puwang", "luna"], "fact": {"tl": "Madaling masiksik (ma-compress) ang gas sa mas maliit na espasyo dahil malalaki ang puwang sa pagitan ng mga particle nito — kaya kayang punuin ng maraming hangin ang isang gulong; mahirap naman siksikin ang likido at solid.", "en": "A gas can be squeezed into a smaller space because there are big gaps between its particles — that is why a lot of air can be pumped into a tire; liquids and solids are very hard to compress.", "bis": "Sayon nga ma-compress ang gas ngadto sa mas gamayng espasyo kay dako ang luna tali sa mga particle niini — mao nga daghang hangin ang masulod sa usa ka ligid; ang likido ug solid lisod i-compress."}, "source": "NRC PS1.A; AAAS BSL Ch.4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "state-changes-reversible-g5", "domain": "MATTER", "topic": "changes of state are reversible", "grades": [4, 5, 6], "terms": ["physical change", "reversible", "mababalik", "mabalik", "tunaw", "yelo", "tubig", "singaw", "sangkap", "sustansya", "substance", "init", "lamig"], "fact": {"tl": "Ang pagbabago ng state ay isang physical change — mababalik ito at walang bagong sangkap na nabubuo: kapag natunaw ang yelo, tubig pa rin ito, at kapag pinalamig muli, magyeyelo itong muli.", "en": "A change of state is a physical change — it can be reversed and no new substance is made: when ice melts it is still water, and when cooled again it becomes ice once more.", "bis": "Ang pagbalhin sa state usa ka physical change — mabalik kini ug walay bag-ong sustansya nga maporma: kung matunaw ang yelo, tubig gihapon kini, ug kung bugnawon usab, mo-yelo na usab."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "mixture-keeps-properties-g5", "domain": "MATTER", "topic": "each part of a mixture keeps its properties", "grades": [5, 6], "terms": ["mixture", "halo", "pinaghalo", "sagol", "katangian", "kinaiya", "properties", "hiwalay", "mabulag", "buhangin", "balas", "bakal", "puthaw", "magnet"], "fact": {"tl": "Sa isang mixture, pinapanatili ng bawat sangkap ang sariling katangian, kaya madalas pa rin itong makikilala o mapaghihiwalay — halimbawa, sa pinaghalong buhangin at bakal, kayang akitin ng magnet ang bakal palabas.", "en": "In a mixture, each part keeps its own properties, so it can often still be recognized or separated — for example, in a mix of sand and iron filings, a magnet can pull the iron back out.", "bis": "Sa usa ka mixture, ang matag bahin magpabilin sa kaugalingong kinaiya, mao nga kasagaran mailhan o mabulag gihapon — pananglitan, sa sagol nga balas ug puthaw, madani sa magnet ang puthaw pagawas."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "homogeneous-heterogeneous-g7", "domain": "MATTER", "topic": "homogeneous and heterogeneous mixtures", "grades": [7, 8], "terms": ["homogeneous", "heterogeneous", "mixture", "halo", "sagol", "pantay", "pareho", "magkaiba", "lainlain", "bahagi", "bahin", "salad", "solution", "asukal"], "fact": {"tl": "Sa homogeneous mixture, pantay ang pagkakahalo at iisang hitsura lang ito (gaya ng tubig na may asukal, isang solution); sa heterogeneous mixture, kitang-kita ang magkakaibang bahagi (gaya ng ensalada o sopas na may sangkap).", "en": "In a homogeneous mixture the parts are evenly blended and look uniform (like sugar dissolved in water, a solution); in a heterogeneous mixture the different parts are clearly visible (like a salad or chunky soup).", "bis": "Sa homogeneous mixture, patas ang pagkasagol ug usa ra ka hitsura (sama sa tubig nga may asukal, usa ka solution); sa heterogeneous mixture, klarong makita ang lainlaing bahin (sama sa salad o sabaw nga may sagol)."}, "source": "NRC PS1.A; AAAS BSL Ch.4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "suspension-colloid-g8", "domain": "MATTER", "topic": "suspensions and colloids", "grades": [8, 9], "terms": ["suspension", "colloid", "mixture", "halo", "sagol", "lumulutang", "lutang", "tumira", "motining", "sinala", "gatas", "milk", "fog", "gabon", "maputik", "lapok"], "fact": {"tl": "Ang suspension ay mixture na may mga particle na sapat ang laki para makita at tumira sa ilalim kapag iniwan (gaya ng maputik na tubig); ang colloid naman ay may particle na napakaliit para tumira at nananatiling lutang (gaya ng gatas o fog).", "en": "A suspension is a mixture with particles big enough to see and to settle at the bottom if left to stand (like muddy water); a colloid has particles too small to settle, so they stay spread out (like milk or fog).", "bis": "Ang suspension usa ka mixture nga adunay mga particle nga igong dako aron makita ug motining sa ilawom kung pasagdan (sama sa lapok nga tubig); ang colloid adunay particle nga gagmay kaayo aron motining, mao nga magpabilin nga nagkatag (sama sa gatas o gabon)."}, "source": "NRC PS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "solubility-limit-temperature-g7", "domain": "MATTER", "topic": "temperature changes how much dissolves", "grades": [7, 8], "terms": ["solubility", "saturated", "natutunaw", "matunaw", "dissolve", "init", "temperatura", "asukal", "asin", "mainit", "kristal", "crystal", "lumalamig", "bugnaw"], "fact": {"tl": "Karaniwang mas marami ang natutunaw na solid (gaya ng asukal o asin) sa mainit na tubig kaysa malamig — kaya kapag pinalamig ang puno-puno (saturated) na mainit na solusyon, ang sobrang natunaw ay maaaring lumabas bilang kristal.", "en": "More of a solid (like sugar or salt) usually dissolves in hot water than in cold — so when a saturated hot solution is cooled, the extra dissolved solid can come back out as crystals.", "bis": "Kasagaran mas daghan ang matunaw nga solid (sama sa asukal o asin) sa init nga tubig kaysa bugnaw — mao nga kung bugnawon ang puno (saturated) nga init nga solusyon, ang sobra nga natunaw mahimong mogula isip kristal."}, "source": "NRC PS1.A; AAAS BSL Ch.4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "concentration-dilute-g7", "domain": "MATTER", "topic": "concentrated and dilute solutions", "grades": [6, 7, 8], "terms": ["concentration", "concentrated", "dilute", "matapang", "lig-on", "mahina", "solute", "solvent", "tubig", "asukal", "kape", "dami", "daghan"], "fact": {"tl": "Ang isang solution ay concentrated kapag maraming natunaw na solute sa kaunting solvent (gaya ng matapang na kape), at dilute kapag kaunti lang ang solute sa maraming tubig — nadaragdagan ng tubig ang pagiging dilute nito.", "en": "A solution is concentrated when a lot of solute is dissolved in a little solvent (like strong coffee), and dilute when there is only a little solute in a lot of water — adding water makes it more dilute.", "bis": "Ang usa ka solution concentrated kung daghang natunaw nga solute sa gamayng solvent (sama sa lig-on nga kape), ug dilute kung gamay ra ang solute sa daghang tubig — ang pagdugang og tubig mopadilute niini."}, "source": "NRC PS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "filtration-method-g6", "domain": "MATTER", "topic": "filtration separates solids from liquids", "grades": [5, 6, 7], "terms": ["filtration", "pagsala", "sala", "salaan", "ihiwalay", "bulagon", "buhangin", "balas", "tubig", "papel", "filter paper", "butas", "lungag", "lumusot"], "fact": {"tl": "Ginagamit ang filtration para ihiwalay ang hindi natutunaw na solid sa likido: dumadaan ang likido sa maliliit na butas ng salaan o filter paper, samantalang naiiwan sa ibabaw ang solid — gaya ng pagsala ng buhangin mula sa tubig.", "en": "Filtration separates an undissolved solid from a liquid: the liquid passes through the tiny holes of a filter or filter paper while the solid stays behind on top — like filtering sand out of water.", "bis": "Gamiton ang filtration aron bulagon ang dili matunaw nga solid gikan sa likido: ang likido moagi sa gagmayng lungag sa filter o filter paper samtang ang solid mabilin sa ibabaw — sama sa pagsala sa balas gikan sa tubig."}, "source": "DepEd Science CG (Matter); AAAS BSL Ch.4", "generator": "claude-workflow", "reviewed": false},
  {"id": "evaporation-recover-salt-g6", "domain": "MATTER", "topic": "evaporation recovers a dissolved solid", "grades": [5, 6, 7], "terms": ["evaporation", "asin", "salt", "sea salt", "asinan", "tubig-dagat", "kumukulo", "singaw", "alisngaw", "makuha", "natitira", "mabilin", "Pilipinas"], "fact": {"tl": "Para makuha ang natunaw na solid mula sa solusyon, hinahayaang sumingaw o pinapakulo ang tubig hanggang maiwan ang solid — ganito gumagawa ng asin mula sa tubig-dagat sa mga asinan ng Pilipinas.", "en": "To get back a dissolved solid from a solution, the water is left to evaporate or is boiled away until only the solid remains — this is how sea salt is made from seawater in Philippine salt beds.", "bis": "Aron makuha ang natunaw nga solid gikan sa solusyon, pasagdan nga mo-alisngaw o pabukalan ang tubig hangtod mabilin ang solid — mao kini ang paghimo og asin gikan sa tubig-dagat sa mga asinan sa Pilipinas."}, "source": "DepEd Science CG (Matter); AAAS BSL Ch.4", "generator": "claude-workflow", "reviewed": false},
  {"id": "distillation-method-g8", "domain": "MATTER", "topic": "distillation", "grades": [7, 8, 9], "terms": ["distillation", "distilled water", "pagdistila", "alisngaw", "singaw", "condense", "purong tubig", "putli", "asin", "ihiwalay", "initin", "palamigin", "destilado"], "fact": {"tl": "Sa distillation, pinapakulo ang isang solusyon para sumingaw ang tubig (o ibang likido), pagkatapos ay pinapalamig ang singaw para mag-condense pabalik sa purong likido — ganito gumagawa ng distilled water mula sa maalat na tubig.", "en": "In distillation, a solution is boiled so the water (or another liquid) evaporates, then the vapor is cooled to condense back into pure liquid — this is how distilled water is made from salty water.", "bis": "Sa distillation, pabukalan ang usa ka solusyon aron mo-alisngaw ang tubig (o laing likido), unya bugnawon ang alisngaw aron mo-condense balik ngadto sa putli nga likido — mao kini ang paghimo og distilled water gikan sa parat nga tubig."}, "source": "DepEd Science CG (Matter); AAAS BSL Ch.4", "generator": "claude-workflow", "reviewed": false},
  {"id": "decantation-method-g6", "domain": "MATTER", "topic": "decantation", "grades": [5, 6, 7], "terms": ["decantation", "pagsalin", "isalin", "ibuhos", "ibubo", "tubig", "putik", "lapok", "tumira", "motining", "ilalim", "ibabaw", "dahan-dahan", "langis", "lana"], "fact": {"tl": "Sa decantation, hinahayaang tumira sa ilalim ang mas mabigat na bahagi, pagkatapos ay dahan-dahang ibinubuhos ang malinaw na likido sa itaas — kaya naihihiwalay ang tubig mula sa putik na nag-settle na, o ang langis na lumutang.", "en": "In decantation, the heavier part is left to settle at the bottom, then the clear liquid on top is carefully poured off — this separates water from settled mud, or oil floating on top.", "bis": "Sa decantation, pasagdan motining sa ilawom ang mas bug-at nga bahin, unya hinay-hinay nga ibubo ang tin-aw nga likido sa ibabaw — mao nga mabulag ang tubig gikan sa lapok nga mitining na, o ang lana nga milutaw."}, "source": "DepEd Science CG (Matter); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnetic-separation-g6", "domain": "MATTER", "topic": "separating with a magnet", "grades": [5, 6], "terms": ["magnet", "magnetic separation", "bakal", "puthaw", "iron", "akitin", "danihon", "madani", "buhangin", "balas", "ihiwalay", "bulagon", "asin", "papel"], "fact": {"tl": "Maaaring ihiwalay ang mga magnetic na bagay tulad ng bakal sa isang mixture gamit ang magnet — inaakit ng magnet ang bakal palabas, samantalang naiiwan ang buhangin, asin, o papel na hindi naaakit nito.", "en": "Magnetic materials like iron can be separated from a mixture with a magnet — the magnet pulls the iron out, while sand, salt, or paper that it does not attract are left behind.", "bis": "Ang magnetic nga mga butang sama sa puthaw mabulag gikan sa usa ka mixture gamit ang magnet — danihon sa magnet ang puthaw pagawas, samtang mabilin ang balas, asin, o papel nga dili niini madani."}, "source": "DepEd Science CG (Matter); AAAS BSL Ch.4", "generator": "claude-workflow", "reviewed": false},
  {"id": "chromatography-method-g8", "domain": "MATTER", "topic": "chromatography separates colors", "grades": [8, 9], "terms": ["chromatography", "kromatograpiya", "ink", "tinta", "kulay", "kolor", "colors", "marker", "papel", "tubig", "kumalat", "naghiwalay", "mabulag", "pigment", "umakyat", "pasaka"], "fact": {"tl": "Sa chromatography, naihihiwalay ang magkakaibang kulay sa isang halo (gaya ng tinta) dahil ang ilang pigment ay mas mabilis na natatangay ng tubig pataas sa papel kaysa iba — kaya nahahati ang itim na tinta sa ilang kulay.", "en": "In chromatography, the different colors in a mixture (like ink) separate because some pigments are carried up a paper by water faster than others — so black ink can split into several colors.", "bis": "Sa chromatography, mabulag ang lainlaing kolor sa usa ka sagol (sama sa tinta) kay ang ubang pigment madala paspas sa tubig pasaka sa papel kaysa uban — mao nga ang itom nga tinta mabahin ngadto sa pipila ka kolor."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.4", "generator": "claude-workflow", "reviewed": false},
  {"id": "matter-not-created-destroyed-state-g7", "domain": "MATTER", "topic": "mass stays the same during a state change", "grades": [6, 7, 8], "terms": ["conservation", "mass", "timbang", "weight", "yelo", "tubig", "tunaw", "natunaw", "pareho", "parehas", "hindi nawawala", "particle", "saradong", "sirado", "sealed"], "fact": {"tl": "Hindi nawawala ang matter kapag nagbabago ang state nito — kung tutunawin ang yelo sa saradong lalagyan, pareho pa rin ang mass ng tubig at ng dating yelo, dahil pareho ang dami ng particle, naiba lang ang ayos.", "en": "Matter is not lost when its state changes — if ice melts in a sealed container, the water has the same mass as the ice did, because the number of particles is the same; only their arrangement changed.", "bis": "Dili mawala ang matter kung mausab ang state niini — kung tunawon ang yelo sa sirado nga sudlanan, parehas ra ang mass sa tubig ug sa kanhi yelo, kay parehas ang gidaghanon sa particle, ang han-ay lang ang nausab."}, "source": "NRC PS1.B; AAAS BSL Ch.4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-puddles-faster-sun-g3", "domain": "MATTER", "topic": "why wet things dry faster in the sun", "grades": [3, 4], "terms": ["araw", "adlaw", "sun", "init", "mabilis", "paspas", "tuyo", "mauga", "basa", "damit", "singaw", "alisngaw", "evaporation"], "fact": {"tl": "Mas mabilis natutuyo ang basang bagay sa ilalim ng araw kaysa sa lilim dahil nagbibigay ng dagdag na init ang araw — at mas mabilis na nakakatakas ang mga particle ng tubig bilang singaw kapag mas mainit.", "en": "Wet things dry faster in the sun than in the shade because the sun adds extra heat — and water particles escape as vapor more quickly when it is warmer.", "bis": "Mas paspas mauga ang basa nga butang ilalom sa adlaw kaysa landong kay ang adlaw mohatag og dugang init — ug mas paspas makaikyas ang mga particle sa tubig isip alisngaw kung mas init."}, "source": "NRC ESS2.C; AAAS BSL Ch.4", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-fog-mirror-bathroom-g5", "domain": "MATTER", "topic": "why a bathroom mirror fogs up", "grades": [4, 5, 6], "terms": ["salamin", "mirror", "banyo", "bathroom", "hamog", "gabon", "fog", "malabo", "hanap", "singaw", "alisngaw", "shower", "ligo", "condensation", "patak", "tulo"], "fact": {"tl": "Nalalabo ang salamin sa banyo pagkatapos maligo dahil ang maraming singaw ng tubig mula sa mainit na shower ay dumidikit sa mas malamig na salamin at nag-condense bilang maliliit na patak — pareho ito sa pamamawis ng malamig na baso.", "en": "A bathroom mirror fogs up after a hot shower because the plentiful water vapor touches the cooler mirror and condenses into tiny droplets — the same way a cold glass 'sweats'.", "bis": "Mohanap ang salamin sa banyo human maligo kay ang daghang alisngaw sa tubig gikan sa init nga shower modikit sa mas bugnaw nga salamin ug mo-condense isip gagmayng tulo — sama ra sa pagsingot sa bugnaw nga baso."}, "source": "NRC ESS2.C; AAAS BSL Ch.4", "generator": "claude-workflow", "reviewed": false},
  {"id": "atom-tiny-building-block-g5", "domain": "MATTER", "topic": "atoms are tiny building blocks", "grades": [4, 5, 6], "terms": ["atom", "atomo", "building block", "blocks", "pinakamaliit", "kinagamyang", "maliit", "gamay", "gibuhat", "gawa", "binubuo", "hinimo", "particle", "napakaliit", "gagmay kaayo", "makita", "makikita", "lahat", "tanan"], "fact": {"tl": "Ang lahat ng bagay sa paligid mo — hangin, tubig, bato, at maging ikaw — ay gawa sa napakaliliit na piraso na tinatawag na atom. Napakaliit ng atom kaya hindi natin ito nakikita kahit sa karaniwang mikroskopyo.", "en": "Everything around you — air, water, rock, and even you — is made of extremely tiny pieces called atoms. Atoms are so small that we cannot see them, even with an ordinary microscope.", "bis": "Ang tanang butang sa imong palibot — hangin, tubig, bato, ug bisan ikaw — hinimo sa gagmay kaayo nga piraso nga gitawag og atom. Gamay ra kaayo ang atom maong dili nato kini makita, bisan sa ordinaryong mikroskopyo."}, "source": "AAAS BSL Ch.4D (4D/M1a, 4D/E3)", "generator": "claude-workflow", "reviewed": false},
  {"id": "element-pure-substance-g5", "domain": "MATTER", "topic": "what an element is", "grades": [5, 6], "terms": ["element", "elemento", "pure", "purong", "putli", "iisang uri", "usa ka klase", "isang klase", "atom", "sangkap", "sustansya", "building block", "oxygen", "carbon", "gold", "bakal", "puthaw"], "fact": {"tl": "Ang element ay isang purong sangkap na gawa sa iisang uri lang ng atom. Ang oxygen, carbon, gold (ginto), at iron (bakal) ay mga halimbawa ng element.", "en": "An element is a pure substance made of only one kind of atom. Oxygen, carbon, gold, and iron are examples of elements.", "bis": "Ang element usa ka putli nga sustansya nga hinimo sa usa ra ka klase nga atom. Ang oxygen, carbon, gold (bulawan), ug iron (puthaw) mga pananglitan sa element."}, "source": "AAAS BSL Ch.4D (4D/M5)", "generator": "claude-workflow", "reviewed": false},
  {"id": "element-limited-number-g6", "domain": "MATTER", "topic": "there are about 100 elements", "grades": [5, 6, 7], "terms": ["element", "elemento", "mga 100", "about 100", "isandaan", "bilang", "gidaghanon", "limitado", "limitadong", "building block", "tanang butang", "lahat ng bagay", "milyon", "millions", "materyales"], "fact": {"tl": "May mga 100 lang na uri ng element, pero kapag pinagsama-sama ang mga ito sa iba't ibang paraan, nabubuo ang milyon-milyong magkakaibang bagay sa mundo.", "en": "There are only about 100 kinds of elements, but by combining them in different ways, millions of different materials in the world are formed.", "bis": "Mga 100 ra ka klase sa element, apan kung sagolon kini sa lain-laing paagi, makaporma og minilyon nga lain-laing butang sa kalibutan."}, "source": "AAAS BSL Ch.4D (4D/M5, 4D/E4b)", "generator": "claude-workflow", "reviewed": false},
  {"id": "molecule-atoms-joined-g5", "domain": "MATTER", "topic": "what a molecule is", "grades": [5, 6], "terms": ["molecule", "molekula", "atom", "magkadikit", "nagkadikit", "magkakabit", "grupo", "group", "pinagsama", "gisagol", "gisumpay", "dugtong", "tubig", "water", "nagkahiusa", "joined"], "fact": {"tl": "Ang molecule ay grupo ng dalawa o higit pang atom na magkakabit. Halimbawa, ang isang molekula ng tubig ay gawa sa tatlong atom na magkadikit.", "en": "A molecule is a group of two or more atoms joined together. For example, one molecule of water is made of three atoms stuck together.", "bis": "Ang molecule usa ka grupo sa duha o sobra pa nga atom nga nagkadikit. Pananglitan, ang usa ka molekula sa tubig hinimo sa tulo ka atom nga nagdugtong."}, "source": "AAAS BSL Ch.4D (4D/M1cd)", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-made-of-hydrogen-oxygen-g5", "domain": "MATTER", "topic": "water is made of hydrogen and oxygen", "grades": [5, 6], "terms": ["tubig", "water", "H2O", "hydrogen", "oxygen", "molekula", "molecule", "atom", "pinagsama", "gisagol", "binubuo", "hinimo", "dalawang", "duha", "element", "gawa"], "fact": {"tl": "Ang tubig ay tinatawag na H₂O dahil ang bawat molekula nito ay gawa sa dalawang atom ng hydrogen at isang atom ng oxygen na magkadikit.", "en": "Water is called H₂O because each of its molecules is made of two hydrogen atoms and one oxygen atom stuck together.", "bis": "Ang tubig gitawag og H₂O kay ang matag molekula niini hinimo sa duha ka atom sa hydrogen ug usa ka atom sa oxygen nga nagkadikit."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "compound-new-substance-kid-g6", "domain": "MATTER", "topic": "compounds have new properties", "grades": [5, 6], "terms": ["compound", "kompound", "pinagsama", "gisagol", "bagong", "bag-ong", "properties", "katangian", "kabtangan", "iba", "lahi", "element", "tubig", "water", "asin", "salt", "new"], "fact": {"tl": "Kapag nagsama ang dalawa o higit pang element, nabubuo ang compound na may bagong katangian — gaya ng tubig na gawa sa dalawang gas (hydrogen at oxygen) pero likido at maiinom.", "en": "When two or more elements combine, they form a compound with new properties — like water, made from two gases (hydrogen and oxygen) yet is a drinkable liquid.", "bis": "Kung magsagol ang duha o sobra pa nga element, maporma ang compound nga adunay bag-ong kinaiya — sama sa tubig nga hinimo sa duha ka gas (hydrogen ug oxygen) apan likido ug mainom."}, "source": "AAAS BSL Ch.4D (4D/E4a)", "generator": "claude-workflow", "reviewed": false},
  {"id": "oxygen-gas-we-breathe-g4", "domain": "MATTER", "topic": "oxygen is the gas we breathe", "grades": [3, 4, 5], "terms": ["oxygen", "oksiheno", "hangin", "air", "hininga", "ginhawa", "huminga", "moginhawa", "gas", "mabuhay", "mabuhi", "element", "kailangan", "kinahanglan", "walang kulay", "walay kolor"], "fact": {"tl": "Ang oxygen ay isang element na walang kulay na gas sa hangin. Ito ang gas na hinihinga natin para mabuhay.", "en": "Oxygen is an element that is a colorless gas in the air. It is the gas we breathe to stay alive.", "bis": "Ang oxygen usa ka element nga walay kolor nga gas sa hangin. Mao kini ang gas nga atong giginhawa aron mabuhi."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.4B", "generator": "claude-workflow", "reviewed": false},
  {"id": "oxygen-needed-for-fire-g5", "domain": "MATTER", "topic": "oxygen is needed for fire", "grades": [4, 5, 6], "terms": ["oxygen", "oksiheno", "apoy", "kalayo", "fire", "sunog", "kandila", "candle", "mamatay", "mapalong", "takpan", "taboni", "nasusunog", "masunog", "element", "kailangan"], "fact": {"tl": "Kailangan ng apoy ang oxygen para magpatuloy. Kapag tinakpan mo ang nagliliyab na kandila ng baso, mauubos ang oxygen sa loob at mamamatay ang apoy.", "en": "Fire needs oxygen to keep burning. If you cover a burning candle with a glass, the oxygen inside runs out and the flame goes out.", "bis": "Ang kalayo nagkinahanglan og oxygen aron magpadayon. Kung taboni nimo ang nagsiga nga kandila og baso, mahurot ang oxygen sa sulod ug mapalong ang kalayo."}, "source": "AAAS BSL Ch.4D (chemical change); NRC PS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "carbon-in-living-things-g5", "domain": "MATTER", "topic": "carbon is in all living things", "grades": [5, 6], "terms": ["carbon", "karbon", "element", "buhay", "living", "tao", "hayop", "tanom", "halaman", "plants", "animals", "katawan", "lawas", "pagkain", "food", "kahoy", "wood", "uling", "charcoal", "binubuo"], "fact": {"tl": "Ang carbon ay isang element na matatagpuan sa lahat ng buhay na bagay — sa mga halaman, hayop, at sa katawan mo. Karbon din ang nasa uling at sa lapis na ginagamit mo.", "en": "Carbon is an element found in all living things — in plants, animals, and your own body. Carbon is also what charcoal and pencil lead are made of.", "bis": "Ang carbon usa ka element nga makita sa tanang buhi nga butang — sa mga tanom, hayop, ug sa imong lawas. Carbon usab ang anaa sa uling ug sa lapis nga imong gigamit."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.5", "generator": "claude-workflow", "reviewed": false},
  {"id": "carbon-diamond-and-graphite-g6", "domain": "MATTER", "topic": "diamond and graphite are both carbon", "grades": [6, 7], "terms": ["carbon", "karbon", "diamante", "diamond", "brilyante", "graphite", "lapis", "pencil", "matigas", "gahi", "malambot", "humok", "pareho", "pareha", "atom", "ayos", "arrangement", "kulay"], "fact": {"tl": "Ang diamante at ang itim na laman ng lapis (graphite) ay parehong gawa lamang sa carbon — magkaiba lang sila dahil sa kung paano nakaayos ang mga atom: matigas ang diamante, malambot ang graphite.", "en": "Diamond and the black part of a pencil (graphite) are both made only of carbon — they differ only because of how the atoms are arranged: diamond is hard, graphite is soft.", "bis": "Ang diamante ug ang itom nga sulod sa lapis (graphite) parehong hinimo lang sa carbon — lahi lang sila tungod sa kung giunsa pagkahan-ay ang mga atom: gahi ang diamante, humok ang graphite."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "gold-shiny-does-not-rust-g5", "domain": "MATTER", "topic": "gold is shiny and does not rust", "grades": [4, 5, 6], "terms": ["gold", "ginto", "bulawan", "element", "metal", "makintab", "sinaw", "kinang", "kalawang", "taya", "rust", "hindi", "dili", "alahas", "jewelry", "mahalaga", "mahal", "precious", "mananatili"], "fact": {"tl": "Ang gold (ginto) ay isang metal na element na makintab at hindi kinakalawang, kaya nananatili itong maganda nang napakatagal. Kaya ginagamit ito sa alahas at barya.", "en": "Gold is a metal element that is shiny and does not rust, so it stays beautiful for a very long time. That is why it is used in jewelry and coins.", "bis": "Ang gold (bulawan) usa ka metal nga element nga sinaw ug dili matayaan, maong magpabilin kining nindot sa dugay nga panahon. Mao nga gigamit kini sa alahas ug sinsilyo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "iron-strong-magnetic-metal-g5", "domain": "MATTER", "topic": "iron is a strong magnetic metal", "grades": [4, 5, 6], "terms": ["iron", "bakal", "puthaw", "metal", "element", "matibay", "lig-on", "matigas", "magnet", "magnetiko", "nakukuha", "madani", "tulay", "bridge", "gusali", "sasakyan", "makintab"], "fact": {"tl": "Ang iron (bakal) ay isang matibay na metal na element na nadadani ng magnet. Dahil matibay ito, ginagamit ang bakal sa pagtatayo ng mga tulay, gusali, at sasakyan.", "en": "Iron is a strong metal element that is attracted by a magnet. Because it is strong, iron is used to build bridges, buildings, and vehicles.", "bis": "Ang iron (puthaw) usa ka lig-on nga metal nga element nga madani sa magnet. Tungod kay lig-on kini, gigamit ang puthaw sa paghimo og mga taytayan, building, ug sakyanan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "iron-in-blood-g6", "domain": "LIVING_THINGS", "topic": "iron in your blood", "grades": [5, 6, 7], "terms": ["iron", "bakal", "puthaw", "dugo", "blood", "pula", "red", "oxygen", "element", "katawan", "lawas", "kailangan", "kinahanglan", "cell", "red blood cell", "carries", "modala", "kulay"], "fact": {"tl": "May kaunting iron (bakal) sa loob ng dugo mo. Tumutulong ito sa pulang dugo na magdala ng oxygen sa buong katawan, kaya kailangan ng katawan ng pagkaing mayaman sa iron.", "en": "There is a small amount of iron inside your blood. It helps red blood carry oxygen around your body, which is why your body needs iron-rich food.", "bis": "Adunay gamay nga iron (puthaw) sa sulod sa imong dugo. Motabang kini sa pula nga dugo sa pagdala og oxygen sa tibuok lawas, mao nga ang lawas nagkinahanglan og pagkaong daghan og iron."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.6", "generator": "claude-workflow", "reviewed": false},
  {"id": "periodic-table-list-of-elements-g6", "domain": "MATTER", "topic": "the periodic table", "grades": [6, 7], "terms": ["periodic table", "talahanayan", "lamesa", "listahan", "listing", "elements", "elemento", "nakaayos", "gihan-ay", "ayos", "hanay", "mahanap", "makita", "tsart", "chart", "scientist", "siyentista"], "fact": {"tl": "Ang periodic table ay isang malaking tsart kung saan nakaayos ang lahat ng kilalang element. Tinulungan nito ang mga siyentista na makita kung anong mga element ang magkakatulad ang katangian.", "en": "The periodic table is a big chart where all the known elements are arranged. It helps scientists see which elements have similar properties.", "bis": "Ang periodic table usa ka dako nga tsart diin gihan-ay ang tanang nailhan nga element. Motabang kini sa mga siyentista nga makita kung unsang mga element ang managsama og kinaiya."}, "source": "AAAS BSL Ch.4D (4D/H6)", "generator": "claude-workflow", "reviewed": false},
  {"id": "element-symbols-g6", "domain": "MATTER", "topic": "elements have short symbols", "grades": [6, 7], "terms": ["symbol", "simbolo", "letra", "letter", "element", "elemento", "O", "C", "Fe", "Au", "pangalan", "ngalan", "maikli", "mubo", "sulat", "short", "oxygen", "carbon", "iron", "gold"], "fact": {"tl": "Bawat element ay may maikling simbolo na isa o dalawang letra — halimbawa, O para sa oxygen, C para sa carbon, Fe para sa iron, at Au para sa gold. Ginagamit ito ng mga siyentista para mabilis na isulat ang mga element.", "en": "Each element has a short symbol of one or two letters — for example, O for oxygen, C for carbon, Fe for iron, and Au for gold. Scientists use these to write elements quickly.", "bis": "Ang matag element adunay mubo nga simbolo nga usa o duha ka letra — pananglitan, O para sa oxygen, C para sa carbon, Fe para sa iron, ug Au para sa gold. Gigamit kini sa mga siyentista aron paspas masulat ang mga element."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hydrogen-lightest-element-g6", "domain": "MATTER", "topic": "hydrogen is the lightest element", "grades": [6, 7], "terms": ["hydrogen", "hidroheno", "element", "pinakamagaan", "kinagaanan", "gaan", "gas", "lobo", "balloon", "lumulutang", "molutaw", "araw", "sun", "bituin", "star", "tubig", "water", "unang"], "fact": {"tl": "Ang hydrogen ay ang pinakamagaan at pinakasimpleng element. Ito ang pinakakaraniwang element sa buong uniberso at bahagi ng tubig at ng mga bituin tulad ng araw.", "en": "Hydrogen is the lightest and simplest element. It is the most common element in the whole universe and is part of water and of stars like the sun.", "bis": "Ang hydrogen mao ang kinagaanan ug kinasimplehan nga element. Mao kini ang labing komon nga element sa tibuok uniberso ug kabahin sa tubig ug sa mga bituon sama sa adlaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "atoms-too-small-to-see-g5", "domain": "MATTER", "topic": "atoms are incredibly small", "grades": [5, 6], "terms": ["atom", "atomo", "maliit", "gamay", "liit", "napakaliit", "gagmay", "buhangin", "sand", "grain", "butil", "milyon", "millions", "bilyon", "mikroskopyo", "microscope", "makita", "makikita"], "fact": {"tl": "Napakaliit ng atom kaya kahit ang isang maliit na butil ng buhangin ay may bilyun-bilyong atom sa loob. Hindi natin sila nakikita nang isa-isa.", "en": "Atoms are so small that even a single tiny grain of sand has billions of atoms inside it. We cannot see them one by one.", "bis": "Gamay ra kaayo ang atom maong bisan ang usa ka gamay nga lugas sa balas adunay binilyon nga atom sa sulod. Dili nato sila makita nga tinagsa."}, "source": "AAAS BSL Ch.4D (4D/M1a)", "generator": "claude-workflow", "reviewed": false},
  {"id": "same-element-same-atoms-g6", "domain": "MATTER", "topic": "atoms of one element are alike", "grades": [6, 7], "terms": ["atom", "element", "elemento", "magkapareho", "managsama", "pareho", "pareha", "magkaiba", "lahi", "managlahi", "gold", "carbon", "oxygen", "klase", "kind", "uri", "iba't iba"], "fact": {"tl": "Magkakapareho ang lahat ng atom ng iisang element — magkapareho ang lahat ng atom ng gold, at magkapareho ang lahat ng atom ng carbon. Pero magkaiba ang atom ng iba't ibang element.", "en": "All the atoms of one element are alike — every gold atom is alike, and every carbon atom is alike. But atoms of different elements are different from each other.", "bis": "Managsama ang tanang atom sa usa ka element — managsama ang tanang atom sa gold, ug managsama ang tanang atom sa carbon. Apan managlahi ang atom sa lain-laing element."}, "source": "AAAS BSL Ch.4D (4D/M1b)", "generator": "claude-workflow", "reviewed": false},
  {"id": "matter-made-of-particles-magnify-g4", "domain": "MATTER", "topic": "matter is made of tiny parts", "grades": [4, 5], "terms": ["matter", "bagay", "butang", "piraso", "parts", "bahin", "maliit", "gamay", "magnifying glass", "lente", "mikroskopyo", "makita", "makikita", "laman", "mga parte", "powder", "pulbos", "asin"], "fact": {"tl": "Ang mga bagay ay gawa sa napakaliliit na piraso na minsan ay masyadong maliit para makita ng mata. Ang ibang piraso, gaya ng butil ng asin, ay makikita lang gamit ang magnifying glass.", "en": "Things are made of very tiny parts that are sometimes too small for the eye to see. Some parts, like grains of salt, can be seen only with a magnifying glass.", "bis": "Ang mga butang hinimo sa gagmay kaayo nga piraso nga usahay gamay ra kaayo para makita sa mata. Ang ubang piraso, sama sa lugas sa asin, makita lang gamit ang magnifying glass."}, "source": "AAAS BSL Ch.4D (4D/E3)", "generator": "claude-workflow", "reviewed": false},
  {"id": "atoms-rearrange-not-disappear-g5", "domain": "MATTER", "topic": "atoms are not created or destroyed", "grades": [5, 6], "terms": ["atom", "matter", "bagay", "butang", "mawala", "mawagtang", "nawala", "nagkaroon", "biglang", "disappear", "appear", "binago", "gisagol", "gibahin", "rearrange", "timbang", "gibug-aton", "weight", "total", "kabuuan"], "fact": {"tl": "Hindi basta nawawala o biglang lumilitaw ang matter. Kapag may nagbago, hindi nawawala ang mga atom — nag-aayos lang sila sa bagong paraan, kaya pareho lang ang kabuuang timbang.", "en": "Matter does not just disappear or suddenly appear. When something changes, the atoms are not lost — they only rearrange in a new way, so the total weight stays the same.", "bis": "Ang matter dili lang basta mawala o kalit motungha. Kung adunay mausab, dili mawala ang mga atom — naghan-ay lang sila sa bag-ong paagi, maong pareho ra ang kinatibuk-ang gibug-aton."}, "source": "AAAS BSL Ch.4D (4D/E2, 4D/E5, 4D/M7b)", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-three-states-same-molecules-g5", "domain": "MATTER", "topic": "ice water and steam are the same molecules", "grades": [5, 6], "terms": ["tubig", "water", "yelo", "ice", "singaw", "steam", "vapor", "alisngaw", "molekula", "molecule", "pareho", "pareha", "H2O", "solid", "liquid", "gas", "estado", "state", "nagbabago", "mausab"], "fact": {"tl": "Ang yelo, likidong tubig, at singaw ay gawa sa parehong molekula ng tubig (H₂O) — nagbabago lang kung gaano kabilis gumalaw ang mga molekula kapag pinainit o pinalamig.", "en": "Ice, liquid water, and steam are all made of the same water molecules (H₂O) — only how fast the molecules move changes when it is heated or cooled.", "bis": "Ang yelo, likidong tubig, ug singaw parehong hinimo sa molekula sa tubig (H₂O) — ang mausab lang kung unsa ka paspas molihok ang mga molekula kung initon o bugnawon."}, "source": "AAAS BSL Ch.4B (4B/E3); 4D/M3", "generator": "claude-workflow", "reviewed": false},
  {"id": "carbon-dioxide-molecule-g5", "domain": "MATTER", "topic": "carbon dioxide molecule", "grades": [5, 6], "terms": ["carbon dioxide", "CO2", "molekula", "molecule", "carbon", "oxygen", "atom", "hininga", "ginhawa", "nilalabas", "ibinubuga", "gibuga", "halaman", "tanom", "soda", "bula", "gas", "hangin"], "fact": {"tl": "Ang carbon dioxide (CO₂) ay isang molekula na gawa sa isang carbon atom at dalawang oxygen atom. Ito ang gas na ibinubuga natin kapag huminga at ginagamit ng mga halaman sa photosynthesis.", "en": "Carbon dioxide (CO₂) is a molecule made of one carbon atom and two oxygen atoms. It is the gas we breathe out and that plants use in photosynthesis.", "bis": "Ang carbon dioxide (CO₂) usa ka molekula nga hinimo sa usa ka carbon atom ug duha ka oxygen atom. Mao kini ang gas nga atong gibuga kung moginhawa ug gigamit sa mga tanom sa photosynthesis."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.5", "generator": "claude-workflow", "reviewed": false},
  {"id": "metals-vs-nonmetals-kid-g6", "domain": "MATTER", "topic": "metals and nonmetals", "grades": [6, 7], "terms": ["metal", "nonmetal", "element", "makintab", "sinaw", "matibay", "lig-on", "kuryente", "elektrisidad", "init", "heat", "conduct", "nagpapadaloy", "nagpadala", "bakal", "gold", "oxygen", "carbon", "tunog"], "fact": {"tl": "Maraming element ay metal — makintab, matibay, at nagpapadaloy ng init at kuryente, gaya ng bakal at gold. Ang ilang element ay nonmetal — kadalasang hindi nagpapadaloy ng kuryente, gaya ng oxygen at carbon.", "en": "Many elements are metals — shiny, strong, and they conduct heat and electricity, like iron and gold. Some elements are nonmetals — usually they do not conduct electricity, like oxygen and carbon.", "bis": "Daghang element kay metal — sinaw, lig-on, ug nagpadala og init ug kuryente, sama sa puthaw ug gold. Ang ubang element kay nonmetal — kasagaran dili magpadala og kuryente, sama sa oxygen ug carbon."}, "source": "AAAS BSL Ch.4D; DepEd Science CG", "generator": "claude-workflow", "reviewed": false},
  {"id": "salt-from-two-elements-g5", "domain": "MATTER", "topic": "table salt is a compound", "grades": [5, 6], "terms": ["asin", "salt", "table salt", "sodium", "chlorine", "element", "compound", "kompound", "pinagsama", "gisagol", "ligtas", "luwas", "makakain", "kaonon", "lason", "poison", "gas", "metal", "bagong"], "fact": {"tl": "Ang asin sa mesa ay isang compound na gawa sa dalawang element: sodium (isang metal) at chlorine (isang gas). Magkahiwalay, mapanganib sila, pero pinagsama, nabubuo ang ligtas na asin na kinakain natin.", "en": "Table salt is a compound made of two elements: sodium (a metal) and chlorine (a gas). Apart, they are dangerous, but combined they form the safe salt we eat.", "bis": "Ang asin sa lamesa usa ka compound nga hinimo sa duha ka element: sodium (usa ka metal) ug chlorine (usa ka gas). Bulag, delikado sila, apan kung magsagol maporma ang luwas nga asin nga atong kaonon."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.4D (4D/E4a)", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-gold-used-jewelry-g5", "domain": "MATTER", "topic": "why gold is used for jewelry", "grades": [4, 5, 6], "terms": ["gold", "ginto", "bulawan", "alahas", "jewelry", "singsing", "ring", "kwintas", "makintab", "sinaw", "hindi nasisira", "dili madunot", "kalawang", "taya", "rust", "mahalaga", "mahal", "element", "metal"], "fact": {"tl": "Ginagamit ang gold sa alahas dahil hindi ito kinakalawang ni nasisira, kaya nananatiling makintab kahit lumipas ang maraming taon. Kaya napakahalaga at mahal nito.", "en": "Gold is used for jewelry because it does not rust or spoil, so it stays shiny even after many years. That is why it is so precious and valuable.", "bis": "Gigamit ang gold sa alahas kay dili kini matayaan o madunot, maong magpabilin nga sinaw bisan molabay ang daghang tuig. Mao nga bililhon kaayo ug mahal kini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "oxygen-from-plants-g5", "domain": "MATTER", "topic": "plants make the oxygen we breathe", "grades": [4, 5, 6], "terms": ["oxygen", "oksiheno", "halaman", "tanom", "plants", "puno", "kahoy", "trees", "photosynthesis", "ginagawa", "gibuhat", "nilalabas", "gibuga", "hangin", "air", "hininga", "ginhawa", "gas", "element"], "fact": {"tl": "Karamihan ng oxygen sa hangin ay gawa ng mga halaman, puno, at maliliit na halaman sa dagat sa pamamagitan ng photosynthesis. Kaya ang pag-aalaga ng mga puno at karagatan ay nakakatulong sa malinis na hanging hinihinga natin.", "en": "Most of the oxygen in the air is made by plants, trees, and tiny plants in the sea through photosynthesis. So caring for trees and oceans helps keep the air we breathe clean.", "bis": "Kadaghanan sa oxygen sa hangin gibuhat sa mga tanom, kahoy, ug gagmayng tanom sa dagat pinaagi sa photosynthesis. Mao nga ang pag-atiman sa mga kahoy ug kadagatan makatabang nga limpyo ang hangin nga atong giginhawa."}, "source": "AAAS BSL Ch.5; NRC LS1.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "different-arrangements-different-stuff-g6", "domain": "MATTER", "topic": "arrangement of atoms makes different materials", "grades": [6, 7], "terms": ["atom", "element", "ayos", "arrangement", "pagkakaayos", "pagkahan-ay", "pinagsama", "gisagol", "iba", "lahi", "magkaiba", "materyales", "materials", "bagay", "butang", "milyon", "millions", "building block", "paraan"], "fact": {"tl": "Iilang uri lang ng atom ang umiiral, pero dahil sa iba't ibang paraan ng pagsasama at pagkakaayos ng mga ito, nabubuo ang napakaraming magkakaibang materyales sa paligid natin.", "en": "Only a few kinds of atoms exist, but because of the many ways they can combine and be arranged, a huge variety of different materials around us is formed.", "bis": "Pipila ra ka klase sa atom ang anaa, apan tungod sa daghang paagi sa pagsagol ug pagkahan-ay niini, maporma ang daghan kaayong lain-laing materyales sa atong palibot."}, "source": "AAAS BSL Ch.4D (4D/M1cd, 4D/E4b)", "generator": "claude-workflow", "reviewed": false},
  {"id": "light-travels-straight-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "light travels in straight lines", "grades": [3, 4, 5], "terms": ["liwanag", "ilaw", "tuwid", "dumadaan", "diretso", "kahaba", "light", "travels", "straight", "line", "kahayag", "suga", "tul-id", "molabay", "naglakaw"], "fact": {"tl": "Ang liwanag ay naglalakbay sa tuwid na linya hangga't walang humaharang dito.", "en": "Light travels in straight lines until something blocks or bends it.", "bis": "Ang kahayag mobiyahe sa tul-id nga linya hangtod nga adunay mobabag o moliko niini."}, "source": "NRC PS4.B; AAAS BSL Ch.4F", "generator": "claude-workflow", "reviewed": false},
  {"id": "how-we-see-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "how we see things", "grades": [3, 4, 5], "terms": ["nakikita", "makita", "paano", "mata", "liwanag", "pumapasok", "bumabalik", "tumatama", "see", "eye", "light", "reflect", "kahayag", "makakita", "mosulod", "mobalik", "ngano"], "fact": {"tl": "Nakikita natin ang isang bagay kapag may liwanag na tumama dito, bumalik, at pumasok sa ating mga mata.", "en": "We see an object when light bounces off it and enters our eyes.", "bis": "Makakita kita sa usa ka butang kung adunay kahayag nga motama niini, mobalik, ug mosulod sa atong mga mata."}, "source": "AAAS BSL Ch.6C; NRC LS1.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "light-sources-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "sources of light", "grades": [3, 4], "terms": ["pinagmumulan", "gumagawa", "liwanag", "araw", "apoy", "bombilya", "kandila", "source", "light", "sun", "fire", "bulb", "tinubdan", "kahayag", "adlaw", "kalayo", "naghatag"], "fact": {"tl": "Ang ilang bagay tulad ng araw, apoy, kandila, at bombilya ay gumagawa ng sarili nilang liwanag.", "en": "Some things such as the sun, fire, candles, and light bulbs make their own light.", "bis": "Ang ubang butang sama sa adlaw, kalayo, kandila, ug bombilya naghimo sa ilang kaugalingong kahayag."}, "source": "AAAS BSL Ch.4F; DepEd G3 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-main-light-g4", "domain": "EARTH_SPACE", "topic": "the sun is earth's main light source", "grades": [4, 5], "terms": ["araw", "pangunahing", "pinagmumulan", "liwanag", "mundo", "init", "bituin", "sun", "main", "light", "earth", "star", "heat", "adlaw", "nag-unang", "tinubdan", "kahayag", "kalibutan", "kainit", "bitoon"], "fact": {"tl": "Ang araw ang pangunahing pinagmumulan ng liwanag at init para sa Mundo, at ito ay isang bituin.", "en": "The sun is Earth's main source of light and heat, and it is a star.", "bis": "Ang adlaw mao ang nag-unang tinubdan sa kahayag ug kainit alang sa Kalibutan, ug kini usa ka bitoon."}, "source": "NRC ESS1.B; AAAS BSL Ch.4B", "generator": "claude-workflow", "reviewed": false},
  {"id": "opaque-transparent-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "opaque transparent translucent materials", "grades": [4, 5, 6], "terms": ["dumadaan", "nadadaanan", "liwanag", "salamin", "makapal", "transparent", "opaque", "translucent", "light", "pass", "through", "clear", "kahayag", "molabay", "tin-aw", "baga", "bildo", "matin-aw"], "fact": {"tl": "Ang liwanag ay madaling dumadaan sa transparent na bagay tulad ng malinaw na bildo, bahagyang dumadaan sa translucent, at hindi dumadaan sa opaque tulad ng kahoy.", "en": "Light passes easily through transparent things like clear glass, partly through translucent things, and not at all through opaque things like wood.", "bis": "Ang kahayag dali nga molabay sa transparent nga butang sama sa tin-aw nga bildo, partial sa translucent, ug dili gyud molabay sa opaque sama sa kahoy."}, "source": "AAAS BSL Ch.4F; DepEd G4 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "shadow-formation-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "how shadows form", "grades": [3, 4], "terms": ["anino", "nabubuo", "humaharang", "liwanag", "bagay", "madilim", "shadow", "form", "block", "light", "dark", "landong", "mobabag", "kahayag", "ngitngit", "mabuo", "gisanta"], "fact": {"tl": "Nabubuo ang anino kapag may bagay na humaharang sa liwanag, kaya nagkakaroon ng madilim na lugar sa likod nito.", "en": "A shadow forms when an object blocks light, leaving a dark area behind it.", "bis": "Mabuo ang landong kung adunay butang nga mobabag sa kahayag, mao nga adunay ngitngit nga dapit sa luyo niini."}, "source": "AAAS BSL Ch.4F; DepEd G3 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "shadow-size-changes-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "shadows change size and direction", "grades": [4, 5], "terms": ["anino", "laki", "habang", "araw", "gumagalaw", "umaga", "hapon", "mahaba", "maikli", "shadow", "size", "longer", "shorter", "sun", "landong", "gidak-on", "mausab", "adlaw", "molihok", "taas", "mubo", "buntag", "hapon"], "fact": {"tl": "Nagbabago ang laki at direksyon ng anino habang gumagalaw ang araw sa langit — mas mahaba ito sa umaga at hapon, at mas maikli sa tanghali.", "en": "A shadow changes size and direction as the sun moves across the sky — longer in the morning and afternoon, shorter at noon.", "bis": "Mausab ang gidak-on ug direksyon sa landong samtang molihok ang adlaw sa langit — mas taas kini sa buntag ug hapon, mas mubo sa udto."}, "source": "AAAS BSL Ch.4F; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "reflection-mirror-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "reflection of light", "grades": [4, 5, 6], "terms": ["liwanag", "bumabalik", "tumatalbog", "makinis", "salamin", "mirror", "reflect", "reflection", "bounce", "kahayag", "mobalik", "mosalbog", "hapsay", "pagbalik"], "fact": {"tl": "Ang reflection ay kapag ang liwanag ay tumatalbog pabalik mula sa isang makinis na ibabaw tulad ng salamin.", "en": "Reflection is when light bounces back off a smooth surface such as a mirror.", "bis": "Ang reflection mao kung ang kahayag mosalbog balik gikan sa usa ka hapsay nga nawong sama sa salamin."}, "source": "NRC PS4.B; AAAS BSL Ch.4F", "generator": "claude-workflow", "reviewed": false},
  {"id": "plane-mirror-image-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "flat mirror image is reversed", "grades": [5, 6, 7], "terms": ["salamin", "patag", "larawan", "baliktad", "kaliwa", "kanan", "mirror", "flat", "plane", "image", "reversed", "left", "right", "hulagway", "balitad", "wala", "tuo", "baliskad"], "fact": {"tl": "Sa patag na salamin, ang larawan mo ay kasinglaki mo ngunit baliktad ang kaliwa at kanan.", "en": "In a flat mirror, your image is the same size as you but left and right appear reversed.", "bis": "Sa patag nga salamin, ang imong hulagway parehas og gidak-on nimo apan baliskad ang wala ug tuo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "refraction-light-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "refraction of light", "grades": [6, 7, 8], "terms": ["liwanag", "lumiliko", "bumabaluktot", "dumadaan", "tubig", "bildo", "refract", "refraction", "bend", "light", "water", "glass", "kahayag", "moliko", "mobaliko", "molabay", "pagbaliko"], "fact": {"tl": "Ang refraction ay ang pagliko ng liwanag kapag ito ay dumadaan mula sa isang materyal patungo sa iba, tulad ng mula hangin patungong tubig.", "en": "Refraction is the bending of light as it passes from one material into another, such as from air into water.", "bis": "Ang refraction mao ang pagliko sa kahayag samtang kini molabay gikan sa usa ka materyal ngadto sa lain, sama sa gikan sa hangin ngadto sa tubig."}, "source": "NRC PS4.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "straw-bent-water-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "straw looks bent in water", "grades": [5, 6, 7], "terms": ["straw", "baso", "tubig", "mukhang", "baluktot", "putol", "lumiliko", "liwanag", "bent", "broken", "water", "glass", "light", "murag", "baliko", "naputol", "refraction"], "fact": {"tl": "Mukhang baluktot o putol ang isang straw sa baso ng tubig dahil lumiliko ang liwanag (refraction) habang lumalabas sa tubig.", "en": "A straw in a glass of water looks bent or broken because light bends (refracts) as it leaves the water.", "bis": "Murag baliko o naputol ang straw sa baso nga tubig tungod kay moliko ang kahayag (refraction) samtang mogawas kini sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "convex-lens-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "convex lens converges light", "grades": [7, 8, 9], "terms": ["lens", "convex", "manipis", "gitna", "liwanag", "tinitipon", "nagdadako", "magnifying", "converge", "magnify", "light", "lente", "baga", "tunga", "kahayag", "gitigom", "modako"], "fact": {"tl": "Ang convex na lens ay mas makapal sa gitna at tinitipon nito ang liwanag, kaya magagamit ito para palakihin ang tingin sa isang bagay.", "en": "A convex lens is thicker in the middle and brings light together, so it can be used to magnify how an object looks.", "bis": "Ang convex nga lente mas baga sa tunga ug gitigom niini ang kahayag, mao nga magamit kini sa pagpadako sa panan-aw sa usa ka butang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "concave-lens-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "concave lens diverges light", "grades": [7, 8, 9], "terms": ["lens", "concave", "manipis", "gitna", "liwanag", "kumakalat", "pinaliliit", "diverge", "spread", "light", "smaller", "lente", "nipis", "tunga", "kahayag", "mokatag", "gipagamay"], "fact": {"tl": "Ang concave na lens ay mas manipis sa gitna at pinapakalat nito ang liwanag, kaya pinaliliit nito ang tingin sa bagay.", "en": "A concave lens is thinner in the middle and spreads light apart, so it makes an object look smaller.", "bis": "Ang concave nga lente mas nipis sa tunga ug gipakatag niini ang kahayag, mao nga gipagamay niini ang panan-aw sa butang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "eye-lens-vision-g6", "domain": "LIVING_THINGS", "topic": "the eye lens focuses light on the retina", "grades": [6, 7, 8], "terms": ["mata", "lens", "liwanag", "tinutuon", "retina", "larawan", "utak", "eye", "focus", "light", "vision", "lente", "kahayag", "gitutok", "hulagway", "utok", "panan-aw"], "fact": {"tl": "May lens ang mata na nagtutuon ng liwanag sa retina sa likod nito, at ipinapadala ng retina ang signal sa utak para makakita tayo.", "en": "The eye has a lens that focuses light onto the retina at the back, and the retina sends signals to the brain so we can see.", "bis": "Ang mata adunay lente nga nagtutok sa kahayag ngadto sa retina sa luyo niini, ug ang retina magpadala og signal sa utok aron makakita kita."}, "source": "AAAS BSL Ch.6C; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "white-light-colors-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "white light is made of colors", "grades": [5, 6, 7], "terms": ["puti", "liwanag", "kulay", "pitong", "spectrum", "prism", "white", "light", "colors", "seven", "puti", "kahayag", "kolor", "pito", "balangaw", "nabuo"], "fact": {"tl": "Ang puting liwanag ay binubuo ng maraming kulay na pinagsama-sama, at mahahati ito sa pitong kulay ng bahaghari.", "en": "White light is made of many colors mixed together, and it can be split into the seven colors of the rainbow.", "bis": "Ang puti nga kahayag gilangkuban sa daghang kolor nga gisagol, ug mabahin kini sa pito ka kolor sa balangaw."}, "source": "NRC PS4.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "prism-splits-light-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "prism splits white light", "grades": [6, 7, 8], "terms": ["prism", "bildo", "puti", "liwanag", "naghahati", "kulay", "lumiliko", "split", "spectrum", "prisma", "kahayag", "gibahin", "kolor", "moliko"], "fact": {"tl": "Kapag dumaan ang puting liwanag sa isang prism, nahahati ito sa iba't ibang kulay dahil bawat kulay ay lumiliko nang kaiba.", "en": "When white light passes through a prism, it splits into different colors because each color bends by a different amount.", "bis": "Kung molabay ang puti nga kahayag sa usa ka prisma, mabahin kini sa nagkalainlaing kolor tungod kay ang matag kolor moliko og lahi nga gidaghanon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rainbow-order-g5", "domain": "EARTH_SPACE", "topic": "order of rainbow colors", "grades": [5, 6, 7], "terms": ["bahaghari", "kulay", "pula", "kahel", "dilaw", "berde", "asul", "lila", "rainbow", "red", "orange", "yellow", "green", "blue", "violet", "balangaw", "kolor", "dalag", "lunhaw", "tapul"], "fact": {"tl": "May pitong kulay ang bahaghari sa ayos na: pula, kahel, dilaw, berde, asul, indigo, at lila.", "en": "A rainbow has seven colors in order: red, orange, yellow, green, blue, indigo, and violet.", "bis": "Ang balangaw adunay pito ka kolor sa han-ay: pula, kahel, dalag, lunhaw, asul, indigo, ug tapul."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-behind-for-rainbow-g6", "domain": "EARTH_SPACE", "topic": "sun must be behind you to see a rainbow", "grades": [6, 7], "terms": ["bahaghari", "araw", "likod", "ulan", "harap", "makita", "rainbow", "sun", "behind", "rain", "front", "see", "balangaw", "adlaw", "luyo", "atubangan"], "fact": {"tl": "Nakikita mo ang bahaghari kapag nasa likod mo ang araw at nasa harap mo ang ulan.", "en": "You see a rainbow when the sun is behind you and the rain is in front of you.", "bis": "Makita nimo ang balangaw kung ang adlaw anaa sa imong luyo ug ang ulan anaa sa imong atubangan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "object-color-reflection-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "why objects have color", "grades": [5, 6, 7], "terms": ["kulay", "bagay", "liwanag", "sinasalamin", "sinisipsip", "dahon", "berde", "color", "object", "reflect", "absorb", "leaf", "green", "kolor", "butang", "kahayag", "gibalik", "gisuyop", "dahon", "lunhaw", "ngano"], "fact": {"tl": "May kulay ang isang bagay dahil sinasalamin nito ang ilang kulay ng liwanag at sinisipsip ang iba — halimbawa, berde ang dahon dahil sinasalamin nito ang berdeng liwanag.", "en": "An object has color because it reflects some colors of light and absorbs the rest — for example, a leaf looks green because it reflects green light.", "bis": "Ang usa ka butang adunay kolor tungod kay gibalik niini ang ubang kolor sa kahayag ug gisuyop ang uban — pananglitan, lunhaw ang dahon tungod kay gibalik niini ang lunhaw nga kahayag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "black-white-objects-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "black absorbs white reflects light", "grades": [5, 6, 7], "terms": ["itim", "puti", "kulay", "sinisipsip", "sinasalamin", "liwanag", "init", "black", "white", "absorb", "reflect", "light", "heat", "itom", "kolor", "gisuyop", "gibalik", "kahayag", "kainit"], "fact": {"tl": "Sinisipsip ng itim na bagay ang lahat ng kulay ng liwanag kaya mas umiinit ito, samantalang sinasalamin ng puti ang halos lahat ng liwanag.", "en": "A black object absorbs all colors of light so it heats up more, while a white object reflects almost all the light.", "bis": "Ang itom nga butang nagsuyop sa tanang kolor sa kahayag mao nga mas moinit kini, samtang ang puti nagbalik sa halos tanang kahayag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-sky-blue-g6", "domain": "EARTH_SPACE", "topic": "why the sky is blue", "grades": [6, 7, 8], "terms": ["langit", "asul", "bughaw", "kulay", "liwanag", "hangin", "kumakalat", "scatter", "sky", "blue", "color", "light", "air", "kolor", "kahayag", "mokatag", "ngano"], "fact": {"tl": "Asul ang langit dahil ang asul na liwanag mula sa araw ay mas madaling kumalat sa mga particle ng hangin kaysa sa ibang kulay.", "en": "The sky is blue because blue light from the sun scatters more off the tiny particles in the air than other colors do.", "bis": "Asul ang langit tungod kay ang asul nga kahayag gikan sa adlaw mas dali nga mokatag sa gagmay nga partikulo sa hangin kaysa sa ubang kolor."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-sunset-red-g6", "domain": "EARTH_SPACE", "topic": "why sunsets are red and orange", "grades": [6, 7, 8], "terms": ["paglubog", "araw", "pula", "kahel", "langit", "liwanag", "kumakalat", "sunset", "red", "orange", "sky", "light", "scatter", "pagsalop", "kahayag", "mokatag", "ngano"], "fact": {"tl": "Pula at kahel ang langit kapag paglubog ng araw dahil mas malayo ang dinaanan ng liwanag, kaya nakakalat na ang asul at natitira ang pula.", "en": "The sky looks red and orange at sunset because the light travels through more air, scattering away the blue and leaving the red.", "bis": "Pula ug kahel ang langit kung pagsalop sa adlaw tungod kay mas layo ang giagian sa kahayag, mao nga nakatag na ang asul ug nahibilin ang pula."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "light-fastest-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "light is the fastest thing", "grades": [7, 8, 9, 10], "terms": ["liwanag", "bilis", "mabilis", "pinakamabilis", "kidlat", "kulog", "light", "speed", "fast", "fastest", "lightning", "thunder", "kahayag", "kakusog", "kusog", "kilat", "dalogdog", "ngano"], "fact": {"tl": "Ang liwanag ang pinakamabilis na bagay sa uniberso, kaya nauuna nating makita ang kidlat bago natin marinig ang kulog.", "en": "Light is the fastest thing in the universe, which is why we see lightning before we hear the thunder.", "bis": "Ang kahayag mao ang pinakakusog nga butang sa uniberso, mao nga makita una nato ang kilat sa dili pa nato madungog ang dalogdog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "moon-reflects-sunlight-g5", "domain": "EARTH_SPACE", "topic": "moon shines by reflecting sunlight", "grades": [5, 6, 7], "terms": ["buwan", "liwanag", "sariling", "sinasalamin", "araw", "nagniningning", "moon", "light", "own", "reflect", "sun", "shine", "bulan", "kahayag", "kaugalingon", "gibalik", "nagsidlak", "ngano"], "fact": {"tl": "Ang buwan ay walang sariling liwanag — nagniningning ito dahil sinasalamin nito ang liwanag ng araw.", "en": "The moon has no light of its own — it shines because it reflects the sun's light.", "bis": "Ang bulan walay kaugalingong kahayag — nagsidlak kini tungod kay gibalik niini ang kahayag sa adlaw."}, "source": "AAAS BSL Ch.4B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "primary-light-colors-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "mixing colored light", "grades": [7, 8], "terms": ["pula", "berde", "asul", "liwanag", "puti", "pinaghalo", "kulay", "red", "green", "blue", "light", "white", "mix", "color", "lunhaw", "kahayag", "gisagol", "kolor"], "fact": {"tl": "Kapag pinaghalo ang pula, berde, at asul na liwanag, nabubuo ang puting liwanag.", "en": "When red, green, and blue light are mixed together, they make white light.", "bis": "Kung sagolon ang pula, lunhaw, ug asul nga kahayag, mabuo ang puti nga kahayag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "light-is-energy-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "light is a form of energy", "grades": [6, 7, 8], "terms": ["liwanag", "enerhiya", "uri", "init", "halaman", "pagkain", "light", "energy", "form", "heat", "plant", "food", "kahayag", "matang", "kainit", "tanom", "pagkaon", "photosynthesis"], "fact": {"tl": "Ang liwanag ay isang uri ng enerhiya, at ginagamit ito ng mga halaman para gumawa ng kanilang sariling pagkain.", "en": "Light is a form of energy, and plants use it to make their own food.", "bis": "Ang kahayag usa ka matang sa enerhiya, ug gigamit kini sa mga tanom aron mohimo sa ilang kaugalingong pagkaon."}, "source": "NRC PS3.D; AAAS BSL Ch.4E", "generator": "claude-workflow", "reviewed": false},
  {"id": "pinhole-image-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "light through a small hole makes an upside-down image", "grades": [6, 7, 8], "terms": ["liwanag", "maliit", "butas", "larawan", "baliktad", "tuwid", "straight", "light", "small", "hole", "image", "upside-down", "kahayag", "gamay", "lungag", "hulagway", "balitad", "tul-id", "pinhole"], "fact": {"tl": "Kapag ang liwanag ay dumaan sa isang maliit na butas, nabubuo ang baliktad na larawan dahil naglalakbay ang liwanag sa tuwid na linya.", "en": "When light passes through a small hole, it makes an upside-down image because light travels in straight lines.", "bis": "Kung ang kahayag molabay sa usa ka gamay nga lungag, mabuo ang balitad nga hulagway tungod kay ang kahayag mobiyahe sa tul-id nga linya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnet-two-poles-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "magnet north and south poles", "grades": [4, 5, 6], "terms": ["magnet", "poste ng magnet", "polo", "hilaga", "timog", "amihanan", "habagatan", "north pole", "south pole", "poles", "polo sa magnet", "dulo ng magnet"], "fact": {"tl": "Ang bawat magnet ay may dalawang dulo na tinatawag na hilagang poste at timog na poste, at dito pinakamalakas ang puwersa nito.", "en": "Every magnet has two ends called the north pole and the south pole, where its pulling force is strongest.", "bis": "Ang matag magnet adunay duha ka tumoy nga gitawag amihanan nga polo ug habagatan nga polo, ug diri pinakakusgan ang gahum niini."}, "source": "AAAS 4G/E2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnet-poles-attract-repel-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "like poles repel unlike poles attract", "grades": [5, 6, 7], "terms": ["magnet", "polo", "poste", "magkaakit", "umaakit", "nagtutulak", "nagtataboy", "magkasalungat", "magkapareho", "attract", "repel", "magdani", "magsalikway", "magkabingkil", "pareho nga polo", "magkalahi nga polo"], "fact": {"tl": "Ang magkaparehong poste ng dalawang magnet ay nagtataboy, ngunit ang magkasalungat na poste ay umaakit sa isa't isa.", "en": "Like poles of two magnets push each other away, but opposite poles pull toward each other.", "bis": "Ang parehas nga polo sa duha ka magnet magsalikway sa usag usa, apan ang magkalahi nga polo magdani sa usag usa."}, "source": "AAAS 4G/E2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnet-attracts-iron-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "magnets attract iron and steel", "grades": [3, 4, 5], "terms": ["magnet", "bakal", "iron", "asero", "steel", "umaakit", "humihila", "puthaw", "salsalon", "magdani", "metal", "nikel", "kobalt", "attracts iron", "dumidikit na metal"], "fact": {"tl": "Ang magnet ay umaakit lamang sa ilang mga metal tulad ng bakal at asero, hindi sa lahat ng metal gaya ng tanso o aluminyo.", "en": "A magnet attracts only certain metals such as iron and steel, not all metals like copper or aluminum.", "bis": "Ang magnet magdani lamang sa pipila ka metal sama sa puthaw ug asero, dili sa tanan nga metal sama sa tumbaga o aluminyo."}, "source": "AAAS 4G/E2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnet-force-without-touching-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "magnets act without touching", "grades": [3, 4, 5], "terms": ["magnet", "hindi hinahawakan", "di-dinadampian", "puwersa", "lakas", "without touching", "walay hikap", "dili paghikap", "gahum", "layo", "kumikilos nang di-hinihipo", "nakahilang"], "fact": {"tl": "Ang magnet ay maaaring humila o magtulak ng bagay kahit hindi ito dinidikit, dahil may puwersa itong umaabot sa paligid.", "en": "A magnet can pull or push an object without touching it, because its force reaches across the space around it.", "bis": "Ang magnet makahaylo o makatulak sa usa ka butang bisan dili kini hikapon, kay ang gahum niini moabot sa palibot."}, "source": "AAAS 4G/P2, 4G/E2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnetic-field-invisible-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "magnetic field around a magnet", "grades": [5, 6, 7], "terms": ["magnetic field", "magnetikong larangan", "magnetikong patlang", "lugar sa palibot", "iron filings", "pilas ng bakal", "natad nga magnetiko", "kusog magnetiko", "field lines", "lugar na may puwersa"], "fact": {"tl": "Sa paligid ng bawat magnet ay may di-nakikitang magnetikong larangan kung saan nararamdaman ng ibang magnet o bakal ang puwersa nito.", "en": "Around every magnet is an invisible magnetic field, the region where another magnet or piece of iron feels its force.", "bis": "Sa palibot sa matag magnet adunay dili makita nga natad nga magnetiko, ang dapit diin mabati sa lain nga magnet o puthaw ang gahum niini."}, "source": "encyclopedia-stable consensus; AAAS 4G/E2", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-magnet-compass-g6", "domain": "EARTH_SPACE", "topic": "Earth acts like a giant magnet", "grades": [5, 6, 7], "terms": ["compass", "kompas", "Earth magnet", "magnet ang Mundo", "hilaga", "amihanan", "north", "magnetikong larangan ng Mundo", "kalibutan magnet", "nagtuturo sa hilaga", "nagtudlo sa amihanan", "needle"], "fact": {"tl": "Ang Mundo mismo ay parang isang malaking magnet, kaya ang karayom ng kompas ay laging tumutukoy sa hilaga.", "en": "The Earth itself acts like a giant magnet, which is why a compass needle always points toward the north.", "bis": "Ang Kalibutan mismo morag usa ka dako nga magnet, mao nga ang dagom sa kompas kanunay motudlo sa amihanan."}, "source": "AAAS 4G/H7; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnet-cut-still-two-poles-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "cutting a magnet makes two magnets", "grades": [6, 7, 8], "terms": ["magnet", "hinati", "putol", "two poles", "dalawang poste", "bawat piraso", "gigamay", "gitunga", "duha ka polo", "kada bahin", "bagong magnet", "cut magnet"], "fact": {"tl": "Kapag hinati mo ang isang magnet, bawat piraso ay magiging isang buong magnet na may sariling hilaga at timog na poste.", "en": "If you cut a magnet in half, each piece becomes a whole magnet with its own north and south pole.", "bis": "Kung tungaon nimo ang usa ka magnet, ang matag bahin mahimong tibuok nga magnet nga adunay kaugalingong amihanan ug habagatan nga polo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "circuit-complete-loop-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "a circuit must be a closed loop", "grades": [5, 6, 7], "terms": ["circuit", "sirkito", "kompletong daanan", "buong kawing", "saradong loop", "elektrisidad dumadaloy", "kuryente", "koryente", "tibuok nga dalan", "sirado nga sirkito", "agianan", "daloy", "closed loop"], "fact": {"tl": "Para dumaloy ang kuryente, kailangan ang isang kompletong saradong daanan na tinatawag na sirkito, mula sa baterya pabalik dito.", "en": "For electricity to flow, it needs a complete closed path called a circuit, going out from the battery and back to it.", "bis": "Aron modagayday ang kuryente, kinahanglan ang usa ka tibuok ug sirado nga agianan nga gitawag sirkito, gikan sa baterya ug mobalik niini."}, "source": "AAAS 4E/M2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "circuit-switch-opens-breaks-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "a switch opens and closes a circuit", "grades": [4, 5, 6], "terms": ["switch", "swits", "pindutan", "bukas", "sara", "open circuit", "closed circuit", "kuryente", "kuryenti", "ilaw", "suga", "buksan", "patyon", "naga-on naga-off", "putol ang daloy"], "fact": {"tl": "Ang switch ay pumuputol o nagbubukas ng sirkito; kapag sarado ito, dumadaloy ang kuryente at nagliliwanag ang ilaw.", "en": "A switch breaks or completes a circuit; when it is closed, electricity flows and the light turns on.", "bis": "Ang switch maoy mobungkag o motibuok sa sirkito; kung sirado kini, modagayday ang kuryente ug modan-ag ang suga."}, "source": "AAAS 4E/M2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "conductors-let-current-flow-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "conductors let electricity pass", "grades": [5, 6, 7], "terms": ["conductor", "konduktor", "dumadaloy", "metal", "tanso", "kopper", "bakal", "elektrisidad", "kuryente", "nagpadaloy", "magpaagi", "tumbaga", "puthaw", "molabay ang kuryente", "wire", "alambre"], "fact": {"tl": "Ang mga konduktor gaya ng tanso at iba pang metal ay nagpapadaloy ng kuryente nang madali, kaya ginagawang alambre ang mga ito.", "en": "Conductors like copper and other metals let electricity pass through easily, which is why wires are made from them.", "bis": "Ang mga konduktor sama sa tumbaga ug uban pang metal magpaagi sa kuryente dali ra, mao nga ginahimo silang alambre."}, "source": "AAAS 4G/H4, 4D/M9; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "insulators-block-current-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "insulators block electricity", "grades": [5, 6, 7], "terms": ["insulator", "insulador", "goma", "plastik", "kahoy", "salamin", "hindi nagpapadaloy", "hindi dumadaloy", "kuryente", "rubber", "plastic", "dili magpaagi", "tabunok", "hindi makakuryente", "panangga"], "fact": {"tl": "Ang mga insulador gaya ng goma at plastik ay hindi nagpapadaloy ng kuryente, kaya ito ang ibinabalot sa mga alambre para maging ligtas.", "en": "Insulators like rubber and plastic do not let electricity pass through, so they are wrapped around wires to keep us safe.", "bis": "Ang mga insulador sama sa goma ug plastik dili magpaagi sa kuryente, mao nga kini ang ginaputos sa mga alambre aron maluwas kita."}, "source": "AAAS 4G/H4; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "battery-stores-chemical-energy-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "battery stores chemical energy", "grades": [5, 6, 7], "terms": ["battery", "baterya", "kemikal na enerhiya", "chemical energy", "naiimbak", "nakaimbak", "kuryente", "elektrikal", "tinipig", "kemikal nga enerhiya", "stored energy", "pinagkukunan"], "fact": {"tl": "Ang baterya ay nag-iimbak ng kemikal na enerhiya at ginagawa itong elektrikal na enerhiya kapag ikinabit sa isang sirkito.", "en": "A battery stores chemical energy and turns it into electrical energy when it is connected in a circuit.", "bis": "Ang baterya nagtipig ug kemikal nga enerhiya ug ginahimo kining elektrikal nga enerhiya kung ikonektar sa usa ka sirkito."}, "source": "AAAS 4E/M2, 4E/M4; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "battery-two-terminals-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "battery positive and negative terminals", "grades": [5, 6, 7], "terms": ["battery", "baterya", "positibo", "negatibo", "terminal", "dulo", "plus", "minus", "positive", "negative", "tumoy", "polo sa baterya", "terminal sa baterya"], "fact": {"tl": "Ang baterya ay may dalawang dulo, ang positibo (+) at ang negatibo (−), at sa pagitan nila dumadaloy ang kuryente sa sirkito.", "en": "A battery has two ends, the positive (+) and the negative (−), and current flows through the circuit between them.", "bis": "Ang baterya adunay duha ka tumoy, ang positibo (+) ug ang negatibo (−), ug taliwala niini modagayday ang kuryente sa sirkito."}, "source": "encyclopedia-stable consensus; AAAS 4E/M2", "generator": "claude-workflow", "reviewed": false},
  {"id": "static-electricity-charge-buildup-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "static electricity from rubbing", "grades": [5, 6, 7], "terms": ["static electricity", "static", "kuryenteng static", "kuskos", "hinihimas", "pagkiskis", "globo", "buhok", "nagdidikit", "charge", "static nga kuryente", "kuskoson", "buhok motindog", "elektrisidad", "naipon nga charge"], "fact": {"tl": "Ang static na kuryente ay lumilitaw kapag dalawang bagay ay nagkiskisan, kaya naipon ang elektrikal na karga na pwedeng humila ng buhok o papel.", "en": "Static electricity appears when two things rub together, building up electric charge that can pull at hair or bits of paper.", "bis": "Ang static nga kuryente motungha kung duha ka butang magkuskos, nga maghimo ug naipon nga elektrikal nga charge nga makahaylo sa buhok o gamayng papel."}, "source": "AAAS 4G/E3, 4G/H3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "two-kinds-of-charge-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "positive and negative charges", "grades": [7, 8, 9], "terms": ["charge", "karga", "positibo", "negatibo", "positive charge", "negative charge", "umaakit", "nagtataboy", "magdani", "magsalikway", "positibong karga", "negatibong karga", "like charges", "opposite charges", "kuryente"], "fact": {"tl": "May dalawang uri ng elektrikal na karga: positibo at negatibo; ang magkaparehong karga ay nagtataboy, at ang magkasalungat ay umaakit.", "en": "There are two kinds of electric charge, positive and negative; like charges repel each other and opposite charges attract.", "bis": "Adunay duha ka matang sa elektrikal nga charge, positibo ug negatibo; ang parehas nga charge magsalikway ug ang magkalahi magdani."}, "source": "AAAS 4G/M5, 4G/H3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "charge-from-electrons-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "charge comes from gaining or losing electrons", "grades": [8, 9, 10], "terms": ["electron", "elektron", "karga", "charge", "nawawalan", "nadadagdagan", "negatibo", "positibo", "neutral", "nawad-an", "nadungagan", "balanseng karga", "gaining electrons", "losing electrons"], "fact": {"tl": "Ang isang bagay ay nagiging negatibo kapag nakakuha ito ng dagdag na elektron at positibo kapag nawalan ng elektron.", "en": "An object becomes negatively charged when it gains extra electrons and positively charged when it loses electrons.", "bis": "Ang usa ka butang mahimong negatibo kung makadawat kini ug dugang nga elektron ug positibo kung mawad-an kini ug elektron."}, "source": "AAAS 4G/H3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lightning-static-discharge-g6", "domain": "EARTH_SPACE", "topic": "lightning is a giant static discharge", "grades": [6, 7, 8], "terms": ["lightning", "kidlat", "static", "kuryente", "ulap", "charge", "kilat", "panganod", "static nga kuryente", "dako nga spark", "elektrisidad sa langit", "discharge", "kidlat sa ulan"], "fact": {"tl": "Ang kidlat ay isang napakalaking pagbuga ng static na kuryente mula sa mga ulap patungo sa lupa o sa ibang ulap.", "en": "Lightning is a giant burst of static electricity leaping from clouds to the ground or to another cloud.", "bis": "Ang kilat usa ka dako kaayo nga pagbuga sa static nga kuryente gikan sa mga panganod paingon sa yuta o sa lain nga panganod."}, "source": "encyclopedia-stable consensus; AAAS 4G/H3", "generator": "claude-workflow", "reviewed": false},
  {"id": "electromagnet-coil-wire-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "electromagnet from coil and current", "grades": [7, 8, 9], "terms": ["electromagnet", "elektromagnet", "kuryente", "kawad", "ikot", "pako", "bakal", "coil", "wire", "alambre", "nakaikot", "lilikon", "puthaw", "kuryenti", "magnet gikan sa kuryente", "current", "naka-on naga-magnet"], "fact": {"tl": "Kapag pinaikot mo ang alambre sa isang pako at pinadaluyan ng kuryente, ito ay nagiging electromagnet, isang magnet na maaaring buksan at saraduhin.", "en": "When you wind wire around an iron nail and run current through it, it becomes an electromagnet, a magnet you can switch on and off.", "bis": "Kung lilikuson nimo ang alambre palibot sa usa ka lansang ug paagian ug kuryente, mahimo kining electromagnet, usa ka magnet nga mahimong on ug off."}, "source": "AAAS 4G/M3, 4G/H5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "electromagnet-stronger-more-coils-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "making an electromagnet stronger", "grades": [7, 8, 9], "terms": ["electromagnet", "elektromagnet", "mas malakas", "dami ng ikot", "mas maraming baterya", "lakas", "coils", "stronger", "kusog", "daghan nga lilikon", "dugang baterya", "kuryente", "more current", "padaghanon ang likos"], "fact": {"tl": "Lumalakas ang electromagnet kapag dinagdagan mo ang bilang ng ikot ng alambre o ang dami ng kuryenteng dumadaloy dito.", "en": "An electromagnet gets stronger when you add more turns of wire or send more current through it.", "bis": "Ang electromagnet mas mokusog kung dugangan nimo ang gidaghanon sa likos sa alambre o ang kuryente nga moagi niini."}, "source": "AAAS 4G/M3, 4G/H5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "current-and-magnet-force-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "electric current and magnets affect each other", "grades": [7, 8, 9], "terms": ["electric current", "kuryente", "magnet", "puwersa", "force", "magkaugnay", "magkadugtong", "elektromagnetismo", "kuryenti", "gahum", "naka-apekto", "nagpapagalaw", "magkalambigit", "motor", "generator"], "fact": {"tl": "Ang dumadaloy na kuryente at ang magnet ay maaaring maglagay ng puwersa sa isa't isa, at ito ang prinsipyong pinaggagawa ng mga motor at generator.", "en": "A flowing electric current and a magnet can each exert a force on the other, which is the principle behind motors and generators.", "bis": "Ang nagdagayday nga kuryente ug ang magnet makahatag ug gahum sa usag usa, ug kini ang prinsipyo nga gigamit sa mga motor ug generator."}, "source": "AAAS 4G/M3, 4G/H5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "metals-conduct-free-electrons-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "why metals carry electric current", "grades": [8, 9, 10], "terms": ["metal", "konduktor", "elektron", "malayang elektron", "kuryente", "dumadaloy", "free electrons", "gawasnon nga elektron", "kuryenti", "moagi", "current", "galaw ng elektron"], "fact": {"tl": "Sa mga metal, may mga malayang elektron na madaling gumalaw, kaya madaling dumaloy ang kuryente sa mga ito.", "en": "In metals, some electrons are free to move easily, so an electric current can flow through them readily.", "bis": "Sa mga metal, adunay gawasnon nga mga elektron nga sayon molihok, mao nga dali nga modagayday ang kuryente niini."}, "source": "AAAS 4G/H4; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "series-circuit-one-path-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "series circuit single path", "grades": [7, 8, 9], "terms": ["series circuit", "serye", "isang daanan", "magkasunod", "ilaw namatay", "single path", "tinurok", "usa ka agianan", "magsunod", "kung maputol mawala tanan", "bombilya", "konektado nga sunod"], "fact": {"tl": "Sa isang series circuit, iisang daanan lang ang kuryente, kaya kapag naputol ang isang bahagi, namamatay ang lahat ng ilaw.", "en": "In a series circuit there is only one path for the current, so if one part breaks, all the lights go out.", "bis": "Sa usa ka series circuit usa ra ka agianan ang kuryente, mao nga kung maputol ang usa ka bahin, mapalong ang tanan nga suga."}, "source": "encyclopedia-stable consensus; AAAS 4E/M2", "generator": "claude-workflow", "reviewed": false},
  {"id": "parallel-circuit-many-paths-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "parallel circuit multiple paths", "grades": [7, 8, 9], "terms": ["parallel circuit", "parallel", "maraming daanan", "magkahiwalay", "ilaw nananatili", "many paths", "daghan nga agianan", "magkalain nga dalan", "bombilya gihapon naga-on", "bahay na kuryente", "branch"], "fact": {"tl": "Sa isang parallel circuit, may maraming magkahiwalay na daanan, kaya kahit mamatay ang isang ilaw, patuloy pa ring nagniningning ang iba.", "en": "In a parallel circuit there are several separate paths, so even if one light goes out, the others keep shining.", "bis": "Sa usa ka parallel circuit adunay daghang managlahi nga agianan, mao nga bisan mapalong ang usa ka suga, ang uban padayon nga modan-ag."}, "source": "encyclopedia-stable consensus; AAAS 4E/M2", "generator": "claude-workflow", "reviewed": false},
  {"id": "electrical-safety-water-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "electricity and water are dangerous together", "grades": [3, 4, 5], "terms": ["electrical safety", "kaligtasan sa kuryente", "tubig", "basa", "kuryente", "delikado", "huwag hawakan", "water", "wet hands", "basa nga kamot", "peligro", "kuryenti", "ayaw hikapa", "saksak", "kuryente sa basa"], "fact": {"tl": "Mapanganib ang kuryente kapag may tubig, kaya hindi dapat hawakan ang switch o saksakan gamit ang basang kamay.", "en": "Electricity is dangerous around water, so you should never touch a switch or outlet with wet hands.", "bis": "Delikado ang kuryente kung adunay tubig, mao nga dili gayud hikapon ang switch o saksakan gamit ang basa nga kamot."}, "source": "encyclopedia-stable consensus; DepEd electrical safety", "generator": "claude-workflow", "reviewed": false},
  {"id": "electrical-safety-no-outlet-fingers-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "do not poke things into outlets", "grades": [3, 4, 5], "terms": ["outlet", "saksakan", "kuryente", "huwag isuksok", "daliri", "metal", "delikado", "electric shock", "kuryenti", "ayaw isuksok", "tudlo", "kuryente makapatay", "kakuryentihan", "shock"], "fact": {"tl": "Hindi dapat isuksok ang daliri o anumang bagay na metal sa saksakan dahil maaari kang makuryente at masaktan nang malala.", "en": "You should never poke your finger or any metal object into an outlet, because you could get a serious electric shock.", "bis": "Dili gayud isuksok ang imong tudlo o bisan unsang metal nga butang sa saksakan, kay mahimo kang ma-kuryente ug grabe nga masakitan."}, "source": "encyclopedia-stable consensus; DepEd electrical safety", "generator": "claude-workflow", "reviewed": false},
  {"id": "fuse-breaker-safety-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "fuses and circuit breakers protect wiring", "grades": [7, 8, 9], "terms": ["fuse", "fyus", "circuit breaker", "breaker", "sobrang kuryente", "pumuputol", "init", "sunog", "too much current", "moputol sa kuryente", "sobra nga kuryente", "kalayo", "proteksyon", "overheat"], "fact": {"tl": "Ang fuse o circuit breaker ay awtomatikong pumuputol ng kuryente kapag sobra ang dumaloy, para hindi uminit ang alambre at magdulot ng sunog.", "en": "A fuse or circuit breaker automatically cuts off the current when too much flows, so the wires do not overheat and start a fire.", "bis": "Ang fuse o circuit breaker awtomatik nga moputol sa kuryente kung sobra ang moagi, aron dili moinit ang alambre ug makapasugod ug kalayo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "electrical-energy-transfers-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "electricity carries energy to devices", "grades": [6, 7, 8], "terms": ["electrical energy", "enerhiyang elektrikal", "kuryente", "ilaw", "init", "galaw", "naililipat", "nagdadala", "kuryenti", "suga", "kainit", "lihok", "gibalhin", "appliance", "bombilya"], "fact": {"tl": "Ang kuryente ay nagdadala ng enerhiya sa mga kagamitan, na maaaring maging liwanag sa bombilya, init sa plantsa, o galaw sa motor.", "en": "Electricity carries energy to devices, which can become light in a bulb, heat in an iron, or motion in a motor.", "bis": "Ang kuryente nagdala ug enerhiya ngadto sa mga gamit, nga mahimong kahayag sa bombilya, kainit sa plantsa, o lihok sa motor."}, "source": "AAAS 4E/M2, 4E/M4; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "generator-magnets-make-electricity-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "generators use magnets to make electricity", "grades": [7, 8, 9], "terms": ["generator", "henerator", "magnet", "umiikot", "kuryente", "nakukuryente", "spinning", "kawad", "naglihok nga magnet", "naghimo ug kuryente", "power plant", "planta", "umiikot na magnet", "turbine", "kuryenti"], "fact": {"tl": "Sa isang generator, ang mga umiikot na magnet sa tabi ng alambre ay gumagawa ng kuryente, at ganito karaniwang nalilikha ang kuryente sa mga power plant.", "en": "In a generator, spinning magnets near coils of wire produce electricity, which is how most electricity is made in power plants.", "bis": "Sa usa ka generator, ang naglihok nga mga magnet duol sa likos sa alambre maghimo ug kuryente, ug mao kini ang naandang pagmugna sa kuryente sa mga power plant."}, "source": "AAAS 4G/H5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "newton-first-law-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "Newton's first law of motion", "grades": [8, 9, 10], "terms": ["Newton", "unang batas", "first law", "inertia", "inersya", "nagpapahinga", "nakapahulay", "gumagalaw", "naglihok", "puwersa", "force", "kusog", "tumitigil", "mohunong", "patuloy na gumagalaw"], "fact": {"tl": "Ayon sa unang batas ni Newton, ang isang bagay ay mananatiling nakapahinga o patuloy na gagalaw nang tuwid sa parehong bilis hangga't walang panlabas na puwersang kumikilos dito.", "en": "Newton's first law says an object stays at rest or keeps moving straight at the same speed unless an outside force acts on it.", "bis": "Sumala sa unang balaod ni Newton, ang usa ka butang magpabilin nga nakapahulay o magpadayon sa paglihok nga tul-id sa samang katulin gawas kon adunay gawas nga kusog nga molihok niini."}, "source": "NRC PS2.A; AAAS BSL Ch.4 Motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "newton-second-law-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "Newton's second law force mass acceleration", "grades": [8, 9, 10], "terms": ["Newton", "ikalawang batas", "second law", "puwersa", "force", "kusog", "masa", "mass", "gibug-aton", "acceleration", "aselerasyon", "paspas", "mabigat", "mas mahirap pakilusin", "bug-at"], "fact": {"tl": "Ayon sa ikalawang batas ni Newton, mas malaking puwersa ang kailangan upang pabilisin ang isang mas mabigat na bagay — ang puwersa ay katumbas ng masa beses aselerasyon (F = ma).", "en": "Newton's second law says a heavier object needs a bigger force to speed it up — force equals mass times acceleration (F = ma).", "bis": "Sumala sa ikaduhang balaod ni Newton, mas dako nga kusog ang gikinahanglan aron paspason ang usa ka mas bug-at nga butang — ang kusog parehas sa masa pilo-on sa aselerasyon (F = ma)."}, "source": "NRC PS2.A; AAAS BSL Ch.4 Motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "newton-third-law-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "Newton's third law action reaction", "grades": [8, 9, 10], "terms": ["Newton", "ikatlong batas", "third law", "aksyon", "reaksyon", "action", "reaction", "puwersa", "force", "kusog", "magkabaliktad", "pantay na puwersa", "pareho ang lakas", "magkasalungat"], "fact": {"tl": "Ayon sa ikatlong batas ni Newton, sa bawat aksyon ay may pantay at magkabaliktad na reaksyon — kapag itinulak mo ang dingding, itinutulak ka rin nito pabalik nang may kaparehong lakas.", "en": "Newton's third law says for every action there is an equal and opposite reaction — when you push a wall, it pushes back on you just as hard.", "bis": "Sumala sa ikatulong balaod ni Newton, sa matag aksyon adunay parehas ug atbang nga reaksyon — kon imong iduso ang bungbong, iduso ka usab niini balik sa samang kusog."}, "source": "NRC PS2.A; AAAS BSL Ch.4 Motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "weight-vs-mass-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "weight versus mass", "grades": [7, 8, 9], "terms": ["timbang", "weight", "masa", "mass", "gibug-aton", "gravity", "grabidad", "kilo", "newton", "dami ng materya", "kabug-aton", "buwan", "moon", "nagbabago ang timbang", "hindi nagbabago ang masa"], "fact": {"tl": "Ang masa ay ang dami ng materyang nasa isang bagay at hindi nagbabago, ngunit ang timbang ay ang hila ng grabidad dito kaya't mas magaan ang iyong timbang sa buwan kahit pareho ang masa mo.", "en": "Mass is the amount of matter in an object and never changes, but weight is the pull of gravity on it, so you would weigh less on the Moon even though your mass is the same.", "bis": "Ang masa mao ang gidaghanon sa materya sa usa ka butang ug dili mausab, apan ang gibug-aton mao ang bira sa grabidad niini, mao nga mas gaan ka sa Bulan bisan pareho ra ang imong masa."}, "source": "NRC PS2.B; AAAS BSL Ch.4 Forces of Nature", "generator": "claude-workflow", "reviewed": false},
  {"id": "gravity-attracts-all-masses-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "gravity between all masses", "grades": [7, 8, 9], "terms": ["grabidad", "gravity", "hila", "mass", "masa", "lahat ng bagay", "naghihilahan", "mas malaki mas malakas", "Earth", "Daigdig", "Yuta", "attraction", "bira", "kalibutan", "magbiniraay"], "fact": {"tl": "Lahat ng bagay na may masa ay naghihilahan dahil sa grabidad, ngunit napakahina nito sa maliliit na bagay kaya napapansin lang natin ito sa napakalaking bagay gaya ng Daigdig.", "en": "Every object with mass pulls on every other object through gravity, but the pull is so weak for small things that we only notice it with huge bodies like the Earth.", "bis": "Tanang butang nga adunay masa magbiniraay tungod sa grabidad, apan huyang kaayo kini sa gagmay nga butang mao nga mamatikdan lang nato kini sa dagkong butang sama sa Yuta."}, "source": "NRC PS2.B; AAAS BSL Ch.4 Forces of Nature", "generator": "claude-workflow", "reviewed": false},
  {"id": "free-fall-same-rate-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "objects fall at the same rate", "grades": [6, 7, 8], "terms": ["malaglag", "nahulog", "fall", "nahagba", "free fall", "grabidad", "gravity", "magkasabay bumagsak", "same speed", "bigat hindi mahalaga", "vacuum", "walang hangin", "bato", "martilyo", "patak nang sabay"], "fact": {"tl": "Kung walang hangin na humahadlang, ang isang mabigat at magaang bagay ay magkasabay na bumabagsak dahil pinapabilis sila ng grabidad sa parehong dami.", "en": "With no air to slow them, a heavy object and a light object fall and hit the ground at the same time because gravity speeds them up by the same amount.", "bis": "Kon walay hangin nga makababag, ang bug-at ug gaan nga butang dungan nga mahulog kay gipaspas sila sa grabidad sa samang gidaghanon."}, "source": "NRC PS2.B; AAAS BSL Ch.4 Motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "newton-force-unit-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "the newton unit of force", "grades": [8, 9, 10], "terms": ["newton", "yunit ng puwersa", "unit of force", "sukat", "sukod", "force", "puwersa", "kusog", "spring scale", "panimbang", "pagsukat ng puwersa", "N", "Isaac Newton"], "fact": {"tl": "Sinusukat ang puwersa sa yunit na tinatawag na newton (N), na pinangalan kay Isaac Newton; ang isang maliit na mansanas ay tumitimbang nang humigit-kumulang isang newton.", "en": "Force is measured in a unit called the newton (N), named after Isaac Newton; a small apple weighs about one newton.", "bis": "Ang kusog gisukod sa yunit nga gitawag og newton (N), nga ginganlan sunod kang Isaac Newton; ang gamay nga mansanas mga usa ka newton ang gibug-aton."}, "source": "AAAS BSL Ch.4 Motion; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "speed-distance-time-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "speed as distance over time", "grades": [6, 7, 8], "terms": ["bilis", "speed", "katulin", "layo", "distance", "gilay-on", "oras", "time", "panahon", "kilometro kada oras", "km/h", "mabilis", "paspas", "pagsukat ng bilis", "distansya"], "fact": {"tl": "Ang bilis ay kung gaano kalayo ang nilakbay ng isang bagay sa loob ng isang panahon, kaya kinakalkula ito sa pamamagitan ng paghahati ng layo sa oras (halimbawa, kilometro kada oras).", "en": "Speed is how far something travels in a given time, so you calculate it by dividing the distance by the time (for example, kilometers per hour).", "bis": "Ang katulin mao kung unsa ka layo ang gilakwan sa usa ka butang sa sulod sa usa ka panahon, busa makwenta kini pinaagi sa pagbahin sa gilay-on sa oras (pananglitan, kilometro matag oras)."}, "source": "AAAS BSL Ch.4 Motion; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "acceleration-meaning-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "acceleration change in speed", "grades": [7, 8, 9], "terms": ["aselerasyon", "acceleration", "pagbabago ng bilis", "bumibilis", "bumagal", "speeding up", "slowing down", "paghinay", "pagpaspas", "lumiliko", "puwersa", "force", "kusog", "deceleration", "pagbag-o sa katulin"], "fact": {"tl": "Ang aselerasyon ay ang pagbabago sa bilis o direksyon ng isang bagay, kaya nangyayari ito kapag bumibilis, bumabagal, o lumiliko ang isang sasakyan.", "en": "Acceleration is any change in an object's speed or direction, so it happens when a vehicle speeds up, slows down, or turns.", "bis": "Ang aselerasyon mao ang pagbag-o sa katulin o direksyon sa usa ka butang, busa mahitabo kini kon mopaspas, mohinay, o moliko ang usa ka sakyanan."}, "source": "NRC PS2.A; AAAS BSL Ch.4 Motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "wedge-simple-machine-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "the wedge simple machine", "grades": [4, 5, 6], "terms": ["wedge", "kalang", "tulis", "simpleng makina", "simple machine", "palakol", "axe", "kutsilyo", "knife", "pako", "hiwa", "naghihiwa", "naghati", "tumutulak palayo", "matalim"], "fact": {"tl": "Ang wedge ay isang simpleng makinang matulis sa isang dulo, gaya ng palakol o kutsilyo, na naghahati o naghihiwa ng bagay sa pamamagitan ng pagtulak nito sa magkabilang panig.", "en": "A wedge is a simple machine with a sharp edge, like an axe or knife, that splits or cuts things by pushing them apart on each side.", "bis": "Ang wedge usa ka simpleng makina nga hait sa usa ka tumoy, sama sa atsa o kutsilyo, nga mobahin o moputol sa mga butang pinaagi sa pagduso niini sa managlahing kilid."}, "source": "AAAS BSL Ch.8 The Designed World; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "screw-simple-machine-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "the screw simple machine", "grades": [4, 5, 6], "terms": ["screw", "turnilyo", "tornilyo", "simpleng makina", "simple machine", "inclined plane", "paikot", "umiikot", "tirintas", "kumakapit", "umaangkla", "bolt", "thread", "naglulungog", "spiral"], "fact": {"tl": "Ang turnilyo ay isang inclined plane na nakapilipit sa palibot ng isang baras, kaya't kapag iniikot mo ito, humuhukay ito at humihigpit nang mariin sa kahoy o metal.", "en": "A screw is an inclined plane wrapped around a rod, so when you turn it, it digs in and holds tightly into wood or metal.", "bis": "Ang turnilyo usa ka inclined plane nga giputos libot sa usa ka baras, busa kon imong tuyokon kini, mokalot kini ug mogunit og hugot sa kahoy o metal."}, "source": "AAAS BSL Ch.8 The Designed World; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wheel-and-axle-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "wheel and axle simple machine", "grades": [4, 5, 6], "terms": ["gulong at ehe", "wheel and axle", "ligid", "gulong", "wheel", "ehe", "axle", "simpleng makina", "simple machine", "umiikot", "kareton", "doorknob", "manibela", "pinapadali", "rolling"], "fact": {"tl": "Ang gulong at ehe ay isang simpleng makinang may malaking gulong na nakakabit sa isang mas maliit na baras (ehe), na nagpapadali sa pagbuhat tulad ng pag-ikot ng manibela o pag-andar ng kareton.", "en": "A wheel and axle is a simple machine with a large wheel attached to a smaller rod (the axle), which makes jobs easier such as turning a steering wheel or rolling a cart.", "bis": "Ang ligid ug ehe usa ka simpleng makina nga adunay dakong ligid nga nasumpay sa mas gamay nga baras (ehe), nga nagpasayon sa trabaho sama sa pagtuyok sa manibela o pagpadagan sa karetilya."}, "source": "AAAS BSL Ch.8 The Designed World; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gear-machine-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "how gears work", "grades": [5, 6, 7], "terms": ["gear", "engranahe", "ngipin", "teeth", "umiikot", "naglihok", "bisikleta", "bicycle", "orasan", "clock", "naglilipat ng galaw", "kumakapit ang ngipin", "pinapabilis", "pinapalakas", "magkadikit"], "fact": {"tl": "Ang mga gear ay mga gulong na may ngipin na nagkakapit upang ilipat ang galaw; kapag malaking gear ang umiikot ng maliit na gear, mas bumibilis ang maliit gaya ng sa bisikleta.", "en": "Gears are toothed wheels that interlock to pass along motion; when a big gear turns a small gear, the small one spins faster, like on a bicycle.", "bis": "Ang mga gear mao ang mga ligid nga adunay ngipon nga nagkagunitanay aron ibalhin ang lihok; kon dakong gear ang motuyok sa gamay nga gear, mas mopaspas ang gamay sama sa bisikleta."}, "source": "AAAS BSL Ch.8 The Designed World; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ramp-trades-force-distance-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "machines trade force for distance", "grades": [5, 6, 7], "terms": ["rampa", "ramp", "inclined plane", "mas mahabang daan", "mas konting puwersa", "less force", "mechanical advantage", "pinapadali", "pag-akyat", "pagbuhat", "trabaho", "work", "trade-off", "mas layo pero mas magaan"], "fact": {"tl": "Hindi binabawasan ng simpleng makina ang kabuuang trabaho — pinapadali lang nila ito sa pamamagitan ng pagpapalit ng mas konting puwersa sa mas mahabang distansya, gaya ng pag-akyat sa mahabang rampa kaysa diretsong pag-angat.", "en": "A simple machine does not reduce the total work — it just makes a job easier by trading less force over a longer distance, like pushing up a long ramp instead of lifting straight up.", "bis": "Ang simpleng makina dili mokunhod sa kinatibuk-ang trabaho — gipasayon lang niini ang trabaho pinaagi sa pag-ilis og gamay nga kusog sa mas taas nga gilay-on, sama sa pagtulak sa taas nga rampa imbis nga mag-alsa diretso."}, "source": "AAAS BSL Ch.8 The Designed World; NRC PS3.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "mechanical-advantage-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "mechanical advantage", "grades": [7, 8, 9], "terms": ["mechanical advantage", "bentahe ng makina", "dinadami ang puwersa", "force multiplier", "pinalalakas ang puwersa", "lever", "palanca", "pulley", "pinapadami ang lakas", "mas mabigat na bagay", "pagbuhat", "magaan lang ang hila"], "fact": {"tl": "Tinatawag na mechanical advantage ang kung gaano dinadami ng makina ang iyong puwersa; halimbawa, ang isang palanca ay maaaring mag-angat ng bagay na mas mabigat pa sa kaya mong buhatin nang mag-isa.", "en": "Mechanical advantage is how much a machine multiplies your force; for example, a lever can lift something much heavier than you could raise on your own.", "bis": "Ang mechanical advantage mao kung unsa kadaghan gipadaghan sa makina ang imong kusog; pananglitan, ang usa ka palanca makaalsa og butang nga mas bug-at pa sa imong maalsa nga mag-inusara."}, "source": "AAAS BSL Ch.8 The Designed World; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-cannot-be-created-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "conservation of energy", "grades": [7, 8, 9], "terms": ["enerhiya", "energy", "kusog", "hindi nawawala", "hindi nalilikha", "conserved", "nagbabago anyo", "transformed", "konserbasyon", "law of conservation", "dili mawala", "kabuuang enerhiya", "constant", "nananatili"], "fact": {"tl": "Ayon sa batas ng konserbasyon ng enerhiya, ang enerhiya ay hindi maaaring likhain o sirain — nagbabago lamang ito ng anyo, kaya't ang kabuuang enerhiya ay nananatiling pareho.", "en": "By the law of conservation of energy, energy cannot be created or destroyed — it only changes form, so the total amount of energy stays the same.", "bis": "Sumala sa balaod sa konserbasyon sa enerhiya, ang enerhiya dili mahimo o malaglag — mausab lamang kini og porma, busa ang kinatibuk-ang enerhiya magpabilin nga pareho."}, "source": "NRC PS3.B; AAAS BSL Ch.4 Energy Transformations", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-lost-as-heat-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "energy spreads as waste heat", "grades": [7, 8, 9], "terms": ["enerhiya", "energy", "init", "heat", "kawalan", "sayang na init", "waste heat", "friction", "alitan", "kuskos", "nawawala sa init", "hindi 100% efficient", "machine", "makina", "nag-iinit", "dili epektibo"], "fact": {"tl": "Tuwing nagbabago ang enerhiya ng anyo, may bahaging tumatakas bilang init, kaya't walang makinang gumagamit ng enerhiya nang 100 porsiyentong walang sayang.", "en": "Every time energy changes form, some of it escapes as heat, so no machine can use energy with no waste at all.", "bis": "Matag higayon nga mausab ang porma sa enerhiya, adunay bahin nga moikyas isip kainit, busa walay makina nga makagamit sa enerhiya nga walay gisayang."}, "source": "NRC PS3.B; AAAS BSL Ch.4 Energy Transformations", "generator": "claude-workflow", "reviewed": false},
  {"id": "chemical-energy-food-fuel-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "chemical energy in food and fuel", "grades": [5, 6, 7], "terms": ["chemical energy", "enerhiya kemikal", "pagkain", "food", "gasolina", "fuel", "krudo", "katawan", "lakas", "nagbibigay enerhiya", "nasusunog", "stored energy", "naimbak", "nakatago", "kalan", "sugnod"], "fact": {"tl": "Ang enerhiyang kemikal ay nakaimbak sa pagkain at sa gasolina, at lumalabas ito bilang lakas at init kapag tinunaw ito ng katawan o sinunog sa makina.", "en": "Chemical energy is stored in food and in fuel, and it is released as power and heat when the body breaks it down or an engine burns it.", "bis": "Ang enerhiyang kemikal natipig sa pagkaon ug sa gasolina, ug mogawas kini isip kusog ug kainit kon tunawon kini sa lawas o sunogon sa makina."}, "source": "NRC PS3.D; AAAS BSL Ch.4 Energy Transformations", "generator": "claude-workflow", "reviewed": false},
  {"id": "elastic-potential-energy-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "elastic potential energy in springs", "grades": [5, 6, 7], "terms": ["elastic", "spring", "muwelye", "goma", "rubber band", "lastiko", "naunat", "nakabaluktot", "stored energy", "naipon na enerhiya", "tirador", "slingshot", "bumabalik", "stretched", "compressed", "binanat"], "fact": {"tl": "Kapag inuunat o binabaluktot mo ang isang lastiko o muwelye, nag-iimbak ito ng elastic potential energy na inilalabas bilang galaw kapag binitawan mo ito.", "en": "When you stretch or bend a rubber band or spring, it stores elastic potential energy that is released as motion when you let it go.", "bis": "Kon imong unaton o balukton ang usa ka lastiko o muwelye, motipig kini og elastic potential energy nga ipagawas isip lihok kon imo kining buhian."}, "source": "NRC PS3.A; AAAS BSL Ch.4 Energy Transformations", "generator": "claude-workflow", "reviewed": false},
  {"id": "gravitational-potential-energy-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "gravitational potential energy of height", "grades": [6, 7, 8], "terms": ["potential energy", "potensyal na enerhiya", "taas", "height", "kahabog", "mataas", "nakataas", "nakaipon na enerhiya", "stored", "grabidad", "gravity", "babagsak", "mas mataas mas malakas", "bato sa bangin", "naghihintay"], "fact": {"tl": "Habang itinataas mo ang isang bagay, dumadami ang naiimbak nitong gravitational potential energy, kaya't mas malakas ang pagbagsak ng bagay na inihulog mula sa mas mataas na lugar.", "en": "The higher you raise an object, the more gravitational potential energy it stores, which is why something dropped from higher up hits harder.", "bis": "Samtang gipataas nimo ang usa ka butang, modaghan ang gitipigan niini nga gravitational potential energy, mao nga mas kusog ang pagkahulog sa butang nga gibitaw gikan sa mas taas nga lugar."}, "source": "NRC PS3.A; AAAS BSL Ch.4 Energy Transformations", "generator": "claude-workflow", "reviewed": false},
  {"id": "rolling-friction-less-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "rolling friction is less than sliding", "grades": [4, 5, 6], "terms": ["rolling friction", "friction", "alitan", "kuskosan", "gulong", "rolling", "pagulong", "sliding", "pagkaladkad", "mas madaling igulong", "wheels", "ligid", "mga gulong", "mas magaan", "kareton", "mas kaunting friction"], "fact": {"tl": "Mas kaunti ang friction kapag gumugulong ang isang bagay kaysa kapag kinakaladkad ito, kaya mas madaling itulak ang kahong may gulong kaysa ang basta hinihila sa sahig.", "en": "There is less friction when an object rolls than when it is dragged, which is why a box on wheels is much easier to push than one slid along the floor.", "bis": "Mas gamay ang friction kon moligid ang usa ka butang kaysa kon guyoron kini, mao nga mas sayon iduso ang kahon nga adunay ligid kaysa giguyod sa salog."}, "source": "AAAS BSL Ch.4 Motion; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lubricant-reduces-friction-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "lubricants reduce friction", "grades": [4, 5, 6], "terms": ["pampadulas", "lubricant", "langis", "oil", "grasa", "grease", "friction", "alitan", "kuskosan", "binabawasan ang friction", "makinis", "madulas", "mas magaan ang galaw", "kadena", "chain", "mas dali molihok"], "fact": {"tl": "Ang langis at grasa ay mga pampadulas na nagbabawas ng friction sa pagitan ng dalawang magkadikit na bahagi, kaya mas magaan at mas tahimik ang galaw ng makina.", "en": "Oil and grease are lubricants that reduce the friction between two touching parts, so a machine moves more smoothly and quietly.", "bis": "Ang lana ug grasa mao ang mga pangpadulas nga mokunhod sa friction tali sa duha ka nagkadikit nga bahin, mao nga mas hapsay ug mas hilom molihok ang makina."}, "source": "AAAS BSL Ch.4 Motion; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "contact-vs-noncontact-force-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "contact and non-contact forces", "grades": [6, 7, 8], "terms": ["contact force", "puwersang dikit", "non-contact", "puwersang malayo", "magnetismo", "magnet", "magnetic", "grabidad", "gravity", "kuryente", "static", "hindi nagdidikit", "walang hipo", "nahihila kahit walang dikit", "kusog nga layo"], "fact": {"tl": "Karamihan ng puwersa ay kailangang dumikit upang kumilos, ngunit ang grabidad, magnetismo, at static na kuryente ay maaaring humila o magtulak kahit walang pagdidikit.", "en": "Most forces need to touch an object to act on it, but gravity, magnetism, and static electricity can pull or push without touching at all.", "bis": "Kadaghanan sa mga kusog kinahanglan modikit aron molihok, apan ang grabidad, magnetismo, ug static nga kuryente makabira o makaduso bisan walay paghikap."}, "source": "NRC PS2.B; AAAS BSL Ch.4 Forces of Nature", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnetic-poles-attract-repel-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "magnetic poles attract and repel", "grades": [4, 5, 6], "terms": ["magnet", "magnetismo", "poste", "poles", "north", "south", "hilaga", "timog", "naghihila", "nagtutulakan", "attract", "repel", "magkasalungat naghihila", "magkapareho nagtutulak", "amihanan", "habagatan"], "fact": {"tl": "Ang bawat magnet ay may dalawang dulo na tinatawag na north at south pole; naghihilahan ang magkasalungat na poste samantalang nagtutulakan ang magkaparehong poste.", "en": "Every magnet has two ends called the north and south poles; opposite poles attract each other while like poles push each other away.", "bis": "Matag magnet adunay duha ka tumoy nga gitawag og north ug south pole; ang atbang nga poste magbiniraay samtang ang managsama nga poste magduslakay."}, "source": "NRC PS2.B; AAAS BSL Ch.4 Forces of Nature", "generator": "claude-workflow", "reviewed": false},
  {"id": "drag-air-water-resistance-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "drag from air and water", "grades": [5, 6, 7], "terms": ["drag", "hadlang ng hangin", "air resistance", "hangin", "water resistance", "tubig", "pumipigil", "bumabagal", "streamlined", "matuwid na hugis", "isda", "fish", "kotse", "matulis na harapan", "pinipigilan", "babag"], "fact": {"tl": "Ang hangin at tubig ay nagbibigay ng puwersang tinatawag na drag na pumipigil sa mga bagay na gumagalaw, kaya hinuhugis na makinis at matulis ang mga kotse, eroplano, at isda upang mabawasan ito.", "en": "Air and water push back on moving objects with a force called drag, which is why cars, planes, and fish are shaped smooth and streamlined to reduce it.", "bis": "Ang hangin ug tubig moduso balik sa naglihok nga mga butang pinaagi sa kusog nga gitawag og drag, mao nga ang mga awto, eroplano, ug isda gihulma nga hapsay ug tul-id aron makunhoran kini."}, "source": "AAAS BSL Ch.4 Motion; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "thermal-energy-particle-motion-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "thermal energy is particle motion", "grades": [6, 7, 8], "terms": ["thermal energy", "init", "heat", "kainit", "temperatura", "temperature", "mga maliit na butang gumagalaw", "particles", "molecules", "mabilis gumalaw", "mas mainit", "vibrating", "umaalog", "galaw ng partikulo", "lihok sa gagmay nga butang"], "fact": {"tl": "Ang init ay isang anyo ng enerhiya na nagmumula sa paggalaw ng napakaliliit na bahagi ng materya; mas mabilis silang gumagalaw, mas mainit ang bagay.", "en": "Heat is a form of energy that comes from the motion of the tiny particles in matter; the faster they move, the hotter the object is.", "bis": "Ang kainit usa ka porma sa enerhiya nga gikan sa paglihok sa gagmay kaayo nga bahin sa materya; mas paspas sila molihok, mas init ang butang."}, "source": "NRC PS3.A; AAAS BSL Ch.4 Energy Transformations", "generator": "claude-workflow", "reviewed": false},
  {"id": "speed-needs-reference-point-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "motion is relative to a reference point", "grades": [5, 6, 7], "terms": ["galaw", "motion", "lihok", "reference point", "batayang punto", "tumitigil o gumagalaw", "relative", "sasakyan", "bus", "nakaupo", "tila hindi gumagalaw", "kapwa pasahero", "puno", "kumikilos kumpara sa", "depende sa pananaw"], "fact": {"tl": "Kung gumagalaw ba ang isang bagay ay nakadepende sa kung ano ang ginagamit nating batayan; halimbawa, ang kapwa mong pasahero sa bus ay tila hindi gumagalaw sa iyo ngunit mabilis na gumagalaw kumpara sa mga puno sa labas.", "en": "Whether something is moving depends on the reference point you compare it to; for example, a fellow bus passenger seems still to you but is moving fast compared with the trees outside.", "bis": "Kung naglihok ba ang usa ka butang nagdepende sa unsa ang gigamit natong sukaranan; pananglitan, ang imong kauban nga pasahero sa bus daw walay lihok kanimo apan paspas nga naglihok kumpara sa mga kahoy sa gawas."}, "source": "AAAS BSL Ch.4 Motion; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tension-pulling-force-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "tension force in ropes", "grades": [5, 6, 7], "terms": ["tension", "tirintas", "hila", "pulling", "lubid", "rope", "pisi", "kable", "cable", "nakabitin", "nakahatak", "hinihila", "nakaunat", "tug of war", "buno-bunohan", "binira", "hugot"], "fact": {"tl": "Ang tension ay ang humihilang puwersang dumadaloy sa isang lubid o kable kapag ito ay binabanat sa magkabilang dulo, gaya sa laro ng tug-of-war.", "en": "Tension is the pulling force carried along a rope or cable when it is stretched tight at both ends, like in a game of tug-of-war.", "bis": "Ang tension mao ang nagbira nga kusog nga moagi sa usa ka pisi o kable kon kini hugton sa duha ka tumoy, sama sa dula nga tug-of-war."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "balance-center-of-gravity-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "center of gravity and balance", "grades": [6, 7, 8], "terms": ["balanse", "balance", "center of gravity", "sentro ng bigat", "tunga sa gibug-aton", "natutumba", "babagsak", "matatag", "stable", "mababa ang sentro", "tore", "tumba", "hindi natutumbahan", "patag ang base", "pagbalanse"], "fact": {"tl": "Ang isang bagay ay nananatiling balanse kapag ang sentro ng bigat nito ay nasa ibabaw ng base nito; mas mababa at mas malapad ang base, mas mahirap itong matumba.", "en": "An object stays balanced when its center of gravity is over its base; the lower and wider the base, the harder it is to tip over.", "bis": "Ang usa ka butang magpabilin nga balanse kon ang sentro sa gibug-aton niini anaa sa ibabaw sa base niini; mas ubos ug mas lapad ang base, mas lisod kining matumba."}, "source": "AAAS BSL Ch.4 Forces of Nature; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "perpetual-motion-impossible-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "perpetual motion is impossible", "grades": [8, 9, 10], "terms": ["perpetual motion", "walang hanggang galaw", "imposible", "impossible", "libre na enerhiya", "free energy", "friction", "alitan", "energy loss", "nauubos ang enerhiya", "hindi tumitigil", "tumitigil din", "makina nga dili mohunong", "dili mahimo"], "fact": {"tl": "Imposible ang isang makinang gumagalaw nang walang hanggan nang walang dagdag na enerhiya, dahil laging may enerhiyang nawawala bilang init dahil sa friction.", "en": "A machine that runs forever with no added energy is impossible, because some energy is always lost as heat through friction.", "bis": "Imposible ang usa ka makina nga molihok hangtod sa kahangtoran nga walay dugang nga enerhiya, kay kanunay adunay enerhiya nga mawala isip kainit tungod sa friction."}, "source": "NRC PS3.B; AAAS BSL Ch.4 Energy Transformations", "generator": "claude-workflow", "reviewed": false},
  {"id": "power-rate-of-energy-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "power as rate of doing work", "grades": [8, 9, 10], "terms": ["power", "lakas", "kapangyarihan", "watt", "bilis ng paggawa", "rate of work", "energy per second", "mas mabilis na trabaho", "gaano kabilis", "enerhiya kada segundo", "kusog kada segundo", "bombilya"], "fact": {"tl": "Ang power ay kung gaano kabilis ginagamit o nililikha ang enerhiya, at sinusukat ito sa watt; mas mataas ang watt, mas mabilis ang paggawa ng trabaho.", "en": "Power is how fast energy is used or produced, measured in watts; the higher the wattage, the faster the work gets done.", "bis": "Ang power mao kung unsa ka paspas gigamit o gimugna ang enerhiya, ug gisukod kini sa watt; mas taas ang watt, mas paspas mahuman ang trabaho."}, "source": "AAAS BSL Ch.4 Energy Transformations; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-cycle-sun-engine-g5", "domain": "EARTH_SPACE", "topic": "the sun powers the water cycle", "grades": [5, 6], "terms": ["araw", "init ng araw", "water cycle", "siklo ng tubig", "nagpapagana", "enerhiya", "sun", "powers", "energy", "adlaw", "kainit", "siklo sa tubig", "kusog", "bakit umuulan", "ngano nga magbalik-balik ang tubig"], "fact": {"tl": "Ang init ng araw ang nagpapagana sa buong siklo ng tubig — ito ang enerhiyang nagpapasingaw ng tubig pataas, at kung walang araw ay hindi magkakaroon ng ulap o ulan.", "en": "The sun's heat is the engine that drives the whole water cycle — its energy lifts water up as vapor, and without the sun there would be no clouds or rain.", "bis": "Ang kainit sa adlaw mao ang nagpadagan sa tibuok siklo sa tubig — kini ang kusog nga nagpaalisngaw sa tubig pataas, ug kung walay adlaw walay panganod o ulan."}, "source": "AAAS Benchmarks 4B/M7; NRC ESS2.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-cycle-infiltration-runoff-g6", "domain": "EARTH_SPACE", "topic": "infiltration and runoff", "grades": [6, 7], "terms": ["tubig-ulan", "sumisipsip", "lupa", "infiltration", "runoff", "umaagos", "ibabaw", "patubo", "soaks", "ground", "surface", "misuyop", "yuta", "midagayday", "saan napupunta ang ulan", "asa moadto ang ulan"], "fact": {"tl": "Kapag umulan, ang ilang tubig ay sumisipsip sa lupa (infiltration) at ang iba ay umaagos sa ibabaw papunta sa mga sapa at ilog (runoff).", "en": "When it rains, some water soaks down into the soil (infiltration) while the rest flows across the surface into streams and rivers (runoff).", "bis": "Kung mo-ulan, ang ubang tubig mosuyop sa yuta (infiltration) ug ang uban modagayday sa ibabaw paingon sa mga sapa ug suba (runoff)."}, "source": "NRC ESS2.C; AAAS Benchmarks 4B/M7", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-cycle-transpiration-role-g6", "domain": "EARTH_SPACE", "topic": "plants add water to the cycle", "grades": [6, 7], "terms": ["halaman", "dahon", "transpiration", "singaw ng dahon", "siklo ng tubig", "puno", "plants", "leaves", "water cycle", "tanom", "dahon mopagawas", "alisngaw sa dahon", "kahoy", "ngano basa ang hangin sa lasang"], "fact": {"tl": "Ang mga halaman at puno ay nagdaragdag din ng tubig sa siklo — naglalabas sila ng singaw mula sa kanilang mga dahon (transpiration), kaya't basa ang hangin sa paligid ng kagubatan.", "en": "Plants and trees also add water to the cycle — they release vapor from their leaves (transpiration), which is why the air around a forest is moist.", "bis": "Ang mga tanom ug kahoy nagdugang usab og tubig sa siklo — mopagawas sila og alisngaw gikan sa ilang mga dahon (transpiration), maong basa ang hangin palibot sa lasang."}, "source": "NRC LS1.C; AAAS Benchmarks 4B/M7", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-cycle-fresh-from-salty-g5", "domain": "EARTH_SPACE", "topic": "evaporation leaves salt behind", "grades": [5, 6], "terms": ["alat", "asin", "naiiwan", "sumisingaw", "tabang", "ulan", "fresh water", "salt", "evaporation", "dagat", "asgad", "asin nahibilin", "nag-alisngaw", "tab-ang", "ngano tab-ang ang ulan", "bakit hindi maalat ang ulan"], "fact": {"tl": "Kapag sumisingaw ang tubig-dagat, ang asin ay naiiwan at ang singaw lamang ang umaakyat — kaya ang ulan ay tabang (fresh) at hindi maalat.", "en": "When seawater evaporates, the salt is left behind and only pure vapor rises — that is why rain is fresh water and not salty.", "bis": "Kung mo-alisngaw ang tubig-dagat, ang asin mahibilin ug ang alisngaw ra ang mosaka — mao nga ang ulan tab-ang (fresh) ug dili asgad."}, "source": "AAAS Benchmarks 4B/M7; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "river-source-to-mouth-g5", "domain": "EARTH_SPACE", "topic": "rivers flow from source to mouth", "grades": [5, 6], "terms": ["ilog", "pinagmulan", "bukal", "bundok", "wawa", "bunganga", "dagat", "umaagos", "river", "source", "mouth", "downhill", "suba", "tinubdan", "bukana", "mibu-bu", "asa magsugod ang suba", "saan nagsisimula ang ilog"], "fact": {"tl": "Ang ilog ay nagsisimula sa isang pinagmulan (source) sa mataas na lugar gaya ng bundok, at umaagos pababa hanggang sa bunganga (mouth) kung saan ito sumasanib sa lawa o dagat.", "en": "A river begins at a source in high ground such as a mountain, and flows downhill to its mouth, where it empties into a lake or the sea.", "bis": "Ang suba magsugod sa usa ka tinubdan (source) sa habog nga dapit sama sa bukid, ug modagayday paubos hangtod sa bukana (mouth) diin kini mosulod sa lanaw o dagat."}, "source": "encyclopedia-stable consensus; NRC ESS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "river-tributaries-g5", "domain": "EARTH_SPACE", "topic": "tributaries join a river", "grades": [5, 6], "terms": ["sanga", "sapa", "tributary", "sumasanib", "ilog", "maliit", "stream", "joins", "river", "sangang sapa", "suba", "sapa nga mosulod", "nagbu-bu", "saan galing ang tubig sa ilog", "asa gikan ang tubig sa suba"], "fact": {"tl": "Ang malalaking ilog ay kinukuha ang tubig mula sa maraming maliliit na sapa na sumasanib dito — ang mga ito ay tinatawag na tributaries o sangang-sapa.", "en": "Big rivers gather their water from many smaller streams that flow into them — these are called tributaries.", "bis": "Ang dagkong suba magtigom sa ilang tubig gikan sa daghang gagmay nga sapa nga mosulod kanila — kini gitawag og tributaries o sangang-sapa."}, "source": "encyclopedia-stable consensus; NRC ESS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "river-erosion-shapes-land-g6", "domain": "EARTH_SPACE", "topic": "rivers carve the land", "grades": [6, 7], "terms": ["ilog", "umuukit", "erosion", "lambak", "kanyon", "lupa", "bato", "river", "carve", "valley", "canyon", "suba", "nagkutkot", "walog", "lumalalim", "ngano lawom ang suba", "bakit may lambak"], "fact": {"tl": "Sa loob ng libu-libong taon, ang umaagos na tubig ng ilog ay unti-unting umuukit ng lupa at bato, gumagawa ng malalalim na lambak at kanyon.", "en": "Over thousands of years, a river's flowing water slowly carves through soil and rock, creating deep valleys and canyons.", "bis": "Sulod sa liboan ka tuig, ang nagdagayday nga tubig sa suba hinay-hinay nga nagkutkot sa yuta ug bato, naghimo og lawom nga walog ug kanyon."}, "source": "NRC ESS2.A; AAAS Benchmarks 4C/M", "generator": "claude-workflow", "reviewed": false},
  {"id": "river-delta-deposits-g6", "domain": "EARTH_SPACE", "topic": "deltas form where rivers meet the sea", "grades": [6, 7], "terms": ["delta", "putik", "buhangin", "naiipon", "wawa", "ilog", "dagat", "lupa", "sediment", "deposit", "delta", "lapok", "balas", "natipon", "bukana", "suba", "ngano nagmugna og yuta ang suba", "bakit may bagong lupa sa wawa"], "fact": {"tl": "Sa bunganga ng ilog, bumabagal ang agos at ang dala nitong putik at buhangin ay naiipon, kaya nabubuo ang bagong lupa na tinatawag na delta.", "en": "At a river's mouth the flow slows down and the mud and sand it carries settle out, building up new land called a delta.", "bis": "Sa bukana sa suba mohinay ang agos ug ang lapok ug balas nga gidala niini matipon, busa naporma ang bag-ong yuta nga gitawag og delta."}, "source": "NRC ESS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "river-cagayan-longest-ph-g6", "domain": "EARTH_SPACE", "topic": "Cagayan River is the longest in the Philippines", "grades": [6, 7], "terms": ["Cagayan", "ilog", "pinakamahabang", "Pilipinas", "Luzon", "river", "longest", "Philippines", "suba", "pinakatas-an", "kinatas-ang suba", "pinakamahaba", "anong pinakamahabang ilog", "unsa ang pinakataas nga suba"], "fact": {"tl": "Ang Cagayan River sa hilagang Luzon ang pinakamahabang ilog sa Pilipinas, na may humigit-kumulang 505 kilometro ang haba.", "en": "The Cagayan River in northern Luzon is the longest river in the Philippines, stretching about 505 kilometers.", "bis": "Ang Cagayan River sa amihanang Luzon mao ang pinakataas nga suba sa Pilipinas, mga 505 ka kilometro ang gitas-on."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "river-pasig-connects-g6", "domain": "EARTH_SPACE", "topic": "Pasig River links Laguna de Bay and Manila Bay", "grades": [6, 7], "terms": ["Pasig", "ilog", "Laguna de Bay", "Manila Bay", "Maynila", "umaagos", "lawa", "river", "Pasig", "suba", "lanaw", "nagkonekta", "anong ilog sa Maynila", "unsa nga suba sa Manila"], "fact": {"tl": "Ang Pasig River ay umaagos mula sa Laguna de Bay, ang pinakamalaking lawa sa Pilipinas, patungo sa Manila Bay, dumadaan sa gitna ng Kalakhang Maynila.", "en": "The Pasig River flows from Laguna de Bay, the largest lake in the Philippines, to Manila Bay, passing through the heart of Metro Manila.", "bis": "Ang Pasig River modagayday gikan sa Laguna de Bay, ang pinakadakong lanaw sa Pilipinas, paingon sa Manila Bay, nga moagi sa tunga sa Metro Manila."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lake-what-is-g4", "domain": "EARTH_SPACE", "topic": "what a lake is", "grades": [4, 5], "terms": ["lawa", "tubig", "napaliligiran", "lupa", "nakapaloob", "lake", "still water", "surrounded", "land", "lanaw", "natipon nga tubig", "gilibutan", "yuta", "ano ang lawa", "unsa ang lanaw"], "fact": {"tl": "Ang lawa ay isang malaking tubig na nakapaloob at napaliligiran ng lupa, at karaniwang tabang (fresh) ang tubig nito kumpara sa dagat.", "en": "A lake is a large body of still water surrounded by land, and its water is usually fresh rather than salty like the sea.", "bis": "Ang lanaw usa ka dakong tubig nga gilibutan sa yuta, ug kasagaran tab-ang (fresh) ang tubig niini dili sama sa parat nga dagat."}, "source": "encyclopedia-stable consensus; NRC ESS2.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "lake-taal-volcano-g6", "domain": "EARTH_SPACE", "topic": "Taal Lake holds a volcano", "grades": [6, 7], "terms": ["Taal", "lawa", "bulkan", "isla", "Batangas", "loob", "lake", "volcano", "island", "Taal", "lanaw", "bulkang Taal", "pulo sa sulod", "ano ang Taal", "unsa ang Taal"], "fact": {"tl": "Ang Taal Lake sa Batangas ay nabuo sa loob ng isang malaking lumang bulkan, at may isla pa nga sa loob nito kung saan naroon ang aktibong Taal Volcano.", "en": "Taal Lake in Batangas formed inside a huge old volcanic crater, and it even has an island within it holding the active Taal Volcano.", "bis": "Ang Taal Lake sa Batangas naporma sulod sa usa ka dako ug daan nga bulkan, ug aduna pa kini'y pulo sa sulod diin nahimutang ang aktibo nga Taal Volcano."}, "source": "encyclopedia-stable consensus; PHIVOLCS", "generator": "claude-workflow", "reviewed": false},
  {"id": "lake-formation-ways-g6", "domain": "EARTH_SPACE", "topic": "how lakes form", "grades": [6, 7], "terms": ["lawa", "nabubuo", "lubak", "yelo", "bulkan", "natipon", "tubig-ulan", "lake", "form", "hollow", "basin", "lanaw", "naporma", "lungag", "natipon nga tubig", "paano nabuo ang lawa", "unsaon pagkaporma sa lanaw"], "fact": {"tl": "Nabubuo ang lawa kapag napupuno ng tubig-ulan, sapa, o groundwater ang isang lubak sa lupa na maaaring iniwan ng yelo, bulkan, o paggalaw ng lupa.", "en": "A lake forms when a hollow in the ground — left by ice, a volcano, or shifting land — fills up with rain, streams, or groundwater.", "bis": "Maporma ang lanaw kung mapuno og tubig-ulan, sapa, o groundwater ang usa ka lungag sa yuta nga gibilin sa yelo, bulkan, o paglihok sa yuta."}, "source": "NRC ESS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "groundwater-aquifer-g7", "domain": "EARTH_SPACE", "topic": "aquifers store water underground", "grades": [7, 8], "terms": ["aquifer", "tubig", "ilalim", "bato", "buhangin", "imbak", "groundwater", "layer", "underground", "store", "lapok", "ilalom", "tinipigan", "bato ug balas", "saan nakaimbak ang tubig sa lupa", "asa gitipigan ang tubig sa ilalom"], "fact": {"tl": "Ang aquifer ay isang layer ng bato o buhangin sa ilalim ng lupa na puno ng tubig sa mga butas nito, at dito nakaimbak ang karamihan ng tubig na ininom natin mula sa balon.", "en": "An aquifer is a layer of rock or sand underground whose tiny spaces are filled with water, and it stores most of the water we draw from wells.", "bis": "Ang aquifer usa ka layer sa bato o balas sa ilalom sa yuta nga ang gagmayng lungag niini puno og tubig, ug dinhi gitipigan ang kadaghanan sa tubig nga atong gikuha sa atabay."}, "source": "NRC ESS2.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "groundwater-spring-g6", "domain": "EARTH_SPACE", "topic": "springs are where groundwater surfaces", "grades": [6, 7], "terms": ["bukal", "tubig", "lumalabas", "lupa", "groundwater", "natural", "spring", "surface", "underground", "tuboran", "tubod", "migawas", "yuta", "saan nanggagaling ang bukal", "asa gikan ang tuboran"], "fact": {"tl": "Ang bukal (spring) ay nabubuo kapag ang groundwater ay natural na lumalabas sa ibabaw ng lupa, kaya may malinis na tubig na umaagos kahit walang ulan.", "en": "A spring forms where groundwater naturally flows out at the surface, giving clean flowing water even when it has not rained.", "bis": "Ang tuboran (spring) maporma kung ang groundwater natural nga mogawas sa ibabaw sa yuta, busa adunay limpyo nga tubig nga modagayday bisan walay ulan."}, "source": "NRC ESS2.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "groundwater-recharge-g7", "domain": "EARTH_SPACE", "topic": "groundwater is recharged by rain", "grades": [7, 8], "terms": ["groundwater", "napupunan", "tubig-ulan", "sumisipsip", "recharge", "ubos", "refill", "rain", "tubig sa ilalim", "napuno balik", "misuyop", "nahurot", "bakit nauubos ang tubig sa balon", "ngano mahurot ang tubig sa atabay"], "fact": {"tl": "Ang groundwater ay napupunan muli (recharge) kapag ang tubig-ulan ay sumisipsip pababa sa lupa, ngunit kung mas mabilis tayong kumuha kaysa sa pagpuno, nauubos ito.", "en": "Groundwater is recharged when rainwater soaks back down into the ground, but if we pump it out faster than it refills, it runs low.", "bis": "Ang groundwater mapuno balik (recharge) kung ang tubig-ulan mosuyop balik paubos sa yuta, apan kung mas paspas ta mokuha kaysa sa pagpuno, mahurot kini."}, "source": "AAAS Benchmarks 4B/M8; NRC ESS2.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "watershed-what-is-g6", "domain": "EARTH_SPACE", "topic": "what a watershed is", "grades": [6, 7], "terms": ["watershed", "lupa", "tubig-ulan", "umaagos", "iisang ilog", "kalupaan", "drainage", "basin", "collects", "saluran ng tubig", "yuta", "modagayday", "usa ka suba", "ano ang watershed", "unsa ang watershed"], "fact": {"tl": "Ang watershed ay ang buong kalupaan kung saan ang lahat ng tubig-ulan ay umaagos pababa patungo sa iisang ilog, lawa, o dagat.", "en": "A watershed is the whole area of land where all the rainwater drains down into the same river, lake, or sea.", "bis": "Ang watershed mao ang tibuok yuta diin ang tanang tubig-ulan modagayday paubos paingon sa usa ra ka suba, lanaw, o dagat."}, "source": "NRC ESS2.A; AAAS Benchmarks 4B/M7", "generator": "claude-workflow", "reviewed": false},
  {"id": "watershed-forests-protect-g7", "domain": "EARTH_SPACE", "topic": "forests protect watersheds", "grades": [7, 8], "terms": ["gubat", "puno", "ugat", "hawak", "lupa", "tubig", "watershed", "forest", "roots", "soak", "kalasangan", "lasang", "gamot", "nagpugong", "nagtipig", "bakit kailangan ng gubat sa watershed", "ngano importante ang lasang sa watershed"], "fact": {"tl": "Ang mga puno sa watershed ay tumutulong na mahawakan ang lupa at masipsip ang tubig-ulan nang dahan-dahan, kaya kapag kinakalbo ang gubat, mas madaling magkabaha at magkaroon ng erosion.", "en": "Trees in a watershed help hold the soil and let rainwater soak in slowly, so when forests are cleared, floods and erosion happen more easily.", "bis": "Ang mga kahoy sa watershed motabang sa pagkupot sa yuta ug pagpasuyop sa tubig-ulan og hinay-hinay, busa kung mawala ang lasang, mas sayon ang baha ug erosion."}, "source": "AAAS Benchmarks 4B/M8, 4B/M11; NRC ESS3.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "freshwater-tiny-fraction-g6", "domain": "EARTH_SPACE", "topic": "fresh water is a tiny fraction of Earth's water", "grades": [6, 7], "terms": ["tabang na tubig", "fresh water", "kaunti", "porsyento", "dagat", "alat", "Earth", "tiny", "percent", "tab-ang nga tubig", "gamay", "porsyento", "parat", "ilan porsyento ang tabang na tubig", "pila ka porsyento ang tab-ang nga tubig"], "fact": {"tl": "Halos lahat ng tubig sa Mundo ay maalat na tubig-dagat — wala pang 3 porsyento ang tabang (fresh) na tubig, at karamihan pa nito ay nakatago sa yelo at glacier.", "en": "Almost all of Earth's water is salty seawater — less than 3 percent is fresh water, and most of that is locked away in ice and glaciers.", "bis": "Halos tanang tubig sa Kalibutan parat nga tubig-dagat — ubos sa 3 porsyento ang tab-ang (fresh) nga tubig, ug kadaghanan niini natago sa yelo ug glacier."}, "source": "AAAS Benchmarks 4B/M8; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "freshwater-precious-limited-g5", "domain": "EARTH_SPACE", "topic": "fresh water is limited and precious", "grades": [5, 6], "terms": ["tubig", "mahalaga", "kakaunti", "buhay", "inom", "fresh water", "limited", "precious", "life", "tabang", "tab-ang nga tubig", "bililhon", "gamay ra", "kinabuhi", "bakit mahalaga ang tubig", "ngano bililhon ang tubig"], "fact": {"tl": "Ang tabang na tubig ay napakahalaga dahil kakaunti lamang nito ang available, at kailangan ito ng tao, hayop, at halaman para mabuhay.", "en": "Fresh water is precious because only a small amount is available, and people, animals, and plants all need it to live.", "bis": "Ang tab-ang nga tubig bililhon kaayo kay gamay ra ang anaa, ug gikinahanglan kini sa tawo, hayop, ug tanom aron mabuhi."}, "source": "AAAS Benchmarks 4B/M8", "generator": "claude-workflow", "reviewed": false},
  {"id": "freshwater-pollution-g6", "domain": "EARTH_SPACE", "topic": "polluted water becomes unusable", "grades": [6, 7], "terms": ["polusyon", "marumi", "tubig", "ilog", "basura", "hindi mainom", "pollution", "polluted", "unusable", "hugaw", "nahugawan", "dili mainom", "basura", "bakit di pwede inumin ang maruming tubig", "ngano dili mainom ang hugaw nga tubig"], "fact": {"tl": "Kapag ang ilog o groundwater ay dinumihan ng basura at kemikal, nagiging hindi na ito ligtas inumin, at napakahirap at magastos linisin muli.", "en": "When a river or groundwater is polluted with trash and chemicals, it becomes unsafe to drink, and it is very hard and costly to clean it again.", "bis": "Kung ang suba o groundwater mahugawan og basura ug kemikal, dili na kini luwas imnon, ug lisod kaayo ug mahal limpyohan pag-usab."}, "source": "AAAS Benchmarks 4B/M8, 4B/M11", "generator": "claude-workflow", "reviewed": false},
  {"id": "freshwater-conserve-g4", "domain": "EARTH_SPACE", "topic": "saving water at home", "grades": [4, 5], "terms": ["tubig", "tipid", "sarado", "gripo", "conserve", "save", "water", "faucet", "tipid sa tubig", "pagtipig", "tubig", "sirado", "gripo", "paano makakatipid ng tubig", "unsaon pagtipig sa tubig"], "fact": {"tl": "Makakatulong tayong makatipid ng tubig sa pamamagitan ng pagsasara ng gripo habang nagsisipilyo at pag-aayos ng tumutulong gripo, dahil kakaunti lamang ang tabang na tubig sa mundo.", "en": "We can help save water by turning off the tap while brushing our teeth and fixing dripping faucets, because the world has only a little fresh water.", "bis": "Makatabang ta sa pagtipig og tubig pinaagi sa pagsira sa gripo samtang nagsipilyo ug pag-ayo sa nagtulo nga gripo, kay gamay ra ang tab-ang nga tubig sa kalibutan."}, "source": "AAAS Benchmarks 4B/M8 (conservation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "drought-what-is-g5", "domain": "EARTH_SPACE", "topic": "what a drought is", "grades": [5, 6], "terms": ["tagtuyot", "tagsalat", "kakulangan", "tubig", "ulan", "matagal", "drought", "dry", "no rain", "huwaw", "hulaw", "kanihit", "walay ulan", "dugay nga walay ulan", "ano ang tagtuyot", "unsa ang hulaw"], "fact": {"tl": "Ang tagtuyot (drought) ay matagal na panahon na halos walang ulan, kaya natutuyo ang mga ilog at lupa at nagkukulang ang tubig para sa pananim at tao.", "en": "A drought is a long period with little or no rain, so rivers and soil dry up and there is not enough water for crops and people.", "bis": "Ang hulaw (drought) usa ka dugay nga panahon nga halos walay ulan, busa momala ang mga suba ug yuta ug makulang ang tubig para sa pananom ug tawo."}, "source": "AAAS Benchmarks 4B/M8; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "drought-el-nino-ph-g6", "domain": "EARTH_SPACE", "topic": "El Niño can bring drought to the Philippines", "grades": [6, 7], "terms": ["El Niño", "tagtuyot", "init", "kakaunti", "ulan", "Pilipinas", "PAGASA", "drought", "dry", "hot", "hulaw", "kanihit nga ulan", "init nga panahon", "ano ang El Niño", "unsa ang El Niño"], "fact": {"tl": "Tuwing may El Niño, ang panahon sa Pilipinas ay nagiging mas mainit at mas tuyo dahil bumababa ang ulan, kaya nagbabantay ang PAGASA para sa tagtuyot.", "en": "During an El Niño, the Philippines becomes hotter and drier because there is less rain, so PAGASA watches closely for drought.", "bis": "Panahon sa El Niño, ang panahon sa Pilipinas mas mo-init ug mo-uga kay mokunhod ang ulan, busa nagbantay ang PAGASA para sa hulaw."}, "source": "PAGASA; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "flash-flood-g6", "domain": "EARTH_SPACE", "topic": "flash floods rise very fast", "grades": [6, 7], "terms": ["flash flood", "biglaang baha", "mabilis", "tumataas", "ulan", "bundok", "rapid", "sudden", "fast", "kalit nga baha", "kalit", "tumaas", "kusog nga ulan", "ano ang flash flood", "unsa ang flash flood"], "fact": {"tl": "Ang flash flood o biglaang baha ay tumataas nang napakabilis sa loob lamang ng ilang minuto matapos ang napakalakas na ulan, kaya mas mapanganib dahil walang masyadong oras para makatakas.", "en": "A flash flood rises very fast, within just minutes after very heavy rain, making it especially dangerous because there is little time to escape.", "bis": "Ang flash flood o kalit nga baha motaas dayon sulod ra sa pipila ka minuto human sa kusog kaayo nga ulan, busa mas peligroso kay gamay ra ang panahon aron makaikyas."}, "source": "encyclopedia-stable consensus (disaster preparedness); PAGASA", "generator": "claude-workflow", "reviewed": false},
  {"id": "wetlands-soak-floods-g7", "domain": "EARTH_SPACE", "topic": "wetlands soak up floodwater", "grades": [7, 8], "terms": ["latian", "wetland", "sumisipsip", "baha", "tubig", "natural", "sponge", "absorb", "flood", "lamakan", "kalapukan", "nagsuyop", "baha", "ano ang silbi ng latian", "unsa ang pulos sa lamakan"], "fact": {"tl": "Ang mga latian (wetland) ay parang natural na espongha na sumisipsip at humahawak ng sobrang tubig kapag umuulan nang malakas, kaya nababawasan nila ang baha sa kalapit na lugar.", "en": "Wetlands act like natural sponges that soak up and hold extra water during heavy rain, so they reduce flooding in nearby areas.", "bis": "Ang mga lamakan (wetland) sama sa natural nga espongha nga mosuyop ug mokupot sa sobra nga tubig kung kusog ang ulan, busa makapakunhod sila sa baha sa duol nga lugar."}, "source": "NRC ESS3.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "river-mouth-estuary-g7", "domain": "EARTH_SPACE", "topic": "fresh and salt water mix in an estuary", "grades": [7, 8], "terms": ["estuary", "ilog", "dagat", "naghahalo", "tabang", "alat", "wawa", "brackish", "mix", "fresh", "salt", "estuary", "suba", "dagat", "nagsagol", "tab-ang", "asgad", "saan naghahalo ang tubig tabang at alat", "asa magsagol ang tab-ang ug parat nga tubig"], "fact": {"tl": "Sa estuary, kung saan ang ilog ay sumasanib sa dagat, naghahalo ang tabang at maalat na tubig, kaya espesyal na tirahan ito para sa mga isda at bakawan.", "en": "In an estuary, where a river meets the sea, fresh and salty water mix together, making it a special home for fish and mangroves.", "bis": "Sa estuary, diin ang suba mosulod sa dagat, magsagol ang tab-ang ug parat nga tubig, busa espesyal kini nga puy-anan sa mga isda ug bakhaw."}, "source": "encyclopedia-stable consensus; NRC ESS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-cycle-no-new-water-g6", "domain": "EARTH_SPACE", "topic": "Earth keeps recycling the same water", "grades": [6, 7], "terms": ["tubig", "umiikot", "luma", "dinosaur", "parehong tubig", "recycle", "water cycle", "same water", "dinosaurs", "tubig", "naglibot", "karaan", "dinosauro", "pareho ra nga tubig", "bagong tubig ba ang ulan", "bag-o ba nga tubig ang ulan"], "fact": {"tl": "Walang bagong tubig na nililikha — ang siklo ng tubig ay paulit-ulit na ginagamit ang parehong tubig, kaya ang tubig na iniinom mo ngayon ay maaaring nainom na ng isang dinosaur noon.", "en": "No new water is ever made — the water cycle keeps reusing the same water, so the water you drink today may once have been drunk by a dinosaur.", "bis": "Walay bag-ong tubig nga mahimo — ang siklo sa tubig balik-balik nga mogamit sa pareho ra nga tubig, busa ang tubig nga imong giinom karon basin nainom na sa usa ka dinosauro kaniadto."}, "source": "AAAS Benchmarks 4B/M7 (conservation of matter); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lake-laguna-largest-g6", "domain": "EARTH_SPACE", "topic": "Laguna de Bay is the largest lake in the Philippines", "grades": [6, 7], "terms": ["Laguna de Bay", "lawa", "pinakamalaking", "Pilipinas", "Luzon", "isda", "lake", "largest", "Philippines", "lanaw", "pinakadako", "kinadak-ang lanaw", "anong pinakamalaking lawa", "unsa ang pinakadakong lanaw"], "fact": {"tl": "Ang Laguna de Bay ang pinakamalaking lawa sa Pilipinas, at mahalaga itong pinagkukunan ng isda at tubig para sa mga komunidad sa paligid nito.", "en": "Laguna de Bay is the largest lake in the Philippines, and it is an important source of fish and water for the communities around it.", "bis": "Ang Laguna de Bay mao ang pinakadakong lanaw sa Pilipinas, ug importante kini nga tinubdan sa isda ug tubig para sa mga komunidad palibot niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "greenhouse-effect-basic-g6", "domain": "EARTH_SPACE", "topic": "greenhouse effect", "grades": [5, 6, 7], "terms": ["greenhouse effect", "epekto ng greenhouse", "init", "epekto sa greenhouse", "greenhouse", "hangin", "atmospera", "atmospero", "init sa kalibutan", "kainit", "pagpainit", "trapping heat", "naiipon na init", "carbon dioxide"], "fact": {"tl": "Ang ilang mga gas sa hangin, gaya ng carbon dioxide, ay humuhuli ng init mula sa araw at pinapanatiling mainit-init ang Earth—tinatawag itong greenhouse effect.", "en": "Some gases in the air, like carbon dioxide, trap heat from the Sun and keep Earth warm—this is called the greenhouse effect.", "bis": "Ang pipila ka mga gas sa hangin, sama sa carbon dioxide, mosakmit sa init gikan sa adlaw ug magpabilin nga mainit-init ang Yuta—gitawag kini nga greenhouse effect."}, "source": "NRC ESS3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "greenhouse-keeps-earth-livable-g6", "domain": "EARTH_SPACE", "topic": "greenhouse effect importance", "grades": [6, 7, 8], "terms": ["greenhouse effect", "epekto ng greenhouse", "natural", "kinaiyanhon", "buhi", "livable", "mabuhay", "lamig", "bugnaw", "kung wala", "kon walay", "natural greenhouse", "tama lang na init"], "fact": {"tl": "Ang natural na greenhouse effect ay mahalaga—kung wala ito, magiging napakalamig ng Earth at mahihirapang mabuhay ang mga nilalang.", "en": "The natural greenhouse effect is important—without it, Earth would be far too cold for life to survive easily.", "bis": "Ang kinaiyanhon nga greenhouse effect importante—kon walay kini, mahimong sobra ka bugnaw ang Yuta ug lisod mabuhi ang mga buhing butang."}, "source": "NRC ESS3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "carbon-dioxide-warming-g7", "domain": "EARTH_SPACE", "topic": "carbon dioxide and temperature", "grades": [6, 7, 8], "terms": ["carbon dioxide", "CO2", "temperatura", "temperatura sa kalibutan", "init", "average temperature", "atmospheric carbon dioxide", "carbon dioxide sa hangin", "pag-init", "pagtaas ng init", "average na temperatura"], "fact": {"tl": "Habang dumarami ang carbon dioxide sa hangin, tumataas din ang average na temperatura ng Earth.", "en": "As the amount of carbon dioxide in the air rises, Earth's average temperature rises too.", "bis": "Samtang modaghan ang carbon dioxide sa hangin, motaas usab ang average nga temperatura sa Yuta."}, "source": "NRC Chapter 8 (atmospheric CO2 / Earth's average temperature)", "generator": "claude-workflow", "reviewed": false},
  {"id": "climate-change-definition-g7", "domain": "EARTH_SPACE", "topic": "climate change", "grades": [6, 7, 8], "terms": ["climate change", "pagbabago ng klima", "pagbag-o sa klima", "klima", "global warming", "pag-init ng mundo", "pag-init sa kalibutan", "matagal", "dugay", "init", "panahon", "kalibutan", "mundo"], "fact": {"tl": "Ang climate change ay ang pangmatagalang pagbabago ng karaniwang panahon at temperatura ng buong mundo.", "en": "Climate change is a long-term shift in the world's usual weather patterns and temperatures.", "bis": "Ang climate change mao ang dugay nga pagbag-o sa naandang panahon ug temperatura sa tibuok kalibutan."}, "source": "encyclopedia-stable consensus; NRC ESS3", "generator": "claude-workflow", "reviewed": false},
  {"id": "burning-fuel-releases-co2-g7", "domain": "EARTH_SPACE", "topic": "fossil fuels and carbon dioxide", "grades": [6, 7, 8], "terms": ["fossil fuel", "gasolina", "uling", "karbon", "coal", "pagsunog", "pagsunog ug gasolina", "kotse", "sakyanan", "pabrika", "pabrikahan", "factory", "usok", "aso", "carbon dioxide", "petrolyo", "diesel"], "fact": {"tl": "Kapag sinusunog natin ang gasolina, uling, at langis para sa kuryente at sasakyan, naglalabas ito ng carbon dioxide na nagpapainit sa mundo.", "en": "When we burn gasoline, coal, and oil for electricity and vehicles, they release carbon dioxide that warms the planet.", "bis": "Kon mosunog kita og gasolina, uling, ug lana para sa kuryente ug mga sakyanan, nagbuga kini og carbon dioxide nga nagpainit sa kalibutan."}, "source": "encyclopedia-stable consensus; NRC ESS3", "generator": "claude-workflow", "reviewed": false},
  {"id": "climate-change-melting-ice-g7", "domain": "EARTH_SPACE", "topic": "effects of climate change", "grades": [6, 7, 8], "terms": ["climate change", "pagtunaw", "natunaw", "yelo", "ice", "glacier", "tubig dagat", "sea level", "lebel sa dagat", "pagtaas ng tubig", "pagbaha", "baha", "natunaw na yelo", "pagkatunaw sa yelo", "global warming", "polo"], "fact": {"tl": "Dahil sa pag-init ng mundo, natutunaw ang malalaking yelo sa magkabilang polo ng Earth, kaya tumataas ang lebel ng tubig-dagat.", "en": "Because the planet is warming, large ice sheets at the poles are melting, which makes sea levels rise.", "bis": "Tungod sa pag-init sa kalibutan, natunaw ang dagkong yelo sa duha ka polo sa Yuta, mao nga motaas ang lebel sa tubig-dagat."}, "source": "encyclopedia-stable consensus; NRC ESS3", "generator": "claude-workflow", "reviewed": false},
  {"id": "ozone-layer-shield-g6", "domain": "EARTH_SPACE", "topic": "ozone layer", "grades": [5, 6, 7], "terms": ["ozone layer", "ozono", "ozon", "ozone", "kalasag", "panagang", "proteksyon", "ultraviolet", "UV", "sikat ng araw", "silaw sa adlaw", "atmospera", "atmospero", "taas nga hangin", "harmful rays", "delikadong sinag"], "fact": {"tl": "Ang ozone layer ay isang manipis na patong ng gas na mataas sa himpapawid na pumipigil sa nakakapinsalang ultraviolet rays ng araw.", "en": "The ozone layer is a thin layer of gas high in the sky that blocks the Sun's harmful ultraviolet rays.", "bis": "Ang ozone layer usa ka nipis nga sapaw sa gas sa taas nga kawanangan nga nagsanta sa makadaot nga ultraviolet rays sa adlaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ozone-hole-recovery-g7", "domain": "EARTH_SPACE", "topic": "ozone hole", "grades": [6, 7, 8], "terms": ["ozone hole", "butas sa ozone", "lungag sa ozone", "ozono", "ozone layer", "CFC", "aerosol", "spray", "refrigerator", "pridyider", "naghulip", "naghilom", "gumagaling", "humilom", "chemical", "kemikal", "naayo"], "fact": {"tl": "Noong nakaraan, may butas sa ozone layer dahil sa mga kemikal na CFC, ngunit dahil sa pagbabawal sa mga ito, dahan-dahan na itong gumagaling.", "en": "In the past, chemicals called CFCs created a hole in the ozone layer, but after they were banned the hole is slowly healing.", "bis": "Kaniadto, ang mga kemikal nga gitawag og CFC nakahimo og lungag sa ozone layer, apan human gidili kini, hinay-hinay na kining naayo."}, "source": "encyclopedia-stable consensus (Montreal Protocol)", "generator": "claude-workflow", "reviewed": false},
  {"id": "ozone-not-same-as-greenhouse-g8", "domain": "EARTH_SPACE", "topic": "ozone vs greenhouse confusion", "grades": [7, 8, 9], "terms": ["ozone layer", "ozono", "global warming", "greenhouse effect", "magkaiba", "lahi", "managlahi", "dili pareho", "magkaibang problema", "UV rays", "init", "naglibog", "different problems"], "fact": {"tl": "Magkaibang bagay ang butas sa ozone at ang global warming—ang ozone ay tungkol sa UV rays, samantalang ang global warming ay tungkol sa naiipong init.", "en": "The ozone hole and global warming are two different problems—ozone is about UV rays, while global warming is about trapped heat.", "bis": "Lahi nga butang ang lungag sa ozone ug ang global warming—ang ozone bahin sa UV rays, samtang ang global warming bahin sa natipon nga init."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "air-pollution-sources-g5", "domain": "EARTH_SPACE", "topic": "air pollution", "grades": [4, 5, 6], "terms": ["air pollution", "polusyon sa hangin", "hugaw nga hangin", "maruming hangin", "usok", "aso", "smoke", "sasakyan", "sakyanan", "pabrika", "pabrikahan", "factory", "smog", "kontaminado", "marumi", "hugaw"], "fact": {"tl": "Ang air pollution ay ang pagkakaroon ng maruming usok at gas sa hangin na galing sa mga sasakyan at pabrika.", "en": "Air pollution is dirty smoke and gases in the air, often coming from vehicles and factories.", "bis": "Ang air pollution mao ang hugaw nga aso ug mga gas sa hangin, kasagaran gikan sa mga sakyanan ug pabrikahan."}, "source": "encyclopedia-stable consensus; DepEd MATATAG Earth & Space", "generator": "claude-workflow", "reviewed": false},
  {"id": "air-pollution-health-g6", "domain": "LIVING_THINGS", "topic": "air pollution and health", "grades": [5, 6, 7], "terms": ["air pollution", "polusyon sa hangin", "baga", "baga sa tawo", "lungs", "paghinga", "ginhawa", "sakit", "hubak", "asthma", "ubo", "ubo-ubo", "kalusugan", "panglawas", "health", "maruming hangin"], "fact": {"tl": "Ang paghinga ng maruming hangin ay nakakasama sa ating baga at maaaring magdulot ng ubo, hika, at iba pang sakit.", "en": "Breathing dirty air harms our lungs and can cause coughing, asthma, and other illnesses.", "bis": "Ang pagginhawa og hugaw nga hangin makadaot sa atong baga ug mahimong hinungdan sa ubo, hubak, ug uban pang sakit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-pollution-basic-g5", "domain": "EARTH_SPACE", "topic": "water pollution", "grades": [4, 5, 6], "terms": ["water pollution", "polusyon sa tubig", "hugaw nga tubig", "maruming tubig", "ilog", "suba", "dagat", "basura", "basura sa tubig", "kemikal", "chemical", "imbornal", "kanal", "isda", "kontaminado", "marumi"], "fact": {"tl": "Ang water pollution ay nangyayari kapag may basura, kemikal, o dumi na pumapasok sa mga ilog, lawa, at dagat.", "en": "Water pollution happens when trash, chemicals, or waste get into rivers, lakes, and the sea.", "bis": "Ang water pollution mahitabo kon adunay basura, kemikal, o hugaw nga mosulod sa mga suba, lanaw, ug dagat."}, "source": "encyclopedia-stable consensus; DepEd MATATAG Earth & Space", "generator": "claude-workflow", "reviewed": false},
  {"id": "plastic-pollution-ocean-g6", "domain": "EARTH_SPACE", "topic": "plastic pollution", "grades": [5, 6, 7], "terms": ["plastic", "plastik", "plastic pollution", "polusyon sa plastik", "dagat", "ocean", "isda", "pawikan", "sea turtle", "hayop sa dagat", "basura", "single-use", "supot", "plastic bag", "nalulunod", "nakakain", "delikado"], "fact": {"tl": "Maraming plastik ang napupunta sa dagat, kung saan napagkakamalan itong pagkain ng mga isda at pawikan na maaaring ikamatay nila.", "en": "A lot of plastic ends up in the ocean, where fish and sea turtles mistake it for food, which can kill them.", "bis": "Daghang plastik ang maadto sa dagat, diin ang mga isda ug pawikan magtuo nga pagkaon kini, nga mahimong makapatay kanila."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "plastic-takes-long-to-break-down-g6", "domain": "EARTH_SPACE", "topic": "plastic decomposition", "grades": [5, 6, 7], "terms": ["plastik", "plastic", "matagal", "dugay", "madunot", "malanta", "decompose", "break down", "daghang tuig", "maraming taon", "hundred years", "microplastic", "maliliit na piraso", "gagmay nga tipik", "basura"], "fact": {"tl": "Ang plastik ay napakatagal bago madunot—maaaring umabot ng daan-daang taon, kaya patuloy itong naiipon sa kalikasan.", "en": "Plastic takes a very long time to break down—sometimes hundreds of years—so it keeps piling up in nature.", "bis": "Ang plastik dugay kaayo madunot—usahay moabot og gatusan ka tuig—mao nga padayon kining matipon sa kinaiyahan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "recycling-meaning-g4", "domain": "EARTH_SPACE", "topic": "recycling", "grades": [3, 4, 5], "terms": ["recycle", "recycling", "pag-recycle", "paggamit muli", "magamit pag-usab", "basura", "bagong gamit", "papel", "plastik", "bote", "lata", "garbage", "muling gamitin", "reuse", "bag-ong gamit"], "fact": {"tl": "Ang pag-recycle ay paggawa ng bagong bagay mula sa lumang basura, gaya ng paggawa ng bagong papel mula sa lumang papel.", "en": "Recycling means making new things out of old waste, like making new paper from used paper.", "bis": "Ang pag-recycle mao ang paghimo og bag-ong butang gikan sa daang basura, sama sa paghimo og bag-ong papel gikan sa daang papel."}, "source": "encyclopedia-stable consensus; DepEd MATATAG", "generator": "claude-workflow", "reviewed": false},
  {"id": "three-rs-reduce-reuse-recycle-g5", "domain": "EARTH_SPACE", "topic": "reduce reuse recycle", "grades": [4, 5, 6], "terms": ["reduce", "reuse", "recycle", "tatlong R", "3R", "tulo ka R", "bawasan", "kunhuran", "gamiting muli", "gamiton pag-usab", "basura", "garbage", "magtipid", "less waste", "limit", "tatlong hakbang"], "fact": {"tl": "Ang \"Tatlong R\"—Reduce, Reuse, Recycle—ay nangangahulugang bawasan, gamiting muli, at i-recycle ang ating mga gamit para mabawasan ang basura.", "en": "The \"Three Rs\"—Reduce, Reuse, Recycle—mean to use less, use again, and recycle our things to cut down on trash.", "bis": "Ang \"Tulo ka R\"—Reduce, Reuse, Recycle—nagpasabot nga kunhuran, gamiton pag-usab, ug i-recycle ang atong mga butang aron makunhuran ang basura."}, "source": "encyclopedia-stable consensus; DepEd MATATAG", "generator": "claude-workflow", "reviewed": false},
  {"id": "composting-g5", "domain": "EARTH_SPACE", "topic": "composting", "grades": [4, 5, 6], "terms": ["compost", "composting", "kompos", "abono", "patabang yutang", "nabubulok", "madunot nga basura", "food waste", "tira sa pagkain", "bunga", "dahon", "balat sa prutas", "lupa", "yuta", "halaman", "natural na pataba"], "fact": {"tl": "Ang composting ay paglalagay ng mga nabubulok na basura gaya ng balat ng prutas sa lupa para maging natural na pataba sa mga halaman.", "en": "Composting is letting food scraps like fruit peels rot in the soil so they become natural fertilizer for plants.", "bis": "Ang composting mao ang pagpadunot sa mga basura sama sa panit sa prutas sa yuta aron mahimo kining natural nga abono para sa mga tanom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "segregation-waste-g4", "domain": "EARTH_SPACE", "topic": "waste segregation", "grades": [3, 4, 5], "terms": ["segregation", "paghihiwalay ng basura", "pagbulag sa basura", "nabubulok", "hindi nabubulok", "biodegradable", "non-biodegradable", "basurahan", "trash bin", "recyclable", "tamang itapon", "sort", "uri ng basura"], "fact": {"tl": "Ang tamang paghihiwalay ng basura sa nabubulok at hindi nabubulok ay tumutulong para mas madaling ma-recycle ito.", "en": "Sorting trash into rotting and non-rotting kinds makes it easier to recycle.", "bis": "Ang husto nga pagbulag sa basura ngadto sa madunot ug dili madunot makatabang aron mas sayon kining ma-recycle."}, "source": "encyclopedia-stable consensus; RA 9003 (PH solid waste)", "generator": "claude-workflow", "reviewed": false},
  {"id": "trees-clean-air-g4", "domain": "LIVING_THINGS", "topic": "trees and air", "grades": [3, 4, 5], "terms": ["puno", "kahoy", "tree", "hangin", "oxygen", "carbon dioxide", "naglilinis ng hangin", "nagahinlo sa hangin", "nagtatanim", "pagtanim ug kahoy", "reforestation", "sariwang hangin", "presko", "halaman"], "fact": {"tl": "Ang mga puno ay sumisipsip ng carbon dioxide at naglalabas ng oxygen, kaya nakakatulong silang linisin ang hangin.", "en": "Trees soak up carbon dioxide and give off oxygen, so they help clean the air.", "bis": "Ang mga kahoy mosuyop og carbon dioxide ug mobuga og oxygen, mao nga makatabang sila sa paghinlo sa hangin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "deforestation-g6", "domain": "EARTH_SPACE", "topic": "deforestation", "grades": [5, 6, 7], "terms": ["deforestation", "pagkakalbo ng gubat", "pagkawala sa kalasangan", "gubat", "kalasangan", "kahoy", "puno", "pagputol", "pagputol ug kahoy", "logging", "tahanan ng hayop", "habitat", "baha", "pagguho ng lupa", "landslide", "naputol na puno"], "fact": {"tl": "Ang deforestation o pagputol ng maraming puno sa gubat ay nagpapawala ng tirahan ng mga hayop at nagdudulot ng baha at pagguho ng lupa.", "en": "Deforestation, the cutting down of many forest trees, destroys animal homes and leads to floods and landslides.", "bis": "Ang deforestation o pagputol sa daghang kahoy sa kalasangan magguba sa puy-anan sa mga hayop ug magdala og baha ug pagdahili sa yuta."}, "source": "encyclopedia-stable consensus; DepEd MATATAG", "generator": "claude-workflow", "reviewed": false},
  {"id": "conservation-meaning-g5", "domain": "EARTH_SPACE", "topic": "conservation", "grades": [4, 5, 6], "terms": ["conservation", "konserbasyon", "pag-amping", "pag-iingat", "pagtipid", "kalikasan", "kinaiyahan", "natural resources", "yamang likas", "protektahan", "panalipdan", "tubig", "gubat", "pag-alaga", "pag-amping sa kinaiyahan"], "fact": {"tl": "Ang conservation ay ang pag-iingat at matalinong paggamit ng likas na yaman gaya ng tubig at gubat para hindi ito maubos.", "en": "Conservation means protecting and wisely using natural resources like water and forests so they don't run out.", "bis": "Ang conservation mao ang pag-amping ug maalamon nga paggamit sa kinaiyanhong bahandi sama sa tubig ug kalasangan aron dili kini mahurot."}, "source": "encyclopedia-stable consensus; NRC ESS3", "generator": "claude-workflow", "reviewed": false},
  {"id": "endangered-species-protection-g6", "domain": "LIVING_THINGS", "topic": "protecting endangered species", "grades": [5, 6, 7], "terms": ["endangered", "namumuhay na malapit nang maubos", "nameligro", "hayop na malapit nang maubos", "extinct", "proteksyon", "panalipod", "tarsier", "agila", "Philippine eagle", "pawikan", "habitat", "tirahan", "ipreserba", "alagaan"], "fact": {"tl": "Ang ilang hayop gaya ng Philippine eagle at tarsier ay nanganganib nang maubos, kaya ipinagbabawal ng batas na sila ay saktan o hulihin.", "en": "Some animals like the Philippine eagle and tarsier are endangered, so the law forbids hurting or catching them.", "bis": "Ang pipila ka hayop sama sa Philippine eagle ug tarsier nameligro nga mahurot, mao nga gidili sa balaod nga sakitan o dakpon sila."}, "source": "encyclopedia-stable consensus; RA 9147 (PH Wildlife Act)", "generator": "claude-workflow", "reviewed": false},
  {"id": "protected-areas-g6", "domain": "EARTH_SPACE", "topic": "protected areas", "grades": [5, 6, 7], "terms": ["protected area", "protektadong lugar", "gipanalipdan nga lugar", "national park", "marine sanctuary", "santuwaryo", "Tubbataha", "reef", "bahura", "gubat", "hayop", "ipreserba", "bawal mangisda", "bawal mangahoy", "kalikasan", "reserba"], "fact": {"tl": "Ang mga protektadong lugar gaya ng Tubbataha Reef ay mga espesyal na pook kung saan bawal manghuli o manira para mapangalagaan ang kalikasan.", "en": "Protected areas like the Tubbataha Reef are special places where hunting and damage are banned to keep nature safe.", "bis": "Ang mga gipanalipdan nga lugar sama sa Tubbataha Reef mga espesyal nga dapit diin gidili ang pagpangayam o pagguba aron maamping ang kinaiyahan."}, "source": "encyclopedia-stable consensus (Tubbataha Reefs Natural Park)", "generator": "claude-workflow", "reviewed": false},
  {"id": "renewable-energy-clean-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "renewable energy and climate", "grades": [6, 7, 8], "terms": ["renewable energy", "malinis na enerhiya", "hinlo nga enerhiya", "solar", "araw", "adlaw", "hangin", "wind", "tubig", "hydro", "clean energy", "walang usok", "walay aso", "carbon dioxide", "solar panel", "windmill", "alternatibo"], "fact": {"tl": "Ang malilinis na enerhiya gaya ng solar at hangin ay hindi naglalabas ng carbon dioxide, kaya nakakatulong itong labanan ang climate change.", "en": "Clean energy like solar and wind power makes no carbon dioxide, so it helps fight climate change.", "bis": "Ang hinlo nga enerhiya sama sa solar ug hangin walay gibuga nga carbon dioxide, mao nga makatabang kini sa pagbatok sa climate change."}, "source": "encyclopedia-stable consensus; NRC ESS3/PS3", "generator": "claude-workflow", "reviewed": false},
  {"id": "acid-rain-g8", "domain": "EARTH_SPACE", "topic": "acid rain", "grades": [7, 8, 9], "terms": ["acid rain", "ulang asido", "asido nga ulan", "polusyon", "usok", "aso", "pabrika", "factory", "sulfur", "halaman", "tanom", "isda", "gusali", "ulan", "kemikal sa hangin", "nakakasira nga ulan"], "fact": {"tl": "Ang acid rain ay ulang naging asido dahil sa polusyon sa hangin, at nakakasira ito sa mga halaman, isda, at gusali.", "en": "Acid rain is rain that turned acidic because of air pollution, and it harms plants, fish, and buildings.", "bis": "Ang acid rain mao ang ulan nga nahimong asido tungod sa polusyon sa hangin, ug makadaot kini sa mga tanom, isda, ug mga building."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "litter-storm-drains-flood-g5", "domain": "EARTH_SPACE", "topic": "litter and flooding", "grades": [4, 5, 6], "terms": ["basura", "garbage", "litter", "kanal", "imbornal", "kanal nga tubig", "drainage", "barado", "nabara", "natambakan", "baha", "pagbaha", "estero", "ilog", "itapon", "tamang pagtapon", "flood"], "fact": {"tl": "Ang pagtapon ng basura sa kanal at estero ay nakakabara sa daloy ng tubig, kaya mas madaling magkaroon ng baha kapag umuulan.", "en": "Throwing trash into canals and waterways clogs the flow of water, so floods happen more easily when it rains.", "bis": "Ang paglabay og basura sa kanal ug sapa makababag sa agos sa tubig, mao nga mas sayon ang pagbaha kon mag-ulan."}, "source": "encyclopedia-stable consensus; DepEd MATATAG", "generator": "claude-workflow", "reviewed": false},
  {"id": "carbon-cycle-balance-g8", "domain": "EARTH_SPACE", "topic": "carbon and nature balance", "grades": [7, 8, 9], "terms": ["carbon", "carbon dioxide", "balanse", "balanse sa kinaiyahan", "puno", "dagat", "ocean", "sumisipsip", "mosuyop", "natural balance", "ekosistema", "ecosystem", "naiipon", "sobra", "labis", "atmospera", "atmospero"], "fact": {"tl": "Karaniwang balanse ang carbon dioxide sa hangin dahil sinisipsip ito ng mga puno at dagat, ngunit sumosobra na ito dahil sa gawain ng tao.", "en": "Carbon dioxide in the air is usually balanced because trees and oceans absorb it, but human activity is now adding too much.", "bis": "Kasagaran balanse ang carbon dioxide sa hangin kay gisuyop kini sa mga kahoy ug kadagatan, apan sobra na karon tungod sa buhat sa tawo."}, "source": "NRC Chapter 8 (atmospheric CO2 / dynamic equilibrium); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "save-water-conservation-g4", "domain": "EARTH_SPACE", "topic": "water conservation", "grades": [3, 4, 5], "terms": ["tubig", "water", "pagtipid", "pagtipid ug tubig", "pag-amping sa tubig", "save water", "gripo", "tubo", "tagas", "tulo", "leak", "maubos", "mahurot", "conserve water", "limpyong tubig"], "fact": {"tl": "Ang pagtipid sa tubig, gaya ng pagsasara ng gripo habang nagsesepilyo, ay tumutulong para hindi maubos ang malinis na tubig.", "en": "Saving water, like turning off the faucet while brushing your teeth, helps keep clean water from running out.", "bis": "Ang pagtipig sa tubig, sama sa pagsira sa gripo samtang nagsipilyo, makatabang aron dili mahurot ang limpyong tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "extreme-weather-climate-g8", "domain": "EARTH_SPACE", "topic": "climate change and extreme weather", "grades": [7, 8, 9], "terms": ["climate change", "pagbabago ng klima", "bagyo", "bagyong malakas", "kusog nga bagyo", "stronger storms", "tagtuyot", "drought", "hulaw", "init", "heat wave", "matinding panahon", "extreme weather", "sobrang init", "pagbaha", "mas malakas"], "fact": {"tl": "Ang climate change ay nagpapalakas ng ilang bagyo at nagdudulot ng mas matinding init at tagtuyot sa iba't ibang lugar.", "en": "Climate change makes some storms stronger and brings more intense heat and droughts in different places.", "bis": "Ang climate change makapakusog sa pipila ka bagyo ug magdala og mas grabe nga kainit ug hulaw sa nagkalain-laing dapit."}, "source": "encyclopedia-stable consensus; NRC ESS3", "generator": "claude-workflow", "reviewed": false},
  {"id": "seasons-caused-by-tilt-not-distance-g7", "domain": "EARTH_SPACE", "topic": "seasons are caused by tilt not distance", "grades": [7, 8, 9], "terms": ["seasons", "panahon", "season", "tilt", "pagkatagilid", "pagkahilig", "axis", "ehe", "init", "kainit", "layo sa araw", "distance", "hindi dahil sa layo", "dili tungod sa kalayo", "angulo", "anggulo", "sinag", "silaw", "sunlight"], "fact": {"tl": "Hindi nagkakaroon ng panahon (seasons) dahil sa layo ng Earth sa Araw — nagkakaroon ng panahon dahil nakatagilid ang ehe ng Earth, kaya iba't iba ang anggulo ng pagtama ng sinag sa iba't ibang bahagi sa loob ng taon.", "en": "Seasons are not caused by how far Earth is from the Sun — they happen because Earth's axis is tilted, so sunlight strikes different parts of Earth at different angles during the year.", "bis": "Ang panahon (seasons) dili tungod sa kalayo sa Earth gikan sa Adlaw — naa kini tungod kay nahilig ang ehe sa Earth, mao nga lain-lain ang anggulo sa pagtama sa silaw sa lain-laing bahin sulod sa tuig."}, "source": "AAAS BSL 4B/M4, 4B/H3", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-axis-tilt-23-degrees-g6", "domain": "EARTH_SPACE", "topic": "Earth's axis is tilted about 23.5 degrees", "grades": [6, 7, 8], "terms": ["ehe", "axis", "tilt", "tagilid", "hilig", "nakatagilid", "nahilig", "23 degrees", "23 digri", "Earth", "mundo", "kalibutan", "tuwid", "tul-id", "nakahapay", "tindog"], "fact": {"tl": "Hindi tuwid na nakatayo ang Earth — ang ehe (axis) nito ay nakatagilid nang mga 23.5 digri. Itong maliit na pagkatagilid na ito ang dahilan ng iba't ibang panahon sa mundo.", "en": "Earth does not stand straight up — its axis is tilted by about 23.5 degrees. This small tilt is the reason Earth has different seasons.", "bis": "Wala magtindog og tul-id ang Earth — ang ehe (axis) niini nahilig og mga 23.5 ka digri. Kining gamayng paghilig mao ang hinungdan sa lain-laing panahon sa kalibutan."}, "source": "AAAS BSL 4B/M4; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "summer-direct-sunlight-g7", "domain": "EARTH_SPACE", "topic": "why summer is hotter", "grades": [7, 8], "terms": ["tag-init", "tag-araw", "summer", "ting-init", "init", "mainit", "tuwirang sinag", "direktang sinag", "direct sunlight", "deretsong silaw", "nakatungo sa araw", "nahilig paingon sa adlaw", "mas mahaba ang araw", "mas taas ang adlaw", "anggulo"], "fact": {"tl": "Mas mainit sa tag-init dahil ang bahaging ito ng mundo ay nakatungo papunta sa Araw, kaya mas tuwiran at malakas ang pagtama ng sinag at mas mahaba ang maaraw na oras.", "en": "Summer is hotter because that part of Earth is tilted toward the Sun, so sunlight hits more directly and strongly and the daylight lasts longer.", "bis": "Mas init sa ting-init kay kanang bahina sa kalibutan nahilig paingon sa Adlaw, mao nga mas direkta ug kusog ang pagtama sa silaw ug mas taas ang oras nga adlaw."}, "source": "AAAS BSL 4B/M4, 4B/H3", "generator": "claude-workflow", "reviewed": false},
  {"id": "winter-slanted-sunlight-g7", "domain": "EARTH_SPACE", "topic": "why winter is colder", "grades": [7, 8], "terms": ["taglamig", "tingtugnaw", "winter", "lamig", "malamig", "bugnaw", "nakatalikod sa araw", "nahilig palayo sa adlaw", "pahilig na sinag", "slanted sunlight", "kiling nga silaw", "maikli ang araw", "mubo ang adlaw", "anggulo"], "fact": {"tl": "Mas malamig sa taglamig dahil ang bahaging ito ng mundo ay nakahilig palayo sa Araw, kaya pahilig na tumatama ang sinag at mas maikli ang maaraw na oras.", "en": "Winter is colder because that part of Earth is tilted away from the Sun, so sunlight hits at a slant and the daylight is shorter.", "bis": "Mas bugnaw sa tingtugnaw kay kanang bahina sa kalibutan nahilig palayo sa Adlaw, mao nga kiling ang pagtama sa silaw ug mas mubo ang oras nga adlaw."}, "source": "AAAS BSL 4B/M4, 4B/H3", "generator": "claude-workflow", "reviewed": false},
  {"id": "opposite-seasons-hemispheres-g7", "domain": "EARTH_SPACE", "topic": "opposite seasons in north and south", "grades": [7, 8], "terms": ["hemisphere", "hilaga", "amihanan", "north", "timog", "habagatan", "south", "magkasalungat na panahon", "magkasumpaki nga panahon", "opposite seasons", "tag-init sa isa", "tagilid", "magkaiba", "Australia", "Pilipinas"], "fact": {"tl": "Kapag tag-init sa hilagang bahagi ng mundo, taglamig naman sa timog na bahagi — magkasalungat ang panahon nila dahil ang nakahilig papunta sa Araw na bahagi ay isa lang sa pagkakataong iyon.", "en": "When it is summer in the northern half of the world, it is winter in the southern half — their seasons are opposite because only one half is tilted toward the Sun at a time.", "bis": "Kung ting-init sa amihanang bahin sa kalibutan, tingtugnaw sa habagatang bahin — magkasumpaki ang ilang panahon kay usa ra ka bahin ang nahilig paingon sa Adlaw matag higayon."}, "source": "AAAS BSL 4B/M4; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "summer-solstice-longest-day-g6", "domain": "EARTH_SPACE", "topic": "summer solstice the longest day", "grades": [6, 7, 8], "terms": ["solstice", "summer solstice", "pinakamahabang araw", "pinakataas nga adlaw", "longest day", "Hunyo", "June", "Hunyo 21", "araw na pinakamatagal ang liwanag", "taas ang adlaw", "nakahilig papunta sa araw"], "fact": {"tl": "Ang summer solstice ay ang araw na may pinakamahabang oras ng liwanag sa isang taon, na nangyayari mga Hunyo 21 sa hilagang bahagi ng mundo, kapag pinakanakatungo ang bahaging iyon sa Araw.", "en": "The summer solstice is the day with the most hours of daylight in the year, around June 21 in the northern half of the world, when that half is tilted most toward the Sun.", "bis": "Ang summer solstice mao ang adlaw nga adunay pinakataas nga oras sa kahayag sulod sa tuig, mga Hunyo 21 sa amihanang bahin sa kalibutan, kung kana nga bahin maoy labing nahilig paingon sa Adlaw."}, "source": "encyclopedia-stable consensus; AAAS BSL 4B/M4", "generator": "claude-workflow", "reviewed": false},
  {"id": "winter-solstice-shortest-day-g6", "domain": "EARTH_SPACE", "topic": "winter solstice the shortest day", "grades": [6, 7, 8], "terms": ["solstice", "winter solstice", "pinakamaikling araw", "pinakamubo nga adlaw", "shortest day", "Disyembre", "December", "Disyembre 21", "maikli ang liwanag", "mubo ang adlaw", "nakahilig palayo sa araw"], "fact": {"tl": "Ang winter solstice ay ang araw na may pinakamaikling oras ng liwanag sa isang taon, na nangyayari mga Disyembre 21 sa hilagang bahagi ng mundo, kapag pinakanakahilig palayo ang bahaging iyon sa Araw.", "en": "The winter solstice is the day with the fewest hours of daylight in the year, around December 21 in the northern half of the world, when that half is tilted most away from the Sun.", "bis": "Ang winter solstice mao ang adlaw nga adunay pinakamubo nga oras sa kahayag sulod sa tuig, mga Disyembre 21 sa amihanang bahin sa kalibutan, kung kana nga bahin maoy labing nahilig palayo sa Adlaw."}, "source": "encyclopedia-stable consensus; AAAS BSL 4B/M4", "generator": "claude-workflow", "reviewed": false},
  {"id": "equinox-equal-day-night-g6", "domain": "EARTH_SPACE", "topic": "equinox equal day and night", "grades": [6, 7, 8], "terms": ["equinox", "pantay ang araw at gabi", "patas ang adlaw ug gabii", "equal day night", "Marso", "Setyembre", "March", "September", "katumbas ang liwanag", "12 oras", "walang tagilid sa araw", "wala mahilig sa adlaw"], "fact": {"tl": "Sa equinox, halos pantay ang haba ng araw at gabi sa buong mundo — mga 12 oras bawat isa. Nangyayari ito ng dalawang beses sa isang taon, mga Marso 21 at Setyembre 23.", "en": "On an equinox, day and night are nearly equal in length all over the world — about 12 hours each. It happens twice a year, around March 21 and September 23.", "bis": "Sa equinox, halos patas ang gitas-on sa adlaw ug gabii sa tibuok kalibutan — mga 12 ka oras matag usa. Mahitabo kini kaduha sa usa ka tuig, mga Marso 21 ug Setyembre 23."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-ph-no-four-seasons-g5", "domain": "EARTH_SPACE", "topic": "why the Philippines has no four seasons", "grades": [5, 6, 7], "terms": ["Pilipinas", "Philippines", "ekwador", "equator", "ekuwador", "malapit sa gitna", "duol sa tunga", "tropical", "walang taglamig", "wala tingtugnaw", "init buong taon", "init tibuok tuig", "deretsong sinag", "tuwirang sinag", "apat na panahon", "upat ka panahon"], "fact": {"tl": "Walang apat na panahon ang Pilipinas dahil malapit ito sa ekwador, kung saan halos tuwiran ang sinag ng Araw buong taon — kaya mainit lagi at wala tayong taglamig.", "en": "The Philippines has no four seasons because it lies near the equator, where the Sun's rays are nearly direct all year — so it stays warm and we have no winter.", "bis": "Walay upat ka panahon ang Pilipinas kay duol kini sa ekwador, diin halos tul-id ang silaw sa Adlaw tibuok tuig — mao nga init kanunay ug wala tay tingtugnaw."}, "source": "AAAS BSL 4B/M4; DepEd Science CG", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-rotation-speed-g7", "domain": "EARTH_SPACE", "topic": "Earth spins very fast", "grades": [7, 8], "terms": ["rotation", "umiikot", "molibot", "bilis ng pag-ikot", "katulin sa paglibot", "spin speed", "mabilis", "paspas", "hindi nararamdaman", "wala mabati", "1600 km", "ekwador", "equator", "bakit hindi natatangay"], "fact": {"tl": "Umiikot ang Earth nang napakabilis — sa ekwador, umaabot sa mga 1,600 kilometro kada oras ang bilis ng ibabaw nito — pero hindi natin ito nararamdaman dahil kasama nating umiikot ang lahat, pati ang hangin.", "en": "Earth spins very fast — at the equator its surface moves about 1,600 kilometers per hour — but we do not feel it because everything, including the air, turns along with us.", "bis": "Molibot ang Earth nga paspas kaayo — sa ekwador, mokabat og mga 1,600 ka kilometro matag oras ang katulin sa ibabaw niini — apan dili nato kini mabati kay kuyog tang tanan nga molibot, lakip ang hangin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-rises-east-rotation-g4", "domain": "EARTH_SPACE", "topic": "why the sun rises in the east", "grades": [4, 5, 6], "terms": ["silangan", "sidlakan", "east", "kanluran", "kasadpan", "west", "sumisikat", "mosubang", "pagsikat", "sunrise", "paglubog", "salop", "sunset", "umiikot pasilangan", "molibot", "rotation", "araw", "adlaw"], "fact": {"tl": "Lagi nating nakikitang sumisikat ang Araw sa silangan at lumulubog sa kanluran dahil umiikot ang Earth papuntang silangan; kaya tila gumagalaw ang Araw sa kabilang direksyon sa langit.", "en": "We always see the Sun rise in the east and set in the west because Earth spins toward the east; this makes the Sun appear to move the other way across the sky.", "bis": "Kanunay natong makita nga mosubang ang Adlaw sa sidlakan ug mosalop sa kasadpan kay molibot ang Earth paingon sa sidlakan; mao nga morag molihok ang Adlaw sa pikas direksyon sa langit."}, "source": "AAAS BSL 4B/E2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "stars-appear-to-move-rotation-g6", "domain": "EARTH_SPACE", "topic": "stars appear to move because Earth rotates", "grades": [6, 7], "terms": ["bituin", "bituon", "stars", "gumagalaw ang bituin", "molihok ang bituon", "umiikot ang langit", "nagatuyok ang langit", "rotation", "umiikot ang earth", "molibot ang earth", "north star", "polaris", "nakatutok", "gabi", "gabii", "hindi talaga gumagalaw"], "fact": {"tl": "Sa gabi, parang umiikot ang lahat ng bituin sa langit, pero hindi talaga sila ang gumagalaw — ang Earth ang umiikot, kaya nagbabago ang tanawin natin sa kalawakan.", "en": "At night the stars seem to circle across the sky, but they are not really the ones moving — Earth is rotating, so our view of space keeps changing.", "bis": "Sa gabii, morag molibot ang tanang bituon sa langit, apan dili sila ang tinuod nga naglihok — ang Earth maoy molibot, mao nga mausab ang atong panan-aw sa kawanangan."}, "source": "AAAS BSL 4B/E2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "leap-year-extra-day-g6", "domain": "EARTH_SPACE", "topic": "leap year and the extra quarter day", "grades": [6, 7], "terms": ["leap year", "taong lukso", "tuig nga lukso", "366 araw", "366 ka adlaw", "Pebrero 29", "February 29", "Pebrero", "dagdag na araw", "dugang nga adlaw", "365 at kalahati", "365 ug tunga", "revolution", "umiikot sa araw", "molibot sa adlaw", "kada apat na taon"], "fact": {"tl": "Hindi eksaktong 365 araw ang isang pag-ikot ng Earth sa Araw, kundi mga 365 araw at kalahating araw; kaya tuwing ika-apat na taon, dinadagdagan natin ng isang araw (Pebrero 29) — ang leap year.", "en": "Earth's trip around the Sun is not exactly 365 days but about 365 and a quarter days; so every fourth year we add one extra day (February 29) — a leap year.", "bis": "Dili eksaktong 365 ka adlaw ang usa ka libot sa Earth sa Adlaw, kondili mga 365 ug tunga ka adlaw; mao nga matag ikaupat ka tuig, modugang ta og usa ka adlaw (Pebrero 29) — ang leap year."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "solar-eclipse-new-moon-g7", "domain": "EARTH_SPACE", "topic": "solar eclipse happens at new moon", "grades": [7, 8], "terms": ["solar eclipse", "eklipse sa araw", "eklipse sa adlaw", "buwan humaharang sa araw", "bulan moali sa adlaw", "anino ng buwan", "anino sa bulan", "bagong buwan", "bag-ong bulan", "new moon", "umaga", "araw na dumidilim", "mongitngit", "nagdidilim"], "fact": {"tl": "Nagkakaroon ng solar eclipse kapag dumadaan ang buwan sa pagitan ng Earth at Araw, kaya humaharang ito sa liwanag at bumabagsak ang anino ng buwan sa Earth. Nangyayari lang ito kapag bagong buwan.", "en": "A solar eclipse happens when the Moon passes between Earth and the Sun, blocking its light so the Moon's shadow falls on Earth. It can only happen at new moon.", "bis": "Adunay solar eclipse kung moagi ang bulan tungatunga sa Earth ug Adlaw, mao nga moali kini sa kahayag ug mahulog ang anino sa bulan sa Earth. Mahitabo lang kini kung bag-ong bulan."}, "source": "encyclopedia-stable consensus; AAAS BSL 4A", "generator": "claude-workflow", "reviewed": false},
  {"id": "lunar-eclipse-full-moon-g7", "domain": "EARTH_SPACE", "topic": "lunar eclipse happens at full moon", "grades": [7, 8], "terms": ["lunar eclipse", "eklipse sa buwan", "eklipse sa bulan", "earth humaharang", "earth moali", "anino ng earth", "anino sa earth", "kabilugan ng buwan", "takdol", "full moon", "buong buwan", "gabi", "gabii", "dumidilim ang buwan", "mongitngit ang bulan"], "fact": {"tl": "Nagkakaroon ng lunar eclipse kapag nasa pagitan ng Araw at buwan ang Earth, kaya tumatama ang anino ng Earth sa buwan. Nangyayari lang ito kapag kabilugan ng buwan (full moon).", "en": "A lunar eclipse happens when Earth is between the Sun and the Moon, so Earth's shadow falls on the Moon. It can only happen at full moon.", "bis": "Adunay lunar eclipse kung ang Earth anaa sa tungatunga sa Adlaw ug bulan, mao nga motama ang anino sa Earth sa bulan. Mahitabo lang kini kung takdol o full moon."}, "source": "encyclopedia-stable consensus; AAAS BSL 4A", "generator": "claude-workflow", "reviewed": false},
  {"id": "blood-moon-red-eclipse-g7", "domain": "EARTH_SPACE", "topic": "why the moon turns red during a lunar eclipse", "grades": [7, 8, 9], "terms": ["blood moon", "pulang buwan", "pula nga bulan", "red moon", "namumula", "namumula ang buwan", "namula ang bulan", "lunar eclipse", "eklipse sa buwan", "pulang liwanag", "pula nga kahayag", "atmospera", "kapaligiran", "scattered", "nakukurba ang liwanag"], "fact": {"tl": "Tuwing lunar eclipse, namumula ang buwan dahil ang ilang liwanag ng Araw ay dumadaan sa atmospera ng Earth, na sumasala sa ibang kulay at nagpapadaan ng pulang liwanag papunta sa buwan.", "en": "During a lunar eclipse the Moon turns reddish because some of the Sun's light passes through Earth's atmosphere, which filters out other colors and bends red light onto the Moon.", "bis": "Sa lunar eclipse, mamula ang bulan kay ang ubang kahayag sa Adlaw moagi sa atmospera sa Earth, nga mosala sa ubang kolor ug mopaagi sa pula nga kahayag paingon sa bulan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "total-solar-eclipse-rare-g7", "domain": "EARTH_SPACE", "topic": "why total solar eclipses are rare in one place", "grades": [7, 8], "terms": ["total solar eclipse", "ganap na eklipse", "bug-os nga eklipse", "bihira", "talagsa", "rare", "maliit na anino", "gamayng anino", "umaga ng dumilim", "tindi sa kangitngit", "buwan eksaktong tumatakip", "bulan eksaktong motakip", "kasinglaki ng araw"], "fact": {"tl": "Bihira maranasan ang ganap na solar eclipse sa isang lugar dahil maliit lang ang madilim na anino ng buwan, kaya iilang lugar lamang sa Earth ang madadaanan nito sa bawat eklipse.", "en": "A total solar eclipse is rare in any one place because the Moon's dark shadow is small, so it touches only a narrow strip of Earth during each eclipse.", "bis": "Talagsa ra masinati ang bug-os nga solar eclipse sa usa ka dapit kay gamay ra ang ngitngit nga anino sa bulan, mao nga pipila ra ka dapit sa Earth ang maagian niini matag eklipse."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "never-look-at-sun-eclipse-g5", "domain": "EARTH_SPACE", "topic": "never look directly at a solar eclipse", "grades": [5, 6, 7], "terms": ["solar eclipse", "eklipse sa araw", "eklipse sa adlaw", "huwag tumingin", "ayaw pagtan-aw", "delikado sa mata", "peligro sa mata", "nakakasilaw", "makasunog sa mata", "danger to eyes", "espesyal na salamin", "espesyal nga antiyohos", "kaligtasan", "kaluwasan"], "fact": {"tl": "Huwag kailanman tumingin nang tuwiran sa Araw kahit may solar eclipse — masisira nito ang mata. Kailangan ng espesyal na salamin para sa eklipse o tingnan na lamang ang anino nito sa papel.", "en": "Never look straight at the Sun even during a solar eclipse — it can damage your eyes. You need special eclipse glasses, or just watch its shadow projected on paper.", "bis": "Ayaw gyud pagtan-aw og direkta sa Adlaw bisan adunay solar eclipse — makadaot kini sa imong mata. Kinahanglan og espesyal nga antiyohos alang sa eklipse, o tan-awa na lang ang anino niini sa papel."}, "source": "encyclopedia-stable consensus (eye safety)", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-not-eclipse-every-month-g8", "domain": "EARTH_SPACE", "topic": "why eclipses do not happen every month", "grades": [8, 9], "terms": ["eclipse", "eklipse", "bakit hindi kada buwan", "ngano dili kada bulan", "tagilid na orbita", "hilig nga orbita", "tilted orbit", "5 degrees", "5 digri", "nakahilig ang landas ng buwan", "nahilig ang dalan sa bulan", "hindi laging nagkakahanay", "dili kanunay maglinya"], "fact": {"tl": "Hindi nagkakaroon ng eclipse kada buwan dahil bahagyang nakahilig ang landas ng buwan kumpara sa landas ng Earth, kaya kadalasan ay nasa itaas o ibaba ng linya ang buwan at hindi tumatama ang anino.", "en": "Eclipses do not happen every month because the Moon's path is tilted a little compared to Earth's path, so the Moon usually passes above or below the line and no shadow lands.", "bis": "Wala'y eclipse matag bulan kay gamay nga nahilig ang dalan sa bulan kumpara sa dalan sa Earth, mao nga kasagaran ang bulan moagi sa ibabaw o ubos sa linya ug walay anino nga motama."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "day-length-changes-over-year-g6", "domain": "EARTH_SPACE", "topic": "why daylight length changes through the year", "grades": [6, 7], "terms": ["haba ng araw", "gitas-on sa adlaw", "daylight length", "umaga at gabi", "nagbabago ang haba ng liwanag", "mausab ang gitas-on sa kahayag", "mas mahabang araw", "mas taas nga adlaw", "tag-init", "ting-init", "tag-lamig", "tingtugnaw", "tagilid", "hilig"], "fact": {"tl": "Hindi pantay ang haba ng araw at gabi buong taon sa karamihan ng lugar — dahil sa pagkatagilid ng Earth, mas mahaba ang araw kapag tag-init at mas maikli kapag taglamig.", "en": "In most places day and night are not equal all year — because Earth is tilted, daylight is longer in summer and shorter in winter.", "bis": "Sa kadaghanang dapit, dili patas ang gitas-on sa adlaw ug gabii tibuok tuig — tungod sa paghilig sa Earth, mas taas ang adlaw sa ting-init ug mas mubo sa tingtugnaw."}, "source": "AAAS BSL 4B/M4; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "midnight-sun-poles-g8", "domain": "EARTH_SPACE", "topic": "midnight sun and polar night", "grades": [8, 9], "terms": ["midnight sun", "araw sa hatinggabi", "adlaw sa tungang gabii", "polar night", "gabi na walang araw", "gabii nga walay adlaw", "polo", "tumoy sa kalibutan", "Arctic", "Antarctica", "araw na hindi lumulubog", "adlaw nga dili mosalop", "24 oras na liwanag", "24 oras nga kangitngit"], "fact": {"tl": "Malapit sa mga polo ng Earth, may panahong hindi lumulubog ang Araw nang ilang araw (midnight sun) at panahong hindi ito sumisikat — dulot ito ng matinding pagkatagilid ng Earth sa mga lugar na iyon.", "en": "Near Earth's poles, there are times when the Sun does not set for days (the midnight sun) and times when it does not rise at all — caused by Earth's strong tilt at those places.", "bis": "Duol sa mga polo sa Earth, adunay panahon nga dili mosalop ang Adlaw sulod sa pipila ka adlaw (midnight sun) ug panahon nga dili kini mosubang — tungod sa kusog nga paghilig sa Earth niadtong mga dapita."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-revolution-speed-g8", "domain": "EARTH_SPACE", "topic": "Earth travels fast around the Sun", "grades": [8, 9], "terms": ["revolution", "umiikot sa araw", "molibot sa adlaw", "bilis", "katulin", "speed", "mabilis", "paspas", "orbita", "orbit", "landas", "dalan", "100,000 km", "isang taon", "usa ka tuig", "30 km kada segundo"], "fact": {"tl": "Habang umiikot ang Earth sa Araw, naglalakbay ito nang napakabilis — mga 30 kilometro kada segundo — pero hindi natin nararamdaman ang paggalaw na ito.", "en": "As Earth orbits the Sun, it travels very fast — about 30 kilometers every second — yet we do not feel this motion at all.", "bis": "Samtang molibot ang Earth sa Adlaw, mobiyahe kini nga paspas kaayo — mga 30 ka kilometro matag segundo — apan dili gyud nato mabati kining paglihok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "shadows-change-during-day-g4", "domain": "EARTH_SPACE", "topic": "shadows change length and direction during the day", "grades": [4, 5, 6], "terms": ["anino", "shadow", "landong", "nagbabago", "mausab", "mahaba sa umaga", "taas sa buntag", "maikli sa tanghali", "mubo sa udto", "tanghaling-tapat", "udto", "umiikot ang araw sa langit", "molihok ang adlaw", "posisyon ng araw", "posisyon sa adlaw"], "fact": {"tl": "Nagbabago ang haba at direksyon ng ating anino sa buong araw — mahaba ito sa umaga at hapon kapag mababa ang Araw, at pinakamaikli sa tanghali kapag mataas ang Araw sa langit.", "en": "Our shadow changes length and direction through the day — it is long in the morning and afternoon when the Sun is low, and shortest at noon when the Sun is high.", "bis": "Mausab ang gitas-on ug direksyon sa atong landong sa tibuok adlaw — taas kini sa buntag ug hapon kung ubos ang Adlaw, ug pinakamubo sa udto kung taas ang Adlaw sa langit."}, "source": "AAAS BSL 4B (light and angle); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-orbit-nearly-circle-g8", "domain": "EARTH_SPACE", "topic": "Earth's orbit is nearly a circle", "grades": [8, 9], "terms": ["orbita", "orbit", "landas", "dalan", "hugis", "porma", "bilog na landas", "lingin nga dalan", "halos bilog", "halos lingin", "nearly circle", "hindi perpektong bilog", "dili hingpit nga lingin", "elliptical", "layo sa araw"], "fact": {"tl": "Halos bilog ang landas (orbita) ng Earth sa paligid ng Araw, kaya halos pareho lang ang layo nito sa Araw buong taon — kaya hindi ang layo ang nagdudulot ng panahon.", "en": "Earth's path around the Sun is nearly a circle, so its distance from the Sun stays almost the same all year — which is why distance is not what causes the seasons.", "bis": "Halos lingin ang dalan (orbita) sa Earth libot sa Adlaw, mao nga halos parehas ra ang kalayo niini sa Adlaw tibuok tuig — mao nga dili ang kalayo ang hinungdan sa panahon."}, "source": "encyclopedia-stable consensus; AAAS BSL 4B/M4", "generator": "claude-workflow", "reviewed": false},
  {"id": "geocentric-vs-heliocentric-g7", "domain": "EARTH_SPACE", "topic": "Earth orbits the Sun not the other way", "grades": [7, 8], "terms": ["heliocentric", "araw ang sentro", "adlaw ang sentro", "Sun centered", "geocentric", "akala dati", "kanhi gituohan", "earth ang sentro", "umiikot sa araw", "molibot sa adlaw", "Copernicus", "Galileo", "hindi ang araw ang umiikot", "dili ang adlaw ang molibot"], "fact": {"tl": "Noong unang panahon, akala ng mga tao na ang Earth ang sentro at ang Araw ang umiikot dito; ngayon alam na natin na ang Earth ang umiikot sa Araw, isang ideyang ipinaliwanag nina Copernicus at Galileo.", "en": "Long ago people thought Earth was the center and the Sun went around it; today we know Earth orbits the Sun, an idea explained by Copernicus and Galileo.", "bis": "Kaniadto, gituohan sa mga tawo nga ang Earth maoy sentro ug ang Adlaw molibot niini; karon nahibalo na ta nga ang Earth maoy molibot sa Adlaw, usa ka ideya nga gipasabot nila Copernicus ug Galileo."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.4", "generator": "claude-workflow", "reviewed": false},
  {"id": "time-zones-from-rotation-g6", "domain": "EARTH_SPACE", "topic": "time zones come from Earth's rotation", "grades": [6, 7, 8], "terms": ["time zone", "sona ng oras", "sona sa oras", "iba't ibang oras", "lain-laing oras", "different time", "umaga sa isa gabi sa iba", "buntag sa usa gabii sa lain", "umiikot ang earth", "molibot ang earth", "rotation", "kabilang bansa", "lain-laing nasod", "mas maaga o mas huli"], "fact": {"tl": "Magkakaiba ang oras sa iba't ibang bahagi ng mundo dahil umiikot ang Earth — kapag tanghali sa Pilipinas, gabi na sa Amerika at iba ang oras sa ibang bansa.", "en": "Different parts of the world have different times because Earth rotates — when it is noon in the Philippines, it is night in America and a different time of day in other countries.", "bis": "Lain-lain ang oras sa lain-laing bahin sa kalibutan kay molibot ang Earth — kung udto sa Pilipinas, gabii na sa Amerika ug lahi ang oras sa ubang nasod."}, "source": "encyclopedia-stable consensus; AAAS BSL 4B/E2", "generator": "claude-workflow", "reviewed": false},
  {"id": "tilt-stays-same-direction-g8", "domain": "EARTH_SPACE", "topic": "Earth's tilt always points the same way", "grades": [8, 9], "terms": ["tagilid", "hilig", "tilt", "laging nakaturo sa iisang direksyon", "kanunay nagaturo sa usa ka direksyon", "fixed direction", "north star", "polaris", "hindi nagbabago ang tagilid", "dili mausab ang hilig", "habang umiikot sa araw", "samtang molibot sa adlaw", "kaya magkaiba ang panahon"], "fact": {"tl": "Habang umiikot ang Earth sa Araw, laging nakaturo sa iisang direksyon ang pagkatagilid nito (papunta sa North Star) — ito ang dahilan kung bakit nagbabago ang panahon sa iba't ibang bahagi ng taon.", "en": "As Earth orbits the Sun, its tilt keeps pointing the same direction (toward the North Star) — this is why the seasons change at different parts of the year.", "bis": "Samtang molibot ang Earth sa Adlaw, ang paghilig niini kanunay nagaturo sa usa ka direksyon (paingon sa North Star) — mao kini ang hinungdan nganong mausab ang panahon sa lain-laing bahin sa tuig."}, "source": "encyclopedia-stable consensus; AAAS BSL 4B/M4", "generator": "claude-workflow", "reviewed": false},
  {"id": "annular-eclipse-ring-g8", "domain": "EARTH_SPACE", "topic": "annular eclipse the ring of fire", "grades": [8, 9], "terms": ["annular eclipse", "singsing na eklipse", "singsing nga eklipse", "ring of fire", "singsing ng apoy", "singsing sa kalayo", "buwan mas maliit", "bulan mas gamay", "malayo ang buwan", "layo ang bulan", "hindi ganap na takip", "dili bug-os nga tabon", "solar eclipse"], "fact": {"tl": "Kapag malayo ang buwan sa Earth tuwing solar eclipse, hindi nito ganap na natatakpan ang Araw, kaya nakikita ang isang maliwanag na singsing sa paligid ng buwan — tinatawag itong annular eclipse o 'ring of fire'.", "en": "When the Moon is far from Earth during a solar eclipse, it cannot fully cover the Sun, so a bright ring shows around the Moon — this is called an annular eclipse or 'ring of fire'.", "bis": "Kung layo ang bulan sa Earth panahon sa solar eclipse, dili niini matabonan og bug-os ang Adlaw, mao nga makita ang masilaw nga singsing libot sa bulan — gitawag kini og annular eclipse o 'ring of fire'."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "what-is-a-landform-g3", "domain": "EARTH_SPACE", "topic": "landforms basics", "grades": [3, 4], "terms": ["landform", "anyo ng lupa", "mga anyong lupa", "bundok", "kapatagan", "burol", "lapyahan sa yuta", "dagway sa yuta", "bukid", "patag", "mountain", "valley", "plain", "hill"], "fact": {"tl": "Ang anyong lupa ay ang iba't ibang hugis ng ibabaw ng lupa, tulad ng bundok, burol, kapatagan, at lambak.", "en": "A landform is a natural shape on Earth's surface, such as a mountain, hill, plain, or valley.", "bis": "Ang anyo sa yuta mao ang lain-laing porma sa ibabaw sa kalibotan, sama sa bukid, bungtod, patag, ug walog."}, "source": "AAAS Benchmarks 4C/M8 (variety of landforms)", "generator": "claude-workflow", "reviewed": false},
  {"id": "how-mountains-form-g5", "domain": "EARTH_SPACE", "topic": "how mountains form", "grades": [5, 6, 7], "terms": ["bundok", "paano nabubuo ang bundok", "plate", "kapatagan ng lupa", "nagtutulak", "bukid", "unsaon pagporma sa bukid", "plata sa yuta", "nagduot", "mountain", "form", "plates", "push up"], "fact": {"tl": "Maraming bundok ang nabubuo kapag dahan-dahang nagtutulak ang malalaking piraso ng balat ng Mundo at nag-aangat ng lupa pataas.", "en": "Many mountains form when huge pieces of Earth's crust slowly push against each other and lift the land upward.", "bis": "Daghang bukid ang naporma kung ang dagkong piraso sa panit sa Kalibotan hinay-hinay nga magduot ug mag-alsa sa yuta pataas."}, "source": "AAAS Benchmarks 4C/H5 (plate collision builds mountains)", "generator": "claude-workflow", "reviewed": false},
  {"id": "mountains-wear-down-g6", "domain": "EARTH_SPACE", "topic": "mountains erode over time", "grades": [6, 7, 8], "terms": ["bundok", "naaagnas", "tubig", "hangin", "yelo", "pinapababa", "nagkakagutay", "bukid", "nahurot", "nataes", "wind", "water", "ice", "wear down", "erode"], "fact": {"tl": "Sa napakahabang panahon, unti-unting pinapababa ng tubig, yelo, at hangin ang mga bundok hanggang sa maging mas pantay ang lupa.", "en": "Over very long times, water, ice, and wind slowly wear mountains down until the land becomes flatter.", "bis": "Sa hataas kaayo nga panahon, ang tubig, yelo, ug hangin hinay-hinay nga magpaubos sa mga bukid hangtod nga mahimong mas patag ang yuta."}, "source": "AAAS Benchmarks 4C/M2b (water and wind level mountain ranges)", "generator": "claude-workflow", "reviewed": false},
  {"id": "what-is-a-valley-g4", "domain": "EARTH_SPACE", "topic": "valleys", "grades": [4, 5], "terms": ["lambak", "valley", "kapatagan sa pagitan ng bundok", "ilog", "inukit", "walog", "patag tunga sa bukid", "sapa", "carved", "river", "low land"], "fact": {"tl": "Ang lambak ay mababang lupa sa pagitan ng mga bundok o burol, at kadalasang inukit ito ng isang ilog sa paglipas ng panahon.", "en": "A valley is low land between mountains or hills, often carved out by a river over a long time.", "bis": "Ang walog mao ang ubos nga yuta tunga sa mga bukid o bungtod, kasagaran gikalot kini sa usa ka suba sa paglabay sa panahon."}, "source": "encyclopedia-stable consensus; AAAS 4C/M2b (rivers carve land)", "generator": "claude-workflow", "reviewed": false},
  {"id": "what-is-a-plateau-g5", "domain": "EARTH_SPACE", "topic": "plateaus", "grades": [5, 6], "terms": ["talampas", "plateau", "mataas na patag na lupa", "mesa", "talampad", "habog nga patag", "mataas ug patag", "flat highland", "high flat land"], "fact": {"tl": "Ang talampas ay malawak na lupang patag sa ibabaw ngunit nakaangat at mataas kaysa sa palibot nito.", "en": "A plateau is a wide area of flat land that sits high above the land around it.", "bis": "Ang talampad mao ang lapad nga patag nga yuta nga taas ug habog kaysa sa palibot niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "how-caves-form-g6", "domain": "EARTH_SPACE", "topic": "how caves form", "grades": [6, 7], "terms": ["kuweba", "yungib", "paano nabubuo ang kuweba", "tubig", "apog", "limestone", "tinutunaw", "langob", "gilungag", "tubig nga mokaon sa bato", "cave", "limestone", "dissolve", "underground"], "fact": {"tl": "Maraming kuweba ang nabubuo kapag dahan-dahang tinutunaw ng bahagyang asim na tubig ang batong-apog (limestone) sa ilalim ng lupa.", "en": "Many caves form when slightly acidic water slowly dissolves limestone rock underground.", "bis": "Daghang langob ang naporma kung ang gamay nga aslom nga tubig hinay-hinay nga motunaw sa limestone nga bato ilalom sa yuta."}, "source": "encyclopedia-stable consensus (karst/limestone cave formation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "stalactites-stalagmites-g6", "domain": "EARTH_SPACE", "topic": "cave formations", "grades": [6, 7], "terms": ["stalactite", "stalagmite", "nakabitin sa kisame ng kuweba", "tumutubo pataas", "mineral", "tumutulo", "nagbitay sa langob", "tumubo sa salog", "drip", "hang", "grow up", "ceiling", "floor"], "fact": {"tl": "Sa loob ng kuweba, ang stalactite ay tumutubong pababa mula sa kisame, habang ang stalagmite ay tumutubong pataas mula sa sahig dahil sa tumutulong tubig na may mineral.", "en": "Inside a cave, stalactites grow down from the ceiling and stalagmites grow up from the floor as mineral-filled water drips over many years.", "bis": "Sulod sa langob, ang stalactite motubo paubos gikan sa kisame, samtang ang stalagmite motubo pataas gikan sa salog tungod sa nagtulo nga tubig nga adunay mineral."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "what-is-a-desert-g4", "domain": "EARTH_SPACE", "topic": "deserts", "grades": [4, 5], "terms": ["disyerto", "desert", "tuyo", "kakaunti ang ulan", "mainit", "buhangin", "desyerto", "uga", "gamay ang ulan", "init", "balas", "dry", "little rain", "sand"], "fact": {"tl": "Ang disyerto ay napakatuyong lugar na kakaunti lang ang ulan, kaya iilang halaman at hayop lang ang nakakatira roon.", "en": "A desert is a very dry place that gets very little rain, so only a few plants and animals can live there.", "bis": "Ang desyerto mao ang uga kaayo nga dapit nga gamay ra kaayo ang ulan, mao nga pipila ra ka tanom ug hayop ang makapuyo didto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "deserts-not-always-hot-g6", "domain": "EARTH_SPACE", "topic": "cold deserts", "grades": [6, 7], "terms": ["disyerto", "malamig na disyerto", "hindi laging mainit", "Antarctica", "tuyo", "bugnaw nga desyerto", "dili kanunay init", "uga", "cold desert", "not always hot", "dry"], "fact": {"tl": "Hindi lahat ng disyerto ay mainit; may mga malamig na disyerto rin tulad ng Antarctica, na tuyo dahil napakakaunti ng ulan o niyebe roon.", "en": "Not all deserts are hot; some deserts are cold, like Antarctica, which is dry because it gets very little rain or snow.", "bis": "Dili tanan nga desyerto kay init; adunay bugnaw nga mga desyerto sama sa Antarctica, nga uga tungod kay gamay ra kaayo ang ulan o niyebe didto."}, "source": "encyclopedia-stable consensus (deserts defined by dryness, not heat)", "generator": "claude-workflow", "reviewed": false},
  {"id": "how-islands-form-g6", "domain": "EARTH_SPACE", "topic": "how islands form", "grades": [6, 7], "terms": ["isla", "pulo", "paano nabubuo ang isla", "bulkan", "ilalim ng dagat", "umaangat", "unsaon pagporma sa isla", "gikan sa bulkan", "ilalom sa dagat", "mitungha", "island", "volcano", "undersea", "rise above sea"], "fact": {"tl": "Maraming isla ang nabubuo kapag tumataas ang mga bulkan mula sa ilalim ng dagat hanggang sumulpot ang tuktok nito sa ibabaw ng tubig.", "en": "Many islands form when volcanoes rise from the ocean floor until their tops poke above the water.", "bis": "Daghang isla ang naporma kung ang mga bulkan motungha gikan sa salog sa dagat hangtod ang ila nga tumoy mogawas sa ibabaw sa tubig."}, "source": "AAAS Benchmarks 4C/H5 (undersea volcanoes form islands)", "generator": "claude-workflow", "reviewed": false},
  {"id": "philippines-many-islands-g3", "domain": "EARTH_SPACE", "topic": "Philippine islands", "grades": [3, 4, 5], "terms": ["Pilipinas", "pulo", "isla", "arkipelago", "libo-libong isla", "Luzon", "Visayas", "Mindanao", "kapuluan", "liboan ka isla", "archipelago", "thousands of islands"], "fact": {"tl": "Ang Pilipinas ay isang arkipelago, ibig sabihin ito ay binubuo ng libu-libong isla na napapaligiran ng tubig.", "en": "The Philippines is an archipelago, meaning it is made up of thousands of islands surrounded by water.", "bis": "Ang Pilipinas usa ka arkipelago, nagpasabot nga kini gilangkoban sa liboan ka isla nga gipalibutan sa tubig."}, "source": "encyclopedia-stable consensus (Philippines ~7,641 islands)", "generator": "claude-workflow", "reviewed": false},
  {"id": "what-is-soil-g3", "domain": "EARTH_SPACE", "topic": "what soil is made of", "grades": [3, 4, 5], "terms": ["lupa", "soil", "durog na bato", "bulok na halaman", "mga buhay na bagay", "yuta", "dugmok nga bato", "gabok nga tanom", "pagkagama sa yuta", "weathered rock", "plant remains", "living things"], "fact": {"tl": "Ang lupa ay gawa sa pinong durog na bato na hinaluan ng mga bulok na halaman at maraming maliliit na buhay na bagay.", "en": "Soil is made of tiny bits of broken-down rock mixed with rotted plants and many small living things.", "bis": "Ang yuta hinimo gikan sa gagmay nga dugmok nga bato nga gisagol sa nadunot nga mga tanom ug daghang gagmay nga buhi nga mga butang."}, "source": "AAAS Benchmarks 4C/E2 (soil from weathered rock + plant remains + organisms)", "generator": "claude-workflow", "reviewed": false},
  {"id": "soil-layers-horizons-g6", "domain": "EARTH_SPACE", "topic": "soil layers", "grades": [6, 7], "terms": ["lupa", "mga patong ng lupa", "topsoil", "ibabaw na lupa", "subsoil", "bedrock", "bato sa ilalim", "sapaw sa yuta", "ibabaw nga yuta", "lawom nga yuta", "soil layers", "topsoil", "subsoil"], "fact": {"tl": "Ang lupa ay may mga patong: ang madilim na ibabaw (topsoil) na mayaman sa sustansya, ang subsoil sa ilalim, at ang matibay na bedrock sa pinakailalim.", "en": "Soil has layers: the dark, nutrient-rich topsoil on top, the subsoil below it, and solid bedrock at the bottom.", "bis": "Ang yuta adunay mga sapaw: ang itom nga ibabaw nga yuta (topsoil) nga dato sa sustansya, ang subsoil sa ilalom, ug ang gahi nga bedrock sa kinaubsan."}, "source": "encyclopedia-stable consensus (soil horizons)", "generator": "claude-workflow", "reviewed": false},
  {"id": "topsoil-takes-long-to-form-g6", "domain": "EARTH_SPACE", "topic": "soil forms slowly", "grades": [6, 7, 8], "terms": ["topsoil", "ibabaw na lupa", "matagal bago mabuo", "daan-daang taon", "sustansya", "ibabaw nga yuta", "dugay maporma", "gatusan ka tuig", "slow to form", "hundreds of years"], "fact": {"tl": "Napakatagal bago mabuo ang lupa—maaaring umabot ng daan-daang taon para makagawa lang ng manipis na patong ng mayamang topsoil.", "en": "Soil forms very slowly—it can take hundreds of years just to build a thin layer of rich topsoil.", "bis": "Hinay kaayo ang pagporma sa yuta—mahimong moabot og gatusan ka tuig aron makahimo lang og nipis nga sapaw sa dato nga topsoil."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sand-silt-clay-g6", "domain": "EARTH_SPACE", "topic": "soil types by particle size", "grades": [6, 7], "terms": ["buhangin", "sand", "silt", "luwad", "clay", "laki ng butil", "uri ng lupa", "balas", "yutang kulonon", "gidak-on sa partikulo", "klase sa yuta", "particle size", "loam"], "fact": {"tl": "Ang uri ng lupa ay nakabatay sa laki ng butil nito: ang buhangin ay malalaki at magaspang, ang silt ay mas pino, at ang luwad (clay) ay pinakamaliit at malagkit.", "en": "Soil types depend on particle size: sand has large, gritty grains, silt is finer, and clay has the tiniest, stickiest particles.", "bis": "Ang klase sa yuta nag-agad sa gidak-on sa partikulo niini: ang balas dako ug magaspang, ang silt mas pino, ug ang yutang kulonon (clay) mao ang pinakagamay ug pinaka-pilit."}, "source": "encyclopedia-stable consensus (soil texture classes)", "generator": "claude-workflow", "reviewed": false},
  {"id": "what-is-weathering-g5", "domain": "EARTH_SPACE", "topic": "weathering", "grades": [5, 6], "terms": ["weathering", "pagdurog ng bato", "nagkakawatak-watak", "init", "lamig", "tubig", "pagkagabok sa bato", "pagkadugmok", "init ug bugnaw", "breaking rock", "heat", "cold"], "fact": {"tl": "Ang weathering ay ang unti-unting pagdurog ng malalaking bato tungo sa mas maliliit na piraso dahil sa init, lamig, tubig, at hangin.", "en": "Weathering is the slow breaking of large rocks into smaller pieces by heat, cold, water, and wind.", "bis": "Ang weathering mao ang hinay nga pagkadugmok sa dagkong bato ngadto sa gagmay nga piraso tungod sa init, bugnaw, tubig, ug hangin."}, "source": "AAAS Benchmarks 4C/E2 (weathering breaks rock)", "generator": "claude-workflow", "reviewed": false},
  {"id": "plant-roots-break-rock-g6", "domain": "EARTH_SPACE", "topic": "biological weathering", "grades": [6, 7], "terms": ["ugat", "plant roots", "bumabasag ng bato", "tumutubo sa lamat", "pagputok ng bato", "gamot", "gamot sa tanom", "mobuak sa bato", "motubo sa liki", "roots crack rock", "crack", "grow"], "fact": {"tl": "Kahit ang mga ugat ng halaman ay nakakabasag ng bato—tumutubo ang mga ito sa mga lamat hanggang lumaki at maputok ang bato.", "en": "Even plant roots can break rock—they grow into cracks and slowly widen them until the rock splits apart.", "bis": "Bisan ang gamot sa tanom makabuak sa bato—motubo kini sa mga liki ug hinay-hinay nga magpadako niini hangtod mabuak ang bato."}, "source": "AAAS Benchmarks 4C/M6 (roots influence soil/rock); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "freeze-thaw-weathering-g7", "domain": "EARTH_SPACE", "topic": "freeze-thaw weathering", "grades": [7, 8], "terms": ["tubig sa lamat", "nagyeyelo", "lumalaki ang yelo", "bumabasag", "freeze", "ice wedge", "tubig sa liki", "mogahi nga yelo", "modako", "nagbuak", "ice", "expand", "crack"], "fact": {"tl": "Kapag pumasok ang tubig sa lamat ng bato at nagyelo, lumalaki ito at unti-unting binabasag ang bato—tinatawag itong freeze-thaw weathering.", "en": "When water seeps into a rock crack and freezes, it expands and slowly splits the rock apart, a process called freeze-thaw weathering.", "bis": "Kung ang tubig mosulod sa liki sa bato ug mogahi nga yelo, modako kini ug hinay-hinay nga mobuak sa bato, gitawag kini nga freeze-thaw weathering."}, "source": "encyclopedia-stable consensus (physical weathering)", "generator": "claude-workflow", "reviewed": false},
  {"id": "what-is-erosion-g5", "domain": "EARTH_SPACE", "topic": "erosion", "grades": [5, 6], "terms": ["erosion", "pagguho", "pagtangay ng lupa", "dinadala ng tubig", "hangin", "yelo", "banlas", "pagkahurot sa yuta", "gidala sa tubig", "carries away", "water", "wind", "wear away"], "fact": {"tl": "Ang erosion ay ang pagtangay ng tubig, hangin, o yelo sa lupa at durog na bato papunta sa ibang lugar.", "en": "Erosion is the carrying away of soil and broken rock by water, wind, or ice to another place.", "bis": "Ang erosion mao ang pagdala sa tubig, hangin, o yelo sa yuta ug dugmok nga bato ngadto sa laing dapit."}, "source": "AAAS Benchmarks 4C/M2b (rivers and ice carry off soil)", "generator": "claude-workflow", "reviewed": false},
  {"id": "weathering-vs-erosion-g6", "domain": "EARTH_SPACE", "topic": "weathering vs erosion", "grades": [6, 7], "terms": ["weathering", "erosion", "pagkakaiba", "pagdurog vs pagtangay", "kaibhan", "pagdugmok vs pagdala", "difference", "break vs carry", "break down", "move"], "fact": {"tl": "Magkaiba ang weathering at erosion: ang weathering ang dumudurog sa bato, habang ang erosion ang nagdadala ng durog na bato palayo.", "en": "Weathering and erosion are different: weathering breaks rock into pieces, while erosion carries those pieces away.", "bis": "Lahi ang weathering ug erosion: ang weathering mao ang modugmok sa bato, samtang ang erosion mao ang modala sa dugmok nga bato palayo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rivers-carve-canyons-g6", "domain": "EARTH_SPACE", "topic": "rivers shape land", "grades": [6, 7], "terms": ["ilog", "river", "kanyon", "canyon", "inuukit ng tubig", "malalim na lambak", "suba", "gikalot sa tubig", "lawom nga walog", "carve", "deep valley"], "fact": {"tl": "Sa milyon-milyong taon, ang umaagos na ilog ay maaaring umukit ng malalalim na kanyon sa bato, tulad ng mga ilog sa kabundukan.", "en": "Over millions of years, a flowing river can carve deep canyons into rock, like rivers cutting through mountains.", "bis": "Sa minilyon ka tuig, ang nagdagayday nga suba mahimong mokalot og lawom nga kanyon sa bato, sama sa mga suba nga moagi sa kabukiran."}, "source": "AAAS Benchmarks 4C/M2b (rivers break down rock and carve land)", "generator": "claude-workflow", "reviewed": false},
  {"id": "deposition-builds-deltas-g7", "domain": "EARTH_SPACE", "topic": "deposition and deltas", "grades": [7, 8], "terms": ["delta", "deposition", "pagpapatong ng putik", "bunganga ng ilog", "ipinapatong", "matabang lupa", "pag-ipon sa lapok", "baba sa suba", "gipundo", "drop", "sediment", "river mouth"], "fact": {"tl": "Kapag bumagal ang ilog sa bunganga nito sa dagat, ibinababa nito ang dalang putik at buhangin, at unti-unting nabubuo ang isang delta.", "en": "When a river slows down at its mouth near the sea, it drops the mud and sand it carried, slowly building a delta.", "bis": "Kung mohinay ang suba sa baba niini duol sa dagat, ipundo niini ang dala nga lapok ug balas, ug hinay-hinay nga maporma ang usa ka delta."}, "source": "AAAS Benchmarks 4C/M2b (depositing material in sediments)", "generator": "claude-workflow", "reviewed": false},
  {"id": "soil-erosion-loss-g6", "domain": "EARTH_SPACE", "topic": "soil erosion threat", "grades": [6, 7, 8], "terms": ["pagguho ng lupa", "soil erosion", "nawawalang lupa", "pagtatanim", "kalbong bundok", "banlas sa yuta", "nawala nga yuta", "pagputol sa kahoy", "topsoil", "losing soil", "deforestation", "bare land"], "fact": {"tl": "Kapag nawawala ang mga puno at halaman, mas madaling tangayin ng ulan ang mayamang topsoil, kaya nahihirapang tumubo ang mga pananim.", "en": "When trees and plants are removed, rain washes away the rich topsoil more easily, making it hard for crops to grow.", "bis": "Kung mawala ang mga kahoy ug tanom, mas sayon nga banlasan sa ulan ang dato nga topsoil, mao nga maglisod og tubo ang mga tanom."}, "source": "AAAS Benchmarks 4C/M6, 4C/M7 (plants protect soil; human activity changes land)", "generator": "claude-workflow", "reviewed": false},
  {"id": "plants-hold-soil-g5", "domain": "EARTH_SPACE", "topic": "plants protect soil", "grades": [5, 6], "terms": ["ugat", "halaman", "pumipigil sa pagguho", "hawak ang lupa", "puno", "gamot", "tanom", "mokupot sa yuta", "gapugong sa banlas", "roots hold soil", "prevent erosion", "trees"], "fact": {"tl": "Ang mga ugat ng halaman ay humahawak sa lupa nang mahigpit, kaya nakakatulong ang mga puno na pigilan ang pagguho ng lupa.", "en": "Plant roots hold the soil tightly in place, so trees help stop the soil from washing or blowing away.", "bis": "Ang gamot sa tanom mokupot pag-ayo sa yuta, mao nga ang mga kahoy makatabang sa pagpugong sa banlas sa yuta."}, "source": "AAAS Benchmarks 4C/M6 (roots and organisms resist erosion)", "generator": "claude-workflow", "reviewed": false},
  {"id": "earthworms-help-soil-g4", "domain": "LIVING_THINGS", "topic": "earthworms enrich soil", "grades": [4, 5, 6], "terms": ["bulate sa lupa", "earthworm", "naghuhukay", "nagpapaluwag ng lupa", "sustansya", "ulod", "wati", "nagkalot sa yuta", "nagpaluag sa yuta", "aerate", "loosen soil", "nutrients"], "fact": {"tl": "Ang mga bulate sa lupa ay naghuhukay ng mga daanan na nagpapaluwag ng lupa at nagpapayaman dito, kaya mas madaling tumubo ang halaman.", "en": "Earthworms dig tunnels that loosen the soil and make it richer, helping plants grow better.", "bis": "Ang mga wati nagkalot og agianan nga nagpaluag sa yuta ug nagpadato niini, mao nga mas sayon motubo ang tanom."}, "source": "AAAS Benchmarks 4C/M6 (worms influence soil fertility)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sand-dunes-form-g6", "domain": "EARTH_SPACE", "topic": "sand dunes", "grades": [6, 7], "terms": ["sand dune", "buntong buhangin", "tinatangay ng hangin", "disyerto", "tabing-dagat", "tipun-tipon nga balas", "gidala sa hangin", "desyerto", "baybayon", "wind", "piles of sand", "beach"], "fact": {"tl": "Ang mga buntong buhangin (sand dune) ay nabubuo kapag tinatangay at itinatambak ng hangin ang buhangin sa disyerto o sa tabing-dagat.", "en": "Sand dunes form when wind blows and piles up sand in deserts or along beaches.", "bis": "Ang mga sand dune maporma kung ang hangin modala ug motapok sa balas sa desyerto o sa baybayon."}, "source": "encyclopedia-stable consensus (aeolian deposition)", "generator": "claude-workflow", "reviewed": false},
  {"id": "glaciers-shape-land-g7", "domain": "EARTH_SPACE", "topic": "glaciers carve land", "grades": [7, 8], "terms": ["glacier", "yelo", "gumagalaw na yelo", "umuukit", "lambak", "nagagasgas", "nagalihok nga yelo", "mokalot", "walog", "moving ice", "carve", "scrape", "valley"], "fact": {"tl": "Ang glacier ay malaking masa ng yelo na dahan-dahang gumagalaw at umuukit ng malalawak na lambak habang dinadala nito ang bato.", "en": "A glacier is a huge mass of ice that slowly moves and carves out wide valleys as it drags rock along.", "bis": "Ang glacier usa ka dako nga tipun-tipon nga yelo nga hinay-hinay nga molihok ug mokalot og lapad nga walog samtang gidala niini ang bato."}, "source": "AAAS Benchmarks 4C/M2b (glacial ice carves and carries material)", "generator": "claude-workflow", "reviewed": false},
  {"id": "caves-have-no-light-g4", "domain": "EARTH_SPACE", "topic": "cave environment", "grades": [4, 5], "terms": ["kuweba", "yungib", "madilim", "walang liwanag", "paniki", "bulag na hayop", "langob", "ngitngit", "walay kahayag", "kabog", "cave", "dark", "no light", "bats"], "fact": {"tl": "Sa kailaliman ng kuweba ay walang liwanag mula sa araw, kaya ang mga hayop doon tulad ng paniki ay sanay mabuhay sa dilim.", "en": "Deep inside a cave there is no sunlight at all, so animals there like bats are used to living in total darkness.", "bis": "Sa kinahiladman sa langob walay kahayag gikan sa adlaw, mao nga ang mga hayop didto sama sa kabog naanad nga mabuhi sa kangitngit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "limestone-karst-philippines-g7", "domain": "EARTH_SPACE", "topic": "Philippine karst landforms", "grades": [7, 8], "terms": ["batong-apog", "limestone", "karst", "Chocolate Hills", "Bohol", "Palawan", "kuweba", "bungtod sa Bohol", "langob", "apog", "chocolate hills", "underground river"], "fact": {"tl": "Maraming kakaibang anyong lupa sa Pilipinas tulad ng Chocolate Hills sa Bohol at mga yungib sa Palawan ay nabuo dahil sa pagtunaw ng tubig sa batong-apog.", "en": "Many unusual Philippine landforms, like the Chocolate Hills in Bohol and the caves of Palawan, formed as water dissolved limestone rock.", "bis": "Daghang talagsaon nga anyo sa yuta sa Pilipinas, sama sa Chocolate Hills sa Bohol ug ang mga langob sa Palawan, naporma tungod sa pagtunaw sa tubig sa limestone nga bato."}, "source": "encyclopedia-stable consensus (Philippine karst geology)", "generator": "claude-workflow", "reviewed": false},
  {"id": "mountains-cold-at-top-g5", "domain": "EARTH_SPACE", "topic": "why mountaintops are cold", "grades": [5, 6], "terms": ["bundok", "tuktok", "malamig", "mataas", "manipis na hangin", "bukid", "tumoy", "bugnaw", "habog", "nipis nga hangin", "mountaintop", "cold", "high", "thin air"], "fact": {"tl": "Mas malamig ang tuktok ng mataas na bundok kaysa sa paanan nito dahil bumababa ang temperatura habang tumataas ka sa himpapawid.", "en": "The top of a tall mountain is colder than its base because the air gets colder the higher you go up.", "bis": "Mas bugnaw ang tumoy sa taas nga bukid kaysa sa tiilan niini tungod kay mas mobugnaw ang hangin samtang mosaka ka pataas."}, "source": "encyclopedia-stable consensus (temperature lapse rate)", "generator": "claude-workflow", "reviewed": false},
  {"id": "atmosphere-five-layers-g6", "domain": "EARTH_SPACE", "topic": "layers of the atmosphere", "grades": [6, 7, 8], "terms": ["atmosphere", "layers", "layer", "troposphere", "stratosphere", "mesosphere", "thermosphere", "exosphere", "mga sapaw", "sapin-sapin", "hugna", "baga nga hangin", "lima ka layer", "lima na bahagi"], "fact": {"tl": "Ang atmosphere ay nahahati sa limang pangunahing layer mula sa ibaba pataas: troposphere, stratosphere, mesosphere, thermosphere, at exosphere. Habang umaakyat, lalong nanipis ang hangin.", "en": "The atmosphere is divided into five main layers from the bottom up: the troposphere, stratosphere, mesosphere, thermosphere, and exosphere. The higher you go, the thinner the air becomes.", "bis": "Ang atmosphere nabahin sa lima ka nag-unang layer gikan sa ubos paingon sa taas: troposphere, stratosphere, mesosphere, thermosphere, ug exosphere. Samtang mosaka, mas manipis ang hangin."}, "source": "NRC ESS2.D; AAAS BSL Ch.4B", "generator": "claude-workflow", "reviewed": false},
  {"id": "troposphere-weather-layer-g6", "domain": "EARTH_SPACE", "topic": "the troposphere is where weather happens", "grades": [5, 6, 7], "terms": ["troposphere", "weather layer", "panahon", "ulan", "ulap", "clouds", "pinakamababang", "kinaubsang", "tubo kang panahon", "dinhi mahitabo ang panahon", "hininga", "ginhuwa", "pinakamalapit sa lupa"], "fact": {"tl": "Ang troposphere ang pinakamababang layer ng atmosphere kung saan tayo nakatira at humihinga, at dito nangyayari halos lahat ng panahon — ang ulan, ulap, at hangin.", "en": "The troposphere is the lowest layer of the atmosphere, where we live and breathe, and it is where nearly all weather happens — the rain, clouds, and wind.", "bis": "Ang troposphere mao ang kinaubsang layer sa atmosphere diin kita nagpuyo ug nagginhawa, ug dinhi mahitabo halos tanang panahon — ang ulan, panganod, ug hangin."}, "source": "NRC ESS2.D; AAAS BSL Ch.4B", "generator": "claude-workflow", "reviewed": false},
  {"id": "stratosphere-ozone-planes-g7", "domain": "EARTH_SPACE", "topic": "the stratosphere holds the ozone layer", "grades": [6, 7, 8], "terms": ["stratosphere", "ozone layer", "eroplano", "ayroplano", "airplane", "jet", "lumilipad", "manglupad", "matahum", "kalmado", "walang ulap", "ibabaw sa troposphere", "ozone naa diri"], "fact": {"tl": "Ang stratosphere ay nasa itaas ng troposphere at dito matatagpuan ang ozone layer; kalmado ang hangin dito kaya dito lumilipad ang mga jet na eroplano.", "en": "The stratosphere lies above the troposphere and contains the ozone layer; the air there is calm, which is why jet airplanes fly in it.", "bis": "Ang stratosphere anaa sa ibabaw sa troposphere ug dinhi makita ang ozone layer; kalmado ang hangin dinhi maong dinhi manglupad ang mga jet nga ayroplano."}, "source": "NRC ESS2.D; ESS3.C; AAAS BSL Ch.4B", "generator": "claude-workflow", "reviewed": false},
  {"id": "mesosphere-burns-meteors-g7", "domain": "EARTH_SPACE", "topic": "the mesosphere burns up meteors", "grades": [6, 7, 8], "terms": ["mesosphere", "meteor", "shooting star", "bulalakaw", "nasusunog", "masunog", "pinakamalamig", "kinabugnaw", "bato gikan sa kawanangan", "third layer", "ikatlong layer", "nagsusunog ng bato"], "fact": {"tl": "Ang mesosphere ang ikatlong layer at ang pinakamalamig na bahagi ng atmosphere; dito nasusunog ang karamihan ng meteor o bulalakaw bago pa sila tumama sa lupa.", "en": "The mesosphere is the third layer and the coldest part of the atmosphere; this is where most meteors (shooting stars) burn up before they can reach the ground.", "bis": "Ang mesosphere mao ang ikatlong layer ug ang kinabugnaw nga bahin sa atmosphere; dinhi masunog ang kadaghanan sa mga meteor o bulalakaw sa dili pa sila makaabot sa yuta."}, "source": "NRC ESS2.D; AAAS BSL Ch.4A/4B", "generator": "claude-workflow", "reviewed": false},
  {"id": "thermosphere-space-edge-g8", "domain": "EARTH_SPACE", "topic": "the thermosphere and the edge of space", "grades": [7, 8, 9], "terms": ["thermosphere", "exosphere", "aurora", "ISS", "space station", "istasyon sa kawanangan", "sangko", "init kaayo", "napakainit", "gilid ng kalawakan", "ngilit sa kawanangan", "satellite"], "fact": {"tl": "Sa itaas ng mesosphere ay ang thermosphere, na napakainit pero napakanipis ng hangin; dito umiikot ang International Space Station at nabubuo ang aurora, at sa exosphere na nasa labas nito unti-unting nagiging kalawakan.", "en": "Above the mesosphere is the thermosphere, which is very hot but has extremely thin air; the International Space Station orbits here and auroras form here, and beyond it the exosphere slowly fades into space.", "bis": "Sa ibabaw sa mesosphere mao ang thermosphere, nga init kaayo apan nipis kaayo ang hangin; dinhi molibot ang International Space Station ug maporma ang aurora, ug sa exosphere nga anaa sa gawas niini hinay-hinay nga mahimong kawanangan."}, "source": "NRC ESS2.D; ESS1.B; AAAS BSL Ch.4B", "generator": "claude-workflow", "reviewed": false},
  {"id": "air-thinner-with-altitude-g6", "domain": "EARTH_SPACE", "topic": "air gets thinner higher up", "grades": [5, 6, 7], "terms": ["thin air", "nanipis na hangin", "manipis nga hangin", "altitude", "bundok", "bukid", "mountain", "mahirap huminga", "lisod moginhawa", "mas mataas", "mas habog", "konti ang oxygen", "gamay nga oxygen", "mountaineer"], "fact": {"tl": "Habang umaakyat ka sa mas mataas na lugar, nanipis ang hangin at kumakaunti ang oxygen, kaya nahihirapan huminga ang mga umaakyat sa napakataas na bundok.", "en": "As you climb to higher places, the air gets thinner and has less oxygen, which is why climbers feel out of breath on very tall mountains.", "bis": "Samtang mosaka ka sa mas habog nga dapit, manipis ang hangin ug mokunhod ang oxygen, mao nga maglisod sa pagginhawa ang mga mosaka sa habog kaayo nga bukid."}, "source": "AAAS BSL Ch.4B; NRC ESS2.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "higher-is-colder-g5", "domain": "EARTH_SPACE", "topic": "why mountaintops are cold", "grades": [5, 6, 7], "terms": ["malamig sa bundok", "bugnaw sa bukid", "mountaintop cold", "tuktok ng bundok", "tumoy sa bukid", "mas mataas mas malamig", "Baguio", "niyebe", "ice", "snow", "temperatura bumababa", "mubu ang temperatura", "habog mas bugnaw"], "fact": {"tl": "Mas malamig sa tuktok ng matataas na bundok kaysa sa lupa dahil bumababa ang temperatura habang tumataas ang lugar — kaya malamig sa Baguio at may yelo sa tuktok ng pinakamatataas na bundok.", "en": "Mountaintops are colder than the lowlands because the temperature drops as you go higher — this is why Baguio is cool and the tallest peaks have ice on top.", "bis": "Mas bugnaw sa tumoy sa habog nga bukid kaysa sa patag tungod kay mokunhod ang temperatura samtang mosaka — mao nga bugnaw sa Baguio ug adunay yelo sa tumoy sa kinahabugang bukid."}, "source": "AAAS BSL Ch.4B; NRC ESS2.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "air-presses-all-directions-g6", "domain": "EARTH_SPACE", "topic": "air pressure pushes in all directions", "grades": [6, 7, 8], "terms": ["air pressure", "presyon ng hangin", "presyon sa hangin", "diin sa tanang direksyon", "idinidiin", "duot", "lahat ng direksyon", "hindi natin nararamdaman", "wala ta mabati", "balanse", "pantimbang", "kilo bawat metro"], "fact": {"tl": "Ang air pressure ay idinidiin ng hangin sa lahat ng direksyon — pataas, pababa, at sa gilid — kaya hindi natin ito karaniwang nararamdaman bagama't may bigat ang hangin sa ibabaw natin.", "en": "Air pressure pushes in every direction — up, down, and sideways — which is why we usually don't feel it even though there is a heavy column of air above us.", "bis": "Ang air pressure moduot sa tanang direksyon — paingon sa taas, ubos, ug kilid — mao nga sagad dili nato kini mabati bisan adunay bug-at nga hangin sa ibabaw nato."}, "source": "AAAS BSL Ch.4D; NRC PS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "wind-high-to-low-pressure-g6", "domain": "EARTH_SPACE", "topic": "wind blows from high to low pressure", "grades": [6, 7, 8], "terms": ["wind", "hangin", "high pressure", "low pressure", "mataas na presyon", "mababang presyon", "taas nga presyon", "ubos nga presyon", "umiihip", "mohuyop", "gikan sa taas paingon sa ubos", "kalainan sa presyon"], "fact": {"tl": "Umiihip ang hangin mula sa lugar na may mataas na air pressure papunta sa lugar na may mababang air pressure; mas malaki ang pagkakaiba ng presyon, mas malakas ang hangin.", "en": "Wind blows from places of high air pressure toward places of low air pressure; the bigger the pressure difference, the stronger the wind.", "bis": "Mohuyop ang hangin gikan sa dapit nga adunay taas nga air pressure paingon sa dapit nga adunay ubos nga air pressure; kon mas dako ang kalainan sa presyon, mas kusog ang hangin."}, "source": "NRC ESS2.D; AAAS BSL Ch.4B", "generator": "claude-workflow", "reviewed": false},
  {"id": "low-pressure-brings-storms-g7", "domain": "EARTH_SPACE", "topic": "low pressure brings clouds and storms", "grades": [6, 7, 8], "terms": ["low pressure", "mababang presyon", "ubos nga presyon", "bagyo", "unos", "storm", "umuulan", "mag-ulan", "ulap", "panganod", "umaakyat ang hangin", "mosaka ang hangin", "masamang panahon", "ngil-ad nga panahon"], "fact": {"tl": "Sa lugar na may mababang air pressure, umaakyat ang hangin at lumalamig, kaya nabubuo ang ulap at madalas umuulan; ito ang dahilan kung bakit kaakibat ng bagyo ang napakababang presyon.", "en": "Where air pressure is low, air rises and cools, so clouds form and it often rains; this is why very low pressure goes hand in hand with storms.", "bis": "Sa dapit nga adunay ubos nga air pressure, mosaka ang hangin ug mobugnaw, mao nga maporma ang panganod ug sagad mag-ulan; mao kini ang hinungdan nga ang ubos kaayo nga presyon kauban sa bagyo."}, "source": "NRC ESS2.D; AAAS BSL Ch.4B", "generator": "claude-workflow", "reviewed": false},
  {"id": "thermometer-measures-temperature-g4", "domain": "EARTH_SPACE", "topic": "a thermometer measures temperature", "grades": [3, 4, 5], "terms": ["thermometer", "termometro", "panukat sa init", "panukat ng temperatura", "init", "kainit", "temperatura", "mainit", "malamig", "bugnaw", "sukat", "sukod", "Celsius", "degree"], "fact": {"tl": "Ang thermometer ay kasangkapan na ginagamit para sukatin ang temperatura — kung gaano kainit o kalamig ang hangin, tubig, o katawan.", "en": "A thermometer is a tool used to measure temperature — how hot or cold the air, water, or a body is.", "bis": "Ang thermometer usa ka galamiton nga gigamit aron sukdon ang temperatura — kon unsa ka init o ka bugnaw ang hangin, tubig, o lawas."}, "source": "AAAS BSL Ch.3; DepEd weather instruments", "generator": "claude-workflow", "reviewed": false},
  {"id": "barometer-measures-pressure-g6", "domain": "EARTH_SPACE", "topic": "a barometer measures air pressure", "grades": [5, 6, 7], "terms": ["barometer", "barometro", "panukat sa presyon", "air pressure", "presyon ng hangin", "panahon", "weather", "hula sa panahon", "nagbabago ang presyon", "bumababang presyon", "bagyo", "manghulagway sa panahon"], "fact": {"tl": "Ang barometer ay kasangkapan na sumusukat sa air pressure; kapag mabilis na bumababa ang basa ng barometer, palatandaan ito na maaaring may paparating na masamang panahon.", "en": "A barometer is a tool that measures air pressure; when the barometer reading drops quickly, it is a sign that bad weather may be coming.", "bis": "Ang barometer usa ka galamiton nga mosukod sa air pressure; kon paspas nga mokunhod ang basa sa barometer, timailhan kini nga tingali adunay umaabot nga ngil-ad nga panahon."}, "source": "AAAS BSL Ch.4B; DepEd weather instruments", "generator": "claude-workflow", "reviewed": false},
  {"id": "anemometer-measures-wind-speed-g5", "domain": "EARTH_SPACE", "topic": "an anemometer measures wind speed", "grades": [4, 5, 6], "terms": ["anemometer", "anemometro", "panukat sa hangin", "bilis ng hangin", "katulin sa hangin", "wind speed", "umiikot na tasa", "nagtuyok nga tasa", "cup", "spinning cups", "lakas ng hangin", "kusog sa hangin", "mga kopita"], "fact": {"tl": "Ang anemometer ay kasangkapan na sumusukat sa bilis ng hangin; karaniwan itong may tatlo o apat na maliliit na tasa na umiikot — mas mabilis ang ikot, mas malakas ang hangin.", "en": "An anemometer is a tool that measures wind speed; it usually has three or four little cups that spin — the faster they spin, the stronger the wind.", "bis": "Ang anemometer usa ka galamiton nga mosukod sa katulin sa hangin; sagad kini adunay tulo o upat ka gagmay nga tasa nga magtuyok — kon mas paspas magtuyok, mas kusog ang hangin."}, "source": "AAAS BSL Ch.4B; DepEd weather instruments", "generator": "claude-workflow", "reviewed": false},
  {"id": "wind-vane-shows-direction-g4", "domain": "EARTH_SPACE", "topic": "a wind vane shows wind direction", "grades": [4, 5, 6], "terms": ["wind vane", "weather vane", "veleta", "panturo sa hangin", "direksyon ng hangin", "direksyon sa hangin", "saan nanggagaling", "asa gikan", "arrow", "pana", "umiikot", "motuyok", "manok sa atop", "rooster"], "fact": {"tl": "Ang wind vane (o weather vane) ay kasangkapan na nagpapakita kung saang direksyon nanggagaling ang hangin; umiikot ito at ang dulo nito ay tumuturo sa pinanggagalingan ng hangin.", "en": "A wind vane (or weather vane) is a tool that shows which direction the wind is coming from; it turns so that its pointer faces into the wind.", "bis": "Ang wind vane (o weather vane) usa ka galamiton nga magpakita kon asa gikan ang hangin; motuyok kini ug ang tumoy niini moatubang sa gigikanan sa hangin."}, "source": "AAAS BSL Ch.4B; DepEd weather instruments", "generator": "claude-workflow", "reviewed": false},
  {"id": "rain-gauge-measures-rain-g4", "domain": "EARTH_SPACE", "topic": "a rain gauge measures rainfall", "grades": [4, 5, 6], "terms": ["rain gauge", "panukat sa ulan", "panukat ng ulan", "dami ng ulan", "gidaghanon sa ulan", "rainfall", "milimetro", "milliliter", "nakolektang ulan", "natipon nga ulan", "baso nga may sukod", "tubo", "container"], "fact": {"tl": "Ang rain gauge ay kasangkapan na sumusukat kung gaano karaming ulan ang bumagsak; ito ay isang lalagyan na may panukat na nagsasabi ng dami ng tubig-ulan sa milimetro.", "en": "A rain gauge is a tool that measures how much rain has fallen; it is a container with a scale that tells the amount of rainwater in millimeters.", "bis": "Ang rain gauge usa ka galamiton nga mosukod kon unsa ka daghan ang ulan nga nahulog; usa kini ka sudlanan nga adunay sukdanan nga magsulti sa gidaghanon sa tubig-ulan sa milimetro."}, "source": "AAAS BSL Ch.4B; DepEd weather instruments", "generator": "claude-workflow", "reviewed": false},
  {"id": "hygrometer-measures-humidity-g6", "domain": "EARTH_SPACE", "topic": "a hygrometer measures humidity", "grades": [6, 7, 8], "terms": ["hygrometer", "higrometro", "panukat sa kaumog", "humidity", "halumigmig", "alimuot", "kahalumigmig", "singaw sa tubig sa hangin", "water vapor", "basa ang hangin", "umok nga hangin", "porsyento"], "fact": {"tl": "Ang hygrometer ay kasangkapan na sumusukat sa halumigmig — kung gaano karaming singaw ng tubig ang nasa hangin, na karaniwang ipinapakita bilang porsyento.", "en": "A hygrometer is a tool that measures humidity — how much water vapor is in the air, usually shown as a percentage.", "bis": "Ang hygrometer usa ka galamiton nga mosukod sa kahalumigmig — kon unsa ka daghan ang singaw sa tubig sa hangin, sagad gipakita isip porsyento."}, "source": "AAAS BSL Ch.4B; DepEd weather instruments", "generator": "claude-workflow", "reviewed": false},
  {"id": "clouds-need-dust-to-form-g6", "domain": "EARTH_SPACE", "topic": "clouds form around tiny dust particles", "grades": [6, 7, 8], "terms": ["cloud formation", "ulap", "panganod", "alikabok", "abog", "dust", "condensation nuclei", "kumakapit ang singaw", "mokapyot ang singaw", "tiny particle", "gagmay nga partikulo", "tubig sa hangin", "water vapor", "kumakapit"], "fact": {"tl": "Para mabuo ang ulap, kailangan ng napakaliliit na particle tulad ng alikabok o asin sa hangin; kumakapit dito ang singaw ng tubig at nagiging maliliit na patak na bumubuo ng ulap.", "en": "For a cloud to form, the air needs tiny particles like dust or salt; water vapor sticks to these and becomes the little droplets that make up a cloud.", "bis": "Aron maporma ang panganod, kinahanglan ang gagmay kaayo nga partikulo sama sa abog o asin sa hangin; mokapyot dinhi ang singaw sa tubig ug mahimong gagmay nga tulo nga maghimo sa panganod."}, "source": "NRC ESS2.C/2.D; AAAS BSL Ch.4B", "generator": "claude-workflow", "reviewed": false},
  {"id": "cloud-height-naming-g7", "domain": "EARTH_SPACE", "topic": "clouds are named by their height", "grades": [6, 7, 8], "terms": ["cloud names", "pangalan ng ulap", "ngalan sa panganod", "taas", "kahabog", "cirrus", "stratus", "cumulus", "alto", "mataas na ulap", "habog nga panganod", "mababang ulap", "ubos nga panganod", "antas"], "fact": {"tl": "Pinangangalanan ang mga ulap ayon sa taas at hugis nila: ang cirrus ay matataas at parang himulmol, ang cumulus ay parang bukol-bukol na bulak, at ang stratus ay pantay at nakakalat na parang kumot sa langit.", "en": "Clouds are named by their height and shape: cirrus are high and wispy, cumulus look like lumpy cotton, and stratus form flat sheets spread across the sky like a blanket.", "bis": "Ginganlan ang mga panganod sumala sa ilang kahabog ug porma: ang cirrus taas ug murag balhibo, ang cumulus murag bukol-bukol nga gapas, ug ang stratus patag ug nagkatag sa langit nga murag habol."}, "source": "AAAS BSL Ch.4B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cumulonimbus-thunderhead-g7", "domain": "EARTH_SPACE", "topic": "cumulonimbus is the thunderstorm cloud", "grades": [6, 7, 8], "terms": ["cumulonimbus", "thunderhead", "ulap ng kulog", "panganod sa dalugdog", "kidlat", "lightning", "kulog", "dalugdog", "makapal na ulap", "baga nga panganod", "mataas na ulap", "towering cloud", "bagyo", "unos", "matangkad na ulap"], "fact": {"tl": "Ang cumulonimbus ay napakataas at makapal na ulap na umaabot na parang tore sa langit; ito ang ulap na nagdadala ng malakas na ulan, kidlat, kulog, at minsan granizo.", "en": "A cumulonimbus is a very tall, thick cloud that towers up into the sky; it is the cloud that brings heavy rain, lightning, thunder, and sometimes hail.", "bis": "Ang cumulonimbus usa ka habog ug baga kaayo nga panganod nga moabot nga murag tore sa langit; mao kini ang panganod nga magdala og kusog nga ulan, kilat, dalugdog, ug usahay ulan-yelo."}, "source": "AAAS BSL Ch.4B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "clouds-white-vs-gray-g5", "domain": "EARTH_SPACE", "topic": "why clouds look white or gray", "grades": [5, 6, 7], "terms": ["white cloud", "puting ulap", "puti nga panganod", "gray cloud", "kulay-abong ulap", "abuhon nga panganod", "makapal", "baga", "liwanag", "kahayag", "nahaharangan", "na-block ang sidlak", "ulan paparating", "dark cloud", "madilim na ulap"], "fact": {"tl": "Puti ang ulap kapag pinapasok nito ang liwanag ng araw, pero nagiging kulay-abo o madilim ito kapag napakakapal na — dahil naharang na ng makapal na patak ng tubig ang liwanag, na palatandaan ng paparating na ulan.", "en": "A cloud looks white when sunlight passes through it, but it turns gray or dark when it grows very thick — because the dense water droplets block the light, a sign that rain may be coming.", "bis": "Puti ang panganod kon moagi niini ang kahayag sa adlaw, apan mahimong abuhon o ngitngit kon mograbe na kabaga — kay ang baga nga mga tulo sa tubig nakababag na sa kahayag, timailhan nga moabot na ang ulan."}, "source": "AAAS BSL Ch.4F; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fog-types-radiation-g7", "domain": "EARTH_SPACE", "topic": "fog forms when ground cools the air", "grades": [6, 7, 8], "terms": ["fog", "hamog", "gabon", "ambon nga gabon", "lumalamig ang lupa", "mobugnaw ang yuta", "gabi", "kagabhion", "umaga", "kabuntagon", "mababang ulap", "ground level cloud", "mahalumigmig", "umog", "valley fog", "bukid nga gabon"], "fact": {"tl": "Madalas mabuo ang hamog (fog) sa gabi at madaling-araw kapag lumalamig ang lupa at pati ang hangin sa ibabaw nito, kaya ang singaw ng tubig ay nagiging maliliit na patak malapit sa lupa.", "en": "Fog often forms at night and early morning when the ground cools and chills the air just above it, so the water vapor turns into tiny droplets close to the ground.", "bis": "Sagad maporma ang gabon panahon sa gabii ug kaadlawon kon mobugnaw ang yuta ug ang hangin ibabaw niini, mao nga ang singaw sa tubig mahimong gagmay nga tulo duol sa yuta."}, "source": "NRC ESS2.D; AAAS BSL Ch.4B", "generator": "claude-workflow", "reviewed": false},
  {"id": "dew-point-g7", "domain": "EARTH_SPACE", "topic": "the dew point", "grades": [7, 8, 9], "terms": ["dew point", "temperatura ng hamog", "punto sa yamog", "lumalamig ang hangin", "mobugnaw ang hangin", "puno na ng singaw", "puno na sa singaw", "saturated", "nagsisimulang mabuo ang hamog", "magsugod ang yamog", "condensation", "kondensasyon"], "fact": {"tl": "Ang dew point ay ang temperatura kung saan napakalamig na ng hangin para hawakan pa ang lahat ng singaw nito, kaya nagsisimula na itong maging hamog o ulap; mas mataas ang dew point, mas mahalumigmig ang panahon.", "en": "The dew point is the temperature at which air becomes too cold to hold all its water vapor, so it starts turning into dew or clouds; the higher the dew point, the more humid it feels.", "bis": "Ang dew point mao ang temperatura diin bugnaw na kaayo ang hangin aron mahuptan pa ang tanang singaw niini, mao nga magsugod na kini nga mahimong yamog o panganod; kon mas taas ang dew point, mas humid ang gibati."}, "source": "AAAS BSL Ch.4B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "frost-vs-dew-g6", "domain": "EARTH_SPACE", "topic": "frost forms below freezing without melting", "grades": [6, 7, 8], "terms": ["frost", "yelong nakadikit", "tun-og nga yelo", "namuong yelo", "ice crystal", "kristal ng yelo", "below zero", "ubos sa zero", "sobrang lamig", "bugnaw kaayo", "hindi muna naging hamog", "direktang yelo", "white frost", "puting yelo", "dahon"], "fact": {"tl": "Nabubuo ang frost kapag napakalamig na ng ibabaw (sa ibaba ng 0°C) kaya ang singaw ng tubig ay direktang nagiging maliliit na kristal ng yelo sa dahon o damo — hindi muna ito dumadaan bilang patak ng hamog.", "en": "Frost forms when a surface gets cold enough (below 0°C) that water vapor turns straight into tiny ice crystals on leaves or grass — it does not first become liquid dew.", "bis": "Maporma ang frost kon bugnaw na kaayo ang patong (ubos sa 0°C) maong ang singaw sa tubig diretso nga mahimong gagmay nga kristal sa yelo sa dahon o sagbot — dili una kini mahimong tulo sa yamog."}, "source": "AAAS BSL Ch.4B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "trade-winds-g8", "domain": "EARTH_SPACE", "topic": "trade winds blow steadily near the equator", "grades": [7, 8, 9], "terms": ["trade winds", "palagiang hangin", "kanunay nga hangin", "equator", "ekwador", "tropiko", "tropics", "umiihip patuwid", "kanunay ihip", "sailing ships", "barkong layag", "sulog sa hangin", "steady wind", "silangan", "sidlakan"], "fact": {"tl": "Ang trade winds ay mga palagiang hangin na umiihip malapit sa ekwador mula silangan papuntang kanluran; noong unang panahon, ginagamit ito ng mga barkong de-layag para tumawid sa karagatan.", "en": "The trade winds are steady winds that blow near the equator from east to west; long ago, sailing ships relied on them to cross the oceans.", "bis": "Ang trade winds mao ang kanunay nga hangin nga mohuyop duol sa ekwador gikan sa sidlakan paingon sa kasadpan; kaniadto, gigamit kini sa mga barko nga layag aron motabok sa kadagatan."}, "source": "AAAS BSL Ch.4B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "jet-stream-g8", "domain": "EARTH_SPACE", "topic": "the jet stream is a fast high wind", "grades": [7, 8, 9], "terms": ["jet stream", "mabilis na hangin sa itaas", "paspas nga hangin sa taas", "high altitude wind", "ilalim ng eroplano", "ubos sa ayroplano", "river of wind", "ilog ng hangin", "sapa sa hangin", "weather", "panahon", "kanluran pasilangan", "steers storms"], "fact": {"tl": "Ang jet stream ay napakabilis na agos ng hangin na umiihip sa napakataas na bahagi ng atmosphere; ginagabayan nito ang galaw ng mga sistema ng panahon at nakakatulong pabilisin ang mga eroplanong tumutugma sa daloy nito.", "en": "The jet stream is a very fast ribbon of wind that blows high up in the atmosphere; it steers weather systems along and can speed up airplanes flying with it.", "bis": "Ang jet stream usa ka paspas kaayo nga agos sa hangin nga mohuyop sa habog kaayo nga bahin sa atmosphere; mogiya kini sa paglihok sa mga sistema sa panahon ug makapaspas sa mga ayroplano nga mosakay niini."}, "source": "AAAS BSL Ch.4B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-ears-pop-altitude-pressure-g6", "domain": "EARTH_SPACE", "topic": "air pressure changes when you go up fast", "grades": [6, 7, 8], "terms": ["air pressure change", "pagbabago ng presyon", "kausaban sa presyon", "umaakyat", "mosaka", "bundok", "bukid", "eroplano", "ayroplano", "mas mababang presyon", "ubos nga presyon", "hangin nananipis", "manipis ang hangin", "altitude"], "fact": {"tl": "Kapag mabilis kang umaakyat sa mataas na lugar o eroplano, bumababa ang air pressure sa paligid mo dahil nanipis ang hangin — kaya nararamdaman mo ang pagbabago, halimbawa kapag pumuputok ang tenga mo.", "en": "When you go up quickly in a plane or up a mountain, the air pressure around you drops because the air is thinner — which is why you can feel the change, like your ears popping.", "bis": "Kon paspas ka nga mosaka sa habog nga dapit o sa ayroplano, mokunhod ang air pressure sa imong palibot kay nipis ang hangin — mao nga mabati nimo ang kausaban, sama sa pagbutok sa imong dalunggan."}, "source": "AAAS BSL Ch.4D; NRC PS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "warm-air-holds-more-vapor-g7", "domain": "EARTH_SPACE", "topic": "warm air holds more water vapor", "grades": [6, 7, 8], "terms": ["warm air", "mainit na hangin", "init nga hangin", "water vapor", "singaw ng tubig", "singaw sa tubig", "more moisture", "mas daghang umog", "mahalumigmig", "humid", "alimuot", "alindanaw", "lumalamig nagbubuo ng patak", "mobugnaw maghimog tulo", "sticky"], "fact": {"tl": "Mas maraming singaw ng tubig ang kayang hawakan ng mainit na hangin kaysa sa malamig na hangin; kaya kapag lumalamig ang mainit at mahalumigmig na hangin, sumosobra ang singaw at nagiging patak — ulap, hamog, o ulan.", "en": "Warm air can hold more water vapor than cold air; so when warm, moist air cools, the extra vapor turns into droplets — making clouds, dew, or rain.", "bis": "Mas daghang singaw sa tubig ang mahuptan sa init nga hangin kaysa sa bugnaw nga hangin; mao nga kon mobugnaw ang init ug humid nga hangin, ang sobra nga singaw mahimong tulo — maghimog panganod, yamog, o ulan."}, "source": "AAAS BSL Ch.4B; NRC ESS2.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "atmosphere-holds-heat-night-g6", "domain": "EARTH_SPACE", "topic": "the atmosphere keeps nights from getting too cold", "grades": [6, 7, 8], "terms": ["atmosphere keeps warm", "init sa gabi", "panghupot sa init", "hininga ng init", "blanket", "kumot", "habol", "walang atmosphere", "walay atmosphere", "Buwan", "Moon", "sobrang lamig ng gabi", "grabe kabugnaw sa gabii", "balanseng init"], "fact": {"tl": "Hinahawakan ng atmosphere ang bahagi ng init sa gabi tulad ng kumot, kaya hindi sobrang lumalamig ang gabi; sa Buwan na walang atmosphere, sobrang init kapag araw at sobrang lamig kapag gabi.", "en": "The atmosphere holds in some heat at night like a blanket, so nights don't get extremely cold; on the Moon, which has no atmosphere, it is scorching by day and freezing at night.", "bis": "Ang atmosphere mohupot sa pipila ka init sa gabii sama sa habol, mao nga dili sobra kabugnaw ang gabii; sa Bulan nga walay atmosphere, init kaayo kon adlaw ug bugnaw kaayo kon gabii."}, "source": "NRC ESS2.D; AAAS BSL Ch.4B", "generator": "claude-workflow", "reviewed": false},
  {"id": "bacteria-good-and-bad-g5", "domain": "LIVING_THINGS", "topic": "helpful and harmful bacteria", "grades": [4, 5, 6], "terms": ["bacteria", "bakterya", "good bacteria", "mabuting bakterya", "maayong bacteria", "tiyan", "tinai", "gut", "yogurt", "nakakasakit", "makapasakit", "helpful", "harmful", "tumutulong", "motabang", "tunaw", "digest", "sakit"], "fact": {"tl": "Hindi lahat ng bacteria ay masama — marami sa kanila ang tumutulong. May mabuting bacteria sa ating bituka na tumutulong sa pagtunaw ng pagkain, at ginagamit ang iba para gumawa ng yogurt at keso. Iilan lang na uri ng bacteria ang nagdudulot ng sakit.", "en": "Not all bacteria are bad — many of them help us. Good bacteria in our gut help digest food, and others are used to make yogurt and cheese. Only some kinds of bacteria cause disease.", "bis": "Dili tanang bacteria daotan — daghan kanila motabang nato. Adunay maayong bacteria sa atong tinai nga motabang sa pagtunaw sa pagkaon, ug ang uban gigamit aron maghimo og yogurt ug keso. Pipila lang ka matang sa bacteria ang hinungdan sa sakit."}, "source": "AAAS BSL 6E/M3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bacteria-divide-multiply-g6", "domain": "LIVING_THINGS", "topic": "how bacteria multiply", "grades": [6, 7], "terms": ["bacteria", "bakterya", "dumadami", "modaghan", "naghahati", "mobahin", "split", "divide", "multiply", "mabilis", "paspas", "isang cell", "copy", "kopya", "oras", "mainit", "basa"], "fact": {"tl": "Dumarami ang bacteria sa pamamagitan ng paghahati ng kanilang sarili — ang isang cell ay nagiging dalawa, ang dalawa ay nagiging apat, at iba pa. Sa mainit at basang lugar, maaari silang dumami nang napakabilis sa loob lang ng ilang oras.", "en": "Bacteria multiply by splitting themselves in two — one cell becomes two, two become four, and so on. In warm, moist places they can multiply very fast in just a few hours.", "bis": "Modaghan ang bacteria pinaagi sa pagbahin sa ilang kaugalingon — ang usa ka cell mahimong duha, ang duha mahimong upat, ug uban pa. Sa init ug basa nga dapit, makadaghan sila pag-ayo sulod lang sa pipila ka oras."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "antibodies-immune-memory-g7", "domain": "LIVING_THINGS", "topic": "antibodies and immune memory", "grades": [6, 7, 8], "terms": ["antibody", "antibodies", "white blood cells", "puting selula", "immune memory", "alaala ng katawan", "memorya", "tatak", "mark", "sundalo", "germ", "mikrobyo", "muling", "balik", "mabilis na laban", "mas paspas", "subli"], "fact": {"tl": "Kapag pumasok ang isang germ, gumagawa ang ilang white blood cells ng antibodies — maliliit na sandata na kumakapit sa germ para masugpo ito. Naaalala ng katawan ang germ na iyon, kaya kung babalik ito, mas mabilis itong malalabanan.", "en": "When a germ enters, some white blood cells make antibodies — tiny weapons that latch onto the germ to destroy it. The body remembers that germ, so if it returns it can be fought off much faster.", "bis": "Kung mosulod ang usa ka germ, ang pipila ka white blood cells maghimo og antibodies — gagmayng hinagiban nga mokupot sa germ aron laglagon kini. Mahinumdom ang lawas niadtong germ, busa kung mobalik kini, mas paspas kining masukol."}, "source": "AAAS BSL 6E/M4", "generator": "claude-workflow", "reviewed": false},
  {"id": "vaccines-how-they-work-g6", "domain": "LIVING_THINGS", "topic": "how vaccines work", "grades": [5, 6, 7, 8], "terms": ["vaccine", "bakuna", "turok", "injection", "immunity", "proteksyon", "panalipod", "sanayan", "practice", "patay", "mahina", "weak", "germ", "antibodies", "hindi magkakasakit", "dili magsakit", "ensayo", "handa"], "fact": {"tl": "Ang bakuna (vaccine) ay nagtuturo sa katawan na labanan ang isang sakit bago pa ito dumating. Naglalaman ito ng patay o mahinang bahagi ng germ na hindi magpapasakit, pero sapat para gumawa ang katawan ng antibodies — parang ensayo para handa ang depensa.", "en": "A vaccine teaches the body to fight a disease before it ever arrives. It contains a dead or weakened part of a germ that cannot make you sick, but is enough for the body to build antibodies — like a practice run so the defenses are ready.", "bis": "Ang bakuna (vaccine) magtudlo sa lawas sa pagpakigbatok sa usa ka sakit sa dili pa kini moabot. Adunay patay o huyang nga bahin sa germ nga dili makapasakit, apan igo aron ang lawas maghimo og antibodies — sama sa ensayo aron andam ang depensa."}, "source": "AAAS BSL 6E/M7", "generator": "claude-workflow", "reviewed": false},
  {"id": "jenner-first-vaccine-g7", "domain": "LIVING_THINGS", "topic": "Edward Jenner and the first vaccine", "grades": [6, 7, 8], "terms": ["Edward Jenner", "vaccine", "bakuna", "smallpox", "bulutong", "cowpox", "doktor", "doctor", "1796", "unang bakuna", "una nga bakuna", "first vaccine", "gatasan", "baka", "cow", "imbento"], "fact": {"tl": "Si Edward Jenner, isang Ingles na doktor, ang gumawa ng unang vaccine noong 1796 laban sa bulutong (smallpox). Napansin niyang ang mga gatasan ng baka na nagkaroon ng banayad na cowpox ay hindi na nagkakasakit ng bulutong, kaya ginamit niya ito para protektahan ang mga tao.", "en": "Edward Jenner, an English doctor, made the first vaccine in 1796 against smallpox. He noticed that milkmaids who had caught mild cowpox did not get smallpox, so he used this to protect people.", "bis": "Si Edward Jenner, usa ka Ingles nga doktor, maoy naghimo sa unang vaccine niadtong 1796 batok sa bulutong (smallpox). Namatikdan niya nga ang mga taggatas sa baka nga nataptan og hinay nga cowpox dili na magsakit og bulutong, busa gigamit niya kini aron panalipdan ang mga tawo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pasteur-germ-theory-g7", "domain": "LIVING_THINGS", "topic": "Louis Pasteur and germ theory", "grades": [6, 7, 8], "terms": ["Louis Pasteur", "germ theory", "mikrobyo", "germs", "pasteurization", "gatas", "milk", "init", "painit", "heat", "sakit", "French", "Pranses", "siyentipiko", "scientist", "bacteria", "patunay"], "fact": {"tl": "Si Louis Pasteur, isang Pranses na siyentipiko, ang nagpatunay na ang maliliit na germs ang sanhi ng maraming sakit at pagkabulok ng pagkain. Inimbento rin niya ang pasteurization — ang pag-init sa gatas para patayin ang mapanganib na bacteria.", "en": "Louis Pasteur, a French scientist, proved that tiny germs cause many diseases and the spoiling of food. He also invented pasteurization — heating milk to kill harmful bacteria.", "bis": "Si Louis Pasteur, usa ka Pranses nga siyentista, maoy nagpamatuod nga ang gagmayng germs maoy hinungdan sa daghang sakit ug sa pagkadunot sa pagkaon. Iya usab nga giimbento ang pasteurization — ang pag-init sa gatas aron patyon ang makadaot nga bacteria."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fleming-penicillin-g7", "domain": "LIVING_THINGS", "topic": "Alexander Fleming and penicillin", "grades": [6, 7, 8], "terms": ["Alexander Fleming", "penicillin", "antibiotic", "antibiotiko", "amag", "mold", "gamot", "medisina", "medicine", "bacteria", "1928", "nadiskubre", "nakaplagan", "accident", "aksidente", "unang antibiotic"], "fact": {"tl": "Natuklasan ni Alexander Fleming ang penicillin noong 1928 nang mapansin niyang may amag (mold) na pumatay sa bacteria sa kanyang laboratoryo. Ito ang naging unang antibiotic — isang gamot na lumalaban sa impeksyong dulot ng bacteria.", "en": "Alexander Fleming discovered penicillin in 1928 when he noticed a mold that killed bacteria in his laboratory. It became the first antibiotic — a medicine that fights infections caused by bacteria.", "bis": "Nadiskobrehan ni Alexander Fleming ang penicillin niadtong 1928 sa dihang namatikdan niya nga adunay agup-op (mold) nga mipatay sa bacteria sa iyang laboratoryo. Kini ang nahimong unang antibiotic — usa ka tambal nga makigbatok sa impeksiyon nga gikan sa bacteria."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "antibiotics-only-bacteria-g7", "domain": "LIVING_THINGS", "topic": "how antibiotics work", "grades": [6, 7, 8], "terms": ["antibiotic", "antibiotiko", "gamot sa bacteria", "bacteria", "bakterya", "virus", "sipon", "trangkaso", "flu", "hindi gumagana", "dili molihok", "doktor", "doctor", "reseta", "prescription", "ubusin", "humanon", "sobra", "resistance"], "fact": {"tl": "Ang antibiotics ay gamot na pumapatay o pumipigil sa bacteria, pero hindi ito gumagana laban sa virus tulad ng sipon o trangkaso. Mahalagang inumin lamang ito kapag inireseta ng doktor at ubusin ang buong gamot, dahil ang maling paggamit ay nagpapalakas sa bacteria laban dito.", "en": "Antibiotics are medicines that kill or stop bacteria, but they do not work against viruses like colds or flu. It is important to take them only when a doctor prescribes them and to finish the whole course, because misuse makes bacteria stronger against them.", "bis": "Ang antibiotics mga tambal nga mopatay o mopugong sa bacteria, apan dili kini molihok batok sa virus sama sa sip-on o trangkaso. Importante nga imnon lang kini kung gireseta sa doktor ug humanon ang tibuok tambal, kay ang sayop nga paggamit makapalig-on sa bacteria batok niini."}, "source": "encyclopedia-stable consensus; AAAS BSL 6E/M3", "generator": "claude-workflow", "reviewed": false},
  {"id": "disease-spread-droplets-g5", "domain": "LIVING_THINGS", "topic": "how germs spread through air", "grades": [4, 5, 6], "terms": ["kumakalat", "mokatap", "spread", "ubo", "cough", "bahin", "sneeze", "droplets", "laway", "luwa", "hangin", "air", "mikrobyo", "germs", "takip", "tabon", "cover", "mask", "sakit", "ilong", "baba"], "fact": {"tl": "Kapag umuubo o bumahin ang taong may sakit, kumakalat ang maliliit na patak (droplets) na may germs sa hangin, at maaaring malanghap ng iba. Kaya nakakatulong ang pagtakip ng bibig at ilong o pagsuot ng mask para hindi kumalat ang sakit.", "en": "When a sick person coughs or sneezes, tiny droplets carrying germs spread into the air and can be breathed in by others. That is why covering the mouth and nose or wearing a mask helps stop disease from spreading.", "bis": "Kung mag-ubo o magbahaon ang tawong may sakit, mokatap ang gagmayng tulo (droplets) nga may germs sa hangin, ug mahimong masuyop sa uban. Mao nga makatabang ang pagtabon sa baba ug ilong o pagsul-ob og mask aron dili mokatap ang sakit."}, "source": "AAAS BSL 6E/M3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "disease-spread-water-food-g5", "domain": "LIVING_THINGS", "topic": "germs spread through food and water", "grades": [4, 5, 6], "terms": ["kumakalat", "mokatap", "tubig", "water", "pagkain", "food", "maruming tubig", "hugaw nga tubig", "dirty water", "diarrhea", "pagtatae", "kalibanga", "bacteria", "mikrobyo", "luto", "luto-on", "cook", "linis", "hugas", "pakuluan"], "fact": {"tl": "Kumakalat din ang ilang germs sa pamamagitan ng maruming tubig o pagkaing may bacteria, na maaaring magdulot ng pagtatae. Ang pagpapakulo ng tubig, paghuhugas ng prutas, at maayos na pagluluto ng pagkain ay pumipigil dito.", "en": "Some germs also spread through dirty water or food that has bacteria, which can cause diarrhea. Boiling water, washing fruit, and cooking food properly help stop this.", "bis": "Ang ubang germs mokatap usab pinaagi sa hugaw nga tubig o pagkaon nga may bacteria, nga makahatag og kalibanga. Ang pagpabukal sa tubig, paghugas sa prutas, ug husto nga pagluto sa pagkaon makapugong niini."}, "source": "AAAS BSL 6E/M5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "diarrhea-dehydration-oresol-g4", "domain": "LIVING_THINGS", "topic": "diarrhea and dehydration", "grades": [3, 4, 5], "terms": ["pagtatae", "kalibanga", "diarrhea", "tubig", "water", "dehydration", "nauubusan ng tubig", "mauga", "oresol", "ORS", "asin", "sugar", "asukal", "kalibang", "inom", "mainom", "mahina", "sakit sa tiyan", "tinai"], "fact": {"tl": "Kapag nagtatae ang isang tao, nawawalan ang katawan ng maraming tubig at asin, na maaaring makapanghina. Mahalagang uminom ng maraming malinis na tubig o oresol (ORS) para mapalitan ang nawalang tubig.", "en": "When a person has diarrhea, the body loses a lot of water and salt, which can make them weak. It is important to drink plenty of clean water or oral rehydration solution (ORS) to replace what was lost.", "bis": "Kung magkalibang ang usa ka tawo, mawad-an ang lawas og daghang tubig ug asin, nga makapaluya. Importante nga moinom og daghang limpyo nga tubig o oresol (ORS) aron mapulihan ang nawala nga tubig."}, "source": "encyclopedia-stable consensus; DepEd health integration", "generator": "claude-workflow", "reviewed": false},
  {"id": "cold-vs-flu-g5", "domain": "LIVING_THINGS", "topic": "colds versus flu", "grades": [4, 5, 6], "terms": ["sipon", "cold", "colds", "trangkaso", "flu", "influenza", "virus", "ubo", "cough", "lagnat", "fever", "hilanat", "pananakit ng katawan", "sakit sa lawas", "mas malala", "mas grabe", "pahinga", "rest", "tubig", "magkaiba"], "fact": {"tl": "Parehong dulot ng virus ang sipon at trangkaso, pero mas malala ang trangkaso (flu) — kadalasang may mataas na lagnat at pananakit ng buong katawan. Parehong gumagaling sa pahinga at maraming tubig, hindi sa antibiotic.", "en": "Both colds and flu are caused by viruses, but the flu is more severe — usually with a high fever and aching all over the body. Both get better with rest and plenty of fluids, not with antibiotics.", "bis": "Parehong gikan sa virus ang sip-on ug trangkaso, apan mas grabe ang trangkaso (flu) — kasagaran may taas nga hilanat ug sakit sa tibuok lawas. Parehong maayo pinaagi sa pahulay ug daghang tubig, dili sa antibiotic."}, "source": "AAAS BSL 6E/M3", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-catch-cold-many-times-g6", "domain": "LIVING_THINGS", "topic": "why you catch colds many times", "grades": [5, 6, 7], "terms": ["sipon", "cold", "colds", "paulit-ulit", "balik-balik", "subli-subli", "many times", "virus", "maraming uri", "daghang klase", "different", "iba-iba", "immune", "antibody", "bagong virus", "bag-ong virus", "bakit", "ngano"], "fact": {"tl": "Maaari kang magkasipon nang paulit-ulit dahil napakaraming iba't ibang uri ng cold virus na nagbibigay ng parehong sintomas. Kahit nalabanan na ng katawan ang isa, bago pa rin sa kanya ang iba pang uri.", "en": "You can catch a cold many times because there are very many different kinds of cold viruses that give similar symptoms. Even after your body has fought off one, the other kinds are still new to it.", "bis": "Mahimo kang magsip-on og balik-balik tungod kay daghan kaayong nagkalainlaing matang sa cold virus nga maghatag og samang sintomas. Bisan ug napildi na sa imong lawas ang usa, ang ubang matang bag-o gihapon para niini."}, "source": "AAAS BSL 6E/M3", "generator": "claude-workflow", "reviewed": false},
  {"id": "chickenpox-once-g5", "domain": "LIVING_THINGS", "topic": "chickenpox", "grades": [4, 5, 6], "terms": ["bulutong-tubig", "chickenpox", "varicella", "butlig", "pantal", "rash", "kati", "makati", "virus", "minsan lang", "kausa ra", "once", "kumakalat", "contagious", "nakakahawa", "makatakod", "immune", "alaala"], "fact": {"tl": "Ang bulutong-tubig (chickenpox) ay sakit na dulot ng virus na nagbibigay ng makating butlig sa balat. Madalas itong nagkakaroon minsan lang sa buhay, dahil naaalala ng katawan ang virus at nakakapaglaban na rito pagkatapos.", "en": "Chickenpox is an illness caused by a virus that gives itchy blisters on the skin. People usually get it only once, because the body remembers the virus and can fight it off afterward.", "bis": "Ang bulutong-tubig (chickenpox) usa ka sakit nga gikan sa virus nga maghatag og makatol nga butlig sa panit. Kasagaran kausa ra kini makuha, kay mahinumdom ang lawas sa virus ug makasukol na niini human niadto."}, "source": "encyclopedia-stable consensus; AAAS BSL 6E/M4", "generator": "claude-workflow", "reviewed": false},
  {"id": "measles-vaccine-g6", "domain": "LIVING_THINGS", "topic": "measles", "grades": [5, 6, 7], "terms": ["tigdas", "measles", "virus", "pantal", "rash", "lagnat", "fever", "nakakahawa", "makatakod", "contagious", "bakuna", "vaccine", "MMR", "mabilis kumalat", "peligroso", "bata", "children", "ubo", "mata"], "fact": {"tl": "Ang tigdas (measles) ay sakit na dulot ng virus na nagbibigay ng mataas na lagnat at pamamantal sa balat, at napakabilis kumalat sa hangin. Mapanganib ito lalo na sa maliliit na bata, pero maiiwasan sa pamamagitan ng bakuna.", "en": "Measles is an illness caused by a virus that brings high fever and a skin rash, and it spreads very quickly through the air. It can be dangerous, especially for young children, but it can be prevented with a vaccine.", "bis": "Ang tigdas (measles) usa ka sakit nga gikan sa virus nga maghatag og taas nga hilanat ug pantal sa panit, ug paspas kaayo mokatap sa hangin. Peligroso kini ilabina sa gagmayng bata, apan malikayan pinaagi sa bakuna."}, "source": "encyclopedia-stable consensus; AAAS BSL 6E/M7", "generator": "claude-workflow", "reviewed": false},
  {"id": "tuberculosis-lungs-g7", "domain": "LIVING_THINGS", "topic": "tuberculosis", "grades": [6, 7, 8], "terms": ["tuberculosis", "TB", "tigbi", "baga", "lungs", "bacteria", "bakterya", "ubo", "cough", "matagal", "dugay", "hangin", "air", "nakakahawa", "gamot", "tambal", "medicine", "BCG", "bakuna", "Pilipinas", "Philippines"], "fact": {"tl": "Ang tuberculosis (TB) ay sakit na dulot ng bacteria na karaniwang umaatake sa baga, at kumakalat sa hangin kapag umuubo ang taong may sakit. Magagamot ito sa pamamagitan ng espesyal na gamot na iniinom nang maraming buwan, at may bakunang BCG para dito.", "en": "Tuberculosis (TB) is a disease caused by bacteria that usually attacks the lungs, and it spreads through the air when a sick person coughs. It can be cured with special medicine taken for many months, and there is a BCG vaccine for it.", "bis": "Ang tuberculosis (TB) usa ka sakit nga gikan sa bacteria nga kasagaran moatake sa baga, ug mokatap sa hangin kung mag-ubo ang tawong may sakit. Matambalan kini pinaagi sa espesyal nga tambal nga imnon sulod sa daghang bulan, ug adunay BCG nga bakuna alang niini."}, "source": "encyclopedia-stable consensus; AAAS BSL 6E/M6", "generator": "claude-workflow", "reviewed": false},
  {"id": "ringworm-fungus-skin-g5", "domain": "LIVING_THINGS", "topic": "ringworm and skin fungus", "grades": [4, 5, 6], "terms": ["buni", "an-an", "ringworm", "fungus", "fungi", "amag sa balat", "sakit sa panit", "skin", "kati", "makati", "bilog", "ring", "hawa", "makatakod", "alipunga", "athlete's foot", "gamot", "cream", "tuyo", "linis"], "fact": {"tl": "Ang buni (ringworm) at alipunga ay sakit sa balat na dulot ng fungus, hindi ng uod. Nagbibigay ito ng makati at minsan bilog na pantal, at kumakalat sa pamamagitan ng paghawak o paggamit ng damit ng may sakit. Tumutulong ang pananatiling malinis at tuyo ng balat.", "en": "Ringworm and athlete's foot are skin diseases caused by a fungus, not a worm. They cause an itchy, sometimes ring-shaped rash and spread by touching or sharing the clothes of someone infected. Keeping the skin clean and dry helps prevent them.", "bis": "Ang buni (ringworm) ug alipunga mga sakit sa panit nga gikan sa fungus, dili sa ulod. Maghatag kini og makatol, usahay lingin nga pantal, ug mokatap pinaagi sa paghikap o paggamit sa sinina sa may sakit. Makatabang ang pagpabilin nga limpyo ug uga sa panit."}, "source": "encyclopedia-stable consensus; AAAS BSL 6E/M3", "generator": "claude-workflow", "reviewed": false},
  {"id": "parasites-worms-g6", "domain": "LIVING_THINGS", "topic": "parasites and intestinal worms", "grades": [5, 6, 7], "terms": ["parasite", "parasito", "bulate", "ulod", "worm", "intestinal worm", "bituka", "tinai", "tiyan", "sakit", "kumakain", "mosuyop", "sustansya", "maruming kamay", "hugaw nga kamot", "sapatos", "deworming", "purga", "gamot", "linis"], "fact": {"tl": "Ang mga parasito tulad ng bulate sa bituka ay nabubuhay sa loob ng katawan at kumukuha ng sustansya mula sa pagkaing kinakain natin. Nakukuha ang mga ito sa maruming pagkain, tubig, o kamay, kaya mahalaga ang paghuhugas ng kamay at pagsusuot ng tsinelas o sapatos.", "en": "Parasites such as intestinal worms live inside the body and take nutrients from the food we eat. They are caught from dirty food, water, or hands, so washing hands and wearing slippers or shoes is important.", "bis": "Ang mga parasito sama sa ulod sa tinai magpuyo sulod sa lawas ug mokuha og sustansya gikan sa pagkaon nga atong gikaon. Makuha kini gikan sa hugaw nga pagkaon, tubig, o kamot, busa importante ang paghugas sa kamot ug pagsul-ob og tsinelas o sapatos."}, "source": "AAAS BSL 6E/M3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "skin-first-defense-g6", "domain": "LIVING_THINGS", "topic": "skin as a barrier against germs", "grades": [5, 6, 7], "terms": ["balat", "panit", "skin", "harang", "babag", "barrier", "depensa", "panalipod", "germ", "mikrobyo", "sugat", "samad", "wound", "sa labas", "first defense", "unang depensa", "langib", "scab", "linis", "tubig"], "fact": {"tl": "Ang balat ang unang harang ng katawan laban sa mga germ — pinipigilan nitong makapasok ang mikrobyo mula sa labas. Kapag nasugatan ang balat, mas madaling makapasok ang germs, kaya mahalagang linisin at takpan ang sugat.", "en": "The skin is the body's first barrier against germs — it stops microbes from getting in from outside. When the skin is cut, germs can enter more easily, so it is important to clean and cover a wound.", "bis": "Ang panit mao ang unang babag sa lawas batok sa mga germ — mapugngan niini nga makasulod ang mikrobyo gikan sa gawas. Kung masamdan ang panit, mas sayon makasulod ang germs, busa importante nga limpyohan ug tabonan ang samad."}, "source": "AAAS BSL 6C/H1; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "stomach-acid-kills-germs-g6", "domain": "LIVING_THINGS", "topic": "stomach acid kills germs", "grades": [5, 6, 7], "terms": ["tiyan", "sikmura", "stomach", "acid", "asido", "germ", "mikrobyo", "pagkain", "food", "pumapatay", "mopatay", "kill", "depensa", "protect", "panalipod", "tunaw", "digest", "nakain"], "fact": {"tl": "May malakas na acid ang ating sikmura na tumutulong tunawin ang pagkain at pumapatay sa maraming germs na nakakain natin. Isa rin ito sa mga paraan ng katawan para protektahan ang sarili laban sa sakit.", "en": "Our stomach has a strong acid that helps digest food and kills many germs we swallow. It is one of the body's ways of protecting itself against disease.", "bis": "Ang atong tiyan adunay kusog nga acid nga motabang sa pagtunaw sa pagkaon ug mopatay sa daghang germs nga atong matulon. Usa usab kini sa mga paagi sa lawas aron panalipdan ang kaugalingon batok sa sakit."}, "source": "AAAS BSL 6C/H1; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "specific-germ-specific-disease-g6", "domain": "LIVING_THINGS", "topic": "specific germs cause specific diseases", "grades": [6, 7, 8], "terms": ["germ", "mikrobyo", "sakit", "disease", "specific", "tiyak", "espesipiko", "iba-iba", "lainlain", "bacteria", "virus", "sanhi", "hinungdan", "cause", "trangkaso", "tigdas", "kanya-kanya", "klase"], "fact": {"tl": "Bawat sakit ay may sariling tiyak na germ na nagdudulot nito — iba ang germ ng trangkaso, iba ang sa tigdas, at iba rin sa TB. Kaya tumutulong sa mga doktor na malaman kung anong germ ang sanhi para malaman ang tamang gamot.", "en": "Each disease has its own specific germ that causes it — the flu germ is different from the measles germ, which is different from the TB germ. Knowing which germ is the cause helps doctors find the right treatment.", "bis": "Ang matag sakit adunay kaugalingong espesipikong germ nga maoy hinungdan niini — lahi ang germ sa trangkaso, lahi sa tigdas, ug lahi usab sa TB. Busa makatabang sa mga doktor nga mahibaw-an kung unsang germ ang hinungdan aron mahibaw-an ang husto nga tambal."}, "source": "AAAS BSL 6E/M6", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-brush-teeth-g3", "domain": "LIVING_THINGS", "topic": "brushing teeth and bacteria", "grades": [2, 3, 4], "terms": ["sipilyo", "brush", "toothbrush", "ngipin", "ngipon", "teeth", "bacteria", "bakterya", "plaque", "sira", "bungbong", "cavity", "asukal", "sugar", "sour", "linis", "kalinisan", "tooth decay", "ung-ong"], "fact": {"tl": "May bacteria sa ating bibig na kumakain ng matamis na natitira sa ngipin at gumagawa ng acid na sumisira dito. Ang pagsisipilyo ng ngipin araw-araw ay nag-aalis sa kanila para hindi mabungbong o masira ang ngipin.", "en": "There are bacteria in our mouth that feed on sweet bits left on the teeth and make an acid that damages them. Brushing teeth every day removes them so teeth don't get cavities or decay.", "bis": "Adunay bacteria sa atong baba nga mokaon sa tam-is nga nahibilin sa ngipon ug maghimo og acid nga modaot niini. Ang pagsipilyo sa ngipon adlaw-adlaw makakuha kanila aron dili mabongbong o madaot ang ngipon."}, "source": "encyclopedia-stable consensus; DepEd health integration", "generator": "claude-workflow", "reviewed": false},
  {"id": "clean-water-prevents-disease-g5", "domain": "LIVING_THINGS", "topic": "clean water and sanitation", "grades": [4, 5, 6], "terms": ["malinis na tubig", "limpyo nga tubig", "clean water", "sanitation", "kalinisan", "kubeta", "toilet", "inumin", "drinking water", "sakit", "disease", "pakulo", "boil", "filter", "salaan", "cholera", "typhoid", "kalusugan", "komunidad"], "fact": {"tl": "Ang malinis na tubig at maayos na kubeta ay mahalaga para maiwasan ang sakit. Ang maruming tubig ay maaaring magdala ng germs na sanhi ng pagtatae at iba pang sakit, kaya pinapakulo o sinasala ang inuming tubig sa maraming lugar.", "en": "Clean water and proper toilets are important for preventing disease. Dirty water can carry germs that cause diarrhea and other illnesses, so in many places drinking water is boiled or filtered.", "bis": "Ang limpyo nga tubig ug maayong kasilyas importante aron malikayan ang sakit. Ang hugaw nga tubig makadala og germs nga hinungdan sa kalibanga ug ubang sakit, busa sa daghang dapit ang imnonon nga tubig pabukalan o salaan."}, "source": "AAAS BSL 6E/M5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cover-food-from-flies-g4", "domain": "LIVING_THINGS", "topic": "covering food from flies", "grades": [3, 4, 5], "terms": ["langaw", "fly", "flies", "lalat", "pagkain", "food", "takip", "tabon", "cover", "germ", "mikrobyo", "bacteria", "sakit", "dumi", "hugaw", "dapo", "tugpa", "nagdadala", "kalinisan"], "fact": {"tl": "Ang mga langaw ay dumadapo sa dumi at basura, kaya nagdadala sila ng germs sa kanilang mga paa. Kapag tumapat sila sa bukas na pagkain, maaari silang mag-iwan ng bacteria, kaya dapat takpan ang pagkain.", "en": "Flies land on filth and garbage, so they carry germs on their feet. When they land on uncovered food, they can leave behind bacteria, so food should be kept covered.", "bis": "Ang mga langaw motugpa sa hugaw ug basura, busa magdala sila og germs sa ilang mga tiil. Kung motugpa sila sa bukas nga pagkaon, makabilin sila og bacteria, busa angay tabonan ang pagkaon."}, "source": "encyclopedia-stable consensus; AAAS BSL 6E/M5", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-eat-healthy-immune-g5", "domain": "LIVING_THINGS", "topic": "nutrition and the immune system", "grades": [4, 5, 6], "terms": ["masustansya", "masustansiya", "nutritious", "gulay", "prutas", "vitamin", "bitamina", "immune system", "depensa", "malakas", "kusgan", "laban sa sakit", "resistensya", "resistance", "tulog", "sleep", "ehersisyo", "kalusugan"], "fact": {"tl": "Ang pagkain ng masustansyang pagkain tulad ng gulay at prutas ay nagbibigay sa katawan ng mga bitamina na kailangan ng immune system para maging malakas. Ang sapat na tulog at ehersisyo ay tumutulong din para mas makalaban tayo sa sakit.", "en": "Eating nutritious food like vegetables and fruit gives the body vitamins the immune system needs to stay strong. Enough sleep and exercise also help us fight off disease better.", "bis": "Ang pagkaon og masustansya nga pagkaon sama sa utanon ug prutas maghatag sa lawas og bitamina nga gikinahanglan sa immune system aron magmalig-on. Ang igong tulog ug ehersisyo motabang usab aron mas makasukol ta sa sakit."}, "source": "AAAS BSL 6C/H1; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fever-rest-recovery-g5", "domain": "LIVING_THINGS", "topic": "resting when sick helps recovery", "grades": [3, 4, 5], "terms": ["pahinga", "pahulay", "rest", "sakit", "sick", "gumaling", "maayo", "recover", "tulog", "sleep", "enerhiya", "energy", "immune system", "laban", "tubig", "gamot", "doktor", "bumawi"], "fact": {"tl": "Kapag may sakit tayo, nakakatulong ang pahinga at tulog dahil binibigyan nito ang katawan ng enerhiya para labanan ang germs. Ang pag-inom ng maraming tubig at pagsunod sa payo ng doktor ay tumutulong para mas mabilis tayong gumaling.", "en": "When we are sick, rest and sleep help because they give the body energy to fight germs. Drinking plenty of water and following a doctor's advice help us recover faster.", "bis": "Kung may sakit ta, makatabang ang pahulay ug tulog kay maghatag kini sa lawas og enerhiya aron pakigbatokan ang germs. Ang pag-inom og daghang tubig ug pagsunod sa tambag sa doktor motabang aron mas paspas ta maayo."}, "source": "encyclopedia-stable consensus; AAAS BSL 6C/H1", "generator": "claude-workflow", "reviewed": false},
  {"id": "pus-sign-of-fighting-g6", "domain": "LIVING_THINGS", "topic": "what pus is", "grades": [5, 6, 7], "terms": ["nana", "pus", "sugat", "samad", "wound", "impeksyon", "infection", "puti", "dilaw", "white blood cells", "patay na germ", "laban", "bacteria", "mikrobyo", "tanda", "senyales", "sign", "namamaga"], "fact": {"tl": "Ang nana (pus) na lumalabas sa namamagang sugat ay binubuo ng mga patay na white blood cells, germs, at cell na nasira sa laban. Senyales ito na nilalabanan ng katawan ang impeksyon sa lugar na iyon.", "en": "The pus that comes out of an infected wound is made of dead white blood cells, germs, and cells damaged in the fight. It is a sign that the body is battling an infection in that spot.", "bis": "Ang nana (pus) nga mogawas sa namaga nga samad gilangkoban sa patay nga white blood cells, germs, ug cell nga nadaot sa away. Timailhan kini nga ang lawas nakigbatok sa impeksiyon niadtong dapita."}, "source": "AAAS BSL 6E/M4; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "germs-too-small-to-see-g3", "domain": "LIVING_THINGS", "topic": "germs are invisible to the eye", "grades": [2, 3, 4], "terms": ["mikrobyo", "germs", "napakaliit", "gamay kaayo", "tiny", "invisible", "hindi nakikita", "dili makita", "mata", "eye", "microscope", "mikroskopyo", "kahit malinis", "kamay", "saanman", "everywhere", "mesa", "hawak"], "fact": {"tl": "Napakaliit ng mga germs kaya hindi natin sila nakikita ng mata — kailangan ng microscope para makita. Kahit mukhang malinis ang isang kamay o mesa, maaaring may mga germs pa rin doon, kaya mahalaga ang paghuhugas at paglilinis.", "en": "Germs are so tiny that we cannot see them with our eyes — you need a microscope to see them. Even if a hand or table looks clean, there may still be germs on it, so washing and cleaning matter.", "bis": "Gamay kaayo ang mga germs maong dili nato sila makita sa mata — kinahanglan og microscope aron makita. Bisan og tan-awon nga limpyo ang usa ka kamot o lamesa, mahimong adunay germs gihapon didto, busa importante ang paghugas ug paglimpyo."}, "source": "AAAS BSL 6E/M3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "immune-germs-invaders-g4", "domain": "LIVING_THINGS", "topic": "immune system fights germs", "grades": [4, 5, 6], "terms": ["immune system", "sistemang panananggol", "panlaban", "germ", "mikrobyo", "bacteria", "virus", "pananggalang", "depensa", "sistema sa panalipod", "kontra sakit", "mga mikrobyo"], "fact": {"tl": "Ang immune system ang panlaban ng katawan na pumipigil sa mga germ tulad ng bacteria at virus na magdulot ng sakit.", "en": "The immune system is the body's defense that stops germs like bacteria and viruses from making us sick.", "bis": "Ang immune system mao ang panalipod sa lawas nga nagpugong sa mga germ sama sa bacteria ug virus aron dili ta magsakit."}, "source": "AAAS BSL 6C/H1; 6C/E3", "generator": "claude-workflow", "reviewed": false},
  {"id": "immune-white-cells-eat-germs-g5", "domain": "LIVING_THINGS", "topic": "white blood cells eat germs", "grades": [5, 6, 7], "terms": ["white blood cells", "puting selula ng dugo", "kumakain", "lumululon", "engulf", "germ", "puting selula sa dugo", "molamoy", "mikrobyo", "selula", "lumaban"], "fact": {"tl": "May mga puting selula ng dugo na parang lumululon at kumakain ng mga germ para wasakin ang mga ito sa loob ng katawan.", "en": "Some white blood cells swallow and eat germs to destroy them inside the body.", "bis": "Adunay mga puti nga selula sa dugo nga molamoy ug mokaon sa mga germ aron laglagon kini sulod sa lawas."}, "source": "AAAS BSL 6C/H1; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "immune-antibodies-lock-key-g6", "domain": "LIVING_THINGS", "topic": "antibodies fight specific germs", "grades": [6, 7, 8], "terms": ["antibody", "antibodies", "sangga", "kandado", "susi", "kapareha ng germ", "kumakapit", "susi ug kandado", "mokapyot", "piho nga germ", "tukma"], "fact": {"tl": "Gumagawa ang katawan ng antibodies na parang susi na bagay lang sa isang uri ng germ at kumakapit dito para madaling mawasak.", "en": "The body makes antibodies that fit one kind of germ like a key, sticking to it so it can be destroyed.", "bis": "Ang lawas mohimo og antibodies nga mohaom sa usa ka klase sa germ sama sa yawi, ug mokapyot niini aron dali kining malaglag."}, "source": "AAAS BSL 6C/H1; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "immune-vaccine-practice-g6", "domain": "LIVING_THINGS", "topic": "how vaccines work", "grades": [6, 7, 8], "terms": ["vaccine", "bakuna", "turok", "ensayo", "sanayin", "memory", "naaalala", "bakunahon", "pagbansay", "mahinumdoman", "panalipod", "kontra sakit"], "fact": {"tl": "Ang bakuna ay nagsasanay sa immune system gamit ang patay o mahinang germ para maalala nito ang kaaway at mabilis lumaban kapag dumating ang tunay na sakit.", "en": "A vaccine trains the immune system using a dead or weakened germ so it remembers the enemy and fights fast if the real disease comes.", "bis": "Ang bakuna mobansay sa immune system gamit ang patay o huyang nga germ aron mahinumdoman niini ang kaaway ug paspas molaban kon moabot ang tinuod nga sakit."}, "source": "AAAS BSL 6C/H1; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "immune-fever-helps-g5", "domain": "LIVING_THINGS", "topic": "fever helps fight infection", "grades": [5, 6, 7], "terms": ["fever", "lagnat", "init ng katawan", "sakit", "kalaban germ", "hilanat", "kainit sa lawas", "panlaban", "init", "mga germ", "mainit"], "fact": {"tl": "Kapag may impeksyon, minsan iniinit ng katawan ang sarili bilang lagnat, na nakakatulong na pabagalin ang ilang germ habang lumalaban ang immune system.", "en": "During an infection the body sometimes raises its heat as a fever, which can slow some germs while the immune system fights.", "bis": "Kon adunay impeksyon, usahay ang lawas mopainit sa kaugalingon isip hilanat, nga makapahinay sa pipila ka germ samtang nagaaway ang immune system."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "immune-skin-first-barrier-g4", "domain": "LIVING_THINGS", "topic": "skin as germ barrier", "grades": [3, 4, 5], "terms": ["skin", "balat", "panangga", "harang", "germ", "tuyo", "panangga sa lawas", "panit", "babag", "mga germ", "mauga", "unang depensa"], "fact": {"tl": "Ang balat ang unang harang ng katawan — pinipigilan nito ang germ at hinahadlangan ang katawan na matuyo.", "en": "The skin is the body's first barrier — it keeps germs out and stops the body from drying out.", "bis": "Ang panit mao ang unang babag sa lawas — kini magpugong sa mga germ ug dili ipasagdan nga mauga ang lawas."}, "source": "AAAS BSL 6C/E3", "generator": "claude-workflow", "reviewed": false},
  {"id": "skin-two-layers-g5", "domain": "LIVING_THINGS", "topic": "skin has layers", "grades": [5, 6, 7], "terms": ["skin layers", "epidermis", "dermis", "ibabaw", "kapal", "balat", "panit", "sapaw", "gawas", "sulod", "duha ka sapaw", "ilalim"], "fact": {"tl": "May dalawang pangunahing kapal ang balat: ang epidermis sa ibabaw na nakikita natin, at ang mas malalim na dermis na may mga ugat at nerve.", "en": "The skin has two main layers: the epidermis we see on top, and the deeper dermis that holds blood vessels and nerves.", "bis": "Ang panit adunay duha ka nag-unang sapaw: ang epidermis sa ibabaw nga atong makita, ug ang mas lawom nga dermis nga adunay mga ugat ug nerve."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "skin-renews-itself-g5", "domain": "LIVING_THINGS", "topic": "skin cells renew", "grades": [5, 6, 7], "terms": ["skin", "balat", "nagpapalit", "bagong selula", "natutuyo", "nalalaglag", "panit", "mag-ilis", "bag-ong selula", "mangahulog", "nagbag-o"], "fact": {"tl": "Patuloy na nagpapalit ng balat ang katawan — natutuyo at nalalaglag ang lumang selula sa ibabaw habang bagong selula ang humahalili mula sa ilalim.", "en": "The body constantly renews its skin — old cells on top dry up and flake off while new cells take their place from below.", "bis": "Ang lawas kanunay nga mag-ilis sa panit — ang daan nga mga selula sa ibabaw mauga ug mangahulog samtang bag-ong selula ang mopuli gikan sa ilawom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "skin-melanin-tan-g5", "domain": "LIVING_THINGS", "topic": "skin tans from sun", "grades": [5, 6, 7], "terms": ["tan", "umiitim", "araw", "melanin", "pananggalang", "sunburn", "sunog ng araw", "mongit-ngit", "adlaw", "panalipod", "init sa adlaw", "kolor sa panit"], "fact": {"tl": "Kapag nasa araw nang matagal, gumagawa ang balat ng mas maraming melanin kaya umiitim ito — isang paraan ng pananggalang laban sa nakakasakit na sinag ng araw.", "en": "When out in the sun a long time, the skin makes more melanin and gets darker — a way to protect itself against the sun's harmful rays.", "bis": "Kon dugay sa adlaw, ang panit mohimo og mas daghang melanin maong mongit-ngit kini — usa ka paagi sa pagpanalipod batok sa makadaot nga silaw sa adlaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "skin-goosebumps-g4", "domain": "LIVING_THINGS", "topic": "why we get goosebumps", "grades": [4, 5, 6], "terms": ["goosebumps", "kilabot", "balahibo", "lamig", "takot", "kuyamoy", "panit", "katugnaw", "kahadlok", "kulba"], "fact": {"tl": "Kapag nilalamig o natatakot tayo, humihigpit ang maliliit na kalamnan sa balat at tumatayo ang balahibo — ito ang kilabot o goosebumps.", "en": "When we feel cold or scared, tiny muscles in the skin tighten and the hairs stand up — that is goosebumps.", "bis": "Kon matugnaw o mahadlok ta, ang gagmay nga kaunoran sa panit mohugot ug motindog ang mga balahibo — mao kini ang kulba o goosebumps."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wound-healing-stages-g6", "domain": "LIVING_THINGS", "topic": "how a wound heals", "grades": [6, 7, 8], "terms": ["wound", "sugat", "gumagaling", "langib", "scab", "bagong balat", "samad", "mamaayo", "kugang", "bag-ong panit", "tambal sa kaugalingon"], "fact": {"tl": "Gumagaling ang sugat nang paunti-unti: una ay namumuo ang dugo, pagkatapos ay nabubuo ang langib na nagpoprotekta habang gumagawa ang katawan ng bagong balat sa ilalim.", "en": "A wound heals step by step: first the blood clots, then a scab forms to protect it while the body builds new skin underneath.", "bis": "Ang samad mamaayo anam-anam: una mamuo ang dugo, dayon mahimo ang kugang nga manalipod samtang ang lawas mohimo og bag-ong panit sa ilawom."}, "source": "AAAS BSL 6C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wound-scar-g6", "domain": "LIVING_THINGS", "topic": "why scars form", "grades": [6, 7, 8], "terms": ["scar", "peklat", "malalim na sugat", "bagong tisyu", "marka", "samad nga lawom", "bag-ong unod", "timaan", "nahimong peklat", "panit nga lahi"], "fact": {"tl": "Kapag malalim ang sugat, minsan iniiwan nito ang peklat dahil ang bagong tisyung pampuno ay hindi kapareho ng dating balat.", "en": "When a wound is deep, it can leave a scar because the new tissue that fills it is not exactly like the original skin.", "bis": "Kon lawom ang samad, usahay magbilin kini og peklat tungod kay ang bag-ong unod nga mopuno niini dili parehas sa orihinal nga panit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "teeth-enamel-hardest-g4", "domain": "LIVING_THINGS", "topic": "tooth enamel is hardest", "grades": [4, 5, 6], "terms": ["enamel", "ngipin", "pinakamatigas", "panangga", "esmalte", "tooth", "ngipon", "pinakagahi", "panalipod", "gahi nga bahin", "ibabaw sa ngipon"], "fact": {"tl": "Ang enamel sa ibabaw ng ngipin ang pinakamatigas na bahagi ng buong katawan, at ito ang nagpoprotekta sa malambot na loob ng ngipin.", "en": "The enamel covering a tooth is the hardest part of the whole body, and it protects the soft inside of the tooth.", "bis": "Ang enamel nga nagtabon sa ngipon mao ang pinakagahi nga bahin sa tibuok lawas, ug kini ang manalipod sa humok nga sulod sa ngipon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "teeth-types-jobs-g4", "domain": "LIVING_THINGS", "topic": "different teeth do different jobs", "grades": [4, 5, 6], "terms": ["teeth types", "pangil", "bagang", "incisor", "molar", "kanine", "ngipin", "klase sa ngipon", "tango", "bag-ang", "mokagat", "moligis", "mongus-ngus"], "fact": {"tl": "Iba-iba ang gawa ng ngipin: ang harapang ngipin ay panghiwa, ang matulis na pangil ay panggutay, at ang malalapad na bagang ay pandurog ng pagkain.", "en": "Different teeth have different jobs: the front teeth cut, the pointed canines tear, and the wide back molars grind food.", "bis": "Lain-lain ang buhat sa ngipon: ang atubangan nga ngipon mangutlo, ang talinis nga tango mogisi, ug ang lapad nga bag-ang moligis sa pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "teeth-cavities-acid-g5", "domain": "LIVING_THINGS", "topic": "how cavities form", "grades": [5, 6, 7], "terms": ["cavity", "bulok na ngipin", "sira ngipin", "asido", "bacteria", "matamis", "ngipon nga gabok", "aslom", "plaque", "tam-is", "mokaon sa ngipon"], "fact": {"tl": "Nabubulok ang ngipin kapag ang bacteria sa bibig ay gumagawa ng asido mula sa natitirang matamis na pagkain, na unti-unting bumubutas sa enamel.", "en": "A tooth decays when bacteria in the mouth make acid from leftover sugary food, slowly eating a hole through the enamel.", "bis": "Magabok ang ngipon kon ang bacteria sa baba mohimo og aslom gikan sa nahabilin nga tam-is nga pagkaon, nga hinay-hinay nga mobangag sa enamel."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "teeth-brushing-fluoride-g4", "domain": "LIVING_THINGS", "topic": "brushing and fluoride", "grades": [4, 5, 6], "terms": ["brush teeth", "magsipilyo", "toothpaste", "fluoride", "plaque", "linis ngipin", "pagpaninglo", "sepilyo", "plaka", "hugasan ang ngipon", "mag-amping"], "fact": {"tl": "Ang pagsisipilyo ay nag-aalis ng plaque at tira-tirang pagkain, at ang fluoride sa toothpaste ay nagpapatibay ng enamel laban sa pagkabulok.", "en": "Brushing removes plaque and bits of food, and the fluoride in toothpaste strengthens enamel against decay.", "bis": "Ang pagsipilyo magtangtang sa plaque ug mga salin sa pagkaon, ug ang fluoride sa toothpaste mopalig-on sa enamel batok sa pagkagabok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "teeth-roots-anchor-g5", "domain": "LIVING_THINGS", "topic": "tooth roots and gums", "grades": [5, 6, 7], "terms": ["tooth root", "ugat ng ngipin", "gilagid", "gum", "nakakapit", "panga", "gamot sa ngipon", "lagus", "gums", "nakaugat", "apapangig"], "fact": {"tl": "Bawat ngipin ay may ugat na nakatanim nang malalim sa panga at hinahawakan ng gilagid para hindi ito matanggal.", "en": "Each tooth has a root planted deep in the jawbone and held by the gums so it does not fall out.", "bis": "Ang matag ngipon adunay gamot nga nakatanom og lawom sa apapangig ug gigunitan sa lagus aron dili kini matangtang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "blood-types-abo-g6", "domain": "LIVING_THINGS", "topic": "blood types A B AB O", "grades": [6, 7, 8], "terms": ["blood type", "uri ng dugo", "grupo", "A B AB O", "klase sa dugo", "tipo sa dugo", "grupo sa dugo", "mga marka", "red blood", "selula sa dugo", "lainlaing dugo"], "fact": {"tl": "May apat na pangunahing uri ng dugo — A, B, AB, at O — depende sa maliliit na markang nasa ibabaw ng pulang selula ng dugo.", "en": "There are four main blood types — A, B, AB, and O — based on tiny markers found on the surface of red blood cells.", "bis": "Adunay upat ka nag-unang klase sa dugo — A, B, AB, ug O — depende sa gagmay nga mga marka sa ibabaw sa pula nga selula sa dugo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "blood-types-matching-transfusion-g7", "domain": "LIVING_THINGS", "topic": "matching blood for transfusion", "grades": [7, 8, 9], "terms": ["blood transfusion", "salin ng dugo", "tugma", "donate", "bigay dugo", "transfusion", "pagsalin sa dugo", "mohaom", "mga klase", "ihatag dugo", "kompatible", "dili magtugma"], "fact": {"tl": "Kapag may nangangailangan ng dugo, kailangang tugma ang uri ng dugo ng nagbigay at tumanggap, dahil ang maling tugma ay maaaring makasama sa katawan.", "en": "When someone needs blood, the donor's and the patient's blood types must match, because a wrong match can harm the body.", "bis": "Kon adunay nanginahanglan og dugo, kinahanglan magtugma ang klase sa dugo sa naghatag ug sa nagdawat, kay ang sayop nga pagtugma makadaot sa lawas."}, "source": "AAAS BSL 6A/M7; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "blood-type-o-donor-g7", "domain": "LIVING_THINGS", "topic": "type O universal donor", "grades": [7, 8, 9], "terms": ["type O", "O blood", "universal donor", "unibersal", "makakapagbigay", "tipo O", "unibersal nga donor", "makahatag sa tanan", "walang marka", "O nga dugo", "donor sa tanan"], "fact": {"tl": "Ang dugong uri O ay tinatawag na universal donor dahil maaari itong ibigay sa karamihan ng tao na walang markang lumalaban dito.", "en": "Type O blood is called the universal donor because it can be given to most people without markers that fight against it.", "bis": "Ang dugo nga klase O gitawag nga universal donor tungod kay mahatag kini sa kadaghanan nga walay marka nga mosukol niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "blood-plasma-liquid-g6", "domain": "LIVING_THINGS", "topic": "blood plasma carries cells", "grades": [6, 7, 8], "terms": ["plasma", "likido ng dugo", "tubig sa dugo", "dinadala", "selula", "likido sa dugo", "nagdala", "naglutaw", "selula sa dugo", "sustansya"], "fact": {"tl": "Karamihan ng dugo ay isang likido na tinatawag na plasma, na nagdadala sa mga selula ng dugo, sustansya, at dumi palabas ng katawan.", "en": "Most of blood is a liquid called plasma, which carries the blood cells, nutrients, and wastes around the body.", "bis": "Kadaghanan sa dugo usa ka likido nga gitawag og plasma, nga nagdala sa mga selula sa dugo, sustansya, ug hugaw libot sa lawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "blood-red-color-g5", "domain": "LIVING_THINGS", "topic": "why blood is red", "grades": [5, 6, 7], "terms": ["red blood", "pula ang dugo", "hemoglobin", "oxygen", "bakal", "ngano pula ang dugo", "pula", "oksiheno", "iron", "kolor sa dugo"], "fact": {"tl": "Pula ang dugo dahil sa hemoglobin, isang sangkap na may bakal na nagdadala ng oxygen at namumula kapag may hawak na oxygen.", "en": "Blood is red because of hemoglobin, an iron-containing substance that carries oxygen and turns red when it holds oxygen.", "bis": "Pula ang dugo tungod sa hemoglobin, usa ka sangkap nga adunay puthaw nga nagdala sa oksiheno ug mopula kon naghupot kini og oksiheno."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "excretory-system-job-g5", "domain": "LIVING_THINGS", "topic": "excretory system removes waste", "grades": [5, 6, 7], "terms": ["excretory system", "sistemang pang-alis dumi", "basura ng katawan", "ihi", "kidney", "sistema sa pag-ekskreta", "hugaw sa lawas", "mokuha sa hugaw", "manlimpyo", "bato"], "fact": {"tl": "Ang excretory system ang nag-aalis ng mga dumi ng katawan, lalo na ang likidong basura na lumalabas bilang ihi.", "en": "The excretory system removes the body's wastes, especially the dissolved liquid waste that leaves as urine.", "bis": "Ang excretory system mao ang mokuha sa mga hugaw sa lawas, ilabi na ang likido nga hugaw nga mogawas isip ihi."}, "source": "AAAS BSL 6C/M3", "generator": "claude-workflow", "reviewed": false},
  {"id": "kidneys-make-urine-g6", "domain": "LIVING_THINGS", "topic": "kidneys filter blood into urine", "grades": [6, 7, 8], "terms": ["kidney", "bato", "salaan ng dugo", "ihi", "dumi", "bato sa lawas", "salaan sa dugo", "limpyohan", "sobrang tubig"], "fact": {"tl": "Sinasala ng dalawang bato (kidney) ang dugo, inaalis ang sobrang tubig at dumi na nagiging ihi.", "en": "The two kidneys filter the blood, removing extra water and wastes that become urine.", "bis": "Ang duha ka bato (kidney) mosala sa dugo, magtangtang sa sobra nga tubig ug hugaw nga mahimong ihi."}, "source": "AAAS BSL 6C/M3", "generator": "claude-workflow", "reviewed": false},
  {"id": "ureters-urethra-path-g7", "domain": "LIVING_THINGS", "topic": "path of urine", "grades": [7, 8, 9], "terms": ["ureter", "urethra", "daan ng ihi", "pantog", "bladder", "tubo sa ihi", "agianan sa ihi", "mogawas", "tubo", "dalan sa ihi"], "fact": {"tl": "Dumadaloy ang ihi mula sa bato pababa sa makitid na tubo na ureter, naiipon sa pantog, at lumalabas sa katawan sa tubong urethra.", "en": "Urine flows from the kidneys down narrow tubes called ureters, collects in the bladder, and leaves the body through the urethra.", "bis": "Ang ihi modagayday gikan sa kidney paubos sa pig-ot nga mga tubo nga ureter, magtigom sa pantog, ug mogawas sa lawas pinaagi sa urethra."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "urine-yellow-water-g5", "domain": "LIVING_THINGS", "topic": "why urine is yellow", "grades": [5, 6, 7], "terms": ["urine color", "kulay ng ihi", "dilaw", "tubig", "inom", "ngano dilaw ang ihi", "kolor sa ihi", "dalag", "mag-inom", "klaro ang ihi"], "fact": {"tl": "Dilaw ang ihi dahil sa dumi na inalis ng bato; kapag kulang sa tubig, mas matingkad ang dilaw, at kapag sapat ang inom, mas maliwanag ito.", "en": "Urine is yellow from wastes the kidneys removed; when you drink too little it turns deeper yellow, and when you drink enough it looks paler.", "bis": "Dalag ang ihi tungod sa hugaw nga gikuha sa bato; kon kulang sa tubig mas labihan ang pagkadalag, ug kon igo ang imnon mas hayag kini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "excretion-skin-lungs-too-g6", "domain": "LIVING_THINGS", "topic": "skin and lungs also excrete", "grades": [6, 7, 8], "terms": ["excretion", "pawis", "sweat", "baga", "carbon dioxide", "balat", "pag-ekskreta", "singot", "alisngaw", "panit", "mogawas ang hugaw"], "fact": {"tl": "Hindi lang bato ang nag-aalis ng dumi — nagpapalabas din ng tubig at asin ang balat sa pamamagitan ng pawis, at ang baga ay naglalabas ng carbon dioxide.", "en": "The kidneys are not alone in removing wastes — the skin releases water and salt through sweat, and the lungs breathe out carbon dioxide.", "bis": "Dili lang ang bato ang mokuha sa hugaw — ang panit mogawas og tubig ug asin pinaagi sa singot, ug ang baga moginhawa pagawas sa carbon dioxide."}, "source": "AAAS BSL 6C/M3", "generator": "claude-workflow", "reviewed": false},
  {"id": "lymph-nodes-swell-g7", "domain": "LIVING_THINGS", "topic": "swollen lymph nodes when sick", "grades": [7, 8, 9], "terms": ["lymph node", "kulani", "namamaga", "sakit", "immune", "manghupong", "magsakit", "panlaban", "nagtrabaho ang immune", "panalipod"], "fact": {"tl": "Kapag may sakit, minsan namamaga ang maliliit na kulani (lymph nodes) sa leeg o kilikili dahil masigla itong gumagawa ng panlaban sa germ.", "en": "When you are sick, small lymph nodes in the neck or armpit may swell because they are busy making defenders against germs.", "bis": "Kon magsakit, usahay manghupong ang gagmay nga lymph nodes sa liog o ilok tungod kay busy kini sa paghimo og panalipod batok sa germ."}, "source": "AAAS BSL 6C/H1; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "immune-handwashing-stops-germs-g3", "domain": "LIVING_THINGS", "topic": "handwashing stops germs", "grades": [3, 4, 5], "terms": ["handwashing", "paghuhugas kamay", "sabon", "germ", "sakit", "panghugas", "paghugas kamot", "mikrobyo", "kalimpyohan", "limpyo", "pugong sa germ"], "fact": {"tl": "Ang paghuhugas ng kamay nang may sabon ay nag-aalis ng mga germ bago sila makapasok sa katawan, kaya isa itong pinakamadaling paraan para hindi magkasakit.", "en": "Washing your hands with soap removes germs before they can get inside the body, making it one of the easiest ways to avoid getting sick.", "bis": "Ang paghugas sa kamot gamit ang sabon magtangtang sa mga germ una pa kini makasulod sa lawas, busa usa kini sa pinakasayon nga paagi aron dili magsakit."}, "source": "AAAS BSL 6C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "blood-clot-stops-bleeding-g5", "domain": "LIVING_THINGS", "topic": "blood clots to stop bleeding", "grades": [5, 6, 7], "terms": ["bleeding", "dugo", "tumitigil", "platelet", "clot", "namumuo", "pagdugo", "mohunong", "mamuo", "sampong", "pugong sa dugo"], "fact": {"tl": "Kapag nasugatan ka, nagtitipon ang maliliit na platelet sa dugo para bumuo ng tapon na pumipigil sa pagdugo.", "en": "When you get hurt, tiny platelets in the blood gather to form a plug that stops the bleeding.", "bis": "Kon masamdan ka, ang gagmay nga platelet sa dugo magtigom aron maghimo og sampong nga mopugong sa pag-agas sa dugo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-we-eat-food-energy-g3", "domain": "LIVING_THINGS", "topic": "why we eat food", "grades": [3, 4], "terms": ["bakit kumakain", "kumain", "kumakain", "pagkain", "ngano mokaon", "mokaon", "pagkaon", "enerhiya", "kusog", "energy", "lakas", "gana", "buhay", "mabuhi", "fuel", "gasolina"], "fact": {"tl": "Kumakain tayo dahil ang pagkain ang nagbibigay ng enerhiya para makagalaw, makapag-isip, at lumaki — parang gasolina ito ng ating katawan.", "en": "We eat because food gives us the energy to move, think, and grow — it is like fuel for our body.", "bis": "Mokaon ta tungod kay ang pagkaon maghatag og kusog aron makalihok, makahunahuna, ug motubo — sama kini sa gasolina sa atong lawas."}, "source": "AAAS BSL Ch.6 (6E/E1); NRC LS1.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "carbohydrates-energy-food-g5", "domain": "LIVING_THINGS", "topic": "carbohydrates for energy", "grades": [5, 6], "terms": ["carbohydrates", "karbohidrato", "kanin", "kan-on", "tinapay", "tinapayan", "kamote", "mais", "enerhiya", "kusog", "energy", "go food", "go foods", "pampalakas"], "fact": {"tl": "Ang mga carbohydrates tulad ng kanin, kamote, at tinapay ang pangunahing pinagkukunan ng mabilis na enerhiya ng katawan.", "en": "Carbohydrates like rice, sweet potato (kamote), and bread are the body's main source of quick energy.", "bis": "Ang mga carbohydrates sama sa kan-on, kamote, ug tinapay maoy nag-unang gigikanan sa paspas nga kusog sa lawas."}, "source": "AAAS BSL Ch.6; DepEd Health/Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "protein-builds-body-g5", "domain": "LIVING_THINGS", "topic": "protein builds and repairs the body", "grades": [5, 6], "terms": ["protina", "protein", "grow food", "grow foods", "isda", "itlog", "manok", "karne", "unod", "baka", "gatas", "monggo", "mongo", "beans", "paglaki", "pagtubo", "pag-ayo", "kalamnan", "muscle", "kaunoran"], "fact": {"tl": "Ang protina mula sa isda, itlog, manok, at monggo ang gumagawa at nag-aayos ng mga bahagi ng katawan tulad ng kalamnan.", "en": "Protein from fish, eggs, chicken, and beans builds and repairs body parts such as muscles.", "bis": "Ang protina gikan sa isda, itlog, manok, ug monggo maoy maghimo ug mag-ayo sa mga bahin sa lawas sama sa kaunoran."}, "source": "AAAS BSL Ch.6 (6E/E1)", "generator": "claude-workflow", "reviewed": false},
  {"id": "fats-store-energy-g6", "domain": "LIVING_THINGS", "topic": "fats store energy", "grades": [6, 7], "terms": ["taba", "fat", "fats", "tambok", "mantika", "lana", "cooking oil", "mani", "nuts", "enerhiya", "kusog", "imbak", "tipig", "stored", "bitamina", "sobra", "sobrang taba"], "fact": {"tl": "Ang taba mula sa mantika, mani, at ilang karne ay nag-iimbak ng enerhiya at tumutulong sa katawan na sumipsip ng ilang bitamina, ngunit ang sobra ay hindi mabuti sa kalusugan.", "en": "Fats from oil, nuts, and some meats store energy and help the body absorb certain vitamins, but too much is unhealthy.", "bis": "Ang tambok gikan sa lana, mani, ug pipila ka karne magtipig og kusog ug motabang sa lawas nga makasuyop og pipila ka bitamina, apan ang sobra dili maayo sa panglawas."}, "source": "AAAS BSL Ch.6 (6E/M2)", "generator": "claude-workflow", "reviewed": false},
  {"id": "calcium-strong-bones-g5", "domain": "LIVING_THINGS", "topic": "calcium for bones and teeth", "grades": [4, 5, 6], "terms": ["calcium", "kalsyum", "buto", "bukog", "ngipin", "ngipon", "teeth", "gatas", "milk", "keso", "cheese", "dahong gulay", "utanon", "malakas", "lig-on", "matibay", "strong bones"], "fact": {"tl": "Ang calcium na nasa gatas, keso, at madahong gulay ay nagpapalakas at nagpapatibay ng buto at ngipin.", "en": "Calcium found in milk, cheese, and leafy vegetables makes bones and teeth strong and hard.", "bis": "Ang calcium nga anaa sa gatas, keso, ug mga dahon nga utanon maglig-on ug magpagahi sa bukog ug ngipon."}, "source": "AAAS BSL Ch.6 (6E/E1b)", "generator": "claude-workflow", "reviewed": false},
  {"id": "iron-prevents-anemia-g6", "domain": "LIVING_THINGS", "topic": "iron prevents anemia", "grades": [6, 7], "terms": ["iron", "bakal", "mineral", "dugo", "blood", "red blood cells", "malunggay", "kamatis", "atay", "liver", "karne", "gulay", "anemia", "kapoy", "panghihina", "luya", "pamutla", "kulay", "oxygen"], "fact": {"tl": "Ang iron mula sa pagkaing tulad ng malunggay, karne, at atay ay tumutulong sa dugo na magdala ng oxygen; kapag kulang dito, nagkaka-anemia at nanghihina ang tao.", "en": "Iron from foods like malunggay, meat, and liver helps the blood carry oxygen; without enough of it a person gets anemia and feels weak.", "bis": "Ang iron gikan sa pagkaon sama sa malunggay, karne, ug atay motabang sa dugo nga magdala og oxygen; kon kulang niini, magka-anemia ug magluya ang tawo."}, "source": "AAAS BSL Ch.6 (6E/E1b); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "iodine-prevents-goiter-g6", "domain": "LIVING_THINGS", "topic": "iodine prevents goiter", "grades": [6, 7], "terms": ["iodine", "yodo", "mineral", "goiter", "goyter", "beke", "leeg", "liog", "thyroid", "asin", "iodized salt", "asin na may yodo", "isda", "seafood", "dagat", "kulang"], "fact": {"tl": "Ang iodine na idinaragdag sa asin (iodized salt) at matatagpuan sa isda ay kailangan ng katawan; ang kakulangan dito ay nagdudulot ng goiter o pamamaga sa leeg.", "en": "Iodine added to salt (iodized salt) and found in seafood is needed by the body; a lack of it causes goiter, a swelling in the neck.", "bis": "Ang iodine nga gidugang sa asin (iodized salt) ug makita sa isda gikinahanglan sa lawas; ang kakulang niini magpahinabog goiter o paghubag sa liog."}, "source": "encyclopedia-stable consensus; DepEd Health", "generator": "claude-workflow", "reviewed": false},
  {"id": "vitamin-a-eyesight-g5", "domain": "LIVING_THINGS", "topic": "vitamin A for eyesight", "grades": [4, 5], "terms": ["vitamin A", "bitamina A", "mata", "eyes", "paningin", "panan-aw", "eyesight", "gabi", "night vision", "karot", "carrot", "kamote", "squash", "kalabasa", "malunggay", "dahon", "dilaw", "orange"], "fact": {"tl": "Ang vitamin A na nasa karot, kalabasa, at madahong gulay ay nakakatulong sa malinaw na paningin, lalo na sa gabi.", "en": "Vitamin A found in carrots, squash, and leafy greens helps with clear eyesight, especially at night.", "bis": "Ang vitamin A nga anaa sa karot, kalabasa, ug mga dahon nga utanon motabang sa tin-aw nga panan-aw, ilabi na sa gabii."}, "source": "NRC LS1.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "vitamin-c-fights-sickness-g5", "domain": "LIVING_THINGS", "topic": "vitamin C and immunity", "grades": [4, 5], "terms": ["vitamin C", "bitamina C", "prutas", "fruit", "kalamansi", "dalandan", "orange", "bayabas", "guava", "gulay", "immune system", "lumalaban", "sakit", "sip-on", "sugat", "samad", "wound", "kahel"], "fact": {"tl": "Ang vitamin C mula sa kalamansi, dalandan, at bayabas ay tumutulong sa katawan na labanan ang sakit at magpagaling ng sugat.", "en": "Vitamin C from kalamansi, oranges, and guava helps the body fight illness and heal wounds.", "bis": "Ang vitamin C gikan sa kalamansi, kahel, ug bayabas motabang sa lawas nga makigbatok sa sakit ug makaayo sa samad."}, "source": "NRC LS1.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "vitamin-d-sunlight-bones-g5", "domain": "LIVING_THINGS", "topic": "vitamin D from sunlight", "grades": [4, 5, 6], "terms": ["vitamin D", "bitamina D", "araw", "adlaw", "sunlight", "sikat ng araw", "sidlak", "balat", "skin", "buto", "bukog", "calcium", "umaga", "isda", "itlog", "malakas na buto"], "fact": {"tl": "Ginagawa ng balat ang vitamin D kapag tinatamaan ito ng sikat ng araw, at tinutulungan nito ang katawan na gamitin ang calcium para sa matibay na buto.", "en": "The skin makes vitamin D when sunlight touches it, and this helps the body use calcium for strong bones.", "bis": "Ang panit maghimo og vitamin D kon mahaplasan kini sa sidlak sa adlaw, ug kini motabang sa lawas nga magamit ang calcium para sa lig-on nga bukog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-most-important-nutrient-g4", "domain": "LIVING_THINGS", "topic": "why we need water", "grades": [3, 4, 5], "terms": ["tubig", "water", "inom", "uminom", "inumin", "drink", "imnon", "hydration", "uhaw", "giuhaw", "thirst", "katawan", "lawas", "dugo", "blood", "init", "pawis", "singot", "sweat", "temperatura"], "fact": {"tl": "Kailangan nating uminom ng tubig araw-araw dahil ginagamit ito ng katawan sa pagdadala ng sustansya, paglilinis ng dumi, at pagpapanatili ng tamang temperatura.", "en": "We need to drink water every day because the body uses it to carry nutrients, remove waste, and keep the right temperature.", "bis": "Kinahanglan ta moinom og tubig adlaw-adlaw kay gamiton kini sa lawas sa pagdala og sustansya, paghinlo sa hugaw, ug pagpabilin sa hustong temperatura."}, "source": "AAAS BSL Ch.6; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dehydration-feel-thirsty-g4", "domain": "LIVING_THINGS", "topic": "dehydration and thirst", "grades": [4, 5], "terms": ["uhaw", "giuhaw", "thirst", "thirsty", "dehydration", "kakulangan ng tubig", "kulang sa tubig", "tubig", "water", "init", "kainitan", "pawis", "singot", "sweat", "hilo", "sakit ng ulo", "luya", "babala", "pasidaan", "palatandaan"], "fact": {"tl": "Kapag kulang sa tubig ang katawan (dehydration), nauuhaw tayo bilang babala; maaari ring sumakit ang ulo at manghina ang tao lalo na kapag mainit o pagod sa laro.", "en": "When the body is low on water (dehydration), we feel thirsty as a warning; it can also cause headaches and weakness, especially when it is hot or after hard play.", "bis": "Kon kulang sa tubig ang lawas (dehydration), uhawon ta isip pasidaan; mahimo usab nga sakiton ang ulo ug magluya ang tawo ilabi na kon init o human sa kusog nga dula."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fiber-helps-digestion-g6", "domain": "LIVING_THINGS", "topic": "fiber and digestion", "grades": [6, 7], "terms": ["fiber", "hibla", "gulay", "utanon", "prutas", "fruit", "brown rice", "whole grain", "panunaw", "paghilis", "digestion", "dumi", "bituka", "intestine", "tae", "constipation", "tibi", "regular", "pagkalibang"], "fact": {"tl": "Ang fiber na nasa gulay, prutas, at whole grains ay tumutulong sa maayong panunaw at pagdumi nang regular.", "en": "Fiber found in vegetables, fruits, and whole grains helps with good digestion and regular bowel movement.", "bis": "Ang fiber nga anaa sa utanon, prutas, ug whole grains motabang sa maayong paghilis ug regular nga pagkalibang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "too-much-sugar-unhealthy-g5", "domain": "LIVING_THINGS", "topic": "too much sugar is unhealthy", "grades": [4, 5, 6], "terms": ["asukal", "sugar", "sobrang tamis", "matam-is", "sweets", "kendi", "candy", "softdrinks", "soft drinks", "tam-is", "junk", "ngipin", "ngipon", "teeth", "tooth decay", "sira", "bulok", "timbang", "weight", "kaunti lang"], "fact": {"tl": "Ang sobrang asukal mula sa kendi at softdrinks ay nakakasira ng ngipin at maaaring magdulot ng problema sa timbang at kalusugan, kaya dapat kaunti lang.", "en": "Too much sugar from candy and soft drinks damages teeth and can cause weight and health problems, so it should be eaten only in small amounts.", "bis": "Ang sobrang asukal gikan sa kendi ug softdrinks makadaot sa ngipon ug mahimong hinungdan og problema sa timbang ug panglawas, mao nga gamay lang ang angay kaonon."}, "source": "AAAS BSL Ch.6 (6E/M2); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "junk-food-vs-real-food-g5", "domain": "LIVING_THINGS", "topic": "junk food vs nutritious food", "grades": [5, 6], "terms": ["junk food", "junk", "chichirya", "chips", "instant", "sustansya", "nutrient", "walang sustansya", "masustansya", "empty calories", "asin", "tasik", "taba", "asukal", "hindi malusog", "unhealthy", "gulay", "prutas", "meryenda"], "fact": {"tl": "Ang junk food tulad ng chichirya ay madalas na puno ng asin, taba, at asukal ngunit kakaunti ang sustansya, kaya mas mainam ang prutas at gulay bilang meryenda.", "en": "Junk food like chips is often full of salt, fat, and sugar but has few nutrients, so fruits and vegetables make a better snack.", "bis": "Ang junk food sama sa chips kasagarang puno sa asin, tambok, ug asukal apan gamay ra og sustansya, mao nga mas maayo ang prutas ug utanon isip meryenda."}, "source": "AAAS BSL Ch.6 (6E/M2)", "generator": "claude-workflow", "reviewed": false},
  {"id": "breakfast-important-meal-g4", "domain": "LIVING_THINGS", "topic": "importance of breakfast", "grades": [3, 4, 5], "terms": ["almusal", "agahan", "breakfast", "pamahaw", "umaga", "buntag", "morning", "enerhiya", "kusog", "energy", "gising", "mata", "pag-aaral", "focus", "gutom", "gigutom", "klase", "school"], "fact": {"tl": "Mahalaga ang almusal dahil nagbibigay ito ng enerhiya pagkatapos ng mahabang tulog, para makapag-isip at makapag-aral nang mabuti ang bata.", "en": "Breakfast is important because it gives energy after a long sleep, so a child can think and learn well.", "bis": "Importante ang pamahaw kay maghatag kini og kusog human sa taas nga tulog, aron makahunahuna ug makakat-on og maayo ang bata."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "variety-of-food-balanced-g4", "domain": "LIVING_THINGS", "topic": "eating a variety of foods", "grades": [3, 4], "terms": ["sari-saring pagkain", "iba-ibang pagkain", "variety", "balanse", "balanced", "nagkalainlain", "lainlain", "klase", "sustansya", "masustansya", "isang uri lang", "kompleto", "complete", "lahat ng grupo"], "fact": {"tl": "Walang isang pagkaing may lahat ng sustansyang kailangan natin, kaya dapat kumain ng sari-saring pagkain mula sa lahat ng grupo araw-araw.", "en": "No single food has all the nutrients we need, so we should eat a variety of foods from all the groups every day.", "bis": "Walay usa ka pagkaon nga adunay tanang sustansyang atong gikinahanglan, mao nga angay tang mokaon og nagkalainlaing pagkaon gikan sa tanang grupo matag adlaw."}, "source": "AAAS BSL Ch.6 (6E/P1)", "generator": "claude-workflow", "reviewed": false},
  {"id": "exercise-strengthens-heart-g6", "domain": "LIVING_THINGS", "topic": "exercise strengthens heart and lungs", "grades": [5, 6, 7], "terms": ["ehersisyo", "exercise", "puso", "kasingkasing", "heart", "baga", "lungs", "kalamnan", "muscle", "kaunoran", "takbo", "dagan", "run", "laro", "dula", "malakas", "lig-on", "kalusugan", "fit"], "fact": {"tl": "Ang regular na ehersisyo tulad ng pagtakbo at paglalaro ay nagpapalakas sa puso, baga, at kalamnan, at nagpapanatili ng malusog na katawan.", "en": "Regular exercise like running and playing strengthens the heart, lungs, and muscles, and keeps the body healthy.", "bis": "Ang regular nga ehersisyo sama sa pagdagan ug pagdula maglig-on sa kasingkasing, baga, ug kaunoran, ug magpabilin nga himsog ang lawas."}, "source": "AAAS BSL Ch.6 (6E/M1b)", "generator": "claude-workflow", "reviewed": false},
  {"id": "exercise-uses-calories-g7", "domain": "LIVING_THINGS", "topic": "exercise and food energy", "grades": [7, 8], "terms": ["calorie", "kaloriya", "enerhiya", "kusog", "energy", "ehersisyo", "exercise", "sunog", "gasto", "gugol", "burn", "gawi", "aktibidad", "activity", "timbang", "weight", "balanse", "pagkain", "sobrang kain"], "fact": {"tl": "Ang ehersisyo ay gumagamit ng enerhiya (calories) mula sa pagkain; kapag kasing-dami lang ang kinakain natin ng nagagasta natin, mas madaling mapanatili ang malusog na timbang.", "en": "Exercise uses up food energy (calories); when we eat about as much as we burn, it is easier to keep a healthy weight.", "bis": "Ang ehersisyo mogamit og kusog (calories) gikan sa pagkaon; kon ang atong gikaon sama ra kadaghan sa atong nagasto, mas sayon ang pagpabilin og himsog nga timbang."}, "source": "AAAS BSL Ch.6 (6E/M1)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sleep-helps-body-repair-g6", "domain": "LIVING_THINGS", "topic": "sleep repairs and strengthens the body", "grades": [5, 6, 7], "terms": ["tulog", "katog", "sleep", "pahinga", "pahulay", "rest", "ayos", "reparar", "repair", "cell", "selula", "immune", "paglaki", "growth", "hormone", "utak", "alaala", "memory", "gabi", "sapat"], "fact": {"tl": "Habang natutulog, inaayos ng katawan ang mga sirang cell, pinalalakas ang immune system, at inilalabas ang mga hormone na tumutulong sa bata na lumaki.", "en": "During sleep the body repairs damaged cells, strengthens the immune system, and releases hormones that help a child grow.", "bis": "Samtang natulog, ayohon sa lawas ang nadaot nga mga cell, lig-onon ang immune system, ug ipagawas ang mga hormone nga motabang sa bata nga motubo."}, "source": "AAAS BSL Ch.6; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "handwashing-before-eating-g3", "domain": "LIVING_THINGS", "topic": "washing hands before eating", "grades": [2, 3, 4], "terms": ["hugas", "maghugas", "paghuhugas", "kamay", "kamot", "wash hands", "sabon", "soap", "tubig", "water", "mikrobyo", "germ", "germs", "sakit", "sip-on", "disease", "kumain", "mokaon", "bago kumain", "linis"], "fact": {"tl": "Ang paghuhugas ng kamay gamit ang sabon at tubig bago kumain ay nag-aalis ng mga germ para hindi tayo magkasakit.", "en": "Washing hands with soap and water before eating removes germs so we do not get sick.", "bis": "Ang paghugas sa kamot gamit ang sabon ug tubig sa dili pa mokaon mokuha sa mga germ aron dili ta magsakit."}, "source": "AAAS BSL Ch.6 (6E/P3)", "generator": "claude-workflow", "reviewed": false},
  {"id": "brushing-teeth-prevents-decay-g3", "domain": "LIVING_THINGS", "topic": "brushing teeth prevents tooth decay", "grades": [2, 3, 4], "terms": ["sipilyo", "magsipilyo", "sepilyo", "brush teeth", "ngipin", "ngipon", "teeth", "tooth", "toothpaste", "kolgeyt", "sira", "bulok", "decay", "cavity", "bukbok", "plaque", "matam-is", "bacteria", "araw-araw"], "fact": {"tl": "Ang pagsisipilyo ng ngipin dalawang beses sa isang araw ay nag-aalis ng pagkaing natitira at bacteria na sanhi ng pagkabulok ng ngipin.", "en": "Brushing teeth twice a day removes leftover food and bacteria that cause tooth decay.", "bis": "Ang pagsipilyo sa ngipon kaduha sa usa ka adlaw mokuha sa nahabilin nga pagkaon ug bacteria nga maoy hinungdan sa pagkabulok sa ngipon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "malunggay-nutritious-leaves-g5", "domain": "LIVING_THINGS", "topic": "malunggay is nutritious", "grades": [4, 5, 6], "terms": ["malunggay", "moringa", "kamunggay", "dahon", "leaves", "utanon", "gulay", "sustansya", "masustansya", "iron", "calcium", "vitamin", "bitamina", "tinola", "sabaw", "soup", "pinoy", "lokal"], "fact": {"tl": "Ang malunggay ay isang masustansyang dahon na mayaman sa iron, calcium, at vitamins, kaya madalas itong idinaragdag sa sabaw at tinola sa Pilipinas.", "en": "Malunggay (moringa) is a nutritious leaf rich in iron, calcium, and vitamins, so it is often added to soups in the Philippines.", "bis": "Ang kamunggay (malunggay) usa ka masustansya nga dahon nga dato sa iron, calcium, ug bitamina, mao nga kanunay kining idugang sa sabaw sa Pilipinas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fish-healthy-protein-ph-g5", "domain": "LIVING_THINGS", "topic": "fish as healthy protein", "grades": [4, 5, 6], "terms": ["isda", "fish", "bangus", "tilapia", "galunggong", "protina", "protein", "sustansya", "masustansya", "utak", "brain", "omega", "dagat", "sea", "pinoy", "murang ulam", "ulam", "malusog", "utok"], "fact": {"tl": "Ang isda tulad ng bangus, tilapia, at galunggong ay magandang pinagkukunan ng protina at sustansyang mabuti para sa puso at utak.", "en": "Fish like bangus, tilapia, and galunggong are a good source of protein and nutrients that are good for the heart and brain.", "bis": "Ang isda sama sa bangus, tilapia, ug galunggong maayo nga gigikanan sa protina ug sustansya nga maayo sa kasingkasing ug utok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "vegetables-fruits-glow-foods-g4", "domain": "LIVING_THINGS", "topic": "vegetables and fruits as glow foods", "grades": [3, 4, 5], "terms": ["gulay", "utanon", "vegetables", "prutas", "fruit", "glow food", "glow foods", "bitamina", "vitamins", "mineral", "balat", "skin", "kutis", "panit", "kolor", "kalusugan", "kangkong", "talong", "mangga", "saging"], "fact": {"tl": "Ang gulay at prutas ang tinatawag na GLOW foods dahil ang mga vitamins at minerals dito ay nagpapanatili ng malusog na balat, mata, at katawan.", "en": "Vegetables and fruits are called GLOW foods because the vitamins and minerals in them keep the skin, eyes, and body healthy.", "bis": "Ang utanon ug prutas gitawag og GLOW foods kay ang mga bitamina ug mineral niini magpabilin nga himsog ang panit, mata, ug lawas."}, "source": "DepEd Health/Science; AAAS BSL Ch.6", "generator": "claude-workflow", "reviewed": false},
  {"id": "food-pyramid-portions-g6", "domain": "LIVING_THINGS", "topic": "food pyramid and portions", "grades": [6, 7], "terms": ["food pyramid", "piramide ng pagkain", "pyramid", "balanced diet", "balanseng pagkain", "dami", "sukat", "portion", "rasyon", "kanin", "gulay", "prutas", "taba", "asukal", "kaunti", "marami", "gabay", "guide"], "fact": {"tl": "Ipinapakita ng food pyramid na dapat tayong kumain ng mas maraming kanin, gulay, at prutas, at kaunting taba at matamis lang, para balanse ang pagkain.", "en": "The food pyramid shows that we should eat more grains, vegetables, and fruits, and only a little fat and sweets, to keep a balanced diet.", "bis": "Ang food pyramid magpakita nga angay tang mokaon og mas daghang kan-on, utanon, ug prutas, ug gamay lang nga tambok ug tam-is, aron balanse ang pagkaon."}, "source": "DepEd Health/Science; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "malnutrition-too-little-food-g6", "domain": "LIVING_THINGS", "topic": "malnutrition from poor diet", "grades": [6, 7], "terms": ["malnutrisyon", "malnutrition", "kulang sa sustansya", "undernourished", "sustansya", "nutrient", "payat", "niwang", "stunting", "bansot", "paglaki", "growth", "hindi tumutubo", "luya", "sakit", "sakitin", "kakulangan", "pagkain"], "fact": {"tl": "Ang malnutrisyon ay nangyayari kapag kulang sa sustansya ang kinakain ng isang tao, na maaaring magdulot ng pagiging bansot, panghihina, at madaling pagkakasakit.", "en": "Malnutrition happens when a person's food lacks enough nutrients, which can cause stunted growth, weakness, and getting sick easily.", "bis": "Ang malnutrisyon mahitabo kon kulang sa sustansya ang gikaon sa usa ka tawo, nga mahimong hinungdan og pagka-bansot, kaluya, ug sayon nga pagsakit."}, "source": "AAAS BSL Ch.6 (6E/E1); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "too-much-salt-unhealthy-g7", "domain": "LIVING_THINGS", "topic": "too much salt is unhealthy", "grades": [7, 8], "terms": ["asin", "salt", "tasik", "sodium", "maalat", "alat", "presyon", "blood pressure", "high blood", "puso", "heart", "kidney", "bato", "instant", "processed", "kaunti lang", "sobra"], "fact": {"tl": "Ang sobrang asin sa pagkain ay maaaring magtaas ng presyon ng dugo at makaapekto sa puso, kaya dapat hindi sobra ang inaasin.", "en": "Too much salt in food can raise blood pressure and affect the heart, so we should not over-salt our food.", "bis": "Ang sobrang asin sa pagkaon makapataas sa presyon sa dugo ug makaapekto sa kasingkasing, mao nga dili angay sobra ang pag-asin."}, "source": "AAAS BSL Ch.6 (6E/M2); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "clean-safe-water-health-g4", "domain": "LIVING_THINGS", "topic": "clean and safe drinking water", "grades": [4, 5], "terms": ["malinis na tubig", "tubig", "clean water", "safe water", "hugaw na tubig", "contaminated", "germ", "mikrobyo", "pakuluan", "boil", "sakit sa tiyan", "diarrhea", "pagtatae", "kalibang", "imnon", "inumin", "kalusugan"], "fact": {"tl": "Mahalagang malinis at ligtas ang tubig na iniinom natin, dahil ang maruming tubig ay maaaring magdala ng germ na nagdudulot ng pagtatae at sakit sa tiyan.", "en": "It is important that our drinking water is clean and safe, because dirty water can carry germs that cause diarrhea and stomach illness.", "bis": "Importante nga limpyo ug luwas ang tubig nga atong imnon, kay ang hugaw nga tubig makadalag germ nga maghatag og kalibang ug sakit sa tiyan."}, "source": "AAAS BSL Ch.6 (6E/P3); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cell-unit-of-life-g5", "domain": "LIVING_THINGS", "topic": "cell is the basic unit of life", "grades": [5, 6], "terms": ["selula", "cell", "pinakamaliit na bahagi ng buhay", "yunit ng buhay", "selyula", "binubuo ng selula", "gilinhan", "labing gamay nga bahin", "binuo sa selula", "unit of life", "building block"], "fact": {"tl": "Ang selula ang pinakamaliit na yunit ng buhay, at lahat ng nabubuhay na bagay ay binubuo ng isa o maraming selula.", "en": "The cell is the smallest unit of life, and every living thing is made of one or many cells.", "bis": "Ang selula mao ang pinakagamay nga yunit sa kinabuhi, ug ang tanang buhing butang gibuhat gikan sa usa o daghang selula."}, "source": "AAAS Benchmarks 5C/M1a; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "cells-too-small-to-see-g4", "domain": "LIVING_THINGS", "topic": "cells are microscopic", "grades": [4, 5], "terms": ["selula", "cell", "napakaliit", "hindi nakikita", "mata", "microscope", "mikroskopyo", "gamay kaayo", "dili makita", "mata lang", "too small to see", "naked eye"], "fact": {"tl": "Karamihan ng mga selula ay napakaliit kaya hindi natin sila nakikita sa mata lang; kailangan natin ng mikroskopyo.", "en": "Most cells are so tiny that we cannot see them with our eyes alone; we need a microscope.", "bis": "Kadaghanan sa mga selula gamay ra kaayo mao nga dili nato sila makita sa mata lang; kinahanglan natog mikroskopyo."}, "source": "AAAS Benchmarks 5C/E2a, 5C/M1a", "generator": "claude-workflow", "reviewed": false},
  {"id": "microscope-reveals-cells-g5", "domain": "LIVING_THINGS", "topic": "microscopes show living things are made of cells", "grades": [4, 5, 6], "terms": ["mikroskopyo", "microscope", "palaki", "magnify", "selula", "cell", "tumitingin", "pagdako", "tan-aw", "lens", "magnifier", "see cells"], "fact": {"tl": "Sa tulong ng mikroskopyo, nakita ng mga siyentipiko na ang mga halaman at hayop ay gawa sa maliliit na selula.", "en": "With the help of microscopes, scientists discovered that plants and animals are made of tiny cells.", "bis": "Pinaagi sa mikroskopyo, nadiskobrehan sa mga siyentista nga ang mga tanom ug hayop gibuhat gikan sa gagmayng selula."}, "source": "AAAS Benchmarks 5C/E2a", "generator": "claude-workflow", "reviewed": false},
  {"id": "robert-hooke-named-cells-g6", "domain": "LIVING_THINGS", "topic": "Robert Hooke named the cell", "grades": [6, 7], "terms": ["Robert Hooke", "Hooke", "pangalan ng selula", "cork", "tapon", "1665", "nagngalan", "ginganlan ang selula", "named cell", "scientist"], "fact": {"tl": "Si Robert Hooke ang unang gumamit ng salitang 'cell' noong 1665 nang makita niya ang mga maliliit na puwang sa balat ng tapon (cork) sa ilalim ng mikroskopyo.", "en": "Robert Hooke first used the word 'cell' in 1665 when he saw tiny empty spaces in cork under a microscope.", "bis": "Si Robert Hooke mao ang unang migamit sa pulong nga 'cell' niadtong 1665 dihang nakita niya ang gagmayng bakanteng espasyo sa cork ilalom sa mikroskopyo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "leeuwenhoek-saw-microbes-g6", "domain": "LIVING_THINGS", "topic": "Leeuwenhoek saw living microbes", "grades": [6, 7], "terms": ["Leeuwenhoek", "Anton van Leeuwenhoek", "mikrobyo", "microbe", "bakterya", "bacteria", "unang nakakita", "tubig", "buhing mikrobyo", "first to see", "animalcules"], "fact": {"tl": "Si Anton van Leeuwenhoek ang unang nakakita ng mga buhay na mikrobyo gaya ng bakterya sa pamamagitan ng kanyang sariling gawang mikroskopyo.", "en": "Anton van Leeuwenhoek was the first person to see living microbes, such as bacteria, using a microscope he made himself.", "bis": "Si Anton van Leeuwenhoek mao ang unang tawo nga nakakita sa buhing mikrobyo, sama sa bakterya, gamit ang mikroskopyo nga iyang gibuhat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "single-celled-organisms-g5", "domain": "LIVING_THINGS", "topic": "single-celled organisms", "grades": [4, 5, 6], "terms": ["isang selula", "single cell", "single-celled", "ameba", "amoeba", "bakterya", "bacteria", "buong nabubuhay", "usa ka selula", "organismo", "tibuok organismo", "one cell organism", "microorganism"], "fact": {"tl": "May mga nabubuhay na binubuo lamang ng isang selula, gaya ng ameba at bakterya, at kaya nilang kumain, lumaki, at magparami.", "en": "Some living things are made of just one cell, like the amoeba and bacteria, and that single cell can eat, grow, and reproduce.", "bis": "Adunay mga buhing butang nga gibuhat gikan sa usa ra ka selula, sama sa amoeba ug bakterya, ug kana nga selula makakaon, makadako, ug makapadaghan."}, "source": "AAAS Benchmarks 5C/E1", "generator": "claude-workflow", "reviewed": false},
  {"id": "cell-membrane-g6", "domain": "LIVING_THINGS", "topic": "cell membrane", "grades": [6, 7, 8], "terms": ["cell membrane", "lamad ng selula", "membrane", "balat ng selula", "pumapasok", "lumalabas", "panit sa selula", "gawasan", "sudlanan", "outer covering", "controls what enters"], "fact": {"tl": "Ang lamad ng selula (cell membrane) ang nakapalibot sa selula at kumokontrol kung ano ang pumapasok at lumalabas dito.", "en": "The cell membrane is the thin layer around a cell that controls what goes in and out of it.", "bis": "Ang cell membrane mao ang nipis nga panit nga naglibot sa selula ug nagkontrol kung unsa ang mosulod ug mogawas niini."}, "source": "AAAS Benchmarks 5C/H2a", "generator": "claude-workflow", "reviewed": false},
  {"id": "cell-nucleus-control-g6", "domain": "LIVING_THINGS", "topic": "nucleus is the cell's control center", "grades": [6, 7, 8], "terms": ["nucleus", "nukleus", "control center", "utak ng selula", "namumuno", "DNA", "instructions", "tigdumala", "sentro", "gitago ang DNA", "command center", "brain of the cell"], "fact": {"tl": "Ang nucleus ang parang utak o control center ng selula dahil dito nakatago ang DNA na nag-uutos sa gagawin ng selula.", "en": "The nucleus is like the brain or control center of the cell because it holds the DNA that directs what the cell does.", "bis": "Ang nucleus sama sa utok o control center sa selula tungod kay diha niini gitago ang DNA nga nagmando sa buhaton sa selula."}, "source": "AAAS Benchmarks 5C/H2a; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mitochondria-energy-g7", "domain": "LIVING_THINGS", "topic": "mitochondria release energy", "grades": [7, 8], "terms": ["mitochondria", "mitokondriya", "enerhiya", "energy", "powerhouse", "lakas", "pagkain", "sugar", "kusog", "asukal", "release energy", "power station"], "fact": {"tl": "Ang mitochondria ang bahagi ng selula na nagbubukas ng enerhiya mula sa pagkain para magamit ito ng selula.", "en": "The mitochondria are the cell parts that release energy from food so the cell can use it.", "bis": "Ang mitochondria mao ang bahin sa selula nga nagpagawas ug kusog gikan sa pagkaon aron magamit kini sa selula."}, "source": "AAAS Benchmarks 5C/H2a (oxidize sugar to release energy)", "generator": "claude-workflow", "reviewed": false},
  {"id": "plant-cell-wall-chloroplast-g7", "domain": "LIVING_THINGS", "topic": "plant cells have a cell wall and chloroplasts", "grades": [6, 7, 8], "terms": ["cell wall", "pader ng selula", "halaman", "plant cell", "chloroplast", "kloroplast", "berde", "luntian", "matigas na balat", "tanom", "lunhaw", "bungbong sa selula", "rigid wall", "green"], "fact": {"tl": "Ang mga selula ng halaman ay may matigas na cell wall at mga chloroplast na ginagamit nila para gumawa ng pagkain mula sa liwanag.", "en": "Plant cells have a stiff cell wall and chloroplasts, which they use to make food from light.", "bis": "Ang mga selula sa tanom adunay gahi nga cell wall ug mga chloroplast nga ilang gigamit aron maghimo ug pagkaon gikan sa kahayag."}, "source": "AAAS Benchmarks 5C/M1c; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cells-divide-growth-repair-g6", "domain": "LIVING_THINGS", "topic": "cells divide for growth and repair", "grades": [6, 7, 8], "terms": ["selula", "cell", "naghahati", "divide", "dumarami", "lumalaki", "sugat", "gumagaling", "growth", "repair", "nagbahin", "nagdaghan", "samad", "kaayohan", "cell division", "heal wound"], "fact": {"tl": "Ang mga selula ay naghahati para dumami—ito ang dahilan kung bakit tayo lumalaki at kung bakit gumagaling ang ating mga sugat.", "en": "Cells divide to make more cells, which is how we grow and how our wounds heal.", "bis": "Ang mga selula nagbahin aron modaghan—mao kini ang hinungdan nganong modako kita ug nganong maayo ang atong mga samad."}, "source": "AAAS Benchmarks 5C/M2a", "generator": "claude-workflow", "reviewed": false},
  {"id": "specialized-cells-g6", "domain": "LIVING_THINGS", "topic": "different cells do different jobs", "grades": [6, 7, 8], "terms": ["iba't ibang selula", "different cells", "muscle cell", "selula ng kalamnan", "nerve cell", "selula ng utak", "skin cell", "trabaho", "tungkulin", "lainlain nga selula", "buluhaton", "specialized cells", "cell types"], "fact": {"tl": "May iba't ibang uri ng selula sa katawan—gaya ng selula ng kalamnan, ng buto, at ng balat—at ang bawat isa ay may sariling tungkulin.", "en": "The body has different kinds of cells—like muscle cells, bone cells, and skin cells—and each kind has its own job.", "bis": "Ang lawas adunay lainlaing matang sa selula—sama sa selula sa kaunoran, sa bukog, ug sa panit—ug ang matag matang adunay kaugalingong buluhaton."}, "source": "AAAS Benchmarks 5C/M1b", "generator": "claude-workflow", "reviewed": false},
  {"id": "cells-mostly-water-g7", "domain": "LIVING_THINGS", "topic": "cells are mostly water", "grades": [7, 8], "terms": ["tubig", "water", "selula", "cell", "dalawang-katlo", "two thirds", "karamihan tubig", "tunaw", "kadaghanan tubig", "dako nga bahin", "mostly water", "water content"], "fact": {"tl": "Mga dalawang-katlo ng bigat ng isang selula ay tubig, kaya napakahalaga ng tubig para mabuhay ang mga selula natin.", "en": "About two-thirds of a cell's weight is water, which is why water is so important for keeping our cells alive.", "bis": "Mga dos-tersiya sa gibug-aton sa usa ka selula tubig, mao nga importante kaayo ang tubig aron mabuhi ang atong mga selula."}, "source": "AAAS Benchmarks 5C/M4", "generator": "claude-workflow", "reviewed": false},
  {"id": "all-cells-from-cells-g7", "domain": "LIVING_THINGS", "topic": "cells come from other cells", "grades": [7, 8], "terms": ["selula", "cell", "galing sa selula", "nanggagaling", "naghahati", "isang selula", "pinagmulan", "gikan sa selula", "nagbahin", "tinubdan", "cells from cells", "origin of cells"], "fact": {"tl": "Ang bawat bagong selula ay nanggagaling sa isa pang selula na naghati, kaya lahat ng selula natin ay galing sa unang selula nang tayo ay simula pa lang.", "en": "Every new cell comes from another cell that divided, so all of our cells trace back to the very first cell we started from.", "bis": "Ang matag bag-ong selula naggikan sa laing selula nga nagbahin, mao nga ang tanan natong selula naggikan sa unang selula nga atong gisugdan."}, "source": "AAAS Benchmarks 5C/H5; 5B/M2b; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dna-instructions-g6", "domain": "LIVING_THINGS", "topic": "DNA carries the instructions for life", "grades": [6, 7, 8], "terms": ["DNA", "instructions", "panuto", "blueprint", "code", "tagubilin", "selula", "nucleus", "mga utos", "panudlo", "instruction ng katawan", "genetic code", "recipe of life"], "fact": {"tl": "Ang DNA ay parang aklat ng panuto sa loob ng selula na nagsasabi kung paano buuin at patakbuhin ang isang nabubuhay na bagay.", "en": "DNA is like an instruction book inside the cell that tells how to build and run a living thing.", "bis": "Ang DNA sama sa libro sa panudlo sulod sa selula nga nagsulti kung unsaon paghimo ug pagpadagan sa usa ka buhing butang."}, "source": "AAAS Benchmarks 5B/H3; 5C/H4a", "generator": "claude-workflow", "reviewed": false},
  {"id": "dna-four-letters-g8", "domain": "LIVING_THINGS", "topic": "DNA is a code of four letters", "grades": [8, 9, 10], "terms": ["DNA", "apat na letra", "four letters", "A T C G", "code", "kowd", "haba", "kadena", "upat ka letra", "kodigo", "sunod-sunod", "genetic code", "base pairs", "sequence"], "fact": {"tl": "Ang DNA ay isang mahabang kadena na binubuo ng apat na klase ng maliliit na molekula, at ang pagkakasunod-sunod ng mga ito ang nagtatago ng impormasyon.", "en": "DNA is a long chain made of just four kinds of small molecules, and the order they are arranged in stores the information.", "bis": "Ang DNA usa ka taas nga kadena nga gibuhat gikan sa upat ra ka matang sa gagmayng molekula, ug ang han-ay niini maoy nagtago sa impormasyon."}, "source": "AAAS Benchmarks 5B/H3", "generator": "claude-workflow", "reviewed": false},
  {"id": "dna-shape-double-helix-g8", "domain": "LIVING_THINGS", "topic": "DNA double helix shape", "grades": [8, 9, 10], "terms": ["DNA", "double helix", "hagdan", "ladder", "pilipit", "spiral", "hugis", "korte", "namaluktot na hagdan", "porma", "twisted ladder", "spiral shape"], "fact": {"tl": "Ang DNA ay hugis na parang pilipit na hagdan na tinatawag na 'double helix.'", "en": "DNA has the shape of a twisted ladder called a 'double helix.'", "bis": "Ang DNA porma sama sa linubid nga hagdanan nga gitawag ug 'double helix.'"}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gene-segment-dna-g8", "domain": "LIVING_THINGS", "topic": "genes are segments of DNA", "grades": [8, 9, 10], "terms": ["gene", "gen", "bahagi ng DNA", "segment", "katangian", "trait", "kulay ng mata", "instruction", "bahin sa DNA", "kinaiya", "kolor sa mata", "unit of heredity", "controls trait"], "fact": {"tl": "Ang gene ay isang maliit na bahagi ng DNA na may tagubilin para sa isang partikular na katangian, gaya ng kulay ng iyong mata.", "en": "A gene is a small section of DNA that carries the instruction for one particular trait, like the color of your eyes.", "bis": "Ang gene usa ka gamayng bahin sa DNA nga nagdala sa panudlo alang sa usa ka piho nga kinaiya, sama sa kolor sa imong mata."}, "source": "AAAS Benchmarks 5B/H4", "generator": "claude-workflow", "reviewed": false},
  {"id": "chromosomes-package-dna-g8", "domain": "LIVING_THINGS", "topic": "chromosomes package DNA", "grades": [8, 9, 10], "terms": ["chromosome", "kromosoma", "DNA", "nakarolyo", "packaged", "nucleus", "46", "tao", "kromosom", "giputos", "nukleus", "human chromosomes", "coiled DNA"], "fact": {"tl": "Ang DNA ay nakarolyo nang maayos sa mga istrukturang tinatawag na chromosomes, at ang bawat selula ng tao ay may 46 nito.", "en": "DNA is neatly coiled into structures called chromosomes, and each human cell has 46 of them.", "bis": "Ang DNA giputos ug maayo sa mga istruktura nga gitawag ug chromosomes, ug ang matag selula sa tawo adunay 46 niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "offspring-resemble-parents-g4", "domain": "LIVING_THINGS", "topic": "children resemble their parents", "grades": [3, 4, 5], "terms": ["mukha", "kamukha", "magulang", "anak", "resemble", "kahawig", "katulad", "namana", "parehas ang nawong", "ginikanan", "managsama", "look like parents", "family resemblance"], "fact": {"tl": "Ang mga anak ay madalas kahawig ng kanilang mga magulang dahil minamana nila ang ilang katangian mula sa kanila.", "en": "Children often look like their parents because they inherit some of their traits from them.", "bis": "Ang mga anak kasagaran managsama sa ilang ginikanan tungod kay napanunod nila ang pipila ka kinaiya gikan kanila."}, "source": "AAAS Benchmarks 5B/P2, 5B/E1", "generator": "claude-workflow", "reviewed": false},
  {"id": "inherited-vs-learned-g5", "domain": "LIVING_THINGS", "topic": "inherited traits vs learned traits", "grades": [4, 5, 6], "terms": ["namana", "inherited", "natutuhan", "learned", "kulay ng mata", "wika", "katangian", "natutunan", "napanunod", "natun-an", "pinulongan", "inborn vs learned", "trait"], "fact": {"tl": "May mga katangiang namana natin gaya ng kulay ng mata, at may mga natutuhan lang natin gaya ng pagsasalita ng isang wika.", "en": "Some traits we inherit, like eye color, while others we only learn, like speaking a language.", "bis": "Adunay mga kinaiya nga atong napanunod sama sa kolor sa mata, ug adunay uban nga atong natun-an lamang sama sa pagsulti ug usa ka pinulongan."}, "source": "AAAS Benchmarks 5B/E1", "generator": "claude-workflow", "reviewed": false},
  {"id": "half-genes-each-parent-g7", "domain": "LIVING_THINGS", "topic": "half of genes come from each parent", "grades": [7, 8], "terms": ["kalahati", "half", "gene", "magulang", "nanay", "tatay", "ina", "ama", "namana", "katunga", "inahan", "amahan", "from each parent", "mix of traits"], "fact": {"tl": "Sa mga hayop at tao, kalahati ng mga gene ng anak ay galing sa ina at kalahati ay galing sa ama.", "en": "In animals and people, half of a child's genes come from the mother and half come from the father.", "bis": "Sa mga hayop ug tao, katunga sa mga gene sa anak naggikan sa inahan ug katunga naggikan sa amahan."}, "source": "AAAS Benchmarks 5B/M1b", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-siblings-differ-g6", "domain": "LIVING_THINGS", "topic": "why siblings are not identical", "grades": [5, 6, 7], "terms": ["magkapatid", "siblings", "magkaiba", "differ", "hindi pareho", "kumbinasyon", "gene", "managsoon", "lahi", "nagkalainlain", "combination", "different mix", "not identical"], "fact": {"tl": "Magkakapatid ay magkakaiba kahit pareho ang magulang dahil bawat isa ay nakakakuha ng ibang kumbinasyon ng mga gene.", "en": "Brothers and sisters look different even with the same parents because each one gets a different mix of genes.", "bis": "Ang managsoon magkalahi bisan pareho ang ginikanan tungod kay ang matag usa nakakuha ug lahi nga sagol sa mga gene."}, "source": "AAAS Benchmarks 5B/H2; 5B/P2", "generator": "claude-workflow", "reviewed": false},
  {"id": "dominant-recessive-traits-g8", "domain": "LIVING_THINGS", "topic": "dominant and recessive traits", "grades": [8, 9, 10], "terms": ["dominant", "recessive", "dominante", "nakatago", "katangian", "trait", "nananaig", "nagtatago", "gene", "nagpatigbabaw", "tinago", "dominanteng kinaiya", "stronger trait", "hidden trait"], "fact": {"tl": "May mga katangiang dominant na lumalabas kahit isang gene lang ang nagdadala nito, at may recessive na nagtatago at lumalabas lang kapag dalawang gene ang magkapareho.", "en": "Some traits are dominant and show up even with one gene, while others are recessive and only appear when both genes match.", "bis": "Adunay mga kinaiya nga dominant nga mogawas bisan usa ra ka gene, ug adunay recessive nga magtago ug mogawas lang kung pareho ang duha ka gene."}, "source": "encyclopedia-stable consensus (Mendelian genetics)", "generator": "claude-workflow", "reviewed": false},
  {"id": "mendel-pea-plants-g8", "domain": "LIVING_THINGS", "topic": "Gregor Mendel and pea plants", "grades": [8, 9, 10], "terms": ["Gregor Mendel", "Mendel", "gisantes", "pea plant", "heredity", "pagmamana", "tatay ng genetics", "father of genetics", "patani", "panunod", "amahan sa genetics", "monk", "pea experiments"], "fact": {"tl": "Si Gregor Mendel ay nag-aral ng mga halaman ng gisantes at natuklasan niya kung paano naipapasa ang mga katangian, kaya tinawag siyang 'ama ng genetics.'", "en": "Gregor Mendel studied pea plants and discovered how traits are passed on, which is why he is called the 'father of genetics.'", "bis": "Si Gregor Mendel nagtuon sa mga tanom nga gisantes ug nadiskobrehan niya kung unsaon pagpasa sa mga kinaiya, mao nga gitawag siya nga 'amahan sa genetics.'"}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "watson-crick-franklin-dna-g9", "domain": "LIVING_THINGS", "topic": "discovery of DNA structure", "grades": [9, 10], "terms": ["Watson", "Crick", "Rosalind Franklin", "Franklin", "DNA structure", "hugis ng DNA", "natuklasan", "double helix", "nadiskobrehan", "porma sa DNA", "x-ray", "discovered DNA shape"], "fact": {"tl": "Natuklasan nina James Watson at Francis Crick ang hugis ng DNA noong 1953, gamit ang mahalagang larawang x-ray ni Rosalind Franklin.", "en": "James Watson and Francis Crick discovered the shape of DNA in 1953, using an important X-ray image taken by Rosalind Franklin.", "bis": "Nadiskobrehan nila James Watson ug Francis Crick ang porma sa DNA niadtong 1953, gamit ang importanteng x-ray nga litrato ni Rosalind Franklin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mutation-change-in-dna-g8", "domain": "LIVING_THINGS", "topic": "mutations are changes in DNA", "grades": [8, 9, 10], "terms": ["mutation", "mutasyon", "pagbabago", "DNA", "gene", "pagkakamali", "nabago", "kausaban", "sayop", "nausab nga gene", "change in DNA", "genetic change"], "fact": {"tl": "Ang mutation ay isang pagbabago sa DNA, at maaari itong walang epekto, makatulong, o makasama sa nabubuhay na bagay.", "en": "A mutation is a change in the DNA, and it can have no effect, help, or harm the living thing.", "bis": "Ang mutation usa ka kausaban sa DNA, ug mahimo kining walay epekto, makatabang, o makadaot sa buhing butang."}, "source": "AAAS Benchmarks 5B/H4", "generator": "claude-workflow", "reviewed": false},
  {"id": "mutation-causes-g9", "domain": "LIVING_THINGS", "topic": "what causes mutations", "grades": [9, 10], "terms": ["mutation", "mutasyon", "radiation", "radyasyon", "kemikal", "chemical", "sanhi", "dahilan", "hinungdan", "sun rays", "causes of mutation", "UV"], "fact": {"tl": "Maaaring magkaroon ng mutation dahil sa mga bagay gaya ng radiation at ilang kemikal na nakakapinsala sa DNA.", "en": "Mutations can be caused by things like radiation and certain chemicals that damage DNA.", "bis": "Ang mutation mahimong mahitabo tungod sa mga butang sama sa radiation ug pipila ka kemikal nga makadaot sa DNA."}, "source": "AAAS Benchmarks 5B/H5", "generator": "claude-workflow", "reviewed": false},
  {"id": "mutation-passed-to-offspring-g9", "domain": "LIVING_THINGS", "topic": "mutations in sex cells pass to offspring", "grades": [9, 10], "terms": ["mutation", "mutasyon", "namamana", "sex cells", "selula ng pagpaparami", "anak", "naipapasa", "napanunod", "selula sa pagpadaghan", "kaliwatan", "inherited mutation", "passed to children"], "fact": {"tl": "Kapag nangyari ang mutation sa mga selulang pang-reproduksyon, maaari itong maipasa sa mga anak; kung sa ibang selula naman, hindi ito namamana.", "en": "If a mutation happens in reproductive cells, it can be passed to offspring; but if it happens in other cells, it is not inherited.", "bis": "Kung ang mutation mahitabo sa mga selula sa pagpadaghan, mahimo kining ipasa sa mga anak; apan kung sa ubang selula, dili kini mapanunod."}, "source": "AAAS Benchmarks 5B/H5", "generator": "claude-workflow", "reviewed": false},
  {"id": "mutation-source-of-variety-g9", "domain": "LIVING_THINGS", "topic": "mutations create variety in living things", "grades": [9, 10], "terms": ["mutation", "mutasyon", "pagkakaiba", "variety", "bago", "katangian", "ebolusyon", "evolution", "kausaban", "bag-ong kinaiya", "lainlain", "source of variation", "new traits"], "fact": {"tl": "Ang mga mutation ay isa sa mga pinagmumulan ng pagkakaiba-iba sa mga nabubuhay, at sa paglipas ng panahon ay maaari itong magbunga ng mga bagong katangian.", "en": "Mutations are one source of the variety among living things, and over time they can lead to new traits.", "bis": "Ang mga mutation usa sa mga tinubdan sa kalainlain sa mga buhing butang, ug sa paglabay sa panahon mahimo kining mosangpot ug bag-ong mga kinaiya."}, "source": "AAAS Benchmarks 5B/H1, 5B/H4", "generator": "claude-workflow", "reviewed": false},
  {"id": "selective-breeding-g7", "domain": "LIVING_THINGS", "topic": "selective breeding of plants and animals", "grades": [7, 8], "terms": ["selective breeding", "pinili", "pagpaparami", "aso", "breed", "pananim", "katangian", "bagong klase", "gipili", "pagpadaghan", "iro", "bag-ong klase", "bred for traits", "domestication"], "fact": {"tl": "Sa pamamagitan ng pagpili kung aling mga halaman o hayop ang pagpaparamihin, nakagawa ang tao ng mga bagong uri na may katangiang gusto nila, gaya ng iba't ibang lahi ng aso.", "en": "By choosing which plants or animals to breed, people have created new kinds with traits they want, like the many breeds of dogs.", "bis": "Pinaagi sa pagpili kung unsang mga tanom o hayop ang padaghanon, ang tawo nakahimo ug bag-ong matang nga adunay kinaiya nga ilang gusto, sama sa daghang lahi sa iro."}, "source": "AAAS Benchmarks 5B/M3", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-pyramid-ten-percent-g7", "domain": "LIVING_THINGS", "topic": "energy pyramid ten percent rule", "grades": [7, 8], "terms": ["enerhiya", "sampung porsiyento", "10%", "pyramid ng enerhiya", "nawawalang enerhiya", "init", "trophic level", "energy pyramid", "kusog", "enerhiya nawala", "gamay ra nga enerhiya", "mokaon", "each level", "mas gamay", "mas kaunti"], "fact": {"tl": "Sa bawat hakbang ng food chain, tinatayang 10% lang ng enerhiya ang naipapasa sa susunod na hayop — ang iba ay nawawala bilang init, kaya kakaunti lang ang malalaking mandaragit sa tuktok.", "en": "At each step of a food chain only about 10% of the energy passes to the next animal — the rest is lost as heat, which is why there are few big predators at the top.", "bis": "Sa matag ang-ang sa food chain, mga 10% lang sa enerhiya ang mabalhin ngadto sa sunod nga hayop — ang uban mawala isip init, mao nga gamay ra ang dagkong mananap sa taas."}, "source": "AAAS 5E/H3; NRC LS2.B energy flow", "generator": "claude-workflow", "reviewed": false},
  {"id": "producers-base-of-food-chain-g5", "domain": "LIVING_THINGS", "topic": "producers make their own food", "grades": [5, 6], "terms": ["prodyuser", "producer", "halaman", "gumagawa ng sariling pagkain", "tanom", "mohimo og kaugalingong pagkaon", "saligan sa food chain", "araw", "adlaw", "sinugdanan", "base ng food chain", "green plants", "luntiang halaman"], "fact": {"tl": "Ang mga prodyuser tulad ng halaman at algae ang nasa simula ng bawat food chain dahil sila lang ang gumagawa ng sariling pagkain mula sa liwanag ng araw.", "en": "Producers like plants and algae are at the start of every food chain because only they can make their own food from sunlight.", "bis": "Ang mga producer sama sa tanom ug algae ang anaa sa sinugdanan sa matag food chain kay sila ra ang makahimo og kaugalingong pagkaon gikan sa kahayag sa adlaw."}, "source": "AAAS 5D/M4; NRC LS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "herbivore-carnivore-omnivore-g4", "domain": "LIVING_THINGS", "topic": "herbivore carnivore omnivore", "grades": [4, 5], "terms": ["herbivore", "carnivore", "omnivore", "kumakain ng halaman", "kumakain ng karne", "kumakain ng dalawa", "mokaon og tanom", "mokaon og karne", "tanom-kaon", "karne-kaon", "plant eater", "meat eater", "baboy", "kambing", "leon"], "fact": {"tl": "Ang herbivore ay kumakain lang ng halaman, ang carnivore ay kumakain ng ibang hayop, at ang omnivore ay kumakain ng halaman at hayop tulad ng tao at baboy.", "en": "A herbivore eats only plants, a carnivore eats other animals, and an omnivore eats both plants and animals — like humans and pigs.", "bis": "Ang herbivore mokaon lang og tanom, ang carnivore mokaon og ubang mananap, ug ang omnivore mokaon og tanom ug mananap sama sa tawo ug baboy."}, "source": "encyclopedia-stable consensus; AAAS 5D/M2", "generator": "claude-workflow", "reviewed": false},
  {"id": "decomposers-recycle-nutrients-g6", "domain": "LIVING_THINGS", "topic": "decomposers recycle matter", "grades": [6, 7], "terms": ["dekompiser", "decomposer", "fungi", "bacteria", "nabubulok", "nadunot", "nutrients", "sustansya", "nagbabalik sa lupa", "nadugta", "mobalik sa yuta", "sustansiya", "recycle", "pag-recycle", "kabag-o", "kuhol", "uod"], "fact": {"tl": "Kung walang dekompiser na nagbabalik ng sustansya sa lupa, mauubos ang nutrients at hindi na makakatubo ang mga halaman — kaya sila ang tagapag-recycle ng kalikasan.", "en": "Without decomposers returning nutrients to the soil, nutrients would run out and plants could not grow — so they are nature's recyclers.", "bis": "Kung walay decomposer nga mobalik sa sustansiya sa yuta, mahurot ang nutrients ug dili na makatubo ang mga tanom — mao nga sila ang tig-recycle sa kinaiyahan."}, "source": "AAAS 5A/M5; NRC LS2.B matter cycling", "generator": "claude-workflow", "reviewed": false},
  {"id": "scavengers-clean-ecosystem-g5", "domain": "LIVING_THINGS", "topic": "scavengers eat dead animals", "grades": [5, 6], "terms": ["scavenger", "mga kumakain ng patay", "bangkay", "langaw", "uwak", "buwitre", "mokaon og patay", "mananap nga patay", "tig-limpyo", "naglilinis", "crab", "alimango", "dead animals", "carrion"], "fact": {"tl": "Ang mga scavenger tulad ng uwak at alimango ay kumakain ng bangkay ng patay na hayop, kaya tumutulong silang linisin ang ecosystem.", "en": "Scavengers like crows and crabs eat the bodies of dead animals, helping to clean up the ecosystem.", "bis": "Ang mga scavenger sama sa uwak ug alimango mokaon sa lawas sa patay nga mga hayop, busa motabang sila paglimpyo sa ecosystem."}, "source": "AAAS 5D/M2 (scavenge relationship)", "generator": "claude-workflow", "reviewed": false},
  {"id": "habitat-vs-niche-g6", "domain": "LIVING_THINGS", "topic": "habitat and niche", "grades": [6, 7], "terms": ["habitat", "tirahan", "niche", "papel", "trabaho sa kalikasan", "puluy-anan", "tahanan", "role", "lugar na tinitirhan", "gimbuhat", "pinuy-anan", "where it lives", "kung ano ginagawa"], "fact": {"tl": "Ang habitat ay ang lugar na tinitirhan ng isang hayop, samantalang ang niche ay ang papel o trabaho nito sa ecosystem tulad ng kung ano ang kinakain nito.", "en": "A habitat is the place where an animal lives, while its niche is the role or job it plays in the ecosystem, like what it eats.", "bis": "Ang habitat mao ang dapit nga gipuy-an sa usa ka hayop, samtang ang niche mao ang papel o trabaho niini sa ecosystem sama sa unsa ang gikaon niini."}, "source": "NRC LS2.A interdependent relationships", "generator": "claude-workflow", "reviewed": false},
  {"id": "keystone-species-g8", "domain": "LIVING_THINGS", "topic": "keystone species", "grades": [8, 9], "terms": ["keystone species", "mahalagang species", "susing species", "kung mawala", "mabago ang buong ecosystem", "importante kaayo", "kung mawagtang", "sea otter", "pating", "tuko sa ecosystem", "holds together", "balanse"], "fact": {"tl": "Ang keystone species ay isang species na napakahalaga kaya kung mawala ito, malaki ang magbabago sa buong ecosystem, tulad ng pating sa karagatan.", "en": "A keystone species is one so important that if it disappears the whole ecosystem changes dramatically, like sharks in the ocean.", "bis": "Ang keystone species mao ang usa ka species nga importante kaayo mao nga kung mawala kini, dako ang mabag-o sa tibuok ecosystem, sama sa iho sa dagat."}, "source": "encyclopedia-stable consensus; NRC LS2.C ecosystem stability", "generator": "claude-workflow", "reviewed": false},
  {"id": "apex-predator-top-food-chain-g6", "domain": "LIVING_THINGS", "topic": "apex predator top of food chain", "grades": [6, 7], "terms": ["apex predator", "pangunahing mandaragit", "tuktok ng food chain", "walang kumakain", "agila", "leon", "pinakataas", "walay mokaon niini", "mananap nga labaw", "top predator", "punoan sa food chain", "haring ibon"], "fact": {"tl": "Ang apex predator ay ang nasa pinakatuktok ng food chain na walang ibang hayop na kumakain dito, tulad ng Philippine Eagle sa ating kagubatan.", "en": "An apex predator sits at the very top of the food chain with no other animal hunting it, like the Philippine Eagle in our forests.", "bis": "Ang apex predator anaa sa kinatas-ang bahin sa food chain nga walay laing mananap nga mokaon niini, sama sa Philippine Eagle sa atong kalasangan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rainforest-biome-layers-g6", "domain": "LIVING_THINGS", "topic": "tropical rainforest biome", "grades": [6, 7], "terms": ["rainforest", "gubat", "kagubatan", "tropikal", "maulan", "canopy", "kapal ng dahon", "lasang", "ulanon", "biome", "mainit at basa", "mga ibabaw na sanga", "most species", "pinakamaraming hayop", "Palawan"], "fact": {"tl": "Ang tropical rainforest ay mainit at maulan buong taon, at kahit maliit lang ang lupang sakop nito, dito nakatira ang pinakamaraming uri ng halaman at hayop sa mundo.", "en": "A tropical rainforest is hot and rainy all year, and though it covers little land, it is home to more kinds of plants and animals than any other place on Earth.", "bis": "Ang tropical rainforest init ug ulanon sa tibuok tuig, ug bisan gamay ra ang yuta nga gisakpan niini, dinhi nagpuyo ang pinakadaghang matang sa tanom ug hayop sa kalibotan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "desert-biome-adaptation-g6", "domain": "LIVING_THINGS", "topic": "desert biome", "grades": [6, 7], "terms": ["desert", "disyerto", "tuyot", "kaunting ulan", "cactus", "kamelyo", "nag-iimbak ng tubig", "init", "mamala", "gamay og ulan", "nagtipig og tubig", "dry", "mainit araw malamig gabi", "adaptation", "pag-angkop"], "fact": {"tl": "Sa disyerto na halos walang ulan, ang mga halaman tulad ng cactus ay nag-iimbak ng tubig sa katawan nito para mabuhay sa matinding init.", "en": "In a desert where almost no rain falls, plants like cacti store water in their bodies to survive the intense heat.", "bis": "Sa disyerto nga halos walay ulan, ang mga tanom sama sa cactus magtipig og tubig sa lawas niini aron mabuhi sa hilabihang init."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "grassland-biome-grazers-g6", "domain": "LIVING_THINGS", "topic": "grassland biome", "grades": [6, 7], "terms": ["grassland", "damuhan", "sabana", "kapatagan ng damo", "kalabaw", "grazers", "kumakain ng damo", "kabukiran", "kasagbutan", "mosabsab", "mananap nga mokaon og sagbot", "savanna", "malawak na damo", "kambing"], "fact": {"tl": "Ang grassland ay malawak na lupang puno ng damo na may kaunting puno, at tahanan ito ng mga hayop na kumakain ng damo tulad ng kalabaw at usa.", "en": "A grassland is a wide land covered with grasses and few trees, home to grazing animals like buffalo and deer.", "bis": "Ang grassland mao ang lapad nga yuta nga puno sa sagbot ug pipila ra ka kahoy, puluy-anan kini sa mga mananap nga mosabsab sama sa kabaw ug usa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "coral-reef-rainforest-of-sea-g6", "domain": "LIVING_THINGS", "topic": "coral reef biodiversity", "grades": [6, 7], "terms": ["coral reef", "bahura", "gubat ng dagat", "rainforest of the sea", "maraming isda", "biodiversity", "puno ng buhay", "daghan og isda", "kabahuran", "kinabuhi sa dagat", "sea biodiversity", "Tubbataha", "most diverse"], "fact": {"tl": "Tinatawag na 'rainforest ng dagat' ang coral reef dahil bagaman maliit lang na bahagi ng karagatan ang sakop nito, dito nakatira ang napakaraming uri ng isda at hayop-dagat.", "en": "Coral reefs are called the 'rainforests of the sea' because although they cover only a small part of the ocean, a huge variety of fish and sea life lives there.", "bis": "Gitawag nga 'rainforest sa dagat' ang coral reef kay bisan gamay ra nga bahin sa kadagatan ang gisakpan niini, dinhi nagpuyo ang daghan kaayong matang sa isda ug kinabuhi sa dagat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "coral-bleaching-warming-g7", "domain": "LIVING_THINGS", "topic": "coral bleaching", "grades": [7, 8], "terms": ["coral bleaching", "namumuti ang coral", "namuti ang bahura", "mainit na tubig", "pag-init ng dagat", "algae", "umaalis ang algae", "namatay", "nanguti", "init sa dagat", "white coral", "global warming", "pagputi"], "fact": {"tl": "Kapag uminit nang labis ang tubig-dagat, inaalis ng coral ang mga maliit na algae na nagbibigay ng kulay at pagkain dito, kaya namumuti ito at maaaring mamatay — tinatawag itong coral bleaching.", "en": "When seawater gets too warm, coral expels the tiny algae that give it color and food, so it turns white and can die — this is called coral bleaching.", "bis": "Kung mainit kaayo ang tubig-dagat, papahawaon sa coral ang gagmayng algae nga naghatag og kolor ug pagkaon niini, busa moputi kini ug mahimong mamatay — gitawag kini nga coral bleaching."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mangrove-fish-nursery-g6", "domain": "LIVING_THINGS", "topic": "mangrove nursery for fish", "grades": [6, 7], "terms": ["mangrove", "bakawan", "nursery ng isda", "tagong lugar ng isda", "pinaglalakihan ng isda", "ugat", "gamot", "puluy-anan sa gagmayng isda", "tagoanan", "fish nursery", "baby fish", "tinitirhan ng tilapia", "bakhaw"], "fact": {"tl": "Ang magulong ugat ng bakawan ay nagiging ligtas na taguan kung saan lumalaki ang maliliit na isda at hipon bago lumabas sa malawak na dagat.", "en": "The tangled roots of mangroves form a safe nursery where young fish and shrimp grow before heading out to the open sea.", "bis": "Ang nagkagubot nga gamot sa bakhaw mahimong luwas nga tagoanan diin modako ang gagmayng isda ug pasayan sa dili pa mogawas sa lapad nga dagat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "symbiosis-mutualism-g7", "domain": "LIVING_THINGS", "topic": "mutualism symbiosis", "grades": [7, 8], "terms": ["mutualism", "symbiosis", "tulungan", "parehong nakikinabang", "bubuyog", "bulaklak", "clownfish", "anemone", "magkatabang", "silang duha makabenepisyo", "both benefit", "simbyosis", "magkaibigan sa kalikasan", "pollination"], "fact": {"tl": "Sa mutualism, dalawang magkaibang species ang tumutulong sa isa't isa, tulad ng clownfish na nagtatago sa sea anemone habang pinoprotektahan nito ang anemone.", "en": "In mutualism, two different species help each other, like the clownfish that hides in a sea anemone while protecting the anemone in return.", "bis": "Sa mutualism, duha ka lainlaing species ang magtinabangay, sama sa clownfish nga magtago sa sea anemone samtang gipanalipdan niini ang anemone."}, "source": "AAAS 5D/M2 mutually beneficial relationships", "generator": "claude-workflow", "reviewed": false},
  {"id": "symbiosis-parasitism-g7", "domain": "LIVING_THINGS", "topic": "parasitism", "grades": [7, 8], "terms": ["parasitism", "parasite", "parasito", "host", "napipinsala", "kumakapit", "garapata", "bulate", "lintaw", "makadaot sa host", "nakapuyo sa lain", "one harmed", "sumisipsip", "tik", "leeches"], "fact": {"tl": "Sa parasitism, ang parasito tulad ng garapata ay nabubuhay sa katawan ng ibang hayop (host) at sumisipsip ng dugo nito, kaya napipinsala ang host.", "en": "In parasitism, a parasite like a tick lives on another animal (the host) and feeds on it, harming the host.", "bis": "Sa parasitism, ang parasite sama sa garapata mopuyo sa lawas sa laing mananap (host) ug mosuyop sa dugo niini, busa madaot ang host."}, "source": "AAAS 5D/M2 parasite/host relationship", "generator": "claude-workflow", "reviewed": false},
  {"id": "competition-for-resources-g6", "domain": "LIVING_THINGS", "topic": "competition in ecosystems", "grades": [6, 7], "terms": ["kompetisyon", "competition", "pag-aagawan", "tubig", "pagkain", "tirahan", "espasyo", "limitado", "kakulangan", "indigay", "panag-indigay", "nag-away para sa pagkaon", "resources", "kapos na pagkain", "survival"], "fact": {"tl": "Kapag kulang ang pagkain, tubig, o espasyo, nag-aagawan ang mga hayop na may parehong pangangailangan, at ang mas malakas o mabilis ay mas malamang na mabuhay.", "en": "When food, water, or space is scarce, animals with the same needs compete for it, and the stronger or faster ones are more likely to survive.", "bis": "Kung kulang ang pagkaon, tubig, o luna, mag-indigay ang mga mananap nga managsama og panginahanglan, ug ang mas kusgan o paspas mas lagmit mabuhi."}, "source": "AAAS 5D/M1 competition for resources", "generator": "claude-workflow", "reviewed": false},
  {"id": "matter-cycles-energy-flows-g8", "domain": "LIVING_THINGS", "topic": "matter cycles energy flows one way", "grades": [8, 9], "terms": ["matter cycles", "umiikot ang matter", "enerhiya dumadaloy", "one-way", "nag-iikot ang materya", "molekula", "atomo", "muliko ang materya", "enerhiya magdagan", "recycled", "hindi naluluto enerhiya", "gigamit balik", "carbon", "cycle of matter"], "fact": {"tl": "Sa ecosystem, ang materya tulad ng carbon ay paulit-ulit na umiikot mula halaman hanggang hayop hanggang lupa, ngunit ang enerhiya ay dumadaloy lang nang minsan at unti-unting nawawala bilang init.", "en": "In an ecosystem, matter like carbon cycles round and round from plants to animals to soil, but energy flows only one way and is gradually lost as heat.", "bis": "Sa ecosystem, ang materya sama sa carbon magtuyok-tuyok gikan sa tanom ngadto sa hayop ngadto sa yuta, apan ang enerhiya magdagayday lang og kausa ug hinay-hinay nga mawala isip init."}, "source": "AAAS 5E/H3; NRC LS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "trophic-levels-feeding-g7", "domain": "LIVING_THINGS", "topic": "trophic levels", "grades": [7, 8], "terms": ["trophic level", "antas ng pagkain", "unang antas", "pangalawang antas", "primary consumer", "secondary consumer", "ang-ang sa pagkaon", "han-ay sa pagkaon", "feeding level", "first level", "mga antas", "level ng food chain"], "fact": {"tl": "Ang bawat antas ng pagkain sa food chain ay tinatawag na trophic level: ang halaman ang unang antas, ang kumakain ng halaman ang pangalawa, at ang kumakain ng hayop ang pangatlo.", "en": "Each feeding level in a food chain is called a trophic level: plants are the first level, plant-eaters the second, and animal-eaters the third.", "bis": "Ang matag ang-ang sa pagkaon sa food chain gitawag og trophic level: ang tanom mao ang unang ang-ang, ang mokaon og tanom mao ang ikaduha, ug ang mokaon og hayop mao ang ikatulo."}, "source": "NRC LS2.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "food-web-collapse-g7", "domain": "LIVING_THINGS", "topic": "removing a species affects food web", "grades": [7, 8], "terms": ["food web", "kawing ng pagkain", "kung mawala ang isa", "apektado lahat", "nasisira ang web", "domino", "kadena", "kung mawagtang ang usa", "maapektuhan tanan", "connected", "magkaugnay", "balanse", "ripple effect"], "fact": {"tl": "Dahil magkaugnay ang lahat sa isang food web, kapag nawala ang isang species ay maaaring magkaroon ng kakulangan o sobra sa iba, na nakaapekto sa buong ecosystem.", "en": "Because everything in a food web is connected, removing one species can cause shortages or overgrowth in others, affecting the whole ecosystem.", "bis": "Tungod kay magkadugtong ang tanan sa usa ka food web, kung mawala ang usa ka species mahimong adunay kakulang o sobra sa uban, nga makaapekto sa tibuok ecosystem."}, "source": "NRC LS2.C ecosystem dynamics; AAAS 5D", "generator": "claude-workflow", "reviewed": false},
  {"id": "endemic-species-philippines-g7", "domain": "LIVING_THINGS", "topic": "endemic species Philippines", "grades": [7, 8], "terms": ["endemic", "endemiko", "tanging matatagpuan", "dito lang sa Pilipinas", "tarsier", "tamaraw", "dito lang makita", "talagsaon", "mao ra makita sa Pilipinas", "found only here", "unique sa Pilipinas", "native species", "Philippine Eagle"], "fact": {"tl": "Ang endemic na species tulad ng tarsier at tamaraw ay matatagpuan lamang sa Pilipinas at wala nang ibang bansa, kaya napakahalaga nilang protektahan.", "en": "Endemic species like the tarsier and tamaraw are found only in the Philippines and nowhere else, so protecting them is very important.", "bis": "Ang endemic nga species sama sa tarsier ug tamaraw makita lamang sa Pilipinas ug wala na sa laing nasod, busa importante kaayo nga panalipdan sila."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "invasive-species-harm-g8", "domain": "LIVING_THINGS", "topic": "invasive species", "grades": [8, 9], "terms": ["invasive species", "dayuhang species", "nakakasamang species", "janitor fish", "golden kuhol", "walang kalaban", "kumakalat", "langyaw nga species", "makadaot nga species", "mikaylap", "sobrang dami", "outcompete", "sumisira sa katutubo"], "fact": {"tl": "Ang invasive species tulad ng janitor fish ay galing sa ibang lugar at mabilis kumalat dahil walang natural na kalaban dito, kaya napipinsala nito ang mga katutubong hayop.", "en": "An invasive species like the janitor fish comes from elsewhere and spreads fast because it has no natural enemies here, harming native animals.", "bis": "Ang invasive species sama sa janitor fish naggikan sa laing dapit ug paspas mokaylap kay walay natural nga kaaway dinhi, busa makadaot kini sa lumad nga mga mananap."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "plankton-base-ocean-foodweb-g6", "domain": "LIVING_THINGS", "topic": "plankton base of ocean food web", "grades": [6, 7], "terms": ["plankton", "phytoplankton", "maliliit na halaman sa dagat", "pagkain ng isda", "saligan ng food web", "ginikanan sa pagkaon sa dagat", "gagmayng tanom sa dagat", "microscopic", "base of ocean", "oxygen sa dagat", "pinakamaliit"], "fact": {"tl": "Ang phytoplankton ay napakaliliit na halaman na lumulutang sa dagat, at sila ang nasa simula ng food web sa karagatan dahil sila ang pinakapangunahing pagkain.", "en": "Phytoplankton are tiny plant-like organisms floating in the sea, and they are at the base of the ocean food web as the most basic food.", "bis": "Ang phytoplankton mao ang gagmay kaayong tanom-tanom nga naglutaw sa dagat, ug sila ang anaa sa sinugdanan sa food web sa kadagatan isip kinaubsang pagkaon."}, "source": "AAAS 5A/M5 ocean food web", "generator": "claude-workflow", "reviewed": false},
  {"id": "biome-definition-g7", "domain": "LIVING_THINGS", "topic": "what is a biome", "grades": [7, 8], "terms": ["biome", "malaking ecosystem", "klima", "uri ng halaman", "desert tundra rainforest", "dako nga ecosystem", "klase sa tanom", "panahon", "large region", "grupo ng ecosystem", "tundra", "biomes", "malawak na rehiyon"], "fact": {"tl": "Ang biome ay isang napakalawak na rehiyon na may partikular na klima at uri ng halaman at hayop, tulad ng disyerto, rainforest, at tundra.", "en": "A biome is a very large region with a particular climate and characteristic plants and animals, such as desert, rainforest, and tundra.", "bis": "Ang biome mao ang lapad kaayong rehiyon nga adunay piho nga klima ug kinaiya nga mga tanom ug hayop, sama sa disyerto, rainforest, ug tundra."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "population-and-community-g6", "domain": "LIVING_THINGS", "topic": "population and community", "grades": [6, 7], "terms": ["population", "populasyon", "community", "pamayanan", "grupo ng parehong species", "lahat ng buhay na magkasama", "pundok sa managsamang species", "komunidad", "tanang buhi nga nagpuyo", "grupo", "sama-samang species", "group of same kind"], "fact": {"tl": "Ang populasyon ay lahat ng iisang uri ng organismo sa isang lugar, samantalang ang komunidad ay lahat ng magkakaibang populasyon na magkakasamang nabubuhay doon.", "en": "A population is all the organisms of one kind in a place, while a community is all the different populations living together there.", "bis": "Ang populasyon mao ang tanang usa ka matang sa organismo sa usa ka dapit, samtang ang komunidad mao ang tanang lainlaing populasyon nga nagpuyo og dungan didto."}, "source": "NRC LS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sunlight-source-of-all-food-g5", "domain": "LIVING_THINGS", "topic": "sun powers ecosystems", "grades": [5, 6], "terms": ["araw", "adlaw", "pinagmulan ng enerhiya", "sun", "liwanag", "lahat ng pagkain galing sa araw", "tanang pagkaon gikan sa adlaw", "sinugdanan sa enerhiya", "kahayag", "energy source", "saligan ng buhay", "powers life"], "fact": {"tl": "Halos lahat ng enerhiya sa isang ecosystem ay nagmumula sa araw, dahil ginagamit ng halaman ang liwanag nito para gumawa ng pagkaing pinagmumulan ng lakas ng lahat ng hayop.", "en": "Almost all the energy in an ecosystem comes from the sun, because plants use its light to make the food that powers every animal.", "bis": "Halos tanang enerhiya sa usa ka ecosystem naggikan sa adlaw, kay gamiton sa tanom ang kahayag niini aron mohimo og pagkaon nga maoy gigikanan sa kusog sa tanang mananap."}, "source": "AAAS 5E/H3; NRC LS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "mangrove-carbon-storage-g8", "domain": "LIVING_THINGS", "topic": "mangroves store carbon", "grades": [8, 9], "terms": ["mangrove", "bakawan", "nag-iimbak ng carbon", "carbon", "climate change", "tumutulong sa klima", "nagtipig og carbon", "bakhaw", "tabang sa klima", "blue carbon", "sumisipsip ng carbon dioxide", "nagbabawas ng init"], "fact": {"tl": "Ang mga bakawan ay mahusay sa pag-iimbak ng carbon sa kanilang putik at ugat, kaya nakakatulong sila laban sa climate change.", "en": "Mangroves are excellent at storing carbon in their mud and roots, so they help fight climate change.", "bis": "Ang mga bakhaw maayo kaayo sa pagtipig og carbon sa ilang lapok ug gamot, busa motabang sila batok sa climate change."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "every-organism-has-role-g5", "domain": "LIVING_THINGS", "topic": "every organism has a role", "grades": [5, 6], "terms": ["bawat hayop may papel", "role sa ecosystem", "mahalaga lahat", "kahit maliit na hayop", "matag mananap adunay papel", "importante tanan", "bisan gamay nga mananap", "trabaho sa kalikasan", "every living thing matters", "balanse", "walang walang silbi"], "fact": {"tl": "Sa isang ecosystem, bawat organismo kahit napakaliit ay may papel na ginagampanan, kaya ang pagkawala ng kahit isa ay maaaring makasira sa balanse.", "en": "In an ecosystem every organism, even a tiny one, has a role to play, so losing even one can upset the balance.", "bis": "Sa usa ka ecosystem matag organismo, bisan gamay kaayo, adunay papel nga ginabuhat, busa ang pagkawala bisan og usa mahimong makaguba sa balanse."}, "source": "NRC LS2.C; Harlen Big Idea (organisms interdependent)", "generator": "claude-workflow", "reviewed": false},
  {"id": "plant-diversity-groups-g4", "domain": "LIVING_THINGS", "topic": "kinds of plants", "grades": [4, 5, 6], "terms": ["halaman", "uri", "tanom", "klase", "kinds of plants", "trees", "puno", "kahoy", "flowers", "bulaklak", "bulak", "fern", "pako", "moss", "lumot", "grass", "damo", "sagbot", "magkaiba", "lainlain"], "fact": {"tl": "Maraming uri ng halaman: may malalaking puno, may mababang damo, may mga bulaklak, at may mga pako (ferns) at lumot (moss) na walang bulaklak. Lahat sila ay gumagawa ng sariling pagkain mula sa liwanag.", "en": "There are many kinds of plants: tall trees, low grasses, flowering plants, and plants like ferns and mosses that have no flowers. All of them make their own food from light.", "bis": "Daghang klase sa tanom: tag-as nga mga kahoy, mubo nga mga sagbot, mga namulak nga tanom, ug mga tanom sama sa pako (ferns) ug lumot (moss) nga walay bulak. Tanan sila naghimo sa ilang kaugalingong pagkaon gikan sa kahayag."}, "source": "AAAS BSL Ch.5A diversity of life; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fungi-not-plants-g5", "domain": "LIVING_THINGS", "topic": "fungi are not plants", "grades": [5, 6, 7], "terms": ["kabute", "fungi", "fungus", "mushroom", "uhong", "amag", "mold", "agup-op", "hindi halaman", "dili tanom", "walay berde", "no green", "chlorophyll", "kulay-luntian"], "fact": {"tl": "Ang kabute at amag ay fungi, hindi halaman. Hindi sila berde at hindi sila gumagawa ng sariling pagkain; kumukuha sila ng sustansya mula sa patay o nabubulok na bagay.", "en": "Mushrooms and molds are fungi, not plants. They are not green and do not make their own food; they take nutrients from dead or rotting material.", "bis": "Ang uhong ug agup-op kay fungi, dili tanom. Dili sila berde ug dili sila maghimo sa ilang kaugalingong pagkaon; mokuha sila og sustansya gikan sa patay o nadunot nga butang."}, "source": "AAAS BSL Ch.5A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fern-no-flowers-spores-g5", "domain": "LIVING_THINGS", "topic": "ferns reproduce by spores", "grades": [5, 6, 7], "terms": ["pako", "fern", "ferns", "spore", "spores", "walang bulaklak", "walay bulak", "no flower", "no seed", "walang buto", "walay liso", "dahon", "fiddlehead", "lilim", "shade"], "fact": {"tl": "Ang pako (fern) ay halamang walang bulaklak at walang buto. Sa halip, kumakalat ito gamit ang maliliit na spore na nasa ilalim ng mga dahon nito.", "en": "A fern is a plant with no flowers and no seeds. Instead, it spreads using tiny spores found on the underside of its leaves.", "bis": "Ang pako (fern) usa ka tanom nga walay bulak ug walay liso. Hinuon, mokatag kini gamit ang gagmay nga mga spore nga anaa sa ilalom sa mga dahon niini."}, "source": "AAAS BSL Ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "moss-tiny-damp-g5", "domain": "LIVING_THINGS", "topic": "mosses are small and grow in damp places", "grades": [4, 5, 6], "terms": ["lumot", "moss", "mosses", "maliit", "gamay", "basa", "mamasa", "umido", "damp", "walang ugat", "walay gamot", "no roots", "bato", "puno ng kahoy", "tubig"], "fact": {"tl": "Ang lumot (moss) ay maliliit na halamang tumutubo sa mamasa-masang lugar tulad ng mga bato at puno ng kahoy. Wala itong tunay na ugat at sumisipsip ng tubig sa pamamagitan ng buong katawan nito.", "en": "Mosses are tiny plants that grow in damp places like rocks and tree trunks. They have no true roots and soak up water through their whole body.", "bis": "Ang lumot (moss) gagmay nga mga tanom nga motubo sa mamasa-masa nga dapit sama sa mga bato ug punoan sa kahoy. Wala kini tinuod nga gamot ug mosuyop og tubig pinaagi sa tibuok lawas niini."}, "source": "AAAS BSL Ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "flowering-plants-most-common-g5", "domain": "LIVING_THINGS", "topic": "flowering plants make seeds inside fruit", "grades": [5, 6, 7], "terms": ["bulaklak", "flower", "flowering plant", "namumulaklak", "namulak", "buto", "liso", "prutas", "bunga", "fruit", "seed", "pinakamarami", "kadaghanan", "most common", "pananom", "tanom"], "fact": {"tl": "Ang mga halamang namumulaklak ang pinakamaraming uri ng halaman sa mundo. Gumagawa sila ng buto sa loob ng bunga o prutas, na nagpoprotekta at tumutulong ikalat ang mga buto.", "en": "Flowering plants are the most common kind of plant on Earth. They make seeds inside a fruit, which protects the seeds and helps spread them.", "bis": "Ang mga namulak nga tanom mao ang labing daghan nga klase sa tanom sa kalibotan. Maghimo sila og liso sulod sa bunga o prutas, nga manalipod ug motabang pagkatag sa mga liso."}, "source": "AAAS BSL Ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "seed-parts-g4", "domain": "LIVING_THINGS", "topic": "what is inside a seed", "grades": [3, 4, 5], "terms": ["buto", "liso", "seed", "loob ng buto", "sulod sa liso", "baby plant", "munting halaman", "embryo", "pagkain", "stored food", "tinanim", "balat", "seed coat", "tutubo", "moturok"], "fact": {"tl": "Sa loob ng buto ay may maliit na halaman na natutulog at imbak na pagkain para sa unang paglaki nito. Kapag may tamang tubig at init, tutubo ito at magiging bagong halaman.", "en": "Inside a seed is a tiny sleeping plant and stored food for its first growth. With enough water and warmth, it sprouts into a new plant.", "bis": "Sulod sa liso adunay gamay nga natulog nga tanom ug tinipigan nga pagkaon alang sa una niini nga pagtubo. Kon adunay igong tubig ug kainit, moturok kini ug mahimong bag-ong tanom."}, "source": "AAAS BSL Ch.5C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "seed-dispersal-g4", "domain": "LIVING_THINGS", "topic": "how seeds travel", "grades": [4, 5, 6], "terms": ["buto", "liso", "seed", "kumakalat", "pagkalat", "naglakaw", "naglupad", "dispersal", "hangin", "wind", "hayop", "animal", "tubig", "water", "dumikit", "midikit", "kumakapit", "balahibo", "bunga"], "fact": {"tl": "Naglalakbay ang mga buto sa iba't ibang paraan: tinatangay ng hangin, dinadala ng tubig, kinakain ng mga hayop, o dumidikit sa balahibo at damit. Nakakatulong ito para tumubo ang mga halaman sa bagong lugar.", "en": "Seeds travel in many ways: carried by wind, floated by water, eaten by animals, or stuck to fur and clothes. This helps plants grow in new places.", "bis": "Ang mga liso mobiyahe sa nagkalainlaing paagi: gianod sa hangin, gidala sa tubig, gikaon sa mga hayop, o midikit sa balhibo ug sa sapot. Makatabang kini aron motubo ang mga tanom sa bag-ong dapit."}, "source": "AAAS BSL Ch.5C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fruit-protects-seed-g4", "domain": "LIVING_THINGS", "topic": "fruit holds and protects seeds", "grades": [3, 4, 5], "terms": ["prutas", "bunga", "fruit", "buto", "liso", "seed", "nakapaloob", "sulod", "nagpoprotekta", "nanalipod", "matamis", "tam-is", "sweet", "kumain", "mansanas", "kamatis"], "fact": {"tl": "Ang prutas ay nababalot sa palibot ng buto ng isang halaman. Pinoprotektahan nito ang buto, at kapag ito ay matamis, hinihikayat nitong kainin ng mga hayop para maikalat ang buto.", "en": "A fruit is the part that grows around a plant's seeds. It protects the seeds, and when it is sweet it tempts animals to eat it and spread the seeds.", "bis": "Ang prutas mao ang bahin nga motubo libot sa mga liso sa usa ka tanom. Manalipod kini sa mga liso, ug kon tam-is kini, mag-awhag sa mga hayop nga kaonon kini aron makatag ang mga liso."}, "source": "AAAS BSL Ch.5C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tomato-cucumber-are-fruits-g5", "domain": "LIVING_THINGS", "topic": "some vegetables are really fruits", "grades": [5, 6, 7], "terms": ["kamatis", "tomato", "pipino", "cucumber", "talong", "eggplant", "sili", "pepper", "prutas", "fruit", "gulay", "vegetable", "utan", "may buto", "may liso", "with seeds", "katunayan", "tinuod"], "fact": {"tl": "Sa siyensya, ang anumang bahagi ng halaman na may buto sa loob ay isang prutas. Kaya ang kamatis, pipino, at talong ay talagang mga prutas, kahit tinatawag nating gulay.", "en": "In science, any part of a plant that holds seeds inside is a fruit. So tomato, cucumber, and eggplant are really fruits, even though we call them vegetables.", "bis": "Sa siyensya, bisan unsang bahin sa tanom nga adunay liso sa sulod kay usa ka prutas. Busa ang kamatis, pipino, ug talong tinuod nga mga prutas, bisan og tawgon nato silang utanon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rice-palay-staple-g3", "domain": "LIVING_THINGS", "topic": "rice is the main Philippine crop", "grades": [3, 4, 5], "terms": ["bigas", "palay", "kanin", "rice", "humay", "bugas", "kan-on", "pangunahing pagkain", "staple", "pananim", "tanom", "Pilipinas", "Pinas", "basang lupa", "paddy", "araw-araw"], "fact": {"tl": "Ang palay ay isang halamang damo na pinagkukunan natin ng bigas, ang pangunahing pagkain ng karamihan ng mga Pilipino. Tumutubo ito sa basang palayan.", "en": "Rice (palay) is a grass plant that gives us the rice grain, the main food of most Filipinos. It grows in flooded paddy fields.", "bis": "Ang humay usa ka tanom nga sagbot nga gikuhaan nato og bugas, ang nag-unang pagkaon sa kadaghanang Pilipino. Motubo kini sa basa nga basakan."}, "source": "encyclopedia-stable consensus; DepEd PH crops", "generator": "claude-workflow", "reviewed": false},
  {"id": "rice-grass-grain-g5", "domain": "LIVING_THINGS", "topic": "rice grows from a grass", "grades": [5, 6, 7], "terms": ["palay", "rice", "humay", "damo", "grass", "sagbot", "butil", "grain", "lugas", "tangkay", "uhay", "balat", "ipa", "upa", "husk", "ani", "harvest"], "fact": {"tl": "Ang bigas ay ang butil ng halamang palay, isang uri ng damo. Ang bawat butil ay nababalot ng matigas na balat (ipa) na inaalis bago ito kainin.", "en": "Rice is the grain of the palay plant, a kind of grass. Each grain is wrapped in a hard husk that is removed before we eat it.", "bis": "Ang bugas mao ang lugas sa tanom nga humay, usa ka matang sa sagbot. Ang matag lugas giputos sa gahi nga balat (upa) nga kuhaon una sa atong pagkaon niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "coconut-tree-of-life-g4", "domain": "LIVING_THINGS", "topic": "coconut tree uses", "grades": [4, 5, 6], "terms": ["niyog", "buko", "coconut", "lubi", "puno ng niyog", "tree of life", "puno ng buhay", "kahoy sa kinabuhi", "tubig ng buko", "coconut water", "gata", "coconut milk", "langis", "oil", "bunot", "husk", "marami ang gamit"], "fact": {"tl": "Ang puno ng niyog ay tinatawag na \"tree of life\" sa Pilipinas dahil halos lahat ng bahagi nito ay may gamit: ang tubig at laman ng buko, ang gata, ang langis, at maging ang bunot at dahon.", "en": "The coconut tree is called the \"tree of life\" in the Philippines because nearly every part is useful: the coconut water and meat, the coconut milk, the oil, and even the husk and leaves.", "bis": "Ang punoan sa lubi gitawag nga \"tree of life\" sa Pilipinas tungod kay halos tanang bahin niini mapuslanon: ang tubig ug unod sa lubi, ang gata, ang lana, ug bisan ang bunot ug dahon."}, "source": "encyclopedia-stable consensus; DepEd PH crops", "generator": "claude-workflow", "reviewed": false},
  {"id": "coconut-floats-disperses-g5", "domain": "LIVING_THINGS", "topic": "coconut seed floats across the sea", "grades": [5, 6, 7], "terms": ["niyog", "buko", "coconut", "lubi", "lumulutang", "molutaw", "floats", "dagat", "sea", "tubig", "buto", "liso", "seed", "bunot", "husk", "naglalakbay", "mokatag", "isla", "island", "kumakapit"], "fact": {"tl": "Ang buong niyog ay isang malaking buto na lumulutang sa tubig. Ito ang dahilan kung bakit ang niyog ay nakapaglalakbay sa dagat at tumutubo sa mga baybayin ng malalayong isla.", "en": "A whole coconut is a giant seed that floats on water. This is why coconuts can travel across the sea and grow on the shores of faraway islands.", "bis": "Ang tibuok lubi usa ka dako nga liso nga molutaw sa tubig. Mao kini ang hinungdan nganong ang lubi makahimo pagbiyahe latas sa dagat ug motubo sa baybayon sa layong mga isla."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "banana-herb-not-tree-g6", "domain": "LIVING_THINGS", "topic": "banana plant is a giant herb", "grades": [6, 7, 8], "terms": ["saging", "banana", "saba", "puno ng saging", "stem", "tangkay", "punoan", "hindi puno", "dili kahoy", "not a tree", "giant herb", "damo", "malambot", "humok", "dahon", "leaves", "buwig", "bunch"], "fact": {"tl": "Kahit tinatawag nating \"puno ng saging,\" hindi ito tunay na puno — walang matigas na kahoy ang tangkay nito. Ang saging ay isang napakalaking damo, at ang \"tangkay\" ay mga dahong magkakapatong.", "en": "Even though we say \"banana tree,\" it is not a true tree — its stem has no hard wood. The banana is a giant herb, and its \"trunk\" is made of tightly packed leaves.", "bis": "Bisan og tawgon natong \"punoan sa saging,\" dili kini tinuod nga kahoy — walay gahi nga kahoy ang punoan niini. Ang saging usa ka dako kaayo nga sagbot, ug ang \"punoan\" hinimo sa nag-uban-uban nga mga dahon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "banana-no-seeds-eaten-g6", "domain": "LIVING_THINGS", "topic": "eating bananas have no real seeds", "grades": [6, 7, 8], "terms": ["saging", "banana", "buto", "liso", "seed", "walang buto", "walay liso", "no seeds", "itim na tuldok", "black dots", "supang", "saha", "sucker", "tinatanim", "gitanom", "clone"], "fact": {"tl": "Ang mga saging na kinakain natin ay halos walang buto — ang maliliit na itim na tuldok sa gitna ay mga buto na hindi na tumutubo. Kaya ang mga magsasaka ay nagtatanim ng saging mula sa mga supang, hindi sa buto.", "en": "The bananas we eat have almost no seeds — the tiny black dots in the middle are seeds that no longer grow. So farmers plant bananas from suckers (offshoots), not from seeds.", "bis": "Ang mga saging nga atong gikaon halos walay liso — ang gagmay nga itom nga tulbok sa tunga mao ang mga liso nga dili na motubo. Busa ang mga mag-uuma magtanom og saging gikan sa mga saha, dili gikan sa liso."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mango-national-fruit-g3", "domain": "LIVING_THINGS", "topic": "mango is the Philippine national fruit", "grades": [3, 4, 5], "terms": ["mangga", "mango", "manggang Pilipino", "pambansang prutas", "national fruit", "prutas sa nasud", "matamis", "tam-is", "sweet", "hilaw", "luto", "ripe", "hinog", "berde", "dilaw", "yellow", "carabao mango"], "fact": {"tl": "Ang mangga ang pambansang prutas ng Pilipinas. Kilala ang matamis na manggang Pilipino (carabao mango) sa buong mundo, lalo na kapag hinog at dilaw na ito.", "en": "The mango is the national fruit of the Philippines. The sweet Philippine carabao mango is famous around the world, especially when it is ripe and yellow.", "bis": "Ang mangga mao ang nasudnong prutas sa Pilipinas. Ang tam-is nga mangga sa Pilipinas (carabao mango) bantog sa tibuok kalibotan, ilabi na kon hinog na kini ug dalag."}, "source": "encyclopedia-stable consensus; PH national symbols", "generator": "claude-workflow", "reviewed": false},
  {"id": "mango-one-big-seed-g4", "domain": "LIVING_THINGS", "topic": "mango has one large seed", "grades": [4, 5, 6], "terms": ["mangga", "mango", "buto", "liso", "seed", "pit", "stone", "isang malaki", "usa ka dako", "one big", "gitna", "tunga", "laman", "unod", "flesh", "matamis", "bunga", "tag-init"], "fact": {"tl": "Ang bawat mangga ay may isang malaking buto sa gitna na napapaligiran ng matamis na laman. Mula sa isang butong ito maaaring tumubo ang isang bagong puno ng mangga.", "en": "Each mango has one large seed in the center, surrounded by sweet flesh. From this single seed a whole new mango tree can grow.", "bis": "Ang matag mangga adunay usa ka dako nga liso sa tunga nga gilibotan sa tam-is nga unod. Gikan niini nga usa ka liso makatubo ang usa ka tibuok bag-ong punoan sa mangga."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "narra-national-tree-g4", "domain": "LIVING_THINGS", "topic": "narra is the Philippine national tree", "grades": [4, 5, 6], "terms": ["narra", "national tree", "pambansang puno", "kahoy sa nasud", "matibay na kahoy", "hardwood", "matigas na kahoy", "dilaw na bulaklak", "yellow flowers", "Pilipinas", "Pinas", "puno", "kahoy", "lilim"], "fact": {"tl": "Ang narra ang pambansang puno ng Pilipinas. Ito ay isang malaki at matibay na puno na may matigas na kahoy at maliliit na dilaw na bulaklak.", "en": "The narra is the national tree of the Philippines. It is a large, strong tree with very hard wood and small yellow flowers.", "bis": "Ang narra mao ang nasudnong kahoy sa Pilipinas. Usa kini ka dako ug lig-on nga kahoy nga adunay gahi kaayo nga kahoy ug gagmay nga dalag nga mga bulak."}, "source": "encyclopedia-stable consensus; PH national symbols", "generator": "claude-workflow", "reviewed": false},
  {"id": "narra-hardwood-furniture-g6", "domain": "LIVING_THINGS", "topic": "narra wood is prized hardwood", "grades": [6, 7, 8], "terms": ["narra", "kahoy", "hardwood", "matigas", "gahi", "muwebles", "furniture", "mamahalin", "mahalon", "valuable", "pinoprotektahan", "gipanalipdan", "protected", "putulin", "tumutubo nang mabagal", "slow-growing"], "fact": {"tl": "Ang kahoy ng narra ay matigas, matibay, at maganda ang kulay, kaya mamahalin ito para sa muwebles. Dahil mabagal itong tumubo at marami nang naputol, pinoprotektahan na ito ng batas sa Pilipinas.", "en": "Narra wood is hard, strong, and beautifully colored, making it a prized wood for furniture. Because it grows slowly and many were cut down, it is now protected by law in the Philippines.", "bis": "Ang kahoy sa narra gahi, lig-on, ug nindot og kolor, busa mahal kini alang sa muwebles. Tungod kay hinay kini motubo ug daghan na ang giputol, gipanalipdan na kini sa balaod sa Pilipinas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "trees-tallest-longest-living-g5", "domain": "LIVING_THINGS", "topic": "trees are the largest and longest-living plants", "grades": [5, 6, 7], "terms": ["puno", "kahoy", "tree", "trees", "pinakamataas", "labing taas", "tallest", "pinakamatanda", "labing tigulang", "oldest", "matagal mabuhay", "tangkay", "trunk", "wood", "matibay", "lilim", "daang taon", "siglo"], "fact": {"tl": "Ang mga puno ang pinakamalalaki at pinakamatagal mabuhay na halaman. Marami sa kanila ay nabubuhay nang daan-daang taon dahil ang kanilang matigas na tangkay (kahoy) ay nagbibigay ng lakas at suporta.", "en": "Trees are the largest and longest-living plants. Many live for hundreds of years because their hard trunk (wood) gives them strength and support.", "bis": "Ang mga kahoy mao ang labing dagko ug labing dugay mabuhi nga mga tanom. Daghan kanila ang mabuhi og gatusan ka tuig tungod kay ang ilang gahi nga punoan (kahoy) naghatag og kusog ug suporta."}, "source": "AAAS BSL Ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tree-rings-age-g5", "domain": "LIVING_THINGS", "topic": "tree rings show age", "grades": [5, 6, 7], "terms": ["puno", "kahoy", "tree", "singsing", "tree rings", "argolya", "edad", "age", "taon", "tuig", "year", "bilangin", "ihapon", "count", "putol", "trunk", "tangkay", "isang taon"], "fact": {"tl": "Kapag pinutol ang isang puno, makikita mo ang mga singsing sa loob ng tangkay nito. Ang bawat singsing ay isang taon ng paglaki, kaya mabibilang mo ang edad ng puno sa pamamagitan ng mga ito.", "en": "When a tree is cut, you can see rings inside its trunk. Each ring is one year of growth, so you can count them to tell the tree's age.", "bis": "Kon putlon ang usa ka kahoy, makita nimo ang mga singsing sulod sa punoan niini. Ang matag singsing usa ka tuig nga pagtubo, busa maihap nimo kini aron mahibal-an ang edad sa kahoy."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bamboo-fast-grass-g5", "domain": "LIVING_THINGS", "topic": "bamboo is a fast-growing grass", "grades": [5, 6, 7], "terms": ["kawayan", "bamboo", "bagakay", "damo", "grass", "sagbot", "hindi puno", "dili kahoy", "not a tree", "mabilis tumubo", "paspas motubo", "fast growing", "guwang", "hollow", "matibay", "bahay", "gamit"], "fact": {"tl": "Ang kawayan ay isang napakalaking damo, hindi puno, at isa sa pinakamabilis tumubong halaman sa mundo. Magaan ngunit matibay ito, kaya ginagamit sa paggawa ng bahay at kasangkapan.", "en": "Bamboo is a giant grass, not a tree, and one of the fastest-growing plants in the world. It is light yet strong, so it is used to build houses and tools.", "bis": "Ang kawayan usa ka dako kaayo nga sagbot, dili kahoy, ug usa sa labing paspas motubo nga mga tanom sa kalibotan. Gaan apan lig-on kini, busa gamiton sa paghimo og balay ug galamiton."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "abaca-fiber-ph-plant-g6", "domain": "LIVING_THINGS", "topic": "abaca gives Manila hemp fiber", "grades": [6, 7, 8], "terms": ["abaka", "abaca", "Manila hemp", "hibla", "fiber", "lanot", "lubid", "rope", "pisi", "tela", "papel", "banig", "kamukha ng saging", "parehas sa saging", "like banana", "halamang Pilipino", "tanom"], "fact": {"tl": "Ang abaka ay isang halamang Pilipino na kamukha ng saging. Mula sa malalakas na hibla ng tangkay nito ginagawa ang lubid, papel, at tela na kilala bilang \"Manila hemp.\"", "en": "Abaca is a Philippine plant that looks like a banana. From the strong fibers of its stalk, people make rope, paper, and cloth known as \"Manila hemp.\"", "bis": "Ang abaka usa ka tanom sa Pilipinas nga morag saging. Gikan sa lig-on nga mga lanot sa punoan niini, ang mga tawo maghimo og pisi, papel, ug panapton nga nailhan nga \"Manila hemp.\""}, "source": "encyclopedia-stable consensus; PH crops", "generator": "claude-workflow", "reviewed": false},
  {"id": "sampaguita-national-flower-g3", "domain": "LIVING_THINGS", "topic": "sampaguita is the Philippine national flower", "grades": [3, 4, 5], "terms": ["sampaguita", "national flower", "pambansang bulaklak", "bulak sa nasud", "puti", "white", "mabango", "humot", "fragrant", "maliit", "gamay", "kuwintas", "garland", "Pilipinas", "bulaklak", "bulak"], "fact": {"tl": "Ang sampaguita ang pambansang bulaklak ng Pilipinas. Ito ay maliit, puti, at napakabango, at madalas gawing kuwintas ng bulaklak.", "en": "The sampaguita is the national flower of the Philippines. It is small, white, and very fragrant, and is often made into flower garlands.", "bis": "Ang sampaguita mao ang nasudnong bulak sa Pilipinas. Gamay kini, puti, ug humot kaayo, ug kanunay himoon nga kwintas sa bulak."}, "source": "encyclopedia-stable consensus; PH national symbols", "generator": "claude-workflow", "reviewed": false},
  {"id": "flower-parts-attract-g6", "domain": "LIVING_THINGS", "topic": "why flowers are colorful and scented", "grades": [5, 6, 7], "terms": ["bulaklak", "flower", "bulak", "makulay", "mabulukon", "colorful", "mabango", "humot", "scent", "bubuyog", "bee", "putyokan", "paru-paro", "butterfly", "alibangbang", "naghihikayat", "pollen", "polen", "nectar", "pulot", "dugos"], "fact": {"tl": "Makulay at mabango ang mga bulaklak para makaakit ng mga insekto tulad ng bubuyog at paru-paro. Kapag lumapit ang mga ito sa pulot, nadadala nila ang pollen at tumutulong sa pollination.", "en": "Flowers are colorful and fragrant to attract insects like bees and butterflies. When these visit for the nectar, they carry pollen and help with pollination.", "bis": "Ang mga bulak mabulukon ug humot aron makadani og mga insekto sama sa putyokan ug alibangbang. Kon moduol sila sa dugos, madala nila ang polen ug makatabang sa pollination."}, "source": "AAAS BSL Ch.5C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sugarcane-sweet-crop-g4", "domain": "LIVING_THINGS", "topic": "sugarcane gives us sugar", "grades": [4, 5, 6], "terms": ["tubo", "sugarcane", "asukal", "sugar", "kalamay", "matamis", "tam-is", "sweet", "damo", "grass", "tangkay", "stalk", "katas", "juice", "duga", "Negros", "pananim", "tanom"], "fact": {"tl": "Ang tubo ay isang matamis na damo na pinagkukunan ng asukal. Ang katas ng makapal nitong tangkay ay pinipiga at pinapakulo hanggang maging asukal o kalamay.", "en": "Sugarcane is a sweet grass that gives us sugar. The juice from its thick stalk is squeezed out and boiled down to make sugar.", "bis": "Ang tubo usa ka tam-is nga sagbot nga gikuhaan og asukal. Ang duga gikan sa baga niini nga punoan pug-on ug pabukalon hangtod mahimong asukal o kalamay."}, "source": "encyclopedia-stable consensus; PH crops", "generator": "claude-workflow", "reviewed": false},
  {"id": "pineapple-many-flowers-g6", "domain": "LIVING_THINGS", "topic": "a pineapple is made of many flowers", "grades": [6, 7, 8], "terms": ["pinya", "pineapple", "prutas", "fruit", "maraming bulaklak", "daghang bulak", "many flowers", "nagsanib", "naghiusa", "fused", "balat", "skin", "panit", "matinik", "korona", "crown", "halaman", "tanom"], "fact": {"tl": "Ang isang pinya ay talagang gawa sa maraming maliliit na bulaklak na nagsanib-sanib sa isang malaking prutas. Ang bawat \"mata\" sa balat ng pinya ay galing sa isang bulaklak.", "en": "A pineapple is really made of many small flowers that fused together into one big fruit. Each \"eye\" on the pineapple's skin comes from a single flower.", "bis": "Ang usa ka pinya tinuod nga hinimo sa daghang gagmay nga mga bulak nga naghiusa ngadto sa usa ka dako nga prutas. Ang matag \"mata\" sa panit sa pinya gikan sa usa ka bulak."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mushroom-spores-spread-g6", "domain": "LIVING_THINGS", "topic": "mushrooms spread by spores", "grades": [6, 7, 8], "terms": ["kabute", "uhong", "mushroom", "fungi", "spore", "spores", "walang buto", "walay liso", "no seeds", "ilalim", "ilalom", "underside", "kalat", "mokatag", "hangin", "wind", "basa", "moist", "lumalaki"], "fact": {"tl": "Ang kabute ay hindi nagpaparami sa pamamagitan ng buto kundi sa pamamagitan ng napakaliliit na spore na nasa ilalim ng cap nito. Tinatangay ng hangin ang mga spore para tumubo sa ibang basang lugar.", "en": "A mushroom does not reproduce with seeds but with very tiny spores under its cap. The wind carries the spores so new mushrooms can grow in other damp places.", "bis": "Ang uhong dili magsanay pinaagi sa liso kondili pinaagi sa gagmay kaayo nga mga spore sa ilalom sa kalo niini. Ang hangin modala sa mga spore aron motubo ang bag-ong uhong sa ubang mamasa nga dapit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cacao-coffee-ph-crops-g6", "domain": "LIVING_THINGS", "topic": "cacao and coffee are seed crops", "grades": [6, 7, 8], "terms": ["kakaw", "cacao", "tsokolate", "chocolate", "tsako", "kape", "coffee", "buto", "liso", "seed", "beans", "butil", "prinito", "giprito", "roasted", "pananim", "tanom", "puno", "Pilipinas"], "fact": {"tl": "Ang tsokolate at kape ay parehong nagmumula sa mga buto ng halaman. Ang tsokolate ay gawa sa buto ng kakaw, at ang kape ay gawa sa prinitong buto ng halamang kape.", "en": "Chocolate and coffee both come from plant seeds. Chocolate is made from cacao seeds, and coffee is made from the roasted seeds of the coffee plant.", "bis": "Ang tsokolate ug kape parehong gikan sa mga liso sa tanom. Ang tsokolate hinimo gikan sa liso sa kakaw, ug ang kape hinimo gikan sa giprito nga liso sa tanom nga kape."}, "source": "encyclopedia-stable consensus; PH crops", "generator": "claude-workflow", "reviewed": false},
  {"id": "moss-fern-no-flower-old-g7", "domain": "LIVING_THINGS", "topic": "mosses and ferns are ancient flowerless plants", "grades": [7, 8, 9], "terms": ["lumot", "moss", "pako", "fern", "walang bulaklak", "walay bulak", "flowerless", "walang buto", "spore", "sinauna", "karaan", "ancient", "una", "first plants", "matagal na", "dating halaman"], "fact": {"tl": "Ang mga lumot at pako ay kabilang sa pinakaunang mga halaman sa lupa. Lumitaw sila milyon-milyong taon bago pa magkaroon ng mga halamang namumulaklak, kaya nagpaparami pa rin sila gamit ang spore.", "en": "Mosses and ferns are among the earliest land plants. They appeared millions of years before flowering plants existed, which is why they still reproduce with spores.", "bis": "Ang mga lumot ug pako kabahin sa labing una nga mga tanom sa yuta. Mitungha sila milyon-milyon ka tuig una pa naglungtad ang mga namulak nga tanom, mao nga nagsanay pa gihapon sila gamit ang spore."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "countershading-camouflage-g5", "domain": "LIVING_THINGS", "topic": "countershading camouflage", "grades": [5, 6, 7], "terms": ["countershading", "kamuflahe", "kamuflage", "pagtatago", "kulay", "itim sa likod", "puti sa tiyan", "anino", "shading", "ngitngit sa luyo", "belly", "back", "fish", "isda", "tiyan", "likod"], "fact": {"tl": "Maraming hayop tulad ng isda at usa ay may madilim na kulay sa likod at maputi sa tiyan — tinatawag itong countershading. Pinapawi nito ang anino sa ilalim ng katawan kaya mahirap silang makita ng kalaban.", "en": "Many animals like fish and deer are dark on top and pale on the belly — this is called countershading. It cancels out the shadow under the body, making them harder to spot.", "bis": "Daghang mananap sama sa isda ug usa ang itom sa likod ug maputi sa tiyan — gitawag kini og countershading. Gipapas niini ang anino sa ilawom sa lawas mao nga lisod sila makita sa kaaway."}, "source": "AAAS BSL 5A/P2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "warning-colors-aposematism-g5", "domain": "LIVING_THINGS", "topic": "warning coloration", "grades": [5, 6, 7], "terms": ["warning colors", "aposematism", "matingkad na kulay", "babala", "lason", "makahilo", "poison", "dilaw", "pula", "itim", "bright colors", "hayop", "pasidaan", "mapula", "madilaw"], "fact": {"tl": "Ang ilang hayop na lason o lasang masama ay may matingkad na kulay tulad ng pula, dilaw, o itim — para mag-babala sa mananakop na huwag silang kainin.", "en": "Some animals that are poisonous or taste bad have bright colors like red, yellow, or black — a warning that tells predators not to eat them.", "bis": "Ang ubang mananap nga makahilo o pait og lami adunay hayag nga kolor sama sa pula, dalag, o itom — usa ka pasidaan nga moingon sa mga manunukob nga dili sila kan-on."}, "source": "AAAS BSL 5A/P2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mimicry-harmless-copies-g6", "domain": "LIVING_THINGS", "topic": "mimicry in animals", "grades": [6, 7, 8], "terms": ["mimicry", "panggagaya", "panggaya", "gaya", "ginagaya", "mapanganib", "harmless", "hindi nakakapinsala", "manggagaya", "insekto", "insect", "copies", "sundog", "mosundog", "walay kuyaw"], "fact": {"tl": "Sa mimicry, ginagaya ng isang hayop na walang depensa ang hitsura ng isang mapanganib o lason na hayop, kaya iniiwasan ito ng mga mananakop kahit hindi naman ito nakakasakit.", "en": "In mimicry, a harmless animal copies the look of a dangerous or poisonous animal, so predators avoid it even though it cannot really hurt them.", "bis": "Sa mimicry, gisundog sa usa ka mananap nga walay depensa ang panagway sa usa ka delikado o makahilo nga mananap, mao nga likayan kini sa mga manunukob bisan tuod dili kini makasakit."}, "source": "AAAS BSL 5A/P2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mimic-octopus-impersonation-g6", "domain": "LIVING_THINGS", "topic": "mimic octopus", "grades": [6, 7, 8], "terms": ["mimic octopus", "pugita", "kugita", "octopus", "manggagaya", "ahas-dagat", "sea snake", "lionfish", "flatfish", "ginagaya", "Indo-Pacific", "pagbabago ng hitsura", "mosundog", "nagagaya"], "fact": {"tl": "Ang mimic octopus ng Indo-Pacific ay kayang baguhin ang hugis at galaw nito para magmukhang ahas-dagat, lionfish, o flatfish — iba't ibang mapanganib na hayop ang ginagaya nito para protektahan ang sarili.", "en": "The mimic octopus of the Indo-Pacific can change its shape and movements to look like a sea snake, lionfish, or flatfish — copying several dangerous animals to protect itself.", "bis": "Ang mimic octopus sa Indo-Pacific makahimo sa pag-usab sa porma ug lihok niini aron magpakita nga halas sa dagat, lionfish, o flatfish — gisundog niini ang lainlaing delikadong mananap aron mapanalipdan ang kaugalingon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "monarch-butterfly-migration-g6", "domain": "LIVING_THINGS", "topic": "monarch butterfly migration", "grades": [6, 7, 8], "terms": ["monarch butterfly", "paru-paro", "alibangbang", "monarch", "paglipat", "migration", "Mexico", "libo-libong kilometro", "henerasyon", "generations", "milkweed", "naglalakbay", "mobalhin", "milya", "taglagas"], "fact": {"tl": "Ang monarch butterfly ay lumilipad ng libo-libong kilometro mula Canada at United States papuntang Mexico tuwing taglagas — napakalayo nito kaya ilang henerasyon ng paru-paro ang kailangan para makumpleto ang buong biyahe.", "en": "The monarch butterfly flies thousands of kilometers from Canada and the United States to Mexico each autumn — so far that it takes several generations of butterflies to complete the full round trip.", "bis": "Ang monarch butterfly molupad og libo ka kilometro gikan sa Canada ug United States padulong sa Mexico matag tinghulog — layo kaayo nga magkinahanglan og pipila ka henerasyon sa alibangbang aron mahuman ang tibuok biyahe."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "salmon-upstream-migration-g6", "domain": "LIVING_THINGS", "topic": "salmon migration", "grades": [5, 6, 7], "terms": ["salmon", "isda", "migration", "paglipat", "ilog", "upstream", "pasalungat", "dagat", "spawn", "mangitlog", "mangiklog", "balik", "amoy", "smell", "river", "sapa", "pangiklog", "balik sa natawhan"], "fact": {"tl": "Ang salmon ay namumuhay sa dagat ngunit bumabalik pasalungat sa ilog kung saan ito ipinanganak para mangitlog — ginagabayan ito ng amoy ng tubig pabalik sa eksaktong sapa.", "en": "Salmon live in the ocean but swim back upstream to the river where they were born to lay their eggs — they are guided by the smell of the water back to the exact stream.", "bis": "Ang salmon nagpuyo sa dagat apan mobalik pasulbong sa suba diin sila natawo aron mangitlog — gigiyahan sila sa baho sa tubig pabalik sa eksaktong sapa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wildebeest-great-migration-g6", "domain": "LIVING_THINGS", "topic": "wildebeest migration", "grades": [5, 6, 7], "terms": ["wildebeest", "Africa", "migration", "paglipat", "Serengeti", "damo", "grass", "ulan", "rain", "kawan", "herd", "milyon", "lumilipat", "panon", "mobalhin", "sabana", "savanna"], "fact": {"tl": "Sa Africa, mahigit isang milyong wildebeest ang sabay-sabay na lumilipat sa Serengeti bawat taon, sinusundan ang ulan papunta sa mga lugar na may sariwang damo.", "en": "In Africa, over a million wildebeest migrate together across the Serengeti every year, following the rains to places with fresh grass.", "bis": "Sa Africa, kapin sa usa ka milyon ka wildebeest ang dungan nga mobalhin tabok sa Serengeti matag tuig, ginasunod ang ulan padulong sa mga dapit nga adunay lab-as nga sagbot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "torpor-hummingbird-energy-g6", "domain": "LIVING_THINGS", "topic": "torpor in animals", "grades": [6, 7, 8], "terms": ["torpor", "hummingbird", "ibon", "langgam", "mababang init", "slow down", "gabi", "night", "tibok ng puso", "heartbeat", "energy", "lakas", "tipid", "cold night", "mokunhod", "malamig na gabi"], "fact": {"tl": "Tuwing malamig na gabi, ang maliit na hummingbird ay pumapasok sa torpor — bumababa nang husto ang temperatura at tibok ng puso nito para makatipid ng lakas hanggang umaga.", "en": "On cold nights, the tiny hummingbird enters torpor — its temperature and heartbeat drop sharply to save energy until morning.", "bis": "Sa bugnaw nga gabii, ang gamay nga hummingbird mosulod sa torpor — mokunhod pag-ayo ang temperatura ug pitik sa kasingkasing niini aron makadaginot og kusog hangtod sa buntag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "brumation-reptiles-cold-g6", "domain": "LIVING_THINGS", "topic": "reptile dormancy in cold", "grades": [6, 7, 8], "terms": ["brumation", "reptile", "reptilya", "ahas", "snake", "butiki", "lizard", "pagong", "bao", "turtle", "cold-blooded", "malamig na dugo", "taglamig", "winter", "dormant", "bugnaw nga dugo", "malamig na panahon", "halos di gumagalaw"], "fact": {"tl": "Ang mga reptilya tulad ng ahas at pagong ay dumaraan sa brumation tuwing malamig na panahon — tumitigil sila at halos hindi gumagalaw dahil ang init ng katawan nila ay sumusunod sa init ng paligid.", "en": "Reptiles like snakes and turtles go through brumation in cold weather — they become still and barely move because their body temperature follows the temperature around them.", "bis": "Ang mga reptilya sama sa halas ug bao moagi sa brumation sa bugnaw nga panahon — mohunong sila ug halos dili molihok kay ang kainit sa ilang lawas mosunod sa kainit sa palibot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "antifreeze-fish-polar-g7", "domain": "LIVING_THINGS", "topic": "antifreeze in polar fish", "grades": [7, 8, 9], "terms": ["antifreeze", "icefish", "isda", "polar", "Antarctica", "yelo", "ice", "dugo", "blood", "protina", "protein", "hindi nagyeyelo", "malamig na dagat", "freezing", "frozen", "dili mogelo", "tubig nga bugnaw"], "fact": {"tl": "Ang ilang isda sa nagyeyelong dagat ng Antarctica ay may natatanging protina sa dugo na parang antifreeze — pinipigilan nito ang dugo nila na maging yelo kahit napakalamig ng tubig.", "en": "Some fish in the freezing seas of Antarctica have special antifreeze proteins in their blood — these stop their blood from turning to ice even in water cold enough to freeze.", "bis": "Ang ubang isda sa nagyelo nga dagat sa Antarctica adunay pinasahi nga protina sa dugo nga sama sa antifreeze — gipugngan niini ang ilang dugo nga mahimong yelo bisan sa tubig nga bugnaw kaayo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "camel-desert-survival-g5", "domain": "LIVING_THINGS", "topic": "camel desert adaptations", "grades": [4, 5, 6], "terms": ["camel", "kamelyo", "camello", "disyerto", "desert", "init", "heat", "tubig", "water", "hump", "umbok", "taba", "fat", "mata", "eyelashes", "pilikmata", "buhangin", "sand", "nagtitipid ng tubig", "balas"], "fact": {"tl": "Ang kamelyo ay nakakaligtas sa disyerto dahil iniimbak nito ang taba sa umbok (hump) nito bilang lakas, kaya nitong tiisin ang maraming araw na walang tubig, at may mahahabang pilikmata para harangin ang buhangin.", "en": "The camel survives the desert because it stores fat in its hump for energy, can go many days without water, and has long eyelashes to keep out the sand.", "bis": "Ang kamelyo mabuhi sa disyerto kay gitipigan niini ang tambok sa bukol (hump) niini isip kusog, makaagwanta og daghang adlaw nga walay tubig, ug adunay tag-as nga pilok aron dili masudlan og balas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fennec-fox-big-ears-g5", "domain": "LIVING_THINGS", "topic": "fennec fox desert ears", "grades": [4, 5, 6], "terms": ["fennec fox", "fox", "soro", "disyerto", "desert", "malalaking tainga", "big ears", "dako nga dalunggan", "init", "heat", "lamig", "cool", "gabi", "night", "Sahara", "nagpapalamig", "init sa lawas", "nocturnal"], "fact": {"tl": "Ang fennec fox sa disyerto ng Sahara ay may napakalalaking tainga na tumutulong palabasin ang init ng katawan nito para hindi ito mainitan, at lumalabas lang ito kapag gabi na malamig.", "en": "The fennec fox of the Sahara desert has very large ears that help release body heat so it stays cool, and it comes out mainly at night when it is cooler.", "bis": "Ang fennec fox sa disyerto sa Sahara adunay dagko kaayo nga dalunggan nga motabang sa pagpagawas sa kainit sa lawas niini aron dili kini mainit, ug mogawas kini kasagaran sa gabii nga mas bugnaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "polar-bear-cold-survival-g5", "domain": "LIVING_THINGS", "topic": "polar bear cold adaptations", "grades": [4, 5, 6], "terms": ["polar bear", "oso", "white bear", "Arctic", "lamig", "cold", "yelo", "ice", "blubber", "taba", "fur", "balahibo", "init", "insulate", "mainitan", "bugnaw", "makapal nga balhibo"], "fact": {"tl": "Ang polar bear ay nananatiling mainit-init sa Arctic dahil may makapal itong balahibo at isang makapal na patong ng taba (blubber) sa ilalim ng balat na nagsisilbing insulasyon laban sa lamig.", "en": "The polar bear stays warm in the Arctic because of its thick fur and a thick layer of fat (blubber) under the skin that works as insulation against the cold.", "bis": "Ang polar bear magpabilin nga init sa Arctic tungod sa baga niini nga balhibo ug usa ka baga nga taba (blubber) ilawom sa panit nga nagsilbing insulasyon batok sa kabugnaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "penguin-huddle-warmth-g4", "domain": "LIVING_THINGS", "topic": "penguins keeping warm", "grades": [3, 4, 5], "terms": ["penguin", "pengwin", "Antarctica", "lamig", "cold", "huddle", "siksikan", "magkadikit", "nagpapainit", "keep warm", "ice", "yelo", "grupo", "group", "emperor penguin", "nagsiksikan", "init", "pundok"], "fact": {"tl": "Sa sobrang lamig ng Antarctica, ang mga emperor penguin ay nagsisiksikan nang magkakadikit sa isang malaking grupo para mainit-init at pinagsasalit-salit nila kung sino ang nasa labas ng grupo.", "en": "In the bitter cold of Antarctica, emperor penguins huddle tightly together in a big group to stay warm, taking turns being on the cold outer edge.", "bis": "Sa hilabihan ka bugnaw sa Antarctica, ang mga emperor penguin magdinikitay og higpit sa usa ka dakong pundok aron magpainit, ug magsalisi sila kon kinsa ang naa sa gawas nga bahin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bioluminescence-deep-sea-g6", "domain": "LIVING_THINGS", "topic": "deep sea bioluminescence", "grades": [6, 7, 8], "terms": ["bioluminescence", "deep sea", "kalaliman", "ilaw", "light", "glow", "nagliliwanag", "kumikinang", "dilim", "dark", "isda", "fish", "tubig", "ocean", "makadan-ag", "lawom nga dagat", "liwanag"], "fact": {"tl": "Sa madilim na kalaliman ng dagat na hindi naaabot ng sikat ng araw, maraming hayop ang gumagawa ng sarili nilang ilaw — tinatawag itong bioluminescence — para humanap ng pagkain, kasama, o takutin ang kalaban.", "en": "In the dark deep sea where sunlight never reaches, many animals make their own light — called bioluminescence — to find food, find mates, or scare off enemies.", "bis": "Sa ngitngit nga kahiladman sa dagat diin dili maabot ang silaw sa adlaw, daghang mananap ang naghimo sa ilang kaugalingong kahayag — gitawag kini og bioluminescence — aron mangita og pagkaon, magpares, o mahadlok ang kaaway."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "anglerfish-glowing-lure-g6", "domain": "LIVING_THINGS", "topic": "anglerfish deep sea lure", "grades": [6, 7, 8], "terms": ["anglerfish", "isda", "deep sea", "kalaliman", "ilaw", "glowing lure", "pain", "bait", "nagliliwanag", "ngipin", "teeth", "dilim", "dark", "predator", "nagdan-ag nga paon", "lawom nga dagat", "pang-akit"], "fact": {"tl": "Ang anglerfish sa kalaliman ng dagat ay may nakausli na parang pamingwit na nagliliwanag sa dulo — ginagamit nito ang ilaw na ito bilang pain para akitin ang maliliit na isda papalapit sa malaki nitong bibig.", "en": "The deep-sea anglerfish has a glowing lure dangling in front of it — it uses this light as bait to draw small fish close to its big mouth.", "bis": "Ang anglerfish sa kahiladman sa dagat adunay nag-idlab nga paon nga nagbitay sa atubangan niini — gigamit niini kini nga kahayag isip paon aron danihon ang gagmayng isda paduol sa dako niini nga baba."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "deep-sea-pressure-adaptation-g7", "domain": "LIVING_THINGS", "topic": "deep sea pressure survival", "grades": [7, 8, 9], "terms": ["deep sea pressure", "presyon", "pressure", "kalaliman", "deep", "durog", "crush", "katawan", "body", "soft", "malambot", "walang hangin", "no air bladder", "isda", "fish", "gibug-aton sa tubig", "lawom", "dili madugmok"], "fact": {"tl": "Sa pinakamalalim na bahagi ng dagat, napakalakas ng presyon ng tubig na durog-durog sana ang karaniwang hayop — kaya ang mga isda doon ay may malalambot na katawan na walang air bladder para hindi sila madurog.", "en": "In the deepest parts of the ocean the water pressure is strong enough to crush an ordinary animal — so the fish there have soft bodies with no air bladder so they are not crushed.", "bis": "Sa kinahiladman nga bahin sa dagat, kusog kaayo ang presyon sa tubig nga makadugmok unta sa ordinaryong mananap — busa ang mga isda didto adunay humok nga lawas nga walay air bladder aron dili sila madugmok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "skunk-spray-defense-g4", "domain": "LIVING_THINGS", "topic": "skunk defense spray", "grades": [4, 5, 6], "terms": ["skunk", "mabahong amoy", "spray", "wisik", "depensa", "defense", "stinky", "baho", "mabaho", "kalaban", "predator", "itim na puti", "stripe", "babala", "warning", "nagwiwisik", "panimaho", "panghimo og baho"], "fact": {"tl": "Kapag natakot, ang skunk ay nagwiwisik ng likido na napakabaho mula sa likod nito para itaboy ang kalaban — ang itim-at-puti nitong kulay ay babala na huwag itong lapitan.", "en": "When threatened, a skunk sprays a very smelly liquid from its rear to drive off an enemy — its black-and-white color is a warning to stay away.", "bis": "Kon mahadlok, ang skunk mowisik og likido nga baho kaayo gikan sa likod niini aron abugon ang kaaway — ang itom-ug-puti niini nga kolor usa ka pasidaan nga dili kini duolon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "porcupine-quills-defense-g4", "domain": "LIVING_THINGS", "topic": "porcupine quill defense", "grades": [4, 5, 6], "terms": ["porcupine", "quills", "tinik", "spines", "matatalim", "sharp", "depensa", "defense", "kalaban", "predator", "balahibong matalim", "sumasaksak", "tusok", "tumutusok", "babala", "protect", "mananap nga tunokon", "tunok"], "fact": {"tl": "Ang porcupine ay natatakpan ng matatalim na tinik na tinatawag na quills — kapag may kalaban, itinataas nito ang mga tinik para tumusok sa lumalapit na hayop.", "en": "A porcupine is covered with sharp spines called quills — when an enemy comes near, it raises the quills so they jab the attacking animal.", "bis": "Ang porcupine natabunan og hait nga mga tunok nga gitawag og quills — kon adunay kaaway nga moduol, ipataas niini ang mga tunok aron motusok sa nagsulong nga mananap."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pufferfish-inflate-defense-g4", "domain": "LIVING_THINGS", "topic": "pufferfish defense", "grades": [4, 5, 6], "terms": ["pufferfish", "botete", "isda", "lumalaki", "inflate", "umaalsa", "bilog", "ball", "tinik", "spines", "tubig", "water", "lason", "poison", "depensa", "defense", "namamaga", "nagdako", "makahilo nga isda"], "fact": {"tl": "Kapag nasa panganib, ang pufferfish (botete) ay sumisipsip ng tubig at lumalaki na parang bilog na lobo na puno ng tinik — kaya mahirap itong kainin, at ang ilang uri ay may lason pa.", "en": "When in danger, a pufferfish gulps water and swells into a spiky ball — making it hard to eat, and some kinds are even poisonous.", "bis": "Kon namiligro, ang pufferfish (botete) mosuyop og tubig ug modako nga sama sa lingin nga bola nga puno og tunok — mao nga lisod kini kan-on, ug ang uban pa gani makahilo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gecko-tail-autotomy-g5", "domain": "LIVING_THINGS", "topic": "lizard tail drop defense", "grades": [4, 5, 6], "terms": ["gecko", "butiki", "tuko", "lizard", "buntot", "tail", "autotomy", "pagpuputol ng buntot", "naglalaglag", "gumagalaw", "wiggle", "depensa", "defense", "tumakas", "escape", "nagtutubo ulit", "regrow", "ikog", "nagtubo balik"], "fact": {"tl": "Maraming butiki ang kayang i-drop ang buntot kapag nahuli ng kalaban — gumagalaw pa ang nahulog na buntot para guluhin ang kalaban habang tumatakas ang butiki, at unti-unti itong tumutubo ulit.", "en": "Many lizards can drop their tail when caught by an enemy — the fallen tail keeps wiggling to distract the predator while the lizard escapes, and it slowly grows back.", "bis": "Daghang butiki ang makahulog sa ilang ikog kon madakpan sa kaaway — ang nahulog nga ikog magpadayon sa paglihok aron libgon ang manunukob samtang moikyas ang butiki, ug hinay-hinay kining motubo balik."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bat-echolocation-g5", "domain": "LIVING_THINGS", "topic": "bat echolocation", "grades": [5, 6, 7], "terms": ["bat", "paniki", "kabog", "echolocation", "tunog", "sound", "echo", "alingawngaw", "dilim", "dark", "gabi", "night", "sound waves", "insekto", "insect", "hunt", "nangangaso", "tingog", "alingugngog"], "fact": {"tl": "Ang paniki ay gumagamit ng echolocation para makahanap ng pagkain sa dilim — naglalabas ito ng tunog at pinakikinggan ang alingawngaw na bumabalik para malaman kung saan ang insekto o hadlang.", "en": "A bat uses echolocation to find food in the dark — it makes sounds and listens to the echoes that bounce back to learn where an insect or obstacle is.", "bis": "Ang kabog mogamit og echolocation aron makakaplag og pagkaon sa kangitngit — mohimo kini og tingog ug maminaw sa alingugngog nga mobalik aron mahibaloan kon asa ang insekto o babag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "nocturnal-night-vision-g5", "domain": "LIVING_THINGS", "topic": "night vision in nocturnal animals", "grades": [5, 6, 7], "terms": ["nocturnal", "night vision", "gabi", "night", "mata", "eyes", "malalaking mata", "kumikinang na mata", "reflective", "tapetum", "pusa", "cat", "dilim", "dark", "makakita sa gabi", "liwanag", "glowing eyes", "dako nga mata"], "fact": {"tl": "Maraming hayop na gising sa gabi ay may malalaking mata at isang patong sa likod ng mata na sumasalamin ng liwanag pabalik — kaya kumikinang ang mata nila sa dilim at mas malinaw silang nakakakita sa gabi.", "en": "Many night animals have large eyes and a layer behind the eye that reflects light back — this is why their eyes glow in the dark and they can see better at night.", "bis": "Daghang mananap nga gising sa gabii ang adunay dagkong mata ug usa ka sapaw sa likod sa mata nga mosumbalik sa kahayag — mao nga mosidlak ang ilang mga mata sa kangitngit ug mas klaro silang makakita sa gabii."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "arctic-fox-color-change-g5", "domain": "LIVING_THINGS", "topic": "arctic fox seasonal camouflage", "grades": [5, 6, 7], "terms": ["arctic fox", "fox", "soro", "Arctic", "niyebe", "snow", "puti", "white", "brown", "kayumanggi", "kamuflahe", "camouflage", "season", "panahon", "nagbabago ng kulay", "balahibo", "fur", "taglamig", "tag-init", "puti nga balhibo"], "fact": {"tl": "Ang arctic fox ay nagiging puti ang balahibo tuwing taglamig para tumugma sa niyebe, at nagiging kayumanggi o kulay-abo naman ito tuwing tag-init para tumugma sa lupa — isang uri ng kamuflahe na nagbabago kasabay ng panahon.", "en": "The arctic fox turns white in winter to match the snow, and brown or gray in summer to match the ground — a kind of camouflage that changes with the seasons.", "bis": "Ang arctic fox mahimong puti ang balhibo sa tingtugnaw aron mohaom sa niyebe, ug mahimong kape o abuhon sa ting-init aron mohaom sa yuta — usa ka matang sa camouflage nga nag-usab uban sa panahon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "leaf-insect-camouflage-g5", "domain": "LIVING_THINGS", "topic": "leaf insect camouflage", "grades": [4, 5, 6], "terms": ["leaf insect", "dahon", "leaf", "insekto", "insect", "kamuflahe", "camouflage", "nagtatago", "blend", "kulay", "green", "berde", "luntian", "predator", "hugis dahon", "kahawig ng dahon", "sama sa dahon", "nagtago"], "fact": {"tl": "Ang leaf insect ay may katawang kahawig na kahawig ng dahon — pati ang gilid at ugat ng dahon ay nasa katawan nito — kaya halos hindi ito makita ng ibon at iba pang kakain dito.", "en": "The leaf insect has a body that looks exactly like a leaf — even the edges and veins of a leaf are on its body — so birds and other eaters can barely see it.", "bis": "Ang leaf insect adunay lawas nga susama gayod sa dahon — bisan ang ngilit ug ugat sa dahon anaa sa lawas niini — mao nga halos dili kini makita sa mga langgam ug uban pang mokaon niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "blubber-marine-mammals-g6", "domain": "LIVING_THINGS", "topic": "blubber insulation", "grades": [5, 6, 7], "terms": ["blubber", "taba", "fat", "whale", "balyena", "seal", "sea lion", "dolphin", "dolpin", "lamig", "cold", "malamig na dagat", "insulation", "init", "keep warm", "makapal na taba", "baga nga tambok", "insulasyon"], "fact": {"tl": "Ang mga balyena, seal, at iba pang mamalyang naninirahan sa malamig na dagat ay may makapal na patong ng taba na tinatawag na blubber sa ilalim ng balat — ito ang nagpapanatiling mainit ng katawan nila sa nagyeyelong tubig.", "en": "Whales, seals, and other mammals living in cold seas have a thick layer of fat called blubber under the skin — this keeps their bodies warm in freezing water.", "bis": "Ang mga balyena, seal, ug ubang mananap nga nagpuyo sa bugnaw nga dagat adunay baga nga sapaw sa tambok nga gitawag og blubber ilawom sa panit — kini ang nagpabilin nga init sa ilang lawas sa nagyelo nga tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hibernation-vs-sleep-g5", "domain": "LIVING_THINGS", "topic": "how hibernation differs from sleep", "grades": [5, 6, 7], "terms": ["hibernation", "hibernasyon", "sleep", "tulog", "matulog", "winter", "taglamig", "slow heartbeat", "mabagal na tibok", "body temperature", "temperatura", "groundhog", "ground squirrel", "taba", "fat", "gising", "mokunhod", "tipid sa kusog"], "fact": {"tl": "Ang tunay na hibernation ay hindi lang basta mahimbing na tulog — bumababa nang husto ang temperatura at tibok ng puso ng hayop nang maraming linggo o buwan para makatipid ng lakas habang walang pagkain sa taglamig.", "en": "True hibernation is not just deep sleep — the animal's body temperature and heartbeat drop very low for weeks or months to save energy while there is no food in winter.", "bis": "Ang tinuod nga hibernation dili lang ordinaryong tulog — ang temperatura ug pitik sa kasingkasing sa mananap mokunhod pag-ayo sulod sa daghang semana o bulan aron makadaginot og kusog samtang walay pagkaon sa tingtugnaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "desert-animals-nocturnal-water-g5", "domain": "LIVING_THINGS", "topic": "how desert animals survive heat", "grades": [4, 5, 6], "terms": ["desert animals", "disyerto", "desert", "init", "heat", "tubig", "water", "gabi", "night", "lungga", "burrow", "tago", "hide", "araw", "day", "kangaroo rat", "pagkaon", "food", "nagtatago sa lungga", "mananap sa disyerto"], "fact": {"tl": "Maraming hayop sa disyerto ang nagtatago sa malamig na lungga sa ilalim ng lupa kapag araw at lumalabas lang kapag gabi — at ang iba tulad ng kangaroo rat ay halos hindi na umiinom dahil kumukuha sila ng tubig mula mismo sa kanilang pagkain.", "en": "Many desert animals hide in cool underground burrows during the day and come out only at night — and some, like the kangaroo rat, barely drink at all because they get water from their food itself.", "bis": "Daghang mananap sa disyerto ang motago sa bugnaw nga lungag ilawom sa yuta panahon sa adlaw ug mogawas lang sa gabii — ug ang uban sama sa kangaroo rat halos dili na moinom kay magkuha sila og tubig gikan mismo sa ilang pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "chameleon-color-change-g4", "domain": "LIVING_THINGS", "topic": "chameleon color change", "grades": [4, 5, 6], "terms": ["chameleon", "hayop", "color change", "nagbabago ng kulay", "kulay", "color", "balat", "skin", "kamuflahe", "camouflage", "init", "mood", "damdamin", "communicate", "green", "brown", "nag-usab og kolor", "panit", "makausab og kolor"], "fact": {"tl": "Ang chameleon ay kayang baguhin ang kulay ng balat nito — ginagawa nito ito hindi lang para magtago kundi para rin ipakita ang init nito o ang damdamin nito sa ibang chameleon.", "en": "A chameleon can change the color of its skin — it does this not only to hide but also to show its temperature or its mood to other chameleons.", "bis": "Ang chameleon makahimo sa pag-usab sa kolor sa panit niini — gibuhat niini kini dili lang aron magtago kondili usab aron ipakita ang kainit niini o ang gibati niini ngadto sa ubang chameleon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "thick-fur-mountain-cold-g4", "domain": "LIVING_THINGS", "topic": "thick fur for cold mountains", "grades": [3, 4, 5], "terms": ["thick fur", "makapal na balahibo", "fur", "cold", "lamig", "bundok", "mountain", "yak", "snow leopard", "mainit", "warm", "init", "balahibo", "taglamig", "insulation", "mananap sa bundok", "baga nga balhibo", "malamig na lugar"], "fact": {"tl": "Ang mga hayop na nakatira sa malalamig na bundok tulad ng yak ay may napakakapal na balahibo na parang makapal na damit — hinaharang nito ang lamig at pinapanatiling mainit ang katawan nila.", "en": "Animals that live on cold mountains like the yak have very thick fur that works like a heavy coat — it blocks the cold and keeps their bodies warm.", "bis": "Ang mga mananap nga nagpuyo sa bugnaw nga kabukiran sama sa yak adunay baga kaayo nga balhibo nga sama sa bug-at nga sapot — gibabagan niini ang kabugnaw ug gipabilin nga init ang ilang lawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "five-kingdoms-life-g7", "domain": "LIVING_THINGS", "topic": "kingdoms of life", "grades": [6, 7, 8], "terms": ["kingdom", "kaharian", "gingharian", "animal", "hayop", "plant", "halaman", "tanom", "fungi", "amag", "agup-op", "protist", "bacteria", "bakterya", "monera", "lima", "grupo", "uri", "klase", "five kingdoms"], "fact": {"tl": "Bago ang species, inuuri muna ng mga siyentipiko ang buhay sa malalaking grupo na tinatawag na kingdom; karaniwang itinuturo ang limang kingdom: hayop (animals), halaman (plants), fungi (tulad ng amag at kabute), protist, at bacteria.", "en": "Above the species level, scientists sort life into large groups called kingdoms; five kingdoms are commonly taught: animals, plants, fungi (like molds and mushrooms), protists, and bacteria.", "bis": "Una pa sa species, gigrupo sa mga siyentista ang kinabuhi ngadto sa dagkong grupo nga gitawag og kingdom; kasagarang gitudlo ang lima ka kingdom: hayop (animals), tanom (plants), fungi (sama sa agup-op ug uhong), protist, ug bacteria."}, "source": "AAAS BSL Ch.5; NRC LS4.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fungi-not-plants-g6", "domain": "LIVING_THINGS", "topic": "fungi kingdom", "grades": [5, 6, 7], "terms": ["fungi", "fungus", "amag", "agup-op", "kabute", "uhong", "lumot", "halaman", "tanom", "hindi halaman", "dili tanom", "mushroom", "mold", "natutunaw", "patay", "decomposer", "spore"], "fact": {"tl": "Ang fungi tulad ng amag at kabute ay HINDI halaman — hindi sila gumagawa ng sariling pagkain sa sikat ng araw, sa halip ay sinisipsip nila ang sustansya mula sa patay o nabubulok na bagay.", "en": "Fungi like molds and mushrooms are NOT plants — they do not make their own food from sunlight; instead they absorb nutrients from dead or decaying matter.", "bis": "Ang fungi sama sa agup-op ug uhong DILI tanom — dili sila maghimo og kaugalingong pagkaon gikan sa adlaw, hinuon mosuyop sila og sustansya gikan sa patay o nadunot nga butang."}, "source": "AAAS BSL Ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bacteria-microscopic-g6", "domain": "LIVING_THINGS", "topic": "bacteria", "grades": [5, 6, 7], "terms": ["bacteria", "bakterya", "mikrobyo", "germ", "mikroskopyo", "microscope", "isang selula", "usa ka selula", "single cell", "maliit", "gamay", "di nakikita", "dili makita", "microorganism", "tumutulong", "nakakasakit"], "fact": {"tl": "Ang bacteria ay napakaliliit na nabubuhay na bagay na gawa sa iisang selula lamang at hindi nakikita ng mata; ang iba ay nagdudulot ng sakit, ngunit marami ang nakakatulong, tulad ng mga gumagawa ng yogurt o naglilinis ng lupa.", "en": "Bacteria are tiny living things made of just one cell and too small to see with the eye; some cause disease, but many are helpful, like those that make yogurt or clean the soil.", "bis": "Ang bacteria gagmay kaayo nga buhi nga butang nga hinimo og usa lang ka selula ug dili makita sa mata; ang uban makahatag og sakit, apan daghan ang makatabang, sama sa mga naghimo og yogurt o naglimpyo sa yuta."}, "source": "AAAS BSL Ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "what-is-species-g6", "domain": "LIVING_THINGS", "topic": "what a species is", "grades": [6, 7, 8], "terms": ["species", "espesye", "uri", "klase", "matang", "magparami", "magkrus", "mate", "anak", "offspring", "supling", "parehong uri", "managsama", "makapanganak", "fertile", "tao", "aso"], "fact": {"tl": "Ang isang species ay isang uri ng buhay na nabubuhay na bagay na maaaring magparami kasama ang isa't isa at magkaroon ng anak na kaya ring magparami; halimbawa, lahat ng tao ay iisang species.", "en": "A species is one kind of living thing whose members can breed with each other and have offspring that can also breed; for example, all humans are one species.", "bis": "Ang usa ka species mao ang usa ka matang sa buhi nga butang nga makahimo og pagsanay tali sa usag usa ug makabaton og anak nga makasanay usab; pananglitan, ang tanang tawo usa ra ka species."}, "source": "AAAS BSL 5A/M4; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "scientific-name-binomial-g7", "domain": "LIVING_THINGS", "topic": "scientific names", "grades": [7, 8], "terms": ["scientific name", "pangalang siyentipiko", "ngalang siyentipiko", "Latin", "dalawang salita", "duha ka pulong", "genus", "species", "Homo sapiens", "binomial", "Linnaeus", "iisang pangalan", "global", "tao"], "fact": {"tl": "Binibigyan ng mga siyentipiko ang bawat species ng dalawang-salitang pangalang siyentipiko sa Latin (tulad ng Homo sapiens para sa tao) para magkaisa ang tawag dito ng mga tao sa buong mundo, kahit iba-iba ang kanilang lokal na wika.", "en": "Scientists give every species a two-word scientific name in Latin (like Homo sapiens for humans) so that people all over the world call it the same thing, even when their local languages differ.", "bis": "Hatagan sa mga siyentista ang matag species og duha-ka-pulong nga ngalang siyentipiko sa Latin (sama sa Homo sapiens para sa tawo) aron managsama ang tawag niini sa mga tawo sa tibuok kalibotan, bisan lainlain ang ilang lokal nga pinulongan."}, "source": "encyclopedia-stable consensus (Linnaean binomial nomenclature)", "generator": "claude-workflow", "reviewed": false},
  {"id": "mammals-defining-traits-g5", "domain": "LIVING_THINGS", "topic": "what makes a mammal", "grades": [4, 5, 6], "terms": ["mammal", "mamipero", "gatas", "milk", "sumususo", "nagsuso", "balahibo", "balhibo", "fur", "hair", "mainit ang dugo", "init ang dugo", "warm-blooded", "huminga", "baga", "lungs", "aso", "pusa", "tao", "paniki"], "fact": {"tl": "Ang mga mammal ay mga hayop na nagpapasuso ng gatas sa kanilang anak, may balahibo o buhok sa balat, at humihinga ng hangin gamit ang baga; kabilang dito ang aso, pusa, paniki, balyena, at tao.", "en": "Mammals are animals that feed their young with milk, have fur or hair on their skin, and breathe air with lungs; these include dogs, cats, bats, whales, and humans.", "bis": "Ang mga mammal mao ang mga hayop nga magpasuso og gatas sa ilang anak, adunay balhibo o buhok sa panit, ug magginhawa og hangin pinaagi sa baga; lakip niini ang iro, iring, kabog, balyena, ug tawo."}, "source": "AAAS BSL Ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birds-defining-traits-g5", "domain": "LIVING_THINGS", "topic": "what makes a bird", "grades": [4, 5, 6], "terms": ["bird", "ibon", "langgam", "balahibo", "balhibo", "feathers", "pakpak", "pako", "wings", "tuka", "sungo", "beak", "itlog", "egg", "nangingitlog", "mangitlog", "mainit ang dugo", "warm-blooded", "lumilipad", "molupad"], "fact": {"tl": "Ang mga ibon ang tanging hayop na may balahibo (feathers); karamihan ay may pakpak para lumipad, may tuka na walang ngipin, at nangingitlog ng mga itlog na may matigas na balat.", "en": "Birds are the only animals with feathers; most have wings for flying, a toothless beak, and lay eggs with a hard shell.", "bis": "Ang mga langgam mao ang bugtong hayop nga adunay balhibo (feathers); kasagaran adunay pako aron molupad, adunay sungo nga walay ngipon, ug mangitlog og mga itlog nga adunay gahi nga bagol."}, "source": "AAAS BSL Ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fish-defining-traits-g5", "domain": "LIVING_THINGS", "topic": "what makes a fish", "grades": [4, 5, 6], "terms": ["fish", "isda", "hasang", "gills", "huminga sa tubig", "moginhawa sa tubig", "kaliskis", "himbis", "scales", "palikpik", "fins", "kapay", "malamig ang dugo", "bugnaw ang dugo", "cold-blooded", "lumalangoy", "molangoy", "tubig"], "fact": {"tl": "Ang mga isda ay nabubuhay sa tubig at humihinga gamit ang hasang (gills) sa halip na baga; karamihan ay may kaliskis, may palikpik para lumangoy, at malamig ang dugo.", "en": "Fish live in water and breathe with gills instead of lungs; most have scales, fins for swimming, and are cold-blooded.", "bis": "Ang mga isda magpuyo sa tubig ug moginhawa gamit ang hasang (gills) imbes nga baga; kasagaran adunay himbis, adunay kapay aron molangoy, ug bugnaw ang dugo."}, "source": "AAAS BSL Ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "reptiles-defining-traits-g5", "domain": "LIVING_THINGS", "topic": "what makes a reptile", "grades": [4, 5, 6], "terms": ["reptile", "reptilya", "tuyong kaliskis", "uga nga himbis", "dry scales", "balat", "panit", "malamig ang dugo", "bugnaw ang dugo", "cold-blooded", "itlog", "egg", "ahas", "bitin", "butiki", "tiki", "pawikan", "buwaya", "buaya", "huminga", "baga"], "fact": {"tl": "Ang mga reptilya tulad ng ahas, butiki, pagong, at buwaya ay may tuyo at makaliskis na balat, humihinga ng hangin gamit ang baga, at malamig ang dugo kaya madalas silang nagpapainit sa ilalim ng araw.", "en": "Reptiles like snakes, lizards, turtles, and crocodiles have dry, scaly skin, breathe air with lungs, and are cold-blooded, so they often bask in the sun to warm up.", "bis": "Ang mga reptilya sama sa bitin, tiki, bao, ug buaya adunay uga ug himbison nga panit, moginhawa og hangin pinaagi sa baga, ug bugnaw ang dugo busa kasagaran mopainit sila ilalom sa adlaw."}, "source": "AAAS BSL Ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "warm-cold-blooded-g5", "domain": "LIVING_THINGS", "topic": "warm-blooded vs cold-blooded", "grades": [4, 5, 6], "terms": ["warm-blooded", "cold-blooded", "mainit ang dugo", "malamig ang dugo", "init ang dugo", "bugnaw ang dugo", "temperatura ng katawan", "temperatura sa lawas", "init", "lamig", "kapaligiran", "palibot", "mammal", "ibon", "reptilya", "isda", "nagpapainit", "araw"], "fact": {"tl": "Ang mga mainit ang dugo (warm-blooded) tulad ng mammal at ibon ay pinapanatili ang sariling init ng katawan, samantalang ang mga malamig ang dugo (cold-blooded) tulad ng isda, reptilya, at amphibian ay sumusunod sa init o lamig ng kanilang paligid.", "en": "Warm-blooded animals like mammals and birds keep their own body heat steady, while cold-blooded animals like fish, reptiles, and amphibians follow the warmth or coolness of their surroundings.", "bis": "Ang mga init og dugo (warm-blooded) sama sa mammal ug langgam magpabilin sa kaugalingong init sa lawas, samtang ang mga bugnaw og dugo (cold-blooded) sama sa isda, reptilya, ug amphibian mosunod sa init o bugnaw sa ilang palibot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-meaning-g7", "domain": "LIVING_THINGS", "topic": "what evolution is", "grades": [7, 8, 9], "terms": ["evolution", "ebolusyon", "pagbabago", "pag-usab", "nagbago", "nag-usab", "species", "henerasyon", "kaliwatan", "matagal", "dugay", "milyong taon", "milyon ka tuig", "nanggaling", "naggikan", "ninuno", "katigulangan", "descended"], "fact": {"tl": "Ang evolution ay ang mabagal na pagbabago ng mga species sa napakaraming henerasyon; ang ibig sabihin nito, ang mga buhay na bagay ngayon ay nanggaling sa mga naunang species na medyo iba ang anyo.", "en": "Evolution is the slow change of species over very many generations; it means that today's living things descended from earlier species that looked somewhat different.", "bis": "Ang evolution mao ang hinay nga pag-usab sa mga species sa daghan kaayong kaliwatan; ang buot ipasabot, ang mga buhi nga butang karon naggikan sa naunang mga species nga medyo lahi ang panagway."}, "source": "AAAS BSL 5F/H1; NRC LS4.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "variation-within-species-g6", "domain": "LIVING_THINGS", "topic": "variation within a species", "grades": [5, 6, 7], "terms": ["variation", "pagkakaiba", "kalainan", "magkaiba", "lainlain", "individuals", "miyembro", "kasapi", "parehong uri", "managsama nga matang", "kulay", "kolor", "laki", "gidak-on", "hindi magkapareho", "dili pareho", "magkapatid"], "fact": {"tl": "Kahit iisang species, hindi magkapareho ang bawat indibidwal — may pagkakaiba-iba sila sa laki, kulay, bilis, o lakas, tulad ng magkakapatid na may magkaibang taas; tinatawag itong variation.", "en": "Even within one species, no two individuals are exactly alike — they vary in size, color, speed, or strength, like siblings of different heights; this is called variation.", "bis": "Bisan usa ra ka species, walay duha ka indibidwal nga managsama gayod — managlahi sila sa gidak-on, kolor, kakusog, o kalig-on, sama sa managsoon nga lainlain og gitas-on; gitawag kini og variation."}, "source": "AAAS BSL 5B/P1, 5F/E1; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "natural-selection-kid-g7", "domain": "LIVING_THINGS", "topic": "natural selection", "grades": [7, 8, 9], "terms": ["natural selection", "natural na seleksyon", "kinaiyanhong pagpili", "survival of the fittest", "kabuhi", "buhi", "nakaligtas", "naluwas", "matalik", "nabuhay", "nagparami", "nanganak", "anak", "kalamangan", "bentaha", "kapaligiran", "palibot", "Darwin"], "fact": {"tl": "Sa natural selection, ang mga indibidwal na may mga katangiang akma sa kanilang kapaligiran ay mas malamang na mabuhay at magkaanak, kaya unti-unting dumarami ang mga supling na nagmamana ng kapaki-pakinabang na katangiang iyon.", "en": "In natural selection, individuals with traits that fit their environment are more likely to survive and have young, so over time more and more offspring inherit that helpful trait.", "bis": "Sa natural selection, ang mga indibidwal nga adunay kinaiya nga angay sa ilang palibot mas lagmit nga mabuhi ug manganak, busa hinay-hinay nga modaghan ang mga anak nga makapanunod sa kanang mapuslanong kinaiya."}, "source": "AAAS BSL 5F/H3; NRC LS4.B/LS4.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "darwin-natural-selection-g8", "domain": "LIVING_THINGS", "topic": "Charles Darwin", "grades": [7, 8, 9], "terms": ["Darwin", "Charles Darwin", "natural selection", "natural na seleksyon", "ebolusyon", "evolution", "Galapagos", "Beagle", "siyentipiko", "siyentista", "naglakbay", "nibiyahe", "biyahe", "libro", "aklat", "On the Origin of Species", "ibon", "langgam"], "fact": {"tl": "Si Charles Darwin ay isang siyentipikong British na, pagkatapos maglakbay sa buong mundo at mag-aral ng mga hayop sa Galapagos Islands, ang nagpaliwanag sa natural selection bilang paraan kung paano nagbabago ang mga buhay na bagay sa paglipas ng panahon.", "en": "Charles Darwin was a British scientist who, after sailing around the world and studying animals on the Galapagos Islands, explained natural selection as the way living things change over time.", "bis": "Si Charles Darwin usa ka British nga siyentista nga, human makapanaw sa tibuok kalibotan ug makatuon sa mga hayop sa Galapagos Islands, mipasabot sa natural selection isip paagi kung giunsa pag-usab sa mga buhi nga butang sa paglabay sa panahon."}, "source": "encyclopedia-stable consensus (Darwin, On the Origin of Species, 1859)", "generator": "claude-workflow", "reviewed": false},
  {"id": "darwin-finches-galapagos-g8", "domain": "LIVING_THINGS", "topic": "Darwin's finches", "grades": [7, 8, 9], "terms": ["Darwin's finches", "finch", "Galapagos", "tuka", "sungo", "beak", "ibon", "langgam", "isla", "isla-isla", "pagkain", "kalan-on", "buto", "binhi", "insekto", "iba-ibang hugis", "lainlaing porma", "adaptasyon", "natural selection"], "fact": {"tl": "Sa Galapagos Islands, napansin ni Darwin na ang magkakaugnay na ibong finch ay may magkakaibang hugis ng tuka depende sa kanilang kinakain — manipis para sa insekto, makapal para sa matitigas na buto — isang halimbawa ng pag-aangkop sa kapaligiran.", "en": "On the Galapagos Islands, Darwin noticed that related finch birds had differently shaped beaks depending on what they ate — thin for insects, thick for hard seeds — an example of fitting to the environment.", "bis": "Sa Galapagos Islands, namatikdan ni Darwin nga ang nagkadugtong nga mga langgam nga finch adunay lainlaing porma sa sungo depende sa ilang gikaon — nipis para sa insekto, baga para sa gahi nga liso — usa ka pananglitan sa pagpahiangay sa palibot."}, "source": "encyclopedia-stable consensus (Darwin's Galapagos finches)", "generator": "claude-workflow", "reviewed": false},
  {"id": "adaptation-meaning-g5", "domain": "LIVING_THINGS", "topic": "adaptation", "grades": [4, 5, 6], "terms": ["adaptation", "adaptasyon", "pagbagay", "pagpahiangay", "katangian", "kinaiya", "tumutulong", "makatabang", "mabuhay", "mabuhi", "kapaligiran", "palibot", "tirahan", "puy-anan", "makapal na balahibo", "siwang", "kuko", "tuka"], "fact": {"tl": "Ang adaptation ay isang katangian ng hayop o halaman na tumutulong dito na mabuhay sa kanyang kapaligiran, tulad ng makapal na balahibo para sa lamig o mahabang tuka para abutin ang pagkain.", "en": "An adaptation is a feature of an animal or plant that helps it survive in its environment, like thick fur for the cold or a long beak to reach food.", "bis": "Ang adaptation usa ka kinaiya sa hayop o tanom nga makatabang niini nga mabuhi sa iyang palibot, sama sa baga nga balhibo para sa katugnaw o taas nga sungo aron makab-ot ang pagkaon."}, "source": "AAAS BSL 5F/P1; NRC LS4.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "camouflage-adaptation-g4", "domain": "LIVING_THINGS", "topic": "camouflage", "grades": [3, 4, 5], "terms": ["camouflage", "kamuflahe", "pagtatago", "pagtago", "kulay", "kolor", "nagkakaila", "nahisama", "halaman", "tanom", "kapaligiran", "palibot", "nagtatago", "manunugis", "manunukob", "predator", "biktima", "tuko", "uod"], "fact": {"tl": "Ang camouflage ay isang adaptasyon kung saan ang kulay o hugis ng isang hayop ay nahahalintulad sa paligid nito, para mahirapang makita ito ng manunugis o ng kanyang biktima.", "en": "Camouflage is an adaptation where an animal's color or shape blends in with its surroundings, making it hard for predators or prey to see it.", "bis": "Ang camouflage usa ka adaptasyon diin ang kolor o porma sa usa ka hayop nahisama sa iyang palibot, aron lisod kini makita sa manunukob o sa iyang biktima."}, "source": "AAAS BSL 5F/P1; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "selective-breeding-g6", "domain": "LIVING_THINGS", "topic": "selective breeding", "grades": [6, 7, 8], "terms": ["selective breeding", "selective na pagpaparami", "pinili nga pagpasanay", "pagpaparami", "pagpili", "tao", "hayop", "halaman", "tanom", "aso", "iro", "mais", "katangian", "kinaiya", "pinakamaganda", "pinakaayo", "henerasyon", "kaliwatan", "artipisyal"], "fact": {"tl": "Sa selective breeding, pinipili ng tao kung aling mga hayop o halaman ang magpaparami batay sa katangiang gusto nila, kaya sa paglipas ng henerasyon ay nagkaroon tayo ng iba't ibang lahi ng aso, mais, at iba pang alagang halaman at hayop.", "en": "In selective breeding, people choose which animals or plants will reproduce based on traits they want, so over generations we got many breeds of dogs, kinds of corn, and other crops and animals.", "bis": "Sa selective breeding, ang tawo magpili kung unsang mga hayop o tanom ang magsanay base sa kinaiya nga gusto nila, busa sa paglabay sa kaliwatan nakabaton kita og lainlaing rasa sa iro, klase sa mais, ug uban pang tanom ug hayop."}, "source": "AAAS BSL 5B/M3, 5F/M1; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "extinction-meaning-g6", "domain": "LIVING_THINGS", "topic": "extinction", "grades": [5, 6, 7], "terms": ["extinction", "extinct", "pagkalipol", "pagkapuo", "tuluyang nawala", "nawala hangtod", "wala na", "naubos", "species", "dinosaur", "nagbago", "nag-usab", "kapaligiran", "palibot", "hindi nakaligtas", "wala makaluwas", "huling", "kataposan"], "fact": {"tl": "Ang extinction ay nangyayari kapag tuluyang nawala ang lahat ng miyembro ng isang species at wala nang natitira; karamihan ng species na nabuhay sa Earth ay extinct na, tulad ng mga dinosaur.", "en": "Extinction happens when every member of a species dies out and none are left; most species that ever lived on Earth are now extinct, like the dinosaurs.", "bis": "Ang extinction mahitabo kung ang tanang miyembro sa usa ka species mawala hangtod ug wala nay mahibilin; kadaghanan sa mga species nga nabuhi sa Earth extinct na, sama sa mga dinosaur."}, "source": "AAAS BSL 5F/M4; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "extinction-environment-change-g7", "domain": "LIVING_THINGS", "topic": "why species go extinct", "grades": [7, 8], "terms": ["extinction", "extinct", "pagkalipol", "pagkapuo", "kapaligiran", "palibot", "nagbago", "nag-usab", "klima", "weather", "pagkain", "kalan-on", "habitat", "tirahan", "puy-anan", "hindi nakaangkop", "wala makapahiangay", "namatay", "species", "dahilan", "hinungdan"], "fact": {"tl": "Karaniwang nauubos (nagiging extinct) ang isang species kapag mabilis na nagbago ang kapaligiran nito — tulad ng pagbabago ng klima o pagkawala ng pagkain — at ang mga indibidwal nito ay walang mga katangiang kailangan para mabuhay sa bagong kalagayan.", "en": "A species usually goes extinct when its environment changes quickly — like a change in climate or loss of food — and its individuals lack the traits needed to survive in the new conditions.", "bis": "Kasagarang mapuo (mahimong extinct) ang usa ka species kung dali nga mausab ang palibot niini — sama sa pagbag-o sa klima o pagkawala sa pagkaon — ug ang mga indibidwal niini walay kinaiya nga gikinahanglan aron mabuhi sa bag-ong kahimtang."}, "source": "AAAS BSL 5F/M2b, 5F/M4; NRC LS4.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fossils-evidence-evolution-g7", "domain": "LIVING_THINGS", "topic": "fossils as evidence of evolution", "grades": [7, 8, 9], "terms": ["fossil", "fosil", "ebidensya", "patunay", "ebidensiya", "pamatuod", "evolution", "ebolusyon", "nagbago", "nag-usab", "buhay", "kinabuhi", "matagal", "dugay", "layers", "patong-patong", "bato", "luma", "karaan", "kaiba", "lahi"], "fact": {"tl": "Ang mga fossil ay malakas na ebidensya para sa evolution dahil ipinapakita nila na ang mga buhay na bagay noong unang panahon ay kaiba sa mga buhay ngayon, at na unti-unting nagbago ang buhay sa Earth sa milyon-milyong taon.", "en": "Fossils are strong evidence for evolution because they show that living things long ago were different from those alive today, and that life on Earth slowly changed over millions of years.", "bis": "Ang mga fossil kusgan nga ebidensya para sa evolution kay gipakita nila nga ang mga buhi nga butang kaniadto lahi kay sa mga buhi karon, ug nga hinay-hinay nga miusab ang kinabuhi sa Earth sulod sa milyon-milyon ka tuig."}, "source": "AAAS BSL 5F/H7; NRC LS4.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rock-layers-older-deeper-g7", "domain": "LIVING_THINGS", "topic": "fossils in rock layers", "grades": [7, 8], "terms": ["rock layers", "patong-patong na bato", "patong sa bato", "sedimentary", "ilalim", "ilalom", "ibaba", "luma", "karaan", "edad", "panahon", "fossil", "fosil", "mas matanda", "mas tigulang", "deep", "lalim", "pagkakasunod-sunod"], "fact": {"tl": "Sa patong-patong na bato (sedimentary rock), ang mga fossil sa mas malalim na patong ay karaniwang mas matanda kaysa sa nasa ibabaw, kaya nababasa ng mga siyentipiko mula rito ang pagkakasunod-sunod ng mga buhay na nabuhay sa Earth.", "en": "In layered (sedimentary) rock, fossils in the deeper layers are usually older than those near the top, so scientists can read from them the order in which living things appeared on Earth.", "bis": "Sa patong-patong nga bato (sedimentary rock), ang mga fossil sa mas lawom nga patong kasagarang mas tigulang kay sa anaa sa ibabaw, busa mabasa sa mga siyentista gikan niini ang han-ay sa mga buhi nga nabuhi sa Earth."}, "source": "AAAS BSL 5F/M3; NRC ESS1.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "common-ancestor-g8", "domain": "LIVING_THINGS", "topic": "common ancestor", "grades": [8, 9, 10], "terms": ["common ancestor", "iisang ninuno", "managsamang katigulangan", "ninuno", "katigulangan", "kamag-anak", "paryente", "magkaugnay", "nagkadugtong", "DNA", "magkatulad", "managsama", "punong-kahoy", "kahoy sa kinabuhi", "tree of life", "relasyon", "kaliwat"], "fact": {"tl": "Ipinapaliwanag ng evolution na ang magkakatulad na species ay nagmula sa iisang ninuno noong nakaraan; kaya nga ang dami ng pagkakatulad sa katawan at DNA ng dalawang hayop ay nagpapakita kung gaano sila kalapit na magkamag-anak.", "en": "Evolution explains that similar species came from a common ancestor in the past; that is why how much two animals share in body and DNA shows how closely related they are.", "bis": "Gipasabot sa evolution nga ang managsama nga mga species naggikan sa usa ka komon nga katigulangan kaniadto; mao nga kung unsa kadaghan ang panag-ingnan sa lawas ug DNA sa duha ka hayop nagpakita kung unsa sila ka suod nga paryente."}, "source": "AAAS BSL 5F/H1, 5A/H2; NRC LS4.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "whales-evolved-land-g8", "domain": "LIVING_THINGS", "topic": "whale evolution from land mammals", "grades": [7, 8, 9], "terms": ["whale", "balyena", "ebolusyon", "evolution", "ninuno", "katigulangan", "lupa", "yuta", "naglakad", "naglakaw", "dagat", "tubig", "fossil", "fosil", "buto", "bukog", "buto sa hita", "hip bone", "mammal", "bumalik sa dagat"], "fact": {"tl": "Bagama't nabubuhay sa dagat, ang mga balyena ay nagmula sa mga ninunong mammal na dating naglalakad sa lupa; nakita ito ng mga siyentipiko sa mga fossil na nagpapakita ng unti-unting pagbabago mula sa apat na paa tungo sa mga palikpik.", "en": "Although they live in the sea, whales came from ancestor mammals that once walked on land; scientists saw this in fossils that show a gradual change from four legs to flippers.", "bis": "Bisan tuod nagpuyo sa dagat, ang mga balyena naggikan sa katigulangan nga mammal nga kaniadto naglakaw sa yuta; nakita kini sa mga siyentista sa mga fossil nga nagpakita sa hinay-hinay nga pag-usab gikan sa upat ka tiil ngadto sa mga kapay."}, "source": "encyclopedia-stable consensus (whale fossil transitional series)", "generator": "claude-workflow", "reviewed": false},
  {"id": "first-life-single-celled-g9", "domain": "LIVING_THINGS", "topic": "earliest life on Earth", "grades": [8, 9, 10], "terms": ["earliest life", "unang buhay", "unang kinabuhi", "isang selula", "usa ka selula", "single-celled", "bilyong taon", "bilyon ka tuig", "billion", "simple", "microorganism", "mikroorganismo", "una", "sinimulan", "nagsugod", "dagat", "tubig", "naunang buhay"], "fact": {"tl": "Pinaniniwalaan ng mga siyentipiko na ang unang buhay sa Earth ay simpleng mga isahang-selula na organismo na lumitaw mga apat na bilyong taon na ang nakaraan; mula sa mga ito unti-unting umusbong ang mas masalimuot na buhay.", "en": "Scientists think the first life on Earth was simple single-celled organisms that appeared about four billion years ago; from these, more complex life slowly arose.", "bis": "Gituohan sa mga siyentista nga ang unang kinabuhi sa Earth maoy yano nga usa-ka-selula nga organismo nga mitungha mga upat ka bilyon ka tuig na ang milabay; gikan niini hinay-hinay nga mitubo ang mas komplikado nga kinabuhi."}, "source": "AAAS BSL 5F/H8; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "amphibians-vs-reptiles-g5", "domain": "LIVING_THINGS", "topic": "amphibians vs reptiles difference", "grades": [4, 5, 6], "terms": ["amphibian", "reptile", "reptilya", "pagkakaiba", "kalainan", "palaka", "baki", "ahas", "bitin", "balat", "panit", "basa", "tuyo", "uga", "kaliskis", "himbis", "itlog sa tubig", "itlog sa lupa", "manipis"], "fact": {"tl": "Magkaiba ang amphibian at reptilya: ang amphibian tulad ng palaka ay may manipis at basa-basang balat at karaniwang nangingitlog sa tubig, samantalang ang reptilya tulad ng ahas ay may tuyo at makaliskis na balat at nangingitlog sa lupa.", "en": "Amphibians and reptiles are different: amphibians like frogs have thin, moist skin and usually lay eggs in water, while reptiles like snakes have dry, scaly skin and lay eggs on land.", "bis": "Lahi ang amphibian ug reptilya: ang amphibian sama sa baki adunay nipis ug umog nga panit ug kasagarang mangitlog sa tubig, samtang ang reptilya sama sa bitin adunay uga ug himbison nga panit ug mangitlog sa yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "invertebrates-most-animals-g6", "domain": "LIVING_THINGS", "topic": "invertebrates are most animals", "grades": [5, 6, 7], "terms": ["invertebrate", "walang gulugod", "walay backbone", "walang backbone", "backbone", "gulugod", "buto sa likod", "insekto", "insect", "gagamba", "lawalawa", "uod", "ulod", "hipon", "pasayan", "pinakamarami", "kadaghanan", "halos lahat", "hayop", "dikya", "bukya"], "fact": {"tl": "Ang mga invertebrate (walang gulugod) ang bumubuo sa halos lahat ng uri ng hayop sa mundo — higit 90 porsiyento — kabilang ang mga insekto, gagamba, uod, hipon, at dikya; kakaunti lamang ang may backbone.", "en": "Invertebrates (animals without a backbone) make up almost all kinds of animals on Earth — over 90 percent — including insects, spiders, worms, shrimp, and jellyfish; only a small number have a backbone.", "bis": "Ang mga invertebrate (walay backbone) maoy naglangkob sa hapit tanang matang sa hayop sa kalibotan — kapin 90 porsyento — lakip ang mga insekto, lawalawa, ulod, pasayan, ug bukya; gamay ra ang adunay backbone."}, "source": "AAAS BSL Ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "elephant-largest-land-animal-g3", "domain": "LIVING_THINGS", "topic": "elephant largest land animal", "grades": [3, 4, 5], "terms": ["elepante", "pinakamalaki", "hayop sa lupa", "elephant", "largest land animal", "biggest", "kinadak-an", "hayop sa yuta", "pinakadako"], "fact": {"tl": "Ang elepante ang pinakamalaking hayop na nakatira sa lupa.", "en": "The elephant is the largest animal that lives on land.", "bis": "Ang elepante mao ang kinadak-ang hayop nga nagpuyo sa yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "elephant-trunk-uses-g3", "domain": "LIVING_THINGS", "topic": "elephant trunk uses", "grades": [3, 4, 5], "terms": ["elepante", "nguso", "trunk", "ilong", "uminom", "humawak", "kumain", "lawit", "elephant trunk", "simod", "sungo", "ilong sa elepante", "kuptan", "moinom"], "fact": {"tl": "Ginagamit ng elepante ang mahaba nitong nguso para uminom, kumain, at humawak ng mga bagay.", "en": "An elephant uses its long trunk to drink, eat, and grab things.", "bis": "Gigamit sa elepante ang iyang taas nga sungo aron moinom, mokaon, ug mokupot og mga butang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "elephant-big-ears-cool-g4", "domain": "LIVING_THINGS", "topic": "elephant ears cooling", "grades": [4, 5, 6], "terms": ["elepante", "malalaking tainga", "tenga", "pampalamig", "init", "pawis", "big ears", "cool", "elephant ears", "dalunggan", "dagko nga dalunggan", "pabugnaw", "kainit", "pinapaypay"], "fact": {"tl": "Pinapaypay ng elepante ang malalaki nitong tainga para palamigin ang katawan kapag mainit.", "en": "An elephant flaps its big ears to cool its body when it is hot.", "bis": "Gikapay-kapay sa elepante ang iyang dagko nga dalunggan aron pabugnawon ang lawas kon init."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "elephant-tusks-teeth-g5", "domain": "LIVING_THINGS", "topic": "elephant tusks ivory teeth", "grades": [5, 6, 7], "terms": ["elepante", "pangil", "tusk", "ngipin", "garing", "ivory", "tusks", "elephant tusk", "tango", "bangkil", "ngipon sa elepante"], "fact": {"tl": "Ang mahahabang pangil ng elepante ay talagang napakalalaking ngipin.", "en": "An elephant's long tusks are really very large teeth.", "bis": "Ang taas nga bangkil sa elepante mao gyud ang dagko kaayo nga ngipon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "giraffe-eats-tall-leaves-g4", "domain": "LIVING_THINGS", "topic": "giraffe eats tall tree leaves", "grades": [4, 5, 6], "terms": ["giraffe", "dyirap", "dahon", "mataas na puno", "kumain", "dila", "tongue", "leaves", "tall trees", "dahon sa taas", "dahon nga taas", "dila sa giraffe", "kahoy"], "fact": {"tl": "Kayang abutin ng giraffe ang mga dahon sa matataas na puno na hindi maabot ng ibang hayop.", "en": "A giraffe can reach leaves high in tall trees that other animals cannot reach.", "bis": "Makaabot ang giraffe sa mga dahon sa taas nga mga kahoy nga dili maabot sa ubang hayop."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "giraffe-spots-pattern-g4", "domain": "LIVING_THINGS", "topic": "giraffe spots unique pattern", "grades": [4, 5, 6], "terms": ["giraffe", "dyirap", "batik", "spots", "balat", "kakaiba", "pattern", "giraffe spots", "puntik", "pintok", "panit", "lahi nga pattern"], "fact": {"tl": "Bawat giraffe ay may sariling natatanging mga batik, na parang bakas ng kamay ng tao.", "en": "Every giraffe has its own unique pattern of spots, like a human fingerprint.", "bis": "Matag giraffe adunay kaugalingong talagsaon nga mga pintok, sama sa fingerprint sa tawo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "monkey-tail-grip-g3", "domain": "LIVING_THINGS", "topic": "monkey tail climbing", "grades": [3, 4, 5], "terms": ["unggoy", "monkey", "buntot", "tail", "umakyat", "puno", "kapit", "sanga", "climb", "ikog", "amo", "punoan", "sanga sa kahoy", "kapyot"], "fact": {"tl": "May mga unggoy na gumagamit ng buntot nila para kumapit habang umaakyat sa mga puno.", "en": "Some monkeys use their tails to hold on while climbing trees.", "bis": "Adunay mga unggoy nga mogamit sa ilang ikog aron mokapyot samtang nagsaka sa mga kahoy."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ape-no-tail-g4", "domain": "LIVING_THINGS", "topic": "apes no tail gorilla chimpanzee", "grades": [4, 5, 6], "terms": ["ape", "gorilya", "chimpanzee", "orangutan", "walang buntot", "unggoy", "no tail", "great ape", "walay ikog", "gorilla", "amo", "dakong amo"], "fact": {"tl": "Ang mga ape tulad ng gorilya at chimpanzee ay walang buntot, kaya iba sila sa mga unggoy.", "en": "Apes like gorillas and chimpanzees have no tail, which makes them different from monkeys.", "bis": "Ang mga ape sama sa gorilya ug chimpanzee walay ikog, mao nga lahi sila sa mga unggoy."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "chimpanzee-uses-tools-g5", "domain": "LIVING_THINGS", "topic": "chimpanzee uses tools", "grades": [5, 6, 7], "terms": ["chimpanzee", "tsimpanse", "kasangkapan", "tools", "patpat", "kumain", "anay", "stick", "matalino", "smart", "gamit", "sungkod", "sanga", "anay nga insekto", "himan"], "fact": {"tl": "Marunong gumamit ng kasangkapan ang chimpanzee, gaya ng patpat para kunin ang mga anay na kakainin.", "en": "Chimpanzees know how to use tools, like a stick to fish out termites to eat.", "bis": "Ang chimpanzee kahibalo mogamit og himan, sama sa sungkod aron kuhaon ang mga anay nga kan-on."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bat-only-flying-mammal-g4", "domain": "LIVING_THINGS", "topic": "bat only flying mammal", "grades": [4, 5, 6], "terms": ["paniki", "bat", "lumilipad", "mammal", "may suso", "pakpak", "flying mammal", "kabog", "kabag", "naglupad", "pako", "hayop nga naglupad", "kuwaknit"], "fact": {"tl": "Ang paniki ang tanging mammal na talagang nakakalipad gamit ang mga pakpak nito.", "en": "The bat is the only mammal that can truly fly using its wings.", "bis": "Ang kabog mao ra ang mammal nga makalupad gyud pinaagi sa iyang mga pako."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bat-eats-insects-fruit-g4", "domain": "LIVING_THINGS", "topic": "bat diet insects fruit", "grades": [4, 5, 6], "terms": ["paniki", "bat", "insekto", "prutas", "kumain", "lamok", "fruit bat", "insects", "kabog", "mangaon", "bunga", "mokaon"], "fact": {"tl": "May mga paniking kumakain ng insekto at may mga paniking kumakain ng prutas.", "en": "Some bats eat insects, while other bats eat fruit.", "bis": "Adunay mga kabog nga mokaon og insekto, ug adunay mga kabog nga mokaon og prutas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kangaroo-pouch-baby-g3", "domain": "LIVING_THINGS", "topic": "kangaroo pouch joey baby", "grades": [3, 4, 5], "terms": ["kangaroo", "kanggaroo", "bulsa", "pouch", "anak", "joey", "tiyan", "sanggol", "baby", "puyo", "tiyan nga puyo", "nati"], "fact": {"tl": "Dinadala ng inang kangaroo ang anak nito sa isang bulsa sa harap ng tiyan niya.", "en": "A mother kangaroo carries her baby in a pouch on the front of her belly.", "bis": "Ang inahang kangaroo magdala sa iyang anak sulod sa usa ka puyo sa atubangan sa iyang tiyan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kangaroo-hops-legs-g4", "domain": "LIVING_THINGS", "topic": "kangaroo hops strong legs", "grades": [4, 5, 6], "terms": ["kangaroo", "kanggaroo", "talon", "lumukso", "binti", "malakas", "buntot", "hop", "jump", "legs", "lukso", "ambak", "kusgan nga paa", "tiil", "ikog"], "fact": {"tl": "Lumulukso ang kangaroo gamit ang malalakas nitong binti sa likod, at ang buntot ang tumutulong sa kanyang balanse.", "en": "A kangaroo moves by hopping on its strong back legs, and its tail helps it balance.", "bis": "Ang kangaroo molukso pinaagi sa iyang kusgan nga likod nga mga paa, ug ang ikog motabang sa iyang panimbang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "koala-eats-eucalyptus-g4", "domain": "LIVING_THINGS", "topic": "koala eats eucalyptus leaves", "grades": [4, 5, 6], "terms": ["koala", "dahon", "eucalyptus", "kumain", "puno", "leaves", "eucalyptus leaves", "dahon sa eucalyptus", "mokaon", "kahoy", "dahon nga eucalyptus"], "fact": {"tl": "Halos dahon lamang ng eucalyptus ang kinakain ng koala.", "en": "A koala eats almost only the leaves of the eucalyptus tree.", "bis": "Ang koala halos dahon lang sa eucalyptus ang ginakaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "koala-sleeps-long-g3", "domain": "LIVING_THINGS", "topic": "koala sleeps long hours", "grades": [3, 4, 5], "terms": ["koala", "tulog", "matulog", "puno", "buong araw", "sleep", "sleepy", "katulog", "natulog", "kahoy", "adlaw", "mokatulog", "sanga"], "fact": {"tl": "Natutulog ang koala nang napakaraming oras sa loob ng isang araw, kadalasan sa sanga ng puno.", "en": "A koala sleeps for very many hours each day, usually up in a tree branch.", "bis": "Ang koala matulog og daghan kaayo nga oras sa usa ka adlaw, kasagaran sa sanga sa kahoy."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rhino-horn-keratin-g5", "domain": "LIVING_THINGS", "topic": "rhino horn keratin", "grades": [5, 6, 7], "terms": ["rhino", "rhinoceros", "rinoseros", "sungay", "horn", "ilong", "kuko", "keratin", "buhok", "sungay sa ilong", "kuko ug buhok", "panit"], "fact": {"tl": "Ang sungay ng rhino ay gawa sa keratin, ang parehong sangkap ng ating kuko at buhok.", "en": "A rhino's horn is made of keratin, the same material as our nails and hair.", "bis": "Ang sungay sa rhino hinimo gikan sa keratin, ang samang materyal sa atong kuko ug buhok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rhino-thick-skin-g4", "domain": "LIVING_THINGS", "topic": "rhino thick skin grazer", "grades": [4, 5, 6], "terms": ["rhino", "rinoseros", "makapal na balat", "damo", "kumain", "halaman", "thick skin", "grass", "panit", "baga nga panit", "sagbot", "mokaon og tanom", "tanom"], "fact": {"tl": "May napakakapal na balat ang rhino, at karaniwan itong kumakain ng damo at mga halaman.", "en": "A rhino has very thick skin, and it usually eats grass and plants.", "bis": "Ang rhino adunay baga kaayo nga panit, ug kasagaran kini mokaon og sagbot ug mga tanom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hippo-water-time-g4", "domain": "LIVING_THINGS", "topic": "hippo spends day in water", "grades": [4, 5, 6], "terms": ["hippo", "hippopotamus", "ipopotamo", "tubig", "ilog", "lubog", "init", "araw", "water", "river", "suba", "lubong", "mainit nga adlaw"], "fact": {"tl": "Halos buong maghapon na nakalubog sa tubig ang hippo para hindi mainitan ang balat nito.", "en": "A hippo stays soaking in the water most of the day so its skin does not get too hot.", "bis": "Ang hippo halos tibuok adlaw nga naglubong sa tubig aron dili mainitan ang iyang panit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hippo-big-mouth-g3", "domain": "LIVING_THINGS", "topic": "hippo big mouth jaws", "grades": [3, 4, 5], "terms": ["hippo", "ipopotamo", "malaking bibig", "nguso", "ngipin", "bukas", "big mouth", "jaws", "baba", "dakong baba", "ngipon", "abli nga baba"], "fact": {"tl": "Kayang ibuka ng hippo ang napakalaking bibig nito nang sobrang lapad.", "en": "A hippo can open its very large mouth extremely wide.", "bis": "Ang hippo makahimo sa pag-abli sa iyang dako kaayo nga baba og halapad kaayo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "horse-sleeps-standing-g4", "domain": "LIVING_THINGS", "topic": "horse sleeps standing up", "grades": [4, 5, 6], "terms": ["kabayo", "horse", "tayo", "natutulog", "nakatayo", "standing", "sleep", "paa", "tindog", "natulog", "nagtindog", "tiil"], "fact": {"tl": "Kayang matulog ng kabayo nang nakatayo dahil hindi nababaluktot ang mga binti nito kahit pagod.", "en": "A horse can sleep while standing up because its legs can lock and not buckle.", "bis": "Ang kabayo makahimo sa pagkatulog nga nagtindog tungod kay ang iyang mga paa makaharang ug dili matumba bisan pagod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "horse-runs-fast-hooves-g3", "domain": "LIVING_THINGS", "topic": "horse runs fast hooves", "grades": [3, 4, 5], "terms": ["kabayo", "horse", "takbo", "mabilis", "kuko", "paa", "run", "fast", "hooves", "kuko sa paa", "tiil", "kusog modagan", "modagan"], "fact": {"tl": "Mabilis tumakbo ang kabayo gamit ang matitigas nitong kuko sa paa.", "en": "A horse can run fast using the hard hooves on its feet.", "bis": "Ang kabayo kusog modagan pinaagi sa gahi nga kuko sa iyang mga tiil."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rodent-teeth-grow-g5", "domain": "LIVING_THINGS", "topic": "rodent teeth keep growing", "grades": [5, 6, 7], "terms": ["daga", "rodent", "ngipin", "tumutubo", "ngangatngat", "gnaw", "teeth grow", "mouse", "ilaga", "ngipon", "motubo", "kagat", "mangagat"], "fact": {"tl": "Ang mga ngipin sa harap ng mga daga ay patuloy na tumutubo, kaya kailangan nilang ngumatngat para hindi humaba ang mga ito.", "en": "A rodent's front teeth keep growing, so it must gnaw to keep them from getting too long.", "bis": "Ang atubangang ngipon sa ilaga padayon nga motubo, busa kinahanglan kini mangagat aron dili motaas kaayo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rodent-group-examples-g4", "domain": "LIVING_THINGS", "topic": "rodents group mouse rat squirrel", "grades": [4, 5, 6], "terms": ["daga", "rodent", "ilaga", "squirrel", "beaver", "grupo", "uri", "mouse", "rat", "rodents", "ardilya", "klase", "matang", "grupo sa hayop"], "fact": {"tl": "Ang mga daga, ilaga, at squirrel ay pawang kabilang sa grupo ng mga hayop na tinatawag na rodents.", "en": "Mice, rats, and squirrels all belong to a group of animals called rodents.", "bis": "Ang ilaga ug ang squirrel tanan sakop sa grupo sa mga hayop nga gitawag og rodents."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mammals-have-fur-milk-g3", "domain": "LIVING_THINGS", "topic": "mammals fur hair milk", "grades": [3, 4, 5], "terms": ["mammal", "hayop na may suso", "balahibo", "gatas", "fur", "milk", "hair", "anak", "suso", "buhok", "hayop nga may suso"], "fact": {"tl": "Ang mga mammal ay may balahibo o buhok at pinapasuso ng gatas ang kanilang mga anak.", "en": "Mammals have fur or hair and feed their babies with milk.", "bis": "Ang mga mammal adunay balahibo o buhok ug magpasuso og gatas sa ilang mga anak."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mammals-warm-blooded-g5", "domain": "LIVING_THINGS", "topic": "mammals warm blooded", "grades": [5, 6, 7], "terms": ["mammal", "mainit ang dugo", "temperatura", "katawan", "warm-blooded", "body temperature", "init sa lawas", "init nga dugo", "temperatura sa lawas", "hayop nga may suso"], "fact": {"tl": "Ang mga mammal ay warm-blooded, ibig sabihin pinapanatili nila ang init ng kanilang katawan kahit malamig sa paligid.", "en": "Mammals are warm-blooded, meaning they keep their body warm even when it is cold around them.", "bis": "Ang mga mammal warm-blooded, buot ipasabot ginabantayan nila ang kainit sa ilang lawas bisan bugnaw ang palibot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "elephant-largest-baby-g5", "domain": "LIVING_THINGS", "topic": "elephant long pregnancy big calf", "grades": [5, 6, 7], "terms": ["elepante", "anak", "buntis", "matagal", "calf", "pregnancy", "baby elephant", "nati", "mabdos", "dugay", "anak sa elepante", "nag-anak"], "fact": {"tl": "Napakatagal bago manganak ang elepante, at malaki na agad ang anak nito pagsilang.", "en": "An elephant is pregnant for a very long time, and its baby is already big when it is born.", "bis": "Ang elepante dugay kaayo nga mabdos, ug dako na dayon ang iyang anak inig-anak."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "monkey-lives-in-groups-g4", "domain": "LIVING_THINGS", "topic": "monkeys live in groups troop", "grades": [4, 5, 6], "terms": ["unggoy", "monkey", "grupo", "pangkat", "magkasama", "troop", "group", "tumulong", "amo", "ikog", "panon", "grupo sa unggoy", "nagtipon", "magtinabangay"], "fact": {"tl": "Maraming unggoy ang namumuhay nang sama-sama sa isang grupo para magtulungan at magbantayan.", "en": "Many monkeys live together in a group so they can help and watch out for each other.", "bis": "Daghang unggoy nagpuyo nga magkauban sa usa ka grupo aron magtinabangay ug magbantay sa usag usa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-invertebrate-no-backbone-g3", "domain": "LIVING_THINGS", "topic": "invertebrates", "grades": [3, 4, 5], "terms": ["invertebrate", "backbone", "spine", "walang gulugod", "gulugod", "buto sa likod", "walay bukobuko", "bukobuko", "worm", "snail", "crab", "insect", "bulate", "kuhol", "alimango", "insekto", "more than 90 percent", "karamihan", "kadaghanan"], "fact": {"tl": "Ang invertebrate ay hayop na WALANG gulugod (backbone) o buto sa likod, gaya ng bulate, kuhol, alimango, at insekto. Higit sa 9 sa bawat 10 hayop sa mundo ay invertebrate.", "en": "An invertebrate is an animal with NO backbone, like worms, snails, crabs, and insects. More than 9 out of every 10 animals on Earth are invertebrates.", "bis": "Ang invertebrate usa ka hayop nga WALAY bukobuko (backbone) o bukog sa likod, sama sa bulate, kuhol, alimango, ug insekto. Kapin sa 9 sa matag 10 ka hayop sa kalibotan mga invertebrate."}, "source": "AAAS BSL Ch.5 (diversity of life); NRC LS4.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-earthworm-soil-g4", "domain": "LIVING_THINGS", "topic": "earthworms", "grades": [3, 4, 5], "terms": ["earthworm", "bulate", "wati", "ulod sa yuta", "soil", "lupa", "yuta", "tunnel", "butas", "hangin", "hingahan", "makanunot", "ground", "tilapon", "nagpapataba ng lupa", "tabunok", "mineral"], "fact": {"tl": "Ang bulate sa lupa (earthworm) ay kumakain ng lupa at bulok na dahon, at ang inilalabas nito ay nagpapataba sa lupa para sa mga halaman. Ang mga butas na ginagawa nito ang nagpapasok ng hangin at tubig sa lupa.", "en": "An earthworm eats soil and rotting leaves, and its droppings make the soil rich for plants. The tunnels it digs let air and water into the ground.", "bis": "Ang bulate sa yuta (earthworm) mokaon og yuta ug dunot nga dahon, ug ang iyang tae makapatambok sa yuta para sa mga tanom. Ang mga lungag nga iyang kalotan magpasulod og hangin ug tubig sa yuta."}, "source": "encyclopedia-stable consensus; NRC LS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-snail-shell-g3", "domain": "LIVING_THINGS", "topic": "snails", "grades": [3, 4], "terms": ["snail", "kuhol", "kuhul", "bagongon", "shell", "kabibe", "bahay", "balay", "kabhang", "protect", "nagtatago", "mosulod", "slime", "uhog", "laway", "slimy trail", "tumutubo kasama", "mokamang"], "fact": {"tl": "Ang kuhol (snail) ay may matigas na bahay (shell) sa likod na tumutubo kasama nito; pag may panganib, nagtatago ito sa loob. Lumalakad ito sa makapit na uhog (slime) na inilalabas nito.", "en": "A snail has a hard shell on its back that grows with it; when there is danger, it hides inside. It moves along on a sticky slime it makes.", "bis": "Ang kuhol (snail) adunay gahi nga balay (shell) sa likod nga motubo uban niini; kung adunay kakuyaw, mosulod kini sa sulod. Mokamang kini diha sa pilit nga uhog (slime) nga iyang gibuga."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-slug-no-shell-g4", "domain": "LIVING_THINGS", "topic": "slugs", "grades": [4, 5], "terms": ["slug", "slag", "kuhol na walang bahay", "walang shell", "walay kabhang", "moist", "basa-basa", "mamasa-masa", "dry", "natutuyo", "nauga", "gabii", "gabi-i", "night", "damp", "mollusk", "mga molusko", "related to snail"], "fact": {"tl": "Ang slug ay parang kuhol na walang bahay (shell), kaya kailangan nitong manatiling basa-basa para hindi matuyo at mamatay. Kadalasan itong lumalabas sa gabi o kapag mamasa-masa.", "en": "A slug is like a snail without a shell, so it must stay moist or it dries out and dies. It usually comes out at night or when it is damp.", "bis": "Ang slug murag kuhol nga walay balay (shell), busa kinahanglan kini magpabiling mamasa-masa kay basig mauga ug mamatay. Kasagaran mogawas kini sa gabii o kung umog ang palibot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-mollusk-soft-body-g5", "domain": "LIVING_THINGS", "topic": "mollusks", "grades": [5, 6], "terms": ["mollusk", "molusko", "soft body", "malambot na katawan", "humok nga lawas", "kuhol", "snail", "tahong", "mussel", "talaba", "oyster", "clam", "octopus", "pugita", "kugita", "shell maker", "gumagawa ng kabibe", "grupo", "group"], "fact": {"tl": "Ang mga molusko (mollusks) ay grupo ng malalambot ang katawan na hayop tulad ng kuhol, tahong, talaba, at pugita; karamihan sa kanila ay may matigas na kabibe (shell) na sila mismo ang gumagawa.", "en": "Mollusks are a group of soft-bodied animals like snails, mussels, oysters, and octopuses; most of them make their own hard shell.", "bis": "Ang mga mollusk usa ka grupo sa humok og lawas nga mga hayop sama sa kuhol, tahong, talaba, ug kugita; kadaghanan nila adunay gahi nga kabhang (shell) nga sila mismo ang naghimo."}, "source": "AAAS BSL Ch.5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-crustacean-exoskeleton-g5", "domain": "LIVING_THINGS", "topic": "crustaceans", "grades": [5, 6], "terms": ["crustacean", "krustaseo", "crab", "alimango", "alimasag", "shrimp", "hipon", "pasayan", "ulang", "lobster", "banghai", "molt", "nagpapalit ng balat", "mag-ilis", "panit", "hard shell", "matigas na balat", "gahi nga panit", "exoskeleton", "balahibo sa gawas", "gills", "hasang"], "fact": {"tl": "Ang mga krustaseo (crustaceans) gaya ng alimango, hipon, at ulang ay may matigas na balat sa labas (exoskeleton) sa halip na buto sa loob. Para lumaki, kailangan nilang magpalit ng lumang balat (molting).", "en": "Crustaceans like crabs, shrimp, and lobsters have a hard shell on the outside (exoskeleton) instead of bones inside. To grow, they must shed their old shell (molting).", "bis": "Ang mga crustacean sama sa alimango, hipon, ug ulang adunay gahi nga panit sa gawas (exoskeleton) imbis bukog sa sulod. Aron motubo, kinahanglan silang mag-ilis sa daan nga panit (molting)."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.5", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-crab-sideways-claws-g3", "domain": "LIVING_THINGS", "topic": "crabs", "grades": [3, 4], "terms": ["crab", "alimango", "alimasag", "kasag", "claw", "sipit", "sipot", "pincers", "pang-ipit", "sideways", "patagilid", "walking", "naglalakad", "molakaw", "ten legs", "sampung paa", "napulo ka tiil", "eyes on stalks", "mata sa tangkay"], "fact": {"tl": "Ang alimango (crab) ay may sampung paa, kasama na ang dalawang malalaking sipit na pang-ipit at pananggol. Karaniwan itong naglalakad nang patagilid.", "en": "A crab has ten legs, including two big claws used for grabbing and for defense. It usually walks sideways.", "bis": "Ang alimango (crab) adunay napulo ka tiil, lakip ang duha ka dagkong sipit nga gamiton sa pagkupot ug sa pagdepensa. Kasagaran molakaw kini nga patagilid."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-hermit-crab-borrowed-shell-g4", "domain": "LIVING_THINGS", "topic": "hermit crabs", "grades": [4, 5], "terms": ["hermit crab", "umang", "bahay-bahayan", "hinarmit", "borrowed shell", "hiniram na kabibe", "hinulaman nga kabhang", "empty shell", "walang laman na kabibe", "soft tail", "malambot na buntot", "humok nga ikog", "grows", "lumalaki", "lumilipat", "mobalhin", "bigger shell"], "fact": {"tl": "Ang hermit crab (umang) ay walang sariling matigas na kabibe sa buntot, kaya naninirahan ito sa walang laman na kabibe ng patay na kuhol. Pag lumaki ito, lumilipat ito sa mas malaking kabibe.", "en": "A hermit crab has no hard shell of its own on its tail, so it lives inside an empty shell from a dead snail. As it grows, it moves into a bigger shell.", "bis": "Ang hermit crab (umang) walay kaugalingong gahi nga kabhang sa ikog, busa mopuyo kini sulod sa walay sulod nga kabhang sa patay nga kuhol. Kung motubo na kini, mobalhin kini sa mas dako nga kabhang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-starfish-arms-regrow-g4", "domain": "LIVING_THINGS", "topic": "starfish", "grades": [4, 5, 6], "terms": ["starfish", "sea star", "bituin sa dagat", "starfis", "tihik-tihik", "arms", "braso", "bukton", "regrow", "tumutubo muli", "motubo balik", "regenerate", "nawalang braso", "five arms", "limang braso", "lima ka bukton", "no brain", "walang utak", "walay utok", "tube feet"], "fact": {"tl": "Ang bituin sa dagat (starfish) ay karaniwang may limang braso, at kayang nitong magpatubo muli ng nawalang braso. Wala itong utak ni dugo na tulad natin.", "en": "A starfish (sea star) usually has five arms and can regrow an arm it loses. It has no brain or blood like ours.", "bis": "Ang bituon sa dagat (starfish) kasagaran adunay lima ka bukton, ug makahimo kini og pagtubo balik sa nawala nga bukton. Wala kini utok o dugo nga sama sa ato."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-starfish-tube-feet-g5", "domain": "LIVING_THINGS", "topic": "starfish", "grades": [5, 6], "terms": ["starfish", "sea star", "bituin sa dagat", "tube feet", "maliliit na paa", "gagmay nga tiil", "tubular feet", "water", "tubig", "stick", "kumakapit", "mokapit", "crawl", "gumagapang", "mokamang", "underside", "ilalim", "ubos", "stomach", "tiyan", "sea floor"], "fact": {"tl": "Ang starfish ay gumagalaw gamit ang daan-daang maliliit na paa (tube feet) na napupuno ng tubig sa ilalim ng braso nito. Ginagamit din nito ang mga ito para kumapit sa bato at buksan ang kabibe ng biktima.", "en": "A starfish moves using hundreds of tiny tube feet filled with water on the underside of its arms. It also uses them to grip rocks and pry open the shells of its prey.", "bis": "Ang starfish molihok pinaagi sa gatosan ka gagmayng tiil (tube feet) nga napuno og tubig sa ilawom sa iyang mga bukton. Gigamit usab niini kini aron mokapit sa bato ug aron ablihan ang kabhang sa iyang biktima."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-coral-is-animal-g5", "domain": "LIVING_THINGS", "topic": "corals", "grades": [5, 6, 7], "terms": ["coral", "koral", "bahura", "corals are animals", "hayop ang koral", "hayop ang bahura", "polyp", "polip", "tiny animals", "maliliit na hayop", "gagmayng hayop", "not a plant", "hindi halaman", "dili tanom", "not a rock", "hindi bato", "limestone", "skeleton", "tentacles", "galamay"], "fact": {"tl": "Ang koral (coral) ay HINDI bato o halaman kundi binubuo ng libo-libong napakaliliit na hayop na tinatawag na polyp. Bawat polyp ay gumagawa ng matigas na kalansay na nagiging bahura (reef).", "en": "A coral is NOT a rock or a plant; it is made of thousands of tiny animals called polyps. Each polyp builds a hard skeleton, and together they form a reef.", "bis": "Ang coral DILI bato o tanom kondili gilangkoban sa liboan ka gagmay kaayong hayop nga gitawag og polyp. Matag polyp maghimo og gahi nga kalansay nga mahimong bahura (reef)."}, "source": "encyclopedia-stable consensus; NRC LS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-coral-algae-partner-g6", "domain": "LIVING_THINGS", "topic": "corals", "grades": [6, 7, 8], "terms": ["coral", "koral", "bahura", "algae", "lumot", "algae sa sulod", "zooxanthellae", "partner", "magkatuwang", "magtinabangay", "sunlight", "liwanag ng araw", "kahayag", "food", "pagkain", "color", "kulay", "kolor", "coral bleaching", "namuti", "namuputi", "mamuti", "warm water", "mainit na tubig", "init"], "fact": {"tl": "Ang koral ay may maliliit na lumot (algae) na nakatira sa loob nito na gumagawa ng pagkain mula sa sikat ng araw; ito rin ang nagbibigay ng kulay sa koral. Kapag sobrang init ng tubig, umaalis ang lumot at namumuti ang koral (coral bleaching).", "en": "Coral has tiny algae living inside it that make food from sunlight and give the coral its color. When the water gets too warm, the algae leave and the coral turns white (coral bleaching).", "bis": "Ang coral adunay gagmayng lumot (algae) nga nagpuyo sulod niini nga maghimo og pagkaon gikan sa kahayag sa adlaw ug naghatag sa kolor sa coral. Kung mainit na kaayo ang tubig, mobiya ang lumot ug mamuti ang coral (coral bleaching)."}, "source": "encyclopedia-stable consensus; NRC LS2.A/LS2.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-sponge-filter-feeder-g5", "domain": "LIVING_THINGS", "topic": "sponges", "grades": [5, 6], "terms": ["sponge", "espongha", "spongha", "sea sponge", "esponghang dagat", "filter", "sinasala", "sinala", "food from water", "pagkain sa tubig", "holes", "butas", "mga lungag", "pores", "poro", "simplest animal", "pinakasimpleng hayop", "no organs", "walang organ", "walay organ", "stays in one place", "nakadikit", "mopilit", "does not move"], "fact": {"tl": "Ang espongha (sponge) ay isa sa pinakasimpleng hayop: nakadikit ito sa isang lugar at sinasala ang pagkain mula sa tubig na dumadaan sa libo-libong butas nito. Wala itong utak, puso, o iba pang organ.", "en": "A sponge is one of the simplest animals: it stays in one place and filters food from the water flowing through its thousands of holes. It has no brain, heart, or other organs.", "bis": "Ang espongha (sponge) usa sa pinakasimpleng hayop: mopilit kini sa usa ka lugar ug mosala sa pagkaon gikan sa tubig nga moagi sa liboan niini ka lungag. Wala kini utok, kasingkasing, o ubang organ."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.5", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-centipede-legs-pairs-g4", "domain": "LIVING_THINGS", "topic": "centipedes", "grades": [4, 5, 6], "terms": ["centipede", "alupihan", "ulahipan", "uhipan", "legs", "paa", "tiil", "one pair per segment", "isang pares kada segment", "fast", "mabilis", "paspas", "predator", "mandaragit", "mangangaso", "venom", "kamandag", "hilo", "bite", "kagat", "paak", "flat body", "patag na katawan", "not exactly 100"], "fact": {"tl": "Ang alupihan (centipede) ay may mahabang katawan na hati sa mga segment, at may isang pares ng paa sa bawat segment. Mabilis itong mangangaso at gumagamit ng kamandag para hulihin ang maliliit na hayop.", "en": "A centipede has a long body divided into segments, with one pair of legs on each segment. It is a fast hunter and uses venom to catch small animals.", "bis": "Ang alupihan (centipede) adunay taas nga lawas nga nabahin sa mga segment, ug adunay usa ka paris nga tiil sa matag segment. Paspas kini nga mangangaso ug mogamit og hilo aron dakpon ang gagmayng hayop."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-millipede-vs-centipede-g5", "domain": "LIVING_THINGS", "topic": "millipedes", "grades": [5, 6], "terms": ["millipede", "alupihang gabe", "antipelo", "ulahipan nga lukot", "two pairs per segment", "dalawang pares kada segment", "centipede", "alupihan", "curl up", "nagiging bilog", "mibilot", "slow", "mabagal", "hinay", "eats dead leaves", "kumakain ng patay na dahon", "mokaon og dahon", "not a predator", "hindi mandaragit", "more legs"], "fact": {"tl": "Ang millipede ay kahawig ng alupihan pero may DALAWANG pares ng paa kada segment at mas marami itong paa. Mabagal ito, kumakain ng bulok na dahon, at namimilipit (nagiging bilog) kapag natatakot, hindi nangangagat gaya ng alupihan.", "en": "A millipede looks like a centipede but has TWO pairs of legs per segment and many more legs. It is slow, eats rotting leaves, and curls into a ball when scared instead of biting like a centipede.", "bis": "Ang millipede morag alupihan apan adunay DUHA ka paris nga tiil matag segment ug mas daghan og tiil. Hinay kini, mokaon og dunot nga dahon, ug mobilot (mahimong bilog) kung mahadlok imbis mopaak sama sa alupihan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-jellyfish-no-bones-g4", "domain": "LIVING_THINGS", "topic": "jellyfish", "grades": [4, 5], "terms": ["jellyfish", "dikya", "sea jelly", "salabay", "bukal", "no bones", "walang buto", "walay bukog", "no brain", "walang utak", "walay utok", "mostly water", "puro tubig", "tubig ang kadaghanan", "tentacles", "galamay", "sumusunod sa agos", "drift", "naglulutang", "molutaw", "sting", "makakapaso"], "fact": {"tl": "Ang dikya (jellyfish) ay walang buto, walang utak, at walang puso, at halos puro tubig ang katawan nito. Naglulutang lang ito sa dagat at sumusunod sa agos.", "en": "A jellyfish has no bones, no brain, and no heart, and its body is almost all water. It simply drifts in the sea and follows the current.", "bis": "Ang dikya (jellyfish) walay bukog, walay utok, ug walay kasingkasing, ug halos puro tubig ang iyang lawas. Molutaw lang kini sa dagat ug mosunod sa sulog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-jellyfish-stinging-tentacles-g5", "domain": "LIVING_THINGS", "topic": "jellyfish", "grades": [5, 6], "terms": ["jellyfish", "dikya", "salabay", "tentacles", "galamay", "sumusunod", "sting", "makakapaso", "makapaso", "mamaak", "stinging cells", "stinging", "nakakapasong selula", "tublog", "catch prey", "manghuli", "mangdakop", "defense", "pananggol", "depensa", "careful", "mag-ingat", "pag-amping", "do not touch"], "fact": {"tl": "Ang mahahabang galamay (tentacles) ng dikya ay may maliliit na nakakapasong selula na ginagamit nito para mahuli ang pagkain at ipagtanggol ang sarili. Kahit patay nang nakahandusay sa buhangin, kaya pa nitong makapaso, kaya mag-ingat.", "en": "A jellyfish's long tentacles have tiny stinging cells it uses to catch food and defend itself. Even a dead one lying on the sand can still sting, so be careful.", "bis": "Ang taas nga galamay (tentacles) sa dikya adunay gagmayng selula nga makapaso nga gamiton niini sa pagdakop og pagkaon ug sa pagdepensa. Bisan patay na nga naghigda sa balas, makapaso pa gihapon kini, busa pag-amping."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-sea-anemone-clownfish-g5", "domain": "LIVING_THINGS", "topic": "sea anemones", "grades": [5, 6], "terms": ["sea anemone", "anemone", "bulaklak sa dagat", "anemonong dagat", "clownfish", "nemo", "clown fish", "tentacles", "galamay", "sting", "makapaso", "protect", "ipinagtatanggol", "panalipdan", "symbiosis", "magkatuwang", "magtinabangay", "partner", "mutualism", "stuck to rock", "nakadikit sa bato"], "fact": {"tl": "Ang sea anemone ay hayop na mukhang bulaklak at may nakakapasong galamay; nakadikit ito sa bato sa dagat. Ang clownfish (Nemo) ay nakakatira nang ligtas sa loob nito dahil hindi ito tinatablan ng kamandag ng anemone.", "en": "A sea anemone is an animal that looks like a flower and has stinging tentacles; it stays stuck to a rock in the sea. The clownfish (Nemo) can live safely among its tentacles because it is not harmed by the anemone's sting.", "bis": "Ang sea anemone usa ka hayop nga morag bulak ug adunay galamay nga makapaso; mopilit kini sa bato sa dagat. Ang clownfish (Nemo) makapuyo nga luwas sulod niini kay dili kini matandog sa hilo sa anemone."}, "source": "encyclopedia-stable consensus; NRC LS2.A (interactions)", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-leech-blood-g5", "domain": "LIVING_THINGS", "topic": "leeches", "grades": [5, 6], "terms": ["leech", "linta", "alimatok", "blood", "dugo", "sumisipsip", "mosuyop", "mosipsip", "wetland", "basang lugar", "umog nga dapit", "sucker", "panghigop", "worm relative", "kamag-anak ng bulate", "paryente sa bulate", "painless bite", "hindi masakit na kagat", "two suckers", "dalawang panghigop"], "fact": {"tl": "Ang linta (leech) ay isang uri ng bulate na may dalawang panghigop (sucker) at sumisipsip ng dugo ng ibang hayop o tao. Karaniwan itong matatagpuan sa basa o maputik na lugar.", "en": "A leech is a kind of worm with two suckers that feeds by sucking the blood of other animals or people. It is usually found in wet or muddy places.", "bis": "Ang alimatok (leech) usa ka matang sa bulate nga adunay duha ka panghigop (sucker) ug mosuyop sa dugo sa ubang hayop o tawo. Kasagaran makit-an kini sa basa o lapokon nga dapit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-snail-teeth-radula-g6", "domain": "LIVING_THINGS", "topic": "snails", "grades": [6, 7], "terms": ["snail", "kuhol", "radula", "tongue with teeth", "dilang may ngipin", "dila nga adunay ngipin", "thousands of teeth", "libong ngipin", "liboan ka ngipin", "scrape food", "kinakayod", "gikiskis", "grazing", "most teeth", "pinakamaraming ngipin", "tiny teeth", "gagmay nga ngipin"], "fact": {"tl": "Ang kuhol (snail) ay kumakain gamit ang isang parang dila na may libo-libong napakaliliit na ngipin (radula) na ginagamit nito para magkayod ng pagkain. Ilang uri ng kuhol ang may pinakamaraming ngipin sa lahat ng hayop.", "en": "A snail eats using a tongue-like part covered with thousands of tiny teeth (the radula) that it uses to scrape up food. Some snails have more teeth than any other animal.", "bis": "Ang kuhol (snail) mokaon gamit ang murag dila nga adunay liboan ka gagmay kaayong ngipin (radula) nga gamiton niini sa pagkiskis sa pagkaon. Ang ubang kuhol adunay mas daghang ngipin kaysa bisan unsang laing hayop."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-shrimp-vs-prawn-g4", "domain": "LIVING_THINGS", "topic": "shrimp", "grades": [4, 5], "terms": ["shrimp", "hipon", "prawn", "sugpo", "pasayan", "ulang", "swimming legs", "pang-langoy na paa", "tiil panglangoy", "antennae", "sungot", "feelers", "long whiskers", "mahabang sungot", "mga bagyong tubig", "backward swim", "paatras na langoy", "molangoy paatras", "tail flick", "molukso"], "fact": {"tl": "Ang hipon (shrimp) ay maliit na krustaseo na may mahahabang sungot (antennae) at mga paa para lumangoy. Pag natatakot, biglang lumalangoy ito paatras sa pamamagitan ng mabilis na pagpaspas ng buntot.", "en": "A shrimp is a small crustacean with long feelers (antennae) and legs for swimming. When startled, it suddenly darts backward by quickly flicking its tail.", "bis": "Ang hipon (shrimp) usa ka gamay nga crustacean nga adunay tag-as nga sungot (antennae) ug mga tiil para molangoy. Kung makuratan, kalit kini molangoy paatras pinaagi sa paspas nga pagpaypay sa iyang ikog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-worm-segments-g4", "domain": "LIVING_THINGS", "topic": "worms", "grades": [4, 5], "terms": ["worm", "bulate", "ulod", "earthworm", "segments", "singsing-singsing", "mga bahin", "tunay na bulate", "ringed body", "singsing na katawan", "liso-liso nga lawas", "no legs", "walang paa", "walay tiil", "no eyes", "walang mata", "walay mata", "feels light", "nakakaramdam", "squeeze through", "gumagapang"], "fact": {"tl": "Ang tunay na bulate (worm) gaya ng bulate sa lupa ay may pahaba at malambot na katawan na hati sa maliliit na singsing o segment, walang paa, at walang tunay na mata. Naglalakbay ito sa pamamagitan ng pagkurot at pag-unat ng mga segment nito.", "en": "A true worm like an earthworm has a long, soft body divided into little rings or segments, no legs, and no real eyes. It moves by squeezing and stretching its segments.", "bis": "Ang tinuod nga bulate (worm) sama sa bulate sa yuta adunay taas ug humok nga lawas nga nabahin sa gagmayng singsing o segment, walay tiil, ug walay tinuod nga mata. Molihok kini pinaagi sa pagkomprés ug pag-inat sa iyang mga segment."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.5", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-crab-molting-soft-g6", "domain": "LIVING_THINGS", "topic": "crabs", "grades": [6, 7], "terms": ["crab", "alimango", "molting", "nagpapalit ng balat", "mag-ilis sa panit", "soft shell crab", "malambot na alimango", "humok nga alimango", "new shell", "bagong balat", "hardens", "tumitigas", "mogahi", "vulnerable", "mahina", "luya", "hides", "nagtatago", "mosulod", "grow bigger", "lumaki", "dako"], "fact": {"tl": "Para lumaki, hinuhubad ng alimango ang lumang matigas nitong balat (molting); pagkatapos, malambot muna ang bagong balat bago tuluyang tumigas. Sa panahong iyon, mahina ito at nagtatago dahil madali itong masaktan.", "en": "To grow, a crab sheds its old hard shell (molting); afterward its new shell is soft until it slowly hardens. During that time the crab is weak and hides, because it is easily hurt.", "bis": "Aron motubo, ang alimango mohukas sa daan niyang gahi nga panit (molting); human niini, humok una ang bag-ong panit hangtod nga hinay-hinay kining mogahi. Niadtong panahona luya kini ug motago, kay sayon ra kining masakitan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-coral-reef-home-g5", "domain": "LIVING_THINGS", "topic": "coral reefs", "grades": [5, 6, 7], "terms": ["coral reef", "bahura", "koral reef", "reef", "habitat", "tirahan", "puy-anan", "home for fish", "tahanan ng isda", "balay sa isda", "biodiversity", "sari-saring buhay", "nagkalainlaing buhay", "rainforest of the sea", "gubat sa dagat", "Philippines", "Pilipinas", "Coral Triangle", "shelter", "kanlungan", "silonganan"], "fact": {"tl": "Ang bahura (coral reef) ay tirahan ng libo-libong uri ng isda at iba pang hayop sa dagat, kaya tinatawag itong 'gubat-tropiko ng dagat.' Ang Pilipinas ay bahagi ng Coral Triangle na may isa sa pinakamayamang bahura sa mundo.", "en": "A coral reef is home to thousands of kinds of fish and other sea animals, which is why it is called the 'rainforest of the sea.' The Philippines is part of the Coral Triangle, which has some of the richest reefs in the world.", "bis": "Ang bahura (coral reef) maoy puy-anan sa liboan ka klase sa isda ug ubang hayop sa dagat, mao nga gitawag kini nga 'lasang sa dagat.' Ang Pilipinas bahin sa Coral Triangle nga adunay usa sa pinakaadunahang bahura sa kalibotan."}, "source": "encyclopedia-stable consensus; NRC LS2.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-golden-apple-snail-pest-g6", "domain": "LIVING_THINGS", "topic": "snails", "grades": [6, 7], "terms": ["golden apple snail", "golden kuhol", "kuhol sa palayan", "kuhol sa basakan", "rice pest", "peste sa palay", "peste sa humay", "pink eggs", "kulay-rosas na itlog", "pink nga itlog", "palay", "rice seedlings", "punla", "binhi", "invasive", "dayuhang species", "langyaw", "Philippines", "Pilipinas", "damage", "pinsala", "kadaot"], "fact": {"tl": "Ang golden kuhol (golden apple snail) ay dayuhang kuhol na naging peste sa mga palayan sa Pilipinas dahil kinakain nito ang murang punla ng palay. Madali itong makilala sa kulay-rosas nitong mga itlog na nakadikit sa mga tangkay.", "en": "The golden apple snail is a foreign snail that became a pest in Philippine rice fields because it eats young rice seedlings. It is easy to spot by its pink eggs stuck on stems.", "bis": "Ang golden kuhol (golden apple snail) usa ka langyaw nga kuhol nga nahimong peste sa mga basakan sa Pilipinas kay mokaon kini sa bata pa nga punla sa humay. Sayon kini mailhan pinaagi sa iyang pink nga mga itlog nga nipilit sa mga punoan."}, "source": "encyclopedia-stable consensus; DepEd PH agriculture context", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-barnacle-stuck-g5", "domain": "LIVING_THINGS", "topic": "barnacles", "grades": [5, 6], "terms": ["barnacle", "kabibe sa bato", "susô sa bato", "pukot-pukot", "tiny crustacean", "maliit na krustaseo", "glued", "nakadikit", "mopilit", "rocks", "bato", "boats", "bangka", "barko", "filter feeding", "sinasala ang pagkain", "feathery legs", "balahibong paa", "balhiboon nga tiil", "not a mollusk", "hindi molusko", "cement"], "fact": {"tl": "Ang barnacle ay maliit na krustaseo (kamag-anak ng alimango) na nakadikit nang husto sa bato, bangka, o kahit balyena. Inilalabas nito ang parang balahibong mga paa para salain ang pagkain mula sa tubig.", "en": "A barnacle is a tiny crustacean (a relative of crabs) that glues itself firmly to rocks, boats, or even whales. It sticks out feathery legs to filter food from the water.", "bis": "Ang barnacle usa ka gamay nga crustacean (paryente sa alimango) nga mopilit og maayo sa bato, sakayan, o bisan balyena. Mopagawas kini og murag balhibo nga mga tiil aron mosala og pagkaon gikan sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-starfish-eats-coral-g7", "domain": "LIVING_THINGS", "topic": "crown-of-thorns starfish", "grades": [7, 8], "terms": ["crown-of-thorns starfish", "dapag", "crown of thorns", "starfish na may tinik", "spiny starfish", "tinikon nga starfish", "eats coral", "kumakain ng koral", "mokaon og coral", "reef damage", "pinsala sa bahura", "outbreak", "pagdami", "pagdaghan", "venomous spines", "makamandag na tinik", "makahilo nga tunok", "Philippines"], "fact": {"tl": "Ang crown-of-thorns starfish ay malaking bituin sa dagat na may makamandag na mga tinik at kumakain ng buhay na koral. Kapag biglang dumami ang mga ito, malaking bahagi ng bahura ang nasisira.", "en": "The crown-of-thorns starfish is a large sea star covered in venomous spines that feeds on living coral. When their numbers suddenly explode, they can destroy large parts of a reef.", "bis": "Ang crown-of-thorns starfish usa ka dakong bituon sa dagat nga puno og makahilo nga tunok ug mokaon og buhi nga coral. Kung kalit modaghan kini, makaguba sila og dagkong bahin sa bahura."}, "source": "encyclopedia-stable consensus; NRC LS2.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-sand-dollar-relative-g5", "domain": "LIVING_THINGS", "topic": "sand dollars", "grades": [5, 6], "terms": ["sand dollar", "sand dolyar", "starfish relative", "kamag-anak ng bituin sa dagat", "paryente sa bituon sa dagat", "sea urchin", "tuyom", "maritangtang", "flat round", "patag at bilog", "spines", "tinik", "tunok", "tube feet", "star pattern", "hugis-bituin", "disenyong bituin", "buhangin", "sea floor"], "fact": {"tl": "Ang sand dollar ay kamag-anak ng bituin sa dagat at tuyom (sea urchin); patag at bilog ito at natatakpan ng napakaliliit na tinik habang buhay. Sa ibabaw ng patay at puti nitong balát ay may disenyong parang limang-tulis na bituin.", "en": "A sand dollar is a relative of the starfish and sea urchin; it is flat and round and covered in tiny spines when alive. The bleached white shell shows a pattern like a five-pointed star.", "bis": "Ang sand dollar paryente sa bituon sa dagat ug sa tuyom (sea urchin); patag ug lingin kini ug puno og gagmayng tunok samtang buhi. Sa puti na nga kabhang niini makita ang disenyo nga murag lima-ka-tumoy nga bituon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-sea-urchin-spines-g4", "domain": "LIVING_THINGS", "topic": "sea urchins", "grades": [4, 5], "terms": ["sea urchin", "tuyom", "maritangtang", "swaki", "spines", "tinik", "tunok", "round", "bilog", "lingin", "ball of spines", "bolang tinik", "tube feet", "protect", "panananggol", "panalipod", "sharp", "matalim", "tumotuhog", "graze algae", "kumakain ng lumot", "mokaon og lumot", "reef"], "fact": {"tl": "Ang tuyom (sea urchin) ay parang bolang puno ng matatalas na tinik na ginagamit nito para ipagtanggol ang sarili laban sa mga mandaragit. Gumagalaw at kumakain ito ng lumot gamit ang maliliit na paa (tube feet) sa pagitan ng mga tinik.", "en": "A sea urchin is like a ball covered in sharp spines that it uses to protect itself from predators. It moves and grazes on algae using tiny tube feet between its spines.", "bis": "Ang tuyom (sea urchin) murag bola nga puno og hait nga tunok nga gamiton niini sa pagpanalipod batok sa mga manunukob. Molihok ug mokaon kini og lumot gamit ang gagmayng tiil (tube feet) tunga-tunga sa mga tunok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "litmus-indicator-color-g7", "domain": "MATTER", "topic": "acid-base indicators", "grades": [7, 8, 9], "terms": ["litmus", "indicator", "papel litmus", "tagasukat", "kulay", "kolor", "acid", "asido", "base", "mopula", "mo-pula", "asul", "blue", "red", "pula", "nagbabago", "mabag-o", "pagtukoy"], "fact": {"tl": "Ang litmus paper ay isang indicator na nagpapakita kung acid o base ang isang likido sa pamamagitan ng pagbabago ng kulay: pumupula ito sa acid at nagiging asul sa base.", "en": "Litmus paper is an indicator that shows whether a liquid is an acid or a base by changing color: it turns red in acid and blue in a base.", "bis": "Ang litmus paper usa ka indicator nga magpakita kon acid o base ang usa ka likido pinaagi sa pag-usab sa kolor: mopula kini sa acid ug mo-asul sa base."}, "source": "DepEd Science CG (Matter, JHS); AAAS BSL 4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "natural-indicator-cabbage-g6", "domain": "MATTER", "topic": "natural acid-base indicators", "grades": [5, 6, 7], "terms": ["repolyo", "cabbage", "indicator", "natural", "kulay", "kolor", "acid", "base", "mabag-o", "pula", "berde", "gulay", "katas", "duga", "eksperimento", "tagatukoy"], "fact": {"tl": "May mga halaman tulad ng pulang repolyo na maaaring gawing natural indicator: nagbabago ang kulay ng katas nito kapag inihalo sa acid (namumula) o sa base (nagiging berde o asul).", "en": "Some plants like red cabbage can be used as a natural indicator: the color of its juice changes when mixed with an acid (turns pink) or a base (turns green or blue).", "bis": "Adunay mga tanom sama sa pula nga repolyo nga mahimong natural nga indicator: mabag-o ang kolor sa duga niini kon isagol sa acid (mopula) o sa base (mahimong berde o asul)."}, "source": "AAAS BSL 4D; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "neutralization-acid-base-g8", "domain": "MATTER", "topic": "neutralization", "grades": [8, 9, 10], "terms": ["neutralization", "neutralisasyon", "acid", "base", "asido", "pinaghalo", "gisagol", "kanselahin", "mawala", "asin", "salt", "tubig", "tubig", "reaksyon", "balanse"], "fact": {"tl": "Kapag pinaghalo ang isang acid at isang base sa tamang dami, kinakansela nila ang isa't isa (neutralization) at bumubuo ng asin at tubig — kaya hindi na ito masyadong acid o base.", "en": "When an acid and a base are mixed in the right amounts, they cancel each other out (neutralization) and form a salt and water — so it is no longer strongly acidic or basic.", "bis": "Kon sagolon ang usa ka acid ug usa ka base sa saktong gidaghanon, magkanselahay sila (neutralization) ug maghimog asin ug tubig — busa dili na kini kaayo acid o base."}, "source": "DepEd Science CG (Matter, JHS); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "antacid-neutralizes-stomach-g7", "domain": "MATTER", "topic": "antacids neutralize acid", "grades": [6, 7, 8], "terms": ["antacid", "antasido", "gamot", "tabang", "tiyan", "stomach", "asido", "acid", "heartburn", "sobrang asido", "neutralize", "base", "mawala", "kirot", "sakit sa sikmura", "kanselahin"], "fact": {"tl": "Ang antacid na gamot sa sobrang asido sa tiyan ay isang base — kinakansela nito ang labis na acid sa tiyan sa pamamagitan ng neutralization para mawala ang hapdi.", "en": "Antacid medicine for an upset stomach is a base — it cancels the excess acid in the stomach by neutralization to relieve the burning feeling.", "bis": "Ang antacid nga tambal sa sobra nga asido sa tiyan usa ka base — kanselahon niini ang sobra nga acid sa tiyan pinaagi sa neutralization aron mawala ang kasakit."}, "source": "encyclopedia-stable consensus; AAAS BSL 4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "acids-bases-safety-strong-g8", "domain": "MATTER", "topic": "strong acids and bases are dangerous", "grades": [7, 8, 9], "terms": ["malakas na acid", "strong acid", "strong base", "mapanganib", "delikado", "peligroso", "makapaso", "makasunog sa panit", "corrosive", "muriatic", "panit", "ingat", "hugasan", "linis", "kemikal"], "fact": {"tl": "Hindi lahat ng acid at base ay ligtas — ang malalakas na uri tulad ng muriatic acid at malakas na pamputol-langis (lye) ay mapanganib at maaaring makapaso ng balat at mata, kaya dapat maingat at may proteksyon kapag ginagamit.", "en": "Not all acids and bases are safe — strong ones like muriatic acid and strong drain cleaner (lye) are dangerous and can burn skin and eyes, so they must be handled carefully and with protection.", "bis": "Dili tanan nga acid ug base luwas — ang kusgan nga matang sama sa muriatic acid ug kusgan nga drain cleaner (lye) delikado ug makapaso sa panit ug mata, busa kinahanglang amping ug naay proteksyon kon gamiton."}, "source": "encyclopedia-stable consensus; DepEd Science CG (safety)", "generator": "claude-workflow", "reviewed": false},
  {"id": "rust-prevention-paint-g6", "domain": "MATTER", "topic": "preventing rust", "grades": [5, 6, 7], "terms": ["kalawang", "rust", "taya", "pintura", "paint", "grasa", "grease", "langis", "oil", "takip", "tabon", "proteksyon", "pigilan", "mapugngan", "bakal", "puthaw", "oxygen", "hangin"], "fact": {"tl": "Maiiwasan ang pagkalawang ng bakal kung tatakpan ito ng pintura, grasa, o langis upang hindi makaabot dito ang oxygen at tubig na sanhi ng kalawang.", "en": "Rusting of iron can be prevented by coating it with paint, grease, or oil so that the oxygen and water that cause rust cannot reach it.", "bis": "Mapugngan ang pagkataya sa puthaw kon taboni kini og pintura, grasa, o lana aron dili makaabot niini ang oxygen ug tubig nga maoy hinungdan sa taya."}, "source": "AAAS BSL 4D/M6; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "galvanized-iron-zinc-g7", "domain": "MATTER", "topic": "galvanized iron", "grades": [7, 8], "terms": ["yero", "galvanized", "bubong", "roof", "zinc", "sinc", "bakal", "puthaw", "takip", "sanggalang", "proteksyon", "kalawang", "taya", "rust", "atip", "balay", "metal"], "fact": {"tl": "Ang yerong galvanized na ginagamit sa bubong ay binalutan ng manipis na zinc na nagsisilbing sanggalang ng bakal laban sa kalawang.", "en": "Galvanized iron used for roofing is coated with a thin layer of zinc that protects the iron underneath from rusting.", "bis": "Ang galvanized nga yero nga gigamit sa atip giputos og nipis nga zinc nga magsilbing taming sa puthaw batok sa taya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rust-weakens-metal-g6", "domain": "MATTER", "topic": "rust weakens metal", "grades": [5, 6, 7], "terms": ["kalawang", "rust", "taya", "mahina", "humihina", "manipis", "gumuho", "nasisira", "bakal", "puthaw", "metal", "tulay", "barko", "masaha", "durog", "corrosion", "masira"], "fact": {"tl": "Ang kalawang ay hindi lang nagpaparumi ng bakal — pinapahina nito ito sa paglipas ng panahon, kaya maaaring masira ang mga kalawanging tulay, barko, at sasakyan kung hindi inaalagaan.", "en": "Rust does not just make iron look dirty — it weakens the metal over time, so rusty bridges, ships, and vehicles can break down if not maintained.", "bis": "Ang taya dili lang maghimog hugaw sa puthaw — pahuyangon niini kini sa paglabay sa panahon, busa ang tinay-an nga taytayan, barko, ug sakyanan mahimong maguba kon dili atimanon."}, "source": "AAAS BSL 4D/M6; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "smoke-ash-from-burning-g5", "domain": "MATTER", "topic": "smoke and ash from burning", "grades": [4, 5, 6], "terms": ["usok", "smoke", "abo", "ash", "sunog", "pagsusunog", "apoy", "kahoy", "wood", "kayo", "aso", "nasunog", "bagong sangkap", "chemical change", "mawala", "natitira", "gas", "init"], "fact": {"tl": "Kapag nasusunog ang kahoy, nagiging usok, gas, abo, at init ito — mga bagong sangkap na iba na sa orihinal na kahoy, kaya ang pagsusunog ay isang chemical change na hindi na maibabalik.", "en": "When wood burns, it turns into smoke, gas, ash, and heat — new substances different from the original wood, so burning is a chemical change that cannot be reversed.", "bis": "Kon masunog ang kahoy, mahimo kining aso, gas, abo, ug kainit — bag-ong mga sustansya nga lahi na sa orihinal nga kahoy, busa ang pagsunog usa ka chemical change nga dili na mabalik."}, "source": "AAAS BSL 4D; NRC PS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "how-to-put-out-fire-g5", "domain": "MATTER", "topic": "putting out fires", "grades": [4, 5, 6], "terms": ["apoy", "fire", "kalayo", "patayin", "mapalong", "palungin", "tubig", "water", "init", "heat", "oxygen", "gatong", "fuel", "fire triangle", "takpan", "taboni", "ekstinguisher", "ligtas"], "fact": {"tl": "Pinapatay natin ang apoy sa pamamagitan ng pag-alis ng isa sa tatlong kailangan nito: tubig para bawasan ang init, takip para harangin ang oxygen, o pag-alis ng gatong.", "en": "We put out a fire by taking away one of the three things it needs: water to remove heat, a cover to block oxygen, or removing the fuel.", "bis": "Palungon nato ang kalayo pinaagi sa pagkuha sa usa sa tulo ka butang nga gikinahanglan niini: tubig aron makunhuran ang kainit, tabon aron babagan ang oxygen, o pagkuha sa sugnod."}, "source": "NRC PS1.B; AAAS BSL 4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "oil-fire-no-water-g6", "domain": "MATTER", "topic": "oil fires and water", "grades": [6, 7, 8], "terms": ["langis", "oil", "mantika", "grease", "apoy", "kalayo", "fire", "tubig", "water", "huwag", "ayaw", "delikado", "kusina", "kitchen", "lumalaki", "mokalat", "takpan", "taboni", "peligroso", "sunog"], "fact": {"tl": "Huwag bubuhusan ng tubig ang nagliliyab na mantika sa kusina — lumulutang ang langis sa tubig at lalo lang kumakalat ang apoy; sa halip, takpan ito para maputol ang oxygen.", "en": "Never pour water on a grease fire in the kitchen — oil floats on water and this makes the fire spread; instead, cover it to cut off the oxygen.", "bis": "Ayaw bubo-i og tubig ang nagsiga nga mantika sa kusina — molutaw ang lana sa tubig ug mas mokalat hinuon ang kalayo; hinuon, taboni kini aron putlon ang oxygen."}, "source": "encyclopedia-stable consensus; AAAS BSL 4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "cooking-egg-chemical-change-g5", "domain": "MATTER", "topic": "cooking eggs is a chemical change", "grades": [4, 5, 6], "terms": ["itlog", "egg", "luto", "nilaga", "pinrito", "cook", "init", "heat", "puti", "tigas", "matigas", "hilaw", "raw", "chemical change", "hindi na maibabalik", "bagong sangkap", "prito", "pagkaon"], "fact": {"tl": "Kapag niluluto ang itlog, ang malinaw at malabnaw na puti nito ay tumitigas at nagiging puti — isang chemical change dahil hindi na ito maibabalik sa hilaw nitong anyo.", "en": "When an egg is cooked, its clear runny white turns firm and white — a chemical change because it cannot be turned back into its raw form.", "bis": "Kon lutoon ang itlog, ang tin-aw ug labnaw nga puti niini mogahi ug mahimong puti — usa ka chemical change kay dili na kini mabalik sa hilaw niini nga porma."}, "source": "AAAS BSL 4D; NRC PS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "browning-food-cooking-g6", "domain": "MATTER", "topic": "why cooked food browns", "grades": [5, 6, 7], "terms": ["kayumanggi", "brown", "nag-iitim", "naninilaw", "tinapay", "bread", "prito", "fried", "ihaw", "grilled", "init", "heat", "lasa", "amoy", "aroma", "chemical change", "nagbabago", "toast", "sarap"], "fact": {"tl": "Ang init sa pagluluto ang dahilan kung bakit nag-kayumanggi ang tinapay, prito, at iniihaw na pagkain — bumubuo ng bagong sangkap na nagbibigay ng masarap na kulay, amoy, at lasa (isang chemical change).", "en": "Heat in cooking is why bread, fried food, and grilled food turn brown — it forms new substances that give the tasty color, smell, and flavor (a chemical change).", "bis": "Ang kainit sa pagluto maoy hinungdan nganong mahimong brown ang pan, prito, ug sinugbang pagkaon — maghimo kini og bag-ong sustansya nga maghatag sa lami nga kolor, baho, ug lami (usa ka chemical change)."}, "source": "encyclopedia-stable consensus; AAAS BSL 4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "baking-soda-rises-bread-g6", "domain": "MATTER", "topic": "why baked goods rise", "grades": [5, 6, 7], "terms": ["baking soda", "baking powder", "yeast", "lebadura", "tinapay", "cake", "bread", "umaalsa", "mag-alsa", "tumataas", "bula", "carbon dioxide", "gas", "butas", "malambot", "fluffy", "luto", "hurno", "oven"], "fact": {"tl": "Umaalsa ang tinapay at cake dahil ang baking soda o lebadura ay bumubuo ng carbon-dioxide na gas na nag-iiwan ng maliliit na butas, kaya nagiging malambot at mataas ang luto.", "en": "Bread and cake rise because baking soda or yeast produces carbon-dioxide gas that leaves tiny holes, making the baked food soft and fluffy.", "bis": "Mosaka ang pan ug cake tungod kay ang baking soda o lebadura maghimog carbon-dioxide nga gas nga magbilin og gagmayng lungag, busa mahimong humok ug taas ang giluto."}, "source": "encyclopedia-stable consensus; NRC PS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "melting-butter-physical-g4", "domain": "MATTER", "topic": "melting is a physical change", "grades": [3, 4, 5], "terms": ["mantikilya", "butter", "tunaw", "natunaw", "natutunaw", "melt", "init", "heat", "physical change", "pareho", "gihapon", "matigas", "likido", "balik", "mabalik", "sorbetes", "tsokolate", "chocolate"], "fact": {"tl": "Kapag natunaw ang mantikilya o tsokolate sa init, isa lang itong physical change — pareho pa ring sangkap ito at muling tumitigas kapag pinalamig.", "en": "When butter or chocolate melts in heat, it is only a physical change — it is still the same substance and hardens again when cooled.", "bis": "Kon matunaw ang mantikilya o tsokolate sa kainit, usa lang kini ka physical change — pareho gihapon nga sustansya kini ug mogahi pag-usab kon bugnawan."}, "source": "AAAS BSL 4D; NRC PS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "soap-needs-scrubbing-germs-g3", "domain": "MATTER", "topic": "soap and handwashing", "grades": [3, 4], "terms": ["sabon", "soap", "mikrobyo", "germ", "mga mikrobyo", "hugas", "kamot", "hands", "linis", "limpyo", "kuskos", "kusoa", "tubig", "water", "sakit", "disease", "banlaw", "alisin", "mahuhugasan"], "fact": {"tl": "Hindi pinapatay ng sabon ang lahat ng mikrobyo — sa halip, dinudulas at hinahatak nito ang mga ito palayo sa kamay kaya kailangan ng pagkuskos at pagbanlaw para tuluyang maalis.", "en": "Soap does not kill all germs — instead it makes them slippery and lifts them off your hands, so scrubbing and rinsing are needed to wash them fully away.", "bis": "Ang sabon dili mopatay sa tanan nga mikrobyo — hinuon padanlogon ug bira-on niini sila palayo sa kamot, busa kinahanglan ang pagkuskos ug pagbanlaw aron hingpit nga makuha."}, "source": "encyclopedia-stable consensus; AAAS BSL 4", "generator": "claude-workflow", "reviewed": false},
  {"id": "detergent-vs-soap-g6", "domain": "MATTER", "topic": "detergent and grease", "grades": [5, 6, 7], "terms": ["sabon", "detergent", "sabong panlaba", "langis", "grasa", "grease", "oil", "tubig", "water", "hila", "hatak", "molekula", "linis", "limpyo", "mantsa", "stain", "damit", "plato", "emulsyon", "surfactant"], "fact": {"tl": "Ang detergent at sabon ay gumagana sa parehong paraan: hinahati nila ang langis at grasa sa napakaliliit na patak na natatangay ng tubig, kaya nahuhugasan ang mantsa sa damit at plato.", "en": "Detergent and soap work the same way: they break grease and oil into tiny droplets that water can carry away, so stains wash off clothes and dishes.", "bis": "Ang detergent ug sabon parehas og pamaagi: bahinon nila ang lana ug grasa ngadto sa gagmay kaayong tinulo nga madala sa tubig, busa mahugasan ang mansa sa sinina ug plato."}, "source": "AAAS BSL 4; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ice-protects-fish-g6", "domain": "MATTER", "topic": "floating ice protects water life", "grades": [5, 6, 7], "terms": ["yelo", "ice", "lumulutang", "molutaw", "ibabaw", "top", "lawa", "lake", "ilog", "river", "isda", "fish", "buhay", "survive", "mabuhay", "ilalim", "ilalom", "lamig", "cold", "takip", "mainit pa", "density"], "fact": {"tl": "Dahil lumulutang ang yelo sa ibabaw ng tubig, nananatiling likido at mas mainit ang tubig sa ilalim sa malalamig na lugar — kaya nabubuhay pa rin ang mga isda sa ilalim ng nagyelong lawa.", "en": "Because ice floats on top of the water, the water below stays liquid and warmer in cold places — so fish can still survive beneath a frozen lake.", "bis": "Tungod kay molutaw ang yelo sa ibabaw sa tubig, ang tubig sa ilawom magpabilin nga likido ug mas init sa bugnaw nga mga dapit — busa mabuhi gihapon ang mga isda sa ilawom sa nayelo nga lanaw."}, "source": "AAAS BSL 4D; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-expands-freezing-pipes-g7", "domain": "MATTER", "topic": "water expands when it freezes", "grades": [6, 7, 8], "terms": ["tubig", "water", "lumalaki", "modako", "nag-expand", "nagyeyelo", "freeze", "yelo", "ice", "bottle", "bote", "tubo", "pipe", "puputok", "mabuak", "lumalakas", "density", "bumababa", "puno", "pintog"], "fact": {"tl": "Lumalaki ang tubig kapag nagiging yelo, kaya ang punong bote o tubo ng tubig ay maaaring pumutok kapag nagyelo ang laman nito.", "en": "Water expands when it turns to ice, so a full bottle or pipe of water can crack or burst when the water inside freezes.", "bis": "Modako ang tubig kon mahimo kining yelo, busa ang punong botelya o tubo sa tubig mahimong mabuak kon mo-yelo ang sulod niini."}, "source": "AAAS BSL 4D; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dissolving-physical-change-g6", "domain": "MATTER", "topic": "dissolving is a physical change", "grades": [5, 6, 7], "terms": ["asukal", "sugar", "asin", "salt", "natunaw", "matunaw", "dissolve", "tubig", "water", "nawala", "physical change", "nandiyan pa", "naa pa", "sabaw", "solution", "mabalik", "sa-sing-aw", "lasa", "tikman"], "fact": {"tl": "Kapag natunaw ang asukal o asin sa tubig, hindi ito nawawala — physical change lang ito at nakukuha mong muli ang asin kung pasisingawin mo ang tubig.", "en": "When sugar or salt dissolves in water it does not disappear — it is only a physical change, and you can get the salt back by evaporating the water.", "bis": "Kon matunaw ang asukal o asin sa tubig dili kini mawala — usa lang kini ka physical change, ug makuha nimo balik ang asin kon pasingawon nimo ang tubig."}, "source": "AAAS BSL 4D; NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "physical-change-reversible-g5", "domain": "MATTER", "topic": "telling physical from chemical change", "grades": [4, 5, 6], "terms": ["physical change", "chemical change", "maibabalik", "mabalik", "reversible", "bagong sangkap", "new substance", "pareho", "gihapon", "hugis", "anyo", "porma", "durog", "gupit", "sunog", "luto", "kalawang", "pagkilala"], "fact": {"tl": "Karaniwang maibabalik ang physical change (tulad ng pagputol o paglamig) dahil pareho pa rin ang sangkap, ngunit hindi maibabalik ang chemical change (tulad ng pagsusunog o pagkalawang) dahil nabuo na ang bagong sangkap.", "en": "A physical change (like cutting or cooling) can usually be reversed because the substance is the same, but a chemical change (like burning or rusting) cannot be reversed because a new substance has formed.", "bis": "Ang physical change (sama sa pagputol o pagbugnaw) kasagaran mabalik kay pareho gihapon ang sustansya, apan ang chemical change (sama sa pagsunog o pagkataya) dili mabalik kay naporma na ang bag-ong sustansya."}, "source": "AAAS BSL 4D; NRC PS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "soda-fizz-dissolved-gas-g6", "domain": "MATTER", "topic": "why soda fizzes", "grades": [5, 6, 7], "terms": ["softdrinks", "soda", "gas", "carbon dioxide", "bula", "fizz", "nalusaw", "natunaw", "dissolved", "presyon", "pressure", "bukas", "open", "tumatakas", "mogawas", "kumukulo", "sparkling", "inumin", "sisi"], "fact": {"tl": "May carbon-dioxide na gas na natunaw sa loob ng softdrinks sa ilalim ng presyon; kapag binuksan mo ito, lumalabas ang gas bilang mga bula — kaya ito 'sumisitsit.'", "en": "Soft drinks have carbon-dioxide gas dissolved inside under pressure; when you open the bottle, the gas escapes as bubbles — which is why soda fizzes.", "bis": "Ang softdrinks adunay carbon-dioxide nga gas nga natunaw sulod ubos sa presyon; kon ablihan nimo ang botelya, mogawas ang gas isip mga bula — mao nga 'mositsit' ang soda."}, "source": "encyclopedia-stable consensus; AAAS BSL 4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "candle-wax-both-changes-g6", "domain": "MATTER", "topic": "a burning candle shows two changes", "grades": [6, 7], "terms": ["kandila", "candle", "kandilang", "wax", "kandilang-pula", "natutunaw", "melt", "physical change", "sunog", "apoy", "chemical change", "init", "liwanag", "mitsa", "wick", "dalawang pagbabago", "liyab"], "fact": {"tl": "Sa nagliliyab na kandila ay may dalawang pagbabago: ang pagtunaw ng waks ay physical change, ngunit ang pagsunog ng waks na nagbibigay ng init at liwanag ay chemical change.", "en": "A burning candle shows two changes: the wax melting is a physical change, but the wax burning to give heat and light is a chemical change.", "bis": "Sa nagsiga nga kandila adunay duha ka pagbag-o: ang pagtunaw sa kandila usa ka physical change, apan ang pagsunog sa kandila nga maghatag og kainit ug kahayag usa ka chemical change."}, "source": "AAAS BSL 4D; NRC PS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "acid-on-marble-chalk-g7", "domain": "MATTER", "topic": "acids react with chalk and shells", "grades": [7, 8], "terms": ["acid", "asido", "suka", "vinegar", "tisa", "chalk", "kabibe", "shell", "apog", "marble", "marmol", "bula", "fizz", "carbon dioxide", "tunaw", "natutunaw", "reaksyon", "nasisira", "ngipin", "teeth"], "fact": {"tl": "Ang acid ay tumutugon sa mga bagay na gawa sa apog tulad ng tisa, kabibe, at marmol — bumubula ito at unti-unting natutunaw ang mga ito, kaya nasisira rin ng acid ang ngipin.", "en": "Acids react with things made of calcium carbonate like chalk, seashells, and marble — they bubble and slowly dissolve, which is also why acids can damage teeth.", "bis": "Ang acid mo-react sa mga butang nga hinimo sa apog sama sa tisa, kabibi, ug marmol — mobula kini ug hinay-hinay nga matunaw kini, mao nga ang acid makadaot pod sa ngipon."}, "source": "AAAS BSL 4D; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-spoiled-food-changed-g5", "domain": "MATTER", "topic": "spoiled food is a chemical change", "grades": [4, 5, 6], "terms": ["sira", "panis", "spoiled", "pagkaon", "food", "baho", "amoy", "smell", "bulok", "rot", "mikrobyo", "germ", "chemical change", "nagbago", "gatas", "milk", "asim", "aslom", "luma", "hindi na maibabalik"], "fact": {"tl": "Kapag napapanis ang pagkaon, dinudurog ito ng mga mikrobyo at bumubuo ng bagong masangsang na sangkap — isang chemical change na hindi na maibabalik, kaya hindi na ito ligtas kainin.", "en": "When food spoils, microbes break it down and form new bad-smelling substances — a chemical change that cannot be reversed, which is why it is no longer safe to eat.", "bis": "Kon mapan-os ang pagkaon, dunoton kini sa mga mikrobyo ug maghimog bag-ong baho nga sustansya — usa ka chemical change nga dili na mabalik, mao nga dili na kini luwas kan-on."}, "source": "AAAS BSL 4D; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rust-needs-water-and-air-g6", "domain": "MATTER", "topic": "rust needs both water and air", "grades": [5, 6, 7], "terms": ["kalawang", "rust", "taya", "tubig", "water", "hangin", "air", "oxygen", "kailangan", "kinahanglan", "dalawa", "duha", "tuyo", "dry", "basa", "wet", "mas mabilis", "dagat", "alat", "bakal", "pako", "nail"], "fact": {"tl": "Kailangan ng kalawang ang parehong tubig at hangin (oxygen) — kaya mas mabilis kinakalawang ang bakal sa basa o maalat na lugar tulad ng tabing-dagat kaysa sa tuyong lugar.", "en": "Rust needs both water and air (oxygen) — so iron rusts faster in wet or salty places like the seaside than in a dry place.", "bis": "Ang taya nagkinahanglan og tubig ug hangin (oxygen) — busa mas paspas matayaan ang puthaw sa basa o parat nga dapit sama sa baybayon kaysa sa uga nga dapit."}, "source": "AAAS BSL 4D/M6; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-universal-solvent-g5", "domain": "MATTER", "topic": "water as a solvent", "grades": [4, 5, 6], "terms": ["tubig", "nakakalusaw", "natutunaw na bagay", "natutunaw", "matunaw", "makatunaw", "matunaw niini", "water", "solvent", "dissolve", "universal solvent", "tunaw"], "fact": {"tl": "Ang tubig ang tinatawag na \"universal solvent\" dahil mas maraming bagay ang natutunaw dito kaysa sa ibang likido.", "en": "Water is called the \"universal solvent\" because more substances dissolve in it than in any other liquid.", "bis": "Ang tubig gitawag nga \"universal solvent\" kay mas daghang butang ang matunaw niini kaysa sa ubang likido."}, "source": "NRC PS1.A (grade-5 endpoint: sugar in solution); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "solute-solvent-solution-g5", "domain": "MATTER", "topic": "solute, solvent, and solution", "grades": [5, 6, 7], "terms": ["solute", "solvent", "solusyon", "tinunaw", "panunaw", "asukal sa tubig", "asin sa tubig", "gitunaw", "solution", "mixture", "dissolve", "natunaw"], "fact": {"tl": "Sa isang solusyon, ang bagay na natutunaw ay tinatawag na solute at ang likidong nagtutunaw nito ay ang solvent.", "en": "In a solution, the substance that dissolves is called the solute and the liquid that dissolves it is called the solvent.", "bis": "Sa usa ka solusyon, ang butang nga matunaw gitawag nga solute ug ang likido nga nagtunaw niini mao ang solvent."}, "source": "NRC PS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dissolving-sugar-still-there-g4", "domain": "MATTER", "topic": "matter is conserved when it dissolves", "grades": [3, 4, 5], "terms": ["asukal", "natunaw", "nawala", "timbang", "hindi nawawala", "nasa tubig pa", "wala mawala", "gibug-aton", "matilawan", "sugar", "dissolve", "still there", "weight", "conserved", "matunaw"], "fact": {"tl": "Kapag natunaw ang asukal sa tubig, hindi ito nawawala — naroon pa rin ito at matitikman, kaya hindi nagbabago ang timbang.", "en": "When sugar dissolves in water it does not disappear — it is still there and can be tasted, so the total weight stays the same.", "bis": "Kon matunaw ang asukal sa tubig, dili kini mawala — naa pa gihapon ug matilawan, mao nga dili mausab ang gibug-aton."}, "source": "NRC PS1.A grade-5 endpoint (weight conserved, sugar in solution)", "generator": "claude-workflow", "reviewed": false},
  {"id": "warm-water-dissolves-faster-g5", "domain": "MATTER", "topic": "temperature speeds dissolving", "grades": [4, 5, 6], "terms": ["mainit na tubig", "mabilis matunaw", "init", "mas mabilis", "haloin", "init nga tubig", "paspas matunaw", "kutawon", "warm water", "dissolve faster", "stir", "temperature", "matunaw dali"], "fact": {"tl": "Mas mabilis matunaw ang isang solute sa mainit na tubig at kung hinahalo, kaysa sa malamig at tahimik na tubig.", "en": "A solute dissolves faster in warm water and when stirred than in cold, still water.", "bis": "Mas paspas matunaw ang usa ka solute sa init nga tubig ug kon kutawon, kaysa sa bugnaw ug hilom nga tubig."}, "source": "NRC PS1.A / PS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "not-everything-dissolves-g4", "domain": "MATTER", "topic": "some things do not dissolve in water", "grades": [3, 4, 5], "terms": ["langis", "buhangin", "hindi natutunaw", "di matunaw", "lana", "balas", "dili matunaw", "bato", "oil", "sand", "does not dissolve", "insoluble"], "fact": {"tl": "Hindi lahat ng bagay ay natutunaw sa tubig — ang langis, buhangin, at bato ay hindi natutunaw at nananatiling hiwalay.", "en": "Not everything dissolves in water — oil, sand, and stones do not dissolve and stay separate.", "bis": "Dili tanang butang matunaw sa tubig — ang lana, balas, ug bato dili matunaw ug magpabilin nga bulag."}, "source": "NRC PS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "oil-water-do-not-mix-g4", "domain": "MATTER", "topic": "oil and water separate", "grades": [4, 5, 6], "terms": ["langis", "tubig", "hindi naghahalo", "lumulutang ang langis", "lana", "dili magsagol", "naglutaw", "molutaw", "oil", "water", "do not mix", "oil floats"], "fact": {"tl": "Hindi naghahalo ang langis at tubig; ang langis ay lumulutang sa ibabaw dahil mas magaan ito kaysa sa tubig.", "en": "Oil and water do not mix; the oil floats on top because it is lighter (less dense) than water.", "bis": "Ang lana ug tubig dili magsagol; ang lana molutaw sa ibabaw kay mas gaan (gamay og density) kini kaysa tubig."}, "source": "encyclopedia-stable consensus (density / immiscibility)", "generator": "claude-workflow", "reviewed": false},
  {"id": "density-why-float-sink-g5", "domain": "MATTER", "topic": "density determines floating and sinking", "grades": [5, 6, 7], "terms": ["lumulutang", "lumulubog", "density", "mas magaan sa tubig", "naglutaw", "molugdang", "molutaw", "molunod", "float", "sink", "heavier than water"], "fact": {"tl": "Lumulutang ang isang bagay kung mas mababa ang density nito kaysa sa tubig, at lumulubog kung mas mataas ang density nito.", "en": "An object floats if its density is lower than water's and sinks if its density is higher.", "bis": "Ang usa ka butang molutaw kon mas ubos ang density niini kaysa tubig, ug molunod kon mas taas ang density niini."}, "source": "encyclopedia-stable consensus (density and buoyancy)", "generator": "claude-workflow", "reviewed": false},
  {"id": "density-mass-per-volume-g6", "domain": "MATTER", "topic": "what density means", "grades": [6, 7, 8], "terms": ["density", "gaano kasiksik", "mass", "volume", "bigat sa laki", "gibug-aton sa gidak-on", "siksik", "mass per volume", "how packed", "gaano kabigat"], "fact": {"tl": "Ang density ay kung gaano kasiksik ang isang bagay — ang bigat (mass) nito sa bawat sukat ng espasyong inookupahan (volume).", "en": "Density is how tightly packed a material is — its mass for each amount of space (volume) it takes up.", "bis": "Ang density mao ang pagkasiksik sa usa ka materyal — ang gibug-aton (mass) niini matag gidak-on sa luna (volume) nga giokupahan."}, "source": "encyclopedia-stable consensus (definition of density)", "generator": "claude-workflow", "reviewed": false},
  {"id": "steel-ship-floats-g6", "domain": "MATTER", "topic": "why heavy steel ships float", "grades": [6, 7, 8], "terms": ["barko", "bakal", "lumulutang", "hollow", "hugis-lukong", "puthaw", "naglutaw", "lungagon", "ship", "steel", "floats", "hollow shape", "displaces water", "molutaw"], "fact": {"tl": "Lumulutang ang mabibigat na barkong bakal dahil hugis-lukong ito at puno ng hangin sa loob, kaya mas mababa ang kabuuang density nito kaysa sa tubig.", "en": "Heavy steel ships float because their hollow shape is full of air inside, making the ship's overall density lower than water's.", "bis": "Ang bug-at nga barkong puthaw molutaw kay lungagon ug puno sa hangin sa sulod, mao nga mas ubos ang kinatibuk-ang density niini kaysa tubig."}, "source": "encyclopedia-stable consensus (buoyancy / Archimedes)", "generator": "claude-workflow", "reviewed": false},
  {"id": "salt-water-more-buoyant-g6", "domain": "MATTER", "topic": "salt water lifts objects more", "grades": [5, 6, 7], "terms": ["tubig-alat", "maalat na tubig", "mas lumulutang", "Dead Sea", "asin", "parat nga tubig", "mas molutaw", "salt water", "more buoyant", "denser", "mas dense"], "fact": {"tl": "Mas madaling lumutang ang isang bagay sa tubig-alat kaysa sa tabang na tubig dahil mas mataas ang density ng maalat na tubig.", "en": "Things float more easily in salt water than in fresh water because salt water is denser.", "bis": "Mas sayon molutaw ang usa ka butang sa parat nga tubig kaysa tab-ang nga tubig kay mas dense ang parat nga tubig."}, "source": "encyclopedia-stable consensus (density of saltwater; Dead Sea)", "generator": "claude-workflow", "reviewed": false},
  {"id": "surface-tension-g5", "domain": "MATTER", "topic": "surface tension of water", "grades": [4, 5, 6], "terms": ["surface tension", "balat ng tubig", "patak", "nag-iipon", "panit sa tubig", "tulo", "lingin", "surface tension", "skin on water", "water drop", "cohesion"], "fact": {"tl": "May parang manipis na \"balat\" ang ibabaw ng tubig dahil sa surface tension, na siyang dahilan kung bakit bilog ang mga patak ng tubig.", "en": "The surface of water has a thin \"skin\" called surface tension, which is why water drops pull into round beads.", "bis": "Ang ibabaw sa tubig adunay nipis nga \"panit\" nga gitawag og surface tension, mao nga ang mga tulo sa tubig magtipon nga lingin."}, "source": "encyclopedia-stable consensus (cohesion / surface tension)", "generator": "claude-workflow", "reviewed": false},
  {"id": "surface-tension-insect-walks-g5", "domain": "MATTER", "topic": "insects walk on water", "grades": [4, 5, 6], "terms": ["water strider", "lumalakad sa tubig", "surface tension", "insekto", "naglakaw sa tubig", "mananap sa tubig", "walks on water", "floats", "dili molunod"], "fact": {"tl": "Dahil sa surface tension, may mga insekto tulad ng water strider na nakakalakad sa ibabaw ng tubig nang hindi lumulubog.", "en": "Because of surface tension, some insects like the water strider can walk on top of water without sinking.", "bis": "Tungod sa surface tension, adunay mga insekto sama sa water strider nga makalakaw sa ibabaw sa tubig nga dili molunod."}, "source": "encyclopedia-stable consensus (surface tension)", "generator": "claude-workflow", "reviewed": false},
  {"id": "soap-breaks-surface-tension-g6", "domain": "MATTER", "topic": "soap lowers surface tension", "grades": [5, 6, 7], "terms": ["sabon", "surface tension", "humihina", "naghuhugas", "nagpaluya", "mahugasan", "hugaw", "soap", "breaks surface tension", "cleaning", "detergent", "surfactant"], "fact": {"tl": "Pinahihina ng sabon ang surface tension ng tubig, kaya mas madaling makapasok ang tubig sa dumi at malabhan ito.", "en": "Soap weakens water's surface tension, letting water spread into dirt more easily so it can wash things clean.", "bis": "Ang sabon nagpaluya sa surface tension sa tubig, mao nga mas sayon makasulod ang tubig sa hugaw aron mahugasan kini."}, "source": "encyclopedia-stable consensus (surfactants)", "generator": "claude-workflow", "reviewed": false},
  {"id": "evaporation-puddle-g4", "domain": "MATTER", "topic": "evaporation", "grades": [3, 4, 5], "terms": ["sumisingaw", "singaw", "natutuyo", "lusak", "init ng araw", "mosingaw", "mauga", "danaw", "alisngaw", "evaporate", "puddle dries", "water vapor", "sun heat"], "fact": {"tl": "Kapag natutuyo ang isang lusak sa init ng araw, ang tubig ay nagiging singaw na pumapailanlang sa hangin — ito ang evaporation.", "en": "When a puddle dries in the sun, the water turns into vapor that rises into the air — this is evaporation.", "bis": "Kon mauga ang danaw sa init sa adlaw, ang tubig mahimong alisngaw nga mosaka sa hangin — kini mao ang evaporation."}, "source": "NRC PS1.A grade-5 endpoint (evaporation of a puddle)", "generator": "claude-workflow", "reviewed": false},
  {"id": "evaporation-cools-skin-g5", "domain": "MATTER", "topic": "evaporation cools", "grades": [4, 5, 6], "terms": ["pawis", "lumalamig", "sumisingaw", "init kinukuha", "singot", "mobugnaw", "mosingaw", "evaporation", "cooling", "sweat", "why we sweat", "mabugnaw"], "fact": {"tl": "Pinapalamig tayo ng pawis dahil kapag sumisingaw ito, dala nito ang init mula sa ating balat papunta sa hangin.", "en": "Sweat cools us because as it evaporates it carries heat away from our skin into the air.", "bis": "Ang singot magpabugnaw kanato kay samtang kini mosingaw, dad-on niini ang init gikan sa atong panit ngadto sa hangin."}, "source": "encyclopedia-stable consensus (evaporative cooling)", "generator": "claude-workflow", "reviewed": false},
  {"id": "boiling-water-100c-g5", "domain": "MATTER", "topic": "boiling point of water", "grades": [5, 6, 7], "terms": ["kumukulo", "boiling", "100 degrees", "bula", "singaw", "nagbukal", "mobukal", "100 degree", "boiling point", "100 Celsius", "bubbles", "steam"], "fact": {"tl": "Kumukulo ang tubig sa 100 degrees Celsius; sa init na ito, mabilis itong nagiging singaw at gumagawa ng mga bula.", "en": "Water boils at 100 degrees Celsius; at that heat it quickly turns into vapor and forms bubbles.", "bis": "Ang tubig mobukal sa 100 ka degrees Celsius; niini nga kainit, paspas kini mahimong alisngaw ug maghimo og mga bula."}, "source": "encyclopedia-stable consensus (boiling point of water at sea level)", "generator": "claude-workflow", "reviewed": false},
  {"id": "steam-is-water-vapor-g5", "domain": "MATTER", "topic": "steam is water in gas form", "grades": [4, 5, 6], "terms": ["singaw", "tubig pa rin", "gas", "kondensasyon", "alisngaw", "tubig", "steam", "water vapor", "gas form", "condense", "mobugnaw"], "fact": {"tl": "Ang singaw ng tubig ay tubig pa rin — nasa anyong gas lang ito, at babalik sa likido kapag lumamig (condensation).", "en": "Steam is still water — it is just water in gas form, and it turns back to liquid when it cools (condensation).", "bis": "Ang alisngaw tubig gihapon — anaa lang kini sa porma nga gas, ug mobalik sa likido kon mobugnaw (condensation)."}, "source": "NRC PS1.A grade-5 endpoint (condensation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-expands-when-frozen-g6", "domain": "MATTER", "topic": "water expands as it freezes", "grades": [6, 7, 8], "terms": ["yelo", "lumalaki", "nagyeyelo", "lumulutang ang yelo", "tubig", "mudako", "molutaw ang yelo", "ice", "water expands", "ice floats", "freezing", "less dense"], "fact": {"tl": "Kakaiba ang tubig dahil lumalaki ang volume nito kapag nagiging yelo, kaya mas magaan ang yelo at lumulutang sa tubig.", "en": "Water is unusual because it expands when it freezes, so ice is less dense and floats on water.", "bis": "Talagsaon ang tubig kay modako ang volume niini kon mahimong yelo, mao nga mas gaan ang yelo ug molutaw sa tubig."}, "source": "encyclopedia-stable consensus (anomalous expansion of water)", "generator": "claude-workflow", "reviewed": false},
  {"id": "ice-floats-protects-fish-g6", "domain": "MATTER", "topic": "floating ice protects life", "grades": [6, 7, 8], "terms": ["yelo", "lumulutang", "isda", "lawa", "taglamig", "naglutaw ang yelo", "linaw", "tugnaw", "ice floats", "fish survive", "lake", "insulates", "mabuhi"], "fact": {"tl": "Dahil lumulutang ang yelo, natatakpan nito ang ibabaw ng lawa sa malamig na panahon at nananatiling buhay ang mga isda sa tubig sa ilalim.", "en": "Because ice floats, it covers a lake's surface in cold weather while fish stay alive in the water below.", "bis": "Tungod kay molutaw ang yelo, matabonan niini ang ibabaw sa linaw sa tugnaw nga panahon samtang ang mga isda mabuhi sa tubig sa ilawom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-three-states-g4", "domain": "MATTER", "topic": "water exists in three states", "grades": [3, 4, 5], "terms": ["tubig", "yelo", "singaw", "solid likido gas", "tatlong anyo", "alisngaw", "tulo ka porma", "water", "ice", "vapor", "three states", "solid liquid gas"], "fact": {"tl": "Ang tubig ay isa sa iilang bagay na makikita natin sa tatlong anyo sa pang-araw-araw na buhay: solid (yelo), likido (tubig), at gas (singaw).", "en": "Water is one of the few things we see in all three states in everyday life: solid (ice), liquid (water), and gas (vapor).", "bis": "Ang tubig usa sa pipila ka butang nga makita nato sa tulo ka porma kada adlaw: solid (yelo), likido (tubig), ug gas (alisngaw)."}, "source": "NRC PS1.A grade-2 endpoint (solid or liquid by temperature)", "generator": "claude-workflow", "reviewed": false},
  {"id": "filtering-vs-dissolving-g5", "domain": "MATTER", "topic": "separating mixtures by filtering", "grades": [5, 6, 7], "terms": ["salaan", "filter", "buhangin", "natutunaw", "paghihiwalay", "salaa", "balas", "matunaw", "lainon", "separate mixture", "sand", "strain", "dissolved cannot filter"], "fact": {"tl": "Maaaring ihiwalay ang buhangin sa tubig sa pamamagitan ng salaan, ngunit hindi masasala ang asukal na natunaw na dahil bahagi na ito ng solusyon.", "en": "Sand can be separated from water with a filter, but dissolved sugar cannot be filtered out because it is now part of the solution.", "bis": "Ang balas mahimong lainon gikan sa tubig pinaagi sa salaan, apan ang natunaw nga asukal dili masala kay bahin na kini sa solusyon."}, "source": "encyclopedia-stable consensus (separation of mixtures)", "generator": "claude-workflow", "reviewed": false},
  {"id": "evaporate-to-get-salt-g5", "domain": "MATTER", "topic": "recovering salt by evaporation", "grades": [4, 5, 6], "terms": ["asin", "asinan", "sumingaw", "tira", "tubig-dagat", "mosingaw", "nahibilin", "mabilin", "salt", "evaporate", "sea salt", "left behind", "salt pans"], "fact": {"tl": "Kapag pinasingaw ang tubig-alat, naiiwan ang asin — ganito gumagawa ng asin sa mga asinan sa Pilipinas mula sa tubig-dagat.", "en": "When salt water is evaporated, the salt is left behind — this is how salt is made from seawater in Philippine salt beds.", "bis": "Kon pasingawon ang parat nga tubig, mabilin ang asin — mao kini ang paghimo og asin sa mga asinan sa Pilipinas gikan sa tubig-dagat."}, "source": "encyclopedia-stable consensus; PH salt-making (asin)", "generator": "claude-workflow", "reviewed": false},
  {"id": "capillary-action-plants-g6", "domain": "MATTER", "topic": "capillary action", "grades": [6, 7, 8], "terms": ["umaakyat na tubig", "capillary", "tela", "halaman", "manipis na tubo", "tubig nga mosaka", "panapton", "tanom", "tangkay", "capillary action", "water climbs", "plant stem", "wick"], "fact": {"tl": "Nakakaakyat ang tubig sa makikitid na tubo o sa tangkay ng halaman kahit pataas — tinatawag itong capillary action.", "en": "Water can climb up very thin tubes or a plant's stem even against gravity — this is called capillary action.", "bis": "Ang tubig makasaka sa pig-ot kaayo nga tubo o sa tangkay sa tanom bisan pasaka — gitawag kini og capillary action."}, "source": "encyclopedia-stable consensus (cohesion/adhesion, capillarity)", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-supports-life-g4", "domain": "LIVING_THINGS", "topic": "living things need water", "grades": [3, 4, 5], "terms": ["tubig", "buhay", "kailangan", "katawan", "halaman", "hayop", "kinahanglan", "lawas", "tanom", "mananap", "water for life", "living things need", "cannot live without", "kinabuhi"], "fact": {"tl": "Kailangan ng tubig ng lahat ng nabubuhay na bagay dahil dito natutunaw at nadadala ang mga sustansyang kailangan ng kanilang katawan.", "en": "All living things need water because the nutrients their bodies need dissolve and travel in it.", "bis": "Ang tanang buhing butang nanginahanglan og tubig kay diha niini matunaw ug madala ang mga sustansya nga gikinahanglan sa ilang lawas."}, "source": "NRC LS1; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-most-of-earth-g4", "domain": "EARTH_SPACE", "topic": "water covers most of Earth", "grades": [3, 4, 5], "terms": ["tubig", "Mundo", "karagatan", "nakatakip", "asul na planeta", "kalibutan", "kadagatan", "asul nga planeta", "natabonan", "water covers Earth", "blue planet", "oceans", "most of surface"], "fact": {"tl": "Halos tatlong-kapat ng ibabaw ng Mundo ay natatakpan ng tubig, kaya tinatawag itong \"blue planet.\"", "en": "About three-quarters of Earth's surface is covered by water, which is why it is called the \"blue planet.\"", "bis": "Mga tulo-ka-upat sa ibabaw sa Kalibutan natabonan sa tubig, mao nga gitawag kini og \"blue planet.\""}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fresh-vs-salt-water-g5", "domain": "EARTH_SPACE", "topic": "most water is salty", "grades": [4, 5, 6], "terms": ["tubig-tabang", "tubig-alat", "kaunti", "maiinom", "karagatan", "tab-ang nga tubig", "parat nga tubig", "gamay", "mainom", "fresh water", "salt water", "drinkable", "most is salty"], "fact": {"tl": "Karamihan ng tubig sa Mundo ay maalat na tubig-dagat; kakaunti lamang ang sariwang tubig na maaari nating inumin.", "en": "Most of Earth's water is salty seawater; only a small part is fresh water that we can drink.", "bis": "Kadaghanan sa tubig sa Kalibutan parat nga tubig-dagat; gamay ra ang tab-ang nga tubig nga atong mainom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "nitrogen-most-of-air-g5", "domain": "MATTER", "topic": "nitrogen is most of the air", "grades": [5, 6, 7], "terms": ["nitrogen", "nitroheno", "hangin", "air", "pinakamarami", "kadaghanan", "78", "gas", "walang kulay", "walay kolor", "hindi natutunaw", "dili masunog", "element", "karamihan"], "fact": {"tl": "Ang pinakamaraming gas sa hangin ay nitrogen — humigit-kumulang 78% ng hangin. Ito ay isang walang kulay na gas na hindi madaling sumama sa ibang sangkap, kaya hindi ito natutunaw sa apoy gaya ng oxygen.", "en": "The most common gas in the air is nitrogen — about 78% of it. It is a colorless gas that does not easily react with other things, so it does not burn the way oxygen lets things burn.", "bis": "Ang pinakadaghan nga gas sa hangin mao ang nitrogen — mga 78% sa hangin. Usa kini ka walay kolor nga gas nga dili sayon makig-uban sa ubang butang, mao nga dili kini mosunog sama sa gibuhat sa oxygen."}, "source": "AAAS BSL Ch.4B (reference value); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gases-have-no-color-usually-g4", "domain": "MATTER", "topic": "most gases are invisible", "grades": [3, 4, 5], "terms": ["gas", "hangin", "air", "hindi nakikita", "dili makita", "invisible", "walang kulay", "walay kolor", "amoy", "baho", "oxygen", "nitrogen", "makita", "nararamdaman", "mabati"], "fact": {"tl": "Karamihan ng gas tulad ng oxygen at nitrogen ay hindi nakikita at walang kulay, kaya parang walang laman ang hangin — pero may laman pala. Minsan nalalaman natin na may gas dahil sa amoy nito o sa galaw na nararamdaman natin.", "en": "Most gases like oxygen and nitrogen are invisible and colorless, so the air looks empty even though it is not. Sometimes we know a gas is there from its smell or the movement we can feel.", "bis": "Kadaghanan sa gas sama sa oxygen ug nitrogen dili makita ug walay kolor, mao nga morag walay sulod ang hangin — apan naa diay. Usahay mahibaw-an nato nga adunay gas tungod sa baho niini o sa lihok nga atong mabati."}, "source": "AAAS BSL Ch.4D; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "air-has-weight-g4", "domain": "MATTER", "topic": "air has weight", "grades": [4, 5, 6], "terms": ["hangin", "air", "timbang", "gibug-aton", "bigat", "may bigat", "mass", "lobo", "balloon", "puno", "walang laman", "gas"], "fact": {"tl": "Kahit hindi natin ito nakikita, may timbang ang hangin. Kapag pinuno mo ng hangin ang isang lobo, ito ay bahagyang bumibigat kaysa sa walang hangin — patunay na ang gas ay tunay na bagay na may mass.", "en": "Even though we cannot see it, air has weight. When you fill a balloon with air, it becomes a little heavier than an empty one — proof that a gas is real matter with mass.", "bis": "Bisan dili nato kini makita, ang hangin adunay timbang. Kung pun-on nimo og hangin ang lobo, mahimo kining gamay nga mas bug-at kaysa walay sulod — pamatuod nga ang gas tinuod nga butang nga adunay mass."}, "source": "AAAS BSL Ch.4B; NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "warm-gas-expands-g5", "domain": "MATTER", "topic": "gases expand when heated", "grades": [5, 6, 7], "terms": ["gas", "hangin", "air", "init", "kainit", "lumalawak", "molapad", "mokatag", "lobo", "balloon", "lumalaki", "modako", "lumamig", "mobugnaw", "umuurong", "particle", "mabilis"], "fact": {"tl": "Kapag iniinit ang gas, mas mabilis at mas malayo ang galaw ng mga particle nito, kaya lumalawak ito at kumukuha ng mas malaking espasyo. Kapag pinalamig naman, umuurong ito — ito ang dahilan kung bakit lumalaki ang lobo sa init at lumiliit sa lamig.", "en": "When a gas is heated, its particles move faster and farther apart, so it expands and takes up more space. When cooled, it shrinks — this is why a balloon grows a little in heat and shrinks in the cold.", "bis": "Kung initan ang gas, mas paspas ug mas layo ang lihok sa mga particle niini, mao nga molapad kini ug mokuha og mas dako nga espasyo. Kung bugnawon, mo-urong kini — mao kini ang hinungdan nganong modako ang lobo sa kainit ug mogamay sa kabugnaw."}, "source": "AAAS BSL Ch.4D; NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "warm-air-rises-balloon-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "hot air rises", "grades": [5, 6, 7], "terms": ["mainit na hangin", "init nga hangin", "hot air", "pumapaitaas", "mosaka", "umaakyat", "magaan", "mas gaan", "density", "hot air balloon", "lumulutang", "molutaw", "lumalamig", "mobugnaw", "bumababa", "ulap"], "fact": {"tl": "Ang mainit na hangin ay mas magaan (mas mababa ang density) kaysa malamig na hangin, kaya ito ay pumapaitaas. Ito ang gumagana sa hot air balloon at dahilan kung bakit umaakyat ang init sa kisame ng silid.", "en": "Warm air is lighter (less dense) than cool air, so it rises. This is what lifts a hot air balloon and why heat rises to the ceiling of a room.", "bis": "Ang init nga hangin mas gaan (mas ubos ang density) kaysa bugnaw nga hangin, mao nga mosaka kini. Mao kini ang nagpalupad sa hot air balloon ug ang hinungdan nganong mosaka ang kainit sa kisame sa kwarto."}, "source": "NRC PS3.B; AAAS BSL Ch.4E", "generator": "claude-workflow", "reviewed": false},
  {"id": "carbon-dioxide-makes-fizz-g4", "domain": "MATTER", "topic": "carbon dioxide bubbles in soda", "grades": [4, 5, 6], "terms": ["carbon dioxide", "CO2", "soda", "softdrink", "bula", "bula-bula", "bubbles", "fizz", "gas", "kumukulo", "mobukal", "baso", "sumisingaw", "mokatag", "inumin"], "fact": {"tl": "Ang mga bula sa softdrink ay carbon dioxide gas na pinilit pasukin sa likido. Kapag binuksan ang bote, kumakalat ang gas pataas bilang mga bula — kaya parang 'kumukulo' ang soda kahit malamig.", "en": "The bubbles in a soft drink are carbon dioxide gas forced into the liquid. When the bottle is opened, the gas escapes upward as bubbles — which is why soda fizzes even when it is cold.", "bis": "Ang mga bula sa softdrink mao ang carbon dioxide gas nga gipugos sulod sa likido. Kung ablihan ang botelya, mogawas ang gas pataas isip mga bula — mao nga morag 'mobukal' ang soda bisan bugnaw."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "carbon-dioxide-heavier-than-air-g6", "domain": "MATTER", "topic": "carbon dioxide is denser than air", "grades": [6, 7], "terms": ["carbon dioxide", "CO2", "mabigat", "mas bug-at", "heavier", "density", "lumulubog", "mounlod", "mababa", "ubos", "apoy", "mapalong", "fire extinguisher", "pumapatay ng apoy", "gas", "hangin"], "fact": {"tl": "Ang carbon dioxide ay mas mabigat (mas mataas ang density) kaysa karaniwang hangin, kaya may posibilidad itong manatili sa mababang lugar. Dahil dito at dahil hindi ito nakakatulong sa pagkasunog, ginagamit ang CO₂ sa ilang fire extinguisher para patayin ang apoy.", "en": "Carbon dioxide is heavier (denser) than ordinary air, so it can settle in low places. Because of this and because it does not support burning, CO₂ is used in some fire extinguishers to smother flames.", "bis": "Ang carbon dioxide mas bug-at (mas taas ang density) kaysa ordinaryong hangin, mao nga mahimo kining magpabilin sa ubos nga dapit. Tungod niini ug tungod kay dili kini makatabang sa pagsunog, gigamit ang CO₂ sa pipila ka fire extinguisher aron mapalong ang kalayo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "helium-makes-voice-high-g5", "domain": "MATTER", "topic": "helium changes the voice", "grades": [5, 6, 7], "terms": ["helium", "balloon", "lobo", "boses", "tingog", "voice", "matinis", "high", "magaan", "mas gaan", "gas", "bilis ng tunog", "tulin sa tingog", "sound", "tunog", "mabilis"], "fact": {"tl": "Kapag huminga ng helium mula sa lobo, nagiging matinis ang boses dahil mas mabilis dumaan ang tunog sa magaan na helium kaysa sa karaniwang hangin. (Mapanganib gawin ito dahil pinapalitan nito ang oxygen na kailangan natin.)", "en": "Breathing helium from a balloon makes the voice sound high and squeaky because sound travels faster through the light helium than through ordinary air. (It is dangerous to do because it replaces the oxygen we need.)", "bis": "Kung moginhawa og helium gikan sa lobo, mahimong matinis ang tingog tungod kay mas paspas molabay ang tunog sa gaan nga helium kaysa sa ordinaryong hangin. (Delikado kini buhaton kay pulihan niini ang oxygen nga atong gikinahanglan.)"}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "helium-second-lightest-g6", "domain": "MATTER", "topic": "helium is a very light gas", "grades": [6, 7], "terms": ["helium", "gas", "magaan", "gaan", "light", "element", "ikalawa", "ikaduha", "hydrogen", "walang kulay", "walay kolor", "walang amoy", "walay baho", "hindi nasusunog", "dili masunog", "lobo", "balloon"], "fact": {"tl": "Ang helium ay isa sa pinakamagaang gas at ikalawa sa pinakamagaang element kasunod ng hydrogen. Wala itong kulay ni amoy at hindi nasusunog, kaya mas ligtas itong gamitin sa lobo kaysa hydrogen.", "en": "Helium is one of the lightest gases and the second-lightest element after hydrogen. It has no color or smell and does not burn, which makes it safer than hydrogen for filling balloons.", "bis": "Ang helium usa sa pinakagaan nga gas ug ikaduha sa pinakagaan nga element sunod sa hydrogen. Wala kini kolor o baho ug dili masunog, mao nga mas luwas kini gamiton sa lobo kaysa hydrogen."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "oxygen-supports-burning-bright-g6", "domain": "MATTER", "topic": "pure oxygen makes fire burn brighter", "grades": [6, 7], "terms": ["oxygen", "oksiheno", "apoy", "kalayo", "fire", "mas maliwanag", "mas hayag", "brighter", "mabilis", "paspas", "nasusunog", "masunog", "glowing splint", "sigang", "pure oxygen", "dalisay", "lumalakas"], "fact": {"tl": "Pinalalakas ng oxygen ang pagkasunog: mas maliwanag at mas mabilis nasusunog ang isang bagay sa dalisay na oxygen kaysa sa karaniwang hangin. Kaya kapag inilubog ang nag-aapoy na patpat sa oxygen, biglang lumalakas ang liyab.", "en": "Oxygen makes things burn more strongly: an object burns brighter and faster in pure oxygen than in ordinary air. That is why a glowing splint flares up when placed in oxygen.", "bis": "Gipakusog sa oxygen ang pagsunog: mas hayag ug mas paspas masunog ang usa ka butang sa lunsay nga oxygen kaysa ordinaryong hangin. Mao nga kung ituslob ang nagbaga nga sungkod sa oxygen, kalit nga mosiga kini."}, "source": "AAAS BSL Ch.4D; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gas-takes-shape-of-container-g4", "domain": "MATTER", "topic": "gas has no fixed shape", "grades": [3, 4, 5], "terms": ["gas", "hangin", "air", "hugis", "porma", "shape", "lalagyan", "sudlanan", "container", "walang sariling hugis", "walay kaugalingong porma", "sumusunod", "mosunod", "lobo", "bilog", "mahaba"], "fact": {"tl": "Walang sariling hugis ang gas — sumusunod ito sa hugis ng lalagyan nito. Ang parehong hangin ay nagiging bilog sa bilog na lobo at mahaba sa mahabang lobo.", "en": "A gas has no shape of its own — it takes the shape of whatever holds it. The same air becomes round in a round balloon and long in a long balloon.", "bis": "Ang gas walay kaugalingong porma — mosunod kini sa porma sa sudlanan niini. Ang samang hangin mahimong lingin sa lingin nga lobo ug taas sa taas nga lobo."}, "source": "NRC PS1.A; AAAS BSL Ch.4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "smell-travels-through-air-g4", "domain": "MATTER", "topic": "smells spread as gases diffuse", "grades": [3, 4, 5], "terms": ["amoy", "baho", "smell", "ulam", "luto", "kumakalat", "mokatag", "spread", "silid", "kwarto", "room", "gas", "particle", "gumagalaw", "molihok", "hangin", "diffusion"], "fact": {"tl": "Kumakalat ang amoy ng luto sa buong bahay dahil ang amoy ay dala ng maliliit na particle ng gas na malayang gumagalaw at kumakalat sa hangin hanggang abutin ang ating ilong.", "en": "The smell of cooking spreads through the whole house because a smell is carried by tiny gas particles that move freely and spread through the air until they reach our nose.", "bis": "Mokatag ang baho sa pagluto sa tibuok balay tungod kay ang baho gidala sa gagmayng particle sa gas nga gawasnong molihok ug mokatag sa hangin hangtod maabot ang atong ilong."}, "source": "NRC PS1.A; AAAS BSL Ch.4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-vapor-in-air-g5", "domain": "MATTER", "topic": "there is water vapor in the air", "grades": [5, 6, 7], "terms": ["water vapor", "singaw ng tubig", "alisngaw", "tubig", "gas", "hangin", "air", "humidity", "halumigmig", "basa", "mamasa", "hamog", "dew", "baso", "malamig na baso", "invisible", "nakikita"], "fact": {"tl": "May nakatagong water vapor (singaw ng tubig) sa hangin bilang isang gas na hindi natin nakikita. Kapag dumikit ito sa malamig na baso, nagiging maliliit na patak ng tubig — kaya nababasa ang labas ng baso ng malamig na inumin.", "en": "The air holds hidden water vapor — water in gas form that we cannot see. When it touches a cold glass, it turns into tiny water drops, which is why the outside of a glass of cold drink gets wet.", "bis": "Ang hangin adunay tinago nga water vapor (alisngaw sa tubig) isip gas nga dili nato makita. Kung modikit kini sa bugnaw nga baso, mahimo kining gagmayng tulo sa tubig — mao nga mabasa ang gawas sa baso sa bugnaw nga ilimnon."}, "source": "NRC ESS2.D; AAAS BSL Ch.4B", "generator": "claude-workflow", "reviewed": false},
  {"id": "we-breathe-out-water-vapor-g4", "domain": "LIVING_THINGS", "topic": "breath contains water vapor", "grades": [4, 5, 6], "terms": ["hininga", "ginhawa", "breath", "singaw", "alisngaw", "water vapor", "malamig", "bugnaw", "salamin", "glass", "fog", "ulap", "hininga sa lamig", "nabubuo", "mapormang"], "fact": {"tl": "Bukod sa carbon dioxide, may dalang singaw ng tubig ang ating hininga. Kapag huminga ka sa malamig na salamin o sa malamig na hangin, nakikita mo ang maliliit na patak na nabubuo mula sa singaw na ito.", "en": "Besides carbon dioxide, our breath carries water vapor. When you breathe onto a cold mirror or into cold air, you can see tiny droplets form from that vapor.", "bis": "Gawas sa carbon dioxide, ang atong ginhawa nagdala og alisngaw sa tubig. Kung moginhawa ka sa bugnaw nga salamin o sa bugnaw nga hangin, makita nimo ang gagmayng tulo nga mapormang gikan niini nga alisngaw."}, "source": "encyclopedia-stable consensus; NRC LS1.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "air-pushes-in-all-directions-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "gas pressure pushes in all directions", "grades": [6, 7, 8], "terms": ["gas", "hangin", "air", "pressure", "presyon", "tumutulak", "motulod", "lahat ng direksyon", "tanang direksyon", "particle", "tumatama", "tumama", "dingding", "bongbong", "lobo", "matigas", "masikip", "mabilis", "banggaan"], "fact": {"tl": "Ang presyon ng gas ay galing sa milyon-milyong particle nito na patuloy na tumatama sa mga dingding ng lalagyan mula sa loob. Tumutulak ang presyong ito sa lahat ng direksyon nang pantay-pantay — kaya tumitigas ang lobo o gulong kapag pinuno ng hangin.", "en": "Gas pressure comes from millions of its particles constantly hitting the walls of a container from the inside. This pressure pushes equally in all directions — which is why a balloon or tire becomes firm when filled with air.", "bis": "Ang presyon sa gas gikan sa minilyon nga particle niini nga padayong nag-igo sa mga bongbong sa sudlanan gikan sa sulod. Kini nga presyon motulod sa tanang direksyon nga managsama — mao nga mogahi ang lobo o ligid kung pun-on og hangin."}, "source": "NRC PS1.A; AAAS BSL Ch.4F", "generator": "claude-workflow", "reviewed": false},
  {"id": "squeezing-gas-raises-pressure-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "squeezing a gas raises its pressure", "grades": [7, 8], "terms": ["gas", "hangin", "air", "siksik", "compress", "piga", "pisil", "presyon", "pressure", "tumataas", "mosaka", "syringe", "bomba", "pump", "mas masikip", "particle", "mas madalas", "banggaan"], "fact": {"tl": "Kapag siniksik mo ang gas sa mas maliit na espasyo, mas madalas tumama ang mga particle nito sa dingding, kaya tumataas ang presyon. Kaya nararamdaman mong tumitigas ang dulo ng syringe kapag tinakpan mo ang butas at itinulak ang piston.", "en": "When you squeeze a gas into a smaller space, its particles hit the walls more often, so the pressure rises. That is why a syringe feels harder to push when you cover the tip and press the plunger.", "bis": "Kung imong i-compress ang gas ngadto sa mas gamayng espasyo, mas kanunay nga mo-igo ang mga particle niini sa bongbong, mao nga mosaka ang presyon. Mao nga mobati ka nga mogahi ang tumoy sa syringe kung taboni nimo ang lungag ug iduot ang piston."}, "source": "NRC PS1.A; AAAS BSL Ch.4F", "generator": "claude-workflow", "reviewed": false},
  {"id": "air-resistance-feels-like-push-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "moving fast through air feels like a push", "grades": [4, 5], "terms": ["hangin", "air", "huyop", "push", "tumutulak", "motulod", "kamay", "bintana", "sasakyan", "takbo", "dagan", "papel", "unti-unti", "dahan-dahan", "resistance", "nararamdaman", "gas"], "fact": {"tl": "Kahit hindi nakikita ang hangin, nararamdaman mo ito kapag mabilis kang gumalaw — gaya ng paglalabas ng kamay sa bintana ng tumatakbong sasakyan. Ang pakiramdam na 'tumutulak' ay ang hangin na tinutulak mo papalayo.", "en": "Even though air is invisible, you feel it when you move fast — like sticking your hand out the window of a moving car. That 'pushing' feeling is the air you are shoving out of the way.", "bis": "Bisan dili makita ang hangin, mabati nimo kini kung paspas ka molihok — sama sa pagpagawas sa imong kamot sa bintana sa nagdagan nga sakyanan. Kanang 'pagtulod' nga bation mao ang hangin nga imong gitulod palayo."}, "source": "NRC PS2.A; AAAS BSL Ch.4F", "generator": "claude-workflow", "reviewed": false},
  {"id": "gases-mix-evenly-g6", "domain": "MATTER", "topic": "gases mix together evenly", "grades": [6, 7], "terms": ["gas", "hangin", "air", "naghahalo", "magkasagol", "mix", "pantay", "patas", "kumakalat", "mokatag", "oxygen", "nitrogen", "magkasama", "sabay-sabay", "particle", "mabilis", "silid", "kwarto", "amoy"], "fact": {"tl": "Ang magkakaibang gas ay kusang naghahalo nang pantay-pantay dahil mabilis at malayang gumagalaw ang kanilang mga particle. Kaya magkakahalong mabuti ang oxygen at nitrogen sa hangin saanman sa isang silid.", "en": "Different gases mix together evenly on their own because their particles move fast and freely. That is why oxygen and nitrogen stay well mixed in the air everywhere in a room.", "bis": "Ang nagkalainlaing gas kusog nga magkasagol nga managsama tungod kay paspas ug gawasnong molihok ang ilang mga particle. Mao nga maayong magkasagol ang oxygen ug nitrogen sa hangin bisan asa sa kwarto."}, "source": "NRC PS1.A; AAAS BSL Ch.4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "plants-take-in-co2-g4", "domain": "LIVING_THINGS", "topic": "plants take in carbon dioxide", "grades": [4, 5, 6], "terms": ["halaman", "tanom", "plant", "carbon dioxide", "CO2", "sinisipsip", "gisuyop", "kinukuha", "gikuha", "dahon", "leaves", "photosynthesis", "pagkain", "gas", "hangin", "oxygen", "nilalabas", "gibuga"], "fact": {"tl": "Sinisipsip ng mga halaman ang carbon dioxide gas mula sa hangin sa pamamagitan ng kanilang mga dahon, at ginagamit ito para gumawa ng sariling pagkain. Bilang kapalit, naglalabas sila ng oxygen na hinihinga natin.", "en": "Plants take in carbon dioxide gas from the air through their leaves and use it to make their own food. In return, they give off the oxygen we breathe.", "bis": "Gisuyop sa mga tanom ang carbon dioxide gas gikan sa hangin pinaagi sa ilang mga dahon, ug gigamit kini aron makahimo sa ilang kaugalingong pagkaon. Baylo niini, mobuga sila og oxygen nga atong giginhawa."}, "source": "NRC LS1.C; AAAS BSL Ch.5", "generator": "claude-workflow", "reviewed": false},
  {"id": "too-much-co2-warms-earth-g7", "domain": "EARTH_SPACE", "topic": "carbon dioxide as a greenhouse gas", "grades": [7, 8], "terms": ["carbon dioxide", "CO2", "greenhouse gas", "init", "kainit", "Earth", "mundo", "kalibutan", "sobra", "dagdag", "pagbabago ng klima", "climate change", "init ng mundo", "global warming", "nagtatabon", "tinatago", "kumot", "fossil fuel"], "fact": {"tl": "Ang carbon dioxide ay isang greenhouse gas — nagtatabon ito ng init sa atmosphere tulad ng kumot. Kapag sobra ang CO₂ mula sa pagsunog ng karbon at langis, mas umiinit ang Earth, na siyang sanhi ng pagbabago ng klima.", "en": "Carbon dioxide is a greenhouse gas — it traps heat in the atmosphere like a blanket. When there is too much CO₂ from burning coal and oil, the Earth warms up, which drives climate change.", "bis": "Ang carbon dioxide usa ka greenhouse gas — gitago niini ang kainit sa atmosphere sama sa habol. Kung sobra ang CO₂ gikan sa pagsunog sa karbon ug lana, mas moinit ang Earth, nga maoy hinungdan sa pagbag-o sa klima."}, "source": "NRC ESS3.D; AAAS BSL Ch.4B", "generator": "claude-workflow", "reviewed": false},
  {"id": "oxygen-not-flammable-itself-g6", "domain": "MATTER", "topic": "oxygen does not burn by itself", "grades": [6, 7], "terms": ["oxygen", "oksiheno", "apoy", "kalayo", "fire", "nasusunog", "masunog", "hindi nasusunog", "dili masunog", "sumusuporta", "gatong", "sugnod", "fuel", "nagpapalakas", "gas", "kailangan"], "fact": {"tl": "Maraming nag-aakalang ang oxygen mismo ang nasusunog, pero hindi ito tama. Ang oxygen ay hindi nasusunog — sumusuporta lamang ito sa pagkasunog ng gatong gaya ng kahoy o gaas. Walang oxygen, hindi magkakaroon ng apoy.", "en": "Many people think oxygen itself burns, but that is not right. Oxygen does not burn — it only supports the burning of a fuel like wood or kerosene. Without oxygen, there can be no fire.", "bis": "Daghan ang naghunahuna nga ang oxygen mismo ang masunog, apan dili kini husto. Ang oxygen dili masunog — gisuportahan lang niini ang pagsunog sa sugnod sama sa kahoy o gas. Kung walay oxygen, walay kalayo."}, "source": "AAAS BSL Ch.4D; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gas-can-become-liquid-g7", "domain": "MATTER", "topic": "gases can be cooled into liquids", "grades": [7, 8], "terms": ["gas", "liquid", "tubig", "nagiging likido", "mahimong likido", "palamig", "bugnawon", "cool", "oxygen", "nitrogen", "liquid nitrogen", "napakalamig", "bugnaw kaayo", "tanke", "tangke", "condense", "pressure", "piga"], "fact": {"tl": "Kahit ang gas ay maaaring maging likido kung palalamigin nang husto o didiinin nang malakas. Halimbawa, ang nitrogen ay nagiging liquid nitrogen kapag pinalamig sa sobrang lamig na temperatura, at iniimbak ito sa mga espesyal na tangke.", "en": "Even a gas can turn into a liquid if it is cooled enough or squeezed hard enough. For example, nitrogen becomes liquid nitrogen when cooled to extremely low temperatures, and it is stored in special tanks.", "bis": "Bisan ang gas mahimong likido kung bugnawon pag-ayo o duoton og kusog. Pananglitan, ang nitrogen mahimong liquid nitrogen kung bugnawon sa hilabihan ka ubos nga temperatura, ug gitipigan kini sa espesyal nga mga tangke."}, "source": "NRC PS1.A; AAAS BSL Ch.4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "low-oxygen-on-mountains-g6", "domain": "EARTH_SPACE", "topic": "thinner air high on mountains", "grades": [6, 7], "terms": ["bundok", "bukid", "mountain", "taas", "mataas", "altitude", "manipis na hangin", "nipis nga hangin", "thin air", "oxygen", "kulang", "kapoy", "hingal", "hapong", "hininga", "ginhawa", "air pressure", "mababa"], "fact": {"tl": "Habang umaakyat ka sa mataas na bundok, mas manipis (mas kakaunti) ang hangin at mas kaunti ang oxygen sa bawat hininga. Kaya mas madaling mahingal at mapagod ang mga tao sa napakataas na lugar.", "en": "As you climb a high mountain, the air gets thinner and there is less oxygen in each breath. That is why people get out of breath and tired more easily at very high places.", "bis": "Samtang mosaka ka sa taas nga bukid, mas nipis (mas gamay) ang hangin ug mas gamay ang oxygen sa matag ginhawa. Mao nga mas dali maghangos ug makapoy ang mga tawo sa taas kaayo nga dapit."}, "source": "encyclopedia-stable consensus; NRC ESS2.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "vacuum-no-gas-g6", "domain": "MATTER", "topic": "a vacuum is space with no gas", "grades": [6, 7], "terms": ["vacuum", "walang laman", "walay sulod", "walang gas", "walay gas", "espasyo", "wala", "tinanggal", "gikuha", "gas", "hangin", "air", "kalawakan", "kawanangan", "space", "pump", "bomba"], "fact": {"tl": "Ang vacuum ay isang espasyo na halos walang gas o anumang particle. Maaari itong gawin sa pamamagitan ng pagbomba palabas ng hangin sa isang sisidlan — at ito rin ang dahilan kung bakit halos vacuum ang kalawakan.", "en": "A vacuum is a space with almost no gas or particles in it. It can be made by pumping the air out of a container — and it is also why outer space is nearly a vacuum.", "bis": "Ang vacuum usa ka espasyo nga halos walay gas o bisan unsang particle. Mahimo kining buhaton pinaagi sa pagbomba pagawas sa hangin gikan sa sudlanan — ug mao usab kini ang hinungdan nganong halos vacuum ang kawanangan."}, "source": "NRC PS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dissolved-oxygen-in-water-g6", "domain": "LIVING_THINGS", "topic": "oxygen dissolved in water", "grades": [6, 7], "terms": ["oxygen", "oksiheno", "tubig", "water", "natutunaw", "matunaw", "dissolved", "isda", "fish", "hasang", "gills", "huminga", "moginhawa", "gas", "ilog", "dagat", "lawa", "hangin", "nabubuhay"], "fact": {"tl": "May kaunting oxygen na natutunaw sa tubig, at ito ang hinihinga ng mga isda sa pamamagitan ng kanilang mga hasang. Kaya kahit nasa ilalim ng tubig, nakakakuha pa rin ng oxygen ang mga hayop sa dagat at ilog.", "en": "A small amount of oxygen dissolves in water, and this is the oxygen fish breathe through their gills. So even underwater, animals in the sea and rivers can still get oxygen.", "bis": "Adunay gamay nga oxygen nga matunaw sa tubig, ug mao kini ang giginhawa sa mga isda pinaagi sa ilang mga hasang. Mao nga bisan ilalom sa tubig, makakuha gihapon og oxygen ang mga mananap sa dagat ug suba."}, "source": "encyclopedia-stable consensus; NRC LS1.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "steam-is-water-as-gas-g5", "domain": "MATTER", "topic": "steam is water in gas form", "grades": [5, 6], "terms": ["steam", "singaw", "alisngaw", "tubig", "water", "gas", "kumukulo", "nagbukal", "nagbubukal", "init", "kainit", "invisible", "hindi nakikita", "ulap", "puti", "mainit", "pinakuluan", "kaldero"], "fact": {"tl": "Ang singaw (steam) ay tubig na naging gas dahil sa init. Ang tunay na steam ay hindi nakikita; ang puting ulap na nakikita sa itaas ng kumukulong tubig ay maliliit na patak na ng tubig na lumalamig na.", "en": "Steam is water that has turned into a gas because of heat. True steam is invisible; the white cloud you see above boiling water is actually tiny water droplets already cooling back down.", "bis": "Ang alisngaw (steam) mao ang tubig nga nahimong gas tungod sa kainit. Ang tinuod nga steam dili makita; ang puti nga panganod nga makita ibabaw sa nagbukal nga tubig mao na ang gagmayng tulo sa tubig nga nagbugnaw na."}, "source": "NRC PS1.A; AAAS BSL Ch.4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "air-needed-for-rust-and-rot-g6", "domain": "MATTER", "topic": "oxygen causes rust and browning", "grades": [6, 7], "terms": ["oxygen", "oksiheno", "kalawang", "taya", "rust", "bakal", "puthaw", "metal", "nabubulok", "madunot", "prutas", "mansanas", "apple", "kayumanggi", "nag-iiba", "hangin", "air", "reaksyon", "oxidation"], "fact": {"tl": "Marami sa hangin ang oxygen na dahan-dahang nakikipagreaksyon sa ibang bagay. Ito ang sanhi ng pagkalawang ng bakal at ng pagiging kayumanggi ng hiniwang mansanas kapag naiwan sa hangin.", "en": "The oxygen in air slowly reacts with other things. It is what makes iron rust and what turns a cut apple brown when it is left out in the air.", "bis": "Ang oxygen sa hangin hinay-hinay nga makig-reaksyon sa ubang butang. Mao kini ang hinungdan sa pagtaya sa puthaw ug sa pagkahimong kape ang giputol nga mansanas kung mabiyaan sa hangin."}, "source": "AAAS BSL Ch.4D; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gas-has-very-low-density-g6", "domain": "MATTER", "topic": "gases are far less dense than liquids and solids", "grades": [6, 7], "terms": ["gas", "density", "magaan", "gaan", "mababang density", "ubos nga density", "particle", "malayo", "layo sa usag usa", "liquid", "solid", "mass", "espasyo", "volume", "mas magaan", "hangin", "puwang"], "fact": {"tl": "Mas mababa ang density ng gas kaysa likido o solid dahil malalaki ang puwang sa pagitan ng mga particle nito. Ibig sabihin, mas kaunti ang mass ng gas sa parehong dami ng espasyo — kaya magaan ang isang lobong puno ng hangin.", "en": "A gas has a much lower density than a liquid or solid because its particles are far apart. This means there is less mass in the same amount of space — which is why a balloon full of air is light.", "bis": "Mas ubos ang density sa gas kaysa likido o solid kay dako ang puwang tali sa mga particle niini. Buot pasabot, mas gamay ang mass sa gas sa samang gidaghanon sa espasyo — mao nga gaan ang lobo nga puno sa hangin."}, "source": "NRC PS1.A; AAAS BSL Ch.4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "living-things-need-oxygen-g4", "domain": "LIVING_THINGS", "topic": "animals need oxygen to live", "grades": [3, 4, 5], "terms": ["oxygen", "oksiheno", "hayop", "mananap", "animal", "tao", "human", "huminga", "moginhawa", "ginhawa", "mabuhay", "mabuhi", "gas", "kailangan", "kinahanglan", "hangin", "air", "energy", "lakas", "pagkain"], "fact": {"tl": "Halos lahat ng hayop, kasama ang tao, ay nangangailangan ng oxygen para mabuhay. Ginagamit ng katawan ang oxygen para makakuha ng enerhiya mula sa pagkain — kaya hindi tayo makakahinto sa paghinga.", "en": "Almost all animals, including people, need oxygen to live. The body uses oxygen to get energy from food — which is why we cannot stop breathing.", "bis": "Halos tanang hayop, lakip ang tawo, nagkinahanglan og oxygen aron mabuhi. Gigamit sa lawas ang oxygen aron makakuha og kusog gikan sa pagkaon — mao nga dili ta makahunong sa pagginhawa."}, "source": "NRC LS1.C; AAAS BSL Ch.5", "generator": "claude-workflow", "reviewed": false},
  {"id": "heat-vs-temperature-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "heat versus temperature", "grades": [5, 6, 7], "terms": ["init", "temperatura", "kainitan", "termal na enerhiya", "kaibahan ng init at temperatura", "kainit", "init ug temperatura", "kalainan", "heat", "temperature", "difference", "thermal energy", "how hot"], "fact": {"tl": "Ang temperatura ay sukat kung gaano kainit o kalamig ang isang bagay, samantalang ang init ay ang enerhiyang dumadaloy mula sa mas mainit patungo sa mas malamig na bagay.", "en": "Temperature measures how hot or cold something is, while heat is the energy that flows from a hotter object to a cooler one.", "bis": "Ang temperatura mao ang sukod kung unsa ka-init o ka-bugnaw ang usa ka butang, samtang ang init mao ang enerhiya nga nagaagas gikan sa mas init paingon sa mas bugnaw nga butang."}, "source": "AAAS Benchmarks 4E/M3, 4E/M4; NRC PS3.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "bigger-object-more-heat-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "size and amount of heat", "grades": [6, 7, 8], "terms": ["mas malaki", "mas maraming init", "parehong temperatura", "dami ng init", "dako", "mas daghang init", "parehas nga temperatura", "bigger", "more heat", "same temperature", "amount of heat", "cup vs pot"], "fact": {"tl": "Ang isang malaking palayok ng maligamgam na tubig ay maaaring may mas maraming init kaysa sa isang maliit na tasa ng mainit na tubig, kahit mas mataas ang temperatura ng tasa.", "en": "A big pot of warm water can hold more total heat than a small cup of hot water, even though the cup has the higher temperature.", "bis": "Ang dakong kaldero sa init-init nga tubig mahimong adunay mas daghang init kaysa gamay nga tasa sa init nga tubig, bisan pa ug mas taas ang temperatura sa tasa."}, "source": "AAAS Benchmarks 4E/M4; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "heat-flows-hot-to-cold-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "direction of heat flow", "grades": [4, 5, 6], "terms": ["init", "dumadaloy", "mainit patungo malamig", "lumalamig", "umiinit", "init nagaagas", "init paingon bugnaw", "heat flows", "hot to cold", "warms up", "cools down"], "fact": {"tl": "Ang init ay palaging dumadaloy mula sa mas mainit na bagay patungo sa mas malamig hanggang sila ay magkaparehong temperatura.", "en": "Heat always flows from the warmer object to the cooler one until they reach the same temperature.", "bis": "Ang init kanunay nga nagaagas gikan sa mas init nga butang paingon sa mas bugnaw hangtod nga sila managsama na og temperatura."}, "source": "AAAS Benchmarks 4E/M3; NRC PS3.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "conduction-heat-transfer-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "conduction of heat", "grades": [6, 7, 8], "terms": ["kondaksyon", "pagdaloy ng init sa solido", "dikit na bagay", "kutsara sa sabaw", "konduksyon", "pagdagayday sa init", "pagdikit", "conduction", "heat through solids", "touching", "spoon in soup"], "fact": {"tl": "Sa kondaksyon, dumadaloy ang init sa loob ng isang solidong bagay habang ang mabibilis na umuugang maliliit na bahagi nito ay bumabangga sa mga katabi nila, tulad ng kutsarang umiinit sa mainit na sabaw.", "en": "In conduction, heat moves through a solid as its fast-jiggling tiny particles bump into their neighbors, like a spoon heating up in hot soup.", "bis": "Sa konduksyon, ang init mobalhin sa sulod sa usa ka solido samtang ang paspas nga nag-uyog nga gagmay nga bahin niini magbangga sa ilang silingan, sama sa kutsara nga mag-init sa init nga sabaw."}, "source": "AAAS Benchmarks 4E/M3; NRC PS3.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "convection-heat-transfer-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "convection of heat", "grades": [6, 7, 8], "terms": ["kombeksyon", "init sa tubig at hangin", "umaakyat na mainit", "agos ng init", "kombeksiyon", "init sa tubig ug hangin", "nagasaka nga init", "convection", "heat in liquids and gases", "rising warm water", "boiling"], "fact": {"tl": "Sa kombeksyon, umaakyat ang pinainit na tubig o hangin dahil ito ay mas magaan, at bumababa naman ang mas malamig, kaya umiikot ang init sa loob ng kumukulong tubig.", "en": "In convection, heated water or air rises because it becomes lighter while the cooler part sinks, making heat circulate inside boiling water.", "bis": "Sa konveksyon, ang gipainit nga tubig o hangin mosaka kay mas gaan kini, samtang ang mas bugnaw mounlod, mao nga ang init magtuyok sulod sa nagbukal nga tubig."}, "source": "AAAS Benchmarks 4E/M3, 4E/H8; NRC PS3.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "radiation-heat-transfer-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "radiation of heat", "grades": [6, 7, 8], "terms": ["radyasyon", "init mula sa araw", "init na dumadaan sa kawalan", "init nang hindi dumidikit", "radiation", "init gikan sa adlaw", "init nga moagi sa wala", "init walay paghikap", "heat across space", "sun's warmth", "no contact"], "fact": {"tl": "Sa radyasyon, naglalakbay ang init bilang mga di-nakikitang alon kaya naaabot tayo ng init ng araw kahit walang hangin sa pagitan natin at nito.", "en": "In radiation, heat travels as invisible waves, which is why the sun's warmth reaches us even though there is no air between us and the sun.", "bis": "Sa radyasyon, ang init mobiyahe isip dili makita nga mga balod, mao nga ang init sa adlaw makaabot kanato bisan walay hangin tunga kanato ug niini."}, "source": "AAAS Benchmarks 4E/M3, 4E/M6; NRC PS3.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "three-ways-heat-moves-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "three ways heat travels", "grades": [5, 6, 7], "terms": ["tatlong paraan ng paglipat ng init", "kondaksyon kombeksyon radyasyon", "paano gumagalaw ang init", "tulo ka paagi sa pagbalhin sa init", "konduksyon konveksyon radyasyon", "unsaon paglihok sa init", "three ways heat moves", "conduction convection radiation"], "fact": {"tl": "Ang init ay maaaring lumipat sa tatlong paraan: kondaksyon (sa pamamagitan ng dikit), kombeksyon (sa umaagos na tubig o hangin), at radyasyon (sa mga alon na dumadaan sa kawalan).", "en": "Heat can travel in three ways: conduction (through touching), convection (through flowing liquid or gas), and radiation (through waves crossing empty space).", "bis": "Ang init mahimong mobalhin sa tulo ka paagi: konduksyon (pinaagi sa paghikap), konveksyon (pinaagi sa nagaagas nga tubig o hangin), ug radyasyon (pinaagi sa mga balod nga moagi sa wala)."}, "source": "AAAS Benchmarks 4E/M3; NRC PS3.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "metals-good-conductors-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "metals conduct heat well", "grades": [4, 5, 6], "terms": ["metal", "mabuting tagahatid ng init", "bakal", "mabilis uminit", "konduktor sa init", "puthaw", "metal", "good conductor", "iron", "heats up fast", "conducts heat"], "fact": {"tl": "Ang mga metal tulad ng bakal at tanso ay magagaling na tagahatid ng init, kaya mabilis silang uminit at maglipat ng init.", "en": "Metals like iron and copper are good conductors of heat, so they warm up quickly and pass heat along fast.", "bis": "Ang mga metal sama sa puthaw ug tumbaga maayong tighatod sa init, mao nga sila paspas nga mag-init ug mobalhin sa init."}, "source": "AAAS Benchmarks Ch4 (conduction of heat as material property); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "insulators-block-heat-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "insulators of heat", "grades": [4, 5, 6], "terms": ["insulator", "hindi mabuting tagahatid ng init", "kahoy goma plastik", "humaharang sa init", "panangga sa init", "wala maghatod sa init", "insulator", "poor conductor", "wood rubber plastic", "blocks heat"], "fact": {"tl": "Ang mga insulator tulad ng kahoy, goma, at plastik ay hindi mabuting tagahatid ng init, kaya ginagamit ang mga ito sa hawakan ng kaldero upang hindi tayo mapaso.", "en": "Insulators like wood, rubber, and plastic are poor conductors of heat, so they are used for pot handles to keep us from getting burned.", "bis": "Ang mga insulator sama sa kahoy, goma, ug plastik dili maayong tighatod sa init, mao nga gigamit kini sa kuptanan sa kaldero aron dili ta mapaso."}, "source": "AAAS Benchmarks Ch4 (conduction of heat as material property); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "metal-feels-cold-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "why metal feels colder", "grades": [6, 7, 8], "terms": ["bakit malamig ang metal", "metal mas malamig pakiramdam", "kumukuha ng init sa kamay", "ngano bugnaw ang metal", "metal morag bugnaw", "mokuha sa init sa kamot", "why metal feels cold", "metal feels colder", "pulls heat from hand"], "fact": {"tl": "Mas malamig ang pakiramdam ng metal kaysa kahoy kahit pareho silang temperatura, dahil mabilis na inaalis ng metal ang init sa ating kamay.", "en": "Metal feels colder than wood even at the same temperature because metal quickly pulls heat away from our hand.", "bis": "Ang metal morag mas bugnaw kaysa kahoy bisan parehas silag temperatura, kay ang metal paspas nga mokuha sa init gikan sa atong kamot."}, "source": "encyclopedia-stable consensus (thermal conductivity)", "generator": "claude-workflow", "reviewed": false},
  {"id": "thermometer-liquid-rises-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "how a thermometer works", "grades": [5, 6, 7], "terms": ["paano gumagana ang termometro", "umaakyat na likido", "lumalawak kapag pinainit", "unsaon paglihok sa termometro", "nagasaka nga likido", "molapad kung painiton", "how thermometer works", "liquid rises", "expands when heated"], "fact": {"tl": "Gumagana ang ilang termometro dahil lumalawak at umaakyat ang likido sa loob ng manipis na tubo kapag mas mainit, at bumababa kapag mas malamig.", "en": "Some thermometers work because the liquid inside a thin tube expands and rises when it is hotter, and sinks when it is colder.", "bis": "Ang ubang termometro molihok kay ang likido sulod sa nipis nga tubo molapad ug mosaka kung mas init, ug mounlod kung mas bugnaw."}, "source": "encyclopedia-stable consensus (thermal expansion)", "generator": "claude-workflow", "reviewed": false},
  {"id": "celsius-water-points-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "Celsius scale and water", "grades": [5, 6, 7], "terms": ["Celsius", "digri", "kumukulo sa 100", "namumuo sa 0", "iskala ng temperatura", "grado", "mobukal sa 100", "moyelo sa 0", "degrees", "boils at 100", "freezes at 0", "temperature scale"], "fact": {"tl": "Sa Celsius na iskala, namumuo ang tubig sa 0 digri at kumukulo sa 100 digri sa karaniwang antas ng dagat.", "en": "On the Celsius scale, water freezes at 0 degrees and boils at 100 degrees at normal sea level.", "bis": "Sa Celsius nga iskala, ang tubig moyelo sa 0 ka grado ug mobukal sa 100 ka grado sa normal nga lebel sa dagat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "metal-expands-when-heated-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "thermal expansion of metal", "grades": [6, 7, 8], "terms": ["lumalawak ang metal", "umiinit nag-eexpand", "lumaki kapag mainit", "molapad ang metal", "mag-init molako", "thermal expansion", "metal expands", "gets bigger when hot", "swells"], "fact": {"tl": "Karamihan ng mga bagay tulad ng metal ay bahagyang lumalawak kapag pinainit at umuurong kapag pinalamig, dahil mas malayo ang pagitan ng mga umuugang maliliit na bahagi nito.", "en": "Most things like metal expand a little when heated and shrink when cooled, because their jiggling tiny particles spread farther apart.", "bis": "Kadaghanan sa mga butang sama sa metal molapad og gamay kung painiton ug mokulo kung bugnawon, kay ang nag-uyog nga gagmay nga bahin niini magkalayo og diyutay."}, "source": "encyclopedia-stable consensus (thermal expansion)", "generator": "claude-workflow", "reviewed": false},
  {"id": "railroad-gaps-expansion-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "expansion gaps in rails and bridges", "grades": [6, 7, 8], "terms": ["puwang sa riles", "tulay lumalawak", "gap sa tren", "pagitan para sa init", "gintang sa riles", "taytayan molapad", "puwang para init", "rail gaps", "bridge expansion", "expansion joint", "train tracks"], "fact": {"tl": "Ang mga riles ng tren at tulay ay binibigyan ng maliliit na puwang upang may lugar silang lawakan kapag uminit, at hindi sumiksik o mabaluktot.", "en": "Train rails and bridges are built with small gaps so they have room to expand when it gets hot, instead of buckling or bending.", "bis": "Ang mga riles sa tren ug mga taytayan gibuhatan og gagmay nga gintang aron adunay luna sila molapad kung mag-init, imbes nga mokuyos o mobaliko."}, "source": "encyclopedia-stable consensus (thermal expansion)", "generator": "claude-workflow", "reviewed": false},
  {"id": "heat-spreads-out-evenly-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "heat spreads until even", "grades": [6, 7, 8], "terms": ["kumakalat ang init", "pantay ang temperatura", "lumalamig na bagay", "nagkakalat", "mokatag ang init", "patas nga temperatura", "heat spreads", "evens out", "thermal equilibrium", "cools down"], "fact": {"tl": "Sa paglipas ng panahon, kumakalat ang init nang pantay sa isang bagay at sa mga bagay na magkadikit, kaya ang mainit ay lumalamig at ang malamig ay umiinit.", "en": "Over time, heat spreads out evenly through an object and between touching objects, so hot things cool down and cold things warm up.", "bis": "Sa paglabay sa panahon, ang init mokatag nga patas sa usa ka butang ug taliwala sa mga butang nga nagdikit, mao nga ang init mobugnaw ug ang bugnaw mag-init."}, "source": "AAAS Benchmarks 4E/M3", "generator": "claude-workflow", "reviewed": false},
  {"id": "dark-colors-absorb-heat-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "dark colors absorb more heat", "grades": [4, 5, 6], "terms": ["maitim na kulay umiinit", "itim sumisipsip ng init", "puti sumasalamin", "damit sa araw", "itom mosuyop sa init", "puti mopabalik", "dark absorbs heat", "black gets hotter", "white reflects", "clothes in sun"], "fact": {"tl": "Ang maiitim na kulay ay sumisipsip ng mas maraming init mula sa araw, kaya mas mainit ang pakiramdam ng itim na damit kaysa puti sa ilalim ng araw.", "en": "Dark colors absorb more heat from the sun, which is why black clothes feel hotter than white ones in the sunshine.", "bis": "Ang itom nga mga kolor mosuyop og mas daghang init gikan sa adlaw, mao nga ang itom nga sapot mas init og bati kaysa puti ilalom sa adlaw."}, "source": "AAAS Benchmarks 4E/M6; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-holds-heat-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "water stores a lot of heat", "grades": [6, 7, 8], "terms": ["tubig mabagal uminit", "tubig humahawak ng init", "matagal lumamig", "mabagal mag-init ang tubig", "tubig mohupot og init", "hinay mabugnaw", "water holds heat", "slow to heat", "slow to cool", "high heat capacity"], "fact": {"tl": "Ang tubig ay nakahahawak ng maraming init, kaya mabagal itong uminit at mabagal ding lumamig kumpara sa lupa o buhangin.", "en": "Water can hold a lot of heat, so it warms up slowly and also cools down slowly compared to soil or sand.", "bis": "Ang tubig makahupot og daghang init, mao nga hinay kining mag-init ug hinay usab mabugnaw kumpara sa yuta o balas."}, "source": "AAAS Benchmarks 4B/M9; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sea-breeze-convection-g7", "domain": "EARTH_SPACE", "topic": "sea breeze from uneven heating", "grades": [6, 7, 8], "terms": ["simoy ng dagat", "hangin mula dagat", "lupa mas mabilis uminit", "habagat na umiikot", "huyop sa dagat", "yuta paspas mag-init", "sea breeze", "land heats faster", "convection wind", "coastal breeze"], "fact": {"tl": "Sa tabing-dagat, mas mabilis uminit ang lupa kaysa tubig, kaya umaakyat ang mainit na hangin sa lupa at pumapalit ang mas malamig na hangin mula sa dagat bilang simoy.", "en": "At the coast, land heats faster than water, so warm air rises over the land and cooler air from the sea moves in as a sea breeze.", "bis": "Sa baybayon, ang yuta paspas mag-init kaysa tubig, mao nga ang init nga hangin mosaka ibabaw sa yuta ug ang mas bugnaw nga hangin gikan sa dagat mosulod isip huyop sa dagat."}, "source": "AAAS Benchmarks 4E/H8, 4B/H2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "vacuum-flask-keeps-warm-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "thermos blocks heat transfer", "grades": [6, 7, 8], "terms": ["termos", "panatilihin ang init", "humaharang sa lahat ng paglipat", "natatakpang lalagyan", "magpabilin ang init", "thermos", "vacuum flask", "keeps drinks hot", "blocks heat transfer"], "fact": {"tl": "Pinapanatili ng termos na mainit o malamig ang inumin sa pamamagitan ng pagharang sa kondaksyon, kombeksyon, at radyasyon nang sabay-sabay.", "en": "A thermos keeps a drink hot or cold by blocking conduction, convection, and radiation all at the same time.", "bis": "Ang termos magpabiling init o bugnaw ang ilimnon pinaagi sa pagbabag sa konduksyon, konveksyon, ug radyasyon sa dungan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "blowing-cools-food-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "blowing cools hot food", "grades": [3, 4, 5], "terms": ["hinihipan ang mainit na pagkain", "lumalamig kapag inihip", "init naaalis ng hangin", "huypan ang init nga pagkaon", "mobugnaw kung huypan", "blowing cools food", "blow on hot soup", "moving air"], "fact": {"tl": "Kapag hinihipan natin ang mainit na pagkain, mas mabilis itong lumalamig dahil tinatangay ng gumagalaw na hangin ang init palayo dito.", "en": "When we blow on hot food, it cools faster because the moving air carries the heat away from it.", "bis": "Kung huypan nato ang init nga pagkaon, mas paspas kining mobugnaw kay ang naglihok nga hangin modala sa init palayo niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sweat-cools-body-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "evaporation of sweat cools us", "grades": [5, 6, 7], "terms": ["pawis nagpapalamig", "sumisingaw ang pawis", "init nakukuha ng singaw", "ginhawa kapag pinawisan", "singot magpabugnaw", "moalisngaw ang singot", "sweat cools", "evaporation cools", "perspiration", "cooling off"], "fact": {"tl": "Kapag sumisingaw ang pawis mula sa ating balat, kinukuha nito ang init mula sa katawan, kaya nakakatulong ang pagpapawis para palamigin tayo.", "en": "When sweat evaporates from our skin, it takes heat away from the body, which is how sweating helps cool us down.", "bis": "Kung moalisngaw ang singot gikan sa atong panit, mokuha kini sa init gikan sa lawas, mao nga ang pagsingot makatabang sa pagpabugnaw kanato."}, "source": "encyclopedia-stable consensus (evaporative cooling)", "generator": "claude-workflow", "reviewed": false},
  {"id": "pot-handle-insulator-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "why pot handles are not metal", "grades": [3, 4, 5], "terms": ["hawakan ng kaldero", "kahoy o plastik na hawakan", "hindi mapaso", "kuptanan sa kaldero", "kahoy o plastik nga kuptanan", "dili mapaso", "pot handle", "wooden handle", "won't burn hand", "insulated grip"], "fact": {"tl": "Ang hawakan ng maraming kaldero ay gawa sa kahoy o plastik, hindi metal, upang hindi mabilis na dumaloy ang init sa ating kamay.", "en": "The handles of many pots are made of wood or plastic, not metal, so heat does not flow quickly into our hand.", "bis": "Ang kuptanan sa daghang kaldero hinimo sa kahoy o plastik, dili metal, aron ang init dili paspas nga moagas ngadto sa atong kamot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "air-good-insulator-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "trapped air insulates", "grades": [6, 7, 8], "terms": ["hangin mabuting insulator", "nakulong na hangin", "swetersa nagpapainit", "balahibo ng hayop", "nabilanggo nga hangin", "hangin maayong insulator", "sweater nagpainit", "trapped air insulates", "warm clothes", "fur feathers"], "fact": {"tl": "Ang nakulong na hangin ay mahusay na insulator, kaya ang makapal na swetersa, balahibo ng hayop, at malalambot na materyales na puno ng maliliit na bulsa ng hangin ay nagpapanatili ng init.", "en": "Trapped air is a good insulator, which is why a thick sweater, animal fur, and fluffy materials full of tiny air pockets keep heat in.", "bis": "Ang nabilanggo nga hangin maayo nga insulator, mao nga ang baga nga sweater, balhibo sa hayop, ug humok nga materyal nga puno sa gagmay nga lungag sa hangin magpabilin sa init."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "friction-makes-heat-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "rubbing produces heat", "grades": [4, 5, 6], "terms": ["pagkuskos gumagawa ng init", "magkiskisan umiinit", "init mula sa pagkikiskis", "pagkuskos sa kamot", "paghaplos magbutang og init", "kuskos mag-init", "rubbing makes heat", "friction heat", "warm hands"], "fact": {"tl": "Kapag pinagkukuskos natin ang ating mga kamay, gumagawa ng init ang pagkikiskis, kaya umiinit ang ating mga palad.", "en": "When we rub our hands together, the friction makes heat, so our palms get warm.", "bis": "Kung magkuskos kita sa atong mga kamot, ang paghaplos magbuhat og init, mao nga mag-init ang atong mga palad."}, "source": "encyclopedia-stable consensus (friction to thermal energy)", "generator": "claude-workflow", "reviewed": false},
  {"id": "ice-cools-by-taking-heat-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "ice cools by absorbing heat", "grades": [4, 5, 6], "terms": ["yelo kumukuha ng init", "natutunaw na yelo", "init pumupunta sa yelo", "walang lumalabas na lamig", "yelo mokuha sa init", "natunaw nga yelo", "ice takes heat", "melting ice", "heat flows into ice", "no cold flows out"], "fact": {"tl": "Hindi naglalabas ng lamig ang yelo; sa halip, kinukuha nito ang init mula sa paligid, kaya lumalamig ang inumin habang natutunaw ang yelo.", "en": "Ice does not give off cold; instead it takes heat from its surroundings, which is why a drink cools as the ice melts.", "bis": "Ang yelo wala magpagawas og kabugnaw; hinuon mokuha kini sa init gikan sa palibot, mao nga mobugnaw ang ilimnon samtang matunaw ang yelo."}, "source": "AAAS Benchmarks Ch4 (cold as transfer of heat); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "heat-from-energy-changes-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "energy changes give off heat", "grades": [7, 8, 9], "terms": ["enerhiya nagiging init", "init mula sa makina", "bombilya umiinit", "nasasayang na init", "enerhiya nahimong init", "init gikan sa makina", "energy becomes heat", "waste heat", "engine warms", "bulb gets hot"], "fact": {"tl": "Halos lahat ng pagbabago ng enerhiya ay gumagawa ng kaunting init, kaya umiinit ang makina ng sasakyan at ang bombilya kapag ginagamit.", "en": "Almost every energy change produces some heat, which is why a car engine and a light bulb get warm when they are used.", "bis": "Halos tanang kabag-ohan sa enerhiya magbuhat og gamay nga init, mao nga mag-init ang makina sa sakyanan ug ang bombilya kung gamiton."}, "source": "AAAS Benchmarks 4E/H3; NRC PS3.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "boiling-water-stays-hundred-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "boiling water holds steady temperature", "grades": [6, 7, 8], "terms": ["kumukulong tubig", "hindi na umiinit pataas", "100 digri sa pagkulo", "init napupunta sa singaw", "nagbukal nga tubig", "dili na mosaka ang init", "boiling water", "stays at 100", "extra heat to steam", "temperature plateau"], "fact": {"tl": "Habang kumukulo ang tubig, nananatili itong mga 100 digri Celsius dahil ang dagdag na init ay napupunta sa pagbabago ng tubig na maging singaw.", "en": "While water boils, it stays at about 100 degrees Celsius because the extra heat goes into turning the water into steam.", "bis": "Samtang nagbukal ang tubig, magpabilin kini sa mga 100 ka grado Celsius kay ang dugang nga init mopaingon sa pag-usab sa tubig ngadto sa alisngaw."}, "source": "encyclopedia-stable consensus (latent heat of vaporization)", "generator": "claude-workflow", "reviewed": false},
  {"id": "warm-air-rises-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "warm air rises", "grades": [4, 5, 6], "terms": ["mainit na hangin umaakyat", "pumapaitaas ang init", "globo ng hot air", "hangin sa kisame", "init nga hangin mosaka", "init nga hangin pataas", "warm air rises", "hot air balloon", "ceiling is warmer"], "fact": {"tl": "Ang mainit na hangin ay umaakyat dahil ito ay mas magaan kaysa malamig na hangin, kaya mas mainit sa itaas na bahagi ng isang silid kaysa sa sahig.", "en": "Warm air rises because it is lighter than cold air, so the top of a room is warmer than the floor.", "bis": "Ang init nga hangin mosaka kay mas gaan kini kaysa bugnaw nga hangin, mao nga mas init ang ibabaw nga bahin sa kwarto kaysa salog."}, "source": "AAAS Benchmarks 4E/H8; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cooking-pots-metal-bottom-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "metal pots conduct heat to food", "grades": [3, 4, 5], "terms": ["kaldero gawa sa metal", "metal naghahatid ng init sa pagkain", "mabilis magluto", "kaldero metal", "metal mohatod sa init sa pagkaon", "metal pot", "conducts heat to food", "cooks fast"], "fact": {"tl": "Ang mga kaldero at kawali ay gawa sa metal upang mabilis na maihatid ang init mula sa apoy patungo sa pagkain.", "en": "Pots and pans are made of metal so heat can pass quickly from the flame into the food.", "bis": "Ang mga kaldero ug kalaha hinimo sa metal aron paspas nga makahatod sa init gikan sa kalayo ngadto sa pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sound-is-a-wave-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "sound as a wave", "grades": [5, 6], "terms": ["alon ng tunog", "sound wave", "balod sa tingog", "alon", "wave", "tunog", "tingog", "sound", "vibrating air", "gaalon", "kumakalat"], "fact": {"tl": "Ang tunog ay isang uri ng alon — kapag may bagay na nayayanig, itinutulak nito ang mga particle ng hangin paroo't parito, at ang pagkalat na ito ng pag-yanig ang tinatawag nating alon ng tunog.", "en": "Sound is a kind of wave: when something vibrates, it pushes the air particles back and forth, and this spreading pattern of vibration is what we call a sound wave.", "bis": "Ang tingog usa ka matang sa balod — kon may butang nga magkurog, ituklod niini ang mga partikulo sa hangin balik-balik, ug kining pagkatag sa pagkurog mao ang gitawag natong balod sa tingog."}, "source": "NRC PS4.A; AAAS Benchmarks Ch.4 (waves)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sound-needs-medium-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "sound needs a medium", "grades": [4, 5], "terms": ["kailangan ng hangin", "kailangan ng medium", "sound needs air", "tunog kailangan", "tingog nanginahanglan", "needs material", "hangin tubig solid", "walang hangin walang tunog", "dili molabay"], "fact": {"tl": "Hindi makakalakbay ang tunog sa kawalan — kailangan nito ng isang bagay na madadaanan tulad ng hangin, tubig, o matigas na bagay; kaya't sa lugar na walang materyal, walang tunog.", "en": "Sound cannot travel through empty nothingness — it needs a material to pass through such as air, water, or a solid, so where there is no material there is no sound.", "bis": "Ang tingog dili makalakaw sa hawan nga wala — nanginahanglan kini ug butang nga maagian sama sa hangin, tubig, o gahi nga butang, busa kon walay materyal, walay tingog."}, "source": "NRC PS4.A; AAAS Benchmarks Ch.4", "generator": "claude-workflow", "reviewed": false},
  {"id": "sound-faster-in-water-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "sound travels faster in water", "grades": [6, 7], "terms": ["mas mabilis sa tubig", "sound in water", "tingog sa tubig", "mas paspas", "faster in water", "bilis ng tunog sa tubig", "underwater sound", "upat ka pilo", "four times", "apat na beses"], "fact": {"tl": "Mas mabilis maglakbay ang tunog sa tubig kaysa sa hangin — humigit-kumulang apat na beses na mas mabilis — kaya't malayo ang naaabot ng tawag ng mga balyena sa karagatan.", "en": "Sound travels faster in water than in air — about four times faster — which is why whale calls can reach so far across the ocean.", "bis": "Mas paspas molakaw ang tingog sa tubig kaysa sa hangin — mga upat ka pilo nga mas paspas — mao nga ang tawag sa mga balyena makaabot ug layo sa kadagatan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sound-fastest-in-solids-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "sound travels fastest in solids", "grades": [6, 7], "terms": ["pinakamabilis sa solido", "sound in solids", "tingog sa gahi", "bakal metal", "train track riles", "dingding wall", "pinakapaspas", "through walls", "kahoy"], "fact": {"tl": "Pinakamabilis maglakbay ang tunog sa matitigas na bagay tulad ng bakal o kahoy, dahil magkakalapit ang kanilang mga particle at mabilis nilang naipapasa ang yanig.", "en": "Sound travels fastest through solids like steel or wood, because their particles are packed close together and pass the vibration along quickly.", "bis": "Pinakapaspas molakaw ang tingog sa gahi nga mga butang sama sa puthaw o kahoy, kay duol ra ang ilang mga partikulo ug paspas nila ipasa ang pagkurog."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks Ch.4", "generator": "claude-workflow", "reviewed": false},
  {"id": "string-can-carry-sound-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "string telephone", "grades": [3, 4], "terms": ["lata at pisi", "string telephone", "telepono sa pisi", "tin can phone", "tunog sa pisi", "tingog sa hilo", "baso at tali", "cup phone", "gakurog ang pisi", "vibration travels"], "fact": {"tl": "Kung magkakabit ka ng dalawang lata gamit ang hinatak na pisi, makakausap mo ang kaibigan mo dahil dumadaloy ang yanig ng iyong boses sa pisi papunta sa kabilang lata.", "en": "If you join two cans with a tight string, you can talk to a friend because the vibration of your voice travels along the string to the other can.", "bis": "Kon imong idugtong ang duha ka lata pinaagi sa hugot nga pisi, makasulti ka sa imong higala kay ang pagkurog sa imong tingog molabay sa pisi paingon sa pikas lata."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pitch-from-frequency-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "pitch and frequency", "grades": [6, 7], "terms": ["taas ng tono", "pitch", "tono", "frequency", "dalas ng yanig", "kapaspas sa pagkurog", "high pitch low pitch", "mataas mababang tono", "faster vibration higher", "high note"], "fact": {"tl": "Ang taas ng tono (pitch) ay nakadepende sa dalas ng pag-yanig: mas mabilis ang pag-yanig, mas mataas ang tono; mas mabagal, mas mababa ang tono.", "en": "A sound's pitch depends on how often it vibrates: faster vibrations make a higher pitch, and slower vibrations make a lower pitch.", "bis": "Ang kataas sa tono (pitch) nagdepende sa kapaspas sa pagkurog: mas paspas ang pagkurog, mas taas ang tono; mas hinay, mas ubos ang tono."}, "source": "NRC PS4.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "loudness-from-amplitude-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "loudness and amplitude", "grades": [6, 7], "terms": ["lakas ng tunog", "loudness", "kakusog sa tingog", "amplitude", "laki ng yanig", "kadako sa pagkurog", "malakas mahina", "bigger vibration louder", "volume", "makusog"], "fact": {"tl": "Ang lakas ng tunog ay nakadepende sa laki ng pag-yanig: mas malaki ang galaw ng nayayanig na bagay, mas malakas ang tunog na naririnig natin.", "en": "How loud a sound is depends on the size of the vibration: the bigger the back-and-forth movement, the louder the sound we hear.", "bis": "Ang kakusog sa tingog nagdepende sa kadako sa pagkurog: mas dako ang lihok sa nagkurog nga butang, mas kusog ang tingog nga atong madungog."}, "source": "NRC PS4.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "decibels-measure-loudness-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "decibels", "grades": [7, 8], "terms": ["desibel", "decibel", "sukat ng lakas", "gisukod kakusog", "sukod sa kasaba", "loudness unit", "whisper jet", "bulong eroplano", "dB", "ingay sukat"], "fact": {"tl": "Sinusukat ang lakas ng tunog sa yunit na tinatawag na desibel (dB): ang bulong ay mga 30 dB, ang normal na usapan ay mga 60 dB, at ang umaalis na jet ay mahigit 120 dB.", "en": "Loudness is measured in units called decibels (dB): a whisper is about 30 dB, normal talking about 60 dB, and a jet taking off over 120 dB.", "bis": "Ang kakusog sa tingog gisukod sa yunit nga gitawag ug desibel (dB): ang hunghong mga 30 dB, ang normal nga panagsulti mga 60 dB, ug ang molupad nga jet kapin sa 120 dB."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "loud-sound-harms-hearing-g6", "domain": "LIVING_THINGS", "topic": "loud sound and hearing damage", "grades": [6, 7], "terms": ["malakas na tunog nakakasira", "hearing damage", "makadaot sa pandungog", "ingay nakakabingi", "saba makasamok dunggan", "earphones loud", "protect ears", "alagaan ang tainga", "makadaot sa dalunggan", "headphone kusog"], "fact": {"tl": "Ang sobrang lakas na tunog ay maaaring makasira sa maliliit na sensor sa loob ng tainga, kaya mabuting hindi palakasin nang husto ang earphone at takpan ang tainga kapag napakaingay.", "en": "Very loud sound can damage the tiny sensors inside the ear, so it is wise not to turn earphones up too high and to cover your ears when it is extremely noisy.", "bis": "Ang sobra ka kusog nga tingog makadaot sa gagmay nga sensor sa sulod sa dalunggan, busa maayo nga dili palabihan ug kusog ang earphone ug tabonan ang dalunggan kon sobra ka saba."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks Ch.6 (human health)", "generator": "claude-workflow", "reviewed": false},
  {"id": "ultrasound-too-high-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "ultrasound", "grades": [7, 8], "terms": ["ultrasound", "sobrang taas na tono", "dili madungog sa tawo", "ultrasonido", "tunog na hindi naririnig", "high frequency", "aso paniki", "dog bat hearing", "ultrasonic", "sonar buntis scan"], "fact": {"tl": "Ang ultrasound ay tunog na napakataas ng tono para marinig ng tao, pero naririnig ito ng mga aso at paniki, at ginagamit din ito sa hospital para makita ang sanggol sa sinapupunan.", "en": "Ultrasound is sound with a pitch too high for people to hear, but dogs and bats can hear it, and hospitals use it to see a baby inside the womb.", "bis": "Ang ultrasound usa ka tingog nga sobra ka taas ang tono aron madungog sa tawo, apan madungog kini sa mga iro ug kabog, ug gamiton sab kini sa hospital aron makita ang bata sa tagoangkan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "infrasound-too-low-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "infrasound", "grades": [7, 8], "terms": ["infrasound", "sobrang baba na tono", "dili madungog kay ubos", "tunog na napakababa", "low frequency", "elepante balyena", "elephant whale low sound", "infrasonido", "lindol bagyo tunog", "earthquake rumble"], "fact": {"tl": "Ang infrasound ay tunog na napakababa ng tono para marinig ng tao, ngunit ginagamit ito ng mga elepante at balyena para makipag-usap sa napakalayo.", "en": "Infrasound is sound with a pitch too low for people to hear, but elephants and whales use it to communicate across very long distances.", "bis": "Ang infrasound usa ka tingog nga sobra ka ubos ang tono aron madungog sa tawo, apan gamiton kini sa mga elepante ug balyena aron makig-istorya sa hilabihan ka layo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "echo-helps-measure-distance-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "echoes and sonar", "grades": [6, 7], "terms": ["alingawngaw sukat layo", "sonar", "echo distance", "gisukod ang gilay-on", "barko sonar", "ship depth ocean", "lalim ng dagat", "sukod sa kalawom", "time delay echo", "bounce back"], "fact": {"tl": "Dahil alam natin ang bilis ng tunog, magagamit ang alingawngaw para sukatin ang layo — gumagamit ang mga barko ng sonar, na nagpapadala ng tunog sa ilalim at nagbibilang kung gaano katagal bumalik ang alingawngaw.", "en": "Because we know how fast sound travels, an echo can be used to measure distance — ships use sonar, sending sound down and timing how long the echo takes to return.", "bis": "Tungod kay nahibalo ta sa kapaspas sa tingog, ang alingugngog magamit aron sukdon ang gilay-on — ang mga barko mogamit ug sonar, nga magpadala ug tingog sa ilawom ug mag-ihap kon unsa kadugay mobalik ang alingugngog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "voice-from-vocal-cords-g5", "domain": "LIVING_THINGS", "topic": "how we make our voice", "grades": [5, 6], "terms": ["boses vocal cords", "how voice works", "ngano naay tingog ang tawo", "kuwerdas sa boses", "larynx leeg", "gakurog ang vocal cords", "throat voice box", "lalamunan tunog", "tingog sa tawo", "vibrating cords"], "fact": {"tl": "Lumilikha tayo ng boses kapag dumadaan ang hangin mula sa baga sa dalawang manipis na laylayan ng laman sa leeg na tinatawag na vocal cords, na nayayanig at gumagawa ng tunog.", "en": "We make our voice when air from the lungs passes through two thin flaps in the throat called vocal cords, which vibrate and produce sound.", "bis": "Makahimo ta ug tingog kon ang hangin gikan sa baga moagi sa duha ka nipis nga panit sa liog nga gitawag ug vocal cords, nga magkurog ug mohimo ug tingog."}, "source": "AAAS Benchmarks Ch.6 (human organism); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "guitar-string-vibration-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "guitar and string instruments", "grades": [5, 6], "terms": ["gitara kuwerdas", "guitar string", "gitara kwerdas", "plucked string", "pinitik na kuwerdas", "string vibrates", "gakurog ang kuwerdas", "banghoy tunog", "instrumentong may kuwerdas", "violin"], "fact": {"tl": "Sa gitara at biyolin, gumagawa ng tunog ang nayayanig na kuwerdas kapag pinitik o hinihila; mas maikli o mas hinigpit ang kuwerdas, mas mataas ang tono.", "en": "In a guitar or violin, a vibrating string makes the sound when it is plucked or bowed; a shorter or tighter string gives a higher pitch.", "bis": "Sa gitara ug biyolin, ang nagkurog nga kuwerdas mao ang mohimo sa tingog kon kuhiton o hapyoron; mas mubo o mas hugot ang kuwerdas, mas taas ang tono."}, "source": "encyclopedia-stable consensus; NRC PS4.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "drum-membrane-vibration-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "drums and percussion", "grades": [4, 5], "terms": ["tambol balat", "drum", "drum skin", "gakurog ang panit sa tambol", "pinitpit na balat", "percussion", "tunog ng tambol", "bumbo", "membrane vibrates", "hinampas tambol"], "fact": {"tl": "Kapag pinukpok ang tambol, nayayanig ang nakaunat nitong balat pataas-pababa nang napakabilis, at ang yanig na ito ang nagtutulak sa hangin para lumikha ng tunog.", "en": "When a drum is struck, its stretched skin vibrates up and down very fast, and that vibration pushes the air to create the sound.", "bis": "Kon bunalan ang tambol, ang gibutang nga panit niini magkurog pataas-paubos ug paspas kaayo, ug kining pagkurog mao ang motuklod sa hangin aron makahimo ug tingog."}, "source": "encyclopedia-stable consensus; NRC PS4.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "wind-instrument-air-column-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "wind instruments", "grades": [6, 7], "terms": ["plawta plauta", "flute", "wind instrument", "hangin sa tubo", "gakurog ang hangin", "pluot trumpeta", "air column vibrates", "instrumentong hinihipan", "trumpet", "mas mahaba mas mababa"], "fact": {"tl": "Sa plawta at trumpeta, ang nayayanig ay ang hanging nasa loob ng tubo; mas mahaba ang haba ng dinaraanan ng hangin, mas mababa ang tono kaya kung tatakpan ang mga butas, nababago ang nota.", "en": "In a flute or trumpet, it is the air inside the tube that vibrates; a longer air path gives a lower pitch, which is why covering the holes changes the note.", "bis": "Sa plawta ug trumpeta, ang nagkurog mao ang hangin sa sulod sa tubo; mas taas ang agianan sa hangin, mas ubos ang tono, mao nga ang pagtabon sa mga lungag mag-usab sa nota."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "empty-bottle-pitch-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "pitch from water in a bottle", "grades": [5, 6], "terms": ["botelya tubig tono", "bottle pitch", "botelya tingog", "hihipan na botelya", "blowing bottle", "mas maraming tubig", "more water higher", "sukod sa tubig sa botelya", "experiment tunog", "resonance bottle"], "fact": {"tl": "Kapag hinipan mo ang bibig ng botelya, ang dami ng tubig sa loob ang magbabago ng tono: mas maraming tubig, mas kaunting hangin ang nayayanig, kaya mas mataas ang tunog.", "en": "When you blow across the mouth of a bottle, the amount of water inside changes the pitch: more water leaves less air to vibrate, so the sound is higher.", "bis": "Kon huyopan nimo ang baba sa botelya, ang gidaghanon sa tubig sa sulod mag-usab sa tono: mas daghan ang tubig, mas gamay ang hangin nga magkurog, busa mas taas ang tingog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sound-spreads-out-fainter-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "sound gets fainter with distance", "grades": [5, 6], "terms": ["humihina sa layo", "fainter farther", "mahuyang kon layo", "lumalayo mahina", "spreads out", "kumakalat kaya humihina", "gikalat ang enerhiya", "why distant sound quiet", "malayo mahinang tunog", "fades with distance"], "fact": {"tl": "Humihina ang tunog habang lumalayo ito sa pinanggalingan, dahil kumakalat ang enerhiya nito sa mas malawak na espasyo habang papalayo ang alon.", "en": "A sound grows fainter the farther it gets from its source, because its energy spreads out over a wider and wider space as the wave moves away.", "bis": "Ang tingog mahuyang samtang molayo kini gikan sa gigikanan, kay ang kusog niini magkatag sa mas lapad nga luna samtang ang balod molayo."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks Ch.4", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-shout-into-cupped-hands-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "cupping hands to be heard", "grades": [4, 5], "terms": ["nakakup na kamay sumigaw", "cup hands shout", "megaphone", "gisalipdan ang baba", "tinipon ang tunog", "direct the sound", "megapono", "tunog patungo", "funnel sound", "sigaw malakas"], "fact": {"tl": "Kapag nilagay mo ang mga kamay sa gilid ng iyong bibig habang sumisigaw, mas malayo ang naaabot ng boses mo dahil itinutuon nito ang tunog sa isang direksyon sa halip na ikalat ito sa paligid.", "en": "When you cup your hands around your mouth as you shout, your voice carries farther because it aims the sound in one direction instead of letting it spread all around.", "bis": "Kon ibutang nimo ang imong mga kamot sa kilid sa imong baba samtang magsinggit, mas layo ang maabot sa imong tingog kay gipunting niini ang tingog sa usa ka direksyon imbes ipakatag sa palibot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bat-echolocation-hunt-g5", "domain": "LIVING_THINGS", "topic": "bat echolocation", "grades": [5, 6], "terms": ["paniki echolocation", "bat sound hunt", "kabog tingog", "alingawngaw ng paniki", "clicks bat", "huni sa kabog pangita", "catch insects dark", "madilim lumilipad", "echolocation gabi", "find prey sound"], "fact": {"tl": "Ang paniki ay naghahanap ng pagkain sa dilim sa pamamagitan ng paglalabas ng mabibilis na tunog at pakikinig sa alingawngaw nito, kaya nahuhuli nito ang mga insekto kahit walang liwanag.", "en": "A bat finds food in the dark by sending out quick sounds and listening for their echoes, letting it catch insects even with no light at all.", "bis": "Ang kabog mangita ug pagkaon sa kangitngit pinaagi sa pagbuga ug paspas nga mga tingog ug pamati sa ilang alingugngog, mao nga makadakop kini ug insekto bisan walay kahayag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cricket-chirp-wings-g3", "domain": "LIVING_THINGS", "topic": "how crickets chirp", "grades": [3, 4], "terms": ["kuliglig huni", "cricket chirp", "kuliglig", "kagiw tingog", "kuliglig pakpak", "rubbing wings", "ihagod ang pako", "gabi tunog", "insect sound night", "stridulation"], "fact": {"tl": "Ang kuliglig ay gumagawa ng huni hindi sa pamamagitan ng bibig kundi sa paghagod ng isang pakpak sa kabila, na parang paghagod sa ngipin ng suklay.", "en": "A cricket makes its chirp not with its mouth but by rubbing one wing against the other, like running a fingernail over the teeth of a comb.", "bis": "Ang kagiw mohimo sa iyang huni dili pinaagi sa baba kondili pinaagi sa paghagod sa usa ka pako sa pikas, sama sa paghagod sa ngipon sa sudlay."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-block-ears-quieter-g3", "domain": "LIVING_THINGS", "topic": "covering ears blocks sound", "grades": [3, 4], "terms": ["takpan ang tainga", "cover ears quiet", "gitabonan ang dalunggan", "hina ng tunog takpan", "plug ears", "earplug", "gibara ang dunggan", "hadlang sa tunog", "block sound", "muffle noise"], "fact": {"tl": "Kapag tinakpan mo ang iyong tainga, mas mahina ang naririnig mo dahil hinaharang ng iyong kamay ang ilang yanig ng hangin bago ito makarating sa loob ng iyong tainga.", "en": "When you cover your ears, sounds get quieter because your hands block some of the air's vibrations before they can reach inside your ear.", "bis": "Kon tabonan nimo ang imong dalunggan, mahuyang ang imong madungog kay gibabagan sa imong kamot ang uban nga pagkurog sa hangin sa dili pa kini makaabot sa sulod sa imong dalunggan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "see-vibration-make-sound-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "seeing vibrations make sound", "grades": [4, 5], "terms": ["nakikitang yanig", "feel vibration sound", "makita ang pagkurog", "ruler sa lamesa", "hipo sa lalamunan boses", "feel throat hum", "gakurog dahan na ruler", "tuning fork tubig", "ripples water", "kabhang sa tingog"], "fact": {"tl": "Mararamdaman mong tunay na yanig ang gumagawa ng tunog: hawakan ang iyong lalamunan habang nag-iimik, o ilubog ang tumutunog na tuning fork sa tubig, at makikita mong gumagalaw ito.", "en": "You can feel that real vibration makes sound: hold your throat while you hum, or dip a ringing tuning fork into water, and you will see it shake the water.", "bis": "Imong mabati nga tinuod nga pagkurog ang mohimo sa tingog: kuptan ang imong liog samtang maghuni, o ituslob ang nagtingog nga tuning fork sa tubig, ug imong makita nga molihok kini."}, "source": "NRC PS4.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "speed-of-sound-count-thunder-g5", "domain": "EARTH_SPACE", "topic": "counting seconds to thunder", "grades": [5, 6], "terms": ["bilangin ang segundo kidlat", "count thunder seconds", "ihapa ang segundo kilat", "kidlat tapos kulog", "how far storm", "layo sa bagyo", "gilay-on sa dalugdog", "three seconds kilometer", "bagyo kalayo", "estimate distance lightning"], "fact": {"tl": "Dahil mas mabagal ang tunog kaysa liwanag, kung bibilangin mo ang mga segundo sa pagitan ng kidlat at kulog at hahatiin sa tatlo, makukuha mo ang tinatayang layo ng bagyo sa kilometro.", "en": "Because sound is slower than light, if you count the seconds between the lightning flash and the thunder and divide by three, you get the storm's rough distance in kilometers.", "bis": "Tungod kay mas hinay ang tingog kaysa kahayag, kon ihapon nimo ang mga segundo tali sa kilat ug dalugdog ug bahinon sa tulo, makuha nimo ang gibanabana nga gilay-on sa bagyo sa kilometro."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "soft-rooms-absorb-sound-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "why some rooms have less echo", "grades": [6, 7], "terms": ["malambot na bagay sumisipsip", "absorb sound", "gisuyop ang tingog", "kurtina karpet", "curtain carpet quiet", "walang alingawngaw kwarto", "empty room echo", "hubo nga kwarto", "soft surfaces muffle", "walang gamit kwarto"], "fact": {"tl": "Ang mga malalambot na bagay tulad ng kurtina, karpet, at unan ay sumisipsip ng tunog sa halip na ipatalbog ito, kaya walang gaanong alingawngaw sa isang kwartong puno ng ganitong gamit, ngunit malakas ang alingawngaw sa walang lamang silid.", "en": "Soft things like curtains, carpets, and cushions soak up sound instead of bouncing it back, which is why a room full of them has little echo while an empty room echoes loudly.", "bis": "Ang humok nga mga butang sama sa kurtina, karpet, ug unlan mosuyop sa tingog imbes ipabalik kini, mao nga ang kwarto nga puno niini gamay rag alingugngog samtang ang walay sulod nga kwarto kusog mo-alingugngog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sound-is-energy-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "sound is a form of energy", "grades": [4, 5], "terms": ["tunog ay enerhiya", "sound is energy", "tingog usa ka enerhiya", "enerhiya ng tunog", "carries energy", "nagdadala ng enerhiya", "gumagalaw ang bagay", "window rattle bass", "yumayanig ang bintana", "feel the bass"], "fact": {"tl": "Ang tunog ay isang anyo ng enerhiya — kaya nararamdaman mo ang pagyanig ng dibdib mo o ng bintana kapag napakalakas ng tugtog, dahil dala ng tunog ang enerhiyang nakakagalaw ng mga bagay.", "en": "Sound is a form of energy — that is why you can feel your chest or a window shake when music is very loud, because the sound carries energy that can move things.", "bis": "Ang tingog usa ka matang sa enerhiya — mao nga imong mabati ang pagkurog sa imong dughan o sa bintana kon kusog kaayo ang sonata, kay ang tingog nagdala ug enerhiya nga makapalihok sa mga butang."}, "source": "NRC PS4.A; AAAS Benchmarks Ch.4 (energy)", "generator": "claude-workflow", "reviewed": false},
  {"id": "animals-hear-higher-than-us-g5", "domain": "LIVING_THINGS", "topic": "animals hear sounds we cannot", "grades": [5, 6], "terms": ["aso naririnig na hindi natin", "animals hear higher", "makadungog ang iro ug dili nato", "silbato ng aso", "dog whistle", "mga hayop pandinig", "sharper hearing", "mas maganda pandinig hayop", "mataas na tono hayop", "bat dog hearing"], "fact": {"tl": "Maraming hayop ang nakakarinig ng mga tunog na hindi natin naririnig: naririnig ng aso ang tunog ng espesyal na silbato na tila tahimik sa atin, at mas mataas pa ang naririnig ng paniki at daga.", "en": "Many animals hear sounds we cannot: a dog can hear a special whistle that seems silent to us, and bats and mice can hear even higher pitches.", "bis": "Daghang hayop ang makadungog sa mga tingog nga dili nato madungog: ang iro makadungog sa espesyal nga silbato nga morag hilom para nato, ug ang kabog ug ilaga makadungog pa ug mas taas nga tono."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fridge-moves-heat-out-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "how a refrigerator cools", "grades": [5, 6, 7], "terms": ["refrigerator", "ref", "fridge", "palamigan", "refrigerador", "pridyider", "malamig", "lamig", "cold", "init", "heat", "inilalabas", "ginahawa", "ginakuha", "ipagawas", "likod", "luyo", "nagpapalamig", "nagpabugnaw", "mainit sa likod", "cooling"], "fact": {"tl": "Hindi gumagawa ng lamig ang refrigerator — sa halip, inilalabas nito ang init mula sa loob papunta sa hangin sa likuran, kaya nananatiling malamig ang loob at mainit ang mga tubo sa likod.", "en": "A refrigerator does not make cold — instead it moves heat out from inside to the air at the back, so the inside stays cold while the coils behind it feel warm.", "bis": "Ang refrigerator dili maghimo og bugnaw — hinuon ginakuha niini ang kainit gikan sa sulod ngadto sa hangin sa likod, mao nga magpabilin nga bugnaw ang sulod ug init ang mga tubo sa luyo."}, "source": "encyclopedia-stable consensus; NRC PS3.B (heat transfer)", "generator": "claude-workflow", "reviewed": false},
  {"id": "fridge-coolant-evaporates-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "refrigerant absorbs heat", "grades": [7, 8], "terms": ["refrigerant", "coolant", "gas", "likido", "sumisingaw", "mosinghot", "mosingaw", "kumukuha ng init", "mga tubo", "coils", "compressor", "kompresor", "umiikot", "paulit-ulit", "cycle", "palamigan", "refrigerator", "sumisikip", "dinidiin", "pinipiga"], "fact": {"tl": "Sa loob ng refrigerator ay may espesyal na likido (refrigerant) na sumisingaw at sumisipsip ng init mula sa pagkain, pagkatapos ay dinidiin ng compressor upang ilabas ang init sa likod — paulit-ulit ang ikot na ito.", "en": "Inside a refrigerator a special fluid called refrigerant evaporates and absorbs heat from the food, then a compressor squeezes it to release that heat at the back — this cycle repeats over and over.", "bis": "Sulod sa refrigerator adunay espesyal nga likido (refrigerant) nga mosingaw ug mosuyop sa kainit gikan sa pagkaon, dayon ipiga kini sa compressor aron ipagawas ang kainit sa luyo — balik-balik kini nga siklo."}, "source": "encyclopedia-stable consensus; NRC PS3.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "airplane-four-forces-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "the four forces on an airplane", "grades": [6, 7], "terms": ["eroplano", "ayroplano", "airplane", "plane", "lift", "weight", "bigat", "thrust", "tulak", "tutulak", "drag", "hila ng hangin", "apat na puwersa", "four forces", "lumilipad", "molupad", "nakakalipad", "pakpak", "makina", "engine", "tumutulak", "balanse"], "fact": {"tl": "Apat na puwersa ang kumikilos sa eroplano: ang lift na nagtataas dito, ang bigat na humihila pababa, ang thrust ng makina na nagtutulak pasulong, at ang drag ng hangin na pumipigil dito.", "en": "Four forces act on an airplane: lift pushing it up, weight pulling it down, thrust from the engines pushing it forward, and drag from the air holding it back.", "bis": "Upat ka puwersa ang molihok sa eroplano: ang lift nga magpataas niini, ang gibug-aton nga mobira paubos, ang thrust sa makina nga motulod pasulong, ug ang drag sa hangin nga mopugong niini."}, "source": "encyclopedia-stable consensus; NRC PS2 (forces); AAAS BSL Ch.8", "generator": "claude-workflow", "reviewed": false},
  {"id": "jet-engine-pushes-air-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "how a jet engine pushes a plane", "grades": [7, 8], "terms": ["jet engine", "makina ng eroplano", "jet", "sumisipsip ng hangin", "ginasuyop", "sumusunog", "gasolina", "fuel", "init", "mabilis", "gas", "palabas sa likod", "tumutulak pasulong", "molupad", "reaction", "aksyon", "tutulak", "turbine", "sumusulpot", "airplane", "eroplano"], "fact": {"tl": "Ang jet engine ay sumisipsip ng hangin sa harap, hinahalo ito sa panggatong at sinusunog, pagkatapos ay binubuga ang mainit na gas nang napakabilis sa likod — at ang pagbuga na iyon ang tumutulak sa eroplano pasulong.", "en": "A jet engine sucks in air at the front, mixes it with fuel and burns it, then blasts the hot gas out the back very fast — and that backward blast pushes the plane forward.", "bis": "Ang jet engine mosuyop og hangin sa atubangan, isagol kini sa gasolina ug sunogon, dayon ibuga ang init nga gas nga paspas kaayo sa likod — ug kanang pagbuga maoy motulod sa eroplano pasulong."}, "source": "encyclopedia-stable consensus; NRC PS2 (Newton's third law)", "generator": "claude-workflow", "reviewed": false},
  {"id": "car-engine-burns-fuel-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "how a car engine works", "grades": [6, 7], "terms": ["makina ng kotse", "car engine", "sasakyan", "kotse", "awto", "sumusunog", "gasolina", "fuel", "panggatong", "pagsabog", "explosion", "piston", "pumppistol", "umaakyat-bumababa", "gumagalaw", "gulong", "pumapaandar", "internal combustion", "init", "enerhiya", "engine"], "fact": {"tl": "Ang makina ng kotse ay sumusunog ng gasolina sa loob ng maliliit na silid, at ang maliliit na pagsabog na ito ang nagtutulak sa mga piston pataas at pababa nang mabilisan upang paandarin ang mga gulong.", "en": "A car engine burns gasoline inside small chambers, and these tiny explosions push pistons up and down very fast, which turns the wheels.", "bis": "Ang makina sa awto mosunog og gasolina sulod sa gagmay nga mga kwarto, ug kining gagmay nga pagbuto motulod sa mga piston pataas ug paubos nga paspas aron padaganon ang mga ligid."}, "source": "encyclopedia-stable consensus; NRC PS3.B (energy from fuel)", "generator": "claude-workflow", "reviewed": false},
  {"id": "car-engine-needs-air-g7", "domain": "MATTER", "topic": "engines need air to burn fuel", "grades": [7, 8], "terms": ["makina", "engine", "hangin", "air", "oxygen", "oksiheno", "sunog", "pagkasunog", "combustion", "gasolina", "fuel", "panggatong", "kailangan ng hangin", "kinahanglan og hangin", "usok", "aso", "exhaust", "tambutso", "carbon dioxide", "tubo"], "fact": {"tl": "Kailangan ng makina ng kotse ang oxygen mula sa hangin para masunog ang gasolina, at ang mga gas na nabubuo (tulad ng carbon dioxide at usok) ay lumalabas sa tambutso (exhaust).", "en": "A car engine needs oxygen from the air to burn its gasoline, and the gases that form (like carbon dioxide and smoke) leave through the exhaust pipe.", "bis": "Ang makina sa awto nagkinahanglan og oxygen gikan sa hangin aron masunog ang gasolina, ug ang mga gas nga maporma (sama sa carbon dioxide ug aso) mogawas sa tambutso (exhaust)."}, "source": "encyclopedia-stable consensus; NRC PS1.B (combustion)", "generator": "claude-workflow", "reviewed": false},
  {"id": "bicycle-balance-moving-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "why a moving bicycle stays up", "grades": [4, 5, 6], "terms": ["bisikleta", "bicycle", "bike", "umaandar", "gumagalaw", "pumapadyak", "hindi nahuhulog", "tuwid", "balanse", "balance", "manibela", "steering", "ililiko", "tumutumba kapag tumigil", "molihok", "wala matumba", "gulong", "ligid", "nakatayo", "stable"], "fact": {"tl": "Mas madaling panatilihing tuwid ang bisikleta kapag gumagalaw kaysa nakatigil, dahil ang maliliit na paggalaw ng manibela ay nakakatulong na ibalik ito sa balanse.", "en": "A bicycle is easier to keep upright when it is moving than when it is still, because small steering movements can bring it back into balance.", "bis": "Mas sayon nga magpabilin nga tul-id ang bisikleta kon naglihok kay sa naghunong, kay ang gagmay nga paglihok sa manibela makatabang nga mabalik kini sa balanse."}, "source": "encyclopedia-stable consensus; NRC PS2 (forces and motion); corrected to avoid contested gyroscopic-only claim", "generator": "claude-workflow", "reviewed": false},
  {"id": "bicycle-gears-chain-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "how bicycle gears and chain work", "grades": [6, 7], "terms": ["bisikleta", "bicycle", "gear", "engranahe", "kadena", "chain", "pedal", "padyak", "pinapadyak", "umiikot", "gulong sa likod", "ginagaan", "mahirap", "kuwesta", "akyat", "matarik", "makapasayon", "pataas", "pababa", "talim", "sprocket", "baguhin"], "fact": {"tl": "Sa bisikleta, ang kadena ay nag-uugnay sa pedal at sa gulong sa likod sa pamamagitan ng mga gear; ang pagpili ng tamang gear ay nagpapagaan ng pagpadyak sa matarik na akyat o nagpapabilis sa patag na daan.", "en": "On a bicycle, the chain links the pedals to the back wheel through gears; choosing the right gear makes pedaling easier on a steep hill or faster on flat ground.", "bis": "Sa bisikleta, ang kadena nagsumpay sa pedal ug sa likod nga ligid pinaagi sa mga gear; ang pagpili sa hustong gear makapasayon sa pagpedal sa tarik nga sak-anan o makapaspas sa patag nga dalan."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.8 (gears)", "generator": "claude-workflow", "reviewed": false},
  {"id": "bicycle-brakes-friction-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "how brakes stop a bicycle", "grades": [5, 6, 7], "terms": ["preno", "brake", "bisikleta", "bicycle", "huminto", "mohunong", "tumigil", "friction", "kuskos", "goma", "rubber pad", "dumidiin sa gulong", "kapit", "init", "slows down", "bumabagal", "kuskusan", "gilis", "mopahunong", "nagpapabagal"], "fact": {"tl": "Huminto ang bisikleta kapag dumidiin ang mga goma ng preno (brake) sa umiikot na gulong; ang kuskusan o friction sa pagitan nila ang nagpapabagal at nagpapatigil dito.", "en": "A bicycle stops when the rubber brake pads press against the spinning wheel; the friction between them slows the wheel down and brings it to a stop.", "bis": "Mohunong ang bisikleta kon ang mga goma sa preno (brake) modiin sa nagtuyok nga ligid; ang friction o kuskusanay tali kanila maoy mopahinay ug mopahunong niini."}, "source": "encyclopedia-stable consensus; NRC PS2 (friction)", "generator": "claude-workflow", "reviewed": false},
  {"id": "elevator-counterweight-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "how an elevator works", "grades": [6, 7], "terms": ["elevator", "asensor", "lift", "umaakyat", "bumababa", "gusali", "building", "kable", "cable", "lubid", "kontrapeso", "counterweight", "motor", "makina", "pulley", "kalo", "balanse", "ginagaan", "hinihila", "nagaakyat", "nagpapataas"], "fact": {"tl": "Ang elevator ay hinihila pataas at pababa ng mga matitibay na kable na nakabalot sa isang motor, at may mabigat na counterweight sa kabilang dulo na nagpapagaan sa trabaho ng motor.", "en": "An elevator is pulled up and down by strong cables wound around a motor, and a heavy counterweight on the other end balances the load so the motor works less hard.", "bis": "Ang elevator ginabira pataas ug paubos sa lig-on nga mga kable nga giputos sa usa ka motor, ug adunay bug-at nga counterweight sa pikas tumoy nga mobalanse sa karga aron mas gaan ang trabaho sa motor."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.8; NRC PS2", "generator": "claude-workflow", "reviewed": false},
  {"id": "escalator-moving-stairs-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "how an escalator works", "grades": [4, 5, 6], "terms": ["escalator", "gumagalaw na hagdan", "moving stairs", "hagdan", "baitang", "steps", "loop", "tumatakbo", "umiikot", "motor", "kadena", "chain", "mall", "umaakyat", "bumababa", "naglilibot", "nagatakbo", "kuryente", "paikot"], "fact": {"tl": "Ang escalator ay isang gumagalaw na hagdan na ang mga baitang ay nakakabit sa isang mahabang kadena na umiikot nang paulit-ulit, pinapaandar ng isang motor.", "en": "An escalator is a moving staircase whose steps are attached to a long chain that loops around again and again, driven by a motor.", "bis": "Ang escalator usa ka naglihok nga hagdanan kansang mga baitang nasumpay sa taas nga kadena nga magtuyok balik-balik, gipadagan sa usa ka motor."}, "source": "encyclopedia-stable consensus; NRC PS3 (energy in machines)", "generator": "claude-workflow", "reviewed": false},
  {"id": "incandescent-bulb-glows-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "how an old light bulb glows", "grades": [6, 7], "terms": ["bombilya", "light bulb", "ilaw", "suga", "incandescent", "filament", "manipis na kawad", "thin wire", "umiinit", "mainit", "nagbabaga", "nagniningning", "glow", "kuryente", "kainit", "liwanag", "kahayag", "wire", "nagliliwanag", "puti"], "fact": {"tl": "Sa lumang uri ng bombilya (incandescent), dumadaan ang kuryente sa isang napakanipis na kawad na tinatawag na filament; uminit ito nang husto kaya nagbabaga at nagliliwanag.", "en": "In the old kind of light bulb (incandescent), electricity passes through a very thin wire called a filament; it heats up so much that it glows and gives off light.", "bis": "Sa karaang klase sa bombilya (incandescent), moagi ang kuryente sa nipis kaayo nga kawad nga gitawag og filament; moinit kini pag-ayo mao nga mobaga ug mohatag og kahayag."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.4 (energy to light)", "generator": "claude-workflow", "reviewed": false},
  {"id": "led-bulb-efficient-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "why LED bulbs save energy", "grades": [6, 7], "terms": ["LED", "led bulb", "bombilya", "ilaw", "suga", "matipid", "nakakatipid", "kuryente", "energy", "init", "mainit", "malamig", "mas kaunti", "walang filament", "modern", "bagong bombilya", "gumagana", "nagliliwanag", "liwanag", "kahayag", "tipid"], "fact": {"tl": "Ang LED bulb ay gumagawa ng liwanag mula sa kuryente nang hindi muna umiinit nang husto, kaya mas matipid ito sa kuryente at hindi gaanong nag-iinit kaysa lumang bombilya.", "en": "An LED bulb makes light from electricity without first getting very hot, so it uses much less energy and stays cooler than an old-style bulb.", "bis": "Ang LED bulb maghimo og kahayag gikan sa kuryente nga dili una moinit pag-ayo, mao nga mas tipid kini sa kuryente ug dili kaayo moinit kay sa karaang bombilya."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.8 (designed world)", "generator": "claude-workflow", "reviewed": false},
  {"id": "phone-radio-waves-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "how a phone sends calls", "grades": [6, 7], "terms": ["cellphone", "telepono", "selpon", "phone", "tawag", "call", "text", "mensahe", "radio waves", "alon ng radyo", "signal", "senyales", "tore", "cell tower", "antenna", "walang kable", "wireless", "nagpapadala", "ginapadala", "hangin", "mabilis"], "fact": {"tl": "Ang cellphone ay nagpapadala at tumatanggap ng mga radio wave — isang uri ng nakatagong alon — na naglalakbay sa hangin papunta sa malalaking tore (cell tower) na nag-uugnay sa iyong tawag o text sa ibang tao.", "en": "A cellphone sends and receives radio waves — a kind of invisible wave — that travel through the air to tall cell towers, which connect your call or text to another person.", "bis": "Ang cellphone magpadala ug modawat og radio waves — usa ka klase sa dili makita nga balod — nga moagi sa hangin padulong sa tag-as nga mga tore (cell tower) nga magsumpay sa imong tawag o text ngadto sa laing tawo."}, "source": "encyclopedia-stable consensus; NRC PS4.C (information technologies)", "generator": "claude-workflow", "reviewed": false},
  {"id": "computer-binary-onoff-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "how a computer stores information", "grades": [7, 8], "terms": ["computer", "kompyuter", "cellphone", "telepono", "binary", "1 at 0", "on off", "bukas sarado", "switch", "bilyon", "milyon", "tiny switches", "maliliit na switch", "impormasyon", "information", "larawan", "numero", "letra", "memory", "nag-iimbak", "ginatipig", "chip", "kuryente"], "fact": {"tl": "Iniimbak ng computer at cellphone ang lahat — larawan, salita, at musika — bilang milyon-milyong maliliit na switch na naka-on o naka-off lamang, na kinakatawan ng mga 1 at 0.", "en": "A computer or phone stores everything — pictures, words, and music — as millions of tiny switches that are simply on or off, written as 1s and 0s.", "bis": "Ang computer ug cellphone magtipig sa tanan — hulagway, pulong, ug musika — isip minilyon ka gagmay nga switch nga naka-on o naka-off lang, gisulat isip mga 1 ug 0."}, "source": "encyclopedia-stable consensus; NRC PS4.C (digitized information)", "generator": "claude-workflow", "reviewed": false},
  {"id": "computer-chip-transistors-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "what is a computer chip", "grades": [8, 9], "terms": ["chip", "microchip", "computer", "kompyuter", "cellphone", "transistor", "switch", "maliit", "silicon", "bilyon", "kalkulasyon", "computation", "mabilis", "utak ng kompyuter", "brain", "kuryente", "kontrolado", "proseso", "ginaproseso", "silisyon"], "fact": {"tl": "Ang utak ng computer ay isang maliit na chip na puno ng bilyon-bilyong napakaliliit na switch na tinatawag na transistor, na napakabilis na nagbubukas at nagsasara para magkalkula.", "en": "The brain of a computer is a tiny chip packed with billions of extremely small switches called transistors, which turn on and off incredibly fast to do calculations.", "bis": "Ang utok sa computer usa ka gamay nga chip nga puno sa binilyon ka gagmay kaayo nga switch nga gitawag og transistor, nga moabli ug mosira nga paspas kaayo aron makakwenta."}, "source": "encyclopedia-stable consensus; NRC PS4.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "wifi-invisible-waves-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "how wifi connects devices", "grades": [5, 6, 7], "terms": ["wifi", "wi-fi", "internet", "walang kable", "wireless", "radio waves", "alon", "signal", "senyales", "router", "cellphone", "telepono", "computer", "kompyuter", "hangin", "nakatago", "invisible", "nagkokonekta", "nagsusumpay", "nagdadala", "data"], "fact": {"tl": "Ang Wi-Fi ay gumagamit ng mga nakatagong radio wave para magpadala ng impormasyon sa pagitan ng isang router at ng iyong telepono o computer nang hindi gumagamit ng kable.", "en": "Wi-Fi uses invisible radio waves to carry information between a router and your phone or computer without any wires.", "bis": "Ang Wi-Fi mogamit og dili makita nga radio waves aron magdala og impormasyon tali sa router ug sa imong telepono o computer nga walay kable."}, "source": "encyclopedia-stable consensus; NRC PS4.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "airplane-tilts-flaps-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "how a plane turns and climbs", "grades": [7, 8], "terms": ["eroplano", "airplane", "plane", "pumipihit", "lumiliko", "umaakyat", "bumababa", "flaps", "rudder", "pakpak", "buntot", "tail", "gumagalaw na bahagi", "control", "piloto", "pilot", "direksyon", "kontrolado", "banking", "ikinikiling", "steering"], "fact": {"tl": "Pinipihit at iniaangat ng piloto ang eroplano sa pamamagitan ng pagkilos ng maliliit na bahagi sa pakpak at buntot (flaps at rudder), na nagbabago kung paano umaagos ang hangin sa palibot nito.", "en": "A pilot turns and climbs an airplane by moving small parts on the wings and tail (flaps and rudder), which change how the air flows around it.", "bis": "Pihiton ug ipataas sa piloto ang eroplano pinaagi sa paglihok sa gagmay nga bahin sa pako ug ikog (flaps ug rudder), nga mausab kung unsaon pag-agos sa hangin libot niini."}, "source": "encyclopedia-stable consensus; NRC PS2 (forces)", "generator": "claude-workflow", "reviewed": false},
  {"id": "car-brakes-friction-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "how car brakes work", "grades": [6, 7], "terms": ["preno", "brake", "kotse", "sasakyan", "awto", "car", "huminto", "tumigil", "mohunong", "friction", "kuskusan", "init", "mainit", "disc", "goma", "dumidiin", "slows down", "bumabagal", "ligid", "gulong", "nagpapatigil", "kinetic energy"], "fact": {"tl": "Huminto ang kotse kapag ang mga preno ay dumidiin sa umiikot na gulong; ang friction ay nagbabago ng enerhiya ng paggalaw tungo sa init, kaya umiinit ang preno habang bumabagal ang kotse.", "en": "A car stops when its brakes press against the spinning wheels; friction changes the energy of motion into heat, so the brakes get hot as the car slows down.", "bis": "Mohunong ang awto kon ang mga preno modiin sa nagtuyok nga ligid; ang friction mag-usab sa enerhiya sa paglihok ngadto sa kainit, mao nga moinit ang preno samtang mohinay ang awto."}, "source": "encyclopedia-stable consensus; NRC PS3.B (energy and friction)", "generator": "claude-workflow", "reviewed": false},
  {"id": "freezer-makes-ice-g4", "domain": "MATTER", "topic": "how a freezer makes ice", "grades": [4, 5], "terms": ["freezer", "palamigan", "ref", "fridge", "yelo", "ice", "tubig", "water", "nagyeyelo", "nagayelo", "frozen", "malamig", "nagbabato", "solid", "init", "inalis", "nagiging solid", "nagtitigas", "nagbabago anyo", "cold"], "fact": {"tl": "Gumagawa ng yelo ang freezer sa pamamagitan ng pag-alis ng init sa tubig hanggang sa lumamig ito nang husto at maging solid — ang tubig ay nagiging yelo kapag napakalamig na.", "en": "A freezer makes ice by taking heat away from water until it gets so cold that it turns solid — water becomes ice when it is cold enough.", "bis": "Maghimo og yelo ang freezer pinaagi sa pagkuha sa kainit gikan sa tubig hangtod nga mobugnaw kini pag-ayo ug mahimong gahi — mahimong yelo ang tubig kon bugnaw na kaayo."}, "source": "encyclopedia-stable consensus; NRC PS1.A (states of matter)", "generator": "claude-workflow", "reviewed": false},
  {"id": "battery-rechargeable-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "how a rechargeable battery works", "grades": [6, 7], "terms": ["battery", "baterya", "rechargeable", "kinakarga", "ginacharge", "tinatapatan", "kuryente", "muling pinupuno", "reused", "cellphone", "telepono", "ubos", "empty", "puno", "full", "chemical", "kemikal", "binabaligtad", "reverse", "nag-iimbak"], "fact": {"tl": "Ang rechargeable na baterya ay maaaring punuin muli: kapag kinakarga (charge) mo ito, ibinabalik ng kuryente ang chemical energy sa loob nito upang magamit muli, tulad sa cellphone.", "en": "A rechargeable battery can be filled again: when you charge it, electricity pushes the chemical energy back inside so it can be used over and over, like in a phone.", "bis": "Ang rechargeable nga baterya mahimong pun-on pag-usab: kon i-charge nimo kini, ang kuryente mobalik sa chemical energy sa sulod aron magamit balik-balik, sama sa cellphone."}, "source": "encyclopedia-stable consensus; NRC PS3.A (energy storage)", "generator": "claude-workflow", "reviewed": false},
  {"id": "airplane-jet-vs-propeller-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "jet planes vs propeller planes", "grades": [6, 7], "terms": ["eroplano", "airplane", "jet", "propeller", "propela", "helices", "umiikot", "spinning blades", "makina", "engine", "tumutulak", "hangin", "mabilis", "mabagal", "maliit na eroplano", "malaking eroplano", "molupad", "tumutulak pasulong", "blades", "paspas"], "fact": {"tl": "May mga eroplanong may umiikot na propeller na humahawi ng hangin para sumulong, at may mga jet na bumubuga ng mainit na gas; ang jet ay karaniwang mas mabilis at para sa mahabang biyahe.", "en": "Some planes use a spinning propeller that pushes air to move forward, while jets blast out hot gas; jets are usually faster and used for long trips.", "bis": "Ang ubang eroplano mogamit og nagtuyok nga propeller nga moduso sa hangin aron mosulong, samtang ang jet mobuga og init nga gas; ang jet kasagaran mas paspas ug gigamit alang sa taas nga biyahe."}, "source": "encyclopedia-stable consensus; NRC PS2", "generator": "claude-workflow", "reviewed": false},
  {"id": "electric-car-motor-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "how an electric car works", "grades": [7, 8], "terms": ["electric car", "kotseng de-kuryente", "sasakyan", "awto", "baterya", "battery", "motor", "kuryente", "walang gasolina", "no gasoline", "tahimik", "quiet", "walang usok", "no smoke", "nagcha-charge", "kinakarga", "gulong", "pinapaandar", "de-kuryente"], "fact": {"tl": "Ang electric car ay walang makinang sumusunog ng gasolina — sa halip, gumagamit ito ng malaking baterya na nagpapaandar sa isang electric motor para iikot ang mga gulong, kaya tahimik at walang usok.", "en": "An electric car has no engine that burns gasoline — instead it uses a big battery to run an electric motor that turns the wheels, so it is quiet and gives off no smoke.", "bis": "Ang electric car walay makina nga mosunog og gasolina — hinuon mogamit kini og dakong baterya nga mopadagan sa electric motor aron tuyokon ang mga ligid, mao nga hilom kini ug walay aso."}, "source": "encyclopedia-stable consensus; NRC PS3.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "screen-tiny-lights-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "how a phone or TV screen makes pictures", "grades": [6, 7], "terms": ["screen", "iskrin", "monitor", "cellphone", "telepono", "TV", "telebisyon", "computer", "kompyuter", "larawan", "picture", "pixel", "maliliit na ilaw", "tiny lights", "kulay", "color", "pula berde asul", "red green blue", "nagliliwanag", "dot", "puntos", "mata"], "fact": {"tl": "Ang screen ng telepono o telebisyon ay binubuo ng milyon-milyong napakaliliit na ilaw (pixel) na may kulay na pula, berde, at asul; magkakasama itong nagbubuo ng larawan na nakikita mo.", "en": "A phone or TV screen is made of millions of tiny lights called pixels in red, green, and blue; together they form the picture you see.", "bis": "Ang screen sa telepono o telebisyon hinimo sa minilyon ka gagmay kaayo nga suga (pixel) nga pula, berde, ug asul; magkahiusa kini aron maporma ang hulagway nga imong makita."}, "source": "encyclopedia-stable consensus; NRC PS4 (light and information)", "generator": "claude-workflow", "reviewed": false},
  {"id": "motor-electricity-to-motion-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "how an electric motor works", "grades": [7, 8], "terms": ["electric motor", "motor", "kuryente", "umiikot", "spins", "galaw", "motion", "magnet", "bumbilya", "fan", "bentilador", "blender", "makina", "de-kuryente", "nagpapaikot", "pumapaandar", "enerhiya", "elektrikal", "ginahimong galaw", "gulong"], "fact": {"tl": "Ang electric motor ay nagbabago ng kuryente tungo sa paggalaw: gumagamit ito ng magnet at kuryente para magpaikot ng isang baras, na siyang nagpapaandar ng bentilador, blender, o gulong.", "en": "An electric motor turns electricity into motion: it uses magnets and electric current to spin a rod, which then runs a fan, a blender, or a wheel.", "bis": "Ang electric motor mag-usab sa kuryente ngadto sa paglihok: mogamit kini og magnet ug kuryente aron tuyokon ang usa ka baras, nga maoy mopadagan sa bentilador, blender, o ligid."}, "source": "encyclopedia-stable consensus; NRC PS2.B (magnetism) and PS3.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "aircon-cools-like-fridge-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "how an air conditioner cools a room", "grades": [6, 7], "terms": ["aircon", "air conditioner", "airconditioner", "malamig na hangin", "cool air", "kwarto", "room", "init", "heat", "inilalabas", "ginahawa", "sa labas", "outside", "refrigerant", "compressor", "pareho ng ref", "nagpapalamig", "nagpabugnaw", "hangin", "palamig"], "fact": {"tl": "Gumagana ang aircon tulad ng refrigerator: kinukuha nito ang init sa loob ng kwarto at inilalabas ito sa hangin sa labas, kaya nananatiling malamig ang loob.", "en": "An air conditioner works like a refrigerator: it takes heat from inside the room and moves it out to the air outside, keeping the room cool.", "bis": "Ang aircon molihok sama sa refrigerator: kuhaon niini ang kainit sa sulod sa kwarto ug ipagawas kini ngadto sa hangin sa gawas, aron magpabilin nga bugnaw ang sulod."}, "source": "encyclopedia-stable consensus; NRC PS3.B (heat transfer)", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-renewable-vs-nonrenewable-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "renewable vs non-renewable energy", "grades": [5, 6, 7], "terms": ["renewable", "non-renewable", "nababago", "nare-renew", "muling magagamit", "hindi nauubos", "nauubos", "mapadayonon nga enerhiya", "dili mapulihan", "enerhiya", "kuryente", "energy source", "mauubos"], "fact": {"tl": "Ang renewable na pinagkukunan ng enerhiya tulad ng araw at hangin ay hindi nauubos, samantalang ang non-renewable tulad ng langis at karbon ay maubos kapag nagamit na.", "en": "Renewable energy sources like sunlight and wind never run out, while non-renewable ones like oil and coal are used up and cannot be quickly replaced.", "bis": "Ang mapadayonon nga tinubdan sa enerhiya sama sa adlaw ug hangin dili mahurot, samtang ang dili mapadayunon sama sa lana ug karbon mahurot kon magamit na."}, "source": "AAAS Benchmarks 8C/M10, 4B/H8", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-sun-ultimate-source-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "sun as main energy source", "grades": [4, 5, 6], "terms": ["araw", "adlaw", "sun", "sunlight", "sinag", "silaw", "pangunahing pinagkukunan", "ultimate source", "enerhiya", "energy", "init", "kainit"], "fact": {"tl": "Ang araw ang pangunahing pinagkukunan ng halos lahat ng enerhiyang ginagamit natin sa Mundo.", "en": "The sun is the main source of nearly all the energy we use on Earth.", "bis": "Ang adlaw mao ang nag-unang tinubdan sa hapit tanang enerhiya nga atong gigamit sa Kalibotan."}, "source": "AAAS Benchmarks 8C/E2, 8C/H8", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-solar-panels-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "solar power", "grades": [5, 6, 7], "terms": ["solar", "solar panel", "panel", "araw", "adlaw", "sinag ng araw", "silaw sa adlaw", "kuryente mula sa araw", "koryente gikan sa adlaw", "photovoltaic", "solar energy", "enerhiya sa adlaw"], "fact": {"tl": "Ang solar panel ay gumagawa ng kuryente sa pamamagitan ng pagsipsip ng liwanag ng araw at pagpapalit nito sa elektrisidad.", "en": "A solar panel makes electricity by absorbing sunlight and turning it directly into electric current.", "bis": "Ang solar panel naghimog koryente pinaagi sa pagsuyop sa kahayag sa adlaw ug pag-usab niini ngadto sa elektrisidad."}, "source": "AAAS Benchmarks 8C/E3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-wind-turbine-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "wind power", "grades": [5, 6, 7], "terms": ["hangin", "wind", "wind turbine", "turbine", "windmill", "molino", "ikot", "libot", "blades", "paypay", "kuryente mula sa hangin", "koryente gikan sa hangin", "enerhiya sa hangin"], "fact": {"tl": "Ang wind turbine ay umiikot kapag hinihipan ng hangin, at ang pag-ikot na ito ay gumagawa ng kuryente.", "en": "A wind turbine spins when the wind blows, and that spinning motion generates electricity.", "bis": "Ang wind turbine motuyok kon huypon sa hangin, ug kini nga pagtuyok maghimog koryente."}, "source": "AAAS Benchmarks 8C/E3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-hydroelectric-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "hydroelectric power", "grades": [6, 7, 8], "terms": ["hydro", "hydroelectric", "tubig", "water", "dam", "saplad", "pader ng tubig", "agos", "dagayday", "ilog", "suba", "kuryente mula sa tubig", "koryente gikan sa tubig", "enerhiya sa tubig", "pag-agos"], "fact": {"tl": "Sa hydroelectric power, ang lakas ng umaagos na tubig sa isang dam ang nagpapaikot ng turbine para makagawa ng kuryente.", "en": "In hydroelectric power, fast-flowing water from a dam spins a turbine to generate electricity.", "bis": "Sa hydroelectric power, ang kusog sa nagdagayday nga tubig gikan sa usa ka dam maoy mopatuyok sa turbine aron makahimog koryente."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-geothermal-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "geothermal power", "grades": [6, 7, 8], "terms": ["geothermal", "init ng lupa", "kainit sa yuta", "singaw", "alisngaw", "aso", "steam", "ilalim ng lupa", "ilalom sa yuta", "bulkan", "volcano", "kuryente mula sa init", "enerhiya sa init sa lupa"], "fact": {"tl": "Ang geothermal energy ay galing sa init sa ilalim ng lupa, na nagpapakulo ng tubig upang gumawa ng singaw na nagpapaikot ng turbine.", "en": "Geothermal energy comes from heat deep inside the Earth, which boils water into steam that spins a turbine.", "bis": "Ang geothermal energy gikan sa kainit sa ilalom sa yuta, nga magpabukal sa tubig ngadto sa alisngaw nga mopatuyok sa turbine."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-philippines-geothermal-leader-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "Philippine geothermal energy", "grades": [7, 8, 9], "terms": ["Pilipinas", "Philippines", "geothermal", "init ng lupa", "kainit sa yuta", "bulkan", "volcano", "pinakamalaki", "top producer", "Tiwi", "Makban", "Leyte", "enerhiya", "kuryente"], "fact": {"tl": "Ang Pilipinas ay isa sa pinakamalaking gumagawa ng geothermal energy sa buong mundo dahil sa dami ng mga bulkan nito.", "en": "The Philippines is one of the world's largest producers of geothermal energy because of its many volcanoes.", "bis": "Ang Pilipinas usa sa pinakadako nga naghimog geothermal energy sa tibuok kalibotan tungod sa daghan niini nga mga bulkan."}, "source": "ThinkGeoEnergy Top 10 Geothermal Countries 2024 (Philippines ranks 3rd worldwide)", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-fossil-fuels-from-plants-g6", "domain": "EARTH_SPACE", "topic": "how fossil fuels form", "grades": [6, 7, 8], "terms": ["fossil fuel", "fossil fuels", "panggatong na fosil", "langis", "lana", "oil", "karbon", "coal", "gas", "tanim noon", "tanom kaniadto", "milyon-milyong taon", "milyon ka tuig", "namatay na halaman", "patay nga tanom"], "fact": {"tl": "Ang mga fossil fuel tulad ng langis at karbon ay nabuo mula sa mga halaman at hayop na namatay milyon-milyong taon na ang nakalipas.", "en": "Fossil fuels like oil and coal formed from plants and animals that died millions of years ago.", "bis": "Ang fossil fuels sama sa lana ug karbon naporma gikan sa mga tanom ug hayop nga namatay milyon-milyon ka tuig na ang milabay."}, "source": "AAAS Benchmarks 8C/E2, 8C/H8", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-coal-g5", "domain": "EARTH_SPACE", "topic": "coal", "grades": [5, 6, 7], "terms": ["karbon", "coal", "itim na bato", "itom nga bato", "mineral", "sinusunog", "sunugon", "power plant", "gatong", "kahoyng-bato", "fossil fuel"], "fact": {"tl": "Ang karbon ay isang itim na bato na sinusunog sa mga power plant para gumawa ng init na nagpapatakbo ng kuryente.", "en": "Coal is a black rock that is burned in power plants to make the heat used to generate electricity.", "bis": "Ang karbon usa ka itom nga bato nga sunugon sa mga power plant aron maghimog kainit nga gamiton sa paghimog koryente."}, "source": "AAAS Benchmarks 8C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-petroleum-uses-g6", "domain": "MATTER", "topic": "petroleum and oil", "grades": [6, 7, 8], "terms": ["langis", "lana", "petrolyo", "petroleum", "oil", "gasolina", "krudo", "crude", "gasoline", "diesel", "plastik", "plastic", "sasakyan", "sakyanan", "fossil fuel"], "fact": {"tl": "Ang krudo o petrolyo ay pinoproseso para gumawa ng gasolina, diesel, at kahit plastik.", "en": "Crude oil, or petroleum, is processed to make gasoline, diesel, and even plastics.", "bis": "Ang crude oil o petrolyo giproseso aron maghimog gasolina, diesel, ug bisan plastik."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-natural-gas-g6", "domain": "MATTER", "topic": "natural gas", "grades": [6, 7, 8], "terms": ["natural gas", "gas", "metano", "methane", "nasusunog na gas", "masunog nga gas", "luto", "panghimo", "ilalim ng lupa", "ilalom sa yuta", "fossil fuel", "panggatong"], "fact": {"tl": "Ang natural gas ay isang fossil fuel na matatagpuan sa ilalim ng lupa at sinusunog para magluto at gumawa ng kuryente.", "en": "Natural gas is a fossil fuel found underground that is burned for cooking and to generate electricity.", "bis": "Ang natural gas usa ka fossil fuel nga makaplagan sa ilalom sa yuta nga sunugon aron magluto ug maghimog koryente."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-how-electricity-generated-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "how a generator makes electricity", "grades": [6, 7, 8], "terms": ["generator", "kuryente", "koryente", "electricity", "gumawa", "maghimo", "umiikot", "motuyok", "magnet", "kuwerdas", "wire", "pag-ikot", "spin", "turbine", "power plant"], "fact": {"tl": "Karamihan ng kuryente ay nagagawa kapag may umiikot na turbine na nagpapagalaw ng magnet sa loob ng generator.", "en": "Most electricity is made when a spinning turbine moves magnets inside a generator.", "bis": "Kadaghanan sa koryente mahimo kon adunay nagtuyok nga turbine nga magpalihok sa mga magnet sulod sa generator."}, "source": "AAAS Benchmarks 4E/M2, 4G/H5", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-power-plant-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "power plants", "grades": [5, 6, 7], "terms": ["power plant", "planta", "planta ng kuryente", "planta sa koryente", "power station", "gumagawa ng kuryente", "naghimog koryente", "poste", "linya", "grid", "kuryente", "koryente"], "fact": {"tl": "Ang power plant ay isang malaking pasilidad na gumagawa ng kuryente at ipinapadala ito sa mga bahay sa pamamagitan ng mga wire.", "en": "A power plant is a large facility that generates electricity and sends it to homes through wires.", "bis": "Ang power plant usa ka dako nga pasilidad nga maghimog koryente ug magpadala niini sa mga balay pinaagi sa mga alambre."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-fossil-fuels-pollution-g6", "domain": "EARTH_SPACE", "topic": "fossil fuels and pollution", "grades": [6, 7, 8], "terms": ["polusyon", "pollution", "carbon dioxide", "usok", "aso", "greenhouse gas", "init ng mundo", "pag-init sa kalibotan", "global warming", "climate change", "sinunog", "sunugon", "fossil fuel", "hangin"], "fact": {"tl": "Ang pagsunog ng mga fossil fuel ay naglalabas ng carbon dioxide na nagpapainit ng Mundo.", "en": "Burning fossil fuels releases carbon dioxide that warms the Earth.", "bis": "Ang pagsunog sa fossil fuels mopagawas ug carbon dioxide nga magpainit sa Kalibotan."}, "source": "AAAS Benchmarks 4B/H6", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-clean-energy-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "clean energy", "grades": [5, 6, 7], "terms": ["malinis na enerhiya", "limpyo nga enerhiya", "clean energy", "green energy", "walang usok", "walay aso", "hindi nakakasira", "dili makadaot", "kalikasan", "kinaiyahan", "renewable", "solar", "wind", "hangin"], "fact": {"tl": "Ang malinis na enerhiya tulad ng solar at wind ay hindi gumagawa ng nakakapinsalang usok kapag gumagawa ng kuryente.", "en": "Clean energy like solar and wind makes electricity without producing harmful smoke.", "bis": "Ang limpyo nga enerhiya sama sa solar ug wind maghimog koryente nga walay makadaot nga aso."}, "source": "AAAS Benchmarks 8C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-saving-turn-off-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "saving electricity at home", "grades": [3, 4, 5], "terms": ["pagtitipid", "pagtipig", "saving", "makatipid", "makadaginot", "patayin ang ilaw", "palonga ang suga", "turn off", "ilaw", "suga", "kuryente", "koryente", "bayad", "plug", "switch"], "fact": {"tl": "Ang pagpatay ng mga ilaw at gamit na hindi ginagamit ay nakakatipid ng kuryente sa bahay.", "en": "Turning off lights and appliances you are not using saves electricity at home.", "bis": "Ang pagpalong sa mga suga ug gamit nga wala gamita makadaginot ug koryente sa balay."}, "source": "AAAS Benchmarks 8C/M10; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-led-bulb-saving-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "energy-efficient bulbs", "grades": [4, 5, 6], "terms": ["LED", "LED bulb", "bombilya", "bulb", "ilaw", "suga", "matipid", "madaginot", "mas kaunting kuryente", "mas gamay nga koryente", "efficient", "incandescent", "luma"], "fact": {"tl": "Ang LED bulb ay nangangailangan ng mas kaunting kuryente kaysa lumang bombilya para magbigay ng parehong liwanag.", "en": "An LED bulb needs much less electricity than an old bulb to give off the same amount of light.", "bis": "Ang LED bulb nanginahanglan ug gamay ra nga koryente kay sa daan nga bombilya aron makahatag sa samang kahayag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-biomass-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "biomass energy", "grades": [6, 7, 8], "terms": ["biomass", "kahoy", "wood", "dayami", "uhot", "basura", "sinunog na halaman", "sunugon nga tanom", "panggatong", "gatong", "enerhiya sa tanom", "renewable", "dagami"], "fact": {"tl": "Ang biomass ay enerhiyang galing sa pagsunog ng mga bagay na buhat sa halaman tulad ng kahoy at dayami.", "en": "Biomass is energy made by burning materials that come from plants, such as wood and rice straw.", "bis": "Ang biomass usa ka enerhiya gikan sa pagsunog sa mga butang nga gikan sa tanom sama sa kahoy ug dagami."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-nuclear-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "nuclear energy", "grades": [8, 9, 10], "terms": ["nuclear", "nukleyar", "nuclear energy", "atomo", "uranium", "atomic", "paghahati", "pagbahin", "init", "kainit", "power plant", "walang usok", "walay aso", "singaw", "steam", "alisngaw"], "fact": {"tl": "Ang nuclear energy ay galing sa paghahati ng mga atomo, na naglalabas ng malaking init para gumawa ng singaw at kuryente.", "en": "Nuclear energy comes from splitting atoms, which releases huge heat used to make steam and electricity.", "bis": "Ang nuclear energy gikan sa pagbahin sa mga atomo, nga mopagawas ug dako nga kainit aron maghimog alisngaw ug koryente."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-battery-stores-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "how batteries store energy", "grades": [4, 5, 6], "terms": ["baterya", "battery", "imbak", "tipig", "stored", "nakaimbak", "chemical", "kemikal", "kuryente", "koryente", "cellphone", "flashlight", "nakaipon"], "fact": {"tl": "Ang baterya ay nag-iimbak ng enerhiya sa anyong kemikal at nilalabas ito bilang kuryente kapag ginagamit.", "en": "A battery stores energy in chemical form and releases it as electricity when you use it.", "bis": "Ang baterya magtipig ug enerhiya sa porma nga kemikal ug mopagawas niini isip koryente kon gamiton."}, "source": "AAAS Benchmarks 4E/M2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-tidal-wave-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "ocean tidal energy", "grades": [7, 8, 9], "terms": ["alon", "balod", "wave", "tidal", "taog", "hunas", "tide", "dagat", "ocean", "tubig-dagat", "enerhiya sa dagat", "kuryente mula sa alon", "renewable"], "fact": {"tl": "Ang enerhiyang galing sa pagtaas at pagbaba ng tubig-dagat o tidal energy ay maaari ring gawing kuryente.", "en": "The energy from the rising and falling of ocean tides, called tidal energy, can also be turned into electricity.", "bis": "Ang enerhiya gikan sa pagsaka ug pagkanaog sa tubig-dagat o tidal energy mahimo usab nga koryente."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-grid-distribution-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "the power grid", "grades": [6, 7, 8], "terms": ["grid", "power grid", "linya ng kuryente", "linya sa koryente", "poste", "tore", "transmission", "kable", "wire", "kuryente", "koryente", "ipinapamahagi", "apod-apod", "kabahayan"], "fact": {"tl": "Ang kuryente ay dumadaan sa mga linya at poste ng power grid bago marating ang mga bahay at gusali.", "en": "Electricity travels through the wires and towers of a power grid before reaching homes and buildings.", "bis": "Ang koryente moagi sa mga linya ug poste sa power grid una pa kini moabot sa mga balay ug bilding."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-philippines-mostly-coal-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "Philippine electricity sources", "grades": [8, 9, 10], "terms": ["Pilipinas", "Philippines", "kuryente", "koryente", "karbon", "coal", "fossil fuel", "pinagkukunan", "tinubdan", "renewable", "geothermal", "hydro", "halo", "sagol", "power mix"], "fact": {"tl": "Sa Pilipinas, malaking bahagi ng kuryente ay galing sa karbon, ngunit dumadami rin ang gamit ng geothermal at iba pang renewable.", "en": "In the Philippines, much of the electricity comes from coal, but the use of geothermal and other renewables is growing.", "bis": "Sa Pilipinas, dako nga bahin sa koryente gikan sa karbon, apan nagkadaghan na usab ang paggamit sa geothermal ug uban pang renewable."}, "source": "Philippines DOE 2024 power mix (coal ~62%); renewables growing", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-solar-needs-sun-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "limits of solar power", "grades": [4, 5, 6], "terms": ["solar", "solar panel", "gabi", "gabii", "ulap", "panganod", "walang araw", "walay adlaw", "hindi gumagana", "dili molihok", "limitasyon", "kakulangan", "araw", "adlaw", "kuryente"], "fact": {"tl": "Ang solar panel ay hindi gumagawa ng kuryente kapag gabi o makulimlim dahil kailangan nito ng liwanag ng araw.", "en": "A solar panel does not make electricity at night or when it is very cloudy because it needs sunlight.", "bis": "Ang solar panel dili makahimog koryente kon gabii o maalindahaw kay nagkinahanglan kini sa kahayag sa adlaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-windmill-bangui-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "Bangui wind farm Philippines", "grades": [6, 7, 8], "terms": ["Bangui", "windmill", "wind farm", "molino", "Ilocos", "Ilocos Norte", "hangin", "wind turbine", "Pilipinas", "Philippines", "baybayin", "baybay", "kuryente"], "fact": {"tl": "Ang Bangui Wind Farm sa Ilocos Norte ay may hanay ng malalaking windmill sa tabing-dagat na gumagawa ng kuryente mula sa hangin.", "en": "The Bangui Wind Farm in Ilocos Norte has a row of giant windmills by the sea that make electricity from wind.", "bis": "Ang Bangui Wind Farm sa Ilocos Norte adunay laray sa dagkong windmill sa daplin sa dagat nga maghimog koryente gikan sa hangin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-conserve-why-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "why we save energy", "grades": [5, 6, 7], "terms": ["pagtitipid", "pagtipig", "conserve", "saving", "bakit magtipid", "ngano magdaginot", "mauubos", "mahurot", "mahal", "bayad", "fossil fuel", "kalikasan", "kinaiyahan", "resource"], "fact": {"tl": "Nagtitipid tayo ng enerhiya dahil maraming pinagkukunan nito ay nauubos at ang pagsunog ng fossil fuel ay nakakasama sa kalikasan.", "en": "We save energy because many sources run out and burning fossil fuels harms the environment.", "bis": "Magdaginot ta ug enerhiya kay daghang tinubdan niini mahurot ug ang pagsunog sa fossil fuels makadaot sa kinaiyahan."}, "source": "AAAS Benchmarks 8C/M10, 4B/H6", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-fuel-stores-chemical-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "chemical energy in fuels", "grades": [6, 7, 8], "terms": ["panggatong", "gatong", "sugnod", "fuel", "kemikal na enerhiya", "kemikal nga enerhiya", "chemical energy", "nakaimbak", "natipig", "stored", "sinunog", "sunugon", "init", "kainit", "enerhiya"], "fact": {"tl": "Ang panggatong tulad ng gasolina at kahoy ay may nakaimbak na kemikal na enerhiya na nagiging init kapag sinunog.", "en": "Fuels like gasoline and wood hold stored chemical energy that turns into heat when burned.", "bis": "Ang sugnod sama sa gasolina ug kahoy adunay natipig nga kemikal nga enerhiya nga mahimong kainit kon sunugon."}, "source": "AAAS Benchmarks 4E/M2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-sun-powers-wind-hydro-g6", "domain": "EARTH_SPACE", "topic": "sun drives wind and water cycle energy", "grades": [6, 7, 8], "terms": ["araw", "adlaw", "sun", "hangin", "wind", "ulan", "tubig", "water cycle", "init", "kainit", "pinagmulan", "gigikanan", "enerhiya", "alisngaw", "singaw"], "fact": {"tl": "Kahit ang enerhiya ng hangin at tubig ay galing din sa araw, dahil ito ang nagpapakilos ng hangin at nagpapasingaw ng tubig.", "en": "Even wind and water energy come from the sun, because the sun drives the wind and lifts water into the sky.", "bis": "Bisan ang enerhiya sa hangin ug tubig gikan usab sa adlaw, kay ang adlaw maoy mopalihok sa hangin ug mopaalisngaw sa tubig."}, "source": "AAAS Benchmarks 8C/E2, 4B/H2", "generator": "claude-workflow", "reviewed": false},
  {"id": "newton-gravity-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "Isaac Newton and gravity", "grades": [5, 6, 7], "terms": ["Isaac Newton", "gravity", "gravidad", "gravitasyon", "grabidad", "bigat", "force", "puwersa", "puersa", "nahuhulog", "nahulog", "mahulog", "mansanas", "apple", "mansanas nahulog", "siyentista", "scientist", "syentista"], "fact": {"tl": "Si Isaac Newton ay isang siyentistang Ingles na nagpaliwanag na ang gravity o gravitasyon ang puwersang humihila sa mga bagay pababa sa lupa.", "en": "Isaac Newton was an English scientist who explained that gravity is the force that pulls objects down toward the ground.", "bis": "Si Isaac Newton usa ka Ingles nga siyentista nga nagpasabot nga ang gravity mao ang puwersa nga nagbira sa mga butang paubos sa yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "newton-laws-motion-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "Newton's laws of motion", "grades": [7, 8, 9], "terms": ["Newton", "laws of motion", "batas ng galaw", "balaod sa paglihok", "tatlong batas", "three laws", "puwersa", "force", "kilos", "galaw", "paglihok", "lihok", "inertia", "siyentista", "scientist"], "fact": {"tl": "Si Isaac Newton ang gumawa ng tatlong batas ng galaw na naglalarawan kung paano gumagalaw ang mga bagay kapag may puwersang humihila o tumutulak sa kanila.", "en": "Isaac Newton created the three laws of motion that describe how objects move when forces push or pull them.", "bis": "Si Isaac Newton naghimo sa tulo ka balaod sa paglihok nga nagsaysay kung giunsa paglihok sa mga butang kung adunay puwersa nga magtukmod o magbira kanila."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "einstein-relativity-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "Albert Einstein and relativity", "grades": [7, 8, 9, 10], "terms": ["Albert Einstein", "Einstein", "relativity", "relatibidad", "oras", "panahon", "time", "space", "kalawakan", "liwanag", "light", "kahibalo", "henyo", "genius", "siyentista", "scientist", "pisika", "physics"], "fact": {"tl": "Si Albert Einstein ay isang siyentista na nagturo na ang oras at espasyo ay magkadugtong at maaaring magbago depende sa bilis ng paggalaw.", "en": "Albert Einstein was a scientist who showed that time and space are connected and can change depending on how fast something moves.", "bis": "Si Albert Einstein usa ka siyentista nga nagtudlo nga ang oras ug espasyo nagdugtong ug mahimong mausab depende sa kakusog sa paglihok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "einstein-emc2-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "Einstein E=mc2 energy and mass", "grades": [8, 9, 10], "terms": ["Einstein", "E=mc2", "enerhiya", "energy", "kusog", "masa", "mass", "ekwasyon", "equation", "liwanag", "light", "bilis ng liwanag", "pisika", "physics", "sikat na pormula"], "fact": {"tl": "Ipinakita ni Einstein sa kanyang pormulang E=mc2 na ang masa ay maaaring maging napakalaking enerhiya.", "en": "Einstein showed with his formula E=mc2 that mass can be turned into a huge amount of energy.", "bis": "Gipakita ni Einstein sa iyang pormula nga E=mc2 nga ang masa mahimong dako kaayo nga enerhiya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "darwin-evolution-g8", "domain": "LIVING_THINGS", "topic": "Charles Darwin and evolution", "grades": [8, 9, 10], "terms": ["Charles Darwin", "Darwin", "evolution", "ebolusyon", "pagbabago", "nagbabago", "living things", "mga hayop", "species", "uri", "natural selection", "natural na pagpili", "siyentista", "scientist", "naturalista"], "fact": {"tl": "Si Charles Darwin ay isang siyentista na nagpaliwanag ng ebolusyon, ang dahan-dahang pagbabago ng mga uri ng buhay sa paglipas ng napakaraming taon.", "en": "Charles Darwin was a scientist who explained evolution, the slow change of living things over very long periods of time.", "bis": "Si Charles Darwin usa ka siyentista nga nagpasabot sa ebolusyon, ang hinay-hinay nga pagbag-o sa mga buhing butang sulod sa daghan kaayo nga katuigan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "darwin-galapagos-finches-g8", "domain": "LIVING_THINGS", "topic": "Darwin Galapagos finches", "grades": [7, 8, 9], "terms": ["Darwin", "Galapagos", "finches", "ibon", "mga ibon", "langgam", "tuka", "beak", "sungkad", "isla", "island", "adaptation", "pag-aangkop", "pagkaon", "food", "biyahe", "HMS Beagle"], "fact": {"tl": "Napansin ni Darwin sa mga isla ng Galapagos na ang mga ibong finch ay may iba't ibang hugis ng tuka ayon sa pagkaing kinakain nila.", "en": "On the Galapagos Islands, Darwin noticed that finch birds had different beak shapes depending on the food they ate.", "bis": "Sa mga isla sa Galapagos, namatikdan ni Darwin nga ang mga langgam nga finch adunay lain-laing porma sa sungkad depende sa ilang gikaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "marie-curie-radioactivity-g7", "domain": "MATTER", "topic": "Marie Curie and radioactivity", "grades": [6, 7, 8], "terms": ["Marie Curie", "Curie", "radioactivity", "radyaktibidad", "radiation", "babaeng siyentista", "woman scientist", "siyentista", "scientist", "Nobel Prize", "gantimpala", "mineral", "kemika", "chemistry"], "fact": {"tl": "Si Marie Curie ay isang siyentista na nag-aral ng radioactivity o radyaktibidad, ang lihim na enerhiyang inilalabas ng ilang mineral.", "en": "Marie Curie was a scientist who studied radioactivity, the hidden energy given off by certain minerals.", "bis": "Si Marie Curie usa ka siyentista nga nagtuon sa radioactivity, ang tinago nga enerhiya nga gibuga sa pipila ka mineral."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "marie-curie-elements-g8", "domain": "MATTER", "topic": "Marie Curie discovered polonium and radium", "grades": [8, 9, 10], "terms": ["Marie Curie", "polonium", "radium", "elemento", "element", "natuklasan", "discovered", "nadiskubre", "dalawang Nobel", "two Nobel Prizes", "babae", "woman", "kemika", "chemistry", "pisika"], "fact": {"tl": "Natuklasan ni Marie Curie ang dalawang bagong elemento na polonium at radium, at siya ang unang babaeng nanalo ng Nobel Prize.", "en": "Marie Curie discovered two new elements called polonium and radium, and she was the first woman to win a Nobel Prize.", "bis": "Nadiskobrehan ni Marie Curie ang duha ka bag-ong elemento nga polonium ug radium, ug siya ang unang babaye nga nidaog og Nobel Prize."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "galileo-telescope-g5", "domain": "EARTH_SPACE", "topic": "Galileo and the telescope", "grades": [5, 6, 7], "terms": ["Galileo", "Galileo Galilei", "telescope", "teleskopyo", "bituin", "stars", "planeta", "planet", "langit", "sky", "Jupiter", "buwan", "moon", "siyentista", "scientist", "astronomo", "astronomer"], "fact": {"tl": "Si Galileo Galilei ay isa sa mga unang siyentista na gumamit ng teleskopyo upang pag-aralan ang mga planeta at bituin sa langit.", "en": "Galileo Galilei was one of the first scientists to use a telescope to study the planets and stars in the sky.", "bis": "Si Galileo Galilei usa sa unang mga siyentista nga migamit og teleskopyo aron tun-an ang mga planeta ug bituon sa langit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "galileo-jupiter-moons-g6", "domain": "EARTH_SPACE", "topic": "Galileo discovered moons of Jupiter", "grades": [6, 7, 8], "terms": ["Galileo", "Jupiter", "moons", "buwan", "mga buwan", "bulan", "natuklasan", "discovered", "umiikot", "orbit", "planeta", "teleskopyo", "telescope", "apat na buwan", "four moons"], "fact": {"tl": "Natuklasan ni Galileo ang apat na malalaking buwan na umiikot sa planetang Jupiter gamit ang kanyang teleskopyo.", "en": "Galileo discovered four large moons orbiting the planet Jupiter using his telescope.", "bis": "Nadiskobrehan ni Galileo ang upat ka dagkong bulan nga nagtuyok sa planeta nga Jupiter gamit ang iyang teleskopyo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "galileo-falling-objects-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "Galileo falling objects same speed", "grades": [7, 8, 9], "terms": ["Galileo", "falling", "nahuhulog", "nahulog", "bagay", "objects", "bigat", "weight", "mabigat", "magaan", "heavy", "light", "same speed", "sabay", "dungan", "gravity", "eksperimento", "experiment"], "fact": {"tl": "Ipinakita ni Galileo na ang mabigat at magaang bagay ay nahuhulog nang magkasabay kung walang hangin na hahadlang sa kanila.", "en": "Galileo showed that heavy and light objects fall at the same speed when no air slows them down.", "bis": "Gipakita ni Galileo nga ang bug-at ug gaan nga mga butang mahulog nga dungan kung walay hangin nga moabag kanila."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "edison-lightbulb-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "Thomas Edison and the light bulb", "grades": [4, 5, 6], "terms": ["Thomas Edison", "Edison", "light bulb", "bombilya", "ilaw", "liwanag", "light", "kuryente", "electricity", "koryente", "imbentor", "inventor", "imbento", "invention", "natuklasan"], "fact": {"tl": "Si Thomas Edison ay isang imbentor na nagpaunlad ng bombilya na nagbibigay ng ilaw gamit ang kuryente.", "en": "Thomas Edison was an inventor who developed a light bulb that gives off light using electricity.", "bis": "Si Thomas Edison usa ka imbentor nga nagpalambo sa bombilya nga nagahatag og kahayag gamit ang kuryente."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "edison-inventions-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "Edison many inventions and persistence", "grades": [5, 6, 7], "terms": ["Edison", "inventions", "imbensyon", "imbento", "invention", "phonograph", "tunog", "sound", "maraming", "many", "sumubok", "tried", "pagsubok", "persistence", "laboratoryo", "imbentor", "inventor"], "fact": {"tl": "Si Thomas Edison ay gumawa ng napakaraming imbensyon at sumubok nang paulit-ulit hanggang gumana ang kanyang mga ideya.", "en": "Thomas Edison created very many inventions and tried again and again until his ideas worked.", "bis": "Si Thomas Edison naghimo og daghan kaayo nga mga imbensyon ug nagsige og sulay hangtod nga molihok ang iyang mga ideya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "galvez-tan-virgin-coconut-g6", "domain": "LIVING_THINGS", "topic": "Filipino scientists inventions and discoveries overview", "grades": [6, 7, 8], "terms": ["Filipino scientist", "Pilipinong siyentista", "Pinoy scientist", "syentistang Pilipino", "siyentista", "scientist", "imbentor", "Pilipinas", "Philippines", "natuklasan", "discovery", "tulong", "pananaliksik", "research"], "fact": {"tl": "Maraming Pilipinong siyentista ang gumawa ng mahahalagang imbensyon at tuklas na nakatutulong sa kalusugan, pagkain, at agham.", "en": "Many Filipino scientists have made important inventions and discoveries that help with health, food, and science.", "bis": "Daghang Pilipinong siyentista ang naghimo og importante nga mga imbensyon ug diskobre nga nakatabang sa panglawas, pagkaon, ug siyensya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fe-del-mundo-incubator-g6", "domain": "LIVING_THINGS", "topic": "Fe del Mundo Filipino pediatrician inventor", "grades": [6, 7, 8], "terms": ["Fe del Mundo", "Filipino doctor", "Pilipinong doktor", "pediatrician", "sanggol", "baby", "incubator", "ginhawa", "kalusugan", "health", "babaeng siyentista", "woman scientist", "doktora", "National Scientist"], "fact": {"tl": "Si Fe del Mundo ay isang Pilipinong doktora na nag-imbento ng murang incubator para mapanatiling mainit at ligtas ang mga sanggol.", "en": "Fe del Mundo was a Filipino doctor who invented a low-cost incubator to keep babies warm and safe.", "bis": "Si Fe del Mundo usa ka Pilipinong doktora nga nag-imbento og barato nga incubator aron mainit ug luwas ang mga masuso."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "angel-alcala-marine-g7", "domain": "LIVING_THINGS", "topic": "Angel Alcala marine biologist", "grades": [7, 8, 9], "terms": ["Angel Alcala", "marine biologist", "dagat", "sea", "ocean", "isda", "fish", "coral", "bahura", "reef", "artificial reef", "conservation", "pangangalaga", "siyentista", "scientist", "Filipino", "Pilipino"], "fact": {"tl": "Si Angel Alcala ay isang Pilipinong siyentista na nag-aral ng buhay sa dagat at tumulong gumawa ng mga artipisyal na bahura para dumami ang isda.", "en": "Angel Alcala is a Filipino scientist who studied sea life and helped build artificial reefs so fish could multiply.", "bis": "Si Angel Alcala usa ka Pilipinong siyentista nga nagtuon sa kinabuhi sa dagat ug nitabang paghimo og artipisyal nga mga bahura aron modaghan ang isda."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ramon-barba-mango-g6", "domain": "LIVING_THINGS", "topic": "Ramon Barba mango flowering", "grades": [6, 7, 8], "terms": ["Ramon Barba", "mango", "mangga", "bulaklak", "flower", "namumulaklak", "induce flowering", "prutas", "fruit", "horticulture", "agrikultura", "Filipino scientist", "Pilipinong siyentista", "tanim", "plant"], "fact": {"tl": "Natuklasan ni Ramon Barba ang paraan para mas madaling mamulaklak at mamunga ang mga punong mangga sa buong taon.", "en": "Ramon Barba discovered a way to make mango trees flower and bear fruit more easily throughout the year.", "bis": "Nadiskobrehan ni Ramon Barba ang paagi aron mas dali nga mamulak ug mamunga ang mga kahoy nga mangga sa tibuok tuig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "eduardo-quisumbing-plants-g6", "domain": "LIVING_THINGS", "topic": "Eduardo Quisumbing medicinal plants", "grades": [6, 7, 8], "terms": ["Eduardo Quisumbing", "plants", "halaman", "tanom", "medicinal plants", "gamot", "medisina", "herbal", "botanist", "botaniko", "Filipino scientist", "Pilipinong siyentista", "pag-aaral ng halaman"], "fact": {"tl": "Si Eduardo Quisumbing ay isang Pilipinong siyentista na nag-aral at nagtala ng libo-libong halamang gamot sa Pilipinas.", "en": "Eduardo Quisumbing was a Filipino scientist who studied and recorded thousands of medicinal plants in the Philippines.", "bis": "Si Eduardo Quisumbing usa ka Pilipinong siyentista nga nagtuon ug nagsulat sa liboan ka tanom nga tambal sa Pilipinas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gregorio-zara-videophone-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "Gregorio Zara videophone inventor", "grades": [7, 8, 9], "terms": ["Gregorio Zara", "videophone", "telepono", "phone", "tawag", "video call", "imbentor", "inventor", "imbento", "invention", "Filipino inventor", "Pilipinong imbentor", "enhinyero", "engineer", "teknolohiya"], "fact": {"tl": "Si Gregorio Zara ay isang Pilipinong imbentor na lumikha ng videophone, isang teleponong may larawan ng nag-uusap.", "en": "Gregorio Zara was a Filipino inventor who created the videophone, a telephone that shows a picture of the person talking.", "bis": "Si Gregorio Zara usa ka Pilipinong imbentor nga naghimo sa videophone, usa ka telepono nga nagpakita sa hulagway sa nagsultihay."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "abelardo-aguilar-erythromycin-g8", "domain": "LIVING_THINGS", "topic": "Abelardo Aguilar erythromycin antibiotic", "grades": [8, 9, 10], "terms": ["Abelardo Aguilar", "erythromycin", "antibiotic", "antibyotiko", "gamot", "medisina", "medicine", "bakterya", "bacteria", "sakit", "disease", "Filipino scientist", "Pilipinong siyentista", "lupa", "soil"], "fact": {"tl": "Si Abelardo Aguilar ay isang Pilipino na nakatuklas ng mikrobyo sa lupa na ginamit upang gumawa ng antibyotikong erythromycin.", "en": "Abelardo Aguilar was a Filipino who discovered a soil microbe used to make the antibiotic erythromycin.", "bis": "Si Abelardo Aguilar usa ka Pilipino nga nakadiskobre og mikrobyo sa yuta nga gigamit aron himuon ang antibiotic nga erythromycin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "benjamin-franklin-electricity-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "Benjamin Franklin electricity and lightning", "grades": [6, 7, 8], "terms": ["Benjamin Franklin", "Franklin", "electricity", "kuryente", "koryente", "kidlat", "lightning", "kite", "saranggola", "kalawakit", "kulog", "scientist", "siyentista", "lightning rod", "kawad"], "fact": {"tl": "Ipinakita ni Benjamin Franklin sa pamamagitan ng eksperimento na ang kidlat ay isang uri ng kuryente.", "en": "Benjamin Franklin showed through an experiment that lightning is a form of electricity.", "bis": "Gipakita ni Benjamin Franklin pinaagi sa eksperimento nga ang kilat usa ka matang sa kuryente."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "alexander-graham-bell-telephone-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "Alexander Graham Bell telephone", "grades": [5, 6, 7], "terms": ["Alexander Graham Bell", "Bell", "telephone", "telepono", "tawag", "call", "tunog", "sound", "boses", "voice", "imbentor", "inventor", "imbento", "invention", "komunikasyon", "usapan"], "fact": {"tl": "Si Alexander Graham Bell ang nag-imbento ng telepono na nagpapadala ng boses sa malayong lugar sa pamamagitan ng kawad.", "en": "Alexander Graham Bell invented the telephone, which sends a person's voice to a faraway place through a wire.", "bis": "Si Alexander Graham Bell ang nag-imbento sa telepono nga nagpadala sa tingog sa layo nga dapit pinaagi sa alambre."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "louis-pasteur-germs-g7", "domain": "LIVING_THINGS", "topic": "Louis Pasteur germs and vaccines", "grades": [7, 8, 9], "terms": ["Louis Pasteur", "Pasteur", "germs", "mikrobyo", "bakterya", "bacteria", "germ theory", "sakit", "disease", "vaccine", "bakuna", "pasteurization", "gatas", "milk", "siyentista", "scientist"], "fact": {"tl": "Ipinakita ni Louis Pasteur na ang maliliit na mikrobyo ang sanhi ng maraming sakit, at gumawa siya ng mga unang bakuna.", "en": "Louis Pasteur showed that tiny germs cause many diseases, and he made some of the first vaccines.", "bis": "Gipakita ni Louis Pasteur nga ang gagmay nga mga mikrobyo maoy hinungdan sa daghang sakit, ug naghimo siya og pipila sa unang mga bakuna."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "newton-prism-light-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "Newton splitting white light with a prism", "grades": [6, 7, 8], "terms": ["Newton", "prism", "prisma", "liwanag", "light", "puti", "white light", "kulay", "colors", "bahaghari", "rainbow", "spectrum", "pitong kulay", "seven colors", "liwanag na puti"], "fact": {"tl": "Ipinakita ni Isaac Newton na ang puting liwanag ay binubuo ng pitong kulay kapag ito ay dumaan sa isang prisma.", "en": "Isaac Newton showed that white light is made of seven colors when it passes through a prism.", "bis": "Gipakita ni Isaac Newton nga ang puti nga kahayag gilangkoban sa pito ka kolor kung kini moagi sa usa ka prisma."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "einstein-curiosity-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "Einstein curiosity and imagination", "grades": [4, 5, 6], "terms": ["Einstein", "curiosity", "pagkamausisa", "imagination", "imahinasyon", "tanong", "questions", "nagtatanong", "henyo", "genius", "matalino", "smart", "siyentista", "scientist", "pisika", "physics"], "fact": {"tl": "Si Albert Einstein ay kilala sa kanyang pagkamausisa at imahinasyon, na nagpapaalala na ang pagtatanong ay mahalaga sa agham.", "en": "Albert Einstein was famous for his curiosity and imagination, reminding us that asking questions is important in science.", "bis": "Si Albert Einstein bantog sa iyang pagkamausisaon ug imahinasyon, nga nagpahinumdom nga ang pagpangutana importante sa siyensya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "darwin-tree-of-life-g9", "domain": "LIVING_THINGS", "topic": "Darwin common ancestor shared life", "grades": [9, 10], "terms": ["Darwin", "common ancestor", "ninuno", "kanunong", "pinagmulan", "related", "magkakaugnay", "tree of life", "puno ng buhay", "species", "uri", "evolution", "ebolusyon", "living things", "buhay"], "fact": {"tl": "Iminungkahi ni Darwin na ang lahat ng buhay sa mundo ay magkakaugnay at nagmula sa parehong sinaunang ninuno.", "en": "Darwin proposed that all living things on Earth are related and came from the same ancient ancestor.", "bis": "Gisugyot ni Darwin nga ang tanang buhi nga butang sa kalibotan magkalambigit ug naggikan sa samang karaang katigulangan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "galileo-earth-moves-g8", "domain": "EARTH_SPACE", "topic": "Galileo Earth moves around the Sun", "grades": [8, 9, 10], "terms": ["Galileo", "Earth moves", "umiikot", "mundo", "Earth", "araw", "Sun", "planeta", "planet", "heliocentric", "umiikot sa araw", "orbit", "Copernicus", "astronomo", "siyentista"], "fact": {"tl": "Sinuportahan ni Galileo ang ideya na ang Mundo at iba pang planeta ay umiikot sa Araw, hindi ang Araw sa Mundo.", "en": "Galileo supported the idea that the Earth and other planets move around the Sun, not the Sun around the Earth.", "bis": "Gisuportahan ni Galileo ang ideya nga ang Kalibotan ug ubang planeta nagtuyok sa Adlaw, dili ang Adlaw sa Kalibotan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "newton-reflecting-telescope-g7", "domain": "EARTH_SPACE", "topic": "Newton invented reflecting telescope", "grades": [7, 8, 9], "terms": ["Newton", "reflecting telescope", "teleskopyo", "telescope", "salamin", "mirror", "liwanag", "light", "bituin", "stars", "imbento", "invention", "astronomo", "instrument", "Isaac Newton"], "fact": {"tl": "Si Isaac Newton ang gumawa ng teleskopyong gumagamit ng salamin para makita nang mas malinaw ang malalayong bituin.", "en": "Isaac Newton built a telescope that uses a mirror to see distant stars more clearly.", "bis": "Si Isaac Newton naghimo og teleskopyo nga naggamit og salamin aron mas klaro nga makita ang layong mga bituon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "caesar-saloma-physics-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "Filipino physicists optics and light research", "grades": [8, 9, 10], "terms": ["Caesar Saloma", "Filipino physicist", "Pilipinong pisisista", "light", "liwanag", "laser", "optics", "optika", "pananaliksik", "research", "pisika", "physics", "siyentista", "scientist", "Pilipino"], "fact": {"tl": "May mga Pilipinong pisisista tulad ni Caesar Saloma na nag-aaral ng liwanag at laser para sa mga makabagong teknolohiya.", "en": "There are Filipino physicists like Caesar Saloma who study light and lasers for modern technology.", "bis": "Adunay mga Pilipinong pisisista sama ni Caesar Saloma nga nagtuon sa kahayag ug laser para sa modernong teknolohiya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wheel-invention-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "the invention of the wheel", "grades": [3, 4, 5], "terms": ["gulong", "ligid", "wheel", "imbento", "imbensiyon", "invention", "naimbento", "giimbento", "noong unang panahon", "kanhing panahon", "Mesopotamia", "umiikot", "nagtuyok", "kareton", "umiinog", "matagal na", "dugay na"], "fact": {"tl": "Ang gulong ay isa sa pinakamatandang imbensiyon ng tao, naimbento mga 5,500 taon na ang nakalipas sa Mesopotamia, at ginamit muna sa paggawa ng palayok bago ginamit sa mga kareton.", "en": "The wheel is one of the oldest human inventions, made about 5,500 years ago in Mesopotamia, and was first used for shaping pottery before it was used on carts.", "bis": "Ang ligid usa sa pinakakaraang imbensiyon sa tawo, gibuhat mga 5,500 ka tuig na ang milabay sa Mesopotamia, ug una gigamit sa paghimo og kolon una pa kini gamita sa mga karetilya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wheel-axle-why-useful-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "why the wheel changed travel and work", "grades": [4, 5, 6], "terms": ["gulong", "ligid", "wheel", "ehe", "axle", "mabigat", "bug-at", "pagdadala", "pagdala", "transportasyon", "kareton", "sasakyan", "sakyanan", "mas madali", "mas sayon", "nakabawas ng puwersa", "rolling", "gumugulong", "moligid"], "fact": {"tl": "Binago ng gulong ang buhay dahil ginawa nitong mas madali ang pagdala ng mabibigat na bagay sa malalayong lugar — sa halip na kaladkarin, igugulong na lang ito sa ehe, kaya umunlad ang transportasyon at kalakalan.", "en": "The wheel changed life because it made carrying heavy loads over long distances much easier — instead of dragging things, you could roll them on an axle, which helped travel and trade grow.", "bis": "Giusab sa ligid ang kinabuhi kay gihimo niini nga mas sayon ang pagdala sa bug-at nga mga butang sa layong dapit — imbis guyoron, maligid na lang kini sa ehe, mao nga miuswag ang transportasyon ug pamatigayon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "light-bulb-edison-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "the electric light bulb", "grades": [4, 5, 6], "terms": ["bombilya", "ilaw", "bombilya elektrik", "light bulb", "Thomas Edison", "Edison", "imbento", "naimbento", "giimbento", "kuryente", "koryente", "elektrisidad", "1879", "nagliliwanag", "nagdan-ag", "gabi", "kahayag", "filament"], "fact": {"tl": "Noong 1879, gumawa si Thomas Edison ng isang praktikal na bombilyang de-kuryente na tumatagal nang matagal, kaya may maaasahang ilaw na ang mga tao kahit gabi nang hindi gumagamit ng kandila o gas.", "en": "In 1879, Thomas Edison made a practical electric light bulb that lasted a long time, so people had reliable light at night without using candles or gas.", "bis": "Niadtong 1879, naghimo si Thomas Edison og praktikal nga bombilya nga elektrik nga dugay molungtad, busa adunay kasaligan nga suga ang mga tawo bisan gabii nga dili na mogamit og kandila o gas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "light-bulb-changed-life-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "how the light bulb changed daily life", "grades": [4, 5, 6], "terms": ["bombilya", "ilaw", "light bulb", "gabi", "trabaho", "pag-aaral", "pagtuon", "binago ang buhay", "giusab ang kinabuhi", "ligtas", "luwas", "kandila", "apoy", "kahayag", "kadan-ag", "mas mahabang oras", "kuryente"], "fact": {"tl": "Binago ng bombilya ang buhay dahil nakapagtrabaho, nakapag-aral, at nakapaglaro na ang mga tao kahit gabi, at mas ligtas ito kaysa sa apoy ng kandila o gas-lamp.", "en": "The light bulb changed life because people could now work, study, and play even after dark, and it was safer than the flame of a candle or gas lamp.", "bis": "Giusab sa bombilya ang kinabuhi kay nakatrabaho, nakatuon, ug nakaduwa na ang mga tawo bisan gabii, ug mas luwas kini kaysa sa kalayo sa kandila o gas-lamp."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "telephone-bell-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "the invention of the telephone", "grades": [4, 5, 6], "terms": ["telepono", "telupono", "telephone", "Alexander Graham Bell", "Bell", "imbento", "naimbento", "giimbento", "1876", "boses", "tingog", "tinig", "malayo", "layo", "usapan", "pakikipag-usap", "pagtawag", "pagkawag"], "fact": {"tl": "Noong 1876, naimbento ni Alexander Graham Bell ang telepono, isang makina na nagbabago ng boses sa senyales na dumadaan sa kawad upang makausap ng tao ang iba kahit malayo.", "en": "In 1876, Alexander Graham Bell invented the telephone, a machine that turns a voice into a signal sent through a wire so a person can talk to others far away.", "bis": "Niadtong 1876, giimbento ni Alexander Graham Bell ang telepono, usa ka makina nga mag-usab sa tingog ngadto sa signal nga moagi sa alambre aron makaistorya ang tawo sa uban bisan layo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "telephone-changed-communication-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "how the telephone changed communication", "grades": [5, 6, 7], "terms": ["telepono", "telephone", "komunikasyon", "pakikipag-ugnayan", "sulat", "liham", "balita", "balita kaagad", "malayo", "layo", "boses", "tingog", "binago", "giusab", "cellphone", "selpon", "mabilis", "paspas"], "fact": {"tl": "Binago ng telepono ang komunikasyon dahil agad nang nakakausap ng tao ang kapamilya o kaibigan sa malayo gamit ang boses, na dati ay aabutin pa ng araw o linggo sa sulat.", "en": "The telephone changed communication because people could instantly speak with family or friends far away using their voice, which once took days or weeks by letter.", "bis": "Giusab sa telepono ang komunikasyon kay diha-diha na makaistorya ang tawo sa pamilya o higala nga layo gamit ang tingog, nga kaniadto mag-abot pa og adlaw o semana pinaagi sa sulat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "airplane-wright-brothers-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "the first airplane flight", "grades": [4, 5, 6], "terms": ["eroplano", "ayroplano", "airplane", "Wright brothers", "magkapatid na Wright", "magsoong Wright", "Orville", "Wilbur", "1903", "unang lumipad", "unang nilupad", "lumipad", "molupad", "makinang lumilipad", "motorisadong eroplano", "imbento", "naimbento"], "fact": {"tl": "Noong 1903, ang magkapatid na Orville at Wilbur Wright ang unang nakalipad ng eroplanong de-makina, na tumagal lang ng mga 12 segundo sa unang paglipad nito.", "en": "In 1903, brothers Orville and Wilbur Wright made the first flight in a powered airplane, which lasted only about 12 seconds on its first flight.", "bis": "Niadtong 1903, ang managsoon nga si Orville ug Wilbur Wright ang unang nakalupad og eroplano nga adunay makina, nga milungtad lang og mga 12 segundo sa una niini nga paglupad."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "airplane-changed-travel-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "how the airplane changed travel", "grades": [5, 6, 7], "terms": ["eroplano", "ayroplano", "airplane", "paglalakbay", "panaw", "pagbiyahe", "malayong bansa", "layong nasod", "mabilis", "paspas", "oras", "buwan", "biyahe", "barko", "sakayan", "dagat", "binago", "giusab", "kontinente"], "fact": {"tl": "Binago ng eroplano ang paglalakbay dahil ang biyaheng dating tumatagal ng mga buwan sa barko ay nagagawa na ngayon sa ilang oras lang, kaya mas madaling makarating sa malalayong bansa.", "en": "The airplane changed travel because a trip that once took months by ship can now be done in just hours, making it much easier to reach faraway countries.", "bis": "Giusab sa eroplano ang pagpanaw kay ang biyahe nga kaniadto mag-abot og mga bulan pinaagi sa barko mahimo na karon sa pipila lang ka oras, mao nga mas sayon makaabot sa layong mga nasod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "computer-what-is-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "what a computer is", "grades": [4, 5, 6], "terms": ["kompyuter", "computer", "makina", "makinang elektroniko", "elektroniko", "impormasyon", "datos", "data", "programa", "program", "sumusunod sa utos", "mosunod sa mando", "mabilis", "paspas", "nagkukuwenta", "mag-ihap", "naglilitaw"], "fact": {"tl": "Ang kompyuter ay isang makinang elektroniko na sumusunod sa mga utos na tinatawag na programa upang mag-imbak, mag-ayos, at magproseso ng impormasyon nang napakabilis.", "en": "A computer is an electronic machine that follows instructions called programs to store, organize, and process information very quickly.", "bis": "Ang kompyuter usa ka elektronikong makina nga mosunod sa mga mando nga gitawag og programa aron magtipig, mag-ayos, ug magproseso og impormasyon nga paspas kaayo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "computer-shrank-over-time-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "how computers got smaller and faster", "grades": [5, 6, 7], "terms": ["kompyuter", "computer", "dati", "kaniadto", "kasing-laki ng kuwarto", "kadako sa kwarto", "malaki", "dako", "maliit", "gamay", "cellphone", "selpon", "transistor", "chip", "mas mabilis", "mas paspas", "umunlad", "miuswag", "teknolohiya"], "fact": {"tl": "Ang unang mga kompyuter ay kasing-laki ng buong kuwarto, ngunit dahil sa pagpapaliit ng mga bahagi nito tulad ng transistor at chip, kasyang-kasya na ngayon ang isang malakas na kompyuter sa loob ng cellphone.", "en": "The first computers were as big as a whole room, but as their parts like the transistor and chip became smaller, a powerful computer now fits inside a cellphone.", "bis": "Ang unang mga kompyuter sama kadako sa tibuok kwarto, apan tungod sa pagpagamay sa mga bahin niini sama sa transistor ug chip, mohaom na karon ang usa ka kusgan nga kompyuter sulod sa cellphone."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "internet-what-is-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "what the internet is", "grades": [5, 6, 7], "terms": ["internet", "network", "koneksiyon", "koneksyon", "magkakaugnay", "nagkadugtong", "kompyuter", "computer", "buong mundo", "tibuok kalibutan", "impormasyon", "datos", "nagpapadala", "magpadala", "nagbabahagi", "magbahin", "konektado"], "fact": {"tl": "Ang internet ay isang napakalaking network na nag-uugnay ng milyon-milyong kompyuter at telepono sa buong mundo upang magpadala at magbahagi ng impormasyon.", "en": "The internet is a huge network that connects millions of computers and phones around the world so they can send and share information.", "bis": "Ang internet usa ka dako kaayo nga network nga nagdugtong sa minilyon ka kompyuter ug telepono sa tibuok kalibutan aron makapadala ug makapakigbahin og impormasyon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "internet-changed-life-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "how the internet changed life", "grades": [5, 6, 7], "terms": ["internet", "binago", "giusab", "impormasyon", "kaalaman", "kahibalo", "pag-aaral", "pagtuon", "balita", "mensahe", "video", "larawan", "hulagway", "kahit saan", "bisan asa", "mabilis", "paspas", "komunikasyon", "konektado"], "fact": {"tl": "Binago ng internet ang buhay dahil sa loob ng ilang segundo ay makakahanap, makakapagpadala, at makakapagbahagi na tayo ng impormasyon, balita, larawan, at mensahe sa kahit sinong tao sa mundo.", "en": "The internet changed life because in just seconds we can find, send, and share information, news, pictures, and messages with almost anyone in the world.", "bis": "Giusab sa internet ang kinabuhi kay sulod sa pipila ka segundo makakita, makapadala, ug makapakigbahin na kita og impormasyon, balita, hulagway, ug mensahe sa halos bisan kinsa sa kalibutan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "vaccine-what-is-g5", "domain": "LIVING_THINGS", "topic": "what a vaccine is", "grades": [5, 6, 7], "terms": ["bakuna", "bakunay", "vaccine", "sakit", "balatian", "depensa", "panalipod", "immune system", "katawan", "lawas", "nakikilala", "mailhan", "germ", "mikrobyo", "naghahanda", "moandam", "proteksyon", "iniksyon", "turok"], "fact": {"tl": "Ang bakuna ay isang gamot na nagtuturo sa depensa ng katawan na makilala at labanan ang isang partikular na sakit, kaya hindi ka na ito masyadong magkasakit o hindi na talaga magkakasakit.", "en": "A vaccine is a medicine that teaches the body's defenses to recognize and fight a certain disease, so you become much less likely to get sick from it.", "bis": "Ang bakuna usa ka tambal nga magtudlo sa depensa sa lawas aron mailhan ug makigbatok sa usa ka partikular nga sakit, busa dili na ka kaayo masakit o dili na gyud masakit niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "vaccine-jenner-smallpox-g6", "domain": "LIVING_THINGS", "topic": "the first vaccine", "grades": [6, 7, 8], "terms": ["bakuna", "vaccine", "Edward Jenner", "Jenner", "smallpox", "bulutong", "1796", "unang bakuna", "doktor", "mananambal", "imbento", "natuklasan", "nadiskobre", "cowpox", "naimbento", "kasaysayan"], "fact": {"tl": "Noong 1796, ginawa ng doktor na si Edward Jenner ang unang bakuna laban sa nakamamatay na sakit na smallpox (bulutong), na nagbukas ng daan para sa mga bakunang nagliligtas ng milyon-milyong buhay ngayon.", "en": "In 1796, the doctor Edward Jenner made the first vaccine against the deadly disease smallpox, which opened the way for the vaccines that save millions of lives today.", "bis": "Niadtong 1796, gihimo sa doktor nga si Edward Jenner ang unang bakuna batok sa makamatay nga sakit nga smallpox (bulutong), nga nag-abli sa dalan alang sa mga bakuna nga nagluwas og minilyon ka kinabuhi karon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "vaccine-changed-health-g6", "domain": "LIVING_THINGS", "topic": "how vaccines changed health", "grades": [6, 7, 8], "terms": ["bakuna", "vaccine", "sakit", "balatian", "kalusugan", "panglawas", "smallpox", "bulutong", "polio", "tigdas", "namatay", "naluwas", "milyon-milyong buhay", "nawala", "napuksa", "epidemya", "binago", "giusab", "bata"], "fact": {"tl": "Binago ng bakuna ang kalusugan ng mundo dahil ang mga sakit na dating pumapatay ng napakaraming bata, tulad ng smallpox at polio, ay napigilan o tuluyang nawala dahil dito.", "en": "Vaccines changed the world's health because diseases that once killed very many children, like smallpox and polio, have been stopped or even wiped out because of them.", "bis": "Giusab sa bakuna ang panglawas sa kalibutan kay ang mga sakit nga kaniadto mopatay og daghan kaayong bata, sama sa smallpox ug polio, napugngan o nawala na tungod niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "printing-press-gutenberg-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "the printing press", "grades": [5, 6, 7], "terms": ["imprenta", "printing press", "Johannes Gutenberg", "Gutenberg", "libro", "basahon", "aklat", "1440", "imbento", "naimbento", "giimbento", "nagkopya", "magkopya", "limbag", "moimprenta", "marami", "daghan", "letra", "titik"], "fact": {"tl": "Noong mga 1440, naimbento ni Johannes Gutenberg sa Europa ang imprenta na may galaw-galaw na letra, na nagpabilis sa paggawa ng maraming kopya ng libro.", "en": "Around 1440, Johannes Gutenberg in Europe invented the printing press with movable type, which made it much faster to make many copies of a book.", "bis": "Niadtong mga 1440, giimbento ni Johannes Gutenberg sa Europa ang imprenta nga adunay malihok nga mga letra, nga nagpapaspas sa paghimo og daghang kopya sa basahon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "printing-press-changed-learning-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "how the printing press spread knowledge", "grades": [6, 7, 8], "terms": ["imprenta", "printing press", "libro", "basahon", "aklat", "kaalaman", "kahibalo", "kamao", "pagbasa", "pagsulat", "mura", "barato", "mahal", "kamay", "sinulat sa kamay", "kinamot", "marami", "daghan", "binago", "giusab", "edukasyon"], "fact": {"tl": "Bago ang imprenta, isinusulat ng kamay ang mga libro kaya kakaunti at mahal ang mga ito; pinabilis ng imprenta ang paggawa ng libro, kaya mas maraming tao ang nakapag-aral at nakabasa.", "en": "Before the printing press, books were copied by hand so they were few and expensive; the press made books quickly, so far more people could learn and read.", "bis": "Sa wala pa ang imprenta, ang mga libro gikopya pinaagi sa kamot busa gamay ra ug mahal; gipapaspas sa imprenta ang paghimo og libro, busa mas daghang tawo ang nakatuon ug nakabasa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "radio-invention-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "the invention of radio", "grades": [5, 6, 7], "terms": ["radyo", "radio", "Marconi", "Guglielmo Marconi", "alon", "balod", "radio waves", "senyales", "signal", "boses", "tingog", "musika", "balita", "walang kawad", "way alambre", "malayo", "layo", "wireless", "nagpapadala"], "fact": {"tl": "Noong huling bahagi ng 1890s, naipakita ni Guglielmo Marconi kung paano magpadala ng mensahe sa pamamagitan ng radio waves nang walang kawad, na naging simula ng radyo.", "en": "In the late 1890s, Guglielmo Marconi showed how to send messages through radio waves without wires, which was the start of the radio.", "bis": "Sa ulahing bahin sa 1890s, gipakita ni Guglielmo Marconi kung unsaon pagpadala og mensahe pinaagi sa radio waves nga walay alambre, nga maoy sinugdanan sa radyo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "radio-changed-news-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "how radio spread news to many people", "grades": [5, 6, 7], "terms": ["radyo", "radio", "balita", "balita kaagad", "mensahe", "musika", "tugtog", "maraming tao", "daghang tawo", "sabay-sabay", "dungan", "bahay", "balay", "bagyo", "babala", "pasidaan", "Pilipinas", "broadcast", "nakarating"], "fact": {"tl": "Binago ng radyo ang pagbabalita dahil sabay-sabay nang nakakarating ang balita, babala sa bagyo, at musika sa milyon-milyong tahanan kahit walang internet o telebisyon.", "en": "Radio changed the news because news, storm warnings, and music could reach millions of homes all at the same time, even without internet or television.", "bis": "Giusab sa radyo ang pagbalita kay dungan nga makaabot ang balita, pasidaan sa bagyo, ug musika sa minilyon ka panimalay bisan walay internet o telebisyon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "steam-engine-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "the steam engine", "grades": [6, 7, 8], "terms": ["steam engine", "makinang singaw", "singaw", "alisngaw", "aso sa tubig", "James Watt", "Watt", "tren", "barko", "pabrika", "pabrikahan", "init", "kuryente ng singaw", "puwersa", "kusog", "naglihok", "umandar", "1700s", "rebolusyong industriyal"], "fact": {"tl": "Ang steam engine, na pinaunlad ni James Watt noong 1700s, ay gumagamit ng singaw ng kumukulong tubig para magpaandar ng makina, at naging dahilan ng pagdami ng mga pabrika, tren, at barko.", "en": "The steam engine, improved by James Watt in the 1700s, uses the steam of boiling water to power machines, and it led to the rise of factories, trains, and ships.", "bis": "Ang steam engine, nga gipauswag ni James Watt niadtong 1700s, naggamit sa aso sa nagbukal nga tubig aron padaganon ang makina, ug nahimong hinungdan sa pagdaghan sa mga pabrika, tren, ug barko."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "car-automobile-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "the automobile", "grades": [5, 6, 7], "terms": ["kotse", "awto", "sasakyan", "sakyanan", "automobile", "car", "Karl Benz", "Benz", "makina", "gasolina", "Henry Ford", "Ford", "marami", "daghan", "biyahe", "panaw", "1886", "imbento", "naimbento", "kabayo", "kalsada"], "fact": {"tl": "Ang kotseng de-makina ay ginawa ni Karl Benz noong 1886, at nang gawing mura at marami ni Henry Ford ang mga kotse, nakapagbiyahe na ang karaniwang tao nang hindi kailangan ng kabayo o karwahe.", "en": "The motor car was built by Karl Benz in 1886, and when Henry Ford made cars cheap and plentiful, ordinary people could travel without needing a horse or carriage.", "bis": "Ang awto nga adunay makina gibuhat ni Karl Benz niadtong 1886, ug sa dihang gihimo ni Henry Ford nga barato ug daghan ang mga awto, nakabiyahe na ang ordinaryong tawo nga dili na kinahanglan og kabayo o karwahe."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "telegraph-morse-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "the telegraph", "grades": [6, 7, 8], "terms": ["telegrapo", "telegraph", "Morse code", "Samuel Morse", "Morse", "kawad", "alambre", "senyales", "signal", "tuldok", "guhit", "dash", "dot", "mensahe", "malayo", "layo", "kuryente", "1840s", "mabilis", "una pang telepono"], "fact": {"tl": "Ang telegrapo, na pinaunlad ni Samuel Morse noong 1840s, ay nagpapadala ng mensahe sa malayo sa pamamagitan ng mga tuldok at guhit (Morse code) na dumadaan sa kawad — ito ang unang mabilis na komunikasyon bago ang telepono.", "en": "The telegraph, developed by Samuel Morse in the 1840s, sent messages over long distances using dots and dashes (Morse code) carried through a wire — it was the first fast long-distance communication before the telephone.", "bis": "Ang telegrapo, nga gipauswag ni Samuel Morse niadtong 1840s, nagpadala og mensahe sa layo pinaagi sa mga tuldok ug guhit (Morse code) nga moagi sa alambre — kini ang unang paspas nga komunikasyon sa wala pa ang telepono."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "refrigerator-invention-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "the refrigerator", "grades": [4, 5, 6], "terms": ["repridyiretor", "refrigerator", "pridyider", "ref", "malamig", "bugnaw", "pagkain", "pagkaon", "panis", "madunot", "madaot", "yelo", "ice", "presko", "preserba", "tagal", "imbento", "kuryente", "init"], "fact": {"tl": "Binago ng refrigerator ang buhay dahil pinapanatili nitong malamig ang pagkain upang hindi agad mapanis, kaya nagagawa nang itago ang pagkain nang matagal nang hindi gumagamit ng yelo araw-araw.", "en": "The refrigerator changed life because it keeps food cold so it does not spoil quickly, letting people store food for a long time without needing ice every day.", "bis": "Giusab sa refrigerator ang kinabuhi kay gibantayan niini nga bugnaw ang pagkaon aron dili dali madaot, busa matipigan na ang pagkaon og dugay nga dili kinahanglan og yelo matag adlaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "telescope-invention-g5", "domain": "EARTH_SPACE", "topic": "the telescope", "grades": [5, 6, 7], "terms": ["teleskopyo", "telescope", "Galileo", "salamin", "lente", "lens", "malayong bagay", "layong butang", "bituin", "bitoon", "buwan", "bulan", "planeta", "kalangitan", "tumingin", "motan-aw", "malinaw", "imbento", "1600s"], "fact": {"tl": "Ang teleskopyo ay isang kagamitang gumagamit ng lente para palakihin ang malalayong bagay, at noong mga 1609 ginamit ito ni Galileo para tingnan ang buwan, mga planeta, at bituin.", "en": "The telescope is a tool that uses lenses to make far-away objects look bigger, and around 1609 Galileo used it to look at the moon, planets, and stars.", "bis": "Ang teleskopyo usa ka himan nga naggamit og lente aron padakuon ang layong mga butang, ug niadtong mga 1609 gigamit kini ni Galileo aron tan-awon ang bulan, mga planeta, ug bitoon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "antibiotics-penicillin-g7", "domain": "LIVING_THINGS", "topic": "antibiotics and penicillin", "grades": [7, 8, 9], "terms": ["antibiotic", "antibiotiko", "penicillin", "penisilina", "Alexander Fleming", "Fleming", "bakterya", "bacteria", "impeksiyon", "impeksyon", "sakit", "amag", "agup-op", "gamot", "tambal", "1928", "namatay", "naluwas", "germ"], "fact": {"tl": "Noong 1928, natuklasan ni Alexander Fleming ang penicillin mula sa isang amag, ang unang antibiotic — isang gamot na pumapatay ng bakteryang nagdudulot ng impeksiyon at nakapagligtas ng napakaraming buhay.", "en": "In 1928, Alexander Fleming discovered penicillin from a mold, the first antibiotic — a medicine that kills the bacteria that cause infections and has saved very many lives.", "bis": "Niadtong 1928, nadiskobrehan ni Alexander Fleming ang penicillin gikan sa usa ka agup-op, ang unang antibiotic — usa ka tambal nga mopatay sa bakterya nga maoy hinungdan sa impeksiyon ug nakaluwas og daghan kaayong kinabuhi."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "compass-invention-g5", "domain": "EARTH_SPACE", "topic": "the magnetic compass", "grades": [5, 6, 7], "terms": ["kompas", "compass", "magnet", "bato-balani", "hilaga", "amihanan", "norte", "direksiyon", "direksyon", "karayom", "dagom", "barko", "marino", "China", "Tsina", "nawawala", "nakalibot", "naglalakbay", "imbento"], "fact": {"tl": "Ang kompas ay isang kagamitang may magnetikong karayom na laging tumuturo sa hilaga, na unang ginamit sa China at tumulong sa mga marino na hindi maligaw kahit malayo sa dagat.", "en": "The compass is a tool with a magnetic needle that always points north, first used in China, and it helped sailors not get lost even far out at sea.", "bis": "Ang kompas usa ka himan nga adunay magnetikong dagom nga kanunay motudlo sa amihanan, unang gigamit sa China, ug nakatabang sa mga marino nga dili masaag bisan layo sa dagat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "camera-photography-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "the camera and photography", "grades": [5, 6, 7], "terms": ["kamera", "camera", "litrato", "hulagway", "larawan", "retrato", "kuha", "kuhaan", "ilaw", "liwanag", "kahayag", "lente", "lens", "naglalarawan", "alaala", "memorya", "1800s", "imbento", "natala"], "fact": {"tl": "Ang kamera ay isang kagamitang humuhuli ng larawan sa pamamagitan ng pagpapasok ng liwanag sa lente, at noong unang naimbento ito noong 1800s, unang beses na natala ang mga totoong larawan na hindi iginuhit ng kamay.", "en": "The camera is a tool that captures images by letting light through a lens, and when it was first invented in the 1800s, real pictures could be recorded for the first time without being drawn by hand.", "bis": "Ang kamera usa ka himan nga modakop og hulagway pinaagi sa pagpasulod sa kahayag sa lente, ug sa una kini naimbento niadtong 1800s, sa unang higayon natala ang tinuod nga mga hulagway nga wala gidrowing pinaagi sa kamot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "battery-invention-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "the battery", "grades": [5, 6, 7], "terms": ["baterya", "battery", "Alessandro Volta", "Volta", "kuryente", "koryente", "elektrisidad", "iniimbak", "tinipigan", "stored", "kemikal", "kemikal nga reaksyon", "flashlight", "cellphone", "selpon", "1800", "lakas", "kuryenteng dala"], "fact": {"tl": "Ang baterya, na unang ginawa ni Alessandro Volta noong 1800, ay nag-iimbak ng kuryente mula sa reaksyong kemikal, kaya may dalang sariling kuryente ang mga gadget tulad ng flashlight at cellphone kahit walang saksak.", "en": "The battery, first made by Alessandro Volta in 1800, stores electricity from a chemical reaction, so gadgets like flashlights and cellphones carry their own power even when unplugged.", "bis": "Ang baterya, nga unang gihimo ni Alessandro Volta niadtong 1800, magtipig og kuryente gikan sa kemikal nga reaksiyon, busa ang mga gadget sama sa flashlight ug cellphone adunay kaugalingong kuryente bisan walay saksak."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bird-of-paradise-flower-g4", "domain": "LIVING_THINGS", "topic": "bird of paradise flower", "grades": [3, 4, 5], "terms": ["bird of paradise", "bulaklak", "strelitzia", "ibong", "orange", "asul", "kahawig ng ibon", "bulak", "pollination", "pollinator", "bunga", "bird-shaped flower", "kahel", "dilaw"], "fact": {"tl": "Ang bird of paradise ay isang halamang pang-hardin na may kahel at asul na bulaklak na kahawig ng ulo ng lumilipad na ibon.", "en": "The bird of paradise is a garden plant whose orange and blue flowers look like the head of a flying bird.", "bis": "Ang bird of paradise usa ka tanom sa hardin nga ang kahel ug asul nga bulak morag ulo sa naglupad nga langgam."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "biodiversity-forest-layers-g5", "domain": "LIVING_THINGS", "topic": "forest layers and biodiversity", "grades": [4, 5, 6], "terms": ["forest layers", "gubat", "kagubatan", "biodiversity", "kasarisari", "canopy", "tuktok ng gubat", "understory", "kalupkupan", "sahig ng gubat", "forest floor", "halaman", "hayop", "tirahan", "habitat", "puno", "kahoy", "naglainlain"], "fact": {"tl": "May iba't ibang patong ang gubat—mula sa mataas na tuktok ng mga puno hanggang sa madilim na sahig—at bawat patong ay tirahan ng iba't ibang halaman at hayop.", "en": "A forest has different layers—from the high treetops down to the dark floor—and each layer is home to different plants and animals.", "bis": "Ang lasang adunay lainlaing sapaw—gikan sa taas nga tumoy sa mga kahoy hangtod sa ngitngit nga salog—ug ang matag sapaw puy-anan sa lainlaing tanom ug hayop."}, "source": "Harlen Big Ideas; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "birdwing-butterfly-g4", "domain": "LIVING_THINGS", "topic": "birdwing butterfly", "grades": [3, 4, 5], "terms": ["birdwing butterfly", "paruparo", "alibangbang", "butterfly", "malaki", "biggest butterfly", "pakpak", "wings", "tropical", "insekto", "insect", "kabukid", "kagubatan", "Southeast Asia", "alibangbang"], "fact": {"tl": "Ang birdwing ay kabilang sa pinakamalalaking paruparo sa mundo, na may malalapad na pakpak na nakikita sa mainit na kagubatan ng tropiko.", "en": "The birdwing is one of the largest butterflies in the world, with wide wings seen in warm tropical forests.", "bis": "Ang birdwing usa sa pinakadako nga alibangbang sa kalibotan, nga adunay halapad nga pako nga makita sa init nga lasang sa tropiko."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "black-pepper-vine-g5", "domain": "LIVING_THINGS", "topic": "black pepper vine", "grades": [4, 5, 6], "terms": ["black pepper", "paminta", "pamienta", "vine", "baging", "spice", "pampalasa", "bunga", "bilog", "peppercorn", "halaman", "tanom", "gumagapang", "climbing plant", "anghang", "pebra", "paklang"], "fact": {"tl": "Ang paminta ay nagmumula sa maliliit at bilog na bunga ng isang gumagapang na baging na pinatutuyo at ginagawang pampalasa sa pagkain.", "en": "Black pepper comes from the small round berries of a climbing vine that are dried and used to spice up food.", "bis": "Ang paminta gikan sa gagmay ug lingin nga bunga sa nagakatay nga baging nga gipauga ug gigamit pangpalami sa pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "blood-components-drop-g6", "domain": "LIVING_THINGS", "topic": "components of blood", "grades": [5, 6, 7], "terms": ["blood", "dugo", "red blood cells", "pulang selula", "white blood cells", "puting selula", "platelets", "plasma", "oxygen", "oksiheno", "germs", "mikrobyo", "namumuong dugo", "clotting", "pula nga selula", "puti nga selula", "sangkap ng dugo"], "fact": {"tl": "Ang dugo ay binubuo ng plasma at maliliit na selula—pulang selula na nagdadala ng oksiheno, puting selula na lumalaban sa mikrobyo, at platelet na nagpapamuo ng sugat.", "en": "Blood is made of plasma and tiny cells—red cells that carry oxygen, white cells that fight germs, and platelets that clot wounds.", "bis": "Ang dugo gilangkoban sa plasma ug gagmay nga selula—pula nga selula nga nagdala og oksiheno, puti nga selula nga nakig-away sa mikrobyo, ug platelet nga nagpamuo sa samad."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "biodiversity-hotspot-pyramid-g7", "domain": "LIVING_THINGS", "topic": "biodiversity hotspot", "grades": [6, 7, 8], "terms": ["biodiversity hotspot", "biodiversity", "kasarisari ng buhay", "Pilipinas", "Philippines", "endemic", "katutubo", "hayop", "halaman", "species", "namumuhay dito lang", "endangered", "nanganganib", "natatanging hayop", "talagsaon", "kinaiyanhon"], "fact": {"tl": "Ang Pilipinas ay isang biodiversity hotspot—isang lugar na may napakaraming katutubong hayop at halaman na matatagpuan lamang dito at kailangang ingatan.", "en": "The Philippines is a biodiversity hotspot—a place with very many native animals and plants found nowhere else, which must be protected.", "bis": "Ang Pilipinas usa ka biodiversity hotspot—usa ka dapit nga adunay daghang kinaiyanhon nga mananap ug tanom nga makita lamang dinhi ug kinahanglan ampingan."}, "source": "DepEd MATATAG Science; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "blind-snake-ahas-bulag-g5", "domain": "LIVING_THINGS", "topic": "blind snake", "grades": [4, 5, 6], "terms": ["blind snake", "ahas na bulag", "ahas", "bitin", "snake", "lupa", "underground", "earthworm", "bulate", "parang bulate", "maliit", "small snake", "mata", "harmless", "hindi nakakagat", "halos walang mata", "buta nga halas"], "fact": {"tl": "Ang blind snake ay isang maliit na ahas na parang bulate, na nakatira sa ilalim ng lupa at halos hindi nakakakita kaya tinawag itong bulag.", "en": "The blind snake is a tiny, worm-like snake that lives underground and can barely see, which is why it is called blind.", "bis": "Ang blind snake usa ka gamay nga halas nga morag wati, nga nagpuyo ilalom sa yuta ug halos dili makakita maong gitawag nga buta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bird-pollination-sunbird-scene-g4", "domain": "LIVING_THINGS", "topic": "bird pollination by sunbirds", "grades": [3, 4, 5], "terms": ["sunbird", "pispis", "tamsi", "pollination", "polinasyon", "nektar", "nectar", "bulaklak", "flower", "ibon", "bird", "naglilipat ng polen", "pollen", "langgam", "nanunuyo", "pollinator", "naglupad", "tutok-tutok"], "fact": {"tl": "Habang umiinom ng tamis na nektar sa bulaklak, ang sunbird ay nadidikitan ng polen at dinadala ito sa ibang bulaklak, kaya tumutulong itong magpabunga ng halaman.", "en": "While drinking sweet nectar from flowers, the sunbird picks up pollen and carries it to other flowers, helping the plants make seeds.", "bis": "Samtang naginom sa tam-is nga nektar sa bulak, ang sunbird mapilit og polen ug madala kini sa laing bulak, busa makatabang kini sa pagpamunga sa tanom."}, "source": "NRC LS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "blood-circulation-loop-g6", "domain": "LIVING_THINGS", "topic": "blood circulation", "grades": [5, 6, 7], "terms": ["blood circulation", "sirkulasyon ng dugo", "puso", "heart", "dugo", "blood", "ugat", "blood vessel", "oksiheno", "oxygen", "buong katawan", "pumipintig", "pumping", "pag-ikot ng dugo", "baga", "lungs", "tibok", "nag-uulit", "sirkulasyon"], "fact": {"tl": "Ang puso ay parang bomba na walang tigil na pinapadaloy ang dugo sa buong katawan sa pamamagitan ng mga ugat, para magdala ng oksiheno at pagkain sa bawat bahagi.", "en": "The heart works like a pump that keeps blood flowing through vessels around the whole body, carrying oxygen and food to every part.", "bis": "Ang kasingkasing morag bomba nga walay hunong nga nagpadagayday sa dugo sa tibuok lawas pinaagi sa mga ugat, aron magdala og oksiheno ug pagkaon sa matag bahin."}, "source": "NRC LS1.A; DepEd Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "body-defenses-against-germs-g6", "domain": "LIVING_THINGS", "topic": "body defenses against germs", "grades": [5, 6, 7], "terms": ["body defenses", "panlaban sa sakit", "immune system", "depensa ng katawan", "germs", "mikrobyo", "bacteria", "virus", "balat", "skin", "puting selula", "white blood cells", "lumalaban", "proteksyon", "panangga", "depensa sa lawas", "sakit"], "fact": {"tl": "Ang katawan ay may mga panangga laban sa mikrobyo—ang balat na humaharang, at ang puting selula ng dugo na lumalamon sa mga mikrobyong nakakapasok.", "en": "The body has defenses against germs—the skin that blocks them out, and white blood cells that gobble up germs that get inside.", "bis": "Ang lawas adunay mga panalipod batok sa mikrobyo—ang panit nga nagsumpo, ug ang puti nga selula sa dugo nga nagatulon sa mikrobyo nga makasulod."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "blood-pressure-cuff-check-g7", "domain": "LIVING_THINGS", "topic": "blood pressure", "grades": [6, 7, 8], "terms": ["blood pressure", "presyon ng dugo", "cuff", "sphygmomanometer", "puso", "heart", "ugat", "artery", "lakas ng pagtulak", "sukat", "measure", "doktor", "kalusugan", "health", "presyon sa dugo", "tibok", "tension"], "fact": {"tl": "Ang blood pressure ay sukat kung gaano kalakas itinutulak ng puso ang dugo sa mga ugat, at sinusukat ito gamit ang isang cuff na ibinabalot sa braso.", "en": "Blood pressure measures how hard the heart pushes blood through the vessels, and it is measured with a cuff wrapped around the arm.", "bis": "Ang blood pressure mao ang sukod kung unsa kakusog ang pagtulod sa kasingkasing sa dugo agi sa mga ugat, ug gisukod kini gamit ang cuff nga giputos sa bukton."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bone-structure-cutaway-g6", "domain": "LIVING_THINGS", "topic": "bone structure", "grades": [5, 6, 7], "terms": ["bone", "buto", "bukog", "skeleton", "balangkas", "marrow", "utak ng buto", "matigas", "hard", "dugo", "blood cells", "kalsiyum", "calcium", "sumusuporta", "support", "gumagawa ng dugo", "buhay na buto", "lawas"], "fact": {"tl": "Ang buto ay matigas sa labas para suportahan ang katawan, ngunit may malambot na marrow sa loob na gumagawa ng bagong selula ng dugo.", "en": "A bone is hard on the outside to support the body, but has soft marrow inside that makes new blood cells.", "bis": "Ang bukog gahi sa gawas aron suportahan ang lawas, apan adunay humok nga marrow sa sulod nga naghimo og bag-ong selula sa dugo."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "blood-vessel-types-cross-section-g7", "domain": "LIVING_THINGS", "topic": "types of blood vessels", "grades": [6, 7, 8], "terms": ["blood vessels", "ugat", "arteries", "arterya", "veins", "vena", "capillaries", "kapilarya", "dugo", "blood", "papalayo sa puso", "pabalik sa puso", "maninipis", "oxygen", "oksiheno", "uri ng ugat", "agianan ng dugo"], "fact": {"tl": "May tatlong uri ng ugat: ang arterya na nagdadala ng dugo palayo sa puso, ang vena na nagbabalik nito, at ang maninipis na kapilarya kung saan dumadaloy ang oksiheno sa selula.", "en": "There are three kinds of blood vessels: arteries carry blood away from the heart, veins bring it back, and tiny capillaries let oxygen pass to the cells.", "bis": "Adunay tulo ka matang sa ugat: ang arterya nagdala sa dugo palayo sa kasingkasing, ang vena nagbalik niini, ug ang nipis nga kapilarya nagpaagi sa oksiheno ngadto sa selula."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bougainvillea-g4", "domain": "LIVING_THINGS", "topic": "bougainvillea", "grades": [3, 4, 5], "terms": ["bougainvillea", "bugambilya", "bulaklak", "flower", "tinik", "thorns", "makukulay", "colorful", "halaman", "tanom", "bracts", "dahon", "rosas", "pula", "lila", "hardin", "gumagapang", "purple", "pink"], "fact": {"tl": "Ang bugambilya ay isang matinik na halaman na ang makukulay na 'bulaklak' nito ay talagang mga espesyal na dahon na nakapalibot sa maliit na tunay na bulaklak.", "en": "Bougainvillea is a thorny plant whose colorful 'flowers' are really special leaves that surround the small true flowers.", "bis": "Ang bugambilya usa ka tunokon nga tanom kansang mabulukon nga 'bulak' mao gyud ang pinasahi nga mga dahon nga naglibot sa gagmay nga tinuod nga bulak."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "boiling-drinking-water-pot-g4", "domain": "MATTER", "topic": "boiling water to make it safe to drink", "grades": [3, 4, 5], "terms": ["boiling water", "pagpapakulo ng tubig", "kulo", "mikrobyo", "germs", "ligtas inumin", "safe to drink", "init", "heat", "tubig", "water", "patay ang mikrobyo", "malinis", "clean", "pinakuluan", "pagpakulo", "buling tubig", "kalusugan"], "fact": {"tl": "Kapag pinakuluan ang tubig hanggang sa lumagablab, namamatay ang mga nakakasakit na mikrobyo, kaya nagiging mas ligtas itong inumin.", "en": "When water is boiled until it bubbles, the harmful germs in it are killed, making the water safer to drink.", "bis": "Kon pabukalan ang tubig hangtod molagiti, mamatay ang makasakit nga mikrobyo, busa mas luwas na kining imnon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bracket-fungus-shelf-g6", "domain": "LIVING_THINGS", "topic": "bracket fungus", "grades": [5, 6, 7], "terms": ["bracket fungus", "shelf fungus", "kabute", "uhong", "fungus", "puno", "tree trunk", "decomposer", "naagnas", "bulok na kahoy", "dead wood", "patong-patong", "nakadikit sa puno", "lumot", "kabuti", "nabulok", "uhong sa kahoy"], "fact": {"tl": "Ang bracket fungus ay isang uhong na patong-patong na tumutubo sa gilid ng mga puno, at tumutulong itong magpabulok ng patay na kahoy pabalik sa lupa.", "en": "Bracket fungus is a shelf-like fungus that grows on the sides of trees, and it helps rot dead wood back into the soil.", "bis": "Ang bracket fungus usa ka uhong nga morag estante nga motubo sa kilid sa mga kahoy, ug makatabang kini sa pagdunot sa patay nga kahoy balik sa yuta."}, "source": "NRC LS2.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "breathing-balloon-lung-model-g5", "domain": "LIVING_THINGS", "topic": "how the lungs breathe", "grades": [4, 5, 6], "terms": ["breathing", "paghinga", "baga", "lungs", "diaphragm", "balloon", "lobo", "hangin", "air", "oksiheno", "oxygen", "lumalaki", "lumiliit", "inhale", "exhale", "paglanghap", "pagbuga", "ginhawa", "balloon lung"], "fact": {"tl": "Kapag huminga tayo, lumalaki ang baga na parang lobong pinupuno ng hangin, at kapag bumuga tayo, lumiliit ito para palabasin ang hangin.", "en": "When we breathe in, the lungs expand like a balloon filling with air, and when we breathe out, they shrink to push the air back out.", "bis": "Kon moginhawa ta, modako ang baga sama sa lobo nga napuno og hangin, ug kon mobuga ta, mokunhod kini aron ipagawas ang hangin."}, "source": "NRC LS1.A; DepEd Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "brain-three-regions-simple-g6", "domain": "LIVING_THINGS", "topic": "three regions of the brain", "grades": [5, 6, 7], "terms": ["brain", "utak", "cerebrum", "cerebellum", "brain stem", "isip", "pag-iisip", "balanse", "balance", "tibok ng puso", "paghinga", "kontrol", "control", "bahagi ng utak", "thinking", "tatlong bahagi", "utok"], "fact": {"tl": "Ang utak ay may tatlong pangunahing bahagi: ang malaking cerebrum para mag-isip, ang cerebellum para sa balanse at galaw, at ang brain stem na kumokontrol sa paghinga at tibok ng puso.", "en": "The brain has three main parts: the large cerebrum for thinking, the cerebellum for balance and movement, and the brain stem that controls breathing and heartbeat.", "bis": "Ang utok adunay tulo ka panguna nga bahin: ang dako nga cerebrum para sa paghunahuna, ang cerebellum para sa balanse ug lihok, ug ang brain stem nga nagkontrol sa pagginhawa ug pitik sa kasingkasing."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "brittle-star-arms-g5", "domain": "LIVING_THINGS", "topic": "brittle star", "grades": [4, 5, 6], "terms": ["brittle star", "starfish", "bituin sa dagat", "limang braso", "five arms", "echinoderm", "dagat", "sea", "ilalim ng dagat", "seafloor", "gumagalaw", "manipis na braso", "regrow", "tumutubong muli", "bitoon sa dagat", "buhay sa dagat", "bituin ng dagat"], "fact": {"tl": "Ang brittle star ay kamag-anak ng starfish na may limang manipis at gumagalaw na braso, at kaya nitong palitan ang braso na napuputol.", "en": "The brittle star is a relative of the starfish with five thin, wiggly arms, and it can regrow an arm that breaks off.", "bis": "Ang brittle star paryente sa starfish nga adunay lima ka nipis ug mabaling nga bukton, ug makahimo kini og bag-ong bukton kon maputol."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "buho-bamboo-g5", "domain": "LIVING_THINGS", "topic": "buho bamboo", "grades": [4, 5, 6], "terms": ["buho", "bamboo", "kawayan", "kawayang buho", "thin-walled bamboo", "halaman", "tanom", "damo", "grass", "mabilis lumaki", "fast-growing", "tuyong gilid", "ilog", "Pilipinas", "Philippines", "manipis na balat", "kawayan nga buho"], "fact": {"tl": "Ang buho ay isang uri ng kawayan na may manipis na balat at madalas tumutubo malapit sa ilog at gilid ng bundok sa Pilipinas.", "en": "Buho is a kind of bamboo with thin walls that often grows near rivers and hillsides in the Philippines.", "bis": "Ang buho usa ka matang sa kawayan nga adunay nipis nga bongbong nga kasagaran motubo duol sa suba ug kilid sa bukid sa Pilipinas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "breadfruit-rimas-g4", "domain": "LIVING_THINGS", "topic": "breadfruit (rimas)", "grades": [3, 4, 5], "terms": ["breadfruit", "rimas", "prutas", "fruit", "puno", "tree", "malaki", "starchy", "almirol", "niluluto", "cooked", "pagkain", "food", "tropical", "bunga", "rimas nga prutas", "kahoy"], "fact": {"tl": "Ang rimas o breadfruit ay isang malaking bunga ng puno na puno ng almirol, at niluluto ito bago kainin na parang gulay o kamoteng-kahoy.", "en": "The breadfruit, or rimas, is a large starchy fruit from a tree, and it is cooked before eating like a vegetable or root crop.", "bis": "Ang rimas o breadfruit usa ka dako nga bunga sa kahoy nga puno sa almidor, ug giluto kini una kan-on sama sa utanon o lagutmon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "burn-cool-running-water-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "first aid for burns with cool running water", "grades": [3, 4, 5], "terms": ["burn", "paso", "first aid", "lunas", "tubig", "cool water", "malamig na tubig", "init", "heat", "balat", "skin", "sakit", "pahirin ang init", "running water", "umaagos na tubig", "tulong", "paso sa init", "nagdadagan nga tubig"], "fact": {"tl": "Kapag napaso, dapat ilagay agad ang sugat sa ilalim ng malamig na umaagos na tubig nang ilang minuto para mabawasan ang init at sakit.", "en": "When you get a burn, you should hold it under cool running water for several minutes to draw out the heat and ease the pain.", "bis": "Kon mapaso, kinahanglan dayon ibutang ang samad ilalom sa bugnaw nga nagdagayday nga tubig sa pipila ka minuto aron makunhoran ang kainit ug kasakit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "brown-vs-white-rice-bowls-g5", "domain": "LIVING_THINGS", "topic": "brown rice versus white rice", "grades": [4, 5, 6], "terms": ["brown rice", "white rice", "kanin", "bigas", "pulang bigas", "puting bigas", "balat ng bigas", "bran", "fiber", "hibla", "sustansya", "nutrients", "kinain", "milled", "hinimay", "bran layer", "lugas", "humay", "kanin nga pula"], "fact": {"tl": "Ang brown rice ay may natitirang panlabas na balat na puno ng hibla at sustansya, samantalang ang white rice ay tinatanggalan ng balat na ito kaya mas kaunti ang sustansya nito.", "en": "Brown rice keeps its outer bran layer full of fiber and nutrients, while white rice has that layer removed, leaving it with fewer nutrients.", "bis": "Ang brown rice nagpabilin ang gawas nga panit nga puno sa hibla ug sustansya, samtang ang white rice gikuhaan niini nga panit busa mas gamay ang sustansya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cadena-de-amor-g4", "domain": "LIVING_THINGS", "topic": "cadena de amor", "grades": [3, 4, 5], "terms": ["cadena de amor", "chain of love", "bulaklak", "flower", "baging", "vine", "pink", "rosas", "gumagapang", "climbing", "bubuyog", "bees", "nektar", "halaman", "tanom", "puso-puso", "heart-shaped", "kadena de amor", "korona ng bulaklak"], "fact": {"tl": "Ang cadena de amor ay isang gumagapang na baging na may kumpol-kumpol na rosas na bulaklak na malimit dinarayo ng mga bubuyog para sa nektar.", "en": "Cadena de amor is a climbing vine with clusters of pink flowers that bees often visit for nectar.", "bis": "Ang cadena de amor usa ka nagakatay nga baging nga adunay pungpong nga rosas nga bulak nga kanunay duawon sa mga buyog para sa nektar."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "buko-juice-vendor-scene-g4", "domain": "LIVING_THINGS", "topic": "buko (young coconut) water", "grades": [3, 4, 5], "terms": ["buko", "young coconut", "niyog", "lubi", "coconut water", "tubig ng buko", "juice", "inumin", "drink", "refreshing", "nakakapreskong", "sustansya", "prutas", "bunga", "tubig sa lubi", "malamig na buko", "buko juice"], "fact": {"tl": "Ang buko ay batang niyog na ang loob ay may malinaw at matamis na tubig, na isang nakakapreskong inumin lalo na sa mainit na araw.", "en": "Buko is a young coconut whose inside holds clear, sweet water, which is a refreshing drink especially on hot days.", "bis": "Ang buko mao ang batan-ong lubi nga ang sulod adunay tin-aw ug tam-is nga tubig, nga usa ka makapreskong ilimnon ilabina sa init nga adlaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bullfrog-leap-g4", "domain": "LIVING_THINGS", "topic": "bullfrog and its leap", "grades": [3, 4, 5], "terms": ["bullfrog", "palaka", "baki", "frog", "amphibian", "lumukso", "leap", "jump", "malalakas na binti", "strong legs", "tubig", "lawa", "pond", "insekto", "kumakain ng insekto", "malaking palaka", "talon", "lukso"], "fact": {"tl": "Ang bullfrog ay isang malaking palaka na may malalakas na hulihang binti na nagbibigay-daan dito na lumukso nang malayo para makahuli ng insekto o makatakas.", "en": "The bullfrog is a large frog with strong back legs that let it leap far to catch insects or escape danger.", "bis": "Ang bullfrog usa ka dako nga baki nga adunay kusgan nga likod nga bitiis nga makapalukso niini og layo aron makadakop og insekto o makaikyas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cacao-pod-g5", "domain": "LIVING_THINGS", "topic": "cacao pod and chocolate", "grades": [4, 5, 6], "terms": ["cacao", "kakaw", "chocolate", "tsokolate", "pod", "bunga", "buto", "beans", "tablea", "puno", "tree", "prutas", "fermented", "pinatuyo", "tropical", "bunga ng kakaw", "sikwate", "kakaw nga prutas"], "fact": {"tl": "Ang tsokolate ay nagmumula sa mga buto sa loob ng bunga ng kakaw, na pinapatuyo at ginigiling bago gawing tablea o kendi.", "en": "Chocolate comes from the seeds inside the cacao pod, which are dried and ground before being made into tablea or candy.", "bis": "Ang tsokolate gikan sa mga liso sulod sa bunga sa kakaw, nga gipauga ug giligis una himoon nga tablea o kendi."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "calamansi-fruit-g4", "domain": "LIVING_THINGS", "topic": "calamansi", "grades": [3, 4, 5], "terms": ["calamansi", "kalamansi", "limonsito", "citrus", "maasim", "sour", "prutas", "fruit", "bitamina C", "vitamin C", "juice", "katas", "pampalasa", "berde", "green", "maliit na prutas", "kalamunding", "sampalok-citrus"], "fact": {"tl": "Ang kalamansi ay isang maliit at maasim na prutas na citrus na mayaman sa bitamina C at madalas pigaan para sa katas na pampalasa o inumin.", "en": "Calamansi is a small, sour citrus fruit rich in vitamin C that is often squeezed for juice to flavor food or make a drink.", "bis": "Ang kalamansi usa ka gamay ug aslom nga prutas nga citrus nga dato sa bitamina C ug kasagarang pug-on para sa duga nga pampalami o ilimnon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "buri-palm-g5", "domain": "LIVING_THINGS", "topic": "buri palm", "grades": [4, 5, 6], "terms": ["buri", "buri palm", "palma", "palmera", "dahon", "leaves", "banig", "sombrero", "weaving", "habi", "fiber", "raffia", "halaman", "tanom", "puno", "Pilipinas", "Philippines", "malaking palma"], "fact": {"tl": "Ang buri ay isang malaking palma na ang malalapad na dahon ay ginagawang banig, sombrero, at bayong sa pamamagitan ng paghahabi.", "en": "The buri is a large palm whose broad leaves are woven into mats, hats, and baskets.", "bis": "Ang buri usa ka dako nga palma kansang halapad nga mga dahon gihimo nga banig, kalo, ug bukag pinaagi sa paghabol."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "caecilian-worm-amphibian-g6", "domain": "LIVING_THINGS", "topic": "caecilian limbless amphibian", "grades": [6, 7], "terms": ["caecilian", "amphibian", "amphibyo", "walang paa", "parang bulate", "limbless", "burrowing", "naghuhukay sa lupa", "ulod nga amphibian", "walay tiil", "mananap nga molupyo sa yuta"], "fact": {"tl": "Ang caecilian ay isang amphibian na walang paa at parang malaking bulate, na naghuhukay at nabubuhay sa ilalim ng basa-basang lupa.", "en": "A caecilian is a limbless amphibian that looks like a large worm and burrows through moist soil.", "bis": "Ang caecilian usa ka amphibian nga walay tiil nga sama sa dakong ulod, ug nagkalot kini sa basa nga yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "capillary-action-celery-dye-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "capillary action in plant stems", "grades": [4, 5, 6], "terms": ["capillary action", "aksyong kapilarya", "kintsay", "celery", "kulay", "tubig umakyat", "tangkay", "akyat ng tubig", "pagtaas ng tubig", "kolor sa tubig", "pagsaka sa tubig", "lawas sa tanom", "uga sa tubig"], "fact": {"tl": "Kapag inilubog ang tangkay ng kintsay sa tubig na may kulay, umaakyat ang kuláy na tubig sa loob ng tangkay sa pamamagitan ng capillary action.", "en": "When a celery stalk is placed in colored water, the colored water climbs up through the stalk by capillary action.", "bis": "Kon ibutang ang tangkay sa celery sa tubig nga may kolor, mosaka ang kolorado nga tubig sa sulod sa tangkay pinaagi sa capillary action."}, "source": "AAAS Benchmarks; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "calamian-deer-g6", "domain": "LIVING_THINGS", "topic": "Calamian deer endemic Philippine species", "grades": [6, 7, 8], "terms": ["Calamian deer", "usa", "binaw", "Calamian", "Palawan", "endemiko", "naninirahan lamang sa Pilipinas", "nanganganib", "native deer", "endemic", "Pilipinhon nga usa", "endemiko sa Palawan", "usa nga namiligro"], "fact": {"tl": "Ang Calamian deer ay isang usa na matatagpuan lamang sa mga isla ng Calamian sa Palawan, kaya itinuturing itong endemiko at nanganganib sa Pilipinas.", "en": "The Calamian deer is a deer found only on the Calamian Islands of Palawan, making it an endemic and endangered Philippine species.", "bis": "Ang Calamian deer usa ka usa nga makit-an lamang sa mga isla sa Calamian sa Palawan, busa endemiko ug namiligro kini nga matang sa Pilipinas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "capillary-exchange-tissue-g9", "domain": "LIVING_THINGS", "topic": "capillary exchange in tissues", "grades": [9, 10], "terms": ["capillary", "kapilarya", "manipis na ugat", "palitan ng oxygen", "nutrient", "pinakamaliit na ugat", "tissue", "selula", "oxygen at nutrisyon", "manipis nga ugat", "pag-ilis sa oxygen", "kasselulahan", "labing gamay nga ugat"], "fact": {"tl": "Ang mga capillary ay ang pinakamaliit at pinakamanipis na mga daluyan ng dugo kung saan ipinapasa ang oxygen at nutrisyon sa mga selula at kinukuha ang dumi nito.", "en": "Capillaries are the smallest, thinnest blood vessels, where oxygen and nutrients pass into cells and wastes are picked up.", "bis": "Ang mga capillary mao ang labing gamay ug nipis nga agianan sa dugo, diin ang oxygen ug nutrisyon mosulod sa mga selula ug ang hugaw makuha."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "camia-ginger-lily-g5", "domain": "LIVING_THINGS", "topic": "camia white ginger lily", "grades": [5, 6], "terms": ["camia", "kamia", "ginger lily", "puting bulaklak", "mabango", "halaman", "tumutubo sa basang lupa", "white flower", "fragrant", "puti nga bulak", "humot nga bulak", "tanom nga mahumot"], "fact": {"tl": "Ang camia o kamia ay isang halaman na may mabango at puting bulaklak na tumutubo sa basa-basang lupa sa Pilipinas.", "en": "The camia, or white ginger lily, is a plant with fragrant white flowers that grows in moist soil in the Philippines.", "bis": "Ang camia o kamia usa ka tanom nga may mahumot ug puti nga bulak nga motubo sa basa nga yuta sa Pilipinas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "calamansi-vitamin-c-g5", "domain": "LIVING_THINGS", "topic": "calamansi vitamin C citrus", "grades": [4, 5, 6], "terms": ["calamansi", "kalamansi", "vitamin C", "bitamina C", "maasim", "citrus", "prutas", "katas", "sangkap sa pagkain", "sour", "lemonsito", "aslom", "prutas nga maaslom"], "fact": {"tl": "Ang kalamansi ay isang maliit at maasim na prutas na sagana sa bitamina C, na tumutulong upang labanan ng katawan ang sakit.", "en": "Calamansi is a small, sour citrus fruit rich in vitamin C, which helps the body fight off sickness.", "bis": "Ang kalamansi usa ka gamay ug maaslom nga prutas nga daghan sa bitamina C, nga makatabang sa lawas batok sa sakit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "carabao-grazing-single-g3", "domain": "LIVING_THINGS", "topic": "carabao grazing herbivore", "grades": [3, 4], "terms": ["carabao", "kalabaw", "damo", "kumakain ng damo", "herbivore", "halamang kinakain", "bukid", "hayop", "kalabaw nga mananap", "nagsibsib ug sagbot", "mananap nga mokaon ug sagbot", "grazing"], "fact": {"tl": "Ang kalabaw ay isang hayop na kumakain ng damo, kaya ito ay tinatawag na herbivore o halamang-kumakain.", "en": "The carabao is an animal that eats grass, so it is called a herbivore, or plant-eater.", "bis": "Ang kalabaw usa ka mananap nga mokaon ug sagbot, busa gitawag kini nga herbivore o tanom-kaon."}, "source": "AAAS Benchmarks; DepEd G3 Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "carabao-cart-pull-single-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "carabao pulling cart force", "grades": [3, 4, 5], "terms": ["carabao", "kalabaw", "kariton", "hila", "puwersa", "paggalaw", "hatak", "pull", "force", "kariton hinihila", "kusog", "pagbira", "kariton gibira", "puwersa sa pagbira"], "fact": {"tl": "Kapag hinihila ng kalabaw ang kariton, gumagamit ito ng puwersa na nagpapagalaw sa kariton pasulong.", "en": "When a carabao pulls a cart, it uses force that makes the cart move forward.", "bis": "Kon birahon sa kalabaw ang kariton, mogamit kini ug puwersa nga makapalihok sa kariton pasulong."}, "source": "NRC PS2.A; DepEd G4 Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "carbohydrate-energy-foods-g6", "domain": "LIVING_THINGS", "topic": "carbohydrates energy food", "grades": [5, 6, 7], "terms": ["carbohydrate", "karbohaydreyt", "kanin", "tinapay", "enerhiya", "pinagkukunan ng lakas", "pagkain", "bigas", "energy", "rice", "bread", "kusog gikan sa pagkaon", "kan-on", "kalan-on nga makahatag ug kusog"], "fact": {"tl": "Ang mga carbohydrate na makikita sa kanin at tinapay ay ang pangunahing pinagkukunan ng enerhiya ng katawan.", "en": "Carbohydrates, found in foods like rice and bread, are the body's main source of energy.", "bis": "Ang mga carbohydrate nga makit-an sa kan-on ug tinapay mao ang nag-unang tuboran sa kusog sa lawas."}, "source": "encyclopedia-stable consensus; DepEd Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "carpenter-ant-large-g5", "domain": "LIVING_THINGS", "topic": "carpenter ant wood nesting", "grades": [5, 6], "terms": ["carpenter ant", "langgam", "malaking langgam", "kahoy", "nangunguya sa kahoy", "kolonya", "insekto", "wood", "ant", "dako nga hulmigas", "hulmigas sa kahoy", "namuyo sa kahoy"], "fact": {"tl": "Ang carpenter ant ay isang malaking langgam na gumagawa ng kanyang pugad sa loob ng kahoy sa pamamagitan ng paghuhukay nito.", "en": "The carpenter ant is a large ant that makes its nest inside wood by tunneling through it.", "bis": "Ang carpenter ant usa ka dako nga hulmigas nga maghimo sa iyang salag sulod sa kahoy pinaagi sa pagkalot niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "carpenter-bee-bubuyog-itim-g5", "domain": "LIVING_THINGS", "topic": "carpenter bee pollinator wood", "grades": [5, 6], "terms": ["carpenter bee", "bubuyog", "itim na bubuyog", "bubuyog na itim", "kahoy", "pollinator", "bulaklak", "namumugad sa kahoy", "bee", "itom nga bubuyog", "putyukan", "namuyo sa kahoy", "tigpabunga"], "fact": {"tl": "Ang carpenter bee ay isang malaki at madalas itim na bubuyog na gumagawa ng pugad sa kahoy at tumutulong sa pagpopolinasyon ng mga bulaklak.", "en": "The carpenter bee is a large, often black bee that nests in wood and helps pollinate flowers.", "bis": "Ang carpenter bee usa ka dako ug sagad itom nga bubuyog nga magsalag sa kahoy ug motabang sa pagpabunga sa mga bulak."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cassava-kamoteng-kahoy-g5", "domain": "LIVING_THINGS", "topic": "cassava root crop food", "grades": [4, 5, 6], "terms": ["cassava", "kamoteng kahoy", "balinghoy", "ugat", "halamang-ugat", "almirol", "pagkain", "lupa", "root crop", "starch", "balanghoy", "gamot nga kalan-on", "tanom nga ugat", "kamoteng-kahoy"], "fact": {"tl": "Ang kamoteng kahoy o cassava ay isang halamang-ugat na sagana sa almirol at niluluto bilang pagkain sa maraming bahagi ng Pilipinas.", "en": "Cassava is a starchy root crop that is cooked as food in many parts of the Philippines.", "bis": "Ang balanghoy o cassava usa ka tanom nga ugat nga daghan ug almirol ug lutoon isip pagkaon sa daghang bahin sa Pilipinas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "carp-karpa-g5", "domain": "LIVING_THINGS", "topic": "carp freshwater fish", "grades": [4, 5, 6], "terms": ["carp", "karpa", "isda", "tubig-tabang", "ilog", "lawa", "freshwater fish", "pinapalaki sa palaisdaan", "isda sa tubig-tabang", "isda sa suba", "pond fish", "tubig-tab-ang"], "fact": {"tl": "Ang karpa o carp ay isang isda sa tubig-tabang na nakatira sa mga ilog at lawa at madalas palakihin sa palaisdaan bilang pagkain.", "en": "The carp is a freshwater fish that lives in rivers and lakes and is often raised in fishponds for food.", "bis": "Ang karpa o carp usa ka isda sa tubig-tab-ang nga nagpuyo sa mga suba ug linaw ug sagad alimahan sa pondahan isip pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cattle-egret-carabao-symbiosis-g6", "domain": "LIVING_THINGS", "topic": "cattle egret and carabao symbiosis", "grades": [6, 7, 8], "terms": ["cattle egret", "tagak", "kalabaw", "insekto", "symbiosis", "magkatuwang", "kumakain ng insekto", "egret", "carabao", "mutualism", "tagak nga puti", "tinabangay sa mananap", "pagtinabangay"], "fact": {"tl": "Ang puting tagak ay madalas sumama sa kalabaw upang kainin ang mga insektong nagugulo nito, kaya pareho silang nakikinabang sa ganitong ugnayan.", "en": "The white cattle egret often follows a carabao to eat the insects it stirs up, so both animals benefit from this relationship.", "bis": "Ang puti nga tagak sagad mosunod sa kalabaw aron kan-on ang mga insekto nga ginatay-og niini, busa silang duha makabenepisyo niini nga relasyon."}, "source": "encyclopedia-stable consensus; NRC LS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "cave-swiftlet-colony-scene-g6", "domain": "LIVING_THINGS", "topic": "cave swiftlet echolocation nests", "grades": [6, 7, 8], "terms": ["swiftlet", "balinsasayaw", "kuweba", "pugad", "echolocation", "tunog", "kolonya", "ibon", "lumilipad sa dilim", "cave bird", "nest", "langgam sa langub", "salag sa langub", "tunog aron makakita"], "fact": {"tl": "Ang balinsasayaw ay isang ibon na naninirahan sa madilim na kuweba at gumagamit ng tunog (echolocation) upang makapaglakbay sa dilim.", "en": "The cave swiftlet is a bird that lives in dark caves and uses sound (echolocation) to find its way in the dark.", "bis": "Ang balinsasayaw usa ka langgam nga nagpuyo sa ngitngit nga langub ug naggamit ug tunog (echolocation) aron makalihok sa kangitngit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cell-comparison-g7", "domain": "LIVING_THINGS", "topic": "plant cell versus animal cell", "grades": [7, 8], "terms": ["cell", "selula", "halaman", "hayop", "cell wall", "pader ng selula", "chloroplast", "pagkakaiba ng selula", "plant cell", "animal cell", "selula sa tanom", "selula sa mananap", "bungbong sa selula", "pagkalahi sa selula"], "fact": {"tl": "Ang selula ng halaman ay may matigas na cell wall at chloroplast na wala sa selula ng hayop, kaya magkaiba ang anyo ng dalawa.", "en": "A plant cell has a stiff cell wall and chloroplasts that an animal cell does not have, so the two look different.", "bis": "Ang selula sa tanom may gahi nga cell wall ug chloroplast nga wala sa selula sa mananap, busa lahi ang panagway sa duha."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "catfish-hito-g4", "domain": "LIVING_THINGS", "topic": "catfish whiskers freshwater", "grades": [4, 5, 6], "terms": ["catfish", "hito", "isda", "bigote", "barbel", "putik", "tubig-tabang", "walang kaliskis", "whiskers", "freshwater fish", "isda nga walay himbis", "bungot sa hito", "isda sa lapok"], "fact": {"tl": "Ang hito ay isang isda sa tubig-tabang na may mga bigote (barbel) na ginagamit nitong panghanap ng pagkain sa maputik na ilalim.", "en": "The catfish is a freshwater fish with whisker-like barbels that it uses to find food along the muddy bottom.", "bis": "Ang hito usa ka isda sa tubig-tab-ang nga may mga bungot (barbel) nga gigamit niini sa pagpangita ug pagkaon sa lapok nga ilalom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "champaca-tree-flower-g5", "domain": "LIVING_THINGS", "topic": "champaca fragrant flowering tree", "grades": [5, 6], "terms": ["champaca", "tsampaka", "tsampakang puno", "mabango", "bulaklak", "puno", "dilaw na bulaklak", "fragrant", "tree", "halaman", "humot nga bulak", "kahoy nga namulak", "tanom nga mahumot"], "fact": {"tl": "Ang tsampaka ay isang puno na kilalang-kilala sa kanyang mababango at dilaw o kremang bulaklak.", "en": "The champaca is a tree well known for its very fragrant yellow or cream-colored flowers.", "bis": "Ang champaca usa ka kahoy nga ilado sa iyang humot kaayo nga dalag o kremang bulak."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "chameleon-bunglon-forest-g5", "domain": "LIVING_THINGS", "topic": "chameleon color change camouflage", "grades": [5, 6, 7], "terms": ["chameleon", "bunglon", "hayop", "kulay", "nagbabago ng kulay", "kamuflahe", "nagtatago", "reptilya", "color change", "camouflage", "tabili", "nag-usab ug kolor", "pagtago", "lizard"], "fact": {"tl": "Ang bunglon o chameleon ay isang reptilyang kayang baguhin ang kulay ng balat nito upang magtago o ipahayag ang kanyang kalagayan.", "en": "The chameleon is a reptile that can change the color of its skin to blend in or show how it feels.", "bis": "Ang chameleon usa ka reptilya nga makahimo sa pag-usab sa kolor sa iyang panit aron motago o mopakita sa iyang gibati."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cellular-respiration-simple-g7", "domain": "LIVING_THINGS", "topic": "cellular respiration energy release", "grades": [7, 8, 9], "terms": ["cellular respiration", "selular na respirasyon", "oxygen", "pagkain", "enerhiya", "selula", "lakas mula sa pagkain", "hininga ng selula", "energy", "cells", "kusog gikan sa pagkaon", "ginhawa sa selula", "oxygen ug pagkaon"], "fact": {"tl": "Sa cellular respiration, pinagsasama ng selula ang oxygen at pagkain upang makakuha ng enerhiyang gagamitin nito.", "en": "In cellular respiration, cells combine oxygen with food to release the energy they need to work.", "bis": "Sa cellular respiration, ginahiusa sa selula ang oxygen ug pagkaon aron makakuha sa kusog nga gamiton niini."}, "source": "NRC LS1.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "chewing-food-in-mouth-g4", "domain": "LIVING_THINGS", "topic": "chewing mechanical digestion mouth", "grades": [3, 4, 5], "terms": ["chewing", "pagnguya", "bibig", "ngipin", "pagdurog ng pagkain", "panimula ng digestion", "laway", "mouth", "teeth", "digestion", "pag-usap", "pagdugmok sa pagkaon", "laway sa baba", "ngipon"], "fact": {"tl": "Kapag ngumunguya tayo, dinudurog ng ating ngipin ang pagkain sa maliliit na piraso upang madaling matunaw ng katawan.", "en": "When we chew, our teeth break food into smaller pieces so the body can digest it more easily.", "bis": "Kon mag-usap kita, ginadugmok sa atong ngipon ang pagkaon ngadto sa gagmay nga piraso aron sayon nga matunaw sa lawas."}, "source": "NRC LS1.A; DepEd Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "chick-g3", "domain": "LIVING_THINGS", "topic": "chick young chicken life cycle", "grades": [3, 4], "terms": ["chick", "sisiw", "manok", "itlog", "napisa", "anak ng manok", "lumalaki", "buhay na ikot", "young chicken", "egg", "piso", "nipsa", "anak sa manok", "kinabuhi nga libot"], "fact": {"tl": "Ang sisiw ay ang batang manok na napisa mula sa itlog at unti-unting lalaki upang maging ganap na manok.", "en": "A chick is a young chicken that hatched from an egg and will slowly grow into a full-grown chicken.", "bis": "Ang piso mao ang bata nga manok nga napusa gikan sa itlog ug hinay-hinay nga modako aron mahimong hingkod nga manok."}, "source": "AAAS Benchmarks; DepEd G3 Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "cicada-kuliglig-g4", "domain": "LIVING_THINGS", "topic": "cicada loud sound insect", "grades": [4, 5, 6], "terms": ["cicada", "kuliglig", "insekto", "tunog", "maingay", "tag-init", "huni", "puno", "loud sound", "insect", "mananap nga insekto", "saba nga tunog", "tunog sa kahoy"], "fact": {"tl": "Ang kuliglig ay isang insektong kilala sa kanyang malakas na huni na madalas marinig sa mga puno tuwing tag-init.", "en": "The cicada is an insect known for the loud buzzing sound it makes, often heard in trees during hot weather.", "bis": "Ang kuliglig usa ka insekto nga ilado sa iyang kusog nga tunog nga sagad madungog sa mga kahoy panahon sa init."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "chromosome-gene-g8", "domain": "LIVING_THINGS", "topic": "chromosomes and genes heredity", "grades": [8, 9, 10], "terms": ["chromosome", "kromosoma", "gene", "henes", "DNA", "minana", "katangian", "selula", "namamana", "heredity", "kromosom", "panulundon", "gisunod nga kinaiya", "henes sa selula"], "fact": {"tl": "Ang mga kromosoma sa loob ng selula ay binubuo ng mga gene na nagdadala ng mga tagubilin para sa minanang katangian ng isang nilalang.", "en": "Chromosomes inside a cell are made of genes that carry the instructions for a living thing's inherited traits.", "bis": "Ang mga kromosom sulod sa selula gilangkoban sa mga gene nga nagdala sa mga instruksiyon alang sa napanunod nga kinaiya sa usa ka buhi nga binuhat."}, "source": "NRC LS3.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "clam-shell-g4", "domain": "LIVING_THINGS", "topic": "clam two-part protective shell", "grades": [4, 5, 6], "terms": ["clam", "kabibe", "halaan", "kabibi", "talukab", "shell", "dalawang bahagi", "tubig", "mollusk", "two shells", "kinhason", "panit nga gahi", "duha ka bahin nga kabhang", "buhi sa tubig"], "fact": {"tl": "Ang halaan ay isang hayop sa tubig na may dalawang bahaging matigas na talukab na nagbubukas at nagsasara upang protektahan ang malambot nitong katawan.", "en": "A clam is a water animal with a two-part hard shell that opens and closes to protect its soft body.", "bis": "Ang halaan usa ka mananap sa tubig nga may duha ka bahin nga gahi nga kabhang nga moabli ug mosira aron panalipdan ang humok niini nga lawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "chloroplast-organelle-closeup-g7", "domain": "LIVING_THINGS", "topic": "chloroplast photosynthesis organelle", "grades": [7, 8], "terms": ["chloroplast", "kloroplast", "selula ng halaman", "berde", "photosynthesis", "potosintesis", "sikat ng araw", "pagkain ng halaman", "green", "plant cell", "berdeng bahin sa selula", "naghimo ug pagkaon", "kahayag sa adlaw"], "fact": {"tl": "Ang chloroplast ay ang berdeng bahagi ng selula ng halaman kung saan ginagawa ang pagkain mula sa sikat ng araw sa pamamagitan ng photosynthesis.", "en": "The chloroplast is the green part of a plant cell where food is made from sunlight through photosynthesis.", "bis": "Ang chloroplast mao ang berde nga bahin sa selula sa tanom diin gihimo ang pagkaon gikan sa kahayag sa adlaw pinaagi sa photosynthesis."}, "source": "NRC LS1.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "civet-musang-g6", "domain": "LIVING_THINGS", "topic": "civet nocturnal mammal coffee", "grades": [6, 7, 8], "terms": ["civet", "musang", "alamid", "gabi", "nocturnal", "mamalya", "kape", "kapeng alamid", "prutas", "nighttime animal", "mammal", "mananap sa gabii", "mananap nga mogula sa gabii"], "fact": {"tl": "Ang musang o civet ay isang mamalyang aktibo sa gabi na kumakain ng prutas at insekto, at sa Pilipinas ay kilala dahil sa kapeng alamid.", "en": "The civet is a night-active mammal that eats fruit and insects, and in the Philippines it is known for civet coffee (kape alamid).", "bis": "Ang musang o civet usa ka mananap nga aktibo sa gabii nga mokaon ug prutas ug insekto, ug sa Pilipinas ilado kini tungod sa kape nga alamid."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "chico-sapodilla-g5", "domain": "LIVING_THINGS", "topic": "chico sapodilla sweet fruit", "grades": [4, 5, 6], "terms": ["chico", "tsiko", "sapodilla", "prutas", "matamis", "kayumanggi", "buto", "puno", "sweet fruit", "brown", "tam-is nga prutas", "kahoy nga namunga", "prutas nga tabunon"], "fact": {"tl": "Ang tsiko ay isang matamis na prutas na may kayumangging balat at malambot na laman, at tumutubo sa mainit na lugar tulad ng Pilipinas.", "en": "The chico, or sapodilla, is a sweet fruit with brown skin and soft flesh that grows in warm places like the Philippines.", "bis": "Ang tsiko o sapodilla usa ka tam-is nga prutas nga may tabunon nga panit ug humok nga unod, ug motubo sa init nga dapit sama sa Pilipinas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cicada-molt-shell-g5", "domain": "LIVING_THINGS", "topic": "cicada molting shed exoskeleton", "grades": [5, 6, 7], "terms": ["cicada molt", "kuliglig", "balat na natuklap", "molting", "pagpapalit ng balat", "exoskeleton", "insekto", "lumalaki", "shed skin", "molt", "panit nga nataktak", "pag-ilis ug panit", "gawas nga panit"], "fact": {"tl": "Habang lumalaki ang kuliglig, tinatanggal nito ang lumang matigas na balat sa labas (molting) at nag-iiwan ng tila buong balat sa puno.", "en": "As a cicada grows, it sheds its old hard outer skin (molting), leaving behind what looks like an empty shell on a tree.", "bis": "Samtang nagdako ang kuliglig, ginataktak niini ang daan nga gahi nga gawas nga panit (molting), nga magbilin ug daw walay sulod nga panit sa kahoy."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cleaner-wrasse-symbiosis-g6", "domain": "LIVING_THINGS", "topic": "cleaner wrasse mutualism reef fish", "grades": [6, 7, 8], "terms": ["cleaner wrasse", "isda", "naglilinis", "parasito", "malalaking isda", "symbiosis", "mutualism", "bahura", "coral reef", "cleaner fish", "isda nga maglimpyo", "naglinis sa isda", "magtinabangay"], "fact": {"tl": "Ang cleaner wrasse ay isang maliit na isda na naglilinis ng mga parasito sa katawan ng mas malalaking isda, kaya parehong nakikinabang sila.", "en": "The cleaner wrasse is a small fish that eats parasites off the bodies of larger fish, so both fish benefit.", "bis": "Ang cleaner wrasse usa ka gamay nga isda nga maglimpyo sa mga parasito gikan sa lawas sa mas dagkong isda, busa silang duha makabenepisyo."}, "source": "encyclopedia-stable consensus; NRC LS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "clam-tridacna-row-g6", "domain": "LIVING_THINGS", "topic": "giant clam taklobo", "grades": [5, 6, 7], "terms": ["taklobo", "kabibe", "higanteng kabibe", "tridacna", "giant clam", "imbaw", "dako nga kabibe", "shellfish", "talaba", "bivalve", "reef", "bahura"], "fact": {"tl": "Ang taklobo (giant clam) ay ang pinakamalaking kabibe sa mundo na naninirahan sa mababaw na bahura, at nakakakuha ito ng pagkain mula sa maliliit na algae na nakatira sa loob ng kanyang makulay na laman.", "en": "The giant clam (taklobo) is the world's largest bivalve shellfish, living on shallow coral reefs and getting much of its food from tiny algae that live inside its colorful flesh.", "bis": "Ang taklobo (giant clam) mao ang pinakadako nga kabibe sa kalibutan nga nagpuyo sa mabaw nga bahura, ug nagkuha kini ug pagkaon gikan sa gagmay nga algae nga nagpuyo sa sulod sa iyang kolorido nga unod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "clean-fingernails-hygiene-g3", "domain": "LIVING_THINGS", "topic": "handwashing nail hygiene", "grades": [3, 4, 5], "terms": ["kuko", "malinis na kuko", "paghuhugas ng kamay", "kalinisan", "kuko sa tudlo", "hugas kamot", "fingernails", "clean nails", "hygiene", "germs", "mikrobyo", "kagaw"], "fact": {"tl": "Ang pagpapanatiling malinis at maikli ng mga kuko ay nakakatulong na maiwasan ang sakit, dahil sa ilalim ng mahahabang kuko ay madaling magtago ang mga mikrobyo na pwedeng makapasok sa katawan kapag kumain tayo.", "en": "Keeping fingernails clean and short helps prevent illness, because germs easily hide under long nails and can enter the body when we eat with our hands.", "bis": "Ang paghuptan nga limpyo ug mubo sa mga kuko makatabang sa paglikay sa sakit, kay sa ilalom sa taas nga kuko dali nga magtago ang mga kagaw nga makasulod sa lawas kung mokaon ta gamit ang kamot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cleaning-wound-bandage-g4", "domain": "LIVING_THINGS", "topic": "wound care first aid", "grades": [3, 4, 5, 6], "terms": ["sugat", "paglilinis ng sugat", "benda", "bendahe", "first aid", "wound", "bandage", "samad", "pagbendahe", "tubig at sabon", "germs", "impeksyon", "kagaw"], "fact": {"tl": "Kapag nasugatan, dapat hugasan ang sugat ng malinis na tubig at takpan ng malinis na benda upang hindi makapasok ang mga mikrobyo at maiwasan ang impeksyon.", "en": "When you get a cut, you should wash the wound with clean water and cover it with a clean bandage to keep germs out and prevent infection.", "bis": "Kung masamdan, kinahanglan hugasan ang samad ug limpyo nga tubig ug taboni kini ug limpyo nga bendahe aron dili makasulod ang mga kagaw ug malikayan ang impeksyon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "coastal-dune-vegetation-g6", "domain": "LIVING_THINGS", "topic": "coastal dune plants", "grades": [5, 6, 7], "terms": ["buhangin", "tabing-dagat", "halaman sa baybayin", "coastal dune", "beach plants", "dune vegetation", "baybayon", "balas", "tanom sa baybayon", "ugat", "gamot", "erosion", "pagguho"], "fact": {"tl": "Ang mga halamang tumutubo sa buhanginan sa tabing-dagat ay may mahahabang ugat na humahawak sa buhangin, kaya't pinipigilan nila ang pagguho ng baybayin tuwing may malakas na hangin at alon.", "en": "Plants that grow on sandy coastal dunes have long, spreading roots that hold the sand in place, so they help stop the shore from washing away during strong winds and waves.", "bis": "Ang mga tanom nga motubo sa balas sa baybayon adunay tag-as nga gamot nga maghupot sa balas, mao nga makapugong sila sa pag-anod sa baybayon kung kusog ang hangin ug balod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cloud-forest-mossy-g7", "domain": "LIVING_THINGS", "topic": "cloud forest mossy forest", "grades": [6, 7, 8], "terms": ["cloud forest", "mossy forest", "kagubatang maulap", "lumot", "kakahuyan", "ulap", "gubat nga lumot", "panganod", "moss", "humid", "halumigmig", "bundok", "bukid"], "fact": {"tl": "Ang mossy o cloud forest ay matatagpuan sa matataas na bahagi ng bundok kung saan palaging maulap at mahalumigmig, kaya't napupuno ng makapal na lumot ang mga puno at lupa.", "en": "A mossy or cloud forest grows high on mountains where it is almost always misty and damp, so thick moss covers the trees and ground.", "bis": "Ang mossy o cloud forest makit-an sa habog nga bahin sa bukid diin kanunay panganod ug umog, mao nga baga ang lumot nga motabon sa mga kahoy ug yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "climbing-perch-martiniko-g6", "domain": "LIVING_THINGS", "topic": "climbing perch fish", "grades": [5, 6, 7], "terms": ["martiniko", "puyo", "climbing perch", "Anabas", "isda", "isdang nakakalakad", "puyo isda", "freshwater fish", "hangin", "labyrinth organ", "huminga ng hangin", "tubig-tabang", "tab-ang"], "fact": {"tl": "Ang martiniko o puyo ay isang isdang tubig-tabang na may natatanging organ na nagbibigay-daan dito na huminga ng hangin, kaya kaya nitong mabuhay sa lupa nang ilang oras at gumapang patungo sa ibang tubig.", "en": "The climbing perch (martiniko) is a freshwater fish with a special breathing organ that lets it gulp air, so it can survive out of water for hours and even wriggle over land to another pond.", "bis": "Ang puyo o climbing perch usa ka isda sa tab-ang nga tubig nga adunay pinasahi nga organ nga makatabang niini sa pagginhawa ug hangin, mao nga makabuhi kini sa yuta sulod sa pipila ka oras ug makakamang ngadto sa laing tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "club-moss-g7", "domain": "LIVING_THINGS", "topic": "club moss spores", "grades": [6, 7, 8], "terms": ["club moss", "Lycopodium", "halamang walang bulaklak", "spore", "espora", "lumot", "pako", "tanom nga walay bulak", "primitive plant", "liso", "sinaunang halaman", "fern ally"], "fact": {"tl": "Ang club moss ay isang sinaunang uri ng halaman na walang bulaklak o buto, sa halip ay dumarami ito sa pamamagitan ng maliliit na espora na parang alikabok.", "en": "Club moss is an ancient kind of plant that has no flowers or seeds; instead it reproduces using tiny, dust-like spores.", "bis": "Ang club moss usa ka karaan nga matang sa tanom nga walay bulak o liso, kondili nagdaghan kini pinaagi sa gagmay nga espora nga morag abog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cloud-rat-bag-ing-g6", "domain": "LIVING_THINGS", "topic": "Philippine cloud rat", "grades": [5, 6, 7], "terms": ["cloud rat", "bag-ing", "giant cloud rat", "Phloeomys", "daga", "ilagang punong-kahoy", "ilaga", "endemic", "katutubo", "Luzon", "balahibo", "endemiko", "nocturnal", "gabi"], "fact": {"tl": "Ang giant cloud rat o bag-ing ay isang malaking dagang mabalahibo na endemiko sa Pilipinas, naninirahan ito sa mga puno ng kagubatan sa Luzon at gabi lamang lumalabas para kumain ng dahon at bunga.", "en": "The giant cloud rat (bag-ing) is a large, furry rat found only in the Philippines, living in forest trees on Luzon and coming out at night to eat leaves and fruit.", "bis": "Ang giant cloud rat o bag-ing usa ka dako nga balahiboon nga ilaga nga endemiko sa Pilipinas, nagpuyo kini sa mga kahoy sa kalasangan sa Luzon ug mogawas lang sa gabii aron mokaon ug dahon ug bunga."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cockroach-ipis-g4", "domain": "LIVING_THINGS", "topic": "cockroach insect", "grades": [3, 4, 5, 6], "terms": ["ipis", "cockroach", "insekto", "kulisap", "anim na paa", "uok", "insecto", "antena", "scavenger", "germs", "mikrobyo", "kagaw", "gabi", "nocturnal"], "fact": {"tl": "Ang ipis ay isang insekto na may anim na paa at dalawang mahabang antena, at mahilig itong lumabas sa gabi para kumain ng mga tira-tirang pagkain at basura.", "en": "A cockroach is an insect with six legs and two long antennae, and it likes to come out at night to feed on food scraps and waste.", "bis": "Ang uok o ipis usa ka insekto nga adunay unom ka tiil ug duha ka taas nga antena, ug ganahan kini mogawas sa gabii aron mokaon sa mga salin nga pagkaon ug basura."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cobra-ulupong-hood-g6", "domain": "LIVING_THINGS", "topic": "cobra snake hood venom", "grades": [5, 6, 7, 8], "terms": ["cobra", "ulupong", "ahas", "kamandag", "hood", "halas", "naga", "venom", "lala", "leeg", "liog", "Philippine cobra", "kapa"], "fact": {"tl": "Ang cobra (ulupong) ay isang ahas na may kamandag na nakakapagpalaki ng balat sa leeg nito na parang kapa kapag nababalisa, bilang babala sa mga banta.", "en": "The cobra (ulupong) is a venomous snake that can spread the skin of its neck into a wide hood when alarmed, as a warning to threats.", "bis": "Ang cobra (ulupong) usa ka halas nga adunay lala nga makapadako sa panit sa iyang liog nga morag kapa kung mabalaka, isip pasidaan sa mga hulga."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cogon-grassland-scene-g6", "domain": "LIVING_THINGS", "topic": "cogon grass grassland", "grades": [5, 6, 7], "terms": ["cogon", "kugon", "damo", "talahib", "grassland", "cogon grass", "Imperata", "sagbot", "balili", "ugat", "sunog", "fire", "fast-growing", "mabilis tumubo"], "fact": {"tl": "Ang cogon ay isang matigas na damo na mabilis tumubo sa mga bukas at maaraw na lupa, at madali itong dumami pagkatapos ng sunog dahil nakaligtas ang mga ugat nito sa ilalim ng lupa.", "en": "Cogon is a tough grass that grows quickly on open, sunny land, and it spreads easily after a fire because its roots survive underground.", "bis": "Ang kugon usa ka gahi nga sagbot nga paspas motubo sa abli ug init nga yuta, ug dali kini modaghan human sa sunog kay maluwas ang mga gamot niini ilalom sa yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "common-cold-flu-symptoms-g4", "domain": "LIVING_THINGS", "topic": "cold and flu symptoms", "grades": [3, 4, 5, 6], "terms": ["sipon", "trangkaso", "ubo", "lagnat", "common cold", "flu", "sip-on", "virus", "bayrus", "sakit", "hilanat", "fever", "cough", "sneeze", "bahing"], "fact": {"tl": "Ang sipon at trangkaso ay dulot ng mga virus, at ang mga karaniwang sintomas nito ay ubo, bahing, baradong ilong, at minsan lagnat.", "en": "The common cold and flu are caused by viruses, and their usual symptoms include coughing, sneezing, a stuffy nose, and sometimes fever.", "bis": "Ang sip-on ug trangkaso gipahinabo sa mga virus, ug ang kasagaran nga simtomas niini mao ang ubo, bahaon, baradong ilong, ug usahay hilanat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "coconut-palm-form-g4", "domain": "LIVING_THINGS", "topic": "coconut palm tree", "grades": [3, 4, 5, 6], "terms": ["niyog", "puno ng niyog", "coconut", "coconut palm", "lubi", "buko", "kahoy nga lubi", "palma", "tree of life", "puno ng buhay", "copra", "tabing-dagat"], "fact": {"tl": "Ang puno ng niyog ay isang matangkad na palma na tumutubo malapit sa dagat, at tinatawag itong 'tree of life' dahil halos lahat ng bahagi nito—prutas, dahon, tangkay, at ugat—ay may pakinabang sa tao.", "en": "The coconut palm is a tall tree that grows near the sea, and it is called the 'tree of life' because nearly every part—fruit, leaves, trunk, and roots—is useful to people.", "bis": "Ang puno sa lubi usa ka taas nga palma nga motubo duol sa dagat, ug gitawag kini nga 'tree of life' kay halos tanan nga bahin niini—bunga, dahon, punoan, ug gamot—mapuslan sa tawo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "coffee-cherry-branch-g5", "domain": "LIVING_THINGS", "topic": "coffee plant cherry bean", "grades": [4, 5, 6, 7], "terms": ["kape", "bunga ng kape", "coffee cherry", "coffee bean", "kapeng halaman", "buto ng kape", "kape nga tanom", "liso sa kape", "Arabica", "Robusta", "hinog", "pula"], "fact": {"tl": "Ang kape ay nagmumula sa maliliit na bungang parang seresa ng halamang kape; kapag hinog na at pula na ang bunga, kinukuha ang mga buto sa loob nito na siyang inihahaw at ginigiling para gawing kape.", "en": "Coffee comes from the small, cherry-like fruit of the coffee plant; when the fruit ripens and turns red, the seeds inside are taken out, roasted, and ground to make coffee.", "bis": "Ang kape gikan sa gagmay nga bunga sa tanom nga kape nga morag seresa; kung mahinog ug mapula na ang bunga, kuhaon ang mga liso sa sulod niini nga gilanggaw ug gigaling aron mahimong kape."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "coastal-mudflat-scene-g6", "domain": "LIVING_THINGS", "topic": "mudflat tidal habitat", "grades": [5, 6, 7], "terms": ["putikan", "mudflat", "tabing-dagat", "lusak", "lapok", "kati ng tubig", "low tide", "alimango", "talaba", "shorebirds", "langgam sa baybayon", "putik", "hubas"], "fact": {"tl": "Ang putikan o mudflat ay ang malambot na lupang nalalantad kapag kati ang tubig-dagat, at ito ay mayamang pinagkukunan ng pagkain ng mga alimango, talaba, at mga ibong-baybay.", "en": "A mudflat is the soft, muddy ground that is exposed when the tide goes out, and it is a rich feeding place for crabs, clams, and shorebirds.", "bis": "Ang putikan o mudflat mao ang humok nga lapok nga yuta nga makita kung mohubas ang dagat, ug usa kini ka dato nga tinubdan sa pagkaon sa mga alimango, talaba, ug mga langgam sa baybayon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cooling-down-after-exercise-g5", "domain": "LIVING_THINGS", "topic": "cool down after exercise", "grades": [4, 5, 6, 7], "terms": ["ehersisyo", "pagpapalamig", "cool down", "cooling down", "exercise", "pahinga", "tibok ng puso", "pag-inat", "stretching", "heart rate", "pitik sa kasingkasing", "lawas"], "fact": {"tl": "Pagkatapos mag-ehersisyo, mahalaga ang dahan-dahang pagpapalamig ng katawan sa pamamagitan ng mabagal na paglakad at pag-uunat, upang unti-unting bumagal ang tibok ng puso at hindi mahilo.", "en": "After exercising, it is important to cool down with slow walking and gentle stretching so the heartbeat slows gradually and you do not feel dizzy.", "bis": "Human magpa-ehersisyo, importante ang hinay-hinay nga pagpabugnaw sa lawas pinaagi sa hinay nga paglakaw ug pag-inat, aron hinay-hinay nga mohinay ang pitik sa kasingkasing ug dili malipong."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "compost-pile-cross-section-g6", "domain": "LIVING_THINGS", "topic": "composting decomposition", "grades": [4, 5, 6, 7], "terms": ["kompost", "compost", "agnas", "pagkabulok", "decomposition", "organikong basura", "abono", "decomposer", "bulate", "mikrobyo", "ulod", "pampataba", "dunot"], "fact": {"tl": "Ang compost ay nabubuong likas na pataba kapag ang mga tirang gulay, dahon, at iba pang organikong basura ay binubulok ng mga mikrobyo at bulate, na nagiging mayamang lupa para sa mga halaman.", "en": "Compost forms when food scraps, leaves, and other organic waste are broken down by microbes and worms, turning into rich soil that feeds plants.", "bis": "Ang compost mahimo nga natural nga abono kung ang mga salin nga utanon, dahon, ug uban pang organikong basura dunoton sa mga mikrobyo ug ulod, nga mahimong dato nga yuta para sa mga tanom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "common-cold-symptoms-g3", "domain": "LIVING_THINGS", "topic": "common cold prevention", "grades": [3, 4, 5], "terms": ["sipon", "common cold", "baradong ilong", "bahing", "pag-iwas sa sipon", "sip-on", "ilong", "hugas kamot", "virus", "bayrus", "takip ng bibig", "tabon sa baba"], "fact": {"tl": "Ang sipon ay madaling kumakalat mula sa isang tao patungo sa iba, kaya't ang pagtatakip ng bibig kapag umuubo o bumabahing at madalas na paghuhugas ng kamay ay nakakatulong para hindi ito kumalat.", "en": "A cold spreads easily from person to person, so covering your mouth when you cough or sneeze and washing your hands often help keep it from spreading.", "bis": "Ang sip-on dali ra mokatap gikan sa usa ka tawo ngadto sa uban, mao nga ang pagtabon sa baba kung mag-ubo o magbahaon ug ang kanunay nga paghugas sa kamot makatabang aron dili kini mokatap."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "conservation-marine-protected-area-g7", "domain": "LIVING_THINGS", "topic": "marine protected area conservation", "grades": [6, 7, 8, 9], "terms": ["marine protected area", "MPA", "pangangalaga sa dagat", "santuwaryo ng isda", "bahura", "fish sanctuary", "panalipod sa dagat", "isda", "coral reef", "korales", "no-fishing zone", "pagdami ng isda"], "fact": {"tl": "Ang marine protected area ay isang bahagi ng dagat kung saan ipinagbabawal o nililimitahan ang pangingisda, upang makapagpahinga at makadami muli ang mga isda, korales, at iba pang buhay-dagat.", "en": "A marine protected area is a part of the sea where fishing is banned or limited so that fish, corals, and other sea life can rest and grow in number again.", "bis": "Ang marine protected area usa ka bahin sa dagat diin gidili o gilimitahan ang pagpangisda, aron makapahuway ug makadaghan pag-usab ang mga isda, korales, ug uban pang kinabuhi sa dagat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "compost-bottle-decomposition-g5", "domain": "LIVING_THINGS", "topic": "compost bottle experiment", "grades": [4, 5, 6], "terms": ["compost bottle", "boteng kompost", "pagkabulok", "decomposition", "obserbasyon", "botelya", "dunot", "mikrobyo", "decomposer", "experiment", "eksperimento", "organikong basura"], "fact": {"tl": "Sa isang compost bottle, makikita natin kung paano dahan-dahang nabubulok ang mga tirang gulay at dahon sa loob ng plastik na bote, na nagpapakita kung paano binabalik ng kalikasan ang basura sa lupa.", "en": "In a compost bottle, we can watch food scraps and leaves slowly rot inside a plastic bottle, showing how nature turns waste back into soil.", "bis": "Sa usa ka compost bottle, makita nato kung giunsa hinay-hinay nga pagkadunot sa mga salin nga utanon ug dahon sulod sa plastik nga botelya, nga nagpakita kung giunsa pagbalik sa kinaiyahan ang basura ngadto sa yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "community-urban-garden-scene-g5", "domain": "LIVING_THINGS", "topic": "urban community garden", "grades": [4, 5, 6, 7], "terms": ["hardin", "urban garden", "community garden", "gulayan", "tanim sa lungsod", "halamanan", "pananim", "gulay", "lungsod", "vegetables", "siyudad", "tanom"], "fact": {"tl": "Ang community o urban garden ay isang lugar sa lungsod kung saan magkakasamang nagtatanim ng gulay at halaman ang mga residente, na nagbibigay ng sariwang pagkain at mas malinis na hangin sa siyudad.", "en": "A community or urban garden is a place in the city where residents grow vegetables and plants together, providing fresh food and cleaner air for the city.", "bis": "Ang community o urban garden usa ka lugar sa siyudad diin ang mga residente nagtanom ug utanon ug tanom nga dungan, nga naghatag ug presko nga pagkaon ug mas limpyo nga hangin sa siyudad."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "conservation-mangrove-planting-g6", "domain": "LIVING_THINGS", "topic": "mangrove planting conservation", "grades": [5, 6, 7, 8], "terms": ["bakawan", "mangrove", "pagtatanim ng bakawan", "mangrove planting", "tabing-dagat", "bakhaw", "pagtanom ug bakhaw", "ugat", "bagyo", "alon", "balod", "hipon", "pasayan"], "fact": {"tl": "Ang pagtatanim ng bakawan sa tabing-dagat ay tumutulong na protektahan ang baybayin mula sa malalaking alon at bagyo, at nagsisilbing tirahan at lugar-pagpaparami ng maraming isda at hipon.", "en": "Planting mangroves along the coast helps protect the shore from big waves and storms, and gives many fish and shrimp a place to live and breed.", "bis": "Ang pagtanom ug bakhaw sa baybayon makatabang sa pagpanalipod sa baybayon gikan sa dagkong balod ug bagyo, ug nahimong puy-anan ug katuboan sa daghang isda ug pasayan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "coral-reef-fishing-community-g6", "domain": "LIVING_THINGS", "topic": "coral reef fishing livelihood", "grades": [5, 6, 7, 8], "terms": ["bahura", "coral reef", "mangingisda", "pangisda", "komunidad", "reef fishing", "isda", "kabuhayan", "mananagat", "panginabuhian", "fishing community", "pagkain", "pagkaon"], "fact": {"tl": "Ang mga bahura ay nagbibigay ng pagkain at kabuhayan sa maraming pamayanan sa baybayin, dahil tahanan ito ng libu-libong isda, kaya mahalagang pangalagaan ito upang hindi maubos ang huli.", "en": "Coral reefs provide food and livelihood for many coastal communities because they are home to thousands of fish, so they must be cared for to keep the catch from running out.", "bis": "Ang mga bahura naghatag ug pagkaon ug panginabuhian sa daghang komunidad sa baybayon, kay puy-anan kini sa liboan ka isda, mao nga importante kining bantayan aron dili mahurot ang kuha."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "coral-polyp-zooxanthellae-symbiosis-g8", "domain": "LIVING_THINGS", "topic": "coral polyp algae symbiosis", "grades": [7, 8, 9, 10], "terms": ["coral polyp", "korales", "zooxanthellae", "algae", "symbiosis", "simbiyosis", "bahura", "polyp", "tinabangay", "photosynthesis", "kolor", "coral bleaching"], "fact": {"tl": "Ang bawat coral polyp ay may tinitirhang maliliit na algae na tinatawag na zooxanthellae sa loob nito; ang algae ang nagbibigay ng pagkain at kulay sa coral sa pamamagitan ng photosynthesis, habang ang coral naman ang nagbibigay ng tirahan at proteksyon.", "en": "Each coral polyp hosts tiny algae called zooxanthellae inside it; the algae make food and give the coral its color through photosynthesis, while the coral gives the algae a safe home.", "bis": "Ang matag coral polyp adunay gagmay nga algae nga gitawag zooxanthellae sa sulod niini; ang algae maghimo ug pagkaon ug maghatag ug kolor sa coral pinaagi sa photosynthesis, samtang ang coral maghatag ug luwas nga puy-anan sa algae."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cosmos-flower-g4", "domain": "LIVING_THINGS", "topic": "cosmos flower", "grades": [3, 4, 5], "terms": ["cosmos", "bulaklak", "cosmos flower", "talulot", "halaman", "bulak", "petalo", "paru-paro", "bubuyog", "pollinator", "alibangbang", "putyukan"], "fact": {"tl": "Ang cosmos ay isang madaling tumubong bulaklak na may malalapad na talulot na kulay rosas, puti, o lila, at madalas itong dinadalaw ng mga paru-paro at bubuyog na tumutulong sa pagpopolinasyon nito.", "en": "The cosmos is an easy-to-grow flower with broad pink, white, or purple petals, and it is often visited by butterflies and bees that help pollinate it.", "bis": "Ang cosmos usa ka sayon nga patuboon nga bulak nga adunay lapad nga mga petalo nga rosas, puti, o purpura, ug kanunay kini bisitahon sa mga alibangbang ug putyukan nga makatabang sa pagpolinisar niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "covering-water-drum-lid-g4", "domain": "LIVING_THINGS", "topic": "covering water dengue prevention", "grades": [3, 4, 5, 6], "terms": ["takip", "imbak na tubig", "lalagyan ng tubig", "lamok", "dengue", "covering water", "drum", "tabon sa tubig", "sudlanan sa tubig", "mosquito", "itlog ng lamok", "kiti-kiti"], "fact": {"tl": "Ang pagtatakip ng mga lalagyan ng nakaimbak na tubig ay nakakatulong na maiwasan ang dengue, dahil hindi makakapangitlog ang mga lamok sa nakatakip at malinis na tubig.", "en": "Covering containers of stored water helps prevent dengue, because mosquitoes cannot lay their eggs in water that is kept covered and clean.", "bis": "Ang pagtabon sa mga sudlanan sa gitipigan nga tubig makatabang sa paglikay sa dengue, kay dili makapangitlog ang mga lamok sa tubig nga natabonan ug limpyo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "coral-restoration-frames-scene-g7", "domain": "LIVING_THINGS", "topic": "coral restoration reef rehabilitation", "grades": [6, 7, 8, 9], "terms": ["coral restoration", "pagpapanumbalik ng bahura", "coral frames", "rehabilitasyon", "korales", "pagtanom ug korales", "bahura", "reef restoration", "fragments", "transplant", "ilalom sa dagat", "pagpataba sa bahura"], "fact": {"tl": "Sa coral restoration, ang maliliit na piraso ng buhay na coral ay ikinakabit sa mga bakal o semento na frame sa ilalim ng dagat upang muli silang tumubo at maibalik ang nasirang bahura.", "en": "In coral restoration, small pieces of living coral are attached to metal or cement frames underwater so they can grow again and rebuild a damaged reef.", "bis": "Sa coral restoration, ang gagmay nga piraso sa buhi nga coral ipataod sa puthaw o semento nga frame ilalom sa dagat aron motubo kini pag-usab ug mabalik ang naguba nga bahura."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "crab-molt-soft-shell-g6", "domain": "LIVING_THINGS", "topic": "crab molting exoskeleton", "grades": [5, 6, 7, 8], "terms": ["alimango", "alimasag", "pagbalat", "molting", "soft shell crab", "talukab", "exoskeleton", "panit", "crab molt", "pagbalat sa alimango", "matigas na balat", "paglaki"], "fact": {"tl": "Ang alimango ay may matigas na balat sa labas na tinatawag na exoskeleton, at upang lumaki, kailangan nitong itapon ang lumang balat sa pamamagitan ng pagbabalat, kaya pansamantalang malambot ang bagong balat nito.", "en": "A crab has a hard outer shell called an exoskeleton, and to grow bigger it must shed the old shell by molting, leaving its new shell soft for a short time.", "bis": "Ang alimango adunay gahi nga panit sa gawas nga gitawag exoskeleton, ug aron modako, kinahanglan kini molabay sa daan nga panit pinaagi sa pagpamanit, mao nga humok una ang bag-o niini nga panit sulod sa mubo nga panahon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "countershading-marine-g6", "domain": "LIVING_THINGS", "topic": "countershading camouflage in sea animals", "grades": [5, 6, 7], "terms": ["countershading", "kamuflahe", "pagtatago", "kolor", "itim sa likod", "puti sa ilalim", "isda", "pating", "shark", "tuna", "dagat", "kamuflahe sa dagat", "panagtago", "isda nga kolor", "puti sa ubos", "itom sa taas", "lumba-lumba", "predator", "biktima"], "fact": {"tl": "Maraming isda at hayop sa dagat ang madilim ang likod at maputi ang tiyan, isang kulay na tinatawag na countershading na nagpapahirap sa mga mandaragit na makita sila mula sa itaas o sa ibaba.", "en": "Many fish and sea animals are dark on top and pale underneath, a coloring called countershading that makes them hard for predators to spot from above or below.", "bis": "Daghang isda ug mananap sa dagat ang itom sa likod ug puti sa tiyan, usa ka kolor nga gitawag countershading nga maghimo nga lisod sila makita sa mga manunukob gikan sa taas o ubos."}, "source": "encyclopedia-stable consensus; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "cotton-boll-plant-g5", "domain": "LIVING_THINGS", "topic": "cotton plant and its fiber", "grades": [4, 5, 6], "terms": ["cotton", "bulak", "gapas", "cotton boll", "halamang bulak", "tanom nga gapas", "hibla", "fiber", "tela", "damit", "panapton", "buto", "buhok ng buto", "white fluff", "puti nga balhibo", "sako", "boll"], "fact": {"tl": "Ang halamang bulak ay nagbubunga ng malambot na puting bukol na tinatawag na boll, at ang mahahabang hibla rito ay hinahabi upang gawing tela para sa ating mga damit.", "en": "The cotton plant grows a soft white puff called a boll, and the long fibers inside it are spun into cloth to make our clothes.", "bis": "Ang tanom nga gapas mamunga og humok nga puti nga bukol nga gitawag boll, ug ang taas nga mga hibla niini ginahabol aron mahimong panapton alang sa atong mga sanina."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dama-de-noche-g5", "domain": "LIVING_THINGS", "topic": "dama de noche night-blooming flower", "grades": [4, 5, 6], "terms": ["dama de noche", "bulaklak", "bulak", "gabi", "mabango", "amoy", "namumukadkad sa gabi", "night blooming", "lady of the night", "halaman", "tanom", "humot", "namumulak sa gabii", "fragrant", "pollinator", "gamu-gamo", "moth", "puting bulaklak"], "fact": {"tl": "Ang dama de noche ay isang halaman na ang maliliit na puting bulaklak ay namumukadkad at naglalabas ng matapang na bango tuwing gabi upang akitin ang mga gamu-gamong nagpo-polinasyon.", "en": "Dama de noche is a plant whose small white flowers open and release a strong sweet scent at night to attract the moths that pollinate them.", "bis": "Ang dama de noche usa ka tanom kansang gagmay nga puti nga mga bulak mamukhad ug mogawas og kusog nga humot panahon sa gabii aron makadani sa mga anunugba nga magpolinasyon niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cuttlefish-bagulan-g6", "domain": "LIVING_THINGS", "topic": "cuttlefish color-changing mollusk", "grades": [5, 6, 7], "terms": ["cuttlefish", "bagulan", "nokus", "pusit", "kolor", "nagbabago ng kulay", "camouflage", "kamuflahe", "molusko", "mollusk", "walong braso", "tentacles", "galamay", "dagat", "tinta", "ink", "cuttlebone", "nag-iiba ang kulay", "mag-usab og kolor"], "fact": {"tl": "Ang cuttlefish o bagulan ay isang molusko sa dagat na kayang baguhin ang kulay at himig ng balat nito sa ilang segundo upang magtago o makipag-usap sa kapwa nito.", "en": "The cuttlefish is a sea mollusk that can change the color and pattern of its skin in seconds to hide or to signal to other cuttlefish.", "bis": "Ang cuttlefish o bagulan usa ka molusko sa dagat nga makausab sa kolor ug pattern sa panit niini sulod sa pipila ka segundo aron motago o makigsulti sa ubang cuttlefish."}, "source": "encyclopedia-stable consensus; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "damselfly-tutubi-payat-g5", "domain": "LIVING_THINGS", "topic": "damselfly slender flying insect", "grades": [4, 5, 6], "terms": ["damselfly", "tutubing payat", "tutubi", "alindahaw", "insekto", "kulisap", "pakpak", "wings", "tubig", "lawa", "ilog", "lumilipad", "naglalakbay", "nymph", "uod ng lamok", "ulod sa lamok", "manipis", "payat", "nipis nga lawas", "predator"], "fact": {"tl": "Ang tutubing payat o damselfly ay isang manipis na insektong lumilipad malapit sa tubig, at ang mga anak nito ay lumalaki rin sa ilalim ng tubig kung saan kumakain sila ng maliliit na uod ng lamok.", "en": "The damselfly is a slender flying insect that lives near water, and its young also grow underwater where they eat tiny mosquito larvae.", "bis": "Ang damselfly o nipis nga alindahaw usa ka manipis nga insekto nga molupad duol sa tubig, ug ang mga anak niini motubo usab ilalom sa tubig diin mokaon sila og gagmay nga mga ulod sa lamok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "covering-sneeze-elbow-g3", "domain": "LIVING_THINGS", "topic": "covering a sneeze to stop germs", "grades": [3, 4, 5], "terms": ["sneeze", "bahin", "pagbahin", "siko", "elbow", "germs", "mikrobyo", "kagaw", "sakit", "lamig", "sipon", "ubo", "cough", "pagtakip", "takip sa bahing", "kalusugan", "hygiene", "pagkalat ng sakit", "tabon sa siko"], "fact": {"tl": "Kapag bumabahin tayo, dapat takpan ang bibig at ilong gamit ang siko upang hindi kumalat sa hangin ang mga maliliit na kagaw na nagdadala ng sakit.", "en": "When we sneeze, we should cover our mouth and nose with our elbow so the tiny germs that carry illness do not spread into the air.", "bis": "Kon mobahin kita, kinahanglan tabonan nato ang baba ug ilong gamit ang siko aron dili mokatag sa hangin ang gagmay nga mga kagaw nga nagdala og sakit."}, "source": "encyclopedia-stable consensus; DepEd health/hygiene", "generator": "claude-workflow", "reviewed": false},
  {"id": "cyanobacteria-filament-g7", "domain": "LIVING_THINGS", "topic": "cyanobacteria oxygen-making microbes", "grades": [6, 7, 8], "terms": ["cyanobacteria", "blue-green algae", "lumot na asul-berde", "mikrobyo", "bakterya", "oxygen", "oksiheno", "photosynthesis", "potosintesis", "filament", "tubig", "lawa", "dagat", "sinaunang buhay", "ancient", "tinipon na oksiheno", "nakagagawa ng pagkain", "sinag ng araw"], "fact": {"tl": "Ang cyanobacteria ay napakaliit na bakteryang nakatira sa tubig na gumagawa ng sariling pagkain mula sa sikat ng araw, at sila ang isa sa mga unang nagdagdag ng oksiheno sa hangin ng Daigdig.", "en": "Cyanobacteria are tiny water microbes that make their own food from sunlight, and they were among the first living things to add oxygen to Earth's air.", "bis": "Ang cyanobacteria gagmay kaayo nga bakterya nga nagpuyo sa tubig nga maghimo sa kaugalingong pagkaon gikan sa silaw sa adlaw, ug sila usa sa unang buhi nga nagdugang og oksiheno sa hangin sa Kalibotan."}, "source": "encyclopedia-stable consensus; NRC LS1.C, ESS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "dap-dap-tree-g5", "domain": "LIVING_THINGS", "topic": "dapdap flowering tree", "grades": [4, 5, 6], "terms": ["dapdap", "dap-dap", "coral tree", "Erythrina", "puno", "kahoy", "mapulang bulaklak", "pula nga bulak", "namumulaklak", "bulaklak", "Pilipinas", "katutubo", "native", "bubuyog", "ibon", "nectar", "tag-init", "summer", "red flowers"], "fact": {"tl": "Ang dapdap ay isang katutubong punong namumulaklak ng matingkad na pulang bulaklak tuwing tag-init, at ang nektar nito ay kinakain ng mga ibon at bubuyog.", "en": "The dapdap is a native tree that blooms with bright red flowers in summer, and birds and bees feed on its nectar.", "bis": "Ang dapdap usa ka lumad nga kahoy nga mamulak og hayag nga pula nga mga bulak panahon sa ting-init, ug ang nektar niini ginakaon sa mga langgam ug buyog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "daily-hygiene-routine-g3", "domain": "LIVING_THINGS", "topic": "daily hygiene habits for health", "grades": [3, 4, 5], "terms": ["hygiene", "kalinisan", "kalimpyo", "paghuhugas", "paligo", "ligo", "sipilyo", "brush teeth", "kamay", "hands", "germs", "kagaw", "mikrobyo", "kalusugan", "himsog", "araw-araw", "adlaw-adlaw", "malusog", "sabon", "tubig"], "fact": {"tl": "Ang araw-araw na paghuhugas ng kamay, pagliligo, at pagsisipilyo ng ngipin ay nag-aalis ng mga kagaw sa katawan upang manatili tayong malusog.", "en": "Daily habits like washing hands, bathing, and brushing teeth remove germs from the body and help keep us healthy.", "bis": "Ang adlaw-adlaw nga paghugas sa kamot, pagligo, ug panerepilyo sa ngipon magtangtang sa mga kagaw sa lawas aron magpabilin kitang himsog."}, "source": "encyclopedia-stable consensus; DepEd health/hygiene", "generator": "claude-workflow", "reviewed": false},
  {"id": "digestion-path-simple-g4", "domain": "LIVING_THINGS", "topic": "the path food takes through the body", "grades": [4, 5, 6], "terms": ["digestion", "panunaw", "pagtunaw", "pagkain", "daanan ng pagkain", "bibig", "esophagus", "sikmura", "tiyan", "stomach", "bituka", "intestine", "ginatunaw", "sustansya", "nutrients", "agianan sa pagkaon", "tinunaw nga pagkaon", "katawan"], "fact": {"tl": "Ang pagkain ay dumadaan mula sa bibig patungo sa sikmura at saka sa mahabang bituka, kung saan ito tinutunaw upang makuha ng katawan ang sustansya.", "en": "Food travels from the mouth down to the stomach and then through the long intestines, where it is broken down so the body can take in its nutrients.", "bis": "Ang pagkaon moagi gikan sa baba paingon sa tiyan ug dayon sa taas nga tinai, diin kini matunaw aron makuha sa lawas ang sustansya."}, "source": "NRC LS1.A; DepEd G4-G6 Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "decomposition-log-fungi-g5", "domain": "LIVING_THINGS", "topic": "fungi decomposing fallen logs", "grades": [5, 6, 7], "terms": ["decomposition", "pagkabulok", "pagkadunot", "kabog", "fungi", "kabute", "mushroom", "uhong", "troso", "log", "kahoy na bulok", "decomposer", "nutrients", "sustansya sa lupa", "ginabalik sa yuta", "nutrient cycle", "dunot nga kahoy", "agup-op", "buhok ng halaman"], "fact": {"tl": "Ang mga fungi tulad ng kabute ay sumisira sa mga bulok na troso at dahon, at ibinabalik nito sa lupa ang mga sustansyang magagamit ng mga bagong halaman.", "en": "Fungi such as mushrooms break down rotting logs and leaves, returning nutrients to the soil that new plants can use.", "bis": "Ang mga fungi sama sa uhong magdunot sa mga gadunot nga troso ug dahon, ug ibalik niini sa yuta ang mga sustansya nga magamit sa bag-ong mga tanom."}, "source": "NRC LS2.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "deforestation-before-after-g6", "domain": "EARTH_SPACE", "topic": "deforestation and its effects on land", "grades": [5, 6, 7], "terms": ["deforestation", "pagkakalbo ng gubat", "pagputol ng puno", "kalbo nga lasang", "gubat", "kagubatan", "lasang", "kahoy", "puno", "soil erosion", "pagguho ng lupa", "baha", "flood", "tirahan ng hayop", "habitat", "wildlife", "pagkawala ng gubat", "pagtroso", "logging"], "fact": {"tl": "Ang deforestation ay ang malawakang pagputol ng mga puno sa gubat, at kapag nawala ang mga puno, mas madaling maguho ang lupa at lumakas ang baha.", "en": "Deforestation is the large-scale cutting down of forest trees, and when the trees are gone the soil washes away more easily and floods grow worse.", "bis": "Ang deforestation mao ang dako nga pagputol sa mga kahoy sa lasang, ug kon mawala ang mga kahoy, mas dali na maguba ang yuta ug mokusog ang baha."}, "source": "NRC ESS3.C; DepEd Science environment", "generator": "claude-workflow", "reviewed": false},
  {"id": "diatom-microbe-g7", "domain": "LIVING_THINGS", "topic": "diatoms glass-shelled microalgae", "grades": [6, 7, 8], "terms": ["diatom", "mikrobyo", "microalgae", "lumot na maliit", "plankton", "phytoplankton", "silica", "salamin na kabibe", "shell", "oxygen", "oksiheno", "photosynthesis", "potosintesis", "tubig", "dagat", "lawa", "napakaliit", "gagmay kaayo", "tinapon ng oksiheno", "pagkain sa dagat"], "fact": {"tl": "Ang mga diatom ay napakaliit na halamang-tubig na may matigas na balat na yari sa silica na parang salamin, at sila ay gumagawa ng malaking bahagi ng oksiheno sa hangin.", "en": "Diatoms are tiny water plants with hard glass-like shells made of silica, and together they produce a large share of the oxygen in our air.", "bis": "Ang mga diatom gagmay kaayo nga tanom sa tubig nga adunay gahi nga panit nga sama sa salamin nga hinimo sa silica, ug sila maghimo og dako nga bahin sa oksiheno sa atong hangin."}, "source": "encyclopedia-stable consensus; NRC LS1.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "dna-replication-g9", "domain": "LIVING_THINGS", "topic": "DNA copying before cell division", "grades": [8, 9, 10], "terms": ["DNA", "DNA replication", "pagkopya ng DNA", "kopya sa DNA", "cell division", "paghahati ng selula", "selula", "cell", "double helix", "blueprint", "genetic", "mana", "namamana", "kromosom", "chromosome", "nukleus", "nucleus", "tig-isa nga kopya", "magkapareho"], "fact": {"tl": "Bago maghati ang isang selula, kinokopya muna nito ang buong DNA nito upang ang bawat bagong selula ay magkaroon ng kumpletong set ng parehong tagubilin.", "en": "Before a cell divides, it first copies its entire DNA so that each new cell receives a complete set of the same instructions.", "bis": "Sa dili pa mabahin ang usa ka selula, kopyahon una niini ang tibuok DNA niini aron ang matag bag-ong selula makadawat og kompleto nga set sa managsama nga mga instruksyon."}, "source": "NRC LS1.A, LS3.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "digestive-journey-of-food-g5", "domain": "LIVING_THINGS", "topic": "stages of the digestive journey", "grades": [4, 5, 6], "terms": ["digestive system", "sistema ng panunaw", "panunaw", "pagtunaw", "paglalakbay ng pagkain", "bibig", "mouth", "ngipin", "laway", "saliva", "sikmura", "stomach", "tiyan", "bituka", "intestine", "biyahe sa pagkaon", "ginatunaw", "natunaw", "tinai"], "fact": {"tl": "Ang paglalakbay ng pagkain ay nagsisimula sa bibig kung saan nginunguya at hinahaluan ng laway, bago ito dumaloy sa sikmura at bituka upang lubusang matunaw.", "en": "Food's journey begins in the mouth where it is chewed and mixed with saliva, before flowing into the stomach and intestines to be fully broken down.", "bis": "Ang panaw sa pagkaon magsugod sa baba diin kini usapon ug sagolan og laway, sa dili pa kini moagos paingon sa tiyan ug tinai aron hingpit nga matunaw."}, "source": "NRC LS1.A; DepEd G4-G6 Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "digestive-organs-helpers-g6", "domain": "LIVING_THINGS", "topic": "liver and pancreas as digestion helpers", "grades": [5, 6, 7], "terms": ["digestive organs", "atay", "liver", "pancreas", "lapay", "apdo", "bile", "katas ng panunaw", "digestive juices", "enzyme", "tumutulong sa panunaw", "pagtunaw", "taba", "fat", "sustansya", "katabang sa panunaw", "tabang sa pagtunaw", "tiyan", "bituka"], "fact": {"tl": "Ang atay at pancreas ay mga tagatulong sa panunaw na naglalabas ng katas na bumabasag sa taba at pagkain upang madaling matunaw ng katawan.", "en": "The liver and pancreas are digestion helpers that release juices which break down fats and food so the body can absorb them easily.", "bis": "Ang atay ug pancreas mao ang mga katabang sa panunaw nga mogawas og duga nga magbungkag sa tambok ug pagkaon aron dali masuhop sa lawas."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dental-care-scene-g3", "domain": "LIVING_THINGS", "topic": "brushing teeth to prevent cavities", "grades": [3, 4, 5], "terms": ["dental care", "ngipin", "sipilyo", "toothbrush", "brushing", "paghuhugas ng ngipin", "panepilyo", "cavity", "bulok na ngipin", "uk-ok", "tooth decay", "plaque", "toothpaste", "kalinisan", "kalusugan", "kagaw", "asukal", "limpyo nga ngipon", "araw-araw"], "fact": {"tl": "Ang pagsisipilyo ng ngipin tuwing umaga at gabi ay nag-aalis ng mga kagaw at tira ng pagkain upang hindi mabulok ang ating ngipin.", "en": "Brushing our teeth every morning and night removes germs and bits of food, which helps stop our teeth from decaying.", "bis": "Ang paneripilyo sa ngipon kada buntag ug gabii magtangtang sa mga kagaw ug salin sa pagkaon aron dili madunot ang atong ngipon."}, "source": "encyclopedia-stable consensus; DepEd health/hygiene", "generator": "claude-workflow", "reviewed": false},
  {"id": "dendrobium-orchid-g5", "domain": "LIVING_THINGS", "topic": "dendrobium orchid epiphyte", "grades": [4, 5, 6], "terms": ["dendrobium", "orchid", "orkidya", "orkids", "bulaklak", "bulak", "halaman", "tanom", "epiphyte", "nakadikit sa puno", "tumutubo sa kahoy", "ugat sa hangin", "air roots", "Pilipinas", "tropical", "namumulaklak", "magagandang bulaklak", "namumulak", "sanga ng puno"], "fact": {"tl": "Ang dendrobium ay isang uri ng orkidya na karaniwang tumutubo na nakakapit sa mga sanga ng puno, at sumisipsip ito ng tubig at sustansya mula sa hangin at ulan.", "en": "The dendrobium is a kind of orchid that usually grows clinging to tree branches, taking in water and nutrients from the air and rain.", "bis": "Ang dendrobium usa ka klase sa orkidya nga kasagaran motubo nga nagkapyot sa mga sanga sa kahoy, ug mosuyop kini og tubig ug sustansya gikan sa hangin ug ulan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "digestion-stages-journey-g6", "domain": "LIVING_THINGS", "topic": "mechanical and chemical digestion stages", "grades": [6, 7, 8], "terms": ["digestion stages", "yugto ng panunaw", "mechanical digestion", "chemical digestion", "panunaw", "pagtunaw", "pagnguya", "chewing", "enzyme", "ensaym", "laway", "saliva", "sikmura", "stomach", "asido", "acid", "pisikal na pagdurog", "kemikal na pagbabago", "tinai", "absorption"], "fact": {"tl": "Ang panunaw ay may dalawang paraan: ang mekanikal na pagdurog sa pamamagitan ng pagnguya, at ang kemikal na pagbasag gamit ang mga ensaym at asido sa sikmura.", "en": "Digestion happens in two ways: mechanical breakdown by chewing, and chemical breakdown using enzymes and acid in the stomach.", "bis": "Ang panunaw mahitabo sa duha ka paagi: ang mekanikal nga pagdugmok pinaagi sa pag-usap, ug ang kemikal nga pagbungkag gamit ang mga enzyme ug asido sa tiyan."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "diving-beetle-water-g5", "domain": "LIVING_THINGS", "topic": "diving beetle aquatic insect", "grades": [4, 5, 6], "terms": ["diving beetle", "salagubang sa tubig", "uwang sa tubig", "insekto", "kulisap", "bakukang", "lumalangoy", "naglalangoy", "tubig", "lawa", "pond", "air bubble", "bula ng hangin", "huminga sa ilalim", "predator", "tubigan", "molangoy", "kuto sa tubig", "naghihinga"], "fact": {"tl": "Ang diving beetle ay isang salagubang na naninirahan sa tubig at marunong lumangoy, at nagdadala ito ng bulang hangin sa ilalim ng pakpak upang makahinga habang nasa ilalim ng tubig.", "en": "The diving beetle is a water-living beetle that swims well, carrying a bubble of air under its wings so it can breathe while underwater.", "bis": "Ang diving beetle usa ka bakukang nga nagpuyo sa tubig ug kahibalo molangoy, ug magdala kini og bula sa hangin ilalom sa pako niini aron makaginhawa samtang naa sa ilalom sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dolphin-lumba-lumba-g4", "domain": "LIVING_THINGS", "topic": "dolphin air-breathing sea mammal", "grades": [4, 5, 6], "terms": ["dolphin", "lumba-lumba", "lumod", "dolphin sa dagat", "mammal", "mamalya", "sea mammal", "humihinga ng hangin", "blowhole", "dagat", "matalino", "echolocation", "tunog", "sound", "langoy", "nilalanggoy", "isda nga dili", "nagpapasuso", "hayop sa dagat"], "fact": {"tl": "Ang lumba-lumba ay isang mamalyang naninirahan sa dagat na sumasalpok sa ibabaw ng tubig upang huminga ng hangin sa pamamagitan ng butas sa ulo nito.", "en": "The dolphin is a sea mammal that comes up to the water's surface to breathe air through a blowhole on top of its head.", "bis": "Ang lumba-lumba usa ka mamalya nga nagpuyo sa dagat nga mosulpot sa ibabaw sa tubig aron makaginhawa og hangin pinaagi sa lungag sa ibabaw sa ulo niini."}, "source": "encyclopedia-stable consensus; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "dichotomous-key-branching-g7", "domain": "LIVING_THINGS", "topic": "dichotomous key for identifying organisms", "grades": [6, 7, 8], "terms": ["dichotomous key", "branching key", "susi sa pagkilala", "klasipikasyon", "classification", "pagkakategorya", "dalawang pagpipilian", "yes or no", "katangian", "characteristics", "hayop", "halaman", "pagtukoy", "identifying", "sanga-sanga", "magpili", "pagkilala sa organismo", "pares ng tanong", "sunod-sunod nga pangutana"], "fact": {"tl": "Ang dichotomous key ay isang gabay na may serye ng mga tanong na may dalawang sagot na nagtuturo sa atin upang makilala kung anong hayop o halaman ang nakikita natin.", "en": "A dichotomous key is a guide of paired either-or questions that leads us step by step to identify which animal or plant we are looking at.", "bis": "Ang dichotomous key usa ka giya nga adunay sunod-sunod nga mga pangutana nga adunay duha ka tubag nga maggiya kanato aron mailhan kung unsang hayop o tanom ang atong nakita."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "donkey-asno-g4", "domain": "LIVING_THINGS", "topic": "donkey work animal", "grades": [3, 4, 5], "terms": ["donkey", "asno", "burro", "hayop", "mammal", "mamalya", "pasanin", "work animal", "kabayo", "horse", "pag-aalaga", "tainga", "long ears", "mahabang tainga", "kargada", "load", "matiisin", "mananap", "trabaho", "alaga"], "fact": {"tl": "Ang asno ay isang hayop na kahawig ng kabayo ngunit mas maliit at may mas mahabang tainga, at ginagamit ito ng mga tao upang magbuhat at maghatid ng mabibigat na kargada.", "en": "The donkey is an animal like a small horse with longer ears, and people use it to carry and haul heavy loads.", "bis": "Ang asno usa ka hayop nga sama sa kabayo apan mas gamay ug adunay mas taas nga dalunggan, ug gigamit kini sa mga tawo aron magdala ug magkarga og bug-at nga mga butang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dove-kalapati-g4", "domain": "LIVING_THINGS", "topic": "dove seed-eating bird", "grades": [3, 4, 5], "terms": ["dove", "kalapati", "salampati", "punay", "ibon", "bird", "lumilipad", "pakpak", "wings", "buto", "seeds", "pagkain", "pugad", "nest", "lumipad", "kumakain ng buto", "langgam", "malumo nga huni", "malambing na huni", "cooing"], "fact": {"tl": "Ang kalapati ay isang ibong karaniwang kumakain ng mga buto at butil, at kilala ito sa malambing nitong huni.", "en": "The dove is a bird that mainly eats seeds and grains, and it is known for its soft cooing call.", "bis": "Ang salampati usa ka langgam nga kasagaran mokaon og mga liso ug lugas, ug nailhan kini sa malumo niini nga huni."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "drinking-glass-milk-child-g3", "domain": "LIVING_THINGS", "topic": "milk for strong bones and teeth", "grades": [3, 4, 5], "terms": ["milk", "gatas", "inom", "uminom", "calcium", "kalsyum", "buto", "bones", "ngipin", "teeth", "malakas na buto", "lumalaki", "growth", "sustansya", "nutrients", "pagkain", "himsog", "malusog", "baso", "glass", "lig-on nga bukog"], "fact": {"tl": "Ang gatas ay mayaman sa kalsyum, isang sustansyang tumutulong sa pagpapalakas ng ating mga buto at ngipin habang tayo ay lumalaki.", "en": "Milk is rich in calcium, a nutrient that helps build strong bones and teeth as we grow.", "bis": "Ang gatas dato sa kalsyum, usa ka sustansya nga magtabang sa paglig-on sa atong mga bukog ug ngipon samtang nagdako kita."}, "source": "encyclopedia-stable consensus; DepEd health/nutrition", "generator": "claude-workflow", "reviewed": false},
  {"id": "dugong-grazing-g5", "domain": "LIVING_THINGS", "topic": "dugong seagrass-grazing sea mammal", "grades": [4, 5, 6], "terms": ["dugong", "duyong", "sea cow", "baka ng dagat", "mammal", "mamalya", "seagrass", "damong-dagat", "kumakain ng damo", "dagat", "endangered", "namamatay na species", "Pilipinas", "humihinga ng hangin", "kalmado", "mananap sa dagat", "kumakain ng halaman", "sagbot sa dagat", "mabaw nga tubig"], "fact": {"tl": "Ang dugong o duyong ay isang malaking mamalyang dagat na kumakain ng damong-dagat sa mababaw na tubig, at ito ay isang nanganganib na species sa Pilipinas.", "en": "The dugong is a large sea mammal that grazes on seagrass in shallow water, and it is an endangered species in the Philippines.", "bis": "Ang dugong o duyong usa ka dako nga mamalya sa dagat nga mokaon og sagbot sa dagat sa mabaw nga tubig, ug usa kini ka namiligrong species sa Pilipinas."}, "source": "encyclopedia-stable consensus; DepEd Science PH biodiversity", "generator": "claude-workflow", "reviewed": false},
  {"id": "duhat-java-plum-g4", "domain": "LIVING_THINGS", "topic": "duhat java plum fruit tree", "grades": [3, 4, 5], "terms": ["duhat", "java plum", "lomboy", "black plum", "prutas", "fruit", "bunga", "puno", "kahoy", "tanom", "maitim na bunga", "itom nga bunga", "matamis", "maasim", "namumunga", "tag-init", "summer", "Pilipinas", "katutubong prutas", "berry"], "fact": {"tl": "Ang duhat ay isang katutubong prutas na maliit, maitim, at matamis-maasim, na hinog tuwing tag-init at nag-iiwan ng lila sa dila kapag kinain.", "en": "The duhat is a native fruit that is small, dark purple, and sweet-sour, ripening in summer and staining the tongue purple when eaten.", "bis": "Ang lomboy o duhat usa ka lumad nga prutas nga gamay, itom-lila, ug tam-is-aslom, nga mahinog panahon sa ting-init ug magbilin og lila sa dila kon kan-on."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "durian-fruit-g4", "domain": "LIVING_THINGS", "topic": "durian thorny strong-smelling fruit", "grades": [3, 4, 5], "terms": ["durian", "prutas", "fruit", "bunga", "Davao", "Mindanao", "tinik", "spiny", "matinik nga bunga", "mabaho", "malakas na amoy", "strong smell", "humot", "matamis", "creamy", "balat na matigas", "puno", "katutubo", "hari ng prutas", "king of fruits", "amoy"], "fact": {"tl": "Ang durian ay isang matinik na prutas na sikat sa Davao, na kilala sa malakas nitong amoy ngunit malambot at matamis ang laman sa loob.", "en": "The durian is a thorny fruit famous in Davao, known for its strong smell but soft, sweet flesh inside.", "bis": "Ang durian usa ka tunokon nga prutas nga bantog sa Davao, nailhan sa kusog niini nga baho apan humok ug tam-is ang unod sa sulod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dragonfly-perched-wings-g4", "domain": "LIVING_THINGS", "topic": "dragonfly insect predator", "grades": [3, 4, 5], "terms": ["tutubi", "alindahaw", "alanihaw", "dragonfly", "insekto", "insect", "pakpak", "wings", "lamok", "mosquito", "predator", "insektong lumilipad"], "fact": {"tl": "Ang tutubi ay isang insektong may apat na manipis na pakpak at malalaking mata, at kumakain ito ng lamok at iba pang maliliit na insekto.", "en": "The dragonfly is an insect with four thin wings and large eyes, and it eats mosquitoes and other small insects.", "bis": "Ang alindahaw usa ka insekto nga adunay upat ka nipis nga pako ug dagkong mga mata, ug mokaon kini og lamok ug uban pang gagmay nga insekto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dynamite-fishing-damage-g6", "domain": "LIVING_THINGS", "topic": "dynamite fishing reef damage", "grades": [5, 6, 7, 8], "terms": ["pangingisdang may dinamita", "dynamite fishing", "blast fishing", "pangdadenamita", "bawal", "ipinagbabawal", "coral reef", "bahura", "coral", "nasisira", "makadaot", "destroy", "isda"], "fact": {"tl": "Ang pangingisdang may dinamita ay bawal dahil winawasak nito ang mga bahura na tahanan ng mga isda at pumapatay ng maraming nilalang nang sabay-sabay.", "en": "Dynamite fishing is illegal because the blast destroys coral reefs that are homes to fish and kills many creatures all at once.", "bis": "Ang pagpangisda gamit ang dinamita gidili kay gigun-ob niini ang mga bahura nga puy-anan sa mga isda ug daghang mananap ang mamatay dungan."}, "source": "encyclopedia-stable consensus; DepEd Science environment", "generator": "claude-workflow", "reviewed": false},
  {"id": "drongo-balicassiao-g5", "domain": "LIVING_THINGS", "topic": "drongo bird mimic", "grades": [4, 5, 6], "terms": ["balicassiao", "balikasyaw", "drongo", "ibon", "langgam", "bird", "itim", "black", "buntot", "forked tail", "gumagaya", "mimic", "huni", "kagubatan", "forest"], "fact": {"tl": "Ang balicassiao ay isang maitim na ibon na may hating buntot na karaniwang nakikita sa kagubatan ng Pilipinas, at marunong itong gumaya ng tunog ng ibang ibon.", "en": "The balicassiao is a black drongo bird with a forked tail commonly seen in Philippine forests, and it can mimic the calls of other birds.", "bis": "Ang balicassiao usa ka itom nga langgam nga adunay nahimulag nga ikog nga makita sa kalasangan sa Pilipinas, ug mahibalo kini mosundog sa tingog sa ubang langgam."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ear-parts-diagram-g5", "domain": "LIVING_THINGS", "topic": "ear hearing organ parts", "grades": [4, 5, 6], "terms": ["tainga", "dalunggan", "ear", "pandinig", "hearing", "tunog", "sound", "drum membrane", "eardrum", "bahagi ng tainga", "ear parts", "nakakarinig", "makadungog"], "fact": {"tl": "Ang tainga ang organ na ginagamit natin sa pandinig; pumapasok ang tunog sa labas na bahagi at umuugong sa eardrum upang marinig natin ito.", "en": "The ear is the organ we use for hearing; sound enters the outer part and vibrates the eardrum so we can hear it.", "bis": "Ang dalunggan mao ang organ nga gamiton nato sa pagpaminaw; mosulod ang tingog sa gawas nga bahin ug mokurog sa eardrum aron madungog nato kini."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "duckling-bibe-g3", "domain": "LIVING_THINGS", "topic": "duckling young duck", "grades": [3, 4], "terms": ["bibe", "sisiw ng pato", "duckling", "itik", "pato", "duck", "balahibo", "feathers", "lumalangoy", "swim", "tubig", "water", "bata", "young"], "fact": {"tl": "Ang bibe ay batang pato na may malambot na balahibo, at marunong na itong lumangoy sa tubig ilang araw pa lang matapos mapisa.", "en": "A duckling is a young duck with soft down feathers, and it can already swim in water just days after it hatches.", "bis": "Ang bibe usa ka batan-ong itik nga adunay humok nga balhibo, ug makahibalo na kini molangoy sa tubig pipila lang ka adlaw human mapusa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dragonfruit-pitaya-g5", "domain": "LIVING_THINGS", "topic": "dragon fruit cactus plant", "grades": [4, 5, 6], "terms": ["dragon fruit", "saniata", "pitaya", "cactus", "kaktus", "prutas", "fruit", "pula", "red", "buto", "seeds", "gabi", "night-blooming", "bulaklak", "flower", "halaman"], "fact": {"tl": "Ang dragon fruit ay prutas ng isang uri ng kaktus na umaakyat, may makapal na pulang balat at puti o pulang laman na puno ng maliliit na itim na buto.", "en": "Dragon fruit is the fruit of a climbing cactus, with a thick pink skin and white or red flesh full of tiny black seeds.", "bis": "Ang dragon fruit usa ka prutas sa nagakatkat nga kaktus, adunay baga nga pula nga panit ug puti o pula nga unod nga puno sa gagmayng itom nga liso."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "eight-glasses-water-g4", "domain": "LIVING_THINGS", "topic": "drinking water hydration health", "grades": [3, 4, 5], "terms": ["walong basong tubig", "eight glasses water", "tubig", "water", "uminom", "inom", "drink", "hydration", "katawan", "body", "kalusugan", "health", "nauuhaw", "giuhaw"], "fact": {"tl": "Kailangan nating uminom ng sapat na tubig araw-araw dahil tumutulong ito sa pagtunaw ng pagkain at pagpapanatiling sariwa ng ating katawan.", "en": "We need to drink enough water every day because it helps digest food and keeps our body working well.", "bis": "Kinahanglan kita moinom og igong tubig matag adlaw kay motabang kini sa paghilis sa pagkaon ug magpadayon nga himsog sa atong lawas."}, "source": "encyclopedia-stable consensus; DepEd health", "generator": "claude-workflow", "reviewed": false},
  {"id": "earthworm-soil-mixing-g5", "domain": "LIVING_THINGS", "topic": "earthworm soil enrichment", "grades": [4, 5, 6], "terms": ["bulate sa lupa", "earthworm", "wati", "ulod", "lupa", "soil", "yuta", "naghahalo", "mixing", "nagbubukas", "tunnels", "matabang lupa", "fertile", "pataba", "decompose", "nabubulok"], "fact": {"tl": "Ang bulate sa lupa ay naghuhukay ng mga butas habang gumagapang, kaya naghahalo ito ng lupa at nagpapataba nito para sa mga halaman.", "en": "The earthworm digs tunnels as it crawls, mixing the soil and making it richer for plants to grow.", "bis": "Ang wati nagkalot og mga lungag samtang nagakamang, busa giapil-apil niini ang yuta ug gipatambok kini alang sa mga tanom."}, "source": "NRC LS2.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "eel-igat-g5", "domain": "LIVING_THINGS", "topic": "eel snake-like fish", "grades": [4, 5, 6], "terms": ["igat", "kasili", "palos", "eel", "isda", "fish", "mahaba", "long", "parang ahas", "snake-like", "tubig", "water", "ilog", "river", "madulas", "slippery"], "fact": {"tl": "Ang igat ay isang mahabang isdang parang ahas ang hugis na may madulas na balat, at nakatira ito sa mga ilog, sapa, at dagat.", "en": "The eel is a long, snake-shaped fish with slippery skin, and it lives in rivers, streams, and the sea.", "bis": "Ang igat usa ka taas nga isda nga morag bitin og porma nga adunay danlog nga panit, ug nagpuyo kini sa mga suba, sapa, ug dagat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "early-bedtime-rest-g3", "domain": "LIVING_THINGS", "topic": "sleep rest health", "grades": [3, 4, 5], "terms": ["maagang pagtulog", "early bedtime", "tulog", "sleep", "katulog", "pahinga", "rest", "pagpapahinga", "katawan", "body", "lakas", "energy", "kalusugan", "health", "umaga"], "fact": {"tl": "Ang sapat na tulog tuwing gabi ay nakakatulong sa ating katawan na magpahinga, lumaki, at magkaroon ng lakas para sa susunod na araw.", "en": "Getting enough sleep at night helps our body rest, grow, and gain energy for the next day.", "bis": "Ang igong katulog matag gabii motabang sa atong lawas nga makapahulay, motubo, ug makabaton og kusog alang sa sunod nga adlaw."}, "source": "encyclopedia-stable consensus; DepEd health", "generator": "claude-workflow", "reviewed": false},
  {"id": "ecological-interactions-g7", "domain": "LIVING_THINGS", "topic": "ecological interactions ecosystem", "grades": [6, 7, 8, 9], "terms": ["ugnayang ekolohikal", "ecological interactions", "ekosistema", "ecosystem", "predation", "kompetisyon", "competition", "simbiyosis", "symbiosis", "relasyon", "relationship", "organismo", "organisms", "nabubuhay"], "fact": {"tl": "Sa isang ekosistema, ang mga organismo ay nag-uugnayan sa iba't ibang paraan tulad ng pagkain sa isa't isa, paligsahan sa pagkain, o pagtutulungan upang mabuhay.", "en": "In an ecosystem, organisms interact in many ways such as eating one another, competing for food, or helping each other to survive.", "bis": "Sa usa ka ekosistema, ang mga organismo nagkalambigit sa nagkalainlaing paagi sama sa pagkaon sa usag usa, pag-indigay sa pagkaon, o pagtinabangay aron mabuhi."}, "source": "NRC LS2.A; DepEd G7 ecosystems", "generator": "claude-workflow", "reviewed": false},
  {"id": "egret-tagak-puti-g5", "domain": "LIVING_THINGS", "topic": "egret wading bird", "grades": [4, 5, 6], "terms": ["tagak", "puting tagak", "egret", "ibon", "langgam", "bird", "puti", "white", "mahabang paa", "long legs", "palaisdaan", "wetland", "pilapil", "rice field", "isda", "wading"], "fact": {"tl": "Ang puting tagak ay isang ibong may mahahabang paa at leeg na karaniwang nakikita sa mga palayan at lawa habang naghahanap ng isda at insekto.", "en": "The white egret is a long-legged, long-necked bird often seen in rice fields and ponds hunting for fish and insects.", "bis": "Ang puti nga tagak usa ka langgam nga adunay tag-as nga tiil ug liog nga sagad makita sa kahumayan ug linaw samtang mangita og isda ug insekto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "endoplasmic-reticulum-g9", "domain": "LIVING_THINGS", "topic": "endoplasmic reticulum organelle", "grades": [8, 9, 10], "terms": ["endoplasmic reticulum", "organel", "organelle", "selula", "cell", "selyula", "protina", "protein", "taba", "lipid", "membrane", "gumagawa", "produce", "tubo", "network"], "fact": {"tl": "Ang endoplasmic reticulum ay isang sistema ng mga manipis na tubo sa loob ng selula na tumutulong gumawa at maghatid ng mga protina at taba.", "en": "The endoplasmic reticulum is a network of thin tubes inside the cell that helps make and transport proteins and lipids.", "bis": "Ang endoplasmic reticulum usa ka sistema sa nipis nga mga tubo sa sulod sa selula nga motabang sa paghimo ug paghatud sa mga protina ug tambok."}, "source": "encyclopedia-stable consensus; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "emptying-stagnant-containers-g5", "domain": "LIVING_THINGS", "topic": "mosquito control stagnant water dengue", "grades": [4, 5, 6, 7], "terms": ["nagtigil na tubig", "stagnant water", "lamok", "mosquito", "dengue", "itlog", "eggs", "sisidlan", "container", "tinitirikan", "empty", "pagtatapon ng tubig", "kuto-kuto", "wriggler", "sakit", "disease"], "fact": {"tl": "Nangingitlog ang lamok sa nakatigil na tubig, kaya ang pagtatapon ng tubig sa mga lalagyan ay nakakapigil sa pagdami ng lamok na nagdadala ng dengue.", "en": "Mosquitoes lay their eggs in stagnant water, so emptying water from containers helps stop the spread of dengue-carrying mosquitoes.", "bis": "Ang lamok mangitlog sa nagbarog nga tubig, busa ang pag-yabo sa tubig gikan sa mga sudlanan makapugong sa pagdaghan sa lamok nga nagdala og dengue."}, "source": "encyclopedia-stable consensus; DepEd health", "generator": "claude-workflow", "reviewed": false},
  {"id": "ear-cleaning-gentle-care-g4", "domain": "LIVING_THINGS", "topic": "ear care hygiene hearing", "grades": [3, 4, 5], "terms": ["paglilinis ng tainga", "ear cleaning", "dalunggan", "ear", "tutuli", "earwax", "pandinig", "hearing", "mahinang paglilinis", "gentle", "kalinisan", "hygiene", "pag-aalaga", "care"], "fact": {"tl": "Dapat marahang linisin lang ang labas ng tainga, dahil ang paglalagay ng matutulis na bagay sa loob ay maaaring makapinsala sa pandinig.", "en": "We should clean only the outside of the ear gently, because putting sharp objects inside can damage our hearing.", "bis": "Kinahanglan limpyohan lang og hinay ang gawas sa dalunggan, kay ang pagsulod og hait nga butang makadaot sa atong pandungog."}, "source": "encyclopedia-stable consensus; DepEd health", "generator": "claude-workflow", "reviewed": false},
  {"id": "everlasting-flower-g5", "domain": "LIVING_THINGS", "topic": "everlasting flower dry highland plant", "grades": [4, 5, 6], "terms": ["everlasting", "bulaklak", "flower", "halaman", "plant", "Baguio", "Benguet", "tuyo", "dried", "hindi nalalanta", "does not wilt", "papel", "papery", "bundok", "highland", "souvenir"], "fact": {"tl": "Ang everlasting ay bulaklak mula sa malamig na kabundukan tulad ng Baguio na nananatiling buo at parang papel kahit matuyo, kaya ginagawang pampalamuti.", "en": "The everlasting is a flower from cool highlands like Baguio that stays whole and papery even when dried, so it is made into decorations.", "bis": "Ang everlasting usa ka bulak gikan sa bugnaw nga kabukiran sama sa Baguio nga magpabilin nga buo ug morag papel bisan mauga na, busa gihimong dekorasyon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "epiphyte-orchid-on-tree-g6", "domain": "LIVING_THINGS", "topic": "epiphyte plant grows on tree", "grades": [5, 6, 7], "terms": ["epiphyte", "epipita", "orkidya", "orchid", "halaman", "plant", "tanom", "puno", "tree", "kahoy", "nakakapit", "clings", "ugat", "roots", "hangin", "air", "hindi parasito", "not parasite"], "fact": {"tl": "Ang epiphyte tulad ng ilang orkidya ay halamang tumutubo sa sanga ng puno, ngunit hindi ito kumukuha ng sustansya mula sa puno kundi sa hangin at ulan.", "en": "An epiphyte like some orchids is a plant that grows on a tree's branch, but it takes its nourishment from the air and rain, not from the tree.", "bis": "Ang epiphyte sama sa pipila ka orkidyas usa ka tanom nga motubo sa sanga sa kahoy, apan dili kini mokuha og sustansiya gikan sa kahoy kondili gikan sa hangin ug ulan."}, "source": "encyclopedia-stable consensus; NRC LS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "exercise-children-playing-g3", "domain": "LIVING_THINGS", "topic": "exercise physical activity health", "grades": [3, 4, 5], "terms": ["ehersisyo", "exercise", "paglalaro", "playing", "laro", "tumakbo", "run", "katawan", "body", "kalamnan", "muscles", "puso", "heart", "malusog", "healthy", "lakas", "fit"], "fact": {"tl": "Ang regular na ehersisyo tulad ng pagtakbo at paglalaro ay nagpapalakas ng ating mga kalamnan at puso, kaya tayo nagiging malusog.", "en": "Regular exercise like running and playing strengthens our muscles and heart, keeping us healthy.", "bis": "Ang regular nga ehersisyo sama sa pagdagan ug pagdula nagpalig-on sa atong mga kaunoran ug kasingkasing, busa kita mahimong himsog."}, "source": "encyclopedia-stable consensus; DepEd health", "generator": "claude-workflow", "reviewed": false},
  {"id": "feeling-pulse-at-neck-g6", "domain": "LIVING_THINGS", "topic": "pulse heartbeat circulation", "grades": [5, 6, 7], "terms": ["pulso", "pulse", "leeg", "neck", "tibok", "heartbeat", "puso", "heart", "dugo", "blood", "ugat", "artery", "pintig", "beat", "bilang", "circulation"], "fact": {"tl": "Ang pulso na nararamdaman natin sa leeg o pulso sa kamay ay galing sa pagtibok ng puso habang nagtutulak ito ng dugo sa ating katawan.", "en": "The pulse we feel at the neck or wrist comes from the heartbeat as it pushes blood through our body.", "bis": "Ang pulso nga atong mabati sa liog o pulso sa kamot naggikan sa pagpitik sa kasingkasing samtang nagtulod kini og dugo sa atong lawas."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "eye-parts-diagram-g5", "domain": "LIVING_THINGS", "topic": "eye vision organ parts", "grades": [4, 5, 6], "terms": ["mata", "eye", "mata bahagi", "eye parts", "paningin", "vision", "makakita", "makita", "liwanag", "light", "balintataw", "pupil", "iris", "retina", "nakikita"], "fact": {"tl": "Ang mata ang organ na ginagamit natin sa paningin; pumapasok ang liwanag sa balintataw at nabubuo ang larawan sa likod ng mata para makakita tayo.", "en": "The eye is the organ we use for sight; light enters through the pupil and an image forms at the back of the eye so we can see.", "bis": "Ang mata mao ang organ nga gamiton nato sa panan-aw; mosulod ang kahayag sa kalimutaw ug maporma ang hulagway sa likod sa mata aron makakita kita."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "eye-rest-from-screen-g4", "domain": "LIVING_THINGS", "topic": "eye care screen rest", "grades": [3, 4, 5], "terms": ["pahinga ng mata", "eye rest", "screen", "iskrin", "mata", "eye", "mata pagod", "eye strain", "paningin", "vision", "pagpapahinga", "tumingin sa malayo", "look far", "kalusugan ng mata", "kapoy"], "fact": {"tl": "Mabuting magpahinga ang mata paminsan-minsan kapag matagal na tayong nakatingin sa screen, dahil nakakapagod ito sa ating paningin.", "en": "It is good to rest our eyes now and then when we look at a screen for a long time, because it tires our vision.", "bis": "Maayo nga papahulayon ang mata matag karon ug unya kung dugay na kita nagtan-aw sa screen, kay makapakapoy kini sa atong panan-aw."}, "source": "encyclopedia-stable consensus; DepEd health", "generator": "claude-workflow", "reviewed": false},
  {"id": "fire-tree-caballero-g5", "domain": "LIVING_THINGS", "topic": "fire tree flame tree", "grades": [4, 5, 6], "terms": ["fire tree", "caballero", "arbol de fuego", "flame tree", "puno", "tree", "kahoy", "bulaklak", "flowers", "pula", "orange", "red", "tag-init", "summer", "lilim", "shade", "namumulaklak"], "fact": {"tl": "Ang fire tree o caballero ay isang punong namumukadkad ng makukulay na pula-kahel na bulaklak tuwing tag-init, kaya parang naglalagablab ang buong puno.", "en": "The fire tree or caballero is a tree that blooms with bright red-orange flowers in summer, making the whole tree look like it is on fire.", "bis": "Ang fire tree o caballero usa ka kahoy nga mamulak og bidlisiw nga pula-kahel nga mga bulak panahon sa ting-init, busa morag nagdilaab ang tibuok kahoy."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "extinction-timeline-g7", "domain": "LIVING_THINGS", "topic": "extinction species disappear", "grades": [6, 7, 8, 9], "terms": ["pagkalipol", "extinction", "lumipol", "species", "uri ng hayop", "nawala", "disappear", "dinosaur", "wala na", "no longer exist", "habitat", "tirahan", "endangered", "nanganganib", "fossil"], "fact": {"tl": "Ang pagkalipol ay nangyayari kapag namatay ang lahat ng miyembro ng isang uri ng hayop o halaman, kaya wala na itong matitira sa mundo magpakailanman.", "en": "Extinction happens when all members of a kind of animal or plant die out, so that none are left on Earth ever again.", "bis": "Ang pagkapuo mahitabo kung mamatay ang tanang sakop sa usa ka matang sa mananap o tanom, mao nga wala nay mahabilin niini sa kalibotan hangtod sa kahangtoran."}, "source": "NRC LS4.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "estuary-where-river-meets-sea-g6", "domain": "EARTH_SPACE", "topic": "estuary brackish water habitat", "grades": [5, 6, 7, 8], "terms": ["estuary", "estuwaryo", "ilog", "river", "dagat", "sea", "sapa", "bukana ng ilog", "river mouth", "tabang at alat", "brackish", "halong tubig", "mixed water", "bakawan", "mangrove", "tahanan ng isda"], "fact": {"tl": "Ang estuary ay ang lugar kung saan nagtatagpo ang ilog at dagat, kaya nagiging halong tabang at alat ang tubig na tirahan ng maraming isda at hipon.", "en": "An estuary is the place where a river meets the sea, so the water becomes a mix of fresh and salty that is home to many fish and shrimp.", "bis": "Ang estuary mao ang dapit diin magtagbo ang suba ug dagat, busa ang tubig mahimong sagol nga tab-ang ug parat nga puy-anan sa daghang isda ug pasayan."}, "source": "encyclopedia-stable consensus; NRC ESS2.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "field-rat-daga-bukid-g5", "domain": "LIVING_THINGS", "topic": "field rat rodent pest", "grades": [4, 5, 6], "terms": ["daga sa bukid", "field rat", "rice field rat", "daga", "rat", "ilaga", "rodent", "palay", "rice", "peste", "pest", "kakanin ang pananim", "crops", "bukid", "field", "ngongotngot"], "fact": {"tl": "Ang daga sa bukid ay maliit na hayop na ngumangatngat na kumakain ng palay at iba pang pananim, kaya itinuturing itong peste ng mga magsasaka.", "en": "The field rat is a small gnawing animal that eats rice and other crops, so farmers consider it a pest.", "bis": "Ang ilaga sa uma usa ka gamay nga mananap nga mokitkit nga mokaon og humay ug uban pang tanom, busa giisip kini nga peste sa mga mag-uuma."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "first-aid-nosebleed-g5", "domain": "LIVING_THINGS", "topic": "nosebleed first aid", "grades": [4, 5, 6, 7], "terms": ["balinguyngoy", "nosebleed", "dugo sa ilong", "first aid", "unang lunas", "ilong", "nose", "yumuko", "lean forward", "pipigain", "pinch", "huminto ang dugo", "stop bleeding", "gamot"], "fact": {"tl": "Kapag nagkadugo ang ilong, dapat bahagyang yumuko ang ulo at marahang pipigain ang malambot na bahagi ng ilong hanggang huminto ang pagdugo.", "en": "When a nose bleeds, you should lean the head slightly forward and gently pinch the soft part of the nose until the bleeding stops.", "bis": "Kung mag-agas ang ilong, kinahanglan moduko og gamay ang ulo ug hinay-hinayng ipislit ang humok nga bahin sa ilong hangtod mohunong ang pag-agas."}, "source": "encyclopedia-stable consensus; DepEd health", "generator": "claude-workflow", "reviewed": false},
  {"id": "first-aid-burn-cool-water-g5", "domain": "MATTER", "topic": "first aid for minor burns cool running water", "grades": [4, 5, 6], "terms": ["paso", "napaso", "sunog na balat", "malamig na tubig", "first aid", "burn", "minor burn", "cool running water", "paghilom", "samad sa kainit", "napaso ang panit", "bugnaw nga tubig", "unang tabang"], "fact": {"tl": "Kapag napaso, ibuhos agad ang malamig na umaagos na tubig sa apektadong balat nang mga 10 hanggang 20 minuto upang mabawasan ang init at pananakit.", "en": "For a minor burn, run cool (not icy) water over the skin for about 10 to 20 minutes to draw out the heat and ease the pain.", "bis": "Kung mapaso, ibubo dayon ang bugnaw nga nagdagayday nga tubig sa naigo nga panit mga 10 ngadto sa 20 ka minuto aron makunhuran ang kainit ug ang kasakit."}, "source": "encyclopedia-stable consensus (Red Cross first aid)", "generator": "claude-workflow", "reviewed": false},
  {"id": "first-aid-cut-wound-g5", "domain": "LIVING_THINGS", "topic": "first aid for a small cut wound", "grades": [4, 5, 6], "terms": ["sugat", "hiwa", "gasa", "linis ang sugat", "diretsong diin", "presyon", "tigilin ang dugo", "cut", "wound", "clean", "pressure", "bleeding", "samad", "limpyohan", "ipit", "duguon"], "fact": {"tl": "Para sa maliit na hiwa, hugasan ang sugat ng malinis na tubig, idiin ang malinis na tela para tumigil ang dugo, at takpan ito ng malinis na benda.", "en": "For a small cut, wash the wound with clean water, press a clean cloth on it to stop the bleeding, then cover it with a clean bandage.", "bis": "Para sa gamay nga samad, hugasi ang samad og limpyo nga tubig, ipiti og limpyo nga panapton aron mohunong ang dugo, dayon taboni kini og limpyo nga bendahe."}, "source": "encyclopedia-stable consensus (Red Cross first aid)", "generator": "claude-workflow", "reviewed": false},
  {"id": "feather-star-crinoid-g6", "domain": "LIVING_THINGS", "topic": "feather star crinoid coral reef animal", "grades": [5, 6, 7], "terms": ["feather star", "crinoid", "bituing balahibo", "hayop sa bahura", "echinoderm", "kapamilya ng starfish", "sea lily", "pakpak na braso", "feathery arms", "coral reef", "bituon sa dagat nga balahibuhon", "isda sa bahura", "kadagatan"], "fact": {"tl": "Ang feather star o crinoid ay isang hayop sa bahura na kamag-anak ng starfish, na may mga balahibo-balahibong braso na ginagamit nito para humuli ng maliliit na pagkaing tinatangay ng tubig.", "en": "A feather star, or crinoid, is a reef animal related to starfish whose many feathery arms catch tiny bits of food drifting in the water.", "bis": "Ang feather star o crinoid usa ka mananap sa bahura nga paryente sa starfish, nga adunay daghang balahibuhon nga mga bukton nga gigamit niini sa pagdakop sa gagmay nga pagkaon nga ginadala sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "first-aid-insect-bite-g5", "domain": "LIVING_THINGS", "topic": "first aid for insect bite or sting", "grades": [4, 5, 6], "terms": ["kagat ng insekto", "kinagat", "tusok ng pukyutan", "namaga", "kati", "malamig na compress", "yelo", "insect bite", "sting", "swelling", "itch", "cold compress", "paak sa insekto", "gipaak", "tusok sa bubuyog", "nihubag", "katol"], "fact": {"tl": "Kapag nakagat ng insekto, hugasan ang lugar at maglagay ng malamig na compress para mabawasan ang pamamaga at pangangati.", "en": "After an insect bite or sting, wash the spot and place a cold compress on it to reduce swelling and itching.", "bis": "Kung mapaak sa insekto, hugasi ang dapit ug butangan og bugnaw nga compress aron makunhuran ang paghubag ug ang katol."}, "source": "encyclopedia-stable consensus (Red Cross first aid)", "generator": "claude-workflow", "reviewed": false},
  {"id": "fish-sanctuary-marine-protected-g6", "domain": "LIVING_THINGS", "topic": "fish sanctuary marine protected area", "grades": [5, 6, 7], "terms": ["fish sanctuary", "marine protected area", "santuwaryo ng isda", "bawal mangisda", "protektadong dagat", "nagdadami ang isda", "bahura", "no-fishing zone", "conservation", "dalangpan sa isda", "gidili ang pagpangisda", "panalipdan nga dagat", "nagdaghan ang isda", "pagpanalipod"], "fact": {"tl": "Ang fish sanctuary ay isang protektadong bahagi ng dagat kung saan bawal mangisda, kaya nakakapagparami nang ligtas ang mga isda at nadadagdagan ang huli sa palibot na karagatan.", "en": "A fish sanctuary is a protected part of the sea where fishing is banned, so fish can breed safely and spill over to refill the surrounding waters.", "bis": "Ang fish sanctuary usa ka panalipdan nga bahin sa dagat diin gidili ang pagpangisda, busa luwas nga makasanay ang mga isda ug magdugang ang madakpan sa palibot nga kadagatan."}, "source": "encyclopedia-stable consensus; DepEd G6 ecosystems", "generator": "claude-workflow", "reviewed": false},
  {"id": "first-aid-sprain-rice-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "first aid for sprain RICE rest ice compression elevation", "grades": [5, 6, 7], "terms": ["pilay", "napilay", "RICE", "pahinga", "yelo", "benda", "itaas ang paa", "rest ice compression elevation", "sprain", "swelling", "kapilay", "napilayan", "pahulay", "ipataas", "namaga", "kasumpay"], "fact": {"tl": "Para sa pilay, gamitin ang RICE: pahinga (Rest), yelo (Ice), pagbenda (Compression), at pag-angat ng paa (Elevation) upang mabawasan ang pamamaga at sakit.", "en": "For a sprain, use RICE: Rest, Ice, Compression with a bandage, and Elevation of the limb, to reduce swelling and pain.", "bis": "Para sa kapilay, gamita ang RICE: pahulay (Rest), yelo (Ice), bendahe (Compression), ug pagpataas sa tiil (Elevation) aron makunhuran ang paghubag ug kasakit."}, "source": "encyclopedia-stable consensus (sports first aid)", "generator": "claude-workflow", "reviewed": false},
  {"id": "fish-pen-aquaculture-g6", "domain": "LIVING_THINGS", "topic": "fish pen aquaculture fish farming", "grades": [5, 6, 7], "terms": ["fish pen", "fish cage", "baklad", "palaisdaan", "pag-aalaga ng isda", "aquaculture", "lawa", "bangus", "tilapia", "fish farming", "kulungan ng isda", "alagaang isda", "pagpadako og isda", "lanaw", "pataba sa isda"], "fact": {"tl": "Ang fish pen ay isang malaking kulungan na lambat sa lawa o dagat kung saan inaalagaan at pinapakain ang mga isda tulad ng bangus at tilapia hanggang sa lumaki para anihin.", "en": "A fish pen is a large net enclosure in a lake or sea where fish such as milkfish and tilapia are raised and fed until they are big enough to harvest.", "bis": "Ang fish pen usa ka dako nga kulungan nga pukot sa lanaw o dagat diin gialagaan ug gipakaon ang mga isda sama sa bangus ug tilapia hangtod nga modako kini aron anihon."}, "source": "encyclopedia-stable consensus; PH aquaculture", "generator": "claude-workflow", "reviewed": false},
  {"id": "euglena-microbe-g7", "domain": "LIVING_THINGS", "topic": "euglena single-celled microbe", "grades": [6, 7, 8], "terms": ["euglena", "mikrobyo", "isang selula", "protista", "flagellum", "buntot na latigo", "chloroplast", "gumagawa ng pagkain", "microbe", "single-celled", "swims", "eyespot", "usa ka selula", "naglihok", "naghimo og pagkaon", "tubig tab-ang"], "fact": {"tl": "Ang euglena ay isang napakaliit na nilalang na may isang selula lamang, na lumalangoy gamit ang buntot na latigo at nakakagawa ng sariling pagkain mula sa sikat ng araw tulad ng halaman.", "en": "Euglena is a tiny single-celled creature that swims with a whip-like tail and can make its own food from sunlight like a plant.", "bis": "Ang euglena usa ka gamay kaayo nga binuhat nga adunay usa ra ka selula, nga molangoy pinaagi sa ikog nga sama sa latigo ug makahimo og kaugalingong pagkaon gikan sa kahayag sa adlaw sama sa tanom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "flying-fox-roost-colony-g6", "domain": "LIVING_THINGS", "topic": "flying fox fruit bat roost colony", "grades": [5, 6, 7], "terms": ["flying fox", "fruit bat", "kabog", "paniki", "bayakan", "kolonya ng paniki", "nakabitin sa puno", "roost", "fruit bat colony", "nagkakalat ng buto", "seed disperser", "kabog nga dako", "nagbitay sa kahoy", "panon sa kabog", "nagsabwag og liso"], "fact": {"tl": "Ang flying fox o malaking paniki ay nakatira nang sama-sama sa malalaking kolonya na nakabitin sa matataas na puno tuwing araw, at tumutulong itong magkalat ng mga buto ng prutas sa gabi.", "en": "Flying foxes are large fruit bats that roost together in big colonies hanging from tall trees by day and help spread fruit seeds across the forest at night.", "bis": "Ang flying fox o dako nga kabog nagpuyo nga nagtapok sa dagkong panon nga nagbitay sa tag-as nga kahoy panahon sa adlaw, ug motabang kini sa pagsabwag sa mga liso sa prutas panahon sa gabii."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "flat-headed-frog-philippine-g7", "domain": "LIVING_THINGS", "topic": "philippine flat-headed frog endemic amphibian", "grades": [6, 7, 8], "terms": ["flat-headed frog", "palaka", "patag ang ulo", "endemic", "endemiko sa Pilipinas", "batis", "amphibian", "stream frog", "Barbourula", "baki", "patag og ulo", "tubig tab-ang", "sapa", "amphibyo", "Pilipinas lamang"], "fact": {"tl": "Ang Philippine flat-headed frog ay isang palakang may patag na ulo na matatagpuan lamang sa Pilipinas at nakatira sa malalamig at malilinis na batis sa kagubatan.", "en": "The Philippine flat-headed frog is a flat-headed frog found only in the Philippines, living in cool, clean forest streams.", "bis": "Ang Philippine flat-headed frog usa ka baki nga patag og ulo nga makit-an lamang sa Pilipinas ug nagpuyo sa bugnaw ug limpyo nga mga sapa sa kalasangan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "flower-cross-section-g6", "domain": "LIVING_THINGS", "topic": "parts of a flower cross section", "grades": [5, 6, 7], "terms": ["bahagi ng bulaklak", "bulaklak", "talulot", "pollen", "stamen", "pistil", "puno ng bulaklak", "stigma", "petal", "flower parts", "reproduksiyon", "bahin sa bulak", "bulak", "petalo", "polen", "pagsanay sa tanom"], "fact": {"tl": "Ang bulaklak ay ang bahagi ng halaman para sa pagpaparami, na may mga talulot, polen mula sa stamen, at pistil na tumatanggap ng polen upang mabuo ang buto.", "en": "A flower is the plant's part for reproduction, with petals, pollen from the stamens, and a pistil that receives pollen so seeds can form.", "bis": "Ang bulak mao ang bahin sa tanom alang sa pagsanay, nga adunay mga petalo, polen gikan sa stamen, ug pistil nga modawat sa polen aron maporma ang liso."}, "source": "AAAS Benchmarks 5C; DepEd G5 plant reproduction", "generator": "claude-workflow", "reviewed": false},
  {"id": "flying-fish-bolador-g6", "domain": "LIVING_THINGS", "topic": "flying fish bolador gliding fish", "grades": [5, 6, 7], "terms": ["flying fish", "bolador", "lumilipad na isda", "lumalampas sa tubig", "pakpak na palikpik", "glides", "wing-like fins", "tumatakas sa lamon", "iniwasan ang mandaragit", "milipad sa tubig", "naglupad nga isda", "kapay nga sama sa pako", "nilupad", "miikyas sa manunukob"], "fact": {"tl": "Ang flying fish o bolador ay isang isda na lumulundag mula sa tubig at gumagamit ng malalaki nitong palikpik na parang pakpak upang lumipad-lipad sa ibabaw ng dagat at makaiwas sa mga mandaragit.", "en": "The flying fish, or bolador, leaps from the water and uses its large wing-like fins to glide above the sea to escape predators.", "bis": "Ang flying fish o bolador usa ka isda nga molukso gikan sa tubig ug mogamit sa dagkong kapay niini nga sama sa pako aron molupad sa ibabaw sa dagat ug makalikay sa mga manunukob."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "flying-lemur-kagwang-g6", "domain": "LIVING_THINGS", "topic": "philippine flying lemur kagwang colugo gliding mammal", "grades": [5, 6, 7], "terms": ["flying lemur", "kagwang", "colugo", "lumilipad na hayop", "balat na pang-glide", "gliding mammal", "nag-glide sa puno", "endemiko", "kaybaog", "naglupad nga hayop", "panit nga pang-glide", "nag-glide sa kahoy", "Pilipinas", "nokturnal"], "fact": {"tl": "Ang kagwang o Philippine flying lemur ay isang mammal na hindi talaga lumilipad kundi nag-glide mula sa puno patungo sa puno gamit ang malapad na balat sa gilid ng katawan nito.", "en": "The kagwang, or Philippine flying lemur, is a mammal that does not truly fly but glides from tree to tree using the wide flap of skin along its body.", "bis": "Ang kagwang o Philippine flying lemur usa ka mammal nga dili tinuod nga molupad kondili mo-glide gikan sa kahoy ngadto sa laing kahoy pinaagi sa lapad nga panit sa kilid sa lawas niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "flowerpecker-tiny-bird-g6", "domain": "LIVING_THINGS", "topic": "flowerpecker tiny bird pollinator seed disperser", "grades": [5, 6, 7], "terms": ["flowerpecker", "pipit", "maliit na ibon", "kumakain ng prutas", "mistletoe", "nagkakalat ng buto", "pollinator", "tiny bird", "nectar", "gamay nga langgam", "mokaon og bunga", "nagsabwag og liso", "nektar", "Pilipinas"], "fact": {"tl": "Ang flowerpecker ay isang napakaliit na ibon na kumakain ng maliliit na prutas at nektar, at tumutulong itong magkalat ng mga buto at magpolen ng mga bulaklak.", "en": "The flowerpecker is a very small bird that eats tiny fruits and nectar, helping to spread seeds and pollinate flowers.", "bis": "Ang flowerpecker usa ka gamay kaayo nga langgam nga mokaon og gagmayng bunga ug nektar, ug motabang kini sa pagsabwag og liso ug sa pagpolen sa mga bulak."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "food-making-in-chloroplast-g6", "domain": "LIVING_THINGS", "topic": "photosynthesis food made in chloroplast", "grades": [5, 6, 7], "terms": ["chloroplast", "kloroplast", "luntiang bahagi", "chlorophyll", "kloropil", "gumagawa ng pagkain", "photosynthesis", "potosintesis", "sikat ng araw", "dahon", "food making", "naghimo og pagkaon", "luntian", "kahayag sa adlaw", "dahon sa tanom"], "fact": {"tl": "Sa loob ng mga dahon, ang maliliit na luntiang bahagi na tinatawag na chloroplast ang gumagawa ng pagkain ng halaman mula sa sikat ng araw, tubig, at hangin.", "en": "Inside leaves, tiny green parts called chloroplasts make the plant's food from sunlight, water, and air.", "bis": "Sulod sa mga dahon, ang gagmay nga luntian nga bahin nga gitawag og chloroplast maoy naghimo sa pagkaon sa tanom gikan sa kahayag sa adlaw, tubig, ug hangin."}, "source": "AAAS Benchmarks 5E; DepEd G6 photosynthesis", "generator": "claude-workflow", "reviewed": false},
  {"id": "flying-lizard-draco-g6", "domain": "LIVING_THINGS", "topic": "flying lizard draco gliding lizard", "grades": [5, 6, 7], "terms": ["flying lizard", "draco", "lumilipad na butiki", "balat na pakpak", "gliding lizard", "nag-glide sa puno", "skin wings", "naglupad nga tiki", "panit nga pako", "nag-glide", "kahoy", "Pilipinas", "mananap nga molupad"], "fact": {"tl": "Ang flying lizard o draco ay isang maliit na butiki na nakakapag-glide mula sa isang puno patungo sa iba gamit ang malalapad na balat sa gilid nito na bumubukas na parang pakpak.", "en": "The flying lizard, or draco, is a small lizard that glides from tree to tree by spreading wide flaps of skin on its sides like wings.", "bis": "Ang flying lizard o draco usa ka gamay nga tiki nga makahimo og glide gikan sa usa ka kahoy ngadto sa lain pinaagi sa pagbukhad sa lapad nga panit sa kilid niini nga sama sa pako."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "food-spoilage-safe-storage-g5", "domain": "MATTER", "topic": "food spoilage safe storage refrigeration", "grades": [4, 5, 6], "terms": ["pagkasira ng pagkain", "panis", "bulok", "refrigerator", "lamig", "tagong ligtas", "bakterya", "food spoilage", "safe storage", "preservation", "pagkadunot sa pagkaon", "dunot", "ref", "bugnaw", "tipigan", "bakterya nga makadaot"], "fact": {"tl": "Nabubulok ang pagkain dahil sa pagdami ng mga mikrobyo, kaya ang pagtatago sa lamig na refrigerator ay nagpapabagal sa kanila at nagpapatagal sa pagkain.", "en": "Food spoils because microbes multiply in it, so storing food cold in a refrigerator slows the microbes down and keeps it fresh longer.", "bis": "Madunot ang pagkaon tungod kay nagdaghan ang mga mikrobyo niini, busa ang pagtipig sa bugnaw nga refrigerator makapahinay kanila ug makapadugay sa kapresko sa pagkaon."}, "source": "AAAS Benchmarks 8B; DepEd G5 food preservation", "generator": "claude-workflow", "reviewed": false},
  {"id": "food-groups-balanced-plate-g5", "domain": "LIVING_THINGS", "topic": "food groups balanced diet pinggang pinoy", "grades": [3, 4, 5, 6], "terms": ["food groups", "go grow glow", "pinggang pinoy", "balanseng pagkain", "gulay", "prutas", "karbohidrat", "protina", "energy", "nutrisyon", "balanced diet", "utan", "tamang pagkaon", "kusog sa lawas"], "fact": {"tl": "Upang lumusog, kailangan ng katawan ng sari-saring pagkain: 'go' na nagbibigay-lakas tulad ng kanin, 'grow' na pampalaki tulad ng isda't karne, at 'glow' na pampalakas-resistensya tulad ng gulay at prutas.", "en": "To stay healthy the body needs a mix of foods: 'go' foods for energy like rice, 'grow' foods for building the body like fish and meat, and 'glow' foods for protection like vegetables and fruit.", "bis": "Aron mahimsog, ang lawas nagkinahanglan og nagkalainlaing pagkaon: 'go' nga naghatag og kusog sama sa kan-on, 'grow' nga pangpadako sama sa isda ug karne, ug 'glow' nga pangpalig-on sama sa utanon ug prutas."}, "source": "DepEd / DOST-FNRI Pinggang Pinoy; DepEd health-science", "generator": "claude-workflow", "reviewed": false},
  {"id": "food-spoilage-fresh-vs-rotten-g4", "domain": "MATTER", "topic": "telling fresh food from spoiled food", "grades": [3, 4, 5], "terms": ["sariwa", "bulok", "panis", "amoy", "kulay na nagbago", "amag", "fresh vs rotten", "spoiled food", "signs of spoilage", "presko", "dunot", "baho", "nausab ang kolor", "agup-op", "ilhanan sa pagkadunot"], "fact": {"tl": "Makikilala mo ang bulok na pagkain sa masangsang na amoy, nagbagong kulay, malambot na bahagi, o pagkakaroon ng amag, at hindi na ito ligtas kainin.", "en": "You can tell spoiled food by its bad smell, changed color, mushy spots, or fuzzy mold, and it is no longer safe to eat.", "bis": "Mailhan nimo ang dunot nga pagkaon pinaagi sa baho niini, nausab nga kolor, humok nga bahin, o agup-op, ug dili na kini luwas kan-on."}, "source": "encyclopedia-stable consensus; DepEd G4 food safety", "generator": "claude-workflow", "reviewed": false},
  {"id": "foot-body-part-g4", "domain": "LIVING_THINGS", "topic": "the foot body part for standing and walking", "grades": [3, 4, 5], "terms": ["paa", "talampakan", "daliri sa paa", "buto", "naglalakad", "tumatayo", "balanse", "foot", "toes", "heel", "arch", "tiil", "lapalapa", "tudlo sa tiil", "bukog", "naglakaw", "nagtindog", "timbang"], "fact": {"tl": "Ang paa ay ang bahagi ng katawan sa dulo ng binti na may maraming buto at daliri, at tumutulong itong tumayo, maglakad, at panatilihin ang balanse.", "en": "The foot is the body part at the end of the leg, with many small bones and toes, and it helps us stand, walk, and keep our balance.", "bis": "Ang tiil mao ang bahin sa lawas sa tumoy sa bitiis nga adunay daghang gagmay nga bukog ug mga tudlo, ug motabang kini kanato sa pagtindog, paglakaw, ug sa pagtimbang."}, "source": "AAAS Benchmarks 6C; DepEd human body", "generator": "claude-workflow", "reviewed": false},
  {"id": "food-from-farm-to-table-g4", "domain": "LIVING_THINGS", "topic": "food from farm to table where food comes from", "grades": [3, 4, 5], "terms": ["bukid", "pagsasaka", "ani", "pamilihan", "mesa", "saan galing ang pagkain", "magsasaka", "farm to table", "harvest", "market", "uma", "pag-uma", "merkado", "asa gikan ang pagkaon", "mag-uuma", "pamaligya"], "fact": {"tl": "Karamihan sa pagkain natin ay nagsisimula sa bukid o palaisdaan, inaani ng mga magsasaka't mangingisda, dinadala sa pamilihan, at saka umaabot sa ating mesa.", "en": "Most of our food begins on a farm or fishpond, is harvested by farmers and fishers, taken to the market, and finally reaches our table.", "bis": "Kadaghanan sa atong pagkaon magsugod sa uma o sa palaisdaan, anihon sa mga mag-uuma ug mangingisda, dad-on sa merkado, ug sa kataposan moabot sa atong lamesa."}, "source": "DepEd G3-4 food and agriculture; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "foodweb-rainforest-ph-g6", "domain": "LIVING_THINGS", "topic": "rainforest food web philippine forest", "grades": [5, 6, 7], "terms": ["food web", "kadena ng pagkain", "gubat", "kagubatan", "halaman", "insekto", "ibon", "agila", "mandaragit", "rainforest food web", "predator", "prey", "lasang", "tanom", "langgam", "manunukob", "ginakaon", "sumpay sa pagkaon"], "fact": {"tl": "Sa kagubatan ng Pilipinas, kumakain ng dahon ang mga insekto, kinakain naman sila ng mga ibon, at ang mga ibon ay maaaring biktima ng malalaking mandaragit gaya ng agila, na bumubuo ng isang food web.", "en": "In a Philippine rainforest, insects eat leaves, birds eat the insects, and big predators like eagles eat the birds, forming a food web that links them all.", "bis": "Sa kalasangan sa Pilipinas, ang mga insekto mokaon og dahon, ang mga langgam mokaon sa insekto, ug ang dagkong manunukob sama sa agila mokaon sa mga langgam, nga maghimo og food web nga nagsumpay kanilang tanan."}, "source": "NRC LS2.B; DepEd G6 ecosystems", "generator": "claude-workflow", "reviewed": false},
  {"id": "foodweb-mangrove-ph-g6", "domain": "LIVING_THINGS", "topic": "mangrove food web bakawan estuary", "grades": [5, 6, 7], "terms": ["food web", "bakawan", "mangrove", "dahong nalalaglag", "alimango", "hipon", "isda", "tagak", "detritus", "estuary", "mangrove food web", "kadena ng pagkain", "lambay", "pasayan", "tabok", "nangkalaglag nga dahon"], "fact": {"tl": "Sa kabakawanan, ang nahuhulog na dahon ng bakawan ang nagiging pagkain ng mga hipon, alimango, at isda, na siya namang kinakain ng mga ibong tulad ng tagak.", "en": "In a mangrove forest, fallen mangrove leaves become food for shrimp, crabs, and fish, which in turn are eaten by birds such as herons.", "bis": "Sa kabakawanan, ang nahulog nga dahon sa bakawan mahimong pagkaon sa mga pasayan, lambay, ug isda, nga gikaon usab sa mga langgam sama sa tabok."}, "source": "NRC LS2.B; DepEd G6 ecosystems", "generator": "claude-workflow", "reviewed": false},
  {"id": "foodweb-pond-freshwater-g6", "domain": "LIVING_THINGS", "topic": "freshwater pond food web", "grades": [5, 6, 7], "terms": ["food web", "lawa", "pond", "tubig-tabang", "algae", "lumot", "palaka", "isda", "tagak", "freshwater pond food web", "plankton", "kadena ng pagkain", "lanaw", "tubig tab-ang", "baki", "tabok", "sumpay sa pagkaon"], "fact": {"tl": "Sa isang lawa, ang lumot at mga maliliit na halaman ang pinagsisimulan ng pagkain na kinakain ng mga isda at insekto, na siya namang kinakain ng mga palaka at ibon.", "en": "In a freshwater pond, algae and tiny plants start the food chain, eaten by fish and insects, which are then eaten by frogs and birds.", "bis": "Sa usa ka lanaw, ang lumot ug gagmay nga tanom maoy sinugdanan sa pagkaon nga gikaon sa mga isda ug insekto, nga gikaon usab sa mga baki ug langgam."}, "source": "NRC LS2.B; DepEd G6 ecosystems", "generator": "claude-workflow", "reviewed": false},
  {"id": "foodweb-diagram-g6", "domain": "LIVING_THINGS", "topic": "food web diagram how energy flows", "grades": [5, 6, 7], "terms": ["food web", "food chain", "kadena ng pagkain", "daloy ng enerhiya", "producer", "consumer", "decomposer", "arrow", "kumakain", "energy flow", "sumpay sa pagkaon", "agos sa kusog", "naghatag og pagkaon", "mokaon", "tigdugmok", "pana"], "fact": {"tl": "Ang food web ay isang larawan na nagpapakita kung paano nag-uugnay-ugnay ang maraming kadena ng pagkain, kung saan ang bawat palaso ay nagtuturo mula sa kinakain patungo sa kumakain.", "en": "A food web is a diagram showing how many food chains link together, where each arrow points from the food to the living thing that eats it.", "bis": "Ang food web usa ka hulagway nga nagpakita kung giunsa pagsumpaysumpay sa daghang sumpay sa pagkaon, diin ang matag pana motudlo gikan sa gikaon ngadto sa buhing butang nga mokaon niini."}, "source": "NRC LS2.B; AAAS Benchmarks 5D", "generator": "claude-workflow", "reviewed": false},
  {"id": "four-s-dengue-prevention-g5", "domain": "LIVING_THINGS", "topic": "4S dengue prevention against mosquitoes", "grades": [4, 5, 6], "terms": ["dengue", "4S", "lamok", "Aedes", "search and destroy", "self-protection", "seek early consultation", "say yes to fogging", "stagnant water", "namo", "tubig nga nagtigom", "pagpugong sa dengue", "Aedes nga lamok"], "fact": {"tl": "Upang maiwasan ang dengue, sundin ang 4S: Search and destroy ang pamamahayan ng lamok, Self-protection, Seek early consultation, at Say yes to fogging kapag may outbreak.", "en": "To prevent dengue, follow the 4S: Search and destroy mosquito breeding spots, Self-protection, Seek early consultation, and Say yes to fogging during an outbreak.", "bis": "Aron malikayan ang dengue, sunda ang 4S: Search and destroy sa puy-anan sa lamok, Self-protection, Seek early consultation, ug Say yes to fogging kung adunay outbreak."}, "source": "DOH 4S strategy; DepEd health-science", "generator": "claude-workflow", "reviewed": false},
  {"id": "freshwater-marsh-wetland-g6", "domain": "EARTH_SPACE", "topic": "freshwater marsh wetland habitat", "grades": [5, 6, 7], "terms": ["latian", "marsh", "wetland", "basa-basang lupa", "tubig-tabang", "tirahan ng ibon", "halamang-tubig", "nagsasala ng tubig", "freshwater marsh", "habitat", "lapok", "kalamakan", "basa nga yuta", "tubig tab-ang", "puy-anan sa langgam", "tanom sa tubig"], "fact": {"tl": "Ang latian o marsh ay isang basa-basang lupain na puno ng mga halamang-tubig, na nagsisilbing tirahan ng maraming ibon at isda at tumutulong ding magsala ng tubig.", "en": "A freshwater marsh is a low, watery wetland full of water plants that is home to many birds and fish and also helps clean the water.", "bis": "Ang kalamakan o marsh usa ka basa nga yuta nga puno sa mga tanom sa tubig, nga nahimong puy-anan sa daghang langgam ug isda ug motabang usab sa paglimpyo sa tubig."}, "source": "encyclopedia-stable consensus; DepEd G6 ecosystems", "generator": "claude-workflow", "reviewed": false},
  {"id": "foodweb-seagrass-meadow-g6", "domain": "LIVING_THINGS", "topic": "seagrass meadow food web dugong sea turtle", "grades": [5, 6, 7], "terms": ["food web", "seagrass", "damong-dagat", "dugong", "pawikan", "sea turtle", "isda", "seagrass meadow", "kumakain ng damong-dagat", "habitat ng isda", "kadena ng pagkain", "balili sa dagat", "mokaon og damong-dagat", "puy-anan sa isda"], "fact": {"tl": "Sa damuhang-dagat o seagrass meadow, ang damong-dagat ang pagkain ng dugong at pawikan, at nagsisilbi rin itong tahanan at pakanan ng maraming maliliit na isda.", "en": "In a seagrass meadow, the seagrass is food for dugongs and sea turtles, and it is also a home and feeding ground for many small fish.", "bis": "Sa seagrass meadow, ang damong-dagat mao ang pagkaon sa dugong ug pawikan, ug nahimo usab kini nga puy-anan ug kan-anan sa daghang gagmayng isda."}, "source": "NRC LS2.B; DepEd G6 marine ecosystems", "generator": "claude-workflow", "reviewed": false},
  {"id": "fruit-bat-seed-disperser-g5", "domain": "LIVING_THINGS", "topic": "fruit bats as seed dispersers", "grades": [4, 5, 6], "terms": ["paniki", "kabog", "fruit bat", "seed disperser", "buto ng prutas", "liso", "binhi", "naghahasik", "nagkakalat ng buto", "magsabwag ug liso", "forest", "gubat", "lasang"], "fact": {"tl": "Kapag kumakain ng prutas ang paniki, naipupunta nito ang buto sa malalayong lugar kaya nakakatulong itong magpatubo ng bagong puno sa gubat.", "en": "When fruit bats eat fruit, they carry and drop the seeds far away, helping new trees grow in the forest.", "bis": "Kon mokaon ug prutas ang kabog, gidala niini ang liso sa layong dapit busa nakatabang kini nga motubo ang bag-ong kahoy sa lasang."}, "source": "encyclopedia-stable consensus; NRC LS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "freshwater-eel-palos-g5", "domain": "LIVING_THINGS", "topic": "freshwater eel (palos)", "grades": [4, 5, 6], "terms": ["palos", "igat", "kasili", "freshwater eel", "eel", "isda", "ilog", "sapa", "suba", "snakelike fish", "slippery", "madulas", "madanglog"], "fact": {"tl": "Ang palos ay isang isdang parang ahas ang hugis na may madulas na balat at nakatira sa mga ilog at sapa bago lumangoy patungong dagat para mangitlog.", "en": "The freshwater eel (palos) is a snake-shaped fish with slippery skin that lives in rivers and streams before swimming to the sea to lay eggs.", "bis": "Ang kasili o palos usa ka isda nga morag bitin ang porma nga adunay madanglog nga panit ug nagpuyo sa mga suba sa dili pa molangoy ngadto sa dagat aron mangitlog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "freshwater-lake-ecosystem-g6", "domain": "LIVING_THINGS", "topic": "freshwater lake ecosystem", "grades": [5, 6, 7], "terms": ["lawa", "linaw", "lanaw", "freshwater lake", "ecosystem", "ekosistema", "isda", "halamang-tubig", "tanom sa tubig", "fresh water", "tubig-tabang", "ibon", "langgam"], "fact": {"tl": "Ang lawa ay isang malaking tubig-tabang na tahanan ng mga isda, halamang-tubig, at ibon na magkakaugnay sa isa't isa para mabuhay.", "en": "A freshwater lake is a large body of fresh water that is home to fish, water plants, and birds that all depend on one another to live.", "bis": "Ang lanaw usa ka dako nga tubig-tabang nga gipuy-an sa mga isda, tanom sa tubig, ug langgam nga nagsalig sa usag usa aron mabuhi."}, "source": "encyclopedia-stable consensus; NRC LS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "foodweb-grassland-ph-g6", "domain": "LIVING_THINGS", "topic": "grassland food web", "grades": [5, 6, 7], "terms": ["food web", "kadena ng pagkain", "kalan-onan nga kadena", "damo", "sagbot", "tipaklong", "apan-apan", "ibon", "langgam", "ahas", "bitin", "grassland", "kaparangan", "kasagbutan"], "fact": {"tl": "Sa kaparangan, kinakain ng tipaklong ang damo, kinakain naman ang tipaklong ng ibon, at ang ibon ay maaaring kainin ng ahas, na bumubuo ng isang food web.", "en": "In a grassland, grasshoppers eat grass, birds eat grasshoppers, and snakes may eat birds, forming a food web that links many living things.", "bis": "Sa kasagbutan, ang apan-apan mokaon sa sagbot, ang langgam mokaon sa apan-apan, ug ang bitin mahimong mokaon sa langgam, nga naghimo ug usa ka food web."}, "source": "NRC LS2.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "frigatebird-soar-g5", "domain": "LIVING_THINGS", "topic": "frigatebird", "grades": [4, 5, 6], "terms": ["frigatebird", "ibon sa dagat", "langgam sa dagat", "seabird", "lumilipad", "naglalayag sa himpapawid", "soar", "pulang lalamunan", "red throat pouch", "isda", "naglupad nga taas", "pula nga tutunlan"], "fact": {"tl": "Ang frigatebird ay isang ibong-dagat na may mahabang pakpak na nakakapaglutang sa himpapawid nang maraming oras nang hindi pumapagaspas, at ang lalaki ay may pulang lalamunan na napapalobo.", "en": "The frigatebird is a seabird with long wings that can glide in the air for hours without flapping, and the male has a red throat pouch it puffs up.", "bis": "Ang frigatebird usa ka langgam sa dagat nga adunay tag-as nga pako nga makahimo paglutaw sa kawanangan ug daghang oras nga walay pagkapakapa, ug ang laki adunay pula nga tutunlan nga iyang gibula."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "estero-river-pollution-g6", "domain": "EARTH_SPACE", "topic": "water pollution in esteros and rivers", "grades": [5, 6, 7], "terms": ["estero", "ilog", "suba", "polusyon sa tubig", "water pollution", "basura", "dumi", "marumi", "hugaw", "kontaminado", "pollution", "plastik"], "fact": {"tl": "Kapag itinatapon ang basura at dumi sa estero at ilog, nagiging marumi ang tubig at namamatay ang mga isda kaya mahalagang panatilihing malinis ang ating mga waterways.", "en": "When trash and waste are thrown into esteros and rivers, the water becomes polluted and fish die, so keeping our waterways clean is important.", "bis": "Kon ilabay ang basura ug hugaw sa estero ug suba, mahimong hugaw ang tubig ug mamatay ang mga isda busa importante nga limpyohan ang atong mga sapa."}, "source": "encyclopedia-stable consensus; DepEd Earth Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "freshwater-turtle-bakoko-g5", "domain": "LIVING_THINGS", "topic": "freshwater turtle (pagong)", "grades": [3, 4, 5], "terms": ["bakoko", "pagong", "bao", "freshwater turtle", "turtle", "ilog", "suba", "lawa", "lanaw", "shell", "talukab", "kabhang", "reptilya", "reptile"], "fact": {"tl": "Ang pagong sa tubig-tabang ay isang reptilyang may matigas na talukab na nakatira sa ilog at lawa at maaaring magpahinga sa lupa o lumangoy sa tubig.", "en": "The freshwater turtle is a reptile with a hard shell that lives in rivers and lakes and can rest on land or swim in the water.", "bis": "Ang bao sa tubig-tabang usa ka reptilya nga adunay gahi nga kabhang nga nagpuyo sa suba ug lanaw ug makapahulay sa yuta o makalangoy sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "forest-fruit-bat-python-chain-g6", "domain": "LIVING_THINGS", "topic": "forest food chain", "grades": [5, 6, 7], "terms": ["food chain", "kadena ng pagkain", "kalan-onan nga kadena", "prutas", "paniki", "kabog", "sawa", "python", "gubat", "lasang", "predator", "biktima"], "fact": {"tl": "Sa gubat, kinakain ng paniki ang prutas ng puno at ang paniki naman ay maaaring kainin ng sawa, na nagpapakita kung paano dumadaloy ang enerhiya sa isang food chain.", "en": "In the forest, fruit bats eat the fruit of trees and a python may eat the bat, showing how energy flows along a food chain.", "bis": "Sa lasang, ang kabog mokaon sa prutas sa kahoy ug ang kabog mahimong kan-on sa sawa, nga nagpakita kon unsaon pag-agos sa kusog sa usa ka food chain."}, "source": "NRC LS2.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "freshwater-river-ecosystem-g6", "domain": "LIVING_THINGS", "topic": "freshwater river ecosystem", "grades": [5, 6, 7], "terms": ["ilog", "suba", "river", "ecosystem", "ekosistema", "umaagos na tubig", "flowing water", "isda", "hipon", "pasayan", "halamang-tubig", "tanom sa tubig", "tubig-tabang", "freshwater"], "fact": {"tl": "Ang ilog ay isang ekosistema ng umaagos na tubig-tabang kung saan nakatira ang mga isda, hipon, at halamang-tubig na nakikinabang sa malinaw at gumagalaw na tubig.", "en": "A river is a flowing freshwater ecosystem where fish, shrimp, and water plants live and depend on its clear, moving water.", "bis": "Ang suba usa ka ekosistema sa nag-agos nga tubig-tabang diin nagpuyo ang mga isda, pasayan, ug tanom sa tubig nga nagsalig sa tin-aw ug naglihok nga tubig."}, "source": "encyclopedia-stable consensus; NRC LS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "germ-spread-disease-transmission-g5", "domain": "LIVING_THINGS", "topic": "how germs spread disease", "grades": [4, 5, 6], "terms": ["mikrobyo", "germ", "bakterya", "virus", "sakit", "disease", "naghahawa", "pagkalat ng sakit", "ubo", "bahin", "hangin", "kamay", "kagaw", "nagtatakod"], "fact": {"tl": "Kumakalat ang mga mikrobyo na nagdudulot ng sakit sa pamamagitan ng ubo, bahin, o maruming kamay, kaya nakakatulong ang madalas na paghuhugas ng kamay para hindi tayo magkasakit.", "en": "Germs that cause disease can spread through coughs, sneezes, or dirty hands, so washing hands often helps keep us from getting sick.", "bis": "Ang mga kagaw nga maoy hinungdan sa sakit makatakod pinaagi sa ubo, bahaon, o hugaw nga kamot, busa ang kanunay nga panghugas sa kamot makatabang nga dili kita magsakit."}, "source": "encyclopedia-stable consensus; DepEd Health/Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "gabi-taro-g4", "domain": "LIVING_THINGS", "topic": "taro (gabi)", "grades": [3, 4, 5], "terms": ["gabi", "taro", "halaman", "tanom", "ugat", "gamot", "tuber", "malalapad na dahon", "lapad nga dahon", "korm", "basa nga yuta", "pagkaon", "kan-onon"], "fact": {"tl": "Ang gabi ay isang halamang may malalapad na dahon na tumutubo sa basang lupa, at ang mataba nitong ugat at dahon ay niluluto bilang pagkain.", "en": "Taro (gabi) is a plant with broad leaves that grows in wet soil, and its starchy root and leaves are cooked as food.", "bis": "Ang gabi usa ka tanom nga adunay lapad nga dahon nga motubo sa basa nga yuta, ug ang baga niini nga gamot ug dahon giluto isip pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gene-on-chromosome-location-g9", "domain": "LIVING_THINGS", "topic": "genes on chromosomes", "grades": [8, 9, 10], "terms": ["gene", "henes", "kromosom", "chromosome", "DNA", "namamana", "minana", "instruksyon", "katangian", "kinaiya", "trait", "panulondon"], "fact": {"tl": "Ang gene ay isang bahagi ng DNA na matatagpuan sa kromosom at nagdadala ng instruksyon para sa isang katangian tulad ng kulay ng mata.", "en": "A gene is a section of DNA located on a chromosome that carries the instructions for a trait such as eye color.", "bis": "Ang gene usa ka bahin sa DNA nga makit-an sa kromosom ug nagdala sa instruksyon alang sa usa ka kinaiya sama sa kolor sa mata."}, "source": "NRC LS3.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "germination-conditions-g5", "domain": "LIVING_THINGS", "topic": "conditions for seed germination", "grades": [4, 5, 6], "terms": ["pagtubo ng buto", "germination", "binhi", "buto", "liso", "tubig", "init", "kainit", "hangin", "oxygen", "kondisyon", "pagsibol", "moturok"], "fact": {"tl": "Para magsibol ang isang buto, kailangan nito ng tubig, sapat na init, at hangin, at kapag kulang ang alinman sa mga ito ay hindi ito tutubo.", "en": "For a seed to germinate, it needs water, enough warmth, and air, and if any of these is missing the seed will not sprout.", "bis": "Aron moturok ang usa ka liso, kinahanglan niini ang tubig, igong kainit, ug hangin, ug kon kulang ang usa niini dili kini moturok."}, "source": "AAAS Benchmarks 5C; DepEd G4-5 Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "germinating-respiration-jar-warmth-g7", "domain": "LIVING_THINGS", "topic": "respiration in germinating seeds", "grades": [6, 7, 8], "terms": ["paghinga", "respiration", "tumutubong buto", "germinating seeds", "init", "kainit", "warmth", "enerhiya", "oxygen", "carbon dioxide", "nagtubo nga liso", "ginhawa"], "fact": {"tl": "Ang tumutubong buto ay humihinga gamit ang oxygen at naglalabas ng init, kaya kapag inilagay sa garapon ay nararamdaman ang bahagyang pag-init.", "en": "Germinating seeds carry out respiration using oxygen and give off heat, so a jar of sprouting seeds feels slightly warm inside.", "bis": "Ang nagtubo nga mga liso naginhawa gamit ang oxygen ug nagbuga ug kainit, busa ang garapon nga adunay nagtubo nga liso mobati nga init sa sulod."}, "source": "encyclopedia-stable consensus; NRC LS1.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "garlic-bawang-g4", "domain": "LIVING_THINGS", "topic": "garlic (bawang)", "grades": [3, 4, 5], "terms": ["bawang", "garlic", "ahos", "halaman", "tanom", "bumbilya", "bulb", "pampalasa", "panimpla", "matapang na amoy", "kusog nga baho", "strong smell", "pagkaon"], "fact": {"tl": "Ang bawang ay isang halamang ang bahaging tumutubo sa ilalim ng lupa ay binubuo ng maliliit na pira na ginagamit na pampalasa dahil sa matapang nitong amoy at lasa.", "en": "Garlic (bawang) is a plant whose underground bulb is made of small cloves used to flavor food because of its strong smell and taste.", "bis": "Ang ahos usa ka tanom nga ang bahin niini sa ilawom sa yuta gilangkoban sa gagmay nga mga tipik nga gigamit nga panimpla tungod sa kusog niini nga baho ug lami."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fruit-dove-punay-g5", "domain": "LIVING_THINGS", "topic": "fruit dove (punay)", "grades": [4, 5, 6], "terms": ["punay", "fruit dove", "kalapati", "salampati", "dove", "ibon", "langgam", "prutas", "makulay", "mabulukon", "colorful", "gubat", "lasang", "naghahasik ng buto"], "fact": {"tl": "Ang punay ay isang makulay na ibong kumakain ng prutas sa kagubatan ng Pilipinas at nakakatulong ito sa pagkalat ng mga buto ng puno.", "en": "The fruit dove (punay) is a colorful bird that eats fruit in Philippine forests and helps spread the seeds of trees.", "bis": "Ang punay usa ka mabulukon nga langgam nga mokaon ug prutas sa kalasangan sa Pilipinas ug nakatabang kini sa pagkatag sa mga liso sa kahoy."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "germination-stages-g4", "domain": "LIVING_THINGS", "topic": "stages of seed germination", "grades": [3, 4, 5], "terms": ["pagtubo ng buto", "germination stages", "binhi", "liso", "ugat", "gamot", "root", "usbong", "turok", "shoot", "dahon", "sprout", "yugto", "ang-ang sa pagtubo"], "fact": {"tl": "Kapag tumutubo ang buto, unang lumalabas ang ugat pababa, pagkatapos ay ang usbong paitaas, hanggang sa magkaroon ito ng unang mga dahon.", "en": "When a seed germinates, the root comes out first and grows down, then the shoot grows up, until the seedling forms its first leaves.", "bis": "Kon moturok ang liso, ang gamot mogula una ug motubo paubos, dayon ang turok motubo pataas, hangtod nga maporma ang una niini nga mga dahon."}, "source": "AAAS Benchmarks 5C; DepEd G4 Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "giant-clam-taklobo-g5", "domain": "LIVING_THINGS", "topic": "giant clam (taklobo)", "grades": [4, 5, 6], "terms": ["taklobo", "giant clam", "kabibe", "shellfish", "talaba", "bahura", "coral reef", "pinakamalaking kabibe", "largest clam", "alga", "algae", "dagat", "molusko"], "fact": {"tl": "Ang taklobo ay ang pinakamalaking kabibe sa mundo na nakatira sa mga bahura at tumutubo nang napakalaki dahil tinutulungan ito ng maliliit na alga na nasa loob ng laman nito.", "en": "The giant clam (taklobo) is the largest clam in the world, living on coral reefs and growing very big with the help of tiny algae inside its body.", "bis": "Ang taklobo mao ang pinakadako nga kabibe sa kalibutan nga nagpuyo sa mga bahura ug motubo ug dako kaayo tungod sa tabang sa gagmay nga alga sulod sa lawas niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "giant-clam-open-mantle-g6", "domain": "LIVING_THINGS", "topic": "giant clam mantle and algae", "grades": [5, 6, 7], "terms": ["taklobo", "giant clam", "mantle", "makulay na laman", "mabulukon nga unod", "alga", "algae", "araw", "adlaw", "sunlight", "pagkain", "symbiosis", "tulong-tulong"], "fact": {"tl": "Bukas ang makulay na laman ng taklobo sa araw para makakuha ng liwanag ang maliliit na algang nakatira rito, at ang algang ito ang gumagawa ng pagkain para sa kabibe.", "en": "The giant clam opens its colorful mantle to the sun so the tiny algae living in it can get light, and these algae make food for the clam.", "bis": "Ginabukas sa taklobo ang mabulukon niini nga unod ngadto sa adlaw aron makadawat ug kahayag ang gagmay nga alga nga nagpuyo niini, ug kini nga alga maoy naghimo ug pagkaon para sa kabibe."}, "source": "encyclopedia-stable consensus; NRC LS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "giant-millipede-g4", "domain": "LIVING_THINGS", "topic": "giant millipede", "grades": [3, 4, 5], "terms": ["giant millipede", "millipede", "uod na maraming paa", "many legs", "maraming paa", "daghang tiil", "gumugulong", "bulok na dahon", "malata nga dahon", "decomposer", "gubat", "lasang"], "fact": {"tl": "Ang giant millipede ay isang hayop na may mahaba at bilog na katawan na may napakaraming paa, at kumakain ito ng mga bulok na dahon kaya nakakatulong itong linisin ang sahig ng gubat.", "en": "The giant millipede is an animal with a long, round body and very many legs that eats rotting leaves, helping clean the forest floor.", "bis": "Ang giant millipede usa ka mananap nga adunay tag-as ug lingin nga lawas nga adunay daghan kaayong tiil, ug mokaon kini ug malata nga dahon busa nakatabang sa paghinlo sa salog sa lasang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ghost-crab-sand-g4", "domain": "LIVING_THINGS", "topic": "ghost crab", "grades": [3, 4, 5], "terms": ["ghost crab", "alimasag", "kasag", "buhangin", "balas", "sand", "dalampasigan", "baybayon", "beach", "lungga", "lungag", "humuhukay", "mabilis tumakbo", "paspas modagan"], "fact": {"tl": "Ang ghost crab ay isang maputlang alimasag na naninirahan sa mga lungga sa buhangin ng dalampasigan at mabilis tumakbo paghabol sa pagkain sa gabi.", "en": "The ghost crab is a pale crab that lives in burrows in the beach sand and runs very fast to chase food at night.", "bis": "Ang ghost crab usa ka maputi nga kasag nga nagpuyo sa mga lungag sa balas sa baybayon ug paspas modagan aron mogukod ug pagkaon sa gabii."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "glow-foods-protector-group-g3", "domain": "LIVING_THINGS", "topic": "Glow foods (protective foods)", "grades": [3, 4, 5], "terms": ["glow foods", "pampakinang na pagkain", "panalipod nga pagkaon", "gulay", "utanon", "prutas", "bitamina", "vitamins", "mineral", "minerals", "malusog na balat", "himsog nga panit", "pananggol sa sakit"], "fact": {"tl": "Ang mga glow foods tulad ng gulay at prutas ay mayaman sa bitamina at mineral na nagpapakinis ng balat at nagpapalakas ng katawan laban sa sakit.", "en": "Glow foods like vegetables and fruits are rich in vitamins and minerals that keep our skin healthy and protect the body from sickness.", "bis": "Ang mga glow foods sama sa utanon ug prutas dato sa bitamina ug mineral nga maghimong himsog sa panit ug manalipod sa lawas batok sa sakit."}, "source": "DepEd Go-Grow-Glow; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "getting-a-vaccine-shot-g6", "domain": "LIVING_THINGS", "topic": "how vaccines work", "grades": [5, 6, 7], "terms": ["bakuna", "vaccine", "iniksiyon", "shot", "depensa", "immune system", "sakit", "mikrobyo", "kagaw", "antibody", "pananggalang sa sakit", "panalipod"], "fact": {"tl": "Ang bakuna ay nagtuturo sa depensa ng katawan na kilalanin ang isang mikrobyo nang maaga, kaya kapag dumating ang totoong sakit ay handa na itong labanan.", "en": "A vaccine teaches the body's defenses to recognize a germ ahead of time, so when the real disease comes the body is ready to fight it.", "bis": "Ang bakuna nagtudlo sa depensa sa lawas nga mailhan ang usa ka kagaw nga sayo, busa kon moabot ang tinuod nga sakit andam na kini nga makigbatok."}, "source": "encyclopedia-stable consensus; DepEd Health/Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "goat-billy-horns-g4", "domain": "LIVING_THINGS", "topic": "billy goat and horns", "grades": [3, 4, 5], "terms": ["kambing", "goat", "kanding", "lalaking kambing", "billy goat", "laki nga kanding", "sungay", "horns", "balbas", "hayop sa bukid", "kumakain ng damo", "mokaon ug sagbot"], "fact": {"tl": "Ang lalaking kambing ay may matigas na sungay na ginagamit nito para makipaglaban at maipagtanggol ang sarili, at kumakain ito ng damo at mga dahon.", "en": "A male goat (billy goat) has hard horns it uses to fight and protect itself, and it eats grass and leaves.", "bis": "Ang laki nga kanding adunay gahi nga sungay nga gigamit niini sa pakig-away ug pagpanalipod sa kaugalingon, ug mokaon kini ug sagbot ug dahon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "golgi-apparatus-closeup-g9", "domain": "LIVING_THINGS", "topic": "Golgi apparatus", "grades": [8, 9, 10], "terms": ["golgi apparatus", "golgi", "selula", "cell", "organelle", "protina", "protein", "nagpapakete", "packaging", "nagbabalot", "nagputos", "nagpadala", "bahin sa selula"], "fact": {"tl": "Ang Golgi apparatus ay isang bahagi ng selula na nagbabalot at nag-aayos ng mga protina bago ipadala ang mga ito sa ibang bahagi ng selula o sa labas nito.", "en": "The Golgi apparatus is a part of the cell that packages and sorts proteins before sending them to other parts of the cell or out of it.", "bis": "Ang Golgi apparatus usa ka bahin sa selula nga nagputos ug nag-areglo sa mga protina sa dili pa kini ipadala sa ubang bahin sa selula o sa gawas niini."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "goldfish-generic-g4", "domain": "LIVING_THINGS", "topic": "goldfish", "grades": [3, 4, 5], "terms": ["goldfish", "isda", "alagang isda", "alaga sa balay", "aquarium", "hasang", "gills", "palikpik", "fins", "tubig", "naglangoy", "naginhawa sa hasang"], "fact": {"tl": "Ang goldfish ay isang alagang isdang humihinga sa tubig gamit ang hasang nito at lumalangoy gamit ang mga palikpik, at madalas itong inaalagaan sa aquarium.", "en": "A goldfish is a pet fish that breathes in water using its gills and swims with its fins, and it is often kept in an aquarium.", "bis": "Ang goldfish usa ka alagang isda nga naginhawa sa tubig gamit ang hasang niini ug nagalangoy gamit ang mga palikpik, ug kasagaran kini gialima sa aquarium."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "go-grow-glow-food-groups-g3", "domain": "LIVING_THINGS", "topic": "Go-Grow-Glow food groups", "grades": [3, 4, 5], "terms": ["go grow glow", "pampalakas", "pampatibay", "pampakinang", "go foods", "grow foods", "glow foods", "kanin", "karne", "gulay", "utanon", "grupo sa pagkaon", "balanseng pagkain"], "fact": {"tl": "Ang mga pagkain ay nahahati sa tatlong grupo: Go foods na nagbibigay enerhiya, Grow foods na bumubuo ng katawan, at Glow foods na nagpoprotekta laban sa sakit.", "en": "Foods are grouped into three: Go foods that give energy, Grow foods that build the body, and Glow foods that protect against sickness.", "bis": "Ang mga pagkaon gibahin sa tulo: Go foods nga naghatag ug kusog, Grow foods nga nagtukod sa lawas, ug Glow foods nga manalipod batok sa sakit."}, "source": "DepEd Go-Grow-Glow; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "goat-kambing-g4", "domain": "LIVING_THINGS", "topic": "goat (kambing)", "grades": [3, 4, 5], "terms": ["kambing", "goat", "kanding", "hayop sa bukid", "damo", "sagbot", "dahon", "gatas", "milk", "alagang hayop", "ngumunguya", "ngisngison"], "fact": {"tl": "Ang kambing ay isang hayop na inaalagaan ng mga tao para sa gatas at karne, at kumakain ito ng damo at dahon na muli nitong ngumunguya.", "en": "The goat (kambing) is an animal raised by people for milk and meat, and it eats grass and leaves which it chews again.", "bis": "Ang kanding usa ka mananap nga gialagaan sa mga tawo para sa gatas ug karne, ug mokaon kini ug sagbot ug dahon nga iyang ngisngison pag-usab."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "good-vs-slouch-posture-g5", "domain": "LIVING_THINGS", "topic": "good sitting posture", "grades": [4, 5, 6], "terms": ["postura", "posture", "tamang pag-upo", "good posture", "yumuko", "pagkubo", "slouch", "gulugod", "spine", "likod", "tuwid na likod", "tul-id nga likod"], "fact": {"tl": "Ang tuwid na pag-upo ay nakakatulong sa malusog na gulugod, samantalang ang madalas na pagyuko ay maaaring magdulot ng sakit sa likod sa paglaon.", "en": "Sitting up straight helps keep the spine healthy, while often slouching can lead to back pain over time.", "bis": "Ang tul-id nga paglingkod makatabang nga himsog ang gulugod, samtang ang kanunay nga pagkubo mahimong moresulta ug sakit sa likod sa kadugayan."}, "source": "encyclopedia-stable consensus; DepEd Health/Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "goat-kid-baby-g3", "domain": "LIVING_THINGS", "topic": "baby goat (kid)", "grades": [3, 4], "terms": ["kambing", "anak ng kambing", "batang kambing", "goat", "kid", "baby goat", "kanding", "nati nga kanding", "gatas", "sungay"], "fact": {"tl": "Ang anak ng kambing ay tinatawag na batang kambing o 'kid', at nakakatayo at nakakatakbo ito ilang oras lamang matapos isilang.", "en": "A baby goat is called a kid, and it can stand and run just a few hours after it is born.", "bis": "Ang nati sa kanding gitawag og 'kid,' ug makatindog ug makadagan kini pipila ka oras human kini matawo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "goose-gansa-g4", "domain": "LIVING_THINGS", "topic": "goose", "grades": [3, 4, 5], "terms": ["gansa", "goose", "ibon", "lumalangoy", "webbed feet", "may ugat na paa", "gansa nga langgam", "lumilipad", "tubig"], "fact": {"tl": "Ang gansa ay malaking ibong-tubig na may basang paa (webbed) para makalangoy, at maingay itong sumisigaw kapag may dumadating na estranghero.", "en": "A goose is a large water bird with webbed feet for swimming, and it honks loudly to warn when a stranger comes near.", "bis": "Ang gansa usa ka dako nga langgam sa tubig nga adunay webbed nga tiil aron makalangoy, ug motingog kini og kusog aron magpasidaan kon adunay dumuduol nga dumuloong."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "grouper-lapu-lapu-g4", "domain": "LIVING_THINGS", "topic": "grouper fish (lapu-lapu)", "grades": [4, 5, 6], "terms": ["lapu-lapu", "grouper", "isda", "bato", "coral reef", "bahura", "manunukob", "isda sa dagat", "lapulapu", "isda nga lapu-lapu"], "fact": {"tl": "Ang lapu-lapu ay isdang naninirahan malapit sa mga bato at bahura sa dagat, at isa itong manunukob na lumululon ng buong mas maliit na isda.", "en": "The grouper (lapu-lapu) is a fish that lives near rocks and coral reefs, and it is a predator that swallows smaller fish whole.", "bis": "Ang lapu-lapu usa ka isda nga nagpuyo duol sa mga bato ug bahura sa dagat, ug usa kini ka manunukob nga magtulon og tibuok nga gagmay nga isda."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gourami-gurami-g4", "domain": "LIVING_THINGS", "topic": "gourami fish", "grades": [4, 5, 6], "terms": ["gurami", "gourami", "isda", "tubig-tabang", "freshwater fish", "labyrinth organ", "humihinga ng hangin", "isda sa lim-aw", "isda nga gurami", "tab-ang nga tubig"], "fact": {"tl": "Ang gurami ay isdang tubig-tabang na may natatanging bahaging tinatawag na labyrinth organ na nagpapahintulot itong huminga ng hangin mula sa ibabaw ng tubig.", "en": "The gourami is a freshwater fish with a special labyrinth organ that lets it breathe air from the water's surface.", "bis": "Ang gurami usa ka isda sa tab-ang nga tubig nga adunay espesyal nga bahin nga gitawag og labyrinth organ nga magtugot niini nga makaginhawa og hangin gikan sa ibabaw sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "go-foods-energy-group-g4", "domain": "LIVING_THINGS", "topic": "Go foods (energy-giving food group)", "grades": [3, 4, 5], "terms": ["Go foods", "pampalakas", "kanin", "tinapay", "carbohydrates", "enerhiya", "pagkaing nagbibigay-lakas", "go nga pagkaon", "kusog", "humay", "tinapay nga pagkaon"], "fact": {"tl": "Ang mga Go food gaya ng kanin, tinapay, at patatas ay mayaman sa carbohydrates na nagbibigay ng enerhiya para makagalaw at makapaglaro tayo.", "en": "Go foods like rice, bread, and potatoes are rich in carbohydrates that give us energy to move and play.", "bis": "Ang mga Go nga pagkaon sama sa kan-on, tinapay, ug patatas adunay daghang carbohydrates nga naghatag og kusog aron kita makalihok ug makadula."}, "source": "DepEd Health/Science nutrition (GMD food groups); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "guard-cells-stomata-g7", "domain": "LIVING_THINGS", "topic": "guard cells and stomata", "grades": [6, 7, 8], "terms": ["guard cells", "stomata", "butas sa dahon", "guard cell", "bantay na selula", "pores", "dahon", "carbon dioxide", "oxygen", "selula nga magbantay", "lungag sa dahon", "stoma"], "fact": {"tl": "Ang guard cells ay magkapares na selula sa dahon na bumubukas at sumasara ng maliliit na butas na tinatawag na stomata upang makapasok ang carbon dioxide at makalabas ang tubig at oxygen.", "en": "Guard cells are paired cells in a leaf that open and close tiny pores called stomata to let carbon dioxide in and water and oxygen out.", "bis": "Ang guard cells mao ang parisan nga mga selula sa dahon nga magbukas ug magsira sa gagmayng lungag nga gitawag og stomata aron makasulod ang carbon dioxide ug makagawas ang tubig ug oxygen."}, "source": "AAAS Benchmarks 5C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "grow-foods-builder-group-g4", "domain": "LIVING_THINGS", "topic": "Grow foods (body-building food group)", "grades": [3, 4, 5], "terms": ["Grow foods", "pampatubo", "protina", "protein", "isda", "itlog", "karne", "gatas", "munggo", "pagkaing pampalaki ng katawan", "grow nga pagkaon", "protina nga pagkaon"], "fact": {"tl": "Ang mga Grow food gaya ng isda, itlog, karne, at munggo ay mayaman sa protina na tumutulong palakihin at ayusin ang mga bahagi ng ating katawan.", "en": "Grow foods like fish, eggs, meat, and beans are rich in protein that helps build and repair our bodies.", "bis": "Ang mga Grow nga pagkaon sama sa isda, itlog, karne, ug munggo adunay daghang protina nga makatabang sa pagpadako ug pag-ayo sa mga bahin sa atong lawas."}, "source": "DepEd Health/Science nutrition (GMD food groups); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "guinea-pig-g3", "domain": "LIVING_THINGS", "topic": "guinea pig", "grades": [3, 4], "terms": ["guinea pig", "alagang hayop", "daga", "rodent", "kumakain ng gulay", "ngumunguya", "herbivore", "alagang guinea pig", "pet", "mananap"], "fact": {"tl": "Ang guinea pig ay maliit na alagang hayop na uri ng rodent (kapamilya ng daga) na kumakain lamang ng halaman gaya ng gulay at damo.", "en": "A guinea pig is a small pet rodent (a relative of mice) that eats only plants like vegetables and grass.", "bis": "Ang guinea pig usa ka gamay nga binuhing hayop nga klase sa rodent (paryente sa ilaga) nga mokaon lamang og tanom sama sa utanon ug sagbot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "habitat-aerial-g4", "domain": "LIVING_THINGS", "topic": "aerial habitat (air)", "grades": [3, 4, 5], "terms": ["aerial habitat", "tirahan sa himpapawid", "hangin", "lumilipad", "ibon", "insekto", "paniki", "pakpak", "puluy-anan sa kahanginan", "naglupad", "tirahan sa hangin"], "fact": {"tl": "Ang aerial habitat ay ang tirahan sa himpapawid kung saan gumugugol ng karamihan ng oras sa paglipad ang mga hayop gaya ng ibon, paniki, at insekto na may pakpak.", "en": "An aerial habitat is the air, where animals like birds, bats, and winged insects spend much of their time flying.", "bis": "Ang aerial habitat mao ang puluy-anan sa kahanginan diin ang mga mananap sama sa langgam, kabog, ug insekto nga adunay pako mogahin sa kadaghanan sa ilang panahon sa paglupad."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gulaman-agar-seaweed-g5", "domain": "MATTER", "topic": "gulaman / agar from seaweed", "grades": [4, 5, 6], "terms": ["gulaman", "agar", "damong-dagat", "seaweed", "gel", "namumuo", "jelly", "lumalamig", "gugulaman", "lapok sa dagat", "agar-agar", "tubig"], "fact": {"tl": "Ang gulaman ay gawa sa agar na kinukuha mula sa damong-dagat, at namumuo itong parang jelly kapag pinakuluan sa tubig at saka pinalamig.", "en": "Gulaman is made from agar taken from seaweed, and it sets into a jelly when it is boiled in water and then cooled.", "bis": "Ang gulaman gihimo gikan sa agar nga gikuha sa damong-dagat, ug mogahi kini nga morag jelly kon lutoon sa tubig ug human pabugnawon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "guava-leaf-sprig-g5", "domain": "LIVING_THINGS", "topic": "guava leaves", "grades": [4, 5, 6], "terms": ["bayabas", "dahon ng bayabas", "guava leaves", "guava", "panghugas", "sugat", "gamot", "bayabas nga dahon", "tambal", "halaman", "pamahid"], "fact": {"tl": "Ang dahon ng bayabas ay ginagamit sa tradisyunal na panggamot bilang panghugas o pampalinis ng sugat dahil naniniwalang nakakatulong itong maiwasan ang impeksyon.", "en": "Guava leaves are used in traditional medicine as a wash to clean wounds, because they are believed to help prevent infection.", "bis": "Ang dahon sa bayabas gigamit sa tradisyonal nga tambal isip panghugas o panglimpyo sa samad kay gituohan nga makatabang kini sa pagpugong sa impeksyon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gumamela-g4", "domain": "LIVING_THINGS", "topic": "gumamela (hibiscus)", "grades": [3, 4, 5], "terms": ["gumamela", "hibiscus", "bulaklak", "halaman", "pollen", "pulot", "bubuyog", "ornamental", "tanom nga bulak", "bulak", "stamen", "talulot"], "fact": {"tl": "Ang gumamela ay isang malaki at makulay na bulaklak na karaniwang itinatanim sa hardin, at may mahabang gitnang bahagi (stamen) na nagdadala ng pollen.", "en": "The gumamela (hibiscus) is a large, colorful flower often grown in gardens, with a long central stalk (the stamen) that carries pollen.", "bis": "Ang gumamela usa ka dako ug mabulukon nga bulak nga kasagarang gitanom sa tanaman, ug adunay taas nga sentro nga bahin (stamen) nga nagdala og pollen."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "habitat-garden-g3", "domain": "LIVING_THINGS", "topic": "garden habitat", "grades": [3, 4], "terms": ["hardin", "garden", "tirahan", "habitat", "halaman", "uod", "bubuyog", "paru-paro", "tanaman", "puluy-anan", "insekto", "tanom"], "fact": {"tl": "Ang hardin ay isang tirahan kung saan magkakasamang nabubuhay ang mga halaman at maliliit na hayop gaya ng uod, paru-paro, at bubuyog.", "en": "A garden is a habitat where plants and small animals like worms, butterflies, and bees live together.", "bis": "Ang tanaman usa ka puluy-anan diin ang mga tanom ug gagmayng mananap sama sa ulod, alibangbang, ug putyukan magpuyo nga magkauban."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "guso-seaweed-g5", "domain": "LIVING_THINGS", "topic": "guso seaweed", "grades": [4, 5, 6], "terms": ["guso", "seaweed", "damong-dagat", "Eucheuma", "carrageenan", "kinilaw", "ensalada", "lapok sa dagat", "damong dagat", "tinanom sa dagat", "halaman sa dagat"], "fact": {"tl": "Ang guso ay isang uri ng damong-dagat na tumutubo sa mababaw na bahura, at kinakain ito bilang ensalada o kinilaw sa maraming baybaying bayan sa Pilipinas.", "en": "Guso is a kind of seaweed that grows on shallow reefs, and it is eaten as a salad in many coastal towns in the Philippines.", "bis": "Ang guso usa ka matang sa damong-dagat nga motubo sa mabaw nga bahura, ug ginakaon kini isip ensalada sa daghang baybayon nga lungsod sa Pilipinas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "habitat-aquatic-g4", "domain": "LIVING_THINGS", "topic": "aquatic habitat (water)", "grades": [3, 4, 5], "terms": ["aquatic habitat", "tirahan sa tubig", "tubig", "isda", "water", "hasang", "gills", "halamang-tubig", "puluy-anan sa tubig", "mananap sa tubig", "lim-aw", "dagat"], "fact": {"tl": "Ang aquatic habitat ay tirahang nasa tubig gaya ng ilog, lawa, at dagat, kung saan nakatira ang mga isda at iba pang hayop na nakakahinga gamit ang hasang.", "en": "An aquatic habitat is a home in water such as a river, lake, or sea, where fish and other animals that breathe through gills live.", "bis": "Ang aquatic habitat usa ka puluy-anan sa tubig sama sa suba, linaw, ug dagat, diin nagpuyo ang mga isda ug uban pang mananap nga makaginhawa pinaagi sa hasang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "guyabano-soursop-g5", "domain": "LIVING_THINGS", "topic": "guyabano (soursop)", "grades": [4, 5, 6], "terms": ["guyabano", "soursop", "prutas", "berdeng prutas", "tinik", "puti ang laman", "maasim-tamis", "bunga", "prutas nga guyabano", "punoan", "halaman"], "fact": {"tl": "Ang guyabano ay tropikal na prutas na may berde at matinik na balat at malambot na puting laman na maasim-tamis ang lasa.", "en": "The guyabano (soursop) is a tropical fruit with a green, spiny skin and soft white flesh that tastes sweet and a little sour.", "bis": "Ang guyabano usa ka tropikal nga prutas nga adunay berde ug tunokon nga panit ug humok nga puti nga unod nga tam-is ug gamay nga aslom ang lami."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "habitat-seashore-g4", "domain": "LIVING_THINGS", "topic": "seashore habitat", "grades": [3, 4, 5], "terms": ["dalampasigan", "baybayin", "seashore", "tabing-dagat", "alon", "kabibe", "alimango", "tirahan sa baybay", "baybayon", "puluy-anan sa baybayon", "balas", "bato"], "fact": {"tl": "Ang dalampasigan ay tirahan sa pagitan ng lupa at dagat kung saan nakatira ang mga hayop gaya ng kabibe, alimango, at maliliit na nilalang na kayang magtago kapag humuhupa ang tubig.", "en": "The seashore is a habitat between land and sea where animals like shells, crabs, and small creatures live and can hide when the tide goes out.", "bis": "Ang baybayon usa ka puluy-anan taliwala sa yuta ug dagat diin nagpuyo ang mga mananap sama sa kinhason, kasag, ug gagmayng binuhat nga makatago kon mohunas ang tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "habitat-rice-field-g4", "domain": "LIVING_THINGS", "topic": "rice field habitat", "grades": [3, 4, 5], "terms": ["palayan", "rice field", "bukid", "tirahan", "palaka", "ibong tagak", "susô", "tutubi", "uma", "humayan", "puluy-anan", "tubig", "palay"], "fact": {"tl": "Ang palayan ay isang tirahang puno ng tubig at palay kung saan dumarami ang mga hayop gaya ng palaka, susô, tutubi, at ibong tagak na kumakain ng mga insekto.", "en": "A rice field is a watery habitat full of rice plants where animals like frogs, snails, dragonflies, and egrets that eat insects thrive.", "bis": "Ang humayan usa ka puluy-anan nga puno sa tubig ug humay diin modaghan ang mga mananap sama sa baki, kuhol, alindahaw, ug talabong nga mokaon og insekto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "habitat-forest-g4", "domain": "LIVING_THINGS", "topic": "forest habitat", "grades": [3, 4, 5], "terms": ["gubat", "forest", "kakahuyan", "tirahan", "puno", "ibon", "unggoy", "habitat", "lasang", "kalasangan", "puluy-anan", "kahoy", "mananap"], "fact": {"tl": "Ang gubat ay tirahang puno ng matataas na puno na nagbibigay ng pagkain at tahanan sa maraming hayop gaya ng ibon, unggoy, at insekto.", "en": "A forest is a habitat full of tall trees that give food and shelter to many animals like birds, monkeys, and insects.", "bis": "Ang lasang usa ka puluy-anan nga puno sa tag-as nga kahoy nga naghatag og pagkaon ug puy-anan sa daghang mananap sama sa langgam, unggoy, ug insekto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "habitat-pond-g4", "domain": "LIVING_THINGS", "topic": "pond habitat", "grades": [3, 4, 5], "terms": ["lawa", "pond", "lim-aw", "tirahan", "palaka", "isda", "lumot", "lily pad", "tubig-tabang", "linaw", "puluy-anan", "tubig", "halamang-tubig"], "fact": {"tl": "Ang lawa ay isang maliit na tipak ng nakatigil na tubig-tabang kung saan nakatira ang mga palaka, isda, at halamang-tubig gaya ng lumot at water lily.", "en": "A pond is a small body of still freshwater where frogs, fish, and water plants like algae and water lilies live.", "bis": "Ang lim-aw usa ka gamay nga walay agos nga tab-ang nga tubig diin nagpuyo ang mga baki, isda, ug tanom sa tubig sama sa lumot ug water lily."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "habitat-mangrove-g5", "domain": "LIVING_THINGS", "topic": "mangrove habitat", "grades": [4, 5, 6], "terms": ["bakawan", "mangrove", "tirahan", "ugat", "alat na tubig", "alimango", "isda", "baybayin", "bakhaw", "puluy-anan", "gamot", "tabing-dagat"], "fact": {"tl": "Ang bakawan ay kakahuyan na tumutubo sa alat na tubig sa pagitan ng lupa at dagat, at ang mataas nilang ugat ay tirahan at taguan ng maliliit na isda at alimango.", "en": "A mangrove is a forest that grows in salty water between land and sea, and its tangled roots are a home and hiding place for small fish and crabs.", "bis": "Ang bakhaw usa ka kalasangan nga motubo sa parat nga tubig taliwala sa yuta ug dagat, ug ang ilang tag-as nga gamot maoy puluy-anan ug tagoanan sa gagmayng isda ug kasag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "habitat-terrestrial-g4", "domain": "LIVING_THINGS", "topic": "terrestrial habitat (land)", "grades": [3, 4, 5], "terms": ["terrestrial habitat", "tirahan sa lupa", "lupa", "land", "kalupaan", "hayop sa lupa", "puluy-anan sa yuta", "yuta", "mananap sa lupa", "halaman", "tuyo nga yuta"], "fact": {"tl": "Ang terrestrial habitat ay tirahang nasa lupa kung saan naninirahan ang mga hayop at halamang nabubuhay sa tuyong lupa, gaya ng aso, ahas, at puno.", "en": "A terrestrial habitat is a home on land, where animals and plants that live on dry ground, such as dogs, snakes, and trees, are found.", "bis": "Ang terrestrial habitat usa ka puluy-anan sa yuta diin nagpuyo ang mga mananap ug tanom nga buhi sa mala nga yuta, sama sa iro, halas, ug kahoy."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "habitat-ocean-g4", "domain": "LIVING_THINGS", "topic": "ocean habitat", "grades": [3, 4, 5], "terms": ["karagatan", "ocean", "dagat", "alat na tubig", "isda", "balyena", "pating", "coral", "kadagatan", "parat nga tubig", "puluy-anan sa dagat", "tubig"], "fact": {"tl": "Ang karagatan ay napakalawak na tirahan ng alat na tubig kung saan nakatira ang maraming hayop gaya ng isda, pating, balyena, at coral.", "en": "The ocean is a vast saltwater habitat where many animals like fish, sharks, whales, and corals live.", "bis": "Ang kadagatan usa ka halapad kaayo nga puluy-anan sa parat nga tubig diin nagpuyo ang daghang mananap sama sa isda, iho, balyena, ug coral."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "habitat-rainforest-g5", "domain": "LIVING_THINGS", "topic": "rainforest habitat", "grades": [4, 5, 6], "terms": ["rainforest", "gubat na ulan", "kagubatan", "tirahan", "maraming ulan", "biodiversity", "ibon", "unggoy", "lasang nga ulanon", "puluy-anan", "daghang mananap", "kahoy"], "fact": {"tl": "Ang rainforest ay napakasalimuot na gubat na umuulan nang madalas, at ito ang tirahan ng pinakamaraming uri ng halaman at hayop sa lupa.", "en": "A rainforest is a thick forest where it rains very often, and it is the habitat of the greatest variety of plants and animals on land.", "bis": "Ang rainforest usa ka baga kaayo nga lasang nga kanunayng ulanon, ug mao kini ang puluy-anan sa pinakadaghang matang sa tanom ug mananap sa yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hamster-g3", "domain": "LIVING_THINGS", "topic": "hamster", "grades": [3, 4], "terms": ["hamster", "alagang hayop", "daga", "rodent", "cheek pouches", "pisngi", "nag-iimbak ng pagkain", "pet", "binuhi nga hamster", "mananap", "ngumunguya"], "fact": {"tl": "Ang hamster ay maliit na alagang rodent na may pisnging parang bag (cheek pouches) kung saan naglalagay ito ng pagkain para dalhin sa pugad.", "en": "A hamster is a small pet rodent with bag-like cheek pouches where it stuffs food to carry back to its nest.", "bis": "Ang hamster usa ka gamay nga binuhing rodent nga adunay aping nga morag bag (cheek pouches) diin magsulod kini og pagkaon aron dad-on balik sa iyang salag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "habitat-river-g4", "domain": "LIVING_THINGS", "topic": "river habitat", "grades": [3, 4, 5], "terms": ["ilog", "river", "suba", "tirahan", "umaagos na tubig", "isda", "hipon", "tubig-tabang", "puluy-anan", "tab-ang nga tubig", "nagdagayday", "tubig"], "fact": {"tl": "Ang ilog ay tirahan ng umaagos na tubig-tabang kung saan nakatira ang mga isda, hipon, at iba pang hayop na nakakalaban sa agos ng tubig.", "en": "A river is a flowing freshwater habitat where fish, shrimp, and other animals that can handle the current live.", "bis": "Ang suba usa ka puluy-anan sa nagdagayday nga tab-ang nga tubig diin nagpuyo ang mga isda, pasayan, ug uban pang mananap nga makasugakod sa sulog sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hand-palm-g4", "domain": "LIVING_THINGS", "topic": "the human hand", "grades": [3, 4, 5], "terms": ["kamay", "palad", "hand", "palm", "daliri", "hinlalaki", "buto", "humahawak", "kamot", "palad sa kamot", "tudlo", "kalansay"], "fact": {"tl": "Ang kamay ng tao ay may limang daliri kabilang ang hinlalaki na kayang humarap sa ibang daliri, kaya kaya nitong humawak nang mahigpit sa mga bagay.", "en": "The human hand has five fingers including a thumb that can face the other fingers, which lets it grip objects firmly.", "bis": "Ang kamot sa tawo adunay lima ka tudlo apil ang kumagko nga makaatubang sa ubang tudlo, mao nga makakupot kini og hugot sa mga butang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "handwashing-steps-sequence-g3", "domain": "LIVING_THINGS", "topic": "handwashing steps", "grades": [3, 4, 5], "terms": ["paghuhugas ng kamay", "handwashing", "sabon", "tubig", "mikrobyo", "germs", "kalusugan", "paghugas sa kamot", "limpyo", "sabon ug tubig", "kuskos", "sakit"], "fact": {"tl": "Ang tamang paghuhugas ng kamay ay paggamit ng sabon at tubig, pagkuskos nang hindi bababa sa 20 segundo, at pagbabanlaw upang maalis ang mga mikrobyong nagdadala ng sakit.", "en": "Proper handwashing means using soap and water, scrubbing for at least 20 seconds, and rinsing to remove germs that cause sickness.", "bis": "Ang husto nga paghugas sa kamot mao ang paggamit og sabon ug tubig, pagkuskos sa dili moubos sa 20 ka segundo, ug paghugas aron mawala ang mga mikrobyo nga maoy hinungdan sa sakit."}, "source": "WHO/DepEd health hygiene; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hawk-lawin-g4", "domain": "LIVING_THINGS", "topic": "hawk (lawin)", "grades": [3, 4, 5], "terms": ["lawin", "hawk", "ibong mandaragit", "raptor", "matalim na kuko", "talon", "matalas ang paningin", "lumilipad", "agila", "langgam nga mandadagit", "kuko", "manunukob"], "fact": {"tl": "Ang lawin ay isang ibong mandaragit na may napakatalas na paningin at matatalim na kuko (talon) na ginagamit nitong manghuli ng maliliit na hayop mula sa himpapawid.", "en": "A hawk (lawin) is a bird of prey with very sharp eyesight and strong talons that it uses to catch small animals from the air.", "bis": "Ang lawin usa ka langgam nga mandadagit nga adunay hait kaayo nga panan-aw ug talinis nga kuko nga gamiton niini sa pagdakop og gagmayng mananap gikan sa kahanginan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "heart-blood-loop-body-g6", "domain": "LIVING_THINGS", "topic": "heart and blood circulation", "grades": [5, 6, 7], "terms": ["puso", "dugo", "heart", "blood", "sirkulasyon", "ugat", "bombang", "oxygen", "circulation", "kasingkasing", "dugo sa lawas", "pintog", "ugat sa dugo"], "fact": {"tl": "Ang puso ay isang kalamnang bombang umiikot ng dugo sa buong katawan sa pamamagitan ng mga ugat, na nagdadala ng oxygen at pagkain sa bawat bahagi.", "en": "The heart is a muscle that pumps blood in a loop around the whole body through blood vessels, carrying oxygen and food to every part.", "bis": "Ang kasingkasing usa ka kaunoran nga magbomba sa dugo libot sa tibuok lawas pinaagi sa mga ugat, nga magdala og oxygen ug pagkaon sa matag bahin."}, "source": "AAAS Benchmarks 6C; NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "healthy-baon-prep-scene-g4", "domain": "LIVING_THINGS", "topic": "balanced baon meal preparation", "grades": [3, 4, 5], "terms": ["baon", "masustansyang pagkain", "gulay", "prutas", "kanin", "isda", "balanseng pagkain", "balanced meal", "healthy lunchbox", "nutrition", "utanon", "kan-on", "himsog nga pagkaon", "panghatag baon"], "fact": {"tl": "Ang masustansyang baon na may kanin, gulay, prutas, at isda o itlog ay nagbibigay ng lakas at sustansyang kailangan ng katawan para mag-aral at maglaro.", "en": "A healthy baon with rice, vegetables, fruit, and fish or egg gives the body the energy and nutrients it needs to study and play.", "bis": "Ang himsog nga baon nga adunay kan-on, utanon, prutas, ug isda o itlog naghatag ug kusog ug sustansya nga gikinahanglan sa lawas aron makakat-on ug makadula."}, "source": "DepEd MATATAG Science Health/Nutrition; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "healthy-snack-fruit-vs-chips-g4", "domain": "LIVING_THINGS", "topic": "choosing fruit over junk food snacks", "grades": [3, 4, 5], "terms": ["prutas", "chips", "meryenda", "masustansyang meryenda", "junk food", "asin", "asukal", "fruit snack", "healthy snack", "vitamins", "tam-is", "himsog nga meryenda"], "fact": {"tl": "Mas mainam pumili ng prutas kaysa chips bilang meryenda dahil ang prutas ay may bitamina at hibla, samantalang ang chips ay maraming asin at taba.", "en": "Choosing fruit instead of chips for a snack is healthier because fruit has vitamins and fiber, while chips are high in salt and fat.", "bis": "Mas maayo nga mopili ug prutas kaysa chips isip meryenda kay ang prutas adunay bitamina ug fiber, samtang ang chips daghan ug asin ug tambok."}, "source": "DepEd MATATAG Science Health/Nutrition; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "goat-grazing-backyard-g3", "domain": "LIVING_THINGS", "topic": "goats are grass-eating farm animals", "grades": [3, 4], "terms": ["kambing", "damo", "halaman", "alagang hayop", "herbivore", "goat", "grazing", "backyard animal", "kanding", "sagbot", "balili", "mananap nga mokaon ug sagbot", "alaga"], "fact": {"tl": "Ang kambing ay alagang hayop na herbivore o pawang halaman ang kinakain, kaya madalas itong makitang nanginginain ng damo sa bakuran o parang.", "en": "A goat is a herbivore farm animal that eats only plants, so it is often seen grazing on grass in the backyard or field.", "bis": "Ang kanding usa ka alagang mananap nga herbivore o tanom lang ang gikaon, mao nga kanunay kini makita nga nagsibsib ug sagbot sa nataran o kapatagan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "harvestman-daddylonglegs-g5", "domain": "LIVING_THINGS", "topic": "harvestman daddy longlegs arachnid", "grades": [4, 5, 6], "terms": ["harvestman", "daddy longlegs", "gagamba", "arachnid", "mahabang binti", "walang lason", "hindi gagamba", "spider", "arachnida", "taas nga tiil", "lawalawa", "wala'y hilo", "walo ka tiil"], "fact": {"tl": "Ang harvestman o daddy longlegs ay arachnid na may walong mahahabang binti, ngunit hindi ito tunay na gagamba dahil hindi ito gumagawa ng sapot at walang kamandag.", "en": "The harvestman, or daddy longlegs, is an arachnid with eight long legs, but it is not a true spider because it makes no web and has no venom.", "bis": "Ang harvestman o daddy longlegs usa ka arachnid nga adunay walo ka taas nga tiil, apan dili kini tinuod nga lawa-lawa kay wala kini magbuhat ug sapot ug walay hilo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "healthy-lungs-vs-smoke-g6", "domain": "LIVING_THINGS", "topic": "smoking harms the lungs", "grades": [5, 6, 7], "terms": ["baga", "usok", "sigarilyo", "paninigarilyo", "malusog na baga", "lungs", "smoke", "tobacco", "respiratory", "oksiheno", "aso", "himsog nga baga", "panghuyop"], "fact": {"tl": "Ang malusog na baga ay malinis at kayang sumipsip ng maraming oksiheno, ngunit ang usok ng sigarilyo ay nakakasira nito at nagpapahina ng paghinga.", "en": "Healthy lungs are clean and can absorb plenty of oxygen, but cigarette smoke damages them and makes breathing harder.", "bis": "Ang himsog nga baga limpyo ug makahimo ug pagsuyop ug daghang oksiheno, apan ang aso sa sigarilyo makadaot niini ug makapaluya sa pagginhawa."}, "source": "DepEd MATATAG Science; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "heart-four-chambers-flow-g6", "domain": "LIVING_THINGS", "topic": "the heart has four chambers", "grades": [5, 6, 7], "terms": ["puso", "silid ng puso", "atrium", "ventricle", "dugo", "four chambers", "heart chambers", "atria", "ventrikulo", "kasingkasing", "lawak sa kasingkasing"], "fact": {"tl": "Ang puso ng tao ay may apat na silid—dalawang atrium sa itaas at dalawang ventricle sa ibaba—na nagtutulungan para itulak ang dugo sa buong katawan.", "en": "The human heart has four chambers—two atria on top and two ventricles below—that work together to pump blood throughout the body.", "bis": "Ang kasingkasing sa tawo adunay upat ka lawak—duha ka atrium sa ibabaw ug duha ka ventricle sa ubos—nga magtinabangay sa pagduso sa dugo sa tibuok lawas."}, "source": "NRC LS1.A; DepEd MATATAG Science; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "healthy-plate-with-fish-rice-g4", "domain": "LIVING_THINGS", "topic": "a balanced plate of rice fish and vegetables", "grades": [3, 4, 5], "terms": ["pinggan", "kanin", "isda", "gulay", "balanseng pagkain", "balanced plate", "go grow glow", "nutrition", "protina", "kan-on", "utanon", "himsog nga plato", "balanse nga pagkaon"], "fact": {"tl": "Ang balanseng pinggan na may kanin, isda, at gulay ay nagbibigay ng enerhiya mula sa kanin, protina mula sa isda, at bitamina mula sa gulay.", "en": "A balanced plate of rice, fish, and vegetables gives energy from the rice, protein from the fish, and vitamins from the vegetables.", "bis": "Ang balanse nga plato nga adunay kan-on, isda, ug utanon naghatag ug kusog gikan sa kan-on, protina gikan sa isda, ug bitamina gikan sa utanon."}, "source": "DepEd MATATAG Science Health/Nutrition; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "heart-rate-after-exercise-g6", "domain": "LIVING_THINGS", "topic": "heart rate rises during exercise", "grades": [5, 6, 7], "terms": ["tibok ng puso", "ehersisyo", "pintig", "bilis ng tibok", "heart rate", "exercise", "pulse", "oksiheno", "kalamnan", "pitik sa kasingkasing", "pamitik", "kusog nga pitik", "oksiheno sa kaunoran"], "fact": {"tl": "Tumataas ang bilis ng tibok ng puso habang nag-eehersisyo dahil kailangan ng mga kalamnan ng mas maraming oksiheno at enerhiya.", "en": "Your heart rate goes up during exercise because your muscles need more oxygen and energy.", "bis": "Mosaka ang kapaspas sa pitik sa kasingkasing samtang nag-ehersisyo kay nagkinahanglan ang kaunoran ug mas daghang oksiheno ug kusog."}, "source": "NRC LS1.A; DepEd MATATAG Science; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "healthy-vs-decayed-tooth-g4", "domain": "LIVING_THINGS", "topic": "tooth decay from sugar and poor cleaning", "grades": [3, 4, 5], "terms": ["ngipin", "bulok na ngipin", "tooth decay", "cavity", "asukal", "pagsisipilyo", "healthy tooth", "bacteria", "enamel", "ngipon", "bun-og nga ngipon", "tam-is", "pagsipilyo", "lungib sa ngipon"], "fact": {"tl": "Ang ngipin ay nasisira at nagkakaroon ng butas kapag ang asukal at bakterya ay naiwan dito, kaya mahalaga ang regular na pagsisipilyo.", "en": "A tooth decays and forms cavities when sugar and bacteria are left on it, so brushing regularly is important.", "bis": "Ang ngipon madaot ug magkaadunay lungib kung ang tam-is ug bakterya mabilin niini, mao nga importante ang regular nga pagsipilyo."}, "source": "DepEd MATATAG Science Health; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "heart-pumping-cycle-g6", "domain": "LIVING_THINGS", "topic": "the heart pumps blood in a repeating cycle", "grades": [5, 6, 7], "terms": ["puso", "pagbomba ng dugo", "tibok", "pintig", "dugo", "heart pump", "pumping cycle", "circulation", "pulso", "kasingkasing", "pagbomba sa dugo", "pitik", "sirkulasyon sa dugo"], "fact": {"tl": "Ang puso ay paulit-ulit na bumobomba—nagrerelaks para mapuno ng dugo, pagkatapos ay sumisikip para itulak ang dugo palabas patungo sa buong katawan.", "en": "The heart pumps in a repeating cycle—relaxing to fill with blood, then squeezing to push the blood out to the whole body.", "bis": "Ang kasingkasing nagbomba sa balikbalik nga siklo—mag-relaks aron mapuno ug dugo, dayon mopuga aron iduso ang dugo paingon sa tibuok lawas."}, "source": "NRC LS1.A; DepEd MATATAG Science; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "heron-flight-tagak-g4", "domain": "LIVING_THINGS", "topic": "herons fly with long necks and wide wings", "grades": [3, 4, 5], "terms": ["tagak", "lumilipad na ibon", "mahabang leeg", "pakpak", "heron", "flight", "wading bird", "wetland", "langgam", "taas nga liog", "pako", "naglupad nga langgam"], "fact": {"tl": "Ang tagak ay lumilipad gamit ang malalapad nitong pakpak habang nakatupi ang mahabang leeg, at madalas itong namamahay malapit sa tubig.", "en": "A heron flies with its wide wings while folding its long neck, and it usually lives near water.", "bis": "Ang tagak naglupad gamit ang lapad nga mga pako samtang gipilo ang taas nga liog, ug kasagaran kini magpuyo duol sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hilot-herbal-medicine-scene-g6", "domain": "LIVING_THINGS", "topic": "traditional herbal medicine from plants", "grades": [5, 6, 7], "terms": ["halamang gamot", "herbal", "lagundi", "sambong", "hilot", "tradisyunal na gamot", "herbal medicine", "medicinal plants", "tanglad", "tambal nga tanom", "tambong", "tradisyonal nga tambal"], "fact": {"tl": "Maraming halamang gamot sa Pilipinas, gaya ng lagundi at sambong, ang ginagamit bilang tradisyunal na gamot dahil may mga sangkap silang nakakatulong sa katawan.", "en": "Many Philippine medicinal plants, like lagundi and sambong, are used as traditional medicine because they contain substances that can help the body.", "bis": "Daghang tambal nga tanom sa Pilipinas, sama sa lagundi ug tambong, ang gigamit isip tradisyonal nga tambal kay adunay sila mga sangkap nga makatabang sa lawas."}, "source": "DepEd MATATAG Science; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "homeostasis-feedback-g9", "domain": "LIVING_THINGS", "topic": "homeostasis keeps the body stable", "grades": [8, 9, 10], "terms": ["homeostasis", "balanse ng katawan", "feedback", "temperatura", "pawis", "regulation", "internal balance", "panatag na kalagayan", "balanse sa lawas", "singot", "pagmintinar sa balanse"], "fact": {"tl": "Ang homeostasis ay ang pagpapanatili ng katawan ng matatag na kalagayan—gaya ng temperatura at tubig—gamit ang feedback, halimbawa ang pagpapawis kapag mainit.", "en": "Homeostasis is how the body keeps a stable internal state—such as temperature and water—using feedback, like sweating when it is hot.", "bis": "Ang homeostasis mao ang pagmintinar sa lawas sa lig-on nga kahimtang sulod—sama sa temperatura ug tubig—pinaagi sa feedback, sama sa pagsingot kung init."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "heron-tagak-g3", "domain": "LIVING_THINGS", "topic": "the heron is a long-legged wading bird", "grades": [3, 4], "terms": ["tagak", "ibon", "mahabang binti", "mahabang leeg", "isda", "heron", "wading bird", "marsh", "langgam", "taas nga tiil", "taas nga liog", "lamakan"], "fact": {"tl": "Ang tagak ay ibong may mahabang binti at leeg na naninirahan malapit sa palayan, ilog, at latian, at kumakain ito ng isda at maliliit na hayop.", "en": "The heron is a bird with long legs and a long neck that lives near rice fields, rivers, and marshes, and it eats fish and small animals.", "bis": "Ang tagak usa ka langgam nga adunay taas nga tiil ug liog nga magpuyo duol sa humayan, suba, ug lamakan, ug mokaon kini ug isda ug gagmayng mananap."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "honeybee-pukyutan-g4", "domain": "LIVING_THINGS", "topic": "honeybees make honey and pollinate flowers", "grades": [3, 4, 5], "terms": ["pukyutan", "bubuyog", "pulot", "honey", "polinasyon", "bulaklak", "honeybee", "pollination", "nektar", "putyukan", "buyog", "dugos", "bulak", "polinisasyon"], "fact": {"tl": "Ang pukyutan ay gumagawa ng pulot mula sa nektar ng bulaklak, at habang naghahanap ng nektar ay nakakatulong itong polinasyon o paghahatid ng pollen sa ibang bulaklak.", "en": "Honeybees make honey from flower nectar, and as they gather nectar they help pollinate by carrying pollen between flowers.", "bis": "Ang putyukan naghimo ug dugos gikan sa nektar sa bulak, ug samtang nangita ug nektar makatabang kini sa polinisasyon pinaagi sa pagdala ug pollen sa lain-laing bulak."}, "source": "NRC LS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hen-chicks-inahin-g3", "domain": "LIVING_THINGS", "topic": "hens care for their chicks", "grades": [3, 4], "terms": ["inahin", "manok", "sisiw", "itlog", "alaga ng magulang", "hen", "chicks", "egg", "parental care", "himungaan", "piso", "pag-atiman sa anak"], "fact": {"tl": "Ang inahing manok ay nangingitlog at inaalagaan ang mga sisiw nito, pinaiinitan ang itlog hanggang mapisa at pinoprotektahan ang mga ito.", "en": "A mother hen lays eggs and cares for her chicks, keeping the eggs warm until they hatch and protecting the young.", "bis": "Ang himungaan nga manok mangitlog ug mag-atiman sa iyang mga piso, gipainit ang itlog hangtod mapusa ug gipanalipdan ang mga gagmay."}, "source": "NRC LS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hibiscus-bloom-g4", "domain": "LIVING_THINGS", "topic": "the hibiscus flower and its parts", "grades": [3, 4, 5], "terms": ["gumamela", "bulaklak", "talulot", "pollen", "hibiscus", "flower", "stamen", "petal", "polinasyon", "bulak", "petalo", "polen"], "fact": {"tl": "Ang gumamela ay malaking bulaklak na may makukulay na talulot at nakausli ang mahabang istruktura sa gitna na nagdadala ng pollen para sa polinasyon.", "en": "The hibiscus is a large flower with colorful petals and a long central structure sticking out that carries pollen for pollination.", "bis": "Ang gumamela usa ka dako nga bulak nga adunay mabulukon nga petalo ug taas nga estruktura sa tunga nga nagdala ug pollen para sa polinisasyon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "horsetail-plant-g6", "domain": "LIVING_THINGS", "topic": "horsetail is an ancient spore plant", "grades": [5, 6, 7], "terms": ["horsetail", "halaman", "spore", "walang bulaklak", "matandang halaman", "horsetail plant", "spores", "non-flowering", "buntot ng kabayo", "tanom", "spora", "walay bulak", "karaang tanom"], "fact": {"tl": "Ang horsetail ay isang sinaunang halamang walang bulaklak na nagpaparami gamit ang spores sa halip na buto, at madalas itong tumutubo sa mamasa-masang lupa.", "en": "The horsetail is an ancient non-flowering plant that reproduces with spores instead of seeds, and it often grows in moist soil.", "bis": "Ang horsetail usa ka karaang tanom nga walay bulak nga magsanay gamit ang spora imbis liso, ug kasagaran motubo sa basa nga yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "housefly-langaw-g3", "domain": "LIVING_THINGS", "topic": "houseflies can spread germs", "grades": [3, 4, 5], "terms": ["langaw", "insekto", "mikrobyo", "sakit", "housefly", "fly", "germs", "insect", "dumi", "kagaw", "hugaw"], "fact": {"tl": "Ang langaw ay insektong madaling makakuha ng mikrobyo mula sa dumi at basura, kaya kapag dumapo ito sa pagkain ay maaari itong magkalat ng sakit.", "en": "The housefly is an insect that easily picks up germs from waste and garbage, so when it lands on food it can spread disease.", "bis": "Ang langaw usa ka insekto nga sayon makakuha ug kagaw gikan sa hugaw ug basura, mao nga kung motugdon kini sa pagkaon makapakatag kini ug sakit."}, "source": "DepEd MATATAG Science Health; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "house-lizard-butiki-wall-g3", "domain": "LIVING_THINGS", "topic": "house geckos eat insects on walls", "grades": [3, 4, 5], "terms": ["butiki", "house lizard", "gecko", "insekto", "dingding", "reptilya", "house gecko", "wall", "insect eater", "tiki", "tabili", "bongbong", "mokaon ug insekto"], "fact": {"tl": "Ang butiki ay maliit na reptilyang gumagapang sa dingding at kisame, at tumutulong ito sa bahay sa pamamagitan ng pagkain ng mga insekto gaya ng lamok.", "en": "The house lizard is a small reptile that crawls on walls and ceilings, and it helps in the home by eating insects like mosquitoes.", "bis": "Ang tabili usa ka gamayng reptilya nga mokamang sa bongbong ug kisame, ug makatabang kini sa balay pinaagi sa pagkaon ug mga insekto sama sa lamok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "homologous-limbs-comparison-g9", "domain": "LIVING_THINGS", "topic": "homologous limbs show shared ancestry", "grades": [8, 9, 10], "terms": ["homologous", "magkahawig na buto", "ebolusyon", "ninuno", "paa", "pakpak", "homologous limbs", "evolution", "common ancestor", "buto", "managsama nga bukog", "katigulangan", "pako"], "fact": {"tl": "Ang homologous na mga galamay—gaya ng braso ng tao, pakpak ng paniki, at palikpik ng balyena—ay may magkakatulad na ayos ng buto na nagpapakitang sila ay may iisang ninuno.", "en": "Homologous limbs—like the human arm, a bat's wing, and a whale's flipper—share the same bone pattern, showing they came from a common ancestor.", "bis": "Ang homologous nga mga bukton—sama sa bukton sa tawo, pako sa kabog, ug palikpik sa balyena—adunay managsamang han-ay sa bukog nga nagpakita nga sila gikan sa usa ka katigulangan."}, "source": "NRC LS4.A; AAAS Benchmarks evolution; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "illegal-logging-truck-scene-g6", "domain": "EARTH_SPACE", "topic": "illegal logging harms forests", "grades": [5, 6, 7], "terms": ["illegal logging", "pagtotroso", "kalbong gubat", "deforestation", "kagubatan", "erosion", "logging", "forest loss", "puno", "iligal nga pagputol", "kalasangan", "kakahoyan", "pagguba sa lasang"], "fact": {"tl": "Ang iligal na pagtotroso ay nag-aalis ng mga puno sa kagubatan, na nagdudulot ng pagguho ng lupa, pagbaha, at pagkawala ng tahanan ng mga hayop.", "en": "Illegal logging removes trees from the forest, which leads to soil erosion, flooding, and loss of homes for animals.", "bis": "Ang iligal nga pagputol ug kahoy magtangtang sa mga punoan sa lasang, nga maoy hinungdan sa pagkakahig sa yuta, pagbaha, ug pagkawala sa puy-anan sa mga mananap."}, "source": "NRC ESS3.C; DepEd MATATAG Science; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "iron-rich-foods-g5", "domain": "LIVING_THINGS", "topic": "iron-rich foods prevent anemia", "grades": [4, 5, 6], "terms": ["bakal", "iron", "malunggay", "kamatis", "atay", "dugo", "anemya", "iron-rich foods", "anemia", "hemoglobin", "puga", "kamunggay", "kakulang sa dugo"], "fact": {"tl": "Ang mga pagkaing mayaman sa iron, gaya ng malunggay, atay, at karne, ay tumutulong sa katawan na gumawa ng malusog na dugo at maiwasan ang anemya.", "en": "Iron-rich foods, like malunggay, liver, and meat, help the body make healthy blood and prevent anemia.", "bis": "Ang mga pagkaon nga daghan ug iron, sama sa kamunggay, atay, ug karne, makatabang sa lawas sa paghimo ug himsog nga dugo ug makalikay sa anemia."}, "source": "DepEd MATATAG Science Health/Nutrition; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "incomplete-dominance-g9", "domain": "LIVING_THINGS", "topic": "incomplete dominance blends traits", "grades": [8, 9, 10], "terms": ["incomplete dominance", "mana", "pagmamana", "halo-halong katangian", "genetika", "alele", "blended trait", "genetics", "allele", "panulondon", "sinagol nga kinaiya", "henetika"], "fact": {"tl": "Sa incomplete dominance, walang gene na ganap na nananaig, kaya ang supling ay nagkakaroon ng pinaghalong katangian—gaya ng pink na bulaklak mula sa pula at puti.", "en": "In incomplete dominance, neither gene fully dominates, so the offspring shows a blended trait—like a pink flower from a red and a white parent.", "bis": "Sa incomplete dominance, walay gene nga hingpit nga modaog, mao nga ang anak magpakita ug sinagol nga kinaiya—sama sa pink nga bulak gikan sa pula ug puti nga ginikanan."}, "source": "NRC LS3.B; AAAS Benchmarks heredity; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "incomplete-dominance-bougainvillea-g8", "domain": "LIVING_THINGS", "topic": "incomplete dominance in flowers", "grades": [8, 9, 10], "terms": ["incomplete dominance", "bougainvillea", "bugambilya", "namamana", "mana", "kulay ng bulaklak", "naghahalo", "blending", "genetiko", "panulundon", "kolor sa bulak", "pagminaw", "intermediate trait"], "fact": {"tl": "Sa incomplete dominance, gaya kung minsan sa bulaklak, walang gene na nananaig kaya naghahalo ang dalawang katangian at lumalabas ang gitnang kulay (hal. pula at puti na nagiging rosas).", "en": "In incomplete dominance, neither gene fully dominates, so two traits blend and an in-between color appears (for example red and white parents making pink offspring).", "bis": "Sa incomplete dominance, walay gene nga modaog, busa magsagol ang duha ka kinaiya ug motungha ang taliwala nga kolor (pananglitan pula ug puti nga mahimong rosas)."}, "source": "encyclopedia-stable consensus; NRC LS3 Heredity", "generator": "claude-workflow", "reviewed": false},
  {"id": "jogging-exercise-health-g4", "domain": "LIVING_THINGS", "topic": "exercise keeps the body healthy", "grades": [3, 4, 5], "terms": ["jogging", "pagtakbo", "ehersisyo", "exercise", "kalusugan", "puso", "malakas na puso", "physical activity", "pagdagan", "lihok", "lawas", "himsog", "kasingkasing", "paghinga"], "fact": {"tl": "Ang jogging at iba pang ehersisyo ay nagpapalakas ng puso at mga kalamnan, at tumutulong sa katawan na manatiling malusog.", "en": "Jogging and other exercise strengthen the heart and muscles and help the body stay healthy.", "bis": "Ang jogging ug uban pang ehersisyo nagpalig-on sa kasingkasing ug mga kaunoran, ug nagtabang sa lawas nga magpabiling himsog."}, "source": "DepEd MAPEH/Health; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "jackfruit-langka-g4", "domain": "LIVING_THINGS", "topic": "jackfruit, the largest tree fruit", "grades": [3, 4, 5], "terms": ["jackfruit", "langka", "nangka", "prutas", "punong langka", "pinakamalaking prutas sa puno", "matamis", "buto", "fruit", "tree", "kahoy", "tam-is", "bunga"], "fact": {"tl": "Ang langka ang pinakamalaking prutas na tumutubo sa puno; ito ay matamis kapag hinog at may maraming buto sa loob.", "en": "Jackfruit is the largest fruit that grows on a tree; it is sweet when ripe and holds many seeds inside.", "bis": "Ang nangka mao ang pinakadako nga prutas nga motubo sa kahoy; tam-is kini kon hinog ug daghan ug liso sa sulod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ilang-ilang-flower-g5", "domain": "LIVING_THINGS", "topic": "ilang-ilang, a fragrant flower", "grades": [4, 5, 6], "terms": ["ilang-ilang", "ylang-ylang", "bulaklak", "mabango", "pabango", "perfume", "dilaw na bulaklak", "punong ilang-ilang", "fragrant flower", "humot", "bulak", "kahumot"], "fact": {"tl": "Ang ilang-ilang ay isang punong-kahoy na may dilaw, mababangong bulaklak na ginagamit sa paggawa ng pabango.", "en": "Ilang-ilang is a tree with yellow, sweet-smelling flowers that are used to make perfume.", "bis": "Ang ilang-ilang usa ka kahoy nga adunay dalag, humot nga mga bulak nga gigamit sa paghimo ug pahumot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "iron-rich-leafy-greens-g5", "domain": "LIVING_THINGS", "topic": "leafy greens and iron in the diet", "grades": [4, 5, 6], "terms": ["iron", "bakal", "leafy greens", "madahong gulay", "malunggay", "kangkong", "dugo", "red blood cells", "pulang selula ng dugo", "nutrisyon", "gulay nga dahon", "puthaw", "dugo"], "fact": {"tl": "Ang mga madahong gulay gaya ng malunggay at kangkong ay mayaman sa bakal (iron), na kailangan ng katawan upang makagawa ng malusog na pulang selula ng dugo.", "en": "Leafy greens like malunggay and kangkong are rich in iron, which the body needs to make healthy red blood cells.", "bis": "Ang mga dahonon nga utanon sama sa malunggay ug kangkong dato sa puthaw (iron), nga gikinahanglan sa lawas aron makahimo ug himsog nga pula nga selula sa dugo."}, "source": "DepEd Health/Nutrition; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ipil-tree-g6", "domain": "LIVING_THINGS", "topic": "ipil, a hardwood tree", "grades": [5, 6, 7], "terms": ["ipil", "ipil tree", "matigas na kahoy", "hardwood", "punong-kahoy", "kagubatan", "Pilipinas", "matibay na kahoy", "tree", "lumber", "gahi nga kahoy", "kahoy", "lasang"], "fact": {"tl": "Ang ipil ay isang punong-kahoy ng Pilipinas na may napakatigas at matibay na kahoy, kaya ginagamit ito sa paggawa ng muwebles at mga gusali.", "en": "Ipil is a Philippine tree with very hard, durable wood, so it is used to make furniture and buildings.", "bis": "Ang ipil usa ka kahoy sa Pilipinas nga adunay gahi kaayo ug lig-on nga kahoy, busa gigamit kini sa paghimo ug muwebles ug mga building."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kabuteng-dilaw-mushroom-g5", "domain": "LIVING_THINGS", "topic": "mushrooms are fungi, not plants", "grades": [4, 5, 6], "terms": ["kabute", "kabuteng dilaw", "mushroom", "fungi", "fungus", "halamang singaw", "hindi halaman", "spore", "spores", "nabubulok", "decomposer", "uhong", "agup-op", "dilaw nga uhong"], "fact": {"tl": "Ang kabute ay isang uri ng fungi, hindi halaman, dahil wala itong dahon o ugat at hindi nakakagawa ng sariling pagkain mula sa araw.", "en": "A mushroom is a kind of fungus, not a plant, because it has no leaves or roots and cannot make its own food from sunlight.", "bis": "Ang uhong usa ka matang sa fungi, dili tanom, kay wala kini dahon o gamot ug dili makahimo sa kaugalingong pagkaon gikan sa adlaw."}, "source": "AAAS Benchmarks 5A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "jumping-jacks-exercise-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "muscles and energy during exercise", "grades": [3, 4, 5], "terms": ["jumping jacks", "ehersisyo", "exercise", "muscles", "kalamnan", "enerhiya", "energy", "paggalaw", "warm-up", "lihok", "kaunoran", "kusog"], "fact": {"tl": "Kapag gumagawa ng jumping jacks, gumagamit ng enerhiya ang mga kalamnan upang igalaw ang mga braso at binti, kaya bumibilis ang tibok ng puso at paghinga.", "en": "When you do jumping jacks, your muscles use energy to move your arms and legs, so your heartbeat and breathing speed up.", "bis": "Kon maghimo kag jumping jacks, ang imong mga kaunoran mogamit ug kusog aron lihukon ang mga bukton ug bitiis, busa mopaspas ang pitik sa kasingkasing ug ang ginhawa."}, "source": "DepEd MAPEH/Health; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "invasive-water-hyacinth-g6", "domain": "LIVING_THINGS", "topic": "water hyacinth as an invasive plant", "grades": [5, 6, 7], "terms": ["water hyacinth", "water lily", "invasive", "tubig na halaman", "ilog", "lawa", "nakakasakal", "oxygen", "isda", "mabilis kumalat", "dayuhang halaman", "suba", "linaw", "tubig"], "fact": {"tl": "Ang water hyacinth ay isang dayuhang halaman na mabilis kumalat sa ilog at lawa, at nakatatakip sa tubig kaya nababawasan ang oxygen na kailangan ng mga isda.", "en": "Water hyacinth is an invasive plant that spreads quickly over rivers and lakes, covering the water and reducing the oxygen that fish need.", "bis": "Ang water hyacinth usa ka langyaw nga tanom nga paspas mokatag sa suba ug linaw, nga motabon sa tubig ug mokunhod sa oxygen nga gikinahanglan sa mga isda."}, "source": "encyclopedia-stable consensus; NRC LS2 Ecosystems", "generator": "claude-workflow", "reviewed": false},
  {"id": "joints-and-bones-types-g6", "domain": "LIVING_THINGS", "topic": "joints let bones move", "grades": [5, 6, 7], "terms": ["joints", "kasukasuan", "bones", "buto", "tuhod", "siko", "balikat", "hinge joint", "ball and socket", "paggalaw", "skeletal system", "lutahan", "bukog", "tuhod"], "fact": {"tl": "Ang mga kasukasuan ang nagdurugtong sa mga buto at nagbibigay-daan sa paggalaw; halimbawa, ang tuhod at siko ay gumagalaw paisa-isang direksyon, samantalang ang balikat ay umiikot sa maraming direksyon.", "en": "Joints connect bones and let them move; for example, the knee and elbow bend in one direction, while the shoulder can rotate in many directions.", "bis": "Ang mga lutahan nagdugtong sa mga bukog ug nagtugot kanila sa paglihok; pananglitan, ang tuhod ug siko mobawog sa usa ka direksyon, samtang ang abaga makatuyok sa daghang direksyon."}, "source": "DepEd G6 Human Body; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "janitor-fish-invasive-g6", "domain": "LIVING_THINGS", "topic": "janitor fish as an invasive species", "grades": [5, 6, 7], "terms": ["janitor fish", "suckermouth catfish", "invasive", "dayuhang isda", "ilog", "Marikina", "lawa", "katutubong isda", "nakakaubos", "isda", "suba", "langyaw nga isda", "lumad nga isda"], "fact": {"tl": "Ang janitor fish ay isang dayuhang isda na kumalat sa mga ilog ng Pilipinas, at dahil mabilis itong dumami, nakakasama ito sa mga katutubong isda.", "en": "The janitor fish is an introduced fish that has spread in Philippine rivers, and because it multiplies fast it harms native fish.", "bis": "Ang janitor fish usa ka langyaw nga isda nga mikatag sa mga suba sa Pilipinas, ug tungod kay paspas kini modaghan, makadaot kini sa lumad nga mga isda."}, "source": "encyclopedia-stable consensus; NRC LS2 Ecosystems", "generator": "claude-workflow", "reviewed": false},
  {"id": "jumping-spider-small-g4", "domain": "LIVING_THINGS", "topic": "jumping spiders and how they hunt", "grades": [3, 4, 5], "terms": ["jumping spider", "gagamba", "lumulukso", "tumatalon", "mata", "predator", "insekto", "lumukso", "spider", "eyes", "lawalawa", "lukso", "mananap"], "fact": {"tl": "Ang jumping spider ay isang maliit na gagamba na may malalaki at matatalas na mata, at lumulukso ito upang hulihin ang maliliit na insekto sa halip na gumamit ng sapot.", "en": "The jumping spider is a small spider with large, sharp eyes, and it leaps to catch tiny insects instead of using a web.", "bis": "Ang jumping spider usa ka gamay nga lawalawa nga adunay dagko ug hait nga mga mata, ug molukso kini aron dakpon ang gagmay nga insekto imbis nga mogamit ug lawa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kaimito-star-apple-g4", "domain": "LIVING_THINGS", "topic": "kaimito (star apple) fruit", "grades": [3, 4, 5], "terms": ["kaimito", "star apple", "caimito", "prutas", "bituin", "hiwa", "matamis", "lila", "purple", "punong-kahoy", "fruit", "bituon", "tam-is", "bunga"], "fact": {"tl": "Ang kaimito ay isang matamis na prutas na nagpapakita ng hugis-bituin kapag hiniwa nang pahalang ang loob nito.", "en": "The kaimito, or star apple, is a sweet fruit that shows a star shape when its inside is sliced across.", "bis": "Ang kaimito o star apple usa ka tam-is nga prutas nga magpakita ug porma sa bituon kon hiwaon ang sulod niini sa pikas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kadios-pigeon-pea-g5", "domain": "LIVING_THINGS", "topic": "kadios (pigeon pea) legume", "grades": [4, 5, 6], "terms": ["kadios", "pigeon pea", "legumbre", "legume", "munggo-tulad", "buto", "protina", "KBL", "halaman", "nitrogen", "lupa", "liso", "utanon", "binhi"], "fact": {"tl": "Ang kadios ay isang halamang gumugulay (legume) na ang mga buto ay mayaman sa protina, at ginagamit ito sa lutong KBL (kadios, baboy, langka).", "en": "Kadios (pigeon pea) is a legume whose seeds are rich in protein, and it is used in the Filipino dish KBL (kadios, pork, jackfruit).", "bis": "Ang kadios usa ka legume nga ang mga liso dato sa protina, ug gigamit kini sa pagkaong KBL (kadios, baboy, nangka)."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kaingin-slash-burn-g7", "domain": "EARTH_SPACE", "topic": "kaingin (slash-and-burn) and the environment", "grades": [6, 7, 8], "terms": ["kaingin", "slash and burn", "kagubatan", "pagsunog", "deforestation", "soil erosion", "pagkasira ng lupa", "carbon dioxide", "kalikasan", "lasang", "pagdaob", "yuta", "kalasangan"], "fact": {"tl": "Ang kaingin ay ang pagsunog ng kagubatan upang gawing taniman, ngunit nawawala ang mga puno, natatanggal ang taba ng lupa, at lumalala ang pagguho ng lupa.", "en": "Kaingin is burning forest to clear land for farming, but it removes the trees, strips the soil of its nutrients, and worsens soil erosion.", "bis": "Ang kaingin mao ang pagsunog sa kalasangan aron himoong umahan, apan mawala ang mga kahoy, makuha ang sustansiya sa yuta, ug mograbe ang pagguho sa yuta."}, "source": "DepEd Earth Science; NRC ESS3 Human Impacts", "generator": "claude-workflow", "reviewed": false},
  {"id": "kalachuchi-frangipani-g5", "domain": "LIVING_THINGS", "topic": "kalachuchi (frangipani) flower", "grades": [4, 5, 6], "terms": ["kalachuchi", "frangipani", "plumeria", "bulaklak", "mabango", "puti", "dilaw", "punong-kahoy", "katsuhi", "flower", "humot", "bulak", "kahumot"], "fact": {"tl": "Ang kalachuchi ay isang punong-kahoy na may mababango at makapal na bulaklak na karaniwang puti at dilaw sa gitna.", "en": "Kalachuchi (frangipani) is a tree with fragrant, thick-petaled flowers that are usually white with a yellow center.", "bis": "Ang kalachuchi usa ka kahoy nga adunay humot ug baga nga mga bulak nga kasagaran puti nga adunay dalag sa tunga."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kamatis-vine-cluster-g4", "domain": "LIVING_THINGS", "topic": "tomato fruit and its seeds", "grades": [3, 4, 5], "terms": ["kamatis", "tomato", "prutas", "gulay", "buto", "halaman", "pula", "ugat", "fruit", "vine", "kamatis", "liso", "pula"], "fact": {"tl": "Ang kamatis ay isang prutas (madalas ituring na gulay) na tumutubo sa baging, at may maraming buto sa loob na maaaring maging bagong halaman.", "en": "The tomato is a fruit (often used as a vegetable) that grows on a vine, with many seeds inside that can grow into new plants.", "bis": "Ang kamatis usa ka prutas (kasagarang giisip nga utanon) nga motubo sa baging, ug daghan ug liso sa sulod nga mahimong bag-ong tanom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kalaw-hornbill-flight-g5", "domain": "LIVING_THINGS", "topic": "the Philippine hornbill (kalaw)", "grades": [4, 5, 6], "terms": ["kalaw", "hornbill", "Philippine hornbill", "ibon", "tuka", "kagubatan", "prutas", "endangered", "endemic", "langgam", "tuka", "lasang", "naglupad"], "fact": {"tl": "Ang kalaw ay isang malaking ibon ng kagubatan ng Pilipinas na may malaking tuka, at tumutulong itong magtanim ng puno sa pamamagitan ng pagkalat ng buto mula sa mga prutas na kinakain nito.", "en": "The kalaw (hornbill) is a large Philippine forest bird with a big bill, and it helps grow new trees by spreading seeds from the fruits it eats.", "bis": "Ang kalaw usa ka dakong langgam sa kalasangan sa Pilipinas nga adunay dakong sungo, ug motabang kini sa pagpatubo ug bag-ong kahoy pinaagi sa pagkatag sa liso gikan sa mga prutas nga gikaon niini."}, "source": "encyclopedia-stable consensus; NRC LS2 Ecosystems", "generator": "claude-workflow", "reviewed": false},
  {"id": "kamias-bilimbi-g4", "domain": "LIVING_THINGS", "topic": "kamias (bilimbi), a sour fruit", "grades": [3, 4, 5], "terms": ["kamias", "bilimbi", "maasim", "prutas", "sinigang", "pampaasim", "berde", "punong-kahoy", "sour fruit", "fruit", "aslom", "maaslom", "bunga"], "fact": {"tl": "Ang kamias ay isang berde at napakaasim na prutas na tumutubo nang sama-sama sa sanga, at ginagamit itong pampaasim sa mga lutong gaya ng sinigang.", "en": "Kamias (bilimbi) is a green, very sour fruit that grows in clusters on the branch, and it is used to add a sour taste to dishes like sinigang.", "bis": "Ang kamias usa ka berde ug aslom kaayo nga prutas nga motubo nga nagpundok sa sanga, ug gigamit kini aron paaslomon ang mga pagkaon sama sa sinigang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kangkong-g4", "domain": "LIVING_THINGS", "topic": "kangkong, a water-loving vegetable", "grades": [3, 4, 5], "terms": ["kangkong", "water spinach", "gulay", "tubig", "madahong gulay", "halaman", "berde", "lumulutang", "vegetable", "utanon", "tubig", "dahon"], "fact": {"tl": "Ang kangkong ay isang madahong gulay na tumutubo sa mababaw na tubig o basang lupa, at mayaman ito sa bitamina at iron.", "en": "Kangkong (water spinach) is a leafy vegetable that grows in shallow water or wet soil, and it is rich in vitamins and iron.", "bis": "Ang kangkong usa ka dahonon nga utanon nga motubo sa mabaw nga tubig o basa nga yuta, ug dato kini sa bitamina ug puthaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kapok-tree-pod-g5", "domain": "LIVING_THINGS", "topic": "kapok tree and its cotton-like fiber", "grades": [4, 5, 6], "terms": ["kapok", "kapok tree", "punong-kahoy", "bunga", "pod", "bulak", "himulmol", "unan", "kutson", "buto", "fiber", "cotton tree", "gapas", "bunga sa kapok"], "fact": {"tl": "Ang kapok ay isang punong-kahoy na ang mga bunga ay napupuno ng malambot na hibla na parang bulak, at ginagamit ito noon bilang laman ng mga unan at kutson.", "en": "The kapok is a tree whose pods are filled with soft, cotton-like fibers, which were used to stuff pillows and mattresses.", "bis": "Ang kapok usa ka kahoy nga ang mga bunga puno sa humok nga hilo nga sama sa gapas, ug gigamit kini kanhi nga sulod sa mga unlan ug kutson."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kamote-tops-talbos-g4", "domain": "LIVING_THINGS", "topic": "kamote tops (talbos ng kamote) as food", "grades": [3, 4, 5], "terms": ["talbos ng kamote", "kamote tops", "sweet potato leaves", "dahon", "gulay", "madahong gulay", "bitamina", "halaman", "talbos", "dahon sa kamote", "utanon", "dahon"], "fact": {"tl": "Ang talbos ng kamote ay ang mga murang dahon ng halamang kamote, at ito ay isang masustansyang madahong gulay na mayaman sa bitamina.", "en": "Kamote tops are the young leaves of the sweet potato plant, and they are a nutritious leafy vegetable rich in vitamins.", "bis": "Ang talbos sa kamote mao ang mga batan-ong dahon sa tanom nga kamote, ug usa kini ka masustansiyang dahonon nga utanon nga dato sa bitamina."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kelp-seaweed-forest-g6", "domain": "LIVING_THINGS", "topic": "kelp forests as ocean habitats", "grades": [5, 6, 7], "terms": ["kelp", "seaweed", "kelp forest", "damong-dagat", "algae", "dagat", "tirahan", "isda", "oxygen", "kagubatan sa dagat", "lawod", "lumot sa dagat", "dagat"], "fact": {"tl": "Ang kelp ay isang malaking damong-dagat na tumutubo nang sama-sama at bumubuo ng parang kagubatan sa ilalim ng dagat, na nagbibigay ng tirahan at pagkain sa maraming isda.", "en": "Kelp is a large seaweed that grows together to form underwater forests, which provide shelter and food for many fish.", "bis": "Ang kelp usa ka dako nga lumot sa dagat nga motubo nga nagpundok ug maghimo ug daw kalasangan ilalom sa dagat, nga naghatag ug puy-anan ug pagkaon sa daghang isda."}, "source": "encyclopedia-stable consensus; NRC LS2 Ecosystems", "generator": "claude-workflow", "reviewed": false},
  {"id": "kasoy-cashew-apple-g4", "domain": "LIVING_THINGS", "topic": "cashew (kasoy) fruit and nut", "grades": [3, 4, 5], "terms": ["kasoy", "cashew", "cashew apple", "prutas", "buto", "nut", "Antipolo", "punong-kahoy", "matamis", "seed", "liso", "tam-is", "bunga"], "fact": {"tl": "Ang kasoy ay may makatas na bahaging prutas (cashew apple) na may nakabitin na buto sa dulo, at ang butong ito ang niluluto bilang masarap na nut.", "en": "The cashew has a juicy fruit part (the cashew apple) with a single seed hanging at its end, and that seed is roasted into the tasty cashew nut.", "bis": "Ang kasoy adunay duga nga bahin nga prutas (cashew apple) nga adunay usa ka liso nga nagbitay sa tumoy, ug kana nga liso giluto aron mahimong lami nga cashew nut."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "katuray-flower-g5", "domain": "LIVING_THINGS", "topic": "katuray, an edible flower", "grades": [4, 5, 6], "terms": ["katuray", "katurai", "sesbania", "bulaklak na kinakain", "edible flower", "gulay", "puti", "ensalada", "punong-kahoy", "legume", "bulak", "utanon", "bulak nga makaon"], "fact": {"tl": "Ang katuray ay isang puting bulaklak ng isang punong-kahoy na maaaring kainin bilang gulay, gaya ng paglalaga o paggawa nito sa ensalada.", "en": "Katuray is a white flower from a tree that can be eaten as a vegetable, such as boiled or made into a salad.", "bis": "Ang katuray usa ka puti nga bulak sa usa ka kahoy nga mahimong kan-on isip utanon, sama sa pagpabukal o paghimo niini nga ensalada."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kanin-ulam-gulay-balanced-meal-g4", "domain": "LIVING_THINGS", "topic": "a balanced Filipino meal", "grades": [3, 4, 5], "terms": ["kanin", "ulam", "gulay", "balanced meal", "masustansyang pagkain", "carbohydrate", "protina", "bitamina", "go grow glow", "kanin ulam gulay", "balanseng pagkain", "kan-on", "sud-an", "utanon"], "fact": {"tl": "Ang balanseng pagkain na may kanin, ulam, at gulay ay nagbibigay ng enerhiya, protina, at bitamina na kailangan ng katawan upang lumaki at maging malusog.", "en": "A balanced meal of rice, a main dish, and vegetables gives the body the energy, protein, and vitamins it needs to grow and stay healthy.", "bis": "Ang balanseng pagkaon nga adunay kan-on, sud-an, ug utanon naghatag sa lawas ug kusog, protina, ug bitamina nga gikinahanglan aron motubo ug magpabiling himsog."}, "source": "DepEd Health/Nutrition; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ladybug-ladybird-g4", "domain": "LIVING_THINGS", "topic": "ladybugs help farmers by eating pests", "grades": [3, 4, 5], "terms": ["ladybug", "ladybird", "salagubang", "kulisap", "insekto", "aphid", "peste", "magsasaka", "pula", "batik", "predator", "insekto", "bakukang", "peste"], "fact": {"tl": "Ang ladybug ay isang maliit na pula at batik-batik na kulisap na tumutulong sa mga magsasaka dahil kinakain nito ang maliliit na peste na sumisira sa mga halaman.", "en": "The ladybug is a small red, spotted insect that helps farmers because it eats the tiny pests that damage plants.", "bis": "Ang ladybug usa ka gamay nga pula ug puntik-puntik nga insekto nga motabang sa mga mag-uuma kay kan-on niini ang gagmay nga peste nga modaot sa mga tanom."}, "source": "encyclopedia-stable consensus; NRC LS2 Ecosystems", "generator": "claude-workflow", "reviewed": false},
  {"id": "kingfisher-kasaykasay-g4", "domain": "LIVING_THINGS", "topic": "kingfisher bird", "grades": [3, 4, 5], "terms": ["kasaykasay", "salaksak", "tikgi", "kingfisher", "ibon", "langgam", "salampati sa suba", "tubig", "isda", "pamingwit", "manunukob"], "fact": {"tl": "Ang kingfisher (kasaykasay) ay isang maliit na ibong may matingkad na kulay na nakatira malapit sa mga ilog at sapa, at sumisisid ito sa tubig para humuli ng maliliit na isda.", "en": "The kingfisher is a small, brightly colored bird that lives near rivers and streams, where it dives into the water to catch small fish.", "bis": "Ang kingfisher (tikgi) usa ka gamay nga langgam nga hayag og kolor nga nagpuyo duol sa mga suba ug sapa, ug magsalom kini sa tubig aron makadakop og gagmay nga isda."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kingfisher-dive-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "kingfisher diving", "grades": [4, 5, 6], "terms": ["kingfisher", "kasaykasay", "salaksak", "tikgi", "sisid", "sumisisid", "pagsalom", "nagsalom", "dive", "tubig", "isda", "bilis", "tuwid"], "fact": {"tl": "Kapag nakakita ng isda, ang kingfisher ay sumisisid nang mabilis at tuwid mula sa hangin patungo sa tubig, na may sapat na lakas para sunggaban ang isda gamit ang matulis nitong tuka.", "en": "When it spots a fish, the kingfisher dives swiftly and straight from the air into the water, fast enough to snatch the fish with its sharp, pointed beak.", "bis": "Kon makakita kini og isda, ang kingfisher magsalom og paspas ug tul-id gikan sa hangin paingon sa tubig, kusog kaayo aron madakpan ang isda pinaagi sa hait niini nga sungo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "labanos-radish-g4", "domain": "LIVING_THINGS", "topic": "radish vegetable", "grades": [3, 4, 5], "terms": ["labanos", "radish", "gulay", "ugat", "ubod", "puti", "kinilaw", "halaman", "tanom", "ugat nga gulay", "puti nga gulay"], "fact": {"tl": "Ang labanos ay isang puti at mahabang gulay-ugat na lumalaki sa ilalim ng lupa, at kinakain natin ang namamagang ugat nito na may bahagyang maanghang na lasa.", "en": "The radish (labanos) is a white, long root vegetable that grows underground, and we eat its swollen root, which has a slightly spicy taste.", "bis": "Ang labanos usa ka puti ug taas nga gulay nga gamot nga motubo ilalom sa yuta, ug atong kan-on ang nanghubag niini nga gamot nga gamay og kaanghang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kintsay-celery-g4", "domain": "LIVING_THINGS", "topic": "celery vegetable", "grades": [3, 4, 5], "terms": ["kintsay", "celery", "kinchay", "gulay", "tangkay", "berde", "dahon", "halaman", "tanom", "sabaw", "pampalasa"], "fact": {"tl": "Ang kintsay ay isang berdeng gulay na may mahahaba at malalutong na tangkay at mababangong dahon, na madalas idagdag sa sabaw at ulam bilang pampalasa.", "en": "Celery (kintsay) is a green vegetable with long, crisp stalks and fragrant leaves, often added to soups and dishes to give flavor.", "bis": "Ang kintsay usa ka lunhaw nga gulay nga adunay taas ug malutong nga mga punoan ug humot nga dahon, nga sagad idugang sa sabaw ug sud-an aron molami."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kitten-kuting-g3", "domain": "LIVING_THINGS", "topic": "kitten young cat", "grades": [3, 4], "terms": ["kuting", "kitten", "pusa", "anak ng pusa", "iring", "kuring", "anak sa iring", "gatas", "mammal", "hayop", "alaga"], "fact": {"tl": "Ang kuting ay anak ng pusa na sumususo ng gatas sa ina nito noong sanggol pa, at unti-unting natututong maglakad, maglaro, at manghuli ng maliliit na bagay habang lumalaki.", "en": "A kitten is a baby cat that drinks its mother's milk when very young, and slowly learns to walk, play, and pounce on small things as it grows.", "bis": "Ang kuting mao ang anak sa iring nga mosuso og gatas sa iyang inahan samtang gamay pa, ug anam-anam nga makakat-on molakaw, magdula, ug manghakop og gagmay nga butang samtang motubo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "koi-fish-ornamental-g4", "domain": "LIVING_THINGS", "topic": "koi ornamental fish", "grades": [3, 4, 5], "terms": ["koi", "isda", "isdang pampaganda", "ornamental", "carp", "kolor", "pond", "lawa", "isdang pang-alaga", "tubig-tabang", "isda nga bahandianon"], "fact": {"tl": "Ang koi ay isang malaki at makulay na isda na inaalagaan sa mga lawa o tangke bilang palamuti, at maaari itong mabuhay nang napakatagal kung maayos ang pag-aalaga.", "en": "Koi are large, colorful fish kept in ponds or tanks as ornaments, and they can live for a very long time when cared for well.", "bis": "Ang koi usa ka dako ug mabulukon nga isda nga gibuhi sa mga linaw o tangke isip dayandayan, ug mabuhi kini og dugay kaayo kon maayo ang pag-atiman."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lanzones-fruit-g4", "domain": "LIVING_THINGS", "topic": "lanzones fruit", "grades": [3, 4, 5], "terms": ["lanzones", "lanzon", "buko-buko", "prutas", "bunga", "matamis", "maasim", "puno", "kumpol", "balat", "Camiguin", "buongon nga prutas"], "fact": {"tl": "Ang lanzones ay isang maliit na bilog na prutas na nagsasalansan nang kumpol-kumpol sa puno, may manipis na kayumangging balat at matamis-asim na laman sa loob.", "en": "Lanzones is a small round fruit that grows in clusters on a tree, with a thin brown skin and sweet-sour flesh inside.", "bis": "Ang lanzones usa ka gamay ug lingin nga prutas nga magpungpong sa kahoy, adunay nipis nga kape nga panit ug tam-is-aslom nga unod sa sulod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kundol-winter-melon-g4", "domain": "LIVING_THINGS", "topic": "winter melon gourd", "grades": [3, 4, 5], "terms": ["kundol", "winter melon", "wax gourd", "kondol", "gulay", "prutas", "malaki", "gulayon", "matamis", "minatamis", "halaman", "kondol nga gulay"], "fact": {"tl": "Ang kundol ay isang malaking berdeng gulay na gumagapang sa lupa, at maaaring lutuin bilang ulam o gawing matamis na minatamis.", "en": "The winter melon (kundol) is a large green gourd that grows along the ground on a vine, and it can be cooked as a dish or made into sweet candied treats.", "bis": "Ang kundol usa ka dako nga lunhaw nga gulay nga mokamang sa yuta, ug mahimong lutoon isip sud-an o himoong tam-is nga minatamis."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lato-sea-grapes-g5", "domain": "LIVING_THINGS", "topic": "sea grapes seaweed", "grades": [4, 5, 6], "terms": ["lato", "sea grapes", "ar-arosep", "damong-dagat", "seaweed", "algae", "dagat", "kinilaw", "ensalada", "lab-as nga damong-dagat"], "fact": {"tl": "Ang lato ay isang uri ng damong-dagat na tumutubo sa mababaw na bahagi ng dagat, na may maliliit at bilog na butil-butil na pumuputok sa bibig at madalas kainin bilang ensalada.", "en": "Lato (sea grapes) is a kind of seaweed that grows in shallow seawater, with tiny round beads that pop in the mouth and are often eaten as a salad.", "bis": "Ang lato usa ka matang sa damong-dagat nga motubo sa mabaw nga bahin sa dagat, nga adunay gagmay ug lingin nga liso nga mobuto sa baba ug sagad kan-on isip ensalada."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "leaf-rubbing-texture-activity-g3", "domain": "MATTER", "topic": "leaf texture and observation", "grades": [3, 4], "terms": ["dahon", "leaf rubbing", "tekstura", "texture", "ugat ng dahon", "guhit", "krayola", "papel", "obserbasyon", "magaspang", "patron", "dahon nga tekstura"], "fact": {"tl": "Kapag inilagay mo ang papel sa ibabaw ng dahon at kinuskos ng krayola, lumalabas ang patron ng mga ugat at hugis nito, na tumutulong sa atin na obserbahan ang tekstura ng bawat dahon.", "en": "When you place paper over a leaf and rub it with crayon, the pattern of its veins and shape appears, helping us observe the texture of each leaf.", "bis": "Kon ibutang nimo ang papel ibabaw sa dahon ug kuskoson og krayola, mogawas ang sumbanan sa mga ugat ug porma niini, nga motabang kanato sa pag-obserbar sa tekstura sa matag dahon."}, "source": "DepEd MATATAG Science G3; AAAS observation skills", "generator": "claude-workflow", "reviewed": false},
  {"id": "lagundi-shrub-g6", "domain": "LIVING_THINGS", "topic": "lagundi medicinal plant", "grades": [5, 6, 7], "terms": ["lagundi", "shrub", "halamang gamot", "tanom nga tambal", "dahon", "ubo", "hilab", "five-leaved chaste tree", "DOH", "herbal", "punong-gamot", "tambal nga dahon"], "fact": {"tl": "Ang lagundi ay isang halamang-gamot na may dahong hugis-kamay na binubuo ng limang dahon, at ang pinakuluang dahon nito ay ginagamit bilang lunas sa ubo at sipon.", "en": "Lagundi is a medicinal shrub with hand-shaped leaves made of five leaflets, and a boiled brew of its leaves is used as a remedy for cough and colds.", "bis": "Ang lagundi usa ka tanom nga tambal nga adunay dahon nga porma og kamot nga gilangkuban og lima ka dahon, ug ang gilat-an niini nga dahon gigamit isip tambal sa ubo ug sip-on."}, "source": "Philippine DOH-recognized medicinal plant; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "leaf-g4", "domain": "LIVING_THINGS", "topic": "leaf and photosynthesis", "grades": [4, 5, 6], "terms": ["dahon", "leaf", "litrato", "photosynthesis", "pagkain", "sikat ng araw", "berde", "klorofila", "chlorophyll", "halaman", "tanom", "dahon nga lunhaw"], "fact": {"tl": "Ang dahon ay ang bahagi ng halaman na gumagawa ng pagkain nito, dahil ginagamit nito ang liwanag ng araw, tubig, at hangin para makabuo ng enerhiya.", "en": "A leaf is the part of a plant that makes its food, because it uses sunlight, water, and air to create energy.", "bis": "Ang dahon mao ang bahin sa tanom nga maghimo sa pagkaon niini, kay gamiton niini ang kahayag sa adlaw, tubig, ug hangin aron makahimo og kusog."}, "source": "NRC LS1.C; DepEd MATATAG Science G4-G6", "generator": "claude-workflow", "reviewed": false},
  {"id": "kamagong-tree-g6", "domain": "LIVING_THINGS", "topic": "kamagong ironwood tree", "grades": [5, 6, 7], "terms": ["kamagong", "ironwood", "mabolo", "puno", "kahoy", "matigas na kahoy", "ebony", "Pilipinas", "endemic", "katutubo", "matig-a nga kahoy", "punoan"], "fact": {"tl": "Ang kamagong ay isang katutubong puno sa Pilipinas na kilala sa napakatigas at maitim na kahoy nito, kaya pinoprotektahan ito at bawal putulin nang walang pahintulot.", "en": "Kamagong is a tree native to the Philippines known for its very hard, dark wood, so it is protected and cannot be cut without permission.", "bis": "Ang kamagong usa ka lumad nga kahoy sa Pilipinas nga ilado sa hilabihan ka gahi ug itom niini nga kahoy, busa gipanalipdan kini ug dili mahimong putlon nga walay pagtugot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "legume-root-nodules-nitrogen-g8", "domain": "LIVING_THINGS", "topic": "legume root nodules nitrogen fixation", "grades": [7, 8, 9], "terms": ["legume", "munggo", "patani", "root nodules", "ugat", "bukol sa ugat", "nitrogen", "bakterya", "bacteria", "lupa", "abono", "tabunok nga yuta", "fertilidad"], "fact": {"tl": "Ang mga halamang legume tulad ng munggo at patani ay may maliliit na bukol sa ugat kung saan nakatira ang bakterya na kumukuha ng nitrogen mula sa hangin, na nagpapayaman sa lupa.", "en": "Legume plants such as mung beans and lima beans have tiny nodules on their roots where bacteria live and take nitrogen from the air, enriching the soil.", "bis": "Ang mga tanom nga legume sama sa munggo ug patani adunay gagmay nga bukol sa gamot diin nagpuyo ang bakterya nga mokuha og nitrogen gikan sa hangin, nga makapatambok sa yuta."}, "source": "NRC LS2.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kuhol-golden-snail-rice-g5", "domain": "LIVING_THINGS", "topic": "golden apple snail rice pest", "grades": [4, 5, 6], "terms": ["kuhol", "golden apple snail", "golden kuhol", "suso", "palay", "rice pest", "peste", "bukid", "itlog na rosas", "pink eggs", "invasive", "peste sa humay"], "fact": {"tl": "Ang golden kuhol ay isang suso na nangingitlog ng kulay-rosas na itlog sa mga halaman malapit sa tubig, at itinuturing itong peste dahil kinakain nito ang murang halaman ng palay.", "en": "The golden apple snail (kuhol) is a snail that lays pink eggs on plants near water, and it is treated as a pest because it eats young rice seedlings.", "bis": "Ang golden kuhol usa ka kuhol nga mangitlog og rosas nga itlog sa mga tanom duol sa tubig, ug giisip kini nga peste kay kan-on niini ang batan-on nga tanom sa humay."}, "source": "encyclopedia-stable consensus; DepEd MATATAG Science G5", "generator": "claude-workflow", "reviewed": false},
  {"id": "leaf-hopper-ngusongkabayo-g6", "domain": "LIVING_THINGS", "topic": "leafhopper insect", "grades": [5, 6, 7], "terms": ["leafhopper", "ngusong kabayo", "ngusongkabayo", "kuliglig", "insekto", "insect", "peste", "palay", "dahon", "katas", "lumukso", "insekto sa dahon"], "fact": {"tl": "Ang leafhopper (ngusong-kabayo) ay isang maliit na insektong sumisipsip ng katas ng halaman, at madalas itong makita sa mga palayan kung saan maaari itong makapinsala sa pananim.", "en": "The leafhopper is a small insect that sucks the juices of plants, and it is often found in rice fields where it can harm the crops.", "bis": "Ang leafhopper (ngusong-kabayo) usa ka gamay nga insekto nga mosupsop sa duga sa tanom, ug sagad makita kini sa kahumayan diin makadaot kini sa mga pananom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lifecycle-coconut-g5", "domain": "LIVING_THINGS", "topic": "coconut life cycle", "grades": [4, 5, 6], "terms": ["niyog", "coconut", "lubi", "lifecycle", "siklo ng buhay", "buto", "binhi", "usbong", "puno", "bunga", "tumubo", "tubo sa lubi", "siklo sa kinabuhi"], "fact": {"tl": "Ang niyog ay nagsisimula bilang isang buong bunga na sumisibol ng usbong, na unti-unting nagiging mataas na puno na pagkalipas ng ilang taon ay namumunga rin ng sariling mga niyog.", "en": "A coconut begins as a whole fruit that sprouts a shoot, which slowly grows into a tall palm tree that, after several years, produces its own coconuts.", "bis": "Ang lubi magsugod isip usa ka tibuok nga bunga nga moturok og udlot, nga anam-anam mahimong taas nga kahoy nga, paglabay sa pipila ka tuig, mamunga usab og kaugalingong mga lubi."}, "source": "NRC LS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lifecycle-butterfly-g4", "domain": "LIVING_THINGS", "topic": "butterfly life cycle metamorphosis", "grades": [3, 4, 5], "terms": ["paru-paro", "butterfly", "alibangbang", "uod", "caterpillar", "higad", "supot", "chrysalis", "pupa", "itlog", "metamorphosis", "siklo ng buhay", "siklo sa kinabuhi"], "fact": {"tl": "Ang paru-paro ay dumadaan sa apat na yugto ng buhay: itlog, uod, supot (pupa), at saka lumalabas bilang ganap na paru-parong may pakpak.", "en": "A butterfly goes through four life stages: egg, caterpillar, pupa, and finally emerges as a full butterfly with wings.", "bis": "Ang alibangbang moagi sa upat ka yugto sa kinabuhi: itlog, ulod, pupa, ug unya mogula isip hingpit nga alibangbang nga adunay pako."}, "source": "NRC LS1.B; DepEd MATATAG Science G4", "generator": "claude-workflow", "reviewed": false},
  {"id": "lichen-on-bark-g7", "domain": "LIVING_THINGS", "topic": "lichen symbiosis", "grades": [6, 7, 8], "terms": ["lichen", "balatik sa kahoy", "balat sa kahoy", "fungus", "algae", "halamang singaw", "puno", "balakbak", "symbiosis", "magkasama", "tumutubo sa balat ng kahoy", "lumot"], "fact": {"tl": "Ang lichen ay isang organismong nabubuo mula sa fungus at algae na magkasamang nabubuhay, at madalas itong makita na nakadikit sa balat ng mga puno at bato.", "en": "A lichen is an organism formed by a fungus and an alga living together, and it is often seen clinging to the bark of trees and to rocks.", "bis": "Ang lichen usa ka organismo nga gimugna gikan sa fungus ug algae nga nagpuyo nga magkauban, ug sagad makita kini nga nakapilit sa panit sa mga kahoy ug sa mga bato."}, "source": "encyclopedia-stable consensus; NRC LS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "lifecycle-dragonfly-g5", "domain": "LIVING_THINGS", "topic": "dragonfly life cycle", "grades": [4, 5, 6], "terms": ["tutubi", "dragonfly", "alindahaw", "nymph", "itlog", "tubig", "siklo ng buhay", "pakpak", "lumipad", "naiad", "siklo sa kinabuhi", "insekto"], "fact": {"tl": "Ang tutubi ay nangingitlog sa tubig, at ang anak nito ay nabubuhay muna sa ilalim ng tubig bilang nymph bago umahon at maging tutubing may pakpak na lumilipad.", "en": "A dragonfly lays its eggs in water, and its young first live underwater as a nymph before climbing out and becoming a winged, flying dragonfly.", "bis": "Ang alindahaw mangitlog sa tubig, ug ang anak niini magpuyo una ilalom sa tubig isip nymph una pa kini mosaka ug mahimong alindahaw nga adunay pako nga molupad."}, "source": "encyclopedia-stable consensus; NRC LS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "levels-of-organization-g8", "domain": "LIVING_THINGS", "topic": "levels of biological organization", "grades": [7, 8, 9], "terms": ["levels of organization", "antas ng organisasyon", "selula", "cell", "tissue", "himbis", "organ", "sangkap-lawas", "organ system", "organismo", "lebel sa organisasyon", "selula hangtod organismo"], "fact": {"tl": "Ang katawan ng mga buhay na bagay ay nakaayos sa antas: mula sa selula, patungong tissue, organ, organ system, hanggang sa buong organismo.", "en": "The bodies of living things are arranged in levels: from cells, to tissues, to organs, to organ systems, up to the whole organism.", "bis": "Ang lawas sa buhi nga mga butang gihan-ay sa lebel: gikan sa selula, ngadto sa tissue, organ, organ system, hangtod sa tibuok organismo."}, "source": "NRC LS1.A; DepEd MATATAG Science G7-G8", "generator": "claude-workflow", "reviewed": false},
  {"id": "lifecycle-chicken-g3", "domain": "LIVING_THINGS", "topic": "chicken life cycle", "grades": [3, 4, 5], "terms": ["manok", "chicken", "lifecycle", "itlog", "sisiw", "chick", "piso", "inahin", "tandang", "lumaki", "siklo ng buhay", "siklo sa kinabuhi"], "fact": {"tl": "Ang manok ay nagsisimula bilang itlog na pinipisa ng inahin, at pagkatapos ng halos tatlong linggo ay lumalabas ang sisiw na unti-unting lumalaki at nagiging ganap na manok.", "en": "A chicken begins as an egg kept warm by the hen, and after about three weeks a chick hatches that slowly grows into a full-grown chicken.", "bis": "Ang manok magsugod isip itlog nga lumlomon sa himungaan, ug human sa mga tulo ka semana mogula ang piso nga anam-anam motubo ug mahimong hingkod nga manok."}, "source": "encyclopedia-stable consensus; DepEd MATATAG Science G3", "generator": "claude-workflow", "reviewed": false},
  {"id": "lifecycle-fern-g7", "domain": "LIVING_THINGS", "topic": "fern life cycle spores", "grades": [6, 7, 8], "terms": ["pako", "fern", "lifecycle", "spore", "spora", "itlog", "binhi", "walang bulaklak", "dahon", "basa", "siklo ng buhay", "pakpako", "siklo sa kinabuhi"], "fact": {"tl": "Ang pako ay isang halamang walang bulaklak o buto na dumadami sa pamamagitan ng maliliit na spore na matatagpuan sa ilalim ng mga dahon nito.", "en": "A fern is a plant without flowers or seeds that reproduces through tiny spores found on the underside of its leaves.", "bis": "Ang pako usa ka tanom nga walay bulak o liso nga modaghan pinaagi sa gagmay nga spore nga makita sa ilawom sa mga dahon niini."}, "source": "NRC LS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lifecycle-fish-g4", "domain": "LIVING_THINGS", "topic": "fish life cycle", "grades": [3, 4, 5], "terms": ["isda", "fish", "lifecycle", "itlog", "fry", "fingerling", "nilalakihan", "tubig", "siklo ng buhay", "anak ng isda", "siklo sa kinabuhi", "pisi"], "fact": {"tl": "Ang isda ay nangingitlog sa tubig, at mula sa mga itlog ay lumalabas ang maliliit na isda na unti-unting lumalaki hanggang maging ganap nang isda.", "en": "Fish lay their eggs in water, and from the eggs hatch tiny young fish that slowly grow until they become full-grown fish.", "bis": "Ang isda mangitlog sa tubig, ug gikan sa mga itlog mogula ang gagmay nga isda nga anam-anam motubo hangtod mahimo kining hingkod nga isda."}, "source": "NRC LS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lifecycle-frog-g4", "domain": "LIVING_THINGS", "topic": "frog life cycle metamorphosis", "grades": [4, 5, 6], "terms": ["palaka", "frog", "baki", "lifecycle", "itlog", "tadpole", "ulu-ulo", "buntot", "binti", "metamorphosis", "tubig", "siklo ng buhay", "siklo sa kinabuhi"], "fact": {"tl": "Ang palaka ay nangingitlog sa tubig, at mula rito ay lumalabas ang tadpole na may buntot na lumalangoy, na unti-unting tumutubuan ng binti at nagiging palakang nakatira sa lupa at tubig.", "en": "A frog lays its eggs in water, and from these hatch tadpoles with tails that swim, which slowly grow legs and become frogs that live on land and in water.", "bis": "Ang baki mangitlog sa tubig, ug gikan niini mogula ang tadpole nga adunay ikog nga molangoy, nga anam-anam motubo og bitiis ug mahimong baki nga magpuyo sa yuta ug sa tubig."}, "source": "NRC LS1.B; DepEd MATATAG Science G4", "generator": "claude-workflow", "reviewed": false},
  {"id": "lifecycle-mosquito-g5", "domain": "LIVING_THINGS", "topic": "mosquito life cycle", "grades": [4, 5, 6], "terms": ["lamok", "mosquito", "lifecycle", "itlog", "kiti-kiti", "larva", "pupa", "tubig", "tubig na nakatigil", "dengue", "siklo ng buhay", "siklo sa kinabuhi", "kiwi-kiwi"], "fact": {"tl": "Ang lamok ay nangingitlog sa nakatigil na tubig, at ang itlog ay nagiging kiti-kiti at pupa bago lumipad bilang lamok, kaya mahalagang alisin ang nakaipong tubig para hindi ito dumami.", "en": "A mosquito lays its eggs in still water, and the eggs become wrigglers (larvae) and pupae before flying off as mosquitoes, so it is important to remove standing water to stop them from multiplying.", "bis": "Ang lamok mangitlog sa nagtigi nga tubig, ug ang itlog mahimong kiti-kiti ug pupa una pa kini molupad isip lamok, busa importante nga kuhaon ang natipon nga tubig aron dili kini modaghan."}, "source": "encyclopedia-stable consensus; DepEd health-science integration", "generator": "claude-workflow", "reviewed": false},
  {"id": "lifecycle-mangrove-propagule-g6", "domain": "LIVING_THINGS", "topic": "mangrove propagule", "grades": [5, 6, 7], "terms": ["bakawan", "mangrove", "propagule", "lifecycle", "binhi", "buto", "tumutubo sa puno", "putik", "baybayin", "tubig-alat", "siklo ng buhay", "bakhaw", "siklo sa kinabuhi"], "fact": {"tl": "Ang bakawan ay may natatanging binhi na tinatawag na propagule na tumutubo na habang nakakabit pa sa puno, at kapag nahulog ito sa putik ay nag-uugat at lumalaking bagong puno.", "en": "The mangrove has a special seed called a propagule that begins growing while still attached to the parent tree, and when it drops into the mud it takes root and grows into a new tree.", "bis": "Ang bakhaw adunay talagsaon nga liso nga gitawag og propagule nga magsugod na og tubo samtang nakabitay pa sa kahoy, ug kon mahulog kini sa lapok mogamot kini ug motubo nga bag-ong kahoy."}, "source": "encyclopedia-stable consensus; NRC LS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "lionfish-firefish-g6", "domain": "LIVING_THINGS", "topic": "lionfish venomous fish", "grades": [5, 6, 7], "terms": ["lionfish", "firefish", "isda", "tinik", "venom", "lason", "kamatis-dagat", "dagat", "bahura", "coral reef", "guhit", "stripe", "makamandag nga isda"], "fact": {"tl": "Ang lionfish ay isang makulay na isda ng bahura na may mahahaba at matutulis na tinik na naglalaman ng lason, na ginagamit nito para magtanggol sa sarili laban sa mga kaaway.", "en": "The lionfish is a colorful reef fish with long, sharp spines that carry venom, which it uses to defend itself against enemies.", "bis": "Ang lionfish usa ka mabulukon nga isda sa bahura nga adunay taas ug hait nga mga tunok nga adunay hilo, nga gamiton niini aron manalipod sa kaugalingon batok sa mga kaaway."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lifecycle-snail-g4", "domain": "LIVING_THINGS", "topic": "snail life cycle", "grades": [3, 4, 5], "terms": ["suso", "snail", "kuhol", "lifecycle", "itlog", "bahay", "talukab", "shell", "lumaki", "basa", "siklo ng buhay", "siklo sa kinabuhi", "lihok"], "fact": {"tl": "Ang suso ay nangingitlog ng maliliit na itlog, at mula rito ay lumalabas ang munting suso na may maliit nang bahay-bahay (shell) na lumalaki kasabay ng paglaki ng suso.", "en": "A snail lays small eggs, and from these hatch tiny snails that already have a little shell, which grows larger as the snail grows.", "bis": "Ang suso mangitlog og gagmay nga itlog, ug gikan niini mogula ang gagmay nga suso nga adunay gamay nga bahay-bahay (shell) nga modako samtang motubo ang suso."}, "source": "encyclopedia-stable consensus; NRC LS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "long-tailed-macaque-matsing-g6", "domain": "LIVING_THINGS", "topic": "long-tailed macaque monkey", "grades": [5, 6, 7], "terms": ["matsing", "macaque", "long-tailed macaque", "unggoy", "amo", "monkey", "mahabang buntot", "gubat", "Pilipinas", "primate", "mammal", "taas og ikog nga unggoy"], "fact": {"tl": "Ang long-tailed macaque (matsing) ay isang unggoy na may mahabang buntot na matatagpuan sa mga gubat ng Pilipinas, at namumuhay ito nang grupo-grupo habang naghahanap ng prutas at iba pang pagkain.", "en": "The long-tailed macaque (matsing) is a monkey with a long tail found in the forests of the Philippines, and it lives in groups while searching for fruit and other food.", "bis": "Ang long-tailed macaque (matsing) usa ka unggoy nga adunay taas nga ikog nga makita sa mga lasang sa Pilipinas, ug magpuyo kini og grupo-grupo samtang mangita og prutas ug uban pang pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lifecycle-rice-plant-g4", "domain": "LIVING_THINGS", "topic": "rice plant life cycle", "grades": [4, 5, 6], "terms": ["palay", "bigas", "kanin", "siklo ng buhay", "binhi", "punla", "tangkay", "uhay", "humay", "siklo sa kinabuhi", "liso", "bugas", "rice", "paddy", "life cycle", "seed", "seedling", "grain", "Oryza sativa"], "fact": {"tl": "Ang palay ay tumutubo mula sa binhi tungo sa punla, lumalaki bilang halaman, at namumunga ng mga butil na nagiging bigas na ginagawang kanin.", "en": "A rice plant grows from a seed into a seedling, matures into a tall grassy plant, and produces grains in a head that become the rice we cook and eat.", "bis": "Ang humay motubo gikan sa liso ngadto sa punla, modako nga tanom, ug mamunga og mga liso nga mahimong bugas nga atong lutoon ug kan-on."}, "source": "DepEd G4 Life Cycles; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lungs-inhale-exhale-g5", "domain": "LIVING_THINGS", "topic": "lungs breathing inhale exhale", "grades": [4, 5, 6, 7], "terms": ["baga", "paghinga", "paglanghap", "pagbuga", "oksiheno", "carbon dioxide", "hangin", "baga ng tao", "respiratory", "pagginhawa", "ginhawa", "lungs", "inhale", "exhale", "oxygen", "breathe"], "fact": {"tl": "Kapag humihinga ka, ang iyong mga baga ay lumalaki para lumanghap ng hanging may oksiheno, at lumiliit para magbuga ng carbon dioxide na hindi na kailangan ng katawan.", "en": "When you breathe, your lungs expand to pull in air rich in oxygen and shrink to push out carbon dioxide that your body no longer needs.", "bis": "Kon moginhawa ka, ang imong mga baga molapad aron mosuyop og hangin nga puno sa oksiheno, ug mokunhod aron mobuga sa carbon dioxide nga dili na kinahanglan sa lawas."}, "source": "NRC LS1.A; DepEd G5 Human Body Systems", "generator": "claude-workflow", "reviewed": false},
  {"id": "lifecycle-plant-g4", "domain": "LIVING_THINGS", "topic": "plant life cycle", "grades": [3, 4, 5], "terms": ["halaman", "siklo ng buhay", "binhi", "buto", "punla", "ugat", "bulaklak", "bunga", "tanom", "liso", "gamot", "bulak", "siklo sa kinabuhi", "plant", "seed", "seedling", "flower", "fruit", "life cycle", "germinate"], "fact": {"tl": "Karamihan ng halaman ay nagsisimula bilang binhi na tumutubo, nag-uugat at nagdadahon, pagkatapos ay namumulaklak at namumunga ng bagong binhi upang magpatuloy ang siklo.", "en": "Most plants begin as a seed that sprouts and grows roots and leaves, then forms flowers and fruit holding new seeds that start the cycle again.", "bis": "Kadaghanan sa mga tanom magsugod isip liso nga moturok ug motubo og gamot ug dahon, dayon mamulak ug mamunga og bag-ong liso aron magpadayon ang siklo."}, "source": "AAAS Benchmarks 5C; DepEd G4 Life Cycles", "generator": "claude-workflow", "reviewed": false},
  {"id": "liverwort-mat-g7", "domain": "LIVING_THINGS", "topic": "liverwort non-vascular plant", "grades": [6, 7, 8], "terms": ["liverwort", "lumot na liverwort", "halamang walang ugat", "basa", "anino", "spore", "non-vascular", "bryophyte", "lumot", "basa-basa", "landong", "moss-like", "damp", "shade"], "fact": {"tl": "Ang liverwort ay maliit at simpleng halamang walang tunay na ugat o bulaklak na tumutubo bilang lapad na kapal sa basa at malilim na lupa o bato.", "en": "A liverwort is a small, simple plant with no true roots or flowers that grows as a flat, leafy mat on damp, shaded soil and rocks.", "bis": "Ang liverwort usa ka gamay ug simple nga tanom nga walay tinuod nga gamot o bulak, nga motubo isip lapad nga sapaw sa basa ug landong nga yuta o bato."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lotus-flower-g5", "domain": "LIVING_THINGS", "topic": "lotus aquatic flower", "grades": [4, 5, 6], "terms": ["lotus", "bulaklak na lotus", "halamang tubig", "lawa", "ugat sa putik", "dahong lumulutang", "bulak nga lotus", "tubigon", "linaw", "water lily", "pond", "floating leaf", "aquatic plant"], "fact": {"tl": "Ang lotus ay halamang tubig na ang mga ugat ay nasa putik sa ilalim ng lawa habang ang malalaki nitong dahon at bulaklak ay nakaangat sa ibabaw ng tubig.", "en": "The lotus is a water plant whose roots anchor in the mud at the bottom of a pond while its large round leaves and flowers rise above the water surface.", "bis": "Ang lotus usa ka tubigon nga tanom kansang gamot nakaugat sa lapok sa ilawom sa linaw samtang ang dagko niini nga dahon ug bulak motungha ibabaw sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "luffa-dried-sponge-g5", "domain": "LIVING_THINGS", "topic": "luffa sponge gourd", "grades": [4, 5, 6], "terms": ["patola", "luffa", "espongha", "tuyong patola", "gulay na patola", "hibla", "panghugas", "patula", "utanon nga patola", "sponge", "loofah", "gourd", "dried", "fiber"], "fact": {"tl": "Ang patola ay isang gulay na kapag hinayaang huminog at matuyo ay nagiging magaspang na espongha na ginagamit panghugas dahil sa matitigas nitong hibla sa loob.", "en": "The luffa is a gourd vegetable that, when left to ripen and dry on the vine, turns into a rough natural sponge used for scrubbing because of its tough inner fibers.", "bis": "Ang patola usa ka utanon nga kon pasagdan nga mahinog ug momala, mahimong gaspang nga espongha nga gamiton panghugas tungod sa gahi nga hibla sa sulod niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lobster-banagan-g5", "domain": "LIVING_THINGS", "topic": "lobster marine crustacean", "grades": [4, 5, 6], "terms": ["banagan", "ulang", "lobster", "crustacean", "dagat", "balat na matigas", "sipit", "claws", "shell", "seabed", "sea animal"], "fact": {"tl": "Ang banagan o lobster ay isang malaking hayop sa dagat na may matigas na balat at malalakas na sipit, at gumagapang sa pusod ng dagat para maghanap ng pagkain.", "en": "The lobster (banagan) is a large sea animal with a hard shell and strong front claws that crawls along the seabed searching for food.", "bis": "Ang banagan o lobster usa ka dako nga mananap sa dagat nga adunay gahi nga panit ug kusgan nga mga sipit, ug mokamang sa salog sa dagat aron mangita og pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lovebird-colasisi-g5", "domain": "LIVING_THINGS", "topic": "colasisi Philippine hanging parrot", "grades": [4, 5, 6], "terms": ["kolasisi", "colasisi", "kulasisi", "loro", "ibong loro", "Philippine hanging parrot", "berdeng ibon", "endemic", "langgam nga loro", "lunhaw", "hanging parrot", "green bird", "endemic Philippines"], "fact": {"tl": "Ang kolasisi ay maliit na berdeng loro na endemik sa Pilipinas at kilala dahil natutulog ito nang nakatiwarik na nakabitin sa sanga, kaya tinawag itong hanging parrot.", "en": "The colasisi is a small green parrot found only in the Philippines, known for sleeping upside down hanging from a branch, which is why it is called a hanging parrot.", "bis": "Ang kolasisi usa ka gamay nga lunhaw nga loro nga makit-an lamang sa Pilipinas, ilado kay matulog kini nga nagbitay nga balintong sa sanga, mao nga gitawag kini nga hanging parrot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mahogany-tree-g6", "domain": "LIVING_THINGS", "topic": "mahogany hardwood tree", "grades": [5, 6, 7], "terms": ["mahogany", "punong mahogany", "matigas na kahoy", "muwebles", "lilim", "mataas na puno", "kahoy nga mahogany", "gahi nga kahoy", "hardwood", "timber", "furniture", "tall tree", "shade tree"], "fact": {"tl": "Ang mahogany ay mataas na puno na ang matigas at pula-pulang kahoy ay pinahahalagahan sa paggawa ng muwebles, at madalas itong itanim sa tabi ng kalsada para sa lilim.", "en": "Mahogany is a tall tree whose hard, reddish-brown wood is prized for making furniture, and it is often planted along roads to provide shade.", "bis": "Ang mahogany usa ka tag-as nga kahoy kansang gahi ug mapula-pula nga troso gipabilhan sa paghimo og muwebles, ug kasagaran itanom sa daplin sa dalan aron molandong."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mabolo-velvet-apple-g5", "domain": "LIVING_THINGS", "topic": "mabolo velvet apple fruit", "grades": [4, 5, 6], "terms": ["mabolo", "kamagong", "velvet apple", "prutas na pula", "balahibong balat", "katutubong puno", "prutas nga pula", "fuzzy skin", "native fruit", "Philippine endemic", "Diospyros"], "fact": {"tl": "Ang mabolo ay prutas mula sa katutubong puno ng kamagong sa Pilipinas na may makapal na pulang balat na parang pelus at malambot na laman sa loob.", "en": "The mabolo, or velvet apple, is a fruit from the native Philippine kamagong tree with a thick reddish skin covered in soft velvety fuzz and sweet flesh inside.", "bis": "Ang mabolo o velvet apple usa ka prutas gikan sa lumad nga kahoy nga kamagong sa Pilipinas nga adunay baga nga pula nga panit nga morag pelus ug humok nga unod sa sulod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lysosome-organelle-g9", "domain": "LIVING_THINGS", "topic": "lysosome cell organelle", "grades": [8, 9, 10], "terms": ["lysosome", "lisosoma", "organelle", "selula", "bahagi ng selula", "pantunaw", "enzyme", "basura ng selula", "organelo", "digest", "waste", "cell"], "fact": {"tl": "Ang lysosome ay isang maliit na bahagi ng selula na naglalaman ng mga enzyme na tumutunaw at sumisira ng mga sira o hindi na kailangang bahagi sa loob ng selula.", "en": "A lysosome is a tiny organelle inside a cell that contains enzymes which break down and digest worn-out parts and waste the cell no longer needs.", "bis": "Ang lysosome usa ka gamay nga bahin sa selula nga adunay mga enzyme nga motunaw ug moguba sa mga daot o dili na kinahanglan nga bahin sulod sa selula."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "makahiya-sensitive-plant-g4", "domain": "LIVING_THINGS", "topic": "makahiya sensitive plant movement", "grades": [3, 4, 5], "terms": ["makahiya", "sensitive plant", "halamang nahihiya", "nagsasara ang dahon", "tinik", "huya-huya", "kibhibi", "mopilo ang dahon", "leaves close", "touch", "fold"], "fact": {"tl": "Ang makahiya ay isang halamang ang maliliit na dahon ay agad nagsasara o nakatiklop kapag nahipo o nayanig, na parang ito ay nahihiya.", "en": "The makahiya, or sensitive plant, has tiny leaves that quickly fold and close when touched or shaken, as if the plant were shy.", "bis": "Ang makahiya o sensitive plant adunay gagmay nga dahon nga dali nga mosira o mopilo kon mahikapan o mauyog, nga morag naulaw."}, "source": "DepEd G4 Plant Responses; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "malnutrition-healthy-child-g6", "domain": "LIVING_THINGS", "topic": "nutrition malnutrition health", "grades": [5, 6, 7], "terms": ["malnutrisyon", "sustansya", "wastong pagkain", "kalusugan", "vitamina", "protina", "kulang sa pagkain", "kulang sa sustansya", "balanseng pagkain", "panglawas", "balanced diet", "vitamins", "protein", "healthy"], "fact": {"tl": "Ang malnutrisyon ay nangyayari kapag ang katawan ay kulang sa tamang sustansya, kaya mahalagang kumain ng balanseng pagkaing may protina, gulay, at prutas para lumaking malusog.", "en": "Malnutrition happens when the body does not get enough of the right nutrients, so eating a balanced diet with protein, vegetables, and fruit is important for growing up healthy.", "bis": "Ang malnutrisyon mahitabo kon ang lawas kulang sa husto nga sustansya, busa importante ang pagkaon og balanse nga pagkaon nga adunay protina, utanon, ug prutas aron motubo nga himsog."}, "source": "DepEd G6 Nutrition; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lukban-citron-g5", "domain": "LIVING_THINGS", "topic": "lukban pomelo citrus", "grades": [4, 5, 6], "terms": ["lukban", "suha", "pomelo", "sitrus", "prutas na maasim", "makapal na balat", "prutas nga aslom", "citrus", "thick rind", "sour fruit"], "fact": {"tl": "Ang lukban ay isang malaking sitrus na prutas na may makapal na balat at maraming maaasim hanggang matatamis na bahagi sa loob na puno ng katas.", "en": "The lukban is a large citrus fruit with a thick rind and many juicy segments inside that range from sour to sweet.", "bis": "Ang lukban usa ka dako nga citrus nga prutas nga adunay baga nga panit ug daghang aslom ngadto sa tam-is nga bahin sa sulod nga puno sa duga."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "makopa-wax-apple-g4", "domain": "LIVING_THINGS", "topic": "makopa wax apple fruit", "grades": [3, 4, 5], "terms": ["makopa", "wax apple", "tambis", "prutas na kampana", "makintab na balat", "tubig na prutas", "prutas nga morag kampana", "bell-shaped", "watery fruit", "shiny skin"], "fact": {"tl": "Ang makopa ay hugis-kampanang prutas na may makintab na balat at malutong, tubig na laman, kaya nakakawala ito ng uhaw kapag mainit.", "en": "The makopa, or wax apple, is a bell-shaped fruit with shiny skin and crisp, watery flesh, making it refreshing to eat on a hot day.", "bis": "Ang makopa o tambis usa ka prutas nga porma og kampana nga adunay sinaw nga panit ug malutong, tubigon nga unod, busa makapawala kini sa kauhaw kon init."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "luyang-dilaw-turmeric-g6", "domain": "LIVING_THINGS", "topic": "turmeric spice rhizome use", "grades": [5, 6, 7], "terms": ["luyang dilaw", "turmeric", "kalawag", "pampakulay", "pampalasa", "ugat sa lupa", "dilaw na pulbos", "panakot", "kolor", "rhizome", "spice", "yellow dye", "medicine"], "fact": {"tl": "Ang dilaw na bahagi ng luyang dilaw na ginagamit sa pagluluto at gamot ay hindi bulaklak kundi ang lumusog na ugat nito sa ilalim ng lupa na tinatawag na rhizome.", "en": "The yellow part of turmeric used in cooking and medicine is not a root or flower but its swollen underground stem called a rhizome.", "bis": "Ang dalag nga bahin sa luyang dilaw nga gamiton sa pagluto ug tambal dili gamot o bulak kondili ang minaghang nga punoan niini sa ilawom sa yuta nga gitawag og rhizome."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mango-tree-form-g4", "domain": "LIVING_THINGS", "topic": "mango tree", "grades": [3, 4, 5], "terms": ["mangga", "punong mangga", "prutas na mangga", "mataas na puno", "lilim", "bulaklak ng mangga", "kahoy nga mangga", "prutas nga mangga", "mango tree", "fruit tree", "shade", "blossom", "Mangifera"], "fact": {"tl": "Ang punong mangga ay malaki at mayabong na puno na namumulaklak bago mamunga ng matamis na manggang isa sa mga paboritong prutas sa Pilipinas.", "en": "The mango tree is a large, leafy tree that bursts into flowers before producing sweet mangoes, one of the most loved fruits in the Philippines.", "bis": "Ang kahoy nga mangga usa ka dako ug labong nga kahoy nga mamulak una mamunga og tam-is nga mangga, usa sa labing pinangga nga prutas sa Pilipinas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mangrove-mud-lobster-mound-g7", "domain": "LIVING_THINGS", "topic": "mud lobster mounds mangrove engineer", "grades": [6, 7, 8], "terms": ["mud lobster", "bunton ng putik", "bakawan", "mangrove", "tagahukay", "bunton sa lapok", "bakhaw", "mound", "burrow", "mangrove soil", "Thalassina"], "fact": {"tl": "Ang mud lobster ay hayop sa putik ng kabakawanan na gumagawa ng mataas na bunton ng putik habang naghuhukay, na nagpapaluwag at nagpapasariwa ng lupa para sa ibang halaman.", "en": "The mud lobster is a burrowing animal of mangrove mud that builds tall mounds of soil as it digs, loosening and refreshing the ground for other plants.", "bis": "Ang mud lobster usa ka mananap sa lapok sa bakhaw nga maghimo og tag-as nga bunton sa yuta samtang nagkalot, nga makapaluag ug makapabag-o sa yuta alang sa ubang tanom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "maidenhair-fern-g7", "domain": "LIVING_THINGS", "topic": "maidenhair fern spores", "grades": [6, 7, 8], "terms": ["pako", "maidenhair fern", "fern", "halamang walang bulaklak", "spore", "anino", "basa", "lumot na lupa", "lagolago", "shade", "moist", "no flowers"], "fact": {"tl": "Ang maidenhair fern ay isang uri ng pako na may manipis na tangkay at maliliit na pabilog na dahon, at dumarami ito sa pamamagitan ng spore sa halip na binhi.", "en": "The maidenhair fern is a delicate fern with thin black stalks and small fan-shaped leaflets that reproduces by spores rather than seeds, thriving in shady, moist spots.", "bis": "Ang maidenhair fern usa ka klase sa pako nga adunay nipis nga tangkay ug gagmay nga lingin nga dahon, ug modaghan kini pinaagi sa spore imbis liso, nga molambo sa landong ug basa nga dapit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mangrove-nutrient-cycle-g8", "domain": "LIVING_THINGS", "topic": "mangrove nutrient cycle ecosystem", "grades": [7, 8, 9], "terms": ["bakawan", "mangrove", "siklo ng sustansya", "nabubulok na dahon", "ekosistema", "isda", "nutrient cycle", "bakhaw", "siklo sa sustansya", "nadunot nga dahon", "detritus", "estuary", "nursery"], "fact": {"tl": "Sa kabakawanan, ang mga nalalaglag na dahon ng bakawan ay nabubulok at nagiging sustansyang pinagkukunan ng pagkain ng maliliit na hayop, na sinusunod naman ng mas malalaking isda.", "en": "In a mangrove forest, fallen mangrove leaves rot and release nutrients that feed tiny animals, which in turn become food for larger fish in a connected nutrient cycle.", "bis": "Sa kabakhawan, ang nangahulog nga dahon sa bakhaw madunot ug mahimong sustansya nga pagkaon sa gagmay nga mananap, nga sundan usab sa mas dagko nga isda sa nasumpay nga siklo sa sustansya."}, "source": "NRC LS2.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mangrove-cutting-destruction-g7", "domain": "LIVING_THINGS", "topic": "mangrove loss coastal protection", "grades": [6, 7, 8], "terms": ["pagputol ng bakawan", "bakawan", "mangrove", "pagkasira", "alon", "baha", "proteksyon sa baybay", "pagputol sa bakhaw", "bakhaw", "balud", "panalipod sa baybayon", "coastal erosion", "flooding", "habitat loss"], "fact": {"tl": "Kapag pinuputol ang mga bakawan, nawawala ang likas na harang na pumipigil sa malalakas na alon at baha, at nawawalan din ng tirahan ang mga isda at ibong umaasa rito.", "en": "When mangroves are cut down, the coast loses a natural barrier that holds back strong waves and floods, and the fish and birds that depend on them lose their home.", "bis": "Kon putlon ang mga bakhaw, mawala ang natural nga babag nga makapugong sa kusog nga balud ug baha, ug mawad-an usab og puy-anan ang mga isda ug langgam nga nagsalig niini."}, "source": "DepEd G7 Ecosystems; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mango-orchard-harvest-g4", "domain": "LIVING_THINGS", "topic": "mango harvest farming", "grades": [3, 4, 5], "terms": ["ani ng mangga", "taniman ng mangga", "mangga", "pamimitas", "tag-init", "magsasaka", "orchard", "ani sa mangga", "tanaman sa mangga", "pupo", "ting-init", "ripe", "picking", "dry season"], "fact": {"tl": "Ang mangga ay inaani kapag hinog na ito sa puno, at sa Pilipinas ay marami itong namumunga sa tag-init kaya masagana ang ani noong mainit na buwan.", "en": "Mangoes are harvested when they ripen on the tree, and in the Philippines they fruit heavily during the hot dry season, giving a rich harvest in the warm months.", "bis": "Ang mangga anihon kon hinog na kini sa kahoy, ug sa Pilipinas daghan kini mamunga panahon sa ting-init mao nga abunda ang ani sa init nga bulan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mangrove-crab-fishing-g5", "domain": "LIVING_THINGS", "topic": "mud crab mangrove fishing", "grades": [4, 5, 6], "terms": ["alimango", "mud crab", "bakawan", "mangrove", "panghuli ng alimango", "putik", "pangisda", "bakhaw", "panakop og alimango", "lapok", "crab fishing", "claws", "mudflat"], "fact": {"tl": "Ang alimango ay malaking alimangong naninirahan sa putik ng kabakawanan, at marami sa baybaying pamayanan ang humuhuli nito para kainin o ipagbili bilang kabuhayan.", "en": "The mud crab is a large crab that lives in the muddy floor of mangrove forests, and many coastal villages catch it for food and to sell as a living.", "bis": "Ang alimango usa ka dako nga alimango nga nagpuyo sa lapok sa kabakhawan, ug daghan sa mga baryo sa baybayon ang manakop niini aron kan-on o ibaligya isip panginabuhi."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mantis-shrimp-tatampal-g6", "domain": "LIVING_THINGS", "topic": "mantis shrimp powerful strike", "grades": [5, 6, 7], "terms": ["tatampal", "mantis shrimp", "hipon", "alupihang dagat", "malakas na suntok", "sipit", "bahura", "alupihan sa dagat", "kusog nga suntok", "hanlilitik", "punch", "strike", "reef", "claw"], "fact": {"tl": "Ang mantis shrimp o tatampal ay maliit na hayop sa dagat na bantog sa napakabilis at napakalakas nitong suntok na kayang basagin ang kabibe ng kanyang biktima.", "en": "The mantis shrimp is a small sea animal famous for its extremely fast and powerful strike, strong enough to crack the hard shells of its prey.", "bis": "Ang mantis shrimp o tatampal usa ka gamay nga mananap sa dagat nga bantog sa kusog ug paspas kaayo nga suntok niini nga makabuak sa gahi nga kabhang sa iyang biktima."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "maya-bird-flock-g4", "domain": "LIVING_THINGS", "topic": "maya bird sparrow flock", "grades": [3, 4, 5], "terms": ["maya", "ibon", "maya bird", "kawan", "palay", "pugad", "munting ibon", "langgam", "panon", "salag", "humay", "tabunon", "sparrow", "flock", "grain", "nest", "small bird"], "fact": {"tl": "Ang maya ay maliit na kayumangging ibon na karaniwang nakikitang lumilipad nang kawan-kawan at madalas dumapo sa mga palayan para kumain ng butil.", "en": "The maya is a small brown bird often seen flying in flocks and landing in rice fields to feed on grain.", "bis": "Ang maya usa ka gamay nga tabunon nga langgam nga sagad makita nga naglupad og pundok-pundok ug kanunay motugdon sa kaumahan sa humay aron mokaon og liso."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "marine-protected-area-g6", "domain": "LIVING_THINGS", "topic": "marine protected area conservation", "grades": [5, 6, 7], "terms": ["sanctuary sa dagat", "marine protected area", "bantay-dagat", "bawal mangisda", "bahura", "pangangalaga", "isda", "protektadong dagat", "dili pwede mangisda", "no-fishing zone", "conservation", "reef"], "fact": {"tl": "Ang marine protected area ay bahagi ng dagat kung saan limitado o bawal ang pangingisda upang makabawi at dumami muli ang mga isda at bahura.", "en": "A marine protected area is a part of the sea where fishing is limited or banned so that fish and coral reefs can recover and grow back in number.", "bis": "Ang marine protected area usa ka bahin sa dagat diin limitado o gidili ang pagpangisda aron makabawi ug modaghan pag-usab ang mga isda ug bahura."}, "source": "DepEd G6 Ecosystems; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "marine-toad-kamprag-g5", "domain": "LIVING_THINGS", "topic": "cane toad introduced amphibian", "grades": [4, 5, 6], "terms": ["palaka", "kamprag", "marine toad", "cane toad", "bufo", "palakang malaki", "amphibian", "lason sa balat", "baki", "poison gland", "introduced"], "fact": {"tl": "Ang marine toad o kamprag ay malaking palaka na may magaspang na balat at may lason sa mga glandula nito, kaya hindi ito dapat hawakan o kainin ng tao o hayop.", "en": "The marine toad, or cane toad, is a large rough-skinned toad with poison glands on its body, so it is dangerous for people or animals to handle or eat.", "bis": "Ang marine toad o kamprag usa ka dako nga baki nga adunay gaspang nga panit ug hilo sa mga glandula niini, busa delikado kini kuptan o kan-on sa tawo o mananap."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "marang-fruit-g4", "domain": "LIVING_THINGS", "topic": "marang tropical fruit", "grades": [3, 4, 5], "terms": ["marang", "prutas na marang", "Mindanao", "matamis", "mabangong prutas", "tinik na balat", "prutas nga marang", "humot nga prutas", "tropical fruit", "sweet", "fragrant", "spiky skin"], "fact": {"tl": "Ang marang ay matamis at mabangong tropikal na prutas na karaniwang tumutubo sa Mindanao, na may magaspang na balat at malalambot na puting laman sa loob.", "en": "The marang is a sweet, fragrant tropical fruit that grows mainly in Mindanao, with a rough spiky skin and soft white juicy segments inside.", "bis": "Ang marang usa ka tam-is ug humot nga tropikal nga prutas nga sagad motubo sa Mindanao, nga adunay gaspang nga panit ug humok, puti nga unod sa sulod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "marigold-flower-g4", "domain": "LIVING_THINGS", "topic": "marigold flower", "grades": [3, 4, 5], "terms": ["marigold", "amarilyo", "bulaklak na dilaw", "halamang namumulaklak", "hardin", "kulisap", "bulak nga dalag", "tanom nga mamulak", "yellow orange flower", "garden", "blooming plant"], "fact": {"tl": "Ang marigold ay halamang namumulaklak ng maliliwanag na dilaw at kahel na bulaklak, at madalas itong itanim sa hardin dahil masaya itong tingnan at madaling alagaan.", "en": "The marigold is a plant that blooms with bright yellow and orange flowers, often grown in gardens because it is cheerful to look at and easy to care for.", "bis": "Ang marigold usa ka tanom nga mamulak og hayag nga dalag ug kahel nga mga bulak, ug kanunay itanom sa tanaman kay nindot tan-awon ug sayon atimanon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mini-greenhouse-bottle-plant-g4", "domain": "LIVING_THINGS", "topic": "mini greenhouse and plant needs", "grades": [3, 4, 5], "terms": ["mini greenhouse", "bote", "halaman", "plastik na bote", "init", "hamog", "moisture", "botelya", "tanom", "plastic bottle", "greenhouse", "tubig", "tumubo", "motubo", "kainit", "alisngaw"], "fact": {"tl": "Ang isang halaman sa loob ng nakatakip na plastik na bote ay nagiging maliit na greenhouse, kung saan naiipon ang init at hamog para manatiling basa at mainit ang halaman.", "en": "A plant inside a closed plastic bottle becomes a mini greenhouse, trapping heat and moisture so the plant stays warm and damp.", "bis": "Ang tanom sulod sa sirado nga plastik nga botelya mahimong gamay nga greenhouse, nga naghipos sa kainit ug alisngaw aron magpabilin nga basa ug init ang tanom."}, "source": "encyclopedia-stable consensus; DepEd G4 plant needs", "generator": "claude-workflow", "reviewed": false},
  {"id": "maya-bird-g3", "domain": "LIVING_THINGS", "topic": "maya bird", "grades": [3, 4, 5], "terms": ["maya", "ibon", "langgam", "pispis", "Eurasian tree sparrow", "munting kayumangging ibon", "lumilipad", "buto", "binhi", "small brown bird", "milikong maya", "molupad", "liso"], "fact": {"tl": "Ang maya ay isang maliit na kayumangging ibon na karaniwang nakikita sa mga bahay at bukid sa Pilipinas, at kumakain ito ng mga buto at maliliit na insekto.", "en": "The maya is a small brown bird commonly seen around Philippine homes and farms, and it eats seeds and tiny insects.", "bis": "Ang maya usa ka gamay nga kapehon nga langgam nga sagad makita sa mga balay ug uma sa Pilipinas, ug mokaon kini og mga liso ug gagmay nga insekto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "milkfish-bangus-g4", "domain": "LIVING_THINGS", "topic": "milkfish bangus", "grades": [3, 4, 5, 6], "terms": ["bangus", "milkfish", "isda", "isdang bangus", "pambansang isda", "national fish", "lumalangoy", "palaisdaan", "fishpond", "isda sa Pilipinas", "isda", "molangoy", "naglangoy", "punoan sa isda"], "fact": {"tl": "Ang bangus ay isang isdang may pilak na kaliskis na itinuturing na pambansang isda ng Pilipinas, at madalas itong inaalagaan sa mga palaisdaan.", "en": "The milkfish, or bangus, is a silvery-scaled fish considered the national fish of the Philippines, and it is often raised in fishponds.", "bis": "Ang bangus usa ka isda nga adunay pilak nga himbis nga giila nga nasudnong isda sa Pilipinas, ug kasagaran kini gialimahan sa mga punoan sa isda."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "milkfish-bangus-swim-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "how fish swim", "grades": [5, 6, 7], "terms": ["bangus", "milkfish", "lumalangoy", "palikpik", "buntot", "fins", "tail", "swim", "tubig", "itinutulak", "isda", "molangoy", "kapay", "ikog", "nagduso sa tubig"], "fact": {"tl": "Lumalangoy ang bangus sa pamamagitan ng pagkampay ng buntot at palikpik nito, na nagtutulak sa tubig pabalik upang ito ay sumulong.", "en": "A milkfish swims by sweeping its tail and fins, pushing water backward so its body moves forward.", "bis": "Ang bangus molangoy pinaagi sa pagwakay sa iyang ikog ug mga kapay, nga nagaduso sa tubig pabalik aron mosulong kini."}, "source": "NRC PS2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mint-herb-g4", "domain": "LIVING_THINGS", "topic": "mint herb", "grades": [3, 4, 5], "terms": ["mint", "yerbabuena", "herba buena", "halamang gamot", "halaman", "dahon", "mabangong dahon", "amoy", "herb", "leaves", "lamig", "tanom", "tambal nga tanom", "humot nga dahon", "presko"], "fact": {"tl": "Ang mint o yerbabuena ay isang halaman na may mabangong dahon na nagbibigay ng presko at malamig na amoy, at ginagamit ito sa pagkain at gamot.", "en": "Mint is a herb with fragrant leaves that give a cool, fresh smell, and people use it in food and medicine.", "bis": "Ang mint o yerbabuena usa ka tanom nga adunay humot nga mga dahon nga naghatag og presko ug bugnaw nga baho, ug gigamit kini sa pagkaon ug tambal."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "market-vegetable-stall-gulay-g3", "domain": "LIVING_THINGS", "topic": "vegetables are plant parts", "grades": [3, 4, 5], "terms": ["gulay", "vegetables", "talong", "kamatis", "kangkong", "ugat", "dahon", "bunga", "halaman", "palengke", "market", "utanon", "merkado", "gamot", "prutas sa tanom", "bahin sa tanom"], "fact": {"tl": "Ang mga gulay na ibinebenta sa palengke ay iba't ibang bahagi ng halaman—may ugat tulad ng karot, dahon tulad ng kangkong, at bunga tulad ng talong.", "en": "The vegetables sold at the market are different parts of plants—roots like carrots, leaves like kangkong, and fruits like eggplant.", "bis": "Ang mga utanon nga gibaligya sa merkado lain-laing bahin sa tanom—gamot sama sa karot, dahon sama sa kangkong, ug bunga sama sa talong."}, "source": "AAAS Benchmarks 5C; DepEd G3 plant parts", "generator": "claude-workflow", "reviewed": false},
  {"id": "millipede-coiled-defense-g4", "domain": "LIVING_THINGS", "topic": "millipede coiling defense", "grades": [4, 5, 6], "terms": ["millipede", "labod", "pumupulupot", "nagiging bilog", "pananggalang", "depensa", "panganib", "coil", "defense", "proteksyon", "naglikit", "nagbola", "panalipod", "kahadlok"], "fact": {"tl": "Kapag may panganib, pumupulupot ang millipede na parang spiral upang protektahan ang malambot na ilalim ng katawan nito.", "en": "When threatened, a millipede coils up into a tight spiral to protect the soft underside of its body.", "bis": "Kon adunay kapeligrohan, ang millipede maglikit nga morag spiral aron panalipdan ang humok nga ubos sa iyang lawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "molave-tree-g6", "domain": "LIVING_THINGS", "topic": "molave tree", "grades": [5, 6, 7, 8], "terms": ["molave", "tugas", "puno", "matibay na kahoy", "hardwood", "katutubong puno", "Vitex parviflora", "matigas", "kahoy", "tree", "native tree", "kahoy nga gahi", "tugas nga kahoy", "lig-on"], "fact": {"tl": "Ang molave ay isang katutubong puno sa Pilipinas na kilala sa napakatibay at matigas nitong kahoy, kaya't ginagamit ito sa paggawa ng muwebles at gusali.", "en": "The molave is a native Philippine tree known for its very strong, hard wood, which is used to make furniture and buildings.", "bis": "Ang molave usa ka lumad nga kahoy sa Pilipinas nga ilado sa iyang lig-on ug gahi kaayo nga kahoy, mao nga gigamit kini sa paghimo og muwebles ug mga building."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mold-bread-observation-g5", "domain": "LIVING_THINGS", "topic": "bread mold growth", "grades": [4, 5, 6, 7], "terms": ["amag", "mold", "tinapay", "bread mold", "fungus", "halamang singaw", "basa", "mainit", "tumutubo", "spore", "amag sa tinapay", "fungi", "agup-op", "motubo", "humok ug init"], "fact": {"tl": "Ang amag na tumutubo sa lumang tinapay ay isang uri ng fungus, at mas mabilis itong lumaganap kapag basa at mainit ang kapaligiran.", "en": "The mold that grows on old bread is a kind of fungus, and it spreads faster when the surroundings are damp and warm.", "bis": "Ang agup-op nga motubo sa daang tinapay usa ka matang sa fungus, ug mas paspas kini mokatag kon basa ug init ang palibot."}, "source": "AAAS Benchmarks 5A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mold-hyphae-network-g8", "domain": "LIVING_THINGS", "topic": "mold hyphae", "grades": [7, 8, 9, 10], "terms": ["amag", "mold", "hyphae", "sinulid", "fungus", "mycelium", "sumisipsip ng sustansya", "thread", "fungi", "agup-op", "lanot", "fungal threads", "misipsip og sustansya"], "fact": {"tl": "Ang amag ay gawa sa maraming mahaba't manipis na sinulid na tinatawag na hyphae, na sumisipsip ng sustansya mula sa kinakapitan nitong pagkain.", "en": "Mold is made of many long, thin threads called hyphae, which absorb nutrients from the food it grows on.", "bis": "Ang agup-op gihimo gikan sa daghang taas ug nipis nga mga lanot nga gitawag og hyphae, nga misuyop sa sustansya gikan sa pagkaon nga gituboan niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mitosis-stages-g9", "domain": "LIVING_THINGS", "topic": "mitosis cell division", "grades": [8, 9, 10], "terms": ["mitosis", "paghahati ng selula", "cell division", "dalawang selula", "chromosome", "magkapareho", "nagdadami", "two identical cells", "selula", "pagpilo sa selula", "duha ka pareho nga selula", "nagdaghan", "kromosoma"], "fact": {"tl": "Ang mitosis ay ang proseso kung saan ang isang selula ay nahahati upang gumawa ng dalawang bagong selulang magkapareho ang mga chromosome.", "en": "Mitosis is the process in which one cell divides to produce two new cells with identical chromosomes.", "bis": "Ang mitosis mao ang proseso diin ang usa ka selula mapikas aron mohimo og duha ka bag-ong selula nga managsama ang mga kromosoma."}, "source": "AAAS Benchmarks 5C; DepEd G9 cell division", "generator": "claude-workflow", "reviewed": false},
  {"id": "mitochondrion-organelle-g9", "domain": "LIVING_THINGS", "topic": "mitochondrion powerhouse", "grades": [8, 9, 10], "terms": ["mitochondria", "mitochondrion", "organelle", "selula", "enerhiya", "powerhouse", "respirasyon", "gumagawa ng enerhiya", "ATP", "cell", "energy", "mitokondriya", "kusog", "naghimo og enerhiya"], "fact": {"tl": "Ang mitochondria ang tinatawag na 'powerhouse' ng selula dahil dito gumagawa ng enerhiyang ginagamit ng selula mula sa pagkain.", "en": "The mitochondria are called the 'powerhouse' of the cell because they make the energy the cell uses from food.", "bis": "Ang mitochondria gitawag nga 'powerhouse' sa selula tungod kay dinhi gihimo ang enerhiya nga gigamit sa selula gikan sa pagkaon."}, "source": "AAAS Benchmarks 5C; DepEd G9 cell", "generator": "claude-workflow", "reviewed": false},
  {"id": "monggo-plant-g4", "domain": "LIVING_THINGS", "topic": "mung bean plant", "grades": [3, 4, 5], "terms": ["monggo", "mung bean", "munggo", "buto", "binhi", "halaman", "tumutubo", "ugat", "dahon", "tanom", "seed", "sprout", "liso", "tubo sa monggo", "motubo"], "fact": {"tl": "Ang monggo ay isang halaman na madaling itanim, at mula sa maliit nitong buto ay tumutubo ang ugat at dahon sa loob lamang ng ilang araw.", "en": "The mung bean is an easy plant to grow, and from its small seed a root and leaves sprout in just a few days.", "bis": "Ang monggo usa ka tanom nga sayon itanom, ug gikan sa gamay niini nga liso motubo ang gamot ug dahon sulod lang sa pipila ka adlaw."}, "source": "DepEd G4 plant life cycle; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "monohybrid-cross-mongo-g10", "domain": "LIVING_THINGS", "topic": "monohybrid cross inheritance", "grades": [9, 10], "terms": ["monohybrid cross", "pagmamana", "dominant", "recessive", "trait", "katangian", "genetics", "Punnett", "namamana", "namana", "gene", "panulundon", "dominante", "recessive nga kinaiya", "mapanunod"], "fact": {"tl": "Sa monohybrid cross, pinag-aaralan kung paano namamana ang isang katangian, kung saan natatakpan ng dominanteng katangian ang recessive sa mga supling.", "en": "In a monohybrid cross, scientists study how a single trait is inherited, where a dominant trait masks a recessive one in the offspring.", "bis": "Sa monohybrid cross, gitun-an kung giunsa pagpanunod ang usa ka kinaiya, diin ang dominante nga kinaiya motabon sa recessive sa mga anak."}, "source": "AAAS Benchmarks 5B; DepEd G10 heredity", "generator": "claude-workflow", "reviewed": false},
  {"id": "morning-glory-flower-g3", "domain": "LIVING_THINGS", "topic": "morning glory flower", "grades": [3, 4, 5], "terms": ["morning glory", "bulaklak", "halaman", "umaga", "namumukadkad", "gumagapang", "baging", "flower", "vine", "umakyat", "bulak", "tanom", "buntag", "namukhad", "nagsaka"], "fact": {"tl": "Ang morning glory ay isang gumagapang na halaman na ang mga bulaklak nito ay namumukadkad tuwing umaga at nagsasara sa hapon.", "en": "The morning glory is a climbing plant whose flowers open in the morning and close by the afternoon.", "bis": "Ang morning glory usa ka nagkamang nga tanom kansang mga bulak mobukhad sa buntag ug mosira pagkahapon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mosquito-borne-disease-prevention-g5", "domain": "LIVING_THINGS", "topic": "preventing mosquito-borne disease", "grades": [4, 5, 6, 7], "terms": ["lamok", "mosquito", "dengue", "sakit", "tubig na nakatigil", "stagnant water", "pamiminsala", "pag-iwas", "malaria", "iwas", "stagnant nga tubig", "pugong sa sakit", "lamok nga nagdala og sakit"], "fact": {"tl": "Ang ilang lamok ay maaaring magdala ng sakit tulad ng dengue, kaya mahalagang alisin ang nakatigil na tubig kung saan sila nangingitlog.", "en": "Some mosquitoes can carry diseases like dengue, so it is important to remove stagnant water where they lay their eggs.", "bis": "Ang ubang lamok makadala og sakit sama sa dengue, mao nga importante nga kuhaon ang nagtigom nga tubig diin sila mangitlog."}, "source": "encyclopedia-stable consensus; DepEd health science", "generator": "claude-workflow", "reviewed": false},
  {"id": "mosquito-net-over-bed-g4", "domain": "LIVING_THINGS", "topic": "mosquito net protection", "grades": [3, 4, 5, 6], "terms": ["kulambo", "mosquito net", "lamok", "kama", "proteksyon", "kagat", "barrier", "harang", "dengue", "katulog", "moskitero", "panalipod sa lamok", "pagtulog", "paak sa lamok", "babag"], "fact": {"tl": "Ang kulambo ay isang lambat na inilalagay sa ibabaw ng higaan upang hindi makakagat ang mga lamok habang natutulog.", "en": "A mosquito net is a mesh placed over a bed to keep mosquitoes from biting while a person sleeps.", "bis": "Ang moskitero usa ka pukot nga ibutang ibabaw sa higdaanan aron dili makapaak ang mga lamok samtang natulog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "moth-gamugamo-g4", "domain": "LIVING_THINGS", "topic": "moth", "grades": [3, 4, 5, 6], "terms": ["gamugamo", "moth", "insekto", "ilaw", "lumilipad", "gabi", "pakpak", "metamorphosis", "uod", "insect", "wings", "night", "anunugba", "alibangbang sa gabii", "molupad", "ilaw sa gabii"], "fact": {"tl": "Ang gamugamo ay isang insektong kadalasang lumilipad sa gabi at naaakit sa ilaw, at galing ito sa isang uod na nag-iba ng anyo.", "en": "A moth is an insect that usually flies at night and is drawn to light, and it grows from a caterpillar that changes form.", "bis": "Ang anunugba usa ka insekto nga kasagaran molupad sa gabii ug madani sa kahayag, ug naggikan kini sa usa ka ulod nga miusab og porma."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks 5B", "generator": "claude-workflow", "reviewed": false},
  {"id": "moss-clump-g5", "domain": "LIVING_THINGS", "topic": "moss", "grades": [4, 5, 6, 7], "terms": ["lumot", "moss", "halaman", "basa", "lilim", "walang bulaklak", "spore", "bato", "puno", "damp", "shade", "tanom nga walay bulak", "lumot sa bato", "humok nga lumot", "lilim ug basa"], "fact": {"tl": "Ang lumot ay isang maliit na halamang walang bulaklak na tumutubo sa basa at malilim na lugar tulad ng mga bato at puno.", "en": "Moss is a small flowerless plant that grows in damp, shady places such as rocks and tree trunks.", "bis": "Ang lumot usa ka gamay nga tanom nga walay bulak nga motubo sa basa ug landong nga mga dapit sama sa mga bato ug punoan sa kahoy."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks 5A", "generator": "claude-workflow", "reviewed": false},
  {"id": "moray-eel-reef-g5", "domain": "LIVING_THINGS", "topic": "moray eel", "grades": [4, 5, 6, 7], "terms": ["moray eel", "palos", "igat", "bahura", "coral reef", "isda", "lungga", "predator", "nagtatago", "reef", "eel", "indol", "kasagang sa bato", "nagtago", "isdang parang ahas"], "fact": {"tl": "Ang moray eel ay isang mahaba't parang ahas na isda na nakatira sa mga bahura, at madalas itong nagtatago sa mga butas ng bato.", "en": "The moray eel is a long, snake-like fish that lives in coral reefs and often hides inside cracks in the rocks.", "bis": "Ang moray eel usa ka taas, morag bitin nga isda nga nagpuyo sa mga bahura, ug kasagaran nagatago sulod sa mga liki sa bato."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mouse-deer-pilandok-g5", "domain": "LIVING_THINGS", "topic": "Philippine mouse-deer pilandok", "grades": [4, 5, 6, 7], "terms": ["pilandok", "mouse-deer", "Philippine mouse-deer", "maliit na hayop", "Palawan", "Balabac", "gubat", "endemic", "katutubo", "pinakamaliit", "tiny deer", "kinagamyan nga usa", "lasang", "mananap sa Pilipinas", "endemiko"], "fact": {"tl": "Ang pilandok ay isa sa pinakamaliit na hayop na may sungay-na-katulad ng usa sa mundo, at matatagpuan ito sa mga isla ng Balabac at Palawan.", "en": "The Philippine mouse-deer, or pilandok, is one of the world's smallest hoofed deer-like animals, found on the islands of Balabac and Palawan.", "bis": "Ang pilandok usa sa kinagamyan nga mananap nga morag usa sa kalibotan, ug makit-an kini sa mga isla sa Balabac ug Palawan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "muscles-flexing-bicep-g6", "domain": "LIVING_THINGS", "topic": "muscles and movement", "grades": [5, 6, 7, 8], "terms": ["kalamnan", "muscle", "biceps", "braso", "humihila", "buto", "galaw", "kontraksyon", "pulled", "bones", "movement", "kaunoran", "bukton", "kuyhad", "naghulbot", "gibira sa unod"], "fact": {"tl": "Gumagalaw ang ating katawan dahil ang mga kalamnan ay umuurong at humihila sa mga buto, gaya ng biceps na yumuyukod sa braso.", "en": "Our body moves because muscles contract and pull on bones, like the biceps bending the arm.", "bis": "Ang atong lawas molihok tungod kay ang mga unod mokuyhad ug mobira sa mga bukog, sama sa biceps nga nagpaliko sa bukton."}, "source": "AAAS Benchmarks 6A; DepEd G6 human body", "generator": "claude-workflow", "reviewed": false},
  {"id": "monkey-eating-macaque-g5", "domain": "LIVING_THINGS", "topic": "long-tailed macaque", "grades": [4, 5, 6, 7], "terms": ["unggoy", "macaque", "long-tailed macaque", "gubat", "prutas", "umaakyat", "puno", "mammal", "kawan", "monkey", "amo", "lasang", "mosaka sa kahoy", "prutas ug liso", "panon"], "fact": {"tl": "Ang long-tailed macaque ay isang uri ng unggoy na nakatira sa mga gubat ng Pilipinas, at kumakain ito ng prutas, dahon, at maliliit na hayop.", "en": "The long-tailed macaque is a kind of monkey that lives in Philippine forests, and it eats fruit, leaves, and small animals.", "bis": "Ang long-tailed macaque usa ka matang sa unggoy nga nagpuyo sa mga lasang sa Pilipinas, ug mokaon kini og prutas, dahon, ug gagmay nga mananap."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "market-fruit-stall-tropical-g3", "domain": "LIVING_THINGS", "topic": "tropical fruits are seed-bearing", "grades": [3, 4, 5], "terms": ["prutas", "tropical fruit", "mangga", "saging", "papaya", "buto", "binhi", "halaman", "bunga", "palengke", "matamis", "prutas sa tropiko", "bunga sa tanom", "liso", "merkado", "tam-is"], "fact": {"tl": "Ang mga prutas sa tropiko tulad ng mangga, saging, at papaya ay bunga ng mga halaman, at marami sa mga ito ay may butong maaaring tumubo bilang bagong halaman.", "en": "Tropical fruits like mango, banana, and papaya are the fruits of plants, and many of them carry seeds that can grow into new plants.", "bis": "Ang mga prutas sa tropiko sama sa mangga, saging, ug papaya mao ang bunga sa mga tanom, ug daghan niini adunay liso nga mahimong motubo isip bag-ong tanom."}, "source": "AAAS Benchmarks 5C; DepEd G3 plants", "generator": "claude-workflow", "reviewed": false},
  {"id": "muscle-cell-fibers-g7", "domain": "LIVING_THINGS", "topic": "muscle cells and fibers", "grades": [7, 8], "terms": ["muscle cell", "muscle fiber", "kalamnan", "selula ng kalamnan", "hibla ng kalamnan", "unod sa kalamnan", "lanot sa kaunlan", "kontraksiyon", "contract", "kuyos"], "fact": {"tl": "Ang mga selula ng kalamnan ay mahahabang hibla na umuurong at humahaba para makakilos ang ating katawan.", "en": "Muscle cells are long fibers that shorten and relax, letting the body move.", "bis": "Ang mga selula sa kaunlan kay tag-as nga mga lanot nga mokuyos ug moluag aron makalihok ang atong lawas."}, "source": "encyclopedia-stable consensus; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "mudskipper-tambasakan-g5", "domain": "LIVING_THINGS", "topic": "mudskipper fish", "grades": [4, 5, 6], "terms": ["mudskipper", "tambasakan", "isda", "bakawan", "mangrove", "isdang naglalakad", "fish out of water", "palikpik", "putikan", "lapok", "kamang"], "fact": {"tl": "Ang tambasakan ay isdang naninirahan sa putikan ng bakawan at kayang gumapang sa lupa gamit ang malalakas na palikpik habang humihinga sa balat at bibig.", "en": "The mudskipper is a fish that lives in mangrove mudflats and can crawl on land using strong fins while breathing through its skin and mouth.", "bis": "Ang tambasakan kay isda nga nagpuyo sa lapok sa bakawan ug makakamang sa yuta pinaagi sa kusgan nga mga palikpik samtang moginhawa pinaagi sa panit ug baba."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "muskmelon-melon-g4", "domain": "LIVING_THINGS", "topic": "muskmelon fruit", "grades": [3, 4, 5], "terms": ["muskmelon", "melon", "cantaloupe", "prutas", "bunga", "tam-is nga prutas", "matamis na prutas", "buto", "seeds", "liso", "gumagapang"], "fact": {"tl": "Ang melon ay malaki at matamis na prutas na may makatas na laman at maraming buto sa loob, at tumutubo bilang gumagapang na halaman.", "en": "The muskmelon is a large, sweet fruit with juicy flesh and many seeds inside, grown on a trailing vine.", "bis": "Ang melon kay dako ug tam-is nga prutas nga adunay tubigon nga unod ug daghang liso sa sulod, ug motubo isip nagakamang nga tanom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mustasa-mustard-greens-g4", "domain": "LIVING_THINGS", "topic": "mustard greens vegetable", "grades": [3, 4, 5], "terms": ["mustasa", "mustard greens", "gulay", "utanon", "dahon", "dahong gulay", "leafy vegetable", "anghang", "pait", "mustard"], "fact": {"tl": "Ang mustasa ay madahong gulay na may bahagyang anghang na lasa at masustansiya, kaya madalas itong idinaragdag sa sabaw at ensalada.", "en": "Mustard greens are a leafy vegetable with a slightly spicy taste that are nutritious and often added to soups and salads.", "bis": "Ang mustasa kay dahonon nga utanon nga adunay gamay nga anghang nga lami ug puno sa sustansiya, busa kanunay idugang sa sabaw ug ensalada."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mutation-types-g9", "domain": "LIVING_THINGS", "topic": "DNA mutation", "grades": [8, 9, 10], "terms": ["mutation", "mutasyon", "pagbabago sa DNA", "kausaban sa DNA", "gene", "henes", "DNA", "namamana", "trait", "pagkakaiba"], "fact": {"tl": "Ang mutasyon ay pagbabago sa pagkakasunod-sunod ng DNA ng organismo, at maaari itong walang epekto, makasama, o makatulong sa kaligtasan ng nilalang.", "en": "A mutation is a change in an organism's DNA sequence, and it can be harmless, harmful, or helpful to the organism's survival.", "bis": "Ang mutasyon kay kausaban sa han-ay sa DNA sa usa ka organismo, ug mahimong walay epekto, makadaot, o makatabang sa pagkabuhi niini."}, "source": "NRC LS3.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mynah-bird-martines-g4", "domain": "LIVING_THINGS", "topic": "mynah bird", "grades": [3, 4, 5], "terms": ["mynah", "martines", "ibon", "langgam", "itim na ibon", "black bird", "gumagaya ng tunog", "mimic", "huni", "tingog"], "fact": {"tl": "Ang martines ay maitim na ibon na may dilaw na tuka at paligid ng mata, at kilala ito sa paggaya ng iba't ibang tunog kabilang ang boses ng tao.", "en": "The mynah is a dark bird with a yellow beak and eye patch, known for mimicking many sounds including human speech.", "bis": "Ang martines kay itom nga langgam nga adunay dalag nga sungo ug palibot sa mata, ug ilado sa pagsundog sa nagkalainlaing tingog lakip na ang tingog sa tawo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "nerve-cell-signal-path-g8", "domain": "LIVING_THINGS", "topic": "nerve cell signaling", "grades": [7, 8, 9], "terms": ["nerve cell", "neuron", "selula ng nerbiyo", "selula sa nerbiyo", "signal", "senyas", "impulse", "utak", "brain", "mensahe", "utok"], "fact": {"tl": "Ang selula ng nerbiyo o neuron ay naghahatid ng mga senyas na parang elektrikong mensahe mula sa isang bahagi ng katawan patungo sa utak at pabalik.", "en": "A nerve cell, or neuron, carries signals like tiny electrical messages from one part of the body to the brain and back.", "bis": "Ang selula sa nerbiyo o neuron nagdala sa mga senyas nga sama sa gagmay nga elektrikong mensahe gikan sa usa ka bahin sa lawas paingon sa utok ug balik."}, "source": "encyclopedia-stable consensus; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "nerve-signal-brain-muscle-g8", "domain": "LIVING_THINGS", "topic": "brain to muscle signal", "grades": [7, 8, 9], "terms": ["nerve signal", "senyas ng nerbiyo", "senyas sa nerbiyo", "utak", "brain", "kalamnan", "kaunlan", "muscle", "kilos", "lihok", "utok"], "fact": {"tl": "Kapag gusto nating kumilos, nagpapadala ang utak ng senyas sa pamamagitan ng mga nerbiyo papunta sa kalamnan upang ito ay umurong.", "en": "When we want to move, the brain sends a signal through nerves to a muscle, telling it to contract.", "bis": "Kung gusto natong molihok, ang utok magpadala og senyas pinaagi sa mga nerbiyo paingon sa kaunlan aron kini mokuyos."}, "source": "encyclopedia-stable consensus; NRC LS1.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "nipa-palm-g5", "domain": "LIVING_THINGS", "topic": "nipa palm", "grades": [4, 5, 6], "terms": ["nipa", "sasa", "nipa palm", "palma", "pawid", "bakawan", "mangrove", "alat na tubig", "brackish", "pawod", "atip"], "fact": {"tl": "Ang nipa o sasa ay palmang tumutubo sa maalat na putikan ng bakawan, at ang mga dahon nito ay ginagawang pawid na pantakip sa bubong.", "en": "The nipa palm grows in the brackish mud of mangroves, and its leaves are woven into thatch for roofing.", "bis": "Ang nipa o sasa kay palma nga motubo sa parat nga lapok sa bakawan, ug ang mga dahon niini gihimong pawod nga atip sa atop."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "niyog-niyogan-g5", "domain": "LIVING_THINGS", "topic": "Rangoon creeper vine", "grades": [4, 5, 6], "terms": ["niyog-niyogan", "niog-niogan", "Rangoon creeper", "baging", "gapang", "namumulaklak", "bulaklak", "bulak", "ornamental vine", "puti at pula", "mabango"], "fact": {"tl": "Ang niyog-niyogan ay gumagapang na baging na may mababangong bulaklak na nagbabago ang kulay mula puti hanggang pula habang tumatanda.", "en": "The niyog-niyogan is a climbing vine whose fragrant flowers change color from white to red as they age.", "bis": "Ang niyog-niyogan kay nagakamang nga baging nga adunay humot nga mga bulak nga mausab ang kolor gikan puti ngadto pula samtang motigulang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "no-take-zone-fish-recovery-g6", "domain": "LIVING_THINGS", "topic": "marine protected area", "grades": [5, 6, 7], "terms": ["no-take zone", "marine sanctuary", "sanctuary", "bawal mangisda", "protektadong dagat", "gibawal manginsda", "pangisdaan", "dumaragdag ang isda", "fish recovery", "konserbasyon", "marine protected area"], "fact": {"tl": "Ang no-take zone ay bahagi ng dagat kung saan bawal mangisda, kaya nakakapagparami ang mga isda at unti-unting bumabalik ang dami nila.", "en": "A no-take zone is part of the sea where fishing is banned, so fish can breed and their numbers slowly recover.", "bis": "Ang no-take zone kay bahin sa dagat diin gibawal ang pagpangisda, busa makapasanay ang mga isda ug hinay-hinay nga modaghan pag-usab."}, "source": "encyclopedia-stable consensus; DepEd Science ecosystems", "generator": "claude-workflow", "reviewed": false},
  {"id": "nutmeg-fruit-g5", "domain": "LIVING_THINGS", "topic": "nutmeg spice", "grades": [4, 5, 6], "terms": ["nutmeg", "moskada", "pampalasa", "panimpla", "spice", "buto", "liso", "prutas", "mabango", "mainit-tamis", "humot"], "fact": {"tl": "Ang nutmeg ay pampalasang nanggagaling sa tuyong buto sa loob ng prutas ng punong nutmeg, at kilala ito sa mabango at mainit-tamis na lasa.", "en": "Nutmeg is a spice made from the dried seed inside the fruit of the nutmeg tree, prized for its warm, fragrant flavor.", "bis": "Ang nutmeg kay panimpla nga gikan sa uga nga liso sulod sa prutas sa kahoy nga nutmeg, ilado tungod sa humot ug init nga lami niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "okra-fruit-g4", "domain": "LIVING_THINGS", "topic": "okra vegetable", "grades": [3, 4, 5], "terms": ["okra", "lady's finger", "gulay", "utanon", "bunga", "malagkit", "slimy", "buto", "liso", "berde", "sabaw"], "fact": {"tl": "Ang okra ay berdeng gulay na hugis daliri na may malagkit na laman at maraming buto, at masustansiya itong idinaragdag sa sabaw.", "en": "Okra is a green, finger-shaped vegetable with slimy flesh and many seeds, and it is a nutritious addition to soups.", "bis": "Ang okra kay berde nga utanon nga porma og tudlo nga adunay pilit nga unod ug daghang liso, ug masustansiya idugang sa sabaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "olive-ridley-hatchling-g5", "domain": "LIVING_THINGS", "topic": "sea turtle hatchling", "grades": [4, 5, 6], "terms": ["olive ridley", "pawikan", "sea turtle", "hatchling", "anak ng pawikan", "piso sa pawikan", "itlog", "baybayin", "dagat", "pugad", "nangingitlog"], "fact": {"tl": "Ang olive ridley ay isang uri ng pawikan na nangingitlog sa buhanginan, at pagkapisa ng maliliit na anak ay agad silang gumagapang papunta sa dagat.", "en": "The olive ridley is a kind of sea turtle that lays its eggs on sandy beaches, and its tiny hatchlings crawl straight to the sea after hatching.", "bis": "Ang olive ridley kay usa ka klase sa pawikan nga mangitlog sa balas, ug human mapusa ang gagmay nga mga anak, dihadiha kini mokamang paingon sa dagat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "onion-skin-cells-microscope-g7", "domain": "LIVING_THINGS", "topic": "plant cells under microscope", "grades": [6, 7, 8], "terms": ["onion skin", "balat ng sibuyas", "panit sa sibuyas", "cells", "selula", "mikroskopyo", "microscope", "cell wall", "dingding ng selula", "nucleus", "plant cell", "halamang selula"], "fact": {"tl": "Kapag tinitingnan sa mikroskopyo, ang manipis na balat ng sibuyas ay nagpapakita ng mga selulang hugis-tisa na may matibay na dingding, patunay na buo ang halaman sa maliliit na selula.", "en": "Under a microscope, the thin skin of an onion shows brick-shaped cells with firm walls, proving that plants are made of tiny cells.", "bis": "Kon tan-awon sa mikroskopyo, ang nipis nga panit sa sibuyas magpakita og mga selula nga porma og tisa nga adunay gahi nga bongbong, pamatuod nga ang tanom hinimo sa gagmay nga mga selula."}, "source": "encyclopedia-stable consensus; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "oral-rehydration-oresol-g6", "domain": "MATTER", "topic": "oral rehydration solution", "grades": [5, 6, 7], "terms": ["oresol", "oral rehydration", "ORS", "tubig at asin", "tubig asin asukal", "rehydration", "pagtatae", "kalibanga", "dehydration", "solusyon", "asukal at asin"], "fact": {"tl": "Ang oresol ay timplang tubig na may tamang dami ng asin at asukal na nagpapanumbalik ng tubig at mineral sa katawan ng taong may pagtatae.", "en": "Oral rehydration solution (oresol) is water mixed with the right amounts of salt and sugar that replaces water and minerals lost during diarrhea.", "bis": "Ang oresol kay tubig nga gisagolan og hustong gidaghanon sa asin ug asukal nga nagapuli sa tubig ug mineral nga nawala sa lawas atol sa kalibanga."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "oregano-herb-g4", "domain": "LIVING_THINGS", "topic": "oregano herb", "grades": [3, 4, 5], "terms": ["oregano", "herbal", "halamang gamot", "tanom nga tambal", "dahon", "mabango", "pampalasa", "ubo", "lunas sa ubo", "herb", "humot"], "fact": {"tl": "Ang oregano ay mabangong halamang may makapal na dahon na ginagamit bilang pampalasa at karaniwang itinuturing na panlunas sa ubo sa Pilipinas.", "en": "Oregano is a fragrant herb with thick leaves used as a seasoning and commonly used as a folk remedy for cough in the Philippines.", "bis": "Ang oregano kay humot nga tanom nga adunay baga nga dahon nga gigamit isip panimpla ug kasagarang gamiton nga tambal sa ubo sa Pilipinas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "organ-brain-g6", "domain": "LIVING_THINGS", "topic": "the brain", "grades": [5, 6, 7], "terms": ["brain", "utak", "utok", "organ", "nervous system", "sistema ng nerbiyo", "pag-iisip", "kontrol ng katawan", "memory", "alaala", "panumduman"], "fact": {"tl": "Ang utak ang sentro ng kontrol ng katawan; ito ang nag-iisip, nag-uutos sa kilos, at nag-iimbak ng mga alaala.", "en": "The brain is the body's control center; it thinks, commands movement, and stores memories.", "bis": "Ang utok mao ang sentro sa pagdumala sa lawas; kini ang naghunahuna, nagsugo sa lihok, ug nagtipig sa mga panumduman."}, "source": "encyclopedia-stable consensus; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "organ-heart-g6", "domain": "LIVING_THINGS", "topic": "the heart", "grades": [5, 6, 7], "terms": ["heart", "puso", "kasingkasing", "dugo", "blood", "pumping", "tibok", "pitik", "circulatory", "sirkulasyon", "organ", "bomba ng dugo"], "fact": {"tl": "Ang puso ay kalamnang nagsisilbing bomba na walang tigil na nagpapadaloy ng dugo sa buong katawan.", "en": "The heart is a muscular pump that keeps blood flowing throughout the whole body.", "bis": "Ang kasingkasing kay unodnon nga bomba nga walay hunong nga nagapaagas sa dugo sa tibuok lawas."}, "source": "encyclopedia-stable consensus; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "organ-kidneys-g6", "domain": "LIVING_THINGS", "topic": "the kidneys", "grades": [5, 6, 7], "terms": ["kidneys", "bato", "kidney", "ihi", "pagsala ng dugo", "filter", "dumi sa dugo", "urine", "organ", "pantog", "salaan"], "fact": {"tl": "Ang mga bato ay dalawang organong humuhugas o sumasala sa dugo at nagaalis ng dumi at sobrang tubig sa pamamagitan ng ihi.", "en": "The kidneys are two organs that filter the blood and remove waste and extra water as urine.", "bis": "Ang mga kidney kay duha ka organo nga nagasala sa dugo ug nagakuha sa hugaw ug sobra nga tubig pinaagi sa ihi."}, "source": "encyclopedia-stable consensus; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "organ-lungs-g6", "domain": "LIVING_THINGS", "topic": "the lungs", "grades": [5, 6, 7], "terms": ["lungs", "baga", "lung", "hangin", "oxygen", "oksiheno", "paghinga", "ginhawa", "carbon dioxide", "respiratory", "organ"], "fact": {"tl": "Ang mga baga ay dalawang organ na humihigop ng oksiheno mula sa hangin at naglalabas ng carbon dioxide tuwing tayo ay huminga.", "en": "The lungs are two organs that take in oxygen from the air and release carbon dioxide each time we breathe.", "bis": "Ang mga baga kay duha ka organo nga nagasuyop sa oksiheno gikan sa hangin ug nagapagawas sa carbon dioxide matag kita moginhawa."}, "source": "encyclopedia-stable consensus; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "organ-stomach-g6", "domain": "LIVING_THINGS", "topic": "the stomach", "grades": [5, 6, 7], "terms": ["stomach", "tiyan", "sikmura", "pagtunaw ng pagkain", "digest", "acid", "asido", "pagkain", "digestion", "organ", "tunaw"], "fact": {"tl": "Ang sikmura ay organong parang sisidlan na gumigiling at nagtutunaw ng pagkain gamit ang malakas na asido bago ito dumaan sa bituka.", "en": "The stomach is a pouch-like organ that churns and breaks down food with strong acid before it passes to the intestines.", "bis": "Ang tiyan kay organo nga sama sa sudlanan nga nagagaling ug nagatunaw sa pagkaon pinaagi sa kusgan nga asido sa dili pa kini moagi sa tinai."}, "source": "encyclopedia-stable consensus; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "overfishing-empty-net-g6", "domain": "LIVING_THINGS", "topic": "overfishing", "grades": [5, 6, 7], "terms": ["overfishing", "sobrang pangingisda", "sobra nga pagpangisda", "nauubos na isda", "kakulangan ng isda", "empty net", "lambat", "pukot", "konserbasyon", "naubos"], "fact": {"tl": "Ang sobrang pangingisda ay nangyayari kapag mas maraming isda ang nahuhuli kaysa sa nakakapagparami, kaya unti-unting nauubos ang mga isda sa dagat.", "en": "Overfishing happens when more fish are caught than can reproduce, so the fish in the sea slowly run out.", "bis": "Ang sobra nga pagpangisda mahitabo kon mas daghan ang isda nga madakpan kaysa makasanay, busa hinay-hinay nga maubos ang mga isda sa dagat."}, "source": "encyclopedia-stable consensus; DepEd Science ecosystems", "generator": "claude-workflow", "reviewed": false},
  {"id": "oxygen-bubbles-water-plant-g6", "domain": "LIVING_THINGS", "topic": "photosynthesis oxygen release", "grades": [5, 6, 7], "terms": ["oxygen bubbles", "bula ng oksiheno", "bula sa oksiheno", "halaman sa tubig", "tanom sa tubig", "water plant", "photosynthesis", "potosintesis", "oksiheno", "araw", "liwanag"], "fact": {"tl": "Ang mga halamang nasa ilalim ng tubig ay naglalabas ng maliliit na bula ng oksiheno habang gumagawa sila ng pagkain mula sa liwanag ng araw sa proseso ng potosintesis.", "en": "Underwater plants release tiny oxygen bubbles as they make food from sunlight through photosynthesis.", "bis": "Ang mga tanom ilalom sa tubig nagapagawas og gagmay nga bula sa oksiheno samtang naghimo sila og pagkaon gikan sa kahayag sa adlaw pinaagi sa potosintesis."}, "source": "encyclopedia-stable consensus; NRC LS1.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "oyster-mushroom-g5", "domain": "LIVING_THINGS", "topic": "oyster mushroom", "grades": [4, 5, 6], "terms": ["oyster mushroom", "kabute", "uhong", "fungus", "fungi", "decomposer", "kahoy", "bulok na kahoy", "dunot nga kahoy", "patay na halaman"], "fact": {"tl": "Ang oyster mushroom ay kabuteng tumutubo sa bulok na kahoy at hindi gumagawa ng sariling pagkain, sa halip ay kumukuha ito ng sustansiya mula sa patay na halaman.", "en": "The oyster mushroom is a fungus that grows on rotting wood and does not make its own food; instead it takes nutrients from dead plant matter.", "bis": "Ang oyster mushroom kay uhong nga motubo sa dunot nga kahoy ug dili maghimo og kaugalingong pagkaon; hinuon, mokuha kini og sustansiya gikan sa patay nga tanom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "palawan-peacock-pheasant-g5", "domain": "LIVING_THINGS", "topic": "Palawan peacock-pheasant", "grades": [4, 5, 6], "terms": ["Palawan peacock-pheasant", "tandikan", "ibon", "langgam", "endemic", "katutubo", "Palawan", "kagubatan", "balahibo", "balhibo", "nanganganib", "endangered"], "fact": {"tl": "Ang Palawan peacock-pheasant o tandikan ay ibong matatagpuan lamang sa kagubatan ng Palawan, at ang lalaki ay may makintab na bughaw-berdeng balahibo na hugis-mata sa buntot.", "en": "The Palawan peacock-pheasant, or tandikan, is a bird found only in the forests of Palawan, and the male has shiny blue-green eye-shaped feathers on its tail.", "bis": "Ang Palawan peacock-pheasant o tandikan kay langgam nga makit-an lamang sa kalasangan sa Palawan, ug ang laki adunay sinaw nga asul-berde nga balhibo nga porma og mata sa ikog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pandan-leaves-g4", "domain": "LIVING_THINGS", "topic": "pandan plant", "grades": [3, 4, 5], "terms": ["pandan", "dahon ng pandan", "dahon sa pandan", "screwpine", "mabango", "aroma", "kanin", "luto", "pampabango", "halaman", "berdeng dahon"], "fact": {"tl": "Ang pandan ay halamang may mahaba at berdeng dahon na mabango, kaya idinaragdag ito sa kanin at matamis na pagkain para bigyan ng amoy at kulay.", "en": "Pandan is a plant with long green leaves that smell sweet, so they are added to rice and desserts to give them aroma and color.", "bis": "Ang pandan kay tanom nga adunay tag-as ug berde nga dahon nga humot, busa idugang kini sa kan-on ug tam-is nga pagkaon aron mahatagan og humot ug kolor."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "parasitic-vine-strangling-g7", "domain": "LIVING_THINGS", "topic": "parasitic and strangling vines", "grades": [6, 7, 8], "terms": ["parasitic vine", "baging na parasito", "baging nga parasito", "strangling", "namamarasito", "host plant", "punong pinagtutubuan", "sumisipsip ng sustansiya", "parasite", "pumupulupot", "liyok"], "fact": {"tl": "May mga baging na namamarasito na pumupulupot sa ibang halaman at sumisipsip ng tubig at sustansiya mula rito, na maaaring makasakal at makamatay sa punong pinagtutubuan.", "en": "Some parasitic vines wrap around other plants and suck water and nutrients from them, which can strangle and kill the host plant.", "bis": "Adunay mga baging nga parasito nga moliyok sa ubang tanom ug mosuyop sa tubig ug sustansiya gikan niini, nga makatuok ug makapatay sa tanom nga gibutangan."}, "source": "encyclopedia-stable consensus; NRC LS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "patani-lima-bean-g5", "domain": "LIVING_THINGS", "topic": "patani lima bean legume plant", "grades": [4, 5, 6], "terms": ["patani", "lima bean", "legume", "gulay", "buto", "halaman", "binhi", "utanon", "liso", "tanom", "bean", "seed", "pod", "vine"], "fact": {"tl": "Ang patani ay isang gumagapang na halamang-gulay na may malalapad na buto sa loob ng mahahabang supot na kinakain bilang protina.", "en": "The patani (lima bean) is a climbing vegetable whose flat seeds grow inside long pods and are eaten as a protein-rich food.", "bis": "Ang patani usa ka nagakatay nga utanon nga adunay lapad nga mga liso sulod sa tag-as nga mga sopot nga ginakaon isip protina."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "patola-loofah-g5", "domain": "LIVING_THINGS", "topic": "patola loofah gourd vegetable", "grades": [4, 5, 6], "terms": ["patola", "loofah", "luffa", "gulay", "gumagapang", "baging", "halaman", "utanon", "ridge gourd", "sponge", "tanom", "vine"], "fact": {"tl": "Ang patola ay isang gumagapang na halamang-gulay na karaniwang niluluto kapag bata pa, at kapag tumanda ay nagiging hibla na ginagamit pampaligo.", "en": "The patola (loofah) is a climbing vine vegetable cooked while young, and when left to ripen its dried fibers become a natural scrubbing sponge.", "bis": "Ang patola usa ka nagakatay nga utanon nga ginaluto samtang bata pa, ug kon mahinog na ang gahi nga himbis niini mahimong panghugas o spongha."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "peanut-mani-plant-g5", "domain": "LIVING_THINGS", "topic": "peanut mani legume underground", "grades": [4, 5, 6], "terms": ["mani", "peanut", "groundnut", "legume", "buto", "halaman", "ilalim ng lupa", "ugat", "binhi", "liso", "tanom", "nuts", "pod"], "fact": {"tl": "Ang mani ay isang halamang-gulay na kakaiba dahil ang bulaklak nito ay bumababa at ang buto ay nahihinog sa ilalim ng lupa.", "en": "The peanut (mani) is a legume that is unusual because its flowers bend down and its seeds ripen underground inside pods.", "bis": "Ang mani usa ka tanom nga lahi kay ang bulak niini moyukbo paubos ug ang mga liso mahinog sa ilawom sa yuta sulod sa sopot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pechay-bok-choy-g5", "domain": "LIVING_THINGS", "topic": "pechay bok choy leafy vegetable", "grades": [3, 4, 5], "terms": ["pechay", "petsay", "bok choy", "dahon", "gulay", "leafy vegetable", "halaman", "utanon", "tanom", "greens", "leaves", "vitamin"], "fact": {"tl": "Ang pechay ay isang madaling tumubong halamang-gulay na ang luntiang dahon at puting tangkay ay kinakain at mayaman sa bitamina.", "en": "Pechay (bok choy) is a fast-growing leafy vegetable whose green leaves and white stalks are eaten and are rich in vitamins.", "bis": "Ang pechay usa ka paspas motubo nga utanon nga ang lunhaw nga dahon ug puti nga tangkay ginakaon ug dato sa bitamina."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pedigree-chart-g8", "domain": "LIVING_THINGS", "topic": "pedigree chart inheritance traits", "grades": [8, 9, 10], "terms": ["pedigree chart", "talaangkanan", "minana", "katangian", "pamana", "trait", "namana", "kabilin", "kaliwatan", "heredity", "family tree", "genes", "inheritance"], "fact": {"tl": "Ang pedigree chart ay isang dayagram na nagpapakita kung paano naipapasa ang isang katangian mula sa magulang patungo sa anak sa loob ng ilang henerasyon.", "en": "A pedigree chart is a diagram that shows how a trait is passed from parents to children across several generations of a family.", "bis": "Ang pedigree chart usa ka dayagram nga nagpakita kon giunsa pagsalin ang usa ka kinaiya gikan sa ginikanan ngadto sa anak sa pipila ka kaliwatan."}, "source": "AAAS Benchmarks 5B Heredity", "generator": "claude-workflow", "reviewed": false},
  {"id": "philippine-bulbul-g6", "domain": "LIVING_THINGS", "topic": "philippine bulbul endemic bird", "grades": [5, 6, 7], "terms": ["philippine bulbul", "bulbul", "ibon", "endemic", "katutubo", "langgam", "pispis", "gubat", "kahoy", "tanom", "forest bird", "fruit eater", "native"], "fact": {"tl": "Ang Philippine bulbul ay isang katutubong ibon na matatagpuan lamang sa Pilipinas at kumakain ng prutas at insekto sa mga gubat.", "en": "The Philippine bulbul is a native bird found only in the Philippines that feeds on fruits and insects in forests.", "bis": "Ang Philippine bulbul usa ka lumad nga langgam nga makita lamang sa Pilipinas ug nagakaon ug prutas ug insekto sa kalasangan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "philippine-cockatoo-katala-g6", "domain": "LIVING_THINGS", "topic": "philippine cockatoo katala endangered", "grades": [5, 6, 7], "terms": ["katala", "philippine cockatoo", "kalangay", "ibon", "loro", "parrot", "endangered", "nanganganib", "endemic", "langgam", "pispis", "namiligro", "white parrot", "protected"], "fact": {"tl": "Ang katala o Philippine cockatoo ay isang puting loro na endemiko sa Pilipinas at lubhang nanganganib na maubos dahil sa pagkawala ng tirahan at panghuhuli.", "en": "The katala (Philippine cockatoo) is a white parrot endemic to the Philippines and is critically endangered due to habitat loss and trapping.", "bis": "Ang katala o Philippine cockatoo usa ka puti nga loro nga endemiko sa Pilipinas ug grabe nga namiligro tungod sa pagkawala sa puy-anan ug pagpangdakop."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "philippine-flying-fox-fruit-bat-g6", "domain": "LIVING_THINGS", "topic": "philippine flying fox fruit bat", "grades": [5, 6, 7], "terms": ["flying fox", "fruit bat", "kabag", "paniki", "kabog", "bat", "mammal", "mamalya", "prutas", "gabi", "endemic", "kuribabog", "nocturnal", "pollinator"], "fact": {"tl": "Ang malaking flying fox ay isang paniki na kumakain ng prutas at tumutulong magpakalat ng buto at magpolinasyon ng mga halaman sa gubat.", "en": "The large flying fox is a fruit bat that eats fruit and helps spread seeds and pollinate forest plants at night.", "bis": "Ang dako nga flying fox usa ka kabog nga nagakaon ug prutas ug nagtabang sa pagkatag sa mga liso ug pagpolinasyon sa mga tanom sa lasang sa gabii."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "philippine-pangolin-g6", "domain": "LIVING_THINGS", "topic": "philippine pangolin scaly anteater", "grades": [5, 6, 7], "terms": ["philippine pangolin", "balintong", "pangolin", "scaly anteater", "kaliskis", "mammal", "mamalya", "langgam-kaon", "himbis", "endangered", "namiligro", "scales", "ant eater", "Palawan"], "fact": {"tl": "Ang Philippine pangolin o balintong ay isang mamalyang natatakpan ng matigas na kaliskis at gumugulong na parang bola kapag natatakot.", "en": "The Philippine pangolin (balintong) is a mammal covered in hard scales that rolls into a ball when frightened.", "bis": "Ang Philippine pangolin o balintong usa ka mamalya nga natabonan ug gahi nga himbis nga molingin nga morag bola kon mahadlok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "phototropism-plant-toward-light-g6", "domain": "LIVING_THINGS", "topic": "phototropism plant growth toward light", "grades": [5, 6, 7], "terms": ["phototropism", "pototropismo", "ilaw", "araw", "tumutubo papunta sa ilaw", "halaman", "tangkay", "kahayag", "light", "growth", "bending", "response"], "fact": {"tl": "Ang phototropism ay ang paghilig at pagtubo ng halaman patungo sa pinanggagalingan ng liwanag upang makakuha ng mas maraming sikat ng araw.", "en": "Phototropism is the way a plant bends and grows toward a light source so it can capture more sunlight.", "bis": "Ang phototropism mao ang pagpaingon ug pagtubo sa tanom paingon sa gigikanan sa kahayag aron makakuha ug mas daghang silaw sa adlaw."}, "source": "AAAS Benchmarks 5C; DepEd Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "pine-tree-benguet-g5", "domain": "LIVING_THINGS", "topic": "benguet pine tree cool highlands", "grades": [4, 5, 6], "terms": ["pine", "Benguet pine", "saleng", "pino", "kahoy", "puno", "gubat", "Baguio", "bundok", "highland", "kabukiran", "needle", "cone", "conifer"], "fact": {"tl": "Ang Benguet pine ay isang punong-kahoy na may parang karayom na dahon at matatagpuan sa malamig na kabundukan tulad ng Baguio.", "en": "The Benguet pine is a tree with needle-like leaves that grows in the cool highlands of the Philippines, such as around Baguio.", "bis": "Ang Benguet pine usa ka kahoy nga adunay morag dagom nga dahon ug nagtubo sa bugnaw nga kabukiran sa Pilipinas sama sa palibot sa Baguio."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pinggang-pinoy-balanced-meal-g4", "domain": "LIVING_THINGS", "topic": "pinggang pinoy balanced meal plate", "grades": [3, 4, 5], "terms": ["pinggang pinoy", "balanced meal", "balanseng pagkain", "plato", "go grow glow", "gulay", "prutas", "kanin", "ulam", "pagkaon", "nutrition", "food groups", "healthy plate"], "fact": {"tl": "Ang Pinggang Pinoy ay isang gabay na nagpapakita ng tamang dami ng kanin, ulam, gulay, at prutas sa isang balanseng kainan.", "en": "Pinggang Pinoy is a guide that shows the right amounts of rice, protein, vegetables, and fruit for one balanced meal.", "bis": "Ang Pinggang Pinoy usa ka giya nga nagpakita sa hustong gidaghanon sa kan-on, sud-an, utanon, ug prutas sa usa ka balanse nga pagkaon."}, "source": "DepEd Health/Science; FNRI Pinggang Pinoy", "generator": "claude-workflow", "reviewed": false},
  {"id": "pinggang-pinoy-portions-g5", "domain": "LIVING_THINGS", "topic": "pinggang pinoy food portions proportions", "grades": [4, 5, 6], "terms": ["pinggang pinoy", "portions", "bahagi", "proporsyon", "gulay", "kanin", "protina", "prutas", "tubig", "portion", "half plate vegetables", "nutrition guide"], "fact": {"tl": "Sa Pinggang Pinoy, kalahati ng plato ay dapat gulay at prutas, at ang kalahati pa ay hinahati sa kanin at ulam na may protina.", "en": "In Pinggang Pinoy, half the plate should be vegetables and fruit, while the other half is split between rice and protein-rich food.", "bis": "Sa Pinggang Pinoy, katunga sa plato kinahanglan utanon ug prutas, ug ang laing katunga gibahin sa kan-on ug sud-an nga adunay protina."}, "source": "FNRI Pinggang Pinoy guide", "generator": "claude-workflow", "reviewed": false},
  {"id": "pitfall-trap-soil-bugs-g6", "domain": "LIVING_THINGS", "topic": "pitfall trap soil insect survey", "grades": [5, 6, 7], "terms": ["pitfall trap", "bitag", "insekto sa lupa", "imbestigasyon", "siyensiya", "lit-ag", "mananap sa yuta", "ground beetle", "sampling", "soil animals", "method"], "fact": {"tl": "Ang pitfall trap ay isang baso o lalagyang ibinabaon nang pantay sa lupa para mahulog at mahuli ang mga maliliit na hayop na gumagapang sa ibabaw ng lupa.", "en": "A pitfall trap is a cup buried level with the ground so that small crawling soil animals fall in and can be counted by scientists.", "bis": "Ang pitfall trap usa ka tasa nga gilubong patas sa yuta aron mahulog ug madakpan ang gagmay nga nagakamang nga mga mananap sa yuta aron maihap."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "plankton-microscope-view-g7", "domain": "LIVING_THINGS", "topic": "plankton microscopic drifting organisms", "grades": [6, 7, 8], "terms": ["plankton", "mikroskopyo", "dagat", "maliit na nilalang", "lumulutang", "phytoplankton", "gagmay nga mananap sa tubig", "naglutaw", "ocean", "drifting", "microscopic", "food web"], "fact": {"tl": "Ang plankton ay napakaliliit na nilalang na lumulutang sa tubig at siyang pangunahing pagkain ng maraming isda at mga hayop sa dagat.", "en": "Plankton are tiny organisms that drift in the water and form the base food source for many fish and ocean animals.", "bis": "Ang plankton mao ang gagmay kaayo nga mga binuhat nga naglutaw sa tubig ug mao ang sukaranan nga pagkaon sa daghang isda ug mga mananap sa dagat."}, "source": "AAAS Benchmarks 5D ecosystems", "generator": "claude-workflow", "reviewed": false},
  {"id": "plant-maze-light-shoot-g6", "domain": "LIVING_THINGS", "topic": "plant growing through maze toward light", "grades": [5, 6, 7], "terms": ["plant maze", "halaman", "ilaw", "phototropism", "tumubo papunta sa ilaw", "labirinto", "usbong", "tanom", "kahayag", "experiment", "light", "shoot", "bending"], "fact": {"tl": "Kapag inilagay ang halaman sa isang kahon na may butas, tutubo ang usbong nito paliko-liko hanggang maabot ang liwanag na pumapasok.", "en": "When a plant is placed in a box with a hole, its shoot grows winding around obstacles until it reaches the light coming in.", "bis": "Kon ibutang ang tanom sa kahon nga adunay lungag, ang usbong niini motubo nga liko-liko hangtod makaabot sa kahayag nga mosulod."}, "source": "AAAS Benchmarks 5C; phototropism demo", "generator": "claude-workflow", "reviewed": false},
  {"id": "plant-needs-light-covered-leaf-g5", "domain": "LIVING_THINGS", "topic": "plants need light photosynthesis covered leaf", "grades": [4, 5, 6], "terms": ["dahon na natatakpan", "ilaw", "photosynthesis", "halaman kailangan ng liwanag", "eksperimento", "kahayag", "tanom", "almirol", "starch", "covered leaf", "light experiment", "sunlight"], "fact": {"tl": "Kapag tinakpan ang bahagi ng dahon para hindi tamaan ng araw, ang bahaging iyon ay hindi makakagawa ng pagkain, na nagpapatunay na kailangan ng halaman ang liwanag.", "en": "When part of a leaf is covered so sunlight cannot reach it, that part cannot make food, which proves plants need light to make their food.", "bis": "Kon tabonan ang bahin sa dahon aron dili maigo sa adlaw, kana nga bahin dili makahimo ug pagkaon, nga nagpamatuod nga ang tanom nanginahanglan ug kahayag."}, "source": "AAAS Benchmarks 5E photosynthesis; DepEd Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "playing-patintero-active-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "patintero active play exercise body", "grades": [3, 4, 5], "terms": ["patintero", "laro", "ehersisyo", "aktibo", "katawan", "dula", "lihok", "lawas", "physical activity", "exercise", "muscles", "heartbeat"], "fact": {"tl": "Ang paglalaro ng patintero ay isang aktibong ehersisyo na nagpapabilis ng tibok ng puso at nagpapalakas ng mga kalamnan ng katawan.", "en": "Playing patintero is active exercise that makes the heart beat faster and strengthens the body's muscles.", "bis": "Ang pagdula ug patintero usa ka aktibo nga ehersisyo nga nagpaspas sa pitik sa kasingkasing ug nagpalig-on sa mga unod sa lawas."}, "source": "DepEd Health/Science; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pomegranate-granada-g5", "domain": "LIVING_THINGS", "topic": "pomegranate granada fruit many seeds", "grades": [4, 5, 6], "terms": ["granada", "pomegranate", "prutas", "buto", "halaman", "puno", "fruit", "many seeds", "daghang liso", "bunga", "arils", "red fruit"], "fact": {"tl": "Ang granada o pomegranate ay isang prutas na may makapal na balat at puno ng daan-daang makatas at kulay-pulang buto na kinakain.", "en": "The pomegranate (granada) is a fruit with a thick rind that is packed with hundreds of juicy red seeds that are eaten.", "bis": "Ang granada o pomegranate usa ka prutas nga adunay baga nga panit ug puno sa gatosan ka tubigon ug pula nga mga liso nga ginakaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pomelo-suha-g5", "domain": "LIVING_THINGS", "topic": "pomelo suha large citrus fruit", "grades": [4, 5, 6], "terms": ["suha", "pomelo", "lukban", "citrus", "prutas", "makapal na balat", "fruit", "dako nga prutas", "bunga", "balat", "largest citrus", "thick rind", "vitamin C"], "fact": {"tl": "Ang suha o pomelo ay ang pinakamalaking prutas sa pamilya ng sitrus na may napakakapal na balat at mayaman sa bitamina C.", "en": "The pomelo (suha) is the largest fruit in the citrus family, with a very thick rind and flesh rich in vitamin C.", "bis": "Ang suha o pomelo mao ang pinakadako nga prutas sa pamilya sa sitrus, nga adunay baga kaayo nga panit ug unod nga dato sa bitamina C."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pond-water-microscope-scene-g7", "domain": "LIVING_THINGS", "topic": "pond water microorganisms microscope", "grades": [6, 7, 8], "terms": ["pond water", "tubig sa lawa", "mikroskopyo", "mikroorganismo", "maliit na nilalang", "tubig sa danaw", "gagmay nga binuhat", "microscope", "algae", "protozoa", "microorganisms", "tiny life"], "fact": {"tl": "Ang isang patak ng tubig sa lawa ay maaaring maglaman ng maraming napakaliliit na nilalang na makikita lamang sa pamamagitan ng mikroskopyo.", "en": "A single drop of pond water can contain many tiny living things that can only be seen through a microscope.", "bis": "Ang usa ka tulo sa tubig sa danaw mahimong adunay daghang gagmay kaayo nga mga binuhat nga makita lamang pinaagi sa mikroskopyo."}, "source": "AAAS Benchmarks 5A cells/microorganisms", "generator": "claude-workflow", "reviewed": false},
  {"id": "population-growth-curve-g9", "domain": "LIVING_THINGS", "topic": "population growth curve carrying capacity", "grades": [8, 9, 10], "terms": ["population growth", "paglaki ng populasyon", "kurba", "carrying capacity", "graph", "pagdaghan sa populasyon", "limitasyon", "S-curve", "logistic", "limits", "resources"], "fact": {"tl": "Mabilis na dumarami ang isang populasyon hanggang umabot ito sa hangganang kayang suportahan ng kapaligiran, kung saan tumitigil o pumapatag ang paglaki.", "en": "A population grows quickly until it reaches the limit the environment can support, where its growth slows and levels off.", "bis": "Ang usa ka populasyon paspas modaghan hangtod kini moabot sa kinutoban nga kaya sa palibot, diin ang pagtubo mohinay ug mopatag."}, "source": "AAAS Benchmarks 5D; NRC LS2", "generator": "claude-workflow", "reviewed": false},
  {"id": "posture-lifting-safely-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "safe lifting posture protect back", "grades": [5, 6, 7], "terms": ["posture", "pagbubuhat", "ligtas na pagbuhat", "likod", "tuhod", "lifting", "luhod sa pag-alsa", "back", "knees", "spine", "ergonomics"], "fact": {"tl": "Sa ligtas na pagbubuhat ng mabigat, dapat lumuhod at gamitin ang lakas ng mga binti sa halip na yumuko at ipain ang likod.", "en": "To lift a heavy object safely, you should bend your knees and use your leg muscles instead of bending and straining your back.", "bis": "Sa luwas nga pag-alsa ug bug-at, kinahanglan moluhod ug gamiton ang kusog sa mga paa imbis nga moyukbo ug ipaningkamot ang likod."}, "source": "encyclopedia-stable consensus; DepEd Health", "generator": "claude-workflow", "reviewed": false},
  {"id": "praying-mantis-sasamba-g5", "domain": "LIVING_THINGS", "topic": "praying mantis predator insect", "grades": [4, 5, 6], "terms": ["praying mantis", "sasamba", "insekto", "mandaragit", "predator", "insect", "manunukob", "biktima", "forelegs", "camouflage", "predatory insect"], "fact": {"tl": "Ang praying mantis o sasamba ay isang mandaragit na insekto na may matutulis na unahang paa na ginagamit para sunggaban at kainin ang ibang maliliit na insekto.", "en": "The praying mantis is a predatory insect with spiked front legs that it uses to snatch and eat other small insects.", "bis": "Ang praying mantis usa ka manunukob nga insekto nga adunay talinis nga unahang tiil nga gamiton aron dakpon ug kaonon ang ubang gagmay nga insekto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "proper-toothbrushing-steps-g3", "domain": "LIVING_THINGS", "topic": "proper toothbrushing dental hygiene", "grades": [3, 4, 5], "terms": ["toothbrushing", "pagsisipilyo", "ngipin", "kalinisan", "sipilyo", "toothpaste", "panglinis sa ngipon", "dental", "cavity", "plaque", "hygiene", "brushing"], "fact": {"tl": "Ang wastong pagsisipilyo nang dalawang beses sa isang araw ay nag-aalis ng tira-tirang pagkain at bakterya na nagdudulot ng pagkasira ng ngipin.", "en": "Brushing the teeth properly twice a day removes leftover food and bacteria that cause tooth decay.", "bis": "Ang husto nga pagsipilyo kaduha sa usa ka adlaw nagatangtang sa nahabilin nga pagkaon ug bakterya nga maoy hinungdan sa pagkadunot sa ngipon."}, "source": "encyclopedia-stable consensus; DepEd Health", "generator": "claude-workflow", "reviewed": false},
  {"id": "protective-gear-safety-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "protective gear safety equipment", "grades": [3, 4, 5], "terms": ["protective gear", "kagamitang pangkaligtasan", "helmet", "goggles", "kaligtasan", "kasangkapan sa kaluwasan", "panalipod", "safety", "pads", "injury prevention"], "fact": {"tl": "Ang mga kagamitang pangkaligtasan tulad ng helmet at goggles ay nakapagpoprotekta sa katawan laban sa pinsala kapag tayo ay naglalaro o nagtatrabaho.", "en": "Protective gear such as helmets and goggles shields the body from injury while we play or work.", "bis": "Ang mga kagamitan sa kaluwasan sama sa helmet ug goggles nagapanalipod sa lawas batok sa kadaot samtang kita magdula o magtrabaho."}, "source": "encyclopedia-stable consensus; DepEd Health", "generator": "claude-workflow", "reviewed": false},
  {"id": "protein-food-sources-g5", "domain": "LIVING_THINGS", "topic": "protein food sources body building", "grades": [4, 5, 6], "terms": ["protina", "protein", "isda", "itlog", "karne", "munggo", "grow food", "sud-an", "manok", "beans", "muscle", "nutrition"], "fact": {"tl": "Ang protina mula sa pagkain tulad ng isda, itlog, karne, at munggo ay tumutulong magpalaki at mag-ayos ng mga bahagi ng katawan.", "en": "Protein from foods like fish, eggs, meat, and beans helps build and repair the body's parts.", "bis": "Ang protina gikan sa pagkaon sama sa isda, itlog, karne, ug munggo nagatabang sa pagpadako ug pag-ayo sa mga bahin sa lawas."}, "source": "DepEd Science/Health; FNRI", "generator": "claude-workflow", "reviewed": false},
  {"id": "protozoa-pond-water-g7", "domain": "LIVING_THINGS", "topic": "protozoa single-celled organisms pond", "grades": [6, 7, 8], "terms": ["protozoa", "protozoo", "isahang selula", "mikroorganismo", "tubig sa lawa", "amoeba", "paramecium", "usa ka selula", "gagmay nga binuhat", "single-celled", "microorganism", "cilia", "microscope"], "fact": {"tl": "Ang protozoa ay mga nilalang na isahang selula lamang na lumalangoy sa tubig at gumagalaw para humanap at sumipsip ng pagkain.", "en": "Protozoa are single-celled organisms that swim in water and move to find and take in their food.", "bis": "Ang protozoa mao ang mga binuhat nga usa ra ka selula nga naglangoy sa tubig ug naglihok aron mangita ug mosuyop sa ilang pagkaon."}, "source": "AAAS Benchmarks 5A cells; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "puffball-mushroom-g5", "domain": "LIVING_THINGS", "topic": "puffball mushroom spores", "grades": [4, 5, 6], "terms": ["puffball", "kabute", "uhong", "mushroom", "spores", "spora", "fungus", "fungi", "pumuputok", "spore cloud", "uhong nga mubuto"], "fact": {"tl": "Ang puffball ay isang bilog na kabute na walang tangkay, at kapag napindot o naulanan ito ay pumuputok at naglalabas ng ulap ng maliliit na spora upang dumami.", "en": "A puffball is a round, stalkless mushroom that bursts when pressed or hit by rain, releasing a cloud of tiny spores that grow into new fungi.", "bis": "Ang puffball usa ka lingin nga uhong nga walay punoan, ug kon mapislit o maulanan kini mubuto ug mubuga og panganod sa gagmay nga spora aron modaghan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pulmonary-systemic-circuits-g7", "domain": "LIVING_THINGS", "topic": "pulmonary and systemic circulation", "grades": [7, 8, 9], "terms": ["pulmonary circulation", "systemic circulation", "sirkulasyon", "dugo", "puso", "baga", "lungs", "heart", "oxygen", "oksiheno", "double circulation", "blood circuit", "kasingkasing", "duha ka sirkito"], "fact": {"tl": "Sa katawan ng tao, ang pulmonary circuit ay nagdadala ng dugo mula sa puso papuntang baga upang kumuha ng oxygen, habang ang systemic circuit naman ang nagdadala ng dugong puno ng oxygen sa buong katawan.", "en": "In the human body, the pulmonary circuit carries blood from the heart to the lungs to pick up oxygen, while the systemic circuit delivers oxygen-rich blood to the rest of the body.", "bis": "Sa lawas sa tawo, ang pulmonary circuit magdala sa dugo gikan sa kasingkasing paingon sa baga aron mokuha og oxygen, samtang ang systemic circuit magdala sa dugo nga puno og oxygen ngadto sa tibuok lawas."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rafflesia-bloom-g6", "domain": "LIVING_THINGS", "topic": "Rafflesia largest flower", "grades": [5, 6, 7], "terms": ["rafflesia", "bunga", "pinakamalaking bulaklak", "bulaklak", "bulak", "largest flower", "parasite", "parasitiko", "Philippine flower", "mabaho", "corpse flower", "labing dako nga bulak", "langaw"], "fact": {"tl": "Ang Rafflesia ay isang halamang parasito na may isa sa pinakamalalaking bulaklak sa mundo, at naglalabas ito ng mabahong amoy tulad ng bulok na karne upang makaakit ng mga langaw na magpapalipat ng pollen.", "en": "Rafflesia is a parasitic plant with one of the largest flowers in the world, and it gives off a foul smell like rotting meat to attract flies that carry its pollen.", "bis": "Ang Rafflesia usa ka parasitikong tanom nga adunay usa sa pinakadagkong bulak sa kalibotan, ug mubuga kini og baho nga sama sa nadunot nga karne aron makadani og mga langaw nga magdala sa pollen niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rambutan-fruit-g4", "domain": "LIVING_THINGS", "topic": "rambutan fruit", "grades": [3, 4, 5], "terms": ["rambutan", "prutas", "bunga", "hairy fruit", "balahibo", "tropical fruit", "buhok-buhok", "rambutan prutas", "balhiboon nga prutas", "fruit"], "fact": {"tl": "Ang rambutan ay isang matamis na tropikal na prutas na may pulang balat na puno ng malalambot na buhok-buhok, at ang puti nitong laman ang kinakain natin.", "en": "Rambutan is a sweet tropical fruit with a red skin covered in soft hairy spikes, and we eat the juicy white flesh inside.", "bis": "Ang rambutan usa ka tam-is nga tropikal nga prutas nga adunay pula nga panit nga puno og humok nga balahibo, ug ang puti nga unod sa sulod mao ang atong kan-on."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rattan-vine-g6", "domain": "LIVING_THINGS", "topic": "rattan climbing palm", "grades": [5, 6, 7], "terms": ["rattan", "yantok", "uway", "climbing palm", "baging", "vine", "furniture", "muwebles", "tropical forest", "gumagapang", "rattan yantok", "tunok", "musaka nga palma"], "fact": {"tl": "Ang rattan o yantok ay isang uri ng palmang gumagapang na umaakyat sa ibang puno gamit ang matutulis na tinik, at ang matibay na tangkay nito ay ginagamit sa paggawa ng muwebles at basket.", "en": "Rattan, or yantok, is a climbing palm that scrambles up other trees using sharp thorns, and its strong stems are used to make furniture and baskets.", "bis": "Ang rattan o uway usa ka klase sa palma nga musaka sa ubang kahoy pinaagi sa hait nga tunok, ug ang lig-on nga punoan niini gamiton sa paghimo og muwebles ug bukag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rattan-yantok-g4", "domain": "MATTER", "topic": "rattan as a useful material", "grades": [3, 4, 5], "terms": ["rattan", "yantok", "uway", "material", "muwebles", "furniture", "basket", "bukag", "flexible", "malambot", "natural material", "rattan yantok", "lig-on nga materyales"], "fact": {"tl": "Ang yantok ay isang likas at matibay ngunit nababaluktot na materyal mula sa halaman, kaya ito ay perpektong gamitin sa paghabi ng silya, basket, at iba pang muwebles.", "en": "Yantok (rattan) is a natural, strong yet bendable plant material, which makes it perfect for weaving chairs, baskets, and other furniture.", "bis": "Ang uway usa ka natural ug lig-on apan mabawog nga materyales gikan sa tanom, busa kini hingpit gamiton sa paghabol og lingkoranan, bukag, ug ubang muwebles."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "reading-a-thermometer-g4", "domain": "MATTER", "topic": "reading a thermometer", "grades": [3, 4, 5], "terms": ["thermometer", "termometro", "temperatura", "temperature", "init", "lamig", "degrees", "Celsius", "pagbasa", "init ug bugnaw", "pagsukod sa kainit"], "fact": {"tl": "Ang termometro ay sumusukat ng temperatura o init ng isang bagay, at binabasa natin ang antas sa pamamagitan ng pagtingin kung saan umaabot ang likido o numero, na karaniwang nasa Celsius.", "en": "A thermometer measures the temperature, or how hot or cold something is, and we read it by seeing where the liquid or number reaches, usually in degrees Celsius.", "bis": "Ang termometro mosukod sa temperatura o kainit sa usa ka butang, ug atong basahon kini pinaagi sa pagtan-aw asa moabot ang likido o numero, kasagaran sa Celsius."}, "source": "DepEd MATATAG Science; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "reduce-soft-drinks-g5", "domain": "LIVING_THINGS", "topic": "limiting sugary drinks for health", "grades": [4, 5, 6], "terms": ["soft drinks", "softdrinks", "sugar", "asukal", "ngipin", "teeth", "healthy", "malusog", "tubig", "water", "inumin", "tam-is nga ilimnon", "panglawas", "himsog"], "fact": {"tl": "Ang mga softdrinks ay may napakaraming asukal na maaaring magdulot ng sira sa ngipin at sobrang timbang, kaya mas mabuting uminom ng tubig o gatas para sa malusog na katawan.", "en": "Soft drinks contain a lot of sugar that can cause tooth decay and excess weight, so it is healthier to drink water or milk instead.", "bis": "Ang softdrinks adunay daghan kaayong asukal nga makahatag og guba nga ngipon ug sobra nga timbang, busa mas maayo nga moinom og tubig o gatas para sa himsog nga lawas."}, "source": "DepEd MATATAG Science; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "reflex-arc-g8", "domain": "LIVING_THINGS", "topic": "reflex arc nervous response", "grades": [7, 8, 9], "terms": ["reflex", "reflex arc", "nerbiyos", "nerve", "spinal cord", "gulugod", "automatic", "kusang-loob", "stimulus", "mabilis na tugon", "kaunoran", "init"], "fact": {"tl": "Ang reflex arc ay ang mabilis at kusang daan ng signal mula sa sensor patungo sa gulugod at pabalik sa kalamnan, kaya umiilag tayo agad nang hindi pa nag-iisip kapag may nakahawak tayong mainit.", "en": "A reflex arc is the fast, automatic path a signal takes from a sensor to the spinal cord and back to a muscle, which is why we pull away instantly before even thinking when we touch something hot.", "bis": "Ang reflex arc mao ang paspas ug awtomatikong agianan sa signal gikan sa sensor paingon sa gulugod ug balik sa kaunoran, mao nga mulayo dayon ta nga wala pa makahunahuna kon makahikap ta og init."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "remora-shark-symbiosis-g6", "domain": "LIVING_THINGS", "topic": "remora and shark symbiosis", "grades": [5, 6, 7], "terms": ["remora", "shark", "pating", "isda", "fish", "symbiosis", "simbiyosis", "dumikit", "hitchhike", "commensalism", "iho", "mutapot", "tira-tira"], "fact": {"tl": "Ang remora ay isang isda na may suction sa ulo na ginagamit nito para dumikit sa pating, at sumasakay ito nang libre habang kumakain ng tira-tirang pagkain ng pating.", "en": "The remora is a fish with a sucker on its head that it uses to attach to a shark, getting a free ride while feeding on the shark's leftover scraps.", "bis": "Ang remora usa ka isda nga adunay suyop sa ulo nga gamiton niini aron motapot sa iho, ug magsakay kini nga libre samtang mokaon sa salin nga pagkaon sa iho."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rib-cage-diagram-g6", "domain": "LIVING_THINGS", "topic": "rib cage protects organs", "grades": [5, 6, 7], "terms": ["rib cage", "tadyang", "buto", "ribs", "bones", "puso", "baga", "heart", "lungs", "skeleton", "kalansay", "proteksiyon", "gusok", "panalipod sa organo"], "fact": {"tl": "Ang rib cage o hawla ng tadyang ay binubuo ng mga buto ng tadyang na nakakurba sa dibdib, at pinoprotektahan nito ang puso at baga sa loob.", "en": "The rib cage is made of curved rib bones around the chest, and it protects the heart and lungs inside.", "bis": "Ang rib cage o hawla sa gusok hinimo sa mga bukog sa gusok nga nagkurba palibot sa dughan, ug kini manalipod sa kasingkasing ug baga sa sulod."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rice-field-food-chain-g5", "domain": "LIVING_THINGS", "topic": "rice field food chain", "grades": [4, 5, 6], "terms": ["food chain", "kadena ng pagkain", "rice field", "palayan", "palay", "tipaklong", "grasshopper", "palaka", "frog", "ahas", "snake", "kadena sa pagkaon", "apan-apan", "bitin"], "fact": {"tl": "Sa isang kadena ng pagkain sa palayan, ang palay ay kinakain ng tipaklong, ang tipaklong ay kinakain ng palaka, at ang palaka naman ay kinakain ng ahas.", "en": "In a rice field food chain, the rice plant is eaten by a grasshopper, the grasshopper is eaten by a frog, and the frog is eaten by a snake.", "bis": "Sa usa ka kadena sa pagkaon sa palayan, ang humay kan-on sa apan-apan, ang apan-apan kan-on sa baki, ug ang baki kan-on sa bitin."}, "source": "NRC LS2.B; DepEd MATATAG Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "rice-growing-stages-paddy-g5", "domain": "LIVING_THINGS", "topic": "stages of rice growing", "grades": [4, 5, 6], "terms": ["rice", "palay", "humay", "paddy", "palayan", "seedling", "punla", "transplant", "harvest", "ani", "stages", "yugto", "pagtubo sa humay", "ang-ang"], "fact": {"tl": "Ang palay ay tumutubo sa ilang yugto: una itong itinatanim bilang punla, pagkatapos ay inililipat sa pinabahang palayan, at sa wakas ay umaani kapag naging ginto na ang mga uhay.", "en": "Rice grows in stages: first it is planted as seedlings, then transplanted into a flooded paddy, and finally harvested when the grain-heads turn golden.", "bis": "Ang humay motubo sa mga ang-ang: una kini itanom isip semilya, dayon ibalhin ngadto sa gibahaan nga palayan, ug sa kataposan anihon kon mahimong bulawan na ang mga uhay."}, "source": "DepEd MATATAG Science; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rice-method-sprain-care-g6", "domain": "LIVING_THINGS", "topic": "RICE first aid for sprains", "grades": [5, 6, 7], "terms": ["RICE method", "sprain", "pilay", "lubag", "first aid", "lunas", "rest", "ice", "yelo", "compression", "elevation", "unang lunas", "pag-atiman sa pilay", "hubag"], "fact": {"tl": "Ang RICE method ay isang unang lunas sa pilay na nangangahulugang Rest (pahinga), Ice (yelo), Compression (pagbenda), at Elevation (pagtaas ng sugatang bahagi) upang mabawasan ang pamamaga at sakit.", "en": "The RICE method is a first aid for sprains that stands for Rest, Ice, Compression, and Elevation, which helps reduce swelling and pain in an injured part.", "bis": "Ang RICE method usa ka unang hinabang sa pilay nga nagkahulogan og Rest (pahulay), Ice (yelo), Compression (pagbendahe), ug Elevation (pagpataas sa samad nga bahin) aron makunhoran ang panghubag ug kasakit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "river-goby-biya-g6", "domain": "LIVING_THINGS", "topic": "river goby (biya) fish", "grades": [5, 6, 7], "terms": ["goby", "biya", "isda", "fish", "river", "ilog", "suba", "freshwater", "tabang", "small fish", "isda sa suba", "kapyot sa bato", "palikpik"], "fact": {"tl": "Ang biya ay isang maliit na isdang-ilog na may magkadikit na palikpik sa tiyan na parang suction cup, kaya kaya nitong kumapit sa mga bato kahit sa mabilis na agos ng tubig.", "en": "The biya, or goby, is a small river fish whose belly fins are fused into a suction-cup shape, letting it cling to rocks even in fast-flowing water.", "bis": "Ang biya usa ka gamay nga isda sa suba nga ang mga palikpik sa tiyan niini gisumpay nga sama sa suction cup, mao nga makakapyot kini sa mga bato bisan sa paspas nga agos sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "role-carnivore-g4", "domain": "LIVING_THINGS", "topic": "carnivore meat eater", "grades": [3, 4, 5], "terms": ["carnivore", "karnibora", "kumakain ng karne", "meat eater", "hayop", "animal", "predator", "mandaragit", "leon", "buwaya", "mokaon og karne", "mananap", "buaya"], "fact": {"tl": "Ang carnivore o karnibora ay isang hayop na karne ng ibang hayop ang kinakain, tulad ng leon, pusa, at buwaya.", "en": "A carnivore is an animal that eats the meat of other animals, such as a lion, a cat, or a crocodile.", "bis": "Ang carnivore o karnibora usa ka mananap nga mokaon sa karne sa ubang mananap, sama sa leon, iring, ug buaya."}, "source": "NRC LS2.B; DepEd MATATAG Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "role-decomposer-g5", "domain": "LIVING_THINGS", "topic": "decomposers recyclers", "grades": [4, 5, 6], "terms": ["decomposer", "dekompositor", "kabute", "uhong", "bakterya", "bacteria", "fungi", "nabubulok", "nutrients", "sustansya", "tigbungkag", "yuta", "lupa"], "fact": {"tl": "Ang mga decomposer tulad ng kabute at bakterya ay nagbubulok ng mga patay na halaman at hayop, at ibinabalik nito ang sustansya sa lupa para muling magamit ng mga buhay na halaman.", "en": "Decomposers like fungi and bacteria break down dead plants and animals, returning nutrients to the soil for living plants to use again.", "bis": "Ang mga decomposer sama sa uhong ug bakterya magbungkag sa patay nga tanom ug mananap, ug ibalik niini ang sustansya ngadto sa yuta aron magamit pag-usab sa buhing tanom."}, "source": "NRC LS2.B; DepEd MATATAG Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "role-herbivore-g4", "domain": "LIVING_THINGS", "topic": "herbivore plant eater", "grades": [3, 4, 5], "terms": ["herbivore", "erbibora", "kumakain ng halaman", "plant eater", "damo", "kalabaw", "kambing", "baka", "cow", "carabao", "mokaon og tanom", "sagbot", "kabaw"], "fact": {"tl": "Ang herbivore o erbibora ay isang hayop na mga halaman lamang ang kinakain, tulad ng kalabaw, kambing, at baka na kumakain ng damo.", "en": "A herbivore is an animal that eats only plants, such as a carabao, a goat, or a cow that feeds on grass.", "bis": "Ang herbivore o erbibora usa ka mananap nga mokaon lang og mga tanom, sama sa kabaw, kanding, ug baka nga mokaon og sagbot."}, "source": "NRC LS2.B; DepEd MATATAG Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "role-omnivore-g4", "domain": "LIVING_THINGS", "topic": "omnivore eats plants and animals", "grades": [3, 4, 5], "terms": ["omnivore", "omnibora", "halaman at hayop", "plants and animals", "tao", "baboy", "manok", "pig", "chicken", "human", "mokaon og tanom ug mananap", "tawo"], "fact": {"tl": "Ang omnivore o omnibora ay isang hayop na parehong kumakain ng halaman at hayop, tulad ng tao, baboy, at manok.", "en": "An omnivore is an animal that eats both plants and animals, such as humans, pigs, and chickens.", "bis": "Ang omnivore o omnibora usa ka mananap nga mokaon sa tanom ug mananap, sama sa tawo, baboy, ug manok."}, "source": "NRC LS2.B; DepEd MATATAG Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "rosal-gardenia-g5", "domain": "LIVING_THINGS", "topic": "rosal (gardenia) flower", "grades": [4, 5, 6], "terms": ["rosal", "gardenia", "bulaklak", "bulak", "flower", "halaman", "mabango", "fragrant", "puti", "white flower", "mahumot nga bulak", "ornamental", "tanom"], "fact": {"tl": "Ang rosal o gardenia ay isang halamang-palamuti na may makapal at puting bulaklak na kilala sa napakabango nitong amoy.", "en": "The rosal, or gardenia, is an ornamental plant with thick, creamy-white flowers known for their very sweet fragrance.", "bis": "Ang rosal o gardenia usa ka tanom nga pangdayan-dayan nga adunay baga ug puti nga bulak nga ilado sa hilabihang humot niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rose-rosas-g4", "domain": "LIVING_THINGS", "topic": "rose flower with thorns", "grades": [3, 4, 5], "terms": ["rose", "rosas", "bulaklak", "bulak", "flower", "tinik", "thorn", "halaman", "mabango", "petals", "talulot", "tunokon nga bulak", "tunok", "petalo"], "fact": {"tl": "Ang rosas ay isang mabangong bulaklak na may maraming malalambot na talulot, at ang tangkay nito ay may matutulis na tinik na nagsisilbing proteksiyon.", "en": "The rose is a fragrant flower with many soft petals, and its stem has sharp thorns that serve as protection.", "bis": "Ang rosas usa ka humot nga bulak nga adunay daghang humok nga petalo, ug ang punoan niini adunay hait nga tunok nga magsilbing panalipod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rosemary-herb-g5", "domain": "LIVING_THINGS", "topic": "rosemary herb", "grades": [4, 5, 6], "terms": ["rosemary", "herb", "halamang gamot", "pampalasa", "spice", "mabango", "fragrant", "leaves", "dahon", "needle-like", "panakot", "humot nga tanom", "dagom"], "fact": {"tl": "Ang rosemary ay isang mabangong halamang-gamot na may manipis at parang karayom na mga dahon, at ginagamit ito bilang pampalasa sa pagluluto.", "en": "Rosemary is a fragrant herb with thin, needle-like leaves, and it is used as a seasoning in cooking.", "bis": "Ang rosemary usa ka humot nga tanom-tambal nga adunay nipis ug sama-sa-dagom nga mga dahon, ug gamiton kini isip panakot sa pagluto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rotifer-microbe-g7", "domain": "LIVING_THINGS", "topic": "rotifer microscopic animal", "grades": [6, 7, 8], "terms": ["rotifer", "microbe", "mikrobyo", "microscopic", "napakaliit", "tubig", "water", "wheel animal", "cilia", "plankton", "gamay kaayo nga hayop", "tab-ang nga tubig", "mikroskopyo"], "fact": {"tl": "Ang rotifer ay isang napakaliit na hayop na matatagpuan sa tubig-tabang at nakikita lamang sa mikroskopyo, at gumagamit ito ng umiikot na mga balahibo (cilia) sa ulo para humila ng tubig at pagkain papunta sa bibig nito.", "en": "A rotifer is a tiny animal found in freshwater that can only be seen under a microscope, and it uses spinning hair-like cilia on its head to sweep water and food into its mouth.", "bis": "Ang rotifer usa ka gamay kaayo nga hayop nga makit-an sa tab-ang nga tubig ug makita lang pinaagi sa mikroskopyo, ug mogamit kini og nagatuyok nga gagmay nga balahibo (cilia) sa ulo aron mosuyod sa tubig ug pagkaon ngadto sa baba niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rufous-hornbill-kalaw-g6", "domain": "LIVING_THINGS", "topic": "Philippine rufous hornbill (kalaw)", "grades": [5, 6, 7], "terms": ["rufous hornbill", "kalaw", "ibon", "bird", "Philippine bird", "endemic", "endemiko", "casque", "tuka", "beak", "kagubatan", "forest", "langgam sa Pilipinas", "orasan sa kalasangan"], "fact": {"tl": "Ang kalaw o Philippine rufous hornbill ay isang malaking ibon na tangi sa Pilipinas, na may malaking tuka na may parang sungay sa itaas, at tinatawag itong 'orasan ng kagubatan' dahil may malakas itong tunog na maririnig sa malayo.", "en": "The kalaw, or Philippine rufous hornbill, is a large bird found only in the Philippines, with a big beak topped by a horn-like casque, and it is called the 'clock of the mountains' because of its loud, far-carrying call.", "bis": "Ang kalaw o Philippine rufous hornbill usa ka dako nga langgam nga makita lang sa Pilipinas, nga adunay dako nga sungo nga adunay sama-sa-sungay sa ibabaw, ug gitawag kini nga 'orasan sa kalasangan' tungod sa kusog nga singgit niini nga madungog sa layo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sago-palm-g6", "domain": "LIVING_THINGS", "topic": "sago palm starch food", "grades": [5, 6, 7], "terms": ["sago", "sago palm", "lumbia", "palma", "palm", "almirol", "starch", "pagkain", "food", "tangkay", "pith", "starch sa palma", "almidon", "carbohydrate"], "fact": {"tl": "Ang sago palm ay isang puno ng palma na ang loob ng tangkay nito ay puno ng almirol o starch, at mula rito ginagawa ang sago na maliliit na bilog na kinakain sa mga panghimagas.", "en": "The sago palm is a palm tree whose trunk pith is full of starch, and from it people make sago, the little chewy pearls eaten in desserts.", "bis": "Ang sago palm usa ka palma nga ang sulod sa punoan niini puno og almidon o starch, ug gikan niini ginahimo ang sago nga gagmay nga lingin nga kan-on sa mga panam-is."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "saliva-mouth-digestion-start-g5", "domain": "LIVING_THINGS", "topic": "saliva starts digestion in the mouth", "grades": [4, 5, 6], "terms": ["laway", "laway sa bibig", "panimula ng pagtunaw", "saliva", "spit", "mouth", "digestion", "ngata", "laway sa baba", "sugod sa paghilis", "enzyme", "starch", "almirol"], "fact": {"tl": "Ang laway sa ating bibig ang nagsisimula ng pagtunaw ng pagkain sa pamamagitan ng pagbabad at paghahati nito habang ngumunguya tayo.", "en": "Saliva in our mouth begins digestion by wetting food and starting to break it down as we chew.", "bis": "Ang laway sa atong baba mao ang magsugod sa paghilis sa pagkaon pinaagi sa pagbasa ug pagbungkag niini samtang mag-usap kita."}, "source": "NRC LS1.A; DepEd G5 human body; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "salt-oil-moderation-g6", "domain": "MATTER", "topic": "eat salt and oil only in moderation", "grades": [5, 6, 7], "terms": ["asin", "langis", "katamtaman", "sobrang asin", "sobrang langis", "salt", "oil", "moderation", "tamang dami", "asgad", "lana", "kasarangan", "health", "alat"], "fact": {"tl": "Kailangan nating kainin ang asin at langis nang katamtaman lamang, dahil ang sobra ay maaaring makasama sa puso at presyon ng dugo.", "en": "We should eat salt and oil only in moderation, because too much can harm the heart and raise blood pressure.", "bis": "Kinahanglan natong kaonon ang asin ug lana sa kasarangan lamang, kay ang sobra makadaot sa kasingkasing ug makapataas sa presyon sa dugo."}, "source": "DepEd G6 nutrition; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "saluyot-jute-g5", "domain": "LIVING_THINGS", "topic": "saluyot (jute) leafy vegetable", "grades": [3, 4, 5], "terms": ["saluyot", "jute", "gulay na dahon", "malagkit na gulay", "Corchorus", "leafy vegetable", "slippery leaves", "nutritious", "dahong gulay", "gulay", "slimy", "bitamina", "iron"], "fact": {"tl": "Ang saluyot ay isang malusog na gulay na dahon na nagiging malagkit kapag niluluto at mayaman sa bitamina at iron.", "en": "Saluyot (jute) is a healthy leafy vegetable whose leaves turn slippery when cooked and are rich in vitamins and iron.", "bis": "Ang saluyot kay usa ka himsog nga utan nga dahon nga mahimong danlog kon lutoon ug daghan og bitamina ug iron."}, "source": "encyclopedia-stable consensus; DepEd G5 nutrition", "generator": "claude-workflow", "reviewed": false},
  {"id": "sambong-herb-g6", "domain": "LIVING_THINGS", "topic": "sambong medicinal herb", "grades": [5, 6, 7], "terms": ["sambong", "Blumea balsamifera", "halamang gamot", "medicinal herb", "diuretic", "panggamot", "herbal", "tanom nga tambal", "gamot sa bato", "ihi", "kidney stone", "pampaihi"], "fact": {"tl": "Ang sambong ay isang halamang gamot sa Pilipinas na ginagamit bilang diuretic upang tumulong sa pag-ihi at sa mga problema sa bato.", "en": "Sambong is a Philippine medicinal herb used as a diuretic to help with urination and kidney problems.", "bis": "Ang sambong kay usa ka tanom nga tambal sa Pilipinas nga gamiton isip diuretic aron motabang sa pagpangihi ug sa mga problema sa kidney."}, "source": "DOH/PITAHC approved herbal medicine; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sampalok-tamarind-g5", "domain": "LIVING_THINGS", "topic": "sampalok (tamarind) sour fruit tree", "grades": [3, 4, 5], "terms": ["sampalok", "tamarind", "Tamarindus indica", "maasim na prutas", "punong sampalok", "sour fruit", "pulp", "pampaasim", "sambag", "aslom", "prutas", "sinigang", "seed pod"], "fact": {"tl": "Ang sampalok ay isang malaking puno na may maasim na bunga na ginagamit pampaasim sa sinigang at ibang putahe.", "en": "Sampalok (tamarind) is a large tree with sour pod fruit that is used to make sinigang and other dishes sour.", "bis": "Ang sampalok (sambag) kay usa ka dako nga kahoy nga adunay aslom nga bunga nga gigamit aron pa-aslomon ang sinigang ug uban pang pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sandy-beach-zonation-g6", "domain": "LIVING_THINGS", "topic": "sandy beach has zones from water to dry land", "grades": [5, 6, 7, 8], "terms": ["mabuhanging dalampasigan", "sona ng dalampasigan", "alon", "tubig", "tuyong buhangin", "sandy beach", "zonation", "intertidal", "tides", "baybayon", "balod", "balas", "crab", "talaba", "tide line", "habitat"], "fact": {"tl": "Sa mabuhanging dalampasigan, may magkakaibang sona mula sa basang tubig hanggang sa tuyong buhangin, at iba't ibang hayop ang nakatira sa bawat sona ayon sa taas at baba ng tubig.", "en": "A sandy beach has different zones from the wet water's edge to the dry sand, and different animals live in each zone depending on the rise and fall of the tides.", "bis": "Sa balason nga baybayon, adunay lain-laing sona gikan sa basa nga ngilit sa tubig hangtod sa uga nga balas, ug lain-laing mananap ang nagpuyo sa matag sona depende sa taas ug hubas sa dagat."}, "source": "AAAS Benchmarks 5D habitats; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "santan-flower-g4", "domain": "LIVING_THINGS", "topic": "santan flower clusters attract pollinators", "grades": [3, 4, 5], "terms": ["santan", "Ixora", "bulaklak", "kumpol-kumpol na bulaklak", "nektar", "flower", "cluster", "pollinator", "paru-paro", "bubuyog", "bulak", "tangkay", "tabog", "nectar", "ornamental"], "fact": {"tl": "Ang santan ay namumulaklak nang kumpol-kumpol at ang matamis nitong nektar ay umaakit sa mga paru-paro at bubuyog na tumutulong sa pollination.", "en": "Santan blooms in dense flower clusters whose sweet nectar attracts butterflies and bees that help with pollination.", "bis": "Ang santan namulak og pinungpong ug ang tam-is nga nektar niini magdani sa mga alibangbang ug putyukan nga motabang sa pollination."}, "source": "NRC LS2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "santol-fruit-g5", "domain": "LIVING_THINGS", "topic": "santol (cotton fruit) tropical tree", "grades": [3, 4, 5], "terms": ["santol", "cotton fruit", "Sandoricum koetjape", "prutas", "maasim-tamis na prutas", "sour-sweet fruit", "seeds", "balat", "santol nga prutas", "aslom", "tam-is", "liso", "tropical fruit", "rind"], "fact": {"tl": "Ang santol ay isang tropikal na prutas na may makapal na balat at maasim-tamis na laman na nakapalibot sa malalaking buto.", "en": "Santol is a tropical fruit with a thick rind and a sour-sweet flesh that surrounds large seeds.", "bis": "Ang santol kay usa ka tropikal nga prutas nga adunay baga nga panit ug aslom-tam-is nga unod nga naglibot sa dagkong liso."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sargassum-seaweed-g6", "domain": "LIVING_THINGS", "topic": "sargassum is a floating brown seaweed", "grades": [5, 6, 7, 8], "terms": ["sargassum", "damong-dagat", "lumolutang na algae", "kayumangging algae", "seaweed", "brown algae", "floating", "gas bladders", "lusay", "algae", "lutaw", "dagat", "photosynthesis", "habitat for fish"], "fact": {"tl": "Ang sargassum ay isang kayumangging damong-dagat na lumulutang dahil sa maliliit nitong tila-bolang puno ng hangin, at nagbibigay ito ng tirahan sa maliliit na isda.", "en": "Sargassum is a brown seaweed that floats because of tiny gas-filled bladders, and it provides shelter for small sea animals.", "bis": "Ang sargassum kay usa ka kapehon nga lusay nga molutaw tungod sa gagmay nga sudlanan og gas, ug naghatag kini og puy-anan sa gagmay nga isda."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sayote-chayote-g5", "domain": "LIVING_THINGS", "topic": "sayote (chayote) climbing vegetable", "grades": [3, 4, 5], "terms": ["sayote", "chayote", "Sechium edule", "gulay", "baging na gulay", "climbing vine", "pear-shaped", "gourd", "baging", "gulay", "upo", "wrinkled", "cool climate", "utanon"], "fact": {"tl": "Ang sayote ay isang gulay na tumutubo sa gumagapang na baging at may berde, kulubot na balat na maganda lutuing nilaga o ginisa.", "en": "Sayote (chayote) is a vegetable that grows on a climbing vine and has a green, wrinkled skin, good for boiling or sauteing.", "bis": "Ang sayote kay usa ka utanon nga motubo sa nagakatay nga baging ug adunay berde, kunot nga panit nga maayo lutoon og linat-an o gisa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "scorpion-tail-sting-g5", "domain": "LIVING_THINGS", "topic": "scorpion uses its tail stinger to inject venom", "grades": [4, 5, 6], "terms": ["scorpion", "alakdan", "buntot", "tibo", "kamandag", "sting", "tail", "venom", "pincers", "arachnid", "tanga", "ikog", "lala", "sipit", "arthropod", "prey", "defense"], "fact": {"tl": "Ang alakdan ay may nakaangat na buntot na may tibo na ginagamit nito upang ituturok ang kamandag sa biktima o panlaban sa kaaway.", "en": "A scorpion has a raised tail tipped with a stinger that it uses to inject venom into prey or to defend itself.", "bis": "Ang tanga adunay gibayaw nga ikog nga may tusok nga gamiton niini sa pagpasulod og hilo sa biktima o sa pagdepensa sa kaugalingon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "screw-pine-pandan-fruit-g5", "domain": "LIVING_THINGS", "topic": "screw pine (pandan) fruit and aromatic leaves", "grades": [3, 4, 5], "terms": ["pandan", "screw pine", "Pandanus", "prutas", "mabangong dahon", "aromatic leaves", "fruit cluster", "fragrant", "prop roots", "pandan nga dahon", "humot", "gamot", "flavoring"], "fact": {"tl": "Ang pandan o screw pine ay may mabilog na bungang tila pinya at mabangong mahahabang dahon na ginagamit pampalasa at pampabango ng pagkain.", "en": "The screw pine (pandan) bears a round pineapple-like fruit cluster and long fragrant leaves used to flavor and scent food.", "bis": "Ang pandan o screw pine adunay lingin nga bunga nga morag pinya ug taas, humot nga mga dahon nga gamiton aron lasahan ug pahumotan ang pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "seagrass-dugong-grazing-g6", "domain": "LIVING_THINGS", "topic": "dugongs graze on seagrass beds", "grades": [5, 6, 7, 8], "terms": ["dugong", "seagrass", "damong-dagat", "kumakain ng damong-dagat", "grazing", "sea cow", "marine mammal", "herbivore", "baka sa dagat", "lusay", "mananap sa dagat", "mammal", "habitat", "endangered"], "fact": {"tl": "Ang dugong ay isang mammal sa dagat na kumakain ng damong-dagat (seagrass), kaya tinatawag ding 'baka ng dagat,' at nasa panganib na maubos.", "en": "The dugong is a sea mammal that grazes on seagrass, earning it the name 'sea cow,' and it is now an endangered animal.", "bis": "Ang dugong kay usa ka mammal sa dagat nga mokaon og lusay (seagrass), mao nga gitawag og 'baka sa dagat,' ug nameligro na nga mahurot."}, "source": "encyclopedia-stable consensus; IUCN status", "generator": "claude-workflow", "reviewed": false},
  {"id": "seagrass-bed-nursery-g6", "domain": "LIVING_THINGS", "topic": "seagrass beds are nurseries for sea life", "grades": [5, 6, 7, 8], "terms": ["seagrass", "damong-dagat", "tirahan ng isda", "nursery", "seagrass bed", "marine plants", "oxygen", "shelter", "lusay", "puy-anan", "isda", "dagat", "photosynthesis", "habitat", "fish nursery"], "fact": {"tl": "Ang damong-dagat ay tunay na halaman na may ugat at bulaklak na tumutubo sa ilalim ng dagat, at ang tirahan nito ay duyan ng maraming batang isda at hayop-dagat.", "en": "Seagrass is a true flowering plant with roots that grows underwater, and its beds serve as a nursery sheltering many young fish and sea animals.", "bis": "Ang lusay (seagrass) kay tinuod nga tanom nga adunay gamot ug bulak nga motubo ilalom sa dagat, ug ang puy-anan niini maoy duyan sa daghang batan-ong isda ug mananap sa dagat."}, "source": "AAAS Benchmarks 5D; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "seahorse-kabayong-dagat-g5", "domain": "LIVING_THINGS", "topic": "seahorse is a fish where the male carries the young", "grades": [4, 5, 6], "terms": ["seahorse", "kabayong-dagat", "isda", "lalaki ang nagbubuntis", "tail grips", "male pouch", "fish", "kabayo sa dagat", "laki nga nagsabak", "ikog", "upright", "camouflage", "brood pouch"], "fact": {"tl": "Ang kabayong-dagat ay isang isda na lumalangoy nang patayo at kakaiba dahil ang lalaki, hindi ang babae, ang nagbubuntis at nagsisilang ng mga anak.", "en": "The seahorse is a fish that swims upright, and unusually it is the male, not the female, that carries and gives birth to the young.", "bis": "Ang kabayong-dagat kay usa ka isda nga molangoy nga tindog, ug talagsaon kay ang laki, dili ang baye, ang magsabak ug manganak sa mga gagmay."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "seashore-zonation-cross-section-g7", "domain": "LIVING_THINGS", "topic": "seashore zones differ by exposure to tides", "grades": [6, 7, 8], "terms": ["baybayin", "baybayon", "sona ng baybayin", "intertidal", "supratidal", "subtidal", "seashore zonation", "tides", "exposure", "sona sa baybayon", "balod", "hubas", "taob", "cross-section", "habitat", "adaptation"], "fact": {"tl": "Kapag tiningnan ang baybayin mula gilid, makikita ang magkakaibang sona—mula sa laging-tuyo hanggang sa laging-basa—at iba ang mga hayop at halamang nabubuhay sa bawat isa dahil sa pagkakaiba ng taas ng tubig.", "en": "Seen as a cross-section, the seashore shows distinct zones—from always-dry to always-wet—each home to different plants and animals adapted to how much they are covered by the tides.", "bis": "Kon tan-awon ang baybayon gikan sa kilid, makita ang lain-laing sona—gikan sa kanunay-uga hangtod sa kanunay-basa—ug lahi ang mga tanom ug mananap sa matag usa tungod sa kalainan sa taas sa tubig."}, "source": "AAAS Benchmarks 5D; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sense-ear-hearing-g4", "domain": "LIVING_THINGS", "topic": "the ear is the sense organ for hearing", "grades": [3, 4, 5], "terms": ["tainga", "pandinig", "pakinig", "ear", "hearing", "sound", "vibration", "sense organ", "dalunggan", "pamati", "tingog", "tunog", "eardrum", "sound waves"], "fact": {"tl": "Ang tainga ang sangkap ng katawan na nakakarinig; sinasalo nito ang mga tunog at ipinapadala ang senyales sa utak upang ating marinig.", "en": "The ear is the body's organ for hearing; it catches sounds and sends signals to the brain so we can hear.", "bis": "Ang dalunggan mao ang bahin sa lawas nga makadungog; magsalo kini sa mga tingog ug magpadala og senyas ngadto sa utok aron kita makadungog."}, "source": "NRC LS1.A; DepEd G3-4 sense organs", "generator": "claude-workflow", "reviewed": false},
  {"id": "sense-eye-sight-g4", "domain": "LIVING_THINGS", "topic": "the eye is the sense organ for sight", "grades": [3, 4, 5], "terms": ["mata", "paningin", "tingin", "eye", "sight", "vision", "light", "sense organ", "panan-aw", "kahayag", "tan-aw", "pupil", "iris", "lens", "brain"], "fact": {"tl": "Ang mata ang sangkap ng katawan na nakakakita; pinapasok nito ang liwanag at ipinapadala ang larawan sa utak upang makita natin ang mga bagay.", "en": "The eye is the body's organ for sight; it lets in light and sends the image to the brain so we can see things.", "bis": "Ang mata mao ang bahin sa lawas nga makakita; magpasulod kini og kahayag ug magpadala sa hulagway ngadto sa utok aron kita makakita sa mga butang."}, "source": "NRC LS1.A; DepEd G3-4 sense organs", "generator": "claude-workflow", "reviewed": false},
  {"id": "shiitake-mushroom-g6", "domain": "LIVING_THINGS", "topic": "shiitake mushroom is a fungus, not a plant", "grades": [5, 6, 7], "terms": ["shiitake", "kabute", "fungus", "hindi halaman", "mushroom", "decomposer", "spores", "uhong", "fungi", "wood", "kingdom fungi", "edible"], "fact": {"tl": "Ang shiitake ay isang uri ng kabute na kabilang sa kahariang fungi, hindi halaman, at tumutubo sa mga bumubulok na kahoy.", "en": "The shiitake is a kind of mushroom that belongs to the fungi kingdom, not the plant kingdom, and grows on decaying wood.", "bis": "Ang shiitake kay usa ka matang sa uhong nga sakop sa gingharian sa fungi, dili tanom, ug motubo sa nagakadunot nga kahoy."}, "source": "AAAS Benchmarks 5A diversity of life; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sigarilyas-winged-bean-g5", "domain": "LIVING_THINGS", "topic": "sigarilyas (winged bean) legume with winged pods", "grades": [3, 4, 5], "terms": ["sigarilyas", "winged bean", "Psophocarpus", "gulay", "may pakpak na bunga", "legume", "nitrogen-fixing", "four-angled pod", "utanon", "may pako nga bunga", "liso", "protein", "pod"], "fact": {"tl": "Ang sigarilyas ay isang gulay na may apat na pakpak ang berdeng bunga at, bilang legume, ay nakakatulong magpataba ng lupa.", "en": "Sigarilyas (winged bean) is a vegetable whose green pod has four wing-like ridges, and as a legume it helps enrich the soil.", "bis": "Ang sigarilyas kay usa ka utanon nga ang berde nga bunga niini adunay upat ka pako, ug isip legume motabang kini sa pagpatambok sa yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "siling-haba-long-chili-g5", "domain": "LIVING_THINGS", "topic": "siling haba (long green chili) mild pepper", "grades": [3, 4, 5], "terms": ["siling haba", "long chili", "sili", "pampasarap", "green chili", "Capsicum", "mild", "sili nga taas", "gulay", "pang-sinigang", "pepper", "capsaicin", "spice"], "fact": {"tl": "Ang siling haba ay isang mahaba at berdeng sili na mas banayad ang anghang at ginagamit pampasarap sa sinigang at iba pang ulam.", "en": "Siling haba is a long green chili that is mild in heat and is used to flavor sinigang and other dishes.", "bis": "Ang siling haba kay taas ug berde nga sili nga dili kaayo halang ug gamiton aron lasahan ang sinigang ug uban pang sud-an."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "siling-labuyo-g5", "domain": "LIVING_THINGS", "topic": "siling labuyo is a small very hot chili", "grades": [3, 4, 5, 6], "terms": ["siling labuyo", "bird's eye chili", "sili", "maliit na sili", "very hot", "capsaicin", "spicy", "anghang", "sili nga labuyo", "gamay nga sili", "halang kaayo", "pepper", "capsicum", "heat"], "fact": {"tl": "Ang siling labuyo ay napakaliit ngunit napakaanghang na sili dahil sa kemikal na capsaicin na nagdudulot ng init na pakiramdam sa dila.", "en": "Siling labuyo is a tiny but very hot chili because of a chemical called capsaicin that creates a burning feeling on the tongue.", "bis": "Ang siling labuyo kay gamay kaayo apan halang kaayo nga sili tungod sa kemikal nga capsaicin nga maghatag og init nga bati sa dila."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sineguelas-spanish-plum-g5", "domain": "LIVING_THINGS", "topic": "sineguelas (Spanish plum) summer fruit", "grades": [3, 4, 5], "terms": ["sineguelas", "Spanish plum", "Spondias purpurea", "prutas", "prutas sa tag-init", "summer fruit", "plum", "single seed", "sirguelas", "tag-init", "liso", "sweet", "tropical fruit"], "fact": {"tl": "Ang sineguelas ay isang maliit na prutas na hugis-itlog, matamis-maasim, at namumunga tuwing tag-init na may iisang malaking buto sa loob.", "en": "Sineguelas (Spanish plum) is a small egg-shaped, sweet-sour summer fruit with a single large seed inside.", "bis": "Ang sineguelas kay gamay, morag itlog nga porma, tam-is-aslom nga prutas sa ting-init nga adunay usa ka dako nga liso sa sulod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sitaw-string-beans-g5", "domain": "LIVING_THINGS", "topic": "sitaw (string beans) long-podded legume", "grades": [3, 4, 5], "terms": ["sitaw", "string beans", "yardlong beans", "Vigna", "gulay", "mahabang bunga", "legume", "nitrogen-fixing", "batong", "utanon", "taas nga bunga", "liso", "protein", "pod", "vegetable"], "fact": {"tl": "Ang sitaw ay isang gulay na may napakahabang berdeng bunga na puno ng buto at, bilang legume, ay tumutulong magpataba ng lupa.", "en": "Sitaw (string beans) is a vegetable with very long green pods full of seeds, and as a legume it helps make the soil fertile.", "bis": "Ang sitaw (batong) kay usa ka utanon nga adunay taas kaayo nga berde nga bunga nga puno og liso ug, isip legume, motabang sa pagpatambok sa yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "six-kingdoms-g8", "domain": "LIVING_THINGS", "topic": "living things are grouped into kingdoms", "grades": [7, 8, 9, 10], "terms": ["anim na kaharian", "kaharian ng buhay", "klasipikasyon", "six kingdoms", "classification", "animals", "plants", "fungi", "bacteria", "protists", "kingdom", "ginghariang sa kinabuhi", "mananap", "tanom", "uhong", "archaea"], "fact": {"tl": "Inuuri ng mga siyentipiko ang lahat ng nabubuhay na bagay sa malalaking grupong tinatawag na kaharian—tulad ng hayop, halaman, fungi, at mga mikrobyo—batay sa kanilang pagkakatulad.", "en": "Scientists sort all living things into large groups called kingdoms—such as animals, plants, fungi, and microbes—based on their shared traits.", "bis": "Gibahin sa mga siyentista ang tanang buhing butang ngadto sa dagkong grupo nga gitawag og gingharian—sama sa mananap, tanom, uhong, ug mga mikrobyo—base sa ilang managsama nga kinaiya."}, "source": "AAAS Benchmarks 5A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "skin-layers-cross-section-g6", "domain": "LIVING_THINGS", "topic": "skin has layers that protect the body", "grades": [5, 6, 7], "terms": ["balat", "kutis", "sapin-sapin na balat", "epidermis", "dermis", "skin layers", "protect", "sweat", "largest organ", "panit", "panit sa lawas", "sapaw", "singot", "barrier", "temperature"], "fact": {"tl": "Ang balat ay binubuo ng magkakapatong na sapin na nagtatanggol sa katawan, nag-aalis ng init sa pamamagitan ng pawis, at humahadlang sa mikrobyo.", "en": "The skin is made of stacked layers that protect the body, release heat through sweat, and block out germs.", "bis": "Ang panit gilangkoban og sapin-sapin nga sapaw nga magpanalipod sa lawas, magpagawas og init pinaagi sa singot, ug magbabag sa mga mikrobyo."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "skink-bubuli-g5", "domain": "LIVING_THINGS", "topic": "skink is a smooth-scaled lizard", "grades": [4, 5, 6], "terms": ["skink", "butiki", "bubuli", "makinis na balat", "reptile", "lizard", "smooth scales", "cold-blooded", "tabili", "reptilya", "kaliskis", "tail", "insectivore", "scales"], "fact": {"tl": "Ang skink (bubuli o butiki) ay isang reptilyang may makinis at makintab na kaliskis, at marami ito sa mga halaman at ilalim ng mga bato sa Pilipinas.", "en": "The skink (bubuli) is a reptile with smooth, shiny scales, common among plants and under rocks in the Philippines.", "bis": "Ang skink (bubuli o tabili) kay usa ka reptilya nga adunay hamis ug masinaw nga himbis, ug daghan kini sa mga tanom ug ilalom sa mga bato sa Pilipinas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "skipping-rope-cardio-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "exercise like skipping rope strengthens the heart", "grades": [5, 6, 7], "terms": ["lukso-lubid", "skipping rope", "jump rope", "ehersisyo", "cardio", "heart", "exercise", "lakas", "luksong lubid", "kasingkasing", "puso", "aerobic", "fitness", "breathing"], "fact": {"tl": "Ang paglukso sa lubid ay isang ehersisyong nagpapabilis ng tibok ng puso at hininga, kaya pinalalakas nito ang puso at baga.", "en": "Skipping rope is an exercise that speeds up the heartbeat and breathing, which strengthens the heart and lungs.", "bis": "Ang paglukso sa pisi kay usa ka ehersisyo nga magpaspas sa pitik sa kasingkasing ug gininhawa, mao nga magpalig-on sa kasingkasing ug baga."}, "source": "DepEd PE/health; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "small-intestine-nutrient-absorption-g6", "domain": "LIVING_THINGS", "topic": "small intestine absorbs nutrients into the blood", "grades": [5, 6, 7, 8], "terms": ["maliit na bituka", "sustansya", "pagsipsip ng sustansya", "small intestine", "nutrient absorption", "villi", "blood", "digestion", "gamay nga tinai", "pagsuyop", "dugo", "absorb", "nutrients"], "fact": {"tl": "Sa maliit na bituka natutunaw nang husto ang pagkain at doon sinisipsip ang mga sustansya papasok sa dugo sa pamamagitan ng maliliit na bulutong tinatawag na villi.", "en": "In the small intestine food is fully broken down and nutrients are absorbed into the blood through tiny finger-like folds called villi.", "bis": "Sa gamay nga tinai bug-os nga matunaw ang pagkaon ug didto masuyop ang mga sustansya ngadto sa dugo pinaagi sa gagmay nga pilo nga gitawag og villi."}, "source": "NRC LS1.A; DepEd G6 digestive system; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "soil-decomposers-g5", "domain": "LIVING_THINGS", "topic": "soil decomposers break down dead matter", "grades": [5, 6, 7], "terms": ["decomposer", "decomposers", "soil", "dead leaves", "rotting", "fungi", "bacteria", "earthworm", "nutrients", "agbubulok", "naabulok", "lupa", "bakterya", "bulati", "sustansya", "nadunot", "yamungan", "naghugno", "yuta", "bag-as", "ulod", "sustansiya"], "fact": {"tl": "Ang mga decomposer tulad ng fungi, bakterya, at bulati sa lupa ay sumisira sa mga patay na halaman at hayop, na nagbabalik ng sustansya sa lupa para magamit muli ng mga halaman.", "en": "Decomposers like fungi, bacteria, and earthworms in the soil break down dead plants and animals, returning nutrients to the soil for plants to use again.", "bis": "Ang mga decomposer sama sa fungi, bakterya, ug ulod sa yuta nagaguba sa mga patay nga tanom ug hayop, nga nagpabalik sa sustansiya sa yuta aron magamit pag-usab sa mga tanom."}, "source": "NRC LS2.B (cycles of matter); AAAS Benchmarks 5D; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "spine-curves-posture-g5", "domain": "LIVING_THINGS", "topic": "the spine has natural curves that support the body", "grades": [5, 6, 7], "terms": ["spine", "backbone", "vertebrae", "curves", "posture", "support", "gulugod", "kurba", "tindig", "buto", "balikat", "tul-an sa likod", "panindog", "likod", "bukog", "postura"], "fact": {"tl": "Ang gulugod natin ay may likas na mga kurba na parang malambot na 'S' na tumutulong sa pagbalanse, pagsuporta sa timbang ng katawan, at pagprotekta sa spinal cord.", "en": "Our spine has natural S-shaped curves that help us balance, support our body weight, and protect the spinal cord inside it.", "bis": "Ang atong gulugod adunay natural nga mga kurba nga morag 'S' nga nagtabang sa pagbalanse, pagsuporta sa gibug-aton sa lawas, ug pagpanalipod sa spinal cord."}, "source": "encyclopedia-stable consensus (human anatomy)", "generator": "claude-workflow", "reviewed": false},
  {"id": "spine-good-standing-posture-g4", "domain": "LIVING_THINGS", "topic": "good standing posture keeps the back healthy", "grades": [3, 4, 5], "terms": ["posture", "standing", "straight back", "health", "spine", "tindig", "tamang tindig", "tuwid", "likod", "kalusugan", "tarong nga panindog", "tul-id", "panglawas", "tindog"], "fact": {"tl": "Ang tamang pagtayo nang tuwid—balikat na nakaayos at ulong nakaangat—ay nakakatulong na panatilihing malusog ang gulugod at iwasan ang pananakit ng likod.", "en": "Standing up straight with shoulders back and head up keeps the spine healthy and helps prevent back pain.", "bis": "Ang tarong nga pagbarog nga tul-id—abaga nga gipalapad ug ulo nga gipataas—makatabang nga magpabiling himsog ang gulugod ug malikayan ang sakit sa likod."}, "source": "encyclopedia-stable consensus (health education)", "generator": "claude-workflow", "reviewed": false},
  {"id": "staghorn-fern-g5", "domain": "LIVING_THINGS", "topic": "staghorn fern grows on trees without harming them", "grades": [5, 6, 7], "terms": ["staghorn fern", "fern", "epiphyte", "antler leaves", "tree", "pakong-usa", "pako", "halaman", "dahon", "puno", "nakadikit sa puno", "pako nga usa", "lumot-lumot", "kahoy", "dahon nga sungay"], "fact": {"tl": "Ang staghorn fern ay isang pakong tumutubo na nakakapit sa mga sanga ng puno (epiphyte) at may mga dahong hugis-sungay ng usa, ngunit hindi nito sinisipsip ang sustansya ng puno—gumagamit lang ito nito bilang lugar na matirahan.", "en": "The staghorn fern is a fern that grows clinging to tree branches (an epiphyte) and has antler-shaped leaves, but it does not feed off the tree—it only uses it as a place to perch.", "bis": "Ang staghorn fern usa ka pako nga motubo nga nagkapyot sa mga sanga sa kahoy (epiphyte) ug adunay mga dahon nga morag sungay sa usa, apan dili niini suyopon ang sustansiya sa kahoy—gigamit lang kini ingong puy-anan."}, "source": "encyclopedia-stable consensus (botany)", "generator": "claude-workflow", "reviewed": false},
  {"id": "starch-test-leaf-iodine-g6", "domain": "LIVING_THINGS", "topic": "iodine turns starch blue-black to test for photosynthesis", "grades": [6, 7, 8], "terms": ["starch test", "iodine", "leaf", "photosynthesis", "blue-black", "almirol", "yodo", "dahon", "potosintesis", "asul-itim", "subok sa almirol", "tinta", "almidor", "asul nga itom"], "fact": {"tl": "Kapag tinapatan ng yodo ang isang dahon at ito ay naging asul-itim, ibig sabihin may almirol (starch) dito—isang patunay na gumawa ng pagkain ang dahon sa pamamagitan ng photosynthesis.", "en": "When iodine is dropped on a leaf and it turns blue-black, it shows the leaf contains starch—proof that the leaf made food through photosynthesis.", "bis": "Kon tagayan og yodo ang usa ka dahon ug kini mahimong asul-itom, nagpasabot nga adunay almidor (starch) niini—usa ka pamatuod nga ang dahon naghimo og pagkaon pinaagi sa potosintesis."}, "source": "encyclopedia-stable consensus (school biology); AAAS Benchmarks 5C", "generator": "claude-workflow", "reviewed": false},
  {"id": "starfish-reef-g4", "domain": "LIVING_THINGS", "topic": "starfish are echinoderms that move with tube feet", "grades": [4, 5, 6], "terms": ["starfish", "sea star", "tube feet", "reef", "regrow arm", "bituin sa dagat", "braso", "bahura", "paa", "tumutubo muli", "bitoon sa dagat", "bukton", "tiil", "motubo balik"], "fact": {"tl": "Ang starfish ay isang hayop sa dagat (echinoderm), hindi isda, na gumagalaw gamit ang daan-daang maliliit na 'tube feet' at kayang patubuin muli ang nawawalang braso nito.", "en": "The starfish is a sea animal called an echinoderm—not a fish—that moves using hundreds of tiny tube feet and can regrow an arm it loses.", "bis": "Ang starfish usa ka mananap sa dagat (echinoderm), dili isda, nga molihok gamit ang gatosan ka gagmay nga 'tube feet' ug makahimo og pagtubo balik sa nawala niini nga bukton."}, "source": "encyclopedia-stable consensus (marine biology)", "generator": "claude-workflow", "reviewed": false},
  {"id": "stomach-breaking-down-food-g5", "domain": "LIVING_THINGS", "topic": "the stomach digests food with acid and juices", "grades": [5, 6, 7], "terms": ["stomach", "digestion", "stomach acid", "digestive juices", "food", "tiyan", "sikmura", "pagtunaw", "asido", "katas", "pagkain", "tunaw", "asido sa tiyan", "duga", "pagkaon"], "fact": {"tl": "Ang sikmura ay isang parang bag na kalamnan na nagtutunaw ng pagkain sa pamamagitan ng pag-aalog nito at paghahalo ng asido at mga digestive juice upang maging malambot at madaling masipsip.", "en": "The stomach is a muscular bag that breaks down food by churning it and mixing it with acid and digestive juices until it becomes a soft, soupy mush.", "bis": "Ang tiyan usa ka morag bag nga unod nga nagatunaw sa pagkaon pinaagi sa pag-uyog niini ug pagsagol og asido ug digestive juices aron mahimong humok ug malumo."}, "source": "encyclopedia-stable consensus (human anatomy); DepEd Science human body systems", "generator": "claude-workflow", "reviewed": false},
  {"id": "stomach-mixing-food-g4", "domain": "LIVING_THINGS", "topic": "stomach muscles squeeze and mix food", "grades": [3, 4, 5], "terms": ["stomach", "muscle", "squeeze", "mix food", "churn", "tiyan", "kalamnan", "pagpiga", "paghalo", "pagkain", "sikmura", "kaunoran", "pagpuga", "pagsagol", "pagkaon", "kusog"], "fact": {"tl": "Ang mga kalamnan ng sikmura ay gumagalaw at pumipiga upang haluin ang kinain natin, kaya minsan naririnig natin ang 'kalam' nito kapag gutom o tumutunaw ng pagkain.", "en": "The muscles of the stomach squeeze and churn to mix the food we eat, which is why we sometimes hear it rumble when we are hungry or digesting.", "bis": "Ang mga unod sa tiyan mopuga ug moapil-apil aron sagolon ang atong gikaon, mao nga usahay madungog nato ang pagngulob niini kon gigutom o nagatunaw og pagkaon."}, "source": "encyclopedia-stable consensus (human anatomy)", "generator": "claude-workflow", "reviewed": false},
  {"id": "straw-mushroom-kabuteng-saging-g6", "domain": "LIVING_THINGS", "topic": "straw mushroom is an edible fungus grown on rice straw", "grades": [5, 6, 7], "terms": ["straw mushroom", "mushroom", "fungus", "edible", "rice straw", "kabute", "kabuteng saging", "kabuteng dayami", "fungi", "nakakain", "uhot", "uhong", "makaon", "dagami", "uhong sa dagami"], "fact": {"tl": "Ang kabuteng saging (straw mushroom) ay isang nakakaing fungi na karaniwang pinapatubo sa basang dayami ng palay, at hindi ito halaman dahil hindi ito gumagawa ng sariling pagkain sa pamamagitan ng photosynthesis.", "en": "The straw mushroom is an edible fungus often grown on damp rice straw, and it is not a plant because it cannot make its own food through photosynthesis.", "bis": "Ang straw mushroom usa ka makaon nga uhong nga sagad gipatubo sa basa nga dagami sa humay, ug dili kini tanom kay dili kini makahimo og kaugalingong pagkaon pinaagi sa potosintesis."}, "source": "encyclopedia-stable consensus (mycology)", "generator": "claude-workflow", "reviewed": false},
  {"id": "stretching-before-exercise-g4", "domain": "LIVING_THINGS", "topic": "stretching warms up muscles before exercise", "grades": [3, 4, 5], "terms": ["stretching", "warm up", "muscles", "exercise", "injury", "pag-uunat", "kalamnan", "ehersisyo", "pananakit", "init", "pag-inat", "kaunoran", "samad", "pag-init", "lihok"], "fact": {"tl": "Ang pag-uunat (stretching) bago mag-ehersisyo ay nagpapainit at nagpapalambot sa mga kalamnan, na nakatutulong na maiwasan ang pananakit o pagkapinsala ng mga ito.", "en": "Stretching before exercise warms up and loosens the muscles, which helps prevent strains and injuries.", "bis": "Ang pag-inat sa dili pa mag-ehersisyo nagpainit ug nagpahumok sa mga unod, nga makatabang aron malikayan ang sakit o kadaot niini."}, "source": "encyclopedia-stable consensus (physical education / physiology)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sugar-in-drinks-comparison-g5", "domain": "MATTER", "topic": "sweet drinks contain large amounts of dissolved sugar", "grades": [5, 6, 7], "terms": ["sugar", "sweet drinks", "soda", "dissolved", "health", "asukal", "matamis na inumin", "softdrinks", "natutunaw", "kalusugan", "tam-is nga ilimnon", "natunaw", "panglawas"], "fact": {"tl": "Ang mga matamis na inumin tulad ng softdrinks at juice ay may natunaw na malaking dami ng asukal na hindi natin nakikita, kaya ang madalas na pag-inom nito ay maaaring makasama sa ngipin at kalusugan.", "en": "Sweet drinks like soda and juice hold large amounts of dissolved sugar we cannot see, so drinking them often can harm our teeth and health.", "bis": "Ang tam-is nga mga ilimnon sama sa softdrinks ug juice adunay daghang natunaw nga asukal nga dili nato makita, mao nga ang kanunay nga pag-inom niini makadaot sa ngipon ug panglawas."}, "source": "encyclopedia-stable consensus (nutrition / health education)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-protection-salakot-g4", "domain": "LIVING_THINGS", "topic": "the salakot shades the body from the sun", "grades": [3, 4, 5], "terms": ["salakot", "sun protection", "shade", "hat", "heat", "sunlight", "proteksyon sa araw", "lilim", "sumbrero", "init", "sikat ng araw", "panalipod sa adlaw", "landong", "kalo", "silaw sa adlaw"], "fact": {"tl": "Ang salakot ay isang tradisyonal na Pilipinong sumbrero na malapad ang labi upang magbigay ng lilim at protektahan ang mukha at leeg mula sa nakakapasong sikat ng araw.", "en": "The salakot is a traditional wide-brimmed Filipino hat that gives shade and protects the face and neck from the burning rays of the sun.", "bis": "Ang salakot usa ka tradisyonal nga Pilipinhong kalo nga lapad ang ngilit aron mohatag og landong ug manalipod sa nawong ug liog gikan sa makapaso nga silaw sa adlaw."}, "source": "encyclopedia-stable consensus (Philippine culture / health)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sunflower-mirasol-g4", "domain": "LIVING_THINGS", "topic": "sunflowers turn to follow the sun", "grades": [4, 5, 6], "terms": ["sunflower", "mirasol", "heliotropism", "follow the sun", "seeds", "flower", "bulaklak ng araw", "sumusunod sa araw", "buto", "bulaklak", "bulak sa adlaw", "nagsunod sa adlaw", "liso", "bulak"], "fact": {"tl": "Ang batang sunflower o mirasol ay umiikot sa maghapon upang humarap sa araw, isang galaw na tinatawag na heliotropism, at ang kanyang buto ay maaaring kainin o gawing langis.", "en": "A young sunflower turns through the day to face the sun, a movement called heliotropism, and its seeds can be eaten or pressed into oil.", "bis": "Ang batan-ong sunflower o mirasol motalikod sa tibuok adlaw aron mo-atubang sa adlaw, usa ka lihok nga gitawag og heliotropism, ug ang liso niini makaon o himoong lana."}, "source": "encyclopedia-stable consensus (botany)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sweating-cooling-body-g5", "domain": "MATTER", "topic": "sweat cools the body by evaporating", "grades": [5, 6, 7], "terms": ["sweat", "perspiration", "cooling", "evaporation", "body temperature", "pawis", "pagpapawis", "paglamig", "pagsingaw", "init ng katawan", "singot", "pagsingot", "pagbugnaw", "pag-alisngaw", "init sa lawas", "panglamig"], "fact": {"tl": "Kapag tayo ay pinapawisan, ang pawis sa ating balat ay sumisingaw, at ang pagsingaw na ito ay nag-aalis ng init kaya lumalamig ang ating katawan.", "en": "When we sweat, the sweat on our skin evaporates, and this evaporation carries heat away, cooling our body down.", "bis": "Kon kita singoton, ang singot sa atong panit moalisngaw, ug kini nga pag-alisngaw mokuha sa init busa mobugnaw ang atong lawas."}, "source": "encyclopedia-stable consensus (human physiology); AAAS Benchmarks 4D (evaporation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sweet-potato-kamote-g4", "domain": "LIVING_THINGS", "topic": "kamote is a root crop rich in energy", "grades": [4, 5, 6], "terms": ["sweet potato", "kamote", "root crop", "tuber", "carbohydrates", "energy", "kamoteng baging", "ugat", "lamang-ugat", "karbohidrato", "enerhiya", "gamot", "karbohidrato", "kusog"], "fact": {"tl": "Ang kamote ay isang lamang-ugat na lumalaki sa ilalim ng lupa bilang namamagang ugat, at ito ay mayaman sa karbohidrato na nagbibigay ng enerhiya sa katawan.", "en": "The sweet potato (kamote) is a root crop that grows underground as a swollen root, and it is rich in carbohydrates that give the body energy.", "bis": "Ang kamote usa ka lamang-ugat nga motubo ilalom sa yuta isip nanghupong nga gamot, ug dato kini sa karbohidrato nga naghatag og kusog sa lawas."}, "source": "encyclopedia-stable consensus (botany / nutrition)", "generator": "claude-workflow", "reviewed": false},
  {"id": "symbiosis-types-g7", "domain": "LIVING_THINGS", "topic": "types of symbiosis between living things", "grades": [6, 7, 8], "terms": ["symbiosis", "mutualism", "commensalism", "parasitism", "relationship", "organisms", "ugnayan ng organismo", "tulungan", "parasitiko", "simbiyosis", "relasyon sa organismo", "panagtinabangay", "parasito", "komensalismo"], "fact": {"tl": "Ang symbiosis ay ang malapit na pamumuhay ng dalawang magkaibang nilalang: sa mutualism pareho silang nakikinabang, sa commensalism isa ang nakikinabang nang hindi nasasaktan ang isa, at sa parasitism isa ang nakikinabang habang napipinsala ang kabila.", "en": "Symbiosis is the close living-together of two different organisms: in mutualism both benefit, in commensalism one benefits while the other is unharmed, and in parasitism one benefits while the other is harmed.", "bis": "Ang symbiosis mao ang suod nga panagpuyo sa duha ka lahi nga binuhat: sa mutualism pareho silang makabenepisyo, sa commensalism usa ang makabenepisyo nga walay kadaot sa lain, ug sa parasitism usa ang makabenepisyo samtang madaot ang pikas."}, "source": "NRC LS2; AAAS Benchmarks 5D; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "system-integumentary-g6", "domain": "LIVING_THINGS", "topic": "the integumentary system is skin, hair, and nails", "grades": [6, 7, 8], "terms": ["integumentary system", "skin", "hair", "nails", "protection", "body system", "sistemang integumentaryo", "balat", "buhok", "kuko", "proteksyon", "sistema ng katawan", "panit", "panalipod", "sistema sa lawas"], "fact": {"tl": "Ang integumentary system ay binubuo ng balat, buhok, at kuko, at ito ang panlabas na takip na nagpoprotekta sa katawan, pumipigil sa pagkawala ng tubig, at tumutulong sa pagkontrol ng init ng katawan.", "en": "The integumentary system is made up of the skin, hair, and nails, and it forms the outer covering that protects the body, keeps water in, and helps control body temperature.", "bis": "Ang integumentary system gilangkoban sa panit, buhok, ug kuko, ug mao kini ang gawas nga tabon nga nanalipod sa lawas, nagpugong sa pagkawala sa tubig, ug nagtabang sa pagkontrol sa init sa lawas."}, "source": "encyclopedia-stable consensus (human anatomy); DepEd Science human body systems", "generator": "claude-workflow", "reviewed": false},
  {"id": "talbos-ng-kamote-g5", "domain": "LIVING_THINGS", "topic": "kamote tops are an edible leafy vegetable", "grades": [4, 5, 6], "terms": ["sweet potato tops", "kamote tops", "talbos ng kamote", "leafy vegetable", "vitamins", "edible leaves", "gulay na dahon", "bitamina", "nakakaing dahon", "talbos sa kamote", "utan nga dahon", "makaon nga dahon", "lamukot"], "fact": {"tl": "Ang talbos ng kamote ay ang mga murang dahon at usbong ng halamang kamote, at ito ay isang mura at masustansyang gulay na mayaman sa bitamina at hibla (fiber).", "en": "Kamote tops are the young leaves and shoots of the sweet potato plant, and they are a cheap, nutritious leafy vegetable rich in vitamins and fiber.", "bis": "Ang talbos sa kamote mao ang batan-ong dahon ug saha sa tanom nga kamote, ug kini usa ka barato ug masustansya nga utan nga dato sa bitamina ug hibla."}, "source": "encyclopedia-stable consensus (botany / nutrition)", "generator": "claude-workflow", "reviewed": false},
  {"id": "talinum-spinach-g5", "domain": "LIVING_THINGS", "topic": "talinum is a leafy vegetable rich in nutrients", "grades": [4, 5, 6], "terms": ["talinum", "Philippine spinach", "Ceylon spinach", "leafy vegetable", "iron", "gulay", "dahon", "bakal", "sustansya", "utan", "puthaw", "sustansiya"], "fact": {"tl": "Ang talinum ay isang madaling itanim na gulay na dahon na mabilis tumubo kahit sa bakuran, at ito ay pinagkukunan ng bakal at iba pang sustansya na mabuti sa katawan.", "en": "Talinum is an easy-to-grow leafy vegetable that thrives even in backyards, and it is a source of iron and other nutrients good for the body.", "bis": "Ang talinum usa ka sayon nga itanom nga utan nga dahon nga paspas motubo bisan sa tugkaran, ug kini tinubdan sa puthaw ug uban pang sustansiya nga maayo sa lawas."}, "source": "encyclopedia-stable consensus (botany / nutrition)", "generator": "claude-workflow", "reviewed": false},
  {"id": "talisay-tree-g5", "domain": "LIVING_THINGS", "topic": "talisay is a shade tree with tiered branches", "grades": [4, 5, 6], "terms": ["talisay", "tropical almond", "shade tree", "tiered branches", "deciduous", "puno", "lilim", "sanga", "dahon", "kahoy", "landong", "almendras"], "fact": {"tl": "Ang talisay ay isang malaking puno na may mga sangang nakaayos patong-patong na parang palapag, kaya ito ay nagbibigay ng malawak na lilim, at ang mga dahon nito ay namumula bago malagas.", "en": "The talisay is a large tree with branches arranged in horizontal tiers, giving wide shade, and its leaves turn red before they fall.", "bis": "Ang talisay usa ka dako nga kahoy nga ang mga sanga gihan-ay nga patong-patong sama sa andana, busa mohatag kini og lapad nga landong, ug ang mga dahon niini mopula sa dili pa mangahulog."}, "source": "encyclopedia-stable consensus (botany)", "generator": "claude-workflow", "reviewed": false},
  {"id": "tambis-water-apple-g4", "domain": "LIVING_THINGS", "topic": "tambis is a juicy bell-shaped tropical fruit", "grades": [3, 4, 5], "terms": ["tambis", "water apple", "rose apple", "makopa", "fruit", "juicy", "prutas", "matubig", "kampanilya", "tubigon", "bunga"], "fact": {"tl": "Ang tambis ay isang prutas na hugis-kampanilya na may makinis na balat at malutong, matubig at bahagyang matamis na laman, at lumalaki ito sa mga punong-kahoy sa tropikong lugar.", "en": "The tambis (water apple) is a bell-shaped fruit with smooth skin and crisp, watery, mildly sweet flesh, and it grows on trees in tropical places.", "bis": "Ang tambis usa ka prutas nga porma og kampana nga adunay hamis nga panit ug malutong, tubigon, ug gamay nga tam-is nga unod, ug motubo kini sa mga kahoy sa tropikanhong dapit."}, "source": "encyclopedia-stable consensus (botany)", "generator": "claude-workflow", "reviewed": false},
  {"id": "tanglad-lemongrass-g5", "domain": "LIVING_THINGS", "topic": "lemongrass is a fragrant grass used in cooking", "grades": [4, 5, 6], "terms": ["lemongrass", "tanglad", "fragrant grass", "herb", "citral", "cooking", "salay", "mabangong damo", "halamang gamot", "pagluluto", "tangad", "humot nga sagbot", "tambal nga tanom", "pagluto"], "fact": {"tl": "Ang tanglad ay isang mabangong damo na tumutubo nang pakumpol, at ginagamit ang mga matigas nitong dahon at puno bilang pampalasa sa lutuin at panlaban sa lamok dahil sa likas nitong amoy.", "en": "Lemongrass (tanglad) is a fragrant grass that grows in clumps, and its tough leaves and stalks are used to flavor food and to repel mosquitoes because of its natural scent.", "bis": "Ang tanglad usa ka humot nga sagbot nga motubo nga pinungpong, ug ang gahi niini nga dahon ug punoan gigamit isip pampalasa sa pagkaon ug pang-abog sa lamok tungod sa natural niini nga humot."}, "source": "encyclopedia-stable consensus (botany / ethnobotany)", "generator": "claude-workflow", "reviewed": false},
  {"id": "terrarium-closed-jar-ecosystem-g6", "domain": "LIVING_THINGS", "topic": "a closed terrarium recycles water and air", "grades": [6, 7, 8], "terms": ["terrarium", "closed jar", "ecosystem", "water cycle", "photosynthesis", "recycling", "saradong garapon", "ekosistema", "siklo ng tubig", "potosintesis", "sirado nga garapon", "siklo sa tubig"], "fact": {"tl": "Sa isang saradong terrarium, ang mga halaman ay naglalabas ng oxygen at singaw ng tubig na muling nagiging tubig sa loob, kaya nagagawa nitong i-recycle ang tubig at hangin nang halos walang dagdag mula sa labas.", "en": "In a sealed terrarium, the plants release oxygen and water vapor that condenses back into water inside, so it can recycle its own water and air with almost nothing added from outside.", "bis": "Sa usa ka sirado nga terrarium, ang mga tanom mobuga og oxygen ug alisngaw sa tubig nga mobalik nga tubig sa sulod, busa ma-recycle niini ang kaugalingong tubig ug hangin nga halos walay idugang gikan sa gawas."}, "source": "NRC LS2.B; AAAS Benchmarks 5D (cycling of matter); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "three-meals-a-day-g3", "domain": "LIVING_THINGS", "topic": "eating regular balanced meals gives the body energy", "grades": [3, 4, 5], "terms": ["three meals", "balanced diet", "energy", "breakfast", "nutrition", "health", "tatlong beses kumain", "balanseng pagkain", "enerhiya", "almusal", "sustansya", "tulo ka higayon mokaon", "balanse nga pagkaon", "kusog", "pamahaw", "sustansiya"], "fact": {"tl": "Ang pagkain ng tatlong balanseng pagkain sa isang araw—almusal, tanghalian, at hapunan—ay nagbibigay sa katawan ng tuloy-tuloy na enerhiya at sustansya para lumaki at mag-isip nang maayos.", "en": "Eating three balanced meals a day—breakfast, lunch, and dinner—gives the body steady energy and nutrients to grow and think well.", "bis": "Ang pagkaon og tulo ka balanse nga pagkaon sa usa ka adlaw—pamahaw, paniudto, ug panihapon—naghatag sa lawas og padayon nga kusog ug sustansiya aron motubo ug makahunahuna og maayo."}, "source": "encyclopedia-stable consensus (nutrition / health education)", "generator": "claude-workflow", "reviewed": false},
  {"id": "tibig-wild-fig-g6", "domain": "LIVING_THINGS", "topic": "tibig is a native fig tree that holds water", "grades": [5, 6, 7], "terms": ["tibig", "wild fig", "Ficus nota", "native tree", "water source", "fig", "punong igos", "katutubong puno", "tubig", "prutas", "lunhaw nga kahoy", "lumad nga kahoy", "igos"], "fact": {"tl": "Ang tibig ay isang katutubong punong-igos sa Pilipinas na ang mga sanga at ugat ay nag-iimbak ng tubig na maaaring inumin, kaya tinuturing itong puno ng tubig sa kagubatan.", "en": "The tibig is a native Philippine fig tree whose branches and roots store drinkable water, so it is regarded as a water-giving tree in the forest.", "bis": "Ang tibig usa ka lumad nga punoan sa igos sa Pilipinas nga ang mga sanga ug gamot nagtipig og tubig nga mainom, busa giila kini nga kahoy nga tinubdan sa tubig sa lasang."}, "source": "encyclopedia-stable consensus (Philippine ethnobotany)", "generator": "claude-workflow", "reviewed": false},
  {"id": "tidal-flat-migratory-birds-g6", "domain": "LIVING_THINGS", "topic": "tidal flats feed migratory shorebirds", "grades": [5, 6, 7], "terms": ["tidal flat", "mudflat", "migratory birds", "shorebirds", "low tide", "feeding", "lapad na putikan", "ibong dayo", "kati ng tubig", "kati", "lapad nga lapok", "balinhang langgam", "hunas", "ibon"], "fact": {"tl": "Kapag humuhupa ang tubig sa mga tidal flat o putikan sa baybayin, lumilitaw ang malawak na putik na puno ng maliliit na hayop, kaya ito ay nagiging mahalagang lugar na pakainan ng mga ibong dayo (migratory birds).", "en": "When the tide goes out on coastal tidal flats, wide mud rich in small animals is exposed, making it an important feeding ground for migratory shorebirds.", "bis": "Kon mohunas ang tubig sa mga tidal flat o lapok sa baybayon, motungha ang lapad nga lapok nga puno sa gagmay nga mananap, busa kini mahimong importante nga pasibsiban sa mga balinhang langgam."}, "source": "encyclopedia-stable consensus (ecology / ornithology)", "generator": "claude-workflow", "reviewed": false},
  {"id": "tide-pool-scene-g5", "domain": "LIVING_THINGS", "topic": "tide pools are small habitats left by the tide", "grades": [4, 5, 6], "terms": ["tide pool", "rock pool", "low tide", "habitat", "sea creatures", "imbak ng tubig-dagat", "kati", "tirahan", "hayop sa dagat", "bato", "linaw sa bato", "hunas", "puy-anan", "mananap sa dagat"], "fact": {"tl": "Ang tide pool ay isang maliit na imbak ng tubig-dagat na naiiwan sa pagitan ng mga bato kapag humupa ang tubig, at dito nagtatago ang mga starfish, crab, at maliliit na isda hanggang bumalik ang taog.", "en": "A tide pool is a small pocket of seawater left among the rocks when the tide goes out, where starfish, crabs, and small fish shelter until the tide returns.", "bis": "Ang tide pool usa ka gamay nga linaw sa tubig-dagat nga nahibilin tunga sa mga bato kon mohunas ang tubig, ug dinhi magtago ang mga starfish, alimango, ug gagmay nga isda hangtod mobalik ang taob."}, "source": "encyclopedia-stable consensus (marine ecology)", "generator": "claude-workflow", "reviewed": false},
  {"id": "tiesa-canistel-g4", "domain": "LIVING_THINGS", "topic": "tiesa is a sweet egg-textured tropical fruit", "grades": [3, 4, 5], "terms": ["tiesa", "canistel", "egg fruit", "chesa", "fruit", "tropical", "atis-atis", "prutas", "tropikal", "dilaw", "prutas", "tropikanhon", "dalag"], "fact": {"tl": "Ang tiesa o canistel ay isang prutas na dilaw-kahel ang laman na malambot at tuyo na parang lutong pula ng itlog, kaya tinatawag din itong 'egg fruit', at ito ay matamis kapag hinog na.", "en": "The tiesa (canistel) is a fruit with orange-yellow flesh that is soft and dry like a cooked egg yolk—earning it the name 'egg fruit'—and it is sweet when ripe.", "bis": "Ang tiesa o canistel usa ka prutas nga dalag-kahel ang unod nga humok ug uga sama sa giluto nga pula sa itlog, busa gitawag usab kini og 'egg fruit', ug tam-is kini kon hinog na."}, "source": "encyclopedia-stable consensus (botany)", "generator": "claude-workflow", "reviewed": false},
  {"id": "tindalo-tree-g6", "domain": "LIVING_THINGS", "topic": "tindalo is a native Philippine hardwood tree", "grades": [5, 6, 7], "terms": ["tindalo", "Afzelia rhomboidea", "hardwood", "native tree", "timber", "endangered", "matigas na kahoy", "katutubong puno", "troso", "nanganganib", "gahi nga kahoy", "lumad nga kahoy", "namiligro"], "fact": {"tl": "Ang tindalo ay isang katutubong puno sa Pilipinas na may napakatigas at matibay na kahoy na dating ginagamit sa magagandang muwebles, ngunit dahil sa labis na pagtotroso ay bihira na ito ngayon.", "en": "The tindalo is a native Philippine tree with very hard, durable wood once prized for fine furniture, but heavy logging has made it rare today.", "bis": "Ang tindalo usa ka lumad nga kahoy sa Pilipinas nga adunay gahi ug lig-on kaayo nga kahoy nga kaniadto gigamit sa nindot nga mga muwebles, apan tungod sa sobra nga pagputol nahimo na kining talagsaon karon."}, "source": "encyclopedia-stable consensus (Philippine forestry)", "generator": "claude-workflow", "reviewed": false},
  {"id": "tobacco-plant-g6", "domain": "LIVING_THINGS", "topic": "tobacco plant", "grades": [5, 6, 7], "terms": ["tabako", "halamang tabako", "dahon", "tabako nga tanom", "dahon sa tabako", "tobacco plant", "leaves", "nicotine", "Ilocos"], "fact": {"tl": "Ang tabako ay isang halamang malalaki ang dahon na pinapatuyo at ginagamit sa sigarilyo, at marami nito ang itinatanim sa rehiyon ng Ilocos.", "en": "Tobacco is a broad-leaved plant whose dried leaves are used to make cigarettes, and a lot of it is grown in the Ilocos region.", "bis": "Ang tabako usa ka tanom nga lapad og dahon nga ginapauga ug gigamit sa sigarilyo, ug daghan niini ang gitanom sa rehiyon sa Ilocos."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "togue-bean-sprouts-g4", "domain": "LIVING_THINGS", "topic": "mung bean sprouts (togue)", "grades": [3, 4, 5], "terms": ["togue", "ugat", "mung", "munggo", "sibol", "usbong", "toge", "turok sa munggo", "bean sprouts", "germination", "seed"], "fact": {"tl": "Ang togue ay sumisibol na buto ng munggo, na nagiging mahaba't puti kapag pinatubo sa madilim na lugar at sariwang gulay na niluluto.", "en": "Togue is sprouting mung bean seeds that grow long and white when germinated in the dark, and they are cooked as a fresh vegetable.", "bis": "Ang togue mao ang nagaturok nga liso sa munggo nga magtaas ug maputi kung patuboon sa ngitngit nga dapit, ug ginaluto kini isip presko nga utan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tooth-cross-section-parts-g6", "domain": "LIVING_THINGS", "topic": "parts of a tooth", "grades": [5, 6, 7], "terms": ["ngipin", "enamel", "dentin", "pulp", "ugat ng ngipin", "ngipon", "bahin sa ngipon", "tooth", "crown", "root", "nerve"], "fact": {"tl": "Ang ngipin ay may matigas na enamel sa labas, dentin sa loob, at pulp sa gitna na may ugat at nerbiyo.", "en": "A tooth has hard enamel on the outside, dentin underneath, and a soft pulp in the center that holds blood vessels and nerves.", "bis": "Ang ngipon adunay gahi nga enamel sa gawas, dentin sa ilalom, ug humok nga pulp sa tunga nga adunay ugat ug nerbiyo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tooth-function-g4", "domain": "LIVING_THINGS", "topic": "teeth and chewing", "grades": [3, 4, 5], "terms": ["ngipin", "pagnguya", "pagkain", "ngipon", "pagusap", "pagpaak", "tooth", "teeth", "chew", "bite", "digestion"], "fact": {"tl": "Ginagamit natin ang ating mga ngipin upang ngumuya at pagputol-putulin ang pagkain nang mas madaling lunukin at matunaw.", "en": "We use our teeth to chew and cut food into smaller pieces so it is easier to swallow and digest.", "bis": "Gigamit nato ang atong mga ngipon aron mag-usap ug putol-putolon ang pagkaon aron sayon nga tunlon ug hilison."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "transpiration-bag-leaf-experiment-g6", "domain": "LIVING_THINGS", "topic": "transpiration in plants", "grades": [5, 6, 7], "terms": ["transpirasyon", "singaw", "dahon", "tubig", "halaman", "alisngaw", "pag-alisngaw sa tubig", "transpiration", "water vapor", "leaf", "stomata", "plastic bag experiment"], "fact": {"tl": "Kapag binalutan ng plastik ang isang sanga, makikita ang mga patak ng tubig sa loob dahil sa transpirasyon, kung saan inilalabas ng dahon ang singaw ng tubig.", "en": "When a leafy branch is covered with a plastic bag, water droplets collect inside because of transpiration, where leaves release water vapor into the air.", "bis": "Kung putoson og plastik ang usa ka sanga nga adunay dahon, makita ang tinulo sa tubig sa sulod tungod sa transpirasyon, diin ang dahon nagpagawas og alisngaw sa tubig."}, "source": "AAAS Benchmarks 5C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tree-fern-g6", "domain": "LIVING_THINGS", "topic": "tree fern", "grades": [5, 6, 7], "terms": ["pakong kahoy", "pako", "tree fern", "spores", "frond", "punoan nga pako", "pako nga kahoy", "fern", "no flowers", "rainforest"], "fact": {"tl": "Ang tree fern o pakong-kahoy ay malaking pako na may matangkad na tangkay na parang puno, at hindi ito namumulaklak kundi dumarami sa pamamagitan ng spores.", "en": "A tree fern is a large fern with a tall trunk-like stem, and instead of flowers it reproduces using spores.", "bis": "Ang tree fern o pako nga kahoy usa ka dako nga pako nga taas og lawas nga morag punoan, ug dili kini mamulak kondili nagsanay pinaagi sa spores."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tree-nursery-seedling-scene-g5", "domain": "LIVING_THINGS", "topic": "tree nursery and seedlings", "grades": [4, 5, 6], "terms": ["punlaan", "punla", "seedling", "tree nursery", "pananim", "nursery sa kahoy", "tanom", "punla sa kahoy", "transplant", "reforestation"], "fact": {"tl": "Sa isang punlaan, pinatutubo muna ang maliliit na punla sa mga lalagyan bago ito itanim sa bundok o gubat para sa muling pagpapaunlad ng kakahuyan.", "en": "In a tree nursery, young seedlings are grown in containers first before being planted in hills or forests to help reforestation.", "bis": "Sa usa ka punlaan, ginapatubo una ang gagmay nga punla sa sudlanan una itanom sa bukid o lasang aron makatabang sa pagbalik sa kalasangan."}, "source": "DepEd MATATAG Science CG; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "trimming-fingernails-clipper-g3", "domain": "LIVING_THINGS", "topic": "trimming fingernails for hygiene", "grades": [3, 4], "terms": ["kuko", "pagputol ng kuko", "kalinisan", "gunting sa kuko", "pagputol sa kuko", "kuko sa tudlo", "fingernail", "clipper", "hygiene", "germs"], "fact": {"tl": "Pinuputol natin ang mga kuko gamit ang panggupit upang hindi makaipon ng dumi at mikrobyo sa ilalim ng mga ito.", "en": "We trim our fingernails with a clipper so that dirt and germs do not collect underneath them.", "bis": "Ginaputol nato ang atong mga kuko gamit ang kortador aron walay hugaw ug mikrobyo nga magtipon sa ilawom niini."}, "source": "DepEd MATATAG Science CG; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "trophic-roles-web-diagram-g6", "domain": "LIVING_THINGS", "topic": "food web trophic roles", "grades": [5, 6, 7], "terms": ["food web", "producer", "consumer", "decomposer", "gumagawa ng pagkain", "kumakain", "tagapagsira", "tigtunaw", "nagbuhat og pagkaon", "tagkaon", "sagol-sagol nga kadena sa pagkaon", "energy flow"], "fact": {"tl": "Sa isang food web, ang mga halaman ang gumagawa ng pagkain, ang mga hayop ang kumakain nito, at ang mga decomposer ang nagbubulok ng mga patay na bagay.", "en": "In a food web, plants are the producers that make food, animals are the consumers that eat it, and decomposers break down dead matter.", "bis": "Sa usa ka food web, ang mga tanom mao ang naghimo og pagkaon, ang mga hayop mao ang nagkaon niini, ug ang mga decomposer mao ang naglata sa mga patay nga butang."}, "source": "NRC LS2.B; AAAS Benchmarks 5D", "generator": "claude-workflow", "reviewed": false},
  {"id": "tsaang-gubat-g6", "domain": "LIVING_THINGS", "topic": "tsaang-gubat medicinal plant", "grades": [5, 6, 7], "terms": ["tsaang gubat", "wild tea", "halamang gamot", "dahon", "tsaang-gubat", "herbal nga tsaa", "tanom nga tambal", "Ehretia microphylla", "medicinal plant", "stomach"], "fact": {"tl": "Ang tsaang-gubat ay isang halamang-gamot na ang mga dahon ay pinapakuluan bilang tsaa upang tumulong laban sa pananakit ng tiyan at pagtatae.", "en": "Tsaang-gubat is a Philippine medicinal plant whose leaves are boiled into a tea to help relieve stomachache and diarrhea.", "bis": "Ang tsaang-gubat usa ka tanom nga tambal sa Pilipinas nga ang mga dahon ginapabukal isip tsaa aron makatabang batok sa kasakit sa tiyan ug kalibanga."}, "source": "DOH-PITAHC approved Philippine herbal medicine; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tuba-coconut-sap-gathering-g6", "domain": "LIVING_THINGS", "topic": "coconut sap (tuba)", "grades": [5, 6, 7], "terms": ["tuba", "katas ng niyog", "bulaklak ng niyog", "mangungutob", "duga sa lubi", "bulak sa lubi", "coconut sap", "fermentation", "toddy", "mananggete"], "fact": {"tl": "Ang tuba ay katas na kinukuha mula sa hindi pa nabubukang bulaklak ng niyog, at kapag ito ay umasim sa pamamagitan ng fermentation ay nagiging inumin.", "en": "Tuba is the sweet sap gathered from the unopened flower of the coconut tree, and it becomes a drink when it ferments and turns sour.", "bis": "Ang tuba mao ang tam-is nga duga nga ginakuha gikan sa wala pa mabuka nga bulak sa lubi, ug mahimo kining ilimnon kung mo-aslom kini pinaagi sa fermentation."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tugui-yam-g5", "domain": "LIVING_THINGS", "topic": "tugui (lesser yam)", "grades": [4, 5, 6], "terms": ["tugui", "tugi", "ube", "ugat", "lesser yam", "gamot nga kan-onon", "tuber", "root crop", "carbohydrate"], "fact": {"tl": "Ang tugui ay isang ugat na pananim na tumutubo sa ilalim ng lupa at niluluto bilang pagkaing mayaman sa carbohydrate.", "en": "Tugui is a yam root crop that grows underground and is cooked as a starchy food rich in carbohydrates.", "bis": "Ang tugui usa ka gamot nga tanom nga motubo sa ilalom sa yuta ug ginaluto isip pagkaon nga dato sa carbohydrate."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ube-purple-yam-g5", "domain": "LIVING_THINGS", "topic": "ube (purple yam)", "grades": [4, 5, 6], "terms": ["ube", "ubi", "purple yam", "lila", "ugat", "purpura nga ubi", "gamot nga kan-onon", "tuber", "root crop", "halaya", "Dioscorea alata"], "fact": {"tl": "Ang ube ay isang ugat na pananim na kulay lila ang loob, tumutubo sa ilalim ng lupa, at ginagamit sa mga panghimagas tulad ng halaya at ice cream.", "en": "Ube is a purple-fleshed yam that grows underground and is used in Filipino desserts like halaya and ice cream.", "bis": "Ang ube usa ka gamot nga tanom nga purpura ang sulod, motubo sa ilalom sa yuta, ug gigamit sa mga matam-is sama sa halaya ug ice cream."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "upo-bottle-gourd-g5", "domain": "LIVING_THINGS", "topic": "upo (bottle gourd)", "grades": [4, 5, 6], "terms": ["upo", "kalabasa", "bottle gourd", "gulay", "tabungaw", "utan", "gourd", "vine", "vegetable"], "fact": {"tl": "Ang upo ay isang mahaba't berdeng gulay na tumutubo sa gumagapang na halaman at niluluto bilang sabaw o ginisa.", "en": "Upo is a long, light-green gourd that grows on a climbing vine and is cooked in soups or sauteed dishes.", "bis": "Ang upo usa ka taas ug berde nga utanon nga motubo sa nagakatay nga tanom ug ginaluto isip sabaw o ginisa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "urinary-system-pathway-g6", "domain": "LIVING_THINGS", "topic": "urinary system", "grades": [5, 6, 7], "terms": ["sistema ng ihi", "bato", "pantog", "ihi", "sistema sa ihi", "kidney", "amimislon", "pantog sa ihi", "urinary system", "bladder", "ureter", "waste"], "fact": {"tl": "Sa sistema ng ihi, sinasala ng mga bato ang dugo at ginagawang ihi ang dumi na dumadaloy patungo sa pantog bago ilabas ng katawan.", "en": "In the urinary system, the kidneys filter the blood and turn waste into urine, which flows to the bladder before leaving the body.", "bis": "Sa sistema sa ihi, ang mga kidney nagasala sa dugo ug naghimo og ihi gikan sa hugaw, nga modagayday padulong sa pantog una mogawas sa lawas."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "vaccination-immunity-g6", "domain": "LIVING_THINGS", "topic": "vaccination and immunity", "grades": [5, 6, 7], "terms": ["bakuna", "kaligtasan sa sakit", "immune", "pagbakuna", "depensa sa lawas", "vaccine", "immunity", "antibodies", "disease"], "fact": {"tl": "Ang bakuna ay nagsasanay sa depensa ng katawan upang makilala at malabanan ang isang mikrobyo, kaya hindi na tayo madaling magkasakit nito.", "en": "A vaccine trains the body's defenses to recognize and fight a germ, so we are protected and less likely to get that disease.", "bis": "Ang bakuna nagabansay sa depensa sa lawas aron mailhan ug masukol ang usa ka mikrobyo, mao nga maluwas kita ug dili dali matakdan niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "vanda-orchid-g6", "domain": "LIVING_THINGS", "topic": "vanda orchid", "grades": [5, 6, 7], "terms": ["vanda", "orkidya", "orchid", "bulaklak", "orkids", "bulak", "ugat sa hangin", "aerial roots", "epiphyte"], "fact": {"tl": "Ang vanda ay isang uri ng orkidya na may makukulay na bulaklak at mga ugat na nakalantad sa hangin para sumipsip ng halumigmig.", "en": "The vanda is a type of orchid with colorful flowers and air roots that hang out in the open to absorb moisture.", "bis": "Ang vanda usa ka matang sa orkids nga adunay mabulukon nga bulak ug mga ugat nga nagbitay sa hangin aron mosuyop og umog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "vanilla-orchid-pod-g6", "domain": "LIVING_THINGS", "topic": "vanilla orchid", "grades": [5, 6, 7], "terms": ["vanilla", "orkidya", "vanilla pod", "bunga", "banilya", "orkids", "bunga sa vanilla", "vanilla orchid", "flavoring", "bean pod"], "fact": {"tl": "Ang vanilla ay nagmumula sa mahabang bunga ng isang orkidya, at ang pinatuyong bunga nito ang nagbibigay ng pampalasa sa mga matamis na pagkain.", "en": "Vanilla comes from the long pod of an orchid, and the dried pod gives the sweet flavoring used in desserts.", "bis": "Ang vanilla naggikan sa taas nga bunga sa usa ka orkids, ug ang pinauga nga bunga niini maoy naghatag og lami sa mga matam-is nga pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "vegetable-garden-pechay-plot-g4", "domain": "LIVING_THINGS", "topic": "vegetable garden", "grades": [3, 4, 5], "terms": ["hardin ng gulay", "pechay", "taniman", "gulay", "tanaman sa utanon", "petsay", "utanon", "vegetable garden", "leafy vegetable", "harvest"], "fact": {"tl": "Sa isang hardin ng gulay, itinatanim sa magkakahanay na taniman ang mga gulay tulad ng pechay na inaalagaan ng tubig at araw hanggang maani.", "en": "In a vegetable garden, leafy vegetables like pechay are planted in rows and cared for with water and sunlight until they are ready to harvest.", "bis": "Sa usa ka tanaman sa utanon, ang mga utanon sama sa petsay ginatanom sa han-ay nga taroan ug giatiman pinaagi sa tubig ug adlaw hangtod maani."}, "source": "DepEd MATATAG Science CG; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "vitamin-a-food-sources-g5", "domain": "LIVING_THINGS", "topic": "vitamin A food sources", "grades": [4, 5, 6], "terms": ["bitamina A", "karot", "kamote", "mata", "vitamin A", "carrots", "eyesight", "malunggay"], "fact": {"tl": "Ang bitamina A na makukuha sa karot, kamote, at malunggay ay tumutulong upang manatiling malinaw at malusog ang ating paningin.", "en": "Vitamin A, found in carrots, sweet potato, and malunggay, helps keep our eyesight clear and our eyes healthy.", "bis": "Ang bitamina A nga makuha sa karot, kamote, ug malunggay nagatabang aron magpabilin nga klaro ug himsog ang atong panan-aw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "vitamin-c-food-sources-g5", "domain": "LIVING_THINGS", "topic": "vitamin C food sources", "grades": [4, 5, 6], "terms": ["bitamina C", "kalamansi", "dalandan", "bayabas", "kahel", "vitamin C", "citrus", "guava", "immune system"], "fact": {"tl": "Ang bitamina C na matatagpuan sa kalamansi, dalandan, at bayabas ay tumutulong upang labanan ang sakit at gumaling ang mga sugat.", "en": "Vitamin C, found in calamansi, oranges, and guava, helps the body fight illness and heal wounds.", "bis": "Ang bitamina C nga makita sa kalamansi, kahel, ug bayabas nagatabang sa lawas aron makigbatok sa sakit ug maayo ang mga samad."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "vitamins-sources-fruits-veg-g4", "domain": "LIVING_THINGS", "topic": "vitamins from fruits and vegetables", "grades": [3, 4, 5], "terms": ["bitamina", "prutas", "gulay", "sustansya", "utanon", "sustansiya", "vitamins", "fruits", "vegetables", "nutrients", "health"], "fact": {"tl": "Ang mga prutas at gulay ay mayaman sa iba't ibang bitamina na nagpapalakas ng katawan at nagpapanatili sa atin na malusog.", "en": "Fruits and vegetables are rich in different vitamins that strengthen the body and keep us healthy.", "bis": "Ang mga prutas ug utanon dato sa nagkalainlaing bitamina nga nagpalig-on sa lawas ug nagtipig kanato nga himsog."}, "source": "DepEd MATATAG Science CG; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "volcanic-slope-ecosystem-g7", "domain": "LIVING_THINGS", "topic": "volcanic slope ecosystem", "grades": [6, 7, 8], "terms": ["bulkan", "ekosistema", "lupa", "halaman", "kalibutanan", "yuta", "tanom", "volcanic slope", "ecosystem", "fertile soil", "pioneer plants"], "fact": {"tl": "Pagkalipas ng pagputok ng bulkan, ang abo nito ay nagpapayaman ng lupa kaya unti-unting tumutubo muli ang mga halaman at bumabalik ang mga hayop sa dalisdis.", "en": "After a volcano erupts, its ash enriches the soil, so plants slowly grow back and animals return to live on the slope.", "bis": "Human mobuto ang bulkan, ang abo niini nagpadato sa yuta mao nga anam-anam nga motubo pag-usab ang mga tanom ug mobalik ang mga hayop sa bakilid."}, "source": "AAAS Benchmarks 5D; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "waling-waling-orchid-g6", "domain": "LIVING_THINGS", "topic": "waling-waling orchid", "grades": [5, 6, 7], "terms": ["waling-waling", "orkidya", "Mindanao", "bulaklak", "orkids", "bulak", "waling waling", "orchid", "endemic", "Vanda sanderiana"], "fact": {"tl": "Ang waling-waling ay isang malaki at makulay na orkidya na tubo lamang sa mga gubat ng Mindanao, at itinuturing itong 'Reyna ng mga Orkidya' ng Pilipinas.", "en": "The waling-waling is a large, colorful orchid that grows wild only in the forests of Mindanao, and it is called the 'Queen of Philippine Orchids.'", "bis": "Ang waling-waling usa ka dako ug mabulukon nga orkids nga motubo lamang sa kalasangan sa Mindanao, ug gitawag kini nga 'Rayna sa mga Orkids' sa Pilipinas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "warmup-stretching-poses-g4", "domain": "LIVING_THINGS", "topic": "warm-up stretching", "grades": [3, 4, 5], "terms": ["pag-init", "pag-unat", "ehersisyo", "kalamnan", "pag-init sa lawas", "pag-inat", "warm-up", "stretching", "muscles", "exercise"], "fact": {"tl": "Ang pag-init at pag-unat bago mag-ehersisyo ay naghahanda sa ating mga kalamnan at nakatutulong upang maiwasan ang pinsala.", "en": "Warming up and stretching before exercise prepares our muscles and helps prevent injuries.", "bis": "Ang pag-init ug pag-inat sa dili pa mag-ehersisyo nagaandam sa atong mga unod ug nagatabang aron malikayan ang kadaot."}, "source": "DepEd MATATAG Science CG; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-lily-g5", "domain": "LIVING_THINGS", "topic": "water lily", "grades": [4, 5, 6], "terms": ["water lily", "lirio", "lawa", "dahon", "lirio sa tubig", "linaw", "dahon nga naglutaw", "floating leaves", "pond", "aquatic plant", "roots in mud"], "fact": {"tl": "Ang water lily ay halamang-tubig na may malalapad na dahong lumulutang sa ibabaw ng lawa habang nakaugat ang halaman sa putik sa ilalim.", "en": "The water lily is an aquatic plant with broad leaves that float on the surface of a pond while its roots anchor in the mud below.", "bis": "Ang water lily usa ka tanom sa tubig nga adunay lapad nga mga dahon nga naglutaw sa ibabaw sa linaw samtang ang gamot niini nakaugat sa lapok sa ilalom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "watermelon-pakwan-g4", "domain": "LIVING_THINGS", "topic": "watermelon fruit", "grades": [3, 4, 5], "terms": ["pakwan", "watermelon", "prutas", "bunga", "tubig", "buto", "pula", "tag-init", "pakwan prutas", "watermelon fruit", "berde", "lasang tubig", "mga liso"], "fact": {"tl": "Ang pakwan ay isang malaki, berde sa labas at pula sa loob na prutas na halos puro tubig, kaya nakakapreskong kainin tuwing tag-init.", "en": "Watermelon is a large fruit, green outside and red inside, that is mostly water, which is why it is so refreshing to eat in the hot season.", "bis": "Ang pakwan usa ka dako nga prutas, lunhaw sa gawas ug pula sa sulod, nga puno sa tubig, mao nga makapabugnaw kini kan-on panahon sa init."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wearing-mask-when-sick-g4", "domain": "LIVING_THINGS", "topic": "wearing a face mask", "grades": [3, 4, 5], "terms": ["mask", "maskara", "takip sa ilong", "may sakit", "ubo", "bahin", "sipon", "mikrobyo", "germ", "kumalat", "pagsuot ng mask", "wearing mask", "pagsul-ob ug mask", "ubo bahin"], "fact": {"tl": "Kapag may sakit ka, ang pagsuot ng mask ay humaharang sa maliliit na patak ng laway kapag umuubo o bumabahing ka, kaya hindi mabilis na kumalat ang mikrobyo sa iba.", "en": "When you are sick, wearing a mask blocks the tiny droplets from your coughs and sneezes, so germs do not spread as easily to other people.", "bis": "Kung magsakit ka, ang pagsul-ob ug mask makasanta sa gagmay nga tulo sa laway kung mag-ubo o magbahin ka, busa dili dali makatakod ang mikrobyo sa uban."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wearing-slippers-outdoors-g3", "domain": "LIVING_THINGS", "topic": "footwear protects feet", "grades": [3, 4], "terms": ["tsinelas", "slippers", "sapatos", "paa", "sugat", "mikrobyo", "bulate", "proteksyon", "pagsuot ng tsinelas", "wearing slippers", "sandalyas", "sakit sa paa", "tiil"], "fact": {"tl": "Ang pagsuot ng tsinelas o sapatos sa labas ay nag-iingat sa iyong mga paa mula sa matatalim na bagay at mikrobyong nasa lupa na maaaring magdulot ng sugat o sakit.", "en": "Wearing slippers or shoes outdoors protects your feet from sharp objects and germs in the soil that could cause cuts or illness.", "bis": "Ang pagsul-ob ug tsinelas o sapatos sa gawas manalipod sa imong tiil gikan sa hait nga butang ug mikrobyo sa yuta nga makahatag ug samad o sakit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wildlife-poaching-cage-scene-g6", "domain": "LIVING_THINGS", "topic": "wildlife poaching harms biodiversity", "grades": [5, 6, 7], "terms": ["pangangaso", "poaching", "ilegal", "hayop", "wildlife", "ihalas nga hayop", "hawla", "cage", "endangered", "namamatay na species", "pagpangayam", "ilegal nga pagdakop", "konserbasyon", "pagkalipol"], "fact": {"tl": "Ang ilegal na pangangaso o pagbihag ng mababangis na hayop ay nagpapababa sa bilang ng mga species at maaaring magtulak sa ilang hayop patungo sa pagkalipol.", "en": "Illegal poaching or caging of wild animals lowers the number of each species and can push some animals toward extinction.", "bis": "Ang ilegal nga pagpangayam o pagbihag sa ihalas nga mga hayop makapakunhod sa gidaghanon sa matag species ug mahimong moduso sa pipila ka hayop ngadto sa pagkapuo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wildlife-rescue-release-scene-g6", "domain": "LIVING_THINGS", "topic": "wildlife rescue and release", "grades": [5, 6, 7], "terms": ["pagsagip", "rescue", "wildlife", "hayop", "kalikasan", "release", "pagpakawala", "ihalas nga hayop", "konserbasyon", "pagluwas", "pagbuhi", "habitat", "tirahan", "puy-anan"], "fact": {"tl": "Sa wildlife rescue, ang mga nasaktan o nahuling hayop ay pinapagaling muna at saka pinapakawala pabalik sa kanilang likas na tirahan upang muling mabuhay nang malaya.", "en": "In wildlife rescue, injured or captured animals are first nursed back to health and then released into their natural habitat to live freely again.", "bis": "Sa wildlife rescue, ang nasamdan o nadakpan nga mga hayop pagaayohon una unya buhian balik sa ilang natural nga puy-anan aron mabuhi pag-usab nga gawasnon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wormwood-herba-buena-g6", "domain": "LIVING_THINGS", "topic": "herbal mint plant", "grades": [5, 6, 7], "terms": ["herba buena", "herbabuena", "yerba buena", "mint", "halamang gamot", "dahon", "pananakit ng ulo", "tambal", "tanom nga tambal", "mentol", "mabangong dahon", "medicinal plant", "labad sa ulo", "tiyan"], "fact": {"tl": "Ang herba buena ay isang mabangong halamang-gamot na kapamilya ng mint, at ang mga dahon nito ay matagal nang ginagamit sa Pilipinas bilang panlunas sa pananakit ng ulo at sikmura.", "en": "Herba buena is a fragrant mint-family herb whose leaves have long been used in the Philippines as a folk remedy for headaches and stomachaches.", "bis": "Ang herba buena usa ka humot nga tanom nga tambal nga sakop sa banay sa mint, ug ang mga dahon niini dugay nang gigamit sa Pilipinas isip tambal sa labad sa ulo ug tiyan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "yakal-tree-g6", "domain": "LIVING_THINGS", "topic": "yakal hardwood tree", "grades": [5, 6, 7], "terms": ["yakal", "punong yakal", "kahoy", "matigas na kahoy", "hardwood", "Shorea", "katutubong puno", "gusali", "konstruksyon", "kahoy nga gahi", "lumber", "native tree", "taytayan", "haligi"], "fact": {"tl": "Ang yakal ay isang katutubong punong-kahoy ng Pilipinas na napakatigas at matibay ng kahoy, kaya't ginagamit ito sa mga haligi, tulay, at gusali.", "en": "Yakal is a native Philippine tree whose wood is very hard and strong, so it is used for posts, bridges, and buildings.", "bis": "Ang yakal usa ka lumad nga kahoy sa Pilipinas nga gahi kaayo ug lig-on ang kahoy, busa gigamit kini sa mga haligi, taytayan, ug mga building."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "yeast-balloon-fermentation-g6", "domain": "MATTER", "topic": "yeast produces carbon dioxide gas", "grades": [5, 6, 7], "terms": ["lebadura", "yeast", "lobo", "balloon", "asukal", "carbon dioxide", "gas", "fermentation", "pagbula", "umaalsa", "namamaga ang lobo", "pampaalsa", "pampalobo", "botelya"], "fact": {"tl": "Kapag pinagsama ang lebadura, asukal, at maligamgam na tubig sa loob ng bote, kinakain ng lebadura ang asukal at naglalabas ng carbon dioxide na gas na nagpapalobo sa nakatakip na lobo.", "en": "When yeast, sugar, and warm water are mixed in a bottle, the yeast feeds on the sugar and releases carbon dioxide gas that inflates a balloon placed over the top.", "bis": "Kung isagol ang lebadura, asukal, ug init-init nga tubig sa botelya, mokaon ang lebadura sa asukal ug mobuga ug carbon dioxide nga gas nga mopaburot sa lobo nga gibutang sa baba sa botelya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "yeast-fermentation-cells-g7", "domain": "LIVING_THINGS", "topic": "yeast are living fungi", "grades": [6, 7, 8], "terms": ["lebadura", "yeast", "fungi", "halamang-singaw", "selula", "cell", "nabubuhay", "microorganism", "fermentation", "pagpaparami", "naghahati", "fungus", "buhing organismo", "pampaalsa"], "fact": {"tl": "Ang lebadura ay isang buhay na isang-selulang halamang-singaw (fungus) na dumarami sa pamamagitan ng pagsibol, at sa proseso ng fermentation ito ang gumagawa ng gas at alkohol mula sa asukal.", "en": "Yeast is a living single-celled fungus that multiplies by budding, and through fermentation it makes gas and alcohol from sugar.", "bis": "Ang lebadura usa ka buhi nga usa-ka-selula nga fungus nga nagdaghan pinaagi sa pagturok, ug pinaagi sa fermentation kini ang nagahimo ug gas ug alkohol gikan sa asukal."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "yellow-bell-flower-g4", "domain": "LIVING_THINGS", "topic": "yellow bell flowering shrub", "grades": [3, 4, 5], "terms": ["yellow bell", "kampanilya", "dilaw na bulaklak", "halaman", "bulaklak", "shrub", "palumpong", "Allamanda", "tanom", "bulak nga dilaw", "hardin", "ornamental", "kampana", "tanaman"], "fact": {"tl": "Ang yellow bell o kampanilya ay isang palumpong na may matingkad na dilaw na bulaklak na hugis kampana, at madalas itong itinatanim sa mga hardin bilang palamuti.", "en": "The yellow bell is a shrub with bright yellow bell-shaped flowers, and it is often planted in gardens as an ornamental.", "bis": "Ang yellow bell usa ka palumpong nga adunay hayag nga dilaw nga bulak nga porma og kampana, ug kanunay kining gitanom sa mga tanaman isip dayandayan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ylang-ylang-flower-g6", "domain": "LIVING_THINGS", "topic": "ylang-ylang fragrant flower", "grades": [5, 6, 7], "terms": ["ylang-ylang", "ilang-ilang", "bulaklak", "mabango", "pabango", "perfume", "langis", "essential oil", "humot nga bulak", "tanom", "punong ilang-ilang", "amoy", "Cananga", "pahumot"], "fact": {"tl": "Ang ilang-ilang ay isang punong-kahoy na may mabangong dilaw na bulaklak, at ang langis na kinukuha mula rito ay ginagamit sa paggawa ng mamahaling pabango.", "en": "Ylang-ylang is a tree with very fragrant yellow flowers, and the oil taken from them is used to make expensive perfumes.", "bis": "Ang ilang-ilang usa ka kahoy nga adunay humot nga dilaw nga bulak, ug ang lana nga gikuha gikan niini gigamit sa paghimo ug mahal nga pahumot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "zinnia-flower-g4", "domain": "LIVING_THINGS", "topic": "zinnia garden flower", "grades": [3, 4, 5], "terms": ["zinnia", "bulaklak", "halaman", "makukulay", "hardin", "buto", "tanom", "bulak", "mabilis tumubo", "paru-paro", "pollinator", "ornamental", "garden flower", "alibangbang"], "fact": {"tl": "Ang zinnia ay isang madaling palaguing halamang-bulaklak na may makukulay na talulot, at ang mga bulaklak nito ay umaakit ng mga paru-paro at bubuyog sa hardin.", "en": "The zinnia is an easy-to-grow flowering plant with colorful petals, and its blooms attract butterflies and bees to the garden.", "bis": "Ang zinnia usa ka sayon patubuon nga tanom nga bulak nga adunay mabulukon nga mga petalo, ug ang mga bulak niini magdani sa mga alibangbang ug putyukan sa tanaman."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "acid-on-eggshell-bubbles-g6", "domain": "MATTER", "topic": "acid reacting with eggshell", "grades": [5, 6, 7], "terms": ["asido", "acid", "suka", "vinegar", "balat ng itlog", "eggshell", "bula", "carbon dioxide", "gas", "calcium carbonate", "reaksyon", "panit sa itlog", "naglalabas ng bula", "kemikal na reaksyon"], "fact": {"tl": "Kapag inilubog ang itlog sa suka, ang asido ay tumutugon sa calcium carbonate ng balat at naglalabas ng mga bula ng carbon dioxide, hanggang sa malusaw ang matigas na balat.", "en": "When an egg is soaked in vinegar, the acid reacts with the calcium carbonate of the shell and releases carbon dioxide bubbles, until the hard shell dissolves away.", "bis": "Kung itumog ang itlog sa suka, ang asido motubag sa calcium carbonate sa panit ug mobuga ug mga bula sa carbon dioxide, hangtod matunaw ang gahi nga panit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "antacid-tablet-fizzing-g6", "domain": "MATTER", "topic": "antacid tablet fizzing reaction", "grades": [5, 6, 7], "terms": ["antacid", "tableta", "pumuputok", "bula", "tubig", "carbon dioxide", "gas", "reaksyon", "fizzing", "nalulusaw", "natutunaw", "natunaw nga tableta", "kemikal na reaksyon", "gamot sa sikmura"], "fact": {"tl": "Kapag inihulog ang isang fizzing na antacid tablet sa tubig, ito ay tumutugon at naglalabas ng carbon dioxide na gas, kaya lumilitaw ang maraming bula.", "en": "When a fizzing antacid tablet is dropped into water, it reacts and releases carbon dioxide gas, which is why many bubbles appear.", "bis": "Kung ihulog ang usa ka fizzing nga antacid tablet sa tubig, motubag kini ug mobuga ug carbon dioxide nga gas, mao nga daghang bula ang motungha."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "apog-lime-for-nganga-g7", "domain": "MATTER", "topic": "slaked lime is a base", "grades": [6, 7, 8], "terms": ["apog", "lime", "nganga", "betel", "ngangaan", "calcium hydroxide", "base", "alkaline", "puti", "mineral", "apog sa nganga", "lime sa nganga", "asido base", "pula nga laway"], "fact": {"tl": "Ang apog na idinaragdag sa nganga ay calcium hydroxide, isang puting base na tumutulong na palabasin ng dahon ng ikmo at ng bunga ang sangkap na nagpapapula sa laway.", "en": "The lime added to betel chew is calcium hydroxide, a white base that helps release the substances from the betel leaf and nut, turning the chewer's saliva red.", "bis": "Ang apog nga idugang sa nganga mao ang calcium hydroxide, usa ka puti nga base nga motabang sa pagpagawas sa mga sustansya gikan sa dahon ug bunga, nga magpapula sa laway."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "atchara-fermentation-jar-g7", "domain": "LIVING_THINGS", "topic": "fermentation preserves atchara", "grades": [6, 7, 8], "terms": ["atchara", "atsara", "papaya", "fermentation", "suka", "pag-iimbak", "preservation", "asin", "bakterya", "pagpapanatili", "pag-asim", "pagpreserba", "kapayas", "asido"], "fact": {"tl": "Ang atsara ay gawa sa hinimay na hilaw na papaya na ibinababad sa suka, asukal, at asin, kung saan ang asido at asin ang pumipigil sa mga nakasisirang mikrobyo upang tumagal ang pagkain.", "en": "Atchara is made from shredded unripe papaya steeped in vinegar, sugar, and salt, where the acid and salt stop spoilage microbes so the food lasts longer.", "bis": "Ang atchara hinimo gikan sa giniris nga hilaw nga kapayas nga gituslob sa suka, asukal, ug asin, diin ang asido ug asin mopugong sa mikrobyo nga makadaot aron molungtad ang pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "atom-bohr-model-g9", "domain": "MATTER", "topic": "Bohr model of the atom", "grades": [8, 9, 10], "terms": ["atom", "atomo", "Bohr model", "nucleus", "nucleo", "electron", "elektron", "proton", "neutron", "orbit", "shell", "antas", "modelo ni Bohr", "umiikot na elektron"], "fact": {"tl": "Sa modelo ni Bohr, ang atom ay may maliit na nucleus na puno ng proton at neutron sa gitna, at umiikot ang mga elektron dito sa tiyak na mga antas o orbit.", "en": "In the Bohr model, the atom has a tiny nucleus of protons and neutrons at the center, with electrons orbiting it in fixed energy levels or shells.", "bis": "Sa modelo ni Bohr, ang atomo adunay gamay nga nucleus nga puno sa proton ug neutron sa tunga, ug ang mga elektron magtuyok niini sa pihong mga ang-ang o orbit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "atomic-model-timeline-g9", "domain": "MATTER", "topic": "history of the atomic model", "grades": [8, 9, 10], "terms": ["atomic model", "modelo ng atomo", "Dalton", "Thomson", "Rutherford", "Bohr", "kasaysayan", "atom", "atomo", "ebolusyon ng modelo", "kausaban", "siyentipiko", "timeline", "modelo sa atomo"], "fact": {"tl": "Ang modelo ng atom ay nagbago sa paglipas ng panahon, mula sa simpleng buong bola ni Dalton, patungo sa 'raisin bread' ni Thomson, sa may nucleus ni Rutherford, hanggang sa may-orbit na modelo ni Bohr.", "en": "The model of the atom changed over time, from Dalton's simple solid ball, to Thomson's 'raisin bread', to Rutherford's nucleus, to Bohr's orbiting-electron model.", "bis": "Ang modelo sa atomo nausab sa paglabay sa panahon, gikan sa yano nga bola ni Dalton, ngadto sa 'raisin bread' ni Thomson, sa adunay nucleus ni Rutherford, hangtod sa adunay-orbit nga modelo ni Bohr."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "baking-soda-box-spoon-g6", "domain": "MATTER", "topic": "baking soda is a base", "grades": [5, 6, 7], "terms": ["baking soda", "sodium bicarbonate", "pampaalsa", "puting pulbo", "base", "suka", "bula", "carbon dioxide", "reaksyon", "luto", "pampaalsa sa tinapay", "puti nga pulbos", "minasa", "soda sa pagluto"], "fact": {"tl": "Ang baking soda ay isang puting pulbos na sodium bicarbonate na isang base, at kapag hinaluan ng asido tulad ng suka, naglalabas ito ng carbon dioxide na nagpapaalsa sa minasa.", "en": "Baking soda is a white powder called sodium bicarbonate that is a base, and when mixed with an acid like vinegar it releases carbon dioxide that makes dough rise.", "bis": "Ang baking soda usa ka puti nga pulbos nga gitawag og sodium bicarbonate nga usa ka base, ug kung isagol sa asido sama sa suka, mobuga kini ug carbon dioxide nga mopaalsa sa minasa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "balloon-inflating-breath-g4", "domain": "MATTER", "topic": "air takes up space in a balloon", "grades": [3, 4, 5], "terms": ["lobo", "balloon", "hangin", "hininga", "umaalsa", "namamaga", "hihip", "air", "gas", "puno ng hangin", "huyop", "pagpaburot", "espasyo", "hangin sa lobo"], "fact": {"tl": "Kapag hinihipan mo ang lobo, ang hangin mula sa iyong baga ay pumupuno at umaabot ng espasyo sa loob, kaya lumalaki at namamaga ang lobo.", "en": "When you blow into a balloon, the air from your lungs fills it and takes up space inside, so the balloon grows bigger and stretches out.", "bis": "Kung huypan nimo ang lobo, ang hangin gikan sa imong baga mopuno ug mokuha ug luna sa sulod, busa modako ug moburot ang lobo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "balloon-static-cling-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "static electricity on a balloon", "grades": [4, 5, 6], "terms": ["lobo", "balloon", "static", "kuryente", "buhok", "dumidikit", "static electricity", "kuskos", "pagkiskis", "charge", "elektrisidad", "nagdidikit", "umaakit", "static nga kuryente"], "fact": {"tl": "Kapag kiniskis mo ang lobo sa iyong buhok, ito ay nagkakaroon ng static na kuryente, kaya nakakadikit ito sa pader o naaakit nito ang maliliit na piraso ng papel.", "en": "When you rub a balloon on your hair, it builds up static electricity, so it can stick to a wall or attract small pieces of paper.", "bis": "Kung ikuskos nimo ang lobo sa imong buhok, makabaton kini ug static nga kuryente, busa makapilit kini sa bongbong o makadani sa gagmay nga papel."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "banana-cue-frying-scene-g6", "domain": "MATTER", "topic": "frying is an irreversible change", "grades": [5, 6, 7], "terms": ["banana cue", "banana-q", "saging", "prito", "pagprito", "init", "mantika", "asukal", "caramel", "irreversible", "hindi na maibabalik", "pagprito sa saging", "lutong saging", "kayumanggi"], "fact": {"tl": "Sa pagprito ng banana cue, ang init ay nagpapaluto sa saging at nagpapakaramelo sa asukal, isang pagbabagong hindi na maibabalik sa dating hilaw na saging.", "en": "When making banana cue, heat cooks the banana and caramelizes the sugar coating, a change that cannot be turned back into the raw banana.", "bis": "Sa pagprito sa banana cue, ang kainit moluto sa saging ug mokaramelo sa asukal, usa ka kausaban nga dili na mabalik ngadto sa hilaw nga saging."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "banana-ripening-color-change-g5", "domain": "LIVING_THINGS", "topic": "fruit ripening color change", "grades": [4, 5, 6], "terms": ["saging", "banana", "hinog", "ripening", "berde", "dilaw", "kulay", "pagkahinog", "matamis", "almirol", "asukal", "naghihinog", "hinog na saging", "nahinog"], "fact": {"tl": "Habang naghihinog ang saging, ang balat nito ay nagbabago mula berde tungo sa dilaw, at ang almirol sa loob ay nagiging asukal kaya nagiging mas matamis ito.", "en": "As a banana ripens, its peel changes from green to yellow, and the starch inside turns into sugar, making it sweeter.", "bis": "Samtang mahinog ang saging, ang panit niini mausab gikan sa lunhaw ngadto sa dilaw, ug ang almidon sa sulod mahimong asukal, mao nga mas motam-is kini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bar-of-laundry-soap-g6", "domain": "MATTER", "topic": "soap lifts away dirt and grease", "grades": [5, 6, 7], "terms": ["sabon", "soap", "labahin", "panlaba", "dumi", "grasa", "tubig", "bula", "naglilinis", "naghuhugas", "sabon sa labada", "labahon", "hugaw", "lana"], "fact": {"tl": "Ang sabon panlaba ay humahawak sa magkabilang dulo ng grasa at tubig, kaya naaalis nito ang langis at dumi sa damit at natatangay ito kasama ng tubig na panghugas.", "en": "Laundry soap grabs onto both grease and water at the same time, so it lifts oil and dirt off clothes and carries them away with the rinse water.", "bis": "Ang sabon sa labada mokupot sa grasa ug tubig dungan, busa makakuha kini sa lana ug hugaw sa sinina ug madala kini uban sa tubig nga ihugas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "basi-fermentation-jar-g7", "domain": "LIVING_THINGS", "topic": "fermentation makes basi wine", "grades": [6, 7, 8], "terms": ["basi", "tubo", "sugarcane", "alak", "fermentation", "lebadura", "asukal", "alkohol", "Ilocos", "pag-asim", "pinaasim", "alak gikan sa tubo", "burong tubo", "tradisyunal na alak"], "fact": {"tl": "Ang basi ay tradisyunal na alak ng Ilocos na gawa sa katas ng tubo, kung saan kinakain ng lebadura ang asukal sa pamamagitan ng fermentation at ginagawa itong alkohol.", "en": "Basi is a traditional Ilocos wine made from sugarcane juice, where yeast eats the sugar through fermentation and turns it into alcohol.", "bis": "Ang basi usa ka tradisyonal nga bino sa Ilocos nga hinimo gikan sa duga sa tubo, diin ang lebadura mokaon sa asukal pinaagi sa fermentation ug mohimo niini nga alkohol."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bibingka-rising-clay-oven-g6", "domain": "MATTER", "topic": "leavening makes bibingka rise", "grades": [5, 6, 7], "terms": ["bibingka", "kakanin", "umaalsa", "pampaalsa", "baking powder", "gas", "init", "rising", "umalsa ang masa", "luto sa pugon", "galapong", "nag-aalsa", "carbon dioxide", "rice cake"], "fact": {"tl": "Ang bibingka ay umaalsa habang niluluto dahil ang pampaalsa rito ay naglalabas ng carbon dioxide na gas, at ang init mula sa baga sa ibabaw at ilalim ang nagpapaluto rito.", "en": "Bibingka rises while cooking because its leavening releases carbon dioxide gas, and heat from the coals above and below cooks it through.", "bis": "Ang bibingka moalsa samtang giluto kay ang pampaalsa niini mobuga ug carbon dioxide nga gas, ug ang kainit gikan sa baga sa ibabaw ug sa ilawom maoy moluto niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "biodegradable-vs-not-g6", "domain": "MATTER", "topic": "biodegradable versus non-biodegradable waste", "grades": [5, 6, 7], "terms": ["biodegradable", "nabubulok", "non-biodegradable", "hindi nabubulok", "basura", "plastik", "dahon", "mikrobyo", "agnas", "madunot", "madunot nga basura", "dili madunot", "kalikasan", "naagnas"], "fact": {"tl": "Ang biodegradable na basura tulad ng dahon at balat ng prutas ay nabubulok at nilalansag ng mga mikrobyo, ngunit ang non-biodegradable tulad ng plastik ay nananatili sa kalikasan nang napakatagal.", "en": "Biodegradable waste like leaves and fruit peels rots and is broken down by microbes, but non-biodegradable trash like plastic stays in the environment for a very long time.", "bis": "Ang biodegradable nga basura sama sa dahon ug panit sa prutas madunot ug gilansang sa mga mikrobyo, apan ang non-biodegradable sama sa plastik magpabilin sa kinaiyahan sa hataas kaayo nga panahon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bleach-stain-removal-g7", "domain": "MATTER", "topic": "bleach removes color by chemical change", "grades": [6, 7, 8], "terms": ["bleach", "kloroks", "mantsa", "stain", "puti", "kulay", "kemikal", "naglilinis", "nagtatanggal ng kulay", "reaksyon", "nawawala ang mantsa", "pagputi", "chemical change", "kolor"], "fact": {"tl": "Ang bleach ay nag-aalis ng mantsa sa pamamagitan ng kemikal na pagbabago na sumisira sa molekula ng kulay, kaya nawawala ang kulay ng mantsa sa damit.", "en": "Bleach removes a stain through a chemical change that breaks apart the color molecules, so the stain's color disappears from the cloth.", "bis": "Ang bleach magtangtang sa mantsa pinaagi sa kemikal nga kausaban nga moguba sa molekula sa kolor, busa mawala ang kolor sa mantsa sa sinina."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bleaching-clothes-soak-g6", "domain": "MATTER", "topic": "soaking clothes in bleach solution", "grades": [5, 6, 7], "terms": ["bleach", "kloroks", "babad", "ibabad", "damit", "puti", "tubig", "solusyon", "naglilinis", "diluted", "natunaw sa tubig", "pagpuputi", "pagpapaputi", "labada"], "fact": {"tl": "Kapag nagbababad ng puting damit sa bleach na hinaluan ng tubig, ang kemikal sa bleach ang dahan-dahang nag-aalis ng mantsa at nagpapaputi ng tela.", "en": "When white clothes are soaked in bleach mixed with water, the chemical in the bleach slowly removes stains and whitens the fabric.", "bis": "Kung ibabad ang puti nga sinina sa bleach nga gisagol sa tubig, ang kemikal sa bleach hinay-hinay nga motangtang sa mantsa ug mopaputi sa panapton."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bond-covalent-g9", "domain": "MATTER", "topic": "covalent chemical bond", "grades": [8, 9, 10], "terms": ["covalent bond", "covalent", "bono", "atomo", "atom", "elektron", "shared", "pinaghahatian", "molekula", "tubig", "nonmetal", "pinanghahatian nga elektron", "kemikal na bono", "pagbahin sa elektron"], "fact": {"tl": "Sa covalent bond, dalawang atomo ang naghahatian ng kanilang mga elektron upang magbuo ng molekula, gaya ng dalawang hydrogen at isang oxygen na nagbubuo ng tubig.", "en": "In a covalent bond, two atoms share their electrons to form a molecule, like two hydrogen atoms and one oxygen forming water.", "bis": "Sa covalent bond, duha ka atomo magbahin sa ilang mga elektron aron maghimo ug molekula, sama sa duha ka hydrogen ug usa ka oxygen nga maghimo ug tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "recyclable-materials-sorting-g5", "domain": "MATTER", "topic": "sorting recyclable materials", "grades": [4, 5, 6], "terms": ["recycle", "recyclable", "basura", "paghihiwalay", "pag-uuri", "papel", "plastik", "bakal", "salamin", "garbage", "sorting", "paper", "plastic", "metal", "glass", "paglahi", "pagrecycle", "sudlanan", "matang"], "fact": {"tl": "Bago i-recycle, pinaghihiwalay ang basura ayon sa uri nito—papel, plastik, metal, at salamin—para mas madaling gawing bagong gamit.", "en": "Before recycling, waste is sorted by type—paper, plastic, metal, and glass—so each kind can more easily be made into new things.", "bis": "Sa dili pa i-recycle, ginalahi ang basura sumala sa matang niini—papel, plastik, metal, ug salamin—aron sayon nga mahimong bag-ong gamit."}, "source": "DepEd MATATAG Science (materials & environment); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "recycle-bins-5r-g5", "domain": "MATTER", "topic": "the 5Rs reduce reuse recycle", "grades": [4, 5, 6], "terms": ["5R", "reduce", "reuse", "recycle", "recover", "refuse", "pagbawas", "muling gamit", "pag-recycle", "basura", "kalikasan", "pagrecycle", "garbage", "waste"], "fact": {"tl": "Ang 5R—Reduce, Reuse, Recycle, Recover, at Refuse—ay mga paraan para bawasan ang basura at protektahan ang kalikasan.", "en": "The 5Rs—Reduce, Reuse, Recycle, Recover, and Refuse—are ways to cut down waste and protect the environment.", "bis": "Ang 5R—Reduce, Reuse, Recycle, Recover, ug Refuse—mga paagi sa pagpakunhod sa basura ug pagpanalipod sa kalikasan."}, "source": "DepEd MATATAG Science (environment & sustainability)", "generator": "claude-workflow", "reviewed": false},
  {"id": "rotting-fruit-on-counter-g5", "domain": "MATTER", "topic": "rotting fruit is a chemical change", "grades": [4, 5, 6], "terms": ["bulok", "nabubulok", "prutas", "pagkabulok", "rotting", "rot", "fruit", "decay", "spoil", "bacteria", "fungi", "amag", "dunot", "nadunot", "pagkadunot", "agup-op", "bakterya"], "fact": {"tl": "Ang prutas na naiwan sa labas ay nabubulok dahil sa mga bakterya at amag na sumisira rito—isang chemical change na hindi na maibabalik.", "en": "Fruit left out rots because bacteria and molds break it down—a chemical change that cannot be reversed.", "bis": "Ang prutas nga gibilin sa gawas mabulok tungod sa bakterya ug agup-op nga moguba niini—usa ka chemical change nga dili na mabalik."}, "source": "AAAS Benchmarks 4D (chemical change); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rust-flaking-corrugated-roof-g6", "domain": "MATTER", "topic": "rust weakens iron roofing", "grades": [5, 6, 7], "terms": ["kalawang", "kinalawang", "bakal", "yero", "bubong", "rust", "rusting", "corrugated", "roof", "iron", "oxygen", "tubig", "moisture", "taya", "gitay-an", "atop", "puthaw"], "fact": {"tl": "Ang kalawang ay nabubuo kapag ang bakal na yero ay nababad sa tubig at hangin, at unti-unti nitong pinanghihina at binubutas ang bubong.", "en": "Rust forms when an iron roof is exposed to water and air, slowly weakening it and eating holes through the metal.", "bis": "Ang taya maporma kung ang puthaw nga atop maladlad sa tubig ug hangin, ug hinay-hinay niining ginapahuyang ug ginabuslotan ang atop."}, "source": "AAAS Benchmarks 4D (chemical change); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rust-formation-nail-jars-g6", "domain": "MATTER", "topic": "rust needs both water and air", "grades": [5, 6, 7], "terms": ["kalawang", "pako", "bakal", "tubig", "hangin", "oxygen", "rust", "nail", "iron", "water", "air", "experiment", "taya", "lansang", "puthaw", "eksperimento", "kinalawang"], "fact": {"tl": "Sa eksperimentong may pako sa magkakaibang garapon, kinakalawang lamang ang pakong nadidikit sa parehong tubig at hangin—kaya kailangan ng dalawa para magkalawang.", "en": "In the nail-in-jars experiment, only the nail touching both water and air rusts—showing rusting needs both together.", "bis": "Sa eksperimento nga lansang sa lain-laing garapon, ang lansang lang nga nahikap sa tubig ug hangin ang motaya—nagpakita nga kinahanglan ang duha aron motaya."}, "source": "AAAS Benchmarks 4D (chemical change); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rust-formation-stages-nail-g6", "domain": "MATTER", "topic": "stages of a nail rusting", "grades": [5, 6, 7], "terms": ["kalawang", "pako", "yugto", "rust", "stages", "nail", "orange", "brown", "flaking", "taya", "lansang", "kahel", "pula", "natutuklap", "namumula", "puthaw"], "fact": {"tl": "Habang kinakalawang ang pako, dahan-dahan itong nagiging kulay-kahel hanggang pula-rusay, at sa bandang huli ay natutuklap na ang ibabaw nito.", "en": "As a nail rusts it slowly turns orange, then reddish-brown, and finally its surface begins to flake away.", "bis": "Samtang motaya ang lansang, hinay-hinay kining mahimong kahel, dayon pula-pula, ug sa kataposan magsugod na pagkatangtang ang ibabaw niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rusting-bolo-blade-g6", "domain": "MATTER", "topic": "preventing rust on a bolo", "grades": [5, 6, 7], "terms": ["kalawang", "itak", "sundang", "bolo", "talim", "langis", "rust", "blade", "oil", "dry", "taya", "lana", "uga", "gipahiran", "puthaw", "talinis", "sulab"], "fact": {"tl": "Para hindi kalawangin ang itak, pinupunasan itong tuyo at pinapahiran ng langis upang harangan ang tubig at hangin sa bakal nitong talim.", "en": "To keep a bolo from rusting, it is wiped dry and rubbed with oil to keep water and air off its iron blade.", "bis": "Aron dili motaya ang sundang, pahiran kini hangtod mauga ug hidhiran og lana aron didili ang tubig ug hangin sa puthaw nga sulab."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sago-pearls-in-drink-g4", "domain": "MATTER", "topic": "sago pearls swell by absorbing water", "grades": [3, 4, 5], "terms": ["sago", "perlas", "inumin", "almirol", "starch", "tubig", "pearls", "drink", "swell", "absorb", "lumaki", "namaga", "nagsipsip", "nagdako", "nagtuhop", "luto", "nagsuyop"], "fact": {"tl": "Ang sago ay gawa sa almirol na galing sa halaman, at lumalaki ito at nagiging malambot kapag nagsisipsip ng tubig habang niluluto.", "en": "Sago pearls are made from plant starch, and they swell up soft and chewy as they soak up water while cooking.", "bis": "Ang sago hinimo gikan sa starch sa tanom, ug modako kini ug mahumok samtang nagsuyop og tubig sa pagluto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sandpaper-sheet-grit-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "sandpaper roughness and friction", "grades": [4, 5, 6], "terms": ["sandpaper", "liha", "gaspang", "magaspang", "friction", "kuskos", "grit", "rough", "smooth", "kinis", "kisaw", "gahi", "pagdaplos", "pino", "hapsay"], "fact": {"tl": "Ang liha ay may magaspang na ibabaw na nagdudulot ng malakas na friction, kaya nakakaalis ito ng pintura at nakapagpapakinis ng kahoy.", "en": "Sandpaper has a rough, gritty surface that creates strong friction, so it can scrape off paint and smooth wood.", "bis": "Ang sandpaper adunay gaspang nga nawong nga naghatag og kusog nga friction, mao nga makakuha kini og pintura ug makapahapsay sa kahoy."}, "source": "NRC PS2.B (forces); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "separate-decantation-g6", "domain": "MATTER", "topic": "separating mixtures by decantation", "grades": [5, 6, 7], "terms": ["dekantasyon", "decantation", "pagsasalin", "paghihiwalay", "halo", "latak", "tubig", "putik", "pour", "settle", "pag-ibo", "pagbubo", "lapok", "nilubog", "mixture", "molugdang"], "fact": {"tl": "Sa dekantasyon, hinahayaang lumubog ang mabibigat na bahagi, pagkatapos ay dahan-dahang isinasalin ang malinaw na likido sa ibabaw para ihiwalay ito.", "en": "In decantation, the heavier solid is left to settle, then the clear liquid on top is carefully poured off to separate them.", "bis": "Sa decantation, pasagdan nga molugdang ang bug-at nga bahin, dayon hinay-hinay nga ibubo ang tin-aw nga likido sa ibabaw aron mabulag."}, "source": "DepEd MATATAG Science (separating mixtures); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "separate-evaporation-g6", "domain": "MATTER", "topic": "separating a dissolved solid by evaporation", "grades": [5, 6, 7], "terms": ["evaporation", "pagsingaw", "asin", "tubig", "natunaw", "dissolved", "salt", "water", "boil", "init", "nalanay", "pagpainit", "natuyo", "mixture", "paghiwalay", "mabilin"], "fact": {"tl": "Para ihiwalay ang natunaw na asin sa tubig, pinapainit ang halo hanggang sumingaw ang tubig at maiwan ang asin.", "en": "To separate dissolved salt from water, the mixture is heated until the water evaporates and only the salt is left.", "bis": "Aron mabulag ang natunaw nga asin gikan sa tubig, painiton ang sagol hangtod mosingaw ang tubig ug mabilin ang asin."}, "source": "DepEd MATATAG Science (separating mixtures); NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "separate-filtering-g5", "domain": "MATTER", "topic": "separating mixtures by filtering", "grades": [4, 5, 6], "terms": ["pagsasala", "salaan", "filter", "filtering", "tubig", "buhangin", "solid", "liquid", "papel", "pagsala", "ayagan", "balas", "lusot", "mixture", "paghiwalay", "buslot"], "fact": {"tl": "Sa pagsasala, dumadaan ang likido sa maliliit na butas ng salaan habang naiiwan ang mga solidong hindi kasya, gaya ng buhangin sa tubig.", "en": "In filtering, the liquid passes through tiny holes while solids too big to fit are left behind, like sand from water.", "bis": "Sa pagsala, moagi ang likido sa gagmayng buslot sa salaan samtang mabilin ang solido nga dili mosulod, sama sa balas gikan sa tubig."}, "source": "DepEd MATATAG Science (separating mixtures); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "separate-magnet-g5", "domain": "MATTER", "topic": "separating iron with a magnet", "grades": [4, 5, 6], "terms": ["magnet", "bakal", "paghihiwalay", "iron", "magnetic", "halo", "buhangin", "attract", "humila", "puthaw", "magnetiko", "balas", "nadani", "pagbira", "mixture", "paghiwalay", "birahon"], "fact": {"tl": "Magagamit ang magnet para ihiwalay ang bakal sa halo, dahil hinihila nito ang bakal samtang naiiwan ang ibang materyales.", "en": "A magnet can separate iron from a mixture because it pulls the iron bits out while leaving the other materials behind.", "bis": "Magamit ang magnet aron mabulag ang puthaw gikan sa sagol, kay birahon niini ang puthaw samtang mabilin ang ubang materyales."}, "source": "DepEd MATATAG Science (separating mixtures); NRC PS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "separate-sieving-g5", "domain": "MATTER", "topic": "separating by sieving", "grades": [3, 4, 5], "terms": ["pagsasala", "ayagan", "bistay", "sieve", "sieving", "harina", "buhangin", "laki", "magaspang", "size", "ayag", "balas", "gidak-on", "mixture", "paghiwalay", "mahulog"], "fact": {"tl": "Sa pag-ayag, dumadaan sa maliliit na butas ang pinong butil habang naiiwan ang mas malalaking piraso, kaya nahihiwalay sila ayon sa laki.", "en": "In sieving, fine bits fall through small holes while bigger pieces stay on top, separating them by size.", "bis": "Sa pag-ayag, mahulog sa gagmayng buslot ang pino nga bahin samtang mabilin ang dagkong piraso, busa mabulag sila sumala sa gidak-on."}, "source": "DepEd MATATAG Science (separating mixtures); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "separating-iron-sulfur-mixture-g7", "domain": "MATTER", "topic": "iron and sulfur mixture vs compound", "grades": [7, 8, 9], "terms": ["bakal", "asupre", "sulfur", "iron", "magnet", "halo", "mixture", "compound", "pinaghalo", "paghihiwalay", "puthaw", "sagol", "kombinasyon", "elemento", "element"], "fact": {"tl": "Kapag pinaghalo lang ang bakal at asupre, mahihiwalay pa rin sila gamit ang magnet dahil pisikal na halo lamang ito, hindi pa bagong sangkap.", "en": "When iron and sulfur are merely mixed, a magnet can still pull out the iron because it is only a physical mixture, not a new compound.", "bis": "Kung sagolon lang ang puthaw ug asupre, mabulag gihapon sila pinaagi sa magnet kay pisikal nga sagol lang kini, dili pa bag-ong compound."}, "source": "NRC PS1.A/PS1.B (mixtures vs compounds); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "separation-distillation-g7", "domain": "MATTER", "topic": "separating liquids by distillation", "grades": [6, 7, 8], "terms": ["distilasyon", "distillation", "pagsingaw", "pag-condense", "singaw", "evaporate", "condense", "boiling point", "purong tubig", "alisngaw", "pagbalik likido", "tubig", "pabukalon", "palamigon"], "fact": {"tl": "Sa distilasyon, pinakukulo ang halo para sumingaw ang isang likido, pagkatapos ay pinalalamig ang singaw upang maging purong likido muli.", "en": "In distillation, a mixture is boiled so one liquid evaporates, then the vapor is cooled back into a pure liquid.", "bis": "Sa distillation, pabukalon ang sagol aron mosingaw ang usa ka likido, dayon palamigon ang aso aron mahimong putli nga likido pag-usab."}, "source": "NRC PS1.A (separating mixtures); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "settling-rice-wash-water-g4", "domain": "MATTER", "topic": "settling solids in rice-wash water", "grades": [3, 4, 5], "terms": ["hugas-bigas", "pinaghugasan", "settling", "paglubog", "latak", "rice wash", "settle", "tubig", "malabo", "nilinaw", "hugas-bugas", "lugdang", "tin-aw", "molugdang", "sediment"], "fact": {"tl": "Kapag hinayaang manatili ang maputlang hugas-bigas, dahan-dahang lumulubog sa ilalim ang mga maliliit na butil at lumilinaw ang tubig sa itaas.", "en": "If cloudy rice-wash water is left to stand, the tiny bits slowly settle to the bottom and the water above turns clear.", "bis": "Kung pasagdan ang hugas-bugas nga lubog, hinay-hinay nga molugdang sa ilalom ang gagmayng bahin ug motin-aw ang tubig sa ibabaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "silver-tarnishing-g6", "domain": "MATTER", "topic": "silver tarnishing is a chemical change", "grades": [5, 6, 7], "terms": ["pilak", "silver", "nangingitim", "tarnish", "tarnishing", "sulfur", "hangin", "chemical change", "umitim", "nangitngit", "nagdulom", "asupre", "metal", "moitom"], "fact": {"tl": "Ang pilak ay nangingitim o nagiging madilim kapag ito ay tumagal sa hangin, dahil tumutugon ito sa sulfur—isang uri ng chemical change.", "en": "Silver tarnishes and turns dark over time because it reacts with sulfur in the air—a kind of chemical change.", "bis": "Ang pilak mangitngit o moitom kon dugay na sa hangin, kay motubag kini sa sulfur sa hangin—usa ka matang sa chemical change."}, "source": "AAAS Benchmarks 4D (chemical change); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "single-replacement-reaction-g9", "domain": "MATTER", "topic": "single replacement reaction", "grades": [8, 9, 10], "terms": ["single replacement", "reaksyong kemikal", "chemical reaction", "metal", "displace", "kompound", "nagpapalit", "reaksyon", "nagpuli", "elemento", "element", "displacement", "mopuli", "tanso", "tumbaga"], "fact": {"tl": "Sa single replacement reaction, ang isang mas aktibong elemento ay pumapalit sa ibang elemento sa loob ng isang kompound, gaya ng bakal na pumapalit sa tanso sa isang solusyon.", "en": "In a single replacement reaction, a more reactive element takes the place of another element in a compound, like iron displacing copper from a solution.", "bis": "Sa single replacement reaction, ang mas aktibo nga elemento mopuli sa laing elemento sulod sa usa ka compound, sama sa puthaw nga mopuli sa tumbaga gikan sa solusyon."}, "source": "encyclopedia-stable consensus (chemistry)", "generator": "claude-workflow", "reviewed": false},
  {"id": "soap-grease-cleaning-action-g6", "domain": "MATTER", "topic": "how soap removes grease", "grades": [5, 6, 7], "terms": ["sabon", "soap", "mantika", "grease", "langis", "tubig", "naghuhugas", "molecule", "naghihiwalay", "naglilinis", "tambok", "lana", "molekula", "detergent", "mokupot"], "fact": {"tl": "Ang sabon ay may bahaging dumidikit sa langis at bahaging dumidikit sa tubig, kaya naitatangay nito ang mantika palayo sa kamay o pinggan.", "en": "Soap has one part that grabs onto grease and another that grabs onto water, so it can lift oil away from your hands or dishes.", "bis": "Ang sabon adunay bahin nga mokupot sa lana ug bahin nga mokupot sa tubig, busa makahakwat kini sa tambok gikan sa kamot o plato."}, "source": "encyclopedia-stable consensus (chemistry)", "generator": "claude-workflow", "reviewed": false},
  {"id": "soap-making-process-g7", "domain": "MATTER", "topic": "soap is made by saponification", "grades": [6, 7, 8], "terms": ["sabon", "soap", "saponification", "langis", "lye", "lihiya", "taba", "reaksyon", "gawa", "ginawa", "lana", "tambok", "gibuhat", "chemical reaction", "base"], "fact": {"tl": "Ang sabon ay ginagawa sa pamamagitan ng paghahalo ng taba o langis sa isang malakas na base na tinatawag na lihiya, sa prosesong kemikal na saponification.", "en": "Soap is made by reacting fat or oil with a strong base called lye, in a chemical process called saponification.", "bis": "Ang sabon gihimo pinaagi sa pagsagol sa tambok o lana ngadto sa kusog nga base nga gitawag og lihiya, sa kemikal nga proseso nga saponification."}, "source": "encyclopedia-stable consensus (chemistry)", "generator": "claude-workflow", "reviewed": false},
  {"id": "soda-going-flat-comparison-g5", "domain": "MATTER", "topic": "soda goes flat as gas escapes", "grades": [4, 5, 6], "terms": ["softdrink", "soda", "bula", "carbon dioxide", "gas", "flat", "naglalabas", "bumubula", "tumakas", "lumipas", "nawala", "fizz", "mokalagiw", "walay bula"], "fact": {"tl": "Ang softdrink ay may natunaw na carbon dioxide na gas; kapag bukas ito nang matagal, tumatakas ang gas at nagiging walang bula o flat na.", "en": "Soda has carbon dioxide gas dissolved in it; left open too long, the gas escapes and the drink goes flat.", "bis": "Ang softdrink adunay natunaw nga carbon dioxide nga gas; kon abli na og dugay, mokalagiw ang gas ug mahimong walay bula o flat na."}, "source": "NRC PS1.A (gases & solutions); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "soured-rice-spoiled-g4", "domain": "MATTER", "topic": "rice spoils when bacteria grow", "grades": [3, 4, 5], "terms": ["kanin", "panis", "naasim", "bulok", "rice", "spoiled", "sour", "bacteria", "warm", "kanon", "napan-os", "naaslom", "bakterya", "init", "pagkadunot", "spoil", "moaslom"], "fact": {"tl": "Ang kaning naiwan sa init ay napapanis at naaasim dahil dumarami rito ang mga bakteryang sumisira sa pagkain.", "en": "Rice left in the warmth turns sour and spoils because food-spoiling bacteria multiply in it.", "bis": "Ang kanon nga gibilin sa init mapan-os ug moaslom kay modaghan didto ang bakterya nga moguba sa pagkaon."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks 4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "souring-milk-curdling-g5", "domain": "MATTER", "topic": "milk curdles when it sours", "grades": [4, 5, 6], "terms": ["gatas", "milk", "namuo", "curdle", "naasim", "sour", "bakterya", "asido", "lactic acid", "buo", "naaslom", "namug-ot", "spoil", "protina", "mamuo"], "fact": {"tl": "Kapag naaasim ang gatas, gumagawa ang mga bakterya ng asido na nagpapamuo sa proteina nito, kaya ito namumuo at nagiging buo-buo.", "en": "When milk sours, bacteria make acid that clumps its protein, so the milk curdles into lumps.", "bis": "Kon moaslom ang gatas, ang bakterya maghimo og asido nga magpamuo sa protina niini, busa mamuo kini og tinipik."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks 4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "state-sort-chart-g4", "domain": "MATTER", "topic": "three states of matter solid liquid gas", "grades": [3, 4, 5], "terms": ["estado ng bagay", "solid", "likido", "gas", "states of matter", "solido", "buo", "tubig", "hangin", "pag-uuri", "kahimtang sa butang", "uri", "matter", "modagayday"], "fact": {"tl": "Ang mga bagay ay maaaring iuri sa tatlong estado—solido na may sariling hugis, likido na umaagos, at gas na kumakalat upang punuin ang lalagyan.", "en": "Matter can be sorted into three states—solids that hold their shape, liquids that flow, and gases that spread to fill their container.", "bis": "Ang mga butang mahimong bahinon sa tulo ka kahimtang—solido nga adunay kaugalingong porma, likido nga modagayday, ug gas nga mokatag aron mapuno ang sudlanan."}, "source": "NRC PS1.A; DepEd MATATAG Science (states of matter)", "generator": "claude-workflow", "reviewed": false},
  {"id": "steam-from-rice-pot-g4", "domain": "MATTER", "topic": "steam is water vapor from boiling", "grades": [3, 4, 5], "terms": ["singaw", "usok", "kanin", "tubig", "kumukulo", "steam", "vapor", "boiling", "evaporation", "init", "alisngaw", "aso", "kanon", "nagbukal", "water vapor", "tulo"], "fact": {"tl": "Ang puting singaw sa kumukulong palayok ng kanin ay water vapor—tubig na naging gas dahil sa init—na muling lumalamig pabalik sa maliliit na patak.", "en": "The white steam over a boiling rice pot is water vapor—water turned to gas by heat—cooling back into tiny droplets.", "bis": "Ang puti nga singaw sa nagbukal nga kolon sa kanon usa ka water vapor—tubig nga nahimong gas tungod sa init—nga mobalik og lamig ngadto sa gagmayng tulo."}, "source": "NRC PS1.A (states & phase change); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "steeping-tea-diffusion-g5", "domain": "MATTER", "topic": "tea color spreads by diffusion", "grades": [4, 5, 6], "terms": ["tsaa", "tea", "diffusion", "pagkalat", "kulay", "tubig", "lumalaganap", "steep", "namamahagi", "kape", "pagkatag", "kolor", "milukop", "mikatag", "dissolve", "mokatag"], "fact": {"tl": "Kapag ibinabad ang tsaa sa mainit na tubig, kumakalat ang kulay at lasa nito sa buong tubig sa pamamagitan ng diffusion.", "en": "When tea steeps in hot water, its color and flavor spread evenly through the water by diffusion.", "bis": "Kon itunlob ang tsaa sa init nga tubig, mokatag ang kolor ug lami niini sa tibuok tubig pinaagi sa diffusion."}, "source": "NRC PS1.A (particles & diffusion); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "straining-gata-coconut-milk-g4", "domain": "MATTER", "topic": "straining coconut milk separates pulp", "grades": [3, 4, 5], "terms": ["gata", "niyog", "pagsasala", "coconut milk", "straining", "sapal", "katas", "buko", "salaan", "lubi", "pagsala", "tuno", "pagpuga", "filter", "kinudkod", "kinudkod"], "fact": {"tl": "Para makuha ang gata, sinasala ang pinigang kinudkod na niyog upang ihiwalay ang malabnaw na katas sa magaspang na sapal.", "en": "To get coconut milk, the grated coconut is strained to separate the smooth white liquid from the coarse pulp.", "bis": "Aron makuha ang gata, sagaon ang gigaling nga lubi aron mabulag ang humok nga tuno gikan sa gaspang nga sapal."}, "source": "DepEd MATATAG Science (separating mixtures); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "subatomic-particles-g8", "domain": "MATTER", "topic": "protons neutrons and electrons", "grades": [7, 8, 9], "terms": ["atomo", "atom", "proton", "neutron", "electron", "subatomic", "nucleus", "nukleus", "charge", "karga", "tunga", "nukleyo", "partikulo", "particle"], "fact": {"tl": "Ang atomo ay binubuo ng tatlong pangunahing partikulo—proton na positibo at neutron na walang karga sa nucleus, at electron na negatibo sa paligid nito.", "en": "An atom is made of three main particles—positive protons and neutral neutrons in the nucleus, and negative electrons around it.", "bis": "Ang atomo gilangkoban og tulo ka nag-unang partikulo—positibo nga proton ug walay karga nga neutron sa nucleus, ug negatibo nga electron sa palibot niini."}, "source": "NRC PS1.A (structure of matter); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sublimation-camphor-g6", "domain": "MATTER", "topic": "sublimation of camphor", "grades": [6, 7, 8], "terms": ["alkampor", "kamper", "sublimasyon", "solid tungo sa gas", "sublimation", "camphor", "mothball", "naga-sublime", "nahimong alisngaw", "alimyon"], "fact": {"tl": "Ang alkampor o kamper ay maaaring direktang maging singaw mula sa solido nang hindi muna nagiging likido, isang prosesong tinatawag na sublimasyon.", "en": "Camphor can turn directly from a solid into a gas without first becoming a liquid, a process called sublimation.", "bis": "Ang kamper mahimong moalisngaw direkta gikan sa gahi nga porma nga dili una mahimong likido, usa ka proseso nga gitawag og sublimation."}, "source": "NRC PS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "substance-vs-mixture-particles-g6", "domain": "MATTER", "topic": "pure substance versus mixture", "grades": [5, 6, 7], "terms": ["purong sangkap", "halo", "haluang", "substansya", "timpla", "pure substance", "mixture", "elemento", "compound", "managsama nga partikulo", "sagol", "lainlain nga partikulo"], "fact": {"tl": "Ang purong sangkap ay gawa sa iisang uri ng particle, samantalang ang halo ay binubuo ng dalawa o higit pang magkakaibang sangkap na pisikal na pinagsama.", "en": "A pure substance is made of only one kind of particle, while a mixture contains two or more different substances physically combined.", "bis": "Ang putli nga sangkap hinimo sa usa lang ka matang nga partikulo, samtang ang sagol naglangkob og duha o labaw pa ka lainlaing sangkap nga pisikal nga gisagol."}, "source": "NRC PS1.A; AAAS Benchmarks", "generator": "claude-workflow", "reviewed": false},
  {"id": "sugar-caramelizing-pan-g7", "domain": "MATTER", "topic": "caramelization of sugar", "grades": [6, 7, 8], "terms": ["asukal", "caramel", "karamelo", "nagkakaramelo", "pagkulay-kayumanggi", "caramelizing", "caramelization", "init", "kaldero", "nag-init nga asukal", "browning", "nahimong brown"], "fact": {"tl": "Kapag pinainit ang asukal hanggang matunaw at mag-kayumanggi, nagbabago ang kemikal nito at lumilikha ng bagong lasa at amoy—isang halimbawa ng pagbabagong kemikal.", "en": "When sugar is heated until it melts and turns brown, its chemicals change to make new flavors and smells—an example of a chemical change.", "bis": "Kon ang asukal initon hangtod matunaw ug mahimong brown, mausab ang kemikal niini ug maghimo og bag-ong lami ug baho—usa ka pananglitan sa kemikal nga pagbag-o."}, "source": "NRC PS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sugar-stirred-into-coffee-g4", "domain": "MATTER", "topic": "dissolving sugar in water", "grades": [3, 4, 5], "terms": ["asukal", "kape", "natutunaw", "nadidissolve", "solusyon", "halo", "dissolve", "solution", "stirring", "hinalo", "natunaw", "matunaw sa tubig", "solute"], "fact": {"tl": "Kapag hinalo ang asukal sa mainit na kape, natutunaw ito at kumakalat ang mga particle nito sa buong inumin, kaya nagiging matamis ang bawat patak.", "en": "When sugar is stirred into hot coffee it dissolves, spreading its particles all through the drink so every sip tastes sweet.", "bis": "Kon kutawon ang asukal sa init nga kape, matunaw kini ug mokatag ang mga partikulo niini sa tibuok ilimnon, busa matam-is ang matag higop."}, "source": "NRC PS1.A; DepEd G4", "generator": "claude-workflow", "reviewed": false},
  {"id": "suspension-muddy-water-g6", "domain": "MATTER", "topic": "suspension in muddy water", "grades": [5, 6, 7], "terms": ["maputik na tubig", "putik", "suspension", "lumulutang na particle", "lumalapag", "settle", "muddy water", "lapok", "nagalutaw nga lapok", "molugdang", "sediment", "namuo"], "fact": {"tl": "Ang maputik na tubig ay isang suspension—nakalutang ang maliliit na particle ng lupa na unti-unting lumalapag sa ilalim kapag pinabayaan.", "en": "Muddy water is a suspension—tiny soil particles float in it and slowly settle to the bottom if left undisturbed.", "bis": "Ang lapok nga tubig usa ka suspension—naglutaw ang gagmayng partikulo sa yuta nga hinayhinay nga molugdang sa ubos kon pasagdan."}, "source": "NRC PS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "synthesis-reaction-combine-g8", "domain": "MATTER", "topic": "synthesis (combination) reaction", "grades": [8, 9, 10], "terms": ["synthesis reaction", "combination reaction", "pagsasama", "reaksyong kemikal", "bagong sangkap", "pinagsama", "combine", "reactant", "produkto", "gisagol", "bag-ong compound", "nag-react"], "fact": {"tl": "Sa isang synthesis o combination reaction, dalawa o higit pang sangkap ang nagsasama upang bumuo ng iisang bagong compound, gaya ng hydrogen at oxygen na nagiging tubig.", "en": "In a synthesis or combination reaction, two or more substances join to form a single new compound, such as hydrogen and oxygen forming water.", "bis": "Sa synthesis o combination reaction, duha o labaw pa ka sangkap ang magtipon aron maghimo og usa ka bag-ong compound, sama sa hydrogen ug oxygen nga mahimong tubig."}, "source": "NRC PS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tarnished-silver-spoon-g7", "domain": "MATTER", "topic": "tarnishing of silver", "grades": [6, 7, 8], "terms": ["pilak", "kutsara", "nangingitim", "tarnish", "tarnished", "silver", "kemikal na reaksyon", "sulfur", "naitim", "silver sulfide", "nangitngit nga plata", "kalawang sa plata"], "fact": {"tl": "Nangingitim ang pilak na kutsara kapag ang pilak ay nakikipagreaksyon sa sulfur sa hangin, na bumubuo ng manipis na itim na silver sulfide—isang pagbabagong kemikal.", "en": "A silver spoon darkens because the silver reacts with sulfur in the air, forming a thin black layer of silver sulfide—a chemical change.", "bis": "Mongitngit ang plata nga kutsara tungod kay ang plata mo-react sa sulfur sa hangin, nga maghimo og nipis nga itom nga silver sulfide—usa ka kemikal nga pagbag-o."}, "source": "NRC PS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tawas-alum-crystal-g6", "domain": "MATTER", "topic": "alum (tawas) crystals", "grades": [5, 6, 7], "terms": ["tawas", "alum", "kristal", "crystal", "deodorant", "naglilinaw ng tubig", "potassium alum", "kristal nga tawas", "nagahimo og kristal", "naglinis ug tubig", "panghugas"], "fact": {"tl": "Ang tawas ay isang natural na kristal (potassium alum) na ginagamit ng mga Pilipino bilang panlinis ng baho at pampalinaw ng maputik na tubig.", "en": "Tawas is a natural crystal (potassium alum) that Filipinos use as a deodorant and to clear cloudy water by making dirt clump and settle.", "bis": "Ang tawas usa ka natural nga kristal (potassium alum) nga gamiton sa mga Pilipino isip pangwala og baho ug pangtin-aw sa lapok nga tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "titration-setup-burette-g10", "domain": "MATTER", "topic": "acid-base titration", "grades": [9, 10], "terms": ["titration", "burette", "buret", "asido", "base", "indicator", "neutralisasyon", "pagsukat ng konsentrasyon", "pagtulo", "titrasyon", "neutral", "pagsukod sa asido"], "fact": {"tl": "Sa titration, dahan-dahang idinadagdag ang isang solusyon mula sa burette papunta sa isa pa hanggang ganap silang mag-neutralisa, upang masukat ang konsentrasyon ng asido o base.", "en": "In titration, one solution is slowly added from a burette into another until they exactly neutralize, letting us measure how concentrated an acid or base is.", "bis": "Sa titration, hinayhinay nga idugang ang usa ka solusyon gikan sa burette ngadto sa lain hangtod sila hingpit nga mag-neutralisa, aron masukod kon unsa kakusog ang asido o base."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "toasting-bread-maillard-g7", "domain": "MATTER", "topic": "Maillard browning of toast", "grades": [6, 7, 8], "terms": ["tinapay", "toast", "tinusta", "nagba-brown", "Maillard", "init", "kemikal na reaksyon", "amino acid", "asukal", "kayumanggi", "nagbrown nga pan", "gisanlag", "bag-ong lami"], "fact": {"tl": "Kapag tinutusta ang tinapay, ang init ay nagdudulot ng reaksyon sa pagitan ng asukal at protina (Maillard reaction) na nagbibigay ng kayumanggi nitong kulay at masarap na amoy.", "en": "When bread is toasted, heat triggers a reaction between its sugars and proteins (the Maillard reaction) that gives it a brown color and tasty smell.", "bis": "Kon sanglagon ang pan, ang init magpahinabog reaksyon tali sa asukal ug protina (Maillard reaction) nga maghatag sa brown nga kolor ug lami nga baho niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tuba-fermentation-bamboo-g8", "domain": "MATTER", "topic": "fermentation of tuba (coconut sap)", "grades": [7, 8, 9], "terms": ["tuba", "fermentation", "pagbuburo", "lebadura", "yeast", "katas ng niyog", "alkohol", "kawayan", "coconut sap", "napermenta", "alak", "namugna nga alkohol", "tubâ"], "fact": {"tl": "Ang tuba ay gawa mula sa katas ng puno ng niyog na pinapalaki ng lebadura sa pamamagitan ng fermentation, na nagbabago ng asukal tungo sa alkohol.", "en": "Tuba is made from coconut palm sap that yeast ferments, changing its sugars into alcohol.", "bis": "Ang tuba hinimo gikan sa duga sa lubi nga gipa-ferment sa lebadura, nga magbalhin sa asukal ngadto sa alkohol."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tyndall-effect-flashlight-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "Tyndall effect (scattering of light)", "grades": [7, 8, 9], "terms": ["Tyndall effect", "kalat ng liwanag", "flashlight", "kolloid", "usok", "scattering", "sinag", "ilaw", "kolloid nga partikulo", "naglatag nga suga", "nakita nga sinag", "abog"], "fact": {"tl": "Kapag dumaan ang sinag ng flashlight sa usok o gatas na may tubig, nagiging kita ang daan ng liwanag dahil ikinakalat ito ng maliliit na particle—tinatawag itong Tyndall effect.", "en": "When a flashlight beam passes through smoke or milky water, its path becomes visible because tiny particles scatter the light—this is the Tyndall effect.", "bis": "Kon ang suga sa flashlight moagi sa aso o gatas nga tubig, makita ang agianan sa kahayag tungod kay gikatag kini sa gagmayng partikulo—gitawag kini og Tyndall effect."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "vinegar-fermentation-jar-scene-g8", "domain": "MATTER", "topic": "vinegar fermentation in a jar", "grades": [7, 8, 9], "terms": ["suka", "vinegar", "fermentation", "pagbuburo", "bakterya", "acetic acid", "alkohol", "garapon", "asido", "napermenta nga suka", "asido nga aseti", "bacteria"], "fact": {"tl": "Ang suka ay nabubuo kapag pinapayagan ang bakterya na palitan ang alkohol sa fermenting na likido patungong acetic acid, na siyang nagbibigay ng maasim nitong lasa.", "en": "Vinegar forms when bacteria turn the alcohol in a fermenting liquid into acetic acid, which gives vinegar its sour taste.", "bis": "Ang suka maporma kon ang bakterya magbalhin sa alkohol sa nag-ferment nga likido ngadto sa acetic acid, nga maoy nagahatag sa aslom nga lami niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "vinegar-making-suka-fermentation-g6", "domain": "MATTER", "topic": "making suka (Filipino vinegar)", "grades": [5, 6, 7], "terms": ["suka", "paggawa ng suka", "vinegar", "fermentation", "tuba", "niyog", "tubo", "naga-suka", "maasim", "fermented", "paghimo og suka", "katas", "aslom"], "fact": {"tl": "Sa Pilipinas, ang suka ay madalas gawa mula sa fermented na katas ng niyog, tubo, o nipa, kung saan unti-unting nagiging maasim ang likido sa loob ng ilang linggo.", "en": "In the Philippines, suka (vinegar) is often made from fermented coconut, sugarcane, or nipa sap, which slowly turns sour over several weeks.", "bis": "Sa Pilipinas, ang suka kasagarang hinimo gikan sa fermented nga duga sa lubi, tubo, o nipa, nga hinayhinay nga mahimong aslom sulod sa pipila ka semana."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "vsepr-shapes-g10", "domain": "MATTER", "topic": "molecular shapes (VSEPR)", "grades": [9, 10], "terms": ["VSEPR", "hugis ng molekula", "molecular shape", "electron pair", "bond", "geometry", "nagtatabuyan", "molekula", "porma sa molekula", "electron", "naglikay", "linear", "bent"], "fact": {"tl": "Ayon sa VSEPR, ang mga pares ng electron sa paligid ng isang atom ay nagtatabuyan at lumalayo sa isa't isa, kaya nakukuha natin ang tatlong-dimensyong hugis ng isang molekula.", "en": "According to VSEPR theory, the electron pairs around an atom push apart as far as possible, which gives a molecule its three-dimensional shape.", "bis": "Sumala sa VSEPR, ang mga paris sa electron palibot sa usa ka atom mag-abog ug magpalayo sa usag usa, busa makuha nato ang tulo-ka-dimensyon nga porma sa usa ka molekula."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-filter-buko-shell-sand-g5", "domain": "MATTER", "topic": "simple water filtration", "grades": [4, 5, 6], "terms": ["salaan ng tubig", "water filter", "buhangin", "buko shell", "uling", "pagsala", "filtration", "malinis na tubig", "dumi", "balas", "pagsala sa tubig", "tin-aw nga tubig", "gisala"], "fact": {"tl": "Ang isang simpleng salaan na gawa sa buhangin, uling, at balat ng buko ay nakakaalis ng putik at maliliit na dumi sa tubig sa pamamagitan ng pagsala (filtration).", "en": "A simple filter of sand, charcoal, and coconut shell removes mud and tiny bits of dirt from water by trapping the particles as the water passes through.", "bis": "Ang yano nga salaan nga hinimo sa balas, uling, ug bagol sa lubi makakuha sa lapok ug gagmayng hugaw sa tubig pinaagi sa pagsala (filtration)."}, "source": "NRC PS1.A; DepEd G5", "generator": "claude-workflow", "reviewed": false},
  {"id": "wax-paper-candle-soot-g6", "domain": "MATTER", "topic": "soot from incomplete combustion", "grades": [6, 7, 8], "terms": ["uling", "soot", "kandila", "agiw", "incomplete combustion", "pagkasunog", "carbon", "itim na usok", "apoy", "dili hingpit nga pagkasunog", "itom nga agiw", "carbon nga abo"], "fact": {"tl": "Ang itim na agiw mula sa kandila ay carbon na nabuo kapag hindi ganap na nasunog ang kandilang waks dahil sa kakulangan ng oxygen (incomplete combustion).", "en": "The black soot from a candle is carbon that forms when the candle wax does not burn completely because there is not enough oxygen.", "bis": "Ang itom nga agiw gikan sa kandila kay carbon nga maporma kon ang kandila nga taro dili hingpit nga masunog tungod sa kakulang sa oxygen."}, "source": "NRC PS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "yeast-balloon-co2-experiment-g6", "domain": "MATTER", "topic": "yeast producing carbon dioxide", "grades": [5, 6, 7], "terms": ["lebadura", "yeast", "lobo", "balloon", "carbon dioxide", "asukal", "fermentation", "gas", "lumobo", "namuga nga gas", "namaga nga lobo", "naghimo og gas", "CO2"], "fact": {"tl": "Kapag pinakain ng asukal ang lebadura, lumilikha ito ng carbon dioxide na gas na maaaring magpalobo ng lobo na nakakabit sa bote—patunay na ang lebadura ay buhay.", "en": "When yeast is fed sugar it gives off carbon dioxide gas, which can inflate a balloon on a bottle—showing that yeast is alive.", "bis": "Kon pakan-on og asukal ang lebadura, mohimo kini og carbon dioxide nga gas nga makapahubag sa lobo nga gitaod sa botelya—nagpamatuod nga buhi ang lebadura."}, "source": "NRC LS1.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "amihan-cool-breeze-scene-g5", "domain": "EARTH_SPACE", "topic": "amihan (northeast monsoon)", "grades": [4, 5, 6], "terms": ["amihan", "hangin", "malamig na hangin", "northeast monsoon", "tag-lamig", "cool breeze", "habagat", "panahon", "bugnaw nga hangin", "ulan", "Disyembre", "klima", "habagat amihan"], "fact": {"tl": "Ang amihan ay ang malamig at tuyong hanging humihihip mula sa hilagang-silangan sa Pilipinas tuwing Nobyembre hanggang Pebrero, na nagdadala ng malamig na panahon.", "en": "The amihan is the cool, dry wind that blows from the northeast over the Philippines from about November to February, bringing cooler weather.", "bis": "Ang amihan mao ang bugnaw ug uga nga hangin nga mohuyop gikan sa amihanan-sidlakan sa Pilipinas gikan Nobyembre hangtod Pebrero, nga magdala og bugnaw nga panahon."}, "source": "PAGASA; DepEd G5 Earth Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "anvil-cloud-storm-top-g7", "domain": "EARTH_SPACE", "topic": "anvil top of a thunderstorm cloud", "grades": [6, 7, 8], "terms": ["ulap", "cumulonimbus", "anvil cloud", "bagyo", "kulog", "kidlat", "thunderstorm", "ulap na parang palihan", "panganod", "unos", "tumampok nga panganod", "dag-om", "bagyong ulap"], "fact": {"tl": "Ang patag na tuktok na parang palihan ng isang malaking cumulonimbus na ulap ay nabubuo kapag ang umaakyat na hangin ay umabot na sa taas na hindi na ito makakaakyat pa.", "en": "The flat, anvil-shaped top of a tall thunderstorm cloud forms where the rising air reaches a height it can no longer climb above and spreads sideways.", "bis": "Ang patag, sama-sa-palihan nga tumoy sa taas nga cumulonimbus nga panganod maporma kon ang nagsaka nga hangin moabot sa gihabogon nga dili na kini makasaka ug mokatag sa kilid."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ash-cloud-eruption-column-g7", "domain": "EARTH_SPACE", "topic": "volcanic ash eruption column", "grades": [6, 7, 8], "terms": ["bulkan", "pagputok", "ash cloud", "abo", "eruption", "volcano", "haligi ng abo", "lava", "Pinatubo", "PHIVOLCS", "buga sa bulkan", "abog sa bulkan", "ash column"], "fact": {"tl": "Kapag pumutok ang isang bulkan, maaari itong magpaitaas ng matarik na haligi ng mainit na abo, gas, at bato pataas sa himpapawid nang ilang kilometro.", "en": "When a volcano erupts, it can blast a towering column of hot ash, gas, and rock several kilometers up into the sky.", "bis": "Kon mobuto ang usa ka bulkan, mahimo kining mobuga og taas nga haligi sa init nga abo, gas, ug bato paingon sa kawanangan og pipila ka kilometro."}, "source": "PHIVOLCS; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "asteroid-tumbling-g6", "domain": "EARTH_SPACE", "topic": "asteroids", "grades": [5, 6, 7], "terms": ["asteroid", "bato sa kalawakan", "asteroid belt", "araw", "umiikot", "space rock", "Mars", "Jupiter", "umiinog", "asteroid sa kalawakan", "nagtuyok nga bato", "naglibot sa adlaw"], "fact": {"tl": "Ang asteroid ay isang mabatong bagay na umiikot sa Araw, kadalasan ay matatagpuan sa asteroid belt sa pagitan ng Mars at Jupiter.", "en": "An asteroid is a rocky object that orbits the Sun, with most of them found in the asteroid belt between Mars and Jupiter.", "bis": "Ang asteroid usa ka batoon nga butang nga naglibot sa Adlaw, ug ang kadaghanan niini makit-an sa asteroid belt tali sa Mars ug Jupiter."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "astronaut-floating-g5", "domain": "EARTH_SPACE", "topic": "weightlessness in orbit", "grades": [4, 5, 6], "terms": ["astronaut", "lumulutang", "weightless", "kalawakan", "gravity", "orbit", "space", "walang timbang", "naglutaw", "libre nga pagkahulog", "naglutaw nga astronaut", "kawanangan", "free fall"], "fact": {"tl": "Lumulutang ang mga astronaut sa loob ng spacecraft dahil sila at ang sasakyan ay patuloy na bumabagsak sa paligid ng Daigdig nang sabay, kaya nararamdaman nilang walang timbang.", "en": "Astronauts float inside a spacecraft because they and the craft are constantly falling around Earth together, making them feel weightless.", "bis": "Naglutaw ang mga astronaut sulod sa spacecraft tungod kay sila ug ang sakyanan padayon nga nagahulog palibot sa Kalibotan nga dungan, busa mobati silang walay gibug-aton."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "aurora-over-horizon-g7", "domain": "EARTH_SPACE", "topic": "auroras", "grades": [6, 7, 8], "terms": ["aurora", "ilaw sa langit", "northern lights", "araw", "magnetic field", "particle", "solar wind", "kulay na liwanag", "polo", "aurora borealis", "kahayag sa langit", "kolor nga suga", "magnetiko"], "fact": {"tl": "Ang aurora ay makukulay na liwanag sa langit na nabubuo kapag ang mga particle mula sa Araw ay tumama sa hangin sa itaas malapit sa mga polo ng Daigdig.", "en": "An aurora is a colorful glow in the sky made when particles from the Sun strike the upper air near Earth's poles.", "bis": "Ang aurora mao ang kolorido nga kahayag sa langit nga maporma kon ang mga partikulo gikan sa Adlaw mohampak sa hangin sa taas duol sa mga polo sa Kalibotan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "banaue-terraces-landscape-g6", "domain": "EARTH_SPACE", "topic": "rice terraces and erosion control", "grades": [5, 6, 7], "terms": ["Banaue", "hagdan-hagdang palayan", "rice terraces", "bundok", "erosion", "lupa", "Ifugao", "pagtatanim", "patag na lupa", "payyo", "hagdanan nga humayan", "pagkahugno sa yuta", "pag-agos"], "fact": {"tl": "Ang hagdan-hagdang palayan ng Banaue ay inukit sa gilid ng bundok upang gawing patag ang lupa para sa palay at upang pigilan ang pag-agos at pagguho ng lupa.", "en": "The Banaue rice terraces were carved into the mountainsides to make flat land for growing rice and to slow down soil erosion.", "bis": "Ang hagdan-hagdan nga humayan sa Banaue gikulit sa kilid sa bukid aron mahimong patag ang yuta para sa humay ug aron mapugngan ang pag-anod ug pagkahugno sa yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "barrier-reef-lagoon-g6", "domain": "EARTH_SPACE", "topic": "coral reefs and lagoons", "grades": [5, 6, 7], "terms": ["bahura", "coral reef", "barrier reef", "lagoon", "korales", "dagat", "isla", "lawa ng dagat", "buhay sa dagat", "kabahuran", "lim-aw sa dagat", "korales nga bahura", "alon"], "fact": {"tl": "Ang isang barrier reef ay mahabang bahura ng korales na nasa malayo sa baybayin, na nagpoprotekta sa mababaw na lagoon sa pagitan nito at ng isla mula sa malalakas na alon.", "en": "A barrier reef is a long coral reef lying offshore that shelters a calm, shallow lagoon between it and the island from strong waves.", "bis": "Ang barrier reef usa ka taas nga bahura sa korales nga naa sa layo sa baybayon, nga nagpanalipod sa mabaw nga lim-aw tali niini ug sa isla gikan sa kusog nga balod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "big-dipper-constellation-g6", "domain": "EARTH_SPACE", "topic": "Big Dipper asterism", "grades": [5, 6, 7], "terms": ["Big Dipper", "konstelasyon", "bituin", "tabo", "North Star", "Ursa Major", "Polaris", "asterism", "pitong bituin", "hugpong sa bituon", "tabò", "amihanan nga bituon", "constellation"], "fact": {"tl": "Ang Big Dipper ay pangkat ng pitong maliliwanag na bituin na hugis-tabo, at ang dalawang dulong bituin nito ay tumuturo sa North Star na nagpapakita ng hilaga.", "en": "The Big Dipper is a group of seven bright stars shaped like a ladle, and its two end stars point to the North Star that shows which way is north.", "bis": "Ang Big Dipper usa ka grupo sa pito ka hayag nga bituon nga porma og tabo, ug ang duha ka kinatumyang bituon niini nagtudlo sa North Star nga nagpakita kon asa ang amihanan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bodies-of-water-overview-g4", "domain": "EARTH_SPACE", "topic": "bodies of water", "grades": [3, 4, 5], "terms": ["anyong tubig", "dagat", "ilog", "lawa", "sapa", "karagatan", "bodies of water", "lake", "river", "ocean", "tubig sa kalibotan", "suba", "lanaw", "danaw", "kadagatan"], "fact": {"tl": "Ang anyong-tubig ay mga lugar na natatakpan ng tubig gaya ng karagatan, lawa, ilog, at sapa, na karamihan ay tubig-alat sa dagat at tubig-tabang sa ilog at lawa.", "en": "Bodies of water are places covered by water such as oceans, lakes, rivers, and streams; most water is salty in oceans and fresh in lakes and rivers.", "bis": "Ang mga anyo sa tubig mao ang mga dapit nga natabonan og tubig sama sa kadagatan, lanaw, suba, ug sapa; kadaghanan parat sa dagat ug tab-ang sa suba ug lanaw."}, "source": "DepEd G4 Earth Science; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "carbon-stored-in-forest-diagram-g7", "domain": "LIVING_THINGS", "topic": "carbon storage in forests", "grades": [6, 7, 8], "terms": ["kagubatan", "puno", "carbon", "carbon dioxide", "photosynthesis", "naka-imbak na carbon", "forest", "klima", "carbon sink", "gitipigan nga carbon", "kahoy", "lasang", "nagsuyop og carbon"], "fact": {"tl": "Ang mga puno sa kagubatan ay sumisipsip ng carbon dioxide mula sa hangin at iniimbak ang carbon sa kanilang mga sanga, ugat, at lupa, kaya nakakatulong itong pigilan ang pag-init ng mundo.", "en": "Forest trees absorb carbon dioxide from the air and store the carbon in their wood, roots, and soil, which helps slow down global warming.", "bis": "Ang mga kahoy sa lasang nagasuyop og carbon dioxide gikan sa hangin ug nagtipig sa carbon sa ilang mga sanga, gamot, ug yuta, busa makatabang kini sa pagpugong sa pag-init sa kalibotan."}, "source": "NRC LS2.B; AAAS Benchmarks", "generator": "claude-workflow", "reviewed": false},
  {"id": "chocolate-hills-bohol-g6", "domain": "EARTH_SPACE", "topic": "Chocolate Hills of Bohol", "grades": [5, 6, 7], "terms": ["Chocolate Hills", "Bohol", "burol", "bundok", "bungtod", "kalapyason", "anapog", "limestone", "apog", "karst", "Pilipinas", "Bisaya", "uga", "tagtuig", "grass-covered hills", "tigang"], "fact": {"tl": "Ang Chocolate Hills sa Bohol ay daan-daang maliliit na burol na gawa sa apog (limestone), at nagiging kayumanggi parang tsokolate ang damo sa ibabaw nito kapag tag-init.", "en": "The Chocolate Hills in Bohol are hundreds of small limestone mounds whose grass turns brown like chocolate during the dry season.", "bis": "Ang Chocolate Hills sa Bohol mga gatosan ka gagmay nga bungtod nga hinimo sa anapog (limestone), ug ang sagbot niini mahimong kape sama sa tsokolate kon ting-init."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cirrus-wisps-g5", "domain": "EARTH_SPACE", "topic": "Cirrus clouds", "grades": [4, 5, 6], "terms": ["cirrus", "ulap", "panganod", "manipis", "mataas", "kulot", "wispy", "thin clouds", "yelo", "ice crystals", "kristal ng yelo", "high clouds", "buhok", "feathery"], "fact": {"tl": "Ang cirrus ay manipis at parang buhok na mga ulap na nasa pinakamataas na bahagi ng kalangitan, at gawa ito sa maliliit na kristal ng yelo sa halip na patak ng tubig.", "en": "Cirrus are thin, wispy clouds that form very high in the sky and are made of tiny ice crystals instead of water droplets.", "bis": "Ang cirrus mga nipis ug daw buhok nga panganod nga anaa sa kinatas-ang bahin sa langit, ug hinimo kini sa gagmayng kristal sa yelo imbis tinulo sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "clean-vs-polluted-river-g5", "domain": "LIVING_THINGS", "topic": "Clean versus polluted water", "grades": [4, 5, 6], "terms": ["malinis na ilog", "maruming ilog", "polusyon", "polluted river", "clean water", "tubig", "suba", "hugaw", "kontaminado", "basura", "isda", "fish die", "water pollution", "kalinis", "kahugaw"], "fact": {"tl": "Ang malinis na ilog ay may malinaw na tubig na kayang tirhan ng isda, samantalang ang maruming ilog na puno ng basura at kemikal ay nakamamatay sa mga hayop sa tubig.", "en": "A clean river has clear water that fish and other animals can live in, while a polluted river full of garbage and chemicals can kill the living things in it.", "bis": "Ang hinlo nga suba adunay tin-aw nga tubig nga mapuy-an sa isda, samtang ang hugaw nga suba nga puno sa basura ug kemikal makapatay sa mga mananap sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "climate-zones-map-g7", "domain": "EARTH_SPACE", "topic": "Climate zones of Earth", "grades": [6, 7, 8], "terms": ["climate zones", "klima", "tropical", "tropiko", "temperate", "polar", "ekwador", "equator", "init", "lamig", "klimang panahon", "klimatikong sona", "Pilipinas tropical", "tropikanhon", "bugnaw", "polo"], "fact": {"tl": "Hinahati ang Daigdig sa mga climate zone: mainit na tropical malapit sa ekwador, banayad na temperate sa gitna, at napakalamig na polar malapit sa mga poste, at ang Pilipinas ay nasa tropical zone.", "en": "Earth is divided into climate zones: hot tropical near the equator, mild temperate in the middle, and very cold polar near the poles, and the Philippines lies in the tropical zone.", "bis": "Ang Kalibotan gibahin sa mga climate zone: init nga tropical duol sa ekwador, kasarangan nga temperate sa tunga, ug bugnaw kaayo nga polar duol sa mga polo, ug ang Pilipinas anaa sa tropical zone."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "coastal-cove-bay-g6", "domain": "EARTH_SPACE", "topic": "Bays and coves", "grades": [5, 6, 7], "terms": ["cove", "bay", "look", "kalookan", "luok", "baybayin", "coast", "dagat", "dagang tubig", "sheltered water", "kalmadong tubig", "sanctuary", "look ng dagat", "kurbada ng baybayin", "calm water"], "fact": {"tl": "Ang look o cove ay kurbadong bahagi ng baybayin kung saan pumapasok ang dagat sa lupa, kaya kalmado at protektado ang tubig dito laban sa malalakas na alon.", "en": "A bay or cove is a curved part of the coast where the sea reaches into the land, so its water is calmer and more sheltered from strong waves.", "bis": "Ang luok o cove kurbado nga bahin sa baybayon diin ang dagat mosulod sa yuta, busa kalmado ug protektado ang tubig niini batok sa kusog nga balod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "coastal-erosion-undercut-house-g7", "domain": "EARTH_SPACE", "topic": "Coastal erosion", "grades": [6, 7, 8], "terms": ["coastal erosion", "pagguho ng baybayin", "alon", "balod", "natanggal na lupa", "wave erosion", "nakukuha ng dagat", "baybayin", "bahay na bumagsak", "undercut", "pagsira ng dagat", "kakulang baybayon", "naluwang", "sea eats land"], "fact": {"tl": "Ang coastal erosion ay nangyayari kapag hinahampas ng mga alon ang baybayin at unti-unting kinakain ang lupa, kaya minsan bumabagsak ang mga bahay na malapit sa dagat.", "en": "Coastal erosion happens when waves repeatedly pound the shore and slowly wear away the land, which can leave seaside houses undercut and collapsing.", "bis": "Ang coastal erosion mahitabo kon ang mga balod kanunay nga mohampak sa baybayon ug hinay-hinay nga mokaon sa yuta, busa usahay matumba ang mga balay nga duol sa dagat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "comet-tail-g5", "domain": "EARTH_SPACE", "topic": "Comets", "grades": [4, 5, 6], "terms": ["comet", "kometa", "bulalakaw", "buntot", "tail", "yelo", "alikabok", "ice and dust", "araw", "sun heat", "naglalakbay sa kalawakan", "kometang may buntot", "tagdugok", "bituin na may buntot", "space ice"], "fact": {"tl": "Ang kometa ay isang malaking bola ng yelo at alikabok na umiikot sa Araw, at kapag lumalapit ito sa Araw, natutunaw ang yelo at bumubuo ng mahabang nagniningning na buntot.", "en": "A comet is a giant ball of ice and dust that orbits the Sun, and when it comes close to the Sun the ice melts and forms a long glowing tail.", "bis": "Ang kometa usa ka dako nga bola sa yelo ug abog nga naglibot sa Adlaw, ug kon moduol kini sa Adlaw, matunaw ang yelo ug maghimo ug taas nga nagsidlak nga ikog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "compass-rose-eight-point-g4", "domain": "EARTH_SPACE", "topic": "Compass directions", "grades": [3, 4, 5], "terms": ["compass rose", "kompas", "hilaga", "timog", "silangan", "kanluran", "north", "south", "east", "west", "amihanan", "habagatan", "sidlakan", "kasadpan", "direksyon", "directions", "panudlo", "mapa"], "fact": {"tl": "Ang compass rose ay nagpapakita ng mga pangunahing direksyon — Hilaga, Timog, Silangan, at Kanluran — para makatulong sa atin na malaman kung saan tayo papunta sa mapa.", "en": "A compass rose shows the main directions — North, South, East, and West — to help us know which way we are going on a map.", "bis": "Ang compass rose nagpakita sa nag-unang mga direksyon — Amihanan, Habagatan, Sidlakan, ug Kasadpan — aron makatabang nato mahibalo asa kita paingon sa mapa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "continental-vs-oceanic-crust-g9", "domain": "EARTH_SPACE", "topic": "Continental and oceanic crust", "grades": [8, 9, 10], "terms": ["continental crust", "oceanic crust", "balat ng lupa", "kalupaan", "crust", "makapal", "manipis", "granite", "basalt", "kontinental", "ocean floor", "tubig dagat na lupa", "lithosphere", "panit sa yuta", "lupa sa dagat"], "fact": {"tl": "Ang continental crust na pinagtatayuan ng mga lupain ay mas makapal at mas magaan (gawa sa granite), samantalang ang oceanic crust sa ilalim ng karagatan ay mas manipis at mas mabigat (gawa sa basalt).", "en": "Continental crust, which forms the land, is thicker and lighter (made of granite), while oceanic crust beneath the seas is thinner and denser (made of basalt).", "bis": "Ang continental crust nga gibarogan sa mga yuta mas baga ug mas gaan (hinimo sa granite), samtang ang oceanic crust sa ilawom sa kadagatan mas nipis ug mas bug-at (hinimo sa basalt)."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "crepuscular-rays-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "Crepuscular rays (sunbeams)", "grades": [5, 6, 7], "terms": ["crepuscular rays", "sinag ng araw", "sunbeams", "silahis", "ulap", "anino", "shadow", "liwanag", "alikabok", "tubig sa hangin", "sun rays through clouds", "haligi ng liwanag", "silaw", "banaag", "light beams"], "fact": {"tl": "Ang crepuscular rays ay ang parang haligi na sinag ng araw na nakikita kapag dumadaan ang liwanag sa pagitan ng mga ulap, na nagpapakita ng landas ng liwanag sa alikabok at tubig sa hangin.", "en": "Crepuscular rays are the beam-like shafts of sunlight you see when light streams through gaps in the clouds, made visible by dust and moisture in the air.", "bis": "Ang crepuscular rays mao ang daw haligi nga silaw sa adlaw nga makita kon ang kahayag moagi sa mga lutas sa panganod, nga gipakita sa abog ug tubig sa hangin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "crop-rotation-g6", "domain": "LIVING_THINGS", "topic": "Crop rotation", "grades": [5, 6, 7], "terms": ["crop rotation", "pag-ikot ng pananim", "magsasaka", "lupa", "sustansya", "nutrients", "soil", "iba-ibang pananim", "fertility", "yutang umalan", "pagsalintabok sa tanom", "matatabang lupa", "nitrogen", "peste", "tabunok"], "fact": {"tl": "Ang crop rotation ay ang pagtatanim ng iba't ibang pananim sa parehong lupa taon-taon, na tumutulong panatilihing matabang ang lupa at nakababawas ng mga peste at sakit.", "en": "Crop rotation is planting different crops in the same field from year to year, which helps keep the soil fertile and reduces pests and diseases.", "bis": "Ang crop rotation mao ang pagtanom ug lain-laing tanom sa samang uma matag tuig, nga makatabang nga magpabiling tabunok ang yuta ug makamenos sa mga peste ug sakit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "day-night-rotation-g5", "domain": "EARTH_SPACE", "topic": "Day and night from Earth's rotation", "grades": [4, 5, 6], "terms": ["day and night", "araw at gabi", "pag-ikot ng mundo", "rotation", "Earth spins", "globo", "flashlight", "umaga", "gabi", "adlaw ug gabii", "pagtuyok sa kalibotan", "24 oras", "araw umiikot", "naglibot ang yuta", "axis"], "fact": {"tl": "Nagkakaroon tayo ng araw at gabi dahil umiikot ang Daigdig sa sarili nitong axis isang beses kada 24 oras, kaya ang bahaging nakaharap sa Araw ay araw at ang nasa likod ay gabi.", "en": "We have day and night because Earth spins on its own axis once every 24 hours, so the side facing the Sun has daytime while the other side has night.", "bis": "Aduna kitay adlaw ug gabii tungod kay ang Kalibotan magtuyok sa kaugalingong axis kausa matag 24 oras, busa ang bahin nga nag-atubang sa Adlaw adlaw ug ang likod gabii."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "deforestation-erosion-g7", "domain": "LIVING_THINGS", "topic": "Deforestation and erosion", "grades": [6, 7, 8], "terms": ["deforestation", "pagkakalbo ng gubat", "pagputol ng puno", "erosion", "pagguho ng lupa", "ugat", "roots hold soil", "kagubatan", "kalbong bundok", "pagkakalbo", "landslide", "pagkahugno sa yuta", "pagpamutol ug kahoy", "bare hills", "baha"], "fact": {"tl": "Kapag pinuputol ang mga puno sa gubat (deforestation), nawawala ang mga ugat na humahawak sa lupa, kaya mas madaling maguho ang lupa at magkaroon ng baha at landslide.", "en": "When forest trees are cut down (deforestation), the roots that hold the soil are lost, so the land erodes more easily and floods and landslides become more likely.", "bis": "Kon putlon ang mga kahoy sa lasang (deforestation), mawala ang mga gamot nga naggunit sa yuta, busa sayon nga mahugno ang yuta ug magbaha ug magdahili."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "delta-formation-g7", "domain": "EARTH_SPACE", "topic": "River delta formation", "grades": [6, 7, 8], "terms": ["delta", "ilog", "suba", "putik", "sediment", "buhangin", "river mouth", "bunganga ng ilog", "naipon na lupa", "deposition", "pagtitipon", "dagat", "delta sa suba", "natambak na yuta", "fan shape", "sandbar"], "fact": {"tl": "Ang delta ay tatsulok na lupa na nabubuo sa bunganga ng ilog kapag ibinababa ng mabagal na agos ang dala nitong putik at buhangin bago lumabas sa dagat.", "en": "A delta is a triangle-shaped piece of land that forms at a river's mouth when the slowing water drops the mud and sand it carries before reaching the sea.", "bis": "Ang delta usa ka triyanggulo nga yuta nga maporma sa baba sa suba kon ang hinay nga agos magpahulog sa dala niini nga lapok ug balas una mosulod sa dagat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "deposition-sandbar-g7", "domain": "EARTH_SPACE", "topic": "Deposition and sandbars", "grades": [6, 7, 8], "terms": ["deposition", "pagtitipon", "sandbar", "buhangin", "balas", "natambak", "agos", "current", "ilog", "dagat", "tabok sa balas", "naipong buhangin", "sediment drops", "patong ng buhangin", "shallow", "mababaw"], "fact": {"tl": "Ang deposition ay ang pagbaba ng dala-dalang buhangin at putik ng tubig kapag bumabagal ito, at kung saan ito nagtitipon-tipon ay nabubuo ang sandbar o tambak ng buhangin.", "en": "Deposition is the dropping of sand and mud carried by water when it slows down, and where this material piles up a sandbar can form.", "bis": "Ang deposition mao ang pagpahulog sa dala nga balas ug lapok sa tubig kon mohinay kini, ug kon asa kini magtigom maporma ang sandbar o tapok sa balas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dew-drops-leaf-g5", "domain": "MATTER", "topic": "Dew formation", "grades": [4, 5, 6], "terms": ["dew", "hamog", "patak ng tubig", "dahon", "umaga", "lamig", "condensation", "singaw ng tubig", "yamog", "tinulo sa dahon", "water vapor cools", "namumuong tubig", "morning dew", "malamig na bagay", "tulo"], "fact": {"tl": "Ang hamog ay mga patak ng tubig na nabubuo sa mga dahon at damo sa umaga kapag lumalamig ang gabi at ang singaw ng tubig sa hangin ay nagiging likido sa malamig na ibabaw.", "en": "Dew is the water droplets that form on leaves and grass in the morning when the night cools and water vapor in the air turns to liquid on cold surfaces.", "bis": "Ang yamog mga tinulo sa tubig nga maporma sa mga dahon ug sagbot sa buntag kon mobugnaw ang gabii ug ang alisngaw sa tubig sa hangin mahimong likido sa bugnaw nga nawong."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "disaster-gobag-g5", "domain": "EARTH_SPACE", "topic": "Disaster preparedness go-bag", "grades": [4, 5, 6], "terms": ["go-bag", "disaster kit", "kalamidad", "bagyo", "lindol", "emergency", "handa sa sakuna", "tubig", "pagkain", "flashlight", "first aid", "go-bag para sa kalamidad", "andam sa katalagman", "baha", "linog", "evacuation"], "fact": {"tl": "Ang go-bag ay isang nakahandang bag na may tubig, pagkain, gamot, flashlight, at importanteng papeles na dapat dalhin agad kapag may bagyo, baha, o lindol para makaligtas.", "en": "A go-bag is a ready-packed bag with water, food, medicine, a flashlight, and important papers that you grab quickly during a typhoon, flood, or earthquake to stay safe.", "bis": "Ang go-bag usa ka andam nga bag nga adunay tubig, pagkaon, tambal, flashlight, ug importanteng papeles nga dali nimong dad-on kon may bagyo, baha, o linog aron maluwas."}, "source": "DepEd MATATAG Science; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "double-rainbow-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "Double rainbow", "grades": [5, 6, 7], "terms": ["double rainbow", "bahaghari", "balangaw", "dobleng bahaghari", "ulan", "sikat ng araw", "tubig na patak", "reflection", "kulay", "baligtad na kulay", "raindrops", "dalawang bahaghari", "doble nga balangaw", "secondary rainbow", "ilaw nakurba"], "fact": {"tl": "Ang dobleng bahaghari ay nangyayari kapag ang liwanag ng araw ay dalawang beses na natatalbog sa loob ng mga patak ng ulan, at ang mahinang pangalawang bahaghari ay may baligtad na ayos ng kulay.", "en": "A double rainbow appears when sunlight reflects twice inside raindrops, and the fainter second rainbow has its colors in reverse order.", "bis": "Ang doble nga balangaw mahitabo kon ang kahayag sa adlaw makad-uha mabanaag sulod sa mga tulo sa ulan, ug ang luya nga ikaduhang balangaw adunay sukwahi nga han-ay sa kolor."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "drought-cracked-earth-g6", "domain": "EARTH_SPACE", "topic": "Drought", "grades": [5, 6, 7], "terms": ["drought", "tagtuyot", "tag-init", "walang ulan", "tuyong lupa", "biyak na lupa", "cracked earth", "tubig nauubos", "El Nino", "tuyot", "hulaw", "tinghulaw", "liki sa yuta", "dry season", "pananim namamatay"], "fact": {"tl": "Ang tagtuyot (drought) ay matagal na panahon na halos walang ulan, kaya natutuyo at nababiyak ang lupa, naghihirap ang mga pananim, at nagkukulang ng tubig.", "en": "A drought is a long period with almost no rain, so the soil dries out and cracks, crops struggle, and water becomes scarce.", "bis": "Ang hulaw (drought) dugay nga panahon nga halos walay ulan, busa mauga ug maliki ang yuta, maglisod ang mga tanom, ug magkulang ang tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-moon-distance-g6", "domain": "EARTH_SPACE", "topic": "Earth-Moon distance", "grades": [5, 6, 7], "terms": ["Earth Moon distance", "buwan", "bulan", "layo ng buwan", "384,000 kilometro", "space", "kalawakan", "satellite", "natural satellite", "distansya", "gilay-on sa bulan", "tatlong daang libo", "moon orbits", "kalayuan", "scale"], "fact": {"tl": "Ang Buwan ay nasa average na layo na halos 384,000 kilometro mula sa Daigdig, kaya napakalayo nito kahit mukhang malapit sa langit.", "en": "The Moon is on average about 384,000 kilometers away from Earth, so it is very far even though it looks close in the sky.", "bis": "Ang Bulan anaa sa kasagaran nga gilay-on nga halos 384,000 ka kilometro gikan sa Kalibotan, busa layo kaayo kini bisan murag duol sa langit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-planet-g5", "domain": "EARTH_SPACE", "topic": "Planet Earth", "grades": [4, 5, 6], "terms": ["Earth", "Daigdig", "Mundo", "Kalibotan", "planeta", "planet", "third planet", "tubig", "buhay", "may buhay", "atmospera", "asul na planeta", "blue planet", "ikatlong planeta", "oxygen", "habitat"], "fact": {"tl": "Ang Daigdig ay ang ikatlong planeta mula sa Araw at ang tanging planetang alam nating may tubig at buhay, kaya tinatawag itong asul na planeta.", "en": "Earth is the third planet from the Sun and the only planet we know that has liquid water and life, which is why it is called the blue planet.", "bis": "Ang Kalibotan mao ang ikatulong planeta gikan sa Adlaw ug ang bugtong planeta nga atong nahibal-an nga adunay tubig ug kinabuhi, busa gitawag kining asul nga planeta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "el-nido-limestone-cliffs-g6", "domain": "EARTH_SPACE", "topic": "Limestone cliffs of El Nido", "grades": [5, 6, 7], "terms": ["El Nido", "Palawan", "limestone cliffs", "bangin", "apog", "anapog", "karst", "dagat", "isla", "bato", "korales", "pampang na bato", "talampas", "limestone", "pangpang", "matarik na bato"], "fact": {"tl": "Ang El Nido sa Palawan ay sikat sa matataas na bangin na gawa sa apog (limestone), na unti-unting nahubog ng tubig-ulan at dagat sa loob ng milyon-milyong taon.", "en": "El Nido in Palawan is famous for its towering limestone cliffs, which were slowly carved by rainwater and the sea over millions of years.", "bis": "Ang El Nido sa Palawan bantog sa habog nga mga pangpang nga hinimo sa anapog (limestone), nga hinay-hinayng gikulit sa tubig-ulan ug dagat sulod sa minilyon ka tuig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "el-nino-dry-reservoir-g7", "domain": "EARTH_SPACE", "topic": "El Nino", "grades": [6, 7, 8], "terms": ["El Nino", "tagtuyot", "init ng dagat", "Pacific", "klima", "walang ulan", "drought", "Pilipinas", "PAGASA", "init ng panahon", "tuyong reservoir", "hulaw", "pag-init sa dagat", "warm ocean", "dry spell", "tubig kulang"], "fact": {"tl": "Ang El Nino ay isang pangyayari kung kailan uminit ang tubig-dagat sa Pasipiko, na kadalasang nagdudulot ng mas kaunting ulan at tagtuyot sa Pilipinas ayon sa PAGASA.", "en": "El Nino is a pattern in which the Pacific Ocean's surface warms, which often brings less rain and drought to the Philippines according to PAGASA.", "bis": "Ang El Nino usa ka panghitabo diin moinit ang ibabaw sa dagat sa Pasipiko, nga sagad magdala ug menos nga ulan ug hulaw sa Pilipinas sumala sa PAGASA."}, "source": "PAGASA; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "erosion-soil-slope-g6", "domain": "EARTH_SPACE", "topic": "Soil erosion by water", "grades": [5, 6, 7], "terms": ["erosion", "pagguho ng lupa", "soil erosion", "agos ng tubig", "dalisdis", "slope", "ulan", "natatangay na lupa", "running water", "hagdan", "pagdahili sa yuta", "tubig nagdala", "naanod na lupa", "burol", "washed away"], "fact": {"tl": "Ang erosion ay ang pagtangay ng tubig sa lupa, at mas mabilis itong nangyayari sa matarik na dalisdis na walang halaman na humahawak sa lupa.", "en": "Erosion is the washing away of soil by water, and it happens faster on steep slopes that have no plants to hold the soil in place.", "bis": "Ang erosion mao ang pagdala sa tubig sa yuta, ug mas paspas kini mahitabo sa tarik nga bakilid nga walay tanom nga moggunit sa yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "geyser-jet-g7", "domain": "EARTH_SPACE", "topic": "Geysers", "grades": [6, 7, 8], "terms": ["geyser", "umaagos na mainit na tubig", "init ng lupa", "underground heat", "singaw", "steam", "bukal", "tubig na sumabog", "hot spring", "magma", "init sa ilawom", "nagbuhagay nga tubig", "volcanic", "kumukulong tubig", "eruption tubig"], "fact": {"tl": "Ang geyser ay isang bukal na paulit-ulit na bumubuga ng mainit na tubig at singaw paitaas, dahil pinapainit ng init ng lupa ang tubig sa ilalim hanggang sumabog ito palabas.", "en": "A geyser is a spring that repeatedly shoots hot water and steam into the air, because heat from inside the Earth boils underground water until it bursts out.", "bis": "Ang geyser usa ka tuburan nga balik-balik nga mobuga ug init nga tubig ug aso paibabaw, tungod kay ang kainit gikan sa sulod sa yuta magpabukal sa tubig sa ilawom hangtod mosabog kini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "estero-cleanup-g5", "domain": "LIVING_THINGS", "topic": "Waterway cleanup", "grades": [4, 5, 6], "terms": ["estero", "cleanup", "paglilinis", "basura", "kanal", "ilog", "waterway", "polusyon", "baha", "barado", "linis-estero", "paglimpyo", "hugaw sa kanal", "community cleanup", "tubig malinis", "plastik"], "fact": {"tl": "Ang paglilinis ng estero ay pagtanggal ng basura sa maliliit na daluyan ng tubig sa lungsod, na nakatutulong upang hindi bumara ang tubig at maiwasan ang baha.", "en": "Cleaning up an estero means removing garbage from a city's small waterways, which helps keep water flowing freely and reduces flooding.", "bis": "Ang paglimpyo sa estero mao ang pagkuha sa basura sa gagmayng agianan sa tubig sa siyudad, nga makatabang aron dili mabara ang tubig ug malikayan ang baha."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "flood-evacuation-boat-g5", "domain": "EARTH_SPACE", "topic": "Flood evacuation", "grades": [4, 5, 6], "terms": ["baha", "evacuation", "paglikas", "bangka", "boat", "flood", "rescue", "ligtas", "mataas na lugar", "bagyo", "paglikas sa baha", "pagbakwit", "luwas", "pagsagip", "evacuation center", "tubig taas"], "fact": {"tl": "Kapag malala ang baha, minsan kailangang lumikas gamit ang bangka papunta sa mas mataas at ligtas na lugar, dahil mapanganib ang malalim at malakas na agos ng tubig.", "en": "During severe floods, people sometimes have to evacuate by boat to higher, safer ground, because deep and fast-moving floodwater is dangerous.", "bis": "Kon grabe ang baha, usahay kinahanglan mobakwit gamit ang sakayan paingon sa mas habog ug luwas nga dapit, tungod kay delikado ang lawom ug kusog nga agos sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ewaste-pile-g7", "domain": "MATTER", "topic": "Electronic waste", "grades": [6, 7, 8], "terms": ["e-waste", "electronic waste", "basurang elektroniko", "sirang gadget", "cellphone", "computer", "lason", "toxic metals", "recycle", "lead", "mercury", "elektronikong basura", "guba nga gadget", "nakakalason", "hazardous", "tambak ng e-waste"], "fact": {"tl": "Ang e-waste ay mga sirang gadget tulad ng cellphone at computer na naglalaman ng nakakalasong metal, kaya dapat itong i-recycle nang maayos at hindi basta itapon kahit saan.", "en": "E-waste is discarded gadgets like cellphones and computers that contain toxic metals, so it should be recycled properly and not just thrown anywhere.", "bis": "Ang e-waste mao ang guba nga gadget sama sa cellphone ug kompiyuter nga adunay makahilo nga metal, busa kinahanglan kining i-recycle ug maayo ug dili lang ilabay bisan asa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fault-line-offset-g9", "domain": "EARTH_SPACE", "topic": "Faults and earthquakes", "grades": [8, 9, 10], "terms": ["fault line", "bitak sa lupa", "lindol", "linog", "earthquake", "fault", "gumagalaw na bato", "crust", "West Valley Fault", "PHIVOLCS", "lambak nga bali", "naggalaw nga yuta", "fault offset", "lupa naghiwalay", "tectonic", "plates"], "fact": {"tl": "Ang fault ay isang bitak sa balat ng lupa kung saan naghahati at gumagalaw ang mga bloke ng bato, at kapag bigla itong dumulas, nagkakaroon ng lindol.", "en": "A fault is a crack in Earth's crust where blocks of rock are split and can move, and when they suddenly slip, an earthquake occurs.", "bis": "Ang fault usa ka liki sa panit sa yuta diin nagbahin ug naglihok ang mga bloke sa bato, ug kon kalit kining modahili, mahitabo ang linog."}, "source": "PHIVOLCS; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "flash-flood-rushing-water-g6", "domain": "EARTH_SPACE", "topic": "flash flood", "grades": [5, 6, 7], "terms": ["flash flood", "rushing water", "baha", "biglang baha", "ragasa", "agos ng tubig", "buhos ng ulan", "baha sa biglaan", "flood", "heavy rain", "matinding ulan", "kusog sa ulan", "rumaragasang tubig"], "fact": {"tl": "Ang flash flood ay biglang baha na dumarating nang mabilis kapag napakalakas na ulan ang bumuhos sa maikling panahon at hindi na kayang sipsipin ng lupa.", "en": "A flash flood is a sudden flood that rushes in quickly when very heavy rain falls in a short time and the ground cannot soak it up fast enough.", "bis": "Ang flash flood maoy kalit nga baha nga moabot dayon kon kusog kaayo nga ulan ang mobundak sa mubo nga panahon ug dili na masuyop sa yuta."}, "source": "encyclopedia-stable consensus; DepEd G6 Earth Science (weather hazards)", "generator": "claude-workflow", "reviewed": false},
  {"id": "flooded-street-baha-scene-g4", "domain": "EARTH_SPACE", "topic": "urban flooding", "grades": [3, 4, 5], "terms": ["baha", "flood", "flooded street", "baha sa kalsada", "lubog sa tubig", "tubig baha", "naglunop", "lunop", "kanal", "drainage", "drainase", "rising water", "tumataas na tubig"], "fact": {"tl": "Bumabaha sa mga kalsada kapag napuno ng tubig-ulan ang lupa at mga kanal, kaya't ang sobrang tubig ay umaapaw at tumitipon sa mababang bahagi ng daan.", "en": "Streets flood when rainwater fills the ground and drains, so the extra water overflows and collects in the low parts of the road.", "bis": "Mobaha ang mga dalan kon mapuno na sa tubig-ulan ang yuta ug mga kanal, mao nga ang sobra nga tubig moawas ug motapok sa ubos nga bahin sa dalan."}, "source": "encyclopedia-stable consensus; DepEd Earth Science (weather hazards)", "generator": "claude-workflow", "reviewed": false},
  {"id": "four-seasons-earth-orbit-g6", "domain": "EARTH_SPACE", "topic": "seasons and Earth's tilt", "grades": [5, 6, 7], "terms": ["four seasons", "apat na panahon", "tilt", "pagkakiling ng Earth", "orbit", "pag-ikot sa araw", "tag-init", "tag-lamig", "season", "panahon", "ting-init", "axis", "ehe", "pagkiling sa yuta", "tuig"], "fact": {"tl": "May apat na panahon (tagsibol, tag-init, taglagas, taglamig) sa ibang bansa dahil ang Earth ay nakakiling sa ehe nito habang umiikot sa Araw, kaya nag-iiba ang dami ng sikat na natatanggap ng bawat bahagi.", "en": "Other countries have four seasons (spring, summer, autumn, winter) because Earth is tilted on its axis as it orbits the Sun, so each part receives different amounts of sunlight through the year.", "bis": "Adunay upat ka panahon (tingpamulak, ting-init, tinghulog-dahon, tingtugnaw) sa ubang nasod tungod kay ang yuta nagharag sa iyang ehe samtang nagtuyok sa Adlaw, mao nga lahi ang gidaghanon sa silaw nga madawat sa matag bahin."}, "source": "encyclopedia-stable consensus; NRC ESS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "frost-on-grass-g5", "domain": "MATTER", "topic": "frost formation", "grades": [4, 5, 6], "terms": ["frost", "hamog na nagyelo", "namuong hamog", "yelo sa damo", "frozen dew", "freezing", "pagyeyelo", "deposition", "singaw ng tubig", "alisngaw", "tun-og", "namugnaw", "ice crystals", "kristal ng yelo", "malamig na gabi"], "fact": {"tl": "Ang frost ay manipis na yelo na bumubuo sa damo at bagay kapag napakalamig ng gabi at ang singaw ng tubig sa hangin ay direktang nagiging maliliit na kristal ng yelo.", "en": "Frost is a thin layer of ice that forms on grass and objects on very cold nights, when water vapor in the air turns directly into tiny ice crystals.", "bis": "Ang frost maoy nipis nga yelo nga matawo sa sagbot ug mga butang kon bugnaw kaayo ang gabii ug ang alisngaw sa tubig sa hangin diretso nga mahimong gagmay nga kristal sa yelo."}, "source": "encyclopedia-stable consensus; NRC PS1.A (changes of state)", "generator": "claude-workflow", "reviewed": false},
  {"id": "full-moon-over-sea-g4", "domain": "EARTH_SPACE", "topic": "full moon phase", "grades": [3, 4, 5], "terms": ["full moon", "kabilugan ng buwan", "bilog na buwan", "buong buwan", "moon phase", "yugto ng buwan", "bulan", "takdol", "pagsidlak sa bulan", "reflected sunlight", "liwanag ng araw", "moon over sea", "dagat", "lunar phase"], "fact": {"tl": "Nagiging full moon o kabilugan ng buwan kapag nasa magkabilang panig ang Earth at Buwan mula sa Araw, kaya buong mukha ng Buwan na nakaharap sa atin ang naliliwanagan.", "en": "We see a full moon when Earth lies between the Sun and the Moon, so the whole face of the Moon turned toward us is lit by sunlight.", "bis": "Makita nato ang takdol o bug-os nga bulan kon ang Yuta anaa sa tunga sa Adlaw ug sa Bulan, mao nga ang tibuok nawong sa Bulan nga nag-atubang kanato masidlakan sa silaw sa adlaw."}, "source": "encyclopedia-stable consensus; NRC ESS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "garbage-clogged-floodway-g5", "domain": "EARTH_SPACE", "topic": "garbage and flooding", "grades": [4, 5, 6], "terms": ["garbage", "basura", "clogged", "barado", "floodway", "kanal", "estero", "waterway", "daluyan ng tubig", "baha", "flood", "samok sa kanal", "naghimo og baha", "pagtapok sa basura", "drainage", "drainase", "polusyon"], "fact": {"tl": "Lalong lumalala ang baha kapag napupuno ng basura ang mga kanal at estero, dahil nababarahan ang daluyan at hindi makaagos palabas ang tubig-ulan.", "en": "Flooding gets worse when garbage clogs canals and waterways, because the blocked channels stop rainwater from flowing away.", "bis": "Mograbe ang baha kon mapuno sa basura ang mga kanal ug estero, kay nasamok ang agianan ug dili na makaagos pagawas ang tubig-ulan."}, "source": "encyclopedia-stable consensus; DepEd Earth Science (human impact, weather hazards)", "generator": "claude-workflow", "reviewed": false},
  {"id": "greenhouse-jars-temperature-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "greenhouse effect", "grades": [5, 6, 7], "terms": ["greenhouse effect", "epekto ng greenhouse", "init", "trapped heat", "natipong init", "garapon", "jar", "temperatura", "temperature", "sikat ng araw", "sunlight", "nainit", "nahimong init", "warming", "pagkulong sa init", "experiment"], "fact": {"tl": "Sa loob ng saradong garapon o greenhouse, nakukulong ang init ng araw kaya tumataas ang temperatura — ganito rin nagpapainit ng Earth ang mga greenhouse gas sa atmospera.", "en": "Inside a closed jar or greenhouse, the Sun's heat gets trapped so the temperature rises — in the same way, greenhouse gases in the atmosphere warm the Earth.", "bis": "Sa sulod sa sirado nga garapon o greenhouse, makulong ang init sa adlaw mao nga mosaka ang temperatura — sama usab niini ang pagpainit sa Yuta sa mga greenhouse gas sa atmospera."}, "source": "encyclopedia-stable consensus; NRC ESS2.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "gusty-wind-bending-palms-g4", "domain": "EARTH_SPACE", "topic": "strong wind", "grades": [3, 4, 5], "terms": ["gusty wind", "malakas na hangin", "humihihip", "hangin", "wind", "niyog", "palma", "palm tree", "yumuyuko", "nakuyaw", "bending trees", "bagyo", "storm", "hampas ng hangin", "kusog nga hangin", "huros sa hangin", "moving air"], "fact": {"tl": "Ang hangin ay gumagalaw na himpapawid, at kapag napakalakas nito ay napapayuko at nababaluktot pati ang matatatag na puno ng niyog at palma.", "en": "Wind is moving air, and when it blows very strongly it can bend and sway even sturdy coconut and palm trees.", "bis": "Ang hangin maoy naglihok nga hangin, ug kon kusog kaayo kini makapaduko ug makapakurba bisan sa lig-on nga mga lubi ug palma."}, "source": "encyclopedia-stable consensus; NRC ESS2.D (weather)", "generator": "claude-workflow", "reviewed": false},
  {"id": "hailstones-falling-g6", "domain": "MATTER", "topic": "hail", "grades": [5, 6, 7], "terms": ["hail", "hailstones", "ulan na yelo", "graniso", "yelong bumabagsak", "frozen rain", "thunderstorm", "kulog at kidlat", "ice ball", "bola ng yelo", "ulan-yelo", "ulan nga yelo", "nagyeyelo", "naghimo og yelo", "storm cloud", "ulap"], "fact": {"tl": "Ang graniso o hail ay mga bola ng yelo na nahuhulog mula sa malalakas na ulap-bagyo, kung saan ang patak ng tubig ay paulit-ulit na nadadala pataas sa malamig na bahagi at nagyeyelo bago bumagsak.", "en": "Hail is balls of ice that fall from tall storm clouds, where raindrops are carried up again and again into freezing air and turn to ice before they drop.", "bis": "Ang hail o yelo nga ulan maoy mga bola sa yelo nga mahulog gikan sa taas nga panganod sa bagyo, diin ang tulo sa tubig balik-balik nga dad-on pataas ngadto sa bugnaw nga hangin ug mahimong yelo una mahulog."}, "source": "encyclopedia-stable consensus; NRC ESS2.D (water cycle, weather)", "generator": "claude-workflow", "reviewed": false},
  {"id": "high-tide-low-tide-compare-g6", "domain": "EARTH_SPACE", "topic": "ocean tides", "grades": [5, 6, 7], "terms": ["high tide", "low tide", "taog", "kati", "tide", "pagtaas ng tubig", "pagbaba ng tubig", "buwan", "moon gravity", "grabidad ng buwan", "dagat", "sea level", "taob", "hunas", "pull of the moon", "hila ng buwan", "tidal"], "fact": {"tl": "Tumataas ang tubig-dagat tuwing high tide at bumababa tuwing low tide dahil sa hila ng grabidad ng Buwan (at kaunti ng Araw) sa tubig ng karagatan.", "en": "The sea rises at high tide and drops at low tide because of the pull of the Moon's gravity (and a little of the Sun's) on the ocean water.", "bis": "Mosaka ang tubig-dagat panahon sa taob ug mohubas panahon sa hunas tungod sa pagbira sa grabidad sa Bulan (ug gamay sa Adlaw) sa tubig sa kadagatan."}, "source": "encyclopedia-stable consensus; NRC ESS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "hill-landform-g4", "domain": "EARTH_SPACE", "topic": "hill landform", "grades": [3, 4, 5], "terms": ["hill", "burol", "bungtod", "landform", "anyong lupa", "mababang bundok", "nakataas na lupa", "raised land", "slope", "dalisdis", "bukid", "punso", "gentle slope", "tagaytay", "lupang mataas"], "fact": {"tl": "Ang burol ay isang anyong-lupa na nakataas sa palibot na lupa ngunit mas mababa at mas pahilis-hilis kaysa sa bundok.", "en": "A hill is a landform that rises above the surrounding ground but is lower and more gently sloped than a mountain.", "bis": "Ang bungtod maoy usa ka porma sa yuta nga mas taas sa palibot nga yuta apan mas ubos ug mas hinay ang dalisdis kaysa bukid."}, "source": "encyclopedia-stable consensus; DepEd G4 Earth Science (landforms)", "generator": "claude-workflow", "reviewed": false},
  {"id": "hot-spring-geyser-g7", "domain": "EARTH_SPACE", "topic": "hot springs and geysers", "grades": [6, 7, 8], "terms": ["hot spring", "geyser", "mainit na bukal", "init nga tuburan", "mainit na tubig", "volcanic heat", "init ng bulkan", "magma", "underground heat", "tubig na pumupulandit", "steam", "singaw", "pagbula sa tubig", "Pansol", "geothermal"], "fact": {"tl": "Ang mainit na bukal at geyser ay lumalabas kapag ang tubig sa ilalim ng lupa ay napainit ng mainit na bato malapit sa magma, kaya umaakyat itong mainit o pumupulandit pataas bilang singaw at tubig.", "en": "Hot springs and geysers appear where underground water is heated by hot rock near magma, so it rises up warm or even bursts upward as steam and water.", "bis": "Ang init nga tuburan ug geyser motungha kon ang tubig ilalom sa yuta mainit tungod sa init nga bato duol sa magma, mao nga mosaka kini nga init o mobuto pataas isip alisngaw ug tubig."}, "source": "encyclopedia-stable consensus; NRC ESS2.A (geothermal/volcanism)", "generator": "claude-workflow", "reviewed": false},
  {"id": "hundred-islands-bay-g5", "domain": "EARTH_SPACE", "topic": "Hundred Islands", "grades": [4, 5, 6], "terms": ["Hundred Islands", "Hundred Islands National Park", "Alaminos", "Pangasinan", "isla", "pulo", "limestone islands", "anyong tubig", "look", "bay", "karst", "coral", "umangat na bahura", "ancient coral reef", "bahurang umangat", "islet"], "fact": {"tl": "Ang Hundred Islands National Park sa Alaminos, Pangasinan ay binubuo ng daan-daang maliliit na pulo na dating mga sinaunang bahura ng coral na umangat mula sa dagat libu-libong taon na ang nakalipas.", "en": "Hundred Islands National Park in Alaminos, Pangasinan is made of hundreds of small islands that were once ancient coral reefs lifted up out of the sea thousands of years ago.", "bis": "Ang Hundred Islands National Park sa Alaminos, Pangasinan gilangkoban sa gatosan ka gagmay nga isla nga kaniadto karaan nga coral reef nga miangat gikan sa dagat liboan ka tuig na ang milabay."}, "source": "encyclopedia-stable consensus (Hundred Islands National Park)", "generator": "claude-workflow", "reviewed": false},
  {"id": "intertropical-convergence-zone-g8", "domain": "EARTH_SPACE", "topic": "intertropical convergence zone", "grades": [7, 8, 9], "terms": ["intertropical convergence zone", "ITCZ", "habagat", "pagtatagpo ng hangin", "converging winds", "ekwador", "equator", "ulan", "rain band", "tropical rain", "ulan sa tropiko", "rising air", "umakyat na hangin", "trade winds", "kalma", "doldrums"], "fact": {"tl": "Ang Intertropical Convergence Zone (ITCZ) ay banda malapit sa ekwador kung saan nagtatagpo ang hangin mula sa hilaga at timog, umaakyat ito at lumalamig, kaya madalas itong nagdadala ng makapal na ulap at malakas na ulan sa Pilipinas.", "en": "The Intertropical Convergence Zone (ITCZ) is a band near the equator where winds from the north and south meet and rise, cooling and bringing thick clouds and heavy rain, including to the Philippines.", "bis": "Ang Intertropical Convergence Zone (ITCZ) maoy usa ka banda duol sa ekwador diin magtagbo ang mga hangin gikan sa amihanan ug habagatan, mosaka kini ug mobugnaw, mao nga sagad magdala kini og baga nga panganod ug kusog nga ulan, lakip sa Pilipinas."}, "source": "encyclopedia-stable consensus (PAGASA; atmospheric science)", "generator": "claude-workflow", "reviewed": false},
  {"id": "island-formation-volcanic-g7", "domain": "EARTH_SPACE", "topic": "volcanic island formation", "grades": [6, 7, 8], "terms": ["volcanic island", "bulkanikong isla", "pulo mula sa bulkan", "lava", "magma", "underwater volcano", "bulkan sa ilalim ng dagat", "island formation", "pagkabuo ng isla", "umusbong na lupa", "cooled lava", "tumigas na lava", "natawo nga isla", "seafloor", "eruption"], "fact": {"tl": "Maraming pulo, gaya ng marami sa Pilipinas, ay nabuo nang sumabog ang mga bulkan sa ilalim ng dagat at unti-unting nagtumpok ang tumigas na lava hanggang umangat ito sa ibabaw ng tubig.", "en": "Many islands, like many in the Philippines, formed when undersea volcanoes erupted and their cooled lava piled up over time until it rose above the water.", "bis": "Daghang isla, sama sa daghan sa Pilipinas, naporma sa dihang mibuto ang mga bulkan ilalom sa dagat ug anam-anam nga nagtapok ang nagbugnaw nga lava hangtod miangat kini ibabaw sa tubig."}, "source": "encyclopedia-stable consensus; NRC ESS2.B (plate tectonics, volcanism)", "generator": "claude-workflow", "reviewed": false},
  {"id": "jupiter-with-bands-g6", "domain": "EARTH_SPACE", "topic": "planet Jupiter", "grades": [5, 6, 7], "terms": ["Jupiter", "pinakamalaking planeta", "gas giant", "bands", "guhit ng ulap", "cloud bands", "Great Red Spot", "malaking pulang batik", "bagyo", "storm", "planeta", "planet", "gas", "pinakadako nga planeta", "buwan ni Jupiter", "moons"], "fact": {"tl": "Ang Jupiter ang pinakamalaking planeta sa Solar System at isang higanteng gas; ang mga makukulay na guhit dito ay mga banda ng ulap na hinihipan ng napakalalakas na hangin.", "en": "Jupiter is the largest planet in the Solar System and a giant ball of gas; its colorful stripes are bands of clouds blown by very strong winds.", "bis": "Ang Jupiter mao ang pinakadako nga planeta sa Solar System ug usa ka higante nga gas; ang mabulukon nga mga gilis niini maoy mga banda sa panganod nga gihuyop sa kusog kaayo nga hangin."}, "source": "encyclopedia-stable consensus; NRC ESS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "karst-pinnacles-field-g8", "domain": "EARTH_SPACE", "topic": "karst landform", "grades": [7, 8, 9], "terms": ["karst", "limestone", "apog", "batong apog", "pinnacles", "matulis na bato", "dissolved rock", "natunaw na bato", "acidic rain", "maasim na ulan", "cave", "kweba", "anyong lupa", "karst nga yuta", "natunaw nga bato", "eroded limestone"], "fact": {"tl": "Ang karst ay tanawing-lupa ng batong-apog na unti-unting natutunaw ng bahagyang maasim na tubig-ulan, kaya nabubuo ang matutulis na bato, lubak, at mga kweba.", "en": "Karst is a landscape of limestone that is slowly dissolved by slightly acidic rainwater, forming sharp pinnacles, sinkholes, and caves.", "bis": "Ang karst maoy talan-awon nga yuta sa batong apog nga hinay-hinay nga matunaw sa gamay nga aslom nga tubig-ulan, mao nga matawo ang talinis nga mga bato, lungag, ug mga langob."}, "source": "encyclopedia-stable consensus; NRC ESS2.A (weathering, erosion)", "generator": "claude-workflow", "reviewed": false},
  {"id": "la-nina-flooded-fields-g8", "domain": "EARTH_SPACE", "topic": "La Nina", "grades": [7, 8, 9], "terms": ["La Nina", "La Niña", "malakas na ulan", "baha", "flood", "Pacific Ocean", "Karagatang Pasipiko", "malamig na tubig-dagat", "cooler sea", "ulan", "rainfall", "El Nino", "wet season", "basang panahon", "kusog nga ulan", "baha sa uma", "climate pattern"], "fact": {"tl": "Ang La Niña ay panahon na lumalamig ang ibabaw ng gitnang Karagatang Pasipiko, kaya madalas itong nagdadala ng mas maraming ulan at baha sa Pilipinas.", "en": "La Niña is a period when the surface of the central Pacific Ocean cools, which often brings more rain and flooding to the Philippines.", "bis": "Ang La Niña maoy panahon nga mobugnaw ang ibabaw sa sentro nga Kadagatang Pasipiko, mao nga sagad kini magdala og mas daghang ulan ug baha sa Pilipinas."}, "source": "encyclopedia-stable consensus (PAGASA; ENSO climate pattern)", "generator": "claude-workflow", "reviewed": false},
  {"id": "lake-volcanic-crater-g6", "domain": "EARTH_SPACE", "topic": "crater lake", "grades": [5, 6, 7], "terms": ["crater lake", "lawa sa bunganga", "lawa sa bulkan", "volcanic crater", "bunganga ng bulkan", "Taal", "lake", "lawa", "lanaw", "tubig sa krater", "rainwater filled", "napuno ng ulan", "extinct volcano", "patay na bulkan", "caldera"], "fact": {"tl": "Ang crater lake ay lawa na nabuo sa loob ng bunganga ng isang bulkan kapag napuno ng tubig-ulan o tubig-lupa ang malalim na lubak nito, gaya ng makikita sa Taal.", "en": "A crater lake is a lake that forms inside the bowl-shaped mouth of a volcano when rainwater or groundwater fills the deep hollow, as seen at Taal.", "bis": "Ang crater lake maoy lanaw nga matawo sulod sa baba sa usa ka bulkan kon mapuno sa tubig-ulan o tubig sa yuta ang lawom nga lungag niini, sama sa makita sa Taal."}, "source": "encyclopedia-stable consensus; NRC ESS2.A (volcanism, landforms)", "generator": "claude-workflow", "reviewed": false},
  {"id": "landslide-hillside-collapse-g6", "domain": "EARTH_SPACE", "topic": "landslide", "grades": [5, 6, 7], "terms": ["landslide", "pagguho ng lupa", "guho", "dagsa", "hillside collapse", "gumuhong lupa", "bangin", "slope", "dalisdis", "heavy rain", "malakas na ulan", "deforestation", "kalbo na bundok", "gravity", "grabidad", "natural-on nga yuta", "pagdahili sa yuta"], "fact": {"tl": "Nagaganap ang landslide o pagguho ng lupa kapag ang lupa at bato sa gilid ng burol o bundok ay bumibigay at bumababa, kadalasan dahil sa malakas na ulan o kawalan ng punong humahawak sa lupa.", "en": "A landslide happens when soil and rock on a hill or mountain slope give way and slide down, often after heavy rain or when there are no trees to hold the ground.", "bis": "Mahitabo ang landslide o pagdahili sa yuta kon ang yuta ug bato sa kilid sa bungtod o bukid mawad-an og gunitanan ug modahili paubos, sagad tungod sa kusog nga ulan o kawalay kahoy nga mokupot sa yuta."}, "source": "encyclopedia-stable consensus; DepEd Earth Science (geologic hazards)", "generator": "claude-workflow", "reviewed": false},
  {"id": "landslide-mud-debris-flow-g7", "domain": "EARTH_SPACE", "topic": "mudflow and debris flow", "grades": [6, 7, 8], "terms": ["mudflow", "debris flow", "putik na umaagos", "lahar", "rumaragasang putik", "mud", "putik", "saturated soil", "basang lupa", "rumaragasa", "lapok", "naghugpa nga lapok", "fast moving mud", "heavy rain", "malakas na ulan"], "fact": {"tl": "Ang mudflow o debris flow ay mabilis na pag-agos ng putik, bato, at sanga pababa sa dalisdis kapag ang lupa ay nababad sa tubig-ulan, at mabilis itong makasisira ng mga tahanan.", "en": "A mudflow or debris flow is a fast rush of mud, rock, and branches down a slope when the ground is soaked with rain, and it can quickly destroy homes.", "bis": "Ang mudflow o debris flow maoy paspas nga pag-agos sa lapok, bato, ug sanga paubos sa dalisdis kon ang yuta nahumod sa tubig-ulan, ug paspas kining makaguba sa mga balay."}, "source": "encyclopedia-stable consensus; DepEd Earth Science (geologic hazards)", "generator": "claude-workflow", "reviewed": false},
  {"id": "lava-flow-fissure-g7", "domain": "EARTH_SPACE", "topic": "lava flow", "grades": [6, 7, 8], "terms": ["lava flow", "agos ng lava", "fissure", "bitak", "lava", "magma", "molten rock", "natunaw na bato", "bulkan", "volcano", "eruption", "pagputok", "init nga bato", "nagdagayday nga lava", "litik sa yuta", "cooled lava", "tumigas na lava"], "fact": {"tl": "Ang lava ay natunaw na bato na lumalabas mula sa bulkan o sa bitak sa lupa, at habang umaagos ito ay unti-unting lumalamig at tumitigas na bago.", "en": "Lava is melted rock that comes out of a volcano or a crack in the ground, and as it flows it slowly cools and hardens into new rock.", "bis": "Ang lava maoy natunaw nga bato nga mogawas gikan sa bulkan o sa liki sa yuta, ug samtang nag-agos kini hinay-hinay nga mobugnaw ug mogahi nga bag-ong bato."}, "source": "encyclopedia-stable consensus; NRC ESS2.A (volcanism)", "generator": "claude-workflow", "reviewed": false},
  {"id": "lightning-bolt-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "lightning", "grades": [5, 6, 7], "terms": ["lightning", "kidlat", "kilat", "lightning bolt", "electric spark", "kuryente sa ulap", "static electricity", "static na kuryente", "ulap", "storm cloud", "thunder", "kulog", "dalugdog", "init nga hangin", "electric charge", "singil-kuryente", "discharge"], "fact": {"tl": "Ang kidlat ay napakalakas na agos ng kuryente na nabubuo kapag nagkakaroon ng salungat na singil-kuryente sa loob ng ulap, at biglang lumalabas ito bilang nakakasilaw na liwanag.", "en": "Lightning is a very powerful flow of electricity that builds up when opposite electric charges form inside a storm cloud and then suddenly leap out as a bright flash.", "bis": "Ang kidlat maoy kusog kaayo nga agos sa elektrisidad nga matawo kon adunay nagkasumpaki nga singil-kuryente sulod sa panganod, ug kalit kining mogawas isip masulaw nga kahayag."}, "source": "encyclopedia-stable consensus; NRC PS3.A (energy), PS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "lightning-over-sea-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "lightning and thunder", "grades": [5, 6, 7], "terms": ["lightning over sea", "kidlat sa dagat", "thunder", "kulog", "dalugdog", "light faster than sound", "mabilis ang liwanag", "speed of light", "speed of sound", "bilis ng tunog", "kidlat ug dalugdog", "ngano nauna ang kidlat", "delay", "agwat", "storm at sea"], "fact": {"tl": "Nakikita muna natin ang kidlat bago marinig ang kulog dahil ang liwanag ay naglalakbay nang mas mabilis kaysa tunog, kaya mas matagal dumating sa tainga natin ang ugong ng kulog.", "en": "We see lightning before we hear thunder because light travels much faster than sound, so the rumble of thunder reaches our ears later.", "bis": "Makita una nato ang kidlat una madungog ang dalugdog tungod kay ang kahayag mas paspas molakaw kaysa tingog, mao nga mas dugay moabot sa atong dalunggan ang dahunog sa dalugdog."}, "source": "encyclopedia-stable consensus; NRC PS4.A (light and sound)", "generator": "claude-workflow", "reviewed": false},
  {"id": "liquefaction-after-quake-g8", "domain": "EARTH_SPACE", "topic": "soil liquefaction", "grades": [7, 8, 9], "terms": ["liquefaction", "pagiging likido ng lupa", "soil liquefaction", "earthquake", "lindol", "linog", "shaking ground", "naalog na lupa", "wet sandy soil", "basang buhangin", "sinking buildings", "lumulubog na gusali", "namutik nga yuta", "quake damage", "saturated soil"], "fact": {"tl": "Ang liquefaction ay nangyayari kapag ang basa at mabuhanging lupa ay umaalog nang husto sa lindol, kaya't ito ay kumikilos parang likido at maaaring lumubog ang mga gusali.", "en": "Liquefaction happens when wet, sandy ground is shaken hard by an earthquake, so it behaves like a liquid and buildings can sink or tilt into it.", "bis": "Ang liquefaction mahitabo kon ang basa ug balason nga yuta mauyog og maayo sa linog, mao nga molihok kini sama sa likido ug mahimong molubog o moharag ang mga building."}, "source": "encyclopedia-stable consensus; PHIVOLCS (earthquake hazards)", "generator": "claude-workflow", "reviewed": false},
  {"id": "mangrove-coastline-aerial-g5", "domain": "LIVING_THINGS", "topic": "mangrove forest", "grades": [4, 5, 6], "terms": ["mangrove", "bakawan", "bakhaw", "mangrove forest", "kagubatan ng bakawan", "coastline", "baybayin", "tabing-dagat", "salty water", "alat na tubig", "roots", "ugat", "nursery for fish", "tirahan ng isda", "stilt roots", "protektahan sa baha", "erosion barrier"], "fact": {"tl": "Ang bakawan ay mga puno na tumutubo sa maalat na tubig sa baybayin, at ang masalimuot nilang ugat ay nagsisilbing tahanan ng mga isda at sanggalang ng baybayin laban sa alon at bagyo.", "en": "Mangroves are trees that grow in salty water along the coast, and their tangled roots act as a home for fish and a shield that protects the shore from waves and storms.", "bis": "Ang bakhaw maoy mga kahoy nga motubo sa parat nga tubig sa baybayon, ug ang ilang nagkaginsang nga mga gamot maoy puy-anan sa mga isda ug taming sa baybayon batok sa balod ug bagyo."}, "source": "encyclopedia-stable consensus; NRC LS2 (ecosystems)", "generator": "claude-workflow", "reviewed": false},
  {"id": "mantle-convection-g9", "domain": "EARTH_SPACE", "topic": "mantle convection", "grades": [8, 9, 10], "terms": ["mantle convection", "convection sa mantle", "mantle", "balat-lupa", "manggas", "moving rock", "gumagalaw na bato", "heat from core", "init ng core", "plate tectonics", "paggalaw ng plato", "convection current", "agos ng init", "rising hot rock", "umakyat na init", "lumubog na malamig"], "fact": {"tl": "Sa loob ng Earth, ang init mula sa core ay nagpapagalaw sa mainit na bato ng mantle paitaas habang ang malamig na bato ay lumulubog, at ang mabagal na siklong ito (convection) ang nagtutulak sa mga plato ng Earth.", "en": "Inside Earth, heat from the core makes hot rock in the mantle rise while cooler rock sinks, and this slow cycle of motion (convection) drives the movement of Earth's plates.", "bis": "Sa sulod sa Yuta, ang init gikan sa core makapasaka sa init nga bato sa mantle samtang ang bugnaw nga bato molugsong, ug kini nga hinay nga siklo sa paglihok (convection) maoy nagtukmod sa mga plato sa Yuta."}, "source": "encyclopedia-stable consensus; NRC ESS2.B (plate tectonics)", "generator": "claude-workflow", "reviewed": false},
  {"id": "maria-cristina-falls-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "Maria Cristina Falls hydropower", "grades": [5, 6, 7], "terms": ["Maria Cristina Falls", "talon", "busay", "Iligan", "Mindanao", "Agus River", "waterfall", "hydropower", "hydroelectric", "kuryente mula sa tubig", "kuryente sa busay", "moving water", "agos ng tubig", "power plant", "planta ng kuryente", "energy", "enerhiya"], "fact": {"tl": "Ang Maria Cristina Falls sa Iligan City ay isang talon sa Ilog Agus na ginagamit para gumawa ng kuryente, kung saan ang lakas ng bumabagsak na tubig ang nagpapaikot ng mga turbina.", "en": "Maria Cristina Falls in Iligan City is a waterfall on the Agus River used to make electricity, where the force of the falling water spins turbines to generate power.", "bis": "Ang Maria Cristina Falls sa Iligan City maoy busay sa Suba sa Agus nga gigamit aron makahimo og kuryente, diin ang kusog sa nahulog nga tubig maoy nagpatuyok sa mga turbina aron makahimo og elektrisidad."}, "source": "encyclopedia-stable consensus; NRC PS3.B (energy transfer)", "generator": "claude-workflow", "reviewed": false},
  {"id": "meteor-shower-night-g6", "domain": "EARTH_SPACE", "topic": "meteor shower", "grades": [5, 6, 7], "terms": ["meteor shower", "bulalakaw", "ulan ng bulalakaw", "shooting star", "meteor", "falling star", "naglalagablab na bato", "comet dust", "alikabok ng kometa", "atmosphere", "atmospera", "burning up", "nasusunog", "bituin nga nahagba", "space dust", "alabok sa kawanangan", "streak of light"], "fact": {"tl": "Ang meteor shower o ulan ng bulalakaw ay nangyayari kapag dumaan ang Earth sa landas na puno ng maliliit na tipak ng alikabok mula sa kometa, na nasusunog sa atmospera at nagiging maraming guhit ng liwanag sa langit.", "en": "A meteor shower happens when Earth passes through a trail of tiny dust bits left by a comet, which burn up in the atmosphere and appear as many streaks of light across the sky.", "bis": "Ang meteor shower o ulan sa bulalakaw mahitabo kon ang Yuta moagi sa agianan nga puno sa gagmay nga abog gikan sa kometa, nga masunog sa atmospera ug mahimong daghang gilis sa kahayag sa langit."}, "source": "encyclopedia-stable consensus; NRC ESS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "milky-way-from-earth-g6", "domain": "EARTH_SPACE", "topic": "Milky Way galaxy", "grades": [5, 6, 7], "terms": ["Milky Way", "galaxy", "galaksi", "bituin", "stars", "milky way galaxy", "kalawakan", "band of stars", "guhit ng bituin", "billions of stars", "bilyong bituin", "night sky", "kalangitan sa gabi", "atong galaksiya", "Solar System", "spiral galaxy", "Via Lactea"], "fact": {"tl": "Ang Milky Way ay ang galaksing kinabibilangan ng ating Araw at Earth, at ang maputlang guhit na nakikita sa madilim na kalangitan sa gabi ay ang sanga-sangang liwanag ng bilyun-bilyong malalayong bituin nito.", "en": "The Milky Way is the galaxy that our Sun and Earth belong to, and the faint band we see across a dark night sky is the combined light of its billions of distant stars.", "bis": "Ang Milky Way maoy galaksiya nga gigikanan sa atong Adlaw ug Yuta, ug ang luspad nga gilis nga makita sa ngitngit nga langit sa gabii maoy hiniusang kahayag sa binilyon nga halayo nga mga bituon niini."}, "source": "encyclopedia-stable consensus; NRC ESS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "akapulko-ringworm-bush-g5", "domain": "LIVING_THINGS", "topic": "akapulko medicinal plant", "grades": [4, 5, 6], "terms": ["akapulko", "bayabas-bayabasan", "ringworm bush", "candle bush", "Senna alata", "halamang gamot", "tambal nga tanom", "alibhon", "an-an", "medicinal plant", "dahon", "dahon-dahon", "bulak nga dilaw", "fungal skin"], "fact": {"tl": "Ang akapulko ay isang halamang gamot na may dilaw na bulaklak, at ang dinikdik na dahon nito ay ipinapahid sa balat para gamutin ang an-an at buni na sanhi ng fungus.", "en": "Akapulko (ringworm bush) is a medicinal plant with yellow flowers whose crushed leaves are rubbed on the skin to treat fungal infections like ringworm.", "bis": "Ang akapulko usa ka tambal nga tanom nga may dalag nga bulak, ug ang gidugmok niini nga dahon ginahaplas sa panit aron tambalan ang an-an nga gikan sa fungus."}, "source": "DepEd MATATAG Science (medicinal plants); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "aloe-vera-sabila-g4", "domain": "LIVING_THINGS", "topic": "aloe vera sabila plant", "grades": [3, 4, 5], "terms": ["aloe vera", "sabila", "succulent", "halamang gamot", "tambal nga tanom", "makapal nga dahon", "gel", "uhog sa dahon", "paso", "burn", "balat", "panit", "matabang dahon", "halaman"], "fact": {"tl": "Ang sabila o aloe vera ay halamang may makapal na dahon na puno ng malagkit na gel, at ginagamit ang gel na ito para palamigin ang balat na napaso o nasunog.", "en": "Aloe vera (sabila) is a plant with thick leaves full of a clear gel, and that gel is used to soothe skin that has been burned or sunburned.", "bis": "Ang sabila o aloe vera usa ka tanom nga may baga nga dahon nga puno sa pilit nga gel, ug kini nga gel gigamit aron pabugnawon ang panit nga napaso o nasunog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "alibangbang-leaf-g5", "domain": "LIVING_THINGS", "topic": "alibangbang butterfly-shaped leaf", "grades": [4, 5, 6], "terms": ["alibangbang", "Bauhinia", "butterfly tree", "kabit-kabag", "dahong hugis paruparo", "dahon nga porma sa alibangbang", "maasim na dahon", "aslom nga dahon", "sinigang", "pampaasim", "two-lobed leaf", "biniyak na dahon"], "fact": {"tl": "Ang alibangbang ay isang puno na ang dahon ay hati sa dulo kaya parang pakpak ng paruparo, at ang maasim nitong dahon ay ginagamit na pampaasim sa sinigang.", "en": "Alibangbang is a tree whose leaf is split at the tip like a butterfly's wings, and its sour leaves are used to add a tangy taste to dishes like sinigang.", "bis": "Ang alibangbang usa ka kahoy nga ang dahon gibahin sa tumoy mura'g pako sa alibangbang, ug ang aslom niini nga dahon gigamit nga pampaaslom sa sinigang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "alugbati-malabar-spinach-g4", "domain": "LIVING_THINGS", "topic": "alugbati malabar spinach vegetable", "grades": [3, 4, 5], "terms": ["alugbati", "malabar spinach", "Basella", "gulay", "utanon", "baging", "vine", "gumagapang na tanim", "berdeng dahon", "lunhaw nga dahon", "halamang gulay", "leafy vegetable", "bitamina", "iron"], "fact": {"tl": "Ang alugbati ay isang gumagapang na halamang-gulay na may makapal at malusog na dahon, at niluluto ito bilang gulay dahil mayaman sa bitamina at bakal.", "en": "Alugbati (Malabar spinach) is a climbing leafy vegetable with thick succulent leaves, cooked as a vegetable because it is rich in vitamins and iron.", "bis": "Ang alugbati usa ka nagakatay nga utanon nga may baga ug masustansya nga dahon, ug giluto kini isip utan kay dato sa bitamina ug puthaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ampalaya-bitter-gourd-g5", "domain": "LIVING_THINGS", "topic": "ampalaya bitter gourd", "grades": [4, 5, 6], "terms": ["ampalaya", "bitter gourd", "bitter melon", "Momordica charantia", "paliya", "mapait na gulay", "pait nga utanon", "kulubot na balat", "bumpy skin", "baging", "vine", "blood sugar", "asukal sa dugo", "gulay"], "fact": {"tl": "Ang ampalaya ay isang gulay na baging na may kulubot na balat at kilalang mapait ang lasa, at madalas itong kainin dahil sinasabing nakakatulong sa pagkontrol ng asukal sa dugo.", "en": "Ampalaya (bitter gourd) is a vine vegetable with bumpy skin and a famously bitter taste, often eaten because it is believed to help control blood sugar.", "bis": "Ang ampalaya o paliya usa ka utanon nga nagakatay nga may kulubot nga panit ug ilado nga pait kaayo, ug kanunay kini kan-on kay giingong makatabang sa pagkontrol sa asukal sa dugo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "amoeba-microbe-g6", "domain": "LIVING_THINGS", "topic": "amoeba single-celled organism", "grades": [5, 6, 7], "terms": ["amoeba", "ameba", "isang selula", "usa ka selula", "single-celled", "microbe", "mikrobyo", "pseudopod", "paa-paahan", "shape-changing", "nagbabagong hugis", "tubig", "protist", "mikroskopyo", "engulf"], "fact": {"tl": "Ang amoeba ay isang nilalang na binubuo lamang ng isang selula, at gumagalaw ito sa pamamagitan ng pag-abot ng parang paa nitong tinatawag na pseudopod para hatakin ang sarili at lamunin ang pagkain.", "en": "An amoeba is a tiny living thing made of just one cell, and it moves by pushing out finger-like extensions called pseudopods to creep along and engulf its food.", "bis": "Ang amoeba usa ka buhing butang nga gama lang sa usa ka selula, ug naglihok kini pinaagi sa pag-abot sa iyang murag tiil nga gitawag og pseudopod aron mokamang ug molamoy sa pagkaon."}, "source": "AAAS Benchmarks (cells); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "adaptation-camouflage-stick-insect-g5", "domain": "LIVING_THINGS", "topic": "stick insect camouflage adaptation", "grades": [4, 5, 6], "terms": ["stick insect", "walking stick", "sanga-sangahan", "insekto", "camouflage", "pagtatago", "panag-tago", "adaptation", "adaptasyon", "pagbagay", "kahoy nga sanga", "mura'g sanga", "parang sanga", "predator", "manunukob"], "fact": {"tl": "Ang stick insect ay isang insektong ang katawan ay kahawig na kahawig ng sanga ng kahoy, at ito ang kanyang kamuflahe para hindi siya makita ng mga ibong gustong kumain sa kanya.", "en": "A stick insect has a body that looks almost exactly like a twig, and this camouflage hides it from birds and other predators that want to eat it.", "bis": "Ang stick insect usa ka insekto nga ang lawas susama kaayo sa sanga sa kahoy, ug kini ang iyang takuban aron dili siya makita sa mga langgam nga gustong mokaon kaniya."}, "source": "NRC LS1/LS4 (structure, adaptation); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ant-aphid-mutualism-g6", "domain": "LIVING_THINGS", "topic": "ant and aphid mutualism", "grades": [5, 6, 7], "terms": ["langgam", "hulmigas", "ant", "aphid", "dapulak", "mutualism", "tabang-tabang", "symbiosis", "honeydew", "matamis na katas", "tam-is nga duga", "protection", "proteksyon", "panalipod", "relationship", "kapwa tulong"], "fact": {"tl": "Ang langgam at aphid ay nagtutulungan: iniinom ng langgam ang matamis na katas na inilalabas ng aphid, at bilang kapalit, binabantayan ng langgam ang aphid laban sa mga kaaway nito.", "en": "Ants and aphids help each other: the ant drinks the sweet honeydew the aphid makes, and in return the ant guards the aphid from its enemies.", "bis": "Ang hulmigas ug ang aphid nagtinabangay: gainom ang hulmigas sa tam-is nga duga nga gibuga sa aphid, ug isip baylo, ginabantayan sa hulmigas ang aphid batok sa mga kaaway niini."}, "source": "NRC LS2 (interactions); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "acacia-tree-g4", "domain": "LIVING_THINGS", "topic": "acacia rain tree", "grades": [3, 4, 5], "terms": ["acacia", "akasya", "rain tree", "Samanea saman", "malaking puno", "dako nga kahoy", "lilim", "landong", "shade", "kumakalat na sanga", "nagsanga-sanga", "dahon na nagsasara", "nagasira nga dahon", "folding leaves", "gabi"], "fact": {"tl": "Ang akasya ay isang malaking puno na may malawak na sanga na nagbibigay ng malamig na lilim, at ang maliliit nitong dahon ay nagsasara kapag gabi o umuulan.", "en": "The acacia (rain tree) is a large tree with wide spreading branches that give cool shade, and its tiny leaves fold up at night or when it rains.", "bis": "Ang akasya usa ka dako nga kahoy nga may halapad nga sanga nga naghatag og bugnaw nga landong, ug ang gagmay niini nga dahon mosira kon gabii o mag-ulan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "anahaw-palm-g5", "domain": "LIVING_THINGS", "topic": "anahaw national leaf palm", "grades": [4, 5, 6], "terms": ["anahaw", "fan palm", "Saribus rotundifolius", "pambansang dahon", "national leaf", "abaniko", "paypay", "round leaf", "bilog na dahon", "lingin nga dahon", "pamaypay", "bubong", "atop", "roofing", "palm"], "fact": {"tl": "Ang anahaw ay isang palmera na may malalaki at bilog na dahong hugis-abaniko, at ito ang itinuturing na pambansang dahon ng Pilipinas at ginagamit bilang pamaypay at pangbubong.", "en": "The anahaw is a fan palm with large round leaves shaped like a fan, and it is honored as the national leaf of the Philippines, used for fans and roofing.", "bis": "Ang anahaw usa ka palmera nga may dagko ug lingin nga dahon nga porma sa pamaypay, ug kini ang giila nga nasudnong dahon sa Pilipinas ug gigamit isip pamaypay ug atop."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "active-vs-passive-transport-g8", "domain": "LIVING_THINGS", "topic": "active vs passive transport in cells", "grades": [7, 8, 9, 10], "terms": ["active transport", "passive transport", "aktibong transport", "passibong transport", "cell membrane", "lamad ng selula", "kalamhan sa selula", "diffusion", "enerhiya", "kusog", "ATP", "high to low", "mataas sa mababa", "molecules", "molekula"], "fact": {"tl": "Sa passive transport, kusang gumagalaw ang mga sangkap papasok o palabas ng selula mula sa mataas patungong mababang konsentrasyon nang hindi gumagamit ng enerhiya, ngunit sa active transport ay kailangan ng enerhiya para itulak ang mga ito laban sa daloy.", "en": "In passive transport, substances drift in or out of a cell from high to low concentration without using energy, while active transport must spend energy to pump them the opposite way.", "bis": "Sa passive transport, ang mga sustansya molihok pasulod o pagawas sa selula gikan sa taas paingon sa ubos nga konsentrasyon nga walay gigamit nga kusog, apan sa active transport kinahanglan ang enerhiya aron iduso kini batok sa agos."}, "source": "NRC LS1.A (cell function); AAAS Benchmarks", "generator": "claude-workflow", "reviewed": false},
  {"id": "adaptation-finch-beak-shapes-g7", "domain": "LIVING_THINGS", "topic": "finch beak shapes adaptation", "grades": [6, 7, 8], "terms": ["finch", "pipit", "tuka", "sungo", "beak", "Darwin", "adaptation", "adaptasyon", "pagbagay", "buto", "liso", "seed", "insekto", "insect", "different food", "iba-ibang pagkain", "evolution", "ebolusyon"], "fact": {"tl": "Ang iba't ibang uri ng finch ay may iba't ibang hugis ng tuka—makapal para sa matigas na buto, manipis para sa insekto—na angkop sa pagkaing kinakain nila sa kanilang tirahan.", "en": "Different kinds of finches have differently shaped beaks—thick ones for cracking hard seeds, thin ones for catching insects—each matched to the food in their home.", "bis": "Ang lain-laing matang sa finch may lain-laing porma sa sungo—baga para sa gahi nga liso, nipis para sa insekto—nga haom sa pagkaon nga ilang gikaon sa ilang gipuy-an."}, "source": "NRC LS4 (adaptation, natural selection); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "adaptation-beak-shapes-birds-g5", "domain": "LIVING_THINGS", "topic": "bird beak shapes match their food", "grades": [4, 5, 6], "terms": ["ibon", "langgam", "bird", "tuka", "sungo", "beak", "bibig ng ibon", "hugis", "porma", "adaptation", "adaptasyon", "pagkain", "pagkaon", "agila", "eagle", "tagak", "heron", "buto", "liso", "seed", "isda", "fish"], "fact": {"tl": "Ang hugis ng tuka ng isang ibon ay tumutugma sa pagkain nito—matulis at nakakurba ang tuka ng agila para lumapa ng laman, habang manipis at mahaba ang tuka ng tagak para manghuli ng isda.", "en": "A bird's beak shape matches the food it eats—an eagle's sharp hooked beak tears meat, while a heron's thin pointed beak spears fish.", "bis": "Ang porma sa sungo sa usa ka langgam mohaom sa pagkaon niini—hait ug kurba ang sungo sa agila aron mogisi og unod, samtang nipis ug taas ang sungo sa tagak aron modakop og isda."}, "source": "NRC LS1 (structure and function); DepEd Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "aratiles-fruit-g4", "domain": "LIVING_THINGS", "topic": "aratiles cherry fruit tree", "grades": [3, 4, 5], "terms": ["aratiles", "aratilis", "mansanitas", "Muntingia calabura", "jamaican cherry", "panama berry", "maliit na pula", "gamay nga pula", "prutas", "bunga", "tam-is", "matamis", "puno", "kahoy", "kainin ng bata", "street tree"], "fact": {"tl": "Ang aratiles ay isang puno na nagbubunga ng maliliit at pulang prutas na napakatamis, at ito ay paboritong pulutin at kainin ng mga bata mula sa kalsada.", "en": "Aratiles is a tree that bears tiny round red fruits that are very sweet, and they are a favorite that children pick and eat right off the street tree.", "bis": "Ang aratiles usa ka kahoy nga namunga og gagmay ug pula nga prutas nga tam-is kaayo, ug paborito kini pupoon ug kaonon sa mga bata gikan sa kahoy sa dalan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "apitong-tree-g6", "domain": "LIVING_THINGS", "topic": "apitong dipterocarp timber tree", "grades": [5, 6, 7], "terms": ["apitong", "Dipterocarpus", "dipterocarp", "puno ng gubat", "kahoy sa lasang", "hardwood", "matigas na kahoy", "matarong nga kahoy", "timber", "troso", "resin", "dagta", "rainforest", "gubat", "tall tree", "mataas na puno"], "fact": {"tl": "Ang apitong ay isang napakataas na puno ng katutubong gubat ng Pilipinas, at ang matigas nitong kahoy ay ginagamit sa pagtatayo at paggawa ng sahig at kahoy-panggusali.", "en": "Apitong is a very tall tree of the Philippine rainforest, and its hard, strong wood is used for building, flooring, and construction timber.", "bis": "Ang apitong usa ka taas kaayo nga kahoy sa lumad nga lasang sa Pilipinas, ug ang gahi niini nga kahoy gigamit sa pagtukod, salog, ug kahoy nga panggama."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "arm-bones-diagram-g5", "domain": "LIVING_THINGS", "topic": "bones of the human arm", "grades": [4, 5, 6], "terms": ["braso", "bukton", "arm", "buto", "bukog", "bones", "humerus", "radius", "ulna", "siko", "elbow", "balikat", "abaga", "shoulder", "kalansay", "skeleton", "joint", "kasukasuan"], "fact": {"tl": "Ang braso ay may tatlong pangunahing buto—ang humerus sa itaas mula balikat hanggang siko, at ang radius at ulna sa ibaba mula siko hanggang pulso—na nagbibigay-daan upang makayuko at maiikot ito.", "en": "The arm has three main bones—the humerus from shoulder to elbow, and the radius and ulna from elbow to wrist—which let it bend and twist.", "bis": "Ang bukton may tulo ka nag-unang bukog—ang humerus sa ibabaw gikan sa abaga ngadto sa siko, ug ang radius ug ulna sa ubos gikan sa siko ngadto sa pulso—nga maoy hinungdan nga makabawog ug makatuyok kini."}, "source": "AAAS Benchmarks (human body); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "anthurium-flower-g4", "domain": "LIVING_THINGS", "topic": "anthurium ornamental flower", "grades": [3, 4, 5], "terms": ["anthurium", "anturyum", "halamang-palamuti", "ornamental", "bulaklak", "bulak", "puso-pusong dahon", "heart-shaped", "makintab", "sinaw", "shiny red", "pulang bulaklak", "spadix", "tanim sa bahay", "houseplant"], "fact": {"tl": "Ang anthurium ay isang halamang-palamuti na may makintab at hugis-pusong bahaging pula na madalas nating akalang bulaklak, ngunit ang totoong munting bulaklak nito ay nasa matulis na sentrong bahagi.", "en": "The anthurium is an ornamental plant with a shiny, heart-shaped red part we often think is the flower, but its true tiny flowers sit on the pointed center spike.", "bis": "Ang anthurium usa ka tanom nga pangdayan-dayan nga may sinaw ug porma-kasingkasing nga pula nga sagad gituohan natong bulak, apan ang tinuod niini nga gagmayng bulak naa sa hait nga sentro."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "antlion-larva-g6", "domain": "LIVING_THINGS", "topic": "antlion larva sand trap", "grades": [5, 6, 7], "terms": ["antlion", "antlion larva", "doodlebug", "buhangin", "balas", "sand", "funnel trap", "bitag", "lit-ag", "hukay nga buho", "predator", "manunukob", "langgam", "hulmigas", "ant", "panga", "apapangig", "jaws", "insekto"], "fact": {"tl": "Ang antlion larva ay humuhukay ng parang-funnel na hukay sa buhangin, at naghihintay sa ilalim para hulihin ng malalaki nitong panga ang langgam na madulas at mahulog papasok.", "en": "The antlion larva digs a funnel-shaped pit in loose sand and waits at the bottom to snap its large jaws on any ant that slips and tumbles in.", "bis": "Ang antlion larva nagakalot og porma-funnel nga buho sa balas, ug naghulat sa ilawom aron sikupon sa iyang dagkong apapangig ang hulmigas nga madakin-as ug mahulog pasulod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "balanced-day-healthy-habits-g3", "domain": "LIVING_THINGS", "topic": "healthy daily habits", "grades": [3, 4, 5], "terms": ["malusog na gawi", "himsog nga batasan", "healthy habits", "tulog", "katulog", "sleep", "ehersisyo", "exercise", "masustansyang pagkain", "masustansya nga pagkaon", "balanced diet", "tubig", "water", "paglilinis", "kahinlo", "hygiene", "katawan"], "fact": {"tl": "Para manatiling malusog ang katawan, kailangan natin ng sapat na tulog, regular na ehersisyo, masustansyang pagkain, maraming tubig, at malinis na katawan araw-araw.", "en": "To keep our bodies healthy, we need enough sleep, regular exercise, nutritious food, plenty of water, and good cleanliness every day.", "bis": "Aron magpabiling himsog ang lawas, kinahanglan nato ang igong katulog, kanunay nga ehersisyo, masustansya nga pagkaon, daghang tubig, ug hinlo nga lawas matag adlaw."}, "source": "DepEd MATATAG Science/Health; AAAS Benchmarks (human health)", "generator": "claude-workflow", "reviewed": false},
  {"id": "anthill-observation-jar-g4", "domain": "LIVING_THINGS", "topic": "ant colony tunnels and teamwork", "grades": [3, 4, 5], "terms": ["langgam", "hulmigas", "ant", "anthill", "punso", "kolonya", "colony", "tunnel", "lagusan", "agianan", "obserbasyon", "pagtuon", "queen ant", "reyna", "rayna", "teamwork", "pagtutulungan", "panaghiusa", "lupa", "yuta"], "fact": {"tl": "Ang mga langgam ay naninirahan sa kolonyang gawa sa magkakaugnay na lagusan sa ilalim ng lupa, at nagtutulungan ang libu-libong langgam—may naghahanap ng pagkain, may nag-aalaga ng itlog—para mabuhay ang kanilang pugad.", "en": "Ants live in a colony of connected tunnels under the ground, and thousands of ants work together—some find food, some tend the eggs—to keep their nest alive.", "bis": "Ang mga hulmigas nagpuyo sa kolonya nga gama sa nagsumpay-sumpay nga lagusan ilalom sa yuta, ug ang liboan ka hulmigas nagtinabangay—naay mangita og pagkaon, naay mag-atiman sa itlog—aron mabuhi ang ilang salag."}, "source": "NRC LS2 (organisms, group behavior); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "backyard-ecosystem-bahay-g5", "domain": "LIVING_THINGS", "topic": "backyard as a small ecosystem", "grades": [4, 5, 6], "terms": ["bakuran", "natad", "backyard", "ecosystem", "ekosistema", "halaman", "tanom", "plants", "insekto", "insects", "ibon", "langgam", "bird", "lupa", "yuta", "soil", "magkakaugnay", "nagsalig-salig", "living things", "buhay na bagay"], "fact": {"tl": "Kahit ang isang ordinaryong bakuran ay isang maliit na ekosistema kung saan magkakaugnay ang halaman, insekto, ibon, at lupa habang nagtutulungan at umaasa sa isa't isa para mabuhay.", "en": "Even an ordinary backyard is a small ecosystem where plants, insects, birds, and soil are all connected, depending on one another to live.", "bis": "Bisan ang ordinaryong natad usa ka gamayng ekosistema diin nalambigit ang tanom, insekto, langgam, ug yuta samtang nagsinaligay sa usag-usa aron mabuhi."}, "source": "NRC LS2 (ecosystems); DepEd MATATAG Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "asian-palm-civet-coffee-g6", "domain": "LIVING_THINGS", "topic": "asian palm civet and kape alamid", "grades": [5, 6, 7], "terms": ["alamid", "musang", "Asian palm civet", "Paradoxurus", "kape alamid", "civet coffee", "kapeng alamid", "mammal", "mamalya", "gabi", "nocturnal", "prutas", "bunga", "kape", "coffee cherry", "digest", "dumi", "ihi"], "fact": {"tl": "Ang alamid o musang ay isang gabing-aktibong hayop na kumakain ng hinog na bunga ng kape, at ang mga buto nitong nailalabas ay nililinis at ginagawang mamahaling kapeng alamid.", "en": "The Asian palm civet (alamid) is a night-active animal that eats ripe coffee cherries, and the beans it passes are cleaned to make the prized civet coffee (kape alamid).", "bis": "Ang alamid o musang usa ka mananap nga aktibo sa gabii nga mokaon sa hinog nga bunga sa kape, ug ang mga liso nga gipagawas niini ginalimpyohan aron himoong mahal nga kape alamid."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "avocado-fruit-g4", "domain": "LIVING_THINGS", "topic": "avocado fruit", "grades": [3, 4, 5], "terms": ["avocado", "abukado", "prutas", "bunga", "fruit", "malaking buto", "dakong liso", "big seed", "berdeng laman", "lunhaw nga unod", "creamy", "malambot", "humok", "taba", "healthy fat", "puno"], "fact": {"tl": "Ang abukado ay isang prutas na may malambot at malinamnam na berdeng laman at isang malaking buto sa gitna, at mayaman ito sa malusog na taba na mabuti sa katawan.", "en": "The avocado is a fruit with soft, creamy green flesh and one large seed in the middle, and it is rich in healthy fats that are good for the body.", "bis": "Ang abukado usa ka prutas nga may humok ug lami nga lunhaw nga unod ug usa ka dako nga liso sa tunga, ug dato kini sa himsog nga tambok nga maayo sa lawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "atis-sugar-apple-g4", "domain": "LIVING_THINGS", "topic": "atis sugar apple fruit", "grades": [3, 4, 5], "terms": ["atis", "sugar apple", "sweetsop", "custard apple", "Annona squamosa", "prutas", "bunga", "fruit", "kuba-kubang balat", "bukol-bukol", "lumpy skin", "matamis", "tam-is", "puti na laman", "itom nga liso", "maraming buto", "puno"], "fact": {"tl": "Ang atis ay isang prutas na may bukol-bukol na berdeng balat at napakatamis na puting laman, ngunit may maraming maiitim na buto sa loob nito.", "en": "The atis (sugar apple) is a fruit with bumpy green skin and very sweet white flesh, but it holds many small black seeds inside.", "bis": "Ang atis usa ka prutas nga may bukol-bukol nga lunhaw nga panit ug tam-is kaayo nga puti nga unod, apan daghan kini og itom nga liso sa sulod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "askal-native-dog-g3", "domain": "LIVING_THINGS", "topic": "askal native filipino dog", "grades": [3, 4, 5], "terms": ["askal", "asong kalye", "iro sa dalan", "native dog", "aspin", "Filipino dog", "alagang hayop", "binuhing mananap", "pet", "matalino", "maugdang", "loyal", "tapat", "matinabangon", "mammal", "mamalya", "tahol", "usig"], "fact": {"tl": "Ang askal o aspin ay ang katutubong asong Pilipino na hindi tiyak ang lahi, at kilala itong matalino, matibay, at tapat na alagang hayop.", "en": "The askal (aspin) is the native Filipino dog of mixed breed, and it is known for being smart, hardy, and a loyal pet.", "bis": "Ang askal o aspin mao ang lumad nga iro sa Pilipinas nga sagol og kaliwat, ug ilado kini nga maalamon, lig-on, ug matinud-anon nga binuhing mananap."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bacterial-cell-diagram-g8", "domain": "LIVING_THINGS", "topic": "parts of a bacterial cell", "grades": [7, 8, 9, 10], "terms": ["bacteria", "bakterya", "bacterial cell", "selula sa bakterya", "cell wall", "pader ng selula", "bungbong sa selula", "flagellum", "buntot", "ikog", "DNA", "walang nucleus", "walay nucleus", "no nucleus", "prokaryote", "isang selula", "mikrobyo"], "fact": {"tl": "Ang selula ng bakterya ay napaliligiran ng matibay na cell wall at karaniwang may parang-buntot na flagellum para makagalaw, ngunit wala itong nucleus kaya nakalutang lamang ang DNA nito sa loob.", "en": "A bacterial cell is wrapped in a tough cell wall and often has a tail-like flagellum to move, but it has no nucleus, so its DNA simply floats inside.", "bis": "Ang selula sa bakterya gilibutan sa lig-on nga cell wall ug sagad may murag-ikog nga flagellum aron makalihok, apan wala kini'y nucleus busa naglutaw lang ang DNA niini sa sulod."}, "source": "AAAS Benchmarks (cells); NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "bacteria-shapes-three-types-g7", "domain": "LIVING_THINGS", "topic": "three shapes of bacteria", "grades": [6, 7, 8], "terms": ["bacteria", "bakterya", "bacteria shapes", "hugis", "porma", "bilog", "lingin", "cocci", "round", "stick", "bacilli", "baras", "patpat-patpat", "rod", "spiral", "pilipit", "kulot", "spirilla", "mikrobyo", "microscope"], "fact": {"tl": "Ang bakterya ay may tatlong pangunahing hugis: bilog (cocci), hugis-patpat (bacilli), at pilipit o parang-spring (spirilla).", "en": "Bacteria come in three main shapes: round ones (cocci), rod-shaped ones (bacilli), and spiral or corkscrew ones (spirilla).", "bis": "Ang bakterya may tulo ka nag-unang porma: lingin (cocci), porma-baras (bacilli), ug pilipit o murag-spring (spirilla)."}, "source": "AAAS Benchmarks (cells); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "backyard-pig-pen-scene-g4", "domain": "LIVING_THINGS", "topic": "pigs as backyard farm livestock", "grades": [3, 4, 5], "terms": ["baboy", "babuyan", "kulungan ng baboy", "alaga", "hayop sa bakuran", "babuy", "alima", "kulungan", "pig", "pig pen", "backyard livestock", "raising pigs", "omnivore"], "fact": {"tl": "Ang baboy ay alagang hayop sa bakuran na kumakain ng halos lahat—tira-tirang pagkain, gulay, at darak—kaya madali itong alagaan para gawing karne.", "en": "The pig is a backyard farm animal that eats almost anything—food scraps, vegetables, and bran—making it easy to raise for meat.", "bis": "Ang baboy usa ka binuhi nga hayop sa luyo sa balay nga mokaon sa halos tanan—sobra nga pagkaon, utanon, ug tahup—busa sayon ni alimahan para himuong karne."}, "source": "encyclopedia-stable consensus; DepEd MATATAG Science (animals and uses)", "generator": "claude-workflow", "reviewed": false},
  {"id": "balanced-meal-tray-school-g4", "domain": "LIVING_THINGS", "topic": "balanced diet food groups", "grades": [3, 4, 5], "terms": ["timbang na pagkain", "masustansyang pagkain", "Go Grow Glow", "kanin", "gulay", "prutas", "karne", "balanseng diyeta", "timbang nga pagkaon", "utanon", "balanced meal", "balanced diet", "nutrition", "food groups", "healthy plate"], "fact": {"tl": "Ang timbang na pagkain ay may kanin o tinapay para sa lakas, karne o isda para sa paglaki, at gulay't prutas para manatiling malusog ang katawan.", "en": "A balanced meal has rice or bread for energy, meat or fish for growth, and vegetables and fruits to keep the body healthy.", "bis": "Ang timbang nga pagkaon adunay kan-on o tinapay para sa kusog, karne o isda para sa pagtubo, ug utanon ug prutas aron magpabiling himsog ang lawas."}, "source": "DepEd MATATAG Science (nutrition); NRC LS1.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "atlas-moth-giant-g6", "domain": "LIVING_THINGS", "topic": "atlas moth, one of the largest moths", "grades": [5, 6, 7], "terms": ["atlas moth", "gamu-gamo", "higanteng gamu-gamo", "paru-parong gabi", "anik-anik", "alibangbang sa gabi", "dako nga gamu-gamo", "atlas moth", "giant moth", "wingspan", "Saturniidae", "Asia"], "fact": {"tl": "Ang atlas moth ay isa sa pinakamalaking gamu-gamo sa mundo, na ang lapad ng pakpak ay umaabot ng halos 25 sentimetro, at matatagpuan sa mga kagubatan ng Asya kasama ang Pilipinas.", "en": "The atlas moth is one of the world's largest moths, with a wingspan reaching nearly 25 centimeters, and it lives in the forests of Asia including the Philippines.", "bis": "Ang atlas moth usa sa pinakadako nga gamu-gamo sa kalibutan, nga ang gilapdon sa pako moabot ug halos 25 sentimetro, ug makit-an sa kalasangan sa Asya lakip ang Pilipinas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ball-socket-joint-hip-g7", "domain": "LIVING_THINGS", "topic": "ball-and-socket joint of the hip", "grades": [6, 7, 8], "terms": ["kasukasuan", "balikat", "balakang", "buko-buko", "ball and socket", "lutahan", "abaga", "paa-paa", "ball-and-socket joint", "hip joint", "shoulder", "rotation", "skeletal system"], "fact": {"tl": "Ang balakang at balikat ay may ball-and-socket na kasukasuan, kung saan ang bilog na dulo ng buto ay pumapasok sa lukong na hugis-mangkok, kaya nakakaikot ang braso o binti sa maraming direksyon.", "en": "The hip and shoulder have ball-and-socket joints, where the round end of one bone fits into a cup-shaped hollow, letting the arm or leg rotate in many directions.", "bis": "Ang balikawang ug abaga adunay ball-and-socket nga lutahan, diin ang lingin nga tumoy sa bukog mosulod sa hugis-yahong nga lungag, mao nga makatuyok ang bukton o paa sa daghang direksyon."}, "source": "encyclopedia-stable consensus; NRC LS1.A (body systems)", "generator": "claude-workflow", "reviewed": false},
  {"id": "balete-tree-g6", "domain": "LIVING_THINGS", "topic": "balete (Philippine banyan/strangler fig)", "grades": [5, 6, 7], "terms": ["balete", "punong balete", "ugat na nakabitin", "matandang puno", "kahoy nga balete", "Ficus", "balete tree", "banyan", "strangler fig", "aerial roots", "Philippines"], "fact": {"tl": "Ang balete ay isang malaking punong Pilipino na nagpapalaylay ng mga ugat mula sa mga sanga nito pababa sa lupa, kaya lumalaki ito at nagiging napakalapad sa paglipas ng panahon.", "en": "The balete is a large Philippine tree that drops aerial roots from its branches down to the ground, letting it spread and grow very wide over time.", "bis": "Ang balete usa ka dako nga kahoy sa Pilipinas nga nagpatunghay ug mga gamot gikan sa mga sanga paubos sa yuta, mao nga nagkadako ug nagkalapad kini sa paglabay sa panahon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ball-socket-vs-hinge-joints-g7", "domain": "LIVING_THINGS", "topic": "comparing ball-and-socket and hinge joints", "grades": [6, 7, 8], "terms": ["kasukasuan", "hinge joint", "ball and socket", "tuhod", "siko", "balikat", "lutahan", "abaga", "hinge joint", "ball-and-socket joint", "knee", "elbow", "joint movement"], "fact": {"tl": "Ang hinge na kasukasuan tulad ng tuhod at siko ay yumuyuko't umuunat lamang sa isang direksyon, samantalang ang ball-and-socket tulad ng balikat ay nakakaikot sa lahat ng direksyon.", "en": "A hinge joint like the knee and elbow bends and straightens in only one direction, while a ball-and-socket joint like the shoulder can rotate in all directions.", "bis": "Ang hinge nga lutahan sama sa tuhod ug siko moliko ug motuy-od lang sa usa ka direksyon, samtang ang ball-and-socket sama sa abaga makatuyok sa tanang direksyon."}, "source": "encyclopedia-stable consensus; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "bamboo-grove-g5", "domain": "LIVING_THINGS", "topic": "bamboo, a fast-growing giant grass", "grades": [4, 5, 6], "terms": ["kawayan", "kawayanan", "damo", "mabilis tumubo", "kabugangan", "bamboo", "bamboo grove", "giant grass", "fast-growing", "hollow stem"], "fact": {"tl": "Ang kawayan ay isang higanteng damo na may guwang na tangkay, isa ito sa pinakamabilis tumubong halaman sa mundo, at ginagamit sa Pilipinas para sa bahay, kasangkapan, at pagkain.", "en": "Bamboo is a giant grass with a hollow stem, one of the fastest-growing plants in the world, used in the Philippines for houses, tools, and food.", "bis": "Ang kawayan usa ka higante nga sagbot nga adunay guwang nga punoan, usa sa pinakapaspas motubo nga tanom sa kalibutan, ug gamiton sa Pilipinas para sa balay, galamiton, ug pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "balimbing-starfruit-g5", "domain": "LIVING_THINGS", "topic": "balimbing (starfruit)", "grades": [4, 5, 6], "terms": ["balimbing", "prutas na hugis-bituin", "maasim", "starfruit", "carambola", "prutas", "aslom", "star fruit", "five-ridged fruit"], "fact": {"tl": "Ang balimbing ay isang prutas na may limang gilid, kaya kapag hiniwa ay parang hugis-bituin, at ito'y maasim hanggang matamis kapag hinog.", "en": "The balimbing or starfruit has five ridges, so a slice looks like a star, and it tastes sour to sweet when ripe.", "bis": "Ang balimbing usa ka prutas nga adunay lima ka kilid, busa kung tagudtagoron daw hugis-bituon, ug aslom ngadto sa tam-is kung hinog na."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "basil-balanoy-g5", "domain": "LIVING_THINGS", "topic": "basil (balanoy) herb", "grades": [4, 5, 6], "terms": ["balanoy", "basil", "halamang gamot", "pampalasa", "mabangong dahon", "humot nga dahon", "herb", "aromatic leaves", "Ocimum"], "fact": {"tl": "Ang balanoy o basil ay isang mabangong halamang-gamot na ang mga dahon ay ginagamit na pampalasa sa pagkain at panlunas sa mga karaniwang sakit.", "en": "Basil, called balanoy, is a fragrant herb whose leaves are used to flavor food and as a folk remedy for common ailments.", "bis": "Ang balanoy o basil usa ka humot nga tanom-tambal nga ang mga dahon gamiton isip pampalami sa pagkaon ug tambal sa kasagarang sakit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "banyan-strangler-fig-g6", "domain": "LIVING_THINGS", "topic": "banyan / strangler fig growth habit", "grades": [5, 6, 7], "terms": ["balete", "strangler fig", "banyan", "ugat na bumabalot", "puno", "kahoy", "gamot", "host tree", "aerial roots"], "fact": {"tl": "Ang strangler fig o banyan ay tumutubo muna sa ibang puno, ibinababa ang mga ugat nito hanggang sa lupa, at unti-unting binabalutan ang punong sinasakyan nito.", "en": "The strangler fig or banyan starts growing on another tree, sends roots down to the ground, and slowly wraps around its host tree.", "bis": "Ang strangler fig o banyan magsugod ug tubo sa laing kahoy, ipakanaog ang mga gamot ngadto sa yuta, ug hinay-hinay nga libuton ang kahoy nga gisakyan niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "barnacle-cluster-g6", "domain": "LIVING_THINGS", "topic": "barnacles, shelled marine animals", "grades": [5, 6, 7], "terms": ["barnacle", "kabibi sa bato", "nagkakapit na hayop sa bato", "kapit sa bato", "hayop sa dagat", "crustacean", "intertidal", "filter feeder", "attaches to rocks"], "fact": {"tl": "Ang barnacle ay isang maliit na hayop-dagat na may matigas na balat na nakakapit nang husto sa mga bato, barko, at kabibe, at sumasala ng pagkain mula sa tubig.", "en": "A barnacle is a small sea animal with a hard shell that cements itself tightly to rocks, ships, and shells, and filters food from the water.", "bis": "Ang barnacle usa ka gamay nga hayop sa dagat nga adunay gahi nga panit nga mokapyot pag-ayo sa mga bato, barko, ug kabhang, ug mosala ug pagkaon gikan sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "barracuda-rumpe-g6", "domain": "LIVING_THINGS", "topic": "barracuda, a fast predatory fish", "grades": [5, 6, 7], "terms": ["rumpe", "barracuda", "isdang mabangis", "mabilis na isda", "matalas na ngipin", "isda", "kusog molangoy", "predatory fish", "sharp teeth", "reef fish"], "fact": {"tl": "Ang barracuda o rumpe ay isang mahaba at mabilis na isdang-dagat na may matatalas na ngipin, at naninila ito ng mas maliliit na isda sa mga bahura.", "en": "The barracuda is a long, fast sea fish with sharp teeth that hunts smaller fish around reefs.", "bis": "Ang barracuda o rumpe usa ka taas ug paspas nga isda sa dagat nga adunay hait nga ngipon, ug mangayam kini sa gagmay nga isda sa mga bahura."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "banana-plantation-scene-g5", "domain": "LIVING_THINGS", "topic": "banana plant and plantation", "grades": [4, 5, 6], "terms": ["saging", "taniman ng saging", "punong saging", "puso ng saging", "prutas", "tanaman sa saging", "puso", "banana", "banana plantation", "herb plant", "tropical fruit"], "fact": {"tl": "Ang saging ay tumutubo sa isang malaking halamang hindi tunay na puno, at ang Pilipinas ay isa sa mga pangunahing nagluluwas ng saging sa mundo.", "en": "Bananas grow on a large plant that is not a true tree, and the Philippines is one of the world's leading banana exporters.", "bis": "Ang saging motubo sa usa ka dako nga tanom nga dili tinuod nga kahoy, ug ang Pilipinas usa sa mga nag-unang tigbaligya ug saging sa kalibutan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "banaba-tree-g6", "domain": "LIVING_THINGS", "topic": "banaba tree, native Philippine flowering tree", "grades": [5, 6, 7], "terms": ["banaba", "punong banaba", "lila na bulaklak", "halamang gamot", "kahoy nga banaba", "bulak nga lila", "Lagerstroemia", "purple flowers", "medicinal tree", "native tree"], "fact": {"tl": "Ang banaba ay isang katutubong punong Pilipino na may magagandang lilang bulaklak, at ang mga dahon nito ay matagal nang ginagamit na panghalo sa tsaa na panlunas.", "en": "The banaba is a native Philippine tree with showy purple flowers, and its leaves have long been brewed into a medicinal tea.", "bis": "Ang banaba usa ka lumad nga kahoy sa Pilipinas nga adunay nindot nga lila nga bulak, ug ang mga dahon niini dugay nang gigamit isip tsa nga tambal."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bataw-hyacinth-bean-g6", "domain": "LIVING_THINGS", "topic": "bataw (hyacinth bean)", "grades": [5, 6, 7], "terms": ["bataw", "patani-patani", "gulay na sitsaro", "baging", "balatong", "gulay", "hyacinth bean", "lablab bean", "climbing legume", "edible pods"], "fact": {"tl": "Ang bataw o hyacinth bean ay isang gumagapang na halamang gulay na ang mga lapad na buto't supot ay nilulutong ulam kapag bata pa at malambot.", "en": "Bataw or hyacinth bean is a climbing vegetable vine whose flat pods and seeds are cooked as food while young and tender.", "bis": "Ang bataw o hyacinth bean usa ka nagakatay nga tanom-utanon nga ang lapad nga liso ug sumpot lutoon nga sud-an samtang batan-on pa ug humok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "barn-owl-kuwago-puso-g6", "domain": "LIVING_THINGS", "topic": "barn owl, heart-faced nocturnal hunter", "grades": [5, 6, 7], "terms": ["kuwago", "barn owl", "ibong nangangaso sa gabi", "mukhang puso", "naninila ng daga", "ngiwngiw", "langgam sa gabi", "nocturnal", "heart-shaped face", "rodent hunter", "raptor"], "fact": {"tl": "Ang barn owl o kuwago ay isang ibong nangangaso sa gabi na may mukhang hugis-puso, at malaking tulong ito sa magsasaka dahil kumakain ito ng mga daga.", "en": "The barn owl is a night-hunting bird with a heart-shaped face, and it helps farmers greatly by eating rats and mice.", "bis": "Ang barn owl o ngiwngiw usa ka langgam nga mangayam sa gabii nga adunay hugis-kasingkasing nga nawong, ug dako kini ug tabang sa mag-uuma kay mokaon kini ug ilaga."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bat-pollination-night-flower-scene-g7", "domain": "LIVING_THINGS", "topic": "bat pollination of night-blooming flowers", "grades": [6, 7, 8], "terms": ["paniki", "polinasyon", "bulaklak na namumukadkad sa gabi", "pagbalisbis ng polen", "kabog", "pollination", "bulak sa gabii", "nocturnal flowers", "nectar", "pollinator"], "fact": {"tl": "May mga bulaklak na namumukadkad lamang sa gabi at umaakit ng mga paniki na umiinom ng nektar, at sa paglipat ng paniki ay dala nito ang polen para magkabunga ang halaman.", "en": "Some flowers bloom only at night and attract nectar-drinking bats, which carry pollen from flower to flower so the plants can make fruit.", "bis": "Adunay mga bulak nga mobukhad lang sa gabii ug modani ug mga kabog nga moinom ug nektar, ug sa paglupad sa kabog madala niini ang polen aron mamunga ang tanom."}, "source": "encyclopedia-stable consensus; NRC LS2.A (interdependence)", "generator": "claude-workflow", "reviewed": false},
  {"id": "bean-germination-jar-experiment-g4", "domain": "LIVING_THINGS", "topic": "seed germination in a jar", "grades": [3, 4, 5], "terms": ["pagtubo ng buto", "germinasyon", "binhi", "ugat", "tangkay", "pagtubo sa liso", "gamot", "saha", "seed germination", "sprouting", "root", "shoot", "bean experiment"], "fact": {"tl": "Kapag binasa ang buto ng monggo sa isang garapon, ito'y sumisibol—unang lumalabas ang ugat pababa, tapos ang tangkay paitaas—na nagpapakita kung paano nagsisimula ang buhay ng halaman.", "en": "When a bean seed is kept moist in a jar, it germinates—the root grows down first, then the shoot grows up—showing how a plant's life begins.", "bis": "Kung basaon ang liso sa monggos sulod sa garapon, moturok kini—una mogawas ang gamot paubos, dayon ang saha paitaas—nga nagpakita kung giunsa pagsugod ang kinabuhi sa tanom."}, "source": "DepEd MATATAG Science (plant growth); NRC LS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "bell-pepper-atsal-g4", "domain": "LIVING_THINGS", "topic": "bell pepper (atsal) as a fruit-vegetable", "grades": [3, 4, 5], "terms": ["atsal", "kampanang siling", "bell pepper", "gulay", "hugis-kampana", "kampana nga sili", "sweet pepper", "fruit vegetable", "vitamin C"], "fact": {"tl": "Ang atsal o bell pepper ay isang hugis-kampanang gulay na hindi maanghang, may buto sa loob, at mayaman sa bitamina C.", "en": "The bell pepper, or atsal, is a bell-shaped vegetable that is not spicy, has seeds inside, and is rich in vitamin C.", "bis": "Ang atsal o bell pepper usa ka hugis-kampana nga utanon nga dili halang, adunay liso sa sulod, ug daghan ug bitamina C."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "beetle-g5", "domain": "LIVING_THINGS", "topic": "beetles, insects with hardened wing covers", "grades": [4, 5, 6], "terms": ["salagubang", "uang", "insekto", "bakukang", "beetle", "elytra", "hard wing covers", "Coleoptera"], "fact": {"tl": "Ang salagubang ay isang insektong may matigas na pantakip-pakpak na nagpoprotekta sa malambot na pakpak sa ilalim, at ito ang pinakamaraming uri ng hayop sa mundo.", "en": "A beetle is an insect with hard wing covers that protect the soft flying wings underneath, and beetles are the most numerous kind of animal on Earth.", "bis": "Ang salagubang usa ka insekto nga adunay gahi nga pantabon sa pako nga manalipod sa humok nga pako sa ilalom, ug kini ang pinakadaghang matang sa hayop sa kalibutan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "biking-for-fitness-g5", "domain": "LIVING_THINGS", "topic": "exercise such as biking benefits the body", "grades": [4, 5, 6], "terms": ["pagbibisikleta", "ehersisyo", "kalusugan", "puso", "lakas ng kalamnan", "pagbisikleta", "himsog", "kasingkasing", "biking", "cycling", "exercise", "fitness", "heart health"], "fact": {"tl": "Ang pagbibisikleta ay isang ehersisyong nagpapalakas sa puso, baga, at kalamnan ng binti, kaya nananatiling malusog at malakas ang katawan.", "en": "Biking is exercise that strengthens the heart, lungs, and leg muscles, keeping the body healthy and fit.", "bis": "Ang pagbisikleta usa ka ehersisyo nga nagpalig-on sa kasingkasing, baga, ug kaunoran sa paa, busa magpabiling himsog ug kusgan ang lawas."}, "source": "DepEd MATATAG Science (health and fitness); NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "betel-nut-palm-bunga-g6", "domain": "LIVING_THINGS", "topic": "betel nut palm (bunga / areca)", "grades": [5, 6, 7], "terms": ["bunga", "areca palm", "nganga", "punong niyog-niyugan", "buyo", "lubi nga bunga", "betel nut", "areca nut", "palm tree"], "fact": {"tl": "Ang bunga o betel nut palm ay isang matangkad na palmera na ang prutas ay nginunguya ng ilang matatanda kasama ng dahon ng ikmo bilang tradisyong nganga.", "en": "The betel nut palm, or bunga, is a tall palm whose nut is chewed by some elders together with betel leaf in the tradition of nganga.", "bis": "Ang bunga o betel nut palm usa ka taas nga palmera nga ang bunga ginausap sa pipila ka tigulang uban sa dahon sa buyo isip tradisyon nga mama."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "betel-leaf-ikmo-g6", "domain": "LIVING_THINGS", "topic": "betel leaf (ikmo / buyo) vine", "grades": [5, 6, 7], "terms": ["ikmo", "buyo", "betel leaf", "dahon na pang-nganga", "baging", "dahon nga mama", "betel vine", "Piper betle", "heart-shaped leaf"], "fact": {"tl": "Ang ikmo o buyo ay isang gumagapang na halaman na may makinis at hugis-pusong dahon, at ito ang ibinabalot sa bunga sa tradisyong nganga.", "en": "Betel leaf, or ikmo, is a climbing vine with smooth heart-shaped leaves, used to wrap the betel nut in the chewing tradition.", "bis": "Ang ikmo o buyo usa ka nagakatay nga tanom nga adunay hamis ug hugis-kasingkasing nga dahon, ug kini ang iputos sa bunga sa tradisyon nga mama."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "binary-fission-bacteria-g8", "domain": "LIVING_THINGS", "topic": "binary fission in bacteria", "grades": [7, 8, 9, 10], "terms": ["binary fission", "paghahati ng bakterya", "pagpaparami", "isang selula", "bakterya", "pagpilo", "pagdaghan", "bacteria reproduction", "asexual reproduction", "cell division"], "fact": {"tl": "Ang bakterya ay nagpaparami sa pamamagitan ng binary fission—hinahati nito ang sarili sa dalawang magkaparehong selula—kaya napakabilis nilang dumami.", "en": "Bacteria reproduce by binary fission—one cell splits into two identical cells—which lets their numbers grow very quickly.", "bis": "Ang bakterya modaghan pinaagi sa binary fission—mobahin ang usa ka selula ngadto sa duha ka managsama nga selula—mao nga paspas kaayo sila modaghan."}, "source": "encyclopedia-stable consensus; NRC LS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "body-outline-front-g4", "domain": "LIVING_THINGS", "topic": "external parts of the human body", "grades": [3, 4, 5], "terms": ["bahagi ng katawan", "ulo", "katawan", "braso", "binti", "bahin sa lawas", "bukton", "paa", "body parts", "human body", "external body parts", "head trunk limbs"], "fact": {"tl": "Ang katawan ng tao ay may mga panlabas na bahagi tulad ng ulo, katawan, dalawang braso, at dalawang binti, na bawat isa ay may sariling tungkulin.", "en": "The human body has external parts such as the head, trunk, two arms, and two legs, each with its own job.", "bis": "Ang lawas sa tawo adunay panggawas nga mga bahin sama sa ulo, lawas, duha ka bukton, ug duha ka paa, nga ang matag usa adunay kaugalingong buluhaton."}, "source": "DepEd MATATAG Science (parts of the body); NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "bougainvillea-g5", "domain": "LIVING_THINGS", "topic": "bougainvillea ornamental plant", "grades": [4, 5, 6], "terms": ["bougainvillea", "halamang-palamuti", "makulay na dahon", "bulaklak", "kolorado nga dahon", "ornamental plant", "colorful bracts", "thorny vine"], "fact": {"tl": "Ang bougainvillea ay isang halamang-palamuti na ang makukulay na bahagi ay tunay na mga espesyal na dahon na tinatawag na bracts, hindi ang maliit na puting bulaklak sa gitna.", "en": "Bougainvillea is an ornamental plant whose colorful parts are really special leaves called bracts, not the tiny white flowers in their center.", "bis": "Ang bougainvillea usa ka tanom-pangdayandayan nga ang mahayag nga mga bahin sa tinuod mao ang espesyal nga mga dahon nga gitawag ug bracts, dili ang gagmay nga puti nga bulak sa tunga."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "composting-pit-backyard-g6", "domain": "EARTH_SPACE", "topic": "composting decomposes waste into soil nutrients", "grades": [5, 6, 7], "terms": ["compost", "pagbubulok", "abono", "basurang nabubulok", "lupa", "kompos", "pagkadunot", "yuta", "composting", "decomposition", "decomposers", "organic waste", "nutrient recycling"], "fact": {"tl": "Sa compost pit, ang mga tira-tirang pagkain at dahon ay binubulok ng mga maliliit na organismo, kaya nagiging mayamang abono na nagpapataba sa lupa.", "en": "In a compost pit, food scraps and leaves are broken down by tiny organisms, turning into rich fertilizer that nourishes the soil.", "bis": "Sa compost pit, ang sobra nga pagkaon ug mga dahon dunoton sa gagmay nga mga organismo, busa mahimong dato nga abono nga magpatambok sa yuta."}, "source": "NRC LS2.B (cycles of matter); DepEd MATATAG Science (decomposition)", "generator": "claude-workflow", "reviewed": false},
  {"id": "drying-hands-clean-cloth-g4", "domain": "LIVING_THINGS", "topic": "drying hands to stay clean and healthy", "grades": [3, 4, 5], "terms": ["pagpunas ng kamay", "malinis na tela", "kalinisan", "mikrobyo", "kalusugan", "pagpahid sa kamot", "limpyo nga panapton", "kahinlo", "drying hands", "hygiene", "clean cloth", "germs", "handwashing"], "fact": {"tl": "Ang pagpunas ng kamay sa malinis na tela pagkatapos maghugas ay nakakatulong mapanatiling tuyo at malinis ang kamay, kaya hindi madaling kumapit ang mikrobyo.", "en": "Drying your hands on a clean cloth after washing keeps them dry and clean, so germs are less likely to cling to them.", "bis": "Ang pagpahid sa kamot sa limpyo nga panapton human manghugas makatabang nga magpabiling uga ug hinlo ang kamot, busa dili dali mokapyot ang mikrobyo."}, "source": "DepEd MATATAG Science (personal hygiene)", "generator": "claude-workflow", "reviewed": false},
  {"id": "drinking-water-during-play-g4", "domain": "LIVING_THINGS", "topic": "drinking water and hydration during activity", "grades": [3, 4, 5], "terms": ["pag-inom ng tubig", "uhaw", "pawis", "katawan", "paglalaro", "pag-inom ug tubig", "singot", "lawas", "drinking water", "hydration", "thirst", "sweat", "exercise"], "fact": {"tl": "Kapag naglalaro tayo at pinagpapawisan, nawawalan ng tubig ang katawan, kaya kailangang uminom ng tubig para hindi ma-uhaw at manatiling malakas.", "en": "When we play and sweat, the body loses water, so we need to drink water to avoid thirst and stay strong.", "bis": "Kung magdula kita ug magsingot, mawad-an ug tubig ang lawas, busa kinahanglan moinom ug tubig aron dili uhawon ug magpabiling kusgan."}, "source": "DepEd MATATAG Science (health and the body); NRC LS1.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "fire-ant-colony-single-g4", "domain": "LIVING_THINGS", "topic": "ant colony social insects", "grades": [3, 4, 5], "terms": ["fire ant", "hantik", "langgam", "ant", "colony", "kolonya", "reyna", "queen", "manggagawa", "worker", "hulmigas", "social insect", "pugad", "salag", "nest"], "fact": {"tl": "Ang mga langgam tulad ng fire ant ay nabubuhay sa isang kolonya kung saan ang reyna ay nangingitlog at libo-libong manggagawang langgam ang naghahanap ng pagkain at nag-aalaga sa pugad.", "en": "Ants such as fire ants live together in a colony where one queen lays the eggs while thousands of worker ants gather food and care for the nest.", "bis": "Ang mga hulmigas sama sa fire ant nagpuyo sa usa ka kolonya diin ang rayna mangitlog samtang liboan ka mamumuong hulmigas ang mangita ug pagkaon ug moatiman sa salag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fiddler-crab-talangka-g5", "domain": "LIVING_THINGS", "topic": "fiddler crab mangrove", "grades": [4, 5, 6], "terms": ["fiddler crab", "alimango", "crab", "bakawan", "bakhaw", "mangrove", "putik", "lapok", "mudflat", "malaking sipit", "big claw", "lalaki", "laki", "male", "lungga", "burrow"], "fact": {"tl": "Ang fiddler crab ay isang maliit na alimangong naninirahan sa putikan ng bakawan, at ang lalaki ay may isang napakalaking sipit na iwinawagayway nito para makaakit ng kapareha.", "en": "The fiddler crab is a small crab that lives in muddy mangrove flats, and the male has one greatly enlarged claw that it waves to attract a mate.", "bis": "Ang fiddler crab usa ka gamay nga alimango nga nagpuyo sa lapok sa bakhaw, ug ang laki adunay usa ka dako kaayo nga sipit nga iyang iwarawara aron makadani ug kapikas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "flying-fish-locale-g6", "domain": "LIVING_THINGS", "topic": "flying fish gliding", "grades": [5, 6, 7], "terms": ["flying fish", "barongoy", "bolador", "isda", "fish", "palikpik", "fins", "gliding", "lumilipad", "tumalon", "ambak", "dagat", "ocean", "manlulupad"], "fact": {"tl": "Ang flying fish ay isang isdang dagat na may malalapad na palikpik na parang pakpak, kaya naitatalon nito ang sarili sa tubig at nakakalipad-lipad ito para makatakas sa mga maninila.", "en": "The flying fish is a sea fish with wide, wing-like fins that let it leap from the water and glide through the air to escape predators.", "bis": "Ang flying fish usa ka isda sa dagat nga adunay halapad nga palikpik nga sama sa pako, mao nga makaambak kini gikan sa tubig ug makalupad-lupad aron makaikyas sa mga manunukob."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "flower-dissection-tray-g5", "domain": "LIVING_THINGS", "topic": "flower parts reproduction", "grades": [4, 5, 6], "terms": ["flower parts", "bahagi ng bulaklak", "bahin sa bulak", "talulot", "petal", "petalo", "stamen", "stigma", "pistil", "polen", "pollen", "ovary", "pollination", "polinasyon", "reproduction"], "fact": {"tl": "Ang bulaklak ay may iba't ibang bahagi: ang makukulay na talulot na umaakit ng insekto, ang stamen na gumagawa ng polen, at ang pistil na tatanggap ng polen para magbunga.", "en": "A flower has different parts: colorful petals that attract insects, the stamen that makes pollen, and the pistil that receives pollen so the plant can make seeds.", "bis": "Ang bulak adunay nagkalainlaing bahin: ang mabulokon nga petalo nga modani sa insekto, ang stamen nga maghimo ug polen, ug ang pistil nga modawat sa polen aron makamunga ang tanom."}, "source": "AAAS Benchmarks 5C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "foot-g4", "domain": "LIVING_THINGS", "topic": "human foot bones support", "grades": [3, 4, 5], "terms": ["foot", "paa", "tiil", "buto", "bukog", "bones", "kasukasuan", "lutahan", "joints", "daliri sa paa", "toes", "balanse", "balance", "paglakad", "walking", "support"], "fact": {"tl": "Ang paa ay may maraming maliliit na buto at kasukasuan na tumutulong sa atin na tumayo nang balanse, lumakad, at tumakbo.", "en": "The foot has many small bones and joints that help us stand with balance, walk, and run.", "bis": "Ang tiil adunay daghang gagmay nga bukog ug lutahan nga makatabang kanato sa pagtindog nga balanse, sa paglakaw, ug sa pagdagan."}, "source": "DepEd MATATAG Science (human body); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "germination-cup-row-conditions-g5", "domain": "LIVING_THINGS", "topic": "seed germination conditions", "grades": [4, 5, 6], "terms": ["germination", "pagtubo ng buto", "pagtubo sa liso", "binhi", "liso", "seed", "tubig", "water", "init", "kainit", "warmth", "hangin", "oxygen", "supang", "sprout", "usbong", "turok"], "fact": {"tl": "Para tumubo ang buto at maging supang, kailangan nito ng tubig, sapat na init, at hangin; kapag kulang ang isa sa mga ito, hindi ito sisibol.", "en": "For a seed to sprout and grow, it needs water, enough warmth, and air; if any one of these is missing, the seed will not germinate.", "bis": "Aron motubo ang liso ug mosupang, kinahanglan niini ang tubig, igong kainit, ug hangin; kung makulang ang usa niini, dili kini moturok."}, "source": "AAAS Benchmarks 5C; DepEd Science (plants)", "generator": "claude-workflow", "reviewed": false},
  {"id": "fruit-veggie-basket-full-g4", "domain": "LIVING_THINGS", "topic": "fruits vegetables nutrition", "grades": [3, 4, 5], "terms": ["fruits", "prutas", "vegetables", "gulay", "utanon", "bunga", "bitamina", "vitamins", "mineral", "nutrisyon", "nutrition", "malusog", "healthy", "himsog", "pagkain"], "fact": {"tl": "Ang mga prutas at gulay ay punong-puno ng bitamina at mineral na nagpapalakas ng katawan at tumutulong sa atin na manatiling malusog.", "en": "Fruits and vegetables are full of vitamins and minerals that strengthen the body and help us stay healthy.", "bis": "Ang mga prutas ug utanon puno sa bitamina ug mineral nga makapalig-on sa lawas ug makatabang kanato nga magpabiling himsog."}, "source": "DepEd MATATAG Science (nutrition); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gumamela-g5", "domain": "LIVING_THINGS", "topic": "gumamela hibiscus flower", "grades": [4, 5, 6], "terms": ["gumamela", "hibiscus", "bulaklak", "bulak", "flower", "halaman", "tanom", "shrub", "palumpong", "stamen", "polen", "pollination", "bubuyog", "bee", "talulot", "petalo"], "fact": {"tl": "Ang gumamela ay isang halamang-palumpong na may malalaki at makukulay na bulaklak, at madaling makita ang mahaba nitong stamen na may polen sa gitna ng talulot.", "en": "The gumamela (hibiscus) is a shrub with large, colorful flowers, and you can easily see its long stamen carrying pollen in the center of the petals.", "bis": "Ang gumamela usa ka palumpong nga adunay dagko ug mabulokon nga bulak, ug dali ra makita ang taas niini nga stamen nga nagdala ug polen sa tunga sa mga petalo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hamster-g4", "domain": "LIVING_THINGS", "topic": "hamster mammal cheek pouches", "grades": [3, 4, 5], "terms": ["hamster", "hayop", "mananap", "mammal", "rodent", "daga", "pisngi", "aping", "cheek pouch", "pagkain", "imbak", "store food", "alagang hayop", "pet", "lungga", "lungib"], "fact": {"tl": "Ang hamster ay isang maliit na hayop na may balahibo (mammal) na nag-iimbak ng pagkain sa kanyang malalaking pisngi para dalhin ito pabalik sa lungga nito.", "en": "The hamster is a small furry mammal that stores food in its big cheek pouches to carry it back to its burrow.", "bis": "Ang hamster usa ka gamay nga balhiboon nga mananap (mammal) nga magtipig ug pagkaon sa dagko niini nga aping aron dad-on kini balik sa iyang lungib."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "head-face-front-g4", "domain": "LIVING_THINGS", "topic": "head sense organs", "grades": [3, 4, 5], "terms": ["head", "ulo", "mukha", "face", "nawong", "mata", "eyes", "tainga", "dalunggan", "ears", "ilong", "nose", "bibig", "mouth", "dila", "pandama", "senses", "sense organs"], "fact": {"tl": "Sa ulo at mukha matatagpuan ang karamihan ng ating mga sangkap ng pandama—ang mata, tainga, ilong, at dila—na tumutulong sa atin na makakita, makarinig, makaamoy, at makalasa.", "en": "The head and face hold most of our sense organs—the eyes, ears, nose, and tongue—which help us see, hear, smell, and taste.", "bis": "Sa ulo ug nawong nahimutang ang kadaghanan sa atong mga organo sa pagbati—ang mata, dalunggan, ilong, ug dila—nga makatabang kanato sa pagtan-aw, pagpaminaw, pagsimhot, ug pagtilaw."}, "source": "DepEd MATATAG Science (sense organs); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "horseshoe-crab-katang-g6", "domain": "LIVING_THINGS", "topic": "horseshoe crab living fossil", "grades": [5, 6, 7], "terms": ["horseshoe crab", "katang", "crab", "living fossil", "alimango", "talukab", "shell", "buntot", "ikog", "tail", "dagat", "sea", "gagamba", "lawalawa", "spider", "alakdan", "tanga", "scorpion", "arthropod"], "fact": {"tl": "Ang horseshoe crab (katang) ay isang napakatandang uri ng hayop-dagat na may matigas na talukab at matulis na buntot, at hindi ito tunay na alimango kundi mas malapit sa gagamba at alakdan.", "en": "The horseshoe crab is a very ancient sea animal with a hard, dome-shaped shell and a pointed tail, and it is not a true crab but is more closely related to spiders and scorpions.", "bis": "Ang horseshoe crab (katang) usa ka karaan kaayo nga mananap sa dagat nga adunay gahi nga talukab ug talinis nga ikog, ug dili kini tinuod nga alimango kondili mas duol sa lawalawa ug tanga."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "jogging-in-park-scene-g4", "domain": "LIVING_THINGS", "topic": "exercise heart health", "grades": [3, 4, 5], "terms": ["jogging", "pagtakbo", "pagdagan", "ehersisyo", "exercise", "puso", "kasingkasing", "heart", "kalamnan", "kaunoran", "muscles", "kusog", "fitness", "malusog", "himsog", "lakas"], "fact": {"tl": "Ang regular na ehersisyo gaya ng jogging ay nagpapalakas ng puso at mga kalamnan, at nakatutulong para manatiling malusog at masigla ang katawan.", "en": "Regular exercise like jogging strengthens the heart and muscles and helps keep the body healthy and full of energy.", "bis": "Ang regular nga ehersisyo sama sa jogging makapalig-on sa kasingkasing ug sa mga kaunoran ug makatabang aron magpabiling himsog ug kusgan ang lawas."}, "source": "DepEd MATATAG Science (health and the body); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kangkong-g5", "domain": "LIVING_THINGS", "topic": "kangkong water spinach", "grades": [4, 5, 6], "terms": ["kangkong", "water spinach", "tangkong", "gulay", "utanon", "vegetable", "halaman", "tanom", "tubig", "water plant", "lumulutang", "lumutaw", "floating", "hungkag na tangkay", "hollow stem", "basa"], "fact": {"tl": "Ang kangkong ay isang gulay na tumutubo sa basa o mababaw na tubig, at may guwang (hungkag) na tangkay na tumutulong dito na lumutang sa ibabaw ng tubig.", "en": "Kangkong (water spinach) is a vegetable that grows in wet or shallow water, and its hollow stems help it float on the water's surface.", "bis": "Ang kangkong usa ka utanon nga motubo sa basa o mabaw nga tubig, ug ang bagahong (haw-ang) niini nga punoan makatabang niini sa paglutaw sa ibabaw sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kalachuchi-tree-cluster-g5", "domain": "LIVING_THINGS", "topic": "kalachuchi frangipani tree", "grades": [4, 5, 6], "terms": ["kalachuchi", "kalatsutsi", "frangipani", "plumeria", "puno", "tree", "kahoy", "bulaklak", "bulak", "flower", "mabango", "mahumot", "fragrant", "katas", "duga", "milky sap", "puti", "white"], "fact": {"tl": "Ang kalachuchi ay isang punong may mababangong puti o dilaw na bulaklak, at kapag naputol ang sanga nito ay lumalabas ang isang puti at malagkit na katas.", "en": "The kalachuchi (frangipani) is a tree with fragrant white or yellow flowers, and when a branch is cut it releases a white, sticky, milky sap.", "bis": "Ang kalachuchi usa ka kahoy nga adunay mahumot nga puti o dalag nga bulak, ug kung maputol ang sanga niini mogawas ang puti ug pilit nga gatas-gatas nga duga."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kelp-seaweed-bed-scene-g6", "domain": "LIVING_THINGS", "topic": "seaweed marine plants habitat", "grades": [5, 6, 7], "terms": ["seaweed", "lumot-dagat", "lusay", "guso", "algae", "alga", "dagat", "ocean", "tirahan", "puy-anan", "habitat", "kanlungan", "oksiheno", "oxygen", "isda", "fish shelter", "tubig-alat"], "fact": {"tl": "Ang mga lumot-dagat o seaweed ay tumutubo sa ilalim ng dagat at bumubuo ng makakapal na kama na nagbibigay ng pagkain, oksiheno, at kanlungan sa maraming isda at hayop-dagat.", "en": "Seaweeds grow underwater and form thick beds that provide food, oxygen, and shelter for many fish and sea animals.", "bis": "Ang mga lumot-dagat o seaweed motubo ilalom sa dagat ug maghimo ug baga nga kama nga maghatag ug pagkaon, oksiheno, ug puy-anan sa daghang isda ug mananap sa dagat."}, "source": "NRC LS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "leaf-g5", "domain": "LIVING_THINGS", "topic": "leaf photosynthesis food making", "grades": [4, 5, 6], "terms": ["leaf", "dahon", "halaman", "plant", "tanom", "photosynthesis", "potosintesis", "sikat ng araw", "kahayag sa adlaw", "sunlight", "chlorophyll", "luntian", "berde", "green", "pagkain", "food"], "fact": {"tl": "Ang dahon ay ang bahagi ng halaman na gumagawa ng pagkain nito sa pamamagitan ng sikat ng araw, tubig, at hangin sa proseso na tinatawag na potosintesis.", "en": "The leaf is the part of a plant that makes the plant's food using sunlight, water, and air in a process called photosynthesis.", "bis": "Ang dahon mao ang bahin sa tanom nga maghimo sa pagkaon niini pinaagi sa kahayag sa adlaw, tubig, ug hangin sa proseso nga gitawag ug potosintesis."}, "source": "AAAS Benchmarks 5E; NRC LS1.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "maya-perched-single-g5", "domain": "LIVING_THINGS", "topic": "maya bird eurasian tree sparrow", "grades": [4, 5, 6], "terms": ["maya", "maya bird", "sparrow", "ibon", "langgam", "bird", "kayumanggi", "tabunon", "brown", "palay", "humay", "rice", "butil", "lugas", "seeds", "liso", "bukid", "uma"], "fact": {"tl": "Ang maya ay isang maliit at kayumangging ibon na karaniwang nakikita sa mga bahay at bukid sa Pilipinas, at kumakain ito ng mga butil at buto tulad ng palay.", "en": "The maya is a small brown bird commonly seen around houses and fields in the Philippines, and it feeds on grains and seeds such as rice.", "bis": "Ang maya usa ka gamay ug pula-tabunon nga langgam nga kasagarang makita libot sa mga balay ug uma sa Pilipinas, ug mokaon kini ug mga lugas ug liso sama sa humay."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "millipede-antipuyo-g5", "domain": "LIVING_THINGS", "topic": "millipede many legs decomposer", "grades": [4, 5, 6], "terms": ["millipede", "antipuyo", "uod", "ulod", "maraming paa", "many legs", "tiil", "paa", "legs", "namumulutong", "molikos", "curl", "singsing", "dahong-bulok", "lupa", "soil", "arthropod"], "fact": {"tl": "Ang millipede (antipuyo) ay isang hayop na may napakaraming maliliit na paa, at kapag natakot ito ay namumulutong ito na parang singsing para protektahan ang sarili.", "en": "The millipede is an animal with very many tiny legs, and when frightened it curls up into a tight coil to protect itself.", "bis": "Ang millipede (antipuyo) usa ka mananap nga adunay daghan kaayo nga gagmay nga tiil, ug kung mahadlok kini molikos kini sama sa singsing aron mapanalipdan ang kaugalingon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "moss-g6", "domain": "LIVING_THINGS", "topic": "moss simple plant spores", "grades": [5, 6, 7], "terms": ["moss", "lumot", "halaman", "plant", "tanom", "spore", "spora", "walang ugat", "walay gamot", "no roots", "basa", "mahalumigmig", "moist", "bato", "rocks", "luntian", "berde", "green"], "fact": {"tl": "Ang lumot (moss) ay isang simpleng halamang walang tunay na ugat o bulaklak, tumutubo sa mga basa at malilim na lugar, at dumarami sa pamamagitan ng maliliit na spora sa halip na buto.", "en": "Moss is a simple plant without true roots or flowers; it grows in damp, shady places and reproduces using tiny spores instead of seeds.", "bis": "Ang lumot (moss) usa ka yano nga tanom nga walay tinuod nga gamot o bulak; motubo kini sa basa ug landong nga mga dapit ug modaghan pinaagi sa gagmay nga spora imbis liso."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "morning-bath-scene-g3", "domain": "LIVING_THINGS", "topic": "personal hygiene cleanliness germs", "grades": [3, 4, 5], "terms": ["bath", "paliligo", "ligo", "kaligo", "kalinisan", "hygiene", "kahinlo", "sabon", "soap", "mikrobyo", "germs", "bakterya", "bacteria", "sakit", "disease", "malusog", "himsog"], "fact": {"tl": "Ang regular na pagliligo gamit ang sabon at tubig ay nag-aalis ng dumi at mikrobyo sa balat, na nakakatulong upang hindi tayo magkasakit.", "en": "Bathing regularly with soap and water removes dirt and germs from the skin, which helps keep us from getting sick.", "bis": "Ang regular nga pagkaligo gamit ang sabon ug tubig magtangtang sa hugaw ug mikrobyo sa panit, nga makatabang aron dili kita masakit."}, "source": "DepEd MATATAG Science (health and hygiene); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mudskipper-tambasakan-g6", "domain": "LIVING_THINGS", "topic": "mudskipper amphibious fish mangrove", "grades": [5, 6, 7], "terms": ["mudskipper", "tambasakan", "tambasan", "isda", "fish", "bakawan", "bakhaw", "mangrove", "putik", "lapok", "mud", "tumalon", "ambak", "palikpik", "lumalakad", "lakaw", "breathe air", "hangin"], "fact": {"tl": "Ang mudskipper (tambasakan) ay isang kakaibang isda na kayang lumakad at tumalon sa putikan ng bakawan, at nakakahinga ito ng hangin habang nasa labas ng tubig.", "en": "The mudskipper is an unusual fish that can walk and hop across mangrove mudflats and can breathe air while out of the water.", "bis": "Ang mudskipper (tambasakan) usa ka talagsaon nga isda nga makalakaw ug makaambak sa lapok sa bakhaw, ug makaginhawa kini ug hangin samtang gawas sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ph-endemic-birds-collage-g6", "domain": "LIVING_THINGS", "topic": "philippine endemic birds biodiversity", "grades": [5, 6, 7], "terms": ["endemic birds", "katutubong ibon", "ibon", "langgam", "bird", "agila", "philippine eagle", "kalaw", "hornbill", "endemiko", "endemic", "Pilipinas", "biodiversity", "kagubatan", "lasang", "forest", "natatangi"], "fact": {"tl": "Maraming ibon sa Pilipinas, gaya ng Philippine Eagle at kalaw, ay endemiko—ibig sabihin matatagpuan lamang sila rito at wala sa ibang bansa.", "en": "Many birds in the Philippines, such as the Philippine Eagle and the hornbill, are endemic—meaning they are found only here and nowhere else in the world.", "bis": "Daghang langgam sa Pilipinas, sama sa Philippine Eagle ug kalaw, ang endemiko—nagpasabot nga makit-an lamang sila dinhi ug wala sa ubang nasod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ph-endemic-mammals-collage-g6", "domain": "LIVING_THINGS", "topic": "philippine endemic mammals biodiversity", "grades": [5, 6, 7], "terms": ["endemic mammals", "katutubong hayop", "tarsier", "mamalya", "mammal", "mananap", "tamaraw", "kalabaw ng Mindoro", "cloud rat", "endemiko", "endemic", "Pilipinas", "biodiversity", "kagubatan", "lasang", "natatangi"], "fact": {"tl": "Ang ilang mga hayop na may balahibo (mammal) sa Pilipinas, gaya ng tarsier at tamaraw, ay endemiko at matatagpuan lamang dito, kaya mahalaga silang pangalagaan.", "en": "Some mammals in the Philippines, such as the tarsier and the tamaraw, are endemic and found only here, so it is important to protect them.", "bis": "Ang ubang mga balhiboon nga mananap (mammal) sa Pilipinas, sama sa tarsier ug tamaraw, endemiko ug makit-an lamang dinhi, mao nga importante nga panalipdan sila."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "reef-fish-cleaning-station-scene-g7", "domain": "LIVING_THINGS", "topic": "cleaning station mutualism symbiosis", "grades": [6, 7, 8], "terms": ["cleaning station", "cleaner fish", "isdang taga-linis", "isdang tig-limpyo", "isda", "fish", "bahura", "coral reef", "parasito", "parasite", "symbiosis", "simbiyosis", "mutualism", "tulungan", "pagtinabangay", "naglilinis"], "fact": {"tl": "Sa mga bahura, may maliliit na isdang taga-linis na kumakain ng mga parasito at patay na balat ng mas malalaking isda; nakakakain ang maliit at nalilinis naman ang malaki—isang halimbawa ng tulungan sa kalikasan.", "en": "On coral reefs, small cleaner fish eat the parasites and dead skin off larger fish; the small fish gets a meal while the big fish gets cleaned—an example of two animals helping each other.", "bis": "Sa mga bahura, adunay gagmay nga isdang tig-limpyo nga mokaon sa mga parasito ug patay nga panit sa dagkong isda; makakaon ang gamay samtang malimpyohan ang dako—usa ka panig-ingnan sa pagtinabangay sa kinaiyahan."}, "source": "NRC LS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "reef-to-shore-connection-g6", "domain": "LIVING_THINGS", "topic": "coral reef and shore ecosystem connection", "grades": [5, 6, 7], "terms": ["bahura", "coral reef", "baybayin", "dalampasigan", "shore", "ecosystem", "sistema", "isda", "fish", "konektado", "konektado ang bahura", "konektado ang bahura sa baybayin", "balud", "alon", "wave", "habitat", "tirahan"], "fact": {"tl": "Ang bahura ng korales at ang baybayin ay magkakawing na ecosystem—pinipigilan ng bahura ang malalakas na alon habang nagbibigay ito ng tirahan sa mga isda na kinakain ng mga taong nasa pampang.", "en": "A coral reef and the nearby shore are linked ecosystems—the reef breaks strong waves while giving fish a home, and those fish feed the people living along the coast.", "bis": "Ang bahura sa korales ug ang baybayon nagkadugtong nga ecosystem—ginababagan sa bahura ang kusog nga balud samtang naghatag kini og puy-anan sa mga isda nga ginakaon sa mga tawo sa baybayon."}, "source": "NRC LS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rice-harvest-golden-field-g4", "domain": "LIVING_THINGS", "topic": "rice plant harvest life cycle", "grades": [3, 4, 5], "terms": ["palay", "rice", "bigas", "kanin", "ani", "anihin", "humay", "anihon", "harvest", "ginintuan", "golden", "bukid", "field", "uhay", "grain", "butil", "hinog", "luto", "hinog na palay", "magsasaka", "mag-uuma", "farmer"], "fact": {"tl": "Kapag naninilaw na at lumuluhod ang mga uhay ng palay sa bigat ng mga butil, ibig sabihin hinog na ito at handa nang anihin upang maging bigas.", "en": "When rice stalks turn golden and bend from the weight of their grains, it means the rice is ripe and ready to be harvested and milled into rice.", "bis": "Kon manggidalag na ug moduko ang mga uhay sa humay tungod sa kabug-at sa mga lugas, kini nagpasabot nga hinog na kini ug andam nang anihon aron mahimong bugas."}, "source": "DepEd G4 Life Science; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rice-transplanting-seedlings-g4", "domain": "LIVING_THINGS", "topic": "rice transplanting seedlings", "grades": [3, 4, 5], "terms": ["pagtatanim", "transplanting", "punla", "seedling", "palay", "rice", "humay", "tanim", "itanim", "itanom", "binhi", "pananom", "pilapil", "paddy", "tubig", "water", "magsasaka", "lipat-tanim", "binhing palay", "semilya"], "fact": {"tl": "Sa pagtatanim ng palay, inilipat ng magsasaka ang mga batang punla mula sa punlaan patungo sa basang pilapil na may tubig upang magkaroon ng sapat na espasyo ang bawat tanim na lumaki.", "en": "When planting rice, farmers move the young seedlings from a seedbed into a flooded paddy so each plant has enough room to grow.", "bis": "Sa pagtanom og humay, ginabalhin sa mag-uuma ang batan-ong mga punla gikan sa tampi ngadto sa basa nga pilapil nga may tubig aron makaangkon og igong luna ang matag tanom nga motubo."}, "source": "DepEd G4 Life Science; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rocky-shore-tidepool-g5", "domain": "LIVING_THINGS", "topic": "rocky shore tide pool habitat", "grades": [4, 5, 6], "terms": ["batuhang baybayin", "rocky shore", "tide pool", "tidepool", "danaw sa bato", "kati", "low tide", "taog", "naiwang tubig", "starfish", "alon", "balud", "kabibi", "shell", "danaw", "pool", "buhay-dagat"], "fact": {"tl": "Ang tide pool ay isang lawa ng tubig-dagat na naiiwan sa mga hukay ng bato kapag humuhupa ang tubig, at dito nagtatago ang mga maliliit na isda, hipon, at starfish hanggang bumalik ang alon.", "en": "A tide pool is a small pool of seawater left in rocky hollows when the tide goes out, where little fish, shrimp, and starfish shelter until the waves return.", "bis": "Ang tide pool usa ka gamay nga danaw sa tubig-dagat nga mabilin sa mga lungag sa bato kon mohubas ang dagat, ug didto magtago ang gagmay nga isda, pasayan, ug starfish hangtod mobalik ang balud."}, "source": "NRC LS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "santan-g4", "domain": "LIVING_THINGS", "topic": "santan flower nectar", "grades": [3, 4, 5], "terms": ["santan", "ixora", "bulaklak", "flower", "bulak", "nektar", "nectar", "tamis", "pulot", "paniki", "paru-paro", "butterfly", "alibangbang", "halaman", "tanom", "shrub", "palumpong", "pula", "red", "santan flower", "pollinator", "magsupsop"], "fact": {"tl": "Ang santan ay isang palumpong na namumulaklak ng maliliit na bulaklak na nakapumpon-pumpon, at ang matatamis na dulo ng bulaklak nito ay sinisipsip ng mga paru-paro at bata para sa nektar.", "en": "Santan (ixora) is a shrub that grows clusters of small flowers, and the sweet base of each bloom holds nectar that butterflies and curious children love to sip.", "bis": "Ang santan usa ka palumpong nga namulak og gagmay nga mga bulak nga nagpundok, ug ang tam-is nga tumoy sa matag bulak gisupsop sa mga alibangbang ug mga bata alang sa nektar."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "soil-decomposers-cross-section-g5", "domain": "LIVING_THINGS", "topic": "soil decomposers recycling nutrients", "grades": [4, 5, 6], "terms": ["lupa", "soil", "yuta", "decomposer", "mga tagapagpabulok", "tagabulok", "bulok", "bulok na dahon", "uod", "bulati", "earthworm", "fungi", "amag", "bakterya", "sustansya", "nutrient", "abono", "natural na pataba", "lupang malusog", "nagpapabulok", "buhay sa lupa"], "fact": {"tl": "Sa ilalim ng lupa, ang mga tagapagpabulok tulad ng mga uod, fungi, at bakterya ay sumisira sa mga patay na dahon at hayop, na nagbabalik ng sustansya sa lupa para muling tumubo ang mga halaman.", "en": "Underground, decomposers like earthworms, fungi, and bacteria break down dead leaves and animals, returning nutrients to the soil so new plants can grow.", "bis": "Sa ilawom sa yuta, ang mga tigpadunot sama sa bulati, fungi, ug bakterya magdunot sa patay nga mga dahon ug mananap, nga magbalik sa sustansiya ngadto sa yuta aron makatubo pag-usab ang mga tanom."}, "source": "NRC LS2.B; AAAS Benchmarks 5E", "generator": "claude-workflow", "reviewed": false},
  {"id": "stag-beetle-g5", "domain": "LIVING_THINGS", "topic": "stag beetle large jaws", "grades": [4, 5, 6], "terms": ["stag beetle", "salagubang", "uang", "bakukang", "sungay", "jaws", "panga", "panghang", "insekto", "insect", "kahoy", "wood", "bulok na kahoy", "rotting wood", "uok", "larva", "pakpak", "panga ng lalaki", "kagat", "lalaking stag beetle"], "fact": {"tl": "Ang stag beetle ay isang malaking salagubang na ang mga lalaki ay may matitigas na pangang kahawig ng sungay ng usa, na ginagamit nila sa pakikipaglaban sa ibang lalaki, hindi sa pangangagat ng tao.", "en": "The stag beetle is a large beetle whose males have huge antler-like jaws, which they use to wrestle other males rather than to bite people.", "bis": "Ang stag beetle usa ka dako nga salagubang nga ang mga laki adunay dagko nga panga nga morag sungay sa usa, nga ilang gigamit sa pakig-away sa ubang laki, dili sa pagpaak sa tawo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tooth-g4", "domain": "LIVING_THINGS", "topic": "tooth structure enamel", "grades": [3, 4, 5], "terms": ["ngipin", "tooth", "teeth", "ipon", "enamel", "esmalte", "ngumunguya", "chew", "ngata", "matigas", "hard", "bahagi ng katawan", "dentin", "gilingin", "pagkain", "food", "pinakamatigas", "proteksyon", "balat ng ngipin"], "fact": {"tl": "Ang ngipin ay tumutulong sa atin na ngumuya ng pagkain, at ang panlabas na balot nito na tinatawag na enamel ang pinakamatigas na bahagi ng buong katawan ng tao.", "en": "Teeth help us chew our food, and their outer coating, called enamel, is the hardest substance in the entire human body.", "bis": "Ang ngipon nagtabang nato sa pagusap sa pagkaon, ug ang panggawas nga sapaw niini nga ginatawag og enamel mao ang pinakagahi nga bahin sa tibuok lawas sa tawo."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "torso-organs-g6", "domain": "LIVING_THINGS", "topic": "torso houses vital organs", "grades": [5, 6, 7], "terms": ["torso", "katawan", "lawas", "dibdib", "tiyan", "puso", "heart", "kasingkasing", "baga", "lungs", "atay", "liver", "stomach", "organ", "bahagi ng loob", "tadyang", "ribs", "gusok", "protektado", "vital organs", "sistema ng katawan"], "fact": {"tl": "Ang torso o gitnang katawan ang nagtataglay ng mahahalagang organo tulad ng puso, baga, at atay, na pinoprotektahan ng mga buto ng dibdib na tinatawag na tadyang.", "en": "The torso, or middle of the body, holds vital organs like the heart, lungs, and liver, which are shielded by the chest bones called ribs.", "bis": "Ang torso o tungang lawas mao ang nagsulod sa importante nga mga organo sama sa kasingkasing, baga, ug atay, nga ginapanalipdan sa mga bukog sa dughan nga gitawag og gusok."}, "source": "NRC LS1.A; DepEd G6 Life Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "urban-park-greenspace-g5", "domain": "LIVING_THINGS", "topic": "urban park green space benefits", "grades": [4, 5, 6], "terms": ["parke", "park", "lungsod", "city", "siyudad", "lunti", "green space", "luntiang lugar", "puno", "tree", "kahoy", "hangin", "air", "presko", "lilim", "shade", "landong", "ibon", "bird", "oksiheno", "oxygen", "malinis na hangin", "parke sa lungsod"], "fact": {"tl": "Ang mga parke sa lungsod ay may mga puno na nagbibigay ng lilim, gumagawa ng oksiheno, at nagpapalamig sa mainit na lugar, kaya mas presko ang hangin sa paligid nito.", "en": "City parks have trees that give shade, make oxygen, and cool down hot areas, so the air around them feels fresher.", "bis": "Ang mga parke sa siyudad adunay mga kahoy nga naghatag og landong, naghimo og oksiheno, ug nagpabugnaw sa init nga dapit, busa mas presko ang hangin sa palibot niini."}, "source": "NRC ESS3.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "vertical-farm-tower-g6", "domain": "LIVING_THINGS", "topic": "vertical farming stacked crops", "grades": [5, 6, 7], "terms": ["vertical farm", "patayong sakahan", "patindog nga uma", "tore", "tower", "patong-patong", "stacked", "halaman", "gulay", "vegetable", "utanon", "ilaw", "light", "suga", "tubig", "water", "espasyo", "space", "lungsod", "city", "pagtatanim sa loob", "indoor farming", "sakahan"], "fact": {"tl": "Sa vertical farm, itinatanim ang mga halaman nang patong-patong sa mga istante sa loob ng gusali, gamit ang artipisyal na ilaw, upang makapagtanim ng maraming gulay kahit kakaunti lang ang lupa sa lungsod.", "en": "In a vertical farm, plants are grown in stacked shelves inside a building under artificial light, letting people raise lots of vegetables even where city land is scarce.", "bis": "Sa vertical farm, ang mga tanom ginatanom nga patong-patong sa mga estante sulod sa usa ka building ubos sa artipisyal nga suga, aron makatanom og daghang utanon bisan gamay ra ang yuta sa siyudad."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "balloon-air-pressure-g5", "domain": "MATTER", "topic": "inflated balloon and air pressure", "grades": [4, 5, 6], "terms": ["lobo", "balloon", "globo", "hangin", "air", "huyop", "hangin sa loob", "presyon", "pressure", "lumaki", "stretch", "binanat", "unat", "gas", "puwersa", "pumutok", "burst", "buga", "naiipit na hangin", "elastic"], "fact": {"tl": "Kapag hinipan mo ang lobo, naiipon sa loob ang hangin at itinutulak nito ang goma palabas sa lahat ng direksyon, kaya tumitigas at lumalaki ang lobo.", "en": "When you blow up a balloon, air collects inside and pushes the rubber outward in every direction, which is why the balloon grows firm and round.", "bis": "Kon imong huypan ang balloon, motipon ang hangin sa sulod ug iduso niini ang goma pagawas sa tanang direksyon, mao nga motig-a ug modako ang balloon."}, "source": "NRC PS1.A; AAAS Benchmarks 4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "bond-ionic-g8", "domain": "MATTER", "topic": "ionic bond electron transfer", "grades": [8, 9, 10], "terms": ["ionic bond", "bigkis na ayoniko", "ionic nga bond", "ion", "elektron", "electron", "metal", "non-metal", "asin", "salt", "sodium", "chloride", "pagbibigay ng elektron", "kuryenteng singil", "charge", "kabit", "nagbibigkis", "kristal", "crystal", "table salt", "naglilipat ng elektron"], "fact": {"tl": "Sa ionic bond, ibinibigay ng isang atom ang isa o higit pang elektron sa kabilang atom, kaya nagiging magkasalungat ang kanilang kuryenteng singil at naaakit sila sa isa't isa—gaya sa asin na sodium chloride.", "en": "In an ionic bond, one atom gives up one or more electrons to another, so the atoms gain opposite electric charges and attract each other—as in table salt, sodium chloride.", "bis": "Sa ionic bond, ang usa ka atomo mohatag og usa o daghang elektron sa laing atomo, mao nga magkaatbang ang ilang kuryente nga singil ug magkadani sila—sama sa asin nga sodium chloride."}, "source": "NRC PS1.A; DepEd G9 Chemistry", "generator": "claude-workflow", "reviewed": false},
  {"id": "bond-metallic-g9", "domain": "MATTER", "topic": "metallic bond sea of electrons", "grades": [9, 10], "terms": ["metallic bond", "bigkis na metaliko", "metallic nga bond", "metal", "metal nga butang", "elektron", "electron", "malayang elektron", "free electron", "kuryente", "electricity", "init", "conductor", "konduktor", "bakal", "tanso", "copper", "iron", "naghahatid ng kuryente", "dagat ng elektron"], "fact": {"tl": "Sa metallic bond, ang mga elektron sa labas ng mga atom ng metal ay malayang gumagalaw na parang dagat ng elektron, kaya ang mga metal ay mahusay na naghahatid ng kuryente at init.", "en": "In a metallic bond, the outer electrons of metal atoms move about freely like a sea of electrons, which is why metals conduct electricity and heat so well.", "bis": "Sa metallic bond, ang mga elektron sa gawas sa mga atomo sa metal molihok nga gawasnon nga morag dagat sa elektron, mao nga ang mga metal maayo nga maghatud sa kuryente ug kainit."}, "source": "NRC PS1.A; DepEd G9 Chemistry", "generator": "claude-workflow", "reviewed": false},
  {"id": "bread-dough-rising-yeast-g6", "domain": "MATTER", "topic": "yeast makes dough rise carbon dioxide", "grades": [5, 6, 7], "terms": ["lebadura", "yeast", "tinapay", "bread", "pan", "masa", "dough", "minasa", "umaalsa", "rising", "umalsa", "miburot", "lumaki", "carbon dioxide", "gas", "bula", "bubble", "fungi", "asukal", "sugar", "fermentation", "umaalsa ang masa", "panaderya"], "fact": {"tl": "Ang lebadura ay isang maliit na fungi na kumakain ng asukal sa masa at naglalabas ng gas na carbon dioxide, kaya pumupuno ng bula at umaalsa ang masa bago lutuin sa tinapay.", "en": "Yeast is a tiny fungus that feeds on sugar in dough and releases carbon dioxide gas, which fills the dough with bubbles and makes it rise before baking into bread.", "bis": "Ang lebadura usa ka gamay nga fungi nga mokaon sa asukal sa masa ug mobuga og gas nga carbon dioxide, mao nga mapuno og bula ug moburot ang masa una lutoon nga pan."}, "source": "NRC LS1.C; PS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "browning-cut-banana-g6", "domain": "MATTER", "topic": "cut fruit browning oxidation", "grades": [5, 6, 7], "terms": ["saging", "banana", "hinog", "hiniwa", "cut", "nangingitim", "browning", "naitom", "kayumanggi", "brown", "oksihenasyon", "oxidation", "hangin", "oxygen", "oksiheno", "enzyme", "prutas", "fruit", "nag-iiba ng kulay", "reaksyon", "calamansi", "nangingitim ang saging"], "fact": {"tl": "Kapag hiniwa ang saging o mansanas, nakikipagsama ang loob nito sa oksiheno sa hangin at nagdudulot ito ng kulay-kayumanggi—isang pagbabagong-kemikal na tinatawag na oksihenasyon.", "en": "When a banana or apple is cut, its exposed flesh reacts with oxygen in the air and turns brown—a chemical change called oxidation.", "bis": "Kon mahiwa ang saging o mansanas, ang sulod niini makig-uban sa oksiheno sa hangin ug mahimong brown—usa ka kemikal nga kausaban nga gitawag og oksidasyon."}, "source": "NRC PS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "buko-shake-suspension-g6", "domain": "MATTER", "topic": "buko shake as a suspension mixture", "grades": [5, 6, 7], "terms": ["buko shake", "suspension", "suspensyon", "buko", "young coconut", "lubi", "halo", "mixture", "sagol", "mga piraso", "particles", "lumulutang", "tumitining", "settle", "magkahalo", "gata", "hindi natutunaw", "tubig", "magkahalong likido at solido"], "fact": {"tl": "Ang buko shake ay isang suspension dahil ang maliliit na piraso ng buko ay nakalutang lamang sa likido at hindi natutunaw, kaya tumitining ang mga ito sa ilalim kapag iniwang nakatayo.", "en": "A buko shake is a suspension because the small bits of coconut are only floating in the liquid and do not dissolve, so they settle to the bottom if left standing.", "bis": "Ang buko shake usa ka suspension kay ang gagmay nga tipik sa lubi naglutaw lang sa likido ug dili matunaw, mao nga molugdang kini sa ilawom kon pasagdan nga magbarog."}, "source": "NRC PS1.A; DepEd G6 Matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "burong-isda-fermentation-g7", "domain": "MATTER", "topic": "buro fermentation preserves food", "grades": [6, 7, 8], "terms": ["buro", "burong isda", "fermentation", "pagbuburo", "pickling", "isda", "fish", "kanin", "rice", "asin", "salt", "bakterya", "bacteria", "preservation", "pag-iimbak", "hindi mabulok", "asim", "sour", "aslom", "naasim", "lactic acid", "nagpapaasim", "natural na preserbasyon"], "fact": {"tl": "Ang burong isda ay gawa sa isda at kanin na hinaluan ng asin at iniwang ferment, kung saan ang mabubuting bakterya ang gumagawa ng asim na pumipigil sa pagkabulok ng pagkain.", "en": "Buro is made from fish and rice mixed with salt and left to ferment, where helpful bacteria produce a sour acid that keeps the food from spoiling.", "bis": "Ang burong isda hinimo gikan sa isda ug kan-on nga gisagol og asin ug gipasagdang mo-ferment, diin ang maayong bakterya maghimo og aslom nga makapugong sa pagkadunot sa pagkaon."}, "source": "NRC LS1.C; PS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "calamansi-juice-mixing-g5", "domain": "MATTER", "topic": "dissolving calamansi juice in water solution", "grades": [4, 5, 6], "terms": ["kalamansi", "calamansi", "juice", "katas", "piniga", "squeezed", "pinuga", "tubig", "water", "tunaw", "dissolve", "natunaw", "matunaw", "solution", "solusyon", "sagol", "mixture", "magkahalo", "maasim", "asim", "aslom", "homogeneous", "pinaghalong likido"], "fact": {"tl": "Kapag pinipiga ang katas ng kalamansi sa tubig, kumakalat at nahahalo ito nang pantay sa buong tubig, kaya nagiging isang solution na pare-pareho ang lasa sa bawat patak.", "en": "When calamansi juice is squeezed into water, it spreads and mixes evenly throughout, forming a solution that tastes the same in every drop.", "bis": "Kon ipuga ang katas sa kalamansi ngadto sa tubig, mokatag ug masagol kini nga patas sa tibuok tubig, mao nga mahimong usa ka solusyon nga managsama ang lami sa matag tulo."}, "source": "NRC PS1.A; DepEd G5 Matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "candle-flame-combustion-g6", "domain": "MATTER", "topic": "candle flame burning wax and oxygen", "grades": [5, 6, 7], "terms": ["kandila", "candle", "ningas", "flame", "kalayo", "siga", "apoy", "fire", "kainit", "init", "heat", "ilaw", "light", "suga", "pabilo", "wick", "oksiheno", "oxygen", "pagkasunog", "combustion", "nasusunog na kandila", "nagliliyab", "natutunaw na kandila"], "fact": {"tl": "Ang ningas ng kandila ay nanggagaling sa pagkasunog ng natutunaw na kandila na umaakyat sa pabilo, at kailangan nito ng oksiheno sa hangin upang patuloy na magliyab.", "en": "A candle flame comes from burning melted wax that travels up the wick, and it needs oxygen from the air to keep burning.", "bis": "Ang siga sa kandila gikan sa pagkasunog sa natunaw nga kandila nga mosaka sa pabilo, ug nagkinahanglan kini og oksiheno gikan sa hangin aron magpadayon sa pagsiga."}, "source": "NRC PS3.D; PS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "candle-jar-oxygen-test-g6", "domain": "MATTER", "topic": "candle goes out without oxygen", "grades": [5, 6, 7], "terms": ["kandila", "candle", "garapon", "jar", "tinakpan", "covered", "gitabunan", "namatay ang apoy", "extinguish", "naubos na oksiheno", "oxygen", "oksiheno", "hangin", "air", "nawalan ng hangin", "pagkasunog", "combustion", "nakulong na hangin", "namatay ang ningas", "patay na kandila"], "fact": {"tl": "Kapag tinakpan ng garapon ang nagniningas na kandila, namamatay ang apoy pagkaubos ng oksiheno sa loob, na nagpapakitang kailangan ng oksiheno upang magpatuloy ang pagkasunog.", "en": "When a jar is placed over a lit candle, the flame goes out once the oxygen inside is used up, showing that burning needs oxygen.", "bis": "Kon tabunan og garapon ang nagsiga nga kandila, mapalong ang siga kon maubos na ang oksiheno sa sulod, nga nagpakita nga ang pagkasunog nagkinahanglan og oksiheno."}, "source": "NRC PS1.B; AAAS Benchmarks 4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "candle-relighting-resolidified-g5", "domain": "MATTER", "topic": "melted wax resolidifies physical change", "grades": [4, 5, 6], "terms": ["kandila", "candle", "natunaw", "melted", "natunaw na kandila", "tumigas", "resolidify", "nigahi", "muli", "lumamig", "cooled", "mibugnaw", "physical change", "pisikal na pagbabago", "wax", "muling tumigas", "nagbalik", "solido", "tunaw na kandila", "nagpalit ng anyo", "naparelit", "relighting"], "fact": {"tl": "Kapag lumamig ang natunaw na kandila, tumitigas itong muli at maaari pa ring sindihan—isang pisikal na pagbabago lamang dahil kandila pa rin ang sangkap nito.", "en": "When melted candle wax cools, it hardens again and can still be lit—just a physical change, because it is still the same wax.", "bis": "Kon mobugnaw ang natunaw nga kandila, motig-a kini pag-usab ug mahimo pa gihapong dagkutan—usa lang ka pisikal nga kausaban kay kandila gihapon ang sangkap niini."}, "source": "NRC PS1.A; DepEd G5 Matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "candle-wax-melting-pooling-g4", "domain": "MATTER", "topic": "candle wax melting from solid to liquid", "grades": [3, 4, 5], "terms": ["kandila", "candle", "natutunaw", "melting", "natunaw", "natunaw na kandila", "init", "heat", "kainit", "solido", "solid", "likido", "liquid", "tunaw", "namuo", "pooling", "wax", "anyo", "state of matter", "pagbabagong-anyo", "matunaw sa init"], "fact": {"tl": "Ang init ng ningas ay tumutunaw sa solidong kandila sa paligid ng pabilo, kaya nagiging likido ito at namumuo sa ibabaw bago muling tumigas kapag lumamig.", "en": "The flame's heat melts the solid wax around the wick, turning it into a liquid that pools on top before hardening again as it cools.", "bis": "Ang kainit sa siga magtunaw sa solido nga kandila palibot sa pabilo, mao nga mahimo kining likido nga magpundok sa ibabaw una motig-a pag-usab kon mobugnaw."}, "source": "NRC PS1.A; DepEd G4 Matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "capiz-shell-window-g5", "domain": "MATTER", "topic": "capiz shell translucent windows", "grades": [4, 5, 6], "terms": ["capiz", "kapis", "kabibe", "shell", "kabibi", "bintana", "window", "bintana sa balay", "translucent", "naaaninag", "nakakapasok ng liwanag", "liwanag", "light", "kahayag", "windowpane oyster", "tahanan", "Pilipinas", "manipis", "makinis", "naninipis na kabibi"], "fact": {"tl": "Ang capiz ay manipis at naaaninag na kabibe na ginagamit sa mga lumang bahay-Pilipino bilang bintana, dahil pinapapasok nito ang maamong liwanag ngunit hindi ito lubos na malinaw.", "en": "Capiz is a thin, translucent shell used as windowpanes in old Filipino houses because it lets soft light pass through while not being fully clear.", "bis": "Ang capiz usa ka nipis ug naaninag nga kabibi nga gigamit sa karaang mga balay-Pilipino isip bintana, kay ginapasudlan niini ang humok nga kahayag apan dili kini hingpit nga tin-aw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "carbon-bonding-g9", "domain": "MATTER", "topic": "carbon forms four bonds many molecules", "grades": [8, 9, 10], "terms": ["carbon", "karbon", "carbon nga atomo", "bond", "bigkis", "kabit", "apat na bond", "four bonds", "kovalent", "covalent", "molekula", "molecule", "kadena", "chain", "buhay", "life", "organic", "organiko", "diamante", "diamond", "uling", "graphite", "elemento ng buhay", "karbon nga elemento"], "fact": {"tl": "Ang carbon ay nakakabuo ng apat na bond sa ibang atom, kaya kayang-kaya nitong gumawa ng napakaraming iba't ibang molekula—kabilang ang mga molekulang bumubuo sa lahat ng nabubuhay na bagay.", "en": "A carbon atom can form four bonds with other atoms, which lets it build a huge variety of molecules—including the molecules that make up all living things.", "bis": "Ang carbon makahimo og upat ka bond sa ubang mga atomo, mao nga kaya niini maghimo og daghan kaayong nagkalain-laing molekula—lakip na ang mga molekula nga naglangkob sa tanang buhing butang."}, "source": "NRC PS1.A; LS1.C; DepEd G9 Chemistry", "generator": "claude-workflow", "reviewed": false},
  {"id": "centrifuge-separation-g8", "domain": "MATTER", "topic": "centrifuge separates mixtures by density", "grades": [7, 8, 9], "terms": ["centrifuge", "sentripugo", "umiikot", "spinning", "naglibot", "pag-ikot", "paghihiwalay", "separation", "pagbulag", "halo", "mixture", "sagol", "bigat", "density", "mabigat", "lumulubog", "settle", "dugo", "blood", "puwersang sentripugal", "makina"], "fact": {"tl": "Ang centrifuge ay isang makinang umiikot nang napakabilis upang ihiwalay ang mga bahagi ng halo, kung saan ang mas mabibigat na bahagi ay napupunta sa ilalim—gaya ng paghihiwalay sa mga bahagi ng dugo.", "en": "A centrifuge is a machine that spins very fast to separate the parts of a mixture, sending the heavier parts to the bottom—such as separating the parts of blood.", "bis": "Ang centrifuge usa ka makina nga molibot og paspas kaayo aron ibulag ang mga bahin sa usa ka sagol, diin ang mas bug-at nga mga bahin moadto sa ilawom—sama sa pagbulag sa mga bahin sa dugo."}, "source": "NRC PS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "champorado-stirring-mix-g4", "domain": "MATTER", "topic": "stirring mixes champorado evenly", "grades": [3, 4, 5], "terms": ["champorado", "tsamporado", "tsokolate", "chocolate", "haluin", "stir", "kutawin", "kutaw", "ihalo", "lutuin", "kanin", "rice", "malagkit", "halo", "mixture", "sagol", "pantay", "even", "magkahalo", "kumakapal", "thickens", "almusal"], "fact": {"tl": "Kapag kinutaw ang champorado habang niluluto, pantay na nagkakahalo ang tsokolate at malagkit na kanin upang maging makinis at parehong-pareho ang lasa sa buong palayok.", "en": "Stirring champorado while it cooks blends the chocolate and sticky rice evenly, making it smooth and the same flavor throughout the pot.", "bis": "Kon kutawon ang champorado samtang ginaluto, patas nga masagol ang tsokolate ug pilit nga kan-on aron mahimong hapsay ug managsama ang lami sa tibuok kolon."}, "source": "NRC PS1.A; DepEd G4 Matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "champorado-tuyo-heterogeneous-g6", "domain": "MATTER", "topic": "champorado and tuyo heterogeneous mixture", "grades": [5, 6, 7], "terms": ["champorado", "tsamporado", "tuyo", "dried fish", "bulad", "daing", "heterogeneous", "heterohenyo", "halo", "mixture", "sagol", "magkaibang bahagi", "nakikita ang piraso", "visible parts", "hindi pantay", "magkahiwalay", "tsokolate", "kanin", "magkaibang sangkap", "almusal"], "fact": {"tl": "Ang champorado na may tuyo ay isang heterogeneous na halo dahil makikita mo pa rin nang hiwalay ang malagkit na champorado at ang mga piraso ng tuyo sa plato.", "en": "Champorado served with tuyo is a heterogeneous mixture because you can still clearly see the sticky champorado and the pieces of dried fish as separate parts on the plate.", "bis": "Ang champorado nga may tuyo usa ka heterogeneous nga sagol kay makita pa nimo nga bulag ang pilit nga champorado ug ang mga tipik sa bulad sa plato."}, "source": "NRC PS1.A; DepEd G6 Matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "change-burning-paper-g6", "domain": "MATTER", "topic": "burning paper is a chemical change", "grades": [5, 6, 7], "terms": ["papel", "paper", "nasusunog", "burning", "nasunog", "sunog", "fire", "kalayo", "apoy", "abo", "ash", "abu", "usok", "smoke", "aso", "chemical change", "pagbabagong-kemikal", "kemikal nga kausaban", "hindi na maibabalik", "irreversible", "bagong sangkap", "gas", "init", "permanenteng pagbabago"], "fact": {"tl": "Ang pagsunog ng papel ay isang pagbabagong-kemikal dahil ang papel ay nagiging abo, usok, at gas na hindi na maibabalik sa dating anyong papel.", "en": "Burning paper is a chemical change because the paper turns into ash, smoke, and gases that can never be turned back into paper.", "bis": "Ang pagsunog sa papel usa ka kemikal nga kausaban kay ang papel mahimong abo, aso, ug gas nga dili na mabalik sa dating porma nga papel."}, "source": "NRC PS1.B; DepEd G6 Matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "charcoal-making-earth-mound-g7", "domain": "MATTER", "topic": "charcoal making by limited-air burning", "grades": [6, 7, 8], "terms": ["uling", "charcoal", "kahoy", "wood", "tinabunan", "covered mound", "kulang sa hangin", "limited air", "konting oksiheno", "mabagal na pagkasunog", "carbon", "karbon", "panggatong", "fuel", "pagluluto", "gawang uling", "natutuyong kahoy", "gumagawa ng uling", "init", "earth mound"], "fact": {"tl": "Ang uling ay ginagawa sa pamamagitan ng pagsunog ng kahoy sa loob ng tinabunang lupa na kakaunti ang hangin, kaya hindi ito tuluyang nasusunog kundi nagiging halos purong carbon na panggatong.", "en": "Charcoal is made by burning wood inside a covered earth mound with very little air, so it does not burn away completely but turns into nearly pure carbon fuel.", "bis": "Ang uling ginahimo pinaagi sa pagsunog sa kahoy sulod sa tinabonan nga yuta nga gamay ra og hangin, mao nga dili kini masunog sa hingpit kondili mahimong halos lunsay nga carbon nga panggatong."}, "source": "NRC PS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "chemical-equation-balanced-g8", "domain": "MATTER", "topic": "balanced chemical equation", "grades": [8, 9, 10], "terms": ["balanseng chemical equation", "balanseng ekwasyong kemikal", "balanced equation", "conservation of mass", "konserbasyon ng masa", "panimbang na reaksyon", "balanse nga chemical equation", "managsama ang atomo", "same number of atoms", "reaktant", "produkto"], "fact": {"tl": "Balanse ang isang chemical equation kapag pareho ang bilang ng bawat uri ng atom sa magkabilang panig, dahil hindi nawawala o nadadagdag ang atom sa isang reaksiyon.", "en": "A chemical equation is balanced when each type of atom has the same number on both sides, because atoms are neither created nor destroyed in a reaction.", "bis": "Balanse ang chemical equation kon parehas ang gidaghanon sa matag klase sa atomo sa duha ka kilid, kay walay atomo nga mawala o madugang sa usa ka reaksiyon."}, "source": "NRC PS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cooking-oil-bottle-pour-g4", "domain": "MATTER", "topic": "liquid viscosity and flow", "grades": [4, 5, 6], "terms": ["mantika", "langis", "cooking oil", "viscosity", "kapal ng likido", "dahan-dahang dumadaloy", "flows slowly", "lana", "kalapot", "hinay nga modagayday", "likido", "pagbuhos"], "fact": {"tl": "Mas malapot ang mantika kaysa tubig, kaya mas mabagal itong dumadaloy kapag ibinubuhos mula sa bote.", "en": "Cooking oil is thicker, or more viscous, than water, so it flows more slowly when poured from a bottle.", "bis": "Mas labot ang mantika kay sa tubig, busa mas hinay kini modagayday kon ibubo gikan sa botelya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "copper-patina-green-g6", "domain": "MATTER", "topic": "copper corrosion patina", "grades": [6, 7, 8], "terms": ["tanso", "copper", "berdeng patina", "green patina", "kalawang ng tanso", "oxidation", "kemikal na pagbabago", "tumbaga", "berde nga tabon", "kalawang sa tumbaga", "hangin ug tubig", "chemical change"], "fact": {"tl": "Ang berdeng patina sa tanso ay bunga ng dahan-dahang reaksiyon nito sa hangin at halumigmig, isang kemikal na pagbabago na bumubuo ng bagong sangkap sa ibabaw.", "en": "The green patina on copper forms from its slow reaction with air and moisture, a chemical change that creates a new compound on the surface.", "bis": "Ang berdeng patina sa tumbaga magikan sa hinay nga reaksiyon niini sa hangin ug kaumog, usa ka kemikal nga kabag-ohan nga maghimo ug bag-ong sangkap sa ibabaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "crystal-growing-string-jar-g5", "domain": "MATTER", "topic": "crystallization from solution", "grades": [5, 6, 7], "terms": ["kristal", "crystal", "asukal o asin", "supersaturated solution", "pagtubo ng kristal", "lubid sa garapon", "ebaporasyon", "crystallization", "kristal nga motubo", "tunaw nga asin", "string jar"], "fact": {"tl": "Kapag unti-unting sumisingaw ang tubig sa isang puno-punong solusyon ng asukal o asin, naiiwan ang sangkap at bumubuo ito ng mga kristal sa lubid.", "en": "As water slowly evaporates from a saturated sugar or salt solution, the dissolved substance is left behind and builds into crystals on a string.", "bis": "Samtang hinay nga moalisngaw ang tubig gikan sa puno nga solusyon sa asukar o asin, mahibilin ang sangkap ug maghimo kini ug mga kristal sa pisi."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "decanting-patis-g5", "domain": "MATTER", "topic": "decanting to separate mixtures", "grades": [5, 6, 7], "terms": ["patis", "decanting", "pagsala sa pagbuhos", "paghihiwalay ng halo", "latak", "sediment", "malinaw na likido", "fish sauce", "pagbubo", "pag-ibo", "lapok", "separation of mixtures"], "fact": {"tl": "Sa decanting, dahan-dahang ibinubuhos ang malinaw na likido tulad ng patis upang maiwan ang lumusong na latak sa ilalim ng lalagyan.", "en": "In decanting, the clear liquid such as fish sauce is poured off slowly so the settled sediment is left behind at the bottom of the container.", "bis": "Sa decanting, hinay nga ibubo ang tin-aw nga likido sama sa patis aron mabilin ang nilugdang nga lapok sa ilawom sa sudlanan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "density-liquid-layers-column-g6", "domain": "MATTER", "topic": "density of liquids and layering", "grades": [6, 7, 8], "terms": ["densidad", "density", "patong-patong na likido", "liquid layers", "kapal ng masa", "lumulutang", "lumulubog", "pulot at langis", "density column", "magkapatong nga likido", "bug-at nga likido", "naglutaw"], "fact": {"tl": "Nagpapatong-patong ang iba't ibang likido sa isang kolumna dahil ang mas mataas ang densidad ay lumulubog sa ilalim at ang mas mababa ay lumulutang sa itaas.", "en": "Different liquids stack in layers in a column because the denser ones sink to the bottom and the less dense ones float on top.", "bis": "Magpatong-patong ang lain-laing likido sa usa ka kolumna kay ang mas dasok molugdang sa ilawom ug ang mas magaan molutaw sa ibabaw."}, "source": "NRC PS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "chromatography-tissue-g6", "domain": "MATTER", "topic": "paper chromatography separates colors", "grades": [6, 7, 8], "terms": ["chromatography", "kromatograpiya", "paghihiwalay ng kulay", "tisyu o papel", "pigment", "mga kulay sa tinta", "marker", "umaakyat na tubig", "magkalainlaing kulay", "pagbahin sa kolor", "tissue paper"], "fact": {"tl": "Sa chromatography, umaakyat ang tubig sa papel at dinadala ang tinta, kaya naghihiwalay ang magkakaibang kulay na bumubuo ng isang pigment.", "en": "In chromatography, water climbs up the paper and carries the ink, so the different colors that make up one pigment separate from each other.", "bis": "Sa chromatography, mosaka ang tubig sa papel ug magdala sa tinta, busa magbulagbulag ang lain-laing kolor nga naglangkob sa usa ka pigment."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dissolving-particles-diagram-g5", "domain": "MATTER", "topic": "dissolving at the particle level", "grades": [5, 6, 7], "terms": ["natutunaw", "dissolving", "maliliit na particle", "asin sa tubig", "solute", "solvent", "nagkakalat na particle", "solution", "natunaw nga asin", "mga partikulo", "nagkatag", "particle model"], "fact": {"tl": "Kapag natutunaw ang asin sa tubig, naghihiwalay ito sa napakaliliit na particle na pantay na kumakalat sa pagitan ng mga particle ng tubig.", "en": "When salt dissolves in water, it breaks into tiny particles that spread out evenly among the water particles.", "bis": "Kon matunaw ang asin sa tubig, mabahinbahin kini ngadto sa gagmayng mga partikulo nga magkatag nga patas taliwala sa mga partikulo sa tubig."}, "source": "NRC PS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "distillation-tuba-still-g7", "domain": "MATTER", "topic": "distillation separates by boiling point", "grades": [7, 8, 9], "terms": ["distillation", "distilasyon", "pagpapasingaw at paglamig", "tuba", "lambanog", "boiling point", "singaw at kondensasyon", "paghihiwalay ng likido", "pag-init ug pagpabugnaw", "alkohol", "kondensar", "still"], "fact": {"tl": "Sa distilasyon, pinainit ang isang halo hanggang sumingaw ang sangkap na may mas mababang punto ng pagkulo, at pinalalamig muli ang singaw upang makuhang malinis na likido.", "en": "In distillation, a mixture is heated until the substance with the lower boiling point evaporates, then the vapor is cooled back into a purer liquid.", "bis": "Sa distillation, init-an ang sagol hangtod moalisngaw ang sangkap nga ubos ang boiling point, dayon pabugnawon ang alisngaw aron mahimong mas limpyo nga likido."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "filtration-setup-diagram-g4", "domain": "MATTER", "topic": "filtration separates solids from liquids", "grades": [4, 5, 6], "terms": ["pagsasala", "filtration", "salaan", "filter paper", "naghihiwalay ng solid sa likido", "residue", "filtrate", "naipon na buhangin", "pagsala", "pag-igo", "limpyo nga tubig", "funnel"], "fact": {"tl": "Sa pagsasala, dumadaan ang likido sa salaan ngunit naiiwan ang mas malalaking solidong piraso tulad ng buhangin sa ibabaw nito.", "en": "In filtration, the liquid passes through a filter while larger solid pieces such as sand are trapped and left on top of it.", "bis": "Sa pagsala, moagi ang likido sa salaan apan mabilin ang mas dagkong solidong tipik sama sa balas sa ibabaw niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ph-scale-strip-g7", "domain": "MATTER", "topic": "pH scale of acids and bases", "grades": [7, 8, 9], "terms": ["pH scale", "iskala ng pH", "asido", "base", "neutral", "litmus o indicator", "suka at sabon", "asidiko", "alkaline", "acid", "indicator strip", "sukaranan sa pH"], "fact": {"tl": "Sinusukat ng pH scale mula 0 hanggang 14 kung gaano kaasido o kabase ang isang solusyon, kung saan ang 7 ay neutral, mas mababa ay asido, at mas mataas ay base.", "en": "The pH scale runs from 0 to 14 and measures how acidic or basic a solution is, where 7 is neutral, lower is acidic, and higher is basic.", "bis": "Ang pH scale gikan 0 hangtod 14 magsukod kon unsa ka asido o ka base ang usa ka solusyon, diin ang 7 neutral, ang mas ubos asido, ug ang mas taas base."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "diffusion-dye-water-spread-g5", "domain": "MATTER", "topic": "diffusion of dye in water", "grades": [5, 6, 7], "terms": ["diffusion", "pagkalat", "kulay sa tubig", "dye", "kumakalat na sarili", "particle motion", "pantay na pagkalat", "tina sa tubig", "pagkaylap", "nagkatag", "galaw ng particle"], "fact": {"tl": "Sa diffusion, kusang kumakalat ang mga particle ng kulay mula sa siksik na bahagi patungo sa mas kaunti hanggang pantay na itong umabot sa buong tubig.", "en": "In diffusion, dye particles spread on their own from where they are crowded to where there are fewer, until they are evenly mixed through the water.", "bis": "Sa diffusion, kusog nga magkatag ang mga partikulo sa tina gikan sa dasok nga bahin paingon sa mas gamay hangtod managsama na kini sa tibuok tubig."}, "source": "NRC PS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "diffusion-ink-in-water-g5", "domain": "MATTER", "topic": "diffusion of ink in water", "grades": [5, 6, 7], "terms": ["tinta sa tubig", "ink in water", "diffusion", "pagkalat ng tinta", "patak ng tinta", "kusang paghahalo", "particle", "tinta", "nagkatag nga tinta", "tulo sa tinta", "spontaneous mixing"], "fact": {"tl": "Kapag naghulog ng patak ng tinta sa tubig, kusa itong kumakalat kahit hindi hinahalo dahil patuloy na gumagalaw ang mga particle ng likido.", "en": "When a drop of ink is added to water, it spreads on its own even without stirring because the liquid particles are always moving.", "bis": "Kon ihulog ang usa ka tulo sa tinta sa tubig, kusog kini nga mokatag bisan dili kutawon kay kanunay nga naglihok ang mga partikulo sa likido."}, "source": "NRC PS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dissolving-rate-temperature-g5", "domain": "MATTER", "topic": "temperature affects dissolving rate", "grades": [5, 6, 7], "terms": ["bilis ng pagkatunaw", "dissolving rate", "mainit na tubig", "temperatura", "mas mabilis matunaw", "asukal", "init ng tubig", "kaspas sa pagkatunaw", "init nga tubig", "temperature", "solute"], "fact": {"tl": "Mas mabilis natutunaw ang asukal sa mainit na tubig kaysa sa malamig, dahil mas mabilis gumagalaw ang mga particle ng mainit na tubig.", "en": "Sugar dissolves faster in hot water than in cold water because the particles in hot water move more quickly.", "bis": "Mas paspas matunaw ang asukar sa init nga tubig kay sa bugnaw, kay mas paspas molihok ang mga partikulo sa init nga tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dissolving-vs-melting-g5", "domain": "MATTER", "topic": "dissolving versus melting", "grades": [5, 6, 7], "terms": ["pagkatunaw sa likido", "dissolving", "pagkalusaw", "melting", "init kontra solvent", "pagkakaiba", "asin sa tubig", "yelo na natutunaw", "solute", "natunaw", "natunaw sa kainit", "physical change"], "fact": {"tl": "Ang pagkatunaw ay nangyayari kapag naghahalo ang isang sangkap sa likido tulad ng asin sa tubig, habang ang pagkalusaw ay pagbabago ng solido tungong likido dahil sa init tulad ng yelo.", "en": "Dissolving happens when a substance mixes into a liquid, like salt in water, while melting is a solid turning into a liquid because of heat, like ice.", "bis": "Ang pagkatunaw mahitabo kon ang usa ka sangkap mosagol sa likido sama sa asin sa tubig, samtang ang pagkalanay mao ang pagbalhin sa solido ngadto sa likido tungod sa kainit sama sa yelo."}, "source": "NRC PS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dry-ice-fog-g6", "domain": "MATTER", "topic": "dry ice sublimation and fog", "grades": [6, 7, 8], "terms": ["dry ice", "tuyong yelo", "sublimation", "sublimasyon", "usok na fog", "carbon dioxide", "solido tungong gas", "ulap na puti", "uga nga yelo", "aso", "carbon dioxide gas", "fog"], "fact": {"tl": "Ang dry ice ay solidong carbon dioxide na dumiretsong nagiging gas nang hindi nagiging likido, at ang fog na nakikita ay tubig sa hangin na pinalamig nito.", "en": "Dry ice is solid carbon dioxide that turns straight into a gas without becoming a liquid, and the fog you see is water in the air that it has chilled.", "bis": "Ang dry ice mao ang solido nga carbon dioxide nga diretso nga mahimong gas nga dili una mahimong likido, ug ang fog nga makita mao ang tubig sa hangin nga gipabugnaw niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "electrolysis-of-water-g8", "domain": "MATTER", "topic": "electrolysis splits water", "grades": [8, 9, 10], "terms": ["electrolysis", "elektrolisis", "paghahati ng tubig", "hydrogen at oxygen", "kuryente sa tubig", "electric current", "bula ng gas", "tubig na nahahati", "pagbahin sa tubig", "hydrogen", "oxygen", "elektrisidad"], "fact": {"tl": "Sa electrolysis, dinadaanan ng kuryente ang tubig upang ito ay mahati sa dalawang gas: hydrogen sa isang elektrodo at oxygen sa kabila.", "en": "In electrolysis, an electric current is passed through water to split it into two gases: hydrogen at one electrode and oxygen at the other.", "bis": "Sa electrolysis, paaginon ang elektrisidad sa tubig aron kini mabahin sa duha ka gas: hydrogen sa usa ka elektrodo ug oxygen sa pikas."}, "source": "NRC PS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "electron-configuration-g9", "domain": "MATTER", "topic": "electron arrangement in shells", "grades": [9, 10], "terms": ["electron configuration", "pagkakaayos ng electron", "mga shell o energy level", "electron sa atomo", "valence electron", "lupon ng electron", "pang-ayos sa electron", "energy level", "atom", "shells"], "fact": {"tl": "Ang electron configuration ay naglalarawan kung paano nakaayos ang mga electron ng isang atom sa magkakaibang energy level o shell sa paligid ng nucleus.", "en": "Electron configuration describes how an atom's electrons are arranged in different energy levels, or shells, around the nucleus.", "bis": "Ang electron configuration maghulagway kon giunsa pagkahan-ay ang mga electron sa usa ka atomo sa lain-laing energy level o shell palibot sa nucleus."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "emulsion-mayonnaise-g6", "domain": "MATTER", "topic": "emulsion in mayonnaise", "grades": [6, 7, 8], "terms": ["emulsion", "emulsyon", "mayonesa", "langis at tubig", "hindi naghihiwalay", "emulsifier", "itlog", "lecithin", "halong langis ug tubig", "mayonnaise", "mantika ug tubig", "stable mixture"], "fact": {"tl": "Ang mayonesa ay isang emulsyon kung saan ang maliliit na patak ng langis ay nakakalat sa tubig, at pinananatiling magkahalo ito ng itlog na nagsisilbing emulsifier.", "en": "Mayonnaise is an emulsion in which tiny droplets of oil are spread through water, kept mixed by egg that acts as an emulsifier.", "bis": "Ang mayonesa usa ka emulsion diin ang gagmayng tinulo sa lana magkatag sa tubig, ug gihuptan kini nga sagol sa itlog nga nagsilbing emulsifier."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "evaporating-saltwater-dish-g4", "domain": "MATTER", "topic": "evaporating saltwater leaves salt", "grades": [4, 5, 6], "terms": ["pagsingaw ng tubig", "evaporation", "tubig-alat", "saltwater", "naiwang asin", "salt left behind", "araw na nagpapainit", "asin", "pag-alisngaw", "naghimo ug asin", "salt pan", "evaporating dish"], "fact": {"tl": "Kapag sumisingaw ang tubig-alat, naglalaho lamang ang tubig at naiiwan ang asin, na siyang paraan ng paggawa ng asin sa mga aluwagan.", "en": "When saltwater evaporates, only the water leaves as vapor and the salt is left behind, which is how salt is made in salt beds.", "bis": "Kon moalisngaw ang tubig-asin, ang tubig lang ang mawala isip alisngaw ug ang asin mabilin, nga mao ang pamaagi sa paghimo ug asin sa mga asinan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "exothermic-vs-endothermic-g8", "domain": "MATTER", "topic": "exothermic and endothermic reactions", "grades": [8, 9, 10], "terms": ["exothermic", "endothermic", "naglalabas ng init", "sumisipsip ng init", "reaksyong kemikal", "init na enerhiya", "lumalamig o umiinit", "nagbuga ug init", "nagsuyop ug init", "heat energy", "chemical reaction"], "fact": {"tl": "Ang exothermic na reaksiyon ay naglalabas ng init kaya umiinit ang paligid, habang ang endothermic na reaksiyon ay sumisipsip ng init kaya lumalamig ito.", "en": "An exothermic reaction releases heat so its surroundings get warmer, while an endothermic reaction absorbs heat so its surroundings get cooler.", "bis": "Ang exothermic nga reaksiyon mobuga ug init busa moinit ang palibot, samtang ang endothermic nga reaksiyon mosuyop ug init busa mobugnaw kini."}, "source": "NRC PS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "expansion-balloon-bottle-heat-g6", "domain": "MATTER", "topic": "gases expand when heated", "grades": [6, 7, 8], "terms": ["pagpapalawak ng gas", "thermal expansion", "lobo sa bote", "balloon on bottle", "init na nagpapalaki", "gas na lumalawak", "lobo na lumalaki", "pag-init sa gas", "pagdako sa hangin", "expansion", "heated air"], "fact": {"tl": "Kapag pinainit ang hangin sa loob ng bote, lumalawak ito at maaaring magpalaki sa lobong nakatakip sa bunganga nito.", "en": "When the air inside a bottle is heated, it expands and can blow up a balloon stretched over the bottle's mouth.", "bis": "Kon init-an ang hangin sa sulod sa botelya, mosangkad kini ug mahimong mopadako sa lobo nga nakatabon sa baba sa botelya."}, "source": "NRC PS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fiesta-lechon-roasting-g5", "domain": "MATTER", "topic": "roasting as a chemical change", "grades": [5, 6, 7], "terms": ["lechon", "litson", "pag-iihaw", "roasting", "kemikal na pagbabago", "browning", "init ng apoy", "balat na gumagansal", "pagsugba", "kabag-ohan sa kemikal", "Maillard browning", "fiesta"], "fact": {"tl": "Kapag iniihaw ang lechon, hindi na maibabalik sa hilaw nitong anyo ang karne dahil ang init ay nagdudulot ng kemikal na pagbabago na nagpapakayumanggi at nagpapalasa nito.", "en": "When a lechon is roasted, the meat cannot return to its raw form because the heat causes a chemical change that browns it and develops its flavor.", "bis": "Kon sugbaon ang lechon, dili na mabalik sa hilaw niini ang karne kay ang kainit maghimo ug kemikal nga kabag-ohan nga magpakape niini ug magpalami."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "filtering-kapeng-barako-g4", "domain": "MATTER", "topic": "filtering coffee separates grounds", "grades": [4, 5, 6], "terms": ["kapeng barako", "kape", "filtering coffee", "salaan ng kape", "coffee grounds", "naghihiwalay ng durog", "filtrate na inumin", "pagsala sa kape", "giok sa kape", "filter", "kapeng durog"], "fact": {"tl": "Kapag sinasala ang kapeng barako, dumadaan ang malinaw na inumin sa salaan habang naiiwan ang durog na butil ng kape sa ibabaw.", "en": "When kapeng barako is filtered, the clear drink passes through the filter while the coffee grounds are trapped and left on top.", "bis": "Kon salaan ang kapeng barako, moagi ang tin-aw nga ilimnon sa salaan samtang mabilin ang giok nga lugas sa kape sa ibabaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fire-triangle-g5", "domain": "MATTER", "topic": "fire triangle of combustion", "grades": [5, 6, 7], "terms": ["fire triangle", "tatsulok ng apoy", "panggatong", "fuel", "oxygen", "init na pampaalab", "combustion", "tatlong sangkap ng apoy", "sugnod", "kainit", "oksiheno", "pagdilaab"], "fact": {"tl": "Kailangan ng apoy ang tatlong bagay nang sabay-sabay: panggatong, oxygen, at sapat na init, at mamamatay ito kapag naalis ang kahit alin sa tatlo.", "en": "Fire needs three things at once: fuel, oxygen, and enough heat, and it goes out when any one of the three is removed.", "bis": "Ang kalayo nagkinahanglan ug tulo ka butang dungan: sugnod, oxygen, ug igong kainit, ug mapalong kini kon kuhaon bisan asa sa tulo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fog-over-rice-field-g5", "domain": "EARTH_SPACE", "topic": "fog formation by condensation", "grades": [5, 6, 7], "terms": ["hamog", "fog", "ulap sa palayan", "condensation", "kondensasyon", "malamig na umaga", "singaw na lumalamig", "tubig sa hangin", "gabon", "umog sa hangin", "rice field", "water vapor"], "fact": {"tl": "Bumubuo ang hamog sa palayan kapag lumalamig ang hangin sa umaga at nagiging maliliit na patak ng tubig ang singaw na nakalutang dito.", "en": "Fog forms over a rice field when the morning air cools and the water vapor in it condenses into tiny floating droplets of water.", "bis": "Maporma ang gabon sa palayan kon mobugnaw ang hangin sa buntag ug ang alisngaw nga anaa niini mahimong gagmayng naglutaw nga tulo sa tubig."}, "source": "AAAS Benchmarks; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "frost-on-freezer-wall-g5", "domain": "MATTER", "topic": "frost from deposition of water vapor", "grades": [5, 6, 7], "terms": ["frost", "namuong yelo", "pader ng freezer", "deposition", "singaw na nagiging yelo", "water vapor", "namuong hamog na yelo", "malamig na ibabaw", "yelo sa freezer", "tun-og nga yelo", "freezer wall"], "fact": {"tl": "Ang frost sa pader ng freezer ay bumubuo kapag ang singaw ng tubig sa hangin ay diretsong nagiging yelo sa napakalamig na ibabaw nang hindi nagiging likido.", "en": "Frost on a freezer wall forms when water vapor in the air turns straight into ice on the very cold surface without first becoming liquid.", "bis": "Ang frost sa bungbong sa freezer maporma kon ang alisngaw sa tubig sa hangin diretso nga mahimong yelo sa hilabihan kabugnaw nga ibabaw nga dili una mahimong likido."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gas-laws-boyle-g9", "domain": "MATTER", "topic": "Boyle's law pressure and volume", "grades": [9, 10], "terms": ["Boyle's law", "batas ni Boyle", "presyon at volume", "pressure", "volume", "kabaliktaran na ugnayan", "gas na ipit", "constant temperature", "balaod ni Boyle", "presyur", "kadako sa gas", "inverse"], "fact": {"tl": "Ayon sa batas ni Boyle, kapag pare-pareho ang temperatura, bumababa ang volume ng isang gas habang tumataas ang presyon dito, at gayundin sa kabaliktaran.", "en": "According to Boyle's law, at a constant temperature the volume of a gas decreases as the pressure on it increases, and the other way around.", "bis": "Sumala sa balaod ni Boyle, kon parehas ang temperatura, mokunhod ang volume sa usa ka gas samtang motaas ang presyur niini, ug maingon man sa balikbalik."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gas-laws-charles-g9", "domain": "MATTER", "topic": "Charles's law temperature and volume", "grades": [9, 10], "terms": ["Charles's law", "batas ni Charles", "temperatura at volume", "temperature", "volume", "lumalawak kapag mainit", "gas na lumalaki", "constant pressure", "balaod ni Charles", "kainit ug kadako", "expand", "init nga gas"], "fact": {"tl": "Ayon sa batas ni Charles, kapag pare-pareho ang presyon, lumalawak ang volume ng isang gas habang tumataas ang temperatura nito.", "en": "According to Charles's law, at a constant pressure the volume of a gas increases as its temperature rises.", "bis": "Sumala sa balaod ni Charles, kon parehas ang presyur, mosangkad ang volume sa usa ka gas samtang motaas ang temperatura niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "grilling-isaw-charring-g6", "domain": "MATTER", "topic": "grilling and charring food", "grades": [5, 6, 7], "terms": ["isaw", "inihaw", "pag-ihaw", "pagsunog", "uling", "naninilaw", "grilling", "grilled intestines", "charring", "char", "browning", "init", "init ng baga", "sinugba", "pagsugba", "sinunog", "naitom", "uling sa karne"], "fact": {"tl": "Kapag iniihaw ang isaw sa baga, ang init ay nagdudulot ng kemikal na pagbabago na nagpapaitim at nagbibigay ng espesyal na lasa at amoy sa karne.", "en": "When isaw (grilled intestines) is cooked over hot coals, the heat causes a chemical change that browns or chars the meat and gives it a special smoky flavor and smell.", "bis": "Kon sugbahon ang isaw sa baga, ang kainit maghatag ug kemikal nga kausaban nga maoy makaitom ug makahatag ug espesyal nga lami ug baho sa karne."}, "source": "encyclopedia-stable consensus; NRC PS1.B (chemical reactions)", "generator": "claude-workflow", "reviewed": false},
  {"id": "gulaman-setting-tray-g5", "domain": "MATTER", "topic": "gelatin setting from liquid to solid", "grades": [4, 5, 6], "terms": ["gulaman", "gelatin", "agar", "pagtigas", "tumitigas", "nagiging matigas", "lumalamig", "liquid to solid", "setting", "jelly", "mogahi", "naggahi", "pagbugnaw", "likido ngadto solido"], "fact": {"tl": "Ang mainit at malabnaw na gulaman ay tumitigas at nagiging makinis na solido habang ito ay lumalamig sa tray.", "en": "Hot, watery gulaman (gelatin) turns from a liquid into a firm, smooth solid as it cools down in the tray.", "bis": "Ang init ug labnaw nga gulaman magahi ug mahimong hamis nga solido samtang kini magbugnaw diha sa tray."}, "source": "NRC PS1.A (states of matter; reversible change)", "generator": "claude-workflow", "reviewed": false},
  {"id": "hydrocarbons-g9", "domain": "MATTER", "topic": "hydrocarbons as fuels", "grades": [8, 9, 10], "terms": ["hydrocarbons", "hydrocarbon", "haydrokarbon", "karbon", "hydrogen", "haydroheno", "langis", "petrolyo", "gaas", "gasolina", "metano", "methane", "natural gas", "panggatong", "fuel", "sunog", "carbon", "petroleum", "sugnod"], "fact": {"tl": "Ang mga hydrocarbon ay mga compound na gawa lamang sa carbon at hydrogen, at marami sa kanila tulad ng gasolina at natural gas ay ginagamit bilang panggatong.", "en": "Hydrocarbons are compounds made of only carbon and hydrogen atoms, and many of them such as gasoline and natural gas are used as fuels.", "bis": "Ang mga hydrocarbon mga compound nga hinimo lamang sa carbon ug hydrogen nga mga atomo, ug daghan kanila sama sa gasolina ug natural gas gigamit ingon nga sugnod."}, "source": "encyclopedia-stable consensus; NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "ice-candy-frozen-tube-g4", "domain": "MATTER", "topic": "freezing liquid into ice candy", "grades": [3, 4, 5], "terms": ["ice candy", "ais kandi", "nagyeyelo", "pagyeyelo", "yelo", "nagiging matigas", "lumamig", "freezer", "frozen", "freezing", "liquid to solid", "nagbugnaw", "naggyelo", "nagahi", "likido ngadto solido"], "fact": {"tl": "Ang matamis na likido sa loob ng plastik ay nagyeyelo at nagiging matigas na ice candy kapag inilagay sa freezer dahil nawawala ang init nito.", "en": "The sweet liquid inside the plastic tube freezes into solid ice candy in the freezer because it loses heat and gets very cold.", "bis": "Ang tam-is nga likido sa sulod sa plastik magyelo ug mahimong gahi nga ice candy diha sa freezer tungod kay mawad-an kini ug kainit ug mabugnaw."}, "source": "NRC PS1.A (states of matter; freezing)", "generator": "claude-workflow", "reviewed": false},
  {"id": "ice-cube-g3", "domain": "MATTER", "topic": "ice as frozen water", "grades": [3, 4, 5], "terms": ["ice cube", "yelo", "yelong tubig", "nagyelo", "nagiging tubig", "natutunaw", "frozen water", "solid water", "melting", "natunaw", "nagahi nga tubig", "matunaw", "nagtunaw", "solido nga tubig"], "fact": {"tl": "Ang yelo ay tubig na nagyelo at naging solido sa sobrang lamig, at ito ay natutunaw pabalik sa likido kapag uminit.", "en": "An ice cube is water that has frozen into a solid because it got very cold, and it melts back into liquid water when it warms up.", "bis": "Ang yelo kay tubig nga nagyelo ug nahimong solido tungod sa hilabihang katugnaw, ug kini matunaw balik ngadto sa likido kon mainit."}, "source": "NRC PS1.A (states of matter; melting and freezing)", "generator": "claude-workflow", "reviewed": false},
  {"id": "invisible-ink-calamansi-g6", "domain": "MATTER", "topic": "calamansi juice as invisible ink", "grades": [5, 6, 7], "terms": ["invisible ink", "kalamansi", "calamansi", "katas", "tinta", "lihim na sulat", "naninilaw", "init", "browning", "acid", "asido", "hidden writing", "duga", "duga sa kalamansi", "nagbrown", "tinago nga sulat"], "fact": {"tl": "Ang katas ng kalamansi ay maaaring gamiting lihim na tinta dahil hindi ito kita hanggang painitin, kung saan ito ay naninilaw o nag-iitim sa papel.", "en": "Calamansi juice can be used as invisible ink because the writing stays hidden until you heat the paper, which makes the juice turn brown and appear.", "bis": "Ang duga sa kalamansi mahimong gamiton nga tinago nga tinta tungod kay dili kini makita hangtod nga init-on ang papel, diin ang duga magbrown ug motungha."}, "source": "encyclopedia-stable consensus; NRC PS1.B (chemical change from heat)", "generator": "claude-workflow", "reviewed": false},
  {"id": "invisible-ink-lemon-heat-g6", "domain": "MATTER", "topic": "heat revealing lemon invisible ink", "grades": [5, 6, 7], "terms": ["invisible ink", "lemon", "limon", "katas ng limon", "init", "heat", "naninilaw", "lihim na sulat", "browning", "asido", "lemon juice", "duga sa limon", "kainit", "nagbrown", "tinago nga sulat"], "fact": {"tl": "Kapag pinainit ang papel na may sulat na katas ng limon, ang init ay sumusunog nang bahagya sa katas kaya lumilitaw ang dating hindi nakikitang sulat.", "en": "When you heat paper written on with lemon juice, the heat lightly browns the dried juice so the once-invisible writing appears.", "bis": "Kon init-on ang papel nga gisulatan ug duga sa limon, ang kainit hinay-hinay nga mosunog sa duga maong motungha ang kanhi dili makita nga sulat."}, "source": "encyclopedia-stable consensus; NRC PS1.B (chemical change from heat)", "generator": "claude-workflow", "reviewed": false},
  {"id": "iron-filings-in-cereal-magnet-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "magnet attracting iron in cereal", "grades": [5, 6, 7], "terms": ["iron filings", "bakal", "iron", "magnet", "magneto", "cereal", "nutrient", "fortified", "humihila", "nakukuha", "magnetic", "magnetiko", "puthaw", "magdani", "nakuha sa magnet", "bakal sa pagkaon"], "fact": {"tl": "May maliliit na piraso ng bakal sa ilang fortified na cereal bilang nutrient, at ang mga ito ay maaaring mahila ng magnet dahil ang bakal ay magnetiko.", "en": "Some fortified cereals contain tiny bits of iron as a nutrient, and a magnet can pull these bits out because iron is attracted to magnets.", "bis": "Ang ubang fortified nga cereal adunay gagmay nga tipik sa puthaw isip nutrient, ug ang magnet makabira niini tungod kay ang puthaw madani sa magnet."}, "source": "encyclopedia-stable consensus; NRC PS2.B (magnetic forces)", "generator": "claude-workflow", "reviewed": false},
  {"id": "kapeng-grounds-vs-filtered-g5", "domain": "MATTER", "topic": "filtering separates coffee grounds", "grades": [4, 5, 6], "terms": ["kape", "coffee", "kapeng barako", "grounds", "salaan", "pagsala", "filter", "filtering", "naghihiwalay", "separation", "mixture", "halo", "salaan", "pagsala", "magbulag", "sagol", "gisala", "kape nga giling"], "fact": {"tl": "Ang pagsala ng kape ay naghihiwalay ng malinaw na likido mula sa mga durog na butil na hindi natutunaw, kaya nananatili ang mga ito sa salaan.", "en": "Filtering coffee separates the clear liquid from the gritty grounds that do not dissolve, so the solid grounds stay behind in the filter.", "bis": "Ang pagsala sa kape magbulag sa tin-aw nga likido gikan sa giling nga mga tipik nga dili matunaw, busa ang solido nga giling magpabilin sa salaan."}, "source": "NRC PS1.A (mixtures and separation; solubility)", "generator": "claude-workflow", "reviewed": false},
  {"id": "kesong-puti-curdling-g6", "domain": "MATTER", "topic": "milk curdling into white cheese", "grades": [5, 6, 7], "terms": ["kesong puti", "keso", "gatas", "milk", "curdling", "namumuo", "namuo", "nagbubuo", "asido", "acid", "cheese", "carabao milk", "namumuong gatas", "namuong gatas", "asido sa keso", "puti nga keso"], "fact": {"tl": "Ang kesong puti ay gawa sa gatas ng kalabaw na pinamuo gamit ang asido o espesyal na enzyme, kaya naghihiwalay ang matigas na bahagi mula sa likido.", "en": "Kesong puti is made by curdling carabao's milk with acid or a special enzyme, which makes the solid white curds separate from the watery liquid.", "bis": "Ang kesong puti hinimo gikan sa gatas sa kalabaw nga gipamuo pinaagi sa asido o espesyal nga enzyme, mao nga magbulag ang gahi nga puti gikan sa likido."}, "source": "encyclopedia-stable consensus; NRC PS1.B (chemical change)", "generator": "claude-workflow", "reviewed": false},
  {"id": "leche-flan-caramel-hardening-g6", "domain": "MATTER", "topic": "caramelizing and hardening sugar", "grades": [5, 6, 7], "terms": ["leche flan", "caramel", "karamelo", "asukal", "sugar", "tumitigas", "nagiging matigas", "natutunaw", "init", "browning", "naninilaw", "syrup", "nagahi", "mogahi", "karamelo", "asukal nga natunaw"], "fact": {"tl": "Kapag pinainit ang asukal para sa leche flan, ito ay natutunaw, naninilaw, at nagiging karamelo na tumitigas kapag lumamig.", "en": "When sugar is heated to make leche flan caramel, it melts, turns golden brown, and then hardens into solid caramel as it cools.", "bis": "Kon init-on ang asukal alang sa leche flan, kini matunaw, magbrown, ug mahimong karamelo nga magahi kon mabugnaw."}, "source": "encyclopedia-stable consensus; NRC PS1.B (chemical change; reversible vs irreversible)", "generator": "claude-workflow", "reviewed": false},
  {"id": "lemon-on-marble-acid-reaction-g7", "domain": "MATTER", "topic": "acid reacting with marble", "grades": [6, 7, 8], "terms": ["lemon", "limon", "marble", "marmol", "asido", "acid", "calcium carbonate", "bula", "fizzing", "reaction", "natutunaw", "carbon dioxide", "tumutunaw", "duga sa limon", "bula", "magbukal", "asido sa marmol", "natunaw nga bato"], "fact": {"tl": "Ang asido sa katas ng limon ay tumutugon sa marmol at lumilikha ng maliliit na bula ng gas dahil unti-unting natutunaw ng asido ang bato.", "en": "The acid in lemon juice reacts with marble and makes tiny gas bubbles because the acid slowly dissolves the stone.", "bis": "Ang asido sa duga sa limon mag-reaksyon sa marmol ug maghimo ug gagmay nga bula sa gas tungod kay hinay-hinay nga tunawon sa asido ang bato."}, "source": "encyclopedia-stable consensus; NRC PS1.B (acid-carbonate reaction)", "generator": "claude-workflow", "reviewed": false},
  {"id": "lewis-dot-structures-g9", "domain": "MATTER", "topic": "Lewis dot structures showing valence electrons", "grades": [8, 9, 10], "terms": ["Lewis dot structure", "Lewis structure", "tuldok", "dots", "valence electrons", "bonding", "bono", "shared electrons", "diagram", "atom", "molecule", "tuldok-elektron", "elektron sa gawas", "gibahin nga elektron", "bugkos", "Lewis nga diagram"], "fact": {"tl": "Ang Lewis dot structure ay isang larawan na gumagamit ng mga tuldok upang ipakita ang mga valence electron ng atom at kung paano sila pinaghahatian sa pagbuo ng bono.", "en": "A Lewis dot structure is a diagram that uses dots to show an atom's valence electrons and how those electrons are shared to form chemical bonds.", "bis": "Ang Lewis dot structure usa ka drowing nga naggamit ug mga tuldok aron ipakita ang valence electron sa atomo ug kon giunsa kini pagbahin aron maporma ang mga bugkos."}, "source": "encyclopedia-stable consensus; NRC PS1.A (atomic structure and bonding)", "generator": "claude-workflow", "reviewed": false},
  {"id": "lihiya-lye-jar-kakanin-g7", "domain": "MATTER", "topic": "lye as a base in kakanin", "grades": [6, 7, 8], "terms": ["lihiya", "lye", "kakanin", "base", "alkaline", "pH", "kutsinta", "puto", "alkali", "asido", "mabasa", "base nga sangkap", "kakanin", "alkaline nga lihiya", "lye sa kakanin"], "fact": {"tl": "Ang lihiya ay isang base o alkaline na sangkap na idinadagdag sa ilang kakanin tulad ng kutsinta upang baguhin ang kulay at texture ng kanin o galapong.", "en": "Lihiya (lye) is a base, or alkaline substance, added to some rice cakes like kutsinta to change the color and texture of the rice batter.", "bis": "Ang lihiya usa ka base o alkaline nga sangkap nga idugang sa ubang kakanin sama sa kutsinta aron usbon ang kolor ug texture sa giling nga bugas."}, "source": "encyclopedia-stable consensus; NRC PS1.B (acids and bases)", "generator": "claude-workflow", "reviewed": false},
  {"id": "making-bibingka-baking-g5", "domain": "MATTER", "topic": "baking batter into bibingka", "grades": [4, 5, 6], "terms": ["bibingka", "baking", "pagluluto", "naghuhurno", "galapong", "batter", "init", "kakanin", "tumitigas", "lumalaki", "nagbabago", "rice cake", "irreversible", "giluto", "naggahi", "init sa hudno", "nagdako"], "fact": {"tl": "Kapag iniluluto ang malabnaw na galapong sa init, ito ay lumalaki at tumitigas na hindi na maaaring ibalik sa dati, kaya nagiging bibingka.", "en": "When the runny rice batter is baked with heat, it rises and firms up in a change that cannot be reversed, turning into bibingka.", "bis": "Kon lutoon ang labnaw nga galing sa init, kini modako ug mogahi sa kausaban nga dili na mabalik, busa mahimo kining bibingka."}, "source": "NRC PS1.B (irreversible chemical change in cooking)", "generator": "claude-workflow", "reviewed": false},
  {"id": "making-tubig-buko-juice-mixture-g4", "domain": "MATTER", "topic": "making buko juice mixture", "grades": [3, 4, 5], "terms": ["buko juice", "tubig buko", "buko", "coconut water", "halo", "mixture", "natunaw", "asukal", "dissolve", "naghahalo", "inumin", "solution", "nagtunaw", "sagol", "tubig sa lubi", "magsagol"], "fact": {"tl": "Ang tubig buko ay nagiging matamis na inumin kapag hinaluan ng asukal na natutunaw at kumakalat nang pantay sa buong likido, na bumubuo ng pinaghalong sangkap.", "en": "Buko juice becomes a sweet drink when sugar is mixed in and dissolves, spreading evenly through the liquid to form a mixture.", "bis": "Ang tubig sa buko mahimong tam-is nga ilimnon kon sagolan ug asukal nga matunaw ug mokatag nga patas sa tibuok likido, nga maghimo ug sinagol."}, "source": "NRC PS1.A (mixtures and solutions; dissolving)", "generator": "claude-workflow", "reviewed": false},
  {"id": "matchstick-g5", "domain": "MATTER", "topic": "matchstick burning by friction", "grades": [4, 5, 6], "terms": ["matchstick", "posporo", "match", "kiskis", "friction", "init", "apoy", "ningas", "sunog", "kemikal", "burning", "ignition", "pagkiskis", "kalayo", "magdilaab", "sunog sa posporo"], "fact": {"tl": "Kapag ikiniskis ang ulo ng posporo sa magaspang na bahagi, ang init mula sa friction ay nagpapaningas ng kemikal at lumilikha ng apoy.", "en": "When a matchstick head is struck against a rough strip, the heat from friction ignites the chemicals and makes a flame.", "bis": "Kon kiskison ang ulo sa posporo sa gahi nga bahin, ang kainit gikan sa friction modilaab sa kemikal ug maghimo ug kalayo."}, "source": "encyclopedia-stable consensus; NRC PS3.B / PS1.B (friction heat; combustion)", "generator": "claude-workflow", "reviewed": false},
  {"id": "material-samples-four-types-g4", "domain": "MATTER", "topic": "common materials and their properties", "grades": [3, 4, 5], "terms": ["materials", "materyales", "kahoy", "metal", "bakal", "plastik", "salamin", "glass", "wood", "plastic", "properties", "katangian", "matigas", "malambot", "kabtangan", "kahoy", "puthaw", "salamin", "matig-a"], "fact": {"tl": "Ang mga bagay sa paligid ay gawa sa iba't ibang materyales tulad ng kahoy, metal, plastik, at salamin, at bawat isa ay may sariling katangian gaya ng tigas o kintab.", "en": "Objects around us are made of different materials such as wood, metal, plastic, and glass, and each one has its own properties like hardness or shininess.", "bis": "Ang mga butang sa atong palibot hinimo gikan sa lain-laing materyales sama sa kahoy, puthaw, plastik, ug salamin, ug ang matag usa adunay kaugalingong kabtangan sama sa katig-a o kasinaw."}, "source": "NRC PS1.A (properties of materials); DepEd G3-4 Matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "molecule-models-g8", "domain": "MATTER", "topic": "molecule models showing bonded atoms", "grades": [7, 8, 9], "terms": ["molecule models", "molekula", "molecule", "atom", "atomo", "bono", "bond", "model", "modelo", "bola", "balls and sticks", "compound", "sumpay", "modelo sa molekula", "molekula nga modelo"], "fact": {"tl": "Ang molecule model ay gumagamit ng mga bola at stick upang ipakita kung paano nagkakabit ang mga atom sa pamamagitan ng bono upang bumuo ng isang molekula.", "en": "A molecule model uses balls and sticks to show how atoms join together through bonds to form a molecule.", "bis": "Ang molecule model naggamit ug mga bola ug sungkod aron ipakita kon giunsa pagdugtong sa mga atomo pinaagi sa mga bond aron maporma ang usa ka molekula."}, "source": "encyclopedia-stable consensus; NRC PS1.A (atoms and molecules)", "generator": "claude-workflow", "reviewed": false},
  {"id": "oil-paint-protects-metal-g6", "domain": "MATTER", "topic": "paint protecting metal from rust", "grades": [5, 6, 7], "terms": ["pintura", "paint", "oil paint", "metal", "bakal", "kalawang", "rust", "nagpoprotekta", "barrier", "hangin", "oxygen", "tubig", "rusting", "puthaw", "taya", "nagpanalipod", "proteksyon sa puthaw", "kalawang"], "fact": {"tl": "Ang pintura sa metal ay gumagawa ng manipis na takip na pumipigil sa hangin at tubig na makadikit sa bakal, kaya hindi ito madaling kalawangin.", "en": "Paint on metal forms a thin coating that keeps air and water from touching the iron, so the metal does not rust as easily.", "bis": "Ang pintura sa metal maghimo ug nipis nga tabon nga magpugong sa hangin ug tubig nga makadikit sa puthaw, busa dili kini dali nga tay-an."}, "source": "encyclopedia-stable consensus; NRC PS1.B (preventing corrosion)", "generator": "claude-workflow", "reviewed": false},
  {"id": "oil-vinegar-separating-g5", "domain": "MATTER", "topic": "oil and vinegar separating into layers", "grades": [4, 5, 6], "terms": ["mantika", "oil", "suka", "vinegar", "naghihiwalay", "layers", "patong", "lumulutang", "hindi naghahalo", "immiscible", "density", "naghiwalay", "lana", "suka", "magbulag", "magpatong", "naglutaw", "dili magsagol", "mantika ug suka"], "fact": {"tl": "Kapag pinaghalo ang mantika at suka, naghihiwalay sila sa magkaibang patong dahil mas magaan ang mantika at hindi ito naghahalo sa suka.", "en": "When oil and vinegar are put together, they separate into layers because oil is lighter and does not mix with the watery vinegar.", "bis": "Kon sagolon ang mantika ug suka, magbulag sila sa magkalainlain nga patong tungod kay mas gaan ang mantika ug dili kini magsagol sa suka."}, "source": "NRC PS1.A (immiscible liquids; density)", "generator": "claude-workflow", "reviewed": false},
  {"id": "oil-water-immiscible-shake-g5", "domain": "MATTER", "topic": "oil and water do not mix", "grades": [4, 5, 6], "terms": ["mantika", "oil", "tubig", "water", "hindi naghahalo", "immiscible", "lumulutang", "nagkakahiwalay", "shake", "iniling", "layers", "dili magsagol", "lana", "tubig", "naglutaw", "magbulag balik", "uyog", "mantika ug tubig"], "fact": {"tl": "Kahit ilingin nang malakas ang mantika at tubig, magkakahiwalay pa rin sila dahil hindi naghahalo ang dalawa at lumulutang ang mantika sa ibabaw.", "en": "Even if you shake oil and water hard, they still separate because the two do not mix and the lighter oil floats on top.", "bis": "Bisan uyogon pag-ayo ang mantika ug tubig, magbulag gihapon sila tungod kay dili magsagol ang duha ug ang mas gaan nga mantika molutaw sa ibabaw."}, "source": "NRC PS1.A (immiscible liquids)", "generator": "claude-workflow", "reviewed": false},
  {"id": "periodic-trends-g10", "domain": "MATTER", "topic": "periodic trends in the periodic table", "grades": [9, 10], "terms": ["periodic trends", "periodic table", "talahanayan", "pana-panahong talahanayan", "elemento", "element", "atomic size", "laki ng atom", "reactivity", "trend", "pattern", "grupo", "periyodo", "lamesa sa mga elemento", "patern", "gidak-on sa atomo"], "fact": {"tl": "Ang periodic trends ay mga regular na pattern sa periodic table, gaya ng paliit na laki ng atom habang papunta sa kanan ng isang periyodo.", "en": "Periodic trends are regular patterns in the periodic table, such as atoms getting smaller as you move from left to right across a period.", "bis": "Ang periodic trends mga regular nga patern sa periodic table, sama sa paggamay sa gidak-on sa atomo samtang molihok ngadto sa tuo sa usa ka periyodo."}, "source": "encyclopedia-stable consensus; NRC PS1.A (periodic table organization)", "generator": "claude-workflow", "reviewed": false},
  {"id": "ph-scale-g8", "domain": "MATTER", "topic": "pH scale measures acids and bases", "grades": [7, 8, 9], "terms": ["pH scale", "pH", "asido", "acid", "base", "neutral", "sukat", "panukat", "0 to 14", "litmus", "alkaline", "sukdanan", "sukod sa asido", "pH nga sukdanan", "tubig nga neutral"], "fact": {"tl": "Ang pH scale ay sukatan mula 0 hanggang 14 na nagsasabi kung gaano kaasido o kabase ang isang likido, kung saan ang 7 ay neutral tulad ng purong tubig.", "en": "The pH scale runs from 0 to 14 and tells how acidic or basic a liquid is, where 7 is neutral like pure water.", "bis": "Ang pH scale usa ka sukdanan gikan sa 0 hangtod 14 nga magsulti kon unsa ka asido o ka base ang usa ka likido, diin ang 7 neutral sama sa lunsay nga tubig."}, "source": "encyclopedia-stable consensus; NRC PS1.B (acids and bases)", "generator": "claude-workflow", "reviewed": false},
  {"id": "precipitate-forming-reaction-g9", "domain": "MATTER", "topic": "precipitate forming in a reaction", "grades": [8, 9, 10], "terms": ["precipitate", "namumuong solido", "namuo", "solid", "reaction", "reaksyon", "naghahalo", "dalawang likido", "cloudy", "labo", "chemical change", "nagbubuo", "namuong solido", "reaksyon", "malabo", "bag-ong solido"], "fact": {"tl": "Ang precipitate ay isang bagong solido na biglang nabubuo kapag pinaghalo ang dalawang likido, na nagpapakita na may naganap na reaksyong kemikal.", "en": "A precipitate is a new solid that suddenly forms when two clear liquids are mixed, showing that a chemical reaction has taken place.", "bis": "Ang precipitate usa ka bag-ong solido nga kalit nga maporma kon sagolon ang duha ka likido, nga nagpakita nga adunay nahitabo nga kemikal nga reaksyon."}, "source": "encyclopedia-stable consensus; NRC PS1.B (evidence of chemical reactions)", "generator": "claude-workflow", "reviewed": false},
  {"id": "reactants-products-arrow-diagram-g9", "domain": "MATTER", "topic": "reactants and products in chemical equations", "grades": [8, 9, 10], "terms": ["reactants", "products", "reactant", "produkto", "sangkap", "chemical equation", "ekwasyon", "arrow", "palaso", "pana", "reaksyon", "nagbabago", "before after", "pana sa reaksyon", "kemikal nga ekwasyon", "reactant ug produkto"], "fact": {"tl": "Sa isang chemical equation, ang mga reactant ay ang mga sangkap bago ang reaksyon at ang mga product ay ang mga bagong sangkap pagkatapos, na pinaghihiwalay ng palaso.", "en": "In a chemical equation, reactants are the substances before a reaction and products are the new substances formed after, separated by an arrow.", "bis": "Sa usa ka chemical equation, ang mga reactant mao ang mga sangkap sa wala pa ang reaksyon ug ang mga produkto mao ang bag-ong mga sangkap human niini, nga gibulag sa pana."}, "source": "encyclopedia-stable consensus; NRC PS1.B (conservation in reactions)", "generator": "claude-workflow", "reviewed": false},
  {"id": "reaction-rate-factors-g10", "domain": "MATTER", "topic": "factors affecting reaction rate", "grades": [9, 10], "terms": ["reaction rate", "bilis ng reaksyon", "factors", "temperatura", "temperature", "init", "concentration", "surface area", "catalyst", "bilis", "mabilis", "kadali sa reaksyon", "kainit", "katulin", "katalista", "temperatura sa reaksyon"], "fact": {"tl": "Ang bilis ng isang reaksyong kemikal ay tumataas kapag mas mainit, mas matindi ang konsentrasyon, o mas malaki ang surface area ng mga sangkap.", "en": "The rate of a chemical reaction goes faster when it is hotter, when the substances are more concentrated, or when they have more surface area exposed.", "bis": "Ang katulin sa usa ka kemikal nga reaksyon mas mopaspas kon mas init, kon mas baga ang konsentrasyon, o kon mas dako ang surface area sa mga sangkap."}, "source": "encyclopedia-stable consensus; NRC PS1.B (factors affecting reaction rates)", "generator": "claude-workflow", "reviewed": false},
  {"id": "salt-crystal-growing-pan-g6", "domain": "MATTER", "topic": "salt crystals forming by evaporation", "grades": [5, 6, 7], "terms": ["salt crystal", "asin", "kristal", "crystal", "evaporation", "sumingaw", "natutuyo", "nagbubuo", "tubig-alat", "saltwater", "kristal na asin", "growing crystals", "pag-alisngaw", "mihubas", "namuong kristal", "asin nga kristal"], "fact": {"tl": "Kapag sumingaw ang tubig mula sa tubig-alat sa kawali, naiiwan ang asin at unti-unti itong bumubuo ng matitigas na kristal na may patok-patok na hugis.", "en": "When water evaporates from saltwater in a pan, the salt is left behind and slowly forms hard, cube-shaped crystals.", "bis": "Kon mosingaw ang tubig gikan sa tubig-alat sa kalaha, ang asin mabilin ug hinay-hinay nga maporma ngadto sa gahi nga mga kristal nga daw kwadrado ang porma."}, "source": "NRC PS1.A (evaporation; crystallization; separating mixtures)", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-refilling-station-scene-g5", "domain": "MATTER", "topic": "water purification refilling station", "grades": [5, 6, 7], "terms": ["refilling station", "water station", "purified water", "tubig", "purified na tubig", "ligtas inumin", "pagsala ng tubig", "filter", "limpyo nga tubig", "tubig sa refilling", "gisala nga tubig", "filtration", "drinking water"], "fact": {"tl": "Sa water refilling station, dumadaan ang tubig sa mga filter at minsan sa ultraviolet light para alisin ang dumi at mikrobyo bago ito ligtas nang inumin.", "en": "At a water refilling station, water passes through filters and sometimes ultraviolet light to remove dirt and germs so it is safe to drink.", "bis": "Sa water refilling station, ang tubig moagi sa mga filter ug usahay sa ultraviolet light aron makuha ang hugaw ug mikrobyo aron luwas na kini imnon."}, "source": "encyclopedia-stable consensus; DepEd G5 Matter (mixtures/separation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "deforestation-erosion-cause-effect-g6", "domain": "EARTH_SPACE", "topic": "deforestation causes soil erosion", "grades": [5, 6, 7], "terms": ["deforestation", "pagkakalbo ng gubat", "pagputol ng puno", "soil erosion", "pagguho ng lupa", "pagkalbo sa kalasangan", "pagputol sa kahoy", "erosion", "ugat", "gamot", "roots hold soil", "runoff", "pagkahurot sa yuta"], "fact": {"tl": "Kapag pinuputol ang mga puno, nawawala ang mga ugat na humahawak sa lupa, kaya mas madaling natatangay ng ulan at tubig ang ibabaw na lupa o nagkakaroon ng soil erosion.", "en": "When trees are cut down, the roots that hold the soil are lost, so rain and water more easily wash away the topsoil, causing soil erosion.", "bis": "Kon putlon ang mga kahoy, mawala ang mga gamot nga naghupot sa yuta, busa mas dali nga maanod sa ulan ug tubig ang ibabaw nga yuta o mahitabo ang soil erosion."}, "source": "NRC ESS2; DepEd G6 Earth and Space", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-g4", "domain": "EARTH_SPACE", "topic": "planet Earth third planet life", "grades": [3, 4, 5], "terms": ["earth", "mundo", "daigdig", "planeta", "kalibutan", "planeta nga atong gipuy-an", "tubig", "hangin", "ikatlong planeta", "ikatulong planeta", "buhi nga binuhat", "life", "third planet from the sun"], "fact": {"tl": "Ang Earth o Mundo ang ikatlong planeta mula sa Araw at ang tanging planetang kilala nating may tubig, hangin, at mga nabubuhay na bagay.", "en": "Earth is the third planet from the Sun and the only planet we know that has liquid water, air, and living things.", "bis": "Ang Earth o Kalibutan mao ang ikatulong planeta gikan sa Adlaw ug mao lang ang planeta nga atong nahibal-an nga adunay tubig, hangin, ug buhing mga binuhat."}, "source": "NRC ESS1; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "flash-flood-river-overflow-g5", "domain": "EARTH_SPACE", "topic": "flash flood river overflow heavy rain", "grades": [4, 5, 6], "terms": ["flash flood", "biglang baha", "rumaragasang baha", "baha", "pag-apaw ng ilog", "kalit nga baha", "pagbaha", "pag-awas sa suba", "malakas na ulan", "kusog nga ulan", "river overflow", "bagyo", "heavy rain"], "fact": {"tl": "Ang flash flood o biglang baha ay nangyayari kapag napakalakas at napakabilis ng ulan kaya umaapaw ang ilog at dumadagsa ang tubig sa mababang lugar nang walang babala.", "en": "A flash flood happens when rain is so heavy and fast that the river overflows and water rushes into low areas with little warning.", "bis": "Ang flash flood o kalit nga baha mahitabo kon ang ulan kusog ug paspas kaayo mao nga moawas ang suba ug modagsa ang tubig sa ubos nga dapit nga walay pasidaan."}, "source": "encyclopedia-stable consensus; PAGASA; DepEd G5 Earth and Space", "generator": "claude-workflow", "reviewed": false},
  {"id": "hill-g4", "domain": "EARTH_SPACE", "topic": "hill landform smaller than mountain", "grades": [3, 4, 5], "terms": ["hill", "burol", "bundok-bundok", "landform", "anyong lupa", "bungtod", "gamay nga bukid", "mas mababa sa bundok", "mas mubo sa bukid", "tagaytay", "elevated land", "mound", "mababang bundok"], "fact": {"tl": "Ang burol ay isang nakataas na bahagi ng lupa na mas mababa at mas pabilog ang tuktok kaysa sa isang bundok.", "en": "A hill is a raised area of land that is lower and more rounded at the top than a mountain.", "bis": "Ang bungtod usa ka habog nga bahin sa yuta nga mas mubo ug mas lingin ang tumoy kompara sa usa ka bukid."}, "source": "encyclopedia-stable consensus; DepEd G4 Earth and Space (landforms)", "generator": "claude-workflow", "reviewed": false},
  {"id": "milky-way-over-mountains-g6", "domain": "EARTH_SPACE", "topic": "Milky Way galaxy band of stars", "grades": [5, 6, 7, 8], "terms": ["milky way", "kalawakan", "galaksiya", "galaxy", "milky way galaxy", "bituin", "bitoon", "galaksi", "gatusan ka bilyon nga bituon", "bilyon-bilyong bituin", "atong galaksiya", "band of stars", "night sky", "langit sa gabii"], "fact": {"tl": "Ang makinang na guhit ng mga bituin sa madilim na kalangitan ay ang Milky Way, ang ating sariling galaksiya na binubuo ng daan-daang bilyong bituin kasama ang ating Araw.", "en": "The glowing band of stars in a dark sky is the Milky Way, our own galaxy made of hundreds of billions of stars including our Sun.", "bis": "Ang nagsidlak nga linya sa mga bituon sa ngitngit nga langit mao ang Milky Way, ang atong kaugalingong galaksiya nga gilangkoban sa gatusan ka bilyon nga bituon lakip ang atong Adlaw."}, "source": "NRC ESS1; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mining-tailings-pond-scene-g8", "domain": "EARTH_SPACE", "topic": "mine tailings pond water pollution", "grades": [7, 8, 9, 10], "terms": ["mine tailings", "tailings pond", "minahan", "dumi ng minahan", "polusyon sa tubig", "tailings", "hugaw sa minahan", "mina", "kemikal", "chemical", "heavy metals", "polusyon", "kontaminado", "water pollution", "labi sa minahan"], "fact": {"tl": "Ang tailings pond ay imbakan ng natitirang putik at kemikal mula sa pagmimina, at kung tumagas ito ay maaaring magdala ng mabibigat na metal na nakakalason sa tubig at lupa.", "en": "A tailings pond stores the leftover mud and chemicals from mining, and if it leaks it can carry heavy metals that poison nearby water and soil.", "bis": "Ang tailings pond mao ang gibutangan sa nahabilin nga lapok ug kemikal gikan sa pagmina, ug kon motulo kini makadala ug bug-at nga metal nga makahilo sa tubig ug yuta."}, "source": "encyclopedia-stable consensus; DepEd JHS Earth and Space (human impact)", "generator": "claude-workflow", "reviewed": false},
  {"id": "moon-crescent-g4", "domain": "EARTH_SPACE", "topic": "crescent moon phase thin sliver", "grades": [3, 4, 5], "terms": ["crescent moon", "buwan", "bulan", "gasuglit nga bulan", "manipis na buwan", "phase of the moon", "yugto ng buwan", "pagbag-o sa bulan", "sinag ng araw", "silaw sa adlaw", "kurba", "curved sliver", "moon phase"], "fact": {"tl": "Ang crescent moon ay manipis at hugis-kurbang anyo ng buwan na nakikita kapag maliit na bahagi lang nito ang natatamaan ng sikat ng Araw sa harap natin.", "en": "A crescent moon is the thin, curved shape we see when only a small part of the Moon facing us is lit by the Sun.", "bis": "Ang crescent moon mao ang nipis ug kurba nga porma sa bulan nga makita kon gamay ra nga bahin niini nga nag-atubang kanato ang nasilawan sa Adlaw."}, "source": "NRC ESS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "moon-phases-ball-lamp-demo-g6", "domain": "EARTH_SPACE", "topic": "moon phases model ball and lamp", "grades": [5, 6, 7], "terms": ["moon phases", "bahagi ng buwan", "mga yugto ng buwan", "ball and lamp", "bola at ilaw", "modelo", "model", "demo", "hugis ng buwan", "ikot ng buwan", "pag-ikot sa bulan", "lamp", "shadow", "anino", "lighted half"], "fact": {"tl": "Maipapakita ang mga yugto ng buwan sa pamamagitan ng bola at ilaw: habang umiikot ang bola sa paligid mo, nagbabago kung gaano karami sa naliliwanagang kalahati nito ang nakikita mo, gaya ng tunay na buwan sa Araw.", "en": "Moon phases can be shown with a ball and a lamp: as the ball moves around you, you see different amounts of its lit half, just like the real Moon lit by the Sun.", "bis": "Ang mga hugna sa bulan mapakita pinaagi sa bola ug suga: samtang naglibot ang bola kanimo, magkalainlain ang imong makita sa nasilawan nga katunga niini, sama sa tinuod nga bulan nga gisilawan sa Adlaw."}, "source": "NRC ESS1.B; AAAS Benchmarks (models of sky motions)", "generator": "claude-workflow", "reviewed": false},
  {"id": "morning-mist-over-rice-field-g5", "domain": "EARTH_SPACE", "topic": "morning mist fog condensation", "grades": [4, 5, 6], "terms": ["morning mist", "ulap sa umaga", "hamog", "fog", "mist", "gabon", "ambon", "alimuom", "palayan", "rice field", "umaga", "buntag", "condensation", "pagsingaw", "nagsingaw na tubig", "cool air"], "fact": {"tl": "Ang ulap-ulap o hamog sa umaga sa palayan ay nabubuo kapag lumalamig ang hangin sa gabi at ang singaw ng tubig sa hangin ay nagiging maliliit na patak na lumulutang.", "en": "The morning mist over a rice field forms when the night air cools and water vapor in the air turns into tiny floating droplets.", "bis": "Ang gabon sa buntag sa basakan maporma kon mobugnaw ang hangin sa gabii ug ang alisngaw sa tubig sa hangin mahimong gagmayng tulo nga naglutaw."}, "source": "NRC ESS2; encyclopedia-stable consensus (water cycle/condensation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "mount-apo-peak-g6", "domain": "EARTH_SPACE", "topic": "Mount Apo highest mountain Philippines", "grades": [5, 6, 7], "terms": ["mount apo", "bundok apo", "bukid sa apo", "pinakamataas na bundok", "highest mountain", "labing taas nga bukid", "mindanao", "davao", "bulkan", "volcano", "stratovolcano", "2954 metro", "Philippines highest peak", "taluktok"], "fact": {"tl": "Ang Mount Apo sa Mindanao ang pinakamataas na bundok sa Pilipinas, na umaabot sa mga 2,954 metro ang taas, at isang uri ng bulkan.", "en": "Mount Apo in Mindanao is the highest mountain in the Philippines, rising about 2,954 meters, and it is a type of volcano.", "bis": "Ang Mount Apo sa Mindanao mao ang labing taas nga bukid sa Pilipinas, mokabat ug mga 2,954 ka metro ang gitas-on, ug usa ka klase sa bulkan."}, "source": "encyclopedia-stable consensus; PHIVOLCS", "generator": "claude-workflow", "reviewed": false},
  {"id": "mount-pulag-sea-of-clouds-g6", "domain": "EARTH_SPACE", "topic": "Mount Pulag sea of clouds", "grades": [5, 6, 7], "terms": ["mount pulag", "bundok pulag", "bukid sa pulag", "sea of clouds", "dagat ng ulap", "dagat sa panganod", "luzon", "benguet", "pinakamataas sa luzon", "labing taas sa luzon", "cordillera", "clouds below", "ulap sa ibaba"], "fact": {"tl": "Ang Mount Pulag sa Luzon ay isa sa pinakamataas na bundok sa Pilipinas, at sa taas nito ay madalas mong makita ang \"sea of clouds\" kung saan nasa ibaba mo na ang mga ulap.", "en": "Mount Pulag in Luzon is one of the highest mountains in the Philippines, and at its peak you can often see a \"sea of clouds\" where the clouds lie below you.", "bis": "Ang Mount Pulag sa Luzon usa sa labing taas nga mga bukid sa Pilipinas, ug sa tumoy niini kasagaran makita ang \"sea of clouds\" diin ang mga panganod anaa na sa ilalom nimo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mountain-hot-spring-pool-g6", "domain": "EARTH_SPACE", "topic": "hot spring geothermal heated water", "grades": [5, 6, 7, 8], "terms": ["hot spring", "mainit na bukal", "init nga tubod", "mainit na tubig", "init nga tubig", "bulkan", "volcano", "geothermal", "lupa sa ilalim", "magma", "init gikan sa yuta", "natural na mainit na tubig", "heated underground", "balneario"], "fact": {"tl": "Ang mainit na bukal o hot spring ay tubig sa lupa na napainit ng mga mainit na bato sa ilalim, kadalasang malapit sa mga bulkan, kaya umaagos itong mainit pataas.", "en": "A hot spring is groundwater heated by hot rocks deep underground, often near volcanoes, so it flows up to the surface warm.", "bis": "Ang init nga tubod o hot spring mao ang tubig sa yuta nga gipainit sa mga init nga bato sa ilalom, kasagaran duol sa mga bulkan, busa moagas kini nga mainit paingon sa ibabaw."}, "source": "NRC ESS2; encyclopedia-stable consensus (geothermal)", "generator": "claude-workflow", "reviewed": false},
  {"id": "mountain-g4", "domain": "EARTH_SPACE", "topic": "mountain landform tall raised land", "grades": [3, 4, 5], "terms": ["mountain", "bundok", "bukid", "anyong lupa", "landform", "mataas na lupa", "habog nga yuta", "tuktok", "taluktok", "tumoy", "tall land", "peak", "mas mataas sa burol", "raised land", "mas taas sa bungtod"], "fact": {"tl": "Ang bundok ay napakataas na anyong lupa na may matarik na gilid, at ito ay mas mataas at mas malaki kaysa sa isang burol.", "en": "A mountain is a very tall landform with steep sides, and it is higher and bigger than a hill.", "bis": "Ang bukid usa ka taas kaayo nga porma sa yuta nga adunay tarik nga kilid, ug mas taas ug mas dako kini kaysa usa ka bungtod."}, "source": "encyclopedia-stable consensus; DepEd G4 Earth and Space (landforms)", "generator": "claude-workflow", "reviewed": false},
  {"id": "natural-rock-arch-coast-g7", "domain": "EARTH_SPACE", "topic": "sea arch coastal erosion by waves", "grades": [6, 7, 8], "terms": ["rock arch", "sea arch", "natural arch", "bato na arko", "arko nga bato", "alon", "balod", "coastal erosion", "pagguho dahil sa alon", "pagkakanat sa bato", "waves carve", "tubig dagat", "dagat", "weathering", "naukit ng alon"], "fact": {"tl": "Ang natural na arko sa baybayin ay nabubuo kapag unti-unting inuukit ng malalakas na alon ang mahinang bahagi ng bato hanggang magkabutas ito na parang tulay.", "en": "A natural rock arch on the coast forms when strong waves slowly carve away the weaker part of the rock until a hole opens, leaving a bridge of stone.", "bis": "Ang natural nga arko sa baybayon maporma kon ang kusog nga balod hinay-hinay nga moukit sa luya nga bahin sa bato hangtod nga maabli kini sama sa taytayan nga bato."}, "source": "NRC ESS2; encyclopedia-stable consensus (coastal erosion)", "generator": "claude-workflow", "reviewed": false},
  {"id": "observatory-dome-night-g7", "domain": "EARTH_SPACE", "topic": "observatory telescope studying sky", "grades": [5, 6, 7, 8], "terms": ["observatory", "obserbatoryo", "teleskopyo", "telescope", "pag-aaral ng kalangitan", "bituin", "bitoon", "domo", "dome", "pagtuon sa langit", "astronomer", "astronomo", "pagmasid sa langit", "study the sky", "stars and planets"], "fact": {"tl": "Ang observatory ay gusaling may malaking teleskopyo sa loob ng umiikot na domo, ginagamit ng mga astronomo para pag-aralan ang mga bituin, planeta, at iba pang bagay sa kalangitan.", "en": "An observatory is a building with a large telescope inside a rotating dome, used by astronomers to study stars, planets, and other objects in the sky.", "bis": "Ang observatory usa ka building nga adunay dako nga teleskopyo sulod sa nagatuyok nga dome, gigamit sa mga astronomo aron tun-an ang mga bituon, planeta, ug uban pang butang sa langit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "oil-spill-shore-scene-g7", "domain": "MATTER", "topic": "oil spill water pollution harm wildlife", "grades": [6, 7, 8, 9], "terms": ["oil spill", "pagtagas ng langis", "langis sa dagat", "lana sa dagat", "polusyon sa dagat", "oil pollution", "natulo nga lana", "lumulutang na langis", "lutaw nga lana", "isda", "ibon", "marine life", "hayop sa dagat", "floats on water", "harm wildlife"], "fact": {"tl": "Sa isang oil spill, lumulutang ang langis sa ibabaw ng tubig dagat dahil mas magaan ito kaysa tubig, at ito ay nakakapinsala sa mga isda, ibon, at iba pang nilalang sa dagat.", "en": "In an oil spill, oil floats on top of seawater because it is lighter than water, and it harms fish, birds, and other sea life.", "bis": "Sa usa ka oil spill, ang lana molutaw sa ibabaw sa tubig-dagat tungod kay mas gaan kini kaysa tubig, ug makadaot kini sa mga isda, langgam, ug uban pang binuhat sa dagat."}, "source": "encyclopedia-stable consensus; DepEd JHS Matter / human impact", "generator": "claude-workflow", "reviewed": false},
  {"id": "outdoor-thermometer-strip-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "thermometer measures temperature", "grades": [3, 4, 5, 6], "terms": ["thermometer", "termometro", "temperatura", "init", "lamig", "bugnaw", "sukat ng init", "sukod sa kainit", "degrees", "Celsius", "sukatan ng temperatura", "measure temperature", "kainit", "panahon", "weather temperature"], "fact": {"tl": "Ang termometro ay sukatan na nagsasabi kung gaano kainit o kalamig ang isang bagay o ang hangin, at karaniwang nakasukat ito sa degrees Celsius.", "en": "A thermometer is a tool that tells how hot or cold something or the air is, usually measured in degrees Celsius.", "bis": "Ang termometro usa ka himan nga nagsulti kon unsa ka init o ka bugnaw ang usa ka butang o ang hangin, kasagaran gisukod sa degrees Celsius."}, "source": "NRC PS3; DepEd G4 Force, Motion, and Energy (heat/temperature)", "generator": "claude-workflow", "reviewed": false},
  {"id": "pagsanjan-falls-gorge-g6", "domain": "EARTH_SPACE", "topic": "Pagsanjan Falls waterfall gorge Laguna", "grades": [5, 6, 7], "terms": ["pagsanjan falls", "talon ng pagsanjan", "busay sa pagsanjan", "waterfall", "talon", "busay", "laguna", "gorge", "bangin", "lambak", "ilog", "suba", "river carved", "naukit ng tubig", "Cavinti falls", "tubig na bumabagsak"], "fact": {"tl": "Ang Pagsanjan Falls sa Laguna ay isang tanyag na talon kung saan bumabagsak ang tubig sa pagitan ng matatarik na bangin na unti-unting inukit ng umaagos na ilog sa loob ng mahabang panahon.", "en": "Pagsanjan Falls in Laguna is a famous waterfall where water drops between steep cliffs of a gorge slowly carved by the flowing river over a long time.", "bis": "Ang Pagsanjan Falls sa Laguna usa ka bantog nga busay diin nahulog ang tubig taliwala sa tarik nga mga pangpang sa gorge nga hinay-hinay nga giukit sa nagaagos nga suba sa dugay nga panahon."}, "source": "encyclopedia-stable consensus (river erosion); NRC ESS2", "generator": "claude-workflow", "reviewed": false},
  {"id": "palawan-underground-river-g6", "domain": "EARTH_SPACE", "topic": "Palawan underground river cave limestone", "grades": [5, 6, 7, 8], "terms": ["palawan underground river", "underground river", "ilog sa ilalim ng lupa", "suba sa ilalom sa yuta", "kweba", "langob", "cave", "limestone", "apog na bato", "puerto princesa", "stalactite", "stalagmite", "world heritage", "naukit na bato", "tubig sa kweba"], "fact": {"tl": "Ang Palawan Underground River sa Puerto Princesa ay isang ilog na umaagos sa loob ng malaking kweba ng apog na bato (limestone) na unti-unting naukit ng tubig sa loob ng libu-libong taon.", "en": "The Palawan Underground River in Puerto Princesa is a river that flows inside a large limestone cave slowly dissolved and carved by water over thousands of years.", "bis": "Ang Palawan Underground River sa Puerto Princesa usa ka suba nga nagaagos sulod sa dako nga langob nga apog nga bato (limestone) nga hinay-hinay nga giukit sa tubig sulod sa liboan ka tuig."}, "source": "encyclopedia-stable consensus; NRC ESS2 (weathering of limestone)", "generator": "claude-workflow", "reviewed": false},
  {"id": "planet-size-comparison-g6", "domain": "EARTH_SPACE", "topic": "planet sizes Jupiter largest Mercury smallest", "grades": [5, 6, 7], "terms": ["planet size", "laki ng planeta", "gidak-on sa planeta", "jupiter", "pinakamalaking planeta", "largest planet", "labing dako nga planeta", "mercury", "pinakamaliit", "labing gamay", "comparison", "paghahambing", "pagtandi", "earth size", "gas giant"], "fact": {"tl": "Sa walong planeta ng ating Solar System, ang Jupiter ang pinakamalaki at ang Mercury ang pinakamaliit, at ang Earth ay maliit lang kung ihahambing sa Jupiter.", "en": "Among the eight planets of our Solar System, Jupiter is the largest and Mercury is the smallest, and Earth is small compared to Jupiter.", "bis": "Sa walo ka planeta sa atong Solar System, ang Jupiter mao ang labing dako ug ang Mercury mao ang labing gamay, ug ang Earth gamay ra kon itandi sa Jupiter."}, "source": "NRC ESS1; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "planets-lineup-sky-g6", "domain": "EARTH_SPACE", "topic": "planets visible night sky points of light", "grades": [5, 6, 7], "terms": ["planets in the sky", "planeta sa langit", "planeta sa kalangitan", "venus", "mars", "jupiter", "saturn", "bituin vs planeta", "bitoon", "kuminang na tuldok", "naa sa langit", "naked eye", "hindi kumukurap", "wala mokurap", "points of light", "alignment"], "fact": {"tl": "Ang ilang planeta gaya ng Venus, Mars, Jupiter, at Saturn ay nakikita sa kalangitan na parang maliliwanag na tuldok, ngunit hindi sila kumukurap tulad ng mga bituin dahil mas malapit sila sa atin.", "en": "Some planets like Venus, Mars, Jupiter, and Saturn can be seen in the sky as bright points of light, but they do not twinkle like stars because they are much closer to us.", "bis": "Ang pipila ka planeta sama sa Venus, Mars, Jupiter, ug Saturn makita sa langit nga mura'g hayag nga mga tuldok, apan dili sila mokurap sama sa mga bituon tungod kay mas duol sila kanato."}, "source": "NRC ESS1; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "plate-boundaries-g8", "domain": "EARTH_SPACE", "topic": "tectonic plate boundaries earthquakes volcanoes", "grades": [7, 8, 9, 10], "terms": ["plate boundaries", "tectonic plates", "mga plate", "plato sa yuta", "lindol", "linog", "earthquake", "bulkan", "volcano", "ring of fire", "magkadikit na plate", "nagdugtong nga plate", "fault", "lindol at bulkan", "PHIVOLCS", "crust"], "fact": {"tl": "Ang balat ng Earth ay nahahati sa malalaking piraso na tinatawag na tectonic plates, at sa mga hangganan kung saan nagkikiskisan o nagbabanggaan ang mga ito ay madalas magkaroon ng lindol at bulkan.", "en": "Earth's outer shell is broken into large pieces called tectonic plates, and along the boundaries where they grind or collide, earthquakes and volcanoes often occur.", "bis": "Ang gawas nga panit sa Earth nabahin sa dagkong mga piraso nga gitawag og tectonic plates, ug sa mga utlanan diin sila magkiskis o magbangga, kasagaran adunay linog ug bulkan."}, "source": "NRC ESS2; DepEd G10 Earth and Space; PHIVOLCS", "generator": "claude-workflow", "reviewed": false},
  {"id": "plateau-highland-g6", "domain": "EARTH_SPACE", "topic": "plateau flat-topped highland landform", "grades": [5, 6, 7], "terms": ["plateau", "talampas", "patag nga habog", "highland", "anyong lupa", "landform", "patag na mataas na lupa", "flat-topped", "mataas at patag", "habog ug patag", "table land", "elevated flat land", "bukirang patag", "raised plain"], "fact": {"tl": "Ang talampas o plateau ay malawak na anyong lupa na patag ang ibabaw ngunit nakataas kaysa sa lupang nakapaligid dito.", "en": "A plateau is a wide landform that is flat on top but raised higher than the land around it.", "bis": "Ang plateau o talampas usa ka lapad nga porma sa yuta nga patag ang ibabaw apan mas habog kaysa yuta nga naglibot niini."}, "source": "encyclopedia-stable consensus; DepEd Earth and Space (landforms)", "generator": "claude-workflow", "reviewed": false},
  {"id": "pyroclastic-flow-g9", "domain": "EARTH_SPACE", "topic": "pyroclastic flow volcanic eruption hazard", "grades": [8, 9, 10], "terms": ["pyroclastic flow", "pyroclastic", "putok ng bulkan", "buto sa bulkan", "bulkan", "volcano", "mainit na gas at abo", "init nga gas ug abo", "fast hot cloud", "volcanic hazard", "panganib sa bulkan", "deadly", "Pinatubo", "Mayon", "PHIVOLCS"], "fact": {"tl": "Ang pyroclastic flow ay napakainit at napakabilis na agos ng gas, abo, at bato na bumababa sa gilid ng bulkan kapag sumasabog, at ito ang isa sa pinakamapanganib na bahagi ng pagputok.", "en": "A pyroclastic flow is a scorching, very fast current of gas, ash, and rock that races down a volcano during an eruption, and it is one of the most dangerous parts of an eruption.", "bis": "Ang pyroclastic flow usa ka init kaayo ug paspas kaayo nga agos sa gas, abo, ug bato nga modagan paubos sa kilid sa bulkan panahon sa pagbuto, ug usa kini sa labing delikado nga bahin sa pagbuto."}, "source": "NRC ESS2; PHIVOLCS; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rain-cloud-g4", "domain": "EARTH_SPACE", "topic": "rain cloud water droplets fall as rain", "grades": [3, 4, 5], "terms": ["rain cloud", "ulap ng ulan", "panganod sa ulan", "ulan", "ulap", "panganod", "mga patak ng tubig", "tulo sa tubig", "madilim na ulap", "itom nga panganod", "water droplets", "nimbus", "bumibigat ang ulap", "falls as rain", "kondensasyon"], "fact": {"tl": "Ang ulap ng ulan ay binubuo ng napakaraming maliliit na patak ng tubig, at kapag lumalaki at bumibigat ang mga ito, nahuhulog sila bilang ulan.", "en": "A rain cloud is made of countless tiny water droplets, and when those droplets grow large and heavy enough, they fall as rain.", "bis": "Ang panganod sa ulan gilangkoban sa daghan kaayo nga gagmayng tulo sa tubig, ug kon modako ug mobug-at na kini, mahulog sila isip ulan."}, "source": "NRC ESS2; DepEd G4 Earth and Space (water cycle)", "generator": "claude-workflow", "reviewed": false},
  {"id": "rain-collection-measure-scene-g5", "domain": "EARTH_SPACE", "topic": "measuring rainfall collected in container", "grades": [4, 5, 6], "terms": ["measure rainfall", "sukat ng ulan", "pagsukat ng ulan", "pagsukod sa ulan", "rainfall", "dami ng ulan", "kadaghan sa ulan", "lalagyan", "sudlanan", "container", "millimeter", "rain measurement", "PAGASA", "kolekta ng tubig-ulan", "depth of water"], "fact": {"tl": "Para malaman kung gaano kalakas ang ulan, sinasalo ang tubig-ulan sa isang lalagyan at sinusukat kung gaano kataas ang naipong tubig, kadalasang sa milimetro.", "en": "To find out how much it rained, rainwater is caught in a container and the depth of the collected water is measured, usually in millimeters.", "bis": "Aron mahibal-an kon unsa ka kusog ang ulan, ang tubig-ulan sakpon sa usa ka sudlanan ug sukdon kon unsa ka lawom ang natigom nga tubig, kasagaran sa milimetro."}, "source": "PAGASA; DepEd G5 Earth and Space (weather measurement)", "generator": "claude-workflow", "reviewed": false},
  {"id": "rain-gauge-jar-collector-g5", "domain": "EARTH_SPACE", "topic": "rain gauge instrument measures rainfall", "grades": [4, 5, 6], "terms": ["rain gauge", "panukat ng ulan", "sukdanan sa ulan", "rain gauge instrument", "sukatan ng ulan", "rainfall", "dami ng ulan", "milimetro", "millimeter", "weather instrument", "kasangkapan sa panahon", "PAGASA", "lalagyan ng ulan", "measures rain"], "fact": {"tl": "Ang rain gauge ay kasangkapan sa panahon na sumasalo at sumusukat ng dami ng ulan na bumagsak sa isang lugar, karaniwang ipinapakita sa milimetro.", "en": "A rain gauge is a weather instrument that catches and measures how much rain has fallen in a place, usually shown in millimeters.", "bis": "Ang rain gauge usa ka himan sa panahon nga nagsakop ug nagsukod kon pila ka ulan ang nahulog sa usa ka dapit, kasagaran gipakita sa milimetro."}, "source": "PAGASA; DepEd G5 Earth and Space (weather instruments)", "generator": "claude-workflow", "reviewed": false},
  {"id": "rainbow-over-field-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "rainbow sunlight refraction in raindrops", "grades": [4, 5, 6, 7], "terms": ["rainbow", "bahaghari", "balangaw", "sikat ng araw", "silaw sa adlaw", "patak ng ulan", "tulo sa ulan", "kulay", "kolor", "pitong kulay", "pito ka kulay", "refraction", "pagbaluktot ng liwanag", "sunlight and rain", "spectrum"], "fact": {"tl": "Ang bahaghari ay lumilitaw kapag ang puting sikat ng Araw ay dumadaan sa mga patak ng ulan na bumabaluktot at naghihiwalay ng liwanag sa iba't ibang kulay.", "en": "A rainbow appears when white sunlight passes through raindrops that bend and split the light into its colors.", "bis": "Ang balangaw motungha kon ang puti nga silaw sa Adlaw moagi sa mga tulo sa ulan nga moliko ug mobahin sa kahayag ngadto sa lainlaing kolor."}, "source": "NRC PS4 (light); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rainbow-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "rainbow seven colors arc after rain", "grades": [3, 4, 5], "terms": ["rainbow", "bahaghari", "balangaw", "pitong kulay", "pito ka kulay", "seven colors", "arko", "arch", "pagkatapos ng ulan", "human sa ulan", "pula kahel dilaw", "kulay", "kolor", "araw at ulan", "adlaw ug ulan", "colors of light"], "fact": {"tl": "Ang bahaghari ay isang arko ng mga kulay sa kalangitan na karaniwang lumilitaw pagkatapos ng ulan kapag sumisikat pa rin ang Araw.", "en": "A rainbow is an arc of colors in the sky that usually appears after rain while the Sun is still shining.", "bis": "Ang balangaw usa ka arko sa mga kolor sa langit nga kasagaran motungha human sa ulan samtang nagsidlak pa ang Adlaw."}, "source": "encyclopedia-stable consensus; DepEd G4 (light)", "generator": "claude-workflow", "reviewed": false},
  {"id": "raindrop-g4", "domain": "EARTH_SPACE", "topic": "raindrops and the water cycle", "grades": [3, 4, 5], "terms": ["patak ng ulan", "tulo", "ulan", "singaw", "ulap", "tubig", "tulo sa ulan", "tagaktak", "alisngaw", "panganod", "raindrop", "rain", "water vapor", "cloud", "condense", "water cycle"], "fact": {"tl": "Ang patak ng ulan ay nabubuo kapag ang singaw ng tubig sa ulap ay lumalamig at nagiging maliliit na patak na nagsasama-sama hanggang sa mabigat ang mga ito at bumagsak sa lupa.", "en": "A raindrop forms when water vapor in a cloud cools into tiny droplets that join together until they grow heavy enough to fall to the ground.", "bis": "Ang tulo sa ulan mahimo kung ang alisngaw sa tubig sa panganod mobugnaw ug mahimong gagmayng tulo nga magtapok hangtod nga mabug-at ug mahulog sa yuta."}, "source": "NRC ESS2.C water cycle; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rainwater-harvesting-barrel-g5", "domain": "EARTH_SPACE", "topic": "rainwater harvesting", "grades": [4, 5, 6], "terms": ["pag-impok ng tubig-ulan", "tubig-ulan", "imbak", "drum", "bubong", "kanal", "tipig tubig", "pagtigom sa tubig-ulan", "atop", "rainwater harvesting", "rain barrel", "roof", "store water", "conservation"], "fact": {"tl": "Sa rainwater harvesting, ang tubig-ulan na dumadaloy mula sa bubong ay iniimbak sa drum o tangke para magamit sa pagdidilig o paglilinis, na nakakatipid ng tubig.", "en": "In rainwater harvesting, rain that runs off a roof is collected in a barrel or tank so it can be used later for watering plants or cleaning, saving fresh water.", "bis": "Sa rainwater harvesting, ang tubig-ulan nga modagayday gikan sa atop tigumon sa drum o tangke aron magamit unya sa pagbisbis o paghugas, nga makadaginot og tubig."}, "source": "DepEd Science conservation; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "recycling-collection-g4", "domain": "MATTER", "topic": "recycling materials", "grades": [3, 4, 5], "terms": ["pagre-recycle", "muling paggamit", "basura", "bote", "plastik", "papel", "pag-uri-uri", "pag-recycle", "pagbalik-gamit", "botelya", "recycling", "recycle", "reuse", "bottle", "plastic", "sort waste"], "fact": {"tl": "Ang pagre-recycle ay ang pagkolekta at pag-uri-uri ng mga lumang bote, plastik, at papel upang gawing bagong produkto, na nakakabawas ng basura sa kalikasan.", "en": "Recycling means collecting and sorting old bottles, plastic, and paper so they can be made into new products, which reduces the waste that piles up in the environment.", "bis": "Ang pag-recycle mao ang pagtigom ug pag-uri-uri sa daang botelya, plastik, ug papel aron mahimong bag-ong produkto, nga makapakunhod sa basura sa kalikupan."}, "source": "DepEd Science environment; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "river-meander-bends-g6", "domain": "EARTH_SPACE", "topic": "river meanders", "grades": [5, 6, 7], "terms": ["likaw ng ilog", "kurba", "ilog", "agos", "pag-agnas", "pampang", "liko sa suba", "suba", "hugno", "river meander", "bend", "river", "erosion", "deposition", "riverbank"], "fact": {"tl": "Ang mga likaw o kurba ng ilog ay nabubuo dahil mas mabilis ang agos sa labas ng kurba na umaagnas sa pampang, habang ang mabagal na agos sa loob ay nag-iiwan ng buhangin.", "en": "A river develops winding bends called meanders because water flows faster on the outside of a curve and wears away the bank, while the slower water on the inside drops sand and mud.", "bis": "Ang mga liko o kurba sa suba mahimo tungod kay mas paspas ang agos sa gawas sa kurba nga mohugno sa pangpang, samtang ang hinay nga agos sa sulod magbilin og balas ug lapok."}, "source": "NRC ESS2.A surface processes; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "river-siltation-g6", "domain": "EARTH_SPACE", "topic": "river siltation", "grades": [5, 6, 7], "terms": ["pagkasilt ng ilog", "putik", "latak", "sedimento", "ilog", "pagkababaw", "pagkalbo ng gubat", "pagkalapok sa suba", "lapok", "suba", "siltation", "silt", "sediment", "river", "deforestation", "muddy"], "fact": {"tl": "Ang siltation ay ang pag-ipon ng putik at sedimentong dinadala ng tubig sa ilalim ng ilog, na kadalasang lumalala kapag kinakalbo ang gubat at naanod ang lupa.", "en": "Siltation is the build-up of mud and sediment that flowing water drops on a riverbed, which often gets worse when forests are cleared and bare soil washes in.", "bis": "Ang siltation mao ang pagtapok sa lapok ug sedimento nga dala sa tubig diha sa salog sa suba, nga kasagaran mograbe kung kalbohon ang lasang ug maanod ang yuta."}, "source": "NRC ESS2.A; DepEd Science environment", "generator": "claude-workflow", "reviewed": false},
  {"id": "river-system-watershed-g6", "domain": "EARTH_SPACE", "topic": "river systems and watersheds", "grades": [5, 6, 7], "terms": ["sistema ng ilog", "watershed", "sapa", "sanga ng ilog", "ilog", "dagat", "sistema sa suba", "sanga sa suba", "suba", "river system", "tributary", "stream", "drainage basin", "sea"], "fact": {"tl": "Ang isang sistema ng ilog ay binubuo ng pangunahing ilog at mga sanga o sapa nitong nag-uugnay, at ang lahat ng lupang umaagos ng tubig papunta rito ay tinatawag na watershed.", "en": "A river system is made of a main river plus all the smaller streams that feed into it, and the whole area of land that drains its water there is called a watershed.", "bis": "Ang sistema sa suba gilangkoban sa pangunang suba ug sa tanang gagmayng sapa nga modagayday niini, ug ang tibuok yuta nga modagayday og tubig ngadto niini gitawag og watershed."}, "source": "NRC ESS2.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "river-g4", "domain": "EARTH_SPACE", "topic": "what a river is", "grades": [3, 4, 5], "terms": ["ilog", "agos ng tubig", "tubig-tabang", "bukal", "dagat", "umaagos", "suba", "tubig-tab-ang", "tuburan", "river", "flowing water", "fresh water", "spring", "downhill", "sea"], "fact": {"tl": "Ang ilog ay isang likas na agos ng tubig-tabang na umaagos pababa mula sa mataas na lugar o bukal patungo sa lawa o dagat.", "en": "A river is a natural stream of fresh water that flows downhill from higher ground or a spring toward a lake or the sea.", "bis": "Ang suba usa ka natural nga agos sa tubig-tab-ang nga modagayday paubos gikan sa habog nga dapit o tuburan padulong sa lanaw o dagat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rock-sample-chunk-g5", "domain": "EARTH_SPACE", "topic": "rocks and minerals", "grades": [4, 5, 6], "terms": ["bato", "mineral", "matigas", "lupa", "buhangin", "kristal", "gahi", "yuta", "rock", "solid", "hard", "earth", "crystal"], "fact": {"tl": "Ang bato ay isang likas na matigas na materyales na binubuo ng isa o higit pang mineral, at ito ang bumubuo sa pinakamatigas na bahagi ng balat ng Daigdig.", "en": "A rock is a naturally hard solid made of one or more minerals, and rocks form the hard outer crust of the Earth.", "bis": "Ang bato usa ka natural nga gahi nga materyales nga gilangkoban sa usa o daghang mineral, ug kini ang naghimo sa gahi nga gawas nga panit sa Kalibutan."}, "source": "NRC ESS2.A Earth materials; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rocket-stage-separation-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "rocket stage separation", "grades": [6, 7, 8], "terms": ["rocket", "yugto", "pagbangga", "gasolina", "tangke", "kalawakan", "kabuwagan ng yugto", "kohete", "kawanangan", "rocket stage", "separation", "fuel", "lighter", "space", "thrust"], "fact": {"tl": "Ang malalaking rocket ay may mga yugto (stages) na isa-isang inihihiwalay matapos maubos ang gasolina ng bawat isa, upang gumaan ang rocket at mas mabilis itong makaabot sa kalawakan.", "en": "Large rockets are built in sections called stages, and each empty stage is dropped off after its fuel runs out so the rocket becomes lighter and can reach space faster.", "bis": "Ang dagkong rocket adunay mga bahin nga gitawag og stages, ug ang matag bahin ihulog human maubos ang gasolina niini aron mogaan ang rocket ug mas paspas makaabot sa kawanangan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rockfall-mountain-road-g6", "domain": "EARTH_SPACE", "topic": "rockfalls and landslides", "grades": [5, 6, 7], "terms": ["pagguho ng bato", "rockfall", "bundok", "gravity", "ulan", "lindol", "kalsada", "pagkahulog sa bato", "bukid", "grabidad", "linog", "rock", "mountain", "gravity", "rain", "earthquake", "road"], "fact": {"tl": "Ang rockfall ay nangyayari kapag ang mga bato sa gilid ng bundok ay kumakalas at bumabagsak dahil sa hila ng grabidad, na kadalasang pinalalala ng matinding ulan o lindol.", "en": "A rockfall happens when rocks break loose from a steep mountainside and tumble down because gravity pulls them, often triggered by heavy rain or an earthquake.", "bis": "Ang rockfall mahitabo kung ang mga bato sa kilid sa bukid mobuhi ug mahulog tungod sa grabidad, nga kasagaran mograbe sa kusog nga ulan o linog."}, "source": "NRC ESS2.A; DepEd Science hazards", "generator": "claude-workflow", "reviewed": false},
  {"id": "rocky-sea-stack-g6", "domain": "EARTH_SPACE", "topic": "sea stacks and coastal erosion", "grades": [5, 6, 7], "terms": ["sea stack", "bato sa dagat", "alon", "pag-agnas", "baybayin", "tangwa", "balod", "hugno", "baybayon", "pangpang", "wave", "erosion", "coast", "cliff", "pillar"], "fact": {"tl": "Ang sea stack ay isang nakatayong haligi ng bato sa dalampasigan na naiwan matapos unti-unting agnasin ng mga alon ang mahihinang bahagi ng dating tangwa.", "en": "A sea stack is a tall pillar of rock standing in the sea, left behind after waves slowly wore away the weaker rock of a cliff around it.", "bis": "Ang sea stack usa ka taas nga haligi sa bato nga nagbarog sa dagat, nga nahibilin human hinay-hinayng gihugno sa mga balod ang huyang nga bahin sa kanhing pangpang."}, "source": "NRC ESS2.A coastal erosion; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rolling-hills-grassland-g4", "domain": "EARTH_SPACE", "topic": "grasslands and hills", "grades": [3, 4, 5], "terms": ["damuhan", "burol", "kabundukan", "damo", "lupa", "kapatagan", "kasagbutan", "bungtod", "sagbot", "yuta", "grassland", "hill", "grass", "land", "rolling hills", "plain"], "fact": {"tl": "Ang damuhan o grassland ay malawak na lupang natatakpan ng damo na may kaunting punong-kahoy, at karaniwan itong matatagpuan sa mga maburol na lugar na tigang sa ulan.", "en": "A grassland is a wide area of land covered mostly by grass with few trees, often found on rolling hills where there is not enough rain for thick forest.", "bis": "Ang kasagbutan o grassland usa ka lapad nga yuta nga natabonan sa sagbot nga gamay ra og kahoy, kasagaran makita sa bungtorong dapit nga kulang sa ulan alang sa baga nga lasang."}, "source": "AAAS Benchmarks ecosystems; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sagada-hanging-coffins-g6", "domain": "EARTH_SPACE", "topic": "limestone cliffs of Sagada", "grades": [5, 6, 7], "terms": ["Sagada", "hanging coffins", "bangin", "limestone", "apog", "kweba", "Cordillera", "pangpang", "langob", "cliff", "cave", "Mountain Province", "sea creatures"], "fact": {"tl": "Ang mga bangin sa Sagada sa Mountain Province ay gawa sa limestone (batong-apog), isang batong nabubuo mula sa naipong labi ng mga sinaunang hayop sa dagat at madaling kayariang maging kweba.", "en": "The cliffs of Sagada in Mountain Province are made of limestone, a rock formed from the piled-up remains of ancient sea creatures, which water easily carves into caves.", "bis": "Ang mga pangpang sa Sagada sa Mountain Province hinimo sa limestone (apog nga bato), usa ka bato nga naporma gikan sa natapok nga salin sa karaang mga mananap sa dagat, nga sayon kuliton sa tubig nga langob."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "school-globe-stand-g4", "domain": "EARTH_SPACE", "topic": "the globe as a model of Earth", "grades": [3, 4, 5], "terms": ["globo", "modelo ng mundo", "Daigdig", "bilog", "mapa", "ehe", "modelo sa kalibutan", "lingin", "axis", "globe", "model", "Earth", "round", "sphere"], "fact": {"tl": "Ang globo ay isang maliit na bilog na modelo ng Daigdig na nagpapakita kung paano hugis-bola ang ating planeta at saan matatagpuan ang mga lupain at karagatan.", "en": "A globe is a small round model of the Earth that shows how our planet is shaped like a ball and where the land and oceans are located.", "bis": "Ang globo usa ka gamayng lingin nga modelo sa Kalibutan nga nagpakita kung giunsa ang atong planeta nahimong daw bola ug asa makita ang mga yuta ug kadagatan."}, "source": "DepEd Science Earth; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "seasons-tilt-globe-lamp-g6", "domain": "EARTH_SPACE", "topic": "why seasons happen", "grades": [5, 6, 7], "terms": ["panahon", "tagsibol", "tag-init", "pagkakahilig", "ehe", "Araw", "pag-ikot", "kahilig sa axis", "Adlaw", "seasons", "axis tilt", "Sun", "orbit", "sunlight angle"], "fact": {"tl": "Nagkakaroon ng iba't ibang panahon dahil nakahilig ang ehe ng Daigdig, kaya't sa paglibot nito sa Araw ay nag-iiba ang dami at anggulo ng sikat ng araw sa bawat bahagi ng planeta.", "en": "Seasons happen because the Earth's axis is tilted, so as the planet orbits the Sun, different parts receive sunlight at changing angles and amounts through the year.", "bis": "Adunay nagkalainlaing panahon tungod kay nahilig ang axis sa Kalibutan, mao nga samtang molibot kini sa Adlaw, ang nagkalainlaing bahin makadawat og kahayag sa Adlaw sa nagkalainlaing anggulo ug gidaghanon."}, "source": "NRC ESS1.B Earth-Sun system; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "seismic-waves-g7", "domain": "EARTH_SPACE", "topic": "seismic waves", "grades": [6, 7, 8], "terms": ["seismic waves", "alon ng lindol", "lindol", "yanig", "lupa", "enerhiya", "balod sa linog", "linog", "uyog", "yuta", "seismic wave", "earthquake", "vibration", "ground", "energy"], "fact": {"tl": "Ang seismic waves ay mga alon ng enerhiya na kumakalat sa loob at ibabaw ng Daigdig tuwing may lindol, at ang pagyanig na nararamdaman natin ay dulot ng mga alon na ito.", "en": "Seismic waves are waves of energy that spread through and across the Earth during an earthquake, and the shaking we feel is caused by these waves.", "bis": "Ang seismic waves mao ang mga balod sa enerhiya nga mokaylap sa sulod ug ibabaw sa Kalibutan kon adunay linog, ug ang pag-uyog nga atong mabati gumikan niini nga mga balod."}, "source": "NRC ESS2.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "seismograph-g7", "domain": "EARTH_SPACE", "topic": "seismographs", "grades": [6, 7, 8], "terms": ["seismograph", "panukat ng lindol", "lindol", "yanig", "PHIVOLCS", "rekord", "sukdanan sa linog", "linog", "earthquake", "measure", "record", "magnitude", "instrument"], "fact": {"tl": "Ang seismograph ay isang instrumentong sumusukat at nagtatala ng lakas at galaw ng pagyanig ng lupa tuwing may lindol, at ginagamit ito ng PHIVOLCS sa Pilipinas.", "en": "A seismograph is an instrument that measures and records the strength and motion of ground shaking during an earthquake, used by PHIVOLCS in the Philippines.", "bis": "Ang seismograph usa ka instrumento nga mosukod ug morekord sa kusog ug lihok sa pag-uyog sa yuta panahon sa linog, nga gigamit sa PHIVOLCS sa Pilipinas."}, "source": "DepEd Science earthquakes; PHIVOLCS", "generator": "claude-workflow", "reviewed": false},
  {"id": "shadow-clock-day-tracking-g5", "domain": "EARTH_SPACE", "topic": "shadows and the Sun's daily path", "grades": [4, 5, 6], "terms": ["anino", "orasan ng anino", "sundial", "Araw", "umaga", "tanghali", "hapon", "Adlaw", "buntag", "udto", "shadow", "Sun", "morning", "noon", "shortest shadow"], "fact": {"tl": "Nagbabago ang haba at direksyon ng anino sa buong araw dahil gumagalaw ang posisyon ng Araw sa langit, at pinakamaikli ang anino tuwing tanghali kapag pinakamataas ang Araw.", "en": "A shadow changes its length and direction through the day because the Sun's position in the sky moves, and the shadow is shortest at noon when the Sun is highest.", "bis": "Mausab ang gitas-on ug direksyon sa anino sa tibuok adlaw tungod kay molihok ang posisyon sa Adlaw sa langit, ug pinakamubo ang anino sa udto kung pinakahabog ang Adlaw."}, "source": "NRC ESS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sinkhole-collapse-g6", "domain": "EARTH_SPACE", "topic": "sinkholes", "grades": [5, 6, 7], "terms": ["sinkhole", "paglubog ng lupa", "limestone", "apog", "tubig sa ilalim", "butas", "pagkahugno sa yuta", "lungag", "collapse", "underground water", "cave", "hole"], "fact": {"tl": "Ang sinkhole ay nabubuo kapag ang tubig sa ilalim ng lupa ay unti-unting tinutunaw ang batong-apog hanggang sa magkalukob ang ibabaw at biglang bumagsak na parang malaking butas.", "en": "A sinkhole forms when underground water slowly dissolves limestone rock until the surface above has no support and suddenly collapses into a large hole.", "bis": "Ang sinkhole maporma kung ang tubig sa ilawom sa yuta hinay-hinayng motunaw sa apog nga bato hangtod nga ang ibabaw walay support ug kalit nga mahugno nga daw dakong lungag."}, "source": "NRC ESS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "smog-over-city-g6", "domain": "MATTER", "topic": "air pollution and smog", "grades": [5, 6, 7], "terms": ["usok", "polusyon sa hangin", "smog", "sasakyan", "pabrika", "maruming hangin", "aso", "sakyanan", "air pollution", "smoke", "vehicle", "factory", "haze"], "fact": {"tl": "Ang smog ay maruming hamog na binubuo ng usok at mga gas mula sa mga sasakyan at pabrika, na nakakasama sa baga at nagpapahirap sa paghinga ng mga tao.", "en": "Smog is a dirty haze made of smoke and gases from vehicles and factories, and it harms people's lungs and makes breathing harder.", "bis": "Ang smog usa ka hugaw nga gabon nga hinimo sa aso ug mga gas gikan sa mga sakyanan ug pabrika, nga makadaot sa baga ug maglisod sa pagginhawa sa mga tawo."}, "source": "DepEd Science environment; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "snow-cap-mountain-rare-g6", "domain": "EARTH_SPACE", "topic": "why high mountains can be cold and snowy", "grades": [5, 6, 7], "terms": ["niyebe", "bundok", "taas", "lamig", "yelo", "tuktok", "bukid", "kabugnaw", "snow", "mountain", "altitude", "cold", "ice", "summit", "elevation"], "fact": {"tl": "Lumalamig ang hangin habang tumataas ang lugar, kaya ang mga napakataas na bundok ay maaaring matakpan ng niyebe o yelo sa tuktok kahit nasa mainit na lugar ng mundo.", "en": "Air gets colder as you go higher, so very tall mountains can have snow or ice on their peaks even in warm parts of the world.", "bis": "Mobugnaw ang hangin samtang mosaka ang dapit, mao nga ang taas kaayo nga mga bukid mahimong tabonan og niyebe o yelo sa tumoy bisan sa init nga bahin sa kalibutan."}, "source": "NRC ESS2.D weather/climate; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "soil-clump-sample-g4", "domain": "EARTH_SPACE", "topic": "what soil is made of", "grades": [3, 4, 5], "terms": ["lupa", "soil", "buhangin", "putik", "humus", "bulok na dahon", "mineral", "yuta", "balas", "lapok", "dunot nga dahon", "sand", "clay", "rotted leaves", "minerals"], "fact": {"tl": "Ang lupa ay binubuo ng durog na bato, buhangin, putik, tubig, hangin, at humus na galing sa mga bulok na halaman at hayop na nagbibigay ng sustansya sa pananim.", "en": "Soil is made of tiny bits of broken rock, sand, clay, water, air, and humus from rotted plants and animals that gives nutrients to growing plants.", "bis": "Ang yuta gilangkoban sa gagmayng bato, balas, lapok, tubig, hangin, ug humus gikan sa nadunot nga mga tanom ug mananap nga naghatag og sustansiya sa tanom."}, "source": "NRC ESS2.A; AAAS Benchmarks; DepEd Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "soil-formation-g6", "domain": "EARTH_SPACE", "topic": "how soil forms", "grades": [5, 6, 7], "terms": ["pagkakabuo ng lupa", "pagdurog ng bato", "weathering", "panahon", "humus", "lupa", "pagporma sa yuta", "pagdugmok sa bato", "yuta", "broken rock", "time", "decompose"], "fact": {"tl": "Ang lupa ay nabubuo sa napakahabang panahon habang dinudurog ng init, lamig, tubig, at ugat ang mga bato, at hinahaluan ito ng bulok na halaman at hayop.", "en": "Soil forms over very long periods as heat, cold, water, and roots break rocks into tiny pieces, which then mix with rotted plants and animals.", "bis": "Ang yuta maporma sa taas kaayong panahon samtang gidugmok sa init, bugnaw, tubig, ug gamot ang mga bato, ug masagol kini sa nadunot nga tanom ug mananap."}, "source": "NRC ESS2.A; AAAS Benchmarks", "generator": "claude-workflow", "reviewed": false},
  {"id": "soil-layers-profile-g6", "domain": "EARTH_SPACE", "topic": "soil layers (horizons)", "grades": [5, 6, 7], "terms": ["mga patong ng lupa", "soil layers", "ibabaw na lupa", "topsoil", "subsoil", "batong-magulang", "humus", "patong sa yuta", "ibabaw nga yuta", "horizon", "bedrock", "profile"], "fact": {"tl": "Kapag hinukay ang lupa, makikita ang magkakapatong na layer: ang madilim na topsoil na mayaman sa humus sa itaas, at ang mas magaspang na subsoil at bato sa ilalim.", "en": "If you dig into the ground you see soil in layers: a dark, humus-rich topsoil on top, with coarser subsoil and rock beneath it.", "bis": "Kung kalutkuton ang yuta, makita ang nagtapok nga mga sapaw: ang itom nga topsoil nga dato sa humus sa ibabaw, ug ang mas labukon nga subsoil ug bato sa ubos."}, "source": "NRC ESS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "soil-sandy-g5", "domain": "EARTH_SPACE", "topic": "sandy soil", "grades": [4, 5, 6], "terms": ["mabuhanging lupa", "sandy soil", "buhangin", "tubig", "patak", "tuyo", "lupa", "balason nga yuta", "balas", "uga", "sand", "drains fast", "dry", "loose", "particles"], "fact": {"tl": "Ang mabuhanging lupa ay may malalaking butil kaya mabilis itong tinatagusan ng tubig at madaling matuyo, na nagiging mahirap para sa ilang halaman na nangangailangan ng basang lupa.", "en": "Sandy soil has large grains, so water drains through it quickly and it dries out fast, which makes it hard for plants that need moist soil.", "bis": "Ang balason nga yuta adunay dagkong lugas mao nga paspas molusot ang tubig ug dali kini mauga, nga maglisod sa pipila ka tanom nga nagkinahanglan og umog nga yuta."}, "source": "AAAS Benchmarks; DepEd Science soil", "generator": "claude-workflow", "reviewed": false},
  {"id": "soil-water-retention-test-g5", "domain": "EARTH_SPACE", "topic": "soil and water retention", "grades": [4, 5, 6], "terms": ["pagtatago ng tubig", "lupa", "putik", "buhangin", "pagsubok", "tagas", "pagpugong sa tubig", "yuta", "lapok", "balas", "water retention", "clay", "sand", "drainage", "holds water"], "fact": {"tl": "Sa pagsubok ng lupa, makikitang ang lupang maraming putik ay nagtatago ng mas maraming tubig habang ang mabuhanging lupa ay mabilis tagusan, kaya iba-iba ang dami ng tubig na hinahawakan ng bawat uri.", "en": "In a soil test you can see that clay-rich soil holds more water while sandy soil drains quickly, so different soils keep different amounts of water for plants.", "bis": "Sa pagsulay sa yuta, makita nga ang yuta nga daghan og lapok mas daghang tubig ang gipugngan samtang ang balason nga yuta paspas molusot, mao nga lainlain ang gidaghanon sa tubig nga gihuptan sa matag matang."}, "source": "DepEd Science soil investigation; AAAS Benchmarks", "generator": "claude-workflow", "reviewed": false},
  {"id": "solar-dryer-produce-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "solar drying of food", "grades": [5, 6, 7], "terms": ["solar dryer", "patuyo gamit ang araw", "enerhiya ng araw", "init", "pagpapatuyo ng pagkain", "singaw", "init sa adlaw", "pagpauga sa pagkaon", "alisngaw", "Sun energy", "heat", "drying food", "evaporation", "preserve"], "fact": {"tl": "Ang solar dryer ay gumagamit ng init ng araw upang patuyuin ang mga prutas, isda, o palay sa pamamagitan ng pagpapasingaw ng tubig sa loob nito, na nakakatulong na hindi mabilis mapanis ang pagkain.", "en": "A solar dryer uses the Sun's heat to dry fruits, fish, or rice by evaporating the water inside them, which helps the food keep longer without spoiling.", "bis": "Ang solar dryer mogamit sa init sa adlaw aron paugahon ang mga prutas, isda, o humay pinaagi sa pagpaalisngaw sa tubig sa sulod niini, nga makatabang nga dili dali madunot ang pagkaon."}, "source": "DepEd Science energy use; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "star-g5", "domain": "EARTH_SPACE", "topic": "what stars are", "grades": [4, 5, 6], "terms": ["bituin", "tala", "bitoon", "star", "stars", "araw", "adlaw", "sun is a star", "init", "gas", "nagliliwanag", "nagsiga", "kalangitan"], "fact": {"tl": "Ang bituin ay isang napakalaking bola ng mainit na gas na gumagawa ng sarili nitong liwanag at init, at ang ating Araw ay isa ring bituin na malapit lang sa atin.", "en": "A star is a huge ball of hot gas that makes its own light and heat, and our own Sun is a star that just happens to be very close to us.", "bis": "Ang bitoon usa ka dako kaayo nga bola sa init nga gas nga naghimo sa kaugalingon niini nga kahayag ug kainit, ug ang atong Adlaw usa usab ka bitoon nga duol ra kaayo kanato."}, "source": "encyclopedia-stable consensus; NRC ESS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "star-distance-g6", "domain": "EARTH_SPACE", "topic": "stars look small because they are far", "grades": [5, 6, 7], "terms": ["bituin", "tala", "bitoon", "star", "layo", "halayo", "malayo", "distance", "maliit ang itsura", "twinkle", "kumikislap", "kumukurap", "gabi"], "fact": {"tl": "Mukhang maliliit at parang tuldok ang mga bituin sa gabi dahil sobrang layo nila sa Earth, kahit na ang marami sa kanila ay mas malalaki pa kaysa sa ating Araw.", "en": "Stars look like tiny points of light at night only because they are extremely far from Earth, even though many of them are actually bigger than our Sun.", "bis": "Ang mga bitoon morag gagmay nga tulbok sa kahayag panahon sa gabii tungod kay layo kaayo sila sa Yuta, bisan tuod daghan kanila mas dagko pa kay sa atong Adlaw."}, "source": "encyclopedia-stable consensus; NRC ESS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "storm-surge-wall-of-water-g7", "domain": "EARTH_SPACE", "topic": "storm surge", "grades": [6, 7, 8], "terms": ["storm surge", "daluyong ng bagyo", "pagbaha sa dagat", "humahampas na tubig", "alon", "balod", "baha", "bagyo", "bagyong", "unos", "typhoon", "dagat", "lumalaki ang tubig dagat", "Yolanda", "Haiyan"], "fact": {"tl": "Ang storm surge ay ang biglang pagtaas ng tubig-dagat na itinutulak ng malakas na hangin ng bagyo papunta sa baybayin, at ito ang madalas na pinakanakamamatay na bahagi ng isang malakas na bagyo.", "en": "A storm surge is a sudden rise of seawater pushed onto the coast by a typhoon's strong winds, and it is often the deadliest part of a powerful storm.", "bis": "Ang storm surge mao ang kalit nga pagtaas sa tubig-dagat nga giduso sa kusog nga hangin sa bagyo padulong sa baybayon, ug kini sagad mao ang labing makamatay nga bahin sa usa ka kusog nga bagyo."}, "source": "PAGASA; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "storm-warning-flags-scene-g6", "domain": "EARTH_SPACE", "topic": "typhoon warning signals", "grades": [5, 6, 7], "terms": ["storm warning", "babala sa bagyo", "signal", "Signal No. 1", "tropical cyclone warning", "PAGASA", "pasidaan", "pahimangno", "bagyo", "typhoon", "lakas ng hangin", "hangin", "hangin kusog"], "fact": {"tl": "Nagbibigay ang PAGASA ng mga babala o 'signal' bago at habang may bagyo upang malaman ng mga tao kung gaano kalakas ang darating na hangin at kung kailan dapat mag-ingat.", "en": "PAGASA issues storm warning signals before and during a typhoon so people can know how strong the coming winds will be and when to take cover.", "bis": "Ang PAGASA naghatag ug mga pasidaan o 'signal' sa dili pa ug samtang naa pay bagyo aron mahibaw-an sa mga tawo kung unsa ka kusog ang umaabot nga hangin ug kanus-a kinahanglan mag-amping."}, "source": "PAGASA tropical cyclone warning system", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-angle-latitude-g8", "domain": "EARTH_SPACE", "topic": "sun angle and latitude", "grades": [7, 8, 9], "terms": ["sun angle", "anggulo ng araw", "latitude", "latitud", "ekwador", "equator", "tropiko", "init", "kainit", "diretso ang sikat", "direct sunlight", "tilted Earth", "Pilipinas malapit sa ekwador", "sinag"], "fact": {"tl": "Mas mainit ang mga lugar na malapit sa ekwador tulad ng Pilipinas dahil mas diretso o patindig ang pagtama ng sinag ng araw doon, samantalang pahilis ang sikat nito sa malayong mga lugar na malapit sa poste.", "en": "Places near the equator like the Philippines are hotter because the Sun's rays strike them more directly, while regions near the poles get the same sunlight spread out at a slanted angle.", "bis": "Ang mga dapit duol sa ekwador sama sa Pilipinas mas init tungod kay mas direkta ang pagtama sa silaw sa adlaw didto, samtang hilis ang pagsidlak niini sa mga dapit nga duol sa poste."}, "source": "NRC ESS1.B; AAAS Benchmarks", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-earth-moon-model-g5", "domain": "EARTH_SPACE", "topic": "sun earth moon system", "grades": [4, 5, 6], "terms": ["Araw", "Adlaw", "Lupa", "Yuta", "Earth", "Buwan", "Bulan", "Moon", "umiikot", "nagtuyok", "orbit", "umiikot sa araw", "umiikot ang buwan sa earth", "sistema", "model"], "fact": {"tl": "Ang Earth ay umiikot sa Araw nang isang beses sa loob ng isang taon, habang ang Buwan naman ay umiikot sa Earth, kaya magkakaugnay ang galaw ng tatlong ito.", "en": "Earth orbits the Sun once a year while the Moon orbits Earth, so the Sun, Earth, and Moon all move together in a connected system.", "bis": "Ang Yuta nagtuyok libot sa Adlaw kausa sa usa ka tuig, samtang ang Bulan nagtuyok libot sa Yuta, mao nga magkadugtong ang lihok niining tulo."}, "source": "NRC ESS1.B; DepEd Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-halo-ring-g7", "domain": "EARTH_SPACE", "topic": "sun halo", "grades": [6, 7, 8], "terms": ["sun halo", "singsing sa araw", "bilog na liwanag", "halo", "ulap", "cirrus", "ice crystals", "yelo", "kristal ng yelo", "nababiyak ang liwanag", "refraction", "singsing", "alibukay sa adlaw"], "fact": {"tl": "Ang singsing na liwanag na minsang nakikita sa paligid ng araw, na tinatawag na halo, ay nabubuo kapag ang sikat ng araw ay dumadaan at nababaluktot sa mga maliliit na kristal ng yelo sa matataas na manipis na ulap.", "en": "The ring of light sometimes seen around the Sun, called a halo, forms when sunlight passes through and bends inside tiny ice crystals in high, thin clouds.", "bis": "Ang singsing nga kahayag nga usahay makita libot sa adlaw, nga gitawag ug halo, maporma kung ang silaw sa adlaw moagi ug mobaliko sa gagmay nga mga kristal sa yelo sa taas ug nipis nga mga panganod."}, "source": "encyclopedia-stable consensus (atmospheric optics)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-path-across-sky-g4", "domain": "EARTH_SPACE", "topic": "apparent path of the sun", "grades": [3, 4, 5], "terms": ["daan ng araw", "agi sa adlaw", "sun path", "sumisikat sa silangan", "lumulubog sa kanluran", "east", "west", "silangan", "kasadpan", "subangan", "umaga", "tanghali", "hapon", "pag-ikot ng earth", "tila gumagalaw ang araw"], "fact": {"tl": "Mukhang sumisikat ang araw sa silangan tuwing umaga, umaakyat sa tanghali, at lumulubog sa kanluran sa hapon, pero ito ay dahil sa pag-ikot ng Earth, hindi dahil gumagalaw talaga ang araw.", "en": "The Sun appears to rise in the east each morning, climb high at noon, and set in the west in the afternoon, but this is really because Earth spins, not because the Sun moves.", "bis": "Ang adlaw morag mosubang sa sidlakan matag buntag, mosaka sa udto, ug mosalop sa kasadpan sa hapon, apan kini tungod sa pagtuyok sa Yuta, dili tungod kay naglihok gayod ang adlaw."}, "source": "NRC ESS1.B; DepEd Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "sundial-stick-shadow-g4", "domain": "EARTH_SPACE", "topic": "shadow tells time", "grades": [3, 4, 5], "terms": ["sundial", "orasan sa anino", "anino", "anino ng patpat", "landong", "shadow", "stick", "patpat", "oras", "nagbabago ang anino", "gumagalaw ang anino", "araw", "eksperimento", "sukat ng oras"], "fact": {"tl": "Sa eksperimentong sundial, itinutusok ang isang patpat sa lupa at habang gumagalaw ang araw sa langit, gumagalaw at nagbabago ang haba ng anino nito, na nagpapakita ng pagdaan ng oras.", "en": "In a stick-shadow sundial experiment, you plant a stick in the ground, and as the Sun moves across the sky the stick's shadow moves and changes length, showing the passing of time.", "bis": "Sa eksperimento nga sundial, motusok ka ug patpat sa yuta, ug samtang naglihok ang adlaw sa langit, ang landong sa patpat molihok ug mausab ang gitas-on, nga nagpakita sa pag-agi sa oras."}, "source": "encyclopedia-stable consensus; DepEd Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "sundial-g6", "domain": "EARTH_SPACE", "topic": "sundial as a clock", "grades": [5, 6, 7], "terms": ["sundial", "orasan ng anino", "relo sa adlaw", "anino", "landong", "lumang orasan", "ancient clock", "oras", "gnomon", "sikat ng araw", "pagbabasa ng oras", "una nga orasan"], "fact": {"tl": "Ang sundial ay isa sa pinakaunang uri ng orasan na ginamit ng mga tao, kung saan binabasa ang oras batay sa kung saan tumama ang anino ng isang patayong bahagi nito sa minarkahang plato.", "en": "A sundial is one of the earliest kinds of clock people used, telling the time by where the shadow of an upright part falls on a marked plate.", "bis": "Ang sundial usa sa labing una nga matang sa orasan nga gigamit sa mga tawo, diin mabasa ang oras pinasikad sa kung asa motama ang landong sa usa ka tul-id nga bahin niini sa minarkahan nga plato."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "telescope-observatory-g6", "domain": "EARTH_SPACE", "topic": "observatory and telescopes", "grades": [5, 6, 7], "terms": ["observatory", "obserbatoryo", "telescope", "teleskopyo", "pagmamasid sa langit", "pagtan-aw sa kalangitan", "bituin", "bitoon", "planeta", "astronomer", "astronomo", "malaking teleskopyo", "dome", "pag-aaral ng kalawakan"], "fact": {"tl": "Ang observatory ay isang gusaling may malalaking teleskopyo na ginagamit ng mga astronomo upang pag-aralan ang mga bituin, planeta, at iba pang bagay sa kalawakan nang mas malinaw.", "en": "An observatory is a building with large telescopes that astronomers use to study stars, planets, and other objects in space more clearly.", "bis": "Ang observatory usa ka building nga adunay dagkong teleskopyo nga gigamit sa mga astronomo aron tun-an ang mga bitoon, planeta, ug uban pang butang sa kawanangan nga mas klaro."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "telescope-on-tripod-g5", "domain": "EARTH_SPACE", "topic": "how a telescope works", "grades": [4, 5, 6], "terms": ["telescope", "teleskopyo", "tripod", "lente", "salamin", "pagtingin sa malayo", "magnify", "lumalapit ang itsura", "nagpapalaki", "bituin", "buwan", "bulan", "planeta", "pagtan-aw sa langit"], "fact": {"tl": "Ang teleskopyo ay gumagamit ng mga lente o salamin upang tipunin ang liwanag mula sa malalayong bagay, kaya mukhang mas malaki at mas malapit ang Buwan at mga bituin kapag tinitingnan dito.", "en": "A telescope uses lenses or mirrors to gather light from faraway objects, making the Moon and stars look bigger and closer when you look through it.", "bis": "Ang teleskopyo naggamit ug mga lente o salamin aron tigumon ang kahayag gikan sa layo nga mga butang, mao nga ang Bulan ug mga bitoon morag mas dako ug mas duol kung imong tan-awon niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "thunderhead-rain-shaft-g6", "domain": "EARTH_SPACE", "topic": "cumulonimbus cloud and rain", "grades": [5, 6, 7], "terms": ["thunderhead", "cumulonimbus", "ulap ng kulog", "panganod sa dahunog", "malaking ulap", "ulan", "rain shaft", "buhos ng ulan", "kidlat", "kilat", "kulog", "dahunog", "bagyong ulan", "matangkad na ulap"], "fact": {"tl": "Ang malaki at matangkad na ulap na tinatawag na thunderhead o cumulonimbus ang nagdadala ng malakas na ulan, kidlat, at kulog, at kadalasang nakikita ang buhos ng ulan na parang kurtinang bumababa mula rito.", "en": "The tall, towering cloud called a thunderhead or cumulonimbus brings heavy rain, lightning, and thunder, and you can often see a rain shaft falling like a curtain beneath it.", "bis": "Ang dako ug tag-as nga panganod nga gitawag ug thunderhead o cumulonimbus mao ang nagdala sa kusog nga ulan, kilat, ug dahunog, ug sagad makita ang pagbu-bu sa ulan nga morag kurtina nga nanaog gikan niini."}, "source": "encyclopedia-stable consensus; PAGASA", "generator": "claude-workflow", "reviewed": false},
  {"id": "thunderstorm-formation-g7", "domain": "EARTH_SPACE", "topic": "how thunderstorms form", "grades": [6, 7, 8], "terms": ["thunderstorm", "pagkidlat at pagkulog", "bagyong may kidlat", "kidlat", "kilat", "kulog", "dahunog", "init na hangin", "umaakyat na mainit na hangin", "rising warm air", "ulap", "panganod", "ulan", "singaw ng tubig", "kondensasyon"], "fact": {"tl": "Nabubuo ang thunderstorm kapag mabilis na umaakyat ang mainit at basang hangin, lumalamig at namumuo ito sa matataas na ulap, hanggang sa magdulot ng malakas na ulan, kidlat, at kulog.", "en": "A thunderstorm forms when warm, moist air rises quickly, cools and builds into tall clouds, until it produces heavy rain, lightning, and thunder.", "bis": "Ang thunderstorm maporma kung ang init ug basa nga hangin paspas nga mosaka, mobugnaw ug mausa sa tag-as nga mga panganod, hangtod nga makahatag ug kusog nga ulan, kilat, ug dahunog."}, "source": "encyclopedia-stable consensus; NRC ESS2.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "tides-spring-neap-g8", "domain": "EARTH_SPACE", "topic": "spring and neap tides", "grades": [7, 8, 9], "terms": ["tides", "taog", "kati", "pagtaas ng tubig dagat", "pagbaba ng tubig dagat", "spring tide", "neap tide", "high tide", "low tide", "buwan", "bulan", "araw", "gravity", "hila ng buwan", "alon", "pagdagsa", "taob"], "fact": {"tl": "Pinakamataas at pinakamababa ang taog (tides) tuwing spring tide kapag nakahanay ang Araw, Earth, at Buwan, samantalang mas mababa ang pagkakaiba ng taog tuwing neap tide kapag nasa kanto ang Araw at Buwan.", "en": "Tides are highest and lowest during spring tides, when the Sun, Earth, and Moon line up, while the difference is smaller during neap tides, when the Sun and Moon pull at right angles.", "bis": "Ang taob ug hunas labing taas ug labing ubos panahon sa spring tide kung naghan-ay ang Adlaw, Yuta, ug Bulan, samtang mas gamay ang kalainan panahon sa neap tide kung ang Adlaw ug Bulan magbira sa eskina nga anggulo."}, "source": "NRC ESS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tsunami-formation-g7", "domain": "EARTH_SPACE", "topic": "how tsunamis form", "grades": [6, 7, 8], "terms": ["tsunami", "daluyong", "higanteng alon", "dako nga balod", "lindol", "linog", "earthquake", "ilalim ng dagat", "underwater earthquake", "pagputok ng bulkan", "pananaog ng tubig", "PHIVOLCS", "babala", "alon sa dagat"], "fact": {"tl": "Ang tsunami ay isang serye ng napakalalaking alon na karaniwang nabubuo kapag may malakas na lindol sa ilalim ng dagat na biglang nagtulak sa malaking dami ng tubig.", "en": "A tsunami is a series of very large waves usually formed when a strong earthquake under the sea suddenly pushes a huge amount of water.", "bis": "Ang tsunami usa ka serye sa dagko kaayo nga mga balod nga sagad maporma kung adunay kusog nga linog ilalom sa dagat nga kalit nga miduso sa daghan kaayo nga tubig."}, "source": "PHIVOLCS; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "typhoon-eye-cross-section-g7", "domain": "EARTH_SPACE", "topic": "eye of a typhoon", "grades": [6, 7, 8], "terms": ["typhoon eye", "mata ng bagyo", "mata sa bagyo", "eyewall", "tahimik na gitna", "kalma", "calm center", "bagyo", "unos", "umiikot na ulap", "spiral", "pinakamalakas na hangin", "ulan", "PAGASA"], "fact": {"tl": "Sa gitna ng isang malakas na bagyo ay may tahimik na bahaging tinatawag na mata, kung saan kalma ang panahon, pero sa paligid nito ay naroon ang eyewall na may pinakamalakas na hangin at ulan.", "en": "At the center of a strong typhoon is a calm region called the eye, where the weather is quiet, but surrounding it is the eyewall with the strongest winds and rain.", "bis": "Sa tunga sa usa ka kusog nga bagyo adunay malinawon nga bahin nga gitawag ug mata, diin kalma ang panahon, apan sa palibot niini mao ang eyewall nga adunay labing kusog nga hangin ug ulan."}, "source": "PAGASA; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "typhoon-preparation-home-scene-g6", "domain": "EARTH_SPACE", "topic": "typhoon preparedness", "grades": [5, 6, 7], "terms": ["typhoon preparation", "paghahanda sa bagyo", "pangandam sa bagyo", "emergency kit", "tubig", "pagkain", "flashlight", "baterya", "bagyo", "unos", "lumikas", "evacuate", "ligtas", "kaligtasan", "PAGASA", "babala"], "fact": {"tl": "Bago dumating ang bagyo, mahalagang maghanda ang isang pamilya ng malinis na tubig, pagkaing hindi madaling masira, flashlight, at gamot, at sundin ang babala ng PAGASA upang manatiling ligtas.", "en": "Before a typhoon arrives, a family should prepare clean water, food that does not spoil quickly, a flashlight, and medicine, and follow PAGASA warnings to stay safe.", "bis": "Sa dili pa moabot ang bagyo, importante nga mangandam ang usa ka pamilya ug limpyo nga tubig, pagkaon nga dili daling madunot, flashlight, ug tambal, ug sundon ang pasidaan sa PAGASA aron magpabiling luwas."}, "source": "PAGASA disaster preparedness; DepEd Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "typhoon-satellite-spiral-g6", "domain": "EARTH_SPACE", "topic": "spiral shape of a typhoon", "grades": [5, 6, 7], "terms": ["typhoon spiral", "umiikot na bagyo", "satellite", "satelayt", "litrato mula sa langit", "spiral", "ikot ng ulap", "bagyo", "unos", "umiikot ang hangin", "mula sa itaas", "larawan ng bagyo", "PAGASA"], "fact": {"tl": "Kapag tiningnan mula sa satellite sa kalawakan, ang isang bagyo ay parang malaking umiikot na spiral ng ulap, na ang umiikot na hangin ay pumapaikot sa tahimik na mata sa gitna.", "en": "Seen from a satellite in space, a typhoon looks like a giant swirling spiral of clouds, with the winds spinning around the calm eye at its center.", "bis": "Kung tan-awon gikan sa satellite sa kawanangan, ang usa ka bagyo morag dako nga nagtuyok nga spiral sa mga panganod, nga ang hangin nagtuyok libot sa malinawon nga mata sa tunga niini."}, "source": "PAGASA; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "typhoon-structure-g8", "domain": "EARTH_SPACE", "topic": "structure of a typhoon", "grades": [7, 8, 9], "terms": ["typhoon structure", "bahagi ng bagyo", "bahin sa bagyo", "eye", "mata", "eyewall", "rainbands", "spiral bands", "warm ocean", "mainit na dagat", "init nga dagat", "singaw", "tropical cyclone", "umiikot", "bagyo"], "fact": {"tl": "Binubuo ang isang bagyo ng tatlong pangunahing bahagi: ang tahimik na mata sa gitna, ang eyewall na may pinakamalakas na hangin, at ang mga spiral rainband na nagdadala ng ulan sa palibot.", "en": "A typhoon is made of three main parts: the calm eye at the center, the eyewall with the strongest winds, and the spiral rainbands that carry rain around the outside.", "bis": "Ang usa ka bagyo gilangkoban sa tulo ka nag-unang bahin: ang malinawon nga mata sa tunga, ang eyewall nga adunay labing kusog nga hangin, ug ang mga spiral rainband nga nagdala sa ulan sa palibot."}, "source": "PAGASA; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "venus-bright-evening-star-g6", "domain": "EARTH_SPACE", "topic": "Venus as evening and morning star", "grades": [5, 6, 7], "terms": ["Venus", "Benus", "tala sa gabi", "evening star", "morning star", "tala sa umaga", "pinakamaliwanag na planeta", "bituin", "planeta", "Tala", "kabukasan", "liwanag", "hindi bituin", "maliwanag sa langit"], "fact": {"tl": "Ang maliwanag na 'tala' na madalas makita sa langit pagkatapos lumubog ang araw o bago sumikat ito ay hindi talaga bituin kundi ang planetang Venus, ang pinakamaliwanag na planeta sa ating langit.", "en": "The bright 'star' often seen in the sky just after sunset or before sunrise is not really a star but the planet Venus, the brightest planet in our sky.", "bis": "Ang hayag nga 'bitoon' nga sagad makita sa langit human mosalop ang adlaw o sa dili pa kini mosubang dili gayod bitoon kondili ang planeta nga Venus, ang labing hayag nga planeta sa atong langit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "virga-rain-streaks-g8", "domain": "EARTH_SPACE", "topic": "virga evaporating rain", "grades": [7, 8, 9], "terms": ["virga", "ulan na hindi umabot sa lupa", "rain streaks", "guhit ng ulan", "sumisingaw na ulan", "ulan", "evaporate", "natutuyo", "tuyong hangin", "ulap", "panganod", "buntot ng ulan", "hindi umuulan sa lupa"], "fact": {"tl": "Ang virga ay mga guhit ng ulan na bumababa mula sa ulap pero sumisingaw at nawawala bago pa man umabot sa lupa dahil sa tuyong hangin sa ibaba.", "en": "Virga are streaks of rain that fall from a cloud but evaporate and disappear before reaching the ground because the air below is dry.", "bis": "Ang virga mao ang mga guhit sa ulan nga manaog gikan sa panganod apan mosingaw ug mawala sa dili pa kini makaabot sa yuta tungod sa uga nga hangin sa ubos."}, "source": "encyclopedia-stable consensus (meteorology)", "generator": "claude-workflow", "reviewed": false},
  {"id": "volcano-baking-soda-model-g5", "domain": "MATTER", "topic": "baking soda volcano chemical reaction", "grades": [4, 5, 6], "terms": ["baking soda volcano", "modelong bulkan", "bulkan", "bukan-bukan", "baking soda", "suka", "vinegar", "bula", "umaapaw", "reaksyon", "chemical reaction", "carbon dioxide", "gas", "eksperimento", "pagputok"], "fact": {"tl": "Sa modelong bulkan, kapag pinaghalo ang baking soda at suka, nagkakaroon ng kemikal na reaksyon na gumagawa ng carbon dioxide gas, kaya umaapaw ang bumubulang halo na parang lumalabas na lava.", "en": "In a baking soda volcano model, mixing baking soda and vinegar causes a chemical reaction that makes carbon dioxide gas, so the bubbly mixture foams up and overflows like erupting lava.", "bis": "Sa modelo nga bulkan, kung isagol ang baking soda ug suka, adunay kemikal nga reaksyon nga maghimo ug carbon dioxide nga gas, mao nga ang nagbula nga sagol moawas nga morag nagbuga nga lava."}, "source": "encyclopedia-stable consensus; NRC PS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "volcano-erupting-g6", "domain": "EARTH_SPACE", "topic": "volcanic eruption", "grades": [5, 6, 7], "terms": ["volcano", "bulkan", "bukan", "pagputok ng bulkan", "pagbuto sa bulkan", "lava", "magma", "abo", "abog", "ash", "eruption", "Mayon", "Taal", "Pinatubo", "init sa ilalim", "PHIVOLCS"], "fact": {"tl": "Ang pagputok ng bulkan ay nangyayari kapag ang mainit na natunaw na bato o magma mula sa ilalim ng Earth ay umaakyat at lumalabas bilang lava, abo, at gas, tulad ng nakikita sa Bulkang Mayon at Taal.", "en": "A volcanic eruption happens when hot melted rock or magma from deep inside Earth rises and bursts out as lava, ash, and gas, like at Mayon and Taal Volcanoes.", "bis": "Ang pagbuto sa bulkan mahitabo kung ang init nga natunaw nga bato o magma gikan sa kahiladman sa Yuta mosaka ug mogula isip lava, abo, ug gas, sama sa makita sa Bulkang Mayon ug Taal."}, "source": "PHIVOLCS; NRC ESS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-cycle-bag-window-g4", "domain": "EARTH_SPACE", "topic": "water cycle in a bag", "grades": [3, 4, 5], "terms": ["water cycle", "siklo ng tubig", "tubig", "bag", "supot", "plastik", "bintana", "singaw", "evaporation", "pagsingaw", "condensation", "patak", "tulo", "ulan", "eksperimento", "init ng araw"], "fact": {"tl": "Sa eksperimentong water-cycle-in-a-bag, ang init ng araw ay nagpapasingaw sa tubig sa loob ng supot, at ang singaw ay namumuong muli sa malalamig na bahagi at bumababang parang ulan, na nagpapakita ng siklo ng tubig.", "en": "In a water-cycle-in-a-bag experiment, the Sun's heat evaporates water inside the bag, and the vapor condenses on the cooler sides and trickles down like rain, showing the water cycle.", "bis": "Sa eksperimento nga water-cycle-in-a-bag, ang kainit sa adlaw mopasingaw sa tubig sulod sa supot, ug ang singaw mausa balik sa mas bugnaw nga bahin ug manaog nga morag ulan, nga nagpakita sa siklo sa tubig."}, "source": "NRC ESS2.C; DepEd Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-filter-bottle-layers-g6", "domain": "MATTER", "topic": "water filtration with layers", "grades": [5, 6, 7], "terms": ["water filter", "salaan ng tubig", "pagsala sa tubig", "bottle", "bote", "buhangin", "sand", "graba", "gravel", "uling", "charcoal", "layers", "patong-patong", "marumi", "malinis", "filtration", "dumi"], "fact": {"tl": "Sa isang water filter na yari sa bote, ang patong-patong na buhangin, graba, at uling ay sumasala sa marurumi at maliliit na piraso ng dumi habang dumadaloy ang tubig pababa, kaya mas malinaw ang lumalabas na tubig.", "en": "In a bottle water filter, layers of sand, gravel, and charcoal trap dirt and small bits as the water flows down, so the water that comes out is clearer.", "bis": "Sa usa ka water filter nga hinimo gikan sa botelya, ang sapaw-sapaw nga balas, graba, ug uling mosala sa hugaw ug gagmay nga tipik samtang nag-agay ang tubig paubos, mao nga mas tin-aw ang tubig nga mogawas."}, "source": "encyclopedia-stable consensus; DepEd Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "waterfall-scene-g6", "domain": "EARTH_SPACE", "topic": "how waterfalls form", "grades": [5, 6, 7], "terms": ["waterfall", "talon", "busay", "ilog", "suba", "bumabagsak na tubig", "bato", "matigas na bato", "malambot na bato", "erosion", "natutunaw na bato", "gravity", "tubig na bumababa", "Maria Cristina", "Tinuy-an"], "fact": {"tl": "Nabubuo ang talon kapag ang ilog ay dumadaloy mula sa matigas na bato patungo sa mas malambot na bato, na unti-unting natitibag, kaya bumabagsak ang tubig nang patayo pababa.", "en": "A waterfall forms where a river flows from hard rock onto softer rock that slowly wears away, so the water drops straight down over the edge.", "bis": "Ang busay maporma kung ang suba moagay gikan sa gahi nga bato padulong sa mas humok nga bato nga hinay-hinay nga makutkot, mao nga ang tubig mahulog nga tul-id paubos sa ngilit."}, "source": "NRC ESS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "watershed-protection-forest-vs-bare-g8", "domain": "EARTH_SPACE", "topic": "forests protect watersheds", "grades": [7, 8, 9], "terms": ["watershed", "imbakan ng tubig", "kabukiran", "gubat", "kakahuyan", "kalasangan", "lasang", "kalbo", "bare land", "ugat", "roots", "erosion", "guho", "baha", "flood", "natutuyo", "pagpapanatili ng tubig"], "fact": {"tl": "Mas napoprotektahan ng isang gubat ang watershed kaysa sa kalbong lupa dahil ang mga ugat at lupa nito ay sumisipsip at nagtatabi ng tubig-ulan, kaya nababawasan ang baha at guho at nananatili ang malinis na tubig.", "en": "A forest protects a watershed better than bare land because its roots and soil soak up and store rainwater, reducing floods and landslides and keeping the water clean.", "bis": "Ang lasang mas makapanalipod sa watershed kay sa hubo nga yuta tungod kay ang mga gamot ug yuta niini mosuyop ug motipig sa tubig-ulan, mao nga makunhuran ang baha ug dahili ug magpabiling limpyo ang tubig."}, "source": "NRC ESS3.C; DepEd Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "watershed-protection-scene-g6", "domain": "EARTH_SPACE", "topic": "what a watershed is", "grades": [5, 6, 7], "terms": ["watershed", "imbakan ng tubig", "saluran ng tubig", "ilog", "suba", "ulan", "tubig-ulan", "umaagos pababa", "bundok", "burol", "lupang sumasalo ng tubig", "pinagkukunan ng tubig", "drinking water", "inumin"], "fact": {"tl": "Ang watershed ay isang lugar ng lupa kung saan ang lahat ng tubig-ulan ay umaagos pababa patungo sa iisang ilog, lawa, o imbakan, kaya mahalaga itong pangalagaan bilang pinagmumulan ng ating inuming tubig.", "en": "A watershed is an area of land where all the rainwater flows down into the same river, lake, or reservoir, so it must be protected as a source of our drinking water.", "bis": "Ang watershed usa ka dapit sa yuta diin ang tanang tubig-ulan moagay paubos padulong sa usa ra ka suba, lanaw, o reserboryo, mao nga importante kining bantayan isip tuboran sa atong imnonon nga tubig."}, "source": "NRC ESS3.C; DepEd Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "watershed-water-flow-diagram-g6", "domain": "EARTH_SPACE", "topic": "watershed and water flow", "grades": [5, 6, 7], "terms": ["watershed", "kapaligiran ng tubig", "agos ng tubig", "ilog", "sapa", "river", "stream", "drainage", "tubigan", "dagayday sa tubig", "suba", "rainwater flow", "ulan", "tubig-ulan", "linaw"], "fact": {"tl": "Ang watershed ay isang lugar kung saan ang lahat ng tubig-ulan ay umaagos pababa at nagtitipon sa iisang ilog, lawa, o dagat.", "en": "A watershed is an area of land where all the rainwater flows downhill and drains into the same river, lake, or sea.", "bis": "Ang watershed usa ka dapit diin ang tanang tubig-ulan modagayday paubos ug magtapok sa usa lang ka suba, linaw, o dagat."}, "source": "NRC ESS2.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "weather-chart-g5", "domain": "EARTH_SPACE", "topic": "weather chart and observation", "grades": [4, 5, 6], "terms": ["weather chart", "tsart ng panahon", "talaan ng panahon", "panahon", "ulan", "araw", "ulap", "temperatura", "weather record", "talaan", "rekord sa panahon", "init", "ulanon", "panganuron"], "fact": {"tl": "Ang weather chart ay isang talaan na nagtatala araw-araw kung maaraw, maulan, o maulap, para makita ang pattern ng panahon.", "en": "A weather chart is a record that tracks each day whether it is sunny, rainy, or cloudy, so we can see patterns in the weather.", "bis": "Ang weather chart usa ka talaan nga nagrekord matag adlaw kon init, ulanon, o panganuron, aron makita ang sumbanan sa panahon."}, "source": "DepEd MATATAG Science G4-5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "weather-forecaster-scene-g6", "domain": "EARTH_SPACE", "topic": "weather forecasting", "grades": [5, 6, 7], "terms": ["weather forecaster", "forecaster", "taga-hula ng panahon", "PAGASA", "pagtataya ng panahon", "panahon", "bagyo", "ulan", "forecast", "taga-tagna sa panahon", "panagna sa panahon", "weather report", "hangin", "panganod"], "fact": {"tl": "Ang weather forecaster ay gumagamit ng datos mula sa PAGASA tulad ng temperatura, hangin, at ulap para hulaan ang magiging panahon kinabukasan.", "en": "A weather forecaster uses data from PAGASA such as temperature, wind, and clouds to predict what the weather will be tomorrow.", "bis": "Ang weather forecaster mogamit ug datos gikan sa PAGASA sama sa temperatura, hangin, ug panganod aron matagna ang panahon ugma."}, "source": "DepEd MATATAG Science G6; PAGASA; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "weather-station-backyard-setup-g6", "domain": "EARTH_SPACE", "topic": "weather instruments", "grades": [5, 6, 7], "terms": ["weather station", "estasyon ng panahon", "thermometer", "termometro", "rain gauge", "panukat ng ulan", "anemometer", "panukat ng hangin", "weather instruments", "kagamitan sa panahon", "sukdanan sa ulan", "sukdanan sa hangin", "init", "hangin"], "fact": {"tl": "Ang weather station ay may mga kagamitan tulad ng termometro para sa init, rain gauge para sa dami ng ulan, at anemometer para sa bilis ng hangin.", "en": "A weather station has tools like a thermometer for heat, a rain gauge for how much rain fell, and an anemometer for wind speed.", "bis": "Ang weather station adunay mga gamit sama sa termometro para sa kainit, rain gauge para sa gidaghanon sa ulan, ug anemometer para sa katulin sa hangin."}, "source": "DepEd MATATAG Science G6; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "weather-symbol-set-g4", "domain": "EARTH_SPACE", "topic": "weather symbols", "grades": [3, 4, 5], "terms": ["weather symbol", "simbolo ng panahon", "tanda ng panahon", "araw", "ulap", "ulan", "kidlat", "sun symbol", "cloud", "rain", "simbolo sa panahon", "timaan sa panahon", "adlaw", "panganod", "kilat"], "fact": {"tl": "Ang mga weather symbol ay maliliit na larawan tulad ng araw, ulap, o patak ng ulan na mabilis nagsasabi kung anong panahon ang inaasahan.", "en": "Weather symbols are small pictures like a sun, a cloud, or raindrops that quickly show what kind of weather is expected.", "bis": "Ang mga weather symbol gagmay nga mga hulagway sama sa adlaw, panganod, o tulo sa ulan nga paspas magpakita kon unsa nga panahon ang gipaabot."}, "source": "DepEd MATATAG Science G3-4; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "weathering-of-rocks-g6", "domain": "EARTH_SPACE", "topic": "weathering of rocks", "grades": [5, 6, 7], "terms": ["weathering", "pagguho ng bato", "pagdurog ng bato", "bato", "tubig", "ulan", "hangin", "init", "rock breaking", "pagkadunot sa bato", "pagkadugmok sa bato", "katugnaw", "lamig"], "fact": {"tl": "Ang weathering ay ang unti-unting pagdurog ng malalaking bato sa maliliit na piraso dahil sa tubig, init, hangin, at lamig sa loob ng mahabang panahon.", "en": "Weathering is the slow breaking of large rocks into smaller pieces caused by water, heat, wind, and cold over a long time.", "bis": "Ang weathering mao ang hinay-hinay nga pagkadugmok sa dagkong bato ngadto sa gagmayng tipik tungod sa tubig, kainit, hangin, ug katugnaw sulod sa taas nga panahon."}, "source": "NRC ESS2.A; DepEd G6 Earth Science; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "weathering-of-rocks-g9", "domain": "EARTH_SPACE", "topic": "physical vs chemical weathering", "grades": [8, 9, 10], "terms": ["weathering", "physical weathering", "chemical weathering", "pisikal na pagguho", "kemikal na pagguho", "pagdurog ng bato", "acid rain", "asido", "oxidation", "kalawang", "pisikal nga pagkadunot", "kemikal nga pagkadunot", "asidong ulan", "mineral"], "fact": {"tl": "May dalawang uri ng weathering: pisikal na nagdudurog lang sa bato nang hindi nagbabago ang sangkap, at kemikal na nagpapalit sa mga mineral sa loob ng bato.", "en": "There are two kinds of weathering: physical, which only breaks rock apart without changing its substance, and chemical, which changes the minerals inside the rock.", "bis": "Adunay duha ka matang sa weathering: pisikal nga modugmok lang sa bato nga walay kausaban sa sangkap, ug kemikal nga mousab sa mga mineral sulod sa bato."}, "source": "NRC ESS2.A; AAAS Benchmarks; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "white-island-sandbar-g6", "domain": "EARTH_SPACE", "topic": "sandbar formation", "grades": [5, 6, 7], "terms": ["sandbar", "White Island", "Camiguin", "buhangin", "pulo ng buhangin", "alon", "agos", "tides", "sand", "balas", "balason nga pulo", "balud", "sulog", "pulo sa buhangin", "isla"], "fact": {"tl": "Ang White Island sa Camiguin ay isang sandbar—isang tumpok ng puting buhangin na inihahatid at hinuhubog ng mga alon at agos ng dagat.", "en": "White Island in Camiguin is a sandbar—a heap of white sand carried in and shaped by ocean waves and currents.", "bis": "Ang White Island sa Camiguin usa ka sandbar—usa ka tapok sa puting balas nga gidala ug giporma sa mga balud ug sulog sa dagat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-philippines-has-wet-dry-seasons-g6", "domain": "EARTH_SPACE", "topic": "Philippine monsoon seasons", "grades": [5, 6, 7], "terms": ["wet season", "dry season", "tag-ulan", "tag-init", "tag-araw", "monsoon", "habagat", "amihan", "panahon", "Pilipinas", "rainy season", "ting-ulan", "ting-init", "Pilipinas"], "fact": {"tl": "May tag-ulan at tag-init ang Pilipinas dahil sa mga hanging monsoon: ang habagat mula sa timog-kanluran ay nagdadala ng ulan, samantalang ang amihan mula sa hilagang-silangan ay nagdadala ng malamig at tuyong hangin.", "en": "The Philippines has wet and dry seasons because of monsoon winds: the habagat from the southwest brings rain, while the amihan from the northeast brings cool, dry air.", "bis": "Ang Pilipinas adunay ting-ulan ug ting-init tungod sa mga hangin nga monsoon: ang habagat gikan sa habagatan-kasadpan magdala ug ulan, samtang ang amihan gikan sa amihanan-sidlakan magdala ug bugnaw ug uga nga hangin."}, "source": "PAGASA; DepEd MATATAG Science G6; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wind-sock-cone-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "wind direction indicator", "grades": [4, 5, 6], "terms": ["windsock", "wind sock", "panukat ng hangin", "direksyon ng hangin", "hangin", "wind direction", "airport", "wind speed", "sukdanan sa hangin", "direksyon sa hangin", "kusog sa hangin", "tela", "panapton"], "fact": {"tl": "Ang windsock ay isang tubular na tela na umaalon papunta sa direksyong tinatangay ng hangin, at lumalakas ang pagtayo nito kapag mas malakas ang hangin.", "en": "A windsock is a tube of cloth that points the way the wind is blowing, and stands out straighter when the wind is stronger.", "bis": "Ang windsock usa ka tubular nga panapton nga magtudlo sa direksyon nga gihuyop sa hangin, ug motindog nga mas tul-id kon mas kusog ang hangin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "abaniko-folding-fan-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "moving air cools us", "grades": [3, 4, 5], "terms": ["abaniko", "pamaypay", "folding fan", "hangin", "lamig", "pawis", "init", "fan", "moving air", "paypay", "pawhang", "singot", "pagpalamig", "bugnaw"], "fact": {"tl": "Kapag pinapaypay tayo ng abaniko, pinapagalaw nito ang hangin na tumatangay sa init at pawis sa balat, kaya nararamdaman nating mas malamig.", "en": "When we wave an abaniko, it moves the air that carries heat and sweat away from our skin, so we feel cooler.", "bis": "Kon magpaypay ta ug abaniko, gipalihok niini ang hangin nga magdala sa init ug singot palayo sa atong panit, mao nga mobati ta nga mas bugnaw."}, "source": "NRC PS3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "acoustic-guitar-instrument-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "sound from vibrating strings", "grades": [4, 5, 6], "terms": ["gitara", "acoustic guitar", "kuwerdas", "string", "tunog", "vibration", "pag-vibrate", "sound", "music", "kwerdas", "tingog", "pagkurog", "tugtog"], "fact": {"tl": "Kapag pinitik ang kuwerdas ng gitara, nag-vibrate ito at pinapayanig ang hangin sa loob ng kahon, na siyang gumagawa ng tunog na naririnig natin.", "en": "When a guitar string is plucked, it vibrates and shakes the air inside the wooden body, which makes the sound we hear.", "bis": "Kon pitikon ang kuwerdas sa gitara, mokurog kini ug mauyog ang hangin sulod sa kahoy nga lawas, nga maoy maghimo sa tingog nga atong madungog."}, "source": "NRC PS4.A; AAAS Benchmarks; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "adobo-rice-bowl-g6", "domain": "MATTER", "topic": "vinegar as a food preservative", "grades": [5, 6, 7], "terms": ["adobo", "suka", "vinegar", "asido", "pagpapanatili ng pagkain", "preservative", "bakterya", "panis", "acid", "preservation", "pagkadaot sa pagkaon", "pan-os", "mapanis"], "fact": {"tl": "Ang suka sa adobo ay asido na pumipigil sa pagdami ng bakterya, kaya mas matagal bago mapanis ang pagkain.", "en": "The vinegar in adobo is an acid that slows the growth of bacteria, so the food takes longer to spoil.", "bis": "Ang suka sa adobo usa ka asido nga makapahinay sa pagdaghan sa bakterya, mao nga mas dugay mapan-os ang pagkaon."}, "source": "NRC LS1; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "adobong-mani-garlic-peanuts-g5", "domain": "LIVING_THINGS", "topic": "peanut is a legume", "grades": [4, 5, 6], "terms": ["mani", "peanut", "adobong mani", "legume", "buto", "halaman", "ugat", "lupa", "protina", "binhi", "liso", "tanom", "gamot", "yuta"], "fact": {"tl": "Ang mani ay isang legume na tumutubo ang bunga sa ilalim ng lupa, at mayaman ito sa protina na nakakatulong sa paglaki ng katawan.", "en": "The peanut is a legume whose pods grow underground, and it is rich in protein that helps the body grow.", "bis": "Ang mani usa ka legume nga ang bunga motubo ilalom sa yuta, ug dato kini sa protina nga makatabang sa pagtubo sa lawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "agawan-base-tag-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "speed and motion in games", "grades": [3, 4, 5], "terms": ["agawan base", "habulan", "laro", "takbo", "bilis", "galaw", "speed", "running", "motion", "dula", "dagan", "katulin", "lihok", "habol"], "fact": {"tl": "Sa laro ng agawan base, mas mabilis na tumatakbo ang nanalo dahil mas malaki ang distansyang nalalakbay nito sa parehong oras.", "en": "In agawan base, the faster runner wins because they cover more distance in the same amount of time.", "bis": "Sa dula nga agawan base, ang mas paspas modagan modaog tungod kay mas dako ang gilay-on nga iyang malatas sa samang gidugayon."}, "source": "NRC PS2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "agung-gong-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "sound from a vibrating gong", "grades": [4, 5, 6], "terms": ["agung", "gong", "tansan", "metal", "vibration", "tunog", "pagyanig", "sound", "instrumento", "kulintang", "pagkurog", "tingog", "pauk"], "fact": {"tl": "Kapag pinalo ang agung, nag-vibrate ang malapad nitong metal at nagpapayanig ng hangin, kaya lumalabas ang malalim at malakas na tunog.", "en": "When the agung is struck, its wide metal surface vibrates and shakes the air, producing a deep, loud sound.", "bis": "Kon paukon ang agung, mokurog ang halapad niini nga metal ug mauyog ang hangin, mao nga mogawas ang lawom ug kusog nga tingog."}, "source": "NRC PS4.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "angklung-bamboo-shaker-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "sound from vibrating bamboo", "grades": [4, 5, 6], "terms": ["angklung", "kawayan", "bamboo", "instrumento", "tunog", "vibration", "shaker", "music", "tingog", "pagkurog", "tugtog", "uyog", "tono"], "fact": {"tl": "Ang angklung ay gawa sa kawayan na kapag inalog ay nag-vibrate at gumagawa ng tunog; iba't ibang haba ng kawayan ang gumagawa ng iba't ibang tono.", "en": "The angklung is made of bamboo that vibrates and makes sound when shaken; different lengths of bamboo produce different musical tones.", "bis": "Ang angklung hinimo sa kawayan nga kon uyogon mokurog ug mohimo ug tingog; lainlaing gitas-on sa kawayan maghimo ug lainlaing tono."}, "source": "NRC PS4.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "animal-footprint-track-g4", "domain": "LIVING_THINGS", "topic": "animal tracks as evidence", "grades": [3, 4, 5], "terms": ["bakas", "yapak ng hayop", "footprint", "track", "hayop", "paa", "lupa", "putik", "animal track", "tunob", "tunob sa hayop", "tiil", "lapok", "agi"], "fact": {"tl": "Ang bakas o yapak na naiiwan ng hayop sa putik o buhangin ay nagsasabi sa atin kung anong hayop ang dumaan at saang direksyon ito pumunta.", "en": "The tracks or footprints an animal leaves in mud or sand tell us what animal passed by and which direction it went.", "bis": "Ang mga tunob o agi nga ibilin sa hayop sa lapok o balas magsulti kanato kon unsa nga hayop ang miagi ug asa kini paingon."}, "source": "NRC LS; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "backpack-school-bag-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "backpack straps spread weight", "grades": [3, 4, 5], "terms": ["backpack", "bag", "school bag", "straps", "weight", "load", "force", "shoulders", "bagahe", "sako", "balikat", "bigat", "puwersa", "strap", "pasanin", "abaga", "bug-at", "kusog"], "fact": {"tl": "Ang malapad na strap ng backpack ay nagpapakalat ng bigat ng mga gamit sa malaking bahagi ng balikat, kaya hindi gaanong masakit kaysa makitid na strap.", "en": "A backpack's wide straps spread the weight of your things over more of your shoulders, so it hurts less than thin straps would.", "bis": "Ang lapad nga strap sa backpack nagpakatag sa bug-at sa imong mga gamit sa dako nga bahin sa abaga, mao nga dili kaayo sakit kay sa nipis nga strap."}, "source": "encyclopedia-stable consensus; NRC PS2.B (pressure = force over area)", "generator": "claude-workflow", "reviewed": false},
  {"id": "badminton-shuttlecock-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "shuttlecock air resistance", "grades": [4, 5, 6], "terms": ["badminton", "shuttlecock", "shuttle", "racket", "raketa", "balahibo", "feathers", "air resistance", "hangin", "drag", "bumagal", "lumipad", "hampas", "balhibo", "kusog", "lupad", "resistensya"], "fact": {"tl": "Ang shuttlecock sa badminton ay may bukas na korong-balahibo na humahawak sa hangin, kaya mabilis itong bumagal at laging unang bumabagsak ang mabigat na ulo nito.", "en": "A badminton shuttlecock has an open cone of feathers that grips the air, so it slows down quickly and always flips to fall heavy-head first.", "bis": "Ang shuttlecock sa badminton naay abli nga kono sa balhibo nga mokupot sa hangin, mao nga paspas kini nga mohinay ug kanunay magpauna ang bug-at niini nga ulo sa paghulog."}, "source": "encyclopedia-stable consensus; NRC PS2.A (forces and motion)", "generator": "claude-workflow", "reviewed": false},
  {"id": "bahay-kubo-vegetables-g3", "domain": "LIVING_THINGS", "topic": "garden vegetables we eat", "grades": [3, 4, 5], "terms": ["bahay kubo", "gulay", "halaman", "vegetables", "garden", "singkamas", "talong", "sigarilyas", "mani", "sitaw", "patani", "kundol", "patola", "upo", "kalabasa", "labanos", "mustasa", "tanim", "ugat", "bunga", "utanon", "tanom", "prutas", "kamatis"], "fact": {"tl": "Ang kantang Bahay Kubo ay naglilista ng mga gulay tulad ng singkamas, talong, at kalabasa—mga halaman na kinakain natin ang kanilang ugat, bunga, o dahon.", "en": "The song Bahay Kubo names vegetables like singkamas, eggplant, and squash—garden plants whose roots, fruits, or leaves we eat.", "bis": "Ang kanta nga Bahay Kubo naglista sa mga utanon sama sa singkamas, talong, ug kalabasa—mga tanom nga atong gikaon ang ilang gamot, bunga, o dahon."}, "source": "encyclopedia-stable consensus; DepEd G3 (plants we use)", "generator": "claude-workflow", "reviewed": false},
  {"id": "bakya-wooden-clogs-g4", "domain": "MATTER", "topic": "wood as a clog material", "grades": [3, 4, 5], "terms": ["bakya", "wooden clogs", "wood", "kahoy", "sandals", "tsinelas", "santol", "lightweight", "magaan", "material", "sapatos", "gaan", "panit", "tuyo"], "fact": {"tl": "Ang bakya ay ginagawa mula sa magaan na kahoy gaya ng santol, na inuukit para sa hugis ng paa at tinapakan ng goma o tela.", "en": "Bakya clogs are carved from light wood such as santol, shaped to the foot and topped with a rubber or cloth strap.", "bis": "Ang bakya gihimo gikan sa gaan nga kahoy sama sa santol, nga gikulit sumala sa porma sa tiil ug gibutangan ug goma o panapton nga strap."}, "source": "encyclopedia-stable consensus (material properties of wood)", "generator": "claude-workflow", "reviewed": false},
  {"id": "balsa-bamboo-raft-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "why a bamboo raft floats", "grades": [4, 5, 6], "terms": ["balsa", "raft", "bamboo raft", "kawayan", "bamboo", "float", "lumulutang", "buoyancy", "tubig", "hollow", "guwang", "lutaw", "lumutang", "buoyansya", "magaan", "lutaw"], "fact": {"tl": "Ang balsa na kawayan ay lumulutang dahil ang guwang at magaan na mga tangkay ng kawayan ay puno ng hangin at mas magaan kaysa tubig.", "en": "A bamboo raft floats because bamboo's hollow, light poles are full of air and weigh less than the water they push aside.", "bis": "Ang balsa nga kawayan molutaw tungod kay ang guwang ug gaan nga mga lawas sa kawayan puno sa hangin ug mas gaan kay sa tubig nga ilang gitulak."}, "source": "encyclopedia-stable consensus; NRC PS2.B (buoyancy)", "generator": "claude-workflow", "reviewed": false},
  {"id": "balut-duck-egg-g6", "domain": "LIVING_THINGS", "topic": "developing duck embryo in egg", "grades": [5, 6, 7], "terms": ["balut", "duck egg", "itlog", "pato", "embryo", "embriyo", "developing", "sisiw", "egg", "incubated", "pinisa", "itlog ng pato", "yolk", "itog", "itik", "pisa", "binhi"], "fact": {"tl": "Ang balut ay itlog ng pato na pinausbong ng init nang ilang araw, kaya makikita sa loob ang nagsisimulang bumuong sisiw ng pato.", "en": "Balut is a duck egg warmed for several days, so inside you can see a partly developed duck embryo beginning to take shape.", "bis": "Ang balut maoy itlog sa itik nga gipainit sa pipila ka adlaw, mao nga sa sulod makita ang nagsugod nga molambo nga embryo sa itik."}, "source": "encyclopedia-stable consensus; NRC LS1.B (animal development)", "generator": "claude-workflow", "reviewed": false},
  {"id": "musikong-bumbong-bamboo-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "sound from bamboo instruments", "grades": [4, 5, 6], "terms": ["musikong bumbong", "bamboo band", "kawayan", "bamboo", "tunog", "sound", "vibration", "vibrate", "hihip", "hangin", "instrumento", "huni", "tingog", "kurog", "huyop", "banda", "musika"], "fact": {"tl": "Sa musikong bumbong, ang tunog ay nagmumula sa hanging umuugong sa loob ng mga tubo ng kawayan na nagpapayanig sa hangin sa loob nito.", "en": "In a musikong bumbong band, the sound comes from air vibrating inside hollow bamboo tubes when the players blow across or into them.", "bis": "Sa musikong bumbong, ang tingog gikan sa hangin nga nagkurog sulod sa guwang nga mga tubo sa kawayan kung huypan kini sa mga tigtugtog."}, "source": "encyclopedia-stable consensus; NRC PS4.A (sound from vibration)", "generator": "claude-workflow", "reviewed": false},
  {"id": "bamboo-clapper-kalatok-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "sound when bamboo strikes", "grades": [3, 4, 5], "terms": ["kalatok", "bamboo clapper", "clapper", "kawayan", "bamboo", "tunog", "sound", "vibration", "tama", "hampas", "klik", "tingog", "kurog", "tagsing", "igo"], "fact": {"tl": "Ang kalatok ay gumagawa ng tunog kapag ang dalawang piraso ng kawayan ay nagtatama, na nagpapayanig sa hangin sa paligid.", "en": "A kalatok makes its clacking sound when two pieces of bamboo strike each other, setting the surrounding air vibrating.", "bis": "Ang kalatok mohimo ug tingog kung ang duha ka piraso sa kawayan mag-igoay, nga magpakurog sa hangin sa palibot."}, "source": "encyclopedia-stable consensus; NRC PS4.A (sound)", "generator": "claude-workflow", "reviewed": false},
  {"id": "bamboo-flute-tulali-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "pitch in a bamboo flute", "grades": [4, 5, 6], "terms": ["tulali", "bamboo flute", "plawta", "flute", "kawayan", "bamboo", "tunog", "sound", "butas", "holes", "pitch", "mataas", "mababa", "hangin", "tingog", "lungag", "huyop", "tono"], "fact": {"tl": "Sa tulali na kawayan, nagbabago ang taas ng tono kapag tinakpan o binuksan mo ang mga butas, dahil binabago nito ang haba ng nag-uugong na hangin sa loob.", "en": "On a bamboo tulali flute, the pitch changes as you cover or open the finger holes, because that changes the length of vibrating air inside.", "bis": "Sa tulali nga kawayan, mausab ang kahabog sa tono kung tabunan o ablihan nimo ang mga lungag, kay mausab niini ang gitas-on sa nagkurog nga hangin sa sulod."}, "source": "encyclopedia-stable consensus; NRC PS4.A (pitch and vibration)", "generator": "claude-workflow", "reviewed": false},
  {"id": "gabbang-xylophone-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "bar length sets pitch", "grades": [4, 5, 6], "terms": ["gabbang", "bamboo xylophone", "xylophone", "kawayan", "bamboo", "tunog", "pitch", "haba", "length", "bar", "mataas", "mababa", "tono", "tingog", "gitas-on", "habog", "hampas", "instrumento"], "fact": {"tl": "Sa gabbang, ang mas maikling tipak ng kawayan ay gumagawa ng mas mataas na tono, habang ang mas mahaba ay gumagawa ng mas mababang tono.", "en": "On a gabbang bamboo xylophone, shorter bamboo bars make higher-pitched notes while longer bars make lower-pitched notes.", "bis": "Sa gabbang, ang mas mubo nga piraso sa kawayan mohimo ug mas habog nga tono, samtang ang mas taas mohimo ug mas ubos nga tono."}, "source": "encyclopedia-stable consensus; NRC PS4.A (pitch depends on length)", "generator": "claude-workflow", "reviewed": false},
  {"id": "banana-chips-frying-g5", "domain": "MATTER", "topic": "frying removes water to crisp", "grades": [4, 5, 6], "terms": ["banana chips", "saging", "chips", "pritong saging", "frying", "prito", "crispy", "malutong", "tubig", "water", "init", "tuyot", "mainit", "mantika", "tuyo", "lutong"], "fact": {"tl": "Ang manipis na hiwa ng saging ay nagiging malutong na banana chips kapag pinirito, dahil ang mainit na mantika ay nagpapasingaw sa karamihan ng tubig sa loob nito.", "en": "Thin banana slices turn into crispy banana chips when fried, because the hot oil drives off most of the water inside them.", "bis": "Ang nipis nga hiwa sa saging mahimong lutong nga banana chips kung iprito, kay ang init nga mantika moabog sa kadaghanan sa tubig sa sulod niini."}, "source": "encyclopedia-stable consensus; NRC PS1.B (changes from heating)", "generator": "claude-workflow", "reviewed": false},
  {"id": "banana-que-caramel-g5", "domain": "MATTER", "topic": "sugar caramelizes when heated", "grades": [4, 5, 6], "terms": ["banana que", "banana cue", "asukal", "sugar", "caramel", "saging", "init", "kayumanggi", "brown", "natunaw", "matamis", "kalan", "tunaw", "pula", "tam-is"], "fact": {"tl": "Sa banana que, ang asukal na binudbod sa saging ay natutunaw at nagiging kayumangging caramel kapag pinainit, na nagbibigay ng matamis at malutong na balat.", "en": "In banana que, the sugar coating melts and turns into brown caramel when heated, giving the banana its sweet, crunchy crust.", "bis": "Sa banana que, ang asukal nga gibutang sa saging matunaw ug mahimong pula-pula nga caramel kung initan, nga mohatag ug tam-is ug lutong nga panit."}, "source": "encyclopedia-stable consensus; NRC PS1.B (chemical change from heat)", "generator": "claude-workflow", "reviewed": false},
  {"id": "banca-outrigger-stability-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "outriggers keep a boat stable", "grades": [5, 6, 7], "terms": ["banca", "bangka", "outrigger", "katig", "boat", "stability", "balanse", "lumulutang", "tubig", "tumba", "balance", "lutaw", "sakayan", "dagat"], "fact": {"tl": "Ang banca ay may katig sa magkabilang gilid na lumulutang sa tubig, na pumipigil sa makitid na bangka na tumba kahit may alon.", "en": "A banca has outriggers (katig) floating on each side that keep the narrow boat from tipping over, even in waves.", "bis": "Ang banca naay katig sa matag kilid nga molutaw sa tubig, nga makapugong sa nipis nga sakayan nga matumba bisan naay balod."}, "source": "encyclopedia-stable consensus; NRC PS2.B (stability and balance)", "generator": "claude-workflow", "reviewed": false},
  {"id": "bandurria-strings-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "string thickness and pitch", "grades": [5, 6, 7], "terms": ["bandurria", "string instrument", "kuwerdas", "strings", "rondalla", "tunog", "pitch", "manipis", "makapal", "mataas", "mababa", "vibrate", "tingog", "kurdas", "kurog", "habog", "nipis", "baga", "tono"], "fact": {"tl": "Ang bandurria ay tinutugtog sa pamamagitan ng pagpitik sa mga kuwerdas; ang mas manipis at mas hinigpit na kuwerdas ay gumagawa ng mas mataas na tono.", "en": "The bandurria is played by plucking its strings; thinner and tighter strings vibrate faster and make higher-pitched notes.", "bis": "Ang bandurria gitugtog pinaagi sa pagkutaw sa mga kurdas; ang mas nipis ug mas hugot nga kurdas mokurog nga paspas ug mohimo ug mas habog nga tono."}, "source": "encyclopedia-stable consensus; NRC PS4.A (strings and pitch)", "generator": "claude-workflow", "reviewed": false},
  {"id": "banga-clay-pot-g4", "domain": "MATTER", "topic": "clay hardens when fired", "grades": [3, 4, 5], "terms": ["banga", "clay pot", "palayok", "clay", "luwad", "lupa", "fired", "iniluto", "init", "matigas", "pottery", "kulon", "yutang-kolonon", "gahi", "lapok", "kalayo", "luto"], "fact": {"tl": "Ang banga ay gawa sa malambot na luwad na hinuhubog at saka iniluluto sa apoy, kung saan ito tumitigas at nagiging matibay na lalagyan.", "en": "A banga clay pot is shaped from soft clay and then baked in fire, which hardens it into a strong, water-holding container.", "bis": "Ang banga gihimo gikan sa humok nga yutang-kolonon nga giporma ug dayon giluto sa kalayo, diin kini mogahi ug mahimong lig-on nga sudlanan."}, "source": "encyclopedia-stable consensus; NRC PS1.B (irreversible change by heating)", "generator": "claude-workflow", "reviewed": false},
  {"id": "banig-woven-mat-g4", "domain": "LIVING_THINGS", "topic": "mats woven from plant leaves", "grades": [3, 4, 5], "terms": ["banig", "sleeping mat", "woven mat", "pandan", "buri", "tikog", "dahon", "leaves", "plant", "habi", "weave", "banig", "tanom", "habol", "lala", "lara"], "fact": {"tl": "Ang banig ay hinahabi mula sa pinatuyong dahon ng mga halaman tulad ng pandan, buri, o tikog, na pinipilipit at pinagsasalit-salit upang maging matibay na higaan.", "en": "A banig mat is woven from dried plant leaves such as pandan, buri, or tikog, which are split and interlaced into a strong sleeping mat.", "bis": "Ang banig gilala gikan sa giuga nga dahon sa mga tanom sama sa pandan, buri, o tikog, nga gipikas ug gisalapid aron mahimong lig-on nga higdaanan."}, "source": "encyclopedia-stable consensus; DepEd (plant materials we use)", "generator": "claude-workflow", "reviewed": false},
  {"id": "barangay-health-center-g4", "domain": "LIVING_THINGS", "topic": "community health and vaccines", "grades": [3, 4, 5], "terms": ["barangay health center", "health center", "klinika", "bakuna", "vaccine", "kalusugan", "health", "nars", "checkup", "sakit", "gamot", "panglawas", "tambal", "nurse", "timbang", "lawas"], "fact": {"tl": "Sa barangay health center, ang mga sanggol at bata ay binabakunahan at tinitimbang upang mapanatili silang malusog at maiwasan ang mga sakit.", "en": "At the barangay health center, babies and children get vaccines and checkups to keep them healthy and prevent diseases.", "bis": "Sa barangay health center, ang mga masuso ug bata gibakunahan ug gitiman-an aron magpabiling himsog ug malikayan ang mga sakit."}, "source": "encyclopedia-stable consensus; DepEd (health and the body)", "generator": "claude-workflow", "reviewed": false},
  {"id": "barong-pina-fiber-g5", "domain": "LIVING_THINGS", "topic": "piña fiber from pineapple leaves", "grades": [4, 5, 6], "terms": ["barong tagalog", "piña", "pinya", "tela", "hibla", "dahon ng pinya", "pineapple", "pineapple leaf fiber", "cloth", "panapton", "pinya nga panapton", "dahon", "fiber"], "fact": {"tl": "Ang tradisyonal na barong Tagalog ay madalas hinahabi mula sa piña, isang manipis ngunit matibay na hibla na kinukuha sa mga dahon ng halamang pinya.", "en": "The traditional barong Tagalog is often woven from piña, a thin but strong fiber taken from the leaves of the pineapple plant.", "bis": "Ang tradisyonal nga barong Tagalog kasagarang gihabol gikan sa piña, usa ka nipis apan lig-on nga hibla nga gikuha sa mga dahon sa tanom nga pinya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "barquillos-heat-shaping-g4", "domain": "MATTER", "topic": "heat changing batter into crisp wafer", "grades": [3, 4, 5], "terms": ["barquillos", "wafer", "rolled wafer", "init", "kainit", "tigas", "malutong", "batter", "masa", "iginulong", "crisp", "gilukot", "init nga panghimo", "matahum"], "fact": {"tl": "Ang barquillos ay manipis na masa na iniluluto sa mainit na bakal hanggang tumigas, at habang mainit pa ito ay iginugulong para maging malutong na tubo.", "en": "Barquillos is a thin batter cooked on a hot iron until it hardens, and while still hot it is rolled into a crisp tube.", "bis": "Ang barquillos usa ka nipis nga masa nga giluto sa init nga puthaw hangtod mogahi, ug samtang init pa kini gilukot aron mahimong malutong nga tubo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "basin-pail-water-shape-g3", "domain": "MATTER", "topic": "liquids take the shape of their container", "grades": [3, 4], "terms": ["basin", "balde", "pail", "timba", "tubig", "hugis", "lalagyan", "container", "water", "porma", "sudlanan", "planggana", "liquid", "tubig nga porma"], "fact": {"tl": "Kapag ibinuhos ang tubig sa isang batya o balde, kinukuha nito ang hugis ng lalagyan dahil ang likido ay walang sariling porma.", "en": "When water is poured into a basin or pail, it takes the shape of the container because a liquid has no shape of its own.", "bis": "Kon ibubo ang tubig sa usa ka planggana o balde, magkuha kini sa porma sa sudlanan tungod kay ang likido walay kaugalingong porma."}, "source": "AAAS Benchmarks 4D; DepEd G3 Matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "basket-fish-trap-bubu-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "one-way funnel fish trap", "grades": [5, 6, 7], "terms": ["bubu", "bubo", "fish trap", "bitik", "panghuli isda", "kawayan", "bamboo", "salakab", "funnel", "isda", "lit-ag", "pasok", "hari nga lit-ag", "trap"], "fact": {"tl": "Ang bubo ay isang bitag na gawa sa kawayan na may pasukang parang tunel, kaya madaling makapasok ang isda ngunit mahirap na itong makalabas.", "en": "The bubu is a bamboo fish trap with a funnel-shaped entrance, so a fish can swim in easily but cannot find its way back out.", "bis": "Ang bubo usa ka lit-ag nga hinimo sa kawayan nga adunay agianan nga sama sa funnel, busa sayon makasulod ang isda apan lisod na kini makagawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bayong-woven-plant-fiber-g4", "domain": "LIVING_THINGS", "topic": "bayong woven from buri or pandan leaves", "grades": [3, 4, 5], "terms": ["bayong", "woven bag", "buri", "pandan", "dahon", "hinabi", "bag", "supot", "leaves", "buli", "lukay", "dahon nga hinabol", "natural fiber", "bag nga hinabol"], "fact": {"tl": "Ang bayong ay isang bag na hinahabi mula sa pinatuyong dahon ng mga halaman tulad ng buri o pandan, kaya ito ay likas na nabubulok.", "en": "The bayong is a bag woven from the dried leaves of plants such as buri or pandan, so it breaks down naturally over time.", "bis": "Ang bayong usa ka bag nga gihabol gikan sa uga nga dahon sa mga tanom sama sa buri o pandan, busa kini natural nga madunot sa paglabay sa panahon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "beaker-lab-glass-g5", "domain": "MATTER", "topic": "beaker for measuring and holding liquids", "grades": [4, 5, 6, 7], "terms": ["beaker", "baso ng lab", "salamin", "gamit sa laboratoryo", "sukat", "tubig", "likido", "marka", "glass", "laboratory", "sudlanan", "lab", "sukod", "marka sa gilid", "measure"], "fact": {"tl": "Ang beaker ay isang basong gawa sa salamin na may mga markang panukat sa gilid, ginagamit sa laboratoryo para maglagay, magpainit, at magsukat ng likido.", "en": "A beaker is a glass container with measuring marks on the side, used in the laboratory to hold, heat, and roughly measure liquids.", "bis": "Ang beaker usa ka sudlanan nga hinimo sa salamin nga adunay mga marka sa kilid, gamiton sa laboratoryo aron sudlan, painiton, ug sukdon ang likido."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "beam-balance-mass-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "beam balance compares mass", "grades": [4, 5, 6], "terms": ["beam balance", "timbangan", "bigat", "masa", "panimbang", "balanse", "pantay", "mass", "weigh", "timbang", "patas", "timbangan nga sungkod", "weighing", "balance"], "fact": {"tl": "Ang beam balance ay nagsusukat ng masa sa pamamagitan ng paghahambing ng dalawang bagay sa magkabilang dulo hanggang pumantay ang sungkod sa gitna.", "en": "A beam balance measures mass by comparing two objects on its two ends until the beam settles level in the middle.", "bis": "Ang beam balance nagsukod sa masa pinaagi sa pagtandi sa duha ka butang sa duha ka tumoy hangtod nga mopatas ang sungkod sa tunga."}, "source": "AAAS Benchmarks; DepEd G5 Force and Motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "bati-kite-flight-lift-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "how a kite stays aloft on wind", "grades": [5, 6, 7], "terms": ["bati", "saranggola", "kite", "cobra kite", "hangin", "lift", "lumilipad", "tali", "wind", "buga sa hangin", "tangkad", "hangin nga nagtukbal", "tabanog", "string"], "fact": {"tl": "Lumilipad ang saranggola o bati kapag ang hanging tumatama sa nakahilig nitong mukha ay itinutulak ito pataas, habang pinipigilan ito ng tali na huwag tangayin.", "en": "A kite or bati flies when wind striking its tilted face pushes it upward, while the string holds it back so the air can lift it.", "bis": "Ang tabanog o bati molupad kon ang hangin nga motama sa nagharag niini nga nawong moduso niini pataas, samtang ang pisi mopugong niini aron mabuhi kini sa hangin."}, "source": "AAAS Benchmarks 4F; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bibingka-clay-pot-heat-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "baking with heat from above and below", "grades": [4, 5, 6], "terms": ["bibingka", "clay pot", "palayok", "uling", "init", "baga", "rice cake", "kakanin", "lutong init", "coconut leaf", "dahon ng saging", "init sa ibabaw ug ilawom", "charcoal", "baking"], "fact": {"tl": "Niluluto ang bibingka sa palayok na may baga sa ilalim at sa takip sa ibabaw, kaya pantay itong naluluto mula sa init sa dalawang panig.", "en": "Bibingka is baked in a clay pot with hot coals below and on the lid above, so heat from both sides cooks it evenly.", "bis": "Ang bibingka giluto sa kolon nga adunay baga sa ilawom ug sa taklob sa ibabaw, busa patas kini maluto gikan sa init sa duha ka kilid."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "biko-sticky-rice-starch-g5", "domain": "MATTER", "topic": "glutinous rice and coconut milk in biko", "grades": [4, 5, 6], "terms": ["biko", "malagkit", "sticky rice", "glutinous rice", "gata", "coconut milk", "almirol", "starch", "latik", "dikit", "kakanin", "pilit", "lubi nga gata", "asukal", "sweet"], "fact": {"tl": "Ang biko ay gawa sa malagkit na bigas na pinakuluan sa gata at asukal, at ang malagkit ay dumidikit dahil sa uri ng almirol na taglay nito.", "en": "Biko is made from glutinous rice cooked in coconut milk and sugar, and the rice turns sticky because of the special kind of starch it contains.", "bis": "Ang biko hinimo sa pilit nga bugas nga giluto sa gata ug asukal, ug ang pilit modikit tungod sa matang sa almirol nga anaa niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bicol-express-chili-capsaicin-g6", "domain": "LIVING_THINGS", "topic": "chili heat from capsaicin", "grades": [5, 6, 7], "terms": ["bicol express", "sili", "labuyo", "chili", "anghang", "capsaicin", "gata", "coconut milk", "maanghang", "pamaspas", "hari nga halang", "sili nga halang", "spicy", "halang"], "fact": {"tl": "Maanghang ang Bicol Express dahil sa maraming sili na naglalaman ng capsaicin, isang sangkap na pumupukaw sa mga nerbiyo ng dila na parang nasusunog.", "en": "Bicol Express is spicy because of the many chilies, which contain capsaicin, a substance that triggers the tongue's nerves to feel a burning sensation.", "bis": "Ang Bicol Express halang tungod sa daghang sili nga adunay capsaicin, usa ka sangkap nga mopukaw sa mga nerbiyo sa dila aron mobati nga daw nasunog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bicycle-sidecar-wheel-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "wheels reduce friction to move loads", "grades": [4, 5, 6], "terms": ["bisikleta", "padyak", "bicycle", "sidecar", "gulong", "wheel", "friction", "alikabok", "pedal", "ruweda", "ligid", "kuliglig", "andana", "wheel and axle", "rolling"], "fact": {"tl": "Gumagalaw ang bisikletang may sidecar dahil ang mga umiikot na gulong ay nagpapaliit ng friction, kaya mas madaling itulak ang bigat kaysa kaladkarin ito.", "en": "A bicycle with a sidecar moves because its turning wheels reduce friction, making it far easier to roll a load than to drag it.", "bis": "Ang bisikleta nga adunay sidecar molihok tungod kay ang nagtuyok nga mga ligid mokunhod sa friction, busa mas sayon iligid ang gibug-aton kay sa pagguyod niini."}, "source": "AAAS Benchmarks; DepEd G5 Force and Motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "betamax-grilled-blood-protein-g6", "domain": "MATTER", "topic": "blood cooks solid when heated", "grades": [5, 6, 7], "terms": ["betamax", "dugo", "grilled blood", "ihaw", "tigas", "protina", "protein", "coagulate", "init", "namuo", "isaw", "sugba nga dugo", "namuong dugo", "street food", "tinapay"], "fact": {"tl": "Ang betamax ay parisukat na dugo ng manok na pinatigas sa pamamagitan ng pagpapakulo, dahil namumuo ang protina sa dugo kapag pinainit.", "en": "Betamax is a square of chicken blood set firm by boiling, because the protein in blood coagulates and turns solid when heated.", "bis": "Ang betamax usa ka kwadrado nga dugo sa manok nga gipatig-a pinaagi sa pagpabukal, tungod kay ang protina sa dugo namuo ug mahimong gahi kon initon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bilao-winnowing-tray-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "winnowing separates grain by weight and air", "grades": [4, 5, 6], "terms": ["bilao", "tahip", "nagtatahip", "ipa", "bigas", "palay", "hangin", "winnowing tray", "winnow", "separate grain chaff", "lighter heavier", "ginatahop", "nagtahop", "tahop", "humay", "lubog gaan bug-at"], "fact": {"tl": "Ang bilao ay isang lapad na sawali na ginagamit sa pagtahip, kung saan itinatapon-itapon ang bigas sa hangin para tangayin ng hangin ang magaang ipa habang nahuhulog pabalik ang mas mabigat na butil.", "en": "A bilao is a flat woven tray used for winnowing, where grain is tossed in the air so the breeze carries off the light chaff while the heavier grains fall back down.", "bis": "Ang bilao usa ka lapad nga hinabol nga gamit sa pagtahop, diin ilabay ang bugas sa hangin aron madala sa huyohoy ang gaan nga upa samtang mahulog balik ang mas bug-at nga lugas."}, "source": "encyclopedia-stable consensus; NRC PS2 (forces, air resistance)", "generator": "claude-workflow", "reviewed": false},
  {"id": "billiards-collision-energy-transfer-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "billiard ball collision transfers motion", "grades": [6, 7, 8, 9], "terms": ["bilyar", "billiards", "bola", "tama", "banggaan", "collision", "lakas", "enerhiya", "galaw", "momentum", "naipapasa enerhiya", "pinatama", "bola ball cue", "naglihok", "nagbangga", "kusog", "gibanggaan"], "fact": {"tl": "Kapag tinamaan ng gumagalaw na bola ng bilyar ang isa pang bola, naipapasa nito ang lakas ng paggalaw kaya napapahinto ang una habang umaandar naman ang tinamaang bola.", "en": "When a moving billiard ball strikes another ball, it transfers its energy of motion, so the first ball can stop while the struck ball rolls away.", "bis": "Kon ang naglihok nga bola sa bilyar mobunggo sa laing bola, mabalhin niini ang kusog sa paglihok, busa mohunong ang una samtang moligid ang bola nga nabunggoan."}, "source": "NRC PS2.A (motion and forces); AAAS Benchmarks 4F", "generator": "claude-workflow", "reviewed": false},
  {"id": "binagol-taro-dessert-g5", "domain": "LIVING_THINGS", "topic": "taro root stores starchy food for the plant", "grades": [4, 5, 6], "terms": ["binagol", "gabi", "taro", "talyan giant taro", "ugat", "almirol", "starch", "kanin pagkain halaman", "matamis", "imbak pagkain", "tuber root", "gamot", "almidon", "tinubo", "pagkaon tinago", "gamot sa tanom"], "fact": {"tl": "Ang binagol ay matamis na kakanin na gawa sa giniling na giant taro o talyan, isang ugat-halaman na nag-iimbak ng almirol na pagkain para sa halaman, kaya ito malagkit at busog.", "en": "Binagol is a sweet delicacy made from grated giant taro, a root that stores starchy food for the plant, which is why it is sticky and filling.", "bis": "Ang binagol usa ka tam-is nga kalan-on nga hinimo sa gigaling nga giant taro o talyan, usa ka gamot nga tanom nga nagtipig sa almidon nga pagkaon para sa tanom, mao nga pilit kini ug makabusog."}, "source": "encyclopedia-stable consensus; NRC LS1.C (organisms store energy)", "generator": "claude-workflow", "reviewed": false},
  {"id": "binatog-corn-kernels-g4", "domain": "LIVING_THINGS", "topic": "corn kernels are the seeds of the corn plant", "grades": [3, 4, 5], "terms": ["binatog", "mais", "corn", "butil binhi", "kernel seed", "niyog", "puti hominy", "halaman binhi", "tutubo bagong halaman", "lugas mais", "binhi", "liso", "tubo", "binhi sa mais"], "fact": {"tl": "Ang binatog ay nilagang butil ng puting mais na sinabawan ng gadgad na niyog, at ang bawat butil ay isang binhi na pwedeng tumubo at maging bagong halaman ng mais.", "en": "Binatog is boiled white corn kernels topped with grated coconut, and each kernel is a seed that could sprout into a new corn plant.", "bis": "Ang binatog mao ang linat-an nga lugas sa puti nga mais nga sangkapan ug kinudkod nga lubi, ug ang matag lugas usa ka binhi nga mahimong motubo og bag-ong tanom sa mais."}, "source": "encyclopedia-stable consensus; NRC LS1.B (reproduction, seeds)", "generator": "claude-workflow", "reviewed": false},
  {"id": "binignit-coconut-stew-heat-g5", "domain": "MATTER", "topic": "boiling softens root crops by heat", "grades": [4, 5, 6], "terms": ["binignit", "ginataang halo-halo", "coconut milk", "gata", "saging kamote", "ube root crop", "lumambot init", "boiling softens", "niluluto pakulo", "sago landang", "gilat-an", "humok init", "naluto", "lat-an", "humok tungod sa kainit", "gamot nga tanom"], "fact": {"tl": "Ang binignit ay matamis na nilagang ginataan na may saging, kamote, at ube, kung saan pinapakulo ng init ang mga ugat-halaman para lumambot at maging madaling kainin.", "en": "Binignit is a sweet coconut-milk stew of banana, sweet potato, and yam, where heat from boiling softens the firm root crops so they become easy to eat.", "bis": "Ang binignit usa ka tam-is nga ginat-ang gisagol nga saging, kamote, ug ube, diin ang kainit sa pagpabukal mopahumok sa lig-on nga mga gamot nga tanom aron sayon nang kan-on."}, "source": "encyclopedia-stable consensus; NRC PS3.B (energy transfer by heat)", "generator": "claude-workflow", "reviewed": false},
  {"id": "boat-anchor-friction-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "an anchor holds a boat using weight and friction", "grades": [5, 6, 7], "terms": ["angkla", "anchor", "bangka boat", "bigat", "lubog", "kalawit", "humila ilalim", "friction kuskos", "pumipigil galaw", "agos hangin", "timbang", "ankla", "gibug-aton", "bug-at", "kumkom sa ilawom", "pugong sa bangka"], "fact": {"tl": "Ang angkla ay mabigat na bakal na ibinababa sa ilalim ng tubig, at ang bigat nito at ang pagkalawit sa pusod ng dagat ang pumipigil sa bangka para hindi ito tangayin ng agos o hangin.", "en": "An anchor is a heavy metal piece lowered to the seabed, and its weight plus its grip on the bottom keep the boat from drifting away with the current or wind.", "bis": "Ang angkla usa ka bug-at nga puthaw nga ibutang sa ilawom sa tubig, ug ang gibug-aton niini ug ang pagkupot sa salog sa dagat maoy mopugong sa bangka aron dili madala sa sulog o hangin."}, "source": "NRC PS2.A (forces, friction); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "boat-paddle-third-class-lever-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "a paddle pushes water back to move a boat forward", "grades": [6, 7, 8], "terms": ["sagwan", "paddle", "bangka boat", "tubig pagtulak", "itinutulak likod", "action reaction", "pasulong", "naglalayag", "lakas paggalaw", "bugsay", "nagtulak tubig", "pagduso", "molihok unahan", "tultol sa tubig", "paatras"], "fact": {"tl": "Kapag itinutulak pabalik ng sagwan ang tubig, ipinapasulong nito ang bangka dahil ang pagtulak sa tubig ay sumasagot ng pagtulak na pasulong sa bangka.", "en": "When a paddle pushes water backward, it drives the boat forward, because pushing on the water makes the water push the boat forward in return.", "bis": "Kon ang bugsay moduso sa tubig paatras, mopaduso kini sa bangka paunahan, kay ang pagduso sa tubig motubag ug pagduso sa bangka paunahan."}, "source": "NRC PS2.A (Newton's third law); AAAS Benchmarks 4F", "generator": "claude-workflow", "reviewed": false},
  {"id": "boat-sail-wind-power-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "a sail catches wind to move a boat", "grades": [4, 5, 6, 7], "terms": ["layag", "sail", "bangka boat", "hangin lakas", "wind power", "itinutulak hangin", "naglalayag", "triangular sail", "enerhiya hangin", "tela", "gilayag", "hangin nagtulak", "kusog sa hangin", "naglawig", "panapton"], "fact": {"tl": "Ang layag ay malapad na tela na humuhuli ng hangin, at kapag tumama ang hangin dito, itinutulak nito ang bangka kaya nakakagalaw ito nang hindi kailangan ng makina.", "en": "A sail is a wide cloth that catches the wind, and when wind pushes against it, the wind drives the boat forward without needing any engine.", "bis": "Ang layag usa ka lapad nga panapton nga modakop sa hangin, ug kon ang hangin moduso niini, mopaduso kini sa bangka aron makalihok kini nga walay makina."}, "source": "NRC PS3 (energy from wind); AAAS Benchmarks 8C", "generator": "claude-workflow", "reviewed": false},
  {"id": "boiled-peanuts-legume-g5", "domain": "LIVING_THINGS", "topic": "peanuts are seeds of a legume that grow underground", "grades": [4, 5, 6], "terms": ["mani", "peanut", "nilagang mani", "boiled peanuts", "binhi seed", "legume gisantes", "tumutubo lupa", "ilalim ng lupa", "ugat", "protein pagkain", "buto mani", "liso", "ilawom yuta", "binhi", "motubo sa ilawom"], "fact": {"tl": "Ang mani ay binhi ng isang halamang-gisantes na kakaiba dahil tumutubo ang bunga nito sa ilalim ng lupa, at mayaman ito sa protina na nagpapalakas ng katawan.", "en": "Peanuts are the seeds of a legume plant that is unusual because its pods grow underground, and they are rich in protein that helps build the body.", "bis": "Ang mani mao ang binhi sa usa ka tanom nga legume nga talagsaon kay ang bunga niini motubo sa ilawom sa yuta, ug dato kini sa protina nga makapalig-on sa lawas."}, "source": "encyclopedia-stable consensus; NRC LS1.C (food and nutrients)", "generator": "claude-workflow", "reviewed": false},
  {"id": "bolo-knife-wedge-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "a sharp blade is a wedge that concentrates force", "grades": [5, 6, 7], "terms": ["bolo", "itak", "knife", "matalim", "wedge", "talim", "puwersa", "manipis hiwa", "naghahati", "simple machine", "kahoy putol", "hait", "talinis", "puwersa gipundok", "pang-utol", "sulab sa bolo"], "fact": {"tl": "Ang bolo ay matalim na itak na isang uri ng wedge, kung saan ipinipook ng manipis na talim ang puwersa sa isang makitid na guhit para madaling makahiwa o makaputol.", "en": "A bolo is a sharp blade that works as a wedge, where the thin edge concentrates your pushing force onto a narrow line so it can cut or chop easily.", "bis": "Ang bolo usa ka hait nga sundang nga usa ka matang sa wedge, diin ang nipis nga sulab mopundok sa imong kusog ngadto sa pig-ot nga linya aron sayon mohiwa o moputol."}, "source": "NRC PS2.A (forces); AAAS Benchmarks 8B (simple machines)", "generator": "claude-workflow", "reviewed": false},
  {"id": "bolo-sharpening-friction-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "sharpening grinds metal away by friction", "grades": [5, 6, 7], "terms": ["hasa", "sharpening stone", "bato", "itak bolo", "talim", "kuskos friction", "natanggal metal", "humait", "pagkiskis", "naglinis talim", "baid", "gibaid", "kuskos puthaw", "mohait sa sulab", "gansang"], "fact": {"tl": "Kapag inihahasa ang bolo sa magaspang na bato, inaalis ng kuskusan ang manipis na piraso ng metal sa talim kaya ito humihigpit at humihait.", "en": "When a bolo is rubbed against a rough sharpening stone, friction grinds tiny bits of metal off the edge, making it thinner and sharper.", "bis": "Kon baidon ang bolo sa gansang nga bato, ang pagkiskis mokuha sa gagmay nga tipik sa puthaw gikan sa sulab, mao nga mahimo kining nipis ug hait."}, "source": "NRC PS2.A (friction); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "boxing-gloves-cushion-force-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "padding spreads out and softens an impact force", "grades": [6, 7, 8], "terms": ["guwantes boksing", "boxing gloves", "padding", "nagbibigay sapin", "nagpapahaba oras", "impact force", "tama suntok", "pinapahina", "cushion bumbon", "nakakaiwas pinsala", "sakit", "espongha", "gipalumo", "molugway sa oras", "mopagaan sa hampak"], "fact": {"tl": "Ang makapal na sapin ng guwantes sa boksing ay nagpapahaba sa oras ng pagtama ng suntok, kaya humihina ang puwersa sa bawat sandali at nababawasan ang pinsala.", "en": "The thick padding in boxing gloves stretches out the time of a punch's impact, which lowers the force at each instant and reduces injury.", "bis": "Ang baga nga sapin sa guwantes sa boksing molugway sa oras sa pagtugpa sa sumbag, mao nga mokunhod ang kusog sa matag gutlo ug makunhuran ang kadaot."}, "source": "NRC PS2.A (force, impulse); AAAS Benchmarks 4F", "generator": "claude-workflow", "reviewed": false},
  {"id": "brazo-de-mercedes-egg-foam-g6", "domain": "MATTER", "topic": "beaten egg whites trap air into a foam", "grades": [5, 6, 7], "terms": ["brazo de mercedes", "puti itlog", "egg white", "meringue", "binati", "nahuli hangin", "foam bula", "bumukol lumambot", "lumalaki binati", "luto hurno", "puti sa itlog", "gibatil", "nadakpan hangin", "bula", "milukot"], "fact": {"tl": "Ang brazo de mercedes ay gawa sa pinalong puti ng itlog, kung saan habang binabati ay nahuhuli ng tela-telang protina ang maraming maliliit na bula ng hangin kaya ito lumalambot at lumalaki.", "en": "Brazo de Mercedes is made from beaten egg whites, where whipping traps many tiny air bubbles in the stretchy protein, making a light, puffy foam.", "bis": "Ang brazo de mercedes hinimo sa gibatil nga puti sa itlog, diin samtang gibatil madakpan sa unat-unat nga protina ang daghang gagmayng bula sa hangin, mao nga mahimong gaan ug burot nga bula."}, "source": "encyclopedia-stable consensus; NRC PS1.A (mixtures, gases)", "generator": "claude-workflow", "reviewed": false},
  {"id": "bubo-fish-trap-g5", "domain": "LIVING_THINGS", "topic": "a funnel fish trap lets fish in but not out", "grades": [4, 5, 6], "terms": ["bubo", "bubu", "fish trap", "panghuli isda", "kawayan funnel", "pasok labas", "nahuhuli isda", "pangisda gear", "tilos pasukan", "sapa ilog", "panakop isda", "lit-ag isda", "kawayan", "mosulod dili makagawas"], "fact": {"tl": "Ang bubo ay tradisyunal na bitag na yari sa kawayan na may parang-funnel na pasukan, kaya madaling makapasok ang isda ngunit mahirap nang makalabas, isang matalinong paraan ng panghuhuli.", "en": "A bubo is a traditional bamboo fish trap with a funnel-shaped opening, so fish can swim in easily but find it hard to swim back out, a clever way of catching them.", "bis": "Ang bubo usa ka tradisyonal nga lit-ag nga hinimo sa kawayan nga adunay sama-funnel nga pultahan, busa sayon mosulod ang isda apan lisod na mogawas, usa ka maalamon nga paagi sa pagpanakop."}, "source": "encyclopedia-stable consensus; DepEd (indigenous technology, livelihood)", "generator": "claude-workflow", "reviewed": false},
  {"id": "buchi-sesame-ball-frying-g5", "domain": "MATTER", "topic": "frying heats moisture into steam that puffs the ball", "grades": [5, 6, 7], "terms": ["buchi", "sesame ball", "linga", "malagkit rice", "pinirito", "frying init", "lumobo hollow", "singaw steam", "tubig naging singaw", "bumukol", "mantika mainit", "pagprito", "namurot", "naluto", "alisngaw", "nibukol", "mantika init"], "fact": {"tl": "Ang buchi ay bilog na malagkit na kakanin na binalutan ng linga, at kapag pinirito ito sa mainit na mantika, nagiging singaw ang tubig sa loob na siyang nagpapabukol at nagpapahungkag nito.", "en": "Buchi is a round glutinous rice ball coated in sesame seeds, and when it is fried in hot oil, the water inside turns to steam that puffs it up and makes it hollow.", "bis": "Ang buchi usa ka lingin nga pilit nga kalan-on nga gisapaw sa linga, ug kon iprito kini sa init nga mantika, mahimong alisngaw ang tubig sa sulod nga maoy mopabukol ug mopahawan niini."}, "source": "encyclopedia-stable consensus; NRC PS1.A (states of matter, evaporation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "buko-pandan-coconut-g4", "domain": "LIVING_THINGS", "topic": "buko is the soft meat of a young coconut", "grades": [3, 4, 5], "terms": ["buko", "young coconut", "niyog", "pandan", "malambot laman", "coconut meat", "tubig buko", "halaman bunga", "matamis", "berde niyog", "lubi batan-on", "humok unod", "tubig sa lubi", "bunga sa lubi", "kopra"], "fact": {"tl": "Ang buko ay batang niyog na may malambot at malasang laman at malinaw na tubig, na nagiging matigas na kopra kapag tumanda ang niyog.", "en": "Buko is a young coconut with soft, jelly-like meat and clear water inside, which hardens into firm copra as the coconut matures.", "bis": "Ang buko mao ang batan-on nga lubi nga adunay humok ug malasa nga unod ug tin-aw nga tubig, nga mahimong gahi nga kopras kon motigulang na ang lubi."}, "source": "encyclopedia-stable consensus; NRC LS1.B (plant growth, fruit)", "generator": "claude-workflow", "reviewed": false},
  {"id": "bulalo-marrow-bone-g6", "domain": "LIVING_THINGS", "topic": "bone marrow inside bones makes blood cells", "grades": [6, 7, 8], "terms": ["bulalo", "utak buto", "bone marrow", "buto baka", "marrow soup", "sabaw", "dugo cells", "gumagawa dugo", "buto laman", "nilaga", "utok sa bukog", "bukog", "naghimo dugo", "linat-an"], "fact": {"tl": "Ang bulalo ay nilagang buto ng baka na may utak ng buto sa loob, at sa tunay na hayop, ang malambot na utak ng buto ang gumagawa ng mga selula ng dugo.", "en": "Bulalo is boiled beef shank with marrow inside the bone, and in a living animal that soft marrow is where blood cells are made.", "bis": "Ang bulalo mao ang linat-an nga bukog sa baka nga adunay utok sa bukog sa sulod, ug sa buhi nga hayop, ang humok nga utok sa bukog mao ang naghimo sa mga selula sa dugo."}, "source": "NRC LS1.A (structure and function); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bungkaka-buzzer-bamboo-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "a bamboo buzzer makes sound by vibrating", "grades": [4, 5, 6], "terms": ["bungkaka", "balingbing", "bamboo buzzer", "kawayan", "tunog vibration", "nanginginig", "sound hangin", "tugtugin", "yumayanig", "nagvibrate", "instrumento", "kawayan tugtog", "tingog", "nag-uyog", "tunog gikan vibration"], "fact": {"tl": "Ang bungkaka ay instrumentong kawayan na may biyak na dulo, at kapag ipinukpok ito sa palad, nanginginig ang mga biyak na bahagi at gumagawa ng nagbu-buzz na tunog.", "en": "The bungkaka is a bamboo instrument with a split end, and when struck against the palm, the split prongs vibrate and make a buzzing sound.", "bis": "Ang bungkaka usa ka instrumento nga kawayan nga adunay liki nga tumoy, ug kon ihampak kini sa palad, mo-uyog ang liki nga mga bahin ug mohimog nag-buzz nga tingog."}, "source": "NRC PS4.A (waves, sound from vibration); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "buntal-hat-fiber-weaving-g6", "domain": "LIVING_THINGS", "topic": "buntal fiber from buri palm is woven into hats", "grades": [5, 6, 7], "terms": ["buntal", "buntal hat", "buri palm", "sombrero", "hibla fiber", "tangkay dahon", "hinabing", "halaman fiber", "natural", "telang gawa halaman", "buri", "buntal kalo", "lanot", "gihabol", "fiber gikan tanom", "tangkay sa dahon"], "fact": {"tl": "Ang buntal na sombrero ay hinahabi mula sa pinong hibla na kinukuha sa tangkay ng dahon ng punong buri, na nagpapakita kung paano gawing matibay na tela ang likas na hibla ng halaman.", "en": "A buntal hat is woven from fine fibers stripped from the leaf stalk of the buri palm, showing how natural plant fibers can be turned into strong cloth.", "bis": "Ang buntal nga kalo gihabol gikan sa pino nga lanot nga gikuha sa tangkay sa dahon sa buri nga palmera, nga nagpakita kon unsaon paghimo ang natural nga lanot sa tanom nga lig-on nga panapton."}, "source": "encyclopedia-stable consensus; NRC LS1.A (plant structures, materials)", "generator": "claude-workflow", "reviewed": false},
  {"id": "burnay-jar-clay-firing-g6", "domain": "MATTER", "topic": "firing clay in a kiln hardens it into pottery", "grades": [5, 6, 7], "terms": ["burnay", "clay jar", "putik luwad", "palayok", "hurno apoy", "tumigas init", "pottery", "natuyo", "init pagbago", "garapon", "tibod", "nagbago hindi na balik", "yutang kulonon", "gisunog", "migahi", "kulon"], "fact": {"tl": "Ang burnay ay tradisyunal na garapong-luwad ng Ilocos na hinuhubog mula sa basang putik, at kapag iniihaw sa napakainit na hurno, tumitigas ito nang permanente at hindi na muling lumalambot sa tubig.", "en": "A burnay is a traditional Ilocos clay jar shaped from wet clay, and when fired in a very hot kiln it hardens permanently and will no longer soften in water.", "bis": "Ang burnay usa ka tradisyonal nga tibod nga kulonon sa Ilocos nga gikulit gikan sa basa nga lapok, ug kon sugnoran sa init kaayo nga hudno mogahi kini nga permanente ug dili na mahumok pag-usab sa tubig."}, "source": "NRC PS1.B (irreversible chemical change by heat); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "burong-mangga-pickling-g6", "domain": "MATTER", "topic": "salt and brine preserve unripe mango by stopping spoilage", "grades": [5, 6, 7], "terms": ["burong mangga", "buro", "pickled mango", "asin brine", "hilaw mangga", "preserve", "hindi nabubulok", "asim", "bakterya", "pinapatagal", "imbak", "hilaw na mangga", "asin", "giburo", "dili madunot", "mahimong aslom", "tipig pagkaon"], "fact": {"tl": "Ang burong mangga ay hilaw na manggang inilublob sa maalat na tubig, kung saan pinipigilan ng asin ang paglaki ng bakteryang nagpapabulok kaya tumatagal ang prutas.", "en": "Burong mangga is unripe mango soaked in salty brine, where the salt stops the growth of spoilage bacteria so the fruit can be kept much longer.", "bis": "Ang burong mangga mao ang hilaw nga mangga nga gituslob sa parat nga tubig, diin ang asin mopugong sa pagtubo sa bakterya nga makadunot, mao nga molungtad ang prutas."}, "source": "encyclopedia-stable consensus; NRC LS1 (microbes); DepEd (food preservation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "caldereta-cooking-protein-g6", "domain": "MATTER", "topic": "slow simmering breaks down tough meat into tender meat", "grades": [5, 6, 7], "terms": ["kaldereta", "caldereta", "beef stew", "karne baka", "lumambot luto", "simmer init", "collagen", "matigas naging malambot", "nilaga matagal", "kunekta tisyu", "litson", "nilutong baka", "humok karne", "gilat-an", "humok tungod init", "dugay nga luto"], "fact": {"tl": "Ang kaldereta ay matagal na nilutong karne ng baka, at sa mahabang mabagal na pagluluto, ang matitigas na ugat-laman ay unti-unting nadudurog ng init kaya lumalambot ang karne.", "en": "Caldereta is beef simmered for a long time, and in slow cooking the tough connective tissue is gradually broken down by heat so the meat turns tender.", "bis": "Ang kaldereta mao ang dugay nga gilat-ang karne sa baka, ug sa hinay nga pagluto, ang gahi nga unod-ugat hinay-hinayng madugmok sa kainit, mao nga mahumok ang karne."}, "source": "NRC PS3.B (heat and matter change); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "camote-cue-stick-g4", "domain": "MATTER", "topic": "caramelizing sugar on sweet potato", "grades": [4, 5, 6], "terms": ["camote cue", "kamote", "sweet potato", "asukal", "kalamay", "caramel", "caramelize", "pagprito", "iprito", "tunaw na asukal", "natunaw", "natunaw nga asukal", "matam-is nga camote", "brown nga asukal"], "fact": {"tl": "Ang camote cue ay piniritong hiwa ng kamote na binalutan ng asukal na natunaw at naging kayumangging caramel dahil sa init.", "en": "Camote cue is fried slices of sweet potato coated in sugar that melts and turns into brown caramel because of the heat.", "bis": "Ang camote cue mao ang giprito nga hiwa sa kamote nga gibutangan ug asukal nga natunaw ug nahimong brown nga caramel tungod sa kainit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "camote-fritter-round-g4", "domain": "LIVING_THINGS", "topic": "sweet potato as a root crop", "grades": [3, 4, 5], "terms": ["kamote", "camote", "sweet potato", "ugat", "root crop", "ugat na pananim", "lupa", "tubo sa ilalim", "lamang-ugat", "gamot", "ugat nga tanom", "halaman", "starchy"], "fact": {"tl": "Ang kamote ay isang ugat na pananim na lumalaki sa ilalim ng lupa at puno ng almirol na nagbibigay ng enerhiya sa katawan.", "en": "The sweet potato is a root crop that grows underground and is full of starch, which gives the body energy.", "bis": "Ang kamote usa ka ugat nga tanom nga nagatubo ilawom sa yuta ug puno sa almirol nga naghatag ug kusog sa lawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "capacity-graduated-pour-compare-g3", "domain": "MATTER", "topic": "measuring volume of liquids", "grades": [3, 4, 5], "terms": ["kapasidad", "capacity", "dami ng likido", "volume", "sukat", "panukat", "graduated cylinder", "litro", "mililitro", "milliliter", "pagsukat", "sukdon", "sukod sa tubig", "ibubo", "ihuwad", "dami sa likido"], "fact": {"tl": "Ang kapasidad ay kung gaano karaming likido ang kayang lamanin ng isang lalagyan, at sinusukat ito sa litro o mililitro gamit ang panukat na may marka.", "en": "Capacity is how much liquid a container can hold, and it is measured in liters or milliliters using a marked measuring tool.", "bis": "Ang kapasidad mao ang gidaghanon sa likido nga masulod sa usa ka sudlanan, ug gisukod kini sa litro o mililitro gamit ang panukod nga adunay marka."}, "source": "DepEd MATATAG Science; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "carabao-plow-muddy-paddy-g4", "domain": "LIVING_THINGS", "topic": "carabao as a draft animal", "grades": [3, 4, 5], "terms": ["kalabaw", "carabao", "water buffalo", "araro", "plow", "bukid", "palayan", "rice field", "hayop sa bukid", "pagsasaka", "draft animal", "putik", "lusak", "magsasaka", "kabaw", "daro", "humay", "lapok", "mananap"], "fact": {"tl": "Ang kalabaw ay malakas na hayop na ginagamit ng mga magsasaka sa pag-araro ng palayan dahil kaya nitong humila ng bigat sa maputik na lupa.", "en": "The carabao is a strong animal that farmers use to plow rice fields because it can pull heavy loads through muddy ground.", "bis": "Ang kabaw usa ka kusgan nga mananap nga gigamit sa mga mag-uuma sa pagdaro sa humayan kay makahimo kini sa pagbira sa bug-at sa lapok nga yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "carabao-cooling-mud-g5", "domain": "LIVING_THINGS", "topic": "carabao wallowing to cool down", "grades": [4, 5, 6], "terms": ["kalabaw", "carabao", "water buffalo", "lublob", "wallow", "putik", "lusak", "lapok", "pampalamig", "init", "pawis", "kaunti ang pawisan", "naglublob", "naglunang", "temperatura ng katawan", "init sa lawas", "kabaw"], "fact": {"tl": "Naglulublob ang kalabaw sa putik upang lumamig dahil kakaunti ang pawis nitong glandula, kaya't ang basang putik ang tumutulong na ibaba ang init ng katawan nito.", "en": "A carabao wallows in mud to cool off because it has few sweat glands, so the wet mud helps lower its body heat.", "bis": "Naglunang ang kabaw sa lapok aron mobugnaw kay gamay ra ang singot niini, mao nga ang basa nga lapok ang nagtabang sa pagpaubos sa kainit sa lawas niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cassava-cake-slice-g5", "domain": "LIVING_THINGS", "topic": "cassava root and removing its toxin", "grades": [5, 6, 7], "terms": ["kamoteng kahoy", "cassava", "kamoteng-kahoy", "balinghoy", "ugat", "root crop", "almirol", "starch", "kakanin", "cassava cake", "lason", "cyanide", "luto", "kailangang lutuin", "balanghoy", "ugat nga tanom", "hilo", "lutoon"], "fact": {"tl": "Ang cassava o kamoteng-kahoy ay isang ugat na pananim na masarap gawing kakanin, ngunit kailangan itong lutuing mabuti dahil ang hilaw na cassava ay may likas na lason.", "en": "Cassava is a root crop that makes a tasty cake, but it must be cooked well because raw cassava contains a natural poison.", "bis": "Ang cassava o balanghoy usa ka ugat nga tanom nga lami himoon nga kakanin, apan kinahanglan kini lutoon ug maayo kay ang hilaw nga cassava adunay natural nga hilo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cattle-tethered-grazing-g3", "domain": "LIVING_THINGS", "topic": "cattle as grass-eating herbivores", "grades": [3, 4, 5], "terms": ["baka", "cattle", "cow", "damo", "grass", "manginginain", "herbivore", "kumakain ng damo", "pastol", "graze", "halamang-kanin", "tanim", "tinali", "naghahalaman", "nanginginain", "mananap nga mokaon ug sagbot", "sagbot", "vaca"], "fact": {"tl": "Ang baka ay isang herbivore o hayop na kumakain lamang ng halaman, kaya't ito ay nanginginain ng damo sa parang buong araw.", "en": "Cattle are herbivores, animals that eat only plants, so they graze on grass in the field all day.", "bis": "Ang baka usa ka herbivore o mananap nga mokaon lang ug tanom, mao nga magsabsab kini ug sagbot sa sibsibanan tibuok adlaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "chalk-stick-g4", "domain": "MATTER", "topic": "chalk made of calcium carbonate", "grades": [4, 5, 6], "terms": ["tisa", "chalk", "yeso", "calcium carbonate", "bato", "mineral", "limestone", "apog", "pisara", "pagsusulat", "natutunaw sa asido", "marka", "alabok", "abog", "yeso nga isulat", "calcium", "puti nga tisa"], "fact": {"tl": "Ang tisa ay gawa sa calcium carbonate, isang malambot na mineral mula sa bato na nag-iiwan ng puting marka kapag inihihilis sa pisara.", "en": "Chalk is made of calcium carbonate, a soft mineral from rock that leaves a white mark when dragged across a board.", "bis": "Ang tisa hinimo sa calcium carbonate, usa ka humok nga mineral gikan sa bato nga magbilin ug puti nga marka kung ipangguhit sa pisara."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "champorado-chocolate-rice-g4", "domain": "MATTER", "topic": "starch thickening as rice cooks", "grades": [4, 5, 6], "terms": ["champorado", "tsamporado", "malagkit", "rice porridge", "kakaw", "tablea", "cocoa", "almirol", "starch", "lumalapot", "thicken", "lugaw", "init", "luto", "namamaga ang bigas", "nilugaw", "nilapot", "nilung-ag", "gata sa kakaw"], "fact": {"tl": "Sa pagluluto ng champorado, sumisipsip ng tubig at namamaga ang malagkit na bigas, kaya't lumalapot ang lugaw dahil sa almirol nito.", "en": "As champorado cooks, the sticky rice soaks up water and swells, so the porridge thickens because of its starch.", "bis": "Sa pagluto sa champorado, mosuyop ug tubig ug moburos ang pilit nga bugas, mao nga molapot ang lugaw tungod sa almirol niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "charcoal-making-mound-g6", "domain": "MATTER", "topic": "making charcoal by heating wood without air", "grades": [6, 7, 8], "terms": ["uling", "charcoal", "kahoy", "wood", "init na walang hangin", "pyrolysis", "karbon", "carbon", "tubig na nawawala", "usok", "gibo nga uling", "sunog", "walang oxygen", "pinainit", "panggatong", "fuel", "gisunog nga kahoy", "abo"], "fact": {"tl": "Ang uling ay gawa sa kahoy na pinainit nang matagal sa loob ng tinakpang bunton na kulang sa hangin, kaya't natitira ang halos purong karbon na mabuting panggatong.", "en": "Charcoal is made by heating wood for a long time inside a covered mound with little air, leaving behind nearly pure carbon that burns well as fuel.", "bis": "Ang uling hinimo gikan sa kahoy nga gipainit ug dugay sulod sa tabunan nga tapok nga kulang sa hangin, mao nga mabilin ang halos puro nga karbon nga maayong igsugnod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "chicharon-pork-rind-g6", "domain": "MATTER", "topic": "frying puffs pork skin into a crisp", "grades": [5, 6, 7], "terms": ["chicharon", "tsitsaron", "balat ng baboy", "pork rind", "pork skin", "prito", "deep fry", "namumuti", "namumutok", "kumakalabog", "tubig na sumingaw", "collagen", "malutong", "crispy", "init na mantika", "puffed", "namula", "giprito nga panit"], "fact": {"tl": "Ang chicharon ay nagiging malutong dahil kapag iprinito ang balat ng baboy, sumisingaw ang tubig sa loob nito at namumutok ito na nagiging mabula at matigas.", "en": "Chicharon becomes crunchy because when pork skin is fried, the water inside it turns to steam and puffs it up into a light, crisp solid.", "bis": "Ang chicharon mahimong malutong kay kung iprito ang panit sa baboy, mosingaw ang tubig sulod niini ug moburot kini nga mahimong magaan ug malutong."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "chicken-inasal-quarter-g5", "domain": "MATTER", "topic": "cooking changes meat by heat", "grades": [4, 5, 6], "terms": ["inasal", "chicken inasal", "manok", "chicken", "ihaw", "grill", "init", "luto", "protina", "protein", "nagbabago ang kulay", "namula", "nagiging puti ang laman", "uling", "baga", "pagluluto", "giihaw", "sinugba", "init sa baga"], "fact": {"tl": "Kapag iniihaw ang chicken inasal sa baga, ang init ay nagpapabago sa protina ng manok kaya't nagiging matigas, puti, at ligtas nang kainin ang laman.", "en": "When chicken inasal is grilled over coals, the heat changes the chicken's protein so the meat becomes firm, white, and safe to eat.", "bis": "Kung sugbahon ang chicken inasal sa baga, ang kainit magbag-o sa protina sa manok mao nga mahimong gahi, puti, ug luwas na kan-on ang unod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "child-vaccination-scene-g6", "domain": "LIVING_THINGS", "topic": "how vaccines protect the body", "grades": [5, 6, 7], "terms": ["bakuna", "vaccine", "vaccination", "pagpapabakuna", "sakit", "disease", "depensa", "immune system", "resistensya", "antibodies", "germ", "mikrobyo", "proteksyon", "naghahanda ang katawan", "bata", "iniksyon", "turok", "panalipod", "bakuna sa sakit"], "fact": {"tl": "Ang bakuna ay nagsasanay sa depensa ng katawan na kilalanin ang isang sakit nang maaga, kaya't handa na itong lumaban kung dumating ang tunay na mikrobyo.", "en": "A vaccine trains the body's defenses to recognize a disease ahead of time, so it is ready to fight off the real germ if it arrives.", "bis": "Ang bakuna nagbansay sa depensa sa lawas nga makaila sa usa ka sakit nga sayo, mao nga andam na kini makigbatok kung moabot ang tinuod nga mikrobyo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "chinese-garter-jump-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "elastic stretch and restoring force", "grades": [4, 5, 6], "terms": ["chinese garter", "garter", "goma", "elastic", "rubber band", "banat", "stretch", "nakakaunat", "elasticity", "lukso", "jump", "bumabalik sa dati", "puwersa", "naninipa", "naghigayon", "nag-unat", "bumalik", "tension", "naunat nga goma"], "fact": {"tl": "Kapag inuunat ang goma sa Chinese garter, naiimbak dito ang puwersa kaya't bumabalik ito sa dating haba pagbitiw, isang katangiang tinatawag na elasticity.", "en": "When the rubber band in Chinese garter is stretched, it stores force and snaps back to its original length when released, a property called elasticity.", "bis": "Kung unaton ang goma sa Chinese garter, matipigan niini ang kusog mao nga mobalik kini sa orihinal nga gitas-on kung buhian, usa ka kinaiya nga gitawag elasticity."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "choking-help-response-g6", "domain": "LIVING_THINGS", "topic": "choking blocks the airway", "grades": [5, 6, 7], "terms": ["nabulunan", "choking", "naharang", "airway", "lalamunan", "windpipe", "trachea", "hangin", "oxygen", "hindi makahinga", "Heimlich", "abdominal thrust", "tulong", "first aid", "naharang ang daanan ng hangin", "nakahap", "naluy-an", "pag-ginhawa", "daanan sa hangin"], "fact": {"tl": "Ang pagkabulunan ay nangyayari kapag may pagkain na humaharang sa daanan ng hangin, kaya't kailangan ng mabilis na tulong upang muling makahinga ang tao.", "en": "Choking happens when food blocks the airway, so quick help is needed so the person can breathe again.", "bis": "Ang pagkahap mahitabo kung adunay pagkaon nga makababag sa agianan sa hangin, mao nga kinahanglan ang paspas nga tabang aron makaginhawa pag-usab ang tawo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "coconut-husking-spike-g5", "domain": "LIVING_THINGS", "topic": "coconut husk protects the seed", "grades": [4, 5, 6], "terms": ["niyog", "coconut", "bunot", "husk", "balat", "fiber", "buko", "binhi", "seed", "proteksyon", "makapal na balat", "lihia", "coir", "buhok ng niyog", "lubi", "bulongon", "panit sa lubi", "binhi nga gipanalipdan", "makapal nga bunot"], "fact": {"tl": "Ang makapal at himaymay na bunot ng niyog ay nagsisilbing proteksyon sa binhi sa loob, kaya't kaya nitong lumutang sa dagat at tumubo sa malayong baybayin.", "en": "The thick, fibrous husk of a coconut protects the seed inside, which is why it can float across the sea and sprout on a faraway shore.", "bis": "Ang baga ug lanot nga bunot sa lubi nagsilbi nga panalipod sa binhi sa sulod, mao nga makalutaw kini sa dagat ug motubo sa layo nga baybayon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cornick-fried-corn-g4", "domain": "MATTER", "topic": "frying corn kernels changes them", "grades": [4, 5, 6], "terms": ["cornick", "mais", "pinirito", "sinangag na mais", "corn kernel", "buwad nga mais", "giprito nga mais", "fried corn", "almirol", "starch", "init", "kainit"], "fact": {"tl": "Ang cornick ay butil ng mais na pinirito hanggang tumigas at kumalansing, dahil tinatanggal ng init ang tubig sa loob ng butil.", "en": "Cornick is corn kernels fried until hard and crunchy, because the heat drives the water out of each kernel.", "bis": "Ang cornick mao ang lugas sa mais nga giprito hangtod magahi ug magkalanog, kay ang kainit nagpagawas sa tubig sulod sa lugas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "crayons-wax-color-g3", "domain": "MATTER", "topic": "crayons are colored wax that melts", "grades": [3, 4, 5], "terms": ["crayon", "krayola", "kandila", "wax", "kolor", "pintura", "kulay", "matunaw", "natunaw", "matunaw ang kandila", "pigment", "kolorado"], "fact": {"tl": "Ang krayola ay gawa sa pinakuluang kandila o wax na hinaluan ng kulay, at lumalambot o natutunaw kapag ininit.", "en": "A crayon is made of colored wax, which softens or melts when it gets warm.", "bis": "Ang crayon hinimo gikan sa wax o kandila nga gisagolan og kolor, ug mohumok o matunaw kon mainitan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "crispy-pata-frying-g5", "domain": "MATTER", "topic": "deep-frying makes pork skin crispy", "grades": [5, 6, 7], "terms": ["crispy pata", "pata", "baboy", "pork knuckle", "pinirito", "malutong", "balat", "panit", "giprito", "malutong nga panit", "deep fry", "mantika", "lana", "init"], "fact": {"tl": "Ang crispy pata ay binabad muna at pinapakuluan, pagkatapos ipiprito sa mainit na mantika para tumuyo at maging malutong ang balat.", "en": "Crispy pata is pork leg that is boiled first, then deep-fried in hot oil so the skin dries out and turns crispy.", "bis": "Ang crispy pata mao ang paa sa baboy nga lutoon una unya iprito sa init nga lana aron momala ug malutong ang panit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dabakan-drum-vibration-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "a drumhead vibrates to make sound", "grades": [3, 4, 5], "terms": ["dabakan", "tambol", "drum", "Mindanao", "kulintang", "tunog", "tingog", "vibration", "pagvibrate", "balat ng tambol", "panit", "pukpok", "huni"], "fact": {"tl": "Ang dabakan ay isang malaking tambol ng Mindanao na tumutunog kapag pinupukpok ang nakaunat na balat, na nagpapayanig sa hangin sa paligid.", "en": "The dabakan is a large drum from Mindanao that makes sound when its stretched skin is struck and vibrates the air around it.", "bis": "Ang dabakan usa ka dako nga tambol gikan sa Mindanao nga motingog kon pukpukon ang inat nga panit, nga mopavibrate sa hangin sa palibot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "daing-na-bangus-drying-g5", "domain": "MATTER", "topic": "salting and drying preserves fish", "grades": [4, 5, 6], "terms": ["daing", "bangus", "milkfish", "asin", "asgad", "tinuyo", "binulad", "buwad", "gibulad", "preserved fish", "isda", "isdang tuyo", "salt", "panangtago"], "fact": {"tl": "Ang daing na bangus ay binilad sa araw at inasnan para matanggal ang tubig, kaya hindi madaling mabulok at tumatagal nang mas matagal.", "en": "Daing na bangus is milkfish salted and dried in the sun so the water is removed, which keeps it from spoiling quickly.", "bis": "Ang daing nga bangus mao ang bangus nga giasinan ug gibulad sa adlaw aron makuha ang tubig, mao nga dili dali madunot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "danggit-dried-fish-g5", "domain": "LIVING_THINGS", "topic": "drying fish stops bacteria from spoiling it", "grades": [5, 6, 7], "terms": ["danggit", "rabbitfish", "tuyong isda", "dried fish", "bulad", "binulad", "buwad nga isda", "asin", "bakterya", "bacteria", "mabulok", "madunot", "preserved", "Cebu"], "fact": {"tl": "Ang danggit ay maliit na isdang tinuyo, at ang pagpapatuyo ay pumipigil sa pagdami ng bakteryang nagpapabulok dahil kailangan nila ng tubig.", "en": "Danggit is a small dried fish, and drying it stops spoilage bacteria from multiplying because they need water to grow.", "bis": "Ang danggit gamay nga isda nga gibulad, ug ang pagpamala makapugong sa bakterya nga makapadunot kay nagkinahanglan sila og tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dart-board-projectile-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "a thrown dart follows a curved path", "grades": [6, 7, 8], "terms": ["dart", "darts", "pana", "target board", "ihagis", "ilabay", "gravity", "grabidad", "projectile", "pababa", "kurba", "paglipad", "puwersa", "force"], "fact": {"tl": "Kapag inihagis ang dart, sabay itong gumagalaw pasulong at bumababa dahil sa hila ng grabidad, kaya bahagyang kurba ang daan nito patungo sa target.", "en": "When a dart is thrown, it moves forward while gravity pulls it down, so it follows a slightly curved path to the board.", "bis": "Kon ilabay ang dart, mopadulong kini samtang ginabira sa grabidad paubos, mao nga gamay nga kurba ang agianan niini paingon sa target."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dinuguan-blood-iron-g6", "domain": "LIVING_THINGS", "topic": "blood is rich in iron used to carry oxygen", "grades": [6, 7, 8], "terms": ["dinuguan", "dugo", "blood stew", "baboy", "bakal", "iron", "puthaw", "oksiheno", "oxygen", "protina", "protein", "namnam"], "fact": {"tl": "Ang dinuguan ay niluluto mula sa dugo ng baboy, na mayaman sa bakal na ginagamit ng katawan para magdala ng oksiheno sa dugo.", "en": "Dinuguan is cooked from pig's blood, which is rich in iron that the body uses to carry oxygen in the blood.", "bis": "Ang dinuguan giluto gikan sa dugo sa baboy, nga dato sa puthaw nga gigamit sa lawas aron magdala og oksiheno sa dugo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dirty-ice-cream-melting-g3", "domain": "MATTER", "topic": "ice cream melts from solid to liquid", "grades": [3, 4, 5], "terms": ["dirty ice cream", "sorbetes", "ice cream", "matunaw", "natunaw", "natural", "solido", "likido", "init", "kainit", "melt", "tunaw", "estado", "state of matter"], "fact": {"tl": "Ang sorbetes ay nagyeyelo at matigas kapag malamig, pero natutunaw at nagiging likido kapag nainitan sa labas ng pridyer.", "en": "Ice cream is frozen and solid when cold, but it melts into a liquid when it warms up outside the freezer.", "bis": "Ang sorbetes nagyelo ug gahi kon bugnaw, apan matunaw ug mahimong likido kon mainitan gawas sa freezer."}, "source": "NRC PS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "diwas-panpipe-air-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "blowing across pipes of different lengths makes different notes", "grades": [4, 5, 6], "terms": ["diwas", "panpipe", "saggeypo", "Kalinga", "kawayan", "bamboo", "hihip", "huyop", "tunog", "tingog", "tono", "pitch", "haba", "length", "gitas-on", "air column", "musika"], "fact": {"tl": "Ang diwas ay isang panpipe na gawa sa magkakaibang haba ng kawayan, at ang mas mahabang tubo ay gumagawa ng mas mababang tunog kapag hinipan.", "en": "The diwas is a panpipe made of bamboo tubes of different lengths, and the longer tube makes a lower note when you blow across it.", "bis": "Ang diwas usa ka panpipe nga hinimo sa kawayan nga lainlain ang gitas-on, ug ang mas taas nga tubo mohatag og mas ubos nga tingog kon huypan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dried-mango-preservation-g4", "domain": "MATTER", "topic": "drying mango removes water to preserve it", "grades": [4, 5, 6], "terms": ["dried mango", "mangga", "manggang tuyo", "mango", "pinatuyo", "binulad", "uga nga mangga", "preserve", "tubig", "asukal", "sugar", "prutas", "bunga", "matamis"], "fact": {"tl": "Ang dried mango ay hiniwang mangga na pinatuyo para matanggal ang karamihan ng tubig, kaya tumatagal nang mas matagal at lumalakas ang tamis.", "en": "Dried mango is sliced mango with most of its water removed, which makes it last longer and taste more sweetly concentrated.", "bis": "Ang dried mango mao ang hiniwa nga mangga nga gipauga aron makuha ang kadaghanan sa tubig, mao nga dugay madunot ug molabaw ang katam-is."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dropper-pipette-pressure-g5", "domain": "MATTER", "topic": "a dropper uses air pressure to pick up liquid", "grades": [5, 6, 7], "terms": ["dropper", "pipette", "patak", "tulo", "tagayan", "hangin", "presyon sa hangin", "air pressure", "pisil", "pigaon", "squeeze", "likido", "tubig", "suction", "sipsip"], "fact": {"tl": "Kapag pinipisil ang goma ng dropper, lumalabas ang hangin, at sa pagbitiw ay sumisipsip ito ng likido dahil sa puwersa ng presyon ng hangin.", "en": "When you squeeze a dropper's bulb the air goes out, and when you let go it sucks up liquid because of air pressure.", "bis": "Kon pug-on ang goma sa dropper, mogawas ang hangin, ug kon buhian mosuyop kini og likido tungod sa kusog sa presyon sa hangin."}, "source": "NRC PS2.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ducks-rice-field-g5", "domain": "LIVING_THINGS", "topic": "ducks help rice farmers by eating pests", "grades": [4, 5, 6], "terms": ["itik", "pato", "bibe", "duck", "palayan", "rice field", "uma sa humay", "kuhol", "golden snail", "peste", "pest", "kaen", "kuon", "balanse", "ecosystem", "magsasaka"], "fact": {"tl": "Sa mga palayan, kumakain ang mga itik ng mga peste tulad ng kuhol at insekto, kaya nakakatulong sila sa magsasaka nang hindi gumagamit ng kemikal.", "en": "In rice fields, ducks eat pests like snails and insects, helping farmers without using chemicals.", "bis": "Sa mga humayan, ang mga itik mokaon og mga peste sama sa kuhol ug insekto, busa makatabang sila sa mag-uuma nga walay kemikal."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dyeing-cloth-pigment-g5", "domain": "MATTER", "topic": "dye dissolves in water and colors cloth fibers", "grades": [5, 6, 7], "terms": ["dyeing", "pagtina", "tina", "dye", "tela", "panapton", "cloth", "kulay", "kolor", "pigment", "natunaw", "nalusaw", "dissolve", "sumisipsip", "absorb", "halamang pangkulay"], "fact": {"tl": "Sa pagtitina, natutunaw ang kulay sa tubig at sumisipsip ang hibla ng tela rito, kaya nananatili ang kulay kahit matuyo na.", "en": "In dyeing, the color dissolves in water and the cloth fibers soak it up, so the color stays even after it dries.", "bis": "Sa pagtina, ang kolor matunaw sa tubig ug ang lanot sa panapton mosuyop niini, mao nga magpabilin ang kolor bisan mamala na."}, "source": "NRC PS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "chili-capsaicin-spicy-g6", "domain": "LIVING_THINGS", "topic": "chili peppers feel hot because of capsaicin", "grades": [6, 7, 8], "terms": ["sili", "siling labuyo", "chili", "anghang", "maanghang", "halang", "hot pepper", "capsaicin", "init", "pakiramdam", "lasa", "buto", "espesye", "Capsicum", "alat"], "fact": {"tl": "Ang sili ay maanghang dahil sa sangkap na capsaicin, na pumupukaw sa mga sensor ng init sa dila kaya pakiramdam mo ay nasusunog ka.", "en": "Chili peppers taste hot because of a chemical called capsaicin, which triggers the tongue's heat sensors so your mouth feels like it is burning.", "bis": "Ang sili halang tungod sa sangkap nga capsaicin, nga moaghat sa mga sensor sa kainit sa dila mao nga morag nasunog ang imong baba."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "earthquake-evacuation-safety-g6", "domain": "EARTH_SPACE", "topic": "earthquake safety and evacuation routes", "grades": [5, 6, 7, 8], "terms": ["lindol", "linog", "earthquake", "evacuation route", "ruta sa pagbakwit", "PHIVOLCS", "duck cover hold", "kaligtasan", "kaluwasan", "safety", "ligtas na lugar", "yumanig", "pagyanig", "drill"], "fact": {"tl": "Sa lindol, dapat yumukod, sumilong sa ilalim ng matibay na mesa, at sumunod sa evacuation route palabas patungo sa bukas na ligtas na lugar.", "en": "During an earthquake you should drop, take cover under a sturdy table, and follow the evacuation route out to a safe open space.", "bis": "Sa linog, kinahanglan moyukbo, mosilong ilalom sa lig-on nga lamesa, ug mosunod sa evacuation route paingon sa luwas nga hawan."}, "source": "DepEd MATATAG; PHIVOLCS guidance", "generator": "claude-workflow", "reviewed": false},
  {"id": "egg-pie-protein-g5", "domain": "MATTER", "topic": "egg sets firm when heated because protein changes", "grades": [5, 6, 7], "terms": ["egg pie", "itlog", "egg", "protina", "protein", "namumuo", "namuo", "naglapot", "tumigas", "set", "init", "kainit", "luto", "gatas", "milk", "magahi"], "fact": {"tl": "Ang egg pie ay tumitigas at lumalapot kapag niluto dahil nagbabago ang anyo ng protina ng itlog sa init.", "en": "Egg pie sets firm when baked because the egg's protein changes shape and locks together with heat.", "bis": "Ang egg pie magahi ug molapot kon lutoon kay ang protina sa itlog mausab ang porma ug magsumpay-sumpay tungod sa kainit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "egg-spoon-balance-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "balancing an egg on a spoon while moving", "grades": [4, 5, 6], "terms": ["egg spoon race", "itlog", "kutsara", "spoon", "timbang", "balanse", "balanse sa lawas", "gravity", "grabidad", "center of gravity", "matumba", "mahulog", "mabilis", "marahan", "laro"], "fact": {"tl": "Sa egg spoon race, kailangang panatilihin ang itlog sa gitna ng kutsara para hindi matumba ang sentro ng bigat at mahulog ito.", "en": "In an egg-and-spoon race you must keep the egg centered on the spoon so its center of gravity stays balanced and it does not roll off.", "bis": "Sa egg spoon race, kinahanglan ipataliwala ang itlog sa kutsara aron magpabilin nga balanse ang sentro sa gibug-aton ug dili matagak."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "empanada-frying-g4", "domain": "MATTER", "topic": "frying dough makes a golden brown crust", "grades": [4, 5, 6], "terms": ["empanada", "pinirito", "masa", "dough", "pastry", "giprito", "malutong", "mantika", "lana", "kayumanggi", "golden brown", "browning", "init", "balat", "panit"], "fact": {"tl": "Ang empanada ay binabad na masang may laman, na kapag ipinirito sa mainit na mantika ay nagiging kayumanggi at malutong ang balat.", "en": "An empanada is filled dough that turns golden brown and crispy on the outside when fried in hot oil.", "bis": "Ang empanada mao ang masa nga may sulod, nga kon iprito sa init nga lana mahimong kayumanggi ug malutong ang gawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ensaymada-yeast-bread-g6", "domain": "LIVING_THINGS", "topic": "yeast makes bread rise by releasing gas", "grades": [5, 6, 7], "terms": ["ensaymada", "tinapay", "bread", "lebadura", "pampaalsa", "yeast", "umaalsa", "mialsa", "rise", "gas", "carbon dioxide", "fungi", "bula", "malambot", "soft bread"], "fact": {"tl": "Ang ensaymada ay malambot dahil sa lebadura, isang munting fungi na naglalabas ng gas para umalsa at mabutas-butas ang masa.", "en": "Ensaymada is soft because of yeast, a tiny fungus that releases gas to make the dough rise and form little air pockets.", "bis": "Ang ensaymada humok tungod sa lebadura, gamay nga fungi nga mogawas og gas aron moalsa ang masa ug mabuslot-buslot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "feather-quill-g4", "domain": "LIVING_THINGS", "topic": "bird feathers", "grades": [3, 4, 5], "terms": ["balahibo ng ibon", "balahibo", "pakpak", "ibon", "balhibo sa langgam", "langgam", "feather", "quill", "bird", "wing", "keratin"], "fact": {"tl": "Ang balahibo ng ibon ay gawa sa keratin, gaya ng ating buhok at kuko, at tumutulong dito upang lumipad at manatiling mainit.", "en": "A bird's feather is made of keratin, the same material as our hair and nails, and it helps the bird fly and stay warm.", "bis": "Ang balhibo sa langgam hinimo gikan sa keratin, pareho sa atong buhok ug kuko, ug nagatabang niini sa paglupad ug pagpabilin nga init."}, "source": "encyclopedia-stable consensus; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "pig-livestock-g4", "domain": "LIVING_THINGS", "topic": "pigs as farm animals", "grades": [3, 4, 5], "terms": ["baboy", "alaga", "hayop sa bukid", "kumakain", "pagkain ng baboy", "baboy sa uma", "babuy", "kan-on", "pig", "hog", "livestock", "omnivore", "farm animal"], "fact": {"tl": "Ang baboy ay alagang hayop na omnivore, kumakain ito ng halaman at hayop, at inaalagaan sa bukid para sa karne nito.", "en": "The pig is a farm animal that is an omnivore, eating both plants and animals, and it is raised on farms for its meat.", "bis": "Ang baboy usa ka inalimahang hayop nga omnivore, mokaon kini sa tanom ug hayop, ug gialimahan sa uma alang sa iyang karne."}, "source": "encyclopedia-stable consensus; DepEd Science G4 LS", "generator": "claude-workflow", "reviewed": false},
  {"id": "fire-extinguisher-use-g6", "domain": "MATTER", "topic": "putting out fire", "grades": [5, 6, 7], "terms": ["pamatay-apoy", "extinguisher", "apoy", "sunog", "oksiheno", "pumapatay ng apoy", "pamarong sa kalayo", "kalayo", "oxygen", "fire extinguisher", "combustion", "smother"], "fact": {"tl": "Ang pamatay-apoy ay pumapatay ng sunog sa pamamagitan ng pagtakip sa apoy upang mawalan ito ng oksiheno na kailangan para magpatuloy ang pagliyab.", "en": "A fire extinguisher puts out a fire by smothering the flames so they lose the oxygen the fire needs to keep burning.", "bis": "Ang pamarong sa kalayo nagapalong sa sunog pinaagi sa pagtabon sa kalayo aron mawad-an kini sa oksiheno nga gikinahanglan aron magpadayon ang pagdilaab."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks Physical Setting", "generator": "claude-workflow", "reviewed": false},
  {"id": "fire-safety-stop-drop-roll-g4", "domain": "MATTER", "topic": "fire safety", "grades": [3, 4, 5], "terms": ["tumigil lumuhod gumulong", "sunog", "apoy", "kaligtasan sa sunog", "oksiheno", "kalayo", "pagpalong", "stop drop roll", "fire safety", "flame", "oxygen", "smother"], "fact": {"tl": "Kapag nasunog ang iyong damit, dapat kang tumigil, lumuhod, at gumulong upang takpan ang apoy at maputol ang suplay ng oksiheno na nagpapanatili nitong nagliliyab.", "en": "If your clothes catch fire, you should stop, drop, and roll to smother the flames and cut off the oxygen that keeps the fire burning.", "bis": "Kung masunog ang imong sinina, kinahanglan ka mohunong, moluhod, ug moligid aron matabonan ang kalayo ug maputol ang oksiheno nga nagapadayon sa pagdilaab."}, "source": "encyclopedia-stable consensus; fire-safety education", "generator": "claude-workflow", "reviewed": false},
  {"id": "food-label-nutrition-facts-g6", "domain": "LIVING_THINGS", "topic": "nutrition and food labels", "grades": [5, 6, 7], "terms": ["label ng pagkain", "nutrition facts", "sustansya", "kaloriya", "asukal", "asin", "taba", "label sa pagkain", "sustansiya", "kaloriya", "nutrition label", "calories", "sugar", "nutrients", "serving"], "fact": {"tl": "Ang nutrition facts label sa pagkain ay nagpapakita ng dami ng sustansya gaya ng kaloriya, asukal, taba, at asin upang matulungan tayong pumili ng mas malusog na pagkain.", "en": "The nutrition facts label on food shows amounts of nutrients like calories, sugar, fat, and salt to help us choose healthier food.", "bis": "Ang nutrition facts label sa pagkaon nagapakita sa gidaghanon sa sustansiya sama sa kaloriya, asukal, tambok, ug asin aron makatabang nato sa pagpili og mas himsog nga pagkaon."}, "source": "encyclopedia-stable consensus; DepEd Science/Health G6", "generator": "claude-workflow", "reviewed": false},
  {"id": "free-range-chicken-g4", "domain": "LIVING_THINGS", "topic": "chickens as farm animals", "grades": [3, 4, 5], "terms": ["manok", "free-range", "alagang manok", "itlog", "ibon", "naglalakad sa bakuran", "manok sa bukid", "manok nga gibuhi", "itlog", "chicken", "hen", "poultry", "free range", "bird", "egg"], "fact": {"tl": "Ang manok ay isang ibon na alagang hayop, at sa free-range na pag-aalaga ay malayang naglalakad sa bakuran upang humukay ng pagkain gaya ng uod at butil.", "en": "The chicken is a bird raised as a farm animal, and in free-range farming it roams the yard freely to scratch for food like worms and grains.", "bis": "Ang manok usa ka langgam nga gibuhi nga hayop, ug sa free-range nga pag-atiman gawasnon kini nga molakaw sa nataran aron mangita og pagkaon sama sa ulod ug lugas."}, "source": "encyclopedia-stable consensus; DepEd Science G4 LS", "generator": "claude-workflow", "reviewed": false},
  {"id": "fresh-lumpia-ubod-g4", "domain": "LIVING_THINGS", "topic": "ubod heart of palm food", "grades": [4, 5, 6], "terms": ["lumpiang ubod", "ubod", "sariwang lumpia", "puso ng niyog", "ubod sa lubi", "presko nga lumpia", "fresh lumpia", "heart of palm", "coconut pith", "gulay"], "fact": {"tl": "Ang sariwang lumpiang ubod ay binabalot ng manipis na balat at pinupuno ng ubod, ang malambot at puting puso na kinukuha sa loob ng tangkay ng punong niyog.", "en": "Fresh lumpiang ubod is wrapped in a thin crepe and filled with ubod, the soft white heart taken from inside the stem of the coconut palm.", "bis": "Ang presko nga lumpiang ubod giputos sa nipis nga panit ug gisudlan ug ubod, ang humok ug puti nga kasingkasing nga gikuha sa sulod sa punoan sa lubi."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "funnel-g4", "domain": "MATTER", "topic": "funnel pouring tool", "grades": [3, 4, 5], "terms": ["embudo", "kalo", "pansala", "tunel", "funnel", "ibubo", "ibo-ubo", "pagbubo ng likido", "narrow opening", "pour liquid"], "fact": {"tl": "Ang embudo ay isang kagamitang malapad sa itaas at makitid sa ibaba na tumutulong ibuhos ang likido o buhangin sa maliit na bunganga ng lalagyan nang hindi tumatapon.", "en": "A funnel is a tool that is wide at the top and narrow at the bottom, helping pour liquids or sand into a container's small opening without spilling.", "bis": "Ang embudo usa ka galamiton nga lapad sa ibabaw ug sigpit sa ubos nga makatabang sa pagbubo sa likido o balas ngadto sa gamay nga baba sa sudlanan nga dili mauwag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gangsa-cordillera-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "gangsa gong sound vibration", "grades": [4, 5, 6], "terms": ["gangsa", "gong", "Cordillera", "Igorot", "tugtog", "patpat", "vibrasyon", "tunog", "bibrasyon", "pagtugtog", "brass gong", "sound vibration", "tukar"], "fact": {"tl": "Ang gangsa ay isang patag na gong na tanso ng mga taga-Cordillera na nililikha ang tunog kapag pinapalo, dahil ang metal ay nagbibrasyon at nagpapadala ng alon ng tunog sa hangin.", "en": "The gangsa is a flat brass gong of the Cordillera peoples that makes sound when struck, because the metal vibrates and sends sound waves through the air.", "bis": "Ang gangsa usa ka patag nga gong nga tumbaga sa mga taga-Cordillera nga mohimo ug tingog kon paliron, kay ang metal mokurog ug magpadala ug balod sa tingog latas sa hangin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gangsa-flat-gong-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "flat gong percussion instrument", "grades": [4, 5, 6], "terms": ["gangsa", "patag na gong", "metal", "instrumentong perkusyon", "tunog", "vibrasyon", "flat gong", "percussion", "tingog", "bibrasyon", "tunog ng metal"], "fact": {"tl": "Ang patag na gangsa ay isang instrumentong perkusyon—nililikha nito ang tunog hindi sa pamamagitan ng kuwerdas kundi sa pagbibrasyon ng buong patag na metal kapag ito ay pinalo.", "en": "The flat gangsa is a percussion instrument—it makes sound not from strings but from the whole flat sheet of metal vibrating when it is struck.", "bis": "Ang patag nga gangsa usa ka instrumentong perkusyon—mohimo kini ug tingog dili pinaagi sa kwerdas kondili sa pagkurog sa tibuok patag nga metal kon kini paliron."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gasera-lamp-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "kerosene lamp combustion light", "grades": [4, 5, 6], "terms": ["gasera", "lampara", "gaas", "mitsa", "apoy", "ilaw", "pagkasunog", "kerosene lamp", "wick", "combustion", "suga", "petrolyo", "lana"], "fact": {"tl": "Ang gasera ay isang lampara na sumisipsip ng gaas sa pamamagitan ng mitsa at nagbibigay ng ilaw kapag ang gaas ay nasusunog sa dulo ng apoy.", "en": "A gasera is a lamp that draws kerosene up a wick and gives light when the kerosene burns at the flame.", "bis": "Ang gasera usa ka lampara nga mosuyop ug gaas pinaagi sa pabilo ug mohatag ug suga kon ang gaas masunog sa tumoy sa kalayo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "geometry-compass-tool-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "compass circle drawing tool", "grades": [5, 6, 7], "terms": ["kompas", "pang-bilog", "pagguhit ng bilog", "geometry", "compass", "radius", "pivot", "circle", "lapis", "pana-bilog", "pagguhit ng sirkulo"], "fact": {"tl": "Ang kompas sa geometry ay isang kagamitang may dalawang braso na gumuguhit ng perpektong bilog dahil ang isang dulo ay nananatiling nakatusok habang ang lapis sa kabilang dulo ay umiikot sa pantay na layo.", "en": "A geometry compass is a two-armed tool that draws a perfect circle because one point stays fixed while the pencil on the other arm swings around at an equal distance.", "bis": "Ang kompas sa geometriya usa ka galamiton nga adunay duha ka bukton nga modrowing ug hingpit nga lingin kay ang usa ka tumoy magpabilin nga nakatusok samtang ang lapis sa pikas motuyok sa managsama nga gilay-on."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "giant-lantern-festival-parol-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "parol lantern light electricity", "grades": [4, 5, 6], "terms": ["parol", "Giant Lantern Festival", "Ligligan Parul", "San Fernando", "Pampanga", "ilaw", "kuryente", "bombilya", "lantern", "light", "electricity", "Pasko", "suga", "Kapampangan"], "fact": {"tl": "Ang higanteng parol ng San Fernando, Pampanga ay umiilaw gamit ang libo-libong bombilya na pinapagana ng kuryente at sumasayaw ang mga ilaw sa pagsindi at pagpatay sa tamang ayos.", "en": "The giant parol of San Fernando, Pampanga lights up with thousands of bulbs powered by electricity, and the lights seem to dance as they switch on and off in patterns.", "bis": "Ang higante nga parol sa San Fernando, Pampanga modan-ag pinaagi sa liboan ka bombilya nga gipadagan sa kuryente, ug ang mga suga morag mosayaw samtang magdagkot ug mapalong sumala sa han-ay."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ginataang-bilo-bilo-g4", "domain": "MATTER", "topic": "coconut milk glutinous rice dessert", "grades": [3, 4, 5], "terms": ["ginataang bilo-bilo", "bilo-bilo", "gata", "malagkit", "pamalit", "saging", "kamote", "coconut milk", "glutinous rice balls", "panghimagas", "ginat-an", "matam-is"], "fact": {"tl": "Ang ginataang bilo-bilo ay isang matamis na panghimagas na gawa sa maliliit na bilog na bola ng galapong na malagkit na niluluto sa gata kasama ng saging at kamote.", "en": "Ginataang bilo-bilo is a sweet dessert made of small round balls of glutinous rice dough cooked in coconut milk together with banana and sweet potato.", "bis": "Ang ginataang bilo-bilo usa ka tam-is nga pumahimagas nga hinimo sa gagmay nga lingin nga bola sa pilit nga harina nga giluto sa gata uban sa saging ug kamote."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ginataang-gulay-g4", "domain": "LIVING_THINGS", "topic": "vegetables in coconut milk nutrition", "grades": [3, 4, 5], "terms": ["ginataang gulay", "gata", "gulay", "kalabasa", "sitaw", "kalunggay", "ginat-an", "coconut milk vegetables", "utan", "bitamina", "masustansiya", "nutrient"], "fact": {"tl": "Ang ginataang gulay ay lutong gulay na tulad ng kalabasa at sitaw sa gata, at ang halong gulay ay nagbibigay ng bitamina at hibla na kailangan ng ating katawan.", "en": "Ginataang gulay is vegetables like squash and string beans cooked in coconut milk, and the mix of vegetables gives vitamins and fiber that our bodies need.", "bis": "Ang ginataang utan mao ang mga utanon sama sa kalabasa ug batong nga giluto sa gata, ug ang sagol nga utanon mohatag ug bitamina ug fiber nga gikinahanglan sa atong lawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ginataang-kalabasa-g4", "domain": "LIVING_THINGS", "topic": "squash vitamin A nutrition", "grades": [3, 4, 5], "terms": ["ginataang kalabasa", "kalabasa", "gata", "bitamina A", "dilaw", "ginat-an", "squash", "coconut milk", "vitamin A", "kahel", "masustansiya"], "fact": {"tl": "Ang ginataang kalabasa ay kalabasang niluto sa gata, at ang matingkad na dilaw-kahel na laman nito ay mayaman sa bitamina A na mabuti para sa malinaw na paningin.", "en": "Ginataang kalabasa is squash cooked in coconut milk, and its bright yellow-orange flesh is rich in vitamin A, which is good for clear eyesight.", "bis": "Ang ginataang kalabasa mao ang kalabasa nga giluto sa gata, ug ang hayag nga dalag-kahel nga unod niini dato sa bitamina A nga maayo alang sa tin-aw nga panan-aw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ginataang-langka-g5", "domain": "LIVING_THINGS", "topic": "unripe jackfruit coconut milk dish", "grades": [4, 5, 6], "terms": ["ginataang langka", "langka", "hilaw na langka", "gata", "ginat-an nga nangka", "nangka", "jackfruit", "unripe jackfruit", "coconut milk", "prutas", "gulay"], "fact": {"tl": "Ang ginataang langka ay gawa sa hilaw na langka na niluluto sa gata; kapag hilaw pa, ginagamit ang langka bilang gulay at hindi pa ito matamis na prutas.", "en": "Ginataang langka is made from unripe jackfruit cooked in coconut milk; when still green, jackfruit is used as a vegetable and is not yet a sweet fruit.", "bis": "Ang ginataang nangka hinimo gikan sa hilaw nga nangka nga giluto sa gata; samtang lunhaw pa, ang nangka gigamit isip utanon ug dili pa kini tam-is nga prutas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ginataang-mais-g4", "domain": "LIVING_THINGS", "topic": "corn coconut milk porridge", "grades": [3, 4, 5], "terms": ["ginataang mais", "mais", "gata", "malagkit", "ginat-an nga mais", "corn", "coconut milk", "porridge", "lugaw", "panghimagas", "butil ng mais"], "fact": {"tl": "Ang ginataang mais ay malamig o mainit na panghimagas na gawa sa butil ng mais at malagkit na bigas na niluluto sa matamis na gata.", "en": "Ginataang mais is a warm or cold dessert made from corn kernels and glutinous rice cooked in sweet coconut milk.", "bis": "Ang ginataang mais usa ka init o bugnaw nga pumahimagas nga hinimo gikan sa lugas sa mais ug pilit nga bugas nga giluto sa tam-is nga gata."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ginataang-monggo-g5", "domain": "LIVING_THINGS", "topic": "mung bean coconut dessert protein", "grades": [4, 5, 6], "terms": ["ginataang monggo", "monggo", "munggo", "balatong", "gata", "ginat-an", "mung bean", "coconut milk", "protina", "protein", "butil", "legume"], "fact": {"tl": "Ang ginataang monggo ay matamis na monggong niluto sa gata, at ang monggo ay isang butil na mayaman sa protina na tumutulong patibayin ang katawan.", "en": "Ginataang monggo is sweet mung beans cooked in coconut milk, and mung beans are a seed rich in protein that helps build a strong body.", "bis": "Ang ginataang monggo mao ang tam-is nga monggo nga giluto sa gata, ug ang monggo usa ka liso nga dato sa protina nga makatabang sa paglig-on sa lawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ginisang-monggo-g5", "domain": "LIVING_THINGS", "topic": "sauteed mung bean soup protein", "grades": [4, 5, 6], "terms": ["ginisang monggo", "monggo", "munggo", "balatong", "gulay", "protina", "ginisa nga monggo", "sauteed mung bean", "mung bean soup", "ampalaya", "malunggay", "protein", "Biyernes"], "fact": {"tl": "Ang ginisang monggo ay sabaw ng pinakuluang monggo na may gulay tulad ng malunggay, at ang monggo ay nagbibigay ng murang pinagkukunan ng protina.", "en": "Ginisang monggo is a soup of boiled mung beans with vegetables like malunggay, and the mung beans provide an affordable source of protein.", "bis": "Ang ginisang monggo usa ka sabaw sa linuto nga monggo nga may utanon sama sa malunggay, ug ang monggo naghatag ug barato nga tinubdan sa protina."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ginataang-isda-g5", "domain": "LIVING_THINGS", "topic": "fish coconut milk dish protein", "grades": [4, 5, 6], "terms": ["ginataang isda", "isda", "gata", "ginat-an nga isda", "fish", "coconut milk", "protina", "protein", "ulam", "sustansiya", "fish in coconut milk"], "fact": {"tl": "Ang ginataang isda ay isdang niluto sa gata, at ang isda ay mahalagang ulam na nagbibigay ng protina na kailangan ng katawan upang lumaki at lumakas.", "en": "Ginataang isda is fish cooked in coconut milk, and fish is an important food that gives the protein the body needs to grow and stay strong.", "bis": "Ang ginataang isda mao ang isda nga giluto sa gata, ug ang isda usa ka importanteng sud-an nga naghatag ug protina nga gikinahanglan sa lawas aron motubo ug molig-on."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gloves-g4", "domain": "MATTER", "topic": "gloves hand protection safety", "grades": [3, 4, 5], "terms": ["guwantes", "gwantes", "proteksiyon sa kamay", "kaligtasan", "goma", "gloves", "hand protection", "safety", "panabang sa kamot", "init", "kemikal", "barrier"], "fact": {"tl": "Ang guwantes ay isinusuot upang protektahan ang kamay—nagsisilbing harang ito laban sa init, sugat, o mga kemikal kapag may ginagawang gawain o eksperimento.", "en": "Gloves are worn to protect the hands—they act as a barrier against heat, cuts, or chemicals when doing work or an experiment.", "bis": "Ang guwantes gisul-ob aron panalipdan ang kamot—kini nagsilbi nga babag batok sa kainit, samad, o kemikal kon adunay buluhaton o eksperimento."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "goggles-g4", "domain": "MATTER", "topic": "safety goggles eye protection", "grades": [3, 4, 5], "terms": ["goggles", "salaming pang-mata", "proteksiyon sa mata", "kaligtasan", "laboratoryo", "salamin", "eye protection", "safety goggles", "panalipod sa mata", "kemikal", "tilamsik"], "fact": {"tl": "Ang goggles ay malapot na salaming isinusuot sa mata upang protektahan ito mula sa tilamsik ng kemikal o lumilipad na bagay sa laboratoryo.", "en": "Goggles are close-fitting eyewear worn to protect the eyes from chemical splashes or flying bits in the laboratory.", "bis": "Ang goggles usa ka hugot nga salamin nga gisul-ob sa mata aron mapanalipdan kini gikan sa tilamsik sa kemikal o naglupad nga butang sa laboratoryo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "goto-tripe-porridge-g5", "domain": "LIVING_THINGS", "topic": "goto rice porridge tripe food", "grades": [4, 5, 6], "terms": ["goto", "lugaw", "tripe", "bituka", "kanin", "luya", "goto porridge", "rice porridge", "lugaw nga goto", "init", "pagkain", "tinai sa baka"], "fact": {"tl": "Ang goto ay isang mainit na lugaw na gawa sa pinakuluang kanin na hinaluan ng tripe o laman-loob ng baka, at ang init nito ay nakakatulong magpalipas ng ginaw.", "en": "Goto is a hot rice porridge made from boiled rice mixed with beef tripe, and its warmth helps comfort the body on cold days.", "bis": "Ang goto usa ka init nga lugaw nga hinimo gikan sa linuto nga bugas nga gisagolan ug tripe o tinai sa baka, ug ang kainit niini makatabang aron mainitan ang lawas sa bugnaw nga adlaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "graduated-cylinder-g6", "domain": "MATTER", "topic": "graduated cylinder measuring volume", "grades": [5, 6, 7], "terms": ["graduated cylinder", "sukatang silindro", "sukat ng dami", "volume", "mililitro", "likido", "measuring cylinder", "sukod sa likido", "sukatan", "mililiter", "marka"], "fact": {"tl": "Ang graduated cylinder ay matangkad at makitid na sisidlan na may mga markang guhit na ginagamit upang sukatin nang tumpak ang dami o volume ng likido sa mililitro.", "en": "A graduated cylinder is a tall, narrow container with marked lines used to measure the amount, or volume, of a liquid accurately in milliliters.", "bis": "Ang graduated cylinder usa ka taas ug sigpit nga sudlanan nga may gimarkahan nga mga linya nga gamiton aron tukmang masukod ang gidaghanon o volume sa likido sa mililiter."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "graph-bar-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "bar graph comparing data", "grades": [4, 5, 6], "terms": ["bar graph", "graphong bar", "tsart", "datos", "paghahambing", "haba ng bar", "bar chart", "datus", "paghambing", "graph", "tudling", "talaan"], "fact": {"tl": "Ang bar graph ay nagpapakita ng datos gamit ang mga rektanggulong bar na ang haba o taas ay kumakatawan sa bilang, kaya madaling ihambing kung alin ang mas marami.", "en": "A bar graph shows data using rectangular bars whose length or height stands for an amount, making it easy to compare which is more.", "bis": "Ang bar graph nagpakita ug datos pinaagi sa rektanggulo nga mga bar nga ang gitas-on o gihabugon nagrepresentar sa gidaghanon, mao nga sayon ikumpara kon hain ang mas daghan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "graph-line-distance-time-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "distance-time graph motion speed", "grades": [6, 7, 8], "terms": ["distance-time graph", "graph ng layo at oras", "bilis", "kilos", "slope", "tuwid na linya", "motion", "speed", "gilay-on ug oras", "paglihok", "galaw", "talangguhit"], "fact": {"tl": "Sa isang distance-time graph, ang patuloy na pataas na linya ay nagpapakita ng kumikilos na bagay, at kapag mas matarik ang linya, mas mabilis ang galaw.", "en": "On a distance-time graph, a steadily rising line shows an object moving, and the steeper the line, the faster the motion.", "bis": "Sa usa ka distance-time graph, ang padayon nga nagsaka nga linya nagpakita nga ang butang naglihok, ug kon mas tarik ang linya, mas paspas ang paglihok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "graph-pictograph-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "pictograph picture data", "grades": [3, 4, 5], "terms": ["pictograph", "larawang graph", "datos", "simbolo", "larawan", "bilang", "picture graph", "hulagway nga graph", "datus", "litrato", "talaan"], "fact": {"tl": "Ang pictograph ay isang graph na gumagamit ng maliliit na larawan o simbolo upang katawanin ang bilang, kung saan ang bawat larawan ay tumutumbas sa isang tiyak na dami.", "en": "A pictograph is a graph that uses small pictures or symbols to stand for numbers, where each picture equals a certain amount.", "bis": "Ang pictograph usa ka graph nga naggamit ug gagmay nga mga hulagway o simbolo aron irepresentar ang gidaghanon, diin ang matag hulagway katumbas sa usa ka piho nga gidaghanon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "green-mango-bagoong-g5", "domain": "LIVING_THINGS", "topic": "unripe mango sour taste fermentation", "grades": [4, 5, 6], "terms": ["hilaw na mangga", "manggang hilaw", "bagoong", "alamang", "maasim", "green mango", "shrimp paste", "fermented", "hilaw nga mangga", "guinamos", "aslom", "acid", "asim"], "fact": {"tl": "Ang hilaw na mangga ay maasim dahil puno ito ng acid bago maghinog, at isinasawsaw ito sa maalat na bagoong na gawa sa pinaasim na alamang o isda.", "en": "Green mango tastes sour because it is full of acids before it ripens, and it is dipped in salty bagoong made from fermented tiny shrimp or fish.", "bis": "Ang hilaw nga mangga maaslom kay puno kini sa acid sa wala pa mahinog, ug gituslob kini sa parat nga guinamos nga hinimo gikan sa gipaaslom nga gagmay nga uyap o isda."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "grilled-corn-cob-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "grilled corn heat cooking", "grades": [4, 5, 6], "terms": ["inihaw na mais", "mais", "ihaw", "uling", "init", "sinugba nga mais", "grilled corn", "charcoal", "heat", "pagluto", "baga", "apoy"], "fact": {"tl": "Ang inihaw na mais ay niluluto sa init ng baga o uling, at ang mataas na init ang nagpapaitim-ginto sa balat at naglalabas ng matamis na lasa nito.", "en": "Grilled corn is cooked over the heat of glowing charcoal, and the strong heat browns the kernels and brings out their sweet flavor.", "bis": "Ang sinugba nga mais giluto sa kainit sa baga o uling, ug ang kusog nga init maoy nagpaitom-bulawan sa unod ug nagpagawas sa tam-is nga lami niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "grilling-corn-roadside-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "grilling heat transfer cooking", "grades": [4, 5, 6], "terms": ["pag-ihaw", "inihaw na mais", "baga", "init", "tindera sa kalsada", "pagsugba", "grilling", "roadside", "heat transfer", "init nga mosaylo", "uling", "apoy", "kalsada"], "fact": {"tl": "Kapag nag-iihaw ng mais sa tabing-kalsada, ang init mula sa baga ay lumilipat sa mais sa pamamagitan ng pag-init ng hangin at radiation, kaya naluluto ito kahit hindi sumasayad sa apoy.", "en": "When corn is grilled at the roadside, heat from the embers moves to the corn through hot air and radiation, so it cooks even without touching the flame.", "bis": "Kon magsugba ug mais sa daplin sa dalan, ang init gikan sa baga mobalhin ngadto sa mais pinaagi sa init nga hangin ug radiation, mao nga maluto kini bisan dili modikit sa kalayo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "glue-bottle-g4", "domain": "MATTER", "topic": "glue adhesive sticking material", "grades": [3, 4, 5], "terms": ["pandikit", "kola", "glue", "bote ng glue", "dikit", "adhesive", "pagdikit", "pandikit nga likido", "sticky", "lagkit", "papel", "matuyo"], "fact": {"tl": "Ang pandikit ay isang malagkit na likido na pumipirmi sa dalawang bagay nang magkadikit, at kapag natuyo ito sa hangin, tumitigas at humahawak nang mahigpit.", "en": "Glue is a sticky liquid that holds two things together, and as it dries in the air it hardens and grips tightly.", "bis": "Ang pandikit usa ka pilit nga likido nga maghiusa sa duha ka butang, ug kon mauga kini sa hangin, motig-a kini ug mogunit ug hugot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "guryon-fighting-kite-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "kite flying and air lift force", "grades": [4, 5, 6], "terms": ["guryon", "saranggola", "bulador", "kite", "tabladu", "hangin", "huyop sa hangin", "wind", "lift", "lumilipad", "naglupad", "lumipad", "fighting kite", "pumailanlang"], "fact": {"tl": "Lumilipad ang guryon kapag ang umaagos na hangin ay tumatama sa nakahilig nitong mukha at itinutulak ito pataas, kaya kailangan ng hangin para manatili itong nasa himpapawid.", "en": "A kite flies because moving air pushes against its tilted surface and lifts it upward, so it needs wind to stay in the sky.", "bis": "Naglupad ang guryon kay ang nagdagan nga hangin moigo sa nahiyad nga nawong niini ug moduso pataas, mao nga nagkinahanglan kini og hangin aron magpabilin sa kahanginan."}, "source": "AAAS Benchmarks 4F (motion/forces); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kawayan-bamboo-strength-g6", "domain": "LIVING_THINGS", "topic": "bamboo as a strong fast-growing grass", "grades": [4, 5, 6, 7], "terms": ["kawayan", "bamboo", "kawayanan", "halaman", "damo", "grass", "tubo", "hollow", "guwang", "lawas nga guwang", "tulay", "tube", "matibay", "lig-on", "strong", "mabilis tumubo", "paspas motubo"], "fact": {"tl": "Ang kawayan ay isang napakabilis tumubong damo na may guwang ngunit matigas na sanga, kaya ginagawa itong tulay, bahay, at gamit dahil magaan pero matibay.", "en": "Bamboo is a very fast-growing grass with a hollow but stiff stem, so people use it for bridges, houses, and tools because it is light yet strong.", "bis": "Ang kawayan usa ka paspas kaayo motubo nga sagbot nga adunay guwang apan gahi nga punoan, mao nga gigamit kini sa tulay, balay, ug galamiton kay gaan apan lig-on."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "halayang-saging-jam-g5", "domain": "MATTER", "topic": "cooking fruit into jam thickens it", "grades": [4, 5, 6], "terms": ["halayang saging", "banana jam", "saging", "banana", "sagol nga saging", "halaya", "jam", "nagluto", "init", "heat", "lumalapot", "kumakapal", "nagbaga", "naglapot", "thicken", "tubig sumingaw", "evaporate", "asukal"], "fact": {"tl": "Kapag pinakuluan ang mashed na saging na may asukal, sumisingaw ang tubig at lumalapot ang timpla hanggang maging makapal na halaya.", "en": "When mashed banana is boiled with sugar, water evaporates and the mixture thickens until it becomes a sticky jam.", "bis": "Kung lutoon ang dinugmok nga saging nga sagolan og asukal, mosingaw ang tubig ug molapot ang sagol hangtod mahimo kining baga nga halaya."}, "source": "NRC PS1.A (matter and its changes); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ube-purple-yam-g4", "domain": "LIVING_THINGS", "topic": "ube is a purple root crop", "grades": [3, 4, 5], "terms": ["ube", "halayang ube", "purple yam", "ubi", "gabe", "ugat", "root crop", "tuber", "violet", "lila", "tapol", "purple", "halaman", "tubo sa ilalim ng lupa", "underground"], "fact": {"tl": "Ang ube ay isang ugat na halaman na tumutubo sa ilalim ng lupa at may likas na lilang kulay, kaya ginagawa itong matamis na pagkain tulad ng halaya.", "en": "Ube is a root crop that grows underground and has a naturally purple color, so it is made into sweet foods like jam.", "bis": "Ang ube usa ka tanom nga ugat nga motubo sa ilawom sa yuta ug adunay natural nga tapol nga kolor, mao nga ginahimo kining tam-is nga pagkaon sama sa halaya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "halo-halo-dessert-g5", "domain": "MATTER", "topic": "shaved ice melts and mixtures", "grades": [3, 4, 5, 6], "terms": ["halo-halo", "halohalo", "dessert", "kendi yelo", "yelong kinayod", "shaved ice", "yelo", "ice", "natutunaw", "natunaw", "melt", "halo", "mixture", "sagol", "matamis", "init", "lamig"], "fact": {"tl": "Ang halo-halo ay isang halo o pinaghalong pagkain kung saan ang kinayod na yelo ay unti-unting natutunaw sa init at nagiging malamig na likido kasama ng gatas.", "en": "Halo-halo is a mixture of foods in which the shaved ice slowly melts in the warmth and turns into a cold liquid together with the milk.", "bis": "Ang halo-halo usa ka sagol nga pagkaon diin ang kinayod nga yelo hinay-hinay nga matunaw sa kainit ug mahimong bugnaw nga likido uban sa gatas."}, "source": "NRC PS1.A (states of matter / melting); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "parol-light-source-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "parol lantern as a light source", "grades": [3, 4, 5], "terms": ["parol", "lantern", "parol frame", "ilaw", "suga", "light", "light source", "tinubdan sa kahayag", "pinagmumulan ng liwanag", "kuryente", "bombilya", "kandila", "nagliliwanag", "nagdan-ag", "Pasko", "Christmas"], "fact": {"tl": "Ang parol ay nagliliwanag dahil sa loob nito ay may pinagmumulan ng liwanag tulad ng bombilya o kandila, na nagpapadala ng ilaw palabas ng makukulay na papel.", "en": "A parol shines because inside it is a light source such as a bulb or candle, which sends light out through the colorful paper.", "bis": "Ang parol nagdan-ag tungod kay sa sulod niini adunay tinubdan sa kahayag sama sa bombilya o kandila, nga nagpadala og suga pagawas sa mabulukon nga papel."}, "source": "AAAS Benchmarks 4F (light); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mangga-mango-tree-g4", "domain": "LIVING_THINGS", "topic": "mango fruit and tree", "grades": [3, 4, 5], "terms": ["mangga", "mango", "harvesting mango", "manga", "puno ng mangga", "kahoy nga mangga", "tree", "prutas", "bunga", "fruit", "hinog", "hinog na mangga", "hilaw", "pamitas", "buto", "seed", "matamis", "dilaw"], "fact": {"tl": "Ang mangga ay isang prutas na tumutubo sa matataas na puno, at ang hilaw na berdeng bunga ay nagiging matamis at dilaw kapag hinog na.", "en": "The mango is a fruit that grows on tall trees, and the unripe green fruit turns sweet and yellow when it ripens.", "bis": "Ang mangga usa ka prutas nga motubo sa tag-as nga kahoy, ug ang hilaw nga berde nga bunga mahimong tam-is ug dalag kung mahinog na."}, "source": "NRC LS1 (life cycles); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "buntal-buri-fiber-g6", "domain": "LIVING_THINGS", "topic": "buntal fiber from buri palm", "grades": [5, 6, 7], "terms": ["buntal", "buntal hat", "buri", "buri palm", "buri nga palma", "hibla", "lanot", "fiber", "habi", "weaving", "naghahabi", "naglara", "sombrero", "kalo", "hat", "palaspas", "dahon", "leaf stalk"], "fact": {"tl": "Ang buntal ay isang matibay na hibla na kinukuha mula sa tangkay ng dahon ng buri palm, at hinahabi ito para gumawa ng mga sombrerong tulad ng buntal hat.", "en": "Buntal is a tough fiber taken from the leaf stalk of the buri palm, and it is woven to make hats such as the buntal hat.", "bis": "Ang buntal usa ka lig-on nga lanot nga gikuha gikan sa tangkay sa dahon sa buri nga palma, ug ginahabol kini aron makahimo og kalo sama sa buntal hat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "healthy-habits-g4", "domain": "LIVING_THINGS", "topic": "healthy daily habits for the body", "grades": [3, 4, 5], "terms": ["healthy habits", "malusog na gawi", "himsog nga batasan", "kalusugan", "panglawas", "health", "tulog", "katulog", "sleep", "ehersisyo", "ehersisyo sa lawas", "exercise", "hilamos", "paghugas", "wash", "malinis", "tubig", "checklist"], "fact": {"tl": "Ang mga malusog na gawi tulad ng pagtulog nang sapat, pag-eehersisyo, paghuhugas ng kamay, at pagkain ng masustansyang pagkain ay tumutulong para manatiling malakas at hindi madaling magkasakit ang katawan.", "en": "Healthy habits such as getting enough sleep, exercising, washing your hands, and eating nutritious food help keep the body strong and less likely to get sick.", "bis": "Ang himsog nga mga batasan sama sa igo nga pagkatulog, pag-ehersisyo, paghugas sa kamot, ug pagkaon og masustansya nga pagkaon makatabang aron magpabilin nga lig-on ang lawas ug dili dali masakit."}, "source": "DepEd MATATAG Science/Health (healthy living); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "healthy-snack-vs-sugary-drink-g5", "domain": "LIVING_THINGS", "topic": "sugary drinks vs healthy snacks", "grades": [4, 5, 6], "terms": ["sugary drink", "matamis na inumin", "tam-is nga ilimnon", "asukal", "sugar", "softdrinks", "soda", "malusog na meryenda", "himsog nga meryenda", "healthy snack", "prutas", "gulay", "nutrisyon", "ngipin", "tooth decay", "sira ng ngipin", "obesity"], "fact": {"tl": "Ang mga inuming maraming asukal tulad ng softdrinks ay nagbibigay ng kaunting sustansya at nakakasira ng ngipin, kaya mas mainam ang masustansyang meryenda tulad ng prutas.", "en": "Drinks with a lot of sugar like soft drinks give little nutrition and can harm the teeth, so a nutritious snack like fruit is a better choice.", "bis": "Ang mga ilimnon nga daghan og asukal sama sa softdrinks gamay ra og sustansya ug makadaot sa ngipon, mao nga mas maayo ang masustansya nga meryenda sama sa prutas."}, "source": "DepEd MATATAG Science/Health (nutrition); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "holen-marbles-friction-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "rolling marbles, force and friction", "grades": [4, 5, 6], "terms": ["holen", "marbles", "laro nga holen", "bola-bola", "salamin nga bola", "gumugulong", "naligid", "roll", "tama", "banggaan", "collision", "duso", "lakas", "force", "friction", "kuskos", "huminto"], "fact": {"tl": "Sa laro ng holen, ang bola ay gumugulong kapag tinulak mo ito, at unti-unti itong bumabagal at humihinto dahil sa kuskos o friction sa lupa.", "en": "In the game of marbles, a marble rolls when you push it, and it gradually slows and stops because of friction with the ground.", "bis": "Sa dula nga holen, ang bola moligid kung imo kining iduso, ug hinay-hinay kining mohinay ug mohunong tungod sa kuskos o friction sa yuta."}, "source": "AAAS Benchmarks 4F (forces and motion); NRC PS2", "generator": "claude-workflow", "reviewed": false},
  {"id": "monggo-mung-bean-seed-g5", "domain": "LIVING_THINGS", "topic": "mung bean is a seed that sprouts", "grades": [3, 4, 5, 6], "terms": ["monggo", "mung bean", "munggo", "mongo", "hopia mongo", "buto", "binhi", "liso", "seed", "tumutubo", "nagsibol", "nagtubo", "sprout", "togue", "ugat", "talbos", "legume", "gulay", "halaman"], "fact": {"tl": "Ang monggo ay isang buto na maaaring tumubo at maging halaman, at kapag binabad sa tubig ay nagsisibol ito ng ugat at talbos na tinatawag na togue.", "en": "The mung bean is a seed that can grow into a plant, and when soaked in water it sprouts a root and shoot that we call bean sprouts.", "bis": "Ang monggo usa ka liso nga mahimong motubo og tanom, ug kung ibabad sa tubig moturok kini og gamot ug saha nga gitawag og togue."}, "source": "NRC LS1 (plant life cycles); DepEd G5 (seed germination)", "generator": "claude-workflow", "reviewed": false},
  {"id": "humba-braising-heat-g6", "domain": "MATTER", "topic": "cooking meat with heat changes it", "grades": [4, 5, 6], "terms": ["humba", "braised pork", "giluto nga baboy", "humba nga baboy", "karne", "baboy", "meat", "pork", "init", "luto", "heat", "cooking", "lumambot", "humina", "nag-usab", "nagbag-o", "tender", "nagluluto", "toyo", "asukal"], "fact": {"tl": "Sa pagluluto ng humba, ang init ay marahan na nagpapalambot sa matigas na karne ng baboy at nagbabago sa lasa at kulay nito.", "en": "When cooking humba, heat slowly makes the tough pork tender and changes its taste and color.", "bis": "Sa pagluto og humba, ang kainit hinay-hinay nga magpahumok sa gahi nga karne sa baboy ug magbag-o sa lami ug kolor niini."}, "source": "NRC PS1.A (matter changes with heat); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ice-candy-freezing-g4", "domain": "MATTER", "topic": "freezing liquid into ice candy", "grades": [3, 4, 5], "terms": ["ice candy", "ice candy tube", "kendi yelo", "yelo nga kendi", "tubo", "naninigas", "namuo", "nagyelo", "freeze", "freezing", "likido", "liquid", "solid", "buo", "lamig", "ginaw", "malamig", "natunaw", "estado ng bagay"], "fact": {"tl": "Ang ice candy ay gawa sa likidong juice na ibinubuhos sa tubo at inilalagay sa freezer, kung saan ang lamig ay nagpapanigas dito mula likido patungong solidong yelo.", "en": "Ice candy is made from liquid juice poured into a tube and put in the freezer, where the cold hardens it from a liquid into solid ice.", "bis": "Ang ice candy gihimo gikan sa likido nga juice nga gibubo sa tubo ug gibutang sa freezer, diin ang katugnaw magpagahi niini gikan sa likido ngadto sa solido nga yelo."}, "source": "NRC PS1.A (states of matter / freezing); DepEd G4", "generator": "claude-workflow", "reviewed": false},
  {"id": "scientific-method-steps-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "steps of the scientific method", "grades": [5, 6, 7, 8], "terms": ["scientific method", "pamamaraang siyentipiko", "siyentipikong pamamaraan", "syentipikanhong pamaagi", "hypothesis", "haka-haka", "pangagpas", "experiment", "eksperimento", "konklusyon", "conclusion", "tanong", "pagmamasid", "obserbasyon", "pagsubok", "imbestigasyon"], "fact": {"tl": "Sa pamamaraang siyentipiko, nagtatanong muna ang siyentipiko, gumagawa ng haka-haka o hypothesis, sumusubok sa pamamagitan ng eksperimento, at saka gumagawa ng konklusyon batay sa resulta.", "en": "In the scientific method, a scientist first asks a question, makes a hypothesis or guess, tests it through an experiment, and then forms a conclusion based on the results.", "bis": "Sa syentipikanhong pamaagi, mangutana una ang siyentista, maghimo og hypothesis o banabana, mosulay pinaagi sa eksperimento, ug dayon maghimo og konklusyon base sa resulta."}, "source": "AAAS Benchmarks 1B (scientific inquiry); NRC scientific practices", "generator": "claude-workflow", "reviewed": false},
  {"id": "icon-method-observe-g3", "domain": "LIVING_THINGS", "topic": "observing in science", "grades": [3, 4, 5], "terms": ["pagmamasid", "masdan", "obserbasyon", "pandama", "mata", "tainga", "pag-obserbar", "pagtan-aw", "obserbahan", "dunggan", "observe", "observation", "senses", "science skill", "look carefully"], "fact": {"tl": "Ang pagmamasid ay maingat na paggamit ng ating mga pandama—mata, tainga, ilong, balat—upang malaman kung ano talaga ang nangyayari sa isang bagay.", "en": "Observing means carefully using our senses—eyes, ears, nose, skin—to find out what is really happening with something.", "bis": "Ang pag-obserbar mao ang mainampingong paggamit sa atong mga igbalantay—mata, dunggan, ilong, panit—aron mahibal-an kon unsa gyud ang nahitabo sa usa ka butang."}, "source": "AAAS Benchmarks 1A (scientific inquiry); DepEd G3 process skills", "generator": "claude-workflow", "reviewed": false},
  {"id": "icon-method-question-g3", "domain": "LIVING_THINGS", "topic": "asking questions in science", "grades": [3, 4, 5], "terms": ["tanong", "magtanong", "pagtatanong", "bakit", "paano", "pag-usisa", "pangutana", "mangutana", "ngano", "unsaon", "siyensya", "question", "asking", "why", "how", "inquiry", "scientist"], "fact": {"tl": "Nagsisimula ang agham sa magagandang tanong tulad ng \"Bakit?\" at \"Paano?\", na nagtutulak sa atin na mag-imbestiga at humanap ng sagot.", "en": "Science begins with good questions like \"Why?\" and \"How?\", which push us to investigate and look for answers.", "bis": "Ang siyensya magsugod sa maayong mga pangutana sama sa \"Ngano?\" ug \"Unsaon?\", nga nagtukmod kanato sa pag-imbestiga ug pagpangita ug tubag."}, "source": "AAAS Benchmarks 1A; NRC Framework science practices", "generator": "claude-workflow", "reviewed": false},
  {"id": "icon-observe-eye-g3", "domain": "LIVING_THINGS", "topic": "the eye and sight", "grades": [3, 4, 5], "terms": ["mata", "paningin", "liwanag", "tingin", "makita", "panan-aw", "kahayag", "makakita", "eye", "sight", "light", "see", "vision"], "fact": {"tl": "Nakakakita tayo dahil pumapasok ang liwanag sa ating mata, at ipinapadala nito ang mensahe sa utak para maintindihan natin ang nakikita.", "en": "We can see because light enters our eyes, and the eye sends a message to the brain so we can understand what we are looking at.", "bis": "Makakita kita tungod kay ang kahayag mosulod sa atong mata, ug ang mata mopadala ug mensahe ngadto sa utok aron masabtan nato ang atong gitan-aw."}, "source": "Harlen Big Ideas (senses); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ifugao-bulul-rice-god-g5", "domain": "LIVING_THINGS", "topic": "wood and rice farming", "grades": [4, 5, 6], "terms": ["bulul", "Ifugao", "kahoy", "narra", "palayan", "bigas", "inukit", "kinulit", "humay", "gigikan", "wood", "rice", "carving", "granary", "Ifugao"], "fact": {"tl": "Ang bulul ay rebultong inukit mula sa matibay na kahoy ng mga Ifugao at inilalagay sa kamalig bilang bantay ng kanilang palay na itinatanim sa hagdan-hagdang palayan.", "en": "The bulul is a figure carved from hard wood by the Ifugao and placed in the granary as a guardian of the rice they grow on terraced fields.", "bis": "Ang bulul usa ka rebulto nga gikulit gikan sa gahi nga kahoy sa mga Ifugao ug gibutang sa bodega isip magbalantay sa ilang humay nga gitanom sa hagdan-hagdan nga basakan."}, "source": "encyclopedia-stable consensus; DepEd G5 plants/materials", "generator": "claude-workflow", "reviewed": false},
  {"id": "improvised-tin-tambourine-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "sound from vibration", "grades": [3, 4, 5], "terms": ["tansan", "tambourine", "tunog", "panginginig", "metal", "yanig", "tingog", "pag-uyog", "puthaw", "tin can", "tambourine", "sound", "vibration", "bottle cap"], "fact": {"tl": "Kapag inaalog ang tambourine na yari sa mga pinipirot na tansan, nagbabanggaan ang mga ito at nanginginig ang hangin, kaya may tunog na naririnig.", "en": "When you shake a tambourine made of flattened bottle caps, the caps knock together and make the air vibrate, so we hear sound.", "bis": "Kon uyogon ang tambourine nga hinimo sa pinipi nga mga tansan, mag-igo ang mga tansan ug magpauyog sa hangin, mao nga adunay tingog nga madungog."}, "source": "DepEd G3 sound; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "inabel-loom-weaving-g5", "domain": "MATTER", "topic": "fiber and weaving", "grades": [4, 5, 6], "terms": ["inabel", "habi", "hibla", "sinulid", "tela", "habihan", "Ilocos", "paghabi", "hilo", "panapton", "habol", "fiber", "weaving", "loom", "thread", "cloth", "Ilocano"], "fact": {"tl": "Ang inabel ay telang gawa ng mga Ilokano sa pamamagitan ng paghahabi—maingat na pagsasalitan ng mga hibla ng sinulid sa habihan—para makabuo ng matibay na tela.", "en": "Inabel is a cloth made by Ilocanos through weaving—carefully crossing threads over and under on a loom—to form a strong fabric.", "bis": "Ang inabel usa ka panapton nga gihimo sa mga Ilocano pinaagi sa paghabol—mainampingong pag-agi sa mga hilo ibabaw ug ilawom sa habolan—aron makahimo ug lig-on nga tela."}, "source": "encyclopedia-stable consensus; DepEd G5 materials", "generator": "claude-workflow", "reviewed": false},
  {"id": "isaw-grilled-intestine-g5", "domain": "MATTER", "topic": "cooking and protein", "grades": [4, 5, 6], "terms": ["isaw", "bituka", "ihaw", "manok", "baboy", "protina", "init", "sugba", "tinai", "gisugba", "grilled", "intestine", "protein", "heat", "chicken", "pork"], "fact": {"tl": "Ang isaw ay bituka ng manok o baboy na may protina, at kapag inihaw sa init, namamatay ang mga mikrobyo at nagiging ligtas itong kainin.", "en": "Isaw is the intestine of chicken or pork, which is high in protein, and grilling it with heat kills germs and makes it safe to eat.", "bis": "Ang isaw mao ang tinai sa manok o baboy nga adunay protina, ug kon sugbaon kini sa kainit, mamatay ang mga mikrobyo ug mahimong luwas kaonon."}, "source": "encyclopedia-stable consensus; DepEd G5 nutrition/heat", "generator": "claude-workflow", "reviewed": false},
  {"id": "itak-cleaver-g5", "domain": "MATTER", "topic": "metal and sharp edges", "grades": [4, 5, 6], "terms": ["itak", "bolo", "metal", "bakal", "talim", "matalas", "puthaw", "hait", "talinis", "cleaver", "blade", "sharp"], "fact": {"tl": "Ang itak ay gawa sa matigas na metal at may manipis, matalas na talim na nagtutuon ng puwersa sa isang gilid, kaya madali nitong puputulin ang kahoy o niyog.", "en": "The itak is made of hard metal with a thin, sharp edge that focuses force on one line, so it can easily cut wood or coconut.", "bis": "Ang itak hinimo sa gahi nga metal ug adunay nipis, hait nga sulab nga nagpundok sa kusog sa usa ka linya, busa sayon niini putlon ang kahoy o lubi."}, "source": "encyclopedia-stable consensus; DepEd G5 properties of materials", "generator": "claude-workflow", "reviewed": false},
  {"id": "jackstone-game-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "gravity and falling", "grades": [3, 4, 5], "terms": ["jackstone", "bola", "laro", "bagsak", "gravity", "grabidad", "hulog", "dula", "bati", "jackstone", "ball", "fall", "bounce"], "fact": {"tl": "Sa jackstone, ipinupukol pataas ang bola at habang bumabagsak ito dahil sa grabidad, dinadampot mo ang mga jack bago ito mahuli ng kamay.", "en": "In jackstone, you toss the ball up, and while gravity pulls it back down, you scoop up the jacks before catching the ball.", "bis": "Sa jackstone, ilabay nimo ang bola pataas, ug samtang gibira kini pabalik sa grabidad, hakopon nimo ang mga jack una nimo sakpon ang bola."}, "source": "encyclopedia-stable consensus; DepEd G4 force and motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "jolens-marble-shooting-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "force changes motion", "grades": [3, 4, 5], "terms": ["jolen", "holen", "marble", "tudlo", "puwersa", "tama", "gulong", "kusog", "igo", "ligid", "flick", "force", "motion", "collision"], "fact": {"tl": "Sa larong jolen, pinipitik mo ang isang holen para magbigay ng puwersa, at kapag tumama ito sa ibang holen, naipapasa ang galaw at gumugulong ang mga ito palayo.", "en": "In the game of marbles, you flick one marble to give it force, and when it hits another marble, the motion passes on and they roll away.", "bis": "Sa dula nga holen, tudlohon nimo ang usa ka holen aron hatagan ug kusog, ug kon maigo niini ang laing holen, mabalhin ang lihok ug moligid sila palayo."}, "source": "encyclopedia-stable consensus; DepEd G4 force and motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "kabkab-cassava-cracker-g5", "domain": "MATTER", "topic": "frying and starch", "grades": [4, 5, 6], "terms": ["kabkab", "kamoteng kahoy", "cassava", "almirol", "prito", "init", "lumalaki", "balanghoy", "almidon", "gisaha", "cracker", "starch", "frying", "puff"], "fact": {"tl": "Ang kabkab ay gawa sa giniling na kamoteng-kahoy na puno ng almirol, at kapag iprinito sa mainit na mantika, sumasabog ang singaw sa loob at lumalaki itong parang malutong na kracker.", "en": "Kabkab is made from ground cassava full of starch, and when fried in hot oil, steam bursts inside and it puffs up into a crisp cracker.", "bis": "Ang kabkab hinimo sa giniling nga balanghoy nga puno sa almidon, ug kon iprito sa init nga mantika, mobuto ang aso sa sulod ug mobukha kini nga daw tagiktik nga cracker."}, "source": "encyclopedia-stable consensus; DepEd G5 changes in materials", "generator": "claude-workflow", "reviewed": false},
  {"id": "kagul-bamboo-scraper-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "sound from vibrating bamboo", "grades": [3, 4, 5], "terms": ["kagul", "kawayan", "tunog", "kayod", "panginginig", "instrumento", "tingog", "pagkagis", "pag-uyog", "tulonggon", "bamboo", "scraper", "sound", "vibration", "instrument"], "fact": {"tl": "Ang kagul ay instrumentong kawayan na may mga ngipin, at kapag kinakayod ng patpat, nanginginig ang kawayan at gumagawa ng paulit-ulit na tunog.", "en": "The kagul is a bamboo instrument with notches, and scraping it with a stick makes the bamboo vibrate and produce a repeating rattling sound.", "bis": "Ang kagul usa ka tulonggon nga kawayan nga adunay mga ngipon, ug kon kagison kini ug patpat, mag-uyog ang kawayan ug mohimo ug balikbalik nga tingog."}, "source": "encyclopedia-stable consensus; DepEd G3 sound", "generator": "claude-workflow", "reviewed": false},
  {"id": "kakanin-tray-assortment-g5", "domain": "MATTER", "topic": "rice and coconut food", "grades": [4, 5, 6], "terms": ["kakanin", "bigas", "malagkit", "gata", "niyog", "kanin", "matamis", "pilit", "lubi", "humay", "rice cake", "sticky rice", "coconut milk", "delicacy"], "fact": {"tl": "Ang kakanin ay mga tradisyunal na meryendang Pilipino na karaniwang gawa sa malagkit na bigas at gata ng niyog, na nagiging matamis at malagkit kapag niluto.", "en": "Kakanin are traditional Filipino snacks usually made from sticky rice and coconut milk, which turn sweet and chewy when cooked.", "bis": "Ang kakanin mao ang tradisyonal nga meryenda sa mga Pilipino nga kasagaran hinimo sa pilit nga bugas ug gata sa lubi, nga mahimong tam-is ug pilit kon lutoon."}, "source": "encyclopedia-stable consensus; DepEd G5 food/materials", "generator": "claude-workflow", "reviewed": false},
  {"id": "kalamares-fried-squid-g5", "domain": "LIVING_THINGS", "topic": "squid as a sea animal", "grades": [4, 5, 6], "terms": ["kalamares", "pusit", "dagat", "hayop", "prito", "galamay", "nuos", "mananap", "squid", "sea", "mollusk", "fried", "tentacles"], "fact": {"tl": "Ang kalamares ay gawa sa pusit, isang hayop sa dagat na walang buto pero may maraming galamay, at niluluto ito sa pamamagitan ng pagprito.", "en": "Kalamares is made from squid, a boneless sea animal with many tentacles, and it is cooked by frying.", "bis": "Ang kalamares hinimo sa nuos, usa ka mananap sa dagat nga walay bukog apan adunay daghang galamay, ug giluto kini pinaagi sa pagprito."}, "source": "encyclopedia-stable consensus; DepEd G5 animals", "generator": "claude-workflow", "reviewed": false},
  {"id": "kalamay-hati-jar-g5", "domain": "MATTER", "topic": "heating thickens sugar mixture", "grades": [4, 5, 6], "terms": ["kalamay", "hati", "asukal", "gata", "lapot", "init", "palamig", "asukar", "baga", "sticky sweet", "sugar", "coconut", "thicken", "heat"], "fact": {"tl": "Ang kalamay-hati ay gawa sa gata, asukal, at malagkit na bigas na pinakuluan nang matagal hanggang sumingaw ang tubig at lumapot ito.", "en": "Kalamay-hati is made from coconut milk, sugar, and sticky rice boiled a long time until the water evaporates and the mixture thickens.", "bis": "Ang kalamay-hati hinimo sa gata, asukar, ug pilit nga bugas nga gipabukal og dugay hangtod nga moalisngaw ang tubig ug molapot kini."}, "source": "encyclopedia-stable consensus; DepEd G5 changes in materials", "generator": "claude-workflow", "reviewed": false},
  {"id": "kaldero-pot-g4", "domain": "MATTER", "topic": "metal conducts heat", "grades": [4, 5, 6], "terms": ["kaldero", "kawali", "metal", "init", "aluminyo", "kanin", "puthaw", "aluminum", "kan-on", "pot", "heat", "conduction", "cooking"], "fact": {"tl": "Ang kaldero ay gawa sa metal dahil madaling dumaloy ang init dito, kaya mabilis nitong maipapasa ang init ng apoy sa tubig at pagkain sa loob.", "en": "A kaldero is made of metal because heat flows through it easily, so it quickly passes the fire's heat to the water and food inside.", "bis": "Ang kaldero hinimo sa metal tungod kay sayon moagi ang kainit niini, busa paspas niini mabalhin ang kainit sa kalayo ngadto sa tubig ug pagkaon sa sulod."}, "source": "encyclopedia-stable consensus; DepEd G4 heat/conductors", "generator": "claude-workflow", "reviewed": false},
  {"id": "kalesa-horse-carriage-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "animal pulling force", "grades": [3, 4, 5], "terms": ["kalesa", "kabayo", "hila", "gulong", "puwersa", "sasakyan", "karwahe", "guyod", "ligid", "kusog", "horse", "pull", "wheel", "force", "carriage"], "fact": {"tl": "Ang kalesa ay sasakyang hinihila ng kabayo—ginagamit ng hayop ang lakas ng kalamnan nito para mag-aplay ng puwersa na nagpapagulong sa mga gulong.", "en": "A kalesa is a carriage pulled by a horse—the animal uses its muscle power to apply force that makes the wheels roll.", "bis": "Ang kalesa usa ka sakyanan nga giguyod sa kabayo—gigamit sa mananap ang kusog sa iyang kaunoran aron mohatag ug puwersa nga magpaligid sa mga ligid."}, "source": "encyclopedia-stable consensus; DepEd G4 force and motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "kalinga-gong-circle-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "sound from metal gongs", "grades": [3, 4, 5], "terms": ["gangsa", "Kalinga", "gong", "metal", "tunog", "tugtog", "panginginig", "agong", "tingog", "pagtugtog", "sound", "vibration", "percussion"], "fact": {"tl": "Ang gangsa ay metal na gong ng mga Kalinga, at kapag pinalo, nanginginig ang metal at lumilikha ng malakas na tunog na kumakalat sa hangin.", "en": "The gangsa is a metal gong of the Kalinga, and when struck, the metal vibrates and creates a loud sound that spreads through the air.", "bis": "Ang gangsa usa ka metal nga agong sa mga Kalinga, ug kon pukpukon, mag-uyog ang metal ug mohimo ug kusog nga tingog nga mokaylap sa hangin."}, "source": "encyclopedia-stable consensus; DepEd G3 sound", "generator": "claude-workflow", "reviewed": false},
  {"id": "kamote-chips-bag-g4", "domain": "MATTER", "topic": "frying removes water", "grades": [4, 5, 6], "terms": ["kamote", "chips", "ugat", "prito", "tuyo", "malutong", "gamot", "uga", "sweet potato", "root", "frying", "crisp"], "fact": {"tl": "Ang kamote chips ay manipis na hiwa ng kamote, isang ugat na pagkain, na iprinito hanggang sumingaw ang tubig at maging malutong.", "en": "Kamote chips are thin slices of sweet potato, a root crop, fried until the water evaporates and they turn crisp.", "bis": "Ang kamote chips mao ang nipis nga hiwa sa kamote, usa ka gamot nga tanom, nga giprito hangtod moalisngaw ang tubig ug mahimong tagiktik."}, "source": "encyclopedia-stable consensus; DepEd G4 changes in materials", "generator": "claude-workflow", "reviewed": false},
  {"id": "jeepney-decorated-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "engine powers a vehicle", "grades": [4, 5, 6], "terms": ["jeepney", "makina", "gasolina", "sasakyan", "gulong", "enerhiya", "krudo", "sakyanan", "ligid", "kusog", "engine", "fuel", "vehicle", "energy", "motion"], "fact": {"tl": "Ang jeepney ay tumatakbo dahil sinusunog ng makina nito ang gasolina, at ang enerhiya mula rito ang nagpapaikot sa mga gulong para gumalaw ang sasakyan.", "en": "A jeepney runs because its engine burns fuel, and the energy from that turns the wheels so the vehicle can move.", "bis": "Ang jeepney modagan tungod kay ang makina niini magsunog ug gasolina, ug ang kusog gikan niini magpatuyok sa mga ligid aron molihok ang sakyanan."}, "source": "encyclopedia-stable consensus; DepEd G5 energy", "generator": "claude-workflow", "reviewed": false},
  {"id": "kaong-palm-fruit-g5", "domain": "LIVING_THINGS", "topic": "kaong sugar palm fruit", "grades": [4, 5, 6], "terms": ["kaong", "irok", "kaong palm", "sugar palm", "Arenga pinnata", "prutas", "palma", "bunga", "kahoy", "puno", "matamis na pang-himagas", "halaman"], "fact": {"tl": "Ang kaong ay malalambot at malilinaw na buto ng palmang tinatawag na sugar palm, na pinakukuluan sa arnibal at ginagawang pamatamis sa mga panghimagas tulad ng halo-halo.", "en": "Kaong are the soft, jelly-like seeds of the sugar palm tree, boiled in syrup and used as a sweet topping in desserts like halo-halo.", "bis": "Ang kaong mao ang humok ug mola nga liso sa palmang sugar palm, nga ginalat-an sa dugos ug ginagamit nga tam-is nga sangkap sa halo-halo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kapeng-barako-cup-g6", "domain": "LIVING_THINGS", "topic": "kapeng barako Liberica coffee", "grades": [5, 6, 7], "terms": ["kapeng barako", "barako", "kape", "kapeng Liberica", "Liberica coffee", "Batangas", "Cavite", "buto ng kape", "coffee bean", "puno ng kape", "inumin", "caffeine", "kapeng Pilipino"], "fact": {"tl": "Ang kapeng barako ay isang uri ng Liberica na kape na pinatutubo sa Batangas at Cavite, kilala sa malakas na lasa at amoy nitong galing sa malalaking buto.", "en": "Kapeng barako is a Liberica coffee variety grown in Batangas and Cavite, famous for its strong flavor and bold aroma from its unusually large beans.", "bis": "Ang kapeng barako usa ka matang sa Liberica nga kape nga gitanom sa Batangas ug Cavite, ilado sa kusog nga lami ug kahumot gikan sa dagko niini nga liso."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kawa-vat-of-sugar-g6", "domain": "MATTER", "topic": "boiling sugarcane juice in a kawa", "grades": [5, 6, 7], "terms": ["kawa", "kawa nga tumbaga", "malaking kawali", "tubo", "sugarcane", "muscovado", "asukal", "pagpapakulo", "pagsingaw", "evaporation", "pampalapot", "lutong asukal", "init"], "fact": {"tl": "Sa malaking kawa, pinakukulo ang katas ng tubo nang matagal para sumingaw ang tubig at lumapot ito hanggang maging asukal na tulad ng muscovado.", "en": "In a large kawa (vat), sugarcane juice is boiled for a long time so the water evaporates and the liquid thickens into sugar such as muscovado.", "bis": "Sa dako nga kawa, ginpabukal ang duga sa tubo ug dugay aron mosingaw ang tubig ug molapot kini ngadto sa asukal sama sa muscovado."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kawali-frying-pan-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "metal frying pan conducts heat", "grades": [3, 4, 5], "terms": ["kawali", "frying pan", "wok", "metal", "bakal", "init", "heat", "pagluluto", "conductor", "tagahatid ng init", "pagprito", "kalan", "apoy", "thermal conductor"], "fact": {"tl": "Ang kawali ay gawa sa metal dahil madaling humatid ang metal ng init mula sa apoy patungo sa pagkaing iniluluto.", "en": "A kawali (frying pan) is made of metal because metal is a good conductor that quickly carries heat from the flame to the food being cooked.", "bis": "Ang kawali hinimo sa metal kay ang metal maayong tighatud sa kainit gikan sa kalayo paingon sa pagkaon nga giluto."}, "source": "NRC PS3.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kawayan-bamboo-dance-poles-g6", "domain": "LIVING_THINGS", "topic": "bamboo as a fast-growing grass", "grades": [4, 5, 6, 7], "terms": ["kawayan", "bamboo", "tinikling", "damo", "grass", "halaman", "matigas", "guwang-guwang", "hollow", "mabilis tumubo", "fast growing", "buko", "node", "puno", "kawayan nga poste"], "fact": {"tl": "Ang kawayan ay isang napakabilis tumubong damo na may guwang at matibay na tangkay, kaya ginagamit itong poste sa sayaw na tinikling at sa pagtatayo ng bahay.", "en": "Bamboo is a very fast-growing grass with a hollow, strong stem, which is why it is used as the poles in the tinikling dance and for building houses.", "bis": "Ang kawayan usa ka paspas kaayo motubo nga sagbot nga adunay guwang ug lig-on nga punoan, mao nga gamiton kini nga poste sa sayaw nga tinikling ug sa pagtukod og balay."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kerosene-stove-burner-g5", "domain": "MATTER", "topic": "kerosene burning as fuel", "grades": [4, 5, 6], "terms": ["kerosene", "gaas", "kalan", "stove", "burner", "sunog", "combustion", "gasolina", "fuel", "panggatong", "apoy", "init", "langis", "pagkasunog", "mitsa"], "fact": {"tl": "Ang kerosene o gaas ay isang likido mula sa langis na nasusunog upang maglabas ng init at apoy para magluto.", "en": "Kerosene (gaas) is a liquid fuel made from petroleum that burns to release heat and a flame for cooking.", "bis": "Ang kerosene o gaas usa ka likido nga sugnod gikan sa petrolyo nga masunog aron mohatag og kainit ug kalayo para sa pagluto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kinilaw-raw-fish-g6", "domain": "MATTER", "topic": "acid 'cooking' fish in kinilaw", "grades": [5, 6, 7], "terms": ["kinilaw", "kilawin", "hilaw na isda", "raw fish", "suka", "vinegar", "kalamansi", "acid", "asido", "protina", "protein", "denaturation", "pagbabago", "lasaw", "pagkati"], "fact": {"tl": "Sa kinilaw, ang suka o kalamansi ay may asido na nagbabago sa protina ng hilaw na isda kaya tumitigas at nagiging maputi ito na parang luto kahit walang init.", "en": "In kinilaw, the acid in vinegar or kalamansi changes the proteins of raw fish so it firms up and turns white as if cooked, even without heat.", "bis": "Sa kinilaw, ang asido sa suka o kalamansi nag-usab sa protina sa hilaw nga isda mao nga mogahi ug moputi kini nga daw luto bisan walay kainit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kropek-fish-cracker-g5", "domain": "MATTER", "topic": "puffing of fish crackers when fried", "grades": [4, 5, 6], "terms": ["kropek", "kropeck", "fish cracker", "chicharon", "isda", "almirol", "starch", "pagprito", "frying", "singaw", "steam", "lumobo", "expand", "init", "tubig", "gas"], "fact": {"tl": "Kapag pinirito ang kropek, mabilis na sumisingaw ang tubig sa loob ng manipis na almirol kaya ito biglang lumolobo at lumulutong.", "en": "When kropek is deep-fried, the water trapped inside its thin starch quickly turns to steam, making it puff up suddenly and become crisp.", "bis": "Kon iprito ang kropek, paspas mosingaw ang tubig sa sulod sa nipis nga almirol mao nga kalit kining mohubag ug mokrispi."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kubing-jaw-harp-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "kubing jaw harp vibration and sound", "grades": [4, 5, 6, 7], "terms": ["kubing", "jaw harp", "jew's harp", "instrumento", "vibration", "bibrasyon", "tunog", "sound", "tono", "bibig", "mouth", "resonance", "kawayan", "dila ng kubing", "musical instrument"], "fact": {"tl": "Ang kubing ay isang katutubong instrumentong gawa sa kawayan na pinapatunog sa pamamagitan ng pag-alog ng manipis na dila nito habang ginagamit ang bibig bilang silid-tunog.", "en": "The kubing is a native bamboo jaw harp that makes sound when its thin tongue vibrates, while the player's mouth acts as a resonating chamber to shape the tone.", "bis": "Ang kubing usa ka lumad nga instrumento nga kawayan nga motingog kon mokurog ang nipis nga dila niini, samtang ang baba sa nagtugtog mahimong lawak nga tigpalanog sa tono."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kudkuran-coconut-grater-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "friction grates coconut meat", "grades": [3, 4, 5], "terms": ["kudkuran", "kabayo", "coconut grater", "niyog", "coconut", "gata", "kudkod", "grating", "friction", "kuskos", "ngipin ng kudkuran", "metal", "kusina", "laman ng niyog"], "fact": {"tl": "Ang kudkuran ay may matatalim na ngiping bakal na kumukuskos sa laman ng niyog kaya nagkakapira-piraso ito at madaling makukuha ang gata.", "en": "A kudkuran (coconut grater) has sharp metal teeth that scrape against the coconut meat by friction, shredding it so the coconut milk can be squeezed out.", "bis": "Ang kudkuran adunay hait nga ngipon nga puthaw nga mokiskis sa unod sa lubi pinaagi sa pagkuskos, nga mogalingaling niini aron makuha ang gata."}, "source": "NRC PS2.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kudyapi-boat-lute-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "kudyapi two-stringed boat lute", "grades": [4, 5, 6, 7], "terms": ["kudyapi", "boat lute", "kutyapi", "string instrument", "kwerdas", "string", "vibration", "tunog", "sound", "Mindanao", "lumad", "instrumento", "kahoy", "plucked", "kalbahan"], "fact": {"tl": "Ang kudyapi ay isang katutubong instrumentong hugis-bangka na may dalawang kuwerdas, at gumagawa ng tunog kapag pinitik ng daliri ang kuwerdas na umuugong sa loob ng inukit na kahoy.", "en": "The kudyapi is a native boat-shaped lute with two strings that make sound when plucked, vibrating and echoing inside its hollow carved wooden body.", "bis": "Ang kudyapi usa ka lumad nga instrumento nga porma og sakayan nga adunay duha ka kwerdas nga motingog kon kutkuton, nga mokurog ug molanog sulod sa kinulit nga kahoy nga guwang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kulintang-gong-row-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "kulintang gongs and pitch by size", "grades": [4, 5, 6, 7], "terms": ["kulintang", "gong", "agong", "kulintang gongs", "bronze", "tanso", "metal", "tunog", "pitch", "tono", "vibration", "Mindanao", "instrumento", "laki", "size", "mataas na tono", "mababang tono"], "fact": {"tl": "Ang kulintang ay isang hanay ng walong maliliit na tansong gong na magkakaiba ang laki, at ang mas maliit na gong ay gumagawa ng mas mataas na tono kapag pinalo.", "en": "The kulintang is a row of eight small bronze gongs of different sizes, and the smaller gongs make higher-pitched sounds when struck.", "bis": "Ang kulintang usa ka laray sa walo ka gagmay nga bronse nga agong nga magkalainlain og gidak-on, ug ang mas gamay nga agong mohatag og mas taas nga tono kon bunalan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kutsinta-jelly-cake-g5", "domain": "MATTER", "topic": "kutsinta rice cake gelling", "grades": [4, 5, 6], "terms": ["kutsinta", "kakanin", "bigas", "galapong", "lihiya", "lye", "nagiging makunat", "nag-jelly", "rice flour", "annatto", "atsuete", "kakanin nga humok", "nagiging gel"], "fact": {"tl": "Ang kutsinta ay kakaning gawa sa harina ng bigas na hinahaluan ng lihiya, kaya nagiging makunat at parang jelly kapag niluto sa singaw.", "en": "Kutsinta is a rice-flour cake mixed with a little lye, which makes the batter set into a chewy, jelly-like texture when steamed.", "bis": "Ang kutsinta usa ka kakanin nga hinimo sa harina sa bugas nga gisagulan ug gamay nga lihiya, mao nga mahimo kining humok ug morag jelly kung lutoon sa alisngaw."}, "source": "encyclopedia-stable consensus; food science (starch gelatinization)", "generator": "claude-workflow", "reviewed": false},
  {"id": "kwek-kwek-orange-coated-g4", "domain": "MATTER", "topic": "kwek-kwek egg coating color", "grades": [3, 4, 5], "terms": ["kwek-kwek", "itlog", "egg", "balot na orange", "atsuete", "annatto", "harina", "binalot", "pinirito", "kulay", "deep fry", "itlog nga gibalotan", "kolor"], "fact": {"tl": "Ang kwek-kwek ay itlog ng manok o pugo na binalot sa kulay-orange na harina at pinirito; ang kulay ay galing sa atsuete o food coloring.", "en": "Kwek-kwek is a chicken or quail egg coated in orange batter and deep-fried; the bright color comes from annatto (atsuete) or food coloring, not the egg.", "bis": "Ang kwek-kwek usa ka itlog sa manok o buaw nga gibalotan sa orange nga harina ug giprito; ang kolor gikan sa atsuete o food coloring, dili sa itlog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kwek-kwek-frying-cart-scene-g4", "domain": "MATTER", "topic": "deep frying hot oil cooking", "grades": [4, 5, 6], "terms": ["pagprito", "deep fry", "mainit na mantika", "frying", "kumukulo ang mantika", "bula", "tubig", "singaw", "nagiging malutong", "init", "mainit nga mantika", "nagbukal", "alisngaw"], "fact": {"tl": "Sa pagprito, inilulubog ang pagkain sa napakainit na mantika, kaya ang tubig sa loob nito ay mabilis na nagiging singaw at ginagawa itong malutong.", "en": "In deep-frying, food is dipped in very hot oil, so the water inside it quickly turns to steam and the outside becomes crispy.", "bis": "Sa pagprito, ituslob ang pagkaon sa init kaayo nga mantika, mao nga ang tubig sa sulod niini paspas nga mahimong alisngaw ug ang gawas mahimong tagiktik."}, "source": "encyclopedia-stable consensus; states of matter (evaporation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "lab-apron-g5", "domain": "MATTER", "topic": "laboratory safety apron", "grades": [4, 5, 6, 7], "terms": ["lab apron", "epron", "apron", "kaligtasan", "safety", "laboratoryo", "kemikal", "chemical", "nagpoprotekta", "damit", "lab", "panalipod", "kaluwasan", "kemikal nga makadaot", "bisti"], "fact": {"tl": "Ang lab apron ay isinusuot sa laboratoryo upang protektahan ang katawan at damit mula sa tumalsik na kemikal o mainit na bagay.", "en": "A lab apron is worn in the laboratory to protect your body and clothes from chemical splashes or hot materials.", "bis": "Ang lab apron isul-ob sa laboratoryo aron panalipdan ang lawas ug bisti gikan sa nagtagsik nga kemikal o init nga butang."}, "source": "DepEd Science safety practices; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "laing-taro-leaves-g6", "domain": "LIVING_THINGS", "topic": "taro leaves calcium oxalate cooking", "grades": [5, 6, 7], "terms": ["laing", "gabi", "dahon ng gabi", "taro", "taro leaves", "nakakangati", "calcium oxalate", "kristal", "niluto", "gata", "raw", "hilaw", "kati", "dahon sa gabi", "nangati", "kristales"], "fact": {"tl": "Ang laing ay gawa sa tuyong dahon ng gabi na may kristal ng calcium oxalate na nakakangati, kaya kailangan itong lutuin nang husto sa gata bago kainin.", "en": "Laing is made from dried taro leaves, which contain calcium-oxalate crystals that itch the throat, so the leaves must be fully cooked in coconut milk before eating.", "bis": "Ang laing hinimo sa uga nga dahon sa gabi nga adunay kristales sa calcium oxalate nga makakatol, mao nga kinahanglan kini lutoon ug maayo sa gata una kaunon."}, "source": "encyclopedia-stable consensus; plant biology", "generator": "claude-workflow", "reviewed": false},
  {"id": "langit-lupa-chase-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "chasing game running motion", "grades": [3, 4, 5], "terms": ["langit lupa", "habulan", "taya", "laro", "tumatakbo", "running", "chase", "mabilis", "akyat", "mataas", "ligtas", "kusog modagan", "pagdagan", "habol", "dula"], "fact": {"tl": "Sa larong langit-lupa, mabilis kang tumatakbo at umaakyat sa mataas na lugar; mas malayo ang naaabot mo kapag mas malakas mong itinutulak ang paa sa lupa.", "en": "In the game langit-lupa, you run and climb to a high 'safe' spot; you move faster and farther when your feet push harder against the ground.", "bis": "Sa dula nga langit-lupa, modagan ka ug mosaka sa habog nga luwas nga dapit; mas paspas ug mas layo ang imong maabot kung kusgan nimo itulod ang tiil batok sa yuta."}, "source": "encyclopedia-stable consensus; forces and motion (Newton's third law, child level)", "generator": "claude-workflow", "reviewed": false},
  {"id": "latik-coconut-curds-g6", "domain": "MATTER", "topic": "coconut milk fat separation latik", "grades": [5, 6, 7], "terms": ["latik", "gata", "coconut milk", "niyog", "taba", "fat", "nagbubuko", "curds", "kayumanggi", "init", "lumalapot", "natipon na taba", "gata sa lubi", "tambok", "nagbukal"], "fact": {"tl": "Ang latik ay ang kayumanggi at malutong na tira kapag pinakuluan ang gata; ang init ay naghihiwalay ng langis sa solidong taba ng niyog.", "en": "Latik is the brown, crunchy curds left when coconut milk is simmered; the heat separates the oil from the solid coconut fat.", "bis": "Ang latik mao ang kape ug tagiktik nga sobra kung lutoon ang gata; ang kainit nagbulag sa lana gikan sa gahi nga tambok sa lubi."}, "source": "encyclopedia-stable consensus; food science (emulsion breaking)", "generator": "claude-workflow", "reviewed": false},
  {"id": "laud-instrument-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "plucked string instrument sound", "grades": [4, 5, 6], "terms": ["laud", "lute", "kuwerdas", "string", "tunog", "vibration", "nayayanig", "pinipitik", "musika", "hangin", "alon ng tunog", "kuwerdas sa instrumento", "nagkurog", "tingog", "balod sa tingog"], "fact": {"tl": "Ang laud ay instrumentong may kuwerdas; kapag pinipitik ang kuwerdas, ito ay nayayanig at gumagawa ng tunog na kumakalat sa hangin.", "en": "The laud is a stringed instrument; when a string is plucked it vibrates and produces sound waves that travel through the air.", "bis": "Ang laud usa ka instrumento nga adunay kuwerdas; kung kutson ang kuwerdas, kini magkurog ug mohimo ug tingog nga moagi sa hangin."}, "source": "encyclopedia-stable consensus; sound (vibration)", "generator": "claude-workflow", "reviewed": false},
  {"id": "leche-flan-slice-g6", "domain": "MATTER", "topic": "custard egg protein setting", "grades": [5, 6, 7], "terms": ["leche flan", "flan", "itlog", "egg", "gatas", "milk", "custard", "nagsosolido", "protina", "protein", "init", "lumalapot", "tumitigas", "karamelo", "caramel", "itlog ug gatas", "nagagahi"], "fact": {"tl": "Ang leche flan ay gawa sa itlog at gatas; kapag pinasingaw, ang protina sa itlog ay nagdurugtong-durugtong kaya tumitigas ang halo at nagiging makinis.", "en": "Leche flan is made from eggs and milk; when steamed, the egg proteins link together so the mixture sets into a smooth, firm custard.", "bis": "Ang leche flan hinimo sa itlog ug gatas; kung lutoon sa alisngaw, ang protina sa itlog magdugtong-dugtong mao nga ang sagol mogahi ug mahimong hamis."}, "source": "encyclopedia-stable consensus; food science (protein coagulation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "lechon-kawali-slices-g5", "domain": "MATTER", "topic": "frying crispy pork skin water vapor", "grades": [4, 5, 6], "terms": ["lechon kawali", "baboy", "pork", "balat", "skin", "malutong", "crispy", "mantika", "tubig", "singaw", "pinirito", "init", "nagiging tuyo", "balat sa baboy", "tagiktik", "alisngaw"], "fact": {"tl": "Sa lechon kawali, pinipirito ang baboy sa mainit na mantika kaya ang tubig sa balat ay nawawala at nagiging napakalutong nito.", "en": "In lechon kawali, pork is fried in hot oil so the water in the skin escapes as steam, leaving the skin very crispy.", "bis": "Sa lechon kawali, ang baboy giprito sa init nga mantika mao nga ang tubig sa panit mogawas isip alisngaw, nga maghimo sa panit nga tagiktik kaayo."}, "source": "encyclopedia-stable consensus; states of matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "lechon-roast-pig-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "roasting heat transfer cooking", "grades": [4, 5, 6], "terms": ["lechon", "litson", "baboy", "roast pig", "iniihaw", "uling", "apoy", "init", "heat", "niluluto", "umiikot", "fiesta", "pinagliliyaban", "gisugba", "kainit", "kalayo"], "fact": {"tl": "Ang lechon ay buong baboy na iniihaw sa uling o apoy at paikot-ikot na iniinit, kaya unti-unting naluluto ito mula sa labas papasok.", "en": "Lechon is a whole pig roasted over charcoal or fire and turned slowly, so heat moves from the outside inward to cook the meat through.", "bis": "Ang lechon usa ka tibuok baboy nga gisugba sa uling o kalayo ug hinay-hinay nga gituyok, mao nga ang kainit moagi gikan sa gawas paingon sa sulod aron maluto ang karne."}, "source": "encyclopedia-stable consensus; energy (heat transfer)", "generator": "claude-workflow", "reviewed": false},
  {"id": "libbit-conical-drum-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "drum membrane vibration sound", "grades": [4, 5, 6], "terms": ["libbit", "tambol", "drum", "balat", "membrane", "pinapalo", "tunog", "vibration", "nayayanig", "hangin", "alon", "katutubong instrumento", "gibunalan", "tingog", "nagkurog", "balod"], "fact": {"tl": "Ang libbit ay katutubong tambol na may nakaunat na balat; kapag pinalo ito, ang balat ay nayayanig at gumagawa ng malalim na tunog.", "en": "The libbit is a traditional drum with a stretched skin head; striking it makes the skin vibrate and produce a deep sound.", "bis": "Ang libbit usa ka lumad nga tambol nga adunay inunat nga panit; kung bunalan kini, ang panit magkurog ug mohimo ug lawom nga tingog."}, "source": "encyclopedia-stable consensus; sound (vibration)", "generator": "claude-workflow", "reviewed": false},
  {"id": "lighthouse-tower-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "lighthouse light beam navigation", "grades": [4, 5, 6], "terms": ["lighthouse", "parola", "ilaw", "light", "barko", "ship", "dagat", "sea", "umiikot", "beam", "naggagabay", "gabi", "salamin", "lens", "suga", "kahayag", "naggiya"], "fact": {"tl": "Ang parola ay matayog na tore na may malakas na umiikot na ilaw upang gabayan ang mga barko at maiwasan nila ang mababatuhang baybayin sa gabi.", "en": "A lighthouse is a tall tower with a strong rotating light that guides ships and warns them away from rocky shores at night.", "bis": "Ang parola usa ka taas nga tore nga adunay kusgan ug nagtuyok nga suga aron giyahan ang mga barko ug ipahibalo sila nga maglikay sa batoon nga baybayon panahon sa gabii."}, "source": "encyclopedia-stable consensus; light", "generator": "claude-workflow", "reviewed": false},
  {"id": "lomi-thick-noodle-soup-g6", "domain": "MATTER", "topic": "starch thickening soup", "grades": [5, 6, 7], "terms": ["lomi", "sopas", "noodle soup", "pansit", "malapot", "thick", "almirol", "starch", "gawgaw", "kumakapal", "init", "tubig", "lumalapot", "sabaw", "baga nga sabaw", "almidor"], "fact": {"tl": "Ang lomi ay malapot na sopas dahil ang dinurog na almirol o gawgaw ay sumisipsip ng tubig at lumalapot kapag pinainit.", "en": "Lomi is a thick noodle soup because added starch absorbs water and thickens the broth when heated.", "bis": "Ang lomi usa ka baga nga sabaw kay ang gidugang nga almidor mosuyop ug tubig ug mohimo sa sabaw nga baga kung painiton."}, "source": "encyclopedia-stable consensus; food science (starch gelatinization)", "generator": "claude-workflow", "reviewed": false},
  {"id": "longganisa-sausages-g6", "domain": "LIVING_THINGS", "topic": "sausage curing preservation", "grades": [5, 6, 7], "terms": ["longganisa", "sausage", "tsorisong baboy", "karne", "meat", "asin", "salt", "binalot", "bituka", "casing", "tinitira", "preserve", "naiimbak", "asukal", "karne sa baboy", "natipigan"], "fact": {"tl": "Ang longganisa ay tinadtad na karne na may asin at pampalasa na isinusubo sa malinis na bituka; ang asin ay tumutulong itago ito nang mas matagal.", "en": "Longganisa is seasoned ground meat stuffed into a clean casing; the added salt helps preserve it so it keeps longer.", "bis": "Ang longganisa usa ka gigaling nga karne nga gisagulan ug asin ug pahumot ug gisulod sa limpyo nga casing; ang asin motabang aron molungtad kini ug mas dugay."}, "source": "encyclopedia-stable consensus; food preservation", "generator": "claude-workflow", "reviewed": false},
  {"id": "lugaw-plain-porridge-g5", "domain": "MATTER", "topic": "rice porridge starch swelling", "grades": [4, 5, 6], "terms": ["lugaw", "porridge", "kanin", "bigas", "rice", "tubig", "malapot", "thick", "namamaga", "almirol", "starch", "pinakuluan", "lumalambot", "humok nga kanin", "nagbukal", "namuga"], "fact": {"tl": "Ang lugaw ay bigas na pinakuluan sa maraming tubig; ang butil ng bigas ay sumisipsip ng tubig, namamaga, at lumalapot ang halo.", "en": "Lugaw is rice boiled in plenty of water; the rice grains soak up water, swell, and make the mixture thick and soft.", "bis": "Ang lugaw mao ang bugas nga gilutoan sa daghang tubig; ang lugas sa bugas mosuyop ug tubig, moburot, ug mohimo sa sagol nga baga ug humok."}, "source": "encyclopedia-stable consensus; food science (starch gelatinization)", "generator": "claude-workflow", "reviewed": false},
  {"id": "luksong-baka-leapfrog-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "jumping leapfrog gravity", "grades": [3, 4, 5], "terms": ["luksong baka", "leapfrog", "lukso", "jump", "lumukso", "talon", "grabidad", "gravity", "bumababa", "lupa", "paa", "itinutulak", "laro", "ambak", "naglukso", "gibira sa yuta"], "fact": {"tl": "Sa luksong-baka, lumulukso ka pataas sa nakayukong kalaro; pagkatapos, hinihila ka pababa ng grabidad kaya bumababa ka pabalik sa lupa.", "en": "In luksong-baka you jump up over a crouching playmate; gravity then pulls you back down so you land on the ground again.", "bis": "Sa luksong-baka molukso ka pataas ibabaw sa nagkurokot nga kadula; unya, ang grabidad mobira kanimo paubos mao nga manaog ka balik sa yuta."}, "source": "encyclopedia-stable consensus; forces (gravity)", "generator": "claude-workflow", "reviewed": false},
  {"id": "luksong-lubid-jump-rope-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "jump rope timing motion", "grades": [3, 4, 5], "terms": ["luksong lubid", "jump rope", "lubid", "rope", "umiikot", "spinning", "lumukso", "jump", "tiyempo", "timing", "talon", "laro", "naglukso", "naglikot nga pisi", "ambak", "gitiyempo"], "fact": {"tl": "Sa luksong-lubid, kailangan mong lumukso sa tamang sandali habang umiikot ang lubid upang hindi ito tumama sa iyong paa.", "en": "In jump rope (luksong-lubid), you must jump at just the right moment as the rope spins around so it passes under your feet.", "bis": "Sa luksong-lubid, kinahanglan molukso ka sa husto nga higayon samtang nagtuyok ang pisi aron dili kini maigo sa imong tiil."}, "source": "encyclopedia-stable consensus; motion and timing", "generator": "claude-workflow", "reviewed": false},
  {"id": "luksong-tinik-arch-jump-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "high jump leg muscles force", "grades": [3, 4, 5], "terms": ["luksong tinik", "lukso", "jump", "talon", "mataas", "high jump", "tinik", "kamay", "hand stack", "binti", "muscle", "kalamnan", "naglukso", "lakas", "ambak", "tiil nga kusgan"], "fact": {"tl": "Sa luksong-tinik, lumulukso ka pataas at palampas sa magkapatong na kamay; ang lakas ng iyong binti ang nagtutulak sa iyo sa hangin.", "en": "In luksong-tinik you jump high over a stack of hands; the strength of your leg muscles pushes you up into the air.", "bis": "Sa luksong-tinik molukso ka pataas labaw sa nagtapun-og nga mga kamot; ang kusog sa imong batiis maoy motulod kanimo pataas sa hangin."}, "source": "encyclopedia-stable consensus; forces and the body", "generator": "claude-workflow", "reviewed": false},
  {"id": "lumpiang-shanghai-platter-g5", "domain": "MATTER", "topic": "deep frying spring roll wrapper", "grades": [4, 5, 6], "terms": ["lumpiang shanghai", "lumpia", "spring roll", "balat", "wrapper", "pinirito", "fried", "malutong", "crispy", "mantika", "karne", "binalot", "init", "tagiktik", "gibalot", "giprito"], "fact": {"tl": "Ang lumpiang shanghai ay tinadtad na karne na binalot sa manipis na balat at pinirito, kaya nagiging ginto at malutong ang labas nito.", "en": "Lumpiang shanghai is ground meat wrapped in a thin wrapper and deep-fried, so the outside turns golden and crisp.", "bis": "Ang lumpiang shanghai usa ka gigaling nga karne nga gibalot sa nipis nga panit ug giprito, mao nga ang gawas mahimong bulawanon ug tagiktik."}, "source": "encyclopedia-stable consensus; food science", "generator": "claude-workflow", "reviewed": false},
  {"id": "lusong-mortar-pestle-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "mortar and pestle pounding force", "grades": [4, 5, 6], "terms": ["lusong", "almirez", "mortar", "pestle", "halo", "pounding", "binabayo", "dinikdik", "bigas", "puwersa", "force", "dinurog", "nagiging pino", "gibayo", "kusog", "nagdugmok"], "fact": {"tl": "Ang lusong ay malalim na batong lalagyan na may halo (pestle); ang malakas na pagbayo ay dumudurog ng bigas o pampalasa upang maging pino.", "en": "A lusong is a deep stone bowl with a pestle; the strong pounding force crushes rice or spices into a fine powder.", "bis": "Ang lusong usa ka lawom nga bato nga sudlanan nga adunay alho; ang kusog nga pagbayo modugmok sa bugas o panakot aron mahimong pino."}, "source": "encyclopedia-stable consensus; forces (applied force)", "generator": "claude-workflow", "reviewed": false},
  {"id": "macapuno-balls-g6", "domain": "LIVING_THINGS", "topic": "macapuno coconut mutation", "grades": [5, 6, 7], "terms": ["macapuno", "makapuno", "niyog", "coconut", "laman", "gelatinous", "malambot", "mutation", "buko", "espesyal na niyog", "matamis", "lubi", "humok nga unod", "kakaibang niyog", "tam-is"], "fact": {"tl": "Ang macapuno ay espesyal na niyog na halos walang sabaw at puno ng malambot at makapal na laman dahil sa likas na pagbabago sa buto nito.", "en": "Macapuno is a special coconut with almost no water and a soft, thick jelly-like meat, caused by a natural change (mutation) in the seed.", "bis": "Ang macapuno usa ka espesyal nga lubi nga halos walay tubig ug puno sa humok ug baga nga unod tungod sa natural nga kausaban sa liso niini."}, "source": "encyclopedia-stable consensus; plant biology", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnifying-glass-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "magnifying glass convex lens", "grades": [4, 5, 6], "terms": ["magnifying glass", "lente", "lupa", "salaming pampalaki", "lens", "convex", "pinapalaki", "kumbeks", "magnify", "salamin nga magpadako", "magpadako", "tunghaan"], "fact": {"tl": "Ang magnifying glass ay may makapal-sa-gitnang (convex) lente na yumuyukod sa liwanag para mukhang mas malaki ang maliliit na bagay.", "en": "A magnifying glass has a convex lens that bends light so small objects look bigger.", "bis": "Ang magnifying glass adunay convex nga lente nga nagbawog sa kahayag aron ang gagmay nga butang makita nga mas dako."}, "source": "encyclopedia-stable consensus; NRC PS4.B (light/optics)", "generator": "claude-workflow", "reviewed": false},
  {"id": "microscope-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "microscope magnify tiny things", "grades": [5, 6, 7, 8], "terms": ["microscope", "mikroskopyo", "lente", "selula", "cells", "magnify", "pinapalaki", "mikrobyo", "tunghaan", "magpadako", "gagmay nga butang", "objective lens"], "fact": {"tl": "Ang mikroskopyo ay gumagamit ng dalawa o higit pang lente para palakihin ang mga bagay na napakaliit para makita ng mata, gaya ng mga selula at mikrobyo.", "en": "A microscope uses two or more lenses to magnify things too tiny to see with the eye, such as cells and microbes.", "bis": "Ang mikroskopyo naggamit ug duha o kapin pa nga lente aron padakoon ang mga butang nga gagmay kaayo alang sa mata, sama sa mga selula ug mikrobyo."}, "source": "encyclopedia-stable consensus; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "measuring-cup-g3", "domain": "MATTER", "topic": "measuring cup volume liquid", "grades": [3, 4, 5], "terms": ["measuring cup", "panukat na tasa", "sukatan", "milliliter", "mililitro", "dami", "lakas ng tubig", "volume", "sukod", "sukdanan nga tasa", "gidaghanon sa likido"], "fact": {"tl": "Ang measuring cup ay may mga marka na nagsasabi ng dami (volume) ng likido, kadalasang sa mililitro o tasa.", "en": "A measuring cup has marks that tell the volume of a liquid, usually in milliliters or cups.", "bis": "Ang measuring cup adunay mga marka nga nagsulti sa gidaghanon (volume) sa likido, kasagaran sa mililitro o tasa."}, "source": "encyclopedia-stable consensus; DepEd G3 measurement", "generator": "claude-workflow", "reviewed": false},
  {"id": "measuring-spoons-g3", "domain": "MATTER", "topic": "measuring spoons small volume", "grades": [3, 4, 5], "terms": ["measuring spoons", "panukat na kutsara", "kutsarita", "teaspoon", "tablespoon", "sukatan", "sukod", "gamay nga sukdanan", "kutsara nga sukdanan", "volume"], "fact": {"tl": "Ang measuring spoons ay magkakaibang laki ng kutsara para tumpak na sukatin ang maliliit na dami, gaya ng kutsarita at kutsara.", "en": "Measuring spoons are spoons of set sizes used to measure small amounts exactly, like a teaspoon or a tablespoon.", "bis": "Ang measuring spoons mao ang mga kutsara nga lain-lain ug gidak-on aron sukdon pag-ayo ang gagmay nga gidaghanon, sama sa kutsarita ug kutsara."}, "source": "encyclopedia-stable consensus; DepEd G3 measurement", "generator": "claude-workflow", "reviewed": false},
  {"id": "meter-stick-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "meter stick measuring length", "grades": [3, 4, 5], "terms": ["meter stick", "metro", "panukat", "haba", "length", "sentimetro", "centimeter", "sukatan ng haba", "sukdanan", "gitas-on", "metro nga kahoy", "sukod"], "fact": {"tl": "Ang meter stick ay isang patpat na may haba na isang metro, na may marka kada sentimetro para sukatin ang haba ng mga bagay.", "en": "A meter stick is a stick one meter long, marked every centimeter, used to measure how long things are.", "bis": "Ang meter stick usa ka kahoy nga usa ka metro ang gitas-on, nga may marka matag sentimetro aron sukdon ang gitas-on sa mga butang."}, "source": "encyclopedia-stable consensus; DepEd G3 measurement", "generator": "claude-workflow", "reviewed": false},
  {"id": "mango-fruit-g4", "domain": "LIVING_THINGS", "topic": "mango Philippine national fruit", "grades": [3, 4, 5, 6], "terms": ["mango", "mangga", "manga", "national fruit", "pambansang prutas", "carabao mango", "hilaw", "hinog", "ripe", "bunga", "prutas", "punong mangga", "kahoy nga mangga", "bitamina C"], "fact": {"tl": "Ang mangga ay pambansang prutas ng Pilipinas; ito ay matamis kapag hinog, dilaw ang laman, at sagana sa bitamina C.", "en": "The mango is the national fruit of the Philippines; it is sweet when ripe, has yellow flesh, and is rich in vitamin C.", "bis": "Ang mangga mao ang nasudnong prutas sa Pilipinas; tam-is kini kon hinog, dalag ang unod, ug daghan ug bitamina C."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "banana-fritter-maruya-g4", "domain": "LIVING_THINGS", "topic": "banana saba cooking starch", "grades": [4, 5, 6], "terms": ["banana", "saging", "saba", "maruya", "fritter", "minatamis", "almirol", "starch", "karbohidrato", "carbohydrate", "potassium", "saging nga saba", "prutas", "energy", "enerhiya"], "fact": {"tl": "Ang maruya ay piniritong saging na saba; ang saging ay puno ng karbohidrato (almirol) na nagbibigay ng enerhiya sa katawan.", "en": "Maruya is fried saba banana; bananas are full of carbohydrates (starch) that give the body energy.", "bis": "Ang maruya mao ang giprito nga saging nga saba; ang saging puno ug karbohidrato (almirol) nga naghatag ug kusog sa lawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "coconut-maja-blanca-g5", "domain": "MATTER", "topic": "coconut milk thickening cornstarch gel", "grades": [5, 6, 7], "terms": ["maja blanca", "coconut", "niyog", "gata", "coconut milk", "cornstarch", "gawgaw", "lumalapot", "thicken", "gel", "lugaw", "pagkulo", "init", "lumapot", "humigpit", "almirol"], "fact": {"tl": "Ang maja blanca ay lumalapot dahil ang gawgaw (cornstarch) sa gata ay sumisipsip ng tubig at namamaga kapag pinainit, na bumubuo ng makapal na gel.", "en": "Maja blanca thickens because the cornstarch in coconut milk absorbs water and swells when heated, forming a thick gel.", "bis": "Ang maja blanca molapot tungod kay ang gawgaw (cornstarch) sa gata mosuyop ug tubig ug mohubag kon initon, nga maghimo ug baga nga gel."}, "source": "encyclopedia-stable consensus (starch gelatinization)", "generator": "claude-workflow", "reviewed": false},
  {"id": "minatamis-na-bao-g5", "domain": "MATTER", "topic": "coconut sap sugar caramelization", "grades": [5, 6, 7], "terms": ["minatamis", "bao", "young coconut", "buko", "niyog", "asukal", "sugar", "caramel", "panghimagas", "matamis", "pagluto", "init", "katam-is", "lutuon", "syrup"], "fact": {"tl": "Ang minatamis na bao ay gawa sa malambot na laman ng batang niyog na niluto sa asukal hanggang lumapot ito at maging matamis na panghimagas.", "en": "Minatamis na bao is made from the soft flesh of young coconut cooked in sugar until it thickens into a sweet dessert.", "bis": "Ang minatamis na bao gihimo gikan sa humok nga unod sa batan-ong lubi nga giluto sa asukal hangtod molapot nga tam-is nga panghimagas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "milking-carabao-g4", "domain": "LIVING_THINGS", "topic": "carabao milk mammal dairy", "grades": [3, 4, 5], "terms": ["carabao", "kalabaw", "gatas", "milk", "milking", "mammal", "mamalya", "suso", "udder", "kabaw", "pagsuso", "hayop", "katas ng gatas", "kremoso", "calcium"], "fact": {"tl": "Ang kalabaw ay isang mamalya, kaya naggagatas ito para sa anak nito; ang gatas ng kalabaw ay mas malapot at mataas sa calcium kaysa sa karaniwang gatas.", "en": "The carabao is a mammal, so it produces milk for its young; carabao milk is thicker and higher in calcium than ordinary milk.", "bis": "Ang kabaw usa ka mamalya, busa nagagatas kini para sa nati niini; ang gatas sa kabaw mas baga ug mas taas ug calcium kaysa ordinaryo nga gatas."}, "source": "encyclopedia-stable consensus; NRC LS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "mais-con-yelo-melting-g4", "domain": "MATTER", "topic": "ice melting state change cold dessert", "grades": [3, 4, 5], "terms": ["mais con yelo", "yelo", "ice", "natutunaw", "melting", "solido", "likido", "solid", "liquid", "init", "lamig", "estado", "kinatomtang", "natunaw", "mais", "corn"], "fact": {"tl": "Sa mais con yelo, ang dinurog na yelo ay unti-unting natutunaw mula solido tungo sa likido habang sumisipsip ng init mula sa gatas at mais sa paligid.", "en": "In mais con yelo, the shaved ice slowly melts from solid to liquid as it absorbs heat from the milk and corn around it.", "bis": "Sa mais con yelo, ang dinugmok nga yelo hinay-hinay nga matunaw gikan sa solido ngadto sa likido samtang nagsuyop kini ug kainit gikan sa gatas ug mais sa palibot."}, "source": "encyclopedia-stable consensus; NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "melon-juice-g4", "domain": "LIVING_THINGS", "topic": "melon fruit water content vine", "grades": [3, 4, 5], "terms": ["melon", "milon", "cantaloupe", "juice", "katas", "prutas", "tubig", "water content", "baging", "vine", "matamis", "fruit", "bunga", "hilaw", "hinog", "bitamina"], "fact": {"tl": "Ang melon ay isang prutas na tumutubo sa gumagapang na baging at puno ng tubig, kaya pwedeng gawing malamig na juice.", "en": "Melon is a fruit that grows on a creeping vine and is full of water, so it can be made into a cool juice.", "bis": "Ang milon usa ka prutas nga motubo sa nagakamang nga baging ug puno ug tubig, busa mahimong himoong bugnaw nga juice."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mami-noodle-bowl-g5", "domain": "MATTER", "topic": "hot broth steam condensation evaporation", "grades": [4, 5, 6], "terms": ["mami", "noodle", "sabaw", "broth", "singaw", "steam", "usok", "evaporation", "pagsingaw", "init", "mainit", "alisngaw", "kondensasyon", "pansit", "tubig"], "fact": {"tl": "Ang singaw na umaakyat mula sa mainit na sabaw ng mami ay tubig na sumingaw dahil sa init, na bumabalik sa likido kapag tumama sa malamig na bagay.", "en": "The steam rising from a hot bowl of mami is water that evaporated from the heat, turning back to liquid when it meets something cool.", "bis": "Ang aso nga mosaka gikan sa init nga sabaw sa mami mao ang tubig nga mialisngaw tungod sa kainit, nga mobalik sa likido kon makasugat ug bugnaw nga butang."}, "source": "encyclopedia-stable consensus; NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "maracas-pair-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "maracas sound vibration percussion", "grades": [3, 4, 5], "terms": ["maracas", "kalansing", "tunog", "sound", "vibration", "pag-uga", "shake", "yanig", "tunog ng instrumento", "alog", "bagting", "instrumento", "buto", "lansing"], "fact": {"tl": "Ang maracas ay gumagawa ng tunog kapag inaalog, dahil ang maliliit na butil sa loob ay tumatama sa dingding nito at nagpapayanig ng hangin.", "en": "Maracas make sound when shaken, because the small beads inside strike the shell and make the air vibrate.", "bis": "Ang maracas mohimo ug tunog kon uy-ogon, tungod kay ang gagmay nga butil sa sulod motagbo sa bungbong niini ug magpakurog sa hangin."}, "source": "encyclopedia-stable consensus; NRC PS4.A (sound/vibration)", "generator": "claude-workflow", "reviewed": false},
  {"id": "manununggul-jar-g6", "domain": "EARTH_SPACE", "topic": "Manunggul jar clay pottery artifact", "grades": [5, 6, 7, 8], "terms": ["manunggul jar", "manununggul", "burial jar", "lalagyan", "earthenware", "luwad", "clay", "lutong putik", "palayok", "Palawan", "artifact", "kolon", "kulon", "pottery", "kalumbo"], "fact": {"tl": "Ang Manunggul Jar ay isang sinaunang lalagyang yari sa hinubog na luwad na pinatigas sa apoy, natagpuan sa isang kweba sa Palawan at libu-libong taong gulang.", "en": "The Manunggul Jar is an ancient burial jar made of shaped clay hardened by fire, found in a Palawan cave and thousands of years old.", "bis": "Ang Manunggul Jar usa ka karaang lalagyan nga hinimo sa giumol nga lapok nga gipagahi sa kalayo, nakit-an sa usa ka langob sa Palawan ug liboan ka tuig na ang edad."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "monay-bread-bun-g4", "domain": "MATTER", "topic": "yeast fermentation makes bread rise", "grades": [4, 5, 6], "terms": ["monay", "tinapay", "pandesal", "lebadura", "yeast", "pampaalsa", "umaalsa", "bread", "fermentation", "carbon dioxide", "pan", "pagluto"], "fact": {"tl": "Ang monay ay isang tinapay na umaalsa dahil ang lebadura sa masa ay gumagawa ng gas na carbon dioxide na nagdudulot ng maliliit na butas sa loob.", "en": "Monay is a soft bread bun that rises because yeast in the dough makes carbon dioxide gas, forming tiny air pockets inside.", "bis": "Ang monay usa ka humok nga tinapay nga mosaka tungod kay ang lebadura sa minasa naghimo ug gas nga carbon dioxide nga maghimo ug gagmay nga mga lungag sa sulod."}, "source": "encyclopedia-stable consensus; NRC PS1.B (chemical change)", "generator": "claude-workflow", "reviewed": false},
  {"id": "mongo-con-hielo-g3", "domain": "MATTER", "topic": "ice melts absorbing heat in a cold dessert", "grades": [3, 4, 5], "terms": ["mongo con hielo", "yelo", "ice", "natutunaw", "melting", "monggo", "mung bean", "matamis na panghimagas", "lamig", "init", "nagiging tubig"], "fact": {"tl": "Sa mongo con hielo, ang yelo ay natutunaw at nagiging tubig dahil sumisipsip ito ng init mula sa matamis na monggo, kaya lumalamig ang panghimagas.", "en": "In mongo con hielo, the ice melts into water by absorbing heat from the sweet mung beans, which is why the dessert turns cold.", "bis": "Sa mongo con hielo, ang yelo matunaw ngadto sa tubig kay mosuyop kini sa kainit gikan sa tam-is nga monggo, mao nga mobugnaw ang panghimagas."}, "source": "encyclopedia-stable consensus; NRC PS3.B (heat transfer)", "generator": "claude-workflow", "reviewed": false},
  {"id": "moron-chocolate-rice-g4", "domain": "LIVING_THINGS", "topic": "cacao seeds become chocolate", "grades": [4, 5, 6], "terms": ["moron", "tsokolate", "chocolate", "cacao", "kakaw", "buto", "seed", "malagkit", "rice", "kakanin", "Leyte", "halaman"], "fact": {"tl": "Ang moron ay isang kakaning malagkit na may tsokolate na gawa sa pinroseso at giniling na buto ng kakaw mula sa halamang cacao.", "en": "Moron is a sweet sticky-rice roll flavored with chocolate, which comes from the ground, roasted seeds of the cacao plant.", "bis": "Ang moron usa ka tam-is nga pilit nga adunay tsokolate nga gikan sa giprocesso ug giligis nga liso sa tanom nga kakaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "nata-de-coco-cubes-g6", "domain": "LIVING_THINGS", "topic": "bacteria make nata de coco from coconut water", "grades": [6, 7, 8], "terms": ["nata de coco", "bakterya", "bacteria", "Acetobacter", "tubig ng niyog", "coconut water", "selulosa", "cellulose", "pagbuburo", "fermentation", "kakanin", "microbe"], "fact": {"tl": "Ang malutong na nata de coco ay gawa ng bakteryang nagbuburo ng tubig ng niyog at gumagawa ng makapal na selulosa na pwedeng kainin.", "en": "The chewy nata de coco is made by bacteria that ferment coconut water and build up a thick, edible mat of cellulose.", "bis": "Ang nata de coco gihimo sa bakterya nga mag-fermento sa tubig sa lubi ug magtukod ug baga nga selulosa nga makaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "native-broom-walis-tingting-g3", "domain": "LIVING_THINGS", "topic": "broom made from coconut leaf midribs", "grades": [3, 4, 5], "terms": ["walis tingting", "walis", "broom", "tingting", "niyog", "coconut", "tahi ng dahon", "midrib", "palwa", "dahon", "leaf", "halaman", "Pilipinas"], "fact": {"tl": "Ang walis tingting ay gawa sa matitigas na gitna ng dahon ng niyog na tinatawag na tingting, na pinatuyo at binigkis bago gamitin sa paglilinis.", "en": "The walis tingting broom is made from the stiff midribs of coconut leaves, which are dried and tied together for sweeping.", "bis": "Ang walis tingting hinimo gikan sa gahi nga tunga sa dahon sa lubi nga gitawag tingting, nga gipauga ug gihigot aron gamiton sa paglimpyo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "neighborhood-zumba-morning-scene-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "exercise uses food energy and speeds the heartbeat", "grades": [4, 5, 6], "terms": ["zumba", "ehersisyo", "exercise", "sayaw", "dance", "enerhiya", "energy", "puso", "heart", "tibok", "hininga", "pawis", "katawan", "kalusugan"], "fact": {"tl": "Sa pag-zumba, ginagamit ng katawan ang enerhiya mula sa pagkain kaya bumibilis ang tibok ng puso at hininga upang magdala ng mas maraming oxygen sa mga kalamnan.", "en": "During zumba, the body uses energy from food, so the heart beats faster and breathing speeds up to bring more oxygen to the muscles.", "bis": "Sa zumba, gigamit sa lawas ang enerhiya gikan sa pagkaon mao nga mokusog ang pitik sa kasingkasing ug ang ginhawa aron magdala ug daghang oxygen sa kaunoran."}, "source": "encyclopedia-stable consensus; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "new-year-torotot-horns-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "horns make sound from vibrating air", "grades": [4, 5, 6], "terms": ["torotot", "horn", "tambuli", "tunog", "sound", "vibration", "panginig", "hangin", "air", "bagong taon", "new year", "ihip", "blow", "wave"], "fact": {"tl": "Kapag hinihipan ang torotot, ang hangin sa loob nito ay nanginginig at gumagawa ng malakas na tunog na umaabot sa ating tainga.", "en": "When you blow a torotot horn, the air inside it vibrates and makes a loud sound that travels through the air to your ears.", "bis": "Kon huypan ang torotot, ang hangin sa sulod niini mokurog ug maghimo ug kusog nga tingog nga moabot sa atong dalunggan."}, "source": "encyclopedia-stable consensus; NRC PS4.A (sound)", "generator": "claude-workflow", "reviewed": false},
  {"id": "nilagang-baboy-soup-g3", "domain": "MATTER", "topic": "boiling water cooks soup with heat", "grades": [3, 4, 5], "terms": ["nilagang baboy", "nilaga", "boil", "kumukulo", "boiling", "init", "heat", "tubig", "water", "sabaw", "soup", "singaw", "steam", "luto"], "fact": {"tl": "Sa nilagang baboy, ang kumukulong tubig ay umaabot sa napakainit na temperatura na nagpapaluto sa karne at gulay, at ang ilang tubig ay nagiging singaw.", "en": "In nilagang baboy, boiling water reaches a very hot temperature that cooks the meat and vegetables, and some of the water turns into steam.", "bis": "Sa nilagang baboy, ang nagbukal nga tubig moabot sa init kaayo nga temperatura nga magluto sa karne ug utanon, ug ang uban nga tubig mahimong alisngaw."}, "source": "encyclopedia-stable consensus; NRC PS3.B (heat transfer)", "generator": "claude-workflow", "reviewed": false},
  {"id": "nilupak-mashed-cassava-g4", "domain": "LIVING_THINGS", "topic": "cassava is a starchy root crop", "grades": [4, 5, 6], "terms": ["nilupak", "kamoteng kahoy", "cassava", "balanghoy", "ugat", "root", "almirol", "starch", "carbohydrate", "kakanin", "halaman", "lupa", "pagkain"], "fact": {"tl": "Ang nilupak ay gawa sa dinikdik na kamoteng kahoy, isang ugat na halaman na nag-iimbak ng almirol na nagbibigay ng enerhiya sa katawan.", "en": "Nilupak is made from pounded cassava, a root crop that stores starch, giving the body energy.", "bis": "Ang nilupak hinimo sa giduktok nga balanghoy, usa ka gamot nga tanom nga magtipig ug almirol nga maghatag ug enerhiya sa lawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "nipa-hut-bahay-kubo-scene-g4", "domain": "LIVING_THINGS", "topic": "bahay kubo built from bamboo and nipa palm", "grades": [4, 5, 6], "terms": ["bahay kubo", "nipa hut", "kawayan", "bamboo", "pawid", "nipa", "kogon", "dahon", "leaf", "halaman", "bahay", "house", "materyales", "Pilipinas"], "fact": {"tl": "Ang bahay kubo ay gawa sa mga halaman tulad ng kawayan para sa balangkas at pawid na dahon ng nipa para sa bubong, na pawang mga likas na materyales.", "en": "The bahay kubo is built from plants such as bamboo for its frame and nipa palm leaves for its roof, all natural materials.", "bis": "Ang bahay kubo gitukod gikan sa mga tanom sama sa kawayan alang sa balangkas ug dahon sa nipa alang sa atop, tanan natural nga materyales."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "nipa-hut-on-stilts-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "stilt houses stay above floodwater", "grades": [5, 6, 7], "terms": ["bahay kubo", "stilt", "haligi", "post", "baha", "flood", "nakaangat", "raised", "tubig", "water", "hangin", "ventilation", "pamayanan", "Pilipinas"], "fact": {"tl": "Maraming bahay kubo ang nakatayo sa matataas na haligi upang manatiling tuyo ang loob kapag may baha at upang makapasok ang hangin sa ilalim.", "en": "Many nipa huts stand on tall posts so the inside stays dry during floods and cool air can pass underneath.", "bis": "Daghang bahay kubo nagbarog sa tag-as nga mga haligi aron magpabilin nga uga ang sulod kon mobaha ug aron makasulod ang hangin sa ilawom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "nipa-roof-thatching-scene-g5", "domain": "LIVING_THINGS", "topic": "nipa palm leaves used for waterproof roofing", "grades": [5, 6, 7], "terms": ["pawid", "nipa", "nipa palm", "sasa", "bubong", "roof", "thatch", "dahon", "leaf", "halaman", "bakawan", "mangrove", "ulan", "rain", "tubig-alat"], "fact": {"tl": "Ang pawid na bubong ay gawa sa pinatuyong dahon ng nipa, isang palmang tumutubo sa maalat na tubig malapit sa baybayin, at ito ay sumasalo sa ulan.", "en": "Thatched roofs are made from dried nipa palm leaves, a palm that grows in salty water near coasts, and they shed rain well.", "bis": "Ang pawid nga atop hinimo sa pinauga nga dahon sa nipa, usa ka palma nga motubo sa parat nga tubig duol sa baybayon, ug kini makasalo sa ulan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "nose-flute-tongali-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "nose flute makes sound from vibrating air column", "grades": [5, 6, 7], "terms": ["tongali", "nose flute", "plawta", "flute", "ilong", "nose", "hangin", "air", "tunog", "sound", "vibration", "kawayan", "bamboo", "Kalinga", "katutubo"], "fact": {"tl": "Ang tongali ay isang plawtang kawayan na hinihipan gamit ang hangin mula sa ilong, at ang nanginginig na hangin sa loob nito ang gumagawa ng tunog.", "en": "The tongali is a bamboo flute played with air blown from the nose, and the vibrating column of air inside it produces the sound.", "bis": "Ang tongali usa ka kawayan nga plawta nga huypan gamit ang hangin gikan sa ilong, ug ang nagkurog nga hangin sa sulod niini maoy maghimo sa tingog."}, "source": "encyclopedia-stable consensus; NRC PS4.A (sound)", "generator": "claude-workflow", "reviewed": false},
  {"id": "notebook-school-g4", "domain": "MATTER", "topic": "paper is made from wood fibers of trees", "grades": [4, 5, 6], "terms": ["notebook", "kwaderno", "papel", "paper", "kahoy", "wood", "puno", "tree", "himaymay", "fiber", "pulp", "selulosa", "gawa", "recycle"], "fact": {"tl": "Ang papel sa kwaderno ay gawa sa pinong himaymay ng kahoy mula sa mga puno, na dinurog at pinipis bago patuyuin.", "en": "The paper in a notebook is made from tiny wood fibers from trees, which are mashed into pulp, pressed flat, and dried.", "bis": "Ang papel sa kwaderno hinimo gikan sa gagmay nga himaymay sa kahoy gikan sa mga kahoy, nga giduktok ngadto sa pulp, gipig-ot, ug gipauga."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "octavina-instrument-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "string instrument makes sound from vibrating strings", "grades": [5, 6, 7], "terms": ["octavina", "instrumento", "string instrument", "kwerdas", "string", "rondalla", "tunog", "sound", "vibration", "panginig", "pitch", "tono", "musika", "kahoy"], "fact": {"tl": "Ang octavina ay isang instrumentong may kwerdas na ginagamit sa rondalla, at ang tunog nito ay nagmumula sa nanginginig na kwerdas kapag pinipindot o kinakalbit.", "en": "The octavina is a stringed instrument used in the rondalla, and its sound comes from strings that vibrate when plucked.", "bis": "Ang octavina usa ka instrumento nga adunay kwerdas nga gamiton sa rondalla, ug ang tingog niini gikan sa nagkurog nga kwerdas kon kalboton."}, "source": "encyclopedia-stable consensus; NRC PS4.A (sound)", "generator": "claude-workflow", "reviewed": false},
  {"id": "okoy-stack-g4", "domain": "MATTER", "topic": "frying cooks food in very hot oil", "grades": [4, 5, 6], "terms": ["okoy", "ukoy", "prito", "fry", "fried", "mantika", "oil", "init", "heat", "hipon", "shrimp", "crispy", "malutong", "luto", "kainan"], "fact": {"tl": "Ang okoy ay piniritong hipon at gulay na inilubog sa napakainit na mantika, na nagpapatuyo sa labas kaya ito nagiging malutong.", "en": "Okoy is a shrimp-and-vegetable fritter cooked in very hot oil, which dries the outside and makes it crispy.", "bis": "Ang okoy usa ka prito nga hipon ug utanon nga giluto sa init kaayo nga mantika, nga magpauga sa gawas mao nga mahimong kuyamis."}, "source": "encyclopedia-stable consensus; NRC PS3.B (heat transfer)", "generator": "claude-workflow", "reviewed": false},
  {"id": "pabitin-game-lowering-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "gravity pulls the pabitin frame down when the rope is released", "grades": [5, 6, 7], "terms": ["pabitin", "laro", "game", "lubid", "rope", "gravity", "grabidad", "hatak", "pull", "pababa", "lower", "regalo", "fiesta", "puwersa", "force"], "fact": {"tl": "Sa larong pabitin, hinihila pababa ng grabidad ang balangkas na nakabitin sa lubid, kaya kapag ibinaba ito, bumababa ito sa abot ng mga batang nagtatalon.", "en": "In the pabitin game, gravity pulls the hanging frame downward, so when the rope is lowered the prizes come within reach of the jumping children.", "bis": "Sa dula nga pabitin, ang grabidad mobira paubos sa balangkas nga nagbitay sa pisi, mao nga kon ipaubos kini, makab-ot na sa naglukso nga mga bata."}, "source": "encyclopedia-stable consensus; NRC PS2.B (gravity)", "generator": "claude-workflow", "reviewed": false},
  {"id": "pahiyas-arch-of-fruit-g4", "domain": "LIVING_THINGS", "topic": "fruits are seed-bearing parts of plants", "grades": [3, 4, 5], "terms": ["prutas", "bunga", "buto", "halaman", "ani", "pahiyas", "liso", "tanom", "fruit", "seed", "harvest", "plant", "Pahiyas"], "fact": {"tl": "Sa Pahiyas Festival ng Lucban, ipinagdiriwang ng mga magsasaka ang masaganang ani, at ang mga prutas na ginagamit pandekorasyon ay galing sa mga halaman at naglalaman ng buto na puwedeng tumubo.", "en": "At Lucban's Pahiyas Festival farmers celebrate a good harvest, and the fruits used as decoration grow on plants and hold seeds that can sprout into new plants.", "bis": "Sa Pahiyas Festival sa Lucban gisaulog sa mga mag-uuma ang maayong ani, ug ang mga prutas nga gigamit nga dekorasyon nagtubo sa mga tanom ug naay liso nga makaturok og bag-ong tanom."}, "source": "encyclopedia-stable consensus; DepEd G4 Plant parts", "generator": "claude-workflow", "reviewed": false},
  {"id": "pahiyas-kiping-chandelier-g5", "domain": "MATTER", "topic": "kiping is rice-flour dough shaped and dried", "grades": [4, 5, 6], "terms": ["kiping", "bigas", "harina", "dahon", "hugis", "bugas", "kiping wafer", "rice", "leaf-shaped", "wafer", "Pahiyas"], "fact": {"tl": "Ang kiping ay gawa sa giniling na bigas na ginawang masa, hinugis na parang dahon, at pinatuyo bago kulayan—isang halimbawa ng pagbabago ng anyo ng pagkain sa pagluluto.", "en": "Kiping is made from ground rice turned into a paste, shaped like a leaf, and dried before coloring—an example of how food changes form when it is cooked and dried.", "bis": "Ang kiping hinimo gikan sa giniling nga bugas nga gihimong masa, gihulma nga morag dahon, ug gipauga sa dili pa kolorohan—usa ka pananglitan sa pag-usab og porma sa pagkaon kon lutoon ug pauga-on."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "palayok-clay-cooking-pot-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "clay pots conduct heat to cook food", "grades": [4, 5, 6], "terms": ["palayok", "luwad", "putik", "init", "luto", "apoy", "kaldero", "kolon", "yutang-kulonon", "kalayo", "clay pot", "earthenware", "heat", "cook", "fire"], "fact": {"tl": "Ang palayok ay gawa sa luwad na hinubog at sinunog sa apoy para tumigas, at kapag inilagay sa kalan, dumadaan ang init mula sa apoy patungo sa pagkaing niluluto sa loob.", "en": "A palayok is made of clay shaped and fired hard, and when placed over a stove the heat travels from the fire through the pot to cook the food inside.", "bis": "Ang palayok hinimo sa yutang-kulonon nga gihulma ug gisunog aron motig-a, ug kon ibutang sa kalan, moagi ang init gikan sa kalayo padulong sa pagkaon nga giluto sa sulod."}, "source": "encyclopedia-stable consensus; NRC PS3 heat transfer", "generator": "claude-workflow", "reviewed": false},
  {"id": "palayok-game-blindfold-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "blindfold game relies on senses other than sight", "grades": [3, 4, 5], "terms": ["palayok", "laro", "piring", "mata", "pandama", "pakikinig", "dula", "tabon sa mata", "pamati", "blindfold", "sense", "hearing", "touch", "game"], "fact": {"tl": "Sa larong pukpok-palayok na may piring sa mata, umaasa ang manlalaro sa kanyang pandinig at pandama sa halip na paningin para mahanap ang nakabitin na palayok.", "en": "In the blindfolded pukpok-palayok game, the player relies on hearing and touch instead of sight to find the hanging clay pot.", "bis": "Sa dula nga pukpok-palayok nga gitabonan ang mata, ang magdudula nagsalig sa iyang pandungog ug paghikap imbes panan-aw aron makit-an ang nagbitay nga palayok."}, "source": "encyclopedia-stable consensus; DepEd G4 Senses", "generator": "claude-workflow", "reviewed": false},
  {"id": "palaspas-palm-sunday-g4", "domain": "LIVING_THINGS", "topic": "palm fronds are leaves of palm trees", "grades": [3, 4, 5], "terms": ["palaspas", "palma", "niyog", "dahon", "punong-kahoy", "Linggo ng Palaspas", "lubi", "kahoy", "palwa", "palm", "frond", "leaf", "palm tree", "coconut"], "fact": {"tl": "Ang palaspas na hawak tuwing Linggo ng Palaspas ay yari sa mga batang dahon ng punong palma o niyog, kung saan ginagawa ng dahon ang pagkain ng puno mula sa sikat ng araw.", "en": "The palaspas held on Palm Sunday is made from the young leaves of palm or coconut trees, where leaves make the tree's food from sunlight.", "bis": "Ang palaspas nga gigunitan panahon sa Domingo sa Palaspas hinimo gikan sa batan-ong dahon sa palma o lubi nga kahoy, diin ang dahon naghimo sa pagkaon sa kahoy gikan sa kahayag sa adlaw."}, "source": "encyclopedia-stable consensus; AAAS 5C plant nutrition", "generator": "claude-workflow", "reviewed": false},
  {"id": "palaspas-woven-frond-g4", "domain": "LIVING_THINGS", "topic": "palm leaves can be woven because fronds are long and flexible", "grades": [3, 4, 5], "terms": ["palaspas", "habi", "lala", "dahon", "palma", "malambot", "paglala", "humok", "woven", "palm leaf", "frond", "flexible", "weave"], "fact": {"tl": "Maaaring lalahin ang palaspas dahil ang batang dahon ng palma ay mahaba, manipis, at malambot kaya madaling baluktutin nang hindi nababali.", "en": "Palm fronds can be woven because the young palm leaves are long, thin, and flexible, so they bend easily without breaking.", "bis": "Mahimong lalahon ang palaspas tungod kay ang batan-ong dahon sa palma taas, nipis, ug humok mao nga sayon ibawog nga dili mabali."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "palitaw-flat-cake-g5", "domain": "MATTER", "topic": "cooked dough floats when it is done", "grades": [4, 5, 6], "terms": ["palitaw", "malagkit", "litaw", "lutang", "tubig", "kumukulo", "kakanin", "pilit", "lutaw", "float", "boil", "glutinous rice", "sticky rice"], "fact": {"tl": "Ang palitaw ay gawa sa giling na malagkit na bigas, at ito ay lumulutang sa kumukulong tubig kapag luto na—dahil dito nagmula ang pangalan nitong 'litaw'.", "en": "Palitaw is made from ground glutinous rice, and it floats to the top of the boiling water when it is cooked—which is how it got its name from 'litaw' (to surface).", "bis": "Ang palitaw hinimo gikan sa giniling nga pilit nga bugas, ug molutaw kini sa nagbukal nga tubig kon luto na—mao kini ang gigikanan sa ngalan niini gikan sa 'litaw'."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "palo-sebo-greased-pole-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "grease reduces friction making the pole slippery", "grades": [5, 6, 7], "terms": ["palo sebo", "mantika", "grasa", "madulas", "alpas", "friction", "kuskos", "tambok", "danlog", "greased pole", "grease", "slippery", "climb"], "fact": {"tl": "Mahirap akyatin ang poste sa palo sebo dahil ang grasa o mantika ay nagpapababa ng friction o kuskusan sa pagitan ng kamay at kahoy kaya nadudulas ang umaakyat.", "en": "The pole in palo sebo is hard to climb because the grease lowers the friction between the hands and the wood, making the climber slip.", "bis": "Lisod sak-on ang poste sa palo sebo tungod kay ang tambok o mantika nagpaubos sa friction o kuskusanay tali sa kamot ug kahoy mao nga madanlog ang nagsaka."}, "source": "encyclopedia-stable consensus; NRC PS2 forces, friction", "generator": "claude-workflow", "reviewed": false},
  {"id": "pamaypay-hand-fan-g4", "domain": "MATTER", "topic": "fanning moves air to cool by evaporation", "grades": [4, 5, 6], "terms": ["pamaypay", "abaniko", "hangin", "init", "pawis", "lamig", "paypay", "singot", "fan", "air", "cool", "sweat", "evaporation"], "fact": {"tl": "Kapag nagpapaypay tayo gamit ang pamaypay, pinakikilos nito ang hangin sa ating balat na nagpapabilis ng pagsingaw ng pawis kaya nakakaramdam tayo ng lamig.", "en": "When we wave a hand fan, it moves air across our skin, which speeds up the evaporation of sweat and makes us feel cooler.", "bis": "Kon magpaypay ta gamit ang pamaypay, gipalihok niini ang hangin sa atong panit nga nagpadali sa pag-alisngaw sa singot mao nga mobati ta og kabugnaw."}, "source": "encyclopedia-stable consensus; NRC PS1 evaporation", "generator": "claude-workflow", "reviewed": false},
  {"id": "pamaypay-woven-fan-g4", "domain": "LIVING_THINGS", "topic": "fans are woven from plant fibers like buri palm or bamboo", "grades": [3, 4, 5], "terms": ["pamaypay", "buri", "kawayan", "habi", "hibla", "halaman", "paypay", "lala", "tanom", "woven fan", "buri palm", "bamboo", "fiber", "plant"], "fact": {"tl": "Ang hinabing pamaypay ay madalas gawa sa pinatuyong dahon ng buri o tinabas na kawayan, mga materyales na galing sa mga halaman.", "en": "A woven hand fan is often made from dried buri palm leaves or strips of bamboo, materials that come from plants.", "bis": "Ang hinablang pamaypay kasagaran hinimo gikan sa pinauga nga dahon sa buri o gitabas nga kawayan, mga materyales nga gikan sa mga tanom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pan-de-coco-bun-g5", "domain": "LIVING_THINGS", "topic": "coconut meat is the edible seed of the coconut palm", "grades": [4, 5, 6], "terms": ["pan de coco", "niyog", "tinapay", "buto", "halaman", "laman", "lubi", "liso", "tanom", "unod", "coconut", "bread", "seed", "coconut palm", "filling"], "fact": {"tl": "Ang pan de coco ay tinapay na may palaman na gadgad na niyog, at ang niyog ay galing sa malaking buto ng punong niyog na lumalaki sa init na klima ng Pilipinas.", "en": "Pan de coco is a bun filled with grated coconut, and coconut comes from the large seed of the coconut palm that grows well in the warm Philippine climate.", "bis": "Ang pan de coco usa ka pan nga gisudlan og kinudkod nga lubi, ug ang lubi gikan sa dako nga liso sa kahoy nga lubi nga maayong motubo sa init nga klima sa Pilipinas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "panagbenga-flower-float-g4", "domain": "LIVING_THINGS", "topic": "flowers are the reproductive part of plants", "grades": [3, 4, 5], "terms": ["panagbenga", "bulaklak", "Baguio", "lamig", "halaman", "buto", "bulak", "bugnaw", "tanom", "flower", "festival", "cool climate", "bloom"], "fact": {"tl": "Ang Panagbenga sa Baguio ay 'panahon ng pamumulaklak,' at ang mga bulaklak na nagpapakitang-gilas ay ang bahagi ng halaman na tumutulong sa pagbuo ng buto.", "en": "Panagbenga in Baguio means 'season of blooming,' and the flowers shown off in the festival are the part of a plant that helps make seeds.", "bis": "Ang Panagbenga sa Baguio nagpasabot og 'panahon sa pagbulak,' ug ang mga bulak nga gipasundayag mao ang bahin sa tanom nga motabang sa paghimo og liso."}, "source": "encyclopedia-stable consensus; AAAS 5C reproduction", "generator": "claude-workflow", "reviewed": false},
  {"id": "panagbenga-flower-cool-climate-g5", "domain": "EARTH_SPACE", "topic": "Baguio's high elevation makes a cool climate for flowers", "grades": [5, 6, 7], "terms": ["Baguio", "taas", "bundok", "lamig", "klima", "bulaklak", "panagbenga", "habog", "bukid", "bugnaw", "bulak", "elevation", "highland", "cool", "climate"], "fact": {"tl": "Maraming bulaklak ang umuunlad sa Panagbenga dahil ang Baguio ay nasa mataas na bahagi ng bundok kung saan mas malamig ang klima kaysa sa kapatagan.", "en": "Many flowers thrive at Panagbenga because Baguio sits high in the mountains where the climate is cooler than in the lowlands.", "bis": "Daghang bulak ang molambo sa Panagbenga tungod kay ang Baguio naa sa habog nga bahin sa bukid diin mas bugnaw ang klima kaysa sa kapatagan."}, "source": "encyclopedia-stable consensus; DepEd Earth science climate", "generator": "claude-workflow", "reviewed": false},
  {"id": "pancit-bihon-plate-g5", "domain": "MATTER", "topic": "bihon noodles are made from rice flour", "grades": [4, 5, 6], "terms": ["pancit", "bihon", "bigas", "harina", "pansit", "noodles", "bugas", "rice noodles", "rice flour"], "fact": {"tl": "Ang bihon sa pancit ay manipis na noodles na gawa sa harina ng bigas, na nagiging malambot kapag iniluto sa init na tubig o sabaw.", "en": "The bihon in pancit is a thin noodle made from rice flour, which becomes soft when cooked in hot water or broth.", "bis": "Ang bihon sa pancit usa ka nipis nga noodles nga hinimo gikan sa harina sa bugas, nga mahimong humok kon lutoon sa init nga tubig o sabaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pancit-canton-plate-g5", "domain": "MATTER", "topic": "canton noodles are made from wheat flour", "grades": [4, 5, 6], "terms": ["pancit canton", "trigo", "harina", "noodles", "pansit", "wheat", "flour", "egg noodles", "canton"], "fact": {"tl": "Ang pancit canton ay gawa sa noodles mula sa harina ng trigo, kaya iba ito sa bihon na gawa sa bigas.", "en": "Pancit canton is made from noodles of wheat flour, which makes it different from bihon that is made from rice.", "bis": "Ang pancit canton hinimo gikan sa noodles nga harina sa trigo, mao nga lahi kini sa bihon nga hinimo gikan sa bugas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "paper-boat-folded-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "objects float when they push aside enough water (buoyancy)", "grades": [4, 5, 6], "terms": ["barkong papel", "lutang", "tubig", "buoyancy", "tulak", "hugis", "barko nga papel", "lutaw", "duso", "hulma", "paper boat", "float", "water", "shape"], "fact": {"tl": "Lumulutang ang barkong papel dahil ang hugis nitong parang lalagyan ay nagtutulak ng sapat na tubig pababa kaya itinataas ito ng tubig.", "en": "A paper boat floats because its hollow shape pushes aside enough water, and the water pushes back up to hold it on the surface.", "bis": "Molutaw ang barko nga papel tungod kay ang iyang hawan nga hulma nagduso og igong tubig, ug ang tubig magduso pabalik pataas aron magpalutaw niini."}, "source": "encyclopedia-stable consensus; NRC PS2 forces, buoyancy", "generator": "claude-workflow", "reviewed": false},
  {"id": "parol-capiz-star-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "capiz shells are translucent and let light pass through", "grades": [4, 5, 6], "terms": ["parol", "kapis", "capiz", "ilaw", "liwanag", "nakikita", "kabibe", "suga", "kahayag", "kinhason", "capiz shell", "translucent", "light", "lantern"], "fact": {"tl": "Ang parol na kapis ay gawa sa manipis na kabibe ng kapis na bahagyang nagpapadaan ng liwanag, kaya kumikislap ito kapag may ilaw sa loob.", "en": "A capiz parol is made from thin capiz shells that are translucent and let some light pass through, so it glows when a light is placed inside.", "bis": "Ang parol nga kapis hinimo gikan sa nipis nga kabibe sa kapis nga makapaagi og gamay nga kahayag, mao nga mosidlak kini kon adunay suga sa sulod."}, "source": "encyclopedia-stable consensus; NRC PS4 light, transparency", "generator": "claude-workflow", "reviewed": false},
  {"id": "parol-five-point-star-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "lanterns glow because a light source inside emits light", "grades": [3, 4, 5], "terms": ["parol", "ilaw", "liwanag", "bituin", "ilaw-bombilya", "Pasko", "suga", "kahayag", "bitoon", "lantern", "light source", "star", "glow", "Christmas"], "fact": {"tl": "Ang parol na hugis-bituin ay nagliliwanag dahil may pinagmumulan ng ilaw sa loob nito, tulad ng kandila o bombilya, na nagpapalabas ng liwanag.", "en": "A star-shaped parol shines because there is a light source inside it, like a candle or bulb, that gives off light.", "bis": "Ang parol nga porma-bitoon mosanag tungod kay adunay tinubdan sa kahayag sa sulod niini, sama sa kandila o bombilya, nga mosanag og kahayag."}, "source": "encyclopedia-stable consensus; NRC PS4 light sources", "generator": "claude-workflow", "reviewed": false},
  {"id": "parol-frame-bamboo-skeleton-g4", "domain": "MATTER", "topic": "bamboo is a strong lightweight material for frames", "grades": [3, 4, 5], "terms": ["parol", "kawayan", "balangkas", "magaan", "matibay", "halaman", "kalansay", "gaan", "lig-on", "tanom", "bamboo", "frame", "lightweight", "strong"], "fact": {"tl": "Ang balangkas ng parol ay madalas gawa sa kawayan dahil ito ay magaan ngunit matibay, kaya kaya nitong hawakan ang hugis ng parol nang hindi mabigat.", "en": "The frame of a parol is often made of bamboo because it is lightweight yet strong, so it can hold the lantern's shape without being heavy.", "bis": "Ang balangkas sa parol kasagaran hinimo sa kawayan tungod kay gaan kini apan lig-on, mao nga makaya niini ang porma sa parol nga dili bug-at."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "paksiw-na-isda-g5", "domain": "MATTER", "topic": "vinegar acid helps preserve and cook fish", "grades": [5, 6, 7], "terms": ["paksiw", "isda", "suka", "asido", "luto", "pagkasira", "preserba", "paksiw na isda", "fish", "vinegar", "acid", "preserve", "sour"], "fact": {"tl": "Sa paksiw na isda, ginagamit ang suka na isang asido na tumutulong magluto at magpatagal sa isda dahil pinapabagal nito ang paglaki ng mga mikrobyong nagpapasira.", "en": "In paksiw na isda, vinegar—an acid—helps cook and preserve the fish because it slows the growth of the microbes that cause spoiling.", "bis": "Sa paksiw nga isda, gigamit ang suka nga usa ka asido nga motabang sa pagluto ug pagpadugay sa isda kay gipahinay niini ang pagdaghan sa mga mikrobyo nga makapadunot."}, "source": "encyclopedia-stable consensus; DepEd G6 mixtures, food preservation", "generator": "claude-workflow", "reviewed": false},
  {"id": "pandanggo-sa-ilaw-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "balancing requires keeping the center of gravity steady", "grades": [4, 5, 6], "terms": ["pandanggo sa ilaw", "balanse", "ilaw", "tinghoy", "sayaw", "timbang", "suga", "center of gravity", "balance", "light", "dance", "lamp"], "fact": {"tl": "Sa Pandanggo sa Ilaw, kailangang panatilihing matatag ng mananayaw ang timbang ng mga ilaw sa kanyang kamay at ulo para hindi matumba o mahulog ang mga ito.", "en": "In the Pandanggo sa Ilaw, the dancer must keep the oil lamps balanced steadily on the hands and head so they do not tip over or fall.", "bis": "Sa Pandanggo sa Ilaw, kinahanglan magpabilin nga lig-on ang magsasayaw sa timbang sa mga suga sa iyang kamot ug ulo aron dili kini matumba o mahulog."}, "source": "encyclopedia-stable consensus; NRC PS2 stability, balance", "generator": "claude-workflow", "reviewed": false},
  {"id": "pandesal-bread-rolls-g5", "domain": "MATTER", "topic": "yeast makes bread rise by producing gas bubbles", "grades": [5, 6, 7], "terms": ["pandesal", "tinapay", "lebadura", "yeast", "gas", "bula", "umaalsa", "mosaka", "bread", "rise", "gas bubbles"], "fact": {"tl": "Umaalsa ang masa ng pandesal dahil ang lebadura ay naglalabas ng gas na bumubuo ng maliliit na bula na nagpapalaki at nagpapalambot sa tinapay.", "en": "Pandesal dough rises because yeast releases gas that forms tiny bubbles, making the bread bigger and softer.", "bis": "Mosaka ang masa sa pandesal tungod kay ang lebadura nagpagawas og gas nga naghimo og gagmay nga bula nga nagpadako ug nagpahumok sa tinapay."}, "source": "encyclopedia-stable consensus; DepEd G6 chemical change", "generator": "claude-workflow", "reviewed": false},
  {"id": "pandesal-basket-g4", "domain": "LIVING_THINGS", "topic": "bread is made from wheat flour, a plant grain", "grades": [3, 4, 5], "terms": ["pandesal", "tinapay", "trigo", "harina", "butil", "halaman", "lugas", "tanom", "bread", "wheat", "flour", "grain", "plant"], "fact": {"tl": "Ang pandesal sa basket ay gawa sa harina ng trigo, isang butil ng halaman na giniling para maging harina bago masahin at lutuin sa hurno.", "en": "The pandesal in a basket is made from wheat flour, a plant grain ground into flour before it is kneaded and baked in an oven.", "bis": "Ang pandesal sa basket hinimo gikan sa harina sa trigo, usa ka lugas sa tanom nga giniling aron mahimong harina sa dili pa masahon ug lutoon sa hudno."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "parol-light-lantern-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "parol Christmas lantern light", "grades": [4, 5, 6], "terms": ["parol", "parul", "ilaw", "suga", "lantern", "Christmas lantern", "kandila", "kandela", "bombilya", "light", "energy", "kuryente"], "fact": {"tl": "Ang parol ay isang Pilipinong parol na may hugis-bituin na nagbibigay-liwanag mula sa kandila o ilaw-de-kuryente sa loob nito.", "en": "A parol is a Filipino star-shaped lantern that gives off light from a candle or an electric bulb glowing inside it.", "bis": "Ang parol usa ka Pilipinhong parol nga porma-bituon nga naghatag kahayag gikan sa kandila o suga nga kuryente sa sulod niini."}, "source": "encyclopedia-stable consensus; NRC PS3.A energy", "generator": "claude-workflow", "reviewed": false},
  {"id": "pastillas-milk-candy-g5", "domain": "MATTER", "topic": "pastillas carabao milk candy", "grades": [4, 5, 6], "terms": ["pastillas", "gatas ng kalabaw", "carabao milk", "gatas sa kabaw", "kendi", "kendi sa gatas", "asukal", "candy", "milk", "sugar", "matunaw", "natunaw", "nagmix"], "fact": {"tl": "Ang pastillas ay matamis na kendi na gawa sa gatas ng kalabaw na hinaluan ng asukal at pinakukuluan hanggang lumapot.", "en": "Pastillas is a sweet candy made from carabao's milk mixed with sugar and cooked until it thickens.", "bis": "Ang pastillas usa ka tam-is nga kendi nga hinimo gikan sa gatas sa kabaw nga gisagol ug asukal ug giluto hangtod molapot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "patintero-game-motion-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "patintero running game motion", "grades": [3, 4, 5], "terms": ["patintero", "laro", "dula", "takbo", "tumakbo", "dagan", "midagan", "iwas", "lihay", "bilis", "speed", "run", "dodge", "motion", "galaw", "lihok"], "fact": {"tl": "Sa larong patintero, mabilis na tumatakbo at lumilihis ang mga bata, gumagamit ng bilis at pabago-bagong direksyon para maiwasang mahuli.", "en": "In the game patintero, children run fast and dodge, using speed and sudden changes of direction to avoid being tagged.", "bis": "Sa dula nga patintero, kusog nga magdagan ug molihay ang mga bata, gamit ang katulin ug kalit nga pagbag-o sa direksyon aron dili madakpan."}, "source": "encyclopedia-stable consensus; NRC PS2.A motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "patteng-bamboo-zither-sound-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "patteng bamboo zither sound vibration", "grades": [4, 5, 6], "terms": ["patteng", "patting", "kawayan", "bamboo", "kawayanong instrumento", "zither", "tugtog", "tunog", "tingog", "vibration", "panginig", "sound", "himay", "kalantog"], "fact": {"tl": "Ang patteng ay isang instrumentong kawayan na umaawit kapag pinipitik ang mga himay nitong nanginginig at gumagawa ng tunog.", "en": "The patteng is a bamboo zither that makes music when its strips are plucked, vibrating to produce sound.", "bis": "Ang patteng usa ka instrumentong kawayan nga motingog kon kutingon ang mga himay niini nga mokurog ug mohimog tunog."}, "source": "encyclopedia-stable consensus; NRC PS4.A waves and sound", "generator": "claude-workflow", "reviewed": false},
  {"id": "boat-float-fluvial-procession-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "boats float on river buoyancy", "grades": [4, 5, 6], "terms": ["bangka", "sakayan", "fluvial", "prusisyon sa ilog", "river procession", "lutang", "lumulutang", "naglutaw", "buoyancy", "tubig", "ilog", "float", "boat", "suba"], "fact": {"tl": "Sa prusisyong panlawa, lumulutang ang mga bangkang may pasahero dahil itinutulak sila pataas ng tubig nang mas malakas kaysa bigat nila.", "en": "In a river procession, the passenger boats stay afloat because the water pushes up on them more strongly than their weight pulls down.", "bis": "Sa prusisyon sa subâ, naglutaw ang mga sakayan nga may pasahero kay gituklod sila pataas sa tubig nga mas kusog kay sa ilang gibug-aton."}, "source": "encyclopedia-stable consensus; NRC PS2.A forces", "generator": "claude-workflow", "reviewed": false},
  {"id": "boiled-egg-heat-cooking-g5", "domain": "MATTER", "topic": "boiled egg heat changes protein", "grades": [4, 5, 6], "terms": ["penoy", "itlog", "itlog na pinakuluan", "boiled egg", "nilaga", "nilagang itlog", "init", "kainit", "luto", "naluto", "tumigas", "gahi", "heat", "egg", "lutô"], "fact": {"tl": "Kapag pinakukuluan ang itlog tulad ng penoy, tumitigas ang dating malabnaw na puti at pula dahil binabago sila ng init.", "en": "When an egg like penoy is boiled, the once-runny white and yolk turn solid because the heat changes them.", "bis": "Kon lat-an ang itlog sama sa penoy, mogahi ang kaniadto naghuyang nga puti ug pula tungod kay giusab sila sa kainit."}, "source": "encyclopedia-stable consensus; NRC PS1.B chemical/physical change", "generator": "claude-workflow", "reviewed": false},
  {"id": "ferris-wheel-circular-motion-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "ferris wheel circular motion", "grades": [5, 6, 7], "terms": ["ferris wheel", "perya", "tsubibo", "gulong", "umiikot", "iniikot", "nagtuyok", "circular motion", "paikot", "round", "ride", "lingin", "rotation"], "fact": {"tl": "Ang ferris wheel sa perya ay isang malaking gulong na umiikot, kaya ang mga sakay ay umaakyat at bumababa habang dumadaan sila sa palibot.", "en": "A ferris wheel at the fair is a large wheel that turns in a circle, so riders go up and down as they move around it.", "bis": "Ang ferris wheel sa perya usa ka dakong ligid nga nagtuyok, busa ang mga sakay mosaka ug monaog samtang molibot sila."}, "source": "encyclopedia-stable consensus; NRC PS2.A motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "fish-soup-pesa-nutrition-g4", "domain": "LIVING_THINGS", "topic": "fish soup pesa protein nutrition", "grades": [3, 4, 5], "terms": ["pesa", "isda", "sabaw ng isda", "fish soup", "sabaw sa isda", "protina", "protein", "sustansiya", "nutrisyon", "lusog", "healthy", "lawas", "lamang-dagat"], "fact": {"tl": "Ang pesa ay sopas ng isda na nagbibigay ng protina na tumutulong palakihin at ayusin ang ating katawan.", "en": "Pesa is a fish soup that provides protein, which helps our bodies grow and repair themselves.", "bis": "Ang pesa usa ka sabaw sa isda nga naghatag ug protina nga makatabang motubo ug moayo sa atong lawas."}, "source": "encyclopedia-stable consensus; DepEd Health/Science nutrition", "generator": "claude-workflow", "reviewed": false},
  {"id": "petri-dish-microbes-g6", "domain": "LIVING_THINGS", "topic": "petri dish growing microbes", "grades": [5, 6, 7, 8], "terms": ["petri dish", "plato ng siyensiya", "platito", "bakterya", "bacteria", "mikrobyo", "kagaw", "germ", "tumubo", "nagtubo", "mitubo", "lab", "laboratoryo", "fungi"], "fact": {"tl": "Ang petri dish ay isang mababaw na lalagyang gawa sa salamin o plastik na ginagamit ng mga siyentipiko para magpatubo ng bakterya at mikrobyo na maaaring pag-aralan.", "en": "A petri dish is a shallow glass or plastic container scientists use to grow bacteria and microbes so they can be studied.", "bis": "Ang petri dish usa ka mabaw nga sudlanan nga salamin o plastik nga gamiton sa mga siyentista aron patubuon ang bakterya ug mikrobyo nga matun-an."}, "source": "encyclopedia-stable consensus; NRC LS1 microbiology", "generator": "claude-workflow", "reviewed": false},
  {"id": "pichi-pichi-cassava-g5", "domain": "LIVING_THINGS", "topic": "pichi-pichi cassava root kakanin", "grades": [4, 5, 6], "terms": ["pichi-pichi", "kamoteng kahoy", "cassava", "balanghoy", "kamoteng-kahoy", "ugat", "root", "gulaman", "kakanin", "almirol", "starch", "halaman", "tanom", "tuber"], "fact": {"tl": "Ang pichi-pichi ay isang matamis na kakanin na gawa sa giniling na kamoteng-kahoy, isang ugat na puno ng almirol na nagbibigay ng lakas.", "en": "Pichi-pichi is a sweet rice-cake-like treat made from grated cassava, a starchy root that gives us energy.", "bis": "Ang pichi-pichi usa ka tam-is nga kakanin nga hinimo gikan sa gigaling nga balanghoy, usa ka gamot nga puno sa almidon nga naghatag kusog."}, "source": "encyclopedia-stable consensus; NRC LS1.C food/energy", "generator": "claude-workflow", "reviewed": false},
  {"id": "pina-cloth-pineapple-fiber-g5", "domain": "LIVING_THINGS", "topic": "pina cloth pineapple leaf fiber", "grades": [4, 5, 6], "terms": ["pina", "piña", "pinya", "dahon ng pinya", "pineapple", "tela", "panapton", "fiber", "himay", "hibla", "pisi", "habi", "cloth", "leaf", "dahon", "halaman", "Barong Tagalog"], "fact": {"tl": "Ang piña ay manipis na tela na hinabi mula sa mga himay na kinukuha sa dahon ng halamang pinya.", "en": "Piña is a fine cloth woven from fibers stripped out of the leaves of the pineapple plant.", "bis": "Ang piña usa ka nipis nga panapton nga gihabol gikan sa mga himay nga gikuha sa dahon sa tanom nga pinya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pinakbet-vegetables-g4", "domain": "LIVING_THINGS", "topic": "pinakbet mixed vegetables vitamins", "grades": [3, 4, 5], "terms": ["pinakbet", "gulay", "utan", "ampalaya", "talong", "okra", "kalabasa", "sitaw", "vegetables", "bitamina", "vitamin", "sustansiya", "halaman", "healthy", "dish"], "fact": {"tl": "Ang pinakbet ay putaheng Pilipino na pinaghalong gulay tulad ng ampalaya, talong, at kalabasa na mayaman sa bitamina.", "en": "Pinakbet is a Filipino dish of mixed vegetables like bitter gourd, eggplant, and squash that are rich in vitamins.", "bis": "Ang pinakbet usa ka Pilipinhong sud-an nga sinagol nga utanon sama sa paliya, talong, ug kalabasa nga dato sa bitamina."}, "source": "encyclopedia-stable consensus; DepEd Science/Health nutrition", "generator": "claude-workflow", "reviewed": false},
  {"id": "pinipig-rice-flakes-g5", "domain": "LIVING_THINGS", "topic": "pinipig pounded young rice flakes", "grades": [4, 5, 6], "terms": ["pinipig", "bigas", "palay", "malagkit", "rice", "humay", "rice flakes", "binayo", "pinipi", "butil", "grain", "kakanin", "young rice", "halaman", "tanom"], "fact": {"tl": "Ang pinipig ay gawa sa murang butil ng malagkit na palay na inihahaw at binabayo hanggang maging manipis at malutong na pira-piraso.", "en": "Pinipig is made from young grains of sticky rice that are toasted and pounded flat into thin, crunchy flakes.", "bis": "Ang pinipig hinimo gikan sa batan-on nga lugas sa pilit nga humay nga gibusa ug gibayo hangtod nipis ug magkagiok nga mga piraso."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pinasugbo-banana-g4", "domain": "MATTER", "topic": "pinasugbo caramelized banana sugar", "grades": [4, 5, 6], "terms": ["pinasugbo", "consilva", "saging", "banana", "saba", "caramel", "asukal", "sugar", "pinrito", "giprito", "matamis", "natunaw na asukal", "fried banana", "kakanin", "init"], "fact": {"tl": "Ang pinasugbo ay piniritong saging na binalot sa asukal na tinunaw sa init hanggang maging malagkit at kayumangging caramel.", "en": "Pinasugbo is fried banana coated in sugar that is melted by heat until it turns into sticky, brown caramel.", "bis": "Ang pinasugbo usa ka giprito nga saging nga giputos sa asukal nga gitunaw sa kainit hangtod mahimong pilit ug kape-on nga caramel."}, "source": "encyclopedia-stable consensus; NRC PS1.B change of state", "generator": "claude-workflow", "reviewed": false},
  {"id": "pichi-coconut-jam-g5", "domain": "LIVING_THINGS", "topic": "coconut jam from coconut milk", "grades": [4, 5, 6], "terms": ["coconut jam", "minatamis na bao", "matamis na bao", "niyog", "lubi", "coconut", "gata", "coconut milk", "jam", "matamis", "buko", "halaman", "punong-niyog", "asukal"], "fact": {"tl": "Ang coconut jam ay matamis na pampahid na gawa sa gata ng niyog na hinaluan ng asukal at niluluto hanggang lumapot.", "en": "Coconut jam is a sweet spread made from coconut milk mixed with sugar and cooked until it thickens.", "bis": "Ang coconut jam usa ka tam-is nga ipahid nga hinimo gikan sa gata sa lubi nga gisagol ug asukal ug giluto hangtod molapot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pencil-graphite-g4", "domain": "MATTER", "topic": "pencil graphite writing material", "grades": [3, 4, 5], "terms": ["lapis", "pencil", "tinasa", "tinas-an", "graphite", "grapayt", "uling", "kahoy", "wood", "sulat", "sumulat", "nagsulat", "punto", "writing", "mineral"], "fact": {"tl": "Ang gitna ng lapis ay gawa sa graphite, isang malambot at maitim na mineral na nag-iiwan ng marka kapag idinidiin sa papel.", "en": "The center of a pencil is made of graphite, a soft, dark mineral that leaves a mark when pressed onto paper.", "bis": "Ang tunga sa lapis hinimo sa graphite, usa ka humok ug itom nga mineral nga magbilin ug marka kon idat-ol sa papel."}, "source": "encyclopedia-stable consensus; NRC PS1.A materials", "generator": "claude-workflow", "reviewed": false},
  {"id": "pinukpok-pineapple-fiber-loom-g6", "domain": "LIVING_THINGS", "topic": "pinukpok beaten plant fiber weaving", "grades": [5, 6, 7], "terms": ["pinukpok", "habihan", "habolan", "loom", "himay", "fiber", "hibla", "pinya", "abaka", "abaca", "binayo", "habi", "weaving", "tela", "dahon"], "fact": {"tl": "Ang pinukpok ay tela na hinabi sa habihan mula sa mga hibla ng halaman na binayo o pinitpit muna upang lumambot bago habiin.", "en": "Pinukpok is cloth woven on a loom from plant fibers that are first beaten soft before weaving.", "bis": "Ang pinukpok usa ka panapton nga gihabol sa habolan gikan sa mga himay sa tanom nga gibunalan una aron mohumok sa dili pa habolon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "piyaya-flatbread-g5", "domain": "MATTER", "topic": "piyaya muscovado flatbread baking", "grades": [4, 5, 6], "terms": ["piyaya", "piaya", "tinapay", "manipis", "muscovado", "asukal", "linuto", "hinurno", "init", "flatbread", "muscovado sugar", "baking", "Negros", "pagpana", "tinapay nga manipis"], "fact": {"tl": "Ang piyaya ay manipis na tinapay mula sa Negros na pinupuno ng muscovado at iniihaw, kung saan tinutunaw ng init ang asukal sa loob para maging malagkit.", "en": "Piyaya is a thin flatbread from Negros filled with muscovado sugar and toasted, where the heat melts the sugar inside into a sticky filling.", "bis": "Ang piyaya usa ka nipis nga tinapay gikan sa Negros nga pun-an ug muscovado ug sugbahon, diin ang kainit motunaw sa asukal sa sulod aron mahimong pilit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "polvoron-powder-candy-g4", "domain": "MATTER", "topic": "polvoron pressed powder candy", "grades": [3, 4, 5], "terms": ["polvoron", "polboron", "pulbos", "harina", "ginisang harina", "gatas", "mantikilya", "asukal", "pinindot", "hinubog", "powder candy", "toasted flour", "powdered milk", "pressed mold", "pulbo", "gipindot"], "fact": {"tl": "Ang polvoron ay matamis na pulbos na gawa sa inihaw na harina, gatas na pulbo, asukal, at mantikilya na pinipindot sa hulmahan para magkaroon ng hugis.", "en": "Polvoron is a sweet, crumbly powder candy made from toasted flour, powdered milk, sugar, and butter pressed in a mold to hold its shape.", "bis": "Ang polvoron usa ka tam-is nga pulbos nga kalan-on gama sa gisangag nga harina, gatas nga pulbo, asukal, ug mantikilya nga gipindot sa hulmahan aron magporma."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pork-barbecue-stick-g5", "domain": "MATTER", "topic": "grilling pork barbecue cooking change", "grades": [4, 5, 6], "terms": ["barbecue", "barbeque", "ihaw", "inihaw", "baboy", "karne", "tusok", "uling", "apoy", "init", "luto", "pork", "grill", "skewer", "charcoal", "cooking", "sugnod", "gisugba", "baboy nga karne"], "fact": {"tl": "Kapag iniihaw ang pork barbecue sa baga ng uling, ginagawa ng init na ligtas kainin ang hilaw na karne at nagbibigay ng kayumangging kulay at amoy mula sa nagbabagong sangkap nito.", "en": "When pork barbecue is grilled over charcoal, the heat cooks the raw meat to make it safe to eat and gives it a browned color and aroma from its changing ingredients.", "bis": "Kon sugbahon ang pork barbecue sa baga sa uling, ang kainit moluto sa hilaw nga karne aron luwas kan-on ug mohatag ug kape nga kolor ug humot gikan sa nagbag-o nga sulod niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pottery-firing-open-kiln-g6", "domain": "MATTER", "topic": "firing clay pottery hardening with heat", "grades": [5, 6, 7], "terms": ["palayok", "putik", "luwad", "kalan", "hurno", "apoy", "init", "tumigas", "matigas", "pagluto ng putik", "pottery", "clay", "firing", "kiln", "harden", "fire", "gipagahi", "luad", "gisunog", "lutay"], "fact": {"tl": "Kapag iniihaw ang hinubog na putik sa napakainit na apoy, permanenteng tumitigas ito at hindi na muling lumalambot sa tubig, kaya nagiging matibay na palayok.", "en": "When shaped clay is fired in very hot flames, it hardens permanently and no longer softens in water, becoming a sturdy clay pot.", "bis": "Kon sugbahon ang hinulmang luad sa hilabihan kainit nga kalayo, kini mogahi nga permanente ug dili na molumo sa tubig, busa mahimong lig-on nga kolon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pressed-leaf-specimen-g5", "domain": "LIVING_THINGS", "topic": "pressing and drying leaf specimens", "grades": [4, 5, 6], "terms": ["dahon", "pinindot na dahon", "tuyong dahon", "halaman", "herbarium", "ipit", "natuyo", "tubig", "preserba", "pressed leaf", "specimen", "dried", "plant", "moisture", "dahon nga gipindot", "uga nga dahon", "gipug-an"], "fact": {"tl": "Kapag inilalagay ang dahon sa pagitan ng mga papel at idiniidiin, natutuyo ito habang nawawala ang tubig sa loob, kaya napepreserba nang matagal para pag-aralan.", "en": "When a leaf is placed between papers and pressed flat, it dries out as the water inside escapes, preserving it for a long time to study.", "bis": "Kon ibutang ang dahon sa taliwala sa mga papel ug pug-an, kini momala samtang mogawas ang tubig sa sulod, busa mapreserbar kini sa dugay nga panahon aron tun-an."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "proper-waste-disposal-health-g4", "domain": "LIVING_THINGS", "topic": "proper waste disposal and health", "grades": [3, 4, 5, 6], "terms": ["basura", "tamang pagtatapon", "tapon", "basurahan", "mikrobyo", "sakit", "kalusugan", "kalinisan", "langaw", "waste disposal", "garbage", "germs", "disease", "health", "sanitation", "basura nga itambog", "kahimsog", "kalimpyo"], "fact": {"tl": "Ang tamang pagtatapon ng basura sa tamang lalagyan ay nakakapigil sa pagdami ng mikrobyo at langaw na nagdadala ng sakit, kaya nananatiling malusog ang komunidad.", "en": "Proper disposal of garbage in the right containers prevents the spread of germs and flies that carry disease, keeping the community healthy.", "bis": "Ang husto nga pagtambog sa basura sa saktong sudlanan makapugong sa pagsaka sa mga germ ug langaw nga magdala ug sakit, busa magpabiling himsog ang komunidad."}, "source": "DepEd MATATAG Science CG; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "protractor-half-circle-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "protractor measuring angles in degrees", "grades": [5, 6, 7], "terms": ["protractor", "panukat ng anggulo", "anggulo", "grado", "degree", "kalahating bilog", "sukat", "180", "guhit", "angle", "measure", "half circle", "degrees", "anggulo nga sukdon", "tunga sa lingin", "sukod"], "fact": {"tl": "Ang protractor ay kalahating-bilog na kagamitan na hinati sa 180 na grado, na ginagamit upang sukatin kung gaano kalaki ang anggulo sa pagitan ng dalawang guhit.", "en": "A protractor is a half-circle tool divided into 180 degrees, used to measure how wide the angle is between two lines.", "bis": "Ang protractor usa ka tunga-sa-lingin nga gamit nga gibahin sa 180 ka grado, gamiton aron sukdon kon unsa kalapad ang anggulo tali sa duha ka linya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "puso-hanging-rice-g5", "domain": "MATTER", "topic": "puso hanging rice woven leaf pouch", "grades": [4, 5, 6], "terms": ["puso", "hanging rice", "kanin", "bigas", "dahon ng niyog", "lukay", "hinabi", "niluto", "tubig", "init", "rice", "coconut leaf", "woven", "boiled", "Cebu", "puso nga kanin", "linukot nga dahon", "gilung-ag"], "fact": {"tl": "Ang puso ay kanin na niluluto sa loob ng hinabing dahon ng niyog, kung saan lumalaki ang mga butil ng bigas habang sumisipsip ito ng tubig at init sa kumukulong palayok.", "en": "Puso is rice cooked inside a woven coconut-leaf pouch, where the grains swell as they soak up water and heat in the boiling pot.", "bis": "Ang puso usa ka kan-on nga gilung-ag sulod sa linukot nga dahon sa lubi, diin mohabok ang bugas samtang mosuyop kini ug tubig ug kainit sa nagbukal nga kolon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "puto-bumbong-bamboo-steamer-g5", "domain": "MATTER", "topic": "puto bumbong steaming in bamboo tubes", "grades": [4, 5, 6], "terms": ["puto bumbong", "kawayan", "bumbong", "singaw", "sinaing", "pirurutong", "bigas", "lila", "biko", "Pasko", "steam", "bamboo tube", "purple rice", "Christmas", "kawayan nga tubo", "alisngaw", "gipasingawan"], "fact": {"tl": "Ang puto bumbong ay ginagawa sa pamamagitan ng pagsasalin ng galapong sa loob ng mga tubong kawayan at pinasisingawan, kaya naluluto ang kakanin gamit ang mainit na singaw.", "en": "Puto bumbong is made by filling bamboo tubes with rice dough and steaming them, so the rice cake cooks from the hot steam rising through the tube.", "bis": "Ang puto bumbong gibuhat pinaagi sa pagsulod sa galapong sa mga tubo nga kawayan ug gipasingawan, busa maluto ang kakanon gamit ang init nga alisngaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "puto-bumbong-purple-g5", "domain": "LIVING_THINGS", "topic": "pirurutong purple heirloom rice color", "grades": [4, 5, 6], "terms": ["puto bumbong", "lila", "kulay-ube", "pirurutong", "bigas", "palay", "pigment", "antosyanin", "purple rice", "violet", "heirloom rice", "grain", "lila nga bugas", "pulang bugas", "kolor"], "fact": {"tl": "Ang kulay-lila ng puto bumbong ay nanggagaling sa pirurutong, isang likas na maitim-na-lilang uri ng palay na taglay ang natural na kulay sa balat ng butil nito.", "en": "The purple color of puto bumbong comes from pirurutong, a naturally dark-violet variety of rice whose grain skin carries the color on its own.", "bis": "Ang lila nga kolor sa puto bumbong gikan sa pirurutong, usa ka kinaiyanhong itom-lila nga klase sa humay nga ang panit sa lugas naay kaugalingong kolor."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "puto-rice-cake-g4", "domain": "MATTER", "topic": "puto steamed rice cake rising", "grades": [3, 4, 5], "terms": ["puto", "kakanin", "galapong", "bigas", "singaw", "sinaing", "umalsa", "buko", "rice cake", "steamed", "rice batter", "rise", "fluffy", "puto nga kakanon", "alisngaw", "gipasingawan"], "fact": {"tl": "Ang puto ay kakaning gawa sa galapong ng bigas na pinasisingawan hanggang umalsa at lumambot, kaya nagiging malambot at maputi ang loob nito.", "en": "Puto is a rice cake made from rice batter that is steamed until it rises and softens, making the inside light and fluffy.", "bis": "Ang puto usa ka kakanon gama sa galapong sa bugas nga gipasingawan hangtod motubo ug molumo, busa mahimong humok ug puti ang sulod niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "queso-ice-cream-scoop-g5", "domain": "MATTER", "topic": "ice cream freezing and melting", "grades": [4, 5, 6], "terms": ["sorbetes", "ice cream", "keso", "queso", "gatas", "yelo", "nagyeyelo", "natutunaw", "lamig", "init", "frozen", "milk", "cheese", "melt", "freeze", "cold", "sorbetes nga keso", "natunaw", "gipayelo"], "fact": {"tl": "Ang sorbetes na queso ay gawa sa gatas na pinalalamig hanggang magyelo, ngunit natutunaw itong likido muli kapag umiinit dahil nilalampasan nito ang puntong nagyeyelo.", "en": "Queso ice cream is made from milk frozen until solid, but it melts back into liquid when it warms past its freezing point.", "bis": "Ang queso ice cream gama sa gatas nga gipabugnaw hangtod mogahi, apan kini matunaw balik ngadto sa likido kon moinit lapas sa puntos diin kini mogahi."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "recycling-arrows-symbol-g4", "domain": "LIVING_THINGS", "topic": "recycling symbol reusing materials", "grades": [3, 4, 5, 6], "terms": ["recycling", "muling paggamit", "reciklo", "palaso", "simbolo", "basura", "plastik", "papel", "kalikasan", "recycle", "arrows", "symbol", "reuse", "environment", "rebaybay", "muling gamiton", "simbolo sa pagrecycle", "pana"], "fact": {"tl": "Ang simbolo ng recycling na may tatlong sumusunod-sundang palaso ay nangangahulugang muling magagamit ang isang bagay, na nakakabawas sa basura at nakakatipid sa likas na yaman.", "en": "The recycling symbol of three chasing arrows means an item can be reused again, which cuts down waste and saves natural resources.", "bis": "Ang simbolo sa pagrecycle nga adunay tulo ka nagsunod nga pana nagpasabot nga ang usa ka butang magamit pag-usab, nga makamenos sa basura ug makatipig sa kinaiyanhong bahandi."}, "source": "DepEd MATATAG Science CG; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "referee-whistle-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "whistle making sound from vibrating air", "grades": [3, 4, 5], "terms": ["pito", "silbato", "hihip", "tunog", "hangin", "vibrate", "nayayanig", "referee", "whistle", "sound", "air", "blow", "vibration", "pagatunog", "pito nga huyopon", "tingog", "huyop"], "fact": {"tl": "Kapag hinihipan ang pito, mabilis na umiikot at nayayanig ang hanging nasa loob nito, at ang pag-yanig na ito ang gumagawa ng matinis na tunog.", "en": "When you blow a whistle, the air inside swirls and vibrates very fast, and this vibration is what makes its sharp sound.", "bis": "Kon huypan ang pito, ang hangin sa sulod molibot ug mokurog ug paspas, ug kini nga pagkurog mao ang naghimo sa hait nga tingog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rellenong-bangus-g5", "domain": "LIVING_THINGS", "topic": "milkfish bangus national fish", "grades": [4, 5, 6], "terms": ["bangus", "rellenong bangus", "milkfish", "isda", "isda na bangus", "pangulong isda", "isdang bangus", "fish", "tinik", "buto sa isda", "bangos", "isda nga bangus", "pambansang isda"], "fact": {"tl": "Ang bangus na ginagawang rellenong bangus ay kilalang-kilala bilang pambansang isda ng Pilipinas, inaalagaan sa mga palaisdaan at may maraming maliliit na tinik.", "en": "The milkfish used in rellenong bangus is popularly known as the national fish of the Philippines, raised in fishponds and known for its many tiny bones.", "bis": "Ang bangus nga ginahimo nga rellenong bangus ilado kaayo isip pambansang isda sa Pilipinas, gibuhi sa mga pondahan ug daghan og gagmay nga tinik."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rice-farmer-planting-g4", "domain": "LIVING_THINGS", "topic": "rice plant growth palay", "grades": [3, 4, 5], "terms": ["palay", "bigas", "kanin", "magsasaka", "pagtatanim ng palay", "rice", "rice plant", "halamang palay", "humay", "mag-uuma", "pagtanom og humay", "bugas", "kan-on", "tubig sa palayan"], "fact": {"tl": "Ang palay ay isang halamang damo na tinatanim ng magsasaka sa basang lupa, at ang butil nito ay nagiging bigas at kanin na ating kinakain.", "en": "Rice is a grass plant that farmers grow in flooded, wet soil, and its grain becomes the rice we eat.", "bis": "Ang humay usa ka tanom nga sagbot nga gitanom sa mag-uuma sa basa nga yuta, ug ang lugas niini mahimong bugas ug kan-on nga atong gikaon."}, "source": "encyclopedia-stable consensus; DepEd G3 Q3 plants", "generator": "claude-workflow", "reviewed": false},
  {"id": "roasted-peanuts-mani-g5", "domain": "MATTER", "topic": "peanut legume roasting heat change", "grades": [4, 5, 6], "terms": ["mani", "nilagang mani", "sinangag na mani", "peanut", "roasted peanuts", "binhi", "buto", "gisanlag nga mani", "mani nga sinanlag", "init", "pagprito", "legume", "munggo-pamilya"], "fact": {"tl": "Ang mani ay buto ng halamang legumbre na nag-iimbak ng langis at protina, at ang pag-iihaw nito ay gumagamit ng init para gawing malutong at mabango.", "en": "The peanut is a seed of a legume plant that stores oil and protein, and roasting it uses heat to make it crunchy and fragrant.", "bis": "Ang mani usa ka liso sa tanom nga legumbre nga nagtipig og lana ug protina, ug ang pagsanlag niini naggamit og init aron mahimo kining tagiktik ug humot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rondalla-band-ensemble-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "sound string vibration musical instruments", "grades": [4, 5, 6], "terms": ["rondalla", "bandurya", "oktabina", "kwerdas", "tunog", "vibration", "pag-vibrate", "sound", "string instruments", "tugtog", "gitara", "tingog", "pagkurog sa kwerdas", "musika"], "fact": {"tl": "Ang rondalla ay grupo ng mga instrumentong may kwerdas tulad ng bandurya, at ang tunog ay nabubuo kapag nanginginig ang mga kwerdas nito.", "en": "A rondalla is a group of string instruments like the bandurya, and sound is made when their strings vibrate.", "bis": "Ang rondalla usa ka grupo sa mga instrumento nga adunay kwerdas sama sa bandurya, ug ang tingog matawo kon mokurog ang mga kwerdas niini."}, "source": "encyclopedia-stable consensus; NRC PS4.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "ruler-measuring-tool-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "ruler length measurement", "grades": [3, 4, 5], "terms": ["ruler", "panukat", "sentimetro", "milimetro", "haba", "pagsukat", "sukatan", "centimeter", "length", "measure", "metric", "pagsukod", "gitas-on", "sentimetro ug milimetro"], "fact": {"tl": "Ang ruler ay kasangkapan sa pagsukat ng haba na may mga marka ng sentimetro at milimetro para malaman kung gaano kahaba ang isang bagay.", "en": "A ruler is a tool for measuring length with centimeter and millimeter marks to find out how long an object is.", "bis": "Ang ruler usa ka galamiton sa pagsukod sa gitas-on nga adunay marka sa sentimetro ug milimetro aron mahibal-an kon unsa ka taas ang usa ka butang."}, "source": "encyclopedia-stable consensus; DepEd measurement", "generator": "claude-workflow", "reviewed": false},
  {"id": "ruler-set-triangle-pair-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "set square triangle drawing tool angle", "grades": [5, 6, 7], "terms": ["set triangle", "triangular ruler", "panulat na tatsulok", "anggulo", "tuwid na linya", "set square", "angle", "right angle", "guhit", "tatsulok na panukat", "anggulo nga 90", "tul-id nga linya", "tatsulok"], "fact": {"tl": "Ang magkapares na tatsulok na ruler ay ginagamit sa pagguhit ng tuwid na linya at tumpak na anggulo tulad ng 90 digri.", "en": "A pair of set-square triangles is used to draw straight lines and exact angles like 90 degrees.", "bis": "Ang pares nga tatsulok nga ruler gigamit sa pagdrowing og tul-id nga linya ug tukma nga anggulo sama sa 90 ka degree."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sabong-arena-rooster-g4", "domain": "LIVING_THINGS", "topic": "rooster chicken male bird comb", "grades": [3, 4, 5], "terms": ["tandang", "manok", "rooster", "palaban na manok", "tuka", "palong", "balahibo", "tukâ", "sungayan ng manok", "sunoy", "manok nga laki", "tuktugaok", "comb", "chicken", "tilaok"], "fact": {"tl": "Ang tandang ay lalaking manok na may matingkad na pulang palong at sikat sa malakas nitong pagtilaok tuwing madaling-araw.", "en": "A rooster is a male chicken with a bright red comb, known for its loud crowing at dawn.", "bis": "Ang sunoy usa ka laki nga manok nga adunay mapula nga palong ug ilado sa kusog niini nga pagtuktugaok sa kaadlawon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "saggeypo-bamboo-pipes-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "sound air vibration bamboo pipe instrument", "grades": [4, 5, 6], "terms": ["saggeypo", "kawayan", "bamboo pipes", "tunog", "hangin", "vibration", "instrumento na kawayan", "hihip", "sound", "air column", "kahoy nga kawayan", "tingog gikan sa kawayan", "huyop", "pagkurog sa hangin"], "fact": {"tl": "Ang saggeypo ay instrumentong gawa sa mga tubong kawayan na tumutunog kapag inihihip mo ang hangin sa loob nito.", "en": "The saggeypo is an instrument made of bamboo pipes that makes sound when you blow air through them.", "bis": "Ang saggeypo usa ka instrumento nga hinimo sa mga tubo nga kawayan nga motingog kon huypan nimo og hangin ang sulod niini."}, "source": "encyclopedia-stable consensus; NRC PS4.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "sago-gulaman-g5", "domain": "MATTER", "topic": "gelatin agar seaweed gel solid liquid", "grades": [4, 5, 6], "terms": ["gulaman", "sago", "sagot gulaman", "agar", "halamang-dagat", "damong-dagat", "gel", "lutong gulaman", "tubig na nagiging gulaman", "seaweed", "gelatin", "lapok-lapok", "gulaman gikan sa lumot sa dagat", "namuo"], "fact": {"tl": "Ang gulaman ay gawa sa halamang-dagat na pinakuluan sa tubig, at pagkalamig ito ay namumuo mula likido tungo sa malambot na solido.", "en": "Gulaman is made from seaweed boiled in water, and as it cools it sets from a liquid into a soft solid gel.", "bis": "Ang gulaman hinimo gikan sa lumot sa dagat nga gibukalan sa tubig, ug kon mabugnaw kini mamuo gikan sa likido ngadto sa humok nga solido."}, "source": "encyclopedia-stable consensus; NRC PS1.A states of matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "salabat-ginger-tea-g4", "domain": "LIVING_THINGS", "topic": "ginger root rhizome plant", "grades": [3, 4, 5], "terms": ["luya", "salabat", "ginger", "ginger tea", "ugat ng luya", "halamang luya", "rhizome", "luy-a", "tsaa nga luya", "ugat", "gamot", "init nga ilimnon", "ginger root", "anghang"], "fact": {"tl": "Ang salabat ay mainit na inumin na gawa sa luya, isang halaman na ang naka-imbak na ugat nito sa ilalim ng lupa ang may anghang na lasa.", "en": "Salabat is a warm drink made from ginger, a plant whose underground storage root gives it its spicy taste.", "bis": "Ang salabat usa ka init nga ilimnon nga hinimo gikan sa luy-a, usa ka tanom nga ang gitipigan niini nga ugat ilalom sa yuta maoy naghatag sa anghang nga lami."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sampaloc-candy-tamarind-g5", "domain": "LIVING_THINGS", "topic": "tamarind tree sour fruit acid", "grades": [4, 5, 6], "terms": ["sampaloc", "sampalok", "tamarind", "maasim", "prutas", "asim", "punong sampaloc", "sambag", "aslom", "kahoy nga sambag", "bunga", "acid", "sour fruit", "vitamin C", "candy"], "fact": {"tl": "Ang sampaloc ay bunga ng matangkad na puno na maasim ang lasa dahil sa likas na asido nito, at ginagawang kendi o pampaasim sa ulam.", "en": "Tamarind is the fruit of a tall tree that tastes sour because of its natural acid, and it is made into candy or used to sour dishes.", "bis": "Ang sambag mao ang bunga sa taas nga kahoy nga aslom ang lami tungod sa kinaiyanhon niini nga asido, ug ginahimo nga kendi o pang-aslom sa sud-an."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "san-fernando-giant-parol-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "lantern electric light bulbs energy", "grades": [4, 5, 6], "terms": ["parol", "higanteng parol", "san fernando", "ilaw", "bombilya", "kuryente", "lantern", "light", "electricity", "Pasko", "suga", "kuryente nga nagdan-ag", "bombilya nga nagsiga", "lamparilya", "kidlat-kidlat na ilaw"], "fact": {"tl": "Ang higanteng parol ng San Fernando ay pinaiilaw ng libu-libong bombilya na gumagamit ng kuryente para magpakita ng sumasayaw na liwanag.", "en": "The giant lantern of San Fernando is lit by thousands of bulbs that use electricity to create dancing patterns of light.", "bis": "Ang higante nga parol sa San Fernando gidan-agan sa liboan ka bombilya nga naggamit og kuryente aron makahimo og nagsayaw nga kahayag."}, "source": "encyclopedia-stable consensus; NRC PS3.B energy", "generator": "claude-workflow", "reviewed": false},
  {"id": "rosquillos-ring-cookie-g6", "domain": "MATTER", "topic": "baking irreversible chemical change heat", "grades": [5, 6, 7], "terms": ["rosquillos", "biskwit", "cookie", "paghuhurno", "init", "pagbabago", "chemical change", "harina", "masa", "pag-init", "biskwit nga lingin", "pagluto sa pugon", "irreversible", "baking", "hudno"], "fact": {"tl": "Ang rosquillos ay hugis-singsing na biskwit na niluluto sa init ng hurno, kung saan ang masa ay nagbabago nang permanente at hindi na maibabalik sa dating anyo.", "en": "Rosquillos is a ring-shaped cookie baked by oven heat, where the dough changes permanently and cannot return to its raw form.", "bis": "Ang rosquillos usa ka biskwit nga porma og singsing nga giluto sa init sa hudno, diin ang masa mausab nga permanente ug dili na mabalik sa kanhi niini nga porma."}, "source": "encyclopedia-stable consensus; NRC PS1.B chemical change", "generator": "claude-workflow", "reviewed": false},
  {"id": "samalamig-cold-drink-g5", "domain": "MATTER", "topic": "dissolving mixture cold drink solution", "grades": [4, 5, 6], "terms": ["samalamig", "palamig", "halo-halong inumin", "natunaw", "asukal", "tubig", "yelo", "dissolve", "solution", "mixture", "natunaw nga asukal", "bugnaw nga ilimnon", "timpla", "cold drink", "sago't gulaman"], "fact": {"tl": "Ang samalamig ay malamig na inumin kung saan ang asukal ay natutunaw sa tubig para makabuo ng pinaghalong likido na pantapos sa uhaw.", "en": "Samalamig is a cold drink in which sugar dissolves in water to form a mixture that quenches thirst.", "bis": "Ang samalamig usa ka bugnaw nga ilimnon diin ang asukal matunaw sa tubig aron makabuo og sinagol nga likido nga makapahupay sa kauhaw."}, "source": "encyclopedia-stable consensus; NRC PS1.A mixtures", "generator": "claude-workflow", "reviewed": false},
  {"id": "sapin-sapin-layered-g5", "domain": "MATTER", "topic": "sapin-sapin layered rice dessert", "grades": [4, 5, 6], "terms": ["sapin-sapin", "kakanin", "patong-patong", "galapong", "malagkit", "gata", "naglalapat na sapaw", "kanin nga humok", "lutid nga may sapaw", "layered", "sticky rice", "coconut milk"], "fact": {"tl": "Ang sapin-sapin ay isang Pilipinong kakanin na gawa sa giling na malagkit na bigas at gata na niluluto ng paunti-unti upang ang bawat kulay ay magtumpok bilang magkakapatong na layer.", "en": "Sapin-sapin is a Filipino rice cake made from ground glutinous rice and coconut milk, cooked in stages so each colored batch sets into a separate stacked layer.", "bis": "Ang sapin-sapin usa ka Pilipinhong kakanin nga hinimo sa giniling nga pilit nga bugas ug gata, giluto sa hinay-hinay aron ang matag kolor mopatong isip nagkapatong nga sapaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sari-sari-store-tingi-g4", "domain": "MATTER", "topic": "selling in small measured units (tingi)", "grades": [3, 4, 5], "terms": ["sari-sari store", "tindahan", "tingi", "tinitingi", "pagtitingi", "panukat", "piraso", "gramo", "pag-sukod", "tinda", "tag-usa", "measuring", "small portions", "unit"], "fact": {"tl": "Sa sari-sari store, ang mga produkto ay madalas ibinebenta nang tingi o paisa-isa, kaya natututo ang mga bata na magsukat ng dami gamit ang piraso, gramo, o tasa.", "en": "At a sari-sari store, goods are often sold tingi (in small single portions), which lets people measure quantity using pieces, grams, or cups instead of whole packs.", "bis": "Sa sari-sari store, ang mga baligya kasagaran ibaligya og tingi o tinagsa, busa makakat-on ang mga bata sa pagsukod sa gidaghanon pinaagi sa piraso, gramo, o tasa."}, "source": "encyclopedia-stable consensus; DepEd measurement strand", "generator": "claude-workflow", "reviewed": false},
  {"id": "sawali-bamboo-wall-weave-g5", "domain": "LIVING_THINGS", "topic": "woven bamboo (sawali) building material", "grades": [4, 5, 6], "terms": ["sawali", "kawayan", "habi", "hinabing kawayan", "dingding", "magaan", "matibay", "kawayan nga hinabol", "bongbong", "gaan", "lig-on", "woven bamboo", "wall", "lightweight", "ventilation"], "fact": {"tl": "Ang sawali ay hinabing pinipi na pinilas na kawayan na ginagawang dingding dahil ito ay magaan, matibay, at may maliliit na butas na nagpapadaloy ng hangin sa loob ng bahay.", "en": "Sawali is a mat woven from flattened bamboo strips used as walls because it is lightweight, strong, and full of tiny gaps that let air flow through the house.", "bis": "Ang sawali usa ka hinabol nga gipi nga pinikas nga kawayan nga gigamit isip bongbong tungod kay gaan, lig-on, ug puno sa gagmay nga lungag nga makapaagi sa hangin sa balay."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sayaw-sa-bangko-bench-dance-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "balance and center of gravity in bench dance", "grades": [5, 6, 7], "terms": ["sayaw sa bangko", "balanse", "timbang", "pagtimbang", "sentro ng bigat", "gravity", "bangko", "pagbalanse sa bangko", "panimbang", "sentro sa kabug-aton", "balance", "center of gravity", "bench dance"], "fact": {"tl": "Sa Sayaw sa Bangko, ang mananayaw ay nananatiling nakatayo sa makitid na bangko sa pamamagitan ng pagpapanatili ng kanyang sentro ng bigat sa ibabaw ng bangko.", "en": "In Sayaw sa Bangko, the dancer stays on the narrow bench by keeping their center of gravity directly above the bench so they do not tip over.", "bis": "Sa Sayaw sa Bangko, ang mananayaw magpabilin sa pig-ot nga bangko pinaagi sa pagpadayon sa iyang sentro sa kabug-aton sa ibabaw sa bangko aron dili matumba."}, "source": "encyclopedia-stable consensus; NRC PS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "scissors-lever-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "scissors as a simple machine", "grades": [4, 5, 6], "terms": ["gunting", "simpleng makina", "lever", "pingga", "pivot", "puwersa", "pamutol", "simple nga makina", "tuwang", "pwersa", "scissors", "lever", "fulcrum", "cutting"], "fact": {"tl": "Ang gunting ay binubuo ng dalawang pingga na pinagdugtong sa isang pivot, kaya ang lakas ng kamay sa hawakan ay napapalakas upang madaling maputol ang papel o tela.", "en": "A pair of scissors is two levers joined at a pivot, so the force from your hand on the handles is concentrated at the blades to cut paper or cloth easily.", "bis": "Ang gunting hinimo sa duha ka tuwang nga gisumpay sa usa ka pivot, busa ang kusog sa imong kamot sa kuptanan motuon sa sulab aron sayon maputol ang papel o panapton."}, "source": "NRC PS2.A; AAAS simple machines", "generator": "claude-workflow", "reviewed": false},
  {"id": "scramble-iced-drink-g4", "domain": "MATTER", "topic": "melting and dissolving in an iced drink", "grades": [3, 4, 5], "terms": ["scramble", "yelo", "durog na yelo", "natutunaw", "malamig", "init", "halo", "natunaw nga yelo", "bugnaw", "matunaw", "ice", "melting", "dissolving", "cold drink"], "fact": {"tl": "Ang scramble ay gawa sa durog na yelo na nahahalo sa matamis na gatas; ang yelo ay natutunaw sa init at nagiging tubig, kaya unti-unting lumalabnaw ang inumin.", "en": "Scramble is made from crushed ice mixed with sweet milk; the ice melts in the warmth and turns to water, so the drink slowly gets thinner.", "bis": "Ang scramble hinimo sa dinugmok nga yelo nga gisagol sa tam-is nga gatas; ang yelo matunaw sa kainit ug mahimong tubig, busa hinay-hinay nga molabnaw ang ilimnon."}, "source": "encyclopedia-stable consensus; NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "seashell-spiral-g5", "domain": "LIVING_THINGS", "topic": "spiral seashells of sea snails", "grades": [4, 5, 6], "terms": ["kabibe", "shell", "kuhol sa dagat", "ispiral", "apog", "kaltsiyum", "kabibi", "kinhason", "liko-liko", "gahi nga panit", "spiral shell", "sea snail", "calcium carbonate", "protection"], "fact": {"tl": "Ang paikot na kabibe ay matigas na bahay ng kuhol sa dagat na gawa sa kaltsiyum karbonato, at lumalaki ito nang paikot habang lumalaki ang hayop sa loob.", "en": "A spiral seashell is the hard home of a sea snail, made of calcium carbonate, and it grows in a coil as the animal inside gets bigger.", "bis": "Ang liko-liko nga kinhason mao ang gahi nga balay sa kuhol sa dagat nga hinimo sa calcium carbonate, ug nagtubo kini nga nagliko samtang nagdako ang mananap sa sulod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "seatbelt-inertia-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "seatbelts and inertia", "grades": [5, 6, 7], "terms": ["seatbelt", "sinturon", "sinturon sa sasakyan", "inertia", "biglang preno", "ligtas", "puwersa", "sinturon sa awto", "kalit nga preno", "luwas", "pwersa", "sudden stop", "safety"], "fact": {"tl": "Kapag biglang huminto ang sasakyan, gusto ng katawan mo na magpatuloy sa pagusad dahil sa inertia, kaya hinahawakan ka ng seatbelt upang hindi ka bumangga sa harapan.", "en": "When a vehicle stops suddenly, your body wants to keep moving forward because of inertia, so the seatbelt holds you back to keep you from crashing into the front.", "bis": "Kon kalit mohunong ang sakyanan, gusto sa imong lawas nga magpadayon sa pagpaduol tungod sa inertia, busa ang seatbelt mokupot kanimo aron dili ka mabunggo sa atubangan."}, "source": "NRC PS2.A; Newton's first law", "generator": "claude-workflow", "reviewed": false},
  {"id": "seed-packet-germination-g4", "domain": "LIVING_THINGS", "topic": "seeds and germination", "grades": [3, 4, 5], "terms": ["binhi", "buto", "supot ng binhi", "germination", "nagsisibol", "tubig", "lupa", "itanim", "liso", "pugas", "pagturok sa liso", "tubo", "yuta", "seed", "sprout", "planting"], "fact": {"tl": "Ang supot ng binhi ay naglalaman ng tuyong mga buto na natutulog hanggang sa matanim sa lupa, kung saan ang tubig at init ay nagpapasibol sa kanila bilang bagong halaman.", "en": "A seed packet holds dry seeds that stay dormant until they are planted in soil, where water and warmth make them germinate into new plants.", "bis": "Ang supot sa binhi adunay mga uga nga liso nga natulog hangtod nga itanom sa yuta, diin ang tubig ug kainit maoy makapaturok kanila isip bag-ong tanom."}, "source": "NRC LS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sepak-takraw-projectile-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "kicking forces in sepak takraw", "grades": [5, 6, 7], "terms": ["sepak takraw", "bola", "rattan", "sipa", "puwersa", "arko", "gravity", "patid", "pwersa sa tiil", "arko sa lupad", "rattan ball", "kicking force", "trajectory"], "fact": {"tl": "Sa sepak takraw, sinisipa ng mga manlalaro ang magaan na bolang yari sa rattan, at ang lakas ng sipa ang nagtutulak dito sa hangin habang hinihila ito pababa ng gravity sa arko.", "en": "In sepak takraw, players kick a light rattan ball, and the force of the kick pushes it through the air while gravity pulls it down into a curved path.", "bis": "Sa sepak takraw, patiron sa mga magdudula ang gaan nga bola nga hinimo sa rattan, ug ang kusog sa patid maoy motukmod niini sa hangin samtang ang gravity mobira niini paubos sa liko nga agianan."}, "source": "encyclopedia-stable consensus; NRC PS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "sikwate-tablea-g5", "domain": "MATTER", "topic": "sikwate hot chocolate from cacao tablea", "grades": [4, 5, 6], "terms": ["sikwate", "tsokolate", "tablea", "kakaw", "cacao", "mainit na tsokolate", "natutunaw", "inumin", "tablea sa kakaw", "init nga tsokolate", "matunaw", "ilimnon", "hot chocolate", "dissolving"], "fact": {"tl": "Ang sikwate ay mainit na inuming tsokolate na gawa sa tablea, mga bilog na ginawa mula sa giniling na butil ng kakaw na natutunaw sa mainit na tubig o gatas.", "en": "Sikwate is a hot chocolate drink made from tablea, round disks of ground roasted cacao beans that dissolve into hot water or milk.", "bis": "Ang sikwate usa ka init nga ilimnong tsokolate nga hinimo sa tablea, mga lingin nga gikan sa giniling nga sinanlag nga liso sa kakaw nga matunaw sa init nga tubig o gatas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sinangag-garlic-rice-g5", "domain": "MATTER", "topic": "frying garlic rice (sinangag)", "grades": [4, 5, 6], "terms": ["sinangag", "kanin", "bawang", "prito", "ginisa", "init", "amoy", "mantika", "ahos", "kainit", "lana", "garlic rice", "frying", "browning", "heat"], "fact": {"tl": "Ang sinangag ay kaning iginisa sa mainit na mantika kasama ng bawang; ang init ay nagpapabrown sa bawang at kanin at lumilikha ng bagong masarap na amoy at lasa.", "en": "Sinangag is rice fried in hot oil with garlic; the heat browns the garlic and rice, creating new tasty smells and flavors through cooking.", "bis": "Ang sinangag mao ang kanon nga giprito sa init nga lana uban sa ahos; ang kainit makapabrown sa ahos ug kanon ug makahimo og bag-ong lami nga baho ug lasa."}, "source": "encyclopedia-stable consensus; NRC PS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "singkaban-bamboo-arch-g5", "domain": "LIVING_THINGS", "topic": "decorative carved bamboo arch (singkaban)", "grades": [4, 5, 6], "terms": ["singkaban", "kawayan", "inukit na kawayan", "arko", "kulot", "magaan", "matibay", "dekorasyon", "kinulit nga kawayan", "arko sa kawayan", "gaan", "lig-on", "carved bamboo", "arch"], "fact": {"tl": "Ang singkaban ay arko na gawa sa kawayan na inuukit upang gumawa ng kulot na hibla; magaan ito ngunit matibay dahil ang kawayan ay malakas na damo na may guwang na tangkay.", "en": "A singkaban is an arch made from bamboo carved into curled shavings; it is light yet strong because bamboo is a tall grass with hollow, sturdy stems.", "bis": "Ang singkaban usa ka arko nga hinimo sa kawayan nga gikulit aron makahimo og kulot nga himbis; gaan kini apan lig-on tungod kay ang kawayan usa ka taas nga sagbot nga adunay bakante ug malig-on nga punoan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "singkil-rhythm-timing-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "timing and rhythm in singkil bamboo dance", "grades": [5, 6, 7], "terms": ["singkil", "sayaw", "kawayan", "ritmo", "tiyempo", "galaw", "iwas sa kawayan", "kawayan nga gipasaghid", "lihok", "bamboo poles", "rhythm", "timing"], "fact": {"tl": "Sa Singkil, dalawang kawayan ang pinagsasalpok sa isang tuloy-tuloy na ritmo, at ang mananayaw ay dapat mag-time ng kanyang mga hakbang upang umiwas sa kawayan habang nagsasara ang mga ito.", "en": "In Singkil, two bamboo poles are clapped together in a steady rhythm, and the dancer must time each step to slip out before the poles snap shut.", "bis": "Sa Singkil, duha ka kawayan ang gipasaghid sa kanunay nga ritmo, ug ang mananayaw kinahanglan mag-time sa iyang lakang aron makalikay sa wala pa magtakup ang kawayan."}, "source": "encyclopedia-stable consensus; NRC PS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "single-water-drop-splash-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "surface tension and water drop splash", "grades": [5, 6, 7], "terms": ["patak ng tubig", "tulo", "splash", "korona", "surface tension", "tensiyon sa ibabaw", "tulo sa tubig", "korona sa tubig", "water drop", "crown"], "fact": {"tl": "Kapag may patak ng tubig na bumagsak sa lawa, ang surface tension ay humihila sa tubig pataas sa hugis-korona bago ito muling lumubog at maging mga maliliit na patak.", "en": "When a water drop falls onto a pool, surface tension pulls the water up into a tiny crown shape before it sinks back and breaks into smaller droplets.", "bis": "Kon ang usa ka tulo sa tubig matagak sa linaw, ang surface tension mobira sa tubig pataas nga porma-korona una kini molugdang pag-usab ug mabuak ngadto sa gagmay nga tulo."}, "source": "encyclopedia-stable consensus; NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "shato-stick-game-energy-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "energy transfer in shato stick game", "grades": [4, 5, 6], "terms": ["shato", "syato", "laro", "kahoy", "patpat", "pagtama", "puwersa", "enerhiya", "dula sa kahoy", "pwersa sa kahoy", "lupad", "stick game", "energy transfer"], "fact": {"tl": "Sa larong shato, hinahampas ng mahabang kahoy ang maikling patpat, at ang puwersa ng hampas ay naililipat sa maikling patpat kaya ito lumilipad palayo.", "en": "In the game shato, a long stick strikes a short stick, and the force of the hit transfers energy to the short stick so it flies away.", "bis": "Sa dula nga shato, ang taas nga kahoy mohampak sa mubo nga patpat, ug ang kusog sa hampak mobalhin og enerhiya ngadto sa mubo nga patpat busa kini molupad palayo."}, "source": "encyclopedia-stable consensus; NRC PS3.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "sinigang-soup-bowl-g4", "domain": "MATTER", "topic": "sour soup and dissolving sourness", "grades": [3, 4, 5], "terms": ["sinigang", "asim", "maasim", "sabaw", "sampalok", "kamatis", "init", "luto", "sour", "soup", "tamarind", "dissolve", "aslom", "maaslom", "lung-ag", "kahoy nga aslom"], "fact": {"tl": "Ang sinigang ay maasim na sabaw dahil natutunaw sa mainit na tubig ang asim mula sa sampalok o kamatis.", "en": "Sinigang is a sour soup because the sourness from tamarind or tomatoes dissolves into the hot water.", "bis": "Ang sinigang maaslom nga sabaw kay ang kaaslom gikan sa sampalok o kamatis matunaw sa init nga tubig."}, "source": "encyclopedia-stable consensus; NRC PS1.A (dissolving/mixtures)", "generator": "claude-workflow", "reviewed": false},
  {"id": "siomai-dumplings-g4", "domain": "MATTER", "topic": "cooking food with steam", "grades": [4, 5, 6], "terms": ["siomai", "dumpling", "singaw", "usok", "pagsingaw", "luto", "init", "tubig", "steam", "cook", "vapor", "alisngaw", "aso", "tubig nga nag-init"], "fact": {"tl": "Ang siomai ay niluluto sa singaw ng kumukulong tubig, na nagdadala ng init para magluto ito nang hindi nababad sa tubig.", "en": "Siomai is cooked by the steam of boiling water, which carries heat to cook it without soaking it in water.", "bis": "Ang siomai giluto pinaagi sa singaw sa nagbukal nga tubig, nga nagdala sa kainit aron maluto kini nga dili mahumod sa tubig."}, "source": "encyclopedia-stable consensus; NRC PS3.B (heat transfer)", "generator": "claude-workflow", "reviewed": false},
  {"id": "siopao-steamed-bun-g4", "domain": "MATTER", "topic": "yeast makes dough rise", "grades": [4, 5, 6], "terms": ["siopao", "tinapay", "lebadura", "pampaalsa", "umalsa", "masa", "singaw", "bun", "yeast", "rise", "dough", "patubo", "humboy", "minasa", "pagsingaw"], "fact": {"tl": "Ang siopao ay malambot at mabuhaghag dahil ang lebadura sa masa ay gumagawa ng maliliit na bula ng gas na nagpapaalsa nito bago isingaw.", "en": "Siopao is soft and fluffy because the yeast in the dough makes tiny gas bubbles that puff it up before it is steamed.", "bis": "Ang siopao humok ug malumo kay ang lebadura sa minasa nagbuhat ug gagmay nga bula sa gas nga nagpaburot niini sa dili pa singawan."}, "source": "encyclopedia-stable consensus; NRC LS1.C (yeast as living organism)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sipa-rattan-ball-kick-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "kicking force changes motion", "grades": [3, 4, 5], "terms": ["sipa", "rattan", "yantok", "bola", "sipain", "pwersa", "galaw", "laro", "kick", "force", "motion", "ball", "patid", "kusog", "lihok", "dula"], "fact": {"tl": "Sa larong sipa, ang puwersa ng iyong paa ang nagtutulak sa bolang yantok pataas, at babagsak ito pabalik dahil sa hila ng grabidad.", "en": "In the game of sipa, the force of your foot pushes the rattan ball upward, and it falls back down because gravity pulls it.", "bis": "Sa dula nga sipa, ang kusog sa imong tiil nagduso sa bola nga yantok pataas, ug mahulog kini balik tungod sa pagbira sa grabidad."}, "source": "encyclopedia-stable consensus; NRC PS2.A (forces and motion)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sipa-shuttlecock-net-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "air resistance slows a shuttlecock", "grades": [5, 6, 7], "terms": ["sipa", "shuttlecock", "balahibo", "hangin", "paghadlang", "bilis", "bagal", "lipad", "air resistance", "feather", "fall", "balhibo", "kapaspas", "lupad", "pagbabag sa hangin"], "fact": {"tl": "Ang balahibo ng shuttlecock ay sumasalo ng hangin na siyang nagpapabagal sa paglipad nito kaya dahan-dahan itong bumababa.", "en": "The feathers of a shuttlecock catch the air, which slows its flight so it comes down gently.", "bis": "Ang mga balhibo sa shuttlecock nagsalo sa hangin nga maoy nagpahinay sa paglupad niini busa hinay kini nga mokunsad."}, "source": "encyclopedia-stable consensus; NRC PS2.A (air resistance)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sisig-sizzling-plate-g4", "domain": "MATTER", "topic": "hot metal plate makes food sizzle", "grades": [4, 5, 6], "terms": ["sisig", "kawaling bakal", "mainit", "sizzling", "lagitik", "singaw", "bakal", "init", "plato", "hot plate", "metal", "sizzle", "init nga puthaw", "lagubong", "mainit nga plato"], "fact": {"tl": "Ang sisig ay lumalagitik sa mainit na platong bakal dahil mabilis na umiinit ang bakal at biglang sumisingaw ang likido sa pagkain.", "en": "Sisig sizzles on a hot metal plate because metal heats up quickly and the liquid in the food suddenly turns to steam.", "bis": "Ang sisig naglagubong sa init nga plato nga puthaw kay ang puthaw paspas mo-init ug ang likido sa pagkaon kalit nga mahimong singaw."}, "source": "encyclopedia-stable consensus; NRC PS3.B (heat conduction, evaporation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "siyanse-turner-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "a turner as a simple lever", "grades": [4, 5, 6], "terms": ["siyanse", "turner", "spatula", "pangbaligtad", "bakal", "luto", "pwersa", "angat", "lever", "flip", "balitok", "kusog", "pang-alsa", "puthaw"], "fact": {"tl": "Ang siyanse ay parang isang simpleng pingga na ginagamit upang itaas at ibaligtad ang pagkain nang hindi pinapaso ang kamay.", "en": "A turner works like a simple lever used to lift and flip food without burning your hand.", "bis": "Ang siyanse sama sa usa ka yano nga palanggana nga gigamit aron mo-alsa ug mobalitok sa pagkaon nga dili masunog ang imong kamot."}, "source": "encyclopedia-stable consensus; NRC PS2.A; AAAS (simple machines)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sky-lantern-release-g5", "domain": "MATTER", "topic": "hot air makes a lantern rise", "grades": [5, 6, 7], "terms": ["sky lantern", "parol", "lampara", "mainit na hangin", "gumagaan", "lumulutang", "apoy", "lipad", "hot air", "rise", "float", "init nga hangin", "magaan", "naglutaw", "kalayo", "lupad"], "fact": {"tl": "Lumilipad ang sky lantern dahil pinapainit ng apoy ang hangin sa loob, at ang mainit na hangin ay mas magaan kaya umaakyat ito.", "en": "A sky lantern flies because a flame heats the air inside, and warm air is lighter so it rises.", "bis": "Ang sky lantern molupad kay ang kalayo nagpainit sa hangin sa sulod, ug ang init nga hangin mas magaan busa mosaka kini."}, "source": "encyclopedia-stable consensus; NRC PS3 (thermal expansion, buoyancy of warm air)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sorbetes-dirty-ice-cream-cart-g4", "domain": "MATTER", "topic": "salt and ice keep ice cream frozen", "grades": [4, 5, 6], "terms": ["sorbetes", "ice cream", "yelo", "asin", "lamig", "natutunaw", "kariton", "frozen", "salt", "ice", "melt", "bugnaw", "natunaw"], "fact": {"tl": "Ang sorbetes ay pinapalamig sa pinaghalong yelo at asin, dahil pinapababa ng asin ang temperatura ng yelo para hindi mabilis matunaw ang sorbetes.", "en": "Sorbetes is kept cold by a mix of ice and salt, because salt lowers the ice's temperature so the ice cream does not melt quickly.", "bis": "Ang sorbetes gipabugnaw pinaagi sa sinagol nga yelo ug asin, kay ang asin nagpaubos sa temperatura sa yelo aron dili paspas matunaw ang sorbetes."}, "source": "encyclopedia-stable consensus; NRC PS1.A (freezing-point depression)", "generator": "claude-workflow", "reviewed": false},
  {"id": "spring-balance-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "spring balance measures weight", "grades": [5, 6, 7], "terms": ["spring balance", "timbangan", "spring", "bukal", "bigat", "puwersa", "grabidad", "Newton", "hila", "measure", "weight", "force", "tinggol", "kabug-aton", "kusog", "sukod", "bira"], "fact": {"tl": "Sumusukat ng bigat ang spring balance dahil mas binabanat ng mas mabigat na bagay ang spring sa loob nito.", "en": "A spring balance measures weight because a heavier object stretches the spring inside it more.", "bis": "Ang spring balance nagsukod sa kabug-aton kay ang mas bug-at nga butang mas mobira sa tinggol sa sulod niini."}, "source": "encyclopedia-stable consensus; NRC PS2.A (weight as gravitational force)", "generator": "claude-workflow", "reviewed": false},
  {"id": "stirring-rod-g5", "domain": "MATTER", "topic": "stirring helps things dissolve and mix", "grades": [4, 5, 6], "terms": ["stirring rod", "panghalo", "haluan", "baso", "halo", "tunaw", "timpla", "stir", "mix", "dissolve", "kutaw", "sagol", "haloon"], "fact": {"tl": "Ang stirring rod ay ginagamit sa laboratoryo upang haluin ang likido, na nagpapabilis sa pagkatunaw at paghahalo ng mga sangkap.", "en": "A stirring rod is used in the lab to mix liquids, which speeds up how fast substances dissolve and blend together.", "bis": "Ang stirring rod gigamit sa laboratoryo aron kutawon ang likido, nga nagpadali sa pagkatunaw ug pagsagol sa mga sangkap."}, "source": "encyclopedia-stable consensus; NRC PS1.A (mixtures, rate of dissolving)", "generator": "claude-workflow", "reviewed": false},
  {"id": "stopwatch-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "stopwatch measures time", "grades": [4, 5, 6], "terms": ["stopwatch", "orasan", "oras", "segundo", "sukat", "bilis", "takbo", "time", "seconds", "measure", "speed", "takna", "sukod", "kapaspas", "dagan"], "fact": {"tl": "Ang stopwatch ay sumusukat ng oras sa segundo, kaya nagagamit ito para malaman kung gaano kabilis tumakbo o gumalaw ang isang bagay.", "en": "A stopwatch measures time in seconds, so it is used to find out how fast something runs or moves.", "bis": "Ang stopwatch nagsukod sa oras sa segundo, busa gigamit kini aron mahibal-an kung unsa ka paspas modagan o molihok ang usa ka butang."}, "source": "encyclopedia-stable consensus; NRC PS2.A (measuring motion, speed = distance/time)", "generator": "claude-workflow", "reviewed": false},
  {"id": "suman-leaf-wrapping-g4", "domain": "LIVING_THINGS", "topic": "banana leaves used to wrap and cook food", "grades": [4, 5, 6], "terms": ["suman", "dahon ng saging", "balot", "kanin", "malagkit", "luto", "singaw", "leaf", "banana leaf", "wrap", "rice", "dahon sa saging", "putos", "kanon", "pilit", "dahon"], "fact": {"tl": "Ang suman ay binabalot sa dahon ng saging na pumipigil sa pagkadikit ng kanin at nagbibigay ng bango habang ito ay isinisingaw.", "en": "Suman is wrapped in banana leaves, which keep the rice from sticking and add aroma while it is steamed.", "bis": "Ang suman giputos sa dahon sa saging nga nagpugong sa pagpilit sa kanon ug naghatag ug kahumot samtang giluto kini sa singaw."}, "source": "encyclopedia-stable consensus; DepEd (plants and their uses)", "generator": "claude-workflow", "reviewed": false},
  {"id": "suman-rice-log-g4", "domain": "MATTER", "topic": "sticky rice cooked into a firm log", "grades": [4, 5, 6], "terms": ["suman", "malagkit", "kanin", "kakanin", "gata", "luto", "tigas", "rice", "sticky", "glutinous", "coconut", "pilit nga bugas", "kanon", "kakanon", "gahi"], "fact": {"tl": "Ang suman ay gawa sa malagkit na bigas na lumalapot at tumitigas kapag niluto, kaya nabubuo itong matatag na hugis-troso.", "en": "Suman is made from glutinous rice that thickens and firms up when cooked, so it holds together in a solid log shape.", "bis": "Ang suman gihimo gikan sa pilit nga bugas nga molapot ug mogahi kung luto na, busa magkahiusa kini sama sa lig-on nga troso."}, "source": "encyclopedia-stable consensus; NRC PS1.B (cooking as physical/chemical change)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sungka-board-game-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "counting and motion in sungka", "grades": [3, 4, 5], "terms": ["sungka", "sigay", "kabibe", "bato", "bilang", "laro", "tablero", "shell", "count", "board", "kinhason", "ihap", "dula", "tabla"], "fact": {"tl": "Sa sungka, ihinuhulog mo ang mga sigay isa-isa sa bawat butas, kaya tumutulong itong magsanay sa pagbibilang at maayos na paggalaw ng kamay.", "en": "In sungka, you drop shells one by one into each hole, so it helps you practice counting and steady hand movement.", "bis": "Sa sungka, ihulog nimo ang mga sigay tagsa-tagsa sa matag lungag, busa makatabang kini sa pagbansay sa pag-ihap ug lig-on nga paglihok sa kamot."}, "source": "encyclopedia-stable consensus; DepEd (numeracy, motor skills)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sungka-shell-counting-g4", "domain": "LIVING_THINGS", "topic": "seashells come from sea animals", "grades": [3, 4, 5], "terms": ["sigay", "kabibe", "kinhason", "dagat", "hayop", "bahay", "matigas", "shell", "sea animal", "cowrie", "kabibi", "balay", "gahi"], "fact": {"tl": "Ang mga sigay na ginagamit sa sungka ay galing sa mga kuhol sa dagat na tinatawag na cowrie, na gumagawa ng matigas na bahay para protektahan ang kanilang malambot na katawan.", "en": "The shells used in sungka come from sea snails called cowries, which build a hard shell to protect their soft bodies.", "bis": "Ang mga sigay nga gigamit sa sungka gikan sa mga kuhol sa dagat nga gitawag ug cowrie, nga naghimo ug gahi nga balay aron panalipdan ang ilang humok nga lawas."}, "source": "encyclopedia-stable consensus; NRC LS1.A (animal structures for protection)", "generator": "claude-workflow", "reviewed": false},
  {"id": "table-tennis-paddle-ball-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "a bouncing table tennis ball", "grades": [4, 5, 6], "terms": ["table tennis", "ping pong", "bola", "raketa", "talbog", "tumalbog", "magaan", "pwersa", "bounce", "ball", "paddle", "lukso", "kusog"], "fact": {"tl": "Ang bola ng table tennis ay napakagaan at gawa sa hungkag na plastik, kaya mabilis itong tumatalbog kapag tinatamaan ng raketa.", "en": "A table tennis ball is very light and made of hollow plastic, so it bounces quickly when the paddle hits it.", "bis": "Ang bola sa table tennis gaan kaayo ug hinimo sa hawan nga plastik, busa paspas kini molukso kung igo-on sa raketa."}, "source": "encyclopedia-stable consensus; NRC PS2.A (elastic collision, forces)", "generator": "claude-workflow", "reviewed": false},
  {"id": "taho-soy-pudding-g5", "domain": "MATTER", "topic": "taho soybean curd coagulation", "grades": [5, 6, 7], "terms": ["taho", "toyo", "soybean", "soya", "utaw", "balatong", "soybeans", "curd", "namuo", "namuong", "kinurba", "coagulate", "namo-o", "gulaman", "protina", "protein", "tofu", "soy pudding"], "fact": {"tl": "Ang taho ay gawa sa gatas ng soybean na pinalapot o pinamuo gamit ang isang sangkap kaya nagiging malambot na parang gulaman.", "en": "Taho is made from soybean milk that is thickened, or coagulated, into a soft jelly-like curd by adding a setting agent.", "bis": "Ang taho hinimo gikan sa gatas sa soybean nga gipalapot o gipamuo pinaagi sa usa ka sangkap aron mahimong humok nga sama sa gulaman."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tahong-baked-mussels-g5", "domain": "LIVING_THINGS", "topic": "tahong mussel bivalve filter feeder", "grades": [4, 5, 6], "terms": ["tahong", "mussel", "mussels", "kabibe", "shellfish", "bivalve", "filter feeder", "talaba", "kinason", "mollusk", "molusko", "kabhang", "shell", "nagsala", "tubig"], "fact": {"tl": "Ang tahong ay isang lamang-dagat na may dalawang kabibe at kumakain sa pamamagitan ng pagsala ng maliliit na pagkain mula sa tubig-dagat.", "en": "The tahong (mussel) is a shellfish with two shells that feeds by filtering tiny food particles out of the seawater.", "bis": "Ang tahong usa ka shellfish nga adunay duha ka kabhang ug mokaon pinaagi sa pagsala sa gagmay nga pagkaon gikan sa tubig-dagat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tambol-marching-drum-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "drum vibration produces sound", "grades": [3, 4, 5], "terms": ["tambol", "drum", "tambor", "marching drum", "kahoy", "balat", "panit", "membrane", "vibration", "tugtog", "tunog", "tingog", "vibrate", "nayanig", "uyog", "sound", "percussion"], "fact": {"tl": "Kapag pinukpok ang tambol, nayayanig ang nakaunat na balat nito at ang panginginig na ito ang gumagawa ng tunog na dumadaan sa hangin.", "en": "When a drum is struck, its stretched skin vibrates, and that vibration makes the sound that travels through the air to our ears.", "bis": "Kon bunalan ang tambol, mauyog ang gibira nga panit niini, ug kini nga pag-uyog mao ang naghimo sa tingog nga moagi sa hangin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tambourine-instrument-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "tambourine jingles vibration sound", "grades": [3, 4, 5], "terms": ["tambourine", "pandereta", "jingles", "metal", "metal disks", "kalansing", "tugtog", "tunog", "tingog", "vibration", "uyog", "yanig", "shake", "kalog", "uyogon", "sound", "percussion", "instrumento"], "fact": {"tl": "Kapag niyanig o pinukpok ang tambourine, naguuumpugan ang maliliit na metal na disk nito kaya gumagawa ito ng matinis na kalansing.", "en": "When a tambourine is shaken or tapped, its little metal disks knock together and vibrate, making a bright jingling sound.", "bis": "Kon uyogon o tapikon ang tambourine, magbinangga ang gagmay nga metal nga disk niini ug mag-uyog, busa mohimo kini og tin-aw nga kalansing."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tambuli-carabao-horn-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "tambuli horn air column sound", "grades": [4, 5, 6], "terms": ["tambuli", "carabao horn", "sungay", "kalabaw", "kabaw", "sungay sa kabaw", "horn", "hihip", "huyop", "tingog", "tunog", "hangin", "air column", "vibrate", "instrumento", "tawag", "sound"], "fact": {"tl": "Ang tambuli ay gawa sa sungay ng kalabaw, at kapag inihip ito, ang panginginig ng hangin sa loob nito ang gumagawa ng malakas na tunog na naririnig sa malayo.", "en": "The tambuli is made from a carabao's horn, and when you blow into it, the vibrating air inside makes a loud sound that carries far.", "bis": "Ang tambuli hinimo gikan sa sungay sa kabaw, ug kon huypan kini, ang nag-uyog nga hangin sa sulod mao ang naghimo sa kusog nga tingog nga madungog sa layo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tapa-beef-meal-g6", "domain": "MATTER", "topic": "tapa cured dried meat preservation", "grades": [5, 6, 7], "terms": ["tapa", "beef tapa", "karne", "baka", "binilad", "pinatuyo", "asin", "salt", "cured", "dried meat", "preserve", "pagpreserba", "gipauga", "uga nga karne", "pagtipig", "bakteria", "bacteria", "food preservation"], "fact": {"tl": "Ang tapa ay karneng inasnan at pinatuyo, dahil ang pagtanggal ng tubig at pagdagdag ng asin ay pumipigil sa mga bakteryang nagpapabulok kaya tumatagal ito.", "en": "Tapa is meat that is salted and dried, because removing water and adding salt stops the bacteria that cause spoiling, so the meat keeps longer.", "bis": "Ang tapa karne nga giasinan ug gipauga, kay ang pagkuha sa tubig ug pagdugang og asin makapugong sa bakterya nga magpadunot, busa molungtad kini og dugay."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tatsing-bottlecap-game-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "flicking bottle cap force friction motion", "grades": [3, 4, 5], "terms": ["tatsing", "bottlecap", "tansan", "bottle cap", "pitik", "flick", "puwersa", "force", "gumagalaw", "kuskos", "friction", "natigil", "pitikon", "lihok", "motion", "laro", "dula"], "fact": {"tl": "Sa tatsing, kapag pinitik mo ang tansan, ang puwersa mo ang nagpapakilos dito, at ang kuskos sa lupa ang dahan-dahang nagpapahinto nito.", "en": "In tatsing, when you flick a bottle cap, your force sets it moving, and friction with the ground slowly brings it to a stop.", "bis": "Sa tatsing, kon pitikon nimo ang tansan, ang imong kusog maoy nagpalihok niini, ug ang kuskos sa yuta maoy hinay-hinay nga nagpahunong niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "test-tube-g5", "domain": "MATTER", "topic": "test tube laboratory glassware", "grades": [4, 5, 6], "terms": ["test tube", "test-tube", "salamin", "baso", "glass", "lab", "laboratoryo", "kagamitan", "pagsubok", "experiment", "eksperimento", "likido", "liquid", "init", "heat", "sudlanan", "container", "tubo"], "fact": {"tl": "Ang test tube ay isang manipis na tubong salamin na ginagamit sa laboratoryo para maghalo, magpainit, o mag-obserba ng maliit na dami ng likido.", "en": "A test tube is a thin glass tube used in the laboratory to mix, heat, or observe small amounts of liquid during experiments.", "bis": "Ang test tube usa ka nipis nga tubo nga salamin nga gigamit sa laboratoryo aron magsagol, magpainit, o mag-obserbar og gamay nga likido sa mga eksperimento."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tikoy-sticky-cake-g6", "domain": "MATTER", "topic": "tikoy glutinous rice starch sticky", "grades": [5, 6, 7], "terms": ["tikoy", "sticky cake", "malagkit", "glutinous rice", "kakanin", "bigas", "almirol", "starch", "malagkit na bigas", "pilit", "sticky", "rice cake", "asukal", "pagkaon", "bugas"], "fact": {"tl": "Ang tikoy ay gawa sa malagkit na bigas na maraming almirol, kaya kapag niluto ay nagiging makunat at malagkit ito.", "en": "Tikoy is made from glutinous rice that is rich in starch, which is why it becomes chewy and sticky when cooked.", "bis": "Ang tikoy hinimo gikan sa pilit nga bugas nga daghan og almirol, mao nga kon lutoon mahimo kining unat ug pilit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tilling-soil-hoe-garden-g5", "domain": "EARTH_SPACE", "topic": "tilling soil aeration loosening for planting", "grades": [4, 5, 6], "terms": ["tilling", "soil", "lupa", "yuta", "araro", "asarol", "hoe", "pagbungkal", "loosen", "luag", "aerate", "hangin", "air", "tanim", "gibungkal", "ugat", "gamot", "roots", "pananim", "garden", "hardin", "pagdaro", "soil preparation"], "fact": {"tl": "Ang pagbungkal ng lupa ay nagluluwag dito para makapasok ang hangin at tubig, kaya mas madaling tumubo ang ugat ng pananim.", "en": "Tilling loosens the soil so air and water can get in, making it easier for plant roots to grow.", "bis": "Ang pagbungkal sa yuta makapaluag niini aron makasulod ang hangin ug tubig, busa mas sayon motubo ang gamot sa tanom."}, "source": "DepEd Science soil/agriculture; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tinapa-smoked-fish-g6", "domain": "MATTER", "topic": "tinapa smoked fish preservation", "grades": [5, 6, 7], "terms": ["tinapa", "smoked fish", "isda", "isdang pinausukan", "usok", "smoke", "pinausukan", "gipaaso", "aso", "asin", "salt", "preserve", "pagpreserba", "tinap-an", "bakteria", "bacteria", "uga", "dried", "preservation", "galunggong"], "fact": {"tl": "Ang tinapa ay isdang inasnan at pinausukan, dahil ang usok at asin ay tumutulong na pumatay sa mikrobyo kaya tumatagal nang hindi nabubulok.", "en": "Tinapa is fish that is salted and smoked, because the smoke and salt help kill microbes so the fish keeps without spoiling.", "bis": "Ang tinapa isda nga giasinan ug gipaaso, kay ang aso ug asin makatabang sa pagpatay sa mga mikrobyo busa molungtad kini nga dili madunot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tinapay-monay-yeast-g6", "domain": "LIVING_THINGS", "topic": "bread yeast fermentation rising", "grades": [5, 6, 7], "terms": ["tinapay", "monay", "bread", "pan", "lebadura", "yeast", "fermentation", "pagbuburo", "umalsa", "rise", "umaalsa", "carbon dioxide", "bula", "fungi", "halamang-singaw", "mihubag", "harina", "flour", "buhi nga organismo"], "fact": {"tl": "Ang tinapay na gaya ng monay ay umaalsa dahil sa lebadura, isang maliit na buhay na organismo na naglalabas ng gas na carbon dioxide sa loob ng masa.", "en": "Bread like monay rises because of yeast, a tiny living organism that releases carbon dioxide gas inside the dough.", "bis": "Ang tinapay nga sama sa monay mohubag tungod sa lebadura, usa ka gamay nga buhi nga organismo nga mogawas og gas nga carbon dioxide sulod sa minasa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tinikling-bamboo-poles-g5", "domain": "LIVING_THINGS", "topic": "bamboo fast-growing grass strong light pole", "grades": [4, 5, 6], "terms": ["tinikling", "kawayan", "bamboo", "kawayanon", "poles", "poste", "damo", "grass", "mabilis tumubo", "fast-growing", "magaan", "light", "matibay", "strong", "hollow", "guang", "halaman", "plant", "tanom"], "fact": {"tl": "Ang mga poste sa tinikling ay gawa sa kawayan, isang napakabilis tumubong halaman na magaan ngunit matibay dahil hungkag ang loob nito.", "en": "The poles in tinikling are made of bamboo, a very fast-growing plant that is light yet strong because it is hollow inside.", "bis": "Ang mga poste sa tinikling hinimo gikan sa kawayan, usa ka paspas kaayo motubo nga tanom nga magaan apan lig-on tungod kay guang ang sulod niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tnalak-abaca-cloth-g6", "domain": "LIVING_THINGS", "topic": "tnalak abaca plant fiber weaving", "grades": [5, 6, 7], "terms": ["tnalak", "t'nalak", "abaca", "abaka", "Manila hemp", "hibla", "fiber", "lanot", "tela", "cloth", "panapton", "habi", "weave", "gihabol", "halaman", "plant", "saging", "banana", "T'boli", "tanom", "lubid", "natural fiber"], "fact": {"tl": "Ang t'nalak ay tela na hinahabi ng mga T'boli mula sa hibla ng abaka, isang halamang kamukha ng saging na pinagkukunan ng matibay na lanot.", "en": "T'nalak is a cloth woven by the T'boli people from the fiber of the abaca, a banana-like plant that gives strong natural fibers.", "bis": "Ang t'nalak usa ka panapton nga gihabol sa mga T'boli gikan sa lanot sa abaka, usa ka tanom nga morag saging nga gigikanan sa lig-on nga hibla."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "abandoned-fishpond-conversion-scene-g6", "domain": "LIVING_THINGS", "topic": "habitat change and ecosystem recovery", "grades": [6, 7, 8], "terms": ["palaisdaan", "iniwang palaisdaan", "tirahan", "kapaligiran", "halamang-bakawan", "fishpond", "abandoned fishpond", "habitat", "mangrove", "ecosystem", "gibiyaan nga pundohanan", "puy-anan", "kinaiyahan", "bakhaw"], "fact": {"tl": "Kapag iniwan ang isang palaisdaan, unti-unting bumabalik ang mga halaman tulad ng bakawan at nagiging tirahan muli ito ng mga isda, hipon, at ibon.", "en": "When a fishpond is abandoned, plants like mangroves slowly return and it becomes a habitat again for fish, shrimp, and birds.", "bis": "Kon biyaan ang usa ka pundohanan sa isda, hinay-hinay nga mobalik ang mga tanom sama sa bakhaw ug mahimo na usab kining puy-anan sa mga isda, pasayan, ug langgam."}, "source": "encyclopedia-stable consensus; NRC LS2.C ecosystem dynamics", "generator": "claude-workflow", "reviewed": false},
  {"id": "acacia-g5", "domain": "LIVING_THINGS", "topic": "large shade tree", "grades": [4, 5, 6], "terms": ["akasya", "acacia", "punong akasya", "lilim", "shade tree", "malaking puno", "dahon", "kahoy nga akasya", "landong", "dagkong kahoy", "rain tree"], "fact": {"tl": "Ang akasya ay isang malaking punong nagbibigay ng malawak na lilim at may maliliit na dahong nagsasara kapag gabi o umuulan.", "en": "The acacia is a large tree that gives wide shade and has tiny leaves that fold up at night or when it rains.", "bis": "Ang akasya usa ka dakong kahoy nga naghatag ug halapad nga landong ug adunay gagmayng dahon nga mosira kon gabii o mag-ulan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "backyard-chicken-coop-scene-g4", "domain": "LIVING_THINGS", "topic": "raising animals for food", "grades": [3, 4, 5], "terms": ["kulungan ng manok", "manukan", "manok", "alagang hayop", "itlog", "chicken coop", "backyard chicken", "raising animals", "pag-aalaga", "kulungan", "manok nga giatiman", "giamuma", "tagana"], "fact": {"tl": "Ang kulungan ng manok sa bakuran ay nagbibigay ng ligtas na tirahan sa mga alagang manok na nagbibigay naman ng itlog at karne sa pamilya.", "en": "A backyard chicken coop gives raised chickens a safe shelter, and the chickens in turn provide the family with eggs and meat.", "bis": "Ang kulungan sa manok sa likod sa balay naghatag ug luwas nga puy-anan sa mga giatimang manok nga naghatag usab ug itlog ug karne sa pamilya."}, "source": "encyclopedia-stable consensus; DepEd Science livestock", "generator": "claude-workflow", "reviewed": false},
  {"id": "beetle-g4", "domain": "LIVING_THINGS", "topic": "insects with hard wing covers", "grades": [3, 4, 5], "terms": ["salagubang", "uwang", "beetle", "kulisap", "insekto", "matigas na pakpak", "anim na paa", "bakukang", "gahi nga pako", "unom ka tiil"], "fact": {"tl": "Ang salagubang ay isang insektong may anim na paa at may matigas na panakip sa pakpak na nag-iingat sa malambot nitong lumilipad na pakpak.", "en": "A beetle is an insect with six legs and a hard wing cover that protects its soft flying wings underneath.", "bis": "Ang bakukang usa ka insekto nga adunay unom ka tiil ug gahi nga tabon sa pako nga nanalipod sa humok niini nga molupad nga pako sa ilalom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "insect-net-catch-garden-g4", "domain": "LIVING_THINGS", "topic": "observing insects / scientific tools", "grades": [3, 4, 5], "terms": ["lambat-panghuli", "panghuli ng insekto", "insect net", "pagmamasid", "insekto", "hardin", "siyensiya", "pukot sa insekto", "pagpaniid", "tanaman", "pagsiksik sa kinaiyahan"], "fact": {"tl": "Gumagamit ng lambat-panghuli ng insekto ang mga bata sa hardin upang maingat na mahuli at mapagmasdan ang mga kulisap bago ito muling pakawalan.", "en": "Children use an insect net in the garden to gently catch and observe insects before letting them go again.", "bis": "Naggamit ang mga bata ug pukot sa hardin aron hinay-hinay nga madakpan ug maobserbahan ang mga insekto sa dili pa kini buhian pag-usab."}, "source": "encyclopedia-stable consensus; scientific observation", "generator": "claude-workflow", "reviewed": false},
  {"id": "kangkong-vine-g5", "domain": "LIVING_THINGS", "topic": "hollow stems and floating plants", "grades": [4, 5, 6], "terms": ["kangkong", "tangkay ng kangkong", "guwang na tangkay", "lumulutang", "tubig", "hollow stem", "vine", "guwang nga punoan", "naglutaw sa tubig", "tangkay"], "fact": {"tl": "Ang baging ng kangkong ay may guwang na tangkay na puno ng hangin, kaya nakakalutang ito sa ibabaw ng tubig.", "en": "The kangkong vine has a hollow, air-filled stem, which lets it float on the surface of the water.", "bis": "Ang punoan sa kangkong adunay guwang nga tangkay nga puno sa hangin, mao nga makalutaw kini sa ibabaw sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "moss-g5", "domain": "LIVING_THINGS", "topic": "non-flowering plants", "grades": [5, 6, 7], "terms": ["lumot", "moss", "halamang walang bulaklak", "spore", "basa", "mamasa-masa", "tubig", "non-flowering plant", "tanom nga walay bulak", "spora", "humog", "basa nga dapit"], "fact": {"tl": "Ang lumot ay maliliit na halamang walang bulaklak na tumutubo sa mamasa-masang lugar at dumarami sa pamamagitan ng spore sa halip na buto.", "en": "Moss is a tiny non-flowering plant that grows in damp places and reproduces using spores instead of seeds.", "bis": "Ang lumot gagmayng tanom nga walay bulak nga motubo sa humog nga dapit ug modaghan pinaagi sa spora imbis sa liso."}, "source": "encyclopedia-stable consensus; plant classification", "generator": "claude-workflow", "reviewed": false},
  {"id": "torso-composite-g5", "domain": "LIVING_THINGS", "topic": "internal organs of the torso", "grades": [5, 6, 7], "terms": ["katawan", "torso", "puso", "baga", "tiyan", "atay", "panloob na organ", "internal organs", "lawas", "kasingkasing", "sulod nga organo"], "fact": {"tl": "Sa loob ng torso o gitnang bahagi ng katawan ay nakapaloob ang mahahalagang organ tulad ng puso, baga, tiyan, at atay na nagpapanatiling buhay sa atin.", "en": "Inside the torso, the middle part of the body, are vital organs like the heart, lungs, stomach, and liver that keep us alive.", "bis": "Sulod sa torso o tunga nga bahin sa lawas anaa ang importanteng organo sama sa kasingkasing, baga, tiyan, ug atay nga nagtipig kanato nga buhi."}, "source": "encyclopedia-stable consensus; human body systems", "generator": "claude-workflow", "reviewed": false},
  {"id": "balloon-g5", "domain": "MATTER", "topic": "gases and air pressure", "grades": [4, 5, 6], "terms": ["lobo", "balloon", "hangin", "gas", "lumalaki", "presyon", "humihip", "air pressure", "globo", "molupong", "presyur"], "fact": {"tl": "Kapag hinipan ang lobo, napupuno ito ng hangin na isang gas, at lumalaki ito dahil itinutulak ng hangin ang manipis na goma palabas.", "en": "When you blow into a balloon, it fills with air, which is a gas, and it gets bigger because the air pushes the thin rubber outward.", "bis": "Kon huyopan ang globo, mapuno kini sa hangin nga usa ka gas, ug modako kini tungod kay ang hangin moduso sa nipis nga goma pagawas."}, "source": "NRC PS1.A states of matter; gases", "generator": "claude-workflow", "reviewed": false},
  {"id": "dry-ice-smoke-bowl-g7", "domain": "MATTER", "topic": "sublimation of dry ice", "grades": [6, 7, 8], "terms": ["dry ice", "tuyong yelo", "usok", "sublimation", "carbon dioxide", "gas", "lamig", "singaw", "uga nga yelo", "aso", "bugnaw"], "fact": {"tl": "Ang dry ice ay matigas na carbon dioxide na direktang nagiging gas nang hindi nauuna sa likido, kaya gumagawa ito ng makapal na usok na parang ulap.", "en": "Dry ice is solid carbon dioxide that turns straight into a gas without first becoming a liquid, so it makes a thick, cloud-like smoke.", "bis": "Ang dry ice gahi nga carbon dioxide nga diretso nga mahimong gas nga dili una mahimong likido, mao nga makahimo kini ug baga nga aso nga daw panganod."}, "source": "NRC PS1.A; encyclopedia-stable consensus on sublimation", "generator": "claude-workflow", "reviewed": false},
  {"id": "hydrocarbons-g8", "domain": "MATTER", "topic": "compounds of carbon and hydrogen", "grades": [8, 9, 10], "terms": ["hydrocarbon", "haydrokarbon", "karbon", "haydroheno", "gasolina", "langis", "natural gas", "fuel", "carbon", "hydrogen", "lana", "natural nga gas", "sugnod"], "fact": {"tl": "Ang hydrocarbon ay isang compound na binubuo lamang ng carbon at hydrogen, at ito ang pangunahing sangkap ng gasolina, langis, at natural gas na ginagamit nating panggatong.", "en": "A hydrocarbon is a compound made only of carbon and hydrogen, and it is the main component of gasoline, oil, and natural gas that we use for fuel.", "bis": "Ang hydrocarbon usa ka compound nga gilangkuban lamang sa carbon ug hydrogen, ug mao kini ang pangunang sangkap sa gasolina, lana, ug natural nga gas nga atong gamiton isip sugnod."}, "source": "encyclopedia-stable consensus; chemistry of carbon compounds", "generator": "claude-workflow", "reviewed": false},
  {"id": "laundry-by-hand-batya-scene-g5", "domain": "MATTER", "topic": "soap, water, and cleaning", "grades": [4, 5, 6], "terms": ["paglalaba", "batya", "sabon", "labada", "kuskos", "dumi", "tubig", "soap", "laundry", "paghugas", "labhanan", "kuso-kuso", "hugaw"], "fact": {"tl": "Kapag naglalaba sa batya, tumutulong ang sabon na pagkabit-kabitin ang langis at dumi sa tubig upang madaling matanggal ito sa damit.", "en": "When washing clothes by hand in a basin, soap helps grab oil and dirt and mix them into the water so they wash out of the cloth.", "bis": "Kon manglaba sa batya, ang sabon motabang sa pagkupot sa lana ug hugaw ngadto sa tubig aron sayon kining matangtang gikan sa sapot."}, "source": "encyclopedia-stable consensus; chemistry of soap", "generator": "claude-workflow", "reviewed": false},
  {"id": "quantum-orbitals-g10", "domain": "MATTER", "topic": "electron orbitals in atoms", "grades": [9, 10], "terms": ["orbital", "elektron", "atomo", "ulap ng elektron", "antas ng enerhiya", "electron orbital", "atom", "energy level", "panganod sa elektron", "ang-ang sa enerhiya"], "fact": {"tl": "Ang orbital ay isang rehiyon sa paligid ng atomo kung saan malamang matagpuan ang mga elektron, at parang ulap ito sa halip na pabilog na landas.", "en": "An orbital is a region around an atom where electrons are most likely to be found, and it is more like a cloud than a circular path.", "bis": "Ang orbital usa ka rehiyon sa palibot sa atomo diin lagmit makit-an ang mga elektron, ug daw panganod kini imbis lingin nga agianan."}, "source": "encyclopedia-stable consensus; atomic structure", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-g5", "domain": "EARTH_SPACE", "topic": "the planet Earth", "grades": [4, 5, 6], "terms": ["mundo", "daigdig", "Earth", "planeta", "tubig", "hangin", "buhay", "tahanan", "kalibutan", "yuta", "kinabuhi"], "fact": {"tl": "Ang Earth o mundo ang ikatlong planeta mula sa araw at ang tanging planetang kilalang may likidong tubig at buhay sa ibabaw nito.", "en": "Earth is the third planet from the sun and the only known planet with liquid water and life on its surface.", "bis": "Ang Earth o kalibutan mao ang ikatulong planeta gikan sa adlaw ug mao ra ang nailhang planeta nga adunay likido nga tubig ug kinabuhi sa ibabaw niini."}, "source": "encyclopedia-stable consensus; NRC ESS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "rescue-raft-floodwater-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "raft buoyancy floating rescue", "grades": [4, 5, 6], "terms": ["balsa", "rescue raft", "gakit", "baha", "floodwater", "lumulutang", "naglutaw", "tubig", "buoyancy", "timbang", "bigat", "nakakalutang", "tumutulak pataas", "motukmod"], "fact": {"tl": "Ang balsa ay lumulutang sa baha dahil itinutulak ito pataas ng tubig nang mas malakas kaysa sa bigat nito, kaya kaya nitong magdala ng mga tao palayo sa panganib.", "en": "A rescue raft floats on floodwater because the water pushes up on it harder than its weight, so it can carry people away from danger.", "bis": "Ang gakit molutaw sa baha tungod kay ang tubig motukmod niini pataas nga mas kusog kaysa kabug-at niini, busa makahimo kini sa pagdala sa mga tawo palayo sa kakuyaw."}, "source": "AAAS Benchmarks 4F (buoyancy); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "river-buffer-strip-conservation-g6", "domain": "LIVING_THINGS", "topic": "riparian buffer strip soil erosion conservation", "grades": [5, 6, 7], "terms": ["pampang ng ilog", "buffer strip", "halamang pampang", "tanim sa tabi ng ilog", "ugat", "gamot", "soil erosion", "pagguho ng lupa", "pagkahugno", "tubig", "nagsasala", "masala", "daplin sa suba"], "fact": {"tl": "Ang mga puno at damo sa tabi ng ilog ay humahawak sa lupa gamit ang kanilang ugat, kaya napipigilan nila ang pagguho ng lupa at nasasala nila ang dumi bago ito umabot sa tubig.", "en": "Trees and grasses planted along a riverbank hold the soil with their roots, so they prevent erosion and filter out dirt before it reaches the water.", "bis": "Ang mga kahoy ug sagbot sa daplin sa suba mokupot sa yuta pinaagi sa ilang mga gamot, busa mapugngan nila ang pagkahugno sa yuta ug masala ang hugaw sa dili pa kini moabot sa tubig."}, "source": "NRC LS2.C, ESS3.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "seismograph-g6", "domain": "EARTH_SPACE", "topic": "seismograph earthquake measurement instrument", "grades": [6, 7, 8], "terms": ["seismograph", "seismograpo", "lindol", "linog", "earthquake", "alon", "balod", "pagyanig", "pag-uyog", "PHIVOLCS", "sumusukat", "mosukod", "nagrerekord", "morekord", "magnitude", "lakas ng lindol"], "fact": {"tl": "Ang seismograph ay isang kasangkapan na sumusukat at nagtatala ng mga alon ng pagyanig ng lupa habang may lindol, kaya nalalaman ng mga siyentipiko kung gaano kalakas ito.", "en": "A seismograph is an instrument that measures and records the shaking waves of the ground during an earthquake, so scientists can tell how strong it was.", "bis": "Ang seismograph usa ka galamiton nga mosukod ug morekord sa mga balod sa pag-uyog sa yuta panahon sa linog, busa mahibal-an sa mga siyentista kung unsa kini kakusog."}, "source": "NRC ESS2.B; PHIVOLCS; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-pillar-light-column-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "sun pillar ice crystal light reflection", "grades": [6, 7, 8], "terms": ["haligi ng liwanag", "sun pillar", "haligi ng araw", "kristal ng yelo", "ice crystal", "liwanag", "sinag", "silaw", "reflection", "mabanaag", "naaaninag", "ulap", "kahayag"], "fact": {"tl": "Ang sun pillar ay isang patayong guhit ng liwanag na lumilitaw sa itaas o ibaba ng araw kapag ang sinag nito ay naaaninag sa mga maliliit na patag na kristal ng yelo sa hangin.", "en": "A sun pillar is a vertical streak of light that appears above or below the sun when its light reflects off tiny flat ice crystals floating in the air.", "bis": "Ang sun pillar usa ka tindog nga linya sa kahayag nga motungha sa ibabaw o ilawom sa adlaw kung ang silaw niini mabanaag sa gagmay nga patag nga mga kristal sa yelo nga naglutaw sa hangin."}, "source": "Encyclopedia-stable consensus (atmospheric optics)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sundial-g5", "domain": "EARTH_SPACE", "topic": "sundial shadow earth rotation timekeeping", "grades": [4, 5, 6], "terms": ["sundial", "orasan ng araw", "anino", "landong", "shadow", "araw", "oras", "takna", "pag-ikot ng mundo", "nagatuyok", "rotation", "gumagalaw ang anino", "relo sa adlaw"], "fact": {"tl": "Ang sundial ay isang lumang orasan na gumagamit ng anino na inihahagis ng isang patpat sa ilalim ng araw, at gumagalaw ang anino habang umiikot ang mundo kaya napapakita nito ang oras.", "en": "A sundial is an old clock that uses the shadow cast by a stick in the sunlight, and the shadow moves as the Earth rotates, which shows the time of day.", "bis": "Ang sundial usa ka karaan nga orasan nga naggamit sa landong nga ginahimo sa usa ka sungkod ubos sa silaw sa adlaw, ug ang landong molihok samtang nagatuyok ang kalibutan, busa makita ang takna."}, "source": "NRC ESS1.B (Earth's rotation); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "waterfall-scene-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "waterfall gravity falling water energy", "grades": [4, 5, 6], "terms": ["talon", "waterfall", "busay", "tubig", "ilog", "suba", "bumabagsak", "mahulog", "grabidad", "gravity", "bato", "pababa", "paubos", "nahuhulog", "bangin"], "fact": {"tl": "Ang talon ay nabubuo kapag ang tubig ng ilog ay bumabagsak mula sa mataas na bato patungo sa mababa dahil hinihila ito pababa ng grabidad.", "en": "A waterfall forms when river water drops from a high rocky ledge to a lower level because gravity pulls the water downward.", "bis": "Ang busay maporma kung ang tubig sa suba mahulog gikan sa habog nga bato paingon sa ubos tungod kay ang grabidad mobira sa tubig paubos."}, "source": "NRC PS2.B (gravity), ESS2.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "abacus-counting-frame-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "abacus counting tool sliding beads", "grades": [3, 4, 5], "terms": ["abacus", "abako", "bilangan", "pagbilang", "pag-ihap", "butones", "beads", "bola", "counting", "kawad", "alambre", "dumudulas", "modan-as", "matematika", "laray"], "fact": {"tl": "Ang abacus ay isang lumang kasangkapan sa pagbilang na may mga butones na dumudulas sa mga kawad, at bawat hilera ng butones ay kumakatawan sa mga numero.", "en": "An abacus is an old counting tool with beads that slide along rods, where each row of beads stands for numbers like ones, tens, and hundreds.", "bis": "Ang abacus usa ka karaan nga galamiton sa pag-ihap nga adunay mga bola nga modan-as sa mga alambre, ug ang matag laray sa bola nagrepresentar sa mga numero."}, "source": "Encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "almires-mortar-g4", "domain": "MATTER", "topic": "mortar pestle grinding crushing force", "grades": [3, 4, 5], "terms": ["almires", "lusong", "dikdikan", "mortar", "pestle", "alho", "halo", "bawang", "ahos", "paminta", "pagdurog", "nagdidikdik", "dugmokon", "pulbos", "pino"], "fact": {"tl": "Ang almires ay isang matibay na mangkok na ginagamit kasama ng halo upang durugin ang bawang, paminta, o luya sa pamamagitan ng pagpukpok at paggiling.", "en": "A mortar (almires) is a hard bowl used with a pestle to crush garlic, pepper, or ginger into tiny pieces by pounding and grinding them.", "bis": "Ang almires usa ka gahi nga panaksan nga gamiton uban sa alho aron dugmokon ang ahos, paminta, o luy-a pinaagi sa pagbunal ug paggaling niini."}, "source": "Encyclopedia-stable consensus (physical change by force)", "generator": "claude-workflow", "reviewed": false},
  {"id": "amakan-woven-panel-g5", "domain": "LIVING_THINGS", "topic": "amakan woven bamboo panel plant material", "grades": [4, 5, 6], "terms": ["amakan", "sawali", "kawayan", "bamboo", "habi", "hinabol", "woven panel", "dingding", "bongbong", "bahay", "balay", "halaman", "tanom", "matibay", "magaan", "gaan"], "fact": {"tl": "Ang amakan ay isang dingding na hinabi mula sa mga manipis na pinilas na kawayan, isang halaman na malakas ngunit magaan kaya angkop sa pagpapatibay ng bahay.", "en": "Amakan is a wall panel woven from thin strips of bamboo, a plant that is strong yet light, which makes it good for building house walls.", "bis": "Ang amakan usa ka bongbong nga hinabol gikan sa nipis nga pinikas nga kawayan, usa ka tanom nga lig-on apan gaan, busa angay kini sa paghimo og bongbong sa balay."}, "source": "Encyclopedia-stable consensus (plant materials/properties)", "generator": "claude-workflow", "reviewed": false},
  {"id": "arnis-sticks-pair-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "arnis rattan sticks motion force national sport", "grades": [5, 6, 7], "terms": ["arnis", "eskrima", "kali", "yantok", "rattan stick", "sungkod", "patpat", "martial art", "pambansang isport", "nasudnong dula", "iindayog", "iwasiwas", "bilis", "paspas", "puwersa", "lakas", "kusog"], "fact": {"tl": "Ang arnis ay ang pambansang isport ng Pilipinas na gumagamit ng mga patpat na yantok, at habang mas mabilis na iindayog ang patpat, mas malakas ang puwersa nito kapag tumama.", "en": "Arnis is the national sport of the Philippines that uses rattan sticks, and the faster a stick is swung, the more force it carries when it strikes.", "bis": "Ang arnis mao ang nasudnong dula sa Pilipinas nga naggamit og mga sungkod nga yantok, ug kon mas paspas iwasiwas ang sungkod, mas kusog ang puwersa niini kon motama."}, "source": "NRC PS2.A (force and motion); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "balut-vendor-basket-g6", "domain": "LIVING_THINGS", "topic": "balut duck embryo egg development", "grades": [5, 6, 7], "terms": ["balut", "itlog ng pato", "duck egg", "itlog sa pato", "embryo", "embriyo", "sisiw", "piso", "bibe", "pato", "pagbubuo ng sisiw", "tumutubo", "pagtubo", "lumalaki", "buhay"], "fact": {"tl": "Ang balut ay isang itlog ng pato na pinapainit nang ilang araw upang magsimulang mabuo ang isang sisiw sa loob, kaya nakikita ang maagang yugto ng paglaki ng embryo.", "en": "Balut is a duck egg that is warmed for several days so a duckling begins to develop inside, showing an early stage of an embryo growing.", "bis": "Ang balut usa ka itlog sa pato nga gipainit sulod sa pipila ka adlaw aron magsugod og porma ang usa ka piso sa sulod, busa makita ang sayo nga hugna sa pagtubo sa embryo."}, "source": "NRC LS1.B (growth and development); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "banca-outrigger-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "banca outrigger stability balance floating", "grades": [5, 6, 7], "terms": ["bangka", "banca", "outrigger", "katig", "baroto", "dagat", "lumulutang", "naglutaw", "balanse", "hindi tumataob", "dili matumba", "stability", "katatagan", "sakayan sa tubig"], "fact": {"tl": "Ang bangkang may katig ay hindi madaling tumaob dahil ang mga katig sa magkabilang gilid ay nagbibigay ng balanse sa bangka habang ito ay lumulutang sa tubig.", "en": "An outrigger boat (banca) does not tip over easily because the floats on its sides give it balance while it floats on the water.", "bis": "Ang bangka nga adunay katig dili dali matumba tungod kay ang mga katig sa duha ka kilid mohatag og balanse sa bangka samtang naglutaw kini sa tubig."}, "source": "AAAS Benchmarks 4F (stability/buoyancy); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "banderitas-stringing-scene-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "tension and the curve of a hanging string", "grades": [4, 5, 6], "terms": ["banderitas", "kuwerdas", "nakabitin", "nakasabit", "hanging string", "tension", "gravity", "bitay", "kurba", "curve", "string", "festival flags", "pisi", "bira"], "fact": {"tl": "Kapag isinasabit ang banderitas, hinihila ng gravity ang gitna pababa kaya ang pisi ay nag-aanyong U-kurba, at mas mahigpit ang hila kung mas binabanat ito.", "en": "When banderitas are strung up, gravity pulls the middle down so the string sags into a U-shaped curve, and the tension is greater the tighter you pull it.", "bis": "Kon ibitay ang banderitas, ang gravity nagbira sa tunga paubos maong ang pisi nahimong U nga kurba, ug mas kusog ang bira kon mas hugton kini."}, "source": "encyclopedia-stable consensus; NRC PS2.A (forces)", "generator": "claude-workflow", "reviewed": false},
  {"id": "bandurria-instrument-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "vibrating strings make sound", "grades": [4, 5, 6, 7], "terms": ["bandurria", "kuwerdas", "kwerdas", "vibrate", "nanginginig", "nag-uuyog", "tunog", "tingog", "sound", "vibration", "pitch", "tono", "pluck", "kinudlit", "rondalla", "instrumento", "string instrument"], "fact": {"tl": "Ang bandurria ay isang Pilipinong instrumentong may maraming kuwerdas na pinipitik upang manginig at gumawa ng tunog; mas maikli o mas higpit na kuwerdas ay mas mataas ang tono.", "en": "The bandurria is a Philippine string instrument whose many strings are plucked so they vibrate and make sound; shorter or tighter strings give a higher pitch.", "bis": "Ang bandurria usa ka Pilipinhong instrumento nga daghag kuwerdas nga gikudlit aron mouyog ug mohimog tingog; mas mubo o mas hugot nga kuwerdas mas taas ang tono."}, "source": "encyclopedia-stable consensus; NRC PS4.A (sound/waves)", "generator": "claude-workflow", "reviewed": false},
  {"id": "barong-tagalog-garment-g5", "domain": "LIVING_THINGS", "topic": "natural plant fibers in cloth", "grades": [4, 5, 6], "terms": ["barong tagalog", "barong", "piña", "pinya", "jusi", "hibla", "tela", "panapton", "fiber", "lanot", "pineapple fiber", "dahon", "dahon ng pinya", "leaves", "woven", "hinabi", "gihabol", "plant fiber"], "fact": {"tl": "Ang tradisyonal na Barong Tagalog ay madalas na hinahabi mula sa hibla ng dahon ng pinya (piña), isang likas na halamang hibla na manipis ngunit matibay.", "en": "The traditional Barong Tagalog is often woven from piña, fibers taken from pineapple leaves, a natural plant fiber that is thin yet strong.", "bis": "Ang tradisyonal nga Barong Tagalog kasagarang gihabol gikan sa piña, mga lanot nga gikan sa dahon sa pinya, usa ka natural nga lanot sa tanom nga nipis apan lig-on."}, "source": "encyclopedia-stable consensus; DepEd matter/materials", "generator": "claude-workflow", "reviewed": false},
  {"id": "baro-saya-dress-g5", "domain": "MATTER", "topic": "cloth from natural fibers", "grades": [4, 5, 6], "terms": ["baro't saya", "baro saya", "tela", "panapton", "hibla", "lanot", "fiber", "cotton", "bulak", "gapas", "abaca", "piña", "fabric", "tinahi", "gitahi", "sewn", "cloth", "natural fiber", "sinulid", "hilo"], "fact": {"tl": "Ang baro't saya ay damit na gawa sa tela na hinabi mula sa mga hibla gaya ng bulak o piña, na pinagsalit-salit na sinulid bago tahiin.", "en": "The baro't saya is a dress made of cloth woven from fibers such as cotton or piña, threads interlaced together before being sewn.", "bis": "Ang baro't saya usa ka sapot nga hinimo sa panapton nga gihabol gikan sa mga lanot sama sa gapas o piña, mga hilo nga gisalapid una tahion."}, "source": "encyclopedia-stable consensus; DepEd matter/materials", "generator": "claude-workflow", "reviewed": false},
  {"id": "barrio-fiesta-arch-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "arch shape and load", "grades": [5, 6, 7], "terms": ["arko", "arch", "fiesta arch", "balay", "bigat", "kabug-aton", "load", "weight", "force", "puwersa", "kurba", "curve", "support", "suporta", "bamboo arch", "kawayan", "strong shape"], "fact": {"tl": "Ang hugis-arko ng entrada sa pista ay malakas dahil ipinamamahagi nito ang bigat sa magkabilang gilid pababa, kaya hindi ito basta gumuho.", "en": "The arch shape of a fiesta entrance is strong because it spreads the weight down along both curved sides, so it does not easily collapse.", "bis": "Ang porma nga arko sa entrada sa pista kusgan kay ginapang-apod-apod niini ang gibug-aton paubos sa duha ka kilid, maong dili kini dali matumba."}, "source": "encyclopedia-stable consensus; NRC PS2.A (forces/structures)", "generator": "claude-workflow", "reviewed": false},
  {"id": "basi-revolt-mural-folk-g7", "domain": "LIVING_THINGS", "topic": "fermentation by yeast", "grades": [6, 7, 8], "terms": ["basi", "tubo", "sugarcane", "fermentation", "fermentasyon", "lebadura", "yeast", "asukal", "sugar", "alcohol", "alkohol", "Ilocos", "microbe", "mikrobyo", "sugarcane wine", "katas ng tubo", "duga sa tubo"], "fact": {"tl": "Ang basi ng Ilocos ay alak na gawa mula sa katas ng tubo na nilalamnan ng lebadura, na kumakain ng asukal at gumagawa ng alkohol—isang prosesong tinatawag na fermentation.", "en": "Ilocos basi is a wine made from sugarcane juice fermented by yeast, tiny microbes that eat the sugar and produce alcohol.", "bis": "Ang basi sa Ilocos usa ka bino nga gikan sa duga sa tubo nga gibutangan ug lebadura, gagmayng mikrobyo nga mokaon sa asukal ug mohimog alkohol—gitawag kini nga fermentation."}, "source": "encyclopedia-stable consensus; NRC LS1.C (microbes/fermentation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "basketball-and-ring-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "projectile motion and gravity", "grades": [4, 5, 6, 7], "terms": ["basketball", "bola", "ring", "shoot", "itira", "ibato", "gravity", "arko", "curve", "projectile", "tumalbog", "bounce", "force", "puwersa", "parabola", "lumilipad", "naglupad"], "fact": {"tl": "Kapag itinira ang basketball, lumilipad ito sa arkong-kurba dahil hinihila ito pababa ng gravity habang patuloy itong gumagalaw pasulong.", "en": "When a basketball is shot, it travels in a curved arc because gravity pulls it downward while it keeps moving forward.", "bis": "Kon itira ang basketball, naglupad kini sa kurbang arko kay ginabira kini paubos sa gravity samtang nagpadayon kini paatubang."}, "source": "encyclopedia-stable consensus; NRC PS2.A (forces/motion)", "generator": "claude-workflow", "reviewed": false},
  {"id": "bayong-market-scene-g5", "domain": "LIVING_THINGS", "topic": "woven bag from plant leaves", "grades": [4, 5, 6], "terms": ["bayong", "buri", "pandan", "hinabi", "gihabol", "woven", "dahon", "dahon ng palma", "leaves", "bag", "supot", "sudlanan", "basket", "buslo", "natural material", "tibay", "lig-on", "tanom"], "fact": {"tl": "Ang bayong ay matibay na supot na hinahabi mula sa pinatuyong dahon ng buri o pandan, mga halaman na tumutubo sa Pilipinas.", "en": "The bayong is a sturdy bag woven from the dried leaves of buri or pandan, plants that grow in the Philippines.", "bis": "Ang bayong usa ka lig-on nga sudlanan nga gihabol gikan sa pinauga nga dahon sa buri o pandan, mga tanom nga motubo sa Pilipinas."}, "source": "encyclopedia-stable consensus; DepEd plants/materials", "generator": "claude-workflow", "reviewed": false},
  {"id": "beaker-g4", "domain": "MATTER", "topic": "measuring volume of liquids", "grades": [3, 4, 5, 6], "terms": ["beaker", "baso", "sukatan", "sukod", "measure", "volume", "dami ng likido", "likido", "tubig", "liquid", "laboratoryo", "lab", "marka", "markings", "mililitro", "milliliter", "science tool", "sudlanan"], "fact": {"tl": "Ang beaker ay sisidlang salamin na may mga marka sa gilid na ginagamit sa laboratoryo upang masukat ang dami ng likido.", "en": "A beaker is a glass container with markings on its side used in the laboratory to measure the volume of a liquid.", "bis": "Ang beaker usa ka sudlanan nga bildo nga may mga marka sa kilid nga gigamit sa laboratoryo aron masukod ang gidaghanon sa likido."}, "source": "encyclopedia-stable consensus; DepEd science process skills", "generator": "claude-workflow", "reviewed": false},
  {"id": "bibingka-puto-bumbong-stall-g5", "domain": "MATTER", "topic": "steam cooks rice cakes", "grades": [4, 5, 6], "terms": ["puto bumbong", "bibingka", "singaw", "alisngaw", "aso", "steam", "init", "kainit", "heat", "bumbong", "kawayan", "bamboo tube", "kakanin", "rice cake", "luto", "niluto", "gilung-ag", "cooked", "bigas", "bugas"], "fact": {"tl": "Ang puto bumbong ay niluluto sa pamamagitan ng mainit na singaw na umaakyat sa loob ng kawayang tubo, kung saan dinadala ng singaw ang init para magluto ng bigas.", "en": "Puto bumbong is cooked by hot steam rising through a bamboo tube, where the steam carries heat to cook the rice.", "bis": "Ang puto bumbong giluto pinaagi sa init nga alisngaw nga mosaka sa sulod sa bumbong nga kawayan, diin ang alisngaw nagdala sa init aron malutoan ang bugas."}, "source": "encyclopedia-stable consensus; NRC PS3.A (heat transfer)", "generator": "claude-workflow", "reviewed": false},
  {"id": "bibingkang-malagkit-g6", "domain": "MATTER", "topic": "why glutinous rice is sticky", "grades": [5, 6, 7], "terms": ["bibingkang malagkit", "malagkit", "pilit", "glutinous rice", "almirol", "starch", "almidon", "dikit", "sticky", "pulot", "kanin", "bugas", "rice", "luto", "niluto", "kakanin", "natural starch"], "fact": {"tl": "Malagkit ang bibingkang malagkit dahil ang pilit na bigas ay mayaman sa isang uri ng almirol na nagiging malagkit kapag niluluto sa init.", "en": "Bibingkang malagkit is sticky because glutinous rice is rich in a kind of starch that turns gummy when cooked with heat.", "bis": "Pilit ang bibingkang malagkit kay ang pilit nga bugas dato sa usa ka klase sa almidon nga mahimong dikit kon lutoon sa init."}, "source": "encyclopedia-stable consensus; NRC PS1.A (matter/properties)", "generator": "claude-workflow", "reviewed": false},
  {"id": "billiards-table-cue-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "collision transfers motion", "grades": [5, 6, 7, 8], "terms": ["billiards", "bilyar", "bola", "tira", "banggaan", "nagbangga", "collision", "cue", "gumalaw", "naglihok", "momentum", "puwersa", "force", "transfer", "naipasa", "energy", "kusog", "motion", "naghampak"], "fact": {"tl": "Sa bilyar, kapag tinamaan ng gumagalaw na bola ang nakatigil na bola, naililipat nito ang galaw kaya ang nakatigil na bola ang gagalaw.", "en": "In billiards, when a moving ball strikes a still ball, it passes its motion along so the still ball moves off.", "bis": "Sa bilyar, kon ang naglihok nga bola moigo sa hunong nga bola, gibalhin niini ang lihok maong ang hunong nga bola molihok."}, "source": "encyclopedia-stable consensus; NRC PS2.A (forces/collisions)", "generator": "claude-workflow", "reviewed": false},
  {"id": "binasuan-glass-balance-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "balance and center of gravity", "grades": [4, 5, 6, 7], "terms": ["binasuan", "baso", "sayaw", "dance", "balanse", "timbang", "balance", "gravity", "tilt", "tubig", "water", "sentro ng bigat", "center of gravity", "steady", "lihok", "mananayaw"], "fact": {"tl": "Sa sayaw na Binasuan, nananatiling hindi natatapon ang tubig sa baso dahil pinapanatili ng mananayaw na patag ang baso habang dahan-dahang gumagalaw para magkaroon ng balanse.", "en": "In the Binasuan dance, water stays in the glasses because the dancer keeps each glass level and moves smoothly to stay balanced.", "bis": "Sa sayaw nga Binasuan, ang tubig dili mayabo sa baso kay ginapatag sa mananayaw ang baso ug hinay-hinay nga molihok aron magbalanse."}, "source": "encyclopedia-stable consensus; NRC PS2.A (forces/balance)", "generator": "claude-workflow", "reviewed": false},
  {"id": "buko-pie-slice-g4", "domain": "LIVING_THINGS", "topic": "young coconut as plant food", "grades": [3, 4, 5, 6], "terms": ["buko", "young coconut", "niyog", "lubi", "coconut", "laman", "unod", "meat", "bunga", "prutas", "fruit", "puno ng niyog", "coconut tree", "buko pie", "tubig ng buko", "coconut water", "halaman", "tanom"], "fact": {"tl": "Ang buko ay batang niyog na may malambot na puting laman at matamis na tubig sa loob, at tumutubo ito sa puno ng niyog na karaniwan sa Pilipinas.", "en": "Buko is a young coconut with soft white meat and sweet water inside, and it grows on the coconut tree that is common in the Philippines.", "bis": "Ang buko usa ka batan-ong lubi nga may humok nga puti nga unod ug tam-is nga tubig sa sulod, ug motubo kini sa puno sa lubi nga kasagaran sa Pilipinas."}, "source": "encyclopedia-stable consensus; DepEd plants", "generator": "claude-workflow", "reviewed": false},
  {"id": "bulong-pari-whisper-game-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "sound travels through air", "grades": [3, 4, 5, 6], "terms": ["bulong pari", "bulong", "whisper", "tunog", "tingog", "sound", "tainga", "dalunggan", "ear", "hangin", "air", "naglakbay", "milatas", "travel", "naririnig", "nadungog", "marinig", "vibration", "laro", "dula"], "fact": {"tl": "Sa laruang Bulong Pari, naririnig ang ibinubulong dahil ang tunog ay naglalakbay sa hangin mula sa bibig patungo sa tainga.", "en": "In the game Bulong Pari, you can hear the whisper because sound travels through the air from the mouth to the ear.", "bis": "Sa dula nga Bulong Pari, madungog nimo ang gihunghong kay ang tingog molatas sa hangin gikan sa baba ngadto sa dalunggan."}, "source": "encyclopedia-stable consensus; NRC PS4.A (sound)", "generator": "claude-workflow", "reviewed": false},
  {"id": "carabao-race-festival-g4", "domain": "LIVING_THINGS", "topic": "carabao as a Philippine farm animal", "grades": [3, 4, 5, 6], "terms": ["carabao", "kalabaw", "kabaw", "water buffalo", "hayop", "mananap", "animal", "bukid", "uma", "farm", "araro", "daro", "plow", "lusak", "putik", "lapok", "mud", "gatas", "milk", "mammal", "domestic animal"], "fact": {"tl": "Ang kalabaw ay malaking hayop na ginagamit ng mga magsasaka sa Pilipinas para mag-araro ng bukid, at gusto nitong maglublob sa putik para lumamig.", "en": "The carabao is a large animal Filipino farmers use to plow fields, and it likes to wallow in mud to cool down.", "bis": "Ang kabaw usa ka dakong hayop nga gigamit sa mga mag-uuma sa Pilipinas aron mag-daro sa uma, ug ganahan kini molubog sa lapok aron mabugnaw."}, "source": "encyclopedia-stable consensus; DepEd animals", "generator": "claude-workflow", "reviewed": false},
  {"id": "carabao-kneeling-festival-g4", "domain": "LIVING_THINGS", "topic": "carabao body and behavior", "grades": [3, 4, 5, 6], "terms": ["carabao", "kalabaw", "kabaw", "water buffalo", "sungay", "horns", "hayop", "mananap", "animal", "Pulilan", "festival", "balat", "panit", "skin", "herbivore", "damo", "sagbot", "kumakain ng damo", "tanom"], "fact": {"tl": "Ang kalabaw ay may matibay na malalapad na sungay at kumakain lamang ng damo at halaman, kaya ito ay tinatawag na herbivore.", "en": "The carabao has strong wide horns and eats only grass and plants, which is why it is called a herbivore.", "bis": "Ang kabaw may lig-on ug halapad nga sungay ug mokaon lang ug sagbot ug tanom, mao nga gitawag kining herbivore."}, "source": "encyclopedia-stable consensus; NRC LS2.A (feeding relationships)", "generator": "claude-workflow", "reviewed": false},
  {"id": "chicharong-bulaklak-g5", "domain": "MATTER", "topic": "deep-frying changes food (chicharon bulaklak)", "grades": [4, 5, 6], "terms": ["chicharong bulaklak", "chicharon", "baboy", "bituka", "mesenteryo", "taba", "pinirito", "prito", "init", "deep-fry", "fried", "pork", "mesentery", "ruffle fat", "crispy", "malutong", "tinunaw", "tunaw"], "fact": {"tl": "Ang chicharong bulaklak ay gawa sa manipis na lamad (mesenteryo) na nakakabit sa bituka ng baboy, na malalim na piniprito hanggang maging malutong.", "en": "Chicharong bulaklak is made from the thin membrane (mesentery) attached to a pig's intestines, which is deep-fried until it becomes crispy.", "bis": "Ang chicharong bulaklak gihimo gikan sa nipis nga lamad (mesenteryo) nga nakakabit sa tinai sa baboy, nga giprito ug lawom hangtod mahimong kusog."}, "source": "encyclopedia consensus (chicharon bulaklak = pork mesentery / ruffle fat); DepEd G5 changes in materials when heated", "generator": "claude-workflow", "reviewed": false},
  {"id": "crayons-wax-melting-g4", "domain": "MATTER", "topic": "crayons are wax that melts with heat", "grades": [3, 4, 5], "terms": ["crayon", "krayola", "kandila", "kolor", "wax", "kandilang lana", "init", "tunaw", "matunaw", "natutunaw", "natunaw", "melt", "color", "lapis na kulay", "mogahi"], "fact": {"tl": "Ang krayola ay gawa sa kandilang lana (wax) at pigment, kaya natutunaw ito kapag nainitan at tumitigas muli kapag lumamig.", "en": "Crayons are made of wax and pigment, so they melt when heated and harden again when they cool down.", "bis": "Ang krayola hinimo gikan sa wax (kandila) ug pigment, mao nga matunaw kini kon mainitan ug mogahi balik kon mabugnaw."}, "source": "encyclopedia-stable consensus; DepEd G4 solids change with heat", "generator": "claude-workflow", "reviewed": false},
  {"id": "embutido-steaming-cooks-meat-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "steaming uses heat from water vapor to cook food", "grades": [4, 5, 6], "terms": ["embutido", "embotido", "giniling", "karne", "baboy", "pinasingawan", "singaw", "steam", "steaming", "init", "lutuin", "naluto", "gisteam", "alisngaw", "meatloaf", "ground pork", "cook", "mogahi"], "fact": {"tl": "Ang embutido ay isang Pilipinong meatloaf na gawa sa giniling na baboy na niluluto sa singaw ng kumukulong tubig hanggang tumigas at maluto.", "en": "Embutido is a Filipino meatloaf made of ground pork that is cooked by the steam of boiling water until it firms up and is fully cooked.", "bis": "Ang embutido usa ka Pilipinhong meatloaf nga hinimo sa giniling nga baboy nga giluto pinaagi sa alisngaw sa nagbukal nga tubig hangtod mogahi ug maluto."}, "source": "encyclopedia-stable consensus; DepEd G5 heat transfer in cooking", "generator": "claude-workflow", "reviewed": false},
  {"id": "espasol-rice-flour-kakanin-g5", "domain": "MATTER", "topic": "rice flour kakanin (espasol)", "grades": [4, 5, 6], "terms": ["espasol", "kakanin", "bigas", "galapong", "gata", "niyog", "harina ng bigas", "rice flour", "coconut milk", "glutinous rice", "malagkit", "pilit", "sinangag", "toasted", "binalot", "sweet", "matamis"], "fact": {"tl": "Ang espasol ay isang kakanin na gawa sa harina ng malagkit na bigas at gata, na iginugulong sa sinangag na harina ng bigas para hindi dumikit.", "en": "Espasol is a Filipino rice cake made from glutinous rice flour and coconut milk, rolled in toasted rice flour so it does not stick.", "bis": "Ang espasol usa ka kakanin nga hinimo gikan sa harina sa pilit nga bugas ug gata, nga giligid sa sinanlag nga harina sa bugas aron dili motapot."}, "source": "encyclopedia consensus (toasted glutinous rice flour kakanin from Laguna)", "generator": "claude-workflow", "reviewed": false},
  {"id": "siling-haba-chili-dynamite-g5", "domain": "LIVING_THINGS", "topic": "chili pepper plant (siling haba)", "grades": [4, 5, 6], "terms": ["sili", "siling haba", "siling pangsigang", "dynamite", "anghang", "maanghang", "kapsicum", "halaman", "bunga", "prutas", "chili", "pepper", "spicy", "hot", "capsaicin", "tanim", "namumunga"], "fact": {"tl": "Ang siling haba na ginagawang 'dynamite' ay bunga ng halamang sili, at ang anghang nito ay galing sa sangkap na capsaicin sa loob ng buto at balat.", "en": "The long green chili used to make 'dynamite' is the fruit of the chili plant, and its spicy heat comes from a substance called capsaicin found in its seeds and lining.", "bis": "Ang taas nga sili nga himoong 'dynamite' mao ang bunga sa tanom nga sili, ug ang kahalang niini gikan sa sangkap nga capsaicin nga anaa sa liso ug sulod niini."}, "source": "encyclopedia-stable consensus; DepEd plants and their parts", "generator": "claude-workflow", "reviewed": false},
  {"id": "pig-livestock-feeding-g3", "domain": "LIVING_THINGS", "topic": "pigs are farm animals that need food and care", "grades": [3, 4, 5], "terms": ["baboy", "alagang hayop", "alaga", "kumain", "pagkain", "darak", "kaning-baboy", "labangan", "pig", "hog", "swine", "livestock", "feed", "trough", "farm animal", "babuy", "gipakaon", "pagkaon", "tahop"], "fact": {"tl": "Ang baboy ay isang alagang hayop na inaalagaan sa sakahan para sa karne, at kailangan itong pakainin araw-araw ng pagkaing tulad ng darak at tira-tirang gulay.", "en": "The pig is a farm animal raised for its meat, and it must be fed every day with food such as rice bran and leftover vegetables.", "bis": "Ang baboy usa ka mananap nga giatiman sa uma alang sa karne, ug kinahanglan kini pakan-on adlaw-adlaw ug pagkaon sama sa tahop ug salin nga utan."}, "source": "encyclopedia-stable consensus; DepEd animals and their needs", "generator": "claude-workflow", "reviewed": false},
  {"id": "river-water-source-fetching-g4", "domain": "EARTH_SPACE", "topic": "rivers as a freshwater source", "grades": [3, 4, 5], "terms": ["ilog", "tubig", "tubig-tabang", "balde", "igib", "umigib", "umagos", "agos", "sapa", "river", "stream", "fresh water", "fetch water", "water source", "suba", "magkalos", "nagkalos"], "fact": {"tl": "Ang ilog ay isang likas na pinagkukunan ng tubig-tabang na umaagos mula sa mga bundok patungo sa dagat, at marami pa ring pamilya ang umiigib dito.", "en": "A river is a natural source of fresh water that flows from the mountains toward the sea, and many families still fetch water from it.", "bis": "Ang suba usa ka natural nga tinubdan sa tubig-tab-ang nga nagdagayday gikan sa kabukiran paingon sa dagat, ug daghan pa nga pamilya ang nagkalos niini."}, "source": "encyclopedia-stable consensus; DepEd water sources and the water cycle", "generator": "claude-workflow", "reviewed": false},
  {"id": "active-traditional-games-exercise-g4", "domain": "LIVING_THINGS", "topic": "physical activity keeps the body healthy", "grades": [3, 4, 5], "terms": ["laro", "Pinoy laro", "tumbang preso", "patintero", "luksong tinik", "ehersisyo", "katawan", "malusog", "puso", "kalamnan", "dula", "lihok", "ejersisyo", "lawas", "himsog", "kasingkasing", "kaunuran", "traditional games", "active play", "exercise", "muscles", "heart", "healthy body"], "fact": {"tl": "Ang mga aktibong larong Pinoy tulad ng patintero at tumbang preso ay ehersisyo na nagpapalakas ng kalamnan at puso.", "en": "Active Filipino games like patintero and tumbang preso are exercise that strengthens the muscles and heart.", "bis": "Ang aktibo nga Pinoy nga mga dula sama sa patintero ug tumbang preso mao ang ehersisyo nga nagpalig-on sa kaunuran ug kasingkasing."}, "source": "DepEd MAPEH/Science health strand; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "frying-fishball-heat-g5", "domain": "MATTER", "topic": "frying cooks food using heat from hot oil", "grades": [4, 5, 6], "terms": ["pagprito", "prito", "fishball", "isaw", "mainit na mantika", "init", "lutuin", "lumalapot", "namumula", "nagbabago", "iprito", "pagpaprito", "mantika", "lana", "kainit", "lutoon", "init sa lana", "frying", "hot oil", "heat", "cooking", "fish ball"], "fact": {"tl": "Sa pagprito, dinadala ng mainit na mantika ang init sa fishball kaya ito naluluto, namumula, at nagbabago ang lasa.", "en": "In frying, hot oil carries heat into the fish ball so it cooks, turns brown, and changes in taste.", "bis": "Sa pagprito, ang init nga lana magdala sa kainit ngadto sa fishball mao nga maluto kini, mamula, ug mausab ang lami."}, "source": "NRC PS3.B energy transfer; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fish-protein-food-g4", "domain": "LIVING_THINGS", "topic": "fish is a protein-rich food from the sea", "grades": [3, 4, 5], "terms": ["isda", "palengke", "pamilihan", "bangus", "tilapia", "galunggong", "protina", "pagkain", "dagat", "mangingisda", "isdaan", "sustansya", "isda sa dagat", "isdang dagat", "merkado", "tindahan", "kan-onon", "mananagat", "fish", "market", "protein", "food", "sea", "nutrient"], "fact": {"tl": "Ang isda na ibinebenta sa palengke ay pagkaing mayaman sa protina na nakukuha sa dagat o palaisdaan.", "en": "The fish sold at the market is a protein-rich food caught from the sea or fishponds.", "bis": "Ang isda nga ginabaligya sa merkado usa ka pagkaon nga dato sa protina nga makuha gikan sa dagat o sa isdaan."}, "source": "DepEd nutrition strand; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tinola-cooking-boiling-g4", "domain": "MATTER", "topic": "boiling in soup transfers heat through hot water", "grades": [4, 5, 6], "terms": ["tinola", "sabaw", "isda", "nilaga", "kumukulo", "tubig", "init", "luto", "luya", "sili leaves", "kumulo", "pakuluan", "init nga tubig", "lutoon", "pagpabukal", "tinula", "tubig nga init", "luy-a", "soup", "boiling", "hot water", "heat", "cooking", "fish soup"], "fact": {"tl": "Sa tinolang isda, ang kumukulong tubig ang nagdadala ng init para maluto ang isda at gulay sa loob ng sabaw.", "en": "In fish tinola, the boiling water carries heat to cook the fish and vegetables inside the soup.", "bis": "Sa tinolang isda, ang nagbukal nga tubig maoy nagdala sa kainit aron maluto ang isda ug utanon sulod sa sabaw."}, "source": "NRC PS3.B energy transfer; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "flowers-plant-reproduction-g5", "domain": "LIVING_THINGS", "topic": "flowers are the reproductive part of a plant", "grades": [4, 5, 6], "terms": ["bulaklak", "halaman", "buko", "pollen", "polen", "binhi", "bunga", "anther", "stigma", "pamumulaklak", "namumukadkad", "bulak", "tanom", "liso", "buwa", "namulak", "flower", "plant", "reproduction", "seed", "fruit", "bloom"], "fact": {"tl": "Ang bulaklak ang bahagi ng halaman na gumagawa ng pollen at binhi para magkaroon ng bagong halaman.", "en": "A flower is the part of a plant that makes pollen and seeds so new plants can grow.", "bis": "Ang bulak mao ang bahin sa tanom nga naghimo og pollen ug liso aron makatubo ang bag-ong mga tanom."}, "source": "AAAS Benchmarks 5C; DepEd G5 life science", "generator": "claude-workflow", "reviewed": false},
  {"id": "funnel-tool-pouring-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "a funnel guides liquid into a narrow opening", "grades": [3, 4, 5], "terms": ["funnel", "imbudo", "embudo", "likido", "tubig", "ibuhos", "makitid na butas", "bote", "gabay", "salaan", "ibubo", "gamay nga lungag", "botelya", "panalok", "liquid", "pour", "narrow opening", "bottle", "tool"], "fact": {"tl": "Ang funnel o imbudo ay kasangkapang malapad sa itaas at makitid sa ilalim para madaling maibuhos ang likido sa maliit na butas ng bote.", "en": "A funnel is a tool that is wide at the top and narrow at the bottom so liquid pours easily into a small bottle opening.", "bis": "Ang funnel o imbudo usa ka galamiton nga lapad sa ibabaw ug gamay sa ubos aron sayon nga ikabubo ang likido ngadto sa gamay nga lungag sa botelya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gloves-safety-protection-g4", "domain": "LIVING_THINGS", "topic": "gloves protect the hands during experiments", "grades": [3, 4, 5], "terms": ["guwantes", "gloves", "kamay", "proteksyon", "ligtas", "kemikal", "init", "eksperimento", "mikrobyo", "kaligtasan", "guantes", "kamot", "panalipod", "luwas", "kahilwasan", "hands", "protection", "safety", "chemicals", "experiment", "germs"], "fact": {"tl": "Ang guwantes ay isinusuot sa eksperimento para protektahan ang kamay sa init, kemikal, at mikrobyo.", "en": "Gloves are worn during experiments to protect the hands from heat, chemicals, and germs.", "bis": "Ang guantes ginasul-ob sa eksperimento aron panalipdan ang kamot gikan sa kainit, kemikal, ug mikrobyo."}, "source": "DepEd science safety guidelines; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "goggles-eye-protection-g4", "domain": "LIVING_THINGS", "topic": "safety goggles protect the eyes", "grades": [3, 4, 5], "terms": ["goggles", "salaming pang-mata", "mata", "proteksyon", "ligtas", "kemikal", "tilamsik", "eksperimento", "kaligtasan", "antipara", "salamin sa mata", "panalipod", "luwas", "tilapsik", "eyes", "protection", "safety", "splash", "chemicals", "experiment"], "fact": {"tl": "Ang goggles ay salaming isinusuot sa mata para protektahan ito sa tilamsik ng kemikal o maliliit na bagay sa eksperimento.", "en": "Goggles are protective glasses worn over the eyes to shield them from chemical splashes or small flying bits during experiments.", "bis": "Ang goggles maoy salaming gisul-ob sa mata aron panalipdan kini gikan sa tilapsik sa kemikal o gagmay nga butang sa eksperimento."}, "source": "DepEd science safety guidelines; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "grilling-bbq-heat-g5", "domain": "MATTER", "topic": "grilling cooks food with heat from burning charcoal", "grades": [4, 5, 6], "terms": ["ihaw", "inihaw", "barbecue", "BBQ", "uling", "apoy", "init", "luto", "namumula", "usok", "ihawan", "sugba", "sinugba", "kalayo", "aboabo", "grill", "charcoal", "fire", "heat", "cooking", "smoke"], "fact": {"tl": "Sa pag-ihaw ng barbecue, ang init mula sa nagbabagang uling ang nagluluto sa karne at nagbibigay ng usok na nagpapalasa nito.", "en": "When grilling barbecue, heat from the glowing charcoal cooks the meat and gives off smoke that flavors it.", "bis": "Sa pagsugba og barbecue, ang init gikan sa nagbaga nga uling maoy nagluto sa karne ug naghatag og aso nga naglami niini."}, "source": "NRC PS3.B energy transfer; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bamboo-bridge-material-g5", "domain": "MATTER", "topic": "bamboo is a strong light plant used for building", "grades": [4, 5, 6], "terms": ["kawayan", "tulay", "bamboo", "halaman", "matibay", "magaan", "damo", "tubo", "gusali", "bahay kubo", "taytayan", "lig-on", "gaan", "balay", "sagbot", "bridge", "strong", "light", "grass", "building", "plant"], "fact": {"tl": "Ang kawayan ay isang malaking damo na matibay pero magaan, kaya ginagamit itong materyales sa paggawa ng tulay at bahay.", "en": "Bamboo is a giant grass that is strong yet light, so it is used as a material for building bridges and houses.", "bis": "Ang kawayan usa ka dako nga sagbot nga lig-on apan gaan, mao nga gigamit kini nga materyales sa paghimo og taytayan ug balay."}, "source": "encyclopedia-stable consensus; DepEd materials science", "generator": "claude-workflow", "reviewed": false},
  {"id": "ube-purple-yam-root-g4", "domain": "LIVING_THINGS", "topic": "ube is a purple root crop grown underground", "grades": [3, 4, 5], "terms": ["ube", "lila", "ugat", "halaman", "kamote", "tuber", "lupa", "matamis", "kakanin", "tinubo", "ubi", "kolor lila", "gamot", "tanom", "ilalom sa yuta", "tam-is", "purple yam", "root crop", "underground", "plant", "sweet"], "fact": {"tl": "Ang ube ay isang lilang halamang-ugat na tumutubo sa ilalim ng lupa at ginagawang matamis na kakanin tulad ng halaya.", "en": "Ube is a purple root crop that grows underground and is made into sweet treats like halaya.", "bis": "Ang ubi usa ka lila nga halamang-gamot nga motubo ilalom sa yuta ug ginahimong tam-is nga kalan-on sama sa halaya."}, "source": "encyclopedia-stable consensus; DepEd life science", "generator": "claude-workflow", "reviewed": false},
  {"id": "halo-halo-melting-ice-g4", "domain": "MATTER", "topic": "shaved ice melts from solid to liquid in halo-halo", "grades": [3, 4, 5], "terms": ["halo-halo", "yelo", "natutunaw", "solid", "likido", "init", "tunaw", "pinagsama", "matamis", "magkahalo", "natunaw", "gahi", "sagol", "shaved ice", "melt", "liquid", "heat", "mixture"], "fact": {"tl": "Sa halo-halo, ang yelong solid ay natutunaw at nagiging likido dahil sa init, kaya lahat ng sangkap ay naghahalo.", "en": "In halo-halo, the solid shaved ice melts into liquid because of heat, so all the ingredients mix together.", "bis": "Sa halo-halo, ang gahi nga yelo matunaw nga mahimong likido tungod sa kainit, mao nga magkasagol ang tanang sangkap."}, "source": "NRC PS1.A states of matter; DepEd G4 matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "mango-tree-harvest-g4", "domain": "LIVING_THINGS", "topic": "mango grows on tall trees and is harvested with a pole", "grades": [3, 4, 5], "terms": ["mangga", "puno", "ani", "bunga", "prutas", "matamis", "halaman", "sungkit", "manggahan", "tag-init", "kahoy", "tam-is", "tanom", "mango", "tree", "harvest", "fruit", "sweet", "pole", "plant"], "fact": {"tl": "Ang mangga ay tumutubo sa matatangkad na puno, at inaani ang hinog na bunga gamit ang mahabang sungkit.", "en": "Mango grows on tall trees, and the ripe fruit is harvested using a long pole.", "bis": "Ang mangga motubo sa tag-as nga kahoy, ug ang hinog nga bunga gianihan pinaagi sa taas nga sungkit."}, "source": "encyclopedia-stable consensus; DepEd life science", "generator": "claude-workflow", "reviewed": false},
  {"id": "holen-ring-game-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "marbles collision and motion", "grades": [3, 4, 5], "terms": ["holen", "jolen", "bola-bola", "tama", "tinama", "umalis", "gumulong", "lakas", "buwa", "kanaway", "marble", "marbles", "collision", "flick", "push", "transfer of motion", "naglihok", "gibanggaan"], "fact": {"tl": "Sa laro ng holen, kapag ang isang holen ay tumama sa iba, naililipat nito ang lakas ng galaw kaya ang natamaan ay gumagalaw palayo.", "en": "In the game of marbles, when one marble hits another it transfers its motion, so the marble that gets struck rolls away.", "bis": "Sa dula sa holen, kung ang usa ka holen mobangga sa lain, mabalhin niini ang kusog sa paglihok mao nga ang nabanggaan moligid palayo."}, "source": "encyclopedia-stable consensus; NRC PS2.A (forces and motion)", "generator": "claude-workflow", "reviewed": false},
  {"id": "hopia-mongo-mung-bean-g5", "domain": "LIVING_THINGS", "topic": "mung bean legume seed", "grades": [4, 5, 6], "terms": ["hopia", "monggo", "mongo", "munggo", "binhi", "buto", "gulay", "halaman", "leguminosa", "balatong", "mung bean", "mung", "legume", "bean", "seed", "protein", "tanim", "gitanom", "liso"], "fact": {"tl": "Ang palaman ng hopiang monggo ay gawa sa monggo, isang buto ng halamang leguminosa na mayaman sa protina at madalas itaniman ng mga magsasaka.", "en": "The filling of mung-bean hopia is made from mung beans, the protein-rich seeds of a legume plant that farmers often grow.", "bis": "Ang sulod sa hopiang monggo gama sa balatong, usa ka liso sa tanom nga leguminosa nga daghag protina ug kanunayng gitanom sa mga mag-uuma."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks 5C (flow of matter in living systems)", "generator": "claude-workflow", "reviewed": false},
  {"id": "ice-drop-popsicle-g3", "domain": "MATTER", "topic": "freezing liquid to solid", "grades": [3, 4, 5], "terms": ["ice drop", "ice candy", "yelo", "popsicle", "tubig", "lamig", "nagyelo", "tumigas", "nilagay sa freezer", "estado", "solido", "likido", "freeze", "freezing", "frozen", "solid", "liquid", "cold", "tubig nga nagyelo", "nagbugnaw", "namugnaw", "gahi"], "fact": {"tl": "Nagiging matigas na ice drop ang matamis na tubig kapag inilagay sa sobrang lamig, dahil sa malamig na temperatura ang likido ay nagyeyelo at nagiging solido.", "en": "Sweet liquid turns into a hard ice drop when placed in extreme cold, because at freezing temperatures a liquid changes into a solid.", "bis": "Ang tam-is nga tubig mahimong gahi nga ice drop kung ibutang sa sobrang bugnaw, kay sa bugnaw nga temperatura ang likido moyelo ug mahimong solido."}, "source": "NRC PS1.A (states of matter); DepEd G4 Q1 (changes of state)", "generator": "claude-workflow", "reviewed": false},
  {"id": "karera-ng-kalabaw-carabao-g4", "domain": "LIVING_THINGS", "topic": "carabao water buffalo", "grades": [3, 4, 5], "terms": ["kalabaw", "karera ng kalabaw", "carabao", "water buffalo", "hayop", "mammal", "mamalya", "bukid", "pang-araro", "araro", "lusak", "putik", "carabao race", "kabaw", "hayop sa uma", "gisakay", "naghatod", "sungay", "molunang"], "fact": {"tl": "Ang kalabaw ay isang malaking hayop na nagpapasusong (mammal) na ginagamit ng mga magsasaka sa pag-araro ng palayan at mahilig lumublob sa putik para magpalamig.", "en": "The carabao is a large mammal that farmers use to plow rice fields, and it loves wallowing in mud to cool itself down.", "bis": "Ang kabaw usa ka dako nga hayop nga mammal nga gigamit sa mga mag-uuma sa pagdaro sa humayan, ug ganahan kini molunang sa lapok aron mabugnawan."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks 5A (diversity of life)", "generator": "claude-workflow", "reviewed": false},
  {"id": "karilyo-shadow-puppet-light-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "light and shadows", "grades": [3, 4, 5], "terms": ["karilyo", "shadow puppet", "anino", "ilaw", "liwanag", "shadow", "light", "block", "harang", "naharang", "naliliwanagan", "papel", "tabing", "anino sa dingding", "landong", "kahayag", "gibabagan", "naghatag ug landong", "opaque"], "fact": {"tl": "Sa karilyo o shadow puppet, lumilitaw ang anino dahil hinaharang ng papel na pigura ang ilaw, kaya may madilim na hugis na lumalabas sa tabing.", "en": "In a shadow-puppet show, a shadow appears because the paper figure blocks the light, leaving a dark shape on the screen.", "bis": "Sa karilyo o shadow puppet, mogawas ang landong tungod kay gibabagan sa papel nga pigura ang kahayag, mao nga adunay itom nga porma nga makita sa tabil."}, "source": "NRC PS4.B (electromagnetic radiation, light); DepEd G5 Q3 (light and shadows)", "generator": "claude-workflow", "reviewed": false},
  {"id": "kubing-jaw-harp-sound-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "vibration and sound", "grades": [5, 6, 7], "terms": ["kubing", "jaw harp", "instrumento", "tunog", "vibrasyon", "nanginginig", "yumayanig", "bibig", "kawayan", "sound", "vibration", "vibrate", "bamboo", "pitch", "tono", "tingog", "nagkurog", "huni", "naglihok-lihok"], "fact": {"tl": "Ang kubing ay isang instrumentong gawa sa kawayan na pinapatunog sa pamamagitan ng pagpa-vibrate ng dila nito malapit sa bibig, at ang nanginginig na bahaging ito ang gumagawa ng tunog.", "en": "The kubing is a bamboo jaw-harp played by making its thin tongue vibrate near the mouth, and that vibrating part is what produces the sound.", "bis": "Ang kubing usa ka instrumento nga gama sa kawayan nga patingogon pinaagi sa pagpakurog sa nipis nga dila niini duol sa baba, ug kining nagkurog nga bahin maoy naghimo sa tingog."}, "source": "NRC PS4.A (wave properties, sound from vibration); DepEd G6 Q3 (sound)", "generator": "claude-workflow", "reviewed": false},
  {"id": "kulintang-gongs-pitch-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "sound pitch and size", "grades": [5, 6, 7], "terms": ["kulintang", "gong", "agong", "instrumento", "tunog", "tono", "laki", "malaki", "maliit", "vibrasyon", "tugtog", "metal", "bronze", "sound", "pitch", "high", "low", "gongs", "tingog", "tono nga taas", "gidak-on", "tinugtog"], "fact": {"tl": "Sa kulintang, ang hanay ng mga gong na metal ay gumagawa ng iba't ibang tono dahil ang mas maliliit na gong ay mas mabilis mag-vibrate at gumagawa ng mas matataas na tunog.", "en": "In the kulintang, the row of metal gongs makes different pitches because the smaller gongs vibrate faster and produce higher sounds.", "bis": "Sa kulintang, ang han-ay sa mga metal nga gong naghimo ug lainlaing tono kay ang mas gagmay nga gong mas paspas mokurog ug naghimo ug mas taas nga tingog."}, "source": "NRC PS4.A (wave properties, frequency and pitch); DepEd G6 Q3 (sound)", "generator": "claude-workflow", "reviewed": false},
  {"id": "karambola-billiard-collision-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "elastic collision and momentum", "grades": [5, 6, 7], "terms": ["karambola", "billiard", "bilyar", "bola", "tama", "tinama", "gumulong", "naglipat", "lakas", "tudling", "tako", "collision", "momentum", "transfer", "ball", "cue", "energy", "gibanggaan", "kusog sa paglihok", "naglihok", "natulod"], "fact": {"tl": "Sa bilyar o karambola, kapag tinamaan ng gumugulong na bola ang ibang bola, naililipat nito ang lakas ng galaw kaya ang natamaang bola ang gumagalaw naman.", "en": "In billiards or carom, when a rolling ball strikes another ball it passes on its motion, so the struck ball moves off instead.", "bis": "Sa bilyar o karambola, kung ang naglihok nga bola mobangga sa laing bola, mabalhin niini ang kusog sa paglihok mao nga ang nabanggaan nga bola maoy molihok."}, "source": "NRC PS2.A (forces, transfer of motion); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kornik-corn-snack-g4", "domain": "LIVING_THINGS", "topic": "corn cereal grain", "grades": [3, 4, 5], "terms": ["kornik", "cornick", "mais", "corn", "butil", "buto", "tanim", "halaman", "binusa", "pinirito", "grain", "kernel", "maize", "cereal", "snack", "liso", "tinanom", "ginbusa", "lugas", "mais nga butil"], "fact": {"tl": "Ang kornik ay gawa sa butil ng mais, isang halamang pananim na ang matitigas na buto nito ay pinipirito hanggang maging malutong.", "en": "Cornick is made from kernels of corn, a crop plant whose hard seeds are fried until they become crunchy.", "bis": "Ang kornik gama sa lugas sa mais, usa ka tanom nga ang gahi nga mga liso niini gipirito hangtod mahimong tagumkom."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks 5A (plants and food)", "generator": "claude-workflow", "reviewed": false},
  {"id": "kornika-peanuts-legume-g5", "domain": "LIVING_THINGS", "topic": "peanut legume seed", "grades": [4, 5, 6], "terms": ["kornika", "mani", "peanut", "groundnut", "buto", "binhi", "leguminosa", "halaman", "lupa", "ugat", "nuts", "legume", "seed", "protein", "mani nga liso", "ilalim ng lupa", "tinanom", "tanom", "ilawom sa yuta"], "fact": {"tl": "Ang mani sa kornika ay buto ng halamang leguminosa na namumunga sa ilalim ng lupa at mayaman sa protina at langis.", "en": "The peanut in kornika is the seed of a legume plant that forms its pods underground and is rich in protein and oil.", "bis": "Ang mani sa kornika maoy liso sa tanom nga leguminosa nga mamunga ilawom sa yuta ug daghag protina ug lana."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks 5C (matter in living systems)", "generator": "claude-workflow", "reviewed": false},
  {"id": "higantes-papier-mache-g4", "domain": "MATTER", "topic": "papier-mache material drying", "grades": [3, 4, 5], "terms": ["higantes", "giant", "papier-mache", "papel", "pandikit", "tinuyo", "tumigas", "natuyo", "magaan", "paper", "paste", "dry", "harden", "lightweight", "mache", "basa", "namala", "namad-an", "gaan", "gahi"], "fact": {"tl": "Ang malalaking higantes ng Angono ay gawa sa papier-mache, na nabubuo kapag ang basang papel na may pandikit ay tinutuyo hanggang tumigas pero nananatiling magaan.", "en": "The giant higantes of Angono are made of papier-mache, formed when wet glued paper is dried until it hardens yet stays lightweight.", "bis": "Ang dagkong higantes sa Angono gama sa papier-mache, nga maporma kung ang basa nga papel nga adunay pandikit pamad-an hangtod mogahi apan magpabiling gaan."}, "source": "encyclopedia-stable consensus; NRC PS1.A (properties of materials)", "generator": "claude-workflow", "reviewed": false},
  {"id": "iuk-iuk-blood-coagulation-g7", "domain": "MATTER", "topic": "protein coagulation by heat", "grades": [6, 7, 8], "terms": ["iuk-iuk", "dugo", "betamax", "blood", "coagulate", "namuo", "tumigas", "init", "protina", "likido", "solido", "coagulation", "protein", "heat", "solidify", "grilled", "namua", "nagahi", "gisugba", "init nga", "naluto"], "fact": {"tl": "Ang inihaw na dugo gaya ng iuk-iuk ay tumitigas mula sa likido dahil ang init ay nagpapamuo (coagulate) sa mga protina sa dugo.", "en": "Grilled blood like iuk-iuk turns from liquid to solid because heat makes the proteins in the blood coagulate.", "bis": "Ang sinugba nga dugo sama sa iuk-iuk mogahi gikan sa likido tungod kay ang init maoy hinungdan nga mamuo ang mga protina sa dugo."}, "source": "encyclopedia-stable consensus; NRC PS1.B (chemical changes from heat)", "generator": "claude-workflow", "reviewed": false},
  {"id": "kare-kare-peanut-sauce-g5", "domain": "MATTER", "topic": "thickening a sauce", "grades": [4, 5, 6], "terms": ["kare-kare", "mani", "sarsa", "lumapot", "kumapal", "giniling", "peanut", "sauce", "thicken", "mixture", "halo", "timpla", "luto", "thick", "naglapot", "gilapot", "sarsa nga baga", "giniling nga mani"], "fact": {"tl": "Lumalapot ang sarsa ng kare-kare dahil ang giniling na mani ay naghahalo sa tubig at nagiging makapal na timpla kapag iniluto.", "en": "Kare-kare's sauce thickens because ground peanuts mix into the water and form a thick mixture as it cooks.", "bis": "Molapot ang sarsa sa kare-kare tungod kay ang giniling nga mani mosagol sa tubig ug mahimong baga nga sagol samtang gilutoan."}, "source": "encyclopedia-stable consensus; NRC PS1.A (mixtures)", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnifying-inspection-hand-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "magnifying glass lens", "grades": [3, 4, 5], "terms": ["magnifying glass", "lente", "salamin", "lupa", "pampalaki", "magnifier", "lens", "magnify", "lapad nga salamin", "pangpadako", "pagdako", "lumaki", "tingnan", "tan-aw", "obserba", "observe"], "fact": {"tl": "Ang magnifying glass ay may kurbadong salamin (lente) na nagbabaluktot ng liwanag para magmukhang mas malaki ang maliliit na bagay.", "en": "A magnifying glass has a curved piece of glass (a lens) that bends light so small things look bigger when you look through it.", "bis": "Ang magnifying glass adunay kurbado nga bildo (lente) nga nagabaliko sa kahayag aron ang gagmay nga butang magpakita nga mas dako."}, "source": "encyclopedia-stable consensus; NRC PS4 (light/optics)", "generator": "claude-workflow", "reviewed": false},
  {"id": "microscope-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "microscope magnification", "grades": [5, 6, 7], "terms": ["microscope", "mikroskopyo", "lente", "lens", "selula", "cell", "mikrobyo", "germ", "bacteria", "magnify", "palakihin", "obserbahan", "tan-awon", "selyula", "gagmay kaayo", "maliit", "objective", "magpadako"], "fact": {"tl": "Ang mikroskopyo ay gumagamit ng dalawa o higit pang lente para palakihin nang sobra ang mga bagay na napakaliit para makita ng mata, gaya ng mga selula at mikrobyo.", "en": "A microscope uses two or more lenses to magnify things far too small to see with the eye, like cells and microbes.", "bis": "Ang mikroskopyo naggamit ug duha o labaw pa nga lente aron padakoon pag-ayo ang mga butang nga gagmay kaayo nga dili makita sa mata, sama sa mga selula ug mikrobyo."}, "source": "encyclopedia-stable consensus; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "label-callout-g4", "domain": "LIVING_THINGS", "topic": "labeled diagram", "grades": [3, 4, 5], "terms": ["label", "etiketa", "pangalan", "diagram", "callout", "tatak", "tudling", "ngalan", "guhit", "parte", "bahagi", "bahin", "ipakita", "pakitang parte", "naming parts"], "fact": {"tl": "Sa agham, ang label o callout ay isang maikling pangalan na may guhit na tumuturo sa isang parte ng larawan para malaman kung ano ang tinatawag dito.", "en": "In science, a label or callout is a short name with a line pointing to a part of a picture, so you know what that part is called.", "bis": "Sa siyensya, ang label o callout usa ka mubo nga ngalan nga adunay linya nga nagtudlo sa usa ka bahin sa hulagway, aron mahibaw-an kung unsa ang ngalan niini."}, "source": "encyclopedia-stable consensus (science diagrams)", "generator": "claude-workflow", "reviewed": false},
  {"id": "longganisa-string-hanging-g6", "domain": "MATTER", "topic": "meat preservation curing", "grades": [5, 6, 7], "terms": ["longganisa", "sausage", "karne", "meat", "asin", "salt", "preserba", "preserve", "nabubulok", "pagkabulok", "spoil", "asukal", "cure", "magtago", "tipigan", "tagana", "pagkaon", "magdugay", "bakterya", "bacteria", "madunot"], "fact": {"tl": "Ang longganisa ay karne na hinaluan ng asin, asukal, at rekado para mas tumagal bago mabulok, dahil ang asin ay pumipigil sa pagdami ng bakterya.", "en": "Longganisa is meat mixed with salt, sugar, and spices to make it last longer before spoiling, because salt slows the growth of bacteria.", "bis": "Ang longganisa karne nga gisagolan ug asin, asukar, ug panakot aron mas magdugay sa dili pa madunot, kay ang asin nagpugong sa pagdaghan sa bakterya."}, "source": "encyclopedia-stable consensus (food preservation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "mamon-sponge-cake-g6", "domain": "MATTER", "topic": "leavening rising cake", "grades": [5, 6, 7], "terms": ["mamon", "sponge cake", "keyk", "cake", "itlog", "egg", "hangin", "air", "bula", "bubbles", "umaalsa", "rise", "lumambot", "malambot", "espongha", "init", "heat", "lumaki", "gas", "mosaka", "humok"], "fact": {"tl": "Ang mamon ay malambot dahil ang binateng itlog ay nagkukulong ng maliliit na bula ng hangin na lumalaki sa init ng oven, kaya umaalsa ito.", "en": "Mamon is fluffy because beaten eggs trap tiny air bubbles that expand in the oven's heat, making the cake rise.", "bis": "Ang mamon humok kay ang gibatil nga itlog nagatipig ug gagmay nga bula sa hangin nga modako sa kainit sa oven, mao nga mosaka kini."}, "source": "encyclopedia-stable consensus (baking science)", "generator": "claude-workflow", "reviewed": false},
  {"id": "mango-float-slice-g4", "domain": "MATTER", "topic": "freezing change of state", "grades": [3, 4, 5], "terms": ["mango float", "mangga", "mango", "yelo", "ice", "freezer", "nagyeyelo", "freeze", "tumitigas", "tigas", "lamig", "malamig", "matunaw", "melt", "estado", "solid", "likido", "liquid", "frozen", "mogahi", "bugnaw"], "fact": {"tl": "Ang mango float ay nilalagay sa freezer kaya tumitigas ang malabnaw na crema, dahil ang sobrang lamig ay nagpapatigas (frozen) sa likidong sangkap.", "en": "Mango float is put in the freezer to set, because very cold temperatures freeze the runny cream layer into a firm solid.", "bis": "Ang mango float gibutang sa freezer aron mogahi, kay ang grabe ka bugnaw nga temperatura nagahimo sa labnaw nga krema nga gahi (frozen)."}, "source": "encyclopedia-stable consensus; NRC PS1.A (states of matter)", "generator": "claude-workflow", "reviewed": false},
  {"id": "making-tsokolate-batirol-g4", "domain": "MATTER", "topic": "dissolving mixtures", "grades": [3, 4, 5], "terms": ["tsokolate", "tablea", "chocolate", "batirol", "molinillo", "haluin", "stir", "matunaw", "dissolve", "tunaw", "halo", "mainit na tubig", "hot water", "natutunaw", "sagol", "kutaw", "mixture", "magkahalo", "init"], "fact": {"tl": "Kapag hinahalo ang tablea sa mainit na tubig gamit ang batirol, mas mabilis natutunaw at nagkakahalo ang tsokolate dahil sa init at pagkilos.", "en": "Stirring chocolate tablea in hot water with a batirol makes it dissolve and mix faster, because heat and motion speed up dissolving.", "bis": "Kon kutawon ang tablea sa init nga tubig gamit ang batirol, mas paspas matunaw ug masagol ang tsokolate tungod sa kainit ug paglihok."}, "source": "encyclopedia-stable consensus; NRC PS1.A (mixtures/dissolving)", "generator": "claude-workflow", "reviewed": false},
  {"id": "maglalatik-coconut-dance-g5", "domain": "LIVING_THINGS", "topic": "coconut fruit", "grades": [4, 5, 6], "terms": ["niyog", "coconut", "bao", "shell", "lukad", "bunga", "fruit", "buko", "puno ng niyog", "coconut tree", "balat", "husk", "kopra", "copra", "buto", "seed", "lubi", "prutas", "unod", "liso"], "fact": {"tl": "Ang bao na ginagamit sa sayaw na maglalatik ay ang matigas na panlabas na balat ng buto ng niyog, na nagpoprotekta sa malambot na laman sa loob.", "en": "The coconut shells used in the maglalatik dance are the hard outer covering of the coconut seed, which protects the soft white flesh inside.", "bis": "Ang bao nga gigamit sa sayaw nga maglalatik mao ang gahi nga panggawas nga panit sa liso sa lubi, nga nagapanalipod sa humok nga puti nga unod sa sulod."}, "source": "encyclopedia-stable consensus (botany)", "generator": "claude-workflow", "reviewed": false},
  {"id": "media-noche-round-fruits-g3", "domain": "LIVING_THINGS", "topic": "fruits seeds plants", "grades": [3, 4, 5], "terms": ["prutas", "fruit", "bilog", "round", "buto", "seed", "halaman", "plant", "mansanas", "apple", "ubas", "grapes", "bunga", "tubo", "grow", "liso", "tanom", "magtanim", "lingin nga prutas", "media noche"], "fact": {"tl": "Ang mga bilog na prutas sa media noche, gaya ng mansanas at ubas, ay nagmula sa mga halaman at may mga buto na maaaring tumubo bilang bagong halaman.", "en": "The round fruits at media noche, like apples and grapes, come from plants and hold seeds that can grow into new plants.", "bis": "Ang mga lingin nga prutas sa media noche, sama sa mansanas ug ubas, naggikan sa mga tanom ug adunay mga liso nga mahimong motubo nga bag-ong tanom."}, "source": "encyclopedia-stable consensus; NRC LS1.B (plant reproduction)", "generator": "claude-workflow", "reviewed": false},
  {"id": "menudo-stew-bowl-g5", "domain": "MATTER", "topic": "cooking heat changes food", "grades": [4, 5, 6], "terms": ["menudo", "nilaga", "stew", "init", "heat", "luto", "cook", "lumambot", "tender", "karne", "meat", "patatas", "potato", "sabaw", "broth", "kumukulo", "boil", "nagbabago", "change", "pagluto", "humok", "utanon"], "fact": {"tl": "Sa pagluluto ng menudo, ang init mula sa apoy ay nagpapalambot sa karne at gulay at nagbabago sa lasa at tekstura ng pagkain.", "en": "When cooking menudo, heat from the fire softens the meat and vegetables and changes the food's taste and texture.", "bis": "Sa pagluto sa menudo, ang kainit gikan sa kalayo nagapahumok sa karne ug utanon ug nagausab sa lami ug texture sa pagkaon."}, "source": "encyclopedia-stable consensus; NRC PS1.B (changes from heating)", "generator": "claude-workflow", "reviewed": false},
  {"id": "luksong-tinik-hand-stack-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "jumping push force gravity", "grades": [3, 4, 5], "terms": ["luksong tinik", "talon", "jump", "lukso", "puwersa", "force", "lakas", "push", "gravity", "grabidad", "bumaba", "pababa", "ambak", "itulak", "tumalon", "lakas sa paa", "balik sa lupa", "lupa", "yuta", "tulod"], "fact": {"tl": "Sa luksong tinik, tumatalon ang bata sa pamamagitan ng pagtulak ng kanyang mga paa sa lupa, at hinihila siya pababa ng grabidad para bumalik sa lupa.", "en": "In luksong tinik, a child jumps by pushing their feet against the ground, and gravity pulls them back down to land.", "bis": "Sa luksong tinik, molukso ang bata pinaagi sa pagtulod sa iyang tiil batok sa yuta, ug ang grabidad nagabira kaniya paubos aron mobalik sa yuta."}, "source": "encyclopedia-stable consensus; NRC PS2.A/PS2.B (forces, gravity)", "generator": "claude-workflow", "reviewed": false},
  {"id": "luksong-baka-tall-base-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "energy of motion jumping", "grades": [3, 4, 5], "terms": ["luksong baka", "talon", "jump", "lukso", "lakas", "energy", "enerhiya", "puwersa", "force", "galaw", "motion", "kilos", "tumalon", "kusog", "lihok", "lakas sa lawas", "ambak", "yuta", "bitiis"], "fact": {"tl": "Sa luksong baka, ginagamit ng bata ang lakas ng kanyang mga binti para sumipa sa lupa, na nagbibigay ng enerhiya para makalukso pataas at lampas sa kalaro.", "en": "In luksong baka, a child uses the strength of their legs to push off the ground, giving the energy to jump up and over a playmate.", "bis": "Sa luksong baka, gigamit sa bata ang kusog sa iyang mga bitiis sa pagtulod sa yuta, nga naghatag ug enerhiya aron makalukso pataas ug lapas sa kadula."}, "source": "encyclopedia-stable consensus; NRC PS3.A (energy of motion)", "generator": "claude-workflow", "reviewed": false},
  {"id": "otap-oval-pastry-g4", "domain": "MATTER", "topic": "otap layered pastry baking", "grades": [4, 5, 6], "terms": ["otap", "puff pastry", "biskwit", "tinapay", "pinitsa", "harina", "asukal", "mantikilya", "layered", "flaky", "Cebu", "oval", "manipis", "lutuon", "init sa hudno", "baking", "pastry", "biscuit", "patong"], "fact": {"tl": "Ang otap ay isang manipis, hugis-itlog na biskwit mula sa Cebu na gawa sa harina at asukal, at namumuo ang maraming patong nito kapag tumitigas ang masa sa init ng hudno.", "en": "Otap is a thin, oval pastry from Cebu made from flour and sugar, and its many flaky layers form as the dough hardens in the heat of the oven.", "bis": "Ang otap usa ka nipis, oval nga biskwit gikan sa Cebu nga hinimo sa harina ug asukar, ug ang daghang patong niini maporma samtang mogahi ang minasa sa init sa hudno."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pancit-luglug-bowl-g4", "domain": "LIVING_THINGS", "topic": "rice noodles food nutrition", "grades": [4, 5, 6], "terms": ["pancit luglug", "palabok", "bihon", "noodles", "pansit", "kanin", "bigas", "rice flour", "karbohidrat", "carbohydrate", "lakas", "enerhiya", "kalan-on", "humay", "noodle", "pagkaon"], "fact": {"tl": "Ang pancit luglug ay gawa sa makapal na bihon mula sa harina ng bigas, at ang bigas ay mayaman sa karbohidrat na nagbibigay ng enerhiya sa katawan.", "en": "Pancit luglug is made from thick rice-flour noodles, and rice is rich in carbohydrates that give the body energy.", "bis": "Ang pancit luglug hinimo sa baga nga bihon gikan sa harina sa bugas, ug ang bugas dato sa karbohidrat nga naghatag ug kusog sa lawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pichu-pichu-cup-g4", "domain": "MATTER", "topic": "cassava steamed delicacy", "grades": [4, 5, 6], "terms": ["pichi pichi", "pichu pichu", "kakanin", "kamoteng kahoy", "kasava", "cassava", "balinghoy", "gawgaw", "starch", "almirol", "steamed", "pinasingawan", "malagkit", "niyog", "Bisaya kakanin", "delicacy", "gulaman"], "fact": {"tl": "Ang pichi-pichi ay isang malagkit na kakanin na gawa sa giniling na kamoteng-kahoy, at ito ay tumitigas at nagiging malinaw kapag pinasingawan dahil sa starch o almirol nito.", "en": "Pichi-pichi is a chewy delicacy made from grated cassava, and it firms up and turns translucent when steamed because of its starch.", "bis": "Ang pichi-pichi usa ka pilit nga kakanin nga hinimo sa giniling nga balinghoy, ug kini mogahi ug mahimong tin-aw kon pasingawan tungod sa starch o almidor niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pencil-sharpened-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "pencil sharpener wedge blade", "grades": [3, 4, 5], "terms": ["lapis", "pencil", "pantasa", "sharpener", "talim", "blade", "wedge", "tulis", "matalim", "talinis", "kahoy", "graphite", "simpleng makina", "simple machine", "pagtutulis"], "fact": {"tl": "Ang matalim na talim sa pantasa ay isang wedge na humahati sa kahoy ng lapis upang ito ay maging matulis at handa nang isulat.", "en": "The sharp blade of a pencil sharpener is a wedge that shaves away the wood so the pencil's tip becomes pointed and ready to write.", "bis": "Ang hait nga sulab sa pantasa usa ka wedge nga magkiskis sa kahoy sa lapis aron mahimong talinis ang tumoy ug andam na isulat."}, "source": "AAAS Benchmarks 8E (tools/simple machines)", "generator": "claude-workflow", "reviewed": false},
  {"id": "piko-hopscotch-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "balance and gravity in hopscotch", "grades": [3, 4, 5], "terms": ["piko", "hopscotch", "isang paa", "balance", "balanse", "timbang", "gravity", "grabidad", "talon", "lukso", "lambitin", "ambak", "isa ka tiil", "laro", "game", "center of gravity", "muscle"], "fact": {"tl": "Sa larong piko, kailangan mong panatilihing balanse ang katawan sa isang paa, kaya kumikilos ang iyong mga kalamnan upang labanan ang hila ng grabidad at hindi ka matumba.", "en": "In hopscotch, you must keep your body balanced on one foot, so your muscles work to fight the pull of gravity and keep you from falling over.", "bis": "Sa dula nga piko, kinahanglan nimong magpabilin ang lawas nga balanse sa usa ka tiil, mao nga molihok ang imong mga unod aron batokan ang gabira nga grabidad ug dili ka matumba."}, "source": "AAAS Benchmarks 4F (forces/gravity)", "generator": "claude-workflow", "reviewed": false},
  {"id": "pabuya-coin-scramble-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "gravity makes coins fall", "grades": [3, 4, 5], "terms": ["pabuya", "coin scramble", "barya", "coins", "sinsilyo", "nahuhulog", "fall", "gravity", "grabidad", "hila", "lupa", "bug-at", "nahulog", "ihulog", "scramble", "down", "ibabaw pababa"], "fact": {"tl": "Kapag ihinahagis ang mga barya sa pabuya, palaging bumabagsak ang mga ito pababa sa lupa dahil hinihila ng grabidad ng Earth ang lahat ng bagay patungo sa ibaba.", "en": "When coins are tossed in a pabuya scramble, they always fall downward to the ground because Earth's gravity pulls every object toward the ground.", "bis": "Kon ilabay ang mga sinsilyo sa pabuya, kanunay kining mahulog paubos sa yuta tungod kay ang grabidad sa Yuta nagbira sa tanang butang padulong sa ubos."}, "source": "AAAS Benchmarks 4B (gravity)", "generator": "claude-workflow", "reviewed": false},
  {"id": "planting-trees-community-scene-g4", "domain": "LIVING_THINGS", "topic": "trees clean air and prevent erosion", "grades": [4, 5, 6], "terms": ["pagtatanim ng puno", "planting trees", "reforestation", "kahoy", "puno", "ugat", "roots", "erosion", "guho ng lupa", "hangin", "oxygen", "oksiheno", "carbon dioxide", "lilim", "tubig", "pagtanom ug kahoy", "gamot", "kalikasan", "pagtanom"], "fact": {"tl": "Kapag nagtatanim tayo ng mga puno, naglilinis sila ng hangin sa pamamagitan ng pagsipsip ng carbon dioxide at paglabas ng oksiheno, at hinahawakan ng kanilang mga ugat ang lupa upang hindi guguho.", "en": "When we plant trees, they clean the air by taking in carbon dioxide and releasing oxygen, and their roots hold the soil so it does not wash away.", "bis": "Kon magtanom kita ug mga kahoy, ginalinis nila ang hangin pinaagi sa pagsuyop sa carbon dioxide ug pagbuga ug oksiheno, ug ang ilang mga gamot nagkupot sa yuta aron dili mahugno."}, "source": "NRC LS2; DepEd G4 environment", "generator": "claude-workflow", "reviewed": false},
  {"id": "plantsa-flat-iron-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "iron uses heat energy to smooth cloth", "grades": [4, 5, 6], "terms": ["plantsa", "flat iron", "iron", "kuryente", "electricity", "init", "heat", "enerhiya", "energy", "kuluntoy", "gusot", "damit", "tela", "kalor", "init sa plantsa", "plantsahan", "wrinkles", "smooth", "kalentura sa puthaw"], "fact": {"tl": "Ang plantsa ay nagpapainit gamit ang kuryente, at ang init nitong enerhiya ang nagpapatag sa mga gusot ng tela kapag idinaan mo ito sa damit.", "en": "A flat iron heats up using electricity, and its heat energy presses out the wrinkles in cloth when you slide it over the fabric.", "bis": "Ang plantsa moinit pinaagi sa koryente, ug ang init nga enerhiya niini maoy mopatag sa mga kunot sa panapton kon imong ipadagan kini sa sapot."}, "source": "NRC PS3 (energy/heat); DepEd G5 energy", "generator": "claude-workflow", "reviewed": false},
  {"id": "parol-vendor-stand-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "lighted Christmas lantern electricity", "grades": [4, 5, 6], "terms": ["parol", "Christmas lantern", "Pasko", "ilaw", "light", "bombilya", "bulb", "kuryente", "electricity", "kuryenteng dumadaloy", "enerhiya", "liwanag", "circuit", "suga", "parul", "ilaw sa Pasko", "bituin", "star lantern"], "fact": {"tl": "Ang makulay na parol ng Pasko ay nagliliwanag dahil dumadaloy ang kuryente sa mga maliliit nitong bombilya, na nagbabago ng elektrikal na enerhiya tungo sa liwanag.", "en": "The colorful Christmas parol glows because electricity flows through its tiny bulbs, changing electrical energy into light.", "bis": "Ang mabulukon nga parol sa Pasko mosiga tungod kay ang koryente nag-agos sa gagmay niini nga bombilya, nga nag-usab sa elektrikal nga enerhiya ngadto sa kahayag."}, "source": "NRC PS3 (energy transfer); DepEd G5 electricity", "generator": "claude-workflow", "reviewed": false},
  {"id": "pahiyas-kiping-house-facade-g5", "domain": "MATTER", "topic": "kiping rice wafer decoration", "grades": [4, 5, 6], "terms": ["kiping", "Pahiyas", "Lucban", "rice wafer", "galapong", "bigas", "rice", "dahon", "leaf-shaped", "kabal leaf", "kulay", "pagkain", "dekorasyon", "harvest festival", "anihan", "bugas", "humay", "wafer", "pista"], "fact": {"tl": "Ang makukulay na kiping na ipinangdedekorasyon sa mga bahay tuwing Pahiyas ay gawa sa galapong o giniling na bigas na hinugis sa dahon, na nagpapakita kung paano nagiging makinis na pagkain ang bigas.", "en": "The colorful kiping that decorate houses during the Pahiyas festival are made from ground rice batter shaped on a leaf, showing how rice can be turned into a smooth food.", "bis": "Ang mabulukon nga kiping nga gigamit sa pagdayandayan sa mga balay panahon sa Pahiyas hinimo sa giniling nga bugas nga giporma sa dahon, nga nagpakita kon unsaon pagkahimong hamis nga pagkaon ang bugas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "puto-steamed-rice-cake-g4", "domain": "MATTER", "topic": "steaming cooks food using water vapor heat", "grades": [4, 5, 6], "terms": ["puto", "kakanin", "singaw", "pinapasingawan", "sinaing sa singaw", "alisngaw", "gisingawan", "gipasingawan", "alisbo", "steam", "steaming", "water vapor", "rice cake"], "fact": {"tl": "Ang puto ay niluluto sa pamamagitan ng singaw ng kumukulong tubig, kaya ito naluluto nang hindi direktang nilulubog sa tubig o pinipirito.", "en": "Puto is cooked by the steam of boiling water, so it cooks without being soaked in water or fried in oil.", "bis": "Ang puto giluto pinaagi sa alisngaw sa nagbukal nga tubig, mao nga maluto kini bisan dili ibutang sa tubig o iprito."}, "source": "encyclopedia-stable consensus; NRC PS1.A (states of matter, heat transfer)", "generator": "claude-workflow", "reviewed": false},
  {"id": "puto-calasiao-fermentation-g6", "domain": "LIVING_THINGS", "topic": "fermentation makes rice cakes rise and turn sour", "grades": [6, 7, 8], "terms": ["puto Calasiao", "puto", "pampaalsa", "lebadura", "pagbuburo", "fermentation", "yeast", "pagpaburo", "binuro", "umaalsa", "naga-alsa", "tubo-tubo", "sour rice cake"], "fact": {"tl": "Ang puto Calasiao ay umaalsa at bahagyang umaasim dahil sa pagbuburo (fermentation), kung saan ang maliliit na organismong tulad ng lebadura ay gumagawa ng gas mula sa asukal ng bigas.", "en": "Puto Calasiao rises and turns slightly sour because of fermentation, where tiny organisms like yeast make gas from the sugar in the rice.", "bis": "Ang puto Calasiao naga-alsa ug medyo naga-aslom tungod sa pagpaburo (fermentation), diin ang gagmay nga organismo sama sa lebadura naghimo og gas gikan sa asukal sa bugas."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks 5C (cells/microbes)", "generator": "claude-workflow", "reviewed": false},
  {"id": "puto-seko-dry-cookie-g4", "domain": "MATTER", "topic": "baking drives off water to make food dry and crumbly", "grades": [4, 5, 6], "terms": ["puto seko", "putong seko", "biskwit", "galyetas", "natuyo", "natuyong tubig", "nawalang tubig", "namala", "nauga", "evaporation", "dry cookie", "crumbly", "tuyo"], "fact": {"tl": "Ang puto seko ay tuyo at madurog dahil sa pagluluto ay halos lahat ng tubig sa masa ay sumingaw at naglaho.", "en": "Puto seko is dry and crumbly because, during baking, almost all the water in the dough evaporates away.", "bis": "Ang puto seko uga ug daling madugmok kay sa pagluto, hapit tanan nga tubig sa minasa nahimong alisngaw ug nawala."}, "source": "encyclopedia-stable consensus; NRC PS1.A (evaporation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "puto-flan-leche-flan-g5", "domain": "MATTER", "topic": "heat changes liquid egg-and-milk mix into a firm solid", "grades": [5, 6, 7], "terms": ["puto flan", "leche flan", "itlog", "gatas", "tumigas", "namuo", "naninigas", "nagbago", "nag-init", "namugna", "gipagahi", "custard", "egg", "milk", "set", "firm"], "fact": {"tl": "Sa leche flan, ang malabnaw na timpla ng itlog at gatas ay naninigas at nagiging matigas na kustard kapag iniinit, isang pagbabagong hindi na bumabalik sa dating anyo.", "en": "In leche flan, the runny mix of egg and milk firms up into a solid custard when heated, a change that cannot return to its old form.", "bis": "Sa leche flan, ang labnaw nga sagol sa itlog ug gatas magahi ngadto sa solidong custard kon initon, usa ka kausaban nga dili na mobalik sa karaan niini nga porma."}, "source": "encyclopedia-stable consensus; NRC PS1.B (irreversible change)", "generator": "claude-workflow", "reviewed": false},
  {"id": "puto-pao-steamed-bun-g4", "domain": "MATTER", "topic": "steamed buns rise from gas bubbles trapped in dough", "grades": [4, 5, 6], "terms": ["puto pao", "siyopaw", "tinapay na pinasingawan", "pampaalsa", "bula ng gas", "umaalsa", "lumaki", "naga-alsa", "nidako", "gas bubbles", "steamed bun", "lambot", "malambot"], "fact": {"tl": "Ang puto pao ay malambot at maaliwalas dahil sa loob ng masa nito ay may maliliit na bula ng gas na lumalaki kapag pinasisingawan.", "en": "Puto pao is soft and fluffy because tiny gas bubbles inside its dough grow larger when it is steamed.", "bis": "Ang puto pao humok ug habog kay adunay gagmay nga bula sa gas sulod sa minasa niini nga modako kon pasingawan."}, "source": "encyclopedia-stable consensus; NRC PS1.A (gases expand with heat)", "generator": "claude-workflow", "reviewed": false},
  {"id": "rice-granary-grain-drying-g5", "domain": "LIVING_THINGS", "topic": "drying and dry storage keep grain from spoiling", "grades": [5, 6, 7], "terms": ["bahay bigasan", "kamalig", "bigas", "palay", "imbakan", "tuyo", "pinatuyo", "amag", "agnata", "uga", "gipauga", "agup-op", "tipigan", "granary", "rice storage", "mold", "spoil"], "fact": {"tl": "Ang palay ay pinatutuyo muna at iniimbak sa tuyong kamalig upang hindi magtubo ang amag, dahil ang amag at insekto ay umuunlad sa basa at maalinsangang lugar.", "en": "Rice grain is first dried and kept in a dry granary so mold cannot grow, because mold and insects thrive in damp, humid places.", "bis": "Ang palay pauga-on una ug tipigan sa uga nga kamalig aron dili motubo ang agup-op, kay ang agup-op ug insekto molambo sa basa ug alisngaw nga dapit."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks 5C (decomposers, food preservation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "road-crossing-safety-stopping-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "moving vehicles cannot stop instantly so look before crossing", "grades": [3, 4, 5], "terms": ["pagtawid sa kalsada", "tumingin", "kaliwa", "kanan", "preno", "hindi agad humihinto", "biglang humihinto", "tan-aw", "wala", "tuo", "dili dayon mohunong", "road crossing", "vehicle", "brake", "stop"], "fact": {"tl": "Tumingin sa kaliwa at kanan bago tumawid dahil ang isang tumatakbong sasakyan ay hindi kaagad humihinto kahit gamitin ang preno, gawa ng inersya nito.", "en": "Look left and right before crossing because a moving vehicle cannot stop instantly even when it brakes, due to its inertia.", "bis": "Tan-aw sa wala ug tuo una motabok kay ang nagdagan nga sakyanan dili dayon mohunong bisan mo-preno, tungod sa inersya niini."}, "source": "encyclopedia-stable consensus; NRC PS2.A (inertia, motion)", "generator": "claude-workflow", "reviewed": false},
  {"id": "ruler-measuring-length-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "a ruler measures length in standard units", "grades": [3, 4, 5], "terms": ["ruler", "panukat", "sentimetro", "milimetro", "haba", "sukat", "sukod", "santimetro", "gitas-on", "sukdanan", "length", "centimeter", "millimeter", "measure"], "fact": {"tl": "Ang ruler ay kasangkapan sa pagsukat ng haba, at karaniwang may guhit na sentimetro at milimetro upang tumpak ang sukat.", "en": "A ruler is a tool for measuring length, and it usually has centimeter and millimeter marks so the measurement is exact.", "bis": "Ang ruler usa ka galamiton sa pagsukod sa gitas-on, ug kasagaran adunay marka nga sentimetro ug milimetro aron sakto ang sukod."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks 9C (measurement, units)", "generator": "claude-workflow", "reviewed": false},
  {"id": "scissors-lever-simple-machine-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "scissors are a pair of levers turning on a pivot", "grades": [5, 6, 7], "terms": ["gunting", "scissors", "panagupit", "pivot", "tuktok na pako", "panghiwa", "pulseyo", "gabuhat", "putol", "simpleng makina", "lever", "pivot", "blade", "cut"], "fact": {"tl": "Ang gunting ay binubuo ng dalawang lever na nagsasalubong sa isang pivot, kaya kahit kaunting puwersa sa hawakan ay sapat na para gupitin ang papel.", "en": "Scissors are made of two levers meeting at a pivot, so even a small force on the handles is enough to cut paper.", "bis": "Ang gunting gama sa duha ka lever nga nagtagbo sa usa ka pivot, mao nga bisan gamay nga kusog sa hawiranan igo na aron putlon ang papel."}, "source": "encyclopedia-stable consensus; NRC PS2.A; AAAS Benchmarks 8B (simple machines)", "generator": "claude-workflow", "reviewed": false},
  {"id": "gulaman-agar-gel-g5", "domain": "MATTER", "topic": "gulaman is a gel set from seaweed extract dissolved in hot water", "grades": [5, 6, 7], "terms": ["gulaman", "sagot gulaman", "agar", "damong dagat", "natunaw", "lumamig", "namuo", "naninigas", "nalusaw", "nibugnaw", "nag-gel", "gipagahi", "seaweed", "gel", "dissolve", "set"], "fact": {"tl": "Ang gulaman ay gawa sa sangkap na kinuha sa damong-dagat na natutunaw sa mainit na tubig at saka naninigas na parang halaya kapag pinalamig.", "en": "Gulaman is made from a substance taken from seaweed that dissolves in hot water and then sets into a jelly when cooled.", "bis": "Ang gulaman gama sa sangkap nga gikan sa lusay nga matunaw sa init nga tubig ug unya magahi nga morag halaya kon bugnawon."}, "source": "encyclopedia-stable consensus; NRC PS1.A (dissolving, temperature and state)", "generator": "claude-workflow", "reviewed": false},
  {"id": "samalamig-dissolving-sweet-drink-g4", "domain": "MATTER", "topic": "sugar dissolves and spreads through water to sweeten a drink", "grades": [4, 5, 6], "terms": ["samalamig", "sago gulaman", "asukal", "natunaw", "nahalo", "kumalat", "inumin", "kalamay", "nasagol", "mikatag", "ilimnon", "dissolve", "sugar", "mix", "drink"], "fact": {"tl": "Sa samalamig, ang asukal ay natutunaw at kumakalat sa buong tubig, kaya pantay-pantay ang tamis ng bawat lagok.", "en": "In samalamig, the sugar dissolves and spreads evenly through the water, so every sip is equally sweet.", "bis": "Sa samalamig, ang asukal matunaw ug mokatag sa tibuok tubig, mao nga managsama ang katam-is sa matag higop."}, "source": "encyclopedia-stable consensus; NRC PS1.A (dissolving, mixtures)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sapin-sapin-layers-color-g4", "domain": "MATTER", "topic": "sapin-sapin is built from separate stacked layers cooked in turn", "grades": [4, 5, 6], "terms": ["sapin-sapin", "kakanin", "patong-patong", "layer", "kulay", "magkakaibang kulay", "namuo", "magkapatong", "magkalainlaing kolor", "sapaw-sapaw", "layered", "stacked", "colors"], "fact": {"tl": "Ang sapin-sapin ay gawa sa magkakapatong na manipis na patong na iba-iba ang kulay, at bawat patong ay niluluto nang isa-isa bago ilagay ang susunod.", "en": "Sapin-sapin is made of thin stacked layers of different colors, and each layer is cooked one at a time before the next is added.", "bis": "Ang sapin-sapin gama sa nipis nga sapaw-sapaw nga lainlain og kolor, ug ang matag sapaw lutoon usa-usa una idugang ang sunod."}, "source": "encyclopedia-stable consensus; NRC PS1.A (states/mixtures, heat)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sans-rival-meringue-cashew-g6", "domain": "MATTER", "topic": "whipping egg whites traps air to make a light meringue", "grades": [6, 7, 8], "terms": ["sans rival", "meringue", "puti ng itlog", "hangin", "binati", "kasoy", "nagbula", "puti sa itlog", "gibatil", "nagbukal", "egg white", "air", "whip", "cashew", "light"], "fact": {"tl": "Ang sans rival ay gawa sa meringue, kung saan ang puti ng itlog ay binabati nang husto upang makakulong ang hangin at maging magaan at malutong.", "en": "Sans rival is made from meringue, where egg whites are whipped hard to trap air so it becomes light and crisp.", "bis": "Ang sans rival gama sa meringue, diin ang puti sa itlog batilon og maayo aron makulong ang hangin ug mahimong gaan ug tagiktik."}, "source": "encyclopedia-stable consensus; NRC PS1.A (mixtures, trapping gas)", "generator": "claude-workflow", "reviewed": false},
  {"id": "salakot-sun-rain-protection-g4", "domain": "MATTER", "topic": "the salakot is a woven wide hat that shields from sun and rain", "grades": [4, 5, 6], "terms": ["salakot", "sumbrero", "habi", "kawayan", "anahaw", "araw", "ulan", "pananggalang", "kalo", "hinabi", "adlaw", "panalipod", "woven", "wide hat", "sun", "rain"], "fact": {"tl": "Ang salakot ay malapad na sumbrerong hinabi mula sa kawayan o dahon ng anahaw, at ginagamit ng mga magsasaka bilang panangga sa init ng araw at ulan.", "en": "The salakot is a wide woven hat made from bamboo or anahaw leaves, used by farmers as a shield against the sun's heat and the rain.", "bis": "Ang salakot usa ka lapad nga kalo nga hinabi gikan sa kawayan o dahon sa anahaw, gigamit sa mga mag-uuma isip panalipod batok sa init sa adlaw ug sa ulan."}, "source": "encyclopedia-stable consensus; DepEd MATATAG (local materials and uses)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sandok-coconut-ladle-material-g3", "domain": "MATTER", "topic": "a coconut-shell ladle uses a hard natural shell as a scoop", "grades": [3, 4, 5], "terms": ["sandok", "bao", "niyog", "ladle", "panandok", "matigas", "kahoy", "kabhang", "lubi", "gahi", "panakdo", "bagol", "coconut shell", "ladle", "hard", "scoop"], "fact": {"tl": "Ang sandok na yari sa bao ng niyog ay gumagamit ng matigas na balat ng niyog bilang lalagyan ng sabaw, na ikinakabit sa hawakang kahoy.", "en": "A ladle made from a coconut shell uses the hard coconut shell as a scoop for soup, fixed to a wooden handle.", "bis": "Ang sandok nga hinimo sa bagol sa lubi naggamit sa gahi nga panit sa lubi isip sudlanan sa sabaw, nga gitaod sa kahoy nga hawiranan."}, "source": "encyclopedia-stable consensus; DepEd MATATAG (properties of materials)", "generator": "claude-workflow", "reviewed": false},
  {"id": "candle-flame-combustion-g5", "domain": "MATTER", "topic": "a burning candle melts then burns wax to give light and heat", "grades": [5, 6, 7], "terms": ["kandila", "apoy", "natutunaw", "init", "liwanag", "pagkasunog", "nasunog", "kalayo", "natunaw", "kainit", "kahayag", "candle", "flame", "wax", "burn", "melt", "combustion"], "fact": {"tl": "Kapag nagniningas ang kandila, ang init ng apoy ay nagpapatunaw sa kandila at sinusunog ang umaakyat na singaw nito, na nagbibigay ng liwanag at init.", "en": "When a candle burns, the flame's heat melts the wax and burns its rising vapor, giving off light and heat.", "bis": "Kon mosiga ang kandila, ang init sa kalayo magtunaw sa kandila ug magsunog sa nagsaka nga alisngaw niini, nga naghatag og kahayag ug kainit."}, "source": "encyclopedia-stable consensus; NRC PS1.B; PS3 (combustion, energy release)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sikwate-cup-g5", "domain": "MATTER", "topic": "sikwate native hot chocolate from cacao tablea dissolving", "grades": [4, 5, 6], "terms": ["sikwate", "tsokolate", "tablea", "kakaw", "cacao", "cocoa", "natutunaw", "natunaw", "matunaw", "init", "mainit", "hot chocolate", "dissolve", "mixture", "halo", "sagol"], "fact": {"tl": "Ang sikwate ay mainit na inuming gawa sa tablea na pinukpok mula sa butil ng kakaw, at madaling natutunaw ang tablea sa mainit na tubig o gatas.", "en": "Sikwate is a hot drink made from tablea pressed from cacao seeds, and the tablea dissolves more easily in hot water or milk.", "bis": "Ang sikwate kay init nga ilimnon gikan sa tablea nga gigaling gikan sa liso sa kakaw, ug dali ra matunaw ang tablea sa init nga tubig o gatas."}, "source": "encyclopedia-stable consensus; NRC PS1.A (mixtures/dissolving)", "generator": "claude-workflow", "reviewed": false},
  {"id": "squid-ball-stick-g5", "domain": "LIVING_THINGS", "topic": "squid is a soft-bodied sea animal mollusk", "grades": [4, 5, 6], "terms": ["squid", "pusit", "nokus", "isda", "dagat", "sea animal", "mollusk", "tentacles", "galamay", "arms", "softbody", "lambot", "humok", "hayop", "hayop sa dagat", "mananap sa dagat"], "fact": {"tl": "Ang pusit, na ginagawang squid ball, ay isang malambot na hayop sa dagat na walang buto at may mahahabang galamay na ginagamit nito para humuli ng pagkain.", "en": "The squid used to make squid balls is a soft-bodied sea animal with no bones and long arms that it uses to catch food.", "bis": "Ang nokus nga himoon nga squid ball kay humok nga mananap sa dagat nga walay bukog ug adunay tag-as nga mga galamay nga gamiton niini sa pagdakop og pagkaon."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks (diversity of life)", "generator": "claude-workflow", "reviewed": false},
  {"id": "suman-budbod-kabog-g5", "domain": "LIVING_THINGS", "topic": "suman and budbod kabog made from glutinous rice and millet plants", "grades": [4, 5, 6], "terms": ["suman", "budbod", "kabog", "millet", "dawa", "malagkit", "pilit", "glutinous rice", "bigas", "bugas", "humay", "tanim", "tanom", "buto", "liso", "lugas", "kakanin"], "fact": {"tl": "Ang suman at ang budbod kabog ay kakanin na gawa sa malagkit na bigas o sa butil ng kabog na isang uri ng millet, na parehong tumutubo bilang mga halaman sa bukirin.", "en": "Suman and budbod kabog are rice cakes made from glutinous rice or from kabog grain, a kind of millet, both of which grow as grain plants in fields.", "bis": "Ang suman ug ang budbod kabog kay kakanin nga hinimo gikan sa pilit nga bugas o gikan sa lugas sa kabog nga usa ka klase sa millet, nga pareho nga motubo isip mga tanom sa uma."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks (plants we use for food)", "generator": "claude-workflow", "reviewed": false},
  {"id": "taho-vendor-scene-g5", "domain": "LIVING_THINGS", "topic": "taho made from soybeans is rich in protein", "grades": [4, 5, 6], "terms": ["taho", "tokwa", "tofu", "soybean", "soya", "utaw", "balatong", "protina", "protein", "halaman", "tanom", "buto", "liso", "soybeans", "arnibal", "sago", "almusal"], "fact": {"tl": "Ang malambot na puti sa taho ay gawa sa gatas ng soybean o utaw, isang buto ng halaman na mayaman sa protina na nakakatulong sa paglaki ng katawan.", "en": "The soft white part of taho is made from the milk of soybeans, a plant seed rich in protein that helps the body grow.", "bis": "Ang humok nga puti sa taho kay hinimo gikan sa gatas sa soybean o utaw, usa ka liso sa tanom nga dato sa protina nga makatabang sa pagtubo sa lawas."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks (food and nutrients)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sorbetes-on-bun-g4", "domain": "MATTER", "topic": "sorbetes ice cream melts from solid to liquid with heat", "grades": [3, 4, 5, 6], "terms": ["sorbetes", "ice cream", "dirty ice cream", "sorbete", "natutunaw", "natunaw", "matunaw", "solid", "solido", "liquid", "likido", "init", "lamig", "malamig", "bugnaw", "tunaw", "states of matter", "anyo ng bagay"], "fact": {"tl": "Ang sorbetes ay malamig at solido kapag bagong luto, ngunit natutunaw ito at nagiging likido kapag uminit dahil sa init ng paligid.", "en": "Sorbetes is cold and solid when freshly made, but it melts into a liquid when it warms up from the heat around it.", "bis": "Ang sorbetes kay bugnaw ug solido kung bag-ong himo, apan matunaw kini ngadto sa likido kung moinit gikan sa kainit sa palibot."}, "source": "encyclopedia-stable consensus; NRC PS1.A (states of matter, melting)", "generator": "claude-workflow", "reviewed": false},
  {"id": "shanghai-rice-meal-g5", "domain": "LIVING_THINGS", "topic": "rice gives energy and meat gives protein in a balanced meal", "grades": [4, 5, 6], "terms": ["lumpiang shanghai", "shanghai", "kanin", "rice", "bugas", "kan-on", "karbohidrato", "carbohydrate", "enerhiya", "energy", "kusog", "protina", "protein", "karne", "meat", "pagkain", "nutrisyon"], "fact": {"tl": "Sa hain ng kanin at lumpiang shanghai, ang kanin ay nagbibigay ng enerhiya mula sa karbohidrato samantalang ang giniling na karne ay nagbibigay ng protina para sa katawan.", "en": "In a meal of rice and lumpiang shanghai, the rice gives energy from carbohydrates while the ground meat gives protein for the body.", "bis": "Sa pagkaon nga kan-on ug lumpiang shanghai, ang kan-on naghatag og kusog gikan sa karbohidrato samtang ang giniling nga karne naghatag og protina para sa lawas."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks (food and nutrients)", "generator": "claude-workflow", "reviewed": false},
  {"id": "tnalak-abaca-cloth-g5", "domain": "MATTER", "topic": "tnalak cloth woven from abaca plant fiber", "grades": [4, 5, 6], "terms": ["tnalak", "t'nalak", "tela", "habi", "hinabi", "abaka", "pinya", "lanot", "hibla", "Tboli", "T'boli", "saput", "panaptong abaka", "tnalak cloth", "abaca fiber", "woven", "weaving", "banana"], "fact": {"tl": "Ang t'nalak ay tela na hinahabi ng mga T'boli mula sa hibla ng halamang abaka, na kamag-anak ng saging.", "en": "T'nalak is a cloth the T'boli people weave from fibers of the abaca plant, a relative of the banana.", "bis": "Ang t'nalak usa ka panapton nga ginahabol sa mga T'boli gikan sa lanot sa tanom nga abaka, paryente sa saging."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tnalak-natural-dye-g6", "domain": "MATTER", "topic": "natural plant dyes color tnalak cloth", "grades": [5, 6, 7], "terms": ["tnalak", "t'nalak", "kulay", "tina", "pangkulay", "knalum", "dahon", "ugat", "natural na tina", "tinina", "natural dye", "pigment", "kolor", "Tboli", "tina sa tanom", "tinaan"], "fact": {"tl": "Ang itim, pula, at puti na kulay ng t'nalak ay galing sa likas na tina mula sa mga dahon at ugat ng halaman, hindi sa kemikal na pintura.", "en": "The black, red, and white colors of t'nalak come from natural dyes made from plant leaves and roots, not from chemical paint.", "bis": "Ang itom, pula, ug puti nga kolor sa t'nalak naggikan sa natural nga tina gikan sa mga dahon ug gamot sa tanom, dili sa kemikal nga pintura."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tboli-brass-belt-alloy-g6", "domain": "MATTER", "topic": "brass belt is an alloy of copper and zinc", "grades": [5, 6, 7], "terms": ["brass", "tanso", "bronse", "haspe", "sinturon", "bakos", "metal", "Tboli", "T'boli", "kuwintas na metal", "copper", "zinc", "halong metal", "aleyahe", "alloy", "tumbaga", "sinaghong metal"], "fact": {"tl": "Ang makinang na brass na ginagamit sa sinturon at palamuti ng T'boli ay isang aleyahe—halo ng dalawang metal na tanso at zinc.", "en": "The shiny brass used in T'boli belts and ornaments is an alloy—a mixture of two metals, copper and zinc.", "bis": "Ang masinaw nga brass nga gigamit sa bakos ug dayandayan sa T'boli usa ka aleyahe—sagol sa duha ka metal, tumbaga ug zinc."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tocino-cured-pork-g6", "domain": "MATTER", "topic": "curing pork with salt and sugar preserves it", "grades": [5, 6, 7], "terms": ["tocino", "tosino", "karneng baboy", "inasnan", "kurado", "asin", "asukal", "preserba", "pagpepreserba", "pagkaon nga baboy", "cured pork", "salt", "sugar", "preserve", "gipreserba", "gitumog", "baboy"], "fact": {"tl": "Ang tocino ay karneng baboy na binabad sa asin at asukal upang ma-preserba at hindi madaling mapanis.", "en": "Tocino is pork cured by soaking it in salt and sugar, which preserves the meat so it does not spoil quickly.", "bis": "Ang tocino kay karneng baboy nga gitumog sa asin ug asukal aron mapreserba ug dili dali madunot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tokneneng-egg-batter-fry-g4", "domain": "MATTER", "topic": "frying batter-coated egg cooks by heat changing the food", "grades": [3, 4, 5], "terms": ["tokneneng", "kwek-kwek", "itlog", "balot na harina", "pirito", "prito", "iniprito", "mainit na mantika", "gipritos", "batter", "fried egg", "harina", "orange", "itlog", "mantika", "luto"], "fact": {"tl": "Ang tokneneng ay itlog na binalot sa harinang may kulay-orange at iprinito sa mainit na mantika hanggang tumigas at lumutong ang balot.", "en": "Tokneneng is an egg coated in orange batter and fried in hot oil until the coating becomes firm and crisp.", "bis": "Ang tokneneng kay itlog nga giputos sa orange nga harina ug gipritos sa init nga mantika hangtod motig-a ug morupok ang putos."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ukulele-sound-vibration-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "plucked strings vibrate to make sound", "grades": [3, 4, 5], "terms": ["ukulele", "kudyapi", "gitara", "kuwerdas", "kuwordas", "kalabit", "tunog", "vibrasyon", "nanginginig", "tugtog", "string", "vibrate", "sound", "nagkurog", "honi", "tingog", "kuwerdas"], "fact": {"tl": "Kapag kinakalabit ang mga kuwerdas ng ukulele, nanginginig ang mga ito at gumagawa ng tunog na pinalalakas ng guwang na katawan nito.", "en": "When the ukulele's strings are plucked, they vibrate and make sound that the hollow body makes louder.", "bis": "Kon kalabiton ang mga kuwerdas sa ukulele, magkurog kini ug mohimo og tingog nga gipalanog sa bakante nga lawas niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "trompo-spinning-top-rotation-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "a spinning top stays upright while it rotates fast", "grades": [4, 5, 6], "terms": ["trompo", "trumpo", "turumpo", "kasing", "umiikot", "pag-ikot", "umiinog", "ikot", "lubid", "spinning top", "spin", "rotate", "balanse", "nagtuyok", "tuyok", "matumba"], "fact": {"tl": "Ang trompo ay nananatiling nakatayo habang mabilis itong umiikot, ngunit babagsak ito kapag bumagal na ang pag-ikot.", "en": "A spinning top stays standing while it spins fast, but it topples once the spinning slows down.", "bis": "Ang trompo magpabiling nagtindog samtang paspas kining nagtuyok, apan matumba kini kon mohinay na ang tuyok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "trompo-string-stored-energy-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "winding and pulling a string transfers energy to spin a top", "grades": [5, 6, 7], "terms": ["trumpo", "trompo", "lubid", "ikid", "pag-ikid", "binalot na lubid", "hila", "enerhiya", "puwersa", "string winding", "pull", "energy", "pisi", "giputos nga pisi", "kusog", "pagbira"], "fact": {"tl": "Kapag iniikid ang lubid sa trompo at saka inihagis, ang puwersa ng paghila sa lubid ang nagbibigay ng enerhiya para umikot ito.", "en": "When the string is wound around a top and then thrown, the pull of the unwinding string gives it the energy to spin.", "bis": "Kon iputos ang pisi sa trompo dayon ilabay, ang kusog sa pagbira sa pisi maoy mohatag og enerhiya aron motuyok kini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tug-of-war-opposing-force-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "tug of war shows opposing forces and which side wins", "grades": [4, 5, 6], "terms": ["tug of war", "batuhan lubid", "hilahan", "hila", "lubid", "puwersa", "magkasalungat", "magkabilang panig", "pull", "force", "rope", "kalaban", "magkasumpaki nga kusog", "birahay", "pisi", "kusog"], "fact": {"tl": "Sa tug-of-war, naghihila ang dalawang pangkat sa magkabilang dulo ng lubid, at nanalo ang panig na mas malakas ang puwersa ng paghila.", "en": "In tug-of-war, two teams pull on opposite ends of a rope, and the side with the stronger pulling force wins.", "bis": "Sa tug-of-war, duha ka grupo ang nagbira sa magkabilang tumoy sa pisi, ug magdaog ang kilid nga mas kusgan ang bira."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tumbang-preso-can-strike-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "a thrown slipper transfers force to knock down a can", "grades": [4, 5, 6], "terms": ["tumbang preso", "lata", "tsinelas", "pukol", "hagis", "pagtumba", "natumba", "puwersa", "banggaan", "throw", "can", "slipper", "force", "impact", "naigo", "gilabay", "kusog"], "fact": {"tl": "Sa tumbang preso, ang itinapong tsinelas ay naglilipat ng puwersa sa lata kaya ito natutumba kapag tinamaan.", "en": "In tumbang preso, the thrown slipper transfers force to the can so the can falls over when it is hit.", "bis": "Sa tumbang preso, ang gilabay nga tsinelas mobalhin og kusog ngadto sa lata maong matumba kini kon maigo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "turon-saba-banana-roll-g4", "domain": "LIVING_THINGS", "topic": "turon is fried saba banana, a starchy cooking banana", "grades": [3, 4, 5], "terms": ["turon", "saba", "saging", "lumpia", "balot", "pinirito", "prito", "asukal", "starch", "saba banana", "fried", "kanela", "saging nga saba", "gipritos", "tam-is", "lutoon"], "fact": {"tl": "Ang turon ay saging na saba na binalot sa manipis na balat ng lumpia at iprinito, at ang saba ay isang uri ng saging na panluto.", "en": "Turon is saba banana wrapped in a thin lumpia sheet and fried, and saba is a starchy type of banana used for cooking.", "bis": "Ang turon kay saging nga saba nga giputos sa nipis nga lumpia ug gipritos, ug ang saba usa ka matang sa saging nga lutoon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "turones-de-casuy-cashew-seed-g5", "domain": "LIVING_THINGS", "topic": "turrones de casuy is made from cashew, the seed of a fruit", "grades": [4, 5, 6], "terms": ["turones de casuy", "turrones de casuy", "kasuy", "cashew", "buto", "binhi", "prutas", "kendi", "nut", "seed", "Pampanga", "kasoy", "liso", "prutas nga kasuy", "tam-is"], "fact": {"tl": "Ang turones de casuy ay matamis na gawa sa kasuy, na ang kinakain ay buto ng prutas na tumutubo sa labas ng laman nito.", "en": "Turrones de casuy is a sweet made from cashew, the seed of a fruit that grows on the outside of the fleshy part.", "bis": "Ang turones de casuy usa ka tam-is nga hinimo sa kasuy, ang liso sa prutas nga motubo sa gawas sa unod niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ube-purple-yam-tuber-g4", "domain": "LIVING_THINGS", "topic": "ube is a purple yam tuber that grows underground", "grades": [3, 4, 5], "terms": ["ube", "ubi", "purple yam", "lila", "ugat", "tuber", "sa ilalim ng lupa", "halaman", "kamote", "yam", "underground", "violet", "ilalom sa yuta", "gamot", "tanom", "lila nga ubi"], "fact": {"tl": "Ang ube na nagbibigay-kulay-lila sa hopia at pandesal ay isang tuber o malaking ugat na tumutubo sa ilalim ng lupa.", "en": "The ube that colors hopia and pandesal purple is a tuber, a large swollen root that grows underground.", "bis": "Ang ube nga naghatag og kolor nga lila sa hopia ug pandesal usa ka tuber, dako nga gamot nga motubo ilalom sa yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "vinta-sail-wind-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "a vinta uses its sail to catch wind for power", "grades": [4, 5, 6], "terms": ["vinta", "bangka", "layag", "hangin", "naglalayag", "Mindanao", "Sulu", "kulay-kulay na layag", "sail", "wind", "boat", "naglawig", "mabulokon nga layag", "sakayan", "molawig"], "fact": {"tl": "Ang vinta ay tradisyonal na bangka sa Mindanao na ginagamit ang makukulay nitong layag para salohin ang hangin at makausad sa tubig.", "en": "The vinta is a traditional Mindanao boat that uses its colorful sail to catch the wind and move across the water.", "bis": "Ang vinta usa ka tradisyonal nga sakayan sa Mindanao nga mogamit sa mabulokon niini nga layag aron sakpon ang hangin ug molihok sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "torogan-stilt-house-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "torogan is a wooden house raised on posts for support", "grades": [4, 5, 6], "terms": ["torogan", "Maranao", "bahay", "haligi", "poste", "kahoy", "nakaangat", "Lanao", "okir", "royal house", "stilt", "post", "wood", "balay", "haligi", "gisuportahan", "gipataas"], "fact": {"tl": "Ang torogan ay malaking bahay ng mga Maranao na nakapatong sa malalaking haliging kahoy upang iangat ito mula sa lupa.", "en": "The torogan is a large Maranao house resting on big wooden posts that raise it up off the ground.", "bis": "Ang torogan usa ka dako nga balay sa mga Maranao nga gisuportahan sa dagkong haligi nga kahoy aron ipataas kini gikan sa yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "traffic-light-colors-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "traffic light colors signal stop, ready, and go", "grades": [3, 4, 5], "terms": ["traffic light", "ilaw sa kalsada", "pula", "berde", "dilaw", "hinto", "tumawid", "humayo", "senyales", "red", "green", "yellow", "stop", "go", "suga sa dalan", "luntian", "dalag"], "fact": {"tl": "Sa traffic light, ang pula ay senyales na huminto, ang dilaw ay maghanda, at ang berde ay puwede nang umusad.", "en": "On a traffic light, red signals stop, yellow means get ready, and green means it is safe to go.", "bis": "Sa traffic light, ang pula nagpasabot og hunong, ang dalag pangandam, ug ang berde mahimo nang molihok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "candle-combustion-g5", "domain": "MATTER", "topic": "a burning candle melts wax and uses it as fuel", "grades": [4, 5, 6], "terms": ["kandila", "undas", "apoy", "ningas", "kandilang nasusunog", "natutunaw", "mitsa", "pagkasunog", "candle", "flame", "wax", "burn", "fuel", "natunaw", "siga", "kalayo", "gatong"], "fact": {"tl": "Kapag nagniningas ang kandila tuwing Undas, tinutunaw ng apoy ang kandilang waks na siyang nagsisilbing gatong para magpatuloy ang ningas.", "en": "When a candle burns during Undas, the flame melts the wax, which acts as the fuel that keeps the flame going.", "bis": "Kon mosiga ang kandila panahon sa Undas, ang kalayo motunaw sa waks nga maoy gatong aron magpadayon ang siga."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tongs-lever-tool-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "tongs are a tool that grips by acting like a lever", "grades": [3, 4, 5], "terms": ["tongs", "sipit", "kimpit", "panghawak", "mainit na pagkain", "hawak", "lever", "grip", "tool", "kimpit", "panakop", "kompang", "gamit", "gunitan", "galamiton"], "fact": {"tl": "Ang tongs o sipit ay kasangkapang ginagamit para hawakan ang mainit na bagay nang hindi tinatamaan ng kamay, gamit ang dalawang braso nitong nagsisipit.", "en": "Tongs are a tool used to grip hot objects without touching them with your hand, using two arms that pinch together.", "bis": "Ang tongs o sipit usa ka galamiton nga gamiton aron kuptan ang init nga butang nga dili masuod sa kamot, pinaagi sa duha ka bukton nga mokumpang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tongatong-bamboo-instrument-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "stamping bamboo tubes make sound by vibrating air", "grades": [3, 4, 5], "terms": ["tongatong", "kawayan", "bamboo", "tubo", "pinupukpok", "stamping", "tunog", "hangin", "Kalinga", "bamboo tube", "sound", "honi", "tubo nga kawayan", "tingog", "itamtam"], "fact": {"tl": "Ang tongatong ay mga tubong kawayan na pinupukpok sa lupa, at ang pagkayanig ng hangin sa loob ng tubo ang gumagawa ng tunog.", "en": "The tongatong is a set of bamboo tubes stamped on the ground, and the air shaking inside each tube makes the sound.", "bis": "Ang tongatong kay mga tubo nga kawayan nga itamtam sa yuta, ug ang pagkurog sa hangin sulod sa tubo maoy mohimo og tingog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ube-cheese-pandesal-yeast-g6", "domain": "LIVING_THINGS", "topic": "yeast makes bread dough rise by producing gas", "grades": [5, 6, 7], "terms": ["pandesal", "ube cheese pandesal", "lebadura", "yeast", "tinapay", "umaalsa", "masa", "gas", "bula", "rise", "dough", "bread", "mosaka", "mopalobo", "tinapay", "harina"], "fact": {"tl": "Ang malambot na pandesal ay umaalsa dahil sa lebadura, isang maliit na organismo na gumagawa ng gas na nagpapalobo sa masa.", "en": "Soft pandesal rises because of yeast, a tiny living organism that makes gas which puffs up the dough.", "bis": "Ang humok nga pandesal mosaka tungod sa lebadura, gamay nga buhing organismo nga mohimo og gas nga mopalobo sa masa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "volleyball-ball-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "pushing a ball makes it move", "grades": [3, 4], "terms": ["volleyball", "bola", "tampok", "sipa", "tira", "sumayad", "pwersa", "puwersa", "kusog", "itira", "igo", "push", "hit", "force", "moves"], "fact": {"tl": "Kapag tinira mo ang volleyball, ang pwersa ng iyong kamay ang nagpapagalaw at nagpapalipad nito sa hangin.", "en": "When you hit a volleyball, the force from your hand makes it move and fly through the air.", "bis": "Kon imong tamparuson ang volleyball, ang kusog sa imong kamot maoy makapalihok ug makapalupad niini sa hangin."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "walis-tambo-soft-broom-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "friction sweeps dust away", "grades": [3, 4], "terms": ["walis tambo", "walis", "tambo", "silhig", "panilhig", "alikabok", "abog", "hilod", "kiskis", "friksyon", "pwersa", "broom", "sweep", "friction", "dust"], "fact": {"tl": "Ang walis tambo ay gawa sa malambot na tangkay ng damong tambo, at ang pagkiskis nito sa sahig ang humihila sa alikabok palabas.", "en": "The walis tambo is made from the soft stalks of tiger-grass, and rubbing it against the floor drags the dust away.", "bis": "Ang walis tambo hinimo gikan sa humok nga mga tukog sa tambo nga sagbot, ug ang paghilod niini sa salog maoy mokuha sa abog."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wall-calendar-grid-g4", "domain": "EARTH_SPACE", "topic": "calendar tracks days and months", "grades": [3, 4, 5], "terms": ["calendar", "kalendaryo", "petsa", "araw", "buwan", "taon", "adlaw", "bulan", "tuig", "linggo", "semana", "days", "months", "year", "Earth orbit"], "fact": {"tl": "Ang kalendaryo ay naghahati ng panahon sa mga araw, linggo, at buwan, at ang isang taon ay umaabot ng halos 365 araw—ang tagal ng isang pag-ikot ng Mundo sa Araw.", "en": "A calendar divides time into days, weeks, and months, and one year is about 365 days—the time Earth takes to orbit the Sun.", "bis": "Ang kalendaryo nagbahin sa panahon ngadto sa mga adlaw, semana, ug bulan, ug ang usa ka tuig mga 365 ka adlaw—ang gidugayon sa pag-libot sa Kalibotan sa Adlaw."}, "source": "NRC ESS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "warm-up-stretches-g5", "domain": "LIVING_THINGS", "topic": "warming up prepares muscles", "grades": [4, 5, 6], "terms": ["warm-up", "warm up", "pag-iinit", "stretching", "pag-uunat", "kalamnan", "kaunoran", "muscle", "ugat", "pagbanat", "ehersisyo", "tul-id", "stretch", "muscles", "injury"], "fact": {"tl": "Ang warm-up at pag-uunat bago mag-ehersisyo ay nagpapainit at nagpapalambot sa iyong mga kalamnan upang hindi sila madaling mapinsala.", "en": "Warming up and stretching before exercise warms and loosens your muscles so they are less likely to get hurt.", "bis": "Ang warm-up ug pag-inat sa dili pa mag-ehersisyo magpainit ug magpahumok sa imong mga kaunoran aron dili sila dali masamaran."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wearing-helmet-bike-safety-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "helmet absorbs impact force", "grades": [3, 4, 5], "terms": ["helmet", "bisikleta", "bike", "kaligtasan", "kaluwasan", "ulo", "bangga", "umpog", "pwersa", "proteksyon", "pangarda", "safety", "head", "impact", "force"], "fact": {"tl": "Ang helmet ay nagpoprotekta sa iyong ulo kapag nabangga ka sa bisikleta dahil sinisipsip ng malambot nitong palaman ang pwersa ng banggaan para hindi tumama nang diretso sa iyong bungo.", "en": "A helmet protects your head in a bike crash because its padding absorbs the force of the impact instead of letting it hit your skull directly.", "bis": "Ang helmet manalipod sa imong ulo kon mahagba ka sa bisikleta tungod kay ang humok nga palaman niini mosuyop sa kusog sa pagbangga aron dili kini direktang motuhop sa imong bagolbagol."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "yakan-weaving-color-bands-g5", "domain": "MATTER", "topic": "weaving threads into cloth", "grades": [4, 5, 6], "terms": ["Yakan", "weaving", "paghahabi", "habi", "tela", "sinulid", "kulay", "telar", "panapton", "paglara", "hilo", "kolor", "Basilan", "cloth", "thread", "loom", "color"], "fact": {"tl": "Ang Yakan na paghahabi mula sa Basilan ay gumagawa ng makukulay na tela sa pamamagitan ng pagsasalit-salit ng mga sinulid sa isang telar.", "en": "Yakan weaving from Basilan makes brightly colored cloth by interlacing threads back and forth on a loom.", "bis": "Ang Yakan nga paghablon gikan sa Basilan maghimo og mabulokon nga panapton pinaagi sa pagsabod-sabod sa mga lugas sa hilo diha sa usa ka habolanan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "yema-custard-candy-g5", "domain": "MATTER", "topic": "heating changes a mixture", "grades": [4, 5, 6], "terms": ["yema", "kendi", "kendy", "gatas", "itlog", "asukal", "luto", "init", "lapot", "candy", "milk", "egg yolk", "sugar", "heat", "thickens", "pagkain"], "fact": {"tl": "Ang yema ay gawa sa gatas, pula ng itlog, at asukal na iniluluto hanggang lumapot, kaya ang init ang nagbabago ng likidong timpla tungo sa malagkit na kendi.", "en": "Yema is made from milk, egg yolk, and sugar cooked until thick, so heat changes the runny mixture into a chewy candy.", "bis": "Ang yema hinimo gikan sa gatas, pula sa itlog, ug asukal nga giluto hangtod molapot, busa ang init mao ang mag-usab sa tubigon nga sagol ngadto sa pilit nga kendi."}, "source": "NRC PS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "yoyo-trick-walk-the-dog-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "spinning yoyo and gravity", "grades": [4, 5, 6], "terms": ["yoyo", "yo-yo", "tali", "umiikot", "pag-ikot", "grabidad", "gravity", "spin", "tuyok", "lubid", "spinning", "string", "energy"], "fact": {"tl": "Ang yoyo ay bumababa dahil sa grabidad, at habang umiikot ito sa dulo ng tali, ang pag-ikot na iyon ang nagbibigay-daan sa mga trick tulad ng 'walk the dog.'", "en": "A yoyo drops because of gravity, and as it spins at the end of the string, that spinning lets it do tricks like 'walk the dog.'", "bis": "Ang yoyo monaog tungod sa grabidad, ug samtang nagtuyok kini sa tumoy sa lubid, kana nga pagtuyok maoy makahimo sa mga trick sama sa 'walk the dog.'"}, "source": "NRC PS2.A, PS2.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "abaniko-fan-cooling-self-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "moving air cools the skin", "grades": [3, 4, 5], "terms": ["abaniko", "pamaypay", "fan", "hangin", "ihip", "ihangin", "init", "pawis", "lamig", "presko", "balhibo", "panghangin", "air", "breeze", "cool", "sweat", "evaporation"], "fact": {"tl": "Kapag pinaypay mo ang abaniko, ang gumagalaw na hangin ay nagpapabilis ng pagsingaw ng pawis sa balat, kaya nakakaramdam ka ng lamig.", "en": "When you wave an abaniko fan, the moving air speeds up the evaporation of sweat on your skin, so you feel cooler.", "bis": "Kon imong ipaypay ang abaniko, ang naglihok nga hangin magpaspas sa pag-alisngaw sa singot sa imong panit, busa mobati ka og kabugnaw."}, "source": "NRC PS3.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "balance-scale-stones-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "balance scale compares mass", "grades": [3, 4, 5], "terms": ["balance scale", "timbangan", "timbang", "bato", "bigat", "pantay", "patas", "masa", "kabug-aton", "timbangon", "scale", "mass", "weight", "balance", "heavier"], "fact": {"tl": "Ang timbangang balanse ay naghahambing ng bigat: ang panig na may mas mabigat na bagay ay bababa, at kapag pantay ang bigat, magiging patas ang dalawang panig.", "en": "A balance scale compares weight: the side holding the heavier object dips down, and when the weights are equal the two sides stay level.", "bis": "Ang timbangan nga balanse magtandi sa kabug-aton: ang kilid nga may mas bug-at nga butang monaog, ug kon parehas ang gibug-aton, magpatas ang duha ka kilid."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "balloon-rub-stick-wall-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "static electricity attraction", "grades": [4, 5, 6], "terms": ["balloon", "lobo", "kiskis", "hilod", "static electricity", "kuryente", "elektrisidad", "dingding", "bungbong", "buhok", "nakadikit", "static", "rub", "charge", "wall", "attract"], "fact": {"tl": "Kapag kiniskis mo ang lobo sa iyong buhok, nagkakaroon ito ng static electricity na nagpapadikit nito sa dingding.", "en": "When you rub a balloon on your hair, it gains static electricity that makes it stick to a wall.", "bis": "Kon imong ihilod ang lobo sa imong buhok, makabaton kini og static electricity nga maoy makapadikit niini sa bungbong."}, "source": "NRC PS2.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "banca-balancing-stand-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "outrigger keeps boat stable", "grades": [4, 5, 6], "terms": ["banca", "bangka", "katig", "outrigger", "balanse", "timbang", "tumba", "taob", "stability", "dagat", "bangkang may katig", "boat", "balance", "tip over", "float"], "fact": {"tl": "Ang katig sa gilid ng bangka ay nagpapalawak ng base nito sa tubig, kaya hindi ito madaling tumaob kahit may alon.", "en": "The outrigger on the side of a banca widens its base on the water, so it does not tip over easily even in waves.", "bis": "Ang katig sa kilid sa bangka magpalapad sa sukaranan niini sa tubig, busa dili kini dali matumba bisan adunay balod."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "banca-paddle-push-water-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "paddling and reaction force", "grades": [4, 5, 6], "terms": ["banca", "bangka", "sagwan", "bugsay", "tulak", "itulak", "tubig", "atras", "reaksyon", "pwersa", "paddle", "push", "water", "forward", "reaction force"], "fact": {"tl": "Kapag itinutulak ng sagwan ang tubig paatras, ang tubig naman ay tumutulak sa bangka pasulong—ganito gumagalaw ang bangka.", "en": "When a paddle pushes water backward, the water pushes the banca forward in return—that is how the boat moves.", "bis": "Kon ang bugsay magtulod sa tubig paatras, ang tubig motulod usab sa bangka pasulong—mao kini ang paglihok sa bangka."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bell-vibration-sound-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "vibration makes sound", "grades": [3, 4, 5], "terms": ["bell", "kampana", "kampanilya", "tunog", "tugtog", "bagting", "yanig", "vibration", "vibrate", "metal", "ringing", "sound", "tingog", "uyog"], "fact": {"tl": "Kapag tumama ang batingaw sa loob ng kampana, nayayanig ang metal nito, at ang pagyanig na iyon ang gumagawa ng tunog.", "en": "When the clapper strikes the inside of a bell, the metal vibrates, and that vibration is what makes the sound.", "bis": "Kon ang dila sa kampana mosagpa sa sulod niini, ang metal mouyog, ug kana nga pag-uyog maoy maghimo sa tingog."}, "source": "NRC PS4.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bike-downhill-acceleration-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "gravity speeds a bike downhill", "grades": [5, 6, 7], "terms": ["bike", "bisikleta", "paliko", "paibaba", "lusong", "bilis", "tulin", "grabidad", "gravity", "acceleration", "downhill", "bumibilis", "kusog", "kalsada", "speed up", "slope"], "fact": {"tl": "Kapag bumababa ang bisikleta sa dalisdis, hinihila ito ng grabidad pababa kaya patuloy itong bumibilis kahit hindi ka magpedal.", "en": "When a bike goes down a hill, gravity pulls it downward so it keeps speeding up even without pedaling.", "bis": "Kon ang bisikleta monaog sa bakilid, ang grabidad mobira niini paubos busa magpadayon kini sa pagpaspas bisan dili ka magpedal."}, "source": "NRC PS2.A, PS2.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "black-white-shirt-sun-heat-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "dark colors absorb more heat", "grades": [4, 5, 6], "terms": ["black shirt", "white shirt", "itim", "puti", "damit", "sando", "init", "sikat ng araw", "sumisipsip", "absorb", "kainit", "kolor", "color", "heat", "sunlight", "reflect"], "fact": {"tl": "Ang itim na damit ay sumisipsip ng mas maraming init mula sa araw kaysa puti, kaya mas mainit ang pakiramdam kapag nakaitim ka sa labas.", "en": "A black shirt absorbs more heat from the sun than a white one, so you feel hotter wearing dark colors outdoors.", "bis": "Ang itom nga sapot mosuyop og mas daghang init gikan sa adlaw kay sa puti, busa mas init ang imong bati kon magsul-ob ka og itom sa gawas."}, "source": "NRC PS3.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "boiling-pot-convection-loop-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "convection circulates hot water", "grades": [5, 6, 7], "terms": ["boiling", "kumukulo", "nagbubukal", "kaldero", "kawa", "tubig", "init", "convection", "umaakyat", "bumababa", "init na tubig", "pagligid", "convection current", "boiling water", "rises", "circulate"], "fact": {"tl": "Sa kumukulong tubig, ang mainit na tubig sa ilalim ay umaakyat at ang malamig ay bumababa, na bumubuo ng paikot na galaw na tinatawag na convection.", "en": "In a boiling pot, hot water at the bottom rises while cooler water sinks, forming a circular flow called convection.", "bis": "Sa nagbukal nga kaldero, ang init nga tubig sa ilawom mosaka samtang ang bugnaw monaog, nga maghimo og lingin nga agos nga gitawag og convection."}, "source": "NRC PS3.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bottle-cap-opener-lever-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "bottle opener is a lever", "grades": [4, 5, 6], "terms": ["bottle opener", "pambukas ng bote", "abrelata", "takip", "tansan", "lever", "palanca", "tuod", "fulcrum", "pwersa", "buksan", "bote", "cap", "pry"], "fact": {"tl": "Ang pambukas ng bote ay isang palanca: gumagamit ito ng tuod (fulcrum) sa gilid ng takip para mas madaling itaas at matanggal ang tansan gamit ang maliit na pwersa.", "en": "A bottle opener is a lever: it uses a fulcrum at the edge of the cap so a small force can pry the cap off easily.", "bis": "Ang pang-abli sa botelya usa ka palanca: mogamit kini og tuod (fulcrum) sa kilid sa takup aron ang gamay nga kusog makahaw-as sa takup dali ra."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bowling-ball-pins-knock-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "moving object transfers energy", "grades": [3, 4, 5], "terms": ["bowling", "bola", "pins", "pino", "tumama", "banggaan", "tumba", "pwersa", "enerhiya", "energy", "knock down", "transfer", "moving", "natumba", "collision"], "fact": {"tl": "Kapag gumulong ang mabigat na bowling ball at tumama sa mga pin, naililipat nito ang enerhiya ng galaw kaya natutumba ang mga pin.", "en": "When a heavy bowling ball rolls and hits the pins, it transfers its energy of motion to them, so the pins fall over.", "bis": "Kon ang bug-at nga bowling ball moligid ug mobangga sa mga pin, mabalhin niini ang kusog sa paglihok ngadto kanila, busa matumba ang mga pin."}, "source": "NRC PS3.A, PS3.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bucket-spin-water-stays-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "circular motion holds water in", "grades": [6, 7, 8], "terms": ["bucket", "timba", "balde", "umiikot", "tuyok", "tubig", "hindi tumatagas", "circular motion", "gravity", "grabidad", "spinning", "water stays", "centripetal", "pag-ikot"], "fact": {"tl": "Kapag mabilis mong iniikot ang timba na may tubig nang pabilog, hindi natatapon ang tubig dahil ang patuloy na pag-ikot ay itinutulak ito laban sa ilalim ng timba.", "en": "When you spin a bucket of water fast in a circle, the water does not spill because the constant circular motion keeps pressing it against the bottom of the bucket.", "bis": "Kon imong tuyokon paspas ang timba nga may tubig sa lingin, dili mayabo ang tubig tungod kay ang padayon nga pagtuyok mag-ipit niini batok sa ilawom sa timba."}, "source": "NRC PS2.A, PS2.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "can-opener-compound-machine-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "can opener combines simple machines", "grades": [5, 6, 7], "terms": ["can opener", "abrelata", "pambukas ng lata", "lata", "compound machine", "simpleng makina", "gulong", "wheel and axle", "lever", "wedge", "kalang", "simple machines", "combine"], "fact": {"tl": "Ang abrelata ay isang compound machine dahil pinagsasama nito ang ilang simpleng makina—palanca, gulong-at-aksis, at wedge—upang mas madaling mabuksan ang lata.", "en": "A can opener is a compound machine because it combines several simple machines—a lever, a wheel-and-axle, and a wedge—to open a can more easily.", "bis": "Ang abrelata usa ka compound machine tungod kay gihiusa niini ang pipila ka yano nga makina—palanca, ligid-ug-aksis, ug wedge—aron mas sayon ablihan ang lata."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "can-opener-wedge-rim-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "wedge cuts through can lid", "grades": [4, 5, 6], "terms": ["can opener", "abrelata", "wedge", "kalang", "talim", "lata", "gilid", "rim", "putol", "hiwa", "matalim", "blade", "cut", "metal lid", "sharp"], "fact": {"tl": "Ang matalim na gulong ng abrelata ay isang wedge na pumipindot at pumuputol sa manipis na metal sa gilid ng lata habang iniikot mo ito.", "en": "The sharp wheel of a can opener is a wedge that presses and cuts through the thin metal at the rim of the can as you turn it.", "bis": "Ang hait nga ligid sa abrelata usa ka wedge nga mag-ipit ug moputol sa nipis nga metal sa ngilit sa lata samtang imong ginatuyok kini."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "candle-over-spoon-soot-g6", "domain": "MATTER", "topic": "incomplete burning makes soot", "grades": [5, 6, 7], "terms": ["candle", "kandila", "kulimlim", "uling", "soot", "itim", "kuyumos", "apoy", "ningas", "carbon", "burning", "flame", "spoon", "agiw", "incomplete combustion"], "fact": {"tl": "Kapag hinawakan mo ang malamig na kutsara sa ibabaw ng apoy ng kandila, naiiwan dito ang itim na uling (soot) na bunga ng hindi ganap na pagkasunog.", "en": "When you hold a cool spoon above a candle flame, black soot collects on it because the flame is not burning completely.", "bis": "Kon imong ibutang ang bugnaw nga kutsara ibabaw sa siga sa kandila, motapot niini ang itom nga agiw (soot) tungod kay ang siga wala mosunog og hingpit."}, "source": "NRC PS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "carabao-pulling-plow-friction-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "carabao pulls plow against friction", "grades": [4, 5, 6], "terms": ["carabao", "kalabaw", "araro", "plow", "hila", "hatak", "lupa", "bukid", "friction", "friksyon", "pwersa", "pagbungkal", "uma", "plowing", "pull", "soil", "force"], "fact": {"tl": "Ang kalabaw ay humihila ng araro sa pamamagitan ng malakas na pwersa para malampasan ang friction ng siksik na lupa, kaya nababungkal ang bukid.", "en": "A carabao pulls a plow with a strong force to overcome the friction of the packed soil, which turns over the field.", "bis": "Ang kalabaw mobira sa daro pinaagi sa kusgan nga pwersa aron mabuntog ang friksyon sa gahi nga yuta, busa nabungkal ang uma."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cave-echo-shout-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "echo is reflected sound", "grades": [4, 5, 6], "terms": ["cave", "kweba", "yungib", "langub", "echo", "alingawngaw", "alunignig", "sigaw", "tunog", "tumalbog", "reflected sound", "shout", "bounce", "sound", "tingog", "balik"], "fact": {"tl": "Ang alingawngaw sa loob ng kweba ay nangyayari kapag tumalbog ang tunog ng iyong sigaw sa matigas na pader ng bato at bumalik sa iyong tainga.", "en": "An echo in a cave happens when the sound of your shout bounces off the hard rock walls and comes back to your ears.", "bis": "Ang alingawngaw sa sulod sa langub mahitabo kon ang tingog sa imong singgit motalbog sa gahi nga bato nga bungbong ug mobalik sa imong dalunggan."}, "source": "NRC PS4.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "church-bell-ringing-tower-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "sound travels through air far", "grades": [3, 4, 5], "terms": ["church bell", "kampana", "simbahan", "kampanaryo", "bell tower", "tunog", "tugtog", "bagting", "lumalayo", "hangin", "tingog", "sound travels", "air", "far", "ringing"], "fact": {"tl": "Kapag tumutugtog ang kampana sa kampanaryo, kumakalat ang tunog sa hangin paalis sa lahat ng direksyon kaya naririnig ito kahit sa malayo.", "en": "When a church bell rings in its tower, the sound spreads through the air in all directions, so people can hear it even from far away.", "bis": "Kon ang kampana sa kampanaryo motingog, mokatag ang tingog sa hangin sa tanang direksyon busa madungog kini bisan sa layo."}, "source": "NRC PS4.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "circuit-breaker-panel-home-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "circuit breaker stops overload", "grades": [6, 7, 8], "terms": ["circuit breaker", "breaker", "kuryente", "elektrisidad", "kurdon", "overload", "putol", "patay", "safety", "panel", "sobrang kuryente", "electricity", "current", "trips", "overheat", "switch off"], "fact": {"tl": "Ang circuit breaker sa bahay ay awtomatikong pumuputol ng daloy ng kuryente kapag sobra-sobra ito, upang maiwasan ang init na maaaring magdulot ng sunog.", "en": "A circuit breaker in a home automatically cuts off the flow of electricity when too much current flows, to prevent overheating that could start a fire.", "bis": "Ang circuit breaker sa balay awtomatikong moputol sa agos sa kuryente kon sobra na kini, aron malikayan ang kainit nga makahatag og sunog."}, "source": "NRC PS3.A, PS3.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "circuit-incomplete-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "incomplete electric circuit", "grades": [4, 5, 6], "terms": ["circuito", "kuryente", "bombilya", "ilaw", "bukas na circuito", "hindi kumpleto", "sirkito", "wala nagdan", "dili kompleto", "suga", "incomplete circuit", "open circuit", "bulb", "electricity", "broken wire", "does not light"], "fact": {"tl": "Kapag may putol o bukas na bahagi sa isang circuito, hindi makakadaloy ang kuryente kaya hindi magliliwanag ang bombilya.", "en": "When part of a circuit is broken or open, electricity cannot flow through it, so the bulb will not light.", "bis": "Kung adunay nabugto o bukas nga bahin sa circuito, dili makaagi ang kuryente busa dili mosiga ang bombilya."}, "source": "AAAS Benchmarks 4G; DepEd G5 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "clay-jar-evaporative-cooling-g6", "domain": "MATTER", "topic": "evaporative cooling in clay pots", "grades": [5, 6, 7], "terms": ["palayok", "banga", "luwad", "tubig", "lumalamig", "pagsingaw", "evaporative cooling", "init", "naglagiti", "naglamig", "clay jar", "earthenware pot", "evaporation", "cooling water", "porous"], "fact": {"tl": "Ang tubig sa banga ay lumalamig dahil ang kaunting tubig na sumisingaw sa butas-butas na luwad ay nagdadala ng init palabas.", "en": "Water in a clay jar stays cool because a little water evaporates through the porous clay and carries heat away.", "bis": "Ang tubig sa banga magpabilin nga bugnaw kay ang gamay nga tubig nga moalisngaw sa lungag-lungag nga luwad magdala sa kainit pagawas."}, "source": "encyclopedia-stable consensus; NRC PS3", "generator": "claude-workflow", "reviewed": false},
  {"id": "coconut-bolo-wedge-split-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "wedge simple machine", "grades": [4, 5, 6], "terms": ["niyog", "buko", "itak", "bolo", "wedge", "kalang", "biyak", "hiwa", "simpleng makina", "lubi", "sundang", "buwagon", "gigaba", "coconut", "machete", "splitting", "simple machine", "sharp edge"], "fact": {"tl": "Ang matalas na talim ng itak ay isang wedge na nagbabago ng lakas ng hampas para mabiyak ang matigas na bao ng niyog.", "en": "The sharp blade of a bolo is a wedge that turns the force of a chop into a splitting push that cracks open a hard coconut.", "bis": "Ang hait nga sulab sa sundang usa ka wedge nga nagbag-o sa kusog sa tigbas aron mabuak ang gahi nga bagol sa lubi."}, "source": "AAAS Benchmarks 8B; DepEd G5 simple machines", "generator": "claude-workflow", "reviewed": false},
  {"id": "comb-static-attract-hair-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "static electricity", "grades": [4, 5, 6], "terms": ["suklay", "buhok", "static", "kuryenteng static", "kuskos", "hinihila", "naghihila", "charge", "sudlay", "gikuskos", "static electricity", "comb", "hair", "rubbing", "attract", "electric charge"], "fact": {"tl": "Kapag kinuskos mo ang suklay sa buhok, nagkakaroon ito ng static na kuryente kaya nahihila nito ang maliliit na piraso ng papel o ang mismong buhok.", "en": "When you rub a comb on your hair, it builds up static electricity, which lets it attract tiny bits of paper or even your hair.", "bis": "Kung imong kuskuson ang sudlay sa imong buhok, makabaton kini ug static nga kuryente maong makadani kini sa gagmay nga papel o sa imong buhok."}, "source": "AAAS Benchmarks 4G; DepEd G5 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "compass-floating-needle-g6", "domain": "EARTH_SPACE", "topic": "magnetic compass", "grades": [5, 6, 7], "terms": ["kompas", "karayom", "magnet", "hilaga", "lumulutang", "magneto", "direksyon", "amihanan", "naglutaw", "magnetic compass", "floating needle", "north", "magnetized needle", "direction", "earth's magnetism"], "fact": {"tl": "Ang isang magnetisadong karayom na nakalutang sa tubig ay umiikot hanggang tumuro ang dulo nito sa hilaga, kaya ito gumagawang tulad ng kompas.", "en": "A magnetized needle floating on water turns until one end points north, so it works like a compass.", "bis": "Ang usa ka magnetisado nga dagom nga naglutaw sa tubig moliko hangtod motultol ang tumoy niini sa amihanan, busa molihok kini sama sa kompas."}, "source": "encyclopedia-stable consensus; AAAS 4G", "generator": "claude-workflow", "reviewed": false},
  {"id": "compressed-spring-toy-pop-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "elastic potential energy in springs", "grades": [4, 5, 6], "terms": ["spring", "bukal", "kuyog", "nakaipit", "naipit", "tumalon", "nagtatago ng enerhiya", "elastic", "resorte", "gipiit", "milukso", "nagtago ug enerhiya", "compressed spring", "pop up toy", "stored energy", "elastic potential energy", "release"], "fact": {"tl": "Ang isang naipit na spring ay nag-iimbak ng enerhiya, at kapag binitawan ito ay biglang umaalsa para mapatalon ang laruan.", "en": "A compressed spring stores energy, and when it is released it springs back suddenly to make a toy pop up.", "bis": "Ang gipiit nga spring magtipig ug enerhiya, ug kung buhian kini kalit nga mobalik aron makalukso ang dulaan."}, "source": "NRC PS3.A; DepEd G6 energy", "generator": "claude-workflow", "reviewed": false},
  {"id": "concave-mirror-spoon-flip-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "concave mirror image", "grades": [5, 6, 7], "terms": ["kutsara", "salamin", "concave", "baligtad", "imahe", "repleksyon", "liko-liko", "kuyukot", "baliktad", "litrato", "concave mirror", "spoon", "upside down", "reflection", "curved mirror", "image"], "fact": {"tl": "Ang loob ng kutsara ay parang concave na salamin, kaya kapag tumingin ka rito ay baligtad ang iyong makikitang anino.", "en": "The inside of a spoon acts like a concave mirror, so your reflection in it appears upside down.", "bis": "Ang sulod sa kutsara molihok sama sa concave nga samin, busa kung motan-aw ka niini, baliktad ang imong makita nga anino."}, "source": "encyclopedia-stable consensus; AAAS 4F", "generator": "claude-workflow", "reviewed": false},
  {"id": "conductor-tester-circuit-objects-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "conductors and insulators", "grades": [4, 5, 6], "terms": ["conductor", "insulator", "metal", "kuryente", "dumadaloy", "subukan", "bakal", "kawad", "tagaagi", "dili tagaagi", "puthaw", "moagi ang kuryente", "circuit tester", "metal objects", "electricity flow"], "fact": {"tl": "Kapag inilagay mo ang isang bagay sa circuito at magliwanag ang ilaw, ito ay conductor na nagpapadaloy ng kuryente tulad ng bakal.", "en": "When you place an object in a circuit and the light turns on, the object is a conductor that lets electricity flow, like metal.", "bis": "Kung ibutang nimo ang usa ka butang sa circuito ug mosiga ang suga, kana usa ka conductor nga magpaagi sa kuryente sama sa puthaw."}, "source": "AAAS Benchmarks 4G; DepEd G5 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "crane-construction-pulley-system-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "pulley simple machine", "grades": [5, 6, 7], "terms": ["crane", "kalo", "pulley", "polea", "mabigat", "iniaangat", "lubid", "konstruksyon", "bug-at", "gibayaw", "pisi", "pulley system", "heavy load", "lifting", "construction", "simple machine"], "fact": {"tl": "Ang crane sa konstruksyon ay gumagamit ng pulley na may lubid upang gawing mas madali ang pag-angat ng napakabigat na mga bagay.", "en": "A construction crane uses a pulley with rope to make lifting very heavy loads much easier.", "bis": "Ang crane sa konstruksyon mogamit ug pulley nga adunay pisi aron mas sayon ang pagbayaw sa hilabihan kabug-at nga mga butang."}, "source": "AAAS Benchmarks 8B; DepEd G5 simple machines", "generator": "claude-workflow", "reviewed": false},
  {"id": "cricket-chirp-night-g4", "domain": "LIVING_THINGS", "topic": "cricket sound production", "grades": [3, 4, 5], "terms": ["kuliglig", "kagang", "huni", "tunog", "gabi", "pakpak", "kiskis", "gabii", "pako", "gikuskos", "cricket", "chirp", "sound", "night", "rubbing wings", "insect"], "fact": {"tl": "Ang kuliglig ay gumagawa ng huni sa gabi sa pamamagitan ng pagkiskis ng kanyang mga pakpak, hindi sa pamamagitan ng bibig.", "en": "A cricket makes its chirping sound at night by rubbing its wings together, not with its mouth.", "bis": "Ang kuliglig magbuhat sa iyang huni panahon sa gabii pinaagi sa pagkuskos sa iyang mga pako, dili pinaagi sa baba."}, "source": "encyclopedia-stable consensus; AAAS 5C", "generator": "claude-workflow", "reviewed": false},
  {"id": "crowbar-prying-crate-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "lever simple machine", "grades": [4, 5, 6], "terms": ["bareta", "palanca", "lever", "kahon", "pinto", "binubuksan", "pingga", "tuhod", "gibungkag", "tukod", "crowbar", "pry bar", "fulcrum", "prying open"], "fact": {"tl": "Ang bareta o crowbar ay isang palanca na gumagamit ng tukod upang dagdagan ang iyong lakas sa pagbukas ng matibay na kahon.", "en": "A crowbar is a lever that uses a pivot point to multiply your force when prying open a sturdy crate.", "bis": "Ang bareta o crowbar usa ka palanca nga mogamit ug tukod aron padaghanon ang imong kusog sa pag-abli sa lig-on nga kahon."}, "source": "AAAS Benchmarks 8B; DepEd G5 simple machines", "generator": "claude-workflow", "reviewed": false},
  {"id": "dark-vs-light-clothing-heat-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "heat absorption by color", "grades": [4, 5, 6], "terms": ["maitim", "maputi", "damit", "init", "sinisipsip", "araw", "kulay", "mainit", "itom", "puti", "sinina", "gisuyop", "dark clothing", "light clothing", "heat absorption", "sunlight", "color", "warmer"], "fact": {"tl": "Ang maitim na damit ay sumisipsip ng mas maraming init mula sa araw kaya mas mainit ito kaysa sa maputing damit.", "en": "Dark clothing absorbs more heat from the sun than light clothing, so it feels warmer.", "bis": "Ang itom nga sinina mosuyop ug mas daghang init gikan sa adlaw kaysa puti nga sinina, busa mas init kini."}, "source": "AAAS Benchmarks 4E; NRC PS3", "generator": "claude-workflow", "reviewed": false},
  {"id": "deep-well-poso-pumping-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "hand pump and air pressure", "grades": [4, 5, 6], "terms": ["poso", "balon", "bomba", "tubig", "iginiginiik", "presyon ng hangin", "igib", "atabay", "gibomba", "presyur sa hangin", "deep well", "hand pump", "air pressure", "pumping", "suction"], "fact": {"tl": "Sa isang poso, ang pagbomba ng hawakan ay nagbabawas ng hangin sa loob ng tubo kaya ang presyon ng hangin sa labas ang nagtutulak ng tubig pataas.", "en": "In a deep well, pumping the handle removes air inside the pipe, so outside air pressure pushes the water up.", "bis": "Sa poso, ang pagbomba sa kuptanan magkuha sa hangin sulod sa tubo, busa ang presyur sa hangin sa gawas mao ang motulak sa tubig pataas."}, "source": "encyclopedia-stable consensus; AAAS 4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "distance-vs-displacement-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "distance versus displacement", "grades": [7, 8, 9], "terms": ["distansya", "displacement", "layo", "kabuuang nilakbay", "tuwid na linya", "direksyon", "gilay-on", "gilay-on nga gilaktan", "distance", "total path", "straight line", "direction", "start to end"], "fact": {"tl": "Ang distansya ay ang kabuuang haba ng nilakbay, samantalang ang displacement ay ang tuwid na layo mula simula hanggang dulo kasama ang direksyon.", "en": "Distance is the total length of the path traveled, while displacement is the straight-line gap from start to finish, including its direction.", "bis": "Ang gilay-on mao ang kinatibuk-ang gitas-on sa gilaktan, samtang ang displacement mao ang tul-id nga gilay-on gikan sa sinugdanan hangtod sa kataposan, lakip ang direksyon."}, "source": "NRC PS2.A; DepEd G7 motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "diving-board-spring-launch-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "elastic energy in a diving board", "grades": [5, 6, 7], "terms": ["diving board", "tablang lundagan", "spring", "nababaluktot", "bumabalik", "tumatalon", "enerhiya", "nabawog", "mibalik", "milukso", "bends", "bounces back", "launch", "elastic energy"], "fact": {"tl": "Kapag tumuntong ang isang tao sa dulo ng diving board, ito ay nababaluktot at nag-iimbak ng enerhiya na biglang bumabalik para itulak siya pataas.", "en": "When a person steps on the end of a diving board, it bends and stores energy that snaps back to launch them upward.", "bis": "Kung motindog ang usa ka tawo sa tumoy sa diving board, mabawog kini ug magtipig ug enerhiya nga kalit mobalik aron motulak kaniya pataas."}, "source": "NRC PS3.A; DepEd G6 energy", "generator": "claude-workflow", "reviewed": false},
  {"id": "domino-chain-toppling-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "energy transfer in a chain reaction", "grades": [4, 5, 6], "terms": ["domino", "nagkakatumba", "sunod-sunod", "chain reaction", "naipasa", "enerhiya", "tinumba", "nangatumba", "nagsunod-sunod", "gipasa", "dominoes", "toppling", "energy transfer", "falling in a row", "knock over"], "fact": {"tl": "Kapag tinumba ang unang domino, ipinapasa nito ang enerhiya sa susunod, kaya sunod-sunod na bumabagsak ang buong hanay.", "en": "When the first domino is knocked over, it passes its energy to the next one, so the whole row topples one after another.", "bis": "Kung matumba ang unang domino, ipasa niini ang enerhiya sa sunod, busa nagsunod-sunod nga matumba ang tibuok laray."}, "source": "NRC PS3.B; AAAS 4E", "generator": "claude-workflow", "reviewed": false},
  {"id": "doorbell-button-press-circuit-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "switch closing a circuit", "grades": [4, 5, 6], "terms": ["doorbell", "kampanilya", "pindutan", "switch", "circuito", "pinindot", "tumunog", "pindutanan", "gipindot", "mitunog", "button", "press", "completes circuit"], "fact": {"tl": "Kapag pinindot mo ang pindutan ng doorbell, isinasara nito ang circuito kaya dumadaloy ang kuryente at tumutunog ang kampanilya.", "en": "When you press a doorbell button, it closes the circuit so electricity flows and the bell rings.", "bis": "Kung imong pindoton ang doorbell, masirado niini ang circuito busa moagi ang kuryente ug motunog ang kampanilya."}, "source": "AAAS Benchmarks 4G; DepEd G5 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "doorbell-electromagnet-circuit-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "electromagnet in a doorbell", "grades": [7, 8, 9], "terms": ["doorbell", "electromagnet", "kampanilya", "kuryente", "magnet", "kawad na nakapulupot", "humahampas", "elektromagnet", "naglikos nga alambre", "coil", "magnetism", "strikes bell", "electric current"], "fact": {"tl": "Sa loob ng isang doorbell, ang kuryente ay gumagawa ng electromagnet na humihila sa isang martilyo para hampasin ang kampanilya.", "en": "Inside a doorbell, electric current makes an electromagnet that pulls a small hammer to strike the bell.", "bis": "Sulod sa usa ka doorbell, ang kuryente magbuhat ug electromagnet nga mobira sa gamay nga martilyo aron tukon ang kampanilya."}, "source": "NRC PS2.B; AAAS 4G", "generator": "claude-workflow", "reviewed": false},
  {"id": "drinking-glass-prism-edge-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "refraction and color separation", "grades": [5, 6, 7], "terms": ["baso", "salamin", "prism", "kulay", "bahaghari", "liwanag", "naghahati", "kolor", "balangaw", "kahayag", "drinking glass", "prism edge", "rainbow colors", "light splits", "refraction", "spectrum"], "fact": {"tl": "Kapag dumaan ang sikat ng araw sa makapal na gilid ng basong may tubig, parang prism itong naghahati ng liwanag sa mga kulay ng bahaghari.", "en": "When sunlight passes through the thick edge of a water-filled glass, it acts like a prism and splits the light into rainbow colors.", "bis": "Kung moagi ang silaw sa adlaw sa baga nga ngilit sa basong may tubig, molihok kini sama sa prism ug bahinon ang kahayag ngadto sa mga kolor sa balangaw."}, "source": "encyclopedia-stable consensus; AAAS 4F", "generator": "claude-workflow", "reviewed": false},
  {"id": "drum-skin-strike-ripple-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "vibration making sound", "grades": [3, 4, 5], "terms": ["tambol", "balat", "pinalo", "yumayanig", "tunog", "vibration", "alon", "panit", "gibunalan", "nagkurog", "tingog", "drum", "drumhead", "strike", "ripple"], "fact": {"tl": "Kapag pinalo ang balat ng tambol, ito ay mabilis na yumayanig at gumagawa ng tunog na kumakalat sa hangin.", "en": "When a drumhead is struck, it vibrates quickly and makes a sound that spreads through the air.", "bis": "Kung bunalan ang panit sa tambol, kusog kini nga mokurog ug magbuhat ug tingog nga mokaylap sa hangin."}, "source": "AAAS Benchmarks 4F; DepEd G3 sound", "generator": "claude-workflow", "reviewed": false},
  {"id": "drum-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "drum as percussion instrument", "grades": [3, 4, 5], "terms": ["tambol", "instrumento", "tugtugin", "tunog", "balat", "hampas", "membrano", "tugtog", "tingog", "panit", "drum", "percussion", "instrument", "membrane", "musical"], "fact": {"tl": "Ang tambol ay isang instrumentong gumagawa ng tunog kapag pinalo ang nakaunat nitong balat, na pinapayanig ang hangin sa loob at labas.", "en": "A drum is an instrument that makes sound when its stretched skin is struck, setting the air inside and around it vibrating.", "bis": "Ang tambol usa ka instrumento nga magbuhat ug tingog kung bunalan ang gibira niini nga panit, nga magpakurog sa hangin sulod ug palibot niini."}, "source": "AAAS Benchmarks 4F; DepEd G3 sound", "generator": "claude-workflow", "reviewed": false},
  {"id": "egg-drop-protection-challenge-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "cushioning and impact force", "grades": [5, 6, 7], "terms": ["itlog", "ihulog", "proteksyon", "cushion", "puwersa ng banggaan", "nababawasan", "matagal na pagtigil", "ihagit", "panalipod", "kusog sa pagbangga", "egg drop", "cushioning", "impact force", "softens landing", "padding"], "fact": {"tl": "Sa egg drop, ang malambot na balot ay nagpapatagal sa pagtigil ng itlog kaya humihina ang puwersa ng banggaan at hindi ito nababasag.", "en": "In an egg drop, soft padding makes the egg stop more slowly, which lessens the impact force so the egg does not break.", "bis": "Sa egg drop, ang humok nga putos magpahinay sa paghunong sa itlog maong mokunhod ang kusog sa pagbangga ug dili kini mabuak."}, "source": "NRC PS2.A; AAAS 4F", "generator": "claude-workflow", "reviewed": false},
  {"id": "electric-bill-meter-reading-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "measuring electrical energy use", "grades": [5, 6, 7], "terms": ["metro ng kuryente", "electric meter", "bayarin", "konsumo", "kilowatt-hour", "sinusukat", "metro sa kuryente", "bayranan", "gigamit nga kuryente", "electric bill", "energy use", "measuring electricity"], "fact": {"tl": "Ang metro ng kuryente sa bahay ay sumusukat kung gaano karaming enerhiya ang ginamit, na binibilang sa kilowatt-hour para sa iyong bayarin.", "en": "A home electric meter measures how much energy is used, counted in kilowatt-hours, which is what your bill is based on.", "bis": "Ang metro sa kuryente sa balay magsukod kung pila ka enerhiya ang nagamit, gisukod sa kilowatt-hour, nga maoy basihan sa imong bayranan."}, "source": "encyclopedia-stable consensus; NRC PS3", "generator": "claude-workflow", "reviewed": false},
  {"id": "electric-fan-energy-to-wind-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "energy transformation in a fan", "grades": [4, 5, 6], "terms": ["bentilador", "electric fan", "kuryente", "hangin", "umiikot", "enerhiya", "ginagawa", "nagtuyok", "electric fan", "wind", "energy transformation", "electricity to motion", "spinning blades"], "fact": {"tl": "Ang electric fan ay nagbabago ng kuryenteng enerhiya tungo sa galaw, na pinapaikot ang mga talim para makagawa ng hangin.", "en": "An electric fan changes electrical energy into motion, spinning its blades to make a cooling breeze.", "bis": "Ang electric fan magbag-o sa kuryente nga enerhiya ngadto sa lihok, nga magtuyok sa mga sulab aron makahimo ug hangin."}, "source": "NRC PS3.B; DepEd G6 energy", "generator": "claude-workflow", "reviewed": false},
  {"id": "electrocution-wet-hands-warning-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "water conducts electricity safety", "grades": [4, 5, 6], "terms": ["basa", "kamay", "kuryente", "kuryenteng dumadaan", "delikado", "kuryentehan", "ingat", "kamot", "amping", "wet hands", "electric shock", "water conducts electricity", "danger", "safety", "do not touch"], "fact": {"tl": "Hindi dapat hawakan ang mga gamit na de-kuryente gamit ang basang kamay dahil ang tubig ay nagpapadaloy ng kuryente at maaaring makakuryente sa iyo.", "en": "You should never touch electrical devices with wet hands because water conducts electricity and can shock you.", "bis": "Dili gyud angay hikapon ang mga de-kuryente nga gamit gamit ang basa nga kamot kay ang tubig magpaagi sa kuryente ug mahimong makakuryente kanimo."}, "source": "encyclopedia-stable consensus; DepEd G5 electrical safety", "generator": "claude-workflow", "reviewed": false},
  {"id": "electromagnet-nail-coil-build-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "building an electromagnet", "grades": [6, 7, 8], "terms": ["electromagnet", "pako", "kawad", "nakapulupot", "baterya", "magnet", "kuryente", "elektromagnet", "lansang", "alambre", "naglikos", "electromagnet", "nail", "coiled wire", "battery", "magnetism", "temporary magnet"], "fact": {"tl": "Kapag pinulupot mo ng kawad ang isang pako at ikinabit sa baterya, magiging electromagnet ito na maaaring humila ng mga bagay na bakal habang may kuryente.", "en": "When you wrap a nail with wire and connect it to a battery, it becomes an electromagnet that can pull iron objects while current flows.", "bis": "Kung imong likoson ug alambre ang usa ka lansang ug isumpay sa baterya, mahimo kining electromagnet nga makabira sa mga puthaw nga butang samtang aduna pay kuryente."}, "source": "NRC PS2.B; AAAS 4G", "generator": "claude-workflow", "reviewed": false},
  {"id": "electromagnetic-induction-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "electromagnetic induction", "grades": [8, 9, 10], "terms": ["electromagnetic induction", "magnet", "kawad", "ginagalaw", "kuryente", "nalilikha", "induksyon", "alambre", "gilihok", "namugna", "moving magnet", "coil", "generates current", "generator", "induced electricity"], "fact": {"tl": "Kapag ang isang magnet ay ginagalaw papasok o palabas ng nakapulupot na kawad, nalilikha nito ang daloy ng kuryente; ito ang prinsipyo ng generator.", "en": "When a magnet is moved in and out of a coil of wire, it generates a flow of electric current; this is the principle behind generators.", "bis": "Kung ang usa ka magnet ipalihok pasulod ug pagawas sa naglikos nga alambre, makamugna kini ug agos sa kuryente; mao kini ang prinsipyo sa generator."}, "source": "NRC PS2.B; DepEd G10 electromagnetism", "generator": "claude-workflow", "reviewed": false},
  {"id": "em-spectrum-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "electromagnetic spectrum", "grades": [8, 9, 10], "terms": ["electromagnetic spectrum", "liwanag", "radyo", "x-ray", "infrared", "ultraviolet", "alon", "spektro", "kahayag", "balod", "radio waves", "visible light", "x-rays", "wavelength", "radiation"], "fact": {"tl": "Ang electromagnetic spectrum ay ang buong saklaw ng mga alon ng liwanag, mula sa radyo at infrared hanggang sa nakikitang liwanag, ultraviolet, at x-ray.", "en": "The electromagnetic spectrum is the full range of light waves, from radio and infrared to visible light, ultraviolet, and x-rays.", "bis": "Ang electromagnetic spectrum mao ang tibuok han-ay sa mga balod sa kahayag, gikan sa radyo ug infrared ngadto sa makita nga kahayag, ultraviolet, ug x-ray."}, "source": "NRC PS4.B; DepEd G10 waves", "generator": "claude-workflow", "reviewed": false},
  {"id": "extension-cord-overload-hazard-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "circuit overload safety", "grades": [5, 6, 7], "terms": ["extension cord", "sobrang karga", "overload", "uminit", "sunog", "delikado", "maraming nakasaksak", "extension", "sobra nga karga", "init", "amping", "overheating", "fire hazard", "too many plugs", "safety"], "fact": {"tl": "Kapag sobra ang nakasaksak sa isang extension cord, dumadaloy ang labis na kuryente kaya ito uminit at maaaring magdulot ng sunog.", "en": "When too many devices are plugged into one extension cord, too much current flows, making it overheat and possibly start a fire.", "bis": "Kung sobra ang nakasaksak sa usa ka extension cord, sobra ang kuryente nga moagi maong moinit kini ug mahimong hinungdan sa sunog."}, "source": "encyclopedia-stable consensus; DepEd G5 electrical safety", "generator": "claude-workflow", "reviewed": false},
  {"id": "eyeglasses-correcting-vision-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "eyeglasses bend light to correct vision", "grades": [6, 7, 8], "terms": ["salamin sa mata", "antipara", "lente", "nakukurba ang liwanag", "malabong paningin", "antiyohos", "salaming antipara", "mata", "antiyog", "salamin sa mata bisaya", "lente nga magkurba", "panan-aw", "eyeglasses", "lens", "bend light", "focus", "vision", "blurry"], "fact": {"tl": "Ang salamin sa mata ay may mga lenteng nagbabaluktot ng liwanag upang ito ay tumama nang tama sa likod ng mata, kaya nagiging malinaw ang nakikita ng taong malabo ang paningin.", "en": "Eyeglasses have lenses that bend light so it focuses correctly at the back of the eye, making things look clear for a person with blurry vision.", "bis": "Ang antipara naay mga lente nga nagakurba sa kahayag aron motama kini sa likod sa mata, busa mahimong klaro ang panan-aw sa tawo nga halap og mata."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks light/optics", "generator": "claude-workflow", "reviewed": false},
  {"id": "fanning-charcoal-airflow-g4", "domain": "MATTER", "topic": "fanning fire adds oxygen to make it burn hotter", "grades": [4, 5, 6], "terms": ["pagpaypay sa uling", "paypay", "hangin", "oxygen", "nag-aapoy", "sumiklab", "lalong uminit", "apoy", "uling", "sunog", "paypay sa baga", "pagpaypay sa kalayo", "hangin nga oxygen", "baga", "uling nga nagsiga", "fanning", "charcoal", "airflow", "oxygen", "fire burns hotter"], "fact": {"tl": "Kapag pinaypayan natin ang uling, mas maraming hanging may oxygen ang dumadaloy dito, kaya lalong nag-iinit at nagliliyab ang apoy.", "en": "When we fan burning charcoal, more air carrying oxygen flows to it, so the fire burns hotter and brighter.", "bis": "Kon paypayan nato ang baga sa uling, mas daghang hangin nga adunay oxygen ang moagi niini, busa mas moinit ug mosiga ang kalayo."}, "source": "encyclopedia-stable consensus; combustion needs oxygen", "generator": "claude-workflow", "reviewed": false},
  {"id": "faucet-handle-wheel-axle-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "faucet handle is a wheel and axle", "grades": [5, 6, 7], "terms": ["gripo", "hawakan ng gripo", "gulong at ehe", "wheel and axle", "simpleng makina", "umiikot", "pinapadali", "gripo nga gunitanan", "ligid ug ehe", "simpleng makina", "tubig nga gripo", "balbula sa tubig", "faucet handle", "wheel and axle", "simple machine", "turn", "valve"], "fact": {"tl": "Ang pabilog na hawakan ng gripo ay isang gulong-at-ehe, isang simpleng makinang nagpapadali sa pag-ikot ng balbula sa loob upang buksan o isara ang tubig.", "en": "A round faucet handle is a wheel and axle, a simple machine that makes it easier to turn the valve inside to start or stop the water.", "bis": "Ang lingin nga gunitanan sa gripo usa ka ligid-ug-ehe, usa ka simpleng makina nga makapasayon sa pagliso sa balbula sa sulod aron pagbukas o pagsira sa tubig."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks simple machines", "generator": "claude-workflow", "reviewed": false},
  {"id": "fiesta-tug-of-war-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "tug of war shows balanced and unbalanced forces", "grades": [4, 5, 6], "terms": ["batuhan ng lubid", "tug of war", "hilahan ng lubid", "puwersa", "magkasalungat na puwersa", "panalo ang mas malakas", "hatak", "fiesta", "birohan sa lubid", "buhata sa lubid", "kusog nga pagbira", "magkabatok nga kusog", "lubid", "tug of war", "force", "pull", "balanced unbalanced forces", "net force"], "fact": {"tl": "Sa batuhan ng lubid, magkasalungat na puwersa ang hatak ng dalawang grupo, at gumagalaw ang lubid papunta sa panig na mas malakas humihila.", "en": "In tug of war, the two teams pull with opposite forces, and the rope moves toward the side that pulls harder.", "bis": "Sa birohan sa lubid, magkabatok nga kusog ang pagbira sa duha ka grupo, ug molihok ang lubid padulong sa kilid nga mas kusgan mobira."}, "source": "NRC PS2.A forces and motion; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fishing-net-hauling-pull-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "hauling a fishing net is a pulling force", "grades": [3, 4, 5], "terms": ["paghila ng lambat", "lambat", "mangingisda", "puwersa ng hila", "hatak", "pull", "nakahuli ng isda", "pukot", "pagbira sa pukot", "mananagat", "kusog sa pagbira", "isda", "lambat sa mangingisda", "fishing net", "haul", "pull force", "fisherman", "drag"], "fact": {"tl": "Kapag hinihila ng mga mangingisda ang kanilang lambat pabalik sa bangka, gumagamit sila ng puwersa ng hatak upang madala ang mabigat na lambat na puno ng isda.", "en": "When fishermen haul their net back to the boat, they use a pulling force to move the heavy net full of fish.", "bis": "Kon birahon sa mga mananagat ang ilang pukot balik sa sakayan, naggamit silag kusog sa pagbira aron madala ang bug-at nga pukot nga puno sa isda."}, "source": "NRC PS2.A forces; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fishing-rod-lever-cast-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "fishing rod acts as a lever", "grades": [5, 6, 7], "terms": ["pamingwit", "fishing rod", "lever", "pingga", "ihinahagis ang pain", "pumapalo", "umaarko", "pumipingwit", "bunit", "pamunit", "ihagis ang pain", "lever nga bunit", "pamingwit nga baston", "fishing rod", "lever", "cast", "bend", "leverage"], "fact": {"tl": "Ang pamingwit ay para na ring pingga: ang pagbaluktot at pag-arko nito ang nagpapalayo sa paghahagis ng pain papunta sa tubig.", "en": "A fishing rod works like a lever: its bending and arc help fling the bait far out into the water.", "bis": "Ang bunit murag usa ka lever: ang pagbawog ug pag-arko niini ang makatabang sa paglabay sa paon halayo padulong sa tubig."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks simple machines", "generator": "claude-workflow", "reviewed": false},
  {"id": "flashlight-beam-fog-night-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "we see a flashlight beam when light scatters off fog or dust", "grades": [5, 6, 7], "terms": ["sinag ng flashlight", "ulap", "hamog", "alikabok", "liwanag", "nakikita ang sinag", "tumatalbog ang liwanag", "gabi", "flashlight", "silaw", "sinag sa flashlight", "gabon", "abog", "kahayag nga mosalimbag", "kita ang sinag", "flashlight beam", "fog", "dust", "scatter", "light path"], "fact": {"tl": "Nakikita natin ang sinag ng flashlight sa hamog o alikabok dahil tumatalbog ang liwanag sa maliliit na patak ng tubig at butil ng alikabok pabalik sa ating mata.", "en": "We can see a flashlight beam in fog or dust because the light scatters off tiny water droplets and dust particles back to our eyes.", "bis": "Makita nato ang sinag sa flashlight sa gabon o abog tungod kay ang kahayag mosalimbag sa gagmay nga tulo sa tubig ug abog balik sa atong mata."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks light scattering", "generator": "claude-workflow", "reviewed": false},
  {"id": "flashlight-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "flashlight turns battery energy into light", "grades": [4, 5, 6], "terms": ["flashlight", "baterya", "ilaw", "bombilya", "switch", "enerhiya", "kuryente", "nagliliwanag", "baterya nga ilaw", "suga", "elektrisidad", "kuryente gikan sa baterya", "flashlight", "battery", "bulb", "light", "electrical energy"], "fact": {"tl": "Ang flashlight ay nagbibigay ng liwanag sa pamamagitan ng baterya na nagpapadaloy ng kuryente sa bombilya kapag pinindot ang switch.", "en": "A flashlight gives light when a battery sends electricity to the bulb after you press the switch.", "bis": "Ang flashlight mohatag og kahayag pinaagi sa baterya nga nagpadagan og kuryente ngadto sa bombilya kon imong pinduton ang switch."}, "source": "encyclopedia-stable consensus; NRC PS3.B energy transfer", "generator": "claude-workflow", "reviewed": false},
  {"id": "float-sink-materials-test-basin-g4", "domain": "MATTER", "topic": "whether an object floats depends on its material and shape", "grades": [3, 4, 5], "terms": ["lumulutang", "lumulubog", "palanggana", "tubig", "materyales", "subok", "lutang", "lubog", "lutang ug lunod", "planggana", "materyales nga sulayan", "lunod sa tubig", "naglutaw", "float", "sink", "basin", "material test", "density", "water"], "fact": {"tl": "Kapag sinubukan natin sa palanggana ng tubig, may mga bagay na lumulutang at may lumulubog, depende sa kung gaano kabigat ang materyales kumpara sa tubig.", "en": "When we test objects in a basin of water, some float and some sink, depending on how heavy the material is compared with the water.", "bis": "Kon sulayan nato sa planggana nga tubig, naay mga butang nga magalutaw ug naay magalunod, depende kon unsa kabug-at ang materyales kumparado sa tubig."}, "source": "encyclopedia-stable consensus; DepEd properties of matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "floating-sinking-objects-water-g5", "domain": "MATTER", "topic": "objects float when less dense than water", "grades": [5, 6, 7], "terms": ["lumulutang", "lumulubog", "densidad", "kapal", "tubig", "mas magaan", "mas mabigat sa tubig", "lutang", "lunod", "lutang ug lunod", "gibug-aton", "densidad sa tubig", "mas gaan kay sa tubig", "float", "sink", "density", "buoyancy", "less dense", "water"], "fact": {"tl": "Lumulutang ang isang bagay kung ito ay mas magaan kaysa sa katumbas na dami ng tubig, at lumulubog naman kung mas mabigat ito kaysa tubig.", "en": "An object floats if it is lighter than the same amount of water it pushes aside, and sinks if it is heavier than that water.", "bis": "Magalutaw ang usa ka butang kon mas gaan kini kay sa samang gidaghanon sa tubig nga iyang gibalibag, ug magalunod kon mas bug-at kini kay sa tubig."}, "source": "encyclopedia-stable consensus; Archimedes buoyancy; AAAS Benchmarks", "generator": "claude-workflow", "reviewed": false},
  {"id": "free-body-diagram-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "free-body diagram shows forces as arrows on an object", "grades": [8, 9, 10], "terms": ["free-body diagram", "diagram ng puwersa", "pana", "arrow", "puwersa", "bigat", "normal force", "direksyon", "diagram sa kusog", "pana sa puwersa", "gibug-aton", "direksyon sa kusog", "free-body diagram", "force arrows", "vectors", "direction", "magnitude"], "fact": {"tl": "Ang free-body diagram ay isang guhit na nagpapakita ng lahat ng puwersang kumikilos sa isang bagay, gamit ang mga panang nagtuturo sa direksyon at lakas ng bawat puwersa.", "en": "A free-body diagram is a drawing that shows all the forces acting on an object, using arrows that point in the direction and size of each force.", "bis": "Ang free-body diagram usa ka drowing nga nagpakita sa tanang kusog nga naglihok sa usa ka butang, ginamit ang mga pana nga nagtudlo sa direksyon ug kakusog sa matag puwersa."}, "source": "encyclopedia-stable consensus; NRC PS2.A forces", "generator": "claude-workflow", "reviewed": false},
  {"id": "free-throw-arc-basketball-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "a basketball follows a curved path because of gravity", "grades": [7, 8, 9], "terms": ["free throw", "basketball", "arko", "kurba", "gravity", "grabidad", "bumagsak", "proyektil", "basketbol", "arko sa bola", "kurba sa bola", "nahulog", "projectile", "free throw", "arc", "gravity", "curved path"], "fact": {"tl": "Kapag inihahagis ang bola sa free throw, ito ay sumusunod sa isang arko dahil hinihila ng grabidad ang bola pababa habang ito ay lumilipad.", "en": "When a free throw is shot, the ball follows a curved arc because gravity pulls it downward while it flies forward.", "bis": "Kon ilabay ang bola sa free throw, mosunod kini sa usa ka arko tungod kay ang grabidad mobira sa bola paubos samtang naglupad kini."}, "source": "encyclopedia-stable consensus; NRC PS2.A gravity and projectile motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "friction-ramp-surfaces-test-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "rougher surfaces create more friction on a ramp", "grades": [5, 6, 7], "terms": ["alitan", "friction", "ramp", "dahilig", "magaspang", "makinis", "bumagal", "pagsubok", "kuskos", "kiskisan", "banghilig", "magaspang nga ibabaw", "hapsay", "ramp nga pagsulay", "friction", "surface", "rough", "smooth", "slows down"], "fact": {"tl": "Kapag pinagulong natin ang isang bagay sa dahilig, mas mabagal itong gumulong sa magaspang na ibabaw dahil mas malaki ang alitan o friction doon.", "en": "When we roll an object down a ramp, it moves slower on a rough surface because there is more friction there.", "bis": "Kon paligiron nato ang usa ka butang sa banghilig, mas hinay kining moligid sa magaspang nga ibabaw tungod kay mas dako ang friction o kiskisan didto."}, "source": "encyclopedia-stable consensus; NRC PS2.A friction", "generator": "claude-workflow", "reviewed": false},
  {"id": "friction-surfaces-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "friction is a force between two touching surfaces", "grades": [4, 5, 6], "terms": ["alitan", "friction", "kuskos", "dalawang ibabaw", "puwersa", "bumabagal", "init", "magaspang", "kiskisan", "duha ka ibabaw", "kusog nga mosumpo", "mohinay", "init gikan sa kuskos", "friction", "surfaces", "rubbing", "force", "slows", "heat"], "fact": {"tl": "Ang alitan o friction ay isang puwersang nabubuo kapag nagkikiskisan ang dalawang ibabaw, at ito ang nagpapabagal sa paggalaw ng mga bagay.", "en": "Friction is a force that forms when two surfaces rub against each other, and it slows down the movement of objects.", "bis": "Ang kiskisan o friction usa ka kusog nga matuman kon ang duha ka ibabaw maggidlanay, ug kini ang makapahinay sa paglihok sa mga butang."}, "source": "encyclopedia-stable consensus; NRC PS2.A friction", "generator": "claude-workflow", "reviewed": false},
  {"id": "fridge-magnet-holding-note-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "magnets stick to the steel door of a refrigerator", "grades": [3, 4, 5], "terms": ["magnet", "refrigerator", "pridyider", "bakal", "dumidikit", "puwersa ng magnet", "papel", "ref", "magnetiko", "puthaw", "modikit", "kusog sa magnet", "papel nga gipugong", "fridge magnet", "steel door", "attract", "hold note", "magnetic"], "fact": {"tl": "Dumidikit ang magnet sa pinto ng pridyider dahil yari ito sa bakal, at ang puwersa ng magnet ang humahawak sa papel na nakasipit dito.", "en": "A magnet sticks to the refrigerator door because the door is made of steel, and the magnet's force holds the note pressed against it.", "bis": "Modikit ang magnet sa pultahan sa pridyider tungod kay puthaw kini, ug ang kusog sa magnet ang nagpugong sa papel nga gipatapot niini."}, "source": "encyclopedia-stable consensus; NRC PS2.B magnetism", "generator": "claude-workflow", "reviewed": false},
  {"id": "garden-hose-rainbow-mist-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "water droplets split sunlight into a rainbow", "grades": [5, 6, 7], "terms": ["bahaghari", "hose", "ambon", "patak ng tubig", "sikat ng araw", "kulay", "liwanag", "nahahati ang liwanag", "balangaw", "gabon sa tubig", "tulo sa tubig", "kahayag sa adlaw", "kolor", "natunga ang kahayag", "rainbow", "mist", "water droplets", "sunlight", "split light", "colors"], "fact": {"tl": "Kapag pinaambon natin ang hose tuwing may sikat ng araw, lumilitaw ang bahaghari dahil hinahati ng maliliit na patak ng tubig ang puting liwanag sa iba't ibang kulay.", "en": "When we spray a hose into a mist on a sunny day, a rainbow appears because tiny water droplets split white sunlight into different colors.", "bis": "Kon ambonon nato ang hose samtang naay sidlak sa adlaw, motungha ang balangaw tungod kay ang gagmay nga tulo sa tubig magbahin sa puti nga kahayag ngadto sa lainlaing kolor."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks light and color", "generator": "claude-workflow", "reviewed": false},
  {"id": "gear-cog-single-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "a gear is a toothed wheel that turns other gears", "grades": [5, 6, 7], "terms": ["gear", "cog", "ngipin", "gulong na may ngipin", "umiikot", "makina", "nagpapaikot", "gilingan", "ngipon", "ligid nga may ngipon", "moliso", "makina nga gear", "nagpaliso", "gear", "cog", "toothed wheel", "turn", "machine", "mesh"], "fact": {"tl": "Ang gear ay isang gulong na may mga ngipin sa gilid; kapag umikot ito, naipapasa nito ang galaw sa kabit na gear upang umandar ang isang makina.", "en": "A gear is a wheel with teeth around its edge; when it turns, it passes its motion to another gear so a machine can run.", "bis": "Ang gear usa ka ligid nga may mga ngipon sa kilid; kon moliso kini, mapasa niini ang lihok ngadto sa sumpay nga gear aron molihok ang usa ka makina."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks simple machines", "generator": "claude-workflow", "reviewed": false},
  {"id": "grounded-three-prong-safety-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "the third prong grounds a plug for safety", "grades": [7, 8, 9], "terms": ["tatlong tulis na saksak", "ground", "kuryente", "kaligtasan", "lupa", "kuryenteng tumatakas", "saksak", "plug", "grounding", "tulo ka prong nga plug", "kuryente nga moagas", "kaluwasan", "yuta", "three-prong plug", "ground wire", "safety", "electric shock", "earth"], "fact": {"tl": "Ang ikatlong tulis ng saksak ay isang ground na nagdadala ng tumatakas na kuryente palayo papunta sa lupa, kaya nakakaiwas tayo sa pagkakuryente.", "en": "The third prong of a plug is a ground that carries stray electricity safely away into the earth, helping protect us from electric shock.", "bis": "Ang ikatulong tumoy sa plug usa ka ground nga magdala sa nagaagas nga kuryente palayo padulong sa yuta, busa malikayan nato ang pagkakuryente."}, "source": "encyclopedia-stable consensus; electrical safety grounding", "generator": "claude-workflow", "reviewed": false},
  {"id": "hand-crank-generator-toy-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "a hand-crank generator turns motion into electricity", "grades": [6, 7, 8], "terms": ["hand crank", "generator", "pihit", "ikot", "kuryente", "enerhiya", "galaw", "nagagawa ng kuryente", "manibela", "generator nga liso", "kuryente gikan sa lihok", "pagliso", "pagliso sa makina", "hand crank generator", "motion to electricity", "turn", "magnet coil"], "fact": {"tl": "Kapag piniphit natin ang hawakan ng hand-crank generator, ang galaw ay nagiging kuryente na nakapagpapailaw ng maliit na bombilya.", "en": "When we turn the handle of a hand-crank generator, the motion is changed into electricity that can light a small bulb.", "bis": "Kon lisuon nato ang gunitanan sa hand-crank generator, ang lihok mahimong kuryente nga makapasiga sa gamay nga bombilya."}, "source": "encyclopedia-stable consensus; NRC PS3.A energy conversion", "generator": "claude-workflow", "reviewed": false},
  {"id": "hand-pump-poso-lever-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "a poso hand pump uses a lever to raise water", "grades": [5, 6, 7], "terms": ["poso", "bomba ng tubig", "hand pump", "lever", "pingga", "umaakyat ang tubig", "balon", "bomba sa tubig", "lever nga gunitanan", "tubig nga mosaka", "atabay", "hand pump", "raise water", "well", "pump handle"], "fact": {"tl": "Ang poso o hand pump ay gumagamit ng isang pingga: kapag itinaas-baba natin ang hawakan, umaakyat ang tubig mula sa ilalim ng lupa.", "en": "A poso, or hand pump, uses a lever: when we push the handle up and down, water rises up from underground.", "bis": "Ang poso o hand pump naggamit og lever: kon itaas-ubos nato ang gunitanan, mosaka ang tubig gikan sa ilalom sa yuta."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks simple machines", "generator": "claude-workflow", "reviewed": false},
  {"id": "hand-rubbing-warmth-friction-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "rubbing hands makes heat from friction", "grades": [3, 4, 5], "terms": ["pagkiskis ng kamay", "init", "alitan", "friction", "umiinit ang kamay", "kuskos", "lamig", "init gikan sa kiskisan", "pagkiskis sa kamot", "moinit ang kamot", "tugnaw", "kuskos sa kamot", "rubbing hands", "warmth", "friction", "heat", "cold"], "fact": {"tl": "Kapag mabilis nating kinikiskis ang ating mga kamay, umiinit ang mga ito dahil ang alitan o friction ay nagbubuo ng init.", "en": "When we rub our hands together quickly, they warm up because friction between them makes heat.", "bis": "Kon kuskoson nato pag-ayo ang atong mga kamot, moinit kini tungod kay ang kiskisan o friction maghimo og kainit."}, "source": "encyclopedia-stable consensus; NRC PS3.B friction and heat", "generator": "claude-workflow", "reviewed": false},
  {"id": "hand-water-pump-poso-g4", "domain": "EARTH_SPACE", "topic": "a poso draws groundwater from beneath the soil", "grades": [4, 5, 6], "terms": ["poso", "tubig sa ilalim ng lupa", "groundwater", "balon", "bomba", "inumin", "malinis na tubig", "tubig sa ilalom sa yuta", "atabay", "bomba sa tubig", "limpyo nga tubig", "imnon", "poso", "hand pump", "groundwater", "underground water", "well", "drinking water"], "fact": {"tl": "Ang poso ay kumukuha ng tubig mula sa ilalim ng lupa, kung saan naiimbak ang ulang dumaloy pababa at natipon sa pagitan ng mga bato at buhangin.", "en": "A poso draws water from underground, where rain that soaked down is stored among the rocks and sand below the soil.", "bis": "Ang poso magkuha og tubig gikan sa ilalom sa yuta, diin natipon ang ulan nga miagas paubos ug natigom taliwala sa mga bato ug balas."}, "source": "encyclopedia-stable consensus; NRC ESS2.C groundwater", "generator": "claude-workflow", "reviewed": false},
  {"id": "heat-by-color-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "dark colors absorb more sunlight and heat up faster", "grades": [5, 6, 7], "terms": ["kulay at init", "maitim", "maputi", "sumisipsip ng init", "araw", "mas mainit", "absorb", "itim na damit", "kolor ug kainit", "itom", "puti", "mosuyop sa kainit", "mas init", "itom nga sapot", "color and heat", "dark colors", "absorb sunlight", "hotter", "reflect"], "fact": {"tl": "Ang maiitim na kulay ay mas mabilis uminit sa ilalim ng araw kaysa sa maputi, dahil mas marami itong sinisipsip na liwanag at init.", "en": "Dark colors heat up faster in the sun than light colors because they absorb more of the sun's light and heat.", "bis": "Ang itom nga kolor mas paspas moinit ilalom sa adlaw kay sa puti, tungod kay mas daghan kining gisuyop nga kahayag ug kainit."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks energy/heat absorption", "generator": "claude-workflow", "reviewed": false},
  {"id": "heating-water-thermometer-setup-g5", "domain": "MATTER", "topic": "a thermometer measures rising temperature as water heats", "grades": [4, 5, 6], "terms": ["termometro", "pagpainit ng tubig", "temperatura", "init", "tumataas ang bilang", "kumukulo", "thermometer", "pagpainit sa tubig", "kainit", "mosaka ang numero", "molagiti", "heating water", "temperature", "rising", "boiling", "measure"], "fact": {"tl": "Kapag iniinit natin ang tubig, ipinapakita ng termometro na patuloy na tumataas ang temperatura hanggang umabot ito sa puntong kumukulo.", "en": "When we heat water, a thermometer shows the temperature rising steadily until it reaches the boiling point.", "bis": "Kon initon nato ang tubig, ipakita sa termometro nga padayon nga mosaka ang temperatura hangtod moabot kini sa punto nga molagiti."}, "source": "encyclopedia-stable consensus; DepEd heat and temperature", "generator": "claude-workflow", "reviewed": false},
  {"id": "home-wiring-outlet-plug-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "an outlet supplies electricity through a closed circuit when plugged in", "grades": [6, 7, 8], "terms": ["saksakan", "outlet", "plug", "saksak", "kuryente", "kable", "sirkito", "umaandar", "kuryente sa balay", "alambre", "sirado nga sirkito", "kon nakasaksak", "outlet", "plug", "wiring", "circuit", "electricity", "wall socket"], "fact": {"tl": "Kapag isinaksak natin ang plug sa saksakan, nabubuo ang isang saradong sirkito kaya dumadaloy ang kuryente at gumagana ang ating mga kagamitan.", "en": "When we insert a plug into an outlet, a closed circuit forms so electricity flows and our appliances work.", "bis": "Kon isaksak nato ang plug sa saksakan, matuman ang usa ka sirado nga sirkito busa modagan ang kuryente ug molihok ang atong mga gamit."}, "source": "encyclopedia-stable consensus; NRC PS3.B electric circuits", "generator": "claude-workflow", "reviewed": false},
  {"id": "hot-air-balloon-rising-heat-g7", "domain": "MATTER", "topic": "hot air rises, lifting a hot-air balloon", "grades": [6, 7, 8], "terms": ["hot air balloon", "lobo", "mainit na hangin", "umaakyat", "pumapaitaas", "magaan", "lumulutang sa hangin", "init nga hangin", "mosaka", "gaan nga hangin", "lobo nga molupad", "molutaw sa hangin", "hot air balloon", "hot air rises", "lift", "less dense", "buoyancy"], "fact": {"tl": "Pumapaitaas ang hot-air balloon dahil ang pinainit na hangin sa loob nito ay mas magaan kaysa sa malamig na hangin sa labas, kaya ito lumulutang pataas.", "en": "A hot-air balloon rises because the heated air inside it is lighter than the cooler air outside, so it floats upward.", "bis": "Mosaka ang hot-air balloon tungod kay ang gipainit nga hangin sa sulod niini mas gaan kay sa bugnaw nga hangin sa gawas, busa molutaw kini pataas."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks heat and density", "generator": "claude-workflow", "reviewed": false},
  {"id": "hot-spoon-handle-conduction-g6", "domain": "MATTER", "topic": "heat travels along a metal spoon by conduction", "grades": [5, 6, 7], "terms": ["kutsara", "init", "conduction", "metal", "umiinit ang hawakan", "mainit na sopas", "dumadaloy ang init", "tagiliran", "kainit", "metal nga kutsara", "moinit ang gunitanan", "init nga sabaw", "spoon handle", "conduction", "heat travels", "hot soup"], "fact": {"tl": "Kapag iniwan natin ang metal na kutsara sa mainit na sopas, umiinit din ang hawakan dahil dumadaloy ang init sa metal sa pamamagitan ng conduction.", "en": "When we leave a metal spoon in hot soup, the handle also gets hot because heat travels through metal by conduction.", "bis": "Kon ibilin nato ang metal nga kutsara sa init nga sabaw, moinit usab ang gunitanan tungod kay ang kainit moagi sa metal pinaagi sa conduction."}, "source": "encyclopedia-stable consensus; NRC PS3.B heat conduction", "generator": "claude-workflow", "reviewed": false},
  {"id": "hourglass-sand-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "sand falls through an hourglass at a steady rate to measure time", "grades": [3, 4, 5], "terms": ["hourglass", "orasan ng buhangin", "buhangin", "bumabagsak", "grabidad", "sukat ng oras", "patuloy", "orasan sa balas", "balas", "nahulog", "sukod sa oras", "kanunay", "hourglass", "sand", "falls", "gravity", "measure time", "steady"], "fact": {"tl": "Sa orasan ng buhangin, dahan-dahang bumabagsak ang buhangin dahil sa grabidad sa pare-parehong bilis, kaya magagamit ito sa pagsukat ng oras.", "en": "In an hourglass, sand falls steadily because of gravity at the same rate, so it can be used to measure a span of time.", "bis": "Sa orasan sa balas, hinay-hinay nga nahulog ang balas tungod sa grabidad sa managsamang katulin, busa magamit kini sa pagsukod sa oras."}, "source": "encyclopedia-stable consensus; NRC PS2.A gravity", "generator": "claude-workflow", "reviewed": false},
  {"id": "household-appliance-energy-use-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "appliances convert electrical energy", "grades": [5, 6, 7], "terms": ["kagamitan sa bahay", "appliances", "kuryente", "elektrisidad", "enerhiya", "kasangkapan", "gamit sa balay", "koryente", "init", "kahayag", "lihok", "electrical energy", "appliance", "electricity", "heat", "light"], "fact": {"tl": "Ang mga kagamitan sa bahay tulad ng plantsa, bombilya, at electric fan ay gumagamit ng elektrisidad na ginagawang init, liwanag, o galaw.", "en": "Household appliances like the iron, light bulb, and electric fan use electricity, which they change into heat, light, or motion.", "bis": "Ang mga kasangkapan sa balay sama sa plantsa, bombilya, ug electric fan naggamit og koryente nga ilang gihimong init, kahayag, o lihok."}, "source": "NRC PS3.A; DepEd G6 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "ice-candy-melting-hand-g4", "domain": "MATTER", "topic": "melting solid to liquid by heat", "grades": [3, 4, 5], "terms": ["ice candy", "natutunaw", "matunaw", "init ng kamay", "yelo", "solido", "likido", "kainit sa kamot", "tunaw", "gahi", "melting", "ice", "heat", "solid", "liquid"], "fact": {"tl": "Natutunaw ang ice candy kapag hinawakan dahil ang init ng kamay ay nagpapalit sa matigas na yelo nito tungo sa likido.", "en": "An ice candy melts when you hold it because the heat from your hand changes its solid ice into liquid.", "bis": "Matunaw ang ice candy kon imong kuptan tungod kay ang kainit sa imong kamot maoy nagbalhin sa gahi nga yelo niini ngadto sa likido."}, "source": "NRC PS1.A; DepEd G4 Q1", "generator": "claude-workflow", "reviewed": false},
  {"id": "ice-melting-rate-materials-g6", "domain": "MATTER", "topic": "heat conduction varies by material", "grades": [5, 6, 7], "terms": ["bilis ng pagkatunaw", "materyales", "metal", "kahoy", "plastik", "yelo", "conductor", "insulator", "init", "kadali sa pagkatunaw", "puthaw", "wood", "melt rate"], "fact": {"tl": "Mas mabilis natutunaw ang yelo kapag nakapatong sa metal kaysa sa kahoy o plastik dahil mas mabilis maghatid ng init ang metal.", "en": "Ice melts faster on metal than on wood or plastic because metal carries heat to it more quickly.", "bis": "Mas paspas matunaw ang yelo kon gibutang sa metal kaysa sa kahoy o plastik tungod kay mas paspas magdala og init ang metal."}, "source": "NRC PS3.B; DepEd G6 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "ironing-clothes-conduction-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "heat conduction through contact", "grades": [5, 6, 7], "terms": ["pagpaplantsa", "plantsa", "damit", "kondaksyon", "init", "kuryente", "sapot", "conduction", "iron", "clothes", "heat transfer", "contact"], "fact": {"tl": "Sa pagpaplantsa, dumadaloy ang init mula sa mainit na plantsa patungo sa damit sa pamamagitan ng dikit o kondaksyon, kaya naunat ang gusot.", "en": "When ironing, heat flows from the hot iron into the cloth by direct contact, called conduction, which smooths out the wrinkles.", "bis": "Sa pagplantsa, ang init moagos gikan sa init nga plantsa ngadto sa sapot pinaagi sa direktang paghikap o conduction, mao nga maunat ang kunot."}, "source": "NRC PS3.B; DepEd G6 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "jeepney-horn-blast-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "sound as vibration traveling through air", "grades": [4, 5, 6], "terms": ["busina ng dyip", "dyip", "tunog", "bumibrate", "hangin", "busina", "dyipni", "tingog", "mokurog", "sound waves", "vibration", "horn", "jeepney", "air"], "fact": {"tl": "Ang busina ng dyipni ay gumagawa ng malakas na tunog dahil nagpapayanig ito ng hangin na dumadaloy bilang sound waves patungo sa ating tainga.", "en": "A jeepney's horn makes a loud sound because it vibrates the air, which travels as sound waves to our ears.", "bis": "Ang busina sa dyip naghimo og kusog nga tingog tungod kay nagpakurog kini sa hangin nga molihok isip sound waves padulong sa atong dalunggan."}, "source": "NRC PS4.A; DepEd G5 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "jeepney-stop-passengers-lurch-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "inertia when a vehicle stops", "grades": [6, 7, 8], "terms": ["paghinto ng dyip", "pasahero", "inertia", "sumusulong", "biglang hinto", "pag-undang", "inersya", "pag-unahan", "lurch", "stop", "passengers", "jeepney"], "fact": {"tl": "Kapag biglang huminto ang dyipni, ang mga pasahero ay tila sumusulong pa dahil sa inertia—ang ugali ng katawang gumagalaw na magpatuloy sa paggalaw.", "en": "When a jeepney stops suddenly, the passengers lurch forward because of inertia—a moving body's tendency to keep moving.", "bis": "Kon kalit moundang ang dyip, ang mga pasahero morag mopadayon sa unahan tungod sa inertia—ang kinaiya sa naglihok nga lawas nga magpadayon sa paglihok."}, "source": "NRC PS2.A; DepEd G7 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "kalamansi-rolling-table-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "round shapes roll easily", "grades": [3, 4, 5], "terms": ["kalamansi", "gumugulong", "mesa", "bilog", "puwersa", "gumulong", "lamesa", "lingin", "moligid", "rolling", "round", "calamansi", "table", "force"], "fact": {"tl": "Madaling gumulong ang kalamansi sa mesa kapag tinulak dahil bilog ito at kakaunti ang bahaging dumadikit sa ibabaw.", "en": "A calamansi rolls easily across a table when pushed because it is round and only a small part touches the surface.", "bis": "Sayon moligid ang kalamansi sa lamesa kon tulod tungod kay lingin kini ug gamay ra ang bahin nga modikit sa ibabaw."}, "source": "NRC PS2.A; DepEd G4 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "kaleidoscope-looking-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "reflection of light by mirrors", "grades": [5, 6, 7], "terms": ["kaleidoscope", "salamin", "liwanag", "sinasalamin", "repleksyon", "pattern", "kahayag", "gibanaag", "mirror", "light", "reflection"], "fact": {"tl": "Sa loob ng kaleidoscope, ang mga salamin ay paulit-ulit na sinasalamin ang liwanag at kulay kaya nabubuo ang magaganda at simetrikong pattern.", "en": "Inside a kaleidoscope, mirrors reflect light and color over and over, creating beautiful symmetrical patterns.", "bis": "Sa sulod sa kaleidoscope, ang mga salamin balikbalik nga nagbanaag sa kahayag ug kolor mao nga maporma ang nindot ug simetriko nga mga pattern."}, "source": "NRC PS4.B; DepEd G6 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "karaoke-speaker-sound-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "speakers vibrate to make sound", "grades": [4, 5, 6], "terms": ["karaoke", "ispiker", "tunog", "bumibrate", "hangin", "tingog", "nagkurog", "speaker", "sound", "vibration"], "fact": {"tl": "Ang ispiker ng karaoke ay gumagawa ng tunog dahil ang loob nitong cone ay mabilis na bumibrate at nagpapayanig sa hangin sa paligid.", "en": "A karaoke speaker makes sound because the cone inside it vibrates quickly and shakes the air around it.", "bis": "Ang ispiker sa karaoke naghimo og tingog tungod kay ang cone sa sulod niini paspas nga magkurog ug magpakurog sa hangin sa palibot."}, "source": "NRC PS4.A; DepEd G5 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "karetela-wheel-axle-cart-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "wheel and axle simple machine", "grades": [4, 5, 6], "terms": ["karetela", "gulong", "ehe", "simpleng makina", "kabayo", "ligid", "aksis", "karwahe", "yano nga makina", "wheel and axle", "cart", "simple machine"], "fact": {"tl": "Ang karetela ay gumagamit ng gulong at ehe, isang simpleng makina, para madaling maigulong ang bigat na hila ng kabayo.", "en": "A karetela uses a wheel and axle, a simple machine, so the heavy load pulled by the horse can roll along easily.", "bis": "Ang karetela naggamit og ligid ug aksis, usa ka yano nga makina, aron sayon maligid ang bug-at nga gibira sa kabayo."}, "source": "NRC ETS1; DepEd G5 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "kariton-pushing-uphill-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "force needed to move against gravity", "grades": [5, 6, 7], "terms": ["kariton", "pagtulak", "paakyat", "puwersa", "grabidad", "bigat", "tulod", "tungas", "gravity", "push", "uphill", "cart", "force"], "fact": {"tl": "Mas malakas na puwersa ang kailangan para itulak ang kariton paakyat ng dalisdis dahil kalaban mo ang hila ng grabidad.", "en": "You need a stronger push to move a kariton uphill because you are working against the pull of gravity.", "bis": "Mas kusog nga tulod ang gikinahanglan aron iduso ang kariton patungas tungod kay imong gibatok ang pagbira sa grabidad."}, "source": "NRC PS2.A; DepEd G6 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "kariton-wheel-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "wheels reduce friction", "grades": [3, 4, 5], "terms": ["kariton", "gulong", "puwersa", "madaling itulak", "ligid", "friction", "kuskos", "gikoskos", "wheel", "cart", "push"], "fact": {"tl": "Ang gulong ng kariton ay nakakatulong na madaling maigalaw ang bigat na dala dahil binabawasan nito ang kuskos o friction sa lupa.", "en": "The wheels of a kariton help move a heavy load easily because they reduce the rubbing, or friction, against the ground.", "bis": "Ang mga ligid sa kariton makatabang aron sayon malihok ang bug-at nga gidala tungod kay makunhoran niini ang gikoskos o friction sa yuta."}, "source": "NRC PS2.A; DepEd G4 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "kettle-whistle-steam-energy-g6", "domain": "MATTER", "topic": "boiling water makes steam", "grades": [5, 6, 7], "terms": ["takure", "singaw", "tubig", "kumukulo", "init", "sipol", "kettle", "alisngaw", "nagbukal", "mosipol", "steam", "boiling", "whistle"], "fact": {"tl": "Kapag kumukulo ang tubig sa takure, ito ay nagiging singaw na lumalabas nang mabilis at humihip sa sipol kaya ito tumitili.", "en": "When water boils in a kettle, it turns into steam that rushes out and blows through the whistle, making it whistle.", "bis": "Kon mabukal ang tubig sa kettle, mahimo kining alisngaw nga molagpot paspas ug mohuyop sa sipol mao nga mosipol kini."}, "source": "NRC PS1.A; DepEd G6 Q1", "generator": "claude-workflow", "reviewed": false},
  {"id": "kitchen-weighing-scale-dial-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "spring scale measures weight", "grades": [4, 5, 6], "terms": ["timbangan", "bigat", "spring", "dayal", "timbang", "gibug-aton", "dagom", "umuunat", "maunat", "weighing scale", "weight", "dial"], "fact": {"tl": "Ang timbangan sa kusina ay gumagamit ng spring na umuunat ayon sa bigat ng pagkain, at ipinapakita ng karayom sa dial ang timbang.", "en": "A kitchen weighing scale uses a spring that stretches according to the weight of the food, and the needle on the dial shows the weight.", "bis": "Ang timbangan sa kusina naggamit og spring nga maunat sumala sa gibug-aton sa pagkaon, ug ang dagom sa dial magpakita sa timbang."}, "source": "NRC PS2.B; DepEd G5 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "kite-near-power-line-danger-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "electricity safety near power lines", "grades": [5, 6, 7], "terms": ["saranggola", "linya ng kuryente", "kuryente", "delikado", "kaligtasan", "linya sa koryente", "peligro", "mosaghid", "kite", "power line", "electricity", "safety", "danger"], "fact": {"tl": "Mapanganib magpalipad ng saranggola malapit sa linya ng kuryente dahil kung sumayad ang tali o saranggola, maaaring dumaloy ang kuryente at makapanakit.", "en": "Flying a kite near power lines is dangerous because if the string or kite touches them, electricity can flow through and hurt you.", "bis": "Delikado ang pagpalupad og saranggola duol sa linya sa koryente tungod kay kon mosaghid ang pisi o saranggola, mahimong moagos ang kuryente ug makasakit."}, "source": "NRC PS3.A; DepEd G6 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "lemon-battery-bulb-experiment-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "chemical energy makes a battery", "grades": [6, 7, 8], "terms": ["lemon battery", "baterya", "kuryente", "kemikal na enerhiya", "metal", "bumbilya", "koryente", "kemikal", "duga sa limon", "lemon battery", "chemical energy", "electricity", "bulb"], "fact": {"tl": "Sa lemon battery, ang katas ng limon at dalawang magkaibang metal ay gumagawa ng kemikal na reaksyon na nagbubunga ng maliit na daloy ng kuryente.", "en": "In a lemon battery, the lemon's juice and two different metals make a chemical reaction that produces a small flow of electricity.", "bis": "Sa lemon battery, ang duga sa limon ug duha ka lain-laing metal maghimo og kemikal nga reaksyon nga mohatag og gamay nga agos sa kuryente."}, "source": "NRC PS3.D; DepEd G7 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "lenses-converging-diverging-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "convex and concave lenses bend light", "grades": [7, 8, 9, 10], "terms": ["lente", "convex", "concave", "liwanag", "baluktot", "nagtutuon", "kumakalat", "kahayag", "nagtipon", "nagkatag", "lens", "converging", "diverging", "light", "refraction"], "fact": {"tl": "Ang convex (converging) na lente ay tinitipon ang liwanag sa isang punto, samantalang ang concave (diverging) na lente ay pinakakalat ang liwanag palabas.", "en": "A convex (converging) lens bends light to a single point, while a concave (diverging) lens spreads the light outward.", "bis": "Ang convex (converging) nga lente magtipon sa kahayag ngadto sa usa ka punto, samtang ang concave (diverging) nga lente magkatag sa kahayag pagawas."}, "source": "NRC PS4.B; DepEd G8 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "light-switch-bulb-home-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "switch opens and closes a circuit", "grades": [4, 5, 6], "terms": ["switch", "bombilya", "kuryente", "bukas", "sara", "sirkito", "suga", "koryente", "mosiga", "mapalong", "circuit", "bulb"], "fact": {"tl": "Ang switch sa bahay ay nagsasara at nagbubukas ng daanan ng kuryente, kaya nagliliwanag o namamatay ang bombilya kapag pinindot mo ito.", "en": "A light switch closes and opens the path for electricity, so the bulb lights up or goes dark when you flip it.", "bis": "Ang switch sa balay magsira ug magbukas sa agianan sa kuryente, mao nga mosiga o mapalong ang bombilya kon imong i-flip kini."}, "source": "NRC PS3.B; DepEd G5 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "lightbulb-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "bulb changes electricity to light", "grades": [4, 5, 6], "terms": ["bombilya", "ilaw", "kuryente", "liwanag", "init", "filament", "suga", "koryente", "kahayag", "mosiga", "light bulb", "electricity", "light"], "fact": {"tl": "Ang bombilya ay nagbibigay ng liwanag dahil ang kuryenteng dumadaan sa manipis na filament nito ay nagpapainit at nagpapaningning dito.", "en": "A light bulb gives off light because the electricity passing through its thin filament heats it until it glows.", "bis": "Ang bombilya naghatag og kahayag tungod kay ang kuryente nga moagi sa nipis nga filament niini magpainit niini hangtod nga mosiga."}, "source": "NRC PS3.A; DepEd G5 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "lightning-rod-house-protection-g7", "domain": "EARTH_SPACE", "topic": "lightning rod protects buildings", "grades": [6, 7, 8], "terms": ["lightning rod", "kidlat", "bahay", "proteksyon", "kuryente", "lupa", "baras sa kilat", "kilat", "balay", "panalipod", "yuta", "lightning", "protection", "grounding"], "fact": {"tl": "Ang lightning rod sa bubong ng bahay ay tumatanggap ng kidlat at ligtas na dinadala ang kuryente nito pababa sa lupa, kaya hindi nasusunog ang bahay.", "en": "A lightning rod on a roof catches lightning and safely carries its electricity down into the ground, protecting the house from catching fire.", "bis": "Ang lightning rod sa atop sa balay magdawat sa kilat ug luwas nga magdala sa kuryente niini paubos sa yuta, mao nga dili masunog ang balay."}, "source": "NRC PS3.A; DepEd G7 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "machine-pulley-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "pulley simple machine", "grades": [4, 5, 6], "terms": ["kalo", "pulley", "simpleng makina", "puwersa", "pagtaas", "bigat", "lubid", "yano nga makina", "kusog", "pisi", "lift", "force"], "fact": {"tl": "Ang kalo o pulley ay isang simpleng makina na may gulong at lubid na nagpapadali sa pagtaas ng bigat sa pamamagitan ng pagbabago ng direksyon ng puwersa.", "en": "A pulley is a simple machine with a wheel and rope that makes lifting heavy loads easier by changing the direction of your force.", "bis": "Ang pulley usa ka yano nga makina nga adunay ligid ug pisi nga magpasayon sa pag-alsa og bug-at pinaagi sa pag-usab sa direksyon sa imong kusog."}, "source": "NRC ETS1; DepEd G5 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "maglev-train-magnet-levitation-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "magnetic levitation", "grades": [7, 8, 9, 10], "terms": ["maglev", "tren", "magnet", "lumulutang", "magkatulad na poste", "nagtutulakan", "magnetiko", "naglutaw", "magtinulakanay", "levitation", "magnet", "train", "repel"], "fact": {"tl": "Ang maglev na tren ay lumulutang sa ibabaw ng riles dahil ang magkatulad na poste ng magnet ay nagtutulakan, kaya halos walang friction at napakabilis nito.", "en": "A maglev train floats above its track because like magnetic poles push apart, so there is almost no friction and it can go very fast.", "bis": "Ang maglev nga tren maglutaw ibabaw sa riles tungod kay ang managsamang poste sa magnet magtinulakanay, mao nga halos walay friction ug paspas kaayo kini."}, "source": "NRC PS2.B; DepEd G8 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnet-and-paperclips-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "magnets attract iron objects", "grades": [3, 4, 5], "terms": ["magnet", "paperclip", "bakal", "humihila", "magnetiko", "klip", "puthaw", "nagbira", "attract", "iron"], "fact": {"tl": "Ang magnet ay humihila at kumakapit sa mga paperclip dahil ang mga ito ay gawa sa bakal, na isang materyal na nahihila ng magnet.", "en": "A magnet attracts and holds paperclips because they are made of iron, a material that magnets pull on.", "bis": "Ang magnet magbira ug mokapyot sa mga paperclip tungod kay hinimo kini sa puthaw, usa ka materyal nga birahon sa magnet."}, "source": "NRC PS2.B; DepEd G4 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnet-horseshoe-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "horseshoe magnet has two poles", "grades": [4, 5, 6], "terms": ["horseshoe magnet", "magnet", "poste", "hilahin", "bakal", "dulo", "puthaw", "tumoy", "poles", "attract", "iron"], "fact": {"tl": "Ang horseshoe na magnet ay hugis-U at may dalawang poste sa magkabilang dulo, kaya mas malakas itong humila ng bakal kaysa sa tuwid na magnet.", "en": "A horseshoe magnet is U-shaped with its two poles at the ends, so it can pull iron more strongly than a straight bar magnet.", "bis": "Ang horseshoe nga magnet hulagway-U nga adunay duha ka poste sa matag tumoy, mao nga mas kusog kining mobira og puthaw kaysa sa tul-id nga magnet."}, "source": "NRC PS2.B; DepEd G5 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnet-picking-up-nails-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "magnetic attraction on iron nails", "grades": [3, 4, 5], "terms": ["magnet", "pako", "bakal", "humihila", "magnetiko", "lansang", "puthaw", "nagbira", "nails", "iron", "attract"], "fact": {"tl": "Madaling mapupulot ng magnet ang mga pakong bakal nang hindi kinakailangang hawakan, dahil humihila ito ng mga bagay na gawa sa bakal.", "en": "A magnet can pick up iron nails without you touching them, because it pulls on things made of iron.", "bis": "Ang magnet sayon makapunit sa mga lansang nga puthaw bisan dili nimo hikapon, tungod kay magbira kini sa mga butang nga hinimo sa puthaw."}, "source": "NRC PS2.B; DepEd G4 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnet-strength-paperclip-chain-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "magnetic force passes through objects", "grades": [4, 5, 6], "terms": ["lakas ng magnet", "kadena ng paperclip", "magnetiko", "dumadaloy", "bakal", "kusog sa magnet", "kadena", "moagi", "magnetic force", "paperclip chain"], "fact": {"tl": "Ang isang malakas na magnet ay kayang humawak ng kadena ng mga paperclip dahil ang puwersang magnetiko ay dumadaloy mula sa isang klip patungo sa susunod.", "en": "A strong magnet can hold a chain of paperclips because the magnetic force passes from one clip to the next.", "bis": "Ang kusgan nga magnet makakupot og kadena sa mga paperclip tungod kay ang pwersang magnetiko moagi gikan sa usa ka klip ngadto sa sunod."}, "source": "NRC PS2.B; DepEd G5 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnet-through-materials-test-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "magnetism passes through non-metal materials", "grades": [5, 6, 7], "terms": ["magnet", "papel", "tela", "plastik", "dumadaan", "puwersa", "magnetiko", "panapton", "muagi", "babag", "through materials", "magnetic field"], "fact": {"tl": "Ang puwersa ng magnet ay kayang dumaan sa manipis na papel, tela, o plastik, kaya naaakit pa rin nito ang klip kahit may hadlang.", "en": "A magnet's force can pass through thin paper, cloth, or plastic, so it can still attract a clip even with a barrier in between.", "bis": "Ang pwersa sa magnet makaagi sa nipis nga papel, panapton, o plastik, mao nga makabira gihapon kini og klip bisan adunay babag."}, "source": "NRC PS2.B; DepEd G6 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnetic-cabinet-door-latch-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "magnets used in everyday latches", "grades": [4, 5, 6], "terms": ["magnetic latch", "pinto ng kabinet", "magnet", "kumakapit", "sara", "trangka sa pultahan", "kabinet", "mokapyot", "sirado", "cabinet latch", "door", "close"], "fact": {"tl": "Ang pinto ng ilang kabinet ay may maliit na magnet na nakakapit sa metal na plato kaya nananatiling sarado ang pinto.", "en": "Some cabinet doors have a small magnet that grips a metal plate, which keeps the door held shut.", "bis": "Ang pultahan sa ubang kabinet adunay gamay nga magnet nga mokapyot sa metal nga plato mao nga magpabilin kining sirado."}, "source": "NRC PS2.B; DepEd G5 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnetic-test-objects-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "some materials are magnetic, others not", "grades": [3, 4, 5], "terms": ["magnetiko", "hindi magnetiko", "bakal", "plastik", "goma", "pagsubok", "subok", "dili magnetiko", "puthaw", "kahoy", "magnetic", "non-magnetic", "test"], "fact": {"tl": "Kapag sinubukan mo ang iba't ibang bagay gamit ang magnet, ang mga gawa sa bakal ay nahihila, ngunit ang plastik, goma, at kahoy ay hindi.", "en": "When you test different objects with a magnet, those made of iron are attracted, but plastic, rubber, and wood are not.", "bis": "Kon imong sulayan ang lain-laing butang gamit ang magnet, ang hinimo sa puthaw mabira, apan ang plastik, goma, ug kahoy dili."}, "source": "NRC PS2.B; DepEd G4 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnifier-burn-paper-sun-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "convex lens concentrates sunlight", "grades": [6, 7, 8], "terms": ["magnifying glass", "lente", "araw", "sinunog", "papel", "tinipon na liwanag", "adlaw", "gisunog", "sidlak", "convex lens", "sunlight", "focus", "burn"], "fact": {"tl": "Ang magnifying glass ay kayang magtipon ng sinag ng araw sa isang maliit na punto kung saan napakainit nito, kaya kayang sunugin ang papel.", "en": "A magnifying glass can gather the sun's rays into one tiny point so hot that it can burn paper.", "bis": "Ang magnifying glass makahimo og pagtipon sa sidlak sa adlaw ngadto sa usa ka gamay nga punto nga init kaayo, mao nga makasunog kini og papel."}, "source": "NRC PS4.B; DepEd G7 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "marble-ramp-speed-track-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "marble rolling down a ramp gains speed", "grades": [4, 5, 6], "terms": ["holen", "marble", "rampa", "ramp", "dahilig", "slope", "bumibilis", "tumutulin", "speed", "tulin", "bilis", "gulong pababa", "gravity", "grabidad", "kusog", "paspas", "nagdagan", "rolling down"], "fact": {"tl": "Kapag pinagulong mo ang holen sa isang nakatagilid na rampa, bumibilis ito habang bumababa dahil hinihila ito pababa ng grabidad.", "en": "When you roll a marble down a tilted ramp, it speeds up as it goes down because gravity pulls it downward.", "bis": "Kon paligiron nimo ang holen sa usa ka hilig nga rampa, mokusog kini samtang manaog kay birahon kini paubos sa grabidad."}, "source": "NRC PS2.A; DepEd G5 Force and Motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "megaphone-sound-amplify-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "megaphone makes sound louder and directs it", "grades": [4, 5, 6], "terms": ["megaphone", "megapono", "pasalita", "tunog", "sound", "lakas ng tunog", "loud", "malakas", "kusog sa tingog", "tingog", "nagpapalakas", "amplify", "boses", "voice", "nakaturo", "direksyon", "alon ng tunog", "sound waves"], "fact": {"tl": "Pinalalakas ng megaphone ang boses sa pamamagitan ng pagdiretso ng alon ng tunog pasulong sa isang direksyon sa halip na kumalat sa lahat ng panig.", "en": "A megaphone makes a voice louder by directing the sound waves forward in one direction instead of letting them spread out everywhere.", "bis": "Ang megaphone nagapakusog sa tingog pinaagi sa pagtumong sa mga balod sa tingog paatubang sa usa ka direksyon imbes nga mokatag kini sa tanang dapit."}, "source": "NRC PS4.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "merry-go-round-push-spin-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "pushing makes a merry-go-round spin", "grades": [3, 4, 5], "terms": ["merry-go-round", "karusel", "carousel", "pagtulak", "tulak", "push", "umiikot", "ikot", "spin", "rotate", "nagliliko", "tuyok", "nagtuyok", "duso", "puwersa", "force", "umiikot na laro"], "fact": {"tl": "Umiikot ang merry-go-round kapag tinutulak mo ito, at lalo itong bumibilis sa bawat tulak na ibinibigay mo.", "en": "A merry-go-round spins when you push it, and it spins faster with each push you give.", "bis": "Ang merry-go-round motuyok kon duslon nimo kini, ug mas mokusog kini sa matag duso nga imong ihatag."}, "source": "NRC PS2.A; DepEd G4 Force and Motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "metal-spoon-hot-soup-conduction-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "heat conduction up a metal spoon", "grades": [5, 6, 7], "terms": ["kutsara", "spoon", "metal", "bakal", "mainit na sabaw", "hot soup", "init", "heat", "conduction", "pagdaloy ng init", "kumukuha ng init", "uminit", "nagiging mainit", "nahukot", "pagtutok sa init", "nagpapadaloy"], "fact": {"tl": "Kapag inilubog mo ang metal na kutsara sa mainit na sabaw, dumadaloy ang init sa metal pataas kaya umiinit pati ang hawakan nito.", "en": "When you leave a metal spoon in hot soup, heat travels up through the metal by conduction so even the handle becomes warm.", "bis": "Kon ibutang nimo ang puthaw nga kutsara sa init nga sabaw, ang kainit moagi paibabaw sa metal pinaagi sa konduksiyon mao nga moinit bisan ang kuptanan niini."}, "source": "NRC PS3.B; DepEd G6 Heat", "generator": "claude-workflow", "reviewed": false},
  {"id": "mirror-reflection-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "a mirror reflects light to form an image", "grades": [4, 5, 6], "terms": ["salamin", "mirror", "repleksyon", "reflection", "liwanag", "ilaw", "light", "kahaba", "imahe", "image", "anino", "nakikita", "salamin sa mukha", "kasanag", "kahayag", "nagsasalamin", "nagbabalik ng liwanag", "bumabalik"], "fact": {"tl": "Nakikita mo ang sarili mo sa salamin dahil ibinabalik o ini-reflect nito ang liwanag na tumama dito pabalik sa iyong mga mata.", "en": "You can see yourself in a mirror because it reflects the light that hits it back toward your eyes.", "bis": "Makita nimo ang imong kaugalingon sa salamin tungod kay ibalik o i-reflect niini ang kahayag nga miigo niini balik sa imong mga mata."}, "source": "NRC PS4.B; DepEd G5 Light", "generator": "claude-workflow", "reviewed": false},
  {"id": "mirrors-concave-convex-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "concave vs convex mirrors and the images they form", "grades": [7, 8, 9], "terms": ["salamin", "mirror", "concave", "convex", "kurbado paloob", "kurbado palabas", "salaming kurbado", "nakalubog", "nakaumbok", "curved mirror", "imahe", "image", "naglalaki", "magnify", "nagpapaliit", "repleksyon", "reflection", "side mirror", "fokus"], "fact": {"tl": "Ang concave (kurbadong paloob) na salamin ay maaaring magpalaki ng imahe gaya sa shaving mirror, habang ang convex (kurbadong palabas) na salamin ay nagpapaliit at nagpapalawak ng tanaw gaya sa side mirror ng sasakyan.", "en": "A concave (inward-curved) mirror can magnify an image like a shaving mirror, while a convex (outward-curved) mirror shrinks the view and widens it like a car's side mirror.", "bis": "Ang concave (nakurba pasulod) nga salamin makapadako sa imahe sama sa shaving mirror, samtang ang convex (nakurba pagawas) nga salamin nagapagamay ug nagapalapad sa panan-aw sama sa side mirror sa sakyanan."}, "source": "NRC PS4.B; DepEd G8 Light and Mirrors", "generator": "claude-workflow", "reviewed": false},
  {"id": "motion-graphs-distance-time-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "reading a distance-time motion graph", "grades": [7, 8, 9], "terms": ["motion graph", "graph ng galaw", "distansya", "distance", "oras", "time", "tulin", "speed", "bilis", "slope", "linya", "line", "patag na linya", "nakatigil", "tumatarik", "steep", "grap sa lihok", "gilay-on", "nagpapakita ng galaw"], "fact": {"tl": "Sa isang distance-time graph, ipinapakita ng mas matarik na linya ang mas mabilis na galaw, at ang patag na linya naman ay nangangahulugang nakatigil ang bagay.", "en": "On a distance-time graph, a steeper line shows faster motion, while a flat line means the object is not moving.", "bis": "Sa usa ka distance-time graph, ang mas tarik nga linya nagpakita sa mas paspas nga lihok, samtang ang patag nga linya nagpasabot nga ang butang wala maglihok."}, "source": "NRC PS2.A; DepEd G7 Motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "nipa-roof-keeping-cool-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "nipa roof keeps a house cool", "grades": [5, 6, 7], "terms": ["pawid", "nipa", "kogon", "atip", "bubong", "roof", "bahay kubo", "nipa hut", "lamig", "cool", "malamig", "init", "heat", "insulator", "hindi nagpapadaloy ng init", "presko", "hangin", "ventilation", "nagpapalamig", "atop"], "fact": {"tl": "Pinananatiling malamig ng bubong na pawid o nipa ang loob ng bahay-kubo dahil mahina itong magpadaloy ng init mula sa araw at hinahayaan nitong dumaan ang hangin.", "en": "A nipa or thatch roof keeps a hut cool inside because it is a poor conductor of the sun's heat and it lets air pass through.", "bis": "Ang atop nga nipa o kogon nagapabugnaw sa sulod sa payag tungod kay maluya kini nga magpaagi sa kainit gikan sa adlaw ug gitugotan niini nga moagi ang hangin."}, "source": "NRC PS3.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "nutcracker-cracking-nut-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "a nutcracker is a lever that multiplies force", "grades": [5, 6, 7], "terms": ["nutcracker", "pambasag ng mani", "lever", "palanca", "puwersa", "force", "balat", "shell", "mani", "nut", "nababasag", "crack", "pisil", "diin", "nagpapalakas ng puwersa", "simpleng makina", "simple machine", "palya", "pingot"], "fact": {"tl": "Ang nutcracker ay isang uri ng palanca na nagpapalakas ng puwersa ng iyong kamay upang madaling mabasag ang matigas na balat ng mani.", "en": "A nutcracker is a type of lever that multiplies the force of your hand so it can easily crack a nut's hard shell.", "bis": "Ang nutcracker usa ka matang sa palanca nga nagapakusog sa puwersa sa imong kamot aron sayon nga mabuak ang gahi nga panit sa mani."}, "source": "NRC PS2.A; DepEd G5 Simple Machines", "generator": "claude-workflow", "reviewed": false},
  {"id": "ohms-law-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "Ohm's law relates voltage, current, and resistance", "grades": [8, 9, 10], "terms": ["ohm's law", "batas ni ohm", "boltahe", "voltage", "boltage", "kuryente", "current", "agos", "resistance", "resistensya", "ampere", "ohm", "volt", "sirkito", "circuit", "elektrisidad", "electricity", "balaod ni ohm", "koryente"], "fact": {"tl": "Ayon sa Batas ni Ohm, ang dami ng kuryenteng dumadaloy sa isang sirkito ay katumbas ng boltahe na hinati sa resistensya (I = V/R).", "en": "Ohm's law states that the current flowing in a circuit equals the voltage divided by the resistance (I = V/R).", "bis": "Sumala sa Balaod ni Ohm, ang gidaghanon sa koryente nga moagi sa usa ka sirkito katumbas sa boltahe nga gibahin sa resistensya (I = V/R)."}, "source": "encyclopedia-stable consensus; DepEd G9 Electricity", "generator": "claude-workflow", "reviewed": false},
  {"id": "palay-drying-sun-heat-g5", "domain": "EARTH_SPACE", "topic": "drying palay in the sun removes water by evaporation", "grades": [4, 5, 6], "terms": ["palay", "bigas", "rice", "ani", "pagbibilad", "bilad", "drying", "araw", "init ng araw", "sun heat", "sikat ng araw", "tuyo", "dry", "natuyo", "singaw", "evaporation", "tubig", "moisture", "halamigway", "paghulaw", "bulad"], "fact": {"tl": "Ibinibilad ang palay sa init ng araw upang sumingaw ang tubig sa loob nito, sapagkat ang tuyong butil ay hindi madaling mabulok o amagin.", "en": "Palay is spread out under the sun's heat so the water inside it evaporates, because dry grain does not easily rot or grow mold.", "bis": "Ang humay ibulad ilalom sa kainit sa adlaw aron mosingaw ang tubig sa sulod niini, kay ang uga nga lugas dili dali madunot o aguhon."}, "source": "NRC PS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "paper-airplane-distance-test-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "what makes a paper airplane fly farther", "grades": [4, 5, 6], "terms": ["paper airplane", "eroplanong papel", "eroplano", "lumilipad", "fly", "lipad", "layo", "distance", "hangin", "air", "lift", "drag", "hugis", "shape", "pakpak", "wings", "lumipad", "eroplanong papil", "naglupad", "agos ng hangin"], "fact": {"tl": "Mas malayo ang lipad ng eroplanong papel kapag pantay at makinis ang pakpak nito, dahil mas madulas itong dumaan sa hangin nang may kaunting hadlang.", "en": "A paper airplane flies farther when its wings are even and smooth, because it slips through the air with less resistance.", "bis": "Mas layo molupad ang eroplanong papel kon patas ug hamis ang mga pako niini, kay mas hapsay kini nga moagi sa hangin nga gamay ra ang babag."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "paper-boat-gutter-flow-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "flowing water carries a paper boat along", "grades": [3, 4, 5], "terms": ["paper boat", "barkong papel", "bangkang papel", "kanal", "alulod", "gutter", "agos", "flow", "umaagos na tubig", "lumulutang", "float", "lutang", "dala ng tubig", "naglutaw", "sapa", "current", "ulan", "rain", "naanod"], "fact": {"tl": "Lumulutang ang bangkang papel sa ibabaw ng tubig at dinadala ito ng umaagos na tubig sa kanal patungo sa direksyon ng agos.", "en": "A paper boat floats on top of the water and the flowing water in a gutter carries it along in the direction of the current.", "bis": "Ang bangkang papel naglutaw sa ibabaw sa tubig ug ang nagdagayday nga tubig sa kanal magdala niini paingon sa direksyon sa sulog."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "paperclip-magnetism-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "a magnet attracts a steel paperclip", "grades": [3, 4, 5], "terms": ["paperclip", "klip ng papel", "ipit ng papel", "magnet", "bakal", "metal", "steel", "nahihila", "attract", "nadidikit", "magnetism", "magnetismo", "puwersa", "force", "nadakup", "pagkabit", "naakit", "bakal nga klip"], "fact": {"tl": "Nahihila ng magnet ang paperclip na yari sa bakal dahil ang bakal ay isa sa mga metal na umaakit sa magnet.", "en": "A magnet attracts a paperclip made of steel because steel is one of the metals that a magnet pulls toward itself.", "bis": "Ang magnet mobira sa paperclip nga hinimo sa puthaw kay ang puthaw usa sa mga metal nga ginabira sa magnet."}, "source": "NRC PS2.B; DepEd G4 Magnets", "generator": "claude-workflow", "reviewed": false},
  {"id": "parachute-toy-drop-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "a parachute slows a falling object with air resistance", "grades": [4, 5, 6], "terms": ["parachute", "parasyut", "payong", "nahuhulog", "fall", "hulog", "bagal", "slow", "humihina ang bagsak", "hangin", "air", "air resistance", "hadlang ng hangin", "grabidad", "gravity", "dahan-dahan", "lumalapad", "drag", "nahulog", "nahagba"], "fact": {"tl": "Pinabababa nang mas dahan-dahan ng parachute ang isang bagay dahil hinahadlangan ng malawak nitong tela ang hangin habang bumababa ito.", "en": "A parachute lets an object fall more slowly because its wide cloth pushes against the air as it comes down.", "bis": "Ang parachute nagahimo sa usa ka butang nga mahinay nga manaog kay ang lapad niini nga panapton mosukol sa hangin samtang nagkanaog kini."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "parol-series-lights-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "Christmas parol lights wired in series", "grades": [7, 8, 9], "terms": ["parol", "Christmas lights", "ilaw ng parol", "series", "serye", "sirkito", "circuit", "kuryente", "current", "bombilya", "bulb", "ilaw", "namamatay lahat", "namatay", "series circuit", "nagkakadena", "kawad", "wire", "namatay ang ilaw"], "fact": {"tl": "Kapag nakakabit sa serye ang mga ilaw ng parol, dumadaan ang kuryente sa isang daan lamang kaya kapag napatay ang isang bombilya, namamatay ang lahat ng ilaw.", "en": "When parol lights are wired in series, the current flows through a single path so if one bulb burns out, all the lights go dark.", "bis": "Kon nakakabit sa serye ang mga suga sa parol, ang koryente moagi sa usa ra ka dalan mao nga kon mapalong ang usa ka bombilya, mapalong ang tanang suga."}, "source": "encyclopedia-stable consensus; DepEd G8 Electric Circuits", "generator": "claude-workflow", "reviewed": false},
  {"id": "pedal-power-bike-light-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "a bicycle dynamo turns motion into electricity", "grades": [6, 7, 8], "terms": ["pedal", "bisikleta", "bicycle", "dynamo", "dinamo", "ilaw ng bisikleta", "bike light", "kuryente", "electricity", "elektrisidad", "galaw", "motion", "umiikot na gulong", "generator", "henerador", "nagiging kuryente", "nagliliwanag", "pagtapak"], "fact": {"tl": "Ang dynamo ng bisikleta ay nagiging kuryente ang paggalaw ng umiikot na gulong, kaya nagliliwanag ang ilaw habang nagpepedal ka.", "en": "A bicycle dynamo turns the motion of the spinning wheel into electricity, so the light glows while you pedal.", "bis": "Ang dynamo sa bisikleta nagahimo sa lihok sa nagatuyok nga ligid ngadto sa koryente, mao nga modan-ag ang suga samtang nagpedal ka."}, "source": "NRC PS3.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pedicab-pulling-load-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "wheels reduce friction so a pedicab is easier to move", "grades": [4, 5, 6], "terms": ["pedicab", "padyak", "traysikad", "sidecar", "gulong", "wheel", "puwersa", "force", "hila", "pull", "kargada", "load", "friction", "kuskos", "alitan", "umiikot", "mas madali", "gulong nakakabawas", "naghatag karga"], "fact": {"tl": "Mas madaling itulak o hilahin ang pedicab na may pasahero dahil binabawasan ng umiikot na gulong ang friction sa pagitan ng sasakyan at lupa.", "en": "A loaded pedicab is easier to push or pull because its rolling wheels reduce the friction between the vehicle and the ground.", "bis": "Mas sayon iduso o birahon ang pedicab nga adunay pasahero kay ang nagatuyok nga ligid nagapakunhod sa friction tali sa sakyanan ug sa yuta."}, "source": "NRC PS2.A; DepEd G5 Friction", "generator": "claude-workflow", "reviewed": false},
  {"id": "pendulum-swing-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "a pendulum's swing depends on its length", "grades": [6, 7, 8], "terms": ["pendulum", "palawit", "pendulo", "nakabitin", "swing", "ugoy", "umuugoy", "haba", "length", "tali", "string", "bigat", "bob", "grabidad", "gravity", "balik-balik", "period", "panahon ng ugoy", "naglugway", "nagsumbalik"], "fact": {"tl": "Ang bilis ng pag-ugoy ng pendulum ay nakadepende sa haba ng tali nito—mas mahaba ang tali, mas mabagal ang pag-ugoy.", "en": "How fast a pendulum swings depends on the length of its string—the longer the string, the slower the swing.", "bis": "Ang kapaspas sa pag-uyog sa pendulum nagdepende sa gitas-on sa pisi niini—mas taas ang pisi, mas hinay ang pag-uyog."}, "source": "encyclopedia-stable consensus; DepEd G7 Motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "periscope-mirror-light-path-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "a periscope uses two mirrors to see over obstacles", "grades": [6, 7, 8], "terms": ["periscope", "periskopyo", "salamin", "mirror", "dalawang salamin", "two mirrors", "liwanag", "light", "ilaw", "repleksyon", "reflection", "nakatingin pataas", "submarine", "submarino", "tumitingin", "daan ng liwanag", "bumabaling", "nakatagilid", "tan-aw"], "fact": {"tl": "Gumagamit ang periscope ng dalawang nakatagilid na salamin upang ibaling ang liwanag, kaya nakikita mo ang bagay na nasa itaas o likod ng harang.", "en": "A periscope uses two angled mirrors to bend light, so you can see an object that is above or behind a barrier.", "bis": "Ang periscope nagagamit og duha ka tinakilid nga salamin aron ipaliko ang kahayag, mao nga makita nimo ang butang nga anaa sa ibabaw o luyo sa babag."}, "source": "NRC PS4.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pinhole-eclipse-projector-g6", "domain": "EARTH_SPACE", "topic": "a pinhole projector safely views a solar eclipse", "grades": [5, 6, 7], "terms": ["pinhole", "butas-karayom", "eclipse", "eklipse", "eklipse ng araw", "solar eclipse", "projector", "proyektor", "liwanag", "light", "araw", "sun", "ligtas na panonood", "imahe", "image", "anino", "nakaprotekta sa mata", "kahayag", "butas"], "fact": {"tl": "Sa isang pinhole projector, dumadaan ang liwanag ng araw sa maliit na butas at gumuguhit ng maliit na imahe ng araw sa papel, kaya ligtas mong mapapanood ang eklipse nang hindi tinitingnan nang direkta ang araw.", "en": "In a pinhole projector, sunlight passes through a tiny hole and casts a small image of the sun on paper, letting you watch an eclipse safely without looking straight at the sun.", "bis": "Sa usa ka pinhole projector, ang kahayag sa adlaw moagi sa gamay nga lungag ug magpakita og gamay nga imahe sa adlaw sa papel, mao nga luwas nimong matan-aw ang eklipse nga dili magtan-aw diretso sa adlaw."}, "source": "encyclopedia-stable consensus; DepEd G6 Eclipses", "generator": "claude-workflow", "reviewed": false},
  {"id": "pliers-gripping-wire-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "pliers are a lever that increases gripping force", "grades": [5, 6, 7], "terms": ["pliers", "plais", "alikate", "lever", "palanca", "kawad", "wire", "puwersa", "force", "hawak", "grip", "pagpiga", "pisil", "nagpapalakas", "kamay", "simpleng makina", "simple machine", "hawak na hiwalay", "kumakapit"], "fact": {"tl": "Ang pliers ay isang palanca na nagpapalakas sa pisil ng iyong kamay, kaya nahahawakan at nababaluktot nito nang mahigpit ang matigas na kawad.", "en": "Pliers are a lever that increases the squeeze of your hand, so they can grip and bend a stiff wire tightly.", "bis": "Ang plais usa ka palanca nga nagapakusog sa pugong sa imong kamot, mao nga makakupot ug makabawog kini sa gahi nga alambre og hugot."}, "source": "NRC PS2.A; DepEd G5 Simple Machines", "generator": "claude-workflow", "reviewed": false},
  {"id": "plumbing-water-faucet-pressure-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "water pressure pushes water out of a faucet", "grades": [5, 6, 7], "terms": ["gripo", "faucet", "tubo", "pipe", "tubig", "water", "presyon ng tubig", "water pressure", "diin sa tubig", "lumalabas", "flow", "agos", "tangke", "tank", "elebasyon", "nagbubuga", "umaagos", "naghaguros", "pagbukas ng gripo", "lakas ng tubig"], "fact": {"tl": "Lumalabas ang tubig sa gripo dahil itinutulak ito ng presyon ng tubig mula sa mas mataas na tangke o mula sa makina ng tubig.", "en": "Water comes out of a faucet because water pressure pushes it along, often from a higher tank or a water pump.", "bis": "Mogawas ang tubig sa gripo tungod kay giduso kini sa presyon sa tubig, kasagaran gikan sa mas taas nga tangke o gikan sa bomba sa tubig."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "power-line-post-street-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "power lines carry electricity from plants to homes", "grades": [6, 7, 8], "terms": ["power line", "kawad ng kuryente", "poste", "post", "linya ng kuryente", "kuryente", "electricity", "elektrisidad", "kawad", "wire", "planta", "power plant", "bahay", "homes", "transmission", "naghahatid", "nagdadala ng kuryente", "linya sa koryente", "linya sa kalye"], "fact": {"tl": "Ang mga kawad sa poste ng kuryente ay naghahatid ng elektrisidad mula sa power plant patungo sa mga bahay, paaralan, at tindahan sa kalye.", "en": "The wires on power-line posts carry electricity from the power plant to the homes, schools, and shops along the street.", "bis": "Ang mga alambre sa poste sa kuryente nagahatod sa elektrisidad gikan sa power plant ngadto sa mga balay, eskwelahan, ug tindahan sa kadalanan."}, "source": "NRC PS3.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "projectile-motion-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "a projectile follows a curved path under gravity", "grades": [8, 9, 10], "terms": ["projectile", "proyektil", "projectile motion", "galaw na proyektil", "kurba", "curved path", "arko", "trajectory", "grabidad", "gravity", "ipinukol", "thrown", "ibinato", "naghuhulog", "pataas pasulong", "bola", "ball", "parabola", "naglupad", "gilabay"], "fact": {"tl": "Kapag may bagay na ipinukol pasulong, sabay itong gumagalaw pasulong at hinihila pababa ng grabidad, kaya sumusunod ito sa hugis-arkong landas bago bumagsak.", "en": "When an object is thrown forward, it moves forward while gravity pulls it down at the same time, so it follows a curved, arc-shaped path before it lands.", "bis": "Kon adunay butang nga ilabay paatubang, mokilos kini paatubang samtang birahon kini paubos sa grabidad, mao nga mosunod kini sa kurbado nga dalan nga sama sa arko sa dili pa kini matumba."}, "source": "encyclopedia-stable consensus; DepEd G9 Projectile Motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "ramp-loading-sacks-truck-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "a ramp is an inclined plane that eases lifting", "grades": [4, 5, 6], "terms": ["rampa", "ramp", "inclined plane", "dahilig na patag", "sako", "sacks", "trak", "truck", "puwersa", "force", "pagbuhat", "lift", "pagtulak", "push", "mas madali", "simpleng makina", "simple machine", "naghahatag-bigat", "pababa pataas", "iangat"], "fact": {"tl": "Mas madaling iangat ang mabibigat na sako sa trak kapag itinutulak ang mga ito sa isang rampa, dahil ang rampa ay isang dahilig na patag na nagpapaliit ng kailangang puwersa.", "en": "Heavy sacks are easier to get onto a truck by pushing them up a ramp, because a ramp is an inclined plane that reduces the force needed.", "bis": "Mas sayon ipataas ang bug-at nga mga sako ngadto sa trak kon iduso kini sa usa ka rampa, kay ang rampa usa ka hilig nga patag nga nagapakunhod sa gikinahanglan nga puwersa."}, "source": "NRC PS2.A; DepEd G5 Simple Machines", "generator": "claude-workflow", "reviewed": false},
  {"id": "rice-cooker-electric-to-heat-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "a rice cooker changes electrical energy into heat", "grades": [5, 6, 7], "terms": ["rice cooker", "rice kuker", "panlutong kanin", "kuryente", "electricity", "electrical energy", "enerhiya ng kuryente", "init", "heat", "thermal energy", "nagluluto", "cook", "kanin", "rice", "nagiging init", "transpormasyon ng enerhiya", "energy transformation", "uminit", "elemento ng init"], "fact": {"tl": "Ang rice cooker ay nagpapalit ng enerhiya ng kuryente tungo sa init, at ginagamit ang init na ito upang lutuin ang kanin.", "en": "A rice cooker changes electrical energy into heat energy, and uses that heat to cook the rice.", "bis": "Ang rice cooker nagausab sa enerhiya sa koryente ngadto sa init, ug gigamit kini nga init aron lutoon ang kan-on."}, "source": "NRC PS3.A; DepEd G6 Energy Transformation", "generator": "claude-workflow", "reviewed": false},
  {"id": "rolling-ball-friction-grass-tile-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "friction slows a rolling ball", "grades": [4, 5], "terms": ["bola", "gumugulong", "kuskusan", "friksyon", "damo", "tile", "humihinto", "bola nga nagligid", "pagligid", "kuskos", "balili", "rolling ball", "friction", "grass", "tile floor", "slows down", "stops"], "fact": {"tl": "Ang bolang gumugulong sa damo ay mas mabilis humihinto kaysa sa makinis na tile dahil mas malakas ang friksyon o kuskusan sa magaspang na damo.", "en": "A ball rolling on grass stops sooner than one on smooth tile because the rough grass creates more friction to slow it down.", "bis": "Ang bola nga nagligid sa balili mas paspas mohunong kay sa hamis nga tile tungod kay mas kusog ang friction o kuskos sa gahi nga balili."}, "source": "NRC PS2.A forces and motion; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rough-vs-smooth-ramp-roll-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "surface roughness affects rolling distance", "grades": [4, 5], "terms": ["magaspang", "makinis", "rampa", "dahilig", "gumugulong", "layo", "friksyon", "surface", "gaspang", "hamis", "tabok", "bangbang", "rough surface", "smooth ramp", "roll farther", "friction"], "fact": {"tl": "Ang bolang pinagulong sa makinis na rampa ay umaabot nang mas malayo kaysa sa magaspang na rampa dahil mas kaunti ang friksyong humahadlang dito.", "en": "A ball rolls farther down a smooth ramp than a rough one because the smooth surface has less friction to hold it back.", "bis": "Ang bola nga giligid sa hamis nga tabok molagbas og mas layo kay sa gahi nga tabok tungod kay gamay ra ang friction nga nagpugong niini."}, "source": "NRC PS2.A forces and motion; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rubber-band-guitar-pitch-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "tightness changes sound pitch", "grades": [4, 5, 6], "terms": ["goma", "rubber band", "gitara", "tunog", "taas ng tono", "pitch", "hinila", "vibration", "bibrasyon", "lastiko", "gitara nga lastiko", "kahugot", "tono sa tingog", "tinis", "tight string", "high pitch", "vibrate"], "fact": {"tl": "Kapag mas hinihila o hinihigpitan ang isang goma na ginagawang gitara, mas mataas ang tono ng tunog na nalilikha nito dahil mas mabilis itong nanginginig.", "en": "When a rubber band stretched like a guitar string is pulled tighter, it makes a higher-pitched sound because it vibrates faster.", "bis": "Kon mas hugot ang goma nga gihimong gitara, mas taas ang tono sa tingog nga mahimo niini tungod kay mas paspas kini mokurog."}, "source": "NRC PS4.A sound and waves; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ruler-twang-desk-pitch-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "vibration length changes pitch", "grades": [4, 5, 6], "terms": ["ruler", "panukat", "mesa", "tunog", "tono", "pitch", "nanginginig", "vibration", "bibrasyon", "humahaba", "regla", "lamesa", "kurog", "haba sa nagkurog", "twang", "ruler on desk", "length", "pitch"], "fact": {"tl": "Kapag pinatutunog ang dulo ng ruler na nakausli sa gilid ng mesa, mas mataas ang tono kung mas maikli ang nakausli at mas mababa kung mas mahaba.", "en": "When you twang a ruler hanging off the edge of a desk, a shorter overhang makes a higher pitch and a longer overhang makes a lower pitch.", "bis": "Kon imong patingugon ang tumoy sa ruler nga nagtuy-od sa ngilit sa lamesa, mas taas ang tono kon mubo ang nagtuy-od ug mas ubos kon taas."}, "source": "NRC PS4.A sound and waves; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sail-paraw-wind-push-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "wind force pushes a sail", "grades": [3, 4, 5], "terms": ["layag", "hangin", "paraw", "bangka", "itinutulak", "puwersa", "wind force", "sail", "outrigger", "layag sa bangka", "hangin nagtulak", "katig", "wind pushes sail", "boat"], "fact": {"tl": "Ang paraw, isang Pilipinong bangkang may katig, ay umuusad kapag itinutulak ng hangin ang malaki nitong layag.", "en": "A paraw, a Filipino outrigger sailboat, moves forward when the wind pushes against its large sail.", "bis": "Ang paraw, usa ka Pilipinhong bangka nga may katig, mopadayon kon ang hangin moduso sa dako niini nga layag."}, "source": "NRC PS2.A forces and motion; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "screw-jack-lifting-vehicle-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "screw jack as a simple machine", "grades": [5, 6, 7], "terms": ["jack", "screw", "turnilyo", "sasakyan", "pag-angat", "puwersa", "simpleng makina", "screw jack", "pag-alsa sa sakyanan", "kusog sa kamot", "lift car", "simple machine", "screw"], "fact": {"tl": "Ang screw jack ay gumagamit ng paikot na turnilyo para iangat ang mabigat na sasakyan gamit lang ang kaunting puwersa ng kamay.", "en": "A screw jack uses a turning screw to lift a heavy vehicle using only a small force from your hand.", "bis": "Ang screw jack mogamit og nagtuyok nga screw aron alsahon ang bug-at nga sakyanan gamit lang ang gamay nga kusog sa kamot."}, "source": "NRC PS2.A simple machines; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "screwdriver-driving-screw-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "screwdriver turns force to drive a screw", "grades": [5, 6, 7], "terms": ["screwdriver", "desturnilyador", "turnilyo", "screw", "paikot", "puwersa", "kahoy", "simpleng makina", "tarnabis", "pagliko", "turok sa screw", "drive screw", "turning", "wood"], "fact": {"tl": "Ang desturnilyador ay nagpapalit ng paikot na galaw ng kamay sa lakas na nagbabaon ng turnilyo papasok sa kahoy o metal.", "en": "A screwdriver changes the turning motion of your hand into the force that drives a screw into wood or metal.", "bis": "Ang desturnilyador mobalhin sa nagtuyok nga lihok sa kamot ngadto sa kusog nga moturok sa screw sa kahoy o metal."}, "source": "NRC PS2.A simple machines; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "see-saw-playground-balance-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "seesaw as a lever balances at the middle", "grades": [3, 4, 5], "terms": ["seesaw", "tabla-tablahan", "balanse", "lever", "playground", "gitna", "puwersa", "timbang", "patindog", "balanse sa tunga", "tunga", "balance", "fulcrum", "middle"], "fact": {"tl": "Ang seesaw ay isang lever na nasa balanse kapag pantay ang bigat ng dalawang bata sa magkabilang dulo na nasa pantay na layo sa gitna.", "en": "A seesaw is a lever that balances when two children of equal weight sit the same distance from the middle support.", "bis": "Ang seesaw usa ka lever nga balanse kon parehas ang gibug-aton sa duha ka bata nga naglingkod sa managsama nga gilay-on gikan sa tunga."}, "source": "NRC PS2.A simple machines; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "seesaw-unequal-kids-balance-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "heavier child sits closer to balance a seesaw", "grades": [5, 6, 7], "terms": ["seesaw", "lever", "mabigat na bata", "balanse", "malapit sa gitna", "tabla-tablahan", "timbang", "puwersa", "bug-at nga bata", "duol sa tunga", "heavier child", "closer to center", "balance lever"], "fact": {"tl": "Para magbalanse sa seesaw ang dalawang batang magkaiba ng bigat, ang mas mabigat ay dapat umupo nang mas malapit sa gitna.", "en": "To balance a seesaw, the heavier child must sit closer to the middle than the lighter one.", "bis": "Aron magbalanse ang seesaw sa duha ka bata nga lahi og gibug-aton, ang mas bug-at kinahanglan molingkod nga mas duol sa tunga."}, "source": "NRC PS2.A simple machines; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "shadow-puppet-light-blocking-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "shadows form when objects block light", "grades": [3, 4], "terms": ["anino", "ilaw", "hinaharangan", "shadow puppet", "kamay", "liwanag", "dingding", "anino sa kamot", "kahayag", "gibabagan", "landong", "shadow", "blocks light", "wall", "hand puppet"], "fact": {"tl": "Ang anino ng kamay sa dingding ay nabubuo dahil hinaharangan ng kamay ang ilaw na hindi makadaan sa likod nito.", "en": "A hand-shadow on the wall forms because the hand blocks the light from reaching the wall behind it.", "bis": "Ang landong sa kamot sa bongbong matawo tungod kay ang kamot mobabag sa kahayag nga dili makaabot sa bongbong sa luyo niini."}, "source": "NRC PS4.B light; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "shadow-size-distance-light-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "shadow size changes with distance from light", "grades": [4, 5], "terms": ["anino", "laki", "layo", "ilaw", "shadow size", "malapit sa ilaw", "lumalaki", "liwanag", "landong", "gidak-on", "duol sa suga", "kahayag", "shadow grows", "close to light", "distance"], "fact": {"tl": "Lumalaki ang anino ng isang bagay kapag inilapit ito sa ilaw, at lumiliit kapag inilayo, dahil sa nagbabago kung gaano kalaki ang ilaw na hinaharangan nito.", "en": "An object's shadow grows larger when it is moved closer to the light and smaller when moved away, because it blocks a different amount of the light.", "bis": "Ang landong sa usa ka butang modako kon iduol kini sa suga ug mogamay kon ipalayo, tungod kay lahi ang gidaghanon sa kahayag nga babagan niini."}, "source": "NRC PS4.B light; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "siphon-water-tube-transfer-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "siphon moves water through a tube", "grades": [5, 6, 7], "terms": ["siphon", "sipon", "tubo", "tubig", "gravity", "grabidad", "paglipat ng tubig", "mas mababa", "tubo sa tubig", "pagbalhin sa tubig", "ubos", "siphon water", "tube", "downhill", "transfer"], "fact": {"tl": "Sa pamamagitan ng siphon, dumadaloy ang tubig pataas sa loob ng tubo at lumalabas sa kabilang dulo basta't ang dulong iyon ay mas mababa kaysa sa pinagmulang tubig.", "en": "A siphon moves water up through a tube and out the other end, as long as that end is lower than the water it came from.", "bis": "Pinaagi sa siphon, ang tubig modagayday paingon sa taas sulod sa tubo ug mogawas sa pikas tumoy basta kana nga tumoy mas ubos kay sa gigikanan nga tubig."}, "source": "NRC PS2.B gravity and fluids; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "skateboard-ramp-momentum-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "momentum builds rolling down a ramp", "grades": [5, 6, 7], "terms": ["skateboard", "rampa", "momentum", "bilis", "gravity", "pababang dahilig", "lakas ng galaw", "tabok", "kapaspas", "lihok", "rolling down", "ramp", "speed", "gravity"], "fact": {"tl": "Habang bumababa ang skateboard sa rampa, hinihila ito ng grabidad kaya tumataas ang bilis at lakas ng paggalaw o momentum nito.", "en": "As a skateboard rolls down a ramp, gravity pulls it so its speed and momentum keep building up.", "bis": "Samtang nagligid paubos ang skateboard sa tabok, ang grabidad mobira niini maong nagdugang ang kapaspas ug momentum niini."}, "source": "NRC PS2.A motion and energy; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "skipping-stone-water-bounce-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "a flat stone skips on water", "grades": [4, 5, 6], "terms": ["bato", "tumatalbog", "tubig", "skipping stone", "lapad na bato", "ihinagis", "ilog", "ihagis", "bato nga naglukso", "talbog", "lapad nga bato", "skip stone", "bounce", "flat stone", "water"], "fact": {"tl": "Ang lapad na batong ihinagis nang pahalang sa ibabaw ng tubig ay tumatalbog dahil itinutulak ito pabalik ng tubig sa bawat sagi.", "en": "A flat stone thrown low across the water skips because the water pushes it back up each time it touches the surface.", "bis": "Ang lapad nga bato nga ilabay nga hapla sa tubig molukso-lukso tungod kay ang tubig moduso niini pabalik matag sagad niini sa nawong sa tubig."}, "source": "NRC PS2.A forces and motion; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "slide-friction-descent-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "gravity and friction on a slide", "grades": [3, 4], "terms": ["slide", "saglian", "dulasan", "bumababa", "gravity", "grabidad", "friksyon", "dulas", "playground", "paubos", "dahilig", "kuskos", "slide down", "gravity", "friction"], "fact": {"tl": "Dumudulas pababa ang bata sa slide dahil hinihila siya ng grabidad, at ang makinis na ibabaw nito ay may kaunting friksyon para mas madulas.", "en": "A child slides down a slide because gravity pulls them down, and the smooth surface has little friction so they glide easily.", "bis": "Ang bata modulas paubos sa slide tungod kay ang grabidad mobira kaniya, ug ang hamis nga nawong niini gamay rag friction maong sayon modulas."}, "source": "NRC PS2.B gravity; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "solar-panel-roof-house-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "solar panels turn sunlight into electricity", "grades": [5, 6, 7], "terms": ["solar panel", "panel solar", "araw", "kuryente", "bubong", "enerhiya", "sikat ng araw", "elektrisidad", "adlaw", "kuryente gikan sa adlaw", "atop", "kahayag sa adlaw", "sunlight", "electricity", "roof"], "fact": {"tl": "Ang solar panel sa bubong ng bahay ay nagpapalit ng sikat ng araw sa kuryenteng magagamit ng mga gamit sa loob ng bahay.", "en": "A solar panel on a house roof turns sunlight into electricity that can power the things inside the house.", "bis": "Ang solar panel sa atop sa balay mobalhin sa kahayag sa adlaw ngadto sa kuryente nga magamit sa mga butang sulod sa balay."}, "source": "NRC PS3.A energy; DepEd Science energy resources; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "solar-water-heater-roof-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "solar water heater uses sun's heat", "grades": [5, 6, 7], "terms": ["solar water heater", "pampainit ng tubig", "araw", "init", "bubong", "enerhiya", "mainit na tubig", "init sa adlaw", "atop", "pagpainit sa tubig", "kainit", "warm water", "roof", "sun heat"], "fact": {"tl": "Ang solar water heater sa bubong ay gumagamit ng init ng araw para painitin ang tubig nang hindi kailangan ng kuryente.", "en": "A solar water heater on the roof uses the sun's heat to warm water without needing electricity.", "bis": "Ang solar water heater sa atop mogamit sa init sa adlaw aron painiton ang tubig nga dili na kinahanglan og kuryente."}, "source": "NRC PS3.B heat transfer; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sound-source-set-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "vibrating objects make sound", "grades": [3, 4, 5], "terms": ["tunog", "pinagmulan", "nanginginig", "vibration", "kampana", "gitara", "tinig", "bibrasyon", "tingog", "gigikanan sa tingog", "kurog", "kampana", "sound source", "vibrate", "bell", "voice"], "fact": {"tl": "Ang lahat ng tunog ay nagmumula sa isang bagay na nanginginig, gaya ng kampana, kuwerdas ng gitara, o ng ating lalamunan kapag nagsasalita.", "en": "All sounds come from something that is vibrating, such as a bell, a guitar string, or our throat when we speak.", "bis": "Ang tanang tingog gikan sa usa ka butang nga nagkurog, sama sa kampana, kuwerdas sa gitara, o sa atong tutonlan kon kita mosulti."}, "source": "NRC PS4.A sound; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sound-waves-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "sound travels as waves through air", "grades": [5, 6, 7], "terms": ["tunog", "alon", "hangin", "sound waves", "naglalakbay", "vibration", "bibrasyon", "balod sa tingog", "naglakaw", "alon sa tingog", "sound wave", "travels", "air", "vibration"], "fact": {"tl": "Ang tunog ay naglalakbay bilang mga alon na nagtutulak sa mga partikulo ng hangin paabot sa ating tainga.", "en": "Sound travels as waves that push air particles along until they reach our ears.", "bis": "Ang tingog molakaw isip mga balod nga moduso sa mga partikulo sa hangin hangtod nga makaabot kini sa atong dalunggan."}, "source": "NRC PS4.A waves; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "speaker-magnet-sound-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "speakers use a magnet to make sound", "grades": [6, 7, 8], "terms": ["speaker", "ispiker", "magnet", "bakal", "tunog", "kuryente", "nanginginig", "cone", "tingog", "magkurog", "speaker magnet", "vibrate", "electricity", "sound"], "fact": {"tl": "Sa loob ng speaker, ang dumadaloy na kuryente at magnet ay nagtutulak-hila sa isang cone para manginig ito at lumikha ng tunog.", "en": "Inside a speaker, electric current and a magnet push and pull a cone so it vibrates and makes sound.", "bis": "Sulod sa speaker, ang nagdagayday nga kuryente ug ang magnet moduso-bira sa usa ka cone aron mokurog kini ug mohimo og tingog."}, "source": "NRC PS2.B electromagnetism; PS4.A sound; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "speed-vs-velocity-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "speed has no direction, velocity does", "grades": [7, 8, 9], "terms": ["bilis", "speed", "velocity", "direksyon", "tulin", "vector", "kapaspas", "tulin nga may direksyon", "speed direction", "direction"], "fact": {"tl": "Ang bilis (speed) ay nagsasabi lang kung gaano kabilis gumagalaw ang isang bagay, habang ang velocity ay nagsasabi rin ng direksyon ng paggalaw.", "en": "Speed tells only how fast something moves, while velocity tells both how fast and in which direction it moves.", "bis": "Ang speed mosulti lang kon unsa ka paspas molihok ang usa ka butang, samtang ang velocity mosulti usab sa direksyon sa paglihok."}, "source": "NRC PS2.A motion; DepEd Science kinematics; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "spring-coil-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "a spring stores energy when stretched or squeezed", "grades": [4, 5, 6], "terms": ["spring", "muelye", "kulot na bakal", "enerhiya", "hinila", "diniin", "bumabalik", "elastik", "gibira", "naglikos", "lukot nga puthaw", "spring coil", "stretch", "squeeze", "store energy"], "fact": {"tl": "Ang spring na kulot na bakal ay nag-iimbak ng enerhiya kapag ito ay hinila o diniin, at bumabalik ito sa dating hugis kapag binitawan.", "en": "A coiled spring stores energy when you stretch or squeeze it, and it springs back to its shape when you let go.", "bis": "Ang spring nga lukot nga puthaw motipig og enerhiya kon imong birahon o ipiit kini, ug mobalik kini sa daan nga porma kon imong buhian."}, "source": "NRC PS3.A energy; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "stapler-press-lever-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "a stapler is a lever", "grades": [4, 5, 6], "terms": ["stapler", "istapler", "lever", "papel", "pagpindot", "puwersa", "simpleng makina", "pagduso", "press", "paper", "staple"], "fact": {"tl": "Ang stapler ay isang lever na, kapag idiniin, nagbabaon ng metal na pang-staple para pagdugtungin ang mga papel.", "en": "A stapler is a lever that, when pressed down, drives a metal staple through paper to hold the sheets together.", "bis": "Ang stapler usa ka lever nga, kon imong ipiit, moturok og puthaw nga staple latas sa papel aron magdikit ang mga panid."}, "source": "NRC PS2.A simple machines; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "stethoscope-listening-sound-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "a stethoscope carries body sounds to the ear", "grades": [4, 5, 6], "terms": ["stethoscope", "estetoskopyo", "doktor", "tibok ng puso", "tunog", "tainga", "naglalakbay", "tingog sa kasingkasing", "dalunggan", "tunog sa lawas", "heartbeat", "doctor", "sound to ear"], "fact": {"tl": "Ginagamit ng doktor ang stethoscope para palakasin at dalhin ang tunog ng tibok ng puso o paghinga papunta sa kanyang tainga.", "en": "A doctor uses a stethoscope to gather and carry the sound of a heartbeat or breathing to their ears.", "bis": "Ang doktor mogamit og stethoscope aron tigumon ug dad-on ang tingog sa pitik sa kasingkasing o sa pagginhawa paingon sa iyang dalunggan."}, "source": "NRC PS4.A sound; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "stretched-rubber-band-launch-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "stretched rubber band stores energy to launch", "grades": [4, 5, 6], "terms": ["goma", "rubber band", "hinila", "enerhiya", "pinaputok", "lumilipad", "elastik", "lastiko", "gibira", "milupad", "stored energy", "stretch", "launch", "fly"], "fact": {"tl": "Ang hinilang goma ay nag-iimbak ng enerhiya, at kapag binitawan, ginagamit nito ang enerhiyang iyon para ipalipad pasulong ang sarili o anumang nakasabit dito.", "en": "A stretched rubber band stores energy, and when released it uses that energy to launch itself or whatever is hooked on it forward.", "bis": "Ang gibira nga goma motipig og enerhiya, ug kon buhian na, gamiton niini kana nga enerhiya aron ilupad pauna ang kaugalingon o bisan unsang nakasab-it niini."}, "source": "NRC PS3.A elastic potential energy; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sunlight-window-warming-room-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "sunlight warms a room through a window", "grades": [3, 4, 5], "terms": ["sikat ng araw", "bintana", "init", "kuwarto", "sunlight", "umiinit", "enerhiya", "kahayag sa adlaw", "lawak", "kainit", "warm room", "heat", "window"], "fact": {"tl": "Ang sikat ng araw na pumapasok sa bintana ay nagdadala ng init na nagpapainit sa loob ng kuwarto.", "en": "Sunlight coming through a window carries heat that warms up the inside of a room.", "bis": "Ang kahayag sa adlaw nga mosulod sa bintana magdala og init nga mopainit sa sulod sa lawak."}, "source": "NRC PS3.B heat and energy transfer; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "surface-tension-coin-drops-g6", "domain": "MATTER", "topic": "surface tension lets water pile on a coin", "grades": [5, 6, 7], "terms": ["surface tension", "tensyon ng ibabaw", "tubig", "barya", "patak", "umaalsa", "molekula", "tubig sa sensilyo", "tulo", "nawong sa tubig", "sensilyo", "water drops", "coin", "dome"], "fact": {"tl": "Dahil sa surface tension, mahihigpit na magkakapit ang mga molekula ng tubig kaya maraming patak ang maaaring maipundar sa ibabaw ng barya bago ito umapaw.", "en": "Because of surface tension, water molecules cling tightly together, so many drops can pile up into a dome on a coin before it spills.", "bis": "Tungod sa surface tension, ang mga molekula sa tubig manggunit og hugot, mao nga daghang tulo ang matipon ngadto sa ibabaw sa sensilyo una pa kini moawas."}, "source": "NRC PS1.A properties of matter; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "swimming-pool-bent-stick-refraction-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "light refraction makes a stick look bent in water", "grades": [6, 7, 8], "terms": ["refraction", "pagbaluktot ng liwanag", "patpat", "tubig", "baluktot", "ilaw", "pool", "kahayag", "baliko nga sungkod", "pagbawog sa kahayag", "bent stick", "water", "light bends"], "fact": {"tl": "Ang patpat na nakababad sa tubig ay parang baluktot tingnan dahil yumuyuko o nababaluktot ang liwanag pagdaan mula sa tubig papunta sa hangin.", "en": "A stick partly in water looks bent because light changes direction, or refracts, as it passes from water into air.", "bis": "Ang sungkod nga gibutang sa tubig morag baliko tan-awon tungod kay ang kahayag mobawog o mausab og direksyon samtang moagi gikan sa tubig paingon sa hangin."}, "source": "NRC PS4.B light refraction; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "swing-pendulum-arc-child-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "swing as a pendulum", "grades": [4, 5, 6], "terms": ["duyan", "swing", "pendulum", "palugsong", "pabalik-balik", "gravity", "grabidad", "indayog", "saka-baba", "wabe-wabe", "naglutaw-balay", "alindahaw", "back and forth", "arc", "arko"], "fact": {"tl": "Ang bata sa duyan ay kumikilos tulad ng pendulo: hinihila siya pababa ng grabidad at umiindayog nang pabalik-balik sa isang arko.", "en": "A child on a swing moves like a pendulum: gravity pulls them down and they swing back and forth along an arc.", "bis": "Ang bata sa duyan molihok sama sa pendulo: ang grabidad maoy nagbira kaniya paubos ug siya magwabe-wabe balik-balik sa usa ka arko."}, "source": "encyclopedia-stable consensus; NRC PS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "swing-pendulum-playground-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "pendulum energy conversion", "grades": [5, 6, 7], "terms": ["duyan", "swing", "pendulum", "potensyal", "kinetic", "potential energy", "kinetiko", "enerhiya", "kusog", "taas", "pinakataas", "pinakabilis", "pinakaubos", "highest point", "lowest point", "indayog", "wabe-wabe"], "fact": {"tl": "Sa duyan, pinakamabagal ito sa pinakataas na bahagi kung saan may potensyal na enerhiya, at pinakamabilis sa pinakababa kung saan ito nagiging kinetic na enerhiya.", "en": "On a swing, it moves slowest at the highest point where it stores potential energy, and fastest at the bottom where that becomes kinetic energy.", "bis": "Sa duyan, pinakahinay kini sa pinakataas nga bahin diin adunay potensyal nga enerhiya, ug pinakapaspas sa pinakaubos diin kini mahimong kinetiko nga enerhiya."}, "source": "encyclopedia-stable consensus; NRC PS3.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "switch-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "electrical switch closes a circuit", "grades": [3, 4, 5], "terms": ["switch", "swits", "circuit", "sirkito", "kuryente", "elektrisidad", "bukas", "sara", "on", "off", "patay", "sindi", "agos", "agos sa kuryente", "ilaw", "buhi", "open", "closed"], "fact": {"tl": "Ang switch ay nagbubukas at nagsasara ng daloy ng kuryente: kapag sarado ang sirkito, dumadaloy ang kuryente at nagsisindi ang ilaw.", "en": "A switch opens and closes the flow of electricity: when the circuit is closed, current flows and the light turns on.", "bis": "Ang switch maoy nag-abli ug nagsira sa agos sa kuryente: kon sirado ang sirkito, modagayday ang kuryente ug modagkot ang suga."}, "source": "encyclopedia-stable consensus; NRC PS3.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "tape-measure-roll-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "measuring length with a tape measure", "grades": [3, 4, 5], "terms": ["tape measure", "metro", "panukat", "sukat", "haba", "sentimetro", "pulgada", "sukod", "gitas-on", "length", "centimeter", "ruler", "panukat sa gitas-on"], "fact": {"tl": "Ang tape measure ay isang nababaluktot na panukat na may mga marka tulad ng sentimetro at metro para sukatin ang haba ng mga bagay.", "en": "A tape measure is a flexible measuring tool marked in units like centimeters and meters to measure the length of things.", "bis": "Ang tape measure usa ka mahubog nga panukod nga adunay mga marka sama sa sentimetro ug metro aron sukdon ang gitas-on sa mga butang."}, "source": "encyclopedia-stable consensus; DepEd G3 measurement", "generator": "claude-workflow", "reviewed": false},
  {"id": "thermometer-hot-cold-water-cups-g5", "domain": "MATTER", "topic": "thermometer measures temperature", "grades": [4, 5, 6], "terms": ["thermometer", "termometro", "temperatura", "init", "lamig", "kainit", "kabugnaw", "degree", "Celsius", "sukat ng init", "mainit", "malamig", "mabugnaw", "temperature", "hot water", "cold water", "tubig"], "fact": {"tl": "Ang termometro ay sumusukat ng temperatura: tumataas ang basa nito sa mainit na tubig at bumababa sa malamig na tubig.", "en": "A thermometer measures temperature: its reading rises in hot water and drops in cold water.", "bis": "Ang termometro magsukod sa temperatura: mosaka ang basahon niini sa init nga tubig ug monaog sa bugnaw nga tubig."}, "source": "encyclopedia-stable consensus; NRC PS3.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "thermos-keeping-hot-g6", "domain": "MATTER", "topic": "insulation slows heat transfer", "grades": [5, 6, 7], "terms": ["thermos", "termos", "init", "insulation", "insulador", "heat", "kainit", "lamig", "vacuum", "matagal", "nainit", "nagpapanatili", "kabugnaw", "pagpapanatili ng init", "keeps hot", "insulator", "nagtipig sa init"], "fact": {"tl": "Pinapanatiling mainit ng termos ang inumin dahil ang mga dingding nito ay humahadlang sa pagtakas ng init papunta sa malamig na hangin sa labas.", "en": "A thermos keeps a drink hot because its walls block heat from escaping into the cooler air outside.", "bis": "Ang termos magpabilin nga init sa imnonon kay ang mga bongbong niini magsanta sa init nga moikyas ngadto sa bugnaw nga hangin sa gawas."}, "source": "encyclopedia-stable consensus; NRC PS3.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "thunder-lightning-gap-count-g6", "domain": "EARTH_SPACE", "topic": "light travels faster than sound", "grades": [5, 6, 7], "terms": ["kidlat", "kulog", "thunder", "lightning", "liti", "dalugdog", "tunog", "ilaw", "bilis", "layo", "bagyo", "bilis ng ilaw", "bilis ng tunog", "sound", "light speed", "distance", "kalayo", "ihap", "bilang"], "fact": {"tl": "Nakikita muna natin ang kidlat bago marinig ang kulog dahil mas mabilis maglakbay ang ilaw kaysa sa tunog.", "en": "We see the lightning before we hear the thunder because light travels much faster than sound.", "bis": "Makita una nato ang kilat sa dili pa madungog ang dalugdog kay mas paspas molakaw ang kahayag kaysa sa tingog."}, "source": "encyclopedia-stable consensus; NRC PS4.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "tin-can-telephone-talk-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "sound travels through a taut string", "grades": [4, 5, 6], "terms": ["tin can telephone", "lata", "telepono", "tunog", "vibration", "bibrasyon", "kuwerdas", "tali", "hibla", "string", "sound", "nanginginig", "nag-uyog", "tense", "banat", "pisi", "tingog", "tunog sa tali"], "fact": {"tl": "Sa telepono ng lata, ang tunog ay naglalakbay bilang panginginig sa banat na tali mula sa isang lata patungo sa kabila.", "en": "In a tin-can telephone, sound travels as vibrations along the taut string from one can to the other.", "bis": "Sa telepono nga lata, ang tingog molakaw isip pag-uyog subay sa hugot nga tali gikan sa usa ka lata ngadto sa pikas."}, "source": "encyclopedia-stable consensus; NRC PS4.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "toy-car-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "push and pull make things move", "grades": [3, 4], "terms": ["toy car", "laruang kotse", "kotse", "tulak", "hila", "puwersa", "push", "pull", "force", "gulong", "galaw", "kilos", "duslak", "bira", "kusog", "ligid", "move", "wheels", "naglihok"], "fact": {"tl": "Ang laruang kotse ay gumagalaw kapag tinutulak o hinihila mo ito, at humihinto kapag inalis ang puwersa.", "en": "A toy car moves when you push or pull it, and stops when the force is taken away.", "bis": "Ang dulaang awto molihok kon imo kining duslakon o birahon, ug mohunong kon kuhaon ang kusog."}, "source": "encyclopedia-stable consensus; NRC PS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "trampoline-jump-bounce-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "elastic energy in a trampoline", "grades": [5, 6, 7], "terms": ["trampoline", "trampolina", "talbog", "bounce", "elastic", "elastiko", "spring", "enerhiya", "tagsibol", "lukso", "talon", "elastic energy", "naluksong", "naglukso", "bukal", "bouncy"], "fact": {"tl": "Kapag tumalon ka sa trampolina, hinahatak pababa ng bigat mo ang nakaunat na tela na nag-iimbak ng elastic na enerhiya at itinatapon ka pabalik pataas.", "en": "When you jump on a trampoline, your weight stretches the mat which stores elastic energy and throws you back up.", "bis": "Kon ikaw molukso sa trampolina, ang imong gibug-aton magbira sa naunat nga panapton nga magtipig sa elastiko nga enerhiya ug molabay kanimo balik pataas."}, "source": "encyclopedia-stable consensus; NRC PS3.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "tricycle-engine-energy-flow-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "energy transformation in an engine", "grades": [6, 7, 8], "terms": ["tricycle", "traysikel", "makina", "gasolina", "engine", "fuel", "enerhiya", "sunog", "kemikal", "galaw", "chemical energy", "motion", "init", "nasunog", "pagkasunog", "lihok"], "fact": {"tl": "Sa traysikel, ang kemikal na enerhiya ng gasolina ay nagiging init at galaw kapag ito ay nasusunog sa loob ng makina.", "en": "In a tricycle, the chemical energy in gasoline becomes heat and motion when it burns inside the engine.", "bis": "Sa traysikel, ang kemikal nga enerhiya sa gasolina mahimong init ug lihok kon kini masunog sulod sa makina."}, "source": "encyclopedia-stable consensus; NRC PS3.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "motorcycle-turn-lean-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "leaning to balance a turn", "grades": [6, 7, 8], "terms": ["motorcycle", "motorsiklo", "motor", "liko", "lean", "turn", "hilig", "balanse", "balance", "puwersa", "pakiling", "pahilig", "kiling", "sandig", "force", "turning"], "fact": {"tl": "Kapag lumiliko ang motorsiklo, ang rider ay sumasandal papasok sa liko upang mapanatili ang balanse laban sa puwersang nagtutulak palabas.", "en": "When a motorcycle turns, the rider leans into the turn to stay balanced against the force pushing them outward.", "bis": "Kon moliko ang motorsiklo, ang nagsakay mosandig padulong sa liko aron magpabiling balanse batok sa kusog nga nagduso paggawas."}, "source": "encyclopedia-stable consensus; NRC PS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "trompo-spinning-top-pull-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "spinning top stays upright", "grades": [5, 6, 7], "terms": ["trompo", "spinning top", "turumpo", "ikot", "spin", "tali", "balanse", "rotation", "pag-ikot", "tuyok", "nagtutuyok", "umiikot", "patuyok", "spinning", "lubid", "pisi", "tirador"], "fact": {"tl": "Ang trompo ay umiikot nang matayog dahil ang mabilis na pag-ikot nito ay nagpapanatili sa balanse, ngunit nadarapa ito kapag bumagal na.", "en": "A spinning top stays upright because its fast spin keeps it balanced, but it topples once it slows down.", "bis": "Ang trompo magpabiling tarong kay ang paspas nga tuyok niini magpabiling balanse, apan matumba kini kon mohinay na."}, "source": "encyclopedia-stable consensus; NRC PS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "tug-of-war-balanced-forces-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "balanced and unbalanced forces", "grades": [4, 5, 6], "terms": ["tug of war", "batuhan ng lubid", "hila", "lubid", "puwersa", "balanse", "force", "balanced", "patas", "hindi patas", "magkapareho", "bira", "kusog", "unbalanced", "pantay", "biraay sa pisi"], "fact": {"tl": "Sa batuhan ng lubid, hindi gumagalaw ang lubid kung magkapantay ang hila ng dalawang panig, ngunit gumagalaw ito kapag mas malakas ang isang panig.", "en": "In tug-of-war, the rope stays still when both sides pull equally, but it moves when one side pulls harder.", "bis": "Sa biraay sa pisi, dili molihok ang pisi kon managsama ang bira sa duha ka kilid, apan molihok kini kon mas kusgan ang usa ka kilid."}, "source": "encyclopedia-stable consensus; NRC PS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "two-mirror-multiple-images-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "reflection between two mirrors", "grades": [5, 6, 7], "terms": ["mirror", "salamin", "repleksyon", "reflection", "imahe", "image", "ilaw", "liwanag", "anino", "salamin sa salamin", "kahayag", "pagbalik", "litrato", "multiple images", "hulagway"], "fact": {"tl": "Kapag magkaharap ang dalawang salamin, ang ilaw ay paulit-ulit na nababalik sa pagitan nila kaya marami at sunod-sunod na imahe ang nakikita.", "en": "When two mirrors face each other, light bounces back and forth between them, making many repeating images appear.", "bis": "Kon mag-atubang ang duha ka salamin, ang kahayag mobalik-balik tali kanila, busa daghan ug sunod-sunod nga hulagway ang makita."}, "source": "encyclopedia-stable consensus; NRC PS4.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "umbrella-wind-flip-force-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "wind exerts force on a surface", "grades": [4, 5, 6], "terms": ["umbrella", "payong", "hangin", "wind", "puwersa", "force", "baligtad", "flip", "bagyo", "pressure", "natuwad", "nabaliktad", "kusog sa hangin", "presyon", "blow"], "fact": {"tl": "Natutuwad ang payong sa malakas na hangin dahil ang hangin ay nagtutulak ng puwersa sa malapad na tela nito.", "en": "An umbrella flips inside-out in strong wind because the wind pushes a force against its wide surface.", "bis": "Mabaliktad ang payong sa kusog nga hangin kay ang hangin magduso ug kusog batok sa lapad nga panapton niini."}, "source": "encyclopedia-stable consensus; NRC PS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-displacement-volume-measure-g7", "domain": "MATTER", "topic": "measuring volume by water displacement", "grades": [6, 7, 8], "terms": ["water displacement", "pag-angat ng tubig", "volume", "bolyum", "sukat", "tubig", "lubog", "displacement", "gisaylo nga tubig", "gidaghanon", "sukod", "lulan", "naangat", "rises", "submerge"], "fact": {"tl": "Masusukat ang bolyum ng isang di-regular na bagay sa pamamagitan ng paglubog dito sa tubig at pagsukat kung gaano tumaas ang antas ng tubig.", "en": "You can measure the volume of an irregular object by sinking it in water and measuring how much the water level rises.", "bis": "Masukod ang gidaghanon sa usa ka dili-regular nga butang pinaagi sa paglunod niini sa tubig ug pagsukod kon pila ang pagsaka sa lebel sa tubig."}, "source": "encyclopedia-stable consensus; NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-glass-xylophone-pitch-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "water level changes pitch", "grades": [5, 6, 7], "terms": ["water glass", "baso ng tubig", "xylophone", "tono", "pitch", "tunog", "tubig", "vibration", "matinis", "mababa", "tingog", "vaso", "tono sa tubig", "high pitch", "low pitch", "tunog ng baso"], "fact": {"tl": "Sa mga baso na may iba't ibang dami ng tubig, ang mas maraming tubig ay gumagawa ng mas mababang tono kapag pinatunog mo ang baso.", "en": "In glasses with different amounts of water, more water makes a lower pitch when you tap the glass.", "bis": "Sa mga baso nga adunay lain-laing gidaghanon sa tubig, ang mas daghang tubig maghimo ug mas ubos nga tono kon imong tuktokon ang baso."}, "source": "encyclopedia-stable consensus; NRC PS4.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-longitudinal-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "longitudinal waves", "grades": [7, 8, 9], "terms": ["longitudinal wave", "longitudinal na alon", "alon", "tunog", "sound wave", "compression", "siksik", "luwag", "vibration", "balud", "pagsiksik", "pag-uyog", "tingog", "wave direction", "alon ng tunog", "luag"], "fact": {"tl": "Sa longitudinal na alon, tulad ng tunog, ang mga particle ay umuuyog pasulong-paurong sa parehong direksyon ng paglalakbay ng alon.", "en": "In a longitudinal wave, like sound, the particles vibrate back and forth in the same direction the wave travels.", "bis": "Sa longitudinal nga balud, sama sa tingog, ang mga partikulo mag-uyog atubang-balik sa samang direksyon nga ginalakaw sa balud."}, "source": "encyclopedia-stable consensus; NRC PS4.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-transverse-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "transverse waves", "grades": [7, 8, 9], "terms": ["transverse wave", "transverse na alon", "alon", "lubid", "tubig", "wave", "crest", "trough", "pataas-pababa", "ilaw", "balud", "pataas-paubos", "vibration", "perpendicular", "alon ng tubig", "taluwas"], "fact": {"tl": "Sa transverse na alon, tulad ng alon sa tubig, ang mga particle ay umuuyog pataas-pababa, pahalang sa direksyon ng paglalakbay ng alon.", "en": "In a transverse wave, like a water wave, the particles vibrate up and down, at right angles to the direction the wave travels.", "bis": "Sa transverse nga balud, sama sa balud sa tubig, ang mga partikulo mag-uyog pataas-paubos, taluwas sa direksyon nga ginalakaw sa balud."}, "source": "encyclopedia-stable consensus; NRC PS4.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "well-pulley-water-bucket-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "pulley changes direction of force", "grades": [4, 5, 6], "terms": ["pulley", "kalo", "polea", "balon", "well", "timba", "lubid", "puwersa", "hila", "simple machine", "atabay", "bira", "pisi", "simpleng makina", "direction", "pababa", "pataas", "lift"], "fact": {"tl": "Ginagamit ang kalo sa balon para mas madaling iangat ang timba ng tubig: kapag hinila mo pababa ang lubid, tumataas ang timba.", "en": "A pulley on a well makes it easier to lift a bucket of water: when you pull the rope down, the bucket goes up.", "bis": "Gamiton ang kalo sa atabay aron mas sayon nga ialsa ang timba sa tubig: kon imong birahon paubos ang pisi, mosaka ang timba."}, "source": "encyclopedia-stable consensus; NRC PS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "well-sweep-timba-lever-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "well sweep is a lever", "grades": [5, 6, 7], "terms": ["well sweep", "timba", "lever", "panghila", "balon", "tuod", "pingga", "counterweight", "balanse", "fulcrum", "simple machine", "atabay", "tuod nga pingga", "bug-at", "tumbasan", "simpleng makina"], "fact": {"tl": "Ang panghila ng tubig sa balon ay isang lever: may pabigat sa isang dulo na tumutulong iangat ang timba mula sa malalim na balon.", "en": "A well sweep is a lever: a weight on one end helps lift the bucket up from a deep well.", "bis": "Ang pingga sa pagkuha ug tubig sa atabay usa ka lever: ang bug-at sa usa ka tumoy motabang sa pag-alsa sa timba gikan sa lawom nga atabay."}, "source": "encyclopedia-stable consensus; NRC PS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "wet-finger-glass-rim-tone-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "friction makes a glass sing", "grades": [6, 7, 8], "terms": ["glass rim", "labi ng baso", "tono", "daliri", "wet finger", "tunog", "vibration", "friction", "kiskisan", "resonance", "umaalingawngaw", "vaso", "basa nga tudlo", "tingog", "pag-uyog", "kiskis", "ngilit sa baso", "humming"], "fact": {"tl": "Kapag ikiniskis mo ang basang daliri sa labi ng baso, ang alitan ay nagpapauyog sa baso kaya ito ay umaalingawngaw at lumilikha ng malinaw na tono.", "en": "When you rub a wet finger around a glass rim, the friction makes the glass vibrate so it hums and produces a clear tone.", "bis": "Kon imong kuskuson ang basa nga tudlo sa ngilit sa baso, ang kiskisanay maoy magpa-uyog sa baso busa kini mohaguros ug mohatag ug klaro nga tono."}, "source": "encyclopedia-stable consensus; NRC PS4.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "wet-floor-slipping-friction-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "friction and slipping", "grades": [4, 5, 6], "terms": ["wet floor", "basang sahig", "dulas", "friction", "kiskisan", "slip", "madulas", "puwersa", "grip", "kapit", "nadulas", "basa nga salog", "danlog", "kiskisanay", "padulas", "slippery"], "fact": {"tl": "Madulas ang basang sahig dahil binabawasan ng tubig ang alitan sa pagitan ng iyong sapatos at sahig na siyang nagbibigay sa iyo ng kapit.", "en": "A wet floor is slippery because water reduces the friction between your shoes and the floor that normally gives you grip.", "bis": "Danlog ang basa nga salog kay ang tubig magpakunhod sa kiskisanay tali sa imong sapatos ug salog nga maoy naghatag kanimo ug grip."}, "source": "encyclopedia-stable consensus; NRC PS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "wheelbarrow-cement-load-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "wheelbarrow is a lever and wheel", "grades": [5, 6, 7], "terms": ["wheelbarrow", "kariton", "lever", "gulong", "wheel", "karga", "load", "puwersa", "simple machine", "fulcrum", "ligid", "lulan", "simpleng makina", "pingga", "alsa", "buhat", "easier", "lift", "tulak"], "fact": {"tl": "Ang kariton ay isang simpleng makina na pinagsasama ang gulong at lever upang mas madaling buhatin at iangat ang mabigat na karga tulad ng semento.", "en": "A wheelbarrow is a simple machine that combines a wheel and a lever to make carrying and lifting heavy loads like cement easier.", "bis": "Ang kariton usa ka simpleng makina nga naghiusa sa ligid ug lever aron mas sayon nga madala ug maalsa ang bug-at nga lulan sama sa semento."}, "source": "encyclopedia-stable consensus; NRC PS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "wind-spinning-pinwheel-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "wind energy turns a pinwheel", "grades": [3, 4, 5], "terms": ["pinwheel", "pamaypay-ikutan", "rehiyas", "hangin", "wind", "ikot", "spin", "puwersa", "enerhiya", "umiikot", "tuyok", "ikot-ikot", "patuyok", "energy", "blow", "hihip"], "fact": {"tl": "Umiikot ang pinwheel kapag hinipan ng hangin dahil ang puwersa ng hangin ay nagtutulak sa mga pakpak nito.", "en": "A pinwheel spins when the wind blows because the force of the wind pushes against its blades.", "bis": "Motuyok ang pinwheel kon huypan sa hangin kay ang kusog sa hangin magduso batok sa mga pako niini."}, "source": "encyclopedia-stable consensus; NRC PS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "wind-turbine-blade-single-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "wind turbine generates electricity", "grades": [6, 7, 8], "terms": ["wind turbine", "windmill", "turbina ng hangin", "hangin", "kuryente", "electricity", "enerhiya", "pakpak", "blade", "renewable", "umiikot", "elektrisidad", "nababagong enerhiya", "pako", "turbina", "generate", "spin", "tuyok"], "fact": {"tl": "Ginagawang elektrisidad ng wind turbine ang enerhiya ng hangin: pinaiikot ng hangin ang mga pakpak nito na nagpapagana sa isang generator.", "en": "A wind turbine turns the energy of the wind into electricity: the wind spins its blades, which drive a generator.", "bis": "Ang wind turbine maghimo sa enerhiya sa hangin nga elektrisidad: ang hangin magpatuyok sa mga pako niini, nga maoy magpadagan sa usa ka generator."}, "source": "encyclopedia-stable consensus; NRC PS3.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "yoyo-string-spin-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "yoyo energy conversion", "grades": [5, 6, 7], "terms": ["yoyo", "lubid", "string", "potensyal", "kinetic", "potential energy", "enerhiya", "babagsak", "pabalik", "pisi", "tali", "kinetiko", "naghulog", "balik", "spin", "gravity", "grabidad"], "fact": {"tl": "Sa yoyo, ang potensyal na enerhiya sa itaas ay nagiging kinetic na enerhiya habang ito ay bumababa, at bumabalik ito pataas dahil sa pag-ikot ng lubid.", "en": "In a yoyo, potential energy at the top becomes kinetic energy as it drops, and it climbs back up as the string winds around it.", "bis": "Sa yoyo, ang potensyal nga enerhiya sa taas mahimong kinetiko nga enerhiya samtang kini monaog, ug mobalik kini pataas samtang ang pisi moliyok niini."}, "source": "encyclopedia-stable consensus; NRC PS3.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "zipper-wedge-mechanism-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "zipper as wedge simple machine", "grades": [4, 5, 6], "terms": ["zipper", "siper", "zip", "wedge", "simple machine", "simpleng makina", "talim na pansingit", "buwid", "pansara", "panghugpong", "ngipin ng zipper", "ngipin sa siper", "slider", "pananggit", "magkabit", "magsara", "magbukas"], "fact": {"tl": "Gumagana ang zipper gamit ang slider na isang wedge (tulis na simpleng makina) na pinagdidikit ang dalawang hanay ng maliliit na ngipin upang magsara, o pinaghihiwalay ang mga ito upang magbukas, habang itinutulak ito.", "en": "A zipper works using a slider that acts as a wedge (a simple machine), pushing two rows of tiny teeth together to close them or apart to open them as you pull it.", "bis": "Ang siper mogana pinaagi sa slider nga usa ka wedge (yano nga makina) nga magdikit sa duha ka laray sa gagmayng ngipon aron mosira, o magbulag niini aron moabli, samtang ginatulod kini."}, "source": "AAAS Benchmarks 8C (designed systems); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "natural-selection-moth-on-bark-g8", "domain": "LIVING_THINGS", "topic": "natural selection and camouflage", "grades": [7, 8, 9, 10], "terms": ["natural selection", "natural na pagpili", "natural nga pagpili", "gamu-gamo", "anuplos", "alibangbang sa gabii", "moth", "camouflage", "pagtatago", "pagtago", "balat sa kahoy", "bark", "panit sa kahoy", "survival", "pagkaligtas", "evolution", "ebolusyon", "kulay", "kolor", "nakaligtas", "naa-adapt"], "fact": {"tl": "Ang mga gamu-gamo na ang kulay ay tugma sa balat ng kahoy ay mas mahirap makita ng mga ibon, kaya mas madami silang nakaliligtas at nagpaparami—isang halimbawa ng natural selection.", "en": "Moths whose color matches the tree bark are harder for birds to spot, so more of them survive and reproduce, an example of natural selection.", "bis": "Ang mga anuplos nga ang kolor mohaom sa panit sa kahoy lisod makita sa mga langgam, mao nga mas daghan kanila ang maluwas ug manganak, usa ka ehemplo sa natural nga pagpili."}, "source": "NRC LS4.B Natural Selection; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "nerve-cell-labeled-parts-g8", "domain": "LIVING_THINGS", "topic": "parts of a nerve cell", "grades": [7, 8, 9, 10], "terms": ["nerve cell", "selula ng nerbiyo", "selula sa nerbiyo", "neuron", "newron", "dendrite", "dendrita", "axon", "akson", "cell body", "katawan ng selula", "lawas sa selula", "signal", "senyales", "mensahe", "utak", "tissue", "nerbiyo", "nag-uugnay", "nagdadala"], "fact": {"tl": "Ang selula ng nerbiyo o neuron ay may mga dendrite na tumatanggap ng senyales, isang cell body, at isang mahabang axon na nagdadala ng senyales papunta sa ibang selula.", "en": "A nerve cell, or neuron, has dendrites that receive signals, a cell body, and a long axon that carries signals to other cells.", "bis": "Ang selula sa nerbiyo o neuron adunay mga dendrita nga modawat sa senyales, usa ka lawas sa selula, ug usa ka taas nga akson nga modala sa senyales ngadto sa ubang selula."}, "source": "NRC LS1.A Structure and Function; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "neuron-g6", "domain": "LIVING_THINGS", "topic": "neuron function", "grades": [5, 6, 7, 8], "terms": ["neuron", "newron", "selula ng nerbiyo", "selula sa nerbiyo", "nerve cell", "utak", "brain", "senyales", "signal", "mensahe", "elektrikal", "electrical", "nagpapadala", "nagdadala", "nagpadala", "sistema ng nerbiyo", "nervous system", "kalit na galaw"], "fact": {"tl": "Ang neuron ay isang espesyal na selula na nagpapadala ng mabilisang elektrikal na senyales upang makipag-usap ang utak sa ibang bahagi ng katawan.", "en": "A neuron is a special cell that sends fast electrical signals so the brain can communicate with the rest of the body.", "bis": "Ang neuron usa ka pinasahi nga selula nga magpadala og paspas nga elektrikal nga senyales aron ang utok makigsulti sa ubang bahin sa lawas."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "osmosis-turgid-vs-wilted-g8", "domain": "LIVING_THINGS", "topic": "osmosis in plant cells", "grades": [7, 8, 9, 10], "terms": ["osmosis", "tubig", "water", "lanaw", "turgid", "matigas", "gahi", "wilted", "lanta", "nalanta", "nalaya", "plant cell", "selula ng halaman", "selula sa tanom", "tuyot", "membrane", "pagdaloy", "pag-agos", "naglalanta", "nawawalan ng tubig", "namamanas"], "fact": {"tl": "Kapag sapat ang tubig na pumapasok sa mga selula ng halaman sa pamamagitan ng osmosis, ang mga ito ay nagiging matigas at tuwid; kapag kulang ang tubig, ang halaman ay nalalanta.", "en": "When enough water enters a plant's cells through osmosis, the cells become firm and upright; when water is lacking, the plant wilts.", "bis": "Kon igo ang tubig nga mosulod sa mga selula sa tanom pinaagi sa osmosis, kini mahimong gahi ug tul-id; kon kulang ang tubig, malaya ang tanom."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "paramecium-microbe-g7", "domain": "LIVING_THINGS", "topic": "paramecium single-celled organism", "grades": [6, 7, 8, 9], "terms": ["paramecium", "paramesyum", "microbe", "mikrobyo", "isa-isang selula", "single-celled", "usa ka selula", "protozoa", "protozoan", "cilia", "buhok-buhok", "balahibo-balahibo", "tubig", "water", "lawa", "pond", "lumalangoy", "naglalangoy", "naglangoy", "mikroskopyo", "microscope", "tubig-tabang"], "fact": {"tl": "Ang paramecium ay isang maliit na nilalang na binubuo ng isang selula lamang, na lumalangoy sa tubig-tabang gamit ang libong maliliit na buhok-buhok na tinatawag na cilia.", "en": "A paramecium is a tiny living thing made of just one cell, swimming in fresh water using thousands of tiny hairs called cilia.", "bis": "Ang paramecium usa ka gamayng buhi nga binuhat nga usa ra ka selula, nga molangoy sa tab-ang nga tubig gamit ang liboan ka gagmayng balahibo nga gitawag og cilia."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "photosynthesis-detailed-g7", "domain": "LIVING_THINGS", "topic": "photosynthesis process", "grades": [6, 7, 8, 9], "terms": ["photosynthesis", "potosintesis", "halaman", "tanom", "plant", "dahon", "leaf", "sikat ng araw", "sunlight", "kahayag sa adlaw", "carbon dioxide", "tubig", "water", "glucose", "asukal", "azukar", "oxygen", "oksiheno", "chlorophyll", "klorophyll", "luntian", "berde", "pagkain", "gumagawa ng pagkain", "naghahimo og pagkain"], "fact": {"tl": "Sa photosynthesis, ginagamit ng halaman ang sikat ng araw, carbon dioxide mula sa hangin, at tubig upang gumawa ng asukal na pagkain at maglabas ng oxygen.", "en": "In photosynthesis, a plant uses sunlight, carbon dioxide from the air, and water to make sugar for food and release oxygen.", "bis": "Sa photosynthesis, gigamit sa tanom ang kahayag sa adlaw, carbon dioxide gikan sa hangin, ug tubig aron maghimo og asukal nga pagkaon ug mobuga og oxygen."}, "source": "NRC LS1.C; AAAS Benchmarks 5E; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "phylogenetic-tree-g9", "domain": "LIVING_THINGS", "topic": "phylogenetic tree of relationships", "grades": [8, 9, 10], "terms": ["phylogenetic tree", "puno ng ebolusyon", "puno sa ebolusyon", "evolutionary tree", "tree of life", "puno ng buhay", "pagkakamag-anak", "kaugnayan", "kaliwatan", "common ancestor", "ninuno", "katigulangan", "sanga", "branch", "species", "uri", "klase", "ebolusyon", "evolution", "magkakaugnay", "magkadugtong"], "fact": {"tl": "Ang phylogenetic tree ay isang diagram na parang puno na nagpapakita kung paano nagkakaugnay ang iba't ibang uri ng nilalang at kung sino ang kanilang ninunong pinagmulan.", "en": "A phylogenetic tree is a branching diagram that shows how different kinds of living things are related and which common ancestors they share.", "bis": "Ang phylogenetic tree usa ka diagram nga sama sa kahoy nga nagpakita kon giunsa pagkadugtong ang nagkalainlaing matang sa buhi nga binuhat ug kinsa ang ilang gigikanan nga katigulangan."}, "source": "NRC LS4.A Evidence of Common Ancestry; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "plant-tissue-culture-jar-g9", "domain": "LIVING_THINGS", "topic": "plant tissue culture propagation", "grades": [8, 9, 10], "terms": ["tissue culture", "pagpaparami ng halaman", "pagpadaghan sa tanom", "plant propagation", "garapon", "jar", "laboratoryo", "laboratory", "agar", "gel", "selula ng halaman", "selula sa tanom", "klon", "clone", "kambal", "bagong halaman", "bag-ong tanom", "sterile", "malinis", "biotechnology", "bioteknolohiya"], "fact": {"tl": "Sa plant tissue culture, isang maliit na piraso ng halaman ay pinatutubo sa malinis na garapon na may sustansyang gel upang makagawa ng maraming bagong halamang magkakapareho.", "en": "In plant tissue culture, a tiny piece of a plant is grown in a clean jar of nutrient gel to produce many new, identical plants.", "bis": "Sa plant tissue culture, usa ka gamayng tipik sa tanom ang patuboon sulod sa limpyong garapon nga may sustansyang gel aron makahimo og daghang bag-ong tanom nga managsama."}, "source": "DepEd MATATAG Science (biotechnology); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pollination-g5", "domain": "LIVING_THINGS", "topic": "pollination of flowers", "grades": [4, 5, 6, 7], "terms": ["pollination", "polinasyon", "bulaklak", "flower", "bulak", "polen", "pollen", "bubuyog", "bee", "putyukan", "buyog", "paru-paro", "butterfly", "alibangbang", "ibon", "bird", "langgam", "hangin", "wind", "bunga", "buto", "binhi", "fruit", "seed", "lumilipat ng polen", "namumunga"], "fact": {"tl": "Ang pollination ay ang paglipat ng polen mula sa isang bulaklak patungo sa iba, kadalasang tinutulungan ng mga bubuyog, paru-paro, ibon, o hangin, upang makabuo ng bunga at buto.", "en": "Pollination is the moving of pollen from one flower to another, often helped by bees, butterflies, birds, or wind, so that fruits and seeds can form.", "bis": "Ang polinasyon mao ang pagbalhin sa polen gikan sa usa ka bulak ngadto sa lain, kasagaran tabangan sa mga putyukan, alibangbang, langgam, o hangin, aron makabuhat og bunga ug liso."}, "source": "NRC LS1.B Reproduction; AAAS Benchmarks 5C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "punnett-square-g9", "domain": "LIVING_THINGS", "topic": "Punnett square inheritance", "grades": [8, 9, 10], "terms": ["Punnett square", "mana", "kamana", "inheritance", "panulondon", "gene", "gen", "allele", "trait", "katangian", "kinaiya", "dominant", "nangingibabaw", "recessive", "nakatago", "rekesibo", "magulang", "parents", "ginikanan", "anak", "offspring", "posibilidad", "tsansa", "chance", "genetika", "genetics"], "fact": {"tl": "Ang Punnett square ay isang tsart na ginagamit upang ipakita ang mga posibleng katangian ng anak base sa mga gene na minana nito mula sa dalawang magulang.", "en": "A Punnett square is a chart used to show the possible traits of offspring based on the genes inherited from two parents.", "bis": "Ang Punnett square usa ka tsart nga gigamit aron ipakita ang mga posibleng kinaiya sa anak base sa mga gen nga napanunod gikan sa duha ka ginikanan."}, "source": "NRC LS3.B Variation of Traits; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "root-hair-cell-soil-g7", "domain": "LIVING_THINGS", "topic": "root hair cells absorb water", "grades": [6, 7, 8, 9], "terms": ["root hair", "buhok ng ugat", "balahibo sa gamot", "root hair cell", "ugat", "root", "gamot", "lupa", "soil", "yuta", "tubig", "water", "mineral", "sustansya", "sustansiya", "sumisipsip", "umaakit", "nagsipsip", "nag-suyop", "absorb", "halaman", "tanom", "manipis", "haba", "lawak"], "fact": {"tl": "Ang mga selula ng buhok ng ugat ay manipis at mahaba upang madagdagan ang lawak na sumisipsip ng tubig at mineral mula sa lupa para sa halaman.", "en": "Root hair cells are thin and long to increase the surface that soaks up water and minerals from the soil for the plant.", "bis": "Ang mga selula sa balahibo sa gamot nipis ug taas aron madugangan ang gilapdon nga mosuyop og tubig ug mineral gikan sa yuta para sa tanom."}, "source": "NRC LS1.A Structure and Function; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tardigrade-water-bear-g7", "domain": "LIVING_THINGS", "topic": "tardigrade extreme survival", "grades": [6, 7, 8, 9], "terms": ["tardigrade", "water bear", "oso ng tubig", "oso sa tubig", "moss bear", "mikroskopyo", "microscope", "mikroskopiko", "tiny", "napakaliit", "gagmay kaayo", "lumot", "moss", "init", "lamig", "extreme", "buhay", "nabubuhay", "mabuhi", "matibay", "lakas ng katawan", "walang tubig", "espasyo", "space"], "fact": {"tl": "Ang tardigrade o water bear ay napakaliit na hayop na nakikita lang sa mikroskopyo at kayang mabuhay sa matinding init, lamig, at kawalan ng tubig.", "en": "The tardigrade, or water bear, is a tiny animal seen only under a microscope that can survive extreme heat, cold, and lack of water.", "bis": "Ang tardigrade o water bear usa ka gamay kaayo nga mananap nga makita lang sa mikroskopyo ug makasugakod sa hilabihang kainit, katugnaw, ug kawad-on sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "taxonomic-hierarchy-g8", "domain": "LIVING_THINGS", "topic": "levels of biological classification", "grades": [7, 8, 9, 10], "terms": ["taxonomy", "klasipikasyon", "classification", "pag-uuri", "pagklasipikar", "kingdom", "kaharian", "gingharian", "phylum", "class", "klase", "order", "family", "pamilya", "genus", "species", "uri", "espesye", "antas", "lebel", "hagdan", "grupo", "pangkat", "Linnaeus", "magkakapareho"], "fact": {"tl": "Inuuri ng mga siyentipiko ang mga nilalang sa mga antas mula sa pinakamalawak hanggang pinakamaliit: kingdom, phylum, class, order, family, genus, at species.", "en": "Scientists classify living things in levels from broadest to smallest: kingdom, phylum, class, order, family, genus, and species.", "bis": "Giklasipikar sa mga siyentista ang mga buhi nga binuhat sa mga ang-ang gikan sa pinakalapad ngadto sa pinakagamay: kingdom, phylum, class, order, family, genus, ug species."}, "source": "NRC LS4.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "transcription-translation-g10", "domain": "LIVING_THINGS", "topic": "gene expression transcription and translation", "grades": [9, 10], "terms": ["transcription", "transkripsyon", "translation", "translasyon", "DNA", "RNA", "mRNA", "protina", "protein", "gene", "gen", "code", "kodigo", "instruction", "utos", "mando", "nukleyus", "nucleus", "ribosome", "ribosoma", "selula", "amino acid", "ginagawa", "binabasa", "gibasa"], "fact": {"tl": "Sa transcription, kinokopya ang utos ng DNA tungo sa mRNA, at sa translation, binabasa ito ng ribosome upang gumawa ng protina ayon sa kodigo ng gene.", "en": "In transcription, the DNA instructions are copied into mRNA, and in translation, a ribosome reads the mRNA to build a protein following the gene's code.", "bis": "Sa transcription, gikopya ang mando sa DNA ngadto sa mRNA, ug sa translation, gibasa kini sa ribosome aron maghimo og protina sumala sa kodigo sa gen."}, "source": "NRC LS1.A; LS3.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "vacuole-plant-cell-closeup-g8", "domain": "LIVING_THINGS", "topic": "plant cell vacuole", "grades": [7, 8, 9, 10], "terms": ["vacuole", "bakuwol", "selula ng halaman", "selula sa tanom", "plant cell", "tubig", "water", "imbakan", "tindahan", "tipiganan", "storage", "tigib", "matigas", "gahi", "turgid", "membrane", "central vacuole", "malaki", "espasyo", "nag-iimbak", "nagtipig", "naghuyop"], "fact": {"tl": "Ang vacuole ay isang malaking espasyo sa loob ng selula ng halaman na nag-iimbak ng tubig at sustansya at tumutulong panatilihing matigas at tuwid ang halaman.", "en": "The vacuole is a large space inside a plant cell that stores water and nutrients and helps keep the plant firm and upright.", "bis": "Ang vacuole usa ka dakong luna sulod sa selula sa tanom nga nagtipig og tubig ug sustansya ug motabang nga magpabilin nga gahi ug tul-id ang tanom."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "virus-particle-portrait-g8", "domain": "LIVING_THINGS", "topic": "virus structure and reproduction", "grades": [7, 8, 9, 10], "terms": ["virus", "birus", "mikrobyo", "germ", "sakit", "disease", "protina", "protein", "genetic material", "DNA", "RNA", "host cell", "selula", "namamatay", "kumakalat", "nagpaparami", "nagdaghan", "trangkaso", "flu", "napakaliit", "gagmay kaayo", "buhay", "hindi buhay"], "fact": {"tl": "Ang virus ay napakaliit na particle na binubuo ng genetic material na nababalot ng protina, at ito ay makakapagparami lamang kapag pumasok sa loob ng buhay na selula.", "en": "A virus is a tiny particle made of genetic material wrapped in protein, and it can only multiply when it gets inside a living cell.", "bis": "Ang virus usa ka gamay kaayo nga partikulo nga gilangkoban og genetic material nga giputos sa protina, ug makapadaghan lang kini kon makasulod sa sulod sa buhi nga selula."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "yeast-budding-microbe-g7", "domain": "LIVING_THINGS", "topic": "yeast reproduction by budding", "grades": [6, 7, 8, 9], "terms": ["yeast", "lebadura", "fungi", "halamang-singaw", "uhong", "fungus", "budding", "pagsupling", "usbaw", "pagtubo", "tinapay", "bread", "pan", "fermentation", "pagbuburo", "alak", "isa-isang selula", "single-celled", "umaalsa", "carbon dioxide", "nagpaparami", "nagdaghan", "supling"], "fact": {"tl": "Ang yeast o lebadura ay isang halamang-singaw na binubuo ng isang selula na nagpaparami sa pamamagitan ng budding, kung saan tumutubo ang maliit na supling sa gilid nito.", "en": "Yeast is a single-celled fungus that reproduces by budding, where a small new cell grows out from the side of the parent.", "bis": "Ang yeast o lebadura usa ka fungus nga usa ka selula nga magpadaghan pinaagi sa budding, diin moturok ang gamayng bag-ong selula sa kilid niini."}, "source": "NRC LS1.B Reproduction; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "biomolecules-g10", "domain": "LIVING_THINGS", "topic": "four main biomolecules", "grades": [9, 10], "terms": ["biomolecules", "biomolekyul", "carbohydrates", "karbohidrat", "asukal", "lipids", "taba", "tambok", "fats", "protein", "protina", "nucleic acid", "DNA", "RNA", "selula", "katawan", "pagkain", "food", "pagkaon", "sustansya", "molekula", "molecule", "buhay", "tinapay", "karne", "mantika"], "fact": {"tl": "Ang apat na pangunahing biomolecule sa mga buhay na nilalang ay carbohydrates, lipids o taba, proteins, at nucleic acids tulad ng DNA.", "en": "The four main biomolecules in living things are carbohydrates, lipids or fats, proteins, and nucleic acids such as DNA.", "bis": "Ang upat ka nag-unang biomolecule sa buhi nga mga binuhat mao ang carbohydrates, lipids o tambok, proteins, ug nucleic acids sama sa DNA."}, "source": "NRC LS1.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "phospholipid-bilayer-g10", "domain": "LIVING_THINGS", "topic": "cell membrane phospholipid bilayer", "grades": [9, 10], "terms": ["phospholipid bilayer", "cell membrane", "lamad ng selula", "panit sa selula", "membrane", "phospholipid", "dalawang patong", "duha ka sapaw", "double layer", "taba", "fat", "tambok", "head", "ulo", "tail", "buntot", "tubig", "water", "pumipigil", "nagpapasok", "nagpapadaan", "selula", "harang"], "fact": {"tl": "Ang lamad ng selula ay gawa sa phospholipid bilayer, dalawang patong ng molekula ng taba na bumubuo ng harang na kontrolado kung ano ang papasok at lalabas sa selula.", "en": "The cell membrane is made of a phospholipid bilayer, two layers of fat molecules that form a barrier controlling what enters and leaves the cell.", "bis": "Ang lamad sa selula hinimo sa phospholipid bilayer, duha ka sapaw sa molekula sa tambok nga maghimo og babag nga nagkontrol kon unsa ang mosulod ug mogawas sa selula."}, "source": "NRC LS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "photosynthesis-vs-combustion-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "photosynthesis stores energy, combustion releases it", "grades": [8, 9, 10], "terms": ["photosynthesis", "potosintesis", "combustion", "pagkasunog", "pagsunog", "burning", "pagdilaab", "energy", "enerhiya", "kusog", "oxygen", "oksiheno", "carbon dioxide", "sikat ng araw", "sunlight", "kahayag", "init", "heat", "kainit", "halaman", "tanom", "apoy", "kalaban", "kabaligtaran", "sumisipsip", "naglalabas"], "fact": {"tl": "Ang photosynthesis at combustion ay magkasalungat: ang photosynthesis ay sumisipsip ng enerhiya ng araw upang gumawa ng asukal at oxygen, habang ang combustion ay nagsusunog ng asukal o gatong gamit ang oxygen upang maglabas ng enerhiya.", "en": "Photosynthesis and combustion are opposites: photosynthesis takes in the sun's energy to make sugar and oxygen, while combustion burns sugar or fuel with oxygen to release energy.", "bis": "Ang photosynthesis ug combustion magkasumpaki: ang photosynthesis mosuyop sa enerhiya sa adlaw aron maghimo og asukal ug oxygen, samtang ang combustion mosunog sa asukal o gatong gamit ang oxygen aron mobuga og enerhiya."}, "source": "NRC LS1.C; PS3.D; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "nitrogen-cycle-g8", "domain": "EARTH_SPACE", "topic": "nitrogen cycle", "grades": [7, 8, 9, 10], "terms": ["nitrogen cycle", "siklo ng nitroheno", "siklo sa nitroheno", "nitrogen", "nitroheno", "hangin", "air", "lupa", "soil", "yuta", "bacteria", "bakterya", "halaman", "tanom", "plant", "protina", "protein", "sustansya", "pataba", "fertilizer", "abono", "ugat", "decomposers", "umuulit", "pabalik-balik", "siklo"], "fact": {"tl": "Sa nitrogen cycle, ang nitroheno mula sa hangin ay binabago ng bakterya sa lupa upang magamit ng mga halaman, at bumabalik ito sa hangin kapag nabubulok ang mga namatay na nilalang.", "en": "In the nitrogen cycle, nitrogen from the air is changed by soil bacteria into a form plants can use, and it returns to the air when dead things decay.", "bis": "Sa nitrogen cycle, ang nitroheno gikan sa hangin usbon sa bakterya sa yuta ngadto sa porma nga magamit sa mga tanom, ug mobalik kini sa hangin kon madunot ang mga patay nga binuhat."}, "source": "NRC LS2.B Cycles of Matter; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-g5", "domain": "EARTH_SPACE", "topic": "the Sun as a star", "grades": [3, 4, 5, 6], "terms": ["sun", "araw", "adlaw", "bituin", "star", "bituon", "init", "heat", "kainit", "liwanag", "light", "kahayag", "enerhiya", "energy", "kusog", "sistemang solar", "solar system", "gas", "init na gas", "pinakamalapit", "pinakaduol", "araw-araw", "umaga", "buhay", "halaman"], "fact": {"tl": "Ang Araw ay isang bituin, isang napakalaking bolang gas na mainit, at ito ang pinakamalapit na bituin sa Earth na nagbibigay ng liwanag at init para sa buhay.", "en": "The Sun is a star, a giant ball of hot gas, and it is the closest star to Earth, giving the light and heat that life needs.", "bis": "Ang Adlaw usa ka bituon, usa ka dakong bola sa init nga gas, ug mao kini ang pinakaduol nga bituon sa Yuta nga naghatag og kahayag ug kainit para sa kinabuhi."}, "source": "NRC ESS1.A; AAAS Benchmarks 4A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "circuit-schematic-symbols-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "circuit schematic symbols", "grades": [6, 7, 8, 9], "terms": ["circuit", "sirkito", "schematic", "diagram", "dayagram", "symbols", "simbolo", "baterya", "battery", "bombilya", "bulb", "switch", "swits", "wire", "kawad", "alambre", "kuryente", "electricity", "koryente", "guhit", "linya", "drawing", "kuryenteng dumadaloy"], "fact": {"tl": "Sa circuit schematic, gumagamit ang mga inhinyero ng simpleng simbolo—linya para sa kawad, dalawang guhit para sa baterya, at bilog para sa bombilya—upang iguhit kung paano dumadaloy ang kuryente.", "en": "In a circuit schematic, engineers use simple symbols, such as a line for a wire, two bars for a battery, and a circle for a bulb, to draw how electricity flows.", "bis": "Sa circuit schematic, mogamit ang mga inhenyero og yanong simbolo, sama sa linya para sa alambre, duha ka guhit para sa baterya, ug lingin para sa bombilya, aron idrowing kon unsaon pagdagayday sa kuryente."}, "source": "AAAS Benchmarks 8B; NRC PS3.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "electromagnet-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "electromagnet", "grades": [6, 7, 8, 9], "terms": ["electromagnet", "elektromagnet", "magnet", "magneto", "kuryente", "electricity", "koryente", "kawad", "wire", "alambre", "coil", "ikid", "pasikut-sikot", "bakal", "iron", "puthaw", "pako", "nail", "lansang", "magnetic field", "naaakit", "umaakit", "nag-aakit"], "fact": {"tl": "Ang electromagnet ay isang magnet na gawa sa pinaikot na kawad sa paligid ng bakal, at ito ay nagiging magnetiko lamang habang may dumadaloy na kuryente.", "en": "An electromagnet is a magnet made of wire coiled around iron, and it becomes magnetic only while electricity is flowing through it.", "bis": "Ang electromagnet usa ka magnet nga hinimo sa alambre nga giliyok palibot sa puthaw, ug mahimo lang kining magnetiko samtang may kuryente nga modagayday niini."}, "source": "NRC PS2.B; AAAS Benchmarks 4G; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mudfish-dalag-g5", "domain": "LIVING_THINGS", "topic": "dalag snakehead mudfish", "grades": [4, 5, 6, 7], "terms": ["mudfish", "dalag", "snakehead", "haloan", "haruan", "isda", "fish", "putik", "mud", "lapok", "lawa", "swamp", "lanaw", "kanal", "palayan", "rice paddy", "humihinga ng hangin", "naga-ginhawa", "predator", "mandaragit", "ulo ng ahas", "tubig-tabang", "freshwater", "nakakahuni"], "fact": {"tl": "Ang dalag o snakehead ay isang isda sa tubig-tabang sa Pilipinas na naninirahan sa mga palayan at putikang lawa, at kayang huminga ng hangin upang mabuhay sa tubig na kulang sa oxygen.", "en": "The dalag or snakehead is a Philippine freshwater fish that lives in rice paddies and muddy swamps, and it can gulp air to survive in water low in oxygen.", "bis": "Ang haloan o snakehead usa ka tab-ang nga isda sa Pilipinas nga nagpuyo sa kahumayan ug lapokon nga lanaw, ug makaginhawa kini og hangin aron mabuhi sa tubig nga kulang sa oxygen."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mungbean-munggo-g4", "domain": "LIVING_THINGS", "topic": "mung bean munggo plant", "grades": [3, 4, 5, 6], "terms": ["mung bean", "munggo", "monggo", "mongo", "balatong", "legume", "gulay", "vegetable", "utan", "buto", "binhi", "seed", "liso", "ugat", "root", "gamot", "nitrogen", "lupa", "pataba", "abono", "protina", "protein", "pagkain", "ginisang munggo", "tumutubo", "halaman", "tanom", "tumubo"], "fact": {"tl": "Ang munggo ay isang halamang gulay na mayaman sa protina, at ang mga ugat nito ay tumutulong magdagdag ng nitroheno sa lupa upang maging mas mataba ito para sa ibang pananim.", "en": "The mung bean or munggo is a vegetable plant rich in protein, and its roots help add nitrogen to the soil, making it more fertile for other crops.", "bis": "Ang munggo usa ka utanon nga tanom nga dato sa protina, ug ang mga gamot niini motabang sa pagdugang og nitroheno sa yuta aron mahimo kining mas tambok para sa ubang tanom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "myna-flock-roost-g5", "domain": "LIVING_THINGS", "topic": "myna bird flock and roost", "grades": [4, 5, 6, 7], "terms": ["myna", "martines", "mynah", "kuliawan", "ibon", "bird", "langgam", "kawan", "flock", "panon", "puno", "tree", "kahoy", "tulugan", "roost", "katulgan", "gabi", "evening", "gabii", "huni", "tunog", "ingay", "gumagaya", "tumutulad", "social", "magkakasama", "lungsod"], "fact": {"tl": "Ang martines o myna ay isang itim na ibon na laganap sa Pilipinas na nagtitipon sa malalaking kawan sa mga puno tuwing gabi, at kayang gayahin ang iba't ibang tunog.", "en": "The myna or martines is a common black bird in the Philippines that gathers in large flocks in trees each evening to roost, and it can mimic many sounds.", "bis": "Ang martines o myna usa ka itom nga langgam nga kasagaran sa Pilipinas nga magtigom sa dagkong panon sa mga kahoy matag gabii aron matulog, ug makasundog kini sa lainlaing tingog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "narra-g5", "domain": "LIVING_THINGS", "topic": "narra national tree", "grades": [4, 5, 6, 7], "terms": ["narra", "pambansang puno", "national tree", "nasudnong kahoy", "kahoy", "tree", "Pilipinas", "Philippines", "matibay", "kahoy na matigas", "hardwood", "muwebles", "furniture", "kasangkapan", "bulaklak", "dilaw na bulaklak", "yellow flowers", "lilim", "anino", "gubat", "forest", "lasang", "tumutubo", "lumalaki"], "fact": {"tl": "Ang narra ang pambansang puno ng Pilipinas, isang malaking punong may matibay na kahoy na ginagamit sa muwebles at namumukadkad ng mababangong dilaw na bulaklak.", "en": "The narra is the national tree of the Philippines, a large tree with strong wood used for furniture, and it blooms fragrant yellow flowers.", "bis": "Ang narra mao ang nasudnong kahoy sa Pilipinas, usa ka dakong kahoy nga adunay lig-on nga kahoy nga gigamit sa muwebles ug mamulak og humot nga dilaw nga bulak."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "native-chicken-darag-g4", "domain": "LIVING_THINGS", "topic": "Darag native chicken", "grades": [3, 4, 5, 6], "terms": ["native chicken", "manok na bisaya", "bisayang manok", "darag", "manok", "chicken", "Iloilo", "Western Visayas", "katutubo", "lumad", "lokal", "itlog", "egg", "balahibo", "feathers", "balhibo", "kayumanggi", "kapaw", "free range", "matibay", "sakahan", "uma", "alaga"], "fact": {"tl": "Ang Darag ay isang katutubong manok ng Pilipinas mula sa Western Visayas na may kayumangging balahibo, kilala sa pagiging matibay at sa masarap nitong karne at itlog.", "en": "The Darag is a native Philippine chicken from Western Visayas with brownish feathers, known for being hardy and for its tasty meat and eggs.", "bis": "Ang Darag usa ka lumad nga manok sa Pilipinas gikan sa Kasadpang Bisayas nga adunay kayumanggi nga balhibo, ilado sa pagkalig-on ug sa lami niini nga karne ug itlog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "native-horse-kabayong-bundok-g5", "domain": "LIVING_THINGS", "topic": "native Philippine horse", "grades": [4, 5, 6], "terms": ["kabayong bundok", "katutubong kabayo", "kabayo", "mountain horse", "kabayo sa bukid", "native horse", "Philippine horse", "pony", "lumad nga kabayo"], "fact": {"tl": "Ang katutubong kabayong bundok ng Pilipinas ay maliit at matipuno, kaya magaling itong umakyat sa mabatong burol at gamitin sa pagdadala ng mga kargada sa mga lugar na walang daan.", "en": "The native Philippine mountain horse is small but sturdy, so it can climb rocky hills and is used to carry loads in places without roads.", "bis": "Ang lumad nga kabayo sa bukid sa Pilipinas gamay apan kusgan, mao nga maayo kini mosaka sa batoon nga bungtod ug gigamit sa pagdala og mga karga sa mga dapit nga walay dalan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "native-pig-baboy-bisaya-g5", "domain": "LIVING_THINGS", "topic": "native Philippine pig", "grades": [4, 5, 6], "terms": ["baboy bisaya", "katutubong baboy", "baboy", "native pig", "black pig", "itim na baboy", "baboy nga itom", "lumad nga baboy", "backyard pig"], "fact": {"tl": "Ang baboy Bisaya ay isang katutubong itim na baboy na maliit at matibay, kaya nabubuhay ito sa pag-aalaga sa likod-bahay at pagkain ng mga tira-tirang pagkain.", "en": "The Baboy Bisaya is a native black pig that is small and hardy, so it can thrive in backyard raising and eats leftover scraps.", "bis": "Ang baboy Bisaya usa ka lumad nga itom nga baboy nga gamay ug kusgan, mao nga mabuhi kini sa pag-atiman sa likod sa balay ug mokaon sa mga sobra nga pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "nautilus-shell-chambered-g6", "domain": "LIVING_THINGS", "topic": "chambered nautilus", "grades": [5, 6, 7], "terms": ["nautilus", "chambered nautilus", "kabibe", "shell", "kabibi", "spiral shell", "sea creature", "mollusk", "kinason", "spiral nga kabibe"], "fact": {"tl": "Ang nautilus ay isang hayop sa dagat na may makapal na nakapulupot na kabibe na hati-hati sa mga silid, at pinupuno nito ng hangin o tubig ang mga silid para lumutang o lumubog.", "en": "The nautilus is a sea animal with a thick spiral shell divided into chambers, and it fills the chambers with gas or water to float or sink.", "bis": "Ang nautilus usa ka hayop sa dagat nga adunay baga nga nagliko-liko nga kabibe nga gibahin-bahin sa mga lawak, ug gipuno niini og hangin o tubig ang mga lawak aron molutaw o molunod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "needlefish-suaw-g5", "domain": "LIVING_THINGS", "topic": "needlefish", "grades": [4, 5, 6], "terms": ["needlefish", "suaw", "siwid", "batalay", "isda", "manipis na isda", "long thin fish", "pointed jaw", "isdang may tulis na nguso", "fish"], "fact": {"tl": "Ang needlefish o suaw ay isang manipis at mahabang isda na may matulis na nguso na parang karayom, at madalas itong lumangoy malapit sa ibabaw ng tubig.", "en": "The needlefish, or suaw, is a thin, long fish with a sharp needle-like jaw, and it often swims near the water's surface.", "bis": "Ang needlefish o suaw usa ka nipis ug taas nga isda nga adunay talinis nga sungo nga morag dagom, ug kanunay kini molangoy duol sa ibabaw sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "newt-salamander-g5", "domain": "LIVING_THINGS", "topic": "salamander and newt", "grades": [4, 5, 6], "terms": ["salamander", "newt", "salamandra", "amphibian", "amphibyan", "hayop na may apat na paa", "moist skin", "basa na balat", "hayop sa tubig at lupa", "umog nga panit"], "fact": {"tl": "Ang salamander at newt ay mga amphibian na parang butiki ang hugis pero may malambot at basa-basang balat, at kailangan nilang manatili malapit sa basa o malamig na lugar.", "en": "Salamanders and newts are amphibians shaped like lizards but with soft, moist skin, and they must stay near wet or cool places.", "bis": "Ang salamander ug newt mga amphibian nga morag tiki og porma apan adunay humok ug umog nga panit, ug kinahanglan sila magpabilin duol sa basa o bugnaw nga mga dapit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "octopus-jet-swim-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "octopus jet propulsion", "grades": [4, 5, 6], "terms": ["octopus", "pugita", "kugita", "jet swim", "jet propulsion", "pagbuga ng tubig", "tumulak", "lumangoy", "walong paa", "tentacles", "galaw"], "fact": {"tl": "Ang pugita ay lumalangoy nang mabilis sa pamamagitan ng pagbuga ng tubig palabas sa katawan nito, kaya itinutulak nito ang sarili sa kabaligtarang direksiyon.", "en": "An octopus swims fast by squirting water out of its body, which pushes it in the opposite direction.", "bis": "Ang kugita molangoy og paspas pinaagi sa pagbuga sa tubig pagawas sa lawas niini, mao nga gitulod niini ang kaugalingon sa atbang nga direksiyon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "palawan-bearcat-binturong-g6", "domain": "LIVING_THINGS", "topic": "Palawan binturong", "grades": [5, 6, 7], "terms": ["binturong", "bearcat", "Palawan bearcat", "menturon", "hayop sa Palawan", "hayop sa gabi", "nocturnal animal", "buntot na panghawak", "prehensile tail", "puno", "ikog nga makakupot"], "fact": {"tl": "Ang binturong o bearcat ng Palawan ay isang hayop na gumagala sa gabi sa mga puno, at gumagamit ito ng mahabang buntot na panghawak na parang dagdag na kamay sa pag-akyat.", "en": "The Palawan binturong, or bearcat, is a night-roaming animal that lives in trees, and it uses a long grasping tail like an extra hand to climb.", "bis": "Ang binturong o bearcat sa Palawan usa ka hayop nga magsuroy-suroy sa gabii sa mga kahoy, ug gigamit niini ang taas nga ikog nga makakupot nga morag dugang kamot sa pagsaka."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "palengke-fish-stall-freshness-g5", "domain": "LIVING_THINGS", "topic": "judging fresh fish", "grades": [4, 5, 6], "terms": ["sariwang isda", "palengke", "fresh fish", "tindahan ng isda", "presko nga isda", "merkado", "fish stall", "pulang hasang", "red gills", "malinaw na mata", "clear eyes", "freshness"], "fact": {"tl": "Ang sariwang isda sa palengke ay may pulang-pula at basang hasang, malinaw at umbok na mata, at matigas na laman na bumabalik kapag pinindot.", "en": "Fresh fish at the market has bright red moist gills, clear bulging eyes, and firm flesh that springs back when pressed.", "bis": "Ang presko nga isda sa merkado adunay pula kaayo ug basa nga hasang, tin-aw ug burot nga mata, ug gahi nga unod nga mobalik kung ipislit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "parrotfish-mulmol-g5", "domain": "LIVING_THINGS", "topic": "parrotfish and coral sand", "grades": [4, 5, 6], "terms": ["parrotfish", "mulmol", "molmol", "isda ng bahura", "coral", "korales", "buhangin", "sand", "ngipin na parang tuka", "beak teeth", "reef fish", "isdang makulay"], "fact": {"tl": "Ang mulmol o parrotfish ay isang makulay na isda na may ngiping parang tuka ng loro na ginagamit nito sa pagkagat ng korales, at ang dumi nito ay nagiging puting buhangin.", "en": "The parrotfish has a parrot-like beak of teeth that it uses to bite coral, and its droppings turn into white sand.", "bis": "Ang molmol o parrotfish usa ka kolor-kolor nga isda nga adunay ngipon nga morag sungo sa loro nga gigamit sa pagkagat sa korales, ug ang hugaw niini mahimong puti nga balas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "philippine-pheasant-g6", "domain": "LIVING_THINGS", "topic": "Palawan peacock-pheasant", "grades": [5, 6, 7], "terms": ["pheasant", "Palawan peacock-pheasant", "tandikan", "ibon", "ibon sa kagubatan", "forest bird", "langgam", "makulay na balahibo", "iridescent feathers", "endemic bird", "endangered"], "fact": {"tl": "Ang Palawan peacock-pheasant o tandikan ay isang ibong-gubat na endemiko sa Palawan lamang, at ipinagmamalaki ng lalaki nito ang makinang at bughaw-luntiang mga balahibo sa pagliligaw.", "en": "The Palawan peacock-pheasant, or tandikan, is a forest bird found only in Palawan, and the male shows off shiny blue-green feathers when courting.", "bis": "Ang Palawan peacock-pheasant o tandikan usa ka langgam sa kalasangan nga makita lamang sa Palawan, ug ang laki niini magpasigarbo sa kidlap nga asul-lunhaw nga mga balhibo kung manguyab."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "philippine-eagle-wings-spread-g6", "domain": "LIVING_THINGS", "topic": "Philippine eagle", "grades": [4, 5, 6, 7], "terms": ["Philippine eagle", "agila", "haribon", "Pithecophaga", "agila ng Pilipinas", "national bird", "pambansang ibon", "malalapad na pakpak", "broad wings", "raptor", "endangered", "ibong mandaragit"], "fact": {"tl": "Ang agila ng Pilipinas ay isa sa pinakamalaking agila sa mundo, may mga pakpak na halos dalawang metro ang laylayan, at ito ang pambansang ibon ng bansa.", "en": "The Philippine eagle is one of the largest eagles in the world, with wings that span almost two meters, and it is the country's national bird.", "bis": "Ang agila sa Pilipinas usa sa pinakadako nga agila sa kalibutan, adunay mga pako nga halos duha ka metro ang gilapdon, ug kini ang nasudnong langgam sa nasod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "philippine-mallard-itik-pato-g4", "domain": "LIVING_THINGS", "topic": "Philippine duck and itik", "grades": [3, 4, 5], "terms": ["itik", "pato", "Philippine duck", "papan", "bibe", "duck", "balut", "itlog ng itik", "duck eggs", "lawang ibon", "waterfowl", "alaga"], "fact": {"tl": "Ang itik o pato ay isang ibong palundag-lundag sa tubig na may balahibong di basang-basa, at marami itong inaalagaan sa Pilipinas para sa itlog na ginagawang balut.", "en": "The duck, or itik, is a water bird with waterproof feathers, and many are raised in the Philippines for the eggs used to make balut.", "bis": "Ang itik o pato usa ka langgam sa tubig nga adunay balhibo nga dili mabasa, ug daghan ang gi-atiman niini sa Pilipinas alang sa itlog nga gihimo nga balut."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "philippine-trogon-g6", "domain": "LIVING_THINGS", "topic": "Philippine trogon", "grades": [5, 6, 7], "terms": ["trogon", "Philippine trogon", "ibon sa kagubatan", "forest bird", "langgam", "makulay na ibon", "colorful bird", "red belly", "pulang tiyan", "kagubatan", "endemic bird"], "fact": {"tl": "Ang Philippine trogon ay isang makulay na ibong-gubat na may matingkad na pulang tiyan, at tahimik itong nakaupo nang matagal sa mga sanga habang naghihintay ng insekto.", "en": "The Philippine trogon is a colorful forest bird with a bright red belly, and it perches quietly on branches for long periods while waiting for insects.", "bis": "Ang Philippine trogon usa ka kolor-kolor nga langgam sa kalasangan nga adunay hayag nga pula nga tiyan, ug hilom kini molingkod og dugay sa mga sanga samtang nagpaabot og insekto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "philippine-warty-pig-piglet-g6", "domain": "LIVING_THINGS", "topic": "Philippine warty pig", "grades": [5, 6, 7], "terms": ["Philippine warty pig", "baboy-ramo", "baboy ihalas", "wild pig", "warty pig", "baboy gubat", "biik", "piglet", "endemic", "ihalas nga baboy", "badlis-badlis"], "fact": {"tl": "Ang baboy-ramo o Philippine warty pig ay isang ligaw na baboy na endemiko sa Pilipinas, at ang mga biik nito ay may guhit-guhit na balat na nagsisilbing kamuflahe sa gubat.", "en": "The Philippine warty pig is a wild pig found only in the Philippines, and its piglets have stripes that act as camouflage in the forest.", "bis": "Ang baboy-ihalas o Philippine warty pig usa ka ihalas nga baboy nga makita lamang sa Pilipinas, ug ang mga biik niini adunay badlis-badlis nga panit nga nagsilbing tagoanan sa kalasangan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pigeon-kalapati-feral-g4", "domain": "LIVING_THINGS", "topic": "pigeon", "grades": [3, 4, 5], "terms": ["kalapati", "pigeon", "salampati", "ibon sa lungsod", "city bird", "langgam", "dove", "homing pigeon", "ibong nakakauwi", "feral pigeon", "buto-buto"], "fact": {"tl": "Ang kalapati ay isang ibong palagiang nakikita sa mga lungsod, at ang ilang sanay na kalapati ay kayang makahanap ng daan pabalik sa kanilang tahanan kahit malayo.", "en": "The pigeon is a bird commonly seen in cities, and some trained pigeons can find their way back home even from far away.", "bis": "Ang salampati usa ka langgam nga kanunay makita sa mga siyudad, ug ang pipila ka bansay nga salampati makahimo og pangita sa dalan pabalik sa ilang puluy-anan bisan layo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "plant-bud-g4", "domain": "LIVING_THINGS", "topic": "plant bud", "grades": [3, 4, 5], "terms": ["usbong", "buko", "plant bud", "bud", "tumutubo", "tubo", "putot", "bagong dahon", "new leaf", "bulaklak na bubuka", "saha", "tanim"], "fact": {"tl": "Ang usbong ay isang maliit na umbok sa tangkay ng halaman kung saan tumutubo ang bagong dahon o bulaklak.", "en": "A bud is a small bump on a plant's stem from which a new leaf or flower grows.", "bis": "Ang putot usa ka gamay nga burot sa punoan sa tanom diin motubo ang bag-ong dahon o bulak."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "weaving-banig-mat-g5", "domain": "MATTER", "topic": "banig mat weaving from plant fibers", "grades": [4, 5, 6], "terms": ["banig", "habi", "weaving", "paghahabi", "sleeping mat", "pandan", "tikog", "halaman na hibla", "plant fiber", "natural na materyal", "hinabi", "gihabol"], "fact": {"tl": "Ang banig ay hinahabi mula sa mga tuyong dahon ng halaman gaya ng pandan o tikog, kaya ito ay isang likas na materyal na galing sa mga tanim.", "en": "A banig sleeping mat is woven from dried plant leaves such as pandan or tikog, so it is a natural material that comes from plants.", "bis": "Ang banig gihabol gikan sa mga uga nga dahon sa tanom sama sa pandan o tikog, mao nga kini usa ka natural nga materyal nga gikan sa mga tanom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "weighing-scale-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "weighing scale measures weight", "grades": [3, 4, 5], "terms": ["timbangan", "weighing scale", "timbang", "bigat", "weight", "mass", "panimbang", "kilo", "kilogramo", "sukat ng bigat", "timbangon", "gibug-aton"], "fact": {"tl": "Ang timbangan ay isang kasangkapang panukat na nagpapakita kung gaano kabigat ang isang bagay, kadalasan sa yunit na kilogramo.", "en": "A weighing scale is a measuring tool that shows how heavy an object is, usually in kilograms.", "bis": "Ang timbangan usa ka galamiton sa pagsukod nga nagpakita kung unsa kabug-at ang usa ka butang, kasagaran sa yunit nga kilogramo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wet-market-palengke-scene-g4", "domain": "LIVING_THINGS", "topic": "wet market food sources", "grades": [3, 4, 5], "terms": ["palengke", "wet market", "merkado", "tindahan", "gulay", "isda", "karne", "sariwang pagkain", "fresh food", "presko", "pinagkukunan ng pagkain", "food source"], "fact": {"tl": "Sa palengke ay makikita ang iba't ibang sariwang pagkaing galing sa halaman at hayop, gaya ng gulay, prutas, isda, at karne na kailangan ng katawan para lumakas.", "en": "At the wet market you can find many fresh foods from plants and animals, such as vegetables, fruits, fish, and meat that the body needs to stay strong.", "bis": "Sa merkado makita ang nagkalain-laing presko nga pagkaon gikan sa tanom ug hayop, sama sa utanon, prutas, isda, ug karne nga gikinahanglan sa lawas aron mokusog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "air-pressure-egg-bottle-g6", "domain": "MATTER", "topic": "air pressure pushing egg into bottle", "grades": [5, 6, 7], "terms": ["presyon ng hangin", "air pressure", "egg in bottle", "itlog sa bote", "lumamig na hangin", "cooling air", "vacuum", "naipit na itlog", "presyon", "pressure", "puwersa ng hangin", "tinulak"], "fact": {"tl": "Kapag pinainit ang hangin sa loob ng isang bote at saka pinalamig, lumiliit ito at bumababa ang presyon sa loob, kaya itinutulak ng mas malakas na hangin sa labas ang itlog papasok sa bote.", "en": "When the air inside a bottle is heated and then cooled, it shrinks and the pressure inside drops, so the stronger outside air pushes the egg into the bottle.", "bis": "Kung ang hangin sa sulod sa botelya init-on ug dayon pabugnawon, momugot kini ug mokunhod ang presyon sa sulod, mao nga ang mas kusog nga hangin sa gawas motulod sa itlog ngadto sa sulod sa botelya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "axe-splitting-firewood-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "axe as a wedge simple machine", "grades": [5, 6, 7], "terms": ["palakol", "axe", "atsa", "kahoy na panggatong", "firewood", "wedge", "simpleng makina", "simple machine", "puwersa", "force", "pagputol", "bira"], "fact": {"tl": "Ang palakol ay isang uri ng simpleng makinang tinatawag na wedge, na inilalapat nito ang malakas na hampas sa makitid na talim para hatiin ang kahoy.", "en": "An axe is a kind of simple machine called a wedge, which concentrates a strong blow onto its thin blade to split wood.", "bis": "Ang atsa usa ka matang sa yano nga makina nga gitawag og wedge, nga gipunting niini ang kusog nga bunal ngadto sa nipis nga sulab aron buaklon ang kahoy."}, "source": "NRC PS2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "balance-scale-comparing-masses-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "balance scale compares masses", "grades": [4, 5, 6], "terms": ["balanse", "balance scale", "timbangang dalawang dulo", "panimbang", "comparing mass", "paghahambing ng bigat", "pantay", "equal", "gibug-aton", "magtimbang", "mas mabigat", "mas bug-at"], "fact": {"tl": "Ang balance scale ay naghahambing ng bigat ng dalawang bagay; ang mas mabigat na panig ay bumababa, at kapag pantay ang bigat, nagiging patag ang dalawang dulo.", "en": "A balance scale compares the masses of two objects; the heavier side goes down, and when the masses are equal the two ends become level.", "bis": "Ang balance scale nagtandi sa gibug-aton sa duha ka butang; ang mas bug-at nga kilid mokanaog, ug kung managsama ang gibug-aton, mahimong patag ang duha ka tumoy."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ball-rolling-friction-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "rolling ball and friction", "grades": [3, 4, 5], "terms": ["bola", "ball", "gumulong", "rolling", "puwersa", "force", "friction", "kuskos", "tumigil", "natigil", "itulak", "galaw", "ligid"], "fact": {"tl": "Kapag tinulak ang isang bola, gumugulong ito at unti-unting bumabagal hanggang tumigil dahil sa friction o kuskos sa lupa.", "en": "When a ball is pushed, it rolls and slowly slows down until it stops because of friction with the ground.", "bis": "Kung tuklon ang usa ka bola, moligid kini ug hinay-hinay nga mohinay hangtod nga mohunong tungod sa friction o kuskos sa yuta."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "balloon-rocket-string-zip-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "balloon rocket action-reaction", "grades": [5, 6, 7], "terms": ["balloon rocket", "lobo", "balloon", "rocket", "tali", "string", "lumabas na hangin", "escaping air", "aksyon-reaksyon", "action reaction", "tinulak", "Newton", "gumalaw"], "fact": {"tl": "Sa balloon rocket, ang hanging lumalabas sa likod ng lobo ay nagtutulak dito pasulong sa kahabaan ng tali, na nagpapakita na ang bawat aksyon ay may katumbas na reaksiyon.", "en": "In a balloon rocket, the air rushing out the back of the balloon pushes it forward along the string, showing that every action has an equal reaction.", "bis": "Sa balloon rocket, ang hangin nga mogawas sa likod sa lobo motulod niini pasulong subay sa pisi, nga nagpakita nga ang matag aksyon adunay katumbas nga reaksyon."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bamboo-water-pipe-irrigation-g5", "domain": "EARTH_SPACE", "topic": "bamboo water pipe irrigation", "grades": [4, 5, 6], "terms": ["kawayan", "bamboo", "tubo ng tubig", "water pipe", "patubig", "irrigation", "kanal", "dumadaloy", "gravity", "grabidad", "pababang dulo", "agos ng tubig"], "fact": {"tl": "Ginagamit ang hungkag na kawayan bilang tubo na nagdadala ng tubig mula sa mataas na bukal pababa sa mga taniman, dahil natural na dumadaloy ang tubig pababa dahil sa grabidad.", "en": "Hollow bamboo is used as a pipe to carry water from a higher spring down to fields, because water naturally flows downhill due to gravity.", "bis": "Ang gawang nga kawayan gigamit isip tubo nga nagdala og tubig gikan sa habog nga tuburan paubos sa mga uma, tungod kay ang tubig natural nga modagayday paubos tungod sa grabidad."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "basketball-shot-projectile-arc-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "projectile motion of a basketball", "grades": [6, 7, 8], "terms": ["basketball", "projectile", "arko", "arc", "curve", "bumagsak", "grabidad", "gravity", "shot", "tira", "talbog", "trajectory", "naglilipad na bola", "kurbada"], "fact": {"tl": "Kapag itinira ang basketball, sumusunod ito sa kurbadang landas na tinatawag na arc dahil hinihila ng grabidad pababa ang bola habang ito ay paharap na gumagalaw.", "en": "When a basketball is shot, it follows a curved path called an arc because gravity pulls the ball downward while it moves forward.", "bis": "Kung itira ang basketball, mosunod kini sa liko nga agianan nga gitawag og arc tungod kay gibira sa grabidad paubos ang bola samtang kini molihok pasulong."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "battery-stored-chemical-energy-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "battery stores chemical energy", "grades": [5, 6, 7], "terms": ["baterya", "battery", "enerhiya", "energy", "kuryente", "electricity", "kemikal na enerhiya", "chemical energy", "stored energy", "naka-imbak", "dumadaloy", "elektrisidad", "kasangkapan"], "fact": {"tl": "Ang baterya ay nag-iimbak ng enerhiyang kemikal at binabago ito sa enerhiyang elektrikal kapag ikinabit, kaya nakakapagpaandar ito ng mga gamit gaya ng flashlight.", "en": "A battery stores chemical energy and changes it into electrical energy when connected, so it can power devices like a flashlight.", "bis": "Ang baterya nagtipig og kemikal nga enerhiya ug gibalhin kini ngadto sa elektrikal nga enerhiya kung makonektar, mao nga makapadagan kini og mga gamit sama sa flashlight."}, "source": "NRC PS3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "biogas-digester-farm-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "biogas from animal waste", "grades": [6, 7, 8], "terms": ["biogas", "digester", "dumi ng hayop", "animal waste", "methane", "metano", "bakterya", "bacteria", "enerhiyang gawa sa basura", "gasul", "fuel", "renewable", "biogas digester"], "fact": {"tl": "Sa biogas digester, binubulok ng mga bakterya ang dumi ng hayop at basura nang walang hangin, at lumilikha ito ng methane na gas na pwedeng gamiting panggatong sa pagluluto.", "en": "In a biogas digester, bacteria break down animal waste and scraps without air, producing methane gas that can be used as cooking fuel.", "bis": "Sa biogas digester, gibungkag sa bakterya ang hugaw sa hayop ug basura nga walay hangin, ug naghimo kini og methane nga gas nga magamit isip sugnod sa pagluto."}, "source": "NRC PS3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "build-simple-circuit-hands-on-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "simple electric circuit", "grades": [4, 5, 6], "terms": ["simpleng sirkito", "kuryente", "bateriya", "bombilya", "kawad", "lumiwanag", "umiilaw", "yutoong sirkito", "koryente", "baterya", "bombilya", "alambre", "simple circuit", "battery", "bulb", "wire", "electricity", "complete loop", "light up"], "fact": {"tl": "Para mailawan ang isang bombilya, kailangang bumuo ng kompletong sirkito kung saan dumadaloy ang kuryente mula sa bateriya, sa kawad, papunta sa bombilya, at pabalik.", "en": "To light a bulb you must build a complete circuit, an unbroken loop where electricity flows from the battery through the wires to the bulb and back.", "bis": "Aron mosiga ang bombilya, kinahanglan maghimo og kompleto nga sirkito diin ang koryente moagi gikan sa baterya, sa alambre, padulong sa bombilya, ug mobalik."}, "source": "NRC PS3.A; DepEd G5 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "clay-pot-cooling-water-palayok-g6", "domain": "MATTER", "topic": "evaporative cooling clay pot", "grades": [5, 6, 7], "terms": ["palayok", "kolon", "luwad", "tubig", "lumalamig", "singaw", "evaporation", "pagsingaw", "buslot-buslot", "kolon nga yutang-kulonon", "lapok", "tubig", "mabugnaw", "alisngaw", "clay pot", "earthen jar", "evaporative cooling", "water cools", "porous"], "fact": {"tl": "Ang tubig sa loob ng palayok na luwad ay nananatiling malamig dahil kaunting tubig ang dumadaloy sa butas-butas na pader at sumisingaw, at ang pagsingaw ay nagdadala ng init palayo.", "en": "Water inside a clay pot stays cool because a little water seeps through the porous walls and evaporates, and evaporation carries heat away.", "bis": "Ang tubig sulod sa kolon nga yutang-kulonon magpabiling bugnaw kay gamay nga tubig ang moagi sa buslot-buslot nga bongbong ug moalisngaw, ug ang pag-alisngaw magdala sa init palayo."}, "source": "NRC PS3.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "electric-jeepney-charging-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "electric vehicle battery", "grades": [5, 6, 7], "terms": ["e-jeepney", "elektrikong dyip", "nagsasingil", "baterya", "kuryente", "tipid sa gasolina", "walang usok", "e-jeepney", "elektrikong dyip", "nag-charge", "baterya", "koryente", "walay aso", "electric jeepney", "charging", "battery", "stored energy", "no smoke"], "fact": {"tl": "Ang elektrikong dyip ay tumatakbo gamit ang kuryenteng nakaimbak sa malaking baterya na sinisingil sa saksakan, kaya hindi ito naglalabas ng usok mula sa gasolina.", "en": "An electric jeepney runs on electricity stored in a large battery that is charged from an outlet, so it releases no smoke from burning fuel.", "bis": "Ang elektrikong dyip modagan pinaagi sa koryente nga gitipigan sa dako nga baterya nga gi-charge sa saksakan, mao nga wala kini mohaway og aso gikan sa gasolina."}, "source": "NRC PS3.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "firewood-cooking-dapog-scene-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "burning wood releases heat energy", "grades": [3, 4, 5], "terms": ["dapog", "kalan", "kahoy", "panggatong", "apoy", "init", "luto", "nagniningas", "abloy", "kahoy", "sugnod", "kalayo", "init", "kan-on", "firewood", "cookstove", "fire", "heat energy", "burning", "cooking"], "fact": {"tl": "Kapag nagsusunog ng panggatong sa dapog, ang kahoy ay nagiging apoy na naglalabas ng init na ginagamit sa pagluluto ng pagkain.", "en": "When firewood burns in a cookstove, the wood turns into fire that releases heat used to cook food.", "bis": "Kon mosunog og sugnod sa dapog, ang kahoy mahimong kalayo nga mohaway og init nga gamiton sa pagluto sa pagkaon."}, "source": "NRC PS3.B; DepEd G4 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "flagpole-pulley-raising-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "pulley simple machine", "grades": [4, 5, 6], "terms": ["kalo", "poste ng bandila", "polea", "lubid", "hinihila", "pataas", "simpleng makina", "kalo", "poste sa bandila", "pulley", "pisi", "gibira", "pataas", "flagpole", "pulley", "rope", "simple machine", "raise flag", "change direction"], "fact": {"tl": "Ang kalo o polea sa itaas ng poste ng bandila ay isang simpleng makina na nagpapadali sa pag-akyat ng bandila—hinihila mo pababa ang lubid at umaakyat ang bandila pataas.", "en": "The pulley at the top of a flagpole is a simple machine that makes raising the flag easier—you pull the rope down and the flag goes up.", "bis": "Ang pulley sa tumoy sa poste sa bandila usa ka simpleng makina nga mopasayon sa pagpataas sa bandila—bira-on nimo ang pisi paubos ug ang bandila mosaka."}, "source": "NRC PS2.A; DepEd G5 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "jeepney-brake-pedal-lever-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "lever and friction braking", "grades": [5, 6, 7], "terms": ["preno", "pedal", "dyip", "pang-apak", "humihinto", "pwersa", "kuskos", "preno", "pedal", "dyip", "tunob", "mohunong", "kuskos", "brake pedal", "lever", "jeepney", "friction", "stop", "slow down"], "fact": {"tl": "Kapag inaapakan ng tsuper ang pedal ng preno, ang pedal ay parang lever na nagpapalakas ng pwersa, at ang kuskos ng preno sa gulong ang nagpapahinto sa dyip.", "en": "When the driver presses the brake pedal, the pedal acts like a lever that increases force, and friction between the brakes and wheels stops the jeepney.", "bis": "Kon tunob-tunoban sa drayber ang pedal sa preno, ang pedal mahisama sa lever nga modugang sa kusog, ug ang kuskos sa preno sa ligid maoy mopahunong sa dyip."}, "source": "NRC PS2.A, PS2.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kitchen-cooking-stove-scene-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "heat transfer in cooking", "grades": [3, 4, 5], "terms": ["kalan", "lutuan", "init", "kawali", "pagkain", "naglululto", "nag-init", "kalan", "luto-anan", "init", "kawa", "pagkaon", "nag-init", "stove", "cooking", "heat", "pan", "heat transfer", "cook food"], "fact": {"tl": "Sa kalan, ang init mula sa apoy o kuryente ay lumilipat papunta sa kawali at pagkatapos sa pagkain, na siyang nagpapaluto rito.", "en": "On a stove, heat from the flame or electricity moves into the pan and then into the food, which is what cooks it.", "bis": "Sa kalan, ang init gikan sa kalayo o koryente mobalhin ngadto sa kawa ug dayon sa pagkaon, nga maoy moluto niini."}, "source": "NRC PS3.B; DepEd G4 Q3", "generator": "claude-workflow", "reviewed": false},
  {"id": "public-market-weighing-produce-g4", "domain": "MATTER", "topic": "measuring mass with a scale", "grades": [3, 4, 5], "terms": ["timbangan", "palengke", "gulay", "bigat", "kilo", "tinitimbang", "masa", "timbangan", "merkado", "utanon", "kabug-aton", "kilo", "gitimbang", "weighing scale", "market", "produce", "mass", "kilogram", "measure weight"], "fact": {"tl": "Sa palengke, ginagamit ang timbangan para alamin ang bigat ng gulay at prutas sa kilo, na sumusukat kung gaano karaming masa ang nasa bawat batch.", "en": "At the market, a scale is used to find the weight of fruits and vegetables in kilograms, measuring how much mass is in each batch.", "bis": "Sa merkado, gigamit ang timbangan aron mahibaw-an ang kabug-aton sa utanon ug prutas sa kilo, nga magsukod kon pila ka masa ang anaa sa matag bahin."}, "source": "NRC PS1.A; DepEd G4 Q1", "generator": "claude-workflow", "reviewed": false},
  {"id": "sari-sari-store-beam-scale-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "beam balance and equilibrium", "grades": [4, 5, 6], "terms": ["timbangang panaklang", "sari-sari store", "balanse", "pantay", "pabigat", "lever", "patong", "timbangan nga sanga", "tindahan", "balanse", "patas", "pabug-at", "beam scale", "balance", "equal", "equilibrium", "weight", "level beam"], "fact": {"tl": "Ang timbangang panaklang ay isang lever na nagiging pantay kapag magkapareho ang bigat sa magkabilang dulo, kaya nakikita mo ang tamang timbang kapag balanse ito.", "en": "A beam scale is a lever that becomes level when the weights on both ends are equal, so you read the correct weight when it balances.", "bis": "Ang timbangan nga sanga usa ka lever nga mahimong patas kon parehas ang gibug-aton sa duha ka tumoy, mao nga makit-an nimo ang husto nga timbang kon balanse na kini."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "spring-rubberband-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "elastic force in springs and rubber bands", "grades": [4, 5, 6], "terms": ["spring", "lukso", "rubberband", "goma", "nag-uunat", "bumabalik", "elastic", "pwersa", "tipa", "rubber", "nag-inat", "mobalik", "elastic force", "spring", "rubber band", "stretch", "snap back", "stored energy"], "fact": {"tl": "Ang spring at rubberband ay elastiko—kapag inuunat o pinipiga mo ito, nag-iipon ito ng enerhiya at bumabalik sa dating hugis pagbitaw mo.", "en": "A spring and a rubber band are elastic—when you stretch or squeeze them they store energy and snap back to their original shape when you let go.", "bis": "Ang spring ug rubberband elastiko—kon imong inaton o ipiton, magtigom kini og enerhiya ug mobalik sa orihinal nga porma kon imong buhian."}, "source": "NRC PS2.A, PS3.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tricycle-sidecar-scene-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "wheels reduce friction", "grades": [4, 5, 6], "terms": ["traysikel", "sidecar", "gulong", "umiikot", "gumagalaw", "kuskos", "motor", "traysikol", "sidecar", "ligid", "nagtuyok", "naglihok", "tricycle", "sidecar", "wheels", "rolling", "friction", "motorcycle"], "fact": {"tl": "Ang traysikel ay isang motorsiklo na may nakakabit na sidecar, at ang umiikot nitong mga gulong ay nakakabawas ng kuskos kaya madali itong gumulong sa daan.", "en": "A tricycle is a motorcycle with an attached sidecar, and its rolling wheels reduce friction so it moves easily along the road.", "bis": "Ang traysikol usa ka motorsiklo nga adunay nakakabit nga sidecar, ug ang nagtuyok niini nga mga ligid mokunhod sa kuskos mao nga sayon kining moligid sa dalan."}, "source": "NRC PS2.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "windmill-water-pump-farm-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "wind energy powers a pump", "grades": [5, 6, 7], "terms": ["molino ng hangin", "windmill", "hangin", "bukid", "bomba ng tubig", "umiikot", "enerhiya", "molino sa hangin", "hangin", "umahan", "bomba sa tubig", "nagtuyok", "windmill", "wind energy", "farm", "water pump", "spinning blades", "renewable"], "fact": {"tl": "Sa molino ng hangin, ang hangin ay nagpapaikot ng mga pakpak na nagbubomba ng tubig pataas mula sa balon—isang halimbawa ng paggamit ng enerhiya ng hangin.", "en": "In a windmill, wind spins the blades that pump water up from a well—an example of using the energy of moving air.", "bis": "Sa molino sa hangin, ang hangin magpatuyok sa mga pako nga magbomba sa tubig pataas gikan sa atabay—usa ka panig-ingnan sa paggamit sa enerhiya sa hangin."}, "source": "NRC PS3.A, ESS3.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "plant-transport-xylem-phloem-g7", "domain": "LIVING_THINGS", "topic": "xylem and phloem transport", "grades": [6, 7, 8], "terms": ["xylem", "phloem", "halaman", "tubig", "pagkain", "tangkay", "dumadaloy", "ugat", "dahon", "xylem", "phloem", "tanom", "tubig", "pagkaon", "punoan", "nag-agos", "gamot", "dahon", "water transport", "sugar transport", "stem", "vascular tissue"], "fact": {"tl": "Sa loob ng halaman, ang xylem ay nagdadala ng tubig pataas mula sa ugat papuntang dahon, habang ang phloem naman ay nagdadala ng pagkaing gawa sa dahon papunta sa ibang bahagi.", "en": "Inside a plant, xylem carries water up from the roots to the leaves, while phloem carries the food made in the leaves to the rest of the plant.", "bis": "Sulod sa tanom, ang xylem magdala sa tubig pataas gikan sa gamot ngadto sa dahon, samtang ang phloem magdala sa pagkaon nga gihimo sa dahon ngadto sa ubang bahin sa tanom."}, "source": "NRC LS1.A; DepEd G7", "generator": "claude-workflow", "reviewed": false},
  {"id": "pufferfish-deflated-g5", "domain": "LIVING_THINGS", "topic": "pufferfish inflation defense", "grades": [4, 5, 6], "terms": ["butete", "pufferfish", "namamaga", "tubig", "depensa", "tinik", "lason", "butete", "pufferfish", "namaga", "tubig", "depensa", "tunok", "hilo", "pufferfish", "inflate", "swallow water", "defense", "spines", "predator"], "fact": {"tl": "Ang butete ay isang isda na lumulunok ng tubig para mamaga na parang bola kapag nanganganib, na ginagawa itong mahirap kainin ng mga maninila.", "en": "A pufferfish is a fish that gulps water to puff up like a ball when threatened, making it hard for predators to swallow.", "bis": "Ang butete usa ka isda nga motulon og tubig aron mohubag nga morag bola kon mabahad, nga maghimo niini nga lisod kaonon sa mga manunukob."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "puppy-tuta-g3", "domain": "LIVING_THINGS", "topic": "puppy is a young dog (mammal)", "grades": [3, 4], "terms": ["tuta", "aso", "anak", "mammal", "gatas", "bata", "lumalaki", "itoy", "iro", "anak", "mammal", "gatas", "bata", "modako", "puppy", "young dog", "mammal", "milk", "grows up"], "fact": {"tl": "Ang tuta ay batang aso na isang mammal—nagsisimula itong sumipsip ng gatas sa ina bago lumaki at maging ganap na aso.", "en": "A puppy is a young dog, a mammal that starts by drinking its mother's milk before it grows into a full-sized dog.", "bis": "Ang itoy usa ka batan-ong iro nga mammal—magsugod kini sa pagsuso og gatas sa inahan una pa kini modako ug mahimong hingkod nga iro."}, "source": "NRC LS1.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rabbit-kuneho-g3", "domain": "LIVING_THINGS", "topic": "rabbit herbivore mammal", "grades": [3, 4, 5], "terms": ["kuneho", "rabbit", "halaman", "damo", "ngangatngat", "mammal", "tainga", "herbivore", "kuneho", "rabbit", "tanom", "sagbot", "mammal", "dalunggan", "rabbit", "herbivore", "long ears", "grass", "plant-eater", "mammal"], "fact": {"tl": "Ang kuneho ay isang mammal na herbivore—kumakain lamang ito ng mga halaman tulad ng damo at gulay, at gumagamit ng matatalas na ngipin sa pangangatngat.", "en": "A rabbit is a herbivore mammal—it eats only plants such as grass and vegetables, using its sharp front teeth to gnaw.", "bis": "Ang kuneho usa ka mammal nga herbivore—mokaon lamang kini og mga tanom sama sa sagbot ug utanon, ug mogamit sa hait nga ngipon sa pag-usap."}, "source": "NRC LS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ray-eagle-spotted-g6", "domain": "LIVING_THINGS", "topic": "spotted eagle ray cartilaginous fish", "grades": [5, 6, 7], "terms": ["pagi", "eagle ray", "batikan", "lumalangoy", "dagat", "pakpak", "buntot", "kartilago", "pagi", "eagle ray", "puntik-puntik", "molangoy", "dagat", "pako", "ikog", "eagle ray", "spotted ray", "cartilage", "ocean", "wing-like fins", "glide"], "fact": {"tl": "Ang spotted eagle ray ay isang malaking pagi na may puti-puting batik na lumalangoy sa dagat sa pamamagitan ng pagpapagaspas ng malalapad nitong pakpak na parang ibon.", "en": "The spotted eagle ray is a large ray with white spots that swims through the sea by flapping its broad, wing-like fins like a bird.", "bis": "Ang spotted eagle ray usa ka dako nga pagi nga adunay puti nga puntik-puntik nga molangoy sa dagat pinaagi sa pagkapay sa lapad niini nga mga pako nga morag langgam."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "remora-suckerfish-g6", "domain": "LIVING_THINGS", "topic": "remora hitchhiking suckerfish", "grades": [5, 6, 7], "terms": ["remora", "suckerfish", "kumakapit", "pating", "sumisipsip", "dumikit", "biyahe", "remora", "suckerfish", "mokupot", "iho", "modikit", "remora", "suckerfish", "shark", "suction disc", "hitchhike", "attach"], "fact": {"tl": "Ang remora ay isang isda na may parang suso sa ulo na ginagamit nito para kumapit sa pating o malalaking isda at makasama sa kanilang paglangoy.", "en": "A remora is a fish with a sucker-like disc on its head that it uses to cling to sharks or large fish and ride along as they swim.", "bis": "Ang remora usa ka isda nga adunay morag suyup sa ulo nga gamiton niini sa pagkupot sa iho o dagkong isda ug mosakay samtang sila molangoy."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rooster-g3", "domain": "LIVING_THINGS", "topic": "rooster adult male chicken", "grades": [3, 4], "terms": ["tandang", "manok", "lalaki", "tilaok", "palong", "ibon", "umaga", "sunoy", "manok", "lalaki", "tuktugaok", "palong", "langgam", "rooster", "male chicken", "crow", "comb", "bird", "morning"], "fact": {"tl": "Ang tandang ay isang malaking lalaking manok na may pulang palong sa ulo, at kilala ito sa malakas na pagtilaok lalo na tuwing umaga.", "en": "A rooster is an adult male chicken with a red comb on its head, well known for its loud crowing, especially in the morning.", "bis": "Ang sunoy usa ka dako nga laki nga manok nga adunay pula nga palong sa ulo, ug ilado kini sa kusog nga pagtuktugaok ilabi na sa buntag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sabong-rooster-fighting-cock-g4", "domain": "LIVING_THINGS", "topic": "rooster traits used in fighting cocks", "grades": [3, 4, 5], "terms": ["sabong", "manok panabong", "tandang", "tahid", "palong", "balahibo", "tilaok", "sabong", "manok panabong", "sunoy", "balhibo", "palong", "fighting cock", "rooster", "comb", "feathers", "male chicken", "spur"], "fact": {"tl": "Ang manok na ginagamit sa sabong ay isang malakas na tandang na may makulay na balahibo at matulis na tahid sa paa, mga likas na katangian ng lalaking manok.", "en": "A fighting cock is a strong rooster with colorful feathers and sharp natural leg spurs, traits of a male chicken.", "bis": "Ang manok nga gigamit sa sabong usa ka kusgan nga sunoy nga adunay mabulokong balhibo ug hait nga tudlo sa tiil, mga kinaiyanhong timaan sa laki nga manok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sailfin-lizard-ibid-g6", "domain": "LIVING_THINGS", "topic": "Philippine sailfin lizard endemic reptile", "grades": [5, 6, 7], "terms": ["ibid", "layagang butiki", "sailfin lizard", "reptilya", "ilog", "lumalangoy", "Pilipinas", "endemic", "ibid", "halo sa tubig", "sailfin lizard", "reptilya", "suba", "molangoy", "Pilipinas", "sailfin lizard", "endemic", "reptile", "river", "swims", "crest"], "fact": {"tl": "Ang ibid o Philippine sailfin lizard ay isang reptilyang matatagpuan lamang sa Pilipinas, na nakatira malapit sa mga ilog at marunong lumangoy gamit ang malapad nitong buntot.", "en": "The sailfin lizard, or ibid, is a reptile found only in the Philippines that lives near rivers and can swim using its broad, flattened tail.", "bis": "Ang ibid o Philippine sailfin lizard usa ka reptilya nga makit-an lamang sa Pilipinas, nga nagpuyo duol sa mga suba ug makamao molangoy pinaagi sa lapad niini nga ikog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sampaguita-g4", "domain": "LIVING_THINGS", "topic": "sampaguita national flower", "grades": [3, 4, 5], "terms": ["sampaguita", "bulaklak", "puti", "mabango", "pambansang bulaklak", "Pilipinas", "halaman", "sampaguita", "bulak", "puti", "humot", "nasodnong bulak", "Pilipinas", "sampaguita", "white flower", "fragrant", "national flower", "Philippines"], "fact": {"tl": "Ang sampaguita ay isang maliit na puti at mabangong bulaklak na siyang pambansang bulaklak ng Pilipinas, at madalas itong inihahabi sa kwintas.", "en": "The sampaguita is a small, white, fragrant flower that is the national flower of the Philippines, often strung into garlands.", "bis": "Ang sampaguita usa ka gamay, puti, ug humot nga bulak nga maoy nasodnong bulak sa Pilipinas, ug kasagarang gihimong kwintas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sardine-tamban-g5", "domain": "LIVING_THINGS", "topic": "sardine schooling fish", "grades": [4, 5, 6], "terms": ["tamban", "sardinas", "isda", "dagat", "kawan", "lumalangoy", "maliit", "tamban", "sardinas", "isda", "dagat", "panon", "molangoy", "gamay", "sardine", "school of fish", "small fish", "ocean", "swims together"], "fact": {"tl": "Ang tamban o sardinas ay maliliit na isda sa dagat na lumalangoy nang sama-sama sa malalaking kawan, isang karaniwang isdang kinakain sa Pilipinas.", "en": "Sardines, or tamban, are small ocean fish that swim together in large schools, a common food fish in the Philippines.", "bis": "Ang tamban o sardinas gagmay nga isda sa dagat nga molangoy nga magkadungan sa dagkong panon, usa ka kasagarang isda nga ginakaon sa Pilipinas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "school-feeding-program-meal-g4", "domain": "LIVING_THINGS", "topic": "balanced meal and nutrition", "grades": [3, 4, 5], "terms": ["pagkain", "feeding program", "masustansya", "nutrisyon", "kalusugan", "lumalaki", "enerhiya", "pagkaon", "feeding program", "masustansya", "nutrisyon", "panglawas", "modako", "kusog", "balanced meal", "nutrition", "healthy food", "energy", "grow"], "fact": {"tl": "Ang masustansyang pagkain sa feeding program sa paaralan ay nagbibigay ng enerhiya at sustansyang kailangan ng katawan para lumaki at manatiling malusog.", "en": "The nutritious meals in a school feeding program give the body the energy and nutrients it needs to grow and stay healthy.", "bis": "Ang masustansya nga pagkaon sa feeding program sa eskwelahan maghatag og enerhiya ug sustansya nga gikinahanglan sa lawas aron modako ug magpabiling himsog."}, "source": "NRC LS1.C; DepEd G4", "generator": "claude-workflow", "reviewed": false},
  {"id": "scops-owl-kulago-maliit-g6", "domain": "LIVING_THINGS", "topic": "scops owl nocturnal bird", "grades": [5, 6, 7], "terms": ["kuwago", "scops owl", "maliit", "ibon", "gabi", "nanghuhuli", "mata", "nocturnal", "kuwago", "scops owl", "gamay", "langgam", "gabii", "mangita", "owl", "scops owl", "nocturnal", "night", "small bird", "large eyes"], "fact": {"tl": "Ang scops owl ay isang maliit na kuwago na gising sa gabi, gumagamit ng malalaki nitong mata at matalas na pandinig para manghuli ng insekto at maliliit na hayop.", "en": "The scops owl is a small owl that is active at night, using its large eyes and sharp hearing to hunt insects and small animals.", "bis": "Ang scops owl usa ka gamay nga kuwago nga magmata sa gabii, nga mogamit sa dagkong mata ug hait nga pandungog aron mangita og insekto ug gagmayng hayop."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sea-cucumber-balatan-g6", "domain": "LIVING_THINGS", "topic": "sea cucumber seafloor cleaner", "grades": [5, 6, 7], "terms": ["balat", "sea cucumber", "balatan", "dagat", "ilalim", "naglilinis", "buhangin", "echinoderm", "balat", "sea cucumber", "dagat", "ilalom", "maglimpyo", "balas", "sea cucumber", "seafloor", "cleaner", "sand", "echinoderm", "recycles"], "fact": {"tl": "Ang balat o sea cucumber ay isang malambot na hayop sa ilalim ng dagat na kumakain ng buhangin at naglilinis nito habang nagbabalik ng sustansya sa tubig.", "en": "A sea cucumber is a soft animal on the seafloor that eats sand and cleans it, returning nutrients to the water as it feeds.", "bis": "Ang balat o sea cucumber usa ka humok nga hayop sa ilalom sa dagat nga mokaon og balas ug maglimpyo niini samtang magbalik og sustansya sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sea-cucumber-curl-g6", "domain": "LIVING_THINGS", "topic": "sea cucumber defense behavior", "grades": [5, 6, 7], "terms": ["balat", "sea cucumber", "namamaluktot", "depensa", "tinik", "lumalabas", "tigas", "balat", "sea cucumber", "molikos", "depensa", "molisok", "sea cucumber", "curl", "defense", "harden", "release threads", "predator"], "fact": {"tl": "Kapag nanganganib ang balat o sea cucumber, namamaluktot ito o pinapatigas ang katawan, at may ilang uri na naglalabas ng malagkit na sinulid para depensahan ang sarili.", "en": "When threatened, a sea cucumber curls up or stiffens its body, and some kinds release sticky threads to defend themselves.", "bis": "Kon mabahad ang balat o sea cucumber, molikos kini o motig-a ang lawas, ug ang uban motangtang og pilit nga hilo aron manalipod sa kaugalingon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sea-krait-banded-g6", "domain": "LIVING_THINGS", "topic": "banded sea krait venomous sea snake", "grades": [5, 6, 7], "terms": ["ahas dagat", "sea krait", "guhit-guhit", "kamandag", "lumalangoy", "huminga", "hangin", "walo-walo dagat", "halas sa dagat", "sea krait", "bagis-bagis", "hilo", "molangoy", "sea krait", "sea snake", "banded", "venomous", "swims", "breathes air"], "fact": {"tl": "Ang banded sea krait ay isang ahas-dagat na may itim na guhit-guhit, may kamandag, ngunit umaakyat pa rin sa lupa para huminga ng hangin at mangitlog.", "en": "The banded sea krait is a sea snake with black bands that is venomous, yet still comes onto land to breathe air and lay its eggs.", "bis": "Ang banded sea krait usa ka halas sa dagat nga adunay itom nga bagis-bagis, hiloon, apan mosaka gihapon sa yuta aron moginhawa og hangin ug mangitlog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sea-slug-nudibranch-g6", "domain": "LIVING_THINGS", "topic": "nudibranch colorful sea slug", "grades": [5, 6, 7], "terms": ["sea slug", "nudibranch", "makulay", "dagat", "malambot", "babala", "kulay", "sea slug", "nudibranch", "mabulokon", "dagat", "humok", "pasidaan", "nudibranch", "sea slug", "colorful", "warning colors", "soft-bodied", "reef"], "fact": {"tl": "Ang nudibranch o sea slug ay isang malambot at makulay na hayop sa dagat, at ang matitingkad nitong kulay ay nagsisilbing babala sa mga maninila na maaaring lason o di-masarap ito.", "en": "A nudibranch, or sea slug, is a soft, brightly colored sea animal whose vivid colors warn predators that it may be poisonous or bad-tasting.", "bis": "Ang nudibranch o sea slug usa ka humok ug mabulokon nga hayop sa dagat, ug ang hayag niini nga kolor maoy pasidaan sa mga manunukob nga mahimo kining hiloon o dili lami."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sea-snake-walo-walo-g6", "domain": "LIVING_THINGS", "topic": "sea snake", "grades": [5, 6, 7], "terms": ["sea snake", "ahas dagat", "ahas sa dagat", "halas sa dagat", "walo-walo", "marine reptile", "venom", "kamandag", "hilo", "nilalanguyan", "buntot", "ikog"], "fact": {"tl": "Ang ahas-dagat o walo-walo ay isang reptilyang naninirahan sa dagat, may pipi (flattened) na buntot na parang sagwan para makalangoy, at humihinga ng hangin kaya umaahon ito sa ibabaw paminsan-minsan.", "en": "The sea snake (locally walo-walo) is a reptile that lives in the sea, has a flattened paddle-like tail for swimming, and breathes air so it must surface from time to time.", "bis": "Ang halas sa dagat (walo-walo) usa ka reptilya nga nagpuyo sa dagat, may lapad ug pinili nga ikog nga morag bugsay aron makalangoy, ug nagginhawa og hangin maong mosaka kini sa ibabaw matag karon ug unya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sea-star-five-arm-g4", "domain": "LIVING_THINGS", "topic": "sea star starfish", "grades": [3, 4, 5], "terms": ["sea star", "starfish", "bituin sa dagat", "bituing-dagat", "bituon sa dagat", "tinik-balat", "limang braso", "lima ka bukton", "echinoderm", "muling tumubo", "regenerate"], "fact": {"tl": "Ang bituin-dagat (starfish) ay hayop sa dagat na karaniwang may limang braso na nakaayos paikot, at kaya nitong palitan o palaguin muli ang braso kung mawalan nito.", "en": "The sea star (starfish) is a sea animal that usually has five arms arranged around its body, and it can regrow an arm if one is lost.", "bis": "Ang bituon sa dagat (starfish) usa ka hayop sa dagat nga kasagaran adunay lima ka bukton nga naglibot sa lawas, ug makahimo kini og bag-ong bukton kon mawad-an."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "seahorse-curl-tail-g4", "domain": "LIVING_THINGS", "topic": "seahorse", "grades": [3, 4, 5], "terms": ["seahorse", "kabayong-dagat", "kabayo sa dagat", "kabayong dagat", "nakapulupot na buntot", "isda", "fish", "lalaki nagbubuntis", "male carries eggs", "pouch", "supot", "puyo"], "fact": {"tl": "Ang kabayong-dagat ay isang maliit na isda na may ulong parang kabayo at buntot na nakapulupot sa damong-dagat para hindi maanod, at ang lalaki ang nagdadala ng mga itlog sa isang supot sa tiyan.", "en": "The seahorse is a small fish with a horse-like head and a curled tail it wraps around seagrass to hold on, and it is the male that carries the eggs in a belly pouch.", "bis": "Ang kabayo sa dagat usa ka gamay nga isda nga may ulo nga morag kabayo ug ikog nga giputos sa balili sa dagat aron dili maanod, ug ang lalaki maoy nagdala sa mga itlog sa usa ka puyo sa tiyan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sheep-tupa-g4", "domain": "LIVING_THINGS", "topic": "sheep", "grades": [3, 4, 5], "terms": ["sheep", "tupa", "karnero", "wool", "lana", "balahibo", "balhibo", "mammal", "damo", "sagbot", "grass eater", "gatas"], "fact": {"tl": "Ang tupa (sheep) ay isang mamalyang kumakain ng damo at ginugupitan ng makapal nitong balahibong tinatawag na lana o wool na ginagawang tela at panyong panlamig.", "en": "The sheep is a mammal that eats grass and is sheared for its thick coat called wool, which is made into cloth and warm clothing.", "bis": "Ang karnero (sheep) usa ka mammal nga nagkaon og sagbot ug giguntingan sa baga niini nga balhibo nga gitawag og wool o lana, nga himoon nga panapton ug bisti panginit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "shrew-tree-shrew-g6", "domain": "LIVING_THINGS", "topic": "tree shrew", "grades": [5, 6, 7], "terms": ["tree shrew", "tree-shrew", "shrew", "munting hayop", "matulis na nguso", "talinis nga nguso", "mammal", "insekto", "insects", "prutas", "fruit", "kahoy"], "fact": {"tl": "Ang tree shrew ay isang maliit na mamalyang nakatira sa mga puno, may matulis na nguso, at kumakain ng mga insekto at prutas; mukha itong daga pero hindi ito tunay na daga.", "en": "The tree shrew is a small mammal that lives in trees, has a pointed snout, and eats insects and fruit; it looks like a rodent but is not a true rat.", "bis": "Ang tree shrew usa ka gamay nga mammal nga nagpuyo sa mga kahoy, may talinis nga nguso, ug nagkaon og mga insekto ug prutas; morag ilaga kini apan dili tinuod nga ilaga."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "snail-shell-spiral-land-g3", "domain": "LIVING_THINGS", "topic": "land snail", "grades": [3, 4, 5], "terms": ["land snail", "kuhol", "suso", "suso sa yuta", "spiral shell", "talukab", "kabhang", "shell", "mabagal", "hinay", "uhog", "mollusk"], "fact": {"tl": "Ang kuhol o suso sa lupa ay isang malambot na hayop na may matigas na bahay na pasikot-sikot (spiral) sa likod, at gumagapang ito nang mabagal habang nag-iiwan ng makintab na uhog.", "en": "The land snail is a soft-bodied animal with a hard spiral shell on its back, and it crawls slowly while leaving a shiny trail of slime.", "bis": "Ang kuhol o suso sa yuta usa ka humok nga hayop nga may gahi nga balay nga liko-liko (spiral) sa likod, ug nagkamang kini og hinay samtang nagbilin og masinaw nga uhog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "soft-shell-turtle-pakawan-g6", "domain": "LIVING_THINGS", "topic": "softshell turtle", "grades": [5, 6, 7], "terms": ["softshell turtle", "soft-shell turtle", "pagong", "pakawan", "pawikan sa tab-ang", "malambot na talukab", "humok nga kabhang", "ilog", "suba", "reptile", "mahabang leeg", "taas nga liog", "tubig-tabang"], "fact": {"tl": "Ang pakawan o soft-shell turtle ay isang pagong sa tubig-tabang na may malambot at parang katad na talukab sa halip na matigas, at may mahabang leeg at nguso na parang snorkel para makahinga sa ilalim ng tubig.", "en": "The softshell turtle (pakawan) is a freshwater turtle with a soft, leathery shell instead of a hard one, and it has a long neck and snorkel-like snout to breathe just under the water.", "bis": "Ang pakawan o softshell turtle usa ka pawikan sa tab-ang nga tubig nga may humok ug morag panit nga kabhang imbes gahi, ug may taas nga liog ug nguso nga morag snorkel aron makaginhawa ilalom sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "spotted-dove-batobato-g4", "domain": "LIVING_THINGS", "topic": "spotted dove", "grades": [3, 4, 5], "terms": ["spotted dove", "batobato", "alibam", "kalapati", "salampati", "dove", "ibon", "langgam", "puntos sa leeg", "spotted neck", "buto", "liso"], "fact": {"tl": "Ang batobato (spotted dove) ay isang ibong parang kalapati na may itim-at-puting batik sa leeg, karaniwang nakikita sa mga bukid at bakuran, at kumakain ng mga buto at butil.", "en": "The spotted dove (batobato) is a dove-like bird with a black-and-white spotted patch on its neck, often seen in fields and yards, and it eats seeds and grains.", "bis": "Ang batobato (spotted dove) usa ka langgam nga morag salampati nga may itom-ug-puti nga puntik sa liog, kasagaran makita sa mga uma ug nataran, ug nagkaon og mga liso ug lugas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "squirrel-tree-tail-g4", "domain": "LIVING_THINGS", "topic": "squirrel", "grades": [3, 4, 5], "terms": ["squirrel", "ardilya", "mabuhok na buntot", "bushy tail", "balhiboon nga ikog", "rodent", "mammal", "punong-kahoy", "kahoy", "mani", "buto", "liso"], "fact": {"tl": "Ang ardilya (squirrel) ay isang maliit na mamalyang mahusay umakyat sa mga puno, may malago at mabuhok na buntot na ginagamit nito sa pagbalanse, at kumakain ng mga buto at mani.", "en": "The squirrel is a small mammal that is good at climbing trees, has a thick bushy tail it uses for balance, and eats seeds and nuts.", "bis": "Ang squirrel (ardilya) usa ka gamay nga mammal nga hanas mosaka sa mga kahoy, may baga ug balhiboon nga ikog nga gamiton niini sa pagbalanse, ug nagkaon og mga liso ug mani."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "stink-bug-shield-g5", "domain": "LIVING_THINGS", "topic": "stink bug", "grades": [4, 5, 6], "terms": ["stink bug", "shield bug", "atangya", "mabahong insekto", "insekto nga baho", "insect", "insekto", "hugis-kalasag", "porma og taming", "mabahong amoy", "baho", "halaman", "peste", "tanom"], "fact": {"tl": "Ang stink bug o shield bug ay isang insektong hugis-kalasag na naglalabas ng mabahong amoy bilang depensa para itaboy ang mga ibig manakmal dito, at kadalasan itong sumisipsip ng katas ng halaman.", "en": "The stink bug (shield bug) is a shield-shaped insect that releases a foul smell as a defense to drive away predators, and it usually sucks juices from plants.", "bis": "Ang stink bug o shield bug usa ka insekto nga porma og taming nga nagpagawas og baho isip depensa aron abugon ang gustong mokaon niini, ug kasagaran nagsuyop kini sa duga sa tanom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "swallow-layanglayang-g5", "domain": "LIVING_THINGS", "topic": "swallow bird", "grades": [4, 5, 6], "terms": ["swallow", "layang-layang", "layanglayang", "sibid-sibid", "ibon", "langgam", "forked tail", "sanga na buntot", "ikog nga tinidor", "lumilipad", "naglupad", "insekto sa hangin"], "fact": {"tl": "Ang layang-layang (swallow) ay isang maliksing ibong may buntot na hugis-tinidor, at humuhuli ito ng mga insekto habang lumilipad sa himpapawid.", "en": "The swallow (layang-layang) is a swift bird with a forked tail, and it catches insects in mid-air while flying.", "bis": "Ang swallow (layang-layang) usa ka abtik nga langgam nga may ikog nga porma og tinidor, ug nagdakop kini og mga insekto samtang naglupad sa kahanginan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "swordfish-malasugi-g6", "domain": "LIVING_THINGS", "topic": "swordfish marlin", "grades": [5, 6, 7], "terms": ["swordfish", "malasugi", "espada-espada", "isda", "fish", "matulis na nguso", "talinis nga nguso", "bill snout sword", "matulin", "paspas", "dagat", "lamandagat"], "fact": {"tl": "Ang malasugi (swordfish) ay isang malaki at matuling isda sa dagat na may mahaba at matulis na nguso na parang espada, na ginagamit nitong tulungan ang sarili sa paghuli ng pagkain.", "en": "The swordfish (malasugi) is a large, fast ocean fish with a long, pointed bill shaped like a sword, which helps it hunt for food.", "bis": "Ang malasugi (swordfish) usa ka dako ug paspas nga isda sa dagat nga may taas ug talinis nga nguso nga morag espada, nga gigamit niini aron makatabang sa pagpangdakop og pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tailorbird-nest-g6", "domain": "LIVING_THINGS", "topic": "tailorbird nest", "grades": [5, 6, 7], "terms": ["tailorbird", "mananahi na ibon", "ibon", "langgam", "nest", "pugad", "salag", "tinatahi na dahon", "pagtahi sa dahon", "nguso na parang karayom", "tuka", "hibla halaman"], "fact": {"tl": "Ang tailorbird ay isang maliit na ibong gumagawa ng pugad sa pamamagitan ng pagbutas at 'pagtatahi' ng mga dahon gamit ang nguso nito at hibla mula sa halaman.", "en": "The tailorbird is a small bird that builds its nest by piercing and 'sewing' leaves together using its beak and plant fibers.", "bis": "Ang tailorbird usa ka gamay nga langgam nga naghimo sa salag pinaagi sa pagtusok ug 'pagtahi' sa mga dahon gamit ang tuka niini ug hilo gikan sa tanom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tarantula-malaking-gagamba-g5", "domain": "LIVING_THINGS", "topic": "tarantula", "grades": [4, 5, 6], "terms": ["tarantula", "malaking gagamba", "dako nga lawalawa", "gagamba", "lawalawa", "spider", "mabuhok na paa", "balhiboon nga tiil", "walong paa", "walo ka tiil", "lungga", "lungag"], "fact": {"tl": "Ang tarantula ay isang malaki at mabuhok na gagambang may walong paa, na karaniwang naninirahan sa lupa o sa mga lungga at humuhuli ng mga insekto.", "en": "The tarantula is a large, hairy spider with eight legs that usually lives on the ground or in burrows and hunts insects.", "bis": "Ang tarantula usa ka dako ug balhiboon nga lawalawa nga may walo ka tiil, nga kasagaran nagpuyo sa yuta o sa mga lungag ug nangdakop og mga insekto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tarsier-g5", "domain": "LIVING_THINGS", "topic": "Philippine tarsier", "grades": [4, 5, 6], "terms": ["tarsier", "Philippine tarsier", "mamag", "maumag", "malmag", "primate", "malalaking mata", "dagko nga mata", "Bohol", "gabi", "nocturnal", "insekto", "lumukso"], "fact": {"tl": "Ang tarsier (mamag) ay isang napakaliit na primate na matatagpuan sa Pilipinas, lalo na sa Bohol, na may napakalaking mata para makakita sa gabi at kumakain ng mga insekto.", "en": "The tarsier is a very small primate found in the Philippines, especially in Bohol, with huge eyes for seeing at night and a diet of insects.", "bis": "Ang tarsier (mamag) usa ka gamay kaayo nga primate nga makita sa Pilipinas, ilabi na sa Bohol, nga may dagko kaayo nga mata aron makakita sa gabii ug nagkaon og mga insekto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "termite-anay-g5", "domain": "LIVING_THINGS", "topic": "termite", "grades": [4, 5, 6], "terms": ["termite", "anay", "anai", "insekto", "insect", "kahoy", "wood", "kolonya", "colony", "punso", "reyna", "nakakasira ng kahoy"], "fact": {"tl": "Ang anay (termite) ay isang insektong namumuhay nang sama-sama sa malaking kolonya at kumakain ng kahoy, kaya nakakasira ito ng mga bahay at gamit na yari sa kahoy.", "en": "The termite (anay) is an insect that lives together in a large colony and eats wood, so it can damage houses and wooden things.", "bis": "Ang anay (termite) usa ka insekto nga nagpuyo nga tingob sa dako nga kolonya ug nagkaon og kahoy, maong makadaot kini sa mga balay ug gamit nga hinimo sa kahoy."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tern-seabird-g6", "domain": "LIVING_THINGS", "topic": "tern seabird", "grades": [5, 6, 7], "terms": ["tern", "seabird", "ibong-dagat", "langgam sa dagat", "ibon", "langgam", "sumisisid sa tubig", "mosalom", "dives for fish", "isda", "matulis na pakpak", "talinis nga pako"], "fact": {"tl": "Ang tern ay isang ibong-dagat na may matutulis na pakpak at sumisisid sa tubig mula sa himpapawid para humuli ng maliliit na isda.", "en": "The tern is a seabird with sharp, pointed wings that dives into the water from the air to catch small fish.", "bis": "Ang tern usa ka langgam sa dagat nga may talinis nga mga pako ug mosalom sa tubig gikan sa kahanginan aron modakop og gagmay nga isda."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tick-garapata-g5", "domain": "LIVING_THINGS", "topic": "tick parasite", "grades": [4, 5, 6], "terms": ["tick", "garapata", "kuto sa aso", "parasite", "parasito", "dugo", "blood", "sumisipsip ng dugo", "nagsuyop sa dugo", "aso", "iro", "arachnid"], "fact": {"tl": "Ang garapata (tick) ay isang maliit na parasitong kumakapit sa balat ng mga hayop tulad ng aso at sumisipsip ng kanilang dugo, at minsan nakakahawa ito ng sakit.", "en": "The tick (garapata) is a tiny parasite that clings to the skin of animals such as dogs and sucks their blood, and it can sometimes spread disease.", "bis": "Ang garapata (tick) usa ka gamay nga parasito nga mokapyot sa panit sa mga hayop sama sa iro ug nagsuyop sa ilang dugo, ug usahay makatakod kini og sakit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tikling-rail-g5", "domain": "LIVING_THINGS", "topic": "tikling buff-banded rail", "grades": [4, 5, 6], "terms": ["tikling", "buff-banded rail", "barred rail", "ibon", "langgam", "mahabang paa", "taas nga tiil", "palayan", "kaumahan", "tumatakbo", "tinikling dance", "sayaw"], "fact": {"tl": "Ang tikling ay isang ibong may mahahabang paa na karaniwang nakikita sa palayan at damuhan, at sa kanyang maliksing paglakad nahango ang sayaw na tinikling.", "en": "The tikling is a long-legged bird often seen in rice fields and grassy areas, and the folk dance tinikling is named after its nimble steps.", "bis": "Ang tikling usa ka langgam nga taas og tiil nga kasagaran makita sa kaumahan ug kasagbutan, ug gikan sa abtik niini nga paglakaw gikuha ang sayaw nga tinikling."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "toad-g4", "domain": "LIVING_THINGS", "topic": "toad", "grades": [3, 4, 5], "terms": ["toad", "palaka", "palakang-lupa", "baki", "amphibian", "amphibyan", "kulubot na balat", "kubal nga panit", "bumpy dry skin", "lumulukso", "insekto", "lupa"], "fact": {"tl": "Ang palakang-lupa (toad) ay isang amphibian na may tuyo at kulubot na balat, gumugugol ng mas maraming oras sa lupa kaysa tubig, at kumakain ng mga insekto.", "en": "The toad is an amphibian with dry, bumpy skin that spends more time on land than in water and eats insects.", "bis": "Ang baki (toad) usa ka amphibian nga may uga ug kubal nga panit, nga mas magpabilin sa yuta kay sa tubig, ug nagkaon og mga insekto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tuna-school-swim-g5", "domain": "LIVING_THINGS", "topic": "fish schooling", "grades": [4, 5, 6], "terms": ["tuna school", "school of fish", "kawan ng isda", "panon sa isda", "sama-samang langoy", "swim together", "isda", "proteksyon", "protection predator", "manunukob", "tuna", "tambakol"], "fact": {"tl": "Ang tuna at marami pang isda ay lumalangoy nang sama-sama sa malaking kawan, dahil ang sabay-sabay na paggalaw ay nakakalito sa mga maninila at nagbibigay ng proteksyon sa bawat isda.", "en": "Tuna and many other fish swim together in large schools, because moving as one confuses predators and gives each fish protection.", "bis": "Ang tuna ug daghan pang isda naglangoy nga tingob sa dako nga panon, kay ang dungan nga paglihok makalibog sa mga manunukob ug naghatag og panalipod sa matag isda."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tuna-tambakol-g6", "domain": "LIVING_THINGS", "topic": "tuna fish", "grades": [5, 6, 7], "terms": ["tuna", "tambakol", "bariles", "yellowfin", "isda", "fish", "dagat", "matulin", "paspas", "General Santos", "pangisda", "pagpangisda"], "fact": {"tl": "Ang tambakol o tuna ay isang malaki at matuling isda sa bukas na dagat, mahalaga sa pangingisda ng Pilipinas, at kilala ang General Santos City bilang sentro ng tuna sa bansa.", "en": "The tuna (tambakol) is a large, fast fish of the open ocean, important to Philippine fishing, with General Santos City known as the country's tuna center.", "bis": "Ang tambakol o tuna usa ka dako ug paspas nga isda sa lawom nga dagat, importante sa pagpangisda sa Pilipinas, ug ang General Santos City ilado isip sentro sa tuna sa nasod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "viper-snake-coiled-strike-g6", "domain": "LIVING_THINGS", "topic": "viper snake", "grades": [5, 6, 7], "terms": ["viper", "ulupong", "ahas", "halas", "snake", "venomous", "may kamandag", "hilo", "nakalupot", "nagliko-liko", "pangil", "tango"], "fact": {"tl": "Ang viper ay isang ahas na may kamandag na kadalasang nakapulupot at tahimik na naghihintay, pagkatapos ay biglang sumusugod gamit ang mahahabang pangil para tumusok.", "en": "The viper is a venomous snake that often stays coiled and waits quietly, then strikes suddenly with long fangs to inject its venom.", "bis": "Ang viper usa ka halas nga may hilo nga kasagaran nagliko-liko ug hilom nga naghulat, dayon kalit nga moigo gamit ang taas nga mga tango aron motusok og hilo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "visayan-spotted-deer-g6", "domain": "LIVING_THINGS", "topic": "Visayan spotted deer", "grades": [5, 6, 7], "terms": ["Visayan spotted deer", "usa", "spotted deer", "batik-batik na usa", "puntik nga usa", "mammal", "Visayas", "Kabisay-an", "kagubatan", "kalasangan", "Panay", "Negros", "endangered", "nanganganib"], "fact": {"tl": "Ang Visayan spotted deer ay isang usang may puting batik sa likod na matatagpuan lamang sa ilang isla ng Visayas tulad ng Panay at Negros, at isa ito sa mga hayop na nanganganib nang mawala.", "en": "The Visayan spotted deer is a deer with white spots on its back found only on a few Visayan islands such as Panay and Negros, and it is one of the world's endangered animals.", "bis": "Ang Visayan spotted deer usa ka usa nga may puti nga puntik sa likod nga makita lamang sa pipila ka isla sa Kabisay-an sama sa Panay ug Negros, ug usa kini sa mga hayop nga namiligro nga mahurot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wasp-putakti-g5", "domain": "LIVING_THINGS", "topic": "wasp", "grades": [4, 5, 6], "terms": ["wasp", "putakti", "alimpipinig", "insekto", "insect", "tibo", "tusok", "sting", "kamandag", "pugad", "salag", "manipis na baywang", "nipis nga hawak"], "fact": {"tl": "Ang putakti (wasp) ay isang insektong may manipis na baywang at tibo na pang-depensa, at gumagawa ito ng pugad mula sa materyales na parang papel o sa putik.", "en": "The wasp (putakti) is an insect with a narrow waist and a stinger for defense, and it builds a nest from paper-like material or mud.", "bis": "Ang putakti (wasp) usa ka insekto nga may nipis nga hawak ug tusok nga pangdepensa, ug naghimo kini og salag gikan sa morag papel nga materyal o sa lapok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-buffalo-calf-g3", "domain": "LIVING_THINGS", "topic": "carabao water buffalo", "grades": [3, 4, 5], "terms": ["water buffalo", "kalabaw", "carabao", "kabaw", "mammal", "pagsasaka", "pagpanguma", "farming plow", "putik", "lapok", "mud wallow", "sungay", "pambansang hayop"], "fact": {"tl": "Ang kalabaw (water buffalo) ay isang malaking mamalyang tumutulong sa pagsasaka sa Pilipinas, at lumulubog ito sa putik para magpalamig at maiwasan ang mga insekto.", "en": "The water buffalo (carabao) is a large mammal that helps with farming in the Philippines, and it wallows in mud to cool down and keep insects away.", "bis": "Ang kabaw (water buffalo) usa ka dako nga mammal nga motabang sa pagpanguma sa Pilipinas, ug molubong kini sa lapok aron magpabugnaw ug malikayan ang mga insekto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "weevil-snout-beetle-g6", "domain": "LIVING_THINGS", "topic": "weevil snout beetle", "grades": [5, 6, 7], "terms": ["weevil", "snout beetle", "bukbok", "salagubang", "beetle", "insekto", "insect", "mahabang nguso", "taas nga nguso", "butil", "lugas", "bigas", "bugas", "mais", "peste"], "fact": {"tl": "Ang weevil o bukbok ay isang uri ng salagubang na may mahaba at parang ngusong bahagi sa ulo, at madalas itong sumisira sa mga nakaimbak na butil tulad ng bigas at mais.", "en": "The weevil is a kind of beetle with a long snout-like part on its head, and it often damages stored grains such as rice and corn.", "bis": "Ang weevil o bukbok usa ka matang sa salagubang nga may taas ug morag nguso nga bahin sa ulo, ug kasagaran kini makadaot sa gitipig nga mga lugas sama sa bugas ug mais."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wild-cat-musang-leopard-g6", "domain": "LIVING_THINGS", "topic": "leopard cat wild cat", "grades": [5, 6, 7], "terms": ["leopard cat", "wild cat", "maral", "Visayan leopard cat", "ligaw na pusa", "ihalas nga iring", "batik-batik na pusa", "puntik-puntik nga balhibo", "spotted", "mammal", "gabi", "nocturnal", "kagubatan", "kalasangan"], "fact": {"tl": "Ang leopard cat (tinatawag na maral sa Visayas) ay isang maliit na ligaw na pusang may batik-batik na balahibo na naninirahan sa kagubatan at nangangaso ng maliliit na hayop sa gabi.", "en": "The leopard cat (called maral in the Visayas) is a small wild cat with spotted fur that lives in forests and hunts small animals at night.", "bis": "Ang leopard cat (gitawag og maral sa Kabisay-an) usa ka gamay nga ihalas nga iring nga may puntik-puntik nga balhibo nga nagpuyo sa kalasangan ug nangayam og gagmay nga hayop sa gabii."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "woodpecker-anluwage-g5", "domain": "LIVING_THINGS", "topic": "woodpecker bird adaptations", "grades": [4, 5, 6], "terms": ["anluwage", "woodpecker", "ibon", "langgam", "tuka", "matigas na tuka", "tumutuka sa puno", "nagtuktok sa kahoy", "insekto", "uod sa kahoy", "beak", "pecks tree trunk", "tagaktak sa kahoy"], "fact": {"tl": "Ang anluwage (woodpecker) ay isang ibon na may matigas at matulis na tuka na ginagamit nito upang tumuktok sa balat ng puno at kumuha ng mga insekto't uod na nakatago sa loob.", "en": "A woodpecker is a bird with a strong, pointed beak that it uses to peck at tree bark and reach the insects and grubs hidden inside.", "bis": "Ang anluwage (woodpecker) usa ka langgam nga adunay gahi ug talinis nga sungo nga gigamit niini sa pagtuktok sa panit sa kahoy aron makuha ang mga insekto ug ulod nga nagtago sa sulod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "absorbent-vs-waterproof-test-g4", "domain": "MATTER", "topic": "absorbent and waterproof materials", "grades": [3, 4, 5], "terms": ["sumisipsip ng tubig", "absorbent", "absorbente", "waterproof", "hindi tinatablan ng tubig", "tela", "papel", "plastik", "goma", "basa", "tuyo", "sponge", "espongha", "nagsuyop sa tubig", "dili matuhop sa tubig", "plastik nga panapot"], "fact": {"tl": "Ang ilang materyales gaya ng tela, papel, at espongha ay sumisipsip ng tubig (absorbent), samantalang ang plastik at goma ay hindi tinatablan ng tubig (waterproof) kaya pinapatakbo lang nila ito sa ibabaw.", "en": "Some materials like cloth, paper, and sponge soak up water (absorbent), while plastic and rubber keep water out (waterproof) so it just runs off the surface.", "bis": "Ang ubang materyales sama sa panapton, papel, ug espongha mosuyop sa tubig (absorbent), samtang ang plastik ug goma dili matuhop sa tubig (waterproof) maong modagayday lang kini sa ibabaw."}, "source": "AAAS Benchmarks 4D; DepEd G4 Matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "acid-base-household-examples-g6", "domain": "MATTER", "topic": "acids and bases in the home", "grades": [5, 6, 7], "terms": ["asido", "acid", "base", "kalamansi", "suka", "vinegar", "maasim", "sabon", "soap", "mapait", "baking soda", "litmus", "asin", "neutral", "aslom", "asido sa balay", "pait nga base"], "fact": {"tl": "Sa bahay, ang mga maasim na bagay gaya ng suka at katas ng kalamansi ay mga asido (acid), habang ang sabon at baking soda ay mga base na madulas at mapait.", "en": "At home, sour things like vinegar and calamansi juice are acids, while soap and baking soda are bases that feel slippery and taste bitter.", "bis": "Sa balay, ang mga aslom nga butang sama sa suka ug duga sa kalamansi mga asido, samtang ang sabon ug baking soda mga base nga danlog ug pait."}, "source": "AAAS Benchmarks 4D; DepEd G7 Matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "asin-salt-making-saltbeds-g5", "domain": "MATTER", "topic": "salt making by evaporation", "grades": [4, 5, 6], "terms": ["asin", "salt", "gawaan ng asin", "salt bed", "asinan", "tubig-dagat", "seawater", "sumingaw", "evaporation", "init ng araw", "kristal ng asin", "salt crystal", "nagbilad", "paghimo ug asin", "tubig sa dagat", "nag-evaporate"], "fact": {"tl": "Ang asin ay ginagawa sa pamamagitan ng pagsalin ng tubig-dagat sa mababaw na asinan at hinahayaang sumingaw ang tubig sa init ng araw, na nag-iiwan ng mga kristal ng asin.", "en": "Salt is made by letting seawater sit in shallow salt beds where the sun's heat evaporates the water, leaving behind salt crystals.", "bis": "Ang asin gihimo pinaagi sa pagbutang sa tubig-dagat sa mabaw nga asinan ug pasagdan nga moalisngaw ang tubig sa kainit sa adlaw, nga magbilin ug mga kristal sa asin."}, "source": "AAAS Benchmarks 4D; DepEd G5 Matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "cooking-rice-phase-change-g5", "domain": "MATTER", "topic": "phase change cooking rice", "grades": [4, 5, 6], "terms": ["pagluluto ng kanin", "cooking rice", "bigas", "kanin", "tubig", "singaw", "steam", "kumukulo", "boiling", "init", "phase change", "pagbabago ng anyo", "sumingaw ang tubig", "pagluto sa kan-on", "alisngaw", "nagbukal"], "fact": {"tl": "Kapag nagluluto ng kanin, ang init ay nagpapakulo sa tubig at nagiging singaw, at sinisipsip ng bigas ang tubig kaya ito lumalambot at lumalaki.", "en": "When cooking rice, heat boils the water and turns some of it into steam, while the grains absorb water and become soft and swollen.", "bis": "Kon magluto ug kan-on, ang kainit magpabukal sa tubig ug himoon ang uban niini nga alisngaw, samtang ang bugas mosuyop sa tubig maong mahumok ug mohabok kini."}, "source": "AAAS Benchmarks 4D; DepEd G5 Matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "decomposition-reaction-split-g8", "domain": "MATTER", "topic": "decomposition chemical reaction", "grades": [7, 8, 9], "terms": ["decomposition reaction", "reaksyong dekomposisyon", "nahahati", "pinaghihiwalay", "isang sangkap", "dalawang produkto", "chemical reaction", "reaksyong kemikal", "tubig", "hydrogen", "oxygen", "init", "kuryente", "pagkabungkag", "gibahin", "compound"], "fact": {"tl": "Sa reaksyong dekomposisyon, ang isang kompound ay nahahati sa dalawa o higit pang mas simpleng sangkap, gaya ng tubig na pinaghihiwalay sa hydrogen at oxygen gamit ang kuryente.", "en": "In a decomposition reaction, one compound breaks apart into two or more simpler substances, such as water being split into hydrogen and oxygen using electricity.", "bis": "Sa reaksyong dekomposisyon, usa ka compound mabahin ngadto sa duha o labaw pang yano nga mga substansiya, sama sa tubig nga gibahin ngadto sa hydrogen ug oxygen pinaagi sa elektrisidad."}, "source": "AAAS Benchmarks 4D; DepEd G8 Matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "drying-fish-tuyo-racks-g5", "domain": "MATTER", "topic": "drying fish to preserve", "grades": [4, 5, 6], "terms": ["tuyo", "daing", "drying fish", "pagbibilad ng isda", "asin", "salt", "init ng araw", "sun", "sumisingaw", "evaporation", "tubig sa isda", "nabubulok", "preserve", "nagpabilad ug isda", "bulad", "pinabad nga isda", "moalisngaw ang tubig"], "fact": {"tl": "Ang isda ay binubudburan ng asin at ibinibilad sa init ng araw para sumingaw ang tubig dito, kaya nagiging tuyo at hindi madaling mabulok.", "en": "Fish is salted and laid out under the sun so the water in it evaporates, making it dry and slow to spoil.", "bis": "Ang isda gibutangan ug asin ug gipabilad sa init sa adlaw aron moalisngaw ang tubig niini, maong mahimong bulad ug dili dali madunot."}, "source": "AAAS Benchmarks 4D; DepEd G5 Matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "kaldero-rice-cooking-steam-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "heat transfer cooking pot", "grades": [3, 4, 5], "terms": ["kaldero", "pot", "kawali", "metal", "bakal", "init", "heat", "apoy", "nagdadaloy ang init", "conduction", "singaw", "steam", "kalan", "nagluto", "nagaagi ang kainit", "kaldero nga puthaw", "nagbukal"], "fact": {"tl": "Ang kaldero ay yari sa metal dahil madaling dumaloy ang init mula sa apoy patungo sa loob nito, kaya mabilis kumulo ang tubig at maluto ang pagkain.", "en": "A cooking pot is made of metal because heat flows easily from the fire through it, so the water inside boils quickly and the food cooks.", "bis": "Ang kaldero hinimo sa metal kay sayon moagi ang kainit gikan sa kalayo paingon sa sulod niini, maong paspas mobukal ang tubig ug maluto ang pagkaon."}, "source": "AAAS Benchmarks 4E; DepEd G4 Energy", "generator": "claude-workflow", "reviewed": false},
  {"id": "salt-making-evaporation-beds-g6", "domain": "MATTER", "topic": "evaporation and saturated solution", "grades": [5, 6, 7], "terms": ["evaporation", "pagsingaw", "asinan", "salt bed", "solusyon", "natunaw na asin", "dissolved salt", "tubig-dagat", "kristal", "crystal", "sobrang asin", "naiwan", "nag-evaporate", "duga sa dagat", "nahibilin nga asin", "naalisngaw"], "fact": {"tl": "Ang asin ay natunaw sa tubig-dagat, at kapag sumingaw ang tubig, ang asin ay hindi sumasama sa singaw kundi naiiwan bilang mga kristal sa asinan.", "en": "Salt is dissolved in seawater, and when the water evaporates the salt does not leave with the vapor but stays behind as crystals in the salt bed.", "bis": "Ang asin natunaw sa tubig-dagat, ug kon moalisngaw ang tubig ang asin dili mokuyog sa alisngaw kondili mahibilin nga mga kristal sa asinan."}, "source": "AAAS Benchmarks 4D; DepEd G6 Matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "anemometer-g6", "domain": "EARTH_SPACE", "topic": "anemometer measures wind speed", "grades": [5, 6, 7], "terms": ["anemometer", "panukat ng hangin", "bilis ng hangin", "wind speed", "umiikot na tasa", "spinning cups", "panahon", "weather", "PAGASA", "instrumento", "hangin", "kusog sa hangin", "sukdanan sa hangin", "nagtuyok nga tasa"], "fact": {"tl": "Ang anemometer ay isang instrumento na may mga tasa na umiikot sa hangin, at kung mas mabilis itong umikot, mas malakas ang hangin na sinusukat nito.", "en": "An anemometer is an instrument with cups that spin in the wind, and the faster they spin, the stronger the wind speed it measures.", "bis": "Ang anemometer usa ka instrumento nga adunay mga tasa nga magtuyok sa hangin, ug kon mas paspas kini motuyok, mas kusog ang hangin nga gisukod niini."}, "source": "AAAS Benchmarks 4B; DepEd G6 Weather", "generator": "claude-workflow", "reviewed": false},
  {"id": "barometer-g6", "domain": "EARTH_SPACE", "topic": "barometer measures air pressure", "grades": [5, 6, 7], "terms": ["barometer", "presyon ng hangin", "air pressure", "atmospheric pressure", "panahon", "weather", "PAGASA", "ulan", "maaraw", "instrumento", "diin sa hangin", "tagna sa panahon", "presyon sa atmospera", "panukat"], "fact": {"tl": "Ang barometer ay sumusukat sa presyon ng hangin sa atmospera, at ang pagbaba nito ay madalas na palatandaan na may paparating na ulan o bagyo.", "en": "A barometer measures the pressure of the air in the atmosphere, and a falling reading is often a sign that rain or a storm is coming.", "bis": "Ang barometer mosukod sa presyon sa hangin sa atmospera, ug ang pagkahulog niini kasagaran timailhan nga adunay umaabot nga ulan o bagyo."}, "source": "AAAS Benchmarks 4B; DepEd G6 Weather", "generator": "claude-workflow", "reviewed": false},
  {"id": "climate-factors-g7", "domain": "EARTH_SPACE", "topic": "factors that affect climate", "grades": [6, 7, 8], "terms": ["klima", "climate", "latitude", "altitude", "taas sa lupa", "layo sa dagat", "agos ng karagatan", "ocean current", "panahon", "init", "lamig", "kabundukan", "klima sa lugar", "kinaiya sa panahon", "gilay-on sa dagat"], "fact": {"tl": "Ang klima ng isang lugar ay naiimpluwensiyahan ng layo nito sa ekwador, ng taas nito sa lupa, ng kalapitan nito sa dagat, at ng mga agos ng karagatan.", "en": "A place's climate is shaped by its distance from the equator, its height above the land, how close it is to the sea, and ocean currents.", "bis": "Ang klima sa usa ka dapit naimpluwensyahan sa gilay-on niini gikan sa ekwador, sa kahabog niini sa yuta, sa kaduol niini sa dagat, ug sa mga sulog sa kadagatan."}, "source": "NRC ESS2.D; DepEd G7 Earth Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "clothesline-drying-sun-wind-g4", "domain": "MATTER", "topic": "evaporation drying laundry", "grades": [3, 4, 5], "terms": ["sampayan", "clothesline", "pagsasampay", "drying clothes", "init ng araw", "sun", "hangin", "wind", "sumisingaw", "evaporation", "basa", "tuyo", "tubig sa damit", "nagsampay", "namala ang sanina", "moalisngaw"], "fact": {"tl": "Natutuyo ang basang damit sa sampayan dahil ang init ng araw at hangin ay nagpapasingaw sa tubig dito patungong hangin.", "en": "Wet clothes on a clothesline dry because the sun's heat and the wind make the water in them evaporate into the air.", "bis": "Mamala ang basa nga sinina sa sampayan tungod kay ang init sa adlaw ug ang hangin magpaalisngaw sa tubig niini ngadto sa hangin."}, "source": "AAAS Benchmarks 4B; DepEd G4 Matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "cloud-g5", "domain": "EARTH_SPACE", "topic": "how clouds form", "grades": [4, 5, 6], "terms": ["ulap", "cloud", "singaw ng tubig", "water vapor", "lumalamig", "condensation", "patak ng tubig", "water droplets", "langit", "ulan", "rain", "panahon", "panganod", "alisngaw sa tubig", "namuok nga tubig", "nag-condense"], "fact": {"tl": "Ang ulap ay nabubuo kapag ang singaw ng tubig sa hangin ay umaakyat, lumalamig, at nagiging napakaliliit na patak ng tubig o yelo na nagsasama-sama.", "en": "A cloud forms when water vapor in the air rises, cools, and turns into tiny droplets of water or ice that gather together.", "bis": "Ang panganod maporma kon ang alisngaw sa tubig sa hangin mosaka, mobugnaw, ug mahimong gagmayng tulo sa tubig o yelo nga magtapok."}, "source": "NRC ESS2.C; DepEd G5 Weather", "generator": "claude-workflow", "reviewed": false},
  {"id": "coastline-features-g6", "domain": "EARTH_SPACE", "topic": "coastline landforms", "grades": [5, 6, 7], "terms": ["baybayin", "coastline", "dalampasigan", "beach", "look", "bay", "tangos", "cape", "bangin sa dagat", "cliff", "alon", "erosion", "pagguho", "buhangin", "baybayon", "balod", "pangpang", "naagnas"], "fact": {"tl": "Ang baybayin ay ang hangganan kung saan nagtatagpo ang lupa at dagat, at hinuhubog ito ng mga alon sa mga anyo gaya ng dalampasigan, look, at mga bangin.", "en": "A coastline is the boundary where land meets the sea, and waves shape it into features like beaches, bays, and cliffs.", "bis": "Ang baybayon mao ang utlanan diin magtagbo ang yuta ug dagat, ug ang mga balod maghulma niini ngadto sa mga porma sama sa baybayon, look, ug mga pangpang."}, "source": "NRC ESS2.A; DepEd G6 Earth Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "continental-drift-pangaea-g8", "domain": "EARTH_SPACE", "topic": "continental drift and Pangaea", "grades": [7, 8, 9], "terms": ["continental drift", "paggalaw ng kontinente", "Pangaea", "isang malaking kontinente", "supercontinent", "tectonic plates", "plaka ng lupa", "milyong taon", "naghiwalay", "lumayo", "dagat", "pagkalas sa kontinente", "nagbulag", "naglihok nga yuta"], "fact": {"tl": "Milyon-milyong taon na ang nakalipas, ang mga kontinente ay magkakadikit sa isang malaking lupain na tinatawag na Pangaea, at dahan-dahang naghiwalay habang gumagalaw ang mga tectonic plate.", "en": "Millions of years ago the continents were joined in one giant landmass called Pangaea, and they slowly drifted apart as the tectonic plates moved.", "bis": "Milyon-milyon ka tuig na ang milabay, ang mga kontinente nagdikit sa usa ka dako nga yuta nga gitawag og Pangaea, ug hinay-hinay nga nagbulag samtang naglihok ang mga tectonic plate."}, "source": "NRC ESS2.B; DepEd G8 Earth Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "coral-atoll-formation-g8", "domain": "EARTH_SPACE", "topic": "coral atoll formation", "grades": [7, 8, 9], "terms": ["atoll", "coral atoll", "bahurang singsing", "coral reef", "bahura", "isla", "volcano", "bulkan", "lumubog", "lagoon", "polyp", "coral polyp", "singsing na koral", "lawom nga dagat", "nahimong singsing", "naglubog"], "fact": {"tl": "Ang atoll ay isang singsing na bahura na nabuo sa palibot ng isang lumulubog na isla ng bulkan, na nag-iiwan ng kalmadong lagoon sa gitna.", "en": "An atoll is a ring-shaped coral reef that grew around a sinking volcanic island, leaving a calm lagoon in the middle.", "bis": "Ang atoll usa ka porma-singsing nga bahura nga nagtubo palibot sa usa ka naglubog nga isla sa bulkan, nga nagbilin ug kalma nga lagoon sa tunga."}, "source": "NRC ESS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "drought-cracked-rice-field-g6", "domain": "EARTH_SPACE", "topic": "drought and water shortage", "grades": [5, 6, 7], "terms": ["tagtuyot", "drought", "tagtuyo", "matagal na walang ulan", "kakulangan sa tubig", "nag-crack na lupa", "biyak na lupa", "palayan", "rice field", "namatay na pananim", "El Niño", "init", "tagniwang", "nabuak nga yuta", "kahubas sa tubig"], "fact": {"tl": "Ang tagtuyot ay matagal na panahong walang sapat na ulan, kaya natutuyo at namimitak ang lupa sa palayan at nasisira ang mga pananim.", "en": "A drought is a long period with too little rain, so the soil in rice fields dries up and cracks and the crops are ruined.", "bis": "Ang tagtuyot usa ka taas nga panahon nga walay igong ulan, maong mamala ug mabuak ang yuta sa palayan ug madaot ang mga tanom."}, "source": "NRC ESS3.B; DepEd G6 Earth Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "farming-terraced-fields-g6", "domain": "EARTH_SPACE", "topic": "terrace farming prevents erosion", "grades": [5, 6, 7], "terms": ["hagdan-hagdang palayan", "rice terraces", "terrace farming", "Banaue", "Cordillera", "hagdanan sa bukid", "soil erosion", "pagguho ng lupa", "tubig", "patag na lupa", "ani", "naghupot sa yuta", "hagdan-hagdan nga uma", "dili maagnas"], "fact": {"tl": "Ang hagdan-hagdang palayan gaya ng sa Banaue ay mga patag na taniman na inukit sa gilid ng bundok upang pigilan ang pagguho ng lupa at maipon ang tubig para sa pananim.", "en": "Terraced rice fields like those in Banaue are flat steps carved into a mountainside to stop soil from washing away and to hold water for the crops.", "bis": "Ang hagdan-hagdan nga palayan sama sa Banaue mga patag nga tamnanan nga gikulit sa kilid sa bukid aron pugngan ang pag-agnas sa yuta ug tipigan ang tubig alang sa tanom."}, "source": "NRC ESS3.C; DepEd G6 Earth Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "global-warming-impacts-g8", "domain": "EARTH_SPACE", "topic": "global warming impacts", "grades": [7, 8, 9], "terms": ["global warming", "pag-init ng mundo", "greenhouse gas", "carbon dioxide", "pagtaas ng temperatura", "natutunaw na yelo", "melting ice", "pagtaas ng dagat", "sea level rise", "klima", "bagyo", "pag-init sa kalibutan", "natunaw nga yelo", "pagsaka sa dagat"], "fact": {"tl": "Ang global warming ay ang unti-unting pag-init ng mundo dahil sa dami ng greenhouse gases gaya ng carbon dioxide, na nagpapatunaw ng yelo at nagpapataas ng antas ng dagat.", "en": "Global warming is the gradual heating of the Earth caused by greenhouse gases like carbon dioxide, which melts ice and raises sea levels.", "bis": "Ang global warming mao ang hinay-hinay nga pag-init sa kalibutan tungod sa kadaghan sa greenhouse gases sama sa carbon dioxide, nga magtunaw sa yelo ug magpasaka sa lebel sa dagat."}, "source": "NRC ESS3.D; DepEd G8 Earth Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "irrigation-system-farm-g5", "domain": "EARTH_SPACE", "topic": "irrigation supplies water to crops", "grades": [4, 5, 6], "terms": ["irigasyon", "irrigation", "patubig", "kanal", "canal", "ilog", "dam", "tubig sa pananim", "palayan", "pagtutubig", "magsasaka", "ani", "patubig sa uma", "kanal sa tubig", "tubig sa tanom"], "fact": {"tl": "Ang irigasyon ay sistema ng mga kanal at tubo na nagdadala ng tubig mula sa ilog o dam patungo sa mga bukid upang madiligan ang pananim kahit walang ulan.", "en": "Irrigation is a system of canals and pipes that brings water from a river or dam to the fields so crops can be watered even when there is no rain.", "bis": "Ang irigasyon usa ka sistema sa mga kanal ug tubo nga magdala ug tubig gikan sa suba o dam ngadto sa mga uma aron mabisbisan ang mga tanom bisan walay ulan."}, "source": "NRC ESS3.C; DepEd G5 Earth Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "mining-quarry-scene-g7", "domain": "EARTH_SPACE", "topic": "mining extracts earth resources", "grades": [6, 7, 8], "terms": ["pagmimina", "mining", "kantera", "quarry", "mineral", "bato", "ginto", "tanso", "buhangin", "graba", "natural resources", "yamang lupa", "hinukay sa lupa", "mga mineral", "pagkuha sa mineral", "minahan"], "fact": {"tl": "Ang pagmimina at pagkakantera ay paghuhukay ng mga mineral, bato, at metal mula sa lupa, gaya ng ginto, tanso, at graba na ginagamit sa pagtatayo at industriya.", "en": "Mining and quarrying dig minerals, rock, and metals out of the ground, such as gold, copper, and gravel used in building and industry.", "bis": "Ang pagmina ug pagkantera mao ang pagkalot sa mga mineral, bato, ug metal gikan sa yuta, sama sa bulawan, tumbaga, ug graba nga gigamit sa pagtukod ug industriya."}, "source": "NRC ESS3.A; DepEd G7 Earth Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "mountain-range-cordillera-g6", "domain": "EARTH_SPACE", "topic": "mountain range Cordillera", "grades": [5, 6, 7], "terms": ["bulubundukin", "mountain range", "Cordillera", "kabundukan", "Luzon", "magkakadikit na bundok", "tectonic plate", "naipon na lupa", "taas na lupa", "klima sa bundok", "kahit-as", "han-ay sa kabukiran", "bukirong dapit"], "fact": {"tl": "Ang Cordillera ay isang bulubundukin sa hilagang Luzon, isang mahabang hanay ng magkakadikit na matataas na bundok na nabuo sa loob ng milyong taon.", "en": "The Cordillera is a mountain range in northern Luzon, a long chain of high mountains joined together that formed over millions of years.", "bis": "Ang Cordillera usa ka han-ay sa kabukiran sa amihanang Luzon, usa ka taas nga laray sa habog nga mga bukid nga nagdikit ug naporma sulod sa milyon ka tuig."}, "source": "NRC ESS2.B; DepEd G6 Earth Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "rice-drying-on-road-palay-g4", "domain": "MATTER", "topic": "drying palay by evaporation", "grades": [3, 4, 5], "terms": ["palay", "bigas", "rice grains", "pagbibilad ng palay", "drying rice", "init ng araw", "sun", "sumisingaw", "evaporation", "tuyo", "imbak", "hindi mabulok", "nagbilad ug humay", "humay", "namala", "moalisngaw ang tubig"], "fact": {"tl": "Ang palay ay ibinibilad sa init ng araw upang matuyo ito, dahil kapag naalis ang tubig dito, hindi ito madaling maamag o mabulok bago iimbak.", "en": "Palay (rice grain) is spread out under the sun to dry, because once the water leaves it, it is less likely to grow mold or spoil before storage.", "bis": "Ang humay gipabilad sa init sa adlaw aron mamala, kay kon mawala ang tubig niini, dili dali kini agupon o madunot sa dili pa tipigan."}, "source": "AAAS Benchmarks 4B; DepEd G4 Matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "southern-cross-constellation-g6", "domain": "EARTH_SPACE", "topic": "Southern Cross constellation", "grades": [5, 6, 7], "terms": ["konstelasyon", "constellation", "Southern Cross", "Crux", "krus na bituin", "bituin", "stars", "timog", "south", "langit sa gabi", "patnubay", "direksyon", "grupo sa mga bituin", "krus nga konstelasyon", "habagatan"], "fact": {"tl": "Ang Southern Cross (Crux) ay isang maliit na konstelasyon na hugis krus na makikita sa langit sa timog, at ginagamit ito ng mga tao para malaman ang direksyon patungong timog.", "en": "The Southern Cross (Crux) is a small cross-shaped constellation seen in the southern sky, and people use it to find the direction of south.", "bis": "Ang Southern Cross (Crux) usa ka gamay nga konstelasyon nga porma-krus nga makita sa langit sa habagatan, ug gigamit kini sa mga tawo aron mahibal-an ang direksyon paingon sa habagatan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "analog-clock-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "measuring time with a clock", "grades": [3, 4, 5], "terms": ["orasan", "analog clock", "relo", "oras", "time", "kamay ng orasan", "hands of clock", "minuto", "oras na kamay", "segundo", "umiikot", "pagsukat ng oras", "takna", "pagsukod sa oras", "nagtuyok nga kamot"], "fact": {"tl": "Ang analog na orasan ay sumusukat ng oras gamit ang mga kamay na umiikot, kung saan ang maikling kamay ay nagtuturo ng oras at ang mahabang kamay ay nagtuturo ng minuto.", "en": "An analog clock measures time using turning hands, where the short hand points to the hour and the long hand points to the minutes.", "bis": "Ang analog nga orasan mosukod sa oras pinaagi sa mga kamot nga nagtuyok, diin ang mubo nga kamot magtudlo sa takna ug ang taas nga kamot magtudlo sa minuto."}, "source": "DepEd G3 Force and Motion; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bahay-kubo-rice-field-g4", "domain": "LIVING_THINGS", "topic": "rice plant growth in flooded paddy", "grades": [3, 4, 5], "terms": ["palay", "bigas", "bukid", "basakan", "humay", "uma", "rice", "paddy", "field", "rice plant", "tubig", "tanim", "halaman"], "fact": {"tl": "Ang palay ay isang halamang damo na itinatanim sa basa o binahang bukid dahil kailangan nito ng maraming tubig para lumago.", "en": "Rice is a grass plant grown in wet, flooded fields because it needs plenty of water to grow.", "bis": "Ang humay usa ka sagbot nga tanom nga gitanom sa basa o gibahaan nga uma kay nagkinahanglan kini ug daghang tubig aron motubo."}, "source": "encyclopedia-stable consensus; DepEd G4 plants", "generator": "claude-workflow", "reviewed": false},
  {"id": "bahay-kubo-nipa-hut-g5", "domain": "MATTER", "topic": "natural building materials of a nipa hut", "grades": [4, 5, 6], "terms": ["bahay kubo", "kawayan", "nipa", "pawid", "kugon", "kahoy", "bamboo", "nipa hut", "natural materials", "balay", "atup", "materyales"], "fact": {"tl": "Ang bahay kubo ay gawa sa mga likas na materyales tulad ng kawayan at dahon ng nipa, na magaan, malamig, at madaling makuha sa kapaligiran.", "en": "The bahay kubo is built from natural materials like bamboo and nipa leaves, which are light, cool, and easy to gather from the surroundings.", "bis": "Ang bahay kubo gihimo gikan sa kinaiyahang mga materyales sama sa kawayan ug dahon sa nipa, nga gaan, bugnaw, ug sayon makuha sa palibot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bahay-na-bato-stone-house-g6", "domain": "MATTER", "topic": "stone and wood as durable building materials", "grades": [5, 6, 7], "terms": ["bahay na bato", "bato", "kahoy", "pader", "matibay", "stone house", "stone", "wood", "durable", "balay nga bato", "lig-on", "materyales"], "fact": {"tl": "Ang bahay na bato ay may pundasyon at paderang bato na matibay at hindi madaling masunog, kaya't mas matagal itong tumatagal kaysa bahay na gawa sa kahoy lamang.", "en": "The bahay na bato has stone foundations and walls that are strong and not easily burned, so it lasts longer than a house made only of wood.", "bis": "Ang bahay na bato adunay pundasyon ug bongbong nga bato nga lig-on ug dili dali masunog, busa mas dugay kini molungtad kaysa balay nga kahoy lang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "balangay-wooden-boat-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "buoyancy and floating boats", "grades": [4, 5, 6], "terms": ["balangay", "bangka", "kahoy", "lumulutang", "lutang", "tubig", "boat", "float", "buoyancy", "wooden boat", "lutaw", "sakayan"], "fact": {"tl": "Ang balangay ay isang sinaunang bangkang kahoy ng mga Pilipino na lumulutang dahil itinutulak ng tubig ang magaan nitong katawan paitaas.", "en": "The balangay is an ancient Filipino wooden boat that floats because the water pushes its light body upward.", "bis": "Ang balangay usa ka karaang sakayan nga kahoy sa mga Pilipino nga molutaw kay ang tubig moduso sa gaan niini nga lawas paibabaw."}, "source": "encyclopedia-stable consensus; NRC PS2", "generator": "claude-workflow", "reviewed": false},
  {"id": "balut-egg-development-g6", "domain": "LIVING_THINGS", "topic": "embryo development inside an egg", "grades": [5, 6, 7], "terms": ["balut", "itlog", "bibe", "sisiw", "embryo", "duck egg", "develops", "punla", "itlog", "sisiw", "pato"], "fact": {"tl": "Ang balut ay itlog ng pato na pinapainit muna bago lutuin, kaya makikita ang nabubuong sisiw na lumaki sa loob sa tulong ng pula at puti ng itlog.", "en": "Balut is a duck egg incubated for a time before cooking, so you can see a partly formed duck embryo that grew inside, nourished by the egg's yolk and white.", "bis": "Ang balut usa ka itlog sa pato nga gipainit una sa dili pa lutoon, busa makita ang nagporma nga sisiw nga mitubo sa sulod pinaagi sa tabang sa pula ug puti sa itlog."}, "source": "encyclopedia-stable consensus; DepEd life cycle", "generator": "claude-workflow", "reviewed": false},
  {"id": "bamboo-raft-floating-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "why bamboo floats", "grades": [4, 5, 6], "terms": ["balsa", "kawayan", "lumulutang", "ilog", "tubig", "bamboo raft", "float", "river", "bamboo", "gaan", "lutaw", "salog", "suba"], "fact": {"tl": "Ang balsang kawayan ay lumulutang dahil ang kawayan ay magaan at may hangin sa loob ng mga hungkag nitong bahagi.", "en": "A bamboo raft floats because bamboo is light and has air trapped inside its hollow sections.", "bis": "Ang balsa nga kawayan molutaw kay ang kawayan gaan ug adunay hangin sulod sa bakante niini nga mga bahin."}, "source": "encyclopedia-stable consensus; NRC PS2", "generator": "claude-workflow", "reviewed": false},
  {"id": "bangkero-rowing-river-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "rowing and reaction force in water", "grades": [4, 5, 6], "terms": ["bangkero", "sagwan", "bangka", "ilog", "itulak", "boat", "row", "paddle", "oar", "force", "bugsay", "suba", "tulod"], "fact": {"tl": "Kapag itinutulak ng bangkero ang tubig pabalik gamit ang sagwan, ang tubig ay tumutulak din sa bangka pasulong, kaya ito gumagalaw.", "en": "When the boatman pushes the water backward with a paddle, the water pushes the boat forward, making it move.", "bis": "Kon ituok sa bangkero ang tubig pabalik pinaagi sa bugsay, ang tubig moduso usab sa bangka paunahan, busa molihok kini."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "basnigan-fishing-boat-g6", "domain": "LIVING_THINGS", "topic": "fishing and the marine food source", "grades": [5, 6, 7], "terms": ["basnigan", "bangka", "isda", "pangisda", "dagat", "lambat", "fishing boat", "fish", "sea", "net", "catch", "mananagat", "pukot"], "fact": {"tl": "Ang basnigan ay isang bangkang pangisda na gumagamit ng ilaw at lambat sa gabi para hulihin ang mga isdang lumalapit sa liwanag.", "en": "The basnigan is a fishing boat that uses lights and nets at night to catch fish that are drawn to the light.", "bis": "Ang basnigan usa ka sakayan sa pagpangisda nga mogamit ug suga ug pukot sa gabii aron dakpon ang mga isda nga moduol sa kahayag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bathing-cleanliness-health-g3", "domain": "LIVING_THINGS", "topic": "hygiene prevents germs and illness", "grades": [3, 4, 5], "terms": ["paliligo", "kalinisan", "sabon", "mikrobyo", "sakit", "bathing", "hygiene", "soap", "germs", "clean", "kaligo", "kahinlo", "kagaw"], "fact": {"tl": "Ang regular na paliligo gamit ang sabon ay nag-aalis ng dumi at mikrobyong maaaring magdulot ng sakit sa ating katawan.", "en": "Bathing regularly with soap removes dirt and germs that can cause illness in our body.", "bis": "Ang kanunay nga pagkaligo gamit ang sabon mokuha sa hugaw ug kagaw nga makahatag ug sakit sa atong lawas."}, "source": "encyclopedia-stable consensus; DepEd health", "generator": "claude-workflow", "reviewed": false},
  {"id": "bayanihan-carrying-hut-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "many people share a heavy load", "grades": [3, 4, 5], "terms": ["bayanihan", "bahay kubo", "pasan", "bigat", "lakas", "carry", "load", "force", "lift", "weight", "pas-an", "kabug-aton", "kusog"], "fact": {"tl": "Sa bayanihan, maraming tao ang sabay-sabay na bumubuhat sa bahay kubo dahil ang bigat nito ay nahahati sa lahat, kaya mas magaan para sa bawat isa.", "en": "In bayanihan, many people lift the nipa hut together because the weight is shared among all, so it feels lighter for each person.", "bis": "Sa bayanihan, daghang tawo ang dungan nga moalsa sa bahay kubo kay ang kabug-aton gibahin sa tanan, busa mas gaan alang sa matag usa."}, "source": "NRC PS2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bicycle-commuter-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "wheels and pedaling turn effort into motion", "grades": [4, 5, 6], "terms": ["bisikleta", "gulong", "pedal", "kadena", "galaw", "bicycle", "wheels", "pedal", "chain", "motion", "ligid", "lihok", "tuyok"], "fact": {"tl": "Kapag nagpepedal ka sa bisikleta, ang lakas mo ay dumadaan sa kadena patungo sa gulong, kaya ito umiikot at gumagalaw ang bisikleta.", "en": "When you pedal a bicycle, your effort passes through the chain to the wheel, making it spin so the bicycle moves.", "bis": "Kon mopedal ka sa bisikleta, ang imong kusog moagi sa kadena padulong sa ligid, busa motuyok kini ug molihok ang bisikleta."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "blacksmith-panday-forge-g6", "domain": "MATTER", "topic": "heating metal makes it soft and shapeable", "grades": [5, 6, 7], "terms": ["panday", "bakal", "apoy", "init", "hubog", "blacksmith", "metal", "iron", "fire", "heat", "shape", "puthaw", "kalayo"], "fact": {"tl": "Ipinapainit muna ng panday ang bakal sa apoy hanggang sa lumambot ito, para madali itong mahubog sa nais na hugis bago muling tumigas habang lumalamig.", "en": "A blacksmith heats iron in fire until it softens, so it can be hammered into shape before it hardens again as it cools.", "bis": "Painiton una sa panday ang puthaw sa kalayo hangtod nga molumo kini, aron sayon hulmahon sa gusto nga porma sa dili pa motig-a usab samtang nagbugnaw."}, "source": "NRC PS1.A states of matter; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "boiling-water-banga-g4", "domain": "MATTER", "topic": "boiling water turns into steam", "grades": [3, 4, 5], "terms": ["pinakuluang tubig", "banga", "singaw", "init", "kumukulo", "boiling water", "steam", "heat", "clay jar", "evaporate", "alisngaw", "kuluan"], "fact": {"tl": "Kapag pinakukuluan ang tubig sa bangang luwad, umiinit ito hanggang sa maging singaw na pumapaitaas sa hangin.", "en": "When water is boiled in a clay jar, it heats up until it turns into steam that rises into the air.", "bis": "Kon pakuloan ang tubig sa banga nga yutang-kulonon, moinit kini hangtod nga mahimong alisngaw nga mosaka sa hangin."}, "source": "NRC PS1.A; DepEd G4 changes of state", "generator": "claude-workflow", "reviewed": false},
  {"id": "brownout-candlelight-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "candle gives light when electricity is gone", "grades": [3, 4, 5], "terms": ["brownout", "kandila", "ilaw", "kuryente", "liwanag", "blackout", "candle", "light", "electricity", "flame", "suga"], "fact": {"tl": "Kapag nawalan ng kuryente o brownout, ang kandila ay nagbibigay ng liwanag sa pamamagitan ng nagliliyab nitong mitsa.", "en": "During a brownout, a candle gives off light through its burning wick.", "bis": "Kon mawad-an ug kuryente o brownout, ang kandila mohatag ug kahayag pinaagi sa nagdilaab niini nga pabilo."}, "source": "encyclopedia-stable consensus; NRC PS3 energy", "generator": "claude-workflow", "reviewed": false},
  {"id": "carabao-sled-paragos-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "animal pulling force and friction on a sled", "grades": [4, 5, 6], "terms": ["kalabaw", "paragos", "hila", "puwersa", "kiskisan", "carabao", "sled", "pull", "force", "friction", "kabaw", "guyod", "kusog"], "fact": {"tl": "Ang kalabaw ay humihila ng paragos sa putikang bukid sa pamamagitan ng paggamit ng malakas nitong puwersa para magalaw ang mabigat na sakay.", "en": "A carabao pulls a sled across a muddy field by using its strong force to move the heavy load.", "bis": "Ang kabaw moguyod sa paragos sa lapokon nga uma pinaagi sa paggamit sa kusog niini nga puwersa aron malihok ang bug-at nga karga."}, "source": "NRC PS2.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cargo-tricycle-delivery-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "engine converts fuel into motion", "grades": [4, 5, 6], "terms": ["traysikel", "makina", "gasolina", "galaw", "kargada", "tricycle", "engine", "fuel", "motion", "cargo", "tuyok"], "fact": {"tl": "Ang traysikel na may kargada ay gumagalaw dahil ang makina nito ay nagsusunog ng gasolina para makalikha ng lakas na nagpapaikot sa gulong.", "en": "A cargo tricycle moves because its engine burns fuel to create the power that turns the wheels.", "bis": "Ang traysikel nga adunay karga molihok kay ang makina niini mosunog ug gasolina aron makamugna ug kusog nga motuyok sa ligid."}, "source": "NRC PS3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "carolers-christmas-sound-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "sound is made by vibrations", "grades": [3, 4, 5], "terms": ["mga namamasko", "kanta", "tunog", "tinig", "yanig", "carolers", "singing", "sound", "voice", "vibration", "awit", "tingog", "kurog"], "fact": {"tl": "Kapag kumakanta ang mga namamasko, gumagawa sila ng tunog dahil nanginginig ang kanilang mga kuwerdas-bokal sa lalamunan.", "en": "When carolers sing, they make sound because the vocal cords in their throats vibrate.", "bis": "Kon mokanta ang mga namasko, makahimo sila ug tingog kay nagkurog ang ilang mga kuwerdas-bokal sa tutunlan."}, "source": "NRC PS4.A sound; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "carpenter-karpintero-tools-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "hammer and lever multiply force", "grades": [4, 5, 6], "terms": ["karpintero", "martilyo", "pako", "lagari", "puwersa", "carpenter", "hammer", "nail", "saw", "tool", "force", "lansang", "gabas"], "fact": {"tl": "Ginagamit ng karpintero ang martilyo para palakasin ang puwersa ng kanyang kamay at maipasok ang pako sa kahoy.", "en": "A carpenter uses a hammer to amplify the force of the hand and drive a nail into the wood.", "bis": "Gamiton sa karpintero ang martilyo aron padaghanon ang kusog sa iyang kamot ug maipasok ang lansang sa kahoy."}, "source": "NRC PS2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "chopping-vegetables-g4", "domain": "MATTER", "topic": "cutting changes shape not material", "grades": [3, 4, 5], "terms": ["paghiwa", "gulay", "kutsilyo", "hiwa", "hugis", "chopping", "vegetables", "knife", "cut", "shape", "tadtad", "utan", "utanon"], "fact": {"tl": "Kapag hiniwa ang gulay, nagbabago lang ang hugis at laki nito ngunit nananatili pa rin itong gulay.", "en": "When a vegetable is chopped, only its shape and size change, but it is still the same vegetable.", "bis": "Kon hiwaon ang utanon, ang porma ug gidak-on ra niini ang mausab apan utanon gihapon kini."}, "source": "NRC PS1.A; DepEd G4 physical change", "generator": "claude-workflow", "reviewed": false},
  {"id": "classroom-science-lesson-g3", "domain": "LIVING_THINGS", "topic": "observation is how scientists learn", "grades": [3, 4, 5], "terms": ["paaralan", "agham", "obserbasyon", "tanong", "siyentista", "classroom", "science", "observe", "question", "scientist", "siyensya", "obserba", "pangutana"], "fact": {"tl": "Sa klase sa agham, natututo tayo sa pamamagitan ng maingat na pagmamasid, pagtatanong, at pagsubok upang maunawaan ang mundo sa paligid natin.", "en": "In science class, we learn by carefully observing, asking questions, and testing ideas to understand the world around us.", "bis": "Sa klase sa siyensya, makakat-on kita pinaagi sa maampingong pagbantay, pagpangutana, ug pagsulay aron masabtan ang kalibotan sa atong palibot."}, "source": "NRC science practices; DepEd MATATAG", "generator": "claude-workflow", "reviewed": false},
  {"id": "clean-vs-dirty-environment-g4", "domain": "EARTH_SPACE", "topic": "clean environment protects health", "grades": [3, 4, 5], "terms": ["malinis", "marumi", "kapaligiran", "basura", "kalusugan", "clean", "dirty", "environment", "trash", "health", "hinlo", "hugaw", "palibot"], "fact": {"tl": "Ang malinis na kapaligiran na walang nakakalat na basura ay nakapagpapanatili sa atin na malusog at pumipigil sa pagkalat ng sakit.", "en": "A clean environment free of scattered trash keeps us healthy and prevents the spread of illness.", "bis": "Ang hinlo nga palibot nga walay nagkatag nga basura makapadayon kanato nga himsog ug makapugong sa pagkaylap sa sakit."}, "source": "encyclopedia-stable consensus; DepEd environment", "generator": "claude-workflow", "reviewed": false},
  {"id": "coconut-climber-g5", "domain": "LIVING_THINGS", "topic": "coconut palm and its fruit", "grades": [4, 5, 6], "terms": ["niyog", "puno ng niyog", "bunga", "akyat", "buko", "coconut", "palm tree", "fruit", "climb", "coconut tree", "lubi", "saka"], "fact": {"tl": "Inaakyat ng mangangakyat ang mataas na puno ng niyog para pitasin ang mga bunga nito na may matamis na tubig at malasang laman sa loob.", "en": "A coconut climber climbs the tall coconut palm to gather its fruits, which hold sweet water and tasty flesh inside.", "bis": "Sakaon sa mangangakyat ang taas nga punoan sa lubi aron pupoon ang mga bunga niini nga adunay tam-is nga tubig ug lami nga unod sa sulod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cooking-adobo-chemical-change-g6", "domain": "MATTER", "topic": "cooking is a chemical change", "grades": [5, 6, 7], "terms": ["adobo", "pagluluto", "init", "pagbabago", "karne", "cooking", "heat", "chemical change", "meat", "stove", "luto", "kausaban"], "fact": {"tl": "Kapag niluluto ang adobo, ang init ay nagdudulot ng pagbabagong kemikal sa karne na nagpapalambot at nagpapabago ng lasa nito.", "en": "When adobo is cooked, the heat causes a chemical change in the meat that makes it tender and changes its flavor.", "bis": "Kon lutoon ang adobo, ang init maghatag ug kemikal nga kausaban sa karne nga makapahumok ug makapausab sa lami niini."}, "source": "NRC PS1.B chemical reactions; DepEd G6", "generator": "claude-workflow", "reviewed": false},
  {"id": "copra-coconut-drying-g6", "domain": "MATTER", "topic": "drying removes water from coconut meat", "grades": [5, 6, 7], "terms": ["kopras", "niyog", "patuyo", "tuyo", "araw", "copra", "coconut", "drying", "dry", "sun", "lubi", "pauga", "uga"], "fact": {"tl": "Ang kopras ay gawa sa lamang-niyog na pinatuyo sa init ng araw o apoy para maalis ang tubig dito at hindi madaling mabulok.", "en": "Copra is made from coconut meat dried in the sun or by fire to remove its water so it does not spoil easily.", "bis": "Ang kopras gihimo gikan sa unod sa lubi nga gipauga sa init sa adlaw o kalayo aron makuha ang tubig niini ug dili dali madunot."}, "source": "NRC PS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dapog-firewood-cooking-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "burning wood releases heat for cooking", "grades": [3, 4, 5], "terms": ["dapog", "kahoy na panggatong", "apoy", "init", "luto", "firewood", "fire", "heat", "stove", "cooking", "kalayo", "sugnod"], "fact": {"tl": "Sa dapog, ang nasusunog na kahoy na panggatong ay naglalabas ng init na ginagamit para magluto ng pagkain.", "en": "In a firewood stove, the burning wood releases heat that is used to cook food.", "bis": "Sa dapog, ang nagdilaab nga sugnod nga kahoy mopagawas ug init nga gigamit aron magluto ug pagkaon."}, "source": "NRC PS3 energy; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "drying-palay-roadside-g4", "domain": "MATTER", "topic": "sun drying of palay (evaporation)", "grades": [3, 4, 5], "terms": ["palay", "bigas", "patuyo", "pinatutuyo sa araw", "init ng araw", "singaw ng tubig", "humal", "pagbubukbok", "humayan sa palay", "pagsibwag sa palay", "pabad-an", "kainit sa adlaw", "drying palay", "sun drying", "rice grains", "moisture", "evaporation"], "fact": {"tl": "Ikinakalat ang palay sa init ng araw para sumingaw ang tubig sa loob nito, kaya tumutuyo ito at hindi madaling mabulok kapag itinatabi.", "en": "Palay is spread out in the hot sun so the water inside the grains evaporates, drying them so they will not spoil easily in storage.", "bis": "Ginabulad ang palay sa kainit sa adlaw aron mosingaw ang tubig sa sulod niini, busa momala kini ug dili dali madaot kon tipigan."}, "source": "encyclopedia-stable consensus; NRC PS1.A (states of matter / evaporation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "ejeepney-electric-motor-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "electric jeepney runs on a motor and battery", "grades": [5, 6, 7], "terms": ["e-jeepney", "modernong dyip", "elektrikong dyip", "motor", "baterya", "kuryente", "elektrisidad", "walang usok", "modernong jeepney", "elektrikong sakyanan", "koryente", "wala mobuga", "elektronikong dyip", "electric jeepney", "modern jeepney", "battery", "electric motor", "no exhaust", "clean energy"], "fact": {"tl": "Ang modernong e-jeepney ay pinapaandar ng elektrikong motor na kumukuha ng lakas sa baterya, kaya hindi ito bumubuga ng itim na usok tulad ng lumang dyip na de-disel.", "en": "The modern e-jeepney is driven by an electric motor powered by a battery, so it does not release the black exhaust smoke that old diesel jeepneys do.", "bis": "Ang modernong e-jeepney gipadagan sa elektrikong motor nga gikan sa baterya ang kusog, busa wala kini mobuga ug itom nga aso sama sa daang diesel nga dyip."}, "source": "encyclopedia-stable consensus; NRC PS3 (energy transfer)", "generator": "claude-workflow", "reviewed": false},
  {"id": "gas-lamp-combustion-light-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "kerosene lamp turns fuel into light and heat", "grades": [5, 6, 7], "terms": ["gasera", "lamparilya", "ilawan", "gaas", "kerosene", "mitsa", "apoy", "liwanag", "init", "pagliyab", "kingki", "suga", "lampara", "gas", "pabilo", "kalayo", "kahayag", "gas lamp", "kerosene lamp", "wick", "flame", "combustion", "light and heat"], "fact": {"tl": "Sa gasera, umaakyat ang gaas sa mitsa at nasusunog, at ang pagliyab na ito ang nagbibigay ng liwanag at init kapag walang kuryente.", "en": "In a kerosene lamp, oil climbs up the wick and burns, and this burning gives off light and heat when there is no electricity.", "bis": "Sa gasera, mosaka ang gaas sa pabilo ug masunog, ug kini nga pagdilaab maoy mohatag ug kahayag ug kainit kon walay koryente."}, "source": "encyclopedia-stable consensus; NRC PS3 (energy / combustion)", "generator": "claude-workflow", "reviewed": false},
  {"id": "ferry-floats-buoyancy-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "why a heavy ferry floats (buoyancy)", "grades": [4, 5, 6], "terms": ["barko", "ferry", "lantsa", "lumulutang", "tubig", "bigat", "buoyancy", "tulak pataas", "pampasahero", "nakalutaw", "molutaw", "kabug-at", "bug-at nga barko", "salapay sa tubig", "ferry boat", "float", "buoyancy", "water displacement", "ship floats"], "fact": {"tl": "Kahit mabigat ang isang ferry na puno ng pasahero, lumulutang ito dahil itinutulak ito pataas ng tubig na natabig ng malaki at guwang na katawan nito.", "en": "Even though a ferry full of passengers is heavy, it floats because the water pushes it upward against its large, hollow hull.", "bis": "Bisan bug-at ang usa ka ferry nga puno sa pasahero, molutaw kini tungod kay ang tubig motukmod niini paibabaw batok sa dako ug hawan nga lawas niini."}, "source": "encyclopedia-stable consensus; NRC PS2 (forces / buoyancy)", "generator": "claude-workflow", "reviewed": false},
  {"id": "poso-water-pump-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "hand pump lifts water using suction and air pressure", "grades": [4, 5, 6], "terms": ["poso", "bomba", "balon", "tubig sa ilalim", "pagkuha ng tubig", "hatak", "suction", "presyon ng hangin", "igib", "ibabaw na tubig", "pump", "bomba sa tubig", "poso nga bomba", "pagkuha ug tubig", "ground water", "hand pump", "water pump", "suction", "air pressure", "well water"], "fact": {"tl": "Kapag itinataas at ibinababa ang hawakan ng poso, gumagawa ito ng espasyong walang hangin sa loob, at itinutulak ng presyon ng hangin ang tubig pataas mula sa lupa.", "en": "When you push the handle of a poso up and down, it makes an empty, airless space inside, and air pressure pushes the water up from the ground.", "bis": "Kon ipasaka-ubos ang kuptanan sa poso, makahimo kini ug walay-hangin nga luna sa sulod, ug ang presyon sa hangin motukmod sa tubig paibabaw gikan sa yuta."}, "source": "encyclopedia-stable consensus; NRC PS2 (air pressure / forces)", "generator": "claude-workflow", "reviewed": false},
  {"id": "fish-cage-aquaculture-g6", "domain": "LIVING_THINGS", "topic": "fish cages and pens grow fish in lakes (aquaculture)", "grades": [5, 6, 7], "terms": ["fish cage", "baklad", "kulungan ng isda", "lawa", "tilapia", "bangus", "pag-aalaga ng isda", "akwakultura", "pataba", "isda sa lawa", "pinalalaki", "hawla sa isda", "alima sa isda", "linaw", "pisi sa isda", "aquaculture", "fish cage", "fish pen", "lake fish farming", "tilapia", "milkfish"], "fact": {"tl": "Sa mga fish cage o baklad sa lawa, inaalagaan at pinakakain ang mga isdang tulad ng tilapia at bangus hanggang sa lumaki ang mga ito para anihin.", "en": "In fish cages or pens in a lake, fish such as tilapia and milkfish are kept and fed until they grow big enough to be harvested.", "bis": "Sa mga fish cage o baklad sa linaw, ginaatiman ug ginapakaon ang mga isda sama sa tilapia ug bangus hangtod modako kini aron anihon."}, "source": "encyclopedia-stable consensus; DepEd Science (ecosystems / aquaculture)", "generator": "claude-workflow", "reviewed": false},
  {"id": "fish-drying-preservation-g4", "domain": "MATTER", "topic": "sun-drying fish to preserve it (daing/bulad)", "grades": [3, 4, 5], "terms": ["daing", "tuyo", "pinatuyong isda", "asin", "pinatutuyo sa araw", "init ng araw", "singaw ng tubig", "hindi mabulok", "preserba", "bulad", "ginbulad nga isda", "asin sa isda", "pagbulad", "dili madaot", "dried fish", "salting", "sun drying fish", "preservation", "bacteria", "moisture removal"], "fact": {"tl": "Ang isda ay inaasinan at ibinibilad sa araw para mawala ang tubig dito, at sa tuyong isda ay hindi madaling dumami ang bakterya na nagpapabulok.", "en": "Fish is salted and dried in the sun to remove its water, and in dry fish the bacteria that cause spoilage cannot multiply easily.", "bis": "Ang isda ginaasinan ug ginabulad sa adlaw aron mawala ang tubig niini, ug sa mala nga isda dili dali modaghan ang bakterya nga maoy hinungdan sa pagkadaot."}, "source": "encyclopedia-stable consensus; NRC LS1 (microbes) / PS1 (evaporation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "fish-port-gills-g4", "domain": "LIVING_THINGS", "topic": "fish breathe with gills, why fresh fish come from the sea", "grades": [3, 4, 5], "terms": ["isda", "hasang", "paghinga sa tubig", "dagat", "huli", "presko", "oksiheno", "gills", "isda sa dagat", "hasang sa isda", "presko nga isda", "ginakuha sa dagat", "fish gills", "breathing in water", "oxygen", "fresh catch", "sea fish"], "fact": {"tl": "Ang mga isdang ibinababa sa pantalan ay humihinga sa tubig sa pamamagitan ng kanilang hasang, na kumukuha ng oksiheno mula sa tubig-dagat.", "en": "The fish unloaded at the port breathe in water using their gills, which take in oxygen from the seawater.", "bis": "Ang mga isda nga ginakanaog sa pantalan moginhawa sa tubig pinaagi sa ilang hasang, nga mokuha ug oksiheno gikan sa tubig-dagat."}, "source": "encyclopedia-stable consensus; NRC LS1.A (structure & function)", "generator": "claude-workflow", "reviewed": false},
  {"id": "fisherman-net-catch-g4", "domain": "LIVING_THINGS", "topic": "casting a net to catch fish; fish travel in schools", "grades": [3, 4, 5], "terms": ["mangingisda", "lambat", "paghahagis ng lambat", "huli ng isda", "kawan ng isda", "dagat", "pukot", "mananagat", "pagtaktak sa pukot", "panon sa isda", "isda sa dagat", "fisherman", "fishing net", "casting net", "school of fish", "catch"], "fact": {"tl": "Inihahagis ng mangingisda ang lambat sa tubig upang hulihin nang sabay-sabay ang isang kawan ng mga isdang magkakasama na lumalangoy.", "en": "A fisherman throws a net into the water to catch all at once a school of fish that swim together in a group.", "bis": "Ginalabay sa mananagat ang pukot ngadto sa tubig aron dakpon dungan ang usa ka panon sa mga isda nga naglangoy nga nagtipon."}, "source": "encyclopedia-stable consensus; NRC LS2 (animal behavior / groups)", "generator": "claude-workflow", "reviewed": false},
  {"id": "fishing-banca-outrigger-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "outrigger (katig) keeps a banca stable", "grades": [4, 5, 6], "terms": ["bangka", "banca", "katig", "outrigger", "hindi tumataob", "balanse", "dagat", "alon", "matatag", "baroto", "katig sa bangka", "dili motakilid", "timbang", "balod", "outrigger canoe", "bangka", "stability", "balance", "waves", "boat"], "fact": {"tl": "Ang katig sa magkabilang gilid ng bangka ay tumutulong na panatilihin itong matatag at hindi tumaob kahit may malalaking alon sa dagat.", "en": "The outrigger floats on each side of a banca help keep it steady so it does not tip over even when there are big waves at sea.", "bis": "Ang katig sa duha ka kilid sa bangka motabang aron magpabiling lig-on kini ug dili motakilid bisan adunay dagkong balod sa dagat."}, "source": "encyclopedia-stable consensus; NRC PS2 (stability / balance)", "generator": "claude-workflow", "reviewed": false},
  {"id": "food-handling-hygiene-g4", "domain": "LIVING_THINGS", "topic": "washing hands and clean handling prevent germs in food", "grades": [3, 4, 5], "terms": ["paghuhugas ng kamay", "kalinisan", "mikrobyo", "bakterya", "ligtas na pagkain", "sakit sa tiyan", "sabon", "germ", "paghugas ug kamot", "limpyo nga pagkaon", "kagaw", "sabon", "hand washing", "hygiene", "germs", "bacteria", "food safety", "contamination"], "fact": {"tl": "Ang paghuhugas ng kamay gamit ang sabon bago humawak ng pagkain ay nag-aalis ng mga mikrobyong di-nakikita na maaaring magpasakit sa atin.", "en": "Washing your hands with soap before touching food removes invisible germs that could make us sick.", "bis": "Ang paghugas sa kamot gamit ang sabon una mokuptan sa pagkaon mokuha sa dili makita nga mga kagaw nga makapasakit kanato."}, "source": "encyclopedia-stable consensus; NRC LS1 (microbes / health)", "generator": "claude-workflow", "reviewed": false},
  {"id": "food-cooking-kills-germs-g5", "domain": "MATTER", "topic": "cooking food with heat kills harmful germs", "grades": [4, 5, 6], "terms": ["pagluluto", "init", "lutong-luto", "bakterya", "mikrobyo", "ligtas na pagkain", "hilaw", "pagpapakulo", "pagpaluto", "kainit", "kagaw", "luto nga pagkaon", "hilaw nga pagkaon", "cooking food", "heat kills germs", "raw food", "bacteria", "food safety"], "fact": {"tl": "Ang lubusang pagluluto ng pagkain sa init ay pumapatay sa mga nakakasakit na bakteryang maaaring nasa hilaw na karne o isda.", "en": "Cooking food thoroughly with heat kills the harmful bacteria that may be in raw meat or fish.", "bis": "Ang hingpit nga pagluto sa pagkaon sa kainit mopatay sa makadaot nga bakterya nga mahimong anaa sa hilaw nga karne o isda."}, "source": "encyclopedia-stable consensus; NRC LS1 (microbes) / PS3 (heat)", "generator": "claude-workflow", "reviewed": false},
  {"id": "habal-habal-friction-grip-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "tire friction grips a steep trail; motorcycle motion", "grades": [5, 6, 7], "terms": ["habal-habal", "motorsiklo", "gulong", "friction", "pagkapit", "matarik na daan", "trail", "bundok", "kabundukan", "ligid", "pagkupot", "tarik nga dalan", "motorcycle", "tire friction", "grip", "steep trail", "mountain road"], "fact": {"tl": "Ang habal-habal ay nakakaakyat sa matatarik na daan sa bundok dahil sa friction o pagkapit ng makapal na gulong nito sa lupa.", "en": "A habal-habal motorcycle can climb steep mountain trails because of the friction, or grip, between its thick tires and the ground.", "bis": "Ang habal-habal makasaka sa tarik nga dalan sa bukid tungod sa friction o paggunit sa baga niini nga ligid sa yuta."}, "source": "encyclopedia-stable consensus; NRC PS2.A (friction / forces)", "generator": "claude-workflow", "reviewed": false},
  {"id": "hanging-laundry-evaporation-g4", "domain": "MATTER", "topic": "wet clothes dry by evaporation in sun and wind", "grades": [3, 4, 5], "terms": ["sampay", "labada", "pagtutuyo ng damit", "sablay", "araw", "hangin", "singaw", "natutuyo", "basa", "tuyo", "sampayan", "pagsampay", "bisti", "kainit sa adlaw", "molabhan", "mala nga sinina", "hanging laundry", "drying clothes", "evaporation", "sun and wind", "clothesline"], "fact": {"tl": "Natutuyo ang basang damit sa sampayan dahil sumisingaw ang tubig dito patungo sa hangin, lalo na kapag mainit ang araw at may hangin.", "en": "Wet clothes on the line dry because the water in them evaporates into the air, especially when the sun is hot and there is wind.", "bis": "Momala ang basa nga sinina sa sampayan tungod kay mosingaw ang tubig niini ngadto sa hangin, ilabina kon init ang adlaw ug adunay hangin."}, "source": "encyclopedia-stable consensus; NRC PS1.A (evaporation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "home-safety-hazards-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "common home hazards: electricity, fire, slippery floors", "grades": [3, 4, 5], "terms": ["kaligtasan sa bahay", "panganib", "kuryente", "apoy", "madulas na sahig", "kuldas", "pinsala", "ingat", "peligro sa balay", "koryente", "kalayo", "danlog nga salog", "kaluwasan", "home safety", "hazards", "electricity", "fire", "slippery floor", "injury"], "fact": {"tl": "Sa bahay ay may mga panganib gaya ng kuryenteng nakabukas, apoy sa kalan, at madulas na sahig, kaya kailangan ng pag-iingat upang maiwasan ang aksidente.", "en": "At home there are hazards like live electricity, fire from the stove, and slippery floors, so care is needed to avoid accidents.", "bis": "Sa balay adunay mga peligro sama sa abli nga koryente, kalayo sa kalan, ug danlog nga salog, busa kinahanglan ang pag-amping aron malikayan ang aksidente."}, "source": "encyclopedia-stable consensus; DepEd Science (safety)", "generator": "claude-workflow", "reviewed": false},
  {"id": "ice-block-melting-g4", "domain": "MATTER", "topic": "ice melts from solid to liquid when it warms", "grades": [3, 4, 5], "terms": ["yelo", "ice", "natutunaw", "solid", "likido", "init", "tubig", "pagkatunaw", "bloke ng yelo", "yelo nga block", "matunaw", "molalâ", "kainit", "ice block", "melting", "solid to liquid", "heat", "water"], "fact": {"tl": "Ang bloke ng yelo ay natutunaw at nagiging tubig kapag uminit, dahil ang yelo ay solidong anyo ng tubig na lumalambot sa init.", "en": "A block of ice melts into water when it warms up, because ice is the solid form of water that softens into liquid with heat.", "bis": "Ang block sa yelo matunaw ug mahimong tubig kon moinit, kay ang yelo mao ang gahi nga porma sa tubig nga molalâ sa kainit."}, "source": "encyclopedia-stable consensus; NRC PS1.A (states of matter / melting)", "generator": "claude-workflow", "reviewed": false},
  {"id": "jeepney-cargo-weight-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "load on a vehicle roof raises its center of gravity", "grades": [6, 7, 8], "terms": ["dyip", "jeepney", "kargada sa bubong", "bigat", "sentro ng bigat", "balanse", "tumba", "center of gravity", "karga", "atop sa dyip", "kabug-at", "sentro sa kabug-at", "timbang", "roof cargo", "load", "center of gravity", "balance", "top-heavy"], "fact": {"tl": "Kapag nakakarga ng mabigat na gamit sa bubong ng dyip, tumataas ang sentro ng bigat nito kaya nagiging mas madaling matumba sa matarik na liko.", "en": "When heavy cargo is loaded on a jeepney's roof, its center of gravity rises, making it easier to tip over on a sharp turn.", "bis": "Kon adunay bug-at nga karga sa atop sa dyip, mosaka ang sentro sa kabug-at niini busa mas dali kining matumba sa hait nga liko."}, "source": "encyclopedia-stable consensus; NRC PS2 (center of gravity / stability)", "generator": "claude-workflow", "reviewed": false},
  {"id": "kalan-clay-stove-combustion-g5", "domain": "MATTER", "topic": "burning firewood in a clay stove releases heat and smoke", "grades": [4, 5, 6], "terms": ["kalan", "pugon", "kahoy na panggatong", "apoy", "pagsunog", "init", "usok", "abo", "combustion", "luwad nga kalan", "sugnod", "kalayo", "kainit", "aso", "clay stove", "firewood", "burning", "combustion", "heat", "smoke", "ash"], "fact": {"tl": "Sa kalan na luwad, ang panggatong na kahoy ay nasusunog at nagiging abo, usok, at init na ginagamit sa pagluluto.", "en": "In a clay stove, firewood burns and changes into ash, smoke, and heat that is used for cooking.", "bis": "Sa kalan nga luwad, ang sugnod nga kahoy masunog ug mahimong abo, aso, ug kainit nga gamiton sa pagluto."}, "source": "encyclopedia-stable consensus; NRC PS1.B (chemical change / combustion)", "generator": "claude-workflow", "reviewed": false},
  {"id": "kakanin-rice-staple-g4", "domain": "LIVING_THINGS", "topic": "kakanin are rice-based snacks; rice as energy food", "grades": [3, 4, 5], "terms": ["kakanin", "bilao", "kanin", "bigas", "malagkit", "karbohidrat", "lakas", "enerhiya", "dahon ng saging", "bibingka", "puto", "kalan-on", "bugas", "pilit", "kusog", "rice cake", "glutinous rice", "carbohydrate", "energy food", "banana leaf"], "fact": {"tl": "Karamihan sa kakanin ay gawa sa bigas o malagkit na kanin, na mayaman sa karbohidrat na nagbibigay sa atin ng lakas.", "en": "Most kakanin are made from rice or glutinous rice, which is rich in carbohydrates that give us energy.", "bis": "Kadaghanan sa kakanin hinimo gikan sa bugas o pilit, nga dato sa karbohidrat nga maghatag kanato ug kusog."}, "source": "encyclopedia-stable consensus; NRC LS1 (food / nutrition)", "generator": "claude-workflow", "reviewed": false},
  {"id": "banana-leaf-wrapper-g5", "domain": "LIVING_THINGS", "topic": "banana leaves as a natural food wrapper", "grades": [4, 5, 6], "terms": ["dahon ng saging", "pambalot", "kakanin", "natural", "nabubulok", "amoy", "lutong-bahay", "dahon", "dahon sa saging", "pamutos", "madunot", "natural nga putos", "banana leaf", "natural wrapper", "biodegradable", "food wrap", "leaf"], "fact": {"tl": "Ginagamit na pambalot ng kakanin ang dahon ng saging dahil malapad ito, natural, at madaling mabulok kaya hindi ito nagiging basurang plastik.", "en": "Banana leaves are used to wrap kakanin because they are wide, natural, and break down easily, so they do not become plastic waste.", "bis": "Gigamit nga pamutos sa kakanin ang dahon sa saging tungod kay halapad kini, natural, ug dali madunot busa dili kini mahimong basura nga plastik."}, "source": "encyclopedia-stable consensus; NRC LS2 (decomposition / materials)", "generator": "claude-workflow", "reviewed": false},
  {"id": "kargador-carrying-loads-force-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "lifting and carrying heavy loads as force and work", "grades": [3, 4, 5], "terms": ["kargador", "porter", "pasan", "pasanin", "magbuhat", "buhat", "bigat", "puwersa", "trabaho", "kusog", "pagdala", "pagpas-an", "alsa", "load", "lift", "carry", "force", "work", "muscle"], "fact": {"tl": "Kapag binubuhat o pinapasan ng isang kargador ang mabigat na sako, gumagamit siya ng puwersa mula sa kanyang mga kalamnan para malabanan ang hila ng grabidad sa bigat nito.", "en": "When a porter lifts or carries a heavy sack, he uses force from his muscles to overcome gravity pulling down on the load's weight.", "bis": "Kon ang kargador mag-alsa o magpas-an ug bug-at nga sako, mogamit siyag kusog gikan sa iyang mga unod aron buntogon ang gravity nga nagbira sa kabug-aton niini."}, "source": "AAAS Benchmarks 4F (force and motion); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kariton-wheels-reduce-friction-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "wheels reduce friction to move loads easily", "grades": [3, 4, 5], "terms": ["kariton", "cart", "gulong", "ligid", "kuliling", "friction", "kuskos", "pwersa", "puwersa", "hila", "tulak", "pagtulak", "wheel", "roll", "ligid-ligid", "bug-at", "pagligid"], "fact": {"tl": "Mas madaling itulak ang kariton dahil ang mga gulong nito ay umiikot at binabawasan ang friction sa lupa, kaya kailangan ng mas kaunting puwersa kaysa sa paghila ng mabigat na bagay.", "en": "A pushcart is easy to move because its rolling wheels reduce friction with the ground, so it takes much less force than dragging a heavy object.", "bis": "Sayon itulod ang kariton kay ang mga ligid niini moligid ug mokunhod sa friction sa yuta, mao nga gamay ra nga kusog ang gikinahanglan kaysa pag-guyod sa bug-at nga butang."}, "source": "AAAS Benchmarks 8B (simple machines); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kite-flight-wind-lift-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "how wind lifts and holds up a kite", "grades": [4, 5, 6], "terms": ["saranggola", "buradol", "kite", "hangin", "ihip", "pataas", "lift", "pwersa", "puwersa", "lipad", "paglipad", "lupad", "paglupad", "wind", "string", "tali", "angat", "nakaharang", "tangkay"], "fact": {"tl": "Lumilipad ang saranggola dahil tinatamaan ito ng umiihip na hangin sa nakatagilid na ibabaw, at ang hangin ay nagtutulak dito pataas habang hawak ito ng tali laban sa grabidad.", "en": "A kite flies because moving wind pushes against its slanted surface, lifting it upward while the string holds it against gravity.", "bis": "Molupad ang buradol kay ang nagahuyop nga hangin moigo sa nagharag niini nga nawong, ug ang hangin motulod niini paibabaw samtang ang pisi nagkupot batok sa gravity."}, "source": "AAAS Benchmarks 4F (force and motion); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "jumping-luksong-tinik-muscles-gravity-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "jumping uses muscle force and gravity pulls you back down", "grades": [3, 4, 5], "terms": ["luksong tinik", "talon", "lukso", "ambak", "paglukso", "pagtalon", "jump", "kalamnan", "binti", "muscle", "grabidad", "gravity", "pababa", "balik", "puwersa", "kusog"], "fact": {"tl": "Kapag lumulukso ka sa luksong-tinik, itinutulak ng malalakas na kalamnan ng iyong mga binti ang katawan mo pataas, ngunit hinihila ka pabalik sa lupa ng grabidad.", "en": "When you leap in luksong-tinik, the strong muscles of your legs push your body upward, but gravity pulls you back down to the ground.", "bis": "Kon molukso ka sa luksong-tinik, ang kusgang unod sa imong mga bitiis motulod sa imong lawas paibabaw, apan ang gravity mobira kanimo balik sa yuta."}, "source": "AAAS Benchmarks 4F (force and motion); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "marbles-collision-transfer-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "colliding marbles transfer motion to one another", "grades": [4, 5, 6], "terms": ["holen", "marble", "marbles", "banggaan", "bangga", "tama", "tinama", "pintik", "galaw", "kilos", "lihok", "collision", "enerhiya", "energy", "ilis", "tugbang", "naigo", "paggalaw", "paglihok"], "fact": {"tl": "Kapag ang isang gumugulong na holen ay tumama sa nakatigil na holen, ipinapasa nito ang ilan sa kanyang galaw, kaya tumitigil o bumabagal ang una habang gumagalaw naman ang tinamaan.", "en": "When a rolling marble hits a still marble, it transfers some of its motion, so the first one stops or slows while the one it struck rolls away.", "bis": "Kon ang nagaligid nga holen moigo sa hunong nga holen, mobalhin niini ang pipila sa lihok niini, mao nga ang nahauna mohunong o mohinay samtang ang naigo moligid palayo."}, "source": "NRC PS2.A (forces and motion); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tumbang-preso-throwing-force-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "a thrown slipper applies force to knock over a can", "grades": [3, 4, 5], "terms": ["tumbang preso", "tsinelas", "pukol", "hagis", "itapon", "ihagis", "bato", "lata", "natumba", "tumba", "throw", "puwersa", "kusog", "tamaan", "pagtumba", "labay", "paglabay"], "fact": {"tl": "Sa tumbang-preso, kapag inihagis mo ang tsinelas at tumama ito sa lata, ang puwersa ng gumagalaw na tsinelas ang nagtutulak at nagpapatumba sa lata.", "en": "In tumbang-preso, when you throw your slipper and it strikes the can, the force of the moving slipper pushes the can over.", "bis": "Sa tumba-tumba, kon ilabay nimo ang tsinelas ug moigo kini sa lata, ang kusog sa nagalihok nga tsinelas maoy motulod ug motumba sa lata."}, "source": "AAAS Benchmarks 4F (force and motion); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "floods-rising-water-safety-g5", "domain": "EARTH_SPACE", "topic": "floods happen when heavy rain water cannot drain away fast enough", "grades": [4, 5, 6], "terms": ["baha", "pagbaha", "flood", "ulan", "malakas na ulan", "tubig", "lobog", "agos", "bagyo", "PAGASA", "rain", "water", "ilog", "umapaw", "drainage", "kanal", "baha-baha", "lunop", "pagtaob"], "fact": {"tl": "Nagkakaroon ng baha kapag napakalakas o napakatagal ng ulan kaya hindi na kayang sipsipin ng lupa o dalhin ng mga kanal at ilog ang dami ng tubig, kaya umaapaw ito sa mababang lugar.", "en": "Floods happen when rain is so heavy or long that the soil, drains, and rivers cannot carry all the water away, so it overflows into low-lying places.", "bis": "Mahitabo ang baha kon ang ulan kusog o dugay kaayo mao nga dili na masuyop sa yuta o madala sa kanal ug suba ang kadaghanon sa tubig, busa moawas kini sa ubos nga mga dapit."}, "source": "DepEd MATATAG Science (weather and natural hazards); PAGASA; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kitchen-safety-heat-hazards-g4", "domain": "MATTER", "topic": "kitchen heat sources can burn and must be handled safely", "grades": [3, 4, 5], "terms": ["kusina", "kitchen", "init", "mainit", "apoy", "kalan", "kawali", "paso", "mapaso", "ingat", "safety", "kaligtasan", "kuryente", "kutsilyo", "tubig na kumukulo", "hazard", "panganib", "laso", "kainit"], "fact": {"tl": "Sa kusina, ang apoy ng kalan, mainit na kawali, at kumukulong tubig ay sapat na mainit para makapaso ng balat, kaya kailangan ng ingat at hindi dapat hawakan ang mainit na bagay nang walang proteksyon.", "en": "In the kitchen, stove flames, hot pans, and boiling water are hot enough to burn skin, so they must be handled with care and never touched without protection.", "bis": "Sa kusina, ang kalayo sa kalan, init nga kaha, ug nagbukal nga tubig init kaayo nga makapaso sa panit, busa kinahanglan ang pag-amping ug dili gayod hikapon ang init nga butang nga walay panalipod."}, "source": "DepEd MATATAG Science (safety and properties of matter); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kuliglig-hand-tractor-plowing-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "a hand tractor uses an engine to do the heavy work of plowing", "grades": [4, 5, 6], "terms": ["kuliglig", "hand tractor", "traktora", "makina", "engine", "araro", "pag-araro", "lupa", "pagtanim", "gasolina", "pwersa", "puwersa", "makinarya", "bukid", "daro", "pagdaro", "humok nga yuta", "makina sa uma"], "fact": {"tl": "Ang kuliglig ay isang hand tractor na may makina na nagbibigay ng malakas na puwersa para hilahin ang araro, kaya mas mabilis at mas magaan ang pagbubungkal ng lupa kaysa sa kamay lang.", "en": "The kuliglig is a hand tractor with an engine that supplies strong force to pull a plow, making it faster and easier to break up soil than by hand alone.", "bis": "Ang kuliglig usa ka hand tractor nga adunay makina nga mohatag ug kusgang puwersa aron guyoron ang daro, mao nga mas paspas ug mas sayon ang pagbungkal sa yuta kaysa kamot lang."}, "source": "AAAS Benchmarks 8B (technology and energy); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "soap-washing-clothes-g4", "domain": "MATTER", "topic": "soap helps water lift grease and dirt off clothes", "grades": [3, 4, 5], "terms": ["labada", "labandera", "sabon", "soap", "labhan", "paglalaba", "dumi", "mantsa", "tubig", "kuskos", "linis", "wash", "laundry", "hugas", "panaptun", "labhanan", "paghugas", "tunaw sa mantika", "buga"], "fact": {"tl": "Kapag naglalaba, ang sabon ang tumutulong na pakawalan ang langis at dumi sa damit dahil hinihigop nito ang dumi at hinahalo ito sa tubig na maaaring banlawan.", "en": "When washing clothes, soap helps loosen oil and dirt from the cloth because it grabs the grime and lets the water carry it away.", "bis": "Kon manglaba, ang sabon motabang sa pagtangtang sa lana ug hugaw gikan sa sanina kay mokupot kini sa buling ug mosagol niini sa tubig nga mahimong banlawan."}, "source": "AAAS Benchmarks 4D (properties of matter); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lechon-roasting-heat-cooking-g5", "domain": "MATTER", "topic": "roasting over fire cooks meat by transferring heat", "grades": [4, 5, 6], "terms": ["lechon", "litson", "ihaw", "pag-ihaw", "baboy", "uling", "apoy", "init", "luto", "pagluto", "roast", "iikot", "rotate", "even", "heat", "balbakwa", "asado", "pagtuyok", "kainit", "tustado"], "fact": {"tl": "Kapag iniihaw ang lechon, ang init mula sa nagbabagang uling ay nagluluto sa karne, at pinapaikot ito nang dahan-dahan para pantay-pantay na maluto ang lahat ng bahagi.", "en": "When a lechon is roasted, heat from the glowing coals cooks the meat, and it is turned slowly so every part cooks evenly.", "bis": "Kon iihawon ang lechon, ang init gikan sa nagbaga nga uling moluto sa karne, ug tuyokon kini hinay-hinay aron managsama nga maluto ang tanang bahin."}, "source": "NRC PS3 (energy and heat transfer); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lighthouse-light-guides-ships-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "a lighthouse shines a strong light to guide ships at night", "grades": [4, 5, 6], "terms": ["parola", "lighthouse", "ilaw", "liwanag", "barko", "dagat", "gabi", "gabay", "light", "beam", "sinag", "kislap", "warning", "babala", "suga", "kahayag", "barko sa dagat", "pasidaan", "sinag sa ilaw"], "fact": {"tl": "Ang parola ay isang mataas na tore na may malakas na ilaw na nakikita mula sa malayo, na gumagabay sa mga barko sa gabi at nagbibigay-babala sa mababatuhang baybayin.", "en": "A lighthouse is a tall tower with a strong light seen from far away that guides ships at night and warns them of rocky shores.", "bis": "Ang parola usa ka taas nga tore nga adunay kusog nga suga nga makita gikan sa layo, nga mogiya sa mga barko sa gabii ug mopasidaan sa batoon nga baybayon."}, "source": "AAAS Benchmarks 4F (light); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "plants-need-water-watering-g3", "domain": "LIVING_THINGS", "topic": "plants need water to grow and stay healthy", "grades": [3, 4, 5], "terms": ["magbubukid", "magsasaka", "dilig", "pagdidilig", "gulay", "halaman", "tubig", "tumubo", "lago", "ugat", "water", "plant", "vegetable", "buhi", "pananom", "patubig", "pagbisbis", "pagtubo", "lunhaw"], "fact": {"tl": "Dinidiligan ng magbubukid ang mga gulay dahil kailangan ng mga halaman ng tubig para mabuhay, lumago, at makagawa ng pagkain sa kanilang mga dahon.", "en": "A farmer waters the vegetables because plants need water to stay alive, grow, and make food in their leaves.", "bis": "Bisbisan sa mag-uuma ang mga utanon kay kinahanglan sa mga tanom ang tubig aron mabuhi, motubo, ug makahimo ug pagkaon sa ilang mga dahon."}, "source": "NRC LS1.C (organization for matter and energy in organisms); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "palay-rice-grain-plant-g4", "domain": "LIVING_THINGS", "topic": "palay is the rice plant whose grains become the rice we eat", "grades": [3, 4, 5], "terms": ["palay", "bigas", "kanin", "rice", "magsasaka", "ani", "anihin", "butil", "sako", "halaman", "grain", "harvest", "tipasi", "humay", "ani", "pananom", "uhay", "pag-ani", "lugas"], "fact": {"tl": "Ang palay ay isang halamang damo na tumutubo sa basang palayan, at ang mga butil nito ang binabayo o binibilad para maging bigas na niluluto nating kanin.", "en": "Palay is a grassy plant that grows in flooded paddies, and its grains are milled to become the rice we cook and eat.", "bis": "Ang humay usa ka tanom nga sagbot nga motubo sa basa nga basakan, ug ang mga lugas niini galingon aron mahimong bugas nga atong lutoon ug kan-on."}, "source": "DepEd MATATAG Science (plants and food); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "plowing-loosens-soil-g4", "domain": "LIVING_THINGS", "topic": "plowing loosens soil so seeds can grow", "grades": [3, 4, 5], "terms": ["pag-araro", "araro", "magsasaka", "lupa", "bungkal", "pagbubungkal", "binhi", "tanim", "kalabaw", "plow", "soil", "loosen", "hangin", "ugat", "daro", "pagdaro", "humok nga yuta", "pananom", "pagtanom"], "fact": {"tl": "Kapag inararo ng magsasaka ang lupa, nabubuwag at lumuluwag ito, kaya mas madaling tumagos ang tubig, hangin, at mga ugat para tumubo ang mga itatanim.", "en": "When a farmer plows the soil, it is broken up and loosened, so water, air, and roots can pass through more easily for the planted crops to grow.", "bis": "Kon daroon sa mag-uuma ang yuta, kini madugmok ug mahumok, mao nga mas sayon mosulod ang tubig, hangin, ug gamot aron motubo ang itanom."}, "source": "NRC LS2 (ecosystems); DepEd MATATAG Science (soil and plants); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "winnowing-rice-wind-separation-g5", "domain": "MATTER", "topic": "winnowing uses moving air to separate light husks from heavy grain", "grades": [4, 5, 6], "terms": ["pagtatahip", "tahip", "bilao", "hangin", "ipa", "butil", "palay", "winnow", "winnowing", "separate", "magaan", "mabigat", "paghihiwalay", "chaff", "tahup", "upa", "lugas", "panahup", "pagbulag", "gaan", "bug-at"], "fact": {"tl": "Sa pagtatahip, itinataas at ipinapailalim ng hangin ang butil sa bilao, kaya tinatangay ng hangin ang magaang ipa habang nahuhulog pabalik ang mas mabigat na butil ng palay.", "en": "In winnowing, grain is tossed in a flat tray so moving air blows away the light husks while the heavier rice grains fall back down.", "bis": "Sa pagtahup, iitsa ang lugas sa nigo aron ang naglihok nga hangin mopalid sa gaan nga upa samtang ang mas bug-at nga lugas sa humay mahulog balik."}, "source": "AAAS Benchmarks 4D (separating mixtures by properties); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "taho-soybean-curd-g4", "domain": "MATTER", "topic": "taho is a soft curd made from soybeans", "grades": [3, 4, 5], "terms": ["taho", "magtataho", "toyo", "soybean", "soybeans", "utaw", "gawgaw", "arnibal", "sago", "kurd", "curd", "gata ng toyo", "soy", "pagkurd", "malambot", "sabaw", "tofu", "soya"], "fact": {"tl": "Ang taho ay isang malambot na pagkain na gawa sa giniling na soybeans na pinakuluan, sinala, at pinaltik para mamuo bilang malambot na kurd na sinasamahan ng arnibal at sago.", "en": "Taho is a soft food made from ground soybeans that are boiled, strained, and set into a tender curd, then served with syrup and sago.", "bis": "Ang taho usa ka humok nga pagkaon nga hinimo gikan sa giniling nga soybeans nga gipabukal, gisala, ug gipagahi-gahi aron mahimong humok nga curd, dayon dugangan ug arnibal ug sago."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bagoong-fermentation-preservation-g6", "domain": "LIVING_THINGS", "topic": "bagoong is fish or shrimp preserved by salting and fermentation", "grades": [5, 6, 7], "terms": ["bagoong", "alamang", "isda", "asin", "asinan", "ferment", "fermentation", "pagbuburo", "pampreserba", "preserve", "panis", "bacteria", "microbe", "guinamos", "ginamos", "asin sa isda", "pagpreserba", "buro", "halok"], "fact": {"tl": "Ang bagoong ay gawa sa maliit na isda o alamang na hinalo sa maraming asin at hinayaang mag-ferment, kung saan tumutulong ang mga mikrobyo at asin para hindi mabilis na mapanis at lumalim ang lasa.", "en": "Bagoong is made from small fish or shrimp mixed with plenty of salt and left to ferment, where microbes and salt keep it from spoiling quickly while deepening its flavor.", "bis": "Ang ginamos hinimo gikan sa gagmay nga isda o alamang nga sinagol sa daghang asin ug gipasagdang mo-ferment, diin ang mga microbe ug asin motabang aron dili dali madunot ug molalom ang lami."}, "source": "AAAS Benchmarks 5C (microorganisms); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bamboo-fast-growing-grass-g5", "domain": "LIVING_THINGS", "topic": "bamboo is a tall, fast-growing grass that is strong and useful", "grades": [4, 5, 6], "terms": ["kawayan", "bamboo", "damo", "halaman", "matibay", "matikas", "biyas", "buho", "grass", "strong", "hollow", "tumubo nang mabilis", "kahoy", "kawayan", "kugon", "humok", "lig-on", "pananom", "guhot", "tubo"], "fact": {"tl": "Ang kawayan ay isang napakataas na uri ng damo na may guwang na sanga, isa sa pinakamabilis tumubo na halaman, at matibay kaya ginagamit sa bahay, muwebles, at mga gamit.", "en": "Bamboo is a very tall kind of grass with hollow stems, one of the fastest-growing plants, and so strong that it is used for houses, furniture, and tools.", "bis": "Ang kawayan usa ka taas kaayo nga matang sa sagbot nga adunay bangag nga punoan, usa sa labing paspas motubo nga tanom, ug lig-on kaayo busa gigamit sa balay, muwebles, ug mga galamiton."}, "source": "AAAS Benchmarks 5A (diversity of life); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "walis-tingting-coconut-broom-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "a walis tingting is made from coconut leaf midribs and sweeps by friction", "grades": [3, 4, 5], "terms": ["walis", "walis tingting", "tingting", "broom", "niyog", "dahon ng niyog", "pamahid", "walis-walis", "sweep", "sweeping", "kuskos", "friction", "lupa", "basura", "silhig", "silhig lubi", "pagsilhig", "pagwalis", "lubi", "kalibun"], "fact": {"tl": "Ang walis tingting ay gawa sa pinatuyong tingting o gitna ng mga dahon ng niyog, at kapag iwinawalis ito, ang kuskos ng dulo nito sa lupa ang humahatak sa mga dahon at basura.", "en": "A walis tingting is made from the dried midribs of coconut leaves, and when swept, the friction of its tips against the ground drags away leaves and litter.", "bis": "Ang silhig nga tingting hinimo gikan sa giuga nga tingting o tunga sa mga dahon sa lubi, ug kon isilhig kini, ang kuskos sa tumoy niini sa yuta maoy mokuha sa mga dahon ug basura."}, "source": "AAAS Benchmarks 4F (friction); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "electric-train-rails-electricity-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "MRT and LRT trains run on steel rails powered by electricity", "grades": [5, 6, 7], "terms": ["tren", "MRT", "LRT", "train", "riles", "rail", "kuryente", "electricity", "elektrisidad", "gulong", "bakal", "elevated", "nakaangat", "track", "byahe", "tren sa elektrisidad", "kuryente sa tren", "motor", "agianan sa bakal"], "fact": {"tl": "Ang MRT at LRT ay mga tren na tumatakbo sa magkapares na bakal na riles at pinapaandar ng kuryente, kaya nakakagalaw ang mga ito nang mabilis at tahimik kahit walang gasolina.", "en": "The MRT and LRT are trains that run on paired steel rails and are powered by electricity, letting them move fast and quietly without using gasoline.", "bis": "Ang MRT ug LRT mga tren nga modagan sa pares nga puthaw nga riles ug gipalihok sa kuryente, mao nga makalihok kini nga paspas ug hilom bisan walay gasolina."}, "source": "AAAS Benchmarks 8C (energy sources and use); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fishing-net-catches-fish-g4", "domain": "LIVING_THINGS", "topic": "fishers use nets to catch many fish from the sea", "grades": [3, 4, 5], "terms": ["mangingisda", "magdaragat", "lambat", "net", "isda", "huli", "pangingisda", "dagat", "fish", "fishing", "buhol", "tahi ng lambat", "bangka", "mananagat", "pukot", "isda sa dagat", "pangisda", "pagpukot", "lawalawa"], "fact": {"tl": "Gumagamit ang mga mangingisda ng lambat na may maliliit na butas para mahuli ang mga isda, na nasasalo sa lambat habang dumadaloy ang tubig palabas dito.", "en": "Fishers use nets with small holes to catch fish, which are trapped in the net while the water flows out through the openings.", "bis": "Mogamit ang mga mananagat ug pukot nga adunay gagmay nga bangag aron makuha ang mga isda, nga malit-agan sa pukot samtang ang tubig moagos pagawas niini."}, "source": "DepEd MATATAG Science (animals and human use of resources); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "owner-type-jeep-object-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "owner-type jeep engine and motion", "grades": [4, 5, 6], "terms": ["owner-type jeep", "owner jeep", "dyip", "jeep", "makina", "gasolina", "diesel", "gulong", "tumatakbo", "makina sa jeep", "nagdagan", "ligid", "sasakyan", "sakyanan", "engine", "fuel", "wheels", "vehicle"], "fact": {"tl": "Ang owner-type jeep ay isang maliit na sasakyan na umaandar dahil ang makina nito ay nagsusunog ng gasolina o diesel para paikutin ang mga gulong.", "en": "An owner-type jeep is a small vehicle that moves because its engine burns gasoline or diesel to turn its wheels.", "bis": "Ang owner-type jeep usa ka gamay nga sakyanan nga modagan tungod kay ang makina niini nagasunog ug gasolina o diesel aron tuyokon ang mga ligid."}, "source": "encyclopedia-stable consensus; DepEd G5 force and motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "padyak-pedicab-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "padyak pedaling and force", "grades": [4, 5, 6], "terms": ["padyak", "trisikad", "pedicab", "tinatadyakan", "pedal", "bisikleta", "kadena", "gulong", "lakas", "puwersa", "naghahakot", "sako", "gitamak", "chain", "wheel", "force", "human power"], "fact": {"tl": "Ang padyak ay pinatatakbo ng lakas ng tao—kapag tinatadyakan ang pedal, naililipat ng kadena ang puwersa sa gulong para gumalaw kahit may dalang mabibigat na sako.", "en": "A padyak is powered by human strength—pushing the pedals sends force through a chain to the wheel, moving it even when loaded with heavy sacks.", "bis": "Ang padyak gipalihok sa kusog sa tawo—kon tamakon ang pedal, ang kadena magbalhin sa puwersa ngadto sa ligid aron molihok bisan og bug-at ang gikarga nga mga sako."}, "source": "encyclopedia-stable consensus; DepEd G5 force and motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "palay-thresher-manual-g4", "domain": "MATTER", "topic": "threshing separates grain from straw", "grades": [3, 4, 5], "terms": ["giik", "paggiik", "palay", "thresher", "butil", "dayami", "uhay", "naghihiwalay", "binhi", "giniik", "giuk", "lugas", "dagami", "uhot", "gilain", "thresh", "grain", "straw", "rice"], "fact": {"tl": "Sa paggiik, hinahampas o iginugulong ang palay para mahiwalay ang mga butil mula sa uhay at dayami—isang paraan ng paghihiwalay ng halo gamit ang puwersa.", "en": "In threshing, rice stalks are beaten or rolled so the grains separate from the straw—a way of separating a mixture using force.", "bis": "Sa paggiik, ginabunalan o giligid ang humay aron mabulag ang mga lugas gikan sa uhay ug dagami—usa ka paagi sa pagbulag sa sinagol pinaagi sa puwersa."}, "source": "encyclopedia-stable consensus; DepEd G4 separating mixtures", "generator": "claude-workflow", "reviewed": false},
  {"id": "paraw-sailing-wind-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "paraw sailboat moved by wind", "grades": [4, 5, 6], "terms": ["paraw", "bangkang may layag", "layag", "hangin", "naglalayag", "regatta", "outrigger", "katig", "tubig", "naitutulak", "puwersa ng hangin", "milalayag", "gitulod", "sailboat", "sail", "wind", "outrigger", "Iloilo"], "fact": {"tl": "Ang paraw ay tradisyonal na bangkang Pilipino na may layag at katig, at gumagalaw ito kapag tinutulak ng hangin ang malalaki nitong layag.", "en": "The paraw is a traditional Filipino sailboat with outriggers, and it moves when the wind pushes against its large sails.", "bis": "Ang paraw maoy tradisyonal nga sakayan sa Pilipinas nga may layag ug katig, ug molihok kini kon ang hangin motulod sa dagkong mga layag niini."}, "source": "encyclopedia-stable consensus; DepEd G5 force and motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "passenger-jeepney-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "jeepney public transport vehicle", "grades": [4, 5, 6], "terms": ["dyipni", "jeepney", "pampasaherong dyip", "sasakyan", "makina", "diesel", "gulong", "pasahero", "tumatakbo", "ruta", "naghahatid", "dyip", "sakyanan", "ligid", "engine", "passengers", "wheels"], "fact": {"tl": "Ang jeepney ay isang pampasaherong sasakyan sa Pilipinas na umaandar gamit ang makinang diesel na nagpapaikot sa mga gulong para makapaghatid ng maraming tao.", "en": "The jeepney is a Filipino passenger vehicle that runs on a diesel engine, which turns the wheels to carry many people along a route.", "bis": "Ang jeepney usa ka pampasaherong sakyanan sa Pilipinas nga modagan gamit ang makinang diesel nga magtuyok sa mga ligid aron makahatod ug daghang tawo."}, "source": "encyclopedia-stable consensus; DepEd G5 force and motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "playground-safety-rules-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "playground safety and forces", "grades": [3, 4, 5], "terms": ["palaruan", "playground", "kaligtasan", "patakaran", "swing", "duyan", "slide", "bumagsak", "puwersa", "ingat", "hawak", "mahulog", "kaluwasan", "lagda", "duwa", "mokupot", "amping", "safety", "rules", "fall", "force"], "fact": {"tl": "Mahalaga ang mga patakaran sa palaruan dahil ang mabilis na galaw at pagbagsak ay may malakas na puwersa na maaaring makasakit kapag hindi tayo nag-iingat at humawak nang maigi.", "en": "Playground rules matter because fast motion and falls carry strong forces that can hurt us if we do not stay careful and hold on tightly.", "bis": "Importante ang mga lagda sa duwaanan kay ang paspas nga lihok ug pagkahulog adunay kusgang puwersa nga makasakit kanato kon dili kita mag-amping ug mokupot ug hugot."}, "source": "encyclopedia-stable consensus; DepEd G4 force and motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "potter-at-wheel-g5", "domain": "MATTER", "topic": "pottery shaping and firing clay", "grades": [4, 5, 6], "terms": ["palayok", "magpapalayok", "luwad", "putik", "potter", "wheel", "umiikot", "hinuhubog", "sinunog", "tigas", "lalagyan", "yutang kulonon", "lapok", "giumol", "gisunog", "gahi", "kolon", "clay", "fired", "harden", "pottery"], "fact": {"tl": "Hinuhubog ng magpapalayok ang basa at malambot na luwad habang umiikot ang gulong, at kapag sinunog ito sa init, tumitigas ito at nagiging matibay na palayok.", "en": "A potter shapes wet, soft clay as the wheel spins, and when it is fired in heat the clay hardens into a strong pot.", "bis": "Giumol sa magkukulon ang basa ug humok nga yutang kulonon samtang nagtuyok ang ligid, ug kon sunogon kini sa kainit, mogahi kini ug mahimong lig-on nga kolon."}, "source": "encyclopedia-stable consensus; DepEd G5 changes in materials", "generator": "claude-workflow", "reviewed": false},
  {"id": "pumpboat-motor-banca-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "pumpboat floating and engine", "grades": [4, 5, 6], "terms": ["pumpboat", "bangka", "banca", "lumulutang", "katig", "makina", "motor", "dagat", "naglalayag", "puwersa", "tubig", "lutaw", "boat", "float", "outrigger", "engine", "sea"], "fact": {"tl": "Ang pumpboat ay isang motorized na bangkang may katig na lumulutang dahil mas magaan ito kaysa tubig, at ang makina nito ang nagtutulak para gumalaw.", "en": "A pumpboat is a motorized outrigger boat that floats because it is lighter than water, and its engine pushes it forward to move.", "bis": "Ang pumpboat maoy motorisadong sakayan nga may katig nga molutaw tungod kay mas gaan kini kaysa tubig, ug ang makina niini maoy motulod aron molihok."}, "source": "encyclopedia-stable consensus; DepEd G5 force and motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "rice-farming-plowing-carabao-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "carabao plowing and pulling force", "grades": [3, 4, 5], "terms": ["kalabaw", "carabao", "araro", "pag-aararo", "bukid", "palayan", "humay", "hinihila", "puwersa", "lakas", "magsasaka", "putik", "kabaw", "daro", "giguyod", "kusog", "uma", "plow", "pull", "force", "field", "farmer"], "fact": {"tl": "Ang kalabaw ay matibay na hayop na ginagamit sa pag-aararo dahil malakas nitong nahihila ang araro para baligtarin ang putik bago magtanim ng palay.", "en": "The carabao is a strong animal used for plowing because it can pull the plow with great force to turn the mud before planting rice.", "bis": "Ang kabaw maoy kusgan nga mananap nga gigamit sa pagdaro kay kusganon niining maguyod ang daro aron balihon ang lapok una magtanom ug humay."}, "source": "encyclopedia-stable consensus; DepEd G4 force and motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "rice-mill-kiskisan-g5", "domain": "MATTER", "topic": "rice milling removes the husk", "grades": [4, 5, 6], "terms": ["kiskisan", "rice mill", "palay", "bigas", "ipa", "balat", "binayo", "naghihiwalay", "makina", "giniling", "humay", "bugas", "tahop", "panit", "gilain", "husk", "grain", "separate", "milling"], "fact": {"tl": "Sa kiskisan, tinatanggal ng makina ang matigas na balat o ipa ng palay para maging puting bigas na kakainin natin.", "en": "In a rice mill, the machine removes the hard husk from the palay so it becomes the white rice we eat.", "bis": "Sa kiskisan, ang makina magtangtang sa gahi nga panit o tahop sa humay aron mahimong puti nga bugas nga atong kan-on."}, "source": "encyclopedia-stable consensus; DepEd G5 separating mixtures", "generator": "claude-workflow", "reviewed": false},
  {"id": "road-safety-signs-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "road signs and stopping vehicles", "grades": [3, 4, 5], "terms": ["road sign", "karatula", "kaligtasan sa kalsada", "stop", "tigil", "preno", "huminto", "bilis", "sasakyan", "puwersa", "tumawid", "ingat", "kalsada", "mohunong", "paspas", "amping", "dalan", "brake", "speed", "safety", "cross"], "fact": {"tl": "Tumutulong ang mga road sign na manatiling ligtas ang lahat dahil sinasabi nito kung kailan dapat huminto o magpabagal ang mga sasakyan na mahirap pigilan kapag mabilis.", "en": "Road signs help keep everyone safe by telling drivers when to stop or slow down, because fast-moving vehicles are hard to stop quickly.", "bis": "Ang mga road sign motabang nga maluwas ang tanan kay magsulti kini kanus-a mohunong o mohinay ang mga sakyanan nga lisod pahunongon kon paspas."}, "source": "encyclopedia-stable consensus; DepEd G4 force and motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "rolling-pandesal-dough-g5", "domain": "LIVING_THINGS", "topic": "yeast makes bread dough rise", "grades": [4, 5, 6], "terms": ["pandesal", "masa", "lebadura", "yeast", "umaalsa", "lumalaki", "harina", "tinapay", "hinuhulma", "fermentation", "mosaka", "modako", "pan", "dough", "rise", "ferment", "bread", "flour"], "fact": {"tl": "Sa paggawa ng pandesal, hinuhulma ang masa na may lebadura—isang maliit na fungi na bumubuga ng gas para umalsa at lumaki ang tinapay.", "en": "When making pandesal, dough is shaped with yeast—a tiny fungus that gives off gas to make the bread rise and grow bigger.", "bis": "Sa paghimo ug pandesal, giumol ang masa nga may lebadura—gamay nga fungi nga mobuga ug gas aron mosaka ug modako ang tinapay."}, "source": "encyclopedia-stable consensus; DepEd G5 living things", "generator": "claude-workflow", "reviewed": false},
  {"id": "rooster-cockfight-handler-g4", "domain": "LIVING_THINGS", "topic": "rooster male chicken traits", "grades": [3, 4, 5], "terms": ["tandang", "manok", "rooster", "tuka", "palong", "balahibo", "tumitilaok", "lalaki", "hayop", "ibon", "pakpak", "sunoy", "balhibo", "motuktugaok", "comb", "crow", "feathers", "male", "chicken", "bird"], "fact": {"tl": "Ang tandang ay lalaking manok na may makulay na palong sa ulo at sikat sa malakas nitong pagtilaok lalo na tuwing umaga.", "en": "A rooster is a male chicken with a colorful comb on its head, well known for its loud crowing, especially in the morning.", "bis": "Ang sunoy maoy laki nga manok nga may bulokon nga palong sa ulo ug ila tungod sa kusog niini nga pagtuktugaok ilabi na sa buntag."}, "source": "encyclopedia-stable consensus; DepEd G4 animals", "generator": "claude-workflow", "reviewed": false},
  {"id": "roro-ferry-floating-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "RoRo ferry floats and carries vehicles", "grades": [4, 5, 6], "terms": ["roro", "ferry", "barko", "lumulutang", "sasakyan", "dagat", "bakal", "buoyancy", "tubig", "naglalayag", "bigat", "naglululan", "lutaw", "puthaw", "sakyanan", "ship", "float", "vehicles", "sea"], "fact": {"tl": "Ang RoRo ferry ay malaking barkong bakal na lumulutang dahil itinutulak ito pataas ng tubig, kaya nakakapagdala ito ng mga sasakyan tawid-dagat.", "en": "A RoRo ferry is a large steel ship that floats because the water pushes it up, letting it carry vehicles across the sea.", "bis": "Ang RoRo ferry maoy dakong barko nga puthaw nga molutaw tungod kay gitulod kini pataas sa tubig, mao nga makadala kini ug mga sakyanan tabok sa dagat."}, "source": "encyclopedia-stable consensus; DepEd G5 buoyancy and force", "generator": "claude-workflow", "reviewed": false},
  {"id": "salt-bed-harvest-evaporation-g5", "domain": "MATTER", "topic": "sea salt made by evaporation", "grades": [4, 5, 6], "terms": ["asin", "asinan", "salt bed", "tubig-dagat", "sumingaw", "init ng araw", "kristal", "natitira", "evaporation", "anihan", "dagat", "mosingaw", "init sa adlaw", "seawater", "evaporate", "sun", "crystals", "harvest"], "fact": {"tl": "Ang asin ay nakukuha sa pamamagitan ng pagpapasingaw ng tubig-dagat sa init ng araw sa mga asinan, na nag-iiwan ng mga puting kristal ng asin.", "en": "Salt is made by letting seawater evaporate in the sun on salt beds, which leaves behind white crystals of salt.", "bis": "Ang asin makuha pinaagi sa pagpasingaw sa tubig-dagat ilalom sa init sa adlaw diha sa asinan, nga magbilin ug puti nga mga kristal sa asin."}, "source": "encyclopedia-stable consensus; DepEd G5 evaporation and mixtures", "generator": "claude-workflow", "reviewed": false},
  {"id": "sieve-strainer-g4", "domain": "MATTER", "topic": "sieving separates by particle size", "grades": [3, 4, 5], "terms": ["salaan", "sala", "sieve", "strainer", "naghihiwalay", "butil", "maliit", "malaki", "butas", "halo", "sinasala", "ayagan", "gilain", "lusot", "lungag", "separate", "size", "holes", "mixture"], "fact": {"tl": "Ang salaan ay may maliliit na butas na nagpapadaan sa maliliit na bagay ngunit humaharang sa malalaki, kaya nakakapaghiwalay ito ng halo ayon sa laki.", "en": "A sieve has tiny holes that let small bits pass through but block bigger ones, so it can separate a mixture by size.", "bis": "Ang ayagan adunay gagmay nga mga lungag nga magpalusot sa gagmay nga butang apan mag-ali sa dagko, mao nga makabulag kini ug sinagol sumala sa gidak-on."}, "source": "encyclopedia-stable consensus; DepEd G4 separating mixtures", "generator": "claude-workflow", "reviewed": false},
  {"id": "sinigang-simmering-pot-g4", "domain": "MATTER", "topic": "boiling and simmering water", "grades": [3, 4, 5], "terms": ["sinigang", "kumukulo", "pinapakuluan", "init", "singaw", "kaldero", "nagbukal", "naglat-ang", "nagbukal nga tubig", "alisngaw", "boiling", "simmering", "steam", "heat", "pot"], "fact": {"tl": "Kapag pinapakuluan ang sabaw ng sinigang, umiinit ito hanggang lumitaw ang mga bula at singaw, na tanda na ang tubig ay nagiging gas.", "en": "When sinigang broth is boiled, it heats until bubbles and steam appear, a sign that some of the water is turning into gas.", "bis": "Kon pakuluon ang sabaw sa sinigang, moinit kini hangtod motungha ang mga bula ug alisngaw, timaan nga ang tubig nahimong gas."}, "source": "encyclopedia-stable consensus; NRC PS3 (energy/heat)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sorbetes-cart-cold-g4", "domain": "MATTER", "topic": "keeping ice cream frozen", "grades": [3, 4, 5], "terms": ["sorbetes", "dirty ice cream", "malamig", "yelo", "natutunaw", "lalagyan", "init", "bugnaw", "matunaw", "natunaw", "ice cream", "melt", "cold", "frozen", "insulation"], "fact": {"tl": "Itinatago ng sorbetero ang sorbetes sa lalagyang may yelo at asin upang manatiling malamig at hindi agad matunaw sa init.", "en": "The sorbetes vendor keeps the ice cream in a tub packed with ice and salt so it stays cold and does not quickly melt in the heat.", "bis": "Gitipigan sa tindero ang sorbetes sa sudlanan nga adunay yelo ug asin aron magpabilin kining bugnaw ug dili dali matunaw sa kainit."}, "source": "encyclopedia-stable consensus; NRC PS1 (states of matter)", "generator": "claude-workflow", "reviewed": false},
  {"id": "street-basketball-shot-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "gravity and projectile motion", "grades": [4, 5, 6], "terms": ["basketball", "bola", "shoot", "tira", "lambong", "gravidad", "bumabagsak", "tumatalbog", "grabidad", "nahulog", "naglukso", "nagtumbo", "ball", "gravity", "arc", "bounce", "throw"], "fact": {"tl": "Kapag itinapon ang bola sa basketball, hinihila ito pababa ng gravity kaya bumababa ito sa hugis-arko pabalik sa lupa.", "en": "When a basketball is thrown, gravity pulls it down so it follows a curved arc back toward the ground.", "bis": "Kon ilabay ang bola sa basketball, gibira kini paubos sa gravity mao nga moagi kini sa korbado nga arko balik sa yuta."}, "source": "NRC PS2.B (gravity); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "street-sweeper-broom-friction-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "friction sweeping dirt", "grades": [3, 4, 5], "terms": ["walis", "tinting", "nagwawalis", "basura", "kalsada", "kuskos", "pwersa", "nanilhig", "silhig", "naglimpyo", "broom", "sweep", "friction", "dirt", "street"], "fact": {"tl": "Kapag nagwawalis sa kalsada, kinakaladkad ng dulo ng walis ang basura dahil sa kuskusan o friction sa pagitan ng tinting at lupa.", "en": "When sweeping the street, the broom drags the dirt along because of friction between its bristles and the ground.", "bis": "Kon manilhig sa dalan, gibira sa tumoy sa silhig ang basura tungod sa friction o panagkuskos tali sa silhig ug sa yuta."}, "source": "NRC PS2 (forces/friction); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sugar-cane-loading-g5", "domain": "LIVING_THINGS", "topic": "sugarcane plant", "grades": [4, 5, 6], "terms": ["tubo", "asukal", "katas", "tanim", "tangkay", "halaman", "tubo nga tanom", "kalamay", "duga", "tinubo", "lagkaw", "sugarcane", "sugar", "stalk", "juice", "plant"], "fact": {"tl": "Ang tubo ay isang matangkad na damo na nag-iimbak ng matamis na katas sa loob ng tangkay nito, at mula rito ginagawa ang asukal.", "en": "Sugarcane is a tall grass that stores sweet juice inside its stalk, and sugar is made from that juice.", "bis": "Ang tubo usa ka taas nga sagbot nga nagtipig ug tam-is nga duga sulod sa lawas niini, ug gikan niini gihimo ang asukal."}, "source": "encyclopedia-stable consensus; NRC LS1 (plants)", "generator": "claude-workflow", "reviewed": false},
  {"id": "tartanilla-horse-pull-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "animal pulling force", "grades": [3, 4, 5], "terms": ["tartanilla", "kalesa", "kabayo", "humihila", "karwahe", "pwersa", "gumugulong", "kabayo nga nagbira", "karusa", "nagbira", "nagguyod", "carriage", "horse", "pull", "force", "wheels"], "fact": {"tl": "Gumagalaw ang tartanilla dahil hinihila ng kabayo ang karwahe, kaya ang pwersa ng hayop ang nagpapagulong sa mga gulong.", "en": "A tartanilla carriage moves because the horse pulls it, so the animal's force makes the wheels roll forward.", "bis": "Mogalaw ang tartanilla tungod kay gibira sa kabayo ang karwahe, mao nga ang kusog sa hayop maoy nagpaligid sa mga ligid."}, "source": "NRC PS2 (forces and motion); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tinapa-smoking-preserve-g5", "domain": "MATTER", "topic": "smoking to preserve fish", "grades": [5, 6, 7], "terms": ["tinapa", "usok", "isda", "pinatuyo", "pagpapaaso", "preserba", "nabubulok", "aso", "gipa-aso", "gipausok", "nahimong tinapa", "pagpreserba", "smoked fish", "smoke", "preserve", "dry", "spoil"], "fact": {"tl": "Ginagawang tinapa ang isda sa pamamagitan ng pagpapaaso at bahagyang pagpapatuyo, na nagpapabagal sa pagbubulok kaya tumatagal ito.", "en": "Fish is made into tinapa by smoking and partly drying it, which slows down spoilage so it lasts longer.", "bis": "Gihimong tinapa ang isda pinaagi sa pagpa-aso ug gamay nga pagpauga, nga nagpahinay sa pagkadunot busa mas modugay kini."}, "source": "encyclopedia-stable consensus; NRC LS (decomposers/preservation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "tinapay-yeast-bread-g5", "domain": "LIVING_THINGS", "topic": "yeast rising bread", "grades": [5, 6, 7], "terms": ["tinapay", "pampaalsa", "lebadura", "umaalsa", "harina", "masa", "gas", "yeast", "namuga", "nagtubo ang masa", "humuhulma", "bread", "yeast", "rise", "dough", "gas"], "fact": {"tl": "Umaalsa ang masa ng tinapay dahil ang lebadura ay isang maliit na buhay na bagay na naglalabas ng gas na nagpapaluwang sa masa.", "en": "Bread dough rises because yeast is a tiny living thing that releases gas, puffing up the dough.", "bis": "Mobukol ang masa sa tinapay tungod kay ang lebadura usa ka gamay nga buhing butang nga nagpagawas ug gas nga nagpaluag sa masa."}, "source": "encyclopedia-stable consensus; NRC LS1 (living things/microbes)", "generator": "claude-workflow", "reviewed": false},
  {"id": "trisikad-pedal-machine-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "pedals and simple machines", "grades": [4, 5, 6], "terms": ["trisikad", "padyak", "pedicab", "tumatapak", "pedal", "kadena", "gulong", "pwersa", "gitamak", "naglihok", "ligid", "pedal", "chain", "wheel", "pedicab", "force"], "fact": {"tl": "Gumagalaw ang trisikad kapag tinapakan ang pedal, na nagpapaikot sa kadena at gulong para mas madaling iabante ang sasakyan.", "en": "A trisikad moves when you push the pedals, which turn the chain and wheel to make the vehicle easier to move forward.", "bis": "Mogalaw ang trisikad kon tamakan ang pedal, nga nagtuyok sa kadena ug ligid aron mas sayon nga mapaabante ang sakyanan."}, "source": "encyclopedia-stable consensus; NRC PS2 / ETS (simple machines)", "generator": "claude-workflow", "reviewed": false},
  {"id": "tubero-water-pressure-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "water pressure in pipes", "grades": [5, 6, 7], "terms": ["tubero", "tubo", "tubig", "presyon", "gripo", "dumadaloy", "plumber", "pipe", "nag-agas", "presyur", "nagdagayday", "tubod", "water", "pipe", "pressure", "flow", "plumber"], "fact": {"tl": "Dumadaloy ang tubig sa mga tubo dahil sa presyon na nagtutulak dito, kaya kapag binuksan ang gripo ay lumalabas ang tubig.", "en": "Water flows through pipes because pressure pushes it along, so when you open a faucet the water comes out.", "bis": "Nagdagayday ang tubig sa mga tubo tungod sa presyon nga nagtukmod niini, mao nga kon ablihan ang gripo mogawas ang tubig."}, "source": "NRC PS2 (forces); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "carabao-mud-wallow-g4", "domain": "LIVING_THINGS", "topic": "carabao cooling in mud", "grades": [3, 4, 5], "terms": ["kalabaw", "putik", "lumulublob", "lumalamig", "init", "balahibo", "hayop", "carabao", "kabaw", "naglunang", "lapok", "naglubog", "nagpabugnaw", "buffalo", "mud", "wallow", "cool", "heat"], "fact": {"tl": "Lumulublob ang kalabaw sa putik upang palamigin ang katawan nito at maprotektahan ang balat mula sa init at mga insekto.", "en": "The carabao wallows in mud to cool its body and protect its skin from the heat and biting insects.", "bis": "Naglunang ang kabaw sa lapok aron pabugnawon ang lawas niini ug panalipdan ang panit gikan sa kainit ug mga insekto."}, "source": "encyclopedia-stable consensus; NRC LS1 (structure/behavior for survival)", "generator": "claude-workflow", "reviewed": false},
  {"id": "skylab-load-balance-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "balance and center of gravity", "grades": [5, 6, 7], "terms": ["skylab", "habal-habal", "kargada", "balanse", "timbang", "bigat", "gumagalaw", "nahuhulog", "panimbang", "kabug-aton", "patas", "nawala sa timbang", "load", "balance", "weight", "center of gravity", "motorcycle"], "fact": {"tl": "Kailangang patas ang pagkakaayos ng kargada sa skylab nang hindi mawala sa balanse, dahil kung mabigat ang isang gilid, madali itong tumagilid.", "en": "The load on a skylab must be arranged evenly to keep its balance, because if one side is too heavy it easily tips over.", "bis": "Kinahanglan patas ang pagkahan-ay sa karga sa skylab aron dili mawad-an sa balanse, kay kon bug-at ang usa ka kilid dali kining motakilid."}, "source": "encyclopedia-stable consensus; NRC PS2 (forces, stability)", "generator": "claude-workflow", "reviewed": false},
  {"id": "balloon-g4", "domain": "MATTER", "topic": "balloon air gas", "grades": [3, 4, 5], "terms": ["balloon", "lobo", "globo", "hangin", "air", "gas", "umiimpla", "inflate", "humihinga sa loob", "naglapad", "moinat", "stretch", "static", "elastiko", "rubber goma"], "fact": {"tl": "Kapag hinihipan ang lobo, napupuno ito ng hangin na isang gas, at ang goma nito ay naglalapad para tumanggap ng dami ng hangin.", "en": "When you blow into a balloon, it fills with air, which is a gas, and its rubber stretches to hold all that air.", "bis": "Kung huyopan ang lobo, mapuno kini ug hangin nga usa ka gas, ug ang goma niini moinat aron makasulod ang tanan nga hangin."}, "source": "NRC PS1.A; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mountain-g5", "domain": "EARTH_SPACE", "topic": "mountain landform", "grades": [4, 5, 6], "terms": ["mountain", "bundok", "bukid", "landform", "anyong lupa", "porma sa yuta", "mataas", "tall", "tuktok", "peak", "summit", "plate tectonics", "Mount Apo", "lamig sa taas", "rocky"], "fact": {"tl": "Ang bundok ay isang napakataas na anyong lupa na may matarik na gilid, at maraming nabuo nang mga milyong taon dahil sa pagbangga ng malalaking bahagi ng balat ng lupa.", "en": "A mountain is a very tall landform with steep sides, and many formed over millions of years when large pieces of Earth's crust pushed together.", "bis": "Ang bukid usa ka taas kaayo nga porma sa yuta nga adunay tarik nga kilid, ug daghan ang naporma sulod sa minilyon ka tuig tungod sa pagdinasmagay sa dagkong bahin sa panit sa yuta."}, "source": "NRC ESS2.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rainbow-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "rainbow light", "grades": [4, 5, 6], "terms": ["rainbow", "bahaghari", "balangaw", "liwanag", "kahayag", "light", "kulay", "kolor", "colors", "sikat ng araw", "sunlight", "patak ng ulan", "tulo sa ulan", "raindrops", "nasasalamin", "refraction", "spektrum", "pito ang kulay"], "fact": {"tl": "Ang bahaghari ay nabubuo kapag ang sikat ng araw ay dumadaan sa mga patak ng ulan, na humahati sa puting liwanag sa iba't ibang kulay.", "en": "A rainbow forms when sunlight passes through raindrops, which split the white light into its different colors.", "bis": "Ang balangaw maporma kung ang kahayag sa adlaw moagi sa mga tulo sa ulan, nga magbahin sa puti nga kahayag ngadto sa lain-laing kolor."}, "source": "NRC PS4.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "river-g5", "domain": "EARTH_SPACE", "topic": "river water flow", "grades": [4, 5, 6], "terms": ["river", "ilog", "suba", "tubig", "water", "umaagos", "moagos", "flows", "dagat", "sea", "bukal", "source", "mataas pababa", "downhill", "Cagayan River", "tubig-tabang", "freshwater"], "fact": {"tl": "Ang ilog ay isang umaagos na anyong tubig na palaging dumadaloy mula sa mataas na lugar pababa patungo sa lawa o dagat.", "en": "A river is a flowing body of water that always runs from higher ground downhill toward a lake or the sea.", "bis": "Ang suba usa ka nagdagayday nga tubig nga kanunay nga moagos gikan sa habog nga dapit paubos padulong sa linaw o dagat."}, "source": "NRC ESS2.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "abel-loom-weaving-fiber-g4", "domain": "MATTER", "topic": "weaving cloth from fibers on a loom", "grades": [3, 4, 5], "terms": ["abel", "habi", "hinabi", "tela", "sinulid", "hablon", "panghabi", "loom", "habol", "panapton", "gihabol", "paghabol", "fiber", "thread", "weaving", "cloth", "fabric"], "fact": {"tl": "Ang tela ay gawa sa maraming manipis na sinulid na pinagsasalubong nang patayo at pahalang sa isang habihan o loom upang maging isang matibay na piraso ng damit.", "en": "Cloth is made by crossing many thin threads over and under each other, lengthwise and crosswise, on a loom until they form one strong piece of fabric.", "bis": "Ang panapton gibuhat pinaagi sa paghabol sa daghang nipis nga hilo nga gisinabtanay pataas ug patabok diha sa habolan o loom aron mahimong usa ka lig-on nga panapton."}, "source": "encyclopedia-stable consensus; DepEd G4 Matter (materials)", "generator": "claude-workflow", "reviewed": false},
  {"id": "banca-outrigger-buoyancy-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "outrigger keeps a boat from tipping (buoyancy and stability)", "grades": [5, 6, 7], "terms": ["bangka", "banca", "katig", "outrigger", "lumutang", "nakalutang", "lutang", "lutaw", "naglutaw", "balanse", "hindi tumagilid", "dili matuwad", "stability", "balance", "buoyancy", "float", "boat", "tip over"], "fact": {"tl": "Lumulutang ang bangka dahil itinutulak ito pataas ng tubig, at ang katig sa gilid ay nagbibigay ng dagdag na balanse para hindi ito madaling tumagilid sa alon.", "en": "A banca floats because the water pushes up on it, and the outrigger floats on the side to give extra balance so the boat does not tip over in the waves.", "bis": "Naglutaw ang bangka tungod kay gitulod kini paibabaw sa tubig, ug ang katig sa kilid maghatag dugang balanse aron dili kini dali matuwad sa balod."}, "source": "encyclopedia-stable consensus; NRC PS2 forces", "generator": "claude-workflow", "reviewed": false},
  {"id": "afritada-cooking-chemical-change-g5", "domain": "MATTER", "topic": "cooking food is a chemical change", "grades": [4, 5, 6], "terms": ["afritada", "pagluluto", "niluto", "lutuin", "pinakuluan", "init", "pagbabagong kemikal", "pagluto", "giluto", "lutuon", "pagbag-o", "kainit", "cooking", "heat", "chemical change", "stew", "irreversible"], "fact": {"tl": "Kapag niluluto ang afritada, binabago ng init ang lasa, kulay, at tigas ng karne at gulay, at ito ay isang pagbabagong kemikal na hindi na maibabalik sa dating hilaw na anyo.", "en": "When afritada is cooked, the heat changes the taste, color, and firmness of the meat and vegetables, and this is a chemical change that cannot be turned back into raw food.", "bis": "Kon lutuon ang afritada, ang kainit mag-usab sa lami, kolor, ug katig-a sa karne ug utanon, ug kini usa ka kemikal nga pagbag-o nga dili na mabalik sa hilaw nga porma."}, "source": "encyclopedia-stable consensus; NRC PS1.B; DepEd G5 Matter", "generator": "claude-workflow", "reviewed": false},
  {"id": "beaker-measuring-volume-g5", "domain": "MATTER", "topic": "a beaker holds and measures liquid volume", "grades": [4, 5, 6], "terms": ["beaker", "baso", "salukan", "sukat", "sukatan", "dami ng likido", "sudlanan", "sukdanan", "gidaghanon sa tubig", "likido", "measure", "volume", "liquid", "laboratory", "glass", "markings"], "fact": {"tl": "Ang beaker ay isang basong salamin na may guhit-guhit sa gilid na ginagamit sa laboratoryo upang hawakan, ihalo, at sukatin nang humigit-kumulang ang dami ng likido.", "en": "A beaker is a glass container with markings on the side that scientists use in the laboratory to hold, mix, and roughly measure the volume of a liquid.", "bis": "Ang beaker usa ka bildo nga sudlanan nga adunay mga marka sa kilid nga gigamit sa laboratoryo aron sudlan, sagolon, ug sukdon nga banabana ang gidaghanon sa likido."}, "source": "encyclopedia-stable consensus; DepEd Science tools", "generator": "claude-workflow", "reviewed": false},
  {"id": "crayons-wax-pigment-g4", "domain": "MATTER", "topic": "crayons made of wax and pigment that melt with heat", "grades": [3, 4, 5], "terms": ["krayola", "krayon", "kandila", "pagkit", "wax", "crayon", "crayons", "natutunaw", "natunaw", "matunaw", "init", "kolor", "kulay", "pintura", "kolanit", "tunaw", "pigment", "melt", "color", "heat"], "fact": {"tl": "Ang krayola ay gawa sa pagkit (wax) na may halong pangkulay, kaya ito ay matigas kapag malamig ngunit natutunaw kapag pinainit.", "en": "A crayon is made of wax mixed with coloring pigment, so it stays hard when cool but melts when it gets hot.", "bis": "Ang krayola hinimo sa pagkit (wax) nga sagol kolor, mao nga gahi kini kon bugnaw apan matunaw kon mainit."}, "source": "encyclopedia-stable consensus; NRC PS1.A (states of matter change with heat)", "generator": "claude-workflow", "reviewed": false},
  {"id": "tex-teks-air-resistance-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "teks cardboard cards flip in air because of air resistance", "grades": [4, 5, 6], "terms": ["teks", "tex", "darting tex", "kartong laro", "ihahampas", "hampas", "lumilipad", "lumipad", "hangin", "air", "air resistance", "gravity", "grabidad", "nahuhulog", "bumabaligtad", "baligtad", "laro ng bata", "flip", "card", "spin"], "fact": {"tl": "Kapag inihampas ang teks, ang sumasalpok na hangin sa ibabaw nito ang nagpapabaligtad at nagpapaikot ng kartong laro habang ito ay lumilipad.", "en": "When a teks card is slapped down, air pushing against its surface makes the lightweight cardboard flip and spin as it flies.", "bis": "Kon ihampak ang teks, ang hangin nga mosumpaki sa ibabaw niini maoy hinungdan nga mobaliskad ug moliyok ang gaan nga kartong laro samtang molupad."}, "source": "encyclopedia-stable consensus; NRC PS2.A (forces and motion; air resistance)", "generator": "claude-workflow", "reviewed": false},
  {"id": "facial-muscles-expression-g4", "domain": "LIVING_THINGS", "topic": "facial muscles move the face to show emotions like smiling", "grades": [3, 4, 5], "terms": ["mukha", "ngiti", "ngumiti", "kalamnan sa mukha", "muscle", "muscles", "facial muscles", "masaya", "nakangiti", "emosyon", "damdamin", "nawong", "pahiyom", "mopahiyom", "kaunoran", "kunot ng noo", "smile", "frown", "expression", "emotion"], "fact": {"tl": "May mahigit apatnapung maliliit na kalamnan sa ating mukha na umiigkas para tayo makangiti, makasimangot, o makapagpahayag ng damdamin.", "en": "Our face has more than forty small muscles that pull to let us smile, frown, and show how we feel.", "bis": "Adunay kapin kap-atan ka gagmay nga kaunoran sa atong nawong nga mokontra aron kita makapahiyom, makasimangot, ug makapakita sa atong gibati."}, "source": "encyclopedia-stable consensus; AAAS Benchmarks 6C (human organism)", "generator": "claude-workflow", "reviewed": false},
  {"id": "fish-tinola-nutrition-g5", "domain": "LIVING_THINGS", "topic": "tinola fish soup gives protein and vitamins from fish ginger and malunggay", "grades": [4, 5, 6], "terms": ["tinola", "isda", "luya", "malunggay", "sili", "sabaw", "protina", "protein", "sustansya", "bitamina", "vitamin", "nutrisyon", "isda nga tinola", "isdang tinola", "kalan-on", "pagkain", "masustansya", "sabaw sa isda", "nutritious", "fish soup"], "fact": {"tl": "Ang tinolang isda ay masustansyang pagkain dahil ang isda ay nagbibigay ng protina, samantalang ang luya at dahon ng malunggay ay may bitamina.", "en": "Fish tinola is a nourishing dish because the fish gives protein while the ginger and malunggay leaves add vitamins.", "bis": "Ang tinolang isda usa ka masustansyang pagkaon kay ang isda mohatag ug protina, samtang ang luya ug dahon sa malunggay aduna'y bitamina."}, "source": "encyclopedia-stable consensus; DepEd Health/Science nutrition strand", "generator": "claude-workflow", "reviewed": false},
  {"id": "frying-heat-transfer-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "frying cooks food by hot oil transferring heat", "grades": [5, 6, 7], "terms": ["pagprito", "iprito", "pinirito", "fishball", "fish ball", "mainit na mantika", "mantika", "init", "heat", "energy", "enerhiya", "naluluto", "luto", "magprito", "iprito sa mantika", "lana", "lutoon", "frying", "oil", "cook", "hot oil"], "fact": {"tl": "Kapag pinipirito ang fishball, ang init mula sa mainit na mantika ay lumilipat sa pagkain at siyang nagluluto nito.", "en": "When fishballs are fried, heat from the hot oil moves into the food and cooks it.", "bis": "Kon iprito ang fishball, ang kainit gikan sa init nga mantika mobalhin ngadto sa pagkaon ug maoy moluto niini."}, "source": "encyclopedia-stable consensus; NRC PS3.B (energy transfer, heat)", "generator": "claude-workflow", "reviewed": false},
  {"id": "flowers-attract-pollinators-g5", "domain": "LIVING_THINGS", "topic": "colorful flowers attract insects that pollinate them", "grades": [4, 5, 6], "terms": ["bulaklak", "sampaguita", "rosas", "nektar", "nectar", "bubuyog", "paru-paro", "insekto", "polinasyon", "pollination", "pollinator", "bulak", "buyog", "alibangbang", "namumulaklak", "namulaklak", "halaman", "tanom", "flower", "bee", "butterfly", "attract"], "fact": {"tl": "Ang makukulay at mabangong bulaklak ay umaakit ng mga bubuyog at paru-paro, na tumutulong magdala ng pollen para makabuo ng buto ang halaman.", "en": "Colorful, sweet-smelling flowers attract bees and butterflies, which help carry pollen so the plant can make seeds.", "bis": "Ang mabulokon ug humot nga mga bulak modani sa mga buyog ug alibangbang, nga motabang sa pagdala sa pollen aron makahimo ug liso ang tanom."}, "source": "encyclopedia-stable consensus; NRC LS1.B (reproduction; pollination)", "generator": "claude-workflow", "reviewed": false},
  {"id": "food-for-the-gods-dates-walnuts-g6", "domain": "LIVING_THINGS", "topic": "food for the gods dessert is made from date fruit and walnut seeds", "grades": [5, 6, 7], "terms": ["food for the gods", "datiles", "dates", "walnut", "mani", "nuwes", "prutas", "buto", "seed", "fruit", "matamis", "panghimagas", "dessert", "bunga", "liso", "minatamis", "date fruit", "walnut nut", "palmera"], "fact": {"tl": "Ang food for the gods ay isang matamis na panghimagas na gawa sa datiles, na bunga ng palmera, at walnut, na isang uri ng buto.", "en": "Food for the gods is a sweet dessert made from dates, the fruit of a palm tree, and walnuts, which are a kind of seed.", "bis": "Ang food for the gods usa ka tam-is nga panghimagas nga hinimo sa datiles, ang bunga sa palmera, ug walnut, nga usa ka matang sa liso."}, "source": "encyclopedia-stable consensus; NRC LS1.C (food from plants)", "generator": "claude-workflow", "reviewed": false},
  {"id": "marching-band-instruments-sound-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "marching band instruments make sound by vibrating", "grades": [3, 4, 5], "terms": ["banda", "marching band", "tambol", "trumpeta", "instrumento", "tunog", "vibrasyon", "nanginginig", "nagvibrate", "sound", "vibration", "tingog", "huni", "nagkurog", "mokurog", "trumpet", "drum", "musika", "musika sa banda", "instrument"], "fact": {"tl": "Ang mga instrumento ng banda ay gumagawa ng tunog dahil sa pagvibrate: nanginginig ang balat ng tambol o ang hangin sa loob ng trumpeta.", "en": "Marching band instruments make sound by vibrating: the drum's skin shakes or the air inside the trumpet vibrates.", "bis": "Ang mga instrumento sa banda mohimo ug tingog pinaagi sa pagkurog: mokurog ang panit sa tambol o ang hangin sa sulod sa trumpeta."}, "source": "encyclopedia-stable consensus; NRC PS4.A (sound from vibration)", "generator": "claude-workflow", "reviewed": false},
  {"id": "ginataang-coconut-milk-g5", "domain": "MATTER", "topic": "coconut milk gata as an emulsion that thickens with heat", "grades": [4, 5, 6], "terms": ["gata", "ginataan", "coconut milk", "niyog", "lana sa lubi", "lubi", "gatas ng niyog", "emulsion", "kumukulo", "lumalapot", "kapag pinakuluan", "init", "heat", "lumabas ang langis", "thickens", "coconut cream", "gata sa lubi", "molulot"], "fact": {"tl": "Ang gata ay nakukuha sa pagpiga ng kinudkod na niyog, at kapag pinakuluan ito sa ginataang putahe ay lumalapot habang lumalabas ang langis dahil sa init.", "en": "Coconut milk (gata) is squeezed from grated coconut, and when boiled in a ginataang dish it thickens as heat draws out the oil.", "bis": "Ang gata makuha pinaagi sa pagpuga sa kinudkod nga lubi, ug kon pabukalon kini sa ginataang sud-an molulot kini samtang mogawas ang lana tungod sa kainit."}, "source": "encyclopedia-stable consensus; DepEd G5 changes from heating", "generator": "claude-workflow", "reviewed": false},
  {"id": "gloves-safety-g3", "domain": "MATTER", "topic": "gloves as protective barrier in science work", "grades": [3, 4, 5], "terms": ["gloves", "guantes", "gwantes", "proteksyon sa kamay", "panangga", "kamay", "safety", "kaligtasan", "init", "mainit", "kemikal", "chemicals", "barrier", "harang", "panalipod sa kamot", "guwantis", "suot sa kamay", "protective gear"], "fact": {"tl": "Ang gloves o guwantes ay isinusuot sa kamay bilang panangga upang hindi direktang madikit ang balat sa mainit, matalas, o nakakapasong bagay habang nag-eeksperimento.", "en": "Gloves are worn on the hands as a barrier so the skin does not directly touch hot, sharp, or harmful things during an experiment.", "bis": "Ang gloves o guwantis isul-ob sa kamot isip panalipod aron dili direktang masaghid sa init, hait, o makadaot nga butang ang panit samtang mag-eksperimento."}, "source": "DepEd science safety practices; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "goggles-eye-protection-g3", "domain": "MATTER", "topic": "safety goggles protect the eyes during experiments", "grades": [3, 4, 5], "terms": ["goggles", "salaming pang-mata", "salamin sa mata", "proteksyon sa mata", "panangga sa mata", "eye protection", "safety goggles", "tilamsik", "splash", "kemikal", "chemicals", "panalipod sa mata", "antiyohos pangkaligtasan", "suot sa mata", "kaligtasan", "pisik sa mata"], "fact": {"tl": "Ang safety goggles ay malinaw na salaming isinusuot sa mata upang protektahan ito mula sa tilamsik ng kemikal, alikabok, o lumilipad na bagay sa laboratoryo.", "en": "Safety goggles are clear glasses worn over the eyes to protect them from chemical splashes, dust, or flying bits in the laboratory.", "bis": "Ang safety goggles maoy tin-aw nga salamin nga isul-ob sa mata aron panalipdan kini gikan sa pisik sa kemikal, abog, o naglupad nga butang sa laboratoryo."}, "source": "DepEd science safety practices; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "grilled-bbq-chemical-change-g6", "domain": "MATTER", "topic": "grilling meat is a chemical change from heat", "grades": [5, 6, 7], "terms": ["barbecue", "barbekyu", "ihaw", "inihaw", "sinugba", "grilled", "litson", "uling", "baga", "init", "heat", "chemical change", "pagbabagong kemikal", "nagbabago ang kulay", "kayumanggi", "browning", "amoy", "usok", "karne", "sugba", "pagsugba", "naluto"], "fact": {"tl": "Kapag iniihaw ang karne sa baga, ang init ay nagdudulot ng pagbabagong kemikal na nagpapaitim-kayumanggi ng ibabaw nito at gumagawa ng bagong amoy at lasa na hindi na maibabalik sa hilaw.", "en": "When meat is grilled over hot coals, the heat causes a chemical change that browns its surface and creates new smells and flavors that cannot be turned back to raw.", "bis": "Kon sugbahon ang karne sa baga, ang kainit maghimo og pagbag-ong kemikal nga makapaitom-kapeha sa ibabaw niini ug maghimo og bag-ong baho ug lami nga dili na mabalik sa hilaw."}, "source": "DepEd G6 chemical vs physical change; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "halo-halo-mixture-g5", "domain": "MATTER", "topic": "halo-halo is a mixture whose parts keep their identity", "grades": [4, 5, 6], "terms": ["halo-halo", "haluhalo", "halo", "pinaghalong", "mixture", "timpla", "sangkap", "ingredients", "sago", "gulaman", "saging", "langka", "leche flan", "kinilala pa", "nakikilala", "magkakahiwalay", "components", "sagol", "sinagol", "matunaw man", "nakikitang sangkap", "magkakaibang sangkap"], "fact": {"tl": "Ang halo-halo ay isang halo o mixture dahil pinagsama-sama ang iba't ibang sangkap tulad ng sago, gulaman, saging, at langka na nananatiling nakikilala kahit naghalo na sa yelo at gatas.", "en": "Halo-halo is a mixture because different ingredients like sago, gulaman, banana, and jackfruit are combined yet each can still be recognized even after stirring with ice and milk.", "bis": "Ang halo-halo usa ka sagol o mixture kay gisagol ang nagkalain-laing sangkap sama sa sago, gulaman, saging, ug langka nga makaila gihapon bisan human masagol sa yelo ug gatas."}, "source": "DepEd G5 mixtures; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "jolen-marble-motion-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "marbles roll and transfer force when they collide", "grades": [3, 4, 5], "terms": ["jolen", "holen", "marbles", "marble", "bola-bolang salamin", "gumugulong", "rolling", "tinama", "banggaan", "collision", "puwersa", "force", "lakas", "nagulong", "tumigil", "friction", "kuskusan", "naipasa ang lakas", "tira", "natitira", "naghampasan", "pagkilos"], "fact": {"tl": "Kapag tinama ng isang jolen ang isa pa, naipapasa nito ang puwersa kaya gumugulong palayo ang natamaang jolen, at unti-unti itong huhupa dahil sa kuskusan sa lupa.", "en": "When one marble hits another, it passes on a force so the struck marble rolls away, and it gradually slows down because of friction with the ground.", "bis": "Kon ang usa ka holen makaigo sa lain, mabalhin niini ang puwersa mao nga moligid palayo ang naigo nga holen, ug hinay-hinay kining mohinay tungod sa pagkuskos sa yuta."}, "source": "DepEd G4 force and motion; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kakanin-glutinous-rice-g5", "domain": "LIVING_THINGS", "topic": "kakanin are made from sticky glutinous rice", "grades": [4, 5, 6], "terms": ["kakanin", "malagkit", "glutinous rice", "bigas na malagkit", "pilit", "sticky rice", "suman", "biko", "puto", "kanin", "almirol", "starch", "lumalapot", "naluluto", "init", "dikit-dikit", "pulot nga bugas", "kakanon", "halaman", "palay", "rice", "naluto"], "fact": {"tl": "Karamihan ng kakanin tulad ng suman at biko ay gawa sa malagkit na bigas, na mas mataas sa isang uri ng almirol kaya nagiging dikit-dikit at malapot kapag niluluto sa init.", "en": "Most kakanin like suman and biko are made from glutinous (sticky) rice, which has more of one kind of starch so it turns sticky and chewy when cooked with heat.", "bis": "Kadaghanan sa kakanin sama sa suman ug biko hinimo sa pilit nga bugas, nga mas daghan og usa ka matang sa almirol mao nga modikit-dikit ug molapot kini kon lutoon sa kainit."}, "source": "encyclopedia-stable consensus; DepEd G5 sources of food and changes from heating", "generator": "claude-workflow", "reviewed": false},
  {"id": "kare-kare-peanut-g5", "domain": "LIVING_THINGS", "topic": "peanuts thicken the kare-kare sauce", "grades": [4, 5, 6], "terms": ["kare-kare", "mani", "peanut", "peanuts", "giniling na mani", "ground peanut", "sarsa", "sauce", "lumalapot", "thickens", "binhi", "buto", "legume", "tanim", "halaman", "almirol", "langis", "mani nga giling", "lapot", "pampalapot", "protina", "buto sa lupa"], "fact": {"tl": "Ang malapot na sarsa ng kare-kare ay nakukuha sa giniling na mani, isang binhi ng halamang tumutubo sa ilalim ng lupa na mayaman sa langis at protina.", "en": "The thick sauce of kare-kare comes from ground peanuts, the seeds of a plant that grow underground and are rich in oil and protein.", "bis": "Ang lapot nga sarsa sa kare-kare makuha gikan sa giniling nga mani, usa ka liso sa tanom nga motubo ilalom sa yuta nga dato sa lana ug protina."}, "source": "encyclopedia-stable consensus; DepEd G5 sources of food", "generator": "claude-workflow", "reviewed": false},
  {"id": "sack-race-friction-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "the sack slows runners through friction in karera ng sako", "grades": [3, 4, 5], "terms": ["karera ng sako", "sack race", "sako", "sack", "talunan", "lukso", "jumping", "puwersa", "force", "kuskusan", "friction", "bigat", "lakad", "takbo", "running", "indayog", "tumatakbo", "luksong-sako", "nahihirapan", "pagtakbo", "lakas", "kilos"], "fact": {"tl": "Sa karera ng sako, hindi ka makakatakbo nang tuloy-tuloy kaya kailangang lumukso, dahil ang sako ay pumipigil sa galaw ng mga binti at nagdaragdag ng kuskusan sa lupa.", "en": "In a sack race you cannot run freely and must jump instead, because the sack restrains your legs and adds friction with the ground.", "bis": "Sa karera sa sako dili ka makadagan og diretso busa kinahanglang molukso, kay ang sako mopugong sa lihok sa imong mga paa ug magdugang og pagkuskos sa yuta."}, "source": "DepEd G4 force, friction, and motion; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "relay-race-speed-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "speed in a relay race depends on distance over time", "grades": [4, 5, 6], "terms": ["karera", "takbuhan", "relay", "relay race", "estafeta", "bilis", "speed", "tulin", "layo", "distansya", "distance", "oras", "time", "mabilis", "mabagal", "tumatakbo", "running", "abante", "pinakamabilis", "kadali", "kalayo", "panahon"], "fact": {"tl": "Sa relay o karera, mas mabilis ang isang manlalaro kapag mas malayong distansya ang naaabot niya sa mas maikling oras, kaya ang bilis ay sinusukat bilang layo kada oras.", "en": "In a relay race a runner is faster when they cover a longer distance in a shorter time, so speed is measured as distance per unit of time.", "bis": "Sa relay o karera, mas paspas ang usa ka magdudula kon mas layo nga gilay-on ang iyang maabot sa mas mubo nga panahon, mao nga ang katulin sukdon isip gilay-on kada panahon."}, "source": "DepEd G5 measuring motion and speed; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "swimming-buoyancy-river-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "water pushes swimmers up with buoyant force", "grades": [4, 5, 6], "terms": ["paglangoy", "swimming", "langoy", "ilog", "river", "lutang", "lumulutang", "floating", "buoyancy", "buoyant force", "puwersang pataas", "itinutulak pataas", "tubig", "water", "bigat", "timbang", "lumubog", "sinks", "nakalutang", "naglutaw", "tubig nga nagtulod", "lutaw"], "fact": {"tl": "Kapag naglalangoy ang mga bata sa ilog, itinutulak sila pataas ng tubig sa pamamagitan ng puwersang tinatawag na buoyancy, kaya mas madali silang lumutang kaysa sa tuyong lupa.", "en": "When children swim in a river, the water pushes them upward with a force called buoyancy, which makes it easier for them to float than on dry land.", "bis": "Kon molangoy ang mga bata sa suba, gitulod sila pataas sa tubig pinaagi sa puwersa nga gitawag og buoyancy, mao nga mas sayon sila molutaw kaysa sa mamala nga yuta."}, "source": "DepEd G5 forces in fluids; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "parol-lantern-light-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "the parol lantern gives off light from a source inside", "grades": [3, 4, 5], "terms": ["parol", "lantern", "ilaw", "light", "nagliliwanag", "pinagmumulan ng liwanag", "light source", "bombilya", "ilawan", "kandila", "kuryente", "electricity", "sinindihan", "suga", "nagdan-ag", "kasanag", "Pasko", "bituin", "tinubdan sa kahayag"], "fact": {"tl": "Ang parol ay isang bituing hugis na lantern na nagliliwanag dahil may pinagmumulan ng liwanag sa loob, tulad ng bombilya o kandila, na nagpapakalat ng ilaw sa palibot.", "en": "A parol is a star-shaped lantern that glows because it has a light source inside, such as a bulb or candle, that spreads light around it.", "bis": "Ang parol usa ka bituon nga porma nga lantern nga magdan-ag tungod kay aduna kini tinubdan sa kahayag sa sulod, sama sa bombilya o kandila, nga magkatag sa suga sa palibot."}, "source": "DepEd G4 light and its sources; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "microscope-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "microscope magnifying tool", "grades": [3, 4, 5], "terms": ["mikroskopyo", "mikroskopio", "lente", "magnify", "palaki", "pinalaki", "maliliit na bagay", "gamit sa agham", "microscope", "lens", "tiny things", "magnifies", "gagmay nga butang", "magpadako", "gipadako", "lente sa siyensya"], "fact": {"tl": "Ang mikroskopyo ay isang kagamitan sa agham na gumagamit ng mga lente para palakihin ang mga bagay na napakaliit para makita ng mata.", "en": "A microscope is a science tool that uses lenses to magnify things too tiny to see with the eye.", "bis": "Ang mikroskopyo usa ka galamiton sa siyensya nga naggamit ug mga lente aron padakoon ang mga butang nga gagmay kaayo aron makita sa mata."}, "source": "encyclopedia-stable consensus; DepEd G3 scientific tools", "generator": "claude-workflow", "reviewed": false},
  {"id": "microscope-g7", "domain": "LIVING_THINGS", "topic": "microscope reveals cells and microbes", "grades": [7, 8, 9], "terms": ["mikroskopyo", "selula", "mga selula", "cell", "cells", "bakterya", "mikrobyo", "magnipikasyon", "pinalaki", "makita ang selula", "microscope", "magnification", "microbes", "bacteria", "observe cells", "selyula", "tan-awon ang selula", "magpadako"], "fact": {"tl": "Sa pamamagitan ng mikroskopyo, nakikita ng mga siyentipiko ang mga selula, bakterya, at iba pang mikrobyong hindi maaabot ng mata, kaya mahalaga ito sa pag-aaral ng buhay.", "en": "With a microscope, scientists can see cells, bacteria, and other microbes that the eye cannot reach, making it important for studying living things.", "bis": "Pinaagi sa mikroskopyo, makita sa mga siyentista ang mga selula, bakterya, ug uban pang mikrobyo nga dili maabot sa mata, busa importante kini sa pagtuon sa buhing mga butang."}, "source": "encyclopedia-stable consensus; DepEd G7 cell biology", "generator": "claude-workflow", "reviewed": false},
  {"id": "ruler-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "ruler measuring length", "grades": [3, 4], "terms": ["ruler", "panukat", "ruler na panukat", "sukat", "sukatin", "haba", "habang", "sentimetro", "milimetro", "pulgada", "measure", "length", "centimeter", "millimeter", "sukod", "sukdon", "gilay-on", "santimetro", "tag-as"], "fact": {"tl": "Ang ruler ay isang tuwid na kagamitan na may mga guhit na sentimetro at milimetro na ginagamit para sukatin ang haba ng isang bagay.", "en": "A ruler is a straight tool marked with centimeters and millimeters that is used to measure the length of an object.", "bis": "Ang ruler usa ka tul-id nga himan nga adunay mga marka nga sentimetro ug milimetro nga gamiton sa pagsukod sa gitas-on sa usa ka butang."}, "source": "DepEd MATATAG Science G3 (measurement); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ruler-units-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "ruler units centimeter millimeter", "grades": [4, 5], "terms": ["ruler", "panukat", "sentimetro", "milimetro", "sentimetro at milimetro", "isang sentimetro", "sampung milimetro", "sukat", "haba", "centimeter", "millimeter", "unit", "yunit", "sukod", "santimetro", "napulo ka milimetro"], "fact": {"tl": "Sa karaniwang ruler, ang bawat isang sentimetro ay nahahati sa sampung milimetro, kaya nakakasukat ka ng maliliit na haba nang tumpak.", "en": "On a standard ruler, each centimeter is divided into ten millimeters, so you can measure small lengths accurately.", "bis": "Sa naandang ruler, ang matag usa ka sentimetro gibahin sa napulo ka milimetro, busa makasukod ka og gagmay nga gitas-on nga tukma."}, "source": "encyclopedia-stable consensus; SI units (metric)", "generator": "claude-workflow", "reviewed": false},
  {"id": "gulaman-agar-seaweed-gel-g5", "domain": "MATTER", "topic": "gulaman agar seaweed gel", "grades": [5, 6], "terms": ["gulaman", "agar", "agar-agar", "damong-dagat", "seaweed", "lumot sa dagat", "jelly", "jelly na gulaman", "natutunaw", "natunaw sa mainit na tubig", "lumalapot", "gel", "lutang-dagat", "natunaw", "nagulaman", "matunaw", "molabog", "molapot"], "fact": {"tl": "Ang gulaman ay gawa sa agar, isang sangkap na galing sa ilang uri ng damong-dagat na natutunaw sa mainit na tubig at lumalapot na parang jelly kapag lumamig.", "en": "Gulaman is made from agar, a substance from certain seaweeds that dissolves in hot water and sets into a jelly as it cools.", "bis": "Ang gulaman hinimo gikan sa agar, usa ka sangkap nga gikan sa pipila ka klase sa damong-dagat nga matunaw sa init nga tubig ug molapot nga sama sa jelly kung mobugnaw."}, "source": "encyclopedia-stable consensus (agar from red algae)", "generator": "claude-workflow", "reviewed": false},
  {"id": "samalamig-dissolving-drink-g4", "domain": "MATTER", "topic": "samalamig dissolving sugar drink", "grades": [3, 4, 5], "terms": ["samalamig", "sago't gulaman", "sagot gulaman", "inumin", "asukal", "natutunaw", "natunaw ang asukal", "halo", "haluin", "solusyon", "matamis", "tubig", "yelo", "dissolve", "solution", "sugar", "drink", "matunaw", "asukar", "ilimnon", "gisagol", "natunaw na", "molunaw"], "fact": {"tl": "Sa pampalamig na inumin tulad ng samalamig, natutunaw ang asukal sa tubig at nabubuo ang isang solusyon na pantay-pantay ang tamis sa bawat patak.", "en": "In a cold drink like samalamig, sugar dissolves in the water and forms a solution that is equally sweet in every drop.", "bis": "Sa bugnaw nga ilimnon sama sa samalamig, ang asukar matunaw sa tubig ug mahimong solusyon nga managsama ang katam-is sa matag tulo."}, "source": "DepEd MATATAG Science (solutions/mixtures); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sapin-sapin-layers-mixture-g4", "domain": "MATTER", "topic": "layered rice cake as a mixture of colored batters", "grades": [4, 5], "terms": ["sapin-sapin", "kakanin", "patong-patong", "kulay", "layer", "rice cake", "galapong", "magkahiwalay na layer", "pinatong", "naglulayer", "pagkaing may patong", "ginikan sa bugas", "magkalain-laing kolor"], "fact": {"tl": "Ang sapin-sapin ay kakaning gawa sa galapong (giniling na malagkit na bigas) na hinati sa iba't ibang kulay at pinatong-patong, kaya nakikita mo ang magkakahiwalay na makukulay na layer.", "en": "Sapin-sapin is a rice cake made from ground glutinous rice batter that is split into different colors and stacked, so you can see separate colorful layers.", "bis": "Ang sapin-sapin usa ka kakanin nga hinimo sa giniling nga pilit nga bugas nga gibahin sa lainlaing kolor ug gipatong-patong, mao nga makita nimo ang nagkalain-laing kolor nga layer."}, "source": "encyclopedia-stable consensus; DepEd G4 mixtures", "generator": "claude-workflow", "reviewed": false},
  {"id": "scissors-lever-simple-machine-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "scissors as a pair of levers", "grades": [4, 5, 6], "terms": ["gunting", "scissors", "simpleng makina", "lever", "pingga", "pivot", "puwersa", "pumuputol", "ginunting", "simple machine", "gabira", "gunting nga makina", "duha ka pingga", "magputol"], "fact": {"tl": "Ang gunting ay simpleng makina na binubuo ng dalawang pingga (lever) na nagsasalubong sa isang pivot, kaya kahit kaunting puwersa ng kamay ay sapat na para pumutol ng papel o tela.", "en": "Scissors are a simple machine made of two levers joined at a pivot, so even a small push from your hand is enough to cut paper or cloth.", "bis": "Ang gunting usa ka simpleng makina nga gilangkuban sa duha ka pingga (lever) nga nagtagbo sa usa ka pivot, mao nga bisan gamay nga kusog sa imong kamot igo na aron makaputol ug papel o panapton."}, "source": "AAAS Benchmarks 8E; DepEd G5 simple machines", "generator": "claude-workflow", "reviewed": false},
  {"id": "stopwatch-measures-time-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "stopwatch measures elapsed time", "grades": [3, 4, 5], "terms": ["stopwatch", "orasan", "panukat ng oras", "segundo", "sukat ng panahon", "bilis", "takbo", "tiempo", "pagsukat sa oras", "relo", "segundos", "kadugayon", "sukdanan sa oras", "pagsukat sa kapaspas"], "fact": {"tl": "Ang stopwatch ay isang orasan na sumusukat kung gaano katagal nangyayari ang isang bagay, gaya ng bilang ng segundo sa isang takbuhan, kaya nagagamit ito para malaman kung gaano kabilis o kabagal.", "en": "A stopwatch is a clock that measures how long something takes, such as the seconds in a race, so it helps us tell how fast or slow something is.", "bis": "Ang stopwatch usa ka orasan nga nagsukod kung unsa kadugay mahitabo ang usa ka butang, sama sa segundos sa usa ka lumba, mao nga magamit kini aron mahibal-an kung unsa kapaspas o kahinay."}, "source": "AAAS Benchmarks 9C; DepEd G4 motion and measurement", "generator": "claude-workflow", "reviewed": false},
  {"id": "tokneneng-egg-heat-change-g4", "domain": "MATTER", "topic": "egg cooking is an irreversible change from heat", "grades": [4, 5, 6], "terms": ["tokneneng", "itlog", "egg", "binalot na itlog", "init", "niluto", "pagbabago", "hindi na maibabalik", "naninigas", "pritong itlog", "init nga nagbag-o", "giluto nga itlog", "naggahi ang itlog", "dili na mabalik"], "fact": {"tl": "Ang tokneneng ay pinakuluang itlog na binalot sa orange na batter at pinirito; kapag iniinit ang itlog, naninigas ito at hindi na maibabalik sa likido nitong anyo, kaya ito ay halimbawa ng pagbabagong hindi na mababawi.", "en": "Tokneneng is a boiled egg coated in orange batter and fried; when an egg is heated it hardens and cannot return to its runny form, so it is an example of an irreversible change.", "bis": "Ang tokneneng usa ka linat-an nga itlog nga gibalot sa orange nga batter ug giprito; kon initon ang itlog mogahi kini ug dili na mabalik sa likido niini nga porma, mao nga panig-ingnan kini sa kausaban nga dili na mabawi."}, "source": "NRC PS1.B; DepEd G5 reversible and irreversible changes", "generator": "claude-workflow", "reviewed": false},
  {"id": "tokwat-baboy-dish-g5", "domain": "MATTER", "topic": "tofu tokwa from soybeans", "grades": [4, 5, 6], "terms": ["tokwa", "tokwat baboy", "toyo", "tofu", "soybean", "soya", "utaw", "protina", "protein", "balatong", "sabaw", "luto", "tausi"], "fact": {"tl": "Ang tokwa sa tokwa't baboy ay gawa sa gatas ng utaw o soybean na pinatigas, kaya ito ay mayaman sa protina na nagpapalakas ng katawan.", "en": "The tofu in tokwa't baboy is made from soybean milk that is curdled and pressed solid, so it is rich in body-building protein.", "bis": "Ang tokwa sa tokwa't baboy hinimo gikan sa gatas sa utaw o soybean nga gipagahi, busa dato kini sa protina nga nagpalig-on sa lawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tongs-lever-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "tongs as a lever simple machine", "grades": [3, 4, 5], "terms": ["sipit", "tong", "tongs", "kimpit", "lever", "simpleng makina", "simple machine", "puwersa", "pwersa", "kuptan", "panghipos"], "fact": {"tl": "Ang sipit (tongs) ay isang uri ng lever na tumutulong sa atin na humawak ng mainit o madumi na bagay nang hindi dinidikit ang ating kamay.", "en": "Tongs are a kind of lever that helps us grip hot or dirty things without touching them with our hands.", "bis": "Ang sipit (tongs) usa ka matang sa lever nga nagatabang kanato sa pagkupot sa init o hugaw nga butang nga dili magamit ang atong kamot."}, "source": "AAAS Benchmarks; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ukulele-instrument-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "ukulele strings make sound by vibrating", "grades": [4, 5, 6], "terms": ["ukulele", "kwerdas", "kuwerdas", "string", "vibration", "tunog", "tingog", "gitara", "musika", "pag-uyog", "vibrasyon", "kurutan", "pinitik"], "fact": {"tl": "Kapag pinitik ang kwerdas ng ukulele, ito ay nanginginig nang mabilis at ang panginig na ito ang gumagawa ng tunog na ating naririnig.", "en": "When a ukulele string is plucked it vibrates back and forth quickly, and that vibration makes the sound we hear.", "bis": "Kon kurutan ang kwerdas sa ukulele, kini mauyog-uyog ug paspas, ug kanang pag-uyog mao ang naghimo sa tingog nga atong madungog."}, "source": "AAAS Benchmarks 4F; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bell-sound-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "a bell makes sound by vibrating", "grades": [3, 4, 5], "terms": ["kampana", "bell", "kalembang", "tunog", "tingog", "vibration", "pag-uyog", "panginig", "metal", "lingganay", "bagting"], "fact": {"tl": "Tumutunog ang kampana dahil kapag ito ay napalo, ang metal nito ay nanginginig at nagpapadala ng tunog sa hangin.", "en": "A bell rings because when it is struck its metal vibrates, sending sound out through the air.", "bis": "Motingog ang kampana tungod kay kon kini matamparos, mauyog ang puthaw niini ug magpadala og tingog ngadto sa hangin."}, "source": "AAAS Benchmarks 4F; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "drum-sound-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "a drum makes sound by a vibrating membrane", "grades": [3, 4, 5], "terms": ["tambol", "drum", "balat", "membrane", "tunog", "tingog", "vibration", "pag-uyog", "panginig", "palo", "tugtog", "panit"], "fact": {"tl": "Kapag pinalo ang tambol, ang nakaunat na balat sa ibabaw nito ay nanginginig, at ang panginig na ito ang gumagawa ng malakas na tunog.", "en": "When a drum is hit, the tight skin stretched over its top vibrates, and that vibration makes the loud sound.", "bis": "Kon palhon ang tambol, ang gihugot nga panit sa ibabaw niini mauyog, ug kanang pag-uyog maoy naghimo sa kusog nga tingog."}, "source": "AAAS Benchmarks 4F; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "em-spectrum-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "the electromagnetic spectrum", "grades": [7, 8, 9, 10], "terms": ["electromagnetic spectrum", "ispektrum", "espektrum", "radio", "microwave", "infrared", "liwanag", "kahayag", "visible light", "ultraviolet", "x-ray", "gamma", "alon", "balud", "wave"], "fact": {"tl": "Ang electromagnetic spectrum ay ang buong saklaw ng mga alon ng liwanag, mula sa radio waves at microwaves hanggang sa nakikitang liwanag, X-rays, at gamma rays.", "en": "The electromagnetic spectrum is the full range of light waves, from radio waves and microwaves through visible light to X-rays and gamma rays.", "bis": "Ang electromagnetic spectrum mao ang tibuok gilapdon sa mga balud sa kahayag, gikan sa radio waves ug microwaves hangtod sa makita nga kahayag, X-rays, ug gamma rays."}, "source": "NRC PS4; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "em-spectrum-visible-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "visible light is a small part of the spectrum", "grades": [6, 7, 8], "terms": ["nakikitang liwanag", "visible light", "kahayag", "kolor", "kulay", "bahaghari", "rainbow", "balangaw", "wavelength", "mata", "mga mata"], "fact": {"tl": "Ang liwanag na nakikita ng ating mga mata ay isang maliit na bahagi lamang ng electromagnetic spectrum, at ito ang nakikita natin bilang mga kulay ng bahaghari.", "en": "The light our eyes can see is only a small part of the electromagnetic spectrum, and we see it as the colors of the rainbow.", "bis": "Ang kahayag nga makita sa atong mga mata gamay ra nga bahin sa electromagnetic spectrum, ug kini atong makita isip mga kolor sa balangaw."}, "source": "NRC PS4; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "flashlight-circuit-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "a flashlight is a simple electric circuit", "grades": [4, 5, 6], "terms": ["flashlight", "plaslayt", "lampara", "baterya", "battery", "bombilya", "bombilyang", "circuit", "sirkito", "kuryente", "koryente", "kawad", "wire", "suga", "ilaw"], "fact": {"tl": "Gumagana ang flashlight dahil ang baterya, kawad, at bombilya nito ay bumubuo ng isang kumpletong circuit na nagpapadaloy ng kuryente para magningas ang ilaw.", "en": "A flashlight works because its battery, wires, and bulb form a complete circuit that lets electricity flow and light up the bulb.", "bis": "Mogana ang flashlight tungod kay ang baterya, kawad, ug bombilya niini naghimo og kompleto nga circuit nga nagpadagayday sa kuryente aron mosiga ang suga."}, "source": "NRC PS3; DepEd G5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "flashlight-parts-cutaway-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "parts of a flashlight", "grades": [4, 5, 6], "terms": ["flashlight", "plaslayt", "bahagi", "parte", "baterya", "battery", "bombilya", "switch", "salamin", "reflector", "bombilyang", "ilaw", "suga"], "fact": {"tl": "Ang flashlight ay may baterya na pinagmumulan ng kuryente, switch na nagbubukas at nagsasara ng circuit, bombilya na nagbibigay-ilaw, at salaming reflector na nagpapalakas ng sinag.", "en": "A flashlight has a battery for power, a switch that opens and closes the circuit, a bulb that gives light, and a curved mirror reflector that focuses the beam.", "bis": "Ang flashlight adunay baterya nga tinubdan sa kuryente, switch nga nagabuka ug nagasira sa circuit, bombilya nga naghatag og kahayag, ug salamin nga reflector nga nagpakusog sa sidlak."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fridge-magnet-letters-hold-g3", "domain": "FORCE_MOTION_ENERGY", "topic": "magnets stick to iron refrigerator doors", "grades": [3, 4, 5], "terms": ["magnet", "magneto", "bato-balani", "ref", "refrigerator", "pridyider", "bakal", "puthaw", "iron", "metal", "dikit", "dumikit", "nadikit", "letra", "humahawak"], "fact": {"tl": "Dumidikit ang magnet na may mga letra sa pintuan ng ref dahil ang pinto ay gawa sa bakal, at ang magnet ay humahawak lamang sa mga metal na may bakal.", "en": "Letter magnets stick to a refrigerator door because the door is made of iron, and magnets pull only on metals that contain iron.", "bis": "Mopilit ang magnet nga may mga letra sa pultahan sa ref tungod kay ang pultahan hinimo sa puthaw, ug ang magnet mokupot lang sa mga metal nga adunay puthaw."}, "source": "NRC PS2; AAAS Benchmarks 4G", "generator": "claude-workflow", "reviewed": false},
  {"id": "lightbulb-electricity-light-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "a light bulb turns electricity into light", "grades": [4, 5, 6], "terms": ["bombilya", "bombilyang", "lightbulb", "ilaw", "suga", "kuryente", "koryente", "electricity", "init", "kainit", "filament", "liwanag", "kahayag"], "fact": {"tl": "Nagliliwanag ang bombilya dahil pinapadaloy dito ang kuryente na nagpapainit sa manipis na kawad sa loob nito hanggang sa ito ay magbigay ng liwanag.", "en": "A light bulb glows because electricity flows through and heats a thin wire inside it until that wire gives off light.", "bis": "Mosiga ang bombilya tungod kay ang kuryente moagi niini ug mopainit sa nipis nga kawad sa sulod hangtod kini mohatag og kahayag."}, "source": "NRC PS3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "paperclip-magnetic-material-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "paper clips are attracted by magnets", "grades": [3, 4, 5], "terms": ["clip", "paper clip", "ipit", "ipit-papel", "bakal", "puthaw", "iron", "asero", "magnet", "magneto", "bato-balani", "metal", "nahihila", "naakit", "nadani"], "fact": {"tl": "Nahihila ng magnet ang mga paper clip dahil ang mga ito ay gawa sa bakal, na isang metal na nakakaakit sa magnet.", "en": "A magnet pulls paper clips because they are made of steel, a metal that magnets attract.", "bis": "Madani sa magnet ang mga paper clip tungod kay hinimo kini sa puthaw, usa ka metal nga makaakit sa magnet."}, "source": "NRC PS2; AAAS Benchmarks 4G", "generator": "claude-workflow", "reviewed": false},
  {"id": "pendulum-on-stand-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "a pendulum swings because of gravity", "grades": [6, 7, 8], "terms": ["pendulum", "pendulo", "palawit", "duyan", "swing", "ugoy", "indayog", "gravity", "grabidad", "puwersa", "pwersa", "bigat", "bug-at", "pag-indayog"], "fact": {"tl": "Ang pendulum ay isang bigat na nakabitin sa kuwerdas na paroo't parito kapag iindayog, dahil hinihila ito pababa ng grabidad pagkatapos itong iangat.", "en": "A pendulum is a weight hung on a string that swings back and forth because gravity pulls it down after it is lifted to one side.", "bis": "Ang pendulum usa ka bug-at nga gisab-it sa pisi nga magduyan-duyan kay ang grabidad nagbira niini paubos human kini iisa sa usa ka kilid."}, "source": "NRC PS2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "switch-circuit-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "a switch opens and closes a circuit", "grades": [4, 5, 6], "terms": ["switch", "swits", "iswits", "circuit", "sirkito", "kuryente", "koryente", "bukas", "sira", "patay", "buhi", "kawad", "daloy", "pagdagayday"], "fact": {"tl": "Ang switch ay kumokontrol sa daloy ng kuryente dahil kapag ito ay sinara nito ang circuit at dumadaloy ang kuryente, at kapag binuksan ito naputol ang daloy.", "en": "A switch controls the flow of electricity because closing it completes the circuit so current flows, and opening it breaks the path so the current stops.", "bis": "Ang switch nagakontrol sa pagdagayday sa kuryente kay kon sirad-an niini matapos ang circuit ug modagayday ang kuryente, ug kon ablihan maputol ang agianan."}, "source": "NRC PS3; DepEd G5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "thermos-keeps-drink-hot-g6", "domain": "MATTER", "topic": "a thermos slows heat transfer with insulation", "grades": [5, 6, 7], "terms": ["thermos", "termos", "init", "kainit", "insulator", "insulation", "lamig", "bugnaw", "mainit", "init nga ilimnon", "heat", "vacuum", "nagpapanatili", "nagatipig"], "fact": {"tl": "Nananatiling mainit ang inumin sa loob ng thermos dahil ang dobleng dingding nito na may patlang sa pagitan ay humahadlang sa pagtakas ng init.", "en": "A drink stays hot inside a thermos because its double wall with a gap between blocks heat from escaping.", "bis": "Magpabiling init ang ilimnon sulod sa thermos tungod kay ang doble nga bongbong niini nga may luna sa taliwala nagababag sa pag-ikyas sa init."}, "source": "NRC PS3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "neuron-nervous-system-g8", "domain": "LIVING_THINGS", "topic": "neurons carry nerve signals", "grades": [7, 8, 9, 10], "terms": ["neuron", "selula ng nerbiyo", "nerve cell", "utak", "brain", "nerbiyo", "nervous system", "sistema sa nerbiyo", "signal", "senyales", "mensahe", "neurona", "selula", "selyula"], "fact": {"tl": "Ang neuron ay ang selula ng ating nervous system na nagdadala ng mga senyales na elektrikal sa pagitan ng utak at iba't ibang bahagi ng katawan.", "en": "A neuron is the cell of our nervous system that carries fast electrical signals between the brain and the rest of the body.", "bis": "Ang neuron mao ang selula sa atong nervous system nga nagdala sa paspas nga elektrikal nga mga senyales tali sa utok ug sa ubang bahin sa lawas."}, "source": "NRC LS1; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pollination-pollinators-g5", "domain": "LIVING_THINGS", "topic": "animals help pollinate flowers", "grades": [4, 5, 6], "terms": ["pollinator", "bubuyog", "putyukan", "bee", "paru-paro", "alibangbang", "butterfly", "paniki", "bat", "nektar", "polinasyon"], "fact": {"tl": "Maraming hayop tulad ng bubuyog, paru-paro, at paniki ang tumutulong sa pollination habang sila ay naghahanap ng nektar sa mga bulaklak.", "en": "Many animals such as bees, butterflies, and bats help pollination as they search for nectar in flowers.", "bis": "Daghang mananap sama sa putyukan, alibangbang, ug paniki ang nagatabang sa pollination samtang nangita sila og nektar sa mga bulak."}, "source": "NRC LS2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "biomolecules-g9", "domain": "LIVING_THINGS", "topic": "the main biomolecules of living things", "grades": [8, 9, 10], "terms": ["biomolecules", "biomolecula", "carbohydrates", "karbohidrat", "protina", "protein", "taba", "tambok", "lipid", "fats", "nucleic acid", "DNA", "selula", "molekula"], "fact": {"tl": "Ang mga biomolecules tulad ng carbohydrates, protina, taba (lipids), at nucleic acid ay ang mga molekula na bumubuo sa lahat ng nabubuhay na bagay.", "en": "Biomolecules such as carbohydrates, proteins, lipids (fats), and nucleic acids are the molecules that make up all living things.", "bis": "Ang mga biomolecules sama sa carbohydrates, protina, tambok (lipids), ug nucleic acid mao ang mga molekula nga naghimo sa tanang buhing butang."}, "source": "NRC LS1; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-star-g5", "domain": "EARTH_SPACE", "topic": "the Sun is a star", "grades": [4, 5, 6], "terms": ["araw", "adlaw", "sun", "bituin", "bitoon", "star", "init", "kainit", "liwanag", "kahayag", "gas", "napakalaki", "pinakamalapit", "solar system"], "fact": {"tl": "Ang Araw ay isang bituin—isang napakalaking bola ng mainit na gas—at ito ang pinakamalapit na bituin sa Daigdig.", "en": "The Sun is a star—a huge ball of hot, glowing gas—and it is the closest star to Earth.", "bis": "Ang Adlaw usa ka bituon—usa ka dako kaayo nga bola sa init nga gas—ug kini mao ang pinakaduol nga bituon sa Kalibotan."}, "source": "NRC ESS1; DepEd G5; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-energy-life-g5", "domain": "EARTH_SPACE", "topic": "the Sun gives Earth light and heat", "grades": [4, 5, 6], "terms": ["araw", "adlaw", "sun", "init", "kainit", "liwanag", "kahayag", "enerhiya", "energy", "halaman", "tanom", "photosynthesis", "buhay", "kabuhi", "panahon"], "fact": {"tl": "Ang Araw ang nagbibigay ng liwanag at init sa Daigdig, at ang enerhiyang ito ang ginagamit ng mga halaman upang gumawa ng pagkain at nagpapanatili ng buhay sa ating planeta.", "en": "The Sun gives Earth light and heat, and plants use this energy to make food, keeping life on our planet going.", "bis": "Ang Adlaw maoy naghatag og kahayag ug init sa Kalibotan, ug kining enerhiya gigamit sa mga tanom aron makahimo og pagkaon, nga nagpadayon sa kinabuhi sa atong planeta."}, "source": "NRC ESS1; PS3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "coleto-kuling-bird-g4", "domain": "LIVING_THINGS", "topic": "Coleto (kuling) starling endemic Philippine bird", "grades": [4, 5], "terms": ["kuling", "koleto", "kuling-panot", "sal-ing", "iling", "coleto", "ibon", "langgam", "starling", "endemic bird", "Philippine bird", "upaw nga nawong", "katutubong ibon", "kalbo", "endemic"], "fact": {"tl": "Ang kuling o koleto ay isang itim na ibon na matatagpuan lamang sa Pilipinas, at kilala ito sa kanyang kalbo at kulay-rosas na mukha na walang balahibo.", "en": "The coleto, also called kuling, is a black starling found only in the Philippines, known for its bald, bare, pinkish face that has no feathers.", "bis": "Ang kuling o sal-ing usa ka itom nga langgam nga makita lamang sa Pilipinas, ug nailhan kini sa iyang upaw ug pula nga nawong nga walay balahibo."}, "source": "Coleto (Sarcops calvus), Wikipedia / Birds of the World; local names per PH birding sources", "generator": "claude-workflow", "reviewed": false},
  {"id": "coleto-kuling-diet-g5", "domain": "LIVING_THINGS", "topic": "Coleto (kuling) starling diet fruit seeds insects", "grades": [5, 6], "terms": ["kuling", "koleto", "sal-ing", "coleto", "ibon", "langgam", "prutas", "buto", "liso", "insekto", "kumakain ng prutas", "fruit eater", "frugivore", "nagakaon ug prutas", "kumain", "kinakain"], "fact": {"tl": "Ang kuling ay kumakain ng mga prutas, buto, at insekto, kaya nakatutulong ito sa kalikasan dahil naikakalat nito ang mga buto ng halaman.", "en": "The coleto eats fruits, seeds, and insects, so it helps nature by spreading plant seeds wherever it goes.", "bis": "Ang kuling nagakaon ug mga prutas, liso, ug insekto, busa makatabang kini sa kinaiyahan kay makasabwag kini sa mga liso sa tanom."}, "source": "Coleto (Sarcops calvus) diet, encyclopedia consensus; local names per PH birding sources", "generator": "claude-workflow", "reviewed": false},
  {"id": "fire-evacuation-floor-plan-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "fire safety evacuation plan", "grades": [4, 5], "terms": ["sunog", "apoy", "kalayo", "ligtas na labasan", "fire exit", "labasan", "gawasanan", "luwasanan", "paglikas", "pagbakwit", "evacuation", "ruta", "agianan", "floor plan", "plano ng gusali", "mapa sa building", "usok", "aso", "kaligtasan", "kaluwasan", "fire drill", "alarma", "emergency", "emerhensya"], "fact": {"tl": "Ang fire evacuation floor plan ay isang mapa ng gusali na nagpapakita ng pinakamabilis at pinakaligtas na ruta papunta sa labasan kapag may sunog, kaya dapat itong nakadikit sa dingding at alam ng lahat bago pa mangyari ang emergency.", "en": "A fire evacuation floor plan is a map of a building that shows the fastest and safest route to the exits during a fire, so it is posted on the wall and learned by everyone before an emergency ever happens.", "bis": "Ang fire evacuation floor plan usa ka mapa sa building nga nagpakita sa pinakapaspas ug pinakaluwas nga agianan padulong sa gawasanan kon adunay sunog, mao nga gibutang kini sa bongbong ug nahibaloan sa tanan sa wala pa moabot ang emerhensya."}, "source": "DepEd disaster-risk-reduction; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "padyak-pedal-force-g4", "domain": "FORCE_MOTION_ENERGY", "topic": "pushing pedals makes a padyak move", "grades": [3, 4, 5], "terms": ["padyak", "pedicab", "trapilyo", "tapak", "pedal", "puwersa", "puersa", "tulak", "gulong", "wheel", "lakas ng tao", "human force", "pedal force", "tumatakbo", "modog", "kusog", "tao", "tapak sa pedal", "force", "motion"], "fact": {"tl": "Ang padyak ay gumagalaw kapag itinutulak ng paa ng tao ang mga pedal, na nagpapaikot sa mga gulong gamit ang lakas ng katawan, hindi ng makina.", "en": "A padyak (pedal trike) moves when a person's feet push the pedals, turning the wheels using body power instead of an engine.", "bis": "Ang padyak molihok kung itulod sa tiil sa tawo ang mga pedal, nga maoy nagpatuyok sa mga ligid pinaagi sa kusog sa lawas, dili sa makina."}, "source": "NRC PS2.A (forces and motion); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "jeepney-engine-energy-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "a jeepney engine turns fuel into motion", "grades": [5, 6, 7], "terms": ["dyip", "jeepney", "dyipni", "makina", "engine", "gasolina", "diesel", "krudo", "enerhiya", "energy", "kemikal na enerhiya", "chemical energy", "galaw", "kinetic", "tumatakbo", "modagan", "sunog", "combustion", "pasahero", "force", "motion"], "fact": {"tl": "Ang makina ng dyip ay nagsusunog ng krudo o diesel upang gawing enerhiya ng galaw ang kemikal na enerhiya ng gasolina, kaya umaandar ang sasakyan.", "en": "A jeepney's engine burns fuel like diesel to change the fuel's stored chemical energy into energy of motion, making the vehicle move.", "bis": "Ang makina sa dyip nagasunog ug diesel aron himuon nga enerhiya sa paglihok ang kemikal nga enerhiya sa sugnod, mao nga modagan ang sakyanan."}, "source": "NRC PS3.A/PS3.B (energy transfer); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "vehicle-wheels-friction-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "wheels let vehicles roll with less friction", "grades": [4, 5, 6], "terms": ["gulong", "wheel", "ligid", "traysikel", "tricycle", "padyak", "dyip", "pagligid", "rolling", "friction", "kuskos", "pagkikiskis", "kiskis", "madaling itulak", "rolling friction", "puwersa", "force", "motion"], "fact": {"tl": "Ang mga gulong ng traysikel at iba pang sasakyan ay gumugulong sa lupa, kaya mas kaunting friction (pagkikiskis) ang humahadlang at mas madaling itulak ang mabigat na karga.", "en": "The round wheels of a tricycle and other vehicles roll along the ground, so there is much less friction holding them back, making heavy loads easier to push.", "bis": "Ang mga ligid sa traysikel ug uban pang sakyanan moligid sa yuta, busa gamay ra ang friction (pagkiskis) nga nagpugong, ug mas sayon iduso ang bug-at nga karga."}, "source": "NRC PS2.A (forces, friction); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "salt-farming-evaporation-g5", "domain": "MATTER", "topic": "sun evaporates seawater to leave salt", "grades": [4, 5, 6], "terms": ["asin", "salt", "asinan", "salt bed", "salt farm", "tubig-dagat", "seawater", "tubig sa dagat", "init ng araw", "sun heat", "singaw", "evaporation", "pagsingaw", "natural na asin", "pag-asin", "magsasaka ng asin", "salt farmer", "naiiwan", "nagkristal", "crystal", "matter", "dagat"], "fact": {"tl": "Sa paggawa ng asin, ipinipasok ang tubig-dagat sa mababaw na asinan at hinahayaang singawin ng init ng araw ang tubig, kaya naiiwan ang asin.", "en": "To make sea salt, seawater is let into shallow beds and the sun's heat evaporates the water, leaving the salt behind.", "bis": "Sa paghimo ug asin, ang tubig-dagat gipasulod sa mabaw nga asinan ug gipasingaw sa init sa adlaw ang tubig, mao nga mabilin ang asin."}, "source": "NRC PS1.A (states of matter, evaporation); DepEd G5 (changes in matter)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sorbetes-ice-salt-g6", "domain": "MATTER", "topic": "salt and ice make a mix cold enough to freeze ice cream", "grades": [5, 6, 7], "terms": ["sorbetes", "dirty ice cream", "yelo", "ice", "asin", "salt", "lamig", "cold", "nagyeyelo", "freezing point", "punto ng pagyeyelo", "natutunaw", "melting", "sorbetera", "ice cream", "magpalamig", "nagpapalamig", "tunaw", "frozen", "matter", "init"], "fact": {"tl": "Sa paggawa ng sorbetes, ang asin na inihahalo sa yelo ay nagpapababa ng punto ng pagyeyelo, kaya nagiging napakalamig nito para tumigas ang halo sa loob.", "en": "When making sorbetes, salt mixed with ice lowers the freezing point so the ice gets cold enough to freeze the ice-cream mixture inside.", "bis": "Sa paghimo ug sorbetes, ang asin nga gisagol sa yelo nagpaubos sa punto sa pagyelo, mao nga mahimong bugnaw kaayo aron mogahi ang sagol sa sulod."}, "source": "NRC PS1.A (states of matter, freezing); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tinapa-smoking-preserves-fish-g6", "domain": "LIVING_THINGS", "topic": "smoking and drying preserve fish", "grades": [5, 6, 7], "terms": ["tinapa", "smoked fish", "isda", "fish", "usok", "smoke", "aso", "init", "heat", "pagtatanggal ng tubig", "drying", "pagpapatuyo", "preservation", "pag-iimbak", "bakterya", "bacteria", "mikrobyo", "microbe", "hindi madaling masira", "panangtago", "asoy", "tinap-anan"], "fact": {"tl": "Ang isda ay ginagawang tinapa sa pamamagitan ng pagpapausok at pag-init na nagtatanggal ng tubig dito, kaya hirap dumami ang bakteryang nagpapabulok ng isda.", "en": "Fish is turned into tinapa by smoking and heating that remove water from it, making it hard for spoilage bacteria to grow.", "bis": "Ang isda himuong tinapa pinaagi sa pag-aso ug pag-init nga nagtangtang sa tubig niini, mao nga lisod modaghan ang bakterya nga maoy makapadunot sa isda."}, "source": "NRC LS1.C / LS2 (microbes, decomposition); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "valence-electrons-outer-shell-g9", "domain": "MATTER", "topic": "valence electrons outermost shell", "grades": [9, 10], "terms": ["valence electron", "valence electrons", "valence", "outer shell", "outermost shell", "outer electrons", "valence elektron", "panlabas na elektron", "panlabas na shell", "bisa sa pagbugkos", "gawas nga elektron", "pinakagawas nga shell", "valensya elektron", "bonding electrons"], "fact": {"tl": "Ang valence electrons ay ang mga elektron sa pinakalabas na shell ng isang atomo, at sila ang nagpapasya kung paano makikipag-bond ang atomo sa ibang atomo.", "en": "Valence electrons are the electrons in an atom's outermost shell, and they determine how that atom will bond with other atoms.", "bis": "Ang valence electrons mao ang mga elektron sa pinakagawas nga shell sa usa ka atomo, ug sila ang magtino kon unsaon pagbugkos sa atomo sa ubang atomo."}, "source": "AAAS 4D/H2; NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "octet-rule-eight-electrons-g9", "domain": "MATTER", "topic": "octet rule stable eight electrons", "grades": [9, 10], "terms": ["octet rule", "octet", "walong elektron", "eight electrons", "stable", "matatag", "lubos nga", "panuntunan sa octet", "walo ka elektron", "full outer shell", "puno na shell", "noble gas configuration", "stability"], "fact": {"tl": "Ayon sa octet rule, gusto ng karamihang atomo na magkaroon ng walong elektron sa panlabas nilang shell upang maging matatag, kaya sila nagbi-bond.", "en": "According to the octet rule, most atoms tend to bond so that they end up with eight electrons in their outer shell, which makes them stable.", "bis": "Sumala sa octet rule, gusto sa kadaghanan nga atomo nga makabaton ug walo ka elektron sa ilang gawas nga shell aron malig-on, mao nga sila magbugkos."}, "source": "AAAS 4D/H2; NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-atoms-bond-lower-energy-g10", "domain": "MATTER", "topic": "atoms bond to lower energy stability", "grades": [9, 10], "terms": ["why atoms bond", "bakit nagbi-bond", "lower energy", "mas mababang enerhiya", "matatag", "stability", "binding energy", "stable molecule", "ngano nga magbugkos", "ubos nga enerhiya", "malig-on", "minimize energy", "bond formation", "pagbugkos"], "fact": {"tl": "Nagbi-bond ang mga atomo dahil mas mababa ang enerhiya at mas matatag sila kapag magkasama kaysa kapag hiwa-hiwalay.", "en": "Atoms bond because together they have lower energy and are more stable than they are when separated.", "bis": "Magbugkos ang mga atomo tungod kay mas ubos ang enerhiya ug mas malig-on sila kon magkauban kaysa kon magbulag."}, "source": "NRC PS1.A (grade 12): a stable molecule has less energy than the separated atoms", "generator": "claude-workflow", "reviewed": false},
  {"id": "binding-energy-pull-apart-g10", "domain": "MATTER", "topic": "binding energy needed to break bond", "grades": [9, 10], "terms": ["binding energy", "bond energy", "enerhiya ng bond", "break a bond", "pag-break ng bond", "sirain ang bond", "buwagin", "kailangang enerhiya", "energy to break", "gikinahanglan nga enerhiya", "pagbugto sa bond", "putlon ang bond", "bond breaking"], "fact": {"tl": "Kailangan ng enerhiya upang sirain ang isang bond at ihiwalay ang mga atomo, kaya ang matibay na bond ay mas mahirap buwagin.", "en": "Energy is needed to break a bond and pull the atoms apart, so a stronger bond is harder to break.", "bis": "Gikinahanglan ang enerhiya aron putlon ang usa ka bond ug bulagon ang mga atomo, mao nga ang lig-on nga bond mas lisod bugtoon."}, "source": "NRC PS1.A (grade 12): one must provide at least the binding energy to take a molecule apart", "generator": "claude-workflow", "reviewed": false},
  {"id": "noble-gases-stable-no-bond-g10", "domain": "MATTER", "topic": "noble gases full shell rarely bond", "grades": [9, 10], "terms": ["noble gas", "noble gases", "helium", "neon", "argon", "full shell", "puno na shell", "hindi nagbi-bond", "matatag na", "stable", "inert", "wala magbugkos", "puno nga shell", "malig-on na", "helyo"], "fact": {"tl": "Ang mga noble gas gaya ng helium at neon ay halos hindi nagbi-bond dahil puno na ang kanilang panlabas na shell, kaya matatag na sila.", "en": "Noble gases like helium and neon hardly ever bond because their outer shell is already full, so they are already stable.", "bis": "Ang mga noble gas sama sa helium ug neon halos dili magbugkos tungod kay puno na ang ilang gawas nga shell, mao nga malig-on na sila."}, "source": "AAAS 4D/H2; NRC PS1.A (noble-gas electron configuration)", "generator": "claude-workflow", "reviewed": false},
  {"id": "cation-positive-ion-loses-electron-g9", "domain": "MATTER", "topic": "cation positive ion loses electrons", "grades": [9, 10], "terms": ["cation", "positive ion", "ion", "nawalan ng elektron", "lost electron", "positibong charge", "metal ion", "sodium ion", "Na+", "nawad-an ug elektron", "positibo nga ion", "metals lose electrons", "katyon", "nagbigay ng elektron"], "fact": {"tl": "Kapag nawalan ng elektron ang isang atomo, nagiging positibong sisingilin na ion ito na tinatawag na cation, gaya ng sodium ion na Na⁺.", "en": "When an atom loses electrons it becomes a positively charged ion called a cation, such as the sodium ion Na⁺.", "bis": "Kon mawad-an ug elektron ang usa ka atomo, mahimo kining positibo nga ion nga gitawag ug cation, sama sa sodium ion nga Na⁺."}, "source": "AAAS 4D/H2; NRC PS1.A (electron transfer forms ions)", "generator": "claude-workflow", "reviewed": false},
  {"id": "anion-negative-ion-gains-electron-g9", "domain": "MATTER", "topic": "anion negative ion gains electrons", "grades": [9, 10], "terms": ["anion", "negative ion", "ion", "nakakuha ng elektron", "gained electron", "negatibong charge", "chloride ion", "Cl-", "nakadawat ug elektron", "negatibo nga ion", "nonmetals gain electrons", "anyon", "tumanggap ng elektron"], "fact": {"tl": "Kapag nakakuha ng dagdag na elektron ang isang atomo, nagiging negatibong sisingilin na ion ito na tinatawag na anion, gaya ng chloride ion na Cl⁻.", "en": "When an atom gains extra electrons it becomes a negatively charged ion called an anion, such as the chloride ion Cl⁻.", "bis": "Kon makadawat ug dugang nga elektron ang usa ka atomo, mahimo kining negatibo nga ion nga gitawag ug anion, sama sa chloride ion nga Cl⁻."}, "source": "AAAS 4D/H2; NRC PS1.A (electron transfer forms ions)", "generator": "claude-workflow", "reviewed": false},
  {"id": "opposite-charges-attract-ionic-g9", "domain": "MATTER", "topic": "opposite charges attract in ionic bond", "grades": [9, 10], "terms": ["opposite charges attract", "magkasalungat na charge", "magkasalungat na singil", "electrical attraction", "akit", "humihila", "positive negative", "ionic attraction", "magkasumpaki nga charge", "nagbira", "nagdani", "electrostatic", "atraksyon", "elektrikal na puwersa"], "fact": {"tl": "Sa ionic bond, ang positibo at negatibong mga ion ay naghihilahan dahil ang magkasalungat na electric charge ay nag-aakitan.", "en": "In an ionic bond, the positive and negative ions pull toward each other because opposite electric charges attract.", "bis": "Sa ionic bond, ang positibo ug negatibo nga mga ion magbinirahay tungod kay ang magkasumpaki nga electric charge magdinanihay."}, "source": "NRC PS1.A: electrical attractions between charged particles cause atoms to form molecules and structures", "generator": "claude-workflow", "reviewed": false},
  {"id": "nacl-crystal-lattice-g9", "domain": "MATTER", "topic": "salt forms repeating crystal lattice", "grades": [9, 10], "terms": ["salt crystal", "asin", "sodium chloride", "NaCl", "crystal lattice", "kristal", "paulit-ulit na ayos", "repeating pattern", "ionic crystal", "kristal nga ayo", "table salt", "lattice", "balikbalik nga han-ay", "tumpok ng ion"], "fact": {"tl": "Sa table salt (NaCl), ang mga sodium at chloride ion ay nakaayos sa paulit-ulit na pattern na tinatawag na crystal lattice, hindi sa hiwalay na mga molekula.", "en": "In table salt (NaCl), the sodium and chloride ions are arranged in a repeating pattern called a crystal lattice, not in separate molecules.", "bis": "Sa table salt (NaCl), ang mga sodium ug chloride ion gihan-ay sa balikbalik nga pattern nga gitawag ug crystal lattice, dili sa bulag nga mga molekula."}, "source": "NRC PS1.A: atoms combine to form extended structures such as crystals; AAAS 4D/H7", "generator": "claude-workflow", "reviewed": false},
  {"id": "covalent-shared-pair-bond-g9", "domain": "MATTER", "topic": "covalent bond is a shared electron pair", "grades": [9, 10], "terms": ["shared electron pair", "shared pair", "covalent bond", "magkahati", "pinaghahatian", "shared electrons", "single bond", "ibinabahagi", "gipanag-iya nga elektron", "gibahin nga elektron", "shared nga pares", "electron pair", "pares ng elektron"], "fact": {"tl": "Ang isang covalent bond ay binubuo ng isang pares ng elektron na pinaghahatian ng dalawang atomo na parehong humihila sa parehong elektron.", "en": "A single covalent bond is made of one pair of electrons shared between two atoms, with both atoms pulling on the same electrons.", "bis": "Ang usa ka covalent bond gilangkoban sa usa ka pares sa elektron nga gibahin sa duha ka atomo nga managsama nga nagbira sa samang elektron."}, "source": "AAAS 4D/H2: atoms form bonds by sharing electrons", "generator": "claude-workflow", "reviewed": false},
  {"id": "co2-double-bond-g10", "domain": "MATTER", "topic": "carbon dioxide has double bonds", "grades": [9, 10], "terms": ["double bond", "carbon dioxide", "CO2", "dobleng bond", "two pairs", "dalawang pares", "shared two pairs", "doble nga bond", "duha ka pares", "C=O", "dalawang elektron pair", "double covalent bond"], "fact": {"tl": "Sa carbon dioxide (CO₂), ang carbon at bawat oxygen ay naghahati ng dalawang pares ng elektron, kaya may double bond sa pagitan nila.", "en": "In carbon dioxide (CO₂), the carbon and each oxygen share two pairs of electrons, so there is a double bond between them.", "bis": "Sa carbon dioxide (CO₂), ang carbon ug ang matag oxygen nagbahin ug duha ka pares sa elektron, mao nga adunay double bond tali kanila."}, "source": "AAAS 4D/H2, 4D/H8 (electron sharing, molecular configuration)", "generator": "claude-workflow", "reviewed": false},
  {"id": "nitrogen-triple-bond-g10", "domain": "MATTER", "topic": "nitrogen molecule triple bond strong", "grades": [9, 10], "terms": ["triple bond", "nitrogen", "N2", "tatlong pares", "three pairs", "matibay na bond", "strong bond", "nitrogen gas", "triple nga bond", "tulo ka pares", "lig-on nga bond", "N≡N", "matigas na bond", "nitroheno"], "fact": {"tl": "Ang nitrogen gas (N₂) ay may triple bond kung saan tatlong pares ng elektron ang pinaghahatian, kaya napakatibay at mahirap putulin nito.", "en": "Nitrogen gas (N₂) has a triple bond in which three pairs of electrons are shared, which makes it very strong and hard to break.", "bis": "Ang nitrogen gas (N₂) adunay triple bond diin tulo ka pares sa elektron ang gibahin, mao nga lig-on kaayo ug lisod bugtoon."}, "source": "AAAS 4D/H2 (electron sharing); NRC PS1.A (bond strength / binding energy)", "generator": "claude-workflow", "reviewed": false},
  {"id": "polar-bond-unequal-sharing-g10", "domain": "MATTER", "topic": "polar bond unequal electron sharing", "grades": [10], "terms": ["polar bond", "polar", "hindi pantay na hati", "unequal sharing", "partial charge", "bahagyang charge", "electronegativity", "polar molecule", "dili patas nga bahin", "partial nga charge", "polar nga bond", "polar covalent", "water polar", "tubig polar"], "fact": {"tl": "Sa polar bond, hindi pantay ang hatian ng elektron kaya ang isang dulo ng bond ay bahagyang negatibo at ang kabila ay bahagyang positibo.", "en": "In a polar bond, the electrons are shared unequally, so one end of the bond is slightly negative and the other end is slightly positive.", "bis": "Sa polar bond, dili patas ang pagbahin sa elektron mao nga ang usa ka tumoy sa bond medyo negatibo ug ang pikas medyo positibo."}, "source": "NRC PS1.A; AAAS 4D/H8 (electron distribution determines molecular properties)", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-polar-bent-shape-g10", "domain": "MATTER", "topic": "water is a polar bent molecule", "grades": [10], "terms": ["water polar", "tubig polar", "bent shape", "baluktot na hugis", "H2O shape", "polar molecule", "hubog nga porma", "baliko nga porma", "bent molecule", "water molecule", "molekula ng tubig", "polar nga molekula", "hugis ng tubig", "porma sa tubig"], "fact": {"tl": "Ang molekula ng tubig (H₂O) ay may baluktot na hugis at polar ito, kaya ang panig ng oxygen ay bahagyang negatibo at ang panig ng hydrogen ay bahagyang positibo.", "en": "A water molecule (H₂O) has a bent shape and is polar, so the oxygen side is slightly negative and the hydrogen side is slightly positive.", "bis": "Ang molekula sa tubig (H₂O) adunay baliko nga porma ug polar kini, mao nga ang bahin sa oxygen medyo negatibo ug ang bahin sa hydrogen medyo positibo."}, "source": "AAAS 4D/H8 (molecular configuration determines properties); NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "chemical-formula-meaning-g8", "domain": "MATTER", "topic": "chemical formula shows kinds of atoms", "grades": [8, 9], "terms": ["chemical formula", "pormula", "kemikal na pormula", "formula", "klase ng atomo", "kinds of atoms", "elemento sa pormula", "kemikal nga pormula", "klase sa atomo", "molecular formula", "H2O CO2", "simbolo ng elemento", "element symbols"], "fact": {"tl": "Ang isang chemical formula gaya ng H₂O ay nagsasaad kung anong mga elemento at ilang atomo ng bawat isa ang naroroon sa isang compound.", "en": "A chemical formula like H₂O tells which elements and how many atoms of each are present in a compound.", "bis": "Ang usa ka chemical formula sama sa H₂O nagpakita kon unsa nga mga elemento ug pila ka atomo sa matag usa ang naa sa usa ka compound."}, "source": "AAAS 4D/M13, 4D/H7 (composition of substances)", "generator": "claude-workflow", "reviewed": false},
  {"id": "formula-subscript-meaning-g8", "domain": "MATTER", "topic": "subscript number of atoms in formula", "grades": [8, 9], "terms": ["subscript", "maliit na numero", "subscript number", "bilang ng atomo", "number of atoms", "H2O subscript", "gamay nga numero", "gidaghanon sa atomo", "two hydrogen", "dalawang hydrogen", "ilang atomo", "pila ka atomo"], "fact": {"tl": "Ang maliit na numero sa ibaba ng isang formula, gaya ng 2 sa H₂O, ay nagsasaad kung ilang atomo ng elementong iyon ang nasa molekula.", "en": "The small lowered number in a formula, like the 2 in H₂O, tells how many atoms of that element are in the molecule.", "bis": "Ang gamay nga numero sa ubos sa usa ka formula, sama sa 2 sa H₂O, nagpakita kon pila ka atomo niana nga elemento ang naa sa molekula."}, "source": "AAAS 4D/M13, 4D/H7", "generator": "claude-workflow", "reviewed": false},
  {"id": "polyatomic-ion-group-g10", "domain": "MATTER", "topic": "polyatomic ion charged group of atoms", "grades": [10], "terms": ["polyatomic ion", "pangkat ng atomo", "group of atoms", "charged group", "sulfate", "nitrate", "carbonate", "ammonium", "may charge na pangkat", "grupo sa atomo", "may charge nga grupo", "polyatomic", "OH hydroxide", "may singil na grupo"], "fact": {"tl": "Ang isang polyatomic ion ay isang pangkat ng mga atomong magkakabit na may kabuuang electric charge, gaya ng sulfate (SO₄²⁻) at ammonium (NH₄⁺).", "en": "A polyatomic ion is a group of bonded atoms that together carry an electric charge, such as sulfate (SO₄²⁻) and ammonium (NH₄⁺).", "bis": "Ang usa ka polyatomic ion mao ang usa ka grupo sa mga atomo nga nagbugkos nga adunay tibuok electric charge, sama sa sulfate (SO₄²⁻) ug ammonium (NH₄⁺)."}, "source": "NRC PS1.A; AAAS 4D/H2 (ions as charged combinations)", "generator": "claude-workflow", "reviewed": false},
  {"id": "ionic-compound-high-melting-g10", "domain": "MATTER", "topic": "ionic compounds high melting point solid", "grades": [10], "terms": ["ionic compound", "mataas na melting point", "high melting point", "matigas", "solid", "kristal", "asin", "mahirap matunaw", "taas nga melting point", "lisod matunaw", "gahi nga", "ionic nga compound", "brittle", "buwagon"], "fact": {"tl": "Ang mga ionic compound gaya ng asin ay matigas na solido at may napakataas na melting point dahil napakalakas ng hila ng kanilang magkasalungat na ion.", "en": "Ionic compounds like salt are hard solids with very high melting points because the pull between their opposite ions is very strong.", "bis": "Ang mga ionic compound sama sa asin gahi nga solido ug adunay taas kaayo nga melting point tungod kay lig-on kaayo ang bira tali sa ilang magkasumpaki nga ion."}, "source": "NRC PS1.A: properties of materials understood from forces between constituents", "generator": "claude-workflow", "reviewed": false},
  {"id": "ionic-solution-conducts-g10", "domain": "MATTER", "topic": "dissolved ionic compound conducts electricity", "grades": [10], "terms": ["ionic solution conducts", "natunaw na asin", "dissolved salt", "conducts electricity", "nagdadala ng kuryente", "free ions", "malayang ion", "saltwater conducts", "natunaw nga asin", "magdala ug koryente", "gawasnon nga ion", "electrolyte", "tubig na may asin"], "fact": {"tl": "Kapag natunaw sa tubig ang isang ionic compound gaya ng asin, malayang gumagalaw ang mga ion at nagagawang magdala ng kuryente ang tubig.", "en": "When an ionic compound like salt dissolves in water, its ions move freely and let the water conduct electricity.", "bis": "Kon matunaw sa tubig ang usa ka ionic compound sama sa asin, ang mga ion molihok nga gawasnon ug makahimo ang tubig sa pagdala ug koryente."}, "source": "NRC PS1.A: conductivity understood from atomic/molecular constituents and forces", "generator": "claude-workflow", "reviewed": false},
  {"id": "molecular-compound-properties-g10", "domain": "MATTER", "topic": "covalent molecular compounds low melting point", "grades": [10], "terms": ["molecular compound", "covalent compound", "mababang melting point", "low melting point", "madaling matunaw", "gas o likido", "sugar water", "ubos nga melting point", "sayon matunaw", "molecular nga compound", "covalent nga compound", "soft", "malambot"], "fact": {"tl": "Maraming molecular o covalent compound gaya ng asukal at tubig ay may mababang melting point at madalas gas o likido, dahil mas mahina ang hilahan sa pagitan ng kanilang mga molekula.", "en": "Many molecular or covalent compounds like sugar and water have low melting points and are often gases or liquids, because the pull between their separate molecules is weaker.", "bis": "Daghang molecular o covalent compound sama sa asukar ug tubig adunay ubos nga melting point ug kasagaran gas o likido, tungod kay mas huyang ang bira tali sa ilang bulag nga mga molekula."}, "source": "NRC PS1.A; AAAS 4D/H8 (properties from molecular structure and intermolecular forces)", "generator": "claude-workflow", "reviewed": false},
  {"id": "metallic-malleable-bond-g10", "domain": "MATTER", "topic": "metallic bond makes metals bendable", "grades": [9, 10], "terms": ["malleable", "nababaluktot", "nahuhulma", "bendable metal", "metallic bond", "metals bend", "mahimong baluktoton", "mahimong hulmahon", "ductile", "bakal na nababaluktot", "shape metal"], "fact": {"tl": "Dahil malaya ang galaw ng mga elektron sa metallic bond, kayang hulmahin at baluktutin ang mga metal nang hindi sila nababasag.", "en": "Because the electrons move freely in a metallic bond, metals can be shaped and bent without breaking apart.", "bis": "Tungod kay gawasnon ang lihok sa mga elektron sa metallic bond, ang mga metal mahimong hulmahon ug balukton nga dili maguba."}, "source": "NRC PS1.A: hardness and conductivity understood from bonding (sea of electrons)", "generator": "claude-workflow", "reviewed": false},
  {"id": "electronegativity-pull-electrons-g10", "domain": "MATTER", "topic": "electronegativity pull on shared electrons", "grades": [10], "terms": ["electronegativity", "lakas humila ng elektron", "pull on electrons", "atraksyon sa elektron", "electron attraction", "kusog sa pagbira", "lakas ng hila", "kakayahang humila", "fluorine oxygen", "humihila ng elektron", "magbira ug elektron"], "fact": {"tl": "Ang electronegativity ay ang lakas ng paghila ng isang atomo sa mga pinaghahatiang elektron, at ang malaking pagkakaiba nito ay nagdudulot ng polar o ionic na bond.", "en": "Electronegativity is how strongly an atom pulls on shared electrons, and a big difference in it leads to a polar or ionic bond.", "bis": "Ang electronegativity mao ang kakusog sa pagbira sa usa ka atomo sa gibahin nga mga elektron, ug ang dako nga kalainan niini mosangpot sa polar o ionic nga bond."}, "source": "NRC PS1.A (electrical forces between atoms); AAAS 4D/H2", "generator": "claude-workflow", "reviewed": false},
  {"id": "bonding-is-chemical-change-g9", "domain": "MATTER", "topic": "making and breaking bonds is a chemical change", "grades": [9, 10], "terms": ["chemical change", "kemikal na pagbabago", "bagong substance", "new substance", "making bonds", "breaking bonds", "paggawa ng bond", "kemikal nga kausaban", "bag-ong substansiya", "paghimo ug bond", "pagbugto ug bond", "chemical reaction", "reaksyong kemikal", "rearrange atoms"], "fact": {"tl": "Ang paggawa at pagputol ng mga chemical bond ay isang chemical change, dahil muling naiaayos ang mga atomo upang bumuo ng bagong substansiya na may bagong katangian.", "en": "Making and breaking chemical bonds is a chemical change, because the atoms are rearranged into a new substance with new properties.", "bis": "Ang paghimo ug pagbugto sa mga chemical bond usa ka chemical change, tungod kay ang mga atomo gihan-ay pag-usab aron mahimong bag-ong substansiya nga adunay bag-ong kinaiya."}, "source": "AAAS 4D/M13: substances combine when atoms combine in new ways; NRC PS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "atoms-conserved-in-bonding-g9", "domain": "MATTER", "topic": "atoms conserved when bonds rearrange", "grades": [9, 10], "terms": ["atoms conserved", "hindi nawawala ang atomo", "conservation of atoms", "parehong atomo", "same atoms", "rearrange", "muling ayos", "wala mawala nga atomo", "managsama nga atomo", "han-ay pag-usab", "conservation of mass", "konserbasyon ng atomo", "balance equation"], "fact": {"tl": "Sa pagbuo ng bagong bond, hindi nawawala o nadaragdagan ang mga atomo; muli lamang silang naiaayos, kaya pareho ang mga elemento bago at pagkatapos.", "en": "When new bonds form, no atoms are lost or created; they are only rearranged, so the same elements are present before and after.", "bis": "Sa paghimo ug bag-ong bond, walay atomo nga mawala o madugang; gihan-ay lang sila pag-usab, mao nga managsama ang mga elemento sa wala pa ug human."}, "source": "AAAS 4D/M12, 4D/M13; NRC PS1.B (atoms are conserved)", "generator": "claude-workflow", "reviewed": false},
  {"id": "bond-energy-released-absorbed-g10", "domain": "MATTER", "topic": "bonding releases or absorbs energy", "grades": [10], "terms": ["bond energy released", "naglalabas ng enerhiya", "releases energy", "sumisipsip ng enerhiya", "absorbs energy", "nagpapainit", "exothermic", "nagbuga ug enerhiya", "nagsuyup ug enerhiya", "init nga reaksyon", "energy change", "pagbabago ng enerhiya", "burning fuel"], "fact": {"tl": "Kapag nagbabago ang mga bond sa isang reaksyon, may enerhiyang inilalabas o sinisipsip, kaya ang pagsunog ng gasolina ay naglalabas ng init.", "en": "When bonds change in a reaction, energy is either released or absorbed, which is why burning fuel gives off heat.", "bis": "Kon mausab ang mga bond sa usa ka reaksyon, adunay enerhiya nga gibuhian o gisuyop, mao nga ang pagsunog sa gasolina mohatag ug kainit."}, "source": "NRC PS1.B (grade 8/12): chemical processes involve change in bonds and bond energies", "generator": "claude-workflow", "reviewed": false},
  {"id": "diatomic-molecule-same-element-g9", "domain": "MATTER", "topic": "diatomic molecule two atoms same element", "grades": [9, 10], "terms": ["diatomic molecule", "dalawang atomo", "two atoms", "O2 H2 N2", "oxygen gas molecule", "elementong nagbi-bond sa sarili", "duha ka atomo", "diatomic", "oxygen gas", "hydrogen gas", "molekula ng oxygen", "same element bond", "iisang elemento"], "fact": {"tl": "Ang ilang elemento gaya ng oxygen ay umiiral bilang diatomic molecule (O₂), kung saan dalawang atomo ng parehong elemento ang covalent na nagbi-bond.", "en": "Some elements like oxygen exist as diatomic molecules (O₂), in which two atoms of the same element are covalently bonded together.", "bis": "Ang ubang elemento sama sa oxygen naglungtad isip diatomic molecule (O₂), diin duha ka atomo sa samang elemento ang covalent nga nagbugkos."}, "source": "AAAS 4D/H2, 4D/H7 (atoms join in molecules)", "generator": "claude-workflow", "reviewed": false},
  {"id": "metals-nonmetals-bond-types-g10", "domain": "MATTER", "topic": "metal plus nonmetal ionic two nonmetals covalent", "grades": [10], "terms": ["metal nonmetal", "metal at di-metal", "ionic vs covalent", "anong klase ng bond", "type of bond", "two nonmetals", "dalawang di-metal", "metal ug dili-metal", "unsa nga bond", "duha ka dili-metal", "predict bond", "hulaan ang bond", "kind of bond"], "fact": {"tl": "Karaniwang nagiging ionic bond kapag nagsama ang metal at di-metal, samantalang covalent bond naman kapag dalawang di-metal ang nagsama.", "en": "A bond between a metal and a nonmetal is usually ionic, while a bond between two nonmetals is usually covalent.", "bis": "Ang bond tali sa metal ug dili-metal kasagaran ionic, samtang ang bond tali sa duha ka dili-metal kasagaran covalent."}, "source": "AAAS 4D/H2; NRC PS1.A (electron transfer vs sharing by element type)", "generator": "claude-workflow", "reviewed": false},
  {"id": "compound-different-from-elements-g8", "domain": "MATTER", "topic": "compound properties differ from its elements", "grades": [8, 9], "terms": ["compound new properties", "bagong katangian", "different properties", "iba sa elemento", "sodium chlorine salt", "compound vs element", "lahi sa elemento", "bag-ong kinaiya", "kausaban sa kinaiya", "table salt example", "asin galing sa sodium", "kakaibang katangian"], "fact": {"tl": "Kapag nagbi-bond ang mga atomo, ang compound na nabubuo ay may ibang katangian sa mga elemento nito—gaya ng asin na ligtas kainin kahit galing sa mapanganib na sodium at chlorine.", "en": "When atoms bond, the compound that forms has different properties from its elements—like table salt being safe to eat even though it is made from dangerous sodium and chlorine.", "bis": "Kon magbugkos ang mga atomo, ang compound nga maporma adunay lahi nga kinaiya gikan sa mga elemento niini—sama sa asin nga luwas kaonon bisan gama kini sa delikado nga sodium ug chlorine."}, "source": "AAAS 4D/M13 (new substances with new properties); NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "covalent-network-diamond-g10", "domain": "MATTER", "topic": "covalent network solid like diamond", "grades": [10], "terms": ["covalent network", "diamond", "diyamante", "matigas na kristal", "network solid", "carbon network", "lahat magkakabit", "covalent nga network", "gahi nga kristal", "diamante", "hardest", "pinakamatigas", "interconnected bonds", "magkadugtong na bond"], "fact": {"tl": "Sa diamond, ang bawat carbon atom ay covalent na nakakabit sa apat na ibang carbon sa isang malaking network, kaya ito ang pinakamatigas na natural na materyal.", "en": "In diamond, each carbon atom is covalently bonded to four other carbons in one giant network, which makes it the hardest natural material.", "bis": "Sa diamante, ang matag carbon atom covalent nga nagbugkos sa upat ka laing carbon sa usa ka dako nga network, mao nga kini ang pinakagahi nga natural nga materyal."}, "source": "NRC PS1.A: extended structures (crystals) and properties like hardness; AAAS 4D/H7", "generator": "claude-workflow", "reviewed": false},
  {"id": "atom-proton-charge-location-g8", "domain": "MATTER", "topic": "proton positive charge in nucleus", "grades": [7, 8, 9], "terms": ["proton", "positibo", "positive charge", "karga", "kargada", "nucleus", "nukleus", "gitna", "tunga", "atom", "atomo", "positibong karga", "may bigat", "mabigat", "subatomic", "partikulo"], "fact": {"tl": "Ang proton ay isang partikulo na may positibong (+) karga na matatagpuan sa nucleus o gitna ng atom, at ito ay may bigat na halos kapareho ng neutron.", "en": "A proton is a particle with a positive (+) charge found in the nucleus, or center, of an atom, and it has nearly the same mass as a neutron.", "bis": "Ang proton usa ka partikulo nga may positibo (+) nga karga nga makit-an sa nucleus o tunga sa atom, ug halos pareho ra og gibug-aton sa neutron."}, "source": "AAAS BSL 4D/H1; NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "atom-neutron-neutral-mass-g8", "domain": "MATTER", "topic": "neutron is neutral and adds mass", "grades": [7, 8, 9], "terms": ["neutron", "walang karga", "walay karga", "neutral", "neutrico", "nucleus", "nukleus", "bigat", "gibug-aton", "timbang", "atom", "atomo", "partikulo", "particle", "no charge", "katumbas ng proton"], "fact": {"tl": "Ang neutron ay isang partikulo sa nucleus na walang karga (neutral), at halos kasimbigat ito ng proton kaya nakadaragdag ito sa bigat ng atom.", "en": "A neutron is a particle in the nucleus that has no charge (neutral), and it weighs about the same as a proton, so it adds to the atom's mass.", "bis": "Ang neutron usa ka partikulo sa nucleus nga walay karga (neutral), ug halos pareho ra og gibug-aton sa proton mao nga makadugang kini sa gibug-aton sa atom."}, "source": "AAAS BSL 4D/H1; NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "atom-electron-light-negative-g8", "domain": "MATTER", "topic": "electron is light and negative", "grades": [7, 8, 9], "terms": ["electron", "elektron", "negatibo", "negative charge", "karga", "magaan", "kagaan", "gaan", "palibot", "paligid", "nucleus", "nukleus", "atom", "atomo", "napakagaan", "halos walang bigat", "shell", "umiikot"], "fact": {"tl": "Ang electron ay isang napakagaang partikulo na may negatibong (−) karga na gumagalaw sa paligid ng nucleus, at halos 2,000 beses na mas magaan ito kaysa sa proton o neutron.", "en": "An electron is a very light particle with a negative (−) charge that moves around the nucleus, and it is almost 2,000 times lighter than a proton or neutron.", "bis": "Ang electron usa ka gaan kaayo nga partikulo nga may negatibo (−) nga karga nga naglihok sa palibot sa nucleus, ug halos 2,000 ka pilo nga mas gaan kini kaysa proton o neutron."}, "source": "AAAS BSL 4D/H2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "atom-nucleus-tiny-heavy-g9", "domain": "MATTER", "topic": "nucleus is tiny but holds most mass", "grades": [8, 9, 10], "terms": ["nucleus", "nukleus", "gitna", "tunga", "sentro", "maliit", "gamay", "atom", "atomo", "bigat", "gibug-aton", "halos lahat ng bigat", "espasyo", "puwang", "volume", "dense", "siksik", "proton", "neutron"], "fact": {"tl": "Napakaliit ng nucleus kumpara sa buong atom, ngunit dito naipon ang halos lahat ng bigat ng atom dahil naroon ang mga proton at neutron.", "en": "The nucleus is a tiny fraction of the whole atom's volume, yet it holds almost all of the atom's mass because the protons and neutrons are there.", "bis": "Gamay ra kaayo ang nucleus kompara sa tibuok atom, apan dinhi natipon ang halos tanang gibug-aton sa atom kay naa diri ang mga proton ug neutron."}, "source": "AAAS BSL 4D/H1; NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "atom-mostly-empty-space-g9", "domain": "MATTER", "topic": "an atom is mostly empty space", "grades": [8, 9, 10], "terms": ["atom", "atomo", "empty space", "walang laman", "walay sulod", "puwang", "espasyo", "hungaw", "nucleus", "electron", "elektron", "malayo", "layo", "halos walang laman", "Rutherford"], "fact": {"tl": "Halos walang laman ang loob ng atom — napakaliit na nucleus sa gitna na napapalibutan ng malalawak na puwang kung saan gumagalaw ang mga magagaang electron.", "en": "An atom is mostly empty space — a tiny nucleus at the center surrounded by a large space where the light electrons move.", "bis": "Halos walay sulod ang atom — gamay kaayo nga nucleus sa tunga nga gilibutan og dako nga puwang diin naglihok ang gaan nga mga electron."}, "source": "AAAS BSL 4D/H1; encyclopedia-stable consensus (Rutherford)", "generator": "claude-workflow", "reviewed": false},
  {"id": "atom-neutral-equal-protons-electrons-g9", "domain": "MATTER", "topic": "neutral atom has equal protons and electrons", "grades": [8, 9, 10], "terms": ["neutral atom", "atom", "atomo", "proton", "electron", "elektron", "magkapareho", "magkasundo", "managsama", "balanse", "balance", "karga", "kanselado", "pantay", "patas", "walang kabuuang karga", "no overall charge"], "fact": {"tl": "Sa isang neutral na atom, magkapareho ang bilang ng proton at electron, kaya nagkakanselahan ang positibo at negatibong karga at nagiging walang kabuuang karga ang atom.", "en": "In a neutral atom, the number of protons equals the number of electrons, so the positive and negative charges cancel and the atom has no overall charge.", "bis": "Sa usa ka neutral nga atom, managsama ang gidaghanon sa proton ug electron, busa magkanselar ang positibo ug negatibo nga karga ug mahimong walay kinatibuk-ang karga ang atom."}, "source": "AAAS BSL 4D/H2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "atomic-number-defines-element-g9", "domain": "MATTER", "topic": "atomic number is the proton count", "grades": [8, 9, 10], "terms": ["atomic number", "atomikong bilang", "numero sa atom", "bilang ng proton", "gidaghanon sa proton", "proton", "element", "elemento", "natukoy", "natino", "carbon", "6", "hydrogen", "identidad", "kung anong element", "defines"], "fact": {"tl": "Ang atomic number ay ang bilang ng proton sa nucleus, at ito ang nagtatakda kung anong element ang atom — halimbawa, bawat atom na may 6 na proton ay carbon.", "en": "The atomic number is the number of protons in the nucleus, and it decides which element an atom is — for example, every atom with 6 protons is carbon.", "bis": "Ang atomic number mao ang gidaghanon sa proton sa nucleus, ug kini ang nagtino kung unsang element ang atom — pananglitan, ang matag atom nga may 6 ka proton kay carbon."}, "source": "AAAS BSL 4D/H2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mass-number-protons-plus-neutrons-g9", "domain": "MATTER", "topic": "mass number is protons plus neutrons", "grades": [8, 9, 10], "terms": ["mass number", "mass na bilang", "bilang ng masa", "proton", "neutron", "kabuuan", "suma", "total", "kabug-osan", "nucleus", "nukleus", "atom", "atomo", "12", "carbon", "dinagdag", "gidugang", "pinagsama"], "fact": {"tl": "Ang mass number ay ang kabuuang bilang ng proton at neutron sa nucleus ng isang atom — halimbawa, ang carbon na may 6 na proton at 6 na neutron ay may mass number na 12.", "en": "The mass number is the total number of protons and neutrons in an atom's nucleus — for example, carbon with 6 protons and 6 neutrons has a mass number of 12.", "bis": "Ang mass number mao ang kinatibuk-ang gidaghanon sa proton ug neutron sa nucleus sa usa ka atom — pananglitan, ang carbon nga may 6 ka proton ug 6 ka neutron may mass number nga 12."}, "source": "AAAS BSL 4D/H1, 4D/H3; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "find-neutron-count-g9", "domain": "MATTER", "topic": "finding the number of neutrons", "grades": [8, 9, 10], "terms": ["neutron", "bilang ng neutron", "gidaghanon sa neutron", "mass number", "atomic number", "ibawas", "kuhaan", "minus", "subtract", "pagkuwenta", "pagkalkula", "proton", "atom", "atomo", "deduct", "kaibhan"], "fact": {"tl": "Para malaman ang bilang ng neutron, ibinabawas mo ang atomic number (bilang ng proton) sa mass number — halimbawa, 12 binawasan ng 6 ay 6 na neutron sa carbon.", "en": "To find the number of neutrons, you subtract the atomic number (proton count) from the mass number — for example, 12 minus 6 gives 6 neutrons in carbon.", "bis": "Aron mahibal-an ang gidaghanon sa neutron, kuhaan nimo ang atomic number (gidaghanon sa proton) gikan sa mass number — pananglitan, 12 kuhaan og 6 mao ang 6 ka neutron sa carbon."}, "source": "encyclopedia-stable consensus; AAAS BSL 4D/H3", "generator": "claude-workflow", "reviewed": false},
  {"id": "isotopes-same-element-different-neutrons-g9", "domain": "MATTER", "topic": "isotopes differ in neutron number", "grades": [8, 9, 10], "terms": ["isotope", "isotopo", "isotopes", "magkaibang neutron", "lain-laing neutron", "parehong proton", "managsama nga proton", "element", "elemento", "carbon-12", "carbon-14", "mass number", "bersyon", "klase sa atom", "same element"], "fact": {"tl": "Ang mga isotope ay magkakaibang bersyon ng iisang element na may parehong bilang ng proton ngunit magkaibang bilang ng neutron, gaya ng carbon-12 at carbon-14.", "en": "Isotopes are different versions of the same element that have the same number of protons but a different number of neutrons, such as carbon-12 and carbon-14.", "bis": "Ang mga isotope mao ang lain-laing bersyon sa usa ra ka element nga may managsama nga gidaghanon sa proton apan lahi og gidaghanon sa neutron, sama sa carbon-12 ug carbon-14."}, "source": "AAAS BSL 4D/H3; NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "isotopes-same-chemistry-g10", "domain": "MATTER", "topic": "isotopes behave the same chemically", "grades": [9, 10], "terms": ["isotope", "isotopo", "kemikal", "chemical behavior", "kemikong ugali", "parehong reaksyon", "managsama nga reaksyon", "electron", "elektron", "proton", "neutron", "magkasundo", "magkapareho", "stability", "katatagan", "kalig-on"], "fact": {"tl": "Ang mga isotope ng iisang element ay halos magkapareho ng kilos sa mga reaksyong kemikal dahil pareho ang bilang ng kanilang proton at electron; ang neutron lang ang nagbabago.", "en": "Isotopes of the same element behave almost identically in chemical reactions because they have the same number of protons and electrons; only the neutrons differ.", "bis": "Ang mga isotope sa usa ka element halos managsama og lihok sa mga reaksyong kemikal kay pareho ra ang gidaghanon sa ilang proton ug electron; ang neutron ra ang lahi."}, "source": "AAAS BSL 4D/H3; NRC chapter (crosscutting: patterns)", "generator": "claude-workflow", "reviewed": false},
  {"id": "radioactive-isotope-decay-g10", "domain": "MATTER", "topic": "radioactive isotopes have unstable nuclei", "grades": [9, 10], "terms": ["radioactive", "radyoaktibo", "isotope", "isotopo", "unstable", "di-matatag", "dili lig-on", "decay", "pagkabulok", "pagkadunot", "nucleus", "nukleus", "radiation", "radyasyon", "partikulo", "naglalabas", "nagbuga", "carbon-14"], "fact": {"tl": "Ang ilang isotope ay radioactive, ibig sabihin di-matatag ang kanilang nucleus at kusang nasisira habang naglalabas ng maliliit na partikulo o radiation.", "en": "Some isotopes are radioactive, meaning their nucleus is unstable and breaks down on its own while giving off tiny particles or radiation.", "bis": "Ang ubang isotope kay radioactive, nagpasabot nga dili lig-on ang ilang nucleus ug kusog nga madunot samtang nagbuga og gagmay nga partikulo o radiation."}, "source": "AAAS BSL 4D/H4; NRC PS1.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "radioactive-decay-predictable-rate-g10", "domain": "MATTER", "topic": "decay rate is predictable for many atoms", "grades": [9, 10], "terms": ["radioactive decay", "pagkabulok", "pagkadunot", "rate", "bilis", "tulin", "predictable", "matatantya", "matag-an", "isang atom", "usa ka atom", "marami", "daghan", "grupo", "edad", "age", "carbon dating", "petsa", "fossil"], "fact": {"tl": "Hindi mahuhulaan kung kailan masisira ang isang nucleus, ngunit ang isang malaking grupo ng parehong atom ay nasisira sa matatantyang bilis, kaya nagagamit ito sa pagtaya ng edad ng mga bato at fossil.", "en": "It cannot be predicted exactly when one nucleus will decay, but a large group of identical atoms decays at a predictable rate, which lets scientists estimate the age of rocks and fossils.", "bis": "Dili matag-an kung kanus-a madunot ang usa ka nucleus, apan ang dako nga grupo sa parehong atom madunot sa matagna nga tulin, mao nga magamit kini sa pagbanabana sa edad sa mga bato ug fossil."}, "source": "AAAS BSL 4D/H4; NRC chapter (cause and effect)", "generator": "claude-workflow", "reviewed": false},
  {"id": "electron-shells-energy-levels-g9", "domain": "MATTER", "topic": "electrons occupy shells or energy levels", "grades": [8, 9, 10], "terms": ["electron shell", "shell", "antas", "ang-ang", "energy level", "antas ng enerhiya", "ang-ang sa enerhiya", "electron", "elektron", "nucleus", "nukleus", "nakaayos", "gihan-ay", "palibot", "paligid", "orbit", "atom", "atomo"], "fact": {"tl": "Nakaayos ang mga electron ng atom sa mga shell o antas ng enerhiya sa paligid ng nucleus, at mas malayo sa nucleus ang shell, mas mataas ang antas ng enerhiya nito.", "en": "An atom's electrons are arranged in shells, or energy levels, around the nucleus, and the farther a shell is from the nucleus, the higher its energy level.", "bis": "Ang mga electron sa atom gihan-ay sa mga shell o ang-ang sa enerhiya sa palibot sa nucleus, ug mas layo ang shell sa nucleus, mas taas ang ang-ang sa enerhiya niini."}, "source": "encyclopedia-stable consensus (Bohr model); AAAS BSL 4D/H2", "generator": "claude-workflow", "reviewed": false},
  {"id": "electron-shell-filling-order-g10", "domain": "MATTER", "topic": "shells fill from inside out", "grades": [9, 10], "terms": ["electron shell", "shell", "napupuno", "mapuno", "kapasidad", "limitasyon", "limit", "una", "primero", "2", "8", "antas", "ang-ang", "nucleus", "nukleus", "electron", "elektron", "loob", "sulod", "labas", "gawas", "pagpuno"], "fact": {"tl": "Napupuno ang mga electron shell mula sa pinakaloob palabas, at may limitasyon ang bawat shell — kayang magtago ng hanggang 2 electron ang unang shell at hanggang 8 ang pangalawa.", "en": "Electron shells fill from the innermost outward, and each shell has a limit — the first shell can hold up to 2 electrons and the second up to 8.", "bis": "Mapuno ang mga electron shell gikan sa kinasuloran paggawas, ug may limit ang matag shell — ang unang shell makahimo og hangtod 2 ka electron ug ang ikaduha hangtod 8."}, "source": "encyclopedia-stable consensus (shell model)", "generator": "claude-workflow", "reviewed": false},
  {"id": "valence-electrons-bonding-g10", "domain": "MATTER", "topic": "valence electrons control bonding", "grades": [9, 10], "terms": ["valence electron", "valence", "panlabas na electron", "panggawas nga electron", "outermost", "pinakalabas", "pinakagawas", "bonding", "pagbubuklod", "pagkadikit", "reaksyon", "reaction", "atom", "atomo", "nagsasama", "nag-uugnay", "katangian"], "fact": {"tl": "Ang valence electron ay ang mga electron sa pinakalabas na shell, at sila ang pangunahing tumutukoy kung paano nagbubuklod o nakikipagreaksiyon ang isang atom sa ibang atom.", "en": "Valence electrons are the electrons in the outermost shell, and they mainly determine how an atom bonds or reacts with other atoms.", "bis": "Ang valence electron mao ang mga electron sa kinagawasang shell, ug sila ang nag-una nga nagtino kung giunsa pagbugkos o pagreaksiyon sa usa ka atom sa ubang atom."}, "source": "AAAS BSL 4D/H2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ion-charged-atom-g9", "domain": "MATTER", "topic": "ions are charged atoms", "grades": [8, 9, 10], "terms": ["ion", "ayon", "may karga", "charged atom", "naka-karga", "nawalan", "nadugangan", "nawad-an", "nadungagan", "electron", "elektron", "positibo", "negatibo", "positive ion", "negative ion", "atom", "atomo", "naging"], "fact": {"tl": "Kapag ang isang atom ay nawalan o nadagdagan ng electron, nagkakaroon ito ng karga at tinatawag na ion — positibo kung nawalan ng electron, negatibo kung nadagdagan.", "en": "When an atom loses or gains electrons, it becomes charged and is called an ion — positive if it loses electrons, negative if it gains them.", "bis": "Kung ang usa ka atom mawad-an o madungagan og electron, mahimo kining may karga ug gitawag og ion — positibo kung mawad-an og electron, negatibo kung madungagan."}, "source": "AAAS BSL 4D/H2; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "protons-define-electron-arrangement-g10", "domain": "MATTER", "topic": "proton count sets electron configuration", "grades": [9, 10], "terms": ["proton", "electron", "elektron", "configuration", "pagkakaayos", "pagkahan-ay", "bilang ng proton", "gidaghanon sa proton", "element", "elemento", "katangian", "kinaiya", "reaksyon", "reaction", "nucleus", "atom", "atomo", "nagtatakda"], "fact": {"tl": "Ang bilang ng proton sa nucleus ang nagtatakda kung ilang electron ang nasa isang neutral na atom at kung paano sila nakaayos, kaya nito naiba ang katangian ng bawat element.", "en": "The number of protons in the nucleus determines how many electrons a neutral atom has and how they are arranged, which is why each element has its own properties.", "bis": "Ang gidaghanon sa proton sa nucleus mao ang nagtino kung pila ka electron ang anaa sa usa ka neutral nga atom ug giunsa kini paghan-ay, mao nga lahi ang kinaiya sa matag element."}, "source": "AAAS BSL 4D/H2", "generator": "claude-workflow", "reviewed": false},
  {"id": "dalton-atomic-theory-g8", "domain": "MATTER", "topic": "Dalton's atomic theory", "grades": [7, 8, 9], "terms": ["Dalton", "John Dalton", "atomic theory", "teorya ng atomo", "teoriya sa atomo", "atom", "atomo", "hindi mahahati", "dili mabahin", "indivisible", "element", "elemento", "magkapareho", "managsama", "1800s", "siyentista", "chemist"], "fact": {"tl": "Noong unang bahagi ng 1800s, iminungkahi ni John Dalton na ang lahat ng bagay ay gawa sa maliliit na atom na hindi mahahati, at magkakapareho ang lahat ng atom ng iisang element ngunit iba sa ibang element.", "en": "In the early 1800s, John Dalton proposed that all matter is made of tiny atoms that cannot be divided, and that all atoms of one element are alike but different from those of other elements.", "bis": "Sa sayong bahin sa 1800s, gisugyot ni John Dalton nga ang tanang butang hinimo sa gagmay nga atom nga dili mabahin, ug nga managsama ang tanang atom sa usa ka element apan lahi sa uban."}, "source": "AAAS BSL 10F/H3", "generator": "claude-workflow", "reviewed": false},
  {"id": "thomson-electron-discovery-g9", "domain": "MATTER", "topic": "Thomson discovered the electron", "grades": [8, 9, 10], "terms": ["Thomson", "J.J. Thomson", "electron", "elektron", "natuklasan", "nadiskubre", "nadiskobrehan", "negatibo", "negative", "plum pudding", "raisin bread", "modelo", "model", "atom", "atomo", "may bahagi", "may parte", "1897"], "fact": {"tl": "Natuklasan ni J.J. Thomson ang electron, na nagpatunay na may mas maliliit na bahagi pala ang atom; iginuhit niya ang atom bilang isang bola ng positibong sangkap na may nakakalat na maliliit na negatibong electron.", "en": "J.J. Thomson discovered the electron, showing that the atom has even smaller parts; he pictured the atom as a ball of positive material with tiny negative electrons scattered in it.", "bis": "Nadiskobrehan ni J.J. Thomson ang electron, nga nagpamatuod nga ang atom adunay mas gagmay nga mga bahin; gihulagway niya ang atom isip usa ka bola sa positibo nga materyal nga may nagkatag nga gagmay nga negatibo nga electron."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rutherford-nucleus-gold-foil-g9", "domain": "MATTER", "topic": "Rutherford found the nucleus", "grades": [8, 9, 10], "terms": ["Rutherford", "Ernest Rutherford", "nucleus", "nukleus", "gold foil", "ginto", "bulawan", "eksperimento", "experiment", "natuklasan", "nadiskubre", "gitna", "tunga", "positibo", "siksik", "dense", "atom", "atomo", "modelo"], "fact": {"tl": "Sa pamamagitan ng pagpapaputok ng maliliit na partikulo sa manipis na ginto, natuklasan ni Ernest Rutherford na may maliit, siksik, at positibong nucleus sa gitna ng atom.", "en": "By firing tiny particles at thin gold foil, Ernest Rutherford discovered that there is a small, dense, positive nucleus at the center of the atom.", "bis": "Pinaagi sa pagpabuto og gagmay nga partikulo sa nipis nga bulawan, nadiskobrehan ni Ernest Rutherford nga adunay gamay, siksik, ug positibo nga nucleus sa tunga sa atom."}, "source": "AAAS BSL 10G/H1; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bohr-energy-levels-g9", "domain": "MATTER", "topic": "Bohr's electrons in fixed levels", "grades": [8, 9, 10], "terms": ["Bohr", "Niels Bohr", "energy level", "antas ng enerhiya", "ang-ang sa enerhiya", "shell", "orbit", "electron", "elektron", "nakatakdang antas", "pihong ang-ang", "fixed", "modelo", "model", "nucleus", "atom", "atomo", "umiikot"], "fact": {"tl": "Pinaunlad ni Niels Bohr ang modelo ng atom sa pamamagitan ng pagsasabi na umiikot ang mga electron sa nucleus sa tiyak na mga antas ng enerhiya, at hindi sila basta-basta nasa pagitan ng mga antas na iyon.", "en": "Niels Bohr improved the atomic model by proposing that electrons orbit the nucleus in specific energy levels and do not simply sit in between those levels.", "bis": "Gipauswag ni Niels Bohr ang modelo sa atom pinaagi sa pag-ingon nga ang mga electron magtuyok sa nucleus sa pihong mga ang-ang sa enerhiya, ug dili sila basta-basta naa sa tunga niadtong mga ang-anga."}, "source": "encyclopedia-stable consensus (Bohr model)", "generator": "claude-workflow", "reviewed": false},
  {"id": "atomic-model-changes-evidence-g9", "domain": "MATTER", "topic": "atomic model improved with evidence", "grades": [8, 9, 10], "terms": ["atomic model", "modelo ng atomo", "modelo sa atom", "nagbago", "nausab", "improved", "ebidensya", "pruweba", "evidence", "siyensiya", "siyensya", "science", "Dalton", "Thomson", "Rutherford", "Bohr", "kasaysayan", "natutuhan", "nadiskubre"], "fact": {"tl": "Nagbago ang modelo ng atom sa paglipas ng panahon habang nagkakaroon ng bagong ebidensya ang mga siyentista — patunay na umuunlad ang kaalaman sa agham sa pamamagitan ng pagwawasto ng dating mga ideya.", "en": "The model of the atom changed over time as scientists gathered new evidence — showing that scientific knowledge grows by correcting earlier ideas.", "bis": "Nausab ang modelo sa atom sa paglabay sa panahon samtang nakakuha og bag-ong ebidensya ang mga siyentista — pamatuod nga ang kahibalo sa siyensya nagtubo pinaagi sa pagtul-id sa daan nga mga ideya."}, "source": "AAAS BSL 4D/H (nature of science); NRC chapter (stability and change)", "generator": "claude-workflow", "reviewed": false},
  {"id": "smaller-particles-quarks-g10", "domain": "MATTER", "topic": "protons and neutrons have smaller parts", "grades": [9, 10], "terms": ["proton", "neutron", "mas maliit", "mas gamay", "smaller parts", "bahagi", "parte", "quark", "siyentista", "scientist", "natuklasan", "nadiskubre", "subatomic", "partikulo", "particle", "atom", "atomo", "pananaliksik"], "fact": {"tl": "Patuloy na sinasaliksik ng mga siyentista ang atom, at natuklasan nilang ang mga proton at neutron mismo ay binubuo pa ng mas maliliit na partikulo.", "en": "Scientists keep investigating the atom, and they have discovered that protons and neutrons are themselves made of even smaller particles.", "bis": "Padayon nga gisusi sa mga siyentista ang atom, ug nadiskobrehan nila nga ang mga proton ug neutron mismo hinimo pa sa mas gagmay nga mga partikulo."}, "source": "AAAS BSL 4D/H5", "generator": "claude-workflow", "reviewed": false},
  {"id": "periodic-pattern-by-mass-g10", "domain": "MATTER", "topic": "repeating properties when ordered by atom mass", "grades": [9, 10], "terms": ["periodic", "paulit-ulit", "balik-balik", "nagbalikbalik", "pattern", "padron", "katangian", "kinaiya", "properties", "element", "elemento", "nakaayos", "gihan-ay", "bigat", "gibug-aton", "mass", "atom", "atomo", "periodic table"], "fact": {"tl": "Kapag inayos ang mga element ayon sa bigat ng kanilang atom, paulit-ulit na lumilitaw ang parehong pagkakasunod-sunod ng mga katangian — ito ang batayan ng periodic table.", "en": "When the elements are listed in order of their atoms' masses, the same sequence of properties appears over and over — this is the basis of the periodic table.", "bis": "Kung ihan-ay ang mga element sumala sa gibug-aton sa ilang atom, balik-balik nga motungha ang parehong han-ay sa mga kinaiya — mao kini ang basihan sa periodic table."}, "source": "AAAS BSL 4D/H6", "generator": "claude-workflow", "reviewed": false},
  {"id": "electrons-do-the-bonding-g10", "domain": "MATTER", "topic": "atoms bond by sharing or transferring electrons", "grades": [9, 10], "terms": ["bond", "pagbubuklod", "pagbugkos", "bonding", "share", "ibinabahagi", "gipaambit", "transfer", "ibinibigay", "gihatag", "electron", "elektron", "atom", "atomo", "nagsasama", "nag-uugnay", "nucleus", "valence", "reaksyon"], "fact": {"tl": "Nagkakabuklod ang mga atom sa pamamagitan ng pagbabahagi o paglilipat ng kanilang panlabas na electron, hindi ng kanilang nucleus, kaya ang electron ang gumagawa ng mga ugnayang kemikal.", "en": "Atoms bond to each other by sharing or transferring their outer electrons, not their nuclei, so it is the electrons that make chemical connections.", "bis": "Nagbugkos ang mga atom pinaagi sa pagpaambit o pagbalhin sa ilang panggawas nga electron, dili sa ilang nucleus, mao nga ang electron ang naghimo sa mga koneksyon nga kemikal."}, "source": "AAAS BSL 4D/H2", "generator": "claude-workflow", "reviewed": false},
  {"id": "neutrons-affect-stability-not-chemistry-g10", "domain": "MATTER", "topic": "neutrons change mass and stability not chemistry", "grades": [9, 10], "terms": ["neutron", "bigat", "gibug-aton", "mass", "stability", "katatagan", "kalig-on", "nucleus", "nukleus", "kemikal", "chemical", "kaunting epekto", "gamay nga epekto", "reaksyon", "reaction", "isotope", "isotopo", "atom", "atomo"], "fact": {"tl": "Kaunti lang ang epekto ng neutron sa kung paano nakikipagreaksiyon ang isang atom, ngunit nakaaapekto ang bilang ng neutron sa bigat at katatagan ng nucleus.", "en": "Neutrons have little effect on how an atom reacts, but the number of neutrons does affect the mass and the stability of the nucleus.", "bis": "Gamay ra ang epekto sa neutron sa kung giunsa pagreaksiyon sa usa ka atom, apan ang gidaghanon sa neutron makaapekto sa gibug-aton ug sa kalig-on sa nucleus."}, "source": "AAAS BSL 4D/H3", "generator": "claude-workflow", "reviewed": false},
  {"id": "periodic-table-arranged-by-atomic-number-g8", "domain": "MATTER", "topic": "periodic table arranged by atomic number", "grades": [8, 9, 10], "terms": ["periodic table", "talahanayan ng mga elemento", "peryodik na talaan", "atomic number", "bilang ng proton", "lamesa sa mga elemento", "gidaghanon sa proton", "gihan-ay sumala sa atomic number", "arranged by atomic number", "nakaayos ayon sa bilang ng proton"], "fact": {"tl": "Ang mga elemento sa periodic table ay nakaayos ayon sa pataas na atomic number, ibig sabihin ayon sa dami ng proton sa kanilang nucleus.", "en": "The elements in the periodic table are arranged in order of increasing atomic number, that is, by how many protons are in their nucleus.", "bis": "Ang mga elemento sa periodic table gihan-ay sumala sa nagkadako nga atomic number, kana mao ang gidaghanon sa proton sa ilang nucleus."}, "source": "AAAS Benchmarks 4D/H2; 4D/H6; consensus chemistry", "generator": "claude-workflow", "reviewed": false},
  {"id": "atomic-number-defines-element-g8", "domain": "MATTER", "topic": "atomic number defines the element", "grades": [8, 9, 10], "terms": ["atomic number", "bilang ng proton", "gidaghanon sa proton", "defines the element", "tumutukoy sa elemento", "nagtino sa elemento", "proton", "kung anong elemento", "what element it is", "unsa nga elemento"], "fact": {"tl": "Ang bilang ng proton (atomic number) ang tumutukoy kung anong elemento ito, kaya't lahat ng atomo ng karbon ay may 6 na proton.", "en": "The number of protons (the atomic number) determines what element an atom is, so every carbon atom has 6 protons.", "bis": "Ang gidaghanon sa proton (atomic number) maoy nagtino kung unsa nga elemento kini, busa ang tanang atomo sa carbon adunay 6 ka proton."}, "source": "AAAS Benchmarks 4D/H2; consensus chemistry", "generator": "claude-workflow", "reviewed": false},
  {"id": "periods-are-rows-g8", "domain": "MATTER", "topic": "periods are horizontal rows", "grades": [8, 9, 10], "terms": ["period", "periodo", "yugto", "hanay", "row", "pahalang na hanay", "laray", "horizontal row", "seven periods", "pitong periodo", "pito ka periodo"], "fact": {"tl": "Ang mga pahalang na hanay sa periodic table ay tinatawag na periods, at may pitong periods ang pangunahing talahanayan.", "en": "The horizontal rows of the periodic table are called periods, and the main table has seven periods.", "bis": "Ang mga pinahigda nga laray sa periodic table gitawag nga periods, ug ang nag-unang lamesa adunay pito ka periods."}, "source": "Consensus chemistry; IUPAC periodic table", "generator": "claude-workflow", "reviewed": false},
  {"id": "groups-are-columns-g8", "domain": "MATTER", "topic": "groups are vertical columns", "grades": [8, 9, 10], "terms": ["group", "grupo", "pangkat", "column", "hanay na patayo", "kolum", "vertical column", "pamilya ng elemento", "same group", "magkagrupo", "parehong grupo", "similar properties", "magkatulad na katangian", "susama nga kabtangan"], "fact": {"tl": "Ang mga patayong hanay sa periodic table ay tinatawag na groups, at ang mga elementong nasa parehong group ay may magkakatulad na katangian.", "en": "The vertical columns of the periodic table are called groups, and elements in the same group have similar properties.", "bis": "Ang mga pinatindog nga laray sa periodic table gitawag nga groups, ug ang mga elemento sa samang group adunay susama nga mga kabtangan."}, "source": "AAAS Benchmarks 4D/M6; 4D/H6; consensus chemistry", "generator": "claude-workflow", "reviewed": false},
  {"id": "valence-electrons-outermost-g9", "domain": "MATTER", "topic": "valence electrons are the outermost electrons", "grades": [9, 10], "terms": ["valence electron", "balensyang elektron", "outermost electron", "pinakalabas na elektron", "kinagawasang elektron", "outer shell", "panlabas na shell", "gawas nga shell", "bonding", "pagbubuklod", "pagbugkos", "reaktibidad", "reactivity", "pagkareaktibo"], "fact": {"tl": "Ang valence electrons ay ang mga elektron sa pinakalabas na shell ng atomo, at sila ang nagpapasiya kung paano makikipagbuklod ang atomo sa iba.", "en": "Valence electrons are the electrons in an atom's outermost shell, and they decide how the atom will bond with other atoms.", "bis": "Ang valence electrons mao ang mga elektron sa kinagawasang shell sa atomo, ug sila ang nagtino kung unsaon pagbugkos sa atomo sa uban."}, "source": "AAAS Benchmarks 4D/H2; consensus chemistry", "generator": "claude-workflow", "reviewed": false},
  {"id": "group-number-tells-valence-electrons-g9", "domain": "MATTER", "topic": "group number relates to valence electrons", "grades": [9, 10], "terms": ["group number", "bilang ng grupo", "numero sa grupo", "valence electrons", "main group", "pangunahing grupo", "same number of valence electrons", "parehong bilang ng valence", "samang gidaghanon sa valence", "kaya magkatulad", "why similar", "ngano susama"], "fact": {"tl": "Ang mga elemento sa parehong main group ay may parehong bilang ng valence electrons, kaya't magkakatulad ang kanilang kemikal na pag-uugali.", "en": "Elements in the same main group have the same number of valence electrons, which is why they behave similarly in chemical reactions.", "bis": "Ang mga elemento sa samang main group adunay samang gidaghanon sa valence electrons, mao nga susama sila molihok sa kemikal nga reaksiyon."}, "source": "AAAS Benchmarks 4D/H2; 4D/H6; consensus chemistry", "generator": "claude-workflow", "reviewed": false},
  {"id": "metals-left-side-g8", "domain": "MATTER", "topic": "metals on the left of the periodic table", "grades": [8, 9, 10], "terms": ["metal", "bakal", "kaliwa", "left side", "wala nga bahin", "kumikinang", "shiny", "sinaw", "nagdadaloy ng kuryente", "conduct electricity", "nagdala og kuryente", "malleable", "nahuhulma", "mahulma", "most elements are metals", "karamihan metal", "kadaghanan metal"], "fact": {"tl": "Karamihan ng mga elemento ay metal na matatagpuan sa kaliwa at gitna ng periodic table, at sila ay kumikinang at nagdadaloy ng init at kuryente.", "en": "Most elements are metals, found on the left and middle of the periodic table, and they are shiny and conduct heat and electricity.", "bis": "Kadaghanan sa mga elemento mga metal nga makita sa wala ug tunga sa periodic table, ug sila sinaw ug nagdala og kainit ug kuryente."}, "source": "AAAS Benchmarks 4D/M6; consensus chemistry", "generator": "claude-workflow", "reviewed": false},
  {"id": "nonmetals-right-side-g8", "domain": "MATTER", "topic": "nonmetals on the right of the periodic table", "grades": [8, 9, 10], "terms": ["nonmetal", "di-metal", "dili-metal", "hindi metal", "kanan", "right side", "tuo nga bahin", "hindi nagdadaloy ng kuryente", "do not conduct electricity", "dili magdala og kuryente", "oxygen", "oksiheno", "insulator"], "fact": {"tl": "Ang mga di-metal ay matatagpuan sa kanang bahagi ng periodic table at karaniwang hindi nagdadaloy ng kuryente, gaya ng oksiheno at nitroheno.", "en": "Nonmetals are found on the right side of the periodic table and usually do not conduct electricity, such as oxygen and nitrogen.", "bis": "Ang mga dili-metal makita sa tuo nga bahin sa periodic table ug kasagaran dili magdala og kuryente, sama sa oxygen ug nitrogen."}, "source": "AAAS Benchmarks 4D/M6; consensus chemistry", "generator": "claude-workflow", "reviewed": false},
  {"id": "metalloids-staircase-g9", "domain": "MATTER", "topic": "metalloids along the staircase line", "grades": [9, 10], "terms": ["metalloid", "metaloyd", "semimetal", "staircase", "hagdan-hagdan", "hagdanan", "silicon", "silikon", "in-between", "nasa gitna", "tunga-tunga", "semiconductor"], "fact": {"tl": "Ang mga metalloid gaya ng silikon ay matatagpuan sa hangganan ng metal at di-metal at may pinaghalong katangian ng dalawa.", "en": "Metalloids such as silicon lie along the border between metals and nonmetals and have a mix of both kinds of properties.", "bis": "Ang mga metalloid sama sa silicon nahimutang sa utlanan sa metal ug dili-metal ug adunay sinagol nga kabtangan sa duha."}, "source": "Consensus chemistry; IUPAC periodic table", "generator": "claude-workflow", "reviewed": false},
  {"id": "noble-gases-group18-unreactive-g9", "domain": "MATTER", "topic": "noble gases are unreactive", "grades": [9, 10], "terms": ["noble gas", "mararangal na gas", "helium", "neon", "argon", "hindi reaktibo", "unreactive", "dili reaktibo", "full outer shell", "punong shell", "puno nga shell", "group 18", "grupo 18"], "fact": {"tl": "Ang mga noble gas gaya ng helium, neon, at argon ay nasa Group 18 at halos hindi nakikipagreaksyon dahil puno na ang kanilang panlabas na shell.", "en": "The noble gases such as helium, neon, and argon are in Group 18 and almost never react because their outer electron shell is already full.", "bis": "Ang mga noble gas sama sa helium, neon, ug argon anaa sa Group 18 ug halos dili moreaksiyon kay puno na ang ilang gawas nga shell."}, "source": "AAAS Benchmarks 4D/M6a; 4D/H2; consensus chemistry", "generator": "claude-workflow", "reviewed": false},
  {"id": "halogens-group17-reactive-nonmetals-g9", "domain": "MATTER", "topic": "halogens are reactive nonmetals", "grades": [9, 10], "terms": ["halogen", "fluorine", "chlorine", "klorin", "group 17", "grupo 17", "reaktibong di-metal", "reactive nonmetal", "reaktibo nga dili-metal", "seven valence electrons", "pitong valence electron", "pito ka valence electron"], "fact": {"tl": "Ang mga halogen gaya ng fluorine at chlorine ay nasa Group 17, mga reaktibong di-metal na may pitong valence electrons.", "en": "The halogens such as fluorine and chlorine are in Group 17 and are reactive nonmetals with seven valence electrons.", "bis": "Ang mga halogen sama sa fluorine ug chlorine anaa sa Group 17, mga reaktibo nga dili-metal nga adunay pito ka valence electrons."}, "source": "AAAS Benchmarks 4D/M6a; consensus chemistry", "generator": "claude-workflow", "reviewed": false},
  {"id": "alkali-metals-group1-reactive-g9", "domain": "MATTER", "topic": "alkali metals are highly reactive", "grades": [9, 10], "terms": ["alkali metal", "sodium", "potassium", "lithium", "group 1", "grupo 1", "isang valence electron", "one valence electron", "usa ka valence electron", "reaktibong metal", "reactive metal", "reaktibo nga metal"], "fact": {"tl": "Ang mga alkali metal gaya ng sodium at potassium ay nasa Group 1, napakareaktibo, at may isang valence electron lamang.", "en": "The alkali metals such as sodium and potassium are in Group 1, are very reactive, and have just one valence electron.", "bis": "Ang mga alkali metal sama sa sodium ug potassium anaa sa Group 1, reaktibo kaayo, ug adunay usa lang ka valence electron."}, "source": "AAAS Benchmarks 4D/M6a; consensus chemistry", "generator": "claude-workflow", "reviewed": false},
  {"id": "recurring-properties-periodic-law-g10", "domain": "MATTER", "topic": "periodic law of recurring properties", "grades": [9, 10], "terms": ["periodic law", "batas periodiko", "paulit-ulit na katangian", "recurring properties", "balik-balik nga kabtangan", "pattern", "padron", "sundanan", "Mendeleev", "predict", "hulaan", "tag-anon", "bakit periodic", "why periodic", "ngano periodic"], "fact": {"tl": "Kapag isinaayos ang mga elemento ayon sa atomic number, paulit-ulit na lumilitaw ang parehong serye ng mga katangian, at ito ang dahilan kung bakit tinawag itong periodic.", "en": "When elements are arranged by atomic number, the same series of properties appears again and again, which is why the table is called periodic.", "bis": "Kon ang mga elemento han-ayon sumala sa atomic number, ang samang serye sa mga kabtangan mobalik-balik, mao nga gitawag kini nga periodic."}, "source": "AAAS Benchmarks 4D/H6; consensus chemistry", "generator": "claude-workflow", "reviewed": false},
  {"id": "symbol-hydrogen-h-g7", "domain": "MATTER", "topic": "chemical symbol of hydrogen", "grades": [7, 8, 9], "terms": ["hydrogen", "haydroheno", "H", "symbol", "simbolo", "chemical symbol", "kemikal na simbolo", "kemikal nga simbolo", "pinakamagaan", "lightest element", "pinakagaan nga elemento", "atomic number 1"], "fact": {"tl": "Ang simbolo ng haydroheno ay H, ito ang pinakamagaan na elemento at may atomic number na 1.", "en": "The symbol for hydrogen is H; it is the lightest element and has atomic number 1.", "bis": "Ang simbolo sa hydrogen mao ang H; kini ang pinakagaan nga elemento ug adunay atomic number nga 1."}, "source": "Consensus chemistry; IUPAC element symbols", "generator": "claude-workflow", "reviewed": false},
  {"id": "symbol-oxygen-o-g7", "domain": "MATTER", "topic": "chemical symbol of oxygen", "grades": [7, 8, 9], "terms": ["oxygen", "oksiheno", "O", "simbolo", "symbol", "hinihinga", "breathe", "ginaginhawa", "atomic number 8", "hangin", "air"], "fact": {"tl": "Ang simbolo ng oksiheno ay O, ang elementong hinihinga natin mula sa hangin, at may atomic number na 8.", "en": "The symbol for oxygen is O, the element we breathe from the air, and it has atomic number 8.", "bis": "Ang simbolo sa oxygen mao ang O, ang elemento nga atong ginaginhawa gikan sa hangin, ug adunay atomic number nga 8."}, "source": "Consensus chemistry; IUPAC element symbols", "generator": "claude-workflow", "reviewed": false},
  {"id": "symbol-carbon-c-g7", "domain": "MATTER", "topic": "chemical symbol of carbon", "grades": [7, 8, 9], "terms": ["carbon", "karbon", "C", "simbolo", "symbol", "buhay", "living things", "buhi nga mga butang", "atomic number 6", "organic", "organiko"], "fact": {"tl": "Ang simbolo ng karbon ay C, isang elementong pangunahing sangkap ng lahat ng nabubuhay na bagay, at may atomic number na 6.", "en": "The symbol for carbon is C, an element that is a main ingredient of all living things, and it has atomic number 6.", "bis": "Ang simbolo sa carbon mao ang C, usa ka elemento nga nag-unang sangkap sa tanang buhi nga butang, ug adunay atomic number nga 6."}, "source": "AAAS Benchmarks 4D/M6c; consensus chemistry", "generator": "claude-workflow", "reviewed": false},
  {"id": "symbols-from-latin-names-g8", "domain": "MATTER", "topic": "some symbols come from Latin names", "grades": [8, 9, 10], "terms": ["symbol", "simbolo", "Latin", "sodium", "Na", "iron", "bakal", "puthaw", "Fe", "gold", "ginto", "bulawan", "Au", "lumang pangalan", "old name", "karaang ngalan"], "fact": {"tl": "May mga simbolong galing sa lumang pangalang Latin, kaya ang sodium ay Na, ang bakal (iron) ay Fe, at ang ginto (gold) ay Au.", "en": "Some symbols come from old Latin names, so sodium is Na, iron is Fe, and gold is Au.", "bis": "Adunay mga simbolo nga gikan sa karaang ngalang Latin, mao nga ang sodium kay Na, ang puthaw (iron) kay Fe, ug ang bulawan (gold) kay Au."}, "source": "Consensus chemistry; IUPAC element symbols", "generator": "claude-workflow", "reviewed": false},
  {"id": "two-letter-symbol-rule-g8", "domain": "MATTER", "topic": "rule for one and two letter symbols", "grades": [8, 9, 10], "terms": ["symbol", "simbolo", "one letter", "isang titik", "usa ka letra", "two letters", "dalawang titik", "duha ka letra", "capital letter", "malaking titik", "dako nga letra", "helium He", "paano sulatin", "how to write", "unsaon pagsulat"], "fact": {"tl": "Ang unang titik ng simbolo ng elemento ay laging malaki, at kung may pangalawang titik ito ay laging maliit, gaya ng He para sa helium.", "en": "The first letter of an element's symbol is always capital, and if there is a second letter it is always lowercase, like He for helium.", "bis": "Ang unang letra sa simbolo sa elemento kanunay dako, ug kon adunay ikaduhang letra kini kanunay gamay, sama sa He para sa helium."}, "source": "Consensus chemistry; IUPAC nomenclature", "generator": "claude-workflow", "reviewed": false},
  {"id": "neutral-atom-protons-equal-electrons-g8", "domain": "MATTER", "topic": "neutral atom has equal protons and electrons", "grades": [8, 9, 10], "terms": ["neutral atom", "neutral na atomo", "neutral nga atomo", "proton", "electron", "elektron", "pantay", "equal", "pareho", "walang charge", "no charge", "walay charge", "bilang", "number", "gidaghanon"], "fact": {"tl": "Sa isang neutral na atomo, pantay ang bilang ng proton at elektron kaya't walang netong electrical charge ito.", "en": "In a neutral atom, the number of protons equals the number of electrons, so it has no overall electrical charge.", "bis": "Sa usa ka neutral nga atomo, parehas ang gidaghanon sa proton ug elektron, busa wala kini kinatibuk-ang electrical charge."}, "source": "AAAS Benchmarks 4D/H2; consensus chemistry", "generator": "claude-workflow", "reviewed": false},
  {"id": "isotopes-same-element-different-neutrons-g10", "domain": "MATTER", "topic": "isotopes have different numbers of neutrons", "grades": [9, 10], "terms": ["isotope", "isotopo", "neutron", "same element", "parehong elemento", "samang elemento", "magkaibang neutron", "different neutrons", "lahi nga neutron", "mass number", "carbon-12 carbon-14"], "fact": {"tl": "Ang mga isotopo ng parehong elemento ay may parehong bilang ng proton ngunit magkaibang bilang ng neutron, gaya ng carbon-12 at carbon-14.", "en": "Isotopes of the same element have the same number of protons but different numbers of neutrons, like carbon-12 and carbon-14.", "bis": "Ang mga isotope sa samang elemento adunay parehong gidaghanon sa proton apan lahi ang gidaghanon sa neutron, sama sa carbon-12 ug carbon-14."}, "source": "AAAS Benchmarks 4D/H3; consensus chemistry", "generator": "claude-workflow", "reviewed": false},
  {"id": "electrons-determine-bonding-g9", "domain": "MATTER", "topic": "outer electrons determine how atoms bond", "grades": [9, 10], "terms": ["bonding", "pagbubuklod", "pagbugkos", "transfer electrons", "ilipat ang elektron", "ibalhin ang elektron", "share electrons", "ibahagi ang elektron", "ipaambit nga elektron", "outer electrons", "panlabas na elektron", "gawas nga elektron", "interact", "makipag-ugnayan", "makig-interak", "reaksyon", "reaction", "reaksiyon"], "fact": {"tl": "Ang mga atomo ay nagbubuklod sa isa't isa sa pamamagitan ng paglilipat o pagbabahagi ng kanilang panlabas na elektron.", "en": "Atoms bond to one another by transferring or sharing their outer electrons.", "bis": "Ang mga atomo magbugkos sa usag usa pinaagi sa pagbalhin o pagpaambit sa ilang gawas nga mga elektron."}, "source": "AAAS Benchmarks 4D/H2; consensus chemistry", "generator": "claude-workflow", "reviewed": false},
  {"id": "hydrogen-helium-most-abundant-universe-g9", "domain": "MATTER", "topic": "hydrogen and helium are most abundant in the universe", "grades": [8, 9, 10], "terms": ["hydrogen", "haydroheno", "helium", "pinakamarami", "most abundant", "labing daghan", "uniberso", "universe", "bituin", "stars", "bituon", "magaan na elemento", "light elements", "gaan nga elemento"], "fact": {"tl": "Ang haydroheno at helium ang dalawang pinakamaraming elemento sa uniberso at siyang pangunahing sangkap ng mga bituin.", "en": "Hydrogen and helium are the two most abundant elements in the universe and are the main ingredients of stars.", "bis": "Ang hydrogen ug helium mao ang duha ka labing daghang elemento sa uniberso ug mao ang nag-unang sangkap sa mga bituon."}, "source": "AAAS Benchmarks 4A/H2; consensus astronomy", "generator": "claude-workflow", "reviewed": false},
  {"id": "transition-metals-middle-block-g9", "domain": "MATTER", "topic": "transition metals in the middle of the table", "grades": [9, 10], "terms": ["transition metal", "bakal", "iron", "puthaw", "tanso", "copper", "tumbaga", "ginto", "gold", "bulawan", "gitnang bahagi", "middle block", "tunga nga bahin", "matigas", "hard", "gahi", "araw-araw na metal", "everyday metals", "adlaw-adlaw nga metal"], "fact": {"tl": "Ang mga transition metal gaya ng bakal, tanso, at ginto ay matatagpuan sa gitnang bahagi ng periodic table at madalas natin itong nakikita araw-araw.", "en": "The transition metals such as iron, copper, and gold sit in the middle block of the periodic table and are metals we often see every day.", "bis": "Ang mga transition metal sama sa puthaw, tumbaga, ug bulawan makita sa tunga nga bahin sa periodic table ug kanunay natong makita adlaw-adlaw."}, "source": "Consensus chemistry; IUPAC periodic table", "generator": "claude-workflow", "reviewed": false},
  {"id": "about-118-elements-g8", "domain": "MATTER", "topic": "there are about 118 known elements", "grades": [8, 9, 10], "terms": ["elemento", "element", "118", "bilang ng elemento", "number of elements", "gidaghanon sa elemento", "natural", "gawa ng tao", "man-made", "binuhat sa tawo", "ilang elemento", "how many elements", "pila ka elemento"], "fact": {"tl": "May humigit-kumulang 118 na kilalang elemento, kung saan karamihan ay natural at ang ilan ay gawa-gawa lamang ng tao sa laboratoryo.", "en": "There are about 118 known elements, most of which occur in nature while a few are made only by people in laboratories.", "bis": "Adunay mga 118 ka nailhang elemento, ang kadaghanan natural samtang ang pipila binuhat lang sa tawo sa laboratoryo."}, "source": "AAAS Benchmarks 4D/M5; consensus chemistry", "generator": "claude-workflow", "reviewed": false},
  {"id": "period-number-tells-electron-shells-g10", "domain": "MATTER", "topic": "period number tells number of electron shells", "grades": [9, 10], "terms": ["period number", "bilang ng periodo", "gidaghanon sa periodo", "electron shell", "energy level", "antas ng enerhiya", "lebel sa enerhiya", "ilang shell", "how many shells", "pila ka shell", "row", "hanay", "laray", "pababa", "down a group", "paubos"], "fact": {"tl": "Ang numero ng period ng isang elemento ay nagsasabi kung ilang electron shell o energy level mayroon ang atomo nito.", "en": "An element's period number tells how many electron shells, or energy levels, its atoms have.", "bis": "Ang numero sa period sa usa ka elemento nagsulti kung pila ka electron shell o energy level ang anaa sa atomo niini."}, "source": "Consensus chemistry; IUPAC periodic table", "generator": "claude-workflow", "reviewed": false},
  {"id": "reactivity-trend-alkali-down-group-g10", "domain": "MATTER", "topic": "alkali metals get more reactive down the group", "grades": [9, 10], "terms": ["reaktibidad", "reactivity", "pagkareaktibo", "alkali metal", "pababa sa grupo", "down the group", "paubos sa grupo", "mas reaktibo", "more reactive", "tubig", "water", "sodium potassium", "trend", "tunguhin", "tendensya"], "fact": {"tl": "Sa mga alkali metal, mas nagiging reaktibo ang elemento habang bumababa sa grupo, kaya't mas marahas ang reaksyon ng potassium kaysa sodium sa tubig.", "en": "Among the alkali metals, elements become more reactive going down the group, so potassium reacts more violently with water than sodium does.", "bis": "Sa mga alkali metal, mas mahimong reaktibo ang elemento samtang nagpaubos sa grupo, mao nga mas kusog moreaksiyon ang potassium kay sa sodium diha sa tubig."}, "source": "Consensus chemistry; periodic trends", "generator": "claude-workflow", "reviewed": false},
  {"id": "noble-gases-uses-g9", "domain": "MATTER", "topic": "uses of noble gases", "grades": [8, 9, 10], "terms": ["noble gas", "helium", "neon", "lobo", "balloon", "ilaw na neon", "neon light", "suga nga neon", "hindi nasusunog", "does not burn", "dili masunog", "ligtas", "safe", "luwas", "gamit", "uses"], "fact": {"tl": "Dahil hindi reaktibo ang mga noble gas, ginagamit ang helium sa mga lobo at ang neon sa mga makukulay na ilaw na neon.", "en": "Because noble gases are unreactive, helium is used in balloons and neon is used in glowing neon lights.", "bis": "Tungod kay dili reaktibo ang mga noble gas, ang helium gigamit sa mga balloon ug ang neon gigamit sa nagsiga nga neon lights."}, "source": "Consensus chemistry; AAAS Benchmarks 4D/M6a", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-helium-above-neon-not-hydrogen-side-g10", "domain": "MATTER", "topic": "families share behavior because of valence electrons", "grades": [9, 10], "terms": ["pamilya", "family", "valence electron", "magkatulad na pag-uugali", "similar behavior", "susama nga lihok", "bakit magkagrupo", "why grouped together", "ngano gigrupo", "chemical family", "kemikal na pamilya", "kemikal nga pamilya", "predict", "hulaan", "tag-anon"], "fact": {"tl": "Magkakatulad ang pag-uugali ng mga elemento sa isang pamilya dahil pareho ang bilang ng kanilang valence electrons, kaya maaaring hulaan ang kanilang reaksyon.", "en": "Elements in a family behave alike because they share the same number of valence electrons, which lets us predict how they will react.", "bis": "Ang mga elemento sa usa ka pamilya susama mag-lihok kay parehas ang gidaghanon sa ilang valence electrons, mao nga matag-an nato ang ilang reaksiyon."}, "source": "AAAS Benchmarks 4D/H2; 4D/H6; consensus chemistry", "generator": "claude-workflow", "reviewed": false},
  {"id": "hydrogen-special-placement-g10", "domain": "MATTER", "topic": "hydrogen is a special case in the table", "grades": [9, 10], "terms": ["hydrogen", "haydroheno", "natatangi", "special", "talagsaon", "di-metal", "nonmetal", "dili-metal", "group 1", "grupo 1", "isang valence electron", "one valence electron", "usa ka valence electron", "bakit kakaiba", "why unusual", "ngano lahi"], "fact": {"tl": "Bagamat nasa itaas ng Group 1 ang haydroheno, ito ay isang di-metal at hindi gaya ng mga alkali metal, kaya itinuturing itong natatanging elemento.", "en": "Although hydrogen sits at the top of Group 1, it is a nonmetal and unlike the alkali metals, so it is treated as a special element.", "bis": "Bisan tuod anaa sa ibabaw sa Group 1 ang hydrogen, kini usa ka dili-metal ug dili sama sa mga alkali metal, mao nga giisip kini nga talagsaong elemento."}, "source": "Consensus chemistry; IUPAC periodic table", "generator": "claude-workflow", "reviewed": false},
  {"id": "chemical-reaction-new-substances-g8", "domain": "MATTER", "topic": "chemical reaction forms new substances", "grades": [7, 8, 9, 10], "terms": ["chemical reaction", "reaktyong kemikal", "reaksyong kemikal", "bagong sangkap", "bagong substansiya", "reaksiyon", "reaksyon nga kemikal", "bag-ong substansiya", "reactant", "product", "reaktant", "produkto", "panimuna", "sangputanan"], "fact": {"tl": "Sa isang reaksyong kemikal, ang mga panimulang sangkap (reactant) ay nag-aayos-muli ng kanilang mga atomo para bumuo ng bagong sangkap (product) na may ibang katangian.", "en": "In a chemical reaction, the starting substances (reactants) rearrange their atoms to form new substances (products) with different properties.", "bis": "Sa usa ka reaksiyong kemikal, ang mga sinugdanang substansiya (reactant) mag-usab sa han-ay sa ilang mga atomo aron mahimo ang bag-ong substansiya (product) nga lahi og kinaiya."}, "source": "NRC PS1.B grade 8 endpoint; AAAS 4D/M13", "generator": "claude-workflow", "reviewed": false},
  {"id": "signs-of-chemical-reaction-g8", "domain": "MATTER", "topic": "signs that a chemical reaction happened", "grades": [7, 8, 9, 10], "terms": ["signs of reaction", "palatandaan ng reaksyon", "timailhan sa reaksiyon", "pagbabago ng kulay", "gas", "bula", "usok", "init", "lamig", "precipitate", "latak", "pag-init", "pagbula", "pagbag-o sa kolor", "aso", "alisngaw"], "fact": {"tl": "Ang ilang palatandaan na may naganap na reaksyong kemikal ay pagbabago ng kulay, paglabas ng gas o bula, pagbuo ng latak (precipitate), at pagbabago ng temperatura tulad ng pag-init o paglamig.", "en": "Some signs that a chemical reaction has occurred are a color change, release of gas or bubbles, formation of a precipitate, and a temperature change such as heating up or cooling down.", "bis": "Ang pipila ka timailhan nga adunay nahitabo nga reaksiyong kemikal mao ang pag-usab sa kolor, paggawas sa gas o bula, pagporma sa latak (precipitate), ug pag-usab sa temperatura sama sa pag-init o pagbugnaw."}, "source": "Encyclopedia-stable chemistry consensus; AAAS 4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "conservation-of-mass-reaction-g9", "domain": "MATTER", "topic": "conservation of mass in reactions", "grades": [8, 9, 10], "terms": ["conservation of mass", "konserbasyon ng masa", "kabuhungan sa masa", "walang nawawala", "masa ng reactant", "masa ng product", "atomo ay nananatili", "wala mawala", "timbang nga managsama", "gibug-aton", "atomo dili madugang dili makunhod"], "fact": {"tl": "Ayon sa batas ng konserbasyon ng masa, ang kabuuang masa ng mga reactant ay katumbas ng kabuuang masa ng mga product dahil walang atomong nalilikha o nawawala sa reaksyon.", "en": "By the law of conservation of mass, the total mass of the reactants equals the total mass of the products because no atoms are created or destroyed in a reaction.", "bis": "Sumala sa balaod sa konserbasyon sa masa, ang kinatibuk-ang masa sa mga reactant managsama sa kinatibuk-ang masa sa mga product kay walay atomo nga nahimo o nawala sa reaksiyon."}, "source": "NRC PS1.B grade 8 endpoint; AAAS 4D/M7", "generator": "claude-workflow", "reviewed": false},
  {"id": "atoms-conserved-rearranged-g9", "domain": "MATTER", "topic": "atoms conserved and rearranged", "grades": [8, 9, 10], "terms": ["atoms conserved", "atomo ay nananatili", "atomo dili mausab ang gidaghanon", "muling pagkakaayos", "rearranged", "nag-ayos-muli", "regrouped", "na-regroup", "bilang ng atomo", "gidaghanon sa atomo", "gi-usab ang han-ay", "bukdon ug isumpay pag-usab"], "fact": {"tl": "Sa anumang reaksyong kemikal, hindi nagbabago ang bilang ng bawat uri ng atomo; ang mga atomo lamang ay nagbubukluran at nag-aayos-muli sa bagong mga molekula.", "en": "In any chemical reaction the number of each type of atom does not change; the atoms are only regrouped and rearranged into new molecules.", "bis": "Sa bisan unsang reaksiyong kemikal, dili mausab ang gidaghanon sa matag matang sa atomo; ang mga atomo gibukod ug gi-usab lang ang han-ay ngadto sa bag-ong mga molekula."}, "source": "NRC PS1.B grade 8 endpoint; AAAS 4D/M13", "generator": "claude-workflow", "reviewed": false},
  {"id": "balancing-chemical-equation-g9", "domain": "MATTER", "topic": "balancing chemical equations", "grades": [8, 9, 10], "terms": ["chemical equation", "ekwasyong kemikal", "balanseng ekwasyon", "balanced equation", "coefficient", "koepisyent", "pagbabalanse", "pagbalanse", "magkaparehong atomo magkabilang gilid", "subscript", "kapanaog", "balanse nga ekwasyon", "managsama nga atomo"], "fact": {"tl": "Binabalanse ang isang ekwasyong kemikal sa pamamagitan ng paglalagay ng mga coefficient upang maging magkapareho ang bilang ng bawat atomo sa panig ng reactant at sa panig ng product.", "en": "A chemical equation is balanced by placing coefficients so that the number of each atom is the same on the reactant side and the product side.", "bis": "Ang usa ka ekwasyong kemikal gibalanse pinaagi sa pagbutang og mga coefficient aron managsama ang gidaghanon sa matag atomo sa kilid sa reactant ug sa kilid sa product."}, "source": "Encyclopedia-stable chemistry consensus; follows from AAAS 4D/M7 conservation", "generator": "claude-workflow", "reviewed": false},
  {"id": "chemical-equation-symbols-g9", "domain": "MATTER", "topic": "reading a chemical equation", "grades": [8, 9, 10], "terms": ["chemical equation", "ekwasyong kemikal", "arrow", "palaso", "yield", "reactant kaliwa product kanan", "wala ang reactant tuo ang product", "plus sign", "simbolo", "pormula", "formula", "gibasa ang ekwasyon", "pana"], "fact": {"tl": "Sa isang ekwasyong kemikal, ang mga reactant ay nasa kaliwa ng palaso at ang mga product ay nasa kanan, at ang palaso ay nangangahulugang 'nagiging.'", "en": "In a chemical equation the reactants are written on the left of the arrow and the products on the right, and the arrow means 'yields' or 'becomes.'", "bis": "Sa usa ka ekwasyong kemikal, ang mga reactant gisulat sa wala sa pana ug ang mga product sa tuo, ug ang pana nagpasabot og 'mahimong' o 'magresulta.'"}, "source": "Encyclopedia-stable chemistry consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "combination-synthesis-reaction-g10", "domain": "MATTER", "topic": "combination (synthesis) reaction", "grades": [9, 10], "terms": ["combination reaction", "synthesis reaction", "reaksyong pagsasama", "reaksyong sintesis", "pagsasanib", "reaksiyon sa kombinasyon", "dalawang sangkap nagiging isa", "duha mahimong usa", "A plus B", "paghiusa", "panagsama", "mahimong usa ka produkto"], "fact": {"tl": "Sa combination o synthesis reaction, dalawa o higit pang sangkap ang nagsasama upang bumuo ng iisang bagong product, gaya ng hydrogen at oxygen na nagiging tubig.", "en": "In a combination or synthesis reaction, two or more substances join to form a single new product, such as hydrogen and oxygen forming water.", "bis": "Sa combination o synthesis reaction, duha o labaw pa ka substansiya ang maghiusa aron mahimo ang usa ra ka bag-ong product, sama sa hydrogen ug oxygen nga mahimong tubig."}, "source": "Encyclopedia-stable chemistry consensus; DepEd G10 reaction types", "generator": "claude-workflow", "reviewed": false},
  {"id": "decomposition-reaction-g10", "domain": "MATTER", "topic": "decomposition reaction", "grades": [9, 10], "terms": ["decomposition reaction", "reaksyong dekomposisyon", "reaksyong paghihiwalay", "pagkabulag", "reaksiyon sa dekomposisyon", "isang sangkap nahahati", "usa nabahin sa daghan", "nabubuwag", "init nagpabahin", "nadugmok", "nabungkag ngadto sa duha o labaw"], "fact": {"tl": "Sa decomposition reaction, ang iisang sangkap ay nahahati sa dalawa o higit pang mas simpleng sangkap, madalas dahil sa init o kuryente.", "en": "In a decomposition reaction, a single substance breaks down into two or more simpler substances, often caused by heat or electricity.", "bis": "Sa decomposition reaction, ang usa ka substansiya mabungkag ngadto sa duha o labaw pa ka mas simple nga substansiya, kasagaran tungod sa kainit o kuryente."}, "source": "Encyclopedia-stable chemistry consensus; DepEd G10 reaction types", "generator": "claude-workflow", "reviewed": false},
  {"id": "single-replacement-reaction-g10", "domain": "MATTER", "topic": "single replacement reaction", "grades": [9, 10], "terms": ["single replacement", "single displacement", "reaksyong pagpapalit", "isahang pagpapalit", "reaksiyon sa pag-ilis", "usa ka elemento mupuli", "isang elemento pumapalit", "mas aktibong metal", "mas aktibo nga metal", "gipulihan", "pag-ilis sa usa"], "fact": {"tl": "Sa single replacement reaction, ang isang elemento ay pumapalit sa isa pang elemento sa loob ng isang compound, gaya ng mas aktibong metal na pumapalit sa mas mahinang metal.", "en": "In a single replacement reaction, one element takes the place of another element in a compound, such as a more active metal replacing a less active one.", "bis": "Sa single replacement reaction, ang usa ka elemento mupuli sa lain nga elemento sulod sa usa ka compound, sama sa mas aktibo nga metal nga mupuli sa mas huyang nga metal."}, "source": "Encyclopedia-stable chemistry consensus; DepEd G10 reaction types", "generator": "claude-workflow", "reviewed": false},
  {"id": "double-replacement-reaction-g10", "domain": "MATTER", "topic": "double replacement reaction", "grades": [9, 10], "terms": ["double replacement", "double displacement", "reaksyong dobleng pagpapalit", "reaksiyon sa doble nga pag-ilis", "dalawang compound nagpapalitan", "duha ka compound mag-ilisanay", "ions nagpapalit", "precipitate", "latak", "nag-ilisanay ang ions", "pag-ilisay sa duha"], "fact": {"tl": "Sa double replacement reaction, dalawang compound ang nagpapalitan ng kanilang mga bahagi (ions) upang bumuo ng dalawang bagong compound, na kadalasang nagbubuo ng latak.", "en": "In a double replacement reaction, two compounds exchange their parts (ions) to form two new compounds, often producing a precipitate.", "bis": "Sa double replacement reaction, duha ka compound mag-ilisanay sa ilang mga bahin (ions) aron maporma ang duha ka bag-ong compound, kasagaran maghimo og latak."}, "source": "Encyclopedia-stable chemistry consensus; DepEd G10 reaction types", "generator": "claude-workflow", "reviewed": false},
  {"id": "combustion-reaction-g10", "domain": "MATTER", "topic": "combustion reaction", "grades": [9, 10], "terms": ["combustion", "reaksyong pagkasunog", "kombustyon", "pagkasunog", "reaksiyon sa pagsunog", "nasunog sa oxygen", "gasolab", "carbon dioxide ug tubig", "fuel oxygen", "gatong", "nakig-reaksiyon sa oxygen", "nagdilaab"], "fact": {"tl": "Ang combustion ay isang reaksyong kemikal kung saan ang isang sangkap ay mabilis na nakikipagreaksyon sa oxygen, naglalabas ng init at liwanag, at kadalasang bumubuo ng carbon dioxide at tubig.", "en": "Combustion is a chemical reaction in which a substance reacts rapidly with oxygen, releasing heat and light, and usually forming carbon dioxide and water.", "bis": "Ang combustion usa ka reaksiyong kemikal diin ang usa ka substansiya paspas nga makig-reaksiyon sa oxygen, mogawas ang kainit ug kahayag, ug kasagaran maghimo og carbon dioxide ug tubig."}, "source": "NRC PS1.B / PS3.D (burning fuel); AAAS 4E", "generator": "claude-workflow", "reviewed": false},
  {"id": "exothermic-reaction-g10", "domain": "MATTER", "topic": "exothermic reaction releases energy", "grades": [9, 10], "terms": ["exothermic", "exothermic reaction", "naglalabas ng init", "nagpapalabas ng enerhiya", "reaksiyon nga mogawas init", "mainit ang palibot", "nag-init", "releases energy", "nagpainit", "nagbuga og kainit", "mogawas ang enerhiya", "init nga reaksiyon"], "fact": {"tl": "Ang exothermic na reaksyon ay naglalabas ng enerhiya sa paligid, kaya tumataas ang temperatura, gaya ng pagsunog ng gatong.", "en": "An exothermic reaction releases energy to the surroundings, so the temperature rises, as when fuel burns.", "bis": "Ang exothermic nga reaksiyon mogawas og enerhiya ngadto sa palibot, busa mosaka ang temperatura, sama sa pagsunog sa gatong."}, "source": "NRC PS1.B grade 8 endpoint (some reactions release energy); AAAS 4E", "generator": "claude-workflow", "reviewed": false},
  {"id": "endothermic-reaction-g10", "domain": "MATTER", "topic": "endothermic reaction absorbs energy", "grades": [9, 10], "terms": ["endothermic", "endothermic reaction", "sumisipsip ng init", "kumukuha ng enerhiya", "reaksiyon nga musuyop init", "lumalamig ang palibot", "nagbugnaw", "absorbs energy", "nagpalamig", "misuyop og kainit", "nanginahanglan og enerhiya", "bugnaw nga reaksiyon"], "fact": {"tl": "Ang endothermic na reaksyon ay sumisipsip ng enerhiya mula sa paligid, kaya bumababa ang temperatura at lumalamig ang paligid.", "en": "An endothermic reaction absorbs energy from the surroundings, so the temperature drops and the surroundings feel cold.", "bis": "Ang endothermic nga reaksiyon musuyop og enerhiya gikan sa palibot, busa mokunhod ang temperatura ug mobugnaw ang palibot."}, "source": "NRC PS1.B grade 8 endpoint (some reactions store energy); AAAS 4E", "generator": "claude-workflow", "reviewed": false},
  {"id": "bond-energy-exo-endo-g10", "domain": "MATTER", "topic": "bonds breaking and forming carry energy", "grades": [9, 10], "terms": ["bond energy", "enerhiya ng bono", "kusog sa bugkos", "pagputol ng bono", "pagbuo ng bono", "pagbungkag sa bond", "pagporma sa bond", "absorbs energy breaking", "releases energy forming", "sumipsip pagputol", "mogawas paghimo", "bond"], "fact": {"tl": "Kailangan ng enerhiya upang putulin ang mga bono ng reactant, at naglalabas ng enerhiya kapag nabubuo ang mga bagong bono ng product; ang pagkakaiba nito ang nagsasabi kung exothermic o endothermic ang reaksyon.", "en": "Energy is needed to break the bonds of the reactants, and energy is released when the new bonds of the products form; the difference between them tells whether the reaction is exothermic or endothermic.", "bis": "Kinahanglan og enerhiya aron bungkagon ang mga bond sa reactant, ug mogawas ang enerhiya kon maporma ang bag-ong mga bond sa product; ang kalainan niini maoy nagsulti kon exothermic o endothermic ang reaksiyon."}, "source": "NRC PS1.B grade 12 endpoint (change in total binding energy)", "generator": "claude-workflow", "reviewed": false},
  {"id": "collision-theory-reactions-g10", "domain": "MATTER", "topic": "collision theory of reaction rates", "grades": [9, 10], "terms": ["collision theory", "teorya ng banggaan", "teorya sa banggaanay", "pagbabanggaan ng partikulo", "kinahanglan magbangga", "particles must collide", "sapat na enerhiya", "igong enerhiya", "tamang anggulo", "banggaan", "pagbangga sa mga partikulo", "husto nga kusog"], "fact": {"tl": "Ayon sa collision theory, nangyayari ang reaksyon kapag ang mga partikulo ay nagbabanggaan nang may sapat na enerhiya at tamang oryentasyon.", "en": "According to collision theory, a reaction happens when particles collide with enough energy and the correct orientation.", "bis": "Sumala sa collision theory, mahitabo ang reaksiyon kon ang mga partikulo magbinangga nga adunay igong enerhiya ug husto nga oryentasyon."}, "source": "NRC PS1.B grade 12 endpoint (collision model for rates)", "generator": "claude-workflow", "reviewed": false},
  {"id": "reaction-rate-meaning-g10", "domain": "MATTER", "topic": "what reaction rate means", "grades": [9, 10], "terms": ["reaction rate", "bilis ng reaksyon", "tulin sa reaksiyon", "gaano kabilis", "unsa ka paspas", "rate of reaction", "mabilis na reaksyon", "mahinay na reaksiyon", "paspas o hinay", "bilis", "katulin", "gidaghanon nga nabag-o matag panahon"], "fact": {"tl": "Ang bilis ng reaksyon (reaction rate) ay kung gaano kabilis nauubos ang mga reactant o nabubuo ang mga product sa isang yugto ng panahon.", "en": "The reaction rate is how fast the reactants are used up or the products are formed over a period of time.", "bis": "Ang tulin sa reaksiyon (reaction rate) mao kon unsa ka paspas mahurot ang mga reactant o maporma ang mga product sulod sa usa ka yugto sa panahon."}, "source": "AAAS 4D/H9 (rate of reactions); NRC PS1.B grade 12", "generator": "claude-workflow", "reviewed": false},
  {"id": "temperature-affects-rate-g10", "domain": "MATTER", "topic": "temperature affects reaction rate", "grades": [9, 10], "terms": ["temperature reaction rate", "temperatura bilis reaksyon", "init pataas ng bilis", "mas mainit mas paspas", "mainit mas mabilis", "faster collisions", "mabilis na banggaan", "init nagpapabilis", "kainit nagpapaspas", "mas taas nga temperatura", "mas paspas nga reaksiyon", "init"], "fact": {"tl": "Pinabibilis ng mas mataas na temperatura ang reaksyon dahil mas mabilis at mas madalas na nagbabanggaan ang mga partikulo na may sapat na enerhiya.", "en": "A higher temperature speeds up a reaction because particles move faster and collide more often with enough energy.", "bis": "Ang mas taas nga temperatura magpapaspas sa reaksiyon kay ang mga partikulo molihok nga mas paspas ug mas kanunay magbinangga nga adunay igong enerhiya."}, "source": "AAAS 4D/H9; NRC PS1.B grade 12 (higher rates at higher temperatures)", "generator": "claude-workflow", "reviewed": false},
  {"id": "concentration-affects-rate-g10", "domain": "MATTER", "topic": "concentration affects reaction rate", "grades": [9, 10], "terms": ["concentration", "konsentrasyon", "kadaghan sa partikulo", "mas maraming partikulo", "mas konsentrado mas paspas", "more particles", "mas siksik", "dami ng partikulo", "gidaghanon sa partikulo", "mas concentrated", "mas paspas ang reaksiyon", "konsentrado"], "fact": {"tl": "Pinabibilis ng mas mataas na konsentrasyon ang reaksyon dahil mas maraming partikulo sa isang espasyo, kaya mas madalas ang banggaan.", "en": "A higher concentration speeds up a reaction because there are more particles in a space, so collisions happen more often.", "bis": "Ang mas taas nga konsentrasyon magpapaspas sa reaksiyon kay mas daghan ang partikulo sa usa ka luna, busa mas kanunay ang banggaanay."}, "source": "AAAS 4D/H9 (concentration affects rate)", "generator": "claude-workflow", "reviewed": false},
  {"id": "surface-area-affects-rate-g10", "domain": "MATTER", "topic": "surface area affects reaction rate", "grades": [9, 10], "terms": ["surface area", "lawak ng ibabaw", "gidak-on sa nawong", "durog na solido", "pinong pulbos", "pino nga pulbos", "powder reacts faster", "mas malaking ibabaw", "mas dako nga surface", "dinurog", "pulbos mas paspas", "ginadugmok"], "fact": {"tl": "Mas mabilis magreaksyon ang isang solido kapag dinurog o ginawang pulbos dahil mas malaki ang ibabaw na maaaring sumalo sa banggaan.", "en": "A solid reacts faster when it is crushed or powdered because more surface area is exposed for collisions.", "bis": "Mas paspas magreaksiyon ang usa ka solido kon dugmokon o himoong pulbos kay mas dako ang nawong nga maladlad alang sa banggaanay."}, "source": "Encyclopedia-stable chemistry consensus (factors affecting rate); AAAS 4D/H9", "generator": "claude-workflow", "reviewed": false},
  {"id": "catalyst-speeds-reaction-g10", "domain": "MATTER", "topic": "catalyst speeds up reaction", "grades": [9, 10], "terms": ["catalyst", "katalista", "catalyst nagpapabilis", "mga sangkap na nagpapabilis", "substansiya nga magpapaspas", "not used up", "hindi nauubos", "wala maubos", "lowers energy", "enzyme", "enzima", "katalisador", "nagpaspas dili maubos"], "fact": {"tl": "Ang catalyst ay isang sangkap na nagpapabilis sa reaksyon ngunit hindi nauubos, dahil pinababa nito ang enerhiyang kailangan upang magsimula ang reaksyon.", "en": "A catalyst is a substance that speeds up a reaction without being used up, because it lowers the energy needed to start the reaction.", "bis": "Ang catalyst usa ka substansiya nga magpapaspas sa reaksiyon apan dili maubos, kay gipakunhod niini ang enerhiya nga gikinahanglan aron magsugod ang reaksiyon."}, "source": "AAAS 4D/H9b (some molecules encourage interaction of others); NRC PS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "activation-energy-g10", "domain": "MATTER", "topic": "activation energy starts a reaction", "grades": [9, 10], "terms": ["activation energy", "enerhiya ng pagpapasimula", "aktibasyon enerhiya", "panimulang enerhiya", "kinahanglang enerhiya magsugod", "energy to start", "init para magsimula", "spark", "tilamsik", "panukmod", "enerhiya aron magsugod", "minimum nga enerhiya"], "fact": {"tl": "Ang activation energy ay ang pinakamababang enerhiyang kailangan upang magsimula ang isang reaksyon, gaya ng init o tilamsik na nagpapaandar sa pagsunog.", "en": "Activation energy is the smallest amount of energy needed to start a reaction, like the heat or spark that gets burning going.", "bis": "Ang activation energy mao ang labing gamay nga enerhiya nga gikinahanglan aron magsugod ang usa ka reaksiyon, sama sa kainit o tilamsik nga magpasugod sa pagsunog."}, "source": "NRC PS1.B grade 12 endpoint (energy to initiate the process)", "generator": "claude-workflow", "reviewed": false},
  {"id": "reaction-energy-conserved-g10", "domain": "MATTER", "topic": "energy is conserved in reactions", "grades": [9, 10], "terms": ["conservation of energy", "konserbasyon ng enerhiya", "enerhiya dili mawala", "stored energy", "nakaimbak na enerhiya", "natipig nga enerhiya", "chemical energy", "enerhiyang kemikal", "enerhiya kemikal", "bond energy", "enerhiya wala mawala", "gibalhin lang ang enerhiya"], "fact": {"tl": "Sa isang reaksyong kemikal, hindi nawawala ang enerhiya kundi nagbabago lamang ng anyo, mula sa nakaimbak na enerhiya ng mga bono patungong init, liwanag, o kabaligtaran.", "en": "In a chemical reaction energy is not lost but only changes form, from the stored energy of bonds into heat or light, or the other way around.", "bis": "Sa usa ka reaksiyong kemikal, ang enerhiya dili mawala kondili mag-usab lang og porma, gikan sa natipig nga enerhiya sa mga bond ngadto sa kainit o kahayag, o sa baliktad."}, "source": "NRC PS1.B grade 12 endpoint (conservation of energy in reactions)", "generator": "claude-workflow", "reviewed": false},
  {"id": "rusting-slow-reaction-g9", "domain": "MATTER", "topic": "rusting as a slow chemical reaction", "grades": [8, 9, 10], "terms": ["rust", "kalawang", "taya", "rusting", "pagkalawang", "pagtaya", "oxidation", "oxidasyon", "oxihenasyon", "iron oxygen", "bakal oxygen", "puthaw oxygen", "mabagal na reaksyon", "hinay nga reaksiyon", "makawang"], "fact": {"tl": "Ang pagkalawang ng bakal ay isang mabagal na reaksyong kemikal kung saan ang bakal ay nakikipagreaksyon sa oxygen at tubig upang bumuo ng kalawang.", "en": "Rusting of iron is a slow chemical reaction in which iron reacts with oxygen and water to form rust.", "bis": "Ang pagkalawang sa puthaw usa ka hinay nga reaksiyong kemikal diin ang puthaw makig-reaksiyon sa oxygen ug tubig aron maporma ang taya."}, "source": "Encyclopedia-stable chemistry consensus (oxidation example); AAAS 4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "reversible-reaction-equilibrium-g10", "domain": "MATTER", "topic": "reversible reactions and balance", "grades": [9, 10], "terms": ["reversible reaction", "reaksyong nababaligtad", "reaksiyon nga mabalik", "pabalik-balik", "dynamic balance", "balanseng dinamiko", "dinamikong balanse", "equilibrium", "ekwilibriyo", "forward at reverse", "atubangan ug balik", "managsama nga tulin", "pareho ang bilis"], "fact": {"tl": "Sa ilang reaksyon na nababaligtad, ang reaksyong pasulong at pabalik ay maaaring mangyari nang sabay sa magkaparehong bilis, kaya nananatiling balanse ang mga sangkap.", "en": "In some reversible reactions, the forward and reverse reactions can happen at the same time at equal rates, so the amounts of substances stay balanced.", "bis": "Sa pipila ka reaksiyon nga mabalik, ang reaksiyon pasulong ug pabalik mahitabo nga dungan sa managsama nga tulin, busa magpabilin nga balanse ang mga substansiya."}, "source": "NRC PS1.B grade 12 endpoint (dynamic balance / dynamically balanced)", "generator": "claude-workflow", "reviewed": false},
  {"id": "physical-vs-chemical-change-g8", "domain": "MATTER", "topic": "physical change versus chemical change", "grades": [7, 8, 9], "terms": ["physical change", "chemical change", "pisikal na pagbabago", "kemikal na pagbabago", "pisikal nga kausaban", "kemikal nga kausaban", "walang bagong sangkap", "walay bag-ong substansiya", "bagong sangkap", "nabuo ang bag-o", "natunaw", "pagkatunaw", "reversible"], "fact": {"tl": "Sa pisikal na pagbabago tulad ng pagkatunaw, hindi nabubuo ang bagong sangkap, ngunit sa kemikal na pagbabago ay nabubuo ang isang bagong sangkap na may ibang katangian.", "en": "In a physical change like melting, no new substance is formed, but in a chemical change a new substance with different properties is formed.", "bis": "Sa pisikal nga kausaban sama sa pagkatunaw, walay bag-ong substansiya nga maporma, apan sa kemikal nga kausaban adunay bag-ong substansiya nga lahi og kinaiya ang maporma."}, "source": "NRC PS1.B (changes where molecules don't change vs. do); AAAS 4D", "generator": "claude-workflow", "reviewed": false},
  {"id": "photosynthesis-as-reaction-g9", "domain": "MATTER", "topic": "photosynthesis as an endothermic reaction", "grades": [8, 9, 10], "terms": ["photosynthesis reaction", "reaksyon ng potosintesis", "reaksiyon sa potosintesis", "carbon dioxide tubig asukal", "sikat ng araw enerhiya", "kahayag sa adlaw", "sugar oxygen", "asukal oxygen", "kumukuha ng enerhiya", "nanginahanglan enerhiya", "endothermic", "nag-imbak ng enerhiya"], "fact": {"tl": "Ang potosintesis ay isang reaksyong kemikal na kumukuha ng enerhiya mula sa sikat ng araw upang pagsamahin ang carbon dioxide at tubig tungo sa asukal at oxygen.", "en": "Photosynthesis is a chemical reaction that takes in energy from sunlight to combine carbon dioxide and water into sugar and oxygen.", "bis": "Ang potosintesis usa ka reaksiyong kemikal nga musuyop og enerhiya gikan sa kahayag sa adlaw aron iusa ang carbon dioxide ug tubig ngadto sa asukal ug oxygen."}, "source": "NRC PS1.B grade 8 endpoint (synthesis of sugars requires energy input); LS1", "generator": "claude-workflow", "reviewed": false},
  {"id": "respiration-burning-fuel-reaction-g9", "domain": "MATTER", "topic": "respiration and burning release stored energy", "grades": [8, 9, 10], "terms": ["cellular respiration", "respirasyon", "pagginhawa sa selula", "pagsunog ng gatong", "burning fuel", "pagsunog sa gatong", "naglalabas ng enerhiya", "mogawas ang enerhiya", "carbon dioxide tubig", "oxygen reaksiyon", "stored energy", "natipig nga enerhiya", "exothermic"], "fact": {"tl": "Parehong reaksyon sa oxygen ang pagsunog ng gatong at ang respirasyon sa selula, kung saan ang mga molekulang may carbon ay naglalabas ng nakaimbak na enerhiya at bumubuo ng carbon dioxide.", "en": "Both burning fuel and cellular respiration are reactions with oxygen in which carbon-containing molecules release stored energy and form carbon dioxide.", "bis": "Pareho nga reaksiyon sa oxygen ang pagsunog sa gatong ug ang respirasyon sa selula, diin ang mga molekula nga adunay carbon mogawas sa natipig nga enerhiya ug maghimo og carbon dioxide."}, "source": "NRC PS3.D grade 8 endpoint (burning and respiration release stored energy)", "generator": "claude-workflow", "reviewed": false},
  {"id": "acids-bases-react-neutralize-g9", "domain": "MATTER", "topic": "acids and bases react to neutralize", "grades": [8, 9, 10], "terms": ["acid base reaction", "reaksyon ng asido at base", "reaksiyon sa asido ug base", "neutralisasyon", "neutralization", "pagpapaneutral", "asido base nagtutugon", "asido base nagtagbo", "asin at tubig", "tubig ug asin", "salt water", "neutral", "nagiging neutral"], "fact": {"tl": "Kapag nagreaksyon ang isang asido at isang base, nag-neneutralisa sila at kadalasang bumubuo ng asin at tubig.", "en": "When an acid and a base react, they neutralize each other and usually form a salt and water.", "bis": "Kon magreaksiyon ang usa ka asido ug usa ka base, mag-neutralize sila ug kasagaran maghimo og asin ug tubig."}, "source": "Encyclopedia-stable chemistry consensus; NRC PS1.B (reactivity of hydrogen ions)", "generator": "claude-workflow", "reviewed": false},
  {"id": "acid-releases-h-ions-g8", "domain": "MATTER", "topic": "acids release hydrogen ions in water", "grades": [8, 9, 10], "terms": ["acid", "hydrogen ion", "H+", "hydronium", "tubig", "hydrogen", "naglalabas", "ion", "asido", "naglalabas ng hydrogen ion", "nagpagawas", "asido nagpagawas", "maasim dahil sa ion", "dissolved in water", "natunaw sa tubig", "natunaw"], "fact": {"tl": "Ang isang acid ay maasim dahil kapag natunaw ito sa tubig ay naglalabas ito ng mga hydrogen ion (H+), at ang dami ng H+ ang nagpapasiya kung gaano ito ka-acid.", "en": "An acid is sour because when it dissolves in water it releases hydrogen ions (H+), and the amount of H+ is what decides how acidic it is.", "bis": "Ang acid maaslom kay kung matunaw kini sa tubig nagpagawas kini og mga hydrogen ion (H+), ug ang gidaghanon sa H+ maoy nagtino kung unsa kini ka-acid."}, "source": "AAAS Benchmarks 4D Structure of Matter; consensus chemistry; DepEd Science CG (Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "base-releases-hydroxide-ions-g8", "domain": "MATTER", "topic": "bases release hydroxide ions in water", "grades": [8, 9, 10], "terms": ["base", "hydroxide ion", "OH-", "alkaline", "alkali", "tubig", "naglalabas", "ion", "base nagpagawas", "hydroxide", "natunaw sa tubig", "natunaw", "alkalino", "mapakla dahil sa ion"], "fact": {"tl": "Ang isang base ay naglalabas ng mga hydroxide ion (OH-) kapag natunaw sa tubig, at ito ang dahilan kung bakit ang mga base ay tinatawag ding alkaline.", "en": "A base releases hydroxide ions (OH-) when it dissolves in water, which is why bases are also called alkaline.", "bis": "Ang base nagpagawas og mga hydroxide ion (OH-) kung matunaw sa tubig, ug mao kini ang hinungdan nga ang mga base gitawag usab nga alkaline."}, "source": "AAAS Benchmarks 4D Structure of Matter; consensus chemistry; DepEd Science CG (Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "ph-each-unit-tenfold-g9", "domain": "MATTER", "topic": "each pH unit is a tenfold change in acidity", "grades": [9, 10], "terms": ["pH", "tenfold", "sampung beses", "10 times", "acidity", "pH 3", "pH 4", "mas maasim", "ten times more acidic", "napulo ka pilo", "kada pH", "pagkamaasim", "ka-asido", "pagkamaaslom"], "fact": {"tl": "Bawat isang bahagi ng paglayo sa pH scale ay nangangahulugang sampung beses na pagbabago sa pagkamaasim, kaya ang pH 3 ay sampung beses na mas maasim kaysa pH 4.", "en": "Each one-unit step on the pH scale means a tenfold change in acidity, so pH 3 is ten times more acidic than pH 4.", "bis": "Ang matag usa ka lakang sa pH scale nagpasabot og napulo ka pilo nga kausaban sa pagkamaaslom, busa ang pH 3 napulo ka pilo nga mas maaslom kay sa pH 4."}, "source": "Consensus chemistry; DepEd Science CG (Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "strong-vs-weak-acid-g9", "domain": "MATTER", "topic": "strong versus weak acids", "grades": [9, 10], "terms": ["strong acid", "weak acid", "malakas na acid", "mahinang acid", "muriatic", "vinegar", "suka", "tumutunaw nang buo", "fully", "bahagya", "ionize", "kusganon nga acid", "huyang nga acid", "dili tanan", "natutunaw nang buo", "partially"], "fact": {"tl": "Ang isang malakas na acid (tulad ng muriatic acid) ay halos buong naglalabas ng H+ sa tubig, habang ang isang mahinang acid (tulad ng suka) ay bahagya lamang naglalabas ng H+.", "en": "A strong acid (like muriatic acid) releases almost all of its H+ in water, while a weak acid (like vinegar) releases only a small part of its H+.", "bis": "Ang kusganon nga acid (sama sa muriatic acid) hapit tanan nga H+ niini gipagawas sa tubig, samtang ang huyang nga acid (sama sa suka) gamay ra nga bahin sa H+ ang gipagawas."}, "source": "Consensus chemistry; DepEd Science CG (Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "strength-vs-concentration-g10", "domain": "MATTER", "topic": "acid strength is different from concentration", "grades": [9, 10], "terms": ["strength", "concentration", "lakas", "konsentrasyon", "dilute", "concentrated", "malabnaw", "matapang", "iba ang lakas sa dami", "kusog", "kakusgon", "katumog", "lahi ang kusog sa konsentrasyon", "dilute strong acid", "weak but concentrated"], "fact": {"tl": "Ang lakas ng isang acid ay iba sa konsentrasyon nito: ang lakas ay kung gaano ito kadaling maglabas ng H+, samtang ang konsentrasyon ay kung gaano karami ang acid sa tubig.", "en": "An acid's strength is different from its concentration: strength is how readily it releases H+, while concentration is how much acid is dissolved in the water.", "bis": "Ang kakusog sa usa ka acid lahi sa konsentrasyon niini: ang kakusog mao kung unsa kadali kini magpagawas og H+, samtang ang konsentrasyon mao kung pila ka daghan ang acid nga natunaw sa tubig."}, "source": "Consensus chemistry; DepEd Science CG (Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "acid-metal-hydrogen-gas-g9", "domain": "MATTER", "topic": "acids react with metals to release hydrogen gas", "grades": [9, 10], "terms": ["acid", "metal", "hydrogen gas", "metal", "asido", "bakal", "naglalabas ng hydrogen", "bubbles", "bula", "zinc", "nagrereaksyon sa metal", "hydrogen gas", "nagreact sa metal", "puthaw", "salt", "asin", "korosyon"], "fact": {"tl": "Kapag ang isang acid ay nagreact sa maraming metal, lumalabas ang hydrogen gas bilang mga bula at naiiwan ang isang salt na natunaw sa tubig.", "en": "When an acid reacts with many metals, hydrogen gas comes out as bubbles and a dissolved salt is left behind.", "bis": "Kung ang acid magreact sa daghang metal, mogawas ang hydrogen gas isip mga bula ug mahibilin ang usa ka salt nga natunaw sa tubig."}, "source": "Consensus chemistry; DepEd Science CG (Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "neutralization-makes-salt-water-g9", "domain": "MATTER", "topic": "neutralization produces a salt and water", "grades": [9, 10], "terms": ["neutralization", "salt", "water", "acid", "base", "asin", "tubig", "neutralisasyon", "pinaghahalo", "gumagawa ng asin", "salt ug tubig", "neutralisar", "nagahimo og asin", "gisagol", "H+ at OH-", "nag-combine"], "fact": {"tl": "Sa neutralization, ang H+ mula sa acid at ang OH- mula sa base ay nagsasama upang bumuo ng tubig, at ang natitirang mga ion ay bumubuo ng isang salt.", "en": "In neutralization, the H+ from the acid and the OH- from the base join to form water, and the leftover ions form a salt.", "bis": "Sa neutralization, ang H+ gikan sa acid ug ang OH- gikan sa base nag-usa aron mahimong tubig, ug ang nahibilin nga mga ion nagporma og usa ka salt."}, "source": "Consensus chemistry; DepEd Science CG (Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "salt-is-ionic-compound-g9", "domain": "MATTER", "topic": "a salt is an ionic compound from acid and base", "grades": [9, 10], "terms": ["salt", "ionic compound", "asin", "kompound", "positive ion", "negative ion", "hindi lang table salt", "metal at acid", "salt nga kompound", "dili lang asin sa pagkaon", "positibo nga ion", "negatibo nga ion", "sodium chloride", "potassium chloride"], "fact": {"tl": "Sa kimika, ang salt ay hindi lang ang asin sa pagkaon kundi anumang ionic compound na nabuo kapag ang positive ion mula sa base ay nagsama sa negative ion mula sa acid.", "en": "In chemistry a salt is not just table salt but any ionic compound formed when the positive ion from a base joins the negative ion from an acid.", "bis": "Sa kemika ang salt dili lang ang asin sa pagkaon kondili bisan unsang ionic compound nga naporma kung ang positibo nga ion gikan sa base mag-usa sa negatibo nga ion gikan sa acid."}, "source": "Consensus chemistry; DepEd Science CG (Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "acid-base-solutions-conduct-electricity-g9", "domain": "MATTER", "topic": "acids and bases conduct electricity", "grades": [9, 10], "terms": ["conduct electricity", "kuryente", "ion", "electrolyte", "nagdadala ng kuryente", "acid", "base", "solution", "salt water", "tubig-asin", "nagpadagan og kuryente", "kuryente", "ions move", "gumagalaw ang ion", "naghatud og kuryente", "electrolyte"], "fact": {"tl": "Ang mga solusyon ng acid at base ay nakakapagdala ng kuryente dahil naglalaman sila ng mga gumagalaw na ion; kaya rin ang tubig-asin ay nakakapagdaloy ng kuryente.", "en": "Acid and base solutions can carry electricity because they contain moving ions; this is also why salt water can conduct electricity.", "bis": "Ang mga solusyon sa acid ug base makahatud og kuryente kay aduna silay naglihok nga mga ion; mao usab kini ang hinungdan nga ang tubig-asin makahatud og kuryente."}, "source": "Consensus chemistry; DepEd Science CG (Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "universal-indicator-rainbow-g8", "domain": "MATTER", "topic": "universal indicator shows a range of pH colors", "grades": [7, 8, 9], "terms": ["universal indicator", "pH color", "kulay", "indicator", "buong saklaw", "red to violet", "pula hanggang lila", "color chart", "tsart ng kulay", "tibuok han-ay", "pula hangtod lila", "indikator", "sukatan ng kulay", "pH paper"], "fact": {"tl": "Ang universal indicator ay isang halong indicator na nagbabago ng kulay sa buong saklaw ng pH, mula pula sa malakas na acid hanggang lila sa malakas na base, kaya nasasabi natin ang tinatayang pH.", "en": "Universal indicator is a mixture of indicators that changes through a range of colors, from red in a strong acid to violet in a strong base, so we can estimate the pH.", "bis": "Ang universal indicator usa ka sinagol nga indicator nga nag-usab og kolor sa tibuok han-ay sa pH, gikan pula sa kusganon nga acid hangtod lila sa kusganon nga base, busa matag-an nato ang pH."}, "source": "Consensus chemistry; DepEd Science CG (Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "phenolphthalein-indicator-g10", "domain": "MATTER", "topic": "phenolphthalein indicator turns pink in base", "grades": [9, 10], "terms": ["phenolphthalein", "indicator", "pink", "kulay-rosas", "colorless", "walang kulay sa acid", "base", "titration", "nagiging pink sa base", "indikator", "rosas sa base", "walay kolor sa acid", "kupas", "asido"], "fact": {"tl": "Ang phenolphthalein ay isang indicator na walang kulay sa acid at sa neutral ngunit nagiging kulay-rosas sa base, kaya madalas itong gamitin sa titration.", "en": "Phenolphthalein is an indicator that is colorless in acid and neutral but turns pink in a base, so it is often used in titration.", "bis": "Ang phenolphthalein usa ka indicator nga walay kolor sa acid ug sa neutral apan magrosas sa base, busa kasagaran kini gamiton sa titration."}, "source": "Consensus chemistry; DepEd Science CG (Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "carbonic-acid-soda-g8", "domain": "MATTER", "topic": "dissolved carbon dioxide makes water acidic", "grades": [7, 8, 9], "terms": ["carbon dioxide", "carbonic acid", "soft drink", "soda", "maasim", "carbonated", "natunaw na CO2", "fizzy", "acid mula sa CO2", "carbonic acid", "natunaw nga CO2", "softdrink", "maaslom", "sparkling water", "ulan", "rainwater"], "fact": {"tl": "Kapag natunaw ang carbon dioxide sa tubig, bahagya itong nagiging carbonic acid, kaya ang mga softdrink at maging ang likas na ulan ay bahagyang maasim.", "en": "When carbon dioxide dissolves in water it forms a little carbonic acid, which is why soft drinks and even natural rainwater are slightly acidic.", "bis": "Kung ang carbon dioxide matunaw sa tubig nahimo kining gamay nga carbonic acid, mao nga ang mga softdrink ug bisan ang natural nga ulan gamay nga maaslom."}, "source": "Consensus chemistry; DepEd Science CG (Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-acidification-co2-g9", "domain": "MATTER", "topic": "ocean acidification from carbon dioxide", "grades": [8, 9, 10], "terms": ["ocean acidification", "carbon dioxide", "dagat", "coral", "shell", "kabibe", "mas maasim na dagat", "acid", "korales", "nagiging maasim ang dagat", "nag-asido ang dagat", "kinhason", "mahina ang kabibe", "calcium carbonate", "pollution"], "fact": {"tl": "Habang sumisipsip ang dagat ng dagdag na carbon dioxide mula sa hangin, bahagya itong nagiging mas maasim, na nagpapahirap sa mga corals at kabibe na bumuo ng kanilang matigas na balat.", "en": "As the ocean absorbs extra carbon dioxide from the air, it becomes slightly more acidic, making it harder for corals and shellfish to build their hard shells.", "bis": "Samtang ang dagat magsuyop og dugang nga carbon dioxide gikan sa hangin, nahimo kining gamay nga mas maaslom, nga naglisod sa mga korales ug kinhason sa pagporma sa ilang gahi nga panit."}, "source": "Consensus environmental science; NRC ESS3; DepEd Science CG (Earth/Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "blood-narrow-ph-range-g10", "domain": "LIVING_THINGS", "topic": "blood is kept at a steady slightly basic pH", "grades": [9, 10], "terms": ["blood pH", "dugo", "7.4", "slightly basic", "buffer", "panatili", "homeostasis", "pH ng dugo", "bahagyang base", "kontrolado", "pH sa dugo", "gamay nga base", "gibantayan", "patas", "stable", "lihiya sa lawas"], "fact": {"tl": "Ang dugo ng tao ay pinananatili sa napakakitid na saklaw ng pH na bahagyang base (mga 7.4), at ang malaking pagbabago nito ay maaaring nakakasama sa katawan.", "en": "Human blood is kept within a very narrow, slightly basic pH range (about 7.4), and a big change in it can be harmful to the body.", "bis": "Ang dugo sa tawo gibantayan sa pig-ot kaayo nga han-ay sa pH nga gamay nga base (mga 7.4), ug ang dako nga kausaban niini makadaot sa lawas."}, "source": "Consensus physiology; DepEd Science CG (Living Things, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "stomach-acid-strong-ph-g9", "domain": "LIVING_THINGS", "topic": "stomach acid is a strong acid with very low pH", "grades": [8, 9, 10], "terms": ["stomach acid", "hydrochloric acid", "sikmura", "pH 1", "napakaasim", "gastric", "tiyan", "asido sa sikmura", "muriatic-like", "napakababa ng pH", "tiyan", "asido sa tiyan", "hydrochloric acid", "ubos kaayo ang pH", "digestion", "natutunaw ang pagkain"], "fact": {"tl": "Ang likas na asido sa sikmura ay hydrochloric acid na napakaasim (pH na halos 1–2), na tumutulong tunawin ang pagkain at pumatay ng mga mikrobyo.", "en": "The natural acid in the stomach is hydrochloric acid that is very acidic (pH around 1–2), which helps break down food and kill microbes.", "bis": "Ang natural nga asido sa tiyan kay hydrochloric acid nga maaslom kaayo (pH mga 1–2), nga makatabang sa pagtunaw sa pagkaon ug pagpatay sa mga mikrobyo."}, "source": "Consensus physiology; DepEd Science CG (Living Things, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "soil-ph-affects-plants-g8", "domain": "LIVING_THINGS", "topic": "soil pH affects how plants grow", "grades": [7, 8, 9], "terms": ["soil pH", "lupa", "tanim", "asidong lupa", "apog", "lime", "magsasaka", "pH ng lupa", "acidic soil", "alkaline soil", "pH sa yuta", "yuta", "tanom", "apog para sa lupa", "fertilizer", "abono", "nutrients", "sustansya"], "fact": {"tl": "Ang pH ng lupa ay nakakaapekto sa paglaki ng mga tanim dahil kinokontrol nito kung gaano kadaling makuha ng ugat ang mga sustansya; minsan naglalagay ang mga magsasaka ng apog upang bawasan ang asido ng lupa.", "en": "Soil pH affects plant growth because it controls how easily roots can take up nutrients; farmers sometimes add lime to reduce a soil's acidity.", "bis": "Ang pH sa yuta makaapekto sa pagtubo sa mga tanom kay gikontrol niini kung unsa kasayon makuha sa gamot ang mga sustansya; usahay magbutang ang mga mag-uuma og apog aron kunhoran ang kaaslom sa yuta."}, "source": "Consensus agricultural science; DepEd Science CG (Living Things/Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "soap-base-feels-slippery-g8", "domain": "MATTER", "topic": "why soap and bases feel slippery", "grades": [7, 8, 9], "terms": ["soap", "sabon", "madulas", "base", "madanlog", "langis", "oils on skin", "bakit madulas ang sabon", "slippery", "kalansay sa kamot", "ngano madanlog", "natutunaw ang langis", "saponification", "naglilinis", "fatty"], "fact": {"tl": "Madulas ang pakiramdam ng sabon at iba pang base dahil bahagya nitong tinutunaw ang langis sa balat, kaya rin epektibo ang sabon sa paglilinis.", "en": "Soap and other bases feel slippery because they slightly break down the oils on the skin, which is also why soap is good at cleaning.", "bis": "Madanlog ang bati sa sabon ug ubang base kay gamay niini nga gitunaw ang lana sa panit, mao usab nga epektibo ang sabon sa paglimpyo."}, "source": "Consensus chemistry; DepEd Science CG (Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "soap-made-by-base-and-fat-g9", "domain": "MATTER", "topic": "soap is made by reacting fat with a base", "grades": [9, 10], "terms": ["soap making", "saponification", "sabon", "lye", "lihiya", "taba", "fat", "oil", "langis", "paggawa ng sabon", "base at taba", "sodium hydroxide", "paghimo og sabon", "lihiya ug tambok", "tambok", "coconut oil", "lana sa lubi"], "fact": {"tl": "Ginagawa ang sabon sa pamamagitan ng pagpapareact ng taba o langis sa isang malakas na base tulad ng lye, isang prosesong tinatawag na saponification.", "en": "Soap is made by reacting fat or oil with a strong base like lye, a process called saponification.", "bis": "Ang sabon gihimo pinaagi sa pagpareact sa tambok o lana ngadto sa kusganon nga base sama sa lihiya, usa ka proseso nga gitawag og saponification."}, "source": "Consensus chemistry; DepEd Science CG (Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "antacid-bases-named-g9", "domain": "MATTER", "topic": "antacids are mild bases that neutralize stomach acid", "grades": [8, 9, 10], "terms": ["antacid", "calcium carbonate", "magnesium hydroxide", "milk of magnesia", "gamot sa hyperacidity", "base", "neutralize", "antacid", "mahinang base", "pampakalma ng asido", "calcium carbonate", "magnesium hydroxide", "tambal sa hilanat sa tiyan", "huyang nga base", "pampakunhod sa asido"], "fact": {"tl": "Karamihan sa mga antacid ay mahinang base tulad ng calcium carbonate o magnesium hydroxide, na nag-neutralize sa labis na asido sa sikmura nang hindi gumagawa ng bagong panganib.", "en": "Most antacids are mild bases such as calcium carbonate or magnesium hydroxide, which neutralize the excess acid in the stomach without creating a new hazard.", "bis": "Kasagaran sa mga antacid mga huyang nga base sama sa calcium carbonate o magnesium hydroxide, nga nag-neutralize sa sobra nga asido sa tiyan nga walay bag-ong kakuyaw."}, "source": "Consensus chemistry and physiology; DepEd Science CG (Matter/Living Things, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "weak-acids-in-living-things-g9", "domain": "LIVING_THINGS", "topic": "weak acids occur naturally in living things", "grades": [8, 9, 10], "terms": ["citric acid", "acetic acid", "lactic acid", "weak acid", "kalamansi", "suka", "gatas", "natural acid", "citric acid", "lactic acid", "mahinang acid sa katawan", "huyang nga acid", "kalamansi", "gatas", "gatas na naaasim", "amino acid", "protina"], "fact": {"tl": "Maraming mahinang acid ang likas na matatagpuan sa mga buhay na bagay, tulad ng citric acid sa kalamansi, acetic acid sa suka, at lactic acid sa naaasim na gatas.", "en": "Many weak acids occur naturally in living things, such as citric acid in calamansi, acetic acid in vinegar, and lactic acid in souring milk.", "bis": "Daghang huyang nga acid ang natural nga makita sa mga buhi nga butang, sama sa citric acid sa kalamansi, acetic acid sa suka, ug lactic acid sa naaslom nga gatas."}, "source": "Consensus chemistry; DepEd Science CG (Matter/Living Things, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "pure-water-neutral-self-g9", "domain": "MATTER", "topic": "why pure water is neutral", "grades": [9, 10], "terms": ["pure water", "neutral", "purong tubig", "pH 7", "balanse", "H+ at OH-", "magkapareho", "bakit neutral ang tubig", "equal", "putli nga tubig", "patas", "ngano neutral", "managsama nga ion", "distilled water"], "fact": {"tl": "Ang purong tubig ay neutral (pH 7) dahil kaunti lamang ang H+ at OH- na nabubuo rito at magkapareho ang dami ng dalawa, kaya nagkakansela sila.", "en": "Pure water is neutral (pH 7) because only a tiny amount of H+ and OH- forms in it and the two are present in equal amounts, so they cancel out.", "bis": "Ang putli nga tubig neutral (pH 7) kay gamay ra ang H+ ug OH- nga naporma niini ug managsama ang gidaghanon sa duha, busa nagkakansela sila."}, "source": "Consensus chemistry; DepEd Science CG (Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "red-cabbage-indicator-range-g8", "domain": "MATTER", "topic": "red cabbage juice changes through several colors", "grades": [7, 8, 9], "terms": ["red cabbage", "repolyong pula", "indicator", "kulay", "pink sa acid", "berde sa base", "natural indicator", "pula nga repolyo", "color range", "saklaw ng kulay", "natural nga indikator", "berde", "lila", "purple", "homemade indicator"], "fact": {"tl": "Ang katas ng pulang repolyo ay isang natural na indicator na dumadaan sa maraming kulay: namumula sa malakas na acid, lila sa neutral, at nagiging berde hanggang dilaw-berde sa malakas na base.", "en": "Red cabbage juice is a natural indicator that passes through several colors: red in a strong acid, purple when neutral, and green to yellow-green in a strong base.", "bis": "Ang duga sa pula nga repolyo usa ka natural nga indicator nga moagi sa daghang kolor: pula sa kusganon nga acid, lila kung neutral, ug berde ngadto sa dalag-berde sa kusganon nga base."}, "source": "Consensus chemistry; DepEd Science CG (Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "salt-named-from-acid-base-pair-g10", "domain": "MATTER", "topic": "different acid and base pairs make different salts", "grades": [9, 10], "terms": ["sodium chloride", "potassium nitrate", "salt examples", "iba't ibang asin", "acid base pair", "table salt", "sodium chloride", "different salts", "lainlaing asin", "asin nga produkto", "potassium chloride", "calcium chloride", "fertilizer salt", "abono nga asin"], "fact": {"tl": "Iba't ibang pares ng acid at base ang gumagawa ng iba't ibang salt: ang muriatic acid at lye ay gumagawa ng table salt (sodium chloride), habang ang ibang pares ay gumagawa ng mga asing gamit sa abono.", "en": "Different pairs of acid and base make different salts: muriatic acid and lye make table salt (sodium chloride), while other pairs make salts used in fertilizers.", "bis": "Lainlaing paris sa acid ug base ang naghimo og lainlaing salt: ang muriatic acid ug lihiya naghimo og table salt (sodium chloride), samtang ang ubang paris naghimo og mga asin nga gamiton sa abono."}, "source": "Consensus chemistry; DepEd Science CG (Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "lime-neutralizes-acid-water-g9", "domain": "MATTER", "topic": "lime is used to neutralize acidic water and soil", "grades": [8, 9, 10], "terms": ["lime", "apog", "neutralize acid", "asidong tubig", "lawa", "calcium hydroxide", "base para sa lupa", "pampakalma ng asido", "apog para sa tubig", "neutralisar", "asido nga tubig", "yuta", "calcium hydroxide", "alkalino", "agriculture", "fishpond"], "fact": {"tl": "Naglalagay ang mga tao ng apog (isang base) sa labis na asidong lupa, lawa, o palaisdaan upang i-neutralize ang asido at gawing mas angkop sa buhay ang tubig o lupa.", "en": "People add lime (a base) to overly acidic soil, lakes, or fishponds to neutralize the acid and make the water or soil more fit for life.", "bis": "Magbutang ang mga tawo og apog (usa ka base) sa sobra ka-asido nga yuta, lanaw, o pundohanan sa isda aron i-neutralize ang asido ug himuong mas angay sa kinabuhi ang tubig o yuta."}, "source": "Consensus environmental and agricultural science; DepEd Science CG (Matter/Earth, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "indicators-only-show-acid-or-base-g8", "domain": "MATTER", "topic": "indicators detect but do not measure pH exactly", "grades": [7, 8, 9], "terms": ["indicator", "litmus", "indikator", "hindi sukat", "show acid or base", "qualitative", "pH meter", "panukat", "ipakita kung acid o base", "dili eksaktong sukod", "indikator", "litmus", "tabang sa pagtino", "rough", "papel"], "fact": {"tl": "Ipinapakita lamang ng litmus kung ang isang bagay ay acid o base, ngunit hindi nito sinasabi ang eksaktong pH; kailangan ng universal indicator o pH meter para sa numero.", "en": "Litmus only shows whether something is an acid or a base, but it does not tell the exact pH; a universal indicator or a pH meter is needed for the number.", "bis": "Ang litmus nagpakita lang kung ang usa ka butang acid o base, apan dili niini masulti ang eksaktong pH; gikinahanglan ang universal indicator o pH meter para sa numero."}, "source": "Consensus chemistry; DepEd Science CG (Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "acidic-foods-corrode-metal-g8", "domain": "MATTER", "topic": "acidic foods can corrode some metals", "grades": [7, 8, 9], "terms": ["acidic food", "corrode", "metal", "kalawang", "lata", "maasim na pagkain", "aluminum", "suka sa metal", "tumutunaw ng metal", "korosyon", "maaslom nga pagkaon", "lata", "puthaw", "ngano dili itago sa lata", "reactive metal", "tindahan"], "fact": {"tl": "Ang maasim na pagkain tulad ng suka, calamansi, at kamatis ay maaaring dahan-dahang tumunaw o sumira sa ilang metal, kaya hindi mainam na itago ang mga ito nang matagal sa hindi protektadong metal na lalagyan.", "en": "Acidic foods like vinegar, calamansi, and tomatoes can slowly corrode some metals, so they should not be stored for long in unprotected metal containers.", "bis": "Ang maaslom nga pagkaon sama sa suka, kalamansi, ug kamatis mahimong hinay-hinay nga magtunaw o magdaot sa pipila ka metal, busa dili kini angay itago og dugay sa dili protektado nga sudlanan nga metal."}, "source": "Consensus chemistry; DepEd Science CG (Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "acid-rain-from-sulfur-nitrogen-g9", "domain": "EARTH_SPACE", "topic": "what makes rain acidic", "grades": [8, 9, 10], "terms": ["acid rain", "sulfur dioxide", "nitrogen oxide", "ulan na asido", "polusyon", "usok", "sunog ng karbon", "acid rain", "burning fuel", "asido nga ulan", "polusyon sa hangin", "aso", "sulfur dioxide", "nakakasira ng halaman", "factory", "pabrika"], "fact": {"tl": "Nagiging asido ang ulan kapag ang mga gas tulad ng sulfur dioxide at nitrogen oxide mula sa pagsunog ng gasolina at karbon ay nahahalo sa tubig sa hangin upang bumuo ng mahinang acid.", "en": "Rain becomes acidic when gases like sulfur dioxide and nitrogen oxides from burning fuel and coal mix with water in the air to form weak acids.", "bis": "Ang ulan mahimong asido kung ang mga gas sama sa sulfur dioxide ug nitrogen oxide gikan sa pagsunog og gasolina ug karbon masagol sa tubig sa hangin aron mahimong huyang nga acid."}, "source": "Consensus environmental science; NRC ESS3; DepEd Science CG (Earth/Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "neutral-point-needs-right-amount-g9", "domain": "MATTER", "topic": "neutralization needs the right amounts of acid and base", "grades": [9, 10], "terms": ["neutralization", "tamang dami", "acid", "base", "sobra", "kulang", "exact amount", "hindi sapat", "tamang sukat", "neutralisasyon", "husto nga gidaghanon", "sobra nga acid", "kulang nga base", "balance", "endpoint", "titration"], "fact": {"tl": "Hindi sapat na basta paghaluin ang acid at base; kung sobra ang acid ay mananatiling maasim ang halo, at kung sobra ang base ay mananatiling mapakla, kaya kailangan ng tamang dami upang maabot ang neutral.", "en": "It is not enough to just mix an acid and a base; if there is too much acid the mix stays sour, and if there is too much base it stays bitter, so the right amounts are needed to reach neutral.", "bis": "Dili igo nga basta sagolan lang ang acid ug base; kung sobra ang acid magpabilin nga maaslom ang sinagol, ug kung sobra ang base magpabilin nga mapait, busa gikinahanglan ang husto nga gidaghanon aron maabot ang neutral."}, "source": "Consensus chemistry; DepEd Science CG (Matter, JHS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-gene-dna-segment-g9", "domain": "LIVING_THINGS", "topic": "what is a gene", "grades": [8, 9, 10], "terms": ["gene", "genes", "DNA", "deoxyribonucleic", "trait", "instruction", "code", "gen", "segment", "bahagi", "katangian", "pagkakahawig", "kahulugan", "tagubilin", "kinaiya", "gabay", "buhok", "nanunod"], "fact": {"tl": "Ang gene ay isang maikling bahagi ng DNA na nagdadala ng tagubilin para sa isang katangian, tulad ng kulay ng mata o kulay ng bulaklak; ang buong hanay ng DNA ng isang organismo ang humuhubog kung ano ang magiging anyo at gawi nito.", "en": "A gene is a short segment of DNA that carries the instructions for one trait, such as eye color or flower color; the full set of an organism's DNA shapes what it looks like and how it works.", "bis": "Ang gene usa ka mubo nga bahin sa DNA nga nagdala sa tagubilin para sa usa ka kinaiya, sama sa kolor sa mata o kolor sa bulak; ang tibuok DNA sa usa ka organismo maoy naghulma kon unsa ang dagway ug paagi niini."}, "source": "AAAS Benchmarks 5B/H3, 5B/H4 (genes are segments of DNA)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-dna-double-helix-g9", "domain": "LIVING_THINGS", "topic": "DNA double helix", "grades": [8, 9, 10], "terms": ["DNA", "double helix", "dobleng helix", "hagdang paikot", "twisted ladder", "molecule", "molekula", "bases", "A T C G", "adenine", "thymine", "guanine", "cytosine", "estruktura", "istruktura", "kawad", "baitang", "pagkakasunod-sunod", "han-ay"], "fact": {"tl": "Ang DNA ay hugis-dobleng helix, parang hagdang pilipit, at ang pagkakasunod-sunod ng apat na uri ng base nito (madalas tukuyin bilang A, T, C, at G) ang nagsisilbing code o tagubilin para sa buhay.", "en": "DNA is shaped like a double helix, a twisted ladder, and the order of its four kinds of bases (often called A, T, C, and G) is the code or instructions for life.", "bis": "Ang DNA porma og double helix, samag hagdan nga liko-liko, ug ang pagkasunod-sunod sa upat ka klase sa base niini (kasagaran tawgon nga A, T, C, ug G) maoy code o tagubilin alang sa kinabuhi."}, "source": "AAAS Benchmarks 5B/H3 (DNA = long chains of four kinds of smaller molecules); encyclopedia-stable Watson-Crick structure", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-chromosomes-package-dna-g9", "domain": "LIVING_THINGS", "topic": "chromosomes", "grades": [8, 9, 10], "terms": ["chromosome", "chromosomes", "kromosoma", "DNA", "nucleus", "nucleus ng selula", "packaged", "balot", "buhol", "thread", "sinulid", "gene", "genes", "nakaimbak", "selula"], "fact": {"tl": "Ang DNA ay nababalot sa loob ng mga istrukturang tinatawag na chromosomes na matatagpuan sa nucleus ng selula, at ang bawat chromosome ay may dala-dalang maraming gene.", "en": "DNA is packaged into structures called chromosomes found in the nucleus of a cell, and each chromosome carries many genes.", "bis": "Ang DNA giputos sulod sa mga estruktura nga gitawag og chromosomes nga makita sa nucleus sa selula, ug ang matag chromosome nagdala og daghang gene."}, "source": "AAAS Benchmarks 5B/H3-H4; encyclopedia-stable cell biology (chromosomes in nucleus)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-human-46-chromosomes-g9", "domain": "LIVING_THINGS", "topic": "human chromosome number", "grades": [8, 9, 10], "terms": ["46 chromosomes", "23 pairs", "23 pares", "kromosoma", "human", "tao", "pares", "pair", "23 na pares", "apatnaput-anim", "set", "bawat selula", "tagsa-tagsa"], "fact": {"tl": "Karaniwang may 46 na chromosomes ang bawat karaniwang selula ng tao, nakaayos sa 23 na pares, kung saan ang isa sa bawat pares ay galing sa ina at ang isa naman ay galing sa ama.", "en": "Each typical human body cell usually has 46 chromosomes, arranged in 23 pairs, with one of each pair coming from the mother and the other from the father.", "bis": "Ang matag ordinaryong selula sa tao kasagaran adunay 46 ka chromosomes, gihan-ay sa 23 ka pares, diin ang usa sa matag pares gikan sa inahan ug ang usa gikan sa amahan."}, "source": "Encyclopedia-stable human genetics (46 chromosomes, 23 pairs); AAAS 5B/M1 (half of genes from each parent)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-half-from-each-parent-g8", "domain": "LIVING_THINGS", "topic": "genes from each parent", "grades": [7, 8, 9], "terms": ["half genes", "kalahati", "each parent", "magulang", "ina", "ama", "sex cell", "sperm", "egg", "itlog", "fertilization", "fertilized egg", "ginikanan", "inahan", "amahan", "katunga", "anak", "namana"], "fact": {"tl": "Sa organismong may dalawang kasarian, kalahati ng mga gene ng anak ay galing sa ina at kalahati ay galing sa ama, kaya may halong katangian ng dalawang magulang ang bawat anak.", "en": "In organisms with two sexes, half of an offspring's genes come from the mother and half from the father, so each offspring carries a mix of both parents' traits.", "bis": "Sa mga organismo nga adunay duha ka sekso, ang katunga sa mga gene sa anak gikan sa inahan ug ang katunga gikan sa amahan, busa ang matag anak nagdala og sagol nga kinaiya sa duha ka ginikanan."}, "source": "AAAS Benchmarks 5B/M1b, 5B/M2 (half of genes from each parent)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-alleles-two-copies-g9", "domain": "LIVING_THINGS", "topic": "alleles", "grades": [8, 9, 10], "terms": ["allele", "alleles", "alel", "two copies", "dalawang kopya", "bersyon", "version", "gene version", "uri ng gene", "from each parent", "pares ng gene", "magkaibang", "duha ka kopya", "klase sa gene", "porma sa gene"], "fact": {"tl": "Ang allele ay isang bersyon ng isang gene; karaniwang may dalawang kopya ang isang organismo para sa isang katangian — isa mula sa ina at isa mula sa ama — at maaaring magkapareho o magkaiba ang dalawang allele na ito.", "en": "An allele is one version of a gene; an organism usually has two copies for a trait — one from the mother and one from the father — and these two alleles can be the same or different.", "bis": "Ang allele usa ka bersyon sa usa ka gene; ang organismo kasagaran adunay duha ka kopya para sa usa ka kinaiya — usa gikan sa inahan ug usa gikan sa amahan — ug kining duha ka allele mahimong managsama o magkalahi."}, "source": "Encyclopedia-stable Mendelian genetics (alleles); AAAS 5B/M1 (half genes from each parent)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-dominant-recessive-g9", "domain": "LIVING_THINGS", "topic": "dominant and recessive traits", "grades": [8, 9, 10], "terms": ["dominant", "recessive", "dominante", "recessive trait", "nangingibabaw", "natatago", "nakatago", "masunod", "ipinakikita", "hidden trait", "katangian", "kinaiya", "naglupig", "natabunan", "mawala", "lalabas", "modong", "tinago"], "fact": {"tl": "Kapag magkaiba ang dalawang allele ng isang organismo, ang dominanteng allele ang nangingibabaw at lumalabas sa anyo, habang ang recessive na allele ay natatago at lumalabas lamang kapag dalawang recessive na allele ang magkasama.", "en": "When an organism's two alleles differ, the dominant allele shows up in the appearance while the recessive allele stays hidden and shows only when two recessive alleles are present together.", "bis": "Kon magkalahi ang duha ka allele sa usa ka organismo, ang dominanteng allele maoy mogawas sa dagway samtang ang recessive nga allele magpabiling tinago ug mogawas lamang kon duha ka recessive nga allele ang magkauban."}, "source": "Encyclopedia-stable Mendelian genetics (dominant/recessive inheritance)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-genotype-vs-phenotype-g9", "domain": "LIVING_THINGS", "topic": "genotype vs phenotype", "grades": [8, 9, 10], "terms": ["genotype", "phenotype", "henotipo", "penotipo", "gene makeup", "anyo", "itsura", "nakikita", "hitsura", "alleles", "set ng gene", "katangiang lumalabas", "panggene", "gawi", "porma", "makita", "kombinasyon"], "fact": {"tl": "Ang genotype ay ang kombinasyon ng mga allele na taglay ng isang organismo, habang ang phenotype ay ang katangiang nakikita o lumalabas, tulad ng kulay ng mata; ang genotype ang dahilan ng phenotype.", "en": "The genotype is the combination of alleles an organism carries, while the phenotype is the trait you can actually see or observe, such as eye color; the genotype produces the phenotype.", "bis": "Ang genotype mao ang kombinasyon sa mga allele nga gibatonan sa usa ka organismo, samtang ang phenotype mao ang kinaiya nga makita o mamatikdan, sama sa kolor sa mata; ang genotype maoy hinungdan sa phenotype."}, "source": "Encyclopedia-stable Mendelian genetics (genotype vs phenotype)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-homozygous-heterozygous-g10", "domain": "LIVING_THINGS", "topic": "homozygous and heterozygous", "grades": [9, 10], "terms": ["homozygous", "heterozygous", "magkapareho", "magkaiba", "pares ng allele", "pure", "purong", "halong", "two same alleles", "BB", "bb", "Bb", "managsama", "magkalahi", "allele pair", "dalisay"], "fact": {"tl": "Kung magkapareho ang dalawang allele ng isang katangian (halimbawa BB o bb), ito ay tinatawag na homozygous; kung magkaiba naman ang dalawang allele (halimbawa Bb), ito ay heterozygous.", "en": "If an organism's two alleles for a trait are the same (for example BB or bb), it is called homozygous; if the two alleles are different (for example Bb), it is heterozygous.", "bis": "Kon managsama ang duha ka allele sa usa ka kinaiya (pananglitan BB o bb), gitawag kini nga homozygous; kon magkalahi ang duha ka allele (pananglitan Bb), kini heterozygous."}, "source": "Encyclopedia-stable Mendelian genetics (homozygous/heterozygous)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-punnett-square-purpose-g9", "domain": "LIVING_THINGS", "topic": "Punnett square", "grades": [8, 9, 10], "terms": ["Punnett square", "Punnett", "parisukat ni Punnett", "diagram", "tsart", "predict", "hula", "hinuha", "probabilidad", "posibleng anak", "kombinasyon ng allele", "offspring", "cross", "tawiran", "panaganaw", "tagna", "kahimoan", "grid"], "fact": {"tl": "Ang Punnett square ay isang simpleng tsart na ginagamit upang hulaan ang mga posibleng kombinasyon ng allele na maaaring matamo ng mga anak mula sa dalawang magulang.", "en": "A Punnett square is a simple chart used to predict the possible allele combinations that offspring might inherit from two parents.", "bis": "Ang Punnett square usa ka yano nga tsart nga gigamit aron tagnaan ang posibleng mga kombinasyon sa allele nga mahimong maangkon sa mga anak gikan sa duha ka ginikanan."}, "source": "Encyclopedia-stable Mendelian genetics (Punnett square); AAAS 5B/H2 (recombination of genes)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-monohybrid-3to1-ratio-g10", "domain": "LIVING_THINGS", "topic": "3 to 1 phenotype ratio", "grades": [9, 10], "terms": ["3:1 ratio", "tatlo isa", "ratio", "proporsyon", "monohybrid cross", "Bb x Bb", "dominant recessive", "phenotype ratio", "tatlong isa", "tagsa-tagsa", "tulo ngadto sa usa", "probabilidad", "tsansa", "dominante recessive"], "fact": {"tl": "Kapag dalawang magulang na parehong heterozygous (Bb x Bb) ang nagtawid, ang inaasahang proporsyon ng phenotype ng mga anak ay 3 sa 1 — tatlong may dominanteng katangian para sa bawat isang may recessive na katangian.", "en": "When two heterozygous parents (Bb x Bb) are crossed, the expected phenotype ratio of the offspring is 3 to 1 — three with the dominant trait for every one with the recessive trait.", "bis": "Kon duha ka heterozygous nga ginikanan (Bb x Bb) ang itawid, ang gipaabot nga proporsyon sa phenotype sa mga anak mao ang 3 ngadto sa 1 — tulo ang adunay dominanteng kinaiya sa matag usa nga adunay recessive nga kinaiya."}, "source": "Encyclopedia-stable Mendelian genetics (3:1 monohybrid phenotype ratio)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-probability-not-certainty-g9", "domain": "LIVING_THINGS", "topic": "inheritance is probability", "grades": [8, 9, 10], "terms": ["probability", "posibilidad", "tsansa", "chance", "hindi sigurado", "prediction", "hula", "average", "katiyakan", "random", "ratio", "tagna", "dili sigurado", "tagsa-tagsa", "kahigayonan", "panaglahi"], "fact": {"tl": "Ang mga proporsyon na ipinapakita ng Punnett square ay mga posibilidad lamang, hindi katiyakan; tulad ng paghagis ng barya, maaaring hindi eksaktong sundin ng kakaunting anak ang inaasahang ratio.", "en": "The ratios shown by a Punnett square are only probabilities, not certainties; like flipping a coin, a small number of offspring may not exactly follow the expected ratio.", "bis": "Ang mga proporsyon nga gipakita sa Punnett square mga posibilidad lamang, dili katinuod; sama sa paglabay og sensilyo, ang gamay nga gidaghanon sa anak mahimong dili eksakto nga mosunod sa gipaabot nga ratio."}, "source": "Encyclopedia-stable genetics (Mendelian ratios are probabilistic)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-sex-cells-half-chromosomes-g10", "domain": "LIVING_THINGS", "topic": "sex cells carry half the chromosomes", "grades": [9, 10], "terms": ["sex cell", "gamete", "sperm", "egg cell", "itlog", "tamod", "kalahati", "half chromosomes", "23 chromosomes", "fertilization", "pagsasanib", "pinagsama", "katunga", "selula sa sekso", "fertilized", "namana"], "fact": {"tl": "Ang mga sex cell tulad ng tamod at itlog ay may kalahati lamang ng karaniwang bilang ng chromosomes, kaya kapag nagsanib ang dalawa sa fertilization, nabubuo ang anak na may kumpletong bilang ng chromosomes mula sa dalawang magulang.", "en": "Sex cells like sperm and egg carry only half the usual number of chromosomes, so when the two join in fertilization, the offspring forms with the complete chromosome number from both parents.", "bis": "Ang mga sex cell sama sa tamod ug itlog adunay katunga lamang sa kasagarang gidaghanon sa chromosomes, busa kon magsanib ang duha sa fertilization, mahimo ang anak nga adunay kompletong gidaghanon sa chromosomes gikan sa duha ka ginikanan."}, "source": "AAAS Benchmarks 5B/M1, 5B/M2 (sexual reproduction, half genes from each parent); encyclopedia-stable meiosis", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-same-dna-every-cell-g9", "domain": "LIVING_THINGS", "topic": "same DNA in every body cell", "grades": [8, 9, 10], "terms": ["same DNA", "parehong DNA", "every cell", "bawat selula", "kopya", "copied", "fertilized egg", "magkapareho instruction", "kinopya", "tibuok lawas", "managsama DNA", "matag selula", "gisundog", "namana"], "fact": {"tl": "Mula sa isang fertilized egg, kinokopya ang parehong genetic information sa bawat bagong selula ng katawan, kaya halos lahat ng selula ng isang organismo ay may magkaparehong DNA kahit magkaiba ang kanilang gawain.", "en": "Starting from one fertilized egg, the same genetic information is copied into every new body cell, so nearly all of an organism's cells carry identical DNA even though they do different jobs.", "bis": "Sukad sa usa ka fertilized egg, ang samang genetic information gikopya sa matag bag-ong selula sa lawas, busa halos tanang selula sa usa ka organismo adunay managsamang DNA bisan og lahi ang ilang trabaho."}, "source": "AAAS Benchmarks 5B/M2c, 5B/H6 (same genetic information copied in each cell)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-dna-copied-before-division-g10", "domain": "LIVING_THINGS", "topic": "DNA copied before cell division", "grades": [9, 10], "terms": ["DNA replication", "kinopya", "duplicated", "cell division", "paghahati ng selula", "before dividing", "bawat bagong selula", "complete copy", "gisundog", "pagbahin sa selula", "kompletong kopya", "duplikado", "namana"], "fact": {"tl": "Bago maghati ang isang selula, kinokopya muna nito ang lahat ng DNA nito upang ang bawat bagong selula ay makatanggap ng kumpletong set ng genetic instructions.", "en": "Before a cell divides, it first copies all of its DNA so that each new cell receives a complete set of the genetic instructions.", "bis": "Sa dili pa mobahin ang usa ka selula, kopyahon una niini ang tanan nga DNA niini aron ang matag bag-ong selula makadawat og kompletong set sa genetic instructions."}, "source": "AAAS Benchmarks 5C/H4 (instructions duplicated before a cell divides)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-dna-builds-proteins-g10", "domain": "LIVING_THINGS", "topic": "DNA codes for proteins", "grades": [9, 10], "terms": ["protein", "proteins", "protina", "DNA instructions", "assemble protein", "gumagawa ng protina", "code", "build", "tagubilin", "amino acid", "pagbuo ng protina", "naghimo og protina", "magtukod", "selula", "nanunod"], "fact": {"tl": "Ang genetic information sa DNA ang nagbibigay ng tagubilin kung paano bubuuin ng selula ang mga protina, at ang mga protinang ito ang gumaganap ng halos lahat ng gawain sa loob ng buhay na organismo.", "en": "The genetic information in DNA provides the instructions for how a cell builds proteins, and these proteins carry out nearly all the work inside a living organism.", "bis": "Ang genetic information sa DNA naghatag og tagubilin kon unsaon paghimo sa selula ang mga protina, ug kining mga protina maoy nagbuhat sa halos tanang trabaho sulod sa buhi nga organismo."}, "source": "AAAS Benchmarks 5C/H4a (DNA provides instructions for assembling proteins)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-code-universal-g10", "domain": "LIVING_THINGS", "topic": "genetic code is shared by all life", "grades": [9, 10], "terms": ["genetic code", "universal", "lahat ng buhay", "shared code", "halos pareho", "all life forms", "common", "DNA code", "magkatulad", "kahawig", "tanang buhi", "managsama nga code", "kaugnayan", "kaubanan", "namana"], "fact": {"tl": "Halos pareho ang genetic code na ginagamit ng lahat ng buhay na bagay, mula bakterya hanggang tao, na isa sa mga patunay na ang lahat ng buhay sa Earth ay may magkakaugnay na pinagmulan.", "en": "The genetic code used by all living things, from bacteria to humans, is virtually the same, which is one piece of evidence that all life on Earth shares a common origin.", "bis": "Halos managsama ang genetic code nga gigamit sa tanang buhi nga butang, gikan sa bakterya hangtod sa tawo, nga usa sa mga ebidensya nga ang tanang kinabuhi sa Yuta adunay susamang gigikanan."}, "source": "AAAS Benchmarks 5C/H4b (genetic code virtually the same for all life forms)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-mutation-definition-g9", "domain": "LIVING_THINGS", "topic": "what is a mutation", "grades": [8, 9, 10], "terms": ["mutation", "mutations", "mutasyon", "pagbabago", "change DNA", "DNA change", "pagkakaiba", "gene change", "altered gene", "binagong gene", "pagbalhin", "kausaban", "pag-usab sa DNA", "nausab", "kalainan", "namana"], "fact": {"tl": "Ang mutation ay isang pagbabago sa pagkakasunod-sunod ng DNA; maaaring magbago, mawala, o madagdagan ang bahagi ng DNA, at maaari nitong baguhin kung paano gumagana ang isang gene.", "en": "A mutation is a change in the sequence of DNA; a part of the DNA may be altered, deleted, or added, and this can change how a gene works.", "bis": "Ang mutation usa ka kausaban sa pagkasunod-sunod sa DNA; ang usa ka bahin sa DNA mahimong mausab, mawala, o madugangan, ug kini makausab kon unsaon paglihok sa usa ka gene."}, "source": "AAAS Benchmarks 5B/H4 (inserting, deleting, or substituting DNA segments can alter genes)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-mutation-three-effects-g9", "domain": "LIVING_THINGS", "topic": "mutations can be harmful neutral or beneficial", "grades": [8, 9, 10], "terms": ["beneficial mutation", "harmful mutation", "neutral mutation", "nakakatulong", "nakakasama", "walang epekto", "mutasyon", "makabutang", "makadaot", "walay epekto", "epekto", "advantage", "disadvantage", "bentahe", "nakapinsala", "kapaki-pakinabang"], "fact": {"tl": "Ang epekto ng isang mutation ay maaaring mabuti, masama, o wala — may mutation na nakakatulong para mabuhay nang mas mahusay ang organismo, may nakakapinsala, at marami ang walang halos na epekto.", "en": "A mutation's effect can be helpful, harmful, or neutral — some mutations help an organism survive better, some are damaging, and many have little or no effect at all.", "bis": "Ang epekto sa usa ka mutation mahimong maayo, daotan, o wala — adunay mutation nga makatabang aron mas maayong mabuhi ang organismo, adunay makadaot, ug daghan ang walay halos epekto."}, "source": "AAAS Benchmarks 5B/H1, 5B/H4 (resulting features may help, harm, or have little or no effect)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-mutation-causes-g10", "domain": "LIVING_THINGS", "topic": "what causes mutations", "grades": [9, 10], "terms": ["mutation cause", "radiation", "radyasyon", "chemicals", "kemikal", "UV", "sanhi ng mutation", "nagiging sanhi", "copying error", "pagkakamali sa pagkopya", "hinungdan", "kemikal", "nausab", "ginikanan sa kausaban"], "fact": {"tl": "Maaaring dulot ng mga bagay tulad ng radiation at ilang kemikal ang mutation, o ng pagkakamali tuwing kinokopya ang DNA; kapag nangyari ito sa sex cells, maaari itong maipasa sa susunod na henerasyon.", "en": "Mutations can be caused by things like radiation and certain chemicals, or by mistakes made when DNA is copied; when they occur in sex cells, they can be passed on to the next generation.", "bis": "Ang mutation mahimong tungod sa mga butang sama sa radiation ug pipila ka kemikal, o sa sayop nga mahitabo kon kopyahon ang DNA; kon mahitabo kini sa sex cells, mahimo kining ipasa sa sunod nga henerasyon."}, "source": "AAAS Benchmarks 5B/H5 (mutations caused by radiation and chemicals; passed on if in sex cells)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-mutation-body-vs-sex-cell-g10", "domain": "LIVING_THINGS", "topic": "body cell vs sex cell mutations", "grades": [9, 10], "terms": ["body cell mutation", "sex cell mutation", "selula ng katawan", "hindi naipapasa", "naipapasa sa anak", "inherited", "not inherited", "henerasyon", "descendant cells", "lawas nga selula", "dili maipasa", "maipasa sa anak", "namana", "kaliwat"], "fact": {"tl": "Ang mutation na nangyayari sa karaniwang selula ng katawan ay hindi naipapasa sa anak; tanging ang mga mutation sa sex cells (tamod o itlog) ang maaaring maipasa sa susunod na henerasyon.", "en": "A mutation that happens in an ordinary body cell is not passed to offspring; only mutations in the sex cells (sperm or egg) can be passed on to the next generation.", "bis": "Ang mutation nga mahitabo sa ordinaryong selula sa lawas dili maipasa sa anak; ang mga mutation lamang sa sex cells (tamod o itlog) ang mahimong ipasa sa sunod nga henerasyon."}, "source": "AAAS Benchmarks 5B/H5, 5F/H5 (changes in non-reproductive cells cannot be passed on)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-acquired-traits-not-inherited-g10", "domain": "LIVING_THINGS", "topic": "acquired traits are not inherited", "grades": [9, 10], "terms": ["acquired trait", "natutuhan", "hindi minamana", "scar", "peklat", "muscles", "kasanayan", "experience", "karanasan", "learned", "not inherited", "naangkon", "wala mamana", "kabatid", "kasinatian", "namana", "natuon"], "fact": {"tl": "Ang mga katangiang nakuha sa buhay tulad ng peklat, malalaking kalamnan, o natutuhang kasanayan ay hindi naipapasa sa anak, dahil hindi nito binabago ang DNA sa sex cells ng magulang.", "en": "Traits gained during life such as a scar, big muscles, or learned skills are not passed to offspring, because they do not change the DNA in the parent's sex cells.", "bis": "Ang mga kinaiya nga naangkon sa kinabuhi sama sa peklat, dagkong kaunoran, o natun-an nga kahanas dili maipasa sa anak, kay wala niini usba ang DNA sa sex cells sa ginikanan."}, "source": "AAAS Benchmarks 5B/H5 (experiences affect offspring only if genes in sex cells are changed)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-sexual-reproduction-variation-g9", "domain": "LIVING_THINGS", "topic": "sexual reproduction creates variation", "grades": [8, 9, 10], "terms": ["variation", "pagkakaiba-iba", "sexual reproduction", "magkapatid", "siblings", "recombination", "paghahalo ng gene", "iba-iba ang anak", "bag-ong kombinasyon", "kalainan", "panagkalahi", "magsoon", "namana", "kombinasyon"], "fact": {"tl": "Sa sexual reproduction, naghahalo at nagsasama ang mga gene mula sa dalawang magulang sa bago-bagong kombinasyon, kaya magkakaiba-iba ang mga anak ng iisang mag-asawa kahit magkapatid sila.", "en": "In sexual reproduction, genes from two parents mix and combine in new ways, so offspring of the same two parents are varied and different from one another even as siblings.", "bis": "Sa sexual reproduction, ang mga gene gikan sa duha ka ginikanan magsagol ug magtipon sa bag-ong mga kombinasyon, busa lahi-lahi ang mga anak sa managsamang ginikanan bisan magsoon sila."}, "source": "AAAS Benchmarks 5B/H2 (sorting and recombination of genes gives great variety in offspring)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-variation-raw-material-evolution-g10", "domain": "LIVING_THINGS", "topic": "variation and new traits for evolution", "grades": [9, 10], "terms": ["heritable variation", "bagong katangian", "new trait", "evolution", "ebolusyon", "natural selection", "mutation", "gene combination", "minana", "pinagmulan ng pagbabago", "bag-ong kinaiya", "kabag-ohan", "kalainan", "namana", "kausaban", "pagpili sa kinaiyahan"], "fact": {"tl": "Ang mga bagong namamanang katangian ay nagmumula sa bagong kombinasyon ng mga gene o sa mutation sa reproductive cells, at ang ganitong pagkakaiba-iba ang pinagkukunan ng mga bagong katangiang maaaring piliin ng natural selection sa paglipas ng panahon.", "en": "New heritable traits arise from new combinations of genes or from mutations in reproductive cells, and this variation is the source of new traits that natural selection can act on over time.", "bis": "Ang bag-ong mapanunod nga mga kinaiya naggikan sa bag-ong kombinasyon sa mga gene o sa mutation sa reproductive cells, ug kini nga panagkalahi maoy gigikanan sa bag-ong mga kinaiya nga mapilian sa natural selection sa paglabay sa panahon."}, "source": "AAAS Benchmarks 5F/H5 (new heritable characteristics from new gene combinations or mutations in reproductive cells)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-dna-shows-relatedness-g10", "domain": "LIVING_THINGS", "topic": "DNA similarity shows relatedness", "grades": [9, 10], "terms": ["DNA similarity", "pagkakahawig ng DNA", "relatedness", "kaugnayan", "magkamag-anak na species", "common ancestor", "ninuno", "pareho ang DNA", "classification", "pagkakapareho", "kabanay", "managsamang DNA", "kaliwatan", "namana", "katigulangan"], "fact": {"tl": "Mas magkahawig ang DNA ng dalawang species kung mas malapit ang kanilang pagkakaugnay, kaya ginagamit ng mga siyentipiko ang pagkakahawig ng DNA upang malaman kung gaano kalapit ang mga organismo sa isa't isa.", "en": "Two species have more similar DNA the more closely related they are, so scientists use DNA similarity to figure out how closely organisms are related to one another.", "bis": "Mas managsama ang DNA sa duha ka species kon mas duol ang ilang panag-uban, busa gigamit sa mga siyentista ang pagkasama sa DNA aron mahibal-an kon unsa kaduol ang panaglambigit sa mga organismo sa usag usa."}, "source": "AAAS Benchmarks 5A/H2 (relatedness estimated from similarity of DNA sequences)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-cancer-uncontrolled-division-g10", "domain": "LIVING_THINGS", "topic": "mutations and cancer", "grades": [9, 10], "terms": ["cancer", "kanser", "uncontrolled cell division", "mutation", "walang kontrol na paghahati", "radiation", "chemicals", "tumor", "selula", "wala mapugngi nga pagbahin", "mutasyon", "pagdaghan sa selula", "namana"], "fact": {"tl": "Ang ilang mutation sa selula ay maaaring magdulot ng kanser, kung saan walang-kontrol na nagdadami ang selula; pinapataas ng pagkakalantad sa ilang kemikal at radiation ang tsansa ng ganitong mutation.", "en": "Some mutations in a cell can lead to cancer, in which cells divide without control; exposure to certain chemicals and radiation increases the chance of such mutations.", "bis": "Ang pipila ka mutation sa selula mahimong mosangpot sa kanser, diin ang mga selula magdaghan nga walay kontrol; ang pagkaladlad sa pipila ka kemikal ug radiation makadugang sa kahigayonan sa maong mutation."}, "source": "AAAS Benchmarks 5C/H6 (gene mutation can result in uncontrolled cell division called cancer)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-inherited-vs-environment-g9", "domain": "LIVING_THINGS", "topic": "genes and environment together", "grades": [8, 9, 10], "terms": ["genes and environment", "kapaligiran", "nature nurture", "namana", "katangian", "nutrition", "nutrisyon", "height", "taas", "phenotype", "interaction", "epekto ng paligid", "kinaiyahan", "palibot", "gitas-on"], "fact": {"tl": "Hindi lamang ang mga gene ang humuhubog sa anyo at gawi ng organismo; nakikipag-ugnayan din ang kapaligiran, kaya halimbawa ang taas ng tao ay naiimpluwensyahan ng kanyang minanang gene at ng nutrisyong natatanggap niya.", "en": "Genes are not the only thing that shapes an organism's appearance and behavior; the environment interacts with them too, so for example a person's height is influenced both by inherited genes and by the nutrition they receive.", "bis": "Dili lamang ang mga gene ang naghulma sa dagway ug paggawi sa organismo; ang palibot usab makig-uban niini, busa pananglitan ang gitas-on sa tawo naimpluwensyahan sa namana nga gene ug sa nutrisyon nga iyang nadawat."}, "source": "AAAS Benchmarks 5B (interaction between heredity and environment); encyclopedia-stable gene-environment interaction", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-cells-differ-same-dna-g10", "domain": "LIVING_THINGS", "topic": "different cell types from same DNA", "grades": [9, 10], "terms": ["cell specialization", "magkaibang selula", "same DNA", "skin cell", "muscle cell", "nerve cell", "iba't ibang gene ang ginagamit", "differentiation", "selula sa balat", "selula sa kaunoran", "lain-laing selula", "managsamang DNA", "gigamit nga gene", "namana"], "fact": {"tl": "Bagaman halos magkaparehong DNA ang lahat ng selula ng isang organismo, magkakaiba sila ng anyo at gawain — tulad ng selula ng balat at selula ng nerbiyo — dahil iba't ibang bahagi ng genetic instructions ang ginagamit sa bawat uri ng selula.", "en": "Although nearly all of an organism's cells carry the same DNA, they differ in form and function — like skin cells and nerve cells — because different parts of the genetic instructions are used in each cell type.", "bis": "Bisan og halos managsama ang DNA sa tanang selula sa usa ka organismo, lahi sila og porma ug buluhaton — sama sa selula sa panit ug selula sa nerbiyo — kay lain-laing bahin sa genetic instructions ang gigamit sa matag klase sa selula."}, "source": "AAAS Benchmarks 5B/H6 (different parts of genetic instructions used in different cell types)", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetics-pedigree-tracking-traits-g10", "domain": "LIVING_THINGS", "topic": "pedigree and selective breeding", "grades": [9, 10], "terms": ["pedigree", "talaangkanan", "selective breeding", "selektibong pagpaparami", "breeding", "trait tracking", "lahi ng hayop", "lahi ng halaman", "pinili", "ninuno", "kaliwat", "talaan sa kaliwatan", "pagpili sa kinaiya", "namana", "binhi"], "fact": {"tl": "Sa selective breeding, sinasadya ng mga tao na pagparamihin ang mga organismong may ninanais na katangian, at ang talaangkanan o pedigree ang ginagamit upang masubaybayan kung paano ipinapasa ang mga katangian sa magkakasunod na henerasyon.", "en": "In selective breeding, people deliberately breed organisms that have a desired trait, and a pedigree is used to track how traits are passed down through successive generations.", "bis": "Sa selective breeding, tinuyo sa mga tawo nga padaghanon ang mga organismo nga adunay gitinguha nga kinaiya, ug ang pedigree gigamit aron masubay kon giunsa pagpasa ang mga kinaiya sa nagsunod-sunod nga henerasyon."}, "source": "AAAS Benchmarks 5B (artificial selection, pedigrees, breeding to emphasize features)", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-definition-g10", "domain": "LIVING_THINGS", "topic": "biological evolution", "grades": [9, 10], "terms": ["evolution", "ebolusyon", "biological evolution", "species", "espesye", "klase", "nagbabago", "nagbag-o", "nag-uusbong", "pinanggalingan", "gigikanan", "nagmula", "naggikan", "henerasyon", "kaliwatan", "milyon-milyong taon", "milyon ka tuig", "ninuno", "katigulangan"], "fact": {"tl": "Ang ebolusyon ay ang unti-unting pagbabago ng mga klase ng buhay (species) sa napakahabang panahon, kung saan ang mga species ngayon ay nagmula sa mas naunang, ibang-iba nang species.", "en": "Evolution is the gradual change in kinds of living things (species) over very long time, in which today's species descended from earlier, distinctly different species.", "bis": "Ang ebolusyon mao ang hinay-hinay nga pagbag-o sa mga klase sa buhi nga butang (species) sa taas kaayo nga panahon, diin ang mga species karon naggikan sa mas una, lahi kaayo nga mga species."}, "source": "AAAS BSL 5F/H1; NRC LS4.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-natural-selection-mechanism-g10", "domain": "LIVING_THINGS", "topic": "natural selection", "grades": [9, 10], "terms": ["natural selection", "natural na pagpili", "natural nga pagpili", "mekanismo", "mekanismo sa ebolusyon", "bentahe", "kaayohan", "advantage", "mabuhay", "mabuhi", "magparami", "manganak", "survival", "reproduction", "mga katangian", "kinaiya", "namamana", "mapanunod", "darwin"], "fact": {"tl": "Sa natural selection, ang mga indibidwal na may mga namamanang katangiang nagbibigay ng bentahe ay mas malamang na mabuhay at magkaanak, kaya dumarami ang proporsiyon ng mga may-bentaheng katangian sa susunod na mga henerasyon.", "en": "In natural selection, individuals with inherited traits that give an advantage are more likely to survive and reproduce, so the proportion of individuals with the advantageous traits increases over the generations.", "bis": "Sa natural selection, ang mga indibidwal nga adunay napanunod nga kinaiya nga naghatag og bentaha mas lagmit nga mabuhi ug manganak, mao nga modaghan ang proporsiyon sa mga adunay mapuslanon nga kinaiya sa sunod nga mga henerasyon."}, "source": "AAAS BSL 5F/H3", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-variation-within-species-g9", "domain": "LIVING_THINGS", "topic": "variation within a species", "grades": [7, 8, 9], "terms": ["variation", "pagkakaiba-iba", "kalainlain", "variation within species", "hindi magkapareho", "dili managsama", "indibidwal", "kaiba", "kalainan", "namamanang katangian", "napanunod nga kinaiya", "heritable variation", "hilaw na materyal", "raw material", "natural selection"], "fact": {"tl": "May likas na pagkakaiba-iba (variation) sa mga namamanang katangian sa loob ng bawat species — walang dalawang indibidwal na talagang magkapareho — at ang variation na ito ang pinagpipilian ng natural selection.", "en": "There is natural variation in heritable traits within every species — no two individuals are exactly alike — and this variation is the raw material that natural selection acts on.", "bis": "Adunay kinaiyanhon nga kalainlain (variation) sa mga napanunod nga kinaiya sulod sa matag species — walay duha ka indibidwal nga managsama gayod — ug kini nga variation mao ang ginapili sa natural selection."}, "source": "AAAS BSL 5F/H3; NRC LS3.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-survival-reproduction-g9", "domain": "LIVING_THINGS", "topic": "survival and reproduction", "grades": [7, 8, 9], "terms": ["survival", "pananatiling buhay", "pagkabuhi", "reproduction", "pagpaparami", "pagpanganak", "differential survival", "mas malamang", "mas lagmit", "anak", "kaliwat", "kompetisyon", "kompetensya", "limitadong pagkain", "limitado nga pagkaon", "fittest", "mabuhay at magparami"], "fact": {"tl": "Hindi lahat ng indibidwal ay nabubuhay para magkaanak; ang may mga katangiang akma sa kapaligiran ang mas malamang na mabuhay at makapagparami, kaya naipapasa nila ang kanilang katangian sa mas maraming anak.", "en": "Not all individuals survive to reproduce; those with traits suited to their environment are more likely to survive and reproduce, so they pass their traits to more offspring.", "bis": "Dili tanan nga indibidwal mabuhi aron manganak; kadtong adunay kinaiya nga haom sa palibot mas lagmit nga mabuhi ug makapanganak, mao nga ilang ikapasa ang ilang kinaiya ngadto sa mas daghang anak."}, "source": "AAAS BSL 5F/H4b; 5F/M2a", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-mutation-new-traits-g10", "domain": "LIVING_THINGS", "topic": "source of new heritable traits", "grades": [9, 10], "terms": ["mutation", "mutasyon", "new traits", "bagong katangian", "bag-ong kinaiya", "genes", "gene", "reproductive cells", "selula sa pagpaparami", "namamana", "mapanunod", "bagong kombinasyon", "bag-ong kombinasyon", "pagkakaiba-iba", "kalainlain", "DNA", "heritable", "naipapasa"], "fact": {"tl": "Ang mga bagong namamanang katangian ay nagmumula sa mga bagong kombinasyon ng genes o sa mutasyon (pagbabago) ng genes sa mga selula ng pagpaparami; ang pagbabago sa ibang selula ng katawan ay hindi naipapasa sa susunod na henerasyon.", "en": "New heritable traits arise from new combinations of genes or from mutations (changes) of genes in reproductive cells; changes in the body's other cells cannot be passed to the next generation.", "bis": "Ang bag-ong napanunod nga mga kinaiya naggikan sa bag-ong kombinasyon sa genes o sa mutasyon (pagbag-o) sa genes sa mga selula sa pagpaparami; ang pagbag-o sa ubang selula sa lawas dili ikapasa sa sunod nga henerasyon."}, "source": "AAAS BSL 5F/H5", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-population-not-individual-g10", "domain": "LIVING_THINGS", "topic": "evolution acts on populations", "grades": [9, 10], "terms": ["population", "populasyon", "pangkat", "grupo", "individual", "indibidwal", "proporsiyon", "proportion", "hindi nagbabago ang indibidwal", "dili mabag-o ang indibidwal", "nagbabago ang populasyon", "nagbag-o ang populasyon", "katangian", "kinaiya", "henerasyon", "kaliwatan", "natural selection"], "fact": {"tl": "Ang isang indibidwal ay hindi nagbabago (nag-eevolve) sa sarili nitong buhay; sa halip, ang nagbabago sa paglipas ng panahon ay ang proporsiyon ng isang katangian sa buong populasyon.", "en": "A single individual does not evolve during its own lifetime; instead, what changes over time is the proportion of a trait within the whole population.", "bis": "Ang usa ka indibidwal dili mabag-o (mo-evolve) sa iyang kaugalingong kinabuhi; hinuon, ang mausab paglabay sa panahon mao ang proporsiyon sa usa ka kinaiya sa tibuok populasyon."}, "source": "AAAS BSL Ch.5F (individual-versus-population)", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-adaptation-over-time-g9", "domain": "LIVING_THINGS", "topic": "adaptation over time", "grades": [8, 9, 10], "terms": ["adaptation", "adaptasyon", "pag-angkop", "pagpahiangay", "well-suited", "akma sa kapaligiran", "haom sa palibot", "unti-unting nabuo", "hinay-hinay nga gibuhat", "namamanang katangian", "napanunod nga kinaiya", "kapaligiran", "palibot", "mabuhay", "mabuhi", "natural selection", "henerasyon"], "fact": {"tl": "Ang adaptasyon ay ang namamanang katangiang nagpapadali sa pagkabuhay sa isang partikular na kapaligiran; nabubuo ito nang unti-unti sa maraming henerasyon dahil pinili ng natural selection ang mga katangiang nakakatulong sa pananatiling buhay.", "en": "An adaptation is a heritable trait that makes survival easier in a particular environment; it builds up gradually over many generations because natural selection favors traits that help survival.", "bis": "Ang adaptasyon mao ang napanunod nga kinaiya nga nagpasayon sa pagkabuhi sa usa ka partikular nga palibot; mabuo kini hinay-hinay sa daghang henerasyon tungod kay gipili sa natural selection ang mga kinaiya nga makatabang sa pagkabuhi."}, "source": "AAAS BSL 5F/H6a; NRC LS4.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-changing-environment-survival-value-g10", "domain": "LIVING_THINGS", "topic": "changing environment changes selection", "grades": [9, 10], "terms": ["changing environment", "nagbabagong kapaligiran", "nagbag-o nga palibot", "survival value", "halaga sa pagkabuhay", "bili sa pagkabuhi", "dating kapaki-pakinabang", "kaniadto mapuslanon", "naging disbentahe", "nahimong disbentaha", "katangian", "kinaiya", "natural selection", "extinction", "klima", "klimate"], "fact": {"tl": "Kapag nagbago ang kapaligiran — kasama na ang ibang organismong naroon — maaaring magbago rin ang halaga ng isang namamanang katangian: ang dating kapaki-pakinabang ay maaaring maging walang silbi o disbentaha.", "en": "When the environment changes — including the other organisms in it — the survival value of an inherited trait can change too: what was once useful may become useless or a disadvantage.", "bis": "Kon mabag-o ang palibot — apil na ang ubang organismo niini — mahimo usab nga mausab ang bili sa usa ka napanunod nga kinaiya: ang kaniadto mapuslanon mahimong walay pulos o disbentaha."}, "source": "AAAS BSL 5F/H6c", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-common-ancestor-g10", "domain": "LIVING_THINGS", "topic": "common ancestry", "grades": [9, 10], "terms": ["common ancestor", "common ancestry", "iisang ninuno", "usa ka katigulangan", "magkakaugnay", "magkadugtong", "may kaugnayan", "may kalabotan", "naglalala", "nagsanga", "tree of life", "puno ng buhay", "kahoy sa kinabuhi", "descent", "pinagmulan", "gigikanan", "DNA", "molecular evidence"], "fact": {"tl": "Ipinapakita ng ebidensiya na ang lahat ng buhay sa Earth ay magkakaugnay dahil nagmula sila sa iisang ninuno; ang mga linya ng buhay ay nagsanga-sanga sa paglipas ng panahon na parang puno o palumpong.", "en": "Evidence shows that all life on Earth is related because it descended from common ancestors; the lines of life branched over time like a tree or a bush.", "bis": "Gipakita sa ebidensiya nga ang tanan nga buhi sa Yuta adunay kalabotan tungod kay sila naggikan sa usa ka katigulangan; ang mga linya sa kinabuhi nagsanga-sanga paglabay sa panahon sama sa kahoy o sapinit."}, "source": "AAAS BSL 5F/H2; 5F/H9", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-fossil-evidence-g9", "domain": "LIVING_THINGS", "topic": "fossil evidence for evolution", "grades": [7, 8, 9], "terms": ["fossil", "fosil", "fossils", "mga fosil", "sedimentary rock", "sedimentaryong bato", "layers", "mga patong", "mga sapaw", "lumang buhay", "karaang kinabuhi", "patunay", "pamatuod", "ebidensya", "ebidensiya", "nagbabagong anyo ng buhay", "nag-usab nga klase sa buhi", "extinct", "naglaho", "namatay"], "fact": {"tl": "Ang libu-libong patong ng sedimentaryong bato na may lamang mga fosil ay nagbibigay ng patunay sa napakahabang kasaysayan ng nagbabagong anyo ng buhay sa Earth.", "en": "The many thousands of layers of sedimentary rock that contain fossils provide evidence for the very long history of changing life forms on Earth.", "bis": "Ang liboan ka sapaw sa sedimentaryong bato nga adunay sulod nga mga fosil naghatag og pamatuod sa taas kaayo nga kasaysayan sa nag-usab nga klase sa buhi sa Yuta."}, "source": "AAAS BSL 5F/M3a", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-fossil-rock-layers-order-g9", "domain": "LIVING_THINGS", "topic": "relative age of fossils", "grades": [8, 9], "terms": ["rock layers", "patong ng bato", "sapaw sa bato", "relative age", "relatibong edad", "edad nga gitandi", "mas bago", "mas bag-o", "mas luma", "mas karaan", "ibabaw", "ilalim", "ubos", "fossil", "fosil", "nakatabon", "natabunan", "kamakailan", "bag-o lang", "existing species", "buhay pa"], "fact": {"tl": "Ang mga fosil sa mas itaas (mas bagong) patong ng bato ay karaniwang mas kahawig ng mga species na buhay pa ngayon, samantalang ang mga fosil sa mas malalim (mas lumang) patong ay madalas na ibang-iba na.", "en": "Fossils in higher (more recently deposited) rock layers usually resemble species still living today, while fossils in deeper (older) layers are often quite different.", "bis": "Ang mga fosil sa mas taas (mas bag-ong gibutang) nga sapaw sa bato kasagaran mas susama sa mga species nga buhi pa karon, samtang ang mga fosil sa mas lawom (mas karaang) nga sapaw kasagaran lahi na kaayo."}, "source": "AAAS BSL 5F/M3b", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-comparative-anatomy-homologous-g10", "domain": "LIVING_THINGS", "topic": "comparative anatomy evidence", "grades": [9, 10], "terms": ["comparative anatomy", "paghahambing ng anatomiya", "pagtandi sa anatomiya", "homologous structures", "magkatulad na buto", "managsama nga bukog", "kamay", "bukton", "pakpak", "pako", "palikpik", "lapay", "buto", "bukog", "balangkas", "estruktura", "common ancestor", "iisang ninuno", "ebidensya", "pamatuod"], "fact": {"tl": "Ang braso ng tao, pakpak ng paniki, at palikpik ng balyena ay may magkatulad na ayos ng mga buto, na nagpapakitang nagmula silang lahat sa iisang ninuno kahit magkaiba ang kanilang gamit ngayon.", "en": "The human arm, the bat's wing, and the whale's flipper share the same underlying pattern of bones, showing they all came from a common ancestor even though their uses differ today.", "bis": "Ang bukton sa tawo, pako sa kabog, ug palikpik sa balyena adunay managsama nga han-ay sa mga bukog, nga nagpakita nga silang tanan naggikan sa usa ka katigulangan bisan og lahi ang ilang gamit karon."}, "source": "AAAS BSL 5F/H2 (anatomical evidence)", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-vestigial-structures-g10", "domain": "LIVING_THINGS", "topic": "vestigial structures", "grades": [9, 10], "terms": ["vestigial", "vestigial structure", "labi ng dating bahagi", "salin sa bahagi", "natitirang bahagi", "walang silbi na", "wala nay pulos", "appendix", "apendiks", "buto sa hita ng ahas", "bukog sa paa sa bitin", "ninuno", "katigulangan", "ebidensya", "pamatuod", "nawalan ng gamit", "nawad-an og gamit"], "fact": {"tl": "Ang mga vestigial na bahagi ay mga maliliit na salin ng istrukturang ganap nang gumagana sa mga ninuno ngunit halos walang silbi na ngayon — gaya ng natitirang buto ng hita sa loob ng katawan ng ilang ahas at balyena.", "en": "Vestigial structures are small leftovers of structures that were fully functional in ancestors but serve little purpose now — like the remnant hip bones inside some snakes and whales.", "bis": "Ang mga vestigial nga bahin mao ang gagmay nga salin sa mga estruktura nga hingpit nga naglihok sa mga katigulangan apan wala nay pulos karon — sama sa salin nga bukog sa paa sulod sa lawas sa pipila ka bitin ug balyena."}, "source": "Encyclopedia consensus; AAAS BSL 5F (anatomical evidence)", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-galapagos-finches-g10", "domain": "LIVING_THINGS", "topic": "Galapagos finches and Darwin", "grades": [9, 10], "terms": ["galapagos", "galapagos finches", "darwin", "charles darwin", "finch", "ibon", "langgam", "tuka", "tuka sa langgam", "porma sa tuka", "iba-ibang pagkain", "lainlaing pagkaon", "natural selection", "adaptation", "isla", "isolated", "nahiwalay", "nabukod"], "fact": {"tl": "Sa Galápagos Islands, napansin ni Charles Darwin na ang magkakaugnay na finch ay may iba-ibang hugis ng tuka na akma sa iba-ibang pagkain sa bawat isla — isang halimbawa ng natural selection na humubog sa kaniyang teorya.", "en": "On the Galápagos Islands, Charles Darwin noticed that related finches had different beak shapes suited to different foods on each island — an example of natural selection that shaped his theory.", "bis": "Sa Galápagos Islands, namatikdan ni Charles Darwin nga ang managsoon nga mga finch adunay lainlaing porma sa tuka nga haom sa lainlaing pagkaon sa matag isla — usa ka pananglitan sa natural selection nga naghulma sa iyang teoriya."}, "source": "Encyclopedia consensus (Darwin, Galápagos)", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-antibiotic-resistance-g10", "domain": "LIVING_THINGS", "topic": "antibiotic resistance as natural selection", "grades": [9, 10], "terms": ["antibiotic resistance", "resistensya sa antibiotic", "antibiotiko", "bakterya", "bacteria", "lumalaban na bakterya", "nakasugakod nga bakterya", "namamatay", "nangamatay", "nakaligtas", "nakaluwas", "nagparami", "nagdaghan", "natural selection", "obserbahan", "makita karon", "gamot", "tambal", "ospital"], "fact": {"tl": "Kapag ginamitan ng antibiotic ang bakterya, namamatay ang mga mahina ngunit nakaliligtas ang ilang likas na lumalaban; ang mga nakaligtas na ito ang nagpaparami, kaya unti-unting nagiging lahat-lumalaban ang populasyon — natural selection na nakikita sa loob lang ng maikling panahon.", "en": "When bacteria are exposed to an antibiotic, the weak ones die but a few that are naturally resistant survive; those survivors reproduce, so the population becomes resistant over time — natural selection observed in a short span.", "bis": "Kon gamitan og antibiotic ang bakterya, mamatay ang mga huyang apan maluwas ang pipila nga kinaiyanhong nakasugakod; kining mga naluwas ang manganak, mao nga hinay-hinay nga mahimong nakasugakod ang tibuok populasyon — natural selection nga makita sa mubo nga panahon."}, "source": "Encyclopedia/medical consensus; AAAS BSL 5F/H3", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-peppered-moth-g10", "domain": "LIVING_THINGS", "topic": "peppered moth example", "grades": [9, 10], "terms": ["peppered moth", "gamu-gamo", "anunugba", "alibangbang sa gabii", "kulay ng pakpak", "kolor sa pako", "maitim", "itom", "maputi", "puti", "camouflage", "pagtatago", "pagtago", "industriya", "uling", "aso", "nakaligtas sa ibon", "natural selection", "kapaligiran", "palibot"], "fact": {"tl": "Noong umitim ang mga puno dahil sa usok ng industriya sa England, ang mga maitim na peppered moth ay mas natatago sa mga ibon kaya dumami sila kaysa sa mga maputing moth — isang dokumentadong halimbawa ng natural selection.", "en": "When tree bark darkened from industrial soot in England, dark peppered moths were better hidden from birds and increased compared with light moths — a well-documented example of natural selection.", "bis": "Sa dihang miitom ang mga punoan tungod sa aso sa industriya sa England, ang itom nga mga peppered moth mas natago sa mga langgam mao nga midaghan sila kaysa sa puti nga mga moth — usa ka dokumentado nga pananglitan sa natural selection."}, "source": "Encyclopedia consensus (industrial melanism)", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-speciation-g10", "domain": "LIVING_THINGS", "topic": "how new species form", "grades": [9, 10], "terms": ["speciation", "pagbuo ng bagong species", "paghimo og bag-ong species", "bagong species", "bag-ong species", "nahiwalay", "nabukod", "geographically isolated", "magkahiwalay na populasyon", "nagkalainlain", "nagkalahi", "hindi na magkasalo sa pag-anak", "dili na makaparami", "interbreed", "natural selection", "isla", "bundok"], "fact": {"tl": "Nabubuo ang bagong species kapag ang mga pangkat ng iisang populasyon ay nahihiwalay (halimbawa, ng dagat o bundok) at unti-unting nagkakaiba sa loob ng maraming henerasyon hanggang hindi na sila makakapag-anak nang magkasama.", "en": "New species form when groups of one population become separated (for example, by sea or mountains) and gradually grow different over many generations until they can no longer interbreed.", "bis": "Ang bag-ong species mabuo kon ang mga grupo sa usa ka populasyon mabulag (pananglitan, sa dagat o bukid) ug hinay-hinay nga magkalahi sulod sa daghang henerasyon hangtod nga dili na sila makaparami nga magkauban."}, "source": "AAAS BSL 5F/H10; encyclopedia consensus (speciation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-extinction-g9", "domain": "LIVING_THINGS", "topic": "extinction and the environment", "grades": [7, 8, 9], "terms": ["extinction", "pagkalipol", "pagkapuo", "naglaho", "nawagtang", "namatay lahat", "nangamatay tanan", "wala na", "species", "nagbago ang kapaligiran", "nag-usab ang palibot", "walang katangian para mabuhay", "walay kinaiya para mabuhi", "karamihan ng species", "kadaghanan sa species", "dinosaur", "fossil"], "fact": {"tl": "Karamihan ng mga species na nabuhay na sa Earth ay lipol na; nangyayari ang pagkalipol kapag nagbago ang kapaligiran at ang mga indibidwal ng species na iyon ay walang mga katangiang kailangan para mabuhay at magparami doon.", "en": "Most species that have ever lived on Earth are now extinct; extinction happens when the environment changes and the individuals of a species lack the traits needed to survive and reproduce there.", "bis": "Kadaghanan sa mga species nga nabuhi na sa Yuta napuo na; mahitabo ang pagkapuo kon mabag-o ang palibot ug ang mga indibidwal sa maong species walay mga kinaiya nga gikinahanglan aron mabuhi ug manganak didto."}, "source": "AAAS BSL 5F/M4", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-molecular-dna-evidence-g10", "domain": "LIVING_THINGS", "topic": "molecular and DNA evidence", "grades": [9, 10], "terms": ["molecular evidence", "molekular na ebidensya", "molekular nga ebidensiya", "DNA", "genetic code", "kodigo ng buhay", "magkahawig na DNA", "susama nga DNA", "magkalapit na species", "duol nga species", "ebolusyon", "ebidensya", "pamatuod", "sequence", "pagkakasunud-sunod", "common ancestor", "ninuno", "katigulangan"], "fact": {"tl": "Ang molekular na ebidensya — gaya ng pagkakahawig ng DNA ng iba't ibang organismo — ay sumusuporta sa ebidensya mula sa anatomiya: mas magkahawig ang DNA ng mga species na malapit ang ugnayan, na nagpapakita kung paano nagsanga-sanga ang buhay mula sa iisang ninuno.", "en": "Molecular evidence — such as how similar the DNA of different organisms is — supports the anatomical evidence: more closely related species have more similar DNA, showing how life branched from common ancestors.", "bis": "Ang molekular nga ebidensiya — sama sa pagkasusama sa DNA sa lainlaing organismo — nagsuporta sa ebidensiya gikan sa anatomiya: mas susama ang DNA sa mga species nga duol ang kalabotan, nga nagpakita kon giunsa pagsanga sa kinabuhi gikan sa usa ka katigulangan."}, "source": "AAAS BSL 5F/H2", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-selective-breeding-g9", "domain": "LIVING_THINGS", "topic": "artificial selection vs natural selection", "grades": [8, 9, 10], "terms": ["selective breeding", "artificial selection", "piling pagpaparami", "pinili nga pagpaparami", "pagpili sa tawo", "alagang hayop", "binhi", "lahi ng aso", "lahi sa iro", "pananim", "tanom", "darwin", "pinili ng tao", "gipili sa tawo", "natural selection", "henerasyon"], "fact": {"tl": "Sa selective breeding (artificial selection), ang tao ang pumipili kung aling hayop o halaman ang pagpaparamihin para mapalakas ang gustong katangian; napansin ni Darwin na kung magagawa ito ng tao, ang kalikasan din ay maaaring pumili — ito ang natural selection.", "en": "In selective breeding (artificial selection), people choose which animals or plants reproduce to strengthen a desired trait; Darwin saw that if people can do this, nature can also select — that is natural selection.", "bis": "Sa selective breeding (artificial selection), ang tawo ang nagpili kon unsang hayop o tanom ang ipaparami aron palig-onon ang gusto nga kinaiya; namatikdan ni Darwin nga kon mabuhat kini sa tawo, ang kinaiyahan usab makapili — kini mao ang natural selection."}, "source": "AAAS BSL 5F/M1; Ch.5F (Darwin, artificial selection)", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-accumulated-differences-g9", "domain": "LIVING_THINGS", "topic": "small differences accumulate", "grades": [8, 9], "terms": ["accumulate", "naiipon", "natipon", "naipon", "small differences", "maliliit na pagkakaiba", "gagmayng kalainan", "magulang at anak", "ginikanan ug anak", "successive generations", "sunud-sunod na henerasyon", "sunod-sunod nga kaliwatan", "descendants", "inapo", "kaliwat", "iba na sa ninuno", "lahi na sa katigulangan", "selection"], "fact": {"tl": "Ang maliliit na pagkakaiba sa pagitan ng magulang at anak ay maaaring maipon sa sunud-sunod na henerasyon, kaya ang malalayong inapo ay maaaring maging ibang-iba na sa kanilang sinaunang ninuno.", "en": "Small differences between parents and offspring can accumulate over successive generations, so distant descendants can become very different from their ancient ancestors.", "bis": "Ang gagmayng kalainan tali sa ginikanan ug anak mahimong matigom sa sunud-sunod nga henerasyon, mao nga ang layo nga mga kaliwat mahimong lahi na kaayo sa ilang karaang katigulangan."}, "source": "AAAS BSL 5F/M1", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-fact-vs-mechanism-g10", "domain": "LIVING_THINGS", "topic": "evolution as fact vs natural selection as mechanism", "grades": [9, 10], "terms": ["evolution", "ebolusyon", "natural selection", "mekanismo", "mechanism", "patunay", "pamatuod", "tinatanggap na agham", "gidawat sa siyensya", "teorya", "teoriya", "paliwanag", "paghubad", "paano nangyari", "giunsa nahitabo", "darwin", "siyentipiko", "siyentista"], "fact": {"tl": "Ang ebolusyon mismo — ang pagbabago ng mga anyo ng buhay sa panahon — ay tinatanggap na ng mga siyentipiko bilang patunay na pangyayari, samantalang ang natural selection ang siyentipikong paliwanag (mekanismo) kung paano ito nangyayari.", "en": "Evolution itself — the change in life forms over time — is accepted by scientists as a well-substantiated occurrence, while natural selection is the scientific explanation (mechanism) for how it happens.", "bis": "Ang ebolusyon mismo — ang pagbag-o sa mga klase sa buhi paglabay sa panahon — gidawat na sa mga siyentista isip pamatuod nga panghitabo, samtang ang natural selection mao ang siyentipikong paghubad (mekanismo) kon giunsa kini mahitabo."}, "source": "AAAS BSL Ch.5F (evolution vs natural selection distinction)", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-chance-neutral-traits-g10", "domain": "LIVING_THINGS", "topic": "chance and neutral traits", "grades": [9, 10], "terms": ["chance", "tsamba", "swerte", "pagkakataon", "higayon", "neutral trait", "walang bentahe o disbentahe", "walay bentaha o disbentaha", "hindi lahat", "dili tanan", "natural selection lang", "random", "nagkataon", "naipasa", "napasa", "katangian", "kinaiya", "populasyon"], "fact": {"tl": "Hindi lahat ng katangian ay bunga ng natural selection; minsan, dahil lang sa tsamba (pagkakataon), nananatili sa populasyon ang ilang namamanang katangiang walang bentahe o disbentahe sa pananatiling buhay.", "en": "Not every trait is the result of natural selection; sometimes, purely by chance, some inherited traits that give no survival advantage or disadvantage persist in a population.", "bis": "Dili tanan nga kinaiya bunga sa natural selection; usahay, tungod lang sa higayon (chance), magpabilin sa populasyon ang pipila ka napanunod nga kinaiya nga walay bentaha o disbentaha sa pagkabuhi."}, "source": "AAAS BSL 5F/H6b", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-no-fixed-direction-g10", "domain": "LIVING_THINGS", "topic": "evolution has no fixed goal", "grades": [9, 10], "terms": ["evolution", "ebolusyon", "walang itinatakdang direksyon", "walay tinakdang direksyon", "hindi pasulong", "dili pauswag", "hindi laging mas komplikado", "dili kanunay mas komplikado", "branching", "pagsasanga", "pagsanga", "palumpong", "sapinit", "bush", "namatay na sanga", "namatay nga sanga", "misanay", "nagsanga", "buhay"], "fact": {"tl": "Ang ebolusyon ay walang itinatakdang direksyon o layunin; hindi ito laging patungo sa mas komplikado — para itong lumalagong palumpong kung saan may sangang nananatiling halos walang pagbabago, may namamatay, at may paulit-ulit na nagsasanga.", "en": "Evolution has no fixed direction or goal and does not necessarily move toward greater complexity — it is like a growing bush where some branches persist almost unchanged, many die out, and others branch again and again.", "bis": "Ang ebolusyon walay tinakdang direksyon o tumong ug dili kinahanglan nga mopaingon sa mas komplikado — sama kini sa nagtubo nga sapinit diin ang pipila ka sanga magpabilin nga halos walay kausaban, daghan ang mamatay, ug ang uban magsanga balik-balik."}, "source": "AAAS BSL 5F/H9", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-origin-of-cells-g10", "domain": "LIVING_THINGS", "topic": "early history of life", "grades": [9, 10], "terms": ["origin of life", "pinagmulan ng buhay", "gigikanan sa kinabuhi", "isang selula", "usa ka selula", "single-celled", "simpleng organismo", "yano nga organismo", "apat na bilyong taon", "upat ka bilyon ka tuig", "billion years", "nucleus", "selula nga adunay nucleus", "multicellular", "maraming selula", "daghang selula", "evolved", "nag-evolve"], "fact": {"tl": "Pinaniniwalaan ng agham na nagsimula ang buhay sa Earth bilang simpleng isang-selulang organismo mga apat na bilyong taon na ang nakalipas; nang lumitaw ang mga selulang may nucleus, unti-unting nabuo ang mas komplikadong organismong maraming selula.", "en": "Science holds that life on Earth began as simple, one-celled organisms about four billion years ago; once cells with nuclei appeared, increasingly complex multicellular organisms evolved.", "bis": "Gituohan sa siyensya nga ang kinabuhi sa Yuta nagsugod isip yano, usa-ka-selula nga organismo mga upat ka bilyon ka tuig kanhi; sa dihang mitungha ang mga selula nga adunay nucleus, hinay-hinay nga nabuo ang mas komplikado nga daghan-og-selula nga organismo."}, "source": "AAAS BSL 5F/H8", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-transitional-fossils-g10", "domain": "LIVING_THINGS", "topic": "transitional fossils", "grades": [9, 10], "terms": ["transitional fossil", "fosil na tulay", "fosil nga taytayan", "transitional", "halong katangian", "sagol nga kinaiya", "dalawang grupo", "duha ka grupo", "archaeopteryx", "dinosaur at ibon", "dinosaur ug langgam", "isda at hayop sa lupa", "isda ug hayop sa yuta", "ebidensya", "pamatuod", "pagbabagong-anyo", "pag-usab", "evidence"], "fact": {"tl": "Ang mga transitional fossil ay mga fosil na may halong katangian ng dalawang grupo ng buhay — gaya ng Archaeopteryx na may pakpak at balahibo ng ibon ngunit mga ngipin at buntot ng dinosaur — na nagpapakita ng pagbabago ng isang grupo tungo sa iba.", "en": "Transitional fossils show a mix of traits from two groups of life — like Archaeopteryx with a bird's wings and feathers but a dinosaur's teeth and tail — showing the change from one group to another.", "bis": "Ang mga transitional fossil mao ang mga fosil nga adunay sagol nga kinaiya sa duha ka grupo sa buhi — sama sa Archaeopteryx nga adunay pako ug balhibo sa langgam apan ngipon ug ikog sa dinosaur — nga nagpakita sa pagbag-o sa usa ka grupo ngadto sa lain."}, "source": "Encyclopedia consensus (transitional fossils, Archaeopteryx)", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-overproduction-struggle-g10", "domain": "LIVING_THINGS", "topic": "overproduction and struggle for survival", "grades": [9, 10], "terms": ["overproduction", "sobrang dami ng anak", "sobra nga anak", "more offspring", "limitadong pagkain", "limitado nga pagkaon", "limitadong tirahan", "limitado nga puy-anan", "struggle", "labanan", "kompetisyon", "kompetensya", "hindi lahat nabubuhay", "dili tanan mabuhi", "natural selection", "darwin", "populasyon", "predators"], "fact": {"tl": "Karamihan ng mga species ay nanganganak ng mas maraming supling kaysa sa kayang buhayin ng limitadong pagkain at tirahan, kaya may kompetisyon para mabuhay — at ang mga may-bentaheng katangian ang mas madalas na nananatili.", "en": "Most species produce more offspring than the limited food and space can support, so there is competition to survive — and those with advantageous traits more often persist.", "bis": "Kadaghanan sa mga species manganak og mas daghang anak kaysa makaya sa limitado nga pagkaon ug puy-anan, mao nga adunay kompetensya aron mabuhi — ug kadtong adunay mapuslanon nga kinaiya mas kanunay nga magpabilin."}, "source": "Encyclopedia consensus (Darwin, struggle for existence); AAAS BSL Ch.5F", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-isotopic-dating-fossils-g10", "domain": "LIVING_THINGS", "topic": "dating the age of fossils", "grades": [9, 10], "terms": ["isotopic dating", "radiometric dating", "edad ng fosil", "edad sa fosil", "aktwal na edad", "tinuod nga edad", "radioactive", "radyoaktibo", "atomo", "atom", "milyon-milyong taon", "milyon ka tuig", "sapat na panahon", "igong panahon", "natipon", "natigom", "rock layers", "patong ng bato"], "fact": {"tl": "Sa pamamagitan ng isotopic (radioactive) dating, natutukoy ng mga siyentipiko ang aktwal na edad ng mga fosil at bato sa milyon-milyong taon, na nagpapatunay na sapat na ang panahong lumipas para maipon ang sunud-sunod na pagbabago sa buhay.", "en": "Through isotopic (radioactive) dating, scientists determine the actual age of fossils and rocks in millions of years, confirming that enough time has passed for successive changes in life to accumulate.", "bis": "Pinaagi sa isotopic (radioactive) dating, matino sa mga siyentista ang tinuod nga edad sa mga fosil ug bato sa milyon-milyon ka tuig, nga nagpamatuod nga igo na ang panahon nga milabay aron matigom ang sunud-sunod nga pagbag-o sa kinabuhi."}, "source": "AAAS BSL Ch.5F (isotopic dating, grades 9-12)", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-camouflage-mimicry-g9", "domain": "LIVING_THINGS", "topic": "camouflage and mimicry as adaptations", "grades": [8, 9], "terms": ["camouflage", "kamuplahe", "pagtatago", "pagtago", "mimicry", "panggagaya", "panghuwad", "panggaya", "kulay na tumutugma", "kolor nga mohaom", "nakatakas sa kalaban", "nakaikyas sa kaaway", "natural selection", "adaptasyon", "adaptation", "predator", "stick insect", "kapaligiran"], "fact": {"tl": "Ang camouflage (pagtugma ng kulay o hugis sa kapaligiran) at mimicry (panggagaya sa mas mapanganib na hayop) ay mga adaptasyong nabuo sa pamamagitan ng natural selection dahil tumutulong silang makatakas sa mga mandaragit.", "en": "Camouflage (matching the color or shape of the surroundings) and mimicry (resembling a more dangerous animal) are adaptations shaped by natural selection because they help an organism escape predators.", "bis": "Ang camouflage (pagtakdo sa kolor o porma sa palibot) ug mimicry (pagsundog sa mas peligroso nga hayop) maoy mga adaptasyon nga nabuo pinaagi sa natural selection tungod kay sila motabang sa organismo nga makaikyas sa mga manunukob."}, "source": "Encyclopedia consensus; AAAS BSL 5F/H6a", "generator": "claude-workflow", "reviewed": false},
  {"id": "evolution-coevolution-pollinators-g10", "domain": "LIVING_THINGS", "topic": "coevolution", "grades": [9, 10], "terms": ["coevolution", "magkasabay na ebolusyon", "dungan nga ebolusyon", "bulaklak at insekto", "bulak ug insekto", "pollinator", "polinador", "bubuyog", "putyukan", "paniki", "kabog", "magkaakma", "magkahaom", "nag-impluwensiya sa isa't isa", "nag-impluwensya sa usag usa", "natural selection", "adaptation", "nektar"], "fact": {"tl": "Sa coevolution, dalawang species ang magkasabay na nagbabago dahil nakakaapekto sila sa isa't isa — gaya ng bulaklak at ng polinador nitong bubuyog o paniki na unti-unting nagiging akma sa hugis ng isa't isa.", "en": "In coevolution, two species evolve together because they affect each other — like a flower and its pollinator (a bee or bat) that gradually become matched to each other's form.", "bis": "Sa coevolution, duha ka species ang dungan nga mausab tungod kay sila magkaapekto sa usag usa — sama sa bulak ug sa polinador niini nga putyukan o kabog nga hinay-hinay nga mahimong haom sa porma sa usag usa."}, "source": "Encyclopedia consensus (coevolution)", "generator": "claude-workflow", "reviewed": false},
  {"id": "homeostasis-stable-internal-conditions-g9", "domain": "LIVING_THINGS", "topic": "homeostasis keeps internal conditions within a narrow range", "grades": [8, 9, 10], "terms": ["homeostasis", "balanse ng katawan sa loob", "stable internal conditions", "panatag na panloob", "balanse sa sulod sa lawas", "lig-on nga kahimtang sulod", "internal environment", "kapaligiran sa loob", "regulation", "regulasyon", "narrow range", "makitid na saklaw", "limitadong range"], "fact": {"tl": "Ang homeostasis ay ang patuloy na pagpapanatili ng katawan ng matatag na panloob na kalagayan—temperatura, asukal sa dugo, tubig—sa loob ng makitid na saklaw, kahit nagbabago ang labas.", "en": "Homeostasis is the body's constant keeping of stable internal conditions—temperature, blood sugar, water—within a narrow range, even as the outside changes.", "bis": "Ang homeostasis mao ang padayon nga pagmintinar sa lawas sa lig-on nga kahimtang sulod—temperatura, asukal sa dugo, tubig—sulod sa pig-ot nga han-ay, bisan magbag-o ang gawas."}, "source": "NRC LS1.A (Ch.10); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "negative-feedback-corrects-change-g9", "domain": "LIVING_THINGS", "topic": "negative feedback reverses a change to restore balance", "grades": [8, 9, 10], "terms": ["negative feedback", "negatibong feedback", "feedback loop", "tumbalik na pagtugon", "balik sa balanse", "pagbawi sa balanse", "babago paibabaw babalik pababa", "self-correcting", "kusang nagwawasto", "kaugalingong pagtul-id", "reverse the change", "binabaligtad ang pagbabago"], "fact": {"tl": "Sa negative feedback, kapag lumihis ang isang bagay sa normal, naglalabas ang katawan ng tugon na binabaligtad ang pagbabago at ibinabalik ito sa balanse.", "en": "In negative feedback, when something drifts from normal the body produces a response that reverses the change and returns it toward balance.", "bis": "Sa negative feedback, kung mosimang ang usa ka butang gikan sa normal, mohatag ang lawas og tubag nga mobalik sa kausaban ug mopabalik niini sa balanse."}, "source": "NRC 'Stability and Change' (Ch.8) + LS1.A (Ch.10)", "generator": "claude-workflow", "reviewed": false},
  {"id": "set-point-target-value-g9", "domain": "LIVING_THINGS", "topic": "the body regulates around a set point", "grades": [8, 9, 10], "terms": ["set point", "set point ng katawan", "target value", "tamang antas", "normal na antas", "sukdanan", "puntong target", "ang normal nga lebel", "37 degrees", "37 digri", "thermostat", "termostat"], "fact": {"tl": "May 'set point' o normal na antas ang katawan—gaya ng mga 37°C na temperatura—na pinipilit nitong panatilihin, tulad ng thermostat na gumagana sa isang bahay.", "en": "The body has a 'set point' or normal value—such as about 37°C body temperature—that it works to hold, much like a thermostat in a house.", "bis": "Aduna'y 'set point' o normal nga lebel ang lawas—sama sa mga 37°C nga temperatura—nga gipaningkamotan niini nga huptan, sama sa thermostat sa usa ka balay."}, "source": "NRC 'Stability and Change' (Ch.8, thermostat analogy); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hypothalamus-control-center-g10", "domain": "LIVING_THINGS", "topic": "the hypothalamus in the brain is a main homeostatic control center", "grades": [9, 10], "terms": ["hypothalamus", "hypothalamus sa utak", "control center", "sentro ng kontrol", "sentro sa pagdumala", "utak", "utok", "brain", "nagmomonitor", "nagbabantay sa temperatura", "nagsubay sa temperatura", "tagapamahala ng balanse"], "fact": {"tl": "Ang hypothalamus, isang maliit na bahagi ng utak, ang nagbabantay sa temperatura, tubig, at iba pang antas, at nag-uutos ng tamang tugon para mapanatili ang balanse.", "en": "The hypothalamus, a small part of the brain, monitors temperature, water, and other levels and orders the right responses to keep balance.", "bis": "Ang hypothalamus, usa ka gamay nga bahin sa utok, mao ang nagbantay sa temperatura, tubig, ug uban pang lebel, ug nagmando sa hustong tubag aron mahuptan ang balanse."}, "source": "Encyclopedia-stable consensus; NRC LS1.A regulatory mechanisms", "generator": "claude-workflow", "reviewed": false},
  {"id": "thermoregulation-cooling-sweat-g8", "domain": "LIVING_THINGS", "topic": "the body cools itself by sweating and widening skin blood vessels", "grades": [7, 8, 9], "terms": ["pagpapawis", "pawis", "singot", "pagsingot", "sweating", "cooling down", "pagpapalamig ng katawan", "pagpabugnaw sa lawas", "thermoregulation", "lumalapad na ugat sa balat", "namula ang balat", "evaporation", "pagsingaw ng pawis", "init", "kainit"], "fact": {"tl": "Kapag mainit, pinapawisan ang katawan at lumalapad ang mga ugat sa balat para palabasin ang init at ibaba ang temperatura.", "en": "When it is hot, the body sweats and the blood vessels in the skin widen to release heat and lower temperature.", "bis": "Kung init, mosingot ang lawas ug molapad ang mga ugat sa panit aron mogawas ang kainit ug moubos ang temperatura."}, "source": "Encyclopedia-stable consensus; NRC LS1.A feedback mechanisms", "generator": "claude-workflow", "reviewed": false},
  {"id": "thermoregulation-warming-shiver-g8", "domain": "LIVING_THINGS", "topic": "the body warms itself by shivering and narrowing skin blood vessels", "grades": [7, 8, 9], "terms": ["panginginig", "nginig", "pagkurog", "kurog", "shivering", "lamig", "kalamig", "katugnaw", "tugnaw", "pag-init ng katawan", "pagpainit sa lawas", "kumikitid na ugat", "mihugot nga ugat", "goosebumps", "kilabot", "naninindig ang balahibo"], "fact": {"tl": "Kapag malamig, nanginginig ang kalamnan at kumikitid ang mga ugat sa balat para gumawa at hindi mawala ang init ng katawan.", "en": "When it is cold, the muscles shiver and the skin's blood vessels narrow to make heat and keep the body from losing it.", "bis": "Kung tugnaw, mokurog ang kaunoran ug mohugot ang mga ugat sa panit aron makahimo og kainit ug dili mawala ang init sa lawas."}, "source": "Encyclopedia-stable consensus; NRC LS1.A feedback mechanisms", "generator": "claude-workflow", "reviewed": false},
  {"id": "hormones-chemical-messengers-g9", "domain": "LIVING_THINGS", "topic": "hormones are chemical messengers carried by the blood", "grades": [8, 9, 10], "terms": ["hormone", "mga hormone", "hormona", "chemical messenger", "kemikal na mensahero", "kemikal nga mensahero", "tagadala ng mensahe", "dala sa dugo", "carried by blood", "dugo", "endocrine", "mabagal pero malayo ang abot", "slow signal", "target organ", "tagong glandula"], "fact": {"tl": "Ang mga hormone ay mga kemikal na mensahero na inilalabas ng mga glandula at dinadala ng dugo para mag-utos sa malalayong bahagi ng katawan.", "en": "Hormones are chemical messengers released by glands and carried by the blood to give instructions to distant parts of the body.", "bis": "Ang mga hormone mao ang kemikal nga mensahero nga gibuga sa mga glandula ug gidala sa dugo aron mohatag og mando sa layo nga mga bahin sa lawas."}, "source": "Encyclopedia-stable consensus; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "endocrine-system-glands-network-g9", "domain": "LIVING_THINGS", "topic": "the endocrine system is a network of hormone-making glands", "grades": [8, 9, 10], "terms": ["endocrine system", "endocrine", "sistema ng glandula", "mga glandula", "glandula", "kana nga mga glandula", "hormone-making", "gumagawa ng hormone", "naghimo og hormone", "pituitary", "thyroid", "adrenal", "pancreas", "network ng katawan", "tagong glandula", "ductless gland"], "fact": {"tl": "Ang endocrine system ay ang grupo ng mga glandula—gaya ng pituitary, thyroid, adrenal, at pancreas—na gumagawa ng mga hormone na nagkokontrol sa katawan.", "en": "The endocrine system is the group of glands—such as the pituitary, thyroid, adrenal, and pancreas—that make the hormones controlling the body.", "bis": "Ang endocrine system mao ang grupo sa mga glandula—sama sa pituitary, thyroid, adrenal, ug pancreas—nga naghimo sa mga hormone nga nagdumala sa lawas."}, "source": "Encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pituitary-master-gland-g10", "domain": "LIVING_THINGS", "topic": "the pituitary gland directs other glands", "grades": [9, 10], "terms": ["pituitary", "pituitary gland", "master gland", "punong glandula", "pangulong glandula", "agalon nga glandula", "namamahala sa ibang glandula", "nagdumala sa ubang glandula", "ilalim ng utak", "ubos sa utok", "tumutulong sa paglaki", "growth"], "fact": {"tl": "Ang pituitary gland sa ilalim ng utak ang tinaguriang 'master gland' dahil ang mga hormone nito ang nag-uutos sa ibang glandula kung ano ang gagawin.", "en": "The pituitary gland beneath the brain is called the 'master gland' because its hormones tell the other glands what to do.", "bis": "Ang pituitary gland ubos sa utok ang gitawag nga 'master gland' kay ang mga hormone niini maoy nagmando sa ubang glandula kung unsa ang buhaton."}, "source": "Encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pancreas-insulin-lowers-blood-sugar-g10", "domain": "LIVING_THINGS", "topic": "insulin from the pancreas lowers blood sugar", "grades": [9, 10], "terms": ["insulin", "asukal sa dugo", "blood sugar", "glucose", "glukosa", "pancreas", "lapay", "pankreyas", "ibinababa ang asukal", "pagpaubos sa asukal", "pagkain ng matamis", "human kumaon", "stores sugar", "iniimbak na asukal", "high blood sugar", "mataas na asukal"], "fact": {"tl": "Pagkatapos kumain, kapag mataas ang asukal sa dugo, naglalabas ang pancreas ng insulin na tumutulong sa mga cell na sumipsip ng asukal para bumaba ito.", "en": "After eating, when blood sugar is high, the pancreas releases insulin that helps cells take in sugar so the level drops.", "bis": "Human mokaon, kung taas ang asukal sa dugo, mobuga ang pancreas og insulin nga motabang sa mga cell sa pagsuyop sa asukal aron moubos kini."}, "source": "Encyclopedia-stable consensus; NRC LS1.A feedback example", "generator": "claude-workflow", "reviewed": false},
  {"id": "pancreas-glucagon-raises-blood-sugar-g10", "domain": "LIVING_THINGS", "topic": "glucagon from the pancreas raises blood sugar", "grades": [9, 10], "terms": ["glucagon", "asukal sa dugo", "blood sugar", "glucose", "glukosa", "pancreas", "lapay", "pankreyas", "itinataas ang asukal", "pagpataas sa asukal", "gutom", "gigutom", "low blood sugar", "mababang asukal", "atay", "liver", "naimbak na asukal"], "fact": {"tl": "Kapag mababa ang asukal sa dugo, gaya ng nagugutom, naglalabas ang pancreas ng glucagon na nag-uutos sa atay na maglabas ng naimbak na asukal.", "en": "When blood sugar is low, such as when hungry, the pancreas releases glucagon that tells the liver to release stored sugar.", "bis": "Kung ubos ang asukal sa dugo, sama sa gigutom, mobuga ang pancreas og glucagon nga nagmando sa atay nga mobuga sa tinago nga asukal."}, "source": "Encyclopedia-stable consensus; NRC LS1.A feedback example", "generator": "claude-workflow", "reviewed": false},
  {"id": "insulin-glucagon-opposite-pair-g10", "domain": "LIVING_THINGS", "topic": "insulin and glucagon work as an opposing pair to balance blood sugar", "grades": [9, 10], "terms": ["insulin at glucagon", "magkasalungat na hormone", "magkasumpaki nga hormone", "opposing pair", "magkabaligtad", "balanse ng asukal", "balanse sa asukal", "blood sugar balance", "steady sugar", "patuloy na nagbabalanse", "antagonistic", "isang pataas isang pababa"], "fact": {"tl": "Ang insulin at glucagon ay magkasalungat: isa ang nagpapababa at isa ang nagpapataas ng asukal sa dugo, kaya nananatili itong balanse.", "en": "Insulin and glucagon are opposites: one lowers and one raises blood sugar, so the level stays balanced.", "bis": "Ang insulin ug glucagon magkasumpaki: usa ang moubos ug usa ang motaas sa asukal sa dugo, mao nga magpabilin kining balanse."}, "source": "Encyclopedia-stable consensus; NRC LS1.A negative feedback", "generator": "claude-workflow", "reviewed": false},
  {"id": "kidneys-water-balance-g9", "domain": "LIVING_THINGS", "topic": "the kidneys control the body's water balance", "grades": [8, 9, 10], "terms": ["bato", "kidney", "kidneys", "mga bato", "kidni", "balanse ng tubig", "balanse sa tubig", "water balance", "ihi", "umihi", "urine", "pagpapakaunti ng ihi", "concentrated urine", "dami ng tubig sa katawan", "pagsala sa dugo", "filter"], "fact": {"tl": "Ang mga bato ang nagkokontrol ng dami ng tubig sa katawan—kung kulang ang tubig, gumagawa ito ng mas kaunti at mas konsentradong ihi.", "en": "The kidneys control how much water is in the body—when water is short, they make less and more concentrated urine.", "bis": "Ang mga kidney maoy nagdumala sa kadaghan sa tubig sa lawas—kung kulang ang tubig, mohimo kini og mas gamay ug mas konsentrado nga ihi."}, "source": "Encyclopedia-stable consensus; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "adh-thirst-water-conservation-g10", "domain": "LIVING_THINGS", "topic": "ADH and thirst help the body conserve water", "grades": [9, 10], "terms": ["ADH", "antidiuretic hormone", "hormone ng tubig", "pagkauhaw", "uhaw", "kauhaw", "giuhaw", "thirst", "pag-iimbak ng tubig", "pagtipig sa tubig", "conserve water", "dehydration", "pagkawala ng tubig", "kakulangan sa tubig", "pituitary", "kaunting ihi"], "fact": {"tl": "Kapag kulang sa tubig, naglalabas ang katawan ng hormone na ADH para hindi masyadong mawala ang tubig sa ihi, at nararamdaman ang pagkauhaw para uminom.", "en": "When water is short, the body releases the hormone ADH so less water is lost in urine, and it makes you feel thirsty so you drink.", "bis": "Kung kulang sa tubig, mobuga ang lawas og hormone nga ADH aron dili kaayo mawala ang tubig sa ihi, ug mobati og kauhaw aron moinom."}, "source": "Encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "adrenaline-fight-or-flight-g10", "domain": "LIVING_THINGS", "topic": "adrenaline prepares the body for fight or flight", "grades": [9, 10], "terms": ["adrenaline", "adrenalin", "epinephrine", "takot", "kaba", "kahadlok", "kulba", "fear", "fight or flight", "lakas ng loob", "mabilis na tibok ng puso", "kusog ang pitik sa kasingkasing", "adrenal gland", "stress", "delubyo", "biglang lakas"], "fact": {"tl": "Kapag natatakot o nasa panganib, naglalabas ang adrenal gland ng adrenaline na nagpapabilis ng tibok ng puso at hininga para maging handa ang katawan.", "en": "When afraid or in danger, the adrenal gland releases adrenaline that speeds up the heartbeat and breathing to ready the body for action.", "bis": "Kung mahadlok o anaa sa kakuyaw, mobuga ang adrenal gland og adrenaline nga mopaspas sa pitik sa kasingkasing ug ginhawa aron maandam ang lawas."}, "source": "Encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "thyroid-controls-metabolism-g10", "domain": "LIVING_THINGS", "topic": "the thyroid gland controls the body's metabolism", "grades": [9, 10], "terms": ["thyroid", "thyroid gland", "glandula sa leeg", "glandula sa liog", "metabolism", "metabolismo", "bilis ng paggamit ng enerhiya", "kakusog sa paggamit og enerhiya", "iodine", "yodo", "thyroxine", "init at enerhiya ng katawan", "energy use", "leeg", "liog"], "fact": {"tl": "Ang thyroid gland sa leeg ang nagkokontrol ng metabolism—kung gaano kabilis gumamit ng enerhiya at gumawa ng init ang katawan.", "en": "The thyroid gland in the neck controls metabolism—how fast the body uses energy and makes heat.", "bis": "Ang thyroid gland sa liog maoy nagdumala sa metabolism—kung unsa ka paspas mogamit og enerhiya ug mohimo og kainit ang lawas."}, "source": "Encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "growth-hormone-childhood-growth-g9", "domain": "LIVING_THINGS", "topic": "growth hormone helps children grow taller", "grades": [8, 9, 10], "terms": ["growth hormone", "hormone ng paglaki", "hormone sa pagtubo", "pagtaas", "pagtas-on", "paglaki", "pagtubo", "lumalaki ang bata", "buto", "bukog", "bones", "pituitary", "matangkad", "tag-as", "tulog at paglaki"], "fact": {"tl": "Ang growth hormone na galing sa pituitary gland ang tumutulong sa mga bata na lumaki at tumangkad sa pamamagitan ng paglago ng buto at kalamnan.", "en": "Growth hormone from the pituitary gland helps children grow taller by building up bones and muscles.", "bis": "Ang growth hormone gikan sa pituitary gland maoy motabang sa mga bata nga motubo ug motaas pinaagi sa pagpalig-on sa bukog ug kaunoran."}, "source": "Encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "nervous-vs-hormone-speed-g10", "domain": "LIVING_THINGS", "topic": "nerves give fast signals while hormones give slower lasting ones", "grades": [9, 10], "terms": ["nerve at hormone", "nerbiyo", "ugat sa nerbiyo", "nervous system", "sistema sa nerbiyo", "mabilis na senyas", "paspas nga senyas", "fast signal", "mabagal pero matagal", "hinay pero dugay", "slow lasting", "electrical signal", "kuryente sa nerbiyo", "kemikal sa dugo", "dalawang paraan ng kontrol"], "fact": {"tl": "Ang katawan ay kinokontrol sa dalawang paraan: ang nerbiyo na nagbibigay ng mabilis na senyas, at ang hormone na mas mabagal pero mas matagal ang epekto.", "en": "The body is controlled two ways: nerves give fast signals, while hormones act more slowly but last longer.", "bis": "Ang lawas gidumala sa duha ka paagi: ang nerbiyo nga mohatag og paspas nga senyas, ug ang hormone nga mas hinay apan mas dugay ang epekto."}, "source": "Encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fever-immune-response-g8", "domain": "LIVING_THINGS", "topic": "a fever is the body raising its set point to fight germs", "grades": [7, 8, 9], "terms": ["lagnat", "lalagnatin", "fever", "hilanat", "gihilantan", "init ng katawan", "kainit sa lawas", "raised set point", "pagtaas ng set point", "labanan ang mikrobyo", "pakigbatok sa mikrobyo", "fight germs", "immune", "sakit", "impeksyon", "infection"], "fact": {"tl": "Ang lagnat ay sadyang pagtataas ng katawan ng set point nito para mas mahirapan ang mga mikrobyo at matulungan ang immune system na lumaban.", "en": "A fever is the body deliberately raising its set point to make it harder for germs and to help the immune system fight.", "bis": "Ang hilanat mao ang tinuyo nga pagpataas sa lawas sa set point niini aron maglisod ang mga mikrobyo ug matabangan ang immune system sa pagpakig-away."}, "source": "Encyclopedia-stable consensus; NRC LS1.A homeostatic response", "generator": "claude-workflow", "reviewed": false},
  {"id": "homeostasis-breaks-extreme-temperature-g10", "domain": "LIVING_THINGS", "topic": "homeostasis fails at too high or too low temperatures", "grades": [9, 10], "terms": ["homeostasis breaks down", "hindi na kayang ibalanse", "dili na kaya balansehon", "sobrang init", "grabe ka init", "sobrang lamig", "grabe ka tugnaw", "heat stroke", "hypothermia", "limitadong saklaw", "limitado nga han-ay", "extreme temperature", "delikado", "peligroso", "hindi makaligtas", "dili mabuhi"], "fact": {"tl": "Gumagana lamang ang homeostasis sa loob ng limitadong saklaw; sa sobrang init o sobrang lamig, hindi na ito kayang ibalanse ng katawan at nanganganib ang buhay.", "en": "Homeostasis works only within a limited range; at too high or too low a temperature the body can no longer balance it and life is endangered.", "bis": "Ang homeostasis molihok lamang sulod sa limitado nga han-ay; sa hilabihang kainit o katugnaw dili na kini mabalanse sa lawas ug makuyaw ang kinabuhi."}, "source": "NRC Ch.9 (homeostasis breaks down at too high/low temperature)", "generator": "claude-workflow", "reviewed": false},
  {"id": "diabetes-blood-sugar-control-loss-g10", "domain": "LIVING_THINGS", "topic": "diabetes is a loss of blood sugar control", "grades": [9, 10], "terms": ["diabetes", "dyabetis", "sakit sa asukal", "mataas na asukal sa dugo", "taas nga asukal sa dugo", "high blood sugar", "kulang sa insulin", "kulang og insulin", "insulin problem", "hindi nababalanse ang asukal", "dili mabalanse ang asukal", "pancreas problem", "kondisyon", "sakit"], "fact": {"tl": "Sa diabetes, hindi sapat o hindi tama ang paggana ng insulin, kaya hindi nababalanse ang asukal sa dugo at ito ay nananatiling mataas.", "en": "In diabetes, insulin is not enough or does not work well, so blood sugar is not balanced and stays too high.", "bis": "Sa diabetes, dili igo o dili maayo molihok ang insulin, mao nga dili mabalanse ang asukal sa dugo ug magpabilin kining taas."}, "source": "Encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "goiter-iodine-deficiency-g9", "domain": "LIVING_THINGS", "topic": "goiter is an enlarged thyroid from lack of iodine", "grades": [8, 9, 10], "terms": ["goiter", "goiter sa leeg", "lumaki ang leeg", "namaga ang liog", "swollen neck", "kulang sa yodo", "kulang og iodine", "iodine deficiency", "thyroid", "asin na may yodo", "iodized salt", "asin nga adunay yodo", "kakulangan sa sustansya", "sakit sa thyroid"], "fact": {"tl": "Ang goiter ay paglaki ng thyroid gland sa leeg na kadalasang dahil sa kakulangan ng yodo, kaya iminumungkahi ang paggamit ng asing may yodo.", "en": "Goiter is a swelling of the thyroid gland in the neck, often caused by a lack of iodine, which is why iodized salt is recommended.", "bis": "Ang goiter mao ang paghubag sa thyroid gland sa liog, kasagaran tungod sa kakulang sa yodo, mao nga girekomendar ang asin nga adunay yodo."}, "source": "Encyclopedia-stable consensus; PH iodized-salt public health", "generator": "claude-workflow", "reviewed": false},
  {"id": "dehydration-water-loss-g8", "domain": "LIVING_THINGS", "topic": "dehydration is dangerous loss of body water", "grades": [7, 8, 9], "terms": ["dehydration", "pagkawala ng tubig sa katawan", "pagkawala sa tubig sa lawas", "kulang sa tubig", "kulang og tubig", "uhaw", "kauhaw", "giuhaw", "pawis at pagtatae", "singot ug kalibanga", "tuyong bibig", "uga nga baba", "dry mouth", "delikado", "uminom ng tubig", "rehydrate"], "fact": {"tl": "Ang dehydration ay sobrang pagkawala ng tubig sa katawan mula sa pawis, ihi, o pagtatae, na nakakasira sa balanse at delikado kung hindi maagapan.", "en": "Dehydration is too much loss of body water from sweat, urine, or diarrhea, which upsets balance and is dangerous if not corrected.", "bis": "Ang dehydration mao ang sobra nga pagkawala sa tubig sa lawas gikan sa singot, ihi, o kalibanga, nga makaguba sa balanse ug makuyaw kung dili matubag."}, "source": "Encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "stimulus-receptor-effector-pathway-g10", "domain": "LIVING_THINGS", "topic": "homeostasis uses receptors, a control center, and effectors", "grades": [9, 10], "terms": ["receptor", "tagatanggap", "magdawat", "stimulus", "panimuon", "pagbati", "control center", "sentro ng kontrol", "effector", "tagatugon", "tagatubag", "daloy ng feedback", "agos sa feedback", "sensor", "tatlong bahagi", "tulo ka bahin", "pathway"], "fact": {"tl": "Sa feedback, may receptor na nakakaramdam ng pagbabago, control center na nagdedesisyon, at effector gaya ng kalamnan o glandula na tumutugon.", "en": "In feedback, a receptor senses a change, a control center decides, and an effector such as a muscle or gland responds.", "bis": "Sa feedback, adunay receptor nga mobati sa kausaban, control center nga modesisyon, ug effector sama sa kaunoran o glandula nga motubag."}, "source": "Encyclopedia-stable consensus; NRC LS1.A feedback mechanism structure", "generator": "claude-workflow", "reviewed": false},
  {"id": "positive-feedback-amplifies-g10", "domain": "LIVING_THINGS", "topic": "positive feedback pushes a change further instead of reversing it", "grades": [9, 10], "terms": ["positive feedback", "positibong feedback", "pinalalakas ang pagbabago", "gipakusog ang kausaban", "amplify", "lalong tumitindi", "padayon nga modako", "panganganak", "panganak", "childbirth", "pagpapadugo ng sugat", "pamuo sa dugo", "blood clotting", "hindi balanse na uri", "iba sa negative feedback"], "fact": {"tl": "Sa positive feedback, sa halip na balansehin, mas pinalalakas pa ang pagbabago—gaya ng pamumuo ng dugo para huminto ang pagdurugo, o sa panganganak.", "en": "In positive feedback, instead of balancing, a change is pushed even further—as in blood clotting to stop bleeding, or in childbirth.", "bis": "Sa positive feedback, imbis nga balansehon, mas pakusgon pa ang kausaban—sama sa pamuo sa dugo aron mohunong ang pagdugo, o sa pagpanganak."}, "source": "NRC 'Stability and Change' (Ch.8, positive vs negative feedback)", "generator": "claude-workflow", "reviewed": false},
  {"id": "blood-co2-breathing-regulation-g10", "domain": "LIVING_THINGS", "topic": "the body regulates breathing to control carbon dioxide in the blood", "grades": [9, 10], "terms": ["carbon dioxide", "carbon dioxide sa dugo", "CO2", "paghinga", "pagginhawa", "ginhawa", "breathing rate", "bilis ng paghinga", "kapaspas sa ginhawa", "labis na CO2", "sobra nga CO2", "mabilis na hininga", "paspas nga ginhawa", "asido sa dugo", "balanse ng gas", "automatic"], "fact": {"tl": "Kapag tumaas ang carbon dioxide sa dugo, awtomatikong bumibilis ang hininga para mailabas ito at mapanatili ang tamang balanse ng gas.", "en": "When carbon dioxide in the blood rises, breathing automatically speeds up to expel it and keep the right gas balance.", "bis": "Kung motaas ang carbon dioxide sa dugo, awtomatik nga mopaspas ang ginhawa aron mapagawas kini ug mahuptan ang hustong balanse sa gas."}, "source": "Encyclopedia-stable consensus; NRC LS1.A feedback", "generator": "claude-workflow", "reviewed": false},
  {"id": "skin-organ-temperature-water-g8", "domain": "LIVING_THINGS", "topic": "the skin helps control temperature and water loss", "grades": [7, 8, 9], "terms": ["balat", "panit", "skin", "pinakamalaking organ", "labing dako nga organ", "largest organ", "pawis", "singot", "sweat gland", "glandula sa pawis", "tubig sa katawan", "tubig sa lawas", "harang sa tubig", "barrier", "init at lamig", "kainit ug katugnaw", "proteksyon"], "fact": {"tl": "Ang balat, ang pinakamalaking organ, ay tumutulong sa homeostasis sa pamamagitan ng pagpapawis para palamig at pagpigil sa labis na pagkawala ng tubig.", "en": "The skin, the largest organ, helps homeostasis by sweating to cool down and by blocking too much water loss.", "bis": "Ang panit, ang labing dako nga organ, motabang sa homeostasis pinaagi sa pagsingot aron mobugnaw ug pagpugong sa sobra nga pagkawala sa tubig."}, "source": "Encyclopedia-stable consensus; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "hormone-balance-needs-right-amount-g10", "domain": "LIVING_THINGS", "topic": "too much or too little of a hormone harms the body", "grades": [9, 10], "terms": ["tamang dami ng hormone", "husto nga gidaghanon sa hormone", "right amount", "sobra o kulang", "sobra o kulang nga hormone", "too much too little", "imbalance", "hindi balanse na hormone", "dili balanse nga hormone", "sakit sa hormone", "epekto sa katawan", "regulated", "kontrolado"], "fact": {"tl": "Kailangang tama lang ang dami ng bawat hormone—kapag sobra o kulang, nagkakasakit o nagkakaproblema ang katawan.", "en": "Each hormone must be in just the right amount—too much or too little makes the body sick or out of balance.", "bis": "Kinahanglan husto lang ang gidaghanon sa matag hormone—kung sobra o kulang, magsakit o magkaproblema ang lawas."}, "source": "Encyclopedia-stable consensus; NRC LS1.A regulation within limits", "generator": "claude-workflow", "reviewed": false},
  {"id": "lactic-acid-fermentation-yogurt-g8", "domain": "LIVING_THINGS", "topic": "lactic acid fermentation in yogurt", "grades": [8, 9, 10], "terms": ["lactic acid fermentation", "lactic acid", "asido laktiko", "gatas", "milk", "yogurt", "Lactobacillus", "bakterya", "bacteria", "lactose", "lakto", "asim", "maasim", "namuo", "naga-aslom", "fermentation", "pagbuburo", "pagpapaasim", "kabag nga gatas"], "fact": {"tl": "Sa yogurt, ang mga bakteryang gaya ng Lactobacillus ay kumakain ng asukal sa gatas (lactose) at ginagawa itong lactic acid, kaya naaasim at namumuo ang gatas.", "en": "In yogurt, bacteria like Lactobacillus feed on the milk sugar (lactose) and turn it into lactic acid, which sours the milk and makes it thicken.", "bis": "Sa yogurt, ang mga bakterya sama sa Lactobacillus mokaon sa kalamian sa gatas (lactose) ug himuon kining lactic acid, mao nga moaslom ug mokuyamoy ang gatas."}, "source": "NRC LS1.C; consensus food microbiology", "generator": "claude-workflow", "reviewed": false},
  {"id": "alcoholic-fermentation-anaerobic-g9", "domain": "LIVING_THINGS", "topic": "alcoholic fermentation by yeast is anaerobic", "grades": [9, 10], "terms": ["alcoholic fermentation", "fermentation", "anaerobic", "walang oxygen", "way oksiheno", "lebadura", "yeast", "Saccharomyces", "asukal", "sugar", "kalamian", "ethanol", "alkohol", "alcohol", "carbon dioxide", "CO2", "respirasyon", "respiration", "energy", "enerhiya", "pagbuburo nga way hangin"], "fact": {"tl": "Ginagawa ng lebadura ang alcoholic fermentation kapag walang sapat na oxygen: pinaghahati nito ang asukal para makakuha ng kaunting enerhiya, at ang mga tira nito ay ethanol (alkohol) at carbon dioxide.", "en": "Yeast carries out alcoholic fermentation when there is not enough oxygen: it breaks down sugar to get a little energy, leaving behind ethanol (alcohol) and carbon dioxide.", "bis": "Ang lebadura mohimo og alcoholic fermentation kon kulang ang oksiheno: bahinon niini ang kalamian aron makakuha og gamay nga enerhiya, ug ang mabilin mao ang ethanol (alkohol) ug carbon dioxide."}, "source": "NRC LS1.C; consensus biochemistry of fermentation", "generator": "claude-workflow", "reviewed": false},
  {"id": "acetobacter-vinegar-two-step-g9", "domain": "LIVING_THINGS", "topic": "vinegar is made by Acetobacter from alcohol", "grades": [9, 10], "terms": ["vinegar", "suka", "Acetobacter", "bakterya", "bacteria", "alkohol", "alcohol", "ethanol", "acetic acid", "asido asetiko", "oxygen", "oksiheno", "hangin", "asim", "maasim", "aslom", "fermentation", "pagbuburo", "dalawang hakbang"], "fact": {"tl": "Ang suka ay gawa sa dalawang hakbang: una, ginagawang alkohol ng lebadura ang asukal; pagkatapos, ginagamit ng bakteryang Acetobacter ang oxygen para gawing acetic acid ang alkohol, na siyang nagpapaasim ng suka.", "en": "Vinegar is made in two steps: first yeast turns sugar into alcohol, then Acetobacter bacteria use oxygen to turn that alcohol into acetic acid, which gives vinegar its sourness.", "bis": "Ang suka ginama sa duha ka lakang: una, himuong alkohol sa lebadura ang kalamian; dayon, ang bakteryang Acetobacter mogamit og oksiheno aron himuong acetic acid ang alkohol, nga maoy hinungdan sa kaaslom sa suka."}, "source": "Consensus food microbiology; AAAS Benchmarks Ch.8", "generator": "claude-workflow", "reviewed": false},
  {"id": "nata-de-coco-cellulose-bacteria-g9", "domain": "LIVING_THINGS", "topic": "nata de coco is bacterial cellulose", "grades": [9, 10], "terms": ["nata de coco", "nata", "coconut water", "tubig ng niyog", "tubig sa lubi", "Acetobacter xylinum", "bakterya", "bacteria", "cellulose", "selulosa", "gel", "makapal", "matigas", "katas", "fermentation", "pagbuburo", "pagkaing Pilipino", "Filipino food"], "fact": {"tl": "Ang nata de coco ay isang makapal na gel na cellulose na ginagawa ng bakteryang Acetobacter xylinum habang nagfe-ferment ito sa pinatamis na tubig ng niyog.", "en": "Nata de coco is a thick cellulose gel produced by the bacterium Acetobacter xylinum as it ferments sweetened coconut water.", "bis": "Ang nata de coco usa ka baga nga gel nga cellulose nga gibuhat sa bakteryang Acetobacter xylinum samtang mo-ferment kini sa gipatam-is nga tubig sa lubi."}, "source": "Consensus food science; Philippine traditional biotechnology", "generator": "claude-workflow", "reviewed": false},
  {"id": "patis-bagoong-proteolysis-g9", "domain": "LIVING_THINGS", "topic": "patis and bagoong from protein breakdown", "grades": [9, 10], "terms": ["patis", "fish sauce", "bagoong", "isda", "fish", "alamang", "asin", "salt", "enzymes", "enzyme", "protina", "protein", "amino acid", "amino asido", "nabubulok", "natutunaw", "fermentation", "pagbuburo", "preserba", "preservation", "lasa", "umami", "tilaw"], "fact": {"tl": "Kapag binuburo ang isda na may maraming asin, ang mga enzyme at bakterya ay unti-unting binabakbak ang protina nito sa amino acid, na nagbibigay ng malasang patis at bagoong.", "en": "When fish is fermented with plenty of salt, enzymes and bacteria slowly break its proteins down into amino acids, producing the savory patis (fish sauce) and bagoong.", "bis": "Kon i-ferment ang isda nga daghan og asin, ang mga enzyme ug bakterya hinay-hinayng moguba sa protina niini ngadto sa amino acid, nga maoy mohatag og lami nga patis ug bagoong."}, "source": "Consensus food microbiology; Philippine traditional biotechnology", "generator": "claude-workflow", "reviewed": false},
  {"id": "salt-controls-fermentation-microbes-g8", "domain": "LIVING_THINGS", "topic": "salt selects helpful microbes in fermentation", "grades": [8, 9, 10], "terms": ["asin", "salt", "asgad", "fermentation", "pagbuburo", "buro", "burong isda", "atchara", "burong mangga", "bakterya", "bacteria", "lactic acid bacteria", "nakakasamang mikrobyo", "harmful microbes", "namamatay", "kontrol", "preserba", "tubig", "osmosis", "pagpili"], "fact": {"tl": "Sa tradisyonal na pagbuburo gaya ng buro at atchara, pinipigilan ng asin ang paglago ng nakakasirang mikrobyo at hinahayaang dumami lamang ang ligtas na lactic acid bacteria.", "en": "In traditional fermentations like buro and atchara, salt holds back spoilage microbes and lets only the safe lactic acid bacteria thrive.", "bis": "Sa tradisyonal nga pag-ferment sama sa buro ug atchara, ang asin mopugong sa pagtubo sa makadaot nga mikrobyo ug motugot lang nga modaghan ang luwas nga lactic acid bacteria."}, "source": "Consensus food preservation science", "generator": "claude-workflow", "reviewed": false},
  {"id": "cheese-rennet-curds-whey-g9", "domain": "LIVING_THINGS", "topic": "how cheese is made from curds", "grades": [9, 10], "terms": ["cheese", "keso", "kesong puti", "gatas", "milk", "rennet", "enzyme", "namumuo", "namuo", "curds", "whey", "buo", "tubig", "lactic acid bacteria", "bakterya", "bacteria", "asim", "fermentation", "pagbuburo", "naghiwalay", "paghimo og keso"], "fact": {"tl": "Sa paggawa ng keso, pinapaasim muna ng bakterya ang gatas, pagkatapos ay isang enzyme (rennet) ang nagpapamuo nito sa matigas na curds at malabnaw na whey na pinaghihiwalay.", "en": "To make cheese, bacteria first sour the milk, then an enzyme (rennet) makes it clot into solid curds and watery whey, which are separated.", "bis": "Sa paghimo og keso, pasagdan una sa bakterya nga moaslom ang gatas, dayon usa ka enzyme (rennet) ang mopamuo niini ngadto sa gahi nga curds ug labnaw nga whey nga gibulag."}, "source": "Consensus dairy science; AAAS Benchmarks Ch.8", "generator": "claude-workflow", "reviewed": false},
  {"id": "pasteurization-kills-microbes-g8", "domain": "LIVING_THINGS", "topic": "pasteurization makes food safe", "grades": [8, 9, 10], "terms": ["pasteurization", "pasteurisasyon", "gatas", "milk", "init", "heat", "painit", "temperatura", "bakterya", "bacteria", "mikrobyo", "microbes", "namamatay", "patay", "ligtas", "safe", "Louis Pasteur", "spoilage", "preserba", "luwas"], "fact": {"tl": "Sa pasteurization, ipinipinit nang sapat ang gatas o juice para patayin ang mga nakakasamang bakterya nang hindi nasisira ang lasa, kaya nagiging mas ligtas at mas tumatagal ito.", "en": "In pasteurization, milk or juice is heated just enough to kill harmful bacteria without ruining the flavor, making it safer and longer-lasting.", "bis": "Sa pasteurization, init-initan ang gatas o juice og igo aron patyon ang makadaot nga bakterya nga dili madaot ang lami, mao nga mahimo kining mas luwas ug mas dugay."}, "source": "Consensus food safety; named for Louis Pasteur", "generator": "claude-workflow", "reviewed": false},
  {"id": "bread-gluten-traps-co2-g8", "domain": "LIVING_THINGS", "topic": "why bread dough is stretchy and rises", "grades": [8, 9, 10], "terms": ["bread", "tinapay", "pan", "harina", "flour", "gluten", "dough", "masa", "lebadura", "yeast", "carbon dioxide", "CO2", "gas", "buko", "bula", "lumalaki", "umaalsa", "naga-alsa", "nakukulong", "elastic", "nababanat", "fermentation"], "fact": {"tl": "Habang nagfe-ferment ang lebadura sa masa, ang carbon dioxide na nalalabas ay nakukulong ng nababanat na gluten ng harina, kaya umaalsa at nagiging mabuko ang tinapay.", "en": "As yeast ferments in the dough, the carbon dioxide it releases is trapped by the flour's stretchy gluten, so the bread rises and becomes full of holes.", "bis": "Samtang mo-ferment ang lebadura sa masa, ang carbon dioxide nga gibuga niini makulong sa nabanat nga gluten sa harina, mao nga moalsa ug magbuho-buho ang tinapay."}, "source": "Consensus food science; AAAS Benchmarks Ch.8", "generator": "claude-workflow", "reviewed": false},
  {"id": "fermentation-vs-spoilage-g9", "domain": "LIVING_THINGS", "topic": "fermentation versus spoilage", "grades": [9, 10], "terms": ["fermentation", "pagbuburo", "spoilage", "pagkasira", "panis", "bulok", "nadunot", "naghuluw", "kontrolado", "controlled", "ligtas na mikrobyo", "safe microbes", "nakakasama", "harmful", "bakterya", "bacteria", "preserba", "asin", "asido", "acid", "ferment vs sira"], "fact": {"tl": "Ang fermentation at pagkasira ay parehong gawa ng mikrobyo, ngunit sa fermentation ay pinili at kinontrol ang ligtas na mikrobyo na gumagawa ng asido o alkohol na pumipigil naman sa nakakasamang mikrobyo.", "en": "Fermentation and spoilage are both caused by microbes, but in fermentation we choose and control safe microbes whose acid or alcohol actually holds back the harmful ones.", "bis": "Ang fermentation ug ang pagkadaot parehong gibuhat sa mikrobyo, apan sa fermentation gipili ug gikontrol nato ang luwas nga mikrobyo nga ang ilang asido o alkohol mopugong sa makadaot nga mikrobyo."}, "source": "Consensus food microbiology", "generator": "claude-workflow", "reviewed": false},
  {"id": "probiotics-gut-bacteria-g9", "domain": "LIVING_THINGS", "topic": "probiotics and helpful gut bacteria", "grades": [9, 10], "terms": ["probiotics", "probiotic", "yogurt", "fermented food", "pagkaing fermented", "Lactobacillus", "bakterya", "bacteria", "bituka", "gut", "tinai", "digestion", "panunaw", "good bacteria", "mabuting bakterya", "maayong bakterya", "kalusugan", "health", "balanse"], "fact": {"tl": "Ang mga probiotics ay mga buhay na mabubuting bakterya, gaya ng nasa yogurt, na tumutulong panatilihin ang malusog na balanse ng bakterya sa ating bituka.", "en": "Probiotics are live helpful bacteria, like those in yogurt, that help keep a healthy balance of bacteria in our gut.", "bis": "Ang probiotics mao ang buhi nga maayong bakterya, sama sa anaa sa yogurt, nga motabang sa pagtipig sa himsog nga balanse sa bakterya sa atong tinai."}, "source": "Consensus nutrition and microbiology", "generator": "claude-workflow", "reviewed": false},
  {"id": "biotechnology-definition-g8", "domain": "LIVING_THINGS", "topic": "what biotechnology is", "grades": [8, 9, 10], "terms": ["biotechnology", "biyoteknolohiya", "biotech", "organismo", "organism", "buhay", "living things", "mikrobyo", "microbes", "bakterya", "bacteria", "lebadura", "yeast", "gamit ng tao", "products", "produkto", "gamot", "medicine", "pagkain", "food", "teknolohiya", "siyensya"], "fact": {"tl": "Ang biotechnology ay ang paggamit ng mga buhay na organismo gaya ng bakterya, lebadura, at halaman para gumawa ng mga kapaki-pakinabang na bagay tulad ng pagkain, gamot, at panggatong.", "en": "Biotechnology is the use of living organisms such as bacteria, yeast, and plants to make useful things like food, medicine, and fuel.", "bis": "Ang biotechnology mao ang paggamit sa buhi nga organismo sama sa bakterya, lebadura, ug tanom aron mohimo og mapuslanon nga mga butang sama sa pagkaon, tambal, ug sugnod."}, "source": "NRC LS1; AAAS Benchmarks Ch.8 (designed systems)", "generator": "claude-workflow", "reviewed": false},
  {"id": "dna-carries-genetic-instructions-g8", "domain": "LIVING_THINGS", "topic": "DNA carries the instructions of life", "grades": [8, 9, 10], "terms": ["DNA", "deoxyribonucleic acid", "gene", "gen", "genes", "instruksiyon", "instructions", "code", "code ng buhay", "minana", "inherited", "namana", "katangian", "traits", "protina", "protein", "selula", "cell", "organismo", "organism", "heredity", "pagmamana"], "fact": {"tl": "Ang DNA ay isang mahabang molekula sa loob ng selula na nagtataglay ng mga instruksiyon, na tinatawag na gene, kung paano lumalaki at gumagana ang isang organismo.", "en": "DNA is a long molecule inside the cell that carries the instructions, called genes, for how an organism grows and works.", "bis": "Ang DNA usa ka taas nga molekula sulod sa selula nga nagdala sa mga instruksiyon, gitawag og gene, kon unsaon pagtubo ug paglihok sa usa ka organismo."}, "source": "NRC LS3.A Inheritance; consensus molecular biology", "generator": "claude-workflow", "reviewed": false},
  {"id": "genetic-engineering-moving-genes-g9", "domain": "LIVING_THINGS", "topic": "genetic engineering basics", "grades": [9, 10], "terms": ["genetic engineering", "inhinyeryang genetiko", "gene", "gen", "DNA", "lipat", "moving genes", "ilipat", "ibalhin", "bagong katangian", "new trait", "bagong gana", "organismo", "organism", "bakterya", "bacteria", "siyentipiko", "scientist", "laboratoryo", "recombinant", "pag-usab og gene"], "fact": {"tl": "Sa genetic engineering, maingat na inililipat ng mga siyentipiko ang isang gene mula sa isang organismo papunta sa iba para magkaroon ito ng bagong kakayahan, gaya ng paggawa ng isang tiyak na protina.", "en": "In genetic engineering, scientists carefully move a gene from one organism into another so it gains a new ability, such as making a particular protein.", "bis": "Sa genetic engineering, maampingong ibalhin sa mga siyentipiko ang usa ka gene gikan sa usa ka organismo ngadto sa lain aron makaangkon kini og bag-ong abilidad, sama sa paghimo og piho nga protina."}, "source": "NRC LS3; AAAS Benchmarks Ch.8 consensus biotechnology", "generator": "claude-workflow", "reviewed": false},
  {"id": "recombinant-insulin-bacteria-g10", "domain": "LIVING_THINGS", "topic": "insulin made by engineered bacteria", "grades": [9, 10], "terms": ["insulin", "insulina", "diabetes", "dyabetis", "sugar", "asukal sa dugo", "blood sugar", "bakterya", "bacteria", "E. coli", "gene", "gen", "genetic engineering", "gamot", "medicine", "engineered", "ginawa", "gibuhat", "human gene", "protina", "protein"], "fact": {"tl": "Dati ay kinukuha ang insulin mula sa hayop, ngunit ngayon ay inilalagay ng mga siyentipiko ang human insulin gene sa bakterya para ito na ang gumawa ng malinis na insulin para sa mga may diabetes.", "en": "Insulin used to be taken from animals, but now scientists put the human insulin gene into bacteria so the bacteria make pure insulin for people with diabetes.", "bis": "Kaniadto, ang insulin gikuha gikan sa hayop, apan karon ibutang sa mga siyentipiko ang human insulin gene sa bakterya aron ang bakterya na ang mohimo og limpyo nga insulin alang sa mga adunay diabetes."}, "source": "Consensus biotechnology; recombinant DNA technology", "generator": "claude-workflow", "reviewed": false},
  {"id": "gmo-meaning-g9", "domain": "LIVING_THINGS", "topic": "what a GMO is", "grades": [9, 10], "terms": ["GMO", "genetically modified organism", "binagong gene", "modified", "gene", "DNA", "halaman", "plant", "pananim", "crop", "katangian", "trait", "bagong katangian", "peste", "pest", "resistant", "labanan", "genetic engineering", "tanom nga giusab", "binhi"], "fact": {"tl": "Ang GMO o genetically modified organism ay isang halaman o hayop na sadyang binago ang gene gamit ang genetic engineering para magkaroon ito ng kapaki-pakinabang na katangian.", "en": "A GMO, or genetically modified organism, is a plant or animal whose genes have been deliberately changed using genetic engineering to give it a useful trait.", "bis": "Ang GMO o genetically modified organism usa ka tanom o hayop nga tinuyo nga giusab ang gene pinaagi sa genetic engineering aron makabaton kini og mapuslanon nga kinaiya."}, "source": "AAAS Benchmarks Ch.8; consensus biotechnology", "generator": "claude-workflow", "reviewed": false},
  {"id": "bt-corn-pest-resistance-g10", "domain": "LIVING_THINGS", "topic": "Bt corn resists insect pests", "grades": [9, 10], "terms": ["Bt corn", "mais", "corn", "GMO", "Bacillus thuringiensis", "bakterya", "bacteria", "gene", "gen", "protina", "protein", "peste", "pest", "uod", "insekto", "insect", "kumakain", "pesticide", "less pesticide", "resistant", "labanan", "Pilipinas", "Philippines"], "fact": {"tl": "Ang Bt corn ay isang GMO na may dagdag na gene mula sa bakteryang Bacillus thuringiensis, na nagpapagawa rito ng protinang nakakapatay sa mga uod na kumakain dito kaya mas kaunti ang kailangang pesticide.", "en": "Bt corn is a GMO carrying an added gene from the bacterium Bacillus thuringiensis, which makes it produce a protein that kills the caterpillars that eat it, so less pesticide is needed.", "bis": "Ang Bt corn usa ka GMO nga adunay dugang nga gene gikan sa bakteryang Bacillus thuringiensis, nga maoy hinungdan nga mohimo kini og protina nga makapatay sa mga ulod nga mokaon niini, mao nga gamay ra ang pesticide nga gikinahanglan."}, "source": "Consensus agricultural biotechnology; grown in the Philippines", "generator": "claude-workflow", "reviewed": false},
  {"id": "golden-rice-vitamin-a-g10", "domain": "LIVING_THINGS", "topic": "Golden Rice and vitamin A", "grades": [9, 10], "terms": ["Golden Rice", "bigas", "rice", "kanin", "GMO", "gene", "beta-carotene", "vitamin A", "bitamina A", "dilaw", "yellow", "golden", "kakulangan", "deficiency", "mata", "eyes", "kalusugan", "Pilipinas", "Philippines", "pananim", "binhi"], "fact": {"tl": "Ang Golden Rice ay isang GMO na bigas na may dagdag na gene para makagawa ng beta-carotene, na ginagawang vitamin A ng katawan, upang tulungan ang mga batang kulang dito.", "en": "Golden Rice is a GMO rice with added genes that let it make beta-carotene, which the body turns into vitamin A, to help children who lack it.", "bis": "Ang Golden Rice usa ka GMO nga bugas nga adunay dugang nga gene aron makahimo og beta-carotene, nga himuon sa lawas nga vitamin A, aron motabang sa mga bata nga kulang niini."}, "source": "Consensus agricultural biotechnology; Philippines approval", "generator": "claude-workflow", "reviewed": false},
  {"id": "tissue-culture-cloning-plants-g9", "domain": "LIVING_THINGS", "topic": "tissue culture to clone plants", "grades": [9, 10], "terms": ["tissue culture", "halaman", "plant", "tanom", "clone", "klon", "pareho", "identical", "saging", "banana", "orchid", "orkidya", "maliit na piraso", "small piece", "laboratoryo", "lab", "agar", "sustansya", "nutrient", "pinararami", "pagpaparami", "propagation"], "fact": {"tl": "Sa tissue culture, isang maliit na piraso ng halaman ang pinapalaki sa isang malinis na lalagyang may sustansya para makagawa ng maraming bagong halamang magkakapareho sa magulang nito.", "en": "In tissue culture, a tiny piece of a plant is grown in a clean nutrient container to produce many new plants that are identical to the parent.", "bis": "Sa tissue culture, usa ka gamay nga bahin sa tanom ang patubuon sa usa ka limpyo nga sudlanan nga adunay sustansya aron makahimo og daghang bag-ong tanom nga pareho sa ginikanan niini."}, "source": "Consensus plant biotechnology", "generator": "claude-workflow", "reviewed": false},
  {"id": "vaccine-types-weakened-inactivated-g9", "domain": "LIVING_THINGS", "topic": "different kinds of vaccines", "grades": [9, 10], "terms": ["vaccine", "bakuna", "uri ng bakuna", "types of vaccines", "weakened", "pinahina", "mahina", "inactivated", "patay", "killed", "piraso", "piece", "protina", "protein", "germ", "mikrobyo", "antibodies", "immune", "antibody", "proteksyon", "klase sa bakuna"], "fact": {"tl": "May iba't ibang uri ng bakuna: ang ilan ay gawa sa pinahinang germ, ang iba ay sa patay na germ, at ang iba ay sa isang piraso lamang ng germ, ngunit lahat ay nagtuturo sa katawan na gumawa ng antibodies.", "en": "There are different kinds of vaccines: some use a weakened germ, some a killed germ, and some just a piece of the germ, but all of them teach the body to make antibodies.", "bis": "Adunay nagkalainlaing klase sa bakuna: ang uban gikan sa gipahuyang nga germ, ang uban gikan sa patay nga germ, ug ang uban gikan lang sa usa ka bahin sa germ, apan tanan kini motudlo sa lawas nga mohimo og antibodies."}, "source": "Consensus immunology; NRC LS1", "generator": "claude-workflow", "reviewed": false},
  {"id": "mrna-vaccine-instructions-g10", "domain": "LIVING_THINGS", "topic": "how mRNA vaccines work", "grades": [9, 10], "terms": ["mRNA vaccine", "bakuna", "mRNA", "messenger RNA", "instruksiyon", "instructions", "protina", "protein", "spike", "germ", "katawan", "body", "selula", "cells", "antibodies", "immune", "COVID", "covid-19", "proteksyon", "tudlo", "panudlo"], "fact": {"tl": "Ang mRNA vaccine ay nagbibigay sa mga selula ng katawan ng instruksiyon para gumawa ng isang ligtas na piraso ng protina ng germ, kaya natututo ang immune system na kilalanin at labanan ang totoong germ.", "en": "An mRNA vaccine gives the body's cells instructions to make one harmless piece of a germ's protein, so the immune system learns to recognize and fight the real germ.", "bis": "Ang mRNA vaccine mohatag sa mga selula sa lawas og instruksiyon aron mohimo og usa ka luwas nga bahin sa protina sa germ, mao nga makakat-on ang immune system nga mailhan ug masukol ang tinuod nga germ."}, "source": "Consensus immunology and molecular biology", "generator": "claude-workflow", "reviewed": false},
  {"id": "antibiotics-from-microbes-g9", "domain": "LIVING_THINGS", "topic": "antibiotics come from microbes", "grades": [9, 10], "terms": ["antibiotics", "antibyotiko", "gamot", "medicine", "mikrobyo", "microbes", "fungi", "amag", "mold", "Penicillium", "bakterya", "bacteria", "lupa", "soil", "natural", "Alexander Fleming", "penicillin", "lumalaban", "fight", "sakit", "disease", "gibuhat sa mikrobyo"], "fact": {"tl": "Maraming antibiotics ang likas na ginagawa ng mga mikrobyo gaya ng amag at bakterya sa lupa, na ginagamit ito bilang sandata laban sa ibang mikrobyo; halimbawa, galing sa amag na Penicillium ang penicillin.", "en": "Many antibiotics are made naturally by microbes such as soil molds and bacteria, which use them as weapons against other microbes; for example, penicillin comes from the Penicillium mold.", "bis": "Daghang antibiotics ang natural nga gihimo sa mga mikrobyo sama sa agup-op ug bakterya sa yuta, nga gigamit kini ingon armas batok sa ubang mikrobyo; pananglitan, ang penicillin gikan sa agup-op nga Penicillium."}, "source": "Consensus microbiology; Alexander Fleming, penicillin", "generator": "claude-workflow", "reviewed": false},
  {"id": "antibiotic-resistance-evolution-g10", "domain": "LIVING_THINGS", "topic": "how antibiotic resistance develops", "grades": [9, 10], "terms": ["antibiotic resistance", "resistensya", "antibyotiko", "antibiotics", "bakterya", "bacteria", "gamot", "medicine", "hindi tinatablan", "dili matablan", "nakaligtas", "survive", "dumarami", "multiply", "mutation", "ebolusyon", "evolution", "abuso", "overuse", "kalusugan", "superbug"], "fact": {"tl": "Kapag madalas o maling ginagamit ang antibiotics, ang ilang bakteryang likas na matibay ay nakakaligtas at dumarami, kaya nabubuo ang mga bakteryang hindi na tinatablan ng gamot.", "en": "When antibiotics are used too often or wrongly, a few naturally tough bacteria survive and multiply, so strains arise that the medicine can no longer kill.", "bis": "Kon kanunay o sayop nga gamiton ang antibiotics, ang pipila ka natural nga lig-on nga bakterya makalahutay ug modaghan, mao nga motumaw ang mga bakterya nga dili na matablan sa tambal."}, "source": "NRC LS4 natural selection; consensus public health", "generator": "claude-workflow", "reviewed": false},
  {"id": "enzymes-as-biological-catalysts-g9", "domain": "LIVING_THINGS", "topic": "enzymes speed up reactions", "grades": [9, 10], "terms": ["enzyme", "enzymes", "ensima", "protina", "protein", "catalyst", "pinabilis", "speed up", "reaksiyon", "reaction", "panunaw", "digestion", "fermentation", "pagbuburo", "gawa sa selula", "biological", "sustansya", "specific", "lock and key", "gibuhat sa selula"], "fact": {"tl": "Ang mga enzyme ay mga espesyal na protina na pinabibilis ang mga reaksiyong kemikal sa buhay na bagay, gaya ng pagbabakbak ng pagkain o ng paggawa ng produkto sa fermentation.", "en": "Enzymes are special proteins that speed up the chemical reactions in living things, such as breaking down food or making products during fermentation.", "bis": "Ang mga enzyme mao ang espesyal nga protina nga mopaspas sa mga reaksiyong kemikal sa buhi nga butang, sama sa pagguba sa pagkaon o paghimo og produkto sa fermentation."}, "source": "NRC LS1.C; consensus biochemistry", "generator": "claude-workflow", "reviewed": false},
  {"id": "yeast-vs-baking-soda-rise-g8", "domain": "LIVING_THINGS", "topic": "biological vs chemical leavening", "grades": [8, 9, 10], "terms": ["leavening", "pampaalsa", "lebadura", "yeast", "baking soda", "baking powder", "tinapay", "bread", "cake", "carbon dioxide", "CO2", "gas", "buhay", "living", "kemikal", "chemical", "reaksiyon", "fermentation", "pagbuburo", "umaalsa", "pagkakaiba", "kalainan"], "fact": {"tl": "Parehong nagpapaalsa sa masa ang lebadura at baking soda dahil pareho silang naglalabas ng carbon dioxide, ngunit ang lebadura ay buhay na nagfe-ferment habang ang baking soda ay isang reaksiyong kemikal lamang.", "en": "Both yeast and baking soda make dough rise because both release carbon dioxide, but yeast is alive and ferments while baking soda is just a chemical reaction.", "bis": "Parehong moalsa sa masa ang lebadura ug baking soda kay parehong mobuga og carbon dioxide, apan ang lebadura buhi nga mo-ferment samtang ang baking soda usa lang ka reaksiyong kemikal."}, "source": "Consensus food science", "generator": "claude-workflow", "reviewed": false},
  {"id": "biofertilizer-rhizobium-g9", "domain": "LIVING_THINGS", "topic": "biofertilizers use nitrogen-fixing bacteria", "grades": [9, 10], "terms": ["biofertilizer", "biyolohikong abono", "abono", "fertilizer", "bakterya", "bacteria", "Rhizobium", "nitrogen", "nitroheno", "hangin", "air", "ugat", "roots", "legume", "munggo", "lupa", "soil", "tabunok", "pananim", "crop", "natural na abono", "binhi"], "fact": {"tl": "Ang biofertilizer ay gumagamit ng buhay na bakterya gaya ng Rhizobium na kumukuha ng nitrogen mula sa hangin at ginagawa itong sustansyang magagamit ng pananim, kaya nababawasan ang pangangailangan sa kemikal na abono.", "en": "A biofertilizer uses living bacteria like Rhizobium that take nitrogen from the air and turn it into a nutrient plants can use, reducing the need for chemical fertilizer.", "bis": "Ang biofertilizer mogamit og buhi nga bakterya sama sa Rhizobium nga mokuha og nitrogen gikan sa hangin ug himuon kining sustansya nga magamit sa tanom, mao nga makunhuran ang panginahanglan sa kemikal nga abono."}, "source": "Consensus agricultural biotechnology; NRC LS2 nutrient cycling", "generator": "claude-workflow", "reviewed": false},
  {"id": "fermentation-preserves-without-fridge-g8", "domain": "LIVING_THINGS", "topic": "why fermentation preserves food", "grades": [8, 9, 10], "terms": ["fermentation", "pagbuburo", "preserba", "preservation", "pagkain", "food", "walang ref", "no refrigerator", "way pridyider", "asido", "acid", "lactic acid", "alkohol", "alcohol", "nakakasamang bakterya", "harmful bacteria", "hindi mabuhay", "tagal", "matagal", "panahon", "tradisyonal"], "fact": {"tl": "Pinananatiling ligtas ng fermentation ang pagkain kahit walang ref dahil ang asido o alkohol na ginagawa ng mabubuting mikrobyo ay nagpapahirap mabuhay sa mga nakakasamang bakterya na nagpapasira nito.", "en": "Fermentation keeps food safe even without a fridge because the acid or alcohol made by helpful microbes makes it hard for the harmful, spoilage bacteria to survive.", "bis": "Ang fermentation maghupot sa pagkaon nga luwas bisan walay pridyider tungod kay ang asido o alkohol nga gihimo sa maayong mikrobyo maglisod sa makadaot, makapadaot nga bakterya nga mabuhi."}, "source": "Consensus food preservation science", "generator": "claude-workflow", "reviewed": false},
  {"id": "selective-breeding-vs-genetic-engineering-g10", "domain": "LIVING_THINGS", "topic": "selective breeding versus genetic engineering", "grades": [9, 10], "terms": ["selective breeding", "pagpapasama", "pagpili", "breeding", "genetic engineering", "inhinyeryang genetiko", "gene", "DNA", "katangian", "traits", "pananim", "crop", "hayop", "animal", "henerasyon", "generations", "mabagal", "slow", "mabilis", "direktang", "pagpili sa binhi"], "fact": {"tl": "Sa selective breeding, pinipili ng tao sa loob ng maraming henerasyon ang mga organismong may magandang katangian, samantalang sa genetic engineering ay direktang binabago ang gene para mas mabilis makuha ang gustong katangian.", "en": "In selective breeding, people choose organisms with desirable traits over many generations, while in genetic engineering the genes are changed directly to get the wanted trait much faster.", "bis": "Sa selective breeding, ang tawo mopili sulod sa daghang henerasyon sa mga organismo nga adunay maayong kinaiya, samtang sa genetic engineering direktang usbon ang gene aron mas paspas makuha ang gusto nga kinaiya."}, "source": "NRC LS3/LS4; AAAS Benchmarks Ch.8 consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tapay-rice-wine-fermentation-g8", "domain": "LIVING_THINGS", "topic": "tapay and rice fermentation starters", "grades": [8, 9, 10], "terms": ["tapay", "tapuy", "rice wine", "alak na bigas", "kanin", "rice", "bigas", "fermentation", "pagbuburo", "bubod", "starter", "lebadura", "yeast", "amag", "mold", "mikrobyo", "microbes", "asukal", "alkohol", "alcohol", "tradisyonal nga ilimnon", "Pilipinas"], "fact": {"tl": "Sa paggawa ng tapay o rice wine, isang starter na may halong amag at lebadura ang inilalagay sa lutong kanin; unang ginagawang asukal ng amag ang almirol, at ito naman ay ginagawang alkohol ng lebadura.", "en": "To make tapay or rice wine, a starter containing mold and yeast is added to cooked rice; the mold first turns the starch into sugar, and the yeast then turns that sugar into alcohol.", "bis": "Sa paghimo og tapay o rice wine, usa ka starter nga adunay agup-op ug lebadura ang ibutang sa luto nga kan-on; ang agup-op mouna og himo sa almidon ngadto sa kalamian, ug ang lebadura maoy mohimo niini nga alkohol."}, "source": "Consensus food microbiology; Philippine traditional fermentation", "generator": "claude-workflow", "reviewed": false},
  {"id": "meiosis-makes-sex-cells-g9", "domain": "LIVING_THINGS", "topic": "meiosis makes sex cells", "grades": [9, 10], "terms": ["meiosis", "meyosis", "sex cells", "gametes", "gametos", "sperm", "sperma", "egg", "itlog", "obulo", "selulang sekswal", "sex cell", "espermatosoyto", "pagbahin sa selula"], "fact": {"tl": "Ang meiosis ay isang espesyal na uri ng paghahati ng selula na gumagawa ng mga sex cell o gamete tulad ng sperm at egg.", "en": "Meiosis is a special type of cell division that produces sex cells, or gametes, such as sperm and egg cells.", "bis": "Ang meiosis usa ka espesyal nga matang sa pagbahin sa selula nga naghimo ug mga sex cell o gamete sama sa sperm ug itlog."}, "source": "NRC LS1.B; AAAS 5B/M2", "generator": "claude-workflow", "reviewed": false},
  {"id": "meiosis-halves-chromosomes-g9", "domain": "LIVING_THINGS", "topic": "sex cells have half the chromosomes", "grades": [9, 10], "terms": ["half the chromosomes", "kalahati ng chromosome", "kromosoma", "chromosome number", "bilang ng kromosoma", "katunga sa kromosoma", "haploid", "isang kopya", "isa sa bawat pares", "usa sa matag paris", "one of each pair", "bilang sa kromosoma", "espesyal nga pagbahin"], "fact": {"tl": "Sa meiosis, ang mga sex cell ay tumatanggap lamang ng kalahati ng bilang ng chromosome—isa lang sa bawat pares na nasa magulang na selula.", "en": "In meiosis, each sex cell receives only half the number of chromosomes—just one from each pair found in the parent cell.", "bis": "Sa meiosis, ang mga sex cell makadawat lamang ug katunga sa gidaghanon sa kromosoma—usa lang sa matag paris nga anaa sa selula sa ginikanan."}, "source": "NRC LS1.B; LS3.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "fertilization-egg-sperm-unite-g8", "domain": "LIVING_THINGS", "topic": "fertilization unites egg and sperm", "grades": [8, 9], "terms": ["fertilization", "pagpapabunga", "fertilisasyon", "pagsanib", "egg and sperm", "itlog at sperm", "itlog ug sperm", "fertilized egg", "pinabungang itlog", "nabungang itlog", "zygote", "saygot", "pagtagbo sa itlog ug sperm", "pag-usa sa duha ka selula"], "fact": {"tl": "Sa fertilization, ang isang sex cell mula sa babae (egg) ay nagsasanib sa isang sex cell mula sa lalaki (sperm) upang bumuo ng isang bagong selula.", "en": "In fertilization, a sex cell from the female (the egg) joins with a sex cell from the male (the sperm) to form a single new cell.", "bis": "Sa fertilization, ang usa ka sex cell gikan sa babae (ang itlog) mahiusa sa usa ka sex cell gikan sa lalaki (ang sperm) aron maporma ang usa ka bag-ong selula."}, "source": "AAAS 5B/M2a; NRC LS3.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "fertilized-egg-restores-pairs-g9", "domain": "LIVING_THINGS", "topic": "fertilized egg restores chromosome pairs", "grades": [9, 10], "terms": ["fertilized egg", "pinabungang itlog", "nabungang itlog", "chromosome pairs", "pares ng chromosome", "paris sa kromosoma", "from each parent", "mula sa bawat magulang", "gikan sa matag ginikanan", "two of each chromosome", "dalawang kopya", "duha ka kopya", "kompletong set", "complete set", "katunga gikan sa inahan", "katunga gikan sa amahan"], "fact": {"tl": "Kapag nagsanib ang egg at sperm, ang bagong selula ay may dalawang kopya ng bawat chromosome—isa mula sa ina at isa mula sa ama.", "en": "When egg and sperm unite, the new cell ends up with two of each chromosome—one inherited from the mother and one from the father.", "bis": "Kon mahiusa ang itlog ug sperm, ang bag-ong selula adunay duha ka kopya sa matag kromosoma—usa gikan sa inahan ug usa gikan sa amahan."}, "source": "NRC LS3.A; AAAS 5B/M2b", "generator": "claude-workflow", "reviewed": false},
  {"id": "mitosis-identical-meiosis-different-g9", "domain": "LIVING_THINGS", "topic": "mitosis versus meiosis", "grades": [9, 10], "terms": ["mitosis vs meiosis", "mitosis at meiosis", "pagkakaiba", "kalainan", "identical cells", "magkaparehong selula", "pareho nga selula", "growth and repair", "paglaki at pagkukumpuni", "pagtubo ug pag-ayo", "sex cells", "body cells", "selula sa lawas", "two daughter cells", "four sex cells", "diperensiya sa mitosis ug meiosis"], "fact": {"tl": "Ang mitosis ay gumagawa ng magkaparehong selula para sa paglaki at pagkukumpuni, samantalang ang meiosis ay gumagawa ng magkakaibang sex cell para sa pagpaparami.", "en": "Mitosis makes identical cells for growth and repair, while meiosis makes varied sex cells used for reproduction.", "bis": "Ang mitosis naghimo ug pareho nga mga selula alang sa pagtubo ug pag-ayo, samtang ang meiosis naghimo ug lainlaing sex cell nga gamiton sa pagsanay."}, "source": "NRC LS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "sexual-reproduction-two-parents-g8", "domain": "LIVING_THINGS", "topic": "sexual reproduction needs two parents", "grades": [8, 9], "terms": ["sexual reproduction", "sekswal na pagpaparami", "pagsanay nga sekswal", "two parents", "dalawang magulang", "duha ka ginikanan", "pagsasama ng genes", "paghalo ng pamana", "paghalo sa kabilin", "halo-halong katangian", "mixed traits", "bagong kombinasyon", "bag-ong kombinasyon", "pagpaparami", "pagsanay sa duha ka ginikanan"], "fact": {"tl": "Sa sexual na pagpaparami, dalawang magulang ang nag-aambag ng kanilang genes, kaya ang anak ay may halong katangian mula sa pareho.", "en": "In sexual reproduction, two parents each contribute genes, so the offspring carries a mix of traits from both.", "bis": "Sa sekswal nga pagsanay, duha ka ginikanan ang naghatag sa ilang mga gene, busa ang anak adunay sinagol nga mga kinaiya gikan sa duha."}, "source": "NRC LS1.B; LS3.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "asexual-reproduction-one-parent-g8", "domain": "LIVING_THINGS", "topic": "asexual reproduction from one parent", "grades": [8, 9], "terms": ["asexual reproduction", "asekswal na pagpaparami", "asekswal nga pagsanay", "one parent", "isang magulang", "usa ka ginikanan", "identical offspring", "kaparehong anak", "pareho nga anak", "clone", "kopya", "walang kasama", "walay kauban", "single parent", "eksaktong kopya"], "fact": {"tl": "Sa asexual na pagpaparami, isang magulang lamang ang kailangan at ang mga anak ay halos eksaktong kopya nito.", "en": "In asexual reproduction, only one parent is needed and the offspring are nearly exact copies of that parent.", "bis": "Sa asekswal nga pagsanay, usa ra ka ginikanan ang gikinahanglan ug ang mga anak halos eksaktong kopya niini."}, "source": "NRC LS1.B grade-8 endpoint", "generator": "claude-workflow", "reviewed": false},
  {"id": "sexual-reproduction-makes-variation-g9", "domain": "LIVING_THINGS", "topic": "why offspring vary", "grades": [9, 10], "terms": ["variation", "pagkakaiba-iba", "pagkalainlain", "bakit magkaiba ang magkakapatid", "ngano lahi ang managsoon", "why siblings differ", "bagong kombinasyon ng genes", "bag-ong kombinasyon sa gene", "new gene combinations", "random na pamana", "random nga kabilin", "magkahalong chromosome", "sinagol nga kromosoma", "diversity", "pagkaiba-iba sa mga anak"], "fact": {"tl": "Magkakaiba ang mga anak dahil sa sexual na pagpaparami ay nabubuo ang bagong kombinasyon ng genes mula sa dalawang magulang.", "en": "Offspring vary because sexual reproduction creates new combinations of genes from the two parents.", "bis": "Managlahi ang mga anak tungod kay ang sekswal nga pagsanay maghimo ug bag-ong kombinasyon sa mga gene gikan sa duha ka ginikanan."}, "source": "NRC LS3.B; AAAS 5B/H2", "generator": "claude-workflow", "reviewed": false},
  {"id": "crossing-over-meiosis-g10", "domain": "LIVING_THINGS", "topic": "chromosomes swap sections in meiosis", "grades": [10], "terms": ["crossing over", "pagpapalit ng bahagi", "pag-ilis sa bahin", "swap sections", "magpalitan ng segment", "magbaylo sa segment", "meiosis", "bagong kombinasyon", "bag-ong kombinasyon", "genetic variation", "pagkakaiba-iba ng pamana", "pagkalainlain sa kabilin", "paghalo ng chromosome", "pagsagol sa kromosoma", "rekombinasyon", "recombination"], "fact": {"tl": "Sa meiosis, ang mga chromosome ay minsang nagpapalitan ng bahagi, kaya nabubuo ang mga bagong kombinasyon ng genes at mas maraming pagkakaiba-iba.", "en": "During meiosis, chromosomes can swap sections, creating new combinations of genes and thus more genetic variation.", "bis": "Atol sa meiosis, ang mga kromosoma usahay magbinayloay ug mga bahin, nga maghimo ug bag-ong kombinasyon sa mga gene ug mas daghang pagkalainlain."}, "source": "NRC LS3.B grade-12 endpoint", "generator": "claude-workflow", "reviewed": false},
  {"id": "each-parent-gives-half-genes-g9", "domain": "LIVING_THINGS", "topic": "each parent gives half the genes", "grades": [9, 10], "terms": ["half the genes", "kalahati ng genes", "katunga sa gene", "each parent contributes half", "kalahati mula sa bawat magulang", "katunga gikan sa matag ginikanan", "two alleles", "dalawang allele", "duha ka allele", "isa mula sa ina", "isa mula sa ama", "usa gikan sa inahan", "usa gikan sa amahan", "one from each parent", "pamana sa magulang"], "fact": {"tl": "Sa sexual na pagpaparami, ang bawat magulang ay nag-aambag ng kalahati ng genes ng anak, kaya may dalawang allele ang anak sa bawat trait.", "en": "In sexual reproduction, each parent contributes half of the offspring's genes, so the child has two alleles for each trait.", "bis": "Sa sekswal nga pagsanay, ang matag ginikanan naghatag ug katunga sa mga gene sa anak, busa ang bata adunay duha ka allele sa matag kinaiya."}, "source": "NRC LS3.B grade-8 endpoint; AAAS 5B/H2", "generator": "claude-workflow", "reviewed": false},
  {"id": "two-alleles-may-differ-g9", "domain": "LIVING_THINGS", "topic": "two alleles per gene", "grades": [9, 10], "terms": ["alleles", "allele", "bersyon ng gene", "bersyon sa gene", "two alleles", "dalawang allele", "duha ka allele", "magkaibang bersyon", "lahi nga bersyon", "magkapareho o magkaiba", "managsama o managlahi", "gene variants", "isa sa bawat magulang", "usa sa matag ginikanan"], "fact": {"tl": "Bawat tao ay may dalawang allele para sa bawat gene—isa mula sa bawat magulang—at ang mga ito ay maaaring magkapareho o magkaiba.", "en": "Each person has two alleles for every gene—one from each parent—and these may be identical or may differ from each other.", "bis": "Ang matag tawo adunay duha ka allele alang sa matag gene—usa gikan sa matag ginikanan—ug kini mahimong managsama o managlahi."}, "source": "NRC LS3.A grade-8 endpoint", "generator": "claude-workflow", "reviewed": false},
  {"id": "budding-asexual-g8", "domain": "LIVING_THINGS", "topic": "budding reproduction", "grades": [8, 9], "terms": ["budding", "pagsibol", "usbong", "yeast", "lebadura", "hydra", "umuusbong na anak", "outgrowth", "asexual", "asekswal", "tumutubong bahagi", "nagtubo nga bahin", "nagsibol nga anak", "pag-usbong sa bag-ong organismo"], "fact": {"tl": "Sa budding, isang maliit na usbong ang tumutubo sa magulang na organismo gaya ng yeast o hydra, at kalaunan ay nagiging bagong indibidwal.", "en": "In budding, a small outgrowth forms on a parent organism such as yeast or hydra and eventually becomes a new individual.", "bis": "Sa budding, usa ka gamay nga usbong motubo sa ginikanan nga organismo sama sa yeast o hydra, ug sa kadugayan mahimong bag-ong indibidwal."}, "source": "NRC LS1.B; consensus biology", "generator": "claude-workflow", "reviewed": false},
  {"id": "vegetative-reproduction-plants-g8", "domain": "LIVING_THINGS", "topic": "plants reproduce from plant parts", "grades": [8, 9], "terms": ["vegetative reproduction", "vegetative propagation", "pagpaparami sa pamamagitan ng bahagi ng halaman", "pagsanay gikan sa bahin sa tanom", "stem cutting", "tangkay", "sanga", "kamote", "sweet potato", "ginger", "luya", "luy-a", "tubo", "sugarcane", "stolon", "rhizome", "asekswal sa tanom"], "fact": {"tl": "Maraming halaman tulad ng kamote, luya, at tubo ay maaaring magparami mula sa kanilang sariling tangkay o ugat, hindi mula sa buto.", "en": "Many plants such as sweet potato, ginger, and sugarcane can reproduce from their own stems or roots rather than from seeds.", "bis": "Daghang tanom sama sa kamote, luy-a, ug tubo makasanay gikan sa ilang kaugalingong tangkay o gamot, dili gikan sa liso."}, "source": "NRC LS1.B; consensus botany", "generator": "claude-workflow", "reviewed": false},
  {"id": "spore-reproduction-g8", "domain": "LIVING_THINGS", "topic": "spores reproduce ferns and fungi", "grades": [8, 9], "terms": ["spores", "espora", "spore", "ferns", "pako", "lumot", "fungi", "kabute", "uhong", "moss", "amag", "mold", "tiny reproductive cells", "maliit na selulang nagpaparami", "kumakalat sa hangin", "nagkatag sa hangin", "walang buto", "walay liso"], "fact": {"tl": "Ang mga pako, lumot, at kabute ay nagpaparami sa pamamagitan ng maliliit na spore, hindi sa pamamagitan ng buto o bulaklak.", "en": "Ferns, mosses, and fungi reproduce by means of tiny spores rather than through seeds or flowers.", "bis": "Ang mga pako, lumot, ug uhong magsanay pinaagi sa gagmay nga espora, dili pinaagi sa liso o bulak."}, "source": "NRC LS1.B; consensus biology", "generator": "claude-workflow", "reviewed": false},
  {"id": "regeneration-starfish-g8", "domain": "LIVING_THINGS", "topic": "regeneration of lost body parts", "grades": [8, 9], "terms": ["regeneration", "muling paglaki", "pagtubo pag-usab", "starfish", "bituin sa dagat", "lizard tail", "buntot ng butiki", "ikog sa tiki", "lost body part", "nawawalang bahagi", "nawala nga bahin", "planaria", "regrow", "nagtubo balik", "pagbalik tubo"], "fact": {"tl": "Ang ilang hayop tulad ng starfish at butiki ay kayang mapalitan ang nawawalang bahagi ng kanilang katawan sa pamamagitan ng paghahati ng mga selula.", "en": "Some animals such as starfish and lizards can regrow lost body parts through the division of their cells.", "bis": "Ang pipila ka mananap sama sa starfish ug tiki makahimo sa pagpuli sa nawala nga bahin sa ilang lawas pinaagi sa pagbahin sa ilang mga selula."}, "source": "AAAS 5C/M2a; consensus biology", "generator": "claude-workflow", "reviewed": false},
  {"id": "cell-cycle-grow-then-divide-g9", "domain": "LIVING_THINGS", "topic": "cells grow before dividing", "grades": [9, 10], "terms": ["cell cycle", "siklo ng selula", "siklo sa selula", "grow then divide", "lumaki bago maghati", "motubo una mobahin", "lumaki muna", "motubo una", "growth phase", "yugto ng paglaki", "hugna sa pagtubo", "copy DNA", "kopyahin ang DNA", "kopyaha ang DNA", "paghahanda bago maghati", "pag-andam una mobahin"], "fact": {"tl": "Bago maghati ang isang selula, ito muna ay lumalaki at kinokopya ang lahat ng DNA nito upang maging kumpleto ang bawat bagong selula.", "en": "Before a cell divides, it first grows and copies all of its DNA so that each new cell will be complete.", "bis": "Sa dili pa mobahin ang usa ka selula, kini motubo una ug magkopya sa tanan niyang DNA aron mahingpit ang matag bag-ong selula."}, "source": "AAAS 5C/H4c; NRC LS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "daughter-cells-identical-g8", "domain": "LIVING_THINGS", "topic": "daughter cells get identical DNA", "grades": [8, 9], "terms": ["daughter cells", "anak na selula", "anak nga selula", "dalawang bagong selula", "duha ka bag-ong selula", "two new cells", "identical DNA", "magkaparehong DNA", "pareho nga DNA", "magkaparehong instruksyon", "pareho nga instruksiyon", "pagkakahati", "pagbahin", "kopyang DNA", "kopya sa DNA"], "fact": {"tl": "Kapag naghati ang isang selula sa mitosis, ang dalawang anak na selula ay parehong tumatanggap ng eksaktong kopya ng DNA.", "en": "When a cell divides by mitosis, the two daughter cells each receive an exact copy of the DNA.", "bis": "Kon mobahin ang usa ka selula pinaagi sa mitosis, ang duha ka anak nga selula managsama nga makadawat ug eksaktong kopya sa DNA."}, "source": "NRC LS1.B grade-12 endpoint", "generator": "claude-workflow", "reviewed": false},
  {"id": "differentiation-from-one-cell-g10", "domain": "LIVING_THINGS", "topic": "one cell becomes many cell types", "grades": [9, 10], "terms": ["differentiation", "pagkakaiba ng selula", "pagkalainlain sa selula", "specialized cells", "espesyalisadong selula", "espesyal nga selula", "nerve cell", "muscle cell", "selulang nerbiyo", "selula sa kaunoran", "iba't ibang uri ng selula", "lainlaing matang sa selula", "fertilized egg", "isang selula", "usa ka selula", "lainlaing gene nga gamiton"], "fact": {"tl": "Ang lahat ng selula ng katawan ay nagmula sa iisang pinagbuhol na itlog, ngunit nagiging iba't ibang uri sila dahil iba-ibang genes ang gumagana sa bawat isa.", "en": "All of the body's cells come from one fertilized egg, but they become different types because different genes are switched on in each.", "bis": "Ang tanang selula sa lawas naggikan sa usa ka nabungang itlog, apan mahimo silang lainlaing matang tungod kay lainlaing gene ang gamiton sa matag usa."}, "source": "NRC LS1.B; AAAS 5B/H6", "generator": "claude-workflow", "reviewed": false},
  {"id": "all-cells-same-genes-g10", "domain": "LIVING_THINGS", "topic": "every body cell has the same genes", "grades": [9, 10], "terms": ["same genes", "parehong genes", "pareho nga gene", "every cell", "bawat selula", "matag selula", "identical genetic instructions", "magkaparehong instruksyon", "pareho nga instruksiyon", "skin cell", "selula ng balat", "selula sa panit", "nerve cell", "selulang nerbiyo", "lainlaing gamiton"], "fact": {"tl": "Halos lahat ng selula sa katawan mo ay may eksaktong parehong genes, ngunit iba-iba ang gumagana sa bawat uri kaya magkaiba ang kanilang trabaho.", "en": "Almost every cell in your body holds the exact same genes, but a different set is active in each type, which is why they do different jobs.", "bis": "Halos tanang selula sa imong lawas adunay eksaktong pareho nga mga gene, apan lainlaing set ang aktibo sa matag matang, mao nga lahi ang ilang trabaho."}, "source": "AAAS 5B/H6; NRC LS3.A grade-12 endpoint", "generator": "claude-workflow", "reviewed": false},
  {"id": "cancer-uncontrolled-division-g10", "domain": "LIVING_THINGS", "topic": "cancer is uncontrolled cell division", "grades": [10], "terms": ["cancer", "kanser", "uncontrolled division", "walang kontrol na paghahati", "walay kontrol nga pagbahin", "tumor", "bukol", "abnormal cells", "abnormal na selula", "abnormal nga selula", "mutation", "mutasyon", "patuloy na paghahati", "padayon nga pagbahin", "dili makontrol nga pagdaghan sa selula"], "fact": {"tl": "Ang kanser ay nangyayari kapag ang isang selula ay naghahati nang walang kontrol dahil sa pinsala o mutasyon sa mga genes nito.", "en": "Cancer happens when a cell divides without control because of damage or mutation in its genes.", "bis": "Ang kanser mahitabo kon ang usa ka selula mobahin nga walay kontrol tungod sa kadaot o mutasyon sa iyang mga gene."}, "source": "AAAS 5C/H6", "generator": "claude-workflow", "reviewed": false},
  {"id": "mutations-source-of-variation-g10", "domain": "LIVING_THINGS", "topic": "mutations add genetic variation", "grades": [10], "terms": ["mutation", "mutasyon", "pagbabago ng gene", "pagbag-o sa gene", "genetic variation", "pagkakaiba ng pamana", "pagkalainlain sa kabilin", "bagong katangian", "bag-ong kinaiya", "rare changes", "bihirang pagbabago", "talagsa nga pagbag-o", "may pakinabang", "nakaayo", "nakadaot", "harmful", "beneficial", "neutral", "walang epekto", "walay epekto"], "fact": {"tl": "Ang mutasyon ay bihirang pagbabago sa genes na maaaring maging kapaki-pakinabang, nakakasama, o walang epekto, at nagdaragdag ito ng pagkakaiba-iba.", "en": "A mutation is a rare change in genes that may be beneficial, harmful, or neutral, and it adds to genetic variation.", "bis": "Ang mutasyon usa ka talagsa nga pagbag-o sa mga gene nga mahimong mapuslanon, makadaot, o walay epekto, ug kini magdugang sa pagkalainlain."}, "source": "NRC LS3.B grade-8 endpoint; AAAS 5B/H4", "generator": "claude-workflow", "reviewed": false},
  {"id": "selective-breeding-traits-g9", "domain": "LIVING_THINGS", "topic": "selective breeding chooses traits", "grades": [9, 10], "terms": ["selective breeding", "selective na pagpaparami", "pinili nga pagpasanay", "artificial selection", "pumili ng magulang", "pagpili sa ginikanan", "desired traits", "ninanais na katangian", "gusto nga kinaiya", "mas malaking prutas", "mas dako nga prutas", "manok", "baka", "alagang hayop", "new varieties", "bagong uri", "bag-ong klase", "pagpili sa kinaiya"], "fact": {"tl": "Sa selective breeding, pinipili ng tao ang mga magulang na may ninanais na katangian upang maipasa ang mga ito sa susunod na henerasyon.", "en": "In selective breeding, people choose parents with desired traits so that those traits are passed to the next generation.", "bis": "Sa selective breeding, ang mga tawo magpili sa mga ginikanan nga adunay gusto nga kinaiya aron kini ipasa sa sunod nga henerasyon."}, "source": "AAAS 5B/M3; NRC LS4.B grade-8 endpoint", "generator": "claude-workflow", "reviewed": false},
  {"id": "cell-theory-all-from-cells-g8", "domain": "LIVING_THINGS", "topic": "cell theory", "grades": [8, 9], "terms": ["cell theory", "teorya ng selula", "teoriya sa selula", "all living things made of cells", "lahat ng buhay ay gawa sa selula", "tanan nga buhi hinimo sa selula", "basic unit of life", "pinakapangunahing yunit ng buhay", "sukaranang yunit sa kinabuhi", "from existing cells", "mula sa dating selula", "gikan sa naglungtad nga selula", "isa o marami", "usa o daghan", "building blocks"], "fact": {"tl": "Ayon sa cell theory, lahat ng buhay na bagay ay binubuo ng isa o higit pang selula, at ang bawat selula ay nagmula sa dating selula.", "en": "According to cell theory, all living things are made of one or more cells, and every cell comes from a pre-existing cell.", "bis": "Sumala sa cell theory, ang tanang buhi nga butang hinimo sa usa o daghan nga selula, ug ang matag selula naggikan sa naglungtad nang selula."}, "source": "AAAS 5C/M1a; consensus biology", "generator": "claude-workflow", "reviewed": false},
  {"id": "cells-from-existing-cells-g9", "domain": "LIVING_THINGS", "topic": "cells only come from other cells", "grades": [9, 10], "terms": ["cells from cells", "selula mula sa selula", "selula gikan sa selula", "new cells", "bagong selula", "bag-ong selula", "by division", "sa pamamagitan ng paghahati", "pinaagi sa pagbahin", "hindi kusang lumilitaw", "dili kusog motungha", "existing cell", "dating selula", "naglungtad nga selula", "lahat ng selula", "tanang selula"], "fact": {"tl": "Ang mga bagong selula ay hindi kusang lumilitaw—nagmumula sila sa paghahati ng mga selulang nabubuhay na.", "en": "New cells do not appear out of nothing—they arise only from the division of cells that already exist.", "bis": "Ang bag-ong mga selula dili kusog motungha—naggikan kini sa pagbahin sa mga selula nga naglungtad na."}, "source": "AAAS 5C/M2a; consensus biology", "generator": "claude-workflow", "reviewed": false},
  {"id": "tissues-organs-from-cells-g8", "domain": "LIVING_THINGS", "topic": "cells build tissues and organs", "grades": [8, 9], "terms": ["tissues", "tisyu", "himbis sa selula", "organs", "organo", "kahimanan sa lawas", "different cells", "iba't ibang selula", "lainlaing selula", "nerve cells", "selula ng nerbiyo", "muscle cells", "selula ng kalamnan", "selula sa kaunoran", "skin cells", "selula ng balat", "selula sa panit", "levels of organization", "lebel sa organisasyon"], "fact": {"tl": "Ang magkakatulad na selula ay nagsasama-sama upang bumuo ng mga tissue, at ang iba't ibang tissue ay bumubuo ng mga organo.", "en": "Similar cells group together to form tissues, and different tissues combine to form organs.", "bis": "Ang managsama nga mga selula maghiusa aron maporma ang mga tisyu, ug ang lainlaing tisyu maghiusa aron maporma ang mga organo."}, "source": "AAAS 5C/M1b; NRC LS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "improved-microscopes-revealed-microbes-g7", "domain": "LIVING_THINGS", "topic": "better microscopes revealed a hidden world", "grades": [7, 8], "terms": ["microscope", "mikroskopyo", "improved lenses", "pinabuting lente", "gipaayo nga lente", "1600s", "discovery", "natuklasan", "nadiskobrehan", "hidden world", "natatagong mundo", "tinago nga kalibutan", "bacteria", "bakterya", "yeast", "lebadura", "microbes", "mikrobyo", "tiny living things", "maliliit na nabubuhay", "gagmay nga buhi"], "fact": {"tl": "Nang mapabuti ang mga lente ng mikroskopyo noong 1600s, natuklasan ng mga siyentipiko ang isang bagong mundo ng maliliit na nabubuhay tulad ng bakterya at lebadura.", "en": "When microscope lenses improved in the 1600s, scientists discovered a whole new world of tiny living things such as bacteria and yeasts.", "bis": "Sa dihang napaayo ang mga lente sa mikroskopyo niadtong 1600s, nadiskobrehan sa mga siyentista ang usa ka bag-ong kalibutan sa gagmay nga buhi sama sa bakterya ug lebadura."}, "source": "AAAS 10I/M6", "generator": "claude-workflow", "reviewed": false},
  {"id": "microscope-shows-cells-divide-g7", "domain": "LIVING_THINGS", "topic": "watching cells divide under a microscope", "grades": [7, 8], "terms": ["microscope", "mikroskopyo", "watch cells divide", "panoorin ang paghahati ng selula", "tan-awon ang pagbahin sa selula", "living cells", "buhay na selula", "buhi nga selula", "growing and dividing", "lumalaki at naghahati", "nagtubo ug nagbahin", "magnify", "palakihin", "padakuon", "obserbasyon", "obserbahan"], "fact": {"tl": "Sa pamamagitan ng mikroskopyo, maaaring panoorin ng mga estudyante ang mga buhay na selula habang lumalaki, naghahati, at gumagalaw.", "en": "Through a microscope, students can watch living cells as they grow, divide, and move.", "bis": "Pinaagi sa mikroskopyo, makatan-aw ang mga estudyante sa buhi nga mga selula samtang nagtubo, nagbahin, ug naglihok."}, "source": "AAAS 5C/M (grades 3-5 endpoint)", "generator": "claude-workflow", "reviewed": false},
  {"id": "species-mate-fertile-offspring-g8", "domain": "LIVING_THINGS", "topic": "what makes a species", "grades": [8, 9], "terms": ["species", "espesye", "klase sa mananap", "mate", "magparami", "magsanay", "fertile offspring", "anak na may anak", "anak nga makaanak", "same species", "iisang species", "managsama nga espesye", "makakapagparami", "makasanay", "kayang magkaanak", "makahatag ug anak"], "fact": {"tl": "Ang isang species ay binubuo ng mga organismong kayang magparami nang magkasama at magkaroon ng anak na kaya ring magkaanak.", "en": "A species is made up of organisms that can mate with one another and produce offspring that can themselves reproduce.", "bis": "Ang usa ka espesye gilangkoban sa mga organismo nga makasanay nga managsama ug makahimo ug anak nga makasanay usab."}, "source": "AAAS 5A/M4", "generator": "claude-workflow", "reviewed": false},
  {"id": "asexual-fast-no-variation-g9", "domain": "LIVING_THINGS", "topic": "asexual reproduction is fast but lacks variation", "grades": [9, 10], "terms": ["asexual", "asekswal", "mabilis", "paspas", "fast reproduction", "mabilis na pagpaparami", "paspas nga pagsanay", "no variation", "walang pagkakaiba", "walay kalainan", "identical copies", "magkaparehong kopya", "pareho nga kopya", "bakterya", "bacteria", "advantage", "bentaha", "walang halo ng genes", "walay sagol nga gene"], "fact": {"tl": "Ang asexual na pagpaparami ay mabilis at hindi nangangailangan ng kapareha, ngunit halos walang pagkakaiba-iba ang mga anak dahil pawang magkakapareho sila.", "en": "Asexual reproduction is fast and needs no partner, but the offspring show almost no variation because they are all nearly identical.", "bis": "Ang asekswal nga pagsanay paspas ug dili magkinahanglan ug kapikas, apan halos walay kalainan ang mga anak kay halos managsama silang tanan."}, "source": "NRC LS1.B; LS3.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "sex-cells-only-mutations-inherited-g10", "domain": "LIVING_THINGS", "topic": "only sex-cell mutations are inherited", "grades": [10], "terms": ["sex cells", "selulang sekswal", "sex cell", "mutation inherited", "namamanang mutasyon", "napanunod nga mutasyon", "egg and sperm", "itlog at sperm", "itlog ug sperm", "body cells", "selula ng katawan", "selula sa lawas", "passed to offspring", "naipapasa sa anak", "mapasa sa anak", "hindi minana", "dili mapanunod", "reproductive cells", "selulang pang-reproduksiyon"], "fact": {"tl": "Tanging ang mga mutasyon sa mga sex cell (itlog at sperm) ang naipapasa sa anak; ang mutasyon sa ibang selula ay hindi minamana.", "en": "Only mutations in the sex cells (egg and sperm) can be passed to offspring; mutations in other body cells are not inherited.", "bis": "Ang mutasyon lamang sa mga sex cell (itlog ug sperm) ang mapasa sa anak; ang mutasyon sa ubang selula sa lawas dili mapanunod."}, "source": "AAAS 5B/H5", "generator": "claude-workflow", "reviewed": false},
  {"id": "carbon-cycle-overview-g8", "domain": "LIVING_THINGS", "topic": "carbon cycle overview", "grades": [8, 9, 10], "terms": ["carbon cycle", "siklo ng karbon", "ikot ng karbon", "siklo sa carbon", "carbon dioxide", "carbon dioxide sa hangin", "biosphere atmosphere ocean", "karbon", "carbon", "exchange of carbon", "palitan ng karbon", "kapunoan ng karbon", "carbon nga elemento"], "fact": {"tl": "Sa siklo ng karbon, ang elementong karbon ay paikot-ikot na inililipat sa pagitan ng hangin, mga halaman at hayop, karagatan, at lupa sa pamamagitan ng photosynthesis, paghinga, at pagkabulok.", "en": "In the carbon cycle, the element carbon moves round and round between the air, living things, the oceans, and the ground through photosynthesis, respiration, and decay.", "bis": "Sa siklo sa carbon, ang elemento nga carbon naglibot-libot tali sa hangin, mga buhing butang, kadagatan, ug yuta pinaagi sa photosynthesis, pagginhawa, ug pagkadunot."}, "source": "NRC LS2.B (carbon cycle, grade 8); AAAS 5E", "generator": "claude-workflow", "reviewed": false},
  {"id": "photosynthesis-removes-co2-g8", "domain": "LIVING_THINGS", "topic": "photosynthesis takes in carbon dioxide", "grades": [8, 9, 10], "terms": ["photosynthesis takes carbon dioxide", "kumukuha ng carbon dioxide", "halaman kumukuha ng karbon", "photosynthesis carbon dioxide tubig asukal", "tanom nagkuha ug carbon dioxide", "sugar from carbon dioxide", "asukal mula sa karbon", "oxygen released", "naglalabas ng oxygen", "nagbuga ug oxygen"], "fact": {"tl": "Sa photosynthesis, kinukuha ng mga halaman ang carbon dioxide mula sa hangin at pinagsasama ito sa tubig gamit ang liwanag ng araw upang gumawa ng asukal, habang naglalabas ng oxygen.", "en": "In photosynthesis, plants take carbon dioxide from the air and combine it with water using sunlight to make sugar, while releasing oxygen.", "bis": "Sa photosynthesis, ang mga tanom nagkuha ug carbon dioxide gikan sa hangin ug giusa kini sa tubig pinaagi sa kahayag sa adlaw aron mahimong asukal, samtang nagbuga ug oxygen."}, "source": "NRC LS1.C / PS3.D (grade 8); AAAS 5E/M1b", "generator": "claude-workflow", "reviewed": false},
  {"id": "respiration-returns-co2-g8", "domain": "LIVING_THINGS", "topic": "respiration releases carbon dioxide", "grades": [8, 9, 10], "terms": ["cellular respiration", "paghinga ng selula", "respiration releases carbon dioxide", "naglalabas ng carbon dioxide", "asukal at oxygen", "sugar reacts with oxygen", "nagbubuga ng karbon", "pagginhawa nagbuga ug carbon dioxide", "enerhiya mula sa pagkain", "energy from food", "kusog gikan sa pagkaon"], "fact": {"tl": "Sa selular na paghinga, nakikipagreaksyon ang asukal sa oxygen upang maglabas ng enerhiya para sa katawan, at nagbubuga ng carbon dioxide pabalik sa hangin.", "en": "In cellular respiration, sugar reacts with oxygen to release energy for the body, and gives off carbon dioxide back into the air.", "bis": "Sa cellular respiration, ang asukal mareaksyon sa oxygen aron mahatag ang kusog alang sa lawas, ug magbuga ug carbon dioxide balik sa hangin."}, "source": "NRC LS1.C (grade 8/12); AAAS 5E", "generator": "claude-workflow", "reviewed": false},
  {"id": "burning-fossil-fuels-carbon-g9", "domain": "LIVING_THINGS", "topic": "burning fossil fuels releases carbon", "grades": [9, 10], "terms": ["fossil fuels", "panggatong na fosil", "pagsunog ng panggatong", "burning coal oil gas", "uling langis gas", "carbon dioxide release", "naglalabas ng carbon dioxide", "fossil fuel sunog", "pagsunog sa fossil fuel", "karbon mula sa lumang halaman", "carbon from ancient plants", "stored carbon"], "fact": {"tl": "Ang karbon, langis, at gas ay nabuo mula sa mga sinaunang halaman at hayop, kaya kapag sinusunog ito ay naglalabas ng carbon dioxide na matagal nang nakaimbak sa lupa.", "en": "Coal, oil, and gas formed from ancient plants and animals, so burning them releases carbon dioxide that had been stored underground for a very long time.", "bis": "Ang uling, lana, ug gas naporma gikan sa karaang mga tanom ug mananap, mao nga ang pagsunog niini magpagawas ug carbon dioxide nga dugay nang gitipigan ilalom sa yuta."}, "source": "NRC PS3.D / ESS3.D; AAAS 5E/H1", "generator": "claude-workflow", "reviewed": false},
  {"id": "decomposers-release-carbon-g8", "domain": "LIVING_THINGS", "topic": "decay releases carbon back", "grades": [8, 9], "terms": ["decomposition releases carbon", "pagkabulok naglalabas ng karbon", "decomposers carbon dioxide", "mga bulok na halaman", "rotting returns carbon", "pagkadunot nagpabalik ug carbon", "bacteria fungi decay", "bakterya fungi", "namamatay na bagay", "dead matter decay", "patay nga butang madunot"], "fact": {"tl": "Kapag binubulok ng bakterya at fungi ang mga patay na halaman at hayop, naglalabas sila ng carbon dioxide na nagbabalik ng karbon sa hangin at lupa.", "en": "When bacteria and fungi break down dead plants and animals, they release carbon dioxide that returns carbon to the air and soil.", "bis": "Kung dunoton sa bakterya ug fungi ang mga patay nga tanom ug mananap, magpagawas sila ug carbon dioxide nga magpabalik sa carbon ngadto sa hangin ug yuta."}, "source": "NRC LS2.B (decomposers, grade 8); AAAS 5E", "generator": "claude-workflow", "reviewed": false},
  {"id": "nitrogen-fixation-bacteria-g8", "domain": "LIVING_THINGS", "topic": "nitrogen fixation by bacteria", "grades": [8, 9, 10], "terms": ["nitrogen fixation", "pagpapako ng nitrogen", "nitrogen-fixing bacteria", "bakterya sa nitrogen", "nitroheno sa hangin", "nitrogen from air", "halaman hindi makagamit ng nitrogen sa hangin", "plants cannot use air nitrogen", "bakterya nagbag-o sa nitrogen", "nitrogen para sa halaman", "usable nitrogen"], "fact": {"tl": "Hindi magagamit ng mga halaman ang nitrogen gas mula mismo sa hangin, kaya may mga espesyal na bakterya na nagbabago nito sa anyong kayang sipsipin ng mga ugat.", "en": "Plants cannot use nitrogen gas straight from the air, so special bacteria change it into a form the roots can absorb.", "bis": "Dili magamit sa mga tanom ang nitrogen gas direkta gikan sa hangin, mao nga adunay espesyal nga bakterya nga nag-usab niini ngadto sa porma nga masuyop sa mga gamot."}, "source": "NRC LS2.B; AAAS consensus on nitrogen cycle", "generator": "claude-workflow", "reviewed": false},
  {"id": "nitrogen-needed-proteins-g8", "domain": "LIVING_THINGS", "topic": "nitrogen builds proteins", "grades": [8, 9, 10], "terms": ["nitrogen for proteins", "nitroheno para sa protina", "nitrogen builds protein DNA", "nitrogen kailangan ng buhay", "amino acids", "protina at DNA", "nitrogen alang sa protina", "kinahanglan nga sustansya", "essential element nitrogen", "elementong nitroheno"], "fact": {"tl": "Kailangan ng lahat ng buhay ang nitrogen dahil ito ay bahagi ng mga protina at DNA na bumubuo sa kanilang mga selula.", "en": "All living things need nitrogen because it is part of the proteins and DNA that build their cells.", "bis": "Ang tanang buhing butang nagkinahanglan ug nitrogen kay kini bahin sa mga protina ug DNA nga naghimo sa ilang mga selula."}, "source": "NRC LS1.C; AAAS 5C/H8 (cell elements)", "generator": "claude-workflow", "reviewed": false},
  {"id": "nitrogen-decay-return-g8", "domain": "LIVING_THINGS", "topic": "nitrogen returns through decay", "grades": [8, 9, 10], "terms": ["nitrogen returns to soil", "nitroheno bumabalik sa lupa", "decomposition releases nitrogen", "pagkabulok nitrogen", "denitrification balik sa hangin", "nitrogen back to air", "patay na bagay nitrogen", "decay nitrogen soil", "pagkadunot nagpabalik ug nitrogen", "ammonia nitrates"], "fact": {"tl": "Kapag namamatay at nabubulok ang mga halaman at hayop, ang nitrogen sa kanilang katawan ay bumabalik sa lupa, at ang ibang bakterya ay nagpapabalik nito sa hangin.", "en": "When plants and animals die and decay, the nitrogen in their bodies returns to the soil, and other bacteria send some of it back into the air.", "bis": "Kung mamatay ug madunot ang mga tanom ug mananap, ang nitrogen sa ilang lawas mobalik sa yuta, ug ang ubang bakterya magpabalik sa pipila niini ngadto sa hangin."}, "source": "NRC LS2.B; consensus nitrogen cycle", "generator": "claude-workflow", "reviewed": false},
  {"id": "lightning-fixes-nitrogen-g9", "domain": "LIVING_THINGS", "topic": "lightning fixes nitrogen", "grades": [9, 10], "terms": ["lightning nitrogen", "kidlat nitrogen", "lightning fixes nitrogen", "kidlat nagbabago ng nitroheno", "nitrogen sa ulan", "nitrogen in rain", "kilat nitrogen", "nitrogen compounds rain", "natural nitrogen fixation", "likas na pagpapako ng nitrogen"], "fact": {"tl": "Ang malakas na init ng kidlat ay nakakapagbago rin ng nitrogen gas sa hangin tungo sa anyong nadadala ng ulan papunta sa lupa para magamit ng mga halaman.", "en": "The intense heat of lightning can also change nitrogen gas in the air into a form that rain carries down to the soil for plants to use.", "bis": "Ang grabe nga kainit sa kilat makausab usab sa nitrogen gas sa hangin ngadto sa porma nga gidala sa ulan paingon sa yuta aron magamit sa mga tanom."}, "source": "Consensus nitrogen cycle (atmospheric fixation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "oxygen-cycle-photosynthesis-g8", "domain": "LIVING_THINGS", "topic": "oxygen cycle", "grades": [8, 9, 10], "terms": ["oxygen cycle", "siklo ng oxygen", "oxygen from photosynthesis", "oxygen mula sa halaman", "respiration uses oxygen", "paghinga gumagamit ng oxygen", "balanse ng oxygen", "oxygen balance", "siklo sa oxygen", "tanom naghatag ug oxygen", "oxygen para sa hangin"], "fact": {"tl": "Sa siklo ng oxygen, naglalabas ng oxygen ang mga halaman sa photosynthesis, at ginagamit naman ito ng mga hayop at halaman sa paghinga, kaya patuloy itong napapalitan sa hangin.", "en": "In the oxygen cycle, plants release oxygen during photosynthesis, and animals and plants use it up when they breathe, so it keeps being replaced in the air.", "bis": "Sa siklo sa oxygen, ang mga tanom magbuga ug oxygen panahon sa photosynthesis, ug gamiton kini sa mga mananap ug tanom kung mangginhawa, busa kanunay kining mailisan sa hangin."}, "source": "NRC LS2.B; PS1 (oxygen proportion in carbon cycle)", "generator": "claude-workflow", "reviewed": false},
  {"id": "phytoplankton-oxygen-g9", "domain": "LIVING_THINGS", "topic": "ocean plankton make oxygen", "grades": [9, 10], "terms": ["phytoplankton oxygen", "plankton sa dagat oxygen", "ocean phytoplankton photosynthesis", "munting halaman sa dagat", "plankton naghahatid ng oxygen", "marine algae oxygen", "lumot sa dagat", "phytoplankton sa kadagatan", "tiny ocean plants", "dagat oxygen"], "fact": {"tl": "Hindi lamang ang mga puno ang gumagawa ng oxygen; ang mga napakaliit na halaman sa dagat na tinatawag na phytoplankton ay gumagawa rin ng malaking bahagi ng oxygen sa mundo.", "en": "Trees are not the only oxygen makers; tiny ocean plants called phytoplankton also produce a large share of the world's oxygen.", "bis": "Dili lang ang mga kahoy ang naghimo ug oxygen; ang gagmay kaayo nga mga tanom sa dagat nga gitawag ug phytoplankton naghimo usab ug dakong bahin sa oxygen sa kalibutan."}, "source": "NRC LS2.B (phytoplankton as energy-fixers); consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "producers-base-foodweb-g7", "domain": "LIVING_THINGS", "topic": "producers base of food web", "grades": [7, 8], "terms": ["producers", "prodyuser", "tagagawa ng pagkain", "producers make own food", "halaman gumagawa ng sariling pagkain", "autotroph", "base of food web", "pundasyon ng food web", "producer naghimo ug kaugalingong pagkaon", "tanom prodyuser", "first trophic level"], "fact": {"tl": "Ang mga halaman at iba pang organismong gumagawa ng sariling pagkain sa pamamagitan ng photosynthesis ay tinatawag na producers, at sila ang pundasyon ng bawat food web.", "en": "Plants and other organisms that make their own food through photosynthesis are called producers, and they are the base of every food web.", "bis": "Ang mga tanom ug uban pang organismo nga naghimo sa ilang kaugalingong pagkaon pinaagi sa photosynthesis gitawag nga producers, ug sila ang pundasyon sa matag food web."}, "source": "NRC LS2.A/LS2.B (grade 8); AAAS 5D/M4", "generator": "claude-workflow", "reviewed": false},
  {"id": "consumers-types-g7", "domain": "LIVING_THINGS", "topic": "types of consumers", "grades": [7, 8], "terms": ["consumers", "konsyumer", "mamimili ng pagkain", "herbivore carnivore omnivore", "herbivoro karnivoro omnivoro", "primary secondary consumer", "tagakain ng halaman", "tagakain ng hayop", "mananap nga mokaon", "consumer mokaon sa lain", "plant eater meat eater"], "fact": {"tl": "Ang mga hayop ay tinatawag na consumers dahil hindi sila makakagawa ng sariling pagkain; ang kumakain ng halaman ay herbivore, ang kumakain ng hayop ay carnivore, at ang kumakain ng pareho ay omnivore.", "en": "Animals are called consumers because they cannot make their own food; plant-eaters are herbivores, animal-eaters are carnivores, and those that eat both are omnivores.", "bis": "Ang mga mananap gitawag nga consumers kay dili sila makahimo sa ilang kaugalingong pagkaon; ang mokaon ug tanom herbivore, ang mokaon ug mananap carnivore, ug ang mokaon sa duha omnivore."}, "source": "NRC LS2.A; AAAS 5D/M4", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-pyramid-shape-g8", "domain": "LIVING_THINGS", "topic": "energy pyramid shape", "grades": [8, 9, 10], "terms": ["energy pyramid", "piramide ng enerhiya", "ecological pyramid", "pyramid of energy", "kakaunti sa taas", "fewer at the top", "more producers at bottom", "marami sa baba", "piramide sa kusog", "pyramid trophic level", "biomass pyramid"], "fact": {"tl": "Ang energy pyramid ay malapad sa ilalim kung saan maraming producers at makitid sa itaas, dahil paliit nang paliit ang enerhiyang naipapasa sa bawat mataas na antas.", "en": "An energy pyramid is wide at the bottom where there are many producers and narrow at the top, because less and less energy is passed up to each higher level.", "bis": "Ang energy pyramid lapad sa ubos diin daghang producers ug sigpit sa taas, kay paubos ug paubos ang kusog nga gipasa ngadto sa matag mas taas nga ang-ang."}, "source": "NRC LS2.B (grade 12 inefficiency); consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ten-percent-rule-meaning-g8", "domain": "LIVING_THINGS", "topic": "ten percent rule explained", "grades": [8, 9, 10], "terms": ["ten percent rule", "10 percent rule", "panuntunan ng sampung porsyento", "10 porsyento energy", "energy lost as heat", "nawawalang enerhiya", "init na nawawala", "napupunta sa init", "energy transfer efficiency", "epekto sa pagpasa ng enerhiya", "napulo ka porsyento"], "fact": {"tl": "Tinatayang 10% lamang ng enerhiya sa isang antas ng pagkain ang naipapasa sa susunod na antas; ang malaking bahagi ay nagagamit sa paghinga at galaw o nawawala bilang init.", "en": "Only about 10% of the energy at one feeding level passes to the next level; most of it is used for breathing and movement or lost as heat.", "bis": "Mga 10% lamang sa kusog sa usa ka ang-ang sa pagkaon ang mapasa ngadto sa sunod nga ang-ang; ang kadaghanan niini gigamit sa pagginhawa ug paglihok o mawala isip kainit."}, "source": "NRC LS2.B (small fraction transferred); consensus 10% rule", "generator": "claude-workflow", "reviewed": false},
  {"id": "few-top-predators-g8", "domain": "LIVING_THINGS", "topic": "why few top predators", "grades": [8, 9, 10], "terms": ["top predators few", "kakaunting mababangis na hayop sa taas", "few apex predators", "bakit kaunti ang malalaking mandaragit", "limited energy top level", "kulang na enerhiya sa taas", "ngano gamay ang predator", "apex predator", "pinakatuktok ng food chain", "energy limit predators"], "fact": {"tl": "Dahil paunti nang paunti ang enerhiyang umaabot sa bawat mataas na antas, kakaunti lamang ang malalaking mandaragit na kayang suportahan sa tuktok ng isang food chain.", "en": "Because less and less energy reaches each higher level, only a small number of large predators can be supported at the top of a food chain.", "bis": "Tungod kay paubos ug paubos ang kusog nga moabot sa matag mas taas nga ang-ang, gamay ra ka mga dagkong predator ang masuportahan sa kinatumyan sa usa ka food chain."}, "source": "NRC LS2.B (grade 12: fewer organisms at higher levels)", "generator": "claude-workflow", "reviewed": false},
  {"id": "matter-recycled-energy-lost-g8", "domain": "LIVING_THINGS", "topic": "matter recycled but energy not", "grades": [8, 9, 10], "terms": ["matter recycled energy not", "materya pwedeng paikutin", "energy cannot be recycled", "enerhiya hindi maibabalik", "matter cycles energy flows", "bagay umiikot enerhiya dumadaloy", "kusog dili mabalik-balik", "materya gigamit balik-balik", "conservation matter energy", "constant input sunlight", "patuloy na enerhiya ng araw"], "fact": {"tl": "Ang materya tulad ng karbon at nitrogen ay maaaring gamitin nang paulit-ulit sa isang ekosistema, ngunit ang enerhiya ay hindi maibabalik, kaya kailangang patuloy na magmula sa araw.", "en": "Matter such as carbon and nitrogen can be reused over and over in an ecosystem, but energy cannot be recycled, so it must keep coming from the sun.", "bis": "Ang materya sama sa carbon ug nitrogen mahimong gamiton balik-balik sa usa ka ekosistema, apan ang kusog dili mabalik, busa kinahanglan kanunayng maggikan sa adlaw."}, "source": "NRC LS2.B; AAAS 5E/H3 (continual input of sunlight)", "generator": "claude-workflow", "reviewed": false},
  {"id": "carrying-capacity-definition-g9", "domain": "LIVING_THINGS", "topic": "carrying capacity definition", "grades": [9, 10], "terms": ["carrying capacity", "kapasidad ng kalikasan", "limitasyon ng populasyon", "carrying capacity ecosystem", "pinakamaraming maaalagaan", "limit of population", "kakapasidad sa palibot", "labi nga populasyon", "maximum population environment", "limitasyon sa kinabuhi", "tugbong kapasidad"], "fact": {"tl": "Ang carrying capacity ay ang pinakamaraming bilang ng isang uri ng organismo na kayang suportahan ng isang kapaligiran nang hindi nauubos ang pagkain, tubig, at tirahan.", "en": "Carrying capacity is the largest number of a kind of organism that an environment can support without running out of food, water, and space.", "bis": "Ang carrying capacity mao ang labing daghang gidaghanon sa usa ka matang sa organismo nga masuportahan sa usa ka palibot nga dili mahurot ang pagkaon, tubig, ug puy-anan."}, "source": "NRC LS2.A (carrying capacity, grade 8/12)", "generator": "claude-workflow", "reviewed": false},
  {"id": "limiting-factors-population-g9", "domain": "LIVING_THINGS", "topic": "limiting factors on population", "grades": [9, 10], "terms": ["limiting factors", "salik na naglilimita", "limiting factors population", "predation disease food", "gutom sakit mandaragit", "kompetisyon sa pagkain", "competition resources", "limita sa populasyon", "kakulangan sa pagkaon", "factors limit growth", "kalimitan sa populasyon"], "fact": {"tl": "Ang dami ng isang populasyon ay nililimitahan ng mga salik gaya ng kakulangan sa pagkain at tubig, sakit, kompetisyon, at mga mandaragit na kumakain dito.", "en": "The size of a population is held in check by factors such as shortage of food and water, disease, competition, and predators that eat it.", "bis": "Ang gidaghanon sa usa ka populasyon gipugngan sa mga butang sama sa kakulang sa pagkaon ug tubig, sakit, kompetisyon, ug mga predator nga mokaon niini."}, "source": "NRC LS2.A (predation, disease, resources)", "generator": "claude-workflow", "reviewed": false},
  {"id": "population-overshoot-decline-g10", "domain": "LIVING_THINGS", "topic": "population overshoot and decline", "grades": [9, 10], "terms": ["population overshoot", "sobrang dami ng populasyon", "population crash decline", "bumababa ang populasyon", "naubos ang pagkain", "resources run out", "labihan nga populasyon", "pagkunhod sa populasyon", "exceed carrying capacity", "lumagpas sa carrying capacity", "shortage starvation"], "fact": {"tl": "Kapag lumagpas ang dami ng isang populasyon sa carrying capacity ng kapaligiran, nauubos ang mga pinagkukunan at maaaring biglang bumaba ang bilang nito dahil sa gutom o sakit.", "en": "When a population grows beyond its environment's carrying capacity, resources run short and its numbers can drop sharply from starvation or disease.", "bis": "Kung molabaw ang gidaghanon sa usa ka populasyon sa carrying capacity sa palibot, mahurot ang mga kahinguhaan ug mahimong kalit nga mokunhod ang ihap niini tungod sa kagutom o sakit."}, "source": "NRC LS2.A (interactions restrain growth, limit size)", "generator": "claude-workflow", "reviewed": false},
  {"id": "invasive-species-balance-g9", "domain": "LIVING_THINGS", "topic": "invasive species upset balance", "grades": [8, 9, 10], "terms": ["invasive species", "dayuhang species", "introduced species damage", "bagong dating na hayop", "sira sa ekosistema", "invasive upsets balance", "dayong organismo", "janitor fish kuhol", "guba sa balanse", "introduced species ecosystem", "pagkasira ng balanse"], "fact": {"tl": "Kapag may bagong uri ng organismo na ipinapasok sa isang ekosistema, maaari nitong sirain ang balanse dahil wala itong likas na kaaway at maaaring lamunin ang pagkain ng mga katutubong species.", "en": "When a new kind of organism is introduced into an ecosystem, it can upset the balance because it has no natural enemies and may eat up the food of native species.", "bis": "Kung adunay bag-ong matang sa organismo nga gipasulod sa usa ka ekosistema, mahimo niining guboon ang balanse kay wala kini natural nga kaaway ug mahimong kan-on ang pagkaon sa lumad nga mga espisye."}, "source": "NRC LS2.A / LS4.D (newly introduced species damage balance)", "generator": "claude-workflow", "reviewed": false},
  {"id": "levels-organization-cell-biosphere-g7", "domain": "LIVING_THINGS", "topic": "levels of biological organization", "grades": [7, 8, 9, 10], "terms": ["levels of organization", "antas ng organisasyon", "cell tissue organ organism", "selula tisyu organ organismo", "population community ecosystem biosphere", "populasyon komunidad ekosistema biosphere", "ang-ang sa organisasyon", "gikan selula hangtod biosphere", "hierarchy of life", "from cell to biosphere"], "fact": {"tl": "Ang buhay ay nakaayos sa mga antas mula sa pinakamaliit hanggang pinakamalaki: selula, tisyu, organ, organismo, populasyon, komunidad, ekosistema, at sa wakas ang biosphere.", "en": "Life is organized in levels from smallest to largest: cell, tissue, organ, organism, population, community, ecosystem, and finally the biosphere.", "bis": "Ang kinabuhi gihan-ay sa mga ang-ang gikan sa pinakagamay ngadto sa pinakadako: selula, tisyu, organ, organismo, populasyon, komunidad, ekosistema, ug sa kataposan ang biosphere."}, "source": "NRC LS2.A (hierarchy: populations, communities, ecosystems, biosphere)", "generator": "claude-workflow", "reviewed": false},
  {"id": "population-vs-community-g7", "domain": "LIVING_THINGS", "topic": "population versus community", "grades": [7, 8], "terms": ["population", "populasyon", "population same species", "iisang uri ng organismo", "community many species", "komunidad maraming uri", "populasyon parehong klase", "komunidad nagkalainlaing espisye", "group of one species", "different populations interacting", "magkaibang populasyon"], "fact": {"tl": "Ang populasyon ay pangkat ng iisang uri ng organismo na naninirahan sa iisang lugar, habang ang komunidad ay binubuo ng iba't ibang populasyon na magkakasamang naninirahan.", "en": "A population is a group of one kind of organism living in one place, while a community is made up of the different populations living there together.", "bis": "Ang populasyon usa ka grupo sa usa ka matang sa organismo nga nagpuyo sa usa ka dapit, samtang ang komunidad gilangkoban sa nagkalainlaing populasyon nga nagpuyo didto nga magkauban."}, "source": "NRC LS2.A (populations form communities)", "generator": "claude-workflow", "reviewed": false},
  {"id": "biotic-abiotic-factors-g7", "domain": "LIVING_THINGS", "topic": "biotic and abiotic factors", "grades": [7, 8, 9], "terms": ["biotic abiotic", "biotic abiotic factors", "buhay at di-buhay na bahagi", "biotic factor halaman hayop", "abiotic factor tubig liwanag temperatura", "buhi ug dili-buhi nga bahin", "living and nonliving parts", "abiotic init hangin lupa", "components of ecosystem", "bahagi ng ekosistema"], "fact": {"tl": "Ang isang ekosistema ay binubuo ng mga biotic na bahagi gaya ng mga halaman at hayop, at mga abiotic na bahagi gaya ng tubig, liwanag, temperatura, at lupa.", "en": "An ecosystem is made of biotic parts such as plants and animals, and abiotic parts such as water, light, temperature, and soil.", "bis": "Ang usa ka ekosistema gilangkoban sa biotic nga mga bahin sama sa mga tanom ug mananap, ug abiotic nga mga bahin sama sa tubig, kahayag, temperatura, ug yuta."}, "source": "NRC LS2.A (biotic and abiotic components)", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-flows-one-way-g8", "domain": "LIVING_THINGS", "topic": "energy flows one direction from sun", "grades": [8, 9, 10], "terms": ["energy flows one way", "enerhiya dumadaloy paisa-isang direksyon", "energy from sun to producers", "enerhiya mula araw", "one direction energy", "isang direksyon ang enerhiya", "kusog gikan sa adlaw", "energy not cycle", "enerhiya hindi umiikot", "sun primary source", "araw ang pinagmulan"], "fact": {"tl": "Ang enerhiya sa karamihan ng ekosistema ay nagmumula sa araw, dumadaloy mula sa mga producer patungo sa mga consumer sa iisang direksyon, at unti-unting nawawala bilang init.", "en": "Energy in most ecosystems comes from the sun, flows in one direction from producers to consumers, and is gradually lost as heat.", "bis": "Ang kusog sa kadaghanan sa mga ekosistema naggikan sa adlaw, nag-agos sa usa ka direksyon gikan sa mga producer ngadto sa mga consumer, ug anam-anam nga mawala isip kainit."}, "source": "NRC LS2.B; AAAS 5E/H3", "generator": "claude-workflow", "reviewed": false},
  {"id": "decomposers-vs-detritivores-g8", "domain": "LIVING_THINGS", "topic": "decomposers and detritivores", "grades": [8, 9], "terms": ["detritivore decomposer", "detritivoro decomposer", "earthworm decomposer", "bulate sa lupa", "detritivore kumakain ng patay", "scavenger nutrient recycler", "uod nga mokaon ug patay", "fungi bacteria break down", "fungi bakterya nagbubulok", "decomposer recycle nutrients", "tagabulok"], "fact": {"tl": "Ang mga detritivore gaya ng bulate sa lupa ay pisikal na nilalamon ang mga patay na bagay, habang ang mga decomposer gaya ng fungi at bakterya ay kemikal na binubulok ang mga ito upang ibalik ang sustansya sa lupa.", "en": "Detritivores such as earthworms physically eat dead matter, while decomposers such as fungi and bacteria chemically break it down to return nutrients to the soil.", "bis": "Ang mga detritivore sama sa bulate sa yuta pisikal nga mokaon sa patay nga butang, samtang ang mga decomposer sama sa fungi ug bakterya kemikal nga magdunot niini aron ibalik ang sustansya sa yuta."}, "source": "NRC LS2.B (decomposers recycle nutrients)", "generator": "claude-workflow", "reviewed": false},
  {"id": "coral-reef-energy-flow-g9", "domain": "LIVING_THINGS", "topic": "coral reef energy and nutrients", "grades": [9, 10], "terms": ["coral reef ecosystem", "bahura ekosistema", "coral reef energy flow", "zooxanthellae algae coral", "lumot sa coral", "coral reef food web", "bahura sa Pilipinas", "reef nutrient cycle", "coral polyp algae", "magkatuwang na coral at lumot", "coral reef productivity"], "fact": {"tl": "Sa mga bahura ng coral sa Pilipinas, ang mga coral ay may maliliit na lumot sa loob nila na gumagawa ng pagkain sa pamamagitan ng photosynthesis, kaya napakasagana ng buhay sa lugar na ito.", "en": "In Philippine coral reefs, the corals hold tiny algae inside them that make food by photosynthesis, which is why these places teem with so much life.", "bis": "Sa mga coral reef sa Pilipinas, ang mga coral adunay gagmay nga lumot sulod nila nga naghimo ug pagkaon pinaagi sa photosynthesis, mao nga daghan kaayog kinabuhi kining mga dapita."}, "source": "NRC LS2.A (coral reef ecosystems); consensus coral-algae symbiosis", "generator": "claude-workflow", "reviewed": false},
  {"id": "biomagnification-toxins-g10", "domain": "LIVING_THINGS", "topic": "toxins build up in food chain", "grades": [9, 10], "terms": ["biomagnification", "biomagnification toxin", "lason umipon sa food chain", "toxin builds up predators", "mercury sa isda", "lason sa pinakataas", "hilo nagtipon sa food chain", "naipon nga hilo", "pollutant accumulate food chain", "lason sa malalaking hayop", "buildup of poison"], "fact": {"tl": "Ang mga lason gaya ng mercury ay maaaring umipon nang paunti-unti pataas sa food chain, kaya ang mga mandaragit sa tuktok ang maaaring magkaroon ng pinakamataas na dami ng lason sa kanilang katawan.", "en": "Poisons such as mercury can build up little by little going up a food chain, so the predators at the top may end up with the highest amount of toxin in their bodies.", "bis": "Ang mga hilo sama sa mercury mahimong matipon anam-anam paingon sa taas sa food chain, busa ang mga predator sa kinatumyan mahimong maoy adunay pinakataas nga gidaghanon sa hilo sa ilang lawas."}, "source": "Consensus ecology (biomagnification); NRC LS2.A interactions", "generator": "claude-workflow", "reviewed": false},
  {"id": "ecosystem-services-g9", "domain": "LIVING_THINGS", "topic": "ecosystem services", "grades": [9, 10], "terms": ["ecosystem services", "serbisyong likas", "ecosystem services humans", "benepisyong mula sa kalikasan", "malinis na hangin tubig", "pollination decomposition climate", "serbisyo sa ekosistema", "kahimuanan gikan sa kinaiyahan", "clean air water pollination", "natural benefits", "biodiversity benefits"], "fact": {"tl": "Ang mga malulusog na ekosistema ay nagbibigay sa tao ng mahahalagang serbisyo gaya ng malinis na hangin at tubig, pagpaparami ng pananim sa pamamagitan ng pollination, at pagbubulok ng basura.", "en": "Healthy ecosystems give people valuable services such as clean air and water, growing crops through pollination, and breaking down waste.", "bis": "Ang himsog nga mga ekosistema naghatag sa tawo ug bililhong serbisyo sama sa limpyo nga hangin ug tubig, pagpadaghan sa pananom pinaagi sa pollination, ug pagdunot sa basura."}, "source": "NRC LS2 / LS4.D (ecosystem services, biodiversity benefits)", "generator": "claude-workflow", "reviewed": false},
  {"id": "all-food-traces-to-sun-g8", "domain": "LIVING_THINGS", "topic": "all food traces back to the sun", "grades": [8, 9], "terms": ["food traces to sun", "pagkain nagmumula sa araw", "energy from sunlight food", "lahat ng pagkain galing sa halaman", "all food from plants sun", "kusog gikan sa adlaw", "pagkaon gikan sa adlaw", "sunlight ultimate source", "araw ang pinagmulan ng enerhiya", "stored sunlight in food"], "fact": {"tl": "Halos lahat ng pagkain ay maaaring masundan pabalik sa mga halaman, at ang enerhiya rito ay galing sa liwanag ng araw na nakuha sa pamamagitan ng photosynthesis.", "en": "Almost all food can be traced back to plants, and the energy in it originally came from sunlight captured through photosynthesis.", "bis": "Halos tanang pagkaon masubay balik ngadto sa mga tanom, ug ang kusog niini orihinal nga naggikan sa kahayag sa adlaw nga nakuha pinaagi sa photosynthesis."}, "source": "NRC LS2.B (energy ultimately from sun); AAAS 5E", "generator": "claude-workflow", "reviewed": false},
  {"id": "em-wave-transverse-fields-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "electromagnetic waves as transverse waves of electric and magnetic fields", "grades": [9, 10], "terms": ["electromagnetic wave", "alon na electromagnetic", "balod nga electromagnetic", "transverse wave", "transverse na alon", "patindog nga alon", "electric field", "magnetic field", "electric at magnetic field", "elektrikong field", "magnetikong field", "patayong yanig", "changing fields", "nagbabagong field", "nagbag-o nga field", "transverse"], "fact": {"tl": "Ang electromagnetic wave ay isang transverse wave na binubuo ng nagbabagong electric field at magnetic field na magkasamang naglalakbay nang patayo sa direksyon ng paggalaw ng alon.", "en": "An electromagnetic wave is a transverse wave made of a changing electric field and magnetic field that travel together, vibrating at right angles to the wave's direction of motion.", "bis": "Ang electromagnetic wave usa ka transverse wave nga gilangkoban sa nagbag-o nga electric field ug magnetic field nga magkuyog nga nagbiyahe, nga nagkurog nga patindog sa direksyon sa paglihok sa balod."}, "source": "NRC PS4.B; AAAS 4F/H3", "generator": "claude-workflow", "reviewed": false},
  {"id": "em-wave-no-medium-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "electromagnetic waves need no medium", "grades": [9, 10], "terms": ["walang medium", "walang kailangang medium", "dili kinahanglan ug medium", "vacuum", "bakwum", "kawalan", "space", "kalawakan", "kawanangan", "sound needs medium", "tunog kailangan medium", "naglalakbay sa space", "mobiyahe sa wanang", "EM wave space", "araw liwanag space"], "fact": {"tl": "Hindi tulad ng tunog, ang electromagnetic wave ay hindi nangangailangan ng medium kaya nakakadaan ito sa vacuum ng kalawakan—kaya naaabot tayo ng liwanag ng araw at mga bituin.", "en": "Unlike sound, an electromagnetic wave needs no medium, so it can travel through the vacuum of space—that is why light from the Sun and stars can reach us.", "bis": "Dili sama sa tingog, ang electromagnetic wave dili magkinahanglan ug medium, busa makaagi kini sa vacuum sa kawanangan—mao nga ang kahayag sa adlaw ug mga bituon makaabot kanato."}, "source": "NRC PS4.B; AAAS 4F/H3c", "generator": "claude-workflow", "reviewed": false},
  {"id": "em-all-speed-of-light-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "all electromagnetic waves travel at the speed of light in vacuum", "grades": [9, 10], "terms": ["speed of light", "bilis ng liwanag", "katulin sa kahayag", "300000 km/s", "parehong bilis", "samang katulin", "vacuum", "bakwum", "lahat ng EM wave magkapareho bilis", "tanang EM wave pareho", "fastest", "pinakamabilis", "pinakapaspas", "c"], "fact": {"tl": "Lahat ng electromagnetic wave—mula radyo hanggang gamma—ay naglalakbay sa vacuum sa iisang bilis, ang bilis ng liwanag, na halos 300,000 kilometro kada segundo.", "en": "All electromagnetic waves—from radio to gamma—travel through a vacuum at the same speed, the speed of light, which is about 300,000 kilometers per second.", "bis": "Ang tanang electromagnetic wave—gikan sa radyo hangtod sa gamma—mobiyahe sa vacuum sa managsamang katulin, ang katulin sa kahayag, nga mga 300,000 ka kilometro kada segundo."}, "source": "NRC PS4.B; AAAS 4F/H3c", "generator": "claude-workflow", "reviewed": false},
  {"id": "em-spectrum-order-radio-to-gamma-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "order of the electromagnetic spectrum from radio to gamma", "grades": [9, 10], "terms": ["electromagnetic spectrum", "pagkakasunod-sunod", "han-ay sa spectrum", "radio", "radyo", "microwave", "mikrowave", "infrared", "visible light", "nakikitang liwanag", "makita nga kahayag", "ultraviolet", "UV", "x-ray", "gamma", "ayos ng spectrum", "sunod-sunod nga balod"], "fact": {"tl": "Ang electromagnetic spectrum, mula sa pinakamahabang alon hanggang pinakamaikli, ay nasa ganitong ayos: radio, microwave, infrared, nakikitang liwanag, ultraviolet, X-ray, at gamma.", "en": "The electromagnetic spectrum, from the longest waves to the shortest, runs in this order: radio, microwave, infrared, visible light, ultraviolet, X-ray, and gamma.", "bis": "Ang electromagnetic spectrum, gikan sa kinatas-ang balod hangtod sa kinamub-an, naa niini nga han-ay: radio, microwave, infrared, makita nga kahayag, ultraviolet, X-ray, ug gamma."}, "source": "AAAS 4F/M8, 4F/H3; NRC PS4.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "em-wavelength-frequency-inverse-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "wavelength and frequency are inversely related", "grades": [9, 10], "terms": ["wavelength", "haba ng alon", "gitas-on sa balod", "frequency", "dalas", "prekwensi", "kadasig", "mas mahaba mas mababa frequency", "mas taas frequency mas mubo wavelength", "inverse", "kabaligtaran", "shorter wavelength higher frequency", "mas maikli mas mataas dalas"], "fact": {"tl": "Dahil pare-pareho ang bilis ng lahat ng EM wave, mas maikli ang wavelength, mas mataas ang frequency nito; mas mahaba ang wavelength, mas mababa ang frequency.", "en": "Because all EM waves move at the same speed, the shorter the wavelength, the higher the frequency; the longer the wavelength, the lower the frequency.", "bis": "Tungod kay managsama ang katulin sa tanang EM wave, mas mubo ang wavelength, mas taas ang frequency niini; mas taas ang wavelength, mas ubos ang frequency."}, "source": "AAAS 4F/H6; NRC PS4.A grade-12 endpoint", "generator": "claude-workflow", "reviewed": false},
  {"id": "em-frequency-energy-relation-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "higher frequency electromagnetic waves carry more energy", "grades": [9, 10], "terms": ["energy", "enerhiya", "kusog", "higher frequency more energy", "mas mataas frequency mas malakas", "mas taas frequency mas kusog", "gamma most energy", "gamma pinakamalakas", "radio least energy", "radyo pinakamahina", "photon energy", "enerhiya sa balod", "lakas ng alon"], "fact": {"tl": "Mas mataas ang frequency ng isang EM wave, mas malaki ang dala nitong enerhiya—kaya ang gamma rays ang pinakamalakas at ang radio waves ang pinakamahina sa spectrum.", "en": "The higher an EM wave's frequency, the more energy it carries—so gamma rays are the most energetic and radio waves the least energetic in the spectrum.", "bis": "Mas taas ang frequency sa usa ka EM wave, mas dako ang kusog nga dala niini—busa ang gamma rays ang pinakakusgan ug ang radio waves ang pinakaluya sa spectrum."}, "source": "NRC PS4.B; AAAS 4E/M4 (light energy and frequency)", "generator": "claude-workflow", "reviewed": false},
  {"id": "em-accelerating-charge-source-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "electromagnetic waves are produced by accelerating electric charges", "grades": [9, 10], "terms": ["accelerating charge", "kumikilos na charge", "naglihok nga charge", "electric charge", "elektrikong karga", "pinagmulan ng EM wave", "gigikanan sa EM wave", "nababanggit na electron", "antenna", "naglalabas ng EM wave", "produce EM waves", "naghimo ug EM wave", "vibrating charges"], "fact": {"tl": "Nalilikha ang electromagnetic wave kapag may electric charge na binabago ang galaw o bilis nito, gaya ng mga umuugang electron sa antenna.", "en": "Electromagnetic waves are produced when an electric charge changes its motion or speeds up, such as electrons vibrating in an antenna.", "bis": "Ang electromagnetic wave mamugna kung adunay electric charge nga nag-usab sa paglihok o katulin niini, sama sa mga electron nga nagkurog sa antenna."}, "source": "AAAS 4F/H3a", "generator": "claude-workflow", "reviewed": false},
  {"id": "radio-waves-communication-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "radio waves and their uses in communication", "grades": [9, 10], "terms": ["radio waves", "radyo alon", "balod sa radyo", "longest wavelength", "pinakamahabang wavelength", "kinatas-ang wavelength", "broadcast", "radio television", "radyo telebisyon", "cellphone signal", "senyas ng telepono", "wifi", "komunikasyon", "communication", "transmission"], "fact": {"tl": "Ang radio waves ang may pinakamahabang wavelength sa spectrum at ginagamit para magpadala ng tunog at impormasyon sa radyo, telebisyon, cellphone, at Wi-Fi.", "en": "Radio waves have the longest wavelengths in the spectrum and are used to carry sound and information for radio, television, cellphones, and Wi-Fi.", "bis": "Ang radio waves adunay kinatas-ang wavelength sa spectrum ug gigamit aron magpadala ug tingog ug impormasyon sa radyo, telebisyon, cellphone, ug Wi-Fi."}, "source": "NRC PS4.C; AAAS 4F/M8", "generator": "claude-workflow", "reviewed": false},
  {"id": "microwaves-uses-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "microwaves and their uses", "grades": [9, 10], "terms": ["microwave", "mikrowave", "microwave oven", "mikrowave oven", "nagpapainit ng pagkain", "nagpainit sa pagkaon", "tubig sa pagkaon", "water molecules", "cellphone signal", "senyas sa cellphone", "radar", "satellite", "satelayt", "nagluluto", "naglutoq"], "fact": {"tl": "Ang microwave ay may mas maikling wavelength kaysa radio at ginagamit sa cellphone signal, radar, at sa microwave oven na nagpapainit sa pagkain sa pamamagitan ng pagpapagalaw sa mga molekula ng tubig.", "en": "Microwaves have a shorter wavelength than radio waves and are used for cellphone signals, radar, and microwave ovens, which heat food by making its water molecules move.", "bis": "Ang microwave adunay mas mubo nga wavelength kaysa radio ug gigamit sa cellphone signal, radar, ug sa microwave oven nga nagpainit sa pagkaon pinaagi sa pagpalihok sa mga molekula sa tubig niini."}, "source": "NRC PS4.C; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "infrared-heat-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "infrared radiation and heat", "grades": [9, 10], "terms": ["infrared", "infrared radiation", "init", "thermal", "heat", "radiant heat", "nararamdamang init", "kainit", "remote control", "remote ng TV", "remote sa TV", "thermal camera", "night vision", "warm objects emit", "maiinit na bagay", "init nga balod"], "fact": {"tl": "Ang infrared ay ang radiation na nadarama natin bilang init mula sa mainit na bagay, at ginagamit ito sa remote control, thermal camera, at night-vision na kagamitan.", "en": "Infrared is the radiation we feel as heat from warm objects, and it is used in remote controls, thermal cameras, and night-vision equipment.", "bis": "Ang infrared mao ang radiation nga atong gibati nga kainit gikan sa mainit nga butang, ug gigamit kini sa remote control, thermal camera, ug night-vision nga kagamitan."}, "source": "NRC PS4.B; AAAS 4E/M3 (thermal energy radiated)", "generator": "claude-workflow", "reviewed": false},
  {"id": "visible-light-spectrum-narrow-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "visible light is a narrow band of the spectrum", "grades": [9, 10], "terms": ["visible light", "nakikitang liwanag", "makita nga kahayag", "narrow band", "maliit na bahagi", "gamay nga bahin", "human eye", "mata ng tao", "mata sa tawo", "kulay", "color", "kolor", "violet to red", "lila hanggang pula", "tipik sa spectrum", "rainbow"], "fact": {"tl": "Ang nakikitang liwanag ay napakaliit na bahagi lamang ng buong electromagnetic spectrum—ito lang ang saklaw ng wavelength na kaya makita ng mata ng tao, mula lila hanggang pula.", "en": "Visible light is only a very narrow band of the whole electromagnetic spectrum—it is the only range of wavelengths the human eye can see, from violet to red.", "bis": "Ang makita nga kahayag usa lamang ka gamay kaayo nga bahin sa tibuok electromagnetic spectrum—mao ra kini ang gilapdon sa wavelength nga makita sa mata sa tawo, gikan sa lila hangtod sa pula."}, "source": "NRC PS4.B; AAAS 4F/M5", "generator": "claude-workflow", "reviewed": false},
  {"id": "visible-color-wavelength-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "color depends on wavelength of visible light", "grades": [9, 10], "terms": ["color", "kulay", "kolor", "wavelength", "haba ng alon", "gitas-on sa balod", "pula", "red longest", "violet shortest", "lila pinakamaikli", "asul", "blue", "kolor depende sa wavelength", "differences in wavelength", "kaibahan sa wavelength", "spektrum sa kolor"], "fact": {"tl": "Ang iba't ibang kulay na nakikita natin ay nagmumula sa pagkakaiba ng wavelength ng liwanag: ang pula ang may pinakamahabang wavelength at ang lila ang pinakamaikli.", "en": "The different colors we see come from differences in the wavelength of light: red has the longest wavelength and violet the shortest.", "bis": "Ang nagkalainlain nga kolor nga atong makita gikan sa kalainan sa wavelength sa kahayag: ang pula adunay kinatas-ang wavelength ug ang lila ang kinamub-an."}, "source": "AAAS 4F/M5; NRC PS4.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "ultraviolet-rays-uses-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "ultraviolet rays uses", "grades": [9, 10], "terms": ["ultraviolet", "UV", "ultraviolet rays", "UV rays", "araw", "sun", "adlaw", "vitamin D", "bitamina D", "sterilize", "pagdisimpekta", "pag-sterilize", "UV light tubig", "fluorescent", "shorter than visible", "mas maikli sa liwanag", "mas mubo sa kahayag"], "fact": {"tl": "Ang ultraviolet (UV) ay may mas maikling wavelength at mas mataas na enerhiya kaysa nakikitang liwanag; tumutulong ito sa balat para gumawa ng vitamin D at ginagamit para pumatay ng mikrobyo sa tubig at kagamitan.", "en": "Ultraviolet (UV) has a shorter wavelength and higher energy than visible light; it helps the skin make vitamin D and is used to kill germs in water and equipment.", "bis": "Ang ultraviolet (UV) adunay mas mubo nga wavelength ug mas taas nga kusog kaysa makita nga kahayag; makatabang kini sa panit aron makahimo ug vitamin D ug gigamit aron mopatay sa mikrobyo sa tubig ug kagamitan."}, "source": "NRC PS4.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "uv-skin-danger-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "dangers of ultraviolet radiation to skin and eyes", "grades": [9, 10], "terms": ["ultraviolet danger", "UV peligro", "UV katalagman", "sunburn", "pagkapaso ng balat", "napaso nga panit", "skin cancer", "cancer sa balat", "kanser sa panit", "delikado sa mata", "harms eyes", "ionize", "nakakasira ng cells", "makadaot sa selula", "sunscreen", "proteksyon sa araw"], "fact": {"tl": "Dahil mas mataas ang enerhiya ng ultraviolet, kaya nitong sirain ang mga cells ng balat—nagdudulot ito ng sunburn at, sa sobrang pagkalantad, ng skin cancer, kaya mahalaga ang sunscreen at lilim.", "en": "Because ultraviolet carries higher energy, it can damage skin cells—causing sunburn and, with too much exposure, skin cancer, which is why sunscreen and shade matter.", "bis": "Tungod kay mas taas ang kusog sa ultraviolet, makaguba kini sa mga selula sa panit—maoy hinungdan sa sunburn ug, kung sobra ang pagkaladlad, kanser sa panit, mao nga importante ang sunscreen ug landong."}, "source": "NRC PS4.B (short-wavelength radiation ionizes, damages cells); AAAS 4F/H6", "generator": "claude-workflow", "reviewed": false},
  {"id": "xrays-medical-imaging-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "X-rays and medical imaging", "grades": [9, 10], "terms": ["x-ray", "x-rays", "eksrey", "medical imaging", "larawan ng buto", "litrato sa bukog", "bone", "buto", "bukog", "soft tissue", "lumalampas sa laman", "molabang sa unod", "denser matter absorbs", "pasilan ng buto", "doctor x-ray", "fracture bali ng buto", "x-ray litrato"], "fact": {"tl": "Ang X-ray ay nakakadaan sa malambot na laman ngunit nasisipsip ng mas siksik na buto, kaya ginagamit ito ng doktor para kumuha ng larawan ng mga buto sa loob ng katawan.", "en": "X-rays pass through soft body tissue but are absorbed by denser bone, so doctors use them to take images of the bones inside the body.", "bis": "Ang X-ray makaagi sa humok nga unod apan masuhop sa mas baga nga bukog, mao nga gigamit kini sa doktor aron makakuha ug litrato sa mga bukog sulod sa lawas."}, "source": "NRC PS4.B; NRC PS4.C (medical imaging)", "generator": "claude-workflow", "reviewed": false},
  {"id": "xrays-danger-ionizing-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "dangers of X-rays and ionizing radiation", "grades": [9, 10], "terms": ["x-ray danger", "x-ray peligro", "x-ray katalagman", "ionizing radiation", "ionizing", "nakakasira ng cells", "makadaot sa selula", "high energy", "mataas na enerhiya", "taas nga kusog", "lead apron", "proteksyon sa x-ray", "sobrang dami delikado", "knock out electron", "nagtatanggal ng electron"], "fact": {"tl": "Ang X-ray ay may mataas na enerhiya na kayang mag-ionize ng atoms at makasira ng mga buhay na cells, kaya kontrolado ang dami nito at gumagamit ng panangga gaya ng lead apron sa ospital.", "en": "X-rays carry high energy that can ionize atoms and damage living cells, so the amount used is controlled and shields like lead aprons are worn in hospitals.", "bis": "Ang X-ray adunay taas nga kusog nga makahimo ug ionize sa atoms ug makaguba sa buhi nga mga selula, mao nga kontrolado ang gidaghanon niini ug gigamit ang panagang sama sa lead apron sa ospital."}, "source": "NRC PS4.B (ultraviolet, X-rays, gamma rays ionize atoms, damage cells)", "generator": "claude-workflow", "reviewed": false},
  {"id": "gamma-rays-properties-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "gamma rays highest energy radiation", "grades": [9, 10], "terms": ["gamma rays", "gamma", "highest energy", "pinakamataas na enerhiya", "kinatas-ang kusog", "shortest wavelength", "pinakamaikling wavelength", "kinamub-ang wavelength", "nuclear", "nukleyar", "radioactive", "radyoaktibo", "cancer treatment", "gamot sa kanser", "sterilize equipment", "sterilize sa kagamitan", "most penetrating", "tumatagos"], "fact": {"tl": "Ang gamma rays ang may pinakamaikling wavelength at pinakamataas na enerhiya sa spectrum; nagmumula ito sa mga nuclear na pagbabago at ginagamit sa paggamot ng cancer at pag-sterilize ng kagamitan sa ospital.", "en": "Gamma rays have the shortest wavelength and highest energy in the spectrum; they come from nuclear changes and are used to treat cancer and sterilize hospital equipment.", "bis": "Ang gamma rays adunay kinamub-ang wavelength ug kinatas-ang kusog sa spectrum; gikan kini sa mga nuclear nga pagbag-o ug gigamit sa pagtambal sa kanser ug pag-sterilize sa kagamitan sa ospital."}, "source": "NRC PS4.B; NRC PS1.C (gamma from nuclear transitions)", "generator": "claude-workflow", "reviewed": false},
  {"id": "gamma-from-nuclear-decay-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "gamma rays from radioactive nuclei", "grades": [9, 10], "terms": ["gamma rays", "gamma", "radioactive", "radyoaktibo", "radioactive decay", "pagkabulok ng nucleus", "pagkadunot sa nucleus", "nucleus", "nukleus", "unstable nucleus", "di-matatag na nucleus", "dili lig-on nga nucleus", "isotope", "isotopo", "photon", "nuclear transition", "naglalabas ng gamma"], "fact": {"tl": "Ang gamma rays ay inilalabas ng mga di-matatag na nucleus ng radioactive na atoms habang nagbabago ang mga ito, at bawat isotope ay may sariling natatanging gamma wavelength.", "en": "Gamma rays are released by the unstable nuclei of radioactive atoms as they change, and each isotope gives off its own distinctive gamma wavelength.", "bis": "Ang gamma rays gibuga sa dili lig-on nga nucleus sa radioactive nga atoms samtang nagbag-o kini, ug ang matag isotope adunay kaugalingong talagsaong gamma wavelength."}, "source": "NRC PS4.B; AAAS 4D/H4 (radioactive decay emits radiation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "em-ionizing-vs-nonionizing-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "ionizing versus non-ionizing electromagnetic radiation", "grades": [9, 10], "terms": ["ionizing radiation", "ionizing", "nakakasira", "makadaot", "non-ionizing", "ligtas na radiation", "luwas nga radiation", "ultraviolet x-ray gamma", "UV X-ray gamma delikado", "radio microwave infrared ligtas", "knock out electrons", "nagtatanggal ng electron", "shorter wavelength dangerous", "mas maikli mas delikado"], "fact": {"tl": "Ang mga EM wave na may maiikling wavelength—ultraviolet, X-ray, at gamma—ay ionizing dahil kaya nilang magtanggal ng electron at makasira ng cells, habang ang radio, microwave, at infrared ay non-ionizing at mas ligtas.", "en": "EM waves with short wavelengths—ultraviolet, X-rays, and gamma—are ionizing because they can knock out electrons and damage cells, while radio, microwave, and infrared are non-ionizing and safer.", "bis": "Ang mga EM wave nga mubo ang wavelength—ultraviolet, X-ray, ug gamma—mga ionizing kay makahimo silag tangtang sa electron ug makaguba sa selula, samtang ang radio, microwave, ug infrared mga non-ionizing ug mas luwas."}, "source": "NRC PS4.B (short-wavelength radiation ionizes atoms, damages cells)", "generator": "claude-workflow", "reviewed": false},
  {"id": "em-absorbed-as-heat-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "longer-wavelength radiation absorbed as heat", "grades": [9, 10], "terms": ["absorbed as heat", "nagiging init", "mahimong kainit", "thermal energy", "thermal", "init", "infrared init", "longer wavelength heat", "mahabang alon init", "taas nga balod kainit", "absorb", "sinisipsip", "gisuhop", "warming", "pagpainit", "converted to heat"], "fact": {"tl": "Kapag nasisipsip ng bagay ang liwanag o mas mahahabang EM wave gaya ng infrared, karaniwang nagiging init (thermal energy) ito, kaya umiinit ang bagay sa ilalim ng araw.", "en": "When an object absorbs light or longer EM waves like infrared, the energy usually turns into heat (thermal energy), which is why objects warm up in the sun.", "bis": "Kung masuhop sa usa ka butang ang kahayag o ang mas tag-as nga EM wave sama sa infrared, kasagaran mahimong kainit (thermal energy) kini, mao nga moinit ang mga butang ilalom sa adlaw."}, "source": "NRC PS4.B grade-12 endpoint; AAAS 4E/M6", "generator": "claude-workflow", "reviewed": false},
  {"id": "em-photon-particle-model-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "light as wave and as particle (photon)", "grades": [9, 10], "terms": ["photon", "potong", "particle of light", "tipik ng liwanag", "tipik sa kahayag", "wave and particle", "alon at partikulo", "balod ug partikulo", "wave-particle", "dual model", "dalawang modelo", "duha ka modelo", "quantum", "packet of energy", "tibuok kahayag", "particle model"], "fact": {"tl": "Ang liwanag at ibang EM radiation ay maaaring iguhit bilang alon o bilang maliliit na pakete ng enerhiya na tinatawag na photon; magkasamang ginagamit ang dalawang modelong ito para ipaliwanag ang kilos ng liwanag.", "en": "Light and other EM radiation can be described as a wave or as tiny packets of energy called photons; both models together are used to explain how light behaves.", "bis": "Ang kahayag ug uban pang EM radiation mahimong ihulagway isip balod o isip gagmayng pakete sa kusog nga gitawag ug photon; gigamit ang duha ka modelo aron ipasabot ang lihok sa kahayag."}, "source": "NRC PS4.B grade-12 endpoint (wave and particle models)", "generator": "claude-workflow", "reviewed": false},
  {"id": "em-spectral-lines-elements-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "elements emit characteristic frequencies of light", "grades": [9, 10], "terms": ["spectral lines", "spectral line", "linya ng spectrum", "linya sa spectrum", "characteristic frequency", "katangiang frequency", "talagsaong frequency", "element", "elemento", "fingerprint", "tatak ng elemento", "atom emits light", "nagliliwanag na atom", "identify element", "kilalanin ang elemento", "stars composition"], "fact": {"tl": "Bawat elemento ay naglalabas at sumisipsip ng sarili nitong natatanging mga frequency ng liwanag, kaya kayang tukuyin ng mga siyentipiko kung anong elemento ang nasa isang bagay—pati sa malalayong bituin.", "en": "Each element emits and absorbs its own distinctive frequencies of light, so scientists can identify which element is present in a sample—even in faraway stars.", "bis": "Ang matag elemento mobuga ug mosuhop sa kaugalingong talagsaong mga frequency sa kahayag, mao nga matino sa mga siyentista kung unsang elemento ang anaa sa usa ka butang—bisan sa layong mga bituon."}, "source": "NRC PS4.B (atoms emit characteristic frequencies; spectral lines)", "generator": "claude-workflow", "reviewed": false},
  {"id": "em-thermal-spectrum-temperature-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "hot objects emit a spectrum depending on temperature", "grades": [9, 10], "terms": ["hot object emits", "mainit na bagay naglalabas", "init nga butang mobuga", "temperature", "temperatura", "glowing red hot", "pulang baga", "namula sa kainit", "thermal radiation", "spectrum depends temperature", "mas mainit mas maliwanag", "white hot", "metal heated glows", "araw nagliliwanag"], "fact": {"tl": "Anumang bagay ay naglalabas ng spectrum ng EM radiation ayon sa temperatura nito—kaya ang mainit na metal ay namumula at ang mas mainit pa ay nagiging puti ang ningning.", "en": "Any object gives off a spectrum of EM radiation that depends on its temperature—so hot metal glows red, and even hotter objects glow white.", "bis": "Ang bisan unsang butang mobuga ug spectrum sa EM radiation depende sa temperatura niini—mao nga ang init nga metal mopula, ug ang mas init pa mahimong puti ang sidlak."}, "source": "NRC PS4.B (object emits spectrum depending on temperature)", "generator": "claude-workflow", "reviewed": false},
  {"id": "em-refraction-wavelength-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "wave behaviors of light depend on wavelength", "grades": [9, 10], "terms": ["refraction", "pagbaluktot ng liwanag", "pagliko sa kahayag", "reflection", "pagbalik ng liwanag", "pagbanaag", "absorbed", "sinisipsip", "gisuhop", "prism", "prisma", "bumabagsak na wavelength", "depende sa wavelength", "bends differently", "magkaibang baluktot", "rainbow prism"], "fact": {"tl": "Tulad ng anumang alon, ang liwanag ay maaaring ibalik (reflect), ibaluktot (refract), o sipsipin sa hangganan ng dalawang materyal, at ang epekto ay nakadepende sa wavelength—kaya hinahati ng prisma ang puting liwanag sa mga kulay.", "en": "Like any wave, light can be reflected, refracted (bent), or absorbed at the boundary between two materials, and the effect depends on wavelength—so a prism splits white light into colors.", "bis": "Sama sa bisan unsang balod, ang kahayag mahimong ibalik (reflect), ibawog (refract), o suhopon sa utlanan sa duha ka materyal, ug ang epekto nagdepende sa wavelength—mao nga ang prisma magbahin sa puting kahayag ngadto sa mga kolor."}, "source": "NRC PS4.B (reflect, refract, absorb; depends on wavelength); AAAS 4F/H6", "generator": "claude-workflow", "reviewed": false},
  {"id": "em-telescopes-multiwave-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "telescopes detect different parts of the spectrum", "grades": [9, 10], "terms": ["telescope", "teleskopyo", "radio telescope", "x-ray telescope", "x-ray na teleskopyo", "iba't ibang spectrum", "nagkalainlaing spectrum", "astronomy", "astronomiya", "pag-aaral ng bituin", "pagtuon sa bituon", "invisible light", "di-nakikitang liwanag", "dili makita nga kahayag", "detect waves", "universe study"], "fact": {"tl": "Gumagamit ang mga siyentipiko ng iba't ibang teleskopyo—tulad ng radio at X-ray telescope—para makita ang mga bahagi ng spectrum na hindi kayang makita ng mata, kaya mas marami silang nalalaman tungkol sa uniberso.", "en": "Scientists use different telescopes—such as radio and X-ray telescopes—to detect parts of the spectrum the eye cannot see, letting them learn more about the universe.", "bis": "Gigamit sa mga siyentista ang nagkalainlaing teleskopyo—sama sa radio ug X-ray telescope—aron makita ang mga bahin sa spectrum nga dili makita sa mata, busa mas daghan silag nahibaw-an bahin sa uniberso."}, "source": "AAAS 4A/H3; NRC PS4.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "em-uses-summary-by-band-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "modern technology uses different bands of the spectrum", "grades": [9, 10], "terms": ["uses of spectrum", "gamit ng spectrum", "gamit sa spectrum", "teknolohiya", "technology", "radio komunikasyon", "infrared init", "x-ray buto", "gamma kanser", "iba't ibang gamit", "nagkalainlaing gamit", "communication imaging", "bawat band may gamit", "matag band gamit", "applications"], "fact": {"tl": "Bawat bahagi ng spectrum ay may sariling gamit: radio at microwave para sa komunikasyon, infrared para sa init at remote, visible light para makakita, ultraviolet para mag-sterilize, at X-ray at gamma para sa medisina.", "en": "Each part of the spectrum has its own uses: radio and microwave for communication, infrared for heat and remotes, visible light for seeing, ultraviolet to sterilize, and X-ray and gamma for medicine.", "bis": "Ang matag bahin sa spectrum adunay kaugalingong gamit: radio ug microwave para sa komunikasyon, infrared para sa kainit ug remote, makita nga kahayag para makakita, ultraviolet aron mag-sterilize, ug X-ray ug gamma para sa medisina."}, "source": "NRC PS4.C; AAAS 4F/M8", "generator": "claude-workflow", "reviewed": false},
  {"id": "em-spectrum-continuous-overlap-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "the electromagnetic spectrum is continuous", "grades": [9, 10], "terms": ["continuous spectrum", "tuloy-tuloy na spectrum", "padayon nga spectrum", "walang hangganan na guhit", "walay klarong utlanan", "bands overlap", "magkadikit na band", "magtapad nga band", "isang spectrum", "usa lang ka spectrum", "same kind of wave", "parehong uri ng alon", "managsamang klase nga balod", "smooth range"], "fact": {"tl": "Lahat ng EM wave ay iisang uri lamang ng alon at bahagi ng iisang tuloy-tuloy na spectrum; ang mga pangalan gaya ng infrared o ultraviolet ay mga bahagi lang na unti-unting nagsasanib, hindi magkakahiwalay na bagay.", "en": "All EM waves are the same kind of wave and part of one continuous spectrum; names like infrared or ultraviolet are just bands that blend into each other, not separate things.", "bis": "Ang tanang EM wave usa lang ka klase sa balod ug bahin sa usa ka padayon nga spectrum; ang mga ngalan sama sa infrared o ultraviolet mga bahin lang nga hinay-hinayng nagsagol, dili managlahing butang."}, "source": "AAAS 4F/M8, 4F/H3; NRC PS4.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "current-is-flow-rate-of-charge-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "electric current as rate of charge flow", "grades": [9, 10], "terms": ["agos ng kuryente", "elektrisidad", "daloy ng singil", "electron", "elektron", "ampere", "amperes", "current", "elektrik nga sulog", "agos sa kuryente", "dagan sa elektron", "singil", "charge", "rate of flow", "koryente"], "fact": {"tl": "Ang electric current ay ang bilis ng daloy ng mga sisingiling electron sa isang konduktor, at sinusukat ito sa yunit na ampere.", "en": "Electric current is the rate at which electric charge (electrons) flows through a conductor, and it is measured in units called amperes.", "bis": "Ang electric current mao ang katulin sa pag-agos sa mga nagdalag-charge nga electron sa usa ka konduktor, ug sukdon kini sa yunit nga ampere."}, "source": "AAAS 4G/M4; NRC PS3.A energy transfer by electric currents", "generator": "claude-workflow", "reviewed": false},
  {"id": "conventional-current-direction-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "conventional current vs electron flow direction", "grades": [9, 10], "terms": ["direksyon ng daloy", "conventional current", "positibo", "negatibo", "electron flow", "agos ng electron", "patong sa kuryente", "direksiyon sa current", "positibo nga terminal", "negatibo nga terminal", "kombensiyonal nga sulog", "direction of current"], "fact": {"tl": "Sa kombensiyon, ang current ay itinuturing na dumadaloy mula sa positibong terminal patungo sa negatibo, kahit ang mga electron mismo ay gumagalaw sa kabaligtarang direksyon.", "en": "By convention, current is treated as flowing from the positive terminal to the negative terminal, even though the electrons themselves actually move in the opposite direction.", "bis": "Sumala sa kombensiyon, giila ang current nga nag-agos gikan sa positibo nga terminal padulong sa negatibo, bisan tuod ang mga electron mismo molihok sa atbang nga direksiyon."}, "source": "AAAS 4G/M4; physics consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "voltage-is-electrical-push-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "voltage as electrical push or energy per charge", "grades": [9, 10], "terms": ["boltahe", "voltage", "boltas", "volt", "volts", "lakas ng tulak", "enerhiya kada singil", "push sa kuryente", "boltahe sa baterya", "potential difference", "diperensiya sa potensyal", "tulak ng kuryente", "kusog sa current"], "fact": {"tl": "Ang boltahe ang nagbibigay ng \"tulak\" na nagpapagalaw sa mga electron sa isang sirkito, at sinusukat ito sa volt.", "en": "Voltage provides the electrical \"push\" that drives electrons around a circuit, and it is measured in volts.", "bis": "Ang boltahe maoy naghatag sa \"tulak\" nga nagpalihok sa mga electron sa usa ka sirkito, ug sukdon kini sa volt."}, "source": "AAAS 4E/M2; physics consensus on potential difference", "generator": "claude-workflow", "reviewed": false},
  {"id": "resistance-opposes-current-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "electrical resistance opposes current", "grades": [9, 10], "terms": ["resistance", "resistensiya", "ohm", "ohms", "hadlang sa kuryente", "pagpigil sa daloy", "babag sa current", "oposisyon", "resistor", "hadlang", "pumipigil sa daloy", "kontra sa current"], "fact": {"tl": "Ang resistance ay ang pagpigil ng isang materyal sa daloy ng kuryente, at sinusukat ito sa yunit na ohm.", "en": "Resistance is how much a material opposes the flow of electric current, and it is measured in units called ohms.", "bis": "Ang resistance mao ang pagpugong sa usa ka materyal sa pag-agos sa kuryente, ug sukdon kini sa yunit nga ohm."}, "source": "physics consensus; AAAS 4D/M9 materials respond differently to current", "generator": "claude-workflow", "reviewed": false},
  {"id": "ohms-law-qualitative-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "Ohm's law qualitative relationship", "grades": [9, 10], "terms": ["batas ni Ohm", "Ohm's law", "ley ni Ohm", "boltahe current resistance", "mas mataas boltahe", "mas mataas resistensiya", "relasyon", "kung taas ang boltahe", "kung taas ang resistance", "voltage current resistance", "relasyon sa boltahe"], "fact": {"tl": "Ayon sa batas ni Ohm, kapag mas mataas ang boltahe ay mas malakas ang current, ngunit kapag mas mataas ang resistance ay mas mahina ang current.", "en": "Ohm's law says that a higher voltage produces a larger current, while a higher resistance produces a smaller current.", "bis": "Sumala sa balaod ni Ohm, kung mas taas ang boltahe mas kusog ang current, apan kung mas taas ang resistance mas huyang ang current."}, "source": "physics consensus (Ohm's law, qualitative)", "generator": "claude-workflow", "reviewed": false},
  {"id": "longer-thinner-wire-more-resistance-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "wire length and thickness affect resistance", "grades": [9, 10], "terms": ["haba ng wire", "kapal ng wire", "manipis na wire", "mahabang wire", "resistensiya ng wire", "gitas-on sa wire", "kabaga sa wire", "nipis nga wire", "taas nga wire", "wire thickness", "thin wire", "long wire", "manipis", "mas makapal"], "fact": {"tl": "Ang isang mahaba at manipis na wire ay may mas mataas na resistance kaysa sa isang maikli at makapal na wire na gawa sa parehong metal.", "en": "A long, thin wire has more resistance than a short, thick wire made of the same metal.", "bis": "Ang taas ug nipis nga wire mas dako ug resistance kaysa mubo ug baga nga wire nga hinimo sa samang metal."}, "source": "physics consensus on resistance and conductor geometry", "generator": "claude-workflow", "reviewed": false},
  {"id": "current-heats-resistive-wire-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "heating effect of current", "grades": [9, 10], "terms": ["init sa kuryente", "heating effect", "kuryente nagpapainit", "umiinit na wire", "resistance init", "heating coil", "init nga epekto", "nag-init nga wire", "heater", "plantsa", "toaster", "umiinit", "nagpapainit"], "fact": {"tl": "Kapag dumaan ang current sa isang materyal na may resistance, bahagi ng enerhiya ay nagiging init, kaya umiinit ang mga heater, plantsa, at toaster.", "en": "When current passes through a material with resistance, some of the energy turns into heat, which is why heaters, irons, and toasters warm up.", "bis": "Kung moagi ang current sa usa ka materyal nga adunay resistance, ang ubang enerhiya mahimong init, mao nga moinit ang mga heater, plantsa, ug toaster."}, "source": "physics consensus; AAAS 4E/M4 electrical energy in a circuit", "generator": "claude-workflow", "reviewed": false},
  {"id": "series-resistance-adds-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "resistance adds in a series circuit", "grades": [9, 10], "terms": ["series circuit", "magkakasunod na resistor", "dagdag na resistance", "sunod-sunod", "mas mahina ang current", "serye nga sirkito", "nagsunod nga resistor", "dugang resistance", "total resistance", "kabuuang resistance", "nadugangan ang resistance"], "fact": {"tl": "Sa isang series circuit, nagdaragdag ang resistance ng bawat bahagi, kaya mas mataas ang kabuuang resistance at mas mahina ang current.", "en": "In a series circuit the resistances of the parts add up, so the total resistance is higher and the current is smaller.", "bis": "Sa usa ka series circuit, magdugang ang resistance sa matag bahin, mao nga mas taas ang kinatibuk-ang resistance ug mas huyang ang current."}, "source": "physics consensus on series circuits", "generator": "claude-workflow", "reviewed": false},
  {"id": "series-voltage-shared-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "voltage is shared in a series circuit", "grades": [9, 10], "terms": ["boltahe hinati", "series circuit", "magkasunod", "hinati-hinati ang boltahe", "voltage drop", "serye nga sirkito", "gibahin nga boltahe", "shared voltage", "pinaghahati ang boltahe", "mas malabo ang ilaw", "dimmer bulbs"], "fact": {"tl": "Sa isang series circuit, pinaghahati ng mga bumbilya o resistor ang boltahe ng baterya, kaya kapag dumami sila ay mas lumalabo ang bawat ilaw.", "en": "In a series circuit the bulbs or resistors share the battery's voltage, so adding more of them makes each light dimmer.", "bis": "Sa usa ka series circuit, bahinon sa mga bombilya o resistor ang boltahe sa baterya, mao nga kung modaghan sila mas mongitngit ang matag suga."}, "source": "physics consensus on series circuits", "generator": "claude-workflow", "reviewed": false},
  {"id": "parallel-same-voltage-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "each branch in parallel gets full voltage", "grades": [9, 10], "terms": ["parallel circuit", "magkaparehong boltahe", "buong boltahe", "bawat sanga", "parehas nga boltahe", "parallel nga sirkito", "tibuok boltahe", "magkapareho ang liwanag", "same brightness", "buo ang boltahe", "kada sanga"], "fact": {"tl": "Sa isang parallel circuit, bawat sanga ay tumatanggap ng buong boltahe ng baterya, kaya ang mga bumbilya ay nananatiling maliwanag kahit dumami pa sila.", "en": "In a parallel circuit each branch receives the full battery voltage, so the bulbs stay bright even when more of them are added.", "bis": "Sa usa ka parallel circuit, ang matag sanga makadawat sa tibuok boltahe sa baterya, mao nga magpabilin nga hayag ang mga bombilya bisan modaghan pa sila."}, "source": "physics consensus on parallel circuits", "generator": "claude-workflow", "reviewed": false},
  {"id": "parallel-current-splits-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "current splits among parallel branches", "grades": [9, 10], "terms": ["paghahati ng current", "parallel circuit", "nahahati ang daloy", "bawat sanga", "current splits", "branches", "nabahin nga current", "parallel nga sanga", "naghiwa-hiwalay na daloy", "gibahin nga sulog", "naghati ang kuryente"], "fact": {"tl": "Sa isang parallel circuit, naghahati-hati ang current sa iba't ibang sanga, kaya mas malaking kabuuang current ang kinukuha mula sa baterya.", "en": "In a parallel circuit the current splits among the different branches, so a larger total current is drawn from the battery.", "bis": "Sa usa ka parallel circuit, mabahin ang current ngadto sa lain-laing sanga, mao nga mas dako nga kinatibuk-ang current ang kuhaon gikan sa baterya."}, "source": "physics consensus on parallel circuits", "generator": "claude-workflow", "reviewed": false},
  {"id": "parallel-lower-total-resistance-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "parallel circuit has lower total resistance", "grades": [9, 10], "terms": ["mas mababang resistance", "parallel circuit", "dagdag na daanan", "mas maraming landas", "lower resistance", "ubos nga resistance", "dugang agianan", "mas daghan agianan", "more paths", "nabawasan ang resistance", "mas gamay ang resistance"], "fact": {"tl": "Ang pagdaragdag ng mga sanga sa isang parallel circuit ay nagbibigay ng mas maraming landas para sa current, kaya bumababa ang kabuuang resistance.", "en": "Adding more branches to a parallel circuit gives the current more paths to flow, so the total resistance goes down.", "bis": "Ang pagdugang ug mga sanga sa usa ka parallel circuit naghatag ug mas daghang agianan alang sa current, mao nga mokunhod ang kinatibuk-ang resistance."}, "source": "physics consensus on parallel circuits", "generator": "claude-workflow", "reviewed": false},
  {"id": "homes-wired-in-parallel-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "house wiring uses parallel circuits", "grades": [9, 10], "terms": ["kableng pambahay", "parallel ang bahay", "wiring sa bahay", "house wiring", "magkahiwalay na switch", "kableng sa balay", "parallel nga balay", "independent appliances", "hiwalay na gamit", "magamit nga mag-isa", "kuryente sa bahay"], "fact": {"tl": "Ang mga bahay ay nakakable sa parallel circuit upang ang bawat ilaw at kagamitan ay maaaring buksan o patayin nang hiwalay nang hindi naaapektuhan ang iba.", "en": "Houses are wired in parallel circuits so that each light and appliance can be switched on or off separately without affecting the others.", "bis": "Ang mga balay gikable sa parallel circuit aron ang matag suga ug gamit mahimong sindihan o palongon nga bulag nga dili maapektuhan ang uban."}, "source": "physics consensus; standard household wiring practice", "generator": "claude-workflow", "reviewed": false},
  {"id": "electrical-power-voltage-times-current-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "electrical power equals voltage times current", "grades": [9, 10], "terms": ["electrical power", "kuryenteng lakas", "watt", "watts", "boltahe times current", "lakas ng kuryente", "kusog sa kuryente", "watt sa gamit", "power rating", "bilis ng paggamit", "konsumo ng enerhiya", "gamit nga power"], "fact": {"tl": "Ang electrical power ay kung gaano kabilis ginagamit ng isang aparato ang enerhiya, at ito ay katumbas ng boltahe na pinarami sa current, na sinusukat sa watt.", "en": "Electrical power is how fast a device uses energy, and it equals the voltage multiplied by the current, measured in watts.", "bis": "Ang electrical power mao kung unsa ka paspas mogamit ug enerhiya ang usa ka galamiton, ug kini katumbas sa boltahe nga gipadaghan sa current, sukod sa watt."}, "source": "physics consensus (P = V x I)", "generator": "claude-workflow", "reviewed": false},
  {"id": "higher-wattage-uses-more-energy-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "higher wattage devices use more energy", "grades": [9, 10], "terms": ["mataas na watt", "wattage", "mas maraming kuryente", "high wattage", "konsumo", "taas nga watt", "mas daghang kuryente", "gastos sa kuryente", "appliance rating", "mabigat na gamit", "kumukonsumo", "mokonsumo"], "fact": {"tl": "Ang isang aparatong may mas mataas na watt rating ay kumukonsumo ng mas maraming enerhiya kada segundo, kaya mas mabilis tumaas ang kuryenteng gagamitin nito.", "en": "A device with a higher watt rating uses more energy each second, so it adds up your electricity use more quickly.", "bis": "Ang usa ka galamiton nga adunay mas taas nga watt rating mogamit ug mas daghang enerhiya kada segundo, mao nga mas paspas nga modaghan ang konsumo niini sa kuryente."}, "source": "physics consensus on electrical power and consumption", "generator": "claude-workflow", "reviewed": false},
  {"id": "electrical-energy-kilowatt-hour-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "electrical energy measured in kilowatt-hours", "grades": [9, 10], "terms": ["kilowatt-hour", "kWh", "kuryente sa metro", "electric bill", "enerhiya gamit oras", "konsumo ng kuryente", "kilowatt oras", "kuryenteng metro", "singil sa kuryente", "power times time", "enerhiya kada oras", "metro sa kuryente"], "fact": {"tl": "Ang enerhiyang ginagamit ng kuryente ay power na pinarami sa oras, kaya sinusukat ito sa kilowatt-hour (kWh) na siyang nakikita sa electric bill.", "en": "The energy used by electricity is power multiplied by time, so it is measured in kilowatt-hours (kWh), the unit you see on an electric bill.", "bis": "Ang enerhiya nga gigamit sa kuryente mao ang power nga gipadaghan sa oras, mao nga sukdon kini sa kilowatt-hour (kWh), ang yunit nga makita sa electric bill."}, "source": "physics consensus (energy = power x time)", "generator": "claude-workflow", "reviewed": false},
  {"id": "short-circuit-low-resistance-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "short circuit and dangerous large current", "grades": [9, 10], "terms": ["short circuit", "short", "mababang resistance", "malaking current", "sobrang init", "mubo nga sirkito", "ubos nga resistance", "dako nga current", "sunog", "nag-init", "sobrang daloy", "delikadong daloy", "nagdikit ang wire"], "fact": {"tl": "Ang short circuit ay nangyayari kapag may daanang halos walang resistance, kaya biglang lumalaki ang current at maaaring magdulot ng sobrang init o sunog.", "en": "A short circuit happens when current finds a path with almost no resistance, so it suddenly becomes very large and can cause overheating or fire.", "bis": "Ang short circuit mahitabo kung makakaplag ang current ug agianan nga halos walay resistance, mao nga kalit kini modako ug makahimo ug sobrang kainit o sunog."}, "source": "physics consensus; AAAS 4G/M4 complete loop / electrical safety", "generator": "claude-workflow", "reviewed": false},
  {"id": "fuse-melts-to-break-circuit-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "how a fuse works by melting", "grades": [9, 10], "terms": ["fuse", "piyus", "natutunaw na wire", "fuse natunaw", "pumuputol ng current", "natunaw nga wire", "fuse sa balay", "naputol ang sirkito", "melting wire", "pumuputol", "naputol", "fuse pumuputol", "proteksyon"], "fact": {"tl": "Ang isang fuse ay may manipis na wire na natutunaw kapag sobra-sobra ang current, kaya napuputol ang sirkito at naiiwasan ang sunog.", "en": "A fuse contains a thin wire that melts when too much current flows, which breaks the circuit and helps prevent a fire.", "bis": "Ang fuse adunay nipis nga wire nga matunaw kung sobra ang current nga moagi, mao nga maputol ang sirkito ug malikayan ang sunog."}, "source": "physics consensus on fuses; AAAS electrical safety", "generator": "claude-workflow", "reviewed": false},
  {"id": "circuit-breaker-resettable-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "circuit breaker is a resettable switch", "grades": [9, 10], "terms": ["circuit breaker", "breaker", "switch na bumabalik", "naiba-on ulit", "trip", "nag-trip", "automatic switch", "breaker sa balay", "mabalik-on", "resettable", "switch awtomatiko", "naghunong ang kuryente", "babalikan"], "fact": {"tl": "Ang circuit breaker ay parang switch na kusang bumubukas kapag sobra ang current, at maaari itong ibalik o i-reset pagkatapos, hindi tulad ng fuse na kailangang palitan.", "en": "A circuit breaker is like a switch that automatically opens when too much current flows, and it can be reset afterward, unlike a fuse which must be replaced.", "bis": "Ang circuit breaker sama sa switch nga awtomatikong moabli kung sobra ang current, ug mahimo kining i-reset human, dili sama sa fuse nga kinahanglang ilisan."}, "source": "physics consensus on circuit breakers", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-ground-wire-safety-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "grounding and the earth wire", "grades": [9, 10], "terms": ["grounding", "ground wire", "earth wire", "ground sa lupa", "kableng nakaugnay sa lupa", "grounding wire", "ligtas na kable", "ground sa yuta", "nakakabit sa lupa", "earthing", "proteksyon", "ground"], "fact": {"tl": "Ang grounding ay nag-uugnay ng metal na bahagi ng isang aparato sa lupa sa pamamagitan ng ground wire, kaya ang ligaw na current ay dumadaloy nang ligtas papunta sa lupa sa halip na sa tao.", "en": "Grounding connects the metal parts of an appliance to the earth through a ground wire, so any stray current flows safely into the ground instead of through a person.", "bis": "Ang grounding nagdugtong sa metal nga bahin sa usa ka galamiton ngadto sa yuta pinaagi sa ground wire, mao nga ang nahisalaag nga current moagas nga luwas ngadto sa yuta imbes sa tawo."}, "source": "physics consensus on electrical grounding/earthing", "generator": "claude-workflow", "reviewed": false},
  {"id": "bird-on-wire-not-shocked-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "why a bird on a power line is not shocked", "grades": [9, 10], "terms": ["ibon sa kable", "bird on wire", "hindi nakukuryente", "walang boltahe diperensiya", "langgam sa wire", "wala makuryente", "isa ka wire", "same wire", "walang daanan", "dili makuryente", "power line", "kuryenteng linya"], "fact": {"tl": "Ang isang ibong nakatungtong sa isang power line ay hindi nakukuryente dahil pareho ang boltahe sa dalawang paa nito, kaya walang current na dumadaloy sa katawan nito.", "en": "A bird sitting on a single power line is not shocked because both of its feet are at the same voltage, so no current flows through its body.", "bis": "Ang langgam nga naglingkod sa usa ka power line dili makuryente tungod kay parehas ra ang boltahe sa duha niini ka tiil, mao nga walay current nga moagi sa lawas niini."}, "source": "physics consensus on potential difference and shock", "generator": "claude-workflow", "reviewed": false},
  {"id": "water-body-conducts-shock-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "why wet skin makes electric shock worse", "grades": [9, 10], "terms": ["basang balat", "kuryente sa tubig", "wet skin shock", "mas mababang resistance", "delikadong kuryente", "basa nga panit", "tubig nagdala", "mas dako ang current", "shock", "nakuryente", "basa", "delikado kung basa"], "fact": {"tl": "Ang basang balat ay may mas mababang resistance kaysa tuyong balat, kaya mas malaking current ang dumadaloy at mas malala ang pagkakuryente kapag basa ang tao.", "en": "Wet skin has lower resistance than dry skin, so a larger current can flow and an electric shock becomes more dangerous when a person is wet.", "bis": "Ang basa nga panit adunay mas ubos nga resistance kaysa uga nga panit, mao nga mas dako nga current ang moagi ug mas peligroso ang shock kung basa ang tawo."}, "source": "physics consensus on body resistance and shock safety", "generator": "claude-workflow", "reviewed": false},
  {"id": "dc-vs-ac-current-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "direct current versus alternating current", "grades": [9, 10], "terms": ["direct current", "alternating current", "DC", "AC", "isang direksyon", "nagbabago ang direksyon", "baterya DC", "saksakan AC", "diretso nga current", "nagbalhin nga current", "outlet", "baterya", "kuryente sa saksakan"], "fact": {"tl": "Ang direct current (DC) mula sa baterya ay dumadaloy sa isang direksyon lamang, samantalang ang alternating current (AC) sa mga saksakan ay paulit-ulit na nagbabago ng direksyon.", "en": "Direct current (DC) from a battery flows in only one direction, while alternating current (AC) from wall outlets repeatedly reverses its direction.", "bis": "Ang direct current (DC) gikan sa baterya mo-agas sa usa lamang ka direksiyon, samtang ang alternating current (AC) gikan sa mga outlet balikbalik nga mobalhin sa direksiyon niini."}, "source": "physics consensus on DC and AC", "generator": "claude-workflow", "reviewed": false},
  {"id": "transmission-high-voltage-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "why power is transmitted at high voltage", "grades": [9, 10], "terms": ["mataas na boltahe", "transmission line", "high voltage", "transmission", "mas kaunting sayang", "less energy lost", "taas nga boltahe", "linya sa kuryente", "mas gamay ang sayang", "power lines", "transmisyon", "kuryenteng poste"], "fact": {"tl": "Ang kuryente ay ipinapadala sa malalayong lugar gamit ang napakataas na boltahe upang mas maliit ang current at mas kaunti ang enerhiyang nasasayang bilang init sa mga wire.", "en": "Electricity is sent over long distances at very high voltage so that the current is smaller and less energy is wasted as heat in the wires.", "bis": "Ang kuryente ipadala sa layo nga mga dapit gamit ang taas kaayo nga boltahe aron mas gamay ang current ug mas gamay ang enerhiya nga mausik isip init sa mga wire."}, "source": "physics consensus on power transmission and line losses", "generator": "claude-workflow", "reviewed": false},
  {"id": "transformer-changes-voltage-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "transformers change voltage for distribution", "grades": [9, 10], "terms": ["transformer", "transpormer", "nagbabago ng boltahe", "step up step down", "transpormer sa poste", "nagbag-o sa boltahe", "step-down", "pababa ang boltahe", "voltage change", "poste sa kuryente", "distribution"], "fact": {"tl": "Ang transformer ay nagbabago ng boltahe ng AC; itinataas ito para sa malayong transmisyon at ibinababa para ligtas itong magamit sa mga bahay.", "en": "A transformer changes the voltage of AC electricity, raising it for long-distance transmission and lowering it so it is safe to use in homes.", "bis": "Ang transformer mobag-o sa boltahe sa AC nga kuryente, gipataas kini alang sa layo nga transmisyon ug gipaubos aron luwas gamiton sa mga balay."}, "source": "physics consensus on transformers (AC only)", "generator": "claude-workflow", "reviewed": false},
  {"id": "battery-emf-drives-current-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "battery provides steady voltage to drive current", "grades": [9, 10], "terms": ["baterya boltahe", "battery voltage", "tuloy-tuloy na current", "kemikal na enerhiya", "baterya nagtutulak", "boltahe sa baterya", "kemikal nga enerhiya", "padayon nga current", "steady current", "baterya nagtulod", "DC", "tuloy-tuloy"], "fact": {"tl": "Ang baterya ay gumagamit ng kemikal na enerhiya upang magbigay ng tuluy-tuloy na boltahe na nagtutulak ng tuluy-tuloy na current sa isang sirkito.", "en": "A battery uses chemical energy to provide a steady voltage that drives a steady direct current around a circuit.", "bis": "Ang baterya naggamit ug kemikal nga enerhiya aron mohatag ug padayon nga boltahe nga nagtulod ug padayon nga current sa usa ka sirkito."}, "source": "physics consensus on cells/batteries; AAAS 4E/M2 battery in a complete circuit", "generator": "claude-workflow", "reviewed": false},
  {"id": "switch-controls-circuit-gap-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "a switch breaks or completes the circuit", "grades": [9, 10], "terms": ["switch", "swits", "pagbukas ng sirkito", "puwang sa sirkito", "humihinto ang current", "swits sa kuryente", "agianan naputol", "pagsira sa sirkito", "open circuit", "naputol nga sirkito", "patay ang ilaw", "bukas na sirkito"], "fact": {"tl": "Ang isang switch ay gumagawa o nagsasara ng puwang sa sirkito, at kapag may puwang ay tumitigil ang current dahil walang kumpletong daanan.", "en": "A switch opens or closes a gap in the circuit, and when the gap is open the current stops because there is no complete path.", "bis": "Ang switch mohimo o magsira ug usa ka luna sa sirkito, ug kung abli ang luna mohunong ang current tungod kay walay kompleto nga agianan."}, "source": "AAAS 4G/M4 electrical circuits require a complete loop", "generator": "claude-workflow", "reviewed": false},
  {"id": "led-needs-correct-direction-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "an LED only lights with current in one direction", "grades": [9, 10], "terms": ["LED", "led light", "isang direksyon lang", "diode", "tamang polarity", "usa ka direksiyon", "tama nga direksiyon", "polarity", "LED ilaw", "diyodo", "hindi sumisindi kung baligtad", "direksyon ng kable"], "fact": {"tl": "Ang isang LED ay isang uri ng diode na sumisindi lamang kapag tama ang direksyon ng pagkakakabit, dahil pinapadaan nito ang current sa isang direksyon lamang.", "en": "An LED is a kind of diode that lights up only when it is connected the correct way, because it lets current pass in just one direction.", "bis": "Ang LED usa ka matang sa diode nga modan-ag lamang kung sakto ang direksiyon sa pagkonektar, tungod kay paagion lamang niini ang current sa usa ka direksiyon."}, "source": "physics/electronics consensus on diodes and LEDs", "generator": "claude-workflow", "reviewed": false},
  {"id": "ammeter-series-voltmeter-parallel-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "how ammeters and voltmeters are connected", "grades": [9, 10], "terms": ["ammeter", "voltmeter", "ampere metro", "boltahe metro", "series ammeter", "parallel voltmeter", "sukat sa current", "sukat sa boltahe", "panukat ng kuryente", "metro ng current", "metro ng boltahe", "amperimetro", "boltmetro"], "fact": {"tl": "Ang ammeter ay ikinakabit nang series upang sukatin ang current na dumadaan, samantalang ang voltmeter ay ikinakabit nang parallel upang sukatin ang boltahe sa dalawang dulo ng isang bahagi.", "en": "An ammeter is connected in series to measure the current passing through, while a voltmeter is connected in parallel to measure the voltage across a part.", "bis": "Ang ammeter gikonektar sa series aron sukdon ang current nga moagi, samtang ang voltmeter gikonektar sa parallel aron sukdon ang boltahe tabok sa usa ka bahin."}, "source": "physics consensus on measuring instruments in circuits", "generator": "claude-workflow", "reviewed": false},
  {"id": "never-overload-outlet-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "why overloading an outlet is dangerous", "grades": [9, 10], "terms": ["overload", "sobrang plug", "octopus connection", "maraming saksak", "sobrang kuryente", "nag-init ang kable", "sobra nga plug", "daghang saksak", "init nga wire", "delikadong saksakan", "extension cord", "sobrang gamit", "nag-init"], "fact": {"tl": "Ang pagsaksak ng masyadong maraming kagamitan sa iisang saksakan ay nagpapalaki ng kabuuang current, na maaaring magpainit sa mga wire at magdulot ng sunog.", "en": "Plugging too many appliances into one outlet increases the total current, which can overheat the wires and start a fire.", "bis": "Ang pagsaksak ug sobra ka daghang galamiton sa usa lang ka outlet mopadako sa kinatibuk-ang current, nga makapainit sa mga wire ug makahimo ug sunog."}, "source": "physics consensus on circuit overload; electrical safety practice", "generator": "claude-workflow", "reviewed": false},
  {"id": "newton-first-law-uniform-velocity-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "first law constant velocity straight line", "grades": [9, 10], "terms": ["unang batas", "first law", "inertia", "inersya", "tuwid na linya", "straight line", "pare-parehong bilis", "constant velocity", "tuloy-tuloy", "naglihok", "patuloy na gumagalaw", "walang puwersa", "balanced force", "tul-id nga linya", "managsamang katulin", "magpadayon", "walay kusog", "naglihok pa", "uniform motion"], "fact": {"tl": "Sa unang batas ni Newton, ang isang gumagalaw na bagay ay magpapatuloy nang tuwid sa pare-parehong bilis kapag balanse (zero) ang kabuuang puwersa rito — hindi kailangan ng puwersa para panatilihin ang galaw, kailangan lang ito para baguhin ito.", "en": "By Newton's first law, a moving object keeps going straight at a constant speed when the total force on it is balanced (zero) — no force is needed to keep motion going, only to change it.", "bis": "Sa unang balaod ni Newton, ang naglihok nga butang magpadayon nga tul-id sa managsamang katulin kon balanse (zero) ang kinatibuk-ang kusog niini — walay kusog nga gikinahanglan aron mapadayon ang lihok, gikinahanglan lang kini aron usbon kini."}, "source": "NRC PS2.A; AAAS BSL 4F/H8", "generator": "claude-workflow", "reviewed": false},
  {"id": "inertia-depends-on-mass-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "inertia increases with mass", "grades": [9, 10], "terms": ["inertia", "inersya", "masa", "mass", "gibug-aton", "mas mabigat", "mas malaki ang inersya", "mas mahirap pakilusin", "mas mahirap patigilin", "resistensya sa pagbabago", "bug-at", "mas lisod palihukon", "mas lisod patumanon", "resistance to change", "carabao cart", "kariton", "more mass more inertia"], "fact": {"tl": "Mas malaki ang inertia ng isang bagay kapag mas malaki ang masa nito, kaya mas mahirap pakilusin o patigilin ang isang punong kariton kaysa sa isang walang laman.", "en": "An object has more inertia when it has more mass, so a loaded cart is harder to start moving or to stop than an empty one.", "bis": "Mas dako ang inertia sa usa ka butang kon mas dako ang masa niini, mao nga mas lisod palihukon o pahunongon ang puno nga kariton kaysa walay sulod."}, "source": "NRC PS2.A; AAAS BSL 4F", "generator": "claude-workflow", "reviewed": false},
  {"id": "net-force-vector-sum-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "net force as vector sum", "grades": [9, 10], "terms": ["net force", "kabuuang puwersa", "vector sum", "pinagsama-samang puwersa", "direksyon", "direction", "magkasalungat", "magkatumbas", "nagkakansela", "zero net force", "kinatibuk-ang kusog", "atbang", "nagkanselar", "tinipon nga kusog", "resultant force", "puwersang nananaig", "kabug-osang puwersa"], "fact": {"tl": "Ang net force ay ang pinagsama-samang puwersa na isinasaalang-alang ang lakas at direksyon ng bawat isa; kapag nagkakansela ang magkasalungat na puwersa, zero ang net force at hindi nagbabago ang galaw.", "en": "The net force is the combination of all forces taking each one's strength and direction into account; when opposite forces cancel, the net force is zero and the motion does not change.", "bis": "Ang net force mao ang gitiponong tanang kusog nga giila ang kakusgon ug direksyon sa matag usa; kon magkanselar ang atbang nga mga kusog, zero ang net force ug dili mausab ang lihok."}, "source": "NRC PS2.A; AAAS BSL 4F", "generator": "claude-workflow", "reviewed": false},
  {"id": "second-law-double-force-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "force proportional to acceleration", "grades": [9, 10], "terms": ["ikalawang batas", "second law", "doblehin ang puwersa", "double the force", "doble ang aselerasyon", "proporsyonal", "proportional", "katumbas ng dami", "F=ma", "mas malaking puwersa", "mas mabilis", "doblehon ang kusog", "doble ang aselerasyon", "proporsyon", "mas dako nga kusog", "directly proportional", "aselerasyon"], "fact": {"tl": "Para sa parehong masa, kapag dinoble mo ang puwersa, dinodoble mo rin ang aselerasyon — direktang proporsyonal ang puwersa sa pagbabago ng galaw (F = ma).", "en": "For the same mass, doubling the force doubles the acceleration — force is directly proportional to the change in motion (F = ma).", "bis": "Para sa samang masa, kon doblehon nimo ang kusog, doblehon usab nimo ang aselerasyon — direktang proporsyonal ang kusog sa pagbag-o sa lihok (F = ma)."}, "source": "NRC PS2.A; AAAS BSL 4F (Grades 9-12)", "generator": "claude-workflow", "reviewed": false},
  {"id": "second-law-double-mass-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "acceleration inversely proportional to mass", "grades": [9, 10], "terms": ["ikalawang batas", "second law", "doble ang masa", "double the mass", "kalahati ng aselerasyon", "inversely proportional", "baligtad na proporsyon", "mas mabigat", "mas mabagal pabilisin", "doble ang masa", "katunga sa aselerasyon", "baligtad nga proporsyon", "mas bug-at", "mas hinay paspason", "half the acceleration", "F=ma"], "fact": {"tl": "Sa parehong puwersa, kapag dinoble mo ang masa, nababawasan ng kalahati ang aselerasyon — baligtad na proporsyonal ang aselerasyon sa masa (a = F/m).", "en": "For the same force, doubling the mass halves the acceleration — acceleration is inversely proportional to mass (a = F/m).", "bis": "Sa samang kusog, kon doblehon nimo ang masa, makunhuran og katunga ang aselerasyon — baligtad nga proporsyonal ang aselerasyon sa masa (a = F/m)."}, "source": "NRC PS2.A; AAAS BSL 4F (Grades 9-12)", "generator": "claude-workflow", "reviewed": false},
  {"id": "second-law-direction-of-acceleration-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "acceleration in direction of net force", "grades": [9, 10], "terms": ["aselerasyon", "acceleration", "direksyon ng puwersa", "direction of force", "kapareho ng net force", "tumutulak", "humihila", "bumibilis", "bumabagal", "lumiliko", "kadakuan sa puwersa", "direksyon sa kusog", "samang direksyon", "mopaspas", "mohinay", "moliko", "speeds up slows down turns"], "fact": {"tl": "Ang aselerasyon ng isang bagay ay laging nasa direksyon ng net force: kung pasulong ang net force, bumibilis; kung pabalik, bumabagal; kung patagilid, lumiliko ito.", "en": "An object's acceleration is always in the direction of the net force: a forward net force speeds it up, a backward one slows it down, and a sideways one makes it turn.", "bis": "Ang aselerasyon sa usa ka butang kanunay anaa sa direksyon sa net force: kon pasulong ang net force, mopaspas; kon paatras, mohinay; kon pakilid, moliko kini."}, "source": "NRC PS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "action-reaction-different-objects-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "action-reaction pairs act on different objects", "grades": [9, 10], "terms": ["ikatlong batas", "third law", "action reaction", "aksyon reaksyon", "magkaibang bagay", "different objects", "hindi nagkakansela", "do not cancel", "dalawang bagay", "magkahiwalay na bagay", "magkalahing butang", "dili magkanselar", "duha ka butang", "lain-lain nga butang", "pair of forces", "magkapares na puwersa"], "fact": {"tl": "Ang action at reaction ay kumikilos sa DALAWANG MAGKAIBANG bagay — kaya hindi sila nagkakansela: itinutulak mo ang dingding, itinutulak ka nito pabalik, ngunit ang puwersa mo ay nasa dingding at ang puwersa nito ay nasa iyo.", "en": "Action and reaction forces act on TWO DIFFERENT objects — that is why they do not cancel: you push the wall and it pushes you back, but your force is on the wall and its force is on you.", "bis": "Ang action ug reaction nga kusog molihok sa DUHA KA MAGKALAHING butang — mao nga dili sila magkanselar: imong iduso ang bungbong ug iduso ka usab niini, apan ang imong kusog anaa sa bungbong ug ang kusog niini anaa kanimo."}, "source": "NRC PS2.A; AAAS BSL Ch.4 (misconception note)", "generator": "claude-workflow", "reviewed": false},
  {"id": "banca-paddle-action-reaction-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "paddling a banca action-reaction", "grades": [8, 9, 10], "terms": ["banca", "bangka", "sagwan", "paddle", "bugsay", "action reaction", "aksyon reaksyon", "itinutulak ang tubig", "tumutulak pabalik", "naglalayag", "pasulong", "iduso ang tubig", "moduso balik", "pasulong", "ikatlong batas", "third law", "lake boat", "fisherman", "mangingisda"], "fact": {"tl": "Kapag itinutulak pabalik ng sagwan ang tubig (action), itinutulak ng tubig ang banca pasulong (reaction) nang may pantay na lakas — ito ang ikatlong batas ni Newton sa paglalayag.", "en": "When the paddle pushes the water backward (action), the water pushes the banca forward (reaction) with equal strength — this is Newton's third law at work in rowing.", "bis": "Kon ang bugsay moduso sa tubig paatras (action), ang tubig moduso sa banca pasulong (reaction) sa parehas nga kusog — mao kini ang ikatulong balaod ni Newton sa pagbugsay."}, "source": "NRC PS2.A (Newton's third law)", "generator": "claude-workflow", "reviewed": false},
  {"id": "basketball-jump-reaction-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "jumping action-reaction with the floor", "grades": [8, 9, 10], "terms": ["basketball", "talon", "jump", "lukso", "itinutulak ang sahig", "push the floor", "sahig", "floor", "tumutulak pabalik", "reaction", "aksyon reaksyon", "umakyat", "iambak", "iduso ang salog", "moduso balik", "molukso", "ground pushes back", "rebound", "lakas"], "fact": {"tl": "Kapag tumalon ang isang basketball player, malakas niyang itinutulak ang sahig pababa (action), at ang sahig naman ay itinutulak siya pataas (reaction) — kaya siya umaakyat sa ere.", "en": "When a basketball player jumps, they push hard on the floor downward (action), and the floor pushes them upward (reaction) — which is what lifts them into the air.", "bis": "Kon molukso ang basketball player, kusgan niyang iduso ang salog paubos (action), ug ang salog moduso kaniya pataas (reaction) — mao kini ang nagpataas kaniya sa hangin."}, "source": "NRC PS2.A (Newton's third law)", "generator": "claude-workflow", "reviewed": false},
  {"id": "friction-hidden-force-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "friction is why moving things seem to stop on their own", "grades": [9, 10], "terms": ["friction", "friksyon", "alitan", "nagpapabagal", "bumabagal", "tumitigil mag-isa", "nakatagong puwersa", "hidden force", "kuskusan", "nagpapahinto", "mohinay", "mohunong nga mag-isa", "tinago nga kusog", "resistensya", "drag", "humihinto", "lumalaban sa galaw", "mosupak sa lihok"], "fact": {"tl": "Ang dahilan kung bakit mukhang humihinto mag-isa ang mga gumagalaw na bagay ay ang friction — isang nakatagong puwersang lumalaban sa galaw — at hindi dahil natural na humihinto ang galaw.", "en": "The reason moving things seem to stop on their own is friction — a hidden force that opposes motion — not because motion naturally stops.", "bis": "Ang rason nganong morag mohunong nga mag-isa ang naglihok nga mga butang mao ang friction — usa ka tinago nga kusog nga mosupak sa lihok — dili tungod kay natural nga mohunong ang lihok."}, "source": "AAAS BSL Ch.4 (Grades 9-12); NRC PS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "friction-complicates-but-laws-hold-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "Newton's laws still apply with friction", "grades": [9, 10], "terms": ["friction", "friksyon", "alitan", "batas ni Newton", "Newton's laws", "kasama ang friction", "puwersang dagdag", "isa pang puwersa", "totoong mundo", "real world", "uban ang friction", "dugang nga kusog", "lain nga kusog", "tinuod nga kalibutan", "valid pa rin", "still applies", "kasalungat na puwersa"], "fact": {"tl": "Kahit pinalubha ng friction ang paglalarawan ng galaw sa totoong mundo, gumagana pa rin ang mga batas ni Newton — itinuturing lang ang friction bilang isa pang puwersang kasama sa net force.", "en": "Even though friction complicates the description of motion in the real world, Newton's laws still hold — friction is just counted as one more force in the net force.", "bis": "Bisan kon ang friction maglisod sa paghulagway sa lihok sa tinuod nga kalibutan, ang mga balaod ni Newton molihok gihapon — ang friction giihap lang isip usa pa ka kusog sa net force."}, "source": "AAAS BSL 4F/H7 (Grades 9-12)", "generator": "claude-workflow", "reviewed": false},
  {"id": "first-law-special-case-second-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "first law is a special case of the second law", "grades": [9, 10], "terms": ["unang batas", "first law", "ikalawang batas", "second law", "F=0", "walang puwersa", "special case", "espesyal na kaso", "kapag zero ang puwersa", "walang pagbabago sa galaw", "espesyal nga kaso", "walay kusog", "kon zero ang puwersa", "walay kausaban sa lihok", "no change in motion", "F equals zero"], "fact": {"tl": "Ang unang batas ni Newton ay isang espesyal na kaso ng ikalawa: kapag zero ang puwersa (F = 0), zero rin ang aselerasyon, kaya nananatiling tigil o pare-pareho ang bilis ng bagay.", "en": "Newton's first law is a special case of the second: when the force is zero (F = 0), the acceleration is zero too, so the object stays still or keeps a constant speed.", "bis": "Ang unang balaod ni Newton usa ka espesyal nga kaso sa ikaduha: kon zero ang kusog (F = 0), zero usab ang aselerasyon, mao nga magpabilin nga hunong o managsama ang katulin sa butang."}, "source": "AAAS BSL Ch.4 (Grades 9-12)", "generator": "claude-workflow", "reviewed": false},
  {"id": "jeepney-start-passengers-lean-back-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "inertia when a jeepney starts moving", "grades": [8, 9, 10], "terms": ["dyip", "jeepney", "jeep", "umaarangkada", "umandar", "pasahero", "passengers", "sumasandal", "lean back", "inertia", "inersya", "naiiwan", "moandar", "nagsugod molihok", "mosandal", "nahibilin", "tendency to stay at rest", "tigil", "pabalik"], "fact": {"tl": "Kapag biglang umarangkada ang dyip, ang mga pasahero ay tila sumasandal pabalik dahil sa inertia — gusto ng kanilang katawan na manatiling tigil habang sumusulong na ang dyip.", "en": "When a jeepney suddenly starts moving, the passengers seem to lean backward because of inertia — their bodies tend to stay at rest while the jeepney moves forward.", "bis": "Kon kalit moandar ang dyip, ang mga pasahero morag mosandal paatras tungod sa inertia — gusto sa ilang lawas nga magpabilin nga hunong samtang ang dyip mopadayon sa unahan."}, "source": "NRC PS2.A (inertia, Newton's first law)", "generator": "claude-workflow", "reviewed": false},
  {"id": "weight-as-force-equation-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "weight is force from gravity W=mg", "grades": [9, 10], "terms": ["timbang", "weight", "puwersa", "force", "grabidad", "gravity", "W=mg", "masa", "mass", "newton", "yunit", "9.8", "aselerasyon ng grabidad", "gibug-aton isip kusog", "grabidad nga aselerasyon", "kabug-aton", "W equals mg", "free fall", "hila ng grabidad"], "fact": {"tl": "Ang timbang ay ang puwersa ng grabidad sa isang bagay, na katumbas ng masa beses aselerasyon ng grabidad (W = mg), kaya ito'y sinusukat sa newton tulad ng ibang puwersa.", "en": "Weight is the force of gravity on an object, equal to mass times the acceleration of gravity (W = mg), so it is measured in newtons like any other force.", "bis": "Ang gibug-aton mao ang kusog sa grabidad sa usa ka butang, katumbas sa masa pilo-on sa aselerasyon sa grabidad (W = mg), mao nga gisukod kini sa newton sama sa ubang kusog."}, "source": "NRC PS2.B; AAAS BSL Ch.4 Forces of Nature", "generator": "claude-workflow", "reviewed": false},
  {"id": "terminal-velocity-falling-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "terminal velocity balanced forces in fall", "grades": [9, 10], "terms": ["terminal velocity", "huling bilis", "nahuhulog", "falling", "air resistance", "resistensya ng hangin", "katumbas ng grabidad", "balanced", "pare-parehong bilis", "parasyut", "parachute", "nahulog", "sukol sa hangin", "managsama na ang kusog", "hunong na ang pagpaspas", "constant fall speed", "patak ng ulan", "raindrop"], "fact": {"tl": "Habang nahuhulog ang isang bagay, lumalakas ang air resistance hanggang umabot ito sa lakas ng grabidad; kapag balanse na ang dalawa, hindi na bumibilis ang bagay at bumabagsak na ito sa pare-parehong bilis na tinatawag na terminal velocity.", "en": "As an object falls, air resistance grows until it matches gravity; once the two balance, the object stops speeding up and falls at a constant speed called terminal velocity.", "bis": "Samtang nahulog ang usa ka butang, mokusog ang air resistance hangtod makatupong kini sa grabidad; kon magbalanse na ang duha, dili na mopaspas ang butang ug mahulog sa managsamang katulin nga gitawag og terminal velocity."}, "source": "NRC PS2.A; AAAS BSL Ch.4 (Grades 9-12)", "generator": "claude-workflow", "reviewed": false},
  {"id": "momentum-mass-times-velocity-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "momentum is mass times velocity", "grades": [9, 10], "terms": ["momentum", "masa", "mass", "bilis", "velocity", "tulin", "katulin", "mas mabigat", "mas mabilis", "mas malaking momentum", "mahirap patigilin", "mas dako nga momentum", "lisod pahunongon", "trak", "truck", "p=mv", "galaw na dala", "lakas ng galaw"], "fact": {"tl": "Ang momentum ay ang masa beses ang bilis ng isang bagay (p = mv), kaya ang isang mabigat o mabilis na bagay tulad ng trak ay may malaking momentum at mahirap patigilin.", "en": "Momentum is an object's mass times its velocity (p = mv), so a heavy or fast object like a truck has large momentum and is hard to stop.", "bis": "Ang momentum mao ang masa pilo-on sa katulin sa usa ka butang (p = mv), mao nga ang bug-at o paspas nga butang sama sa trak adunay dako nga momentum ug lisod pahunongon."}, "source": "NRC PS2.A (Grade 12; momentum = mass times velocity)", "generator": "claude-workflow", "reviewed": false},
  {"id": "momentum-conservation-collision-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "conservation of momentum in collisions", "grades": [9, 10], "terms": ["conservation of momentum", "konserbasyon ng momentum", "banggaan", "collision", "bangga", "kabuuang momentum", "total momentum", "hindi nawawala", "nananatili", "naililipat", "kinatibuk-ang momentum", "dili mawala", "magpabilin", "ma-transfer", "billiard", "bilyar", "magka-igo", "before and after"], "fact": {"tl": "Sa isang banggaan, ang kabuuang momentum ng mga bagay bago at pagkatapos ay nananatiling pareho — naililipat lang ang momentum mula sa isang bagay patungo sa iba, hindi ito nawawala.", "en": "In a collision, the total momentum of the objects before and after stays the same — momentum is only transferred from one object to another, never lost.", "bis": "Sa usa ka banggaan, ang kinatibuk-ang momentum sa mga butang sa wala pa ug human magpabilin nga parehas — ang momentum gibalhin lang gikan sa usa ka butang ngadto sa lain, dili kini mawala."}, "source": "NRC PS2.A (Grade 12; total momentum is conserved)", "generator": "claude-workflow", "reviewed": false},
  {"id": "rocket-momentum-conservation-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "rocket thrust from momentum conservation", "grades": [9, 10], "terms": ["rocket", "kohete", "gas pababa", "exhaust", "tinaboy na gas", "momentum", "pataas", "action reaction", "konserbasyon ng momentum", "walang hangin", "kalawakan", "space", "ibinuga nga gas", "pataas", "molupad bisan sa wagas", "vacuum", "thrust", "tulak"], "fact": {"tl": "Ang rocket ay sumusulong kahit sa kalawakan na walang hangin dahil habang itinataboy nito ang gas pababa, ang rocket ay nakakakuha ng kapantay na momentum pataas — pinananatili ang kabuuang momentum.", "en": "A rocket moves even in airless space because as it throws gas downward, the rocket gains equal momentum upward — keeping the total momentum the same.", "bis": "Ang rocket molihok bisan sa kawanangan nga walay hangin tungod kay samtang giitsa niini ang gas paubos, ang rocket makakuha og parehas nga momentum pataas — gipabilin ang kinatibuk-ang momentum."}, "source": "NRC PS2.A (Newton's third law; conservation of momentum)", "generator": "claude-workflow", "reviewed": false},
  {"id": "normal-force-book-on-table-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "normal force from a surface", "grades": [9, 10], "terms": ["normal force", "puwersa ng ibabaw", "mesa", "table", "lamesa", "libro", "book", "itinutulak pataas", "support force", "balanse ng timbang", "nakapatong", "tumutulak pabalik", "kusog sa patukoranan", "iduso pataas", "balanse sa gibug-aton", "surface pushes up", "puwersang sumusuporta", "resting on surface"], "fact": {"tl": "Kapag nakapatong ang libro sa mesa, ang mesa ay tumutulak pabalik sa libro pataas nang katumbas ng timbang nito (normal force), kaya balanse ang puwersa at hindi gumagalaw ang libro.", "en": "When a book rests on a table, the table pushes back up on the book with a force equal to its weight (the normal force), so the forces balance and the book stays still.", "bis": "Kon ang libro nahimutang sa lamesa, ang lamesa moduso balik sa libro pataas sa kusog nga parehas sa gibug-aton niini (normal force), mao nga balanse ang kusog ug dili molihok ang libro."}, "source": "NRC PS2.A; AAAS BSL Ch.4 (book-on-table example)", "generator": "claude-workflow", "reviewed": false},
  {"id": "tricycle-friction-tires-grip-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "tires use friction to push the road", "grades": [9, 10], "terms": ["traysikel", "tricycle", "gulong", "tire", "ligid", "friction", "friksyon", "kumakapit sa kalsada", "itinutulak ang kalsada", "tumutulak pabalik", "umaarangkada", "moandar", "ligid mokapyot", "iduso ang dalan", "moduso balik", "action reaction", "grip", "umuusad", "traction", "madulas", "slippery"], "fact": {"tl": "Umaarangkada ang traysikel dahil ang gumugulong na gulong ay itinutulak pabalik ang kalsada gamit ang friction, kaya itinutulak naman ng kalsada ang traysikel pasulong — kaya dumudulas ito kapag basa at mahina ang friction.", "en": "A tricycle moves because its turning tire pushes backward on the road using friction, so the road pushes the tricycle forward — which is why it skids when the road is wet and friction is weak.", "bis": "Moandar ang traysikel tungod kay ang naglibot nga ligid moduso paatras sa dalan gamit ang friction, mao nga ang dalan moduso sa traysikel pasulong — mao nga modahilos kini kon basa ang dalan ug huyang ang friction."}, "source": "NRC PS2.A (Newton's third law; friction)", "generator": "claude-workflow", "reviewed": false},
  {"id": "reference-frame-motion-relative-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "motion is relative to a reference frame", "grades": [9, 10], "terms": ["reference frame", "sanggunian", "galaw ay relatibo", "relative motion", "kaugnay na galaw", "nakaupo sa bus", "tigil para sa iba", "gumagalaw para sa iba", "depende sa tinitingnan", "lihok kalabot sa", "relatibo", "naglingkod sa bus", "depende sa gibasihan", "depende kang kinsa", "observer", "frame of reference", "patnubay"], "fact": {"tl": "Ang galaw ay palaging sinusukat kaugnay ng isang piniling sanggunian (reference frame): ang nakaupo sa bus ay tigil kumpara sa kapwa pasahero ngunit mabilis na gumagalaw kumpara sa taong nasa kalsada.", "en": "Motion is always measured relative to a chosen reference frame: a person sitting in a bus is at rest compared to fellow passengers but moving fast compared to someone on the road.", "bis": "Ang lihok kanunay gisukod kalabot sa usa ka gipiling reference frame: ang naglingkod sa bus hunong kumpara sa isigka-pasahero apan paspas nga naglihok kumpara sa tawo nga naa sa dalan."}, "source": "NRC PS2.A; AAAS BSL Ch.4 (reference frames, Grades 9-12)", "generator": "claude-workflow", "reviewed": false},
  {"id": "carabao-cart-force-mass-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "loaded cart needs more force F=ma", "grades": [8, 9, 10], "terms": ["kalabaw", "carabao", "kariton", "cart", "punong kariton", "loaded", "mas malaking puwersa", "more force", "mas mabagal", "F=ma", "masa", "mass", "puno nga kariton", "mas dako nga kusog", "mas hinay", "hila", "pull", "mabigat na karga", "heavy load"], "fact": {"tl": "Kailangan ng kalabaw ng mas malaking puwersa para pabilisin ang punong kariton kaysa sa walang laman, dahil mas malaki ang masa kaya mas maliit ang aselerasyon sa parehong puwersa (F = ma).", "en": "A carabao needs a larger force to speed up a loaded cart than an empty one, because the bigger mass gives a smaller acceleration for the same force (F = ma).", "bis": "Kinahanglan sa kabaw og mas dako nga kusog aron paspason ang puno nga kariton kaysa walay sulod, kay ang mas dako nga masa mohatag og mas gamay nga aselerasyon sa samang kusog (F = ma)."}, "source": "NRC PS2.A (Newton's second law); DepEd G8", "generator": "claude-workflow", "reviewed": false},
  {"id": "swimmer-pushes-water-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "swimming action-reaction with water", "grades": [8, 9, 10], "terms": ["langoy", "swimming", "lumalangoy", "manlalangoy", "itinutulak ang tubig", "push water back", "tubig tumutulak", "pasulong", "action reaction", "aksyon reaksyon", "iduso ang tubig paatras", "tubig moduso", "molangoy", "kamot ug tiil", "kicks and strokes", "ikatlong batas", "mosulong"], "fact": {"tl": "Lumulutang at sumusulong ang manlalangoy dahil itinutulak niya ang tubig pabalik gamit ang kamay at paa, kaya itinutulak naman siya ng tubig pasulong (ikatlong batas ni Newton).", "en": "A swimmer moves forward because they push the water backward with their hands and feet, so the water pushes them forward in return (Newton's third law).", "bis": "Mosulong ang molangoy tungod kay iduso niya ang tubig paatras gamit ang kamot ug tiil, mao nga ang tubig moduso kaniya pasulong (ikatulong balaod ni Newton)."}, "source": "NRC PS2.A (Newton's third law)", "generator": "claude-workflow", "reviewed": false},
  {"id": "stopping-distance-mass-speed-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "heavier and faster vehicles need more distance to stop", "grades": [9, 10], "terms": ["stopping distance", "layo ng pagtigil", "preno", "brake", "mas mabigat", "mas mabilis", "mas mahabang layo", "mas malaking puwersa kailangan", "inertia", "momentum", "mas bug-at", "mas paspas", "mas taas nga gilay-on", "mas dako nga kusog gikinahanglan", "trak", "truck", "kaligtasan sa kalsada", "road safety"], "fact": {"tl": "Mas mabigat o mas mabilis na sasakyan ay nangangailangan ng mas malaking puwersa at mas mahabang layo bago tumigil, dahil mas malaki ang inertia at momentum nito.", "en": "A heavier or faster vehicle needs a larger force and a longer distance to stop, because it has greater inertia and momentum.", "bis": "Ang mas bug-at o mas paspas nga sakyanan nanginahanglan og mas dako nga kusog ug mas taas nga gilay-on una mohunong, kay mas dako ang inertia ug momentum niini."}, "source": "NRC PS2.A (inertia, momentum); AAAS BSL Ch.4", "generator": "claude-workflow", "reviewed": false},
  {"id": "force-changes-shape-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "forces can change shape not only motion", "grades": [8, 9, 10], "terms": ["puwersa", "force", "hugis", "shape", "korte", "nagbabago ng hugis", "change shape", "nililok", "pinipiga", "binabaluktot", "deformation", "mausab ang porma", "pislit", "ibawog", "dili lang lihok", "spring", "goma", "clay", "luwad"], "fact": {"tl": "Hindi lang galaw ang binabago ng puwersa — maaari rin nitong baguhin ang hugis o anyo ng isang bagay, tulad ng pagpiga sa goma o pagbaluktot sa metal.", "en": "Forces do not only change motion — they can also change the shape or form of an object, such as squeezing rubber or bending metal.", "bis": "Ang kusog dili lang mag-usab sa lihok — mahimo usab niini usbon ang porma o hulagway sa usa ka butang, sama sa pagpislit sa goma o pagbawog sa metal."}, "source": "NRC PS2.A (forces can change shape or orientation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "bicycle-pedal-friction-forward-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "bicycle moves by pushing the road backward", "grades": [9, 10], "terms": ["bisikleta", "bicycle", "bike", "pedal", "gulong", "tire", "itinutulak pabalik ang lupa", "push ground back", "friction", "friksyon", "pasulong", "action reaction", "iduso ang yuta paatras", "molihok pasulong", "ligid", "tumakbo", "modagan", "third law", "ikatlong batas"], "fact": {"tl": "Sumusulong ang bisikleta dahil ang gulong na pinapaikot ng pedal ay itinutulak pabalik ang lupa gamit ang friction, at bilang reaksiyon, itinutulak ng lupa ang bisikleta pasulong.", "en": "A bicycle moves forward because the pedal-driven wheel pushes the ground backward using friction, and in reaction the ground pushes the bicycle forward.", "bis": "Mosulong ang bisikleta tungod kay ang ligid nga gipalibot sa pedal moduso sa yuta paatras gamit ang friction, ug isip reaksyon, ang yuta moduso sa bisikleta pasulong."}, "source": "NRC PS2.A (Newton's third law; friction)", "generator": "claude-workflow", "reviewed": false},
  {"id": "balanced-forces-constant-speed-not-zero-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "balanced forces can mean steady motion not just rest", "grades": [9, 10], "terms": ["balanced forces", "balanseng puwersa", "pare-parehong bilis", "constant speed", "hindi nangangahulugan tigil", "not always at rest", "steady motion", "tuloy-tuloy na galaw", "zero net force", "managsamang katulin", "dili pasabot hunong", "tuloy-tuloy nga lihok", "eroplano", "cruising plane", "patag nga lihok", "equilibrium"], "fact": {"tl": "Ang balanseng puwersa ay hindi laging nangangahulugang nakatigil ang bagay — maaari rin itong gumagalaw nang tuwid sa pare-parehong bilis, tulad ng eroplanong patag na lumilipad.", "en": "Balanced forces do not always mean an object is at rest — it can also be moving straight at a constant speed, like a plane cruising level.", "bis": "Ang balanse nga mga kusog dili kanunay nagpasabot nga hunong ang butang — mahimo usab kining naglihok nga tul-id sa managsamang katulin, sama sa eroplano nga patag nga naglupad."}, "source": "NRC PS2.A; AAAS BSL 4F/H8", "generator": "claude-workflow", "reviewed": false},
  {"id": "free-fall-same-acceleration-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "objects fall at the same acceleration ignoring air", "grades": [9, 10], "terms": ["free fall", "malayang pagbagsak", "nahuhulog", "parehong aselerasyon", "same acceleration", "mabigat at magaan", "heavy and light", "walang air resistance", "9.8", "g", "pantay ang bilis", "managsamang aselerasyon", "bug-at ug gaan", "walay air resistance", "bato ug balhibo", "feather and stone", "vacuum"], "fact": {"tl": "Kapag walang air resistance, ang lahat ng bagay — mabigat man o magaan — ay nahuhulog sa parehong aselerasyon, dahil mas malaking masa ay may mas malaking timbang pero mas malaking inertia rin (F = ma).", "en": "With no air resistance, all objects — heavy or light — fall with the same acceleration, because a larger mass has a larger weight but also a larger inertia (F = ma).", "bis": "Kon walay air resistance, ang tanang butang — bug-at man o gaan — mahulog sa managsamang aselerasyon, kay ang mas dako nga masa adunay mas dako nga gibug-aton apan mas dako usab nga inertia (F = ma)."}, "source": "NRC PS2.A; PS2.B (gravity); AAAS BSL Ch.4 (Grades 9-12)", "generator": "claude-workflow", "reviewed": false},
  {"id": "velocity-time-graph-slope-acceleration-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "velocity-time graph slope is acceleration", "grades": [9, 10], "terms": ["velocity-time graph", "graph ng tulin at oras", "slope", "dalisdis ng linya", "acceleration", "aselerasyon", "pagbabago ng tulin", "tarik", "matarik", "talangguhit sa katulin", "tarik nga linya", "velocity", "tulin", "kapaspas", "pagbag-o sa katulin", "gradient", "pababang slope", "deceleration"], "fact": {"tl": "Sa isang velocity-time graph, ang tarik o slope ng linya ay nagpapakita ng aselerasyon — ang patag na linya ay nangangahulugang pare-pareho ang tulin, ang pataas na linya ay bumibilis, at ang pababang linya ay bumabagal.", "en": "On a velocity-time graph, the steepness or slope of the line shows the acceleration — a flat line means constant velocity, an upward line means speeding up, and a downward line means slowing down.", "bis": "Sa usa ka velocity-time graph, ang tarik o slope sa linya nagpakita sa aselerasyon — ang patag nga linya nagpasabot nga parehas ra ang katulin, ang nagsaka nga linya nagpasabot nga mopaspas, ug ang nagkanaog nga linya nagpasabot nga mohinay."}, "source": "NRC PS2.A; DepEd G9-10 kinematics; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "velocity-time-graph-area-distance-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "area under velocity-time graph is distance", "grades": [9, 10], "terms": ["velocity-time graph", "area sa ilalim", "lawak sa ilalom", "distance", "layo", "gilay-on", "nilakbay", "gilaktan", "sukat ng lugar", "kabuuang layo", "ilalim ng linya", "kahabaan", "tulin", "velocity", "oras", "time", "area under the curve", "kinatibuk-ang gilay-on"], "fact": {"tl": "Sa isang velocity-time graph, ang lawak o sukat ng lugar sa ilalim ng linya ay katumbas ng kabuuang layong nilakbay ng bagay.", "en": "On a velocity-time graph, the area beneath the line equals the total distance the object has traveled.", "bis": "Sa usa ka velocity-time graph, ang lawak sa ilalom sa linya parehas sa kinatibuk-ang gilay-on nga gilaktan sa butang."}, "source": "encyclopedia-stable consensus; DepEd G9-10 kinematics", "generator": "claude-workflow", "reviewed": false},
  {"id": "distance-time-graph-curve-acceleration-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "curved distance-time graph means acceleration", "grades": [9, 10], "terms": ["distance-time graph", "graph ng layo at oras", "kurbada", "nakurba", "curve", "baluktot na linya", "bumibilis", "pabilis nga tarik", "acceleration", "aselerasyon", "tuwid na linya", "pare-parehong bilis", "constant speed", "naglikod nga linya", "nagkakurba", "gilay-on ug oras", "nagdugang ang tarik"], "fact": {"tl": "Sa isang distance-time graph, ang tuwid na linya ay nagpapakita ng pare-parehong bilis, ngunit ang kurbadong linya na patuloy na tumatarik ay nangangahulugang bumibilis o nag-aaselerate ang bagay.", "en": "On a distance-time graph, a straight line shows constant speed, but a curved line that keeps getting steeper means the object is speeding up or accelerating.", "bis": "Sa usa ka distance-time graph, ang tul-id nga linya nagpakita sa parehas nga katulin, apan ang kurbado nga linya nga padayon nga nagtarik nagpasabot nga ang butang nagpaspas o nag-aselerate."}, "source": "encyclopedia-stable consensus; DepEd G9-10 kinematics", "generator": "claude-workflow", "reviewed": false},
  {"id": "acceleration-formula-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "acceleration is change in velocity over time", "grades": [9, 10], "terms": ["aselerasyon", "acceleration", "pagbabago ng tulin", "change in velocity", "kada oras", "metro kada segundo", "m/s2", "pagbag-o sa katulin", "kabag-ohan sa katulin", "tulin", "velocity", "panahon", "time", "pinal na tulin", "simulang tulin", "hinati sa oras", "bawat segundo"], "fact": {"tl": "Ang aselerasyon ay kung gaano kabilis nagbabago ang tulin ng isang bagay, kaya kinukuha ito sa pagbabago ng tulin na hinati sa oras (sinusukat sa metro kada segundo bawat segundo).", "en": "Acceleration is how quickly an object's velocity changes, so it is found from the change in velocity divided by the time taken (measured in meters per second each second).", "bis": "Ang aselerasyon mao kung unsa ka paspas mausab ang katulin sa usa ka butang, busa makuha kini gikan sa pagbag-o sa katulin nga gibahin sa oras (gisukod sa metro kada segundo matag segundo)."}, "source": "NRC PS2.A; DepEd G9-10 kinematics; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "deceleration-negative-acceleration-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "deceleration is negative acceleration", "grades": [9, 10], "terms": ["deceleration", "pagbagal", "paghinay", "negatibong aselerasyon", "negative acceleration", "bumabagal", "mohinay", "kabaliktad ng galaw", "atbang sa direksyon", "preno", "pagpreno", "slowing down", "puwersa pabalik", "katulin nagkagamay", "naghinay"], "fact": {"tl": "Kapag bumabagal ang isang bagay, may aselerasyon pa rin ito ngunit nakaturo ang puwersa pabaligtad sa galaw, kaya tinatawag itong deceleration o negatibong aselerasyon.", "en": "When an object slows down it still has acceleration, but the force points opposite to its motion, so this is called deceleration or negative acceleration.", "bis": "Kung mohinay ang usa ka butang naa pa gihapon kini aselerasyon apan ang kusog nagtumong batok sa lihok niini, busa gitawag kini nga deceleration o negatibong aselerasyon."}, "source": "NRC PS2.A; encyclopedia-stable consensus; DepEd G9-10 kinematics", "generator": "claude-workflow", "reviewed": false},
  {"id": "uniform-velocity-no-acceleration-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "constant velocity means zero acceleration", "grades": [9, 10], "terms": ["pare-parehong tulin", "constant velocity", "uniform velocity", "walang aselerasyon", "zero acceleration", "walay aselerasyon", "patag na linya", "balanced force", "magkapantay na puwersa", "tuloy-tuloy na galaw", "parehas nga katulin", "walang pagbabago", "way kausaban", "steady speed", "tuwid na direksyon"], "fact": {"tl": "Kapag pare-pareho ang tulin at direksyon ng isang bagay, walang aselerasyon ito, at nangangahulugang balanse o magkapantay ang mga puwersang umiiral dito.", "en": "When an object keeps the same speed and direction, it has zero acceleration, which means the forces acting on it are balanced.", "bis": "Kung parehas ra ang katulin ug direksyon sa usa ka butang, wala kini aselerasyon, nga nagpasabot nga balanse o managsama ang mga kusog nga naglihok niini."}, "source": "NRC PS2.A; AAAS BSL Ch.4; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "momentum-formula-mass-velocity-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "momentum equals mass times velocity", "grades": [9, 10], "terms": ["momentum", "masa", "mass", "tulin", "velocity", "p=mv", "lakas ng galaw", "kusog sa paglihok", "may direksyon", "vector", "kilo metro kada segundo", "gibug-aton ug katulin", "produkto", "pinarami", "pilo-on", "dami ng galaw", "direksyon", "bilis"], "fact": {"tl": "Ang momentum ng isang bagay ay katumbas ng masa nito na pinarami sa tulin (p = mv), at may direksyon ito tulad ng tulin.", "en": "An object's momentum equals its mass multiplied by its velocity (p = mv), and like velocity it has a direction.", "bis": "Ang momentum sa usa ka butang parehas sa masa niini nga pilo-on sa katulin (p = mv), ug sama sa katulin naa kini direksyon."}, "source": "NRC PS2.A; DepEd G9-10 momentum; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "conservation-of-momentum-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "conservation of momentum in collisions", "grades": [9, 10], "terms": ["konserbasyon ng momentum", "conservation of momentum", "kabuuang momentum", "kinatibuk-ang momentum", "banggaan", "collision", "bago at pagkatapos", "antes ug human", "hindi nawawala", "way mawala", "magkasamang", "closed system", "saradong sistema", "total momentum", "nagdugtong", "napreserba", "before and after", "pananatiling pantay"], "fact": {"tl": "Sa isang banggaan na walang panlabas na puwersa, ang kabuuang momentum ng mga bagay bago bumangga ay pareho sa kabuuang momentum pagkatapos — hindi ito nawawala kundi nailalapat lang.", "en": "In a collision with no outside force, the total momentum of the objects before they hit equals the total momentum afterward — it is not lost, only shared around.", "bis": "Sa usa ka banggaan nga walay gawas nga kusog, ang kinatibuk-ang momentum sa mga butang antes mobangga parehas sa kinatibuk-ang momentum human niini — dili kini mawala kondili gibahinbahin lamang."}, "source": "NRC PS2.A; DepEd G9-10 momentum; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "impulse-force-times-time-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "impulse is force times time changes momentum", "grades": [9, 10], "terms": ["impulse", "impulso", "puwersa beses oras", "kusog pilo-on sa oras", "pagbabago ng momentum", "pagbag-o sa momentum", "force time", "haba ng pagtama", "gidugayon sa kontak", "longer time", "mas mababang puwersa", "mas gamay nga kusog", "F times t", "change in momentum", "tagal ng dampi", "tugbang"], "fact": {"tl": "Ang impulse ay ang puwersa na pinarami sa haba ng panahon na ito ay umiiral, at ito ang nagdudulot ng pagbabago sa momentum ng isang bagay.", "en": "Impulse is force multiplied by the length of time it acts, and it is what produces a change in an object's momentum.", "bis": "Ang impulse mao ang kusog nga pilo-on sa gidugayon nga kini molihok, ug kini ang hinungdan sa pagbag-o sa momentum sa usa ka butang."}, "source": "NRC PS2.A; DepEd G9-10 momentum and impulse; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "impulse-longer-time-less-force-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "extending impact time reduces force", "grades": [9, 10], "terms": ["impulse", "impulso", "mas mahabang oras", "mas dugay nga oras", "mas mababang puwersa", "mas gamay nga kusog", "pagtama", "hampak", "longer impact", "softer landing", "malambot na pagtigil", "pagbawas ng puwersa", "gipalugway ang oras", "cushion", "pababa ang force", "spreads force", "pagtagal ng dampi"], "fact": {"tl": "Kung pinapahaba ang oras ng pagtama o paghinto, humihina ang puwersang nararanasan sa bawat sandali kahit pareho ang kabuuang pagbabago sa momentum — kaya mas ligtas ito.", "en": "If the time of an impact or stop is stretched out, the force felt at each instant is smaller even though the total change in momentum is the same — making it safer.", "bis": "Kung palugwayon ang oras sa pagbangga o paghunong, mohinay ang kusog nga mabati sa matag gutlo bisan parehas ra ang kinatibuk-ang pagbag-o sa momentum — busa mas luwas kini."}, "source": "NRC PS2.A; DepEd G9-10 impulse-momentum; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "crumple-zone-car-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "crumple zones reduce force in a crash", "grades": [9, 10], "terms": ["crumple zone", "kotse", "sasakyan", "nagigupo na bahagi", "nalukot na harapan", "naluob nga bahin", "banggaan", "aksidente", "crash", "humahaba ang oras ng pagtama", "molugway sa oras", "pinapababa ang puwersa", "mokunhod sa kusog", "kaligtasan", "kaluwasan", "absorbs impact", "sumisipsip ng tama", "front of car", "impulse", "passenger safety"], "fact": {"tl": "Ang crumple zone ay ang bahagi ng kotse na sadyang gumigupo o nalulukot sa banggaan upang humaba ang oras ng pagtama, kaya humihina ang puwersang dumadating sa mga pasahero.", "en": "A crumple zone is the part of a car designed to crush and fold in a crash so the impact takes longer, which lowers the force reaching the passengers.", "bis": "Ang crumple zone mao ang bahin sa awto nga tinuyo nga maluob o malukot sa banggaan aron molugway ang oras sa pagbangga, busa mohinay ang kusog nga moabot sa mga pasahero."}, "source": "NRC PS2.A; DepEd G9-10 impulse-momentum (safety); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "airbag-impulse-safety-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "airbags extend stopping time to reduce force", "grades": [9, 10], "terms": ["airbag", "kotse", "sasakyan", "lumalobo", "mihubag", "lumukso ang hangin", "humahaba ang oras ng paghinto", "molugway sa oras sa paghunong", "pababang puwersa", "mokunhod sa kusog", "ulo", "impulse", "kaligtasan", "kaluwasan", "biglang preno", "kalit nga banggaan", "softens stop", "sumisipsip", "protektado"], "fact": {"tl": "Ang airbag ay biglang lumolobo sa banggaan at humahaba ang oras ng paghinto ng ulo at dibdib, kaya mas mababa ang puwersang tumatama sa katawan.", "en": "An airbag inflates suddenly in a crash and lengthens the time it takes the head and chest to stop, so the force striking the body is smaller.", "bis": "Ang airbag kalit nga mohubag sa banggaan ug molugway sa oras nga mohunong ang ulo ug dughan, busa mas gamay ang kusog nga motugpa sa lawas."}, "source": "NRC PS2.A; DepEd G9-10 impulse-momentum (safety); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "elastic-collision-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "elastic collision conserves kinetic energy", "grades": [9, 10], "terms": ["elastic collision", "elastikong banggaan", "elastik nga banggaan", "kinetic energy", "enerhiya ng galaw", "kusog sa paglihok", "napreserba", "way mawala", "bumabalik", "tumalbog", "nalukso", "bola sa bilyar", "billiard", "bumabangga walang pagkawala", "naipasa lahat", "perfectly elastic", "walang init na nawawala", "nananatili ang enerhiya"], "fact": {"tl": "Sa isang elastikong banggaan, ang mga bagay ay tumatalbog nang halos walang nawawalang enerhiya ng galaw, kaya ang kabuuang kinetic energy ay nananatiling pareho bago at pagkatapos.", "en": "In an elastic collision the objects bounce apart with almost no loss of motion energy, so the total kinetic energy stays the same before and after.", "bis": "Sa usa ka elastik nga banggaan, ang mga butang molukso palayo nga halos walay nawala nga kusog sa paglihok, busa ang kinatibuk-ang kinetic energy magpabilin nga parehas antes ug human."}, "source": "NRC PS2.A, PS3.A; DepEd G9-10 collisions; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "inelastic-collision-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "inelastic collision loses kinetic energy", "grades": [9, 10], "terms": ["inelastic collision", "di-elastikong banggaan", "dili-elastik nga banggaan", "dumikit", "nagdikit", "nag-uros", "kinetic energy", "enerhiya ng galaw", "nawawala bilang init", "nahimong init ug tunog", "deformasyon", "nalukot", "clay", "luwad", "magkasamang gumagalaw", "naghiusa", "stick together", "momentum napreserba pa rin"], "fact": {"tl": "Sa isang di-elastikong banggaan, ang mga bagay ay nagdidikit o nalulukot at ang ilang enerhiya ng galaw ay nagiging init at tunog, ngunit napreserba pa rin ang kabuuang momentum.", "en": "In an inelastic collision the objects stick together or get dented and some motion energy turns into heat and sound, but the total momentum is still conserved.", "bis": "Sa usa ka dili-elastik nga banggaan, ang mga butang magdikit o malukot ug ang pipila ka kusog sa paglihok mahimong init ug tingog, apan ang kinatibuk-ang momentum napreserba gihapon."}, "source": "NRC PS2.A, PS3.A; DepEd G9-10 collisions; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "perfectly-inelastic-stick-together-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "perfectly inelastic collision objects move as one", "grades": [9, 10], "terms": ["perfectly inelastic", "lubusang di-elastiko", "hingpit nga inelastic", "nagdikit", "naghugpong", "magkasamang gumalaw", "magkahiusa molihok", "naghiusa", "tren nga nagdugtong", "coupling", "stick and move together", "magkadikit pagkatapos", "iisang bagay", "isa na lang"], "fact": {"tl": "Sa isang lubusang di-elastikong banggaan, ang mga bagay ay nagdidikit pagkatapos bumangga at sabay na gumagalaw na parang iisang bagay.", "en": "In a perfectly inelastic collision the objects join together after they hit and then move along as a single object.", "bis": "Sa usa ka hingpit nga inelastic nga banggaan, ang mga butang magdikit human mobangga ug dayon molihok nga sama sa usa ka butang."}, "source": "NRC PS2.A; DepEd G9-10 collisions; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "recoil-momentum-gun-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "recoil from conservation of momentum", "grades": [9, 10], "terms": ["recoil", "atras", "pag-atras", "umuurong", "miatras", "kanyon", "cannon", "magkasalungat na momentum", "atbang nga momentum", "kickback", "pabalik na tulak", "konserbasyon ng momentum", "pumuputok", "nagpaputok", "opposite direction", "tumutulak pabalik"], "fact": {"tl": "Kapag pumutok ang isang kanyon, ang bala ay lumilipad pasulong habang ang kanyon ay umuurong pabalik, dahil ang kabuuang momentum ay dapat manatiling pantay.", "en": "When a cannon fires, the ball flies forward while the cannon pushes back, because the total momentum must stay balanced.", "bis": "Kung mobuto ang usa ka kanyon, ang bala molupad pasulong samtang ang kanyon moatras balik, kay ang kinatibuk-ang momentum kinahanglan magpabilin nga balanse."}, "source": "NRC PS2.A; DepEd G9-10 momentum conservation; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rocket-momentum-thrust-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "rockets move by conservation of momentum", "grades": [9, 10], "terms": ["rocket", "rocket ship", "kohete", "gas palabas", "nagbuga ng usok", "ibuga ang gas paubos", "tumutulak pataas", "motulod pataas", "momentum", "konserbasyon", "exhaust", "tambutso", "lumilipad sa kalawakan", "molupad sa kawanangan", "downward gas upward rocket", "thrust", "pwersang itinutulak"], "fact": {"tl": "Ang isang rocket ay umaakyat dahil binubuga nito pababa ang init na gas nang napakabilis, at ayon sa konserbasyon ng momentum, ang rocket naman ay napupwersang pataas.", "en": "A rocket rises because it blasts hot gas downward very fast, and by conservation of momentum the rocket itself is pushed upward.", "bis": "Ang usa ka rocket mosaka tungod kay gibuga niini paubos ang init nga gas nga paspas kaayo, ug sumala sa konserbasyon sa momentum ang rocket gitukmod pataas."}, "source": "NRC PS2.A; DepEd G9-10 momentum conservation; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "heavy-fast-momentum-stopping-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "more momentum is harder to stop", "grades": [9, 10], "terms": ["momentum", "mas mahirap pahintuin", "lisod pahunongon", "mabigat at mabilis", "bug-at ug paspas", "trak", "truck", "mas malaking puwersa", "mas dako nga kusog", "mas mahabang oras", "longer to stop", "stopping distance", "haba ng pagpreno", "lakas ng galaw", "kusog sa paglihok", "mga heavy na sasakyan"], "fact": {"tl": "Kapag mas malaki ang momentum ng isang bagay — dahil mabigat o mabilis ito — mas malaking puwersa o mas mahabang oras ang kailangan upang ito ay tuluyang mapahinto.", "en": "The greater an object's momentum — because it is heavy or fast — the larger the force or the longer the time needed to bring it fully to a stop.", "bis": "Kung mas dako ang momentum sa usa ka butang — tungod kay bug-at o paspas kini — mas dako nga kusog o mas taas nga oras ang gikinahanglan aron kini hingpit nga mohunong."}, "source": "NRC PS2.A; DepEd G9-10 momentum and impulse; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "average-speed-vs-instantaneous-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "average speed versus instantaneous speed", "grades": [9, 10], "terms": ["average speed", "katamtamang bilis", "kasarangang katulin", "instantaneous speed", "bilis sa isang saglit", "katulin sa usa ka gutlo", "speedometer", "buong biyahe", "tibuok biyahe", "kabuuang layo sa kabuuang oras", "kasamtangan nga katulin", "bawat sandali", "matag gutlo", "mean speed", "particular moment"], "fact": {"tl": "Ang average na bilis ay ang kabuuang layo na hinati sa kabuuang oras ng buong biyahe, samantalang ang instantaneous na bilis ay ang bilis sa isang partikular na saglit, gaya ng ipinapakita ng speedometer.", "en": "Average speed is the total distance divided by the total time of a whole trip, while instantaneous speed is the speed at one particular moment, like what a speedometer shows.", "bis": "Ang average nga katulin mao ang kinatibuk-ang gilay-on nga gibahin sa kinatibuk-ang oras sa tibuok biyahe, samtang ang instantaneous nga katulin mao ang katulin sa usa ka partikular nga gutlo, sama sa gipakita sa speedometer."}, "source": "encyclopedia-stable consensus; DepEd G9-10 kinematics", "generator": "claude-workflow", "reviewed": false},
  {"id": "free-fall-acceleration-gravity-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "free fall acceleration due to gravity", "grades": [9, 10], "terms": ["free fall", "malayang paghulog", "gawasnong pagkahulog", "grabidad", "gravity", "aselerasyon", "acceleration", "9.8", "metro kada segundo", "bumibilis paghulog", "mopaspas pagkahulog", "9.8 m/s2", "patuloy na bumibilis", "padayon nga mopaspas", "walang hangin", "way hangin", "vacuum", "downward", "pababa"], "fact": {"tl": "Sa malayang paghulog na walang hangin na humahadlang, ang lahat ng bagay ay bumibilis pababa sa parehong aselerasyon dahil sa grabidad, mga 9.8 metro kada segundo bawat segundo malapit sa lupa.", "en": "In free fall with no air resistance, all objects speed up downward at the same acceleration due to gravity, about 9.8 meters per second each second near the ground.", "bis": "Sa gawasnong pagkahulog nga walay hangin nga mobabag, ang tanang butang mopaspas paubos sa parehas nga aselerasyon tungod sa grabidad, mga 9.8 ka metro kada segundo matag segundo duol sa yuta."}, "source": "NRC PS2.A, PS2.B; encyclopedia-stable consensus; DepEd G9 motion", "generator": "claude-workflow", "reviewed": false},
  {"id": "vector-quantity-direction-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "vector and scalar quantities in motion", "grades": [9, 10], "terms": ["vector", "scalar", "may direksyon", "naay direksyon", "walang direksyon", "way direksyon", "tulin", "velocity", "puwersa", "force", "displacement", "bilis", "speed", "distansya", "lugar at direksyon", "magnitude", "laki at direksyon", "gidaghanon ug direksyon", "magnitude lang"], "fact": {"tl": "Ang ilang dami sa galaw tulad ng velocity, displacement, at puwersa ay vector dahil may laki at direksyon, samantalang ang bilis at distansya ay scalar dahil may laki lang at walang direksyon.", "en": "Some quantities in motion like velocity, displacement, and force are vectors because they have size and direction, while speed and distance are scalars because they have size only and no direction.", "bis": "Ang pipila ka gidaghanon sa lihok sama sa velocity, displacement, ug kusog mga vector kay naay gidak-on ug direksyon, samtang ang katulin ug gilay-on mga scalar kay naay gidak-on lang ug walay direksyon."}, "source": "encyclopedia-stable consensus; DepEd G9-10 kinematics", "generator": "claude-workflow", "reviewed": false},
  {"id": "displacement-can-be-zero-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "displacement can be zero on a round trip", "grades": [9, 10], "terms": ["displacement", "zero displacement", "walang displacement", "way displacement", "bumalik sa simula", "mibalik sa sinugdanan", "round trip", "kabuuang distansya", "kinatibuk-ang gilay-on", "tumatakbo paikot", "midagan paliko", "back to start", "naglakbay pero bumalik", "tuwid na layo zero", "wala mausab nga posisyon"], "fact": {"tl": "Kung ang isang bagay ay bumalik sa eksaktong pinanggalingan nito, ang displacement nito ay zero kahit malaki ang kabuuang distansyang nilakbay.", "en": "If an object returns to its exact starting point, its displacement is zero even though the total distance traveled is large.", "bis": "Kung ang usa ka butang mobalik sa eksakto niyang gigikanan, ang displacement niini zero bisan dako ang kinatibuk-ang gilay-on nga gilaktan."}, "source": "encyclopedia-stable consensus; DepEd G9-10 kinematics", "generator": "claude-workflow", "reviewed": false},
  {"id": "newton-cradle-momentum-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "Newton's cradle shows momentum transfer", "grades": [9, 10], "terms": ["Newton's cradle", "bolang nakabitin", "nagbitay nga bola", "steel balls", "momentum transfer", "naipasa ang momentum", "nabalhin ang momentum", "isang bola palabas", "usa ka bola mogula", "elastikong banggaan", "elastic collision", "kinetic energy napreserba", "nag-untol", "tumama dulo", "pendulum balls", "konserbasyon"], "fact": {"tl": "Sa Newton's cradle, kapag binitawan mo ang isang bolang bakal sa dulo, isang bola lang sa kabilang dulo ang lumilipad palabas dahil naipapasa ang momentum at enerhiya ng galaw sa elastikong banggaan.", "en": "In a Newton's cradle, when you release one steel ball at the end, just one ball flies out the far end because momentum and motion energy pass through the elastic collisions.", "bis": "Sa Newton's cradle, kung buhian nimo ang usa ka steel ball sa tumoy, usa ra ka bola sa pikas tumoy ang molupad gawas tungod kay ang momentum ug kusog sa paglihok mabalhin pinaagi sa elastik nga mga banggaan."}, "source": "NRC PS2.A; encyclopedia-stable consensus; DepEd G9-10 momentum", "generator": "claude-workflow", "reviewed": false},
  {"id": "stopping-distance-speed-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "faster vehicles need longer stopping distance", "grades": [9, 10], "terms": ["stopping distance", "layo ng pagpreno", "gilay-on sa pagpreno", "mas mabilis mas mahabang preno", "mas paspas mas taas nga preno", "braking distance", "reaction distance", "haba ng paghinto", "momentum", "kinetic energy", "kaligtasan sa kalsada", "kaluwasan sa dalan", "speed safety", "doble ang bilis", "longer to stop", "road safety"], "fact": {"tl": "Habang mas mabilis ang isang sasakyan, mas mahaba ang layong kailangan nito upang tuluyang huminto, dahil mas malaki ang momentum at enerhiya ng galaw na kailangang mawala.", "en": "The faster a vehicle moves, the longer the distance it needs to come to a complete stop, because it has more momentum and motion energy to lose.", "bis": "Kung mas paspas ang usa ka sakyanan, mas taas ang gilay-on nga gikinahanglan niini aron hingpit nga mohunong, kay mas dako ang momentum ug kusog sa paglihok nga kinahanglang mawala."}, "source": "NRC PS2.A; DepEd G9-10 momentum and safety; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "two-equal-momentum-collision-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "equal and opposite momenta can cancel", "grades": [9, 10], "terms": ["pantay na momentum", "parehas nga momentum", "magkasalungat na direksyon", "atbang nga direksyon", "nagkansela", "nawala", "head-on collision", "harapang banggaan", "atubangay nga banggaan", "huminto pareho", "naghunong silang duha", "kabuuang momentum zero", "kinatibuk-ang momentum zero", "magkatumbas na bigat at bilis", "opposite directions"], "fact": {"tl": "Kapag dalawang bagay na may pantay na momentum ngunit magkasalungat na direksyon ang nagbangga nang magkadikit, maaaring magkansela ang kanilang momentum at sabay silang huminto.", "en": "When two objects with equal momentum but opposite directions collide and stick, their momenta can cancel out and they both stop.", "bis": "Kung duha ka butang nga parehas og momentum apan atbang og direksyon ang magbangga ug magdikit, mahimong magkansela ang ilang momentum ug mohunong silang duha."}, "source": "NRC PS2.A; DepEd G9-10 momentum conservation; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "uniform-acceleration-equal-velocity-steps-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "uniform acceleration adds equal velocity each second", "grades": [9, 10], "terms": ["uniform acceleration", "pare-parehong aselerasyon", "parehas nga aselerasyon", "pantay na dagdag sa tulin", "managsama nga dugang sa katulin", "bawat segundo", "matag segundo", "patuloy na bumibilis", "padayon nga mopaspas", "constant acceleration", "tuwid na linya sa velocity graph", "free fall", "steady increase", "gradual speed up", "equal change"], "fact": {"tl": "Kapag pare-pareho ang aselerasyon ng isang bagay, pantay-pantay ang dagdag sa tulin nito bawat segundo, kaya tuloy-tuloy at maayos itong bumibilis.", "en": "When an object has uniform acceleration, its velocity increases by the same amount each second, so it speeds up steadily and evenly.", "bis": "Kung parehas ra ang aselerasyon sa usa ka butang, managsama ang dugang sa katulin niini matag segundo, busa padayon ug hapsay kining mopaspas."}, "source": "encyclopedia-stable consensus; DepEd G9-10 kinematics", "generator": "claude-workflow", "reviewed": false},
  {"id": "force-changes-momentum-rate-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "force equals rate of change of momentum", "grades": [9, 10], "terms": ["puwersa", "force", "rate of change of momentum", "bilis ng pagbabago ng momentum", "kapaspason sa pagbag-o sa momentum", "pagbabago ng momentum kada oras", "Newton second law", "ikalawang batas ni Newton", "mas mabilis na pagbabago", "mas dako nga kusog", "impulse", "F times t", "mas malaking puwersa", "change per second"], "fact": {"tl": "Ang puwersa ay kung gaano kabilis nagbabago ang momentum ng isang bagay, kaya kapag mas mabilis mong binago ang momentum nito, mas malaking puwersa ang kailangan.", "en": "Force is how quickly an object's momentum changes, so the faster you change its momentum, the larger the force required.", "bis": "Ang kusog mao kung unsa ka paspas mausab ang momentum sa usa ka butang, busa kung mas paspas nimo usabon ang momentum niini, mas dako nga kusog ang gikinahanglan."}, "source": "NRC PS2.A; DepEd G9-10 Newton's second law and momentum; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "projectile-two-independent-motions-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "projectile horizontal and vertical motion are independent", "grades": [9, 10], "terms": ["projectile", "independent", "magkahiwalay", "pahalang", "patayo", "horizontal", "vertical", "gravity", "gravidad", "walay-labot", "kaugalingon", "pababa", "unahan", "pasulong", "galaw", "lihok", "motion", "komponent", "bahin"], "fact": {"tl": "Sa projectile motion, ang pahalang (forward) at patayong (pababa) galaw ay magkahiwalay: walang epekto ang isa sa isa, kaya ang pahalang na bilis ay nananatili habang ang patayong galaw ay binabago ng gravity.", "en": "In projectile motion the horizontal (forward) and vertical (downward) motions are independent of each other, so the forward speed stays the same while gravity changes only the vertical motion.", "bis": "Sa projectile motion, ang pahalang (pasulong) ug patindog (paubos) nga lihok managlahi: walay epekto ang usa sa usa, mao nga ang pahalang nga katulin magpabilin samtang ang gravity mausab lang ang patindog nga lihok."}, "source": "AAAS 4F/H1; NRC PS2.A; DepEd G9 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "projectile-horizontal-velocity-constant-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "projectile horizontal velocity stays constant", "grades": [9, 10], "terms": ["horizontal velocity", "pahalang na bilis", "pareho", "constant", "walang puwersa", "no force", "resistensya", "hangin", "air resistance", "pasulong", "katulin", "magpabilin", "tuloy-tuloy"], "fact": {"tl": "Kung wala ang resistensya ng hangin, ang pahalang na bilis ng isang projectile ay nananatiling pareho sa buong paglipad dahil walang pahalang na puwersang nagpapabagal dito.", "en": "Ignoring air resistance, a projectile's horizontal velocity stays constant for the whole flight because no horizontal force acts to slow it down.", "bis": "Kung wala ang resistensya sa hangin, ang pahalang nga katulin sa projectile magpabilin nga pareho sa tibuok paglupad kay walay pahalang nga puwersa nga magpahinay niini."}, "source": "AAAS 4F/H8; NRC PS2.A; DepEd G9 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "projectile-vertical-accelerates-gravity-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "projectile vertical motion accelerates due to gravity", "grades": [9, 10], "terms": ["vertical", "patayo", "bumibilis", "accelerate", "gravity", "gravidad", "pababa", "bumagsak", "nahuhulog", "mahulog", "bumababa", "pataas", "velocity", "katulin", "paspas"], "fact": {"tl": "Habang lumilipad ang projectile, hinihila ito pababa ng gravity kaya ang patayong bahagi ng galaw ay bumabagal kapag pataas at lalong bumibilis kapag pababa.", "en": "As a projectile flies, gravity pulls it down, so the vertical part of its motion slows while rising and speeds up while falling.", "bis": "Samtang naglupad ang projectile, ang gravity nagbira niini paubos mao nga ang patindog nga bahin sa lihok mohinay kung pasaka ug mas mopaspas kung paubos."}, "source": "AAAS 4F/H1; NRC PS2.A; DepEd G9 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "projectile-parabola-shape-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "projectile path is a parabola", "grades": [9, 10], "terms": ["parabola", "hugis", "curved path", "arko", "arc", "kurba", "baluktot", "landas", "dalan", "agianan", "simetriko", "symmetric", "trajectory", "binabato", "gitambog", "gilabay"], "fact": {"tl": "Ang landas ng isang projectile ay isang parabola — isang simetrikong kurba na pataas muna saka pababa — dahil sa sabay na pahalang na galaw at patayong paghila ng gravity.", "en": "A projectile's path is a parabola — a symmetric curve that rises then falls — because of its steady forward motion combined with gravity's downward pull.", "bis": "Ang agianan sa projectile usa ka parabola — usa ka simetriko nga kurba nga mosaka una dayon mokunsad — tungod sa makanunayon nga pahalang nga lihok ug ang paubos nga bira sa gravity."}, "source": "AAAS 4F/H1; NRC PS2.A; DepEd G9 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "projectile-range-optimal-45-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "projectile maximum range at 45 degrees", "grades": [10], "terms": ["range", "layo", "pinakamalayo", "abot", "distansya", "45 degrees", "anggulo", "angle", "optimal", "maximum", "ihagis", "ilabay", "pinakamalayong", "gilay-on"], "fact": {"tl": "Kung walang resistensya ng hangin at pantay ang lupa, pinakamalayo ang abot (range) ng isang itinapong bagay kapag inihagis ito sa anggulong 45 degrees.", "en": "With no air resistance and level ground, a thrown object travels the farthest (greatest range) when it is launched at an angle of 45 degrees.", "bis": "Kung walay resistensya sa hangin ug patag ang yuta, pinakalayo ang abot (range) sa gilabay nga butang kung ilabay kini sa anggulo nga 45 degrees."}, "source": "AAAS 4F/H1; consensus physics; DepEd G10 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "projectile-complementary-angles-same-range-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "complementary launch angles give the same range", "grades": [10], "terms": ["complementary", "anggulo", "angle", "pareho", "same range", "30", "60", "magkapares", "abot", "layo", "distansya", "mataas", "mababa", "launch", "ihagis", "ilabay", "gilay-on"], "fact": {"tl": "Dalawang anggulo na nagsusuma ng 90 degrees (gaya ng 30 at 60) ay nagbibigay ng parehong range, pero mas mataas at mas matagal ang paglipad ng inihagis sa mas matarik na anggulo.", "en": "Two launch angles that add up to 90 degrees (such as 30 and 60) give the same range, but the steeper angle makes the object go higher and stay in the air longer.", "bis": "Duha ka anggulo nga magsuma og 90 degrees (sama sa 30 ug 60) maghatag og parehong range, apan ang mas tul-id nga anggulo maghimo sa butang nga mosaka og mas taas ug magdugay sa hangin."}, "source": "consensus physics; DepEd G10 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "projectile-time-of-flight-depends-vertical-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "projectile time of flight depends on vertical motion", "grades": [10], "terms": ["time of flight", "tagal", "panahon sa hangin", "oras", "gaano katagal", "patayo", "vertical", "taas", "height", "pababa", "mahulog", "bumagsak", "independent", "walay-labot", "molungtad"], "fact": {"tl": "Ang tagal ng isang projectile sa hangin ay nakadepende lamang sa patayong galaw (gaano ito kataas umakyat), hindi sa kung gaano kabilis ito pasulong.", "en": "How long a projectile stays in the air depends only on its vertical motion (how high it goes up), not on how fast it moves forward.", "bis": "Ang kadugayon sa projectile sa hangin nagdepende lamang sa patindog nga lihok (kung unsa kini kataas mosaka), dili sa kung unsa kini kapaspas pasulong."}, "source": "consensus physics; AAAS 4F/H1; DepEd G10 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "horizontal-drop-land-same-time-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "dropped and horizontally thrown objects land together", "grades": [10], "terms": ["dropped", "ibinagsak", "horizontally thrown", "inihagis pahalang", "sabay", "same time", "dungan", "lupa", "mahulog", "bumagsak", "gravity", "gravidad", "patayo", "vertical", "magsabay"], "fact": {"tl": "Isang bagay na ibinagsak nang tuwid pababa at isa pang inihagis nang pahalang mula sa parehong taas ay sabay na tatama sa lupa, dahil pareho silang hinihila ng gravity sa patayong direksyon.", "en": "An object dropped straight down and one thrown horizontally from the same height hit the ground at the same time, because gravity pulls both downward in the same way.", "bis": "Ang butang nga gibitik tul-id paubos ug ang gilabay nga pahalang gikan sa parehong gitas-on managsama nga moigo sa yuta, kay ang gravity nagbira sa duha paubos sa samang paagi."}, "source": "consensus physics; AAAS 4F/H1; DepEd G10 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "free-fall-equal-rate-no-air-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "objects fall at the same rate without air resistance", "grades": [9, 10], "terms": ["free fall", "malayang paghulog", "bumabagsak", "nahuhulog", "mabug-at", "magaan", "heavy", "light", "pareho", "same rate", "sabay", "walang hangin", "vacuum", "resistensya", "gravidad", "gravity", "mahulog"], "fact": {"tl": "Kapag walang resistensya ng hangin, ang mabigat at magaang bagay ay bumabagsak nang magkasabay dahil pareho ang acceleration na dulot ng gravity sa lahat ng masa.", "en": "Without air resistance, heavy and light objects fall at exactly the same rate because gravity gives every mass the same acceleration.", "bis": "Kung walay resistensya sa hangin, ang mabug-at ug magaan nga butang manghulog nga dungan kay parehas ra ang acceleration nga gihatag sa gravity sa tanang masa."}, "source": "consensus physics (Galileo); AAAS 4G/H1; DepEd G9 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "air-resistance-affects-real-projectiles-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "air resistance changes real projectile paths", "grades": [10], "terms": ["air resistance", "resistensya ng hangin", "hangin", "drag", "totoong", "real", "mas maikli", "shorter range", "bumabagal", "nagpapabagal", "bola", "papel", "magaan", "feather", "balahibo", "mubo"], "fact": {"tl": "Sa totoong buhay, pinipigil ng resistensya ng hangin ang projectile kaya mas maikli ang range nito at hindi perpektong parabola ang landas, lalo na para sa magagaang bagay.", "en": "In real life, air resistance pushes back on a projectile, making its range shorter and its path not a perfect parabola, especially for light objects.", "bis": "Sa tinuod nga kinabuhi, ang resistensya sa hangin magpugong sa projectile mao nga mas mubo ang range niini ug dili hingpit nga parabola ang agianan, ilabi na para sa magaan nga mga butang."}, "source": "AAAS 4F/H7; consensus physics; DepEd G10 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "uniform-circular-motion-constant-speed-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "uniform circular motion has constant speed changing direction", "grades": [9, 10], "terms": ["uniform circular motion", "pabilog na galaw", "constant speed", "pareho ang bilis", "nagbabago ang direksyon", "direksyon", "direction", "bilog", "lihok", "umiikot", "umiinog", "tuloy-tuloy", "velocity", "katulin"], "fact": {"tl": "Sa uniform circular motion, gumagalaw ang isang bagay sa bilog na may pareho ang bilis, pero patuloy na nagbabago ang direksyon nito sa bawat sandali.", "en": "In uniform circular motion an object moves around a circle at a constant speed, but its direction keeps changing at every moment.", "bis": "Sa uniform circular motion, ang butang molihok libot sa lingin sa parehong katulin, apan kanunay nga mausab ang direksyon niini matag gutlo."}, "source": "AAAS 4F/M3; consensus physics; DepEd G9 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "centripetal-force-points-to-center-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "centripetal force points toward the center", "grades": [9, 10], "terms": ["centripetal force", "puwersa", "papasentro", "toward center", "gitna", "sentro", "center", "papuntang loob", "inward", "humihila", "hinihila", "bumilog", "pabilog", "ngadto sa tunga", "sulod"], "fact": {"tl": "Ang centripetal force ay ang puwersang nakaturo papunta sa gitna ng bilog, at ito ang humihila sa isang bagay para manatili sa pabilog nitong landas.", "en": "Centripetal force is the force directed toward the center of a circle, and it is what pulls an object so that it keeps following its curved, circular path.", "bis": "Ang centripetal force mao ang puwersa nga nagtumong ngadto sa tunga sa lingin, ug mao kini ang nagbira sa butang aron magpabilin sa iyang kurba, lingin nga agianan."}, "source": "AAAS 4F/M3; NRC PS2.A; DepEd G9 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "centripetal-force-changes-direction-not-speed-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "centripetal force changes direction not speed", "grades": [9, 10], "terms": ["centripetal", "puwersa", "direksyon lang", "binabago ang direksyon", "hindi bilis", "not speed", "nagliliko", "liko", "turn", "direction", "papasentro", "katulin", "direksyon"], "fact": {"tl": "Ang centripetal force ay nagbabago lamang ng direksyon ng galaw, hindi ng bilis, kaya nananatiling pantay ang bilis sa uniform circular motion habang patuloy na lumiliko.", "en": "Centripetal force changes only the direction of the motion, not the speed, which is why the speed stays the same in uniform circular motion even as it keeps turning.", "bis": "Ang centripetal force mausab lamang ang direksyon sa lihok, dili ang katulin, mao nga magpabilin nga pareho ang katulin sa uniform circular motion bisan magpadayon kini sa pagliko."}, "source": "AAAS 4F/M3; consensus physics; DepEd G9 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "centripetal-acceleration-toward-center-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "centripetal acceleration points to the center", "grades": [10], "terms": ["centripetal acceleration", "acceleration", "pagbilis", "papasentro", "toward center", "gitna", "sentro", "nagbabago direksyon", "velocity", "bilog", "umiikot", "katulin", "tunga"], "fact": {"tl": "Kahit pantay ang bilis, ang isang bagay sa circular motion ay may acceleration na nakaturo papasentro, dahil patuloy na nagbabago ang direksyon ng velocity nito.", "en": "Even at constant speed, an object in circular motion has an acceleration pointing toward the center, because the direction of its velocity keeps changing.", "bis": "Bisan pareho ang katulin, ang butang sa circular motion adunay acceleration nga nagtumong ngadto sa tunga, kay kanunay nga mausab ang direksyon sa velocity niini."}, "source": "consensus physics; AAAS 4F/M3; DepEd G10 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "no-centripetal-force-fly-straight-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "without centripetal force object flies off straight", "grades": [9, 10], "terms": ["centripetal", "nawala", "puwersa", "tuwid", "straight line", "diretso", "tangent", "lumilipad palabas", "fly off", "inertia", "lubid", "string", "naputol", "tul-id", "molupad"], "fact": {"tl": "Kung biglang mawala ang centripetal force (halimbawa, maputol ang lubid), ang umiikot na bagay ay lilipad palabas sa tuwid na linya, hindi patuloy na bilog.", "en": "If the centripetal force suddenly disappears (for example, the string breaks), the spinning object flies off in a straight line, not in a continuing circle.", "bis": "Kung kalit nga mawala ang centripetal force (pananglitan, mabugto ang pisi), ang nagtuyok nga butang molupad pagawas sa tul-id nga linya, dili magpadayon sa pagtuyok."}, "source": "AAAS 4F/H8; consensus physics; DepEd G9 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "centrifugal-feeling-is-inertia-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "the outward push in a turn is inertia", "grades": [10], "terms": ["centrifugal", "tila itinutulak palabas", "outward", "sasakyan", "liko", "turn", "inertia", "tuloy-tuloy", "tuwid", "straight", "apparent", "tila puwersa", "gibira pagawas", "kilid"], "fact": {"tl": "Ang pakiramdam na itinutulak ka palabas kapag lumiliko ang sasakyan ay hindi tunay na puwersa kundi inertia — gusto ng iyong katawan na magtuloy nang tuwid habang lumiliko ang sasakyan.", "en": "The feeling of being pushed outward when a car turns is not a real force but inertia — your body wants to keep going straight while the car curves.", "bis": "Ang pagbati nga giduso ka pagawas kung moliko ang sakyanan dili tinuod nga puwersa kondili inertia — ang imong lawas gusto magpadayon nga tul-id samtang ang sakyanan moliko."}, "source": "AAAS 4F/H8; NRC PS2.A; DepEd G10 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "friction-as-centripetal-car-turn-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "friction provides centripetal force when a car turns", "grades": [10], "terms": ["friction", "kuskos", "gulong", "tires", "liko", "car turn", "sasakyan", "centripetal", "puwersa", "papasentro", "madulas", "slippery", "wala friction", "dumulas", "slip", "ligid"], "fact": {"tl": "Kapag lumiliko ang sasakyan, ang friction sa pagitan ng gulong at kalsada ang nagbibigay ng centripetal force; kapag madulas ang daan, kulang ito kaya maaaring dumulas ang sasakyan palabas.", "en": "When a car turns, friction between the tires and the road provides the centripetal force; on a slippery road that force is too small, so the car can slide outward.", "bis": "Kung moliko ang sakyanan, ang friction tali sa ligid ug dalan maoy maghatag sa centripetal force; sa danlog nga dalan kulang kini nga puwersa, mao nga ang sakyanan mahimong modaplos pagawas."}, "source": "AAAS 4G/H2; consensus physics; DepEd G10 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "period-frequency-circular-motion-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "period and frequency in circular motion", "grades": [10], "terms": ["period", "panahon", "isang ikot", "one revolution", "frequency", "dalas", "bilang ng ikot", "ilang beses", "kada segundo", "per second", "umiikot", "makausa", "kadaghanon", "pag-tuyok"], "fact": {"tl": "Ang period ay ang oras na inaabot para makaikot nang isang beses, samtang ang frequency ay kung ilang ikot ang nagagawa kada segundo — magkabaligtad ang dalawa.", "en": "The period is the time it takes to go around once, while the frequency is how many turns happen each second — the two are inverses of each other.", "bis": "Ang period mao ang panahon nga gikinahanglan aron makalibot makausa, samtang ang frequency mao kung pila ka libot ang mahimo kada segundo — magbaliktad ang duha."}, "source": "consensus physics; DepEd G10 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "faster-spin-more-centripetal-force-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "faster or tighter circles need more centripetal force", "grades": [10], "terms": ["mas mabilis", "faster", "mas masikip", "tighter circle", "maliit na bilog", "smaller radius", "radius", "mas malaking puwersa", "more force", "centripetal", "kailangan", "masa", "mass", "mas dako", "gamay nga lingin"], "fact": {"tl": "Mas malaking centripetal force ang kailangan kapag mas mabilis ang ikot, mas masikip (mas maliit) ang bilog, o mas mabigat ang umiikot na bagay.", "en": "More centripetal force is needed when the spin is faster, the circle is tighter (smaller), or the spinning object is heavier.", "bis": "Mas dako nga centripetal force ang gikinahanglan kung mas paspas ang tuyok, mas gamay ang lingin, o mas bug-at ang nagtuyok nga butang."}, "source": "consensus physics; AAAS 4F/H1; DepEd G10 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "satellite-orbit-balance-gravity-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "gravity is the centripetal force for orbits", "grades": [9, 10], "terms": ["satellite", "satelayt", "orbita", "orbit", "gravity", "gravidad", "centripetal", "puwersang papasentro", "umiikot", "Earth", "Mundo", "Daigdig", "papasentro", "libot", "yuta"], "fact": {"tl": "Para sa isang satellite na umiikot sa Mundo, ang gravity mismo ang gumaganap bilang centripetal force na humihila dito papasentro at nagpapanatili sa orbita nito.", "en": "For a satellite orbiting Earth, gravity itself acts as the centripetal force that pulls it toward the center and keeps it in its orbit.", "bis": "Para sa satellite nga naglibot sa Yuta, ang gravity mismo maoy nagsilbing centripetal force nga nagbira niini ngadto sa tunga ug nagpabilin niini sa orbita."}, "source": "AAAS 4G/M2; NRC PS2.B; DepEd G9 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "satellite-orbital-speed-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "satellites need a specific high sideways speed to orbit", "grades": [10], "terms": ["orbital speed", "bilis", "mabilis", "fast sideways", "pahalang na bilis", "tamang bilis", "just right", "satellite", "satelayt", "umiikot", "mahulog", "escape", "sideways", "katulin sa orbita"], "fact": {"tl": "Para manatili sa orbita, kailangang sapat ang pahalang na bilis ng isang satellite: kung masyadong mabagal, mahuhulog ito; kung masyadong mabilis, lilipad ito palabas ng orbita.", "en": "To stay in orbit a satellite needs just the right high sideways speed: too slow and it falls back, too fast and it flies off out of orbit.", "bis": "Aron magpabilin sa orbita, kinahanglan igo ang pahalang nga katulin sa satellite: kung hinay kaayo, mahulog kini; kung paspas kaayo, molupad kini pagawas sa orbita."}, "source": "consensus physics; AAAS 4G/M2; DepEd G10 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "orbit-is-continuous-falling-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "an orbit is continuous falling around Earth", "grades": [10], "terms": ["orbit", "orbita", "tuloy-tuloy na paghulog", "continuous falling", "laging nahuhulog", "bumabagsak", "sideways", "pahalang", "nakakalampas sa kurba", "misses the curve", "curve", "satellite", "Newton", "cannonball", "kanyon", "kurba"], "fact": {"tl": "Ang isang orbita ay parang tuloy-tuloy na paghulog: laging hinihila pababa ng gravity ang satellite, pero dahil sobrang bilis nito pahalang, lagi nitong nalalampasan ang kurba ng Mundo kaya umiikot ito sa halip na bumagsak.", "en": "An orbit is like continuous falling: gravity always pulls the satellite down, but because it moves so fast sideways it keeps missing the curve of Earth, so it circles instead of crashing.", "bis": "Ang orbita sama sa padayon nga pagkahulog: kanunay nga gibira paubos sa gravity ang satellite, apan tungod kay paspas kaayo kini pahalang, kanunay niini malabwan ang kurba sa Yuta mao nga molibot kini imbes mahagsa."}, "source": "consensus physics (Newton); AAAS 4G/M2; DepEd G10 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "moon-orbit-gravity-centripetal-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "the Moon stays in orbit by Earth's gravity as centripetal force", "grades": [9, 10], "terms": ["moon", "buwan", "bulan", "umiikot", "orbita", "Earth", "Mundo", "gravity", "gravidad", "centripetal", "puwersang papasentro", "hinihila", "libot", "natural satellite", "kalibutan", "gibira"], "fact": {"tl": "Ang Buwan ay nananatili sa orbita nito dahil ang gravity ng Mundo ang nagsisilbing centripetal force na patuloy na humihila rito papasentro, kaya hindi ito lumilipad palabas sa kalawakan.", "en": "The Moon stays in its orbit because Earth's gravity acts as the centripetal force that keeps pulling it toward the center, so it does not fly off into space.", "bis": "Ang Bulan magpabilin sa iyang orbita kay ang gravity sa Yuta maoy nagsilbing centripetal force nga padayon nga nagbira niini ngadto sa tunga, mao nga dili kini molupad pagawas sa kawanangan."}, "source": "AAAS 4G/M2; NRC PS2.B; DepEd G9 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "planets-orbit-sun-gravity-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "the Sun's gravity holds planets in orbit", "grades": [9, 10], "terms": ["planeta", "planet", "araw", "adlaw", "sun", "gravity", "gravidad", "orbita", "orbit", "umiikot", "centripetal", "puwersa", "hinihila", "solar system", "libot sa araw", "gibira", "sistema sa adlaw"], "fact": {"tl": "Ang gravity ng Araw ang humihila sa mga planeta papasentro at nagsisilbing centripetal force, kaya nananatili silang umiikot sa kanilang orbita sa halip na lumipad palayo.", "en": "The Sun's gravity pulls the planets toward the center and acts as the centripetal force, so they keep moving in their orbits instead of flying away.", "bis": "Ang gravity sa Adlaw nagbira sa mga planeta ngadto sa tunga ug nagsilbing centripetal force, mao nga magpadayon sila sa paglibot sa ilang orbita imbes molupad palayo."}, "source": "AAAS 4G/M2; NRC ESS1.B; DepEd G9 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "astronaut-weightless-freefall-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "astronauts float because they are in free fall", "grades": [10], "terms": ["astronaut", "astronawt", "lumulutang", "weightless", "walang timbang", "floating", "kawalan ng timbang", "free fall", "malayang paghulog", "spaceship", "sasakyang pangkalawakan", "orbit", "naglutaw", "walay gibug-aton"], "fact": {"tl": "Lumulutang ang mga astronaut sa loob ng umiikot na spaceship hindi dahil walang gravity, kundi dahil sila at ang kanilang sasakyan ay sabay na 'bumabagsak' patungo sa Mundo habang umiikot ito.", "en": "Astronauts float inside an orbiting spaceship not because there is no gravity, but because they and their ship are 'falling' toward Earth together as it circles.", "bis": "Ang mga astronaut maglutaw sulod sa naglibot nga spaceship dili tungod kay walay gravity, kondili tungod kay sila ug ang ilang sakyanan dungan nga 'nahulog' paingon sa Yuta samtang naglibot kini."}, "source": "consensus physics; NRC PS2.B; DepEd G10 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "banked-road-helps-turning-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "banked curves help vehicles turn safely", "grades": [10], "terms": ["banked", "nakatagilid na kalsada", "banked curve", "kurba", "liko", "race track", "ekspresway", "tilted road", "tagilid", "centripetal", "tumutulong", "puwersa", "ligtas na liko", "kurbada", "hilig sa dalan", "nakahilig"], "fact": {"tl": "Ang mga nakatagilid (banked) na kurba sa kalsada ay tumutulong sa mga sasakyan na lumiko nang ligtas dahil ang pagkakatagilid ay nagbibigay ng dagdag na centripetal force papasentro.", "en": "Banked (tilted) curves on a road help vehicles turn safely because the tilt adds extra centripetal force directed toward the center of the curve.", "bis": "Ang mga nakahilig (banked) nga kurba sa dalan motabang sa mga sakyanan nga moliko nga luwas kay ang paghilig maghatag og dugang centripetal force ngadto sa tunga sa kurba."}, "source": "consensus physics; AAAS 4F/M3; DepEd G10 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "projectile-max-height-at-top-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "projectile reaches max height when vertical speed is zero", "grades": [10], "terms": ["maximum height", "pinakamataas", "tuktok", "top of arc", "patayong bilis sero", "vertical speed zero", "huminto pataas", "sandaling huminto", "saglit", "momentarily", "pababa na", "peak", "taluktok", "mihunong"], "fact": {"tl": "Naaabot ng isang projectile ang pinakamataas nitong punto kapag naging sero na ang patayong bilis nito; sandaling huminto ang pag-akyat bago ito magsimulang bumagsak pababa.", "en": "A projectile reaches its highest point when its vertical speed becomes zero; for an instant it stops rising before it starts to fall back down.", "bis": "Maabot sa projectile ang pinakataas niini nga punto kung ang patindog nga katulin niini mahimong sero; sa makadiyot mohunong kini sa pagsaka una mosugod og kahulog pabalik."}, "source": "consensus physics; DepEd G10 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "projectile-symmetry-up-down-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "projectile rise and fall are symmetric", "grades": [10], "terms": ["symmetry", "simetriko", "pantay", "pagakyat at pagbaba", "up and down", "parehong oras", "same time", "pareho ang bilis", "launch speed", "landing speed", "magkapareho", "balik", "susama"], "fact": {"tl": "Sa landas ng projectile na walang resistensya ng hangin, kasing tagal ang pag-akyat at pagbaba, at ang bilis pagdating sa lupa ay kapareho ng bilis pag-alis nito.", "en": "In a projectile's path with no air resistance, the time going up equals the time coming down, and its speed when it lands equals its launch speed.", "bis": "Sa agianan sa projectile nga walay resistensya sa hangin, parehas ang panahon sa pagsaka ug pagkanaog, ug ang katulin pag-abot sa yuta parehas sa katulin pag-gikan niini."}, "source": "consensus physics; DepEd G10 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "newton-first-law-circular-needs-force-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "circular motion needs a constant inward force by Newton's first law", "grades": [9, 10], "terms": ["Newton", "unang batas", "first law", "inertia", "tuwid na linya", "straight line", "kailangan ng puwersa", "needs force", "pabilog", "circular", "liko", "walang puwersa diretso", "constant force", "puwersang papasentro", "tul-id", "kinahanglan puwersa"], "fact": {"tl": "Ayon sa unang batas ni Newton, gugustuhin ng isang gumagalaw na bagay na magtuloy sa tuwid na linya, kaya kailangan ng tuloy-tuloy na puwersang papasentro para mapanatili itong umiikot sa bilog.", "en": "By Newton's first law a moving object naturally wants to keep going in a straight line, so a constant inward force is needed to keep it moving in a circle.", "bis": "Sumala sa unang balaod ni Newton, ang naglihok nga butang gusto magpadayon sa tul-id nga linya, mao nga kinahanglan ang padayon nga puwersa paingon sa tunga aron magpabilin kini nga molibot sa lingin."}, "source": "AAAS 4F/H8; NRC PS2.A; DepEd G9 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "projectile-launch-speed-affects-range-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "greater launch speed gives greater range", "grades": [10], "terms": ["launch speed", "bilis ng paghagis", "mas mabilis", "faster throw", "mas malayo", "greater range", "abot", "layo", "distansya", "initial velocity", "panimulang bilis", "lakas", "katulin", "ilabay"], "fact": {"tl": "Sa parehong anggulo, mas malayo ang abot (range) ng isang projectile kapag mas mabilis ang panimulang bilis nito sa paghagis.", "en": "At the same angle, a projectile travels a greater range when its launch speed is faster.", "bis": "Sa parehong anggulo, mas layo ang abot (range) sa projectile kung mas paspas ang sinugdanang katulin niini sa paglabay."}, "source": "consensus physics; DepEd G10 Q4", "generator": "claude-workflow", "reviewed": false},
  {"id": "continental-drift-wegener-g9", "domain": "EARTH_SPACE", "topic": "continental drift theory", "grades": [9, 10], "terms": ["continental drift", "Alfred Wegener", "kontinental na pag-anod", "paggalaw ng kontinente", "continental drift theory", "supercontinent", "naglayag", "naglalayo", "pag-anod sa kontinente", "naglalakaw ang kontinente", "teorya"], "fact": {"tl": "Noong 1912, iminungkahi ng siyentistang si Alfred Wegener ang continental drift — ang ideyang ang mga kontinente ay dating magkadikit at dahan-dahang naglalayo sa isa't isa sa paglipas ng milyon-milyong taon.", "en": "In 1912, the scientist Alfred Wegener proposed continental drift — the idea that the continents were once joined together and have slowly moved apart over millions of years.", "bis": "Niadtong 1912, gisugyot sa siyentista nga si Alfred Wegener ang continental drift — ang ideya nga ang mga kontinente kaniadto nagdikit ug hinay-hinay nga nagbulag sa usag usa sulod sa minilyon nga katuigan."}, "source": "AAAS BSL 4C/H; consensus history of geology", "generator": "claude-workflow", "reviewed": false},
  {"id": "pangaea-supercontinent-g9", "domain": "EARTH_SPACE", "topic": "Pangaea supercontinent", "grades": [9, 10], "terms": ["Pangaea", "Pangea", "supercontinent", "isang malaking kontinente", "dating magkadikit", "supercontinent", "usa ka dako nga kontinente", "nagdikit kaniadto", "nahimulag", "nabuwag", "isang masa ng lupa"], "fact": {"tl": "Mga 300 milyong taon na ang nakalipas, ang lahat ng kontinente ng Earth ay pinaniniwalaang nagsama-sama sa isang higanteng masa ng lupa na tinatawag na Pangaea, na unti-unting nahati at naglayo upang mabuo ang mga kontinente ngayon.", "en": "About 300 million years ago, all of Earth's continents are believed to have been joined in one giant landmass called Pangaea, which slowly broke apart and drifted to form today's continents.", "bis": "Mga 300 ka milyon ka tuig na ang milabay, ang tanang kontinente sa Earth gituohan nga naghiusa sa usa ka dako kaayo nga yuta nga gitawag og Pangaea, nga hinay-hinay nga nabuak ug nagbulag aron maporma ang mga kontinente karon."}, "source": "AAAS BSL 4C/H; consensus historical geology", "generator": "claude-workflow", "reviewed": false},
  {"id": "drift-evidence-matching-coasts-g9", "domain": "EARTH_SPACE", "topic": "evidence for continental drift", "grades": [9, 10], "terms": ["matching coastlines", "magkatugmang baybayin", "South America", "Africa", "jigsaw puzzle", "magkasya", "magkakatugma", "ebidensya", "South America ug Africa", "nagdugtong", "hugis baybayin", "katumbas"], "fact": {"tl": "Isang ebidensya ng continental drift ay ang magkatugmang hugis ng mga baybayin — halimbawa, ang silangang baybayin ng South America at ang kanlurang baybayin ng Africa ay tila magkakasya na parang piyesa ng jigsaw puzzle.", "en": "One piece of evidence for continental drift is the matching shape of coastlines — for example, the east coast of South America and the west coast of Africa look like they would fit together like pieces of a jigsaw puzzle.", "bis": "Usa ka ebidensya sa continental drift mao ang nagkatakdo nga porma sa mga baybayon — pananglitan, ang sidlakang baybayon sa South America ug ang kasadpang baybayon sa Africa morag mohaom sama sa mga piraso sa jigsaw puzzle."}, "source": "AAAS BSL 4C/H; consensus geology", "generator": "claude-workflow", "reviewed": false},
  {"id": "drift-evidence-fossils-g9", "domain": "EARTH_SPACE", "topic": "fossil evidence for drift", "grades": [9, 10], "terms": ["fossil evidence", "matching fossils", "magkatulad na fossils", "magkahiwalay na kontinente", "Mesosaurus", "pareho ang fossil", "ebidensya ng fossil", "managsama nga fossil", "nahimulag nga kontinente", "magkalayong lupa", "halaman at hayop"], "fact": {"tl": "Magkatulad na fossils ng parehong sinaunang halaman at hayop ang natagpuan sa mga kontinenteng ngayon ay magkakalayo na, na nagpapakitang dating magkadikit ang mga lupaing ito.", "en": "Identical fossils of the same ancient plants and animals are found on continents that are now far apart, showing that these lands were once joined together.", "bis": "Managsamang fossil sa parehas nga karaang tanom ug hayop nakit-an sa mga kontinente nga karon nagkalayo na, nga nagpakita nga kini nga mga yuta nagdikit kaniadto."}, "source": "AAAS BSL 4C/H; consensus paleogeography", "generator": "claude-workflow", "reviewed": false},
  {"id": "drift-evidence-rocks-mountains-g9", "domain": "EARTH_SPACE", "topic": "matching rock and mountain evidence", "grades": [9, 10], "terms": ["matching rock layers", "magkatugmang bato", "mountain ranges", "kabundukan", "rock formations", "magkakapareho ang bato", "ebidensya", "managsama nga bato", "kabukiran", "nagpadayon nga bukid", "edad ng bato"], "fact": {"tl": "Ang magkatulad na uri at edad ng mga bato at kabundukan sa magkahiwalay na kontinente ay nagdurugtong kung pagsasamahin ang mga lupain, isa pang ebidensya na dating iisang masa ang mga ito.", "en": "Matching rock types and ages, and mountain ranges that line up across separate continents, connect when the lands are put back together — another piece of evidence that they were once one mass.", "bis": "Ang managsama nga matang ug edad sa mga bato ug mga kabukiran nga magsumpay-sumpay tabok sa nagkabulag nga mga kontinente nagdugtong kung ibalik ang mga yuta, lain pang ebidensya nga kini usa ra ka masa kaniadto."}, "source": "AAAS BSL 4C/H; consensus geology", "generator": "claude-workflow", "reviewed": false},
  {"id": "plate-tectonics-theory-g9", "domain": "EARTH_SPACE", "topic": "plate tectonics theory", "grades": [9, 10], "terms": ["plate tectonics", "tectonic plates", "tektonikong plato", "lithosphere", "litospera", "plate tectonics theory", "magkahiwalay na plato", "teorya ng plate tectonics", "tektonikong plato", "nagdala-dala", "naglutaw", "balat ng Earth"], "fact": {"tl": "Ayon sa teorya ng plate tectonics, ang matibay na panlabas na balat ng Earth (ang lithosphere) ay hati-hati sa malalaking plato na dahan-dahang gumagalaw sa ibabaw ng mas malambot at mainit na bahagi ng mantle.", "en": "According to the theory of plate tectonics, Earth's rigid outer shell (the lithosphere) is broken into large plates that move slowly over the softer, hotter part of the mantle.", "bis": "Sumala sa teorya sa plate tectonics, ang gahi nga panggawas nga balat sa Earth (ang lithosphere) nabahin-bahin sa dagkong mga plato nga hinay nga naglihok ibabaw sa mas humok ug init nga bahin sa mantle."}, "source": "AAAS BSL 4C/M11; NRC ESS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "lithosphere-asthenosphere-g10", "domain": "EARTH_SPACE", "topic": "lithosphere and asthenosphere", "grades": [9, 10], "terms": ["lithosphere", "asthenosphere", "litospera", "astenospera", "matigas na plato", "malambot na bato", "naglutaw ang plato", "rigid plate", "malambot na mantle", "gahi nga plato", "humok nga bato", "naglutaw"], "fact": {"tl": "Ang mga tectonic plate ay binubuo ng lithosphere (ang matibay na crust at itaas na mantle) na nakapatong sa asthenosphere, isang mainit at bahagyang malambot na bahagi ng mantle na maaaring dahan-dahang dumaloy.", "en": "Tectonic plates are made of the lithosphere (the rigid crust and upper mantle) resting on the asthenosphere, a hot, partly soft part of the mantle that can slowly flow.", "bis": "Ang mga tectonic plate gilangkoban sa lithosphere (ang gahi nga crust ug ibabaw nga mantle) nga nagtungtong sa asthenosphere, usa ka init ug medyo humok nga bahin sa mantle nga makahinay-hinay og agos."}, "source": "AAAS BSL 4C/M11, 4C/H4; NRC ESS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "mantle-convection-driver-g10", "domain": "EARTH_SPACE", "topic": "mantle convection drives plates", "grades": [9, 10], "terms": ["mantle convection", "convection current", "alon ng init", "init sa loob ng Earth", "convection sa mantle", "kumukulo", "tumataas at bumababa", "alon sa kainit", "umiikot na init", "init nga nagatuyok", "nagpalihok sa plato", "internal heat"], "fact": {"tl": "Ang init mula sa loob ng Earth ay nagiging sanhi ng convection currents sa mantle — ang mainit na bato ay tumataas, lumalamig, at bumababa muli, at ang dahan-dahang pag-ikot na ito ang nagtutulak sa mga tectonic plate na gumalaw.", "en": "Heat from deep inside Earth causes convection currents in the mantle — hot rock rises, cools, and sinks again, and this slow circulation helps push the tectonic plates to move.", "bis": "Ang kainit gikan sa kahiladman sa Earth maoy hinungdan sa convection currents sa mantle — ang init nga bato mosaka, mobugnaw, ug mounlod pag-usab, ug kini nga hinay nga pagtuyok motukmod sa mga tectonic plate aron molihok."}, "source": "AAAS BSL 4C/H3; NRC ESS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "plate-movement-energy-source-g10", "domain": "EARTH_SPACE", "topic": "energy source of plate motion", "grades": [9, 10], "terms": ["internal heat", "radioactive decay", "init ng Earth", "pinagmulan ng init", "natitirang init", "core heat", "radyoaktibong pagkabulok", "kainit sa kahiladman", "init gikan sa core", "radioactive", "gravitational", "pinagkukunan ng enerhiya"], "fact": {"tl": "Ang enerhiya na nagpapagalaw sa mga plato ay nagmumula sa init sa loob ng Earth — bahagi nito ay natitirang init mula sa pagkakabuo ng planeta at bahagi naman ay galing sa pagkabulok ng radyoaktibong materyales.", "en": "The energy that moves the plates comes from Earth's internal heat — partly leftover heat from when the planet formed, and partly from the decay of radioactive materials inside it.", "bis": "Ang enerhiya nga nagpalihok sa mga plato gikan sa kainit sa sulod sa Earth — usa ka bahin niini mao ang nahibilin nga kainit gikan sa pagporma sa planeta ug usa ka bahin gikan sa pagkadunot sa radioactive nga mga materyales."}, "source": "AAAS BSL 4C/H3; NRC ESS2.A/B", "generator": "claude-workflow", "reviewed": false},
  {"id": "divergent-boundary-g9", "domain": "EARTH_SPACE", "topic": "divergent plate boundary", "grades": [9, 10], "terms": ["divergent boundary", "naglalayong plato", "naghihiwalay", "humihila palayo", "bagong crust", "divergent boundary", "naglalayo", "nagbulag nga plato", "naghimulag", "bag-ong crust", "pagkahiwalay", "magma na umaakyat"], "fact": {"tl": "Sa divergent boundary, ang dalawang plato ay naghihiwalay at naglalayo sa isa't isa; ang magma mula sa ilalim ay umaakyat sa puwang, lumalamig, at bumubuo ng bagong crust.", "en": "At a divergent boundary, two plates pull apart and move away from each other; magma from below rises into the gap, cools, and forms new crust.", "bis": "Sa divergent boundary, ang duha ka plato magbulag ug magpalayo sa usag usa; ang magma gikan sa ilawom mosaka sa luna, mobugnaw, ug moporma og bag-ong crust."}, "source": "AAAS BSL 4C/M12, 4C/H5; NRC ESS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "convergent-boundary-g9", "domain": "EARTH_SPACE", "topic": "convergent plate boundary", "grades": [9, 10], "terms": ["convergent boundary", "nagbabanggaang plato", "nagtutulakan", "nagkukumpulan", "collision", "convergent boundary", "nagbangga nga plato", "nagdinupol", "nagtipon", "pagbangga", "naghampas", "lindol at bulkan"], "fact": {"tl": "Sa convergent boundary, ang dalawang plato ay nagtutulak at nagbabanggaan; dito nabubuo ang matataas na kabundukan, malalalim na trench, at madalas na lindol at bulkan.", "en": "At a convergent boundary, two plates push together and collide; this is where tall mountain ranges, deep trenches, and frequent earthquakes and volcanoes form.", "bis": "Sa convergent boundary, ang duha ka plato magduot ug magbangga; dinhi maporma ang taas nga kabukiran, lawom nga trench, ug kanunay nga linog ug bulkan."}, "source": "AAAS BSL 4C/M12, 4C/H5; NRC ESS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "transform-boundary-g9", "domain": "EARTH_SPACE", "topic": "transform plate boundary", "grades": [9, 10], "terms": ["transform boundary", "nagdadaplisang plato", "nagkakaskasan", "sliding sideways", "strike-slip", "transform fault", "naghadlas nga plato", "nagdaplis", "naglampas", "pagkiskis", "pahalang na galaw", "lindol"], "fact": {"tl": "Sa transform boundary, ang dalawang plato ay nagdadaplis at nagkikiskisan habang gumagalaw nang pahalang sa magkasalungat na direksyon, na kadalasang nagdudulot ng malalakas na lindol.", "en": "At a transform boundary, two plates slide past and grind against each other moving sideways in opposite directions, which often causes strong earthquakes.", "bis": "Sa transform boundary, ang duha ka plato maghadlas ug magkiskis samtang naglihok nga pahapyod sa magkasumpaki nga direksyon, nga kasagaran maoy hinungdan sa kusog nga linog."}, "source": "AAAS BSL 4C/M12; NRC ESS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "seafloor-spreading-g10", "domain": "EARTH_SPACE", "topic": "seafloor spreading", "grades": [9, 10], "terms": ["seafloor spreading", "paglawak ng sahig-dagat", "mid-ocean ridge", "bagong sahig ng dagat", "seafloor spreading", "paglapad sa salog sa dagat", "bag-ong salog dagat", "mid-ocean ridge", "magma sa ilalim", "umaakyat na magma", "lumalawak"], "fact": {"tl": "Sa gitna ng karagatan, may mahabang bulubunduking tinatawag na mid-ocean ridge kung saan umaakyat ang magma, lumalamig, at bumubuo ng bagong sahig-dagat — isang proseso na tinatawag na seafloor spreading na nagtutulak sa mga plato palayo sa isa't isa.", "en": "In the middle of the oceans, long underwater mountain chains called mid-ocean ridges are where magma rises, cools, and forms new sea floor — a process called seafloor spreading that pushes plates away from each other.", "bis": "Sa tunga sa kadagatan, adunay tag-as nga kabukiran sa ilawom sa dagat nga gitawag og mid-ocean ridge diin mosaka ang magma, mobugnaw, ug moporma og bag-ong salog sa dagat — usa ka proseso nga gitawag og seafloor spreading nga motukmod sa mga plato palayo sa usag usa."}, "source": "AAAS BSL 4C/H5; NRC ESS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "seafloor-spreading-evidence-g10", "domain": "EARTH_SPACE", "topic": "evidence for seafloor spreading", "grades": [9, 10], "terms": ["magnetic stripes", "guhit-magnetiko", "edad ng sahig-dagat", "mas bata ang bato", "magnetic reversal", "ebidensya", "magnetikong guhit", "edad sa salog dagat", "mas batan-on nga bato", "simetriko", "patunay", "nagpapatunay"], "fact": {"tl": "Pinapatunayan ang seafloor spreading ng mga magkasalungat na guhit-magnetiko sa bato na simetriko sa magkabilang panig ng ridge, at ng katotohanang mas bata ang sahig-dagat malapit sa ridge at mas matanda kapag malayo dito.", "en": "Seafloor spreading is confirmed by symmetrical magnetic stripes in the rock on both sides of the ridge, and by the fact that the sea floor is youngest near the ridge and older farther away.", "bis": "Ang seafloor spreading gipamatud-an sa simetriko nga mga magnetikong guhit sa bato sa duha ka kilid sa ridge, ug sa kamatuoran nga ang salog sa dagat mas batan-on duol sa ridge ug mas tigulang kung layo na niini."}, "source": "Consensus marine geology (Vine-Matthews); AAAS BSL 4C/H", "generator": "claude-workflow", "reviewed": false},
  {"id": "subduction-zone-g10", "domain": "EARTH_SPACE", "topic": "subduction", "grades": [9, 10], "terms": ["subduction", "paglubog ng plato", "sumususo sa ilalim", "denser plate", "oceanic plate", "subduction", "paglunod sa plato", "nagsulod sa ilalom", "mas bug-at nga plato", "lumulubog na plato", "oceanic plate", "mas siksik"], "fact": {"tl": "Kapag nagbanggaan ang dalawang plato, ang mas mabigat at siksik na oceanic plate ay lumulubog pailalim sa kabilang plato papunta sa mainit na mantle — isang proseso na tinatawag na subduction.", "en": "When two plates collide, the heavier, denser oceanic plate sinks beneath the other plate down into the hot mantle — a process called subduction.", "bis": "Kung magbangga ang duha ka plato, ang mas bug-at ug siksik nga oceanic plate molunod ilawom sa pikas plato paingon sa init nga mantle — usa ka proseso nga gitawag og subduction."}, "source": "AAAS BSL 4C/H4; NRC ESS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-trench-formation-g10", "domain": "EARTH_SPACE", "topic": "deep-sea trench formation", "grades": [9, 10], "terms": ["ocean trench", "kanal sa dagat", "trench", "pinakamalalim", "subduction trench", "Philippine Trench", "deep-sea trench", "lawom nga kanal", "kanal sa dagat", "lumulubog na plato", "pinakalalim", "naporma nga kanal"], "fact": {"tl": "Sa subduction zone, kung saan lumulubog ang isang plato pailalim sa iba, nabubuo ang malalalim na ocean trench — ang pinakamalalim na bahagi ng karagatan, tulad ng Philippine Trench malapit sa silangan ng Pilipinas.", "en": "At a subduction zone, where one plate sinks beneath another, deep ocean trenches form — the deepest parts of the ocean, like the Philippine Trench off the eastern Philippines.", "bis": "Sa subduction zone, diin ang usa ka plato molunod ilawom sa lain, maporma ang lawom nga ocean trench — ang kinalawman nga bahin sa dagat, sama sa Philippine Trench sa sidlakang bahin sa Pilipinas."}, "source": "AAAS BSL 4C/H5; NRC ESS2.B; PH geography consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "subduction-volcano-arc-g10", "domain": "EARTH_SPACE", "topic": "volcanoes from subduction", "grades": [9, 10], "terms": ["volcanic arc", "natutunaw na plato", "subduction volcano", "magma mula sa subduction", "natunaw na bato", "hanay ng bulkan", "natunaw nga plato", "magma gikan sa subduction", "natunaw nga bato", "linya sa bulkan", "lumulubog na plato", "init"], "fact": {"tl": "Habang lumulubog ang plato sa subduction zone, natutunaw ang bahagi nito sa matinding init at gumagawa ng magma na umaakyat upang bumuo ng mga bulkan — kaya maraming bulkan ang Pilipinas sa gilid ng mga subduction zone.", "en": "As a plate sinks at a subduction zone, part of it melts in the intense heat and creates magma that rises to form volcanoes — this is why the Philippines has many volcanoes along its subduction zones.", "bis": "Samtang molunod ang plato sa subduction zone, ang usa ka bahin niini matunaw sa hilabihang kainit ug mohimo og magma nga mosaka aron moporma og mga bulkan — mao kini nganong daghan ang bulkan sa Pilipinas daplin sa subduction zone."}, "source": "AAAS BSL 4C/H5; NRC ESS2.B; PH geology consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mountain-building-collision-g10", "domain": "EARTH_SPACE", "topic": "mountain building (orogeny)", "grades": [9, 10], "terms": ["mountain building", "pagbuo ng kabundukan", "orogeny", "tumitiklop na crust", "continental collision", "Himalayas", "pagbuo sa kabukiran", "nagbangga nga kontinente", "tumataas na lupa", "naghampas nga kontinente", "kabundukan", "nakakapit na bato"], "fact": {"tl": "Kapag nagbanggaan ang dalawang continental plate, hindi madaling lumubog ang alinman dahil pareho silang magaan, kaya ang crust ay natutiklop at naitutulak pataas upang bumuo ng matataas na kabundukan tulad ng Himalayas.", "en": "When two continental plates collide, neither sinks easily because both are light, so the crust folds and is pushed upward to build tall mountain ranges like the Himalayas.", "bis": "Kung magbangga ang duha ka continental plate, walay dali nga molunod kay parehong gaan, busa ang crust mapilo ug matukmod pataas aron moporma og taas nga kabukiran sama sa Himalayas."}, "source": "AAAS BSL 4C/M12, 4C/H4; consensus geology", "generator": "claude-workflow", "reviewed": false},
  {"id": "slab-pull-ridge-push-g10", "domain": "EARTH_SPACE", "topic": "forces that move plates", "grades": [9, 10], "terms": ["slab pull", "ridge push", "hila ng lumulubog na plato", "gravity", "puwersa sa plato", "naghihilang plato", "slab pull", "ridge push", "hila sa naglunod nga plato", "grabidad", "puwersa nga nagpalihok", "bigat ng plato"], "fact": {"tl": "Bukod sa convection, may dalawa pang puwersa na nagpapagalaw sa mga plato: ang 'slab pull,' kung saan hinihila ng bigat ng lumulubog na plato ang natitira nito, at ang 'ridge push,' kung saan itinutulak ang plato palayo sa nakataas na ridge.", "en": "Besides convection, two other forces help move plates: 'slab pull,' where the weight of a sinking plate drags the rest of it down, and 'ridge push,' where a plate is pushed away from the raised ridge.", "bis": "Gawas sa convection, adunay duha pa ka puwersa nga motabang sa paglihok sa mga plato: ang 'slab pull,' diin ang gibug-aton sa naglunod nga plato moguyod sa nahabilin niini, ug ang 'ridge push,' diin ang plato matukmod palayo sa hataas nga ridge."}, "source": "Consensus geophysics; NRC ESS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "oceanic-vs-continental-crust-g10", "domain": "EARTH_SPACE", "topic": "oceanic vs continental crust", "grades": [9, 10], "terms": ["oceanic crust", "continental crust", "crust ng dagat", "crust ng lupa", "siksik na crust", "manipis", "makapal", "oceanic crust", "continental crust", "crust sa dagat", "crust sa yuta", "siksik", "nipis", "baga"], "fact": {"tl": "Ang oceanic crust (sa ilalim ng dagat) ay mas manipis ngunit mas siksik at mabigat, habang ang continental crust (kung saan nakatayo ang mga lupain) ay mas makapal ngunit mas magaan — kaya kapag nagbanggaan, ang oceanic crust ang lumulubog.", "en": "Oceanic crust (under the sea) is thinner but denser and heavier, while continental crust (where the landmasses sit) is thicker but lighter — so when they collide, the oceanic crust is the one that sinks.", "bis": "Ang oceanic crust (ilawom sa dagat) mas nipis apan mas siksik ug bug-at, samtang ang continental crust (diin nahimutang ang mga yuta) mas baga apan mas gaan — busa kung magbangga, ang oceanic crust mao ang molunod."}, "source": "AAAS BSL 4C/H4; NRC ESS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "rift-valley-formation-g10", "domain": "EARTH_SPACE", "topic": "continental rift valley", "grades": [9, 10], "terms": ["rift valley", "lambak ng paghihiwalay", "naghihiwalay na lupa", "East African Rift", "bumubuo ng dagat", "rift valley", "walog sa pagbulag", "nagbulag nga yuta", "East African Rift", "bumukas na lupa", "naghimulag", "bag-ong dagat"], "fact": {"tl": "Kapag nagsisimulang maghiwalay ang isang continental plate, nabubuo ang malalim na lambak na tinatawag na rift valley, tulad ng East African Rift — at sa paglipas ng panahon ay maaaring punuin ito ng tubig at maging bagong dagat.", "en": "When a continental plate begins to split, a deep valley called a rift valley forms, like the East African Rift — and over time it can fill with water and become a new ocean.", "bis": "Kung magsugod og bulag ang usa ka continental plate, maporma ang lawom nga walog nga gitawag og rift valley, sama sa East African Rift — ug sa paglabay sa panahon mahimo kining mapuno og tubig ug mahimong bag-ong dagat."}, "source": "Consensus geology; AAAS BSL 4C/H5", "generator": "claude-workflow", "reviewed": false},
  {"id": "hotspot-volcano-g10", "domain": "EARTH_SPACE", "topic": "hotspot volcanoes", "grades": [9, 10], "terms": ["hotspot", "mainit na lugar", "Hawaii", "mantle plume", "hanay ng isla", "hotspot volcano", "init nga lugar", "naglahos nga init", "Hawaii", "linya sa isla", "gumagalaw na plato", "nagtutol na init", "bulkan"], "fact": {"tl": "May mga bulkan na nabubuo hindi sa gilid ng plato kundi sa ibabaw ng 'hotspot,' isang lugar kung saan umaakyat ang sobrang init na mantle; habang gumagalaw ang plato sa ibabaw nito, nabubuo ang isang hanay ng mga isla tulad ng Hawaii.", "en": "Some volcanoes form not at plate edges but over a 'hotspot,' a place where extra-hot mantle rises; as the plate moves over it, a chain of islands like Hawaii is formed.", "bis": "Adunay mga bulkan nga maporma dili sa daplin sa plato kondili ibabaw sa 'hotspot,' usa ka lugar diin mosaka ang sobra ka init nga mantle; samtang naglihok ang plato ibabaw niini, maporma ang usa ka linya sa mga isla sama sa Hawaii."}, "source": "Consensus geology (mantle plume)", "generator": "claude-workflow", "reviewed": false},
  {"id": "plate-speed-slow-g9", "domain": "EARTH_SPACE", "topic": "speed of plate movement", "grades": [9, 10], "terms": ["plate speed", "bilis ng plato", "sentimetro kada taon", "kasinghaba ng kuko", "napakabagal", "gaano kabilis", "katulin sa plato", "sentimetro kada tuig", "sama sa kuko", "hinay kaayo", "dahan-dahan", "paglaki ng kuko"], "fact": {"tl": "Napakabagal gumalaw ng mga tectonic plate — ilang sentimetro lang bawat taon, halos kasingbilis ng paglaki ng iyong mga kuko, ngunit sa milyon-milyong taon ay naililipat nito ang buong kontinente.", "en": "Tectonic plates move very slowly — only a few centimeters per year, about as fast as your fingernails grow, but over millions of years this moves entire continents.", "bis": "Hinay kaayo molihok ang mga tectonic plate — pipila ra ka sentimetro matag tuig, halos sama ka paspas sa pagtubo sa imong mga kuko, apan sulod sa minilyon ka tuig kini makabalhin sa tibuok kontinente."}, "source": "Consensus geophysics", "generator": "claude-workflow", "reviewed": false},
  {"id": "earthquake-plate-boundary-g9", "domain": "EARTH_SPACE", "topic": "earthquakes at plate boundaries", "grades": [9, 10], "terms": ["earthquake plate boundary", "lindol sa gilid ng plato", "naipon na presyon", "biglang paggalaw", "energy release", "lindol", "linog sa daplin sa plato", "natipon nga presyur", "kalit nga paglihok", "pagpagawas sa enerhiya", "nagkiskisan", "puwersa"], "fact": {"tl": "Karamihan ng malalakas na lindol ay nangyayari sa mga plate boundary kung saan ang mga plato ay nagkukuskusan; naiipon ang presyon hanggang biglang gumalaw ang bato, at ang naipong enerhiya ay kumakalat bilang seismic waves.", "en": "Most strong earthquakes happen at plate boundaries where plates grind against each other; pressure builds up until the rock suddenly slips, and the stored energy spreads out as seismic waves.", "bis": "Kadaghanan sa kusog nga linog mahitabo sa mga plate boundary diin ang mga plato magkiskis sa usag usa; ang presyur magtigom hangtod nga ang bato kalit nga molihok, ug ang natipon nga enerhiya mokatag isip seismic waves."}, "source": "AAAS BSL 4C/M13; NRC ESS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "global-pattern-plate-boundaries-g9", "domain": "EARTH_SPACE", "topic": "global pattern of plate boundaries", "grades": [9, 10], "terms": ["plate boundary pattern", "pandaigdigang patern", "lindol at bulkan na magkasunod", "mapa ng plato", "magkakahanay", "pattern", "kalibutanon nga sumbanan", "linog ug bulkan magdungan", "mapa sa plato", "magkahanay", "patern", "gilid ng plato"], "fact": {"tl": "May malinaw na pandaigdigang patern: ang mga lindol, bulkan, at kabundukan ay hindi nagkalat lang nang basta-basta kundi nakahanay sa mga gilid ng tectonic plate, kaya tinuturuan tayo ng mapa ng mga ito kung nasaan ang mga plate boundary.", "en": "There is a clear worldwide pattern: earthquakes, volcanoes, and mountain ranges are not scattered randomly but line up along the edges of tectonic plates, so a map of them shows us where the plate boundaries are.", "bis": "Adunay tin-aw nga kalibutanon nga sumbanan: ang mga linog, bulkan, ug kabukiran dili nagkatag lang sa walay han-ay kondili naglinya daplin sa mga ngilit sa tectonic plate, busa ang mapa niini magpakita kanato asa ang mga plate boundary."}, "source": "AAAS BSL 4C/M13", "generator": "claude-workflow", "reviewed": false},
  {"id": "philippines-between-plates-g9", "domain": "EARTH_SPACE", "topic": "Philippines on plate boundaries", "grades": [9, 10], "terms": ["Philippine plate", "Eurasian plate", "Pilipinas sa pagitan ng plato", "subduction sa Pilipinas", "nagtatagpong plato", "Philippine Sea Plate", "Pilipinas tunga sa plato", "nag-aginod nga plato", "subduction sa Pilipinas", "nagtagbo nga plato", "lindol at bulkan", "Ring of Fire"], "fact": {"tl": "Ang Pilipinas ay nasa pagitan ng dalawang malalaking tektonikong plato — ang Philippine Sea Plate at ang Eurasian Plate — na nagtatagpo at naglulubog sa isa't isa, kaya napakadalas ng lindol at bulkan dito.", "en": "The Philippines lies between two large tectonic plates — the Philippine Sea Plate and the Eurasian Plate — that meet and subduct beneath each other, which is why earthquakes and volcanoes are so frequent here.", "bis": "Ang Pilipinas nahimutang sa tunga sa duha ka dagkong tektonikong plato — ang Philippine Sea Plate ug ang Eurasian Plate — nga nagtagbo ug naglunod sa usag usa, mao nga kanunay kaayo ang linog ug bulkan dinhi."}, "source": "PHIVOLCS / PH geology consensus; AAAS BSL 4C/M13", "generator": "claude-workflow", "reviewed": false},
  {"id": "rock-cycle-tectonics-g10", "domain": "EARTH_SPACE", "topic": "plate tectonics recycles crust", "grades": [9, 10], "terms": ["crust recycling", "muling paggamit ng crust", "lumang crust", "bagong crust", "pagkasira", "recycle ang bato", "pag-recycle sa crust", "daang crust", "bag-ong crust", "natunaw ug nabag-o", "balanse", "patuloy na pagbabago"], "fact": {"tl": "Patuloy na binabago ng plate tectonics ang ibabaw ng Earth: gumagawa ng bagong crust sa mga ridge habang nilalamon at tinutunaw ang lumang crust sa mga subduction zone, kaya nananatiling balanse ang sukat ng planeta.", "en": "Plate tectonics continually recycles Earth's surface: new crust is made at the ridges while old crust is swallowed and melted at subduction zones, so the planet's size stays balanced.", "bis": "Ang plate tectonics padayon nga nag-usab sa nawong sa Earth: bag-ong crust mabuhat sa mga ridge samtang ang daang crust matulon ug matunaw sa mga subduction zone, busa ang gidak-on sa planeta magpabilin nga balanse."}, "source": "NRC ESS2.A/B; consensus geology", "generator": "claude-workflow", "reviewed": false},
  {"id": "tectonics-deep-time-g10", "domain": "EARTH_SPACE", "topic": "plate tectonics over geologic time", "grades": [9, 10], "terms": ["geologic time", "deep time", "milyong taon", "patuloy na paggalaw", "magbabagong mapa", "future continents", "geolohikong panahon", "minilyon ka tuig", "padayon nga paglihok", "mabag-o ang mapa", "umuusbong", "mahabang panahon"], "fact": {"tl": "Dahil patuloy na gumagalaw ang mga plato, iba ang anyo ng mapa ng Earth ngayon kumpara sa milyon-milyong taon na ang nakalipas — at sa darating na milyon-milyong taon, muling magbabago ang posisyon ng mga kontinente.", "en": "Because the plates keep moving, the map of Earth today looks different from millions of years ago — and over the coming millions of years, the positions of the continents will change again.", "bis": "Tungod kay padayon nga naglihok ang mga plato, lahi ang dagway sa mapa sa Earth karon kompara sa minilyon ka tuig nga milabay — ug sa umaabot nga minilyon ka tuig, mausab pag-usab ang posisyon sa mga kontinente."}, "source": "Consensus geology; AAAS BSL 4C/H", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-age-4-6-billion-g9", "domain": "EARTH_SPACE", "topic": "age of the Earth", "grades": [8, 9, 10], "terms": ["edad ng Earth", "Earth", "Mundo", "Yuta", "Kalibutan", "apat na bilyong", "bilyong taon", "4.6 billion", "milyong", "tanda", "katandaan", "age of the earth", "gulang", "kagulangon", "bilyon ka tuig", "kabilyon"], "fact": {"tl": "Ayon sa siyentipikong ebidensiya, ang Earth ay humigit-kumulang 4.6 na bilyong taon na ang gulang, na natantiya mula sa edad ng pinakamatatandang bato at mga meteorite.", "en": "Scientific evidence indicates the Earth is about 4.6 billion years old, estimated from the ages of the oldest rocks and meteorites.", "bis": "Sumala sa siyentipikong ebidensiya, ang Yuta mga 4.6 ka bilyon ka tuig na ang edad, gibanabana gikan sa edad sa labing karaang mga bato ug mga meteorite."}, "source": "NRC ESS1.C; AAAS 10D/H1, 4C/H6", "generator": "claude-workflow", "reviewed": false},
  {"id": "geologic-time-scale-eras-g9", "domain": "EARTH_SPACE", "topic": "geologic time scale", "grades": [8, 9, 10], "terms": ["geologic time scale", "panahong heolohiko", "eon", "era", "periyod", "period", "epoch", "yugto", "hugna", "kasaysayan ng Earth", "geological time", "gibahinbahin", "panahon", "yugto sa panahon"], "fact": {"tl": "Inaayos ng geologic time scale ang mahabang kasaysayan ng Earth sa palaki nang palaking yugto ng panahon: mga eon, era, periyod (period), at epoch.", "en": "The geologic time scale organizes Earth's long history into increasingly long intervals of time: eons, eras, periods, and epochs.", "bis": "Ang geologic time scale nag-organisar sa taas nga kasaysayan sa Yuta ngadto sa nagkadako nga mga yugto sa panahon: mga eon, era, period, ug epoch."}, "source": "NRC ESS1.C (geological time scale)", "generator": "claude-workflow", "reviewed": false},
  {"id": "relative-dating-superposition-g9", "domain": "EARTH_SPACE", "topic": "relative dating and superposition", "grades": [8, 9, 10], "terms": ["relative dating", "superposition", "relative age", "kamag-anak na edad", "bata", "matanda", "ilalim", "ibaba", "itaas", "strata", "layer ng bato", "patong-patong na bato", "pagkakasunod-sunod", "relatibong edad", "bag-o", "karaan", "ubos", "pinakaubos", "han-ay"], "fact": {"tl": "Sa relative dating, sa isang hindi nagambalang patong-patong na bato, ang pinakamatandang layer ay nasa ilalim at ang pinakabatang layer ay nasa itaas (batas ng superposition).", "en": "In relative dating, in an undisturbed column of rock the oldest layers are at the bottom and the youngest are at the top (the law of superposition).", "bis": "Sa relative dating, sa usa ka wala matandog nga patong-patong nga mga bato, ang labing karaang layer naa sa ilawom ug ang labing bag-o naa sa ibabaw (ang balaod sa superposition)."}, "source": "NRC ESS1.C (relative ages, undisturbed column)", "generator": "claude-workflow", "reviewed": false},
  {"id": "rock-layers-rearranged-tectonics-g9", "domain": "EARTH_SPACE", "topic": "rock layers disturbed by tectonic forces", "grades": [9, 10], "terms": ["folding", "faulting", "uplift", "tectonic", "nabaligtad", "nagambala", "baluktot", "bali", "pagtaas ng lupa", "layer ng bato", "strata", "hindi laging nasa itaas", "gibaliktad", "gibali", "gipiko", "pagbangon sa yuta"], "fact": {"tl": "Ang mga layer ng bato ay maaaring maibaligtad o magambala ng puwersang tektoniko (folding, faulting, uplift), kaya hindi laging nasa itaas ang pinakabatang layer.", "en": "Rock layers can be inverted or rearranged by tectonic forces (folding, faulting, and uplift), so the youngest layer is not always on top.", "bis": "Ang mga layer sa bato mahimong mabaliktad o matandog sa puwersang tektoniko (folding, faulting, uplift), busa dili kanunay naa sa ibabaw ang labing bag-o nga layer."}, "source": "NRC ESS1.C; AAAS 4C/M5", "generator": "claude-workflow", "reviewed": false},
  {"id": "absolute-dating-radioactive-decay-g9", "domain": "EARTH_SPACE", "topic": "absolute dating by radioactive decay", "grades": [9, 10], "terms": ["absolute dating", "radioactive decay", "radiometric", "isotope", "isotopo", "radyoaktibo", "tiyak na edad", "aktwal na edad", "sukatin ang edad", "bato", "absolutong edad", "desintegrasyon", "pagkabulok", "tukmang edad", "sukdon ang edad"], "fact": {"tl": "Sa absolute dating, sinusukat ng mga siyentipiko ang dami ng radyoaktibong isotopo na natitira sa bato para malaman ang tiyak na edad nito sa mga taon.", "en": "In absolute dating, scientists measure the amount of radioactive isotopes remaining in a rock to determine its actual age in years.", "bis": "Sa absolute dating, sukdon sa mga siyentipiko ang gidaghanon sa radyoaktibong isotope nga nahibilin sa bato aron mahibaloan ang tukma niini nga edad sa mga tuig."}, "source": "NRC ESS1.C (radioactive decay lifetimes and isotopic content); AAAS 4C/H", "generator": "claude-workflow", "reviewed": false},
  {"id": "half-life-dating-concept-g10", "domain": "EARTH_SPACE", "topic": "half-life in radiometric dating", "grades": [9, 10], "terms": ["half-life", "kalahating buhay", "kalahati", "nahahati", "radyoaktibo", "isotope", "isotopo", "pagbulok", "palagiang bilis", "orasan ng bato", "natural clock", "tunga sa kinabuhi", "mabulok", "panahon"], "fact": {"tl": "Ang half-life ay ang panahong kailangan para mabulok ang kalahati ng radyoaktibong isotopo; dahil palagi ang bilis nito, nagsisilbi itong natural na orasan para sukatin ang edad ng bato.", "en": "A half-life is the time it takes for half of a radioactive isotope to decay; because this rate is constant, it acts as a natural clock for measuring the age of rocks.", "bis": "Ang half-life mao ang panahon nga kinahanglan aron mabulok ang katunga sa usa ka radyoaktibong isotope; tungod kay kanunay ang katulin niini, magsilbi kining natural nga orasan sa pagsukod sa edad sa bato."}, "source": "NRC ESS1.C; consensus radiometric-dating definition", "generator": "claude-workflow", "reviewed": false},
  {"id": "carbon-14-dating-limit-g10", "domain": "EARTH_SPACE", "topic": "carbon-14 dating of once-living things", "grades": [9, 10], "terms": ["carbon-14", "carbon dating", "radiocarbon", "carbon-14 dating", "dating ng organismo", "dating buhay", "kahoy", "buto", "hanggang", "limitado", "mga libong taon", "50,000 taon", "fosil", "fossil na bata", "kanhi buhi", "tul-an"], "fact": {"tl": "Ang carbon-14 dating ay ginagamit para sa mga bagay na dating buhay tulad ng kahoy at buto, ngunit umaabot lamang ito hanggang mga 50,000 taon, kaya hindi ito magagamit sa napakatatandang fossil.", "en": "Carbon-14 dating is used on things that were once alive, such as wood and bone, but it reaches back only about 50,000 years, so it cannot date very old fossils.", "bis": "Ang carbon-14 dating gigamit sa mga butang nga kanhi buhi sama sa kahoy ug bukog, apan moabot lang kini hangtod mga 50,000 ka tuig, busa dili kini magamit sa karaan kaayo nga mga fossil."}, "source": "Consensus radiocarbon-dating range (encyclopedia-stable)", "generator": "claude-workflow", "reviewed": false},
  {"id": "continental-rock-older-than-ocean-g10", "domain": "EARTH_SPACE", "topic": "continental rocks older than ocean floor", "grades": [9, 10], "terms": ["continental rock", "ocean floor", "sahig ng karagatan", "kontinental na bato", "matanda", "mas bata", "4 billion", "apat na bilyon", "200 million", "sea floor", "ridge", "trench", "bag-ong bato", "karaang bato", "salog sa dagat"], "fact": {"tl": "Ang mga batong kontinental ay maaaring mahigit 4 na bilyong taon ang edad, samantalang ang mga bato sa sahig ng karagatan ay wala pang 200 milyong taon dahil patuloy itong nililikha at sinisira ng tektoniko.", "en": "Continental rocks can be more than 4 billion years old, while ocean-floor rocks are less than 200 million years old because tectonic processes continually create and destroy them.", "bis": "Ang mga kontinental nga bato mahimong kapin sa 4 ka bilyon ka tuig ang edad, samtang ang mga bato sa salog sa dagat ubos sa 200 ka milyon ka tuig kay padayon kining gimugna ug gilaglag sa tektoniko."}, "source": "NRC ESS1.C (continental vs ocean-floor rock ages)", "generator": "claude-workflow", "reviewed": false},
  {"id": "how-fossils-form-sediment-g9", "domain": "EARTH_SPACE", "topic": "how fossils form", "grades": [7, 8, 9], "terms": ["fossil", "fosil", "paano nabubuo ang fosil", "sediment", "sedimento", "nalibing", "natabunan", "sedimentary rock", "batong sedimentaryo", "labi", "buto", "kabibe", "minineral", "gibara", "gilubong", "unod", "tul-an", "kabhang", "mineral"], "fact": {"tl": "Karaniwang nabubuo ang fossil kapag ang labi ng organismo ay mabilis na natatabunan ng sediment, at sa paglipas ng panahon ay nagiging bato (sedimentary rock) na nagpapanatili ng hugis o bakas nito.", "en": "Fossils usually form when the remains of an organism are quickly buried by sediment, and over time the sediment hardens into rock that preserves its shape or trace.", "bis": "Ang fossil kasagarang maporma kung ang salin sa organismo paspas nga matabunan sa sediment, ug sa paglabay sa panahon mahimo kining bato nga magtipig sa porma o timaan niini."}, "source": "AAAS 4C/M3 (remains buried, cemented to form rock); NRC ESS1.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "fossils-need-hard-parts-g9", "domain": "EARTH_SPACE", "topic": "why hard parts fossilize best", "grades": [7, 8, 9], "terms": ["matigas na bahagi", "buto", "ngipin", "kabibe", "shell", "hard parts", "bones", "teeth", "malambot", "soft tissue", "bihirang ma-fosil", "natutunaw", "gagmay nga higayon", "tul-an", "ngipon", "kabhang", "unod nga humok"], "fact": {"tl": "Mas madalas ma-fossil ang matitigas na bahagi tulad ng buto, ngipin, at kabibe; ang malalambot na bahagi tulad ng laman at balat ay madaling mabulok kaya bihira itong mapreserba.", "en": "Hard parts such as bones, teeth, and shells fossilize most often; soft parts like flesh and skin decay quickly and are rarely preserved.", "bis": "Mas kanunay ma-fossil ang gahi nga mga bahin sama sa bukog, ngipon, ug kabhang; ang humok nga mga bahin sama sa unod ug panit dali madunot busa panagsa ra matipigan."}, "source": "Consensus paleontology (encyclopedia-stable); NRC ESS1.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "trace-fossils-vs-body-fossils-g9", "domain": "EARTH_SPACE", "topic": "trace fossils versus body fossils", "grades": [8, 9, 10], "terms": ["trace fossil", "body fossil", "bakas na fosil", "yapak", "tracks", "footprints", "burrow", "coprolite", "tae", "aktuwal na bahagi", "gawi", "kilos", "timaan nga fossil", "tunob", "lihok sa hayop"], "fact": {"tl": "Ang body fossil ay ang aktwal na bahagi ng organismo tulad ng buto o kabibe, samantalang ang trace fossil tulad ng yapak o lungga ay nagpapakita ng gawi o kilos ng organismo.", "en": "A body fossil is an actual part of an organism such as a bone or shell, while a trace fossil such as a footprint or burrow shows the organism's behavior or activity.", "bis": "Ang body fossil mao ang tinuod nga bahin sa organismo sama sa bukog o kabhang, samtang ang trace fossil sama sa tunob o lungag nagpakita sa gawi o lihok sa organismo."}, "source": "Consensus paleontology (encyclopedia-stable)", "generator": "claude-workflow", "reviewed": false},
  {"id": "fossil-record-shows-changing-life-g9", "domain": "EARTH_SPACE", "topic": "fossil record shows life changed over time", "grades": [8, 9, 10], "terms": ["fossil record", "talaan ng fosil", "nagbabagong buhay", "changing life", "successive layers", "magkakasunod na layer", "ebidensiya", "ebolusyon", "lumitaw", "naglaho", "appeared", "disappeared", "talaan sa fossil", "nagbag-o", "nagpakita", "nawala"], "fact": {"tl": "Ipinapakita ng fossil record sa magkakasunod na layer ng bato na nagbago ang mga uri ng buhay sa paglipas ng panahon — may mga organismong lumitaw at may mga naglaho.", "en": "The fossil record in successive rock layers shows that the kinds of life changed over time — some organisms appeared and others disappeared.", "bis": "Ang fossil record sa nagsunodsunod nga mga layer sa bato nagpakita nga nagbag-o ang mga matang sa kinabuhi sa paglabay sa panahon — adunay mga organismo nga mitungha ug adunay nawala."}, "source": "AAAS 4C/M5 (changing life forms in successive layers); NRC ESS1.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "index-fossils-dating-g10", "domain": "EARTH_SPACE", "topic": "index fossils for dating rocks", "grades": [9, 10], "terms": ["index fossil", "gabay na fosil", "palatandaang fosil", "marker fossil", "widespread", "laganap", "maikling panahon", "short-lived", "edad ng bato", "tukuyin", "trilobite", "ammonite", "gabay nga fossil", "timailhan", "panahon"], "fact": {"tl": "Ang index fossil ay galing sa organismong laganap ngunit nabuhay lamang sa maikling yugto ng panahon, kaya nagsisilbi itong gabay para tukuyin ang edad ng layer ng batong kinaroroonan nito.", "en": "An index fossil comes from an organism that was widespread but lived for only a short span of time, so it serves as a guide for determining the age of the rock layer it is found in.", "bis": "Ang index fossil naggikan sa organismo nga kaylap apan nabuhi lang sa mubo nga panahon, busa nagsilbi kining giya sa pag-ila sa edad sa layer sa bato diin kini makit-an."}, "source": "NRC ESS1.C (certain fossils reveal age of rocks); consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mass-extinction-definition-g9", "domain": "EARTH_SPACE", "topic": "mass extinctions in the rock record", "grades": [8, 9, 10], "terms": ["mass extinction", "malawakang paglaho", "maraming species", "nawala", "sabay-sabay", "maikling panahon", "rock record", "fossil record", "lima", "five", "talaan ng bato", "kadaghanan nahanaw", "dungan", "mubo nga panahon"], "fact": {"tl": "Ang mass extinction ay malawakang paglaho ng napakaraming species sa relatibong maikling panahon; ipinapakita ng rock record na nangyari ito nang ilang beses sa kasaysayan ng Earth.", "en": "A mass extinction is the disappearance of very many species in a relatively short time; the rock record shows this has happened several times in Earth's history.", "bis": "Ang mass extinction mao ang kaylap nga pagkahanaw sa daghan kaayong species sulod sa mubo nga panahon; ang rock record nagpakita nga nahitabo kini makadaghan sa kasaysayan sa Yuta."}, "source": "NRC ESS1.C (records of fossils show past periods of massive extinctions)", "generator": "claude-workflow", "reviewed": false},
  {"id": "five-major-mass-extinctions-g10", "domain": "EARTH_SPACE", "topic": "the five major mass extinctions", "grades": [9, 10], "terms": ["five mass extinctions", "limang malaking paglaho", "Big Five", "major extinction", "fossil record", "matinding paglaho", "limang pangunahing", "five major", "lima ka dagkong", "extinction events", "limang dakong pagkahanaw"], "fact": {"tl": "Natukoy ng mga siyentipiko mula sa fossil record ang limang pangunahing mass extinction sa kasaysayan ng Earth, kung saan nawala ang malaking bahagi ng mga species sa daigdig.", "en": "From the fossil record, scientists have identified five major mass extinctions in Earth's history, in each of which a large fraction of the world's species disappeared.", "bis": "Gikan sa fossil record, naila sa mga siyentipiko ang lima ka mga dagkong mass extinction sa kasaysayan sa Yuta, diin nawala ang dakong bahin sa mga species sa kalibutan."}, "source": "Consensus paleontology / 'Big Five' extinctions (encyclopedia-stable)", "generator": "claude-workflow", "reviewed": false},
  {"id": "permian-extinction-largest-g10", "domain": "EARTH_SPACE", "topic": "the Permian (end-Permian) mass extinction", "grades": [9, 10], "terms": ["Permian extinction", "end-Permian", "pinakamalaking paglaho", "Great Dying", "252 million", "252 milyon", "marine species", "malawakang", "volcanic", "pinakamatinding", "largest extinction", "kinadak-ang pagkahanaw", "kadagatan"], "fact": {"tl": "Ang pinakamatinding mass extinction ay nangyari mga 252 milyong taon na ang nakalipas sa dulo ng panahong Permian, kung saan namatay ang karamihan ng mga species sa dagat at lupa.", "en": "The most severe mass extinction occurred about 252 million years ago at the end of the Permian period, when most species in the sea and on land died out.", "bis": "Ang labing grabe nga mass extinction nahitabo mga 252 ka milyon ka tuig kanhi sa kataposan sa panahong Permian, diin nangamatay ang kadaghanan sa mga species sa dagat ug sa yuta."}, "source": "Consensus geology (end-Permian / 'Great Dying', ~252 Ma)", "generator": "claude-workflow", "reviewed": false},
  {"id": "cretaceous-extinction-dinosaurs-g10", "domain": "EARTH_SPACE", "topic": "the Cretaceous extinction and dinosaurs", "grades": [9, 10], "terms": ["Cretaceous extinction", "K-Pg", "dinosaur extinction", "66 million", "66 milyon", "asteroid", "bulkan", "non-avian dinosaur", "pagtatapos ng Mesozoic", "Chicxulub", "paglaho ng dinosaur", "bulkang"], "fact": {"tl": "Mga 66 milyong taon na ang nakalipas, isang mass extinction sa dulo ng panahong Cretaceous ang pumuksa sa mga non-avian na dinosaur, malamang dahil sa pagtama ng isang asteroid.", "en": "About 66 million years ago, a mass extinction at the end of the Cretaceous period wiped out the non-avian dinosaurs, most likely caused by an asteroid impact.", "bis": "Mga 66 ka milyon ka tuig kanhi, usa ka mass extinction sa kataposan sa panahong Cretaceous ang naglaglag sa mga non-avian nga dinosaur, lagmit tungod sa pagbangga sa usa ka asteroid."}, "source": "NRC ESS1.C (catastrophic events); consensus K-Pg extinction", "generator": "claude-workflow", "reviewed": false},
  {"id": "precambrian-most-of-earth-history-g10", "domain": "EARTH_SPACE", "topic": "the Precambrian span of time", "grades": [9, 10], "terms": ["Precambrian", "Precambriano", "unang panahon", "karamihan ng kasaysayan", "most of Earth history", "single-celled", "mikrobyo", "walang buto", "soft-bodied", "bago ang trilobite", "kadaghanan sa panahon", "unang yugto", "mikrobyong buhi"], "fact": {"tl": "Sakop ng Precambrian ang karamihan ng kasaysayan ng Earth, at sa panahong ito karamihan ng buhay ay mga maliliit na organismong walang matitigas na bahagi, kaya kakaunti ang fossil.", "en": "The Precambrian covers most of Earth's history, and during it most life consisted of tiny organisms without hard parts, so fossils from this time are rare.", "bis": "Ang Precambrian naglangkob sa kadaghanan sa kasaysayan sa Yuta, ug niini nga panahon ang kadaghanan sa kinabuhi gagmayng organismo nga walay gahi nga bahin, busa diyutay ra ang fossil."}, "source": "Consensus geology (Precambrian span, sparse fossil record)", "generator": "claude-workflow", "reviewed": false},
  {"id": "uniformitarianism-principle-g10", "domain": "EARTH_SPACE", "topic": "uniformitarianism (the present is the key to the past)", "grades": [9, 10], "terms": ["uniformitarianism", "Charles Lyell", "Lyell", "Principles of Geology", "present key to past", "kasalukuyan susi sa nakaraan", "mabagal na proseso", "parehong proseso", "slow process", "same processes", "kasamtangang proseso yawe sa kagahapon", "susi", "hinay nga proseso"], "fact": {"tl": "Sa prinsipyong uniformitarianism na pinasikat ni Charles Lyell, ang parehong mabagal na prosesong nakikita ngayon (gaya ng erosion at sedimentation) ang nagbago sa Earth sa loob ng napakahabang panahon.", "en": "In the principle of uniformitarianism, popularized by Charles Lyell, the same slow processes we see today (such as erosion and sedimentation) have shaped the Earth over very long spans of time.", "bis": "Sa prinsipyong uniformitarianism nga gipasikat ni Charles Lyell, ang mao ra nga hinay nga proseso nga atong makita karon (sama sa erosion ug sedimentation) ang nag-usab sa Yuta sulod sa taas kaayo nga panahon."}, "source": "AAAS 10D/H2 (Lyell, Principles of Geology); consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lyell-vast-age-evidence-g10", "domain": "EARTH_SPACE", "topic": "evidence that Earth is very old", "grades": [9, 10], "terms": ["Charles Lyell", "vast age", "napakatandang Earth", "libong taon lang akala", "rock layers", "fossils", "19th century", "patong-patong na bato", "ebidensiya ng katandaan", "Lyell", "karaan kaayo", "ebidensiya"], "fact": {"tl": "Hanggang ika-19 na siglo, akala ng karamihan ay ilang libong taon lang ang Earth, ngunit ipinakita ni Charles Lyell mula sa patong-patong na bato at fossil na ito ay napakatanda na pala.", "en": "Until the 19th century most people thought the Earth was only a few thousand years old, but Charles Lyell showed from rock layers and fossils that it is in fact extremely ancient.", "bis": "Hangtod sa ika-19 nga siglo, gituohan sa kadaghanan nga pipila ka libo lang ka tuig ang Yuta, apan gipakita ni Charles Lyell gikan sa patong-patong nga bato ug fossil nga karaan na kaayo kini diay."}, "source": "AAAS 10D/H1, 10D/H2 (Lyell)", "generator": "claude-workflow", "reviewed": false},
  {"id": "deep-time-concept-g10", "domain": "EARTH_SPACE", "topic": "deep time and the scale of geologic history", "grades": [9, 10], "terms": ["deep time", "malalim na panahon", "napakahabang panahon", "geologic time", "milyong taon", "bilyong taon", "mahirap isipin", "scale of time", "human experience", "lalom nga panahon", "taas kaayo nga panahon", "lisod hunahunaon"], "fact": {"tl": "Tinatawag na deep time ang napakahabang yugto ng kasaysayang heolohiko na umaabot sa milyon at bilyong taon, na napakahirap isipin dahil higit na mahaba ito kaysa sa karanasan ng tao.", "en": "Deep time is the name for the immense spans of geologic history that reach into millions and billions of years, which are very hard to imagine because they far exceed human experience.", "bis": "Ang deep time mao ang ngalan sa hilabihan kataas nga mga yugto sa kasaysayang heolohiko nga moabot sa milyon ug bilyon ka tuig, nga lisod kaayong hunahunaon kay labaw pa kaayo kini sa kasinatian sa tawo."}, "source": "AAAS 10D (difficulty imagining vast time spans)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sedimentary-rock-records-history-g9", "domain": "EARTH_SPACE", "topic": "sedimentary rock as a record of Earth's history", "grades": [8, 9, 10], "terms": ["sedimentary rock", "batong sedimentaryo", "libong layer", "thousands of layers", "talaan ng kasaysayan", "record of history", "nabubuo ng paulit-ulit", "sediment", "nalibing na labi", "sedimentaryong bato", "talaan sa kasaysayan", "gilubong nga salin"], "fact": {"tl": "Ang libo-libong layer ng batong sedimentaryo ay parang talaan ng mahabang kasaysayan ng Earth, dahil bawat layer ay maaaring naglalaman ng labi ng mga organismong nabuhay sa panahong iyon.", "en": "The thousands of layers of sedimentary rock act like a record of Earth's long history, because each layer may contain the remains of organisms that lived at that time.", "bis": "Ang liboan ka layer sa sedimentaryong bato sama sa talaan sa taas nga kasaysayan sa Yuta, kay matag layer mahimong adunay salin sa mga organismo nga nabuhi niadtong panahona."}, "source": "AAAS 4C/M5 (thousands of layers confirm long history)", "generator": "claude-workflow", "reviewed": false},
  {"id": "meteorites-clues-to-earth-age-g10", "domain": "EARTH_SPACE", "topic": "meteorites as clues to Earth's age", "grades": [9, 10], "terms": ["meteorite", "meteorito", "asteroid", "edad ng Earth", "walang nagbago", "unchanged", "4.6 billion", "sariling sistema ng araw", "solar system age", "palatandaan", "clues", "timaan sa edad", "wala mausab", "bilyon ka tuig"], "fact": {"tl": "Halos hindi nagbago ang mga meteorite at asteroid sa loob ng bilyong taon, kaya tinutukoy ng mga siyentipiko ang kanilang edad para matantiya ang edad ng Earth at ng buong solar system.", "en": "Meteorites and asteroids have changed very little over billions of years, so scientists date them to estimate the age of the Earth and the whole solar system.", "bis": "Halos wala mausab ang mga meteorite ug asteroid sulod sa bilyon ka tuig, busa gisukod sa mga siyentipiko ang ilang edad aron banabanaon ang edad sa Yuta ug sa tibuok solar system."}, "source": "NRC ESS1.C (meteorites changed little; deduce solar system age)", "generator": "claude-workflow", "reviewed": false},
  {"id": "early-rock-record-destroyed-g10", "domain": "EARTH_SPACE", "topic": "why the earliest rock record is incomplete", "grades": [9, 10], "terms": ["early rock record", "unang bato nawala", "nasira", "plate tectonics", "erosion", "recycled", "walang labi", "incomplete record", "tinunaw", "muling nabuo", "unang talaan nawala", "gilaglag", "gibag-o", "rock cycle"], "fact": {"tl": "Karamihan ng pinakaunang bato ng Earth ay nasira na ng plate tectonics at erosion, kaya hindi kumpleto ang talaan ng pinakaunang bahagi ng kasaysayan ng ating planeta.", "en": "Most of Earth's earliest rock has been destroyed by plate tectonics and erosion, so the record of the very first part of our planet's history is incomplete.", "bis": "Kadaghanan sa labing unang bato sa Yuta gilaglag na sa plate tectonics ug erosion, busa dili kompleto ang talaan sa labing unang bahin sa kasaysayan sa atong planeta."}, "source": "NRC ESS1.C (active processes destroyed early rock record)", "generator": "claude-workflow", "reviewed": false},
  {"id": "fossils-show-past-environments-g9", "domain": "EARTH_SPACE", "topic": "fossils reveal past environments", "grades": [8, 9, 10], "terms": ["fossils", "fosil", "dating kapaligiran", "past environment", "marine fossil sa bundok", "kabibe sa bundok", "dating dagat", "klima noon", "past climate", "dagat dati", "kapaligiran noon", "kanhing palibot", "kabhang sa bukid", "kanhi dagat"], "fact": {"tl": "Maaaring sabihin sa atin ng mga fossil kung ano ang kapaligiran noon — halimbawa, ang fossil ng kabibe sa tuktok ng bundok ay nagpapakitang dating nasa ilalim ng dagat ang lugar na iyon.", "en": "Fossils can tell us what an environment was like in the past — for example, seashell fossils on a mountaintop show that the area was once under the sea.", "bis": "Ang mga fossil makasulti kanato kon unsa ang palibot kaniadto — pananglitan, ang fossil sa kabhang sa tumoy sa bukid nagpakita nga kanhi naa sa ilawom sa dagat kadtong dapita."}, "source": "NRC ESS1.C; consensus paleoenvironment reconstruction", "generator": "claude-workflow", "reviewed": false},
  {"id": "transitional-fossils-evolution-g10", "domain": "EARTH_SPACE", "topic": "fossils as evidence of changing life and evolution", "grades": [9, 10], "terms": ["transitional fossil", "ebolusyon", "evolution", "ebidensiya", "intermediate", "nagbabagong species", "Archaeopteryx", "ibon at reptilya", "fossil evidence", "ebidensiya sa ebolusyon", "nagbag-o nga kinabuhi", "tunga-tunga"], "fact": {"tl": "May mga fossil na nagpapakita ng mga katangiang nasa pagitan ng dalawang grupo ng organismo, gaya ng Archaeopteryx na may katangian ng ibon at reptilya, na ebidensiya ng pagbabago ng buhay sa paglipas ng panahon.", "en": "Some fossils show features in between two groups of organisms, such as Archaeopteryx with traits of both birds and reptiles, providing evidence that life has changed over time.", "bis": "Adunay mga fossil nga nagpakita sa mga kinaiya nga tunga-tunga sa duha ka grupo sa organismo, sama sa Archaeopteryx nga adunay kinaiya sa langgam ug reptilya, nga ebidensiya nga nagbag-o ang kinabuhi sa paglabay sa panahon."}, "source": "AAAS 10H (fossil evidence for evolution); consensus (Archaeopteryx)", "generator": "claude-workflow", "reviewed": false},
  {"id": "radioactive-decay-heats-earth-g10", "domain": "EARTH_SPACE", "topic": "radioactive decay as Earth's internal heat source", "grades": [9, 10], "terms": ["radioactive decay", "init ng loob ng Earth", "internal heat", "isotope", "desintegrasyon", "mantle convection", "nagpapainit", "pinagmumulan ng init", "radyoaktibo", "kainit sa sulod", "gigikanan sa init", "pagkabulok"], "fact": {"tl": "Ang patuloy na radyoaktibong pagkabulok ng mga isotopo sa loob ng Earth ay nagbibigay ng init na nagpapakilos sa mantle at sa mga plate tektoniko.", "en": "The continual radioactive decay of isotopes inside the Earth provides heat that drives the motion of the mantle and the tectonic plates.", "bis": "Ang padayon nga radyoaktibong pagkabulok sa mga isotope sulod sa Yuta naghatag ug kainit nga nagpalihok sa mantle ug sa mga tectonic plate."}, "source": "NRC ESS2.A/ESS2.B (radioactive decay generates Earth's internal heat)", "generator": "claude-workflow", "reviewed": false},
  {"id": "oldest-fossils-microbes-g10", "domain": "EARTH_SPACE", "topic": "the oldest known fossils are microbes", "grades": [9, 10], "terms": ["oldest fossils", "pinakamatandang fosil", "mikrobyo", "bacteria", "stromatolite", "single-celled", "bilyong taon", "unang buhay", "first life", "mikroskopiko", "labing karaang fossil", "mikrobyong buhi", "usa ka selula"], "fact": {"tl": "Ang pinakamatatandang kilalang fossil ay galing sa mga maliliit na organismong may iisang selula gaya ng bacteria, na nabuhay mga ilang bilyong taon na ang nakalipas.", "en": "The oldest known fossils come from tiny single-celled organisms such as bacteria, which lived several billion years ago.", "bis": "Ang labing karaang nailhan nga mga fossil naggikan sa gagmayng usa-ka-selula nga mga organismo sama sa bacteria, nga nabuhi pipila ka bilyon ka tuig kanhi."}, "source": "Consensus paleobiology (oldest fossils are microbial; encyclopedia-stable)", "generator": "claude-workflow", "reviewed": false},
  {"id": "unconformity-missing-time-g10", "domain": "EARTH_SPACE", "topic": "unconformities and gaps in the rock record", "grades": [9, 10], "terms": ["unconformity", "puwang sa talaan", "nawawalang panahon", "gap", "erosion", "missing time", "walang sediment", "gibara nga panahon", "puwang sa bato", "kawad-on sa rekord", "nawala nga panahon", "gintang"], "fact": {"tl": "Ang unconformity ay isang puwang sa rock record kung saan nawawala ang ilang layer dahil sa erosion o dahil walang nadeposito, kaya may mga nawawalang yugto ng panahon sa talaan ng bato.", "en": "An unconformity is a gap in the rock record where some layers are missing due to erosion or because no sediment was deposited, so spans of time are absent from the record.", "bis": "Ang unconformity usa ka gintang sa rock record diin nawala ang pipila ka layer tungod sa erosion o tungod kay walay sediment nga nasalog, busa adunay nawala nga mga yugto sa panahon sa rekord sa bato."}, "source": "Consensus stratigraphy (unconformity definition; encyclopedia-stable)", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-four-main-layers-g8", "domain": "EARTH_SPACE", "topic": "Earth's four main layers", "grades": [8, 9], "terms": ["lupa", "balat ng lupa", "kalibutan", "yuta", "Earth interior", "layers of the Earth", "crust", "mantle", "core", "balat", "manta", "ubod", "panit sa kalibutan", "mga sapaw", "apat na sapaw", "upat ka sapaw", "tunga sa kalibutan"], "fact": {"tl": "Ang Daigdig ay nahahati sa apat na pangunahing sapaw mula labas papasok: ang crust (balat), ang mantle (manta), ang outer core, at ang inner core.", "en": "The Earth is divided into four main layers from the outside in: the crust, the mantle, the outer core, and the inner core.", "bis": "Ang Kalibutan nabahin sa upat ka nag-unang sapaw gikan sa gawas paingon sa sulod: ang crust (panit), ang mantle, ang outer core, ug ang inner core."}, "source": "AAAS 4C/M1; NRC ESS2.B; encyclopedia consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-crust-thinnest-layer-g8", "domain": "EARTH_SPACE", "topic": "crust is the thinnest outer layer", "grades": [8, 9], "terms": ["crust", "balat ng lupa", "panit sa kalibutan", "pinakamanipis", "pinakanipis", "labas na sapaw", "gawas nga sapaw", "thinnest layer", "solid rock", "matigas na bato", "gahi nga bato", "kapal ng crust", "baga sa crust"], "fact": {"tl": "Ang crust ang pinakamanipis at pinakalabas na sapaw na gawa sa matigas na bato, at dito tayo nakatira at nakatayo ang mga lupain at karagatan.", "en": "The crust is the thinnest, outermost layer made of solid rock, and it is where we live and where the land and oceans rest.", "bis": "Ang crust mao ang pinakanipis ug pinakagawas nga sapaw nga hinimo sa gahi nga bato, ug dinhi kita nagpuyo ug nahimutang ang mga yuta ug kadagatan."}, "source": "AAAS 4C/M11; NRC ESS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-mantle-largest-layer-g8", "domain": "EARTH_SPACE", "topic": "mantle is the thickest layer", "grades": [8, 9], "terms": ["mantle", "manta", "pinakamakapal", "pinakabaga", "thickest layer", "hot rock", "mainit na bato", "init nga bato", "solid rock that flows", "rumararagdag", "umuusad", "naglihok", "silikato", "silicate rock", "pinakamalaki", "pinakadako"], "fact": {"tl": "Ang mantle ang pinakamakapal na sapaw ng Daigdig, gawa sa napakainit na bato na bagaman matigas ay dahan-dahang umuusad sa napakahabang panahon.", "en": "The mantle is the Earth's thickest layer, made of very hot rock that, although solid, slowly flows over very long times.", "bis": "Ang mantle mao ang pinakabaga nga sapaw sa Kalibutan, hinimo sa init kaayo nga bato nga bisan gahi, hinay nga naglihok sulod sa taas kaayo nga panahon."}, "source": "AAAS 4C/M12; NRC ESS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-outer-core-liquid-iron-g8", "domain": "EARTH_SPACE", "topic": "outer core is liquid iron and nickel", "grades": [8, 9], "terms": ["outer core", "labas na ubod", "gawas nga ubod", "liquid", "likido", "tunaw", "natunaw na metal", "tinunaw nga puthaw", "iron", "bakal", "puthaw", "nickel", "nikel", "molten metal", "umaagos na metal", "nagaagos nga metal"], "fact": {"tl": "Ang outer core ay isang sapaw ng likido o tunaw na metal, halos puro bakal at nikel, na umaagos sa paligid ng gitna ng Daigdig.", "en": "The outer core is a layer of liquid or molten metal, mostly iron and nickel, that flows around the center of the Earth.", "bis": "Ang outer core usa ka sapaw sa likido o tunaw nga metal, kasagaran puthaw ug nikel, nga nagaagos palibot sa tunga sa Kalibutan."}, "source": "AAAS 4G/H7; NRC ESS2.B; encyclopedia consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-inner-core-solid-iron-g8", "domain": "EARTH_SPACE", "topic": "inner core is solid iron despite heat", "grades": [8, 9], "terms": ["inner core", "loob na ubod", "sulod nga ubod", "solid iron", "matigas na bakal", "gahi nga puthaw", "pinakamainit", "pinakainit", "gitna ng Daigdig", "tunga sa kalibutan", "presyon", "pressure", "dinidiin", "gipisil", "solid despite heat", "buo bagaman mainit"], "fact": {"tl": "Ang inner core ang pinakaloob at pinakamainit na sapaw, ngunit nananatili itong matigas na bakal dahil sa napakalakas na presyon na dumidiin dito.", "en": "The inner core is the deepest and hottest layer, yet it stays solid iron because of the enormous pressure squeezing it.", "bis": "Ang inner core mao ang pinakasulod ug pinakainit nga sapaw, apan nagpabilin kining gahi nga puthaw tungod sa kusog kaayo nga presyon nga nagpisil niini."}, "source": "NRC ESS2.B; encyclopedia consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-inner-core-hot-as-sun-surface-g9", "domain": "EARTH_SPACE", "topic": "inner core temperature near the Sun's surface", "grades": [8, 9, 10], "terms": ["inner core temperature", "init sa ubod", "temperatura ng ubod", "kainit", "kabugnaw", "mainit gaya ng araw", "sama kainit sa adlaw", "Sun's surface", "ibabaw ng araw", "5000", "thousands of degrees", "libo-libong digri", "libolibo ka degree", "napakainit", "init kaayo"], "fact": {"tl": "Ang inner core ay sobrang init, umaabot ng mga 5,000 digri Celsius, na halos kasing-init ng ibabaw ng Araw.", "en": "The inner core is extremely hot, reaching about 5,000 degrees Celsius, which is almost as hot as the surface of the Sun.", "bis": "Ang inner core init kaayo, moabot ug mga 5,000 ka degree Celsius, nga halos sama kainit sa nawong sa Adlaw."}, "source": "Encyclopedia consensus (geophysics)", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-lithosphere-rigid-shell-g9", "domain": "EARTH_SPACE", "topic": "lithosphere is the rigid outer shell", "grades": [9, 10], "terms": ["lithosphere", "litospera", "matigas na sapaw", "gahi nga sapaw", "rigid shell", "crust at itaas na mantle", "crust ug ibabaw nga mantle", "tectonic plates", "mga plate", "mga plaka", "broken into plates", "nabasag", "nabuak", "buo at matigas", "gahi ug buo"], "fact": {"tl": "Ang lithosphere ang matigas na panlabas na balat ng Daigdig na binubuo ng crust at pinakaitaas na bahagi ng mantle, at ito ang nahahati sa mga tectonic plate.", "en": "The lithosphere is the Earth's rigid outer shell made of the crust and the very top of the mantle, and it is what is broken into the tectonic plates.", "bis": "Ang lithosphere mao ang gahi nga gawas nga panit sa Kalibutan nga gilangkob sa crust ug sa kinatas-ang bahin sa mantle, ug kini ang nabahin sa mga tectonic plate."}, "source": "NRC ESS2.B; AAAS 4C/H4", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-asthenosphere-plates-ride-g9", "domain": "EARTH_SPACE", "topic": "asthenosphere lets plates move", "grades": [9, 10], "terms": ["asthenosphere", "astenospera", "malambot na sapaw", "humok nga sapaw", "bahagyang tunaw", "medyo natunaw", "partially molten", "deformable", "gumagalaw na mantle", "naglihok nga mantle", "kinalalagyan ng plate", "gisakyan sa plate", "plates ride", "nakapatong ang plate", "nagdaganay ang plate", "ductile"], "fact": {"tl": "Sa ilalim ng lithosphere ay ang asthenosphere, isang mas mainit at malambot na bahagi ng mantle kung saan dahan-dahang umuusad ang mga plate na nasa ibabaw nito.", "en": "Beneath the lithosphere lies the asthenosphere, a hotter, softer part of the mantle on which the plates above slowly slide.", "bis": "Ilalom sa lithosphere mao ang asthenosphere, usa ka mas init ug mas humok nga bahin sa mantle diin hinay nga naglihok ang mga plate nga anaa sa ibabaw niini."}, "source": "NRC ESS2.B; AAAS 4C/H4", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-lithosphere-vs-asthenosphere-g9", "domain": "EARTH_SPACE", "topic": "lithosphere vs asthenosphere by behavior not composition", "grades": [9, 10], "terms": ["lithosphere vs asthenosphere", "pagkakaiba", "kalainan", "matigas vs malambot", "gahi vs humok", "kilos ng bato", "lihok sa bato", "behavior", "asal ng bato", "kung paano gumagalaw", "kung giunsa paglihok", "same rock different behavior", "magkaibang galaw"], "fact": {"tl": "Ang pagkakaiba ng lithosphere at asthenosphere ay nasa kung paano kumikilos ang bato: matigas at madaling mabasag ang lithosphere, samantalang mas mainit at madaling humubog ang asthenosphere.", "en": "The difference between the lithosphere and asthenosphere is in how the rock behaves: the lithosphere is rigid and brittle, while the asthenosphere is hotter and able to flow.", "bis": "Ang kalainan sa lithosphere ug asthenosphere anaa sa kung giunsa paglihok sa bato: ang lithosphere gahi ug daling mabuak, samtang ang asthenosphere mas init ug makahimo paglihok."}, "source": "NRC ESS2.B; encyclopedia consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-seismic-waves-probe-interior-g9", "domain": "EARTH_SPACE", "topic": "seismic waves reveal Earth's interior", "grades": [8, 9, 10], "terms": ["seismic waves", "mga alon ng lindol", "balod sa linog", "earthquake waves", "alon ng paglindol", "naghahayag ng loob", "nagpadayag sa sulod", "probe interior", "x-ray ng lupa", "sinusuri ang ilalim", "gisusi ang ilalom", "how we know the layers", "kung paano natuklasan", "geologist", "heologo", "geologo"], "fact": {"tl": "Hindi kayang butasin ng tao ang Daigdig, kaya ginagamit ng mga siyentipiko ang mga seismic wave mula sa lindol na parang x-ray upang malaman ang anyo ng mga sapaw sa loob.", "en": "People cannot drill into the deep Earth, so scientists use seismic waves from earthquakes like an x-ray to discover the shape of the layers inside.", "bis": "Dili kaya sa tawo ang pagbangag sa lawom nga Kalibutan, mao nga ginagamit sa mga siyentista ang mga seismic wave gikan sa linog sama sa x-ray aron mahibal-an ang dagway sa mga sapaw sa sulod."}, "source": "NRC PS4.A (grade 12): 'Geologists use seismic waves and their reflection at interfaces between layers to probe structures deep in the planet.'", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-p-waves-s-waves-g9", "domain": "EARTH_SPACE", "topic": "P-waves and S-waves", "grades": [9, 10], "terms": ["P-waves", "S-waves", "primary wave", "secondary wave", "P wave at S wave", "P wave ug S wave", "mabilis na alon", "paspas nga balod", "mabagal na alon", "hinay nga balod", "una at pangalawang alon", "una ug ikaduhang balod", "two kinds of seismic waves", "dalawang uri ng alon", "duha ka klase sa balod"], "fact": {"tl": "May dalawang pangunahing uri ng seismic wave: ang mas mabilis na P-wave na unang dumarating, at ang mas mabagal na S-wave na sumusunod.", "en": "There are two main kinds of seismic waves: the faster P-waves, which arrive first, and the slower S-waves, which follow.", "bis": "Adunay duha ka nag-unang klase sa seismic wave: ang mas paspas nga P-wave nga mouna ug abot, ug ang mas hinay nga S-wave nga mosunod."}, "source": "Encyclopedia consensus (seismology)", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-s-waves-stop-liquid-core-g9", "domain": "EARTH_SPACE", "topic": "S-waves cannot pass the liquid outer core", "grades": [9, 10], "terms": ["S-waves stop", "hindi dumadaan", "dili moagi", "liquid outer core", "likidong ubod", "likido nga ubod", "S-wave hindi makalusot", "dili makalusot ang S-wave", "patunay na likido", "pamatuod nga likido", "proof core is liquid", "hindi dumadaan sa likido", "dili moagi sa likido", "natuklasan ang likidong core"], "fact": {"tl": "Hindi kayang dumaan ng S-wave sa likido, kaya nang mapansin na hindi ito lumalagos sa outer core, napatunayan ng mga siyentista na ang outer core ay likido.", "en": "S-waves cannot pass through liquid, so when scientists saw that they do not travel through the outer core, this proved that the outer core is liquid.", "bis": "Ang S-wave dili makaagi sa likido, mao nga sa dihang namatikdan nga dili kini molusot sa outer core, napamatud-an sa mga siyentista nga ang outer core likido."}, "source": "Encyclopedia consensus (seismology); NRC PS4.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-seismic-shadow-zone-g10", "domain": "EARTH_SPACE", "topic": "seismic shadow zone reveals the core", "grades": [9, 10], "terms": ["shadow zone", "anino ng alon", "landong sa balod", "seismic shadow", "walang umaabot na alon", "walay abot nga balod", "naharang ng core", "nababalda ng ubod", "gibabagan sa ubod", "bumebende ang alon", "nagliko ang alon", "naliko nga balod", "bending of waves", "natuklasan ang core"], "fact": {"tl": "Ang likidong outer core ay humaharang at nagpapaliko sa mga seismic wave, kaya may mga lugar sa kabilang panig ng Daigdig na walang umaabot na alon, tinatawag na shadow zone.", "en": "The liquid outer core blocks and bends seismic waves, so there are regions on the far side of the Earth where no waves arrive, called the shadow zone.", "bis": "Ang likido nga outer core nagbabag ug nagliko sa mga seismic wave, mao nga adunay mga dapit sa pikas bahin sa Kalibutan diin walay balod nga moabot, gitawag nga shadow zone."}, "source": "Encyclopedia consensus (seismology)", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-waves-bend-at-boundaries-g10", "domain": "EARTH_SPACE", "topic": "waves refract and reflect at layer boundaries", "grades": [9, 10], "terms": ["bending of seismic waves", "pagliko ng alon", "pagliko sa balod", "refraction", "reflection", "nagbabago ng bilis", "nag-usab ug katulin", "hangganan ng sapaw", "utlanan sa sapaw", "boundary between layers", "nagbabago ang daloy", "nag-usab ang agos", "iba't ibang bato", "lainlaing bato", "pagbabago ng anggulo"], "fact": {"tl": "Kapag tumatawid ang seismic wave mula sa isang sapaw papunta sa ibang sapaw, nagbabago ang bilis nito at lumiliko, at sa pamamagitan ng pagsusuri nito nalalaman ang lalim ng bawat hangganan.", "en": "When a seismic wave crosses from one layer into another, it changes speed and bends, and by studying this scientists find the depth of each boundary.", "bis": "Kung ang seismic wave motabok gikan sa usa ka sapaw paingon sa lain, mausab ang katulin niini ug moliko, ug pinaagi sa pagtuon niini mahibal-an ang giladmon sa matag utlanan."}, "source": "NRC PS4.A (grade 8/12): waves reflect/refract at interfaces between media", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-moho-crust-mantle-boundary-g10", "domain": "EARTH_SPACE", "topic": "Mohorovicic discontinuity (the Moho)", "grades": [9, 10], "terms": ["Moho", "Mohorovicic discontinuity", "hangganan ng crust at mantle", "utlanan sa crust ug mantle", "boundary crust mantle", "biglang bumilis ang alon", "kalit nga mipaspas ang balod", "pagbabago ng bilis", "pag-usab sa katulin", "natuklasan sa alon ng lindol", "discontinuity", "sapaw na hangganan"], "fact": {"tl": "Ang hangganan sa pagitan ng crust at mantle ay tinatawag na Moho, at natuklasan ito nang mapansing biglang bumibilis ang seismic wave habang lumalampas sa antas na iyon.", "en": "The boundary between the crust and the mantle is called the Moho, and it was discovered when seismic waves were seen to suddenly speed up as they passed that level.", "bis": "Ang utlanan tali sa crust ug mantle gitawag nga Moho, ug nadiskobrehan kini sa dihang namatikdan nga kalit nga mipaspas ang seismic wave samtang miagi nianang lebela."}, "source": "Encyclopedia consensus (seismology; Mohorovičić 1909)", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-temperature-rises-with-depth-g8", "domain": "EARTH_SPACE", "topic": "temperature increases with depth", "grades": [8, 9], "terms": ["geothermal gradient", "init paubos", "init paingon sa ilalom", "mas mainit pababa", "mas init paubos", "temperature with depth", "lalim at init", "kalalom ug kainit", "pailalim mas mainit", "init sa ilalom", "internal heat", "init sa sulod", "loob na init", "minahan na mainit", "deeper hotter"], "fact": {"tl": "Habang papalalim sa loob ng Daigdig, lalong tumataas ang temperatura, kaya napakainit na sa loob ng malalalim na minahan at lalo pa sa mantle at core.", "en": "As you go deeper into the Earth, the temperature keeps rising, which is why deep mines are already hot and the mantle and core are far hotter still.", "bis": "Samtang mosalom sa sulod sa Kalibutan, mas motaas ang temperatura, mao nga init na kaayo sulod sa lawom nga mga minahan ug mas init pa ang mantle ug core."}, "source": "AAAS 4C/M1; NRC ESS2.A; encyclopedia consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-internal-heat-sources-g10", "domain": "EARTH_SPACE", "topic": "where Earth's internal heat comes from", "grades": [9, 10], "terms": ["internal heat", "init sa kalibutan", "init sa sulod", "pinagmumulan ng init", "gigikanan sa init", "radioactive decay", "radyaktibong elemento", "radioactive nga elemento", "natirang init sa pagkabuo", "nahabilin nga init", "leftover heat", "init mula sa pagkaform", "pagkabuo ng daigdig", "pagkahimo sa kalibutan"], "fact": {"tl": "Ang init sa loob ng Daigdig ay nagmumula sa natirang init noong unang nabuo ang planeta at sa unti-unting pagkasira ng mga radyaktibong elemento sa bato.", "en": "The heat inside the Earth comes from leftover heat from when the planet first formed and from the slow decay of radioactive elements in the rock.", "bis": "Ang init sulod sa Kalibutan naggikan sa nahabilin nga init sa dihang una nahimo ang planeta ug sa hinay nga pagkadunot sa mga radioactive nga elemento sa bato."}, "source": "NRC ESS2.A; encyclopedia consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-internal-heat-drives-plates-g9", "domain": "EARTH_SPACE", "topic": "internal heat drives plate motion and quakes", "grades": [9, 10], "terms": ["init na nagtutulak", "init nga nagtulod", "internal heat drives plates", "init na sanhi ng lindol", "init nga hinungdan sa linog", "convection", "pag-akyat ng mainit na bato", "pagsaka sa init nga bato", "rising hot rock", "lumulubog na malamig", "naglugsong nga bugnaw", "pag-usad ng plate", "lihok sa plate", "bulkan at lindol"], "fact": {"tl": "Ang paglabas ng init mula sa loob ng Daigdig ang nagtutulak sa dahan-dahang pag-usad ng mga plate, na siyang nagdudulot ng mga lindol, bulkan, at pagbuo ng bundok.", "en": "The outward flow of heat from inside the Earth drives the slow movement of the plates, which in turn causes earthquakes, volcanoes, and the building of mountains.", "bis": "Ang paggawas sa init gikan sa sulod sa Kalibutan mao ang nagtulod sa hinay nga paglihok sa mga plate, nga maoy hinungdan sa mga linog, bulkan, ug pagtukod sa kabukiran."}, "source": "AAAS 4C/H3; NRC ESS2.A/ESS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-density-increases-with-depth-g10", "domain": "EARTH_SPACE", "topic": "density increases toward the core", "grades": [9, 10], "terms": ["density", "densidad", "kabug-aton", "bigat ng bato", "kabug-at sa bato", "mas mabigat pailalim", "mas bug-at paubos", "denser core", "mabigat na metal", "bug-at nga metal", "magaan na crust", "gaan nga crust", "core mabigat", "denser toward center", "mas masinsin", "mas hugot"], "fact": {"tl": "Mas mabigat at masinsin ang mga sapaw habang papalapit sa gitna ng Daigdig, kaya ang magaan na bato ay nasa crust at ang mabibigat na metal na bakal at nikel ay nasa core.", "en": "The layers become heavier and denser toward the center of the Earth, so the lighter rock is in the crust and the heavy metals iron and nickel are in the core.", "bis": "Ang mga sapaw mahimong mas bug-at ug mas siksik samtang nagkaduol sa tunga sa Kalibutan, mao nga ang mas gaan nga bato anaa sa crust ug ang bug-at nga metal nga puthaw ug nikel anaa sa core."}, "source": "Encyclopedia consensus (geophysics); AAAS 4C/H3", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-magnetic-field-from-core-g9", "domain": "EARTH_SPACE", "topic": "Earth's magnetic field comes from the core", "grades": [8, 9, 10], "terms": ["magnetic field", "magnetikong larangan", "magnetikong puwersa", "magnetikong natad", "Earth's magnet", "magneto ng daigdig", "magnet sa kalibutan", "nagmumula sa core", "naggikan sa ubod", "umaagos na bakal", "nagaagos nga puthaw", "electric current sa loob", "koryente sa sulod", "geomagnetic", "magnetikong larang"], "fact": {"tl": "Ang Daigdig ay may sariling magnetikong larangan na nagmumula sa mga elektrikong agos sa loob ng umaagos at likidong outer core.", "en": "The Earth has its own magnetic field that comes from electric currents inside its swirling, liquid outer core.", "bis": "Ang Kalibutan adunay kaugalingong magnetikong natad nga naggikan sa mga elektrikong agos sulod sa nagatuyok, likido nga outer core."}, "source": "AAAS 4G/H7: 'Electric currents in the earth's interior give the earth an extensive magnetic field.'", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-geodynamo-moving-iron-g10", "domain": "EARTH_SPACE", "topic": "the geodynamo of the outer core", "grades": [9, 10], "terms": ["geodynamo", "dynamo", "dinamo", "gumagalaw na bakal", "naglihok nga puthaw", "moving molten iron", "umiikot na metal", "nagtuyok nga metal", "convection sa core", "init at pag-ikot", "init ug pagtuyok", "gumagawa ng magnetic field", "naghimo sa magnetikong natad", "nagliligtas sa pag-ikot", "spinning Earth", "pag-ikot ng daigdig"], "fact": {"tl": "Ang patuloy na pag-agos at pag-ikot ng mainit, likidong bakal sa outer core ay gumagawa ng magnetikong larangan ng Daigdig sa paraang tinatawag na geodynamo.", "en": "The constant flowing and swirling of hot, liquid iron in the outer core generates the Earth's magnetic field through a process called the geodynamo.", "bis": "Ang padayon nga pag-agos ug pagtuyok sa init, likido nga puthaw sa outer core maoy naghimo sa magnetikong natad sa Kalibutan pinaagi sa proseso nga gitawag nga geodynamo."}, "source": "Encyclopedia consensus (geomagnetism); AAAS 4G/H7", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-magnetic-field-shields-g9", "domain": "EARTH_SPACE", "topic": "magnetic field shields Earth from solar wind", "grades": [8, 9, 10], "terms": ["magnetic shield", "panangga sa init", "taming sa kalibutan", "nagsasanggalang", "nagpanalipod", "solar wind", "hangin ng araw", "hangin sa adlaw", "nakakapinsalang radiation", "makadaot nga radiation", "pinoprotektahan ang buhay", "gipanalipdan ang kinabuhi", "harmful particles", "mapanganib na partikulo", "magnetosphere"], "fact": {"tl": "Ang magnetikong larangan ng Daigdig ay parang taming na sumasalo sa mga nakakapinsalang partikulo mula sa solar wind ng Araw, na nagpoprotekta sa buhay sa ibabaw ng planeta.", "en": "The Earth's magnetic field acts like a shield that catches harmful particles from the Sun's solar wind, protecting life on the planet's surface.", "bis": "Ang magnetikong natad sa Kalibutan sama sa taming nga nagsalo sa mga makadaot nga partikulo gikan sa solar wind sa Adlaw, nga nagpanalipod sa kinabuhi sa nawong sa planeta."}, "source": "Encyclopedia consensus (space physics)", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-magnetic-field-makes-aurora-g9", "domain": "EARTH_SPACE", "topic": "magnetic field and the auroras", "grades": [8, 9, 10], "terms": ["aurora", "northern lights", "ilaw sa langit", "kahayag sa langit", "magnetikong larangan at aurora", "ginabira ang partikulo sa poste", "particles to the poles", "partikulo papunta sa poste", "nagliliwanag na langit", "nagdan-ag nga langit", "polar lights", "ilaw sa polo", "kahayag sa pole", "solar wind aurora"], "fact": {"tl": "Ginagabay ng magnetikong larangan ng Daigdig ang mga partikulo mula sa Araw papunta sa mga poste, kung saan nagdudulot ng makukulay na liwanag sa langit na tinatawag na aurora.", "en": "The Earth's magnetic field guides particles from the Sun toward the poles, where they create the colorful glowing lights in the sky called auroras.", "bis": "Ang magnetikong natad sa Kalibutan nagagiya sa mga partikulo gikan sa Adlaw paingon sa mga polo, diin naghimo sila ug bulokon nga kahayag sa langit nga gitawag nga aurora."}, "source": "Encyclopedia consensus (space physics)", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-magnetic-poles-not-true-poles-g9", "domain": "EARTH_SPACE", "topic": "magnetic poles differ from geographic poles", "grades": [9, 10], "terms": ["magnetic poles", "magnetikong poste", "magnetikong polo", "geographic poles", "tunay na poste", "tinuod nga polo", "hindi magkapareho", "dili pareho", "compass", "kompas", "brujula", "hindi tumpak na hilaga", "dili tukma nga amihan", "magnetic north", "magnetikong hilaga", "magnetikong amihanan", "nagbabago ang poste"], "fact": {"tl": "Ang magnetikong poste ng Daigdig, na tinuturo ng kompas, ay hindi eksaktong nasa parehong lugar ng tunay na hilaga at timog na poste ng pag-ikot ng planeta.", "en": "The Earth's magnetic poles, which a compass points to, are not in exactly the same place as the true north and south poles of the planet's spin.", "bis": "Ang magnetikong polo sa Kalibutan, nga gitudlo sa kompas, dili eksakto nga anaa sa samang dapit sa tinuod nga amihanan ug habagatan nga polo sa pagtuyok sa planeta."}, "source": "Encyclopedia consensus (geomagnetism)", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-magnetic-poles-wander-g10", "domain": "EARTH_SPACE", "topic": "magnetic poles slowly move and can reverse", "grades": [9, 10], "terms": ["magnetic pole movement", "gumagalaw na poste", "naglihok nga polo", "magnetic pole wander", "nag-iiba ang magnetikong hilaga", "nausab ang magnetikong amihan", "pole reversal", "pagbaligtad ng poste", "pagbalit-ad sa polo", "nagbabago sa paglipas ng panahon", "nausab sa paglabay sa panahon", "hindi nakapirmi", "dili pirmi", "changes over time"], "fact": {"tl": "Ang magnetikong poste ng Daigdig ay dahan-dahang gumagalaw sa paglipas ng panahon, at sa napakahabang panahon ay nakapagpapalit pa ng direksyon ang buong magnetikong larangan.", "en": "The Earth's magnetic poles slowly move over time, and over very long ages the whole magnetic field can even reverse direction.", "bis": "Ang magnetikong polo sa Kalibutan hinay nga naglihok sa paglabay sa panahon, ug sulod sa taas kaayo nga mga panahon mahimo pa nga mobalit-ad ang tibuok magnetikong natad."}, "source": "Encyclopedia consensus (paleomagnetism)", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-rocks-record-magnetism-g10", "domain": "EARTH_SPACE", "topic": "cooling lava records the magnetic field", "grades": [9, 10], "terms": ["paleomagnetism", "magnetikong tala sa bato", "magnetikong rekord sa bato", "lumalamig na lava", "nagbugnaw nga lava", "cooling lava", "nakatala ang magnetismo", "narekord ang magnetismo", "frozen magnetism", "patunay ng pagbaligtad", "pamatuod sa pagbalit-ad", "bato na may magnetismo", "rekord sa karaang natad", "ancient field"], "fact": {"tl": "Kapag lumalamig at tumitigas ang lava, nakukuha at nananatili dito ang direksyon ng magnetikong larangan sa panahong iyon, kaya nababasa ng mga siyentipiko ang dating magnetismo ng Daigdig sa mga lumang bato.", "en": "When lava cools and hardens, it locks in the direction of the magnetic field at that time, so scientists can read the Earth's past magnetism in old rocks.", "bis": "Kung mobugnaw ug motig-a ang lava, makuha ug magpabilin niini ang direksyon sa magnetikong natad nianang panahona, mao nga mabasa sa mga siyentista ang kanhing magnetismo sa Kalibutan diha sa karaang mga bato."}, "source": "Encyclopedia consensus (paleomagnetism)", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-deepest-drill-tiny-g9", "domain": "EARTH_SPACE", "topic": "deepest borehole barely scratches the crust", "grades": [8, 9], "terms": ["deepest hole", "pinakamalalim na butas", "pinakalawom nga bangag", "borehole", "pagbabarena", "pagbangag", "hindi kayang abutin ang mantle", "dili maabot ang mantle", "manipis na parte lang", "nipis ra nga bahin", "12 kilometro", "scratch the surface", "balat lang ang naabot", "panit ra ang naabot", "drilling limit"], "fact": {"tl": "Ang pinakamalalim na butas na nabarena ng tao ay umabot lamang ng mga 12 kilometro, na napakanipis pa lamang kumpara sa kapal ng buong crust, kaya hindi pa kayang marating ang mantle.", "en": "The deepest hole people have ever drilled reached only about 12 kilometers, which is just a thin scratch compared with the whole crust, so the mantle has never been reached.", "bis": "Ang pinakalawom nga bangag nga nabangag sa tawo miabot lang ug mga 12 ka kilometro, nga nipis pa kaayo kumpara sa baga sa tibuok crust, mao nga wala pa gayud maabot ang mantle."}, "source": "Encyclopedia consensus (Kola Superdeep Borehole, ~12.3 km)", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-crust-thickness-varies-g9", "domain": "EARTH_SPACE", "topic": "oceanic crust thinner than continental crust", "grades": [9, 10], "terms": ["crust thickness", "kapal ng crust", "baga sa crust", "manipis na oceanic", "nipis nga oceanic", "makapal na continental", "baga nga continental", "ilalim ng dagat", "ilalom sa dagat", "ocean crust", "land crust", "crust sa yuta", "thinner under ocean", "mas manipis sa dagat", "mas nipis ilalom sa dagat"], "fact": {"tl": "Hindi pare-pareho ang kapal ng crust: mas manipis ang oceanic crust sa ilalim ng karagatan, samantalang mas makapal ang continental crust na bumubuo sa mga lupain.", "en": "The crust is not equally thick everywhere: the oceanic crust under the seas is thinner, while the continental crust that makes up the land is thicker.", "bis": "Ang crust dili pareho ang kabaga: mas nipis ang oceanic crust sa ilalom sa kadagatan, samtang mas baga ang continental crust nga naglangkob sa mga yuta."}, "source": "AAAS 4C/H4; encyclopedia consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-mantle-convection-cells-g10", "domain": "EARTH_SPACE", "topic": "mantle convection cells circulate heat", "grades": [9, 10], "terms": ["convection cell", "siklo ng init", "sirkulo sa init", "pag-akyat at paglubog", "pagsaka ug paglugsong", "umiikot na bato", "nagtuyok nga bato", "mantle convection", "init na umaakyat", "init nga mosaka", "malamig na bumababa", "bugnaw nga mokanaog", "loop ng init", "sirkulasyon sa init", "circulating rock", "umiinog na bato"], "fact": {"tl": "Sa loob ng mantle, ang mas mainit na bato ay umaakyat habang ang mas malamig ay lumulubog, na bumubuo ng mabagal na umiinog na siklo ng init na tinatawag na convection.", "en": "Within the mantle, hotter rock rises while cooler rock sinks, forming slow circulating loops of heat called convection cells.", "bis": "Sulod sa mantle, ang mas init nga bato mosaka samtang ang mas bugnaw molugsong, nga naghimo sa hinay nga nagtuyok nga mga sirkulo sa init nga gitawag nga convection."}, "source": "NRC ESS2.A; AAAS 4C/H3", "generator": "claude-workflow", "reviewed": false},
  {"id": "nebular-hypothesis-formation-g9", "domain": "EARTH_SPACE", "topic": "nebular hypothesis solar system formation", "grades": [8, 9, 10], "terms": ["solar nebula", "nebular hypothesis", "nebular", "ulap ng gas at alikabok", "panganod sa gas ug abog", "cloud of gas and dust", "nabuo", "naporma", "formed", "grabidad", "gravity", "bumagsak", "naglupad", "collapse", "Araw", "Adlaw", "Sun", "planeta", "planet", "bilyong taon", "billion years", "4.6 billion", "4.6 bilyong taon", "nagsimula", "nagsugod"], "fact": {"tl": "Ayon sa nebular hypothesis, ang Araw at mga planeta ay nabuo mga 4.6 bilyong taon na ang nakalipas mula sa isang malaking umiikot na ulap ng gas at alikabok (solar nebula) na hinila ng grabidad upang gumuho at magtipon.", "en": "According to the nebular hypothesis, the Sun and planets formed about 4.6 billion years ago from a giant spinning cloud of gas and dust (the solar nebula) that gravity pulled together and made collapse.", "bis": "Sumala sa nebular hypothesis, ang Adlaw ug mga planeta naporma mga 4.6 ka bilyong tuig na ang milabay gikan sa usa ka dakong nagatuyok nga panganod sa gas ug abog (solar nebula) nga gibira sa grabidad aron maguba ug magtapok."}, "source": "NRC ESS1.B (forming disk of dust and gas); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "protoplanetary-disk-spin-g9", "domain": "EARTH_SPACE", "topic": "protoplanetary disk flattening and spin", "grades": [8, 9, 10], "terms": ["protoplanetary disk", "umiikot na disk", "nagatuyok nga disk", "spinning disk", "lumapad", "naglapad", "flattened", "pumayat na disk", "rumikit ang ikot", "spin faster", "bumilis", "nagpaspas", "konserbasyon ng angular momentum", "disk ng pinggan", "gas ug abog", "gas and dust", "Araw sa gitna", "Adlaw sa tunga", "Sun at center"], "fact": {"tl": "Habang gumuguho ang solar nebula, bumilis ang pag-ikot nito at lumapad ito tulad ng isang pinggan, kaya umiikot ang mga planeta ngayon sa halos parehong patag na ibabaw at parehong direksyon.", "en": "As the solar nebula collapsed it spun faster and flattened into a disk, which is why the planets today orbit in nearly the same flat plane and the same direction.", "bis": "Samtang naguba ang solar nebula, nagkapaspas ang pagtuyok niini ug naglapad sama sa usa ka plato, mao nga ang mga planeta karon molibot sa halos samang patag nga ang-ang ug samang direksyon."}, "source": "encyclopedia-stable consensus (nebular theory); NRC ESS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "accretion-planetesimals-g9", "domain": "EARTH_SPACE", "topic": "accretion of planetesimals into planets", "grades": [8, 9, 10], "terms": ["accretion", "pagdikit-dikit", "pagtapot", "sticking together", "planetesimals", "maliliit na bato", "gagmayng bato", "small rocks", "nagtipon", "nagtapok", "clumped", "nabuo ang planeta", "naporma ang planeta", "grew into planets", "banggaan", "pagbangga", "collision", "lumaki", "midako", "grew"], "fact": {"tl": "Ang mga planeta ay nabuo sa pamamagitan ng accretion: nagdikit-dikit ang maliliit na butil ng alikabok at yelo upang maging mas malalaking bato (planetesimals), na patuloy na nagbangga at lumaki hanggang maging planeta.", "en": "Planets formed by accretion: tiny grains of dust and ice stuck together into bigger rocks called planetesimals, which kept colliding and growing until they became planets.", "bis": "Ang mga planeta naporma pinaagi sa accretion: ang gagmayng tipik sa abog ug yelo nagdikit-dikit ngadto sa dagkong bato nga gitawag og planetesimals, nga padayong nagbangga ug midako hangtod nahimong planeta."}, "source": "encyclopedia-stable consensus (planetary accretion)", "generator": "claude-workflow", "reviewed": false},
  {"id": "rocky-inner-icy-outer-formation-g9", "domain": "EARTH_SPACE", "topic": "why inner planets are rocky and outer are gas giants", "grades": [8, 9, 10], "terms": ["frost line", "snow line", "linya ng yelo", "linya sa yelo", "mainit malapit sa Araw", "init duol sa Adlaw", "hot near Sun", "bato", "rocky", "metal", "yelo", "ice", "gas giant", "higanteng gas", "malayo malamig", "layo bugnaw", "far cold", "Jupiter", "loob na planeta", "sulod nga planeta", "inner planet", "labas na planeta", "gawas nga planeta"], "fact": {"tl": "Ang mga loob na planeta ay mabato dahil sa init malapit sa Araw, tanging metal at bato lang ang nananatiling solido, samantalang sa malamig na malayong bahagi nakapagtipon ng gas at yelo ang malalaking gas giant.", "en": "The inner planets are rocky because near the hot Sun only metal and rock stayed solid, while in the cold outer region the gas giants could gather lots of gas and ice.", "bis": "Ang mga sulod nga planeta batoon tungod sa init duol sa Adlaw, metal ug bato ra ang nagpabiling solido, samtang sa bugnaw nga layo nga bahin ang dagkong gas giant nakatigom og daghang gas ug yelo."}, "source": "encyclopedia-stable consensus (frost line / planet formation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-mass-share-g9", "domain": "EARTH_SPACE", "topic": "Sun holds most of solar system mass", "grades": [7, 8, 9, 10], "terms": ["Araw", "Adlaw", "Sun", "99 porsiyento", "99 percent", "halos lahat ng masa", "halos tanang masa", "almost all the mass", "bigat", "kabug-aton", "mass", "grabidad", "gravity", "umiikot ang planeta", "molibot ang planeta", "orbit", "malaki", "dako", "huge"], "fact": {"tl": "Ang Araw ang may hawak ng higit sa 99% ng kabuuang masa ng solar system, kaya napakalakas ng grabidad nito at dito umiikot ang lahat ng planeta.", "en": "The Sun holds more than 99% of all the mass in the solar system, so its gravity is strong enough to keep every planet in orbit around it.", "bis": "Ang Adlaw maoy naghupot sa kapin sa 99% sa tanang masa sa solar system, mao nga kusgan kaayo ang grabidad niini ug niini molibot ang tanang planeta."}, "source": "encyclopedia-stable consensus; NRC ESS1.B (gravity holds objects in orbit)", "generator": "claude-workflow", "reviewed": false},
  {"id": "dwarf-planet-definition-g9", "domain": "EARTH_SPACE", "topic": "what makes a dwarf planet", "grades": [8, 9, 10], "terms": ["dwarf planet", "duwendeng planeta", "bilog dahil sa grabidad", "lingin tungod sa grabidad", "round by gravity", "hindi nalinis ang orbit", "wala malimpyohi ang orbit", "not cleared orbit", "umiikot sa Araw", "molibot sa Adlaw", "orbits Sun", "Pluto", "Ceres", "Eris", "IAU", "kahulugan", "kahulogan", "definition", "maliit", "gamay"], "fact": {"tl": "Ang dwarf planet ay umiikot sa Araw at sapat ang laki para maging bilog dahil sa grabidad nito, ngunit hindi nito nalinis ang ibang bagay sa daan ng orbit nito, kaya hindi ito itinuturing na ganap na planeta.", "en": "A dwarf planet orbits the Sun and is big enough to be round from its own gravity, but it has not cleared other objects out of its orbit, so it is not counted as a full planet.", "bis": "Ang dwarf planet molibot sa Adlaw ug igo ang gidak-on aron mahimong lingin tungod sa grabidad niini, apan wala niini malimpyohi ang ubang butang sa agianan sa orbit niini, mao nga dili kini giisip nga hingpit nga planeta."}, "source": "IAU 2006 definition; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ceres-dwarf-planet-belt-g9", "domain": "EARTH_SPACE", "topic": "Ceres dwarf planet in asteroid belt", "grades": [8, 9, 10], "terms": ["Ceres", "dwarf planet", "duwendeng planeta", "asteroid belt", "sinturon ng asteroid", "bakus sa asteroid", "pinakamalaki sa belt", "kinadak-an sa belt", "largest in belt", "Mars at Jupiter", "Mars ug Jupiter", "between Mars Jupiter", "bilog", "lingin", "round", "tubig na yelo", "tubig nga yelo", "water ice"], "fact": {"tl": "Ang Ceres ang pinakamalaking bagay sa asteroid belt sa pagitan ng Mars at Jupiter, at sapat ang laki nito para maging bilog kaya itinuturing din itong dwarf planet.", "en": "Ceres is the largest object in the asteroid belt between Mars and Jupiter, and it is big enough to be round, so it is also classed as a dwarf planet.", "bis": "Ang Ceres maoy kinadak-ang butang sa asteroid belt sa tunga sa Mars ug Jupiter, ug igo ang gidak-on niini aron mahimong lingin mao nga giisip usab kini nga dwarf planet."}, "source": "encyclopedia-stable consensus (NASA Dawn mission)", "generator": "claude-workflow", "reviewed": false},
  {"id": "eris-massive-dwarf-g9", "domain": "EARTH_SPACE", "topic": "Eris and the reclassification of Pluto", "grades": [8, 9, 10], "terms": ["Eris", "dwarf planet", "duwendeng planeta", "kasimbigat ng Pluto", "sama kabug-at sa Pluto", "as massive as Pluto", "malayo pa sa Pluto", "mas layo pa sa Pluto", "farther than Pluto", "natuklasan", "nadiskobre", "discovered 2005", "dahilan kaya na-demote ang Pluto", "hinungdan", "led to Pluto reclassification", "Kuiper belt", "scattered disk"], "fact": {"tl": "Ang pagkatuklas sa Eris noong 2005, na halos kasinglaki at kasimbigat ng Pluto, ang isa sa mga dahilan kung bakit nagdesisyon ang mga siyentipiko na muling tukuyin ang Pluto bilang dwarf planet.", "en": "The discovery of Eris in 2005, almost the same size and mass as Pluto, was one reason scientists decided to reclassify Pluto as a dwarf planet.", "bis": "Ang pagkadiskobre sa Eris niadtong 2005, halos pareho ang gidak-on ug kabug-aton sa Pluto, maoy usa sa mga hinungdan nganong gidesisyonan sa mga syentista nga usbon ang klasipikasyon sa Pluto ngadto sa dwarf planet."}, "source": "encyclopedia-stable consensus; IAU 2006", "generator": "claude-workflow", "reviewed": false},
  {"id": "kuiper-belt-region-g9", "domain": "EARTH_SPACE", "topic": "Kuiper belt beyond Neptune", "grades": [8, 9, 10], "terms": ["Kuiper belt", "sinturon ng Kuiper", "bakus sa Kuiper", "lampas sa Neptune", "lapas sa Neptune", "beyond Neptune", "lugar ng yelo at bato", "dapit sa yelo ug bato", "icy region", "Pluto", "dwarf planet", "comet", "kometa", "maraming maliliit na bagay", "daghang gagmayng butang", "many small icy bodies", "labas na bahagi", "gawas nga bahin"], "fact": {"tl": "Ang Kuiper belt ay isang malawak na lugar ng yelong-bato na bagay sa labas ng orbit ng Neptune, kung saan matatagpuan ang Pluto at marami pang dwarf planet at maliliit na nilalamig na bagay.", "en": "The Kuiper belt is a wide region of icy-rocky objects beyond Neptune's orbit, where Pluto and many other dwarf planets and small icy bodies are found.", "bis": "Ang Kuiper belt usa ka lapad nga dapit sa yelo-bato nga mga butang lapas sa orbit sa Neptune, diin makit-an ang Pluto ug daghan pang dwarf planet ug gagmayng bugnaw nga mga butang."}, "source": "encyclopedia-stable consensus (NASA)", "generator": "claude-workflow", "reviewed": false},
  {"id": "kuiper-belt-comet-source-g9", "domain": "EARTH_SPACE", "topic": "Kuiper belt as source of short-period comets", "grades": [9, 10], "terms": ["Kuiper belt", "sinturon ng Kuiper", "bakus sa Kuiper", "pinagmulan ng kometa", "tinubdan sa kometa", "source of comets", "short-period comet", "maikli ang ikot", "mubo ang libot", "comet", "kometa", "yelo", "yelo nga bato", "ice", "Neptune", "pinapunta sa loob ng grabidad", "gibira sa grabidad", "nudged inward"], "fact": {"tl": "Maraming kometang mabilis bumalik (short-period comet) ang nagmumula sa Kuiper belt, kapag may grabidad na humila sa isang yelong bagay papasok patungong loob na bahagi ng solar system.", "en": "Many short-period comets come from the Kuiper belt, when gravity nudges an icy object inward toward the inner solar system.", "bis": "Daghang kometa nga paspas mobalik (short-period comet) gikan sa Kuiper belt, kon adunay grabidad nga mobira sa usa ka bugnaw nga butang paingon sa sulod nga bahin sa solar system."}, "source": "encyclopedia-stable consensus (cometary origins)", "generator": "claude-workflow", "reviewed": false},
  {"id": "oort-cloud-distant-comets-g9", "domain": "EARTH_SPACE", "topic": "Oort cloud distant comet shell", "grades": [9, 10], "terms": ["Oort cloud", "ulap ng Oort", "panganod sa Oort", "napakalayo", "halayo kaayo", "very far", "shell ng yelo", "balot sa yelo", "icy shell", "long-period comet", "matagal bago bumalik", "dugay mobalik", "comet", "kometa", "hangganan ng solar system", "utlanan sa solar system", "edge of solar system", "umiikot sa Araw", "molibot sa Adlaw"], "fact": {"tl": "Ang Oort cloud ay isang malayong-malayong balot ng yelong bagay na bumabalot sa solar system, at dito pinaniniwalaang nagmumula ang mga kometang matagal bago bumalik (long-period comet).", "en": "The Oort cloud is a very distant shell of icy bodies surrounding the solar system, and it is thought to be the source of long-period comets that take a long time to return.", "bis": "Ang Oort cloud usa ka halayo kaayo nga balot sa bugnaw nga mga butang nga naglibot sa solar system, ug gituohan nga gikan dinhi ang mga kometa nga dugay mobalik (long-period comet)."}, "source": "encyclopedia-stable consensus (Oort cloud hypothesis)", "generator": "claude-workflow", "reviewed": false},
  {"id": "asteroid-belt-failed-planet-g9", "domain": "EARTH_SPACE", "topic": "why the asteroid belt never became a planet", "grades": [8, 9, 10], "terms": ["asteroid belt", "sinturon ng asteroid", "bakus sa asteroid", "hindi naging planeta", "wala mahimong planeta", "never formed a planet", "grabidad ng Jupiter", "grabidad sa Jupiter", "Jupiter's gravity", "hinalo", "gisamok", "stirred up", "natira", "nabilin", "leftover", "bato", "asteroid", "Mars at Jupiter", "Mars ug Jupiter"], "fact": {"tl": "Hindi naging isang planeta ang asteroid belt dahil hinalo ng malakas na grabidad ng Jupiter ang mga bato roon at hindi sila pinayagang magdikit-dikit, kaya natira silang libu-libong asteroid.", "en": "The asteroid belt never formed into a planet because Jupiter's strong gravity stirred up the rocks there and kept them from sticking together, leaving thousands of separate asteroids.", "bis": "Ang asteroid belt wala mahimong usa ka planeta tungod kay ang kusog nga grabidad sa Jupiter misamok sa mga bato didto ug wala motugot nga magdikit-dikit, mao nga nabilin ang liboan ka managlahing asteroid."}, "source": "encyclopedia-stable consensus (asteroid belt dynamics)", "generator": "claude-workflow", "reviewed": false},
  {"id": "comet-vs-asteroid-composition-g9", "domain": "EARTH_SPACE", "topic": "comet versus asteroid composition", "grades": [8, 9, 10], "terms": ["kometa", "comet", "asteroid", "yelo at alikabok", "yelo ug abog", "ice and dust", "bato at metal", "bato ug metal", "rock and metal", "buntot", "ikog", "tail", "malapit sa Araw", "duol sa Adlaw", "near the Sun", "natutunaw ang yelo", "matunaw ang yelo", "ice vaporizes", "pagkakaiba", "kalainan", "difference"], "fact": {"tl": "Ang pangunahing pagkakaiba ng kometa at asteroid ay ang laman: ang kometa ay gawa sa yelo at alikabok kaya tumutubo ito ng buntot kapag malapit sa Araw, samantalang ang asteroid ay mas mabato at metal at walang buntot.", "en": "The main difference between a comet and an asteroid is what they are made of: a comet is made of ice and dust so it grows a tail near the Sun, while an asteroid is rockier and metallic with no tail.", "bis": "Ang nag-unang kalainan sa kometa ug asteroid mao ang sulod niini: ang kometa hinimo sa yelo ug abog mao nga moturok kini og ikog kon duol sa Adlaw, samtang ang asteroid mas batoon ug metal ug walay ikog."}, "source": "encyclopedia-stable consensus; NRC ESS1.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "comet-tail-solar-wind-g9", "domain": "EARTH_SPACE", "topic": "why a comet tail points away from the Sun", "grades": [9, 10], "terms": ["kometa", "comet", "buntot", "ikog", "tail", "palayo sa Araw", "palayo sa Adlaw", "points away from Sun", "solar wind", "hanging araw", "hangin sa adlaw", "sinag ng Araw", "kahayag sa Adlaw", "sunlight pressure", "natutunaw ang yelo", "matunaw ang yelo", "vaporizing ice", "gas at alikabok", "gas ug abog", "umiikot palayo", "molibot palayo"], "fact": {"tl": "Ang buntot ng kometa ay laging nakaturo palayo sa Araw, hindi pasunod sa direksyon ng paglipad nito, dahil itinutulak ng solar wind at sinag ng Araw ang gas at alikabok palayo.", "en": "A comet's tail always points away from the Sun, not behind its direction of motion, because the solar wind and sunlight push the gas and dust away from the Sun.", "bis": "Ang ikog sa kometa kanunayng nagtutok palayo sa Adlaw, dili sunod sa direksyon sa paglupad niini, tungod kay ang solar wind ug kahayag sa Adlaw moduso sa gas ug abog palayo sa Adlaw."}, "source": "encyclopedia-stable consensus (solar wind / cometary tails)", "generator": "claude-workflow", "reviewed": false},
  {"id": "meteoroid-meteor-meteorite-g9", "domain": "EARTH_SPACE", "topic": "meteoroid versus meteor versus meteorite", "grades": [8, 9, 10], "terms": ["meteoroid", "meteor", "meteorite", "bulalakaw", "bulalakaw sa langit", "shooting star", "bato sa kalawakan", "bato sa kawanangan", "rock in space", "sumusunog sa himpapawid", "nasunog sa atmospera", "burns in atmosphere", "tumama sa lupa", "natagak sa yuta", "lands on ground", "natitira", "nabilin", "survives", "pagkakaiba", "kalainan"], "fact": {"tl": "Ang meteoroid ay maliit na bato sa kalawakan; kung sumunog ito sa himpapawid at maging guhit ng liwanag, ito ay meteor (bulalakaw); at kung may matira na bumagsak sa lupa, ito ay meteorite.", "en": "A meteoroid is a small rock in space; when it burns in the atmosphere as a streak of light it is a meteor (shooting star); and if a piece survives and lands on the ground it is a meteorite.", "bis": "Ang meteoroid usa ka gamayng bato sa kawanangan; kon kini masunog sa atmospera ug mahimong linya sa kahayag, kini meteor (bulalakaw); ug kon adunay mabilin nga matagak sa yuta, kini meteorite."}, "source": "encyclopedia-stable consensus; NRC ESS1.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "meteor-shower-comet-debris-g9", "domain": "EARTH_SPACE", "topic": "meteor showers from comet debris streams", "grades": [8, 9, 10], "terms": ["meteor shower", "ulan ng bulalakaw", "ulan sa bulalakaw", "alikabok ng kometa", "abog sa kometa", "comet dust trail", "dumadaan ang Earth", "moagi ang Earth", "Earth passes through", "taun-taon", "matag tuig", "every year", "parehong panahon", "samang panahon", "same time each year", "sumusunog", "nasunog", "burn up", "guhit ng liwanag", "linya sa kahayag", "streaks of light"], "fact": {"tl": "Nangyayari ang ulan ng bulalakaw (meteor shower) kapag dumadaan ang Earth sa isang landas ng alikabok na naiwan ng kometa, kaya nauulit ito sa parehong panahon taun-taon habang sumusunog ang mga butil sa himpapawid.", "en": "A meteor shower happens when Earth passes through a trail of dust left behind by a comet, so it repeats at the same time each year as the particles burn up in the atmosphere.", "bis": "Ang ulan sa bulalakaw (meteor shower) mahitabo kon ang Earth moagi sa usa ka agianan sa abog nga gibilin sa kometa, mao nga mausab kini sa samang panahon matag tuig samtang nasunog ang mga tipik sa atmospera."}, "source": "encyclopedia-stable consensus; NRC ESS2.A (meteoroid impacts)", "generator": "claude-workflow", "reviewed": false},
  {"id": "meteor-shower-radiant-g9", "domain": "EARTH_SPACE", "topic": "meteor showers named for their radiant constellation", "grades": [9, 10], "terms": ["meteor shower", "ulan ng bulalakaw", "ulan sa bulalakaw", "Perseid", "Leonid", "Geminid", "pangalan", "ngalan", "named after", "konstelasyon", "constellation", "lugar na pinagmumulan", "dapit nga gigikanan", "radiant point", "parang nagmumula", "morag gikan", "appear to come from", "bituin", "bituon", "star pattern"], "fact": {"tl": "Pinangangalanan ang mga meteor shower ayon sa konstelasyon kung saan parang nagmumula ang mga bulalakaw, halimbawa ang Perseid mula sa Perseus at ang Geminid mula sa Gemini.", "en": "Meteor showers are named after the constellation from which the meteors appear to come, for example the Perseids from Perseus and the Geminids from Gemini.", "bis": "Ang mga meteor shower ginganlan sumala sa konstelasyon nga morag gigikanan sa mga bulalakaw, pananglitan ang Perseid gikan sa Perseus ug ang Geminid gikan sa Gemini."}, "source": "encyclopedia-stable consensus (meteor shower radiants)", "generator": "claude-workflow", "reviewed": false},
  {"id": "exoplanet-definition-g9", "domain": "EARTH_SPACE", "topic": "what is an exoplanet", "grades": [8, 9, 10], "terms": ["exoplanet", "eksoplaneta", "planeta sa labas", "planeta sa gawas", "planet outside solar system", "ibang bituin", "laing bituon", "another star", "umiikot sa ibang Araw", "molibot sa laing bituon", "orbits another star", "natuklasan", "nadiskobre", "discovered", "libu-libo", "liboan", "thousands found", "bituin", "bituon", "star"], "fact": {"tl": "Ang exoplanet ay isang planetang umiikot sa ibang bituin, hindi sa ating Araw, at libu-libo na ang natuklasan ng mga siyentipiko sa labas ng ating solar system.", "en": "An exoplanet is a planet that orbits another star, not our Sun, and scientists have already discovered thousands of them outside our solar system.", "bis": "Ang exoplanet usa ka planeta nga molibot sa laing bituon, dili sa atong Adlaw, ug liboan na ang nadiskobre sa mga syentista gawas sa atong solar system."}, "source": "encyclopedia-stable consensus (NASA exoplanet archive); NRC Ch.7 (planets orbiting distant stars)", "generator": "claude-workflow", "reviewed": false},
  {"id": "exoplanet-transit-method-g9", "domain": "EARTH_SPACE", "topic": "transit method for finding exoplanets", "grades": [9, 10], "terms": ["exoplanet", "eksoplaneta", "transit method", "paraan ng pagtuklas", "paagi sa pagdiskobre", "how planets are found", "humihina ang liwanag", "miluya ang kahayag", "star dims", "dumadaan sa harap", "moagi sa atubangan", "passes in front", "bituin", "bituon", "star", "teleskopyo", "telescope", "Kepler", "TESS", "liwanag ng bituin", "kahayag sa bituon"], "fact": {"tl": "Madalas natutuklasan ang mga exoplanet sa pamamagitan ng transit method: kapag dumaan ang planeta sa harap ng bituin nito, bahagyang humihina ang liwanag ng bituin na nakikita ng mga teleskopyo.", "en": "Exoplanets are often found by the transit method: when a planet passes in front of its star, the star's light dims slightly, which telescopes can detect.", "bis": "Ang mga exoplanet kasagarang madiskobre pinaagi sa transit method: kon ang planeta moagi sa atubangan sa bituon niini, ang kahayag sa bituon gamayng miluya, nga mamatikdan sa mga teleskopyo."}, "source": "encyclopedia-stable consensus (transit photometry, Kepler/TESS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "habitable-zone-goldilocks-g9", "domain": "EARTH_SPACE", "topic": "habitable zone Goldilocks zone for liquid water", "grades": [9, 10], "terms": ["habitable zone", "Goldilocks zone", "tamang distansya", "hustong gilay-on", "right distance", "likidong tubig", "tubig nga likido", "liquid water", "hindi masyadong mainit", "dili sobra init", "not too hot", "hindi masyadong malamig", "dili sobra bugnaw", "not too cold", "buhay", "kinabuhi", "life", "exoplanet", "bituin", "bituon", "star"], "fact": {"tl": "Ang habitable zone o 'Goldilocks zone' ay ang distansya mula sa bituin na hindi masyadong mainit at hindi masyadong malamig, kaya posibleng magkaroon ng likidong tubig na kailangan ng buhay.", "en": "The habitable zone or 'Goldilocks zone' is the distance from a star that is not too hot and not too cold, so liquid water—needed for life—could exist there.", "bis": "Ang habitable zone o 'Goldilocks zone' mao ang gilay-on gikan sa bituon nga dili sobra init ug dili sobra bugnaw, mao nga posible nga adunay tubig nga likido nga gikinahanglan sa kinabuhi."}, "source": "encyclopedia-stable consensus (circumstellar habitable zone)", "generator": "claude-workflow", "reviewed": false},
  {"id": "gas-giant-no-surface-g9", "domain": "EARTH_SPACE", "topic": "gas giants have no solid surface", "grades": [8, 9, 10], "terms": ["gas giant", "higanteng gas", "higante nga gas", "Jupiter", "Saturn", "walang matibay na lupa", "walay gahi nga yuta", "no solid surface", "gas at likido", "gas ug likido", "gas and liquid", "hydrogen", "helium", "siksik na ulap", "baga nga panganod", "thick clouds", "hindi matatayuan", "dili katindogan", "cannot stand on"], "fact": {"tl": "Ang mga gas giant tulad ng Jupiter at Saturn ay walang matibay na ibabaw na matatayuan, dahil sila ay halos puro hydrogen at helium na nagiging mas siksik na gas at likido habang papalalim.", "en": "Gas giants like Jupiter and Saturn have no solid surface to stand on, because they are mostly hydrogen and helium that turn into denser gas and liquid as you go deeper.", "bis": "Ang mga gas giant sama sa Jupiter ug Saturn walay gahi nga ibabaw nga katindogan, tungod kay sila halos puro hydrogen ug helium nga mahimong mas baga nga gas ug likido samtang nagkalawom."}, "source": "encyclopedia-stable consensus (gas giant structure)", "generator": "claude-workflow", "reviewed": false},
  {"id": "neptune-uranus-ice-giants-g9", "domain": "EARTH_SPACE", "topic": "Uranus and Neptune are ice giants", "grades": [9, 10], "terms": ["ice giant", "higanteng yelo", "higante nga yelo", "Uranus", "Neptune", "yelo na tubig at gas", "yelo nga tubig ug gas", "icy materials", "mas maliit kaysa Jupiter", "mas gamay kay sa Jupiter", "smaller than Jupiter", "asul", "asul nga kolor", "blue", "methane", "malamig", "bugnaw", "cold", "malayo sa Araw", "layo sa Adlaw"], "fact": {"tl": "Tinatawag na 'ice giant' ang Uranus at Neptune dahil bukod sa gas, marami silang malamig na sangkap na parang yelo tulad ng tubig, methane, at ammonia, kaya iba sila sa puro-gas na Jupiter at Saturn.", "en": "Uranus and Neptune are called 'ice giants' because besides gas they contain a lot of cold icy materials like water, methane, and ammonia, making them different from the mostly-gas Jupiter and Saturn.", "bis": "Ang Uranus ug Neptune gitawag nga 'ice giant' tungod kay gawas sa gas, daghan silang bugnaw nga sangkap nga morag yelo sama sa tubig, methane, ug ammonia, mao nga lahi sila sa puro-gas nga Jupiter ug Saturn."}, "source": "encyclopedia-stable consensus (ice giant classification)", "generator": "claude-workflow", "reviewed": false},
  {"id": "kepler-elliptical-orbits-g9", "domain": "EARTH_SPACE", "topic": "Kepler's laws and elliptical orbits", "grades": [9, 10], "terms": ["Kepler", "batas ni Kepler", "balaod ni Kepler", "Kepler's laws", "elliptical orbit", "habilog na orbit", "elipse", "ellipse", "hindi perpektong bilog", "dili hingpit nga lingin", "not perfect circle", "umiikot sa Araw", "molibot sa Adlaw", "orbit the Sun", "bumibilis kapag malapit", "mopaspas kon duol", "faster when close", "planeta", "planet", "grabidad", "gravity"], "fact": {"tl": "Ayon sa mga batas ni Kepler, ang mga planeta ay umiikot sa Araw sa hugis-elipse (habilog) na landas, hindi perpektong bilog, at bumibilis sila kapag mas malapit sa Araw.", "en": "According to Kepler's laws, planets orbit the Sun along elliptical (oval) paths, not perfect circles, and they move faster when they are closer to the Sun.", "bis": "Sumala sa mga balaod ni Kepler, ang mga planeta molibot sa Adlaw sa porma-elipse (habilog) nga agianan, dili hingpit nga lingin, ug mopaspas sila kon mas duol sa Adlaw."}, "source": "NRC ESS1.B (Kepler's three empirical laws, elliptical paths)", "generator": "claude-workflow", "reviewed": false},
  {"id": "gravity-shapes-orbits-g9", "domain": "EARTH_SPACE", "topic": "gravity and Newton explain why planets orbit", "grades": [9, 10], "terms": ["grabidad", "gravity", "Newton", "batas ng grabidad", "balaod sa grabidad", "law of gravity", "hinihila ng Araw", "gibira sa Adlaw", "Sun pulls", "umiikot", "molibot", "orbit", "hindi lumilipad palayo", "dili molupad palayo", "does not fly away", "balanse", "balance", "patuloy na gumagalaw", "padayong molihok", "keeps moving"], "fact": {"tl": "Ipinaliwanag ni Newton na ang grabidad ng Araw ang patuloy na humihila sa mga planeta papalapit, ngunit dahil sila ay mabilis na gumagalaw sa gilid, umiikot sila sa Araw sa halip na bumagsak dito.", "en": "Newton explained that the Sun's gravity constantly pulls the planets inward, but because they are moving fast sideways, they orbit the Sun instead of falling into it.", "bis": "Gipasabot ni Newton nga ang grabidad sa Adlaw padayong mobira sa mga planeta paduol, apan tungod kay paspas silang molihok sa kilid, molibot sila sa Adlaw imbis nga matagak niini."}, "source": "NRC ESS1.B (Newton's theory of gravity explains Kepler's laws)", "generator": "claude-workflow", "reviewed": false},
  {"id": "moons-of-giant-planets-g9", "domain": "EARTH_SPACE", "topic": "giant planets have many moons", "grades": [8, 9, 10], "terms": ["buwan", "bulan", "moon", "satellite", "Jupiter", "Saturn", "maraming buwan", "daghang bulan", "many moons", "dose-dosena", "dosena-dosena", "dozens of moons", "Ganymede", "Titan", "pinakamalaking buwan", "kinadak-ang bulan", "largest moon", "grabidad", "gravity", "umiikot sa planeta", "molibot sa planeta"], "fact": {"tl": "Ang malalaking planeta tulad ng Jupiter at Saturn ay may dose-dosenang buwan, at ang ilan tulad ng Ganymede (buwan ng Jupiter) at Titan (buwan ng Saturn) ay mas malaki pa sa planetang Mercury.", "en": "Giant planets like Jupiter and Saturn have dozens of moons, and some such as Ganymede (a moon of Jupiter) and Titan (a moon of Saturn) are even larger than the planet Mercury.", "bis": "Ang dagkong planeta sama sa Jupiter ug Saturn adunay dosena-dosenang bulan, ug ang uban sama sa Ganymede (bulan sa Jupiter) ug Titan (bulan sa Saturn) mas dako pa kay sa planeta nga Mercury."}, "source": "encyclopedia-stable consensus (planetary satellites)", "generator": "claude-workflow", "reviewed": false},
  {"id": "leftover-debris-records-formation-g9", "domain": "EARTH_SPACE", "topic": "asteroids and comets as fossils of solar system formation", "grades": [9, 10], "terms": ["asteroid", "kometa", "comet", "labi", "nabilin", "leftover", "halos hindi nagbago", "halos wala mausab", "barely changed", "bilyong taon", "billion years", "rekord ng nakaraan", "rekord sa nangagi", "record of the past", "pagkabuo ng solar system", "pagkaporma sa solar system", "early solar system", "pinag-aaralan ng siyentipiko", "gitun-an sa syentista", "scientists study"], "fact": {"tl": "Pinag-aaralan ng mga siyentipiko ang mga asteroid at kometa dahil halos hindi sila nagbago sa loob ng bilyong taon, kaya parang mga 'fossil' silang nagtatago ng kasaysayan ng kung paano nabuo ang solar system.", "en": "Scientists study asteroids and comets because they have barely changed in billions of years, so they act like 'fossils' that preserve the history of how the solar system formed.", "bis": "Gitun-an sa mga syentista ang mga asteroid ug kometa tungod kay halos wala sila mausab sulod sa bilyong tuig, mao nga morag mga 'fossil' sila nga nagtipig sa kasaysayan kon giunsa pagkaporma ang solar system."}, "source": "NRC ESS1.C (asteroids and meteorites have changed little over billions of years)", "generator": "claude-workflow", "reviewed": false},
  {"id": "comet-coma-nucleus-g9", "domain": "EARTH_SPACE", "topic": "comet nucleus and coma", "grades": [9, 10], "terms": ["kometa", "comet", "nucleus", "ubod", "core", "ulo ng kometa", "ulo sa kometa", "coma", "ulap ng gas", "panganod sa gas", "gas cloud", "yelo at alikabok", "yelo ug abog", "ice and dust", "malapit sa Araw", "duol sa Adlaw", "near the Sun", "natutunaw", "matunaw", "vaporizes", "buntot", "ikog", "tail"], "fact": {"tl": "Ang gitnang matigas na bahagi ng kometa ay tinatawag na nucleus, at kapag malapit ito sa Araw, natutunaw ang yelo at bumubuo ng maluwag na ulap ng gas at alikabok sa paligid nito na tinatawag na coma.", "en": "The solid central part of a comet is called the nucleus, and when it nears the Sun, its ice vaporizes and forms a fuzzy cloud of gas and dust around it called the coma.", "bis": "Ang gahi nga tunga nga bahin sa kometa gitawag og nucleus, ug kon kini moduol sa Adlaw, ang yelo niini matunaw ug maghimo og luag nga panganod sa gas ug abog libot niini nga gitawag og coma."}, "source": "encyclopedia-stable consensus (cometary structure)", "generator": "claude-workflow", "reviewed": false},
  {"id": "halley-comet-period-g9", "domain": "EARTH_SPACE", "topic": "Halley's Comet returns about every 76 years", "grades": [8, 9, 10], "terms": ["Halley's Comet", "kometa ni Halley", "kometa sa Halley", "Halley", "bumabalik", "mobalik", "returns", "76 taon", "76 ka tuig", "every 76 years", "nakikita mula sa Earth", "makita gikan sa Earth", "seen from Earth", "short-period comet", "umiikot sa Araw", "molibot sa Adlaw", "orbit", "huling nakita", "kataposang nakita", "last seen 1986"], "fact": {"tl": "Ang Kometa ni Halley ay bumabalik na nakikita mula sa Earth tuwing humigit-kumulang 76 na taon, at huli itong nakita noong 1986 at inaasahang muling makikita mga 2061.", "en": "Halley's Comet returns to view from Earth about every 76 years, and it was last seen in 1986 and is expected again around 2061.", "bis": "Ang Kometa ni Halley mobalik nga makita gikan sa Earth matag mga 76 ka tuig, ug kataposan kining nakita niadtong 1986 ug gilauman nga mobalik mga 2061."}, "source": "encyclopedia-stable consensus (Halley's Comet)", "generator": "claude-workflow", "reviewed": false},
  {"id": "big-bang-age-universe-g9", "domain": "EARTH_SPACE", "topic": "the age of the universe", "grades": [9, 10], "terms": ["edad ng uniberso", "gulang sa uniberso", "age of universe", "13.8 billion years", "labintatlong bilyong taon", "Big Bang", "billion years old", "katandaan", "kalibutan tibuok"], "fact": {"tl": "Batay sa siyentipikong ebidensiya, tinatayang mahigit sampung bilyong taon na ang edad ng uniberso, mga 13.8 bilyong taon mula nang magsimula ito sa Big Bang.", "en": "Based on scientific evidence, the universe is estimated to be over ten billion years old, about 13.8 billion years since it began in the Big Bang.", "bis": "Base sa siyentipikong ebidensya, gibanabana nga kapin sa napulo ka bilyon ka tuig na ang edad sa uniberso, mga 13.8 ka bilyon ka tuig sukad kini nagsugod sa Big Bang."}, "source": "AAAS Benchmarks 4A/H2ab; scientific consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "big-bang-space-itself-expands-g9", "domain": "EARTH_SPACE", "topic": "the Big Bang expanded space itself", "grades": [9, 10], "terms": ["lumalawak na uniberso", "expanding space", "naglapad nga kawanangan", "space itself stretching", "hindi pagsabog sa isang lugar", "wala mibuto sa usa ka dapit", "expanding universe", "umuunat ang espasyo", "Big Bang"], "fact": {"tl": "Ang Big Bang ay hindi isang pagsabog sa loob ng espasyo kundi ang biglang paglawak ng mismong espasyo, kaya lumalayo ang mga galaksiya dahil umuunat ang puwang sa pagitan nila.", "en": "The Big Bang was not an explosion within space but the sudden expansion of space itself, so galaxies move apart because the space between them is stretching.", "bis": "Ang Big Bang dili usa ka pagbuto sulod sa kawanangan kondili ang kalit nga paglapad sa kawanangan mismo, mao nga nagkalayo ang mga galaksiya tungod kay nagkalapad ang luna tali kanila."}, "source": "AAAS Benchmarks 4A/H2; 4F/H5c", "generator": "claude-workflow", "reviewed": false},
  {"id": "redshift-galaxies-evidence-g10", "domain": "EARTH_SPACE", "topic": "redshift as evidence of expansion", "grades": [9, 10], "terms": ["redshift", "pulang shift", "pula nga pagbalhin", "mas mahabang wavelength", "longer wavelength", "lumalayong galaksiya", "naglayo nga galaksiya", "ilaw na pumupula", "stretching of light", "ebidensiya ng paglawak"], "fact": {"tl": "Ang liwanag mula sa halos lahat ng malalayong galaksiya ay may mas mahabang wavelength (mas pumupula), at dahil dito naniniwala ang mga astronomo na lumalawak ang buong uniberso.", "en": "Because the light from almost all distant galaxies has longer wavelengths (it is redshifted), astronomers believe that the whole universe is expanding.", "bis": "Tungod kay ang kahayag gikan sa halos tanang layo nga galaksiya adunay mas taas nga wavelength (mas mapula), nagtuo ang mga astronomo nga ang tibuok uniberso nagkalapad."}, "source": "AAAS Benchmarks 4F/H5c", "generator": "claude-workflow", "reviewed": false},
  {"id": "farther-galaxies-faster-g10", "domain": "EARTH_SPACE", "topic": "farther galaxies recede faster", "grades": [9, 10], "terms": ["mas malayong galaksiya", "mas paspas nga naglayo", "farther faster", "lumalayo nang mas mabilis", "expansion of the universe", "paglawak ng uniberso", "rate of recession", "Hubble", "mas tulin molayo"], "fact": {"tl": "Sa pangkalahatan, mas mabilis na lumalayo sa atin ang mga galaksiyang mas malayo, na tumutugma sa ideya ng isang uniberso na pantay-pantay na lumalawak sa lahat ng direksiyon.", "en": "In general, galaxies that are farther away move away from us faster, which fits the idea of a universe expanding evenly in all directions.", "bis": "Sa kasagaran, ang mga galaksiya nga mas layo molayo kanato nga mas paspas, nga mohaum sa ideya sa usa ka uniberso nga managsama nga nagkalapad sa tanang direksyon."}, "source": "AAAS Benchmarks 4F/H5c; Hubble's law (scientific consensus)", "generator": "claude-workflow", "reviewed": false},
  {"id": "stars-form-by-gravity-fusion-g9", "domain": "EARTH_SPACE", "topic": "how stars ignite by fusion", "grades": [9, 10], "terms": ["nuclear fusion", "pagsasanib ng nukleyo", "panagsumpay nukleyar", "hydrogen into helium", "haydroheno tungong helium", "gravity squeezes gas", "init ug presyur", "init at presyon", "stars condense", "nagdikit-dikit nga gas"], "fact": {"tl": "Ang mga bituin ay nabubuo kapag hinihila ng grabidad ang mga ulap ng magagaang elemento hanggang ang sobrang init at presyon ay magsimula ng nuclear fusion na nagsasanib ng haydroheno tungong helium.", "en": "Stars form when gravity pulls together clouds of the lightest elements until the intense heat and pressure start nuclear fusion, joining hydrogen into helium.", "bis": "Ang mga bituon maporma kung birahon sa grabidad ang mga panganod sa pinakagaan nga elemento hangtod nga ang grabe nga kainit ug presyur magsugod sa nuclear fusion, nga magsumpay sa hydrogen ngadto sa helium."}, "source": "AAAS Benchmarks 4A/H2cd", "generator": "claude-workflow", "reviewed": false},
  {"id": "fusion-releases-energy-stars-g9", "domain": "EARTH_SPACE", "topic": "fusion powers stars for millions of years", "grades": [9, 10], "terms": ["fusion energy", "enerhiya ng pagsasanib", "kusog gikan sa fusion", "millions of years", "milyong taon", "milyon ka tuig", "bakit nagliliwanag ang bituin", "ngano nagdan-ag ang bituon", "nuclear fusion", "init ug kahayag"], "fact": {"tl": "Ang nuclear fusion sa loob ng isang bituin ay naglalabas ng napakalaking enerhiya sa loob ng milyon-milyong taon, at ito ang dahilan kung bakit nagliliwanag at umiinit ang mga bituin tulad ng Araw.", "en": "Nuclear fusion inside a star releases great amounts of energy over millions of years, and this is why stars like the Sun shine and give off heat.", "bis": "Ang nuclear fusion sulod sa usa ka bituon nagpagawas og dako kaayong enerhiya sulod sa minilyon ka tuig, ug mao kini ang hinungdan nganong nagdan-ag ug nagpainit ang mga bituon sama sa Adlaw."}, "source": "AAAS Benchmarks 4A/H2cd", "generator": "claude-workflow", "reviewed": false},
  {"id": "star-fate-depends-on-mass-g10", "domain": "EARTH_SPACE", "topic": "a star's fate depends on its mass", "grades": [9, 10], "terms": ["bigat ng bituin", "gibug-aton sa bituon", "mass of a star", "wakas ng bituin", "kataposan sa bituon", "malalaking bituin", "dagkong bituon", "white dwarf", "neutron star", "black hole", "kung gaano kalaki"], "fact": {"tl": "Ang kahihinatnan ng isang bituin ay nakadepende sa bigat nito: ang maliliit na bituin ay nagiging malamig na white dwarf, samantalang ang napakalalaking bituin ay sumasabog at nagiging neutron star o black hole.", "en": "What happens to a star at the end depends on its mass: small stars become cooling white dwarfs, while very massive stars explode and leave behind a neutron star or a black hole.", "bis": "Ang madangatan sa usa ka bituon nagdepende sa gibug-aton niini: ang gagmay nga mga bituon mahimong nagbugnaw nga white dwarf, samtang ang dagko kaayong bituon mobuto ug mabilin nga neutron star o black hole."}, "source": "AAAS Benchmarks 4A/H2ef; stellar evolution (scientific consensus)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-will-become-white-dwarf-g10", "domain": "EARTH_SPACE", "topic": "the Sun's future as a white dwarf", "grades": [9, 10], "terms": ["white dwarf", "puting unano", "puting dwarf", "kapalaran ng Araw", "kaugmaon sa Adlaw", "future of the Sun", "red giant", "pulang higante", "pula nga higante", "lalaki ang Araw", "mamatay ang Araw"], "fact": {"tl": "Pagkaubos ng gatong nito makalipas ang bilyong taon, lalaki muna ang Araw bilang isang red giant bago ito mag-iwan ng isang maliit at mainit na natitirang ulo na tinatawag na white dwarf.", "en": "When it runs out of fuel billions of years from now, the Sun will first swell into a red giant, then leave behind a small, hot core called a white dwarf.", "bis": "Kon mahurot ang sugnod niini human sa binilyon ka tuig, ang Adlaw modako una isip usa ka red giant unya mobilin og gamay ug init nga kinauyokan nga gitawag og white dwarf."}, "source": "AAAS Benchmarks 4A/H2; stellar evolution (scientific consensus)", "generator": "claude-workflow", "reviewed": false},
  {"id": "neutron-star-very-dense-g10", "domain": "EARTH_SPACE", "topic": "what a neutron star is", "grades": [9, 10], "terms": ["neutron star", "bituing neutron", "neutron nga bituon", "napakasikip", "grabe ka dasok", "extremely dense", "natira sa supernova", "nabilin sa supernova", "remnant", "maliit pero mabigat", "gamay pero bug-at"], "fact": {"tl": "Ang neutron star ay ang napakasikip na natitirang ulo ng isang sumabog na malaking bituin, kung saan isang kutsaritang sangkap nito ay maaaring tumimbang nang ilang bilyong tonelada.", "en": "A neutron star is the extremely dense leftover core of a large exploded star, where a single spoonful of its material can weigh several billion tons.", "bis": "Ang neutron star mao ang grabe kadasok nga nabiling kinauyokan sa usa ka dakong bituon nga mibuto, diin ang usa ka kutsarita sa material niini mahimong motimbang og pila ka bilyon ka tonelada."}, "source": "Stellar evolution; scientific/encyclopedia consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pulsar-spinning-neutron-star-g10", "domain": "EARTH_SPACE", "topic": "pulsars as spinning neutron stars", "grades": [9, 10], "terms": ["pulsar", "umiikot na neutron star", "nagtuyok nga neutron star", "spinning neutron star", "beam of radio waves", "sinag ng radyo", "silaw sa radyo", "parang parola", "morag parola", "lighthouse", "pulsong sinyal"], "fact": {"tl": "Ang isang pulsar ay isang mabilis na umiikot na neutron star na naglalabas ng sinag ng radyo mula sa mga poste nito, kaya parang parolang kumukurap kapag nakaharap ito sa atin.", "en": "A pulsar is a fast-spinning neutron star that sends out beams of radio waves from its poles, so it appears to blink like a lighthouse each time a beam sweeps past Earth.", "bis": "Ang pulsar usa ka paspas nga nagtuyok nga neutron star nga nagpagawas og silaw sa radyo gikan sa mga poste niini, mao nga morag parola nga nagpangidlap matag higayon nga ang silaw moagi sa Yuta."}, "source": "Scientific/encyclopedia consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "stellar-nucleosynthesis-elements-g10", "domain": "EARTH_SPACE", "topic": "elements forged inside stars", "grades": [9, 10], "terms": ["mas mabibigat na elemento", "mas bug-at nga elemento", "heavier elements", "nuclear fusion sa bituin", "carbon oxygen", "karbon oksiheno", "ginawa sa loob ng bituin", "gibuhat sulod sa bituon", "fusion of light elements", "atomo ng metal"], "fact": {"tl": "Sa loob ng mga bituin, pinagsasanib ng fusion ang magagaang elemento upang makagawa ng mas mabibigat na elemento tulad ng karbon at oksiheno, na hindi umiiral noong unang nabuo ang uniberso.", "en": "Inside stars, fusion joins light elements to make heavier ones like carbon and oxygen, which did not exist when the universe first formed.", "bis": "Sulod sa mga bituon, ang fusion magsumpay sa gaan nga mga elemento aron makahimo og mas bug-at nga mga elemento sama sa carbon ug oxygen, nga wala pa sa unang pagkahimo sa uniberso."}, "source": "AAAS Benchmarks 4A/H2cd; stellar nucleosynthesis (consensus)", "generator": "claude-workflow", "reviewed": false},
  {"id": "supernova-spreads-heavy-elements-g10", "domain": "EARTH_SPACE", "topic": "supernovae seed space with heavy elements", "grades": [9, 10], "terms": ["supernova", "pagsabog ng bituin", "pagbuto sa bituon", "mabibigat na elemento", "bug-at nga elemento", "bakal na iron", "puthaw nga iron", "ikinakalat sa kalawakan", "gikatag sa kawanangan", "bagong bituin at planeta", "bag-ong bituon ug planeta"], "fact": {"tl": "Kapag sumabog ang ilang malalaking bituin bilang supernova, ikinakalat nila sa kalawakan ang mga mabibigat na elementong ginawa nila, at mula sa mga ulap na ito ay maaaring mabuo ang bagong mga bituin at planeta.", "en": "When some large stars explode as supernovae, they scatter the heavy elements they made into space, and from these clouds new stars and planets can later form.", "bis": "Kon mobuto ang pipila ka dagkong bituon isip supernova, ikatag nila sa kawanangan ang mga bug-at nga elemento nga ilang gibuhat, ug gikan niini nga mga panganod mahimong maporma ang bag-ong mga bituon ug planeta."}, "source": "AAAS Benchmarks 4A/H2ef", "generator": "claude-workflow", "reviewed": false},
  {"id": "main-sequence-sun-stable-g10", "domain": "EARTH_SPACE", "topic": "stable middle life of a star", "grades": [9, 10], "terms": ["matatag na bituin", "lig-on nga bituon", "stable star", "balanse ng grabidad at presyon", "balanse sa grabidad ug presyur", "balance of gravity and pressure", "main sequence", "haba ng buhay ng bituin", "gitas-on sa kinabuhi sa bituon", "bilyong taon na matatag"], "fact": {"tl": "Sa karamihan ng buhay nito, matatag ang isang bituin dahil ang lakas ng grabidad na humihila papasok ay balanse sa presyon ng init ng fusion na nagtutulak palabas.", "en": "For most of its life, a star is stable because the inward pull of gravity is balanced by the outward push of the heat from fusion.", "bis": "Sa kadaghanan sa kinabuhi niini, lig-on ang usa ka bituon tungod kay ang pagbira sa grabidad paingon sa sulod gibalanse sa pagduso pagawas sa init gikan sa fusion."}, "source": "Stellar evolution; scientific consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "color-shows-star-temperature-g9", "domain": "EARTH_SPACE", "topic": "star color shows its temperature", "grades": [8, 9, 10], "terms": ["kulay ng bituin", "kolor sa bituon", "color of a star", "asul ay mas mainit", "asul mas init", "blue is hotter", "pula ay mas malamig", "pula mas bugnaw", "red is cooler", "temperatura ng bituin", "temperatura sa bituon"], "fact": {"tl": "Ipinapakita ng kulay ng isang bituin kung gaano ito kainit: ang mga asul-puting bituin ang pinakamainit, samantalang ang mga mapupula ay mas malamig.", "en": "A star's color shows how hot it is: blue-white stars are the hottest, while reddish stars are cooler.", "bis": "Ang kolor sa usa ka bituon nagpakita kung unsa kini kainit: ang asul-puti nga mga bituon ang pinakainit, samtang ang mapula nga mga bituon mas bugnaw."}, "source": "Scientific/encyclopedia consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "milky-way-size-light-years-g9", "domain": "EARTH_SPACE", "topic": "the size of the Milky Way in light-years", "grades": [9, 10], "terms": ["laki ng Milky Way", "kadako sa Milky Way", "size of Milky Way", "isang daang libong light-year", "usa ka gatos ka libo ka light-year", "100,000 light-years", "disk-shaped galaxy", "hugis disk", "porma og plato", "lapad sa galaksiya", "lawak ng galaksiya"], "fact": {"tl": "Napakalaki ng ating galaksiyang Milky Way na umaabot ito ng mga isang daang libong light-year ang lapad, kaya kahit ang liwanag ay nangangailangan ng libu-libong taon para tumawid dito.", "en": "Our Milky Way galaxy is so large that it is about one hundred thousand light-years across, so even light takes thousands of years to cross it.", "bis": "Ang atong galaksiya nga Milky Way grabe kadako mao nga mga usa ka gatos ka libo ka light-year ang gilapdon niini, busa bisan ang kahayag manginahanglan og liboan ka tuig aron motabok niini."}, "source": "AAAS Benchmarks 4A/M1; scientific consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-orbits-galaxy-center-g9", "domain": "EARTH_SPACE", "topic": "the Sun orbits the galaxy's center", "grades": [9, 10], "terms": ["umiikot ang Araw", "nagtuyok ang Adlaw", "Sun orbits galaxy", "gitna ng Milky Way", "sentro sa Milky Way", "galactic center", "milyong taon para umikot", "galactic year", "kasama ang buong solar system", "uban ang tibuok solar system"], "fact": {"tl": "Hindi nakatigil ang Araw kundi umiikot ito kasama ang buong solar system sa paligid ng sentro ng Milky Way, at isang pag-ikot ay tumatagal ng daan-daang milyong taon.", "en": "The Sun is not still but orbits, together with the whole solar system, around the center of the Milky Way, and one orbit takes hundreds of millions of years.", "bis": "Ang Adlaw dili hunong kondili nagtuyok kini, uban sa tibuok solar system, libot sa sentro sa Milky Way, ug usa ka libot mokabat og gatosan ka milyon ka tuig."}, "source": "AAAS Benchmarks 4A/M1; scientific consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "local-group-galaxies-g9", "domain": "EARTH_SPACE", "topic": "the Local Group of galaxies", "grades": [9, 10], "terms": ["Local Group", "pangkat ng galaksiya", "grupo sa galaksiya", "cluster of galaxies", "kumpol ng galaksiya", "pundok sa galaksiya", "Milky Way at Andromeda", "magkalapit na galaksiya", "magkasilingang galaksiya", "nakatali ng grabidad", "gihiusa sa grabidad"], "fact": {"tl": "Ang Milky Way ay kabilang sa isang maliit na pangkat ng dose-dosenang galaksiya na tinatawag na Local Group, na pinagbubuklod ng grabidad kasama ng mas malaking galaksiyang Andromeda.", "en": "The Milky Way belongs to a small cluster of dozens of galaxies called the Local Group, bound together by gravity along with the larger Andromeda galaxy.", "bis": "Ang Milky Way sakop sa usa ka gamay nga pundok sa dosena ka galaksiya nga gitawag og Local Group, nga gihiusa sa grabidad uban sa mas dakong galaksiya nga Andromeda."}, "source": "Scientific/encyclopedia consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "galaxies-form-clusters-g10", "domain": "EARTH_SPACE", "topic": "galaxies gather into clusters", "grades": [9, 10], "terms": ["kumpol ng galaksiya", "pundok sa galaksiya", "galaxy clusters", "grupo-grupo ang galaksiya", "naggrupo nga galaksiya", "hinihila ng grabidad", "gibira sa grabidad", "pinakamalaking istruktura", "pinakadako nga estruktura", "largest structures", "web ng uniberso"], "fact": {"tl": "Hindi pantay na nakakalat ang mga galaksiya kundi naggugrupo sila sa malalaking kumpol dahil sa grabidad, at ang mga kumpol na ito ay kabilang sa pinakamalalaking istruktura sa uniberso.", "en": "Galaxies are not spread out evenly but gather into large clusters because of gravity, and these clusters are among the largest structures in the universe.", "bis": "Ang mga galaksiya wala managsama nga gikatag kondili nagpundok sila sa dagkong pundok tungod sa grabidad, ug kini nga mga pundok sakop sa pinakadagkong estruktura sa uniberso."}, "source": "Scientific/encyclopedia consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "andromeda-will-collide-g10", "domain": "EARTH_SPACE", "topic": "Andromeda approaching the Milky Way", "grades": [9, 10], "terms": ["banggaan ng galaksiya", "banggaanay sa galaksiya", "galaxy collision", "Andromeda papalapit", "Andromeda nagkaduol", "approaching Milky Way", "magsasanib na galaksiya", "maghiusang galaksiya", "bilyong taon mula ngayon", "binilyon ka tuig", "merge"], "fact": {"tl": "Bukod-tangi sa karamihan ng galaksiya, ang Andromeda ay papalapit sa Milky Way, at sa loob ng bilyong taon ay inaasahang magkakabanggaan at unti-unting magsasanib ang dalawang galaksiya.", "en": "Unlike most galaxies, Andromeda is moving toward the Milky Way, and in billions of years the two galaxies are expected to collide and slowly merge.", "bis": "Lahi sa kadaghanan sa galaksiya, ang Andromeda nagkaduol sa Milky Way, ug sulod sa binilyon ka tuig gilauman nga ang duha ka galaksiya magbangga ug hinay-hinay nga maghiusa."}, "source": "Scientific/encyclopedia consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dark-matter-invisible-mass-g10", "domain": "EARTH_SPACE", "topic": "what dark matter is", "grades": [9, 10], "terms": ["dark matter", "madilim na bagay", "ngitngit nga butang", "di-nakikitang masa", "dili makita nga masa", "invisible matter", "walang inilalabas na liwanag", "walay kahayag", "extra gravity", "dagdag na grabidad", "dugang grabidad"], "fact": {"tl": "Tinatawag ng mga siyentipiko na dark matter ang isang di-nakikitang uri ng bagay na hindi naglalabas ni sumisipsip ng liwanag, kaya hindi natin ito makita ng mga teleskopyo.", "en": "Scientists call dark matter an invisible kind of matter that gives off no light and absorbs none, so we cannot see it with telescopes.", "bis": "Gitawag sa mga siyentista nga dark matter ang usa ka dili makita nga matang sa butang nga walay gipagawas nga kahayag ug walay gisuyop, mao nga dili nato kini makita pinaagi sa mga teleskopyo."}, "source": "Scientific consensus (dark matter)", "generator": "claude-workflow", "reviewed": false},
  {"id": "dark-matter-gravity-evidence-g10", "domain": "EARTH_SPACE", "topic": "evidence for dark matter from gravity", "grades": [9, 10], "terms": ["ebidensiya ng dark matter", "ebidensya sa dark matter", "evidence for dark matter", "mabilis umiikot na galaksiya", "paspas motuyok nga galaksiya", "galaxies spin too fast", "extra gravity", "dagdag na grabidad", "dugang grabidad", "di-nakikitang masa", "dili makita nga masa"], "fact": {"tl": "Pinaghihinalaan ng mga siyentipiko ang dark matter dahil ang mga galaksiya ay umiikot nang napakabilis para sa nakikitang masa lamang nila, na para bang may dagdag na di-nakikitang bagay na humihila sa kanila.", "en": "Scientists suspect dark matter because galaxies spin too fast for just the matter we can see, as if extra unseen material is pulling on them.", "bis": "Gisuspetsahan sa mga siyentista ang dark matter tungod kay ang mga galaksiya nagtuyok ug paspas kaayo alang lang sa butang nga atong makita, nga morag adunay dugang dili makita nga butang nga nagbira kanila."}, "source": "Scientific consensus (galaxy rotation curves)", "generator": "claude-workflow", "reviewed": false},
  {"id": "dark-matter-most-of-matter-g10", "domain": "EARTH_SPACE", "topic": "dark matter outweighs ordinary matter", "grades": [9, 10], "terms": ["mas marami ang dark matter", "mas daghan ang dark matter", "dark matter outweighs", "karamihan ng masa", "kadaghanan sa masa", "ordinaryong bagay", "ordinaryo nga butang", "ordinary matter", "bituin at planeta", "bituon ug planeta", "maliit na bahagi"], "fact": {"tl": "Tinatantiya ng mga siyentipiko na mas marami ang dark matter kaysa sa ordinaryong bagay na bumubuo ng mga bituin, planeta, at tao, kahit hindi pa natin alam kung ano talaga ito.", "en": "Scientists estimate that there is much more dark matter than the ordinary matter that makes up stars, planets, and people, even though we do not yet know what it really is.", "bis": "Gibanabana sa mga siyentista nga mas daghan ang dark matter kaysa sa ordinaryong butang nga naglangkob sa mga bituon, planeta, ug tawo, bisan wala pa nato mahibaloi kung unsa gyud kini."}, "source": "Scientific consensus (dark matter)", "generator": "claude-workflow", "reviewed": false},
  {"id": "dark-energy-accelerating-g10", "domain": "EARTH_SPACE", "topic": "dark energy and accelerating expansion", "grades": [9, 10], "terms": ["dark energy", "madilim na enerhiya", "ngitngit nga enerhiya", "bumibilis na paglawak", "nagkapaspas nga paglapad", "accelerating expansion", "itinutulak palayo", "giduso palayo", "pushing galaxies apart", "misteryosong puwersa", "misteryoso nga puwersa"], "fact": {"tl": "Natuklasan ng mga siyentipiko na bumibilis ang paglawak ng uniberso, at tinawag nilang dark energy ang misteryosong dahilan na tila itinutulak ang espasyo na lumawak nang mas mabilis.", "en": "Scientists have found that the expansion of the universe is speeding up, and they call the mysterious cause dark energy, which seems to push space to expand faster.", "bis": "Nadiskobrehan sa mga siyentista nga ang paglapad sa uniberso nagkapaspas, ug gitawag nila nga dark energy ang misteryoso nga hinungdan nga morag nagduso sa kawanangan nga molapad ug mas paspas."}, "source": "Scientific consensus (accelerating expansion / dark energy)", "generator": "claude-workflow", "reviewed": false},
  {"id": "observable-universe-limit-g10", "domain": "EARTH_SPACE", "topic": "the observable universe", "grades": [9, 10], "terms": ["observable universe", "nakikitang uniberso", "makita nga uniberso", "hangganan ng nakikita", "utlanan sa makita", "limit of what we see", "liwanag pa lang dumarating", "kahayag pa lang moabot", "billions of light-years", "binilyon ka light-year", "mas malayo pa"], "fact": {"tl": "May hangganan ang bahagi ng uniberso na nakikita natin dahil ang liwanag mula sa mga pinakamalalayong bagay ay nakakarating lamang sa atin pagkatapos ng bilyong taon ng paglalakbay; tinatawag itong observable universe.", "en": "There is a limit to the part of the universe we can see, because light from the most distant objects has only had billions of years to reach us; this is called the observable universe.", "bis": "Adunay utlanan ang bahin sa uniberso nga atong makita, tungod kay ang kahayag gikan sa pinakalayong mga butang nakaabot lang kanato human sa binilyon ka tuig nga pagbiyahe; gitawag kini nga observable universe."}, "source": "Scientific consensus; AAAS Benchmarks 4A/M2de", "generator": "claude-workflow", "reviewed": false},
  {"id": "looking-out-is-looking-back-g9", "domain": "EARTH_SPACE", "topic": "telescopes look back in time", "grades": [9, 10], "terms": ["pagtingin sa nakaraan", "pagtan-aw sa nangagi", "looking back in time", "lumang liwanag", "daan nga kahayag", "old light", "telescope time machine", "noon pa nagliwanag", "kaniadto pa midan-ag", "billions of years ago", "binilyon ka tuig na ang nakalabay"], "fact": {"tl": "Dahil matagal bago dumating sa atin ang liwanag, ang malalakas na teleskopyo ay parang time machine: kapag tinitingnan nila ang malalayong galaksiya, nakikita nila ang mga ito kung paano sila noong bilyong taon na ang nakalilipas.", "en": "Because light takes so long to reach us, powerful telescopes act like time machines: when they view very distant galaxies, they see them as they were billions of years ago.", "bis": "Tungod kay dugay pa moabot kanato ang kahayag, ang gamhanang mga teleskopyo morag time machine: kon tan-awon nila ang layo kaayong galaksiya, makita nila kini sama sa ilang kahimtang binilyon ka tuig na ang nakalabay."}, "source": "AAAS Benchmarks 4A/M2de; 4A/H3", "generator": "claude-workflow", "reviewed": false},
  {"id": "many-telescope-wavelengths-g9", "domain": "EARTH_SPACE", "topic": "telescopes across the spectrum", "grades": [9, 10], "terms": ["radyo teleskopyo", "radio nga teleskopyo", "radio telescope", "X-ray telescope", "iba't ibang teleskopyo", "lainlaing teleskopyo", "electromagnetic waves", "alon ng liwanag", "balod sa kahayag", "di-nakikitang liwanag", "dili makita nga kahayag", "infrared"], "fact": {"tl": "Gumagamit ang mga astronomo ng iba't ibang teleskopyo—pang-liwanag, pang-radyo, at pang-X-ray—upang mangalap ng impormasyon mula sa buong saklaw ng electromagnetic waves, kasama ang liwanag na di-nakikita ng ating mga mata.", "en": "Astronomers use different telescopes—visible, radio, and X-ray—to collect information from across the whole range of electromagnetic waves, including light our eyes cannot see.", "bis": "Naggamit ang mga astronomo og lainlaing teleskopyo—pangkahayag, pangradyo, ug pang-X-ray—aron mangolekta og impormasyon gikan sa tibuok gilapdon sa electromagnetic waves, lakip ang kahayag nga dili makita sa atong mata."}, "source": "AAAS Benchmarks 4A/H3", "generator": "claude-workflow", "reviewed": false},
  {"id": "elements-identified-by-light-g10", "domain": "EARTH_SPACE", "topic": "identifying elements in stars by their light", "grades": [9, 10], "terms": ["spectrum ng bituin", "spectrum sa bituon", "starlight spectrum", "elemento sa bituin", "elemento sa bituon", "kulay ng liwanag", "kolor sa kahayag", "fingerprint ng atomo", "tigom-tigom nga kolor", "anong gawa ang bituin", "unsay sangkap sa bituon"], "fact": {"tl": "Ang bawat elemento ay naglalabas o sumisipsip ng natatanging mga kulay ng liwanag, kaya kayang malaman ng mga siyentipiko kung anong mga elemento ang nasa isang bituin kahit ito ay nasa kabilang dulo ng uniberso.", "en": "Each element gives off or absorbs its own distinctive colors of light, so scientists can tell what elements are in a star even if it is on the far side of the universe.", "bis": "Matag elemento nagpagawas o nagsuyop sa kaugalingong talagsaong mga kolor sa kahayag, mao nga masuta sa mga siyentista kung unsang mga elemento ang anaa sa usa ka bituon bisan kung kini naa sa pikas tumoy sa uniberso."}, "source": "AAAS Benchmarks 4E (atom/light); spectroscopy (consensus)", "generator": "claude-workflow", "reviewed": false},
  {"id": "speed-of-light-cosmic-ruler-g9", "domain": "EARTH_SPACE", "topic": "speed of light as a cosmic measuring stick", "grades": [9, 10], "terms": ["bilis ng liwanag", "katulin sa kahayag", "speed of light", "panukat ng layo", "sukdanan sa gilay-on", "measuring distance", "light-year", "ilaw sa loob ng taon", "kahayag sa usa ka tuig", "300000 kilometers per second", "pinakamabilis sa uniberso"], "fact": {"tl": "Ginagamit ng mga siyentipiko ang bilis ng liwanag—mga 300,000 kilometro bawat segundo—bilang panukat sa kalawakan, kaya kayang ipahayag ang layo sa pagitan ng mga bituin sa light-year.", "en": "Scientists use the speed of light—about 300,000 kilometers per second—as a cosmic measuring stick, so distances between stars can be expressed in light-years.", "bis": "Gigamit sa mga siyentista ang katulin sa kahayag—mga 300,000 ka kilometro matag segundo—isip sukdanan sa kawanangan, mao nga ang gilay-on tali sa mga bituon mahimong ipahayag sa light-year."}, "source": "AAAS Benchmarks 4A/H; 4A/M2", "generator": "claude-workflow", "reviewed": false},
  {"id": "cosmic-distances-vast-scale-g9", "domain": "EARTH_SPACE", "topic": "the vast scale of cosmic distances", "grades": [9, 10], "terms": ["lawak ng kalawakan", "kalapdon sa kawanangan", "vast distances", "pinakamabilis na rocket", "pinakapaspas nga rocket", "libong taon ang biyahe", "liboan ka tuig nga biyahe", "next nearest star", "pinakamalapit na bituin", "pinakaduol nga bituon", "napakalayo"], "fact": {"tl": "Napakalawak ng kalawakan kaya kahit ang pinakamabilis na rocket ay aabutin ng libu-libong taon para makarating sa pinakamalapit na bituin pagkatapos ng Araw.", "en": "Space is so vast that even the fastest rocket would take thousands of years to reach the next nearest star after the Sun.", "bis": "Grabe kalapad ang kawanangan mao nga bisan ang pinakapaspas nga rocket mokabat og liboan ka tuig aron makaabot sa pinakaduol nga bituon human sa Adlaw."}, "source": "AAAS Benchmarks 4A/M2abc", "generator": "claude-workflow", "reviewed": false},
  {"id": "enso-definition-g9", "domain": "EARTH_SPACE", "topic": "El Nino Southern Oscillation ENSO definition", "grades": [9, 10], "terms": ["El Nino", "El Niño", "La Nina", "La Niña", "ENSO", "Southern Oscillation", "el niño", "klima", "klimaks", "panahon", "init ng dagat", "temperatura ng dagat", "Karagatang Pasipiko", "Pacific Ocean", "sea surface temperature", "ocean", "karagatan", "dagat", "sulog", "agos ng dagat", "pagbabago ng klima"], "fact": {"tl": "Ang El Niño at La Niña ay magkasalungat na yugto ng isang likas na pabago-bagong sistema na tinatawag na ENSO, kung saan nagbabago ang temperatura ng tubig sa ibabaw ng Karagatang Pasipiko at ang pag-ihip ng hangin sa ekwador.", "en": "El Niño and La Niña are opposite phases of a natural cycle called the El Niño-Southern Oscillation (ENSO), in which the surface temperature of the tropical Pacific Ocean and the equatorial winds shift back and forth.", "bis": "Ang El Niño ug La Niña kay magkasumpaki nga bahin sa usa ka natural nga nagbalhinbalhin nga sistema nga gitawag og ENSO, diin nagbag-o ang temperatura sa nawong sa Pasipiko nga dagat ug ang huyop sa hangin sa ekwador."}, "source": "NRC ESS2.D; DepEd G9 Earth Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "el-nino-mechanism-g10", "domain": "EARTH_SPACE", "topic": "El Nino warming mechanism Pacific", "grades": [9, 10], "terms": ["El Nino", "El Niño", "init na tubig", "mainit na tubig", "humihina ang hangin", "trade winds", "hanging kalakal", "Pasipiko", "Pacific", "silangan", "kanluran", "east", "west", "warming", "pag-init", "init sa dagat", "nawong sa dagat", "huyop sa hangin", "naghuyop", "agos"], "fact": {"tl": "Sa panahon ng El Niño, humihina o napapaliko ang karaniwang hanging humihip pakanluran sa ekwador, kaya't ang mainit na tubig ay naiipon sa gitna at silangang Pasipiko sa halip na sa kanluran malapit sa Pilipinas.", "en": "During El Niño, the usual winds that blow westward along the equator weaken or reverse, so warm surface water piles up in the central and eastern Pacific instead of in the west near the Philippines.", "bis": "Sa panahon sa El Niño, nagaluya o nausab ang naandang hangin nga nagahuyop paadto sa kasadpan sa ekwador, busa ang init nga tubig magtapok sa tunga ug sidlakang Pasipiko imbes sa kasadpan duol sa Pilipinas."}, "source": "NRC ESS2.D; PAGASA ENSO", "generator": "claude-workflow", "reviewed": false},
  {"id": "el-nino-ph-drought-g9", "domain": "EARTH_SPACE", "topic": "El Nino effects Philippines drought", "grades": [9, 10], "terms": ["El Nino", "El Niño", "tagtuyot", "tag-init", "kakulangan ng ulan", "drought", "tuyot", "huwaw", "kauhaw sa tubig", "pagkaubos ng tubig", "Pilipinas", "Philippines", "ani", "harvest", "magsasaka", "PAGASA", "init", "tag-araw", "wala ulan", "kakulang sa ulan"], "fact": {"tl": "Sa Pilipinas, ang El Niño ay kadalasang nagdadala ng mas kaunting ulan, mas mahabang tagtuyot, at mas mataas na panganib ng kakulangan sa tubig at pagkasira ng ani.", "en": "In the Philippines, El Niño usually brings less rainfall, longer dry spells, and a higher risk of water shortages and crop damage.", "bis": "Sa Pilipinas, ang El Niño kasagaran nagadala og gamay nga ulan, mas taas nga huwaw, ug mas dako nga peligro sa kakulang sa tubig ug kadaot sa ani."}, "source": "PAGASA ENSO impacts; NRC ESS2.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "la-nina-ph-rain-g9", "domain": "EARTH_SPACE", "topic": "La Nina effects Philippines heavy rain", "grades": [9, 10], "terms": ["La Nina", "La Niña", "malakas na ulan", "baha", "pagbaha", "more rain", "heavy rainfall", "bagyo", "typhoon", "Pilipinas", "Philippines", "basa", "kusog nga ulan", "lunop", "daghang ulan", "pagdaghan sa ulan", "PAGASA", "mas mainit na dagat sa kanluran"], "fact": {"tl": "Ang La Niña ay ang malamig na yugto ng ENSO na kadalasang nagdadala sa Pilipinas ng mas maraming ulan, mas malakas na hanging humampas sa kanluran, at mas mataas na panganib ng pagbaha.", "en": "La Niña is the cool phase of ENSO that usually brings the Philippines more rainfall, stronger westward winds, and a higher risk of flooding.", "bis": "Ang La Niña mao ang bugnaw nga bahin sa ENSO nga kasagaran nagadala sa Pilipinas og daghang ulan, mas kusog nga hangin paadto sa kasadpan, ug mas dako nga peligro sa baha."}, "source": "PAGASA ENSO impacts; NRC ESS2.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "enso-irregular-cycle-g10", "domain": "EARTH_SPACE", "topic": "ENSO irregular timing not seasonal", "grades": [9, 10], "terms": ["ENSO", "El Nino", "La Nina", "hindi regular", "ilang taon", "every few years", "every 2 to 7 years", "irregular", "dili regular", "matag pipila ka tuig", "panghitabo", "cycle", "ikot", "hindi panahong taon-taon", "natural", "likas", "natural nga panghitabo"], "fact": {"tl": "Hindi taon-taon nangyayari ang El Niño at La Niña kundi paitaas-pababa sa di-regular na pagitan na karaniwang dalawa hanggang pitong taon, kaya mahirap itong hulaan nang maaga.", "en": "El Niño and La Niña do not happen every year but swing back and forth at irregular intervals of usually two to seven years, which makes them hard to predict far ahead.", "bis": "Ang El Niño ug La Niña dili matag tuig mahitabo kondili nagbalhinbalhin sa dili regular nga gilay-on nga kasagaran duha ngadto sa pito ka tuig, busa lisod kini matagna sa sayo pa."}, "source": "NRC ESS2.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-currents-move-heat-g8", "domain": "EARTH_SPACE", "topic": "ocean currents move heat around planet", "grades": [7, 8, 9], "terms": ["agos ng dagat", "ocean current", "sulog sa dagat", "init", "heat", "thermal energy", "enerhiyang init", "nagdadala ng init", "naghahatid ng init", "nagdadala", "tropiko", "tropics", "polo", "poles", "tubig", "tubig sa dagat", "nagbabalik-balik", "nagahatud sa kainit", "kainit", "nag-apod-apod", "redistribute"], "fact": {"tl": "Ang mga agos ng dagat ay parang malalaking ilog sa loob ng karagatan na nagdadala ng init mula sa mainit na tropiko patungo sa mas malalamig na lugar malapit sa mga polo, kaya naaapektuhan ang klima sa buong mundo.", "en": "Ocean currents act like huge rivers within the sea that carry heat from the warm tropics toward colder regions near the poles, which shapes climate all around the world.", "bis": "Ang mga sulog sa dagat sama sa dagkong suba sulod sa kadagatan nga nagadala og kainit gikan sa init nga tropiko paingon sa mas bugnaw nga dapit duol sa mga polo, busa naapektuhan ang klima sa tibuok kalibutan."}, "source": "AAAS Benchmarks 4B/M9; NRC ESS2.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "ocean-moderates-coastal-climate-g8", "domain": "EARTH_SPACE", "topic": "ocean moderates coastal temperature", "grades": [7, 8, 9], "terms": ["dagat", "karagatan", "ocean", "mas banayad na temperatura", "moderate", "katamtaman", "baybay", "coast", "tabing-dagat", "loob ng lupa", "inland", "init na naiimbak", "stores heat", "nag-iipon ng init", "naghuhupa", "dili kaayo init", "dili kaayo bugnaw", "naghupot sa kainit", "tubig", "temperatura"], "fact": {"tl": "Dahil ang tubig-dagat ay nakakapag-imbak ng napakaraming init, ang mga lugar na malapit sa karagatan ay may mas banayad na temperatura kaysa sa mga lugar na nasa loob ng lupa ngunit nasa kaparehong latitud.", "en": "Because seawater can store a large amount of heat, places near the ocean have more moderate temperatures than inland places at the same latitude.", "bis": "Tungod kay ang tubig-dagat makahupot og daghan kaayo nga kainit, ang mga dapit duol sa kadagatan adunay mas humok nga temperatura kaysa sa mga dapit sa sulod sa yuta apan parehas og latitud."}, "source": "AAAS Benchmarks 4B/M9; NRC ESS2.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "currents-driven-wind-density-g10", "domain": "EARTH_SPACE", "topic": "what drives ocean currents wind density rotation", "grades": [9, 10], "terms": ["agos ng dagat", "ocean current", "sulog", "hangin", "wind", "huyop sa hangin", "density", "densidad", "kapal", "alat", "asin", "salinity", "temperatura", "pag-ikot ng mundo", "Earth rotation", "Coriolis", "pagliko", "rotasyon", "pagtuyok sa kalibutan", "bug-at nga tubig", "init at lamig", "mainit lumulutang malamig lumulubog"], "fact": {"tl": "Ang mga agos ng dagat ay pinapagalaw ng hangin sa ibabaw, ng pagkakaiba sa temperatura at alat ng tubig na nagbabago sa bigat nito, at ng pag-ikot ng Mundo na nagpapaliko sa daloy.", "en": "Ocean currents are driven by surface winds, by differences in water temperature and saltiness that change the water's density, and by the Earth's rotation, which bends the flow.", "bis": "Ang mga sulog sa dagat gipalihok sa hangin sa ibabaw, sa kalainan sa temperatura ug kaparat sa tubig nga nag-usab sa kabug-at niini, ug sa pagtuyok sa Kalibutan nga nagliko sa pag-agos."}, "source": "AAAS Benchmarks 4B/H2; NRC ESS2.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "thermohaline-conveyor-g10", "domain": "EARTH_SPACE", "topic": "global ocean conveyor deep circulation", "grades": [10], "terms": ["global ocean conveyor", "thermohaline", "malalim na agos", "deep current", "lubog na tubig", "sinking", "lumulubog", "malamig", "maalat", "mabigat na tubig", "cold salty water", "lalim", "deep", "lawom nga tubig", "naglubog", "naghatud sa init", "mainit na tubig sa ibabaw", "global circulation", "sirkulasyon", "naglibot sa mundo", "naglibot sa kalibutan"], "fact": {"tl": "Sa malamig na bahagi ng mundo, ang malamig at maalat na tubig-dagat ay nagiging mabigat at lumulubog sa kailaliman, na nagpapagalaw sa isang mabagal na pandaigdigang daloy na naghahatid ng init sa buong karagatan.", "en": "In cold parts of the world, cold and salty seawater becomes heavy and sinks to the deep ocean, driving a slow global flow that carries heat through the world's seas.", "bis": "Sa bugnaw nga bahin sa kalibutan, ang bugnaw ug parat nga tubig-dagat mahimong bug-at ug maglubog sa kahiladman, nga nagpalihok sa hinay nga global nga pag-agos nga nagdala og kainit sa tibuok kadagatan."}, "source": "NRC ESS2.C; ESS2.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "greenhouse-effect-mechanism-g8", "domain": "EARTH_SPACE", "topic": "greenhouse effect how it works infrared", "grades": [7, 8, 9, 10], "terms": ["greenhouse effect", "epektong greenhouse", "init", "araw", "sunlight", "liwanag ng araw", "infrared", "init na sinasala", "nakukulong na init", "trapped heat", "kumot", "blanket", "carbon dioxide", "water vapor", "singaw ng tubig", "gas", "naiipit na init", "nakulong nga kainit", "kainit gikan sa adlaw", "nagpainit sa kalibutan", "atmospera", "atmosphere"], "fact": {"tl": "Sa greenhouse effect, dumadaan ang liwanag ng araw papasok sa atmospera at nagpapainit sa lupa, ngunit ang ilang gas tulad ng carbon dioxide at singaw ng tubig ay sumasala sa init (infrared) na muling lumalabas, kaya nananatiling mainit ang Mundo.", "en": "In the greenhouse effect, sunlight passes into the atmosphere and warms the ground, but certain gases like carbon dioxide and water vapor absorb the heat (infrared) radiating back out, which keeps the Earth warm.", "bis": "Sa greenhouse effect, ang kahayag sa adlaw moagi paingon sa atmospera ug magpainit sa yuta, apan ang pipila ka gas sama sa carbon dioxide ug alisngaw sa tubig mosuyop sa kainit (infrared) nga mosibog pagawas, busa magpabilin nga init ang Kalibutan."}, "source": "AAAS Benchmarks 4B/H4; NRC ESS2.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "greenhouse-effect-natural-good-g8", "domain": "EARTH_SPACE", "topic": "natural greenhouse effect makes Earth habitable", "grades": [7, 8, 9], "terms": ["greenhouse effect", "natural", "likas", "kailangan", "habitable", "matitirhan", "puwedeng tirhan", "mabuhay", "masyadong malamig", "too cold", "yelo", "frozen", "ginhawang init", "kinahanglan", "puy-anan", "mabuhi", "sobra ka bugnaw", "init nga natural", "atmospera", "buhay sa Mundo"], "fact": {"tl": "Ang likas na greenhouse effect ay mahalaga at kapaki-pakinabang, sapagkat kung wala ito ay masyadong malamig at nagyeyelo ang Mundo para tirhan ng karamihan sa mga buhay na bagay.", "en": "The natural greenhouse effect is important and helpful, because without it the Earth would be too cold and frozen for most living things to survive.", "bis": "Ang natural nga greenhouse effect importante ug mapuslanon, kay kung wala kini sobra ka bugnaw ug nagyelo ang Kalibutan aron puy-an sa kadaghanan sa mga buhi nga butang."}, "source": "NRC ESS2.D; ESS3.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "greenhouse-gases-list-g9", "domain": "EARTH_SPACE", "topic": "main greenhouse gases carbon dioxide methane", "grades": [9, 10], "terms": ["greenhouse gases", "gas na greenhouse", "carbon dioxide", "CO2", "methane", "metano", "water vapor", "singaw ng tubig", "alisngaw sa tubig", "nitrous oxide", "gas na humuhuli ng init", "gas nga nagdakop sa kainit", "naiipon", "atmospera", "sumasala", "mosuyop", "naghuli", "klase sa gas"], "fact": {"tl": "Ang pinakamahahalagang greenhouse gas ay ang singaw ng tubig, carbon dioxide, methane, at nitrous oxide; ang mga ito ay sumisipsip at humahawak ng init na kung hindi ay tatakas papuntang kalawakan.", "en": "The most important greenhouse gases are water vapor, carbon dioxide, methane, and nitrous oxide; they absorb and hold heat that would otherwise escape to space.", "bis": "Ang labing importante nga greenhouse gases mao ang alisngaw sa tubig, carbon dioxide, methane, ug nitrous oxide; kini nagasuyop ug naghupot sa kainit nga kung dili moikyas unta paingon sa kawanangan."}, "source": "NRC ESS2.D; AAAS Benchmarks 4B/H4", "generator": "claude-workflow", "reviewed": false},
  {"id": "fossil-fuels-raise-co2-g9", "domain": "EARTH_SPACE", "topic": "burning fossil fuels increases carbon dioxide", "grades": [9, 10], "terms": ["fossil fuel", "fossil fuels", "uling", "coal", "langis", "oil", "petrolyo", "gasolina", "pagsunog", "burning", "pagdaghan sa carbon dioxide", "carbon dioxide", "CO2", "industriya", "pabrika", "sasakyan", "sunog nga uling", "pagsunog sa langis", "dumadami ang carbon dioxide", "nagdadagdag", "human activity", "ginawa ng tao"], "fact": {"tl": "Ang pagsunog ng mga fossil fuel tulad ng uling, langis, at natural gas para sa kuryente at sasakyan ang pangunahing dahilan kung bakit tumataas ang dami ng carbon dioxide sa atmospera mula noong nakaraang siglo.", "en": "Burning fossil fuels such as coal, oil, and natural gas for electricity and vehicles is the main reason the amount of carbon dioxide in the atmosphere has been rising over the past century.", "bis": "Ang pagsunog sa mga fossil fuel sama sa uling, langis, ug natural gas para sa koryente ug mga sakyanan mao ang nag-unang hinungdan nganong nagsaka ang gidaghanon sa carbon dioxide sa atmospera sukad sa miaging siglo."}, "source": "NRC ESS3.D; AAAS Benchmarks 4B/H6", "generator": "claude-workflow", "reviewed": false},
  {"id": "global-warming-definition-g9", "domain": "EARTH_SPACE", "topic": "global warming rising average temperature", "grades": [9, 10], "terms": ["global warming", "pag-init ng mundo", "pag-init sa kalibutan", "average temperature", "karaniwang temperatura", "tumataas na init", "rising temperature", "greenhouse gases", "tao", "human activity", "ginawa ng tao", "binabalewala", "pagtaas sa kainit", "nagsaka nga temperatura", "klima", "climate change", "pagbabago ng klima"], "fact": {"tl": "Ang global warming ay ang patuloy na pagtaas ng karaniwang temperatura sa ibabaw ng Mundo, na pangunahing dulot ng dumaraming greenhouse gases mula sa gawain ng tao.", "en": "Global warming is the ongoing rise in the average surface temperature of the Earth, caused mainly by the increasing greenhouse gases from human activity.", "bis": "Ang global warming mao ang nagpadayon nga pagsaka sa kasagaran nga temperatura sa nawong sa Kalibutan, nga panguna nga gipahinabo sa nagkadaghan nga greenhouse gases gikan sa kalihokan sa tawo."}, "source": "NRC ESS3.D; AAAS Benchmarks 4B/H6", "generator": "claude-workflow", "reviewed": false},
  {"id": "climate-vs-weather-g8", "domain": "EARTH_SPACE", "topic": "difference between climate and weather", "grades": [7, 8, 9], "terms": ["klima", "climate", "panahon", "weather", "matagal", "long term", "maikli", "short term", "araw-araw", "daily", "dekada", "decades", "average", "karaniwan", "kalainan", "panahon kada adlaw", "klima sa daghang tuig", "taas nga panahon", "kahimtang sa panahon", "init", "ulan"], "fact": {"tl": "Ang panahon (weather) ay ang kalagayan ng atmospera sa maikling panahon tulad ng isang araw, samantalang ang klima ay ang karaniwang pattern ng panahon sa isang lugar sa loob ng maraming taon o dekada.", "en": "Weather is the state of the atmosphere over a short time such as a single day, while climate is the average pattern of weather in a place over many years or decades.", "bis": "Ang panahon (weather) mao ang kahimtang sa atmospera sa mubo nga panahon sama sa usa ka adlaw, samtang ang klima mao ang kasagaran nga sumbanan sa panahon sa usa ka dapit sulod sa daghang tuig o dekada."}, "source": "AAAS Benchmarks 4B/H5; NRC ESS2.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "warming-evidence-temperature-record-g10", "domain": "EARTH_SPACE", "topic": "evidence global warming temperature records", "grades": [9, 10], "terms": ["ebidensya", "evidence", "katibayan", "pagsukat", "measurement", "rekord ng temperatura", "temperature record", "termometro", "thermometer", "siyentipiko", "scientists", "mas mainit na mga taon", "warmest years", "nagsaka nga init", "ebidensya sa pag-init", "datos", "data", "global", "tibuok kalibutan", "pagtaas"], "fact": {"tl": "Ang mga siyentipiko ay may pinagsama-samang pagsukat ng temperatura mula sa buong mundo na nagpapakitang tumataas ang karaniwang temperatura ng Mundo, at ang mga pinakamainit na taon ay naitala sa mga nakaraang dekada.", "en": "Scientists have combined temperature measurements from around the world that show the Earth's average temperature is rising, with the warmest years on record occurring in recent decades.", "bis": "Ang mga siyentista naghiusa sa mga sukod sa temperatura gikan sa tibuok kalibutan nga nagpakita nga nagsaka ang kasagaran nga temperatura sa Kalibutan, ug ang labing init nga mga tuig narekord sa bag-o lang nga mga dekada."}, "source": "NRC ESS3.D; ESS2.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "warming-evidence-ice-sea-g10", "domain": "EARTH_SPACE", "topic": "evidence warming melting ice sea level", "grades": [9, 10], "terms": ["ebidensya", "evidence", "natutunaw na yelo", "melting ice", "glacier", "natunaw nga yelo", "natutunaw", "sea level", "lebel ng dagat", "lebel sa dagat", "pagtaas ng tubig", "rising sea", "yelo sa polo", "polar ice", "natutunaw na glasyar", "nagtaas nga dagat", "katibayan", "pag-init", "Antartika", "Greenland"], "fact": {"tl": "Bukod sa mas mataas na temperatura, kasama sa ebidensya ng global warming ang natutunaw na mga glasyar at yelo sa polo at ang dahan-dahang pagtaas ng lebel ng dagat sa buong mundo.", "en": "Besides higher temperatures, the evidence for global warming includes melting glaciers and polar ice and the gradual rise of sea level around the world.", "bis": "Gawas sa mas taas nga temperatura, apil sa ebidensya sa global warming ang natunaw nga mga glacier ug yelo sa polo ug ang hinay-hinay nga pagsaka sa lebel sa dagat sa tibuok kalibutan."}, "source": "NRC ESS3.D; ESS2.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "sea-level-rise-cause-g10", "domain": "EARTH_SPACE", "topic": "why sea level rises warming", "grades": [9, 10], "terms": ["sea level rise", "pagtaas ng dagat", "pagsaka sa dagat", "lebel ng dagat", "natutunaw na yelo", "melting ice", "natunaw nga yelo", "lumalaki ang tubig", "thermal expansion", "lumalawak ang mainit na tubig", "pag-init ng tubig", "nagdako nga init nga tubig", "glacier", "baybay", "coast", "lunop sa baybay", "pagbaha sa baybay"], "fact": {"tl": "Tumataas ang lebel ng dagat dahil sa dalawang dahilan: ang pagtunaw ng yelo sa lupa na nagdadagdag ng tubig sa karagatan, at ang paglawak ng tubig-dagat habang ito ay umiinit.", "en": "Sea level rises for two reasons: ice on land melts and adds water to the ocean, and seawater expands as it warms.", "bis": "Nagsaka ang lebel sa dagat tungod sa duha ka rason: matunaw ang yelo sa yuta nga magdugang og tubig sa dagat, ug molapad ang tubig-dagat samtang kini moinit."}, "source": "NRC ESS2.C; ESS3.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "climate-impact-extreme-weather-g10", "domain": "EARTH_SPACE", "topic": "climate change impact stronger storms extremes", "grades": [9, 10], "terms": ["climate change", "pagbabago ng klima", "pagbag-o sa klima", "mas malakas na bagyo", "stronger typhoons", "kusog nga bagyo", "tagtuyot", "drought", "huwaw", "matinding panahon", "extreme weather", "init na sobra", "heat wave", "baha", "lunop", "mas init nga dagat", "warmer ocean", "Pilipinas", "Philippines", "panganib"], "fact": {"tl": "Habang umiinit ang Mundo, inaasahan ng mga siyentipiko na lalakas ang ilang bagyo at titindi ang mga matinding panahon tulad ng tagtuyot, baha, at init, na mapanganib para sa bansang madalas bagyuhin tulad ng Pilipinas.", "en": "As the Earth warms, scientists expect some storms to grow stronger and extreme weather such as droughts, floods, and heat to become more intense, which is dangerous for a typhoon-prone country like the Philippines.", "bis": "Samtang moinit ang Kalibutan, gilauman sa mga siyentista nga molakas ang pipila ka bagyo ug mograbe ang grabe nga panahon sama sa huwaw, baha, ug kainit, nga peligroso alang sa nasod nga kanunay gibagyo sama sa Pilipinas."}, "source": "NRC ESS3.D; ESS3.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "climate-impact-ecosystems-g10", "domain": "EARTH_SPACE", "topic": "climate change impact ecosystems coral reefs", "grades": [9, 10], "terms": ["climate change", "pagbabago ng klima", "ecosystem", "coral reef", "bahura", "coral", "namumuting coral", "coral bleaching", "pamuti sa coral", "init na tubig", "warm water", "isda", "fish", "hayop", "halaman", "species", "namamatay", "naapektuhan ang buhay", "kadagatan", "kasagbutan", "pagkaubos sa isda"], "fact": {"tl": "Ang mainit na temperatura ng dagat ay nagpapaputi at pumapatay ng mga bahura ng korales, at ang mabilis na pagbabago ng klima ay maaaring magpalipat o magpamatay ng ilang species ng halaman at hayop na hindi makakaangkop.", "en": "Warmer sea temperatures bleach and kill coral reefs, and rapid climate change can force some plant and animal species to move or die out if they cannot adapt.", "bis": "Ang mas init nga temperatura sa dagat magpaputi ug magpatay sa mga coral reef, ug ang paspas nga pagbag-o sa klima makapugos sa pipila ka matang sa tanom ug hayop nga mobalhin o mamatay kung dili sila makapahiangay."}, "source": "NRC LS2.C; ESS3.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "carbon-cycle-ocean-sink-g10", "domain": "EARTH_SPACE", "topic": "ocean absorbs carbon dioxide acidification", "grades": [10], "terms": ["carbon dioxide", "CO2", "karagatan", "ocean", "dagat", "sumisipsip", "absorbs", "nagasuyop", "ocean acidification", "pag-asim ng dagat", "pagkaaslom sa dagat", "acidic", "asido", "kabhang", "shells", "coral", "kabhang ng hayop", "alat", "tubig", "naghuhupa ng carbon", "nag-inom sa carbon"], "fact": {"tl": "Ang karagatan ay sumisipsip ng malaking bahagi ng dagdag na carbon dioxide mula sa hangin, ngunit dahil dito ay unti-unting umaasim ang tubig-dagat, na nakakasama sa mga corales at hayop na may kabhang.", "en": "The ocean absorbs a large share of the extra carbon dioxide from the air, but this slowly makes seawater more acidic, which harms corals and shelled animals.", "bis": "Ang kadagatan nagasuyop sa dako nga bahin sa sobra nga carbon dioxide gikan sa hangin, apan tungod niini anam-anam nga moaslom ang tubig-dagat, nga makadaot sa mga coral ug mga hayop nga adunay kabhang."}, "source": "NRC ESS2.D; LS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "albedo-ice-feedback-g10", "domain": "EARTH_SPACE", "topic": "ice albedo feedback reflectivity", "grades": [10], "terms": ["yelo", "ice", "puti", "white", "nagsasalamin", "reflects", "nagasalming", "albedo", "sinag ng araw", "sunlight", "kahayag sa adlaw", "natutunaw", "melting", "natunaw", "madilim na tubig", "dark water", "sumisipsip ng init", "absorbs heat", "mosuyop sa kainit", "feedback", "mas mabilis na pag-init"], "fact": {"tl": "Ang maputing yelo ay nagsasalamin ng sinag ng araw pabalik sa kalawakan, kaya kapag natunaw ito ay nalalantad ang madilim na tubig o lupa na mas sumisipsip ng init, na nagpapabilis pa sa pag-init.", "en": "Bright white ice reflects sunlight back to space, so when it melts it exposes darker water or land that absorbs more heat, which speeds up the warming even more.", "bis": "Ang puti nga yelo nagasalming sa kahayag sa adlaw balik sa kawanangan, busa kung kini matunaw mabutyag ang mas itom nga tubig o yuta nga mosuyop og dugang kainit, nga magpadali pa sa pag-init."}, "source": "NRC ESS2.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "natural-climate-change-causes-g10", "domain": "EARTH_SPACE", "topic": "natural causes of past climate change", "grades": [10], "terms": ["natural", "likas", "pagbabago ng klima noon", "past climate change", "bulkan", "volcano", "abo ng bulkan", "volcanic ash", "araw", "sun energy", "sinag ng araw", "orbit", "ice age", "panahon ng yelo", "edad sa yelo", "natural nga rason", "abu sa bulkan", "kanhi nga klima"], "fact": {"tl": "Nagbabago rin ang klima dahil sa likas na dahilan tulad ng pagbabago sa lakas ng araw, pag-ikot at hilig ng Mundo, at pagsabog ng bulkan, ngunit ang mabilis na pag-init ngayon ay dulot ng gawain ng tao.", "en": "Climate also changes for natural reasons such as shifts in the sun's strength, the Earth's orbit and tilt, and volcanic eruptions, but the rapid warming today is caused by human activity.", "bis": "Nagbag-o usab ang klima tungod sa natural nga mga rason sama sa pagbag-o sa kusog sa adlaw, sa orbit ug kiling sa Kalibutan, ug sa pagbuto sa bulkan, apan ang paspas nga pag-init karon gipahinabo sa kalihokan sa tawo."}, "source": "NRC ESS2.D; ESS3.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "mitigation-reduce-emissions-g10", "domain": "EARTH_SPACE", "topic": "climate mitigation reduce greenhouse gas emissions", "grades": [9, 10], "terms": ["mitigation", "pagbabawas", "pagpaminus", "greenhouse gases", "renewable energy", "solar", "araw", "hangin", "wind", "enerhiya nga malinis", "clean energy", "pagbawas ng carbon", "fossil fuel", "kuryente nga limpyo", "puno", "trees", "kahoy", "energy efficiency", "tipid sa kuryente", "solusyon", "solution", "pagbuhi og kahoy"], "fact": {"tl": "Upang mapabagal ang pag-init ng Mundo, kailangang bawasan ang paglabas ng greenhouse gases sa pamamagitan ng paggamit ng malinis na enerhiya tulad ng araw at hangin, pagtitipid ng kuryente, at pagtatanim ng mga puno.", "en": "To slow the warming of the Earth, people need to cut greenhouse gas emissions by using clean energy such as solar and wind, saving electricity, and planting trees.", "bis": "Aron mahinay ang pag-init sa Kalibutan, kinahanglan paminusan ang pagbuga sa greenhouse gases pinaagi sa paggamit og limpyo nga enerhiya sama sa adlaw ug hangin, pagdaginot sa koryente, ug pagtanom og mga kahoy."}, "source": "NRC ESS3.D; ESS3.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "mitigation-vs-adaptation-g10", "domain": "EARTH_SPACE", "topic": "mitigation versus adaptation climate", "grades": [10], "terms": ["mitigation", "adaptation", "pag-angkop", "pagpahiangay", "pagbabawas ng carbon", "pagharap sa epekto", "seawall", "harang sa dagat", "pananim na matibay", "drought-resistant crops", "early warning", "babala", "pasidaan", "pagdepensa", "coping", "pagsagubang", "dalawang paraan", "duha ka paagi", "solusyon sa klima"], "fact": {"tl": "May dalawang paraan ang tao sa pagharap sa pagbabago ng klima: ang mitigation na nagbabawas sa greenhouse gases, at ang adaptation na naghahanda sa epekto tulad ng paggawa ng harang sa dagat at pagtatanim ng pananim na kayang makaligtas sa tagtuyot.", "en": "People deal with climate change in two ways: mitigation, which reduces greenhouse gases, and adaptation, which prepares for the impacts, such as building seawalls and growing crops that survive drought.", "bis": "Adunay duha ka paagi ang tawo sa pag-atubang sa pagbag-o sa klima: ang mitigation nga nagpaminus sa greenhouse gases, ug ang adaptation nga nag-andam sa mga epekto, sama sa paghimo og seawall ug pagtanom og pananom nga makalahutay sa huwaw."}, "source": "NRC ESS3.D; ETS1.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "climate-models-prediction-g10", "domain": "EARTH_SPACE", "topic": "climate models predict future warming", "grades": [10], "terms": ["climate model", "modelo ng klima", "modelo sa klima", "computer", "kompyuter", "hula", "prediction", "tagna", "siyentipiko", "scientists", "pagsubok", "test", "nakaraang klima", "past climate", "future", "hinaharap", "umaasa sa gawi ng tao", "depende sa tao", "panghulagway", "pagbanabana"], "fact": {"tl": "Ang mga siyentipiko ay gumagamit ng climate models sa kompyuter na sumusubok sa nakaraang klima upang hulaan ang hinaharap, at ipinapakita ng mga ito na patuloy na tataas ang temperatura depende sa dami ng greenhouse gas na idaragdag ng tao.", "en": "Scientists use computer climate models that are tested against past climate to predict the future, and these show that temperatures will keep rising depending on how much greenhouse gas humans add.", "bis": "Ang mga siyentista naggamit og climate models sa kompyuter nga gisulayan batok sa kanhing klima aron matagna ang umaabot, ug kini nagpakita nga magpadayon sa pagsaka ang temperatura depende sa kadaghan sa greenhouse gas nga idugang sa tawo."}, "source": "NRC ESS3.D; ESS2.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "enso-affects-fishing-g10", "domain": "EARTH_SPACE", "topic": "El Nino upwelling fish effect", "grades": [10], "terms": ["El Nino", "El Niño", "isda", "fish", "mangingisda", "fishing", "pangisda", "upwelling", "pag-akyat ng malamig na tubig", "sustansya", "nutrients", "plankton", "mainit na tubig", "warm water", "humihina ang isda", "pagkaubos sa isda", "init nga tubig", "tropiko", "Pasipiko", "naghuyop sa hangin"], "fact": {"tl": "Karaniwan, ang malamig at masustansyang tubig ay umaakyat mula sa kailaliman ng dagat at nagpapalago ng isda, ngunit sa panahon ng El Niño ay tinatakpan ito ng mainit na tubig kaya bumababa ang huli ng mga mangingisda.", "en": "Normally cold, nutrient-rich water rises from the deep ocean and feeds large fish populations, but during El Niño warm water covers it, so fishermen's catch drops.", "bis": "Kasagaran, ang bugnaw ug masustansya nga tubig mosaka gikan sa kahiladman sa dagat ug magpadako sa mga isda, apan sa panahon sa El Niño matabonan kini sa init nga tubig busa mokunhod ang kuha sa mga mangingisda."}, "source": "NRC ESS2.D; ESS2.C", "generator": "claude-workflow", "reviewed": false},
  {"id": "carbon-dioxide-radiative-balance-g10", "domain": "EARTH_SPACE", "topic": "energy balance Earth radiates to space", "grades": [10], "terms": ["energy balance", "balanse ng enerhiya", "balanse sa enerhiya", "init mula sa araw", "incoming sunlight", "radiated to space", "naglalabas ng init", "infrared", "greenhouse gas", "mas mainit", "warmer", "naipit na init", "hangtod nga magkatimbang", "katimbang", "balik sa kawanangan", "atmospera", "temperatura", "nagsaka", "nakulong nga kainit"], "fact": {"tl": "Nananatiling balanse ang temperatura ng Mundo kapag pareho ang init na natatanggap mula sa araw at ang init na naglalabas pabalik sa kalawakan, ngunit kapag dumami ang greenhouse gas, kailangang mas uminit muna ang Mundo bago muling magkapantay ang dalawa.", "en": "The Earth's temperature stays steady when the heat it receives from the sun equals the heat it radiates back to space, but when greenhouse gases increase, the Earth must warm up before the two balance again.", "bis": "Magpabilin nga balanse ang temperatura sa Kalibutan kung managsama ang kainit nga madawat gikan sa adlaw ug ang kainit nga gibuga balik sa kawanangan, apan kung modaghan ang greenhouse gas, kinahanglan moinit usa ang Kalibutan una magkapareha pag-usab ang duha."}, "source": "AAAS Benchmarks 4B/H4; NRC ESS2.D", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-anatomy-crest-trough-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "wave crest and trough", "grades": [7, 8, 9], "terms": ["alon", "taluktok ng alon", "lambak ng alon", "balod", "tumoy sa balod", "tunga sa balod", "crest", "trough", "wave anatomy", "peak", "highest point", "lowest point", "bahagi ng alon"], "fact": {"tl": "Ang pinakamataas na bahagi ng isang alon ay tinatawag na taluktok (crest), at ang pinakamababang bahagi ay tinatawag na lambak (trough).", "en": "The highest part of a wave is called the crest, and the lowest part is called the trough.", "bis": "Ang pinakataas nga bahin sa usa ka balod gitawag nga taluktok (crest), ug ang pinakaubos nga bahin gitawag nga lawom o trough."}, "source": "AAAS Benchmarks 4F/M7; NRC PS4.A grade-5 endpoint", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-amplitude-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "wave amplitude", "grades": [7, 8, 9], "terms": ["amplitude", "lakas ng alon", "taas ng alon", "gitas-on sa balod", "kakusog sa balod", "wave height", "amplitud", "lawak ng pag-galaw", "kusog", "loudness", "kalakasan ng tunog"], "fact": {"tl": "Ang amplitude ay ang taas ng alon mula sa gitnang linya nito, at kapag mas malaki ang amplitude, mas malaki ang enerhiyang dala ng alon.", "en": "Amplitude is the height of a wave from its resting middle line, and a larger amplitude means the wave carries more energy.", "bis": "Ang amplitude mao ang gitas-on sa balod gikan sa tunga nga linya niini, ug kung mas dako ang amplitude, mas dako ang enerhiya nga dala sa balod."}, "source": "NRC PS4.A grade-5 endpoint; AAAS Benchmarks 4F/M7", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-wavelength-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "wavelength", "grades": [7, 8, 9], "terms": ["wavelength", "haba ng alon", "gitas-on sa balod", "agwat ng alon", "distansya sa duha ka taluktok", "distance between crests", "haba", "spacing", "sukod sa balod", "wavelength meaning"], "fact": {"tl": "Ang wavelength (haba ng alon) ay ang distansya mula sa isang taluktok hanggang sa susunod na taluktok ng alon.", "en": "Wavelength is the distance from one crest of a wave to the next crest.", "bis": "Ang wavelength (gitas-on sa balod) mao ang distansya gikan sa usa ka taluktok ngadto sa sunod nga taluktok sa balod."}, "source": "AAAS Benchmarks 4F/M7; NRC PS4.A grade-5 endpoint", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-frequency-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "wave frequency", "grades": [7, 8, 9], "terms": ["frequency", "dalas", "kadalas", "kadaghan sa balod", "bilang ng alon", "waves per second", "hertz", "kadalas ng alon", "frequency meaning", "bilang sa balod kada segundo"], "fact": {"tl": "Ang frequency (dalas) ay kung ilang alon ang dumadaan sa isang punto sa loob ng isang segundo, at sinusukat ito sa hertz.", "en": "Frequency is how many waves pass a point in one second, and it is measured in hertz.", "bis": "Ang frequency (kadalas) mao kung pila ka balod ang moagi sa usa ka punto sulod sa usa ka segundo, ug gisukod kini sa hertz."}, "source": "AAAS Benchmarks 4F/M7; NRC PS4.A grade-8 endpoint", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-frequency-wavelength-inverse-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "frequency and wavelength relationship", "grades": [8, 9, 10], "terms": ["frequency wavelength relationship", "mataas na frequency maikling wavelength", "kabaliktaran", "inverse", "habang taas ang dalas mubo ang gitas-on", "higher frequency shorter wavelength", "ugnayan ng dalas at haba", "kalabotan sa kadalas ug gitas-on"], "fact": {"tl": "Para sa parehong uri ng alon, ang mas mataas na frequency ay may mas maikling wavelength, at ang mas mababang frequency ay may mas mahabang wavelength.", "en": "For the same type of wave, a higher frequency has a shorter wavelength, and a lower frequency has a longer wavelength.", "bis": "Para sa parehas nga matang sa balod, ang mas taas nga frequency adunay mas mubo nga wavelength, ug ang mas ubos nga frequency adunay mas taas nga wavelength."}, "source": "AAAS Benchmarks 4F (grades 9-12 discussion); NRC PS4.A grade-12 endpoint", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-speed-equation-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "wave speed equation", "grades": [9, 10], "terms": ["wave speed", "bilis ng alon", "katulin sa balod", "speed equals wavelength times frequency", "bilis katumbas wavelength frequency", "v = f λ", "formula ng alon", "pagkalkula sa balod", "speed wavelength frequency"], "fact": {"tl": "Ang bilis ng isang alon ay katumbas ng wavelength nito na minultiply sa frequency nito (bilis = wavelength × frequency).", "en": "The speed of a wave equals its wavelength multiplied by its frequency (speed = wavelength × frequency).", "bis": "Ang katulin sa usa ka balod katumbas sa wavelength niini nga gipadaghan sa frequency niini (katulin = wavelength × frequency)."}, "source": "AAAS Benchmarks 4F (grades 9-12); NRC PS4.A grade-12 endpoint", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-speed-depends-medium-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "wave speed depends on medium", "grades": [8, 9, 10], "terms": ["wave speed medium", "bilis ng alon depende sa medium", "lainlain nga katulin", "different speeds in different materials", "iba't ibang bilis", "magkaiba sa bawat materyal", "katulin nagdepende sa materyal", "sound travels faster in water"], "fact": {"tl": "Ang isang alon ay maaaring kumilos nang iba't ibang bilis sa iba't ibang materyal; halimbawa, mas mabilis ang tunog sa tubig at metal kaysa sa hangin.", "en": "A wave can travel at different speeds in different materials; for example, sound travels faster in water and metal than in air.", "bis": "Ang usa ka balod mahimong molihok sa lainlaing katulin sa lainlaing materyal; pananglitan, mas paspas ang tingog sa tubig ug metal kaysa sa hangin."}, "source": "AAAS Benchmarks 4F/M4; NRC PS4.A grade-12 endpoint", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-sound-needs-medium-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "sound waves need a medium", "grades": [8, 9], "terms": ["sound needs medium", "kailangan ng tunog ng medium", "walang tunog sa vacuum", "walay tingog sa wala'y hangin", "sound vacuum", "pressure wave air", "tunog kailangan hangin", "tingog nanginahanglan medium", "bakwum"], "fact": {"tl": "Ang tunog ay isang alon ng presyon na nangangailangan ng medium tulad ng hangin, tubig, o solido, kaya't hindi ito makakadaan sa lubos na walang laman na espasyo.", "en": "Sound is a pressure wave that needs a medium such as air, water, or a solid, so it cannot travel through a complete vacuum.", "bis": "Ang tingog usa ka balod sa presyon nga nanginahanglan og medium sama sa hangin, tubig, o solido, mao nga dili kini makaagi sa hingpit nga wala'y sulod nga luna."}, "source": "NRC PS4.A grade-8 endpoint; AAAS Benchmarks 4F/M4", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-carries-energy-not-matter-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "waves carry energy not matter", "grades": [8, 9, 10], "terms": ["wave carries energy not matter", "alon nagdadala ng enerhiya hindi bagay", "balod nagdala enerhiya dili materya", "energy transfer", "cork bobbing", "lumulutang na yelo", "hindi gumagalaw ang tubig", "dili molihok ang medium", "paglipat ng enerhiya", "pattern of motion"], "fact": {"tl": "Ang isang alon ay naglilipat ng enerhiya mula sa isang lugar patungo sa iba nang hindi dinadala ang mismong medium, kaya't ang lumulutang na korotso ay tumataas-bumababa lamang sa lugar nito habang dumadaan ang alon.", "en": "A wave transfers energy from one place to another without carrying the medium itself along, so a floating cork only bobs up and down in place as the wave passes.", "bis": "Ang usa ka balod magbalhin og enerhiya gikan sa usa ka dapit ngadto sa lain nga dili dalhon ang medium mismo, mao nga ang naglutaw nga tapon mokayab-kanaog lang sa iyang dapit samtang moagi ang balod."}, "source": "NRC PS4.A grade-2 and grade-8 endpoints; AAAS Benchmarks 4F/H6c", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-energy-amplitude-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "wave energy and amplitude", "grades": [9, 10], "terms": ["wave energy amplitude", "enerhiya at amplitude", "mas malaki amplitude mas malaki enerhiya", "louder sound bigger amplitude", "kakusog sa tingog", "lakas ng tunog", "mas dako amplitude mas dako kusog", "wave energy"], "fact": {"tl": "Ang enerhiyang dala ng isang alon ay konektado sa amplitude nito, kaya't ang mas malakas na tunog ay may mas malaking amplitude kaysa sa mahinang tunog na may parehong pitch.", "en": "The energy a wave carries is linked to its amplitude, so a louder sound has a larger amplitude than a soft sound of the same pitch.", "bis": "Ang enerhiya nga dala sa usa ka balod konektado sa amplitude niini, mao nga ang mas kusog nga tingog adunay mas dako nga amplitude kaysa sa hinay nga tingog nga parehas og pitch."}, "source": "NRC PS4.A; AAAS Benchmarks 4F/H6c (energy of waves)", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-frequency-pitch-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "frequency and pitch", "grades": [8, 9], "terms": ["frequency pitch", "dalas at pitch", "mataas na frequency mataas na tono", "high pitch", "matas nga tingog", "taas nga pitch", "kadalas ug pitch", "pitch of sound", "tono ng tunog", "mababang tono", "lalim sa tingog"], "fact": {"tl": "Ang frequency ng tunog ang tumutukoy sa pitch nito; ang mataas na frequency ay nagbibigay ng matinis na tunog, at ang mababang frequency ay nagbibigay ng malalim na tunog.", "en": "The frequency of a sound determines its pitch; a high frequency gives a high-pitched sound, and a low frequency gives a low-pitched sound.", "bis": "Ang frequency sa tingog mao ang nagtino sa pitch niini; ang taas nga frequency mohatag og matas nga tingog, ug ang ubos nga frequency mohatag og lawom nga tingog."}, "source": "AAAS Benchmarks 4F/M5 (analog); NRC PS4.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-doppler-effect-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "Doppler effect", "grades": [9, 10], "terms": ["Doppler effect", "epekto ng Doppler", "pagbabago ng pitch", "papalapit papalayo", "relative motion source observer", "kilos sa tinubdan ug tagpaminaw", "pagbag-o sa pitch", "moving source", "siren pitch change", "obserbador", "paglapit at paglayo"], "fact": {"tl": "Sa Doppler effect, nagbabago ang naoobserbahang frequency ng alon dahil sa relatibong galaw ng pinagmumulan at ng tagamasid: mas mataas ang pitch kapag papalapit at mas mababa kapag papalayo.", "en": "In the Doppler effect, the observed frequency of a wave changes because of the relative motion of the source and the observer: the pitch is higher when they approach and lower when they move apart.", "bis": "Sa Doppler effect, mausab ang nakit-an nga frequency sa balod tungod sa relatibo nga paglihok sa tinubdan ug sa tagpaniid: mas taas ang pitch kung magkaduol ug mas ubos kung magkalayo."}, "source": "AAAS Benchmarks 4F/H5ab; NRC PS4.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-doppler-wavelength-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "Doppler effect and observed wavelength", "grades": [9, 10], "terms": ["Doppler wavelength", "naoobserbahang wavelength", "papalapit mas maikli", "papalayo mas mahaba", "shorter wavelength approaching", "mas mubo nga wavelength duol", "observed wavelength", "haba ng alon na nakikita", "relative motion wavelength"], "fact": {"tl": "Ang naoobserbahang wavelength ng isang alon ay nagiging mas maikli kapag papalapit ang pinagmumulan o tagamasid sa isa't isa, at mas mahaba kapag papalayo sila.", "en": "The observed wavelength of a wave becomes shorter when the source or observer moves toward the other, and longer when they move apart.", "bis": "Ang nakit-an nga wavelength sa usa ka balod mahimong mas mubo kung ang tinubdan o tagpaniid magpaduol sa usag usa, ug mas taas kung sila magpalayo."}, "source": "AAAS Benchmarks 4F/H5ab", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-redshift-universe-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "redshift and expanding universe", "grades": [10], "terms": ["redshift", "red shift", "pulang paglipat", "expanding universe", "lumalawak na uniberso", "nagkalapad nga uniberso", "distant galaxies", "malalayong galaksi", "mas mahabang wavelength", "longer wavelength light", "Doppler light", "pula nga galaksi"], "fact": {"tl": "Dahil ang liwanag mula sa halos lahat ng malalayong galaksi ay may mas mahabang wavelength (redshift) kaysa sa inaasahan, naniniwala ang mga astronomo na lumalawak ang buong uniberso.", "en": "Because the light from almost all distant galaxies has a longer wavelength (redshift) than expected, astronomers believe the whole universe is expanding.", "bis": "Tungod kay ang kahayag gikan sa halos tanan nga layo nga galaksiya adunay mas taas nga wavelength (redshift) kaysa gilauman, nagtuo ang mga astronomo nga nagkalapad ang tibuok uniberso."}, "source": "AAAS Benchmarks 4F/H5c", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-resonance-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "resonance", "grades": [9, 10], "terms": ["resonance", "resonansya", "natural frequency", "natural na frequency", "kinaiyanhon nga frequency", "pag-ugong", "in phase", "tumataas na amplitude", "musical instrument", "vibrating string", "instrumentong pangmusika", "pagdugang sa amplitude"], "fact": {"tl": "Ang resonance ay nangyayari kapag ang isang bagay ay tinutulak sa natural na frequency nito, kaya't ang mga alon ay nagdadagdag at lumalaki ang amplitude, tulad sa kuwerdas ng gitara o hangin sa loob ng plawta.", "en": "Resonance happens when something is pushed at its natural frequency, so the waves add up and grow in amplitude, as in a guitar string or the air inside a flute.", "bis": "Ang resonance mahitabo kung ang usa ka butang itulod sa natural niini nga frequency, mao nga ang mga balod magdugang ug modako ang amplitude, sama sa kwerdas sa gitara o sa hangin sulod sa plawta."}, "source": "NRC PS4.A (resonance); AAAS Benchmarks (PS4.A grade-8/12)", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-superposition-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "wave superposition", "grades": [9, 10], "terms": ["superposition", "pagpapatong ng alon", "pagdugtong sa balod", "waves add or cancel", "nagdaragdag o nagkakansela", "magdugang o magwagtang", "interference", "interperensya", "in phase out of phase", "pagsapaw ng alon", "constructive destructive"], "fact": {"tl": "Kapag dalawang alon ng parehong uri ang nagtatagpo, maaari silang magdagdag o magkansela sa isa't isa depende sa pagkakahanay ng kanilang mga taluktok at lambak, ngunit pagkatapos magkrus ay nagpapatuloy sila nang hindi nababago.", "en": "When two waves of the same type meet, they can add together or cancel each other depending on how their crests and troughs line up, but after crossing they continue on unchanged.", "bis": "Kung duha ka balod sa parehas nga matang magtagbo, mahimo silang magdugang o magwagtang sa usag usa depende sa pagkahan-ay sa ilang mga taluktok ug lawom, apan human magkrus magpadayon sila nga walay kausaban."}, "source": "NRC PS4.A grade-5 endpoint; AAAS Benchmarks 4F/H6ab", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-reflection-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "wave reflection", "grades": [8, 9, 10], "terms": ["wave reflection", "pagbalik ng alon", "pagbawi sa balod", "echo", "alingawngaw", "reflected wave", "tumatalbog na alon", "bounce off surface", "pagsalpok sa ibabaw", "reflection of sound", "pag-bounce sa balod"], "fact": {"tl": "Kapag ang isang alon ay tumama sa hangganan ng dalawang magkaibang materyal, bahagi nito ang tumatalbog pabalik, at ito ang dahilan ng alingawngaw ng tunog.", "en": "When a wave hits the boundary between two different materials, part of it bounces back, and this reflection is what causes an echo of sound.", "bis": "Kung ang usa ka balod moigo sa utlanan sa duha ka lainlain nga materyal, ang usa ka bahin niini mobalik, ug kini nga pagbalik mao ang hinungdan sa alingawngaw sa tingog."}, "source": "NRC PS4.A grade-12 endpoint; AAAS Benchmarks 4F/H6ab", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-refraction-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "wave refraction", "grades": [9, 10], "terms": ["wave refraction", "pagliko ng alon", "pagbaliko sa balod", "change direction", "nagbabago ng direksyon", "pagbag-o sa direksyon", "bending of wave", "iba ang bilis sa bagong medium", "pagliko ng liwanag", "refract", "lainlaing katulin"], "fact": {"tl": "Kapag ang isang alon ay dumaan mula sa isang medium patungo sa iba at nagbago ang bilis nito, maaari itong lumiko o mag-refract, tulad ng liwanag na lumiliko kapag pumapasok sa tubig.", "en": "When a wave passes from one medium into another and changes speed, it can bend or refract, like light bending as it enters water.", "bis": "Kung ang usa ka balod moagi gikan sa usa ka medium ngadto sa lain ug mausab ang katulin niini, mahimo kining moliko o mo-refract, sama sa kahayag nga moliko kung mosulod sa tubig."}, "source": "NRC PS4.A grade-12 endpoint; AAAS Benchmarks 4F/H6ab", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-small-objects-pass-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "waves and object size", "grades": [10], "terms": ["wave object size", "alon at laki ng bagay", "sukod sa balod ug butang", "wavelength too small to see", "hindi nakikita", "dili makita", "diffraction around obstacles", "bend around corners", "liko sa eskina", "longer wavelength spread", "spread around obstacles"], "fact": {"tl": "Kapag ang isang bagay ay napakaliit kumpara sa wavelength ng isang alon, halos hindi ito naaapektuhan ng bagay, kaya't may mga bagay na napakaliit para makita gamit ang nakikitang liwanag.", "en": "When an object is very small compared with a wave's wavelength, the wave is barely affected by it, which is why some things are too small to see with visible light.", "bis": "Kung ang usa ka butang gamay kaayo kumpara sa wavelength sa usa ka balod, halos dili kini maapektuhan sa butang, mao nga adunay mga butang nga gamay ra kaayo aron makita gamit ang makita nga kahayag."}, "source": "NRC PS4.A (grade-8/12 wave-object discussion); AAAS Benchmarks 4F (grades 9-12)", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-em-no-medium-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "electromagnetic waves need no medium", "grades": [10], "terms": ["electromagnetic wave", "alon na electromagnetic", "walang medium", "walay medium", "liwanag sa kalawakan", "kahayag sa kawanangan", "speed of light", "bilis ng liwanag", "light travels through space", "kuryente magnetikong alon", "radio waves", "electric magnetic fields"], "fact": {"tl": "Ang mga electromagnetic wave tulad ng liwanag at radyo ay alon ng nagbabagong electric at magnetic field na maaaring dumaan kahit sa walang laman na kalawakan nang hindi nangangailangan ng medium.", "en": "Electromagnetic waves such as light and radio are waves of changing electric and magnetic fields that can travel even through empty space without needing a medium.", "bis": "Ang mga electromagnetic wave sama sa kahayag ug radyo mao ang mga balod sa nagbag-o nga electric ug magnetic field nga makaagi bisan sa wala'y sulod nga kawanangan nga dili manginahanglan og medium."}, "source": "AAAS Benchmarks 4F/H3a, 4F/H3c; NRC PS4.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-em-same-speed-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "speed of light in vacuum", "grades": [10], "terms": ["speed of light", "bilis ng liwanag", "katulin sa kahayag", "all electromagnetic waves same speed", "parehong bilis sa vacuum", "parehas nga katulin", "empty space", "kalawakan", "kawanangan", "radio light same speed", "vacuum speed"], "fact": {"tl": "Sa walang laman na espasyo, lahat ng electromagnetic wave—mula radyo hanggang liwanag—ay kumikilos sa parehong bilis na tinatawag na bilis ng liwanag.", "en": "In empty space, all electromagnetic waves—from radio to light—travel at the same speed, called the speed of light.", "bis": "Sa wala'y sulod nga luna, ang tanan nga electromagnetic wave—gikan sa radyo hangtod sa kahayag—molihok sa parehas nga katulin nga gitawag og katulin sa kahayag."}, "source": "AAAS Benchmarks 4F/H3c", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-seismic-probe-earth-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "seismic waves probe Earth", "grades": [9, 10], "terms": ["seismic waves", "alon ng lindol", "balod sa linog", "probe Earth interior", "loob ng Mundo", "sulod sa Yuta", "earthquake waves", "geologist", "reflection at layers", "pagbalik sa mga sapaw", "imahe sa sulod sa planeta", "pagsusuri sa loob ng planeta"], "fact": {"tl": "Gumagamit ang mga heologo ng mga seismic wave mula sa lindol at ng pagtalbog ng mga ito sa hangganan ng mga sapin upang matuklasan ang istruktura sa loob ng Mundo.", "en": "Geologists use seismic waves from earthquakes and their reflection at the boundaries between layers to discover the structure deep inside the Earth.", "bis": "Naggamit ang mga heologo og mga seismic wave gikan sa linog ug ang pagbalik niini sa mga utlanan sa mga sapaw aron masuta ang istruktura sa sulod sa Yuta."}, "source": "NRC PS4.A grade-8 endpoint; AAAS Benchmarks 4F/M4", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-water-circular-motion-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "water wave particle motion", "grades": [8, 9], "terms": ["water wave", "alon ng tubig", "balod sa tubig", "bobbing cork", "lumulutang na korotso", "naglutaw nga tapon", "up and down in place", "pataas pababa sa lugar", "surface wave", "alon sa ibabaw", "water goes up and down", "bird on water"], "fact": {"tl": "Sa alon sa malalim na tubig, ang tubig ay tumataas at bumababa lamang sa kinalalagyan nito at hindi sumasama sa direksyon ng alon, kaya't ang lumulutang na ibon o korotso ay umuugoy-ugoy lang sa lugar nito.", "en": "In a wave on deep water, the water only goes up and down in place and does not move along with the direction of the wave, so a floating bird or cork just bobs in place.", "bis": "Sa balod sa lawom nga tubig, ang tubig mokayab ug mokanaog lang sa iyang dapit ug dili mouban sa direksyon sa balod, mao nga ang naglutaw nga langgam o tapon mag-uyog-uyog lang sa iyang dapit."}, "source": "NRC PS4.A grade-2 endpoint (bobbing cork/seabird)", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-water-breaks-shore-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "why water waves break at the shore", "grades": [8, 9], "terms": ["wave breaks shore", "pagputok ng alon sa baybayin", "pagbuto sa balod sa baybayon", "shallow water", "mababaw na tubig", "mabaw nga tubig", "wave reaches beach", "alon sa dalampasigan", "breaking wave", "bumabagsak na alon", "tabod sa baybayon"], "fact": {"tl": "Kapag ang alon ay umaabot sa mababaw na tubig malapit sa baybayin, bumabagal ang ilalim nito at tumataas ang taluktok hanggang sa ito ay tumagilid at pumutok bilang nasasakyang alon.", "en": "When a wave reaches shallow water near the shore, its bottom slows down and the crest grows taller until it topples over and breaks as a surf wave.", "bis": "Kung ang balod moabot sa mabaw nga tubig duol sa baybayon, mohinay ang ubos niini ug motaas ang taluktok hangtod nga motakilid kini ug mobuto isip surf nga balod."}, "source": "NRC PS4.A grade-2 endpoint (water meets the beach); consensus oceanography", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-tsunami-long-wavelength-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "tsunami wave properties", "grades": [9, 10], "terms": ["tsunami wave", "alon ng tsunami", "balod sa tsunami", "long wavelength", "mahabang wavelength", "taas nga wavelength", "fast in deep ocean", "mabilis sa lalim", "paspas sa lawod", "grows tall near coast", "lumalaki malapit sa baybayin", "PHIVOLCS", "shallow water height"], "fact": {"tl": "Ang tsunami ay may napakahabang wavelength at kumikilos nang napakabilis sa malalim na dagat, ngunit bumabagal ito at biglang tumataas pagdating sa mababaw na tubig malapit sa baybayin.", "en": "A tsunami has a very long wavelength and travels extremely fast in the deep ocean, but it slows down and suddenly grows tall when it reaches shallow water near the coast.", "bis": "Ang tsunami adunay taas kaayo nga wavelength ug molihok nga paspas kaayo sa lawom nga dagat, apan mohinay kini ug kalit nga motaas pag-abot sa mabaw nga tubig duol sa baybayon."}, "source": "NRC PS4.A; consensus oceanography; PHIVOLCS hazard guidance", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-energy-can-transform-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "wave energy transforms", "grades": [9, 10], "terms": ["wave energy transform", "enerhiya ng alon nababago", "enerhiya sa balod mabalhin", "wave energy other forms", "init gikan sa sanag", "heat from absorbed light", "nasisipsip na alon", "absorbed wave", "pagbalhin sa enerhiya", "naaabsorb ang alon", "enerhiya nahimong init"], "fact": {"tl": "Tulad ng ibang anyo ng enerhiya, ang enerhiya ng isang alon ay maaaring mabago sa ibang anyo, gaya ng liwanag na nasisipsip ng isang bagay at nagiging init.", "en": "Like any form of energy, the energy of a wave can be changed into other forms, such as light that is absorbed by an object and becomes heat.", "bis": "Sama sa ubang porma sa enerhiya, ang enerhiya sa usa ka balod mahimong mabalhin ngadto sa ubang porma, sama sa kahayag nga masuhop sa usa ka butang ug mahimong init."}, "source": "AAAS Benchmarks 4F/H6c; NRC PS4.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-em-spectrum-order-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "electromagnetic spectrum order", "grades": [9, 10], "terms": ["electromagnetic spectrum", "espektro electromagnetic", "radio waves longest", "gamma rays shortest", "pinakamahabang wavelength radyo", "pinakamubo nga gamma", "uri ng alon electromagnetic", "infrared ultraviolet x-ray", "visible light", "nakikitang liwanag", "han-ay sa espektro"], "fact": {"tl": "Ang electromagnetic spectrum ay may iba't ibang alon na nakaayos ayon sa wavelength: pinakamahaba ang radio wave at pinakamaikli ang gamma ray, at ang nakikitang liwanag ay maliit na bahagi lamang nito.", "en": "The electromagnetic spectrum has many waves arranged by wavelength: radio waves are the longest and gamma rays are the shortest, and visible light is only a small part of it.", "bis": "Ang electromagnetic spectrum adunay lainlaing balod nga gihan-ay sumala sa wavelength: ang radio wave ang pinakataas ug ang gamma ray ang pinakamubo, ug ang makita nga kahayag gamay ra nga bahin niini."}, "source": "AAAS Benchmarks 4F/M8; NRC PS4.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "work-joule-unit-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "the joule as the unit of work and energy", "grades": [8, 9, 10], "terms": ["joule", "yunit ng work", "yunit ng enerhiya", "unit of energy", "newton-meter", "isang joule", "isang newton sa isang metro", "yunit ng trabaho", "sukat ng enerhiya", "gisukod sa joule", "yunit sa kusog", "isukod ang work", "newton metro", "sukod sa enerhiya"], "fact": {"tl": "Ang work at enerhiya ay parehong sinusukat sa yunit na joule (J), at isang joule ang nagagawa kapag isang newton na force ang nagpagalaw ng bagay ng isang metro sa direksyon ng force.", "en": "Work and energy are both measured in a unit called the joule (J), and one joule is done when a force of one newton moves an object one meter in the direction of the force.", "bis": "Ang work ug enerhiya parehas nga gisukod sa yunit nga joule (J), ug usa ka joule ang mabuhat kung usa ka newton nga force makapalihok sa butang og usa ka metro sa direksyon sa force."}, "source": "AAAS BSL Ch.4E; encyclopedia-stable consensus (SI units)", "generator": "claude-workflow", "reviewed": false},
  {"id": "work-force-times-distance-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "work equals force times distance", "grades": [8, 9, 10], "terms": ["work formula", "force times distance", "force beses distance", "work = force x distance", "dami ng work", "halaga ng work", "force ipilit sa distance", "gilay-on", "mas malayo mas maraming work", "mas dako nga force", "kantidad sa work", "pagkalkula sa work", "mas malaki ang force", "mas dakong gilay-on", "kuwenta ng trabaho"], "fact": {"tl": "Ang dami ng work ay katumbas ng force na ginamit beses ang distance na nilakbay sa direksyon ng force, kaya mas malaki ang work kapag mas malakas ang force o mas mahaba ang distance.", "en": "The amount of work equals the force used multiplied by the distance moved in the direction of the force, so the work is greater when the force is stronger or the distance is longer.", "bis": "Ang gidaghanon sa work parehas sa force nga gigamit gipilo sa distance nga gibaktas sa direksyon sa force, mao nga mas dako ang work kung mas kusog ang force o mas taas ang gilay-on."}, "source": "AAAS BSL Ch.4E; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "work-perpendicular-no-work-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "carrying a load level does no work on it", "grades": [8, 9, 10], "terms": ["walang work", "pasan", "buhat sa load", "carrying a load", "force na patayo sa galaw", "perpendicular force", "no work done", "pahalang na paglakad", "walang work sa pasanin", "walay work", "pagdala og bug-at", "pataas nga force", "naglakaw nga patag", "force nga tul-id sa lihok", "hindi gumagawa ng work"], "fact": {"tl": "Kapag bitbit mo ang isang bagay habang naglalakad nang pahalang, hindi ka gumagawa ng work dito dahil ang force pataas na itinataas mo ay patayo sa direksyon ng iyong paggalaw.", "en": "When you carry an object while walking on level ground, you do no work on it because the upward force holding it is perpendicular to your direction of motion.", "bis": "Kung magdala ka og butang samtang naglakaw sa patag, wala kay work nga gibuhat niini tungod kay ang force pataas nga imong gibitbit tul-id ngadto sa direksyon sa imong paglihok."}, "source": "Encyclopedia-stable physics consensus (work as force along displacement)", "generator": "claude-workflow", "reviewed": false},
  {"id": "power-watt-joule-per-second-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "the watt as one joule per second", "grades": [8, 9, 10], "terms": ["watt", "joule kada segundo", "joule per second", "watt yunit ng power", "isang watt", "rate of work", "watt sukat ng power", "enerhiya kada segundo", "joule matag segundo", "yunit sa power", "kilowatt", "watt sa bombilya", "isukod sa watt", "kusog kada segundo", "60 watt na bombilya"], "fact": {"tl": "Ang power ay sinusukat sa watt (W), at isang watt ang katumbas ng isang joule ng enerhiyang ginagamit o ginagawa sa bawat segundo.", "en": "Power is measured in watts (W), and one watt equals one joule of energy used or produced each second.", "bis": "Ang power gisukod sa watt (W), ug usa ka watt parehas sa usa ka joule nga enerhiya nga gigamit o gihimo matag segundo."}, "source": "AAAS BSL Ch.4E; encyclopedia-stable consensus (SI units)", "generator": "claude-workflow", "reviewed": false},
  {"id": "power-work-over-time-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "power equals work divided by time", "grades": [8, 9, 10], "terms": ["power = work / time", "work hatiin sa oras", "work over time", "mas mabilis na work mas malaki ang power", "power formula", "kalkula sa power", "kapareho ang work mas mabilis mas malaki power", "bahin sa oras", "work bahinon sa panahon", "mas paspas mas dako power", "pormula sa power", "gano kabilis matapos", "trabaho hatiin sa panahon", "rate ng paggawa"], "fact": {"tl": "Ang power ay katumbas ng work na nagawa na hinati sa oras na ginugol, kaya kung dalawang makina ang gumagawa ng parehong work, mas malaki ang power ng mas mabilis na natatapos.", "en": "Power equals the work done divided by the time taken, so if two machines do the same work, the one that finishes faster has the greater power.", "bis": "Ang power parehas sa work nga nabuhat bahinon sa oras nga gigamit, mao nga kung duha ka makina maghimo sa parehas nga work, mas dako ang power sa mas paspas nga mahuman."}, "source": "AAAS BSL Ch.4E; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "kinetic-energy-depends-on-speed-squared-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "kinetic energy grows with the square of speed", "grades": [8, 9, 10], "terms": ["kinetic energy", "enerhiya ng paggalaw", "bilis na squared", "speed squared", "doble ang bilis apat na beses energy", "mas mabilis mas malaki kinetic energy", "kusog sa paglihok", "doble ang katulin", "bilis kuwadrado", "mas paspas mas dako kinetic energy", "enerhiya sa paglihok", "doblehon ang bilis", "upat ka pilo nga enerhiya", "kinetic energy ng sasakyan", "masa at bilis"], "fact": {"tl": "Ang kinetic energy ng isang bagay ay nakadepende sa masa at sa parisukat (square) ng bilis nito, kaya kapag doble ang bilis, apat na beses ang kinetic energy — kaya delikado ang mabilis na sasakyan.", "en": "The kinetic energy of an object depends on its mass and on the square of its speed, so doubling the speed makes the kinetic energy four times as large — which is why fast vehicles are so dangerous.", "bis": "Ang kinetic energy sa usa ka butang nagdepende sa masa ug sa kuwadrado sa katulin niini, mao nga kung doblehon ang katulin, upat ka pilo ang kinetic energy — mao nga delikado ang paspas nga sakyanan."}, "source": "Encyclopedia-stable physics consensus (KE = ½mv²)", "generator": "claude-workflow", "reviewed": false},
  {"id": "gravitational-pe-mass-height-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "gravitational potential energy from mass, gravity, and height", "grades": [8, 9, 10], "terms": ["gravitational potential energy", "nakaimbak na enerhiya sa taas", "stored energy height", "masa beses gravity beses taas", "mass gravity height", "mas mabigat mas mataas mas malaki PE", "enerhiyang nakatago dahil sa taas", "potential energy sa kataas", "gibug-aton ug kahabog", "mas bug-at mas hataas mas dako", "natipig nga enerhiya sa kahitas-an", "kusog tungod sa gibtang", "tubig sa dam", "stored energy sa bato sa bundok"], "fact": {"tl": "Ang gravitational potential energy ng isang bagay ay lumalaki kapag mas mabigat ito o mas mataas ang kinalalagyan nito, dahil mas malaki ang enerhiyang nakaimbak para mahulog.", "en": "An object's gravitational potential energy increases when it is heavier or placed higher up, because more energy is stored for it to fall with.", "bis": "Ang gravitational potential energy sa usa ka butang modako kung mas bug-at kini o mas hataas ang gibutangan, tungod kay mas dako ang enerhiya nga natipig aron kini mahulog."}, "source": "AAAS BSL Ch.4E (H7); encyclopedia-stable consensus (PE = mgh)", "generator": "claude-workflow", "reviewed": false},
  {"id": "mechanical-energy-sum-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "mechanical energy as kinetic plus potential", "grades": [8, 9, 10], "terms": ["mechanical energy", "kabuuang kinetic at potential", "kinetic plus potential", "enerhiyang mekanikal", "suma ng kinetic at potential", "mechanical energy ng bagay", "total ng galaw at posisyon", "kombinasyon sa kinetic ug potential", "mekanikal nga enerhiya", "tibuok kinetic ug potential", "enerhiya sa lihok ug posisyon", "kinetic at potential na pinagsama", "swing", "pendulum mechanical energy"], "fact": {"tl": "Ang mechanical energy ng isang bagay ay ang kabuuan ng kinetic energy nito (mula sa paggalaw) at potential energy nito (mula sa posisyon o kondisyon).", "en": "The mechanical energy of an object is the sum of its kinetic energy (from motion) and its potential energy (from position or condition).", "bis": "Ang mechanical energy sa usa ka butang mao ang kinatibuk-an sa kinetic energy niini (gikan sa paglihok) ug potential energy niini (gikan sa posisyon o kahimtang)."}, "source": "Encyclopedia-stable physics consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pendulum-energy-swap-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "energy swaps between potential and kinetic in a pendulum", "grades": [8, 9, 10], "terms": ["pendulum", "swing", "duyan", "potential papuntang kinetic", "energy exchange", "palit-palit ng enerhiya", "taas potential mababa kinetic", "swap of energy", "balhinanay sa enerhiya", "duyan-duyan", "pinakataas pinakamabagal", "pinakamababa pinakamabilis", "kahitas-an potential", "kinetic sa ubos", "pabalik-balik na enerhiya", "transpormasyon ng enerhiya"], "fact": {"tl": "Sa isang umuugoy na pendulum, pinakamalaki ang potential energy sa pinakamataas na punto kung saan ito sandaling tumitigil, at nagiging kinetic energy ito habang bumababa, kaya pinakamabilis ito sa pinakamababang punto.", "en": "In a swinging pendulum, potential energy is greatest at the highest point where it briefly stops, and it turns into kinetic energy as it swings down, so it moves fastest at the lowest point.", "bis": "Sa nagbingbing nga pendulum, pinakadako ang potential energy sa pinakahataas nga bahin diin kini mohunong sa makadiyot, ug mahimo kining kinetic energy samtang manaog, mao nga pinakapaspas kini sa pinakaubos nga bahin."}, "source": "Encyclopedia-stable physics consensus (energy transformation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "falling-object-pe-to-ke-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "a falling object converts potential energy to kinetic energy", "grades": [8, 9, 10], "terms": ["nahuhulog na bagay", "falling object", "potential papuntang kinetic", "pe to ke", "nababawasan ang potential nadadagdagan ang kinetic", "habang bumababa bumibilis", "nahulog nga butang", "potential ngadto sa kinetic", "samtang manaog mopaspas", "mokunhod ang potential modako ang kinetic", "enerhiya sa pagkahulog", "bumibilis habang bumabagsak", "transpormasyon sa pagkahulog", "gravity hatak"], "fact": {"tl": "Habang nahuhulog ang isang bagay, nababawasan ang gravitational potential energy nito at nadadagdagan naman ang kinetic energy nito, kaya mas bumibilis ito hanggang sa tumama sa lupa.", "en": "As an object falls, its gravitational potential energy decreases while its kinetic energy increases, so it speeds up until it hits the ground.", "bis": "Samtang nahulog ang usa ka butang, mokunhod ang gravitational potential energy niini ug modugang ang kinetic energy niini, mao nga mas mopaspas kini hangtod nga motugpa sa yuta."}, "source": "Encyclopedia-stable physics consensus (energy transformation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "conservation-closed-system-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "total energy stays constant in a closed system", "grades": [8, 9, 10], "terms": ["conservation of energy", "saradong sistema", "closed system", "kabuuang enerhiya hindi nagbabago", "total energy constant", "nananatili ang kabuuang enerhiya", "sirado nga sistema", "kinatibuk-ang enerhiya dili mausab", "konserbasyon sa enerhiya", "magpabilin ang enerhiya", "hindi nawawala ang enerhiya", "walay enerhiya nga mawala", "isang lugar bumaba isa tumaas", "balanse ng enerhiya"], "fact": {"tl": "Ayon sa konserbasyon ng enerhiya, sa isang saradong sistema na walang enerhiyang pumapasok o lumalabas, hindi nagbabago ang kabuuang enerhiya — kung bumaba ito sa isang anyo, tataas ito sa iba nang eksaktong kasingdami.", "en": "By the conservation of energy, in a closed system with no energy entering or leaving, the total energy never changes — if it drops in one form, it rises in another by exactly the same amount.", "bis": "Sumala sa konserbasyon sa enerhiya, sa usa ka sirado nga sistema nga walay enerhiya nga mosulod o mogawas, dili mausab ang kinatibuk-ang enerhiya — kung mokunhod kini sa usa ka porma, motaas kini sa lain sa eksakto nga gidaghanon."}, "source": "AAAS BSL Ch.4E; NRC PS3.B; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-cannot-be-created-or-destroyed-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "energy is only transformed, never created or destroyed", "grades": [8, 9, 10], "terms": ["enerhiya hindi nalilikha", "energy not created", "hindi nasisira ang enerhiya", "energy not destroyed", "nababago lang ang anyo", "only changes form", "dili mabuhat ang enerhiya", "dili maguba ang enerhiya", "mausab lang ang porma", "transpormasyon lang", "first law of thermodynamics", "unang batas sa thermodynamics", "anyo lamang ang nagbabago", "porma lang mabag-o"], "fact": {"tl": "Hindi maaaring likhain o sirain ang enerhiya — maaari lamang itong mabago mula sa isang anyo patungo sa iba, na siyang unang batas ng thermodynamics.", "en": "Energy cannot be created or destroyed — it can only be changed from one form into another, which is the first law of thermodynamics.", "bis": "Ang enerhiya dili mahimo o maguba — mahimo lang kini nga usbon gikan sa usa ka porma ngadto sa lain, nga mao ang unang balaod sa thermodynamics."}, "source": "AAAS BSL Ch.4E; encyclopedia-stable consensus (first law of thermodynamics)", "generator": "claude-workflow", "reviewed": false},
  {"id": "efficiency-useful-output-ratio-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "efficiency as the ratio of useful output to total input", "grades": [8, 9, 10], "terms": ["efficiency", "kahusayan", "epektibo", "useful output input", "kapaki-pakinabang na enerhiya", "porsyento ng enerhiya", "ratio sa enerhiya", "mapuslanon nga enerhiya", "kahusay sa makina", "porsyento sa enerhiya", "input at output", "enerhiyang ginamit nang mabuti", "gigamit nga maayo", "bahin sa enerhiya na nagagamit", "efficiency percentage"], "fact": {"tl": "Ang efficiency ng isang makina ay ang bahagi ng enerhiyang ipinasok dito na nagiging kapaki-pakinabang na output, kadalasang ipinapahayag bilang porsyento.", "en": "The efficiency of a machine is the fraction of the energy put into it that becomes useful output, usually expressed as a percentage.", "bis": "Ang efficiency sa usa ka makina mao ang bahin sa enerhiya nga gisulod niini nga mahimong mapuslanon nga output, kasagaran gipakita isip porsyento."}, "source": "Encyclopedia-stable physics/engineering consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "no-machine-100-percent-efficient-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "no machine is perfectly efficient", "grades": [8, 9, 10], "terms": ["walang makinang perpekto", "no perfect machine", "efficiency below 100", "may nasasayang na enerhiya", "wasted energy", "friction at init", "friction and heat", "walay hingpit nga makina", "nausik nga enerhiya", "kuhang init", "friction ug kainit", "dili moabot sa 100", "hindi aabot sa 100 porsyento", "sayang na enerhiya bilang init", "perpetual motion imposible"], "fact": {"tl": "Walang makinang umaabot sa 100 porsyentong efficiency dahil laging may bahagi ng enerhiyang nasasayang bilang init, kadalasan dahil sa friction.", "en": "No machine reaches 100 percent efficiency because some of the energy is always lost as heat, often because of friction.", "bis": "Walay makina nga makaabot sa 100 porsyento nga efficiency tungod kay kanunay adunay bahin sa enerhiya nga mausik isip kainit, kasagaran tungod sa friction."}, "source": "AAAS BSL Ch.4E (H3); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-degrades-to-waste-heat-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "energy transformations spread energy out as waste heat", "grades": [8, 9, 10], "terms": ["waste heat", "init na sayang", "nasasayang na init", "kumakalat na init", "energy spreads out", "mas kaunting magagamit", "nausik nga kainit", "kainit nga mikatag", "mikuyanap nga init", "mas gamay nga magamit", "degradation ng enerhiya", "hindi na magagamit na enerhiya", "dili na magamit nga enerhiya", "dissipated heat", "nawawalang enerhiyang magagamit"], "fact": {"tl": "Sa tuwing nagbabago ang anyo ng enerhiya, may bahaging nagiging init na kumakalat sa palibot, kaya kahit pareho pa rin ang kabuuang enerhiya, mas kaunti na ang maaaring gamitin para sa kapaki-pakinabang na gawain.", "en": "Every time energy changes form, some of it becomes heat that spreads into the surroundings, so even though the total energy is the same, less of it is available to do useful work.", "bis": "Matag higayon nga mausab ang porma sa enerhiya, adunay bahin nga mahimong kainit nga mokatag sa palibot, mao nga bisan parehas gihapon ang kinatibuk-ang enerhiya, mas gamay na ang magamit para sa mapuslanon nga buluhaton."}, "source": "AAAS BSL Ch.4E (M2, H3); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "heat-vs-temperature-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "the difference between heat and temperature", "grades": [8, 9, 10], "terms": ["heat", "init", "temperatura", "temperature", "pagkakaiba ng init at temperatura", "heat is energy", "init ay enerhiya", "temperatura ay sukat ng init", "kalainan sa init ug temperatura", "init enerhiya nga mobalhin", "temperatura sukod sa kainit", "average na enerhiya ng molekula", "average nga enerhiya sa molekula", "dami ng init", "mainit na bagay"], "fact": {"tl": "Ang init (heat) ay ang enerhiyang inililipat mula sa mainit patungong malamig na bagay, samtang ang temperatura ay sukat lamang ng average na enerhiya ng paggalaw ng mga maliliit na particle sa loob ng bagay.", "en": "Heat is the energy transferred from a hotter to a cooler object, while temperature is only a measure of the average motion energy of the tiny particles inside a substance.", "bis": "Ang init (heat) mao ang enerhiya nga gibalhin gikan sa mas init ngadto sa mas bugnaw nga butang, samtang ang temperatura sukod lamang sa average nga enerhiya sa paglihok sa gagmay nga partikulo sulod sa usa ka butang."}, "source": "AAAS BSL Ch.4E; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "heat-flows-hot-to-cold-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "heat always flows from hotter to cooler until equal", "grades": [8, 9, 10], "terms": ["heat flow", "daloy ng init", "init mula mainit patungong malamig", "hot to cold", "hanggang pantay ang temperatura", "thermal equilibrium", "agos sa kainit", "init gikan sa mainit ngadto sa bugnaw", "hangtod managsama ang temperatura", "balanse sa kainit", "hindi malamig ang dumadaloy", "init dili katugnaw ang mobalhin", "patas na init", "pagkapareho ng temperatura"], "fact": {"tl": "Laging dumadaloy ang init mula sa mas mainit patungo sa mas malamig na bagay, at hindi kailanman pabaligtad, hanggang sa magkapareho na ang kanilang temperatura.", "en": "Heat always flows from the hotter object to the cooler one, never the other way, until the two reach the same temperature.", "bis": "Ang init kanunay nga moagos gikan sa mas init ngadto sa mas bugnaw nga butang, ug dili sukad mosukwahi, hangtod nga managsama na ang ilang temperatura."}, "source": "AAAS BSL Ch.4E; encyclopedia-stable consensus (second law of thermodynamics)", "generator": "claude-workflow", "reviewed": false},
  {"id": "thermal-energy-particle-motion-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "thermal energy is the disordered motion of particles", "grades": [8, 9, 10], "terms": ["thermal energy", "enerhiyang termal", "magulong galaw ng molekula", "disordered motion", "init mula sa paggalaw ng particle", "vibrating particles", "termal nga enerhiya", "magubot nga paglihok sa molekula", "init gikan sa paglihok sa partikulo", "nagkurog nga partikulo", "mas mainit mas mabilis galaw", "mas init mas paspas ang lihok", "average kinetic energy", "init sa loob ng bagay"], "fact": {"tl": "Ang thermal energy ng isang bagay ay nasa magulong paggalaw at pag-vibrate ng mga molekula nito, kaya kapag mas mainit ang isang bagay, mas mabilis ang paggalaw ng mga particle sa loob nito.", "en": "The thermal energy of an object lies in the disordered motion and vibration of its molecules, so the hotter an object is, the faster its particles move.", "bis": "Ang thermal energy sa usa ka butang anaa sa magubot nga paglihok ug pagkurog sa mga molekula niini, mao nga kung mas init ang usa ka butang, mas paspas ang paglihok sa mga partikulo sulod niini."}, "source": "AAAS BSL Ch.4E (M4, H7); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "heat-transfer-conduction-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "conduction transfers heat through touching particles", "grades": [8, 9, 10], "terms": ["conduction", "kondaksyon", "init sa pamamagitan ng dikit", "heat through touch", "banggaan ng particle", "kutsara sa mainit na sopas", "kondaksiyon", "init pinaagi sa paghikap", "pagbangga sa partikulo", "kutsara sa init nga sabaw", "metal mabilis magdaloy ng init", "metal paspas mopaagi sa init", "konduktor ng init", "init na dumadaan sa solid"], "fact": {"tl": "Sa conduction, naililipat ang init sa pamamagitan ng paghahawak o pagbabanggaan ng magkakatabing particle, kaya umiinit ang hawak na dulo ng kutsarang nasa loob ng mainit na sopas.", "en": "In conduction, heat is transferred as neighboring particles touch and collide, which is why the handle of a spoon left in hot soup becomes warm.", "bis": "Sa conduction, ang init mabalhin samtang ang magkasikbit nga mga partikulo maghikap ug magbangga, mao nga moinit ang gunitanan sa kutsara nga gibutang sa init nga sabaw."}, "source": "AAAS BSL Ch.4E (M3); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "heat-transfer-convection-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "convection transfers heat by moving fluid", "grades": [8, 9, 10], "terms": ["convection", "kombeksyon", "init sa pamamagitan ng umaagos na likido o gas", "heat by fluid", "mainit na hangin pumapaitaas", "rising warm air", "kombeksiyon", "init pinaagi sa nagaagos nga likido o gas", "init nga hangin mosaka", "pagbukal sa tubig", "kumukulong tubig", "alon sa kainit sa likido", "init nga mosaka manaog ang bugnaw", "pag-agos ng init"], "fact": {"tl": "Sa convection, naililipat ang init kapag umaagos ang mainit na likido o gas — ang mas mainit at magaan na bahagi ay pumapaitaas habang ang mas malamig ay bumababa, gaya ng nangyayari sa kumukulong tubig.", "en": "In convection, heat is carried as a warm fluid moves — the hotter, lighter part rises while the cooler part sinks, as happens in boiling water.", "bis": "Sa convection, ang init mabalhin samtang ang init nga likido o gas moagos — ang mas init ug magaan nga bahin mosaka samtang ang mas bugnaw manaog, sama sa mahitabo sa nagbukal nga tubig."}, "source": "AAAS BSL Ch.4E (M3); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "heat-transfer-radiation-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "radiation transfers heat through empty space", "grades": [8, 9, 10], "terms": ["radiation", "radyasyon", "init sa pamamagitan ng sinag", "heat by radiation", "init ng araw sa kalawakan", "infrared", "init pinaagi sa silaw", "init sa adlaw sa wanang", "walang kailangang medium", "walay kinahanglan nga medium", "init na dumadaan sa walang laman na espasyo", "init nga moagi sa walay sulod nga luna", "init mula sa apoy", "electromagnetic wave init"], "fact": {"tl": "Sa radiation, naililipat ang init sa pamamagitan ng mga alon na maaaring tumawid kahit sa walang laman na espasyo, kaya naaabot tayo ng init ng araw sa kabila ng kalawakan.", "en": "In radiation, heat travels as waves that can cross even empty space, which is how the sun's heat reaches us across the vacuum of space.", "bis": "Sa radiation, ang init mobalhin pinaagi sa mga balud nga makatabok bisan sa walay sulod nga luna, mao nga makaabot kanato ang init sa adlaw bisan latas sa wanang."}, "source": "AAAS BSL Ch.4E (M3, H7); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "specific-heat-water-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "water needs a lot of energy to heat up", "grades": [8, 9, 10], "terms": ["specific heat", "init na kailangan ng tubig", "tubig mabagal uminit", "water slow to heat", "tubig nag-iimbak ng init", "high specific heat", "init nga gikinahanglan sa tubig", "tubig hinay moinit", "tubig nagtipig og init", "mainit pa rin ang dagat sa gabi", "init pa ang dagat sa gabii", "tubig mabagal lumamig", "tubig hinay mobugnaw", "klima dagat"], "fact": {"tl": "Kailangan ng tubig ng maraming enerhiya para tumaas ang temperatura nito, kaya mabagal itong uminit at mabagal ring lumamig — isa itong dahilan kung bakit pinapalamig ng dagat ang init ng panahon sa baybayin.", "en": "Water needs a lot of energy to raise its temperature, so it heats up slowly and cools down slowly — one reason the sea keeps coastal weather milder.", "bis": "Ang tubig nanginahanglan og daghang enerhiya aron motaas ang temperatura niini, mao nga hinay kini moinit ug hinay usab mobugnaw — usa kini ka rason nganong ang dagat magpabugnaw sa panahon sa baybayon."}, "source": "Encyclopedia-stable physics consensus (specific heat capacity of water)", "generator": "claude-workflow", "reviewed": false},
  {"id": "phase-change-energy-no-temp-change-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "melting and boiling absorb energy without raising temperature", "grades": [8, 9, 10], "terms": ["latent heat", "pagkatunaw nangangailangan ng enerhiya", "melting absorbs energy", "init na walang pagbabago ng temperatura", "boiling absorbs heat", "yelo natutunaw constant temperatura", "pagkatunaw nanginahanglan og enerhiya", "init nga walay kausaban sa temperatura", "yelo natunaw pareho ang temperatura", "init nga gisuyop sa pag-init", "enerhiya para sirain ang bono", "enerhiya aron lugson ang molekula", "kumukulong tubig 100 degrees", "pagbabago ng anyo"], "fact": {"tl": "Habang natutunaw ang yelo o kumukulo ang tubig, sumisipsip ito ng init na ginagamit para paghiwalayin ang mga molekula, kaya hindi tumataas ang temperatura habang nagaganap ang pagbabago ng anyo.", "en": "While ice melts or water boils, it absorbs heat that is used to pull its molecules apart, so the temperature stays constant during the change of state.", "bis": "Samtang matunaw ang yelo o magbukal ang tubig, mosuyop kini og init nga gamiton aron bulagon ang mga molekula niini, mao nga dili motaas ang temperatura samtang nagakahitabo ang kausaban sa porma."}, "source": "Encyclopedia-stable physics consensus (latent heat / phase change)", "generator": "claude-workflow", "reviewed": false},
  {"id": "friction-converts-ke-to-heat-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "friction turns motion energy into heat", "grades": [8, 9, 10], "terms": ["friction", "kuskos", "preksyon", "init mula sa kuskos", "friction makes heat", "kinetic energy nagiging init", "umiinit ang preno", "init gikan sa pagkuskos", "kinetic energy mahimong init", "moinit ang preno", "paghagod sa kamot moinit", "kuskusin ang kamay umiinit", "energy na nawawala sa friction", "init sa gulong"], "fact": {"tl": "Kapag nagkikiskisan ang dalawang bagay, ang friction ay nagbabago ng bahagi ng kanilang kinetic energy tungong init, kaya umiinit ang preno ng sasakyan at ang magkakuskos na kamay.", "en": "When two objects rub together, friction turns some of their kinetic energy into heat, which is why a car's brakes and rubbed hands get warm.", "bis": "Kung magkuskos ang duha ka butang, ang friction magbalhin sa pipila ka kinetic energy nila ngadto sa init, mao nga moinit ang preno sa sakyanan ug ang gikuskos nga mga kamot."}, "source": "AAAS BSL Ch.4E (E1); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "chemical-to-mechanical-engine-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "engines change chemical energy into motion and waste heat", "grades": [8, 9, 10], "terms": ["makina ng sasakyan", "engine energy", "chemical energy sa gasolina", "fuel to motion", "chemical patungong mechanical", "init na sayang sa makina", "makina sa sakyanan", "chemical energy sa gasolina", "fuel ngadto sa lihok", "kemikal ngadto sa mekanikal", "nausik nga init sa makina", "karamihan nagiging init", "kadaghanan mahimong init", "kombustyon", "enerhiya ng gasolina"], "fact": {"tl": "Ang makina ng sasakyan ay nagbabago ng chemical energy ng gasolina tungong mechanical energy na nagpapagalaw dito, ngunit malaking bahagi nito ang nasasayang bilang init.", "en": "A car engine changes the chemical energy in fuel into the mechanical energy that moves it, but a large share of it is lost as waste heat.", "bis": "Ang makina sa sakyanan magbalhin sa chemical energy sa gasolina ngadto sa mechanical energy nga magpalihok niini, apan dako nga bahin niini ang mausik isip kainit."}, "source": "AAAS BSL Ch.4E (M2); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "generator-mechanical-to-electrical-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "generators turn mechanical energy into electrical energy", "grades": [8, 9, 10], "terms": ["generator", "henerador", "mechanical patungong electrical", "mechanical to electrical", "umiikot na magnet bumubuo ng kuryente", "spinning turbine", "henerador sa kuryente", "mekanikal ngadto sa elektrikal", "nagtuyok nga magnet maghimo og kuryente", "turbine nga nagtuyok", "enerhiya ng paggalaw nagiging kuryente", "lihok mahimong elektrisidad", "elektromagnetikong induksyon", "planta ng kuryente"], "fact": {"tl": "Ang generator ay nagbabago ng mechanical energy ng umiikot na turbine tungong electrical energy sa pamamagitan ng pagpapaikot ng magnet malapit sa mga kawad.", "en": "A generator changes the mechanical energy of a spinning turbine into electrical energy by turning a magnet near coils of wire.", "bis": "Ang generator magbalhin sa mechanical energy sa nagtuyok nga turbine ngadto sa electrical energy pinaagi sa pagtuyok sa magnet duol sa mga koil sa alambre."}, "source": "AAAS BSL Ch.4E; encyclopedia-stable consensus (electromagnetic induction)", "generator": "claude-workflow", "reviewed": false},
  {"id": "energy-source-traced-back-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "tracing an energy chain back to its source", "grades": [8, 9, 10], "terms": ["energy chain", "pinagmulan ng enerhiya", "enerhiya mula sa araw", "energy from sun", "kadena ng enerhiya", "tunton sa enerhiya", "gigikanan sa enerhiya", "enerhiya gikan sa adlaw", "kutob sa pagkaon hangtod sa araw", "pagkain galing sa araw", "pagkaon gikan sa adlaw", "transpormasyon ng enerhiya sunod-sunod", "serye ng enerhiya", "fosil na panggatong"], "fact": {"tl": "Maaaring tunton ang bawat anyo ng enerhiya pabalik sa pinagmulan nito sa pamamagitan ng serye ng mga transpormasyon — halimbawa, ang enerhiya sa iyong pagkilos ay galing sa pagkain, na galing naman sa enerhiya ng araw.", "en": "Every form of energy can be traced back to its source through a chain of transformations — for example, the energy in your movement comes from food, which in turn came from the sun's energy.", "bis": "Ang matag porma sa enerhiya matultolan balik sa gigikanan niini pinaagi sa sunod-sunod nga mga transpormasyon — pananglitan, ang enerhiya sa imong paglihok gikan sa pagkaon, nga gikan usab sa enerhiya sa adlaw."}, "source": "AAAS BSL Ch.4E (M2); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "second-law-energy-quality-g10", "domain": "FORCE_MOTION_ENERGY", "topic": "useful energy decreases as it spreads out", "grades": [9, 10], "terms": ["second law of thermodynamics", "ikalawang batas ng thermodynamics", "kalidad ng enerhiya bumababa", "energy quality falls", "enerhiya kumakalat nang pantay", "less useful energy", "ikaduhang balaod sa thermodynamics", "kalidad sa enerhiya mokunhod", "enerhiya mokatag og patas", "mas gamay nga mapuslanon", "entropy", "enerhiyang nakakalat hindi na magagamit", "enerhiya nga mikatag dili na magamit", "konsentrado patungong kalat"], "fact": {"tl": "Bagaman hindi nababawasan ang kabuuang enerhiya, sa bawat transpormasyon ay kumakalat ito nang mas pantay-pantay, kaya unti-unting bumababa ang dami ng enerhiyang maaaring gamitin para sa kapaki-pakinabang na gawain.", "en": "Although the total amount of energy never decreases, in each transformation it spreads out more evenly, so the amount of energy available for useful work steadily declines.", "bis": "Bisan dili mokunhod ang kinatibuk-ang enerhiya, sa matag transpormasyon mokatag kini og mas patas, mao nga hinay-hinay nga mokunhod ang gidaghanon sa enerhiya nga magamit para sa mapuslanon nga buluhaton."}, "source": "AAAS BSL Ch.4E (H2, H3); encyclopedia-stable consensus (second law of thermodynamics)", "generator": "claude-workflow", "reviewed": false},
  {"id": "machine-trades-force-not-work-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "machines trade force for distance but conserve work", "grades": [8, 9, 10], "terms": ["mechanical advantage", "makina nagpapagaan", "kapalit ng force ay distance", "trade force for distance", "kabuuang work pareho", "work conserved", "makina magpasayon", "baylo sa force kay distance", "kinatibuk-ang work parehas", "mas gamay nga force mas taas nga gilay-on", "mas kaunting force mas mahabang distance", "palanca polea ramp", "leverage", "mas magaan ngunit mas mahaba"], "fact": {"tl": "Ang isang makina tulad ng palanca o polea ay maaaring magbawas ng force na kailangan, ngunit ipinapalit nito ito sa mas mahabang distance, kaya halos pareho pa rin ang kabuuang work na nagagawa.", "en": "A machine such as a lever or pulley can reduce the force you need, but it trades this for a longer distance, so the total work done stays about the same.", "bis": "Ang usa ka makina sama sa palanca o polea makapakunhod sa force nga gikinahanglan, apan ibaylo niini kini sa mas taas nga gilay-on, mao nga halos parehas gihapon ang kinatibuk-ang work nga mabuhat."}, "source": "AAAS BSL Ch.4E; encyclopedia-stable consensus (conservation of work)", "generator": "claude-workflow", "reviewed": false},
  {"id": "power-output-human-vs-machine-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "same work done with more power in less time", "grades": [8, 9, 10], "terms": ["power output", "parehong work iba ang power", "mas mabilis mas malaki power", "more power less time", "pataas ng hagdan mabilis vs mabagal", "running up stairs power", "parehas nga work lahi ang power", "mas paspas mas dako power", "pagtungas sa hagdan paspas vs hinay", "dagan sa hagdanan power", "kapareho ng enerhiya iba ang oras", "managsama nga enerhiya lahi ang oras", "atletang malakas ang power"], "fact": {"tl": "Kung dalawang tao ang umakyat ng parehong hagdan, pareho lang ang work na nagawa nila, ngunit mas malaki ang power ng tumakbo pataas dahil ginawa niya ang parehong work sa mas maikling panahon.", "en": "If two people climb the same staircase, they do the same amount of work, but the one who runs up has greater power because they did that same work in less time.", "bis": "Kung duha ka tawo mosaka sa parehas nga hagdanan, parehas ra ang work nga ilang nabuhat, apan mas dako ang power sa midagan pataas tungod kay iyang gibuhat ang parehas nga work sa mas mubo nga panahon."}, "source": "AAAS BSL Ch.4E; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "aurora-magnetic-poles-g8", "domain": "EARTH_SPACE", "topic": "why auroras appear near the poles", "grades": [7, 8, 9], "terms": ["aurora", "poles", "poste", "magnetic", "magnet", "Earth", "mundo", "magnetic field", "field", "akit", "north", "south", "hilaga", "timog", "particles", "gabay", "gihatud", "oval"], "fact": {"tl": "Lumalabas ang aurora malapit sa magnetic poles dahil ginagabay ng magnetic field ng Earth ang mga particle mula sa araw papunta sa hilaga at timog na bahagi ng mundo.", "en": "Auroras appear near the magnetic poles because Earth's magnetic field guides the particles from the Sun toward the far north and far south.", "bis": "Mogawas ang aurora duol sa magnetic poles tungod kay ang magnetic field sa Yuta naggiya sa mga partikulo gikan sa adlaw padulong sa amihanan ug habagatan nga bahin sa kalibutan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "aurora-height-altitude-g8", "domain": "EARTH_SPACE", "topic": "how high up auroras happen", "grades": [7, 8, 9], "terms": ["aurora", "height", "taas", "altitude", "kilometers", "kilometro", "atmosphere", "atmospera", "high", "mataas", "langit", "upper air", "babaw", "layo", "ulo"], "fact": {"tl": "Nangyayari ang aurora nang napakataas — mga 100 hanggang 300 kilometro sa itaas ng lupa — kaya mas mataas pa ito kaysa sa lumilipad na eroplano.", "en": "Auroras happen very high up — about 100 to 300 kilometers above the ground — much higher than any flying airplane.", "bis": "Ang aurora mahitabo sa hilabihan ka taas — mga 100 ngadto sa 300 ka kilometro ibabaw sa yuta — mas taas pa kini kaysa sa naglupad nga eroplano."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "geyser-old-faithful-g6", "domain": "EARTH_SPACE", "topic": "geysers erupt on a schedule", "grades": [5, 6, 7], "terms": ["geyser", "Old Faithful", "erupt", "pumutok", "sumisirit", "schedule", "oras", "regular", "init", "mainit", "tubig", "singaw", "steam", "spring", "bukal", "balik-balik", "tumataas"], "fact": {"tl": "May mga geyser na sumisirit nang paulit-ulit sa halos parehong oras, gaya ng sikat na 'Old Faithful' sa Amerika na pumuputok kada ilang minuto dahil paulit-ulit kumukulo ang tubig sa ilalim.", "en": "Some geysers erupt over and over at almost regular times, like the famous 'Old Faithful' in America that bursts every so often because the underground water keeps reboiling.", "bis": "Adunay mga geyser nga mosirit balik-balik sa halos parehong oras, sama sa bantogang 'Old Faithful' sa Amerika nga mobuto kada pipila ka minuto tungod kay balik-balik nga mobukal ang tubig sa ilalom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hot-spring-minerals-color-g6", "domain": "EARTH_SPACE", "topic": "why hot springs have colorful water", "grades": [5, 6, 7], "terms": ["hot spring", "mainit na bukal", "colors", "kulay", "minerals", "mineral", "bacteria", "asupre", "sulfur", "amoy", "baho", "tubig", "dilaw", "asul", "langhap", "init"], "fact": {"tl": "Minsan makulay ang tubig sa hot spring — dilaw, kahel, o asul — dahil sa mga mineral at maliliit na bakterya na nakatira sa napakainit na tubig.", "en": "Hot spring water is sometimes brightly colored — yellow, orange, or blue — because of minerals and tiny bacteria living in the very hot water.", "bis": "Usahay mabulukon ang tubig sa hot spring — dalag, kahil, o asul — tungod sa mga mineral ug gagmay nga bakterya nga nagpuyo sa init kaayo nga tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bioluminescence-sea-sparkle-g5", "domain": "LIVING_THINGS", "topic": "glowing waves at night", "grades": [4, 5, 6], "terms": ["bioluminescence", "glow", "ningning", "kumikinang", "plankton", "waves", "alon", "gabi", "dagat", "sea", "sumisigaw", "asul", "blue", "kumikislap", "baybayon", "tubig", "kidlap"], "fact": {"tl": "Kapag kumikinang ang mga alon na asul tuwing gabi, ito ay dahil sa napakaliit na plankton sa tubig na nagbibigay-liwanag (bioluminescence) kapag nagagalaw ang tubig.", "en": "When ocean waves glow blue at night, it is because of tiny plankton in the water that give off light (bioluminescence) when the water is stirred.", "bis": "Kung mosidlak og asul ang mga balod panahon sa gabii, kini tungod sa gagmay kaayo nga plankton sa tubig nga mohatag og kahayag (bioluminescence) kung makutaw ang tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bioluminescence-cold-light-g6", "domain": "LIVING_THINGS", "topic": "living light makes no heat", "grades": [5, 6, 7], "terms": ["bioluminescence", "cold light", "malamig", "liwanag", "light", "init", "heat", "walang", "alitaptap", "firefly", "chemical", "kemikal", "enerhiya", "ningas", "walang init", "kislap"], "fact": {"tl": "Ang liwanag ng mga nilalang gaya ng alitaptap ay tinatawag na 'malamig na liwanag' dahil halos walang init itong inilalabas — kabaligtaran ng mainit na bombilya.", "en": "The light made by living things like fireflies is called 'cold light' because it gives off almost no heat — unlike a hot light bulb.", "bis": "Ang kahayag nga gibuhat sa mga buhing butang sama sa aninipot gitawag og 'bugnaw nga kahayag' tungod kay halos walay init nga gigawas niini — sukwahi sa init nga bombilya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tornado-funnel-spin-g5", "domain": "EARTH_SPACE", "topic": "why a tornado spins into a funnel", "grades": [4, 5, 6], "terms": ["tornado", "buhawi", "ipo-ipo", "spin", "umiikot", "funnel", "hugis", "wind", "hangin", "ulap", "cloud", "storm", "bagyo", "umaakyat", "umangat", "umiikot na hangin"], "fact": {"tl": "Ang tornado (buhawi) ay umiikot na haligi ng hangin na nakadikit sa ulap pababa sa lupa, na nabubuo kapag may mabilis na umiikot na hangin sa loob ng malakas na bagyo.", "en": "A tornado is a spinning column of air reaching from a cloud down to the ground, formed when fast spinning winds build up inside a strong storm.", "bis": "Ang tornado (alimpulos) usa ka nagtuyok nga haligi sa hangin nga gikan sa panganod paubos sa yuta, nga maporma kung adunay paspas nga nagtuyok nga hangin sulod sa kusog nga bagyo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "waterspout-over-water-g6", "domain": "EARTH_SPACE", "topic": "waterspouts are tornadoes over water", "grades": [5, 6, 7], "terms": ["waterspout", "ipo-ipo sa tubig", "buhawi sa tubig", "tornado", "water", "tubig", "dagat", "sea", "lake", "lawa", "spinning", "umiikot", "Pilipinas", "Philippines", "alon", "hangin"], "fact": {"tl": "Ang waterspout ay parang tornado na nabubuo sa ibabaw ng dagat o lawa, at minsan ito ay nakikita rin sa karagatan ng Pilipinas tuwing maulan na panahon.", "en": "A waterspout is like a tornado that forms over the sea or a lake, and it is sometimes seen over Philippine waters during rainy weather.", "bis": "Ang waterspout sama sa tornado nga maporma ibabaw sa dagat o lanaw, ug usahay makita usab kini sa kadagatan sa Pilipinas panahon sa ting-ulan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tornado-fastest-wind-g7", "domain": "EARTH_SPACE", "topic": "tornadoes have the fastest winds", "grades": [6, 7, 8], "terms": ["tornado", "buhawi", "fastest wind", "mabilis", "hangin", "wind speed", "bilis", "strong", "malakas", "damage", "sira", "umaalsa", "tumitilapon", "kotse", "bubong", "lakas"], "fact": {"tl": "Ang hangin sa loob ng isang malakas na tornado ang isa sa pinakamabilis sa Earth — kaya nitong itaas ang mga kotse at bubong, kahit hindi ito kasinglaki ng buong bagyo.", "en": "The wind inside a strong tornado is among the fastest on Earth — it can lift cars and roofs, even though a tornado is much smaller than a whole storm.", "bis": "Ang hangin sulod sa kusog nga tornado usa sa pinakapaspas sa Yuta — makahimo kini sa pag-alsa sa mga sakyanan ug atop, bisan pa nga mas gamay kini kaysa sa tibuok bagyo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sinkhole-karst-philippines-g7", "domain": "EARTH_SPACE", "topic": "sinkholes and Philippine limestone", "grades": [6, 7, 8], "terms": ["sinkhole", "langib", "lungib", "limestone", "apog", "karst", "Bohol", "Philippines", "Pilipinas", "cave", "kweba", "tubig", "dissolve", "natutunaw", "butas", "biglang", "guho"], "fact": {"tl": "Maraming sinkhole at kweba sa mga lugar na batong-apog (limestone) gaya ng Bohol, dahil unti-unting tinutunaw ng tubig ang bato sa ilalim ng lupa.", "en": "Many sinkholes and caves form in limestone areas like Bohol, because water slowly dissolves the rock beneath the ground.", "bis": "Daghang sinkhole ug langub ang maporma sa mga dapit nga apog nga bato (limestone) sama sa Bohol, tungod kay hinay-hinay nga gitunaw sa tubig ang bato sa ilalom sa yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "quicksand-not-sink-g6", "domain": "MATTER", "topic": "you cannot fully sink in quicksand", "grades": [5, 6, 7], "terms": ["quicksand", "kumunoy", "sink", "lumubog", "sand", "buhangin", "water", "tubig", "float", "lumulutang", "trapped", "naiipit", "dense", "makapal", "tao", "lumubog", "ipit"], "fact": {"tl": "Hindi ka talaga buong lumulubog sa quicksand (kumunoy) — ito ay buhangin na puno ng tubig, at dahil mas makapal ito kaysa sa tao, lumulutang ka pataas kung kaya kang magpakalma at hindi magpupumiglas.", "en": "You do not fully sink in quicksand — it is sand full of water, and because it is denser than a person, you actually float and can escape if you stay calm.", "bis": "Dili ka gyud bug-os nga molunod sa quicksand (kumunoy) — kini balas nga puno sa tubig, ug tungod kay mas baga kini kaysa tawo, molutaw ka pataas ug makaikyas kung magpakalma ka."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "quicksand-how-forms-g6", "domain": "MATTER", "topic": "how quicksand forms", "grades": [5, 6, 7], "terms": ["quicksand", "kumunoy", "forms", "nabubuo", "water", "tubig", "sand", "buhangin", "spring", "bukal", "ilalim", "loose", "maluwag", "umaapaw", "tumatagas", "basa", "malambot"], "fact": {"tl": "Nabubuo ang quicksand kapag may tubig na umaapaw sa ilalim ng buhangin, kaya nawawalan ng tigas ang buhangin at nagiging malambot at madulas na parang putik.", "en": "Quicksand forms when water seeps up through sand, so the sand loses its firmness and becomes soft and slippery like mud.", "bis": "Maporma ang quicksand kung adunay tubig nga moawas gikan sa ilalom sa balas, mao nga mawad-an og katig-a ang balas ug mahimong humok ug danlog sama sa lapok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mirage-bending-light-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "why mirages look like water", "grades": [6, 7, 8], "terms": ["mirage", "malikmata", "milagro sa init", "water", "tubig", "road", "kalsada", "hot", "mainit", "light", "liwanag", "bends", "yumuyuko", "baluktot", "sky", "langit", "reflection", "tila tubig", "init"], "fact": {"tl": "Ang malikmata (mirage) sa mainit na kalsada ay parang tubig dahil ang liwanag mula sa langit ay yumuyuko (nababaluktot) habang dumadaan sa napakainit na hangin malapit sa lupa.", "en": "A mirage on a hot road looks like water because light from the sky bends as it passes through the very hot air near the ground.", "bis": "Ang mirage sa init nga dalan murag tubig tungod kay ang kahayag gikan sa langit mobaliko samtang moagi sa init kaayo nga hangin duol sa yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mirage-desert-not-real-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "a mirage is real light not imagination", "grades": [5, 6, 7], "terms": ["mirage", "malikmata", "desert", "disyerto", "not imagination", "totoo", "real", "liwanag", "light", "camera", "kamera", "tubig", "optical", "trick", "ilusyon", "makikita", "kuha"], "fact": {"tl": "Ang mirage ay hindi gawa-gawa ng isip — ito ay tunay na liwanag na nababaluktot, kaya kahit ang kamera ay makakakuha nito.", "en": "A mirage is not made up by the mind — it is real bent light, so even a camera can photograph it.", "bis": "Ang mirage dili imahinasyon lamang sa hunahuna — kini tinuod nga kahayag nga nabaliko, mao nga bisan ang kamera makakuha niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fog-vs-mist-difference-g6", "domain": "EARTH_SPACE", "topic": "difference between fog and mist", "grades": [5, 6, 7], "terms": ["fog", "ulap sa lupa", "hamog", "mist", "ambon", "manipis", "difference", "pagkakaiba", "thick", "makapal", "visibility", "tanaw", "tingnan", "droplets", "patak", "tubig", "mas makapal"], "fact": {"tl": "Pareho ang fog at mist na gawa sa maliliit na patak ng tubig sa hangin, ngunit mas makapal ang fog kaya mas mahirap makakita kaysa sa manipis na mist.", "en": "Fog and mist are both made of tiny water droplets in the air, but fog is thicker so it is harder to see through than the thinner mist.", "bis": "Ang fog ug mist parehong hinimo sa gagmay nga tinulo sa tubig sa hangin, apan mas baga ang fog mao nga mas lisod makakita kaysa sa nipis nga mist."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fog-mountain-baguio-g5", "domain": "EARTH_SPACE", "topic": "why mountains like Baguio are foggy", "grades": [4, 5, 6], "terms": ["fog", "hamog", "ulap", "Baguio", "mountain", "bundok", "cool", "malamig", "cloud", "ulap", "mataas", "high", "Philippines", "Pilipinas", "lamig", "tingnan", "makapal na ulap"], "fact": {"tl": "Malimit may hamog sa matataas na lugar gaya ng Baguio dahil malamig doon, kaya ang singaw ng tubig sa hangin ay madaling maging maliliit na patak na parang ulap sa lupa.", "en": "High places like Baguio are often foggy because it is cool there, so water vapor in the air easily turns into tiny droplets like a cloud on the ground.", "bis": "Kanunay adunay gabon sa taas nga mga dapit sama sa Baguio tungod kay bugnaw didto, mao nga ang alisngaw sa tubig sa hangin dali nga mahimong gagmay nga tinulo sama sa panganod sa yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ball-lightning-mystery-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "ball lightning is a rare mystery", "grades": [6, 7, 8], "terms": ["ball lightning", "bolang kidlat", "kidlat", "lightning", "glowing ball", "bola", "liwanag", "rare", "bihira", "storm", "bagyo", "unyog", "scientist", "siyentipiko", "misteryo", "mystery", "lumulutang", "gumagalaw"], "fact": {"tl": "Ang ball lightning ay isang bihirang lumulutang na bolang liwanag na minsang nakikita tuwing may bagyo — napakabihira nito kaya hindi pa lubos na nauunawaan ng mga siyentipiko kung paano ito nabubuo.", "en": "Ball lightning is a rare floating ball of light sometimes seen during thunderstorms — it is so uncommon that scientists still do not fully understand how it forms.", "bis": "Ang ball lightning usa ka talagsaon nga naglutaw nga bola sa kahayag nga usahay makita panahon sa bagyo — talagsaon kaayo kini mao nga wala pa hingpit nga masabti sa mga siyentipiko kung giunsa kini pagporma."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "aurora-sound-myth-g8", "domain": "EARTH_SPACE", "topic": "can you hear an aurora", "grades": [7, 8, 9], "terms": ["aurora", "sound", "tunog", "hear", "marinig", "silent", "tahimik", "light", "liwanag", "high", "mataas", "atmosphere", "walang tunog", "langit", "crackle", "ingay"], "fact": {"tl": "Karaniwang tahimik ang aurora dahil nangyayari ito nang napakataas kung saan napakanipis ng hangin para magdala ng tunog, kahit may mga taong nag-ulat ng banayad na tunog.", "en": "An aurora is usually silent because it happens so high up where the air is too thin to carry sound, though a few people report faint noises.", "bis": "Kasagaran hilom ang aurora tungod kay mahitabo kini sa hilabihan ka taas diin nipis kaayo ang hangin aron magdala og tingog, bisan adunay pipila ka tawo nga nag-report og hinay nga tingog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "geyser-geothermal-energy-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "hot underground water makes electricity", "grades": [7, 8, 9], "terms": ["geothermal", "init sa lupa", "geothermal energy", "hot spring", "mainit", "steam", "singaw", "electricity", "kuryente", "power plant", "planta", "Philippines", "Pilipinas", "Tiwi", "Makban", "enerhiya", "lindol na init"], "fact": {"tl": "Ginagamit ng Pilipinas ang init ng tubig sa ilalim ng lupa (geothermal) para gumawa ng kuryente — ang singaw nito ay nagpapaikot ng makina sa mga power plant.", "en": "The Philippines uses the heat of underground water (geothermal) to make electricity — its steam spins machines in power plants.", "bis": "Gigamit sa Pilipinas ang init sa tubig sa ilalom sa yuta (geothermal) aron makahimo og kuryente — ang alisngaw niini magpalihok sa mga makina sa power plant."}, "source": "encyclopedia-stable consensus; DepEd G6 Earth and Space", "generator": "claude-workflow", "reviewed": false},
  {"id": "bioluminescence-anglerfish-lure-g6", "domain": "LIVING_THINGS", "topic": "anglerfish glowing lure", "grades": [5, 6, 7], "terms": ["anglerfish", "bioluminescence", "glow", "liwanag", "ningning", "lure", "pain", "fishing", "deep sea", "kailaliman", "dagat", "dark", "madilim", "trap", "bitag", "isda", "pang-akit", "ilaw"], "fact": {"tl": "May isda sa madilim na kailaliman ng dagat na tinatawag na anglerfish na may nakabiting kumikinang na 'pain' sa ulo, na ginagamit nito para akitin at hulihin ang ibang maliliit na isda.", "en": "A deep sea fish called the anglerfish has a glowing 'lure' dangling over its head, which it uses to attract and catch smaller fish in the dark.", "bis": "Adunay isda sa ngitngit nga kahiladman sa dagat nga gitawag og anglerfish nga adunay nagsidlak nga 'paon' nga nagbitay sa ulo niini, gamiton aron danihon ug dakpon ang gagmay nga isda sa kangitngit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tornado-alley-not-philippines-g7", "domain": "EARTH_SPACE", "topic": "why tornadoes are rare in the Philippines", "grades": [6, 7, 8], "terms": ["tornado", "buhawi", "ipo-ipo", "Philippines", "Pilipinas", "rare", "bihira", "Tornado Alley", "America", "Amerika", "typhoon", "bagyo", "flat land", "kapatagan", "malamig at mainit", "banggaan ng hangin"], "fact": {"tl": "Bihira ang malalaking tornado sa Pilipinas; mas madalas itong nangyayari sa malalawak na kapatagan ng Amerika kung saan nagbabanggaan ang malamig at mainit na malalaking masa ng hangin.", "en": "Big tornadoes are rare in the Philippines; they happen more often in the wide plains of America where large cold and warm air masses collide.", "bis": "Talagsaon ang dagkong tornado sa Pilipinas; mas kanunay kini mahitabo sa lapad nga kapatagan sa Amerika diin magbangga ang dagkong bugnaw ug init nga masa sa hangin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hot-spring-bathing-safety-g5", "domain": "EARTH_SPACE", "topic": "why some hot springs are too hot", "grades": [4, 5, 6], "terms": ["hot spring", "mainit na bukal", "init", "hot", "boiling", "kumukulo", "volcano", "bulkan", "magma", "bato", "danger", "delikado", "mainit-init", "pampaligo", "tubig", "init na lupa"], "fact": {"tl": "May mga hot spring na komportableng pampaligo, ngunit ang iba ay sobrang init — halos kumukulo — dahil pinaiinit ito ng napakainit na bato malapit sa bulkan.", "en": "Some hot springs are comfortable for bathing, but others are dangerously hot — nearly boiling — because they are heated by very hot rock near a volcano.", "bis": "Adunay mga hot spring nga komportable kaligoan, apan ang uban init kaayo — hapit mobukal — tungod kay gipainit kini sa init kaayo nga bato duol sa bulkan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "aurora-solar-wind-source-g8", "domain": "EARTH_SPACE", "topic": "the Sun's particles cause auroras", "grades": [7, 8, 9], "terms": ["aurora", "solar wind", "hanging araw", "particle", "araw", "Sun", "charged", "kuryente", "storm", "solar storm", "sigwa ng araw", "sun storm", "brighter", "mas maliwanag", "langit", "tinik ng araw"], "fact": {"tl": "Kapag may malakas na 'sigwa' sa araw na nagpapalabas ng maraming particle (solar wind), mas malaki at mas maliwanag ang aurora na lumalabas sa langit ng mga lugar malapit sa pole.", "en": "When the Sun has a strong 'storm' that releases many particles (solar wind), the aurora in the sky near the poles becomes bigger and brighter.", "bis": "Kung adunay kusog nga 'bagyo' sa adlaw nga mogawas og daghang partikulo (solar wind), mas dako ug mas hayag ang aurora nga mogawas sa langit sa mga dapit duol sa poste."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fog-flashlight-beam-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "why headlights look hazy in fog", "grades": [4, 5, 6], "terms": ["fog", "hamog", "ulap", "headlight", "ilaw ng sasakyan", "flashlight", "liwanag", "scatter", "kumakalat", "droplets", "patak", "gabi", "night", "sinag", "beam", "makikita", "nagkakalat"], "fact": {"tl": "Sa makapal na hamog, makikita mo ang sinag ng ilaw ng sasakyan dahil ang liwanag ay kumakalat (tumatalbog) sa milyun-milyong maliliit na patak ng tubig sa hangin.", "en": "In thick fog you can see a car's light beam because the light scatters off the millions of tiny water droplets floating in the air.", "bis": "Sa baga nga gabon, makita nimo ang silaw sa suga sa sakyanan tungod kay ang kahayag mokatag (mosumbalik) sa minilyon nga gagmay nga tinulo sa tubig nga naglutaw sa hangin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sinkhole-warning-signs-g7", "domain": "EARTH_SPACE", "topic": "sinkholes can appear suddenly", "grades": [6, 7, 8], "terms": ["sinkhole", "langib", "butas", "sudden", "biglaan", "collapse", "gumuho", "ground", "lupa", "crack", "bitak", "road", "kalsada", "building", "gusali", "babala", "warning", "biglang lubog"], "fact": {"tl": "Minsan biglang lumilitaw ang sinkhole sa ilalim ng kalsada o bahay nang walang babala, dahil ang lupa sa itaas ay matagal nang humuhukay paloob bago tuluyang gumuho.", "en": "A sinkhole can suddenly appear under a road or house with no warning, because the ground above has been quietly hollowing out for a long time before it finally collapses.", "bis": "Usahay kalit nga motungha ang sinkhole ilalom sa dalan o balay nga walay pasidaan, tungod kay ang yuta sa ibabaw dugay na nga naghaw-as sa sulod sa wala pa kini hingpit nga matumpag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mist-waterfall-rainbow-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "rainbows in waterfall mist", "grades": [5, 6, 7], "terms": ["mist", "ambon", "talon", "waterfall", "rainbow", "bahaghari", "spray", "tilamsik", "patak", "droplets", "sunlight", "sikat ng araw", "liwanag", "kulay", "sun", "tubig na ulap", "bahaghari sa talon"], "fact": {"tl": "Madalas may bahaghari sa ambon ng talon kapag maaraw, dahil hinahati ng maliliit na patak ng tubig ang puting liwanag ng araw sa iba't ibang kulay.", "en": "Waterfalls often show a rainbow in their mist on sunny days, because the tiny water droplets split the white sunlight into its colors.", "bis": "Kanunay adunay balangaw sa yamog sa busay kung maadlaw, tungod kay ang gagmay nga tinulo sa tubig mobahin sa puti nga kahayag sa adlaw ngadto sa nagkalainlaing kolor."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bioluminescence-firefly-signal-g5", "domain": "LIVING_THINGS", "topic": "why fireflies blink", "grades": [4, 5, 6], "terms": ["firefly", "alitaptap", "aninipot", "blink", "kumikislap", "kurap", "glow", "liwanag", "mate", "kapareha", "signal", "hudyat", "gabi", "night", "pattern", "panata", "kislap", "tiyan"], "fact": {"tl": "Kumikislap ang alitaptap gamit ang ilaw sa tiyan nito bilang hudyat para makahanap ng kapareha — may sariling 'pattern' ng pagkislap ang bawat uri.", "en": "A firefly blinks the light in its belly as a signal to find a mate — each kind has its own blinking pattern.", "bis": "Mokurap ang aninipot gamit ang suga sa tiyan niini isip senyas aron makakita og kapares — ang matag matang adunay kaugalingong sumbanan sa pagkurap."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "internet-data-travels-in-packets-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "internet messages travel in small packets", "grades": [6, 7, 8], "terms": ["internet", "packet", "packets", "mga piraso ng datos", "hinati-hati", "pinaghihiwalay", "mensahe", "data", "pinadala", "gibahinbahin", "gagmay nga bahin", "datos", "router", "network", "send", "reassemble", "pinagsama-sama uli"], "fact": {"tl": "Kapag nagpadala ka ng larawan o mensahe sa internet, hindi ito buong dumadaan — pinaghihiwalay ito sa maraming maliliit na piraso na tinatawag na packets, na maaaring mag-iba-iba ng daan, at pinagsasama-sama uli sa dulo upang mabuo ang orihinal.", "en": "When you send a picture or message over the internet, it does not travel in one piece — it is split into many tiny chunks called packets that may take different paths and are reassembled at the other end.", "bis": "Kung magpadala ka ug litrato o mensahe sa internet, dili kini molabay nga tibuok — gibahinbahin kini sa daghang gagmay nga bahin nga gitawag ug packets, nga mahimong magkalainlain ug agianan, ug gisumpay-sumpay balik sa tumoy aron mabalik ang orihinal."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "internet-undersea-cables-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "the internet runs through undersea cables", "grades": [6, 7, 8], "terms": ["internet", "submarine cable", "undersea cable", "kable sa ilalim ng dagat", "ilalim ng karagatan", "kabel sa ilalom sa dagat", "fiber optic", "ilaw", "liwanag", "kahawig sa baga", "satellite", "trans-oceanic", "kable", "wires under the ocean", "tubo ng salamin", "light pulses"], "fact": {"tl": "Karamihan sa internet na umaabot sa ibang bansa ay hindi dumadaan sa satellite kundi sa makakapal na kable na nakahimlay sa ilalim ng karagatan, kung saan dumadaloy ang impormasyon bilang mabilis na kislap ng liwanag.", "en": "Most of the internet that reaches other countries does not go through satellites but through thick cables resting on the ocean floor, where information travels as fast flashes of light.", "bis": "Kadaghanan sa internet nga moabot sa ubang nasod dili moagi sa satellite kondili sa baga nga mga kable nga naghigda sa ilalom sa dagat, diin ang impormasyon mobiyahe isip kusog nga pangidlap sa kahayag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gps-needs-four-satellites-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "GPS finds your location using satellites", "grades": [6, 7, 8], "terms": ["GPS", "Global Positioning System", "satellite", "satelayt", "lokasyon", "kinaroroonan", "nahimutangan", "lugar", "apat na satellite", "upat ka satellite", "distansya", "layo", "signal", "tatlong satellite", "location", "navigation", "mapa", "panahon ng biyahe ng signal"], "fact": {"tl": "Ang GPS sa telepono ay nalalaman kung nasaan ka dahil nakikinig ito sa hudyat ng ilang satellite sa langit at sinusukat kung gaano katagal dumating ang bawat hudyat — kailangan ng kahit apat na satellite para tumpak.", "en": "The GPS in a phone knows where you are because it listens to signals from several satellites in the sky and measures how long each signal took to arrive — it needs at least four satellites to be accurate.", "bis": "Ang GPS sa telepono nahibalo asa ka tungod kay maminaw kini sa signal sa pipila ka satellite sa langit ug sukdon kung unsa kadugay miabot ang matag signal — kinahanglan kini ug labing menos upat ka satellite aron tukma."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gps-satellite-clocks-relativity-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "GPS satellites carry very precise clocks", "grades": [8, 9, 10], "terms": ["GPS", "satellite", "atomic clock", "relong atomiko", "napakaeksaktong orasan", "tukmang orasan", "oras", "panahon", "presisyon", "timing", "very precise clock", "kalkulasyon", "sukat ng oras", "exact time", "duration"], "fact": {"tl": "Ang bawat GPS satellite ay may sobrang eksaktong orasan, dahil kahit kaunting mali sa oras ay magiging malaking mali sa lokasyon — naglalakbay ang hudyat sa bilis ng liwanag, kaya isang segundong mali ay aabot ng daan-daang libong kilometro ang pagkakamali.", "en": "Each GPS satellite carries an extremely precise clock, because even a tiny timing error becomes a large location error — the signal travels at the speed of light, so a one-second mistake would put you hundreds of thousands of kilometres off.", "bis": "Ang matag GPS satellite nagdala ug sobra ka tukma nga orasan, kay bisan gamay nga sayop sa oras mahimong dako nga sayop sa lokasyon — ang signal mobiyahe sa katulin sa kahayag, busa usa ka segundo nga sayop magpahimutang nimo gatusan ka libo ka kilometro ang sayop."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "touchscreen-senses-body-electricity-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "a touchscreen senses your body's tiny electricity", "grades": [6, 7, 8], "terms": ["touchscreen", "touch screen", "screen", "pindutin", "hawakan", "hipo", "daliri", "tudlo", "hikap", "kuryente ng katawan", "kuryente sa lawas", "capacitive", "electricity", "kuryente", "guwantes", "gloves", "hindi gumagana sa guwantes", "conductive"], "fact": {"tl": "Gumagana ang touchscreen ng telepono dahil ang katawan natin ay may konting kuryente, at nararamdaman ng screen kung saan naabot ng daliri — kaya hindi ito gumagana kapag may suot kang makapal na guwantes.", "en": "A phone's touchscreen works because our bodies carry a little electricity, and the screen senses where your finger touches — which is why it does not work when you wear thick gloves.", "bis": "Mogana ang touchscreen sa telepono tungod kay ang atong lawas adunay gamay nga kuryente, ug mabati sa screen kung asa midapat ang tudlo — mao nga dili kini mogana kung magsul-ob ka ug baga nga gwantes."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rechargeable-battery-ions-move-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "in a battery, charged particles move back and forth", "grades": [8, 9, 10], "terms": ["rechargeable battery", "baterya", "battery", "lithium", "ion", "ions", "naka-charge na partikulo", "gisingilan nga partikulo", "lumilipat", "mobalhin", "kumikilos", "lithium-ion", "kuryente", "charge", "discharge", "naglalakbay pabalik-balik", "balik-balik", "electrode"], "fact": {"tl": "Sa loob ng rechargeable na baterya ng telepono, may maliliit na naka-charge na partikulo (ions) na lumilipat mula sa isang dulo patungo sa kabila kapag ginagamit, at babalik sila sa unang dulo kapag kinakarga mo ulit — kaya muli itong magagamit.", "en": "Inside a phone's rechargeable battery, tiny charged particles (ions) move from one side to the other while you use it, and they move back when you recharge it — which is what lets it be used again.", "bis": "Sulod sa rechargeable nga baterya sa telepono, adunay gagmay nga gisingilan nga partikulo (ions) nga mobalhin gikan sa usa ka kilid ngadto sa pikas samtang gigamit nimo, ug mobalik sila sa unang kilid kung singilan nimo pag-usab — mao kini ang hinungdan nga magamit kini balik."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "battery-wears-out-charge-cycles-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "why rechargeable batteries wear out over time", "grades": [7, 8, 9], "terms": ["rechargeable battery", "baterya", "battery", "humihina", "naluya", "luya", "nauubos", "nahurot", "charge cycle", "pagka-charge", "paghina ng baterya", "wears out", "degrade", "hindi na tumatagal", "dili na molungtad", "buhay ng baterya", "battery life", "limit"], "fact": {"tl": "Humihina ang rechargeable na baterya habang tumatagal dahil sa bawat pag-charge at paggamit ay unti-unting nasisira ang mga sangkap sa loob nito, kaya pagkatapos ng daan-daang beses na pag-charge ay hindi na ito kayang humawak ng dating dami ng enerhiya.", "en": "A rechargeable battery gets weaker over time because each charge and use slightly damages the materials inside it, so after hundreds of charges it can no longer hold as much energy as when it was new.", "bis": "Maluya ang rechargeable nga baterya samtang molabay ang panahon tungod kay ang matag pag-charge ug paggamit hinay-hinay nga makadaot sa mga materyales sa sulod niini, busa human sa gatusan ka beses nga pag-charge dili na kini makakupot sa daghan nga enerhiya sama sa bag-o pa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "solar-panel-photovoltaic-knocks-electrons-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "sunlight knocks electrons loose in a solar panel", "grades": [8, 9, 10], "terms": ["solar panel", "solar cell", "araw", "adlaw", "sinag ng araw", "silaw sa adlaw", "sikat ng araw", "photovoltaic", "electron", "naglalaglag ng electron", "nagtutulak", "kuryente", "kuryente gikan sa adlaw", "silicon", "sunlight", "electricity", "tinatamaan ng liwanag", "naigo sa kahayag"], "fact": {"tl": "Hindi iniinit ng solar panel ang araw para gumawa ng kuryente — sa halip, kapag tinatamaan ng liwanag ang espesyal na materyales (silicon) sa loob nito, natutulak ang maliliit na partikulo (electrons) at iyon ang dumadaloy bilang kuryente.", "en": "A solar panel does not make electricity by getting hot — instead, when light hits the special material (silicon) inside it, tiny particles called electrons are knocked loose, and that flow is the electricity.", "bis": "Ang solar panel dili maghimo ug kuryente pinaagi sa kainit — hinuon, kung ang kahayag motama sa espesyal nga materyales (silicon) sa sulod niini, ang gagmay nga partikulo (electrons) matuklod, ug kana nga pag-agos mao ang kuryente."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "solar-panel-cloudy-still-works-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "solar panels work on cloudy days too", "grades": [6, 7, 8], "terms": ["solar panel", "araw", "adlaw", "maulap", "panganod", "dag-om", "gabon", "cloudy", "ulan", "konting kuryente", "gamay nga kuryente", "liwanag", "kahayag", "umuulan", "still works", "init", "heat", "hindi init kundi liwanag"], "fact": {"tl": "Gumagana pa rin ang solar panel kahit maulap ang araw dahil ang liwanag, hindi ang init, ang ginagamit nito — ngunit mas kaunti ang kuryenteng nagagawa kapag natatakpan ng makakapal na ulap ang araw.", "en": "A solar panel still works on a cloudy day because it uses light, not heat — but it makes less electricity when thick clouds block the sun.", "bis": "Ang solar panel mogana gihapon bisan maulap ang adlaw tungod kay ang kahayag, dili ang kainit, ang gigamit niini — apan mas gamay ang kuryente nga mahimo kung ang baga nga panganod motabon sa adlaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "digital-camera-counts-light-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "a digital camera turns light into numbers", "grades": [7, 8, 9], "terms": ["digital camera", "kamera", "litrato", "hulagway", "larawan", "litrato sa digital", "sensor", "light sensor", "milyon-milyong sensor", "pixel", "numero", "numbers", "ilaw", "liwanag", "kahayag", "binibilang ang liwanag", "nagsusukat ng liwanag", "stored as numbers"], "fact": {"tl": "Ang digital camera ay walang pelikula — sa halip ay mayroon itong sensor na may milyon-milyong maliliit na puntos na nagsusukat kung gaano kalakas ang liwanag na tumama sa bawat isa, at ang larawan ay iniimbak bilang mga numero.", "en": "A digital camera has no film — instead it has a sensor with millions of tiny spots that each measure how much light hit them, and the picture is stored as numbers.", "bis": "Ang digital camera walay pelikula — hinuon adunay sensor nga adunay minilyon nga gagmay nga tuldok nga ang matag usa mosukod kung unsa kakusog ang kahayag nga mitama niini, ug ang litrato gitipigan isip mga numero."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "camera-rgb-pixels-color-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "cameras and screens make all colors from three", "grades": [6, 7, 8], "terms": ["pixel", "kulay", "kolor", "pula", "berde", "asul", "pula berde asul", "pula lunhaw asul", "red green blue", "RGB", "tatlong kulay", "tulo ka kolor", "screen", "camera", "kamera", "lahat ng kulay", "tanang kolor", "color mixing", "paghalo ng kulay"], "fact": {"tl": "Halos lahat ng kulay na nakikita mo sa screen o sa larawan ng kamera ay gawa lamang sa tatlong kulay na pinaghahalo sa iba't ibang dami — pula, berde, at asul.", "en": "Almost every color you see on a screen or in a camera's picture is made from just three colors mixed in different amounts — red, green, and blue.", "bis": "Halos tanang kolor nga makita nimo sa screen o sa litrato sa kamera gihimo lamang gikan sa tulo ka kolor nga gisagol sa lainlaing gidaghanon — pula, lunhaw, ug asul."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wifi-radio-different-channels-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "wifi and radio use invisible waves at set frequencies", "grades": [7, 8, 9], "terms": ["wifi", "wi-fi", "radio wave", "alon ng radyo", "balud sa radyo", "frequency", "himpapawid", "channel", "estasyon", "station", "invisible waves", "alon na di nakikita", "balud nga dili makita", "tunog", "signal", "antenna", "antena", "tuned"], "fact": {"tl": "Ang wifi, radyo, at telepono ay pawang gumagamit ng parehong uri ng alon na hindi nakikita (radio waves), ngunit hindi sila nagkakagulo dahil bawat isa ay nakatutok sa kanyang sariling frequency, gaya ng iba't ibang istasyon sa radyo.", "en": "Wi-Fi, radio, and phones all use the same kind of invisible waves (radio waves), but they do not get mixed up because each one is tuned to its own frequency, like different stations on a radio.", "bis": "Ang wifi, radyo, ug telepono tanan naggamit sa samang matang sa balud nga dili makita (radio waves), apan dili sila magkasagol tungod kay ang matag usa naka-tuned sa kaugalingong frequency niini, sama sa lainlaing estasyon sa radyo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "radio-waves-travel-light-speed-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "radio signals travel at the speed of light", "grades": [8, 9, 10], "terms": ["radio wave", "alon ng radyo", "balud sa radyo", "bilis ng liwanag", "katulin sa kahayag", "speed of light", "napakabilis", "kusog kaayo", "signal", "hudyat", "wifi", "phone signal", "electromagnetic", "mas mabilis sa tunog", "mas paspas sa tingog", "instant"], "fact": {"tl": "Ang hudyat ng radyo, wifi, at telepono ay naglalakbay sa bilis ng liwanag — ito ang pinakamabilis sa lahat, kaya halos walang antala ang pagdating ng alon kahit malayo ang pinanggalingan.", "en": "Radio, wi-fi, and phone signals travel at the speed of light — the fastest speed there is, so the waves arrive with almost no delay even from far away.", "bis": "Ang signal sa radyo, wifi, ug telepono mobiyahe sa katulin sa kahayag — kini ang pinakakusog sa tanan, mao nga halos walay langan ang pag-abot sa balud bisan layo ang gigikanan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "led-light-from-electrons-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "an LED makes light directly from electricity", "grades": [8, 9, 10], "terms": ["LED", "light emitting diode", "ilaw", "kahayag", "liwanag", "suga", "bombilya", "bombilyang LED", "electron", "kuryente", "diode", "diyodo", "walang init", "walay kainit", "electricity to light", "kuryente patungong ilaw", "semiconductor", "matipid", "kuryente direkta sa ilaw"], "fact": {"tl": "Ang LED ay gumagawa ng ilaw nang direkta mula sa kuryente kapag ang maliliit na partikulo (electrons) sa loob nito ay naglalabas ng liwanag habang dumadaan — hindi tulad ng lumang bombilya na kailangan munang sumiklab ang init bago lumiwanag.", "en": "An LED makes light directly from electricity when tiny particles (electrons) inside it release light as they pass through — unlike an old bulb that must first glow hot to shine.", "bis": "Ang LED maghimo ug kahayag direkta gikan sa kuryente kung ang gagmay nga partikulo (electrons) sa sulod niini mobuga ug kahayag samtang mo-agi — dili sama sa daang bombilya nga kinahanglan una mainit aron mosiga."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "microwave-heats-water-molecules-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "a microwave oven heats the water inside food", "grades": [6, 7, 8], "terms": ["microwave", "microwave oven", "hurno", "pugon", "init", "kainit", "tubig sa pagkain", "tubig sa pagkaon", "water molecules", "molekula ng tubig", "nag-uuga", "nagpapayanig", "gipakurog", "pagkain", "pagkaon", "food", "heat", "mainit sa loob", "nagpapagalaw sa tubig"], "fact": {"tl": "Hindi iniinit ng microwave oven ang plato kundi ang tubig na nasa loob mismo ng pagkain — pinapayanig nito nang napakabilis ang mga molekula ng tubig, at ang pagyanig na iyon ang nagiging init.", "en": "A microwave oven does not heat the plate but the water inside the food itself — it makes the water molecules vibrate very fast, and that shaking becomes heat.", "bis": "Ang microwave oven dili mag-init sa plato kondili sa tubig nga anaa mismo sa sulod sa pagkaon — gipakurog niini ang mga molekula sa tubig nga paspas kaayo, ug kana nga pagkurog mahimong kainit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "microwave-metal-danger-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "why you should not put metal in a microwave", "grades": [7, 8, 9], "terms": ["microwave", "microwave oven", "metal", "bakal", "puthaw", "kutsara", "kutsilyo", "spark", "kispas", "kidlat", "alitaptap ng kuryente", "panganib", "katalagman", "kuryente", "hindi pwedeng metal", "dili pwede metal", "do not put metal", "arc"], "fact": {"tl": "Hindi mo dapat ilagay ang metal sa loob ng microwave dahil ang mga alon ay nagdudulot ng matulis na kuryente sa gilid ng metal, na maaaring magkidlat at magdulot ng sunog.", "en": "You should not put metal inside a microwave because the waves build up sharp electricity at the metal's edges, which can spark and start a fire.", "bis": "Dili nimo angay ibutang ang metal sa sulod sa microwave tungod kay ang mga balud magpundok ug hait nga kuryente sa kilid sa metal, nga mahimong mokilat ug maghatag ug sunog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "computer-binary-bits-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "computers store everything as ones and zeros", "grades": [6, 7, 8], "terms": ["computer", "kompyuter", "binary", "isa at sero", "usa ug sero", "1 at 0", "bit", "bits", "switch", "swits", "naka-on naka-off", "on off", "naka-bukas sarado", "code", "digital", "letra at larawan bilang numero", "stored", "naka-imbak"], "fact": {"tl": "Ang computer ay walang ibang alam kundi dalawang bagay — naka-on o naka-off — kaya ang lahat ng letra, larawan, at tunog ay isinusulat bilang mahabang hanay ng 1 at 0 na tinatawag na binary.", "en": "A computer really knows only two things — on or off — so every letter, picture, and sound is written as long strings of 1s and 0s called binary.", "bis": "Ang computer wala'y lain nga nahibaloan kondili duha ka butang — naka-on o naka-off — busa ang tanang letra, litrato, ug tingog gisulat isip taas nga han-ay sa 1 ug 0 nga gitawag ug binary."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "computer-memory-keeps-without-power-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "some computer memory keeps files even when off", "grades": [7, 8, 9], "terms": ["computer memory", "memorya ng kompyuter", "storage", "naka-save", "natipigan", "naluwas", "flash memory", "hindi nawawala", "dili mawala", "patay ang kuryente", "walay kuryente", "power off", "file", "naka-imbak", "RAM", "nakalimutan kapag patay", "keeps without power"], "fact": {"tl": "May dalawang uri ng memorya ang telepono o computer: ang isa ay tumutulong lang habang nakabukas at nakakalimutan ang laman kapag pinatay, at ang isa naman ay nagtatago ng iyong mga larawan at file kahit wala nang kuryente.", "en": "A phone or computer has two kinds of memory: one only helps while it is on and forgets everything when turned off, while the other keeps your pictures and files even with no power.", "bis": "Ang telepono o computer adunay duha ka matang sa memorya: ang usa motabang lamang samtang naka-on ug makalimot sa sulod kung patyon, samtang ang lain motipig sa imong mga litrato ug file bisan wala nay kuryente."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fiber-optic-light-bounces-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "fiber-optic cables guide light by bouncing it inside", "grades": [8, 9, 10], "terms": ["fiber optic", "fiber-optic", "salamin na sinulid", "hibla nga bildo", "tubo ng salamin", "liwanag", "kahayag", "ilaw", "tumatalbog", "mo-bouncing", "bumabalik sa loob", "total internal reflection", "internet", "mabilis na internet", "paspas nga internet", "light bounces", "glass thread"], "fact": {"tl": "Ang fiber-optic cable ay napakanipis na sinulid ng salamin na nagdadala ng impormasyon sa pamamagitan ng liwanag na patuloy na tumatalbog sa loob nito, kaya hindi tumatakas ang ilaw kahit baluktot ang kable.", "en": "A fiber-optic cable is a very thin glass thread that carries information using light that keeps bouncing along the inside, so the light cannot escape even when the cable bends.", "bis": "Ang fiber-optic cable usa ka nipis kaayo nga hilo nga bildo nga nagdala ug impormasyon pinaagi sa kahayag nga padayon nga mobalik sa sulod niini, busa dili makaikyas ang kahayag bisan baliko ang kable."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "phone-charges-slow-when-hot-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "heat is bad for a phone battery", "grades": [7, 8, 9], "terms": ["battery", "baterya", "init", "kainit", "mainit", "phone hot", "telepono mainit", "araw", "adlaw", "nasisira ang baterya", "madaot ang baterya", "overheat", "sobrang init", "huwag iwan sa araw", "ayaw ibilin sa adlaw", "charge", "heat damages battery"], "fact": {"tl": "Masama sa baterya ng telepono ang sobrang init, kaya hindi mo dapat iwan ang telepono sa loob ng sasakyan na nakatigil sa araw — ang matinding init ay mas mabilis na nakakasira ng mga sangkap sa loob ng baterya.", "en": "Strong heat is bad for a phone battery, so you should not leave your phone in a car parked in the sun — high heat damages the materials inside the battery faster.", "bis": "Daotan sa baterya sa telepono ang sobra nga kainit, busa dili nimo angay ibilin ang telepono sulod sa sakyanan nga nakaparking sa adlaw — ang grabe nga kainit mas paspas nga makadaot sa mga materyales sa sulod sa baterya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "router-shares-one-connection-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "a wifi router shares one connection with many devices", "grades": [6, 7, 8], "terms": ["router", "wifi router", "modem", "internet", "isang koneksyon", "usa ka koneksyon", "maraming device", "daghang device", "telepono at laptop", "ipinamamahagi", "gipanghatag", "shares connection", "pinagsasaluhan", "ginabahin-bahin", "broadband", "iisang linya"], "fact": {"tl": "Ang wifi router sa bahay ay kumukuha ng iisang koneksyon sa internet at ipinamamahagi ito sa maraming device — kaya nakakapanood ang isa, nakakapaglaro ang isa, at nakakapag-aral ang isa pa sa parehong sandali.", "en": "A home wifi router takes one internet connection and shares it among many devices — so one person can watch, another can play, and another can study all at the same time.", "bis": "Ang wifi router sa balay magkuha ug usa ka koneksyon sa internet ug ipanghatag kini sa daghang device — busa makakita ang usa, makadula ang lain, ug makatuon ang lain pa sa samang higayon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "screen-pixels-too-small-to-see-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "screen pixels are too small for the eye to see", "grades": [6, 7, 8], "terms": ["pixel", "screen", "telepono", "TV", "napakaliit", "gamay kaayo", "hindi nakikita ng mata", "dili makita sa mata", "magnifying glass", "lente", "may puwang", "tuldok", "tuldok ng kulay", "tiny dots", "milyon-milyon", "minilyon", "magkadikit"], "fact": {"tl": "Ang larawan sa screen ay gawa sa milyon-milyong napakaliliit na tuldok ng ilaw (pixels) na masyadong maliit para makita ng mata mo nang isa-isa, kaya tila tuloy-tuloy ang larawan — ngunit makikita mo ang mga tuldok kung lalagyan mo ng magnifying glass.", "en": "The picture on a screen is made of millions of tiny dots of light (pixels) too small for your eye to see one by one, so the picture looks smooth — but you can see the dots with a magnifying glass.", "bis": "Ang litrato sa screen hinimo gikan sa minilyon nga gagmay kaayo nga tuldok sa kahayag (pixels) nga gamay ra kaayo aron makita sa imong mata tagsa-tagsa, busa morag hapsay ang litrato — apan makita nimo ang mga tuldok kung gamiton nimo ang magnifying glass."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "internet-server-stores-websites-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "websites live on computers called servers", "grades": [6, 7, 8], "terms": ["server", "serbidor", "website", "webpage", "internet", "kompyuter na laging bukas", "computer nga kanunay naka-on", "naka-imbak", "natipigan", "data center", "nagtatago ng website", "stores websites", "request", "hinihingi", "ginakuha", "load", "ipinapadala"], "fact": {"tl": "Ang bawat website na binubuksan mo ay nakatago sa isang makapangyarihang computer na laging nakabukas na tinatawag na server, at kapag nag-click ka, hinihingi ng telepono mo ang impormasyon mula sa server na iyon.", "en": "Every website you open is stored on a powerful computer that is always on, called a server, and when you click, your phone asks that server for the information.", "bis": "Ang matag website nga imong ablihan gitipigan sa usa ka kusgan nga computer nga kanunay naka-on nga gitawag ug server, ug kung mo-click ka, ang imong telepono mangayo ug impormasyon gikan niana nga server."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "phone-airplane-mode-stops-signals-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "airplane mode turns off a phone's wireless signals", "grades": [6, 7, 8], "terms": ["airplane mode", "eroplano mode", "ayroplano mode", "telepono", "wireless", "signal", "hudyat", "radio waves", "pinapatay ang signal", "gipalong ang signal", "eroplano", "ayroplano", "walang signal", "walay signal", "stops sending", "humihinto sa pagpapadala", "interference"], "fact": {"tl": "Kapag binuksan mo ang airplane mode, tumitigil ang telepono sa pagpapadala at pagtanggap ng mga wireless na hudyat tulad ng signal, wifi, at Bluetooth — kaya ito ipinapagawa sa loob ng eroplano upang hindi makagambala sa mga kagamitan nito.", "en": "When you turn on airplane mode, the phone stops sending and receiving wireless signals like cellular, wifi, and Bluetooth — which is why it is asked for on a plane so it will not interfere with the plane's equipment.", "bis": "Kung ablihan nimo ang airplane mode, ang telepono mohunong sa pagpadala ug pagdawat sa wireless nga signal sama sa cellular, wifi, ug Bluetooth — mao nga gipangayo kini sulod sa eroplano aron dili makabalda sa mga kagamitan niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fingerprint-sensor-reads-ridges-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "a phone fingerprint sensor reads the ridges on your finger", "grades": [6, 7, 8], "terms": ["fingerprint", "fingerprint sensor", "bakas ng daliri", "tudlo", "tuyom sa tudlo", "linya ng daliri", "guhit sa kamot", "ridges", "natatangi", "talagsaon", "unique", "telepono", "security", "naa-unlock", "nabuksan", "scan", "binabasa ang guhit"], "fact": {"tl": "Ang fingerprint sensor ng telepono ay nagbabasa ng natatanging guhit at kurba sa dulo ng iyong daliri, at dahil walang dalawang taong magkapareho ng bakas ng daliri, ikaw lamang ang makakapag-unlock nito.", "en": "A phone's fingerprint sensor reads the unique lines and curves on the tip of your finger, and because no two people have the same fingerprint, only you can unlock it.", "bis": "Ang fingerprint sensor sa telepono mobasa sa talagsaon nga linya ug kurba sa tumoy sa imong tudlo, ug tungod kay walay duha ka tawo nga managsama ang fingerprint, ikaw lang ang makahimo sa pag-unlock niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "phone-knows-orientation-sensor-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "a phone has a tiny sensor that feels which way it tilts", "grades": [7, 8, 9], "terms": ["accelerometer", "tilt sensor", "telepono", "nakaikot", "naka-tilt", "nahapayan", "pasulong pahiga", "umiikot ang screen", "nag-rotate ang screen", "sensor", "gravity", "grabidad", "pagkiling", "pagharap", "nararamdaman kung saan nakaharap", "motion sensor", "nagbabago ng tabingi"], "fact": {"tl": "May maliit na sensor sa loob ng telepono na nararamdaman kung paano mo ito hinahawakan o ikinikiling, kaya umiikot ang larawan sa screen kapag pinihit mo ang telepono nang pahiga.", "en": "A phone has a tiny sensor inside that feels how you hold or tilt it, which is why the picture on the screen rotates when you turn the phone sideways.", "bis": "Ang telepono adunay gamay nga sensor sa sulod nga makabati kung giunsa nimo kini gigunitan o gikiling, mao nga moliso ang litrato sa screen kung ipausab nimo ang telepono nga pahigda."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "qr-code-stores-info-in-pattern-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "a QR code stores information in a pattern of squares", "grades": [6, 7, 8], "terms": ["QR code", "qr code", "parisukat na pattern", "kuwadrado nga pattern", "itim at puti", "itom ug puti", "pattern", "kamera", "binabasa ng kamera", "gibasa sa kamera", "impormasyon", "link", "website", "scan", "tuldok at parisukat", "mga kahon", "stores info"], "fact": {"tl": "Ang QR code ay isang pattern ng itim at puting parisukat na nag-iimbak ng impormasyon, at kapag tinutok mo ang kamera dito, binabasa ng telepono ang pattern at dinadala ka nito sa isang website o mensahe.", "en": "A QR code is a pattern of black and white squares that stores information, and when you point a camera at it, the phone reads the pattern and takes you to a website or message.", "bis": "Ang QR code usa ka pattern sa itom ug puti nga kwadrado nga nagtipig ug impormasyon, ug kung itutok nimo ang kamera niini, ang telepono mobasa sa pattern ug modala nimo sa usa ka website o mensahe."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "led-traffic-and-flashlight-low-power-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "LEDs last for years and barely get warm", "grades": [6, 7, 8], "terms": ["LED", "ilaw na LED", "suga nga LED", "bombilya", "matagal", "dugay", "hindi madaling masira", "dili daling maguba", "matipid", "hindi mainit", "dili mainit", "konting kuryente", "gamay nga kuryente", "tumatagal ng taon", "molungtad", "lasts years", "cool"], "fact": {"tl": "Ang ilaw na LED ay maaaring tumagal ng maraming taon at halos hindi uminit kahit matagal na nakabukas, kaya ginagamit ito sa traffic light, flashlight, at screen ng telepono kung saan kailangan ng tibay at kakaunting kuryente.", "en": "An LED light can last many years and barely gets warm even when left on, which is why it is used in traffic lights, flashlights, and phone screens where toughness and low power are needed.", "bis": "Ang suga nga LED mahimong molungtad ug daghang tuig ug halos dili mainit bisan dugay nga naka-on, mao nga gigamit kini sa traffic light, flashlight, ug screen sa telepono diin gikinahanglan ang kalig-on ug gamay nga kuryente."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "eye-image-upside-down-g5", "domain": "LIVING_THINGS", "topic": "the eye makes an upside-down picture", "grades": [5, 6, 7], "terms": ["baligtad", "patiwarik", "baliktad", "nakatuwad", "mata", "retina", "lente", "lens", "utak", "brain", "larawan", "imahe", "image", "upside down", "inverted", "tama ang turing", "baliktarin", "litrato"], "fact": {"tl": "Ang larawang nabubuo sa retina natin ay nakabaligtad, ngunit binabaligtad itong muli ng utak kaya nakikita natin ang mundo nang tama ang turing.", "en": "The picture that forms on the retina is actually upside-down, but the brain flips it again so we see the world the right way up.", "bis": "Ang hulagway nga maporma sa retina nato baliktad gyud, apan baliktaron kini pag-usab sa utok maong makita nato ang kalibutan nga sakto ang pagkabutang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "eye-blind-spot-g6", "domain": "LIVING_THINGS", "topic": "every eye has a blind spot", "grades": [6, 7, 8], "terms": ["blind spot", "bulag na bahagi", "blind spot sa mata", "walang nakikita", "optic nerve", "ugat ng paningin", "retina", "mata", "nawawala", "puno", "utak", "blind spot sa mata", "dili makita", "nawawala ang imahe", "puntong bulag"], "fact": {"tl": "May maliit na bahagi sa retina kung saan lumalabas ang optic nerve na walang sensor, kaya may natural na 'blind spot' ang bawat mata na hindi nakakakita — pero pinupunan ito ng utak kaya hindi natin namamalayan.", "en": "There is a small spot on the retina where the optic nerve leaves and there are no sensors, so every eye has a natural 'blind spot' that cannot see — but the brain fills it in so we never notice.", "bis": "Adunay gamay nga bahin sa retina diin mogula ang optic nerve nga walay sensor, mao nga ang matag mata adunay natural nga 'blind spot' nga dili makakita — apan punan kini sa utok maong dili nato mamatikdan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pupil-changes-size-light-g4", "domain": "LIVING_THINGS", "topic": "the pupil shrinks and widens with light", "grades": [4, 5, 6], "terms": ["balintataw", "pupil", "itim na bilog", "lumalaki", "lumiliit", "liwanag", "madilim", "dilim", "iris", "mata", "nagdadako", "nag-gamay", "nagdaku", "kahayag", "ngitngit", "pinid"], "fact": {"tl": "Ang itim na bilog sa gitna ng mata, ang balintataw o pupil, ay lumiliit kapag maliwanag at lumalaki kapag madilim para itama ang dami ng liwanag na papasok.", "en": "The black circle in the middle of the eye, the pupil, gets smaller in bright light and bigger in the dark to control how much light comes in.", "bis": "Ang itom nga lingin sa tunga sa mata, ang pupil, mo-gamay kung hayag ug modaku kung ngitngit aron makontrol ang gidaghanon sa kahayag nga mosulod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "color-blindness-more-common-boys-g6", "domain": "LIVING_THINGS", "topic": "color blindness is more common in boys", "grades": [6, 7, 8], "terms": ["color blind", "kulang sa pagkilala ng kulay", "hindi makilala ang kulay", "pula at berde", "lalaki", "babae", "mana", "minana", "genes", "color blindness", "bughaw", "pula", "berde", "dili mailhan ang kolor", "gimana", "mas daghan ang lalaki"], "fact": {"tl": "Mas madalas na may color blindness ang mga lalaki kaysa babae dahil minana ito sa pamamagitan ng X chromosome, at iisa lang ang X ng mga lalaki.", "en": "Color blindness is more common in boys than girls because it is inherited through the X chromosome, and boys have only one X.", "bis": "Mas kasagaran nga adunay color blindness ang mga lalaki kaysa babaye tungod kay namana kini pinaagi sa X chromosome, ug usa ra ang X sa mga lalaki."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "color-blind-red-green-g5", "domain": "LIVING_THINGS", "topic": "red-green is the most common color blindness", "grades": [5, 6, 7], "terms": ["color blind", "kulang sa kulay", "pula", "berde", "hindi makita ang pagkakaiba", "pulang berde", "traffic light", "cones", "color blindness", "pula ug berde", "dili makita ang kalainan", "kolor", "kulay", "most common", "pinakakaraniwan"], "fact": {"tl": "Ang pinakakaraniwang uri ng color blindness ay kahirapang ipagkaiba ang pula sa berde, kaya magkasingmukha ang dalawang kulay para sa taong ito.", "en": "The most common kind of color blindness is trouble telling red from green, so the two colors look alike to that person.", "bis": "Ang pinakakasagaran nga matang sa color blindness mao ang kalisod sa pag-ila sa pula gikan sa berde, mao nga managsama ang duha ka kolor alang sa maong tawo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tears-keep-eye-wet-g4", "domain": "LIVING_THINGS", "topic": "tears wash and protect the eye", "grades": [3, 4, 5], "terms": ["luha", "tears", "basa ang mata", "naglilinis", "alikabok", "kurap", "kurap-kurap", "blink", "nagkurap", "linis", "basa", "mata", "naghugas", "abog", "limpyo", "nagpabasa"], "fact": {"tl": "Bawat kurap natin ay nagpapahid ng luha sa mata para panatilihin itong basa at malinis, at upang hugasan palabas ang alikabok.", "en": "Every time we blink, a thin layer of tears spreads over the eye to keep it wet and clean and to wash away dust.", "bis": "Matag pamilok nato magbutang ug nipis nga luha sa mata aron magpabilin kining basa ug limpyo ug aron hugasan pagawas ang abog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-we-blink-g4", "domain": "LIVING_THINGS", "topic": "why we blink so often", "grades": [3, 4, 5], "terms": ["kurap", "blink", "kurap-kurap", "awtomatiko", "luha", "basa ang mata", "hindi inaalala", "talukap", "eyelid", "nagkurap", "pamilok", "awtomatik", "talukap sa mata", "kusog", "kanunay"], "fact": {"tl": "Kusang kumukurap tayo nang ilang beses kada minuto kahit hindi natin sinasadya, para maikalat ang luha at maprotektahan ang mata sa pagkatuyo.", "en": "We blink several times a minute without thinking about it, to spread tears and protect the eye from drying out.", "bis": "Kusog tang mamilok pila ka beses kada minuto bisan dili nato tuyo, aron ikatag ang luha ug mapanalipdan ang mata gikan sa pagkauga."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "eye-color-from-iris-g5", "domain": "LIVING_THINGS", "topic": "eye color comes from the iris", "grades": [5, 6, 7], "terms": ["kulay ng mata", "iris", "balintataw na kulay", "kayumanggi", "itim", "asul", "pigment", "melanin", "mana", "eye color", "kolor sa mata", "brown", "bughaw", "gimana", "kulay", "kulay ng iris"], "fact": {"tl": "Ang kulay ng mata ng tao ay nagmumula sa iris, ang singsing na kulay sa palibot ng balintataw, at nakabatay ito sa dami ng pigment na minana.", "en": "A person's eye color comes from the iris, the colored ring around the pupil, and depends on how much pigment they inherited.", "bis": "Ang kolor sa mata sa tawo gikan sa iris, ang kolor nga singsing libot sa pupil, ug nagdepende kini sa gidaghanon sa pigment nga gimana."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-eyes-red-in-photos-g5", "domain": "LIVING_THINGS", "topic": "why eyes look red in flash photos", "grades": [5, 6, 7], "terms": ["pulang mata", "red eye", "flash", "litrato", "retina", "dugo", "ugat", "pula sa larawan", "kamera", "red-eye", "pula ang mata sa litrato", "retrato", "ngano pula ang mata"], "fact": {"tl": "Kapag kumikislap ang flash ng kamera, tumatama ang liwanag sa likuran ng mata na puno ng maliliit na ugat ng dugo, kaya minsan kulay-pula ang mata sa larawan.", "en": "When a camera flash fires, the light bounces off the back of the eye which is full of tiny blood vessels, so the eyes can look red in the photo.", "bis": "Kung mokidlap ang flash sa kamera, ang kahayag mosalpo sa likod sa mata nga puno sa gagmay nga ugat sa dugo, mao nga usahay pula ang mata sa litrato."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "two-eyes-3d-depth-g6", "domain": "LIVING_THINGS", "topic": "two eyes give 3D vision", "grades": [6, 7, 8], "terms": ["tatlong-dimensyon", "3D", "lalim", "depth", "dalawang mata", "magkaibang anggulo", "stereo", "tatlong dimensyon", "gilay-on", "duha ka mata", "lawom", "3D nga panan-aw", "layo", "makakuha ng lalim"], "fact": {"tl": "Dahil bahagyang magkaiba ang nakikita ng kaliwa at kanang mata, pinagsasama ito ng utak para makabuo ng tatlong-dimensyong larawan na may lalim — ito ang 3D vision.", "en": "Because the left and right eyes see slightly different views, the brain combines them into a three-dimensional picture with depth — this is 3D vision.", "bis": "Tungod kay gamay ang kalainan sa makita sa wala ug tuo nga mata, gihiusa kini sa utok aron makahimo ug tulo-ka-dimensyon nga hulagway nga adunay giladmon — kini ang 3D nga panan-aw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ear-three-smallest-bones-g6", "domain": "LIVING_THINGS", "topic": "the three smallest bones are in the ear", "grades": [6, 7, 8], "terms": ["pinakamaliit na buto", "tatlong buto", "tainga", "ossicles", "maso", "stirrup", "hammer", "anvil", "tenga", "tatlo ka bukog", "pinakagamay nga bukog", "martilyo", "dalunggan", "gagmay nga bukog"], "fact": {"tl": "Ang tatlong pinakamaliit na buto sa katawan ng tao ay nasa loob ng tainga, at ipinapasa nila ang panginig ng tunog mula sa eardrum papunta sa cochlea.", "en": "The three smallest bones in the human body are inside the ear, and they pass the sound vibration from the eardrum to the cochlea.", "bis": "Ang tulo ka pinakagamay nga bukog sa lawas sa tawo anaa sa sulod sa dalunggan, ug ila kining gipasa ang pagkurog sa tingog gikan sa eardrum ngadto sa cochlea."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "earwax-protects-ear-g4", "domain": "LIVING_THINGS", "topic": "earwax protects the ear", "grades": [3, 4, 5], "terms": ["tutuli", "earwax", "tutuli sa tainga", "nagpoprotekta", "alikabok", "mikrobyo", "naglilinis", "hindi dapat ipangsubo", "cotton bud", "tutuli sa dalunggan", "nagpanalipod", "abog", "dalunggan", "limpyo", "dili sungkit"], "fact": {"tl": "Ang tutuli ay hindi dumi kundi natural na proteksyon — humahuli ito ng alikabok at mikrobyo, at dahan-dahang lumalabas nang kusa kaya hindi dapat sungkitin nang malalim.", "en": "Earwax is not just dirt but a natural protection — it traps dust and germs and slowly moves out on its own, so it should not be dug out deeply.", "bis": "Ang tutuli dili lang hugaw kondili natural nga panalipod — modakop kini ug abog ug mikrobyo ug hinay-hinay nga mogawas sa iyang kaugalingon, mao nga dili kini sungkiton ug lawom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cochlea-snail-shaped-g6", "domain": "LIVING_THINGS", "topic": "the cochlea is shaped like a snail", "grades": [6, 7, 8], "terms": ["cochlea", "hugis kuhol", "snail", "tainga sa loob", "fluid", "buhok na sensor", "hair cells", "tunog", "kuhol", "sulod nga dalunggan", "tubig", "balahibo nga sensor", "tingog", "porma sa kuhol", "cochlea sa dalunggan"], "fact": {"tl": "Ang cochlea ay parang kuhol na hugis sa loob ng tainga at puno ng likido; ang panginig ng tunog ay gumagalaw sa likido at humahawi sa libo-libong maliliit na hair cells na nagpapadala ng signal sa utak.", "en": "The cochlea is a snail-shaped, fluid-filled part deep in the ear; sound vibrations move the fluid and bend thousands of tiny hair cells that send signals to the brain.", "bis": "Ang cochlea kuhol nga porma ug puno sa likido sa sulod sa dalunggan; ang pagkurog sa tingog mopalihok sa likido ug moliko sa liboan ka gagmay nga hair cells nga magpadala ug signal sa utok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dizzy-spinning-inner-ear-g5", "domain": "LIVING_THINGS", "topic": "why spinning makes us dizzy", "grades": [5, 6, 7], "terms": ["hilo", "liyo", "spinning", "umiikot", "dizzy", "inner ear", "likido", "balanse", "tumigil", "nahihilo", "huros", "nalipong", "nagliyok", "sulod nga dalunggan", "tubig", "mihunong", "ngano malipong"], "fact": {"tl": "Kapag mabilis tayong umiikot tapos huminto, patuloy pang gumagalaw ang likido sa loob ng tainga, kaya naloloko ang utak at nahihilo tayo na para bang umiikot pa rin.", "en": "When we spin fast and then stop, the fluid in the inner ear keeps moving for a moment, so the brain is fooled and we feel dizzy as if we are still turning.", "bis": "Kung paspas tang moliyok dayon mohunong, padayon pa nga molihok ang likido sa sulod sa dalunggan, mao nga malimbongan ang utok ug malipong ta nga morag nagliyok pa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "motion-sickness-eyes-ears-g6", "domain": "LIVING_THINGS", "topic": "why riding makes some people queasy", "grades": [6, 7, 8], "terms": ["hilo sa biyahe", "motion sickness", "nasusuka", "sasakyan", "barko", "mata", "inner ear", "magkasalungat", "carsick", "seasick", "hilo sa byahe", "masuka", "sakyanan", "balanse", "sumbalik nga senyales", "ngano masuka sa byahe"], "fact": {"tl": "Nahihilo ang ilang tao sa sasakyan o barko kapag nagkakasalungat ang mensahe ng mata at ng balanseng-sentro sa tainga — ramdam ng tainga na gumagalaw tayo pero sabi ng mata ay nakatigil.", "en": "Some people get carsick or seasick when the message from the eyes disagrees with the balance center in the ear — the ear feels motion but the eyes see stillness.", "bis": "Maglipong ang ubang tawo sa sakyanan o barko kung magsumbalik ang mensahe sa mata ug sa sentro sa balanse sa dalunggan — mabati sa dalunggan nga naglihok ta apan ang mata wala makakita ug lihok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cold-blocks-ears-g5", "domain": "LIVING_THINGS", "topic": "why a cold can block the ears", "grades": [5, 6, 7], "terms": ["barado ang tainga", "sipon", "cold", "tube", "eustachian tube", "presyon", "baon ang pandinig", "plema", "blocked ear", "barado nga dalunggan", "sip-on", "tubo", "pressure", "dili kaayo madungog", "ngano barado ang dalunggan"], "fact": {"tl": "May maliit na tubo (Eustachian tube) na nag-uugnay sa tainga at lalamunan; kapag may sipon at namamaga ito, naiipit ang presyon kaya barado at parang baon ang pandinig.", "en": "A small tube (the Eustachian tube) links the ear to the throat; when a cold makes it swell shut, pressure gets trapped and hearing feels blocked or muffled.", "bis": "Adunay gamay nga tubo (Eustachian tube) nga nagdugtong sa dalunggan ug tutunlan; kung tungod sa sip-on mohubag kini ug masira, maipit ang pressure mao nga barado ug morag bungol ang pamati."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "yawn-swallow-pops-ears-g4", "domain": "LIVING_THINGS", "topic": "yawning or swallowing un-pops the ears", "grades": [4, 5, 6], "terms": ["hikab", "lunok", "yawn", "swallow", "pop", "tainga", "presyon", "eustachian tube", "airplane", "eroplano", "huy-ab", "tulon", "pop sa dalunggan", "pressure", "tubo", "balanse ng presyon", "unsaon pagpop sa dalunggan"], "fact": {"tl": "Kapag barado ang tainga sa eroplano o bundok, ang paghikab, paglunok, o pagnguya ay nagbubukas ng Eustachian tube para mapantay ang presyon at mawala ang barado.", "en": "When the ears feel blocked on a plane or mountain, yawning, swallowing, or chewing opens the Eustachian tube to equalize the pressure and clear them.", "bis": "Kung barado ang dalunggan sa eroplano o bukid, ang paghuy-ab, pagtulon, o pagusap nagaabli sa Eustachian tube aron mapantay ang pressure ug mawala ang pagkabarado."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-cant-hear-own-voice-recording-g6", "domain": "LIVING_THINGS", "topic": "why your recorded voice sounds different", "grades": [6, 7, 8], "terms": ["boses", "recording", "iba ang boses", "sariling tinig", "buto", "panginig", "hangin", "record", "kakaiba ang boses", "tingog", "rekording", "lahi ang tingog", "bukog", "kurog", "ngano lahi ang tingog sa rekording"], "fact": {"tl": "Kakaiba ang boses natin sa recording dahil sa totoong buhay, naririnig natin ang sariling tinig na dumadaan din sa buto ng bungo, hindi lang sa hangin gaya ng narinig ng iba.", "en": "Your recorded voice sounds odd because in real life you hear yourself partly through the bones of your skull, not only through the air the way others hear you.", "bis": "Lahi ang tingog nato sa rekording tungod kay sa tinuod nga kinabuhi, madungog nato ang kaugalingong tingog nga moagi sa bukog sa bagolbagol, dili lang sa hangin sama sa nadungog sa uban."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "near-far-focus-lens-g6", "domain": "LIVING_THINGS", "topic": "the lens changes shape to focus near and far", "grades": [6, 7, 8], "terms": ["lente", "lens", "nagbabago ang hugis", "malapit", "malayo", "focus", "kalamnan", "muscle", "tumpok ng liwanag", "accommodation", "lente sa mata", "mag-usab ang porma", "duol", "layo", "nagbag-o ang lente"], "fact": {"tl": "Ang lente ng mata ay nababago ang hugis — kumakapal kapag tumitingin sa malapit at nanipis kapag malayo — para palaging tumama ang focus ng liwanag sa retina.", "en": "The lens of the eye changes shape — getting rounder for near objects and flatter for far ones — so light always focuses sharply on the retina.", "bis": "Ang lente sa mata mag-usab sa porma — mokupot kung motan-aw sa duol ug monipis kung halayo — aron kanunay nga mosakto ang focus sa kahayag sa retina."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "nearsighted-farsighted-g7", "domain": "LIVING_THINGS", "topic": "nearsighted and farsighted", "grades": [7, 8, 9], "terms": ["malabo sa malayo", "malabo sa malapit", "nearsighted", "farsighted", "myopia", "salamin", "eyeglasses", "retina", "hugis ng mata", "malabo", "duol nga klaro", "layo nga hanap", "antipara", "salamin sa mata", "ngano malabo ang mata"], "fact": {"tl": "Kung masyadong mahaba ang mata, nahuhulog ang focus bago ang retina kaya malabo ang malayo (nearsighted); kung maikli, lumalagpas ang focus kaya malabo ang malapit (farsighted) — itinatama ito ng tamang salamin.", "en": "If the eyeball is too long, light focuses in front of the retina so distant things look blurry (nearsighted); if too short, it focuses behind so near things blur (farsighted) — the right glasses correct it.", "bis": "Kung sobra ka taas ang mata, ang focus mahulog sa atubangan sa retina mao nga hanap ang halayo (nearsighted); kung mubo, molabaw ang focus mao nga hanap ang duol (farsighted) — matul-id kini sa saktong antipara."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "eyes-need-time-in-dark-g5", "domain": "LIVING_THINGS", "topic": "eyes take time to adjust to the dark", "grades": [5, 6, 7], "terms": ["madilim", "adjust", "nasanay sa dilim", "dark adaptation", "rods", "retina", "ilaw", "sandali", "unti-unti", "dark", "ngitngit", "naanad sa ngitngit", "kahayag", "hinay-hinay nga makakita", "ngano dili dayon makita sa ngitngit"], "fact": {"tl": "Kapag biglang napatay ang ilaw, hindi tayo agad nakakakita, pero pagkalipas ng ilang minuto ay unti-unting napupukaw ang rods sa retina kaya nakakakita na tayo sa dilim.", "en": "When the lights suddenly go out we can't see at first, but after several minutes the rods in the retina become more sensitive and we can see in the dark.", "bis": "Kung kalit nga mapalong ang suga, dili dayon ta makakita, apan paglabay sa pila ka minuto mahimong mas sensitibo ang rods sa retina mao nga makakita na ta sa ngitngit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bright-light-shrinks-pupil-g4", "domain": "LIVING_THINGS", "topic": "why we squint in bright light", "grades": [4, 5, 6], "terms": ["nakakasilaw", "silaw", "squint", "kunot ng mata", "araw", "liwanag", "pupil", "protektahan", "sumikip ang mata", "kasilaw", "pikit-pikit", "adlaw", "kahayag", "panalipdan", "ngano mosilaw"], "fact": {"tl": "Kapag biglang sumikat ang sobrang liwanag, kusang lumiliit ang pupil at namimilipit ang mata para bawasan ang pumapasok na liwanag at maprotektahan ang loob ng mata.", "en": "When a very bright light hits us, the pupil shrinks and we squint automatically to cut down the light coming in and protect the inside of the eye.", "bis": "Kung kalit nga mosulod ang sobrang kahayag, kusog nga mo-gamay ang pupil ug mopiyong ta aron makunhuran ang kahayag nga mosulod ug mapanalipdan ang sulod sa mata."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-things-blurry-underwater-g5", "domain": "LIVING_THINGS", "topic": "why our eyes are blurry underwater", "grades": [5, 6, 7], "terms": ["malabo sa ilalim ng tubig", "underwater", "tubig", "cornea", "focus", "goggles", "salamin sa paglangoy", "mata", "blurry", "hanap sa ilawom sa tubig", "antipara sa paglangoy", "ngano hanap ilawom sa tubig"], "fact": {"tl": "Malabo ang paningin natin sa ilalim ng tubig dahil ang harapan ng mata (cornea) ay umaasa sa hangin para iangat ang focus; pinapatag ng tubig ang focus na ito kaya kailangan ng goggles para muling lumiwanag.", "en": "Our eyes go blurry underwater because the front of the eye (the cornea) needs air to help focus light; water cancels that focusing, which is why goggles make things clear again.", "bis": "Hanap ang panan-aw nato sa ilawom sa tubig tungod kay ang atubangan sa mata (cornea) nagkinahanglan ug hangin aron mo-focus sa kahayag; gipapas sa tubig kini nga focus, mao nga kinahanglan ang goggles aron mahimong klaro pag-usab."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "loud-then-quiet-ringing-g6", "domain": "LIVING_THINGS", "topic": "why ears ring after loud noise", "grades": [6, 7, 8], "terms": ["umuugong ang tainga", "ringing", "tunog matapos ang ingay", "hair cells", "pagod", "konsiyerto", "paputok", "tinnitus", "ringing ears", "ugong sa dalunggan", "balahibo nga sensor", "gikapoy", "buto", "ngano mong-ngung ang dalunggan"], "fact": {"tl": "Kapag tumahimik na pagkatapos ng sobrang ingay tulad ng paputok o konsiyerto, minsan umuugong ang tainga dahil pansamantalang napagod ang maliliit na hair cells sa loob nito.", "en": "After it goes quiet following very loud noise like fireworks or a concert, the ears sometimes ring because the tiny hair cells inside were temporarily overworked.", "bis": "Kung mohilom na human sa sobrang saba sama sa buto o konsiyerto, usahay mongung-ngung ang dalunggan tungod kay temporaryong gikapoy ang gagmay nga hair cells sa sulod niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "two-ears-locate-sound-g6", "domain": "LIVING_THINGS", "topic": "the brain locates sound by tiny time differences", "grades": [6, 7, 8], "terms": ["saan galing ang tunog", "direksyon", "dalawang tainga", "oras na pagdating", "kaliwa", "kanan", "utak", "sound direction", "asa gikan ang tingog", "duha ka dalunggan", "wala", "tuo", "oras sa pag-abot", "direksyon sa tingog", "unsaon pag-ila asa ang tingog"], "fact": {"tl": "Nadidiskubre ng utak kung saan galing ang tunog dahil bahagyang mas maaga itong umabot sa mas malapit na tainga at bahagyang mas malakas doon — napakaliit na pagkakaibang ito ay sapat na para malaman ang direksyon.", "en": "The brain works out where a sound came from because it reaches the nearer ear a tiny bit sooner and a tiny bit louder — that small difference is enough to tell the direction.", "bis": "Mahibal-an sa utok asa gikan ang tingog tungod kay gamay nga mas sayo kining moabot sa mas duol nga dalunggan ug gamay nga mas kusog didto — kanang gamay nga kalainan igo na aron mahibaloan ang direksyon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "reading-dark-not-blind-g5", "domain": "LIVING_THINGS", "topic": "reading in dim light tires but doesn't ruin eyes", "grades": [5, 6, 7], "terms": ["pagbasa sa madilim", "dim light", "nahahapo ang mata", "hindi nasisira", "pahinga", "screen", "mata", "eyestrain", "pagbasa sa hayag", "gikapoy ang mata", "dili madaut", "pahulay", "tinuod ba nga mabuta sa pagbasa sa ngitngit"], "fact": {"tl": "Ang pagbasa sa madilim ay nakakapagod at nakakapagsakit ng mata, ngunit hindi nito permanenteng sinisira ang paningin — kailangan lang ng sapat na ilaw at pahinga ng mata.", "en": "Reading in dim light tires the eyes and can give a headache, but it does not permanently damage eyesight — the eyes just need enough light and rest.", "bis": "Ang pagbasa sa ngitngit makakapoy ug makasakit sa mata, apan dili kini permanenting makadaut sa panan-aw — kinahanglan lang ug igong kahayag ug pahulay sa mata."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "color-blind-cones-g7", "domain": "LIVING_THINGS", "topic": "color blindness comes from the cones", "grades": [7, 8, 9], "terms": ["cones", "sensor ng kulay", "kulang na cone", "color blind", "retina", "tatlong uri", "pula", "berde", "asul", "sensor sa kolor", "kulang nga cone", "color blindness", "tulo ka matang", "kolor", "ngano color blind"], "fact": {"tl": "Ang normal na retina ay may tatlong uri ng cones para sa pula, berde, at asul; kapag kulang o hindi gumagana nang maayos ang isa, nagkakaroon ng color blindness ang tao.", "en": "A normal retina has three kinds of cones for red, green, and blue; when one kind is missing or works poorly, a person becomes color blind.", "bis": "Ang normal nga retina adunay tulo ka matang sa cones alang sa pula, berde, ug asul; kung kulang o dili maayong molihok ang usa, mahimong color blind ang tawo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "afterimage-staring-g5", "domain": "LIVING_THINGS", "topic": "why you see a ghost shape after staring", "grades": [5, 6, 7], "terms": ["multo ng kulay", "afterimage", "matagal na tinitigan", "mata", "nakikitang anino", "sensor na pagod", "retina", "kakaibang kulay", "tinan-aw ug dugay", "aninong kolor", "sensor nga gikapoy", "ngano adunay nahabilin nga imahe"], "fact": {"tl": "Kapag matagal mong tinitigan ang isang maliwanag na kulay tapos lumingon sa puti, may nakikita kang 'multo' ng kabaligtarang kulay dahil pansamantalang napagod ang mga sensor sa retina.", "en": "If you stare at a bright color for a while then look at white, you see a 'ghost' image in the opposite color because those retina sensors got temporarily tired.", "bis": "Kung dugay nimong tan-awon ang usa ka hayag nga kolor dayon motan-aw sa puti, makakita kag 'aninong' hulagway sa atbang nga kolor tungod kay temporaryong gikapoy ang mga sensor sa retina."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-elderly-need-reading-glasses-g6", "domain": "LIVING_THINGS", "topic": "why older people need reading glasses", "grades": [6, 7, 8], "terms": ["matanda", "reading glasses", "salamin sa pagbasa", "lente", "tumigas", "malapit na basa", "presbyopia", "edad", "tigulang", "mutig-a", "duol nga pagbasa", "ngano nagsalamin ang tigulang"], "fact": {"tl": "Habang tumatanda ang tao, unti-unting tumitigas ang lente ng mata kaya nahihirapan itong magbago ng hugis para sa malapit — kaya maraming nakatatanda ang nangangailangan ng salamin sa pagbasa.", "en": "As people get older, the eye's lens slowly gets stiffer and can no longer change shape easily for close-up, which is why many older people need reading glasses.", "bis": "Samtang motigulang ang tawo, hinay-hinay nga mutig-a ang lente sa mata mao nga maglisod na kini sa pag-usab sa porma alang sa duol — mao nga daghang tigulang ang nagkinahanglan ug salamin sa pagbasa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "animals-see-different-colors-g6", "domain": "LIVING_THINGS", "topic": "animals see colors differently from us", "grades": [6, 7, 8], "terms": ["hayop", "kulay", "aso", "bubuyog", "ultraviolet", "iba ang nakikita", "kulay na hindi natin nakikita", "animal vision", "kolor", "iro", "buyog", "lahi ang makita", "kolor nga dili nato makita", "unsaon pagtan-aw sa kolor sa hayop"], "fact": {"tl": "Iba-iba ang nakikitang kulay ng mga hayop: ang aso ay may mas kaunting kulay kaysa atin, samantalang ang bubuyog ay nakakakita ng ultraviolet na patterns sa bulaklak na hindi natin nakikita.", "en": "Animals see colors differently from us: a dog sees fewer colors than we do, while a bee can see ultraviolet patterns on flowers that are invisible to humans.", "bis": "Lahi-lahi ang makita nga kolor sa mga hayop: ang iro adunay mas gamay nga kolor kaysa nato, samtang ang buyog makakita ug ultraviolet nga pattern sa bulak nga dili nato makita."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-we-blush-g4", "domain": "LIVING_THINGS", "topic": "why we blush", "grades": [4, 5, 6], "terms": ["blush", "blushing", "namumula", "mukha", "pisngi", "hiya", "kahihiyan", "cheeks", "face turns red", "red", "pula", "namula", "blood vessels", "ugat ng dugo", "mamula", "namumula ang mukha", "mapula", "nahihiya", "ulaw", "naulaw", "mamula ang nawong", "nawong", "aping", "dugo", "nervous", "kabado"], "fact": {"tl": "Namumula tayo kapag nahihiya dahil ang utak ay nagpapadala ng senyas na nagpapalapad sa maliliit na ugat ng dugo sa pisngi, kaya mas maraming dugo ang dumadaloy doon at namumula ang mukha.", "en": "We blush when we feel shy because the brain sends a signal that widens the tiny blood vessels in our cheeks, so more blood flows there and the face turns red.", "bis": "Mamula ta kon maulaw kay ang utok magpadala og senyas nga magpalapad sa gagmay nga mga ugat sa dugo sa aping, mao nga daghan og dugo ang moagi didto ug mamula ang nawong."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-we-shiver-makes-heat-g4", "domain": "LIVING_THINGS", "topic": "why shivering warms us", "grades": [4, 5, 6], "terms": ["shiver", "shivering", "nginig", "nangangatog", "kalamig", "panginginig", "ginaw", "manginig", "kuyaw", "kurog", "nangurog", "muscles", "kalamnan", "kaunoran", "init", "heat", "warm", "trembling", "involuntary", "kusog", "kabog", "kabog-kabog", "tugnaw", "gikurog", "mainit", "temperatura sa lawas", "gininaw"], "fact": {"tl": "Nangangatog tayo kapag malamig dahil mabilis na nagkukontra at nag-uunat ang ating mga kalamnan nang paulit-ulit; ang pabigla-biglang galaw na ito ay gumagawa ng init para painitin ang katawan.", "en": "We shiver when it is cold because our muscles quickly tighten and relax over and over; this rapid movement makes heat that warms the body.", "bis": "Mangurog ta kon bugnaw kay ang atong mga kaunoran paspas nga magkuntra ug magluag balikbalik; kini nga paspas nga lihok maghimo og init aron painiton ang lawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-we-cry-emotional-tears-g4", "domain": "LIVING_THINGS", "topic": "why we cry tears", "grades": [4, 5, 6], "terms": ["cry", "crying", "luha", "umiiyak", "iyak", "tears", "emosyon", "lungkot", "saya", "tumutulo", "umuiyak", "tumulo ang luha", "hilak", "naghilak", "gluha", "mga luha", "emotion", "sad", "masaya", "stress", "gland", "glandula", "tear gland", "mata", "nagaluha", "naghilak", "kasubo", "kalipay"], "fact": {"tl": "Iba't ibang dahilan ng pag-iyak: meron tayong luha na nililinis ang mata, at meron ding luha kapag may malakas na nararamdaman tulad ng lungkot o tuwa — naniniwala ang mga siyentipiko na nakatutulong itong magpalabas at magpahupa ng damdamin.", "en": "We cry for different reasons: some tears clean and protect the eyes, and other tears come from strong feelings like sadness or joy — scientists think these emotional tears help release and ease our feelings.", "bis": "Adunay nagkalainlaing hinungdan sa paghilak: ang ubang luha maglimpyo ug magpanalipod sa mata, ug ang ubang luha mogawas kon kusog ang atong gibati sama sa kasubo o kalipay — gituohan sa mga siyentista nga kini nga mga luha makatabang sa pagpagawas ug pagpahupay sa atong gibati."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-eyes-shut-when-sneezing-g4", "domain": "LIVING_THINGS", "topic": "why we close eyes when we sneeze", "grades": [4, 5, 6], "terms": ["sneeze", "sneezing", "bahing", "bumabahing", "napikit", "pumipikit", "mata", "reflex", "mapikit", "nagbahing", "bumahing", "close eyes", "shut eyes", "pumikit", "automatic", "kusang", "mapiyong", "piyong", "nangbahing", "mata mopiyong", "gipiyong", "awtomatiko"], "fact": {"tl": "Kapag bumabahing tayo, kusang napipikit ang ating mga mata — isa itong reflex na hindi natin kontrolado, kaya hindi mo halos mapanatiling dilat ang mga mata habang bumabahing.", "en": "When we sneeze, our eyes shut on their own — it is a reflex we do not control, which is why it is almost impossible to keep your eyes open during a sneeze.", "bis": "Kon mobahing ta, ang atong mga mata mopiyong sa ilang kaugalingon — usa kini ka reflex nga dili nato makontrolar, mao nga halos imposible nga buka ang mga mata samtang nagbahing."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-sneeze-is-fast-g5", "domain": "LIVING_THINGS", "topic": "how fast a sneeze travels", "grades": [5, 6, 7], "terms": ["sneeze", "bahing", "bilis", "mabilis", "hangin", "air", "fast", "speed", "bumahing", "ilong", "throat", "lalamunan", "mucus", "plema", "sipon", "droplets", "patak", "kalat", "kumalat", "paspas", "kusog sa hangin", "gibahing", "tutunlan", "laway", "mikalat", "mga tulo", "tulo"], "fact": {"tl": "Ang hangin na pinapalabas ng isang bahing ay napakabilis — kaya kumakalat ito nang malayo at madali nitong maipalipad ang mga mikrobyo, kung kaya dapat tayong magtakip ng bibig o ilong.", "en": "The air blasted out by a sneeze moves very fast — so it spreads far and easily carries germs through the air, which is why we should cover our mouth or nose.", "bis": "Ang hangin nga gipagawas sa usa ka bahing kusog kaayo — mao nga mikalat kini og layo ug sayon nga makadala og mga mikrobyo sa hangin, mao nga kinahanglan natong taboran ang baba o ilong."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-yawn-contagious-g4", "domain": "LIVING_THINGS", "topic": "why yawns are contagious", "grades": [4, 5, 6], "terms": ["yawn", "yawning", "hikab", "humihikab", "nahahawa", "contagious", "nakakahawa", "humikab", "naghikab", "mahikab", "catch", "copy", "ginagaya", "empathy", "brain", "utak", "makita", "seeing", "nakahikab", "makahawa", "nahikab", "gusto mohikab", "makita ang lain", "gibati"], "fact": {"tl": "Madalas tayong humikab kapag nakita nating may humihikab — tinatawag itong nakakahawang paghikab, at ito ay nauugnay sa kung paano natural na ginagaya ng ating utak ang ginagawa ng ibang tao.", "en": "We often yawn when we see someone else yawn — this is called contagious yawning, and it is linked to how our brain naturally copies what other people do.", "bis": "Sagad ta mohikab kon makita natong adunay nahikab — gitawag kining makatakod nga paghikab, ug kini nalambigit sa kung giunsa pagsundog sa atong utok ang gibuhat sa ubang tawo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-we-stretch-waking-g3", "domain": "LIVING_THINGS", "topic": "why we stretch when we wake up", "grades": [3, 4, 5], "terms": ["stretch", "stretching", "pag-inat", "umiinat", "gising", "waking", "umaga", "morning", "kalamnan", "muscles", "dugo", "blood", "mag-inat", "nag-inat", "tulog", "sleep", "yawn", "banat", "mibanat", "paglihok", "muscle", "nagbanat", "nakatulog", "pagmata", "lawas", "mibati"], "fact": {"tl": "Kapag bagong gising tayo, kusang umiinat ang ating katawan dahil ang mga kalamnan ay nanigas habang natutulog; ang pag-inat ay nagpapadaloy ng dugo at nagpapagising sa mga kalamnan.", "en": "When we just wake up, our body stretches on its own because the muscles stiffened during sleep; stretching gets blood flowing and wakes the muscles up.", "bis": "Kon bag-o pa lang ta nimata, ang atong lawas mobanat sa kaugalingon kay ang mga kaunoran nagahi samtang natulog; ang pagbanat magpadagayday sa dugo ug magpukaw sa mga kaunoran."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-pins-and-needles-g4", "domain": "LIVING_THINGS", "topic": "why limbs fall asleep", "grades": [4, 5, 6], "terms": ["pins and needles", "ngalay", "manhid", "numb", "tingling", "kuryente", "kiliti", "nangangalay", "namamanhid", "paa", "kamay", "nerves", "nerbiyo", "ugat", "blood flow", "dugo", "kuryente sa paa", "nangalay", "leg falls asleep", "makuyaw", "gipanuhot", "nilipong", "kamay natulog", "panuhot", "gipanihol"], "fact": {"tl": "Kapag matagal nating idinaganan o tiniklop ang isang paa o kamay, nababawasan ang daloy ng dugo at napipindot ang mga nerbiyo, kaya nararamdaman natin ang parang kuryente o pangangalay; nawawala ito kapag dumaloy ulit ang dugo.", "en": "When we sit or lie on a leg or arm too long, blood flow is reduced and the nerves get pressed, so we feel a tingling 'pins and needles' — it goes away when blood flows again.", "bis": "Kon dugay natong gipuy-an o gipilo ang usa ka tiil o bukton, makunhuran ang dagan sa dugo ug mapislit ang mga nerbiyo, mao nga atong mabati ang murag kuryente o pamanhid; mawala kini kon modagayday na usab ang dugo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-butterflies-in-stomach-g5", "domain": "LIVING_THINGS", "topic": "butterflies in the stomach when nervous", "grades": [5, 6, 7], "terms": ["butterflies in stomach", "kabog ng tiyan", "kaba", "kinakabahan", "tiyan", "nervous", "kinikilig", "kabado", "sikmura", "nervous feeling", "kaba sa tiyan", "kumukulo", "adrenaline", "brain-gut", "utak", "nahadlok", "kulba", "gikulbaan", "tiyan murag kabog", "gikuyawan", "stress", "sympathetic"], "fact": {"tl": "Kapag kinakabahan tayo, naglalabas ang katawan ng kemikal na naghahanda sa atin sa 'laban o takbo,' at binabawasan nito ang daloy ng dugo sa tiyan — kaya nararamdaman natin ang kakaibang 'kabog' o paru-paro sa loob ng sikmura.", "en": "When we feel nervous, the body releases a chemical that gets us ready to 'fight or flee,' and it reduces blood flow to the stomach — so we feel that strange fluttering 'butterflies' inside the tummy.", "bis": "Kon kulbaan ta, ang lawas mopagawas og kemikal nga mag-andam nato sa 'pakig-away o pagdagan,' ug makunhuran niini ang dagan sa dugo sa tiyan — mao nga atong mabati ang lahi nga murag kabog o alibangbang sa sulod sa tiyan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-fingers-prune-water-g4", "domain": "LIVING_THINGS", "topic": "why fingers wrinkle in water", "grades": [4, 5, 6], "terms": ["fingers wrinkle", "prune", "kulubot", "kunot", "daliri", "kamay", "wrinkled fingers", "tubig", "water", "matagal sa tubig", "nakulubot", "balat", "skin", "nerves", "grip", "hawak", "kunot ng daliri", "kulubot sa tudlo", "tudlo", "naligo", "ligo", "balat nagkunot", "nerbiyo", "gikulubot", "kunot-kunot", "paliguan"], "fact": {"tl": "Kapag matagal tayong nasa tubig, nagkukulubot ang balat ng ating mga daliri — naniniwala ang mga siyentipiko na ito ay kontrolado ng nervous system at maaaring tumulong para mas matatag tayong makahawak ng basang bagay.", "en": "When we stay in water a long time, the skin on our fingers wrinkles — scientists think this is controlled by the nervous system and may help us grip wet things more firmly.", "bis": "Kon dugay ta sa tubig, mokunot ang panit sa atong mga tudlo — gituohan sa mga siyentista nga kini gikontrol sa nervous system ug mahimong makatabang nato nga mas lig-on nga makagunit og basa nga mga butang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-scabs-itch-g4", "domain": "LIVING_THINGS", "topic": "why a healing scab itches", "grades": [4, 5, 6], "terms": ["scab", "itch", "langib", "makati", "sugat", "gumagaling", "healing", "wound", "kati", "nangangati", "scab itchy", "makati ang langib", "balat", "skin", "bagong balat", "new skin", "nerbiyo", "nerves", "kamot", "kagid", "katol", "nangatol", "kati sa samad", "samad", "naayo", "gumaling", "gikatol", "bag-ong panit"], "fact": {"tl": "Kapag gumagaling ang isang sugat, madalas itong makati dahil bumubuo ang balat ng bagong selula at naistimula ang mga nerbiyo sa ilalim ng langib — pero mas mabuting huwag itong kamutin para hindi mabuksan ulit.", "en": "When a wound is healing, it often itches because the skin is building new cells and the nerves under the scab get stirred — but it is better not to scratch it so it does not reopen.", "bis": "Kon naayo ang usa ka samad, sagad kini makatol kay ang panit naghimo og bag-ong mga selula ug nasamok ang mga nerbiyo ilalom sa langib — apan mas maayo nga dili kini kamuton aron dili mabuka pag-usab."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-scar-looks-different-g5", "domain": "LIVING_THINGS", "topic": "why scars look different from skin", "grades": [5, 6, 7], "terms": ["scar", "peklat", "piklat", "sugat", "wound", "skin", "balat", "scar tissue", "collagen", "gumaling", "healed", "gasgas", "tatak ng sugat", "mark", "walang buhok", "kupas", "scar skin different", "piklat sa samad", "uwat", "samad naayo", "panit", "kupas ang kolor", "peklat", "tatak", "kolagen"], "fact": {"tl": "Kapag malalim ang sugat, ang bagong balat na bumubuo ay gawa sa ibang uri ng hibla (collagen) na hindi kasing-pinong tulad ng dating balat — kaya ang peklat ay madalas na mas makinis, walang buhok, at iba ang kulay.", "en": "When a cut is deep, the new skin that forms is made of a different kind of fiber (collagen) that is not as fine as the original skin — so a scar often looks smoother, has no hair, and is a different color.", "bis": "Kon lawom ang samad, ang bag-ong panit nga maporma hinimo sa lahi nga matang sa lanot (collagen) nga dili sama kapino sa orihinal nga panit — mao nga ang piklat sagad mas hamis, walay buhok, ug lahi og kolor."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-bruise-changes-color-g5", "domain": "LIVING_THINGS", "topic": "why bruises change color", "grades": [5, 6, 7], "terms": ["bruise", "pasa", "color", "kulay", "umiitim", "nangangasul", "violet", "yellow", "green", "dilaw", "berde", "asul", "nagiging dilaw", "dugo", "blood", "gumagaling", "healing", "pasa nagbago kulay", "heal", "bruise color change", "bun-og", "nangitngit", "nangasul", "dugo nabuak", "gibun-og", "nag-ilis kolor", "pagkaayo"], "fact": {"tl": "Ang pasa ay nagbabago ng kulay habang gumagaling — pula o lila ito sa simula, pagkatapos ay nagiging asul, luntian, at dilaw, dahil unti-unting sinisira at nililinis ng katawan ang nabuong dugo sa ilalim ng balat.", "en": "A bruise changes color as it heals — it starts red or purple, then turns blue, green, and yellow, because the body slowly breaks down and cleans up the trapped blood under the skin.", "bis": "Ang bun-og mag-ilis og kolor samtang naayo — pula o lila kini sa sinugdan, dayon mahimong asul, lunhaw, ug dalag, kay hinayhinay nga gibungkag ug gilimpyohan sa lawas ang naipit nga dugo ilalom sa panit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-cant-tickle-yourself-g4", "domain": "LIVING_THINGS", "topic": "why you cannot tickle yourself", "grades": [4, 5, 6], "terms": ["tickle", "kiliti", "kinikiliti", "sarili", "yourself", "cannot tickle self", "tumatawa", "kiliti sa sarili", "utak", "brain", "predict", "alam", "expected", "hindi makiliti", "kilitiin", "makiliti", "gikiliti", "kiliti sa kaugalingon", "dili makiliti", "utok", "gibati", "masulti sa utok"], "fact": {"tl": "Hindi mo makikiliti ang iyong sarili dahil alam na ng iyong utak kung saan at kailan mo ito gagawin, kaya hindi ito nagulat — ang kiliti ay nangangailangan ng pagkagulat na dulot ng ibang tao.", "en": "You cannot tickle yourself because your brain already knows where and when you will do it, so it is not surprised — tickling needs the surprise that comes from another person.", "bis": "Dili nimo makiliti ang imong kaugalingon kay ang imong utok nahibalo na kung asa ug kanus-a nimo kini buhaton, mao nga dili kini matingala — ang kiliti nagkinahanglan og katingala nga gikan sa lain nga tawo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-dizzy-after-spinning-g4", "domain": "LIVING_THINGS", "topic": "why we feel dizzy after spinning", "grades": [4, 5, 6], "terms": ["dizzy", "spinning", "umiikot", "nahihilo", "hilo", "liyo", "spin", "umiinog", "tainga", "ear", "tubig sa tainga", "fluid", "balance", "balanse", "inner ear", "nahilo", "nahiliyo", "liyo-liyo", "umiikot ang paligid", "gilipong", "nilipong", "tubig sa dalunggan", "dalunggan", "balanse sa lawas", "mibalik"], "fact": {"tl": "May likido sa loob ng ating tainga na tumutulong sa balanse; kapag mabilis tayong umiikot, patuloy na gumagalaw ang likidong ito kahit huminto na tayo — kaya pakiramdam natin ay umiikot pa rin ang paligid at nahihilo tayo.", "en": "There is fluid inside our ears that helps with balance; when we spin fast, that fluid keeps moving even after we stop — so it feels like the room is still spinning and we get dizzy.", "bis": "Adunay likido sa sulod sa atong dalunggan nga makatabang sa balanse; kon paspas tang moliyok, kini nga likido magpadayon sa paglihok bisan human ta mohunong — mao nga murag nagtuyok pa ang palibot ug malipong ta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-brain-freeze-g4", "domain": "LIVING_THINGS", "topic": "why ice cream gives brain freeze", "grades": [4, 5, 6], "terms": ["brain freeze", "ice cream headache", "sakit ng ulo", "malamig", "ice cream", "sorbetes", "mabilis kumain", "cold", "kalamig", "ngalangala", "roof of mouth", "nerbiyo", "nerve", "ugat", "headache", "sakit ulo sa lamig", "brain freeze sorbetes", "halo-halo", "gisakit ang ulo", "bugnaw", "bugnaw nga pagkaon", "nerbiyo sa baba", "kalit", "tugnaw"], "fact": {"tl": "Kapag mabilis tayong kumain ng napakalamig tulad ng sorbetes o halo-halo, ang biglang lamig sa ngalangala ng bibig ay nakakaapekto sa mga ugat at nerbiyo doon — kaya panandaliang sumasakit ang ulo, na tinatawag na 'brain freeze.'", "en": "When we eat something very cold like ice cream fast, the sudden cold on the roof of the mouth affects the blood vessels and nerves there — so we briefly feel a headache called 'brain freeze.'", "bis": "Kon paspas tang mokaon og bugnaw kaayo sama sa sorbetes o halo-halo, ang kalit nga kabugnaw sa ngalangala sa baba makaapekto sa mga ugat ug nerbiyo didto — mao nga makadiyot nga masakit ang ulo, nga gitawag og 'brain freeze.'"}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-we-burp-g3", "domain": "LIVING_THINGS", "topic": "why we burp", "grades": [3, 4, 5], "terms": ["burp", "dighay", "dumighay", "hangin", "air", "tiyan", "swallow", "nakalunok", "gas", "bumusog", "pagkain", "soda", "carbonated", "umiinom", "burping", "dighay sa tiyan", "pagbusog", "gidighay", "tutunlan", "baba", "sapaw", "nilamoy nga hangin", "gas sa tiyan", "mibusog"], "fact": {"tl": "Dumidighay tayo kapag may sobrang hangin sa loob ng tiyan — madalas itong galing sa hanging nalulunok natin habang kumakain, umiinom, o uminom ng soda; pinapalabas ito ng katawan pataas sa bibig.", "en": "We burp when there is extra air in the stomach — it often comes from air we swallow while eating, drinking, or having soda; the body pushes it back up and out the mouth.", "bis": "Modighay ta kon adunay sobra nga hangin sa sulod sa tiyan — sagad kini gikan sa hangin nga atong nalamoy samtang nagkaon, nag-inom, o nag-inom og soda; gitulod kini sa lawas pataas ug mogawas sa baba."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-we-pass-gas-g4", "domain": "LIVING_THINGS", "topic": "why we pass gas", "grades": [4, 5, 6], "terms": ["fart", "pass gas", "utot", "umuutot", "gas", "hangin", "bituka", "intestines", "bacteria", "mikrobyo", "digesting", "tinutunaw", "food", "pagkain", "umutot", "gas sa tiyan", "kabag", "gas sa bituka", "gikutkot", "mikrobyo sa tinai", "tinai", "na-tunaw", "tunaw"], "fact": {"tl": "Umuutot tayo dahil habang tinutunaw ng mabubuting bakterya sa ating bituka ang ilang pagkain, gumagawa sila ng gas; kapag nag-ipon na ang gas na ito, pinapalabas ito ng katawan — normal at malusog ito.", "en": "We pass gas because as the helpful bacteria in our intestines break down some foods, they make gas; when that gas builds up, the body lets it out — it is normal and healthy.", "bis": "Mokutkot ta kay samtang gibungkag sa mabuot nga bakterya sa atong tinai ang ubang pagkaon, maghimo silag gas; kon matigom na kini nga gas, ipagawas kini sa lawas — normal ug himsog kini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-sleepy-after-eating-g4", "domain": "LIVING_THINGS", "topic": "why we feel sleepy after a big meal", "grades": [4, 5, 6], "terms": ["sleepy after eating", "antok pagkakain", "busog", "nakakaantok", "kumain", "full meal", "tulog", "pagtunaw", "digestion", "dugo", "blood", "tiyan", "antok matapos kumain", "busog antok", "mabusog", "sleepy full", "tinunaw", "gikatulgon human mokaon", "gibusog", "dugo sa tiyan", "pagtunaw sa pagkaon", "gikapoy"], "fact": {"tl": "Madalas tayong inaantok matapos kumain ng marami dahil ang katawan ay nagpapadala ng mas maraming dugo sa tiyan para tumulong sa pagtunaw ng pagkain, at may mga kemikal sa pagkain na nagpapakalma sa atin.", "en": "We often feel sleepy after a big meal because the body sends more blood to the stomach to help digest the food, and some chemicals in food make us feel calm.", "bis": "Sagad tang katulgon human mokaon og daghan kay ang lawas magpadala og mas daghang dugo sa tiyan aron motabang sa pagtunaw sa pagkaon, ug adunay mga kemikal sa pagkaon nga magpakalma nato."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-we-dream-most-in-rem-g6", "domain": "LIVING_THINGS", "topic": "sleep stages and when we dream", "grades": [6, 7, 8], "terms": ["sleep stages", "REM", "panaginip", "tulog", "deep sleep", "mahimbing", "yugto ng tulog", "brain active", "utak", "mata gumagalaw", "dream", "stages of sleep", "mahimbing na tulog", "cycle", "ikot ng tulog", "panaginip sa REM", "damgo", "lawom nga tulog", "yugto", "utok aktibo", "mata nagalihok", "gikatulgon", "yugto sa tulog"], "fact": {"tl": "Ang tulog ay may iba't ibang yugto na paulit-ulit sa buong gabi; pinakamadalas tayong nananaginip sa yugtong tinatawag na REM, kung saan mabilis na gumagalaw ang mga mata at napaka-aktibo ng utak kahit tulog tayo.", "en": "Sleep has different stages that repeat through the night; we dream most during the stage called REM, when the eyes move quickly and the brain is very active even though we are asleep.", "bis": "Ang tulog adunay nagkalainlaing yugto nga magbalikbalik sa tibuok gabii; sagad tang magdamgo sa yugto nga gitawag og REM, diin paspas nga magalihok ang mga mata ug aktibo kaayo ang utok bisan natulog ta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-we-forget-dreams-g5", "domain": "LIVING_THINGS", "topic": "why we forget our dreams", "grades": [5, 6, 7], "terms": ["forget dreams", "nakakalimot panaginip", "panaginip", "dream", "memory", "ala-ala", "nalimutan", "utak", "brain", "gising", "wake up", "hindi natatandaan", "forgetting dreams", "nakalimot sa damgo", "damgo", "nahikalimtan", "panumduman", "utok", "nimata", "wala matandaan", "gikalimtan", "memorya", "panaginip nalimutan"], "fact": {"tl": "Madalas nating nakakalimutan ang ating mga panaginip dahil habang tayo ay natutulog, hindi maganda ang pag-iimbak ng utak ng bagong ala-ala — kaya kung gigising ka agad pagkatapos managinip, mas malaki ang tsansang matandaan mo ito.", "en": "We often forget our dreams because while we sleep, the brain does not store new memories well — so if you wake right after a dream, you are more likely to remember it.", "bis": "Sagad natong makalimtan ang atong mga damgo kay samtang natulog ta, dili maayo ang pagtipig sa utok og bag-ong panumduman — mao nga kon momata ka dayon human magdamgo, mas dako ang posibilidad nga imong mahinumduman kini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-stomach-growls-not-only-hungry-g5", "domain": "LIVING_THINGS", "topic": "stomach growls even when not hungry", "grades": [5, 6, 7], "terms": ["stomach growl", "kalam", "kumakalam", "kumakalog ang tiyan", "bituka", "intestines", "muscle squeeze", "gutom", "hungry", "hindi gutom", "digesting", "gas", "not hungry", "tunog ng tiyan", "gakalibang ang tiyan", "kagil-it sa tiyan", "tiyan nagngulob", "tinai", "tunaw", "gakalibang", "ngulob", "tiyan tunog", "gas sa tinai"], "fact": {"tl": "Kumukulo ang tiyan kahit hindi tayo gutom dahil patuloy na gumagalaw ang mga kalamnan ng tiyan at bituka para itulak ang pagkain at gas — mas malakas lang ang tunog kapag walang laman ang tiyan.", "en": "The stomach growls even when we are not hungry because the muscles of the stomach and intestines keep moving to push food and gas along — the sound is just louder when the stomach is empty.", "bis": "Magngulob ang tiyan bisan dili ta gutom kay ang mga kaunoran sa tiyan ug tinai magpadayon sa paglihok aron itulod ang pagkaon ug gas — mas kusog lang ang tingog kon walay sulod ang tiyan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-yawn-watery-eyes-g4", "domain": "LIVING_THINGS", "topic": "why eyes water when we yawn", "grades": [4, 5, 6], "terms": ["watery eyes yawn", "luha sa paghikab", "hikab", "yawn", "luha", "tears", "mata", "umiipit", "squeeze", "tear gland", "glandula ng luha", "tumutulo", "mata tumutubig", "yawn tears", "naluluha", "nagaluha kon mohikab", "mata nagtubig", "gipuga", "glandula", "nagaluha", "luha mogawas"], "fact": {"tl": "Kapag humihikab tayo, kusang naiipit ng pisngi at mukha ang maliliit na glandula na gumagawa ng luha, kaya minsan ay tumutulo ang luha o tumutubig ang ating mga mata.", "en": "When we yawn, our cheeks and face gently squeeze the tiny glands that make tears, so sometimes our eyes water or a tear rolls out.", "bis": "Kon mohikab ta, ang atong aping ug nawong hinayhinay nga makapuga sa gagmay nga mga glandula nga maghimo og luha, mao nga usahay magtubig ang atong mga mata o adunay luha nga mogawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-cuts-stop-bleeding-platelets-g6", "domain": "LIVING_THINGS", "topic": "how blood clots to stop bleeding", "grades": [6, 7, 8], "terms": ["blood clot", "platelets", "plaketa", "sugat", "tumitigil dugo", "bleeding stop", "namumuo", "clot", "dugo", "tumigil ang dugo", "wound", "cut", "plug", "tumatak", "clotting", "namumuong dugo", "gibara ang dugo", "dugo mihunong", "samad", "mamuo ang dugo", "langib", "mibara", "selula sa dugo"], "fact": {"tl": "Kapag nasugatan tayo, ang maliliit na bahagi ng dugo na tinatawag na platelets ay nagdidikit-dikit sa sugat at gumagawa ng tapon para pigilin ang pagdurugo, na unti-unting nagiging langib.", "en": "When we get a cut, tiny parts of the blood called platelets stick together at the wound and form a plug to stop the bleeding, which slowly becomes a scab.", "bis": "Kon masamdan ta, ang gagmay nga bahin sa dugo nga gitawag og platelets magdikitdikit sa samad ug maghimo og pasak aron hunongon ang pag-agas sa dugo, nga hinayhinay nga mahimong langib."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-we-sweat-when-nervous-g5", "domain": "LIVING_THINGS", "topic": "why we sweat when nervous", "grades": [5, 6, 7], "terms": ["nervous sweat", "pawis sa kaba", "kabado", "kinakabahan", "cold sweat", "malamig na pawis", "sweat", "pawis", "kamay basa", "sweaty palms", "stress", "takot", "fear", "palad", "pinagpapawisan", "gikulbaan nga singot", "singot sa kulba", "gisingot", "kamay nagsingot", "kulba", "hadlok", "palad basa", "singot sa kahadlok"], "fact": {"tl": "Pinagpapawisan tayo kapag kinakabahan o natatakot dahil ang katawan ay naghahanda sa 'laban o takbo,' kaya naglalabas ito ng pawis kahit hindi mainit — kaya bumabasa ang ating mga palad kapag kabado.", "en": "We sweat when nervous or scared because the body is getting ready to 'fight or flee,' so it releases sweat even when it is not hot — that is why our palms get damp when we are anxious.", "bis": "Magsingot ta kon kulbaan o mahadlok kay ang lawas mag-andam sa 'pakig-away o pagdagan,' mao nga mopagawas kini og singot bisan dili init — mao nga mobasa ang atong mga palad kon kulbaan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-funny-bone-tingles-g5", "domain": "LIVING_THINGS", "topic": "why hitting your elbow tingles", "grades": [5, 6, 7], "terms": ["funny bone", "siko", "elbow", "kuryente sa siko", "tingle", "kuryente", "nerbiyo", "nerve", "numb", "manhid", "ulnar", "nabangga ang siko", "elbow hit", "kuryente sa braso", "siko nabunggo", "nerbiyo sa siko", "gikuryente", "manhid sa kamay", "braso", "gibun-og ang siko", "panuhot", "gipanuhot"], "fact": {"tl": "May nerbiyo na dumadaan malapit sa balat sa iyong siko; kapag naumpog mo ito, parang nakuryente ka at namamanhid o kumikiliti ang braso pababa sa mga daliri — kaya tinatawag itong 'funny bone.'", "en": "A nerve runs close to the skin at your elbow; when you bump it, you feel a jolt like electricity and your arm tingles or goes numb down to the fingers — that is why it is called the 'funny bone.'", "bis": "Adunay nerbiyo nga moagi duol sa panit sa imong siko; kon mabunggo nimo kini, mura kag gikuryente ug ang imong bukton manuhot o mamanhid hangtod sa mga tudlo — mao nga gitawag kining 'funny bone.'"}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-morning-breath-g4", "domain": "LIVING_THINGS", "topic": "why we have morning breath", "grades": [4, 5, 6], "terms": ["morning breath", "mabahong hininga sa umaga", "hininga", "breath", "bibig", "mouth", "laway", "saliva", "bacteria", "bakterya", "amoy", "mabaho", "tuyo", "dry mouth", "tulog", "umaga", "baho ng bibig sa umaga", "baba", "ginhawa", "laway nikunhod", "bakterya sa baba", "mabaho nga ginhawa", "mamala ang baba", "gabaho"], "fact": {"tl": "Kapag natutulog tayo, bumababa ang laway sa ating bibig, kaya dumarami ang bakterya na nagdudulot ng amoy — kaya may 'morning breath' tayo pagkagising, at nawawala ito kapag nagsipilyo at uminom ng tubig.", "en": "While we sleep, our mouth makes less saliva, so the smell-causing bacteria grow more — that is why we have 'morning breath' when we wake, and it goes away when we brush and drink water.", "bis": "Samtang natulog ta, mokunhod ang laway sa atong baba, mao nga modaghan ang bakterya nga maghatag og baho — mao nga aduna tay 'morning breath' kon momata, ug mawala kini kon magsepilyo ug moinom og tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-shiver-with-fever-g5", "domain": "LIVING_THINGS", "topic": "why we shiver and feel cold with a fever", "grades": [5, 6, 7], "terms": ["fever chills", "panginginig sa lagnat", "lagnat", "fever", "nangangatog", "ginaw", "kahit mainit", "chills", "temperatura", "raise temperature", "immune", "kalaban sakit", "nginig sa lagnat", "gininaw bisan init", "hilanat", "kurog sa hilanat", "gininaw", "init sa lawas", "panalipod", "mikrobyo", "temperatura sa lawas", "gikurog", "lawas init"], "fact": {"tl": "Kapag may lagnat, itinataas ng katawan ang sarili nitong init para labanan ang mikrobyo; dahil mas mataas na ngayon ang target ng init, pakiramdam natin ay malamig tayo at nangangatog — kahit mainit na ang katawan.", "en": "With a fever, the body raises its own heat to fight germs; because the body's target temperature is now higher, we feel cold and shiver — even though the body is already hot.", "bis": "Kon adunay hilanat, ang lawas mopataas sa kaugalingong init aron makig-away sa mga mikrobyo; tungod kay mas taas na karon ang target nga init, mura tag gininaw ug mangurog — bisan init na ang lawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-we-get-hungry-tummy-signal-g4", "domain": "LIVING_THINGS", "topic": "how the body tells us we are hungry", "grades": [4, 5, 6], "terms": ["hungry", "gutom", "nagugutom", "tiyan", "stomach", "brain", "utak", "senyas", "signal", "kemikal", "hunger", "kumalam", "empty stomach", "gutom na", "kumakalam ang tiyan", "gigutom", "hunger signal", "tiyan walay sulod", "utok", "kemikal sa lawas", "senyas sa lawas", "kumakalam", "kalam", "mibati og gutom"], "fact": {"tl": "Nararamdaman nating gutom dahil kapag walang laman ang tiyan, naglalabas ito ng kemikal na nagsasabi sa utak na oras na para kumain — kaya kumakalam ang tiyan at iniisip natin ang pagkain.", "en": "We feel hungry because when the stomach is empty, it releases a chemical that tells the brain it is time to eat — so the tummy rumbles and we start thinking about food.", "bis": "Mobati tang gutom kay kon walay sulod ang tiyan, mopagawas kini og kemikal nga magsulti sa utok nga oras na para mokaon — mao nga magkalibang ang tiyan ug maghunahuna ta og pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-baby-teeth-fall-out-g3", "domain": "LIVING_THINGS", "topic": "why milk teeth fall out", "grades": [3, 4], "terms": ["bagang", "gatas na ngipin", "gatasong ngipin", "nalalaglag", "nangangati", "permanenteng ngipin", "ugat", "natutunaw", "ngipon sa gatas", "matangtang", "permanente nga ngipon", "gamot", "milk teeth", "baby teeth fall out", "root dissolves"], "fact": {"tl": "Hindi basta nahuhulog ang gatasong ngipin — ang bagong permanenteng ngipin sa ilalim ay dahan-dahang tinutunaw ang ugat ng gatasong ngipin hanggang lumuwag ito at malaglag.", "en": "A baby tooth does not just fall out by chance — the new permanent tooth growing underneath slowly dissolves the baby tooth's root until it loosens and drops.", "bis": "Dili lang basta matangtang ang ngipon sa gatas — ang bag-ong permanente nga ngipon sa ilawom hinay-hinay nga motunaw sa gamot sa ngipon sa gatas hangtod nga moluag kini ug matangtang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wisdom-teeth-last-g6", "domain": "LIVING_THINGS", "topic": "wisdom teeth", "grades": [6, 7, 8], "terms": ["wisdom teeth", "bagang sa karunungan", "huling ngipin", "tumutubo", "binata", "dalaga", "ulahing ngipon", "ngipon sa kaalam", "molars", "third molar", "late teens", "adult", "tumutubo ng huli"], "fact": {"tl": "Ang pinakahuling ngipin na tumutubo ay tinatawag na wisdom teeth, na lumalabas kapag binata o dalaga na ang tao — kaya tinawag itong 'karunungan,' dahil dumarating ito sa edad na mas matalino na.", "en": "The very last teeth to come in are the wisdom teeth, which appear in the late teens or early adulthood — they got that name because they arrive at an age when a person is supposedly wiser.", "bis": "Ang pinakaulahi nga ngipon nga moturok gitawag og wisdom teeth, nga mogula kon tin-edyer na o batan-on nga hamtong na ang tawo — gitawag kini og 'kaalam' kay moabot kini sa edad nga mas maalam na kuno."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "enamel-cannot-heal-g5", "domain": "LIVING_THINGS", "topic": "enamel cannot repair itself", "grades": [5, 6], "terms": ["enamel", "hindi gumagaling", "walang buhay na selula", "ngipin", "sira", "hindi naghihilom", "panit gumagaling", "dili maulian", "walang himo", "wala nay buhay", "cannot heal", "no living cells", "enamel does not grow back"], "fact": {"tl": "Hindi tulad ng balat na gumagaling kapag nasugatan, ang enamel ng ngipin ay walang buhay na selula — kaya kapag nabutas ito ng sira, hindi na ito kayang ayusin ng katawan mag-isa.", "en": "Unlike skin, which heals when cut, tooth enamel has no living cells — so once decay makes a hole, the body cannot repair it on its own.", "bis": "Dili sama sa panit nga maulian kon masamdan, ang enamel sa ngipon walay buhi nga selula — busa kon mabangagan kini sa gabok, dili na kini maayo sa lawas mag-isa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "saliva-protects-teeth-g5", "domain": "LIVING_THINGS", "topic": "saliva protects teeth", "grades": [5, 6], "terms": ["laway", "saliva", "naghuhugas", "mineral", "nagpapatigas", "ngipin", "bibig", "asido", "laway nagpoprotekta", "luwa", "mineral nga magpagahi", "nanghugas", "saliva protects", "minerals strengthen", "washes away acid"], "fact": {"tl": "Ang laway ay hindi lang basta tubig — naghuhugas ito ng tirang pagkain, nagpapababa ng asido, at may mineral na tumutulong magpatibay ng enamel ng ngipin.", "en": "Saliva is not just water — it washes away food bits, lowers acid, and carries minerals that help strengthen tooth enamel.", "bis": "Ang laway dili lang basta tubig — manghugas kini sa salin nga pagkaon, mokunhod sa aslom, ug adunay mineral nga motabang pagpalig-on sa enamel sa ngipon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "teeth-same-age-as-body-g4", "domain": "LIVING_THINGS", "topic": "enamel as hard as rock", "grades": [4, 5], "terms": ["enamel", "kasingtigas", "bato", "pinakamatigas", "bahagi ng katawan", "ngipin", "panit ng katawan", "sama kagahi", "bato nga gahi", "pinakagahi nga bahin", "ngipon", "hardest substance", "as hard as", "mineral crystal"], "fact": {"tl": "Ang enamel ng ngipin ay gawa sa mga kristal ng mineral na halos kasingtigas ng bato — ito ang dahilan kung bakit ito ang pinakamatigas na bahagi ng buong katawan.", "en": "Tooth enamel is built from mineral crystals nearly as hard as rock — that is why it is the hardest substance in the entire body.", "bis": "Ang enamel sa ngipon hinimo gikan sa mga kristal sa mineral nga halos sama kagahi sa bato — mao kini ang hinungdan nganong kini ang pinakagahi nga bahin sa tibuok lawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "plaque-is-living-bacteria-g6", "domain": "LIVING_THINGS", "topic": "dental plaque is bacteria", "grades": [6, 7], "terms": ["plaque", "dumi sa ngipin", "buhay na bacteria", "malagkit", "pelikula", "sinisepilyo", "tinatanggal", "plak", "gagmay nga bacteria", "mapilit", "tinangtang sa pagsipilyo", "plaque is living", "sticky film", "brushing removes bacteria"], "fact": {"tl": "Ang malagkit na plaque sa ngipin ay hindi tirang pagkain kundi milyon-milyong buhay na bacteria — kaya ang pagsesepilyo ay parang paglilinis ng mga ito bago sila makagawa ng asido.", "en": "The sticky plaque on teeth is not leftover food but millions of living bacteria — so brushing is really wiping these germs away before they make acid.", "bis": "Ang mapilit nga plaque sa ngipon dili salin nga pagkaon kondili minilyon nga buhi nga bacteria — busa ang pagsipilyo sama sa paghawid niini sa dili pa sila makahimo og aslom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "skin-largest-organ-spread-g5", "domain": "LIVING_THINGS", "topic": "skin is the largest organ", "grades": [5, 6], "terms": ["balat", "pinakamalaking organ", "kabuuang katawan", "nakabalot", "panit", "pinakadakong organ", "nagputos", "kumot ng katawan", "largest organ", "whole body", "wraps around"], "fact": {"tl": "Ang balat ang pinakamalaking organ ng katawan — kung ikakalat ito nang patag, sasakop ito ng halos dalawang metro kuwadrado, dahil binabalot nito ang buong tao.", "en": "Skin is the body's largest organ — if you spread it out flat it would cover almost two square meters, because it wraps around the whole person.", "bis": "Ang panit mao ang pinakadako nga organo sa lawas — kon ibukhad kini nga patag, motabon kini og halos duha ka metro kwadrado, kay giputos niini ang tibuok tawo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "epidermis-dead-cells-shield-g6", "domain": "LIVING_THINGS", "topic": "outer skin is dead cells", "grades": [6, 7], "terms": ["epidermis", "patay na selula", "ibabaw ng balat", "proteksyon", "natutuyo", "nalalaglag", "alikabok", "panit nga patay", "selula nga patay", "pang-ibabaw", "abog", "dead skin cells", "outer layer", "dust at home"], "fact": {"tl": "Ang pinakaibabaw ng balat na hinihipo natin ay gawa na sa mga patay na selula na natuyo't tumigas para maging panangga — at malaking bahagi ng alikabok sa bahay ay mga laglag na balat ng tao.", "en": "The very surface of skin we touch is made of dead, hardened cells that act as a shield — and much of the dust in a house is actually flakes of shed human skin.", "bis": "Ang pinakaibabaw sa panit nga atong gihikap hinimo na sa patay nga mga selula nga namala ug nigahi aron mahimong taming — ug dako nga bahin sa abog sa balay kay tinangtang nga panit sa tawo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "skin-makes-vitamin-d-sun-g6", "domain": "LIVING_THINGS", "topic": "skin makes vitamin D from sunlight", "grades": [6, 7, 8], "terms": ["bitamina D", "araw", "balat gumagawa", "sikat ng araw", "buto", "matibay", "panit naghimo", "bitamina D gikan sa adlaw", "sinag", "bukog", "vitamin D", "sunlight", "strong bones"], "fact": {"tl": "Kapag tumama ang sikat ng araw sa balat, gumagawa ito ng bitamina D — isang sangkap na tumutulong magpatibay ng mga buto, kaya parang maliit na pabrika ang balat natin.", "en": "When sunlight hits the skin, it makes vitamin D — a substance that helps build strong bones, so your skin works like a tiny factory.", "bis": "Kon ang sinag sa adlaw motama sa panit, maghimo kini og bitamina D — usa ka sangkap nga motabang pagpalig-on sa mga bukog, busa sama sa gamay nga pabrika ang atong panit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-fingers-wrinkle-water-g4", "domain": "LIVING_THINGS", "topic": "why fingers wrinkle in water", "grades": [4, 5, 6], "terms": ["kunot", "daliri", "matagal sa tubig", "nagkukunot", "hawak", "basa", "nakuko nga tudlo", "nagkunot", "gunit", "basa nga tubig", "wrinkly fingers", "prune fingers", "better grip wet"], "fact": {"tl": "Kapag matagal kang nasa tubig, nagkukunot ang dulo ng iyong mga daliri — pinasisimulan ito ng iyong mga nerbiyos para mas madaling makahawak ng basang bagay, hindi dahil sumisipsip ng tubig ang balat.", "en": "After a long time in water, your fingertips wrinkle — your nervous system actually does this to help you grip wet things better, not because the skin soaks up water.", "bis": "Human sa dugay nga pagtuom sa tubig, mokunot ang tumoy sa imong mga tudlo — gibuhat kini sa nerbiyos aron mas sayon makagunit sa basa nga butang, dili tungod kay misuyop og tubig ang panit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "two-kinds-of-sweat-g7", "domain": "LIVING_THINGS", "topic": "why sweat smells", "grades": [7, 8], "terms": ["pawis", "amoy", "bacteria", "kilikili", "walang amoy na pawis", "amoy ng pawis", "singot", "baho", "bacteria sa panit", "walay baho nga singot", "sweat smell", "armpit", "bacteria break down"], "fact": {"tl": "Ang pawis mismo ay halos walang amoy — ang amoy ay galing sa bacteria sa balat na kumakain ng pawis sa mga bahaging tulad ng kilikili at nagiging mabaho ang dulot.", "en": "Sweat itself is almost odorless — body odor comes from bacteria on the skin feeding on the sweat in places like the armpits and giving off a smell.", "bis": "Ang singot mismo halos walay baho — ang baho gikan sa bacteria sa panit nga mokaon sa singot sa mga bahin sama sa kilikili ug mohatag og baho."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "goosebumps-leftover-fur-g6", "domain": "LIVING_THINGS", "topic": "goosebumps are leftover from fur", "grades": [6, 7], "terms": ["kilabot", "balahibo", "ninuno", "hayop", "init", "lamig", "tirang ugali", "kulba sa panit", "balahibo sa hayop", "kainit", "reflex", "goosebumps", "ancestors fur", "trapping warmth"], "fact": {"tl": "Ang kilabot ay tira pa ng ating mga ninuno — sa makakapal na balahibo ng hayop, pinatatayo ng ganitong reflex ang balahibo para mag-ipon ng init, pero sa makinis nating balat, halos wala na itong silbi.", "en": "Goosebumps are a leftover from our furry ancestors — in thick-furred animals the same reflex fluffs up the hair to trap warmth, but on our smooth skin it does almost nothing useful.", "bis": "Ang kulba sa panit kay salin pa sa atong mga katigulangan — sa baga og balhibo nga hayop, kini nga reflex mopatindog sa balhibo aron magtipig og kainit, apan sa atong hamis nga panit, halos wala na kini pulos."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hair-is-not-alive-g4", "domain": "LIVING_THINGS", "topic": "why haircuts dont hurt", "grades": [4, 5], "terms": ["buhok", "patay", "hindi sumasakit", "gupit", "ugat ng buhok", "balahibo", "wala nay buhay", "gupti", "dili sakit", "gamot sa buhok", "haircut no pain", "hair not alive", "root is alive"], "fact": {"tl": "Hindi sumasakit ang paggupit ng buhok dahil ang bahaging nakikita natin ay patay na — buhay lang ang ugat sa ilalim ng balat kung saan ito tumutubo.", "en": "A haircut does not hurt because the part of the hair we see is already dead — only the root beneath the skin, where it grows, is alive.", "bis": "Dili sakit ang paggupit sa buhok kay ang bahin nga atong makita patay na — ang gamot lang sa ilawom sa panit, diin kini moturok, ang buhi."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-hair-is-curly-or-straight-g6", "domain": "LIVING_THINGS", "topic": "why hair is curly or straight", "grades": [6, 7, 8], "terms": ["buhok", "kulot", "unat", "hugis ng follicle", "bilog", "pilipisan", "sungay ng balat", "kulot nga buhok", "tul-id", "porma sa follicle", "curly hair", "straight hair", "follicle shape", "oval round"], "fact": {"tl": "Kulot o unat ang buhok depende sa hugis ng follicle na pinanggagalingan nito — ang bilog na follicle ay gumagawa ng unat na buhok, at ang hugis-itlog na follicle ay gumagawa ng kulot.", "en": "Whether hair is curly or straight depends on the shape of the follicle it grows from — a round follicle makes straight hair, while an oval follicle makes curly hair.", "bis": "Kulot o tul-id ang buhok depende sa porma sa follicle nga gigikanan niini — ang lingin nga follicle maghimo og tul-id nga buhok, ang sama-sa-itlog nga follicle maghimo og kulot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-hair-turns-gray-g6", "domain": "LIVING_THINGS", "topic": "why hair turns gray", "grades": [6, 7, 8], "terms": ["uban", "puting buhok", "melanin", "tumatanda", "nawawalang kulay", "puti nga buhok", "ubanon", "nawala ang kolor", "kulay ng buhok", "gray hair", "white hair", "loses melanin", "pigment"], "fact": {"tl": "Nagiging puti o uban ang buhok kapag tumatanda dahil tumitigil ang mga selula sa paggawa ng melanin — ang pigment na nagbibigay-kulay — kaya tumutubo na itong walang kulay.", "en": "Hair turns gray or white with age because its cells stop making melanin — the pigment that gives it color — so the new hair grows in without color.", "bis": "Mahimong puti o ubanon ang buhok kon magkatigulang kay mohunong ang mga selula sa paghimo og melanin — ang pigment nga maghatag og kolor — busa moturok kini nga walay kolor."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hair-nails-same-material-g5", "domain": "LIVING_THINGS", "topic": "hair and nails made of keratin", "grades": [5, 6, 7], "terms": ["keratin", "buhok", "kuko", "parehong sangkap", "sungay ng hayop", "balahibo ng ibon", "pareho nga sangkap", "buhok ug kuko", "keratin sa hayop", "same protein", "hair and nails", "horn feathers"], "fact": {"tl": "Ang buhok at kuko ay gawa sa parehong matibay na protina na tinatawag na keratin — ang parehong sangkap ng sungay ng hayop, kuko ng kabayo, at balahibo ng ibon.", "en": "Hair and nails are made of the same tough protein called keratin — the very same material in animal horns, horse hooves, and bird feathers.", "bis": "Ang buhok ug kuko hinimo sa samang lig-on nga protina nga gitawag og keratin — ang samang sangkap sa sungay sa hayop, kuko sa kabayo, ug balhibo sa langgam."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fingernails-grow-faster-g5", "domain": "LIVING_THINGS", "topic": "fingernails grow faster than toenails", "grades": [5, 6], "terms": ["kuko sa kamay", "kuko sa paa", "mas mabilis tumubo", "dugo", "mas mabilis lumaki", "kuko sa tiil", "mas paspas moturok", "kuko sa daliri", "fingernails faster", "toenails slower", "blood flow"], "fact": {"tl": "Ang kuko sa kamay ay tumutubo nang mas mabilis kaysa sa kuko sa paa, bahagyang dahil mas madalas gamitin ang kamay at mas malakas ang daloy ng dugo dito.", "en": "Fingernails grow faster than toenails, partly because the hands are used more and have a stronger flow of blood to them.", "bis": "Ang kuko sa kamot moturok nga mas paspas kaysa kuko sa tiil, tungod kay mas kanunay gamiton ang kamot ug mas kusog ang dagayday sa dugo niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "white-spot-half-moon-nail-g5", "domain": "LIVING_THINGS", "topic": "the half-moon at the nail base", "grades": [5, 6], "terms": ["lunula", "puting hugis-buwan", "kuko", "bagong tumubo", "ilalim ng kuko", "puti nga sama-bulan", "bag-ong turok", "half moon nail", "white crescent", "new nail"], "fact": {"tl": "Ang puting hugis-kalahating-buwan sa puno ng kuko ay tinatawag na lunula — ito ang bahagi kung saan bago pa lang ginagawa ang kuko bago tumigas.", "en": "The white half-moon shape at the base of a nail is called the lunula — it is the spot where new nail is still being formed before it hardens.", "bis": "Ang puti nga sama-katunga-sa-bulan sa puno sa kuko gitawag og lunula — mao kini ang bahin diin bag-o pa lang gihimo ang kuko sa dili pa kini mogahi."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fingerprints-form-before-birth-g5", "domain": "LIVING_THINGS", "topic": "fingerprints form before birth", "grades": [5, 6], "terms": ["fingerprint", "bakas ng daliri", "bago isilang", "sinapupunan", "hindi nagbabago", "habambuhay", "tatak sa tudlo", "wala pa matawo", "tagoangkan", "dili mausab", "fingerprints before birth", "womb", "never change"], "fact": {"tl": "Ang iyong fingerprint ay nabuo na bago ka pa isilang, noong nasa sinapupunan ka pa — at hindi na ito nagbabago habang-buhay, kahit lumaki ang iyong mga kamay.", "en": "Your fingerprints were already formed before you were born, while you were still in the womb — and they never change for the rest of your life, even as your hands grow.", "bis": "Ang imong fingerprint naporma na sa wala ka pa matawo, samtang anaa pa ka sa tagoangkan — ug dili na kini mausab sa tibuok kinabuhi, bisan modako ang imong mga kamot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "toes-have-prints-too-g4", "domain": "LIVING_THINGS", "topic": "toes and palms have prints too", "grades": [4, 5], "terms": ["fingerprint", "daliri sa paa", "palad", "talampakan", "bakas", "sariwang tatak", "tudlo sa tiil", "palad sa kamot", "lapalapa", "tatak sa lawas", "toe prints", "palm prints", "footprints unique"], "fact": {"tl": "Hindi lang ang mga daliri ng kamay ang may natatanging guhit — ang mga daliri ng paa, ang palad, at ang talampakan ay may sariling pattern din na walang katulad.", "en": "It is not only the fingers that have unique ridges — your toes, palms, and the soles of your feet each carry their own one-of-a-kind pattern too.", "bis": "Dili lang ang mga tudlo sa kamot ang adunay talagsaong guhit — ang mga tudlo sa tiil, ang palad, ug ang lapalapa adunay kaugalingong sumbanan usab nga walay sama."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "melanin-protects-like-umbrella-g6", "domain": "LIVING_THINGS", "topic": "melanin shields cells from UV", "grades": [6, 7, 8], "terms": ["melanin", "payong", "UV", "sikat ng araw", "nagpoprotekta", "selula", "DNA", "sanag sa adlaw", "payong sa selula", "panangga", "melanin shield", "umbrella", "UV rays", "protects DNA"], "fact": {"tl": "Ang melanin sa balat ay parang maliliit na payong sa loob ng mga selula — sinasalo nito ang mapanganib na UV mula sa araw bago ito makasira sa loob ng selula.", "en": "The melanin in skin works like tiny umbrellas inside the cells — it absorbs the sun's harmful UV rays before they can damage the cell's inner parts.", "bis": "Ang melanin sa panit sama sa gagmay nga payong sulod sa mga selula — masuyop niini ang delikado nga UV gikan sa adlaw sa dili pa kini makadaot sa sulod sa selula."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-bruise-changes-color-g6", "domain": "LIVING_THINGS", "topic": "why a bruise changes color", "grades": [6, 7], "terms": ["pasa", "kulay", "dugo", "nagbabago", "asul", "dilaw", "luslos", "pasa nga kolor", "dugo nga nabuak", "nagkalainlain", "bruise color", "blood breaks down", "blue green yellow"], "fact": {"tl": "Nagbabago ng kulay ang pasa — mula pula tungong asul, berde, at dilaw — dahil dahan-dahang sinisira at nililinis ng katawan ang dugong tumagas sa ilalim ng balat.", "en": "A bruise changes color — from red to blue, green, then yellow — because the body slowly breaks down and cleans up the blood that leaked under the skin.", "bis": "Mausab ang kolor sa pasa — gikan pula ngadto asul, lunhaw, ug dalag — kay hinay-hinay nga gibungkag ug gilimpyohan sa lawas ang dugo nga nibuhagay sa ilawom sa panit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "scar-skin-no-hair-g6", "domain": "LIVING_THINGS", "topic": "why scars look different", "grades": [6, 7], "terms": ["peklat", "sugat gumaling", "walang balahibo", "makinis", "iba ang itsura", "balat na bago", "samad nga naayo", "walay balhibo", "panit nga bag-o", "scar tissue", "no hair on scar", "heals differently"], "fact": {"tl": "Kapag gumaling ang malalim na sugat, ang bagong balat na tumutubo ay peklat — mas makinis, walang balahibo o pawis, dahil mabilis lang itong inayos ng katawan at hindi kasinghusay ng dating balat.", "en": "When a deep wound heals, the new skin that forms is a scar — smoother, with no hair or sweat glands, because the body patched it quickly and not as perfectly as the original skin.", "bis": "Kon maayo ang lawom nga samad, ang bag-ong panit nga moturok mao ang peklat — mas hamis, walay balhibo o singot, kay paspas lang gitapakan sa lawas ug dili sama kahingpit sa orihinal nga panit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "baby-more-bones-fewer-teeth-g4", "domain": "LIVING_THINGS", "topic": "babies are born without teeth", "grades": [4, 5], "terms": ["sanggol", "walang ngipin", "gatas lang", "tumutubo", "unang ngipin", "masuso", "walay ngipon", "gatas lamang", "moturok", "unang ngipon", "babies no teeth", "milk only", "first tooth"], "fact": {"tl": "Ipinanganganak ang sanggol na walang ngipin dahil gatas lang ang inumin nila — at unti-unti pa lang sumusulpot ang unang gatasong ngipin pagdating ng mga anim na buwang gulang.", "en": "Babies are born without teeth because they only drink milk — the first baby teeth only start pushing through at around six months old.", "bis": "Natawo ang masuso nga walay ngipon kay gatas ra ang ilang imnon — ug hinay-hinay pa lang motungha ang unang ngipon sa gatas pag-abot og mga unom ka bulan ang edad."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sweat-salty-taste-g5", "domain": "LIVING_THINGS", "topic": "why sweat tastes salty", "grades": [5, 6], "terms": ["pawis", "maalat", "asin", "katawan", "lasa", "singot nga parat", "asin sa lawas", "singot", "maasin", "salty sweat", "salt in body", "minerals"], "fact": {"tl": "Maalat ang pawis dahil may kasamang asin at mineral na galing sa loob ng katawan — kaya kapag namamawis tayo nang sobra, kailangan ding mapunan ang nawalang asin.", "en": "Sweat tastes salty because it carries salt and minerals from inside the body — so when we sweat a lot, we also need to replace the salt we lose.", "bis": "Parat ang singot kay adunay asin ug mineral nga gikan sa sulod sa lawas — busa kon mosingot ta og sobra, kinahanglan usab nga pul-an ang nawala nga asin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "palms-soles-no-hair-g6", "domain": "LIVING_THINGS", "topic": "why palms have no hair", "grades": [6, 7], "terms": ["palad", "talampakan", "walang balahibo", "makakapit", "makinis", "kapal", "palad sa kamot", "lapalapa", "walay balhibo", "makagunit", "no hair palms", "soles", "better grip"], "fact": {"tl": "Walang tumutubong balahibo sa palad ng kamay at sa talampakan dahil mas makakapit at makahawak tayo nang mahigpit kapag makinis at makapal ang balat dito.", "en": "No hair grows on the palms of the hands or the soles of the feet, because smooth, thick skin there lets us grip and hold on more firmly.", "bis": "Walay balhibo nga moturok sa palad sa kamot ug sa lapalapa, kay ang hamis ug baga nga panit didto motugot nato nga mas hugot makagunit ug makagakos."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-skin-itches-g5", "domain": "LIVING_THINGS", "topic": "why skin itches", "grades": [5, 6], "terms": ["kati", "balat", "nerbiyos", "kalmot", "babala", "kamot", "panit nga katol", "nerbiyos sa panit", "pangalmot", "pasidaan", "itch", "scratch", "nerve signal", "warning"], "fact": {"tl": "Ang kati ay isang senyales mula sa mga nerbiyos sa balat na nagsasabing 'may bagay dito' — parang babala para suriin o tanggalin ang nakadikit, gaya ng insekto o alikabok.", "en": "An itch is a signal from nerves in the skin saying 'something is here' — a kind of warning telling you to check or brush off whatever landed there, like an insect or dust.", "bis": "Ang katol usa ka senyas gikan sa mga nerbiyos sa panit nga nag-ingon 'adunay butang dinhi' — sama sa pasidaan nga mag-aghat nimo nga tan-awon o tangtangon ang nidikit, sama sa insekto o abog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "canine-teeth-sharp-pointed-g4", "domain": "LIVING_THINGS", "topic": "why canine teeth are pointed", "grades": [4, 5], "terms": ["pangil", "matulis", "ngipin", "pumupunit", "karne", "pangil nga talinis", "ngipon nga hait", "mokunis", "canine teeth pointed", "tearing food", "corner teeth"], "fact": {"tl": "Ang matutulis na ngipin sa gilid, na tinatawag na pangil o canine, ay hugis-sibat para makapunit ng matigas na pagkaing gaya ng karne — kaya naiiba ang hugis nito sa pantal na ngipin sa harap at likod.", "en": "The pointed teeth at the corners, called canines, are spear-shaped for tearing tough food like meat — which is why they are shaped differently from the flat teeth in front and back.", "bis": "Ang talinis nga mga ngipon sa kilid, gitawag og pangil o canine, sama sa bangkaw aron makakunis sa gahi nga pagkaon sama sa karne — mao nga lahi ang ilang porma sa patag nga mga ngipon sa atubangan ug likod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dermis-holds-everything-g7", "domain": "LIVING_THINGS", "topic": "the dermis is the busy layer", "grades": [7, 8], "terms": ["dermis", "ilalim na balat", "nerbiyos", "ugat ng dugo", "glandula", "follicle", "panit sa ilawom", "ugat sa dugo", "glandula sa singot", "abot ng damdamin", "dermis layer", "blood vessels", "sweat glands", "nerves"], "fact": {"tl": "Sa ilalim ng nakikita nating balat ay ang dermis — dito naroon ang ugat ng dugo, nerbiyos na nakakaramdam, glandula ng pawis, at ugat ng buhok, kaya ito ang pinakaabalang bahagi ng balat.", "en": "Beneath the skin we see lies the dermis — it holds the blood vessels, the nerves that feel, the sweat glands, and the hair roots, making it the busiest layer of the skin.", "bis": "Sa ilawom sa panit nga atong makita anaa ang dermis — dinhi nagpuyo ang ugat sa dugo, ang nerbiyos nga mobati, ang glandula sa singot, ug ang gamot sa buhok, busa kini ang pinakaaktibo nga sapaw sa panit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "anglerfish-tiny-male-fuses-g7", "domain": "LIVING_THINGS", "topic": "anglerfish male fuses to female", "grades": [6, 7, 8], "terms": ["anglerfish", "male", "female", "fuses", "mating", "deep sea", "lalaki", "babae", "lalake", "baye", "nagdidikit", "dumidikit", "kumakabit", "midikit", "nag-uban", "parasito", "parasitiko", "isda", "lawom nga dagat", "kalaliman", "mas maliit", "gamay"], "fact": {"tl": "Sa ilang uri ng anglerfish, napakaliit ng lalaki kaya kumakabit at dumidikit ito nang tuluyan sa katawan ng mas malaking babae para hindi sila magkahiwalay sa madilim na kailaliman.", "en": "In some kinds of anglerfish, the male is so tiny that he bites onto and fuses permanently into the much larger female's body so they never lose each other in the dark deep.", "bis": "Sa pipila ka matang sa anglerfish, gamay kaayo ang laki maong mokabit ug modikit kini hangtod sa lawas sa mas dako nga baye aron dili sila magkabulag sa ngitngit nga kalaliman."}, "source": "Yale News 2024; Natural History Museum (encyclopedia-stable consensus)", "generator": "claude-workflow", "reviewed": false},
  {"id": "anglerfish-lure-glows-bacteria-g6", "domain": "LIVING_THINGS", "topic": "anglerfish glowing lure bacteria", "grades": [5, 6, 7], "terms": ["anglerfish", "lure", "pain", "pamain", "glowing", "ilaw", "nagniningning", "nagdan-ag", "bakterya", "bacteria", "light", "deep sea", "nakabitin sa noo", "tiny living things", "gagmay nga buhi"], "fact": {"tl": "Ang ilaw na nakabitin sa harap ng anglerfish ay kumikinang dahil sa maliliit na bakteryang nakatira doon, at ginagamit ito ng isda bilang pain para lumapit ang mga hahabuling biktima.", "en": "The little light dangling in front of an anglerfish glows because of tiny bacteria living inside it, and the fish uses it as a lure to draw prey close.", "bis": "Ang gamay nga suga nga nagbitay sa atubangan sa anglerfish nagdan-ag tungod sa gagmay nga bakterya nga nagpuyo didto, ug gigamit kini sa isda nga pain aron moduol ang iyang biktima."}, "source": "Smithsonian Ocean (encyclopedia-stable consensus)", "generator": "claude-workflow", "reviewed": false},
  {"id": "giant-squid-largest-invertebrate-g6", "domain": "LIVING_THINGS", "topic": "giant squid size", "grades": [5, 6, 7], "terms": ["giant squid", "squid", "pusit", "higanteng pusit", "dakong nukos", "nukos", "largest invertebrate", "walang gulugod", "walay bukog", "haba", "metro", "tentakulo", "galamay", "deep sea", "kailaliman"], "fact": {"tl": "Ang giant squid ay isa sa pinakamalaking hayop na walang gulugod, na maaaring umabot ng mga 12 hanggang 13 metro ang haba kasama ang mahahabang galamay nito.", "en": "The giant squid is one of the largest animals without a backbone, reaching about 12 to 13 meters long including its long tentacles.", "bis": "Ang giant squid usa sa pinakadako nga mananap nga walay bukog, nga makaabot og mga 12 hangtod 13 ka metro ang gitas-on lakip na ang taas niini nga mga galamay."}, "source": "Britannica; Smithsonian Ocean (encyclopedia-stable consensus)", "generator": "claude-workflow", "reviewed": false},
  {"id": "giant-squid-eyes-detect-light-g7", "domain": "LIVING_THINGS", "topic": "giant squid huge eyes", "grades": [6, 7, 8], "terms": ["giant squid", "eyes", "mata", "mga mata", "malalaking mata", "dagkong mata", "largest eyes", "plato", "dim light", "madilim", "ngitngit", "manipis na liwanag", "silaw", "nukos", "detect", "makakita", "makakita sa kangitngit"], "fact": {"tl": "May napakalalaking mata ang giant squid, kasinlaki halos ng plato, para makahuli ng kaunting liwanag sa madilim na karagatan at makita ang mga papalapit na panganib.", "en": "The giant squid has enormous eyes, almost the size of a plate, to catch the little light in the dark ocean and spot approaching danger.", "bis": "Ang giant squid adunay dagko kaayo nga mga mata, halos sama kadako sa plato, aron makakuha sa gamay nga kahayag sa ngitngit nga dagat ug makita ang nagsingabot nga kapeligrohan."}, "source": "Smithsonian Ocean; Britannica (encyclopedia-stable consensus)", "generator": "claude-workflow", "reviewed": false},
  {"id": "viperfish-long-fangs-g6", "domain": "LIVING_THINGS", "topic": "viperfish teeth", "grades": [5, 6, 7], "terms": ["viperfish", "fangs", "teeth", "ngipin", "pangil", "mahahabang ngipin", "taas nga ngipin", "trap", "trampa", "biktima", "deep sea fish", "isda", "lawom nga dagat", "nakausli", "lumalabas sa bibig"], "fact": {"tl": "Ang viperfish ay may napakahahabang ngipin na parang pangil, na sobrang haba kaya hindi magkasya sa bibig nito at lumalabas pa palapit sa mga mata.", "en": "The viperfish has fangs so long they cannot fit inside its mouth and stick out past its jaws toward its eyes, helping it trap prey.", "bis": "Ang viperfish adunay taas kaayo nga mga ngipin nga sama sa tango, taas kaayo maong dili mahaom sa baba niini ug mogawas pa duol sa mga mata."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sea-spider-breathes-through-legs-g7", "domain": "LIVING_THINGS", "topic": "sea spiders breathe through legs", "grades": [6, 7, 8], "terms": ["sea spider", "sea spiders", "gagamba sa dagat", "spider", "gagamba", "breathe", "huminga", "ginhawa", "nagaginhawa", "legs", "binti", "paa", "tiil", "walang baga", "walay baga", "oxygen", "oksiheno", "cuticle", "balat"], "fact": {"tl": "Ang sea spider ay walang baga o hasang, kaya humihinga ito sa pamamagitan ng pagpasok ng oxygen sa maliliit na butas sa balat ng mahahaba nitong binti.", "en": "The sea spider has no lungs or gills, so it breathes by letting oxygen seep through tiny pores in the skin of its long legs.", "bis": "Ang sea spider walay baga o hasang, busa nagaginhawa kini pinaagi sa pagpasulod sa oksiheno ngadto sa gagmay nga lungag sa panit sa taas niini nga mga tiil."}, "source": "National Geographic; Journal of Experimental Biology (encyclopedia-stable consensus)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sea-spider-organs-in-legs-g7", "domain": "LIVING_THINGS", "topic": "sea spider body in legs", "grades": [6, 7, 8], "terms": ["sea spider", "sea spiders", "gagamba sa dagat", "legs", "binti", "paa", "tiil", "organs", "laman-loob", "tinai", "bituka", "katawan", "lawas", "maliit", "gamay", "tiyan", "gut"], "fact": {"tl": "Napakaliit ng katawan ng sea spider kaya ang ilan sa mga laman-loob nito, gaya ng bituka, ay umaabot at nakatira sa loob ng mahahaba nitong binti.", "en": "A sea spider's body is so small that some of its inner organs, like parts of its gut, reach into and live inside its long legs.", "bis": "Gamay kaayo ang lawas sa sea spider maong ang uban nga laman-sulod niini, sama sa bahin sa tinai, moabot ug magpuyo sa sulod sa taas niini nga mga tiil."}, "source": "National Geographic; ScienceAlert (encyclopedia-stable consensus)", "generator": "claude-workflow", "reviewed": false},
  {"id": "hydrothermal-vent-life-no-sun-g7", "domain": "LIVING_THINGS", "topic": "hydrothermal vent life without sunlight", "grades": [6, 7, 8], "terms": ["hydrothermal vent", "vent", "bukal sa karagatan", "mainit nga tubod", "init nga tubod", "life", "buhay", "kinabuhi", "walang araw", "walay adlaw", "walang sikat ng araw", "init na tubig", "bakterya", "bacteria", "chemicals", "kemikal", "deep sea floor", "kailaliman"], "fact": {"tl": "Sa ilalim ng dagat, may mga bukal ng napakainit na tubig na tinatawag na hydrothermal vent, at doon may mga hayop na nabubuhay kahit walang sikat ng araw man lang.", "en": "On the deep sea floor there are springs of very hot water called hydrothermal vents, where whole communities of animals live even though no sunlight ever reaches them.", "bis": "Sa ilawom sa dagat adunay mga tubod sa init kaayo nga tubig nga gitawag og hydrothermal vent, ug didto adunay mga mananap nga nabuhi bisan walay silaw sa adlaw nga moabot."}, "source": "Smithsonian Ocean (encyclopedia-stable consensus)", "generator": "claude-workflow", "reviewed": false},
  {"id": "tube-worms-no-mouth-bacteria-g8", "domain": "LIVING_THINGS", "topic": "giant tube worms feed by bacteria", "grades": [7, 8, 9], "terms": ["tube worm", "tube worms", "giant tube worm", "bulati", "ulod", "wati", "no mouth", "walang bibig", "walay baba", "walang tiyan", "bakterya", "bacteria", "chemicals", "kemikal", "hydrogen sulfide", "pagkain", "kinaon", "chemosynthesis", "vent", "mainit nga tubod"], "fact": {"tl": "Ang giant tube worm sa mga hydrothermal vent ay walang bibig at walang tiyan; sa halip, may mga bakterya sa loob nito na gumagawa ng pagkain mula sa kemikal sa tubig.", "en": "The giant tube worm at hydrothermal vents has no mouth and no stomach; instead, bacteria living inside it make food from chemicals in the water.", "bis": "Ang giant tube worm sa mga hydrothermal vent walay baba ug walay tiyan; hinuon, adunay mga bakterya sa sulod niini nga naghimo og pagkaon gikan sa kemikal sa tubig."}, "source": "Smithsonian Ocean; HHMI BioInteractive (encyclopedia-stable consensus)", "generator": "claude-workflow", "reviewed": false},
  {"id": "chemosynthesis-vs-photosynthesis-g8", "domain": "LIVING_THINGS", "topic": "chemosynthesis makes food from chemicals", "grades": [7, 8, 9, 10], "terms": ["chemosynthesis", "photosynthesis", "kemikal", "chemicals", "pagkain", "food", "kinaon", "bakterya", "bacteria", "walang araw", "walay adlaw", "liwanag", "kahayag", "hydrothermal vent", "sulfur", "asupre", "gumagawa ng pagkain", "naghimo og pagkaon"], "fact": {"tl": "Sa ibabaw, gumagawa ang mga halaman ng pagkain mula sa liwanag ng araw, ngunit sa kailaliman ay may mga bakteryang gumagawa ng pagkain mula sa kemikal — ito ang tinatawag na chemosynthesis.", "en": "At the surface, plants make food from sunlight, but in the deep sea some bacteria make food from chemicals instead — this is called chemosynthesis.", "bis": "Sa ibabaw, ang mga tanom naghimo og pagkaon gikan sa silaw sa adlaw, apan sa kalaliman adunay mga bakterya nga naghimo og pagkaon gikan sa kemikal — kini gitawag og chemosynthesis."}, "source": "Smithsonian Ocean (encyclopedia-stable consensus)", "generator": "claude-workflow", "reviewed": false},
  {"id": "vent-food-web-base-bacteria-g8", "domain": "LIVING_THINGS", "topic": "vent food chain starts with bacteria", "grades": [7, 8, 9], "terms": ["hydrothermal vent", "food chain", "food web", "kadena ng pagkain", "kadena sa pagkaon", "bakterya", "bacteria", "base", "pinagmumulan", "tinubdan", "crabs", "alimango", "shrimp", "hipon", "tube worms", "walang halaman", "walay tanom", "walang araw"], "fact": {"tl": "Sa mga hydrothermal vent, ang simula ng kadena ng pagkain ay hindi halaman kundi bakterya, at sa kanila umaasa ang mga alimango, hipon, at tube worm na naninirahan doon.", "en": "At hydrothermal vents the bottom of the food chain is not plants but bacteria, and crabs, shrimp, and tube worms there all depend on them.", "bis": "Sa mga hydrothermal vent, ang sinugdanan sa kadena sa pagkaon dili tanom kondili bakterya, ug ang mga alimango, pasayan, ug tube worm nga nagpuyo didto nagsalig kanila."}, "source": "Smithsonian Ocean (encyclopedia-stable consensus)", "generator": "claude-workflow", "reviewed": false},
  {"id": "deep-sea-no-plants-no-sunlight-g6", "domain": "LIVING_THINGS", "topic": "no plants grow in the deep sea", "grades": [5, 6, 7], "terms": ["deep sea", "kailaliman", "lawom nga dagat", "plants", "halaman", "tanom", "walang halaman", "walay tanom", "walang araw", "walay adlaw", "sunlight", "sikat ng araw", "silaw sa adlaw", "madilim", "ngitngit", "pagkain", "marine snow"], "fact": {"tl": "Walang halamang tumutubo sa malalim na bahagi ng dagat dahil hindi umaabot doon ang sikat ng araw, kaya karamihan ng hayop doon ay umaasa sa pagkaing nahuhulog mula sa itaas.", "en": "No plants can grow in the deep sea because sunlight never reaches there, so most animals depend on food drifting down from above.", "bis": "Walay tanom nga motubo sa lawom nga bahin sa dagat tungod kay ang silaw sa adlaw dili moabot didto, busa kadaghanan sa mga mananap nagsalig sa pagkaon nga nahulog gikan sa ibabaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "marine-snow-falling-food-g6", "domain": "LIVING_THINGS", "topic": "marine snow feeds the deep sea", "grades": [5, 6, 7], "terms": ["marine snow", "niyebe sa dagat", "ulan sa pagkaon", "falling food", "nahuhulog", "nahulog", "nagkahulog", "nahuhulog na pagkain", "particles", "tinik-tinik", "patay", "namatay", "plankton", "deep sea", "kailaliman", "mula sa itaas", "gikan sa ibabaw"], "fact": {"tl": "Patuloy na may maliliit na piraso ng patay na hayop at halaman na bumabagsak mula sa ibabaw ng dagat papunta sa kailaliman — tinatawag itong 'marine snow' at pagkain ito ng maraming hayop sa ilalim.", "en": "Tiny bits of dead animals and plants keep drifting down from the ocean surface to the deep — this is called 'marine snow,' and it feeds many animals below.", "bis": "Adunay padayong nahulog nga gagmay nga tipik sa patay nga mananap ug tanom gikan sa ibabaw sa dagat paingon sa kalaliman — gitawag kini og 'marine snow,' ug pagkaon kini sa daghang mananap sa ilawom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "deep-sea-crushing-pressure-g7", "domain": "LIVING_THINGS", "topic": "crushing pressure of the deep sea", "grades": [6, 7, 8], "terms": ["deep sea", "pressure", "presyon", "diin", "kailaliman", "lawom nga dagat", "crushing", "durog", "dumudurog", "modugmok", "weight of water", "bigat ng tubig", "gibug-aton sa tubig", "tindi", "kalaliman", "hayop", "mananap"], "fact": {"tl": "Sa kailaliman ng dagat, napakabigat ng tubig sa itaas kaya ang presyon doon ay sapat para durugin ang karaniwang hayop o gamit mula sa ibabaw.", "en": "Deep in the ocean the water above is so heavy that the pressure there could crush an ordinary animal or object from the surface.", "bis": "Sa kalaliman sa dagat, bug-at kaayo ang tubig sa ibabaw maong ang presyon didto igo nga modugmok sa ordinaryong mananap o butang gikan sa ibabaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "deep-sea-cold-dark-no-sun-g5", "domain": "LIVING_THINGS", "topic": "deep sea is cold and pitch dark", "grades": [4, 5, 6], "terms": ["deep sea", "cold", "malamig", "bugnaw", "dark", "madilim", "ngitngit", "walang araw", "walay adlaw", "sunlight", "sikat ng araw", "silaw", "midnight zone", "kailaliman", "lawom nga dagat", "pitch black", "itim na itim"], "fact": {"tl": "Sa pinakamalalim na bahagi ng dagat, palaging madilim na parang gabi at napakalamig dahil hindi kailanman nakakaabot doon ang sikat ng araw.", "en": "In the deepest parts of the ocean it is always as dark as night and very cold, because sunlight can never reach there.", "bis": "Sa pinakalawom nga bahin sa dagat, kanunay nga ngitngit nga sama sa gabii ug bugnaw kaayo, tungod kay ang silaw sa adlaw dili gayod makaabot didto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-deep-sea-glow-bioluminescence-uses-g7", "domain": "LIVING_THINGS", "topic": "reasons deep sea animals glow", "grades": [6, 7, 8], "terms": ["bioluminescence", "glow", "ningning", "dan-ag", "nagniningning", "nagdan-ag", "light", "ilaw", "suga", "deep sea", "kailaliman", "mating", "panghuli", "pang-akit", "pagtawag", "pananggalang", "depensa", "pain", "lure", "why glow", "bakit kumikinang"], "fact": {"tl": "Maraming hayop sa kailaliman ang nagniningning para sa iba't ibang dahilan — para manghuli, para takutin ang kaaway, o para makahanap ng kapareha sa dilim.", "en": "Many deep-sea animals glow for different reasons — to catch prey, to scare off enemies, or to find a mate in the dark.", "bis": "Daghang mananap sa kalaliman ang nagdan-ag tungod sa nagkalainlain nga rason — aron manghuli, aron hadlokon ang kaaway, o aron makakita og kapikas sa kangitngit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "counterillumination-belly-glow-g8", "domain": "LIVING_THINGS", "topic": "belly glow hides from predators below", "grades": [7, 8, 9], "terms": ["counterillumination", "belly glow", "tiyan", "ilaw sa tiyan", "suga sa tiyan", "camouflage", "pagtago", "pagtakip", "nagtatago", "anino", "shadow", "landong", "mula sa ibaba", "gikan sa ilawom", "predator", "mananakmal", "nawawala ang anino", "deep sea"], "fact": {"tl": "May mga isda sa dagat na pinakikinang ang kanilang tiyan para tugma sa kaunting liwanag mula sa itaas, kaya nawawala ang kanilang anino at hindi sila makita ng mga mandaragit mula sa ibaba.", "en": "Some sea fish make their bellies glow to match the faint light from above, erasing their shadow so predators below cannot spot them.", "bis": "Adunay mga isda sa dagat nga gipadan-ag ang ilang tiyan aron motakdo sa gamay nga kahayag gikan sa ibabaw, mawala ang ilang landong aron dili sila makita sa mga manunukob gikan sa ilawom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "deep-sea-red-invisible-g8", "domain": "LIVING_THINGS", "topic": "red color is invisible in the deep sea", "grades": [7, 8, 9], "terms": ["red", "pula", "pula nga kolor", "color", "kulay", "invisible", "hindi nakikita", "dili makita", "nawawala", "deep sea", "kailaliman", "light", "liwanag", "kahayag", "walang pulang liwanag", "camouflage", "pagtago", "isda", "hayop", "dragonfish"], "fact": {"tl": "Sa kailaliman ay halos walang pulang liwanag, kaya ang mga hayop na pula ang kulay ay parang naglalaho at hindi nakikita — kaya pulang-pula ang ilang mga deep-sea na isda at hipon.", "en": "Deep down there is almost no red light, so animals that are red appear to vanish and stay hidden — which is why some deep-sea fish and shrimp are bright red.", "bis": "Sa kalaliman halos walay pula nga kahayag, busa ang mga mananap nga pula ang kolor morag mawala ug magpabiling tago — mao nga pula kaayo ang ubang deep-sea nga isda ug pasayan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gulper-eel-huge-mouth-g6", "domain": "LIVING_THINGS", "topic": "gulper eel big mouth swallows large prey", "grades": [5, 6, 7], "terms": ["gulper eel", "pelican eel", "palos", "igat", "big mouth", "malaking bibig", "dakong baba", "lumululon", "tinunlon", "molamoy", "biktima", "mas malaki", "prey", "deep sea", "kailaliman", "balloon", "nagpalaki sa baba"], "fact": {"tl": "Ang gulper eel ay may napakalaking bibig na kayang bumukaka nang malawak, kaya nito itong nalululon ang biktimang mas malaki pa kaysa sa sarili nitong katawan.", "en": "The gulper eel has a huge mouth that can open very wide, letting it swallow prey even bigger than its own body.", "bis": "Ang gulper eel adunay dako kaayo nga baba nga makaabli og lapad, maong makalamoy kini og biktima nga mas dako pa kaysa kaugalingon niini nga lawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dumbo-octopus-ear-fins-g5", "domain": "LIVING_THINGS", "topic": "dumbo octopus ear-like fins", "grades": [4, 5, 6], "terms": ["dumbo octopus", "octopus", "pugita", "kugita", "ears", "tainga", "dalunggan", "fins", "palikpik", "kapay", "lumalangoy", "molangoy", "deepest octopus", "pinakamalalim", "kailaliman", "lumulutang"], "fact": {"tl": "Ang dumbo octopus ay may dalawang palikpik na parang tainga sa ibabaw ng ulo nito na ipinipilipit para lumangoy, at isa ito sa pinakamalalim na nakatirang pugita.", "en": "The dumbo octopus has two ear-like fins on top of its head that it flaps to swim, and it is one of the deepest-living octopuses.", "bis": "Ang dumbo octopus adunay duha ka kapay nga sama sa dalunggan sa ibabaw sa ulo niini nga iyang ipakpak aron molangoy, ug usa kini sa pinakalawom nga nagpuyo nga kugita."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "yeti-crab-hairy-claws-bacteria-g7", "domain": "LIVING_THINGS", "topic": "yeti crab grows bacteria on hairy arms", "grades": [6, 7, 8], "terms": ["yeti crab", "crab", "alimango", "hairy", "mabalahibo", "balhiboon", "claws", "sipit", "kuko", "arms", "braso", "bakterya", "bacteria", "vent", "mainit nga tubod", "kinakain", "gikaon", "tinubuan", "deep sea"], "fact": {"tl": "Ang yeti crab ay may mabalahibong braso, at sa mga balahibong iyon ay nagpaparami ito ng bakterya na pagkatapos ay kinakain nito.", "en": "The yeti crab has hairy arms, and on those hairs it grows bacteria that it then eats.", "bis": "Ang yeti crab adunay balhiboon nga braso, ug niadtong mga balhibo nagpadaghan kini og bakterya nga unya iya rang kan-on."}, "source": "Nature; National Geographic (encyclopedia-stable consensus)", "generator": "claude-workflow", "reviewed": false},
  {"id": "vampire-squid-eats-marine-snow-g7", "domain": "LIVING_THINGS", "topic": "vampire squid eats falling debris", "grades": [6, 7, 8], "terms": ["vampire squid", "squid", "pusit", "nukos", "marine snow", "nahuhulog", "patay", "food", "pagkain", "kinaon", "mababang oxygen", "gamay nga oksiheno", "deep sea", "kailaliman", "hindi nangangagat", "dili manukob", "filaments"], "fact": {"tl": "Sa kabila ng nakakatakot nitong pangalan, ang vampire squid ay hindi nangangagat ng dugo kundi kumakain lamang ng mga nahuhulog na patay na piraso ng pagkain sa kailaliman.", "en": "Despite its scary name, the vampire squid does not bite for blood but only eats bits of dead, falling food in the deep.", "bis": "Bisan pa sa makahadlok niini nga ngalan, ang vampire squid dili mopaak og dugo kondili mokaon lang sa nahulog nga patay nga tipik sa pagkaon sa kalaliman."}, "source": "MBARI (encyclopedia-stable consensus)", "generator": "claude-workflow", "reviewed": false},
  {"id": "deep-sea-gigantism-g8", "domain": "LIVING_THINGS", "topic": "deep sea animals grow giant", "grades": [7, 8, 9], "terms": ["deep sea gigantism", "gigantism", "higante", "dako kaayo", "malaki", "laki", "isopod", "giant isopod", "kuto-kuto sa dagat", "squid", "pusit", "mas malaki", "lamig", "cold", "bugnaw", "mahabang buhay", "tagal ng buhay", "kailaliman"], "fact": {"tl": "May ilang hayop tulad ng giant isopod na lumalaki nang husto sa kailaliman ng dagat kaysa sa kanilang mga kamag-anak sa mababaw — tinatawag itong deep-sea gigantism.", "en": "Some animals like the giant isopod grow much larger in the deep sea than their relatives in shallow water — this is called deep-sea gigantism.", "bis": "Adunay pipila ka mananap sama sa giant isopod nga modako pa kaayo sa kalaliman sa dagat kaysa sa ilang mga paryente sa mabaw — gitawag kini og deep-sea gigantism."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pompeii-worm-heat-tolerant-g8", "domain": "LIVING_THINGS", "topic": "Pompeii worm survives extreme heat", "grades": [7, 8, 9], "terms": ["Pompeii worm", "worm", "bulati", "ulod", "wati", "heat", "init", "kainit", "mainit", "mainit na tubig", "init nga tubig", "vent", "tubod", "survives", "nabubuhay", "nabuhi", "hottest", "pinakainit", "deep sea", "kailaliman"], "fact": {"tl": "Ang Pompeii worm ay isa sa mga hayop na nakakatiis ng pinakamataas na init, dahil nabubuhay ito sa tabi ng mainit na tubig na bumubuga mula sa mga vent sa ilalim ng dagat.", "en": "The Pompeii worm is one of the most heat-tolerant animals, living right beside the scalding water that gushes from vents on the deep sea floor.", "bis": "Ang Pompeii worm usa sa mga mananap nga makaantos sa pinakataas nga init, kay nabuhi kini tupad sa init kaayo nga tubig nga mobuga gikan sa mga vent sa ilawom sa dagat."}, "source": "University of Delaware; AskNature (encyclopedia-stable consensus)", "generator": "claude-workflow", "reviewed": false},
  {"id": "deep-sea-slow-life-g7", "domain": "LIVING_THINGS", "topic": "deep sea animals live slow and long", "grades": [6, 7, 8], "terms": ["deep sea", "slow", "mabagal", "hinay", "matagal mabuhay", "dugay mabuhi", "long life", "mahabang buhay", "cold", "malamig", "bugnaw", "konting pagkain", "gamay nga pagkaon", "scarce food", "mabagal lumaki", "hinay motubo", "kailaliman"], "fact": {"tl": "Dahil malamig at kakaunti ang pagkain sa kailaliman, marami sa mga hayop doon ay mabagal kumilos, mabagal lumaki, at nabubuhay nang napakatagal.", "en": "Because it is cold and food is scarce in the deep, many animals there move slowly, grow slowly, and can live a very long time.", "bis": "Tungod kay bugnaw ug gamay ra ang pagkaon sa kalaliman, daghan sa mga mananap didto hinay molihok, hinay motubo, ug makabuhi og dugay kaayo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bone-eating-worm-whale-fall-g8", "domain": "LIVING_THINGS", "topic": "bone-eating worms on sunken whales", "grades": [7, 8, 9], "terms": ["bone-eating worm", "zombie worm", "whale fall", "whale", "balyena", "buto", "bukog", "kalansay", "nahulog na balyena", "worm", "bulati", "ulod", "kinakain ang buto", "gikaon ang bukog", "bakterya", "deep sea floor", "kailaliman"], "fact": {"tl": "Kapag may patay na balyenang lumubog sa kailaliman, dumarating ang maliliit na 'bone-eating worm' na tumitira sa kalansay nito at kumukuha ng pagkain mula sa mismong mga buto.", "en": "When a dead whale sinks to the deep sea floor, tiny 'bone-eating worms' arrive to settle on its skeleton and draw food from the bones themselves.", "bis": "Kon adunay patay nga balyena nga molunod sa kalaliman, moabot ang gagmay nga 'bone-eating worm' nga mopuyo sa kalansay niini ug mokuha og pagkaon gikan mismo sa mga bukog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "anglerfish-only-female-glows-g7", "domain": "LIVING_THINGS", "topic": "only female anglerfish has the glowing lure", "grades": [6, 7, 8], "terms": ["anglerfish", "female", "babae", "baye", "glowing lure", "pain", "ilaw", "suga", "male", "lalaki", "lalake", "walang ilaw", "walay suga", "isda", "fish", "deep sea", "kailaliman", "mas malaki ang babae"], "fact": {"tl": "Sa anglerfish, ang babae lamang ang may kumikinang na pain sa harap ng ulo; ang lalaki ay maliit, walang ilaw, at gumugugol ng buhay sa paghahanap ng babae.", "en": "In anglerfish, only the female has the glowing lure in front of her head; the male is tiny, has no light, and spends his life searching for a female.", "bis": "Sa anglerfish, ang baye ra ang adunay nagdan-ag nga pain sa atubangan sa ulo; ang laki gamay, walay suga, ug mogahin sa kinabuhi sa pagpangita og baye."}, "source": "Natural History Museum (encyclopedia-stable consensus)", "generator": "claude-workflow", "reviewed": false},
  {"id": "hydrothermal-vent-discovery-g8", "domain": "LIVING_THINGS", "topic": "hydrothermal vents surprised scientists", "grades": [7, 8, 9], "terms": ["hydrothermal vent", "discovery", "natuklasan", "nadiskobrehan", "scientists", "siyentipiko", "syentista", "1977", "submarine", "submarino", "life without sun", "kinabuhi nga walay adlaw", "walang araw", "nagulat", "natingala", "deep sea", "kailaliman", "surprise"], "fact": {"tl": "Hindi inaasahan ng mga siyentipiko na may buhay sa kailaliman ng dagat hanggang sa una nilang matuklasan ang masaganang hayop sa paligid ng mga hydrothermal vent noong 1977.", "en": "Scientists did not expect life so deep in the ocean until they first discovered animals thriving around hydrothermal vents in 1977.", "bis": "Wala damha sa mga siyentista nga adunay kinabuhi sa kalaliman sa dagat hangtod nga ila unang nadiskobrehan ang daghang mananap palibot sa mga hydrothermal vent niadtong 1977."}, "source": "Smithsonian Ocean; WHOI (encyclopedia-stable consensus)", "generator": "claude-workflow", "reviewed": false},
  {"id": "mammoth-frozen-ice-found-g5", "domain": "LIVING_THINGS", "topic": "frozen woolly mammoths", "grades": [4, 5, 6], "terms": ["woolly mammoth", "mammoth", "mamut", "mammut", "yelo", "frozen", "ice", "permafrost", "Siberia", "balat", "laman", "frozen mammoth", "napreserba", "na-frozen", "nakalubong", "tundra", "gelo", "preserved", "unod"], "fact": {"tl": "Dahil sobrang lamig ng lupa sa Siberia, may mga buong woolly mammoth na natagpuan na frozen sa yelo na buo pa ang balahibo, balat, at laman kahit libu-libong taon na silang patay.", "en": "Because the ground in Siberia is so cold, whole woolly mammoths have been found frozen in the ice with their fur, skin, and flesh still preserved even though they died thousands of years ago.", "bis": "Tungod kay bugnaw kaayo ang yuta sa Siberia, naay tibuok nga woolly mammoth nga nakit-an nga frozen sa yelo nga buo pa ang balhibo, panit, ug unod bisan libolibo na ka tuig sila patay."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mammoth-relative-elephant-g4", "domain": "LIVING_THINGS", "topic": "mammoth elephant relative", "grades": [3, 4, 5], "terms": ["woolly mammoth", "mammoth", "mamut", "elephant", "elepante", "kamag-anak", "relative", "sungay", "pangil", "tusk", "tusks", "balahibo", "fur", "malapit na kamag-anak", "paryente", "elepante sa karaan", "fossil", "makapal nga balhibo"], "fact": {"tl": "Ang woolly mammoth ay malapit na kamag-anak ng elepante ngunit may makapal na balahibo at napakahabang baluktot na pangil para mabuhay sa lupaing puno ng niyebe.", "en": "The woolly mammoth was a close relative of the elephant but had thick fur and very long curved tusks to survive in snowy lands.", "bis": "Ang woolly mammoth duol nga paryente sa elepante apan adunay baga nga balhibo ug taas kaayo nga liko-liko nga bangkil aron mabuhi sa yutang puno sa niyebe."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sabertooth-canine-teeth-g4", "domain": "LIVING_THINGS", "topic": "saber-tooth cat fangs", "grades": [3, 4, 5], "terms": ["saber-tooth cat", "saber-toothed", "sabertooth", "Smilodon", "pangil", "fangs", "canine", "ngipin", "mahabang pangil", "tusok", "predator", "mandaragit", "mananakmal", "manunukob", "leon sa karaan", "tigre", "bangkil", "taas nga bangkil"], "fact": {"tl": "Ang saber-tooth cat ay may dalawang napakahabang pangil na kasinghaba ng kutsilyo na ginagamit nito para tusukin ang malalaking hayop na hinuhuli.", "en": "The saber-tooth cat had two very long fangs as long as a knife that it used to stab the large animals it hunted.", "bis": "Ang saber-tooth cat adunay duha ka taas kaayo nga bangkil nga sama kataas sa kutsilyo nga gigamit niini sa pagtusok sa dagkong mananap nga gipangayam niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sabertooth-not-tiger-g5", "domain": "LIVING_THINGS", "topic": "saber-tooth cat is not a tiger", "grades": [4, 5, 6], "terms": ["saber-tooth cat", "saber-tooth tiger", "Smilodon", "tigre", "tiger", "hindi tigre", "pusa", "cat", "feline", "mananakmal", "extinct cat", "dili tigre", "iring", "laing klase", "not a tiger", "kamag-anak"], "fact": {"tl": "Kahit tinatawag itong saber-tooth tiger, ang hayop na ito ay hindi talagang tigre kundi isang kakaibang uri ng malaking pusa na matagal nang naglaho.", "en": "Even though it is called a saber-tooth tiger, this animal was not really a tiger but a different kind of big cat that died out long ago.", "bis": "Bisan og gitawag kining saber-tooth tiger, kining mananapa dili gyud tigre kondili lahi nga matang sa dakong iring nga dugay na nawala."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dodo-could-not-fly-g4", "domain": "LIVING_THINGS", "topic": "dodo flightless bird", "grades": [3, 4, 5], "terms": ["dodo", "dodo bird", "ibon", "bird", "hindi makalipad", "flightless", "cannot fly", "lumilipad", "pakpak", "wings", "langgam", "mabug-at", "mabigat", "dili makalupad", "extinct bird", "naglahong ibon", "pako"], "fact": {"tl": "Ang dodo ay isang malaking ibon na hindi kayang lumipad dahil maliit ang pakpak nito at mabigat ang katawan.", "en": "The dodo was a large bird that could not fly because its wings were small and its body was heavy.", "bis": "Ang dodo usa ka dakong langgam nga dili makalupad tungod kay gamay ra ang pako niini ug bug-at ang lawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dodo-no-fear-humans-g6", "domain": "LIVING_THINGS", "topic": "why the dodo went extinct", "grades": [5, 6, 7], "terms": ["dodo", "dodo bird", "naglaho", "extinct", "walang takot", "not afraid", "no fear of humans", "isla", "island", "Mauritius", "tao", "humans", "nahuli", "hinuli", "nawala", "walay kahadlok", "dali rang nadakpan", "easily caught", "predator"], "fact": {"tl": "Ang dodo ay namuhay sa isla na walang kalaban, kaya hindi ito natakot sa tao at madali itong nahuli hanggang sa tuluyang naglaho ang lahi nito.", "en": "The dodo lived on an island with no enemies, so it was not afraid of people and was easily caught until its whole kind disappeared forever.", "bis": "Ang dodo nagpuyo sa isla nga walay kaaway, mao nga wala kini mahadlok sa tawo ug dali rang nadakpan hangtod nga nawala na hingpit ang tibuok matang niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "megalodon-giant-shark-g5", "domain": "LIVING_THINGS", "topic": "megalodon giant shark", "grades": [4, 5, 6], "terms": ["megalodon", "pating", "shark", "higanteng pating", "giant shark", "malaki", "dako", "pinakamalaki", "biggest shark", "ngipin", "teeth", "dagat", "ocean", "extinct shark", "naglahong pating", "mananakmal", "predator", "mas malaki sa bus", "iho"], "fact": {"tl": "Ang megalodon ay isang higanteng pating na mas mahaba pa sa isang bus at malamang ang pinakamalaking pating na nabuhay kailanman.", "en": "The megalodon was a giant shark longer than a bus and was probably the biggest shark that ever lived.", "bis": "Ang megalodon usa ka higanteng iho nga mas taas pa sa usa ka bus ug lagmit ang pinakadako nga iho nga nabuhi sukad."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "megalodon-tooth-hand-size-g5", "domain": "LIVING_THINGS", "topic": "megalodon teeth fossils", "grades": [4, 5, 6], "terms": ["megalodon", "ngipin", "tooth", "teeth", "kasinlaki ng kamay", "hand-sized", "fossil", "fossils", "buto", "bukog", "kalansay", "pating", "shark", "palad", "kamay", "hand", "laki sa ngipin", "dakong ngipin", "kamot"], "fact": {"tl": "Karamihan sa nalalaman natin tungkol sa megalodon ay nagmula sa kanilang fossil na ngipin, na kasinlaki ng palad ng kamay ng isang tao.", "en": "Most of what we know about the megalodon comes from its fossil teeth, which are as big as a person's hand.", "bis": "Kadaghanan sa atong nahibaloan bahin sa megalodon naggikan sa ilang fossil nga ngipin, nga sama kadako sa palad sa kamot sa usa ka tawo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "megalodon-only-teeth-fossils-g7", "domain": "LIVING_THINGS", "topic": "why megalodon has few fossils", "grades": [6, 7, 8], "terms": ["megalodon", "fossil", "fossils", "ngipin", "teeth", "cartilage", "cartilago", "buto", "skeleton", "kalansay", "kartilago", "hindi naiiwan", "does not fossilize", "pating", "shark", "malambot na buto", "soft skeleton", "dili magpabilin", "humok", "rarely preserved"], "fact": {"tl": "Tulad ng mga pating ngayon, ang kalansay ng megalodon ay gawa sa malambot na cartilage na bihirang maging fossil, kaya halos ang ngipin lamang nito ang natitira.", "en": "Like sharks today, the megalodon's skeleton was made of soft cartilage that rarely becomes a fossil, so mostly only its teeth are left behind.", "bis": "Sama sa mga iho karon, ang kalansay sa megalodon hinimo sa humok nga cartilage nga panagsa rang mahimong fossil, mao nga halos ang ngipin lang niini ang nabilin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ground-sloth-giant-size-g4", "domain": "LIVING_THINGS", "topic": "giant ground sloth", "grades": [3, 4, 5], "terms": ["giant ground sloth", "ground sloth", "sloth", "Megatherium", "higante", "giant", "malaki", "dako", "kasinlaki ng elepante", "elephant-sized", "lupa", "ground", "nakatayo", "tumayo", "extinct", "naglaho", "mabagal", "slow", "higanteng sloth"], "fact": {"tl": "Ang giant ground sloth ay isang sloth na kasinlaki ng elepante na naglakad sa lupa, hindi tulad ng maliliit na sloth ngayon na nakabitin sa puno.", "en": "The giant ground sloth was a sloth as big as an elephant that walked on the ground, unlike today's small sloths that hang in trees.", "bis": "Ang giant ground sloth usa ka sloth nga sama kadako sa elepante nga naglakaw sa yuta, dili sama sa gagmay nga sloth karon nga nagbitay sa kahoy."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ground-sloth-stand-reach-g5", "domain": "LIVING_THINGS", "topic": "how the giant ground sloth ate", "grades": [4, 5, 6], "terms": ["giant ground sloth", "ground sloth", "Megatherium", "tumayo", "stand up", "nakatayo", "dahon", "leaves", "puno", "trees", "kumain", "mokaon", "hind legs", "matataas na sanga", "tall branches", "buntot", "tail", "mitindog", "abot ang dahon", "bitiis"], "fact": {"tl": "Kayang tumayo ng giant ground sloth gamit ang dalawang likurang binti at malaking buntot para abutin ang dahon sa matataas na sanga ng puno.", "en": "The giant ground sloth could stand up on its two hind legs and big tail to reach leaves on the tall branches of trees.", "bis": "Ang giant ground sloth makahimo sa pagtindog sa duha niya ka likod nga bitiis ug dakong ikog aron makab-ot ang dahon sa taas nga sanga sa kahoy."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "trilobites-very-old-g6", "domain": "LIVING_THINGS", "topic": "trilobites ancient sea animals", "grades": [5, 6, 7], "terms": ["trilobite", "trilobites", "matandang hayop", "ancient", "napakatanda", "very old", "dagat", "sea", "ocean", "fossil", "bago pa ang dinosaur", "before dinosaurs", "gumapang", "tubig", "extinct", "naglaho", "milyon-milyong taon", "karaan kaayo", "hayop-dagat"], "fact": {"tl": "Ang trilobite ay isang maliit na hayop-dagat na nabuhay milyon-milyong taon bago pa man lumitaw ang mga dinosaur.", "en": "The trilobite was a small sea animal that lived millions of years before the dinosaurs even appeared.", "bis": "Ang trilobite usa ka gamayng hayop sa dagat nga nabuhi milyon-milyong tuig sa wala pa motungha ang mga dinosaur."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "trilobites-common-fossil-g6", "domain": "LIVING_THINGS", "topic": "trilobite fossils are common", "grades": [5, 6, 7], "terms": ["trilobite", "trilobites", "fossil", "fossils", "karaniwan", "common", "madalas matagpuan", "often found", "matigas na balat", "hard shell", "exoskeleton", "baluti", "armor", "bato", "rock", "naglaho", "extinct", "kasagaran makit-an", "gahi nga panit", "mamatay"], "fact": {"tl": "Madalas matagpuan ang fossil ng trilobite dahil mayroon silang matigas na balat na parang baluti na madaling maging bato matapos silang mamatay.", "en": "Trilobite fossils are often found because they had a hard armor-like shell that easily turned to stone after they died.", "bis": "Kasagarang makit-an ang fossil sa trilobite tungod kay sila adunay gahi nga panit nga morag baluti nga dali rang nahimong bato human sila mamatay."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "trilobites-curl-defense-g7", "domain": "LIVING_THINGS", "topic": "how trilobites protected themselves", "grades": [6, 7, 8], "terms": ["trilobite", "trilobites", "pumulupot", "curl up", "nagbilot", "rolled up", "bola", "ball", "proteksyon", "defense", "kalaban", "predator", "ipagtanggol", "protect", "baluti", "armor", "mananakmal", "mibulot", "nagpanalipod", "malambot"], "fact": {"tl": "Kapag may nanganganib, kayang pumulupot ng trilobite na parang bola para protektahan ang malambot na ilalim ng katawan nito.", "en": "When in danger, a trilobite could curl up into a ball to protect the soft underside of its body.", "bis": "Kung adunay kakuyaw, ang trilobite makahimo sa pagbilot nga morag bola aron mapanalipdan ang humok nga ilawom sa lawas niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cloud-rat-extinct-relative-g6", "domain": "LIVING_THINGS", "topic": "extinct Philippine giant cloud rat", "grades": [5, 6, 7], "terms": ["cloud rat", "giant cloud rat", "Crateromys", "Ilin Island", "Mindoro", "daga", "ilaga", "naglaho", "extinct", "endemiko", "endemic", "Pilipinas", "Philippines", "hindi na nakikita", "not seen", "balahibo", "fur", "katutubo", "nawala", "native rat"], "fact": {"tl": "May isang uri ng giant cloud rat mula sa Ilin Island sa Pilipinas na ilang dekada nang hindi nakikita at malamang ay naglaho na.", "en": "There is a kind of giant cloud rat from Ilin Island in the Philippines that has not been seen for decades and may already be extinct.", "bis": "Adunay usa ka matang sa giant cloud rat gikan sa Ilin Island sa Pilipinas nga pila na ka dekada wala makita ug lagmit nawala na."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cloud-rat-bushy-tail-g5", "domain": "LIVING_THINGS", "topic": "giant cloud rat appearance", "grades": [4, 5, 6], "terms": ["cloud rat", "giant cloud rat", "bushy tail", "mabuhok na buntot", "buntot", "tail", "balahibo", "fur", "malambot", "soft", "hindi parang daga sa bahay", "not like house rat", "Pilipinas", "endemic", "ikog", "mabuhok na ikog", "ilaga", "nindot nga balhibo"], "fact": {"tl": "Hindi tulad ng karaniwang daga sa bahay, ang giant cloud rat ay may makapal na malambot na balahibo at malaking mabuhok na buntot.", "en": "Unlike the common house rat, the giant cloud rat has thick soft fur and a big bushy tail.", "bis": "Dili sama sa ordinaryong ilaga sa balay, ang giant cloud rat adunay baga ug humok nga balhibo ug dakong mabuhok nga ikog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "extinct-forever-meaning-g4", "domain": "LIVING_THINGS", "topic": "extinct means gone forever", "grades": [3, 4, 5], "terms": ["extinct", "naglaho", "gone forever", "wala na", "never come back", "hindi na babalik", "lahi", "species", "uri", "kind", "namatay", "died out", "habambuhay", "forever", "permanente", "dili na mobalik", "nawala na", "tanang matang", "nahanaw", "mamatay"], "fact": {"tl": "Kapag sinabing extinct o naglaho ang isang hayop, ibig sabihin lahat ng uri nito ay namatay na at hindi na ito babalik kailanman.", "en": "When an animal is said to be extinct, it means every one of its kind has died and it will never come back.", "bis": "Kung ang usa ka mananap giingong extinct o nawala na, kana nagpasabot nga ang tanang matang niini namatay na ug dili na gayod mobalik."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "extinction-habitat-loss-g6", "domain": "LIVING_THINGS", "topic": "habitat loss causes extinction", "grades": [5, 6, 7], "terms": ["extinction", "naglaho", "habitat", "tirahan", "tahanan", "home", "nawasak na gubat", "forest cut down", "pinuputol", "gubat", "walang makain", "no food", "tao", "humans", "kalasangan", "naputol", "habitat loss", "nawad-an ug puy-anan", "nasira ang tahanan", "kapuy-an"], "fact": {"tl": "Maraming hayop ang naglaho dahil nasira ang kanilang tahanan, gaya ng gubat na pinutol, kaya wala na silang lugar na matirhan o makain.", "en": "Many animals went extinct because their home was destroyed, like a forest being cut down, so they had no place to live or food to eat.", "bis": "Daghang mananap ang nawala tungod kay naguba ang ilang puy-anan, sama sa kalasangan nga giputol, mao nga wala na silay dapit puy-an o makaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "extinction-climate-change-g7", "domain": "LIVING_THINGS", "topic": "climate change and extinction", "grades": [6, 7, 8], "terms": ["extinction", "naglaho", "klima", "climate", "lumalamig", "cooling", "umiinit", "warming", "ice age", "panahon ng yelo", "pagbabago", "change", "nag-iba", "mammoth", "environment change", "nagbag-o ang klima", "mibugnaw", "nag-init", "dili makaangay", "makaangkop"], "fact": {"tl": "Nagbabago ang lahi ng hayop kapag mabilis na nagbago ang klima, gaya nang lumamig ang mundo noong panahon ng yelo, at ang hindi makaangkop ay naglalaho.", "en": "Animals can die out when the climate changes quickly, such as when the world cooled during the ice age, and those that cannot adjust become extinct.", "bis": "Mahanaw ang matang sa mananap kung kalit nga mausab ang klima, sama sa pagbugnaw sa kalibotan panahon sa ice age, ug ang dili makaangay mawala."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "most-species-extinct-g8", "domain": "LIVING_THINGS", "topic": "most species that lived are extinct", "grades": [7, 8, 9], "terms": ["extinct", "naglaho", "karamihan", "most", "halos lahat", "species", "lahi", "uri", "nabuhay", "ever lived", "fossil", "kasaysayan", "history of life", "wala na", "kadaghanan", "patay na", "kinabuhi sa yuta", "nahanaw na", "buhi karon"], "fact": {"tl": "Halos lahat ng uri ng nilalang na nabuhay sa Daigdig ay naglaho na, kaya higit na marami ang mga extinct na hayop kaysa sa mga nabubuhay ngayon.", "en": "Almost every kind of living thing that ever lived on Earth has gone extinct, so there are far more extinct animals than animals alive today.", "bis": "Halos tanang matang sa buhing butang nga nabuhi sa Yuta nawala na, mao nga mas daghan kaayo ang extinct nga mananap kaysa sa buhi karon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "how-we-know-extinct-fossils-g6", "domain": "LIVING_THINGS", "topic": "how we know about extinct animals", "grades": [5, 6, 7], "terms": ["fossil", "fossils", "buto", "bukog", "kalansay", "skeleton", "extinct", "naglaho", "paano natin alam", "how we know", "natuklasan", "discovered", "bato", "rock", "dug up", "hinukay", "gikalot", "ebidensya", "evidence", "nahibaw-an"], "fact": {"tl": "Alam natin ang tungkol sa mga hayop na naglaho dahil sa kanilang fossil — ang mga buto, ngipin, o bakas na naging bato sa loob ng napakatagal na panahon.", "en": "We know about animals that went extinct because of their fossils — the bones, teeth, or footprints that turned to stone over a very long time.", "bis": "Nahibaw-an nato ang bahin sa mga mananap nga nawala tungod sa ilang fossil — ang mga bukog, ngipin, o tunob nga nahimong bato sa hataas kaayong panahon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mammoth-ice-age-time-g6", "domain": "LIVING_THINGS", "topic": "woolly mammoth and the ice age", "grades": [5, 6, 7], "terms": ["woolly mammoth", "mammoth", "mamut", "ice age", "panahon ng yelo", "panahon sa yelo", "malamig", "cold", "niyebe", "snow", "lumipas", "ended", "uminit", "warmed", "naglaho", "extinct", "libong taon", "thousands of years", "nawala", "nainitan"], "fact": {"tl": "Ang woolly mammoth ay nabuhay noong panahon ng yelo, at marami sa kanila ang naglaho nang uminit ang mundo at natunaw ang niyebe.", "en": "The woolly mammoth lived during the ice age, and many died out when the world warmed and the snow melted.", "bis": "Ang woolly mammoth nabuhi panahon sa ice age, ug daghan kanila ang nawala sa dihang nag-init ang kalibotan ug natunaw ang niyebe."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sabertooth-strong-arms-g6", "domain": "LIVING_THINGS", "topic": "saber-tooth cat body", "grades": [5, 6, 7], "terms": ["saber-tooth cat", "Smilodon", "malakas na braso", "strong arms", "mabigat", "heavy", "matipuno", "muscular", "huli", "prey", "hinawakan", "grabbed", "mananakmal", "predator", "biktima", "kusgang bukton", "nakagunit", "kalamnan", "kusgan", "pangil"], "fact": {"tl": "Ang saber-tooth cat ay matipuno at may napakalakas na braso na ginagamit nito para pigilan at hawakan ang biktima bago ito tusukin ng pangil.", "en": "The saber-tooth cat was muscular with very strong front legs it used to hold down its prey before stabbing with its fangs.", "bis": "Ang saber-tooth cat kusgan ug adunay kusganong unahang bitiis nga gigamit niini sa pagpugong sa biktima sa dili pa kini tusokon sa bangkil."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "dodo-related-to-pigeon-g6", "domain": "LIVING_THINGS", "topic": "dodo related to the pigeon", "grades": [5, 6, 7], "terms": ["dodo", "kalapati", "pigeon", "kamag-anak", "relative", "paryente", "ibon", "bird", "langgam", "malayong kamag-anak", "family", "pamilya", "balahibo", "nakakagulat", "surprising", "duol nga paryente", "salampati", "punay"], "fact": {"tl": "Nakakagulat na ang pinakamalapit na kamag-anak ng dodo ay ang kalapati, kahit mas malaki at mas mabigat ang dodo kaysa rito.", "en": "Surprisingly, the dodo's closest relative is the pigeon, even though the dodo was much bigger and heavier.", "bis": "Makapakurat nga ang pinakaduol nga paryente sa dodo mao ang salampati, bisan og mas dako ug mas bug-at ang dodo niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "trilobites-many-kinds-g7", "domain": "LIVING_THINGS", "topic": "thousands of trilobite kinds", "grades": [6, 7, 8], "terms": ["trilobite", "trilobites", "libu-libo", "thousands", "maraming uri", "many kinds", "iba't ibang", "different", "species", "lahi", "maliit", "tiny", "malaki", "large", "sukat", "sizes", "libolibo ka klase", "nagkalainlain", "milyon ka tuig"], "fact": {"tl": "Mayroong libu-libong magkakaibang uri ng trilobite, mula sa kasinliit ng kuko hanggang sa kasinlaki ng plato, na nabuhay sa dagat sa loob ng milyon-milyong taon.", "en": "There were thousands of different kinds of trilobites, from as tiny as a fingernail to as big as a plate, living in the sea for hundreds of millions of years.", "bis": "Adunay libolibo ka lainlaing matang sa trilobite, gikan sa kagamay sa kuko hangtod sa kadako sa plato, nga nabuhi sa dagat sulod sa gatosan ka milyon ka tuig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ground-sloth-lived-with-humans-g7", "domain": "LIVING_THINGS", "topic": "giant ground sloth and early humans", "grades": [6, 7, 8], "terms": ["giant ground sloth", "ground sloth", "Megatherium", "tao", "humans", "unang tao", "early humans", "sabay nabuhay", "lived together", "kasabay", "naglaho", "extinct", "huli", "hunted", "kasaysayan", "dili sama sa dinosaur", "kauban sa tawo", "dungan nabuhi", "gipangayam"], "fact": {"tl": "Hindi tulad ng mga dinosaur, ang giant ground sloth ay nabuhay kasabay ng mga unang tao at naglaho lamang ilang libong taon na ang nakalipas.", "en": "Unlike the dinosaurs, the giant ground sloth lived at the same time as early humans and only went extinct a few thousand years ago.", "bis": "Dili sama sa mga dinosaur, ang giant ground sloth nabuhi dungan sa mga unang tawo ug nawala lamang pipila ka libo ka tuig ang milabay."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "extinction-natural-and-human-g7", "domain": "LIVING_THINGS", "topic": "natural and human causes of extinction", "grades": [6, 7, 8], "terms": ["extinction", "naglaho", "natural", "likas", "sanhi", "cause", "dahilan", "tao", "humans", "pangangaso", "hunting", "pamamaril", "habitat", "tirahan", "dalawang sanhi", "both", "mga sanhi", "kinaiyanhon", "pagpangayam", "pagkapuo"], "fact": {"tl": "May mga hayop na naglaho dahil sa likas na pagbabago ng kalikasan, ngunit marami ring naglaho dahil sa tao gaya ng sobrang pangangaso at pagsira ng kalikasan.", "en": "Some animals went extinct from natural changes in nature, but many also went extinct because of people through too much hunting and destroying nature.", "bis": "Adunay mga mananap nga nawala tungod sa kinaiyanhong pagbag-o sa kinaiyahan, apan daghan usab ang nawala tungod sa tawo pinaagi sa sobrang pagpangayam ug pagguba sa kinaiyahan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "megalodon-warm-ocean-g7", "domain": "LIVING_THINGS", "topic": "why megalodon went extinct", "grades": [6, 7, 8], "terms": ["megalodon", "pating", "shark", "naglaho", "extinct", "lumamig", "cooling", "dagat", "ocean", "pagkain", "food", "biktima", "prey", "nabawasan", "fewer", "klima", "climate", "nawala ang pagkain", "mibugnaw ang dagat", "kakulang sa pagkaon"], "fact": {"tl": "Ipinapalagay ng mga siyentista na naglaho ang megalodon nang lumamig ang dagat at nabawasan ang malalaking hayop na kinakain nito.", "en": "Scientists think the megalodon went extinct when the oceans cooled and there were fewer of the large animals it ate.", "bis": "Ang mga siyentista nagtuo nga ang megalodon nawala sa dihang mibugnaw ang dagat ug nikunhod ang dagkong mananap nga gikaon niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "extinct-vs-endangered-g6", "domain": "LIVING_THINGS", "topic": "difference between extinct and endangered", "grades": [5, 6, 7], "terms": ["extinct", "naglaho", "endangered", "nanganganib", "panganib", "at risk", "kaibahan", "difference", "wala na", "gone", "kaunti na lang", "very few left", "mabubuhay pa", "still alive", "proteksyon", "kalainan", "namiligro", "gamay na lang", "maluwas pa", "iligtas"], "fact": {"tl": "Ang extinct na hayop ay wala na talaga, ngunit ang endangered na hayop ay kakaunti na lang at maaari pang iligtas bago tuluyang maglaho.", "en": "An extinct animal is gone for good, but an endangered animal is one with very few left that can still be saved before it disappears.", "bis": "Ang extinct nga mananap wala na gayod, apan ang endangered nga mananap mao kadtong gamay na lang ang nahibilin ug maluwas pa sa dili pa kini mawala."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "honey-fungus-largest-organism-g6", "domain": "LIVING_THINGS", "topic": "largest living thing is a fungus", "grades": [6, 7, 8], "terms": ["honey fungus", "pinakamalaking organismo", "pinakadako nga organismo", "largest living thing", "fungus", "kabute", "uhong", "ilalim ng lupa", "ilalom sa yuta", "underground", "mycelium", "sinulid", "gamot", "milya", "libo-libong taon", "thousands of years", "Oregon", "kalat sa ilawom"], "fact": {"tl": "Ang pinakamalaking nabubuhay na bagay sa mundo ay hindi puno o balyena kundi isang fungus na tinatawag na honey fungus sa Oregon, na may mga sinulid sa ilalim ng lupa na kumalat sa ilang kilometro.", "en": "The largest living thing on Earth is not a tree or a whale but a honey fungus in Oregon, whose underground threads spread across several kilometers.", "bis": "Ang pinakadako nga buhing butang sa kalibotan dili kahoy o balyena kondili usa ka fungus nga gitawag og honey fungus sa Oregon, kansang mga lanot sa ilawom sa yuta mikatag og pipila ka kilometro."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mushroom-is-only-the-fruit-g6", "domain": "LIVING_THINGS", "topic": "the mushroom is only the fruiting body", "grades": [5, 6, 7], "terms": ["kabute", "uhong", "mushroom", "fruiting body", "bunga", "prutas ng fungi", "bahin lang", "bahagi lang", "mycelium", "sinulid sa ilalim", "ilalom sa yuta", "underground", "karamihan nasa lupa", "spore", "tubo pagkatapos ng ulan", "parte lang sa fungus"], "fact": {"tl": "Ang nakikita nating kabute ay tulad lamang ng bunga ng isang fungus — ang pinakamalaking bahagi ay nasa ilalim ng lupa bilang isang lambat ng mga sinulid na hindi natin nakikita.", "en": "The mushroom we see is just like the fruit of a fungus — most of it lives hidden underground as a web of threads we cannot see.", "bis": "Ang uhong nga atong makita sama lang sa bunga sa usa ka fungus — ang kinadak-ang bahin niini natago sa ilawom sa yuta isip usa ka lambat sa mga lanot nga dili nato makita."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fungi-closer-to-animals-g8", "domain": "LIVING_THINGS", "topic": "fungi are more like animals than plants", "grades": [7, 8, 9], "terms": ["fungi", "kabute", "uhong", "mas malapit sa hayop", "mas duol sa mananap", "closer to animals", "hindi halaman", "dili tanom", "kumukuha ng pagkain", "mokuha og pagkaon", "hindi gumagawa ng sariling pagkain", "chitin", "balat ng insekto", "panit sa insekto", "cell wall", "kingdom Fungi"], "fact": {"tl": "Kahit mukhang halaman ang fungi, mas malapit sila sa mga hayop dahil hindi sila gumagawa ng sariling pagkain at ang kanilang dingding ng selula ay yari sa chitin, ang parehong sangkap na nasa balat ng mga insekto.", "en": "Even though fungi look like plants, they are actually more closely related to animals because they cannot make their own food and their cell walls are made of chitin, the same material in insect shells.", "bis": "Bisan og morag tanom ang fungi, mas duol gyud sila sa mga mananap kay dili sila makahimo sa ilang kaugalingong pagkaon ug ang ilang bongbong sa selula hinimo sa chitin, ang samang materyal nga anaa sa panit sa mga insekto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fairy-ring-mushrooms-g5", "domain": "LIVING_THINGS", "topic": "fairy ring of mushrooms", "grades": [4, 5, 6], "terms": ["fairy ring", "bilog na kabute", "lingin nga uhong", "kabute na nasa bilog", "circle of mushrooms", "uhong", "mushroom", "tumutubo palabas", "motubo pagawas", "gilid", "ilalim ng lupa", "lumalaki ang singsing", "fungus", "patak ng pataas", "ring"], "fact": {"tl": "Minsan tumutubo ang mga kabute sa hugis-bilog na tinatawag na 'fairy ring' dahil lumalaki ang fungi pa-labas mula sa gitna, kaya laging nasa gilid ang mga bagong kabute.", "en": "Sometimes mushrooms grow in a circle called a 'fairy ring' because the fungus spreads outward from the center, so the newest mushrooms always pop up at the edge.", "bis": "Usahay motubo ang mga uhong sa porma nga lingin nga gitawag og 'fairy ring' kay ang fungus mokatag paggawas gikan sa tunga, mao nga ang bag-ong mga uhong kanunay motungha sa daplin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "glowing-mushrooms-bioluminescent-g6", "domain": "LIVING_THINGS", "topic": "some mushrooms glow in the dark", "grades": [5, 6, 7], "terms": ["kumikinang na kabute", "nagsiga nga uhong", "glowing mushroom", "bioluminescent", "umiilaw sa dilim", "mosiga sa kangitngit", "glow in the dark", "uhong", "mushroom", "berdeng ilaw", "berde nga kahayag", "green light", "kemikal", "kemikal nga kahayag", "foxfire", "ningning"], "fact": {"tl": "May ilang uri ng kabute na umiilaw sa dilim na may malambot na berdeng liwanag dahil gumagawa sila ng kanilang sariling ilaw sa pamamagitan ng isang kemikal na reaksyon.", "en": "Some kinds of mushrooms glow in the dark with a soft green light because they make their own light through a chemical reaction inside them.", "bis": "Adunay pipila ka matang sa uhong nga mosiga sa kangitngit nga adunay humok nga berdeng kahayag tungod kay maghimo sila sa ilang kaugalingong kahayag pinaagi sa usa ka kemikal nga reaksyon sulod nila."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "penicillin-from-mold-g7", "domain": "LIVING_THINGS", "topic": "the first antibiotic came from mold", "grades": [6, 7, 8, 9], "terms": ["penicillin", "penisilina", "amag", "mold", "agup-op", "gamot", "tambal", "medisina", "medicine", "unang antibiotic", "una nga antibiotic", "Alexander Fleming", "pumapatay ng bacteria", "mopatay og bacteria", "kills germs", "fungus", "Penicillium", "natuklasan", "nadiskubrehan", "nakapagligtas ng buhay"], "fact": {"tl": "Ang penicillin, ang unang gamot na antibiotic na nakapagligtas ng milyun-milyong buhay, ay galing sa isang amag na natuklasan ni Alexander Fleming nang mapansin niyang pinapatay nito ang bacteria.", "en": "Penicillin, the first antibiotic medicine that saved millions of lives, came from a mold that Alexander Fleming discovered when he noticed it was killing bacteria.", "bis": "Ang penicillin, ang unang antibiotic nga tambal nga nakaluwas og minilyon nga kinabuhi, naggikan sa usa ka agup-op nga nadiskobrehan ni Alexander Fleming sa dihang namatikdan niya nga gipatay niini ang bacteria."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "blue-cheese-mold-g6", "domain": "LIVING_THINGS", "topic": "blue cheese is made with mold on purpose", "grades": [5, 6, 7], "terms": ["blue cheese", "keso", "amag", "mold", "agup-op", "sinadya", "tinuyo", "on purpose", "asul na guhit", "asul nga linya", "blue veins", "fungus", "lasa", "lami", "flavor", "pagkain", "pagkaon", "ligtas kainin", "luwas kan-on"], "fact": {"tl": "Ang blue cheese ay sadyang ginagawan ng espesyal na amag na nagbibigay ng mga asul na guhit at malakas na lasa — kaya hindi lahat ng amag sa pagkain ay masama.", "en": "Blue cheese is made by adding a special mold on purpose, which gives it blue streaks and a strong flavor — so not all mold on food is bad.", "bis": "Ang blue cheese tinuyo nga butangan og pinasahi nga agup-op nga maghatag og asul nga mga linya ug kusog nga lami — busa dili tanan nga agup-op sa pagkaon daotan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "toyo-koji-mold-fermentation-g6", "domain": "LIVING_THINGS", "topic": "soy sauce is made by mold fermentation", "grades": [5, 6, 7], "terms": ["toyo", "soy sauce", "soya", "koji", "amag", "mold", "agup-op", "fermentation", "pagbuburo", "fungus", "toyong gawa sa amag", "soybeans", "monggo-toyo", "tahong-toyo", "mikrobyo", "mikrobiyo", "pagpapaasim", "tubig-tinapay", "natural", "kabute"], "fact": {"tl": "Ang toyo na nilalagay natin sa pagkain ay gawa sa soybeans na binubo ng isang espesyal na amag na tinatawag na koji, na siyang nagbibigay sa toyo ng kanyang lasa.", "en": "The soy sauce we put on our food is made from soybeans broken down by a special mold called koji, which gives soy sauce its flavor.", "bis": "Ang toyo nga atong ibutang sa pagkaon hinimo gikan sa soybeans nga gibungkag sa usa ka pinasahi nga agup-op nga gitawag og koji, nga maoy naghatag sa toyo sa iyang lami."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mycorrhizae-trees-share-food-g8", "domain": "LIVING_THINGS", "topic": "fungi connect tree roots underground", "grades": [7, 8, 9, 10], "terms": ["fungi", "kabute", "uhong", "ugat ng puno", "gamot sa kahoy", "tree roots", "mycorrhizae", "nag-uugnay", "magdugtong", "underground network", "lambat sa ilalim", "lambat sa ilawom", "nagbabahagi ng pagkain", "magbahin og pagkaon", "share food", "sustansya", "tulong", "tabang", "wood wide web", "magkatuwang"], "fact": {"tl": "Sa ilalim ng kagubatan, ang mga sinulid ng fungi ay dumudugtong sa mga ugat ng iba't ibang puno at tumutulong silang magpalitan ng tubig at sustansya, na para bang isang lihim na lambat.", "en": "Beneath a forest, fungal threads connect the roots of many different trees and help them share water and nutrients, like a hidden underground network.", "bis": "Sa ilawom sa kalasangan, ang mga lanot sa fungi magdugtong sa mga gamot sa lain-laing kahoy ug motabang nga magbinayloay og tubig ug sustansya, daw usa ka tinago nga lambat sa ilawom sa yuta."}, "source": "encyclopedia-stable consensus; NRC LS2.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "athletes-foot-fungus-g5", "domain": "LIVING_THINGS", "topic": "athlete's foot is a fungus", "grades": [4, 5, 6], "terms": ["alipunga", "athlete's foot", "an-an", "buni", "fungus", "kabute sa paa", "uhong sa tiil", "skin fungus", "makati", "katol", "kati", "basa at mainit", "basa ug init", "warm moist", "sapatos", "sapatos basa", "medyas", "pagkalat", "fungi sa balat", "tinea"], "fact": {"tl": "Ang alipunga sa pagitan ng mga daliri sa paa ay sanhi ng isang fungus na mahilig sa basa at mainit na lugar, kaya madali itong tumubo sa loob ng basang sapatos.", "en": "Athlete's foot between the toes is caused by a fungus that loves warm, damp places, which is why it grows easily inside wet shoes.", "bis": "Ang alipunga sa tunga-tunga sa mga tudlo sa tiil tungod sa usa ka fungus nga ganahan sa init ug mamasa nga dapit, mao nga sayon kini motubo sulod sa basa nga sapatos."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "yeast-makes-bubbles-co2-g5", "domain": "LIVING_THINGS", "topic": "yeast makes the gas that puffs up bread", "grades": [4, 5, 6], "terms": ["yeast", "lebadura", "fungi", "bula", "bula nga gas", "bubbles", "carbon dioxide", "gas", "tinapay", "pan", "bread", "umaalsa", "moalsa", "pa-buhaghag", "lukot", "kumakain ng asukal", "mokaon og asukal", "sugar", "kainan ng asukal", "fluffy", "malambot", "humok", "buhay na mikrobyo"], "fact": {"tl": "Ang lebadura ay isang buhay na fungi na kumakain ng asukal sa masa at naglalabas ng gas na bula; ang mga bulang ito ang nagpapaalsa at nagpapalambot sa tinapay.", "en": "Yeast is a living fungus that eats the sugar in dough and gives off bubbles of gas; these bubbles are what make bread rise and turn fluffy.", "bis": "Ang lebadura usa ka buhing fungus nga mokaon sa asukal sa minasa ug mobuga og bula nga gas; kining mga bulaa maoy makapaalsa ug makapahumok sa tinapay."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mushrooms-after-rain-g4", "domain": "LIVING_THINGS", "topic": "why mushrooms appear after rain", "grades": [3, 4, 5], "terms": ["kabute", "uhong", "mushroom", "pagkatapos ng ulan", "human sa ulan", "after rain", "basa", "mamasa", "moist", "mabilis tumubo", "paspas motubo", "grow fast", "tag-ulan", "ting-ulan", "rainy season", "biglang sumulpot", "kalit motungha", "fungus", "tubig"], "fact": {"tl": "Madalas tayong makakita ng mga kabute pagkatapos umulan dahil ang fungi ay nangangailangan ng basa at tubig para mabilis na umusbong ang kanilang mga kabute mula sa lupa.", "en": "We often see mushrooms pop up after it rains because fungi need dampness and water to push their mushrooms up quickly from the ground.", "bis": "Sagad ta makakita og mga uhong human mag-ulan tungod kay ang fungi nagkinahanglan og kabasa ug tubig aron paspas nga motubo ang ilang mga uhong gikan sa yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "spore-print-mushroom-g6", "domain": "LIVING_THINGS", "topic": "mushrooms drop a spore print", "grades": [5, 6, 7], "terms": ["kabute", "uhong", "mushroom", "spore print", "marka ng spore", "marka sa spore", "spore", "ilalim ng cap", "ilalom sa kalo", "gills", "pumapatak", "motulo", "guhit", "linya", "papel", "patong", "milyon-milyong spore", "kulay", "kolor", "fungus", "pagpaparami"], "fact": {"tl": "Kung magpapatong ka ng kabute sa papel nang ilang oras, maiiwan nito ang isang magandang patong ng kulay mula sa milyun-milyong maliliit na spore na bumabagsak mula sa ilalim nito.", "en": "If you set a mushroom cap on paper for a few hours, it leaves a pretty colored pattern made of the millions of tiny spores that fall from underneath it.", "bis": "Kung ipatong nimo ang uhong sa papel sulod sa pipila ka oras, mabilin niini ang usa ka nindot nga kolor nga porma gikan sa minilyon nga gagmayng spore nga matagak gikan sa ilawom niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fungi-rot-fallen-leaves-g5", "domain": "LIVING_THINGS", "topic": "fungi clear away fallen leaves and wood", "grades": [4, 5, 6], "terms": ["fungi", "kabute", "uhong", "amag", "nalaglag na dahon", "nangahulog nga dahon", "fallen leaves", "patay na kahoy", "patay nga kahoy", "dead wood", "naglalansag", "magdunot", "rot", "nabubulok", "nadunot", "linis ng kalikasan", "tig-recycle", "lupa", "yuta", "kung walang fungi", "natitipon"], "fact": {"tl": "Kung walang fungi na magbubulok ng mga nalaglag na dahon at patay na kahoy, matatabunan ng tambak na basura ang kagubatan; sila ang naglilinis at nagbabalik ng sustansya sa lupa.", "en": "If there were no fungi to rot fallen leaves and dead wood, forests would pile up with litter; fungi clean it away and return the nutrients to the soil.", "bis": "Kung walay fungi nga modunot sa nangahulog nga dahon ug patay nga kahoy, matabonan og tinapok nga basura ang kalasangan; ang fungi maoy maglimpyo ug magbalik sa sustansya ngadto sa yuta."}, "source": "encyclopedia-stable consensus; NRC LS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "diatoms-glass-shells-g8", "domain": "LIVING_THINGS", "topic": "diatoms have shells of glass", "grades": [7, 8, 9], "terms": ["diatom", "diatoms", "plankton", "munting halaman", "gagmayng tanom", "tiny algae", "lumot", "salamin", "bildo", "glass", "silica", "shell", "kabhang", "kabyaw", "magagandang hugis", "nindot nga porma", "patterns", "microscope", "mikroskopyo", "dagat", "tubig-tabang", "napakaliit"], "fact": {"tl": "Ang diatoms ay napakaliliit na halaman-plankton na may matigas na balot na yari sa salamin (silica), at may magagandang simetrikong hugis na makikita lamang sa mikroskopyo.", "en": "Diatoms are tiny plant-plankton with hard shells made of glass (silica), and they have beautiful symmetric patterns that can only be seen under a microscope.", "bis": "Ang diatoms gagmay kaayo nga tanom-plankton nga adunay gahi nga kabhang nga hinimo sa bildo (silica), ug adunay nindot nga simetriko nga mga porma nga makita lamang ilalom sa mikroskopyo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "red-tide-harmful-algae-g6", "domain": "LIVING_THINGS", "topic": "red tide is too much algae", "grades": [5, 6, 7, 8], "terms": ["red tide", "pamumula ng dagat", "pula nga dagat", "harmful algae", "nakakalasong lumot", "makahilo nga lumot", "plankton", "algae", "lumot", "lason", "hilo", "talaba", "tahong", "shellfish", "bawal kainin", "dili kan-on", "BFAR", "marami masyado", "sobra ka daghan", "bloom", "dagat na pula"], "fact": {"tl": "Ang red tide ay nangyayari kapag sobrang dami ng isang uri ng plankton sa dagat na nagpapapula sa tubig at gumagawa ng lason, kaya bawal munang kumain ng talaba at tahong tuwing may red tide.", "en": "Red tide happens when too much of a certain plankton fills the sea, turning the water reddish and making a poison, which is why we must not eat shellfish during a red tide.", "bis": "Ang red tide mahitabo kung sobra kadaghan ang usa ka matang sa plankton sa dagat nga makapapula sa tubig ug makahimo og hilo, mao nga dili una mokaon og talaba ug tahong panahon sa red tide."}, "source": "encyclopedia-stable consensus; PH BFAR red-tide advisories", "generator": "claude-workflow", "reviewed": false},
  {"id": "seaweed-not-a-plant-algae-g6", "domain": "LIVING_THINGS", "topic": "seaweed is algae not a true plant", "grades": [5, 6, 7], "terms": ["seaweed", "damong-dagat", "sagbot sa dagat", "lumot sa dagat", "algae", "halaman ng dagat", "hindi tunay na halaman", "dili tinuod nga tanom", "walang ugat", "walay gamot", "no roots", "walang dahon", "walay dahon", "lumulutang", "molutaw", "guso", "gulaman", "tanom sa dagat", "sinipsip ang sustansya"], "fact": {"tl": "Ang damong-dagat ay isang uri ng algae, hindi tunay na halaman, kaya wala itong tunay na ugat, tangkay, o dahon at sumisipsip ito ng sustansya nang direkta mula sa tubig-dagat.", "en": "Seaweed is a kind of algae, not a true plant, so it has no real roots, stems, or leaves and soaks up nutrients directly from the seawater.", "bis": "Ang sagbot sa dagat usa ka matang sa algae, dili tinuod nga tanom, busa wala kini tinuod nga gamot, punoan, o dahon ug mosuyop kini og sustansya direkta gikan sa tubig-dagat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bacteria-make-yogurt-g5", "domain": "LIVING_THINGS", "topic": "good bacteria make yogurt", "grades": [4, 5, 6], "terms": ["bacteria", "bakterya", "mabuting bacteria", "maayong bacteria", "good bacteria", "yogurt", "gatas", "milk", "naninigas", "molagom", "asim", "aslom", "sour", "fermentation", "pagbuburo", "mikrobyo", "mikrobiyo", "kefir", "hindi lahat masama", "dili tanan daotan", "makakain"], "fact": {"tl": "Hindi lahat ng bacteria ay nakakasakit — may mga mabuting bacteria na ginagamit para gawing yogurt ang gatas sa pamamagitan ng pagpapaasim at pagpapakapal nito.", "en": "Not all bacteria make us sick — some good bacteria are used to turn milk into yogurt by souring and thickening it.", "bis": "Dili tanan nga bacteria makapasakit — adunay maayong bacteria nga gigamit aron himoong yogurt ang gatas pinaagi sa pagpaaslom ug pagpalagom niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bacteria-in-our-gut-g7", "domain": "LIVING_THINGS", "topic": "helpful bacteria live in our gut", "grades": [6, 7, 8, 9], "terms": ["bacteria", "bakterya", "tiyan", "tinai", "gut", "bituka", "sikmura", "mabuting bacteria", "maayong bacteria", "tumutulong matunaw", "motabang og tunaw", "digestion", "pagtunaw", "bilyon-bilyon", "binilyon", "billions", "mikrobyo", "tumutulong sa katawan", "motabang sa lawas", "vitamins", "bitamina", "nakatira sa loob"], "fact": {"tl": "May bilyun-bilyong maliliit na bacteria na nakatira sa loob ng ating bituka, at marami sa kanila ay tumutulong sa atin na matunaw ang pagkain at gumawa ng ilang bitamina.", "en": "Billions of tiny bacteria live inside our intestines, and many of them help us digest our food and make certain vitamins.", "bis": "Adunay binilyon nga gagmayng bacteria nga nagpuyo sulod sa atong tinai, ug daghan kanila ang motabang nato sa pagtunaw sa pagkaon ug paghimo og pipila ka bitamina."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bacteria-too-small-to-see-g4", "domain": "LIVING_THINGS", "topic": "bacteria are too small to see without a microscope", "grades": [3, 4, 5], "terms": ["bacteria", "bakterya", "germ", "mikrobyo", "mikrobiyo", "napakaliit", "gagmay kaayo", "too small", "hindi nakikita", "dili makita", "invisible", "mikroskopyo", "microscope", "buhay", "buhi", "living", "everywhere", "kahit saan", "bisan asa", "isang patak ng tubig", "usa ka tulo sa tubig"], "fact": {"tl": "Ang bacteria ay napakaliliit na buhay na nilalang na hindi natin makikita ng mata; daan-libo ang kayang magtago sa isang patak lamang ng tubig.", "en": "Bacteria are living things so tiny we cannot see them with our eyes; hundreds of thousands can hide in a single drop of water.", "bis": "Ang bacteria mga buhing binuhat nga gagmay kaayo nga dili nato makita sa atong mata; gatusan ka libo ang makatago sa usa lang ka tulo sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "single-yeast-rises-whole-bread-g6", "domain": "LIVING_THINGS", "topic": "yeast multiplies very fast", "grades": [5, 6, 7], "terms": ["yeast", "lebadura", "fungi", "nagdadami", "magdaghan", "multiply", "mabilis dumami", "paspas modaghan", "isa naging marami", "warm dough", "mainit na masa", "init nga minasa", "asukal", "sugar", "tinapay", "pan", "bread", "buhay na mikrobyo", "nagpaparami", "umaalsa", "moalsa"], "fact": {"tl": "Sa mainit at matamis na masa, mabilis na dumarami ang lebadura sa pamamagitan ng paghahati-hati ng sarili, kaya kaunting yeast lang ay sapat nang magpaalsa ng isang buong tinapay.", "en": "In warm, sweet dough, yeast multiplies quickly by splitting into more and more cells, so just a little yeast is enough to raise a whole loaf of bread.", "bis": "Sa init ug tam-is nga minasa, paspas modaghan ang lebadura pinaagi sa pagbahin-bahin sa kaugalingon, mao nga gamay ra nga yeast igo na aron paalsahon ang usa ka tibuok tinapay."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "phytoplankton-feed-whales-g6", "domain": "LIVING_THINGS", "topic": "the biggest animals eat the tiniest plankton", "grades": [5, 6, 7], "terms": ["plankton", "phytoplankton", "balyena", "whale", "balena", "pinakamalaking hayop", "pinakadako nga mananap", "biggest animal", "kumakain ng plankton", "mokaon og plankton", "pinakamaliit", "pinakagamay", "smallest", "tiny", "pagkain ng dagat", "food chain", "kadena sa pagkaon", "salain ang tubig", "krill"], "fact": {"tl": "Kahit pinakamalaking hayop sa mundo ang balyena, marami sa kanila ay kumakain ng napakaliliit na plankton na sinasala lamang nila mula sa tubig-dagat.", "en": "Even though whales are the biggest animals on Earth, many of them eat the tiniest plankton, which they simply filter out of the seawater.", "bis": "Bisan og ang balyena mao ang pinakadako nga mananap sa kalibotan, daghan kanila ang mokaon sa gagmay kaayo nga plankton, nga ilang gisala lamang gikan sa tubig-dagat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lichen-grows-where-nothing-else-g7", "domain": "LIVING_THINGS", "topic": "lichen survives in harsh places", "grades": [6, 7, 8], "terms": ["lichen", "lumot-bato", "fungus", "algae", "bato", "bare rock", "hubo nga bato", "walang lupa", "walay yuta", "no soil", "matinding lamig", "grabe nga bugnaw", "extreme cold", "naninirahan", "mabuhi", "survive", "magkasamang nabubuhay", "nag-uunang tumubo", "pioneer", "tumutubo sa bato", "tundra"], "fact": {"tl": "Ang lichen ay kayang mabuhay sa mga lugar na halos walang ibang nilalang ang makakaya, tulad ng hubad na bato at napakalamig na lugar, dahil tinutulungan ng fungus at algae ang isa't isa.", "en": "Lichens can survive in places where almost nothing else can live, like bare rock and very cold lands, because the fungus and the alga help each other.", "bis": "Ang lichen makahimo og pagpuyo sa mga dapit nga halos walay laing binuhat nga makaagwanta, sama sa hubo nga bato ug bugnaw kaayo nga yuta, kay ang fungus ug ang algae magtinabangay."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "poisonous-vs-edible-mushroom-g5", "domain": "LIVING_THINGS", "topic": "some mushrooms are poisonous", "grades": [4, 5, 6], "terms": ["kabute", "uhong", "mushroom", "nakakalason", "makahilo", "poisonous", "makahilong uhong", "lason", "hilo", "hindi makakain", "dili kan-on", "edible", "makakain", "kakahuyan", "kalasangan", "huwag kainin", "ayaw kan-a", "kahawig", "managsama", "look-alike", "mapanganib", "delikado"], "fact": {"tl": "Hindi lahat ng kabute ay ligtas kainin — may ilang ligaw na kabute na nakakalason at maaaring magdulot ng matinding sakit, kaya hindi dapat kumain ng kabuteng hindi sigurado kung ano.", "en": "Not all mushrooms are safe to eat — some wild mushrooms are poisonous and can make a person very sick, so you should never eat a mushroom you are not sure about.", "bis": "Dili tanang uhong luwas kan-on — adunay pipila ka ihalas nga uhong nga makahilo ug makapasakit pag-ayo sa tawo, busa ayaw gyud pagkaon og uhong nga dili nimo sigurado kung unsa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mold-spores-float-in-air-g5", "domain": "LIVING_THINGS", "topic": "mold spores are floating in the air", "grades": [4, 5, 6], "terms": ["amag", "mold", "agup-op", "spore", "spores", "lumulutang sa hangin", "naglutaw sa hangin", "floating in air", "kahit saan", "bisan asa", "everywhere", "kaya tumutubo ang amag", "tinapay", "bread", "pagkain", "pagkaon", "basa", "init", "kusina", "kaya bumubulok", "nakaabot", "mikrobyo"], "fact": {"tl": "Ang dahilan kung bakit biglang tumutubo ang amag sa naiwang pagkain ay dahil palaging may maliliit na spore ng amag na lumulutang sa hangin sa paligid natin, naghihintay lamang ng basa at mainit na lugar.", "en": "The reason mold suddenly grows on leftover food is that tiny mold spores are always floating in the air around us, just waiting for a warm, damp spot.", "bis": "Ang hinungdan nganong kalit motubo ang agup-op sa nahabilin nga pagkaon mao nga kanunay adunay gagmayng spore sa agup-op nga naglutaw sa hangin libot nato, nga naghulat lang og init ug mamasa nga dapit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fungi-have-their-own-kingdom-g7", "domain": "LIVING_THINGS", "topic": "fungi are their own kingdom of life", "grades": [6, 7, 8, 9], "terms": ["fungi", "kabute", "uhong", "amag", "lebadura", "kaharian", "gingharian", "kingdom", "sariling grupo", "kaugalingong grupo", "hindi halaman hindi hayop", "dili tanom dili mananap", "not plant not animal", "klasipikasyon", "pagklasipikar", "scientist", "siyentipiko", "espesyal na grupo", "uri ng buhay"], "fact": {"tl": "Inilagay ng mga siyentipiko ang fungi sa sarili nilang kaharian ng buhay — hiwalay sa mga halaman at mga hayop — dahil ibang-iba ang paraan ng kanilang pamumuhay at pagkuha ng pagkain.", "en": "Scientists place fungi in their very own kingdom of life — separate from plants and from animals — because their way of living and getting food is so different.", "bis": "Gibutang sa mga siyentista ang fungi sa ilang kaugalingong gingharian sa kinabuhi — bulag sa mga tanom ug sa mga mananap — kay lahi kaayo ang ilang paagi sa pagpuyo ug pagkuha og pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "spirulina-edible-algae-g6", "domain": "LIVING_THINGS", "topic": "some algae can be eaten as food", "grades": [5, 6, 7], "terms": ["spirulina", "algae", "lumot", "makakain na lumot", "makaon nga lumot", "edible algae", "pagkain", "pagkaon", "berde", "berdeng lumot", "green", "protina", "protein", "sustansya", "supplement", "nori", "sushi", "damong-dagat", "lumot na pagkain", "malusog", "himsog"], "fact": {"tl": "Ang ilang algae tulad ng spirulina ay kinakain bilang masustansyang pagkain dahil puno ito ng protina, kaya hindi lahat ng lumot ay basta tinatanggal lamang.", "en": "Some algae such as spirulina are eaten as a healthy food because they are full of protein, so not all algae is just something to scrape away.", "bis": "Ang pipila ka algae sama sa spirulina gikaon isip himsog nga pagkaon kay puno kini og protina, mao nga dili tanang lumot kay basta lang kuhaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tempeh-mold-binds-soybeans-g7", "domain": "LIVING_THINGS", "topic": "a mold binds soybeans into tempeh", "grades": [6, 7, 8], "terms": ["tempeh", "soybeans", "monggo", "amag", "mold", "agup-op", "fungus", "pumupili", "magpilit", "binds", "nagdidikit", "magdugtong", "pagkain", "pagkaon", "fermentation", "pagbuburo", "protina", "protein", "puti na sinulid", "puti nga lanot", "white threads", "mycelium", "ligtas kainin"], "fact": {"tl": "Ang tempeh ay gawa sa soybeans na pinagdidikit-dikit ng mga puting sinulid ng isang espesyal na amag, na siyang nagbibigay dito ng matatag na hugis at karagdagang protina.", "en": "Tempeh is made from soybeans held together by the white threads of a special mold, which gives it a firm shape and extra protein.", "bis": "Ang tempeh hinimo gikan sa soybeans nga gidugtong sa puti nga mga lanot sa usa ka pinasahi nga agup-op, nga maoy naghatag niini og lig-on nga porma ug dugang protina."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "decomposers-clean-dead-animals-g5", "domain": "LIVING_THINGS", "topic": "microbes and fungi clean up dead things", "grades": [4, 5, 6], "terms": ["decomposer", "dekompiser", "tig-recycle", "patay na hayop", "patay nga mananap", "dead animals", "bacteria", "bakterya", "fungi", "kabute", "amag", "naglalansag", "magdunot", "nabubulok", "nadunot", "rot", "naglilinis ng kalikasan", "maglimpyo sa kinaiyahan", "kung wala sila", "nagtatambak", "lupa", "yuta"], "fact": {"tl": "Kapag may namatay na hayop sa kalikasan, ang mga bacteria at fungi ang dahan-dahang naglalansag dito pabalik sa lupa; kung wala sila, magtatambak ang mga patay na bagay sa lahat ng dako.", "en": "When an animal dies in nature, bacteria and fungi slowly break it down back into the soil; without them, dead things would pile up everywhere.", "bis": "Kung adunay mananap nga mamatay sa kinaiyahan, ang bacteria ug fungi maoy hinay-hinay nga modunot niini balik sa yuta; kung wala sila, magtapok ang patay nga mga butang bisan asa."}, "source": "encyclopedia-stable consensus; NRC LS2.B", "generator": "claude-workflow", "reviewed": false},
  {"id": "venus-flytrap-snap-g3", "domain": "LIVING_THINGS", "topic": "venus flytrap traps insects", "grades": [3, 4, 5], "terms": ["venus flytrap", "carnivorous plant", "insect", "trap", "halaman", "kumakain", "insekto", "lamok", "bumibitag", "nahubay", "naghuot", "tanom", "mokaon", "lakat", "molukop", "bitag", "leaves", "shut"], "fact": {"tl": "Ang Venus flytrap ay isang halaman na kumakain ng insekto: kapag may langaw na dumapo sa dahon nito, mabilis itong nagsasara na parang bibig at nakukulong ang insekto sa loob.", "en": "The Venus flytrap is a plant that eats insects: when a fly lands on its leaf, the leaf quickly snaps shut like a mouth and traps the insect inside.", "bis": "Ang Venus flytrap usa ka tanom nga mokaon og insekto: kung adunay langaw nga motugdon sa dahon niini, paspas kini nga mosira sama sa baba ug malit-ag ang insekto sa sulod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "venus-flytrap-trigger-hairs-g5", "domain": "LIVING_THINGS", "topic": "venus flytrap trigger hairs counting", "grades": [5, 6, 7, 8], "terms": ["venus flytrap", "trigger hairs", "balahibo", "buhok sensitibo", "bumibilang", "dalawang beses", "segundo", "mahapuhap", "duha ka higayon", "molukop", "naghuot", "sensitive hairs", "touch twice", "count", "electrical signal"], "fact": {"tl": "May maliliit na buhok-sensitibo (trigger hairs) sa loob ng Venus flytrap, at kailangang mahawakan ang mga ito ng dalawang beses sa loob ng ilang segundo bago magsara — kaya hindi ito nasasayang sa basta patak ng ulan.", "en": "The Venus flytrap has tiny trigger hairs inside, and they must be touched twice within a few seconds before the trap shuts — so it does not waste a snap on a raindrop.", "bis": "Adunay gagmay nga mga buhok nga sensitibo (trigger hairs) sa sulod sa Venus flytrap, ug kinahanglan kining mahikap og duha ka higayon sulod sa pipila ka segundo una kini mosira — busa dili kini masayang sa usa lang ka tulo sa ulan."}, "source": "encyclopedia-stable consensus; University of Zurich 2020", "generator": "claude-workflow", "reviewed": false},
  {"id": "venus-flytrap-why-eat-bugs-g4", "domain": "LIVING_THINGS", "topic": "why carnivorous plants eat insects", "grades": [4, 5, 6, 7], "terms": ["carnivorous plant", "why eat insects", "lupang mahirap", "sustansya", "nitrogen", "halaman na kumakain", "bakit", "ngano", "yutang pobre", "sustansiya", "kuhaon", "poor soil", "nutrients", "bog"], "fact": {"tl": "Karaniwang tumutubo ang mga halamang kumakain ng insekto sa lupang mahirap (kulang sa sustansya), kaya nakukuha nila ang nitrogen at iba pang sustansyang kailangan nila mula sa mga insektong nahuhuli nila.", "en": "Insect-eating plants usually grow in poor soil that lacks nutrients, so they get the nitrogen and other nutrients they need from the insects they catch.", "bis": "Kasagaran motubo ang mga tanom nga mokaon og insekto sa yutang pobre (kulang sa sustansiya), busa makuha nila ang nitrogen ug uban pang sustansiya nga ilang gikinahanglan gikan sa mga insekto nga ilang madakpan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pitcher-plant-trap-g4", "domain": "LIVING_THINGS", "topic": "pitcher plant pitfall trap", "grades": [4, 5, 6], "terms": ["pitcher plant", "nepenthes", "pitsel", "halamang baso", "insekto", "nahuhulog", "tubig", "natutunaw", "madulas", "natunaw", "matang-bukid", "nahulog", "natunaw", "slippery", "digest", "pitfall"], "fact": {"tl": "Ang pitcher plant ay may dahong hugis-pitsel na puno ng likido; nadudulas dito ang insektong dumarating at nahuhulog sa loob, kung saan ito unti-unting natutunaw.", "en": "The pitcher plant has a leaf shaped like a pitcher full of liquid; an insect slips on it and falls inside, where it is slowly digested.", "bis": "Ang pitcher plant adunay dahon nga porma og pitsel nga puno og likido; madulas ang insekto nga moduol ug mahulog sa sulod, diin kini hinay-hinay nga matunaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pitcher-plant-philippines-attenboroughii-g6", "domain": "LIVING_THINGS", "topic": "giant philippine pitcher plant", "grades": [6, 7, 8], "terms": ["philippine pitcher plant", "nepenthes attenboroughii", "palawan", "pitsel", "daga", "rat", "malaking pitcher", "ilaga", "endemic", "katutubo", "kinadak-an", "giant", "Mount Victoria"], "fact": {"tl": "Sa Palawan, Pilipinas matatagpuan ang Nepenthes attenboroughii, isa sa pinakamalaking pitcher plant sa mundo — sapat ang laki ng pitsel nito para makahuli minsan ng maliliit na hayop tulad ng daga.", "en": "In Palawan, the Philippines, grows Nepenthes attenboroughii, one of the largest pitcher plants in the world — its pitcher is big enough to sometimes catch small animals like rats.", "bis": "Sa Palawan, Pilipinas makit-an ang Nepenthes attenboroughii, usa sa pinakadako nga pitcher plant sa kalibotan — igo ka dako ang pitsel niini aron makadakop usahay og gagmayng hayop sama sa ilaga."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rafflesia-largest-flower-g4", "domain": "LIVING_THINGS", "topic": "rafflesia largest flower", "grades": [4, 5, 6], "terms": ["rafflesia", "largest flower", "pinakamalaking bulaklak", "bulaklak", "isang metro", "pinakadako nga bulak", "bulak", "metro", "biggest bloom", "world", "mundo", "kalibotan"], "fact": {"tl": "Ang Rafflesia ang may pinakamalaking bulaklak sa mundo — umaabot sa halos isang metro ang lapad nito, kasinlaki ng isang gulong ng kotse.", "en": "The Rafflesia has the largest single flower in the world — it can grow almost a meter wide, about the size of a car tire.", "bis": "Ang Rafflesia maoy adunay pinakadako nga usa ka bulak sa kalibotan — moabot kini og halos usa ka metro ang gilapdon, sama kadako sa usa ka ligid sa awto."}, "source": "Guinness World Records; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rafflesia-corpse-smell-g5", "domain": "LIVING_THINGS", "topic": "rafflesia smells like rotting meat", "grades": [5, 6, 7], "terms": ["rafflesia", "corpse flower", "amoy bulok", "baho", "langaw", "nabubulok na karne", "baho nga karne", "baho sama sa patay", "langaw", "pollinate", "polinasyon", "rotting meat", "flies", "stink"], "fact": {"tl": "Ang Rafflesia ay umaamoy ng nabubulok na karne; ang mabahong amoy na ito ang umaakit sa mga langaw na siyang tumutulong magdala ng pollen nito sa ibang bulaklak.", "en": "The Rafflesia smells like rotting meat; this foul smell attracts flies, which help carry its pollen to other flowers.", "bis": "Ang Rafflesia mobaho sama sa nadunot nga karne; kining baho nga panimaho maoy modani sa mga langaw nga maoy motabang pagdala sa pollen niini ngadto sa ubang bulak."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rafflesia-no-leaves-parasite-g7", "domain": "LIVING_THINGS", "topic": "rafflesia is a parasitic plant", "grades": [7, 8, 9], "terms": ["rafflesia", "parasite plant", "walang dahon", "walang ugat", "parasitiko", "namamahay sa ibang halaman", "wala'y dahon", "wala'y gamot", "parasito", "vine", "tetrastigma", "host", "no leaves no roots", "parasitic"], "fact": {"tl": "Ang Rafflesia ay walang dahon, walang tangkay, at walang ugat na makikita — isa itong parasitiko na nabubuhay sa loob ng isang baging at lumalabas lamang kapag mamumulaklak.", "en": "The Rafflesia has no visible leaves, stem, or roots — it is a parasite that lives inside a vine and emerges only when it blooms.", "bis": "Ang Rafflesia walay dahon, walay punoan, ug walay gamot nga makita — usa kini ka parasito nga nagpuyo sa sulod sa usa ka liana ug mogawas lamang kung mamulak na."}, "source": "encyclopedia-stable consensus; Britannica", "generator": "claude-workflow", "reviewed": false},
  {"id": "makahiya-folds-touch-g3", "domain": "LIVING_THINGS", "topic": "makahiya folds when touched", "grades": [3, 4, 5], "terms": ["makahiya", "sensitive plant", "mimosa pudica", "nahihiya", "dahon", "kumukulot", "nagsasara", "hinipo", "huyang", "mahuyang", "molukot", "nagsira", "gihikap", "folds", "shy plant", "touch", "leaves close"], "fact": {"tl": "Ang makahiya (Mimosa pudica) ay mabilis na nagtitiklop ng mga dahon nito kapag hinipo, na parang nahihiya — kaya ito tinawag na 'makahiya'.", "en": "The makahiya (Mimosa pudica) quickly folds up its leaves when touched, as if it were shy — which is why it is called 'makahiya' (the shy plant).", "bis": "Ang makahiya (Mimosa pudica) paspas nga molukot sa mga dahon niini kung hikapon, nga daw maulaw — mao nga gitawag kini og 'makahiya' o tanom nga maulawon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "makahiya-why-folds-water-g6", "domain": "LIVING_THINGS", "topic": "why makahiya leaves fold mechanism", "grades": [6, 7, 8], "terms": ["makahiya", "mimosa pudica", "bakit nagtitiklop", "tubig", "selula", "pulvinus", "ngano molukot", "tubig sa selula", "lumalabas ang tubig", "nawawala ang tubig", "water cells", "why folds", "limp", "defense"], "fact": {"tl": "Nagtitiklop ang makahiya dahil mabilis na lumalabas ang tubig mula sa mga selula sa puno ng dahon nito, kaya nawawalan ng tigas ang mga ito; pinaniniwalaang depensa ito laban sa mga hayop na kakain dito.", "en": "The makahiya folds because water quickly leaves the cells at the base of its leaves, making them go limp; this is thought to be a defense against animals that might eat it.", "bis": "Molukot ang makahiya tungod kay paspas nga mogawas ang tubig gikan sa mga selula sa punoan sa dahon niini, busa mahuyang kini; gituohan nga depensa kini batok sa mga hayop nga mokaon niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "makahiya-folds-at-night-g5", "domain": "LIVING_THINGS", "topic": "makahiya folds at night", "grades": [5, 6, 7], "terms": ["makahiya", "nagtitiklop sa gabi", "gabi", "natutulog", "dahon", "molukot sa gabi", "matulog", "kagabhion", "nyctinasty", "sleep movement", "night", "evening"], "fact": {"tl": "Bukod sa paghipo, nagtitiklop din ang mga dahon ng makahiya tuwing gabi at bumubukas muli pagsapit ng umaga, na parang natutulog ang halaman.", "en": "Besides being touched, the leaves of the makahiya also fold up at night and open again in the morning, as if the plant were sleeping.", "bis": "Gawas sa paghikap, molukot usab ang mga dahon sa makahiya panahon sa gabii ug moabli pag-usab inig kabuntag, nga daw natulog ang tanom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "seed-dispersal-why-travel-g3", "domain": "LIVING_THINGS", "topic": "why seeds need to travel", "grades": [3, 4, 5], "terms": ["seed dispersal", "buto", "naglalakbay", "bakit lumalayo", "espasyo", "bag-ong tanom", "binhi", "ngano molakaw", "magkadaiya", "kahayag", "travel away", "spread", "grow", "space"], "fact": {"tl": "Kailangang maglakbay ng mga buto palayo sa magulang na halaman para may sapat na espasyo, liwanag, at tubig ang bagong tutubo, at hindi sila magsisiksikan sa iisang lugar.", "en": "Seeds need to travel away from the parent plant so the new plants have enough space, light, and water, and do not crowd together in one spot.", "bis": "Kinahanglan molakaw ang mga liso palayo sa ginikanan nga tanom aron ang bag-ong motubo adunay igong luna, kahayag, ug tubig, ug dili sila magsikit-sikit sa usa lang ka dapit."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.5", "generator": "claude-workflow", "reviewed": false},
  {"id": "seed-dispersal-wind-g4", "domain": "LIVING_THINGS", "topic": "seeds carried by wind", "grades": [4, 5, 6], "terms": ["seed dispersal", "wind", "hangin", "lumilipad na buto", "pakpak", "balahibo", "dandelion", "hangin nagdala", "molupad nga liso", "pako", "balhibo", "winged seed", "parachute", "blow"], "fact": {"tl": "May mga butong dinadala ng hangin: ang iba ay may parang pakpak o balahibo (tulad ng dandelion) para makalutang sa hangin at marating ang malalayong lugar.", "en": "Some seeds are carried by the wind: some have wing-like or fluffy parts (like the dandelion) so they can float on the air and reach faraway places.", "bis": "Adunay mga liso nga gidala sa hangin: ang uban adunay sama-pako o balhibo nga bahin (sama sa dandelion) aron makalutaw sa hangin ug makaabot sa layong mga dapit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "seed-dispersal-water-coconut-g4", "domain": "LIVING_THINGS", "topic": "seeds carried by water coconut", "grades": [4, 5, 6], "terms": ["seed dispersal", "water", "tubig", "niyog", "lumulutang", "dagat", "coconut", "buko", "lumutaw", "dagat", "molutaw", "naglutaw", "float", "ocean", "river", "carried"], "fact": {"tl": "May mga butong dinadala ng tubig: ang niyog, halimbawa, ay lumulutang at maaaring tangayin ng dagat papunta sa malayong baybayin bago tumubo.", "en": "Some seeds are carried by water: the coconut, for example, floats and can be carried by the sea to a distant shore before it sprouts.", "bis": "Adunay mga liso nga gidala sa tubig: ang lubi, pananglitan, molutaw ug mahimong anuron sa dagat ngadto sa layong baybayon una kini motubo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "seed-dispersal-animals-eat-g4", "domain": "LIVING_THINGS", "topic": "seeds spread by animals eating fruit", "grades": [4, 5, 6], "terms": ["seed dispersal", "animals", "hayop", "prutas", "dumi", "kumakain", "ibon", "paniki", "buto sa dumi", "tae", "langgam", "kabog", "molakaw", "fruit", "droppings", "bird", "bat", "eat"], "fact": {"tl": "Maraming hayop tulad ng ibon at paniki ang kumakain ng prutas, at ang mga buto sa loob ay lumalabas sa kanilang dumi sa malayong lugar — kaya tumutubo doon ang bagong halaman.", "en": "Many animals like birds and bats eat fruit, and the seeds inside come out in their droppings far away — so new plants grow there.", "bis": "Daghang hayop sama sa langgam ug kabog ang mokaon og prutas, ug ang mga liso sa sulod mogawas pinaagi sa ilang tae sa layong dapit — busa motubo didto ang bag-ong tanom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "seed-dispersal-burrs-stick-g4", "domain": "LIVING_THINGS", "topic": "sticky hooked seeds cling to fur", "grades": [4, 5, 6], "terms": ["seed dispersal", "burr", "amorseko", "dumikit", "kawit", "balahibo", "damit", "kumakapit", "mokapyot", "amorseko", "tunok", "balhibo", "hook", "fur", "stick", "cling", "velcro"], "fact": {"tl": "May mga butong tulad ng amorseko na may maliliit na kawit, kaya kumakapit ang mga ito sa balahibo ng hayop o sa damit mo at nadadala sa ibang lugar — ito ang nagbigay-ideya sa imbensyong Velcro.", "en": "Some seeds like the amorseko (bur) have tiny hooks, so they cling to animal fur or your clothes and get carried elsewhere — this even inspired the invention of Velcro.", "bis": "Adunay mga liso sama sa amorseko nga adunay gagmayng kaw-it, busa mokapyot kini sa balhibo sa hayop o sa imong sinina ug madala sa ubang dapit — kini maoy nagdasig sa imbensyong Velcro."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "seed-dispersal-exploding-g6", "domain": "LIVING_THINGS", "topic": "seeds shot out by exploding pods", "grades": [6, 7, 8], "terms": ["seed dispersal", "exploding seeds", "pumuputok", "sumasabog", "buto", "bunga", "kusang pumuputok", "mobuto", "mosabog", "liso", "kahoy", "pod", "burst", "shoot", "fling", "self-dispersal"], "fact": {"tl": "May mga halamang itinatapon ang sariling buto sa pamamagitan ng pumuputok na bunga: kapag tuyo na ito, biglang sumasabog at pinapalipad ang mga buto palayo.", "en": "Some plants throw out their own seeds with pods that explode: when the pod dries, it suddenly bursts and flings the seeds away.", "bis": "Adunay mga tanom nga molabay sa kaugalingong liso pinaagi sa bunga nga mobuto: kung mauga na kini, kalit nga mosabog ug ipalupad ang mga liso palayo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bamboo-fastest-growing-plant-g4", "domain": "LIVING_THINGS", "topic": "bamboo fastest growing plant", "grades": [4, 5, 6], "terms": ["bamboo", "kawayan", "pinakamabilis tumubo", "isang araw", "mabilis", "kasagbutan", "kawayan", "paspas motubo", "usa ka adlaw", "fastest growing", "grow", "tall", "day"], "fact": {"tl": "Ang kawayan ay isa sa pinakamabilis tumubong halaman sa mundo — ang ilang uri nito ay makakatubo ng halos isang metro sa loob lamang ng isang araw.", "en": "Bamboo is one of the fastest-growing plants in the world — some kinds can grow almost a meter in just a single day.", "bis": "Ang kawayan usa sa pinakapaspas motubo nga tanom sa kalibotan — ang ubang matang niini makatubo og halos usa ka metro sulod lamang sa usa ka adlaw."}, "source": "encyclopedia-stable consensus; Guinness World Records", "generator": "claude-workflow", "reviewed": false},
  {"id": "bamboo-is-grass-g6", "domain": "LIVING_THINGS", "topic": "bamboo is a giant grass", "grades": [6, 7, 8], "terms": ["bamboo", "kawayan", "damo", "higanteng damo", "hindi puno", "sagbot", "kawayan", "dako nga sagbot", "dili kahoy", "grass family", "not a tree", "giant grass"], "fact": {"tl": "Kahit mukhang puno, ang kawayan ay talagang isang uri ng damo — ito ang pinakamalaking damo sa mundo.", "en": "Even though it looks like a tree, bamboo is actually a kind of grass — it is the largest grass in the world.", "bis": "Bisan og morag kahoy kini, ang kawayan tinuod nga usa ka matang sa sagbot — kini ang pinakadako nga sagbot sa kalibotan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sundew-sticky-trap-g5", "domain": "LIVING_THINGS", "topic": "sundew sticky carnivorous plant", "grades": [5, 6, 7], "terms": ["sundew", "drosera", "malagkit", "patak", "kumikinang", "insekto", "dumikit", "pulot", "malagkit", "mopilit", "tarog", "tubig-tubig", "sticky", "glue", "dewdrop", "trap"], "fact": {"tl": "Ang sundew ay halamang may maliliit na patak na kumikinang na parang hamog sa dahon nito, ngunit malagkit ang mga ito kaya nadidikit at nahuhuli ang insektong dumadapo.", "en": "The sundew is a plant with tiny glistening drops like dew on its leaves, but the drops are sticky, so insects that land get stuck and caught.", "bis": "Ang sundew usa ka tanom nga adunay gagmayng tulo nga mosidlak sama sa yamog sa dahon niini, apan pilit kini busa mopilit ug madakpan ang insekto nga motugdon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bladderwort-fastest-trap-g7", "domain": "LIVING_THINGS", "topic": "bladderwort fastest underwater trap", "grades": [7, 8, 9], "terms": ["bladderwort", "utricularia", "pinakamabilis na bitag", "tubig", "supot", "sumisipsip", "vacuum", "pinakapaspas nga bitag", "supot", "molibot", "underwater", "suction trap", "fastest", "millisecond"], "fact": {"tl": "Ang bladderwort ay halamang-tubig na may maliliit na supot na bumubitag; kapag nahipo ng maliit na hayop ang buhok nito, biglang sumisipsip ang supot at nakukuha ang biktima sa loob ng isang kisapmata — isa sa pinakamabilis na galaw sa mundo ng halaman.", "en": "The bladderwort is a water plant with tiny sac-like traps; when a small animal touches its hairs, the sac suddenly sucks it in within a blink — one of the fastest movements in the plant world.", "bis": "Ang bladderwort usa ka tanom sa tubig nga adunay gagmayng supot nga lit-ag; kung mahikap sa gamayng hayop ang balhibo niini, kalit nga mosuyop ang supot ug makuha ang biktima sulod sa usa ka pamilok — usa sa pinakapaspas nga lihok sa kalibotan sa mga tanom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "coco-de-mer-biggest-seed-g5", "domain": "LIVING_THINGS", "topic": "coco de mer largest seed", "grades": [5, 6, 7], "terms": ["coco de mer", "biggest seed", "pinakamalaking buto", "niyog-dagat", "mabigat", "palm", "pinakadako nga liso", "lubi sa dagat", "bug-at", "largest seed", "heaviest", "palm tree"], "fact": {"tl": "Ang coco de mer ay may pinakamalaki at pinakamabigat na buto sa buong mundo — ang isang buto nito ay maaaring umabot ng higit sa 15 kilo, mas mabigat pa sa isang batang sanggol.", "en": "The coco de mer has the largest and heaviest seed in the whole world — a single seed can weigh more than 15 kilograms, heavier than a baby.", "bis": "Ang coco de mer adunay pinakadako ug pinakabug-at nga liso sa tibuok kalibotan — ang usa ka liso niini mahimong moabot og kapin sa 15 ka kilo, mas bug-at pa sa usa ka masuso."}, "source": "encyclopedia-stable consensus; Guinness World Records", "generator": "claude-workflow", "reviewed": false},
  {"id": "titan-arum-corpse-flower-g6", "domain": "LIVING_THINGS", "topic": "titan arum tallest flower cluster", "grades": [6, 7, 8], "terms": ["titan arum", "corpse flower", "amorphophallus", "amoy patay", "pinakamataas", "bibihirang mamulaklak", "baho sama sa patay", "talagsaon mamulak", "tallest", "rare bloom", "stink", "decades"], "fact": {"tl": "Ang titan arum ay isa sa pinakamataas na namumulaklak na halaman, at gaya ng Rafflesia ay umaamoy ng patay na hayop; bihira itong mamulaklak — minsan, isa o ilang ulit lamang sa loob ng maraming taon.", "en": "The titan arum is one of the tallest flowering plants, and like the Rafflesia it smells of a dead animal; it rarely blooms — sometimes only once in several years.", "bis": "Ang titan arum usa sa pinakahabog nga namulak nga tanom, ug sama sa Rafflesia mobaho kini sama sa patayng hayop; talagsa kini mamulak — usahay kausa lang sulod sa daghang tuig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pitcher-plant-not-all-prey-g7", "domain": "LIVING_THINGS", "topic": "pitcher plants house living animals", "grades": [7, 8, 9], "terms": ["pitcher plant", "nepenthes", "hindi lahat biktima", "uod", "nakatira sa loob", "mutualism", "dili tanan biktima", "ulod", "nagpuyo sulod", "mosquito larva", "lives inside", "symbiosis"], "fact": {"tl": "Hindi lahat ng nahuhulog sa pitcher plant ay biktima — may ilang maliliit na hayop at uod na nabubuhay nang ligtas sa loob ng likido nito, at tumutulong pa ngang sirain ang nahuling insekto.", "en": "Not everything that falls into a pitcher plant is prey — some tiny animals and larvae live safely inside its liquid, and even help break down the trapped insects.", "bis": "Dili tanan nga mahulog sa pitcher plant kay biktima — adunay pipila ka gagmayng hayop ug ulod nga nagpuyo nga luwas sulod sa likido niini, ug motabang pa gani pagdunot sa nadakpang insekto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "flytrap-native-only-one-place-g6", "domain": "LIVING_THINGS", "topic": "venus flytrap natural range tiny", "grades": [6, 7, 8], "terms": ["venus flytrap", "katutubo", "isang lugar lamang", "north carolina", "maliit na lugar", "natural range", "usa ra ka dapit", "lumad", "native", "wild", "small area", "endangered"], "fact": {"tl": "Kahit kilala sa buong mundo, ang Venus flytrap ay likas na tumutubo lamang sa isang maliit na lugar sa silangang bahagi ng Estados Unidos — wala ito sa ibang dako ng kagubatan ng daigdig.", "en": "Even though it is famous worldwide, the Venus flytrap grows naturally in only one small area in the eastern United States — it is not found wild anywhere else.", "bis": "Bisan og bantogan sa tibuok kalibotan, ang Venus flytrap natural nga motubo lamang sa usa ka gamayng dapit sa sidlakang bahin sa Estados Unidos — wala kini sa laing lasang sa kalibotan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "makahiya-pink-flower-seeds-g5", "domain": "LIVING_THINGS", "topic": "makahiya pink flower and prickly stem", "grades": [5, 6, 7], "terms": ["makahiya", "mimosa pudica", "bulaklak", "rosas na bulaklak", "tinik", "tangkay", "bulak nga pink", "tunok", "punoan", "pink flower", "prickly", "thorn", "ball flower"], "fact": {"tl": "Bukod sa nagtitiklop na dahon, ang makahiya ay may maliliit na rosas na bulaklak na hugis-bola at may matitinik na tangkay na nakakatulong itong protektahan.", "en": "Besides its folding leaves, the makahiya has small pink ball-shaped flowers and prickly stems that help protect it.", "bis": "Gawas sa molukot nga dahon, ang makahiya adunay gagmayng pink nga bulak nga porma og bola ug tunokon nga punoan nga makatabang panalipod niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "seed-dormancy-wait-g6", "domain": "LIVING_THINGS", "topic": "seeds can wait years before sprouting", "grades": [6, 7, 8], "terms": ["seed dormancy", "buto", "naghihintay", "natutulog", "tuyot", "tubig", "pagtubo", "naghulat", "natulog nga liso", "tubig", "ulan", "dormant", "sprout", "wait", "germinate"], "fact": {"tl": "Maraming buto ang maaaring 'matulog' nang matagal — naghihintay sila sa lupa hanggang sa dumating ang sapat na tubig at init bago sila tumubo, minsan pagkalipas ng maraming taon.", "en": "Many seeds can 'sleep' for a long time — they wait in the soil until there is enough water and warmth before they sprout, sometimes after many years.", "bis": "Daghang liso ang mahimong 'matulog' og dugay — maghulat sila sa yuta hangtod nga moabot ang igong tubig ug kainit una sila motubo, usahay human sa daghang tuig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "carnivorous-plant-still-photosynthesis-g7", "domain": "LIVING_THINGS", "topic": "carnivorous plants still make own food", "grades": [7, 8, 9], "terms": ["carnivorous plant", "photosynthesis", "gumagawa ng pagkain", "araw", "dahon", "luntian", "naghimo og pagkaon", "adlaw", "berde", "still photosynthesize", "sunlight", "green", "own food"], "fact": {"tl": "Kahit kumakain ng insekto, ang mga halamang carnivorous ay gumagawa pa rin ng sariling pagkain mula sa sikat ng araw sa pamamagitan ng photosynthesis tulad ng ibang halaman — ang insekto ay dagdag-sustansya lamang.", "en": "Even though they eat insects, carnivorous plants still make their own food from sunlight through photosynthesis like other plants — the insects are just extra nutrients.", "bis": "Bisan og mokaon og insekto, ang mga tanom nga carnivorous naghimo gihapon sa ilang kaugalingong pagkaon gikan sa kahayag sa adlaw pinaagi sa photosynthesis sama sa ubang tanom — ang insekto dugang sustansiya lamang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rafflesia-philippines-species-g6", "domain": "LIVING_THINGS", "topic": "rafflesia grows in the philippines", "grades": [6, 7, 8], "terms": ["rafflesia", "philippines", "pilipinas", "bulaklak", "luzon", "gubat", "kabundukan", "bulak", "kalasangan", "endemic", "katutubo nga espisye", "native species", "found in", "rainforest"], "fact": {"tl": "May ilang uri ng Rafflesia na matatagpuan din sa kagubatan ng Pilipinas, kabilang ang mga espesyeng tanging dito lamang tumutubo sa buong mundo.", "en": "Several kinds of Rafflesia are also found in the rainforests of the Philippines, including species that grow nowhere else in the world.", "bis": "Daghang matang sa Rafflesia ang makit-an usab sa kalasangan sa Pilipinas, lakip ang mga espisye nga dinhi lamang motubo sa tibuok kalibotan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "glass-from-melted-sand-g5", "domain": "MATTER", "topic": "glass is made from melted sand", "grades": [4, 5, 6], "terms": ["salamin", "bubog", "glass", "buhangin", "sand", "tinunaw", "matunaw", "init", "mainit", "oven", "factory", "ginama", "gawa sa", "gihimo", "gilanay", "clear", "transparent", "saan galing ang salamin", "unsa gigikanan sa salamin"], "fact": {"tl": "Ang salamin ay gawa sa buhangin na tinunaw sa sobrang init na oven hanggang maging likido, pagkatapos ay hinuhubog at pinapalamig hanggang maging matigas at malinaw.", "en": "Glass is made from sand melted in a very hot furnace until it turns liquid, then shaped and cooled until it becomes hard and clear.", "bis": "Ang salamin hinimo gikan sa balas nga gitunaw sa init kaayo nga hudno hangtod nga mahimong likido, dayon gihulma ug gipabugnaw hangtod nga mogahi ug mahimong tin-aw."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.8", "generator": "claude-workflow", "reviewed": false},
  {"id": "glass-recyclable-forever-g5", "domain": "MATTER", "topic": "glass can be recycled endlessly", "grades": [5, 6, 7], "terms": ["salamin", "bubog", "glass", "recycle", "paulit-ulit", "walang katapusan", "muli", "bag-o", "melt", "tinunaw", "botelya", "bote", "bottle", "paano ma-recycle ang salamin", "ngano pwede usbon ang salamin", "endless", "tunawin"], "fact": {"tl": "Ang salamin ay puwedeng i-recycle nang paulit-ulit at walang katapusan, dahil puwede itong tunawin at hubuging muli na hindi nababawasan ang kalidad nito.", "en": "Glass can be recycled over and over endlessly, because it can be melted and reshaped again without losing its quality.", "bis": "Ang salamin mahimong i-recycle balik-balik nga walay kataposan, kay mahimo kining tunawon ug hulmaon pag-usab nga dili maluya ang kalidad niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "glass-brittle-shatters-g6", "domain": "MATTER", "topic": "why glass is brittle and shatters", "grades": [5, 6, 7], "terms": ["salamin", "bubog", "glass", "babasagin", "durog", "basag", "mabuong", "mabuak", "brittle", "matigas", "stretch", "baluktot", "hindi lumiliko", "dili moliko", "ngano dali mabuak ang salamin", "bakit madaling mabasag", "shatter"], "fact": {"tl": "Ang salamin ay matigas pero malutong — hindi ito kayang yumuko, kaya kapag tinamaan nang malakas ay biglang nababasag sa halip na hubog.", "en": "Glass is hard but brittle — it cannot bend, so when hit hard it suddenly shatters instead of bending.", "bis": "Ang salamin gahi apan dali mabuak — dili kini makaliko, mao nga kon maigo og kusog kalit kining mabuak imbis nga moliko."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tempered-safety-glass-g7", "domain": "MATTER", "topic": "tempered safety glass breaks into blunt pieces", "grades": [6, 7, 8], "terms": ["tempered glass", "safety glass", "salaming pangkaligtasan", "salamin ng kotse", "sasakyan", "car window", "durog", "piraso", "blunt", "mapurol", "hindi matalas", "dili hait", "mas matibay", "stronger", "bakit di nakakahiwa ang basag na salamin", "ngano dili makasamad"], "fact": {"tl": "Ang tempered o safety glass ay pinapalamig nang napakabilis kaya mas matibay, at kapag nabasag ito ay nagiging maliliit na mapurol na piraso sa halip na matatalas na bubog, para hindi makasugat.", "en": "Tempered or safety glass is cooled very quickly so it is stronger, and when it breaks it crumbles into small blunt pieces instead of sharp shards, so it is less likely to cut you.", "bis": "Ang tempered o safety glass gipabugnaw og paspas kaayo busa mas lig-on, ug kon mabuak kini mahimong gagmay nga mapurol nga tipik imbis hait nga bubog, aron dili makasamad."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "metal-from-ore-smelting-g6", "domain": "MATTER", "topic": "metals come from rock ore by smelting", "grades": [6, 7, 8], "terms": ["metal", "bakal", "iron", "ore", "mineral", "bato", "rock", "mina", "mine", "tinunaw", "smelt", "init", "hinango", "kinuha", "extract", "saan galing ang bakal", "unsa gigikanan sa metal", "pagkuha sa metal", "puthaw"], "fact": {"tl": "Karamihan ng metal tulad ng bakal ay hindi natural na nakikitang purong metal — nakatago ito sa loob ng mga bato (ore), at kailangang painitin nang husto para mahango ang metal mula rito.", "en": "Most metals like iron are not found pure in nature — they are locked inside rocks called ore, and must be heated strongly to pull the metal out.", "bis": "Kadaghanan sa metal sama sa puthaw dili makita nga lunsay sa kinaiyahan — natago kini sulod sa mga bato nga gitawag og ore, ug kinahanglan painiton pag-ayo aron makuha ang metal gikan niini."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.8", "generator": "claude-workflow", "reviewed": false},
  {"id": "metal-melt-reshape-recycle-g6", "domain": "MATTER", "topic": "metals can be melted and reshaped so they recycle well", "grades": [5, 6, 7], "terms": ["metal", "bakal", "lata", "recycle", "tinunaw", "matunaw", "melt", "hinubog", "ginama", "muli", "bag-o", "new shape", "paulit-ulit", "paano ma-recycle ang metal", "ngano dali usbon ang metal", "scrap", "reshape", "na-recycle"], "fact": {"tl": "Ang metal ay madaling i-recycle dahil puwede itong tunawin at hubuging muli sa bagong hugis nang paulit-ulit nang hindi nasisira ang sustansya nito.", "en": "Metal is easy to recycle because it can be melted and reshaped into new forms over and over without losing its strength.", "bis": "Ang metal sayon i-recycle kay mahimo kining tunawon ug hulmaon pag-usab ngadto sa bag-ong porma balik-balik nga dili maguba ang kalig-on niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "aluminum-can-recycle-saves-energy-g7", "domain": "MATTER", "topic": "recycling aluminum cans saves a lot of energy", "grades": [6, 7, 8], "terms": ["aluminyo", "aluminum", "lata", "can", "softdrink", "recycle", "enerhiya", "energy", "nakakatipid", "tumipid", "makadaginot", "mas konti", "less", "bauxite", "mina", "ngano i-recycle ang lata", "bakit i-recycle ang aluminum", "tinunaw", "melt"], "fact": {"tl": "Ang pag-recycle ng lata ng aluminyo ay tumitipid ng napakalaking enerhiya — mas kaunti ang kuryenteng kailangan para tunawin ang lumang lata kaysa gumawa ng bagong aluminyo mula sa bato.", "en": "Recycling aluminum cans saves a huge amount of energy — it takes far less power to melt an old can than to make brand-new aluminum from rock.", "bis": "Ang pag-recycle sa lata nga aluminyo makadaginot og dako kaayong enerhiya — mas gamay ra ang kuryente nga kinahanglan aron tunawon ang daang lata kaysa maghimo og bag-ong aluminyo gikan sa bato."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "steel-iron-magnetic-g6", "domain": "MATTER", "topic": "steel and iron are attracted to magnets", "grades": [5, 6, 7], "terms": ["bakal", "iron", "asero", "steel", "magnet", "magnetiko", "nakakabit", "dumidikit", "nadani", "madani", "aluminyo", "aluminum", "tanso", "copper", "hindi dumidikit", "bakit dumidikit ang bakal sa magnet", "ngano modikit ang puthaw sa magnet", "tumbaga"], "fact": {"tl": "Ang bakal at asero (steel) ay nakakabit sa magnet, pero ang ibang metal tulad ng aluminyo at tanso ay hindi — kaya kayang ihiwalay ng malalaking magnet ang bakal na basura para i-recycle.", "en": "Iron and steel stick to magnets, but other metals like aluminum and copper do not — so big magnets can separate iron scrap for recycling.", "bis": "Ang puthaw ug asero (steel) modikit sa magnet, apan ang ubang metal sama sa aluminyo ug tumbaga dili — mao nga ang dagkong magnet makabulag sa puthaw nga basura aron i-recycle."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "stainless-steel-chromium-g8", "domain": "MATTER", "topic": "stainless steel resists rust because of chromium", "grades": [7, 8, 9], "terms": ["stainless steel", "asero", "kutsara", "tenedor", "kaldero", "hindi kinakalawang", "walay taya", "dili magtaya", "chromium", "kromyo", "halong metal", "alloy", "haluang metal", "protective layer", "manipis na panangga", "bakit hindi kinakalawang ang stainless", "ngano dili magtaya"], "fact": {"tl": "Ang stainless steel ay hindi madaling kalawangin dahil may halong metal na chromium ito, na gumagawa ng manipis at hindi nakikitang panangga sa ibabaw na pumipigil sa kalawang.", "en": "Stainless steel resists rust because it contains the metal chromium, which forms a thin invisible protective layer on its surface that blocks rusting.", "bis": "Ang stainless steel dili dali magtaya kay adunay sagol nga metal nga chromium, nga maghimo og nipis ug dili makita nga panagang sa ibabaw nga mopugong sa taya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bronze-age-before-iron-g7", "domain": "MATTER", "topic": "people used bronze before they could make iron", "grades": [6, 7, 8], "terms": ["tanso", "bronze", "copper", "lata", "tin", "sandata", "kasangkapan", "tool", "sinaunang tao", "ancient", "mas madaling gawin", "mababang init", "lower heat", "bakal", "iron", "Bronze Age", "Panahon ng Tanso", "bakit tanso muna bago bakal", "ngano tanso una"], "fact": {"tl": "Noong unang panahon, gumagawa muna ang mga tao ng kasangkapan mula sa bronze (tanso na may halong lata) bago sila natutong gumawa ng bakal, dahil mas mababang init lang ang kailangan para hubugin ang bronze.", "en": "Long ago, people made tools from bronze (copper mixed with tin) before they learned to make iron, because bronze needs less heat to shape.", "bis": "Kaniadto, ang mga tawo naghimo og himan gikan sa bronze (tumbaga nga gisagolan og lata) sa wala pa sila makakat-on paghimo og puthaw, kay ang bronze nagkinahanglan og ubos nga init aron hulmahon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rubber-from-tree-latex-g5", "domain": "MATTER", "topic": "natural rubber comes from tree sap", "grades": [4, 5, 6], "terms": ["goma", "rubber", "puno ng goma", "rubber tree", "dagta", "latex", "gatas ng puno", "sap", "puti", "white", "tinatapyas", "tapped", "gulong", "tire", "saan galing ang goma", "unsa gigikanan sa goma", "dagta sa kahoy", "puno"], "fact": {"tl": "Ang likas na goma ay galing sa maputing dagta (latex) ng puno ng goma — tinatapyasan ang balat ng puno at iniipon ang tumutulong dagta, na pinapatigas para maging goma.", "en": "Natural rubber comes from the white sap (latex) of the rubber tree — the bark is cut and the dripping sap is collected, then hardened into rubber.", "bis": "Ang natural nga goma gikan sa puti nga dagta (latex) sa kahoy nga goma — ginasamaran ang panit sa kahoy ug ginatigom ang nagtulo nga dagta, dayon gipagahi aron mahimong goma."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "vulcanization-rubber-stronger-g8", "domain": "MATTER", "topic": "vulcanization makes rubber stronger", "grades": [7, 8, 9], "terms": ["goma", "rubber", "gulong", "tire", "vulcanization", "vulcanizing", "sulfur", "asupre", "init", "heat", "mas matibay", "mas matigas", "stronger", "durable", "malagkit", "sticky", "lambot", "bakit hindi natutunaw ang gulong sa init", "ngano lig-on ang goma sa gulong"], "fact": {"tl": "Ang hilaw na goma ay malagkit at humihina sa init, pero kapag hinaluan ng asupre at pinainit (tinatawag na vulcanization), nagiging mas matibay at hindi na basta nalalambot sa araw — kaya ginagamit ito sa gulong.", "en": "Raw rubber is sticky and gets weak in heat, but when mixed with sulfur and heated (called vulcanization) it becomes much stronger and no longer softens easily in the sun — which is why it is used for tires.", "bis": "Ang hilaw nga goma malagkit ug maluya sa init, apan kon sagolan og asupre ug initon (gitawag og vulcanization) mahimo kining mas lig-on ug dili na dali mahumok sa adlaw — mao nga gigamit kini sa gulong."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-rubber-stretches-g7", "domain": "MATTER", "topic": "why rubber can stretch and snap back", "grades": [6, 7, 8], "terms": ["goma", "rubber", "rubber band", "lastiko", "stretch", "umuunat", "mahatak", "bumabalik", "mobalik", "snap back", "balik sa porma", "mahabang molekula", "long molecules", "coil", "kulot", "spring", "bakit umuunat ang goma", "ngano makaunat ang goma", "elastic", "nababanat"], "fact": {"tl": "Ang goma ay umuunat dahil ang loob nito ay gawa sa mahahaba at kulot na molekula na parang munting spring — kapag hinila ay umuunat ang mga ito, at kapag binitawan ay bumabalik sa dating hugis.", "en": "Rubber stretches because inside it is made of long, coiled molecules like tiny springs — when pulled they uncoil and stretch, and when let go they snap back to their original shape.", "bis": "Ang goma makaunat kay sulod niini hinimo sa tag-as ug kulot nga molekula nga sama sa gagmay nga spring — kon biraon mounat kini, ug kon buhian mobalik sa orihinal nga porma."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "plastic-from-oil-polymers-g7", "domain": "MATTER", "topic": "plastic is made from oil into long molecule chains", "grades": [6, 7, 8], "terms": ["plastik", "plastic", "langis", "oil", "petrolyo", "petroleum", "krudo", "molekula", "polymer", "mahabang kadena", "long chains", "ginama", "gihimo", "hinubog", "mold", "hugis", "saan galing ang plastik", "unsa gigikanan sa plastik", "sintetiko", "synthetic"], "fact": {"tl": "Ang karamihan ng plastik ay gawa mula sa langis (petrolyo), na ang maliliit na bahagi ay pinagdurugtong-durugtong para maging napakahabang kadena ng molekula na puwedeng hubugin sa anumang hugis.", "en": "Most plastic is made from oil (petroleum), whose tiny parts are joined together into very long chains of molecules that can be shaped into almost anything.", "bis": "Kadaghanan sa plastik hinimo gikan sa lana (petroleum), nga ang gagmay nga bahin niini ginadugtong-dugtong aron mahimong taas kaayo nga kadena sa molekula nga mahimong hulmahon ngadto sa bisan unsang porma."}, "source": "encyclopedia-stable consensus; NRC PS1.A", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-plastic-doesnt-rot-g6", "domain": "MATTER", "topic": "plastic does not rot because microbes cannot eat it", "grades": [5, 6, 7], "terms": ["plastik", "plastic", "hindi nabubulok", "dili madunot", "madunot", "rot", "bakterya", "bacteria", "mikrobyo", "microbe", "amag", "fungi", "hindi nakakain", "dili makaon", "gawa ng tao", "synthetic", "bakit hindi nabubulok ang plastik", "ngano dili madunot ang plastik", "basura", "matagal"], "fact": {"tl": "Ang plastik ay hindi nabubulok tulad ng dahon o pagkain dahil ito ay gawa ng tao at bago sa kalikasan — kaya hindi pa nakakaalam ang karamihan ng bakterya at amag kung paano ito kainin.", "en": "Plastic does not rot like a leaf or food because it is human-made and new to nature — so most bacteria and molds do not yet know how to eat it.", "bis": "Ang plastik dili madunot sama sa dahon o pagkaon kay hinimo kini sa tawo ug bag-o sa kinaiyahan — mao nga kadaghanan sa bakterya ug agup-op wala pa makahibalo unsaon kini pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "thermoplastic-melt-remold-g8", "domain": "MATTER", "topic": "some plastics can be melted and remolded for recycling", "grades": [7, 8, 9], "terms": ["plastik", "plastic", "tinunaw", "matunaw", "melt", "hinubog muli", "remold", "recycle", "thermoplastic", "botelya", "bote", "bottle", "init", "heat", "bagong gamit", "ngano pwede i-recycle ang plastik", "bakit may plastik na nare-recycle", "softens"], "fact": {"tl": "Ang ilang plastik ay lumalambot at natutunaw kapag pinainit, kaya puwede itong hubuging muli sa bagong bagay — ito ang dahilan kung bakit may mga plastik na puwedeng i-recycle.", "en": "Some plastics soften and melt when heated, so they can be remolded into new things — this is why certain plastics can be recycled.", "bis": "Ang ubang plastik mohumok ug matunaw kon initon, mao nga mahimo kining hulmahon pag-usab ngadto sa bag-ong butang — mao kini ang hinungdan nganong ang ubang plastik mahimong i-recycle."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "plastic-recycling-codes-g7", "domain": "MATTER", "topic": "the number inside the recycling triangle tells the plastic type", "grades": [6, 7, 8], "terms": ["plastik", "plastic", "numero", "number", "tatsulok", "triangle", "simbolo", "symbol", "recycling code", "uri ng plastik", "type", "botelya", "bote", "supot", "ano ang numero sa ilalim ng bote", "unsa ang numero sa plastik", "iba-ibang plastik", "sorting", "ano ibig sabihin"], "fact": {"tl": "Ang maliit na numero sa loob ng tatsulok na simbolo sa ilalim ng mga lalagyang plastik ay nagsasabi kung anong uri ng plastik ito, para malaman ng mga tao kung paano ito tama na i-recycle.", "en": "The small number inside the triangle symbol on the bottom of plastic containers tells what kind of plastic it is, so people know how to recycle it correctly.", "bis": "Ang gamay nga numero sulod sa triyanggulo nga simbolo sa ilawom sa mga sudlanan nga plastik nagsulti kon unsa nga matang sa plastik kini, aron mahibal-an sa mga tawo kon unsaon kini pag-recycle sa husto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "concrete-cement-sand-gravel-g6", "domain": "MATTER", "topic": "concrete is a mix of cement, sand, gravel, and water", "grades": [5, 6, 7], "terms": ["konkreto", "concrete", "semento", "cement", "buhangin", "sand", "graba", "gravel", "bato", "tubig", "water", "halo", "mixture", "tumitigas", "mogahi", "matigas", "building", "gusali", "bahay", "saan gawa ang konkreto", "unsa sagol sa konkreto", "cement vs concrete"], "fact": {"tl": "Ang konkreto ay halo ng semento, buhangin, graba, at tubig — ang semento ang dikit na bumubuklod sa lahat, at tumitigas ito na parang bato kapag natuyo.", "en": "Concrete is a mix of cement, sand, gravel, and water — the cement is the glue that binds it all, and it hardens like rock as it sets.", "bis": "Ang konkreto kay sagol sa semento, balas, graba, ug tubig — ang semento mao ang pandikit nga maghigot sa tanan, ug mogahi kini sama sa bato kon momala."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cement-from-limestone-g7", "domain": "MATTER", "topic": "cement is made by heating limestone", "grades": [6, 7, 8], "terms": ["semento", "cement", "apog", "limestone", "bato", "rock", "init", "heat", "oven", "hudno", "kiln", "durog", "pulbos", "powder", "ginama", "gihimo", "saan galing ang semento", "unsa gigikanan sa semento", "painitin", "binubukbok"], "fact": {"tl": "Ang semento ay gawa mula sa apog (limestone) na bato na pinainit nang husto hanggang maging pulbos — kapag hinaluan ng tubig, ito ay tumitigas pabalik na parang bato.", "en": "Cement is made from limestone rock heated very strongly until it becomes a powder — when water is added, it hardens back into a rock-like solid.", "bis": "Ang semento hinimo gikan sa apog (limestone) nga bato nga gipainit pag-ayo hangtod nga mahimong pulbos — kon dugangan og tubig, mogahi kini balik nga sama sa bato."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "concrete-strong-compression-rebar-g8", "domain": "MATTER", "topic": "concrete is strong when squeezed but needs steel bars for pulling", "grades": [7, 8, 9], "terms": ["konkreto", "concrete", "semento", "bakal", "rebar", "steel bar", "kabilya", "compression", "piniga", "pressing", "durog", "crack", "bumabasag", "mapaak", "stretch", "hila", "pull", "matibay", "ngano adunay bakal sa konkreto", "bakit may bakal sa konkreto", "reinforced", "haligi"], "fact": {"tl": "Ang konkreto ay napakatibay kapag pinipiga o tinutulak, pero mahina ito kapag hinihila o binabaluktot — kaya naglalagay ng mga bakal na kabilya sa loob nito para hindi ito basta mabasag.", "en": "Concrete is very strong when squeezed or pushed, but weak when stretched or bent — so steel bars are placed inside it to keep it from cracking.", "bis": "Ang konkreto lig-on kaayo kon piga-on o duso-on, apan luya kon birahon o baw-on — mao nga butangan og bakal nga rebar sa sulod niini aron dili kini dali mabuak."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cloth-from-fibers-g5", "domain": "MATTER", "topic": "cloth is woven from tiny fibers", "grades": [4, 5, 6], "terms": ["tela", "cloth", "fabric", "panapton", "hibla", "fiber", "sinulid", "thread", "hinabi", "weave", "habi", "cotton", "bulak", "gapas", "balahibo", "wool", "tupa", "sheep", "saan galing ang tela", "unsa gigikanan sa panapton", "ano ginawa ang damit", "pinagdugtong"], "fact": {"tl": "Ang tela ay gawa sa maraming manipis na hibla na pinipilipit na parang sinulid, pagkatapos ay hinahabi nang magkakapatong para maging isang piraso ng tela.", "en": "Cloth is made from many thin fibers twisted into thread, which is then woven over and under to form a single piece of fabric.", "bis": "Ang panapton hinimo gikan sa daghang nipis nga hibla nga gilubid aron mahimong sinulid, dayon gihabol nga sumpay-sumpay aron mahimong usa ka piraso nga panapton."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "natural-vs-synthetic-fibers-g6", "domain": "MATTER", "topic": "some cloth fibers come from plants and animals, others from oil", "grades": [6, 7, 8], "terms": ["tela", "cloth", "hibla", "fiber", "cotton", "bulak", "gapas", "wool", "balahibo", "silk", "seda", "natural", "halaman", "hayop", "plant", "animal", "polyester", "nylon", "plastik", "plastic", "langis", "oil", "synthetic", "gawa ng tao", "damit na plastik", "bakit may damit na galing sa langis", "ngano adunay sinina gikan sa lana"], "fact": {"tl": "Ang ilang hibla ng tela ay galing sa kalikasan — ang cotton ay mula sa halaman, ang wool ay mula sa balahibo ng tupa — pero ang iba tulad ng polyester at nylon ay gawa ng tao mula sa langis, kaya parang plastik.", "en": "Some cloth fibers come from nature — cotton from a plant, wool from a sheep's coat — but others like polyester and nylon are human-made from oil, so they are a kind of plastic.", "bis": "Ang ubang hibla sa panapton gikan sa kinaiyahan — ang cotton gikan sa tanom, ang wool gikan sa balhibo sa karnero — apan ang uban sama sa polyester ug nylon hinimo sa tawo gikan sa lana, mao nga sama sa plastik."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ceramic-hard-but-brittle-g7", "domain": "MATTER", "topic": "ceramics are hard and heatproof but brittle", "grades": [6, 7, 8], "terms": ["seramika", "ceramic", "palayok", "plato", "plate", "tasa", "cup", "luwad", "clay", "fired", "matigas", "mogahi", "hard", "init", "heat", "dili matunaw sa kalan", "durog", "brittle", "basag", "mabuak", "bakit di natutunaw ang plato sa init", "ngano dili matunaw ang plato"], "fact": {"tl": "Ang seramika tulad ng plato at palayok ay gawa sa luwad na pinatigas sa apoy — napakatigas nito at kayang tiisin ang init ng kalan, pero malutong din kaya nababasag kapag nahulog.", "en": "Ceramics like plates and pots are made of clay hardened by fire — they are very hard and can take the heat of a stove, but they are also brittle and shatter when dropped.", "bis": "Ang seramika sama sa plato ug kolon hinimo sa lapok nga gipagahi sa kalayo — gahi kaayo kini ug makaagwanta sa init sa kalan, apan dali usab mabuak kon mahulog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "paper-recycling-shortens-fibers-g7", "domain": "MATTER", "topic": "paper can only be recycled a limited number of times", "grades": [6, 7, 8], "terms": ["papel", "paper", "recycle", "hibla", "fiber", "umiikli", "mubo", "short", "fibers", "nababawasan", "limited", "ilang beses lang", "several times", "bagong kahoy", "new wood", "luma", "bakit hindi paulit-ulit ang papel", "ngano dili kanunay i-recycle ang papel", "mahina"], "fact": {"tl": "Ang papel ay puwedeng i-recycle pero ilang beses lang — sa tuwing ire-recycle, umiikli ang mga hibla nito, kaya kailangan pa ring dagdagan ng bagong hibla mula sa kahoy.", "en": "Paper can be recycled, but only a limited number of times — each time, its fibers get shorter, so new wood fibers must still be added.", "bis": "Ang papel mahimong i-recycle, apan pipila lang ka beses — kada i-recycle, momubo ang mga hibla niini, mao nga kinahanglan gihapon dugangan og bag-ong hibla gikan sa kahoy."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "glass-is-amorphous-solid-g8", "domain": "MATTER", "topic": "glass has no orderly crystal pattern unlike most solids", "grades": [8, 9, 10], "terms": ["salamin", "glass", "bubog", "solid", "amorphous", "walang ayos", "disordered", "kristal", "crystal", "yelo", "ice", "walang patern", "frozen liquid", "nagyeyelong likido", "atomo", "bakit kakaiba ang salamin", "ngano lahi ang salamin", "molekula"], "fact": {"tl": "Ang salamin ay kakaibang solid — kapag pinalamig ang tunaw na buhangin nang napakabilis, ang mga atomo nito ay nananatiling magulo na parang likido sa halip na magkaayos sa kristal, kaya minsan tinatawag itong 'frozen liquid'.", "en": "Glass is an unusual solid — when melted sand is cooled very fast, its atoms stay jumbled like a liquid instead of lining up into a crystal, which is why it is sometimes called a 'frozen liquid'.", "bis": "Ang salamin talagsaon nga solid — kon ang tinunaw nga balas pabugnawon og paspas kaayo, ang mga atomo niini magpabilin nga gubot sama sa likido imbis nga mag-han-ay ngadto sa kristal, mao nga usahay tawgon kining 'frozen liquid'."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-metal-cold-to-touch-g6", "domain": "MATTER", "topic": "metal feels colder than wood at the same temperature", "grades": [5, 6, 7], "terms": ["metal", "bakal", "kahoy", "wood", "malamig", "bugnaw", "cold", "feels colder", "init", "heat", "conductor", "nagpapadaloy", "magpadala", "kuha ng init", "kinukuha ang init", "kamay", "hand", "bakit mas malamig ang metal", "ngano mas bugnaw ang metal", "temperatura", "pareho ang temperatura"], "fact": {"tl": "Ang metal ay parang mas malamig kaysa kahoy kahit pareho ang temperatura nila, dahil mabilis nitong kinukuha ang init mula sa iyong kamay — hindi talaga ito mas malamig, mabilis lang itong nagpapadaloy ng init.", "en": "Metal feels colder than wood even at the same temperature, because it quickly pulls heat away from your hand — it is not actually colder, it just carries heat away fast.", "bis": "Ang metal mura'g mas bugnaw kaysa kahoy bisan parehas ra ang ilang temperatura, kay paspas niini nga kuhaon ang init gikan sa imong kamot — dili gyud kini mas bugnaw, paspas lang kini magpadala sa init palayo."}, "source": "encyclopedia-stable consensus; AAAS BSL Ch.4E", "generator": "claude-workflow", "reviewed": false},
  {"id": "recyclable-because-meltable-or-reusable-g6", "domain": "MATTER", "topic": "why some materials recycle easily and others do not", "grades": [6, 7, 8], "terms": ["recycle", "ma-recycle", "nare-recycle", "material", "metal", "salamin", "glass", "papel", "plastik", "tinunaw", "melt", "hinubog muli", "reused", "mahirap", "hard to recycle", "mixed", "pinaghalong materyales", "bakit may di nare-recycle", "ngano ang uban dili ma-recycle", "pure", "puro", "single material"], "fact": {"tl": "Madaling i-recycle ang materyales na puwedeng tunawin at hubuging muli (tulad ng salamin at metal) o durugin pabalik sa hibla (tulad ng papel); mahirap i-recycle ang mga bagay na pinaghalong iba't ibang materyales na hindi mapaghihiwalay.", "en": "Materials are easy to recycle if they can be melted and reshaped (like glass and metal) or mashed back into fibers (like paper); things made of many different materials mixed together are hard to recycle.", "bis": "Sayon i-recycle ang mga materyales nga mahimong tunawon ug hulmahon pag-usab (sama sa salamin ug metal) o dugmokon balik ngadto sa hibla (sama sa papel); lisod i-recycle ang mga butang nga sagol nga lainlaing materyales nga dili mabulag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "copper-best-everyday-wire-g7", "domain": "MATTER", "topic": "copper is used for wires because it carries electricity well", "grades": [6, 7, 8], "terms": ["tanso", "copper", "kable", "wire", "alambre", "kuryente", "electricity", "nagpapadaloy", "magpadala", "conductor", "mabuting tagahatid", "mura", "cheap", "nababaluktot", "bendable", "gold", "ginto", "mahal", "bakit tanso ang wire", "ngano tumbaga ang alambre", "electrical"], "fact": {"tl": "Ang tanso (copper) ay ginagamit sa karamihan ng wire ng kuryente dahil napakahusay nitong magpadaloy ng kuryente, madaling baluktutin, at mas mura kaysa ginto na halos kasinghusay rin.", "en": "Copper is used for most electrical wires because it carries electricity very well, bends easily, and is much cheaper than gold, which is almost as good.", "bis": "Ang tumbaga (copper) gigamit sa kadaghanan sa mga alambre sa kuryente kay maayo kaayo kining magpadala sa kuryente, sayon baw-on, ug mas barato kaysa bulawan nga halos parehas ka maayo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-fridge-slows-spoilage-g5", "domain": "MATTER", "topic": "why cold slows food spoiling", "grades": [5, 6, 7], "terms": ["refrigerator", "fridge", "cold", "bacteria", "slow", "temperature", "ref", "palamigan", "malamig", "mabagal", "mikrobyo", "bakterya", "pagkabulok", "mabulok", "preserba", "bugnaw", "hinay", "nahinay", "pagkadunot"], "fact": {"tl": "Hindi pinapatay ng ref ang mikrobyo na nagpapabulok ng pagkain — pinapabagal lang nito sila, dahil mas mabagal kumilos at dumami ang bakterya kapag malamig, kaya mas tumatagal ang pagkain.", "en": "A fridge does not kill the germs that spoil food — it only slows them down, because bacteria move and multiply more slowly in the cold, so the food lasts longer.", "bis": "Ang ref dili mopatay sa mikrobyo nga maoy hinungdan sa pagkadunot sa pagkaon — gipahinay lang niini sila, kay ang bakterya hinay molihok ug modaghan kung bugnaw, mao nga mas dugay ang pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "salting-pulls-water-bacteria-g6", "domain": "MATTER", "topic": "how salt preserves food", "grades": [6, 7, 8], "terms": ["salt", "preserve", "asin", "tubig", "water", "bacteria", "tuyo", "dehydrate", "draws out", "hinihigop", "preserba", "asgad", "bakterya", "tinapa", "daing", "tuyot", "gisuyop", "pagpreserba"], "fact": {"tl": "Inaasinan ang isda at karne dahil hinihigop ng asin ang tubig palabas ng pagkain at maging ng mga bakterya, at hindi mabuhay o dumami ang mikrobyo kapag walang sapat na tubig.", "en": "Fish and meat are salted because salt pulls water out of the food and out of the bacteria too, and germs cannot live or multiply without enough water.", "bis": "Ang isda ug karne gi-asinan kay ang asin mosuyop sa tubig gawas sa pagkaon ug bisan sa bakterya, ug ang mikrobyo dili mabuhi o modaghan kung walay igong tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "drying-removes-water-preserves-g5", "domain": "MATTER", "topic": "why drying preserves food", "grades": [5, 6, 7], "terms": ["dried", "drying", "tuyo", "tinuyo", "water", "preserve", "sun", "sun-dried", "araw", "mikrobyo", "mold", "amag", "daing", "pinatuyo", "tuyot", "bulad", "binulad", "walay tubig", "preserba", "init sa adlaw"], "fact": {"tl": "Tumatagal ang tuyong pagkain tulad ng daing, pasas, at tinuyong mangga dahil inalis na ang tubig na kailangan ng bakterya at amag para tumubo.", "en": "Dried foods like dried fish, raisins, and dried mango last a long time because the water that bacteria and mold need to grow has been removed.", "bis": "Ang gibulad nga pagkaon sama sa daing, pasas, ug binulad nga mangga dugay madunot kay ang tubig nga gikinahanglan sa bakterya ug agup-op aron motubo gikuha na."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "fermentation-microbes-make-food-g6", "domain": "MATTER", "topic": "what fermentation is", "grades": [6, 7, 8], "terms": ["fermentation", "ferment", "pickled", "fermented", "mikrobyo", "yeast", "bakterya", "burong", "atsara", "binuro", "fermentasyon", "lebadura", "sour", "sourness", "aslom", "gipaaslom", "binurong", "pagpaaslom", "pagkaon", "good bacteria"], "fact": {"tl": "Ang fermentation ay kapag pinapabago ng mabubuting mikrobyo ang pagkain — gaya sa burong isda, atsara, at yogurt — at ang asim at lasa ay galing sa mga sustansyang ginagawa ng mikrobyong ito.", "en": "Fermentation is when helpful microbes change food — like fermented fish, pickled vegetables, and yogurt — and the sourness and flavor come from substances those microbes make.", "bis": "Ang fermentation mao kung ang maayong mikrobyo mobag-o sa pagkaon — sama sa binurong isda, atsara, ug yogurt — ug ang aslom ug lami gikan sa mga sustansya nga gibuhat niini nga mikrobyo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-yogurt-from-milk-g6", "domain": "MATTER", "topic": "why milk turns into yogurt", "grades": [6, 7, 8], "terms": ["yogurt", "milk", "gatas", "bacteria", "sour", "fermented", "kapal", "mikrobyo", "aslom", "gipalapot", "binuro", "lactic acid", "aslom nga gatas", "namuo"], "fact": {"tl": "Nagiging yogurt ang gatas dahil kinakain ng mabubuting bakterya ang asukal sa gatas at gumagawa ng acid, na nagpapaasim at nagpapalapot ng gatas.", "en": "Milk turns into yogurt because helpful bacteria eat the sugar in milk and make an acid, which makes the milk sour and thick.", "bis": "Ang gatas mahimong yogurt kay ang maayong bakterya mokaon sa kalamay sa gatas ug mobuhat og acid, nga maoy hinungdan nga moaslom ug molapot ang gatas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-bread-chewy-gluten-g6", "domain": "MATTER", "topic": "why bread is stretchy and chewy", "grades": [6, 7, 8], "terms": ["gluten", "bread", "dough", "tinapay", "masa", "stretchy", "chewy", "nababanat", "flour", "harina", "makunat", "gluten", "tinapay", "gibanat", "minasa", "protina", "nagdikit", "elastiko"], "fact": {"tl": "Nababanat at makunat ang tinapay dahil sa gluten — isang protina sa harina na bumubuo ng network kapag minasa, at hinuhuli nito ang gas ng lebadura para umalsa ang masa.", "en": "Bread is stretchy and chewy because of gluten — a protein in flour that forms a stretchy network when kneaded, and it traps the yeast's gas so the dough can rise.", "bis": "Ang tinapay makunat ug elastiko tungod sa gluten — usa ka protina sa harina nga mohimo og network kung minasa, ug kini ang modakop sa gas sa lebadura aron motubo ang masa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ripe-fruit-ripens-neighbors-g5", "domain": "MATTER", "topic": "ripe fruit ripens nearby fruit", "grades": [5, 6, 7], "terms": ["ethylene", "ripen", "ripe", "hinog", "gas", "banana", "saging", "mangga", "gulay", "pinapahinog", "gipahinog", "ethylene", "hinog na", "kahinog", "mangga", "papel na supot", "mas mabilis"], "fact": {"tl": "Naglalabas ang hinog na prutas ng gas na ethylene na nakakapahinog din ng katabing prutas, kaya mas mabilis humihinog ang mangga o saging kapag inilagay sa iisang supot kasama ng hinog na prutas.", "en": "Ripe fruit gives off ethylene gas that also ripens the fruit beside it, which is why a mango or banana ripens faster when placed in one bag with already-ripe fruit.", "bis": "Ang hinog nga prutas mogawas og gas nga ethylene nga maoy mopahinog usab sa kasikbit nga prutas, mao nga mas paspas mohinog ang mangga o saging kung ibutang sa usa ka supot uban sa hinog na nga prutas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-banana-spots-brown-g4", "domain": "MATTER", "topic": "why bananas get brown spots", "grades": [4, 5, 6], "terms": ["banana", "brown spots", "saging", "mantsa", "ripen", "sweet", "matamis", "starch", "sugar", "almirol", "asukal", "nangingitim", "spots", "brown", "saging", "puntik", "itom", "nahinog", "tam-is", "kalamay"], "fact": {"tl": "Lumalabas ang kayumangging mantsa sa saging habang ito ay humihinog dahil nagiging asukal ang almirol nito, kaya mas matamis ang saging na maraming itim na mantsa.", "en": "Brown spots appear on a banana as it ripens because its starch is turning into sugar, which is why a banana with many dark spots tastes sweeter.", "bis": "Ang brown nga mga puntik sa saging mogawas samtang kini mohinog kay ang almirol niini nahimong kalamay, mao nga mas tam-is ang saging nga daghan og itom nga puntik."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-onion-tear-trick-g4", "domain": "MATTER", "topic": "trick to cut onions without crying", "grades": [4, 5, 6], "terms": ["onion", "sibuyas", "cry", "luha", "gas", "chill", "cold", "malamig", "tubig", "sharp knife", "matalim", "matalas", "hindi umiyak", "sibuyas", "hilak", "luha", "gas", "gibugnaw", "ref", "hait nga kutsilyo", "dili mohilak"], "fact": {"tl": "Mas kaunti ang luha kapag pinalamig muna ang sibuyas o gumamit ng matalim na kutsilyo, dahil mas konti ang nasisirang selula at gas na lumalabas mula sa sibuyas.", "en": "You cry less if you chill the onion first or use a sharp knife, because fewer cells are torn and less of the tear-causing gas escapes from the onion.", "bis": "Mas gamay ang luha kung bugnawon una ang sibuyas o mogamit og hait nga kutsilyo, kay mas gamay ang nadaot nga selula ug gas nga mogawas gikan sa sibuyas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "umami-savory-fifth-taste-g6", "domain": "MATTER", "topic": "umami the savory taste", "grades": [6, 7, 8], "terms": ["umami", "savory", "fifth taste", "lasa", "glutamate", "MSG", "vetsin", "sabaw", "malinamnam", "masarap", "umami", "lami", "linamnam", "panimpla", "glutamate", "karne", "kamatis", "keso", "panlasa"], "fact": {"tl": "May ikalimang lasa na tinatawag na umami o malinamnam na panlasa, na nararamdaman natin sa pagkaing may glutamate gaya ng karne, kamatis, keso, at sabaw — kaya napaka-sarap ng mga ito.", "en": "There is a fifth taste called umami, a savory taste we sense in foods rich in glutamate such as meat, tomatoes, cheese, and broth — which is why they taste so delicious.", "bis": "Adunay ikalima nga lami nga gitawag og umami o linamnam, nga atong mabati sa pagkaon nga adunay glutamate sama sa karne, kamatis, keso, ug sabaw — mao nga lami kaayo kini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-sugar-tastes-sweet-g5", "domain": "MATTER", "topic": "why sugar tastes sweet", "grades": [5, 6, 7], "terms": ["sweet", "sugar", "asukal", "taste buds", "panlasa", "dila", "tongue", "matamis", "receptor", "molekula", "tam-is", "kalamay", "panlasa", "dila", "receptor", "molecule", "gipadala sa utok", "enerhiya", "energy"], "fact": {"tl": "Matamis ang asukal dahil ang molekula nito ay nakakadikit sa mga espesyal na sensor sa dila na nagpapadala ng senyas na 'matamis' sa utak — paraan ng katawan para makilala ang pagkaing may energy.", "en": "Sugar tastes sweet because its molecules fit special sensors on the tongue that send a 'sweet' signal to the brain — the body's way of recognizing energy-rich food.", "bis": "Tam-is ang kalamay kay ang molekula niini modikit sa espesyal nga sensor sa dila nga magpadala og senyas nga 'tam-is' ngadto sa utok — paagi sa lawas aron mailhan ang pagkaon nga adunay enerhiya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-honey-never-spoils-g6", "domain": "MATTER", "topic": "why honey almost never spoils", "grades": [6, 7, 8], "terms": ["honey", "pulot", "bee", "pukyutan", "never spoils", "sugar", "asukal", "water", "bacteria", "hindi nabubulok", "tagal", "dugos", "pukyutan", "walay tubig", "bakterya", "dili madunot", "kalamay", "preserba"], "fact": {"tl": "Halos hindi nabubulok ang pulot-pukyutan dahil sobra-sobra ang asukal at napakakonti ng tubig dito, kaya hindi mabuhay ang bakterya sa loob nito.", "en": "Honey almost never spoils because it has so much sugar and so little water that bacteria cannot survive inside it.", "bis": "Ang dugos halos dili madunot kay sobra kaayo ang kalamay ug gamay ra kaayo ang tubig niini, mao nga ang bakterya dili mabuhi sa sulod niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-sourdough-bread-sour-g7", "domain": "MATTER", "topic": "why sourdough bread is sour", "grades": [7, 8, 9], "terms": ["sourdough", "sour bread", "maasim na tinapay", "wild yeast", "bacteria", "acid", "mikrobyo", "lebadura", "aslom", "tinapay", "binuro", "sourdough", "ihalas nga lebadura", "bakterya", "acid", "fermentasyon", "aslom nga lami"], "fact": {"tl": "Maasim ang sourdough dahil hindi lang lebadura ang nasa masa kundi pati mabubuting bakterya na gumagawa ng acid habang nagfe-ferment ang harina.", "en": "Sourdough bread is sour because the dough holds not just yeast but also helpful bacteria that make acid as the flour ferments.", "bis": "Aslom ang sourdough kay ang masa adunay dili lang lebadura kondili pati maayong bakterya nga mobuhat og acid samtang nag-ferment ang harina."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-vinegar-sour-acetic-g6", "domain": "MATTER", "topic": "why vinegar is sour", "grades": [6, 7, 8], "terms": ["vinegar", "suka", "sour", "acid", "acetic", "maasim", "fermented", "alak", "alcohol", "mikrobyo", "bakterya", "aslom", "suka", "acetic acid", "binuro", "fermented", "alkohol", "pang-asim"], "fact": {"tl": "Maasim ang suka dahil naglalaman ito ng acetic acid, na ginagawa ng bakterya kapag pinapabago nila ang alak o alkohol — kaya nga galing ang suka sa fermented na katas.", "en": "Vinegar is sour because it contains acetic acid, which bacteria make when they change alcohol — that is why vinegar comes from a fermented juice.", "bis": "Aslom ang suka kay kini adunay acetic acid, nga gibuhat sa bakterya kung ilang bag-ohon ang alkohol — mao nga ang suka gikan sa fermented nga duga."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "freezing-stops-spoilage-best-g5", "domain": "MATTER", "topic": "why frozen food lasts longest", "grades": [5, 6, 7], "terms": ["frozen", "freezer", "yelo", "ice", "preserve", "stops", "bacteria", "huminto", "mabagal", "frozen", "gipalamig", "yelo", "gipatugnaw", "bakterya", "mihunong", "dili modaghan", "preserba", "mas dugay"], "fact": {"tl": "Mas matagal ang pagkaing nasa freezer kaysa sa ref dahil sa sobrang lamig, halos huminto ang paggalaw at pagdami ng bakterya — hindi sila namamatay, hinihinto lang.", "en": "Frozen food lasts longer than food in the fridge because the deep cold almost stops bacteria from moving and multiplying — it does not kill them, only pauses them.", "bis": "Ang frozen nga pagkaon mas dugay kaysa sa naa sa ref kay tungod sa hilabihang katugnaw, halos mohunong ang paglihok ug pagdaghan sa bakterya — wala sila mamatay, gipahunong lang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-meat-browns-cooking-g7", "domain": "MATTER", "topic": "why grilled and fried food browns and smells good", "grades": [7, 8, 9], "terms": ["maillard", "browning", "cooking", "karne", "prito", "ihaw", "brown", "amoy", "lasa", "protina", "asukal", "init", "nagiging kayumanggi", "brown", "gisugba", "giprito", "init", "protina", "kalamay", "bag-ong sustansya", "lami"], "fact": {"tl": "Nagiging kayumanggi at mabango ang iniihaw o piniritong karne dahil nagre-react ang protina at asukal sa init at bumubuo ng bagong sustansyang nagbibigay ng kulay, amoy, at lasa.", "en": "Grilled or fried meat turns brown and smells good because heat makes its protein and sugar react, forming new substances that give the color, aroma, and flavor.", "bis": "Ang gisugba o giprito nga karne mahimong brown ug humot kay ang init maoy hinungdan nga moreact ang protina ug kalamay niini, nga mohimo og bag-ong sustansya nga maghatag og kolor, kahumot, ug lami."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-canned-food-lasts-g6", "domain": "MATTER", "topic": "why canned food lasts for years", "grades": [6, 7, 8], "terms": ["canned", "de lata", "lata", "sealed", "sterile", "heat", "init", "bacteria", "selyado", "walang hangin", "mikrobyo", "de lata", "gilata", "gisarado", "init", "walay hangin", "mikrobyo", "gipatay", "preserba", "dugay"], "fact": {"tl": "Tumatagal ng maraming taon ang de-latang pagkain dahil iniinit ito nang husto para mapatay ang mikrobyo, tapos selyado ang lata para walang bago pang bakterya o hanging makakapasok.", "en": "Canned food lasts for years because it is heated strongly to kill the germs, then the can is sealed so no new bacteria or air can get in.", "bis": "Ang de lata nga pagkaon molungtad og daghang tuig kay kini gipainit pag-ayo aron patyon ang mikrobyo, dayon gisarado ang lata aron walay bag-ong bakterya o hangin nga makasulod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "refrigerate-after-opening-air-g5", "domain": "MATTER", "topic": "why opened food spoils faster", "grades": [5, 6, 7], "terms": ["opened", "air", "exposed", "hangin", "bukas", "mabilis mabulok", "bacteria", "contaminate", "nabukas", "hangin", "gibuksan", "exposed", "mas paspas madunot", "bakterya", "mikrobyo", "preserba", "ref"], "fact": {"tl": "Mas mabilis mabulok ang pagkaing nabuksan na kaysa sa nakasara pa, dahil pagkabukas, nakakapasok na ang hangin at mga bakterya na nagpapasimula ng pagkabulok.", "en": "Opened food spoils faster than sealed food because once it is opened, air and bacteria can get in and start the spoiling.", "bis": "Ang pagkaon nga naabli na mas paspas madunot kaysa sa sirado pa, kay sa diha nga maabli na, makasulod na ang hangin ug bakterya nga magsugod sa pagkadunot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-salt-and-sugar-preserve-g6", "domain": "MATTER", "topic": "why salty and sugary foods keep well", "grades": [6, 7, 8], "terms": ["salt", "sugar", "preserve", "jam", "asin", "asukal", "minatamis", "kondensada", "water", "bacteria", "tubig", "asin", "kalamay", "minatam-is", "preserba", "tubig", "gisuyop", "bakterya", "dili mabuhi"], "fact": {"tl": "Tumatagal ang minatamis na prutas (jam) at inasing pagkain dahil ang sobrang asin o asukal ay humihigop ng tubig palabas ng bakterya, kaya hindi sila makadami.", "en": "Jams and salted foods keep for a long time because very high salt or sugar draws water out of bacteria, so they cannot multiply.", "bis": "Ang minatam-is nga prutas (jam) ug inasin nga pagkaon molungtad og dugay kay ang sobra nga asin o kalamay mosuyop sa tubig gawas sa bakterya, mao nga dili sila makadaghan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-bread-goes-stale-g5", "domain": "MATTER", "topic": "why bread goes stale and hard", "grades": [5, 6, 7], "terms": ["stale", "bread", "tinapay", "hard", "tigas", "starch", "almirol", "dry", "tuyo", "tumigas", "luma", "stale", "tinapay", "gahi", "mogahi", "almirol", "nawad-an", "tubig", "dili na lami"], "fact": {"tl": "Tumitigas ang lumang tinapay hindi lang dahil natutuyo ito kundi dahil ang almirol sa loob ay nagbabago ng ayos at nawawalan ng lambot kahit nasa loob ng supot.", "en": "Bread goes hard and stale not only because it dries out but because the starch inside changes shape and loses its softness, even inside a bag.", "bis": "Ang luma nga tinapay mogahi dili lang tungod kay namala kini kondili tungod kay ang almirol sa sulod mausab og porma ug mawad-an sa kahumok, bisan sa sulod sa supot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-cheese-from-milk-g6", "domain": "MATTER", "topic": "how milk becomes cheese", "grades": [6, 7, 8], "terms": ["cheese", "keso", "milk", "gatas", "curdle", "namumuo", "solid", "bacteria", "enzyme", "namuo", "buo", "tubig", "keso", "gatas", "namuo", "gahi", "bakterya", "enzyme", "gibulag", "gipalapot"], "fact": {"tl": "Nagiging keso ang gatas kapag pinapamuo ito ng acid o espesyal na enzyme, na naghihiwalay sa solidong bahagi ng gatas mula sa likido — at ito ang inihuhubog na keso.", "en": "Milk becomes cheese when an acid or a special enzyme makes it curdle, separating the solid part of the milk from the liquid — and that solid is shaped into cheese.", "bis": "Ang gatas mahimong keso kung kini palapoton sa acid o espesyal nga enzyme, nga magbulag sa gahi nga bahin sa gatas gikan sa likido — ug kana nga gahi maoy himoon nga keso."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-milk-spoils-sour-g5", "domain": "MATTER", "topic": "why milk turns sour when spoiled", "grades": [5, 6, 7], "terms": ["milk", "spoil", "sour", "gatas", "panis", "maasim", "bacteria", "acid", "kumakapal", "mikrobyo", "gatas", "nadunot", "naaslom", "baho", "bakterya", "acid", "milapot", "panis"], "fact": {"tl": "Naaasim at kumakapal ang panis na gatas dahil dumarami ang bakterya rito na kumakain ng asukal sa gatas at gumagawa ng acid kapag iniwan ito sa labas ng ref.", "en": "Spoiled milk turns sour and lumpy because bacteria grow in it, eating the milk's sugar and making acid when it is left out of the fridge.", "bis": "Ang dunot nga gatas moaslom ug molapot kay ang bakterya modaghan niini, mokaon sa kalamay sa gatas ug mobuhat og acid kung ibilin kini gawas sa ref."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-avocado-browns-fast-g5", "domain": "MATTER", "topic": "why cut avocado browns quickly", "grades": [5, 6, 7], "terms": ["avocado", "abokado", "brown", "oxygen", "oxidation", "hangin", "kayumanggi", "enzyme", "lemon", "calamansi", "nangingitim", "abokado", "brown", "hangin", "oxygen", "enzyme", "kalamansi"], "fact": {"tl": "Mabilis mangitim ang hiwa ng abokado dahil ang enzyme nito ay nagre-react agad sa oxygen sa hangin; nababagalan ito ng katas ng kalamansi o pagtakip sa hangin.", "en": "A cut avocado browns quickly because its enzyme reacts fast with oxygen in the air; calamansi juice or covering it from air slows this down.", "bis": "Ang gihiwa nga abokado paspas mongitngit kay ang enzyme niini paspas moreact sa oxygen sa hangin; mapahinay kini sa duga sa kalamansi o pagtabon gikan sa hangin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-rice-spoils-left-out-g4", "domain": "MATTER", "topic": "why cooked rice spoils if left out", "grades": [4, 5, 6], "terms": ["rice", "kanin", "spoil", "panis", "left out", "mainit", "warm", "bacteria", "mikrobyo", "mabilis mapanis", "ref", "kan-on", "nadunot", "gibilin", "init", "bakterya", "mikrobyo", "panis"], "fact": {"tl": "Mabilis mapanis ang kaning iniwan sa labas dahil ang mainit at basang kanin ay paboritong tubuan ng bakterya, kaya mas matagal ito kapag inilagay sa ref.", "en": "Cooked rice left out spoils fast because warm, moist rice is a favorite place for bacteria to grow, so it lasts longer when kept in the fridge.", "bis": "Ang kan-on nga gibilin sa gawas paspas mapanis kay ang init ug basa nga kan-on paborito nga tuboan sa bakterya, mao nga mas dugay kini kung ibutang sa ref."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-soy-sauce-fermented-g7", "domain": "MATTER", "topic": "how soy sauce is made by fermenting", "grades": [7, 8, 9], "terms": ["soy sauce", "toyo", "fermented", "soybeans", "utaw", "mold", "bacteria", "binuro", "mikrobyo", "lasa", "kulay", "toyo", "soya", "binuro", "agup-op", "bakterya", "fermented", "umami", "linamnam"], "fact": {"tl": "Ginagawa ang toyo sa pamamagitan ng matagal na pag-ferment ng soybeans gamit ang amag at bakterya, na nagbibigay ng maitim na kulay at malinamnam na lasa nito.", "en": "Soy sauce is made by fermenting soybeans for a long time with mold and bacteria, which give it its dark color and savory flavor.", "bis": "Ang toyo gibuhat pinaagi sa dugay nga pag-ferment sa soybeans gamit ang agup-op ug bakterya, nga maghatag sa itom niini nga kolor ug linamnam nga lami."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-chili-feels-hot-g5", "domain": "MATTER", "topic": "why chili feels hot in your mouth", "grades": [5, 6, 7], "terms": ["chili", "sili", "spicy", "anghang", "maanghang", "capsaicin", "heat", "init", "nerve", "panlasa", "dila", "nanunog", "sili", "halang", "kahalang", "capsaicin", "init", "nerbiyos", "dili tinuod nga init", "panimpla"], "fact": {"tl": "Maanghang ang sili dahil may sangkap itong capsaicin na nanunog at niloloko ang mga nerbiyos sa bibig na akala ay nasusunog, kahit walang tunay na init.", "en": "Chili feels hot because it has capsaicin, a substance that tricks the nerves in your mouth into feeling burned, even though there is no real heat.", "bis": "Halang ang sili kay kini adunay capsaicin, usa ka sustansya nga molimbong sa mga nerbiyos sa baba aron mobati nga nasunog, bisan walay tinuod nga init."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-cooking-kills-germs-g5", "domain": "MATTER", "topic": "why cooking food makes it safe", "grades": [5, 6, 7], "terms": ["cooking", "luto", "heat", "init", "kills germs", "bacteria", "ligtas", "safe", "mikrobyo", "namamatay", "pakuluan", "prito", "luto", "init", "gipatay", "bakterya", "mikrobyo", "luwas", "mapatay"], "fact": {"tl": "Mas ligtas kainin ang lutong pagkain kaysa hilaw dahil ang init ng pagluluto ay pumapatay sa karamihan ng bakterya at mikrobyong nagdudulot ng sakit.", "en": "Cooked food is safer to eat than raw food because the heat of cooking kills most of the bacteria and germs that cause sickness.", "bis": "Mas luwas kan-on ang luto nga pagkaon kaysa hilaw kay ang init sa pagluto mopatay sa kadaghanan sa bakterya ug mikrobyo nga maoy hinungdan sa sakit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-tea-coffee-bitter-g6", "domain": "MATTER", "topic": "why coffee and bitter foods taste bitter", "grades": [6, 7, 8], "terms": ["bitter", "mapait", "coffee", "kape", "ampalaya", "taste", "panlasa", "warning", "lason", "protect", "dila", "mapait", "pait", "kape", "paliya", "panlasa", "pahimangno", "hilo", "receptor", "dila"], "fact": {"tl": "Mapait ang kape at ampalaya dahil may mga sangkap sila na nararamdaman ng dila bilang pait — at ang panlasa sa pait ay paraan ng katawan para mag-ingat sa mga posibleng nakakalasong halaman.", "en": "Coffee and bitter melon taste bitter because they contain substances the tongue senses as bitter — and tasting bitterness is the body's way of warning us about possibly poisonous plants.", "bis": "Pait ang kape ug paliya kay sila adunay mga sustansya nga mabati sa dila isip pait — ug ang pagtilaw og pait maoy paagi sa lawas aron mag-amping sa mga tanom nga posibleng makahilo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-vinegar-stops-spoiling-g6", "domain": "MATTER", "topic": "why pickling in vinegar preserves food", "grades": [6, 7, 8], "terms": ["pickle", "vinegar", "suka", "atsara", "acid", "preserve", "maasim", "bacteria", "binabad", "binuro", "atsara", "suka", "aslom", "acid", "bakterya", "dili mabuhi", "preserba", "gibabad", "gulay"], "fact": {"tl": "Tumatagal ang atsara at mga binabad sa suka dahil masyadong maasim ang suka para mabuhay ang karamihan ng bakterya na nagpapabulok ng pagkain.", "en": "Pickled vegetables and foods soaked in vinegar last long because vinegar is too acidic for most spoilage bacteria to survive.", "bis": "Ang atsara ug mga butang nga gibabad sa suka molungtad og dugay kay ang suka aslom kaayo aron mabuhi ang kadaghanan sa bakterya nga maoy hinungdan sa pagkadunot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "voyager-golden-record-g6", "domain": "EARTH_SPACE", "topic": "Voyager Golden Record message to aliens", "grades": [5, 6, 7], "terms": ["Voyager", "golden record", "gintong plaka", "rekord", "mensahe", "mensahe sa kalawakan", "alien", "dayuhan", "tinig", "tunog", "musika", "boses", "saludo", "pagbati", "pagtimbaya", "bulawanong plaka", "sounds", "music", "greetings", "languages", "wika", "pinukpok"], "fact": {"tl": "May dala-dalang gintong plaka (Golden Record) ang bawat Voyager probe na puno ng tunog ng Earth—musika, awit ng ibon, at pagbati sa 55 wika—sakaling may matalinong nilalang sa kalawakan na makakita nito.", "en": "Each Voyager probe carries a Golden Record packed with sounds of Earth—music, birdsong, and greetings in 55 languages—in case any intelligent beings in space ever find it.", "bis": "Ang matag Voyager probe nagdala ug bulawanong plaka (Golden Record) nga puno sa mga tingog sa Earth—musika, huni sa langgam, ug mga pangomusta sa 55 ka pinulongan—kon adunay maalamon nga binuhat sa kawanangan nga makakita niini."}, "source": "encyclopedia-stable consensus (NASA Voyager Golden Record)", "generator": "claude-workflow", "reviewed": false},
  {"id": "voyager-still-talking-g7", "domain": "EARTH_SPACE", "topic": "Voyager signals take many hours to reach Earth", "grades": [6, 7, 8], "terms": ["Voyager", "signal", "senyas", "hudyat", "radyo", "radio", "interstellar space", "kalawakan", "kawanangan", "labas ng solar system", "gawas sa solar system", "oras", "hours", "layo", "kalayo", "kalayuon", "bilis ng liwanag", "speed of light", "katulin sa kahayag", "umaabot", "moabot", "nakakaabot"], "fact": {"tl": "Napakalayo na ng Voyager 1 kaya ang radyo nitong senyas, kahit kasimbilis ng liwanag, ay umaabot ng mahigit 20 oras bago marating ang Earth.", "en": "Voyager 1 is now so far away that its radio signal, even at the speed of light, takes more than 20 hours to reach Earth.", "bis": "Layo na kaayo ang Voyager 1 mao nga ang radyo niini nga senyas, bisan sama kapaspas sa katulin sa kahayag, mokabat ug kapin 20 ka oras una makaabot sa Earth."}, "source": "encyclopedia-stable consensus (NASA Voyager mission status)", "generator": "claude-workflow", "reviewed": false},
  {"id": "voyager-left-solar-system-g7", "domain": "EARTH_SPACE", "topic": "Voyager entered interstellar space", "grades": [6, 7, 8], "terms": ["Voyager", "interstellar space", "pagitan ng mga bituin", "tunga sa mga bituon", "labas ng solar system", "gawas sa solar system", "unang", "una", "nilikha ng tao", "gibuhat sa tao", "human-made", "1977", "umalis", "mibiya", "nakaabot", "heliosphere", "hangganan", "utlanan"], "fact": {"tl": "Ang Voyager 1 ang unang bagay na gawa ng tao na umalis sa ating solar system at nakapasok sa interstellar space—ang espasyo sa pagitan ng mga bituin.", "en": "Voyager 1 is the first human-made object to leave our solar system and enter interstellar space—the space between the stars.", "bis": "Ang Voyager 1 mao ang unang butang nga binuhat sa tao nga mibiya sa atong solar system ug misulod sa interstellar space—ang luna tunga sa mga bituon."}, "source": "encyclopedia-stable consensus (NASA, Voyager 1 crossed heliopause 2012)", "generator": "claude-workflow", "reviewed": false},
  {"id": "jwst-infrared-eye-g6", "domain": "EARTH_SPACE", "topic": "James Webb Telescope sees in infrared", "grades": [6, 7, 8], "terms": ["James Webb", "Webb", "telescope", "teleskopyo", "teleskopyo sa kawanangan", "infrared", "infrared light", "init", "kainit", "liwanag na init", "kahayag nga init", "nakikita", "makita", "malayo", "layo nga bituon", "distant", "galaxy", "galaksi", "mata", "mata sa kawanangan", "pinakamalaki"], "fact": {"tl": "Ang James Webb Space Telescope ay nakakakita ng infrared light—isang uri ng liwanag na init na hindi nakikita ng ating mata—kaya nakikita nito ang napakalayong mga bituin at galaksi na nakatago sa ordinaryong teleskopyo.", "en": "The James Webb Space Telescope sees infrared light—a kind of heat light our eyes cannot see—so it can spot very distant stars and galaxies that are hidden from ordinary telescopes.", "bis": "Ang James Webb Space Telescope makakita ug infrared light—usa ka matang sa kahayag nga init nga dili makita sa atong mata—mao nga makita niini ang layo kaayo nga mga bituon ug galaksi nga tago sa ordinaryong teleskopyo."}, "source": "encyclopedia-stable consensus (NASA JWST)", "generator": "claude-workflow", "reviewed": false},
  {"id": "jwst-far-from-earth-g7", "domain": "EARTH_SPACE", "topic": "James Webb Telescope is 1.5 million km from Earth", "grades": [6, 7, 8], "terms": ["James Webb", "Webb telescope", "teleskopyo", "1.5 million", "1.5 milyon", "kilometro", "kilometers", "layo sa Earth", "kalay-o", "milyon kilometro", "Hubble", "umiikot sa Araw", "molibot sa Adlaw", "orbit", "mas malayo kaysa Buwan", "mas layo sa Bulan", "hindi maaayos", "dili maayo"], "fact": {"tl": "Hindi tulad ng Hubble na malapit sa Earth, ang James Webb ay nasa layong mga 1.5 milyong kilometro—mas malayo pa kaysa sa Buwan—kaya napakahirap nitong ayusin kung masira.", "en": "Unlike Hubble, which is close to Earth, James Webb sits about 1.5 million kilometers away—farther than the Moon—which makes it very hard to repair if it breaks.", "bis": "Dili sama sa Hubble nga duol sa Earth, ang James Webb naa sa gilay-on nga mga 1.5 ka milyon ka kilometro—mas layo pa kay sa Bulan—mao nga lisod kaayo kini ayohon kon maguba."}, "source": "encyclopedia-stable consensus (NASA JWST orbits Sun-Earth L2, ~1.5 million km)", "generator": "claude-workflow", "reviewed": false},
  {"id": "hubble-fixed-by-astronauts-g6", "domain": "EARTH_SPACE", "topic": "Astronauts repaired the Hubble telescope in space", "grades": [5, 6, 7], "terms": ["Hubble", "telescope", "teleskopyo", "astronaut", "astronot", "inayos", "inayos sa kalawakan", "giayo", "repair", "pag-ayos", "mata", "salamin", "mirror", "salamin nga baliko", "blurry", "malabo", "hindi malinaw", "dili klaro", "spacewalk", "lakad sa kawanangan", "nakalabas", "nilimbasugan"], "fact": {"tl": "Noong unang nasa kalawakan na ang Hubble, malabo pala ang mga larawan nito dahil sa maling hugis ng salamin (mirror)—kaya may mga astronaut na lumabas sa space para ayusin ito.", "en": "When Hubble first reached space its pictures came out blurry because of a flaw in its mirror—so astronauts went out into space to fix it.", "bis": "Sa una nga naa na sa kawanangan ang Hubble, hanap diay ang mga hulagway niini tungod sa sayop nga porma sa salamin (mirror)—mao nga adunay mga astronaut nga migawas sa kawanangan aron ayohon kini."}, "source": "encyclopedia-stable consensus (Hubble 1993 servicing mission, COSTAR)", "generator": "claude-workflow", "reviewed": false},
  {"id": "moxie-oxygen-on-mars-g6", "domain": "EARTH_SPACE", "topic": "Perseverance rover made oxygen on Mars", "grades": [6, 7, 8], "terms": ["Perseverance", "rover", "Mars", "oxygen", "hangin", "oxygen sa Mars", "ginawang oxygen", "gibuhat nga oxygen", "MOXIE", "carbon dioxide", "atmosphere", "hangin sa Mars", "unang beses", "unang higayon", "first time", "hininga", "ginhawa", "astronaut", "magbubukas ng paraan", "magabukas ug dalan"], "fact": {"tl": "Ang Perseverance rover ang unang nakagawa ng oxygen sa Mars—kinuha nito ang oxygen mula sa carbon dioxide sa hangin ng Mars, na maaaring makatulong sa mga astronaut na huminga balang araw.", "en": "The Perseverance rover was the first to make oxygen on Mars—it pulled oxygen out of the carbon dioxide in Mars's air, which could one day help astronauts breathe.", "bis": "Ang Perseverance rover mao ang una nga nakahimo ug oxygen sa Mars—gikuha niini ang oxygen gikan sa carbon dioxide sa hangin sa Mars, nga mahimong makatabang sa mga astronaut nga makaginhawa sa umaabot."}, "source": "NASA JPL / Scientific American (MOXIE first oxygen on Mars, April 2021)", "generator": "claude-workflow", "reviewed": false},
  {"id": "ingenuity-helicopter-mars-g6", "domain": "EARTH_SPACE", "topic": "Ingenuity helicopter flew on Mars", "grades": [5, 6, 7], "terms": ["Ingenuity", "helicopter", "helikopter", "Mars", "lumipad", "milupad", "naglupad", "fly", "unang lumipad", "unang naglupad", "first flight", "ibang planeta", "laing planeta", "another planet", "manipis na hangin", "nipis nga hangin", "thin air", "drone", "eroplano", "ayroplano"], "fact": {"tl": "Ang Ingenuity ay isang maliit na helikopter na siyang unang sasakyang lumipad sa ibang planeta—nakalipad ito sa napakanipis na hangin ng Mars.", "en": "Ingenuity is a tiny helicopter that became the first aircraft to fly on another planet—it lifted off in the very thin air of Mars.", "bis": "Ang Ingenuity usa ka gamay nga helikopter nga nahimong unang sakyanan nga milupad sa laing planeta—mibangon kini sa nipis kaayo nga hangin sa Mars."}, "source": "encyclopedia-stable consensus (NASA Ingenuity, first powered flight on Mars, April 2021)", "generator": "claude-workflow", "reviewed": false},
  {"id": "mars-rover-slow-careful-g5", "domain": "EARTH_SPACE", "topic": "Mars rovers move very slowly", "grades": [4, 5, 6], "terms": ["Mars rover", "rover", "robot", "Mars", "mabagal", "mahinay", "hinay", "slow", "marahan", "ingat", "amping", "careful", "bato", "bato sa Mars", "rocks", "hindi maipadala agad", "dili dali", "command", "utos", "sugo", "naglalakbay", "nagbiyahe", "nagpanaw"], "fact": {"tl": "Ang mga Mars rover ay gumagalaw nang napakabagal—mas mabagal pa sa paglakad ng tao—para hindi sila madapa sa mga bato sa isang mundong napakalayo para tulungan agad.", "en": "Mars rovers move very slowly—slower than a person walking—so they don't trip over rocks on a world far too distant for quick help.", "bis": "Ang mga Mars rover mohinay-hinay kaayo paglihok—mas hinay pa sa paglakaw sa tawo—aron dili sila mapandol sa mga bato sa usa ka kalibutan nga layo kaayo aron dali-dali matabangan."}, "source": "encyclopedia-stable consensus (NASA Mars rovers travel at a few cm/s)", "generator": "claude-workflow", "reviewed": false},
  {"id": "mars-rover-radio-delay-g7", "domain": "EARTH_SPACE", "topic": "Commands to Mars rovers take minutes to arrive", "grades": [6, 7, 8], "terms": ["Mars rover", "rover", "utos", "sugo", "command", "signal", "senyas", "minuto", "minutos", "minutes", "antala", "delay", "langan", "layo ng Mars", "kalay-o sa Mars", "hindi madiskarte agad", "dili dali masugo", "kaya mag-isa", "kaugalingon", "drive alone", "antay", "paghulat"], "fact": {"tl": "Dahil napakalayo ng Mars, ang utos mula sa Earth ay umaabot ng ilang minuto bago marating ang rover—kaya hindi ito puwedeng i-drive nang live na parang laro.", "en": "Because Mars is so far, a command from Earth takes several minutes to reach a rover—so it cannot be driven live like a video game.", "bis": "Tungod kay layo kaayo ang Mars, ang sugo gikan sa Earth mokabat ug pipila ka minuto una makaabot sa rover—mao nga dili kini madrayb nga live sama sa dula."}, "source": "encyclopedia-stable consensus (Earth-Mars radio delay several minutes)", "generator": "claude-workflow", "reviewed": false},
  {"id": "apollo-rocks-brought-back-g5", "domain": "EARTH_SPACE", "topic": "Apollo astronauts brought Moon rocks to Earth", "grades": [4, 5, 6], "terms": ["Apollo", "astronaut", "astronot", "Moon rocks", "bato sa Buwan", "bato sa Bulan", "Moon", "Buwan", "Bulan", "iniuwi", "gidala", "dinala", "brought back", "pinag-aralan", "gitun-an", "study", "sample", "halimbawa", "ehemplo", "kilo", "timbang", "gibug-aton"], "fact": {"tl": "Ang mga astronaut ng Apollo ay nag-uwi ng daan-daang kilo ng bato at lupa mula sa Buwan para pag-aralan ng mga siyentipiko hanggang ngayon.", "en": "The Apollo astronauts brought home hundreds of kilograms of rock and soil from the Moon for scientists to study even today.", "bis": "Ang mga astronaut sa Apollo nagdala ug ginatos ka kilo nga bato ug yuta gikan sa Bulan aron tun-an sa mga siyentista hangtod karon."}, "source": "encyclopedia-stable consensus (Apollo returned ~382 kg of lunar samples)", "generator": "claude-workflow", "reviewed": false},
  {"id": "apollo-flag-stiff-no-wind-g5", "domain": "EARTH_SPACE", "topic": "The flag on the Moon has no wind to wave it", "grades": [4, 5, 6], "terms": ["Apollo", "bandila", "watawat", "bandera", "flag", "Moon", "Buwan", "Bulan", "hangin", "wala hangin", "walay hangin", "no wind", "wagayway", "wala kumakaway", "wala mawagayway", "nakatuwid", "nakatarong", "alambre", "wire", "tarong", "naghikaw"], "fact": {"tl": "Ang bandila na itinanim sa Buwan ay mukhang nakawagayway, pero dahil walang hangin sa Buwan, may alambre itong nakaipit sa itaas para hindi malukot.", "en": "The flag planted on the Moon looks like it's waving, but since there is no wind on the Moon a wire was sewn along the top to hold it out straight.", "bis": "Ang bandila nga gitanom sa Bulan murag nagwarawara, apan tungod walay hangin sa Bulan, adunay alambre nga gitahi sa ibabaw aron molugway kini nga tarong."}, "source": "encyclopedia-stable consensus (Apollo lunar flag assembly had a horizontal rod)", "generator": "claude-workflow", "reviewed": false},
  {"id": "apollo-three-day-journey-g6", "domain": "EARTH_SPACE", "topic": "Apollo took about three days to reach the Moon", "grades": [5, 6, 7], "terms": ["Apollo", "Moon", "Buwan", "Bulan", "tatlong araw", "tulo ka adlaw", "three days", "biyahe", "panaw", "paglalakbay", "journey", "rocket", "raketa", "umabot sa Buwan", "moabot sa Bulan", "layo", "kalayo", "kalayuon", "spacecraft", "sasakyang pangkalawakan", "sakyanan sa kawanangan"], "fact": {"tl": "Kahit pinakamabilis na sasakyan ng tao, umabot pa rin ng mga tatlong araw bago marating ng mga Apollo astronaut ang Buwan mula sa Earth.", "en": "Even in humanity's fastest spacecraft, it still took the Apollo astronauts about three days to reach the Moon from Earth.", "bis": "Bisan sa pinakapaspas nga sakyanan sa tawo, mikabat gihapon ug mga tulo ka adlaw una maabot sa mga Apollo astronaut ang Bulan gikan sa Earth."}, "source": "encyclopedia-stable consensus (Apollo translunar coast ~3 days)", "generator": "claude-workflow", "reviewed": false},
  {"id": "iss-water-recycled-g6", "domain": "EARTH_SPACE", "topic": "Astronauts recycle their water on the ISS", "grades": [5, 6, 7], "terms": ["ISS", "space station", "estasyon sa kalawakan", "astronaut", "astronot", "tubig", "tubig sa kawanangan", "water", "recycle", "ginagamit ulit", "gigamit usab", "pawis", "singot", "sweat", "ihi", "ihi nila", "urine", "nililinis", "gilimpyohan", "ginagawang inumin", "gihimong mainom", "kakulangan", "kanihit"], "fact": {"tl": "Sa ISS, ang pawis at maging ang ihi ng mga astronaut ay nililinis at ginagawang malinis na inuming tubig, dahil napakahirap magpadala ng tubig mula sa Earth.", "en": "On the ISS, astronauts' sweat and even their urine are cleaned and turned back into clean drinking water, because it is very hard to send water up from Earth.", "bis": "Sa ISS, ang singot ug bisan ang ihi sa mga astronaut gilimpyohan ug gibalik nga limpyo nga mainom nga tubig, tungod kay lisod kaayo magpadala ug tubig gikan sa Earth."}, "source": "encyclopedia-stable consensus (ISS Water Recovery System recycles ~90% of water)", "generator": "claude-workflow", "reviewed": false},
  {"id": "iss-no-up-down-g5", "domain": "EARTH_SPACE", "topic": "There is no up or down on the space station", "grades": [4, 5, 6], "terms": ["ISS", "space station", "estasyon sa kalawakan", "astronaut", "astronot", "taas baba", "itaas ibaba", "up down", "wala", "walay", "weightless", "walang timbang", "walay gibug-aton", "lumulutang", "naglutaw", "float", "natutulog dingding", "matulog sa bungbong", "sleep wall", "nakakabit", "nahigot"], "fact": {"tl": "Sa loob ng space station ay walang totoong itaas o ibaba dahil lumulutang ang lahat, kaya puwede pang magtrabaho ang astronaut na parang nakatiwarik.", "en": "Inside the space station there is no real up or down because everything floats, so an astronaut can even work upside down.", "bis": "Sulod sa space station walay tinuod nga taas o ubos tungod kay naglutaw ang tanan, mao nga makahimo pa ang astronaut ug trabaho nga murag balintong."}, "source": "encyclopedia-stable consensus (microgravity on ISS)", "generator": "claude-workflow", "reviewed": false},
  {"id": "astronaut-bones-weaken-g7", "domain": "EARTH_SPACE", "topic": "Astronauts' bones and muscles weaken in space", "grades": [6, 7, 8], "terms": ["astronaut", "astronot", "buto", "bukog", "bones", "kalamnan", "kaunuran", "muscles", "humihina", "nagluya", "luya", "weaken", "weightless", "walang timbang", "walay gibug-aton", "ehersisyo", "exercise", "araw-araw", "kada adlaw", "kailangan mag-ehersisyo", "magbuhat ug ehersisyo", "espasyo", "kawanangan"], "fact": {"tl": "Dahil walang timbang na binubuhat sa kalawakan, humihina ang buto at kalamnan ng astronaut, kaya kailangan nilang mag-ehersisyo nang ilang oras araw-araw.", "en": "Because there is no weight to carry in space, an astronaut's bones and muscles grow weaker, so they must exercise for hours every day.", "bis": "Tungod kay walay gibug-aton nga gipas-an sa kawanangan, mahuyang ang bukog ug kaunuran sa astronaut, mao nga kinahanglan sila mag-ehersisyo ug pipila ka oras kada adlaw."}, "source": "encyclopedia-stable consensus (microgravity bone density and muscle loss)", "generator": "claude-workflow", "reviewed": false},
  {"id": "astronaut-taller-in-space-g7", "domain": "EARTH_SPACE", "topic": "Astronauts grow slightly taller in space", "grades": [6, 7, 8], "terms": ["astronaut", "astronot", "tumataas", "mitaas", "naglabaw", "taller", "mas mataas", "mas taas", "gulugod", "spine", "backbone", "naunat", "nabanat", "stretch", "weightless", "walang timbang", "walay gibug-aton", "ilang sentimetro", "pipila ka sentimetro", "bumababa pagbalik", "mobalik inig-uli", "espasyo"], "fact": {"tl": "Sa kalawakan, bahagyang tumataas ang astronaut nang ilang sentimetro dahil naunat ang kanilang gulugod kapag walang timbang—pero bumababa ulit ang taas nila pagbalik sa Earth.", "en": "In space, astronauts grow a few centimeters taller because their spine stretches without weight pressing on it—but they shrink back once they return to Earth.", "bis": "Sa kawanangan, gamay nga motaas ang astronaut ug pipila ka sentimetro tungod kay nabanat ang ilang gulugod nga walay gibug-aton nga nagduot—apan momubo usab sila inig-uli sa Earth."}, "source": "encyclopedia-stable consensus (spinal lengthening in microgravity)", "generator": "claude-workflow", "reviewed": false},
  {"id": "astronaut-velcro-tools-g5", "domain": "EARTH_SPACE", "topic": "Astronauts stick things down so they don't float away", "grades": [4, 5, 6], "terms": ["astronaut", "astronot", "gamit", "gamit nila", "tools", "kagamitan", "kasangkapan", "lumulutang", "naglutaw", "float away", "Velcro", "tape", "nakadikit", "napilit", "stick down", "nawawala", "mawala", "nahuhulog", "nahulog", "ipit", "higot", "nakakabit", "ginadikit", "gipapilit"], "fact": {"tl": "Sa walang timbang na kalawakan, dinidikit ng astronaut ang kanilang mga gamit gamit ang Velcro o tape para hindi lumutang at maglaho ang mga ito.", "en": "In weightless space, astronauts stick their tools down with Velcro or tape so they don't float off and get lost.", "bis": "Sa walay gibug-aton nga kawanangan, gipapilit sa astronaut ang ilang mga gamit gamit ang Velcro o tape aron dili kini molutaw ug mawala."}, "source": "encyclopedia-stable consensus (object management in microgravity)", "generator": "claude-workflow", "reviewed": false},
  {"id": "space-food-no-crumbs-g5", "domain": "EARTH_SPACE", "topic": "Astronauts avoid crumbly food in space", "grades": [4, 5, 6], "terms": ["astronaut", "astronot", "pagkain", "pagkaon", "food", "mumo", "momo", "durog", "crumbs", "tinapay", "pan", "tortilla", "lumulutang", "naglutaw", "float", "nakakapasok makina", "makasulod sa makina", "tumortilya", "ginagamit tortilla", "gigamit tortilla", "delikado", "peligro", "matusok ilong", "makasulod ilong"], "fact": {"tl": "Iniiwasan ng astronaut ang tinapay sa kalawakan dahil ang lumulutang na mumo ay maaaring makapasok sa kanilang mata o sa makina—kaya madalas silang gumagamit ng tortilla na hindi gaanong nagdudurog.", "en": "Astronauts avoid bread in space because floating crumbs can get into their eyes or the machines—so they often use tortillas, which barely crumble.", "bis": "Likayan sa astronaut ang pan sa kawanangan tungod kay ang naglutaw nga momo mahimong makasulod sa ilang mata o sa makina—mao nga sagad mogamit silag tortilla, nga dili kaayo modurog."}, "source": "encyclopedia-stable consensus (NASA space food practices)", "generator": "claude-workflow", "reviewed": false},
  {"id": "satellite-gps-helps-find-way-g6", "domain": "EARTH_SPACE", "topic": "GPS satellites help us find our way", "grades": [5, 6, 7], "terms": ["satellite", "satelayt", "GPS", "mapa", "mapa sa telepono", "map", "lokasyon", "kinaroroonan", "nahimutangan", "nasaan", "asa", "where", "direksyon", "dalan", "ruta", "navigation", "telepono", "phone", "umiikot sa Earth", "molibot sa Earth", "tumutulong", "motabang", "nakakatulong"], "fact": {"tl": "Ang mapa sa telepono na nagsasabi kung nasaan ka ay gumagana dahil sa mga GPS satellite na umiikot sa Earth at nagpapadala ng senyas pababa.", "en": "The map on your phone that shows where you are works thanks to GPS satellites circling Earth and sending signals down.", "bis": "Ang mapa sa telepono nga nagpakita kon asa ka molihok tungod sa mga GPS satellite nga naglibot sa Earth ug nagpadala ug senyas paubos."}, "source": "encyclopedia-stable consensus (GPS satellite navigation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "weather-satellite-watches-typhoon-g6", "domain": "EARTH_SPACE", "topic": "Weather satellites watch typhoons from space", "grades": [5, 6, 7], "terms": ["satellite", "satelayt", "weather satellite", "satelayt sa panahon", "bagyo", "unos", "typhoon", "PAGASA", "panahon", "tiempo", "weather", "ulan", "uwan", "ulap", "panganod", "clouds", "nakikita mula taas", "makita gikan sa taas", "babala", "pasidaan", "warning", "nagbabantay", "nagbantay", "Filipinas", "Pilipinas"], "fact": {"tl": "Pinagmamasdan ng mga weather satellite ang mga bagyo mula sa kalawakan, kaya nakapagbibigay ang PAGASA ng babala sa mga Pilipino bago pa dumating ang unos.", "en": "Weather satellites watch typhoons from space, so PAGASA can warn Filipinos before a storm arrives.", "bis": "Ang mga weather satellite nagbantay sa mga bagyo gikan sa kawanangan, mao nga makahatag ang PAGASA ug pasidaan sa mga Pilipino una pa moabot ang unos."}, "source": "encyclopedia-stable consensus (geostationary weather satellites; PAGASA)", "generator": "claude-workflow", "reviewed": false},
  {"id": "space-junk-orbits-earth-g7", "domain": "EARTH_SPACE", "topic": "Space junk orbits Earth at high speed", "grades": [6, 7, 8], "terms": ["space junk", "basura sa kalawakan", "basura sa kawanangan", "space debris", "kalat", "sagbot", "lumang satellite", "daang satellite", "old satellite", "piraso", "tipik", "tibuok", "umiikot", "molibot", "orbit", "bilis", "katulin", "mabilis", "paspas", "delikado", "peligro", "banggaan", "bangga", "nagkalat", "nagkatag"], "fact": {"tl": "Libu-libong piraso ng lumang satellite at iba pang basura ang umiikot sa Earth nang napakabilis, kaya delikado ang mga ito sa mga sasakyang pangkalawakan.", "en": "Thousands of pieces of old satellites and other junk circle Earth at very high speed, making them dangerous to spacecraft.", "bis": "Liboan ka piraso sa daang satellite ug ubang basura ang naglibot sa Earth nga paspas kaayo, mao nga peligroso kini sa mga sakyanan sa kawanangan."}, "source": "encyclopedia-stable consensus (orbital debris)", "generator": "claude-workflow", "reviewed": false},
  {"id": "rockets-stage-fall-off-g6", "domain": "EARTH_SPACE", "topic": "Rockets drop empty parts as they climb", "grades": [5, 6, 7], "terms": ["rocket", "raketa", "missile", "stages", "bahagi", "parte", "tinanggal", "gitangtang", "drop off", "nahuhulog", "nahulog", "gasolina", "sugnod", "fuel", "ubos", "naubos", "naghaw-as", "gaan", "gaang", "mas magaan", "mas gaan", "tumaas", "motaas", "nakaakyat", "nakasaka", "pangkalawakan"], "fact": {"tl": "Habang umaakyat ang raketa, tinatanggal nito ang mga bahaging naubusan na ng gasolina para gumaan at makarating nang mas mataas sa kalawakan.", "en": "As a rocket climbs, it drops off the parts that have run out of fuel so it becomes lighter and can reach higher into space.", "bis": "Samtang mosaka ang raketa, gitangtang niini ang mga bahin nga nahurot na ug sugnod aron mogaan ug makaabot ug mas taas sa kawanangan."}, "source": "encyclopedia-stable consensus (multistage rockets)", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-rockets-need-no-air-g7", "domain": "EARTH_SPACE", "topic": "Rockets carry their own oxygen to burn fuel", "grades": [6, 7, 8], "terms": ["rocket", "raketa", "oxygen", "hangin", "sariling oxygen", "kaugalingong oxygen", "sunog", "gasolina", "sugnod", "fuel", "burn", "walang hangin sa kalawakan", "walay hangin sa kawanangan", "no air space", "dala", "gidala", "kargada", "tangke", "tangki", "tank", "kaya tumakbo", "makagana", "gumagana"], "fact": {"tl": "Walang hangin sa kalawakan, kaya may dala-dalang sariling oxygen ang raketa para masunog nito ang gasolina kahit sa labas ng atmospera.", "en": "There is no air in space, so a rocket carries its own oxygen to burn its fuel even beyond the atmosphere.", "bis": "Walay hangin sa kawanangan, mao nga ang raketa nagdala ug kaugalingong oxygen aron masunog niini ang sugnod bisan gawas sa atmospera."}, "source": "encyclopedia-stable consensus (rockets carry oxidizer)", "generator": "claude-workflow", "reviewed": false},
  {"id": "mars-rover-nuclear-power-g8", "domain": "EARTH_SPACE", "topic": "Some Mars rovers run on nuclear heat, not solar", "grades": [7, 8, 9], "terms": ["Mars rover", "rover", "Perseverance", "Curiosity", "nuclear", "nukleyar", "init", "kainit", "heat", "power", "kuryente", "koryente", "lakas", "baterya", "battery", "solar panel", "araw", "adlaw", "alikabok", "abog", "abo", "dust", "gabi", "gabii", "taglamig", "tingtugnaw", "patuloy gumana", "padayon molihok"], "fact": {"tl": "Ang ilang Mars rover tulad ng Perseverance ay umaandar sa init ng nuclear na materyal, hindi solar panel, para makagana pa rin kahit gabi o kapag maraming alikabok.", "en": "Some Mars rovers like Perseverance run on the heat of nuclear material rather than solar panels, so they can keep working even at night or in dusty weather.", "bis": "Ang ubang Mars rover sama sa Perseverance modagan sa kainit sa nukleyar nga materyal, dili solar panel, aron makapadayon sila paglihok bisan gabii o kon abugon."}, "source": "encyclopedia-stable consensus (RTG power on Curiosity/Perseverance)", "generator": "claude-workflow", "reviewed": false},
  {"id": "telescope-sees-the-past-g8", "domain": "EARTH_SPACE", "topic": "Telescopes show stars as they were long ago", "grades": [7, 8, 9], "terms": ["telescope", "teleskopyo", "Hubble", "Webb", "bituin", "bituon", "stars", "liwanag", "kahayag", "light", "nakaraan", "nangagi", "kaniadto", "past", "matagal", "dugay", "taon", "tuig", "years", "naglakbay", "milangyaw", "nagpanaw", "noon", "kaganina", "long ago", "malayong galaksi", "layo nga galaksi", "nakikita natin", "atong makita"], "fact": {"tl": "Napakalayo ng mga bituin kaya ang liwanag na nakikita natin sa teleskopyo ay umalis sa kanila libu-libo o milyon-milyong taon na ang nakalipas—parang nakatingin tayo sa nakaraan.", "en": "Stars are so far away that the light we see in a telescope left them thousands or millions of years ago—so we are really looking into the past.", "bis": "Layo kaayo ang mga bituon mao nga ang kahayag nga atong makita sa teleskopyo mibiya kanila liboan o milyon-milyon ka tuig na ang milabay—murag naglantaw ta sa nangagi."}, "source": "encyclopedia-stable consensus (light travel time / look-back time)", "generator": "claude-workflow", "reviewed": false},
  {"id": "spacewalk-tether-safety-g6", "domain": "EARTH_SPACE", "topic": "Astronauts use a safety rope during spacewalks", "grades": [5, 6, 7], "terms": ["spacewalk", "lakad sa kalawakan", "lakaw sa kawanangan", "astronaut", "astronot", "tali", "pisi", "hikot", "tether", "rope", "safety", "kaligtasan", "kasigurohan", "nakatali", "gihigot", "nahigot", "lumayo", "mahilayo", "float away", "nawawala", "mawala", "labas", "gawas", "ISS", "space station"], "fact": {"tl": "Tuwing lalabas ang astronaut sa space station para gumawa, may matibay na tali ang nakatali sa kanila para hindi sila lumutang palayo at maligaw sa kalawakan.", "en": "Whenever an astronaut goes outside the space station to work, a strong tether ties them to it so they don't drift away and get lost in space.", "bis": "Matag mogawas ang astronaut sa space station aron motrabaho, adunay lig-on nga hikot nga naghigot kanila aron dili sila molutaw palayo ug mawala sa kawanangan."}, "source": "encyclopedia-stable consensus (EVA safety tethers)", "generator": "claude-workflow", "reviewed": false},
  {"id": "moon-no-sound-g6", "domain": "EARTH_SPACE", "topic": "Sound cannot travel on the Moon or in space", "grades": [5, 6, 7], "terms": ["Moon", "Buwan", "Bulan", "tunog", "tingog", "sound", "hindi naririnig", "dili madungog", "walang hangin", "walay hangin", "no air", "space", "kalawakan", "kawanangan", "astronaut", "astronot", "radyo", "radio", "nag-uusap", "nag-istorya", "nagsultihay", "katahimikan", "kahilom", "silence", "dumadaloy", "moagi", "molabay"], "fact": {"tl": "Walang hangin sa Buwan o sa kalawakan kaya hindi makadaloy ang tunog doon—kaya nag-uusap ang mga astronaut gamit ang radyo kahit magkatabi sila.", "en": "There is no air on the Moon or in space, so sound cannot travel there—which is why astronauts talk through radios even when standing side by side.", "bis": "Walay hangin sa Bulan o sa kawanangan mao nga dili makaagi ang tingog didto—maoy hinungdan nga magsultihanay ang mga astronaut pinaagi sa radyo bisan magtapad sila."}, "source": "encyclopedia-stable consensus (sound needs a medium)", "generator": "claude-workflow", "reviewed": false},
  {"id": "satellites-many-jobs-g5", "domain": "EARTH_SPACE", "topic": "Different satellites do different jobs", "grades": [4, 5, 6], "terms": ["satellite", "satelayt", "trabaho", "buluhaton", "jobs", "telepono", "phone", "TV", "telebisyon", "internet", "panahon", "tiempo", "weather", "mapa", "GPS", "iba-iba", "lain-lain", "magkakaiba", "tulong", "tabang", "umiikot", "molibot", "kalawakan", "kawanangan", "komunikasyon", "communication"], "fact": {"tl": "Iba-iba ang trabaho ng mga satellite—may para sa panahon, para sa TV at internet, at para sa mapa—lahat sila umiikot sa Earth para tumulong sa atin.", "en": "Satellites have many different jobs—some for weather, some for TV and internet, some for maps—and they all orbit Earth to help us.", "bis": "Lain-lain ang buluhaton sa mga satellite—aduna para sa tiempo, para sa TV ug internet, ug para sa mapa—silang tanan molibot sa Earth aron motabang kanato."}, "source": "encyclopedia-stable consensus (satellite applications)", "generator": "claude-workflow", "reviewed": false},
  {"id": "ph-maya-cube-satellite-g7", "domain": "EARTH_SPACE", "topic": "The Philippines launched small Maya cube satellites", "grades": [6, 7, 8], "terms": ["Maya", "Maya-1", "Maya satellite", "Pilipinas", "Filipinas", "Philippines", "cube satellite", "CubeSat", "maliit na satellite", "gamay nga satellite", "small satellite", "estudyante", "tinun-an", "students", "Pinoy", "Pilipino", "ginawa", "gibuhat", "inilunsad", "gipasaka", "launched", "kahon", "kahon nga gamay", "kalawakan", "kawanangan"], "fact": {"tl": "Bukod sa Diwata, naglunsad ang Pilipinas ng mga maliliit na satellite na kasinglaki lang ng kahon na tinatawag na Maya, na tinulungang gawin ng mga estudyanteng Pinoy.", "en": "Besides Diwata, the Philippines launched tiny box-sized satellites called Maya, which Filipino students helped build.", "bis": "Gawas sa Diwata, ang Pilipinas nagpasaka ug gagmay nga satellite nga sama lang kadako sa kahon nga gitawag Maya, nga gitabangan paghimo sa mga estudyanteng Pilipino."}, "source": "encyclopedia-stable consensus (PH Maya CubeSat program, BIRDS project)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-too-bright-for-telescopes-g7", "domain": "EARTH_SPACE", "topic": "Space telescopes shield themselves from the Sun", "grades": [6, 7, 8], "terms": ["telescope", "teleskopyo", "Webb", "James Webb", "Araw", "Adlaw", "Sun", "init", "kainit", "liwanag", "kahayag", "sobrang init", "init kaayo", "too hot", "sunshield", "panangga", "taming", "shield", "lamig", "bugnaw", "tugnaw", "cold", "makita malabo", "makita hanap", "malayong bituin", "layo nga bituon"], "fact": {"tl": "Para makita ng James Webb ang mahihinang liwanag ng malalayong bituin, kailangan itong manatiling napakalamig, kaya may malaking panangga itong humaharang sa init ng Araw.", "en": "For James Webb to see the faint light of distant stars, it must stay extremely cold, so it has a giant shield blocking the Sun's heat.", "bis": "Aron makita sa James Webb ang huyang nga kahayag sa layo nga mga bituon, kinahanglan kini magpabilin nga bugnaw kaayo, mao nga aduna kini dakong taming nga nagsalipod sa kainit sa Adlaw."}, "source": "encyclopedia-stable consensus (JWST five-layer sunshield, cold infrared operation)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-nearest-star-g4", "domain": "EARTH_SPACE", "topic": "the sun is a star", "grades": [3, 4, 5], "terms": ["sun", "star", "araw", "bituin", "pinakamalapit", "bituing", "adlaw", "bitoon", "pinakaduol", "kabituinan", "nearest star", "why sun looks bigger"], "fact": {"tl": "Ang Araw ay isang bituin — ang pinakamalapit na bituin sa atin. Mukha itong mas malaki at maliwanag kaysa ibang bituin dahil napakalapit lang nito; ang ibang bituin ay sobrang layo kaya parang maliliit na tuldok lang sa gabi.", "en": "The Sun is a star — the closest star to us. It looks much bigger and brighter than other stars only because it is so near; the other stars are so far away that they look like tiny dots at night.", "bis": "Ang Adlaw usa ka bitoon — ang pinakaduol nga bitoon kanato. Murag mas dako ug mas hayag kini kaysa ubang bitoon tungod kay duol ra kaayo; ang ubang bitoon layo kaayo mao nga murag gagmay'ng tuldok lang sa gabii."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-why-shines-fusion-g5", "domain": "EARTH_SPACE", "topic": "why the sun shines", "grades": [5, 6, 7], "terms": ["why sun shines", "fusion", "hydrogen", "helium", "kung bakit nagliliwanag", "pagsasanib", "haydroheno", "helyo", "nagniningning", "bakit umiinit araw", "ngano nagdan-ag adlaw", "hydrogen nagtapok", "nuclear fusion kids"], "fact": {"tl": "Nagliliwanag ang Araw dahil sa kaibuturan nito, pinipisil ng matinding init at bigat ang mga maliliit na particle ng haydroheno hanggang magsanib sila at maging helyo — at ang prosesong ito ay naglalabas ng napakalaking enerhiya na liwanag at init.", "en": "The Sun shines because deep in its core, intense heat and pressure squeeze tiny hydrogen particles together until they join to form helium — and this process releases a huge amount of energy as light and heat.", "bis": "Nagdan-ag ang Adlaw tungod kay sa kinahiladman niini, ang grabe nga kainit ug bug-at mopit-os sa gagmay'ng particle sa hydrogen hangtod sila magtapok ug mahimong helium — ug kini nga proseso mopagawas og dako kaayo nga enerhiya nga kahayag ug kainit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-light-travel-time-g6", "domain": "EARTH_SPACE", "topic": "sunlight travel time", "grades": [6, 7, 8], "terms": ["sunlight", "eight minutes", "light travel", "liwanag ng araw", "walong minuto", "biyahe ng liwanag", "layo ng araw", "walo ka minuto", "kahayag sa adlaw", "unsa kadugay kahayag", "how long sunlight reaches earth"], "fact": {"tl": "Ang liwanag ng Araw ay umaabot sa Mundo sa loob ng mga 8 minuto, kahit napakabilis nito — kaya kapag tumingala ka sa Araw, nakikita mo kung ano ang itsura nito 8 minuto na ang nakalipas.", "en": "The Sun's light takes about 8 minutes to reach Earth, even though it travels incredibly fast — so when you look toward the Sun, you are seeing how it looked about 8 minutes ago.", "bis": "Ang kahayag sa Adlaw moabot sa Kalibutan sulod sa mga 8 ka minuto, bisan kusog kaayo kini molupad — busa kung motan-aw ka sa Adlaw, imong nakita kung unsa ang dagway niini 8 ka minuto na ang milabay."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-never-look-directly-g3", "domain": "EARTH_SPACE", "topic": "never look at the sun", "grades": [3, 4, 5], "terms": ["never look at sun", "eye damage", "huwag titigan ang araw", "mapinsala mata", "mabulag", "ayaw tan-awa adlaw", "makadaot mata", "mosilaw", "why looking at sun hurts", "bakit masakit titigan araw"], "fact": {"tl": "Huwag na huwag titigan nang diretso ang Araw, kahit sandali lang — ang sobrang liwanag at init nito ay puwedeng makasira sa loob ng iyong mata at humantong sa permanenteng pagkabulag, at hindi mo man lang ito mararamdamang nasasaktan habang nangyayari.", "en": "Never look directly at the Sun, even for a moment — its intense light and heat can damage the inside of your eye and cause permanent blindness, and you may not even feel pain while it is happening.", "bis": "Ayaw gyud tan-awa og diretso ang Adlaw, bisan makadiyot lang — ang grabe nga kahayag ug kainit niini makadaot sa sulod sa imong mata ug makahimong permanente nga pagkabuta, ug basin dili pa nimo mabati nga sakit samtang nahitabo kini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-eclipse-glasses-g5", "domain": "EARTH_SPACE", "topic": "safe sun viewing", "grades": [5, 6, 7], "terms": ["eclipse glasses", "safe viewing", "pinhole", "salamin pang-eklipse", "ligtas na pagtingin", "butas-karayom", "luwas nga pagtan-aw", "salamin sa eklipse", "sunglasses not safe", "ordinaryong salamin hindi sapat"], "fact": {"tl": "Hindi sapat ang ordinaryong sunglasses para tumingin sa Araw — kailangan ng espesyal na eclipse glasses, o puwede mong tingnan ang anino ng Araw sa pamamagitan ng maliit na butas sa papel (pinhole) na nagpapakita ng larawan nito sa lupa nang ligtas.", "en": "Ordinary sunglasses are not enough to look at the Sun — you need special eclipse glasses, or you can watch the Sun safely by letting it shine through a tiny hole in paper (a pinhole) that projects its image onto the ground.", "bis": "Dili igo ang ordinaryong sunglasses aron motan-aw sa Adlaw — kinahanglan og espesyal nga eclipse glasses, o pwede nimong tan-awon ang Adlaw nga luwas pinaagi sa gamay nga lungag sa papel (pinhole) nga mopakita sa hulagway niini sa yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-sunspot-cooler-g6", "domain": "EARTH_SPACE", "topic": "sunspots", "grades": [6, 7, 8], "terms": ["sunspot", "cooler dark spot", "magnetic", "mantsa ng araw", "mas malamig", "maitim na batik", "magnetiko", "mantsa sa adlaw", "mas bugnaw", "bahid", "why sunspots look dark", "bakit may itim na batik araw"], "fact": {"tl": "Ang sunspot ay maitim na batik sa ibabaw ng Araw na mas malamig kaysa paligid nito — hindi talaga ito itim, ngunit dahil mas malamig ito, mukha itong madilim katabi ng mas mainit at mas maliwanag na bahagi ng Araw. Dulot ito ng malakas na magnetikong puwersa.", "en": "A sunspot is a dark patch on the Sun's surface that is cooler than the area around it — it is not truly black, but because it is cooler it looks dark next to the hotter, brighter parts of the Sun. It is caused by strong magnetic forces.", "bis": "Ang sunspot usa ka itom nga bahid sa nawong sa Adlaw nga mas bugnaw kaysa palibot niini — dili gyud kini itom, apan tungod kay mas bugnaw kini, murag ngitngit kini tapad sa mas init ug mas hayag nga bahin sa Adlaw. Tungod kini sa kusog nga magnetikong puwersa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-sunspot-size-g7", "domain": "EARTH_SPACE", "topic": "sunspot size", "grades": [7, 8, 9], "terms": ["sunspot size", "bigger than earth", "laki ng sunspot", "mas malaki kaysa mundo", "mantsa kasing laki", "gidak-on sunspot", "mas dako kaysa kalibutan", "how big are sunspots", "gaano kalaki batik araw"], "fact": {"tl": "Kahit mukhang maliliit na batik lang ang mga sunspot kapag tiningnan mula sa Mundo, ang ilan sa kanila ay mas malaki pa kaysa sa buong planetang Mundo — napakalaki lang talaga ng Araw.", "en": "Even though sunspots look like small specks when seen from Earth, some of them are larger than the entire planet Earth — the Sun is simply enormous.", "bis": "Bisan murag gagmay lang nga bahid ang mga sunspot kung tan-awon gikan sa Kalibutan, ang uban kanila mas dako pa kaysa tibuok planeta nga Kalibutan — dako gyud kaayo ang Adlaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-solar-flare-g7", "domain": "EARTH_SPACE", "topic": "solar flares", "grades": [7, 8, 9], "terms": ["solar flare", "explosion", "burst of energy", "pagsabog ng araw", "biglang sabog enerhiya", "solar flare tagalog", "pagbuto sa adlaw", "kalit nga pagbuto", "what is a solar flare", "ano ang solar flare"], "fact": {"tl": "Ang solar flare ay biglaang malakas na pagsabog ng enerhiya at liwanag sa ibabaw ng Araw, kadalasang malapit sa mga sunspot — isa itong pinakamalakas na pagsabog sa ating Solar System, na naglalabas ng enerhiya sa loob lamang ng ilang minuto.", "en": "A solar flare is a sudden, powerful burst of energy and light from the Sun's surface, usually near sunspots — it is one of the most powerful explosions in our Solar System, releasing its energy in just minutes.", "bis": "Ang solar flare usa ka kalit, kusog nga pagbuto sa enerhiya ug kahayag gikan sa nawong sa Adlaw, kasagaran duol sa mga sunspot — usa kini sa pinakakusog nga pagbuto sa atong Solar System, nga mopagawas sa enerhiya niini sulod lang sa pipila ka minuto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-solar-wind-g6", "domain": "EARTH_SPACE", "topic": "solar wind", "grades": [6, 7, 8], "terms": ["solar wind", "stream of particles", "hangin ng araw", "agos ng particle", "solar wind tagalog", "hangin sa adlaw", "sulog sa particle", "what is solar wind", "ano ang solar wind", "not air wind"], "fact": {"tl": "Ang solar wind ay hindi hangin na tulad ng dito sa Mundo — ito ay tuloy-tuloy na agos ng napakaliliit na particle na pinakakawalan ng Araw sa lahat ng direksyon sa kalawakan, na umaabot pa hanggang sa Mundo at sa kabila pa.", "en": "The solar wind is not wind like the air on Earth — it is a constant stream of tiny particles that the Sun blows out in all directions into space, reaching all the way to Earth and beyond.", "bis": "Ang solar wind dili hangin nga sama dinhi sa Kalibutan — kini usa ka padayon nga sulog sa gagmay kaayong particle nga gihuyop sa Adlaw sa tanang direksyon ngadto sa kawanangan, nga moabot hangtod sa Kalibutan ug sa unahan pa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-causes-aurora-g6", "domain": "EARTH_SPACE", "topic": "sun causes auroras", "grades": [6, 7, 8], "terms": ["aurora", "northern lights", "solar wind earth", "ilaw sa hilaga", "aurora dulot ng araw", "kahayag sa amihanan", "aurora tungod sa adlaw", "what causes aurora", "bakit may aurora", "kung bakit may ilaw sa langit"], "fact": {"tl": "Ang magagandang kulay-kulay na ilaw sa langit na tinatawag na aurora (northern at southern lights) ay dulot ng Araw — kapag tumama ang mga particle mula sa solar wind sa hangin sa itaas ng Mundo malapit sa mga poste, nagliliwanag ang hanging iyon at nagiging makukulay na ilaw.", "en": "The beautiful colorful lights in the sky called auroras (the northern and southern lights) are caused by the Sun — when particles from the solar wind hit the air high above Earth near the poles, that air glows and turns into colorful lights.", "bis": "Ang nindot ug bulokon nga kahayag sa langit nga gitawag og aurora (northern ug southern lights) tungod sa Adlaw — kung ang mga particle gikan sa solar wind moigo sa hangin sa taas sa Kalibutan duol sa mga poste, modan-ag kana nga hangin ug mahimong bulokon nga kahayag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-aurora-poles-g7", "domain": "EARTH_SPACE", "topic": "why auroras at the poles", "grades": [7, 8, 9], "terms": ["aurora poles", "magnetic field earth", "bakit sa poste aurora", "magnetikong proteksyon", "kalasag ng mundo", "ngano sa poste aurora", "magnetikong panalipod", "why aurora only near poles", "bakit walang aurora sa pilipinas"], "fact": {"tl": "Karaniwang nakikita lang ang aurora malapit sa magkabilang poste ng Mundo, hindi sa mga tropikal na lugar tulad ng Pilipinas — ito ay dahil ginagabayan ng magnetikong puwersa ng Mundo ang mga particle mula sa Araw patungo sa mga poste.", "en": "Auroras are usually seen only near Earth's two poles, not in tropical places like the Philippines — this is because Earth's magnetic force guides the particles from the Sun toward the poles.", "bis": "Ang aurora kasagaran makita lang duol sa duha ka poste sa Kalibutan, dili sa tropikal nga mga dapit sama sa Pilipinas — tungod kini kay ang magnetikong puwersa sa Kalibutan mogiya sa mga particle gikan sa Adlaw padulong sa mga poste."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-magnetic-shield-g8", "domain": "EARTH_SPACE", "topic": "earth's magnetic shield", "grades": [8, 9, 10], "terms": ["magnetosphere", "magnetic shield", "protects earth", "magnetikong kalasag", "nagpoprotekta sa mundo", "solar wind harmful", "magnetikong taming", "manalipod sa kalibutan", "how earth is protected from sun", "paano protektado ang mundo sa araw"], "fact": {"tl": "Ang Mundo ay may di-nakikitang magnetikong kalasag (magnetosphere) na ginawa ng bakal sa kaibuturan nito — pinipigil nito ang karamihan ng nakakapinsalang particle mula sa solar wind ng Araw na umabot sa atin, kaya ligtas ang buhay sa ibabaw ng Mundo.", "en": "Earth has an invisible magnetic shield (the magnetosphere), made by the iron deep inside it — it blocks most of the harmful particles from the Sun's solar wind from reaching us, keeping life on Earth's surface safe.", "bis": "Ang Kalibutan adunay dili makita nga magnetikong taming (magnetosphere), nga gibuhat sa puthaw sa kinahiladman niini — kini mobabag sa kadaghanan sa makadaot nga particle gikan sa solar wind sa Adlaw aron dili kini moabot kanato, busa luwas ang kinabuhi sa nawong sa Kalibutan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-space-weather-g8", "domain": "EARTH_SPACE", "topic": "space weather effects", "grades": [8, 9, 10], "terms": ["space weather", "disrupt satellites", "solar storm", "panahon sa kalawakan", "makaapekto sa satellite", "bagyong solar", "unos sa kawanangan", "makaguba sa satellite", "can sun affect technology", "puwede bang masira gadget dahil sa araw"], "fact": {"tl": "Ang mga malalakas na solar flare at sabog mula sa Araw ay puwedeng makaapekto sa mga satellite, radyo, at maging sa kuryente dito sa Mundo — kaya may mga siyentipikong nagbabantay sa 'panahon sa kalawakan' (space weather) tulad ng pagbabantay sa bagyo.", "en": "Strong solar flares and bursts from the Sun can affect satellites, radios, and even electric power here on Earth — so scientists watch 'space weather' the same way they watch for storms.", "bis": "Ang kusog nga solar flare ug pagbuto gikan sa Adlaw makaapekto sa mga satellite, radyo, ug bisan sa kuryente dinhi sa Kalibutan — busa adunay mga siyentista nga nagbantay sa 'space weather' sama sa pagbantay sa bagyo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-core-temperature-g8", "domain": "EARTH_SPACE", "topic": "sun's core temperature", "grades": [8, 9, 10], "terms": ["sun core temperature", "15 million degrees", "init sa kaibuturan", "milyong degree", "kaibuturan ng araw", "temperatura sa kinahiladman", "milyon ka degree", "how hot is the sun inside", "gaano kainit ang loob ng araw"], "fact": {"tl": "Ang kaibuturan (core) ng Araw ay umaabot sa halos 15 milyong degree Celsius — milyon-milyong beses na mas mainit kaysa sa pinakamainit na oven sa lupa — at doon nagaganap ang pagsasanib na nagpapaningning sa Araw.", "en": "The Sun's core reaches about 15 million degrees Celsius — far hotter than the hottest oven on Earth — and that is where the fusion that makes the Sun shine takes place.", "bis": "Ang kinahiladman (core) sa Adlaw moabot sa mga 15 ka milyon ka degree Celsius — labi pa ka init kaysa pinakainit nga hudno sa yuta — ug didto mahitabo ang fusion nga maoy hinungdan sa kahayag sa Adlaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-size-earths-fit-g6", "domain": "EARTH_SPACE", "topic": "how big the sun is", "grades": [6, 7, 8], "terms": ["sun size", "million earths", "laki ng araw", "milyong mundo kasya", "gaano kalaki araw", "gidak-on sa adlaw", "milyon ka kalibutan", "how many earths fit in sun", "ilang mundo kasya sa araw"], "fact": {"tl": "Napakalaki ng Araw kaya mahigit isang milyong Mundo ang kasya sa loob nito — ito ang pinakamalaking bagay sa ating Solar System, na may halos lahat ng timbang ng buong sistema.", "en": "The Sun is so big that more than a million Earths could fit inside it — it is the largest object in our Solar System, holding almost all the mass of the entire system.", "bis": "Dako kaayo ang Adlaw mao nga kapin sa usa ka milyon ka Kalibutan ang mahimong masulod niini — kini ang pinakadako nga butang sa atong Solar System, nga adunay halos tanang gibug-aton sa tibuok sistema."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-ball-of-gas-g5", "domain": "EARTH_SPACE", "topic": "sun is a ball of hot gas", "grades": [5, 6, 7], "terms": ["ball of gas", "plasma", "no solid ground", "bola ng gas", "walang lupa araw", "init na gas", "bola sa gas", "walay yuta adlaw", "is the sun solid", "puwede bang lakaran ang araw"], "fact": {"tl": "Ang Araw ay hindi solido tulad ng Mundo — isa itong napakainit na bola ng gas, kaya walang lupa na puwedeng tapakan doon. Karamihan dito ay haydroheno at helyo.", "en": "The Sun is not solid like Earth — it is a giant ball of very hot gas, so there is no ground to stand on there. It is mostly hydrogen and helium.", "bis": "Ang Adlaw dili gahi sama sa Kalibutan — usa kini ka dako kaayo nga bola sa init kaayong gas, busa walay yuta nga matumban didto. Kasagaran niini hydrogen ug helium."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-gives-most-energy-g4", "domain": "EARTH_SPACE", "topic": "sun powers life on earth", "grades": [4, 5, 6], "terms": ["sun energy life", "source of energy", "pinagmumulan ng enerhiya", "araw nagbibigay buhay", "halos lahat ng enerhiya", "tinubdan sa enerhiya", "adlaw naghatag kinabuhi", "why is the sun important", "bakit mahalaga ang araw"], "fact": {"tl": "Halos lahat ng enerhiya na ginagamit ng buhay sa Mundo ay nagmula sa Araw — ang halaman ay gumagawa ng pagkain mula sa sikat nito, at ang init nito ang nagpapainit sa hangin, dagat, at sa atin.", "en": "Almost all the energy that life on Earth uses comes from the Sun — plants make food from its light, and its heat warms the air, the seas, and us.", "bis": "Halos tanang enerhiya nga gigamit sa kinabuhi sa Kalibutan naggikan sa Adlaw — ang tanom mohimo og pagkaon gikan sa kahayag niini, ug ang kainit niini moinit sa hangin, sa dagat, ug kanato."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-color-white-g6", "domain": "EARTH_SPACE", "topic": "the sun's true color", "grades": [6, 7, 8], "terms": ["sun color white", "looks yellow", "kulay ng araw", "puti talaga", "bakit dilaw araw", "kolor sa adlaw", "puti gyud", "ngano dalag adlaw", "what color is the sun", "tunay na kulay araw"], "fact": {"tl": "Ang tunay na kulay ng Araw ay puti, hindi dilaw — mukhang dilaw o kahel lang ito sa atin dahil sumasalain ng hangin ng Mundo ang ilang kulay ng liwanag nito, lalo na kapag mababa ito sa paglubog o pagsikat.", "en": "The Sun's true color is white, not yellow — it only looks yellow or orange to us because Earth's air filters out some colors of its light, especially when it is low at sunrise or sunset.", "bis": "Ang tinuod nga kolor sa Adlaw puti, dili dalag — murag dalag o kahel lang kini kanato tungod kay ang hangin sa Kalibutan mosala sa pipila ka kolor sa kahayag niini, ilabi na kung ubos kini sa pagsubang o pagsalop."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-rotation-g7", "domain": "EARTH_SPACE", "topic": "the sun spins", "grades": [7, 8, 9], "terms": ["sun rotates", "sun spins", "umiikot ang araw", "pag-ikot ng araw", "gas iba-ibang bilis", "nagtuyok ang adlaw", "pagtuyok sa adlaw", "does the sun rotate", "umiikot ba ang araw"], "fact": {"tl": "Umiikot din ang Araw tulad ng Mundo, ngunit dahil gas ito at hindi solido, hindi pare-pareho ang bilis ng pag-ikot nito — mas mabilis umikot ang gitna (ekwador) nito kaysa sa mga bahaging malapit sa poste.", "en": "The Sun spins like Earth, but because it is gas and not solid, it does not spin at one speed — its middle (equator) rotates faster than the parts near its poles.", "bis": "Nagtuyok pud ang Adlaw sama sa Kalibutan, apan tungod kay gas kini ug dili gahi, dili managsama ang katulin sa pagtuyok niini — mas paspas motuyok ang tunga (ekwador) niini kaysa mga bahin nga duol sa poste."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-age-lifespan-g8", "domain": "EARTH_SPACE", "topic": "the sun's age and lifespan", "grades": [8, 9, 10], "terms": ["sun age", "billions of years", "edad ng araw", "bilyong taon", "gatong na haydroheno", "edad sa adlaw", "bilyon ka tuig", "how old is the sun", "gaano katanda ang araw", "sun lifespan"], "fact": {"tl": "Ang Araw ay halos 4.6 bilyong taon na ang edad at nasa kalagitnaan pa lang ng buhay nito — may sapat pa itong haydroheno para magningning ng mga 5 bilyong taon pa, kaya hindi tayo dapat mag-alala na mawawala ito sa loob ng mahabang-mahabang panahon.", "en": "The Sun is about 4.6 billion years old and only about halfway through its life — it still has enough hydrogen to keep shining for about 5 billion more years, so we need not worry about it running out for a very, very long time.", "bis": "Ang Adlaw mga 4.6 ka bilyon na ka tuig ang edad ug tunga pa lang sa kinabuhi niini — aduna pa kini igong hydrogen aron modan-ag og mga 5 ka bilyon pa ka tuig, busa dili kita kinahanglan mabalaka nga mahurot kini sulod sa taas kaayo nga panahon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-solar-cycle-g8", "domain": "EARTH_SPACE", "topic": "the solar cycle", "grades": [8, 9, 10], "terms": ["solar cycle", "11 years", "more sunspots", "siklo ng araw", "labing-isang taon", "dumarami sunspot", "siklo sa adlaw", "napulo'g usa ka tuig", "why sunspots come and go", "bakit nagbabago dami ng sunspot"], "fact": {"tl": "Ang dami ng sunspot at solar flare ay nagbabago sa isang regular na siklo na halos 11 taon — may mga panahong marami ang sunspot at maraming sabog, at may mga panahong halos wala, dahil sa pagbabago ng magnetikong puwersa ng Araw.", "en": "The number of sunspots and solar flares changes in a regular cycle of about 11 years — there are times of many sunspots and many bursts, and quiet times of almost none, because the Sun's magnetic force keeps changing.", "bis": "Ang gidaghanon sa sunspot ug solar flare mausab sa usa ka regular nga siklo nga mga 11 ka tuig — adunay panahon nga daghan ang sunspot ug daghang pagbuto, ug adunay hilom nga panahon nga halos wala, tungod sa pagbalhinbalhin sa magnetikong puwersa sa Adlaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-corona-hotter-g9", "domain": "EARTH_SPACE", "topic": "the sun's corona", "grades": [9, 10], "terms": ["corona", "outer atmosphere hotter", "korona ng araw", "mas mainit ang labas", "mistery ng korona", "korona sa adlaw", "mas init ang gawas", "why corona is hotter than surface", "misteryo ng init ng araw"], "fact": {"tl": "Ang korona (corona) ay ang pinakalabas na hangin ng Araw na nakikita bilang maliwanag na singsing tuwing kumpletong eklipse — kakaiba ito dahil mas mainit pa ito kaysa sa mismong ibabaw ng Araw, isang bagay na hanggang ngayon ay pinag-aaralan pa ng mga siyentipiko.", "en": "The corona is the Sun's outermost atmosphere, seen as a glowing ring during a total eclipse — strangely, it is even hotter than the Sun's own surface, a puzzle scientists are still studying.", "bis": "Ang corona mao ang pinakagawas nga hangin sa Adlaw, makita isip nagdan-ag nga singsing panahon sa total nga eklipse — katingad-an kay mas init pa kini kaysa nawong mismo sa Adlaw, usa ka misteryo nga gitun-an pa gihapon sa mga siyentista."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-eclipse-corona-g7", "domain": "EARTH_SPACE", "topic": "seeing the corona during eclipse", "grades": [7, 8, 9], "terms": ["total solar eclipse", "see corona", "kumpletong eklipse", "makita ang korona", "natatakpan ang araw", "total nga eklipse", "makita korona", "when can we see the corona", "kailan makikita ang korona"], "fact": {"tl": "Karaniwang hindi natin nakikita ang malamlam na korona ng Araw dahil sobrang liwanag ng Araw mismo — pero tuwing kumpletong solar eclipse, kapag tinatakpan ng Buwan ang Araw, lumilitaw ang korona bilang magandang singsing ng liwanag sa paligid ng madilim na bilog.", "en": "We normally cannot see the Sun's faint corona because the Sun itself is too bright — but during a total solar eclipse, when the Moon covers the Sun, the corona appears as a beautiful ring of light around the dark circle.", "bis": "Kasagaran dili nato makita ang hanap nga corona sa Adlaw tungod kay hayag kaayo ang Adlaw mismo — apan panahon sa total nga solar eclipse, kung ang Bulan motabon sa Adlaw, motungha ang corona isip nindot nga singsing sa kahayag palibot sa ngitngit nga lingin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-photons-journey-g9", "domain": "EARTH_SPACE", "topic": "how long energy takes to leave the sun", "grades": [9, 10], "terms": ["photon journey", "thousands of years", "liwanag galing core", "libong taon", "matagal lumabas", "kahayag gikan core", "libo ka tuig", "why sunlight is so old", "gaano katagal lumabas liwanag sa araw"], "fact": {"tl": "Ang liwanag na nililikha sa kaibuturan ng Araw ay tumatagal ng libu-libong taon bago makalabas sa ibabaw nito, dahil paulit-ulit itong tumatama sa siksik na gas sa loob — kaya ang sikat na umaabot sa atin ngayon ay galing sa enerhiyang nilikha noon pang sinaunang panahon.", "en": "The light created in the Sun's core takes thousands of years to escape to its surface, because it keeps bouncing off the dense gas inside — so the sunlight reaching us today comes from energy made long, long ago.", "bis": "Ang kahayag nga gimugna sa kinahiladman sa Adlaw mokuha og liboan ka tuig una makagawas sa nawong niini, tungod kay balikbalik kini moigo sa baga nga gas sa sulod — busa ang kahayag nga moabot kanato karon naggikan sa enerhiya nga gihimo dugay na kaayong panahon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-prominence-loops-g9", "domain": "EARTH_SPACE", "topic": "solar prominences", "grades": [9, 10], "terms": ["solar prominence", "loops of gas", "arko ng gas", "umaarko sa araw", "magnetikong loop", "arko sa gas", "solar prominence tagalog", "what are the loops on the sun", "bakit may arko ang araw"], "fact": {"tl": "Minsan ang mainit na gas ng Araw ay umaarko paitaas mula sa ibabaw nito sa hugis-tulay na tinatawag na prominence, na hinuhubog ng magnetikong puwersa — ang ilan sa mga arkong ito ay mas mataas pa kaysa sa maraming Mundong nakapatong-patong.", "en": "Sometimes the Sun's hot gas arcs up from its surface in bridge-like shapes called prominences, shaped by magnetic force — some of these arches are taller than many Earths stacked on top of each other.", "bis": "Usahay ang init nga gas sa Adlaw moarko paibabaw gikan sa nawong niini sa porma nga sama sa taytayan nga gitawag og prominence, gihulma sa magnetikong puwersa — ang uban niini nga arko mas taas pa kaysa daghang Kalibutan nga gipatong-patong."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-gravity-holds-planets-g7", "domain": "EARTH_SPACE", "topic": "the sun's gravity holds the solar system", "grades": [7, 8, 9], "terms": ["sun gravity", "holds planets", "grabidad ng araw", "humihila ng planeta", "umiikot sa araw", "grabidad sa adlaw", "molibot sa adlaw", "why do planets orbit the sun", "bakit umiikot ang planeta sa araw"], "fact": {"tl": "Napakalakas ng grabidad ng Araw dahil sa laki nito kaya hinihila nito ang lahat ng planeta, kasama ang Mundo, na umikot paligid dito — kung wala ang grabidad ng Araw, lilipad palayo ang mga planeta sa kalawakan.", "en": "The Sun's gravity is so strong because of its huge size that it holds all the planets, including Earth, orbiting around it — without the Sun's gravity, the planets would fly off into space.", "bis": "Kusog kaayo ang grabidad sa Adlaw tungod sa kadako niini mao nga gibira niini ang tanang planeta, lakip ang Kalibutan, nga molibot palibot niini — kung walay grabidad sa Adlaw, molupad palayo ang mga planeta ngadto sa kawanangan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-not-on-fire-g6", "domain": "EARTH_SPACE", "topic": "the sun is not burning like fire", "grades": [6, 7, 8], "terms": ["sun not fire", "no oxygen", "hindi apoy ang araw", "walang oxygen", "hindi nasusunog", "dili kalayo ang adlaw", "walay oxygen", "is the sun on fire", "nasusunog ba ang araw na parang apoy"], "fact": {"tl": "Kahit mukhang nagliliyab ang Araw, hindi ito nasusunog na parang apoy ng kandila — walang oxygen sa kalawakan para mag-apoy. Sa halip, ang liwanag at init nito ay galing sa pagsasanib ng mga particle sa kaibuturan nito, isang ganap na ibang proseso.", "en": "Even though the Sun looks like it is blazing, it is not burning like a candle flame — there is no oxygen in space to burn. Instead, its light and heat come from fusion of particles in its core, a completely different process.", "bis": "Bisan murag nagdilaab ang Adlaw, dili kini nasunog sama sa kalayo sa kandila — walay oxygen sa kawanangan aron mokalayo. Hinuon, ang kahayag ug kainit niini gikan sa fusion sa mga particle sa kinahiladman niini, usa ka lahi gyud nga proseso."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-future-red-giant-g9", "domain": "EARTH_SPACE", "topic": "the sun's distant future", "grades": [9, 10], "terms": ["red giant", "sun future", "red giant tagalog", "kinabukasan ng araw", "lalaki ang araw", "umpisang lumamig", "kaugmaon sa adlaw", "modako ang adlaw", "what will happen to the sun", "ano mangyayari sa araw sa hinaharap"], "fact": {"tl": "Pagkatapos ng mga 5 bilyong taon pa, kapag naubos na ang gatong na haydroheno ng Araw, lalaki ito nang husto at magiging pula — ang tinatawag na red giant. Pero napakatagal pa nito kaya wala tayong dapat ikabahala ngayon.", "en": "After about 5 billion more years, when the Sun's hydrogen fuel runs low, it will swell up huge and turn red — becoming what is called a red giant. But this is so far away that we have nothing to worry about now.", "bis": "Human sa mga 5 ka bilyon pa ka tuig, kung mahurot na ang gatong nga hydrogen sa Adlaw, modako kini pag-ayo ug mahimong pula — ang gitawag nga red giant. Apan layo pa kaayo kini mao nga wala kitay angay'ng kabalak-an karon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-heat-light-only-source-g4", "domain": "EARTH_SPACE", "topic": "the sun and day and night", "grades": [3, 4, 5], "terms": ["sun day night", "sunlight warms", "araw at gabi", "init at liwanag", "sikat ng araw nagpapainit", "adlaw ug gabii", "kainit ug kahayag", "why is it warm in the day", "bakit mas mainit sa umaga"], "fact": {"tl": "Tuwing araw, mas mainit at maliwanag dahil nakaharap sa Araw ang bahagi ng Mundo na kinaroroonan natin; tuwing gabi, mas malamig at madilim dahil tumalikod na ang ating bahagi sa Araw habang umiikot ang Mundo.", "en": "During the day it is warmer and bright because our part of Earth faces the Sun; at night it is cooler and dark because our part has turned away from the Sun as Earth spins.", "bis": "Panahon sa adlaw, mas init ug hayag tungod kay nag-atubang sa Adlaw ang bahin sa Kalibutan nga atong gipuy-an; panahon sa gabii, mas bugnaw ug ngitngit tungod kay mitalikod na ang atong bahin sa Adlaw samtang nagtuyok ang Kalibutan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cloud-weight-tons-g5", "domain": "EARTH_SPACE", "topic": "how much a cloud weighs", "grades": [5, 6, 7], "terms": ["cloud weight", "bigat ng ulap", "ulap", "panganod", "gibug-aton sa panganod", "tonelada", "tons", "elephant", "elepante", "bakit lumulutang ang ulap", "ngano naglutaw ang panganod", "tubig", "naglutaw", "lumulutang", "tonnes"], "fact": {"tl": "Kahit mukhang magaan ang isang malaking puting ulap, ang tubig sa loob nito ay maaaring tumimbang ng daan-daang tonelada — kasimbigat ng maraming elepante — pero nananatili itong nakalutang dahil ang tubig ay nakakalat bilang napakaliliit na patak sa hangin.", "en": "Even though a big puffy white cloud looks light, the water inside it can weigh hundreds of tons — as heavy as many elephants — yet it stays floating because the water is spread out as tiny droplets in the air.", "bis": "Bisan og morag gaan ang usa ka dako nga puti nga panganod, ang tubig sa sulod niini mahimong motimbang og gatusan ka tonelada — sama kabug-at sa daghang elepante — apan magpabilin kini nga naglutaw kay ang tubig nagkatag isip gagmay kaayo nga tulo sa hangin."}, "source": "encyclopedia-stable consensus (USGS cloud water content)", "generator": "claude-workflow", "reviewed": false},
  {"id": "cumulus-shapes-flat-bottom-g5", "domain": "EARTH_SPACE", "topic": "why cumulus clouds have flat bottoms", "grades": [5, 6, 7], "terms": ["cumulus", "flat bottom", "patag na ilalim", "patag nga ubos", "cottony cloud", "ulap na parang bulak", "panganod nga morag gapas", "bakit may pantay na base ang ulap", "ngano patag ang ilalom sa panganod", "condensation level", "init", "umaakyat na hangin", "saka nga hangin"], "fact": {"tl": "Maraming maputi at malabukol na cumulus na ulap ay may patag na ilalim dahil ang umaakyat na maligamgam na hangin ay lumalamig at nagiging patak ng tubig sa iisang taas — kaya parang nakaupo sila sa di-nakikitang pantay na linya sa langit.", "en": "Many white, lumpy cumulus clouds have flat bottoms because rising warm air cools and turns into water droplets at the same height — so the clouds look like they are sitting on an invisible flat line in the sky.", "bis": "Daghang puti ug bukol-bukol nga cumulus nga panganod adunay patag nga ubos kay ang nagsaka nga init nga hangin mobugnaw ug mahimong tulo sa tubig sa managsama nga gitas-on — busa morag naglingkod sila sa dili makita nga patag nga linya sa langit."}, "source": "encyclopedia-stable consensus (lifting condensation level)", "generator": "claude-workflow", "reviewed": false},
  {"id": "cirrus-ice-crystals-g6", "domain": "EARTH_SPACE", "topic": "cirrus clouds are made of ice", "grades": [6, 7, 8], "terms": ["cirrus", "ice crystals", "kristal ng yelo", "kristal sa yelo", "mga manipis na ulap", "balahibo sa langit", "wispy cloud", "ulap na parang buhok", "panganod nga morag balhibo", "mataas na ulap", "taas nga panganod", "malamig", "bugnaw", "feather cloud"], "fact": {"tl": "Ang manipis at parang balahibong cirrus na ulap ay napakataas sa langit kung saan napakalamig, kaya gawa sila hindi sa patak ng tubig kundi sa maliliit na kristal ng yelo na inaanod ng hangin sa hugis-buhok.", "en": "Thin, feathery cirrus clouds are so high up where it is freezing cold that they are made not of water droplets but of tiny ice crystals blown by the wind into hair-like wisps.", "bis": "Ang nipis ug morag balhibo nga cirrus nga panganod taas kaayo sa langit diin bugnaw kaayo, busa hinimo sila dili sa tulo sa tubig kondili sa gagmay nga kristal sa yelo nga gipalid sa hangin nga morag buhok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "stratus-blanket-sky-g5", "domain": "EARTH_SPACE", "topic": "stratus clouds cover the sky like a blanket", "grades": [5, 6, 7], "terms": ["stratus", "blanket cloud", "ulap na parang kumot", "panganod nga morag habol", "gray sky", "kulay-abong langit", "abuhon nga langit", "maulap na araw", "madlom nga adlaw", "ambon", "drizzle", "talithi", "manipis na ulan", "low cloud", "mababang ulap", "ubos nga panganod"], "fact": {"tl": "Kapag kulay-abo at pantay ang buong langit na parang nababalot ng kumot, malamang stratus na ulap iyon — mababa itong ulap na nagkakalat ng malamlam na liwanag at kadalasang nagdadala ng ambon, hindi malakas na ulan.", "en": "When the whole sky is gray and even, like it is wrapped in a blanket, that is usually stratus cloud — a low cloud that spreads dull light and often brings drizzle rather than heavy rain.", "bis": "Kon ang tibuok langit abuhon ug patag nga morag giputos og habol, kasagaran stratus kana nga panganod — usa ka ubos nga panganod nga nagkatag og hanap nga kahayag ug kasagaran nagdala og talithi, dili kusog nga ulan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "thunderstorm-anvil-top-g6", "domain": "EARTH_SPACE", "topic": "why storm clouds have a flat anvil top", "grades": [6, 7, 8], "terms": ["cumulonimbus", "thunderstorm cloud", "ulap ng bagyo", "panganod sa unos", "anvil", "palihan", "flat top", "patag na taas", "patag nga tumoy", "kidlat", "kulog", "bakit pumapatag ang taas ng ulap", "ngano mopatag ang tumoy", "stratosphere", "tropopause", "thundercloud"], "fact": {"tl": "Ang matataas na ulap ng kidlat (cumulonimbus) ay umaakyat nang umaakyat hanggang umabot sa isang patong ng himpapawid na hindi na nila madaanan, kaya kumakalat pahalang ang taas nito at nagiging parang patag na palihan (anvil).", "en": "Tall thundercloud (cumulonimbus) keeps growing upward until it hits a layer of the atmosphere it cannot rise past, so its top spreads out sideways into a flat anvil shape.", "bis": "Ang taas nga panganod sa kilat (cumulonimbus) magpadayon og saka hangtod maabot ang usa ka layer sa kahanginan nga dili na niya malabang, busa mokatag pinahigda ang tumoy niini ug mahimong morag patag nga palihan (anvil)."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lightning-hotter-than-sun-g6", "domain": "EARTH_SPACE", "topic": "lightning is hotter than the sun's surface", "grades": [6, 7, 8], "terms": ["lightning temperature", "init ng kidlat", "kainit sa kilat", "kidlat", "kilat", "lightning", "mas mainit sa araw", "labaw kainit sa adlaw", "hotter than sun", "bakit napakainit ng kidlat", "ngano init kaayo ang kilat", "30000", "Celsius", "spark"], "fact": {"tl": "Sa isang iglap, ang hangin sa daanan ng kidlat ay umiinit nang higit sa 30,000°C — limang beses na mas mainit pa kaysa sa ibabaw ng araw — kaya napakaliwanag at biglang sumasabog sa kaliwanagan ang kidlat.", "en": "In a flash, the air along a lightning bolt heats up to over 30,000°C — about five times hotter than the surface of the sun — which is why lightning is so blindingly bright.", "bis": "Sa usa ka pisik, ang hangin sa agianan sa kilat moinit og kapin sa 30,000°C — mga lima ka pilo nga mas init pa kay sa nawong sa adlaw — maong hayag kaayo ug kalit nga mosiga ang kilat."}, "source": "encyclopedia-stable consensus (lightning channel temperature)", "generator": "claude-workflow", "reviewed": false},
  {"id": "thunder-is-exploding-air-g6", "domain": "EARTH_SPACE", "topic": "thunder is the sound of exploding air", "grades": [6, 7, 8], "terms": ["thunder", "kulog", "dalogdog", "dugdog", "sound of thunder", "tunog ng kulog", "tingog sa dalogdog", "bakit may kulog", "ngano adunay dalogdog", "sumasabog na hangin", "mibuto nga hangin", "shock wave", "air expands", "kidlat", "kilat", "rumble"], "fact": {"tl": "Ang kulog ay ang tunog ng hanging mabilis na lumalawak at sumasabog dahil sa init ng kidlat — parang biglaang pagbuto na umuugong palayo sa langit pagkatapos ng kidlat.", "en": "Thunder is the sound of air rapidly expanding and exploding from the heat of a lightning bolt — like a sudden bang that rumbles away across the sky after the flash.", "bis": "Ang dalogdog mao ang tingog sa hangin nga paspas nga mibuklad ug mibuto tungod sa kainit sa kilat — morag kalit nga buto nga modahunog palayo sa langit human sa kilat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "count-seconds-thunder-distance-g5", "domain": "EARTH_SPACE", "topic": "counting seconds to tell how far a storm is", "grades": [5, 6, 7], "terms": ["count seconds lightning thunder", "bilang ng segundo", "ihap sa segundo", "gaano kalayo ang bagyo", "unsa kalayo ang unos", "kidlat at kulog", "kilat ug dalogdog", "distansya ng kidlat", "lebog sa kilat", "bakit may pagitan ang kidlat at kulog", "ngano adunay lat-ang", "tatlong segundo", "kilometro", "sound speed"], "fact": {"tl": "Pwede mong malaman kung gaano kalayo ang bagyo: bilangin ang mga segundo mula nang makita ang kidlat hanggang marinig ang kulog, at bawat tatlong segundo ay mga isang kilometro ang layo ng kidlat sa iyo.", "en": "You can tell how far away a storm is: count the seconds from when you see the lightning to when you hear the thunder, and every three seconds means the lightning is about one kilometer away.", "bis": "Mahibal-an nimo kung unsa kalayo ang unos: ihapa ang mga segundo gikan sa pagkita sa kilat hangtod madungog ang dalogdog, ug matag tulo ka segundo nagpasabot nga ang kilat mga usa ka kilometro ang gilay-on gikan kanimo."}, "source": "encyclopedia-stable consensus (speed of sound ≈ 343 m/s)", "generator": "claude-workflow", "reviewed": false},
  {"id": "lightning-strikes-ground-up-g7", "domain": "EARTH_SPACE", "topic": "the bright lightning stroke travels upward", "grades": [7, 8, 9], "terms": ["lightning direction", "return stroke", "kidlat", "kilat", "pataas ang kidlat", "saka ang kilat", "ground to cloud", "lupa papuntang ulap", "yuta padulong panganod", "bakit pataas ang kidlat", "ngano pasaka ang kilat", "stepped leader", "static charge", "kuryente"], "fact": {"tl": "Kahit mukhang bumabagsak ang kidlat mula sa ulap, ang pinakamaliwanag na bahagi nito ay sumasabog pataas mula sa lupa patungong ulap sa loob ng kaunti pa sa isang kisapmata, kaya tila biglang sumiklab ang buong daanan.", "en": "Although lightning looks like it falls from the cloud, its brightest part actually shoots upward from the ground to the cloud in less than a blink, which is why the whole bolt seems to flash at once.", "bis": "Bisan og morag nahulog ang kilat gikan sa panganod, ang labing hayag nga bahin niini sa tinuod misaka gikan sa yuta padulong sa panganod sa wala pa molabaw sa usa ka pamilok, busa morag kalit nga misiga ang tibuok agianan."}, "source": "encyclopedia-stable consensus (return stroke)", "generator": "claude-workflow", "reviewed": false},
  {"id": "hail-layers-like-onion-g6", "domain": "EARTH_SPACE", "topic": "hailstones have layers like an onion", "grades": [6, 7, 8], "terms": ["hail layers", "ulan na yelo", "ulan nga yelo", "hailstone", "granizo", "kapas-kapas na yelo", "balak-balak nga yelo", "parang sibuyas", "morag sibuyas", "bakit may layer ang yelo", "ngano adunay layer ang yelo", "pataas-pababang biyahe", "thundercloud", "frozen rings"], "fact": {"tl": "Kung hahatiin mo ang isang malaking butil ng hail, makikita mo ang mga patong-patong na yelo na parang sibuyas — bawat patong ay isang pagtaas-pagbaba nito sa loob ng malamig na ulap bago tuluyang bumagsak.", "en": "If you slice a big hailstone in half, you can see layers of ice like an onion — each layer is one more trip it took up and down inside the cold storm cloud before it finally fell.", "bis": "Kon imong tunga-tungaon ang usa ka dako nga hail, makita nimo ang sapaw-sapaw nga yelo nga morag sibuyas — matag sapaw usa ka biyahe niini pasaka ug paubos sulod sa bugnaw nga panganod una kini nahulog."}, "source": "encyclopedia-stable consensus (hailstone accretion layers)", "generator": "claude-workflow", "reviewed": false},
  {"id": "frost-skips-liquid-g6", "domain": "EARTH_SPACE", "topic": "frost forms straight from water vapor without dew", "grades": [6, 7, 8], "terms": ["frost", "namuong hamog", "tun-og nga yelo", "yelong hamog", "frozen vapor", "deposition", "singaw papuntang yelo", "alisngaw padulong yelo", "bakit may frost", "ngano adunay frost", "walang dumaang tubig", "deretso yelo", "deretsong yelo", "lamig", "bugnaw", "ice crystals"], "fact": {"tl": "Hindi laging dumadaan sa pagiging tubig ang frost: kapag napakalamig, ang singaw ng tubig sa hangin ay maaaring direktang maging kristal ng yelo sa dahon o salamin nang hindi muna nagiging patak — ito ang dahilan ng magagandang disenyong yelo.", "en": "Frost does not always pass through being water first: when it is very cold, water vapor in the air can turn straight into ice crystals on a leaf or window without becoming a droplet — which is why frost makes lacy patterns.", "bis": "Dili kanunay moagi sa pagkahimong tubig ang frost: kon bugnaw kaayo, ang alisngaw sa tubig sa hangin mahimong direkta nga mahimong kristal sa yelo sa dahon o bildo nga dili una mahimong tulo — maong matahum ang disenyo sa frost."}, "source": "encyclopedia-stable consensus (deposition)", "generator": "claude-workflow", "reviewed": false},
  {"id": "dew-point-why-grass-wet-g6", "domain": "EARTH_SPACE", "topic": "why grass is wet in the morning even without rain", "grades": [6, 7, 8], "terms": ["dew", "hamog", "tun-og", "morning dew", "basa ang damo sa umaga", "basa ang sagbot sa buntag", "bakit basa ang damo kahit walang ulan", "ngano basa ang sagbot bisan walay ulan", "condensation", "singaw", "alisngaw", "lumamig sa gabi", "mibugnaw sa gabii", "water vapor"], "fact": {"tl": "Kahit hindi umulan, basa ang damo tuwing umaga dahil sa gabi ay lumalamig ang lupa at dahon, at ang singaw ng tubig sa hangin ay namumuo bilang patak (hamog) sa malalamig na ibabaw na ito.", "en": "Even when it did not rain, the grass is wet in the morning because at night the ground and leaves cool down, and water vapor in the air condenses into droplets (dew) on these cold surfaces.", "bis": "Bisan og wala mag-ulan, basa ang sagbot kada buntag kay sa gabii mobugnaw ang yuta ug dahon, ug ang alisngaw sa tubig sa hangin moporma isip tulo (tun-og) sa bugnaw nga mga nawong niini."}, "source": "encyclopedia-stable consensus (dew point)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sunset-red-blue-scattered-g6", "domain": "EARTH_SPACE", "topic": "why the sky is blue by day but red at sunset", "grades": [6, 7, 8], "terms": ["sky color", "kulay ng langit", "kolor sa langit", "asul ang langit", "asul nga langit", "pula ang langit", "pula nga langit", "sunset", "paglubog ng araw", "pagsalop sa adlaw", "scattering", "bakit asul ang langit", "ngano asul ang langit", "bughaw", "makapal na hangin", "baga nga hangin", "Rayleigh"], "fact": {"tl": "Asul ang langit kapag araw dahil mas ikinakalat ng hangin ang asul na liwanag; ngunit sa paglubog ng araw, ang liwanag ay dumaraan sa mas makapal na hangin na nagtatanggal sa asul at nag-iiwan ng pula't kahel.", "en": "The sky is blue during the day because air scatters blue light the most; but at sunset the light passes through much more air, which removes the blue and leaves the reds and oranges.", "bis": "Asul ang langit kon adlaw kay ang hangin maoy labing nagkatag sa asul nga kahayag; apan sa pagsalop sa adlaw, ang kahayag moagi sa mas baga nga hangin nga mowala sa asul ug mobilin sa pula ug kahel."}, "source": "encyclopedia-stable consensus (Rayleigh scattering)", "generator": "claude-workflow", "reviewed": false},
  {"id": "moon-halo-ice-crystals-g6", "domain": "EARTH_SPACE", "topic": "why a ring sometimes circles the moon", "grades": [6, 7, 8], "terms": ["moon halo", "singsing sa buwan", "alibangbang sa bulan", "bilog sa buwan", "lingin sa bulan", "halo", "ring around moon", "korona ng buwan", "korona sa bulan", "bakit may bilog sa paligid ng buwan", "ngano adunay lingin libot sa bulan", "ice crystals", "kristal ng yelo", "cirrus", "22 degrees", "refraction"], "fact": {"tl": "Kapag may makitang malaking bilog sa paligid ng buwan, ito ay dahil sa maliliit na kristal ng yelo na lumulutang sa matataas na manipis na ulap na bumabaluktot sa liwanag ng buwan papunta sa isang singsing.", "en": "When you see a big ring around the moon, it is caused by tiny ice crystals floating in high, thin clouds that bend the moon's light into a circle.", "bis": "Kon makakita ka og dako nga lingin libot sa bulan, kini tungod sa gagmay nga kristal sa yelo nga naglutaw sa taas ug nipis nga panganod nga nagbawog sa kahayag sa bulan ngadto sa usa ka singsing."}, "source": "encyclopedia-stable consensus (22° halo)", "generator": "claude-workflow", "reviewed": false},
  {"id": "moon-halo-rain-coming-g5", "domain": "EARTH_SPACE", "topic": "a ring around the moon can mean rain is coming", "grades": [5, 6, 7], "terms": ["halo means rain", "singsing sa buwan ulan", "lingin sa bulan ulan", "tanda ng ulan", "timaan sa ulan", "weather sign", "bakit ulan kapag may bilog ang buwan", "ngano moulan kon adunay lingin ang bulan", "high clouds", "matataas na ulap", "taas nga panganod", "paparating na bagyo", "cirrus", "approaching storm"], "fact": {"tl": "Sinasabi ng matandang kasabihan na kapag may singsing sa paligid ng buwan, malapit na ang ulan — at madalas itong totoo, dahil ang matataas na manipis na ulap na gumagawa ng singsing ay kadalasang nauuna sa paparating na bagyo.", "en": "An old saying tells that a ring around the moon means rain is near — and it is often true, because the high thin clouds that make the ring usually come ahead of an approaching storm.", "bis": "Adunay karaang panultihon nga kon adunay singsing libot sa bulan, hapit na ang ulan — ug kasagaran tinuod kini, kay ang taas ug nipis nga panganod nga naghimo sa singsing kasagaran mag-una sa nagsingabot nga unos."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rainbow-always-opposite-sun-g5", "domain": "EARTH_SPACE", "topic": "a rainbow is always opposite the sun", "grades": [5, 6, 7], "terms": ["rainbow opposite sun", "bahaghari", "balangaw", "bahaghari katapat ng araw", "balangaw atbang sa adlaw", "rainbow", "saan nakikita ang bahaghari", "asa makita ang balangaw", "bakit nasa likod ng araw ang bahaghari", "ngano sa likod sa adlaw", "talikod sa araw", "back to sun", "sun behind you", "raindrops"], "fact": {"tl": "Para makakita ng bahaghari, dapat nasa likod mo ang araw at nasa harap mo ang ulan — kaya laging nasa kasalungat na bahagi ng langit ng araw ang bahaghari, hindi sa tabi nito.", "en": "To see a rainbow, the sun must be behind you and the rain in front of you — so a rainbow always appears on the opposite side of the sky from the sun, never beside it.", "bis": "Aron makakita og balangaw, kinahanglan anaa sa imong likod ang adlaw ug sa imong atubangan ang ulan — busa kanunay anaa sa atbang nga bahin sa langit gikan sa adlaw ang balangaw, dili sa kilid niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rainbow-is-a-circle-g6", "domain": "EARTH_SPACE", "topic": "a rainbow is really a full circle", "grades": [6, 7, 8], "terms": ["rainbow circle", "bahaghari bilog", "balangaw lingin", "buong bilog na bahaghari", "tibuok lingin nga balangaw", "full circle rainbow", "bakit hindi buo ang bahaghari", "ngano dili kompleto ang balangaw", "ground blocks", "natatakpan ng lupa", "natabunan sa yuta", "airplane", "eroplano", "arc"], "fact": {"tl": "Ang bahaghari ay talagang isang buong bilog, ngunit nakikita lang natin ang ibabaw na arko nito dahil hinaharang ng lupa ang ibabang kalahati — mula sa eroplano, minsan kitang-kita ang buong singsing na bahaghari.", "en": "A rainbow is really a full circle, but we usually see only the top arch because the ground blocks the lower half — from an airplane you can sometimes see the whole rainbow ring.", "bis": "Ang balangaw sa tinuod usa ka tibuok lingin, apan kasagaran makita lang nato ang ibabaw nga arko niini kay ang yuta nagsanta sa ubos nga katunga — gikan sa eroplano, usahay makita ang tibuok singsing nga balangaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "double-rainbow-reversed-g7", "domain": "EARTH_SPACE", "topic": "why the second rainbow has reversed colors", "grades": [7, 8, 9], "terms": ["double rainbow", "dobleng bahaghari", "doble nga balangaw", "secondary rainbow", "pangalawang bahaghari", "ikaduhang balangaw", "baligtad ang kulay", "balit-ad ang kolor", "reversed colors", "bakit dalawa ang bahaghari", "ngano duha ang balangaw", "two reflections", "dalawang reflection", "duha ka reflection", "raindrop"], "fact": {"tl": "Kung minsan may pangalawang mas malabong bahaghari sa labas ng una, at baligtad ang pagkakasunod ng kulay nito dahil ang liwanag ay nagsalamin nang dalawang beses sa loob ng bawat patak ng ulan bago lumabas.", "en": "Sometimes a second, fainter rainbow appears outside the first, and its colors run in reverse order because the light reflected twice inside each raindrop before coming out.", "bis": "Usahay adunay ikaduha, mas hanap nga balangaw sa gawas sa una, ug balit-ad ang pagkasunod sa kolor niini kay ang kahayag misalamin og kaduha sulod sa matag tulo sa ulan una migawas."}, "source": "encyclopedia-stable consensus (secondary bow)", "generator": "claude-workflow", "reviewed": false},
  {"id": "fog-just-low-cloud-g5", "domain": "EARTH_SPACE", "topic": "fog is a cloud touching the ground", "grades": [5, 6, 7], "terms": ["fog is a cloud", "ulap sa lupa", "panganod sa yuta", "ambon na makapal", "gabon", "fog", "hamog na makapal", "bakit may makapal na ulap sa bundok", "ngano adunay panganod sa bukid", "mountain fog", "ulap na nasa lupa", "low cloud", "cool air", "Baguio", "tagaytay"], "fact": {"tl": "Ang makapal na ulap na minsan bumababa sa bundok o pumapalibot sa iyo sa malamig na umaga ay isa lang talagang ulap na dumikit sa lupa — pareho ang ginagawa nito, patak ng tubig na lumulutang sa hangin.", "en": "The thick mist that sometimes settles on a mountain or surrounds you on a cold morning is really just a cloud touching the ground — it is made the same way, of water droplets floating in the air.", "bis": "Ang baga nga gabon nga usahay mokunsad sa bukid o molibot kanimo sa bugnaw nga buntag usa lang gyud ka panganod nga midikit sa yuta — pareho ra ang pagkahimo niini, tulo sa tubig nga naglutaw sa hangin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-clouds-white-g4", "domain": "EARTH_SPACE", "topic": "why clouds are white but storm clouds are gray", "grades": [4, 5, 6], "terms": ["why clouds white", "bakit puti ang ulap", "ngano puti ang panganod", "kulay ng ulap", "kolor sa panganod", "maputing ulap", "puti nga panganod", "kulay-abong ulap", "abuhon nga panganod", "gray cloud", "makapal na ulap", "baga nga panganod", "bakit kulay-abo ang ulap ng bagyo", "ngano abuhon ang panganod sa unos", "sunlight blocked"], "fact": {"tl": "Puti ang karamihan ng ulap dahil pinapagliwanag ng araw ang lahat ng kulay sa patak ng tubig; ngunit kapag napakakapal ng ulap, hindi na nakakalusot ang liwanag sa ilalim kaya nagmumukha itong kulay-abo o maitim.", "en": "Most clouds are white because sunlight lights up all the colors in their water droplets; but when a cloud gets very thick, light cannot pass through to the bottom, so it looks gray or dark.", "bis": "Puti ang kadaghanan sa panganod kay ang adlaw nagpasiga sa tanang kolor sa tulo sa tubig niini; apan kon baga na kaayo ang panganod, dili na makalusot ang kahayag sa ubos busa morag abuhon o itom kini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "raindrop-shape-not-teardrop-g6", "domain": "EARTH_SPACE", "topic": "raindrops are not really teardrop-shaped", "grades": [6, 7, 8], "terms": ["raindrop shape", "hugis ng patak ng ulan", "porma sa tulo sa ulan", "patak ng ulan", "tulo sa ulan", "hindi luha", "dili luha", "teardrop", "bilog na patak", "lingin nga tulo", "bakit hindi luha ang hugis ng ulan", "ngano dili morag luha", "flat bottom", "burger shape", "hamburger bun"], "fact": {"tl": "Hindi hugis-luha ang patak ng ulan gaya ng madalas iginuguhit — ang maliliit ay halos bilog, at ang malalaki ay pumapatag sa ilalim na parang munting pandesal habang bumabagsak sa hangin.", "en": "Raindrops are not teardrop-shaped like we often draw them — small ones are nearly round, and big ones flatten on the bottom like a tiny bun as they fall through the air.", "bis": "Ang tulo sa ulan dili morag luha sama sa kasagaran natong gidrowing — ang gagmay halos lingin, ug ang dagko mopatag sa ilawom morag gamay nga pan samtang nahulog sa hangin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lightning-warm-air-rises-g7", "domain": "EARTH_SPACE", "topic": "thunderstorms need rising warm humid air", "grades": [7, 8, 9], "terms": ["thunderstorm forms", "paano nabubuo ang bagyong may kidlat", "unsaon pagporma sa unos", "kidlat", "kilat", "umaakyat na maligamgam na hangin", "nagsaka nga init nga hangin", "humid air", "mahalumigmig", "umido", "bakit may kidlat sa tag-init", "ngano daghan kilat sa init", "afternoon thunderstorm", "convection", "updraft"], "fact": {"tl": "Ang kidlat ay madalas mangyari kapag mainit at mahalumigmig ang araw, dahil ang maligamgam at basang hangin ay mabilis na umaakyat at bumubuo ng napakataas na ulap kung saan nag-iipon ang singil-kuryente.", "en": "Thunderstorms happen most on hot, humid days, because warm moist air rushes upward and builds the very tall clouds inside which electric charge collects.", "bis": "Ang kilat kasagaran mahitabo kon init ug umido ang adlaw, kay ang init ug basa nga hangin paspas nga mosaka ug magtukod og taas kaayo nga panganod diin magpundok ang kuryente."}, "source": "encyclopedia-stable consensus (convective storms)", "generator": "claude-workflow", "reviewed": false},
  {"id": "snow-rare-philippines-g5", "domain": "EARTH_SPACE", "topic": "why it does not snow in the Philippines", "grades": [5, 6, 7], "terms": ["why no snow Philippines", "bakit walang snow sa Pilipinas", "ngano walay snow sa Pilipinas", "niyebe", "yelo nga mahulog", "snow", "walang taglamig", "walay tugnaw nga panahon", "mainit na klima", "init nga klima", "tropical", "frost sa Baguio", "bundok", "bukid", "freezing", "kabugnaw"], "fact": {"tl": "Hindi nag-snow sa Pilipinas dahil mainit ang klima nito buong taon at natutunaw ang yelo bago pa man makarating sa lupa — kahit sa malalamig na bundok tulad ng Baguio, frost lang at hindi tunay na niyebe ang nakikita.", "en": "It does not snow in the Philippines because its climate is warm all year and ice melts before reaching the ground — even on cold mountains like Baguio, people see only frost, not real snow.", "bis": "Wala mag-snow sa Pilipinas kay init ang klima niini tibuok tuig ug matunaw ang yelo una pa kini makaabot sa yuta — bisan sa bugnaw nga bukid sama sa Baguio, frost lang ang makita, dili tinuod nga niyebe."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lightning-sand-fulgurite-g8", "domain": "EARTH_SPACE", "topic": "lightning can fuse sand into glass tubes", "grades": [8, 9, 10], "terms": ["fulgurite", "lightning glass", "kidlat na bumagsak sa buhangin", "kilat sa balas", "kidlat", "kilat", "buhangin na natupok", "balas nga natunaw", "salamin na yelo", "bildo gikan sa balas", "bakit may salamin sa buhangin", "ngano adunay bildo sa balas", "sand to glass", "tubong salamin", "melted sand"], "fact": {"tl": "Kapag tumama ang kidlat sa buhangin, ang sobrang init nito ay maaaring tunawin ang buhangin sa isang iglap at gawing isang tubong-salamin na tinatawag na fulgurite — isang likhang-kidlat na bato.", "en": "When lightning strikes sand, its extreme heat can melt the sand in an instant and fuse it into a glassy tube called a fulgurite — a rock made by lightning.", "bis": "Kon ang kilat motama sa balas, ang grabe nga kainit niini makatunaw sa balas dayon ug mahimong tubo nga bildo nga gitawag og fulgurite — usa ka bato nga hinimo sa kilat."}, "source": "encyclopedia-stable consensus (fulgurite)", "generator": "claude-workflow", "reviewed": false},
  {"id": "clouds-float-warm-air-g5", "domain": "EARTH_SPACE", "topic": "why heavy clouds do not fall down", "grades": [5, 6, 7], "terms": ["why clouds float", "bakit lumulutang ang ulap", "ngano naglutaw ang panganod", "lumulutang", "naglutaw", "ulap", "panganod", "mabigat na ulap", "bug-at nga panganod", "bakit hindi bumabagsak ang ulap", "ngano dili mahulog ang panganod", "tiny droplets", "maliliit na patak", "gagmay nga tulo", "rising air", "umaakyat na hangin", "saka nga hangin"], "fact": {"tl": "Bumabagsak nga ang patak ng tubig sa ulap, pero napakaliliit ng mga ito kaya mabagal silang lumulubog, at madalas itinataas pa sila ng mainit na hanging umaakyat — kaya parang nakalutang lang ang ulap sa langit.", "en": "The water droplets in a cloud are falling, but they are so tiny that they sink very slowly, and rising warm air often pushes them back up — so the cloud seems to just float in the sky.", "bis": "Nahulog gyud ang tulo sa tubig sa panganod, apan gagmay kaayo sila maong hinay sila molunod, ug kasagaran iduso pa sila pataas sa init nga hangin nga nagsaka — busa morag naglutaw lang ang panganod sa langit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "thunder-rumble-vs-crack-g6", "domain": "EARTH_SPACE", "topic": "why thunder sometimes cracks and sometimes rumbles", "grades": [6, 7, 8], "terms": ["thunder rumble crack", "bakit umuugong ang kulog", "ngano modahunog ang dalogdog", "kulog", "dalogdog", "dugdog", "matagal na ugong", "dugay nga dahunog", "biglaang putok", "kalit nga buto", "malayong kidlat", "layo nga kilat", "malapit na kidlat", "duol nga kilat", "distance", "echo"], "fact": {"tl": "Kapag malapit lang ang kidlat, parang malakas na putok ang kulog; pero kapag malayo ang kidlat, ang tunog mula sa iba't ibang bahagi ng mahabang daanan nito ay dumarating sa iba't ibang oras, kaya nagiging matagal na ugong.", "en": "When lightning is close, thunder sounds like a sharp crack; but when it is far, the sound from different parts of the long bolt arrives at different times, so it becomes a long rumble.", "bis": "Kon duol ra ang kilat, morag kusog nga buto ang dalogdog; apan kon layo ang kilat, ang tingog gikan sa lainlaing bahin sa taas niini nga agianan moabot sa lainlaing oras, busa mahimong taas nga dahunog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mammatus-pouch-clouds-g7", "domain": "EARTH_SPACE", "topic": "the pouch-like clouds that hang under a storm", "grades": [7, 8, 9], "terms": ["mammatus", "pouch clouds", "ulap na parang bilog na bumbilya", "panganod nga morag bukol", "nakalawit na ulap", "nagbitay nga panganod", "bakit may bukol-bukol na ulap", "ngano adunay bukol-bukol nga panganod", "under thunderstorm", "ilalim ng bagyo", "ilawom sa unos", "sinking air", "bumababang hangin", "nagkanaog nga hangin", "lumpy underside"], "fact": {"tl": "Pagkatapos ng malakas na bagyo, minsan may makikitang mga bilog-bilog na parang nakalawit na supot sa ilalim ng ulap (mammatus) — nabubuo ito kapag may malamig na hanging bumababa sa ilalim ng ulap sa hugis-bukol.", "en": "After a strong storm, you can sometimes see round, pouch-like bulges hanging under the cloud (mammatus) — they form when cool air sinks down from the cloud's underside in lumpy pockets.", "bis": "Human sa kusog nga unos, usahay makakita ka og lingin, morag nagbitay nga bukol sa ilawom sa panganod (mammatus) — moporma kini kon ang bugnaw nga hangin mokanaog gikan sa ilawom sa panganod sa bukol-bukol nga porma."}, "source": "encyclopedia-stable consensus (mammatus clouds)", "generator": "claude-workflow", "reviewed": false},
  {"id": "petrichor-rain-smell-g6", "domain": "EARTH_SPACE", "topic": "why rain has a special smell", "grades": [6, 7, 8], "terms": ["petrichor", "rain smell", "amoy ng ulan", "baho sa ulan", "amoy ng lupa kapag umuulan", "kahumot sa yuta kon mag-ulan", "bakit may amoy ang unang ulan", "ngano adunay baho ang unang ulan", "first rain", "tuyong lupa", "uga nga yuta", "geosmin", "bacteria", "soil"], "fact": {"tl": "Ang sariwang amoy kapag tumama ang unang ulan sa tuyong lupa ay galing sa mga sangkap na ginawa ng bakterya sa lupa na napapakawalan sa hangin ng mga patak ng ulan — tinatawag itong petrichor.", "en": "The fresh smell when the first rain hits dry ground comes from chemicals made by soil bacteria that the raindrops release into the air — this scent is called petrichor.", "bis": "Ang presko nga baho kon ang unang ulan motama sa uga nga yuta naggikan sa mga kemikal nga gihimo sa bakterya sa yuta nga gibuhian sa tulo sa ulan ngadto sa hangin — gitawag kini og petrichor."}, "source": "encyclopedia-stable consensus (petrichor / geosmin)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sundog-bright-spots-g7", "domain": "EARTH_SPACE", "topic": "the bright spots that appear beside the sun", "grades": [7, 8, 9], "terms": ["sun dog", "sundog", "parhelion", "maliwanag na puntos sa tabi ng araw", "hayag nga puntos sa kilid sa adlaw", "dalawang araw", "duha ka adlaw", "bakit may dalawang araw", "ngano morag duha ang adlaw", "ice crystals", "kristal ng yelo", "kristal sa yelo", "cirrus", "mataas na ulap", "taas nga panganod", "false sun", "refraction"], "fact": {"tl": "Minsan may makikitang maliliwanag na puntos sa magkabilang tabi ng araw na parang dalawa pang araw — tinatawag itong sun dog, at gawa rin ito ng kristal ng yelo sa matataas na ulap na bumabaluktot sa sikat ng araw.", "en": "Sometimes you can see bright spots on each side of the sun that look like extra suns — these are called sun dogs, and they too are made by ice crystals in high clouds bending the sunlight.", "bis": "Usahay makakita ka og hayag nga puntos sa duha ka kilid sa adlaw nga morag dugang nga mga adlaw — gitawag kini og sun dog, ug hinimo usab kini sa kristal sa yelo sa taas nga panganod nga nagbawog sa silaw sa adlaw."}, "source": "encyclopedia-stable consensus (parhelion)", "generator": "claude-workflow", "reviewed": false},
  {"id": "ball-of-water-cloud-droplet-count-g7", "domain": "EARTH_SPACE", "topic": "a million tiny cloud droplets make one raindrop", "grades": [7, 8, 9], "terms": ["raindrop from cloud droplets", "milyong patak", "milyon ka tulo", "isang patak ng ulan", "usa ka tulo sa ulan", "maliliit na patak ng ulap", "gagmay nga tulo sa panganod", "bakit matagal bago umulan", "ngano dugay una mag-ulan", "collision", "nagsama-sama", "naghiusa", "grow heavy", "million droplets"], "fact": {"tl": "Ang patak ng tubig sa ulap ay napakaliit — kailangan ng halos isang milyon sa kanila na magsama-sama para makabuo ng isang patak ng ulan na sapat ang bigat para bumagsak, kaya may panahong naghihintay bago pa umulan.", "en": "Cloud droplets are so tiny that roughly a million of them must merge together to form a single raindrop heavy enough to fall, which is why a cloud can wait a while before it rains.", "bis": "Ang tulo sa tubig sa panganod gamay kaayo — gikinahanglan ang halos usa ka milyon kanila nga maghiusa aron makahimo og usa ka tulo sa ulan nga igo kabug-at aron mahulog, maong adunay panahon nga maghulat una mag-ulan."}, "source": "encyclopedia-stable consensus (cloud vs rain droplet size)", "generator": "claude-workflow", "reviewed": false},
  {"id": "solar-cell-silicon-knocks-electrons-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "how a solar cell makes electricity", "grades": [7, 8, 9], "terms": ["solar cell", "silicon", "silikon", "photovoltaic", "photovoltaic effect", "electron", "elektron", "sunlight", "sikat ng araw", "liwanag ng araw", "kuryente", "koryente", "photon", "tumatama", "ginabuy-od", "nagagalaw na elektron"], "fact": {"tl": "Sa loob ng solar cell ay may manipis na silikon; kapag tumama ang liwanag ng araw, naitutulak nito ang maliliit na elektron para gumalaw, at ang gumagalaw na elektron na iyon ang nagiging kuryente.", "en": "Inside a solar cell is a thin layer of silicon; when sunlight hits it, it knocks tiny electrons loose so they move, and that flow of moving electrons is the electricity.", "bis": "Sulod sa solar cell adunay nipis nga silikon; kon maigo sa kahayag sa adlaw, ibuy-od niini ang gagmay nga mga elektron aron molihok, ug kanang naglihok nga mga elektron mao ang koryente."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "solar-panel-blue-black-color-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "why solar panels are dark", "grades": [5, 6, 7], "terms": ["solar panel", "dark", "itim", "asul", "maitim", "ngitngit", "absorb", "sumisipsip", "nagsipsip", "sunlight", "sikat ng araw", "kahayag sa adlaw", "color", "kulay", "kolor", "reflect", "mga panel"], "fact": {"tl": "Madilim (asul o itim) ang kulay ng solar panel para mas marami itong masipsip na liwanag ng araw; ang maputi o makintab na ibabaw ay magtatabi lang ng liwanag at maliit ang makukuhang enerhiya.", "en": "Solar panels are dark blue or black so they absorb as much sunlight as possible; a white or shiny surface would bounce the light away and collect far less energy.", "bis": "Ngitngit (asul o itom) ang kolor sa solar panel aron mas daghan nga kahayag sa adlaw ang masuyop niini; ang puti o sinaw nga nawong mobalibad lang sa kahayag ug gamay ra og makuha nga enerhiya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wind-turbine-three-blades-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "why wind turbines have three blades", "grades": [6, 7, 8], "terms": ["wind turbine", "tatlong blade", "tres ka pako", "three blades", "pako", "blades", "balance", "balanse", "timbang", "stable", "spin", "umiikot", "nagatuyok", "wind", "hangin", "generator", "mga pala"], "fact": {"tl": "Karaniwang tatlong pako lang ang wind turbine dahil iyon na ang pinakamatatag at panatag na bilang na umiikot nang pantay-pantay; mas maraming pako ay mas mabigat at mas magastos nang hindi gaanong nadaragdag ang enerhiya.", "en": "Most wind turbines have just three blades because three spins smoothly and stays balanced; adding more blades makes the turbine heavier and costlier without catching much more energy.", "bis": "Kasagaran tulo ra ka pako ang wind turbine kay kana na ang labing lig-on ug timbang nga gidaghanon nga motuyok nga patas; ang mas daghang pako mas bug-at ug mas mahal nga dili kaayo modugang sa enerhiya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wind-turbine-blade-tips-fast-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "how fast wind turbine blade tips move", "grades": [7, 8, 9], "terms": ["wind turbine", "blade tip", "dulo ng pako", "tumoy sa pako", "fast", "mabilis", "paspas", "tip speed", "bilis", "spin", "umiikot", "nagatuyok", "long blade", "mahaba", "kilometro", "oras"], "fact": {"tl": "Kahit mukhang mabagal umikot ang malalaking wind turbine, ang dulo ng mahabang pako ay maaaring kumilos nang mas mabilis pa sa kotse sa highway dahil malayo ang nilalakbay nito sa bawat pag-ikot.", "en": "Even though big wind turbines look like they turn slowly, the tip of a long blade can move faster than a car on the highway, because it travels a huge distance with every rotation.", "bis": "Bisan og morag hinay motuyok ang dagkong wind turbine, ang tumoy sa taas nga pako mahimong molihok nga mas paspas pa sa sakyanan sa highway tungod kay layo kaayo ang gibiyahe niini matag tuyok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wind-too-strong-shutdown-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "turbines stop in very strong wind", "grades": [6, 7, 8], "terms": ["wind turbine", "masyadong malakas", "kusog kaayo", "too strong", "bagyo", "unos", "storm", "hangin", "shut down", "huminto", "mihunong", "tumigil", "brake", "preno", "damage", "masira", "madaot", "ligtas", "awtomatikong nagsasara"], "fact": {"tl": "Kapag sobrang lakas ng hangin tulad sa bagyo, awtomatikong huminto at nagpepreno ang wind turbine para hindi masira; kaya may hangang lakas lang ng hangin na puwede nitong gamitin.", "en": "When the wind is too strong, like in a storm, a wind turbine automatically stops and brakes itself so it isn't damaged, so there is an upper wind speed it can safely use.", "bis": "Kon kusog kaayo ang hangin sama sa bagyo, awtomatikong mohunong ug mopreno ang wind turbine aron dili madaot, mao nga adunay kinatas-ang kakusog sa hangin nga mahimo niini gamiton nga luwas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hydro-dam-stored-energy-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "a dam stores energy as a giant battery", "grades": [6, 7, 8], "terms": ["dam", "presa", "reservoir", "imbak na tubig", "gitipigan nga tubig", "stored energy", "nakaimbak na enerhiya", "battery", "baterya", "high", "mataas", "habog", "gravity", "grabidad", "falling water", "tubig na bumabagsak", "potential energy", "nakaipon nga enerhiya"], "fact": {"tl": "Ang tubig na nakaimbak sa likod ng mataas na dam ay parang malaking baterya: hangga't naka-angat ito, may nakatagong enerhiya, at lumalabas ang enerhiyang iyon kapag pinababagsak ang tubig sa turbine.", "en": "The water held high behind a dam is like a giant battery: as long as it stays up high it stores energy, and that energy is released when the water is let fall onto the turbine.", "bis": "Ang tubig nga natipigan sa luyo sa habog nga dam sama sa dakong baterya: samtang taas pa kini, adunay tinago nga enerhiya, ug mogawas kana nga enerhiya kon pasagdan nga mahulog ang tubig sa turbine."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pumped-storage-uphill-water-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "pumping water uphill to store electricity", "grades": [8, 9, 10], "terms": ["pumped storage", "pumped hydro", "ibinabalik pataas", "gibalik pataas", "pump uphill", "ibomba", "store electricity", "imbak ng kuryente", "tipigan ang koryente", "sobrang kuryente", "extra electricity", "release", "pababain", "ipaubos", "giant battery", "baterya sa tubig"], "fact": {"tl": "Sa pumped storage, kapag sobra ang kuryente ay ginagamit ito para itulak pabalik pataas ang tubig sa mataas na imbakan, at kapag kulang ang kuryente ay pinababagsak muli ang tubig para gumawa ng kuryente — parang bateryang tubig.", "en": "In pumped storage, when there is extra electricity it is used to pump water back uphill into a high reservoir, and when electricity is short the water is released again to make power — like a water battery.", "bis": "Sa pumped storage, kon sobra ang koryente gigamit kini aron iduso pabalik paitaas ang tubig sa habog nga tipiganan, ug kon kulang ang koryente pasagdan na usab nga mahulog ang tubig aron mohimo og koryente — sama sa baterya nga tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "geothermal-volcano-free-heat-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "geothermal taps volcano heat without erupting", "grades": [6, 7, 8], "terms": ["geothermal", "init sa yuta", "init sa ilalom", "earth heat", "bulkan", "volcano", "mainit na bato", "hot rock", "without eruption", "steam", "singaw", "alisngaw", "well", "drill", "binabarena", "kuryente", "Pilipinas"], "fact": {"tl": "Sa geothermal power, binabarena ng mga tao ang lupa malapit sa mainit na bato ng bulkan at kinukuha ang init nito para magpaalisngaw ng tubig — kaya nakakakuha tayo ng kuryente mula sa bulkan nang hindi ito sumasabog.", "en": "In geothermal power, people drill into the ground near a volcano's hot rock and tap its heat to boil water into steam, so we get electricity from a volcano without it ever erupting.", "bis": "Sa geothermal power, ginabarena sa mga tawo ang yuta duol sa init nga bato sa bulkan ug ginakuha ang init niini aron pabukalon ang tubig ngadto sa alisngaw, mao nga makakuha tag koryente gikan sa bulkan nga dili kini mobuto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "geothermal-runs-day-night-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "geothermal works around the clock", "grades": [6, 7, 8], "terms": ["geothermal", "araw at gabi", "adlaw ug gabii", "day and night", "walang tigil", "walay hunong", "steady", "tuloy-tuloy", "init sa ilalom", "underground heat", "reliable", "maaasahan", "kasaligan", "kuryente"], "fact": {"tl": "Hindi tulad ng solar na nangangailangan ng araw o wind na nangangailangan ng hangin, ang geothermal ay gumagana araw-gabi at sa anumang panahon dahil ang init sa ilalim ng lupa ay palaging naroon.", "en": "Unlike solar power that needs the sun or wind power that needs wind, geothermal works day and night in any weather, because the heat deep underground is always there.", "bis": "Dili sama sa solar nga nagkinahanglan og adlaw o wind nga nagkinahanglan og hangin, ang geothermal molihok adlaw ug gabii sa bisan unsang panahon kay ang init sa ilalom sa yuta kanunay nga anaa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "philippines-geothermal-rank-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "Philippines is among the top geothermal producers", "grades": [6, 7, 8], "terms": ["Pilipinas", "Philippines", "geothermal", "init sa yuta", "top producer", "pinakamalaki", "usa sa pinakadako", "Ring of Fire", "Singsing ng Apoy", "Singsing sa Kalayo", "bulkan", "volcano", "maraming bulkan", "kuryente", "enerhiya"], "fact": {"tl": "Dahil nasa Ring of Fire ang Pilipinas at puno ito ng mga bulkan, ito ay isa sa mga bansang may pinakamaraming geothermal na kuryente sa buong mundo.", "en": "Because the Philippines sits on the Ring of Fire and is full of volcanoes, it is one of the countries that produces the most geothermal electricity in the whole world.", "bis": "Tungod kay ang Pilipinas naa sa Singsing sa Kalayo ug puno kini sa mga bulkan, usa kini sa mga nasud nga labing daghan og geothermal nga koryente sa tibuok kalibutan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tidal-energy-moon-pull-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "tidal energy comes from the Moon", "grades": [6, 7, 8], "terms": ["tidal energy", "enerhiya ng tubig-dagat", "kusog sa taob", "tide", "taob", "kati", "moon", "buwan", "bulan", "gravity", "grabidad", "hila ng buwan", "pull", "rise and fall", "taas-baba ng tubig", "predictable", "tubig-dagat", "kuryente"], "fact": {"tl": "Ang enerhiyang tidal ay galing talaga sa buwan: ang hila ng grabidad ng buwan ang nagpapataas at nagpapababa ng tubig-dagat, at ang paggalaw na iyon ng dagat ang puwedeng gawing kuryente.", "en": "Tidal energy really comes from the Moon: the pull of the Moon's gravity makes the sea rise and fall, and that movement of the ocean can be turned into electricity.", "bis": "Ang tidal nga enerhiya gikan gyud sa bulan: ang pagbira sa grabidad sa bulan maoy hinungdan sa pagtaob ug paghunas sa dagat, ug kanang paglihok sa dagat mahimong himoong koryente."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tidal-predictable-advantage-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "tides are predictable years ahead", "grades": [7, 8, 9], "terms": ["tidal energy", "taob", "kati", "tide", "predictable", "matatantya", "matagna", "mahibal-an daan", "years ahead", "taon nang maaga", "mga tuig nang daan", "reliable", "maaasahan", "kasaligan", "kuryente"], "fact": {"tl": "Isang malaking bentahe ng tidal energy ay matatantya nang ilang taon nang maaga kung kailan tataas at bababa ang tubig, kaya alam na nila kung kailan darating ang kuryente — hindi tulad ng hangin na pabigla-bigla.", "en": "A big advantage of tidal energy is that the rise and fall of the sea can be predicted years in advance, so we know exactly when the power will come — unlike wind, which is unpredictable.", "bis": "Usa ka dakong bentaha sa tidal nga enerhiya mao nga matagna pila ka tuig nang daan kanus-a motaob ug mohunas ang dagat, mao nga nahibal-an na kanus-a moabot ang koryente — dili sama sa hangin nga kalit-kalit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "biomass-stored-sunlight-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "biomass is stored sunlight", "grades": [6, 7, 8], "terms": ["biomass", "biomasa", "kahoy", "wood", "dayami", "rice straw", "uhay", "photosynthesis", "potosintesis", "sikat ng araw", "kahayag sa adlaw", "stored sunlight", "halaman", "plants", "tanom", "burn", "sinunog", "gisunog", "enerhiya"], "fact": {"tl": "Ang biomass tulad ng kahoy at dayami ay parang nakaimbak na sikat ng araw, dahil kinuha muna ng halaman ang enerhiya ng araw sa pamamagitan ng potosintesis bago natin ito sunugin para sa init.", "en": "Biomass like wood and rice straw is really stored sunlight, because the plants first captured the Sun's energy through photosynthesis before we burn it for heat.", "bis": "Ang biomass sama sa kahoy ug dayami sama sa natipigan nga kahayag sa adlaw, kay ang tanom nag-una pagkuha sa enerhiya sa adlaw pinaagi sa potosintesis una nato kini sunogon alang sa init."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "biogas-rotting-waste-fuel-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "making cooking gas from waste", "grades": [6, 7, 8], "terms": ["biogas", "gas mula sa dumi", "gas gikan sa hugaw", "animal waste", "dumi ng hayop", "hugaw sa hayop", "bacteria", "bakterya", "walang hangin", "without air", "walay hangin", "methane", "metano", "cooking fuel", "panggatong", "sugnod sa pagluto", "digester"], "fact": {"tl": "Sa biogas, ang mga bakterya ay kumakain ng dumi ng hayop sa loob ng saradong lalagyan na walang hangin, at habang nabubulok ito ay naglalabas ng gas na puwedeng gamiting panggatong sa pagluluto.", "en": "In biogas, bacteria feed on animal waste inside a sealed container with no air, and as it rots it gives off a gas that can be used as cooking fuel.", "bis": "Sa biogas, ang mga bakterya mokaon sa hugaw sa hayop sulod sa sirado nga sudlanan nga walay hangin, ug samtang madunot kini mogawas og gas nga magamit nga sugnod sa pagluto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "renewable-no-fuel-cost-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "sun and wind are free fuel", "grades": [6, 7, 8], "terms": ["renewable", "libreng gatong", "libre nga sugnod", "free fuel", "sun", "araw", "adlaw", "wind", "hangin", "coal", "uling", "krudo", "oil", "cost", "gugol", "solar", "wind power"], "fact": {"tl": "Hindi tulad ng planta na kailangang bumili ng uling o krudo araw-araw, ang araw at hangin ay libre at laging dumarating, kaya wala nang binibiling gatong ang solar at wind power kapag naitayo na.", "en": "Unlike a power plant that must buy coal or oil every day, the sun and wind are free and keep arriving on their own, so solar and wind power buy no fuel once they are built.", "bis": "Dili sama sa planta nga kinahanglang mopalit og uling o krudo matag adlaw, ang adlaw ug hangin libre ug kanunayng moabot sa ilang kaugalingon, mao nga ang solar ug wind power wala nay paliton nga sugnod kon matukod na."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-renewables-no-co2-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "why renewables don't warm the planet", "grades": [7, 8, 9], "terms": ["renewable", "walang sinusunog", "walay sunog", "no burning", "carbon dioxide", "CO2", "greenhouse", "greenhouse gas", "climate", "klima", "global warming", "init sa kalibutan", "solar", "wind", "geothermal", "coal", "uling", "fossil fuel", "walang usok"], "fact": {"tl": "Hindi nakapagpapainit ng mundo ang solar, wind, at hydro dahil hindi sila nagsusunog ng anuman, kaya walang carbon dioxide na lumalabas — iba sa uling at krudo na naglalabas nito kapag sinunog.", "en": "Solar, wind, and hydro do not warm the planet because they burn nothing, so no carbon dioxide is released — unlike coal and oil, which give off this gas when burned.", "bis": "Ang solar, wind, ug hydro dili makapainit sa kalibutan kay wala silay sunogon, mao nga walay carbon dioxide nga mogawas — lahi sa uling ug krudo nga mogawas niini kon sunogon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "solar-panel-cooler-better-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "solar panels work worse when too hot", "grades": [8, 9, 10], "terms": ["solar panel", "sobrang init", "init kaayo", "too hot", "mainit", "kuryente", "koryente", "efficiency", "kahusay", "bumababa", "mokunhod", "cool", "malamig", "bugnaw", "temperature", "temperatura", "cooler day", "mas mahusay sa malamig"], "fact": {"tl": "Nakakagulat na bumababa ang husay ng solar panel kapag sobrang init nito; kaya mas marami pang kuryente ang nagagawa nito sa maaraw pero malamig na araw kaysa sa sobrang init na tanghali.", "en": "Surprisingly, a solar panel works less well when it gets too hot; so it can actually make more electricity on a sunny but cool day than at a scorching hot noon.", "bis": "Makapakurat nga mokunhod ang kahusay sa solar panel kon init kaayo kini; mao nga mas daghan pa kini og koryente nga mahimo sa maadlawng apan bugnaw nga adlaw kay sa init kaayo nga udto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "geothermal-water-reinjected-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "geothermal water is sent back underground", "grades": [8, 9, 10], "terms": ["geothermal", "tubig", "reinjected", "ibinabalik sa lupa", "ibalik sa yuta", "sent back", "well", "balon", "reuse", "ginagamit muli", "gigamit usab", "steam", "singaw", "alisngaw", "reheated", "painiton pag-usab", "sustainable", "hindi nauubos", "dili mahurot"], "fact": {"tl": "Pagkatapos gamitin ang singaw nito, ang tubig sa geothermal plant ay ibinabalik pabalik sa ilalim ng lupa para muling painiton ng mga bato — kaya paikot-ikot lang ito at hindi madaling maubos.", "en": "After its steam is used, the water in a geothermal plant is pumped back down underground to be reheated by the hot rocks — so it keeps cycling and does not easily run out.", "bis": "Human magamit ang alisngaw niini, ang tubig sa geothermal plant ibalik pabalik sa ilalom sa yuta aron painiton pag-usab sa init nga mga bato — mao nga magtuyok-tuyok lang kini ug dili dali mahurot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hydro-largest-renewable-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "hydropower is the biggest renewable", "grades": [8, 9, 10], "terms": ["hydroelectric", "hydropower", "tubig na umaagos", "nagdagayday nga tubig", "largest renewable", "pinakamalaking renewable", "labing dako nga renewable", "dam", "presa", "oldest", "pinakamatanda", "karaang", "worldwide", "sa buong mundo", "sa tibuok kalibutan", "flowing water", "kuryente"], "fact": {"tl": "Sa lahat ng renewable na pagkukunan ng kuryente sa buong mundo, ang hydroelectric mula sa umaagos na tubig ang pinakamarami at isa sa pinakaluma, dahil matagal nang ginagamit ng tao ang lakas ng tubig.", "en": "Of all the renewable sources of electricity in the world, hydroelectric power from flowing water makes the most and is one of the oldest, because people have harnessed the force of water for a very long time.", "bis": "Sa tanang renewable nga tinubdan sa koryente sa tibuok kalibutan, ang hydroelectric gikan sa nagdagayday nga tubig ang labing daghan ug usa sa labing karaan, kay dugay na nga gigamit sa tawo ang kusog sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "offshore-wind-stronger-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "why wind farms are built at sea", "grades": [7, 8, 9], "terms": ["offshore wind", "wind farm sa dagat", "at sea", "sa dagat", "sa kadagatan", "stronger wind", "mas malakas na hangin", "mas kusog nga hangin", "steady", "tuloy-tuloy", "kanunay", "no obstacles", "walang harang", "walay babag", "buildings", "gusali", "bundok", "mountains"], "fact": {"tl": "Maraming wind farm ang itinatayo sa dagat dahil mas malakas at mas tuloy-tuloy doon ang hangin, na walang gusali o bundok na humaharang dito kaya mas maraming kuryente ang nagagawa.", "en": "Many wind farms are built out at sea because the wind there is stronger and steadier, with no buildings or hills to block it, so the turbines make more electricity.", "bis": "Daghang wind farm ang gitukod sa dagat tungod kay mas kusog ug mas kanunay didto ang hangin, nga walay mga building o bukid nga makababag, mao nga mas daghang koryente ang mahimo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "grid-needs-storage-intermittent-g9", "domain": "FORCE_MOTION_ENERGY", "topic": "storing renewable power for later", "grades": [9, 10], "terms": ["renewable", "sun stops", "walang araw sa gabi", "wala nay adlaw sa gabii", "wind stops", "tumitigil ang hangin", "mohunong ang hangin", "battery", "baterya", "storage", "tipiganan", "store", "itago", "tipigan", "night", "gabi", "intermittent", "pabugso-bugso"], "fact": {"tl": "Dahil paminsan-minsan lang sumisikat ang araw at humihihip ang hangin, kailangan ng malalaking baterya o ibang paraan para itago ang sobrang kuryente para magamit kapag gabi o walang hangin.", "en": "Because the sun and wind come and go, large batteries or other storage are needed to save the extra electricity so it can be used at night or when the wind is still.", "bis": "Tungod kay usahay ra mosidlak ang adlaw ug mohuyop ang hangin, gikinahanglan ang dagkong baterya o laing paagi aron itipig ang sobrang koryente aron magamit sa gabii o kon walay hangin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "renewable-needs-much-land-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "why solar and wind need lots of space", "grades": [8, 9, 10], "terms": ["solar farm", "wind farm", "malaking lupa", "dakong yuta", "much land", "lupa", "land", "yuta", "spread out", "nakakalat", "nagkatag", "sunlight", "sikat ng araw", "kahayag", "maraming panel", "daghang panel", "space", "puwang"], "fact": {"tl": "Kailangan ng solar at wind farm ng napakalaking lupa dahil maluwag na nakakalat ang sikat ng araw at hangin, kaya kailangan ng maraming panel o malalaking turbine para makaipon ng sapat na enerhiya.", "en": "Solar and wind farms need a lot of land because sunlight and wind are spread out thinly, so many panels or large turbines are needed to gather enough energy.", "bis": "Ang solar ug wind farm nagkinahanglan og dakong yuta tungod kay ang kahayag sa adlaw ug hangin nagkatag og nipis, mao nga daghang panel o dagkong turbine ang gikinahanglan aron makatigom og igong enerhiya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "all-electricity-spinning-magnet-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "most power plants spin a magnet in coils", "grades": [8, 9, 10], "terms": ["generator", "spinning magnet", "umiikot na magnet", "nagatuyok nga magnet", "coil", "kawad", "alambre", "liko", "turbine", "magnet", "kuryente", "koryente", "steam", "singaw", "wind", "tubig", "geothermal", "coal", "same idea", "ang solar lamang"], "fact": {"tl": "Halos lahat ng power plant — gamit man ng singaw, tubig, hangin, o init ng lupa — ay gumagawa ng kuryente sa parehong paraan: pinaiikot ang isang malaking magnet sa loob ng mga kawad; ang solar panel lang ang naiiba.", "en": "Almost every power plant — whether it uses steam, water, wind, or earth's heat — makes electricity the same way: by spinning a big magnet inside coils of wire; only solar panels are different.", "bis": "Halos tanang power plant — magamit man og alisngaw, tubig, hangin, o init sa yuta — naghimo og koryente sa parehas nga paagi: gipatuyok ang dakong magnet sulod sa mga liko sa alambre; ang solar panel ra ang lahi."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "solar-panels-on-water-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "floating solar panels on reservoirs", "grades": [7, 8, 9], "terms": ["floating solar", "lumulutang na solar", "naglutaw nga solar", "panel sa tubig", "reservoir", "lawa", "lake", "imbakan", "saves land", "nakatipid sa lupa", "makadaginot og yuta", "cooler", "mas malamig", "mas bugnaw", "less evaporation", "mokunhod ang singaw", "tubig", "floating panels"], "fact": {"tl": "May mga solar panel na inilulutang sa ibabaw ng lawa o imbakan ng tubig; nakakatipid ito ng lupa, at ang malamig na tubig sa ilalim ay tumutulong pang panatilihing malamig at mas mahusay ang mga panel.", "en": "Some solar panels are floated on top of lakes or reservoirs; this saves land, and the cool water underneath helps keep the panels cooler and working better.", "bis": "Adunay mga solar panel nga gipalutaw sa ibabaw sa lanaw o tipiganan sa tubig; makadaginot kini og yuta, ug ang bugnaw nga tubig sa ilalom motabang aron magpabugnaw ug mas mohusay ang mga panel."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hydro-fish-ladder-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "dams can block fish and need fish ladders", "grades": [6, 7, 8], "terms": ["dam", "presa", "fish ladder", "hagdan ng isda", "hagdanan sa isda", "isda", "fish", "blocks", "humaharang", "gibabagan", "ilog", "river", "suba", "swim upstream", "langoy paahon", "steps", "baitang", "environment", "kalikasan", "kinaiyahan"], "fact": {"tl": "Bagama't malinis ang enerhiya ng dam, hinahadlangan nito ang mga isda na lumangoy pataas sa ilog, kaya minsan gumagawa ng \"hagdan ng isda\" — mga baitang ng tubig na puwedeng akyatin ng isda.", "en": "Even though a dam makes clean energy, it can block fish from swimming up the river, so people sometimes build a \"fish ladder\" — steps of water the fish can climb past it.", "bis": "Bisan og limpyo ang enerhiya sa dam, makababag kini sa mga isda nga molangoy paahon sa suba, mao nga usahay maghimo og \"hagdan sa isda\" — mga ang-ang sa tubig nga masakahan sa isda."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "geothermal-warms-buildings-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "earth heat can warm buildings directly", "grades": [7, 8, 9], "terms": ["geothermal", "init sa yuta", "direct heat", "direktang init", "direkta nga init", "heat buildings", "painit ng gusali", "painiton ang building", "hot spring", "mainit na bukal", "init nga tuburan", "not only electricity", "hindi laging kuryente", "greenhouse", "spa", "paliguan", "warming"], "fact": {"tl": "Hindi laging kuryente ang gawa sa init ng lupa; sa ibang lugar ay direktang ginagamit ang mainit na tubig sa ilalim para painitin ang mga gusali, greenhouse, o paliguan nang hindi muna ginagawang kuryente.", "en": "Earth's heat is not always turned into electricity; in some places the hot underground water is used directly to warm buildings, greenhouses, or baths without first making power.", "bis": "Dili kanunay koryente ang himoon gikan sa init sa yuta; sa ubang dapit ang init nga tubig sa ilalom direktang gigamit aron painiton ang mga building, greenhouse, o paliguanan nga dili una himoong koryente."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wave-energy-vs-tidal-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "wave energy comes from wind on the sea", "grades": [8, 9, 10], "terms": ["wave energy", "enerhiya ng alon", "enerhiya sa balod", "alon", "waves", "balod", "hangin sa dagat", "wind on sea", "not tides", "iba sa taob", "lahi sa taob", "up and down", "taas-baba", "saka-kanaog", "ocean", "dagat", "kadagatan", "kuryente"], "fact": {"tl": "Iba ang wave energy sa tidal energy: ang wave energy ay galing sa mga alon na ginagawa ng hangin sa ibabaw ng dagat, at ang taas-baba ng tubig sa bawat alon ang ginagawang kuryente.", "en": "Wave energy is different from tidal energy: wave energy comes from the waves that wind makes on the sea's surface, and the up-and-down bobbing of each wave is turned into electricity.", "bis": "Lahi ang wave energy sa tidal energy: ang wave energy gikan sa mga balod nga himoon sa hangin sa ibabaw sa dagat, ug ang saka-kanaog sa tubig sa matag balod maoy himoong koryente."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-powers-wind-and-rain-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "the sun secretly drives wind and hydro too", "grades": [8, 9, 10], "terms": ["araw", "sun", "adlaw", "wind", "hangin", "rain", "ulan", "init ng araw", "sun's heat", "init sa adlaw", "evaporation", "singaw", "alisngaw", "ulap", "clouds", "tubig", "cycle", "ultimately solar"], "fact": {"tl": "Halos lahat ng renewable ay galing pala sa araw: ang init nito ang gumagawa ng hangin para sa wind power at nagpapasingaw ng tubig na bumabalik bilang ulan na pumupuno sa mga dam.", "en": "Almost all renewable energy secretly comes from the sun: its heat stirs up the wind for wind power and evaporates water that returns as rain to fill the dams.", "bis": "Halos tanang renewable nga enerhiya tinago nga gikan sa adlaw: ang init niini maoy nagahimo sa hangin para sa wind power ug nagpaalisngaw sa tubig nga mobalik isip ulan nga mopuno sa mga dam."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "solar-cookers-no-electricity-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "cooking with sunlight using mirrors", "grades": [5, 6, 7], "terms": ["solar cooker", "solar oven", "lutong-araw", "luto gamit ang adlaw", "salamin", "mirror", "focus sunlight", "tinipon na liwanag", "gitapok nga kahayag", "init", "heat", "walang kuryente", "no electricity", "walay koryente", "no fuel", "walang gatong", "cook", "pagluto"], "fact": {"tl": "Puwedeng magluto gamit lang ang araw: tinitipon ng makintab na salamin ang sikat ng araw sa isang lugar para uminit ito nang sobra, kaya nakakapagluto ng pagkain nang walang kuryente o panggatong.", "en": "You can cook using just the sun: shiny mirrors gather sunlight onto one spot so it gets very hot, letting you cook food with no electricity or fuel at all.", "bis": "Mahimo kang magluto gamit ra ang adlaw: ang sinaw nga salamin motapok sa kahayag sa adlaw sa usa ka dapit aron mainit kaayo kini, busa makaluto kag pagkaon nga walay koryente o sugnod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "microplastics-tiny-pieces-g5", "domain": "EARTH_SPACE", "topic": "microplastics", "grades": [5, 6, 7], "terms": ["microplastic", "microplastics", "mikroplastik", "maliliit", "gagmay", "tipik", "piraso", "tipak", "plastik", "pino", "mas maliit", "gamay", "buhok", "particles", "pang-mata", "invisible", "nadudurog"], "fact": {"tl": "Kapag nadudurog ang plastik, hindi ito tuluyang nawawala — nagiging napakaliliit na piraso na tinatawag na microplastics, na minsan ay mas maliit pa sa isang buhok.", "en": "When plastic breaks apart it does not truly disappear — it turns into tiny pieces called microplastics, sometimes smaller than a strand of hair.", "bis": "Kung madugmok ang plastik, dili kini tinuod nga mawala — mahimo kining gagmay kaayong tipik nga gitawag og microplastics, usahay mas gamay pa sa usa ka lugas sa buhok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "microplastics-in-rain-and-food-g6", "domain": "EARTH_SPACE", "topic": "microplastics spread everywhere", "grades": [6, 7, 8], "terms": ["microplastics", "mikroplastik", "ulan", "tubig", "kinakain", "gikaon", "asin", "table salt", "kahit saan", "bisan asa", "nakalat", "nakatag", "natutunton", "hangin", "snow", "everywhere", "layo", "Antarctica"], "fact": {"tl": "Natagpuan na ang microplastics kahit saan — sa tubig-ulan, sa asin sa mesa, at maging sa pinakamalalim na karagatan — dahil napakaliit nila para madaling kumalat.", "en": "Microplastics have been found almost everywhere — in rainwater, in table salt, and even in the deepest oceans — because they are small enough to spread far and wide.", "bis": "Nakit-an na ang microplastics bisan asa — sa tubig-ulan, sa asin sa lamesa, ug bisan sa kinahiladman nga kadagatan — kay gagmay ra kaayo sila aron mokatag og layo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "great-pacific-garbage-patch-g6", "domain": "EARTH_SPACE", "topic": "great pacific garbage patch", "grades": [6, 7, 8], "terms": ["garbage patch", "basurahan", "basura", "dagat", "kadagatan", "Pacific", "alon", "agos", "current", "ipon", "natitipon", "natipon", "umiikot", "France", "Texas", "gyre", "sulog", "tumpok", "nagtipon"], "fact": {"tl": "May higanteng tipon ng basurang plastik sa Pacific Ocean na tinatawag na Great Pacific Garbage Patch — ipinunta roon ng umiikot na agos ng dagat, at mas malaki pa ito sa ilang buong bansa.", "en": "There is a giant collection of floating plastic in the Pacific called the Great Pacific Garbage Patch — swirling ocean currents pile it there, and it is larger than some whole countries.", "bis": "Adunay higante nga tapok sa naglutaw nga plastik sa Pacific Ocean nga gitawag og Great Pacific Garbage Patch — gidala kini didto sa nagtuyok nga sulog sa dagat, ug mas dako pa kini kay sa pipila ka tibuok nasod."}, "source": "NOAA Marine Debris Program; The Ocean Cleanup (2018 survey)", "generator": "claude-workflow", "reviewed": false},
  {"id": "garbage-patch-not-an-island-g6", "domain": "EARTH_SPACE", "topic": "garbage patch is not solid", "grades": [6, 7, 8], "terms": ["garbage patch", "basura", "isla", "island", "dili isla", "hindi pulo", "lutang", "naglutaw", "sopas", "soup", "tipik", "gagmay", "sabaw", "makalakad", "hindi matibay", "scattered", "kalat", "nagkatag"], "fact": {"tl": "Hindi isang matibay na isla ng basura ang garbage patch na malalakaran mo — mas parang \"sopas\" ito ng milyon-milyong maliliit na plastik na nakakalat sa malawak na tubig.", "en": "The garbage patch is not a solid island of trash you could walk on — it is more like a \"soup\" of millions of tiny plastic bits scattered across a huge area of water.", "bis": "Ang garbage patch dili usa ka gahi nga isla sa basura nga imong malakawan — mas sama kini sa \"sabaw\" sa minilyon nga gagmay nga plastik nga nagkatag sa lapad nga tubig."}, "source": "NOAA Marine Debris Program", "generator": "claude-workflow", "reviewed": false},
  {"id": "ghost-nets-fishing-g6", "domain": "EARTH_SPACE", "topic": "ghost nets", "grades": [6, 7, 8], "terms": ["ghost net", "ghost nets", "lambat", "pukot", "naiwang lambat", "nawalang lambat", "mangingisda", "mananagat", "nahuhuli", "nakuha", "isda", "pawikan", "turtle", "nasisilo", "abandoned", "nakabitin", "plastik na lambat"], "fact": {"tl": "Ang mga naiwang lambat-pangisda sa dagat ay tinatawag na \"ghost nets\" — patuloy nilang nahuhuli at nasisilo ang mga isda at pawikan kahit wala nang taong humahawak sa mga ito.", "en": "Fishing nets lost or left in the sea are called \"ghost nets\" — they keep trapping and tangling fish and sea turtles even though no person is holding them anymore.", "bis": "Ang mga pukot nga nawala o nabiyaan sa dagat gitawag og \"ghost nets\" — padayon silang makadakop ug makagapos sa mga isda ug pawikan bisan wala nay tawo nga naggunit niini."}, "source": "NOAA Marine Debris Program", "generator": "claude-workflow", "reviewed": false},
  {"id": "plastic-decomposition-timeline-g6", "domain": "EARTH_SPACE", "topic": "how long plastic lasts", "grades": [5, 6, 7], "terms": ["plastik", "plastic", "bote", "botelya", "supot", "bag", "daan", "taon", "tuig", "450", "matagal", "dugay", "nabubulok", "madunot", "nadunot", "bottle", "gatusan", "decompose", "nasisira"], "fact": {"tl": "Napakatagal mabulok ng plastik — ang isang plastik na bote ay maaaring manatili sa kalikasan nang humigit-kumulang 450 taon, mas matagal pa kaysa sa buhay ng iyong mga lolo't lola.", "en": "Plastic breaks down extremely slowly — a single plastic bottle can stay in nature for around 450 years, far longer than your grandparents' whole lives.", "bis": "Hinay kaayo madunot ang plastik — ang usa ka plastik nga botelya mahimong magpabilin sa kinaiyahan og mga 450 ka tuig, mas dugay pa kay sa tibuok kinabuhi sa imong mga apohan."}, "source": "encyclopedia-stable consensus (NOAA marine debris timelines)", "generator": "claude-workflow", "reviewed": false},
  {"id": "aluminum-recycling-saves-energy-g6", "domain": "EARTH_SPACE", "topic": "recycling aluminum saves energy", "grades": [6, 7, 8], "terms": ["aluminum", "aluminyo", "lata", "can", "recycle", "i-recycle", "enerhiya", "kuryente", "gahum", "mas kaunti", "mas gamay", "95", "TV", "telebisyon", "oras", "nakakatipid", "makatipid", "tipid"], "fact": {"tl": "Ang pag-recycle ng isang lata ng aluminyo ay gumagamit ng halos 95% na mas kaunting enerhiya kaysa sa paggawa ng bago — sapat na ang natitipid para mapaandar ang isang telebisyon nang ilang oras.", "en": "Recycling one aluminum can uses about 95% less energy than making a new one — enough saved energy to run a television for a few hours.", "bis": "Ang pag-recycle sa usa ka lata nga aluminyo naggamit og halos 95% nga mas gamay nga enerhiya kay sa paghimo og bag-o — igo nga natipigan aron mapadagan ang telebisyon sulod sa pipila ka oras."}, "source": "US EPA WasteWise factoids", "generator": "claude-workflow", "reviewed": false},
  {"id": "aluminum-glass-infinitely-recyclable-g6", "domain": "EARTH_SPACE", "topic": "infinitely recyclable materials", "grades": [6, 7, 8], "terms": ["aluminyo", "aluminum", "salamin", "baso", "glass", "bildo", "paulit-ulit", "balik-balik", "balikbalik", "walang katapusan", "walay kataposan", "kalidad", "quality", "hindi nawawala", "dili mawala", "i-recycle", "na-recycle", "forever", "tunawin", "lasaw"], "fact": {"tl": "Ang aluminyo at salamin ay maaaring i-recycle nang paulit-ulit nang walang katapusan nang hindi nawawala ang kanilang kalidad — kaya naman maraming beses na maaaring maging bagong lata o bote ang luma.", "en": "Aluminum and glass can be recycled over and over endlessly without losing quality — so the same metal or glass can become a new can or bottle many times.", "bis": "Ang aluminyo ug bildo mahimong i-recycle balik-balik nga walay kataposan nga dili mawad-an sa kalidad — busa ang samang metal o bildo mahimong bag-ong lata o botelya makadaghan."}, "source": "International Aluminium Institute; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-smog-traps-over-city-g7", "domain": "EARTH_SPACE", "topic": "why smog gets trapped", "grades": [7, 8, 9], "terms": ["smog", "usok", "aso", "lungsod", "siyudad", "nakakulong", "na-trap", "mainit na hangin", "init", "temperature", "nakapatong", "hindi tumataas", "walang hangin", "tahimik na hangin", "inversion", "palibot", "bundok", "kabukiran", "valley", "nananatili", "nagpabilin"], "fact": {"tl": "Lumalala ang smog kapag ang isang layer ng mainit na hangin ay nakapatong sa malamig na hangin sa ibaba — para itong takip na pumipigil sa maruming hangin na umakyat at kumalat, kaya naipon ito sa lungsod.", "en": "Smog gets worse when a layer of warm air sits on top of cooler air below — like a lid that stops the dirty air from rising and clearing, so it builds up over the city.", "bis": "Mograbe ang smog kung adunay layer sa init nga hangin nga magpatong sa bugnaw nga hangin sa ubos — sama sa taklob nga makapugong sa hugaw nga hangin sa pagsaka ug pagkatag, busa magtapok kini sa siyudad."}, "source": "encyclopedia-stable consensus (temperature inversion)", "generator": "claude-workflow", "reviewed": false},
  {"id": "ground-level-ozone-smog-g8", "domain": "EARTH_SPACE", "topic": "ground-level ozone in smog", "grades": [8, 9, 10], "terms": ["ozone", "osono", "ground-level", "sa ibaba", "araw", "adlaw", "sikat ng araw", "sunlight", "usok ng sasakyan", "exhaust", "reaksiyon", "reaksyon", "masamang", "makadaot", "hindi tulad", "baga", "lungs", "nabubuo", "mabuo", "nahimo", "smog", "kemikal"], "fact": {"tl": "Ang sikat ng araw ay maaaring makipagreaksiyon sa usok ng sasakyan para bumuo ng ozone malapit sa lupa — hindi tulad ng nakakatulong na ozone sa itaas, ang ozone na ito sa ibaba ay nakakasama sa ating mga baga.", "en": "Sunlight can react with vehicle exhaust to form ozone near the ground — unlike the helpful ozone high above us, this low-level ozone is harmful to our lungs.", "bis": "Ang silaw sa adlaw mahimong moreaksyon sa aso sa sakyanan aron maporma ang ozone duol sa yuta — dili sama sa makatabang nga ozone sa taas, kining ubos nga ozone makadaot sa atong baga."}, "source": "encyclopedia-stable consensus (photochemical smog)", "generator": "claude-workflow", "reviewed": false},
  {"id": "landfill-trash-mummified-g6", "domain": "EARTH_SPACE", "topic": "trash does not rot in landfills", "grades": [6, 7, 8], "terms": ["landfill", "tambakan", "tambakanan", "basurahan", "basura", "hindi nabubulok", "dili madunot", "walang hangin", "kulang sa hangin", "oxygen", "na-preserve", "nananatili", "nagpabilin", "diyaryo", "newspaper", "pagkain", "pagkaon", "nababasa pa", "selyado", "sealed", "naipon"], "fact": {"tl": "Sa loob ng siksik na tambakan ng basura, kulang ang hangin, kaya kahit ang pagkain at diyaryo ay napakabagal mabulok — minsan ay nababasa pa ang lumang diyaryo pagkalipas ng maraming taon.", "en": "Inside a packed landfill there is little air, so even food and newspaper rot extremely slowly — sometimes an old newspaper can still be read after many years buried.", "bis": "Sulod sa siksik nga tambakanan sa basura, kulang ang hangin, busa bisan ang pagkaon ug mantalaan hinay kaayo madunot — usahay mabasa pa ang daang mantalaan human sa daghang tuig nga gilubong."}, "source": "encyclopedia-stable consensus (landfill anaerobic conditions)", "generator": "claude-workflow", "reviewed": false},
  {"id": "landfill-methane-gas-g8", "domain": "EARTH_SPACE", "topic": "landfill methane", "grades": [8, 9, 10], "terms": ["landfill", "tambakan", "basura", "methane", "metano", "gas", "nabubulok", "madunot", "walang oxygen", "walay hangin", "greenhouse", "init", "mainit", "planeta", "sinusunog", "gisunog", "kuryente", "power", "amoy", "baho", "produces"], "fact": {"tl": "Habang nabubulok ang basura sa tambakan nang walang hangin, naglalabas ito ng methane — isang gas na nagpapainit sa planeta, kaya minsan ay sinasalok ito para gawing kuryente.", "en": "As trash rots in a landfill without air, it gives off methane — a gas that warms the planet, so it is sometimes captured and burned to make electricity.", "bis": "Samtang madunot ang basura sa tambakanan nga walay hangin, mogawas niini ang methane — usa ka gas nga makapainit sa planeta, busa usahay sakpon kini aron himoong kuryente."}, "source": "encyclopedia-stable consensus (US EPA landfill gas)", "generator": "claude-workflow", "reviewed": false},
  {"id": "deforestation-rainforest-oxygen-g7", "domain": "EARTH_SPACE", "topic": "forests make oxygen and rain", "grades": [6, 7, 8], "terms": ["kagubatan", "gubat", "forest", "rainforest", "oxygen", "hangin", "carbon dioxide", "sumisipsip", "gisuyop", "nakuha", "puno", "kahoy", "ulan", "singaw", "tubig", "baha", "flood", "init", "klima", "naglilinis", "nagahawa"], "fact": {"tl": "Sumisipsip ang malalagong kagubatan ng carbon dioxide at naglalabas ng oxygen, at pinalalabas pa nila ang singaw ng tubig na tumutulong gumawa ng ulan — kaya nababago ang panahon kapag pinuputol ang mga ito.", "en": "Lush forests soak up carbon dioxide and release oxygen, and they also breathe out water vapor that helps make rain — so cutting them down can change the weather.", "bis": "Ang labong nga kalasangan mosuyop og carbon dioxide ug mobuga og oxygen, ug mobuga usab silag alisngaw sa tubig nga makatabang sa paghimo og ulan — busa kon putlon kini mausab ang panahon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "trees-absorb-carbon-g6", "domain": "EARTH_SPACE", "topic": "trees store carbon", "grades": [6, 7, 8], "terms": ["puno", "kahoy", "tree", "trees", "carbon", "carbon dioxide", "sumisipsip", "gisuyop", "nakuha", "itinatabi", "gitipigan", "katawan", "tangkay", "troso", "wood", "init", "greenhouse", "nililinis ang hangin", "planting", "pagtatanim", "nagtanom", "tumutulong"], "fact": {"tl": "Sumisipsip ang mga puno ng carbon dioxide mula sa hangin at itinatabi ang carbon sa kanilang katawan at sanga — kaya ang pagtatanim ng puno ay tumutulong bawasan ang gas na nagpapainit sa mundo.", "en": "Trees pull carbon dioxide out of the air and store the carbon in their trunks and branches — so planting trees helps reduce the gas that warms the world.", "bis": "Ang mga kahoy mosuyop og carbon dioxide gikan sa hangin ug magtipig sa carbon sa ilang lawas ug sanga — busa ang pagtanom og kahoy makatabang sa pagpakunhod sa gas nga makapainit sa kalibotan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "acid-rain-pollution-g7", "domain": "EARTH_SPACE", "topic": "acid rain", "grades": [7, 8, 9], "terms": ["acid rain", "ulang asido", "maasim na ulan", "ulan", "gas", "usok", "factory", "pabrika", "sasakyan", "kemikal", "nakakasira", "makadaot", "puno", "kahoy", "rebulto", "estatwa", "building", "tubig", "lawa", "nagiging asido", "maasim", "pollution", "polusyon"], "fact": {"tl": "Kapag humalo sa ulan ang ilang gas mula sa usok ng pabrika at sasakyan, nagiging \"acid rain\" ito — bahagyang maasim na ulan na makakasira ng mga puno, lawa, at maging mga bato at rebulto.", "en": "When certain gases from factory and vehicle smoke mix with rain, it becomes \"acid rain\" — slightly sour rain that can damage trees, lakes, and even stone statues.", "bis": "Kon ang pipila ka gas gikan sa aso sa pabrika ug sakyanan masagol sa ulan, mahimo kining \"acid rain\" — gamay nga aslom nga ulan nga makadaot sa mga kahoy, lanaw, ug bisan sa mga bato ug estatwa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "oil-spill-harms-birds-g6", "domain": "EARTH_SPACE", "topic": "oil spills", "grades": [6, 7, 8], "terms": ["oil spill", "langis", "tumagas", "natapon", "nausik", "dagat", "ibon", "langgam", "balahibo", "balhibo", "feathers", "lumulutang", "naglutaw", "dikit", "lumamig", "nginginig", "init", "nakakamatay", "cleanup"], "fact": {"tl": "Kapag tumagas ang langis sa dagat, dumidikit ito sa balahibo ng mga ibon-dagat at sira ang kakayahan nitong panatilihin silang mainit at lumutang — kaya napakapanganib nito sa mga hayop.", "en": "When oil spills into the sea it sticks to seabirds' feathers and ruins their ability to stay warm and float — which makes oil spills very dangerous to animals.", "bis": "Kon motulo ang lana sa dagat, modikit kini sa balhibo sa mga langgam-dagat ug madaot ang ilang katakos sa pagpabilin nga init ug paglutaw — busa peligroso kaayo ang oil spill sa mga hayop."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "light-pollution-stars-g6", "domain": "EARTH_SPACE", "topic": "light pollution", "grades": [6, 7, 8], "terms": ["light pollution", "polusyong ilaw", "liwanag", "kahayag", "ilaw", "suga", "gabi", "kagabhion", "bituin", "bitoon", "stars", "langit", "kalangitan", "lungsod", "siyudad", "hindi nakikita", "dili makita", "sobra", "maliwanag", "nakakaapekto", "pugad", "sea turtle"], "fact": {"tl": "Ang sobrang ilaw ng mga lungsod sa gabi ay tinatawag na \"light pollution\" — dahil dito ay halos hindi na makita ang mga bituin, at nalilito pa ang ilang hayop tulad ng bagong pisang pawikan.", "en": "Too much city light at night is called \"light pollution\" — it makes the stars almost impossible to see, and it can confuse animals like newly hatched sea turtles.", "bis": "Ang sobra nga kahayag sa mga siyudad sa gabii gitawag og \"light pollution\" — tungod niini halos dili na makita ang mga bituon, ug malibog pa ang pipila ka hayop sama sa bag-ong napusa nga pawikan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "noise-pollution-ocean-g7", "domain": "EARTH_SPACE", "topic": "noise pollution in the ocean", "grades": [7, 8, 9], "terms": ["noise pollution", "polusyong ingay", "ingay", "kasaba", "saba", "tunog", "barko", "ship", "dagat", "ilalim ng tubig", "whale", "balyena", "dolphin", "dolpin", "nakikipag-usap", "nag-uusap", "nag-istorya", "sonar", "naliligaw", "nalilito", "tugon", "sound travels"], "fact": {"tl": "Mas malayo at mas mabilis maglakbay ang tunog sa ilalim ng tubig kaysa sa hangin, kaya ang ingay ng malalaking barko ay nakakaabala sa mga balyena at dolphin na umaasa sa tunog para mag-usap at maghanap ng pagkain.", "en": "Sound travels farther and faster underwater than in air, so noise from big ships can disturb whales and dolphins that depend on sound to talk and find food.", "bis": "Mas layo ug mas paspas mobiyahe ang tingog ilalom sa tubig kay sa hangin, busa ang kasaba sa dagkong barko makasamok sa mga balyena ug dolphin nga nagsalig sa tingog aron makig-istorya ug mangita og pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ewaste-gold-inside-g7", "domain": "EARTH_SPACE", "topic": "e-waste contains metals", "grades": [7, 8, 9], "terms": ["e-waste", "electronic waste", "basurang elektroniko", "lumang gadget", "cellphone", "selpon", "telepono", "computer", "ginto", "gold", "bulawan", "tanso", "copper", "mahahalagang metal", "metal", "loob", "sulod", "makukuha", "makuha", "i-recycle", "nakatago", "nakaipon"], "fact": {"tl": "Ang lumang cellphone at computer ay tinatawag na \"e-waste,\" at may laman silang maliliit na piraso ng ginto, pilak, at tanso — kaya ang pag-recycle nito ay nakababawi ng mahahalagang metal.", "en": "Old cellphones and computers are called \"e-waste,\" and they contain tiny bits of gold, silver, and copper — so recycling them recovers valuable metals.", "bis": "Ang daang cellphone ug computer gitawag og \"e-waste,\" ug adunay sulod nga gagmay nga tipik sa bulawan, plata, ug tumbaga — busa ang pag-recycle niini makabawi sa mahalon nga metal."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-segregate-trash-g5", "domain": "EARTH_SPACE", "topic": "why we sort trash", "grades": [4, 5, 6], "terms": ["segregate", "paghihiwalay", "ihiwalay", "pagbahin", "bulagon", "basura", "nabubulok", "madunot", "biodegradable", "hindi nabubulok", "dili madunot", "recyclable", "pagkain", "pagkaon", "plastik", "papel", "mas madali", "sayon", "tambakan", "i-recycle", "abono"], "fact": {"tl": "Pinaghihiwalay natin ang nabubulok sa hindi nabubulok na basura para mas madaling magawang abono ang mga nabubulok at mai-recycle ang plastik at papel — sa halip na sama-samang itapon lahat.", "en": "We sort rotting waste from non-rotting waste so the rotting parts can more easily become compost and the plastic and paper can be recycled — instead of throwing everything together.", "bis": "Gibulag nato ang madunot gikan sa dili madunot nga basura aron mas sayon mahimong abono ang madunot ug ma-recycle ang plastik ug papel — imbis nga ilabay ang tanan nga sagol."}, "source": "DepEd MATATAG Science (waste segregation); encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "single-use-plastic-g5", "domain": "EARTH_SPACE", "topic": "single-use plastic", "grades": [5, 6, 7], "terms": ["single-use", "isahang gamit", "minsan lang", "kaisa ra gamiton", "plastik", "plastic", "straw", "istro", "supot", "sando bag", "sachet", "tinatapon agad", "gilabay dayon", "sandali lang", "matagal", "dugay", "nananatili", "tabang", "i-refuse", "tanggihan", "dala-dalang"], "fact": {"tl": "Ang single-use na plastik tulad ng straw at sachet ay ginagamit lang nang ilang minuto pero nananatili sa kalikasan nang daan-daang taon — kaya malaking tulong ang pagdadala ng sariling baso o bag.", "en": "Single-use plastics like straws and sachets are used for only a few minutes but stay in nature for hundreds of years — so bringing your own cup or bag helps a lot.", "bis": "Ang single-use nga plastik sama sa istro ug sachet gamiton lang sa pipila ka minuto apan magpabilin sa kinaiyahan og gatusan ka tuig — busa dako og tabang ang pagdala sa kaugalingong baso o bag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "reduce-most-important-r-g6", "domain": "EARTH_SPACE", "topic": "reduce is the best R", "grades": [6, 7, 8], "terms": ["reduce", "bawasan", "pagbawas", "pakunhod", "kunhoran", "3 Rs", "tatlong R", "reuse", "gamitin muli", "recycle", "i-recycle", "pinakamabuti", "pinakamaayo", "una", "mas mainam", "wala nang basura", "walay basura", "hindi gumagawa", "dili maghimo", "unang hakbang", "pinakamahalaga"], "fact": {"tl": "Sa tatlong R, ang \"Reduce\" (bawasan) ang itinuturing na pinakamabuti — dahil kung hindi ka muna bibili o gagamit ng sobra, wala nang basurang kailangang i-reuse o i-recycle.", "en": "Of the three Rs, \"Reduce\" is considered the best — because if you use less in the first place, there is no waste left to reuse or recycle at all.", "bis": "Sa tulo ka R, ang \"Reduce\" (pagpakunhod) ang giisip nga pinakamaayo — kay kon dili ka mogamit og sobra sa sinugdanan, wala nay basura nga kinahanglang i-reuse o i-recycle."}, "source": "encyclopedia-stable consensus (waste hierarchy)", "generator": "claude-workflow", "reviewed": false},
  {"id": "mangrove-protects-coast-pollution-g6", "domain": "EARTH_SPACE", "topic": "mangroves trap pollution and protect coast", "grades": [6, 7, 8], "terms": ["bakawan", "bakhaw", "mangrove", "mangroves", "ugat", "gamot", "gamut", "baybayin", "baybayon", "alon", "balod", "bagyo", "unos", "sumisipsip", "nagasala", "nakakasala", "putik", "sediment", "nililinis", "protektado", "pugad", "isda", "tubo ng halaman"], "fact": {"tl": "Ang masalimuot na ugat ng bakawan ay humahadlang sa malalaking alon at bagyo, at nasasala pa nito ang dumi sa tubig — kaya pinangangalagaan ang baybayin at pinupugaran ng mga isda.", "en": "The tangled roots of mangroves block big waves and storms and also filter dirt from the water — so they protect the coast and shelter young fish.", "bis": "Ang nagkagubot nga gamot sa bakhaw makababag sa dagkong balod ug bagyo ug makasala usab sa hugaw sa tubig — busa gipanalipdan niini ang baybayon ug gisilonganan sa mga gagmayng isda."}, "source": "encyclopedia-stable consensus; DepEd MATATAG Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "animals-eat-plastic-mistake-g6", "domain": "EARTH_SPACE", "topic": "why animals eat plastic", "grades": [5, 6, 7], "terms": ["plastik", "plastic", "supot", "plastic bag", "sando bag", "pawikan", "turtle", "akala", "abi", "abi nila", "dikya", "jellyfish", "pagkain", "pagkaon", "kinakain", "gikaon", "nalilito", "malibog", "kamukha", "susama", "kamukhang", "kumain", "busog", "nagutom"], "fact": {"tl": "Madalas kainin ng mga pawikan ang lumulutang na plastik na supot dahil akala nila ay dikya (jellyfish) ito — kaya napupuno ng plastik ang kanilang tiyan at hindi na sila makakain ng totoong pagkain.", "en": "Sea turtles often eat floating plastic bags because they mistake them for jellyfish — so their stomachs fill with plastic and they can no longer eat real food.", "bis": "Kanunay kaonon sa mga pawikan ang naglutaw nga plastik nga supot kay abi nila dikya (jellyfish) kini — busa mapuno og plastik ang ilang tiyan ug dili na sila makakaon og tinuod nga pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "clogged-drains-cause-floods-g5", "domain": "EARTH_SPACE", "topic": "trash causes floods", "grades": [4, 5, 6], "terms": ["basura", "trash", "kanal", "imburnal", "estero", "drainage", "baradong", "barado", "na-clog", "na-stuck", "tubig-ulan", "ulan", "baha", "lumalala", "mograbe", "itinapon", "gilabay", "plastik", "supot", "umaapaw"], "fact": {"tl": "Kapag tinatapon ang basura sa kanal at estero, nababara ang daluyan ng tubig — kaya hindi makaagos ang tubig-ulan at lumalala ang baha sa lungsod.", "en": "When trash is thrown into canals and waterways, it blocks the path of the water — so rainwater cannot drain away and floods get worse in the city.", "bis": "Kon ilabay ang basura sa kanal ug estero, mabara ang agianan sa tubig — busa dili makaagos ang tubig-ulan ug mograbe ang baha sa siyudad."}, "source": "DepEd MATATAG Science; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "compost-turns-scraps-to-soil-g5", "domain": "EARTH_SPACE", "topic": "composting food scraps", "grades": [5, 6, 7], "terms": ["compost", "abono", "kompost", "pagbubulok", "madunot", "tira sa pagkain", "balat ng prutas", "panit sa prutas", "dahon", "mikrobyo", "decomposer", "nagiging lupa", "lupa", "yuta", "tabang sa tanom", "pataba", "nutrients", "sustansiya", "basura sa kusina"], "fact": {"tl": "Sa pag-compost, ang mga tira sa pagkain, balat ng prutas, at tuyong dahon ay hinahayaang mabulok ng maliliit na mikrobyo hanggang maging mayamang lupa na nakakatulong sa pagtubo ng halaman.", "en": "In composting, food scraps, fruit peels, and dry leaves are left for tiny microbes to break down until they become rich soil that helps plants grow.", "bis": "Sa pag-compost, ang mga sobra sa pagkaon, panit sa prutas, ug uga nga dahon pasagdan nga dunoton sa gagmay nga mikrobyo hangtod mahimong tambok nga yuta nga makatabang sa pagtubo sa tanom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "plastic-from-petroleum-g7", "domain": "MATTER", "topic": "plastic comes from oil", "grades": [7, 8, 9], "terms": ["plastik", "plastic", "langis", "petrolyo", "petroleum", "oil", "gawa sa", "hinimo gikan", "crude oil", "fossil fuel", "gas", "kemikal", "chemical", "hindi natural", "dili natural", "kaya matagal", "hindi nabubulok", "dili madunot", "mikrobyo", "nabuo", "ginawa"], "fact": {"tl": "Karamihan ng plastik ay gawa mula sa langis (petrolyo) sa pamamagitan ng paghuhugis ng mga kemikal nito — at dahil hindi ito natural na materyal, hirap itong bulukin ng mga mikrobyo sa kalikasan.", "en": "Most plastic is made from oil (petroleum) by reshaping its chemicals — and because it is not a natural material, microbes in nature struggle to break it down.", "bis": "Kadaghanan sa plastik gihimo gikan sa lana (petrolyo) pinaagi sa pag-usab sa mga kemikal niini — ug tungod kay dili kini natural nga materyal, malisdan ang mga mikrobyo sa kinaiyahan sa pagdunot niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "recycling-paper-saves-trees-g5", "domain": "EARTH_SPACE", "topic": "recycling paper saves trees", "grades": [5, 6, 7], "terms": ["papel", "paper", "i-recycle", "na-recycle", "luma", "daan", "bagong papel", "new paper", "puno", "kahoy", "tree", "trees", "naililigtas", "maluwas", "tubig", "enerhiya", "mas kaunti", "mas gamay", "nababawasan", "fiber", "himbis"], "fact": {"tl": "Ang pag-recycle ng lumang papel para gumawa ng bago ay nakakatipid ng mga puno at tubig — dahil hindi na kailangang magputol ng bagong kahoy para sa bawat papel.", "en": "Recycling old paper to make new paper saves trees and water — because fewer fresh trees need to be cut down for each sheet.", "bis": "Ang pag-recycle sa daang papel aron maghimo og bag-o makaluwas og mga kahoy ug tubig — kay dili na kinahanglang magputol og bag-ong kahoy alang sa matag papel."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "endangered-protected-area-g6", "domain": "EARTH_SPACE", "topic": "protected areas help wildlife", "grades": [6, 7, 8], "terms": ["protected area", "protektadong lugar", "kapunungan", "sanctuary", "santuwaryo", "reserba", "reserve", "national park", "ligtas", "luwas", "hayop", "mananap", "hindi pinapangaso", "dili mangayam", "habitat", "tirahan", "puok", "nababawi", "makarekober", "populasyon", "ipinagbabawal"], "fact": {"tl": "Ang ilang lugar ay ginagawang \"protected area\" o santuwaryo kung saan ipinagbabawal ang pangangaso at pagputol ng puno — para magkaroon ng ligtas na tirahan ang mga nanganganib na hayop at dumami muli.", "en": "Some places are made into \"protected areas\" or sanctuaries where hunting and tree-cutting are banned — so endangered animals have a safe home and can grow in number again.", "bis": "Ang ubang dapit gihimong \"protected area\" o santuwaryo diin gidili ang pagpangayam ug pagputol og kahoy — aron ang mga namiligrong hayop adunay luwas nga puy-anan ug modaghan pag-usab."}, "source": "encyclopedia-stable consensus; DepEd MATATAG Science", "generator": "claude-workflow", "reviewed": false},
  {"id": "kids-help-environment-g4", "domain": "EARTH_SPACE", "topic": "what kids can do for the planet", "grades": [3, 4, 5], "terms": ["bata", "mga bata", "kabataan", "tabang", "makatabang", "tumulong", "kalikasan", "kinaiyahan", "environment", "planeta", "patayin ang ilaw", "palonga", "gripo", "sara", "tipid", "tubig", "baso", "dala-dalang", "reusable", "magtanim", "pagtatanim", "nagtanom", "huwag magkalat", "ayaw paglabay"], "fact": {"tl": "Kahit mga bata ay makakatulong sa kalikasan sa pamamagitan ng simpleng gawi — pagpatay ng ilaw kapag hindi ginagamit, hindi pag-aaksaya ng tubig, paggamit ng dala-dalang baso, at hindi pagkakalat.", "en": "Even children can help the planet with simple habits — turning off lights when not used, not wasting water, using a reusable cup, and never littering.", "bis": "Bisan ang mga bata makatabang sa kinaiyahan pinaagi sa yano nga batasan — pagpalong sa suga kon dili gamiton, dili pag-usik sa tubig, paggamit og dala-dala nga baso, ug dili pagkalat og basura."}, "source": "DepEd MATATAG Science; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnet-loses-power-when-hot-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "heat can destroy a magnet", "grades": [6, 7, 8], "terms": ["magnet", "mainit", "init", "apoy", "temperatura", "nawawala", "nawala", "mawala", "lakas", "gahum", "kusog", "heat", "temperature", "Curie point", "demagnetize", "mawawalan ng bisa"], "fact": {"tl": "Kapag napakainit ng isang magnet o nasunog ito, nawawalan ito ng lakas at maaaring tumigil sa pagiging magnet.", "en": "If a magnet gets very hot or is heated in a flame, it loses its strength and can stop being a magnet at all.", "bis": "Kon mainit kaayo ang usa ka magnet o sunogon kini, mawad-an kini sa kusog ug mahimong dili na magnet."}, "source": "encyclopedia-stable consensus (Curie temperature)", "generator": "claude-workflow", "reviewed": false},
  {"id": "dropping-magnet-weakens-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "dropping a magnet can weaken it", "grades": [5, 6, 7], "terms": ["magnet", "nahulog", "nabuhi", "nabundak", "sahig", "hampas", "humina", "huyang", "luya", "weaken", "drop", "hit", "jostle", "atoms", "pagkaayos"], "fact": {"tl": "Kapag madalas mahulog o mabagok ang isang magnet, gumugulo ang ayos ng maliliit na bahagi sa loob nito at unti-unting humihina ang magnet.", "en": "Dropping or banging a magnet over and over jumbles the tiny aligned parts inside it, so the magnet slowly gets weaker.", "bis": "Kon kanunay nga mahulog o mabundak ang usa ka magnet, magkaguliyang ang gagmay nga bahin sa sulod niini ug hinay-hinay nga maluya ang magnet."}, "source": "encyclopedia-stable consensus (magnetic domains)", "generator": "claude-workflow", "reviewed": false},
  {"id": "only-three-magnetic-metals-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "why only some metals are magnetic", "grades": [5, 6, 7], "terms": ["bakal", "iron", "metal", "puthaw", "nikel", "kobalt", "nickel", "cobalt", "ginto", "pilak", "tanso", "gold", "silver", "copper", "hindi nakakapit", "dili mokapit", "bakit", "ngano", "magnetiko"], "fact": {"tl": "Karamihan ng metal tulad ng ginto, pilak, at tanso ay hindi naaakit ng magnet; iron, nickel, at cobalt lamang ang malakas na magnetiko.", "en": "Most metals like gold, silver, and copper are not pulled by a magnet; only iron, nickel, and cobalt are strongly magnetic.", "bis": "Kadaghanan sa metal sama sa bulawan, plata, ug tumbaga dili madani sa magnet; ang puthaw, nickel, ug cobalt lang ang kusog nga magnetiko."}, "source": "encyclopedia-stable consensus (ferromagnetism)", "generator": "claude-workflow", "reviewed": false},
  {"id": "aluminum-can-not-magnetic-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "aluminum cans are not magnetic", "grades": [4, 5, 6], "terms": ["aluminum", "lata", "can", "aluminyo", "hindi kumakapit", "dili mokapit", "soda", "softdrink", "bakal na lata", "steel can", "recycle", "magnet", "subok", "test", "paghi-as"], "fact": {"tl": "Hindi kumakapit ang magnet sa lata ng softdrink na gawa sa aluminum, kaya ginagamit ang magnet sa recycling para ihiwalay ang mga latang bakal.", "en": "A magnet will not stick to an aluminum soda can, so recyclers use magnets to separate steel cans from aluminum ones.", "bis": "Dili mokapit ang magnet sa lata sa softdrink nga hinimo sa aluminum, mao nga gamiton ang magnet sa recycling aron ibulag ang mga lata nga puthaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "steel-needle-becomes-magnet-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "rubbing a needle into a magnet", "grades": [5, 6, 7], "terms": ["karayom", "needle", "dagom", "kuskos", "hilod", "kuskusin", "magnet", "gawing magnet", "mahimong magnet", "DIY compass", "magpara", "stroke", "pino", "magnetize"], "fact": {"tl": "Kung kuskusin mo nang paisa-isang direksyon ang isang karayom gamit ang magnet, magiging magnet din ang karayom at puwedeng gawing compass.", "en": "If you stroke a steel needle in one direction with a magnet, the needle itself becomes a magnet and you can make a simple compass with it.", "bis": "Kon hilodon nimo sa usa ka direksyon ang usa ka dagom gamit ang magnet, mahimong magnet usab ang dagom ug pwede himuong compass."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "compass-needle-points-magnetic-not-true-g7", "domain": "EARTH_SPACE", "topic": "compass points to magnetic north not true north", "grades": [6, 7, 8], "terms": ["compass", "kompas", "brujula", "hilagang magnetiko", "magnetic north", "tunay na hilaga", "true north", "amihanan", "norte", "hindi eksaktong tumuturo", "dili tukma", "declination", "mapa", "mariner"], "fact": {"tl": "Ang karayom ng compass ay tumuturo sa magnetic north, na medyo iba sa tunay na hilaga kung saan nakaturo ang globo, kaya kailangang i-adjust ng mga marino.", "en": "A compass needle points to magnetic north, which is a little different from the true north of the globe, so sailors must adjust for the gap.", "bis": "Ang dagom sa compass motudlo sa magnetic north, nga gamay nga lahi sa tinuod nga amihanan diin nagtudlo ang globo, mao nga mag-adjust ang mga marinero."}, "source": "encyclopedia-stable consensus (magnetic declination)", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-magnetic-north-is-south-pole-g8", "domain": "EARTH_SPACE", "topic": "Earth's magnetic north is really a south pole", "grades": [7, 8, 9], "terms": ["mundo", "Earth", "kalibutan", "magnetic", "hilaga", "north", "timog", "south", "poste", "compass", "nakaharap", "naatubang", "opposite poles attract", "kakaiba", "kataw-anan"], "fact": {"tl": "Nakakatuwa na ang tinatawag nating magnetic north ng mundo ay talagang isang south magnetic pole, kaya naaakit dito ang north na dulo ng karayom ng compass.", "en": "Oddly, the place we call Earth's magnetic north is actually a south magnetic pole, which is why the north end of a compass needle is pulled toward it.", "bis": "Kataw-anan nga ang gitawag natong magnetic north sa kalibutan usa man diay ka south magnetic pole, mao nga ang north nga tumoy sa dagom sa compass madani niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnetic-field-protects-air-g8", "domain": "EARTH_SPACE", "topic": "magnetic field helps keep our air", "grades": [7, 8, 9], "terms": ["magnetic field", "magnetikong larangan", "kalasag", "panagang", "taming", "hangin", "atmosphere", "atmospera", "araw", "adlaw", "solar wind", "hangin ng araw", "Mars", "nawalan ng hangin", "protect", "nanalipod"], "fact": {"tl": "Ang magnetikong larangan ng mundo ay parang kalasag na tumutulong panatilihin ang ating hangin sa pamamagitan ng pagpigil sa malakas na hangin mula sa araw.", "en": "Earth's magnetic field acts like a shield that helps keep our air by blocking the strong wind of particles streaming from the Sun.", "bis": "Ang magnetikong field sa kalibutan murag taming nga makatabang nga magpabilin ang atong hangin pinaagi sa pagpugong sa kusog nga hangin gikan sa adlaw."}, "source": "encyclopedia-stable consensus (magnetosphere, solar wind)", "generator": "claude-workflow", "reviewed": false},
  {"id": "aurora-colors-from-gases-g8", "domain": "EARTH_SPACE", "topic": "why auroras have different colors", "grades": [7, 8, 9], "terms": ["aurora", "hilaga", "northern lights", "kulay", "color", "bulok", "berde", "pula", "green", "red", "oxygen", "oksiheno", "nitrogen", "gas", "kalawakan", "langit", "particle", "sumasalpok", "mosalpok"], "fact": {"tl": "Iba-iba ang kulay ng aurora dahil ang berde at pula ay nanggagaling sa oxygen samantalang ang lila at asul ay galing sa nitrogen sa mataas na hangin.", "en": "Auroras glow in different colors because green and red come from oxygen while purple and blue come from nitrogen high in the air.", "bis": "Lahi-lahi ang kolor sa aurora kay ang berde ug pula gikan sa oxygen samtang ang purple ug asul gikan sa nitrogen sa taas nga hangin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "aurora-near-poles-g7", "domain": "EARTH_SPACE", "topic": "why auroras appear near the poles", "grades": [6, 7, 8], "terms": ["aurora", "poste", "hilaga", "timog", "north", "south", "pole", "particle", "sumusunod", "mosunod", "magnetic field lines", "guhit", "linya", "funnel", "dumadaloy", "gitudlo", "bihira sa Pilipinas", "tropiko"], "fact": {"tl": "Madalas makita ang aurora malapit sa hilaga at timog na poste dahil doon hinihila ng magnetikong guhit ng mundo ang mga particle mula sa araw papasok sa hangin.", "en": "Auroras mostly appear near the north and south poles because Earth's magnetic field lines funnel the particles from the Sun into the air there.", "bis": "Kasagaran makita ang aurora duol sa amihanan ug habagatan nga poste kay didto ang magnetikong linya sa kalibutan magbira sa mga partikulo gikan sa adlaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mri-uses-giant-magnet-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "MRI machines use a powerful magnet", "grades": [7, 8, 9], "terms": ["MRI", "makina", "ospital", "hospital", "tubo", "larawan ng loob", "retrato sa sulod", "scan", "napakalakas na magnet", "kusog kaayo nga magnet", "tubig", "hydrogen", "katawan", "lawas", "walang radiation", "picture", "imahe"], "fact": {"tl": "Ang MRI machine sa ospital ay gumagamit ng napakalakas na magnet para kumuha ng malinaw na larawan ng loob ng katawan nang hindi gumagamit ng x-ray.", "en": "An MRI machine in the hospital uses a very powerful magnet to take clear pictures of the inside of the body without using x-rays.", "bis": "Ang MRI machine sa ospital mogamit ug kusog kaayo nga magnet aron makakuha ug klaro nga hulagway sa sulod sa lawas nga walay gamit nga x-ray."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mri-no-metal-allowed-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "why metal is banned near MRI machines", "grades": [7, 8, 9], "terms": ["MRI", "metal", "bakal", "puthaw", "bawal", "gidili", "mapanganib", "delikado", "peligroso", "lumilipad", "molupad", "hila", "gibira", "alahas", "jewelry", "relo", "selpon", "mabilis na hila", "safety"], "fact": {"tl": "Bawal magdala ng bakal na bagay malapit sa MRI dahil napakalakas ng magnet nito kaya kayang hilahin nang mabilis at mapanganib ang metal.", "en": "Metal objects are not allowed near an MRI because its magnet is so strong it can pull metal across the room fast and dangerously.", "bis": "Gidili ang pagdala ug bakal nga butang duol sa MRI kay kusog kaayo ang magnet niini mao nga makabira kini ug metal nga paspas ug peligroso."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "electromagnet-can-turn-off-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "an electromagnet can be switched off", "grades": [5, 6, 7], "terms": ["electromagnet", "elektromagnet", "kuryente", "koryente", "switch", "patay", "buhi", "off", "on", "kayang patayin", "mahimong patyon", "junkyard", "crane", "kotse", "sasakyan", "kontrolado", "control", "kalamangan"], "fact": {"tl": "Hindi tulad ng karaniwang magnet, kayang patayin at buhayin ang electromagnet sa pamamagitan ng pag-on at off ng kuryente.", "en": "Unlike an ordinary magnet, an electromagnet can be turned on and off just by switching the electric current on or off.", "bis": "Lahi sa ordinaryong magnet, ang electromagnet mahimong patyon ug buhion pinaagi lang sa pag-on ug off sa koryente."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "crane-electromagnet-lifts-cars-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "giant electromagnets lift cars in junkyards", "grades": [6, 7, 8], "terms": ["crane", "grua", "electromagnet", "junkyard", "basura ng kotse", "tambakan", "kotse", "sasakyan", "awto", "bakal", "puthaw", "nagbubuhat", "mobuhat", "binibitawan", "gibuwagan", "patayin ang kuryente", "switch", "kalakhan"], "fact": {"tl": "Sa junkyard, gumagamit ng malaking electromagnet ang crane para magbuhat ng buong kotse, at binibitawan ito kapag pinatay ang kuryente.", "en": "In a junkyard, a crane uses a giant electromagnet to lift whole cars, then drops them by switching off the current.", "bis": "Sa junkyard, mogamit ang grua ug dako nga electromagnet aron mobuhat ug tibuok awto, ug ibuhian kini kon patyon ang koryente."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "motor-magnet-spins-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "magnets make motors spin", "grades": [6, 7, 8], "terms": ["motor", "magnet", "kuryente", "koryente", "umiikot", "moliyok", "umiinog", "spin", "push pull", "tinutulak", "gihagit", "fan", "bentilador", "laruan", "dula", "makina sa kotse", "rotation"], "fact": {"tl": "Sa loob ng electric motor, ang magnet at kuryente ay nagtutulak at naghihila kaya patuloy na umiikot ang motor at pinapagana ang mga fan at laruan.", "en": "Inside an electric motor, magnets and electric current push and pull so the motor keeps spinning, running things like fans and toys.", "bis": "Sa sulod sa electric motor, ang magnet ug koryente magtinulakan ug magbinira mao nga padayong moliyok ang motor ug magpadagan sa fan ug dula."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "speaker-magnet-vibrates-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "how a magnet in a speaker makes sound", "grades": [6, 7, 8], "terms": ["speaker", "ispiker", "tunog", "tingog", "magnet", "coil", "kuryente", "koryente", "nanginginig", "mokurog", "vibrate", "cone", "papel na cone", "tugtog", "music", "earphone", "headphone", "kumikilos", "molihok"], "fact": {"tl": "Sa loob ng speaker, ang magnet at coil na may kuryente ay nagpapakilos sa cone pabalik-balik nang mabilis, at ang panginginig na ito ang gumagawa ng tunog.", "en": "Inside a speaker, a magnet and an electric coil push a cone back and forth quickly, and that vibration is what makes the sound.", "bis": "Sa sulod sa speaker, ang magnet ug coil nga adunay koryente magpalihok sa cone balik-balik nga paspas, ug kining pagkurog mao ang mohimo sa tingog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "earphones-tiny-speakers-magnet-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "earphones have tiny magnets inside", "grades": [5, 6, 7], "terms": ["earphone", "headphone", "ataphono", "maliit na magnet", "gamay nga magnet", "tunog", "tingog", "tenga", "dalunggan", "speaker", "laki", "mabilis", "music", "kanta", "liit", "kuryente", "vibrate"], "fact": {"tl": "May maliliit na magnet sa loob ng bawat earphone na nagpapakilos sa maliit na speaker para makarinig ka ng musika sa iyong tenga.", "en": "There are tiny magnets inside every earphone that move a small speaker so you can hear music right in your ear.", "bis": "Adunay gagmay nga magnet sa sulod sa matag earphone nga magpalihok sa gamay nga speaker aron madunggan nimo ang musika sa imong dalunggan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hard-drive-stores-with-magnetism-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "computers store data with magnetism", "grades": [7, 8, 9], "terms": ["hard drive", "computer", "kompyuter", "magnet", "datos", "data", "impormasyon", "kahibalo", "naka-store", "gitago", "disk", "plato", "magnetiko", "spot", "bit", "memorya", "file", "nakaimbak"], "fact": {"tl": "Ang hard drive ng kompyuter ay nag-iimbak ng datos sa pamamagitan ng pag-magnetize ng napakaliliit na lugar sa umiikot na disk.", "en": "A computer's hard drive stores data by magnetizing very tiny spots on a spinning disk.", "bis": "Ang hard drive sa kompyuter mag-imbak ug datos pinaagi sa pag-magnetize sa gagmay kaayo nga lugar sa nagaliyok nga disk."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "credit-card-stripe-magnetic-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "the black stripe on cards is magnetic", "grades": [6, 7, 8], "terms": ["credit card", "ATM card", "kard", "itim na guhit", "itom nga linya", "magnetic stripe", "magnetiko", "impormasyon", "datos", "na-swipe", "gi-swipe", "layo sa magnet", "mawawala", "mabura", "banda", "strip"], "fact": {"tl": "Ang itim na guhit sa likod ng ATM o credit card ay isang magnetic stripe na nag-iingat ng impormasyon, kaya dapat itong ilayo sa malalakas na magnet.", "en": "The black stripe on the back of an ATM or credit card is a magnetic stripe that holds information, so it must be kept away from strong magnets.", "bis": "Ang itom nga linya sa luyo sa ATM o credit card usa ka magnetic stripe nga nagtago ug impormasyon, mao nga ipalayo kini sa kusog nga magnet."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "maglev-no-wheels-fast-g8", "domain": "FORCE_MOTION_ENERGY", "topic": "maglev trains have no wheels touching the track", "grades": [7, 8, 9], "terms": ["maglev", "tren", "train", "gulong", "ligid", "wheel", "walang gulong", "walay ligid", "lumulutang", "naglutaw", "friction", "kuskusan", "mabilis", "paspas", "tahimik", "hilom", "Japan", "China", "levitation"], "fact": {"tl": "Ang maglev na tren ay walang gulong na dumidikit sa riles, kaya halos walang friction at puwede itong tumakbo nang napakabilis at tahimik.", "en": "A maglev train has no wheels touching the rail, so there is almost no friction and it can run extremely fast and quietly.", "bis": "Ang maglev nga tren walay ligid nga modikit sa riles, mao nga halos walay friction ug makadagan kini paspas kaayo ug hilom."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "compass-history-china-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "the first compasses used lodestone", "grades": [5, 6, 7], "terms": ["compass", "kompas", "unang compass", "lodestone", "bato", "magnetiko na bato", "natural na magnet", "natural nga magnet", "China", "Tsina", "sinaunang", "karaan", "floating needle", "naglutaw", "kasaysayan", "history", "navigation"], "fact": {"tl": "Ang mga unang compass ay gawa sa lodestone, isang likas na magnetikong bato, at ginamit sa Tsina noon pa para hanapin ang direksyon.", "en": "The first compasses were made from lodestone, a naturally magnetic rock, and were used long ago in China to find direction.", "bis": "Ang unang compass hinimo gikan sa lodestone, usa ka natural nga magnetikong bato, ug gigamit sa karaang China aron pangitaon ang direksyon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lodestone-natural-magnet-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "lodestone is a magnet made by nature", "grades": [5, 6, 7], "terms": ["lodestone", "bato", "natural na magnet", "natural nga magnet", "magnetite", "mineral", "kidlat", "kilat", "lightning", "nahuhubog", "nakabuhat sa kinaiyahan", "likas", "kinaiyahan", "attracts iron", "umaakit", "modani"], "fact": {"tl": "Ang lodestone ay isang likas na magnet na bato na umaakit ng bakal kahit hindi ito ginawa ng tao; ito ang unang nakilalang magnet.", "en": "Lodestone is a naturally magnetic rock that attracts iron even though no person made it; it was the first magnet ever known.", "bis": "Ang lodestone usa ka natural nga magnetikong bato nga modani ug puthaw bisan walay tawo nga naghimo niini; mao kini ang unang nailhan nga magnet."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnet-works-through-water-g5", "domain": "FORCE_MOTION_ENERGY", "topic": "magnets work through water and glass", "grades": [4, 5, 6], "terms": ["magnet", "tubig", "water", "baso", "salamin", "glass", "papel", "dumadaan", "molabay", "puwersa", "kusog", "force", "through", "clip sa loob ng baso", "experiment", "subok"], "fact": {"tl": "Gumagana pa rin ang puwersa ng magnet kahit may tubig, baso, o papel sa pagitan, kaya kayang gumalaw ang clip sa loob ng basong may tubig.", "en": "A magnet's pull still works through water, glass, or paper in between, so it can move a clip inside a glass of water.", "bis": "Molihok gihapon ang kusog sa magnet bisan adunay tubig, baso, o papel sa tunga, mao nga makalihok kini ug clip sulod sa basong tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnet-cannot-pass-iron-shield-g7", "domain": "FORCE_MOTION_ENERGY", "topic": "iron can block a magnetic field", "grades": [6, 7, 8], "terms": ["magnet", "bakal", "puthaw", "iron", "kalasag", "taming", "panagang", "hindi dumadaan", "dili molabay", "block", "shield", "steel", "hinaharang", "gibabagan", "field", "larangan", "plato", "sumisipsip"], "fact": {"tl": "Karaniwang dumadaan ang magnet sa papel o plastik, pero ang makapal na bakal ay nakakaharang ng magnetikong puwersa tulad ng kalasag.", "en": "A magnet usually reaches through paper or plastic, but a thick piece of iron can block the magnetic force like a shield.", "bis": "Kasagaran molabay ang magnet sa papel o plastik, apan ang baga nga puthaw makababag sa magnetikong kusog murag taming."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "two-magnets-can-float-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "two magnets can make one float", "grades": [5, 6, 7], "terms": ["magnet", "lumulutang", "naglutaw", "levitate", "float", "magkatulad na poste", "managsama nga poste", "nagtutulakan", "magtinulakanay", "pencil", "singsing", "ring magnet", "laruan", "dula", "floating top", "balanse", "gusi"], "fact": {"tl": "Kung salansanin mo ang dalawang ring magnet na magkatulad ang poste sa isang patpat, lulutang ang isa sa ibabaw ng isa dahil nagtutulakan sila.", "en": "If you stack two ring magnets with like poles facing on a stick, one will float above the other because they push apart.", "bis": "Kon tapokon nimo ang duha ka ring magnet nga managsama ang poste sa usa ka patpat, maglutaw ang usa ibabaw sa lain kay magtinulakanay sila."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "earth-field-from-molten-iron-g8", "domain": "EARTH_SPACE", "topic": "Earth is a magnet because of its molten core", "grades": [7, 8, 9], "terms": ["mundo", "Earth", "kalibutan", "magnet", "ubod", "kaibuturan", "core", "tunaw na bakal", "natunaw nga puthaw", "molten iron", "umiikot", "moliyok", "kuryente", "koryente", "geodynamo", "init", "kainit", "spin", "field"], "fact": {"tl": "Naging isang malaking magnet ang mundo dahil sa umiikot na tunaw na bakal sa malalim na ubod nito na gumagawa ng magnetikong larangan.", "en": "Earth acts like a giant magnet because the swirling molten iron deep in its core creates a magnetic field.", "bis": "Ang kalibutan murag dako nga magnet tungod sa nagaliyok nga natunaw nga puthaw sa lawom nga kaibuturan niini nga mohimo ug magnetikong field."}, "source": "encyclopedia-stable consensus (geodynamo)", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnetic-poles-flip-history-g9", "domain": "EARTH_SPACE", "topic": "Earth's magnetic poles have flipped before", "grades": [8, 9, 10], "terms": ["mundo", "Earth", "kalibutan", "magnetic pole", "poste", "hilaga", "timog", "nagpalit", "nag-ilis", "flip", "reversal", "baligtad", "balihad", "libo-libong taon", "libolibong tuig", "bato", "lava", "record", "kasaysayan", "pagbaligtad"], "fact": {"tl": "Sa napakahabang panahon, ilang beses nang nagpalitan ang hilaga at timog na magnetic pole ng mundo, at nakatala ito sa mga lumang bato.", "en": "Over very long times, Earth's north and south magnetic poles have swapped places several times, and old rocks record these flips.", "bis": "Sa hataas kaayong panahon, kapila na nag-ilisay ang amihanan ug habagatan nga magnetic pole sa kalibutan, ug natala kini sa karaang mga bato."}, "source": "encyclopedia-stable consensus (geomagnetic reversal)", "generator": "claude-workflow", "reviewed": false},
  {"id": "animals-sense-magnetic-field-g7", "domain": "LIVING_THINGS", "topic": "some animals sense Earth's magnetic field", "grades": [6, 7, 8], "terms": ["hayop", "mananap", "animal", "ibon", "langgam", "bird", "pawikan", "sea turtle", "damdam", "mabati", "magnetic field", "magnetikong larangan", "compass sa katawan", "navigation", "direksyon", "paglalakbay", "panaw", "migration", "nararamdaman"], "fact": {"tl": "May mga hayop tulad ng ibong migratory at pawikan na nakakaramdam ng magnetikong larangan ng mundo at ginagamit ito bilang likas na compass.", "en": "Some animals like migrating birds and sea turtles can sense Earth's magnetic field and use it as a built-in compass.", "bis": "Adunay mga mananap sama sa langgam nga molalin ug pawikan nga makabati sa magnetikong field sa kalibutan ug gamiton kini ingong natural nga compass."}, "source": "encyclopedia-stable consensus (magnetoreception)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sun-storm-affects-power-g9", "domain": "EARTH_SPACE", "topic": "solar storms can disturb power and signals", "grades": [8, 9, 10], "terms": ["araw", "adlaw", "sun", "solar storm", "bagyong solar", "unos sa adlaw", "magnetic", "kuryente", "koryente", "power grid", "signal", "GPS", "satellite", "satelayt", "naaabala", "nasamok", "aurora", "particle", "kuryenteng patay"], "fact": {"tl": "Ang malalakas na pagsabog sa araw ay nakakaabala sa magnetikong larangan ng mundo at maaaring makaapekto sa kuryente, GPS, at signal ng satellite.", "en": "Strong outbursts from the Sun disturb Earth's magnetic field and can affect electricity, GPS, and satellite signals.", "bis": "Ang kusog nga pagbuto sa adlaw makasamok sa magnetikong field sa kalibutan ug makaapekto sa koryente, GPS, ug signal sa satellite."}, "source": "encyclopedia-stable consensus (geomagnetic storms)", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-magnets-have-two-poles-g6", "domain": "FORCE_MOTION_ENERGY", "topic": "every magnet always has two poles", "grades": [5, 6, 7], "terms": ["magnet", "poste", "north", "south", "hilaga", "timog", "dalawa", "duha", "walang iisang poste", "walay usa ra ka poste", "hinati", "gibahin", "monopole", "palaging may", "laging dalawa"], "fact": {"tl": "Walang magnet na may iisang poste lamang; kahit gaano mo pa ito hatiin, palaging may north at south na poste ang bawat piraso.", "en": "No magnet can have only one pole; no matter how you cut it, every piece always has both a north and a south pole.", "bis": "Walay magnet nga adunay usa ra ka poste; bisan unsaon nimo pagbahin, kanunay adunay north ug south nga poste ang matag bahin."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "diamonds-older-than-dinosaurs-g5", "domain": "EARTH_SPACE", "topic": "how old diamonds are", "grades": [5, 6, 7], "terms": ["diyamante", "brilyante", "diamond", "edad", "tanda", "luma", "bilyong taon", "sinaunang", "karbon", "kalaliman", "edad sa diamante", "tigulang", "binilyon ka tuig", "karaan", "dinosaur", "dinosaurs"], "fact": {"tl": "Karamihan sa mga diyamante ay napakaluma na — mahigit isang bilyong taon na ang edad, kaya mas matanda pa sila kaysa sa mga dinosaur.", "en": "Most diamonds are extremely old — over a billion years — so they are even older than the dinosaurs.", "bis": "Kadaghanan sa mga diamante karaan na kaayo — kapin usa ka bilyong tuig na ang edad, mao nga mas tigulang pa sila kay sa mga dinosaur."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "diamonds-formed-deep-volcano-ride-g7", "domain": "EARTH_SPACE", "topic": "how diamonds reach the surface", "grades": [7, 8, 9], "terms": ["diyamante", "diamond", "bulkan", "volcano", "magma", "kimberlite", "mantle", "mabilis na pagsabog", "kalaliman", "gisaka", "abot sa ibabaw", "pagbuto sa bulkan"], "fact": {"tl": "Nabubuo ang mga diyamante nang napakalalim sa loob ng Earth, at naibabaw lamang sila kapag may sobrang bilis na pagsabog ng bulkan na nagdadala sa kanila pataas sa pamamagitan ng magma.", "en": "Diamonds form very deep inside the Earth, and they only reach the surface when an unusually fast volcanic eruption carries them up through magma.", "bis": "Maporma ang mga diamante lawom kaayo sa sulod sa Earth, ug makaabot lang sila sa ibabaw kon adunay paspas kaayo nga pagbuto sa bulkan nga modala kanila pasaka pinaagi sa magma."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "quartz-most-common-mineral-g5", "domain": "EARTH_SPACE", "topic": "quartz is everywhere", "grades": [5, 6], "terms": ["kuwarts", "quartz", "mineral", "buhangin", "sand", "beach", "baybayin", "karaniwan", "pinakakaraniwan", "silika", "silica", "kristal", "balas", "kasagaran nga mineral", "beach sand", "baybayon"], "fact": {"tl": "Ang kuwarts (quartz) ay isa sa pinakakaraniwang mineral sa Earth, at karamihan ng puting buhangin sa beach ay gawa sa maliliit na butil ng kuwarts.", "en": "Quartz is one of the most common minerals on Earth, and most of the white sand on a beach is made of tiny grains of quartz.", "bis": "Ang quartz usa sa labing kasagaran nga mineral sa Earth, ug kadaghanan sa puti nga balas sa baybayon hinimo sa gagmay nga lugas sa quartz."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "diamond-cuts-but-cleaves-g6", "domain": "EARTH_SPACE", "topic": "hardest is not unbreakable", "grades": [6, 7, 8], "terms": ["diyamante", "diamond", "pinakamatigas", "hardest", "basag", "durog", "mabasag", "martilyo", "hammer", "mabuak", "kabuk-on", "scratch", "kalmot", "gasgas", "pinakagahi", "hampak"], "fact": {"tl": "Kahit pinakamatigas ang diyamante at walang ibang mineral na makagasgas dito, hindi ibig sabihin na hindi ito mababasag — kaya pa rin itong durugin ng malakas na hampas.", "en": "Even though diamond is the hardest mineral and nothing else can scratch it, that does not mean it cannot break — a hard blow can still shatter it.", "bis": "Bisan pa nga ang diamante mao ang pinakagahi nga mineral ug walay laing mineral nga makagasgas niini, dili kini magpasabot nga dili kini mabuak — ang kusog nga hampak makabungkag gihapon niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "geode-plain-rock-crystals-inside-g5", "domain": "EARTH_SPACE", "topic": "geodes hide crystals", "grades": [5, 6], "terms": ["geode", "bato", "rock", "kristal", "crystal", "loob", "sorpresa", "guwang", "hollow", "bukol na bato", "tagong kristal", "sulod", "tinago nga kristal", "buak nga bato", "amethyst", "kuwarts", "quartz"], "fact": {"tl": "Ang geode ay mukhang ordinaryong bukol na bato sa labas, pero kapag binasag ito, may nakatagong magagandang kristal sa loob na guwang nito.", "en": "A geode looks like a plain lumpy rock on the outside, but when you crack it open, beautiful crystals are hidden inside its hollow center.", "bis": "Ang geode morag ordinaryo nga bukol nga bato sa gawas, apan kon buak-on kini, adunay nindot nga mga kristal nga gitago sulod sa guwang niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "crystals-grow-bigger-when-slower-g6", "domain": "EARTH_SPACE", "topic": "slow cooling makes bigger crystals", "grades": [6, 7], "terms": ["kristal", "crystal", "laki", "mabagal", "bilis", "lumalamig", "cooling", "mas malaki", "kristal nga dako", "hinay nga pagbugnaw", "mas dako nga kristal", "atoms", "atomo", "oras", "panahon", "mineral"], "fact": {"tl": "Kapag napakabagal lumamig ng tunaw na bato, mas malalaking kristal ang nabubuo dahil mas maraming oras ang mga atomo para mag-ayos nang maayos.", "en": "When melted rock cools very slowly, bigger crystals form because the atoms have more time to arrange themselves neatly.", "bis": "Kon hinay kaayo nga mobugnaw ang natunaw nga bato, mas dagko nga mga kristal ang maporma kay mas daghan ang oras sa mga atomo aron mahan-ay nga maayo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "some-minerals-glow-uv-g5", "domain": "EARTH_SPACE", "topic": "fluorescent minerals glow", "grades": [5, 6, 7], "terms": ["mineral", "kumikinang", "nagliliwanag", "glow", "fluorescent", "uv", "ultraviolet", "ilaw", "liwanag", "glowing", "kulay", "blacklight", "black light", "nagsiga", "nagdan-ag", "nagsanag", "modan-ag", "kahayag"], "fact": {"tl": "May ilang mineral na nagliliwanag ng matingkad na kulay kapag tinapatan ng ultraviolet (UV) o blacklight, kahit mukha silang ordinaryong bato sa karaniwang ilaw.", "en": "Some minerals glow with bright colors when ultraviolet (UV) or blacklight shines on them, even though they look like ordinary rock in normal light.", "bis": "Adunay pipila ka mineral nga modan-ag og hayag nga kolor kon ultraviolet (UV) o blacklight ang motungha kanila, bisan og morag ordinaryo lang silang bato sa normal nga kahayag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ruby-sapphire-same-mineral-g6", "domain": "EARTH_SPACE", "topic": "ruby and sapphire are the same mineral", "grades": [6, 7], "terms": ["rubi", "ruby", "sapphire", "mineral", "corundum", "pula", "asul", "red", "blue", "parehong mineral", "iisang mineral", "pareho nga mineral", "kolor", "trace", "kulay", "hiyas", "gemstone", "metal"], "fact": {"tl": "Ang pulang rubi at ang asul na sapphire ay parehong gawa sa iisang mineral na corundum — magkaiba lang ang kulay dahil sa kaunting ibang metal na nahalo.", "en": "Red ruby and blue sapphire are made of the very same mineral, corundum — they differ in color only because of tiny traces of different metals mixed in.", "bis": "Ang pula nga ruby ug ang asul nga sapphire parehong hinimo sa usa lang ka mineral nga corundum — managlahi lang ang kolor tungod sa gamay nga lain nga metal nga nasagol."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gold-can-be-found-in-rivers-g4", "domain": "EARTH_SPACE", "topic": "panning for gold in rivers", "grades": [4, 5, 6], "terms": ["ginto", "gold", "ilog", "river", "panning", "bigat", "mabigat", "lumulubog", "butil", "gold flakes", "pagdulang", "dulang", "bulawan", "suba", "ginto sa ilog", "bulawan sa suba", "gibug-aton", "molunod", "mabug-at"], "fact": {"tl": "May ginto na matatagpuan bilang maliliit na butil sa ilog, at dahil napakabigat ng ginto, lumulubog ito sa ilalim ng palanggana habang hinuhugasan ang buhangin at putik.", "en": "Gold can be found as tiny flakes in rivers, and because gold is so heavy, it sinks to the bottom of a pan while the sand and mud are washed away.", "bis": "Adunay bulawan nga makit-an isip gagmay nga lugas sa suba, ug tungod kay bug-at kaayo ang bulawan, molunod kini sa ilawom sa palanggana samtang hugasan ang balas ug lapok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "stalactites-grow-very-slowly-g6", "domain": "EARTH_SPACE", "topic": "how slowly cave formations grow", "grades": [6, 7], "terms": ["stalactite", "stalagmite", "kweba", "cave", "lumalaki", "mabagal", "tumutulo", "drip", "mineral", "libong taon", "dahan-dahan", "sentimetro", "grow slowly", "hinay nga pagtubo", "langob", "kalibong tuig", "tinulo nga tubig", "motubo"], "fact": {"tl": "Napakabagal lumaki ng mga stalactite sa kweba — kadalasan ay isang sentimetro lamang bawat ilang daang taon — kaya ang malalaki ay libong taon nang ginagawa ng tumutulong tubig.", "en": "Stalactites in a cave grow incredibly slowly — often only about a centimeter every few hundred years — so the big ones have been built by dripping water for thousands of years.", "bis": "Hinay kaayo motubo ang mga stalactite sa langob — sagad mga usa ka sentimetro lang matag pipila ka gatos ka tuig — mao nga ang dagko gibuhat sa tinulo nga tubig sulod sa kalibong tuig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cave-pillar-from-joined-stalactite-g6", "domain": "EARTH_SPACE", "topic": "cave columns form when two meet", "grades": [6, 7], "terms": ["haligi", "column", "pillar", "stalactite", "stalagmite", "nagtagpo", "nagdikit", "kweba", "cave", "nagsanib", "poste", "langob", "nagtapo", "nag-abot", "haligi sa langob", "sulod sa kweba", "magtagbo"], "fact": {"tl": "Kapag ang isang stalactite na bumababa mula sa kisame at ang stalagmite na umaakyat mula sa sahig ay nagtagpo, nagiging isang matibay na haligi (column) ang dalawa.", "en": "When a stalactite growing down from the ceiling and a stalagmite growing up from the floor finally meet, the two join into a single sturdy column.", "bis": "Kon ang stalactite nga nanaog gikan sa kisame ug ang stalagmite nga nagsaka gikan sa salog magtagbo, ang duha mahimong usa ka lig-on nga haligi."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "limestone-from-sea-creatures-g6", "domain": "EARTH_SPACE", "topic": "cave limestone was once sea life", "grades": [6, 7, 8], "terms": ["limestone", "apog", "bato", "kweba", "cave", "dagat", "sea", "kabibe", "shell", "coral", "fossil", "dating dagat", "gikan sa dagat", "langob", "kabhang", "mga hayop sa dagat", "milyong taon"], "fact": {"tl": "Ang limestone na bumubuo ng maraming kweba ay galing sa mga durog na kabibe at coral ng mga hayop sa dagat noong sinaunang panahon, kaya minsan ay may fossil sa loob.", "en": "The limestone that forms many caves came from the crushed shells and coral of ancient sea animals, which is why fossils are sometimes found inside it.", "bis": "Ang limestone nga nagporma sa daghang langob naggikan sa nadugmok nga mga kabhang ug coral sa karaang mga mananap sa dagat, mao nga usahay adunay fossil sa sulod niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "talc-softest-mineral-g6", "domain": "EARTH_SPACE", "topic": "softest mineral is talc", "grades": [6, 7], "terms": ["talc", "talko", "pinakamalambot", "softest", "mohs", "kuko", "fingernail", "baby powder", "pulbos", "mineral", "scratch", "kalmot", "malambot", "humok", "pinakahumok nga mineral", "gasgas", "pulbo"], "fact": {"tl": "Ang talc ang pinakamalambot na mineral sa Mohs scale — napakalambot nito kaya kayang gasgasan ito ng kuko mo, at ginagawa itong baby powder.", "en": "Talc is the softest mineral on the Mohs scale — it is so soft you can scratch it with your fingernail, and it is ground up to make baby powder.", "bis": "Ang talc mao ang pinakahumok nga mineral sa Mohs scale — humok kaayo kini mao nga makalmotan kini sa imong kuko, ug ginagaling kini aron himuong baby powder."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gold-so-soft-mixed-with-metal-g6", "domain": "EARTH_SPACE", "topic": "pure gold is soft", "grades": [6, 7], "terms": ["ginto", "gold", "bulawan", "malambot", "soft", "banat", "bend", "alahas", "jewelry", "hinahaluan", "alloy", "karat", "mahumok", "pure gold", "purong ginto", "gisagolan", "makurba", "lubag", "lunsay"], "fact": {"tl": "Napakalambot ng purong ginto kaya madali itong mabaluktot, kaya hinahaluan ito ng ibang metal upang lumakas bago gawing alahas.", "en": "Pure gold is so soft that it bends easily, so it is mixed with other metals to make it stronger before it is made into jewelry.", "bis": "Ang lunsay nga bulawan humok kaayo mao nga sayon kining makurba, busa gisagolan kini og lain nga metal aron molig-on una himuong alahas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "amethyst-purple-quartz-g5", "domain": "EARTH_SPACE", "topic": "amethyst is purple quartz", "grades": [5, 6], "terms": ["amethyst", "kuwarts", "quartz", "lila", "purple", "violet", "gem", "hiyas", "kristal", "iron", "kulay", "kolor", "lila nga quartz", "tapol", "bakal", "puthaw", "gemstone", "mineral"], "fact": {"tl": "Ang amethyst ay talagang kuwarts (quartz) na naging lila ang kulay dahil sa kaunting bakal at radiation sa loob ng lupa.", "en": "Amethyst is really just quartz that turned purple because of tiny amounts of iron and natural radiation deep in the ground.", "bis": "Ang amethyst sa tinuod quartz ra nga nahimong tapol ang kolor tungod sa gamay nga puthaw ug natural nga radiation sa ilalom sa yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "caves-stay-same-temperature-g5", "domain": "EARTH_SPACE", "topic": "caves keep a steady temperature", "grades": [5, 6, 7], "terms": ["kweba", "cave", "lamig", "init", "temperatura", "temperature", "pareho", "steady", "buong taon", "constant", "langob", "tugnaw", "kanunay", "permi parehas", "walay pagbag-o", "tibuok tuig", "sulod sa langob"], "fact": {"tl": "Sa loob ng malalim na kweba, halos pareho lang ang temperatura buong taon — hindi ito napakainit kapag tag-init o napakalamig kapag tag-ulan.", "en": "Deep inside a cave the temperature stays nearly the same all year — it does not get very hot in summer or very cold in the rainy season.", "bis": "Sa sulod sa lawom nga langob, halos parehas lang ang temperatura tibuok tuig — dili kini init kaayo sa ting-init o bugnaw kaayo sa ting-ulan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "streak-test-mineral-color-g7", "domain": "EARTH_SPACE", "topic": "a mineral streak can differ from its color", "grades": [7, 8], "terms": ["streak", "guhit", "kulay", "color", "mineral", "pulbos", "powder", "gasgas", "tile", "pagkilala", "streak plate", "bakas", "badlis", "gasgas sa tisa", "kolor sa pulbo", "tisa", "identify", "mailhan"], "fact": {"tl": "Kapag iginuhit ang isang mineral sa magaspang na tile, ang kulay ng naiiwang pulbos (streak) ay minsan iba sa kulay ng mismong bato — at nakakatulong ito para makilala ang mineral.", "en": "When a mineral is scraped across rough tile, the color of the powder it leaves (its streak) is sometimes different from the color of the stone itself — and this helps identify the mineral.", "bis": "Kon igasgas ang usa ka mineral sa gaspang nga tisa, ang kolor sa pulbos nga mabilin (streak) usahay lahi sa kolor sa mismong bato — ug makatabang kini aron mailhan ang mineral."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "salt-is-a-mineral-we-eat-g4", "domain": "EARTH_SPACE", "topic": "table salt is a mineral", "grades": [4, 5], "terms": ["asin", "salt", "mineral", "halite", "kristal", "kinakain", "kinaon", "kuwadrado", "cube", "kainin", "mineral na kinakain", "asin nga mineral", "kristal nga asin", "table salt", "kwadrado", "lugas"], "fact": {"tl": "Ang asin na inilalagay natin sa pagkain ay talagang isang mineral na tinatawag na halite, at ang mga butil nito ay maliliit na kuwadradong kristal.", "en": "The salt we put on our food is actually a mineral called halite, and its grains are tiny cube-shaped crystals.", "bis": "Ang asin nga gibutang nato sa pagkaon sa tinuod usa ka mineral nga gitawag og halite, ug ang mga lugas niini gagmay nga kwadrado nga mga kristal."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "magnetite-natural-magnet-g6", "domain": "EARTH_SPACE", "topic": "a natural magnet mineral", "grades": [6, 7], "terms": ["magnetite", "lodestone", "mineral", "magnet", "batobalani", "humihila", "bakal", "iron", "natural", "kompas", "compass", "umaakit", "kinaiyanhon nga magnet", "bato nga magnet", "puthaw", "nagbira", "makabira"], "fact": {"tl": "May natural na mineral na tinatawag na magnetite na talagang magnet — kayang humila ng bakal, at noong unang panahon ay ginamit ito para gumawa ng simpleng kompas.", "en": "There is a natural mineral called magnetite that is really a magnet — it can attract iron, and long ago people used it to make a simple compass.", "bis": "Adunay natural nga mineral nga gitawag og magnetite nga tinuod nga magnet — makabira kini og puthaw, ug kaniadto gigamit kini sa mga tawo aron maghimo og simple nga kompas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "diamond-and-graphite-pencil-g5", "domain": "MATTER", "topic": "pencil lead and diamond same element", "grades": [5, 6], "terms": ["lapis", "pencil", "graphite", "grapayt", "diyamante", "diamond", "karbon", "carbon", "malambot", "matigas", "parehong elemento", "iisang sangkap", "arrangement", "parehong karbon", "humok", "gahi", "kahan-ay sa atomo", "atomo"], "fact": {"tl": "Ang itim na dulo ng lapis (graphite) at ang matigas na diyamante ay parehong gawa lamang sa karbon — magkaiba lang sila dahil sa pagkakaayos ng kanilang mga atomo.", "en": "The black tip of a pencil (graphite) and a hard diamond are both made only of carbon — they are different just because of how their atoms are arranged.", "bis": "Ang itom nga tumoy sa lapis (graphite) ug ang gahi nga diamante parehong hinimo lang sa carbon — managlahi lang sila tungod sa kahan-ay sa ilang mga atomo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cave-animals-lose-eyes-g6", "domain": "LIVING_THINGS", "topic": "cave animals adapted to darkness", "grades": [6, 7, 8], "terms": ["kweba", "cave", "hayop", "animal", "mata", "eyes", "bulag", "blind", "dilim", "darkness", "isda", "fish", "pale", "adaptasyon", "langob", "mananap", "wala mata", "ngitngit", "mawad-an og mata", "buta", "panahon"], "fact": {"tl": "Ang ilang hayop na tumitira sa loob ng madilim na kweba ay nawalan na ng mata o naging bulag sa paglipas ng panahon, dahil walang silbi ang paningin kung saan walang liwanag.", "en": "Some animals that live deep in dark caves have lost their eyes or become blind over time, because eyesight is useless where there is no light.", "bis": "Ang ubang mananap nga nagpuyo sa sulod sa ngitngit nga langob nawad-an na og mata o nahimong buta sa paglabay sa panahon, kay walay pulos ang panan-aw kon walay kahayag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sinkhole-cave-roof-collapse-g7", "domain": "EARTH_SPACE", "topic": "sinkholes from collapsed caves", "grades": [7, 8], "terms": ["sinkhole", "lungga", "butas", "gumuho", "collapse", "kweba", "cave", "limestone", "apog", "biglang lumubog", "ground collapse", "langob", "naghugno", "nahugno", "butas sa yuta", "natumpag", "bangag", "gumuho ang lupa"], "fact": {"tl": "Kapag ang bubong ng isang kwebang nasa ilalim ng lupa ay humina at gumuho, biglang nagkakaroon ng malaking butas sa ibabaw na tinatawag na sinkhole.", "en": "When the roof of an underground cave grows weak and collapses, a large hole can suddenly open at the surface called a sinkhole.", "bis": "Kon ang atop sa usa ka langob nga naa sa ilalom sa yuta moluya ug mahugno, kalit nga maabli ang dako nga bangag sa ibabaw nga gitawag og sinkhole."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "diamond-burns-into-gas-g8", "domain": "MATTER", "topic": "diamonds can burn", "grades": [8, 9, 10], "terms": ["diyamante", "diamond", "sunog", "burn", "nasusunog", "karbon", "carbon", "carbon dioxide", "gas", "init", "mawawala", "masunog", "mahimong gas", "mainit kaayo", "oxygen", "matunaw"], "fact": {"tl": "Dahil purong karbon ang diyamante, kayang masunog ito sa sobrang init na may oxygen at maging gas na carbon dioxide — kaya nawawala ito imbes na matunaw na parang metal.", "en": "Because a diamond is pure carbon, at very high heat with oxygen it can actually burn away into carbon dioxide gas — disappearing rather than melting like a metal.", "bis": "Tungod kay lunsay nga carbon ang diamante, sa init kaayo nga adunay oxygen masunog kini ngadto sa carbon dioxide nga gas — mawala kini imbis matunaw nga sama sa metal."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ore-grade-tons-for-ring-g8", "domain": "EARTH_SPACE", "topic": "how little gold is in ore", "grades": [8, 9], "terms": ["ginto", "gold", "ore", "mineral", "mina", "mining", "tonelada", "ton", "kaunti", "konti", "alahas", "singsing", "ring", "bato", "gamay ra", "gintong ore", "daghang bato", "singsing nga bulawan", "bulawan"], "fact": {"tl": "Napakakaunti ng ginto sa karamihang ore — kailangan minsan ng ilang tonelada ng bato para makakuha ng sapat na ginto para sa isang singsing lamang.", "en": "There is very little gold in most ore — sometimes several tons of rock must be processed just to get enough gold for a single ring.", "bis": "Gamay ra kaayo ang bulawan sa kadaghanang ore — usahay pila ka tonelada nga bato ang kinahanglang prosesohon aron makakuha og igong bulawan para sa usa lang ka singsing."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "crystal-flat-faces-from-atoms-g7", "domain": "EARTH_SPACE", "topic": "why crystals have flat faces", "grades": [7, 8], "terms": ["kristal", "crystal", "patag", "flat", "mukha", "faces", "gilid", "atomo", "atoms", "ayos", "pattern", "repeating", "hugis", "kahan-ay", "patag nga nawong", "kilid", "han-ay sa atomo", "ulit-ulit"], "fact": {"tl": "May patag at tuwid na mga mukha (faces) ang mga kristal dahil ang kanilang mga atomo ay nakaayos sa maayos at paulit-ulit na pattern sa loob.", "en": "Crystals have flat, straight faces because their atoms are stacked in a neat, repeating pattern on the inside.", "bis": "Ang mga kristal adunay patag ug tul-id nga mga nawong tungod kay ang ilang mga atomo nakahan-ay sa hapsay ug balik-balik nga pattern sa sulod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gems-rare-because-special-conditions-g6", "domain": "EARTH_SPACE", "topic": "why gems are rare", "grades": [6, 7], "terms": ["hiyas", "gem", "gemstone", "bihira", "rare", "mahal", "mahalaga", "precious", "init", "presyon", "pressure", "kondisyon", "matagal", "panahon", "mineral", "talagsaon", "espesyal nga init ug presyon", "mga kondisyon"], "fact": {"tl": "Bihira ang mga hiyas dahil kailangan ng napakatagal na panahon at espesyal na init at presyon sa lupa para mabuo ang malilinaw at magagandang kristal na ito.", "en": "Gems are rare because it takes a very long time and special heat and pressure deep in the Earth to grow these clear, beautiful crystals.", "bis": "Talagsaon ang mga gem tungod kay nagkinahanglan og taas kaayo nga panahon ug espesyal nga init ug presyon sa sulod sa yuta aron maporma kining tin-aw ug nindot nga mga kristal."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cave-cricket-long-feelers-g6", "domain": "LIVING_THINGS", "topic": "cave creatures feel their way", "grades": [6, 7], "terms": ["kweba", "cave", "kuliglig", "cricket", "hayop", "animal", "mahabang antennae", "feelers", "ramdam", "dilim", "darkness", "hipo", "langob", "mananap", "tag-as nga antennae", "panghikap", "mangitngit", "mobati", "walang ilaw"], "fact": {"tl": "Maraming hayop sa kweba, tulad ng cave cricket, ang may sobrang habang antennae para maramdaman ang daan nila sa dilim dahil hindi sila makakita.", "en": "Many cave animals, like the cave cricket, have extra-long antennae to feel their way in the dark because they cannot see.", "bis": "Daghang mananap sa langob, sama sa cave cricket, ang adunay tag-as kaayo nga antennae aron mobati sa ilang agianan sa ngitngit kay dili sila makakita."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "obsidian-volcanic-glass-no-crystals-g6", "domain": "EARTH_SPACE", "topic": "obsidian is glass without crystals", "grades": [6, 7], "terms": ["obsidian", "bulkang salamin", "volcanic glass", "walang kristal", "no crystals", "mabilis lumamig", "quick cooling", "matalas", "sharp", "itim", "black", "lava", "kristal", "salamin nga bulkan", "wala kristal", "paspas mobugnaw", "hait", "itom", "matulis"], "fact": {"tl": "Ang obsidian ay parang itim na salamin na nabubuo kapag napakabilis lumamig ng lava, kaya walang panahon ang mga atomo na bumuo ng kristal.", "en": "Obsidian is like black natural glass that forms when lava cools so fast that the atoms have no time to form crystals.", "bis": "Ang obsidian sama sa itom nga natural nga bildo nga maporma kon paspas kaayo mobugnaw ang lava, mao nga walay panahon ang mga atomo nga magporma og kristal."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "iceberg-floats-ice-lighter-g5", "domain": "EARTH_SPACE", "topic": "why icebergs float", "grades": [5, 6], "terms": ["iceberg", "yelo", "lumalutang", "bakit lumulutang", "mas magaan", "tubig", "naglutaw", "ngano naglutaw", "mas gaan", "floats", "frozen water", "lighter"], "fact": {"tl": "Lumulutang ang iceberg dahil ang tubig na nagyeyelo ay nagiging mas magaan kaysa sa likidong tubig, kaya nakakalutaw ang yelo.", "en": "An iceberg floats because water that freezes into ice becomes lighter than liquid water, so the ice can float.", "bis": "Naglutaw ang iceberg tungod kay ang tubig nga nagyelo mahimong mas gaan kaysa sa likido nga tubig, mao nga makalutaw ang yelo."}, "source": "encyclopedia-stable consensus (ice is less dense than liquid water)", "generator": "claude-workflow", "reviewed": false},
  {"id": "iceberg-tip-underwater-g6", "domain": "EARTH_SPACE", "topic": "most of an iceberg is underwater", "grades": [6, 7], "terms": ["iceberg", "tip of the iceberg", "nakalubog", "ilalim ng tubig", "karamihan", "mas malaki ang nasa ilalim", "naunlod", "ubos sa tubig", "kadaghanan", "underwater", "hidden", "nine tenths"], "fact": {"tl": "Karamihan ng isang iceberg—halos siyam na bahagi sa sampu—ay nakalubog sa ilalim ng tubig, kaya ang nakikita lang natin ay ang dulo nito.", "en": "Most of an iceberg—about nine-tenths of it—is hidden underwater, so we only see the small tip above the surface.", "bis": "Ang kadaghanan sa usa ka iceberg—halos siyam ka bahin sa napulo—naunlod sa ilawom sa tubig, mao nga ang atong makita kay ang gamay nga tumoy lang."}, "source": "encyclopedia-stable consensus (about 90% of iceberg volume submerged)", "generator": "claude-workflow", "reviewed": false},
  {"id": "iceberg-freshwater-not-salty-g6", "domain": "EARTH_SPACE", "topic": "icebergs are frozen freshwater", "grades": [6, 7], "terms": ["iceberg", "tabang", "sariwang tubig", "hindi maalat", "galing sa glacier", "tab-ang", "dili parat", "gikan sa glacier", "freshwater", "not salty", "calved from glacier"], "fact": {"tl": "Ang mga iceberg ay yari sa sariwang tubig, hindi maalat na tubig-dagat, dahil nanggaling ang mga ito sa mga glacier sa lupa na nabuo mula sa niyebe.", "en": "Icebergs are made of fresh water, not salty seawater, because they break off from land glaciers that formed from snow.", "bis": "Ang mga iceberg hinimo gikan sa tab-ang nga tubig, dili sa parat nga tubig-dagat, kay naggikan kini sa mga glacier sa yuta nga naporma gikan sa nieve."}, "source": "encyclopedia-stable consensus (icebergs calve from freshwater glaciers)", "generator": "claude-workflow", "reviewed": false},
  {"id": "mariana-trench-everest-fits-g6", "domain": "EARTH_SPACE", "topic": "the deepest ocean trench", "grades": [6, 7], "terms": ["Mariana Trench", "pinakamalalim", "kanal sa dagat", "Bundok Everest", "kasya", "labing lawom", "kanal sa dagat", "mahaom", "Everest", "deepest trench", "Challenger Deep", "fit"], "fact": {"tl": "Ang Mariana Trench ang pinakamalalim na bahagi ng dagat, at napakalalim nito na kahit ang Bundok Everest ay kasya rito at malulubog pa rin.", "en": "The Mariana Trench is the deepest part of the ocean, so deep that even Mount Everest would fit inside it and still be underwater.", "bis": "Ang Mariana Trench mao ang labing lawom nga bahin sa dagat, ug lawom kaayo kini nga bisan ang Bukid sa Everest mahaom sulod niini ug magpabilin pa gihapon nga naunlod."}, "source": "encyclopedia-stable consensus (Challenger Deep ~10,900 m > Everest 8,849 m)", "generator": "claude-workflow", "reviewed": false},
  {"id": "mariana-trench-depth-km-g7", "domain": "EARTH_SPACE", "topic": "how deep the Mariana Trench is", "grades": [7, 8], "terms": ["Mariana Trench", "Challenger Deep", "lalim", "labing-onse kilometro", "kanal", "kalawom", "onse ka kilometro", "kanal sa dagat", "eleven kilometers", "Challenger Deep", "depth"], "fact": {"tl": "Sa pinakamalalim na puntong tinatawag na Challenger Deep, umaabot ang lalim ng Mariana Trench sa halos labing-isang kilometro pababa sa ilalim ng dagat.", "en": "At its deepest point, called the Challenger Deep, the Mariana Trench reaches nearly eleven kilometers straight down below the sea.", "bis": "Sa labing lawom nga punto nga gitawag og Challenger Deep, ang Mariana Trench mokabot og halos onse ka kilometro paubos sa ilawom sa dagat."}, "source": "encyclopedia-stable consensus (Challenger Deep ≈ 10,900 m / ~11 km)", "generator": "claude-workflow", "reviewed": false},
  {"id": "glacier-ice-looks-blue-g6", "domain": "EARTH_SPACE", "topic": "why glacier ice looks blue", "grades": [6, 7], "terms": ["glacier", "yelo", "asul na yelo", "bakit asul", "sinisipsip ang pula", "makapal na yelo", "asul nga yelo", "ngano asul", "gisuyop ang pula", "blue ice", "absorbs red", "glacier ice"], "fact": {"tl": "Mukhang asul ang makapal na yelo ng glacier dahil sinisipsip nito ang pulang liwanag at ibinabalik ang asul na liwanag sa ating mga mata.", "en": "Thick glacier ice looks blue because it soaks up the red light and sends the blue light back to our eyes.", "bis": "Ang baga nga yelo sa glacier murag asul tungod kay gisuyop niini ang pula nga kahayag ug gibalik ang asul nga kahayag sa atong mga mata."}, "source": "encyclopedia-stable consensus (dense glacial ice absorbs longer red wavelengths)", "generator": "claude-workflow", "reviewed": false},
  {"id": "glaciers-hold-most-freshwater-g7", "domain": "EARTH_SPACE", "topic": "glaciers store most of Earth's fresh water", "grades": [7, 8], "terms": ["glacier", "yelo", "sariwang tubig", "nakaimbak", "karamihan ng tubig-tabang", "tab-ang nga tubig", "gitipigan", "kadaghanan", "fresh water", "stored", "frozen", "ice caps"], "fact": {"tl": "Karamihan ng sariwang tubig sa mundo ay hindi sa mga ilog o lawa kundi nakaimbak na nakapirming yelo sa mga glacier at ice cap.", "en": "Most of the world's fresh water is not in rivers or lakes but locked up as frozen ice in glaciers and ice caps.", "bis": "Ang kadaghanan sa tab-ang nga tubig sa kalibotan dili anaa sa mga suba o linaw kondili gitipigan isip nagyelo nga tubig sa mga glacier ug ice cap."}, "source": "encyclopedia-stable consensus (~68% of fresh water is in glaciers/ice caps)", "generator": "claude-workflow", "reviewed": false},
  {"id": "glacier-calving-iceberg-birth-g7", "domain": "EARTH_SPACE", "topic": "how icebergs are born from glaciers", "grades": [7, 8], "terms": ["glacier", "iceberg", "kumalas", "nahulog", "calving", "gumuho ang yelo", "nabugto", "nahulog ang yelo", "calving", "breaks off", "glacier edge", "ocean"], "fact": {"tl": "Nabubuo ang mga iceberg kapag ang dulo ng isang glacier na umabot sa dagat ay kumakalas at nahuhulog sa tubig na may malakas na lagapak.", "en": "Icebergs are born when the front edge of a glacier that reaches the sea cracks off and crashes into the water with a loud splash.", "bis": "Naporma ang mga iceberg kung ang tumoy sa usa ka glacier nga miabot sa dagat mabugto ug mahulog sa tubig nga adunay kusog nga lagapak."}, "source": "encyclopedia-stable consensus (glacial calving)", "generator": "claude-workflow", "reviewed": false},
  {"id": "waterfall-erosion-moves-back-g7", "domain": "EARTH_SPACE", "topic": "waterfalls slowly move upstream", "grades": [7, 8], "terms": ["waterfall", "talon", "umuurong", "gumuguho", "nagagasgas ang bato", "busay", "nag-atras", "nagkagasgas", "moves back", "erosion", "retreats", "upstream"], "fact": {"tl": "Dahan-dahang umuurong pabalik ang isang talon sa paglipas ng panahon dahil ang lumalagpak na tubig ay patuloy na umuukit at gumuguho sa bato sa ilalim.", "en": "A waterfall slowly creeps backward over time because the falling water keeps wearing away and breaking the rock at its base.", "bis": "Hinay-hinay nga nag-atras ang usa ka busay sa paglabay sa panahon tungod kay ang nahulog nga tubig padayon nga nagkagasgas ug nagguba sa bato sa ilawom."}, "source": "AAAS Benchmarks 4C/M2 (running water erodes and shapes land; headward erosion of waterfalls)", "generator": "claude-workflow", "reviewed": false},
  {"id": "angel-falls-tallest-g6", "domain": "EARTH_SPACE", "topic": "the tallest waterfall in the world", "grades": [6, 7], "terms": ["Angel Falls", "pinakamataas na talon", "Venezuela", "tubig", "nagiging ulap", "busay", "labing taas", "nahimong gabon", "tallest waterfall", "mist", "plunge"], "fact": {"tl": "Ang Angel Falls sa Venezuela ang pinakamataas na talon sa mundo, at napakataas nito na ang tubig ay nagiging pinong ulap bago pa umabot sa lupa.", "en": "Angel Falls in Venezuela is the tallest waterfall in the world, so high that the water turns into fine mist before it reaches the ground.", "bis": "Ang Angel Falls sa Venezuela mao ang labing taas nga busay sa kalibotan, ug taas kaayo kini nga ang tubig mahimong pinong gabon una pa kini moabot sa yuta."}, "source": "encyclopedia-stable consensus (Angel Falls ~979 m, world's tallest)", "generator": "claude-workflow", "reviewed": false},
  {"id": "warm-cold-currents-meet-fish-g7", "domain": "EARTH_SPACE", "topic": "warm and cold currents meeting brings fish", "grades": [7, 8], "terms": ["ocean current", "mainit na agos", "malamig na agos", "isda", "nagtatagpo", "sagana", "init nga sulog", "bugnaw nga sulog", "isda nagatapok", "warm current", "cold current", "rich fishing", "nutrients"], "fact": {"tl": "Kung saan nagtatagpo ang mainit at malamig na agos-dagat, madalas doon ang sagana sa isda dahil dinadala ng malamig na tubig ang sustansya mula sa ilalim.", "en": "Where warm and cold ocean currents meet, fishing is often very rich because the cold water carries nutrients up from below.", "bis": "Sa dapit diin magtagbo ang init ug bugnaw nga sulog sa dagat, kasagaran daghan ang isda tungod kay ang bugnaw nga tubig nagdala og sustansya gikan sa ilawom."}, "source": "encyclopedia-stable consensus (upwelling at current convergence supports fisheries)", "generator": "claude-workflow", "reviewed": false},
  {"id": "cold-current-upwelling-g8", "domain": "EARTH_SPACE", "topic": "cold currents bring nutrients up", "grades": [8, 9], "terms": ["cold current", "upwelling", "malamig na agos", "sustansya", "umaakyat ang tubig", "plankton", "bugnaw nga sulog", "nagasaka nga tubig", "upwelling", "nutrients", "plankton", "rises"], "fact": {"tl": "Ang malamig na agos ay madalas na may upwelling, kung saan ang malamig na tubig mula sa kailaliman ay umaakyat at nagdadala ng sustansya na kinakain ng plankton.", "en": "Cold currents often have upwelling, where cold water from the deep rises and brings up nutrients that plankton feed on.", "bis": "Ang bugnaw nga sulog kasagaran adunay upwelling, diin ang bugnaw nga tubig gikan sa kahiladman mosaka ug magdala og sustansya nga gikaon sa plankton."}, "source": "encyclopedia-stable consensus (cold-water upwelling raises nutrients)", "generator": "claude-workflow", "reviewed": false},
  {"id": "gulf-stream-warms-europe-g8", "domain": "EARTH_SPACE", "topic": "a warm current keeps places warm", "grades": [8, 9], "terms": ["Gulf Stream", "mainit na agos", "Europe", "mas mainit ang klima", "dinadala ang init", "init nga sulog", "gidala ang kainit", "warm current", "warms Europe", "carries heat", "milder"], "fact": {"tl": "May mga mainit na agos-dagat tulad ng Gulf Stream na nagdadala ng init mula sa tropiko patungo sa malalayong lugar, kaya mas mainit ang klima roon.", "en": "Some warm ocean currents like the Gulf Stream carry heat from the tropics to faraway places, keeping their climate milder than expected.", "bis": "Adunay init nga mga sulog sa dagat sama sa Gulf Stream nga nagdala og kainit gikan sa tropiko paingon sa layo nga mga dapit, mao nga mas init ang klima didto."}, "source": "encyclopedia-stable consensus (Gulf Stream moderates NW European climate)", "generator": "claude-workflow", "reviewed": false},
  {"id": "caspian-largest-lake-g6", "domain": "EARTH_SPACE", "topic": "the world's largest lake", "grades": [6, 7], "terms": ["Caspian Sea", "pinakamalaking lawa", "tinatawag na dagat", "maalat", "labing dako nga linaw", "ginganlan og dagat", "parat", "largest lake", "called a sea", "salty"], "fact": {"tl": "Ang pinakamalaking lawa sa mundo ay ang Caspian Sea, na napakalaki kaya tinawag itong dagat kahit ito ay isang lawa.", "en": "The world's largest lake is the Caspian Sea, which is so big that people call it a sea even though it is really a lake.", "bis": "Ang labing dako nga linaw sa kalibotan mao ang Caspian Sea, nga dako kaayo mao nga gitawag kining dagat bisan tuod kini usa ka linaw."}, "source": "encyclopedia-stable consensus (Caspian Sea is the largest lake by area)", "generator": "claude-workflow", "reviewed": false},
  {"id": "lake-baikal-deepest-g7", "domain": "EARTH_SPACE", "topic": "the deepest lake in the world", "grades": [7, 8], "terms": ["Lake Baikal", "pinakamalalim na lawa", "Russia", "sariwang tubig", "napakaraming tubig", "labing lawom nga linaw", "tab-ang", "deepest lake", "fresh water", "most water"], "fact": {"tl": "Ang Lake Baikal sa Russia ang pinakamalalim na lawa sa mundo, at naglalaman ito ng napakaraming sariwang tubig kaysa sa kahit aling lawa.", "en": "Lake Baikal in Russia is the deepest lake in the world, and it holds more fresh water than any other lake.", "bis": "Ang Lake Baikal sa Russia mao ang labing lawom nga linaw sa kalibotan, ug naglangkob kini og mas daghan nga tab-ang nga tubig kaysa bisan unsang linaw."}, "source": "encyclopedia-stable consensus (Baikal: deepest lake, ~20% of world's unfrozen fresh surface water)", "generator": "claude-workflow", "reviewed": false},
  {"id": "nile-amazon-longest-rivers-g6", "domain": "EARTH_SPACE", "topic": "the longest rivers in the world", "grades": [6, 7], "terms": ["Nile", "Amazon", "pinakamahabang ilog", "pinakamaraming tubig", "suba", "labing taas nga suba", "pinakadako nga tubig", "longest river", "most water", "Nile", "Amazon"], "fact": {"tl": "Ang Ilog Nile ang itinuturing na pinakamahabang ilog, ngunit ang Ilog Amazon ang nagdadala ng pinakamaraming tubig sa lahat ng ilog.", "en": "The Nile is usually called the longest river, but the Amazon carries more water than any other river in the world.", "bis": "Ang Suba sa Nile mao ang giila nga labing taas nga suba, apan ang Suba sa Amazon mao ang nagdala og pinakadaghang tubig sa tanang suba."}, "source": "encyclopedia-stable consensus (Nile ~ longest; Amazon greatest discharge)", "generator": "claude-workflow", "reviewed": false},
  {"id": "river-starts-source-mouth-g4", "domain": "EARTH_SPACE", "topic": "a river's source and mouth", "grades": [4, 5], "terms": ["ilog", "pinagmulan", "bukal", "bunganga ng ilog", "dagat", "suba", "tinubdan", "baba sa suba", "source", "mouth", "spring", "sea"], "fact": {"tl": "Nagsisimula ang isang ilog sa isang pinagmulan tulad ng bukal o natutunaw na yelo sa bundok, at nagtatapos sa bunganga nito kung saan ito dumadaloy sa dagat o lawa.", "en": "A river begins at a source such as a spring or melting mountain ice, and ends at its mouth where it flows into the sea or a lake.", "bis": "Ang usa ka suba magsugod sa usa ka tinubdan sama sa tuburan o natunaw nga yelo sa bukid, ug matapos sa baba niini diin kini moagas sa dagat o linaw."}, "source": "encyclopedia-stable consensus (river source and mouth)", "generator": "claude-workflow", "reviewed": false},
  {"id": "artesian-well-water-rises-g7", "domain": "EARTH_SPACE", "topic": "why artesian well water rises by itself", "grades": [7, 8], "terms": ["artesian well", "balon", "bukal na sumusulpot", "presyon", "aquifer", "artesianong balon", "atabay", "tubig nga mosulbo", "presyon", "artesian well", "pressure", "rises by itself"], "fact": {"tl": "Sa isang artesian well, ang tubig ay umaagos paitaas nang kusa nang hindi kailangan ng bomba dahil ang tubig sa aquifer ay nasa ilalim ng natural na presyon.", "en": "In an artesian well, water flows upward on its own without a pump because the water in the aquifer is under natural pressure.", "bis": "Sa usa ka artesian well, ang tubig moagas pataas nga kinaugalingon nga walay pump tungod kay ang tubig sa aquifer naa sa ilawom sa natural nga presyon."}, "source": "encyclopedia-stable consensus (artesian aquifer / confined pressure)", "generator": "claude-workflow", "reviewed": false},
  {"id": "aquifer-recharge-rain-g7", "domain": "EARTH_SPACE", "topic": "how aquifers get refilled", "grades": [7, 8], "terms": ["aquifer", "tubig sa ilalim", "nasasariwa", "ulan", "tumatagos", "groundwater", "tubig sa ilalom", "gibag-o", "ulan", "mosulod", "recharge", "rain soaks in", "refilled"], "fact": {"tl": "Nasisariwa o napupuno muli ang isang aquifer kapag ang tubig-ulan ay dahan-dahang tumatagos pababa sa lupa at bato hanggang sa umabot ito sa nakaimbak na tubig sa ilalim.", "en": "An aquifer is refilled when rainwater slowly soaks down through the soil and rock until it reaches the stored water underground.", "bis": "Ang usa ka aquifer mapuno pag-usab kung ang tubig-ulan hinay-hinay nga mosulod paubos sa yuta ug bato hangtod nga moabot kini sa gitipigan nga tubig sa ilawom."}, "source": "encyclopedia-stable consensus (aquifer recharge by infiltration)", "generator": "claude-workflow", "reviewed": false},
  {"id": "deep-ocean-cold-dark-g6", "domain": "EARTH_SPACE", "topic": "the deep ocean is dark and cold", "grades": [6, 7], "terms": ["deep ocean", "kalaliman", "madilim", "malamig", "walang liwanag ng araw", "kahiladman", "ngitngit", "bugnaw", "deep ocean", "dark", "cold", "no sunlight"], "fact": {"tl": "Sa malalim na bahagi ng dagat, palaging madilim at napakalamig dahil hindi na umaabot doon ang liwanag ng araw.", "en": "In the deep parts of the ocean it is always dark and very cold because sunlight cannot reach down that far.", "bis": "Sa lawom nga bahin sa dagat, kanunay ngitngit ug bugnaw kaayo tungod kay ang kahayag sa adlaw dili na makaabot ngadto."}, "source": "encyclopedia-stable consensus (sunlight does not penetrate the deep ocean)", "generator": "claude-workflow", "reviewed": false},
  {"id": "trench-pressure-crush-g8", "domain": "EARTH_SPACE", "topic": "crushing pressure in ocean trenches", "grades": [8, 9], "terms": ["ocean trench", "presyon ng tubig", "dumudurog", "kanal", "Mariana", "kusog nga presyon", "modugmok", "kanal sa dagat", "water pressure", "crushing", "deep trench"], "fact": {"tl": "Sa ilalim ng isang malalim na kanal-dagat, ang bigat ng tubig sa itaas ay nagdudulot ng napakalakas na presyon na kayang durugin ang karamihan ng mga makina.", "en": "At the bottom of a deep ocean trench, the weight of the water above presses down with crushing pressure strong enough to wreck most machines.", "bis": "Sa ilawom sa lawom nga kanal sa dagat, ang gibug-aton sa tubig sa ibabaw maghatag og kusog kaayo nga presyon nga makadugmok sa kadaghanan sa mga makina."}, "source": "encyclopedia-stable consensus (hydrostatic pressure ~1,000 atm at Challenger Deep)", "generator": "claude-workflow", "reviewed": false},
  {"id": "icebergs-danger-ships-g6", "domain": "EARTH_SPACE", "topic": "why icebergs are dangerous to ships", "grades": [6, 7], "terms": ["iceberg", "barko", "mapanganib", "nakatago sa ilalim", "Titanic", "panganib", "peligroso", "tago sa ilawom", "danger to ships", "hidden part", "Titanic"], "fact": {"tl": "Mapanganib ang mga iceberg sa mga barko dahil ang pinakamalaking bahagi nito ay nakatago sa ilalim ng tubig kung saan hindi ito agad nakikita.", "en": "Icebergs are dangerous to ships because their biggest part is hidden underwater where it cannot easily be seen.", "bis": "Ang mga iceberg peligroso sa mga barko tungod kay ang labing dako nga bahin niini natago sa ilawom sa tubig diin dili kini dali makita."}, "source": "encyclopedia-stable consensus (submerged iceberg mass; Titanic 1912)", "generator": "claude-workflow", "reviewed": false},
  {"id": "glacier-moves-slowly-g6", "domain": "EARTH_SPACE", "topic": "glaciers flow like very slow rivers", "grades": [6, 7], "terms": ["glacier", "umuusad", "mabagal na ilog ng yelo", "gumagalaw", "dahan-dahan", "molihok", "hinay", "suba sa yelo", "flows slowly", "river of ice", "moves"], "fact": {"tl": "Bagama't tila nakatigil ang isang glacier, ito ay parang napakabagal na ilog ng yelo na patuloy na umuusad pababa dahil sa sarili nitong bigat.", "en": "Even though a glacier looks like it is standing still, it is really a very slow river of ice that keeps creeping downhill under its own weight.", "bis": "Bisan og morag wala maglihok ang usa ka glacier, kini sa tinuod usa ka hinay kaayo nga suba sa yelo nga padayon nga moagas paubos tungod sa kaugalingong gibug-aton."}, "source": "encyclopedia-stable consensus (glaciers flow under gravity)", "generator": "claude-workflow", "reviewed": false},
  {"id": "plunge-pool-waterfall-g6", "domain": "EARTH_SPACE", "topic": "the deep pool at the bottom of a waterfall", "grades": [6, 7], "terms": ["plunge pool", "talon", "malalim na lawa sa ilalim", "humukay", "busay", "gilalom nga linaw", "gikalot", "plunge pool", "deep pool", "waterfall base", "hollows out"], "fact": {"tl": "Sa paanan ng maraming talon ay may malalim na lawa na tinatawag na plunge pool, na hinukay ng tubig na walang tigil na bumabagsak doon.", "en": "At the foot of many waterfalls there is a deep pool called a plunge pool, hollowed out by the water crashing down again and again.", "bis": "Sa tiilan sa daghang busay adunay lawom nga linaw nga gitawag og plunge pool, nga gikalot sa tubig nga walay hunong nga nahulog didto."}, "source": "encyclopedia-stable consensus (plunge pool erosion)", "generator": "claude-workflow", "reviewed": false},
  {"id": "groundwater-cave-formation-g8", "domain": "EARTH_SPACE", "topic": "groundwater carves caves", "grades": [8, 9], "terms": ["groundwater", "tubig sa ilalim", "kuweba", "tinutunaw ang bato", "limestone", "langob", "gitunaw nga bato", "tubig sa ilawom", "carves caves", "dissolves rock", "limestone"], "fact": {"tl": "Ang tubig sa ilalim ng lupa ay maaaring dahan-dahang tunawin ang malambot na bato gaya ng limestone, at sa paglipas ng panahon ay makakabuo ito ng malalaking kuweba.", "en": "Groundwater can slowly dissolve soft rock such as limestone, and over long ages this carves out large caves underground.", "bis": "Ang tubig sa ilawom sa yuta mahimong hinay-hinay nga motunaw sa humok nga bato sama sa limestone, ug sa paglabay sa panahon makahimo kini og dagkong langob."}, "source": "encyclopedia-stable consensus (karst cave formation by groundwater dissolution)", "generator": "claude-workflow", "reviewed": false},
  {"id": "deep-sea-trench-life-g7", "domain": "EARTH_SPACE", "topic": "life lives even in the deepest trench", "grades": [7, 8], "terms": ["deep sea trench", "buhay", "nabubuhay", "kahit pinakamalalim", "hayop", "may kinabuhi", "bisan labing lawom", "nabuhi", "life in trench", "creatures", "deepest"], "fact": {"tl": "Kahit sa pinakamalalim na kanal-dagat na madilim at may matinding presyon, may mga kakaibang hayop na nabubuhay pa rin doon.", "en": "Even in the deepest ocean trench, which is dark and under crushing pressure, there are still strange creatures that manage to live.", "bis": "Bisan sa labing lawom nga kanal sa dagat nga ngitngit ug adunay kusog nga presyon, aduna gihapoy katingad-an nga mga mananap nga nabuhi didto."}, "source": "encyclopedia-stable consensus (amphipods and other life found in Challenger Deep)", "generator": "claude-workflow", "reviewed": false},
  {"id": "icebergs-drift-melt-g6", "domain": "EARTH_SPACE", "topic": "icebergs drift and slowly melt", "grades": [6, 7], "terms": ["iceberg", "umaanod", "unti-unting natutunaw", "agos", "mas mainit na tubig", "naanod", "hinay-hinay natunaw", "sulog", "drifts", "melts", "warmer water"], "fact": {"tl": "Ang mga iceberg ay umaanod kasama ng agos ng dagat patungo sa mas mainit na tubig, kung saan unti-unti silang natutunaw at lumiliit.", "en": "Icebergs drift along with ocean currents toward warmer water, where they slowly melt and shrink away.", "bis": "Ang mga iceberg maanod uban sa sulog sa dagat paingon sa mas init nga tubig, diin sila hinay-hinay nga matunaw ug mokunhod."}, "source": "encyclopedia-stable consensus (icebergs drift with currents and melt)", "generator": "claude-workflow", "reviewed": false},
  {"id": "hot-spring-minerals-color-g7", "domain": "EARTH_SPACE", "topic": "why hot springs can be colorful", "grades": [7, 8], "terms": ["hot spring", "mainit na bukal", "mineral", "makukulay", "bakterya", "init nga tuburan", "kolorado", "minerales", "hot spring", "minerals", "colorful", "bacteria"], "fact": {"tl": "May mga mainit na bukal na makukulay dahil sa mga mineral na natunaw sa tubig at sa mga maliliit na nilalang na nabubuhay sa init.", "en": "Some hot springs are brightly colored because of minerals dissolved in the water and tiny living things that thrive in the heat.", "bis": "Adunay init nga mga tuburan nga kolorado tungod sa mga minerales nga natunaw sa tubig ug sa gagmay nga mga binuhat nga nabuhi sa kainit."}, "source": "encyclopedia-stable consensus (mineral- and microbe-colored hot springs)", "generator": "claude-workflow", "reviewed": false},
  {"id": "glaciers-ice-age-record-g8", "domain": "EARTH_SPACE", "topic": "glacier ice holds ancient air", "grades": [8, 9], "terms": ["glacier", "yelo", "lumang hangin", "bula", "talaan ng nakaraan", "karaang hangin", "tipik sa hangin", "tigom nga yelo", "ancient air", "bubbles", "record of past", "ice core"], "fact": {"tl": "Sa loob ng makapal na yelo ng glacier ay may maliliit na bula ng lumang hangin, kaya nagagamit ito ng mga siyentista para malaman ang lagay ng klima noong unang panahon.", "en": "Deep inside thick glacier ice are tiny bubbles of ancient air, so scientists use it to learn what the climate was like long ago.", "bis": "Sa sulod sa baga nga yelo sa glacier adunay gagmay nga bula sa karaang hangin, mao nga gigamit kini sa mga siyentista aron mahibaloan ang klima sa unang panahon."}, "source": "encyclopedia-stable consensus (ice cores trap ancient atmosphere)", "generator": "claude-workflow", "reviewed": false},
  {"id": "chameleon-color-crystals-g6", "domain": "LIVING_THINGS", "topic": "how chameleons change color with crystals", "grades": [6, 7, 8], "terms": ["chameleon", "hameleon", "bunglon", "color change crystal", "kristal sa panit", "nanocrystal", "kulay galing sa kristal hindi tina", "kolor gikan sa kristal dili tina", "nag-aayos ng kristal", "gi-usab ang gilay-on sa kristal", "skin crystals reflect light", "kristal nga magbanaag sa kahayag", "paano nagbabago ang kulay", "unsaon pag-usab sa kolor", "tiny crystals stretch", "kulay hindi pintura"], "fact": {"tl": "Hindi tina ang dahilan ng pagpapalit-kulay ng chameleon — may mga maliliit na kristal sa balat nito na inuunat o pinipigtas para baguhin kung anong kulay ng liwanag ang sinasalamin pabalik.", "en": "A chameleon does not change color by moving paint — it has tiny crystals in its skin that it spaces closer or farther apart to change which color of light bounces back.", "bis": "Ang chameleon dili mag-usab og kolor pinaagi sa tina — adunay gagmay nga mga kristal sa panit niini nga iyang pasid-okon o pa-lay-on aron usbon kung unsa nga kolor sa kahayag ang ipasanag balik."}, "source": "encyclopedia-stable consensus (iridophore nanocrystals)", "generator": "claude-workflow", "reviewed": false},
  {"id": "chameleon-eyes-separate-g5", "domain": "LIVING_THINGS", "topic": "chameleon eyes move separately", "grades": [4, 5, 6], "terms": ["chameleon eyes", "mata ng hameleon", "mata sa bunglon", "two directions at once", "magkaibang direksyon ang mata", "magkalahi ang direksyon sa mata", "umiikot ang mata nang magkahiwalay", "nagtuyok ang mata og bulag", "independent eyes 360", "makikita ang likod at harap", "makita ang luyo ug atubangan", "nakatingin sa magkaibang lugar", "scanning for food", "panangga sa kaaway"], "fact": {"tl": "Ang dalawang mata ng chameleon ay maaaring gumalaw nang magkahiwalay, kaya kaya nitong tumingin sa dalawang magkaibang direksyon sa parehong oras para maghanap ng pagkain at magbantay sa kaaway.", "en": "A chameleon's two eyes can move on their own, so it can look in two different directions at the same time to hunt for food and watch for enemies.", "bis": "Ang duha ka mata sa chameleon makalihok nga magbulag, mao nga makahimo kini sa pagtan-aw sa duha ka lahi nga direksyon sa samang higayon aron mangita og pagkaon ug magbantay sa kaaway."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "chameleon-tongue-fast-g5", "domain": "LIVING_THINGS", "topic": "chameleon shoots out a long sticky tongue", "grades": [4, 5, 6], "terms": ["chameleon tongue", "dila ng hameleon", "dila sa bunglon", "mabilis na dila", "paspas nga dila", "mas mahaba pa sa katawan ang dila", "mas taas pa sa lawas ang dila", "sticky tongue catches insect", "madikit na dila", "pilit nga dila", "bumubunot ng dila parang tirador", "ginabuhi ang dila sama sa tirador", "sumasakmal ng insekto", "mas mabilis pa sa kisap-mata"], "fact": {"tl": "Ang dila ng chameleon ay maaaring lumabas nang mas mahaba pa sa buong katawan nito, at napakabilis nitong sumakmal ng insekto — mas mabilis pa sa isang kisap-mata.", "en": "A chameleon's tongue can shoot out longer than its whole body, and it snaps onto an insect faster than the blink of an eye.", "bis": "Ang dila sa chameleon makagula nga mas taas pa sa tibuok lawas niini, ug paspas kaayo kini modakop og insekto — mas paspas pa sa usa ka pamilok."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "gecko-van-der-waals-g7", "domain": "LIVING_THINGS", "topic": "why geckos stick without glue", "grades": [7, 8, 9], "terms": ["gecko", "tuko", "tiki", "sticky feet no glue", "walang pandikit ang paa", "walay pandikit ang tiil", "milyon-milyong balahibo sa paa", "minilyon nga balhibo sa tiil", "van der waals force", "molecular attraction", "dumidikit sa salamin", "modikit bisan sa salamin", "sticks even upside down", "nakakapit kahit baligtad", "hairs called setae", "bakit kumakapit sa pader"], "fact": {"tl": "Hindi dahil sa pandikit kumakapit ang tuko sa pader — milyon-milyong napakaliliit na balahibo sa paa nito ang sumasabit sa ibabaw sa antas ng molekula, kaya kayang kumapit kahit sa salamin o baligtad sa kisame.", "en": "A gecko does not stick to walls with glue — millions of tiny hairs on its toes cling to the surface at the level of molecules, letting it hold on even to glass or upside down on a ceiling.", "bis": "Ang tuko dili modikit sa bungbong tungod sa pandikit — minilyon nga gagmay kaayo nga mga balhibo sa tiil niini ang mokapyot sa ibabaw sa lebel sa molekula, mao nga makakapyot kini bisan sa salamin o pabaliskad sa kisame."}, "source": "encyclopedia-stable consensus (van der Waals forces, setae)", "generator": "claude-workflow", "reviewed": false},
  {"id": "gecko-no-eyelids-lick-g6", "domain": "LIVING_THINGS", "topic": "geckos lick their eyes clean", "grades": [5, 6, 7], "terms": ["gecko eyes", "mata ng tuko", "mata sa tiki", "walang talukap ang mata", "walay tabontabon sa mata", "dinidilaan ang sariling mata", "ginatilaan ang kaugalingong mata", "clear scale over eye", "malinis na mata gamit ang dila", "lick eyes clean", "no eyelids cannot blink", "hindi kumukurap", "dili makapamilok", "spectacle eye cover"], "fact": {"tl": "Karamihan ng tuko ay walang talukap sa mata kaya hindi sila kumukurap; sa halip, dinidilaan nila ang sarili nilang mata para panatilihin itong malinis at basa.", "en": "Most geckos have no eyelids and cannot blink, so they lick their own eyes with their tongue to keep them clean and moist.", "bis": "Kadaghanan sa mga tuko walay tabontabon sa mata mao nga dili sila makapamilok; hinuon, ilang tilaan ang ilang kaugalingong mata aron magpabiling limpyo ug basa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "komodo-venom-g7", "domain": "LIVING_THINGS", "topic": "the Komodo dragon has venom", "grades": [7, 8, 9], "terms": ["komodo dragon", "komodo", "bayawak ng komodo", "venom glands", "may kamandag", "adunay hilo", "venom thins blood lowers pressure", "kamandag na nagpapanipis ng dugo", "hilo nga magpanipis sa dugo", "biggest lizard venom", "kagat na may lason", "pinakadakong butiki nga adunay hilo", "prey weakens", "nanghihina ang biktima", "naluya ang biktima"], "fact": {"tl": "Bukod sa malaki at malakas, may mga gland ng kamandag ang Komodo dragon sa baba nito; ang kamandag na ito ay nagpapanipis ng dugo at nagpapababa ng presyon ng biktima, kaya unti-unti itong nanghihina.", "en": "Besides being huge and strong, the Komodo dragon has venom glands in its mouth; this venom thins the blood and lowers the blood pressure of its prey, so the prey slowly weakens.", "bis": "Gawas sa pagkadako ug pagkakusgan, ang Komodo dragon adunay mga glandula sa hilo sa baba niini; kini nga hilo magpanipis sa dugo ug magpaubos sa presyon sa biktima, mao nga hinay-hinay kining naluya."}, "source": "encyclopedia-stable consensus (Komodo venom glands)", "generator": "claude-workflow", "reviewed": false},
  {"id": "komodo-smell-tongue-g6", "domain": "LIVING_THINGS", "topic": "Komodo dragon smells with its tongue", "grades": [5, 6, 7], "terms": ["komodo dragon smell", "amoy ng komodo", "baho sa komodo", "forked tongue", "sangang dila", "sanga nga dila", "amoy gamit ang dila", "panimaho gamit ang dila", "tracks prey from far", "nahahanap ang biktima sa malayo", "makit-an ang biktima sa layo", "jacobson organ", "dinadampot ng dila ang amoy sa hangin", "kuhaon sa dila ang baho sa hangin", "kilometers away smell"], "fact": {"tl": "Ginagamit ng Komodo dragon ang sangang dila nito para makaamoy — sinasalo ng dila ang mga particle ng amoy sa hangin, kaya kaya nitong matunton ang biktima kahit ilang kilometro ang layo.", "en": "The Komodo dragon uses its forked tongue to smell — the tongue catches scent particles from the air, so it can track prey even kilometers away.", "bis": "Gamiton sa Komodo dragon ang sanga niini nga dila aron makapanimaho — kuhaon sa dila ang mga partikulo sa baho gikan sa hangin, mao nga makasubay kini sa biktima bisan pila ka kilometro ang gilay-on."}, "source": "encyclopedia-stable consensus (Jacobson's organ)", "generator": "claude-workflow", "reviewed": false},
  {"id": "komodo-virgin-birth-g8", "domain": "LIVING_THINGS", "topic": "female Komodo dragons can lay eggs without a male", "grades": [8, 9, 10], "terms": ["komodo dragon eggs", "itlog ng komodo", "itlog sa komodo", "parthenogenesis", "walang lalaki na nagkaanak", "walay laki nakaanak", "babaeng komodo nangitlog mag-isa", "baye nga komodo nangitlog nga mag-isa", "virgin birth reptile", "itlog na walang ama", "itlog nga walay amahan", "reproduce without mating", "nakakapagparami nang walang kapareha", "makaanak bisan walay kapares"], "fact": {"tl": "Sa ilang pagkakataon, ang isang babaeng Komodo dragon ay nakakapaglagay ng itlog na nabubuhay kahit walang lalaking kapareha — isang bihirang paraan ng pagpaparami na tinatawag na parthenogenesis.", "en": "In some cases, a female Komodo dragon can lay eggs that hatch even without a male partner — a rare way of reproducing called parthenogenesis.", "bis": "Sa pipila ka higayon, ang usa ka baye nga Komodo dragon makahimo og itlog nga mapusa bisan walay laki nga kapares — usa ka talagsaon nga paagi sa pagsanay nga gitawag og parthenogenesis."}, "source": "encyclopedia-stable consensus (parthenogenesis in Komodo dragons)", "generator": "claude-workflow", "reviewed": false},
  {"id": "croc-vs-gator-snout-g6", "domain": "LIVING_THINGS", "topic": "how to tell a crocodile from an alligator", "grades": [5, 6, 7], "terms": ["crocodile vs alligator", "buwaya at aligator", "krokodilo ug aligator", "pagkakaiba ng buwaya at aligator", "kalainan sa buwaya ug aligator", "matulis na nguso buwaya", "tinurok nga simod buwaya", "bilog na nguso aligator", "lingin nga simod aligator", "V shape U shape snout", "makikita ang ngipin kahit sarado", "makita ang ngipon bisan sira", "teeth show when mouth closed", "ngiti ng buwaya"], "fact": {"tl": "Ang buwaya ay may matulis na nguso na hugis-V at nakikita pa rin ang ilang ngipin kahit nakasara ang bibig, samantalang ang aligator ay may mas bilog na nguso na hugis-U at natatago ang mga ngipin sa ibaba kapag sarado ang bibig.", "en": "A crocodile has a pointed V-shaped snout and some of its teeth still show even when its mouth is closed, while an alligator has a wider U-shaped snout and its lower teeth are hidden when its mouth shuts.", "bis": "Ang buwaya adunay tinurok nga simod nga hulagway-V ug makita gihapon ang pipila ka ngipon bisan sirado ang baba, samtang ang aligator adunay mas lingin nga simod nga hulagway-U ug matago ang ubos nga mga ngipon kung sirado ang baba."}, "source": "Britannica; PBS Nature; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "croc-salt-glands-g7", "domain": "LIVING_THINGS", "topic": "saltwater crocodiles get rid of salt through their tongue", "grades": [7, 8, 9], "terms": ["saltwater crocodile salt", "buwaya sa dagat asin", "buwaya sa parat tubig asin", "salt glands tongue", "ginagawas ang asin sa dila", "ipagawas ang asin sa dila", "crying crocodile tears salt", "luha ng buwaya may asin", "luha sa buwaya adunay asin", "nabubuhay sa maalat na tubig", "mabuhi sa parat nga tubig", "alligator cannot live saltwater", "bakit kaya ng buwaya ang dagat", "ngano kaya sa buwaya ang dagat"], "fact": {"tl": "Kaya nakakapamuhay ang buwaya sa maalat na tubig-dagat dahil may mga espesyal na gland sa dila nito na nagtatapon ng sobrang asin sa katawan — bagay na hindi kayang gawin ng aligator.", "en": "A crocodile can live in salty seawater because it has special glands on its tongue that get rid of extra salt from its body — something an alligator cannot do.", "bis": "Ang buwaya makapuyo sa parat nga tubig-dagat tungod kay aduna kini espesyal nga mga glandula sa dila nga magpagawas sa sobra nga asin gikan sa lawas niini — usa ka butang nga dili mahimo sa aligator."}, "source": "encyclopedia-stable consensus (lingual salt glands)", "generator": "claude-workflow", "reviewed": false},
  {"id": "croc-stones-stomach-g7", "domain": "LIVING_THINGS", "topic": "crocodiles swallow stones", "grades": [6, 7, 8], "terms": ["crocodile swallows stones", "buwaya lumulunok ng bato", "buwaya magtulon og bato", "gastrolith", "bato sa tiyan ng buwaya", "bato sa tiyan sa buwaya", "stones grind food", "binabasag ng bato ang pagkain", "dugmokon sa bato ang pagkaon", "helps stay underwater", "tumitimbang para sumisid", "magpabug-at aron molugdang", "crushing food in stomach", "ballast under water"], "fact": {"tl": "Ang mga buwaya ay sadyang lumulunok ng maliliit na bato na nananatili sa kanilang tiyan; nakakatulong ang mga ito para durugin ang pagkain at para makapanatili silang nakalubog sa tubig.", "en": "Crocodiles deliberately swallow small stones that stay in their stomach; these help grind up food and also help the crocodile stay sunk under the water.", "bis": "Ang mga buwaya tinuyo nga magtulon og gagmay nga mga bato nga magpabilin sa ilang tiyan; kini makatabang sa pagdugmok sa pagkaon ug makatabang usab nga magpabiling naunlod ang buwaya sa tubig."}, "source": "encyclopedia-stable consensus (gastroliths)", "generator": "claude-workflow", "reviewed": false},
  {"id": "croc-death-roll-g6", "domain": "LIVING_THINGS", "topic": "crocodiles spin to tear food (death roll)", "grades": [6, 7, 8], "terms": ["crocodile death roll", "buwaya umiikot", "buwaya magtuyok", "spinning to tear meat", "umiikot para pagputul-putulin", "magtuyok aron gision", "cannot chew tear instead", "hindi marunong ngumuya", "dili kahibalo mag-usap", "powerful twist", "malakas na pag-ikot", "kusog nga pagtuyok", "biktima sa tubig", "grabbing prey and rolling"], "fact": {"tl": "Hindi marunong ngumuya ang buwaya, kaya kapag malaki ang biktima, hinahawakan ito at mabilis na umiikot ang buwaya sa tubig para pagputul-putulin ang laman — tinatawag itong death roll.", "en": "A crocodile cannot chew, so when its prey is large, it grips the prey and spins quickly in the water to tear off pieces of meat — this is called the death roll.", "bis": "Ang buwaya dili kahibalo mag-usap, mao nga kung dako ang biktima, kuptan kini ug paspas nga magtuyok ang buwaya sa tubig aron gision ang unod — gitawag kini og death roll."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "croc-temperature-sex-g8", "domain": "LIVING_THINGS", "topic": "nest temperature decides crocodile sex", "grades": [7, 8, 9], "terms": ["crocodile egg temperature", "temperatura ng itlog ng buwaya", "temperatura sa itlog sa buwaya", "nest heat decides male female", "init ng pugad lalaki o babae", "kainit sa salag laki o baye", "temperature dependent sex", "walang chromosome ang nagtatakda", "dili chromosome ang magtino", "mas mainit mas maraming lalaki", "mas init mas daghan laki", "temperature determines gender", "bakit lalaki o babae", "ngano laki o baye"], "fact": {"tl": "Sa mga buwaya, hindi chromosome ang nagtatakda kung lalaki o babae ang lalabas sa itlog kundi ang temperatura ng pugad — may tiyak na init na gumagawa ng mas maraming lalaki at iba namang init na gumagawa ng mas maraming babae.", "en": "In crocodiles, it is not chromosomes but the temperature of the nest that decides whether an egg becomes male or female — certain warmth makes more males and other warmth makes more females.", "bis": "Sa mga buwaya, dili chromosome ang magtino kung laki o baye ang mogula sa itlog kondili ang temperatura sa salag — adunay piho nga kainit nga maghimo og mas daghang laki ug lahi nga kainit nga maghimo og mas daghang baye."}, "source": "encyclopedia-stable consensus (temperature-dependent sex determination)", "generator": "claude-workflow", "reviewed": false},
  {"id": "croc-mother-carries-babies-g5", "domain": "LIVING_THINGS", "topic": "mother crocodiles carry their babies in their mouth", "grades": [4, 5, 6], "terms": ["mother crocodile babies", "inang buwaya anak", "inahan nga buwaya anak", "carries babies in mouth", "binubuhat ang anak sa bibig", "gisapnay ang anak sa baba", "gentle despite fierce", "maingat kahit mabangis", "mabinantayon bisan bangis", "protects hatchlings", "binabantayan ang itlog", "bantayan ang itlog", "helps eggs hatch", "tumutulong sa pagpisa", "tinatangay sa tubig ang anak"], "fact": {"tl": "Bagaman mabangis ang buwaya, ang inang buwaya ay maingat na binubuhat ang kanyang mga bagong-pisang anak sa loob ng kanyang malaking bibig para dalhin sila nang ligtas patungo sa tubig.", "en": "Even though crocodiles are fierce, a mother crocodile gently carries her newly hatched babies inside her huge mouth to bring them safely to the water.", "bis": "Bisan bangis ang buwaya, ang inahan nga buwaya mabinantayon nga magsapnay sa iyang bag-ong napusa nga mga anak sulod sa iyang dakong baba aron dad-on sila nga luwas ngadto sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ph-crocodile-name-mindanao-g6", "domain": "LIVING_THINGS", "topic": "the Philippine crocodile and where it lives", "grades": [5, 6, 7], "terms": ["philippine crocodile", "buwayang Pilipino", "bukarot", "crocodylus mindorensis", "endemic sa Pilipinas", "endemiko sa Pilipinas", "matatagpuan lamang sa Pilipinas", "makita lamang sa Pilipinas", "freshwater crocodile small", "maliit na buwaya sa ilog", "gamay nga buwaya sa suba", "rare protected critically endangered", "bihira at pinoprotektahan", "talagsaon ug gipanalipdan", "Bukarot ngalan sa buwaya", "tubig-tabang"], "fact": {"tl": "Ang buwayang Pilipino (Crocodylus mindorensis) ay isang maliit na buwaya sa tabang na tubig na matatagpuan lamang sa Pilipinas; ito ay isa sa pinakananganganib na buwaya sa mundo at mahigpit na pinoprotektahan.", "en": "The Philippine crocodile (Crocodylus mindorensis) is a small freshwater crocodile found only in the Philippines; it is one of the most endangered crocodiles in the world and is strictly protected.", "bis": "Ang buwaya nga Pilipino (Crocodylus mindorensis) usa ka gamay nga buwaya sa tab-ang nga tubig nga makita lamang sa Pilipinas; usa kini sa labing namiligro nga buwaya sa kalibutan ug higpit nga gipanalipdan."}, "source": "IUCN Red List; encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "frog-tadpole-tail-reabsorb-g6", "domain": "LIVING_THINGS", "topic": "a tadpole reabsorbs its own tail", "grades": [6, 7, 8], "terms": ["tadpole tail disappears", "buntot ng ulo-ulo nawawala", "ikog sa lawalawa nawala", "reabsorbs tail", "nilulunok ng katawan ang buntot", "gisuyop sa lawas ang ikog", "tail becomes food", "ginagawang sustansya ang buntot", "gihimong sustansya ang ikog", "not falling off", "hindi nahuhulog ang buntot", "dili matangtang ang ikog", "metamorphosis frog tail", "paanong nawawala ang buntot", "ngano nawala ang ikog", "palaka butete"], "fact": {"tl": "Kapag nagiging palaka na ang butete, hindi nahuhulog ang buntot nito — niloloob at sinisipsip ito ng sariling katawan para gawing sustansyang ginagamit habang lumalaki ang mga binti.", "en": "When a tadpole turns into a frog, its tail does not fall off — its own body absorbs the tail and uses it as nourishment while its legs grow.", "bis": "Kung mahimong baki na ang lawalawa, dili matangtang ang ikog niini — suyopon kini sa kaugalingong lawas ug himoon nga sustansya samtang motubo ang mga paa."}, "source": "encyclopedia-stable consensus (tail apoptosis during metamorphosis)", "generator": "claude-workflow", "reviewed": false},
  {"id": "frog-skin-drinks-water-g5", "domain": "LIVING_THINGS", "topic": "frogs drink water through their skin", "grades": [5, 6, 7], "terms": ["frog drinks through skin", "palaka umiinom sa balat", "baki moinom sa panit", "does not drink with mouth", "hindi umiinom gamit ang bibig", "dili moinom gamit ang baba", "absorbs water through skin", "sumisipsip ng tubig sa balat", "mosuyop og tubig sa panit", "drinking patch belly", "tubig sa pamamagitan ng balat", "tubig pinaagi sa panit", "bakit kailangang basa", "ngano kinahanglan basa", "moist skin frog"], "fact": {"tl": "Hindi umiinom ng tubig gamit ang bibig ang palaka — sumisipsip ito ng tubig nang diretso sa balat nito, kaya napakahalaga na laging basa ang kanilang katawan.", "en": "A frog does not drink water with its mouth — it soaks up water straight through its skin, which is why it is so important that a frog's body stays moist.", "bis": "Ang baki dili moinom og tubig gamit ang baba — mosuyop kini og tubig diretso pinaagi sa panit niini, mao nga importante kaayo nga kanunayng basa ang lawas sa baki."}, "source": "encyclopedia-stable consensus (cutaneous water absorption)", "generator": "claude-workflow", "reviewed": false},
  {"id": "frog-breathe-skin-underwater-g6", "domain": "LIVING_THINGS", "topic": "frogs breathe through their skin underwater", "grades": [6, 7, 8], "terms": ["frog breathes through skin", "palaka humihinga sa balat", "baki moginhawa sa panit", "cutaneous respiration", "oxygen through wet skin", "oksiheno sa basang balat", "oksiheno sa basa nga panit", "stays underwater long", "matagal sa ilalim ng tubig", "dugay sa ilawom sa tubig", "breathe without lungs", "humihinga kahit nasa tubig", "moginhawa bisan naa sa tubig", "needs damp skin", "bakit nananatili sa lamig"], "fact": {"tl": "Bukod sa baga, kayang huminga ng palaka sa pamamagitan ng basa nitong balat — dumadaan ang oxygen sa balat papasok sa dugo, kaya kaya nitong manatili nang matagal sa ilalim ng tubig.", "en": "Besides using lungs, a frog can breathe through its wet skin — oxygen passes through the skin into its blood, which lets it stay underwater for a long time.", "bis": "Gawas sa baga, makaginhawa ang baki pinaagi sa basa niini nga panit — moagi ang oksiheno sa panit padulong sa dugo, mao nga makapabilin kini og dugay sa ilawom sa tubig."}, "source": "encyclopedia-stable consensus (cutaneous respiration)", "generator": "claude-workflow", "reviewed": false},
  {"id": "frog-eyes-help-swallow-g5", "domain": "LIVING_THINGS", "topic": "frogs use their eyes to swallow", "grades": [5, 6, 7], "terms": ["frog eyes swallow", "mata ng palaka lumulunok", "mata sa baki magtulon", "pulls eyes down to swallow", "ibinababa ang mata para lumunok", "ipaubos ang mata aron magtulon", "eyes push food down", "itinutulak ng mata ang pagkain", "itukmod sa mata ang pagkaon", "blinking to swallow", "kumukurap habang kumakain", "mokurap samtang mokaon", "bulging eyes", "bakit pumipikit kapag kumakain", "ngano mopiyong kung mokaon"], "fact": {"tl": "Kapag lumululon ng pagkain ang palaka, ibinababa nito ang mga mata papasok sa loob ng ulo nito — itinutulak ng mga mata ang pagkain pababa sa lalamunan, kaya parang pumipikit ito habang kumakain.", "en": "When a frog swallows, it pulls its eyes down into its head — the eyes push the food down its throat, which is why a frog seems to blink while it eats.", "bis": "Kung magtulon og pagkaon ang baki, ipaubos niini ang mga mata sulod sa ulo niini — itukmod sa mga mata ang pagkaon paubos sa tutunlan, mao nga morag mopiyong kini samtang mokaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "frog-eggs-foam-water-g5", "domain": "LIVING_THINGS", "topic": "frog eggs float in jelly clusters", "grades": [4, 5, 6], "terms": ["frog eggs jelly", "itlog ng palaka jelly", "itlog sa baki jelly", "frog spawn", "kumpol-kumpol na itlog sa tubig", "pundok nga itlog sa tubig", "clear jelly protects eggs", "malagkit na pumapalibot sa itlog", "pilit nga maglibot sa itlog", "floating eggs pond", "lumulutang na itlog", "naglutaw nga itlog", "no hard shell", "walang matigas na balat ang itlog", "walay gahi nga panit ang itlog", "laid in water frog"], "fact": {"tl": "Walang matigas na balat ang itlog ng palaka; sa halip, binabalot ito ng malinaw at malagkit na jelly na pumipigil sa pagkatuyo at bahagyang nagpoprotekta rito habang lumulutang sa tubig.", "en": "Frog eggs have no hard shell; instead they are wrapped in clear, sticky jelly that keeps them from drying out and gives them some protection as they float in the water.", "bis": "Ang itlog sa baki walay gahi nga panit; hinuon, gibalot kini sa tin-aw ug pilit nga jelly nga magpugong sa pagkauga ug maghatag og diyutay nga panalipod samtang naglutaw kini sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "glass-frog-transparent-g6", "domain": "LIVING_THINGS", "topic": "glass frogs have see-through skin", "grades": [5, 6, 7], "terms": ["glass frog transparent", "palakang salamin", "baki nga salamin", "see through belly", "makikita ang loob ng tiyan", "makita ang sulod sa tiyan", "clear skin organs visible", "aninag na balat", "aninag nga panit", "heart visible through skin", "nakikita ang puso sa balat", "makita ang kasingkasing sa panit", "camouflage transparency", "bakit aninag ang palaka", "ngano aninag ang baki"], "fact": {"tl": "May mga uri ng palaka na tinatawag na glass frog na napakanipis at malinaw ng balat sa tiyan, kaya makikita mismo mula sa labas ang ilang panloob na bahagi nito tulad ng puso.", "en": "There are frogs called glass frogs whose belly skin is so thin and clear that you can see some of their insides, such as the heart, right through the skin.", "bis": "Adunay mga matang sa baki nga gitawag og glass frog kansang panit sa tiyan nipis ug tin-aw kaayo, mao nga makita gikan sa gawas ang pipila ka sulod niini sama sa kasingkasing."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "frog-freeze-winter-g7", "domain": "LIVING_THINGS", "topic": "some frogs survive being frozen", "grades": [7, 8, 9], "terms": ["frog freezes survives", "palakang nagyeyelo", "baki nga mo-yelo", "wood frog frozen alive", "nabubuhay kahit nagyelo", "mabuhi bisan nag-yelo", "heart stops then restarts", "huminto ang puso bumalik", "mohunong ang kasingkasing mobalik", "natural antifreeze sugar", "asukal pumipigil sa pagyelo", "asukal magpugong sa pag-yelo", "thaws back to life", "nabubuhay muli kapag natunaw", "mabuhi pag-usab kung matunaw"], "fact": {"tl": "May ilang uri ng palaka sa malalamig na bansa na kayang mabuhay kahit halos magyelo nang buo ang katawan nila sa taglamig — humihinto ang kanilang puso, at kapag natunaw na ang yelo, muli silang nabubuhay.", "en": "Some frogs in cold countries can survive even when most of their body freezes in winter — their heart stops, and when the ice melts they come back to life.", "bis": "Adunay pipila ka matang sa baki sa bugnaw nga mga nasod nga makabuhi bisan halos mo-yelo nga tibuok ang ilang lawas sa tingtugnaw — mohunong ang ilang kasingkasing, ug kung matunaw na ang yelo mabuhi sila pag-usab."}, "source": "encyclopedia-stable consensus (wood frog cryoprotection)", "generator": "claude-workflow", "reviewed": false},
  {"id": "amphibian-skin-poison-g6", "domain": "LIVING_THINGS", "topic": "some amphibians make poison in their skin", "grades": [6, 7, 8], "terms": ["poison frog skin", "palakang lason", "baki nga hilo", "poison dart frog", "makukulay na palaka", "kolorido nga baki", "bright colors warn poison", "matingkad na kulay babala", "hayag nga kolor pasidaan", "toxin from skin glands", "lason sa balat", "hilo sa panit", "aposematic warning color", "huwag kainin matingkad na palaka", "ayaw kan-a ang hayag nga baki", "toad parotoid gland"], "fact": {"tl": "May mga palaka't toad na gumagawa ng lason mula sa mga gland sa kanilang balat; madalas na matingkad ang kulay nila bilang babala sa ibang hayop na huwag silang kainin.", "en": "Some frogs and toads make poison from glands in their skin; they are often brightly colored as a warning to other animals not to eat them.", "bis": "Adunay mga baki ug toad nga maghimo og hilo gikan sa mga glandula sa ilang panit; sagad hayag ang ilang kolor isip pasidaan sa ubang hayop nga dili sila kan-on."}, "source": "encyclopedia-stable consensus (aposematism, skin toxins)", "generator": "claude-workflow", "reviewed": false},
  {"id": "toad-hop-not-jump-g4", "domain": "LIVING_THINGS", "topic": "toads walk and hop instead of long leaps", "grades": [3, 4, 5], "terms": ["toad hops", "palakang lupa gumagapang", "kabakaba mo-lukso", "toad short legs", "maikling binti ng toad", "mubo nga paa sa kabakaba", "walks crawls hop", "gumagapang sa lupa", "mokamang sa yuta", "dry warty skin", "kulubot na balat", "kunot nga panit", "not strong leaper like frog", "hindi malayo tumalon", "dili layo molukso", "bakit hindi lumulundag", "ngano dili molukso ang kabakaba"], "fact": {"tl": "Hindi lahat ng kahawig ng palaka ay magaling lumundag — ang toad ay may mas maiikling binti at karaniwang gumagapang o maliliit lang ang lukso, kaiba sa palakang may malayong talon.", "en": "Not every frog-like animal is a great jumper — a toad has shorter legs and usually crawls or hops only a little, unlike a frog with its long leaps.", "bis": "Dili tanan nga morag baki maayong molukso — ang kabakaba adunay mas mubo nga mga paa ug kasagaran mokamang o gamay ra molukso, lahi sa baki nga adunay layo nga lukso."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sea-turtle-magnetic-navigation-g7", "domain": "LIVING_THINGS", "topic": "sea turtles navigate using Earth's magnetic field", "grades": [7, 8, 9], "terms": ["sea turtle navigation", "pawikan nakakauwi", "pawikan makauli", "earth magnetic field", "magnetikong larangan ng mundo", "magnetiko nga natad sa kalibutan", "finds birth beach again", "nakakabalik sa dalampasigan", "makabalik sa baybayon", "internal compass", "parang kompas sa loob", "morag kompas sa sulod", "travels thousands kilometers", "libo-libong kilometro paglangoy", "libolibo ka kilometro paglangoy", "bakit nakakabalik ang pawikan", "paano nakakauwi ang pawikan"], "fact": {"tl": "Nakakalangoy ang pawikan ng libo-libong kilometro at nakakabalik pa rin sa parehong dalampasigan na kanyang pinanganakan dahil nararamdaman nito ang magnetikong larangan ng Daigdig na parang likas na kompas.", "en": "A sea turtle can swim thousands of kilometers and still find its way back to the very beach where it was born because it can sense Earth's magnetic field like a built-in compass.", "bis": "Ang pawikan makalangoy og libolibo ka kilometro ug makabalik gihapon sa samang baybayon diin kini natawo tungod kay mabati niini ang magnetiko nga natad sa Kalibutan sama sa usa ka natural nga kompas."}, "source": "encyclopedia-stable consensus (magnetoreception in sea turtles)", "generator": "claude-workflow", "reviewed": false},
  {"id": "sea-turtle-cannot-hide-shell-g4", "domain": "LIVING_THINGS", "topic": "sea turtles cannot pull into their shell", "grades": [3, 4, 5], "terms": ["sea turtle shell cannot hide", "pawikan hindi makapasok sa bahay", "pawikan dili makasulod sa balay", "flippers cannot retract", "hindi maitago ang ulo at paa", "dili matago ang ulo ug paa", "unlike land turtle", "kaiba sa pagong sa lupa", "lahi sa bao sa yuta", "streamlined for swimming", "hugis pampalangoy ang bahay", "hulma sa paglangoy ang balay", "built for ocean not hiding", "bakit hindi makapasok sa talukab", "ngano dili makasulod sa kabhang"], "fact": {"tl": "Hindi tulad ng pagong sa lupa, hindi kayang itago ng pawikan ang ulo at mga paa nito sa loob ng talukab — ang kanilang katawan ay hugis-pampalangoy na, kaya nakakasagwan sila nang maayos sa karagatan.", "en": "Unlike a land turtle, a sea turtle cannot pull its head and flippers inside its shell — its body is shaped for swimming, so it is built to glide through the ocean instead of hiding.", "bis": "Dili sama sa bao sa yuta, ang pawikan dili makasulod sa ulo ug mga paa niini sa sulod sa kabhang — ang ilang lawas hulma na alang sa paglangoy, mao nga sila gibuhat aron molutaw sa kadagatan imbes magtago."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "turtle-shell-is-bones-g5", "domain": "LIVING_THINGS", "topic": "a turtle's shell is part of its skeleton", "grades": [5, 6, 7], "terms": ["turtle shell bones", "talukab ng pagong buto", "kabhang sa bao bukog", "shell is the skeleton", "kabilang sa kalansay ang talukab", "kabahin sa kalabera ang kabhang", "ribs spine fused shell", "tadyang gulugod nakakabit", "gusok bukog-likod nasumpay", "cannot leave shell", "hindi kayang lumabas sa talukab", "dili makagawas sa kabhang", "not a house it wears", "hindi bahay na isinusuot", "dili balay nga gisul-ob", "bakit kabit ang talukab", "ngano nakakabit ang kabhang"], "fact": {"tl": "Ang talukab ng pagong ay hindi bahay na isinusuot nito — bahagi ito ng kanyang kalansay, dahil nagkakabit dito ang mga tadyang at gulugod, kaya hindi kayang lumabas ng pagong sa sarili nitong talukab.", "en": "A turtle's shell is not a house it wears — it is part of its skeleton, because the ribs and backbone are joined to it, so a turtle can never leave its own shell.", "bis": "Ang kabhang sa bao dili balay nga gisul-ob niini — kabahin kini sa iyang kalabera, kay ang mga gusok ug bukog-likod nasumpay niini, mao nga ang bao dili gayod makagawas sa kaugalingon niining kabhang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "lizard-third-eye-g7", "domain": "LIVING_THINGS", "topic": "some reptiles have a light-sensing third eye", "grades": [7, 8, 9], "terms": ["reptile third eye", "ikatlong mata ng reptilya", "ikatulong mata sa reptilya", "parietal eye", "mata sa tuktok ng ulo", "mata sa tumoy sa ulo", "senses light not images", "nakakaramdam ng liwanag", "makabati og kahayag", "helps with time sun", "nakakatulong sa oras at araw", "makatabang sa oras ug adlaw", "spot on top of head", "batong-mata sa noo", "tuldok sa ibabaw sa ulo", "bakit may parang mata sa ulo"], "fact": {"tl": "May ilang butiki at iba pang reptilya na may parang ikatlong mata sa tuktok ng ulo — hindi ito nakakakita ng larawan, pero nakakaramdam ito ng liwanag at dilim, na tumutulong sa kanila na malaman ang oras at init ng araw.", "en": "Some lizards and other reptiles have a kind of third eye on top of the head — it cannot see pictures, but it senses light and dark, helping them keep track of the time of day and the sun.", "bis": "Adunay pipila ka tiki ug uban pang reptilya nga adunay morag ikatulong mata sa tumoy sa ulo — dili kini makakita og hulagway, apan makabati kini og kahayag ug kangitngit, nga makatabang nila mahibalo sa oras sa adlaw ug init."}, "source": "encyclopedia-stable consensus (parietal eye)", "generator": "claude-workflow", "reviewed": false},
  {"id": "snake-lizard-tongue-smell-g6", "domain": "LIVING_THINGS", "topic": "reptiles taste the air with a forked tongue", "grades": [5, 6, 7], "terms": ["forked tongue smell", "sangang dila amoy", "sanga nga dila baho", "tongue flicks air", "dinadampot ng dila ang amoy", "kuhaon sa dila ang baho", "two tips smell direction", "dalawang dulo ng dila", "duha ka tumoy sa dila", "jacobson organ mouth roof", "alam kung saang panig ang amoy", "mahibaw-an asa nga bahin ang baho", "why snakes flick tongue", "bakit nakausli ang dila ng ahas", "ngano mogula ang dila sa bitin"], "fact": {"tl": "Inuusli ng mga ahas at maraming butiki ang sangang dila nila para sumalo ng mga particle ng amoy sa hangin; dahil dalawa ang dulo ng dila, nalalaman pa nila kung saang panig nanggagaling ang amoy.", "en": "Snakes and many lizards flick out their forked tongue to catch scent particles from the air; because the tongue has two tips, they can even tell which side a smell is coming from.", "bis": "Ang mga bitin ug daghang tiki magpagula sa ilang sanga nga dila aron makakuha og mga partikulo sa baho gikan sa hangin; tungod kay duha ang tumoy sa dila, mahibaw-an pa nila kung asa nga bahin gikan ang baho."}, "source": "encyclopedia-stable consensus (vomeronasal/Jacobson's organ)", "generator": "claude-workflow", "reviewed": false},
  {"id": "amphibian-double-life-meaning-g6", "domain": "LIVING_THINGS", "topic": "the word amphibian means two lives", "grades": [5, 6, 7], "terms": ["amphibian meaning two lives", "amphibian dalawang buhay", "amphibian duha ka kinabuhi", "starts in water then land", "nagsisimula sa tubig pagkatapos lupa", "magsugod sa tubig dayon yuta", "greek word amphi bios", "kahulugan ng salitang amphibian", "kahulogan sa pulong amphibian", "life in water and on land", "buhay sa tubig at lupa", "kinabuhi sa tubig ug yuta", "bakit tinatawag na amphibian", "ngano gitawag og amphibian", "tadpole then frog two stages"], "fact": {"tl": "Ang salitang amphibian ay nangangahulugang 'dalawang buhay' — dahil karamihan sa kanila ay nagsisimula ng buhay sa tubig bilang batang may hasang, at saka lumipat sa lupa kapag may baga na.", "en": "The word amphibian means 'two lives' — because most of them begin life in the water as young with gills, and later move onto land once they have lungs.", "bis": "Ang pulong amphibian nagpasabot og 'duha ka kinabuhi' — tungod kay kadaghanan kanila magsugod og kinabuhi sa tubig isip bata nga adunay hasang, ug unya mobalhin sa yuta kung naa nay baga."}, "source": "encyclopedia-stable consensus (Greek amphi + bios)", "generator": "claude-workflow", "reviewed": false},
  {"id": "bee-waggle-dance-g4", "domain": "LIVING_THINGS", "topic": "honeybee waggle dance", "grades": [4, 5, 6], "terms": ["waggle dance", "sayaw", "sayaw ng bubuyog", "bubuyog", "pukyutan", "putyukan", "buyog", "sayaw ng pukyutan", "sumayaw", "direksyon", "bulaklak", "sayaw-sayaw", "nagsayaw", "misayaw", "direksyon sa bulak", "pulot"], "fact": {"tl": "Kapag nakakita ng pagkain, sumasayaw ang bubuyog sa loob ng bahay-pukyutan — ang 'waggle dance' — para sabihin sa iba kung saang direksyon at gaano kalayo ang mga bulaklak.", "en": "When a honeybee finds food, it does a 'waggle dance' inside the hive to tell the others which direction the flowers are and how far away.", "bis": "Kung makakita og pagkaon, mosayaw ang putyukan sulod sa balay-putyukan — ang 'waggle dance' — aron sultihan ang uban kung asang direksyon ug unsa kalayo ang mga bulak."}, "source": "encyclopedia-stable consensus (von Frisch waggle dance)", "generator": "claude-workflow", "reviewed": false},
  {"id": "bee-queen-one-per-hive-g4", "domain": "LIVING_THINGS", "topic": "honeybee queen", "grades": [4, 5, 6], "terms": ["queen bee", "reyna", "reynang bubuyog", "reyna sa putyukan", "hari-reyna", "itlog", "nangingitlog", "nangitlog", "mangitlog", "pukyutan", "bubuyog", "buyog", "kolonya", "isa lang", "usa ra", "bahay-pukyutan"], "fact": {"tl": "Isang reynang bubuyog lang ang nasa bawat bahay-pukyutan, at siya lang ang nangingitlog — kaya niyang mangitlog ng libu-libo bawat araw.", "en": "There is only one queen bee in each hive, and she is the only one that lays eggs — she can lay thousands of eggs every day.", "bis": "Usa ra ka reyna nga putyukan ang naa sa matag balay-putyukan, ug siya ra ang mangitlog — makahimo siya og liboan ka itlog matag adlaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bee-honey-from-nectar-g4", "domain": "LIVING_THINGS", "topic": "how bees make honey", "grades": [4, 5, 6], "terms": ["honey", "pulot", "pulot-pukyutan", "dugos", "nektar", "nectar", "bulaklak", "bulak", "gumagawa ng pulot", "gibuhat nga dugos", "naghimo og dugos", "tiyan", "sikmura", "sinusuka", "bumalik-balik", "pukyutan", "bubuyog"], "fact": {"tl": "Sinisipsip ng bubuyog ang matamis na nektar ng bulaklak, iniimbak ito sa espesyal na tiyan, at paulit-ulit na pinoproseso hanggang maging makapal na pulot.", "en": "Bees suck sweet nectar from flowers, store it in a special stomach, and process it over and over until it thickens into honey.", "bis": "Ang putyukan mosuyop sa tam-is nga nektar sa bulak, itipig kini sa espesyal nga tiyan, ug balik-balikon kini hangtod mahimong baga nga dugos."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "honey-never-spoils-g5", "domain": "LIVING_THINGS", "topic": "why honey does not spoil", "grades": [5, 6, 7], "terms": ["honey", "pulot", "dugos", "hindi nabubulok", "dili madunot", "walang panis", "hindi napapanis", "mababang tubig", "gamot", "preserve", "nananatili", "matagal", "libong taon", "liboan ka tuig", "bacteria", "mikrobyo", "tamis"], "fact": {"tl": "Hindi madaling napapanis ang pulot dahil napakaliit ng tubig dito at napakatamis, kaya hindi mabuhay ang mga mikrobyong nagpapabulok — may pulot na natagpuang libong taon na pero kainin pa rin.", "en": "Honey almost never spoils because it has very little water and is so sugary that decay microbes cannot grow — jars of honey thousands of years old have been found still edible.", "bis": "Ang dugos halos dili gyud madunot kay gamay ra kaayo ang tubig niini ug tam-is kaayo, mao nga dili mabuhi ang mga mikrobyo nga makapadunot — adunay dugos nga liboan ka tuig na apan makaon gihapon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bees-pollinate-our-food-g4", "domain": "LIVING_THINGS", "topic": "why bees matter for food", "grades": [4, 5, 6], "terms": ["pollination", "polinasyon", "pollinator", "tagahatid ng pollen", "nagdadala ng pollen", "prutas", "gulay", "pagkain", "bulaklak", "bunga", "mangga", "pakwan", "kapag walang bubuyog", "kung wala ang putyukan", "tumutulong", "nakatabang", "pukyutan", "bubuyog"], "fact": {"tl": "Habang naghahanap ng nektar, dinadala ng bubuyog ang pollen sa pagitan ng mga bulaklak, kaya nakakabunga ang maraming prutas at gulay — kung wala sila, mas kaunti ang pagkain natin.", "en": "While looking for nectar, bees carry pollen between flowers, which lets many fruits and vegetables form — without them we would have much less food.", "bis": "Samtang nangita og nektar, ang putyukan magdala og pollen tali sa mga bulak, mao nga makabunga ang daghang prutas ug utanon — kung wala sila, mas gamay ta og pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "worker-bees-all-female-g5", "domain": "LIVING_THINGS", "topic": "worker bees are female", "grades": [5, 6, 7], "terms": ["worker bee", "manggagawang bubuyog", "trabahador", "babae lahat", "puro babae", "tanan babaye", "drone", "male bee", "lalaki", "kolonya", "gawain", "nagtatrabaho", "nagtrabaho", "mangani", "pukyutan", "bubuyog", "buyog"], "fact": {"tl": "Lahat ng manggagawang bubuyog na nangunguha ng pagkain at nag-aalaga sa pugad ay babae; ang mga lalaki (drone) ay iilan lang at ang tanging tungkulin nila ay tumulong sa reyna na magkaroon ng bagong bubuyog.", "en": "All the worker bees that gather food and care for the hive are female; the males (drones) are few and their only job is to help the queen make new bees.", "bis": "Tanang trabahador nga putyukan nga mangani og pagkaon ug moatiman sa salag kay mga babaye; ang mga laki (drone) gamay ra ug ang ila lang nga buluhaton mao ang motabang sa reyna nga makabaton og bag-ong mga putyukan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bee-sting-dies-g4", "domain": "LIVING_THINGS", "topic": "why honeybees die after stinging", "grades": [4, 5, 6], "terms": ["sting", "tusok", "kagat", "tibo", "kamatayan", "namamatay", "namatay", "mamatay", "mamatay-tuslok", "tinik", "barbed", "sumasabit", "nahabilin", "tiyan", "pukyutan", "bubuyog", "buyog", "depensa"], "fact": {"tl": "Ang tibo ng bubuyog ay may maliliit na tinik na sumasabit sa balat, kaya kapag tumusok ito at lumipad palayo, napupunit ang tiyan nito at namamatay.", "en": "A honeybee's stinger has tiny barbs that catch in the skin, so when it stings and flies away, its belly tears and the bee dies.", "bis": "Ang tuslok sa putyukan adunay gagmay nga tunok nga mosab-it sa panit, mao nga kung motuslok kini ug molupad palayo, magisi ang tiyan niini ug mamatay."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "honeycomb-hexagon-g4", "domain": "LIVING_THINGS", "topic": "hexagon honeycomb shape", "grades": [4, 5, 6], "terms": ["honeycomb", "bahay-pukyutan", "balay-putyukan", "hexagon", "anim na panig", "unom ka kilid", "heksagono", "beeswax", "pagkit", "talo", "cells", "selula", "hugis", "porma", "matipid", "walang sayang na puwang", "pukyutan", "bubuyog"], "fact": {"tl": "Ginagawa ng bubuyog ang mga selula ng pugad sa hugis-hexagon (anim na panig) dahil ito ang pinakamatipid na hugis — punung-puno ito nang walang sayang na puwang at kakaunti lang ang pagkit na kailangan.", "en": "Bees build the cells of their comb as hexagons (six sides) because it is the most efficient shape — it fills space with no gaps and needs the least wax.", "bis": "Gibuhat sa putyukan ang mga selula sa salag nga hexagon (unom ka kilid) tungod kay kini ang labing tipid nga porma — mapuno kini nga walay luwang ug gamay ra ang talo nga kinahanglanon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bee-dance-direction-sun-g6", "domain": "LIVING_THINGS", "topic": "waggle dance uses the sun", "grades": [6, 7, 8], "terms": ["waggle dance", "sayaw ng bubuyog", "araw", "adlaw", "anggulo", "direksyon", "navigation", "gabay", "brujula", "compass", "posisyon ng araw", "posisyon sa adlaw", "sumasayaw paitaas", "pataas", "wala na ang araw", "pukyutan", "bubuyog", "sayaw"], "fact": {"tl": "Sa waggle dance, ginagamit ng bubuyog ang posisyon ng araw bilang gabay — ang anggulo ng pagsayaw kaugnay ng patindig ay nagsasabi ng anggulo ng pagkain kaugnay ng araw.", "en": "In the waggle dance, a bee uses the sun as a compass — the angle of its dance from straight up tells the others the direction of the food relative to the sun.", "bis": "Sa waggle dance, gamiton sa putyukan ang posisyon sa adlaw isip giya — ang anggulo sa sayaw gikan sa tul-id pataas magsulti sa direksyon sa pagkaon may kalabotan sa adlaw."}, "source": "encyclopedia-stable consensus (von Frisch)", "generator": "claude-workflow", "reviewed": false},
  {"id": "ants-follow-scent-trail-g4", "domain": "LIVING_THINGS", "topic": "how ants make trails", "grades": [4, 5, 6], "terms": ["ant trail", "langgam", "hantik", "subay", "pisot", "amimik", "sunod-sunod", "linya", "amoy", "baho", "scent", "pheromone", "bakas na amoy", "sundan ang amoy", "pagkain", "nagmamartsa", "nagsunod-sunod", "nagsubay", "langgam-langgam"], "fact": {"tl": "Naglalakad ang mga langgam nang sunud-sunod sa isang linya dahil nag-iiwan ang nauna ng amoy (pheromone) sa lupa na sinusundan ng mga kasunod papunta sa pagkain.", "en": "Ants walk in a line one behind another because the leaders leave a scent trail on the ground that the others follow straight to the food.", "bis": "Ang mga subay molakaw nga sunod-sunod sa usa ka linya tungod kay ang nag-una magbilin og baho (pheromone) sa yuta nga sundon sa mosunod paingon sa pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ant-carries-heavy-g4", "domain": "LIVING_THINGS", "topic": "ants carry heavy loads", "grades": [4, 5, 6], "terms": ["ant strength", "langgam", "subay", "lakas", "kusog", "kakayahang magbuhat", "makapagbuhat", "mabug-at", "mas mabigat", "kaysa sa sarili", "kaysa sa kaugalingon", "timbang", "bigat", "pasan", "nagbubuhat", "nagpas-an", "gibuhat", "sobra-sobra"], "fact": {"tl": "Kayang buhatin ng isang langgam ang bagay na maraming beses na mas mabigat kaysa sa sarili nitong timbang — gaya ng tao na may bitbit na kotse.", "en": "A single ant can lift things many times heavier than its own body — like a person carrying a car.", "bis": "Ang usa ka subay makahimo sa pagbuhat og butang nga pila ka pilo nga mas bug-at kaysa sa kaugalingon niini nga gibug-aton — sama sa tawo nga magpas-an og awto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ant-colony-jobs-g4", "domain": "LIVING_THINGS", "topic": "ant colony division of work", "grades": [4, 5, 6], "terms": ["ant colony", "kolonya ng langgam", "kolonya sa subay", "pugad", "salag", "gawain", "trabaho", "buluhaton", "reyna", "queen ant", "manggagawa", "trabahador", "sundalong langgam", "soldier ant", "nag-aalaga", "nagbabantay", "naghahanap", "hati-hati ang gawain"], "fact": {"tl": "Sa kolonya ng langgam, hati-hati ang gawain: may reyna na nangingitlog, mga manggagawang naghahanap ng pagkain, at mga sundalong nagbabantay sa pugad.", "en": "In an ant colony the work is divided: a queen lays the eggs, worker ants gather food, and soldier ants guard the nest.", "bis": "Sa kolonya sa subay, bahin-bahin ang trabaho: adunay reyna nga mangitlog, mga trabahador nga mangita og pagkaon, ug mga sundalo nga mobantay sa salag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "leafcutter-ants-farm-g6", "domain": "LIVING_THINGS", "topic": "leafcutter ants grow fungus", "grades": [6, 7, 8], "terms": ["leafcutter ant", "langgam na pumuputol ng dahon", "subay nga moputol og dahon", "dahon", "fungus", "amag", "kabute", "nagtatanim", "nag-aalaga ng amag", "magsaka", "magtanim", "hardin", "kinakain ang amag", "hiniwa", "pinuputol na dahon", "sinasaka", "langgam"], "fact": {"tl": "May mga langgam (leafcutter) na pumuputol ng dahon hindi para kainin, kundi para patubuan ng amag sa loob ng pugad — sila ay 'magsasaka' na nag-aalaga at kumakain ng amag na iyon.", "en": "Some ants (leafcutters) cut leaves not to eat them, but to grow fungus inside the nest — they are 'farmers' that tend and eat that fungus.", "bis": "Adunay mga subay (leafcutter) nga moputol og dahon dili aron kan-on, kondili aron patuboan og fungus sulod sa salag — sila mga 'mag-uuma' nga moatiman ug mokaon nianang fungus."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "termites-build-mounds-g5", "domain": "LIVING_THINGS", "topic": "termite mounds", "grades": [5, 6, 7], "terms": ["termite", "anay", "ane", "punso", "mound", "tore", "tahanan", "tirahan", "balay sa anay", "bahay ng anay", "lupa", "laway", "dumi", "matibay", "matigas", "matas", "kawan", "kolonya", "ventilation", "hangin"], "fact": {"tl": "Nagtatayo ang ilang anay ng matataas na punso mula sa lupa at laway na may mga daanan ng hangin sa loob para manatiling presko ang kanilang tahanan kahit napakainit sa labas.", "en": "Some termites build tall mounds of soil and saliva with air passages inside that keep their home cool even when it is very hot outside.", "bis": "Ang ubang anay magtukod og tag-as nga punso gikan sa yuta ug laway nga adunay agianan sa hangin sulod aron magpabiling bugnaw ang ilang balay bisan init kaayo sa gawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "termites-eat-wood-g5", "domain": "LIVING_THINGS", "topic": "termites eat wood", "grades": [5, 6, 7], "terms": ["termite", "anay", "ane", "kahoy", "kayo", "gumagapang sa kahoy", "kinakain ang kahoy", "mokaon og kahoy", "cellulose", "mikrobyo sa tiyan", "tutulong matunaw", "tiyan", "sira ang bahay", "gibabag", "nagsisira", "nakaguba", "makaguba", "kolonya"], "fact": {"tl": "Kinakain ng anay ang kahoy, pero hindi nila ito matutunaw nang mag-isa — may maliliit na mikrobyo sa tiyan nila na tumutulong magtunaw ng kahoy.", "en": "Termites eat wood, but they cannot digest it alone — tiny microbes living in their gut help break the wood down.", "bis": "Ang anay mokaon og kahoy, apan dili nila kini matunaw nga mag-inusara — adunay gagmay nga mikrobyo sa ilang tiyan nga motabang sa pagtunaw sa kahoy."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "firefly-light-cold-g4", "domain": "LIVING_THINGS", "topic": "why fireflies glow", "grades": [4, 5, 6], "terms": ["firefly", "alitaptap", "aninipot", "kingki", "ningning", "kumikislap", "nagliliwanag", "nagdan-ag", "nag-idlap", "ilaw", "liwanag", "kahig nga init", "walang init", "malamig na ilaw", "cold light", "tiyan", "puwit", "kemikal", "gabi"], "fact": {"tl": "Nagliliwanag ang alitaptap dahil sa kemikal sa puwitan nito, at kakaiba ito dahil ang ilaw ay halos walang init — kaya tinatawag itong 'malamig na liwanag'.", "en": "Fireflies glow because of a chemical in their belly, and amazingly the light gives off almost no heat — that is why it is called 'cold light'.", "bis": "Ang aninipot mosiga tungod sa kemikal sa lubot niini, ug katingad-an kay ang kahayag halos walay init — mao nga gitawag kining 'bugnaw nga kahayag'."}, "source": "encyclopedia-stable consensus (bioluminescence)", "generator": "claude-workflow", "reviewed": false},
  {"id": "firefly-flash-signal-g5", "domain": "LIVING_THINGS", "topic": "firefly flashing signals", "grades": [5, 6, 7], "terms": ["firefly", "alitaptap", "aninipot", "kingki", "flash", "kislap", "pagkislap", "kumikislap", "nag-idlap", "senyas", "signal", "hudyat", "tawag", "pares", "kapareha", "makahanap ng kapares", "mangita og pares", "patterns", "ritmo", "gabi", "grupo"], "fact": {"tl": "Kumikislap ang alitaptap sa tiyak na ritmo bilang senyas — ginagamit nila ito para makahanap ng kapareha sa dilim ng gabi.", "en": "Fireflies blink in a special rhythm as a signal — they use these flashes to find a mate in the dark of night.", "bis": "Ang aninipot mag-idlap sa piho nga ritmo isip senyas — gamiton nila kini aron makakita og kapares sa kangitngit sa gabii."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "firefly-synchronous-g6", "domain": "LIVING_THINGS", "topic": "synchronized firefly flashing", "grades": [6, 7, 8], "terms": ["firefly", "alitaptap", "aninipot", "kingki", "sabay-sabay", "dungan-dungan", "sabay kumislap", "sabayan", "sync", "synchronous", "magkakasabay", "puno", "mangrove", "Donsol", "Sorsogon", "palabas", "sayang gabi", "grupo", "kumikislap"], "fact": {"tl": "Sa ilang lugar tulad ng mga bakawan sa Pilipinas, libu-libong alitaptap sa isang puno ang sabay-sabay kumikislap, na parang sumasayaw na ilaw sa gabi.", "en": "In some places, like the mangroves of the Philippines, thousands of fireflies in one tree flash all together, like dancing lights in the night.", "bis": "Sa pipila ka lugar, sama sa mga bakawan sa Pilipinas, liboan ka aninipot sa usa ka kahoy ang dungan-dungan mag-idlap, sama sa nagsayaw nga kahayag sa gabii."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wasps-make-paper-nest-g5", "domain": "LIVING_THINGS", "topic": "wasps build paper nests", "grades": [5, 6, 7], "terms": ["wasp", "putakti", "alimpipinig", "tabuan", "pugad", "salag", "papel", "papel-papel", "ginagawang papel", "gibuhat nga papel", "ngumunguya ng kahoy", "gisapsap nga kahoy", "laway", "balay sa putakti", "bahay-pugad", "selula", "hexagon", "lumilipad", "kawan"], "fact": {"tl": "Gumagawa ang ilang putakti ng pugad na parang papel — ngumunguya sila ng kahoy at hinahalo ito sa laway hanggang maging malambot na materyales na pinupormang pugad.", "en": "Some wasps build nests that feel like paper — they chew wood and mix it with saliva until it becomes a soft material they shape into a nest.", "bis": "Ang ubang putakti maghimo og salag nga morag papel — magsapsap sila og kahoy ug isagol kini sa laway hangtod mahimong humok nga materyal nga porma-on nilang salag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "wasps-eat-pests-g5", "domain": "LIVING_THINGS", "topic": "wasps help control pests", "grades": [5, 6, 7], "terms": ["wasp", "putakti", "alimpipinig", "tabuan", "peste", "pests", "insekto", "uod", "nakakain ng peste", "mokaon og peste", "nakatabang", "tumutulong", "predator", "mandaragit", "mananim", "tanim", "saka", "pananim", "kinokontrol", "lumilipad"], "fact": {"tl": "Hindi lahat ng putakti ay masama — marami sa kanila ang kumakain ng mga peste at uod na sumisira sa pananim, kaya nakatutulong sila sa mga magsasaka.", "en": "Not all wasps are bad — many of them eat pests and caterpillars that damage crops, so they help farmers.", "bis": "Dili tanang putakti daotan — daghan kanila ang mokaon og peste ug ulod nga makadaot sa tanom, mao nga makatabang sila sa mga mag-uuma."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "social-insects-colony-superorganism-g6", "domain": "LIVING_THINGS", "topic": "social insects work as one colony", "grades": [6, 7, 8], "terms": ["social insect", "insektong panlipunan", "insektong nagtutulungan", "kolonya", "kawan", "pamayanan", "nagtutulungan", "nagtinabangay", "magtinabangay", "teamwork", "sama-sama", "tulong-tulong", "parang isang katawan", "colony", "superorganism", "bubuyog", "langgam", "anay", "gawain"], "fact": {"tl": "Ang mga bubuyog, langgam, at anay ay tinatawag na 'social insects' dahil libu-libo silang nagtutulungan sa isang kolonya na parang iisang malaking katawan — walang isa sa kanila ang mabubuhay nang mag-isa.", "en": "Bees, ants, and termites are called 'social insects' because thousands of them work together in one colony like a single big body — none of them could survive alone.", "bis": "Ang mga putyukan, subay, ug anay gitawag og 'social insects' tungod kay liboan sila nga magtinabangay sa usa ka kolonya nga morag usa ka dako nga lawas — walay usa kanila nga mabuhi nga mag-inusara."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bees-beat-wings-hum-g4", "domain": "LIVING_THINGS", "topic": "why bees buzz", "grades": [4, 5, 6], "terms": ["buzz", "ugong", "haging", "pagaspas ng pakpak", "pakpak", "bumabagang tunog", "huni", "tunog", "napakabilis", "kusog kaayo", "libo-libong beses", "mabilis na pagaspas", "pakpak-pakpak", "nag-uugong", "naghaging", "pukyutan", "bubuyog"], "fact": {"tl": "Ang ugong ng bubuyog ay nagmumula sa napakabilis na pagaspas ng pakpak nito — daan-daang beses ito pumagaspas bawat segundo, kaya naririnig natin ang 'buzz'.", "en": "A bee's buzz comes from its wings beating extremely fast — hundreds of times every second — which is why we hear that humming sound.", "bis": "Ang haging sa putyukan gikan sa paspas kaayo nga pagkapakapa sa pako niini — gatusan ka beses matag segundo, mao nga madungog nato ang 'buzz'."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bee-eyes-see-uv-g7", "domain": "LIVING_THINGS", "topic": "bees see ultraviolet on flowers", "grades": [7, 8, 9], "terms": ["bee vision", "mata ng bubuyog", "mata sa putyukan", "ultraviolet", "UV", "kulay na hindi natin nakikita", "dili nato makita", "bulaklak", "bulak", "patterns", "guhit", "gabay sa nektar", "nectar guide", "nakikita ng bubuyog", "makita sa putyukan", "mata", "kompound na mata", "pollen"], "fact": {"tl": "Nakakakita ang bubuyog ng ultraviolet na liwanag na hindi natin nakikita, kaya may mga 'gabay-guhit' sa bulaklak na tanging sila lang ang nakakakita papunta sa nektar.", "en": "Bees can see ultraviolet light that we cannot, so many flowers have hidden 'guide marks' that only bees can see pointing them to the nectar.", "bis": "Ang putyukan makakita og ultraviolet nga kahayag nga dili nato makita, mao nga daghang bulak ang adunay tinago nga 'giya-marka' nga sila ra ang makakita paingon sa nektar."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "queen-bee-royal-jelly-g6", "domain": "LIVING_THINGS", "topic": "royal jelly makes a queen", "grades": [6, 7, 8], "terms": ["royal jelly", "jelly ng reyna", "royal-jelly", "reyna", "queen", "larva", "uod", "bagong itlog", "kung ano ang kinakain", "gipakaon", "pinakain", "naging reyna", "mahimong reyna", "espesyal na pagkain", "pagkaon", "manggagawa", "worker", "pukyutan", "bubuyog", "kasing-itlog"], "fact": {"tl": "Magkapareho ang mga babaeng uod ng bubuyog sa simula, pero ang isang pinakakain ng espesyal na 'royal jelly' ay lumalaki at nagiging reyna — ang pagkain ang nagpasiya kung sino ang magiging reyna.", "en": "Female bee larvae start out the same, but the one fed special 'royal jelly' grows up to become the queen — what it eats decides who becomes queen.", "bis": "Managsama ang mga babaye nga ulod sa putyukan sa sinugdan, apan ang usa nga pakan-on og espesyal nga 'royal jelly' modako ug mahimong reyna — ang pagkaon ang modesisyon kung kinsa ang mahimong reyna."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ants-no-ears-feel-vibration-g6", "domain": "LIVING_THINGS", "topic": "ants sense vibration not sound", "grades": [6, 7, 8], "terms": ["ant senses", "langgam", "subay", "walang tainga", "walay dunggan", "hindi nakakarinig", "dili makadungog", "pag-uga", "vibration", "yanig", "pagyanig", "nararamdaman ang galaw", "gibati ang lihok", "paa", "antennae", "sungot", "damdam sa lupa", "komunikasyon", "langgam"], "fact": {"tl": "Walang tainga ang langgam tulad ng sa atin — sa halip, nararamdaman nila ang pag-uga o yanig ng lupa sa pamamagitan ng kanilang mga paa para makaramdam ng panganib.", "en": "Ants do not have ears like ours — instead they feel vibrations in the ground through their legs to sense danger.", "bis": "Ang subay walay dunggan sama sa ato — hinuon, mabati nila ang pag-uyog o vibration sa yuta pinaagi sa ilang mga tiil aron mabati ang katalagman."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bees-make-beeswax-g5", "domain": "LIVING_THINGS", "topic": "bees make wax from their body", "grades": [5, 6, 7], "terms": ["beeswax", "pagkit", "pagkit ng bubuyog", "talo sa putyukan", "wax", "gumagawa ng pagkit", "gibuhat nga talo", "naghimo og talo", "tiyan", "glandula", "lumalabas sa katawan", "mogawas sa lawas", "kandila", "bahay-pukyutan", "selula", "pukyutan", "bubuyog", "kinakatas"], "fact": {"tl": "Ang pagkit na ginagawang bahay-pukyutan ay galing mismo sa katawan ng bubuyog — lumalabas ito bilang maliliit na piraso mula sa ilalim ng kanilang tiyan.", "en": "The wax that bees build their comb from comes from their own bodies — it oozes out as tiny flakes from under their belly.", "bis": "Ang talo nga gibuhat sa putyukan nga balay gikan mismo sa lawas sa putyukan — mogawas kini isip gagmay nga piraso gikan sa ilawom sa ilang tiyan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "honeybee-many-flowers-one-trip-g5", "domain": "LIVING_THINGS", "topic": "bees visit many flowers for honey", "grades": [5, 6, 7], "terms": ["honey", "pulot", "dugos", "bulaklak", "bulak", "libu-libong bulaklak", "liboan ka bulak", "isang kutsara", "usa ka kutsara", "kaunting pulot", "gamay nga dugos", "maraming biyahe", "daghang biyahe", "buong buhay", "tibuok kinabuhi", "pukyutan", "bubuyog", "nektar", "trabaho"], "fact": {"tl": "Para makagawa lang ng isang kutsarang pulot, kailangang dalawin ng mga bubuyog ang libu-libong bulaklak — kaya napakalaki ng pinagsamang trabaho ng buong kolonya.", "en": "To make just one spoonful of honey, bees must visit thousands of flowers — that is how much combined work the whole colony puts in.", "bis": "Aron makahimo lang og usa ka kutsara nga dugos, kinahanglan duawon sa mga putyukan ang liboan ka bulak — mao kana ka dako ang gihiusang trabaho sa tibuok kolonya."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "brain-neuron-count-g6", "domain": "LIVING_THINGS", "topic": "how many neurons in the brain", "grades": [5, 6, 7, 8], "terms": ["neuron", "neurons", "utak", "selula", "selyula sa utak", "neuron sa utak", "bilyon", "bilyones", "86 billion", "nerve cell", "cell sa utak", "ihap", "daghan", "milya"], "fact": {"tl": "May humigit-kumulang 86 bilyong neuron (selula ng utak) ang utak ng tao, at bawat isa ay maaaring kumonekta sa libo-libong iba pang neuron.", "en": "The human brain has about 86 billion neurons (brain cells), and each one can connect to thousands of other neurons.", "bis": "Ang utak sa tawo adunay mga 86 ka bilyon nga neuron (selula sa utak), ug ang matag usa makakonektar sa liboan ka ubang neuron."}, "source": "encyclopedia-stable consensus (Azevedo et al. 2009)", "generator": "claude-workflow", "reviewed": false},
  {"id": "nerve-signal-speed-g6", "domain": "LIVING_THINGS", "topic": "how fast nerve signals travel", "grades": [5, 6, 7, 8], "terms": ["nerve signal", "bilis", "tulin", "kadali", "kapaspas", "senyas", "signal sa nerbiyos", "nerbiyos", "litrik", "elektrik", "kilometro kada oras", "fast", "kisame", "kuryente"], "fact": {"tl": "Napakabilis ng senyas sa nerbiyos — ang ilan ay umaabot ng mahigit 100 metro kada segundo, kaya kaagad mong nararamdaman ang isang tusok bago mo pa ito maisip.", "en": "Nerve signals are very fast — some travel over 100 meters per second, so you feel a prick almost instantly, even before you can think about it.", "bis": "Paspas kaayo ang senyas sa nerbiyos — ang uban moabot og kapin sa 100 metro kada segundo, mao nga mabati dayon nimo ang pagtusok bisan wala pa nimo kini mahunahuna."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "neuron-electric-chemical-g7", "domain": "LIVING_THINGS", "topic": "how neurons send messages", "grades": [6, 7, 8, 9], "terms": ["neuron", "synapse", "sinapsis", "kemikal", "kemikal na mensahe", "elektrik", "litrik", "agwat", "gintang", "puwang", "neurotransmitter", "mensahe", "mensahe sa neuron", "tumawid", "molukso"], "fact": {"tl": "Sa loob ng isang neuron, ang mensahe ay parang kuryenteng dumadaloy, ngunit sa pagitan ng dalawang neuron ay may maliit na agwat na tinatawid ng kemikal na mensahe.", "en": "Inside a neuron the message travels like electricity, but between two neurons there is a tiny gap that a chemical message crosses.", "bis": "Sulod sa usa ka neuron, ang mensahe mosibya sama sa kuryente, apan tunga sa duha ka neuron adunay gamay nga gintang nga tabukon sa usa ka kemikal nga mensahe."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "synapse-gap-g7", "domain": "LIVING_THINGS", "topic": "neurons do not touch", "grades": [6, 7, 8, 9], "terms": ["synapse", "sinapsis", "neuron", "hindi nagkakadikit", "wala magdikit", "agwat", "gintang", "puwang", "konektado", "konekta", "neurotransmitter", "kemikal", "lukso"], "fact": {"tl": "Karamihan sa mga neuron ay hindi talaga nagkakadikit — may napakaliit na agwat sa pagitan nila na tinatawag na synapse, kung saan dumadaan ang mga mensahe.", "en": "Most neurons do not actually touch — there is a microscopic gap between them called a synapse where messages pass across.", "bis": "Kadaghanan sa mga neuron dili gyud magdikit — adunay gagmay kaayo nga gintang tunga nila nga gitawag og synapse, diin moagi ang mga mensahe."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "myelin-speeds-signals-g8", "domain": "LIVING_THINGS", "topic": "why some nerves are faster", "grades": [7, 8, 9, 10], "terms": ["myelin", "mielina", "balot", "pambalot", "tabon", "insulator", "bilis", "paspas", "nerbiyos", "axon", "tambok", "tabang", "matulin", "mabilis"], "fact": {"tl": "Maraming nerbiyos ay may makapal na pambalot na tinatawag na myelin na parang insulator sa wire — pinapabilis nito nang husto ang pagdaloy ng senyas.", "en": "Many nerves have a fatty wrapping called myelin, like the insulation on a wire, which makes signals travel much faster.", "bis": "Daghang nerbiyos adunay baga nga pamutos nga gitawag og myelin, sama sa insulator sa alambre, nga makapakusog pag-ayo sa pag-agos sa senyas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "reflex-skips-brain-g6", "domain": "LIVING_THINGS", "topic": "why reflexes are so fast", "grades": [5, 6, 7, 8], "terms": ["reflex", "reflek", "repleks", "mabilis na reaksyon", "spinal cord", "gulugod", "utak", "lumaktaw", "wala moagi sa utak", "init", "umalis", "bawi", "kamay", "tugnaw"], "fact": {"tl": "Kapag nahawakan mo ang mainit, agad mong inaalis ang kamay bago pa man dumating ang senyas sa utak — ito ay reflex na pinamamahalaan ng spinal cord para makatipid ng oras.", "en": "When you touch something hot, you pull your hand away before the signal even reaches your brain — this is a reflex handled by the spinal cord to save time.", "bis": "Kon makahikap ka og init, kuhaon dayon nimo ang imong kamot sa dili pa moabot ang senyas sa utak — kini usa ka reflex nga gidumala sa spinal cord aron makatipig og oras."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "spinal-cord-own-reflexes-g7", "domain": "LIVING_THINGS", "topic": "the spinal cord can decide alone", "grades": [6, 7, 8, 9], "terms": ["spinal cord", "gulugod", "utok sa likod", "reflex", "reflek", "magdesisyon", "magdisisyon", "mag-isa", "wala magpaabot sa utak", "tuhod", "knee jerk", "nerbiyos"], "fact": {"tl": "Hindi lang daanan ng mensahe ang spinal cord — kaya nitong magpasya nang mag-isa para sa ilang reflex, gaya ng pagkislot ng binti kapag tinapik ang ibaba ng tuhod.", "en": "The spinal cord is not just a message highway — it can decide on its own for some reflexes, like your leg kicking when the spot below the knee is tapped.", "bis": "Ang spinal cord dili lang agianan sa mensahe — makahukom kini nga mag-isa alang sa pipila ka reflex, sama sa pagsipa sa bitiis kon tapikon ang ubos sa tuhod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "brain-two-halves-g6", "domain": "LIVING_THINGS", "topic": "the brain has two halves", "grades": [5, 6, 7, 8], "terms": ["left brain", "right brain", "kaliwa", "wala", "kanan", "tuo", "kalahati", "magkabahin", "hemisphere", "utak", "magkasalungat", "magkurus", "magtabang", "konektado"], "fact": {"tl": "Ang utak ay may dalawang kalahati, kaliwa at kanan, at ang kaliwang bahagi ang karaniwang kumokontrol sa kanang panig ng katawan habang ang kanan naman ang kumokontrol sa kaliwang panig.", "en": "The brain has two halves, left and right, and the left half mostly controls the right side of the body while the right half controls the left side.", "bis": "Ang utak adunay duha ka bahin, wala ug tuo, ug ang walang bahin maoy nagdumala sa tuong kilid sa lawas samtang ang tuo nagdumala sa walang kilid."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "brain-halves-connected-g7", "domain": "LIVING_THINGS", "topic": "the two brain halves talk to each other", "grades": [6, 7, 8, 9], "terms": ["corpus callosum", "kaliwa", "kanan", "wala", "tuo", "kalahati", "tulay", "taytayan", "nag-uusap", "magkonekta", "nerve fibers", "milyon", "utak", "magtinabangay"], "fact": {"tl": "Ang dalawang kalahati ng utak ay pinagdudugtong ng makapal na tulay ng nerbiyos na tinatawag na corpus callosum, kaya magkausap at magkatulong sila.", "en": "The two halves of the brain are joined by a thick bridge of nerves called the corpus callosum, so they can talk and work together.", "bis": "Ang duha ka bahin sa utak gisumpay sa baga nga taytayan sa nerbiyos nga gitawag og corpus callosum, mao nga sila magsultihanay ug magtinabangay."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "memory-is-connections-g7", "domain": "LIVING_THINGS", "topic": "what a memory is in the brain", "grades": [6, 7, 8, 9], "terms": ["memorya", "alaala", "memory", "panumduman", "handumanan", "koneksyon", "konekta", "neuron", "natutunan", "natun-an", "lumalakas", "molig-on", "ulit", "balikbalik", "pag-aaral"], "fact": {"tl": "Ang isang alaala ay parang bagong daan na binubuo sa pagitan ng mga neuron — kapag inuulit mo ang isang bagay, lumalakas ang koneksyon at mas madali mo itong natatandaan.", "en": "A memory is like a new pathway built between neurons — when you repeat something, that connection grows stronger and you remember it more easily.", "bis": "Ang usa ka panumduman sama sa bag-ong dalan nga gitukod tunga sa mga neuron — kon balikbalikon nimo ang usa ka butang, molig-on ang koneksyon ug mas sayon nimo kining mahinumduman."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "practice-strengthens-brain-g6", "domain": "LIVING_THINGS", "topic": "why practice makes things easier", "grades": [5, 6, 7, 8], "terms": ["practice", "pagsasanay", "ensayo", "pagbansay", "ulit", "balikbalik", "natutunan", "natun-an", "utak", "koneksyon", "lumalakas", "molig-on", "skill", "kahusay"], "fact": {"tl": "Tuwing nagsasanay ka — sa bisikleta o sa pagbasa — lumalakas ang koneksyon sa pagitan ng mga neuron, kaya unti-unting nagiging madali ang dating mahirap.", "en": "Every time you practice — riding a bike or reading — the connections between neurons grow stronger, so what was hard slowly becomes easy.", "bis": "Kada magbansay ka — sa bisikleta o sa pagbasa — molig-on ang koneksyon tunga sa mga neuron, mao nga ang lisod kaniadto anam-anam nga mahimong sayon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sleep-stores-memory-g6", "domain": "LIVING_THINGS", "topic": "why sleep helps memory", "grades": [5, 6, 7, 8], "terms": ["tulog", "katulog", "matulog", "sleep", "memorya", "alaala", "panumduman", "natutunan", "natun-an", "utak", "iniimbak", "tagoan", "isalin", "naaalala", "pahinga"], "fact": {"tl": "Habang natutulog ka, inaayos at iniimbak ng utak ang mga natutunan mo sa araw na iyon, kaya mas naaalala mo ang aral pagkatapos ng magandang tulog.", "en": "While you sleep, the brain sorts and stores what you learned that day, which is why you remember lessons better after a good night's sleep.", "bis": "Samtang natulog ka, hapsayon ug tipigan sa utak ang imong nakat-onan nianang adlawa, mao nga mas mahinumduman nimo ang leksyon human sa maayong tulog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sleep-cleans-brain-g7", "domain": "LIVING_THINGS", "topic": "the brain cleans itself during sleep", "grades": [6, 7, 8, 9], "terms": ["tulog", "matulog", "sleep", "utak", "naglilinis", "naghugas", "limpyo", "basura", "dumi", "hugaw", "waste", "kemikal", "tubig", "fluid", "nag-iipon"], "fact": {"tl": "Sa tulog, mas mahusay na nililinis ng utak ang sarili nito — inaanod palabas ang mga waste na naipon habang ikaw ay gising.", "en": "During sleep the brain cleans itself better, washing out waste that built up while you were awake.", "bis": "Sa pagkatulog, mas maayong manglimpyo ang utak sa kaugalingon niini, gianod pagawas ang hugaw nga natipon samtang ikaw nagmata."}, "source": "encyclopedia-stable consensus (Xie et al. 2013, glymphatic system)", "generator": "claude-workflow", "reviewed": false},
  {"id": "brain-uses-much-energy-g7", "domain": "LIVING_THINGS", "topic": "the brain uses lots of energy", "grades": [6, 7, 8, 9], "terms": ["utak", "brain", "enerhiya", "kusog", "gana", "energy", "porsyento", "20 percent", "maliit", "gamay", "pagkain", "glucose", "asukal", "dugo", "gutom", "nag-iisip"], "fact": {"tl": "Kahit maliit lang ang utak, gumagamit ito ng halos ikalimang bahagi (20%) ng enerhiya ng buong katawan — kaya kailangan nito ng tuloy-tuloy na pagkain at dugo.", "en": "Even though the brain is small, it uses about one-fifth (20%) of the whole body's energy — so it needs a constant supply of food and blood.", "bis": "Bisan gamay ra ang utak, mogamit kini og halos ikalima nga bahin (20%) sa kusog sa tibuok lawas — mao nga nagkinahanglan kini og kanunay nga pagkaon ug dugo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "brain-no-pain-receptors-g7", "domain": "LIVING_THINGS", "topic": "the brain feels no pain", "grades": [6, 7, 8, 9], "terms": ["utak", "brain", "sakit", "kirot", "kasakit", "walang nararamdaman", "wala mobati", "pain", "receptor", "operasyon", "gising", "feels", "ramdam", "kakaiba"], "fact": {"tl": "Ang utak mismo ay walang sakit na nararamdaman dahil wala itong pain sensor — ito ang nakakaramdam ng sakit ng ibang bahagi ng katawan, pero hindi ang sarili nito.", "en": "The brain itself feels no pain because it has no pain sensors — it is what senses pain everywhere else in the body, but not in itself.", "bis": "Ang utak mismo walay mabati nga kasakit kay wala kini pain sensor — kini ang mobati sa kasakit sa ubang bahin sa lawas, apan dili sa kaugalingon niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "senses-mapped-in-brain-g7", "domain": "LIVING_THINGS", "topic": "different brain parts do different jobs", "grades": [6, 7, 8, 9], "terms": ["utak", "bahagi", "bahin", "lugar", "area", "paningin", "panan-aw", "pakikinig", "pandinig", "paggalaw", "lihok", "trabaho", "buluhaton", "region", "magkakaiba", "tahas"], "fact": {"tl": "Iba't ibang bahagi ng utak ang may iba't ibang trabaho — may bahaging para sa paningin, may para sa pandinig, at may para sa paggalaw ng katawan.", "en": "Different parts of the brain have different jobs — one area handles seeing, another hearing, and another controls how the body moves.", "bis": "Lainlaing bahin sa utak adunay lainlaing buluhaton — adunay bahin alang sa panan-aw, adunay alang sa pandungog, ug adunay nagdumala sa paglihok sa lawas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "cerebellum-balance-g7", "domain": "LIVING_THINGS", "topic": "the part of the brain for balance", "grades": [6, 7, 8, 9], "terms": ["cerebellum", "serebelo", "balanse", "timbang", "ekwilibryo", "paggalaw", "lihok", "kinis", "smooth", "koordinasyon", "utak", "ibaba", "likod", "lakad", "sayaw"], "fact": {"tl": "Sa likod-ibaba ng utak ay may bahaging tinatawag na cerebellum na tumutulong sa balanse at sa kinis ng paggalaw, gaya sa paglakad o pagsayaw.", "en": "At the lower back of the brain is a part called the cerebellum that helps with balance and smooth movement, like walking or dancing.", "bis": "Sa ubos-likod nga bahin sa utak adunay gitawag og cerebellum nga motabang sa balanse ug sa hapsay nga paglihok, sama sa paglakaw o pagsayaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "brainstem-controls-breathing-g8", "domain": "LIVING_THINGS", "topic": "the brain keeps you alive automatically", "grades": [7, 8, 9, 10], "terms": ["brainstem", "punong-utak", "tangkay sa utak", "paghinga", "ginhawa", "tibok", "tibok ng puso", "heartbeat", "awtomatiko", "kusa", "kontrolado", "matulog", "buhay", "walang iniisip"], "fact": {"tl": "Ang punong-utak (brainstem) ang awtomatikong nagpapatakbo ng paghinga at tibok ng puso, kaya patuloy ito kahit tulog ka at walang iniisip.", "en": "The brainstem automatically runs your breathing and heartbeat, so they keep going even while you sleep and are not thinking about them.", "bis": "Ang tangkay sa utak (brainstem) maoy awtomatikong nagpadagan sa pagginhawa ug pagpitik sa kasingkasing, mao nga magpadayon kini bisan natulog ka ug walay gihunahuna."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "five-senses-go-to-brain-g5", "domain": "LIVING_THINGS", "topic": "the senses send signals to the brain", "grades": [4, 5, 6, 7], "terms": ["pandama", "limang pandama", "senses", "mata", "tainga", "balat", "ilong", "dila", "mata ug dalunggan", "panit", "ilong ug dila", "nerbiyos", "senyas", "utak", "nararamdaman", "mabati"], "fact": {"tl": "Hindi talaga ang mata, tainga, o balat ang 'nakakaramdam' — sila ay nangongolekta ng senyas at ipinapadala sa utak, at doon nabubuo ang nararamdaman.", "en": "Your eyes, ears, and skin do not really 'feel' on their own — they collect signals and send them to the brain, where the feeling is actually formed.", "bis": "Ang imong mata, dalunggan, o panit dili gyud 'mobati' sa ilang kaugalingon — nangolekta sila og senyas ug ipadala sa utak, ug didto matumaw ang gibati."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "pain-feels-slow-vs-touch-g8", "domain": "LIVING_THINGS", "topic": "some signals are faster than others", "grades": [7, 8, 9, 10], "terms": ["sakit", "kasakit", "kirot", "pain", "haplos", "hapuhap", "touch", "mabilis", "mabagal", "hinay", "paspas", "nerbiyos", "uri", "klase", "myelin", "senyas", "dalawang"], "fact": {"tl": "May dalawang uri ng senyas ng sakit: ang mabilis na nagsasabing 'aray!' kaagad, at ang mabagal na nag-iiwan ng matagal na kirot pagkatapos.", "en": "There are two kinds of pain signals: a fast one that says 'ouch!' right away, and a slow one that leaves a dull ache afterward.", "bis": "Adunay duha ka matang sa senyas sa kasakit: ang paspas nga moingon dayon og 'agay!', ug ang hinay nga mobilin og taas nga kasakit human niini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "brain-mostly-water-fat-g6", "domain": "LIVING_THINGS", "topic": "what the brain is made of", "grades": [5, 6, 7, 8], "terms": ["utak", "brain", "tubig", "tubig ug tambok", "taba", "tambok", "fat", "water", "malambot", "humok", "soft", "bungo", "kalabera", "skull", "protektado", "gawa sa"], "fact": {"tl": "Ang utak ay malambot at karamihan ay tubig at taba — kaya ito ay protektado ng matigas na bungo at lutang sa malinis na likido sa loob.", "en": "The brain is soft and mostly water and fat — that is why it is protected by the hard skull and floats in clean fluid inside.", "bis": "Ang utak humok ug kasagaran tubig ug tambok — mao nga gipanalipdan kini sa gahi nga bungo ug naglutaw sa limpyo nga likido sa sulod."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "left-right-cross-over-g8", "domain": "LIVING_THINGS", "topic": "why the brain controls the opposite side", "grades": [7, 8, 9, 10], "terms": ["kaliwa", "kanan", "wala", "tuo", "magkrus", "magkurus", "nagsasalubong", "cross", "nerbiyos", "kamay", "lihok", "utak", "kabaligtaran", "opposite", "kontra", "panig"], "fact": {"tl": "Ang mga nerbiyong nagmumula sa utak ay nagkukurus pababa sa katawan, kaya ang kaliwang utak ang nag-uutos sa kanang kamay at kabaligtaran.", "en": "The nerves leaving the brain cross over on their way down the body, which is why the left brain commands the right hand and vice versa.", "bis": "Ang mga nerbiyos nga gikan sa utak magkurus paubos sa lawas, mao nga ang walang utak maoy nagmando sa tuong kamot ug sukwahi."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "babies-make-many-connections-g7", "domain": "LIVING_THINGS", "topic": "young brains learn fastest", "grades": [6, 7, 8, 9], "terms": ["sanggol", "bata", "masuso", "baby", "utak", "koneksyon", "konekta", "mabilis matuto", "natuto", "bagong wika", "wika", "lengguwahe", "nagdaragdag", "midaghan", "neuron", "lumalaki"], "fact": {"tl": "Ang utak ng sanggol at bata ay gumagawa ng bagong koneksyon nang napakabilis, kaya mas madali silang matutong magsalita ng bagong wika kaysa sa matatanda.", "en": "The brains of babies and young children make new connections very fast, which is why they learn to speak new languages more easily than adults.", "bis": "Ang utak sa masuso ug bata maghimo og bag-ong koneksyon nga paspas kaayo, mao nga mas sayon silang makakat-on og bag-ong pinulongan kaysa sa hamtong."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "muscle-memory-g6", "domain": "LIVING_THINGS", "topic": "why you do not forget how to ride a bike", "grades": [5, 6, 7, 8], "terms": ["muscle memory", "alaala ng kalamnan", "panumduman sa lawas", "bisikleta", "lumangoy", "langoy", "nakalimutan", "wala makalimti", "utak", "awtomatiko", "kusa", "natutunan", "katawan", "naalala"], "fact": {"tl": "Kapag ilang ulit mong ginawa ang isang galaw gaya ng pagbibisikleta, naitatago ito ng utak bilang 'muscle memory' kaya hindi mo ito makakalimutan kahit matagal nang hindi nagawa.", "en": "When you repeat a movement like cycling many times, the brain stores it as 'muscle memory,' so you do not forget it even after a long time.", "bis": "Kon balikbalikon nimo ang usa ka lihok sama sa pagbisikleta, tipigan kini sa utak isip 'muscle memory,' mao nga dili nimo kini malimtan bisan dugay na nga wala nabuhat."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "nerves-network-whole-body-g6", "domain": "LIVING_THINGS", "topic": "nerves reach every part of the body", "grades": [5, 6, 7, 8], "terms": ["nerbiyos", "nerves", "ugat sa nerbiyos", "buong katawan", "tibuok lawas", "kalat", "sangay", "branch", "network", "kable", "wire", "haba", "milya", "kilometro", "abot", "konektado"], "fact": {"tl": "Ang mga nerbiyos ay parang network ng maliliit na kable na umaabot sa halos bawat bahagi ng katawan, mula ulo hanggang dulo ng paa.", "en": "Nerves are like a network of tiny wires that reach almost every part of the body, from the head down to the tips of the toes.", "bis": "Ang mga nerbiyos sama sa network sa gagmay nga alambre nga moabot sa halos tanang bahin sa lawas, gikan sa ulo hangtod sa tumoy sa tiil."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "blinking-reflex-g4", "domain": "LIVING_THINGS", "topic": "blinking is a protective reflex", "grades": [3, 4, 5, 6], "terms": ["kurap", "pagkurap", "blink", "pagpilok", "reflex", "reflek", "mata", "bagay palapit", "kalit", "agad", "kusa", "awtomatiko", "proteksyon", "panalipod", "pumikit", "mata ug nerbiyos"], "fact": {"tl": "Kapag may bagay na biglang lumapit sa mata mo, kusang pumipikit ka bago mo pa ito maisip — isa itong reflex para maprotektahan ang mata.", "en": "When something suddenly comes near your eye, you blink automatically before you can even think about it — this is a reflex to protect the eye.", "bis": "Kon adunay butang nga kalit nga moduol sa imong mata, mopilok ka dayon sa wala pa nimo kini mahunahuna — usa kini ka reflex aron panalipdan ang mata."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "brain-fills-in-blind-spot-g8", "domain": "LIVING_THINGS", "topic": "the brain fills in what the eye misses", "grades": [7, 8, 9, 10], "terms": ["blind spot", "bulag na puntos", "buta nga bahin", "mata", "utak", "pinupunan", "gisapnayan", "kompleto", "hindi napapansin", "wala mamatikdi", "litrato", "imahe", "image", "puno", "natural"], "fact": {"tl": "May maliit na 'blind spot' ang bawat mata kung saan walang nakikita, ngunit pinupunan ito ng utak kaya hindi mo napapansin ang butas sa tinitingnan mo.", "en": "Each eye has a small 'blind spot' where it sees nothing, but the brain fills it in so you never notice a hole in what you are looking at.", "bis": "Ang matag mata adunay gamay nga 'blind spot' diin walay makita, apan sapnayan kini sa utak mao nga dili nimo mamatikdan ang lungag sa imong gitan-aw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "neurons-do-not-regrow-easily-g8", "domain": "LIVING_THINGS", "topic": "brain cells are hard to replace", "grades": [7, 8, 9, 10], "terms": ["neuron", "selula ng utak", "selula sa utak", "hindi madaling tumubo", "lisod motubo", "regrow", "replace", "mahalaga", "ingat", "panalipod", "helmet", "bungo", "skull", "protektado", "iba pang selula"], "fact": {"tl": "Hindi tulad ng karamihan sa selula ng katawan, ang mga neuron ay napakahirap palitan kapag nasira — kaya napakahalagang ingatan ang ulo, halimbawa sa pagsuot ng helmet.", "en": "Unlike most body cells, neurons are very hard to replace once damaged — that is why protecting the head, such as by wearing a helmet, matters so much.", "bis": "Dili sama sa kadaghanang selula sa lawas, ang mga neuron lisod kaayong ilisan kon madaot na — mao nga importante kaayo nga ampingan ang ulo, sama sa pagsul-ob og helmet."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "brain-tired-needs-rest-g5", "domain": "LIVING_THINGS", "topic": "the brain gets tired too", "grades": [4, 5, 6, 7], "terms": ["utak", "brain", "pagod", "kapoy", "gikapoy", "napapagod", "tired", "pahinga", "rest", "pag-aaral", "matagal", "hirap mag-isip", "lisod maghunahuna", "tigil", "pahinga sa utak"], "fact": {"tl": "Kahit hindi kalamnan, napapagod din ang utak kapag matagal kang nag-aaral o nag-iisip, kaya kailangan nito ng pahinga para gumana nang maayos.", "en": "Even though it is not a muscle, the brain also gets tired when you study or think for a long time, so it needs breaks to work well.", "bis": "Bisan dili kini kaunoran, makapoy usab ang utak kon dugay kang magtuon o maghunahuna, mao nga nagkinahanglan kini og pahulay aron molihok og maayo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bird-migration-magnetic-sense-g6", "domain": "LIVING_THINGS", "topic": "bird migration magnetic compass", "grades": [5, 6, 7], "terms": ["paglipat", "lumilipat na ibon", "migrasyon", "ibon", "kompas", "magnetismo ng Mundo", "magnetic field", "earth's magnetic field", "balhin", "balhinon nga langgam", "panaw", "compass", "navigation", "langgam"], "fact": {"tl": "Maraming lumilipat na ibon ang may parang panloob na kompas na nakakaramdam ng magnetikong larangan ng Mundo, kaya hindi sila naliligaw kahit gabi o maulap ang langit.", "en": "Many migrating birds have a kind of inner compass that senses Earth's magnetic field, so they can find their way even on cloudy nights.", "bis": "Daghang balhinon nga langgam adunay morag sulod nga kompas nga makabati sa magnetikong puwersa sa Kalibutan, mao nga dili sila mawala bisan gabii o dag-om ang langit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bird-migration-distance-arctic-tern-g6", "domain": "LIVING_THINGS", "topic": "longest bird migration", "grades": [5, 6, 7], "terms": ["pinakamahabang paglipat", "Arctic tern", "migrasyon", "ibon", "libong kilometro", "layo", "tag-init", "balhin", "langgam", "pinakalayo nga panaw", "palaibon"], "fact": {"tl": "Ang Arctic tern ang ibong pinakamalayo ang nilalakbay—lumilipad ito mula Hilagang polo papuntang Timog polo at pabalik kada taon, na umabot sa libo-libong kilometro.", "en": "The Arctic tern travels farther than any other bird, flying from near the North Pole to near the South Pole and back each year, covering tens of thousands of kilometers.", "bis": "Ang Arctic tern mao ang langgam nga pinakalayo molupad—gikan sa Amihanang polo paingon sa Habagatang polo ug balik matag tuig, nga moabot ug liboan ka kilometro."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bird-migration-v-formation-g5", "domain": "LIVING_THINGS", "topic": "birds flying in V formation", "grades": [4, 5, 6], "terms": ["hugis V", "pormasyong V", "lumilipad na ibon", "gansa", "V formation", "lumipad nang sabay", "balhin", "langgam nga naglupad", "makatipid ng lakas", "draft", "hangin", "gansâ"], "fact": {"tl": "Maraming malalaking ibon na tulad ng gansa ang lumilipad nang hugis-V upang makasakay sa hanging itinutulak ng pakpak ng nauuna, kaya nakakatipid sila ng lakas sa mahabang biyahe.", "en": "Big birds like geese fly in a V shape so each one can ride the air pushed up by the bird ahead, saving energy on long journeys.", "bis": "Daghang dagkong langgam sama sa gansa molupad nga porma sa V aron makasakay sa hangin nga gitulod sa pako sa nag-una, mao nga makatipig sila ug kusog sa taas nga panaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bird-migration-fat-fuel-g6", "domain": "LIVING_THINGS", "topic": "birds store fat for migration", "grades": [5, 6, 7], "terms": ["taba", "gasolina ng katawan", "nag-iipon ng taba", "migrasyon", "lumilipad", "ibon", "tambok", "gas sa lawas", "balhin", "walay hunong nga lupad", "langgam"], "fact": {"tl": "Bago lumipat, kumakain nang marami ang mga ibon at nag-iipon ng taba na ginagamit nilang gasolina ng katawan para makalipad nang malayo nang halos walang tigil.", "en": "Before migrating, birds eat a lot and store body fat, which they burn as fuel to fly long distances almost without stopping.", "bis": "Sa dili pa mobalhin, mokaon ug daghan ang mga langgam ug magtigom ug tambok nga ilang gamiton nga gasolina sa lawas aron makalupad ug layo nga halos walay hunong."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "penguin-feathers-waterproof-g4", "domain": "LIVING_THINGS", "topic": "how penguins stay warm and dry", "grades": [3, 4, 5], "terms": ["pingwino", "penguin", "balahibo", "makapal na balahibo", "tubig", "langis", "hindi binabasa", "mainit", "panit", "balhibo", "init", "dili mabasa", "tubig nga bugnaw"], "fact": {"tl": "Ang pingwino ay may makakapal at magkakapatong na balahibo na pinapahiran ng langis mula sa katawan, kaya hindi tumatagos ang malamig na tubig at nananatili silang mainit.", "en": "Penguins have thick, overlapping feathers coated with oil from their own body, so cold water can't soak through and they stay warm.", "bis": "Ang penguin adunay baga ug nagpatong-patong nga balhibo nga gipahid ug lana gikan sa lawas, mao nga dili makatagos ang bugnaw nga tubig ug magpabilin silang init."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "penguin-blubber-fat-layer-g4", "domain": "LIVING_THINGS", "topic": "penguin fat keeps it warm", "grades": [3, 4, 5], "terms": ["pingwino", "penguin", "makapal na taba", "blubber", "init", "lamig", "yelo", "tambok", "panit", "kainit", "katugnaw", "layer sa tambok"], "fact": {"tl": "Sa ilalim ng balat ng pingwino ay may makapal na taba (blubber) na parang kumot na pumipigil sa init ng katawan na kumalat, kaya nakakaya nilang manirahan sa nagyeyelong lugar.", "en": "Under a penguin's skin is a thick layer of fat called blubber that works like a blanket to hold in body heat, letting them live in icy places.", "bis": "Sa ilalom sa panit sa penguin adunay baga nga tambok (blubber) nga sama sa habol nga magpugong sa init sa lawas, mao nga makapuyo sila sa yelo nga dapit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "penguin-feet-cold-ice-g5", "domain": "LIVING_THINGS", "topic": "why penguin feet don't freeze", "grades": [4, 5, 6], "terms": ["pingwino", "penguin", "paa", "hindi nagyeyelo", "yelo", "dugo", "init", "tiil", "wala mag-yelo", "yelo nga salog", "sirkulasyon", "dugo nga mainit"], "fact": {"tl": "Hindi nagyeyelo ang paa ng pingwino kahit nakatayo sa yelo dahil pinapainit ng mainit na dugong dumadaloy palabas ang malamig na dugong pabalik, kaya kontrolado ang temperatura ng paa.", "en": "A penguin's feet don't freeze on ice because warm blood flowing out heats the cold blood flowing back, keeping the feet just cool enough but never frozen.", "bis": "Dili mag-yelo ang tiil sa penguin bisan nagbarog sa yelo kay ang init nga dugo nga mogawas magpainit sa bugnaw nga dugo nga mobalik, mao nga kontrolado ang temperatura sa tiil."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "owl-silent-flight-g5", "domain": "LIVING_THINGS", "topic": "why owls fly silently", "grades": [4, 5, 6], "terms": ["kuwago", "owl", "tahimik na lupad", "walang ingay", "balahibo", "pakpak", "pangangaso", "ngiwngiw", "hilom nga lupad", "walay saba", "pako", "pagpangayam"], "fact": {"tl": "May malambot at parang palaylay na gilid ang pakpak ng kuwago na pumipigil sa ingay ng hangin, kaya halos tahimik itong lumilipad at hindi naririnig ng huhulihing biktima.", "en": "An owl's wings have soft, comb-like edges that muffle the sound of the air, so it flies almost silently and its prey never hears it coming.", "bis": "Ang pako sa kuwago adunay humok ug morag sudlay nga sidsid nga magpugong sa saba sa hangin, mao nga halos hilom kini molupad ug dili madunggan sa biktima."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "owl-head-turn-g4", "domain": "LIVING_THINGS", "topic": "owls turn their heads far", "grades": [3, 4, 5], "terms": ["kuwago", "owl", "umiikot ang ulo", "ulo", "leeg", "hindi gumagalaw ang mata", "pagtingin sa likod", "liog", "ulo nga molingi", "mata nga dili molihok", "balikan ang likod"], "fact": {"tl": "Hindi makagalaw sa loob ng socket ang malalaking mata ng kuwago, kaya para makatingin sa gilid o likod, iniikot nito ang ulo nang napakalayo—halos kalahati ng paligid.", "en": "An owl's big eyes can't move in their sockets, so to look to the side or behind, it turns its whole head very far—about halfway around.", "bis": "Dili makalihok sa sulod sa luna ang dagkong mata sa kuwago, mao nga aron makatan-aw sa kilid o likod, lingion niini ang ulo ug halayo kaayo—mga katunga sa palibot."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "owl-hearing-hunt-dark-g5", "domain": "LIVING_THINGS", "topic": "owls hunt by hearing", "grades": [4, 5, 6], "terms": ["kuwago", "owl", "pandinig", "tainga", "pangangaso sa dilim", "tunog", "daga", "dunggan", "talinga", "pagpaminaw", "pagpangayam sa ngitngit", "ilaga", "dunog"], "fact": {"tl": "May mga tainga ang kuwago na magkaiba ng taas sa bawat tabi ng ulo, kaya nakikita nila kung saan eksaktong galing ang tunog at nahuhuli nila ang daga sa ganap na kadiliman.", "en": "An owl's ears are set at different heights on each side of its head, so it can pinpoint exactly where a sound comes from and catch a mouse in total darkness.", "bis": "Ang dunggan sa kuwago lain-laing katas-on sa matag kilid sa ulo, mao nga mabantayan niini asa gyud gikan ang tingog ug madakpan ang ilaga bisan sa hingpit nga kangitngit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "owl-night-vision-g4", "domain": "LIVING_THINGS", "topic": "owl eyes for night", "grades": [3, 4, 5], "terms": ["kuwago", "owl", "mata", "malaking mata", "nakakakita sa dilim", "gabi", "liwanag", "mata nga dako", "makakita sa ngitngit", "gabii", "kahayag", "mata sa kuwago"], "fact": {"tl": "Napakalaki ng mga mata ng kuwago kaya marami itong nasasalong liwanag, at dahil dito ay nakakakita pa rin sila kahit napakadilim na sa gabi.", "en": "An owl's eyes are very large, so they catch a lot of light, letting the owl see even when it is very dark at night.", "bis": "Dagko kaayo ang mata sa kuwago mao nga daghan kini ug masulod nga kahayag, busa makakita gihapon sila bisan ngitngit na kaayo sa gabii."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hummingbird-hover-wings-g5", "domain": "LIVING_THINGS", "topic": "how hummingbirds hover", "grades": [4, 5, 6], "terms": ["hummingbird", "ibon", "lumulutang sa ere", "mabilis na pakpak", "figure-eight", "nektar", "bulaklak", "hovering", "langgam", "naglutaw sa hangin", "kusog nga pako", "dugos sa bulak"], "fact": {"tl": "Pinapagpag ng hummingbird ang mga pakpak nito nang sobrang bilis sa hugis-walo, kaya nakakalutang ito sa ere nang nakatigil habang sumisipsip ng nektar sa bulaklak.", "en": "A hummingbird beats its wings incredibly fast in a figure-eight motion, letting it hover in one spot in the air while it sips nectar from a flower.", "bis": "Gipakpak sa hummingbird ang iyang mga pako ug kusog kaayo nga porma sa walo, mao nga makalutaw kini sa hangin nga walay lihok samtang nagsuyop ug dugos sa bulak."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hummingbird-fly-backward-g5", "domain": "LIVING_THINGS", "topic": "hummingbirds fly backward", "grades": [4, 5, 6], "terms": ["hummingbird", "ibon", "paatras na lupad", "lumipad paurong", "tanging ibon", "backward", "pakpak", "langgam", "molupad paatras", "bugtong nga langgam", "pako"], "fact": {"tl": "Ang hummingbird ang tanging ibong kayang lumipad nang paatras, dahil umiikot ang buong pakpak nito sa balikat na parang propeler.", "en": "The hummingbird is the only bird that can fly backward, because its whole wing can swivel at the shoulder like a propeller.", "bis": "Ang hummingbird mao ra ang langgam nga makalupad paatras, kay ang tibuok pako niini makatuyok sa abaga sama sa propeler."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hummingbird-fast-heart-g6", "domain": "LIVING_THINGS", "topic": "hummingbird heart and energy", "grades": [5, 6, 7], "terms": ["hummingbird", "ibon", "mabilis na tibok ng puso", "puso", "kumakain ng marami", "enerhiya", "nektar", "kasingkasing", "kusog nga pitik", "kaon ug daghan", "kusog sa lawas", "langgam"], "fact": {"tl": "Napakabilis tumibok ng puso ng hummingbird, kaya kailangan nitong kumain ng pagkaing katumbas ng kalahati ng bigat nito araw-araw para may sapat na enerhiya.", "en": "A hummingbird's heart beats extremely fast, so it must eat about half its own weight in food every day to have enough energy.", "bis": "Kusog kaayo mopitik ang kasingkasing sa hummingbird, mao nga kinahanglan kini mokaon ug pagkaon nga katunga sa iyang gibug-aton kada adlaw aron adunay igong kusog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hummingbird-torpor-g6", "domain": "LIVING_THINGS", "topic": "hummingbird saves energy at night", "grades": [5, 6, 7], "terms": ["hummingbird", "ibon", "torpor", "nagpapahinga", "bumabagal ang katawan", "gabi", "enerhiya", "langgam", "mohinay ang lawas", "gabii", "gas sa lawas", "tibok"], "fact": {"tl": "Sa gabi, pinapabagal ng hummingbird ang tibok ng puso at hininga nito (torpor) para makatipid ng enerhiya, dahil masyadong maliit ang katawan nito para mag-imbak ng pagkain.", "en": "At night a hummingbird slows its heartbeat and breathing (called torpor) to save energy, because its tiny body can't store much food.", "bis": "Sa gabii, ipahinay sa hummingbird ang pitik sa kasingkasing ug ginhawa niini (torpor) aron makatipig ug kusog, kay gamay ra kaayo ang lawas niini aron makatigom ug pagkaon."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bird-song-territory-mate-g5", "domain": "LIVING_THINGS", "topic": "why birds sing", "grades": [4, 5, 6], "terms": ["bakit kumakanta ang ibon", "huni ng ibon", "awit", "teritoryo", "tumawag ng kapareha", "ibon", "kanta", "awit sa langgam", "huni", "teritoryo nga panag-iya", "pagtawag ug kapikas", "langgam"], "fact": {"tl": "Kumakanta ang maraming lalaking ibon para sabihin sa ibang ibon na sa kanila ang lugar na iyon at para makaakit ng kapareha—parang paghahayag at pag-aanyaya sa isang awit.", "en": "Many male birds sing to tell other birds 'this area is mine' and to attract a mate—it's both a warning and an invitation in song.", "bis": "Daghang laki nga langgam ang mokanta aron isulti sa ubang langgam nga ila kana nga dapit ug aron makadani ug kapikas—usa kini ka pasidaan ug pagdapit sa awit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bird-song-learned-g6", "domain": "LIVING_THINGS", "topic": "birds learn their songs", "grades": [5, 6, 7], "terms": ["natututo ng kanta", "ibon", "gumagaya", "magulang", "awit", "pinag-aaralan", "sisiw", "nakat-on ug kanta", "langgam", "manununod", "pagtuon sa awit", "piso"], "fact": {"tl": "Maraming batang ibon ang natututo ng kanta nila sa pamamagitan ng pakikinig at paggaya sa magulang, kaya kung paano kumanta ang isang uri ay parang minanang wika.", "en": "Many young birds learn their songs by listening to and copying their parents, so each kind of bird's song is passed down almost like a language.", "bis": "Daghang batan-ong langgam ang makakat-on sa ilang kanta pinaagi sa pagpaminaw ug pagsundog sa ginikanan, mao nga ang awit sa matag matang sama sa napanunod nga pinulongan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bird-syrinx-two-notes-g7", "domain": "LIVING_THINGS", "topic": "how birds make song (syrinx)", "grades": [6, 7, 8], "terms": ["syrinx", "boses ng ibon", "awit", "dalawang tunog nang sabay", "lalamunan", "huni", "ibon", "tunog sa langgam", "duha ka tingog", "tutunlan", "awit", "langgam"], "fact": {"tl": "May espesyal na organ ang ibon na tinatawag na syrinx sa dulo ng lalamunan, at dahil may dalawang panig ito, may ibong kayang umawit ng dalawang nota nang sabay-sabay.", "en": "Birds have a special voice organ called the syrinx deep in the throat, and because it has two sides, some birds can sing two notes at the same time.", "bis": "Ang langgam adunay espesyal nga organ nga gitawag ug syrinx sa kinahiladman sa tutunlan, ug tungod kay duha kini ka kilid, may langgam nga makaawit ug duha ka nota dungan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bird-tool-use-crow-g6", "domain": "LIVING_THINGS", "topic": "birds that use tools", "grades": [5, 6, 7], "terms": ["uwak", "crow", "gumagamit ng kasangkapan", "sanga", "tool use", "matalinong ibon", "uod", "gigamit nga kahoy", "uwak nga maabtik", "sanga sa kahoy", "ulod", "langgam"], "fact": {"tl": "May matatalinong uwak na gumagamit ng maliliit na sanga o tinik bilang kasangkapan para tuhugin at hilahin ang mga uod mula sa loob ng kahoy.", "en": "Some clever crows use small twigs or thorns as tools to poke and pull grubs out from inside wood.", "bis": "Adunay maabtik nga uwak nga mogamit ug gagmay nga sanga o tunok ingong galamiton aron tuslokon ug bira-bira ang mga ulod gikan sa sulod sa kahoy."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bird-tool-bend-hook-g7", "domain": "LIVING_THINGS", "topic": "crows make hooks (tool making)", "grades": [6, 7, 8], "terms": ["uwak", "crow", "gumagawa ng kawit", "baluktot na sanga", "hook", "matalino", "tool making", "naghimo ug taga", "baliko nga sanga", "maabtik", "paghimo ug galamiton", "langgam"], "fact": {"tl": "May mga uwak na hindi lang gumagamit kundi gumagawa pa ng kasangkapan—binabaluktot nila ang sanga para gawing kawit na panghila ng pagkain, isang gawaing iilang hayop lang ang kaya.", "en": "Some crows don't just use tools—they make them, bending a twig into a hook to pull out food, something very few animals can do.", "bis": "Adunay mga uwak nga dili lang mogamit kondili maghimo pa ug galamiton—ilang balikoon ang sanga aron mahimong taga nga ibira sa pagkaon, usa ka butang nga pipila ra ka hayop ang makahimo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "peregrine-falcon-fastest-g5", "domain": "LIVING_THINGS", "topic": "fastest animal peregrine falcon", "grades": [4, 5, 6], "terms": ["peregrine falcon", "lawin", "pinakamabilis na hayop", "sumusugod pababa", "stoop", "dive", "mabilis", "banog", "pinakapaspas nga hayop", "sundo paubos", "lupad nga kusog", "langgam"], "fact": {"tl": "Ang peregrine falcon ang pinakamabilis na hayop sa mundo—kapag sumusugod ito pababa para manghuli, umaabot ito ng higit 300 kilometro kada oras.", "en": "The peregrine falcon is the fastest animal in the world—when it dives down to catch prey, it can reach over 300 kilometers per hour.", "bis": "Ang peregrine falcon mao ang pinakapaspas nga hayop sa kalibutan—kon mosulong kini paubos aron mangayam, makaabot kini ug kapin sa 300 ka kilometro kada oras."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "peregrine-falcon-nostril-g7", "domain": "LIVING_THINGS", "topic": "how falcons breathe at high speed", "grades": [6, 7, 8], "terms": ["peregrine falcon", "lawin", "butas ng ilong", "mabilis na lupad", "hangin", "huminga", "stoop", "banog", "lungag sa ilong", "kusog nga lupad", "ginhawa", "langgam"], "fact": {"tl": "Sa napakabilis na pagsugod ng peregrine falcon, may parang maliit na tukod sa loob ng butas ng ilong nito na pumipigil sa hanging dumadagsa para makahinga pa rin ito habang mabilis na lumilipad.", "en": "During the peregrine falcon's super-fast dive, small bony bumps inside its nostrils slow the rushing air so it can still breathe while plummeting.", "bis": "Sa kusog kaayo nga pagsulong sa peregrine falcon, adunay morag gagmay nga bukog sa sulod sa lungag sa ilong niini nga magpahinay sa nagdagsang hangin aron makaginhawa gihapon kini samtang kusog molupad."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bird-hollow-bones-fly-g5", "domain": "LIVING_THINGS", "topic": "why birds are light enough to fly", "grades": [4, 5, 6], "terms": ["ibon", "magaan na buto", "hollow bones", "lumilipad", "magaan", "buto na may hungkag", "balahibo", "gaan nga bukog", "langgam", "molupad", "bukog nga hungaw", "gaan"], "fact": {"tl": "Magaan na lumipad ang ibon dahil maraming buto nito ay hungkag o may laman na hangin sa loob, kaya hindi sila masyadong mabigat kahit malalaki.", "en": "Birds are light enough to fly because many of their bones are hollow, filled with air inside, so they aren't too heavy even when large.", "bis": "Gaan molupad ang langgam kay daghan sa ilang bukog hungaw o may sulod nga hangin, mao nga dili sila bug-at bisan dagko sila."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bird-preen-oil-feathers-g5", "domain": "LIVING_THINGS", "topic": "birds oil their feathers", "grades": [4, 5, 6], "terms": ["ibon", "naglilinis ng balahibo", "preen", "langis", "glandula", "tubig", "balahibo", "paglinis sa balhibo", "lana", "langgam", "tubig nga dili motagos", "glandula sa lana"], "fact": {"tl": "Sinasagap ng maraming ibon ang langis mula sa glandula malapit sa buntot at ipinapahid ito sa balahibo gamit ang tuka, kaya lalong matibay at hindi binabasa ng tubig ang balahibo.", "en": "Many birds take oil from a gland near the tail and spread it over their feathers with their beak, which keeps the feathers strong and water-resistant.", "bis": "Daghang langgam ang mokuha ug lana gikan sa glandula duol sa ikog ug ipahid kini sa ilang balhibo gamit ang sungo, mao nga molig-on ug dili mabasa ang balhibo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "bird-migration-stars-navigation-g7", "domain": "LIVING_THINGS", "topic": "birds navigate by the stars", "grades": [6, 7, 8], "terms": ["ibon", "bituin", "paglipat", "gabi", "navigation", "pagsunod sa bituin", "migrasyon", "bitoon", "langgam", "panaw sa gabii", "pagsubay sa bitoon", "balhin"], "fact": {"tl": "May mga ibong lumilipat sa gabi na gumagamit ng padron ng mga bituin sa langit bilang gabay sa direksyon, na parang ginagamit nilang mapa ang kalangitan.", "en": "Some birds that migrate at night use the patterns of the stars to find their direction, almost like reading the sky as a map.", "bis": "Adunay mga langgam nga mobalhin sa gabii nga mogamit sa han-ay sa mga bitoon ingong giya sa direksyon, nga morag basahon nila ang langit ingong mapa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "penguin-countershading-g6", "domain": "LIVING_THINGS", "topic": "why penguins are black and white", "grades": [5, 6, 7], "terms": ["pingwino", "penguin", "itim at puti", "kulay", "pagtatago", "camouflage", "countershading", "itom ug puti", "kolor", "panagò", "tinabunan nga kolor", "biktima"], "fact": {"tl": "Itim ang likod at puti ang tiyan ng pingwino para mahirap silang makita sa tubig—mula sa itaas, halos kasing-itim ng madilim na dagat; mula sa ilalim, halos kasing-puti ng maliwanag na langit.", "en": "A penguin is black on its back and white on its belly so it's hard to spot in the water—from above it blends with the dark sea, and from below with the bright sky.", "bis": "Itom ang likod ug puti ang tiyan sa penguin aron lisod silang makita sa tubig—gikan sa taas, morag itom sa ngitngit nga dagat; gikan sa ubos, morag puti sa hayag nga langit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "hummingbird-tongue-nectar-g6", "domain": "LIVING_THINGS", "topic": "how hummingbirds drink nectar", "grades": [5, 6, 7], "terms": ["hummingbird", "ibon", "dila", "nektar", "sumisipsip", "bulaklak", "tuka", "dila nga taas", "dugos sa bulak", "langgam", "pagsuyop", "sungo"], "fact": {"tl": "Mahaba ang dila ng hummingbird at may maliliit na dulong parang sandok na mabilis nitong inilalabas-pasok para sumalok ng nektar sa kaibuturan ng bulaklak.", "en": "A hummingbird's tongue is long with tiny scooping tips that it flicks in and out very fast to lap up nectar deep inside a flower.", "bis": "Taas ang dila sa hummingbird nga adunay gagmay nga morag kutsara nga tumoy nga paspas niini ipagawas-pasulod aron magkuha ug dugos sa kahiladman sa bulak."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "owl-pellet-bones-g5", "domain": "LIVING_THINGS", "topic": "owls cough up pellets", "grades": [4, 5, 6], "terms": ["kuwago", "owl", "pellet", "isinusuka", "buto at balahibo", "hindi natunaw", "daga", "gisuka", "bukog ug balhibo", "wala matunaw", "kuwago nga mosuka", "ilaga"], "fact": {"tl": "Hindi kayang tunawin ng kuwago ang buto at balahibo ng nakain nitong daga, kaya isinusuka nito ang mga ito bilang siksik na bilog na tinatawag na pellet.", "en": "An owl can't digest the bones and fur of the mouse it eats, so it coughs them back up as a packed lump called a pellet.", "bis": "Dili matunaw sa kuwago ang bukog ug balhibo sa ilaga nga iyang gikaon, mao nga isuka niini kini ingong siksik nga bola nga gitawag ug pellet."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rainforest-canopy-dark-floor-g6", "domain": "EARTH_SPACE", "topic": "why a rainforest floor is dark", "grades": [5, 6, 7], "terms": ["rainforest", "kagubatan", "kalasangan", "canopy", "tuktok ng puno", "tumoy sa kahoy", "dahon", "dahon nga baga", "madilim", "ngitngit", "sahig ng gubat", "salog sa lasang", "sikat ng araw", "kahayag sa adlaw", "sinasala", "ginababagan", "kakaunting halaman", "gamayng tanom", "liwanag"], "fact": {"tl": "Sa tropical rainforest, napakakapal ng magkakapatong na dahon sa itaas (canopy) kaya halos walang sikat ng araw na umaabot sa sahig ng gubat — madilim doon at kakaunti lang ang halamang tumutubo sa lupa.", "en": "In a tropical rainforest the layers of leaves at the top (the canopy) are so thick that almost no sunlight reaches the forest floor — it is dark down there and few plants grow on the ground.", "bis": "Sa tropical rainforest, baga kaayo ang nagsapaw nga dahon sa taas (canopy) maong halos walay kahayag sa adlaw nga makaabot sa salog sa lasang — ngitngit didto ug gamay ra ang tanom nga motubo sa yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rainforest-poor-soil-g7", "domain": "EARTH_SPACE", "topic": "rainforest soil is surprisingly poor", "grades": [6, 7, 8], "terms": ["rainforest", "kagubatan", "lupa", "yuta", "lupa nga dili tambok", "mahirap na lupa", "sustansya", "sustansiya", "nutrient", "mabilis nasisipsip", "dali masuyop", "ugat", "gamot", "nabubulok", "nadunot", "decomposition", "mababaw na ugat", "mabaw nga gamot", "mainit", "init", "mamasa", "umuulan"], "fact": {"tl": "Kahit napakayabong ng tropical rainforest, mahina ang lupa nito sa sustansya — dahil sa init at ulan, mabilis nabubulok ang mga dahon at agad nasisipsip ng mababaw na ugat ng mga puno bago pa lumubog sa lupa.", "en": "Even though a tropical rainforest looks lush, its soil is actually poor in nutrients — the heat and rain make leaves rot fast, and the trees' shallow roots grab the nutrients before they sink into the ground.", "bis": "Bisan tuod tambok kaayo og dagway ang tropical rainforest, ang yuta niini huyang sa sustansiya — tungod sa init ug ulan, dali madunot ang mga dahon ug dayon masuyop sa mabaw nga gamot sa mga kahoy una pa malubong sa yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "deserts-at-thirty-degrees-g8", "domain": "EARTH_SPACE", "topic": "why big deserts sit near 30 degrees latitude", "grades": [7, 8, 9], "terms": ["disyerto", "desyerto", "desert", "Sahara", "init na hangin", "init nga hangin", "bumababa", "mokunsad", "nakataas sa ekwador", "equator", "tuyong hangin", "uga nga hangin", "walang ulan", "walay ulan", "latitud", "30 degrees", "band", "strip", "bumabagsak na hangin", "nagmamamala"], "fact": {"tl": "Maraming malalaking disyerto (tulad ng Sahara) ay nasa parehong distansya mula sa ekwador — mga 30 digri — dahil doon bumababa ang dating mainit na hangin mula sa ekwador na natuyo na, kaya bihira ang ulan.", "en": "Many of the world's great deserts (like the Sahara) lie about the same distance from the equator — around 30 degrees — because there the hot air that rose over the equator sinks back down already dried out, so rain is rare.", "bis": "Daghang dagkong disyerto (sama sa Sahara) naa sa managsama nga gilay-on gikan sa ekwador — mga 30 ka degree — kay didto mokunsad ang init nga hangin nga misaka sa ekwador nga namala na, maong talagsa ra ang ulan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "desert-cold-nights-g6", "domain": "EARTH_SPACE", "topic": "deserts are freezing at night", "grades": [5, 6, 7], "terms": ["disyerto", "desert", "malamig sa gabi", "bugnaw sa gabii", "mainit sa araw", "init sa adlaw", "gabi", "gabii", "walang ulap", "walay panganod", "init nagpuntaw", "kumakawala ang init", "nawala ang kainit", "tuyong hangin", "uga", "temperatura", "hatinggabi", "tubo ang init", "nakatakas ang init"], "fact": {"tl": "Sa disyerto, sobrang init sa araw pero pwedeng sobrang lamig sa gabi — dahil walang ulap o halumigmig na maghuli ng init, mabilis itong tumatakas pataas sa langit pagkalubog ng araw.", "en": "A desert can be scorching by day yet freezing at night — with no clouds or moisture to trap the heat, the warmth quickly escapes up into the sky once the sun sets.", "bis": "Sa disyerto, hilabihan ka init sa adlaw apan mahimong hilabihan ka bugnaw sa gabii — kay walay panganod o kaumog nga modakop sa init, dali ra kining mokayab pataas sa langit kon mosalop na ang adlaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "sand-dunes-move-g5", "domain": "EARTH_SPACE", "topic": "sand dunes move with the wind", "grades": [4, 5, 6], "terms": ["buhangin", "balas", "sand dune", "tumpok ng buhangin", "tinapok nga balas", "gumagalaw", "molihok", "naglalakbay", "nagpanaw", "hangin", "hangin nagtulak", "gitulak sa hangin", "disyerto", "desert", "unti-unti", "hinay-hinay", "umuusad", "mibalhin"], "fact": {"tl": "Ang malalaking tumpok ng buhangin sa disyerto (sand dunes) ay dahan-dahang gumagalaw — itinutulak ng hangin ang mga butil ng buhangin paitaas sa isang gilid at pababa sa kabila, kaya parang naglalakbay ang buong buntong buhangin.", "en": "The big hills of sand in a desert (sand dunes) slowly move — the wind pushes grains up one side and they tumble down the other, so the whole dune seems to travel across the land.", "bis": "Ang dagkong tinapok nga balas sa disyerto (sand dunes) hinay-hinay nga molihok — gitulak sa hangin ang mga lugas sa balas pataas sa usa ka kilid ug mangahulog sa pikas, maong daw nagpanaw ang tibuok bungtod sa balas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tundra-permafrost-g7", "domain": "EARTH_SPACE", "topic": "frozen ground of the tundra", "grades": [6, 7, 8], "terms": ["tundra", "malamig na kapatagan", "bugnaw nga kapatagan", "permafrost", "laging yelo na lupa", "kanunay nagyelo nga yuta", "nakayelo", "nagyelo", "lupa", "yuta", "hindi natutunaw", "dili matunaw", "ugat", "gamot", "walang malalalim na puno", "walay tag-as nga kahoy", "mababang halaman", "mubo nga tanom", "lumot", "lumut"], "fact": {"tl": "Sa tundra na malapit sa mga polo, may patong ng lupa sa ilalim na laging nakayelo (permafrost) at hindi natutunaw kahit tag-init — kaya hindi makakaugat nang malalim ang mga puno, at mababang halaman lang at lumot ang tumutubo doon.", "en": "In the tundra near the poles, there is a layer of ground that stays frozen all year (permafrost) and does not melt even in summer — so trees cannot root deeply, and only low plants and mosses grow there.", "bis": "Sa tundra nga duol sa mga polo, adunay patong sa yuta sa ilawom nga kanunay nagyelo (permafrost) ug dili matunaw bisan ting-init — maong dili makagamot og lawom ang mga kahoy, ug mubo nga tanom ug lumut lamang ang motubo didto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "taiga-needle-leaves-g7", "domain": "EARTH_SPACE", "topic": "why northern forests have needle leaves", "grades": [6, 7, 8], "terms": ["taiga", "boreal forest", "gubat sa hilaga", "lasang sa amihanan", "pine", "pino", "karayom na dahon", "dagumon nga dahon", "needle leaves", "manipis", "nipis", "hindi nalalaglag", "dili mangahulog", "evergreen", "laging luntian", "kanunay lunhaw", "niyebe", "niyebe nagdahili", "snow", "malamig", "bugnaw", "nagtitipid ng tubig"], "fact": {"tl": "Sa malamig na gubat sa hilaga (taiga), karamihan ng puno ay may manipis na dahong tulad ng karayom na hindi nalalaglag sa taglamig — ang hugis na ito ay nagtitipid ng tubig at nagpapadulas ng niyebe pababa sa sanga.", "en": "In the cold northern forest (the taiga), most trees have thin, needle-shaped leaves that stay on through winter — this shape saves water and lets snow slide off the branches instead of breaking them.", "bis": "Sa bugnaw nga lasang sa amihanan (taiga), kadaghanan sa kahoy adunay nipis, dagumon nga dahon nga dili mangahulog sa tingtugnaw — kini nga porma magtipig og tubig ug magpadahili sa niyebe paubos sa sanga imbis nga mabali kini."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "tree-line-mountain-g6", "domain": "EARTH_SPACE", "topic": "why trees stop growing high on a mountain", "grades": [5, 6, 7], "terms": ["bundok", "bukid", "tree line", "hanggahan ng puno", "utlanan sa kahoy", "wala nang puno", "wala nay kahoy", "sobrang lamig", "sobra kabugnaw", "taas", "kataas", "itaas ng bundok", "tumoy sa bukid", "damo", "sagbot", "mababang halaman", "mubo nga tanom", "hindi na tumubo", "dili na motubo", "hangin"], "fact": {"tl": "Sa mataas na bundok, may taas kung saan tumitigil ang pagtubo ng puno (tree line) — sobrang lamig at hangin na sa itaas para mabuhay ang mga puno, kaya damo at mababang halaman na lang ang makikita pataas.", "en": "On a high mountain there is a height where trees stop growing (the tree line) — above it the cold and wind are too harsh for trees, so only grasses and low plants are found going up.", "bis": "Sa habog nga bukid, adunay gihabugon diin mohunong na ang pagtubo sa kahoy (tree line) — sobra na kabugnaw ug kakusog sa hangin sa ibabaw aron mabuhi ang mga kahoy, maong sagbot ug mubo nga tanom na lang ang makita paingon sa taas."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mountain-zones-like-poles-g8", "domain": "EARTH_SPACE", "topic": "climbing a mountain is like traveling to the poles", "grades": [7, 8, 9], "terms": ["bundok", "bukid", "pag-akyat", "pagsaka", "climbing", "biome", "zona", "sona", "klima", "klimang nagbabago", "klima nga mausab", "mainit sa baba", "init sa ubos", "malamig sa taas", "bugnaw sa taas", "parang naglalakbay", "daw nagapanaw", "polo", "poles", "ekwador", "gilay-on", "latitud", "altitude"], "fact": {"tl": "Habang umaakyat ka sa isang mataas na bundok, nagbabago ang halaman at klima mula tropikal sa baba hanggang malamig na tundra sa tuktok — para mo na ring naglakbay mula ekwador papunta sa polo, pero pataas lang.", "en": "As you climb a tall mountain, the plants and climate change from tropical at the bottom to cold tundra at the top — it is like traveling from the equator to the pole, but going straight up.", "bis": "Samtang mosaka ka sa habog nga bukid, ang tanom ug klima mausab gikan sa tropikal sa ubos ngadto sa bugnaw nga tundra sa tumoy — sama ra nga nagpanaw ka gikan sa ekwador paingon sa polo, apan pasaka lang."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rain-shadow-dry-side-g7", "domain": "EARTH_SPACE", "topic": "why one side of a mountain is dry", "grades": [6, 7, 8], "terms": ["bundok", "bukid", "rain shadow", "tuyong panig", "uga nga kilid", "basa ang isang gilid", "basa ang usa ka kilid", "ulan", "ulap", "panganod", "pataas", "umaakyat", "misaka", "lumalamig", "nabugnaw", "nauubos ang ulan", "nahurot ang ulan", "kabila", "pikas", "disyerto", "tuyo", "uga"], "fact": {"tl": "Kapag tinutulak ng hangin ang ulap pataas sa isang bundok, lumalamig ito at umuulan sa harap na gilid — pagdating sa kabilang gilid, ubos na ang basa, kaya tuyo at kung minsan disyerto pa ang likuran ng bundok (rain shadow).", "en": "When wind pushes clouds up over a mountain, they cool and dump their rain on the front side — by the time the air crosses to the other side it is squeezed dry, so the back of the mountain is dry and sometimes even desert (a rain shadow).", "bis": "Kon itulak sa hangin ang panganod pataas sa bukid, mobugnaw kini ug mo-ulan sa atubangang kilid — pag-abot sa pikas kilid, nahurot na ang kaumog, maong uga ug usahay disyerto pa ang luyo sa bukid (rain shadow)."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "savanna-fire-helps-g7", "domain": "LIVING_THINGS", "topic": "grass fires keep the savanna open", "grades": [6, 7, 8], "terms": ["savanna", "kasagbutan", "kasagbotan", "grassland", "damuhan", "sunog ng damo", "sunog sa sagbot", "grass fire", "apoy", "kalayo", "tumutubo muli", "mosubol pag-usab", "nagbabalik", "mibalik", "ugat sa ilalim", "gamot sa ilawom", "damo", "sagbot", "puno", "kahoy", "walang punong tumubo", "walay kahoy nga motubo", "Aprika", "Africa"], "fact": {"tl": "Sa savanna ng Africa, paminsan-minsang nasusunog ang tuyong damo, pero mabilis itong tumutubong muli mula sa ugat sa ilalim ng lupa — at ang mga sunog na ito ang pumipigil sa mga puno na takpan ang damuhan.", "en": "In the African savanna, the dry grass sometimes catches fire, but it quickly grows back from roots safe underground — and these fires are what keep trees from taking over the grassland.", "bis": "Sa savanna sa Africa, usahay masunog ang uga nga sagbot, apan dali ra kining mosubol pag-usab gikan sa gamot nga luwas sa ilawom sa yuta — ug kini nga mga sunog maoy magpugong sa mga kahoy nga molukop sa kasagbotan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "ph-megadiverse-country-g7", "domain": "LIVING_THINGS", "topic": "the Philippines is a megadiverse country", "grades": [6, 7, 8], "terms": ["Pilipinas", "Philippines", "megadiverse", "sobrang dami ng species", "sobra kadaghan og species", "biodiversity", "pagkakaiba-iba ng buhay", "kalainlain sa kinabuhi", "tropikal", "tropical", "isla", "pulo", "endemic", "tanging dito matatagpuan", "dinhi ra makita", "hayop", "mananap", "halaman", "tanom", "mainit", "init", "gubat"], "fact": {"tl": "Ang Pilipinas ay isa sa mga 'megadiverse' na bansa sa mundo — dahil tropikal at binubuo ng libu-libong isla, marami dito ang hayop at halaman na wala sa kahit saan pang lugar sa mundo.", "en": "The Philippines is one of the world's 'megadiverse' countries — because it is tropical and made of thousands of islands, it has many animals and plants found nowhere else on Earth.", "bis": "Ang Pilipinas usa sa mga 'megadiverse' nga nasod sa kalibutan — tungod kay tropikal ug gilangkoban sa liboan ka isla, daghan dinhi nga hayop ug tanom nga wala makita bisan asa pang dapit sa kalibutan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-tropics-no-cold-season-g6", "domain": "EARTH_SPACE", "topic": "why the tropics stay warm all year", "grades": [5, 6, 7], "terms": ["tropiko", "tropics", "tropikal", "tropical", "mainit buong taon", "init tibuok tuig", "ekwador", "equator", "sikat ng araw", "kahayag sa adlaw", "tuwid", "tul-id", "direkta", "direkta nga sanag", "hindi pahilig", "dili hapdos", "walang taglamig", "walay tingtugnaw", "Pilipinas", "Philippines", "banda", "band"], "fact": {"tl": "Ang mga lugar sa tropiko (kasama ang Pilipinas) ay mainit buong taon dahil malapit sila sa ekwador, kung saan halos tuwid na bumabagsak ang sikat ng araw sa buong taon — kaya walang taglamig doon.", "en": "Places in the tropics (including the Philippines) stay warm all year because they sit near the equator, where the sun's rays fall almost straight down the whole year — so there is no winter there.", "bis": "Ang mga dapit sa tropiko (apil ang Pilipinas) init tibuok tuig kay duol sila sa ekwador, diin halos tul-id nga mahulog ang kahayag sa adlaw sa tibuok tuig — maong walay tingtugnaw didto."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "poles-receive-slanted-light-g7", "domain": "EARTH_SPACE", "topic": "why ice stays at the poles", "grades": [6, 7, 8], "terms": ["polo", "poles", "Arctic", "Antarctica", "malamig", "bugnaw", "yelo", "niyebe", "sikat ng araw", "kahayag sa adlaw", "pahilig", "hapdos", "slanted", "kumakalat", "mikatag", "mahina ang init", "huyang ang init", "mababang anggulo", "ubos nga anggulo", "laging malamig", "kanunay bugnaw", "puting yelo", "sumasalamin", "gipasanag balik"], "fact": {"tl": "Sa magkabilang polo ng Earth, laging malamig dahil pahilig na tumama ang sikat ng araw at kumakalat sa malawak na lugar, kaya mahina ang init — at sinasalamin pa pabalik ng puting yelo ang karamihan ng liwanag.", "en": "Earth's two poles stay cold because sunlight strikes them at a slant and spreads thin over a wide area, so the warmth is weak — and the white ice reflects much of that light back away too.", "bis": "Ang duha ka polo sa Yuta kanunay bugnaw kay ang kahayag sa adlaw mohapdos nga maigo ug mokatag sa lapad nga dapit, maong huyang ang init — ug ang puti nga yelo magpasanag pa balik sa kadaghanan sa kahayag."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "antarctica-coldest-driest-g6", "domain": "EARTH_SPACE", "topic": "Antarctica is the coldest driest place", "grades": [5, 6, 7], "terms": ["Antarctica", "Antartika", "pinakamalamig", "pinakabugnaw", "coldest", "pinakatuyo", "pinakauga", "disyerto", "desert", "kaunti ang ulan", "gamay ang ulan", "niyebe", "niyebe", "yelo", "kontinente", "continent", "mababang temperatura", "ubos nga temperatura", "walang tao naninirahan", "walay tawo nagpuyo", "hangin"], "fact": {"tl": "Ang Antarctica ang pinakamalamig na lugar sa mundo, pero isa rin itong disyerto — bihirang umulan o magniyebe doon, at ang makapal na yelo ay tinipon sa paglipas ng libu-libong taon.", "en": "Antarctica is the coldest place on Earth, yet it is also a desert — it almost never rains or snows there, and its thick ice piled up over thousands of years.", "bis": "Ang Antarctica mao ang pinakabugnaw nga dapit sa kalibutan, apan disyerto usab kini — talagsa ra moulan o moniyebe didto, ug ang baga nga yelo natapok sulod sa liboan ka tuig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "polar-day-six-months-g8", "domain": "EARTH_SPACE", "topic": "six months of day and night at the poles", "grades": [7, 8, 9], "terms": ["polo", "poles", "Arctic", "Antarctica", "anim na buwan", "unom ka bulan", "araw", "adlaw", "gabi", "gabii", "walang lubog na araw", "walay salop nga adlaw", "walang sikat na araw", "walay sidlak nga adlaw", "kiling ng Earth", "kiling sa Yuta", "tilt", "matagal na dilim", "dugay nga ngitngit", "matagal na liwanag"], "fact": {"tl": "Sa pinakadulo ng mga polo, may panahong umaabot ng anim na buwan na araw na walang gabi, at anim na buwan na gabi na halos walang araw — bunga ito ng pagkakiling ng Earth sa kanyang paggalaw.", "en": "At the very ends of the poles there can be about six months of daylight with no night, then six months of night with almost no sun — this comes from the tilt of the Earth as it travels around the sun.", "bis": "Sa kinatumyan sa mga polo, adunay panahon nga moabot og unom ka bulan nga adlaw nga walay gabii, ug unom ka bulan nga gabii nga halos walay adlaw — bunga kini sa pagkiling sa Yuta samtang naglibot sa adlaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-blue-sea-warm-belts-g8", "domain": "EARTH_SPACE", "topic": "warm and cold ocean belts", "grades": [7, 8, 9], "terms": ["dagat", "dagat", "ocean", "mainit na dagat", "init nga dagat", "malamig na dagat", "bugnaw nga dagat", "ekwador", "equator", "polo", "poles", "temperatura ng tubig", "temperatura sa tubig", "mas mainit malapit ekwador", "mas init duol ekwador", "banda", "band", "klima", "layo sa ekwador"], "fact": {"tl": "Mas mainit ang tubig-dagat malapit sa ekwador at mas malamig palapit sa mga polo, kaya iba ang mga isda at buhay-dagat na matatagpuan sa bawat banda — mainit-tubig na coral sa tropiko, malamig-tubig na hayop malapit sa polo.", "en": "Sea water is warmer near the equator and colder toward the poles, so different fish and sea life live in each belt — warm-water corals in the tropics, cold-water animals near the poles.", "bis": "Mas init ang tubig-dagat duol sa ekwador ug mas bugnaw paingon sa mga polo, maong lain-lain nga isda ug kinabuhi sa dagat ang makit-an sa matag banda — init-tubig nga coral sa tropiko, bugnaw-tubig nga mananap duol sa polo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-philippines-tropical-location-g5", "domain": "EARTH_SPACE", "topic": "why the Philippines is tropical", "grades": [4, 5, 6], "terms": ["Pilipinas", "Philippines", "tropikal", "tropical", "malapit sa ekwador", "duol sa ekwador", "equator", "mainit", "init", "klima", "gitnang bahagi", "tunga-tunga", "banda", "band", "palaging mainit", "kanunay init", "walang taglamig", "walay tingtugnaw", "posisyon", "nahimutangan", "lokasyon"], "fact": {"tl": "Tropikal ang Pilipinas dahil nasa gitnang banda ito ng mundo, malapit sa ekwador kung saan pinakamatindi ang init ng araw — kaya mainit tayo buong taon at walang taglamig.", "en": "The Philippines is tropical because it sits in the middle belt of the world, near the equator where the sun's heat is strongest — so it is warm all year and has no winter.", "bis": "Tropikal ang Pilipinas kay naa kini sa tunga-tunga nga banda sa kalibutan, duol sa ekwador diin pinakakusog ang init sa adlaw — maong init kita tibuok tuig ug walay tingtugnaw."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "temperate-four-seasons-g6", "domain": "EARTH_SPACE", "topic": "why temperate places have four seasons", "grades": [5, 6, 7], "terms": ["temperate", "mahinahong klima", "kasarangan nga klima", "apat na panahon", "upat ka panahon", "four seasons", "tagsibol", "spring", "tag-init", "summer", "taglagas", "autumn", "fall", "taglamig", "winter", "tingtugnaw", "gitna ng ekwador at polo", "tunga sa ekwador ug polo", "kiling", "tilt"], "fact": {"tl": "Ang mga lugar sa temperate zone (sa pagitan ng tropiko at polo) ay may apat na panahon — tagsibol, tag-init, taglagas, at taglamig — dahil malaki ang pagbabago ng tindi ng sikat ng araw habang umiikot ang Earth sa buong taon.", "en": "Places in the temperate zone (between the tropics and the poles) have four seasons — spring, summer, autumn, and winter — because the strength of the sunlight changes a lot through the year as the Earth orbits.", "bis": "Ang mga dapit sa temperate zone (tunga sa tropiko ug polo) adunay upat ka panahon — tingpamulak, ting-init, tingdahon, ug tingtugnaw — kay dako ang pagbag-o sa kakusog sa kahayag sa adlaw sa tibuok tuig samtang nagtuyok ang Yuta."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "animals-bigger-in-cold-g7", "domain": "LIVING_THINGS", "topic": "why cold-climate animals are often bigger", "grades": [6, 7, 8], "terms": ["hayop", "mananap", "malamig na lugar", "bugnaw nga dapit", "cold climate", "mas malaki", "mas dako", "mainit na lugar", "init nga dapit", "mas maliit na tainga", "mas gamay nga dunggan", "init", "kainit", "nawawala ang init", "mawala ang init", "laki ng katawan", "gidak-on sa lawas", "polar bear", "oso", "balhibo"], "fact": {"tl": "Maraming hayop sa malamig na lugar ay mas malaki ang katawan at mas maliit ang mga tainga't buntot kaysa sa kamag-anak nila sa mainit na lugar — ang malaking katawan na may maliliit na tainga't buntot ay mas mabagal mawalan ng init.", "en": "Many animals in cold places have larger bodies and smaller ears and tails than their relatives in warm places — a big body with small ears and tails loses its heat more slowly.", "bis": "Daghang hayop sa bugnaw nga dapit adunay mas dako nga lawas ug mas gamay nga dunggan ug ikog kay sa ilang paryente sa init nga dapit — ang dako nga lawas nga adunay gagmayng dunggan ug ikog mas hinay mawad-an og init."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "desert-plants-store-water-g5", "domain": "LIVING_THINGS", "topic": "how desert plants survive without rain", "grades": [4, 5, 6], "terms": ["disyerto", "desert", "halaman", "tanom", "cactus", "tinik", "tunok", "dahon", "nag-iimbak ng tubig", "magtipig og tubig", "store water", "makapal na tangkay", "baga nga punoan", "mahabang ugat", "tag-as nga gamot", "matagal na walang ulan", "dugay walay ulan", "mabuhay", "mabuhi", "init", "uga"], "fact": {"tl": "Ang mga halaman sa disyerto ay may espesyal na paraan para mabuhay sa kakaunting tubig — ang cactus ay nag-iimbak ng tubig sa makapal nitong katawan, at ang mga tinik nito (sa halip na dahon) ay nagbabawas ng pagkawala ng tubig.", "en": "Desert plants have special ways to survive on little water — a cactus stores water in its thick body, and its spines (instead of leaves) cut down how much water it loses.", "bis": "Ang mga tanom sa disyerto adunay espesyal nga paagi aron mabuhi sa gamayng tubig — ang cactus magtipig og tubig sa baga niini nga lawas, ug ang mga tunok niini (imbis dahon) magkunhod sa pagkawala sa tubig."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "rainforest-belt-around-equator-g6", "domain": "EARTH_SPACE", "topic": "rainforests form a belt around the equator", "grades": [5, 6, 7], "terms": ["rainforest", "kagubatan", "kalasangan", "ekwador", "equator", "banda", "band", "palibot ng mundo", "palibot sa kalibutan", "Amazon", "Congo", "mainit at maulan", "init ug ulan", "pataas na hangin", "misaka nga hangin", "ulan araw-araw", "ulan kada adlaw", "tropikal", "tropical", "gubat", "lasang"], "fact": {"tl": "Ang malalaking tropical rainforest sa mundo (gaya ng Amazon) ay nasa isang banda sa palibot ng ekwador — doon, ang mainit na hangin ay tumataas, lumalamig, at halos araw-araw na umuulan, kaya laging mahalumigmig.", "en": "The world's great tropical rainforests (like the Amazon) lie in a belt around the equator — there the hot air rises, cools, and brings rain almost daily, keeping it always moist.", "bis": "Ang dagkong tropical rainforest sa kalibutan (sama sa Amazon) naa sa usa ka banda libot sa ekwador — didto, ang init nga hangin mosaka, mobugnaw, ug halos kada adlaw mo-ulan, maong kanunay umog."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "microclimate-shade-cooler-g5", "domain": "EARTH_SPACE", "topic": "tiny climates in small places", "grades": [4, 5, 6], "terms": ["microclimate", "maliit na klima", "gamayng klima", "lilim", "landong", "shade", "mas malamig", "mas bugnaw", "ilalim ng puno", "ilawom sa kahoy", "tabi ng ilog", "daplin sa suba", "mainit na semento", "init nga semento", "lungsod", "syudad", "iba-iba ang init", "lain-lain ang init", "maliit na lugar"], "fact": {"tl": "Kahit sa iisang bayan, magkakaiba ang init sa magkakalapit na lugar — mas malamig sa lilim ng puno o tabi ng ilog, mas mainit sa bukas na semento — tinatawag itong microclimate, isang maliit na 'klima' sa isang maliit na lugar.", "en": "Even within one town, nearby spots can feel different — cooler under a tree or by a river, hotter on open pavement — this is called a microclimate, a tiny 'climate' in a small place.", "bis": "Bisan sa usa ra ka lungsod, lahi ang init sa duol nga mga dapit — mas bugnaw sa landong sa kahoy o daplin sa suba, mas init sa bukas nga semento — gitawag kini og microclimate, usa ka gamayng 'klima' sa gamayng dapit."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "baguio-cooler-than-lowland-g4", "domain": "EARTH_SPACE", "topic": "why Baguio is cool though tropical", "grades": [3, 4, 5], "terms": ["Baguio", "mataas na lugar", "habog nga dapit", "bundok", "bukid", "mountain", "malamig", "bugnaw", "mas malamig kaysa Maynila", "mas bugnaw kay sa Manila", "tropikal", "tropical", "altitude", "taas", "kataas", "klima", "summer capital", "preskong hangin", "bugnaw nga hangin"], "fact": {"tl": "Tropikal ang Pilipinas pero malamig pa rin ang Baguio dahil mataas ito sa kabundukan — habang umaakyat ka, lumalamig ang hangin, kaya presko ang Baguio kahit mainit sa kapatagan tulad ng Maynila.", "en": "The Philippines is tropical, yet Baguio is still cool because it sits high in the mountains — the air gets colder as you go up, so Baguio is chilly even when the lowlands like Manila are hot.", "bis": "Tropikal ang Pilipinas apan bugnaw gihapon ang Baguio kay habog kini sa kabukiran — samtang mosaka ka, mobugnaw ang hangin, maong bugnaw ang Baguio bisan init sa kapatagan sama sa Manila."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "oasis-in-desert-g5", "domain": "EARTH_SPACE", "topic": "what an oasis is", "grades": [4, 5, 6], "terms": ["oasis", "disyerto", "desert", "tubig", "tubig", "spring", "bukal", "tuburan", "ilalim ng lupa", "ilawom sa yuta", "groundwater", "luntiang lugar", "lunhaw nga dapit", "halaman", "tanom", "puno", "kahoy", "mabuhay", "mabuhi", "gitna ng buhangin", "tunga sa balas"], "fact": {"tl": "Ang oasis ay isang luntiang lugar sa gitna ng disyerto kung saan umaabot sa ibabaw ang tubig mula sa ilalim ng lupa — doon nakakatubo ang mga halaman at nakakainom ang mga hayop at tao.", "en": "An oasis is a green spot in the middle of a desert where water from underground reaches the surface — there plants can grow and animals and people can drink.", "bis": "Ang oasis usa ka lunhaw nga dapit sa tunga sa disyerto diin ang tubig gikan sa ilawom sa yuta moabot sa ibabaw — didto makatubo ang mga tanom ug makainom ang mga hayop ug tawo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "mangrove-coastal-biome-g6", "domain": "LIVING_THINGS", "topic": "mangrove forests guard tropical coasts", "grades": [5, 6, 7], "terms": ["bakawan", "bakhaw", "mangrove", "baybayin", "baybayon", "coast", "maalat na tubig", "parat nga tubig", "saltwater", "ugat na nakausli", "gamot nga nagtuybo", "tropikal", "tropical", "tumutubo sa putik", "motubo sa lapok", "tahanan ng isda", "puy-anan sa isda", "pananggalang sa bagyo", "panalipod sa bagyo", "alon", "balod"], "fact": {"tl": "Ang bakawan (mangrove) ay espesyal na gubat sa baybayin ng tropikal na lugar — kayang mabuhay ng mga puno nito sa maalat na tubig, at ang masisikip nitong ugat ay tahanan ng mga isda at sanggalang ng baybayin laban sa alon at bagyo.", "en": "A mangrove is a special forest along tropical shores — its trees can live in salty water, and their tangled roots shelter young fish and protect the coast from waves and storms.", "bis": "Ang bakhaw (mangrove) usa ka espesyal nga lasang sa baybayon sa tropikal nga dapit — ang mga kahoy niini mabuhi sa parat nga tubig, ug ang nagkapuot niini nga gamot maoy puy-anan sa isda ug panalipod sa baybayon batok sa balod ug bagyo."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "snow-line-tropical-mountain-g7", "domain": "EARTH_SPACE", "topic": "snow on mountains even at the equator", "grades": [6, 7, 8], "terms": ["niyebe", "niyebe", "snow", "bundok", "bukid", "mountain", "ekwador", "equator", "tropikal", "tropical", "mataas", "habog", "tuktok", "tumoy", "laging malamig", "kanunay bugnaw", "Kilimanjaro", "Andes", "sobrang taas", "sobra kahabog", "yelo", "puting tuktok"], "fact": {"tl": "May mga bundok malapit sa ekwador na laging may niyebe o yelo sa tuktok — kahit mainit ang paligid, sobrang taas ng mga ito kaya laging malamig doon sa itaas, gaya ng Bundok Kilimanjaro sa Africa.", "en": "Some mountains near the equator have snow or ice on top all year — even though the land around is hot, they are so tall that it stays freezing up high, like Mount Kilimanjaro in Africa.", "bis": "Adunay mga bukid duol sa ekwador nga kanunay adunay niyebe o yelo sa tumoy — bisan init ang palibot, sobra ka habog kini maong kanunay bugnaw didto sa taas, sama sa Bukid Kilimanjaro sa Africa."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
  {"id": "why-equator-rains-deserts-dry-g8", "domain": "EARTH_SPACE", "topic": "a global pattern of wet and dry belts", "grades": [7, 8, 9], "terms": ["ekwador", "equator", "maulan", "ulanon", "wet", "disyerto", "desert", "tuyong banda", "uga nga banda", "pataas na hangin", "misaka nga hangin", "rising air", "bumababang hangin", "mokunsad nga hangin", "sinking air", "pabilog na hangin", "sirkulasyon", "patern", "banda ng klima", "banda sa klima", "ulap", "panganod"], "fact": {"tl": "May pandaigdigang patern ang ulan: pataas ang hangin sa ekwador kaya maulan doon, pero bumababa ang tuyong hangin mga 30 digri ang layo kaya disyerto naman doon — kaya magkasunod na banda ng maulan at tuyong lugar ang nakapalibot sa mundo.", "en": "There is a worldwide pattern to rain: air rises at the equator so it is rainy there, but dry air sinks back down about 30 degrees away making deserts — so wet and dry belts ring the planet in turn.", "bis": "Adunay tibuok-kalibutan nga sumbanan ang ulan: mosaka ang hangin sa ekwador maong ulanon didto, apan mokunsad ang uga nga hangin mga 30 ka degree ang gilay-on maong disyerto didto — maong nagsunod nga banda sa ulanon ug uga nga dapit ang naglibot sa kalibutan."}, "source": "encyclopedia-stable consensus", "generator": "claude-workflow", "reviewed": false},
];
